export type EmergencyCategory = 'mental_health' | 'cardiac' | 'general_urgent' | 'dental' | null;

export const ALL_DISEASES = Object.keys(DISEASE_RELATED_SPECIALTIES);

export const getDiseaseInfo = (slug: string) => {
  // 1. Try exact match from constants by looking at slugified keys
  let name = Object.keys(DISEASE_RELATED_SPECIALTIES).find(k => slugify(k) === slug);
  
  // 2. Fallback if not found: convert slug to readable title case (e.g. dolor-de-espalda -> Dolor De Espalda)
  if (!name) {
    name = slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  }

  const relatedSpecialties = DISEASE_RELATED_SPECIALTIES[name] || [];
  const primarySpecialty = relatedSpecialties.length > 0 ? relatedSpecialties[0] : null;

  // --- 3. DYNAMIC EMERGENCY INFERENCE ---
  const mentalHealthSpecs = ['Psicólogo', 'Psiquiatra', 'Psiquiatra infantil', 'Psicoanalista'];
  const cardiacSpecs = ['Cardiólogo', 'Cardiólogo pediátrico', 'Cirujano cardiovascular', 'Cirujano cardiovascular y torácico'];
  const urgentSpecs = ['Urgenciólogo', 'Traumatólogo', 'Neurocirujano'];
  const dentalSpecs = ['Dentista - Odontólogo', 'Odontólogo pediatra', 'Cirujano maxilofacial'];

  let emergencyCategory: EmergencyCategory = null;

  if (relatedSpecialties.some(s => mentalHealthSpecs.includes(s))) {
      emergencyCategory = 'mental_health';
  } else if (relatedSpecialties.some(s => cardiacSpecs.includes(s))) {
      emergencyCategory = 'cardiac';
  } else if (relatedSpecialties.some(s => urgentSpecs.includes(s))) {
      emergencyCategory = 'general_urgent';
  } else if (relatedSpecialties.some(s => dentalSpecs.includes(s))) {
      emergencyCategory = 'dental';
  }

  // Look up in DISEASE_INFORMATION using the slugified key or the name if keys match
  const infoKey = Object.keys(DISEASE_INFORMATION).find(k => slugify(k) === slug) || slug;
  const detailedInfo = DISEASE_INFORMATION[infoKey] || null;

  return {
    name,
    primarySpecialty,
    relatedSpecialties,
    detailedInfo,
    emergencyCategory
  };
};



export const DISEASE_INFORMATION: Record<string, any> = {
'Ansiedad' : { intro: "La ansiedad es una respuesta natural del cuerpo ante el estrés o situaciones percibidas como amenazantes. Sin embargo, cuando la ansiedad es persistente, intensa o interfiere con la vida diaria, puede convertirse en un trastorno que requiere atención médica y psicológica. En esta página encontrarás información clara y confiable sobre qué es la ansiedad, sus síntomas, causas, tipos y opciones de tratamiento.", whatIs: { title: "¿Qué es la Ansiedad?", text: "La ansiedad es un estado emocional caracterizado por preocupación excesiva, nerviosismo o miedo anticipatorio. A diferencia del estrés ocasional, la ansiedad clínica puede mantenerse durante semanas o meses y afectar el bienestar físico, mental y social de una persona." }, symptoms: { title: "Síntomas Comunes de la Ansiedad", intro: "Los síntomas pueden variar según la persona y el tipo de ansiedad, pero suelen incluir:", groups: [ { name: "Síntomas emocionales", items: ["Preocupación constante o pensamientos repetitivos", "Sensación de peligro inminente", "Dificultad para concentrarse", "Irritabilidad"] }, { name: "Síntomas físicos", items: ["Palpitaciones o taquicardia", "Sudoración excesiva", "Tensión muscular", "Dificultad para respirar", "Problemas gastrointestinales", "Trastornos del sueño"] } ], warning: "Si los síntomas son intensos, persistentes o empeoran, es importante buscar orientación médica." }, types: { title: "Tipos de Trastornos de Ansiedad", intro: "La ansiedad puede manifestarse de diferentes formas, entre ellas:", items: ["Trastorno de ansiedad generalizada (TAG)", "Trastorno de pánico", "Fobias específicas", "Ansiedad social", "Trastorno obsesivo-compulsivo (TOC)", "Trastorno de estrés postraumático (TEPT)"], note: "Cada tipo tiene características y tratamientos específicos." }, causes: { title: "Causas y Factores de Riesgo", intro: "La ansiedad suele ser el resultado de una combinación de factores:", items: ["Estrés prolongado", "Experiencias traumáticas", "Factores genéticos", "Desequilibrios químicos en el cerebro", "Problemas de salud física", "Consumo excesivo de cafeína, alcohol o drogas"] }, diagnosis: { title: "¿Cómo se Diagnostica la Ansiedad?", intro: "El diagnóstico generalmente lo realiza un profesional de la salud mediante:", items: ["Entrevista clínica", "Evaluación de síntomas", "Historial médico y emocional", "Descarte de otras condiciones médicas"], note: "No existen pruebas de laboratorio específicas para la ansiedad, pero pueden usarse estudios para descartar causas físicas." }, treatment: { title: "Tratamientos para la Ansiedad", intro: "El tratamiento depende del tipo y la gravedad, e incluye:", subsections: [ { title: "Opciones comunes", items: ["Psicoterapia (como terapia cognitivo-conductual)", "Medicación (cuando es indicada por un médico)", "Técnicas de relajación y manejo del estrés", "Cambios en el estilo de vida (ejercicio, sueño, alimentación)"] } ], note: "Muchas personas mejoran significativamente con el tratamiento adecuado y seguimiento profesional." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Se recomienda buscar ayuda cuando:", items: ["La ansiedad interfiere con el trabajo, estudios o relaciones", "Los síntomas duran varias semanas", "Hay ataques de pánico frecuentes", "Aparecen pensamientos negativos persistentes"] } },
'Depresión' : { intro: "La depresión es más que sentirse triste; es un trastorno del estado de ánimo que afecta cómo te sientes, piensas y manejas las actividades diarias. Puede provocar una variedad de problemas emocionales y físicos y disminuir la capacidad de una persona para funcionar en el trabajo y en casa.", whatIs: { title: "¿Qué es la Depresión?", text: "La depresión clínica es una condición médica grave que afecta negativamente los sentimientos y el comportamiento. Provoca sentimientos persistentes de tristeza y pérdida de interés en actividades que antes se disfrutaban." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas deben estar presentes la mayor parte del día, casi todos los días, durante al menos dos semanas:", groups: [ { name: "Emocionales", items: ["Sentimientos de tristeza, vacío o desesperanza", "Arrebatos de enojo o frustración", "Pérdida de interés en actividades habituales"] }, { name: "Físicos y Cognitivos", items: ["Alteraciones del sueño (insomnio o dormir demasiado)", "Cansancio y falta de energía", "Cambios en el apetito y peso", "Dificultad para pensar o concentrarse"] } ], warning: "La depresión severa puede llevar a pensamientos de autolesión o suicidio." }, types: { title: "Tipos de Depresión", intro: "Existen diferentes variantes del trastorno:", items: ["Trastorno depresivo mayor", "Trastorno depresivo persistente (Distimia)", "Depresión posparto", "Depresión estacional", "Depresión psicótica"], note: "El diagnóstico correcto es clave para el tratamiento." }, causes: { title: "Causas", intro: "Es una condición compleja causada por:", items: ["Bioquímica cerebral", "Genética", "Personalidad", "Factores ambientales y estrés", "Trauma infantil"] }, diagnosis: { title: "Diagnóstico", intro: "Se basa en:", items: ["Examen físico", "Análisis de laboratorio (para descartar tiroides, etc.)", "Evaluación psiquiátrica"], note: "Se utilizan criterios del DSM-5." }, treatment: { title: "Tratamiento", intro: "Generalmente incluye:", subsections: [ { title: "Métodos", items: ["Farmacoterapia (antidepresivos)", "Psicoterapia (TCC, interpersonal)", "Terapia electroconvulsiva (en casos graves)"] } ], note: "El tratamiento suele ser de larga duración." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca ayuda si:", items: ["Te sientes deprimido la mayor parte del tiempo", "Tus síntomas afectan tus relaciones o trabajo", "Tienes pensamientos suicidas"] } },
'Duelo' : { intro: "El duelo es la respuesta natural a la pérdida de alguien o algo importante. Aunque se asocia comúnmente con la muerte, también puede surgir tras una ruptura, pérdida de empleo o cambios drásticos de vida. Es un proceso personal y único.", whatIs: { title: "¿Qué es el Duelo?", text: "Es un proceso de adaptación emocional que sigue a cualquier pérdida. No es una enfermedad, sino una experiencia humana natural que conlleva diversas emociones intensas y cambiantes." }, symptoms: { title: "Manifestaciones del Duelo", intro: "El duelo afecta a la persona en varios niveles:", groups: [ { name: "Emocionales", items: ["Tristeza profunda", "Negación o incredulidad", "Ira y culpa", "Miedo y soledad"] }, { name: "Físicos", items: ["Fatiga y agotamiento", "Náuseas", "Baja inmunidad", "Dolores corporales", "Insomnio"] } ], warning: "Si el duelo impide vivir tras un año (duelo complicado), se requiere ayuda." }, types: { title: "Tipos de Duelo", intro: "Las formas de procesar la pérdida varían:", items: ["Duelo anticipado", "Duelo normal", "Duelo retardado", "Duelo crónico", "Duelo desautorizado (no reconocido socialmente)"], note: "No hay una forma 'correcta' de vivir el duelo." }, causes: { title: "Desencadenantes", intro: "Cualquier pérdida significativa:", items: ["Muerte de un ser querido", "Divorcio o ruptura", "Pérdida de salud", "Pérdida de empleo", "Aborto espontáneo"] }, diagnosis: { title: "Evaluación", intro: "Generalmente no se diagnostica como patología salvo que se vuelva crónico:", items: ["Evaluación clínica si los síntomas persisten excesivamente", "Diferenciación con la depresión mayor"], note: "El 'Trastorno de duelo prolongado' es un diagnóstico clínico." }, treatment: { title: "Manejo del Duelo", intro: "El apoyo es fundamental:", subsections: [ { title: "Estrategias", items: ["Grupos de apoyo", "Terapia de duelo", "Expresión artística o escritura", "Tiempo y paciencia"] } ], note: "El objetivo es integrar la pérdida, no 'superarla' u olvidarla." }, whenToSeekHelp: { title: "¿Cuándo buscar apoyo?", intro: "Es recomendable si:", items: ["Sientes que no puedes seguir adelante", "Te culpas excesivamente", "Deseas morir para estar con el fallecido", "Te aíslas socialmente por mucho tiempo"] } },
'Estrés' : { intro: "El estrés es la forma en que el cerebro y el cuerpo responden a una demanda. Cualquier tipo de desafío (como el rendimiento en el trabajo o un cambio importante en la vida) puede causar estrés. Si bien un poco de estrés es normal, el estrés crónico puede dañar la salud.", whatIs: { title: "¿Qué es el Estrés?", text: "Es una reacción fisiológica y psicológica de defensa. El cuerpo libera hormonas como el cortisol y la adrenalina para preparar al organismo para la acción ('lucha o huida')." }, symptoms: { title: "Signos de Estrés", intro: "El estrés afecta todo el cuerpo:", groups: [ { name: "Cognitivos y Emocionales", items: ["Problemas de memoria", "Incapacidad para concentrarse", "Pesimismo", "Ansiedad o agitación"] }, { name: "Físicos", items: ["Dolores de cabeza", "Malestar estomacal", "Tensión muscular", "Dolor en el pecho", "Fatiga", "Cambios en el deseo sexual"] } ], warning: "El estrés crónico puede causar problemas cardiovasculares graves." }, types: { title: "Tipos de Estrés", intro: "Se clasifica según su duración y causa:", items: ["Estrés agudo (corto plazo)", "Estrés agudo episódico", "Estrés crónico (largo plazo)"], note: "El estrés agudo puede ser emocionante, el crónico es agotador." }, causes: { title: "Estresores", intro: "Las causas son externas e internas:", items: ["Presión laboral o académica", "Problemas financieros", "Problemas de relación", "Cambios grandes en la vida", "Perfeccionismo"] }, diagnosis: { title: "Detección", intro: "No hay prueba única, se evalúa mediante:", items: ["Cuestionarios de nivel de estrés", "Examen físico para ver efectos (presión alta)", "Entrevista sobre estilo de vida"], note: "" }, treatment: { title: "Manejo del Estrés", intro: "Enfoques para reducir la tensión:", subsections: [ { title: "Técnicas", items: ["Ejercicio regular", "Técnicas de relajación (yoga, meditación)", "Gestión del tiempo", "Establecer límites", "Terapia psicológica"] } ], note: "Identificar los desencadenantes es el primer paso." }, whenToSeekHelp: { title: "¿Cuándo es demasiado?", intro: "Busca ayuda si:", items: ["Te sientes abrumado", "Usas drogas o alcohol para afrontarlo", "Tienes pensamientos de hacerte daño", "Afecta tu salud física"] } },
'Codependencia' : { intro: "La codependencia es un patrón de comportamiento en las relaciones donde una persona tiene una dependencia excesiva emocional o psicológica de su pareja, a menudo descuidando sus propias necesidades para cuidar a los demás. Suele ocurrir en relaciones con personas que tienen adicciones o problemas de salud mental.", whatIs: { title: "¿Qué es la Codependencia?", text: "Es una condición aprendida de comportamiento que afecta la capacidad de un individuo para tener una relación sana y mutuamente satisfactoria. También se conoce como 'adicción a las relaciones'." }, symptoms: { title: "Señales de Alerta", intro: "Las personas codependientes suelen presentar:", groups: [ { name: "Comportamiento", items: ["Dificultad para decir 'no'", "Necesidad compulsiva de controlar a otros", "Asumir responsabilidad por los problemas ajenos", "Miedo al abandono"] }, { name: "Sentimientos", items: ["Baja autoestima", "Necesidad de aprobación constante", "Sentimientos de culpa al cuidarse a sí mismo", "Ira reprimida"] } ], warning: "Puede llevar a relaciones abusivas o destructivas." }, types: { title: "Dinámicas", intro: "Se manifiesta en varios contextos:", items: ["Relación con adictos", "Relación con narcisistas", "Relaciones familiares disfuncionales"], note: "No es un diagnóstico clínico oficial en el DSM, pero es reconocido en psicología." }, causes: { title: "Origen", intro: "Suele originarse en la infancia:", items: ["Crianza en familias disfuncionales", "Padres con adicciones o enfermedades mentales", "Falta de validación emocional en la niñez"] }, diagnosis: { title: "Identificación", intro: "Se realiza a través de:", items: ["Evaluación psicológica", "Cuestionarios específicos (como el de Friel)", "Análisis de patrones de relación"], note: "" }, treatment: { title: "Recuperación", intro: "El foco está en el autocuidado:", subsections: [ { title: "Pasos", items: ["Psicoterapia individual o de grupo", "Grupos de apoyo (como CoDA)", "Aprender a establecer límites", "Reconstrucción de la autoestima"] } ], note: "Romper el ciclo requiere tiempo y consciencia." }, whenToSeekHelp: { title: "¿Cuándo buscar apoyo?", intro: "Es vital si:", items: ["Tu felicidad depende enteramente de otra persona", "Te quedas en relaciones dañinas por miedo a estar solo", "Sientes que has perdido tu identidad"] } },
'Hipertensión' : { intro: "La hipertensión arterial es una enfermedad crónica en la que la fuerza que ejerce la sangre contra las paredes de las arterias es lo suficientemente alta como para causar problemas de salud, como enfermedades cardíacas. A menudo se le llama el 'asesino silencioso' porque puede no presentar síntomas.", whatIs: { title: "¿Qué es la Hipertensión?", text: "Se define como una presión arterial sostenida por encima de 130/80 mmHg (según nuevas guías) o 140/90 mmHg. Cuanta más sangre bombee el corazón y más estrechas sean las arterias, mayor será la presión." }, symptoms: { title: "Síntomas", intro: "La mayoría no tiene síntomas, pero en casos extremos puede haber:", groups: [ { name: "Signos de emergencia", items: ["Dolor de cabeza intenso", "Fatiga o confusión", "Problemas de visión", "Dolor en el pecho", "Dificultad para respirar", "Latidos irregulares"] } ], warning: "No esperes a tener síntomas para medir tu presión." }, types: { title: "Tipos", intro: "Se clasifica en dos categorías principales:", items: ["Hipertensión primaria (esencial): Se desarrolla con los años sin causa identificable", "Hipertensión secundaria: Causada por otra condición (riñones, tiroides, medicamentos)"], note: "" }, causes: { title: "Factores de Riesgo", intro: "Múltiples factores influyen:", items: ["Edad y antecedentes familiares", "Sobrepeso u obesidad", "Falta de actividad física", "Consumo de tabaco y exceso de alcohol", "Dieta alta en sodio", "Estrés"] }, diagnosis: { title: "Diagnóstico", intro: "Es sencillo y rápido:", items: ["Medición con tensiómetro en varias consultas", "Monitoreo ambulatorio (MAPA)", "Análisis de sangre y orina"], note: "Una sola lectura alta no confirma el diagnóstico." }, treatment: { title: "Control y Tratamiento", intro: "El objetivo es bajar la presión:", subsections: [ { title: "Estrategias", items: ["Cambios en el estilo de vida (Dieta DASH, ejercicio)", "Reducción de sal", "Medicamentos antihipertensivos (diuréticos, bloqueadores beta, IECA)"] } ], note: "Es una condición de por vida que requiere control constante." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Debes ir si:", items: ["Tus lecturas en casa son consistentemente altas", "Tienes síntomas de crisis hipertensiva", "Tienes efectos secundarios de la medicación"] } },
'Caries' : { intro: "Las caries son zonas dañadas de forma permanente en la superficie dura de los dientes que se convierten en pequeñas aberturas o agujeros. Son uno de los problemas de salud más comunes en el mundo, causados por bacterias, ingesta de azúcar y limpieza deficiente.", whatIs: { title: "¿Qué son las Caries?", text: "Es la destrucción del tejido dental (esmalte y dentina) causada por los ácidos producidos por las bacterias de la placa dental al metabolizar los azúcares." }, symptoms: { title: "Signos", intro: "Los síntomas varían según el tamaño y ubicación:", groups: [ { name: "Progresión", items: ["Dolor de muelas repentino o sin causa aparente", "Sensibilidad dental", "Agujeros visibles en los dientes", "Manchas marrones, negras o blancas", "Dolor al morder"] } ], warning: "Si no se tratan, pueden causar infección severa y pérdida del diente." }, types: { title: "Tipos de Caries", intro: "Según su ubicación:", items: ["Caries de corona (superficie masticatoria)", "Caries interproximal (entre dientes)", "Caries de raíz (en encías retraídas)", "Caries recurrentes (bajo empastes viejos)"], note: "" }, causes: { title: "Causas", intro: "El proceso de deterioro incluye:", items: ["Formación de placa bacteriana", "Ataques de ácido tras comer azúcar/almidón", "Destrucción continua del esmalte", "Falta de flúor"] }, diagnosis: { title: "Detección", intro: "Realizada por el dentista:", items: ["Examen visual con espejo y sonda", "Radiografías dentales para ver caries ocultas"], note: "Las visitas regulares detectan caries antes de que duelan." }, treatment: { title: "Tratamientos", intro: "Depende de la gravedad:", subsections: [ { title: "Opciones", items: ["Tratamientos con flúor (etapa inicial)", "Empastes o restauraciones", "Coronas dentales", "Endodoncia (si llega al nervio)", "Extracción (daño irreparable)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo visitar al dentista?", intro: "Se recomienda:", items: ["Revisiones cada 6 meses", "Si sientes dolor o sensibilidad", "Si notas cambios en la apariencia de los dientes"] } },
'Estrés postraumático' : { intro: "El trastorno de estrés postraumático (TEPT) es una enfermedad de salud mental desencadenada por una situación aterradora, ya sea que se haya experimentado o presenciado. Los síntomas pueden incluir reviscencias, pesadillas y angustia grave.", whatIs: { title: "¿Qué es el TEPT?", text: "Es una reacción psicológica persistente tras un trauma. El cerebro no procesa el evento correctamente y el sistema de alerta se mantiene activo, causando que la persona se sienta en peligro constante." }, symptoms: { title: "Síntomas", intro: "Se agrupan en cuatro categorías y duran más de un mes:", groups: [ { name: "Intrusión y Evasión", items: ["Recuerdos recurrentes e involuntarios (flashbacks)", "Pesadillas", "Evitar lugares o personas que recuerden el trauma"] }, { name: "Cognición y Ánimo", items: ["Pensamientos negativos sobre uno mismo", "Desesperanza", "Problemas de memoria", "Estar siempre alerta o asustadizo"] } ], warning: "Puede surgir meses o años después del evento." }, types: { title: "Manifestaciones", intro: "Variaciones del trastorno:", items: ["TEPT agudo", "TEPT crónico", "TEPT de inicio tardío", "TEPT complejo (trauma repetido)"], note: "" }, causes: { title: "Factores", intro: "Desencadenantes comunes:", items: ["Guerra o combate", "Abuso físico o sexual", "Accidentes graves", "Desastres naturales", "Amenaza de muerte"] }, diagnosis: { title: "Diagnóstico", intro: "Evaluación clínica:", items: ["Examen físico para descartar otros problemas", "Evaluación psicológica detallada", "Criterios del DSM-5"], note: "" }, treatment: { title: "Terapias", intro: "El objetivo es recuperar el control:", subsections: [ { title: "Principal", items: ["Psicoterapia (Terapia de Exposición, EMDR)", "Medicación (Antidepresivos, ansiolíticos)"] } ], note: "El apoyo familiar es crucial." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es urgente si:", items: ["Los síntomas duran más de un mes", "Hay pensamientos suicidas", "Dificultad severa para funcionar en el día a día"] } },
'Trastorno de conducta' : { intro: "El trastorno de conducta es un grupo de problemas emocionales y de comportamiento que se presentan en niños y adolescentes. Se caracteriza por un patrón repetitivo y persistente de comportamiento en el que se violan los derechos básicos de otros o las normas sociales importantes.", whatIs: { title: "¿Qué es el Trastorno de Conducta?", text: "Es una alteración del comportamiento grave. No es solo 'portarse mal'; implica agresión hacia personas o animales, destrucción de propiedad, engaño o robo." }, symptoms: { title: "Signos Comunes", intro: "Los comportamientos se agrupan en:", groups: [ { name: "Agresión y Destrucción", items: ["Intimidar o amenazar", "Peleas físicas crueles", "Uso de armas", "Prender fuego deliberadamente", "Vandalismo"] }, { name: "Engaño y Violación de Normas", items: ["Mentir para obtener favores", "Robar (tiendas, casas)", "Huir de casa", "Faltar a la escuela frecuentemente"] } ], warning: "Suele asociarse con TDAH o problemas de aprendizaje." }, types: { title: "Inicio", intro: "Se clasifica según la edad de comienzo:", items: ["Inicio en la infancia (antes de los 10 años)", "Inicio en la adolescencia", "Inicio no especificado"], note: "El inicio temprano suele tener peor pronóstico." }, causes: { title: "Factores de Riesgo", intro: "Etiología multifactorial:", items: ["Daño cerebral o genética", "Trauma o abuso infantil", "Entorno familiar disfuncional", "Pobreza o entorno social violento"] }, diagnosis: { title: "Evaluación", intro: "Realizada por psiquiatras infantiles:", items: ["Entrevistas con padres y maestros", "Observación conductual", "Evaluación psicológica completa"], note: "" }, treatment: { title: "Intervención", intro: "Requiere enfoque multimodal:", subsections: [ { title: "Estrategias", items: ["Terapia familiar y entrenamiento para padres", "Terapia cognitivo-conductual para el niño", "Apoyo escolar", "Medicación (si hay comorbilidades)"] } ], note: "La intervención temprana es clave para evitar conductas antisociales adultas." }, whenToSeekHelp: { title: "¿Cuándo consultar?", intro: "Busque ayuda si:", items: ["El comportamiento es peligroso para el niño o la familia", "Hay problemas legales recurrentes", "El niño no muestra remordimiento"] } },
'Diabetes' : { intro: "La diabetes es una enfermedad crónica que afecta la forma en que el cuerpo convierte los alimentos en energía. Ocurre cuando el nivel de glucosa (azúcar) en la sangre es demasiado alto debido a que el cuerpo no produce suficiente insulina o no la usa adecuadamente.", whatIs: { title: "¿Qué es la Diabetes?", text: "Es un problema metabólico. La insulina es una hormona que ayuda a que la glucosa entre a las células para darles energía. Sin ella, el azúcar se acumula en la sangre causando daños." }, symptoms: { title: "Síntomas", intro: "Pueden ser sutiles al principio (especialmente Tipo 2):", groups: [ { name: "Clásicos (Las 3 P)", items: ["Poliuria (orinar mucho)", "Polidipsia (mucha sed)", "Polifagia (mucha hambre)"] }, { name: "Otros", items: ["Pérdida de peso inexplicable", "Visión borrosa", "Fatiga extrema", "Llagas que tardan en sanar", "Hormigueo en manos/pies"] } ], warning: "La cetoacidosis es una complicación aguda grave." }, types: { title: "Tipos Principales", intro: "Las formas más comunes son:", items: ["Diabetes Tipo 1 (autoinmune, el cuerpo no produce insulina)", "Diabetes Tipo 2 (resistencia a la insulina, relacionada con estilo de vida)", "Diabetes gestacional (durante el embarazo)", "Prediabetes"], note: "La Tipo 2 es la más común en adultos." }, causes: { title: "Causas", intro: "Varían según el tipo:", items: ["Tipo 1: Reacción inmunitaria desconocida", "Tipo 2: Sobrepeso, inactividad, genética, edad", "Gestacional: Cambios hormonales"] }, diagnosis: { title: "Pruebas", intro: "Se detecta con análisis de sangre:", items: ["Glucosa plasmática en ayunas", "Hemoglobina glicosilada (A1C)", "Prueba de tolerancia oral a la glucosa"], note: "" }, treatment: { title: "Control", intro: "El manejo es diario:", subsections: [ { title: "Pilares", items: ["Insulina (siempre en Tipo 1, a veces en Tipo 2)", "Medicamentos orales (metformina, etc.)", "Dieta saludable y control de carbohidratos", "Actividad física regular", "Monitoreo de glucosa"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Es necesario si:", items: ["Tienes síntomas de diabetes", "Tienes factores de riesgo (obesidad, antecedentes)", "Tus niveles de azúcar no bajan con tratamiento"] } },
'Dislipidemia' : { intro: "La dislipidemia es la alteración de los niveles de lípidos (grasas) en la sangre, lo que incluye colesterol, triglicéridos o ambos. Es uno de los principales factores de riesgo para desarrollar enfermedades cardiovasculares, como infartos y accidentes cerebrovasculares.", whatIs: { title: "¿Qué es la Dislipidemia?", text: "Implica tener niveles altos de colesterol 'malo' (LDL) o triglicéridos, o niveles bajos de colesterol 'bueno' (HDL). Las grasas pueden acumularse en las arterias formando placas (aterosclerosis)." }, symptoms: { title: "Síntomas", intro: "Generalmente es asintomática hasta que causa daño:", groups: [ { name: "Complicaciones visibles", items: ["No suele tener síntomas directos", "Xantomas (depósitos de grasa bajo la piel) en casos severos", "Dolor de pecho o infarto (consecuencia tardía)"] } ], warning: "Es una enfermedad silenciosa que requiere análisis para detectarse." }, types: { title: "Clasificación", intro: "Según su origen:", items: ["Primaria (Genética/Hereditaria)", "Secundaria (Estilo de vida, otras enfermedades)"], note: "" }, causes: { title: "Factores", intro: "Combinación de genética y hábitos:", items: ["Dieta alta en grasas saturadas/trans", "Sedentarismo", "Obesidad", "Diabetes no controlada", "Hipotiroidismo", "Tabaquismo"] }, diagnosis: { title: "Detección", intro: "Mediante perfil lipídico (análisis de sangre):", items: ["Medición de Colesterol Total", "Medición de LDL, HDL y Triglicéridos"], note: "Se recomienda ayuno antes de la prueba." }, treatment: { title: "Manejo", intro: "Reducir riesgo cardiovascular:", subsections: [ { title: "Estrategias", items: ["Cambios dietéticos (menos grasas animales, más fibra)", "Ejercicio aeróbico", "Estatinas y otros hipolipemiantes", "Control de peso"] } ], note: "El tratamiento suele ser de por vida." }, whenToSeekHelp: { title: "¿Cuándo chequearse?", intro: "Recomendaciones:", items: ["Adultos cada 4-6 años", "Más frecuente si hay factores de riesgo cardiovascular o antecedentes familiares"] } },
'Depresión en adolescentes' : { intro: "La depresión en adolescentes es un problema de salud mental grave que provoca un sentimiento de tristeza constante y una pérdida de interés en realizar diferentes actividades. Afecta la manera en que el adolescente piensa, se siente y se comporta, y puede provocar problemas emocionales, funcionales y físicos.", whatIs: { title: "¿Qué es la Depresión Adolescente?", text: "Aunque similar a la de adultos, en adolescentes puede manifestarse más como irritabilidad que como tristeza. Ocurre en una etapa de grandes cambios hormonales y sociales." }, symptoms: { title: "Síntomas Específicos", intro: "Pueden ser difíciles de diferenciar de la 'angustia adolescente' normal:", groups: [ { name: "Cambios de Actitud", items: ["Irritabilidad o ira excesiva", "Sensibilidad extrema a la crítica", "Retraimiento social (incluso de amigos)", "Bajo rendimiento escolar"] }, { name: "Físicos/Conductuales", items: ["Cansancio, falta de energía", "Autolesiones", "Uso de drogas/alcohol", "Descuidar la higiene"] } ], warning: "El riesgo de suicidio es una preocupación mayor en este grupo." }, types: { title: "Presentación", intro: "Varía en intensidad:", items: ["Trastorno depresivo mayor", "Distimia (crónica pero leve)", "Trastorno bipolar (fases de manía y depresión)"], note: "" }, causes: { title: "Factores", intro: "Interacción compleja:", items: ["Química cerebral", "Hormonas", "Trauma infantil", "Patrones de pensamiento negativo", "Presión social/escolar", "Acoso escolar (bullying)"] }, diagnosis: { title: "Evaluación", intro: "Realizada por un especialista:", items: ["Entrevista con el adolescente y padres", "Cuestionarios de depresión", "Evaluación de riesgo suicida"], note: "" }, treatment: { title: "Abordaje", intro: "Suele requerir combinación:", subsections: [ { title: "Opciones", items: ["Psicoterapia (TCC, interpersonal)", "Terapia familiar", "Antidepresivos (con precaución en menores)", "Programas de hospitalización (casos graves)"] } ], note: "La FDA advierte sobre el uso de antidepresivos en jóvenes." }, whenToSeekHelp: { title: "¿Cuándo actuar?", intro: "Los padres deben estar atentos si:", items: ["Los síntomas interfieren con la vida diaria", "Hay cambios drásticos en el comportamiento", "Expresiones de querer morir"] } },
'Bruxismo' : { intro: "El bruxismo es una afección en la que una persona rechina, cruje o aprieta los dientes. Puede ocurrir durante el día o, más comúnmente, durante la noche (bruxismo del sueño). Si no se trata, puede provocar dolor de mandíbula, dolores de cabeza y daños en los dientes.", whatIs: { title: "¿Qué es el Bruxismo?", text: "Es una actividad parafuncional (movimiento sin propósito útil) de los músculos de la masticación. A menudo es inconsciente." }, symptoms: { title: "Signos", intro: "A menudo detectado por un compañero de cama:", groups: [ { name: "Dentales y Musculares", items: ["Dientes aplanados, fracturados o flojos", "Esmalte dental desgastado", "Dolor o sensibilidad en la mandíbula", "Músculos de la mandíbula cansados o rígidos"] }, { name: "Otros", items: ["Dolor de oído (sin infección)", "Dolor de cabeza sordo en las sienes", "Alteraciones del sueño"] } ], warning: "Puede llevar a trastornos de la articulación temporomandibular (ATM)." }, types: { title: "Clasificación", intro: "Según el momento:", items: ["Bruxismo de vigilia (despierto, por estrés/concentración)", "Bruxismo del sueño (trastorno del movimiento relacionado con el sueño)"], note: "" }, causes: { title: "Factores", intro: "Causas multifactoriales:", items: ["Estrés y ansiedad", "Trastornos del sueño (apnea)", "Alineación anormal de los dientes (maloclusión)", "Reflujo ácido", "Tabaco, cafeína o alcohol"] }, diagnosis: { title: "Detección", intro: "En consulta dental:", items: ["Examen físico de dientes y mandíbula", "Reporte de síntomas", "Polisomnografía (en casos complejos de sueño)"], note: "" }, treatment: { title: "Manejo", intro: "Enfocado en proteger los dientes y reducir causas:", subsections: [ { title: "Tratamientos", items: ["Férulas o guardas oclusales (protector bucal)", "Corrección dental (ortodoncia)", "Manejo del estrés", "Relajantes musculares (corto plazo)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo consultar?", intro: "Visita al dentista si:", items: ["Tus dientes están desgastados o sensibles", "Tienes dolor en la mandíbula o cara", "Tu pareja oye ruidos de rechinar al dormir"] } },
'Síndrome metabólico' : { intro: "El síndrome metabólico no es una enfermedad única, sino un grupo de condiciones que ocurren juntas y aumentan el riesgo de sufrir enfermedades cardíacas, accidentes cerebrovasculares y diabetes tipo 2. Estas condiciones incluyen presión arterial alta, niveles altos de azúcar en sangre, exceso de grasa corporal alrededor de la cintura y niveles anormales de colesterol.", whatIs: { title: "¿Qué es el Síndrome Metabólico?", text: "También llamado síndrome X o de resistencia a la insulina. Se diagnostica cuando una persona presenta tres o más de los factores de riesgo específicos simultáneamente." }, symptoms: { title: "Signos Visibles", intro: "La mayoría de los componentes son asintomáticos, excepto:", groups: [ { name: "Indicadores", items: ["Obesidad central (cintura ancha: >102cm hombres, >88cm mujeres)", "Signos de resistencia a la insulina (acantosis nigricans)", "Síntomas de diabetes (sed, fatiga)"] } ], warning: "Tener uno de los componentes aumenta el riesgo de tener los otros." }, types: { title: "Componentes", intro: "Factores que lo componen:", items: ["Hipertensión", "Hiperglucemia", "Dislipidemia (Triglicéridos altos / HDL bajo)", "Obesidad abdominal"], note: "" }, causes: { title: "Riesgos", intro: "Estrechamente ligado a:", items: ["Sobrepeso y obesidad", "Inactividad física", "Resistencia a la insulina", "Edad (aumenta el riesgo al envejecer)", "Genética"] }, diagnosis: { title: "Criterios", intro: "Se confirma con examen físico y sangre si tienes 3 de 5:", items: ["Cintura grande", "Triglicéridos >150 mg/dl", "HDL bajo (<40 hombres, <50 mujeres)", "Presión >130/85", "Glucosa en ayunas >100 mg/dl"], note: "" }, treatment: { title: "Reversión", intro: "El objetivo es reducir el riesgo cardíaco:", subsections: [ { title: "Estilo de Vida", items: ["Pérdida de peso (incluso 7-10% ayuda)", "Dieta saludable para el corazón", "Dejar de fumar", "Ejercicio (30 min diarios)"] }, { title: "Médico", items: ["Medicamentos para presión, colesterol o insulina"] } ], note: "Es posible revertirlo con cambios agresivos en el estilo de vida." }, whenToSeekHelp: { title: "¿Cuándo chequearse?", intro: "Consulta si:", items: ["Tienes sobrepeso abdominal", "Tienes antecedentes familiares de diabetes o infartos", "Llevas una vida sedentaria"] } },
'Dolor de muelas' : { intro: "El dolor de muelas es un dolor en o alrededor de un diente que puede ser causado por diversos problemas dentales. Puede variar desde una molestia leve hasta un dolor punzante e insoportable. Generalmente es un síntoma de que algo no va bien en el diente o la encía.", whatIs: { title: "¿Qué es el Dolor de Muelas?", text: "Es la respuesta nerviosa a una irritación o infección en la pulpa dental (donde están los nervios) o el periodonto. El dolor puede ser constante, intermitente o desencadenado por estímulos (frío/calor)." }, symptoms: { title: "Manifestaciones", intro: "Síntomas acompañantes:", groups: [ { name: "Sensaciones", items: ["Dolor punzante, agudo o constante", "Sensibilidad térmica", "Dolor al masticar"] }, { name: "Signos Físicos", items: ["Hinchazón alrededor del diente", "Fiebre o dolor de cabeza", "Sabor desagradable (si hay infección)", "Mal aliento"] } ], warning: "Si hay fiebre e hinchazón, puede ser una infección grave que requiere atención inmediata." }, types: { title: "Orígenes", intro: "Tipos de dolor según causa:", items: ["Pulpitis (inflamación del nervio, reversible o irreversible)", "Periodontitis (dolor de encía y soporte)", "Dolor referido (sinusitis, oído)"], note: "" }, causes: { title: "Causas Comunes", intro: "Generalmente provocado por:", items: ["Caries dental avanzada", "Infección o absceso", "Diente fracturado", "Relleno dañado", "Bruxismo", "Erupción de muelas del juicio"] }, diagnosis: { title: "Evaluación", intro: "El dentista utiliza:", items: ["Historial del dolor", "Examen visual y percusión", "Radiografías", "Pruebas de vitalidad (frío/calor)"], note: "" }, treatment: { title: "Soluciones", intro: "Depende de la causa raíz:", subsections: [ { title: "Procedimientos", items: ["Empaste (si es caries)", "Endodoncia (si afecta el nervio)", "Extracción (si no es salvable)", "Antibióticos (si hay infección/fiebre)", "Limpieza profunda (problema de encías)"] } ], note: "Los remedios caseros solo alivian temporalmente, no curan." }, whenToSeekHelp: { title: "¿Cuándo es urgencia?", intro: "Ve al dentista ya si:", items: ["El dolor dura más de 1-2 días", "Es severo", "Tienes fiebre o dolor de oído", "Hay hinchazón en la cara"] } },
'Obesidad' : { intro: "La obesidad es una enfermedad compleja que consiste en tener una cantidad excesiva de grasa corporal. No es solo un problema estético; es un problema médico que aumenta el riesgo de otras enfermedades y problemas de salud, como enfermedades cardíacas, diabetes, presión arterial alta y ciertos tipos de cáncer.", whatIs: { title: "¿Qué es la Obesidad?", text: "Se define generalmente por el Índice de Masa Corporal (IMC). Un IMC de 30 o más se considera obesidad. Es el resultado de un desequilibrio calórico crónico donde se ingieren más calorías de las que se queman." }, symptoms: { title: "Signos", intro: "El signo principal es el exceso de tejido adiposo:", groups: [ { name: "Físicos", items: ["IMC >= 30", "Dificultad para respirar al hacer esfuerzo", "Sudoración excesiva", "Dolor en articulaciones (rodillas/espalda)", "Ronquidos o apnea del sueño"] }, { name: "Psicosociales", items: ["Baja autoestima", "Aislamiento social", "Depresión"] } ], warning: "La obesidad mórbida (IMC > 40) pone en riesgo vital inmediato." }, types: { title: "Clasificación", intro: "Según IMC (OMS):", items: ["Clase 1: IMC 30 a <35", "Clase 2: IMC 35 a <40", "Clase 3: IMC 40 o más (Grave/Mórbida)"], note: "También se clasifica por distribución de grasa (Androide/Manzana vs Ginoide/Pera)." }, causes: { title: "Factores", intro: "Interacción compleja:", items: ["Genética y metabolismo", "Estilo de vida (dieta, sedentarismo)", "Factores socioeconómicos", "Ciertas enfermedades (Cushing, hipotiroidismo)", "Medicamentos"] }, diagnosis: { title: "Evaluación", intro: "Más allá del peso:", items: ["Cálculo de IMC", "Medición de circunferencia de cintura", "Análisis de sangre (colesterol, glucosa, hígado)"], note: "" }, treatment: { title: "Manejo Integral", intro: "Requiere compromiso a largo plazo:", subsections: [ { title: "Opciones", items: ["Cambios dietéticos y ejercicio", "Terapia conductual", "Medicamentos recetados para adelgazar", "Cirugía bariátrica (en casos severos)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo consultar?", intro: "Busca apoyo si:", items: ["Te preocupa tu peso", "Tienes problemas de salud relacionados con el peso", "Has intentado adelgazar solo sin éxito"] } },
'Infección dental' : { intro: "Una infección dental, o absceso dental, es una acumulación de pus causada por una infección bacteriana. Puede ocurrir en diferentes regiones del diente por distintas razones y suele ser muy dolorosa. Si no se trata, la infección puede extenderse a otras partes del cuerpo.", whatIs: { title: "¿Qué es una Infección Dental?", text: "Es la invasión de bacterias en la pulpa dental o en las encías/hueso. El cuerpo reacciona enviando glóbulos blancos, lo que genera pus e inflamación." }, symptoms: { title: "Signos de Alarma", intro: "El síntoma principal es el dolor:", groups: [ { name: "Locales", items: ["Dolor intenso, persistente y punzante", "Sensibilidad extrema al calor/frío", "Hinchazón en la cara o mejilla", "Ganglios inflamados", "Bulto en la encía (fístula)"] }, { name: "Sistémicos", items: ["Fiebre", "Malestar general", "Dificultad para tragar o respirar"] } ], warning: "Una infección dental puede ser mortal si obstruye las vías respiratorias (Angina de Ludwig) o causa sepsis." }, types: { title: "Tipos de Absceso", intro: "Según ubicación:", items: ["Periapical (en la punta de la raíz, por caries)", "Periodontal (en las encías, por enfermedad periodontal)"], note: "" }, causes: { title: "Origen", intro: "Entrada de bacterias por:", items: ["Caries profunda no tratada", "Diente roto o astillado", "Enfermedad de las encías"] }, diagnosis: { title: "Evaluación", intro: "El dentista realizará:", items: ["Examen visual y palpación", "Radiografías para ver la extensión", "Pruebas de vitalidad"], note: "" }, treatment: { title: "Intervención", intro: "El objetivo es drenar la infección y salvar el diente:", subsections: [ { title: "Pasos", items: ["Drenaje del absceso", "Endodoncia (tratamiento de conducto)", "Antibióticos (para limitar la infección)", "Extracción (último recurso)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo es emergencia?", intro: "Ve a urgencias si:", items: ["Tienes fiebre alta e hinchazón facial", "Tienes dificultad para respirar o tragar", "El dolor es incontrolable"] } },
'Sobrepeso' : { intro: "El sobrepeso se refiere a un peso corporal superior al que se considera normal o saludable para una determinada estatura. Generalmente se debe a un aumento de grasa corporal y se considera un paso previo a la obesidad. Identificarlo a tiempo permite prevenir complicaciones mayores.", whatIs: { title: "¿Qué es el Sobrepeso?", text: "Se define comúnmente mediante el Índice de Masa Corporal (IMC). Un IMC entre 25.0 y 29.9 se clasifica como sobrepeso. Indica un exceso de peso en relación con la altura, aunque no distingue entre grasa y músculo." }, symptoms: { title: "Indicadores", intro: "A menudo no hay síntomas físicos directos, pero pueden aparecer:", groups: [ { name: "Señales", items: ["Aumento del perímetro abdominal", "Fatiga ligera al esfuerzo", "Ropa más ajustada", "Aumento de presión arterial o colesterol (en análisis)"] } ], warning: "Es el principal factor de riesgo modificable para evitar enfermedades crónicas." }, types: { title: "Medición", intro: "Se evalúa numéricamente:", items: ["IMC 25-29.9"], note: "En personas muy musculosas, el IMC puede indicar sobrepeso sin que haya exceso de grasa." }, causes: { title: "Factores", intro: "Desbalance energético:", items: ["Ingesta calórica mayor al gasto", "Sedentarismo", "Estrés y falta de sueño", "Factores ambientales y sociales", "Metabolismo lento (menos común)"] }, diagnosis: { title: "Detección", intro: "Métodos simples:", items: ["Cálculo del IMC", "Medición de cintura (>102cm hombres, >88cm mujeres indica riesgo)", "Bioimpedancia"], note: "" }, treatment: { title: "Corrección", intro: "Más fácil de revertir que la obesidad:", subsections: [ { title: "Estilo de Vida", items: ["Déficit calórico moderado", "Aumento de actividad física diaria", "Mejora de la calidad del sueño", "Hidratación adecuada"] } ], note: "Pequeños cambios sostenibles son más efectivos que dietas extremas." }, whenToSeekHelp: { title: "¿Cuándo actuar?", intro: "Es momento de cambiar si:", items: ["Tu IMC supera 25", "Tienes antecedentes familiares de diabetes", "Notas que tu peso aumenta gradualmente cada año"] } },
'Fracturas de dientes' : { intro: "Las fracturas de dientes ocurren cuando un diente se rompe o agrieta debido a un traumatismo, mordida dura o debilidad estructural. Pueden variar desde pequeñas astillas en el esmalte hasta roturas profundas que afectan el nervio.", whatIs: { title: "¿Qué son las Fracturas de Dientes?", text: "Es la pérdida de continuidad en la estructura dental. Dependiendo de la profundidad, puede afectar solo el esmalte, la dentina o llegar hasta la pulpa dental, provocando dolor y riesgo de infección." }, types: { title: "Tipos de Fracturas", intro: "Se clasifican según la estructura afectada:", items: ["Líneas de fisura (grietas superficiales)", "Fractura de cúspide (rotura de la superficie de masticación)", "Diente agrietado (grieta que llega hasta la raíz)", "Diente partido", "Fractura radicular vertical"], note: "El tratamiento depende del tipo y profundidad de la grieta." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El dentista evaluará el daño mediante:", items: ["Examen visual con lupa o microscopio dental", "Uso de un explorador dental para sentir la grieta", "Radiografías dentales", "Pruebas de mordida"], note: "A veces, las grietas finas no aparecen en las radiografías." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento busca proteger el diente y aliviar el dolor:", subsections: [ { title: "Procedimientos", items: ["Adhesión dental (resina para reparar)", "Coronas dentales", "Tratamiento de conducto (si el nervio está afectado)", "Extracción (si la grieta es muy profunda)"] } ], note: "La atención temprana puede salvar el diente." }, whenToSeekHelp: { title: "¿Cuándo acudir al dentista?", intro: "Es fundamental buscar ayuda si:", items: ["Sientes dolor agudo al morder", "Hay sensibilidad extrema al frío o calor", "El diente tiene bordes afilados", "El dolor es intermitente pero persistente"] } },
'Desgaste dental' : { intro: "El desgaste dental es la pérdida progresiva de la superficie de los dientes, lo que puede provocar sensibilidad, cambios estéticos y problemas de mordida. Ocurre de forma natural con la edad, pero ciertos hábitos o problemas de salud pueden acelerarlo.", whatIs: { title: "¿Qué es el Desgaste Dental?", text: "Es la erosión, atrición o abrasión del esmalte y, eventualmente, de la dentina subyacente. A diferencia de las caries, no es causado por bacterias, sino por factores mecánicos o químicos." }, types: { title: "Tipos de Desgaste", intro: "Se divide en tres categorías principales:", items: ["Atrición (desgaste por contacto diente con diente, como en el bruxismo)", "Abrasión (desgaste mecánico por cepillado agresivo u objetos externos)", "Erosión (desgaste químico por ácidos estomacales o dieta)"], note: "Es común presentar una combinación de estos tipos." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El odontólogo lo detecta mediante:", items: ["Examen clínico visual", "Comparación con modelos o fotografías previas", "Evaluación de los hábitos del paciente"], note: "Identificar el origen exacto es vital para detener el progreso." }, treatment: { title: "Opciones de Tratamiento", intro: "Depende de la gravedad del daño:", subsections: [ { title: "Soluciones", items: ["Uso de guardas oclusales (para el bruxismo)", "Mejoras en la técnica de cepillado", "Restauraciones con resina o carillas", "Coronas dentales en casos severos"] } ], note: "La prevención y el control de los factores desencadenantes son el primer paso." }, whenToSeekHelp: { title: "¿Cuándo acudir al dentista?", intro: "Se recomienda revisión si:", items: ["Sientes sensibilidad dental nueva o aumentada", "Notas los dientes más cortos o transparentes", "Tus empastes o restauraciones previas sobresalen"] } },
'Ataques de pánico' : { intro: "Los ataques de pánico son episodios repentinos de miedo o ansiedad intensa que desencadenan reacciones físicas graves cuando no existe un peligro real ni una causa aparente.", whatIs: { title: "¿Qué son los Ataques de Pánico?", text: "Son ráfagas súbitas de terror que suelen alcanzar su punto máximo en minutos. La persona puede sentir que está perdiendo el control, teniendo un infarto o incluso muriendo." }, types: { title: "Clasificación", intro: "Los ataques pueden ser:", items: ["Ataques esperados (desencadenados por un miedo conocido)", "Ataques inesperados (ocurren sin previo aviso)"], note: "Tener uno no significa tener un trastorno de pánico." }, diagnosis: { title: "Diagnóstico", intro: "El médico realizará:", items: ["Evaluación médica para descartar problemas cardíacos", "Examen psicológico y entrevista clínica", "Comparación con los criterios del DSM-5"], note: "Es fundamental descartar condiciones médicas que imitan los síntomas." }, treatment: { title: "Tratamientos", intro: "Las principales opciones son:", subsections: [ { title: "Enfoques", items: ["Psicoterapia (Terapia Cognitivo-Conductual)", "Medicamentos (antidepresivos, ansiolíticos)", "Técnicas de manejo de estrés y respiración"] } ], note: "El tratamiento puede reducir la intensidad y frecuencia de los ataques." }, whenToSeekHelp: { title: "¿Cuándo buscar atención?", intro: "Acude a un profesional si:", items: ["Tienes ataques repetidos", "Vives con miedo de tener otro ataque", "Evitas lugares por temor a sufrir un episodio"] } },
'Bullying (acoso escolar)' : { intro: "El bullying o acoso escolar es un comportamiento agresivo, intencional y repetitivo que ocurre entre estudiantes. Involucra un desequilibrio de poder real o percibido y puede tener graves consecuencias emocionales y físicas para la víctima.", whatIs: { title: "¿Qué es el Bullying?", text: "Es una forma de violencia que se manifiesta en el ámbito escolar, donde un estudiante o grupo acosa, intimida o agrede a otro de forma continua." }, types: { title: "Tipos de Acoso", intro: "Se manifiesta de diversas maneras:", items: ["Físico (golpear, empujar)", "Verbal (insultos, burlas, amenazas)", "Social o relacional (exclusión, rumores)", "Ciberbullying (acoso a través de medios digitales)"], note: "Las formas indirectas pueden ser igual de dañinas que las físicas." }, diagnosis: { title: "Evaluación y Detección", intro: "No es una enfermedad, pero requiere evaluación psicológica:", items: ["Entrevistas con el menor, padres y profesores", "Evaluación de cambios en el estado de ánimo o rendimiento", "Detección de posibles trastornos derivados (depresión, ansiedad)"], note: "La observación del comportamiento en casa y escuela es clave." }, treatment: { title: "Manejo e Intervención", intro: "Requiere un abordaje multidisciplinario:", subsections: [ { title: "Estrategias", items: ["Apoyo psicológico para la víctima", "Intervención con el acosador y sus familias", "Implementación de protocolos anti-acoso en la escuela", "Terapia familiar y grupos de apoyo"] } ], note: "La escuela y los padres deben trabajar en conjunto." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda?", intro: "Es urgente si:", items: ["El niño presenta miedo de ir a la escuela", "Hay lesiones inexplicables o pérdida de pertenencias", "Se observan cambios drásticos de humor o aislamiento", "El niño expresa pensamientos autodestructivos"] } },
'Pérdida de dientes' : { intro: "La pérdida de dientes, o edentulismo, es la ausencia de una o más piezas dentales. Afecta no solo la estética de la sonrisa, sino también la capacidad de masticar adecuadamente, la fonética y la estructura ósea de la mandíbula.", whatIs: { title: "¿Qué es la Pérdida de Dientes?", text: "Es el desprendimiento o extracción necesaria de piezas dentales, ya sea de forma parcial o total. Cuando falta un diente, los dientes vecinos pueden desplazarse y el hueso subyacente comienza a reabsorberse." }, types: { title: "Clasificación", intro: "Puede presentarse como:", items: ["Pérdida parcial (ausencia de uno o varios dientes)", "Pérdida total (ausencia de todos los dientes)", "Anodoncia (ausencia congénita de dientes)"], note: "" }, diagnosis: { title: "Evaluación Clínica", intro: "El diagnóstico es visual y radiográfico:", items: ["Examen bucal completo", "Radiografías panorámicas y periapicales", "Evaluación del soporte óseo restante"], note: "El dentista evaluará la salud de los dientes remanentes y las encías." }, treatment: { title: "Opciones de Reemplazo", intro: "Existen varias formas de restaurar la función y estética:", subsections: [ { title: "Tratamientos", items: ["Implantes dentales", "Prótesis fijas (puentes)", "Prótesis removibles (dentaduras parciales o totales)"] } ], note: "El tratamiento ideal depende de la salud ósea, presupuesto y necesidades del paciente." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista?", intro: "Es importante consultar cuando:", items: ["Se cae o se pierde un diente", "Sientes los dientes flojos o con movilidad", "Tienes dificultades crónicas para masticar"] } },
'Dientes desalineados' : { intro: "Los dientes desalineados o torcidos son una condición común en la que los dientes no se posicionan correctamente en el arco dental. Esto puede afectar la apariencia de la sonrisa, dificultar la limpieza y causar problemas de mordida.", whatIs: { title: "¿Qué son los Dientes Desalineados?", text: "Es una forma de maloclusión en la que los dientes presentan rotaciones, inclinaciones o se encuentran fuera de su posición ideal, afectando la armonía dental y funcional." }, types: { title: "Problemas Comunes", intro: "Las desalineaciones pueden incluir:", items: ["Mordida cruzada", "Mordida abierta", "Sobremordida", "Protrusión (dientes salidos)"], note: "Suele acompañarse de problemas de espacio como el apiñamiento o diastemas." }, diagnosis: { title: "Diagnóstico", intro: "Lo realiza el ortodoncista mediante:", items: ["Examen visual y toma de impresiones (moldes)", "Radiografías cefalométricas y panorámicas", "Fotografías clínicas intraorales y extraorales"], note: "El estudio de ortodoncia es esencial para trazar un plan de tratamiento." }, treatment: { title: "Corrección", intro: "Se utilizan fuerzas suaves y constantes para mover los dientes:", subsections: [ { title: "Aparatos", items: ["Brackets metálicos o estéticos", "Alineadores transparentes (ej. Invisalign)", "Aparatos removibles u ortopedia maxilar (en niños)"] } ], note: "El tiempo de tratamiento varía según la severidad del caso." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Considera una evaluación ortodóntica si:", items: ["Tienes dificultad para limpiar entre los dientes", "Te muerdes las mejillas o el paladar con frecuencia", "Estás inconforme con la estética de tu sonrisa"] } },
'Dientes apiñados' : { intro: "El apiñamiento dental ocurre cuando no hay suficiente espacio en la mandíbula o el maxilar para que todos los dientes encajen normalmente. Como resultado, los dientes se amontonan, se superponen o se tuercen.", whatIs: { title: "¿Qué son los Dientes Apiñados?", text: "Es un tipo específico de maloclusión caracterizada por la falta de espacio en la arcada dental, obligando a los dientes a salir desplazados de su eje o superpuestos." }, types: { title: "Grados de Apiñamiento", intro: "Se clasifica según su severidad:", items: ["Leve (ligera superposición de pocos dientes)", "Moderado", "Severo (múltiples dientes muy amontonados o fuera de la arcada)"], note: "El apiñamiento suele empeorar con la edad si no se trata." }, diagnosis: { title: "Evaluación", intro: "El dentista u ortodoncista evaluará:", items: ["El espacio disponible vs. el tamaño de los dientes", "Radiografías para ver la posición de las raíces y muelas del juicio", "Modelos de estudio"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es crear espacio y alinear:", subsections: [ { title: "Soluciones", items: ["Ortodoncia (brackets o alineadores invisibles)", "Desgaste interproximal (stripping) para ganar pequeños espacios", "Extracciones dentales (en casos severos de falta de espacio)", "Expansión del paladar (principalmente en niños)"] } ], note: "Una vez alineados, es crucial usar retenedores para evitar que se vuelvan a mover." }, whenToSeekHelp: { title: "¿Cuándo actuar?", intro: "Se sugiere consulta si:", items: ["No puedes pasar el hilo dental entre ciertos dientes", "Sufres de inflamación constante en las encías (gingivitis)", "Te preocupa el aspecto estético de tu boca"] } },
'Estrés laboral' : { intro: "El estrés laboral es la reacción física y emocional dañina que ocurre cuando las exigencias del trabajo no igualan las capacidades, recursos o necesidades del trabajador. A largo plazo, puede afectar gravemente la salud mental y física.", whatIs: { title: "¿Qué es el Estrés Laboral?", text: "Es un síndrome de agotamiento y tensión derivado del entorno de trabajo. Puede presentarse como 'Burnout' (síndrome del trabajador quemado) cuando el estrés crónico lleva al agotamiento físico, mental y emocional extremo." }, types: { title: "Manifestaciones", intro: "Se puede experimentar como:", items: ["Estrés agudo (episodios puntuales por fechas límite o proyectos)", "Estrés crónico (tensión constante y prolongada)", "Síndrome de Burnout (agotamiento total y despersonalización)"], note: "Afecta tanto a empleados como a líderes de organizaciones." }, diagnosis: { title: "Evaluación", intro: "Se identifica a través de:", items: ["Entrevistas clínicas o psicológicas", "Cuestionarios específicos (como el Maslach Burnout Inventory)", "Evaluación de riesgos psicosociales en el trabajo"], note: "" }, treatment: { title: "Manejo e Intervención", intro: "Requiere cambios a nivel personal y organizacional:", subsections: [ { title: "Estrategias", items: ["Terapia psicológica (apoyo emocional y estrategias de afrontamiento)", "Técnicas de relajación y mindfulness", "Mejora en la organización y límites del horario laboral", "En casos graves, incapacidad médica temporal"] } ], note: "Establecer límites claros entre el trabajo y la vida personal es fundamental." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda?", intro: "Es necesario actuar si:", items: ["Sientes una desmotivación extrema o cinismo hacia el trabajo", "El trabajo afecta tu sueño o tu salud física", "Tienes dolores de cabeza o tensión muscular diarios"] } },
'Angustia' : { intro: "La angustia es una emoción compleja caracterizada por un sentimiento de opresión, miedo intenso o sufrimiento psicológico. A diferencia del miedo, que tiene un objeto claro, la angustia suele ser una sensación difusa de que algo malo va a suceder.", whatIs: { title: "¿Qué es la Angustia?", text: "Es un estado afectivo de carácter penoso, que se acompaña de reacciones físicas (como opresión en el pecho) y una sensación de peligro inminente, paralizando en muchas ocasiones a la persona." }, types: { title: "Presentación", intro: "La angustia puede ser:", items: ["Angustia existencial o vital", "Angustia patológica (cuando es desproporcionada y paralizante)", "Crisis de angustia (ataques repentinos)"], note: "Es un síntoma central en muchos trastornos de ansiedad y depresión." }, diagnosis: { title: "Evaluación Psicológica", intro: "El profesional de salud mental explorará:", items: ["El contexto y duración de la sensación de angustia", "Síntomas físicos acompañantes", "Impacto en el funcionamiento social y laboral"], note: "Se busca diferenciar la angustia normal de la patológica." }, treatment: { title: "Abordaje", intro: "El tratamiento se enfoca en aliviar el sufrimiento:", subsections: [ { title: "Opciones", items: ["Psicoterapia (psicoanálisis, terapia cognitivo-conductual)", "Técnicas de relajación y meditación", "Fármacos ansiolíticos (bajo estricta supervisión médica)"] } ], note: "Hablar sobre los sentimientos es el primer paso para reducirlos." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Solicita apoyo profesional si:", items: ["La sensación de opresión te impide hacer tus tareas diarias", "Sientes que no tienes esperanza", "La angustia se acompaña de dolor físico inexplicable"] } },
'Enfermedad periodontal - piorrea' : { intro: "La enfermedad periodontal, comúnmente conocida como piorrea en su fase avanzada, es una infección grave de las encías que daña el tejido blando y destruye el hueso que sostiene los dientes, pudiendo provocar la pérdida dental.", whatIs: { title: "¿Qué es la Enfermedad Periodontal?", text: "Es un conjunto de enfermedades inflamatorias que afectan los tejidos de soporte de los dientes. Comienza como gingivitis (inflamación superficial) y, si no se trata, avanza a periodontitis, causando bolsas de infección y pérdida ósea." }, types: { title: "Etapas", intro: "La enfermedad progresa en fases:", items: ["Gingivitis (reversible, encías rojas y sangrantes)", "Periodontitis leve (daño inicial al hueso)", "Periodontitis moderada a severa (piorrea, gran pérdida ósea y movilidad dental)"], note: "La piorrea es la causa principal de pérdida de dientes en adultos." }, diagnosis: { title: "Detección", intro: "El periodoncista o dentista realizará:", items: ["Sondaje periodontal para medir la profundidad de las bolsas entre diente y encía", "Radiografías para evaluar el nivel del hueso", "Evaluación de sangrado y movilidad dental"], note: "Un sondaje mayor a 3 milímetros suele indicar problema." }, treatment: { title: "Tratamientos", intro: "El objetivo es limpiar exhaustivamente y detener la progresión:", subsections: [ { title: "Procedimientos", items: ["Limpieza profunda (raspado y alisado radicular)", "Antibióticos (tópicos u orales)", "Cirugía de colgajo (en casos severos para reducir las bolsas)", "Injertos de hueso o tejido blando"] } ], note: "El tratamiento requiere un compromiso estricto de higiene en casa." }, whenToSeekHelp: { title: "¿Cuándo ir al periodoncista?", intro: "Es urgente consultar si:", items: ["Tus encías sangran fácilmente al cepillarte", "Notas mal aliento persistente o mal sabor", "Ves pus entre los dientes y las encías", "Tus dientes se sienten flojos o se están separando"] } },
'Lesiones deportivas' : { intro: "Las lesiones deportivas son daños físicos que ocurren durante la práctica de un deporte o ejercicio físico. Pueden afectar huesos, músculos, tendones, ligamentos y otras estructuras, variando desde molestias leves hasta traumas graves.", whatIs: { title: "¿Qué son las Lesiones Deportivas?", text: "Son alteraciones en los tejidos del cuerpo producidas por estrés mecánico, sobreesfuerzo, mala técnica o accidentes traumáticos durante la actividad física." }, types: { title: "Tipos Comunes", intro: "Se dividen generalmente en:", items: ["Lesiones agudas (fracturas, esguinces, luxaciones, desgarros musculares)", "Lesiones crónicas o por sobreuso (tendinitis, fracturas por estrés, fascitis plantar)"], note: "El tipo de lesión suele estar directamente relacionado con el deporte practicado." }, diagnosis: { title: "Diagnóstico", intro: "El médico del deporte o traumatólogo utilizará:", items: ["Examen físico y pruebas de movilidad", "Radiografías (para descartar fracturas)", "Resonancia magnética o ultrasonido (para ver tejidos blandos)"], note: "" }, treatment: { title: "Recuperación", intro: "El enfoque inicial suele ser el método RICE (Reposo, Hielo, Compresión, Elevación):", subsections: [ { title: "Tratamientos", items: ["Inmovilización (férulas, yesos)", "Fisioterapia y rehabilitación", "Medicamentos antiinflamatorios", "Cirugía (para roturas completas de ligamentos o tendones)"] } ], note: "La rehabilitación adecuada es clave para prevenir recaídas." }, whenToSeekHelp: { title: "¿Cuándo ver a un médico?", intro: "Busca atención inmediata si:", items: ["Sientes un dolor intenso o incapacidad para mover una articulación", "Escuchaste un chasquido seguido de hinchazón rápida", "No puedes soportar peso en la pierna o brazo afectado"] } },
'Trastorno de ansiedad' : { intro: "Los trastornos de ansiedad son afecciones en las que la ansiedad no desaparece y puede empeorar con el tiempo. Los síntomas pueden interferir con las actividades diarias, como el desempeño en el trabajo, la escuela y las relaciones interpersonales.", whatIs: { title: "¿Qué es un Trastorno de Ansiedad?", text: "Es una condición de salud mental que va más allá del nerviosismo temporal. Implica un miedo o preocupación excesiva y persistente ante situaciones que no son realmente amenazantes." }, types: { title: "Variantes", intro: "Es un término paraguas que incluye:", items: ["Trastorno de ansiedad generalizada", "Trastorno de pánico", "Fobias específicas (ej. agorafobia, claustrofobia)", "Trastorno de ansiedad social", "Mutismo selectivo"], note: "Una persona puede padecer más de un tipo a la vez." }, diagnosis: { title: "Evaluación", intro: "Se diagnostica a través de:", items: ["Evaluación psicológica detallada", "Descarte de problemas médicos (como tiroides hiperactiva)", "Uso de criterios del manual diagnóstico DSM-5"], note: "" }, treatment: { title: "Tratamientos", intro: "Generalmente se maneja con una combinación de enfoques:", subsections: [ { title: "Opciones", items: ["Psicoterapia (especialmente cognitivo-conductual)", "Medicación (ISRS, ansiolíticos)", "Cambios en el estilo de vida y técnicas de relajación"] } ], note: "El tratamiento debe ser personalizado y supervisado por un especialista." }, whenToSeekHelp: { title: "¿Cuándo pedir apoyo?", intro: "Es necesario si:", items: ["Tus preocupaciones son difíciles de controlar", "Sientes que la ansiedad está afectando tu salud física", "Tienes pensamientos de hacerte daño"] } },
'Trastorno de ansiedad generalizada' : { intro: "El trastorno de ansiedad generalizada (TAG) se caracteriza por una preocupación y ansiedad exageradas, crónicas e irracionales frente a situaciones cotidianas. Quienes lo padecen anticipan siempre el desastre, preocupándose excesivamente por el dinero, la salud, la familia o el trabajo.", whatIs: { title: "¿Qué es el TAG?", text: "Es un estado constante de tensión mental y nerviosismo que dura al menos seis meses, sin que exista una causa clara que lo justifique, o siendo la reacción desproporcionada a la causa." }, types: { title: "Presentación", intro: "Se caracteriza por:", items: ["Curso crónico y fluctuante", "Frecuente asociación (comorbilidad) con la depresión u otros trastornos de ansiedad"], note: "Es uno de los trastornos de ansiedad más comunes en adultos." }, diagnosis: { title: "Criterios", intro: "El especialista busca:", items: ["Ansiedad presente la mayoría de los días durante al menos 6 meses", "Dificultad evidente para controlar la preocupación", "Presencia de síntomas somáticos acompañantes (tensión, fatiga)"], note: "" }, treatment: { title: "Manejo", intro: "El objetivo es reducir la ansiedad general:", subsections: [ { title: "Terapias", items: ["Terapia Cognitivo-Conductual (para identificar y cambiar patrones de pensamiento)", "Fármacos antidepresivos de primera línea (ISRS o ISRN)", "Ejercicios de relajación progresiva y respiración"] } ], note: "La recuperación lleva tiempo y constancia en la terapia." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Consulta si:", items: ["La preocupación te consume y afecta tu rutina diaria", "Tienes problemas graves para conciliar el sueño por darle vueltas a las cosas", "Sientes tensión muscular constante en cuello y espalda"] } },
'Gastritis' : { intro: "La gastritis es una inflamación del revestimiento del estómago (la mucosa gástrica). Puede presentarse de forma repentina (aguda) o desarrollarse lentamente con el tiempo (crónica). En muchos casos, la gastritis puede mejorar rápidamente con tratamiento.", whatIs: { title: "¿Qué es la Gastritis?", text: "Es la irritación o desgaste de la barrera mucosa que protege la pared del estómago de los jugos digestivos ácidos. Cuando esta barrera se debilita, los jugos dañan e inflaman el revestimiento." }, types: { title: "Tipos", intro: "Las clasificaciones principales son:", items: ["Gastritis aguda (inflamación súbita y severa)", "Gastritis crónica (inflamación sostenida a largo plazo)", "Gastritis erosiva (causa desgaste y úlceras en el estómago)"], note: "La infección por la bacteria Helicobacter pylori es una de las causas más frecuentes." }, diagnosis: { title: "Detección", intro: "El gastroenterólogo puede requerir:", items: ["Pruebas para detectar Helicobacter pylori (aliento, heces o sangre)", "Endoscopia superior (para ver el estómago directamente y tomar biopsia)", "Radiografía del aparato digestivo superior (tránsito de bario)"], note: "" }, treatment: { title: "Tratamiento", intro: "Depende de la causa específica:", subsections: [ { title: "Medicamentos y Cuidados", items: ["Antibióticos (si hay H. pylori)", "Medicamentos que bloquean la producción de ácido (IBP)", "Antiácidos para alivio rápido", "Dieta suave, evitando irritantes, picantes y alcohol"] } ], note: "Sin tratamiento, la gastritis puede conducir a úlceras o cáncer de estómago." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca atención médica si:", items: ["El dolor o malestar estomacal dura más de una semana", "Vomitas sangre o material que parece posos de café", "Tus heces son negras o con sangre"] } },
'Colon irritable' : { intro: "El síndrome de colon irritable (SCI) es un trastorno frecuente que afecta el intestino grueso. Se caracteriza por alteraciones en el ritmo intestinal y dolor abdominal, sin que exista una enfermedad o anomalía estructural subyacente demostrable.", whatIs: { title: "¿Qué es el Colon Irritable?", text: "Es un trastorno funcional gastrointestinal. Significa que el tracto digestivo parece normal, pero no funciona de manera adecuada, siendo más sensible y reaccionando de forma exagerada a estímulos como la comida, el estrés o las bacterias." }, types: { title: "Subtipos", intro: "Se clasifica según el síntoma predominante:", items: ["SCI-E (con predominio de estreñimiento)", "SCI-D (con predominio de diarrea)", "SCI-M (patrón mixto, alternando diarrea y estreñimiento)"], note: "Es una condición crónica que se maneja a largo plazo." }, diagnosis: { title: "Evaluación", intro: "Es un diagnóstico de exclusión (descartando otras enfermedades):", items: ["Historia clínica detallada y criterios de Roma", "Análisis de sangre y heces (para descartar celiaquía, infección o inflamación)", "Colonoscopia (generalmente en pacientes mayores o con síntomas de alarma)"], note: "" }, treatment: { title: "Manejo Integral", intro: "El tratamiento se enfoca en el control de síntomas:", subsections: [ { title: "Estrategias", items: ["Modificaciones en la dieta (dieta baja en FODMAPs, ajuste de fibra)", "Manejo del estrés y terapia psicológica", "Medicamentos (antiespasmódicos, laxantes, antidiarreicos o neuromoduladores)", "Probióticos"] } ], note: "La identificación de los alimentos desencadenantes es fundamental." }, whenToSeekHelp: { title: "¿Cuándo ir al doctor?", intro: "Consulta a un especialista si tienes:", items: ["Cambios persistentes en los hábitos intestinales", "Pérdida de peso inexplicable", "Sangrado rectal", "Dolor que no se alivia al ir al baño o que te despierta por la noche"] } },
'Virus del papiloma humano (VPH)' : { intro: "El Virus del Papiloma Humano (VPH) es la infección de transmisión sexual (ITS) más común. Existen más de 100 tipos de VPH; algunos causan verrugas, mientras que otros están relacionados con el desarrollo de ciertos tipos de cáncer, especialmente el de cuello uterino.", whatIs: { title: "¿Qué es el VPH?", text: "Es un grupo de virus que afectan la piel y las membranas mucosas. La mayoría de las infecciones por VPH desaparecen por sí solas sin causar problemas de salud, pero las infecciones persistentes por tipos de alto riesgo causan anomalías celulares." }, types: { title: "Clasificación de Riesgo", intro: "Los tipos de VPH genital se dividen en:", items: ["Bajo riesgo (tipos 6 y 11 principalmente, causan verrugas genitales)", "Alto riesgo (tipos 16 y 18 principalmente, asociados a cáncer cervicouterino, anal, orofaríngeo y de pene)"], note: "El VPH puede transmitirse incluso si la persona infectada no presenta signos visibles." }, diagnosis: { title: "Detección", intro: "Para las mujeres y la prevención del cáncer:", items: ["Prueba de Papanicolaou (detecta cambios celulares en el cuello uterino)", "Prueba de ADN del VPH (detecta los tipos de alto riesgo)", "Colposcopia (examen visual detallado si hay resultados anormales)"], note: "Actualmente no existe una prueba de VPH aprobada rutinaria para hombres." }, treatment: { title: "Manejo Clínico", intro: "No hay cura para el virus en sí, pero se tratan sus consecuencias:", subsections: [ { title: "Tratamientos", items: ["Eliminación de verrugas (tópicos, crioterapia, láser)", "Procedimientos para células precancerosas cervicales (crioterapia, LEEP, conización)", "Vigilancia activa en caso de infecciones leves"] } ], note: "La vacunación previa al inicio de la vida sexual previene la infección de los tipos más peligrosos." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista?", intro: "Es fundamental programar una visita si:", items: ["Aparecen bultos o verrugas en el área genital", "Toca realizar tu examen de Papanicolaou de rutina", "Tienes sangrado anormal o dolor durante las relaciones sexuales"] } },
'Diabetes gestacional' : { intro: "La diabetes gestacional es un tipo de diabetes que se desarrolla por primera vez durante el embarazo en mujeres que no padecían la enfermedad previamente. Se caracteriza por niveles altos de azúcar en la sangre que pueden afectar tanto a la madre como a la salud del bebé.", whatIs: { title: "¿Qué es la Diabetes Gestacional?", text: "Ocurre cuando las hormonas del embarazo interfieren con la capacidad del cuerpo para usar la insulina de manera efectiva (resistencia a la insulina), causando que la glucosa se acumule en la sangre en lugar de entrar a las células." }, types: { title: "Clasificación en el embarazo", intro: "Generalmente se identifica en dos formas de manejo:", items: ["Diabetes gestacional controlada con dieta y ejercicio", "Diabetes gestacional que requiere medicación o insulina"], note: "Suele desaparecer después del parto, pero aumenta el riesgo de diabetes tipo 2 a futuro." }, diagnosis: { title: "Pruebas de Detección", intro: "Se realiza rutinariamente entre las semanas 24 y 28 de gestación:", items: ["Prueba de tolerancia a la glucosa oral (test de O'Sullivan)", "Curva de tolerancia a la glucosa (si la prueba inicial sale alterada)"], note: "Se puede detectar antes si la madre tiene factores de riesgo altos." }, treatment: { title: "Control y Manejo", intro: "El objetivo es mantener los niveles de azúcar seguros para el bebé:", subsections: [ { title: "Estrategias", items: ["Monitoreo frecuente de los niveles de glucosa en sangre en casa", "Plan de alimentación específico diseñado por un nutricionista", "Ejercicio físico moderado y regular", "Inyecciones de insulina (si la dieta no es suficiente)"] } ], note: "Un buen control previene que el bebé crezca demasiado (macrosomía) y complique el parto." }, whenToSeekHelp: { title: "¿Cuándo contactar al médico?", intro: "Debes buscar atención si:", items: ["Tus niveles de glucosa en el monitoreo casero son consistentemente altos", "Sientes mareos, mucha sed o visión borrosa persistente", "Notas una disminución inusual en los movimientos del bebé"] } },
'Miomas uterinos' : { intro: "Los miomas uterinos, también conocidos como fibromas, son tumores no cancerosos (benignos) que crecen en la pared del útero. Son muy comunes en mujeres en edad fértil y, aunque muchas no tienen síntomas, en algunos casos pueden causar dolor y sangrado abundante.", whatIs: { title: "¿Qué son los Miomas?", text: "Son masas de tejido muscular y fibroso liso. Su crecimiento está asociado a las hormonas femeninas (estrógenos y progesterona) y pueden variar desde el tamaño de una semilla hasta masas que agrandan el útero significativamente." }, types: { title: "Clasificación por Ubicación", intro: "Según dónde crecen en el útero:", items: ["Intramurales (dentro de la pared muscular)", "Submucosos (protruyen hacia la cavidad uterina, causan más sangrado)", "Subserosos (crecen hacia el exterior del útero)", "Pediculados (unidos por un tallo estrecho)"], note: "" }, diagnosis: { title: "Detección", intro: "A menudo se descubren durante exámenes pélvicos de rutina:", items: ["Ecografía pélvica o transvaginal", "Resonancia magnética (RM) para un mapeo exacto", "Histeroscopia (para ver el interior del útero)"], note: "" }, treatment: { title: "Opciones Terapéuticas", intro: "El tratamiento depende de los síntomas, tamaño y el deseo de embarazo:", subsections: [ { title: "Abordajes", items: ["Conducta expectante (vigilancia si no hay síntomas)", "Medicamentos (anticonceptivos, análogos de GnRH para reducir el tamaño)", "Procedimientos no invasivos (ecografía focalizada)", "Cirugía (miomectomía para conservar el útero, o histerectomía)"] } ], note: "Si se acercan a la menopausia, los miomas suelen encogerse de forma natural." }, whenToSeekHelp: { title: "¿Cuándo ir al ginecólogo?", intro: "Programa una cita si experimentas:", items: ["Dolor pélvico persistente o dolor intenso repentino", "Períodos menstruales excesivamente abundantes o prolongados", "Sangrado entre períodos", "Dificultad para vaciar la vejiga"] } },
'Embarazo' : { intro: "El embarazo es el proceso biológico en el cual un embrión o feto se desarrolla dentro del útero de una mujer. Es un periodo de profundos cambios fisiológicos y emocionales que requiere control médico preventivo para asegurar la salud materno-fetal.", whatIs: { title: "¿Qué es el Embarazo?", text: "Es el estado que transcurre desde la implantación del óvulo fecundado en el útero hasta el momento del parto, abarcando habitualmente unas 40 semanas o 9 meses." }, types: { title: "Etapas", intro: "El embarazo se divide convencionalmente en:", items: ["Primer trimestre (hasta la semana 12: formación de órganos)", "Segundo trimestre (semana 13 a 28: crecimiento y desarrollo)", "Tercer trimestre (semana 29 al parto: maduración final y aumento de peso)"], note: "También se distingue entre embarazo único, múltiple y ectópico (fuera del útero, es una urgencia)." }, diagnosis: { title: "Confirmación", intro: "Se determina mediante:", items: ["Test de embarazo en orina (presencia de hormona hCG)", "Análisis de sangre cualitativo o cuantitativo de hCG", "Ecografía transvaginal o abdominal"], note: "La ecografía determina la viabilidad y semanas de gestación exactas." }, treatment: { title: "Cuidado y Seguimiento", intro: "Aunque no es una enfermedad, requiere un estricto 'Control Prenatal':", subsections: [ { title: "Medidas", items: ["Consultas médicas mensuales y luego quincenales/semanales", "Suplementación (ácido fólico, hierro, yodo)", "Ecografías de screening (semanas 12, 20 y 32)", "Pruebas analíticas para descartar infecciones, anemia o diabetes"] } ], note: "El seguimiento médico reduce drásticamente el riesgo de complicaciones." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias obstétricas?", intro: "Es motivo de revisión médica inmediata:", items: ["Sangrado vaginal o pérdida de líquido amniótico", "Dolor abdominal intenso y persistente", "Disminución notable de los movimientos fetales", "Fiebre alta o presión arterial elevada"] } },
'Trastornos de la personalidad' : { intro: "Los trastornos de la personalidad son un grupo de afecciones de salud mental en las que una persona tiene un patrón de pensamiento, desempeño y comportamiento marcado y poco saludable. Perciben y se relacionan con situaciones y personas de forma rígida, causando problemas y limitaciones importantes.", whatIs: { title: "¿Qué son?", text: "Son patrones de comportamiento inflexibles y prolongados que se desvían de las expectativas de la cultura del individuo, causando angustia o deterioro funcional, a menudo comenzando en la adolescencia o adultez temprana." }, types: { title: "Grupos (Clústeres)", intro: "Se dividen en tres grandes grupos:", items: ["Grupo A: Excéntricos o raros (ej. paranoide, esquizoide)", "Grupo B: Erráticos, dramáticos o emocionales (ej. límite/borderline, narcisista, antisocial)", "Grupo C: Ansiosos o temerosos (ej. evitativo, dependiente, obsesivo-compulsivo)"], note: "Cada trastorno tiene características específicas de relación e identidad." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Realizada por un psiquiatra o psicólogo clínico:", items: ["Entrevista psiquiátrica exhaustiva y detallada", "Evaluación de la historia clínica a largo plazo", "Cuestionarios o pruebas de personalidad estandarizadas"], note: "Las personas con estos trastornos a menudo no creen tener un problema." }, treatment: { title: "Abordaje Terapéutico", intro: "El tratamiento suele ser prolongado y un reto clínico:", subsections: [ { title: "Estrategias", items: ["Psicoterapia a largo plazo (Terapia Dialéctico-Conductual, TCC)", "Entrenamiento en habilidades sociales", "Medicamentos (solo para síntomas específicos como depresión, ansiedad o impulsividad)"] } ], note: "El objetivo es mejorar las relaciones y la capacidad de adaptación." }, whenToSeekHelp: { title: "¿Cuándo solicitar intervención?", intro: "Se debe buscar ayuda psiquiátrica si:", items: ["Los problemas de comportamiento destruyen relaciones personales o laborales", "Hay comportamientos impulsivos y peligrosos", "Existe riesgo o intentos de autolesión o suicidio"] } },
'Menopausia' : { intro: "La menopausia es la época de la vida de una mujer en la cual sus ovarios dejan de producir óvulos y cesan sus períodos menstruales. No es una enfermedad, sino una transición biológica natural, aunque puede acompañarse de síntomas físicos y emocionales molestos.", whatIs: { title: "¿Qué es la Menopausia?", text: "Se define oficialmente como el momento en que han transcurrido 12 meses consecutivos sin un período menstrual. Marca el final de los años reproductivos y se debe a la disminución de la producción de estrógeno y progesterona." }, types: { title: "Etapas", intro: "El proceso consta de varias fases:", items: ["Perimenopausia (años previos donde los ciclos se vuelven irregulares y comienzan los síntomas)", "Menopausia (el cese definitivo de la menstruación)", "Posmenopausia (la etapa de la vida posterior a la menopausia)", "Menopausia prematura (ocurre antes de los 40 años, a menudo por genética o cirugía)"], note: "" }, diagnosis: { title: "Detección", intro: "Generalmente se diagnostica por la edad y los síntomas:", items: ["Ausencia de regla por un año en mujeres de cierta edad", "Análisis de sangre para medir la hormona foliculoestimulante (FSH) y el estrógeno (si el diagnóstico es dudoso)"], note: "No se requieren pruebas de rutina para mujeres en el rango de edad típico (45-55 años)." }, treatment: { title: "Manejo de Síntomas", intro: "El tratamiento busca mejorar la calidad de vida de la mujer:", subsections: [ { title: "Opciones", items: ["Terapia de Reemplazo Hormonal (TRH) para sofocos severos y sequedad", "Lubricantes o estrógenos vaginales locales", "Antidepresivos o medicamentos específicos para sofocos", "Suplementos de calcio y vitamina D para proteger los huesos"] } ], note: "Las decisiones de tratamiento hormonal deben ser personalizadas con el ginecólogo." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable acudir si:", items: ["Tienes sofocos, insomnio o cambios de humor que interfieren con tu vida", "Sufres de sangrado vaginal después de la menopausia (es un signo de alerta)", "Experimentas dolor durante las relaciones sexuales"] } },
'Ciática' : { intro: "La ciática es un dolor que se irradia a lo largo del trayecto del nervio ciático, que se ramifica desde la parte inferior de la espalda, pasando por las caderas y los glúteos, y bajando por cada pierna. Por lo general, afecta a un solo lado del cuerpo.", whatIs: { title: "¿Qué es la Ciática?", text: "No es una enfermedad en sí, sino un síntoma de un problema médico subyacente. Ocurre cuando el nervio ciático se pellizca, se comprime o se irrita, causando inflamación, dolor y, a menudo, entumecimiento en la pierna." }, types: { title: "Presentación", intro: "El dolor ciático varía enormemente:", items: ["Agudo (aparición repentina, a menudo se resuelve en semanas)", "Crónico (dolor persistente que dura meses)"], note: "Puede variar desde un dolor sordo hasta una sensación ardiente, similar a una descarga eléctrica." }, diagnosis: { title: "Evaluación Médica", intro: "El médico identificará la causa de la compresión del nervio:", items: ["Examen físico completo (pruebas de fuerza muscular, reflejos y prueba de elevación de la pierna recta)", "Radiografías (para ver alteraciones óseas)", "Resonancia magnética o Tomografía (para ver hernias de disco u otras compresiones)"], note: "" }, treatment: { title: "Opciones de Tratamiento", intro: "La mayoría de los casos mejoran con medidas conservadoras:", subsections: [ { title: "Tratamientos", items: ["Medicación (AINEs, relajantes musculares, corticosteroides orales)", "Fisioterapia y ejercicios de estiramiento", "Inyecciones epidurales de esteroides (para inflamación severa)", "Cirugía (solo si hay debilidad grave, pérdida de control de esfínteres o dolor refractario)"] } ], note: "El reposo prolongado en cama generalmente no se recomienda." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia?", intro: "Busca atención médica inmediata si:", items: ["El dolor es repentino e intenso, acompañado de entumecimiento o debilidad muscular en la pierna", "Pierdes el control de la vejiga o los intestinos", "El dolor ocurre después de un accidente de tráfico u otro traumatismo violento"] } },
'Trastorno de hiperactividad y déficit de atención (TDAH)' : { intro: "El TDAH es un trastorno del neurodesarrollo de carácter crónico, frecuente en la infancia y que a menudo perdura hasta la edad adulta. Los niños con TDAH pueden tener problemas para prestar atención, controlar conductas impulsivas o ser excesivamente activos.", whatIs: { title: "¿Qué es el TDAH?", text: "Es una afección cerebral que afecta las funciones ejecutivas. Quienes lo padecen tienen diferencias en el desarrollo cerebral y en la actividad neurológica que afectan su capacidad de autocontrol y atención sostenida." }, types: { title: "Presentaciones", intro: "Se divide en tres subtipos o presentaciones predominantes:", items: ["Predominantemente inatento (dificultad para organizarse, se distrae fácilmente)", "Predominantemente hiperactivo-impulsivo (se mueve nerviosamente, habla mucho, no puede esperar su turno)", "Combinado (presenta síntomas de ambos en igual medida)"], note: "La presentación puede cambiar a medida que la persona envejece." }, diagnosis: { title: "Proceso Diagnóstico", intro: "No existe una única prueba; es un proceso que implica:", items: ["Evaluación clínica por un especialista (psiquiatra infantil, neurólogo o psicólogo)", "Cuestionarios y escalas de valoración completados por padres, maestros y el propio individuo", "Descarte de problemas de audición, visión o de aprendizaje similares"], note: "Los síntomas deben estar presentes antes de los 12 años y en más de un entorno (ej. casa y escuela)." }, treatment: { title: "Abordaje Terapéutico", intro: "Los mejores resultados se obtienen con un enfoque multimodal:", subsections: [ { title: "Estrategias", items: ["Terapia conductual (para el paciente y entrenamiento para los padres)", "Medicación (estimulantes como el metilfenidato, o no estimulantes)", "Acomodaciones e intervenciones escolares"] } ], note: "El tratamiento no cura el TDAH, pero controla los síntomas de forma muy eficaz." }, whenToSeekHelp: { title: "¿Cuándo solicitar evaluación?", intro: "Es recomendable consultar a un profesional si:", items: ["El niño tiene problemas constantes y graves en la escuela debido a falta de atención o comportamiento", "Las distracciones y la impulsividad afectan la seguridad del niño o sus relaciones sociales", "Un adulto siente que la falta de concentración le impide mantener un empleo o relaciones estables"] } },
'Depresión crónica' : { intro: "La depresión crónica, clínicamente conocida como Trastorno Depresivo Persistente (TDP) o Distimia, es un estado de ánimo deprimido continuo a largo plazo. Aunque los síntomas pueden no ser tan severos como los de la depresión mayor, su larga duración resulta agotadora y desgastante.", whatIs: { title: "¿Qué es la Depresión Crónica?", text: "Es un trastorno del estado de ánimo en el que una persona se siente triste, vacía o sin esperanza la mayor parte del día, la mayoría de los días, durante al menos dos años en adultos (o un año en niños y adolescentes)." }, types: { title: "Variantes Clínicas", intro: "El diagnóstico de TDP unifica dos condiciones previas:", items: ["Distimia pura (síntomas de baja intensidad de forma constante)", "Trastorno depresivo mayor crónico (episodio de depresión mayor que dura dos años o más)", "Depresión doble (tener distimia y, además, presentar episodios de depresión mayor)"], note: "" }, diagnosis: { title: "Diagnóstico Clínico", intro: "Se basa en la evaluación temporal de los síntomas:", items: ["Entrevista psiquiátrica y psicológica profunda", "Presencia de estado de ánimo deprimido por al menos dos años", "Presencia de síntomas como baja autoestima, fatiga, desesperanza o problemas de sueño"], note: "El médico también descartará condiciones médicas como el hipotiroidismo." }, treatment: { title: "Opciones de Manejo", intro: "El tratamiento a largo plazo es esencial y suele combinar:", subsections: [ { title: "Métodos", items: ["Psicoterapia (Terapia Cognitivo-Conductual, Terapia Interpersonal para cambiar hábitos de pensamiento)", "Fármacos antidepresivos (ISRS, IRSN, que pueden requerir ajustes a lo largo del tiempo)", "Cambios integrales en el estilo de vida"] } ], note: "Debido a su cronicidad, la paciencia y el seguimiento continuo son fundamentales." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista?", intro: "Es importante buscar ayuda psiquiátrica o psicológica si:", items: ["Te has sentido triste o apático de forma rutinaria por años, creyendo que 'así es tu personalidad'", "Los sentimientos de vacío interfieren significativamente con tu vida familiar o laboral", "Aparecen pensamientos de muerte o de no querer seguir viviendo"] } },
'Conducta agresiva' : { intro: "La conducta agresiva se refiere a comportamientos hostiles o destructivos que pueden causar daño físico o emocional a los demás, a los objetos o a uno mismo. Cuando es frecuente o incontrolable, suele ser un síntoma de un problema psicológico, neurológico o social subyacente.", whatIs: { title: "¿Qué es la Conducta Agresiva?", text: "Es cualquier acción intencional (física o verbal) que busca causar dolor o daño. En el contexto clínico, se analiza como una falta de control de impulsos, incapacidad para regular la ira o reacción a un malestar profundo." }, types: { title: "Tipos de Agresión", intro: "La agresión puede manifestarse de distintas formas:", items: ["Agresión impulsiva, reactiva o afectiva (surge de la ira extrema y ocurre sin planificación)", "Agresión instrumental o proactiva (un comportamiento premeditado y calculado para lograr un objetivo)", "Agresión verbal, física o relacional (dañar relaciones sociales)"], note: "Puede ser un síntoma de trastornos como TDAH, autismo, trastornos de conducta, o demencia en ancianos." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Para tratar la agresión, se debe encontrar la causa:", items: ["Evaluación psiquiátrica y psicológica completa", "Examen neurológico (para descartar lesiones cerebrales, tumores o demencia)", "Análisis del entorno familiar, social y escolar"], note: "No es un diagnóstico en sí mismo, sino un síntoma clínico." }, treatment: { title: "Intervenciones", intro: "El tratamiento se dirige a la causa subyacente y al manejo de la ira:", subsections: [ { title: "Estrategias", items: ["Psicoterapia (Terapia Cognitivo-Conductual para aprender a manejar la frustración)", "Entrenamiento en habilidades sociales y de comunicación", "Terapia familiar o intervenciones escolares", "Medicamentos (antipsicóticos, estabilizadores del ánimo o sedantes si hay un trastorno mental severo)"] } ], note: "La intervención temprana previene consecuencias legales o lesiones graves." }, whenToSeekHelp: { title: "¿Cuándo es urgente actuar?", intro: "Se requiere intervención inmediata si la persona:", items: ["Causa daño físico a familiares, compañeros, animales o destruye propiedades", "No puede calmarse después de un episodio y representa un peligro inminente", "La agresividad surge de forma nueva e inexplicable en un adulto (podría indicar problema neurológico)"] } },
'Embarazo de alto riesgo' : { intro: "Un embarazo de alto riesgo es aquel en el que existen condiciones de salud maternas, fetales o complicaciones gestacionales que aumentan la probabilidad de enfermedad o muerte para la madre o el bebé, requiriendo cuidados y monitoreo especializado y frecuente.", whatIs: { title: "¿Qué significa?", text: "Implica que, debido a factores médicos preexistentes, complicaciones surgidas durante la gestación o problemas en el desarrollo del feto, el embarazo requiere un nivel de vigilancia superior al de un embarazo normal o de bajo riesgo." }, types: { title: "Categorías de Riesgo", intro: "El riesgo puede originarse por diversas causas:", items: ["Riesgos maternos preexistentes (hipertensión, diabetes tipo 1 o 2, enfermedades autoinmunes)", "Complicaciones del embarazo (preeclampsia, placenta previa, diabetes gestacional)", "Riesgos fetales (embarazo múltiple, anomalías congénitas, restricción del crecimiento)"], note: "La edad materna (muy joven o mayor de 35 años) también se considera un factor." }, diagnosis: { title: "Detección y Control", intro: "Se identifica mediante un control prenatal exhaustivo:", items: ["Revisiones médicas tempranas para detectar factores de riesgo", "Ecografías de alta resolución y Doppler fetal", "Pruebas genéticas o amniocentesis si es necesario", "Monitoreo continuo de la presión arterial y laboratorios regulares"], note: "Suele requerir el seguimiento conjunto de un obstetra y un perinatólogo (especialista en medicina materno-fetal)." }, treatment: { title: "Manejo Médico", intro: "El objetivo es prevenir complicaciones y prolongar el embarazo de forma segura:", subsections: [ { title: "Medidas Terapéuticas", items: ["Ajuste de medicación para enfermedades preexistentes", "Reposo en cama o reducción de actividades", "Medicamentos específicos (ej. para maduración pulmonar fetal, para detener contracciones)", "Planificación de un parto inducido o cesárea programada"] } ], note: "El tratamiento es altamente personalizado según la causa del riesgo." }, whenToSeekHelp: { title: "¿Cuándo ir a urgencias obstétricas?", intro: "Una paciente de alto riesgo debe acudir inmediatamente si presenta:", items: ["Sangrado vaginal de cualquier cantidad", "Dolor pélvico persistente, calambres o contracciones frecuentes antes de término", "Dolor de cabeza severo con alteraciones visuales (ver moscas volantes o destellos)", "Disminución notable del movimiento del bebé"] } },
'Desnutrición' : { intro: "La desnutrición es un estado patológico causado por la falta de ingesta o asimilación de nutrientes, afectando gravemente el desarrollo, la inmunidad y las funciones vitales del cuerpo. Es un problema grave a nivel mundial, especialmente en niños y ancianos.", whatIs: { title: "¿Qué es la Desnutrición?", text: "Es una forma de malnutrición que ocurre cuando el cuerpo no recibe las calorías, proteínas, vitaminas y minerales necesarios para el mantenimiento de los tejidos y el funcionamiento adecuado de los órganos." }, types: { title: "Tipos Clínicos", intro: "Se clasifica por su severidad y presentación clínica:", items: ["Marasmo (desnutrición por déficit calórico total, severa delgadez)", "Kwashiorkor (desnutrición predominante de proteínas, produce inflamación/edema, especialmente en el abdomen)", "Desnutrición mixta", "Desnutrición crónica (causa retraso en el crecimiento y desarrollo en niños)"], note: "También puede ser causada por enfermedades que impiden la absorción de nutrientes, como la celiaquía." }, diagnosis: { title: "Evaluación Nutricional", intro: "El equipo médico determina el grado mediante:", items: ["Evaluación antropométrica (peso, talla, pliegues cutáneos, Índice de Masa Corporal)", "Análisis de sangre (proteínas séricas, albúmina, recuento de linfocitos, vitaminas)", "Evaluación de la ingesta dietética e historia clínica"], note: "Es vital buscar la causa (falta de alimentos vs. enfermedad subyacente)." }, treatment: { title: "Abordaje y Recuperación", intro: "La realimentación debe ser gradual y médicamente supervisada:", subsections: [ { title: "Fases del Tratamiento", items: ["Fase de estabilización (tratar infecciones, corregir deshidratación y desequilibrios electrolíticos mortales)", "Fase de rehabilitación (reintroducción progresiva de alimentos y fórmulas ricas en nutrientes)", "Tratamiento de la enfermedad de base (si la causa es mala absorción o anorexia)"] } ], note: "Una realimentación demasiado rápida puede causar un 'síndrome de realimentación' peligroso." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Se requiere atención médica urgente si hay:", items: ["Pérdida de peso drástica e involuntaria y debilidad extrema", "Edema (hinchazón) inusual en piernas o abdomen junto con delgadez general", "Apatía profunda, desmayos constantes o incapacidad para retener líquidos"] } },
'Endometriosis' : { intro: "La endometriosis es una enfermedad crónica, a menudo dolorosa, en la que un tejido similar al revestimiento interior del útero (endometrio) crece fuera de este. Afecta principalmente a los ovarios, las trompas de Falopio y el tejido que recubre la pelvis, causando inflamación y tejido cicatricial.", whatIs: { title: "¿Qué es la Endometriosis?", text: "Es un trastorno ginecológico donde las lesiones endometriales ectópicas responden a los cambios hormonales del ciclo menstrual, sangrando y causando inflamación, adherencias (bandas de tejido cicatricial) y dolor intenso, pudiendo afectar la fertilidad." }, types: { title: "Clasificación y Estadios", intro: "Se clasifica según su ubicación y severidad:", items: ["Endometriosis peritoneal superficial", "Endometriomas ováricos (quistes de chocolate)", "Endometriosis infiltrante profunda (nódulos que afectan intestino, vejiga u otros órganos)"], note: "La gravedad del dolor no siempre se correlaciona con la extensión de la enfermedad (estadios I al IV)." }, diagnosis: { title: "Confirmación Diagnóstica", intro: "El diagnóstico suele retrasarse; requiere:", items: ["Historia clínica y descripción del dolor", "Examen pélvico para palpar quistes o cicatrices", "Ecografía transvaginal o Resonancia Magnética (identifican quistes grandes o lesiones profundas)", "Laparoscopia (procedimiento quirúrgico para confirmación visual definitiva y biopsia)"], note: "La laparoscopia es el único método para un diagnóstico de certeza absoluta." }, treatment: { title: "Opciones de Tratamiento", intro: "No tiene cura, pero se pueden controlar los síntomas:", subsections: [ { title: "Manejo", items: ["Medicamentos para el dolor (AINEs)", "Terapia hormonal (anticonceptivos, análogos de GnRH) para frenar el crecimiento del tejido", "Cirugía conservadora (laparoscopia para extirpar lesiones y preservar o restaurar la fertilidad)", "Histerectomía (en casos muy graves que no responden a tratamiento)"] } ], note: "El tratamiento depende fuertemente de si la mujer desea quedar embarazada o no." }, whenToSeekHelp: { title: "¿Cuándo consultar al ginecólogo?", intro: "Debes buscar evaluación médica si presentas:", items: ["Dolor pélvico incapacitante durante la menstruación, la ovulación o las relaciones sexuales", "Dificultad o dolor extremo al ir al baño durante el periodo", "Problemas persistentes para lograr un embarazo"] } },
'Insuficiencia cardíaca' : { intro: "La insuficiencia cardíaca es una afección crónica y progresiva en la que el músculo del corazón no puede bombear suficiente sangre para satisfacer las necesidades de sangre y oxígeno del cuerpo. Básicamente, el corazón no puede seguir el ritmo de su carga de trabajo.", whatIs: { title: "¿Qué es la Insuficiencia Cardíaca?", text: "Es un síndrome clínico que resulta de daños al corazón, como arterias estrechadas (enfermedad coronaria), presión arterial alta crónica o infartos previos, que dejan el músculo cardíaco rígido o débil." }, types: { title: "Tipos Principales", intro: "Se clasifica según el lado afectado y la función de bombeo:", items: ["Insuficiencia cardíaca izquierda (la sangre se acumula en los pulmones causando dificultad para respirar)", "Insuficiencia cardíaca derecha (la sangre se acumula en el abdomen, piernas y pies causando hinchazón)", "Con fracción de eyección reducida (el corazón está débil y no se contrae bien)", "Con fracción de eyección preservada (el corazón está rígido y no se relaja/llena bien)"], note: "Con frecuencia, ambos lados del corazón fallan." }, diagnosis: { title: "Evaluación Médica", intro: "El cardiólogo utilizará varias pruebas para confirmar y clasificar el fallo:", items: ["Ecocardiograma (la prueba principal para ver el tamaño y funcionamiento del corazón)", "Electrocardiograma (ECG)", "Análisis de sangre (para medir el péptido natriurético tipo B o BNP)", "Prueba de esfuerzo y radiografía de tórax"], note: "" }, treatment: { title: "Manejo y Control", intro: "El objetivo es vivir más y mejor reduciendo la carga del corazón:", subsections: [ { title: "Tratamientos", items: ["Cambios estrictos en estilo de vida (restricción de sal y líquidos, control de peso diario)", "Medicamentos (diuréticos, bloqueadores beta, inhibidores de la ECA o ARNI)", "Dispositivos médicos (marcapasos biventricular o desfibrilador implantable)", "Cirugía (reparación de válvulas, bypass o, en última instancia, trasplante de corazón)"] } ], note: "Es una enfermedad crónica de por vida que requiere monitoreo estricto." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Llama a emergencias médicas si experimentas:", items: ["Dificultad repentina y grave para respirar, especialmente si toses moco rosado y espumoso", "Dolor en el pecho fuerte o persistente", "Desmayos o debilidad severa", "Hinchazón repentina y rápida en piernas o abdomen con aumento de peso rápido"] } },
'Amenaza de aborto' : { intro: "Una amenaza de aborto es un estado de alerta durante la primera mitad del embarazo (antes de las 20 semanas). Se caracteriza por sangrado vaginal, con o sin dolor pélvico, indicando que existe un riesgo de perder el embarazo, aunque el cuello uterino permanece cerrado.", whatIs: { title: "¿Qué es la Amenaza de Aborto?", text: "Es la presencia de síntomas que sugieren la posibilidad de un aborto espontáneo. A pesar del sangrado y los calambres, el feto sigue vivo y el embarazo puede continuar exitosamente en un porcentaje significativo de casos si se toman medidas." }, types: { title: "Evolución Posible", intro: "A partir de una amenaza, la situación puede derivar en:", items: ["Resolución de los síntomas (el embarazo continúa de forma normal)", "Aborto en evolución o inevitable (el sangrado empeora y el cuello uterino se abre)", "Aborto diferido o retenido (el embrión pierde viabilidad sin sangrado masivo)"], note: "Cerca de la mitad de las mujeres con amenaza de aborto terminan teniendo un embarazo saludable." }, diagnosis: { title: "Evaluación de Urgencia", intro: "Es fundamental realizar un diagnóstico rápido:", items: ["Ecografía transvaginal o pélvica (para confirmar los latidos del corazón del feto y el estado del saco gestacional)", "Examen pélvico (para verificar si el cuello uterino está dilatado o cerrado)", "Análisis de sangre para medir niveles de hCG (hormona del embarazo) y progesterona en días seriados"], note: "" }, treatment: { title: "Manejo Médico", intro: "No existe un tratamiento que garantice detener un aborto si es inevitable, pero se aplican medidas preventivas:", subsections: [ { title: "Recomendaciones Clínicas", items: ["Reposo relativo o absoluto (evitar esfuerzos físicos y cargar peso)", "Abstinencia sexual hasta que cese el sangrado", "Suplementación con progesterona (si el médico determina déficit hormonal)", "Administración de inmunoglobulina Rh (si la madre es Rh negativo)"] } ], note: "El apoyo emocional es crucial durante este periodo de incertidumbre." }, whenToSeekHelp: { title: "¿Cuándo acudir inmediatamente a urgencias?", intro: "Es indispensable la revisión médica si estás embarazada y presentas:", items: ["Cualquier tipo de sangrado vaginal, sin importar la cantidad", "Dolor pélvico intenso o calambres tipo cólico menstrual fuerte", "Expulsión de coágulos o tejido a través de la vagina"] } },
'Adicciones' : { intro: "Las adicciones son enfermedades crónicas y recurrentes del cerebro que se caracterizan por la búsqueda y el uso compulsivo de sustancias o comportamientos, a pesar de sus consecuencias nocivas.", whatIs: { title: "¿Qué son las Adicciones?", text: "Se trata de una dependencia física o psicológica hacia una sustancia (como drogas o alcohol) o una actividad (como el juego), que altera el funcionamiento normal del cerebro." }, types: { title: "Tipos de Adicciones", intro: "Se dividen principalmente en dos grupos:", items: ["Adicciones a sustancias (alcohol, drogas, medicamentos)", "Adicciones conductuales (ludopatía, uso de internet, compras compulsivas)"], note: "Ambas requieren atención profesional." }, diagnosis: { title: "Diagnóstico", intro: "Un profesional de la salud mental evaluará:", items: ["Patrones de consumo o comportamiento", "Impacto en la vida diaria y relaciones", "Criterios del DSM-5 para trastornos por uso de sustancias"], note: "El paciente a menudo niega tener un problema en las etapas iniciales." }, treatment: { title: "Tratamiento", intro: "El manejo suele ser multidisciplinario:", subsections: [ { title: "Opciones", items: ["Desintoxicación médica (si aplica)", "Terapia cognitivo-conductual", "Grupos de apoyo (ej. Alcohólicos Anónimos)", "Medicación para reducir la abstinencia o los antojos"] } ], note: "La recuperación es un proceso a largo plazo y las recaídas son posibles." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es crucial buscar apoyo si:", items: ["No puedes dejar de consumir o realizar la conducta", "Afecta tu salud, trabajo o familia", "Experimentas síntomas de abstinencia al intentar detenerte"] } },
'Apendicitis' : { intro: "La apendicitis es la inflamación del apéndice, una bolsa en forma de dedo que se proyecta desde el colon en el lado inferior derecho del abdomen. Es una emergencia médica que requiere cirugía inmediata.", whatIs: { title: "¿Qué es la Apendicitis?", text: "Es una condición aguda en la que el apéndice se bloquea, se inflama y se llena de pus. Si no se trata rápidamente, el apéndice puede romperse y causar una infección grave en la cavidad abdominal (peritonitis)." }, types: { title: "Tipos", intro: "La progresión clínica suele clasificarse en:", items: ["Apendicitis catarral o inicial", "Apendicitis flegmonosa", "Apendicitis gangrenosa", "Apendicitis perforada"], note: "El riesgo de ruptura aumenta significativamente después de 48 horas del inicio del dolor." }, diagnosis: { title: "Diagnóstico", intro: "El médico realizará:", items: ["Examen físico para evaluar el dolor en el abdomen", "Análisis de sangre (conteo de glóbulos blancos)", "Ecografía o Tomografía Computarizada (TC) abdominal"], note: "El dolor suele comenzar alrededor del ombligo y luego se desplaza al lado inferior derecho." }, treatment: { title: "Tratamiento", intro: "El tratamiento estándar es quirúrgico:", subsections: [ { title: "Procedimientos", items: ["Apendicectomía laparoscópica (cirugía mínimamente invasiva)", "Apendicectomía abierta (si el apéndice se ha roto)", "Antibióticos intravenosos"] } ], note: "La cirugía temprana previene complicaciones potencialmente mortales." }, whenToSeekHelp: { title: "¿Cuándo ir a urgencias?", intro: "Busca atención médica inmediata si tienes:", items: ["Dolor repentino y severo en el lado derecho del abdomen inferior", "Dolor que empeora al toser o caminar", "Fiebre, náuseas y vómitos junto con dolor abdominal"] } },
'Comportamiento suicida' : { intro: "El comportamiento suicida abarca desde tener pensamientos de quitarse la vida (ideación suicida) hasta la planificación y el intento de suicidio. Es una emergencia psiquiátrica que requiere intervención y apoyo inmediato.", whatIs: { title: "¿Qué es?", text: "Es una respuesta trágica a situaciones de vida estresantes o problemas de salud mental severos, donde la persona siente un dolor emocional intolerable y ve la muerte como la única salida." }, types: { title: "Clasificación", intro: "Incluye varias etapas o manifestaciones:", items: ["Ideación suicida pasiva (desear estar muerto)", "Ideación suicida activa (pensar en formas de hacerlo)", "Planificación suicida", "Intento de suicidio"], note: "Cualquier amenaza o comentario sobre el suicidio debe tomarse en serio." }, diagnosis: { title: "Evaluación de Riesgo", intro: "Un profesional de salud mental evaluará:", items: ["Severidad y frecuencia de los pensamientos", "Presencia de un plan específico y acceso a medios letales", "Historial de intentos previos y trastornos psiquiátricos"], note: "El objetivo es determinar el nivel de riesgo inminente." }, treatment: { title: "Intervención y Manejo", intro: "Se enfoca en la seguridad y el tratamiento del dolor subyacente:", subsections: [ { title: "Estrategias", items: ["Hospitalización psiquiátrica (para mantener a la persona segura)", "Psicoterapia intensa (como la Terapia Dialéctica Conductual)", "Medicación (antidepresivos, estabilizadores del ánimo, antipsicóticos)", "Creación de un plan de seguridad continuo"] } ], note: "El apoyo continuo de familiares y amigos es un factor protector clave." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Llama a emergencias o a una línea de prevención si:", items: ["Tú o un ser querido hablan activamente de querer morir", "Hay una búsqueda de métodos para hacerse daño", "Se observa una despedida inusual o el regalo de posesiones preciadas"] } },
'Síndrome de pinzamiento del hombro' : { intro: "El síndrome de pinzamiento del hombro ocurre cuando los tendones del manguito de los rotadores se pellizcan o comprimen al pasar por el estrecho espacio debajo del acromion. Es una causa muy común de dolor de hombro.", whatIs: { title: "¿Qué es el Pinzamiento del Hombro?", text: "Es la irritación mecánica de los tendones y la bursa en el hombro al levantar el brazo. Esto causa inflamación, dolor y limitación en el movimiento de la articulación." }, types: { title: "Etapas", intro: "Suele progresar en fases:", items: ["Estadio 1: Edema e inflamación (común en jóvenes)", "Estadio 2: Fibrosis y tendinitis (común en edad media)", "Estadio 3: Desgarros tendinosos o alteraciones óseas"], note: "Suele agravarse con actividades repetitivas por encima de la cabeza." }, diagnosis: { title: "Diagnóstico", intro: "El médico especialista evaluará:", items: ["Historial de dolor y examen físico con pruebas de movilidad (signos de Neer y Hawkins)", "Radiografías (para ver si hay espolones óseos)", "Resonancia Magnética (para evaluar el daño en tendones o bursa)"], note: "" }, treatment: { title: "Opciones Terapéuticas", intro: "El manejo suele ser conservador inicialmente:", subsections: [ { title: "Tratamientos", items: ["Reposo y evitar movimientos por encima de la cabeza", "Fisioterapia para fortalecer y estabilizar el hombro", "Medicamentos antiinflamatorios (AINEs) e infiltraciones de corticosteroides", "Cirugía artroscópica (descompresión subacromial) si no hay mejora"] } ], note: "La rehabilitación con ejercicios es la base del éxito a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo consultar al traumatólogo?", intro: "Es recomendable acudir si:", items: ["Sientes dolor al levantar el brazo o alcanzar algo detrás de la espalda", "El dolor interrumpe tu sueño, especialmente al acostarte sobre ese lado", "Sientes debilidad progresiva en el hombro"] } },
'Faringitis' : { intro: "La faringitis es la inflamación de la faringe, la parte posterior de la garganta. Es la causa principal del dolor de garganta y suele ser provocada por infecciones virales o bacterianas.", whatIs: { title: "¿Qué es la Faringitis?", text: "Consiste en la irritación e inflamación de los tejidos de la garganta, lo que provoca molestias, dolor y dificultad para tragar. Es muy común, especialmente durante los meses más fríos." }, types: { title: "Clasificación", intro: "Se divide principalmente por su origen:", items: ["Faringitis viral (la más común, asociada a resfriados o gripe)", "Faringitis bacteriana (como la infección por estreptococo, requiere antibióticos)", "Faringitis no infecciosa (por alergias, reflujo o irritantes)"], note: "La faringitis estreptocócica es más común en niños." }, diagnosis: { title: "Evaluación Médica", intro: "El médico puede realizar:", items: ["Examen visual de la garganta, amígdalas y ganglios del cuello", "Prueba rápida de estreptococo (frotis faríngeo)", "Cultivo de garganta (si la prueba rápida es negativa pero hay sospecha)"], note: "Es crucial diferenciar entre origen viral y bacteriano." }, treatment: { title: "Manejo", intro: "Dependerá de la causa exacta:", subsections: [ { title: "Recomendaciones", items: ["Antibióticos (solo si la causa es bacteriana confirmada)", "Analgésicos y antipiréticos (paracetamol, ibuprofeno)", "Remedios caseros (gárgaras con agua salada, líquidos tibios)", "Reposo de la voz"] } ], note: "No se deben usar antibióticos para faringitis virales." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Consulta a un profesional si:", items: ["El dolor de garganta dura más de una semana o es muy intenso", "Tienes fiebre alta, erupción cutánea o dolor articular", "Presentas dificultad severa para tragar o respirar"] } },
'Diabetes tipo 2' : { intro: "La diabetes tipo 2 es una afección crónica que afecta la forma en que el cuerpo procesa el azúcar (glucosa) en la sangre. Con esta condición, el cuerpo no produce suficiente insulina o resiste sus efectos.", whatIs: { title: "¿Qué es la Diabetes Tipo 2?", text: "Es un trastorno metabólico caracterizado por altos niveles de glucosa en sangre debido a la resistencia a la insulina. Con el tiempo, esto puede causar daños graves en los vasos sanguíneos, nervios y órganos." }, types: { title: "Relación con otras condiciones", intro: "Suele estar estrechamente vinculada a:", items: ["Síndrome metabólico", "Prediabetes (etapa previa que puede revertirse)", "Obesidad central"], note: "Es la forma más común de diabetes, representando la gran mayoría de los casos." }, diagnosis: { title: "Pruebas de Detección", intro: "Se diagnostica mediante análisis de sangre:", items: ["Prueba de hemoglobina glicosilada (A1C) mayor a 6.5%", "Glucosa plasmática en ayunas mayor a 126 mg/dL", "Prueba de tolerancia oral a la glucosa"], note: "Generalmente se requieren dos pruebas alteradas para confirmar el diagnóstico." }, treatment: { title: "Control y Tratamiento", intro: "El manejo requiere un enfoque integral a largo plazo:", subsections: [ { title: "Pilares del manejo", items: ["Cambios en el estilo de vida (dieta saludable, pérdida de peso, ejercicio regular)", "Medicamentos orales (metformina, inhibidores de SGLT2, etc.)", "Terapia con insulina (en etapas más avanzadas o mal controladas)", "Monitoreo regular de la glucosa"] } ], note: "El control estricto reduce el riesgo de complicaciones como ceguera, amputaciones o infartos." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca evaluación médica si:", items: ["Tienes aumento inusual de sed y ganas de orinar frecuentemente", "Sientes fatiga extrema o visión borrosa", "Tienes heridas que tardan mucho en sanar"] } },
'Sangrado uterino disfuncional' : { intro: "El sangrado uterino disfuncional (SUD) o sangrado uterino anormal se refiere a cualquier sangrado vaginal que ocurre fuera del ciclo menstrual normal, ya sea por su cantidad, duración o frecuencia, sin que exista una causa estructural evidente (como miomas o pólipos).", whatIs: { title: "¿Qué es el Sangrado Uterino Disfuncional?", text: "Es una alteración en el sangrado menstrual causada predominantemente por desequilibrios hormonales (usualmente falta de ovulación), siendo común en la adolescencia o en la perimenopausia." }, types: { title: "Patrones de Sangrado", intro: "Puede manifestarse de diversas maneras:", items: ["Menorragia (sangrado muy abundante o prolongado)", "Metrorragia (sangrado entre períodos)", "Polimenorrea (ciclos muy cortos, menos de 21 días)", "Oligomenorrea (ciclos muy largos o infrecuentes)"], note: "" }, diagnosis: { title: "Evaluación", intro: "Se requiere descartar causas físicas o anatómicas:", items: ["Examen pélvico y prueba de Papanicolaou", "Ecografía transvaginal (para evaluar el endometrio y ovarios)", "Análisis de sangre (hormonas, tiroides, pruebas de coagulación)", "Biopsia endometrial (en mujeres mayores para descartar malignidad)"], note: "Es un diagnóstico de exclusión." }, treatment: { title: "Manejo Clínico", intro: "El tratamiento busca regular el ciclo y prevenir la anemia:", subsections: [ { title: "Opciones", items: ["Terapia hormonal (píldoras anticonceptivas, progestágenos, DIU hormonal)", "Medicamentos no hormonales (ácido tranexámico, AINEs)", "Suplementos de hierro (si hay anemia)", "Procedimientos quirúrgicos (ablación endometrial o histerectomía en casos severos y refractarios)"] } ], note: "El tratamiento se personaliza según la edad y los deseos reproductivos de la paciente." }, whenToSeekHelp: { title: "¿Cuándo ir al ginecólogo?", intro: "Debes consultar a un profesional si:", items: ["Tu período dura más de 7 días o empapas una compresa cada hora", "Tienes sangrado después de la menopausia", "Experimentas sangrado irregular entre ciclos normales"] } },
'Asma' : { intro: "El asma es una enfermedad crónica que afecta las vías respiratorias de los pulmones. Estas vías se inflaman y se estrechan, lo que dificulta la respiración y provoca episodios de sibilancias, falta de aire y tos.", whatIs: { title: "¿Qué es el Asma?", text: "Es una condición inflamatoria crónica de los bronquios. Ante ciertos desencadenantes (alergenos, frío, ejercicio), las vías respiratorias reaccionan exageradamente, produciendo más moco y contrayendo los músculos que las rodean." }, types: { title: "Clasificación", intro: "El asma se clasifica según su gravedad y desencadenantes:", items: ["Asma alérgica (desencadenada por polen, ácaros, caspa de animales)", "Asma no alérgica (por estrés, frío, infecciones respiratorias)", "Asma ocupacional (exposición en el lugar de trabajo)", "Asma inducida por el ejercicio", "Según gravedad: intermitente, leve persistente, moderada, severa"], note: "" }, diagnosis: { title: "Diagnóstico", intro: "El neumólogo o alergólogo realizará:", items: ["Espirometría (prueba de función pulmonar para medir cuánto y qué tan rápido se exhala el aire)", "Prueba de reversibilidad (espirometría antes y después de usar un broncodilatador)", "Pruebas de alergia (si se sospecha asma alérgica)"], note: "En niños pequeños, el diagnóstico a menudo se basa en los síntomas y la respuesta al tratamiento." }, treatment: { title: "Manejo y Control", intro: "El asma no tiene cura, pero se controla con medicación:", subsections: [ { title: "Medicamentos", items: ["Medicamentos de control a largo plazo (corticosteroides inhalados, modificadores de leucotrienos)", "Medicamentos de alivio rápido o rescate (broncodilatadores de acción corta como el salbutamol)", "Terapias biológicas (para asma severa)"] } ], note: "Es vital identificar y evitar los factores desencadenantes personales." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a urgencias si:", items: ["Tienes dificultad extrema para respirar que no mejora con tu inhalador de rescate", "Tus labios o uñas se vuelven azulados", "Sientes que no puedes hablar frases completas por falta de aire"] } },
'Gingivitis' : { intro: "La gingivitis es una forma frecuente y leve de enfermedad de las encías (enfermedad periodontal), que causa irritación, enrojecimiento e hinchazón (inflamación) de la parte de las encías que rodea la base de los dientes.", whatIs: { title: "¿Qué es la Gingivitis?", text: "Es la inflamación superficial de la encía, causada principalmente por la acumulación de placa bacteriana en la línea de las encías debido a una higiene bucal deficiente. Es completamente reversible si se trata a tiempo." }, types: { title: "Clasificación", intro: "Puede presentarse de diversas formas:", items: ["Gingivitis inducida por placa dental (la más común)", "Gingivitis no inducida por placa (causada por infecciones virales, fúngicas o genéticas)", "Gingivitis asociada a factores sistémicos (embarazo, diabetes)"], note: "Si no se trata, puede progresar a periodontitis y provocar la pérdida de dientes." }, diagnosis: { title: "Detección", intro: "El dentista diagnosticará la afección mediante:", items: ["Examen visual de las encías para detectar inflamación, enrojecimiento o sangrado", "Sondaje de las encías para medir la profundidad de los surcos gingivales", "Revisión del historial médico e higiene dental"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es reducir la inflamación y eliminar la placa:", subsections: [ { title: "Pasos a seguir", items: ["Limpieza dental profesional (profilaxis o raspado para eliminar sarro y placa)", "Mejora rigurosa en la higiene bucal en casa (cepillado dos veces al día y uso de hilo dental)", "Uso de enjuagues bucales antisépticos recetados"] } ], note: "La constancia en los hábitos de higiene es la clave para la prevención." }, whenToSeekHelp: { title: "¿Cuándo visitar al dentista?", intro: "Programa una cita si notas:", items: ["Encías rojas, hinchadas o sensibles", "Sangrado constante al cepillarte los dientes o usar hilo dental", "Mal aliento crónico o mal sabor de boca"] } },
'Maltrato psicológico y abandono infantil' : { intro: "El maltrato psicológico y el abandono son formas de abuso infantil que no siempre dejan marcas físicas, pero causan daños profundos y duraderos en el desarrollo emocional, cognitivo y social del menor. Constituyen violaciones graves de los derechos del niño.", whatIs: { title: "¿Qué son?", text: "El maltrato psicológico implica actos repetidos que transmiten al niño que es inútil, no amado o que solo tiene valor para satisfacer las necesidades de otro. El abandono (negligencia) es la falta de provisión de las necesidades básicas físicas, emocionales, médicas o educativas del menor." }, types: { title: "Manifestaciones", intro: "Estas formas de abuso incluyen:", items: ["Rechazo constante, humillación o aterrorizar al niño", "Aislamiento social forzado", "Negligencia física (falta de alimento, higiene o refugio adecuado)", "Negligencia médica o educativa", "Exposición continua a violencia doméstica"], note: "Suele ocurrir de forma silenciosa dentro del núcleo familiar." }, diagnosis: { title: "Evaluación e Identificación", intro: "Suele requerir la intervención de equipos multidisciplinarios:", items: ["Evaluación psicológica y psiquiátrica del menor", "Observación de retrasos en el desarrollo o comportamientos anormales (agresividad, retraimiento)", "Entrevistas y evaluación del entorno familiar por parte de trabajadores sociales"], note: "Los educadores y médicos suelen ser los primeros en detectar señales de alerta." }, treatment: { title: "Intervención y Protección", intro: "El enfoque principal es proteger al menor y sanar el trauma:", subsections: [ { title: "Medidas", items: ["Intervención de servicios de protección infantil (para garantizar la seguridad física del niño)", "Psicoterapia especializada en trauma infantil (Terapia Cognitivo-Conductual centrada en el trauma)", "Terapia de apoyo y rehabilitación familiar (solo si el entorno puede volverse seguro)", "Apoyo educativo y médico continuo"] } ], note: "La recuperación requiere un entorno seguro, estable y afectuoso." }, whenToSeekHelp: { title: "¿Cuándo denunciar o buscar ayuda?", intro: "Es responsabilidad de cualquier adulto actuar si observa:", items: ["Un niño consistentemente sucio, desnutrido o vestido de forma inadecuada para el clima", "Comportamientos extremadamente temerosos, ansiosos o de apego indiscriminado en un niño", "Conocimiento directo de padres que humillan, amenazan o ignoran sistemáticamente a sus hijos"] } },
'Abdomen agudo' : { intro: "El abdomen agudo es un término médico utilizado para describir un dolor abdominal severo y de aparición rápida que generalmente requiere intervención médica o quirúrgica urgente. Es un síntoma de alarma que agrupa diversas patologías graves.", whatIs: { title: "¿Qué es el Abdomen Agudo?", text: "Es un síndrome clínico caracterizado por un dolor abdominal intenso, de evolución rápida (usualmente menos de 24-48 horas), a menudo acompañado de rigidez muscular abdominal ('abdomen en tabla') y signos de compromiso sistémico." }, types: { title: "Clasificación por Causas", intro: "Se divide según la naturaleza del problema:", items: ["Inflamatorio/Infeccioso (ej. apendicitis, colecistitis, diverticulitis)", "Perforativo (ej. úlcera gástrica perforada)", "Obstructivo (ej. obstrucción intestinal, vólvulo)", "Hemorrágico (ej. rotura de embarazo ectópico, aneurisma aórtico)", "Isquémico (ej. trombosis mesentérica)"], note: "Identificar el tipo exacto es vital para la decisión quirúrgica." }, diagnosis: { title: "Evaluación de Urgencia", intro: "El diagnóstico debe ser rápido y preciso:", items: ["Examen físico detallado (búsqueda de signos de peritonitis o 'rebote')", "Análisis de sangre y orina", "Pruebas de imagen (Tomografía Computarizada, Ecografía o Radiografía de abdomen)"], note: "El retraso en el diagnóstico puede tener consecuencias fatales." }, treatment: { title: "Manejo Médico", intro: "El tratamiento depende directamente de la causa subyacente:", subsections: [ { title: "Intervenciones", items: ["Cirugía de emergencia (laparotomía o laparoscopia exploratoria) en muchos casos", "Estabilización hemodinámica (líquidos intravenosos, corrección de electrolitos)", "Antibióticos de amplio espectro", "Analgésicos (una vez que se ha evaluado el cuadro para no enmascarar síntomas)"] } ], note: "No todos los casos de abdomen agudo requieren cirugía, pero todos requieren evaluación hospitalaria." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Se debe solicitar ayuda médica inmediata ante:", items: ["Dolor abdominal súbito, insoportable o que empeora rápidamente", "Abdomen duro al tacto o dolor severo al soltar la presión", "Dolor acompañado de vómitos con sangre, fiebre alta o desmayos"] } },
'Desorden de ansiedad por separación' : { intro: "El desorden de ansiedad por separación es una condición psicológica en la que un individuo experimenta una ansiedad excesiva e inapropiada para su nivel de desarrollo respecto a la separación de las personas a las que está profundamente apegado (generalmente los padres).", whatIs: { title: "¿Qué es la Ansiedad por Separación?", text: "Si bien una leve ansiedad al separarse es normal en bebés y niños pequeños, este trastorno implica un miedo paralizante y persistente que interfiere con actividades normales como ir a la escuela o dormir solo." }, types: { title: "Presentación", intro: "Aunque es más común en la infancia, puede afectar a:", items: ["Niños en edad preescolar y escolar", "Adolescentes (manifestándose como rechazo escolar o aislamiento)", "Adultos (ansiedad extrema por la pareja o los hijos)"], note: "" }, diagnosis: { title: "Evaluación Clínica", intro: "Un profesional de la salud mental buscará:", items: ["Ansiedad excesiva y recurrente al alejarse del hogar o de las figuras de apego (durante al menos 4 semanas en niños o 6 meses en adultos)", "Pesadillas repetidas sobre la separación", "Rechazo constante a salir de casa o estar solo por miedo"], note: "Se debe diferenciar del trastorno de pánico o fobia social." }, treatment: { title: "Abordaje Terapéutico", intro: "El tratamiento busca enseñar habilidades de afrontamiento:", subsections: [ { title: "Opciones", items: ["Terapia Cognitivo-Conductual (TCC) para el niño y la familia", "Terapia de exposición gradual a la separación", "Entrenamiento para padres sobre cómo manejar las despedidas y fomentar la independencia", "Medicación (solo en casos graves donde la terapia no es suficiente)"] } ], note: "La participación activa de los padres es fundamental para el éxito del tratamiento." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Es momento de buscar ayuda profesional si:", items: ["La ansiedad impide que el niño asista a la escuela o participe en actividades sociales", "El niño experimenta síntomas físicos graves (vómitos, dolores de cabeza) ante la separación", "El problema persiste más allá de la edad preescolar de forma intensa"] } },
'Hernia de disco' : { intro: "Una hernia de disco ocurre cuando el centro blando y gelatinoso de un disco intervertebral se asoma o se rompe a través de un desgarro en el anillo exterior duro. Esto puede irritar los nervios cercanos y causar dolor, entumecimiento o debilidad en un brazo o una pierna.", whatIs: { title: "¿Qué es una Hernia de Disco?", text: "Es el desplazamiento del núcleo pulposo de los discos que amortiguan las vértebras de la columna. Al salirse de su lugar, comprime las raíces nerviosas espinales, generando síntomas neurológicos dolorosos." }, types: { title: "Ubicación", intro: "Pueden ocurrir en cualquier parte de la columna, pero son más comunes en:", items: ["Zona lumbar (espalda baja): Afecta las piernas y es la causa más común de ciática.", "Zona cervical (cuello): Afecta los hombros y brazos.", "Zona torácica (espalda media): Son muy raras."], note: "No todas las hernias de disco causan síntomas; muchas se descubren accidentalmente." }, diagnosis: { title: "Diagnóstico", intro: "El especialista en columna evaluará:", items: ["Examen físico neurológico (evaluación de reflejos, fuerza muscular y sensibilidad)", "Resonancia Magnética (RM) (el método estándar para confirmar la hernia y ver los nervios afectados)", "Radiografías (para descartar otras causas como fracturas o tumores)"], note: "" }, treatment: { title: "Opciones Terapéuticas", intro: "El tratamiento inicial suele ser conservador:", subsections: [ { title: "Manejo", items: ["Modificación de actividades y reposo breve", "Fisioterapia para fortalecer los músculos de la espalda y el tronco", "Medicamentos (AINEs, analgésicos nerviosos, relajantes musculares)", "Inyecciones epidurales de esteroides", "Cirugía (microdiscectomía) si el dolor no mejora tras meses o hay pérdida de función motora"] } ], note: "La gran mayoría de los pacientes mejoran sin necesidad de cirugía." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia?", intro: "Busca atención médica inmediata si experimentas:", items: ["Pérdida de control de la vejiga o los intestinos (incontinencia)", "Entumecimiento progresivo en forma de 'silla de montar' (área de las nalgas y muslos internos)", "Debilidad severa que te impide caminar o mover el pie"] } },
'Tendinitis del manguito de los rotadores' : { intro: "La tendinitis del manguito de los rotadores es la inflamación de los tendones que ayudan a mover y estabilizar la articulación del hombro. Es una patología muy frecuente por uso repetitivo, especialmente en deportes o trabajos que requieren levantar los brazos.", whatIs: { title: "¿Qué es la Tendinitis del Manguito?", text: "Es la irritación e hinchazón de uno o más tendones (frecuentemente el supraespinoso) que conectan los músculos del hombro con el hueso del brazo, provocando dolor al realizar movimientos por encima de la cabeza o al dormir sobre ese lado." }, types: { title: "Presentación Clínica", intro: "Puede presentarse como:", items: ["Tendinitis aguda (por un esfuerzo brusco o lesión reciente)", "Tendinitis crónica (por desgaste repetitivo prolongado)", "Tendinitis calcificante (acumulación de depósitos de calcio en el tendón)"], note: "Suele estar estrechamente relacionada con el síndrome de pinzamiento del hombro." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico se basa en:", items: ["Examen físico con maniobras específicas para evaluar la fuerza y el origen del dolor en el hombro", "Ecografía musculoesquelética (para ver inflamación en tiempo real)", "Resonancia Magnética (para descartar roturas completas del tendón)"], note: "" }, treatment: { title: "Tratamiento", intro: "Se centra en reducir la inflamación y restaurar la mecánica del hombro:", subsections: [ { title: "Intervenciones", items: ["Reposo relativo (evitar el movimiento que causa dolor)", "Aplicación de hielo en etapas agudas", "Fisioterapia especializada (esencial para la recuperación a largo plazo)", "Analgésicos, AINEs o infiltraciones con corticosteroides en casos persistentes"] } ], note: "Ignorar el dolor y continuar con la actividad puede llevar a un desgarro del tendón." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable consultar si:", items: ["El dolor en el hombro dura más de dos semanas a pesar del reposo", "Sientes debilidad notable al intentar levantar el brazo", "El dolor te despierta por la noche sistemáticamente"] } },
'Fobia específica o simple' : { intro: "Una fobia específica es un trastorno de ansiedad caracterizado por un miedo intenso, irracional y persistente hacia un objeto, situación, animal o actividad específica que en realidad representa poco o ningún peligro real.", whatIs: { title: "¿Qué es una Fobia Específica?", text: "Es una respuesta de miedo desproporcionada que provoca que la persona evite activamente el estímulo fóbico, causando una gran angustia e interfiriendo con su rutina diaria, trabajo o vida social." }, types: { title: "Categorías Comunes", intro: "Las fobias específicas se agrupan en cinco tipos principales:", items: ["Animales (arañas, perros, serpientes)", "Entorno natural (alturas, tormentas, agua)", "Sangre, inyecciones o heridas (ver sangre, recibir inyecciones)", "Situacionales (volar en avión, espacios cerrados, ascensores)", "Otras (miedo a asfixiarse, a los payasos, a ruidos fuertes)"], note: "Es posible tener más de una fobia específica simultáneamente." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Un profesional de la salud mental evaluará basándose en el DSM-5:", items: ["El miedo irracional dura seis meses o más", "La exposición al estímulo provoca una respuesta inmediata de ansiedad o ataque de pánico", "El miedo causa un deterioro significativo en la vida de la persona"], note: "El paciente suele reconocer que su miedo es excesivo o irracional." }, treatment: { title: "Manejo y Terapias", intro: "Las fobias específicas son altamente tratables:", subsections: [ { title: "Opciones", items: ["Terapia de Exposición (desensibilización sistemática, el tratamiento más eficaz)", "Terapia Cognitivo-Conductual (TCC)", "Uso de Realidad Virtual para la exposición controlada", "Medicamentos (betabloqueantes o ansiolíticos, usualmente a corto plazo para situaciones específicas como volar)"] } ], note: "Evitar el objeto fóbico suele empeorar la fobia a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo buscar tratamiento?", intro: "Es recomendable pedir ayuda si:", items: ["El miedo paralizante te impide realizar actividades importantes o necesarias", "Modificas tu estilo de vida de manera significativa para evitar el desencadenante", "Sufres de ataques de pánico incontrolables al enfrentarte a la fobia"] } },
'Hernia inguinal' : { intro: "Una hernia inguinal ocurre cuando una porción de tejido, como una parte del intestino, empuja a través de un lugar debilitado en los músculos abdominales en la zona de la ingle. El bulto resultante puede ser doloroso, especialmente al toser, agacharse o levantar objetos pesados.", whatIs: { title: "¿Qué es una Hernia Inguinal?", text: "Es un defecto o debilidad en la pared abdominal baja que permite que el contenido del abdomen protruya, formando un bulto visible en la ingle o el escroto. No mejoran ni desaparecen por sí solas." }, types: { title: "Tipos Clínicos", intro: "Existen dos clasificaciones principales:", items: ["Hernia inguinal indirecta (causada por un defecto congénito, más común en hombres jóvenes o niños)", "Hernia inguinal directa (causada por debilidad muscular adquirida con el tiempo, común en adultos mayores)"], note: "Las hernias inguinales son mucho más frecuentes en hombres que en mujeres." }, diagnosis: { title: "Evaluación", intro: "El diagnóstico suele ser clínico:", items: ["Examen físico (el médico palpará la zona mientras el paciente tose o hace fuerza)", "Ecografía inguinal o Tomografía Computarizada (si el diagnóstico no es claro o para detectar hernias ocultas)"], note: "" }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento definitivo es quirúrgico:", subsections: [ { title: "Procedimientos", items: ["Cirugía abierta (reparación de la hernia con malla sintética)", "Cirugía laparoscópica (mínimamente invasiva, usando incisiones pequeñas y una cámara)", "Espera vigilante (solo en hernias muy pequeñas y asintomáticas, bajo estricto control médico)"] } ], note: "El uso de bragueros (cinturones para hernias) no se recomienda como solución a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a urgencias inmediatamente si sospechas de una hernia estrangulada (sin flujo sanguíneo), que presenta:", items: ["El bulto de la hernia se vuelve rojo, violáceo o muy oscuro", "Dolor súbito que empeora rápidamente", "Náuseas, vómitos o incapacidad para evacuar los intestinos o expulsar gases", "El bulto no se puede volver a empujar hacia adentro (encarcelación)"] } },
'Neumonía' : { intro: "La neumonía es una infección que inflama los sacos aéreos (alvéolos) de uno o ambos pulmones. Los sacos pueden llenarse de líquido o pus, lo que provoca tos con flema, fiebre, escalofríos y dificultad para respirar.", whatIs: { title: "¿Qué es la Neumonía?", text: "Es una enfermedad respiratoria grave causada por bacterias, virus u hongos que logran evadir las defensas del cuerpo y se multiplican en los pulmones, dificultando el intercambio de oxígeno." }, types: { title: "Clasificación", intro: "Se clasifica según dónde y cómo se adquirió:", items: ["Neumonía adquirida en la comunidad (la más común, fuera de hospitales)", "Neumonía intrahospitalaria (adquirida durante una internación, suele ser más grave y resistente)", "Neumonía por aspiración (al inhalar alimentos, líquidos o vómito hacia los pulmones)", "Neumonía atípica (causada por patógenos menos comunes como Mycoplasma)"], note: "La gravedad varía desde leve hasta potencialmente mortal." }, diagnosis: { title: "Pruebas Médicas", intro: "El médico realizará:", items: ["Auscultación pulmonar (para escuchar ruidos crepitantes o burbujeos)", "Radiografía de tórax (confirma la infección y su extensión)", "Análisis de sangre y oximetría de pulso (para ver la oxigenación)", "Cultivo de esputo (para identificar el microorganismo causante)"], note: "" }, treatment: { title: "Manejo Clínico", intro: "El tratamiento depende del tipo de germen, la edad y el estado de salud:", subsections: [ { title: "Terapias", items: ["Antibióticos (para neumonías bacterianas)", "Antivirales (si es causada por virus como la gripe o el SARS-CoV-2)", "Medicamentos para la fiebre, el dolor y antitusígenos (solo para alivio)", "Hospitalización, oxígeno o asistencia respiratoria (en casos graves)"] } ], note: "El reposo y la hidratación abundante son fundamentales para la recuperación." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Es urgente buscar atención si:", items: ["Tienes dificultad significativa para respirar o respiración rápida", "Sientes dolor persistente en el pecho al respirar o toser", "Tienes fiebre alta persistente, desorientación (especialmente en adultos mayores) o coloración azulada en los labios"] } },
'Colecistitis aguda' : { intro: "La colecistitis aguda es la inflamación repentina de la vesícula biliar, el pequeño órgano situado debajo del hígado que almacena la bilis. Es una condición dolorosa y potencialmente grave que requiere atención médica hospitalaria urgente.", whatIs: { title: "¿Qué es la Colecistitis Aguda?", text: "Generalmente ocurre cuando los cálculos biliares (piedras en la vesícula) bloquean el conducto cístico por donde la bilis sale del órgano. Esto provoca que la bilis se acumule, irritando la pared de la vesícula y causando inflamación o infección." }, types: { title: "Tipos", intro: "Se divide principalmente en dos formas:", items: ["Colecistitis litiásica (causada por la presencia de cálculos biliares, representa más del 90% de los casos)", "Colecistitis alitiásica (sin cálculos biliares, a menudo tras traumas graves, cirugías mayores o enfermedades críticas)"], note: "" }, diagnosis: { title: "Diagnóstico", intro: "Para confirmarla, el médico indicará:", items: ["Examen físico con 'Signo de Murphy' positivo (dolor agudo al palpar el abdomen derecho mientras el paciente respira profundo)", "Ecografía abdominal (el mejor estudio para ver cálculos e inflamación de la pared de la vesícula)", "Análisis de sangre (leucocitos altos indicando infección, y enzimas hepáticas)"], note: "" }, treatment: { title: "Manejo Hospitalario", intro: "Suele requerir hospitalización inicial:", subsections: [ { title: "Tratamientos", items: ["Ayuno (para que la vesícula descanse) y líquidos intravenosos", "Antibióticos y analgésicos fuertes", "Colecistectomía laparoscópica (cirugía para extirpar la vesícula biliar, generalmente es el tratamiento definitivo)"] } ], note: "Retrasar el tratamiento puede llevar a complicaciones como la rotura de la vesícula o peritonitis." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Debes buscar ayuda médica inmediata ante:", items: ["Dolor severo y constante en la parte superior derecha o centro del abdomen", "Dolor que se irradia hacia el hombro derecho o la espalda", "Fiebre alta, escalofríos, náuseas, vómitos, o coloración amarillenta de la piel (ictericia)"] } },
'Cataratas' : { intro: "Una catarata es una opacidad de la lente natural (cristalino) del ojo, que normalmente es transparente. Para las personas que tienen cataratas, ver a través de cristalinos opacos es algo parecido a mirar a través de una ventana empañada o escarchada.", whatIs: { title: "¿Qué son las Cataratas?", text: "Es el proceso de envejecimiento o alteración de las proteínas del cristalino, lo que provoca que pierda su transparencia. Esto bloquea o dispersa la luz que entra al ojo, resultando en una visión borrosa, colores menos nítidos y deslumbramiento." }, types: { title: "Clasificación", intro: "Existen varios tipos según su ubicación o causa:", items: ["Cataratas nucleares (en el centro del cristalino, asociadas al envejecimiento)", "Cataratas corticales (en los bordes, en forma de cuña)", "Cataratas subcapsulares posteriores (en la parte posterior, progresan rápidamente, comunes en diabéticos)", "Cataratas congénitas o traumáticas"], note: "La mayoría se desarrollan lentamente y no alteran la vista en etapas tempranas." }, diagnosis: { title: "Evaluación Oftalmológica", intro: "El oftalmólogo realizará un examen ocular completo:", items: ["Examen de agudeza visual", "Examen con lámpara de hendidura (para ver las estructuras del ojo con aumento)", "Examen de la retina tras dilatar las pupilas"], note: "Se diagnostica fácilmente durante un chequeo de rutina." }, treatment: { title: "Soluciones y Cirugía", intro: "La cirugía es el único tratamiento efectivo cuando la pérdida de visión interfiere con las actividades diarias:", subsections: [ { title: "Abordaje", items: ["Uso de gafas más fuertes o mejor iluminación (en etapas iniciales)", "Cirugía de cataratas (extracción del cristalino opaco y reemplazo por un lente intraocular artificial o LIO)", "Medidas de protección (lentes de sol con protección UV)"] } ], note: "La cirugía de cataratas es uno de los procedimientos quirúrgicos más seguros y comunes del mundo." }, whenToSeekHelp: { title: "¿Cuándo programar una cita?", intro: "Consulta a un oftalmólogo si experimentas:", items: ["Cambios repentinos en la visión o visión doble", "Dificultad creciente para ver de noche o conducir en la oscuridad", "Molestia excesiva con las luces brillantes o necesidad de cambiar frecuentemente la graduación de los lentes"] } },
'Reflujo gastroesofágico' : { intro: "La enfermedad por reflujo gastroesofágico (ERGE) es una afección digestiva crónica que ocurre cuando el ácido del estómago o la bilis ascienden hacia el conducto que conecta la boca con el estómago (esófago). Este lavado ácido irrita el revestimiento esofágico.", whatIs: { title: "¿Qué es la ERGE?", text: "Ocurre cuando el esfínter esofágico inferior (una válvula muscular) se debilita o se relaja de manera anormal, permitiendo que el contenido estomacal retorne hacia arriba, causando la clásica sensación de ardor conocida como acidez." }, types: { title: "Presentación", intro: "El reflujo puede ser:", items: ["Fisiológico (episodios ocasionales, especialmente tras comidas copiosas, normales en muchas personas)", "Patológico o ERGE (cuando los síntomas ocurren al menos dos veces por semana o causan daño esofágico)", "Reflujo silencioso o laringofaríngeo (el ácido llega a la garganta causando tos o ronquera, a menudo sin acidez)"], note: "" }, diagnosis: { title: "Pruebas Médicas", intro: "Para diagnosticar ERGE crónico se utilizan:", items: ["Evaluación clínica de los síntomas (suele ser suficiente para iniciar tratamiento)", "Endoscopia superior (para verificar inflamación o esófago de Barrett)", "Monitoreo del pH esofágico de 24 horas (mide la cantidad de ácido)", "Manometría esofágica (mide las contracciones musculares del esófago)"], note: "" }, treatment: { title: "Manejo y Control", intro: "El tratamiento escalonado es la norma:", subsections: [ { title: "Estrategias", items: ["Modificaciones en el estilo de vida (evitar acostarse tras comer, elevar la cabecera de la cama, perder peso)", "Medicamentos de venta libre (antiácidos, antagonistas H2 como famotidina)", "Inhibidores de la bomba de protones o IBP (omeprazol, pantoprazol) para curar el esófago", "Cirugía (funduplicatura de Nissen) en casos refractarios a la medicación"] } ], note: "Evitar desencadenantes como cafeína, alcohol, chocolate y comidas grasas es crucial." }, whenToSeekHelp: { title: "¿Cuándo ver a un médico?", intro: "Busca ayuda especializada si:", items: ["Tienes acidez estomacal severa o frecuente que no mejora con medicamentos de venta libre", "Sientes dolor en el pecho que puede confundirse con un problema cardíaco", "Experimentas dificultad para tragar, sensación de comida atascada o pérdida de peso inexplicable"] } },
'Diverticulitis' : { intro: "La diverticulitis es la inflamación o infección de pequeños sacos o bolsas (divertículos) que se forman en las paredes del tracto digestivo, con mayor frecuencia en la parte inferior del intestino grueso (colon).", whatIs: { title: "¿Qué es la Diverticulitis?", text: "Es una complicación de la diverticulosis. Cuando estas bolsas se desgarran, se inflaman o se infectan, causan dolor abdominal intenso, fiebre, náuseas y un cambio marcado en los hábitos intestinales." }, types: { title: "Clasificación", intro: "Puede presentarse de dos formas principales:", items: ["Diverticulitis no complicada (inflamación localizada sin problemas adicionales)", "Diverticulitis complicada (con abscesos, fístulas, obstrucción intestinal o perforación)"], note: "Los episodios repetidos pueden requerir intervención quirúrgica." }, diagnosis: { title: "Detección", intro: "El diagnóstico médico incluye:", items: ["Exploración física para detectar sensibilidad abdominal", "Tomografía computarizada (TC) del abdomen para confirmar las bolsas inflamadas", "Análisis de sangre y orina para detectar signos de infección"], note: "No se recomienda colonoscopia durante un episodio agudo para evitar perforaciones." }, treatment: { title: "Manejo", intro: "Depende de la gravedad del episodio:", subsections: [ { title: "Opciones", items: ["Dieta líquida y reposo intestinal", "Antibióticos orales o intravenosos", "Analgésicos para el dolor", "Cirugía (resección intestinal) en casos complicados o recurrentes"] } ], note: "Una dieta alta en fibra ayuda a prevenir futuros episodios una vez curado." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca ayuda inmediata si presentas:", items: ["Dolor abdominal intenso, constante y repentino, especialmente en el lado inferior izquierdo", "Fiebre alta y escalofríos", "Vómitos repetidos o sangre en las heces"] } },
'Enfermedad articular degenerativa' : { intro: "La enfermedad articular degenerativa, también conocida como osteoartritis o artrosis, es el tipo más común de artritis. Ocurre cuando el cartílago protector que amortigua los extremos de los huesos se desgasta con el tiempo.", whatIs: { title: "¿Qué es?", text: "Es una enfermedad crónica y progresiva de las articulaciones. El cartílago se vuelve áspero o desaparece por completo, provocando que el hueso roce con el hueso, lo que causa dolor, rigidez y pérdida de movimiento." }, types: { title: "Ubicaciones comunes", intro: "Afecta principalmente a las articulaciones que soportan peso o tienen mucho uso:", items: ["Rodillas", "Caderas", "Manos y dedos", "Columna vertebral (cuello o espalda baja)"], note: "El daño en las articulaciones no se puede revertir, pero los síntomas se pueden controlar." }, diagnosis: { title: "Diagnóstico", intro: "El reumatólogo u ortopedista utilizará:", items: ["Examen físico para revisar la articulación inflamada, su rango de movimiento y dolor", "Radiografías (para mostrar pérdida de cartílago y espolones óseos)", "Resonancia magnética (en casos complejos)", "Análisis de líquido articular (para descartar gota o infección)"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es aliviar el dolor y mantener el movimiento:", subsections: [ { title: "Enfoques", items: ["Medicación (paracetamol, AINEs, cremas tópicas)", "Terapia física y ocupacional", "Pérdida de peso y ejercicio de bajo impacto", "Inyecciones de cortisona o ácido hialurónico", "Cirugía de reemplazo articular (en etapas avanzadas)"] } ], note: "El ejercicio regular es una de las terapias más efectivas." }, whenToSeekHelp: { title: "¿Cuándo ver al médico?", intro: "Es recomendable consultar si:", items: ["Tienes dolor o rigidez en las articulaciones que no desaparece", "El dolor te impide realizar tareas diarias o dormir", "Notas inflamación o deformidad en una articulación"] } },
'Tendinitis' : { intro: "La tendinitis es la inflamación o irritación de un tendón, las cuerdas fibrosas gruesas que unen el músculo al hueso. Este trastorno causa dolor y sensibilidad justo afuera de la articulación.", whatIs: { title: "¿Qué es la Tendinitis?", text: "Es una lesión por sobreuso o sobrecarga mecánica en la que se producen microdesgarros en el tejido del tendón, generando una respuesta inflamatoria local. Es muy común en hombros, codos, muñecas, rodillas y talones." }, types: { title: "Tipos Comunes", intro: "A menudo toman el nombre del deporte que las provoca:", items: ["Codo de tenista (epicondilitis lateral)", "Codo de golfista (epicondilitis medial)", "Hombro de nadador (tendinitis del manguito de los rotadores)", "Rodilla de saltador (tendinitis rotuliana)", "Tendinitis de Aquiles"], note: "" }, diagnosis: { title: "Evaluación", intro: "Suele diagnosticarse clínicamente:", items: ["Examen físico palpando el tendón afectado y pidiendo movimientos específicos", "Ecografía musculoesquelética (para visualizar el engrosamiento e inflamación)", "Resonancia magnética (para evaluar desgarros graves)"], note: "Las radiografías no muestran los tendones, pero pueden descartar problemas óseos." }, treatment: { title: "Recuperación", intro: "Se enfoca en reducir la inflamación y fortalecer:", subsections: [ { title: "Medidas", items: ["Reposo y aplicación de hielo", "Medicamentos antiinflamatorios (AINEs)", "Fisioterapia y ejercicios de estiramiento", "Infiltraciones de corticosteroides (usadas con precaución para no debilitar el tendón)"] } ], note: "Retomar la actividad demasiado pronto puede volver el problema crónico." }, whenToSeekHelp: { title: "¿Cuándo buscar atención?", intro: "Debes ir al médico si:", items: ["El dolor interfiere con tus actividades diarias", "Los remedios caseros y el reposo no mejoran los síntomas después de varios días", "Sientes incapacidad repentina para mover una articulación (posible rotura)"] } },
'Radiculopatía lumbar' : { intro: "La radiculopatía lumbar, a menudo referida como ciática, es una afección que ocurre cuando un nervio en la parte baja de la espalda es comprimido, pellizcado o irritado, causando síntomas que se irradian hacia la pierna.", whatIs: { title: "¿Qué es la Radiculopatía Lumbar?", text: "Es el daño o inflamación de una raíz nerviosa espinal lumbar. Produce una combinación de dolor agudo, entumecimiento, hormigueo o debilidad que viaja a lo largo de la ruta del nervio, desde la espalda baja hasta el pie." }, types: { title: "Causas Subyacentes Frecuentes", intro: "Suele ser provocada por alteraciones estructurales:", items: ["Hernia de disco lumbar (la más común)", "Estenosis espinal (estrechamiento del canal vertebral)", "Espolones óseos (osteofitos debido a artrosis)", "Espondilolistesis (desplazamiento de una vértebra sobre otra)"], note: "" }, diagnosis: { title: "Diagnóstico Médico", intro: "Se requiere localizar exactamente qué nervio está afectado:", items: ["Examen neurológico completo (fuerza, sensibilidad y reflejos de las piernas)", "Prueba de elevación de la pierna estirada", "Resonancia magnética (RM) de la columna lumbar", "Electromiografía (EMG) para medir los impulsos eléctricos de los nervios"], note: "" }, treatment: { title: "Manejo", intro: "La mayoría de los pacientes mejoran con cuidados no quirúrgicos:", subsections: [ { title: "Opciones", items: ["Medicamentos (AINEs, analgésicos neuropáticos, corticosteroides)", "Fisioterapia específica para estabilización lumbar", "Inyecciones epidurales de esteroides", "Cirugía descompresiva (si hay daño nervioso progresivo o dolor intratable)"] } ], note: "Mantenerse moderadamente activo es mejor que el reposo absoluto en cama." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Atención inmediata si presentas:", items: ["Incontinencia urinaria o fecal repentina", "Adormecimiento severo en el área de la ingle y glúteos (anestesia en silla de montar)", "Debilidad que impide levantar el pie (pie caído)"] } },
'Depresión neurótica (distimia)' : { intro: "La distimia, también conocida como trastorno depresivo persistente o antiguamente depresión neurótica, es una forma de depresión continua y a largo plazo. Aunque los síntomas no son tan extremos como la depresión mayor, son constantes y duran años.", whatIs: { title: "¿Qué es la Distimia?", text: "Es un estado de ánimo deprimido crónico. Las personas con distimia pueden ser vistas como sombrías, quejumbrosas o incapaces de divertirse. La falta de alegría afecta profundamente su calidad de vida y relaciones." }, types: { title: "Manifestación", intro: "Características temporales del trastorno:", items: ["Inicio temprano (antes de los 21 años)", "Inicio tardío (a partir de los 21 años)", "Episodios superpuestos (puede sufrir episodios de depresión mayor encima de la distimia, conocido como depresión doble)"], note: "Para ser diagnosticada, los síntomas deben persistir al menos dos años en adultos." }, diagnosis: { title: "Evaluación Psicológica", intro: "El especialista evaluará basándose en el tiempo:", items: ["Entrevista psiquiátrica y cuestionarios de estado de ánimo", "Historial de síntomas por más de dos años sin un periodo libre de síntomas de más de dos meses", "Descarte de causas médicas como hipotiroidismo"], note: "" }, treatment: { title: "Abordaje", intro: "El tratamiento a largo plazo es el más eficaz:", subsections: [ { title: "Terapias", items: ["Psicoterapia (Terapia Cognitivo-Conductual, Terapia Interpersonal)", "Medicamentos antidepresivos (ISRS, ISRN)", "Desarrollo de habilidades de afrontamiento y hábitos de vida saludables"] } ], note: "Puede tomar tiempo encontrar la combinación de terapia y medicación adecuada." }, whenToSeekHelp: { title: "¿Cuándo pedir apoyo?", intro: "Es fundamental buscar ayuda si:", items: ["Sientes que la tristeza es una parte normal de tu personalidad pero te hace infeliz", "Tus relaciones o tu desempeño laboral están sufriendo", "Tienes pensamientos sobre el suicidio o de hacerte daño"] } },
'Infertilidad' : { intro: "La infertilidad se define como la incapacidad de lograr un embarazo después de 12 meses o más de relaciones sexuales regulares sin protección, o la incapacidad de llevar un embarazo a término.", whatIs: { title: "¿Qué es la Infertilidad?", text: "Es un problema del sistema reproductivo (masculino o femenino) que impide la concepción o el desarrollo de un embarazo. Puede deberse a un solo factor en uno de los miembros de la pareja o a una combinación de factores." }, types: { title: "Clasificación", intro: "Se divide médicamente en:", items: ["Infertilidad primaria (nunca se ha logrado un embarazo)", "Infertilidad secundaria (incapacidad de concebir tras haber tenido al menos un embarazo exitoso previo)", "Infertilidad de origen desconocido (cuando todas las pruebas resultan normales)"], note: "Aproximadamente un tercio de los casos se debe a factores masculinos, un tercio a femeninos, y un tercio son combinados o inexplicables." }, diagnosis: { title: "Estudios de Fertilidad", intro: "Ambos miembros de la pareja deben ser evaluados:", items: ["Análisis de semen (espermiograma) para el hombre", "Análisis hormonal y de reserva ovárica para la mujer", "Histerosalpingografía (radiografía para ver si las trompas de Falopio están abiertas)", "Ecografía transvaginal"], note: "Las pruebas pueden llevar tiempo y ser emocionalmente agotadoras." }, treatment: { title: "Soluciones Reproductivas", intro: "Existen múltiples opciones según la causa:", subsections: [ { title: "Técnicas", items: ["Inducción de la ovulación con medicamentos (clomifeno, gonadotropinas)", "Inseminación Intrauterina (IIU)", "Fecundación in Vitro (FIV)", "Inyección Intracitoplasmática de Espermatozoides (ICSI)", "Cirugía para corregir obstrucciones, miomas o endometriosis"] } ], note: "El apoyo psicológico durante los tratamientos es muy recomendado." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista?", intro: "Es el momento de consultar si:", items: ["Tienes menos de 35 años y llevas un año intentando", "Tienes 35 años o más y llevas 6 meses intentando", "Tienes antecedentes de períodos irregulares, endometriosis, o problemas testiculares"] } },
'Rinitis alérgica' : { intro: "La rinitis alérgica, conocida popularmente como fiebre del heno, es una reacción alérgica común que provoca síntomas similares a los del resfriado, afectando la nariz, los ojos, el paladar y la garganta.", whatIs: { title: "¿Qué es la Rinitis Alérgica?", text: "Es la inflamación de la mucosa nasal que se produce cuando el sistema inmunológico reacciona exageradamente a alérgenos en el aire, como polen, polvo o caspa de mascotas, liberando histamina y otras sustancias químicas." }, types: { title: "Presentación", intro: "Se clasifica según su aparición:", items: ["Rinitis alérgica estacional (fiebre del heno, desencadenada por polen en ciertas épocas del año)", "Rinitis alérgica perenne (ocurre todo el año, generalmente por ácaros, moho o mascotas)", "Rinitis ocupacional (causada por exposición a alérgenos en el trabajo)"], note: "A diferencia del resfriado, no es causada por un virus ni produce fiebre." }, diagnosis: { title: "Diagnóstico", intro: "El alergólogo determinará la causa exacta mediante:", items: ["Historia clínica y descripción de los síntomas y su temporalidad", "Pruebas cutáneas de alergia (prick test)", "Análisis de sangre (IgE específica o RAST)"], note: "" }, treatment: { title: "Control", intro: "El manejo busca evitar el alérgeno y tratar los síntomas:", subsections: [ { title: "Opciones", items: ["Evitación del alérgeno desencadenante", "Antihistamínicos (orales o en spray nasal)", "Corticosteroides nasales (el tratamiento más eficaz para la inflamación)", "Inmunoterapia (vacunas contra la alergia para desensibilizar el sistema inmune)"] } ], note: "El uso de lavados nasales con solución salina también proporciona un gran alivio." }, whenToSeekHelp: { title: "¿Cuándo visitar al médico?", intro: "Consulta si:", items: ["Los síntomas te impiden dormir o afectan tu rendimiento", "Los medicamentos de venta libre no brindan alivio", "Otra condición, como el asma, empeora junto con las alergias"] } },
'Cálculos biliares' : { intro: "Los cálculos biliares son depósitos endurecidos de fluido digestivo que se pueden formar en la vesícula biliar. Pueden variar en tamaño, desde un grano de arena hasta una pelota de golf.", whatIs: { title: "¿Qué son los Cálculos Biliares?", text: "Son 'piedras' que se forman debido a desequilibrios en las sustancias que componen la bilis, principalmente cuando hay exceso de colesterol o exceso de bilirrubina. Muchas personas los tienen sin saberlo ni presentar síntomas." }, types: { title: "Composición", intro: "Se dividen principalmente en:", items: ["Cálculos de colesterol (los más comunes, suelen ser de color amarillo-verdoso)", "Cálculos pigmentarios (hechos de bilirrubina, de color marrón oscuro o negro)"], note: "Si un cálculo bloquea un conducto biliar, se produce un 'cólico biliar'." }, diagnosis: { title: "Detección", intro: "Si se sospecha de su existencia, se realizan:", items: ["Ecografía abdominal (el método más común y preciso)", "Tomografía computarizada (TC)", "Colangiopancreatografía por resonancia magnética (CPRM)", "Análisis de sangre para detectar infecciones, ictericia o pancreatitis"], note: "" }, treatment: { title: "Intervenciones", intro: "Si no hay síntomas, usualmente no requieren tratamiento:", subsections: [ { title: "Tratamientos", items: ["Colecistectomía (cirugía para extirpar la vesícula biliar, frecuentemente laparoscópica)", "Medicamentos para disolver cálculos de colesterol (tardan meses/años y los cálculos pueden volver a formarse)", "CPRE (procedimiento endoscópico para extraer piedras de los conductos)"] } ], note: "Una vez extirpada la vesícula, la bilis fluye directamente del hígado al intestino." }, whenToSeekHelp: { title: "¿Cuándo es urgente?", intro: "Acude a urgencias si presentas signos de complicación grave:", items: ["Dolor abdominal tan intenso que no puedes sentarte derecho", "Color amarillento de la piel y la parte blanca de los ojos (ictericia)", "Fiebre alta con escalofríos"] } },
'Periodontitis' : { intro: "La periodontitis es una infección grave de las encías que daña el tejido blando y que, sin tratamiento, destruye el hueso que sostiene los dientes. Puede provocar el aflojamiento o la pérdida de dientes.", whatIs: { title: "¿Qué es la Periodontitis?", text: "Es la progresión grave de la gingivitis no tratada. Las bacterias de la placa dental penetran por debajo de la línea de las encías, creando 'bolsas' profundas llenas de infección que degradan el ligamento periodontal y el hueso alveolar." }, types: { title: "Clasificación", intro: "Se categoriza por su progresión:", items: ["Periodontitis crónica (la más común en adultos, progresión lenta)", "Periodontitis agresiva (rápida pérdida de inserción y destrucción ósea, a menudo familiar)", "Periodontitis como manifestación de enfermedades sistémicas", "Enfermedad periodontal necrosante (lesiones graves a menudo vistas en inmunodeprimidos)"], note: "La mala higiene bucal y el tabaquismo son los principales factores de riesgo." }, diagnosis: { title: "Evaluación Dental", intro: "El periodoncista realiza:", items: ["Sondaje periodontal para medir la profundidad de las bolsas alrededor de los dientes", "Radiografías dentales para ver la pérdida de hueso", "Evaluación de movilidad dental y recesión de encías"], note: "Bolsas de más de 4 mm indican periodontitis." }, treatment: { title: "Tratamiento", intro: "El objetivo es limpiar a fondo las bolsas y prevenir daños mayores:", subsections: [ { title: "Procedimientos", items: ["Raspado y alisado radicular (limpieza profunda debajo de las encías)", "Antibióticos tópicos u orales", "Cirugía de colgajo (para reducir la profundidad de la bolsa)", "Injertos de tejido blando o injertos óseos para regenerar lo perdido"] } ], note: "Requiere un mantenimiento periodontal de por vida (limpiezas frecuentes)." }, whenToSeekHelp: { title: "¿Cuándo consultar?", intro: "No esperes a tener dolor. Consulta si:", items: ["Tus encías se retraen y los dientes parecen más largos", "Tienes dientes flojos o notas que tu mordida ha cambiado", "Sufres de mal aliento constante que no se va con el cepillado"] } },
'Manchas en dientes' : { intro: "Las manchas en los dientes son decoloraciones que afectan la estética de la sonrisa. Pueden ser superficiales, causadas por alimentos o bebidas, o profundas, resultantes de cambios estructurales dentro del propio diente.", whatIs: { title: "¿Qué son las Manchas Dentales?", text: "Son alteraciones en el color natural de los dientes. Pueden afectar la capa externa (esmalte) o la capa interna (dentina), presentándose como zonas amarillentas, marrones, grises o blancas calcáreas." }, types: { title: "Tipos de Decoloración", intro: "Se clasifican según dónde se originan:", items: ["Extrínsecas (manchas superficiales por tabaco, café, té o vino tinto)", "Intrínsecas (dentro del diente por exceso de flúor en la infancia, trauma o tetraciclinas)", "Relacionadas con la edad (desgaste del esmalte que expone la dentina amarilla)"], note: "Las manchas blancas también pueden ser el primer signo de caries dental." }, diagnosis: { title: "Evaluación", intro: "El dentista determina el origen:", items: ["Examen visual y transiluminación", "Historial clínico para indagar uso de medicamentos en la infancia o hábitos dietéticos", "Radiografías si se sospecha necrosis pulpar (nervio muerto)"], note: "" }, treatment: { title: "Opciones Estéticas", intro: "El tratamiento varía desde limpieza hasta prótesis:", subsections: [ { title: "Tratamientos", items: ["Profilaxis profesional (para manchas extrínsecas)", "Blanqueamiento dental profesional (con peróxido de hidrógeno/carbamida)", "Microabrasión del esmalte", "Carillas dentales o coronas (para manchas intrínsecas severas o bandas por tetraciclina)"] } ], note: "Los blanqueamientos caseros sin supervisión pueden dañar el esmalte." }, whenToSeekHelp: { title: "¿Cuándo ver al dentista?", intro: "Es recomendable consultar si:", items: ["Una sola pieza dental se oscurece rápidamente (posible trauma o muerte del nervio)", "Las manchas no desaparecen con la higiene habitual", "Sientes inseguridad y deseas mejorar la estética de tu sonrisa"] } },
'Absceso dental' : { intro: "Un absceso dental es una acumulación de pus provocada por una infección bacteriana dentro del diente o en las encías circundantes. Es una condición muy dolorosa que requiere atención dental de emergencia.", whatIs: { title: "¿Qué es un Absceso Dental?", text: "Es un mecanismo de defensa del cuerpo que aísla una infección formando un saco de pus. Ocurre cuando las bacterias invaden la pulpa del diente (el centro vivo) o los tejidos periodontales debido a caries no tratadas, grietas o enfermedad de encías." }, types: { title: "Tipos de Absceso", intro: "Dependen de su ubicación exacta:", items: ["Absceso periapical (ocurre en la punta de la raíz del diente)", "Absceso periodontal (ocurre en la encía, al lado de la raíz de un diente)", "Absceso gingival (ocurre solo en el tejido de las encías, sin afectar el diente ni su ligamento)"], note: "Si no se trata, la infección puede propagarse a la mandíbula o al torrente sanguíneo." }, diagnosis: { title: "Diagnóstico Clínico", intro: "El dentista confirmará la infección mediante:", items: ["Examen físico, buscando hinchazón y tocando el diente para verificar sensibilidad", "Pruebas térmicas (al frío o calor)", "Radiografías dentales para ver la extensión del absceso y el hueso afectado"], note: "" }, treatment: { title: "Intervención de Urgencia", intro: "El objetivo principal es drenar el pus y eliminar la infección:", subsections: [ { title: "Procedimientos", items: ["Drenaje de la incisión (corte en la encía para liberar el pus)", "Tratamiento de conducto (endodoncia) para salvar el diente", "Extracción del diente si está demasiado dañado", "Antibióticos si la infección se ha propagado a áreas cercanas"] } ], note: "Los analgésicos alivian el dolor, pero no curan el absceso." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda urgente?", intro: "Acude inmediatamente al dentista o urgencias si presentas:", items: ["Dolor de muelas severo y punzante acompañado de fiebre", "Hinchazón visible en la cara, mejilla o ganglios del cuello", "Dificultad repentina para respirar o tragar"] } },
'Dolor abdominal' : { intro: "El dolor abdominal, comúnmente llamado dolor de estómago, abarca cualquier malestar que se sienta en la zona comprendida entre el pecho y la ingle. Puede variar desde un leve calambre hasta un dolor agudo y punzante de emergencia.", whatIs: { title: "¿Qué es el Dolor Abdominal?", text: "Es un síntoma inespecífico que puede originarse en cualquier órgano dentro de la cavidad abdominal (estómago, intestinos, hígado, vesícula, páncreas) o en las estructuras que lo rodean. Su intensidad no siempre refleja la gravedad de la afección." }, types: { title: "Tipos de Dolor", intro: "Se clasifica por cómo se siente y su duración:", items: ["Dolor generalizado (en más de la mitad del abdomen, típico de virus o indigestión)", "Dolor localizado (en un área específica, sugiere problemas en un órgano como apéndice o vesícula)", "Dolor tipo calambre (generalmente no grave, asociado a gases o menstruación)", "Dolor crónico (episódico o constante por meses)"], note: "" }, diagnosis: { title: "Evaluación Médica", intro: "Para determinar la causa exacta, el médico puede solicitar:", items: ["Examen físico palpando distintas áreas del abdomen", "Análisis de sangre, orina o heces", "Pruebas de imagen (Ecografía, Radiografía, TC o RM)", "Endoscopia o colonoscopia"], note: "Conocer si el dolor empezó de repente o gradualmente es clave." }, treatment: { title: "Manejo", intro: "Depende totalmente de la enfermedad subyacente:", subsections: [ { title: "Opciones Generales", items: ["Ayuno temporal y líquidos claros para reposo intestinal", "Medicamentos antiácidos, antiespasmódicos o antibióticos", "Cirugía (en casos de apendicitis, hernias obstruidas o cálculos biliares)"] } ], note: "No se deben tomar analgésicos fuertes sin prescripción, ya que pueden enmascarar síntomas graves." }, whenToSeekHelp: { title: "¿Cuándo ir a emergencias?", intro: "Busca atención médica de inmediato si:", items: ["El dolor es súbito, muy intenso o empeora al tocar el abdomen", "Viene acompañado de vómitos con sangre o heces negras", "No puedes retener líquidos por más de 24 horas", "El abdomen se siente duro, rígido e inflamado"] } },
'Miopía' : { intro: "La miopía es un problema de refracción muy común en el que se ven claramente los objetos cercanos, pero los objetos lejanos se ven borrosos. Suele presentarse en la infancia o adolescencia y estabilizarse en la adultez joven.", whatIs: { title: "¿Qué es la Miopía?", text: "Ocurre cuando la forma del ojo (demasiado largo) o la curva de la córnea (demasiado curva) hacen que los rayos de luz se enfoquen incorrectamente delante de la retina, en lugar de directamente sobre ella, desenfocando la visión lejana." }, types: { title: "Grados de Severidad", intro: "Se mide en dioptrías y se clasifica en:", items: ["Miopía leve (hasta -3.00 dioptrías)", "Miopía moderada (de -3.00 a -6.00 dioptrías)", "Miopía alta o magna (más de -6.00 dioptrías, aumenta el riesgo de problemas graves como desprendimiento de retina)"], note: "Suele tener un fuerte componente genético familiar." }, diagnosis: { title: "Examen Visual", intro: "Se detecta mediante un examen ocular de rutina:", items: ["Prueba de agudeza visual (leer letras en una tabla a distancia)", "Prueba de refracción usando un foróptero para encontrar la graduación exacta", "Examen de la salud ocular general con pupila dilatada"], note: "" }, treatment: { title: "Corrección Óptica", intro: "El objetivo es compensar el enfoque de la luz:", subsections: [ { title: "Métodos", items: ["Anteojos recetados (el método más seguro y sencillo)", "Lentes de contacto", "Cirugía refractiva láser (LASIK, PRK, SMILE) para remodelar la córnea", "Lentes intraoculares (para miopía extrema)"] } ], note: "En niños, existen tratamientos para ralentizar la progresión (como gotas de atropina o lentes especiales)." }, whenToSeekHelp: { title: "¿Cuándo consultar al oftalmólogo?", intro: "Solicita un examen si experimentas:", items: ["Dificultad para leer señales de tránsito o la pizarra en la escuela", "Entrecerrar los ojos constantemente para ver de lejos", "Aparición repentina de destellos de luz, manchas flotantes o una 'cortina' sobre la visión (urgencia)"] } },
'Osteoporosis' : { intro: "La osteoporosis es una enfermedad que hace que los huesos se debiliten y se vuelvan frágiles, tanto que una caída o incluso una leve tensión, como agacharse o toser, pueden causar una fractura.", whatIs: { title: "¿Qué es la Osteoporosis?", text: "Es una enfermedad del metabolismo óseo en la que el cuerpo pierde demasiada masa ósea, produce muy poco hueso nuevo o ambas cosas. Como resultado, los huesos pierden densidad y desarrollan grandes 'agujeros' en su estructura interna tipo panal." }, types: { title: "Clasificación", intro: "Se divide médicamente en:", items: ["Osteoporosis primaria (relacionada con la menopausia o el envejecimiento general)", "Osteoporosis secundaria (causada por otras enfermedades, como problemas de tiroides, o medicamentos como los corticosteroides)", "Osteopenia (una densidad ósea baja que aún no es lo suficientemente grave para ser osteoporosis)"], note: "Se le conoce como la 'enfermedad silenciosa' porque no presenta síntomas hasta que se rompe un hueso." }, diagnosis: { title: "Detección", intro: "La densidad ósea se mide para confirmar la enfermedad:", items: ["Densitometría ósea (DEXA), una radiografía de baja dosis para medir minerales en los huesos (generalmente columna y cadera)", "Análisis de sangre y orina (para detectar condiciones que causen la pérdida ósea)"], note: "Se recomienda para todas las mujeres mayores de 65 años o antes si hay factores de riesgo." }, treatment: { title: "Tratamiento y Prevención", intro: "Se enfoca en detener la pérdida ósea y prevenir fracturas:", subsections: [ { title: "Estrategias", items: ["Medicamentos bifosfonatos (alendronato, risedronato)", "Terapias hormonales o moduladores de estrógenos", "Medicamentos constructores de hueso (teriparatida) en casos graves", "Suplementación con calcio y vitamina D", "Ejercicio regular de soporte de peso y equilibrio"] } ], note: "Prevenir las caídas en el hogar es una parte crítica del manejo de la osteoporosis." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación si:", items: ["Has sufrido una fractura por un golpe leve o caída desde tu propia altura", "Notas una pérdida progresiva de estatura o una postura encorvada (cifosis)", "Pasaste por una menopausia temprana o tomas corticosteroides desde hace meses"] } },
'Diente retenido' : { intro: "Un diente retenido, también llamado impactado, es aquel que no puede salir a través de la encía para ocupar su posición normal en la arcada dental durante su periodo normal de erupción. Ocurre con mucha frecuencia con las 'muelas del juicio' o terceros molares.", whatIs: { title: "¿Qué es un Diente Retenido?", text: "Es un diente que permanece total o parcialmente bloqueado bajo la encía o en el hueso maxilar. Esto se debe a menudo a la falta de espacio en la boca, una alineación incorrecta o tejido grueso que bloquea su salida." }, types: { title: "Posiciones Comunes", intro: "Además de las muelas del juicio, afecta frecuentemente a los caninos superiores. Pueden estar:", items: ["Retención de tejidos blandos (ha atravesado el hueso pero no la encía)", "Retención ósea parcial (ha salido parcialmente del hueso)", "Retención ósea total (está completamente encerrado en el hueso mandibular)"], note: "Un diente parcialmente erupcionado puede atrapar comida y bacterias, causando dolor e infección (pericoronaritis)." }, diagnosis: { title: "Evaluación Dental", intro: "El diagnóstico se basa en la observación y pruebas de imagen:", items: ["Examen intraoral visualizando el espacio o el diente a medio salir", "Radiografía panorámica (muestra todos los dientes y huesos faciales para ubicar el diente impactado y sus raíces)", "Tomografía Cone Beam 3D (para ver la cercanía del diente a los nervios)"], note: "" }, treatment: { title: "Procedimientos", intro: "Si causa problemas, requiere intervención:", subsections: [ { title: "Tratamientos", items: ["Extracción quirúrgica (la solución más común para las muelas del juicio)", "Tratamiento de ortodoncia (para 'jalar' el diente a su lugar, usado comúnmente en caninos retenidos)", "Vigilancia clínica (si el diente no causa síntomas y no afecta a los vecinos)"] } ], note: "Las extracciones son más fáciles en jóvenes antes de que las raíces estén completamente formadas." }, whenToSeekHelp: { title: "¿Cuándo acudir al cirujano maxilofacial?", intro: "Debes buscar ayuda si presentas:", items: ["Dolor palpitante e inflamación en la parte posterior de las encías", "Mal sabor de boca persistente o dificultad para abrir la boca", "Apiñamiento en tus dientes delanteros (los dientes retenidos pueden empujar a los demás)"] } },
'Lesión de Ligamentarias de Rodilla' : { intro: "Las lesiones de los ligamentos de la rodilla son desgarros o estiramientos excesivos de las bandas de tejido resistente que conectan los huesos del muslo con los de la parte inferior de la pierna. Son sumamente comunes en deportes que requieren paradas repentinas o cambios de dirección.", whatIs: { title: "¿Qué es una Lesión Ligamentaria?", text: "Es un esguince o rotura de uno o más de los cuatro ligamentos principales de la rodilla que mantienen la estabilidad de la articulación: LCA, LCP, LLI o LLE." }, types: { title: "Ligamentos Afectados", intro: "Las lesiones se clasifican según el ligamento dañado:", items: ["Rotura del Ligamento Cruzado Anterior (LCA) (muy común en fútbol o baloncesto, a menudo con un sonido de 'pop')", "Lesión del Ligamento Colateral Medial (LCM) (por golpes en la parte externa de la rodilla)", "Lesión del Ligamento Cruzado Posterior (LCP) (suele ocurrir en accidentes de tráfico)", "Lesiones multiligamentarias (rotura de varios ligamentos a la vez)"], note: "Los desgarros pueden ser parciales o completos." }, diagnosis: { title: "Diagnóstico", intro: "El especialista en traumatología realizará:", items: ["Examen físico con maniobras de estrés (como la prueba de Lachman) para comprobar la laxitud de la articulación", "Radiografías (para descartar fracturas óseas asociadas)", "Resonancia magnética (RM) (el estándar de oro para ver claramente el tejido de los ligamentos)"], note: "" }, treatment: { title: "Manejo y Rehabilitación", intro: "Depende del ligamento afectado, la gravedad y la actividad del paciente:", subsections: [ { title: "Enfoques", items: ["Protocolo RICE (Reposo, Hielo, Compresión, Elevación) y uso de rodilleras ortopédicas", "Fisioterapia intensiva (suficiente para muchos desgarros parciales o lesiones del LCM)", "Cirugía de reconstrucción ligamentaria (para roturas completas, especialmente del LCA en personas activas)"] } ], note: "La cirugía suele utilizar un injerto de tendón para reemplazar el ligamento roto." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Debes buscar atención médica inmediata si:", items: ["Escuchaste o sentiste un chasquido fuerte en la rodilla en el momento de la lesión", "La rodilla se hinchó de forma masiva en las primeras 2 horas", "Sientes que la rodilla 'cede' o es incapaz de soportar tu peso"] } },
'Contractura cervical' : { intro: "Una contractura cervical es una contracción involuntaria, continua y dolorosa de uno o varios músculos de la región del cuello (cervical). Provoca que los músculos se sientan rígidos, tensos y limiten considerablemente la movilidad de la cabeza.", whatIs: { title: "¿Qué es la Contractura Cervical?", text: "Es una sobrecarga muscular en la que el músculo se acorta y aumenta su tono de forma patológica. El flujo de sangre disminuye en la zona tensa, acumulando toxinas que causan dolor y creando un ciclo de dolor-espasmo." }, types: { title: "Causas Frecuentes", intro: "Suele estar originada por factores posturales o tensionales:", items: ["Posturales (pasar muchas horas frente al ordenador, dormir en mala posición, uso del móvil con el cuello flexionado)", "Traumáticas (latigazo cervical tras un accidente de tráfico)", "Por estrés o tensión emocional (la ansiedad se acumula en hombros y cuello)"], note: "A menudo afecta los músculos trapecios, esternocleidomastoideos o elevadores de la escápula." }, diagnosis: { title: "Evaluación", intro: "Se diagnostica fundamentalmente mediante exploración clínica:", items: ["Palpación de la musculatura buscando 'nudos' o bandas tensas dolorosas", "Evaluación del rango de movimiento activo y pasivo del cuello", "Radiografías o RM solo si se sospecha de un problema subyacente en la columna (hernia o artrosis)"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es relajar el músculo y romper el ciclo de dolor:", subsections: [ { title: "Terapias", items: ["Fisioterapia (masoterapia, punción seca, termoterapia)", "Estiramientos suaves y corrección postural", "Medicamentos (relajantes musculares y AINEs por corto tiempo)", "Aplicación de calor local en la zona afectada"] } ], note: "Mantener una buena ergonomía en el trabajo previene recaídas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes acudir a un profesional si la contractura:", items: ["Se acompaña de dolor que se irradia por el brazo con hormigueo en los dedos", "No mejora después de una semana de cuidados caseros", "Viene acompañada de mareos intensos, vértigo o dolor de cabeza severo"] } },
'Lesiones de cartílago articular' : { intro: "Las lesiones de cartílago articular involucran daños al tejido liso, blanco y resistente que recubre los extremos de los huesos donde se unen para formar una articulación. Este daño reduce la capacidad de la articulación para deslizarse suavemente.", whatIs: { title: "¿Qué son las Lesiones de Cartílago?", text: "Son defectos o fisuras en el tejido cartilaginoso. Debido a que el cartílago no tiene suministro de sangre propio (es avascular), no se puede curar a sí mismo de manera efectiva cuando se lesiona o desgarra." }, types: { title: "Grados de Lesión", intro: "El daño se evalúa desde un ablandamiento hasta una rotura completa:", items: ["Grado I (cartílago ablandado y con ampollas)", "Grado II (fisuras o desgarros superficiales)", "Grado III (fisuras profundas que casi llegan al hueso)", "Grado IV (el cartílago se ha desgastado completamente, dejando el hueso expuesto)"], note: "Si no se trata, el daño progresa hacia la artrosis prematura." }, diagnosis: { title: "Detección", intro: "Es difícil de ver en pruebas estándar; se utiliza:", items: ["Resonancia Magnética (RM) (el mejor examen no invasivo para ver el cartílago)", "Artroscopia (introducir una cámara en la articulación para ver directamente la lesión y, a menudo, tratarla al mismo tiempo)", "Examen físico para buscar derrame articular (líquido) o 'bloqueos' en la rodilla"], note: "Las radiografías normales no muestran el cartílago, solo el espacio entre huesos." }, treatment: { title: "Opciones Quirúrgicas y Conservadoras", intro: "El manejo busca aliviar síntomas y restaurar la superficie:", subsections: [ { title: "Tratamientos", items: ["Fisioterapia, pérdida de peso e inyecciones de ácido hialurónico (para lesiones leves)", "Desbridamiento artroscópico (limpiar los bordes deshilachados)", "Microfracturas (perforar el hueso para promover un coágulo de sangre que forme fibrocartílago)", "Trasplante de cartílago o implantes de condrocitos (para lesiones grandes en pacientes jóvenes)"] } ], note: "La decisión depende de la edad, la actividad del paciente y el tamaño del defecto." }, whenToSeekHelp: { title: "¿Cuándo consultar al traumatólogo?", intro: "Es importante buscar evaluación si:", items: ["Tu articulación se traba o 'bloquea' durante el movimiento", "Sientes ruidos de crujidos dolorosos acompañados de hinchazón constante", "La rodilla o articulación afectada 'cede' y no puede soportar peso con confianza"] } },
'Anorexia nerviosa' : { intro: "La anorexia nerviosa es un trastorno de la conducta alimentaria que se caracteriza por un peso corporal anormalmente bajo, un temor intenso a aumentar de peso y una percepción distorsionada de la forma y el peso corporal.", whatIs: { title: "¿Qué es la Anorexia Nerviosa?", text: "Es una enfermedad mental grave, no un simple estilo de vida o dieta. Las personas con anorexia controlan severamente la cantidad de comida o calorías que consumen, a menudo haciendo ejercicio excesivo, usando laxantes o vomitando, poniendo su vida en riesgo mortal." }, types: { title: "Subtipos", intro: "Existen dos patrones principales de comportamiento:", items: ["Tipo restrictivo (la pérdida de peso se logra mediante dietas, ayunos o ejercicio excesivo sin atracones ni purgas)", "Tipo con atracones/purgas (se presentan episodios de ingesta excesiva seguidos de vómitos autoinducidos o uso indebido de laxantes o diuréticos)"], note: "El paciente niega sistemáticamente la gravedad de su bajo peso corporal actual." }, diagnosis: { title: "Evaluación Médica y Psicológica", intro: "Un diagnóstico completo requiere:", items: ["Evaluación física para comprobar signos de desnutrición (presión baja, lanugo corporal, osteoporosis)", "Análisis de laboratorio (electrolitos, función hepática y renal, alteraciones hormonales)", "Evaluación psicológica extensa basada en criterios del DSM-5"], note: "Se diagnostica cuando el IMC está significativamente por debajo de lo esperado." }, treatment: { title: "Recuperación Integral", intro: "Requiere un equipo de especialistas (psiquiatra, psicólogo, nutricionista):", subsections: [ { title: "Intervenciones", items: ["Restauración del peso nutricional bajo supervisión médica", "Psicoterapia (Terapia Familiar para adolescentes, Terapia Cognitivo-Conductual)", "Medicamentos psiquiátricos (para tratar la depresión o ansiedad coexistentes)", "Hospitalización (en casos de desnutrición severa o riesgo de paro cardíaco)"] } ], note: "La recuperación es un proceso a largo plazo con riesgo de recaídas." }, whenToSeekHelp: { title: "¿Cuándo intervenir?", intro: "El entorno familiar debe actuar si observa:", items: ["Pérdida de peso rápida y extrema, excusas frecuentes para no comer y saltarse comidas", "Rituales obsesivos con la comida (pesar todo, cortar en trozos minúsculos)", "Miedo pánico injustificado a engordar a pesar de estar claramente demacrado"] } },
'Asma pediátrico' : { intro: "El asma pediátrico es la misma enfermedad de las vías respiratorias que sufren los adultos (inflamación y estrechamiento), pero los niños enfrentan desafíos únicos debido a que sus vías respiratorias son más pequeñas y están en desarrollo.", whatIs: { title: "¿Qué es el Asma en Niños?", text: "Es una enfermedad pulmonar crónica que causa episodios repetidos de sibilancias (silbidos en el pecho), tos persistente (especialmente de noche o al hacer ejercicio), opresión en el pecho y dificultad para respirar." }, types: { title: "Desencadenantes Comunes", intro: "Los ataques en niños suelen ser provocados por:", items: ["Infecciones virales (resfriados, el desencadenante más común en niños pequeños)", "Alergias (polen, ácaros del polvo, pelo de mascotas)", "Ejercicio físico o juego vigoroso", "Cambios climáticos o exposición al aire frío"], note: "Es la causa principal de ausentismo escolar y visitas a urgencias en la infancia." }, diagnosis: { title: "Detección", intro: "Puede ser difícil de diagnosticar en niños menores de 5 años:", items: ["Historial médico detallado y antecedentes familiares de alergias", "Espirometría (pruebas de función pulmonar, generalmente realizables solo en niños mayores de 5-6 años)", "Pruebas de alergia cutánea o en sangre"], note: "A veces se diagnostica en base a si los síntomas mejoran al administrar medicación para el asma." }, treatment: { title: "Manejo y Medicación", intro: "Se requiere un 'Plan de Acción contra el Asma' personalizado:", subsections: [ { title: "Medicamentos", items: ["Medicamentos de control diario (corticosteroides inhalados en dosis bajas para prevenir inflamación)", "Medicamentos de rescate (broncodilatadores como salbutamol para alivio rápido durante una crisis)", "Uso de cámara espaciadora con mascarilla (esencial para que el niño inhale el medicamento correctamente)"] } ], note: "La educación de padres y maestros sobre el plan de acción es vital." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Lleva a tu hijo al médico inmediatamente si presenta:", items: ["Respiración muy rápida con hundimiento de la piel entre las costillas o encima del esternón (tiraje)", "Fosas nasales que se ensanchan al respirar o labios/uñas azulados", "Sibilancias graves que no mejoran después de usar el inhalador de rescate"] } },
'Trastornos de la articulación temporomandibular' : { intro: "Los trastornos de la articulación temporomandibular (ATM) son un grupo de más de 30 afecciones que causan dolor y disfunción en la articulación de la mandíbula y en los músculos que controlan su movimiento.", whatIs: { title: "¿Qué son los trastornos de la ATM?", text: "Son problemas relacionados con la articulación 'bisagra' que conecta la mandíbula inferior con el cráneo. Pueden causar dolor crónico facial, dificultad para masticar y ruidos articulares molestos como chasquidos o estallidos." }, types: { title: "Categorías", intro: "Se dividen principalmente en tres grupos:", items: ["Trastornos musculares (dolor miofascial en los músculos de la masticación)", "Trastornos de la alteración del complejo articular (disco desplazado, dislocación de la mandíbula)", "Trastornos inflamatorios o degenerativos (osteoartritis o artritis reumatoide en la ATM)"], note: "Frecuentemente se asocian al bruxismo (apretar o rechinar los dientes)." }, diagnosis: { title: "Evaluación Odontológica", intro: "El dentista o especialista maxilofacial buscará:", items: ["Examen del rango de apertura mandibular y palpación de la musculatura facial", "Escuchar ruidos articulares durante el movimiento", "Radiografías panorámicas, Tomografía o Resonancia Magnética para ver la posición del disco y el estado del cartílago"], note: "" }, treatment: { title: "Opciones de Manejo", intro: "Suele comenzarse con tratamientos reversibles y conservadores:", subsections: [ { title: "Tratamientos", items: ["Uso de férulas oclusales o protectores bucales (guardas de relajación)", "Fisioterapia mandibular, aplicación de calor/hielo y dieta blanda", "Medicamentos (relajantes musculares, antiinflamatorios)", "Cirugía artroscópica o abierta de ATM (solo en casos graves con daño estructural que no responden a lo anterior)"] } ], note: "La cirugía es el último recurso; la mayoría mejora con cuidados conservadores." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Es recomendable buscar atención si:", items: ["Tienes dolor constante o sensibilidad crónica en la mandíbula, cara o cuello", "No puedes abrir o cerrar la boca completamente ('mandíbula trabada')", "Escuchas un chasquido al masticar que viene acompañado de dolor agudo"] } },
'Lesiones de Menisco' : { intro: "Las lesiones de menisco son roturas o desgarros de uno de los dos discos de cartílago en forma de C (meniscos) que amortiguan la articulación de la rodilla entre el fémur y la tibia. Son de las lesiones de rodilla más comunes.", whatIs: { title: "¿Qué es un Desgarro de Menisco?", text: "Es el daño a los 'amortiguadores' de la rodilla. Ocurre típicamente por girar o torcer la rodilla con fuerza mientras el pie está plantado en el suelo, pero también puede ser resultado de degeneración por envejecimiento." }, types: { title: "Tipos de Rotura", intro: "Se describen según su forma y ubicación:", items: ["Desgarro longitudinal", "Desgarro en 'asa de balde' (una sección se pliega sobre sí misma, trabando la rodilla)", "Desgarro radial o de pico de loro", "Desgarros degenerativos complejos (bordes deshilachados en cartílago viejo)"], note: "El potencial de curación depende de si el desgarro está en la zona vascularizada ('zona roja') del menisco." }, diagnosis: { title: "Examen Físico y Pruebas", intro: "El traumatólogo evaluará la rodilla mediante:", items: ["Prueba de McMurray y palpación de la línea articular en busca de dolor y clics", "Resonancia Magnética (RM) (la prueba definitiva para visualizar el cartílago roto)", "Radiografías (para descartar artrosis u otras patologías óseas asociadas)"], note: "" }, treatment: { title: "Enfoque Terapéutico", intro: "El tratamiento depende del tipo, tamaño y ubicación del desgarro:", subsections: [ { title: "Intervenciones", items: ["Reposo, hielo y fisioterapia (para desgarros pequeños y degenerativos)", "Cirugía artroscópica (meniscectomía parcial) para recortar la zona rota y aliviar el bloqueo", "Reparación meniscal con suturas (ideal en jóvenes con roturas en la 'zona roja' para preservar el menisco)"] } ], note: "Preservar el menisco es la prioridad para prevenir artrosis futura en la rodilla." }, whenToSeekHelp: { title: "¿Cuándo es urgente?", intro: "Acude a un traumatólogo sin demora si:", items: ["Tu rodilla se 'bloquea' o se traba y no puedes enderezarla completamente", "Sientes que la rodilla cede bruscamente y te hace perder el equilibrio", "Se produce una hinchazón repentina y severa tras un giro brusco de la pierna"] } },
'Luto' : { intro: "El luto (o duelo) es la respuesta natural a la pérdida de alguien o algo importante. Es el proceso emocional, cognitivo, físico y espiritual que las personas atraviesan tras una muerte, una ruptura o cualquier pérdida profunda.", whatIs: { title: "¿Qué es el Luto?", text: "Es un periodo de adaptación que involucra una serie de fases o tareas. No es un estado patológico, sino una experiencia humana universal que se manifiesta con tristeza intensa, añoranza, desorientación y a menudo síntomas físicos." }, types: { title: "Formas de presentación", intro: "El proceso puede variar en cada persona:", items: ["Luto normal o anticipado (reacciones esperables que se atenúan con los meses)", "Luto complicado o Trastorno de Duelo Prolongado (el dolor es tan paralizante e intenso que la persona no puede reanudar su vida tras más de un año)", "Luto desautorizado (cuando la sociedad no reconoce o minimiza la pérdida)"], note: "No existe un cronograma rígido ni una forma 'correcta' de vivir el duelo." }, diagnosis: { title: "Evaluación", intro: "No es una enfermedad a diagnosticar salvo que se complique:", items: ["Evaluación clínica psiquiátrica solo si se sospecha de Trastorno de Duelo Prolongado o Depresión Mayor concomitante", "Análisis del impacto en el funcionamiento diario e ideas suicidas asociadas"], note: "" }, treatment: { title: "Apoyo y Manejo", intro: "El luto no se 'cura', se integra:", subsections: [ { title: "Estrategias de Apoyo", items: ["Acompañamiento empático y validación emocional", "Grupos de apoyo de duelo", "Psicoterapia (Terapia de Duelo o Terapia Cognitivo-Conductual para trabajar bloqueos)", "Medicación solo para síntomas transitorios severos de insomnio o ansiedad extrema"] } ], note: "Hablar de la persona fallecida y expresar la tristeza es parte de la recuperación sana." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda profesional?", intro: "Es recomendable acudir a terapia si:", items: ["Sientes una culpa intensa por cosas ajenas a la pérdida o deseas la muerte para reunirte con el fallecido", "El dolor agudo no disminuye o empeora después de muchos meses", "Te aíslas completamente y no puedes cuidar de ti mismo o de tus dependientes"] } },
'Dermatitis atópica' : { intro: "La dermatitis atópica, la forma más común de eccema, es una afección que hace que la piel se enrojezca y pique. Es común en niños pero puede manifestarse a cualquier edad. Es crónica y suele exacerbarse periódicamente.", whatIs: { title: "¿Qué es la Dermatitis Atópica?", text: "Es una inflamación crónica de la piel relacionada con una variación genética que afecta la capacidad de la piel de proporcionar protección (barrera cutánea). Esto permite que la humedad salga y que bacterias y alérgenos entren, causando resequedad extrema, picazón y erupciones." }, types: { title: "Asociaciones Comunes", intro: "A menudo forma parte de la 'marcha atópica':", items: ["Acompañada frecuentemente de asma", "Acompañada de rinitis alérgica o alergias alimentarias"], note: "El estrés, los jabones fuertes y la sudoración pueden desencadenar brotes graves." }, diagnosis: { title: "Diagnóstico Clínico", intro: "No existen pruebas de laboratorio definitivas; se basa en:", items: ["Examen visual de la piel (zonas típicas como pliegues de codos y rodillas en niños mayores y adultos; cara y cuero cabelludo en bebés)", "Historial familiar de atopias (asma, eccema, fiebre del heno)", "Pruebas de parches o alergias solo para descartar otros desencadenantes de contacto"], note: "" }, treatment: { title: "Cuidado de la Piel y Control", intro: "El tratamiento se enfoca en restaurar la barrera cutánea y aliviar la picazón:", subsections: [ { title: "Medidas Terapéuticas", items: ["Hidratación intensiva diaria con emolientes y cremas espesas (sin perfume)", "Corticosteroides tópicos para controlar la inflamación durante los brotes", "Inhibidores de la calcineurina o terapias biológicas (Dupilumab) para casos moderados a severos", "Evitar baños calientes prolongados y usar jabones suaves (syndet)"] } ], note: "Rascarse empeora la condición y puede provocar infecciones bacterianas (impétigo)." }, whenToSeekHelp: { title: "¿Cuándo ir al dermatólogo?", intro: "Programa una visita si:", items: ["La afección afecta el sueño y las actividades diarias", "Las erupciones exudan pus, forman costras amarillas o hay vetas rojas (signo de infección)", "Los síntomas persisten a pesar de los cuidados e hidratación intensiva en el hogar"] } },
'Astigmatismo' : { intro: "El astigmatismo es una imperfección común y generalmente tratable en la curvatura del ojo que causa visión borrosa a todas las distancias, tanto de cerca como de lejos.", whatIs: { title: "¿Qué es el Astigmatismo?", text: "Ocurre cuando la superficie frontal del ojo (córnea) o el cristalino en el interior del ojo tienen curvas irregulares, como la forma de un balón de fútbol americano en lugar de ser redondos como una pelota de baloncesto. Esto distorsiona la forma en que la luz entra a la retina." }, types: { title: "Clasificación", intro: "Dependiendo de la estructura afectada:", items: ["Astigmatismo corneal (la córnea tiene una forma irregular)", "Astigmatismo lenticular (la forma del cristalino está distorsionada)", "Astigmatismo regular (los meridianos principales están a 90 grados entre sí)", "Astigmatismo irregular (los meridianos no son perpendiculares, a menudo causado por queratocono o cicatrices)"], note: "Frecuentemente se presenta junto con miopía o hipermetropía." }, diagnosis: { title: "Examen de la Vista", intro: "El oftalmólogo u optometrista lo detecta mediante:", items: ["Prueba de agudeza visual clásica", "Queratometría (para medir la curvatura de la córnea)", "Topografía corneal (mapa de la superficie del ojo, esencial para astigmatismo irregular)"], note: "" }, treatment: { title: "Opciones de Corrección", intro: "El objetivo es corregir la curvatura irregular causante del desenfoque:", subsections: [ { title: "Correcciones", items: ["Anteojos con lentes cilíndricos recetados", "Lentes de contacto tóricos (diseñados específicamente para astigmatismo)", "Cirugía refractiva (LASIK, PRK) para remodelar la córnea permanentemente", "Cirugía de cataratas con lente intraocular tórico (si hay cataratas presentes)"] } ], note: "Sin corrección, puede causar dolores de cabeza crónicos y fatiga visual severa." }, whenToSeekHelp: { title: "¿Cuándo programar un examen?", intro: "Deberías acudir a revisión si:", items: ["Ves los bordes de los objetos y las luces difuminados, alargados o distorsionados a cualquier distancia", "Sufres de cansancio o fatiga ocular al leer o usar el ordenador", "Entrecierras constantemente los ojos para intentar enfocar"] } },
'Depresión grave' : { intro: "La depresión grave, o trastorno depresivo mayor, es una enfermedad médica que afecta el estado de ánimo, los sentimientos y el comportamiento. Provoca una profunda y persistente sensación de tristeza y pérdida de interés que interfiere con la capacidad de funcionar en la vida diaria.", whatIs: { title: "¿Qué es la Depresión Grave?", text: "Es más que sentirse triste por una mala racha; es una alteración clínica profunda del cerebro que afecta funciones físicas y mentales. Impide trabajar, dormir, estudiar, comer y disfrutar de los aspectos de la vida, pudiendo ser mortal si conduce al suicidio." }, types: { title: "Presentaciones Específicas", intro: "Puede acompañarse de especificadores:", items: ["Depresión con características psicóticas (presencia de delirios o alucinaciones)", "Depresión con patrón estacional (trastorno afectivo estacional)", "Depresión periparto (durante el embarazo o tras el parto)", "Depresión melancólica (falta total de respuesta a cosas placenteras y despertar temprano)"], note: "" }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "El diagnóstico es riguroso e incluye:", items: ["Cinco o más síntomas persistentes (tristeza profunda, falta de energía, alteraciones de peso/sueño, culpa inútil, ideas suicidas) durante al menos dos semanas seguidas", "Examen físico y de laboratorio para descartar problemas médicos (ej. tiroides)", "Uso de criterios estandarizados del manual DSM-5"], note: "" }, treatment: { title: "Tratamiento Integral", intro: "Es altamente tratable, generalmente mediante una combinación:", subsections: [ { title: "Enfoques Clínicos", items: ["Medicación antidepresiva (ISRS, IRSN, atípicos, que requieren semanas para hacer efecto)", "Psicoterapia (TCC, terapia interpersonal, psicoterapia analítica funcional)", "Terapia electroconvulsiva (TEC) o estimulación magnética transcraneal (en casos resistentes a fármacos)", "Ingreso hospitalario (si existe riesgo inminente de suicidio)"] } ], note: "La suspensión abrupta de antidepresivos puede causar síndrome de discontinuación." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Llama a un teléfono de prevención del suicidio o acude a urgencias si:", items: ["Tú o un familiar tienen pensamientos constantes sobre la muerte, el suicidio o hacen planes para autolesionarse", "Sientes que no vale la pena seguir viviendo y te has desprendido por completo de tu entorno", "Hay signos de psicosis y desconexión con la realidad"] } },
'Colecistitis crónica' : { intro: "La colecistitis crónica es la inflamación prolongada de la vesícula biliar, casi siempre causada por ataques repetidos de colecistitis aguda o por la presencia constante de cálculos biliares que irritan la pared del órgano con el tiempo.", whatIs: { title: "¿Qué es la Colecistitis Crónica?", text: "Es el engrosamiento, encogimiento y pérdida de la función de la pared de la vesícula biliar tras múltiples episodios de inflamación. La vesícula pierde su capacidad de almacenar y liberar bilis adecuadamente, volviéndose fibrótica." }, types: { title: "Complicaciones Asociadas", intro: "Puede evolucionar a condiciones más severas:", items: ["Vesícula en porcelana (calcificación completa de la pared, que aumenta el riesgo de cáncer de vesícula)", "Fístulas biliares (conexión anormal con otros órganos por inflamación continua)", "Pancreatitis biliar secundaria"], note: "Los síntomas suelen ser más leves y vagos que en un ataque agudo." }, diagnosis: { title: "Evaluación Médica", intro: "Se detecta mediante pruebas de imagen e historia clínica:", items: ["Ecografía abdominal (muestra pared de la vesícula engrosada y contraída, y cálculos)", "Historia de episodios repetidos de cólicos biliares", "Gammagrafía biliar (HIDA) para evaluar la función de vaciado de la vesícula"], note: "" }, treatment: { title: "Solución Definitiva", intro: "Dado que el órgano está dañado irreversiblemente, el tratamiento es quirúrgico:", subsections: [ { title: "Procedimientos", items: ["Colecistectomía laparoscópica (cirugía de elección para extirpar la vesícula afectada)", "Dieta baja en grasas como manejo temporal de síntomas antes de la cirugía", "Analgésicos y antiespasmódicos para el control del dolor"] } ], note: "Las personas pueden llevar una vida perfectamente normal sin vesícula biliar." }, whenToSeekHelp: { title: "¿Cuándo programar cirugía?", intro: "Consulta con el cirujano general si:", items: ["Padeces de indigestión, gases y dolor sordo en el lado derecho tras comidas grasosas de forma repetitiva", "Tienes antecedentes conocidos de cálculos biliares sintomáticos", "Un ataque de cólico biliar aumenta repentinamente de intensidad y no cede"] } },
'Hernia hiatal' : { intro: "Una hernia hiatal o de hiato ocurre cuando la parte superior del estómago protruye a través del músculo grande que separa el abdomen del tórax (diafragma), invadiendo la cavidad torácica.", whatIs: { title: "¿Qué es la Hernia Hiatal?", text: "Es una anomalía anatómica en la que el hiato diafragmático (el orificio por donde el esófago atraviesa el diafragma para unirse al estómago) se agranda. Esto permite que el estómago suba hacia el tórax, facilitando el reflujo gástrico severo." }, types: { title: "Clasificación Anatómica", intro: "Existen dos tipos principales:", items: ["Hernia hiatal por deslizamiento (Tipo I, la más común; el estómago y la unión esofagogástrica se deslizan hacia arriba y abajo del tórax)", "Hernia hiatal paraesofágica (Tipo II a IV; una porción del estómago pasa al tórax junto al esófago y queda atrapada)"], note: "Las hernias paraesofágicas son menos comunes pero más peligrosas por el riesgo de estrangulación del estómago." }, diagnosis: { title: "Pruebas de Diagnóstico", intro: "A menudo se descubre al buscar la causa del reflujo (ERGE):", items: ["Endoscopia digestiva alta (permite visualizar la unión del estómago y el esófago)", "Tránsito esofagogastroduodenal (radiografía con contraste de bario que delinea el estómago en el tórax)", "Manometría esofágica"], note: "" }, treatment: { title: "Manejo y Cirugía", intro: "Muchas hernias hiatales pequeñas no causan problemas y no necesitan tratamiento:", subsections: [ { title: "Tratamientos", items: ["Medicación para controlar la acidez (Inhibidores de la Bomba de Protones) y cambios en la dieta", "Pérdida de peso (reduce la presión abdominal)", "Cirugía (funduplicatura de Nissen por laparoscopia) para tirar del estómago hacia abajo y estrechar el diafragma en casos grandes o con síntomas graves"] } ], note: "Evitar acostarse inmediatamente después de comer ayuda a controlar los síntomas." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Acude al médico de inmediato si:", items: ["Experimentas dolor de pecho severo que puede confundirse con un ataque cardíaco", "Tienes dificultad extrema para tragar o vomitas sangre", "Sufres de acidez estomacal crónica que los medicamentos no logran aliviar"] } },
'Faringitis bacteriana' : { intro: "La faringitis bacteriana, comúnmente conocida como infección por estreptococo, es una infección dolorosa de la garganta y las amígdalas causada por bacterias, que requiere tratamiento antibiótico para prevenir complicaciones graves.", whatIs: { title: "¿Qué es la Faringitis Bacteriana?", text: "Es la inflamación aguda de la faringe causada casi siempre por la bacteria Streptococcus pyogenes (estreptococo del grupo A). A diferencia de los dolores de garganta virales, aparece de forma muy repentina y severa." }, types: { title: "Complicaciones Posibles", intro: "Si no se trata con antibióticos, la infección puede causar enfermedades graves secundarias:", items: ["Fiebre reumática (puede dañar el corazón y las articulaciones permanentemente)", "Glomerulonefritis posestreptocócica (inflamación aguda de los riñones)", "Absceso periamigdalino (acumulación de pus detrás de las amígdalas)", "Fiebre escarlatina (erupción roja en todo el cuerpo)"], note: "Es más frecuente en niños en edad escolar y adolescentes." }, diagnosis: { title: "Pruebas Confirmatorias", intro: "Es imprescindible diferenciarla de causas virales antes de medicar:", items: ["Examen físico: se buscan amígdalas rojas, hinchadas, a veces con placas de pus blancas, y ganglios del cuello inflamados", "Prueba rápida de detección de antígenos estreptocócicos (frotis faríngeo)", "Cultivo de garganta (prueba definitiva que tarda 24-48 horas)"], note: "Generalmente NO presenta síntomas de resfriado como tos, secreción nasal o conjuntivitis." }, treatment: { title: "Terapia Antibiótica", intro: "El tratamiento es rápido y altamente eficaz:", subsections: [ { title: "Tratamientos", items: ["Antibióticos orales (penicilina o amoxicilina son los de primera elección durante 10 días)", "Analgésicos y antipiréticos (paracetamol, ibuprofeno) para el dolor y la fiebre", "Reposo, aumento de líquidos y alimentos suaves fríos o tibios"] } ], note: "Es vital completar todo el ciclo de antibióticos, incluso si los síntomas desaparecen a los dos días." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Solicita consulta médica si hay:", items: ["Dolor de garganta súbito y muy doloroso, acompañado de fiebre alta", "Dificultad o dolor extremo al tragar, o babear en el caso de niños pequeños", "Manchas rojas pequeñas en el paladar blando o placas blancas de pus en las amígdalas"] } },
'Sensibilidad dentaria' : { intro: "La sensibilidad dentaria o hipersensibilidad dentinaria es un dolor dental agudo, breve y transitorio que ocurre como respuesta a estímulos térmicos, táctiles, químicos u osmóticos que normalmente no deberían causar dolor.", whatIs: { title: "¿Qué es la Sensibilidad Dentaria?", text: "Es el dolor repentino causado por la exposición de la dentina (la capa interna porosa del diente que envuelve el nervio) al medio ambiente bucal. Esto sucede cuando el esmalte protector se desgasta o las encías se retraen, exponiendo la raíz del diente." }, types: { title: "Factores Desencadenantes", intro: "El dolor agudo suele ser provocado por la exposición a:", items: ["Alimentos y bebidas frías (el desencadenante más común) o calientes", "Alimentos o bebidas dulces o muy ácidas", "Cepillado dental vigoroso o el paso del aire frío al respirar por la boca"], note: "Afecta más frecuentemente a adultos entre 20 y 50 años." }, diagnosis: { title: "Diagnóstico Clínico", intro: "El odontólogo debe descartar primero otras patologías graves:", items: ["Examen visual buscando esmalte desgastado, recesión de encías, caries o fracturas dentales", "Aplicación de un chorro de aire frío o un explorador dental para localizar las áreas sensibles", "Radiografías (para descartar caries profundas o inflamación pulpar irreversible)"], note: "La sensibilidad no debe confundirse con el dolor prolongado de un nervio infectado." }, treatment: { title: "Soluciones de Desensibilización", intro: "Existen enfoques en casa y en consultorio:", subsections: [ { title: "Tratamientos", items: ["Uso de pasta dental desensibilizante (con nitrato de potasio) usada de forma continua", "Cepillado suave con cepillos de cerdas extra suaves", "Aplicación profesional de barnices de flúor o resinas desensibilizantes en el cuello del diente expuesto", "Injertos de encía (si la causa es una recesión gingival severa)"] } ], note: "Evitar alimentos excesivamente ácidos (limón, refrescos) ayuda a prevenir la pérdida de esmalte." }, whenToSeekHelp: { title: "¿Cuándo ver al dentista?", intro: "Es importante una revisión si:", items: ["El dolor de sensibilidad persiste mucho tiempo después de que se retira el estímulo (frío/calor)", "El dolor interfiere con la capacidad de comer o cepillarse los dientes adecuadamente", "El dolor se vuelve espontáneo, pulsátil y constante (indica daño al nervio)"] } },
'Bulimia nerviosa' : { intro: "La bulimia nerviosa es un trastorno de la alimentación grave y potencialmente fatal caracterizado por episodios secretos de atracones seguidos de métodos para evitar el aumento de peso, como el vómito autoinducido.", whatIs: { title: "¿Qué es la Bulimia Nerviosa?", text: "Es un trastorno psicológico y alimentario donde la persona ingiere grandes cantidades de comida en poco tiempo, sintiendo pérdida de control, para luego purgarse debido a la culpa y el miedo a engordar." }, types: { title: "Tipos de Comportamiento", intro: "Se divide principalmente en:", items: ["Purgativa (uso de vómitos, laxantes o diuréticos)", "No purgativa (uso de ayuno estricto o ejercicio excesivo para compensar)"], note: "El ciclo de atracón y purga puede ocurrir varias veces a la semana o al día." }, diagnosis: { title: "Diagnóstico", intro: "Un especialista evaluará:", items: ["Examen físico y dental (el ácido del estómago daña el esmalte)", "Análisis de sangre para detectar desequilibrios electrolíticos", "Evaluación psicológica según los criterios del DSM-5"], note: "Las personas con bulimia suelen tener un peso normal o ligero sobrepeso, lo que dificulta su detección." }, treatment: { title: "Tratamiento", intro: "Requiere un enfoque de equipo:", subsections: [ { title: "Opciones", items: ["Psicoterapia (Terapia Cognitivo-Conductual es la más efectiva)", "Antidepresivos (como la fluoxetina)", "Educación nutricional para establecer hábitos saludables"] } ], note: "El tratamiento temprano aumenta las posibilidades de recuperación a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es urgente buscar apoyo si:", items: ["Sientes que no puedes dejar de comer y luego te purgas", "Tienes mareos constantes, palpitaciones o dolor en el pecho", "Tu vida gira obsesivamente en torno a la comida y el peso"] } },
'Hernia umbilical' : { intro: "Una hernia umbilical ocurre cuando una parte del intestino o tejido graso sobresale a través de un punto débil en los músculos abdominales cerca del ombligo. Es muy común en bebés, pero también afecta a adultos.", whatIs: { title: "¿Qué es una Hernia Umbilical?", text: "Es un defecto en la pared abdominal a nivel del ombligo. En bebés, suele cerrarse solo, pero en adultos tiende a empeorar y puede requerir cirugía para evitar que el tejido quede atrapado." }, types: { title: "Clasificación", intro: "Según su estado:", items: ["Reductible (el bulto se puede empujar hacia adentro suavemente)", "Encarcelada (el tejido queda atrapado y no se puede reducir)", "Estrangulada (se corta el flujo sanguíneo al tejido atrapado, siendo una emergencia)"], note: "El riesgo de complicación es mayor en adultos que en niños." }, diagnosis: { title: "Diagnóstico", intro: "Se diagnostica principalmente mediante:", items: ["Examen físico (observación y palpación del bulto al toser o hacer esfuerzo)", "Ecografía o tomografía computarizada (en casos de sospecha de complicaciones)"], note: "A menudo el bulto es más visible cuando el paciente llora, tose o hace fuerza." }, treatment: { title: "Tratamiento", intro: "El manejo varía según la edad:", subsections: [ { title: "Intervenciones", items: ["Observación en bebés (la mayoría se cierra antes de los 4 años)", "Cirugía de reparación (herniorrafia) en adultos o en niños si es muy grande o no cierra", "Uso de mallas quirúrgicas para reforzar la pared abdominal en adultos"] } ], note: "No se recomiendan los vendajes o fajas caseras." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude al hospital inmediatamente si el bulto:", items: ["Se vuelve doloroso, firme, rojo o cambia de color", "No se puede empujar hacia adentro cuando estás acostado y relajado", "Se acompaña de vómitos, dolor abdominal intenso o fiebre"] } },
'Reflujo gastroesofágico en bebés' : { intro: "El reflujo gastroesofágico en bebés ocurre cuando el contenido del estómago retrocede hacia el esófago. Es muy común y, en la mayoría de los casos, es normal y el bebé lo supera con el tiempo sin complicaciones.", whatIs: { title: "¿Qué es?", text: "Es el retorno de leche o comida debido a que el esfínter esofágico inferior del bebé aún es inmaduro. Cuando causa síntomas molestos o impide el crecimiento, se denomina enfermedad por reflujo gastroesofágico (ERGE)." }, types: { title: "Presentación", intro: "Puede ser:", items: ["Reflujo fisiológico (el bebé escupe, pero está feliz y gana peso)", "ERGE infantil (causa llanto frecuente, rechazo al alimento y problemas respiratorios)"], note: "El reflujo fisiológico suele desaparecer entre los 12 y 18 meses de edad." }, diagnosis: { title: "Evaluación", intro: "El pediatra diagnostica basándose en:", items: ["Historia clínica y registro de crecimiento del bebé", "Examen físico", "En casos severos: ecografía, pH-metría esofágica o endoscopia"], note: "Las pruebas invasivas rara vez son necesarias." }, treatment: { title: "Manejo", intro: "Suele manejarse con cambios simples:", subsections: [ { title: "Estrategias", items: ["Mantener al bebé erguido durante y después de la alimentación", "Hacerlo eructar frecuentemente", "Espesar la fórmula o usar fórmulas especiales (bajo indicación médica)", "Medicamentos antiácidos (solo en casos de ERGE diagnosticado)"] } ], note: "No se debe cambiar la dieta ni dar medicación sin consultar al pediatra." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Consulta al pediatra si el bebé:", items: ["No gana peso adecuadamente", "Llora inconsolablemente o arquea la espalda al comer", "Vomita con fuerza (en escopetazo), o el vómito es verde, amarillo o con sangre"] } },
'Dermatitis del pañal' : { intro: "La dermatitis del pañal es una forma común de irritación de la piel (dermatitis) que aparece como manchas rojas en la zona de los glúteos del bebé. Generalmente está relacionada con pañales húmedos o que se cambian con poca frecuencia.", whatIs: { title: "¿Qué es?", text: "Es una erupción inflamatoria en la zona cubierta por el pañal. Puede ser causada por la fricción, la humedad prolongada, el contacto con orina y heces, o la introducción de nuevos alimentos." }, types: { title: "Causas comunes", intro: "La irritación puede complicarse por:", items: ["Irritación de contacto (la más frecuente)", "Infección por hongos (Candida albicans, suele verse roja brillante con bordes definidos)", "Infección bacteriana (impétigo)", "Alergias a toallitas, jabones o material del pañal"], note: "El ambiente cálido y húmedo es ideal para el crecimiento de hongos." }, diagnosis: { title: "Diagnóstico", intro: "El médico o pediatra diagnostica mediante:", items: ["Examen visual de la erupción en la zona del pañal", "Diferenciación entre irritación simple e infección por hongos o bacterias"], note: "Rara vez se necesitan análisis de laboratorio." }, treatment: { title: "Tratamiento", intro: "La clave es mantener la piel limpia y seca:", subsections: [ { title: "Medidas", items: ["Cambios frecuentes de pañal y limpieza suave con agua", "Dejar la zona al aire libre el mayor tiempo posible", "Cremas de barrera con óxido de zinc o vaselina", "Cremas antimicóticas o antibióticas (solo si hay infección confirmada)"] } ], note: "Evita usar talco para bebés, ya que puede irritar los pulmones si se inhala." }, whenToSeekHelp: { title: "¿Cuándo consultar?", intro: "Contacta al médico si:", items: ["La erupción empeora o no mejora después de unos días de tratamiento en casa", "Aparecen ampollas, granos con pus o úlceras abiertas", "El bebé tiene fiebre o parece tener mucho dolor"] } },
'Cólico infantil' : { intro: "El cólico infantil se define como episodios frecuentes, prolongados e intensos de llanto o irritabilidad en un bebé sano. Puede ser muy frustrante para los padres, pero suele alcanzar su punto máximo a las 6 semanas y disminuir notablemente a los 3-4 meses.", whatIs: { title: "¿Qué es el Cólico?", text: "Es una condición benigna y autolimitada descrita por la 'regla de tres': llanto durante más de tres horas al día, más de tres días a la semana, por más de tres semanas, en un bebé por lo demás sano y bien alimentado." }, types: { title: "Factores asociados", intro: "La causa exacta es desconocida, pero se relaciona con:", items: ["Sistema digestivo inmaduro (espasmos o gases)", "Sobrestimulación del entorno", "Alergias alimentarias transitorias o sensibilidad a la dieta de la madre"], note: "El llanto suele ocurrir a la misma hora todos los días, generalmente al final de la tarde o noche." }, diagnosis: { title: "Evaluación", intro: "Es un diagnóstico de exclusión:", items: ["El pediatra realizará un examen físico para descartar otras causas de llanto (infecciones, hernias, reflujo)", "Se evaluará el patrón de crecimiento y alimentación del bebé"], note: "No existen pruebas de laboratorio para diagnosticar el cólico." }, treatment: { title: "Manejo", intro: "El enfoque principal es calmar al bebé y apoyar a los padres:", subsections: [ { title: "Estrategias de consuelo", items: ["Envolver al bebé de forma segura (swaddling)", "Movimiento suave (mecedoras, paseos en coche)", "Ruido blanco o masajes abdominales suaves", "En algunos casos, probar fórmulas hipoalergénicas o gotas de probióticos (bajo indicación médica)"] } ], note: "Cuidar la salud mental de los padres y buscar ayuda para descansar es vital." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Es fundamental descartar otras enfermedades si:", items: ["El llanto se asocia con fiebre, vómitos repetidos o sangre en las heces", "El bebé no está ganando peso adecuadamente", "Sientes que podrías perder el control o hacerle daño al bebé por frustración"] } },
'Alveolitis' : { intro: "La alveolitis, también conocida como osteítis alveolar o 'alvéolo seco', es una afección dental muy dolorosa que a veces ocurre después de la extracción permanente de un diente, especialmente de las muelas del juicio.", whatIs: { title: "¿Qué es la Alveolitis?", text: "Ocurre cuando el coágulo de sangre en el lugar de la extracción del diente no se desarrolla, o se desplaza o disuelve antes de que la herida haya sanado, exponiendo el hueso y los nervios subyacentes." }, types: { title: "Factores de riesgo", intro: "La probabilidad de desarrollarla aumenta por:", items: ["Tabaquismo (fumar interfiere con la cicatrización y puede desplazar el coágulo)", "Mala higiene bucal o enjuagues vigorosos prematuros", "Uso de anticonceptivos orales (estrógenos)", "Extracciones complicadas o traumáticas"], note: "El dolor suele comenzar de 1 a 3 días después de la extracción." }, diagnosis: { title: "Diagnóstico", intro: "El dentista lo identifica fácilmente mediante:", items: ["Revisión del alvéolo (se ve el hueso desnudo en lugar de un coágulo oscuro)", "Historia clínica del dolor intenso y mal aliento", "Radiografías (si se sospecha que quedaron restos de raíces o hueso)"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es aliviar el dolor y promover la curación:", subsections: [ { title: "Medidas", items: ["Limpieza del alvéolo (lavado con solución salina)", "Colocación de apósitos o pastas medicamentosas dentro del alvéolo", "Analgésicos potentes recetados", "Enjuagues con clorhexidina"] } ], note: "El alivio del dolor es casi inmediato tras la colocación del apósito medicado." }, whenToSeekHelp: { title: "¿Cuándo llamar al dentista?", intro: "Contacta a tu cirujano dental si:", items: ["Sientes un dolor intenso o que empeora días después de una extracción", "El dolor se irradia hacia el oído, el ojo o el cuello del mismo lado", "Notas mal aliento persistente o un sabor muy desagradable en la boca"] } },
'Dolor muscular' : { intro: "El dolor muscular (mialgia) es una molestia que puede afectar a uno o varios músculos del cuerpo. Es un síntoma muy común que puede originarse por tensión, sobrecarga, lesiones menores o estar relacionado con enfermedades sistémicas.", whatIs: { title: "¿Qué es el Dolor Muscular?", text: "Es la sensación de malestar, rigidez o dolor en los tejidos musculares. Puede ser agudo y localizado, generalmente por esfuerzo físico, o crónico y generalizado, lo cual sugiere condiciones subyacentes." }, types: { title: "Orígenes Comunes", intro: "Se puede clasificar por su causa:", items: ["Por sobreesfuerzo, tensión o trauma menor (la causa más frecuente)", "Relacionado con infecciones virales (como la gripe o el COVID-19)", "Relacionado con medicamentos (como las estatinas para el colesterol)", "Por trastornos crónicos (fibromialgia, polimialgia reumática)"], note: "El dolor por esfuerzo suele aparecer 12-48 horas después del ejercicio (agujetas)." }, diagnosis: { title: "Evaluación", intro: "Suele diagnosticarse clínicamente, pero si es persistente:", items: ["Examen físico detallado", "Análisis de sangre (para medir enzimas musculares como la CPK o buscar inflamación)", "Revisión de la lista de medicamentos del paciente"], note: "" }, treatment: { title: "Alivio y Recuperación", intro: "El tratamiento se enfoca en el alivio sintomático:", subsections: [ { title: "Medidas", items: ["Descanso, aplicación de hielo (primeras 48h) y luego calor", "Analgésicos y antiinflamatorios de venta libre (AINEs)", "Masajes, estiramientos suaves y fisioterapia", "Tratamiento de la enfermedad subyacente o ajuste de medicamentos si aplica"] } ], note: "Mantenerse hidratado y calentar antes del ejercicio previene lesiones menores." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es necesario buscar atención si el dolor:", items: ["Dura más de unos pocos días o empeora drásticamente", "Se acompaña de debilidad extrema, fiebre alta o hinchazón y enrojecimiento en la zona", "Surgió tras el inicio de un nuevo medicamento, especialmente estatinas"] } },
'Cáncer de piel' : { intro: "El cáncer de piel es el crecimiento anormal de las células de la piel. Suele desarrollarse en la piel expuesta al sol, pero puede formarse en cualquier parte del cuerpo. Es el tipo de cáncer más común a nivel mundial.", whatIs: { title: "¿Qué es el Cáncer de Piel?", text: "Es una enfermedad maligna producida por la división y el crecimiento descontrolado de las células cutáneas, generalmente causado por el daño en el ADN por la radiación ultravioleta (UV) del sol o camas bronceadoras." }, types: { title: "Tipos Principales", intro: "Se divide en tres tipos básicos:", items: ["Carcinoma basocelular (el más común, crece lentamente, rara vez se disemina)", "Carcinoma espinocelular (común en áreas expuestas, puede diseminarse si no se trata)", "Melanoma (el más peligroso y agresivo, puede formarse a partir de un lunar existente)"], note: "La detección temprana es crucial para un tratamiento exitoso." }, diagnosis: { title: "Diagnóstico", intro: "El dermatólogo realizará:", items: ["Examen de la piel completo usando un dermatoscopio", "Regla ABCDE para evaluar lunares (Asimetría, Bordes, Color, Diámetro, Evolución)", "Biopsia de piel (extracción de la lesión o parte de ella para análisis microscópico)"], note: "La biopsia es la única forma de confirmar si una lesión es cancerosa." }, treatment: { title: "Tratamiento", intro: "Depende del tamaño, tipo y profundidad del cáncer:", subsections: [ { title: "Opciones", items: ["Escisión quirúrgica o Cirugía de Mohs (para preservar tejido sano)", "Crioterapia (congelación) o tratamientos tópicos (para cánceres superficiales precoces)", "Radioterapia", "Inmunoterapia o quimioterapia (para melanomas avanzados o con metástasis)"] } ], note: "La protección solar diaria es esencial para prevenir recurrencias." }, whenToSeekHelp: { title: "¿Cuándo ir al dermatólogo?", intro: "Programa una revisión si notas:", items: ["Un lunar nuevo que crece rápidamente, pica o sangra", "Cambios en un lunar existente según la regla ABCDE", "Una llaga que no cicatriza en semanas o que sana y vuelve a abrirse"] } },
'Retinopatía diabética' : { intro: "La retinopatía diabética es una complicación de la diabetes que afecta los ojos. Es causada por el daño a los vasos sanguíneos del tejido sensible a la luz en la parte posterior del ojo (retina).", whatIs: { title: "¿Qué es la Retinopatía Diabética?", text: "Es una enfermedad ocular progresiva que puede causar pérdida de visión y ceguera. Los niveles altos de azúcar en la sangre dañan los diminutos vasos sanguíneos de la retina, haciéndolos gotear fluido o sangrar, o provocando el crecimiento de vasos anormales." }, types: { title: "Etapas", intro: "La afección progresa en dos fases principales:", items: ["Retinopatía diabética no proliferativa (RDNP): Etapa temprana, los vasos sanguíneos se debilitan y gotean, la mácula puede hincharse (edema macular).", "Retinopatía diabética proliferativa (RDP): Etapa avanzada y grave, crecen nuevos vasos anormales que sangran en el gel vítreo y pueden causar desprendimiento de retina."], note: "Al principio, puede no tener síntomas evidentes." }, diagnosis: { title: "Evaluación Oftalmológica", intro: "Requiere un examen ocular completo:", items: ["Examen de fondo de ojo con pupilas dilatadas", "Angiografía con fluoresceína (para ver qué vasos gotean)", "Tomografía de coherencia óptica (OCT) (para medir el grosor de la retina y el edema macular)"], note: "Los diabéticos deben hacerse este examen anualmente." }, treatment: { title: "Manejo y Tratamiento", intro: "El tratamiento busca detener o retrasar la pérdida de visión:", subsections: [ { title: "Procedimientos", items: ["Control estricto de la glucosa en sangre y la presión arterial (fundamental)", "Inyecciones intravítreas de medicamentos anti-VEGF o corticosteroides (para el edema macular)", "Fotocoagulación con láser (para sellar vasos que gotean o encoger vasos anormales)", "Vitrectomía (cirugía para extraer sangre del centro del ojo)"] } ], note: "El daño ya producido a menudo es irreversible, de ahí la importancia de la prevención." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Busca atención oftalmológica inmediata si:", items: ["Experimentas pérdida de visión repentina o visión borrosa de un momento a otro", "Ves manchas, 'moscas volantes' o hilos oscuros repentinos en tu campo de visión", "Sientes un velo u oscuridad sobre tu campo visual"] } },
'Movilidad dentaria' : { intro: "La movilidad dentaria se refiere al aflojamiento de los dientes en sus alvéolos. Mientras que una ligera movilidad fisiológica es normal, un movimiento notorio es un signo clínico de un problema subyacente en el soporte del diente.", whatIs: { title: "¿Qué es la Movilidad Dentaria?", text: "Es el desplazamiento de un diente en dirección horizontal o vertical más allá de lo normal. Indica que las estructuras que anclan el diente al hueso mandibular (el ligamento periodontal y el hueso alveolar) están dañadas o destruidas." }, types: { title: "Causas Principales", intro: "Se origina generalmente por:", items: ["Enfermedad periodontal avanzada (la causa más común, destrucción del hueso de soporte)", "Trauma o golpe directo en los dientes", "Trauma oclusal (rechinar los dientes o bruxismo que somete al diente a fuerzas excesivas)", "Infección periapical severa o absceso"], note: "Se clasifica en grados (1, 2 y 3) según la cantidad de movimiento (milímetros y dirección)." }, diagnosis: { title: "Evaluación Dental", intro: "El dentista determinará la causa y gravedad mediante:", items: ["Prueba de movilidad manual (empujando el diente suavemente con los mangos de dos instrumentos)", "Sondaje periodontal (para medir la pérdida de hueso e inflamación de encías)", "Radiografías periapicales (para ver el nivel óseo y las raíces)"], note: "" }, treatment: { title: "Intervenciones", intro: "El objetivo es tratar la causa y estabilizar el diente:", subsections: [ { title: "Tratamientos", items: ["Limpieza periodontal profunda (raspado y alisado radicular) para eliminar la infección", "Férula dental (unir el diente flojo a dientes firmes vecinos mediante resina y alambre o fibra)", "Ajuste oclusal (desgastar puntos de contacto si la causa es el bruxismo o mala mordida)", "Extracción (si el soporte óseo es mínimo o nulo y el diente es insalvable)"] } ], note: "En casos de trauma agudo, la ferulización inmediata puede salvar el diente." }, whenToSeekHelp: { title: "¿Cuándo acudir al dentista?", intro: "Debes buscar ayuda profesional si:", items: ["Notas que uno o varios dientes se mueven al tocarlos con la lengua o el dedo", "Sientes dolor al masticar o sientes los dientes 'flojos'", "Sufriste un golpe en la boca y los dientes cambiaron de posición"] } },
'Demencia' : { intro: "La demencia no es una enfermedad específica, sino un término general que describe un grupo de síntomas que afectan gravemente la memoria, el pensamiento y las habilidades sociales, lo suficiente como para interferir con la vida diaria.", whatIs: { title: "¿Qué es la Demencia?", text: "Es un síndrome crónico y progresivo caracterizado por el deterioro de la función cognitiva (procesar el pensamiento) más allá de lo que se espera en el envejecimiento normal. Se produce por el daño o la pérdida de células nerviosas en el cerebro." }, types: { title: "Enfermedades Causantes", intro: "Existen diferentes tipos según los daños cerebrales:", items: ["Enfermedad de Alzheimer (la causa más común, alrededor del 60-70% de los casos)", "Demencia vascular (causada por daño a los vasos sanguíneos del cerebro)", "Demencia con cuerpos de Lewy", "Demencia frontotemporal", "Demencia mixta (combinación de varias)"], note: "Algunas condiciones que imitan la demencia (como déficit de vitaminas) son reversibles." }, diagnosis: { title: "Evaluación Neurológica", intro: "Un equipo médico diagnostica y clasifica la demencia mediante:", items: ["Evaluaciones cognitivas y neuropsicológicas (pruebas de memoria, lenguaje y resolución de problemas)", "Evaluaciones psiquiátricas (para detectar depresión o cambios de humor)", "Pruebas de imagen cerebral (RM, TC o PET para buscar tumores, accidentes cerebrovasculares o atrofia)", "Análisis de sangre (para descartar problemas de tiroides o déficit de B12)"], note: "" }, treatment: { title: "Manejo y Cuidado", intro: "La mayoría de las demencias no tienen cura, pero se pueden tratar los síntomas:", subsections: [ { title: "Opciones", items: ["Medicamentos inhibidores de la colinesterasa o memantina (para retrasar el deterioro cognitivo temporalmente)", "Medicamentos para tratar síntomas como problemas de sueño, ansiedad o agitación", "Terapia ocupacional para adaptar el entorno y hacerlo seguro", "Apoyo continuo a los cuidadores familiares"] } ], note: "La planificación legal y financiera temprana es crucial tras un diagnóstico." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es necesario buscar evaluación si notas en ti o en un ser querido:", items: ["Pérdida de memoria reciente constante que afecta las rutinas diarias (ej. hacer la misma pregunta varias veces)", "Dificultad para realizar tareas familiares (cocinar, manejar dinero)", "Desorientación grave en tiempo o lugar (perderse en vecindarios conocidos)", "Cambios abruptos de personalidad, estado de ánimo o juicio"] } },
'Bronquiolitis' : { intro: "La bronquiolitis es una infección pulmonar común en bebés y niños pequeños. Causa inflamación y congestión en las pequeñas vías respiratorias (bronquiolos) del pulmón, dificultando la respiración.", whatIs: { title: "¿Qué es la Bronquiolitis?", text: "Es una enfermedad respiratoria viral, casi siempre causada por el Virus Sincitial Respiratorio (VSR). Comienza con síntomas similares a los de un resfriado leve, pero progresa hacia tos persistente, sibilancias (silbidos) y dificultad respiratoria." }, types: { title: "Población de Riesgo", intro: "Afecta principalmente a:", items: ["Niños menores de 2 años (especialmente entre 3 y 6 meses de edad)", "Bebés prematuros o con problemas cardíacos/pulmonares subyacentes (tienen mayor riesgo de enfermedad grave)"], note: "La incidencia máxima ocurre durante el invierno y principios de la primavera." }, diagnosis: { title: "Evaluación Pediátrica", intro: "Suele diagnosticarse clínicamente:", items: ["Examen físico escuchando los pulmones con un estetoscopio", "Medición de la saturación de oxígeno en la sangre (oximetría de pulso)", "En casos severos, radiografía de tórax o hisopado nasal para identificar el VSR"], note: "" }, treatment: { title: "Cuidados y Tratamiento", intro: "Al ser viral, no se trata con antibióticos; el manejo es sintomático:", subsections: [ { title: "Medidas", items: ["Mantener al niño bien hidratado ofreciendo líquidos frecuentes en pequeñas cantidades", "Aspiración suave de la mucosidad nasal con suero fisiológico", "Uso de humidificadores de vapor frío", "Hospitalización para oxígeno, hidratación IV o asistencia respiratoria (en casos graves)"] } ], note: "Los medicamentos para el asma (broncodilatadores) generalmente no son efectivos para la bronquiolitis." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a urgencias pediátricas inmediatamente si el bebé:", items: ["Respira muy rápido (más de 60 veces por minuto) o hace pausas en la respiración", "Se le hunden las costillas o el cuello al respirar (esfuerzo respiratorio)", "Su piel, labios o uñas se vuelven azulados o muy pálidos", "No puede beber o comer debido a la dificultad para respirar o parece aletargado"] } },
'Conjuntivitis' : { intro: "La conjuntivitis, a menudo llamada 'ojo rosa', es la inflamación de la conjuntiva, la membrana transparente que recubre el interior del párpado y cubre la parte blanca del ojo. Es muy común y altamente contagiosa en algunos casos.", whatIs: { title: "¿Qué es la Conjuntivitis?", text: "Es una afección ocular que causa enrojecimiento, picazón, sensación de arena y lagrimeo. Cuando los pequeños vasos sanguíneos de la conjuntiva se inflaman, se hacen más visibles, dándole al ojo un color rosado o rojizo." }, types: { title: "Tipos y Causas", intro: "Se clasifica por su origen:", items: ["Viral (muy contagiosa, a menudo asociada a resfriados, causa secreción acuosa)", "Bacteriana (muy contagiosa, produce secreción espesa amarilla o verde que puede pegar los párpados)", "Alérgica (afecta ambos ojos, causa picazón intensa, no es contagiosa)", "Irritativa (por químicos, humo, o uso prolongado de lentes de contacto)"], note: "Determinar el tipo es clave para un tratamiento eficaz." }, diagnosis: { title: "Diagnóstico", intro: "El médico u oftalmólogo suele diagnosticarla mediante:", items: ["Examen visual del ojo y evaluación de los síntomas y antecedentes", "Rara vez se toma una muestra de la secreción para cultivo, a menos que sea severa o no responda al tratamiento"], note: "" }, treatment: { title: "Manejo", intro: "El tratamiento varía según la causa:", subsections: [ { title: "Terapias", items: ["Para bacteriana: Gotas o pomadas oftalmológicas con antibióticos", "Para viral: No hay tratamiento específico, se alivia con compresas frías y lágrimas artificiales (sana sola en 1-2 semanas)", "Para alérgica: Gotas para los ojos con antihistamínicos o estabilizadores de mastocitos", "Limpieza cuidadosa y lavado de manos frecuente para evitar contagiar a otros"] } ], note: "Se debe suspender el uso de lentes de contacto y maquillaje hasta que desaparezca la infección." }, whenToSeekHelp: { title: "¿Cuándo acudir al oftalmólogo?", intro: "Es importante buscar atención médica si:", items: ["Experimentas dolor intenso en el ojo, sensibilidad extrema a la luz (fotofobia) o visión borrosa que no mejora tras limpiar las secreciones", "Los síntomas no mejoran después de unos días de tratamiento antibiótico", "Sientes que tienes algo atascado en el ojo que no sale"] } },
'Nutrición inadecuada' : { intro: "La nutrición inadecuada o malnutrición es una condición que resulta de comer una dieta en la cual uno o más nutrientes no son suficientes o son demasiados, de manera que causa problemas de salud. Incluye la desnutrición y el sobrepeso/obesidad.", whatIs: { title: "¿Qué es?", text: "Es el desequilibrio entre los nutrientes que el cuerpo necesita para funcionar y los nutrientes que recibe. Puede significar una falta de calorías y proteínas, deficiencias de vitaminas y minerales (hambre oculta), o un consumo excesivo de calorías." }, types: { title: "Manifestaciones", intro: "Se divide en amplias categorías:", items: ["Desnutrición (retraso del crecimiento, emaciación o bajo peso)", "Malnutrición por deficiencia de micronutrientes (falta de hierro, yodo, vitamina A, etc.)", "Sobrenutrición (sobrepeso, obesidad y enfermedades no transmisibles relacionadas con la dieta)"], note: "Puede ocurrir en personas de cualquier peso, incluyendo individuos con sobrepeso que carecen de vitaminas." }, diagnosis: { title: "Evaluación Nutricional", intro: "Realizada por un médico o dietista-nutricionista:", items: ["Evaluación antropométrica (IMC, pérdida de peso involuntaria, medición de masa muscular y grasa)", "Análisis de sangre (albúmina, hierro, vitaminas, perfil lipídico)", "Revisión detallada de la ingesta dietética e historia clínica"], note: "" }, treatment: { title: "Intervención", intro: "Depende de la naturaleza del desequilibrio:", subsections: [ { title: "Medidas", items: ["Diseño de un plan dietético personalizado y equilibrado", "Suplementos orales (vitaminas, minerales, batidos hipercalóricos/hiperproteicos)", "Intervención médica si la malnutrición es causada por problemas de absorción o enfermedades digestivas", "Nutrición enteral (sonda) o parenteral (intravenosa) en casos severos en hospitales"] } ], note: "La educación nutricional a largo plazo es clave para mantener los resultados." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda?", intro: "Es recomendable consultar a un profesional si:", items: ["Pierdes peso de forma involuntaria e inexplicable", "Te sientes constantemente cansado, débil, te mareas o tienes pérdida de cabello y uñas quebradizas", "Tienes un IMC en los rangos de bajo peso severo u obesidad"] } },
'Mordida abierta' : { intro: "La mordida abierta es un tipo de maloclusión (mala alineación dental) en la cual los dientes superiores e inferiores no logran hacer contacto al cerrar la boca, dejando un espacio visible entre ellos, generalmente en la parte frontal.", whatIs: { title: "¿Qué es la Mordida Abierta?", text: "Es un problema ortodóntico y esquelético donde no hay superposición vertical entre los dientes anteriores (o en ocasiones posteriores). Esto dificulta funciones básicas como morder alimentos (ej. un bocadillo), tragar y hablar correctamente." }, types: { title: "Clasificación", intro: "Se divide según su ubicación y origen:", items: ["Mordida abierta anterior (la más común, los dientes frontales no tocan)", "Mordida abierta posterior (los dientes de atrás no tocan)", "Mordida abierta dental (causada por la inclinación de los dientes)", "Mordida abierta esquelética (causada por el crecimiento anormal de los huesos maxilares)"], note: "El uso prolongado del chupete o la succión del pulgar en la infancia son causas muy frecuentes." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El ortodoncista la identifica mediante:", items: ["Examen clínico de la oclusión (forma de morder)", "Radiografías laterales de cráneo (cefalometría) para evaluar los ángulos de los huesos faciales", "Modelos de estudio o escaneos 3D de la boca"], note: "" }, treatment: { title: "Tratamiento", intro: "La corrección es más fácil si se trata durante el crecimiento:", subsections: [ { title: "Opciones", items: ["En niños: Eliminación de malos hábitos (chupete, dedo), terapia miofuncional para reeducar la lengua, y ortopedia maxilar", "En adolescentes/adultos: Ortodoncia (brackets convencionales o alineadores transparentes con elásticos)", "Cirugía ortognática (cirugía de los huesos maxilares) en adultos con mordidas abiertas esqueléticas severas"] } ], note: "El tratamiento multidisciplinario (ortodoncista + logopeda) suele prevenir recaídas." }, whenToSeekHelp: { title: "¿Cuándo consultar al ortodoncista?", intro: "Es momento de pedir una evaluación si:", items: ["Un niño mayor de 4 años continúa chupándose el dedo o usando chupete de forma constante", "Se observa un espacio claro entre los dientes al morder a cualquier edad", "Existen problemas notables de dicción (ceceo) o dificultades al masticar"] } },
'Diarrea' : { intro: "La diarrea se caracteriza por evacuaciones intestinales flojas, acuosas y más frecuentes de lo habitual. Es un problema común que generalmente dura un par de días y desaparece por sí solo, pero puede ser peligrosa si causa deshidratación.", whatIs: { title: "¿Qué es la Diarrea?", text: "Es una alteración en el ritmo intestinal que resulta en una mayor frecuencia de deposiciones con menor consistencia. A menudo es la forma en que el cuerpo se deshace rápidamente de virus, bacterias o toxinas del tracto digestivo." }, types: { title: "Clasificación por Duración", intro: "Se divide en:", items: ["Diarrea aguda (dura de 1 a 2 días, hasta 2 semanas; típicamente infecciosa o alimentaria)", "Diarrea persistente (dura de 2 a 4 semanas)", "Diarrea crónica (dura más de 4 semanas, suele indicar trastornos como SII, EII, enfermedad celíaca o intolerancias)"], note: "La principal preocupación a corto plazo es la pérdida de líquidos y electrolitos." }, diagnosis: { title: "Evaluación Médica", intro: "Para episodios crónicos o severos, el médico puede solicitar:", items: ["Análisis y cultivo de heces (para buscar bacterias, parásitos o sangre)", "Análisis de sangre (para verificar deshidratación o infecciones subyacentes)", "Endoscopia o colonoscopia (si se sospecha de enfermedad inflamatoria intestinal)"], note: "La mayoría de las diarreas agudas no requieren pruebas diagnósticas." }, treatment: { title: "Manejo y Tratamiento", intro: "El objetivo principal es prevenir la deshidratación:", subsections: [ { title: "Medidas", items: ["Rehidratación oral constante (agua, sueros orales, caldos; evitar jugos azucarados)", "Dieta blanda y astringente (arroz, compota de manzana, tostadas, plátanos)", "Medicamentos antidiarreicos (loperamida) solo en adultos y bajo ciertas condiciones, no si hay fiebre o sangre", "Antibióticos o antiparasitarios (solo si hay una infección bacteriana/parasitaria confirmada)"] } ], note: "No se deben administrar antidiarreicos de venta libre a niños sin indicación médica." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Busca atención médica inmediata si:", items: ["La diarrea dura más de dos días en adultos, o 24 horas en niños", "Presentas signos de deshidratación (boca muy seca, orina oscura, mareos, falta de lágrimas en bebés)", "Tienes dolor abdominal severo, fiebre alta o heces de color negro o con sangre"] } },
'Cáncer de próstata' : { intro: "El cáncer de próstata es el cáncer que se forma en la próstata, una pequeña glándula con forma de nuez en los hombres que produce el líquido seminal. Es uno de los tipos más comunes de cáncer en hombres, y muchos crecen lentamente y se limitan a la glándula.", whatIs: { title: "¿Qué es?", text: "Es el crecimiento maligno y descontrolado de las células de la glándula prostática. Aunque algunos tipos son agresivos y pueden diseminarse rápidamente (metástasis), la gran mayoría crecen de forma tan lenta que nunca causarán problemas graves ni requerirán tratamiento." }, types: { title: "Características", intro: "Se evalúa según su agresividad (Escala de Gleason):", items: ["Bajo grado (crecimiento muy lento, a menudo solo requieren vigilancia)", "Grado intermedio", "Alto grado (crecimiento agresivo y rápido con alta probabilidad de diseminarse a huesos y ganglios)"], note: "La edad avanzada, la raza y los antecedentes familiares son factores de riesgo clave." }, diagnosis: { title: "Detección y Diagnóstico", intro: "Suele detectarse mediante pruebas de detección temprana antes de que haya síntomas:", items: ["Prueba de sangre del Antígeno Prostático Específico (PSA)", "Tacto rectal (TR) para palpar anomalías en la glándula", "Resonancia magnética multiparamétrica y Ecografía transrectal", "Biopsia de próstata (el único procedimiento que confirma el cáncer)"], note: "" }, treatment: { title: "Opciones de Tratamiento", intro: "La elección depende del grado del cáncer, la edad y la salud general:", subsections: [ { title: "Estrategias", items: ["Vigilancia activa (controles regulares sin tratamiento inmediato para cánceres de bajo riesgo)", "Prostatectomía radical (cirugía para extirpar la glándula)", "Radioterapia (externa o braquiterapia)", "Terapia de privación de andrógenos (terapia hormonal para reducir la testosterona)", "Quimioterapia o inmunoterapia (para enfermedad avanzada)"] } ], note: "Los tratamientos pueden tener efectos secundarios como incontinencia urinaria y disfunción eréctil." }, whenToSeekHelp: { title: "¿Cuándo acudir al urólogo?", intro: "Es recomendable consultar si presentas (aunque a menudo no hay síntomas):", items: ["Dificultad o lentitud para orinar, o necesidad frecuente de hacerlo, especialmente de noche", "Sangre en la orina o en el semen", "Dolor persistente en la espalda, las caderas o la pelvis", "Disfunción eréctil de aparición reciente"] } },
'Anemia' : { intro: "La anemia es una afección en la que la sangre no cuenta con suficientes glóbulos rojos sanos o hemoglobina para transportar un nivel adecuado de oxígeno a los tejidos del cuerpo. Esto provoca una sensación constante de cansancio y debilidad.", whatIs: { title: "¿Qué es la Anemia?", text: "Es un déficit en la capacidad de la sangre para oxigenar el organismo. Ocurre si el cuerpo no produce suficientes glóbulos rojos, si el sangrado hace que se pierdan más rápido de lo que se pueden reemplazar, o si el cuerpo los destruye." }, types: { title: "Tipos y Causas", intro: "Existen muchos tipos con diferentes causas:", items: ["Anemia por deficiencia de hierro (la más común en el mundo, por sangrados o dieta pobre)", "Anemia por deficiencia de vitaminas (B12 o ácido fólico)", "Anemia de enfermedades crónicas (por cáncer, artritis reumatoide, enfermedades renales)", "Anemias hemolíticas (los glóbulos rojos se destruyen rápidamente)", "Anemia falciforme o talasemia (trastornos genéticos)"], note: "" }, diagnosis: { title: "Pruebas Médicas", intro: "El diagnóstico es principalmente a través de laboratorio:", items: ["Hemograma completo (mide los niveles de hemoglobina, hematocrito y tamaño de los glóbulos rojos)", "Pruebas para medir niveles de hierro, ferritina, vitamina B12 y folato", "Examen físico buscando palidez en piel y mucosas", "Endoscopia o colonoscopia si se sospecha de sangrado interno oculto"], note: "" }, treatment: { title: "Tratamiento", intro: "Varía dependiendo de la causa exacta:", subsections: [ { title: "Opciones", items: ["Suplementos de hierro orales o intravenosos y cambios en la dieta", "Suplementos de vitamina B12 (inyecciones) o ácido fólico", "Tratamiento de las enfermedades crónicas subyacentes o freno de hemorragias internas", "Transfusiones de sangre o medicamentos que estimulan la médula ósea en casos muy severos"] } ], note: "No se deben tomar suplementos de hierro sin confirmar el diagnóstico médico." }, whenToSeekHelp: { title: "¿Cuándo ver a un médico?", intro: "Programa una cita si notas:", items: ["Fatiga extrema constante que no mejora con el descanso, acompañada de palidez notoria", "Dificultad para respirar, latidos cardíacos rápidos o irregulares (palpitaciones)", "Manos y pies siempre fríos, mareos o dolores de cabeza frecuentes"] } },
'Trastornos del aprendizaje' : { intro: "Los trastornos del aprendizaje son afecciones neurobiológicas que afectan la capacidad del cerebro para recibir, procesar, almacenar, responder y producir información. Las personas con estos trastornos tienen una inteligencia promedio o superior, pero muestran una brecha significativa entre su potencial y su rendimiento académico.", whatIs: { title: "¿Qué son los Trastornos del Aprendizaje?", text: "Son dificultades específicas y persistentes en la adquisición y uso de habilidades como la lectura, escritura o matemáticas, que no se explican por discapacidad intelectual, problemas visuales o auditivos, ni falta de instrucción escolar adecuada." }, types: { title: "Tipos Comunes", intro: "Se agrupan según el área de dificultad:", items: ["Dislexia (dificultad con la lectura, reconocimiento de palabras y fluidez)", "Disgrafía (dificultad con la escritura, ortografía y expresión escrita)", "Discalculia (dificultad para comprender números y conceptos matemáticos)", "Trastorno del procesamiento auditivo o visual"], note: "Frecuentemente coexisten con el TDAH." }, diagnosis: { title: "Evaluación Psicopedagógica", intro: "El diagnóstico lo realiza un equipo (psicólogo, psicopedagogo, neurólogo):", items: ["Pruebas estandarizadas de inteligencia (CI) y de rendimiento académico", "Evaluación de la historia escolar, médica y del desarrollo del niño", "Descarte de problemas sensoriales (visión/audición) o emocionales"], note: "El diagnóstico formal suele hacerse una vez que el niño ha comenzado la educación primaria." }, treatment: { title: "Intervención y Apoyo", intro: "No tienen cura, pero se manejan mediante:", subsections: [ { title: "Estrategias", items: ["Educación especial o tutorías adaptadas con métodos de enseñanza multisensoriales", "Adaptaciones en el aula (ej. más tiempo para exámenes, uso de calculadoras o tecnología de asistencia verbal)", "Terapia ocupacional o del habla", "Apoyo psicológico para manejar la frustración y la autoestima"] } ], note: "La intervención temprana es la clave para el éxito académico y emocional." }, whenToSeekHelp: { title: "¿Cuándo sospechar y buscar evaluación?", intro: "Es recomendable pedir una evaluación si el niño:", items: ["Tiene problemas persistentes para aprender los sonidos de las letras, leer o comprender matemáticas, por debajo de sus compañeros", "Se resiste fuertemente y muestra mucha ansiedad a la hora de hacer las tareas escolares", "Tiene dificultad para recordar secuencias (días de la semana) o direcciones simples"] } },
'Halitosis' : { intro: "La halitosis, comúnmente conocida como mal aliento, es un olor desagradable persistente al exhalar el aliento. Aunque a menudo es motivo de vergüenza y ansiedad social, casi siempre tiene una causa dental o médica tratable.", whatIs: { title: "¿Qué es la Halitosis?", text: "Es la emisión de compuestos de azufre malolientes desde la cavidad oral. Aunque puede originarse en el estómago o el sistema respiratorio, más del 80-90% de los casos se originan en la propia boca debido a la degradación bacteriana de partículas de alimentos y células." }, types: { title: "Causas Principales", intro: "Los orígenes más comunes incluyen:", items: ["Higiene bucal deficiente (acumulación de placa y sarro, saburra en la lengua)", "Enfermedad periodontal (gingivitis o periodontitis) y caries profundas", "Boca seca (xerostomía), ya que la saliva limpia la boca", "Infecciones de garganta (amigdalitis, cálculos amigdalinos) o senos paranasales", "Dietéticas (ajo, cebolla, tabaco) y gastrointestinales (ERGE)"], note: "" }, diagnosis: { title: "Evaluación", intro: "El dentista es el primer profesional a consultar:", items: ["Examen dental y periodontal completo", "Evaluación organoléptica (el dentista huele el aliento para categorizarlo)", "Revisión de la lengua, amígdalas y flujo salival"], note: "Si la boca está sana, el dentista derivará al médico de cabecera o al otorrino." }, treatment: { title: "Manejo y Tratamiento", intro: "Se centra en la higiene y el tratamiento de la causa:", subsections: [ { title: "Medidas", items: ["Mejora drástica de la higiene oral (uso de hilo dental diario, cepillado de dientes y cepillado de la lengua)", "Limpiezas dentales profesionales regulares", "Uso de enjuagues bucales antibacterianos recomendados por el dentista", "Beber mucha agua para prevenir la sequedad y tratar problemas de encías"] } ], note: "Las pastillas de menta o chicles solo enmascaran el olor temporalmente, no curan la causa." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Busca evaluación profesional si:", items: ["El mal aliento persiste a pesar de cepillarte, usar hilo dental y limpiar tu lengua rigurosamente", "Viene acompañado de encías sangrantes, dolorosas o dientes flojos", "Tienes dolor de garganta persistente, goteo posnasal o notas 'piedras' blancas en las amígdalas"] } },
'Glaucoma' : { intro: "El glaucoma es un grupo de afecciones oculares que dañan el nervio óptico, cuya salud es vital para tener una buena vista. Este daño a menudo se produce por una presión anormalmente alta en el ojo y es una de las principales causas de ceguera irreversible en personas mayores de 60 años.", whatIs: { title: "¿Qué es el Glaucoma?", text: "Es una enfermedad neurodegenerativa del ojo. El líquido acuoso dentro del ojo no drena correctamente, aumentando la presión intraocular (PIO). Esta presión comprime y mata progresivamente las fibras del nervio óptico, causando pérdida de visión, comenzando generalmente por la visión periférica." }, types: { title: "Tipos Principales", intro: "Se divide en:", items: ["Glaucoma de ángulo abierto (el más común, progresa muy lentamente, sin dolor ni síntomas iniciales)", "Glaucoma de ángulo cerrado o estrecho (bloqueo repentino del drenaje, causa síntomas súbitos y graves)", "Glaucoma de tensión normal (el nervio se daña incluso con presión ocular normal)"], note: "Se le conoce como el 'ladrón silencioso de la visión'." }, diagnosis: { title: "Detección Oftalmológica", intro: "Solo se detecta con un examen ocular completo (no solo la prueba de presión):", items: ["Tonometría (medición de la presión dentro del ojo)", "Examen del fondo de ojo con pupilas dilatadas para inspeccionar el daño al nervio óptico", "Tomografía de coherencia óptica (OCT) para escanear las fibras nerviosas", "Campimetría (prueba de campo visual para detectar pérdida de visión periférica)"], note: "Los antecedentes familiares y ser mayor de 40 años aumentan el riesgo significativamente." }, treatment: { title: "Tratamiento", intro: "El daño no se puede revertir, pero el tratamiento evita que empeore:", subsections: [ { title: "Opciones", items: ["Gotas oftálmicas recetadas (tratamiento de primera línea para disminuir la producción de líquido o mejorar el drenaje)", "Tratamientos con láser (trabeculoplastia o iridotomía)", "Cirugías de filtración, como la trabeculectomía o el uso de tubos de drenaje", "Cirugía mínimamente invasiva para glaucoma (MIGS)"] } ], note: "El uso diario y estricto de las gotas es esencial de por vida." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "El glaucoma de ángulo cerrado es una urgencia. Acude al hospital si experimentas súbitamente:", items: ["Dolor ocular o dolor de cabeza intenso", "Enrojecimiento del ojo", "Náuseas y vómitos", "Visión borrosa y aparición de halos (anillos de arcoíris) alrededor de las luces"] } },
'Síndrome del ojo seco' : { intro: "El síndrome del ojo seco es una afección frecuente que aparece cuando las lágrimas no pueden lubricar los ojos de forma adecuada. Las lágrimas pueden ser inestables o insuficientes por varias razones, causando inflamación y daño en la superficie del ojo.", whatIs: { title: "¿Qué es el Síndrome del Ojo Seco?", text: "Es un trastorno de la película lagrimal debido a la falta de producción de lágrimas o a la excesiva evaporación de las mismas. Esto deja la superficie ocular expuesta y seca, causando molestias, picazón, sensación de arena y, paradójicamente, a veces lagrimeo excesivo." }, types: { title: "Causas Subyacentes", intro: "Se produce por una alteración en los componentes de la lágrima (agua, aceite o mucosidad):", items: ["Disminución de la producción de lágrimas (por envejecimiento, medicamentos, síndrome de Sjögren)", "Aumento de la evaporación de las lágrimas (por disfunción de las glándulas de Meibomio, no parpadear suficiente frente a pantallas, exposición al viento/aire acondicionado)"], note: "El uso prolongado de lentes de contacto y cirugías láser también pueden desencadenarlo." }, diagnosis: { title: "Evaluación", intro: "El oftalmólogo u optometrista diagnostica mediante:", items: ["Examen completo de los ojos y los párpados", "Prueba de Schirmer (tiras de papel para medir la cantidad de lágrimas producidas)", "Prueba de tiempo de ruptura lagrimal (TBUT) usando un tinte para ver qué tan rápido se evaporan las lágrimas"], note: "" }, treatment: { title: "Tratamiento y Alivio", intro: "Se busca restaurar la lubricación ocular:", subsections: [ { title: "Medidas", items: ["Uso frecuente de lágrimas artificiales sin conservantes", "Gotas o pomadas recetadas para reducir la inflamación (ciclosporina, corticosteroides a corto plazo)", "Compresas tibias y masajes palpebrales (para desobstruir las glándulas productoras de aceite)", "Tapones lagrimales (para bloquear los conductos de drenaje y conservar las lágrimas)"] } ], note: "Tomar descansos frecuentes al usar pantallas (regla 20-20-20) y usar humidificadores son de gran ayuda." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable consultar si:", items: ["Experimentas ojos rojos crónicos, dolorosos e irritados de manera prolongada", "Los síntomas de sequedad afectan tu capacidad para realizar tareas como leer o conducir", "Sientes que los remedios de venta libre no proporcionan alivio"] } },
'Fascitis plantar' : { intro: "La fascitis plantar es una de las causas más comunes de dolor de talón. Consiste en la inflamación de una banda gruesa de tejido (fascia plantar) que atraviesa la planta del pie y conecta el hueso del talón con los dedos del pie.", whatIs: { title: "¿Qué es la Fascitis Plantar?", text: "Es una lesión por microdesgarros y degeneración o inflamación de la fascia plantar debido a tensión repetitiva o sobrecarga. El dolor punzante característico suele ser más intenso al dar los primeros pasos por la mañana al levantarse de la cama." }, types: { title: "Factores de Riesgo", intro: "Afecta frecuentemente a:", items: ["Corredores y bailarines", "Personas con sobrepeso o mujeres embarazadas (por el aumento de presión en el pie)", "Personas con pies planos, arcos altos o mecánica anormal de la marcha", "Quienes pasan muchas horas de pie sobre superficies duras", "Uso de calzado inadecuado sin soporte"], note: "A veces se asocia erróneamente con los espolones calcáneos, aunque la causa del dolor es la fascia, no el espolón en sí." }, diagnosis: { title: "Diagnóstico", intro: "Se diagnostica principalmente de forma clínica:", items: ["Examen físico del pie, buscando puntos de dolor localizado al presionar cerca del talón y evaluar los reflejos", "Radiografías o RM (generalmente solo se piden para descartar otras causas como fracturas por estrés o atrapamiento nervioso)"], note: "" }, treatment: { title: "Tratamiento y Recuperación", intro: "El tratamiento conservador resuelve la mayoría de los casos tras varios meses:", subsections: [ { title: "Medidas Terapéuticas", items: ["Ejercicios específicos de estiramiento de la fascia plantar, el tendón de Aquiles y los gemelos (muy efectivos)", "Uso de férulas nocturnas para estirar la pantorrilla mientras se duerme", "Plantillas ortopédicas para el calzado (dar soporte al arco) y taloneras", "Aplicación de hielo (rodar una botella de agua congelada bajo el pie) y AINEs", "Terapia de ondas de choque, infiltraciones o cirugía (solo en casos refractarios prolongados)"] } ], note: "La recuperación requiere paciencia; puede tardar de 6 a 12 meses." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico o podólogo?", intro: "Debes buscar evaluación profesional si:", items: ["El dolor es tan intenso que no puedes caminar con normalidad o cojeas", "El dolor persiste a pesar de varias semanas de estiramientos, reposo y cambio de calzado", "Sientes adormecimiento, hormigueo o pérdida de sensibilidad en el pie"] } },
'Amigdalitis' : { intro: "La amigdalitis es la inflamación de las amígdalas, dos masas de tejido de forma ovalada situadas a ambos lados de la parte posterior de la garganta. Es una afección muy frecuente, especialmente en niños.", whatIs: { title: "¿Qué es la Amigdalitis?", text: "Es una infección viral o bacteriana que hace que las amígdalas, que son parte de la primera línea de defensa del sistema inmune, se hinchen, se enrojezcan y causen dolor de garganta, dificultad para tragar y fiebre." }, types: { title: "Clasificación por Causa y Duración", intro: "Se divide en:", items: ["Amigdalitis viral (la más frecuente, causada por los virus del resfriado, gripe, mononucleosis)", "Amigdalitis bacteriana (causada por estreptococos, requiere antibióticos)", "Amigdalitis aguda (episodio aislado que dura unos días)", "Amigdalitis crónica o recurrente (infecciones constantes o amígdalas permanentemente agrandadas que causan apnea del sueño o mal aliento)"], note: "A simple vista, puede ser difícil distinguir si es viral o bacteriana." }, diagnosis: { title: "Evaluación Médica", intro: "El médico realizará:", items: ["Examen visual con linterna, buscando amígdalas agrandadas, rojas, y a menudo con manchas blancas o pus", "Prueba rápida de estreptococo o cultivo de garganta (frotis) para descartar infección bacteriana", "Palpación de los ganglios del cuello y revisión de los oídos"], note: "" }, treatment: { title: "Tratamiento", intro: "Dependerá enteramente de la causa de la infección:", subsections: [ { title: "Enfoque Terapéutico", items: ["Cuidados en casa para amigdalitis viral (reposo, líquidos, ibuprofeno/paracetamol, gárgaras de agua salada cálida)", "Ciclo completo de antibióticos recetados (si es bacteriana por estreptococo)", "Amigdalectomía (cirugía para extirpar las amígdalas) en casos de infecciones bacterianas muy frecuentes, apnea obstructiva del sueño o abscesos"] } ], note: "Las amigdalectomías ahora se recomiendan con mucha menos frecuencia que en el pasado." }, whenToSeekHelp: { title: "¿Cuándo ir al médico o urgencias?", intro: "Es necesario buscar atención médica si presentas:", items: ["Dolor de garganta severo acompañado de fiebre alta, o que dura más de 48 horas", "Dificultad real para tragar líquidos, abrir la boca, o babeo en niños pequeños", "Hinchazón severa en un solo lado de la garganta (puede ser un absceso)", "Dificultad para respirar (urgencia médica)"] } },
'Alergia alimentaria' : { intro: "Una alergia alimentaria es una reacción del sistema inmunológico que ocurre poco después de haber ingerido un determinado alimento. Incluso una pequeña cantidad del alimento causante puede desencadenar síntomas graves y potencialmente mortales.", whatIs: { title: "¿Qué es una Alergia Alimentaria?", text: "Se produce cuando el sistema inmunológico del cuerpo identifica erróneamente una proteína alimentaria inofensiva como una amenaza y produce anticuerpos (IgE) para atacarla. Esto desencadena la liberación de histamina, causando síntomas alérgicos rápidos." }, types: { title: "Desencadenantes Comunes", intro: "La gran mayoría de las alergias son causadas por ocho alimentos:", items: ["Leche de vaca", "Huevos", "Cacahuetes (maní)", "Frutos secos (nueces, almendras, avellanas)", "Pescado", "Mariscos (camarones, cangrejos)", "Soja", "Trigo"], note: "No debe confundirse con la intolerancia alimentaria (como la intolerancia a la lactosa), que no involucra al sistema inmunológico y es menos grave." }, diagnosis: { title: "Diagnóstico", intro: "El alergólogo confirmará el diagnóstico mediante:", items: ["Historia clínica detallada de los alimentos consumidos y el tiempo de aparición de los síntomas", "Pruebas cutáneas de punción (prick test) con extractos de alimentos", "Análisis de sangre (medición de anticuerpos IgE específicos)", "Prueba de provocación oral (dar a probar el alimento bajo estricta supervisión médica)"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "Actualmente no existe cura, la prevención es la clave:", subsections: [ { title: "Medidas Vitales", items: ["Evitación estricta del alimento alergénico (leer etiquetas con cuidado)", "Uso de antihistamínicos para reacciones alérgicas leves (como picazón o urticaria ligera)", "Llevar siempre consigo un autoinyector de epinefrina (Adrenalina) para tratar reacciones anafilácticas severas", "Terapia de inmunoterapia oral (desensibilización, disponible para algunos alimentos en centros especializados)"] } ], note: "Muchos niños superan las alergias a la leche, huevo y soja al crecer, pero las alergias a los cacahuetes y mariscos suelen ser de por vida." }, whenToSeekHelp: { title: "¿Cuándo usar la adrenalina y llamar a urgencias?", intro: "La anafilaxia es una emergencia médica extrema. Actúa inmediatamente si, tras comer o tocar un alimento, presentas:", items: ["Dificultad para respirar, opresión en el pecho o sensación de cierre de la garganta", "Hinchazón de los labios, la lengua, la cara o el cuello", "Mareos severos, confusión, piel pálida/azulada, o desmayo", "Una erupción o urticaria generalizada y severa que se propaga rápidamente"] } },
'Hernia' : { intro: "Una hernia ocurre cuando un órgano interno o tejido graso sobresale o empuja a través de un punto débil, un desgarro o una abertura en la fascia muscular o el tejido que lo rodea y contiene normalmente.", whatIs: { title: "¿Qué es una Hernia?", text: "Es la salida anormal del contenido de una cavidad del cuerpo. La mayoría ocurre en la pared abdominal, presentándose como un bulto que a menudo desaparece al acostarse o empujarlo, y que duele o crece al toser o levantar peso." }, types: { title: "Tipos de Hernias Abdominales", intro: "Se nombran según su ubicación anatómica:", items: ["Hernia inguinal (en la ingle, la más común, frecuente en hombres)", "Hernia umbilical (alrededor del ombligo, común en bebés y mujeres obesas o con múltiples embarazos)", "Hernia incisional (en el sitio de una cicatriz de cirugía abdominal previa)", "Hernia femoral (en la parte superior del muslo, debajo de la ingle, más común en mujeres)", "Hernia epigástrica (en la línea media del abdomen)"], note: "No sanan por sí solas y tienden a agrandarse con el tiempo." }, diagnosis: { title: "Detección", intro: "Suele ser evidente con un simple chequeo:", items: ["Examen físico palpando el área afectada mientras se le pide al paciente que tosa o puje de pie", "Ecografía de pared abdominal o Tomografía Computarizada (si la hernia es pequeña o en pacientes obesos)"], note: "" }, treatment: { title: "Reparación Quirúrgica", intro: "La cirugía es el único tratamiento definitivo:", subsections: [ { title: "Abordajes", items: ["Hernioplastia con malla (cirugía abierta para devolver el tejido a su lugar y reforzar la pared débil con una malla sintética)", "Cirugía laparoscópica (mínimamente invasiva con recuperación más rápida)", "Espera vigilante (vigilancia médica solo si la hernia es muy pequeña y asintomática)"] } ], note: "Bajar de peso y dejar de fumar reducen el riesgo de recurrencia tras la cirugía." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a un hospital inmediatamente si se estrangula la hernia, lo que se manifiesta por:", items: ["El bulto no se puede reducir (empujar hacia adentro) y se vuelve doloroso, firme, rojo o morado", "Experimentas dolor abdominal agudo súbito, acompañado de náuseas, vómitos y fiebre", "No puedes evacuar o pasar gases"] } },
'Colitis' : { intro: "La colitis es la inflamación del revestimiento interno del colon (intestino grueso). Provoca dolor abdominal, diarrea a menudo con sangre o mucosidad, y necesidad urgente de defecar.", whatIs: { title: "¿Qué es la Colitis?", text: "Es un término general que describe la inflamación del colon. Puede ser de corta duración (aguda) o durar mucho tiempo (crónica), afectando significativamente la calidad de vida y la absorción de agua y nutrientes." }, types: { title: "Tipos Principales", intro: "Se clasifica según su causa:", items: ["Colitis ulcerosa (enfermedad inflamatoria intestinal autoinmune crónica)", "Colitis infecciosa (causada por bacterias, virus o parásitos)", "Colitis isquémica (flujo sanguíneo reducido al colon)", "Colitis microscópica", "Colitis pseudomembranosa (asociada al uso de antibióticos e infección por C. difficile)"], note: "El tratamiento difiere radicalmente según el tipo." }, diagnosis: { title: "Evaluación Médica", intro: "El gastroenterólogo utilizará:", items: ["Análisis de heces y sangre (para buscar infecciones o marcadores de inflamación)", "Colonoscopia o sigmoidoscopia con biopsia (el examen definitivo)", "Tomografía computarizada (TC) o resonancia magnética"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "Depende de la causa subyacente:", subsections: [ { title: "Opciones", items: ["Antibióticos o antiparasitarios (para colitis infecciosa)", "Antiinflamatorios (aminosalicilatos, corticosteroides), inmunosupresores o terapia biológica (para colitis ulcerosa)", "Modificaciones en la dieta e hidratación", "Cirugía (colectomía) en casos graves que no responden a medicación"] } ], note: "Las enfermedades inflamatorias intestinales (EII) requieren manejo de por vida." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca atención inmediata si presentas:", items: ["Diarrea severa con sangre abundante o de color negro", "Dolor abdominal muy intenso y repentino", "Fiebre alta, escalofríos o signos de deshidratación extrema"] } },
'Cardiomiopatía isquémica' : { intro: "La cardiomiopatía isquémica es una condición en la que el músculo del corazón se debilita o se agranda debido a un daño prolongado por falta de flujo sanguíneo (isquemia), comúnmente como resultado de la enfermedad de las arterias coronarias o infartos.", whatIs: { title: "¿Qué es?", text: "Es un tipo de insuficiencia cardíaca. Cuando las arterias que alimentan el corazón se bloquean (por placas de colesterol) o se produce un ataque cardíaco, parte del músculo muere o se cicatriza, disminuyendo drásticamente su capacidad de bombear sangre al resto del cuerpo." }, types: { title: "Complicaciones Asociadas", intro: "Esta debilidad muscular puede llevar a:", items: ["Insuficiencia cardíaca congestiva", "Arritmias peligrosas (ritmos cardíacos anormales)", "Formación de coágulos de sangre en el corazón", "Paro cardíaco súbito"], note: "Es la causa más común de cardiomiopatía dilatada en países desarrollados." }, diagnosis: { title: "Evaluación Cardiológica", intro: "El cardiólogo indicará:", items: ["Ecocardiograma (para ver la fracción de eyección y cuán débil está el músculo)", "Cateterismo cardíaco o angiografía coronaria (para ver si hay arterias bloqueadas)", "Electrocardiograma (ECG) y prueba de esfuerzo", "Resonancia magnética cardíaca"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "El objetivo es mejorar el flujo sanguíneo y facilitar el trabajo del corazón:", subsections: [ { title: "Intervenciones", items: ["Medicamentos (betabloqueantes, inhibidores de la ECA, diuréticos)", "Modificaciones estrictas del estilo de vida (dejar de fumar, dieta baja en sodio, control de diabetes)", "Procedimientos de revascularización (stents o cirugía de bypass coronario para abrir arterias)", "Implantación de desfibrilador (DAI) o marcapasos biventricular", "Trasplante de corazón en etapas terminales"] } ], note: "El tratamiento es de por vida y requiere estricta adherencia." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Llama a urgencias si experimentas:", items: ["Dolor o presión intensa en el pecho, mandíbula o brazo izquierdo", "Falta de aliento grave repentina, incluso en reposo", "Palpitaciones muy rápidas acompañadas de mareos severos o desmayo", "Hinchazón rápida y repentina en las piernas o el abdomen"] } },
'Fiebre en niños' : { intro: "La fiebre en niños no es una enfermedad en sí misma, sino un síntoma. Es una respuesta defensiva normal y saludable del sistema inmunológico frente a una infección u otra afección, indicando que el cuerpo está luchando para curarse.", whatIs: { title: "¿Qué es la Fiebre Infantil?", text: "Es un aumento temporal de la temperatura corporal, por lo general provocada por una infección viral o bacteriana. En los niños, se considera fiebre cuando la temperatura rectal, de oído o de la arteria temporal es de 38 °C (100.4 °F) o superior." }, types: { title: "Causas Frecuentes", intro: "Las causas más habituales de fiebre infantil son:", items: ["Infecciones virales (resfriados, gripe, gastroenteritis, roséola, virus sincitial respiratorio)", "Infecciones bacterianas (otitis, infecciones de orina, faringitis estreptocócica, neumonía)", "Vacunación reciente (es una reacción normal y transitoria)", "Abrigo excesivo o ambientes muy calurosos (especialmente en bebés pequeños)"], note: "La dentición puede causar un ligero aumento de temperatura, pero no una fiebre alta real." }, diagnosis: { title: "Evaluación Pediátrica", intro: "El pediatra se enfoca en encontrar el foco de la infección:", items: ["Historia detallada sobre la duración de la fiebre y otros síntomas asociados (tos, vómitos, dolor al orinar)", "Examen físico completo del niño", "Análisis de sangre, orina o radiografías, especialmente en bebés menores de 3 meses o si no hay un foco claro"], note: "En niños, cómo se ve y actúa el niño es más importante que el número exacto en el termómetro." }, treatment: { title: "Manejo y Cuidados", intro: "El objetivo del tratamiento es el confort del niño, no bajar la temperatura a la fuerza:", subsections: [ { title: "Recomendaciones", items: ["Ofrecer líquidos con frecuencia para prevenir la deshidratación", "No abrigar en exceso al niño, usar ropa ligera y mantener la habitación fresca", "Medicamentos antitérmicos (paracetamol o ibuprofeno) calculados por peso, solo si la fiebre causa malestar o dolor", "Nunca dar aspirina a niños o adolescentes (riesgo de Síndrome de Reye)"] } ], note: "No se recomienda usar baños de agua fría o fricciones con alcohol." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia o requiere visita al médico?", intro: "Acude inmediatamente al pediatra o urgencias si el niño:", items: ["Tiene menos de 3 meses de edad y presenta cualquier grado de fiebre (38 °C o más)", "Está inusualmente somnoliento, letárgico, no hace contacto visual o cuesta despertarlo", "Presenta dificultad para respirar, cuello rígido, o una erupción cutánea de manchas rojas o púrpuras que no desaparecen al estirar la piel", "Tiene convulsiones febriles o la fiebre dura más de tres días (en niños mayores)"] } },
'Diente impactado' : { intro: "Un diente impactado (o retenido) es aquel que, por algún bloqueo físico o falta de espacio, no ha logrado erupcionar o salir a través de la encía hasta ocupar su posición funcional en la boca. Afecta típicamente a los terceros molares (muelas del juicio) y a los caninos superiores.", whatIs: { title: "¿Qué es un Diente Impactado?", text: "Es un diente que permanece atrapado en el hueso maxilar o bajo el tejido de la encía. En lugar de crecer rectos, a menudo crecen en un ángulo, empujando los dientes vecinos o incluso dañando las raíces o el hueso adyacente." }, types: { title: "Tipos de Impactación", intro: "Los dentistas las clasifican según la posición del diente atrapado:", items: ["Impactación mesioangular (el diente está inclinado hacia adelante, la más común)", "Impactación vertical (diente recto pero no puede romper la encía completamente)", "Impactación distoangular (inclinado hacia atrás)", "Impactación horizontal (el diente está acostado de lado, enterrado en el hueso)"], note: "También se dividen en impactación de tejido blando (cubierto por encía) e impactación ósea (cubierto por hueso)." }, diagnosis: { title: "Evaluación Radiográfica", intro: "Se diagnostican durante los exámenes dentales de rutina, incluso antes de que causen dolor:", items: ["Examen bucal rutinario", "Radiografía panorámica dental (muestra la posición exacta, el ángulo y la relación del diente con los nervios y senos paranasales)", "Tomografía 3D (para casos quirúrgicos complejos)"], note: "Los caninos impactados se suelen descubrir en niños al evaluar su desarrollo para ortodoncia." }, treatment: { title: "Manejo Clínico", intro: "El tratamiento depende de los problemas que esté causando:", subsections: [ { title: "Procedimientos", items: ["Extracción quirúrgica (tratamiento estándar para muelas del juicio que causan dolor, quistes, daño a otros dientes o infecciones)", "Tratamiento combinado de ortodoncia y cirugía (para 'rescatar' caninos impactados y traccionarlos hasta su lugar)", "Observación activa (si el diente está profundamente enterrado, no causa síntomas y el riesgo quirúrgico es alto)"] } ], note: "La extracción de muelas del juicio se recomienda a menudo en la juventud, antes de que el hueso se vuelva más denso y las raíces se arraiguen completamente." }, whenToSeekHelp: { title: "¿Cuándo programar una extracción?", intro: "Es necesario buscar atención del dentista o cirujano oral si tienes:", items: ["Dolor severo, latidos e inflamación en la parte posterior de la mandíbula o encías", "Mal aliento crónico o mal sabor de boca proveniente de esa zona (indicador de infección bajo la encía)", "Dificultad o dolor al intentar abrir la boca ampliamente", "Presión constante que parece estar desplazando tus otros dientes"] } },
'Infección urinaria en niños' : { intro: "La infección del tracto urinario (ITU) en niños es una afección bacteriana común que afecta cualquier parte del sistema urinario, incluyendo los riñones, los uréteres, la vejiga y la uretra. Aunque son habituales y tratables, en los más pequeños requieren atención médica para evitar daños renales.", whatIs: { title: "¿Qué es una Infección Urinaria?", text: "Ocurre cuando las bacterias (frecuentemente E. coli, proveniente del tracto digestivo) ingresan a la uretra y se multiplican en la vejiga. Si no se trata, la infección puede subir a los riñones causando pielonefritis." }, types: { title: "Tipos", intro: "Las infecciones urinarias se clasifican según la zona afectada:", items: ["Cistitis (infección de la vejiga urinaria, es la más común y menos grave)", "Pielonefritis (infección en uno o ambos riñones, es una condición grave)"], note: "Los lactantes y los niños pequeños pueden no presentar síntomas típicos, mostrando a menudo solo fiebre inexplicable." }, diagnosis: { title: "Diagnóstico", intro: "El pediatra diagnosticará mediante:", items: ["Análisis de orina (para detectar glóbulos blancos, sangre o bacterias)", "Cultivo de orina (para identificar la bacteria específica y el antibiótico más efectivo)", "Ecografía renal (en algunos casos para descartar anormalidades anatómicas como el reflujo vesicoureteral)"], note: "Recoger una muestra estéril en bebés puede requerir una sonda o punción suprapúbica." }, treatment: { title: "Tratamiento", intro: "El tratamiento oportuno evita complicaciones severas:", subsections: [ { title: "Medidas Médicas", items: ["Antibióticos orales (o intravenosos si hay infección renal severa o el niño no retiene líquidos)", "Fomentar una alta ingesta de líquidos para 'lavar' las bacterias", "Medicamentos para aliviar el dolor o ardor al orinar"] } ], note: "Es crucial completar todo el ciclo de antibióticos para prevenir la reincidencia." }, whenToSeekHelp: { title: "¿Cuándo acudir al pediatra?", intro: "Solicita atención médica si tu hijo presenta:", items: ["Fiebre inexplicable (especialmente en bebés menores de 6 meses)", "Llanto o quejas de dolor/ardor al orinar, o necesidad inusualmente frecuente de ir al baño", "Orina con mal olor, turbia o con rastros de sangre", "Dolor en la parte baja del abdomen o en la espalda (zona lumbar)"] } },
'Migraña' : { intro: "La migraña es un trastorno neurológico que causa dolores de cabeza intensos y debilitantes, a menudo acompañados de náuseas, vómitos y extrema sensibilidad a la luz y al sonido. Puede durar desde unas horas hasta varios días.", whatIs: { title: "¿Qué es la Migraña?", text: "Es un tipo de cefalea primaria relacionada con cambios en la actividad cerebral, alteración del flujo sanguíneo y de las vías nerviosas y químicas. Produce un dolor pulsátil, típicamente confinado a un lado de la cabeza." }, types: { title: "Clasificación", intro: "Los tipos principales incluyen:", items: ["Migraña sin aura (la más común, comienza sin señales previas)", "Migraña con aura (precedida por trastornos visuales, sensoriales o del habla temporales)", "Migraña crónica (dolores de cabeza 15 o más días al mes)"], note: "Factores como el estrés, cambios hormonales, ciertos alimentos o falta de sueño pueden desencadenarla." }, diagnosis: { title: "Diagnóstico", intro: "Es fundamentalmente clínico:", items: ["Evaluación detallada de los síntomas, frecuencia e historial familiar de migrañas", "Examen neurológico completo", "Pruebas de imagen (RM o TC) solo para descartar tumores, derrames u otras anomalías si los síntomas son atípicos"], note: "Llevar un 'diario del dolor de cabeza' ayuda enormemente al médico." }, treatment: { title: "Tratamiento", intro: "Se divide en alivio agudo y prevención:", subsections: [ { title: "Terapias Farmacológicas", items: ["Tratamiento agudo: analgésicos, triptanes (para detener la crisis), y medicamentos contra las náuseas", "Tratamiento preventivo: betabloqueantes, antidepresivos, anticonvulsivos o inyecciones de Botox", "Nuevas terapias como los anticuerpos monoclonales contra CGRP"] } ], note: "Descansar en una habitación oscura y silenciosa ayuda durante un ataque." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Busca atención médica inmediata si experimentas:", items: ["El 'peor dolor de cabeza de tu vida', repentino y explosivo", "Dolor de cabeza acompañado de fiebre, rigidez en el cuello, confusión, convulsiones o visión doble", "Dolor de cabeza que aparece tras un golpe en la cabeza o que empeora tras el descanso"] } },
'Hiperlipidemia' : { intro: "La hiperlipidemia es el término médico para niveles altos de grasas (lípidos) en la sangre, que incluyen el colesterol y los triglicéridos. Es un factor de riesgo importante para el desarrollo de enfermedades cardiovasculares, como ataques cardíacos y derrames cerebrales.", whatIs: { title: "¿Qué es la Hiperlipidemia?", text: "Es una condición metabólica silenciosa en la que hay un exceso de lípidos circulantes. El colesterol alto puede acumularse en las paredes de las arterias formando placas (aterosclerosis), lo que restringe el flujo sanguíneo." }, types: { title: "Tipos de Lípidos Elevados", intro: "Las anormalidades pueden involucrar:", items: ["Niveles altos de LDL (el colesterol 'malo' que se acumula en los vasos sanguíneos)", "Niveles altos de Triglicéridos (otro tipo de grasa que aumenta el riesgo cardíaco y de pancreatitis)", "Niveles bajos de HDL (el colesterol 'bueno' que ayuda a limpiar el exceso de grasa)", "Hiperlipidemia familiar o genética (niveles extremadamente altos desde joven)"], note: "La condición en sí no presenta síntomas externos perceptibles." }, diagnosis: { title: "Diagnóstico", intro: "Se detecta exclusivamente mediante un análisis de sangre llamado panel lipídico:", items: ["Medición del colesterol total", "Medición de LDL (lipoproteína de baja densidad)", "Medición de HDL (lipoproteína de alta densidad)", "Medición de triglicéridos"], note: "Se requiere un ayuno de 9 a 12 horas antes de la prueba para medir los triglicéridos con precisión." }, treatment: { title: "Tratamiento", intro: "El objetivo es reducir el riesgo de enfermedades del corazón:", subsections: [ { title: "Estilo de Vida y Medicamentos", items: ["Dieta saludable para el corazón (baja en grasas saturadas, grasas trans y rica en fibra)", "Ejercicio aeróbico regular y pérdida de peso", "Dejar de fumar y limitar el consumo de alcohol", "Medicamentos como las estatinas, fibratos o inhibidores de la absorción de colesterol"] } ], note: "Las estatinas no solo bajan el colesterol, sino que estabilizan las placas en las arterias." }, whenToSeekHelp: { title: "¿Cuándo hacer una evaluación?", intro: "Debes programar un chequeo de lípidos si:", items: ["Eres un adulto sano (al menos cada 4 a 6 años a partir de los 20 años)", "Tienes antecedentes familiares de colesterol alto o enfermedades cardíacas prematuras", "Padeces de obesidad, diabetes o presión arterial alta"] } },
'Oclusión dental defectuosa' : { intro: "La oclusión dental defectuosa o maloclusión se refiere al mal alineamiento de los dientes o a la forma incorrecta en que los dientes superiores e inferiores encajan entre sí al morder o cerrar la mandíbula.", whatIs: { title: "¿Qué es la Maloclusión?", text: "Es una desviación de la mordida normal. Afecta no solo la estética facial y la sonrisa, sino que también puede interferir con la masticación, la pronunciación correcta, la limpieza bucal y la salud de la articulación de la mandíbula." }, types: { title: "Tipos Comunes", intro: "Existen varias clases de maloclusión:", items: ["Apiñamiento (dientes amontonados por falta de espacio)", "Sobremordida (los dientes frontales superiores cubren excesivamente a los inferiores)", "Prognatismo o mordida cruzada anterior (mandíbula inferior sobresale más que la superior)", "Mordida abierta (los dientes frontales no hacen contacto al cerrar)", "Diastema (espacios amplios entre dientes)"], note: "Frecuentemente se origina por factores genéticos, tamaño dispar entre mandíbula y dientes, o malos hábitos infantiles." }, diagnosis: { title: "Diagnóstico", intro: "Lo realiza principalmente el ortodoncista mediante:", items: ["Examen bucal clínico y análisis de la mordida", "Radiografías panorámicas y cefalométricas para analizar la relación ósea", "Toma de impresiones dentales o escáner intraoral 3D", "Fotografías faciales y dentales"], note: "" }, treatment: { title: "Tratamiento", intro: "La ortodoncia es la principal herramienta para corregirla:", subsections: [ { title: "Aparatos y Procedimientos", items: ["Brackets metálicos, cerámicos o linguales", "Alineadores transparentes removibles (ej. Invisalign)", "Aparatos ortopédicos funcionales (en niños en etapa de crecimiento para guiar el desarrollo óseo)", "Extracciones dentales en casos de apiñamiento severo", "Cirugía ortognática en casos de discrepancias óseas graves en adultos"] } ], note: "Corregir una maloclusión previene el desgaste anormal del esmalte a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es recomendable visitar a un ortodoncista si:", items: ["Tienes dificultades al masticar o te muerdes frecuentemente el interior de las mejillas", "Sufres de dolores de cabeza crónicos o dolor en la mandíbula (ATM) debido a una mala mordida", "Te sientes incómodo o acomplejado con la apariencia de tus dientes", "En niños, se recomienda una primera evaluación de ortodoncia a los 7 años"] } },
'Hipermetropía' : { intro: "La hipermetropía es un error de refracción común en el que los objetos lejanos se ven con mayor claridad que los cercanos. Sin embargo, en niveles altos de hipermetropía, la visión puede ser borrosa a todas las distancias.", whatIs: { title: "¿Qué es la Hipermetropía?", text: "Ocurre cuando el globo ocular es demasiado corto o la córnea tiene muy poca curvatura. Esto hace que los rayos de luz se enfoquen detrás de la retina en lugar de sobre ella, dificultando el enfoque de objetos próximos." }, types: { title: "Presentación", intro: "Puede variar desde leve hasta severa:", items: ["Hipermetropía leve (el cristalino aún puede acomodar el enfoque, pasando inadvertida en jóvenes)", "Hipermetropía moderada o alta (requiere esfuerzo constante para enfocar, causando fatiga)", "Presbicia (no es hipermetropía, pero causa efectos similares por el envejecimiento del cristalino a partir de los 40 años)"], note: "Muchos niños nacen hipermétropes, pero la condición mejora a medida que el ojo crece." }, diagnosis: { title: "Examen Ocular", intro: "Se diagnostica fácilmente con un examen visual rutinario:", items: ["Prueba de agudeza visual para cerca y lejos", "Refracción para determinar la graduación exacta necesaria", "Examen con dilatación de pupila (para relajar completamente los músculos de enfoque, especialmente en niños)"], note: "" }, treatment: { title: "Corrección Óptica", intro: "El tratamiento corrige la forma en que el ojo enfoca la luz:", subsections: [ { title: "Opciones", items: ["Anteojos con lentes convexos o positivos (la solución más simple)", "Lentes de contacto (ofrecen un campo de visión más amplio)", "Cirugía refractiva (LASIK, PRK) para aumentar la curvatura de la córnea", "Lentes intraoculares fáquicos (en casos muy severos)"] } ], note: "En niños pequeños con hipermetropía significativa, el uso de gafas es vital para prevenir el ojo vago (ambliopía)." }, whenToSeekHelp: { title: "¿Cuándo consultar al oftalmólogo?", intro: "Es recomendable buscar atención si:", items: ["Experimentas dolores de cabeza frecuentes o fatiga visual al leer, trabajar en la computadora o hacer trabajos de cerca", "Tienes dificultad sostenida para leer letras pequeñas", "Un niño cruza los ojos (estrabismo), se frota mucho los ojos o rechaza hacer tareas escolares"] } },
'Acné' : { intro: "El acné es un trastorno de la piel que ocurre cuando los folículos pilosos se tapan con grasa y células cutáneas muertas. Es más común en adolescentes y adultos jóvenes, pero puede afectar a personas de todas las edades, causando puntos blancos, puntos negros o granos.", whatIs: { title: "¿Qué es el Acné?", text: "Es una enfermedad inflamatoria crónica de la unidad pilosebácea. El exceso de sebo y las células muertas bloquean el poro, creando un ambiente ideal para que la bacteria Cutibacterium acnes prolifere y cause inflamación y lesiones." }, types: { title: "Tipos de Lesiones", intro: "El acné se presenta en varias formas y severidades:", items: ["Acné comedónico (puntos negros abiertos y puntos blancos cerrados, no inflamatorios)", "Acné papulopustuloso (granos rojos e inflamados y pústulas con pus)", "Acné noduloquístico (bultos profundos, dolorosos, sólidos o llenos de líquido, con alto riesgo de cicatrices)", "Acné hormonal (común en mujeres adultas en la zona de la mandíbula)"], note: "El estrés, las hormonas, ciertos medicamentos y la genética influyen fuertemente en su aparición." }, diagnosis: { title: "Diagnóstico", intro: "El dermatólogo evalúa la piel:", items: ["Examen visual de la cara, pecho y espalda para determinar los tipos de lesiones y el grado de severidad", "Evaluación de posibles causas subyacentes (como el Síndrome de Ovario Poliquístico en mujeres)"], note: "No se requieren análisis de sangre a menos que se sospechen problemas hormonales graves." }, treatment: { title: "Tratamiento", intro: "Busca reducir la producción de sebo, acelerar la renovación celular y combatir la infección:", subsections: [ { title: "Terapias", items: ["Tratamientos tópicos (peróxido de benzoilo, retinoides, antibióticos, ácido salicílico)", "Medicamentos orales (antibióticos, pastillas anticonceptivas, antiandrógenos)", "Isotretinoína oral (para el acné nodular severo o resistente al tratamiento)", "Terapias con luz/láser o extracciones en consultorio"] } ], note: "Es crucial no apretar los granos para evitar cicatrices permanentes e infecciones peores." }, whenToSeekHelp: { title: "¿Cuándo ir al dermatólogo?", intro: "Debes buscar ayuda médica si:", items: ["Los tratamientos de venta libre no han funcionado después de varios meses", "El acné te está causando cicatrices o manchas oscuras permanentes (hiperpigmentación)", "Aparecen nódulos profundos, grandes y muy dolorosos", "El estado de tu piel está afectando gravemente tu autoestima o salud mental"] } },
'Arritmias' : { intro: "Las arritmias son problemas con la frecuencia o el ritmo de los latidos del corazón. Durante una arritmia, el corazón puede latir demasiado rápido, demasiado lento o de manera irregular, lo que puede afectar la capacidad de bombear sangre eficazmente.", whatIs: { title: "¿Qué son las Arritmias?", text: "Son alteraciones en el sistema eléctrico del corazón, que es el que coordina cada latido. Mientras algunas son inofensivas y se sienten como un 'salto' en el pecho, otras pueden ser graves o potencialmente mortales." }, types: { title: "Clasificación Principal", intro: "Se agrupan según la velocidad del corazón:", items: ["Taquicardia (latido rápido, más de 100 latidos por minuto en reposo; ej. fibrilación auricular, taquicardia supraventricular)", "Bradicardia (latido lento, menos de 60 latidos por minuto en reposo)", "Latidos prematuros o extrasístoles (latidos adicionales o tempranos, a menudo inofensivos)"], note: "La Fibrilación Auricular (FA) es la arritmia crónica más común y aumenta el riesgo de ACV." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El cardiólogo buscará registrar el ritmo anormal:", items: ["Electrocardiograma (ECG) (la prueba principal)", "Monitor Holter o grabadora de eventos (dispositivos portátiles para registrar el corazón 24 horas o más)", "Prueba de esfuerzo (para ver si el ejercicio desencadena la arritmia)", "Estudio electrofisiológico (prueba invasiva para mapear la electricidad del corazón)"], note: "" }, treatment: { title: "Tratamiento", intro: "Si la arritmia causa síntomas graves o complicaciones, puede requerir:", subsections: [ { title: "Opciones Médicas", items: ["Medicamentos antiarrítmicos y anticoagulantes (para prevenir trombos)", "Cardioversión eléctrica o farmacológica (para 'resetear' el ritmo cardíaco)", "Ablación con catéter (para destruir el tejido cardíaco que causa la señal eléctrica defectuosa)", "Dispositivos implantables (marcapasos para bradicardia, o Desfibrilador Automático Implantable DAI para taquicardias letales)"] } ], note: "Evitar la cafeína, el alcohol y el estrés es fundamental en su manejo." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Llama a urgencias médicas si experimentas:", items: ["Palpitaciones cardíacas repentinas e intensas acompañadas de dolor en el pecho", "Dificultad grave para respirar", "Mareos severos, sensación de desmayo inminente o pérdida de conocimiento"] } },
'Sobremordida' : { intro: "La sobremordida es un tipo de maloclusión en la que los dientes frontales superiores se superponen excesivamente o cubren gran parte de los dientes frontales inferiores al cerrar la mandíbula.", whatIs: { title: "¿Qué es la Sobremordida?", text: "Es una desalineación dental profunda, a menudo llamada 'mordida profunda' u 'overbite' (término en inglés). Un cierto grado de superposición es normal, pero cuando es excesiva, puede causar problemas estéticos, daño en los dientes, las encías y problemas en la articulación de la mandíbula." }, types: { title: "Causas y Tipos", intro: "Puede tener orígenes diferentes:", items: ["Sobremordida esquelética (causada por el desarrollo irregular de los huesos maxilar y mandibular)", "Sobremordida dental (causada por la erupción excesiva de los dientes o pérdida prematura de dientes posteriores)", "Asociada a malos hábitos (uso prolongado del chupete, succión del pulgar, empuje lingual)"], note: "En casos severos, los dientes inferiores pueden llegar a morder el paladar, causando llagas." }, diagnosis: { title: "Evaluación", intro: "El ortodoncista evalúa la profundidad de la mordida mediante:", items: ["Examen intraoral visual para determinar el porcentaje de superposición", "Radiografías cefalométricas (lateral de cráneo) para analizar la posición de los maxilares y la inclinación de los dientes", "Modelos dentales o escaneos 3D"], note: "" }, treatment: { title: "Tratamiento", intro: "La edad del paciente es un factor clave en la elección del tratamiento:", subsections: [ { title: "Opciones Correctivas", items: ["Ortopedia funcional en niños (uso de aparatos de crecimiento para modificar el desarrollo de la mandíbula)", "Ortodoncia con brackets o alineadores transparentes en adolescentes y adultos", "Uso de levantes de mordida o planos de mordida anteriores", "Cirugía ortognática en adultos con problemas esqueléticos severos que no se pueden corregir solo moviendo los dientes"] } ], note: "El tratamiento es más fácil y efectivo durante los períodos de crecimiento infantil." }, whenToSeekHelp: { title: "¿Cuándo visitar al ortodoncista?", intro: "Se sugiere una evaluación si:", items: ["Los dientes inferiores son casi invisibles cuando la boca está cerrada y sonriendo", "Sufres de desgaste prematuro e intenso en el esmalte de los dientes incisivos", "Tienes dolor en la mandíbula o dolor de cabeza frecuente", "Experimentas lesiones en las encías del paladar por el roce de los dientes inferiores"] } },
'Hipertiroidismo' : { intro: "El hipertiroidismo ocurre cuando la glándula tiroides produce más hormonas tiroideas (tiroxina y triyodotironina) de las que el cuerpo necesita. Esta afección acelera el metabolismo, lo que puede causar pérdida de peso involuntaria y latidos rápidos o irregulares.", whatIs: { title: "¿Qué es el Hipertiroidismo?", text: "Es una afección caracterizada por la hiperactividad de la glándula tiroides (ubicada en la base del cuello). Al liberar un exceso de hormonas en el torrente sanguíneo, el cuerpo entra en un estado de funcionamiento 'acelerado'." }, types: { title: "Causas Principales", intro: "Los motivos de esta sobreproducción incluyen:", items: ["Enfermedad de Graves (un trastorno autoinmune y la causa más frecuente, puede causar ojos saltones)", "Nódulos tiroideos hiperactivos (enfermedad de Plummer o bocio multinodular tóxico)", "Tiroiditis (inflamación de la tiroides que libera la hormona almacenada)", "Exceso de yodo en la dieta o medicamentos"], note: "Es más común en mujeres que en hombres." }, diagnosis: { title: "Diagnóstico Clínico", intro: "El endocrinólogo confirmará el diagnóstico a través de:", items: ["Análisis de sangre para medir los niveles de las hormonas (TSH baja, y T3 o T4 altas)", "Prueba de captación de yodo radiactivo o gammagrafía tiroidea (para ver qué causa el exceso)", "Ecografía de la tiroides (para detectar nódulos)"], note: "" }, treatment: { title: "Opciones de Tratamiento", intro: "El objetivo es disminuir la producción de hormonas y aliviar los síntomas:", subsections: [ { title: "Terapias", items: ["Medicamentos antitiroideos (metimazol o propiltiouracilo) para frenar la producción hormonal", "Yodo radiactivo oral (destruye permanentemente las células hiperactivas de la tiroides)", "Cirugía (tiroidectomía) para extirpar total o parcialmente la glándula", "Betabloqueantes (para aliviar rápidamente los síntomas como temblores y palpitaciones, aunque no curan la tiroides)"] } ], note: "El tratamiento con yodo radiactivo o la cirugía a menudo resultan en hipotiroidismo (el cual se trata tomando la hormona en pastilla de por vida)." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es necesario buscar una evaluación si experimentas:", items: ["Pérdida de peso rápida y sin causa aparente, incluso si comes más de lo habitual", "Latidos cardíacos acelerados, palpitaciones fuertes o irregulares en estado de reposo", "Sudoración excesiva, nerviosismo, ansiedad o temblor en las manos", "Hinchazón inusual en la base del cuello (bocio)"] } },
'Pterigión' : { intro: "El pterigión es un crecimiento anormal de tejido benigno (no canceroso) en la conjuntiva del ojo que puede extenderse hacia la córnea. Suele tener forma de cuña o ala, y a menudo se le conoce como 'ojo de surfista' por su relación con la exposición solar.", whatIs: { title: "¿Qué es un Pterigión?", text: "Es una lesión fibrosa y vascularizada que crece desde la parte blanca del ojo (generalmente en el lado más cercano a la nariz) hacia el centro de la córnea. Puede causar irritación, enrojecimiento y, si crece demasiado, alterar la visión." }, types: { title: "Factores de Riesgo", intro: "El crecimiento de este tejido se asocia fuertemente a factores ambientales crónicos:", items: ["Exposición prolongada a la radiación ultravioleta (UV) del sol", "Ambientes secos, polvorientos o ventosos", "Exposición crónica a irritantes oculares como arena o humo"], note: "No se debe confundir con la pinguécula, que es un bulto amarillento que no invade la córnea, aunque comparten causas similares." }, diagnosis: { title: "Diagnóstico", intro: "Se diagnostica fácilmente con un examen ocular de rutina:", items: ["Inspección visual y examen con lámpara de hendidura por parte del oftalmólogo (para examinar la córnea y evaluar cuánto tejido ha crecido)", "Pruebas de agudeza visual y topografía corneal para evaluar si el crecimiento ha causado astigmatismo irregular"], note: "" }, treatment: { title: "Tratamiento", intro: "Si el pterigión es pequeño y no molesta, generalmente no requiere tratamiento, solo prevención:", subsections: [ { title: "Medidas Clínicas", items: ["Uso de gotas lubricantes (lágrimas artificiales) o gotas con esteroides suaves para tratar el enrojecimiento y la irritación", "Uso estricto de gafas de sol con protección UV y sombreros (para evitar que siga creciendo)", "Extirpación quirúrgica (si el pterigión amenaza con cubrir la pupila y bloquear la visión, o por motivos estéticos graves)"] } ], note: "La cirugía tiene un riesgo de recurrencia, por lo que a menudo se usa un injerto de tejido para prevenir que vuelva a crecer." }, whenToSeekHelp: { title: "¿Cuándo ir al oftalmólogo?", intro: "Debes buscar evaluación oftalmológica si:", items: ["El tejido comienza a invadir la parte coloreada del ojo (iris) o se acerca a la pupila", "Sientes la visión borrosa o doble", "El ojo está crónicamente rojo, irritado y sientes como si tuvieras arena que no mejora con lágrimas artificiales"] } },
'Pie plano' : { intro: "El pie plano es una afección en la que los arcos de la parte interna del pie se aplanan, haciendo que toda la planta del pie toque el suelo cuando la persona se pone de pie. Es muy común y, por lo general, no causa dolor.", whatIs: { title: "¿Qué es el Pie Plano?", text: "Es una deformidad postural donde el arco longitudinal plantar está caído o ausente. En niños pequeños es fisiológico (normal) debido a la grasa en el pie y a que el arco aún se está desarrollando, pero en algunos persiste en la adultez o se desarrolla más tarde." }, types: { title: "Clasificación", intro: "Puede ser de dos tipos principales:", items: ["Pie plano flexible (el arco aparece cuando el pie no soporta peso o al ponerse de puntillas, pero desaparece al estar de pie; es el más común y suele ser indoloro)", "Pie plano rígido (el arco está plano en todo momento, a menudo debido a problemas óseos o articulares)", "Pie plano adquirido en el adulto (por desgaste, obesidad o lesión del tendón tibial posterior)"], note: "A menudo se asocia con un exceso de pronación (el tobillo se hunde hacia adentro)." }, diagnosis: { title: "Evaluación Médica", intro: "El traumatólogo, ortopedista o podólogo evaluará:", items: ["Examen visual observando los pies del paciente desde atrás y pidiendo que se ponga de puntillas", "Estudio de la marcha o huella plantar", "Pruebas de imagen (radiografías o resonancia magnética si hay dolor severo o sospecha de ruptura de tendón)"], note: "" }, treatment: { title: "Manejo", intro: "Si no causa dolor, no requiere tratamiento. Si hay molestias, se recurre a:", subsections: [ { title: "Intervenciones", items: ["Uso de plantillas ortopédicas personalizadas y calzado con buen soporte (no curan el arco, pero alivian el dolor)", "Ejercicios de estiramiento (especialmente del talón de Aquiles) y fisioterapia", "Pérdida de peso si hay obesidad", "Cirugía (rara vez necesaria, solo para problemas óseos o tendinosos severos en pies rígidos o dolor crónico limitante)"] } ], note: "En niños, el uso de zapatos ortopédicos duros para 'formar el arco' ha demostrado ser ineficaz y ya no se recomienda rutinariamente." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda profesional?", intro: "Es recomendable consultar a un especialista si:", items: ["El pie plano se desarrolla de forma repentina en la edad adulta", "Experimentas dolor persistente en los pies, tobillos, rodillas o la parte baja de la espalda tras estar de pie o caminar", "Sientes rigidez extrema en el pie y el arco no aparece ni siquiera al ponerte de puntillas"] } },
'Sinusitis' : { intro: "La sinusitis es la inflamación de los senos paranasales, las cavidades huecas alrededor de los conductos nasales. Esta inflamación causa una acumulación de mucosidad, dolor facial, congestión nasal y dificultad para respirar por la nariz.", whatIs: { title: "¿Qué es la Sinusitis?", text: "Ocurre cuando el tejido que recubre los senos paranasales se hincha debido a una infección (viral, bacteriana o fúngica), alergias o pólipos. Al bloquearse los conductos de drenaje, los senos se llenan de moco, creando un ambiente ideal para infecciones." }, types: { title: "Tipos de Sinusitis", intro: "Se clasifica principalmente por su duración:", items: ["Sinusitis aguda (de inicio repentino y dura menos de 4 semanas, la mayoría son virales vinculadas al resfriado)", "Sinusitis subaguda (dura de 4 a 12 semanas)", "Sinusitis crónica (los síntomas persisten 12 semanas o más, a pesar del tratamiento, frecuentemente ligada a alergias o problemas anatómicos)", "Sinusitis recurrente (varios ataques agudos dentro de un mismo año)"], note: "" }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El médico, a menudo el otorrinolaringólogo, determinará el origen mediante:", items: ["Examen físico palpando los senos faciales y revisando el interior de la nariz", "Endoscopia nasal (usar un tubo delgado con luz para ver directamente dentro de los senos)", "Tomografía Computarizada (TC) para visualizar obstrucciones crónicas o pólipos", "Pruebas de alergia si se sospecha que esa es la causa subyacente"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "Varía dependiendo si la causa es viral, bacteriana o alérgica:", subsections: [ { title: "Tratamientos", items: ["Lavados salinos nasales y descongestionantes (para alivio a corto plazo)", "Corticosteroides nasales en aerosol (para reducir la inflamación, muy útiles en sinusitis crónica o alérgica)", "Antibióticos orales (solo si se sospecha infección bacteriana aguda y severa)", "Cirugía endoscópica de los senos paranasales (en casos crónicos rebeldes para limpiar y ampliar las vías de drenaje)"] } ], note: "Las compresas calientes sobre el rostro y la inhalación de vapor ofrecen un gran alivio sintomático." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca ayuda profesional si presentas:", items: ["Síntomas de resfriado grave que duran más de 10-14 días sin mejorar", "Fiebre alta persistente o dolor intenso y concentrado en la frente o mejillas", "Cambios en la visión, hinchazón extrema alrededor de los ojos o rigidez en el cuello (signos de que la infección se está propagando, requiere urgencia)"] } },
'Atrición dental' : { intro: "La atrición dental es el desgaste fisiológico o patológico de los tejidos duros del diente debido al contacto directo diente con diente. Es un proceso natural de envejecimiento, pero puede volverse destructivo debido a condiciones como el bruxismo.", whatIs: { title: "¿Qué es la Atrición Dental?", text: "Es la pérdida progresiva y mecánica del esmalte, la dentina e incluso la pulpa dental que ocurre en las superficies de masticación (oclusales e incisales) sin intervención de bacterias. A medida que avanza, los dientes se ven aplanados, más cortos y amarillentos." }, types: { title: "Factores de Desgaste", intro: "Aunque es un tipo de desgaste por fricción, se clasifica en:", items: ["Atrición fisiológica (desgaste normal y lento a lo largo de los años por la masticación de rutina)", "Atrición patológica (desgaste acelerado y destructivo, comúnmente causado por bruxismo o falta de dientes posteriores que sobrecarga a los anteriores)"], note: "Se diferencia de la abrasión (desgaste por cepillado) y erosión (desgaste por ácidos)." }, diagnosis: { title: "Evaluación", intro: "El odontólogo la detecta durante las revisiones periódicas:", items: ["Examen clínico buscando facetas de desgaste lisas, aplanadas y brillantes en los bordes de los dientes", "Comparación visual mediante modelos de estudio o fotografías para evaluar la progresión", "Evaluación de la oclusión, músculos de la mandíbula y signos de bruxismo nocturno"], note: "" }, treatment: { title: "Manejo Preventivo y Restaurador", intro: "El enfoque es detener la causa y reparar el daño si es necesario:", subsections: [ { title: "Opciones Clínicas", items: ["Uso de férulas oclusales o protectores bucales nocturnos (para frenar el desgaste provocado por el bruxismo)", "Ortodoncia (si los dientes están desalineados y provocan fricciones anómalas)", "Restauraciones estéticas (resinas compuestas, carillas o coronas para reconstruir la anatomía dental perdida)", "Reposición de dientes perdidos (implantes o prótesis) para equilibrar las fuerzas masticatorias"] } ], note: "Si el desgaste llega al nervio, puede requerirse endodoncia." }, whenToSeekHelp: { title: "¿Cuándo consultar al dentista?", intro: "Es recomendable agendar una visita si:", items: ["Notas que tus dientes están notablemente más cortos, afilados o desiguales", "Sufres de sensibilidad dental aumentada al frío, calor o dulces debido a la pérdida de esmalte", "Experimentas dolor crónico en la mandíbula o dolores de cabeza por apretar los dientes"] } },
'Baja autoestima' : { intro: "La baja autoestima es una percepción negativa y desvalorizada que una persona tiene de sí misma. Quienes la experimentan dudan de sus capacidades, se critican severamente y sienten que no son dignos de amor o éxito, lo cual impacta todas las áreas de su vida.", whatIs: { title: "¿Qué es la Baja Autoestima?", text: "Es un estado psicológico caracterizado por una falta de confianza y aprecio propio. No es un trastorno mental por sí mismo, sino un síntoma o vulnerabilidad subyacente que predispone a la depresión, la ansiedad y relaciones tóxicas o de codependencia." }, types: { title: "Manifestaciones y Orígenes", intro: "Se manifiesta en patrones de comportamiento como:", items: ["Miedo excesivo al fracaso y a la crítica o rechazo (evitación)", "Necesidad constante de complacer a los demás y dificultad para establecer límites (decir 'no')", "Perfeccionismo paralizante o diálogo interno hipercrítico", "Sus orígenes suelen radicar en experiencias infantiles (abuso, abandono, acoso escolar) o traumas repetidos"], note: "" }, diagnosis: { title: "Evaluación Psicológica", intro: "El psicoterapeuta la identifica a través de:", items: ["Entrevistas clínicas para explorar el diálogo interno y las creencias nucleares de la persona", "Uso de cuestionarios validados (como la Escala de Autoestima de Rosenberg)", "Evaluación de trastornos concurrentes como depresión, ansiedad o trastornos alimentarios"], note: "" }, treatment: { title: "Reconstrucción y Terapia", intro: "Mejorar la autoestima requiere esfuerzo consciente y a menudo apoyo profesional:", subsections: [ { title: "Estrategias de Cambio", items: ["Terapia Cognitivo-Conductual (para identificar y desafiar distorsiones cognitivas y creencias limitantes)", "Práctica de la autocompasión y reestructuración del diálogo interno negativo", "Entrenamiento en asertividad y habilidades sociales (aprender a poner límites)", "Terapia de Aceptación y Compromiso (ACT)"] } ], note: "El proceso toma tiempo y no existen soluciones mágicas ni inmediatas." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda terapéutica?", intro: "Considera iniciar terapia si:", items: ["Tus sentimientos de inutilidad o inseguridad te impiden buscar empleos, relaciones o metas", "Toleras sistemáticamente el abuso físico o emocional de los demás porque crees 'merecerlo'", "Sufres de ansiedad paralizante en situaciones sociales o síntomas severos de depresión"] } },
'Esquizofrenia' : { intro: "La esquizofrenia es un trastorno mental grave y crónico que afecta la forma en que una persona piensa, siente y se comporta. Las personas que la padecen pueden parecer haber perdido el contacto con la realidad, lo que puede ser angustiante para ellos y su familia.", whatIs: { title: "¿Qué es la Esquizofrenia?", text: "Es un síndrome psiquiátrico complejo que altera la percepción de la realidad. Provoca una combinación de síntomas que interfieren drásticamente con la capacidad del individuo para funcionar en la sociedad de forma independiente." }, types: { title: "Categorías de Síntomas", intro: "Los síntomas se dividen clásicamente en:", items: ["Síntomas positivos (adiciones a la realidad: alucinaciones auditivas/visuales, delirios y pensamientos desorganizados)", "Síntomas negativos (pérdida de capacidades normales: falta de emociones, falta de motivación, aislamiento social)", "Síntomas cognitivos (problemas de memoria, atención y toma de decisiones)"], note: "Suele aparecer entre el final de la adolescencia y principios de los 30 años." }, diagnosis: { title: "Diagnóstico", intro: "Realizado por un psiquiatra, es un proceso exhaustivo:", items: ["Entrevista clínica con el paciente y su familia", "Presencia de síntomas clave durante al menos seis meses de forma continua", "Descarte del consumo de sustancias (como la metanfetamina) u otros problemas médicos que puedan causar psicosis"], note: "" }, treatment: { title: "Manejo a Largo Plazo", intro: "La esquizofrenia requiere tratamiento de por vida, incluso si los síntomas desaparecen:", subsections: [ { title: "Pilares del Tratamiento", items: ["Medicamentos antipsicóticos (pilar fundamental para controlar alucinaciones y delirios, a menudo de por vida)", "Terapia psicológica individual (Terapia Cognitivo-Conductual) y psicoeducación familiar", "Rehabilitación psicosocial y entrenamiento en habilidades para la vida independiente", "Hospitalización involuntaria (solo durante crisis agudas si hay riesgo para sí mismo o para terceros)"] } ], note: "El abandono de la medicación es la causa más común de recaídas." }, whenToSeekHelp: { title: "¿Cuándo intervenir?", intro: "La intervención temprana es crucial. Busca ayuda psiquiátrica inmediata si notas que un ser querido:", items: ["Escucha voces que nadie más escucha o cree firmemente que está siendo perseguido o espiado (paranoia extrema)", "Habla de manera incomprensible o salta ilógicamente de un tema a otro", "Presenta un aislamiento social repentino y severo junto con falta total de higiene personal"] } },
'Trastorno bipolar' : { intro: "El trastorno bipolar, antes conocido como depresión maníaca, es una enfermedad mental que causa cambios extremos en el estado de ánimo. Estos cambios incluyen altibajos emocionales, pasando de la euforia o irritabilidad extrema (manía) a la tristeza profunda (depresión).", whatIs: { title: "¿Qué es el Trastorno Bipolar?", text: "Es una afección cerebral crónica en la que los circuitos del estado de ánimo están desregulados. Los episodios anímicos pueden durar semanas o meses, y difieren significativamente de los cambios de humor normales que todas las personas experimentan." }, types: { title: "Tipos de Trastorno", intro: "Se clasifica por la intensidad de los episodios maníacos:", items: ["Trastorno Bipolar tipo I (se experimenta al menos un episodio maníaco completo, a menudo con episodios depresivos; es la forma más severa)", "Trastorno Bipolar tipo II (no hay manía completa, sino episodios de 'hipomanía' alternados con episodios de depresión mayor profunda)", "Trastorno ciclotímico (altibajos emocionales crónicos pero de menor intensidad, durante al menos dos años)"], note: "" }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "El diagnóstico es fundamentalmente clínico:", items: ["Entrevista psiquiátrica exhaustiva y evaluación del historial anímico", "Diario de seguimiento del estado de ánimo y patrones de sueño", "Descarte de trastornos de tiroides, consumo de drogas u otros trastornos psiquiátricos (como la esquizofrenia)"], note: "A menudo se diagnostica erróneamente como depresión unipolar si la persona solo consulta durante las fases bajas." }, treatment: { title: "Tratamiento y Estabilización", intro: "El objetivo es estabilizar el estado de ánimo y prevenir recaídas:", subsections: [ { title: "Opciones de Manejo", items: ["Medicamentos estabilizadores del estado de ánimo (Litio, ácido valproico, lamotrigina)", "Antipsicóticos atípicos (especialmente para controlar la manía)", "Psicoterapia (Terapia Cognitivo-Conductual, Terapia del Ritmo Interpersonal y Social para regular el sueño)", "Educación para que el paciente reconozca las señales de advertencia de un nuevo episodio"] } ], note: "Tomar antidepresivos sin un estabilizador del ánimo puede desencadenar un episodio maníaco peligroso." }, whenToSeekHelp: { title: "¿Cuándo es urgente pedir ayuda?", intro: "Solicita intervención médica o psiquiátrica de urgencia si:", items: ["La persona entra en un estado maníaco con impulsividad extrema, comportamientos de riesgo, gastos financieros desenfrenados o insomnio prolongado de varios días sin sentir cansancio", "Hay síntomas psicóticos (delirios de grandeza inamovibles)", "Aparecen ideaciones o intentos suicidas durante la fase depresiva"] } },
'Hipercolesterolemia' : { intro: "La hipercolesterolemia es la presencia de niveles elevados de colesterol en la sangre, un factor de riesgo principal para enfermedades cardíacas. El colesterol es una sustancia cerosa y similar a la grasa que el cuerpo necesita, pero en exceso se vuelve peligroso.", whatIs: { title: "¿Qué es la Hipercolesterolemia?", text: "Es una dislipidemia específica caracterizada por niveles altos de lipoproteínas de baja densidad (LDL, o colesterol 'malo'). Con el tiempo, este exceso se deposita en las paredes de las arterias (aterosclerosis), endureciéndolas, estrechándolas y bloqueando el flujo de sangre." }, types: { title: "Orígenes Frecuentes", intro: "Las causas se dividen en dos grupos:", items: ["Hipercolesterolemia poligénica o adquirida (la más común, causada por una dieta alta en grasas saturadas, inactividad física y obesidad)", "Hipercolesterolemia Familiar (HF) (un trastorno genético heredado que causa niveles extremadamente altos de LDL desde el nacimiento, resultando en infartos a edades tempranas si no se trata)"], note: "No presenta síntomas, por lo que muchas personas desconocen que la padecen hasta sufrir un infarto." }, diagnosis: { title: "Detección a través de Sangre", intro: "El único método para diagnosticarla es:", items: ["Perfil lipídico completo en sangre (mide Colesterol Total, LDL, HDL y Triglicéridos)", "Evaluación del riesgo cardiovascular global (tomando en cuenta edad, presión arterial, hábito de fumar, etc.)", "Pruebas genéticas (solo en casos sospechosos de Hipercolesterolemia Familiar)"], note: "" }, treatment: { title: "Control y Manejo", intro: "Es fundamental bajar el nivel de LDL para proteger el corazón:", subsections: [ { title: "Terapias", items: ["Cambios estrictos en la dieta (dieta mediterránea, rica en fibra, evitar grasas trans y saturadas) y ejercicio", "Medicamentos de primera línea: Estatinas (atorvastatina, rosuvastatina) para reducir la producción de colesterol en el hígado", "Medicamentos complementarios: Ezetimiba, o inyecciones de inhibidores de PCSK9 para casos resistentes o familiares"] } ], note: "El tratamiento es crónico y los medicamentos no deben suspenderse al normalizar los niveles." }, whenToSeekHelp: { title: "¿Cuándo chequear los niveles?", intro: "Se recomienda realizar un perfil lipídico si:", items: ["Eres mayor de 20 años y nunca te has hecho una prueba de colesterol", "Tienes un familiar directo que sufrió un infarto o derrame cerebral antes de los 55 años (hombres) o 65 años (mujeres)", "Padeces de diabetes, hipertensión o tienes sobrepeso"] } },
'Fracturas' : { intro: "Una fractura es la ruptura, generalmente en un hueso, causada por un traumatismo, osteoporosis o uso excesivo. Si el hueso roto rompe la piel, se denomina fractura abierta o compuesta. Las fracturas comúnmente ocurren por accidentes automovilísticos, caídas o lesiones deportivas.", whatIs: { title: "¿Qué es una Fractura?", text: "Es la pérdida de continuidad del tejido óseo. Dependiendo de la fuerza del impacto y de la resistencia del hueso, la ruptura puede ser una fisura fina o el hueso puede romperse en múltiples fragmentos (conminuta)." }, types: { title: "Clasificación de Fracturas", intro: "Existen múltiples tipos, destacando:", items: ["Fractura cerrada o simple (el hueso se rompe pero la piel permanece intacta)", "Fractura abierta o compuesta (el hueso asoma a través de la piel; alto riesgo de infección)", "Fractura por estrés (fisuras finas causadas por sobrecarga repetitiva, común en deportistas)", "Fractura patológica (causada por una enfermedad subyacente que debilita el hueso, como osteoporosis o cáncer)"], note: "" }, diagnosis: { title: "Diagnóstico Radiológico", intro: "El médico traumatólogo evaluará la lesión mediante:", items: ["Examen físico para buscar deformidades, hinchazón, hematomas y dolor al tacto", "Radiografía estándar (rayos X, el método principal y más común para confirmar fracturas)", "Tomografía computarizada (TC) o Resonancia magnética (para fracturas complejas en articulaciones o fracturas por estrés indetectables por rayos X)"], note: "" }, treatment: { title: "Manejo y Consolidación Ósea", intro: "El objetivo es realinear el hueso y mantenerlo inmovilizado hasta que sane:", subsections: [ { title: "Procedimientos", items: ["Inmovilización conservadora con yeso, férula o bota ortopédica", "Reducción cerrada (reacomodar el hueso desde el exterior bajo anestesia antes de enyesar)", "Reducción abierta y fijación interna (cirugía utilizando placas, tornillos o varillas de metal para mantener los fragmentos unidos)", "Fisioterapia post-inmovilización (esencial para recuperar fuerza y movilidad articular)"] } ], note: "El tiempo de curación varía desde unas pocas semanas hasta varios meses, dependiendo de la edad y el hueso afectado." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda de emergencia?", intro: "Llama a emergencias o acude al hospital si:", items: ["Hay un hueso asomando visiblemente a través de la piel o un sangrado abundante", "La extremidad o la articulación presenta una deformidad evidente o un ángulo antinatural", "No puedes mover o soportar peso en la zona afectada, o la extremidad debajo de la lesión se vuelve fría, pálida o azulada"] } },
'Prognatismo' : { intro: "El prognatismo es una deformidad facial que se caracteriza por la prominencia o protrusión de la mandíbula inferior o el maxilar superior. El caso más común es el prognatismo mandibular, donde la barbilla sobresale excesivamente, causando problemas estéticos y funcionales.", whatIs: { title: "¿Qué es el Prognatismo?", text: "Es una discrepancia en el crecimiento esquelético de los maxilares. Típicamente, el maxilar inferior (mandíbula) crece más de lo normal en relación con el maxilar superior, lo que da como resultado una 'mordida cruzada anterior' (los dientes inferiores quedan por delante de los superiores)." }, types: { title: "Tipos y Orígenes", intro: "Se clasifica según el hueso afectado:", items: ["Prognatismo mandibular (la mandíbula inferior está adelantada)", "Prognatismo maxilar (el maxilar superior está muy adelantado, a menudo acompañado de retrognatia mandibular)", "La causa suele ser fuertemente hereditaria (genética), pero problemas hormonales raros (como el gigantismo) pueden contribuir"], note: "Esta alteración es puramente esquelética, no solo dental." }, diagnosis: { title: "Evaluación Clínico-Radiográfica", intro: "El cirujano maxilofacial y el ortodoncista diagnostican mediante:", items: ["Análisis facial clínico y de perfil", "Radiografías cefalométricas (lateral de cráneo) para medir exactamente los ángulos de los huesos de la cara", "Modelos dentales y tomografía 3D (para planificación preoperatoria)"], note: "" }, treatment: { title: "Cirugía y Ortodoncia", intro: "El tratamiento definitivo en adultos es quirúrgico:", subsections: [ { title: "Fases del Tratamiento", items: ["En niños: Ortopedia dentofacial temprana (usar aparatos como mentoneras o máscaras faciales para frenar el crecimiento mandibular o estimular el maxilar)", "En adultos Fase 1: Ortodoncia prequirúrgica (alinear los dientes durante 1-2 años)", "Fase 2: Cirugía ortognática (cortar y reposicionar la mandíbula o el maxilar en el quirófano)", "Fase 3: Ortodoncia posquirúrgica para el ajuste fino de la mordida"] } ], note: "La cirugía mejora drásticamente no solo la estética facial, sino la respiración, el habla y la masticación." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Es recomendable pedir una evaluación si:", items: ["Observas en tu hijo un crecimiento anormal de la mandíbula inferior (la evaluación ideal es a los 7-8 años)", "Experimentas dificultad crónica para masticar, morder alimentos con los dientes frontales o problemas de habla", "Sufres de dolores articulares de la mandíbula (ATM) debido a la mala mordida o te sientes fuertemente acomplejado por tu perfil facial"] } },
'Alergias' : { intro: "Las alergias son respuestas exageradas del sistema inmunológico ante sustancias extrañas que generalmente son inofensivas para la mayoría de las personas. Estas sustancias, llamadas alérgenos, pueden incluir polen, veneno de abejas, caspa de mascotas o ciertos alimentos.", whatIs: { title: "¿Qué son las Alergias?", text: "Se trata de una hipersensibilidad del sistema inmune. El cuerpo produce anticuerpos (IgE) que identifican un alérgeno específico como dañino, liberando histamina y otras sustancias que causan inflamación en la piel, los senos paranasales, las vías respiratorias o el sistema digestivo." }, types: { title: "Tipos de Alérgenos Comunes", intro: "Las reacciones se desencadenan por diferentes vías:", items: ["Aeroalérgenos (polen, ácaros del polvo, moho, caspa de animales) causan rinitis o asma", "Alérgenos alimentarios (leche, huevos, maní, mariscos, frutos secos) causan problemas digestivos y anafilaxia", "Medicamentos (penicilina, AINEs)", "Picaduras de insectos (abejas, avispas)", "Alergias de contacto (látex, metales como el níquel, cosméticos)"], note: "" }, diagnosis: { title: "Detección", intro: "El alergólogo identifica el problema mediante:", items: ["Historia clínica detallada", "Pruebas cutáneas (Prick test o pruebas de parche para evaluar la reacción en la piel)", "Análisis de sangre para detectar anticuerpos IgE específicos (RAST)"], note: "" }, treatment: { title: "Manejo y Prevención", intro: "El objetivo es aliviar los síntomas y evitar desencadenantes:", subsections: [ { title: "Enfoque Terapéutico", items: ["Evitación estricta del alérgeno conocido", "Antihistamínicos orales, corticosteroides nasales y colirios para aliviar síntomas", "Inmunoterapia (vacunas antialérgicas) para desensibilizar el cuerpo al alérgeno a largo plazo", "Autoinyector de epinefrina de emergencia para quienes tienen riesgo de anafilaxia"] } ], note: "Las alergias pueden cambiar con el tiempo; algunas alergias infantiles se superan, mientras que otras se desarrollan en la edad adulta." }, whenToSeekHelp: { title: "¿Cuándo ir a urgencias?", intro: "La anafilaxia es una emergencia médica letal. Acude de inmediato si presentas:", items: ["Hinchazón severa de garganta, labios o lengua", "Dificultad aguda para respirar o silbidos intensos en el pecho", "Mareos severos, pérdida de conocimiento o caída brusca de la presión arterial", "Urticaria generalizada que aparece muy rápidamente tras una picadura o comida"] } },
'Impactación dental' : { intro: "La impactación dental ocurre cuando un diente no puede erupcionar correctamente y permanece atrapado en la encía o el hueso. Es una condición muy habitual que afecta predominantemente a los terceros molares (las muelas del juicio) y a los caninos.", whatIs: { title: "¿Qué es la Impactación Dental?", text: "Consiste en un bloqueo físico que impide que un diente alcance su posición funcional normal en la arcada dentaria. Esto se debe frecuentemente a la falta de espacio en los maxilares, a que el diente crece en el ángulo equivocado, o a un tejido gingival denso." }, types: { title: "Niveles de Gravedad", intro: "La impactación se evalúa según el tejido que bloquea al diente:", items: ["Impactación parcial (el diente rompe parcialmente la encía; alto riesgo de acumular comida y bacterias, causando pericoronaritis)", "Impactación de tejido blando (el diente salió del hueso, pero está cubierto de encía)", "Impactación ósea completa (el diente está totalmente incrustado dentro del hueso maxilar o mandibular)"], note: "" }, diagnosis: { title: "Diagnóstico Clínico y Radiográfico", intro: "El dentista determina el problema antes de que sea visible:", items: ["Exámenes dentales de rutina", "Radiografías panorámicas (la herramienta principal para ver el ángulo del diente y su proximidad a nervios y raíces vecinas)", "Tomografía 3D (para cirugías complejas de muelas del juicio o caninos)"], note: "A menudo se detectan asintomáticos en revisiones de adolescentes." }, treatment: { title: "Resolución Quirúrgica o de Ortodoncia", intro: "Dependerá de qué diente esté impactado y los síntomas:", subsections: [ { title: "Intervenciones", items: ["Extracción quirúrgica (tratamiento estándar y recomendado para muelas del juicio problemáticas o preventivamente)", "Cirugía para exponer el diente y tracción con ortodoncia (habitual para salvar los caninos impactados en jóvenes)", "Observación y control radiográfico anual si no causan problemas y el riesgo quirúrgico es muy alto"] } ], note: "Las extracciones de las muelas del juicio suelen tener una recuperación de pocos días." }, whenToSeekHelp: { title: "¿Cuándo programar una consulta?", intro: "Deberías acudir al dentista si experimentas:", items: ["Dolor fuerte, sordo y persistente en la parte posterior de las encías", "Encías inflamadas, rojas o sangrantes sobre el lugar donde debería estar la muela", "Dificultad o dolor al intentar abrir la boca, o un sabor desagradable constante al masticar", "Presión en la parte frontal que parece desalinear los demás dientes"] } },
'Cefalea tensional' : { intro: "La cefalea tensional es el tipo más común de dolor de cabeza, caracterizado por un dolor sordo y constante que se siente como una banda apretada alrededor de la frente, sienes o en la parte posterior de la cabeza y el cuello.", whatIs: { title: "¿Qué es la Cefalea Tensional?", text: "Es un dolor de cabeza primario, de intensidad leve a moderada, originado a menudo por la tensión crónica y contracción de los músculos del cuello, los hombros, el cuero cabelludo y la mandíbula. El estrés físico o emocional es el principal desencadenante." }, types: { title: "Tipos por Frecuencia", intro: "Se divide según la cantidad de episodios:", items: ["Cefalea tensional episódica (ocurre menos de 15 días al mes, suele durar de 30 minutos a varios días)", "Cefalea tensional crónica (ocurre más de 15 días al mes, durante al menos 3 meses consecutivos)"], note: "A diferencia de la migraña, no suele empeorar con la actividad física, no causa náuseas severas ni trastornos visuales (aura)." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico se basa en el relato de los síntomas:", items: ["Historia clínica y diario de dolores de cabeza", "Examen físico para buscar puntos sensibles (nudos musculares) en el cuello o los hombros", "Pruebas de imagen (RM o TC) solo se solicitan si hay signos de alarma que sugieran un problema cerebral subyacente"], note: "" }, treatment: { title: "Manejo y Prevención", intro: "El tratamiento se enfoca en romper el ciclo de dolor y tensión:", subsections: [ { title: "Estrategias de Alivio", items: ["Analgésicos de venta libre (paracetamol, ibuprofeno, aspirina) para episodios agudos", "Aplicación de compresas calientes o frías y masajes en cuello/hombros", "Terapia de manejo del estrés, técnicas de relajación y biorretroalimentación (biofeedback)", "Medicamentos preventivos (como antidepresivos tricíclicos) para las cefaleas crónicas"] } ], note: "El uso excesivo de analgésicos puede causar dolores de cabeza 'de rebote' (por uso excesivo de medicación)." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental acudir a urgencias o al neurólogo si:", items: ["Experimentas un dolor de cabeza repentino y severamente explosivo (el peor de tu vida)", "El dolor viene acompañado de fiebre, cuello rígido, confusión, visión doble o dificultad para hablar", "El dolor de cabeza te despierta durante la noche o empeora al toser o hacer esfuerzo"] } },
'Lesión de Manguito Rotador' : { intro: "Una lesión del manguito rotador incluye cualquier tipo de irritación o daño a los músculos o tendones que estabilizan la articulación del hombro y permiten levantar y rotar el brazo. Estas lesiones son comunes y aumentan con la edad o la práctica de ciertos deportes y trabajos.", whatIs: { title: "¿Qué es una Lesión de Manguito Rotador?", text: "Es el desgarro parcial o completo, o la inflamación grave (tendinitis), del grupo de cuatro tendones y músculos (supraespinoso, infraespinoso, redondo menor y subescapular) que abrazan la cabeza del húmero, manteniéndola en el omóplato." }, types: { title: "Causas y Tipos de Lesión", intro: "Se dividen según su origen:", items: ["Desgarros agudos (causados repentinamente por un esfuerzo excesivo, caída o accidente, frecuentes en jóvenes)", "Desgarros degenerativos crónicos (ocurren lentamente por el desgaste natural, falta de irrigación sanguínea o pinzamiento repetitivo a lo largo de los años)"], note: "El tendón del supraespinoso es el que se desgarra con mayor frecuencia." }, diagnosis: { title: "Evaluación Traumatológica", intro: "El especialista determinará la gravedad mediante:", items: ["Examen físico y pruebas de fuerza y rango de movimiento (como la prueba de Jobe)", "Radiografías (para descartar espolones óseos o artrosis)", "Ecografía o Resonancia Magnética (RM) (la RM es el estándar de oro para confirmar el tamaño y la ubicación del desgarro tendinoso)"], note: "" }, treatment: { title: "Rehabilitación o Cirugía", intro: "La mayoría de las personas se recuperan con tratamiento conservador:", subsections: [ { title: "Enfoque Terapéutico", items: ["Fisioterapia intensiva (para fortalecer los músculos circundantes del hombro y restaurar la movilidad)", "Reposo, hielo y evitar actividades por encima de la cabeza", "Infiltraciones de corticosteroides para reducir el dolor intenso y permitir la rehabilitación", "Cirugía artroscópica (para suturar el tendón rasgado, recomendada si es un desgarro grande agudo o si la fisioterapia falla tras meses)"] } ], note: "Ignorar los desgarros degenerativos crónicos puede llevar a pérdida de movimiento permanente." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca atención de un traumatólogo si:", items: ["Sientes un dolor agudo repentino y sensación de desgarro en el hombro al levantar un peso o sufrir una caída", "Tienes una debilidad profunda que te impide levantar el brazo por encima del nivel del hombro", "El dolor interrumpe tu sueño persistentemente, especialmente al intentar dormir sobre el lado afectado"] } },
'Gastroenteritis' : { intro: "La gastroenteritis es una inflamación del revestimiento del estómago y los intestinos, típicamente causada por una infección viral o bacteriana. Popularmente conocida como 'gripe estomacal', provoca episodios intensos de diarrea, vómitos y calambres abdominales.", whatIs: { title: "¿Qué es la Gastroenteritis?", text: "Es una infección gastrointestinal aguda y muy contagiosa. Su peligro principal no es la infección en sí, sino la rápida y severa pérdida de líquidos y electrolitos a través de la diarrea y el vómito, que puede provocar deshidratación grave." }, types: { title: "Agentes Causales", intro: "Se origina por contacto con personas infectadas o alimentos/agua contaminados:", items: ["Gastroenteritis viral (la más común, causada por Rotavirus en niños y Norovirus en adultos)", "Gastroenteritis bacteriana (intoxicación alimentaria causada por Salmonella, E. coli, Campylobacter o Shigella)", "Gastroenteritis parasitaria (causada por parásitos como Giardia)"], note: "No se trata de una 'gripe' real, ya que no es causada por el virus de la influenza ni afecta el sistema respiratorio." }, diagnosis: { title: "Diagnóstico", intro: "Suele diagnosticarse por los síntomas, pero en casos severos se requiere:", items: ["Examen físico para buscar signos de deshidratación severa (ojos hundidos, mucosas secas, letargo)", "Análisis de heces (coprocultivo) para identificar bacterias o parásitos si la diarrea dura muchos días", "Análisis de sangre para chequear la función renal y el nivel de electrolitos"], note: "" }, treatment: { title: "Manejo y Rehidratación", intro: "El pilar absoluto del tratamiento es prevenir y tratar la deshidratación:", subsections: [ { title: "Medidas Terapéuticas", items: ["Rehidratación oral constante (soluciones de rehidratación oral que contienen agua, azúcar y sales; evitar jugos y bebidas deportivas puras)", "Descanso estomacal inicial seguido de dieta blanda progresiva (arroz, plátano, tostadas, compota de manzana)", "Medicamentos antieméticos (para los vómitos) o antidiarreicos solo bajo recomendación médica, y evitados en niños o si hay fiebre/sangre", "Hospitalización para fluidos intravenosos en casos de deshidratación severa"] } ], note: "Los antibióticos no sirven para la gastroenteritis viral, que es la inmensa mayoría de los casos." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Es vital buscar ayuda médica si:", items: ["Eres adulto y no puedes retener líquidos por 24 horas, o un niño/bebé vomita repetidamente por varias horas", "Observas sangre o pus en las heces, o el vómito parece posos de café", "Presentas fiebre alta por encima de 39°C o 40°C", "Hay signos claros de deshidratación extrema (no orinar en horas, sequedad extrema, mareos, letargo o confusión)"] } },
'Angina' : { intro: "La angina es un tipo de dolor en el pecho causado por la reducción del flujo sanguíneo al músculo cardíaco, siendo un síntoma de enfermedad de las arterias coronarias. A menudo se describe como una sensación de presión, pesadez o compresión en el centro del pecho.", whatIs: { title: "¿Qué es la Angina de Pecho?", text: "Es una isquemia cardíaca temporal. Cuando el músculo del corazón necesita más oxígeno (por ejemplo, durante el ejercicio físico o el estrés) y las arterias parcialmente obstruidas no pueden suministrar suficiente sangre, el corazón 'protesta' con dolor." }, types: { title: "Clasificación de la Angina", intro: "Los patrones de presentación son cruciales para el manejo:", items: ["Angina estable (ocurre de forma predecible con el esfuerzo físico y desaparece rápidamente con el reposo o medicación)", "Angina inestable (ocurre de forma inesperada, incluso en reposo, los episodios duran más y son más intensos; es una emergencia pre-infarto)", "Angina variante o de Prinzmetal (causada por un espasmo arterial repentino, suele ocurrir en reposo, a menudo de madrugada)"], note: "" }, diagnosis: { title: "Evaluación Cardiológica", intro: "El cardiólogo determinará la causa y severidad mediante:", items: ["Electrocardiograma (ECG) para registrar la actividad eléctrica", "Prueba de esfuerzo (ergometría) en cinta de correr o bicicleta", "Ecocardiograma", "Angiografía coronaria o cateterismo (el método más preciso para ver las arterias bloqueadas)"], note: "" }, treatment: { title: "Tratamiento y Estilo de Vida", intro: "El objetivo es aliviar los síntomas y prevenir un ataque al corazón:", subsections: [ { title: "Abordaje Médico", items: ["Medicamentos vasodilatadores de acción rápida (nitroglicerina sublingual para detener los episodios agudos)", "Medicamentos preventivos diarios (betabloqueantes, estatinas, ácido acetilsalicílico, bloqueadores de canales de calcio)", "Cambios agresivos en el estilo de vida (dejar de fumar, dieta saludable, control de hipertensión y diabetes)", "Angioplastia y colocación de stent (para abrir arterias bloqueadas) o cirugía de bypass coronario"] } ], note: "Cualquier cambio en el patrón de dolor de una angina estable debe comunicarse al médico." }, whenToSeekHelp: { title: "¿Cuándo llamar a emergencias?", intro: "La angina inestable es una emergencia médica. Llama al 911 si:", items: ["El dolor de pecho es nuevo, inesperado o diferente de tus episodios habituales", "El dolor ocurre mientras estás en reposo absoluto", "El malestar no desaparece después de descansar o después de tomar tus dosis pautadas de nitroglicerina", "Viene acompañado de dificultad severa para respirar, sudoración fría excesiva, mareos o náuseas"] } },
'Úlceras bucales' : { intro: "Las úlceras bucales, o aftas, son pequeñas lesiones dolorosas que se desarrollan en la boca o en la base de las encías. A diferencia del herpes labial, no son contagiosas y no aparecen en la superficie exterior de los labios, pero pueden hacer que comer o hablar sea molesto.", whatIs: { title: "¿Qué son las Úlceras Bucales?", text: "Son heridas superficiales redondas u ovaladas con un centro blanco o amarillento y un borde rojo en los tejidos blandos de la boca. Aunque son muy dolorosas, la mayoría de los casos son menores y sanan solos en una o dos semanas." }, types: { title: "Clasificación", intro: "Se dividen principalmente por su tamaño y severidad:", items: ["Aftas menores (las más comunes, pequeñas, de forma ovalada, sanan sin cicatriz en 1 a 2 semanas)", "Aftas mayores (más grandes y profundas, extremadamente dolorosas, pueden tardar hasta 6 semanas en sanar y dejar cicatrices)", "Aftas herpetiformes (poco comunes, grupos de úlceras muy pequeñas que se unen formando una llaga más grande)"], note: "El estrés emocional, los traumatismos locales (como morderse la mejilla o brackets) y deficiencias vitamínicas suelen ser los desencadenantes." }, diagnosis: { title: "Diagnóstico Visual", intro: "Generalmente no requieren pruebas médicas:", items: ["El dentista o médico realiza un diagnóstico visual", "Si son muy recurrentes o severas, se pueden indicar análisis de sangre para detectar deficiencias nutricionales (B12, hierro, folato) o enfermedades sistémicas (celiaquía, Crohn)"], note: "" }, treatment: { title: "Alivio y Cicatrización", intro: "No requieren tratamiento estricto, pero los síntomas se pueden aliviar:", subsections: [ { title: "Opciones Terapéuticas", items: ["Enjuagues bucales antimicrobianos (con clorhexidina) o soluciones caseras de agua tibia con sal", "Geles o pomadas tópicas con analgésicos o corticosteroides de venta libre aplicados directamente en la lesión", "Evitar alimentos ácidos, picantes, muy salados o muy calientes que irriten la llaga", "Tratamiento sistémico con corticosteroides orales o cauterización química (solo para casos extremadamente severos indicados por el médico)"] } ], note: "Una buena higiene bucal diaria y un cepillado suave ayudan a prevenirlas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico o dentista?", intro: "Es recomendable buscar atención si:", items: ["Tienes llagas inusualmente grandes, o llagas nuevas que aparecen antes de que las viejas hayan sanado", "La úlcera no sana o no muestra signos de mejoría después de dos a tres semanas", "El dolor es intratable incluso con medicamentos analgésicos o te impide comer y beber por completo", "Están acompañadas de fiebre alta o malestar general importante"] } },
'Vértigo postural benigno' : { intro: "El vértigo posicional paroxístico benigno (VPPB) es una de las causas más comunes de vértigo, provocando episodios breves de mareos intensos que te hacen sentir que tú o el entorno están girando, desencadenados por cambios específicos en la posición de la cabeza.", whatIs: { title: "¿Qué es el VPPB?", text: "Ocurre cuando unos pequeños cristales de carbonato de calcio (otoconias) se desprenden de su lugar normal en el oído interno y se acumulan en los canales semicirculares. Al mover la cabeza, los cristales se mueven, enviando señales falsas de movimiento al cerebro." }, types: { title: "Desencadenantes Comunes", intro: "Los episodios suelen ser provocados por movimientos como:", items: ["Darse vuelta o cambiar de posición en la cama", "Inclinar la cabeza hacia atrás para mirar hacia arriba", "Agacharse rápidamente para recoger algo", "Movimientos bruscos de la cabeza al realizar deportes o tras un trauma leve"], note: "Es 'benigno' porque no pone en riesgo la vida, pero las caídas que provoca sí pueden ser peligrosas, especialmente en ancianos." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El otorrinolaringólogo o neurólogo confirmará el VPPB mediante:", items: ["La Maniobra de Dix-Hallpike (una serie de movimientos rápidos de la cabeza y el cuerpo que provocan el vértigo)", "Observación de nistagmo (movimiento rítmico y espasmódico involuntario de los ojos que ocurre durante el mareo)", "Pruebas audiológicas o vestibulares adicionales solo si el diagnóstico no es claro"], note: "" }, treatment: { title: "Maniobras de Reposicionamiento", intro: "El tratamiento es altamente efectivo y curativo en la mayoría de los casos, a menudo en una sola sesión:", subsections: [ { title: "Opciones de Manejo", items: ["Maniobra de Epley o maniobra de Semont (movimientos guiados por el médico en camilla para devolver los cristales a su lugar correcto en el oído interno)", "Ejercicios de Brandt-Daroff para realizar en casa si el médico lo recomienda", "Medicamentos supresores vestibulares (solo para aliviar las náuseas severas a corto plazo, no curan el problema)"] } ], note: "Es normal sentirse desequilibrado durante un par de días tras recolocar los cristales." }, whenToSeekHelp: { title: "¿Cuándo es urgente descartar un problema grave?", intro: "El vértigo debe evaluarse con urgencia si es un síntoma nuevo, grave o incontrolable, o si viene acompañado de signos de ACV, como:", items: ["Dolor de cabeza nuevo, diferente o severo", "Fiebre, visión doble, pérdida temporal de visión o dificultad para hablar", "Debilidad muscular en brazos o piernas, hormigueo o pérdida de audición en un oído", "Incapacidad para caminar o estar de pie sin caerse"] } },
'Infarto agudo de miocardio' : { intro: "El infarto agudo de miocardio, o ataque al corazón, ocurre cuando el flujo de sangre a una parte del corazón se bloquea por un tiempo suficiente para causar daño muscular. Es una emergencia médica crítica que requiere atención inmediata para salvar el músculo cardíaco y la vida.", whatIs: { title: "¿Qué es un Infarto de Miocardio?", text: "Suele ocurrir cuando una placa de colesterol en una arteria coronaria se rompe y se forma un coágulo de sangre que obstruye completamente el paso. Sin la sangre rica en oxígeno, el tejido del músculo cardíaco afectado (miocardio) comienza a morir irreversiblemente." }, types: { title: "Severidad y Diagnóstico", intro: "Se clasifica médicamente por lo que muestra el electrocardiograma:", items: ["Infarto con elevación del segmento ST (STEMI) (bloqueo total de una arteria principal del corazón, requiere abrir la arteria inmediatamente)", "Infarto sin elevación del segmento ST (NSTEMI) (bloqueo parcial o temporal, el daño muscular es menor pero sigue siendo grave)"], note: "Los síntomas clásicos son dolor opresivo en el pecho que se irradia al brazo izquierdo o mandíbula, pero en mujeres, ancianos y diabéticos pueden ser síntomas vagos como fatiga inusual, náuseas o falta de aire." }, diagnosis: { title: "Diagnóstico de Urgencia", intro: "El diagnóstico en sala de emergencias debe ser muy rápido:", items: ["Electrocardiograma (ECG) realizado en los primeros 10 minutos para identificar el daño eléctrico", "Análisis de sangre para medir las troponinas (enzimas cardíacas que se filtran a la sangre cuando el músculo muere)", "Ecocardiograma rápido o angiografía coronaria de urgencia"], note: "" }, treatment: { title: "Tratamiento de Emergencia (Tiempo es Músculo)", intro: "El objetivo es restaurar el flujo sanguíneo lo más rápido posible:", subsections: [ { title: "Intervenciones", items: ["Medicamentos de urgencia: Aspirina, nitroglicerina, trombolíticos (medicamentos 'destructores de coágulos' por vía intravenosa) y anticoagulantes", "Angioplastia coronaria y colocación de stent (el tratamiento preferido, realizado de urgencia mediante cateterismo para abrir la arteria obstruida)", "Cirugía de bypass coronario de emergencia (si la angioplastia no es posible o hay múltiples arterias tapadas)", "Rehabilitación cardíaca y medicación preventiva de por vida tras el alta (betabloqueantes, estatinas)"] } ], note: "Llamar a una ambulancia en lugar de conducir al hospital salva vidas, ya que los paramédicos pueden iniciar el tratamiento en el camino." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911?", intro: "Llama a emergencias de inmediato, NO esperes a ver si los síntomas pasan, si experimentas:", items: ["Dolor, presión, compresión o sensación de plenitud incómoda en el centro o el lado izquierdo del pecho que dura más de unos minutos o desaparece y vuelve", "Dolor o malestar que se irradia a uno o ambos brazos, la espalda, el cuello, la mandíbula o el estómago", "Falta de aire, con o sin malestar en el pecho", "Sudoración fría, mareos repentinos, aturdimiento extremo o náuseas/vómitos"] } },
'Dolor de cabeza por contracción muscular' : { intro: "El dolor de cabeza por contracción muscular, a menudo sinónimo de cefalea tensional, es causado por la tensión crónica de los músculos de la cabeza y el cuello. Se describe como una presión sorda y persistente o una banda apretada alrededor de la cabeza.", whatIs: { title: "¿Qué es?", text: "Es un tipo de cefalea primaria en la que el espasmo o la contractura muscular, frecuentemente desencadenados por el estrés psicológico, la mala postura, el cansancio ocular o apretar los dientes, produce un dolor leve a moderado que no empeora con la actividad física." }, types: { title: "Tipos por Frecuencia", intro: "Se divide según la cantidad de episodios:", items: ["Cefalea tensional episódica (ocurre menos de 15 días al mes, suele durar de 30 minutos a varios días)", "Cefalea tensional crónica (ocurre más de 15 días al mes, durante al menos 3 meses consecutivos)"], note: "A diferencia de la migraña, no suele empeorar con la actividad física, no causa náuseas severas ni trastornos visuales (aura)." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico se basa en el relato de los síntomas:", items: ["Historia clínica y diario de dolores de cabeza", "Examen físico para buscar puntos sensibles (nudos musculares) en el cuello o los hombros", "Pruebas de imagen (RM o TC) solo se solicitan si hay signos de alarma que sugieran un problema cerebral subyacente"], note: "" }, treatment: { title: "Manejo y Prevención", intro: "El tratamiento se enfoca en romper el ciclo de dolor y tensión:", subsections: [ { title: "Estrategias de Alivio", items: ["Analgésicos de venta libre (paracetamol, ibuprofeno, aspirina) para episodios agudos", "Aplicación de compresas calientes o frías y masajes en cuello/hombros", "Terapia de manejo del estrés, técnicas de relajación y biorretroalimentación (biofeedback)", "Medicamentos preventivos (como antidepresivos tricíclicos) para las cefaleas crónicas"] } ], note: "El uso excesivo de analgésicos puede causar dolores de cabeza 'de rebote' (por uso excesivo de medicación)." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental acudir a urgencias o al neurólogo si:", items: ["Experimentas un dolor de cabeza repentino y severamente explosivo (el peor de tu vida)", "El dolor viene acompañado de fiebre, cuello rígido, confusión, visión doble o dificultad para hablar", "El dolor de cabeza te despierta durante la noche o empeora al toser o hacer esfuerzo"] } },
'Trastornos de la ATM' : { intro: "Los trastornos de la articulación temporomandibular (ATM) causan dolor y disfunción en las articulaciones de la mandíbula y los músculos que controlan su movimiento. Son una fuente muy frecuente de dolor facial crónico y dificultades masticatorias.", whatIs: { title: "¿Qué son los trastornos de la ATM?", text: "Son problemas relacionados con la articulación 'bisagra' que conecta la mandíbula inferior con el cráneo. Pueden causar dolor crónico facial, dificultad para masticar y ruidos articulares molestos como chasquidos o estallidos." }, types: { title: "Categorías", intro: "Se dividen principalmente en tres grupos:", items: ["Trastornos musculares (dolor miofascial en los músculos de la masticación)", "Trastornos de la alteración del complejo articular (disco desplazado, dislocación de la mandíbula)", "Trastornos inflamatorios o degenerativos (osteoartritis o artritis reumatoide en la ATM)"], note: "Frecuentemente se asocian al bruxismo (apretar o rechinar los dientes)." }, diagnosis: { title: "Evaluación Odontológica", intro: "El dentista o especialista maxilofacial buscará:", items: ["Examen del rango de apertura mandibular y palpación de la musculatura facial", "Escuchar ruidos articulares durante el movimiento", "Radiografías panorámicas, Tomografía o Resonancia Magnética para ver la posición del disco y el estado del cartílago"], note: "" }, treatment: { title: "Opciones de Manejo", intro: "Suele comenzarse con tratamientos reversibles y conservadores:", subsections: [ { title: "Tratamientos", items: ["Uso de férulas oclusales o protectores bucales (guardas de relajación)", "Fisioterapia mandibular, aplicación de calor/hielo y dieta blanda", "Medicamentos (relajantes musculares, antiinflamatorios)", "Cirugía artroscópica o abierta de ATM (solo en casos graves con daño estructural que no responden a lo anterior)"] } ], note: "La cirugía es el último recurso; la mayoría mejora con cuidados conservadores." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Es recomendable buscar atención si:", items: ["Tienes dolor constante o sensibilidad crónica en la mandíbula, cara o cuello", "No puedes abrir o cerrar la boca completamente ('mandíbula trabada')", "Escuchas un chasquido al masticar que viene acompañado de dolor agudo"] } },
'Curvatura de la columna' : { intro: "La curvatura de la columna vertebral se refiere a las desviaciones anormales en la alineación natural de la espalda, que pueden afectar la postura, causar dolor y, en casos graves, comprometer el funcionamiento de los órganos internos.", whatIs: { title: "¿Qué es la Curvatura de la Columna?", text: "La columna tiene curvas naturales, pero condiciones como la escoliosis (curva lateral), la cifosis (joroba excesiva en la parte superior) o la lordosis (curva excesiva en la parte inferior) representan deformidades estructurales o posturales que requieren atención." }, types: { title: "Tipos de Curvaturas", intro: "Las tres alteraciones principales son:", items: ["Escoliosis (curvatura en forma de S o C hacia los lados, común en el crecimiento adolescente)", "Cifosis (curvatura hacia adelante de la espalda superior, causando postura encorvada)", "Lordosis o hiperlordosis (curvatura hacia adentro extrema en la zona lumbar o cervical)"], note: "Pueden ser congénitas (de nacimiento), neuromusculares o idiopáticas (causa desconocida)." }, diagnosis: { title: "Diagnóstico", intro: "El especialista en columna u ortopedista utilizará:", items: ["Examen físico, como la prueba de flexión hacia adelante de Adams (para detectar escoliosis)", "Radiografías de la columna completa de frente y de perfil para medir el ángulo de la curva (Ángulo de Cobb)", "Resonancia magnética (RM) si se sospechan problemas nerviosos o de la médula espinal"], note: "La detección temprana en la etapa escolar es clave para prevenir progresiones graves." }, treatment: { title: "Tratamiento y Corrección", intro: "Depende de la edad del paciente y la gravedad de la curva:", subsections: [ { title: "Opciones de Manejo", items: ["Observación y controles periódicos (para curvas leves)", "Fisioterapia y ejercicios específicos para fortalecer la espalda y mejorar la postura", "Uso de corsés ortopédicos (en niños en etapa de crecimiento para frenar la progresión)", "Cirugía de fusión espinal (en casos severos donde la curva amenaza la salud o empeora drásticamente)"] } ], note: "El uso de corsé no revierte la curva, pero evita que empeore." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es importante pedir una evaluación si notas:", items: ["Hombros, caderas o cintura desiguales, o si un omóplato sobresale más que el otro", "Dolor de espalda crónico que empeora con el tiempo", "Dificultad para respirar o fatiga extrema (en curvas severas que presionan los pulmones)"] } },
'Bebé prematuro' : { intro: "Un bebé prematuro es aquel que nace antes de completar las 37 semanas de gestación. Debido a que no han tenido el tiempo suficiente para desarrollarse completamente en el útero, estos recién nacidos enfrentan riesgos especiales de salud y a menudo requieren cuidados intensivos.", whatIs: { title: "¿Qué es un Bebé Prematuro?", text: "Es un neonato cuyo nacimiento se adelanta al término normal del embarazo (40 semanas). Al nacer antes de tiempo, sus órganos, especialmente los pulmones, el cerebro y el sistema digestivo, son inmaduros y vulnerables a complicaciones." }, types: { title: "Clasificación por Edad Gestacional", intro: "Se dividen según las semanas de gestación al nacer:", items: ["Prematuro extremo (nacido con menos de 28 semanas)", "Muy prematuro (nacido entre la semana 28 y la 32)", "Prematuro moderado a tardío (nacido entre la semana 32 y la 37)"], note: "Cuanto más prematuro es el bebé, mayor es el riesgo de complicaciones graves a corto y largo plazo." }, diagnosis: { title: "Evaluación Médica Inicial", intro: "El diagnóstico de prematuridad es evidente por la fecha de nacimiento, pero su estado se evalúa con:", items: ["Puntuación de Apgar al minuto y a los cinco minutos de nacer", "Monitoreo continuo en la Unidad de Cuidados Intensivos Neonatales (UCIN) de respiración, ritmo cardíaco y niveles de oxígeno", "Ecografías cerebrales, análisis de sangre y ecocardiogramas para detectar complicaciones internas"], note: "El peso al nacer también es un indicador crítico (bajo peso, muy bajo peso o peso extremadamente bajo)." }, treatment: { title: "Cuidados Neonatales", intro: "El tratamiento se centra en apoyar el desarrollo fuera del útero:", subsections: [ { title: "Medidas en la UCIN", items: ["Soporte respiratorio (ventilación mecánica o CPAP)", "Incubadoras para mantener la temperatura corporal", "Alimentación por sonda (enteral) o por vía intravenosa (parenteral) hasta que puedan succionar", "Fototerapia (luces azules) si desarrollan ictericia", "Medicación para madurar los pulmones o tratar infecciones"] } ], note: "El método 'mamá canguro' (contacto piel con piel) es vital para su estabilización cuando es seguro hacerlo." }, whenToSeekHelp: { title: "¿Cuándo preocuparse tras el alta?", intro: "Una vez en casa, llama al pediatra o ve a urgencias si el bebé:", items: ["Tiene problemas graves para respirar, pausas respiratorias largas o coloración azulada", "Rechaza el alimento repetidamente o no tiene la cantidad adecuada de pañales mojados", "Presenta fiebre (cualquier temperatura sobre 38°C en bebés pequeños es urgencia), letargo extremo o llanto inusual"] } },
'Alopecia areata' : { intro: "La alopecia areata es una afección que provoca la caída del cabello en parches redondos y bien definidos, que pueden ser del tamaño de una moneda o más grandes. Suele aparecer en el cuero cabelludo, pero puede afectar cualquier área con vello del cuerpo.", whatIs: { title: "¿Qué es la Alopecia Areata?", text: "Es un trastorno autoinmune en el cual el sistema inmunológico del propio cuerpo ataca erróneamente los folículos pilosos (las estructuras de donde crece el cabello), provocando que se encojan y detengan la producción de cabello." }, types: { title: "Variantes de la Enfermedad", intro: "Dependiendo de la extensión de la pérdida de cabello:", items: ["Alopecia areata en placas (parches focales, la presentación más común)", "Alopecia totalis (pérdida completa de todo el cabello del cuero cabelludo)", "Alopecia universalis (pérdida de todo el cabello y vello en todo el cuerpo, incluyendo cejas, pestañas y vello corporal)"], note: "La afección no destruye los folículos, por lo que el cabello tiene el potencial de volver a crecer." }, diagnosis: { title: "Diagnóstico Dermatológico", intro: "El dermatólogo la identifica mediante:", items: ["Examen visual detallado de los parches sin cabello (suelen tener una piel suave y normal sin descamación)", "Dermatoscopia (uso de una lupa especial para ver pelos en forma de 'signo de exclamación' en los bordes)", "Rara vez se necesita una biopsia de piel o análisis de sangre para descartar otras enfermedades autoinmunes como trastornos de tiroides"], note: "" }, treatment: { title: "Tratamiento y Manejo", intro: "No existe cura, pero se puede estimular el crecimiento del cabello:", subsections: [ { title: "Opciones Terapéuticas", items: ["Corticosteroides (inyectados directamente en los parches, tópicos u orales para frenar el ataque inmunológico)", "Minoxidil tópico (para estimular el crecimiento una vez frenada la inflamación)", "Inmunoterapia de contacto (provocar una reacción alérgica en el cuero cabelludo para alterar la respuesta inmune)", "Nuevos medicamentos biológicos (inhibidores de JAK) para casos severos"] } ], note: "El cabello puede volver a crecer por sí solo en muchos casos leves sin tratamiento." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es recomendable pedir una cita si:", items: ["Notas la aparición de parches de calvicie repentinos y circulares en el cuero cabelludo, barba o cejas", "La pérdida de cabello es rápida y generalizada", "Experimentas cambios en las uñas, como pequeñas abolladuras, crestas o fragilidad (común en esta afección)"] } },
'Síntomas gastrointestinales' : { intro: "Los síntomas gastrointestinales son un conjunto de molestias y señales que indican que el sistema digestivo no está funcionando correctamente. Pueden abarcar desde el esófago hasta los intestinos, siendo indicadores de trastornos transitorios o enfermedades crónicas.", whatIs: { title: "¿Qué son los Síntomas Gastrointestinales?", text: "Son manifestaciones clínicas que reflejan anormalidades en la digestión, absorción o motilidad del tracto digestivo. Pueden ser causados por infecciones, intolerancias alimentarias, estrés, inflamación o alteraciones estructurales de los órganos digestivos." }, types: { title: "Síntomas Comunes", intro: "Las presentaciones más frecuentes incluyen:", items: ["Náuseas, vómitos y acidez estomacal (pirosis)", "Dolor o calambres abdominales, pesadez y sensación de saciedad precoz", "Alteraciones en las heces: diarrea, estreñimiento o cambios en su color/textura", "Exceso de gases, flatulencia y distensión abdominal (hinchazón)"], note: "Suelen aparecer combinados en síndromes como el Colon Irritable o la Dispepsia." }, diagnosis: { title: "Evaluación Médica", intro: "Para encontrar la causa subyacente, el gastroenterólogo puede indicar:", items: ["Examen físico del abdomen y revisión detallada de la dieta y hábitos del paciente", "Análisis de sangre, heces o pruebas de aliento (para detectar H. pylori o intolerancias)", "Endoscopia o colonoscopia si hay síntomas de alarma o crónicos", "Pruebas de imagen como ecografía o tomografía computarizada"], note: "" }, treatment: { title: "Manejo y Alivio", intro: "El tratamiento es estrictamente dependiente de la causa exacta:", subsections: [ { title: "Intervenciones", items: ["Modificaciones en la dieta (eliminar lácteos, gluten, o seguir una dieta baja en FODMAPs según el caso)", "Medicamentos sintomáticos (antiácidos, antiespasmódicos, laxantes o antidiarreicos)", "Probióticos y ajuste en la hidratación", "Antibióticos o antiinflamatorios si se detecta infección o enfermedad inflamatoria intestinal"] } ], note: "Llevar un 'diario de alimentos' es fundamental para identificar qué provoca el malestar." }, whenToSeekHelp: { title: "¿Cuándo son señales de alarma?", intro: "Debes acudir al médico de inmediato si los síntomas se acompañan de:", items: ["Sangre en el vómito o en las heces (heces negras o alquitranadas)", "Pérdida de peso involuntaria y severa o dificultad persistente para tragar", "Dolor abdominal intenso, repentino o que te despierta por la noche", "Ictericia (color amarillo en piel y ojos) o fiebre alta persistente"] } },
'Verrugas' : { intro: "Las verrugas son pequeños crecimientos en la piel causados por una infección con el virus del papiloma humano (VPH). Son muy comunes, generalmente inofensivas, pero pueden resultar molestas, dolorosas o causar inseguridad estética.", whatIs: { title: "¿Qué son las Verrugas?", text: "Son lesiones cutáneas benignas (no cancerosas) que se presentan como pequeños bultos duros, a menudo con una superficie áspera o rugosa. El VPH infecta la capa superior de la piel, haciendo que crezca rápidamente. Son contagiosas por contacto directo o indirecto." }, types: { title: "Tipos de Verrugas", intro: "Se clasifican según su apariencia y ubicación:", items: ["Verrugas comunes (suelen aparecer en manos y dedos, con aspecto de coliflor)", "Verrugas plantares (crecen en las plantas de los pies, pueden doler al caminar)", "Verrugas planas (más pequeñas y lisas, frecuentes en la cara, cuello o piernas)", "Verrugas filiformes (crecimientos alargados cerca de boca, nariz o barba)", "Verrugas genitales (consideradas una ETS, requieren tratamiento médico específico)"], note: "El virus entra al cuerpo a través de cortes o grietas minúsculas en la piel." }, diagnosis: { title: "Detección Visual", intro: "El diagnóstico suele ser rápido y sencillo:", items: ["El médico o dermatólogo las identifica mediante examen visual de la piel", "Rara vez se requiere una biopsia de piel para confirmar o descartar otros tipos de crecimientos cutáneos"], note: "A menudo se aprecian pequeños puntos negros en la verruga (vasos sanguíneos coagulados)." }, treatment: { title: "Tratamiento y Eliminación", intro: "Aunque muchas desaparecen solas con el tiempo (meses o años), se pueden tratar para acelerar el proceso:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos tópicos con ácido salicílico (para destruir la verruga capa por capa)", "Crioterapia (congelación con nitrógeno líquido, muy eficaz)", "Tratamientos con láser o electrocirugía (quemarlas) para verrugas resistentes", "Cirugía menor (corte directo)"] } ], note: "No se deben intentar arrancar, cortar o morder, ya que esto propaga el virus a otras partes del cuerpo." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es recomendable visitar a un médico si:", items: ["Las verrugas duelen, sangran con facilidad o cambian rápidamente de color y forma", "Se han propagado a muchas partes de tu cuerpo o no responden a los tratamientos de venta libre", "No estás seguro de si el crecimiento es una verruga u otro tipo de lesión (como cáncer de piel)", "Tienes diabetes o problemas de inmunidad y te sale una verruga plantar"] } },
'Alopecia androgénica' : { intro: "La alopecia androgénica es la causa más común de pérdida de cabello tanto en hombres como en mujeres. Comúnmente conocida como calvicie de patrón masculino o calvicie de patrón femenino, es un proceso gradual influenciado por la genética y las hormonas.", whatIs: { title: "¿Qué es la Alopecia Androgénica?", text: "Es la miniaturización progresiva de los folículos pilosos debido a una sensibilidad genética a la hormona dihidrotestosterona (DHT). El cabello se vuelve cada vez más fino y corto en cada ciclo de crecimiento, hasta que el folículo deja de producir cabello nuevo." }, types: { title: "Diferencias de Patrón", intro: "Se manifiesta de manera distinta según el sexo:", items: ["Patrón masculino (retroceso de la línea del cabello en las sienes formando una 'M', y pérdida en la coronilla hasta la calvicie total o parcial)", "Patrón femenino (adelgazamiento difuso del cabello en la parte superior de la cabeza, manteniendo la línea frontal intacta, rara vez conduce a la calvicie total)"], note: "Es un proceso crónico e irreversible sin tratamiento." }, diagnosis: { title: "Diagnóstico Clínico", intro: "El dermatólogo especializado en tricología la identifica por:", items: ["Examen visual del patrón de pérdida de cabello y grosor del tallo capilar", "Uso de un dermatoscopio o tricoscopio para evaluar la miniaturización de los folículos", "Análisis de sangre solo si se sospecha un problema hormonal adicional en mujeres (como ovario poliquístico) o deficiencias nutricionales"], note: "" }, treatment: { title: "Tratamiento y Restauración", intro: "El objetivo es detener la caída y estimular folículos aún vivos:", subsections: [ { title: "Opciones Médicas", items: ["Minoxidil tópico u oral (vasodilatador que alarga la fase de crecimiento del cabello)", "Finasterida o Dutasterida oral (inhiben la conversión de testosterona en DHT, usados principalmente en hombres)", "Terapias con láser de baja intensidad o Plasma Rico en Plaquetas (PRP)", "Trasplante capilar (reubicación de folículos inmunes a la DHT a las zonas calvas, única solución definitiva para folículos ya muertos)"] } ], note: "Cualquier tratamiento médico para la alopecia debe usarse de forma continua; al suspenderlo, la caída se reanuda." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es el momento ideal para buscar ayuda si:", items: ["Notas que tu cabello es más fino, ves más clareos en tu cuero cabelludo o pierdes más cabello de lo habitual en la ducha/almohada", "Deseas frenar el proceso y preservar el cabello existente (el tratamiento temprano es mucho más eficaz)", "La pérdida de cabello te causa estrés emocional severo o problemas de autoestima"] } },
'Bronquitis crónica' : { intro: "La bronquitis crónica es un tipo de Enfermedad Pulmonar Obstructiva Crónica (EPOC). Consiste en la inflamación persistente de los conductos que llevan el aire a los pulmones, provocando una tos crónica que produce mucosidad y dificultad para respirar.", whatIs: { title: "¿Qué es la Bronquiolitis Crónica?", text: "Es la irritación e inflamación a largo plazo de las vías respiratorias principales de los pulmones (bronquios). Se define clínicamente como una tos con esputo (moco) que ocurre la mayoría de los días de un mes, durante al menos 3 meses al año, por dos años consecutivos." }, types: { title: "Causas y Complicaciones", intro: "Es una enfermedad progresiva y destructiva causada principalmente por irritantes:", items: ["Tabaquismo (la causa principal de casi todos los casos de bronquitis crónica)", "Exposición a largo plazo a contaminación del aire, gases tóxicos o polvo industrial", "Complicaciones frecuentes incluyen infecciones respiratorias graves recurrentes y desarrollo de enfisema pulmonar"], note: "El daño a las vías respiratorias y los cilios (pelillos que limpian el moco) no es reversible." }, diagnosis: { title: "Evaluación Neumológica", intro: "El médico especialista evaluará la función pulmonar y los síntomas:", items: ["Espirometría (prueba fundamental para medir cuánto aire exhalas y con qué rapidez, determinando el grado de obstrucción)", "Radiografía de tórax o tomografía computarizada (para descartar otras enfermedades como neumonía o cáncer de pulmón)", "Análisis de gases en sangre arterial o medición de saturación de oxígeno", "Análisis de esputo"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "No tiene cura, el objetivo es aliviar los síntomas y retrasar la progresión:", subsections: [ { title: "Intervenciones", items: ["Dejar de fumar de inmediato (el paso más importante para detener el daño)", "Medicamentos broncodilatadores inhalados y corticosteroides (para relajar las vías y reducir la inflamación)", "Rehabilitación pulmonar (ejercicios de respiración y acondicionamiento físico)", "Terapia de oxígeno (en etapas avanzadas cuando los niveles de oxígeno en sangre son peligrosamente bajos)", "Vacunación anual contra la gripe y el neumococo para prevenir infecciones letales"] } ], note: "Continuar fumando garantiza un rápido empeoramiento de la enfermedad." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca ayuda médica inmediata si experimentas:", items: ["Falta de aliento severa que no te permite hablar, caminar o realizar actividades básicas", "Coloración azulada en los labios o debajo de las uñas (cianosis)", "Un aumento drástico de la mucosidad, o esta se vuelve muy espesa, verde, amarilla o con sangre", "Hinchazón extrema de pies y tobillos (signo de fallo cardíaco secundario)"] } },
'Otitis' : { intro: "La otitis es la inflamación o infección del oído. Puede causar un dolor muy intenso, fiebre y pérdida temporal de audición. Es una de las causas más frecuentes de consulta médica, especialmente en la población infantil.", whatIs: { title: "¿Qué es la Otitis?", text: "Es una afección del oído provocada por una infección viral, bacteriana o por inflamación secundaria a retención de líquidos. El dolor surge por la presión que se acumula en las delicadas estructuras internas del oído debido al bloqueo de trompas o infección en el canal." }, types: { title: "Tipos de Otitis", intro: "Se clasifica según la porción del oído afectada:", items: ["Otitis media aguda (infección detrás del tímpano, común en niños tras un resfriado, causa acumulación de pus)", "Otitis media con derrame (líquido atrapado detrás del tímpano sin infección activa, pero reduce la audición)", "Otitis externa o 'oído de nadador' (infección en el conducto auditivo que va desde el tímpano hasta el exterior de la oreja, a menudo por agua atrapada)", "Otitis interna o laberintitis (inflamación del oído interno, causa vértigo severo y problemas de equilibrio)"], note: "" }, diagnosis: { title: "Examen Médico", intro: "El pediatra u otorrinolaringólogo diagnostica mediante:", items: ["Otoscopia (usar un instrumento con luz para ver dentro del conducto auditivo y evaluar el estado del tímpano)", "Timpanometría (para medir el movimiento del tímpano y detectar líquido detrás de él)", "Pruebas de audición (si la otitis es recurrente o el líquido no drena tras semanas)"], note: "En la otitis externa, tirar suavemente de la oreja causa un dolor muy agudo." }, treatment: { title: "Tratamiento", intro: "Depende del tipo de otitis y de si es viral o bacteriana:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Analgésicos (ibuprofeno, paracetamol) y gotas óticas analgésicas para el dolor", "Otitis media: 'Espera en observación' (si es leve, para ver si mejora sola en 48h) o antibióticos orales (amoxicilina) si es bacteriana severa", "Otitis externa: Gotas óticas con antibióticos y corticosteroides, y mantener el oído rigurosamente seco", "Tubos de timpanostomía (cirugía para colocar pequeños tubos de drenaje en el tímpano en niños con otitis medias recurrentes)"] } ], note: "Nunca se deben usar hisopos (cotonetes) para limpiar el oído infectado." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental acudir a consulta si:", items: ["El dolor de oído es intenso, constante y empeora, o si el niño está extremadamente irritable y se tira de las orejas incesantemente", "Hay supuración, secreción amarilla, verde o con sangre que sale del oído (posible tímpano perforado)", "Se acompaña de fiebre alta, hinchazón detrás de la oreja o rigidez en el cuello", "Los síntomas no mejoran después de 2 a 3 días"] } },
'Lumbalgia' : { intro: "La lumbalgia, comúnmente conocida como dolor de espalda baja, es una de las quejas médicas más frecuentes a nivel mundial. Puede variar desde un dolor sordo y constante hasta una punzada repentina que dificulta el movimiento.", whatIs: { title: "¿Qué es la Lumbalgia?", text: "Es el dolor localizado en la parte inferior de la columna vertebral (zona lumbar). La espalda baja soporta el peso de la parte superior del cuerpo y está sujeta a gran estrés mecánico, lo que la hace susceptible a tensiones, desgarros y desgaste de discos y articulaciones." }, types: { title: "Clasificación y Causas", intro: "Se divide por su duración y origen:", items: ["Lumbalgia aguda (dura menos de 6 semanas, a menudo por un tirón muscular, levantar objetos pesados o mala postura repentina)", "Lumbalgia subaguda (dura entre 6 y 12 semanas)", "Lumbalgia crónica (dura más de 3 meses, puede estar ligada a artrosis, hernia de disco, estenosis espinal o espondilolistesis)", "Dolor radicular o ciática (cuando el dolor se irradia hacia la pierna debido a la compresión de un nervio)"], note: "En la inmensa mayoría de los casos agudos, la causa es muscular o de ligamentos (mecánica)." }, diagnosis: { title: "Evaluación Médica", intro: "Para la lumbalgia inespecífica aguda rara vez se necesitan pruebas, pero si persiste:", items: ["Examen físico y neurológico (para evaluar rango de movimiento, reflejos y fuerza muscular)", "Radiografías (para ver alineación, artrosis o fracturas)", "Resonancia Magnética o Tomografía Computarizada (para visualizar hernias de disco, nervios comprimidos o músculos)", "Electromiografía (EMG) para evaluar el daño a los nervios"], note: "" }, treatment: { title: "Manejo y Recuperación", intro: "El tratamiento prioriza mantener la movilidad y reducir el dolor:", subsections: [ { title: "Estrategias Terapéuticas", items: ["Mantenerse activo en la medida de lo posible y evitar el reposo en cama prolongado (que atrofia los músculos)", "Aplicación de calor (para relajar la musculatura tensa) o hielo (en la fase aguda de inflamación)", "Analgésicos de venta libre, AINEs o relajantes musculares (por poco tiempo)", "Fisioterapia para fortalecimiento del core, estiramientos y corrección postural (el pilar del tratamiento crónico)", "Infiltraciones o cirugía (solo si existen hernias graves, debilidad progresiva o fracaso del tratamiento conservador)"] } ], note: "Cuidar la ergonomía en el trabajo y levantar peso doblando las rodillas es clave para prevenir recaídas." }, whenToSeekHelp: { title: "¿Cuándo es una señal de alarma (Banderas Rojas)?", intro: "Busca atención médica de urgencia si el dolor de espalda:", items: ["Es resultado de un traumatismo severo, caída o accidente automovilístico", "Viene acompañado de incontinencia intestinal o urinaria nueva, o retención de orina", "Sientes adormecimiento o pérdida de sensibilidad en la zona de la ingle y los glúteos ('anestesia en silla de montar')", "Se acompaña de debilidad inexplicada en las piernas, fiebre, o pérdida de peso involuntaria (podría indicar infección o tumor)"] } },
'Luxación Acromioclavicular' : { intro: "Una luxación acromioclavicular (AC), comúnmente llamada 'separación del hombro', es una lesión en la articulación donde la clavícula se une al punto más alto del omóplato (acromion). Es una lesión deportiva muy común, frecuentemente causada por caídas directas sobre el hombro.", whatIs: { title: "¿Qué es una Luxación Acromioclavicular?", text: "Es un esguince o rotura de los ligamentos que mantienen unida la clavícula al omóplato. Cuando estos ligamentos se desgarran, el peso del brazo tira del omóplato hacia abajo, causando que el extremo de la clavícula sobresalga hacia arriba, creando un bulto visible bajo la piel." }, types: { title: "Grados de Severidad", intro: "Se clasifica habitualmente en grados del I al VI, dependiendo del daño a los ligamentos acromioclaviculares (AC) y coracoclaviculares (CC):", items: ["Grado I (esguince leve, ligamentos estirados pero intactos, no hay desplazamiento óseo)", "Grado II (rotura del ligamento AC, pero el ligamento CC está intacto, ligera separación)", "Grado III (rotura completa de los ligamentos AC y CC, el hombro cae y la clavícula se levanta visiblemente)", "Grados IV, V y VI (lesiones muy severas, con gran desplazamiento de la clavícula hacia atrás, arriba o abajo; requieren cirugía)"], note: "Los grados leves son muy dolorosos pero sanan bien con reposo." }, diagnosis: { title: "Evaluación Traumatológica", intro: "El especialista diagnosticará la extensión del daño mediante:", items: ["Examen físico, buscando dolor al tacto sobre la articulación, hinchazón y la presencia de deformidad ('tecla de piano' si la clavícula se hunde al presionarla y vuelve a subir)", "Radiografías de ambos hombros (a veces con pesas colgadas de las muñecas para exagerar la separación de la articulación y confirmar la rotura de los ligamentos CC)"], note: "" }, treatment: { title: "Opciones de Tratamiento", intro: "La decisión depende del grado de la lesión y la actividad del paciente:", subsections: [ { title: "Manejo Conservador y Quirúrgico", items: ["Grados I, II y la mayoría de los III: Tratamiento no quirúrgico con cabestrillo durante varias semanas, aplicación de hielo y analgésicos", "Fisioterapia progresiva (una vez que el dolor agudo cede) para recuperar el movimiento y fortalecer los músculos del hombro que ayudarán a estabilizar la clavícula", "Cirugía (reconstrucción de los ligamentos o uso de placas/tornillos) recomendada para grados altos (IV-VI) o trabajadores/deportistas de alta demanda con lesiones grado III que no toleran la deformidad o debilidad residual"] } ], note: "Incluso con tratamiento conservador y persistencia de un 'bulto' en el hombro, la mayoría recupera la función completa y sin dolor." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Es indispensable la atención médica después del impacto si:", items: ["El dolor en el hombro es insoportable o no puedes levantar ni mover el brazo en absoluto", "Observas una deformidad obvia, un bulto puntiagudo y duro donde termina la clavícula, o si el hueso amenaza con perforar la piel", "Sientes adormecimiento, frialdad u hormigueo que desciende por el brazo hasta los dedos (podría indicar daño nervioso o vascular asociado)"] } },
'Epilepsia' : { intro: "La epilepsia es un trastorno crónico del sistema nervioso central (neurológico) en el que la actividad cerebral se vuelve anormal, lo que provoca convulsiones o períodos de comportamiento o sensaciones inusuales, y a veces pérdida de conciencia.", whatIs: { title: "¿Qué es la Epilepsia?", text: "Es una afección cerebral que predispone a las personas a tener convulsiones recurrentes no provocadas. Una convulsión es una oleada repentina y desorganizada de actividad eléctrica en el cerebro que altera temporalmente cómo una persona piensa, siente o se mueve." }, types: { title: "Tipos de Convulsiones", intro: "Se clasifican según cómo comienza la actividad anormal en el cerebro:", items: ["Convulsiones focales o parciales (la actividad anormal comienza en una sola área del cerebro, pueden ser con o sin pérdida de conciencia, alterando emociones, vista o provocando movimientos involuntarios en una parte del cuerpo)", "Convulsiones generalizadas de ausencia o 'petit mal' (mirada perdida, pequeños movimientos corporales, breves lapsos de conciencia)", "Convulsiones tónico-clónicas generalizadas o 'grand mal' (pérdida de conciencia, rigidez corporal, temblores violentos y sacudidas musculares, a menudo con pérdida del control de esfínteres)", "Acrónicas, clónicas, tónicas o mioclónicas (caídas repentinas, sacudidas o rigidez)"], note: "Tener una sola convulsión (por fiebre o golpe) no significa tener epilepsia; se requieren al menos dos convulsiones no provocadas para el diagnóstico." }, diagnosis: { title: "Evaluación Neurológica", intro: "El neurólogo determinará el tipo de epilepsia para elegir el tratamiento correcto:", items: ["Electroencefalograma (EEG) (la prueba principal, registra la actividad eléctrica del cerebro y puede mostrar anomalías incluso si no se está convulsionando)", "Pruebas de imagen cerebral (Resonancia Magnética o Tomografía Computarizada) para detectar lesiones, tumores, quistes o sangrados que puedan estar causando las convulsiones", "Examen neurológico completo e historia clínica detallada (idealmente con el relato de un testigo de las convulsiones)"], note: "" }, treatment: { title: "Manejo y Control", intro: "Aunque no hay cura, la mayoría de los pacientes pueden controlar las convulsiones:", subsections: [ { title: "Intervenciones", items: ["Medicamentos anticonvulsivos o antiepilépticos (la terapia principal, requiere ajuste preciso de dosis y constancia estricta)", "Cirugía de la epilepsia (para extirpar la pequeña porción del cerebro que genera las convulsiones, si estas no se controlan con fármacos y se originan en un área segura de intervenir)", "Estimulación del nervio vago o estimulación cerebral profunda (dispositivos tipo marcapasos implantados en el cuerpo)", "Dieta cetogénica (alta en grasas y baja en carbohidratos) usada a menudo en niños con epilepsia difícil de tratar"] } ], note: "Evitar los desencadenantes personales (como falta de sueño, estrés, luces estroboscópicas o consumo de alcohol) es clave." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Una convulsión es una urgencia (llama a una ambulancia) si:", items: ["La convulsión dura más de cinco minutos (estado epiléptico, una condición que amenaza la vida)", "La persona no recupera la conciencia o la respiración normal rápidamente después de que termina la convulsión", "Se produce una segunda convulsión inmediatamente después de la primera", "La persona está embarazada, tiene diabetes, o se lastimó durante la convulsión"] } },
'Infarto de miocardio' : { intro: "El infarto de miocardio, conocido como ataque al corazón, es una emergencia vital que ocurre cuando se interrumpe abruptamente el flujo de sangre a una parte del corazón, lo que causa la muerte o daño severo del músculo cardíaco afectado.", whatIs: { title: "¿Qué es un Infarto de Miocardio?", text: "Suele ocurrir cuando una placa de colesterol y grasa (aterosclerosis) en una arteria coronaria se rompe. Esto forma un coágulo de sangre que bloquea completamente la arteria. Sin oxígeno y nutrientes, las células del corazón comienzan a morir rápidamente." }, types: { title: "Presentación Clínica", intro: "Se diferencia médicamente según la gravedad del bloqueo:", items: ["Infarto con elevación del segmento ST (IAMCEST): El bloqueo de la arteria coronaria principal es total. Requiere atención médica inmediata y revascularización urgente.", "Infarto sin elevación del segmento ST (IAMSEST): El bloqueo es parcial o transitorio, el daño es menor pero sigue siendo una emergencia crítica.", "Infarto silencioso: Ocurre sin síntomas evidentes o con síntomas atípicos, a menudo descubierto después del hecho durante un electrocardiograma de rutina, muy común en diabéticos."], note: "Los síntomas en mujeres pueden incluir dolor de espalda, fatiga inusual y acidez estomacal, sin el dolor de pecho aplastante clásico." }, diagnosis: { title: "Diagnóstico Urgente", intro: "En la sala de emergencias, se confirma mediante:", items: ["Electrocardiograma (ECG) inmediato para identificar daños eléctricos y el tipo de infarto", "Análisis de sangre para detectar troponinas (proteínas cardíacas que se filtran a la sangre solo cuando el músculo cardíaco se daña o muere)", "Angiografía coronaria (cateterismo) para localizar y evaluar exactamente dónde está el bloqueo arterial"], note: "El factor tiempo es crucial: 'el tiempo es músculo'." }, treatment: { title: "Tratamiento y Revascularización", intro: "El objetivo es restaurar el flujo sanguíneo antes de que el daño sea irreversible:", subsections: [ { title: "Intervenciones", items: ["Medicamentos de emergencia: Trombolíticos (para disolver el coágulo), antiagregantes plaquetarios (aspirina), anticoagulantes y analgésicos.", "Angioplastia coronaria con colocación de stent (el tratamiento preferido de urgencia, se inserta un balón para abrir la arteria y se deja un tubo de malla para mantenerla abierta)", "Cirugía de revascularización coronaria (bypass) en casos donde la angioplastia no es viable o hay múltiples bloqueos severos", "Tratamiento a largo plazo: Estatinas, betabloqueantes y rehabilitación cardíaca."] } ], note: "Masticar una aspirina normal al inicio de los síntomas puede reducir el daño mientras llega la ayuda." }, whenToSeekHelp: { title: "¿Cuándo llamar a emergencias?", intro: "Llama a urgencias (no conduzcas tú mismo) inmediatamente si sientes:", items: ["Dolor o presión intensa y aplastante en el centro o lado izquierdo del pecho que dura más de unos minutos, o que se va y regresa", "Dolor que se irradia hacia la mandíbula, los dientes, el cuello, la espalda, o uno/ambos brazos (especialmente el izquierdo)", "Dificultad aguda para respirar, sudores fríos repentinos, mareos, aturdimiento extremo o sensación de muerte inminente"] } },
'Fibrilación auricular' : { intro: "La fibrilación auricular (FA) es la arritmia cardíaca grave más frecuente. Provoca un latido del corazón rápido, caótico e irregular que puede provocar coágulos de sangre en el corazón, aumentando enormemente el riesgo de sufrir un accidente cerebrovascular (ACV) y otras complicaciones cardíacas.", whatIs: { title: "¿Qué es la Fibrilación Auricular?", text: "Es un fallo en el sistema eléctrico del corazón. Las cavidades superiores (aurículas) laten sin coordinación y de forma 'temblorosa' (fibrilan) en lugar de contraerse de manera fuerte y rítmica. Debido a esto, la sangre no se vacía completamente de las aurículas y puede estancarse, formando coágulos que pueden viajar al cerebro." }, types: { title: "Patrones de la Enfermedad", intro: "Se clasifica según su duración y frecuencia:", items: ["Fibrilación auricular paroxística (episodios que aparecen y desaparecen espontáneamente, durando de unos minutos a una semana)", "Fibrilación auricular persistente (el ritmo anormal dura más de una semana y no vuelve a la normalidad por sí solo; requiere tratamiento eléctrico o médico para detenerse)", "Fibrilación auricular de larga duración o permanente (el ritmo irregular continuo no puede restablecerse y requiere manejo crónico para controlar la frecuencia cardíaca y prevenir coágulos)"], note: "El riesgo de sufrirla aumenta con la edad, la hipertensión arterial, enfermedades de válvulas y la obesidad." }, diagnosis: { title: "Detección Cardiológica", intro: "Se diagnostica evaluando la actividad eléctrica:", items: ["Electrocardiograma (ECG), que mostrará claramente la ausencia de ondas P y un ritmo caótico y desigual", "Monitor Holter o grabadora de eventos (para detectar FA paroxística que no aparece durante la consulta médica)", "Ecocardiograma (para buscar coágulos dentro de la aurícula izquierda, evaluar las válvulas y el tamaño del corazón)", "Análisis de sangre (para descartar hipertiroidismo, una causa común de FA)"], note: "" }, treatment: { title: "Control de Ritmo, Frecuencia y Prevención", intro: "El tratamiento tiene dos objetivos fundamentales: normalizar el ritmo y prevenir trombos:", subsections: [ { title: "Estrategias de Tratamiento", items: ["Anticoagulantes (la parte más crítica del tratamiento para prevenir derrames cerebrales, independientemente de si el ritmo se ha normalizado o no)", "Medicamentos para controlar la frecuencia cardíaca (betabloqueantes o bloqueadores de canales de calcio para evitar que el corazón se agote)", "Cardioversión eléctrica o farmacológica (procedimiento para 'resetear' el corazón y devolverlo al ritmo sinusal normal)", "Ablación con catéter (procedimiento quirúrgico para cicatrizar las áreas del corazón que envían las señales eléctricas caóticas)"] } ], note: "Es posible que algunas personas no sientan ningún síntoma, pero el riesgo de accidente cerebrovascular sigue siendo igual de alto." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca ayuda médica inmediata si presentas un episodio de fibrilación acompañado de:", items: ["Dificultad intensa para respirar, dolor u opresión en el pecho, o desmayos (síncope)", "Sensación repentina de que el corazón 'galopa' o late a gran velocidad en el pecho (palpitaciones sostenidas severas)", "Signos de accidente cerebrovascular: debilidad o parálisis repentina en la cara, brazo o pierna (especialmente en un lado del cuerpo), dificultad repentina para hablar, o confusión"] } },
'Cáncer de pulmón' : { intro: "El cáncer de pulmón es un tipo de cáncer que se forma en los tejidos de los pulmones, generalmente en las células que recubren los conductos de aire. Es una de las principales causas de muerte por cáncer a nivel mundial, y aunque afecta predominantemente a los fumadores, también puede presentarse en personas que nunca han fumado.", whatIs: { title: "¿Qué es el Cáncer de Pulmón?", text: "Es el crecimiento maligno y descontrolado de células anormales en uno o ambos pulmones. Estos tumores interfieren con el funcionamiento pulmonar y pueden diseminarse (hacer metástasis) fácilmente a través de los ganglios linfáticos u otros órganos del cuerpo, como el cerebro, los huesos o el hígado." }, types: { title: "Clasificación Principal", intro: "Se divide en dos grandes grupos, basados en el aspecto de las células bajo el microscopio, lo que determina cómo se tratarán:", items: ["Cáncer de pulmón de células no pequeñas (CPCNP) (el más común, alrededor del 80-85% de los casos; incluye el adenocarcinoma, el carcinoma de células escamosas y el carcinoma de células grandes. Crece y se propaga más lentamente)", "Cáncer de pulmón de células pequeñas (CPCP) (menos común, aproximadamente el 10-15% de los casos; ocurre casi exclusivamente en grandes fumadores, es muy agresivo y se disemina rápidamente)"], note: "El riesgo de desarrollar cáncer de pulmón está directamente relacionado con la cantidad de cigarrillos fumados y los años de tabaquismo." }, diagnosis: { title: "Detección y Confirmación", intro: "En las etapas tempranas suele no haber síntomas. Cuando se sospecha, las pruebas incluyen:", items: ["Tomografía computarizada (TC) de dosis baja (se usa como tamizaje en fumadores de alto riesgo, y para visualizar masas o nódulos pulmonares sospechosos)", "Radiografía de tórax (puede mostrar un tumor visible, aunque suele detectar la enfermedad en etapas más avanzadas)", "Biopsia de pulmón (extracción de una muestra de tejido mediante broncoscopia, aguja guiada por TC o cirugía, es la única forma de confirmar el cáncer celularmente)", "Citología de esputo (análisis de la mucosidad que se expulsa al toser)"], note: "" }, treatment: { title: "Enfoque Terapéutico Multidisciplinario", intro: "El tratamiento depende del tipo de cáncer, su etapa (estadio) y la salud general del paciente:", subsections: [ { title: "Opciones Oncológicas", items: ["Cirugía (extirpación del tumor, de un lóbulo pulmonar (lobectomía) o de todo el pulmón (neumonectomía), preferida en estadios tempranos)", "Radioterapia (uso de rayos X de alta energía para destruir células cancerosas, a menudo combinada con otros tratamientos)", "Quimioterapia (uso de medicamentos para matar células cancerosas en todo el cuerpo, principal tratamiento para el CPCP)", "Terapia dirigida (medicamentos que atacan mutaciones genéticas específicas de los tumores, especialmente en CPCNP)", "Inmunoterapia (estimula el sistema inmunológico del cuerpo para que reconozca y ataque el cáncer)"] } ], note: "Dejar de fumar antes del tratamiento mejora significativamente los resultados y acelera la recuperación." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Acude a un especialista en neumología u oncología si presentas síntomas persistentes, como:", items: ["Una tos nueva que no desaparece después de varias semanas, o cambios en una tos crónica (tos de fumador)", "Tos con sangre, incluso si es una pequeña cantidad (hemoptisis)", "Falta de aire recurrente, dolor en el pecho constante que empeora al respirar profundo, reír o toser", "Ronquera persistente, pérdida de peso involuntaria y severa, o dolor en los huesos (que podría indicar metástasis)"] } },
'Alergias nasales' : { intro: "Las alergias nasales, médicamente conocidas como rinitis alérgica o fiebre del heno, ocurren cuando el sistema inmunológico reacciona exageradamente a partículas suspendidas en el aire (alérgenos) que se inhalan. Provocan estornudos, secreción nasal y picazón de ojos, boca y garganta.", whatIs: { title: "¿Qué son las Alergias Nasales?", text: "Es una inflamación de las membranas mucosas que recubren la nariz. A diferencia de un resfriado común (causado por un virus), la rinitis alérgica es provocada por una respuesta alérgica a una sustancia inofensiva. El cuerpo libera histamina, causando los molestos síntomas respiratorios." }, types: { title: "Clasificación Temporal", intro: "Dependiendo de los alérgenos que la desencadenan, puede ser:", items: ["Rinitis alérgica estacional ('fiebre del heno', ocurre en épocas específicas del año cuando los árboles, pastos y malezas liberan polen o esporas de moho)", "Rinitis alérgica perenne (ocurre durante todo el año; los desencadenantes comunes incluyen ácaros del polvo, caspa de mascotas, saliva de animales, cucarachas y moho de interiores)", "Rinitis alérgica ocupacional (desencadenada por irritantes y alérgenos en el lugar de trabajo, como polvo de harina, madera o productos químicos)"], note: "Es muy común que las alergias nasales coexistan con el asma, empeorando ambas condiciones." }, diagnosis: { title: "Diagnóstico Alergológico", intro: "El alergólogo determinará los desencadenantes exactos a través de:", items: ["Historia clínica detallada sobre cuándo y dónde empeoran los síntomas (exterior, interior, cerca de animales)", "Pruebas cutáneas (Prick test) donde se introducen pequeñas cantidades de alérgenos en la piel y se observa si hay una reacción (habón)", "Prueba de sangre específica para IgE (RAST) para medir la cantidad de anticuerpos alérgicos en el torrente sanguíneo ante alérgenos concretos"], note: "" }, treatment: { title: "Manejo y Prevención", intro: "La base del tratamiento es evitar el alérgeno, combinado con medicación para aliviar los síntomas:", subsections: [ { title: "Estrategias Terapéuticas", items: ["Evitación ambiental (uso de purificadores de aire con filtro HEPA, fundas antiácaros, mantener las ventanas cerradas en días de alto polen)", "Corticosteroides nasales en aerosol (el tratamiento más eficaz para reducir la inflamación y congestión nasal)", "Antihistamínicos orales o en aerosol nasal (para controlar los estornudos, picazón y secreción nasal)", "Descongestionantes (solo para uso a corto plazo; el uso prolongado de gotas nasales puede causar efecto rebote)", "Inmunoterapia con alérgenos (vacunas para alergias o gotas sublinguales para entrenar gradualmente al sistema inmunológico a tolerar el alérgeno)"] } ], note: "Los lavados nasales diarios con solución salina son un remedio casero muy efectivo para limpiar los alérgenos y mocos." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Deberías pedir ayuda médica especializada si:", items: ["Tus síntomas son severos y no encuentras alivio con los medicamentos de venta libre", "Las alergias te impiden dormir bien o reducen drásticamente tu rendimiento en el trabajo o la escuela", "Los síntomas se complican con infecciones frecuentes de los senos paranasales (sinusitis), dolores de cabeza recurrentes o asma mal controlada", "Los medicamentos para las alergias que tomas te causan efectos secundarios molestos (como somnolencia excesiva)"] } },
'Gastritis por estrés' : { intro: "La gastritis por estrés, también conocida como lesiones de la mucosa relacionadas con el estrés (SRMD), no es la inflamación gástrica causada por el estrés emocional cotidiano, sino una condición médica aguda y severa que ocurre tras un estrés físico o fisiológico extremo en el cuerpo.", whatIs: { title: "¿Qué es la Gastritis por Estrés?", text: "Es una forma aguda de gastritis erosiva en la que el revestimiento del estómago sufre daños rápidos y úlceras múltiples debido a un trauma físico grave, quemaduras extensas, cirugías mayores, septicemia o fallo de órganos. El cuerpo, al luchar por sobrevivir, redirige el flujo sanguíneo lejos del estómago, dañando su barrera protectora." }, types: { title: "Causas y Complicaciones", intro: "Se desarrolla rápidamente en pacientes críticamente enfermos en la Unidad de Cuidados Intensivos (UCI):", items: ["Estrés fisiológico crítico (grandes quemaduras que afectan más del 30% del cuerpo, daño cerebral traumático masivo o ventilación mecánica prolongada)", "La isquemia (falta de sangre) y el exceso de ácido clorhídrico causan erosiones rápidas", "La complicación más grave es el sangrado gastrointestinal masivo, que puede ser potencialmente mortal"], note: "El estrés psicológico agudo (como ansiedad) puede causar acidez o síndrome de intestino irritable (dispepsia funcional), pero no genera úlceras o gastritis hemorrágica como el estrés físico sistémico." }, diagnosis: { title: "Diagnóstico Intrahospitalario", intro: "Dado que afecta a pacientes críticos, se diagnostica de inmediato ante signos de sangrado:", items: ["Endoscopia digestiva alta (es el estándar de oro para confirmar la presencia de múltiples erosiones sangrantes en el estómago y descartar otras causas como úlceras pépticas crónicas o várices)", "Presencia de sangre en una sonda nasogástrica o vómitos con aspecto de posos de café", "Heces alquitranadas y negras (melena) indicando sangre digerida", "Caída inexplicable en la presión arterial y en el recuento de glóbulos rojos (hemoglobina)"], note: "" }, treatment: { title: "Profilaxis y Manejo Agudo", intro: "El tratamiento primordial en la UCI es la prevención (profilaxis) antes de que ocurra el daño:", subsections: [ { title: "Intervenciones Médicas", items: ["Medicamentos supresores de ácido profilácticos (Inhibidores de la bomba de protones intravenosos o antagonistas H2) administrados a pacientes de alto riesgo al ingresar a la UCI", "Estabilización de la condición de base (restaurar el volumen de sangre, presión arterial y oxigenación para mejorar el flujo sanguíneo al estómago)", "Nutrición enteral temprana (alimentar al paciente por sonda en el tracto digestivo lo antes posible ayuda a proteger y mantener sano el revestimiento del estómago)", "En caso de sangrado activo severo, terapia endoscópica para cauterizar los vasos sangrantes o cirugía de urgencia"] } ], note: "Una vez que el paciente se recupera del evento crítico subyacente, la mucosa del estómago suele curarse rápidamente sin dejar secuelas." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Para el público general que experimenta un trauma grave o cirugía reciente, la atención de emergencia es inminente si se presenta:", items: ["Vómitos de sangre roja brillante, sangre oscura con coágulos o material que se asemeja a los granos o posos del café", "Heces de color rojo oscuro, o completamente negras y pegajosas (alquitrán) con un olor muy fétido", "Debilidad repentina, mareo severo al ponerse de pie, confusión, piel pálida, sudoración fría y desmayo (signos de choque por pérdida interna de sangre)"] } },
'Neurosis histérica' : { intro: "La 'neurosis histérica' es un término psiquiátrico histórico que ya no se utiliza en los manuales diagnósticos modernos. En la actualidad, los síntomas que antes se englobaban bajo esta etiqueta se clasifican principalmente como Trastorno de Síntomas Somáticos, Trastorno de Conversión o Trastorno Histriónico de la Personalidad.", whatIs: { title: "¿Qué es (o era) la Neurosis Histérica?", text: "Históricamente, se usaba para describir una afección en la cual una persona presentaba quejas físicas severas (como parálisis, ceguera o convulsiones) sin ninguna causa neurológica o médica comprobable. Se creía que la ansiedad extrema o un trauma emocional 'se convertían' en síntomas físicos (conversión), o que la persona buscaba atención dramáticamente (histeria)." }, types: { title: "Clasificación Actual (DSM-5)", intro: "Lo que antes era 'neurosis histérica' se diagnostica hoy de manera mucho más específica y respetuosa:", items: ["Trastorno de Síntomas Neurológicos Funcionales (Trastorno de Conversión): Presencia real de síntomas neurológicos (ceguera, parálisis, temblores) sin enfermedad física subyacente. Los síntomas son involuntarios y causan angustia real.", "Trastorno de Ansiedad por Enfermedad (antes hipocondría): Preocupación obsesiva por tener una enfermedad grave no diagnosticada.", "Trastorno Histriónico de la Personalidad: Un patrón constante de búsqueda de atención, exceso de emotividad y comportamiento teatral (histrionismo)."], note: "El término 'histeria' fue descartado por la psiquiatría moderna por ser peyorativo, sin rigor científico y tener connotaciones históricas misóginas." }, diagnosis: { title: "Evaluación Psiquiátrica y Neurológica", intro: "Es fundamental descartar cualquier enfermedad física real antes de diagnosticar estos trastornos:", items: ["Evaluación neurológica exhaustiva, Resonancia Magnética (RM) y electroencefalograma (EEG) para asegurar que la parálisis o las crisis no son epilepsia o daño nervioso", "Evaluación psiquiátrica completa para identificar traumas recientes, estrés severo, depresión subyacente o ventajas psicológicas secundarias del síntoma", "Criterios positivos del trastorno de conversión (ej. el síntoma cambia de intensidad cuando el paciente se distrae, algo que no ocurre en lesiones neurológicas reales)"], note: "" }, treatment: { title: "Tratamiento y Abordaje Terapéutico", intro: "El tratamiento requiere tacto y empatía, reconociendo que los síntomas son reales para el paciente, no fingidos:", subsections: [ { title: "Intervenciones Psicológicas y Médicas", items: ["Psicoterapia, en particular la Terapia Cognitivo-Conductual (TCC), para identificar y procesar los desencadenantes del estrés o trauma subyacente", "Fisioterapia para los síntomas motores (parálisis, problemas para caminar) con el fin de retener el movimiento normal y prevenir el debilitamiento de los músculos", "Tratamiento de afecciones psiquiátricas coexistentes (como depresión mayor o ansiedad severa) mediante antidepresivos o ansiolíticos", "Educación del paciente sobre el diagnóstico, explicando cómo el cerebro está enviando señales incorrectas al cuerpo debido a la sobrecarga emocional"] } ], note: "Es vital evitar someter al paciente a cirugías innecesarias o pruebas médicas invasivas repetitivas una vez establecido el diagnóstico." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es crucial solicitar una evaluación médica y psiquiátrica si:", items: ["Experimentas una pérdida repentina de una función corporal (como no poder mover una pierna, perder la vista o la voz) después de un evento extremadamente estresante o traumático", "Tus síntomas físicos cambian o empeoran cuando estás emocionalmente angustiado, y los médicos no han encontrado ninguna lesión que lo justifique", "Las crisis de aparente naturaleza epiléptica duran un tiempo anormalmente largo, no responden a los antiepilépticos y presentas los ojos fuertemente cerrados durante la crisis (convulsiones disociativas)"] } },
'Ausencia dentaria' : { intro: "La ausencia dentaria, médicamente conocida como agenesia dental, hipodoncia o anodoncia, es la falta de desarrollo de uno o más dientes permanentes (o, menos comúnmente, de leche). Es una anomalía del desarrollo maxilofacial bastante frecuente.", whatIs: { title: "¿Qué es la Ausencia Dentaria?", text: "Es una condición en la que el germen dental no se forma durante el desarrollo embrionario o infantil. Como resultado, el diente nunca erupciona porque simplemente no existe. Esto deja espacios (diastemas) en la sonrisa y puede afectar la forma en que el paciente muerde, mastica y habla." }, types: { title: "Clasificación Clínica", intro: "Se categoriza según la cantidad de dientes faltantes:", items: ["Hipodoncia (ausencia de 1 a 5 dientes, excluyendo los terceros molares; es la más común y afecta frecuentemente a los incisivos laterales superiores y a los segundos premolares)", "Oligodoncia (ausencia de 6 o más dientes; suele asociarse a síndromes genéticos como la displasia ectodérmica)", "Anodoncia (ausencia total y completa de todos los dientes, una condición extremadamente rara)", "Agenesia de terceros molares (ausencia de las muelas del juicio; ocurre hasta en el 20-30% de la población y suele considerarse una variante normal de la evolución humana)"], note: "Es importante distinguir la agenesia de un 'diente impactado' (que sí existe pero está atrapado bajo la encía o hueso)." }, diagnosis: { title: "Evaluación Odontológica", intro: "El diagnóstico es principalmente visual y radiográfico, a menudo descubierto en la niñez:", items: ["Retraso significativo en la caída de los dientes de leche o espacios inusuales al erupcionar los definitivos", "Radiografía panorámica dental (ortopantomografía), que permite ver de forma inmediata si los gérmenes de los dientes permanentes están ausentes en el interior del hueso mandibular o maxilar", "Evaluación ortodóntica de la mordida y el espacio disponible"], note: "" }, treatment: { title: "Manejo y Restauración Estética", intro: "El tratamiento es multidisciplinario e involucra a ortodoncistas, cirujanos e implantólogos:", subsections: [ { title: "Opciones de Tratamiento", items: ["Ortodoncia (para abrir el espacio adecuadamente y preparar el lugar para un implante futuro, o bien para cerrar el espacio y sustituir la función del diente faltante con el diente adyacente)", "Mantenimiento del diente de leche (si está sano, puede dejarse en la boca durante la edad adulta temporalmente hasta que se pueda colocar un implante)", "Implantes dentales (el tratamiento definitivo de elección una vez que el paciente finaliza su crecimiento óseo, a partir de los 18-21 años)", "Prótesis dentales fijas (puentes de Maryland o puentes tradicionales) o prótesis parciales removibles, como solución en niños o cuando los implantes no son viables"] } ], note: "La planificación temprana (en la infancia) es esencial para lograr un resultado estético y funcional óptimo en la edad adulta." }, whenToSeekHelp: { title: "¿Cuándo consultar al dentista o al odontopediatra?", intro: "Es recomendable solicitar una revisión si observas que:", items: ["El diente de leche de tu hijo se ha caído, pero han pasado muchos meses (o más de un año) sin que aparezca el diente permanente", "Un diente de leche no se afloja ni se cae mientras que los dientes vecinos de la misma etapa ya han sido reemplazados", "Hay antecedentes familiares conocidos de familiares que nunca desarrollaron ciertos dientes (la agenesia es altamente hereditaria)", "Existen problemas visibles de mala oclusión, desalineación severa, o dificultad para masticar y hablar correctamente debido a los espacios vacíos"] } },
'Desprendimiento de retina' : { intro: "El desprendimiento de retina es una afección ocular grave en la que la retina (la fina capa de tejido sensible a la luz en la parte posterior del ojo) se separa del tejido subyacente que la nutre y sostiene. Es una verdadera emergencia oftalmológica.", whatIs: { title: "¿Qué es el Desprendimiento de Retina?", text: "Es la separación física de la retina de su lecho coroideo, su principal fuente de oxígeno y nutrientes. Si no se repara de inmediato, las células de la retina mueren rápidamente por falta de irrigación sanguínea, provocando ceguera permanente y sin dolor en el ojo afectado." }, types: { title: "Causas y Tipos", intro: "Existen tres mecanismos principales que causan el desprendimiento:", items: ["Desprendimiento regmatógeno (el más común, un desgarro o agujero en la retina permite que el líquido del ojo se filtre debajo de ella, separándola)", "Desprendimiento traccional (el tejido cicatricial en la superficie de la retina, a menudo causado por la retinopatía diabética severa, se contrae y tira de la retina arrancándola de su lugar)", "Desprendimiento exudativo (líquido se acumula bajo la retina sin que haya un desgarro, causado por inflamación, tumores o enfermedades vasculares graves)"], note: "Las personas muy miopes, quienes han sufrido traumas oculares o se han sometido a cirugías previas de cataratas, tienen un riesgo mucho mayor de sufrirlo." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El oftalmólogo (preferiblemente un especialista en retina) diagnosticará la condición mediante:", items: ["Examen del fondo de ojo con pupilas dilatadas a través de un oftalmoscopio o lente especial para ver directamente el desgarro y la porción de retina suelta", "Ecografía ocular (ultrasonido del ojo) en casos donde una hemorragia interna u otras opacidades impiden ver la retina claramente", "Revisión de la agudeza visual y examen de la presión ocular (a menudo reducida en el ojo desprendido)"], note: "El médico siempre examinará exhaustivamente el otro ojo también, ya que el riesgo de desprendimiento bilateral puede ser alto." }, treatment: { title: "Cirugía de Urgencia", intro: "Casi siempre requiere reparación quirúrgica inmediata:", subsections: [ { title: "Procedimientos Quirúrgicos", items: ["Fotocoagulación con láser o criopexia (congelación) para 'soldar' los bordes de un desgarro retiniano antes de que ocurra un desprendimiento completo", "Retinopexia neumática (inyección de una burbuja de gas especial en el ojo para empujar la retina de nuevo a su lugar, combinada con láser o frío para sellarla)", "Vitrectomía (remoción del humor vítreo, el gel del interior del ojo, y a menudo su reemplazo por gas o aceite de silicona para aplanar y pegar la retina desde adentro)", "Cerclaje escleral (costura de una banda de silicona blanda alrededor de la parte exterior del ojo para empujar la pared del ojo hacia la retina desprendida)"] } ], note: "La postura estricta (boca abajo o de lado) puede ser necesaria durante días o semanas tras la cirugía para asegurar que la burbuja de gas mantenga la retina pegada." }, whenToSeekHelp: { title: "¿Cuándo acudir de inmediato a Urgencias Oftalmológicas?", intro: "El tiempo es fundamental para salvar la vista. Ve a urgencias el mismo día, preferiblemente de inmediato, si experimentas (no hay dolor, solo síntomas visuales):", items: ["La aparición repentina y sin dolor de muchísimas moscas volantes (flotadores), telarañas o puntos negros y manchas en la visión", "Destellos de luz repentinos (fotopsias) en uno o ambos ojos, especialmente si mueves la cabeza rápidamente o en la oscuridad", "La sensación de que una sombra gris o oscura, o una 'cortina' negra, cae o se corre sobre tu campo de visión, progresando de la periferia al centro", "Pérdida drástica de la visión central repentina o visión borrosa e inestable de un momento a otro"] } },
'Cáncer del colon' : { intro: "El cáncer de colon es un tipo de cáncer que comienza en el intestino grueso (colon), la parte final del tracto digestivo. Por lo general, afecta a los adultos mayores, aunque puede presentarse a cualquier edad. Es una enfermedad altamente prevenible y tratable si se detecta a tiempo.", whatIs: { title: "¿Qué es el Cáncer del Colon?", text: "Es el crecimiento maligno de células en el revestimiento del colon o del recto (cáncer colorrectal). En la gran mayoría de los casos, comienza como agrupaciones pequeñas y no cancerosas (benignas) de células llamadas pólipos. Con el tiempo (a menudo muchos años), algunos de estos pólipos adenomatosos pueden mutar y convertirse en cáncer de colon invasivo." }, types: { title: "Desarrollo y Factores de Riesgo", intro: "Se desarrolla en etapas (estadios) y está fuertemente vinculado al estilo de vida y la genética:", items: ["Estadio I al IV (indica cuán profundamente ha invadido el tumor la pared del colon y si se ha diseminado a ganglios linfáticos u otros órganos como el hígado)", "Factores de riesgo de estilo de vida: dietas bajas en fibra y muy ricas en grasas y carnes rojas/procesadas, obesidad, tabaquismo y alto consumo de alcohol", "Factores de riesgo genéticos o médicos: antecedentes familiares o personales de cáncer colorrectal o pólipos, Síndrome de Lynch, o tener Enfermedad Inflamatoria Intestinal crónica (como la colitis ulcerosa)"], note: "En etapas tempranas, los pólipos y el cáncer de colon incipiente a menudo no causan ningún síntoma en absoluto, por lo que el cribado es vital." }, diagnosis: { title: "Cribado Preventivo y Diagnóstico", intro: "La detección temprana es la herramienta más poderosa contra esta enfermedad:", items: ["Colonoscopia (la prueba estándar de oro, permite al médico ver el interior del colon completo y extirpar pólipos precancerosos en el momento antes de que se vuelvan malignos)", "Pruebas de sangre oculta en heces o pruebas de ADN en heces (métodos no invasivos para detectar signos de cáncer oculto, recomendados a partir de los 45 años)", "Pruebas de imagen como la Tomografía Computarizada (TC) de abdomen y pelvis o la Resonancia Magnética (RM) para evaluar si el cáncer se ha diseminado (estadificación)", "Análisis de sangre para medir marcadores tumorales como el Antígeno Carcinoembrionario (CEA)"], note: "" }, treatment: { title: "Tratamiento y Erradicación", intro: "Las opciones de tratamiento dependen en gran medida del estadio en que se encuentre el tumor:", subsections: [ { title: "Abordajes Oncológicos y Quirúrgicos", items: ["Polipectomía o escisión local endoscópica (durante una colonoscopia para pólipos o tumores muy tempranos confinados a la superficie)", "Colectomía parcial (cirugía para extirpar la sección del colon que contiene el cáncer junto con un margen de tejido normal y ganglios linfáticos, reconectando luego el intestino sano)", "Creación de una colostomía (generalmente temporal, rara vez permanente, para permitir que los desechos salgan del cuerpo a través del abdomen tras la cirugía)", "Quimioterapia (administrada después de la cirugía para destruir cualquier célula cancerosa oculta, o antes para encoger el tumor)", "Radioterapia (usada más frecuentemente en el cáncer de recto que en el de colon), y nuevas terapias dirigidas o Inmunoterapia para cánceres avanzados con marcadores genéticos específicos"] } ], note: "La extirpación de pólipos precancerosos durante una colonoscopia de rutina es el método principal y más eficaz para prevenir que el cáncer de colon se forme." }, whenToSeekHelp: { title: "¿Cuándo programar un examen o ir al médico?", intro: "Debes realizarte colonoscopias de cribado regularmente a partir de los 45 años, o antes si tienes antecedentes familiares. Consulta sin falta si presentas síntomas como:", items: ["Cambios persistentes e inexplicables en tus hábitos intestinales, como diarrea prolongada, estreñimiento severo, o sentir que tu intestino no se vacía completamente", "Sangrado rectal, encontrar sangre de color rojo brillante o rojo oscuro recubriendo o mezclada en las heces", "Molestias abdominales persistentes, como dolor sordo, calambres continuos o exceso de gases que no ceden", "Sensación de debilidad o fatiga extrema injustificada, o pérdida de peso rápida e involuntaria (a menudo relacionada con la pérdida de sangre microscópica en heces causando anemia)"] } },
'Enfermedad de transmisión sexual (ETS)' : { intro: "Las enfermedades de transmisión sexual (ETS), también conocidas como infecciones de transmisión sexual (ITS), son infecciones que se transmiten de una persona a otra a través del contacto sexual, incluyendo el sexo vaginal, anal y oral. Son extremadamente comunes y muchas de ellas son curables, mientras que otras son crónicas y tratables.", whatIs: { title: "¿Qué es una Enfermedad de Transmisión Sexual?", text: "Es una infección causada por bacterias, virus o parásitos que se ocultan y transmiten en la sangre, el semen, los fluidos vaginales u otros fluidos corporales. Algunas pueden transmitirse de forma no sexual, como de madre a hijo durante el embarazo o el parto, o a través de transfusiones de sangre y agujas compartidas." }, types: { title: "Agentes Causales y Tipos Frecuentes", intro: "Se clasifican fundamentalmente según el microorganismo que las causa:", items: ["Bacterianas (clamidia, gonorrea, sífilis); estas son tratables y curables con antibióticos si se detectan a tiempo", "Virales (Virus del Papiloma Humano o VPH, Herpes genital, VIH/SIDA, Hepatitis B y C); estas no tienen cura definitiva, pero sus síntomas y contagiosidad se pueden controlar y suprimir con medicamentos", "Parasitarias y fúngicas (Tricomoniasis, ladillas/piojos púbicos); altamente curables con medicamentos específicos"], note: "Muchas ITS, como la clamidia o el VPH, pueden cursar sin ningún tipo de síntoma (asintomáticas) durante meses o años, por lo que el portador puede transmitirla sin saberlo." }, diagnosis: { title: "Detección y Pruebas", intro: "El diagnóstico temprano es clave para evitar complicaciones (como la infertilidad) y frenar el contagio:", items: ["Análisis de orina (suele ser el primer paso para detectar clamidia o gonorrea)", "Análisis de sangre rápidos o de laboratorio (imprescindibles para confirmar VIH, sífilis, herpes y hepatitis)", "Muestras de fluidos (frotis o exudado) tomadas con un hisopo suave de llagas activas, de la uretra, el cuello uterino, la garganta o el ano", "Examen pélvico o examen físico visual en busca de verrugas o úlceras anormales"], note: "Las pruebas de Papanicolaou (Pap smear) regulares ayudan a detectar células cervicales anormales causadas por el VPH en las mujeres." }, treatment: { title: "Tratamiento, Manejo y Prevención", intro: "El tratamiento difiere totalmente si la infección es bacteriana o viral:", subsections: [ { title: "Opciones de Tratamiento", items: ["Antibióticos (una sola dosis o un tratamiento de varios días, usualmente por vía oral o inyección, cura infecciones como la sífilis, clamidia y gonorrea)", "Medicamentos antivirales (para suprimir el virus, mantener al mínimo los brotes de herpes y reducir la carga viral del VIH a niveles indetectables, lo que también previene la transmisión)", "Tratamiento de las parejas sexuales (es imperativo notificar y tratar a todas las parejas recientes simultáneamente para evitar la reinfección cruzada)", "Vacunación preventiva (existen vacunas altamente efectivas para el VPH, la Hepatitis A y la Hepatitis B antes de que ocurra la exposición)"] } ], note: "El uso correcto y sistemático del preservativo o condón (masculino o femenino) es el método más eficaz para reducir significativamente (aunque no al 100%) el riesgo de contraer o transmitir ETS." }, whenToSeekHelp: { title: "¿Cuándo realizarse pruebas o acudir al médico?", intro: "Si tienes una vida sexual activa (especialmente con múltiples o nuevas parejas), hazte pruebas de detección anuales. Acude de inmediato al médico si presentas:", items: ["Secreciones inusuales, de mal olor, abundantes o de color amarillo/verdoso por el pene, la vagina o el ano", "Llagas abiertas, úlceras indoloras, bultos anormales, verrugas, ronchas o ampollas en los genitales, muslos internos, boca o zona rectal", "Dolor ardiente y fuerte al orinar, o dolor pélvico profundo y anormal durante o después de las relaciones sexuales", "Erupción cutánea inusual en el cuerpo (especialmente en las palmas de las manos o plantas de los pies), que a veces se acompaña de fiebre, fatiga intensa y ganglios inflamados (signos de sífilis avanzada o infección por VIH)"] } },
'Bradicardia' : { intro: "La bradicardia es una frecuencia cardíaca inusualmente lenta, definida en adultos como una frecuencia en reposo inferior a los 60 latidos por minuto. Para algunas personas, como los atletas jóvenes en buena forma física, un ritmo lento es normal y saludable; pero en otras, puede ser el signo de un problema eléctrico en el corazón.", whatIs: { title: "¿Qué es la Bradicardia?", text: "Es un tipo de arritmia que ocurre cuando las señales eléctricas que controlan el ritmo cardíaco se retrasan o se bloquean. Si el corazón late demasiado despacio, no puede bombear suficiente sangre rica en oxígeno al cerebro y al resto del cuerpo, provocando síntomas debilitantes." }, types: { title: "Causas y Disfunciones Eléctricas", intro: "Puede estar causada por daños en el tejido cardíaco debidos al envejecimiento, infartos o defectos congénitos:", items: ["Disfunción del nódulo sinusal (el marcapasos natural del corazón no genera los impulsos a un ritmo adecuado, común en ancianos)", "Bloqueo auriculoventricular o bloqueo cardíaco (las señales eléctricas generadas no se transmiten correctamente desde las cavidades superiores a las inferiores del corazón)", "Medicamentos (es una respuesta secundaria común a fármacos para la presión arterial o el corazón, como los betabloqueantes o digoxina)", "Causas sistémicas (como hipotiroidismo severo, apnea obstructiva del sueño o desequilibrios de electrolitos)"], note: "Se clasifica en bloqueos de primer, segundo o tercer grado (este último es un bloqueo completo y una emergencia médica)." }, diagnosis: { title: "Diagnóstico Cardiológico", intro: "El médico especialista evaluará el ritmo de forma continua:", items: ["Electrocardiograma (ECG) (la prueba principal y más importante para registrar la actividad y bloqueos eléctricos en reposo)", "Monitor Holter o grabadora de eventos (dispositivos portátiles que el paciente lleva consigo durante 24 horas o más para atrapar la bradicardia intermitente o los desmayos)", "Ecocardiograma (ultrasonido para descartar problemas estructurales o valvulares en el corazón)", "Prueba de la mesa inclinada (Tilt test) si el paciente experimenta desmayos inexplicables"], note: "" }, treatment: { title: "Manejo y Corrección", intro: "Si la bradicardia no causa síntomas, por lo general no se trata. Si es grave o sintomática, las opciones son:", subsections: [ { title: "Intervenciones", items: ["Ajuste o suspensión de medicamentos (si el ritmo lento es un efecto secundario de fármacos recetados, el cardiólogo cambiará el tratamiento o la dosis)", "Tratamiento de la enfermedad subyacente (como recetar hormona tiroidea si el problema es hipotiroidismo)", "Implantación de un marcapasos definitivo (una pequeña cirugía menor en la que se coloca debajo de la piel del pecho un dispositivo alimentado por batería que envía impulsos eléctricos para acelerar el ritmo cuando detecta que el corazón late muy lentamente)"] } ], note: "Una vez colocado un marcapasos, los síntomas de fatiga y mareos suelen desaparecer inmediatamente." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia o señal de alarma?", intro: "Llama a urgencias médicas (911) o acude a un hospital inmediatamente si el ritmo cardíaco lento viene acompañado de:", items: ["Desmayos bruscos (síncope) o episodios en los que casi pierdes el conocimiento de manera recurrente", "Dolor u opresión en el pecho intensa que se extiende hacia el brazo, cuello o espalda", "Dificultad severa para respirar, aturdimiento extremo o confusión mental repentina", "Debilidad paralizante que te impide realizar tus tareas básicas o pararte"] } },
'Cáncer renal' : { intro: "El cáncer renal o cáncer de riñón es una enfermedad en la que las células sanas de uno o ambos riñones se vuelven malignas, crecen sin control y forman un tumor. A menudo se detecta de manera incidental (por accidente) al realizar pruebas de imagen por otros motivos médicos.", whatIs: { title: "¿Qué es el Cáncer Renal?", text: "Es el crecimiento maligno originado en los conductos muy pequeños de los riñones que filtran y limpian la sangre. Si no se trata, este tumor puede invadir la vena cava inferior, propagarse a los ganglios linfáticos cercanos o hacer metástasis hacia los pulmones y huesos." }, types: { title: "Tipos Histológicos y Riesgos", intro: "Se clasifica según el tipo de célula donde se origina:", items: ["Carcinoma de células renales (CCR) (el tipo más común en adultos, representa aproximadamente el 90% de los casos; suele aparecer como un solo tumor en un riñón)", "Carcinoma de células transicionales (se origina en la zona donde el uréter se conecta al riñón)", "Tumor de Wilms (nefroblastoma) (el tipo más común de cáncer renal infantil, aparece en niños muy pequeños)"], note: "El tabaquismo, la obesidad, la hipertensión prolongada y la exposición a ciertos químicos industriales en el trabajo duplican el riesgo de padecerlo." }, diagnosis: { title: "Detección y Estadificación", intro: "El urólogo u oncólogo se apoyará en pruebas de imagen detalladas:", items: ["Tomografía computarizada (TC) de abdomen y pelvis o Resonancia Magnética (RM) (para determinar el tamaño exacto, la forma, la profundidad del tumor y si se ha diseminado a otras áreas)", "Ecografía abdominal (útil para diferenciar entre quistes benignos llenos de líquido y tumores renales sólidos cancerosos)", "Análisis de sangre y orina (buscan rastros de sangre invisible a simple vista y evalúan la función renal)", "Biopsia de riñón (en algunos casos, pero no siempre es necesaria si las imágenes por TC son lo suficientemente claras antes de operar)"], note: "No existen pruebas de laboratorio de 'cribado' (screening) de rutina para la población general." }, treatment: { title: "Enfoques Quirúrgicos y Oncológicos", intro: "El tratamiento primario casi siempre implica cirugía, ya que los cánceres de riñón típicos no responden muy bien a la quimioterapia tradicional:", subsections: [ { title: "Opciones Terapéuticas", items: ["Nefrectomía parcial (cirugía conservadora donde se extirpa solo el tumor y un margen de tejido sano, preservando el resto del riñón funcional; es el tratamiento preferido si es posible)", "Nefrectomía radical (extirpación quirúrgica completa del riñón, la glándula suprarrenal y los tejidos circundantes; a menudo por laparoscopia)", "Ablación por radiofrecuencia (calor) o crioterapia (congelamiento) (para tumores muy pequeños en pacientes mayores que no tolerarían una cirugía mayor)", "Terapia dirigida e Inmunoterapia (medicamentos orales o intravenosos que bloquean señales que permiten a los vasos sanguíneos nutrir el tumor, fundamentales para cánceres avanzados o metastásicos)"] } ], note: "Una persona puede vivir una vida perfectamente normal y saludable con un solo riñón." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico urgentemente?", intro: "El cáncer de riñón temprano rara vez causa molestias. Debes acudir al especialista inmediatamente si notas síntomas de etapas más avanzadas, como:", items: ["Presencia de sangre en la orina (hematuria) sin dolor aparente; la orina puede verse de color rosa, rojo brillante o color té negro", "Un dolor sordo, constante y persistente en la parte baja de un lado de la espalda, justo debajo de las costillas (dolor en el flanco), que no mejora con reposo", "Palpar una masa abultada o un bulto anormal en el costado o el abdomen", "Pérdida rápida de peso involuntaria, fiebre recurrente por las noches (sin infección) y fatiga extrema"] } },
'Enfermedad de Parkinson' : { intro: "La enfermedad de Parkinson es un trastorno progresivo y crónico del sistema nervioso central que afecta primariamente al movimiento y al control muscular. Los síntomas comienzan gradualmente, a veces empezando con un temblor apenas perceptible en una sola mano, y empeoran con el paso de los años.", whatIs: { title: "¿Qué es la Enfermedad de Parkinson?", text: "Es una enfermedad neurodegenerativa causada por la muerte paulatina de ciertas células nerviosas (neuronas) en una zona del cerebro llamada sustancia negra. Al morir, estas neuronas dejan de producir dopamina, un mensajero químico vital que coordina los movimientos suaves y equilibrados del cuerpo." }, types: { title: "Síntomas Motores y No Motores", intro: "La enfermedad se manifiesta de dos maneras distintas que impactan la calidad de vida:", items: ["Síntomas motores principales: Temblores de reposo (como el movimiento de 'contar monedas' con los dedos), bradicinesia (lentitud extrema de movimiento), rigidez muscular o engranaje, e inestabilidad postural (problemas de equilibrio)", "Síntomas no motores o invisibles: Trastornos severos del sueño (actuar los sueños durante la fase REM), pérdida del sentido del olfato (anosmia), estreñimiento crónico, cambios en la voz, y eventualmente problemas cognitivos, depresión y ansiedad"], note: "Aunque la edad avanzada (más de 60 años) y los antecedentes genéticos son factores de riesgo, existen casos de Parkinson de inicio temprano." }, diagnosis: { title: "Evaluación Neurológica", intro: "El diagnóstico es eminentemente clínico; no existe una única prueba de laboratorio o escáner que ofrezca un diagnóstico definitivo de Parkinson:", items: ["Evaluación por parte de un neurólogo especialista en trastornos del movimiento, basada en el historial médico detallado, revisión de signos y síntomas, y un extenso examen neurológico y físico", "Prueba con Carbidopa-Levodopa (se le administra el medicamento al paciente, y si sus síntomas motores mejoran significativamente, el diagnóstico de Parkinson se confirma con gran fiabilidad)", "DaTSCAN (un escáner cerebral por imagen (SPECT) que ayuda a visualizar el sistema de transporte de dopamina, usado solo si hay dudas diagnósticas con otros temblores esenciales)"], note: "" }, treatment: { title: "Manejo Integral y Farmacológico", intro: "El Parkinson no tiene cura, pero la medicina moderna puede aliviar notablemente los síntomas y mantener la calidad de vida durante mucho tiempo:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Medicamentos dopaminérgicos: Levodopa (el fármaco principal y más eficaz, que el cerebro convierte en dopamina), agonistas de la dopamina, y los inhibidores de la MAO-B y de la COMT (que evitan que el cerebro descomponga la dopamina natural o medicada)", "Estimulación Cerebral Profunda (DBS): Cirugía en la que los cirujanos implantan electrodos en una parte específica del cerebro para enviar impulsos eléctricos que bloquean los temblores severos y la rigidez", "Terapias físicas y de apoyo: Fisioterapia para problemas de marcha y equilibrio, terapia ocupacional, y logopedia para tratar los problemas de habla y de deglución", "Ejercicio aeróbico regular (estudios demuestran que ralentiza la progresión funcional de la enfermedad)"] } ], note: "Con el paso de los años, los medicamentos pueden empezar a perder eficacia y producir fluctuaciones motoras o movimientos involuntarios agitados (discinesias)." }, whenToSeekHelp: { title: "¿Cuándo pedir una consulta neurológica?", intro: "Es recomendable solicitar una evaluación especializada si observas señales de advertencia tempranas como:", items: ["Un ligero temblor o sacudida rítmica en un dedo, pulgar, mano o mentón mientras la extremidad está completamente relajada o en reposo", "Tu escritura a mano se ha vuelto progresivamente mucho más pequeña y apretada que en el pasado (micrografía)", "Pierdes el balanceo automático de los brazos al caminar, arrastras un poco un pie, o te sientes rígido al intentar levantarte de una silla", "Aparición de un rostro inexpresivo ('máscara') donde parpadeas menos de lo normal, o hablas en un tono de voz monótono y bajo"] } },
'Quistes ováricos' : { intro: "Los quistes ováricos son sacos o bolsas llenas de líquido o material semisólido que se forman sobre o dentro de la superficie de uno de los ovarios. Son sumamente comunes y, en la inmensa mayoría de los casos en mujeres en edad reproductiva, son benignos, indoloros y desaparecen por sí solos sin tratamiento.", whatIs: { title: "¿Qué son los Quistes Ováricos?", text: "Son formaciones que surgen generalmente como resultado normal del ciclo menstrual mensual (quistes funcionales). En cada ciclo crece un folículo para liberar un óvulo; si este folículo sigue creciendo o se sella tras soltar el óvulo reteniendo líquido, se forma un quiste temporal." }, types: { title: "Clasificación por Origen", intro: "Se dividen principalmente entre quistes vinculados al ciclo menstrual y otros menos comunes:", items: ["Quistes funcionales (quistes foliculares o del cuerpo lúteo): Son los más frecuentes, totalmente inofensivos y suelen resolverse solos en uno o dos ciclos", "Quistes dermoides (teratomas): Contienen tejido como pelo, piel o dientes, ya que se forman a partir de células embrionarias; raramente son cancerosos", "Cistadenomas: Quistes que se desarrollan en la superficie externa del ovario, llenos de material acuoso o mucoso; pueden volverse muy grandes", "Endometriomas ('quistes de chocolate'): Causados por la endometriosis cuando el tejido uterino crece y sangra dentro del ovario"], note: "Tener múltiples quistes pequeños frecuentemente está asociado al Síndrome de Ovario Poliquístico (SOP)." }, diagnosis: { title: "Evaluación Ginecológica", intro: "A menudo se detectan de manera rutinaria durante un examen pélvico anual o un chequeo, tras lo cual se indican:", items: ["Ecografía pélvica y transvaginal (la herramienta principal y más importante para confirmar la presencia del quiste, ver si es líquido, sólido o mixto, e identificar su ubicación exacta)", "Prueba de embarazo (para descartar que la causa sea un embarazo ectópico o para confirmar un quiste del cuerpo lúteo)", "Análisis de sangre CA 125 (un marcador tumoral, utilizado principalmente si la mujer ha pasado la menopausia o si el quiste se ve sólido y sospechoso en la ecografía)"], note: "En mujeres posmenopáusicas, cualquier quiste nuevo requiere vigilancia más estrecha debido a un riesgo ligeramente mayor de malignidad." }, treatment: { title: "Vigilancia y Tratamiento", intro: "El tratamiento depende directamente del tamaño, el tipo de quiste, la edad de la paciente y sus síntomas:", subsections: [ { title: "Medidas y Procedimientos", items: ["Espera vigilante o 'actitud expectante' (el ginecólogo recomendará repetir la ecografía en unos meses para verificar si el quiste funcional ha desaparecido solo)", "Anticonceptivos hormonales (píldoras, para evitar que se desarrollen y formen nuevos quistes funcionales en los ciclos siguientes, aunque no encogen los existentes)", "Laparoscopia quirúrgica mínimamente invasiva (para extirpar quistes mediante pequeñas incisiones si son muy grandes, causan mucho dolor crónico o parecen sospechosos)", "Laparotomía o cistectomía mayor (cirugía abierta para extirpar el quiste intacto si existe preocupación de cáncer)"] } ], note: "La cirugía a menudo puede limitarse a extirpar solo el quiste, preservando el tejido del ovario sano intacto." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia ginecológica?", intro: "Si bien los quistes funcionales suelen ser silenciosos, debes acudir a Urgencias de inmediato si un quiste grande se rompe o provoca la torsión (giro) del ovario, lo que corta su flujo sanguíneo. Busca ayuda si tienes:", items: ["Dolor pélvico o abdominal repentino, extremadamente intenso y agudo (como un cuchillazo) en un lado inferior", "Dolor severo acompañado de fiebre inexplicable, náuseas violentas o vómitos", "Dolor pélvico repentino acompañado de debilidad extrema, aturdimiento profundo, mareo, desmayo o respiración rápida (signos de hemorragia interna)"] } },
'Melasma' : { intro: "El melasma es un problema muy común y crónico de la piel que provoca la aparición de manchas oscuras, difusas e irregulares. Afecta predominantemente a las mujeres (especialmente mujeres jóvenes en edad fértil con tonos de piel más oscuros) y es altamente resistente al tratamiento.", whatIs: { title: "¿Qué es el Melasma?", text: "Es una afección de hiperpigmentación donde los melanocitos (las células que dan color a la piel) se vuelven hiperactivos y producen demasiada melanina en ciertas áreas expuestas. Suele denominarse 'el paño' o la 'máscara del embarazo' y no causa dolor físico, solo impacto cosmético y psicológico." }, types: { title: "Ubicación y Desencadenantes", intro: "Las manchas, de color marrón, grisáceo o bronceado oscuro, suelen aparecer simétricamente en el rostro:", items: ["Patrón facial central (frente, mejillas, puente nasal y labio superior, es el más común)", "Factores hormonales (el desencadenante más fuerte: el embarazo, el uso de pastillas anticonceptivas, terapias de reemplazo hormonal y el uso de DIU hormonales)", "Exposición al sol y al calor extremo (la luz ultravioleta y la luz azul visible estimulan directamente a los melanocitos, empeorando y reactivando la condición de inmediato)", "Irritación (ciertos cosméticos agresivos o terapias con láser que producen mucho calor pueden causar inflamación que empeora las manchas)"], note: "El melasma que surge durante el embarazo a menudo desaparece gradualmente (meses después del parto), pero otros casos duran años o toda la vida." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El diagnóstico clínico es generalmente directo y visual:", items: ["El dermatólogo observa las áreas hiperpigmentadas del rostro", "Uso de la Lámpara de Wood (una luz ultravioleta especializada que permite al médico ver qué tan profundo ha penetrado la melanina extra en la piel, diferenciando entre melasma epidérmico superficial y dérmico profundo)", "Muy rara vez se requiere biopsia cutánea (solo si hay dudas de que la mancha pudiera ser otro trastorno grave de la piel)"], note: "" }, treatment: { title: "Cuidado y Aclarado de la Piel", intro: "El melasma es crónico y difícil de eliminar permanentemente; el tratamiento exige mucha paciencia y una combinación de terapias:", subsections: [ { title: "Protocolos Terapéuticos", items: ["Protección solar estricta, férrea y diaria (el paso más crítico: usar protectores solares minerales de amplio espectro, preferiblemente con óxido de hierro/zinc que bloqueen la luz visible, y sombreros grandes)", "Agentes despigmentantes tópicos (cremas recetadas con Hidroquinona, Ácido Tranexámico, Ácido Kójico, o Ácido Azelaico para bloquear la producción de melanina nueva)", "Cremas con retinoides (Tretinoína) y corticosteroides suaves para acelerar la renovación celular de la piel", "Peelings químicos superficiales o Microneedling (para exfoliar suavemente la capa superior de la piel manchada, siempre realizado por un experto)"] } ], note: "Ciertos tratamientos con láser agresivos están contraindicados para el melasma, ya que el calor intenso puede 'quemar' y oscurecer el rostro aún más de manera permanente (hiperpigmentación postinflamatoria)." }, whenToSeekHelp: { title: "¿Cuándo acudir al dermatólogo?", intro: "Es recomendable pedir una consulta especializada si:", items: ["Las manchas oscuras en tu rostro persisten después del parto o al dejar de tomar medicamentos anticonceptivos hormonales", "Los productos blanqueadores de venta libre irritan tu piel, empeorando el aspecto de las manchas", "La apariencia de las manchas cutáneas te está causando gran angustia psicológica o estrés social crónico", "Deseas recibir cremas aclaradoras recetadas más fuertes y seguras, bajo vigilancia médica"] } },
'Gastroenteritis aguda' : { intro: "La gastroenteritis aguda, a menudo referida como 'gripe estomacal', es la inflamación repentina del revestimiento del tracto digestivo. Es una infección muy común y contagiosa, que provoca episodios repentinos e intensos de diarrea acuosa, cólicos estomacales y vómitos.", whatIs: { title: "¿Qué es la Gastroenteritis Aguda?", text: "Es una irritación del estómago e intestinos causada típicamente por una infección viral (o, menos comúnmente, bacterias o parásitos). Esta irritación provoca un tránsito rápido del contenido intestinal y la incapacidad de absorber el agua adecuadamente, resultando en diarrea intensa." }, types: { title: "Agentes Causales y Trasmisión", intro: "Generalmente se contrae por ingerir agua o alimentos contaminados, o por contacto directo o indirecto con personas infectadas:", items: ["Norovirus (la causa más común de gastroenteritis viral en adultos en todo el mundo, muy contagiosa en espacios cerrados)", "Rotavirus (principal causa de gastroenteritis infantil grave, aunque ahora es prevenible mediante vacunación)", "Infecciones bacterianas o intoxicaciones alimentarias (causadas por E. coli, Salmonella, Campylobacter, tras consumir carne o aves crudas, o huevos en mal estado)", "Parásitos como Giardia o Criptosporidio (adquiridos generalmente al beber agua contaminada de arroyos o piscinas)"], note: "El mayor riesgo y complicación de todos los tipos de gastroenteritis, independientemente de la causa, es la deshidratación rápida y potencialmente mortal." }, diagnosis: { title: "Evaluación Médica", intro: "Suele diagnosticarse por el cuadro clínico y su duración; sin embargo, si los síntomas son severos o prolongados, se indica:", items: ["Evaluación física para buscar signos de deshidratación grave (ojos hundidos, mucosas secas, letargo o latido acelerado)", "Análisis de heces o coprocultivo (para identificar la presencia de bacterias o parásitos patógenos, especialmente si el paciente tiene fiebre alta o ha viajado al extranjero)", "Análisis de sangre para chequear el nivel de electrolitos y la función del riñón (si hay signos de deshidratación)"], note: "Los episodios virales comunes no requieren pruebas de heces de rutina." }, treatment: { title: "Manejo Domiciliario y Rehidratación", intro: "Al no existir un medicamento para curar el virus, la meta primordial es reponer fluidos y mantener el equilibrio del cuerpo:", subsections: [ { title: "Estrategias de Cuidado", items: ["Rehidratación oral constante (soluciones de suero oral de farmacia; se debe evitar el agua pura en grandes cantidades, los jugos azucarados, los refrescos o las bebidas deportivas, ya que pueden empeorar la diarrea osmótica)", "Descanso gástrico inicial seguido de una dieta blanda astringente progresiva (arroz blanco, tostadas, compota de manzana, plátano, caldos claros)", "Antieméticos recetados (para detener vómitos persistentes y permitir que el paciente beba líquidos)", "Medicamentos antidiarreicos (como la loperamida, solo en adultos sin fiebre ni sangre en heces, y bajo consejo médico; no se recomiendan para bacterias o toxinas, ya que el cuerpo necesita expulsarlas)", "Uso cauteloso de antibióticos (estrictamente solo si un análisis de heces confirma que la causa es bacteriana o parasitaria específica)"] } ], note: "El lavado riguroso de manos y superficies es la única forma eficaz de prevenir contagios intrafamiliares." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda de urgencia?", intro: "Acude inmediatamente al médico o al servicio de urgencias si:", items: ["Un adulto es incapaz de retener ningún líquido (vomita todo lo que bebe) durante 24 horas, o un niño/bebé durante varias horas", "Observas deposiciones diarreicas negras y alquitranadas o mezcladas con abundante sangre roja visible, o si el vómito contiene sangre", "Presentas fiebre alta por encima de 39.5°C o 40°C", "Notas síntomas evidentes de deshidratación profunda: sed extrema, no orinar en más de 6 horas en adultos o falta de pañales mojados en bebés, llanto sin lágrimas, aturdimiento agudo, debilidad extrema o confusión"] } },
'Disoclusión de los dientes' : { intro: "La disoclusión de los dientes, también descrita genéricamente dentro del marco de la 'maloclusión severa' o falta de contacto oclusal, ocurre cuando los dientes superiores e inferiores pierden su capacidad de engranar o contactar de forma correcta y equilibrada al cerrar la boca, afectando las funciones masticatorias.", whatIs: { title: "¿Qué es la Disoclusión Dental?", text: "Es la pérdida del contacto anatómico o de la guía fisiológica entre los arcos dentarios oclusales. Dependiendo de cómo se produzca, un paciente puede presentar incapacidad para juntar ciertos dientes al masticar, desgastes destructivos anormales o problemas crónicos en la articulación de la mandíbula (ATM)." }, types: { title: "Manifestaciones Clínicas", intro: "Esta disfunción del contacto dental puede ser un problema aislado o el resultado de múltiples factores:", items: ["Disoclusión traumática o interferencia oclusal (un solo diente hace contacto antes que los demás al cerrar, creando un trauma y desplazando la mandíbula)", "Disoclusión posterior por mordida abierta anterior (los dientes anteriores no contactan, concentrando la presión destructiva solo en las muelas)", "Disoclusión anterior por mordida abierta posterior (los molares pierden el contacto natural)", "Pérdida de 'guía canina' (los caninos, que deberían desenganchar los molares durante el movimiento lateral de la mandíbula, están desgastados o fuera de posición, causando daños a todo el arco)"], note: "Pérdidas dentales no reemplazadas o el bruxismo severo suelen ser grandes promotores de disoclusiones secundarias." }, diagnosis: { title: "Diagnóstico Clínico y Funcional", intro: "El odontólogo, especialmente un especialista en prostodoncia o rehabilitador oral, la detectará mediante:", items: ["Análisis de la oclusión utilizando papel de articular especial para marcar los puntos prematuros de contacto al masticar o rechinar", "Palpación de la articulación temporomandibular (ATM) y la musculatura facial para detectar espasmos musculares asociados al trauma", "Montaje de modelos en articulador semiajustable (para reproducir los movimientos de la mandíbula fuera de la boca del paciente)", "Radiografías periapicales y panorámicas para revisar el daño de las raíces (ensanchamiento del espacio periodontal) o del hueso debido al trauma de la mala mordida"], note: "" }, treatment: { title: "Restauración y Rehabilitación Oral", intro: "El objetivo es devolver un contacto simultáneo, armónico y equilibrado a toda la boca:", subsections: [ { title: "Tratamientos Odontológicos", items: ["Ajuste oclusal o tallado selectivo (desgaste mínimo de los puntos de esmalte de los dientes que están chocando prematuramente)", "Rehabilitación oral compleja (uso de coronas, carillas o incrustaciones de porcelana para reconstruir los dientes desgastados y devolver la altura y guía perdida de la mordida)", "Tratamiento de Ortodoncia (para mover los dientes mal posicionados de vuelta a una alineación funcional correcta)", "Uso de férulas de descarga neuromiorrelajantes nocturnas (para proteger el nuevo trabajo dental, relajar los músculos tensos de la cara y desprogramar las mandíbulas que rechinan)", "Reposición protésica o implantes (para reemplazar las muelas perdidas y evitar el colapso y migración de los dientes restantes)"] } ], note: "Tratar una disoclusión a tiempo evita dolores crónicos intratables de cabeza y cuello relacionados con la mandíbula." }, whenToSeekHelp: { title: "¿Cuándo programar una evaluación profunda?", intro: "Es fundamental consultar con un dentista restaurador si notas:", items: ["Dolor o fatiga persistente en los músculos de la cara y las mandíbulas, sobre todo por las mañanas al despertar, acompañado a veces de dolor de cabeza en las sienes", "Sientes que tu mordida ha 'cambiado' y no sabes dónde colocar cómodamente tu mandíbula al cerrar la boca", "Tus dientes están astillándose, acortándose y muestran áreas amarillentas de dentina desgastada expuesta", "Se te ha caído un empaste o corona repetidamente y sin motivo aparente (fuerte indicativo de interferencia en la mordida)"] } },
'Pólipos nasales' : { intro: "Los pólipos nasales son crecimientos blandos, indoloros y no cancerosos que se desarrollan en el revestimiento interno de los conductos nasales o de los senos paranasales. Parecen uvas o pequeñas lágrimas que cuelgan del techo de la nariz y son una causa muy común de congestión nasal crónica intratable.", whatIs: { title: "¿Qué son los Pólipos Nasales?", text: "Son el resultado final de un proceso de inflamación crónica en la mucosa respiratoria. Cuando los conductos nasales están constantemente irritados por alergias o infecciones crónicas, el tejido se hincha, se llena de líquido y se descuelga formando estas masas grises y lisas que terminan bloqueando las vías respiratorias y de drenaje nasal." }, types: { title: "Condiciones Asociadas", intro: "Cualquiera puede desarrollarlos, pero su crecimiento es muy característico en personas con afecciones subyacentes que producen inflamación persistente:", items: ["Sinusitis crónica (infección e inflamación a largo plazo, de más de 12 semanas)", "Asma (un porcentaje significativo de adultos asmáticos sufren de poliposis nasal)", "Sensibilidad severa a la aspirina u otros AINEs como el ibuprofeno (Tríada de Samter, que es asma, pólipos y sensibilidad a la aspirina)", "Rinitis alérgica severa, infecciones fúngicas nasales crónicas o fibrosis quística"], note: "A diferencia del cáncer o los tumores nasales, que suelen crecer en un solo lado y sangrar, los pólipos benignos crecen casi siempre en ambas fosas nasales, tienen forma de lágrima y no duelen ni sangran al tacto." }, diagnosis: { title: "Evaluación y Visualización", intro: "El otorrinolaringólogo (especialista en nariz, garganta y oído) confirmará el diagnóstico a través de:", items: ["Examen físico directo del interior de la nariz con un otoscopio o rinoscopio", "Endoscopia nasal (el estudio clave: se introduce un tubo estrecho y flexible con luz y cámara en la nariz para ver profundamente en los senos y localizar todos los pólipos ocultos)", "Tomografía Computarizada (TC) de los senos paranasales (para mapear el tamaño exacto, la ubicación profunda de los pólipos y planificar antes de una cirugía, además de descartar tumores óseos)", "Pruebas de alergia (para encontrar qué desencadena la inflamación crónica que los alimenta)"], note: "" }, treatment: { title: "Control Médico y Cirugía", intro: "El objetivo es reducir la inflamación crónica y encoger los pólipos para recuperar la capacidad de respirar y oler, aunque la tasa de recurrencia es extremadamente alta:", subsections: [ { title: "Opciones Terapéuticas", items: ["Corticosteroides nasales en aerosol, gotas o lavados nasales medicados (primera línea de defensa para desinflamar el tejido y encoger pequeños pólipos)", "Corticosteroides orales (ciclos cortos de prednisona oral recomendados solo si los pólipos son severos y no responden a los aerosoles)", "Nuevos medicamentos biológicos inyectables (como dupilumab) para personas con pólipos nasales graves crónicos que también padecen de asma", "Cirugía endoscópica de los senos paranasales (FESS) (si los medicamentos fallan, se introduce un endoscopio en la fosa nasal sin incisiones externas, y se utiliza un microinstrumento para cortar, raspar y limpiar los pólipos bloqueadores de la cavidad)"] } ], note: "Sin un manejo de mantenimiento continuo estricto (uso diario de aerosoles y lavados salinos) tras la cirugía, es altamente probable que los pólipos vuelvan a crecer rápidamente." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico especialista?", intro: "Es prudente solicitar una cita si tus síntomas persisten durante semanas y no mejoran con los medicamentos para el resfriado de venta libre:", items: ["Tienes una congestión o bloqueo nasal profundo, severo y prolongado, por lo que debes respirar obligatoriamente por la boca día y noche", "Experimentas pérdida gradual o completa del sentido del olfato o del gusto, de manera persistente", "Tienes goteo posnasal crónico y constante presión o dolor sordo alrededor de la frente, encima de las mejillas o los dientes superiores", "Presentas empeoramiento inusual repentino del asma, visión doble repentina o hinchazón progresiva alrededor de los ojos (señales graves que requieren revisión de emergencia)"] } },
'Laringitis' : { intro: "La laringitis es la inflamación de la laringe (la caja de resonancia o 'caja de la voz'), que aloja las cuerdas vocales en la parte superior del cuello. Normalmente provoca ronquera profunda, o en casos más graves, la pérdida temporal pero total de la voz.", whatIs: { title: "¿Qué es la Laringitis?", text: "Ocurre cuando las cuerdas vocales, que son dos pliegues de membrana mucosa que vibran para emitir sonido, se inflaman o irritan excesivamente. Al hincharse, los sonidos se distorsionan a medida que el aire pasa sobre ellas, lo que resulta en una voz ronca, raspante o apenas audible." }, types: { title: "Tipos y Desencadenantes", intro: "Dependiendo del tiempo de duración y la causa de la irritación, la laringitis puede ser:", items: ["Laringitis aguda y transitoria (la forma más frecuente, suele deberse a infecciones virales como el resfriado común o la gripe, o al uso excesivo de la voz gritando o animando en un concierto)", "Laringitis crónica (dura más de tres semanas sin parar; las causas más comunes incluyen el reflujo ácido crónico por enfermedad por reflujo gastroesofágico (ERGE), tabaquismo severo persistente, goteo posnasal por sinusitis, o irritantes químicos inhalados repetidamente en el trabajo)", "Laringitis por crecimiento (lesiones vocales) (uso inadecuado y forzado continuo de la voz que produce la formación de nódulos de tejido duro, pólipos blandos o quistes directamente en la superficie vibratoria de las cuerdas)"], note: "En los niños pequeños, una forma específica de laringitis aguda causa el síndrome de crup, caracterizado por una tos ronca que suena como el 'ladrido' de una foca y puede dificultar la respiración." }, diagnosis: { title: "Evaluación Médica Otorrinolaringológica", intro: "El especialista evaluará las cuerdas vocales si la ronquera se prolonga de manera preocupante:", items: ["Historial médico minucioso para detectar problemas digestivos (reflujo) o hábitos perjudiciales", "Examen físico del cuello, palpando y escuchando la respiración y el tono de la voz", "Laringoscopia indirecta o con fibra óptica flexible (el médico inserta un tubo minúsculo e iluminado con una cámara por la fosa nasal o por la garganta para mirar directamente cómo se mueven e interactúan las cuerdas vocales y comprobar si hay inflamación roja o bultos inusuales)", "Rara vez biopsia de las cuerdas, reservada únicamente si el especialista sospecha de la presencia del cáncer de garganta o laringe"], note: "" }, treatment: { title: "Recuperación, Reposo y Prevención", intro: "Para la forma aguda viral o por exceso de uso, el remedio principal no son los medicamentos, sino el cuidado conservador extremo del aparato vocal:", subsections: [ { title: "Medidas Terapéuticas Clave", items: ["Reposo estricto y total de la voz (lo más crítico: hablar lo menos posible y no susurrar, ya que el susurro genera una presión y tensión antinatural aún mayor sobre las cuerdas inflamadas)", "Aumentar la humedad e hidratación extrema (inhalar vapor o aire de humidificadores y beber cantidades copiosas de agua tibia, nunca bebidas con cafeína o alcohol, que resecan mucho más la garganta)", "Tratamiento de las causas subyacentes crónicas (medicamentos antiácidos agresivos para controlar el daño causado por el reflujo gástrico diario, o abstinencia inmediata del tabaco)", "Corticosteroides (pastillas como la prednisona, utilizados exclusivamente por médicos en casos de emergencia y necesidad extrema donde el paciente, como un cantante profesional u orador, requiere restaurar temporalmente la voz para un evento imprescindible o en niños con crup para desinflamar vías cerradas)", "Terapia de la voz con logopeda (para personas con laringitis crónica para reeducar la técnica y aprender patrones de respiración y habla saludables sin golpear las cuerdas)"] } ], note: "Aclararse o carraspear fuertemente la garganta cuando está seca causa una fuerte fricción dañina y empeora directamente la hinchazón." }, whenToSeekHelp: { title: "¿Cuándo es peligroso y debes buscar a un especialista?", intro: "Solicita ayuda urgente o programa una cita médica inmediata si presentas los siguientes síntomas graves:", items: ["Ronquera incesante o cambios extraños de la voz que duran persistentemente más de dos semanas completas en adultos (puede ser una señal de alerta temprana de un tumor benigno, parálisis de cuerdas o cáncer laringeo)", "Una sensación punzante prolongada de que tienes un 'bulto' atorado al tragar, o expulsas mocos teñidos de sangre al toser", "En el caso de niños o bebés, si presentan un sonido estridente de pitido y áspero muy fuerte al inhalar el aire (estridor), comienzan a babear excesivamente y no pueden tragar saliva, desarrollan una tos de ladrido ininterrumpida o tienen evidente y grave dificultad para respirar de forma súbita (urgencia letal por cierre de vías aéreas o epiglotitis)"] } },
'Depresión mayor' : { intro: "La depresión mayor es un trastorno de salud mental caracterizado por un estado de ánimo profunda y persistentemente deprimido, acompañado de una pérdida de interés en las actividades cotidianas. Afecta drásticamente la forma en que la persona siente, piensa y maneja sus actividades diarias.", whatIs: { title: "¿Qué es la Depresión Mayor?", text: "Es una enfermedad clínica severa que va más allá de la tristeza temporal. Involucra alteraciones en los neurotransmisores del cerebro y afecta el sueño, el apetito, la energía y la autoestima, prolongándose por al menos dos semanas consecutivas." }, types: { title: "Subtipos", intro: "Puede presentarse con diferentes características:", items: ["Depresión con características melancólicas (tristeza profunda, peor por la mañana)", "Depresión con características psicóticas (presencia de delirios o alucinaciones)", "Depresión atípica (reactividad del estado de ánimo, aumento de peso y sueño)", "Depresión de patrón estacional (ocurre en ciertas épocas del año)"], note: "Es una de las principales causas de discapacidad en el mundo." }, diagnosis: { title: "Diagnóstico", intro: "Un psiquiatra o psicólogo clínico evalúa mediante:", items: ["Entrevista clínica exhaustiva basada en los criterios del DSM-5", "Cuestionarios de evaluación de la depresión (ej. PHQ-9, Escala de Beck)", "Exámenes de sangre para descartar causas físicas como hipotiroidismo o deficiencia de vitaminas"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "La combinación de terapias suele ser el enfoque más efectivo:", subsections: [ { title: "Estrategias", items: ["Antidepresivos (ISRS, IRSN, que pueden tardar semanas en hacer efecto completo)", "Psicoterapia (Terapia Cognitivo-Conductual, Terapia Interpersonal)", "Terapia Electroconvulsiva (TEC) o Estimulación Magnética Transcraneal (en casos graves o resistentes)", "Modificaciones en el estilo de vida (ejercicio, higiene del sueño)"] } ], note: "El apoyo familiar y la adherencia al tratamiento son fundamentales para la recuperación." }, whenToSeekHelp: { title: "¿Cuándo es urgente?", intro: "Debes buscar ayuda inmediata si:", items: ["Sientes que la vida no vale la pena o tienes pensamientos activos sobre el suicidio", "Estás planeando o has intentado hacerte daño a ti mismo o a otros", "Presentas síntomas de desconexión con la realidad (psicosis)"] } },
'Incontinencia urinaria de esfuerzo' : { intro: "La incontinencia urinaria de esfuerzo es la pérdida involuntaria de orina que ocurre cuando un movimiento o actividad física ejerce presión (estrés) sobre la vejiga. Es muy común, especialmente en mujeres después del parto o en la menopausia.", whatIs: { title: "¿Qué es la Incontinencia de Esfuerzo?", text: "Ocurre cuando los músculos del suelo pélvico o el esfínter urinario están debilitados. Acciones cotidianas que aumentan la presión abdominal provocan que la vejiga filtre orina, ya que la válvula no puede mantenerse cerrada." }, types: { title: "Desencadenantes", intro: "Las fugas suelen ocurrir durante actividades como:", items: ["Toser, estornudar o reír", "Levantar objetos pesados", "Hacer ejercicio, saltar o correr", "Levantarse de una silla o agacharse"], note: "Se diferencia de la incontinencia de urgencia, que es una necesidad repentina e incontrolable de orinar." }, diagnosis: { title: "Evaluación Médica", intro: "El urólogo o ginecólogo realizará:", items: ["Examen físico pélvico y prueba de la tos (pedir al paciente que tosa con la vejiga llena)", "Análisis de orina para descartar infecciones", "Estudio urodinámico (para medir la presión en la vejiga y el flujo de orina)", "Ecografía pélvica o medición del residuo posmiccional"], note: "" }, treatment: { title: "Opciones Terapéuticas", intro: "El tratamiento va de menos a más invasivo:", subsections: [ { title: "Medidas y Cirugía", items: ["Ejercicios de Kegel (fortalecimiento del suelo pélvico, a menudo con fisioterapia especializada)", "Biorretroalimentación (biofeedback) o estimulación eléctrica", "Uso de pesarios vaginales (dispositivos para sostener la vejiga)", "Cirugía de cabestrillo o malla suburetral (para dar soporte a la uretra)"] } ], note: "Bajar de peso y dejar de fumar (para reducir la tos crónica) mejoran enormemente los síntomas." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable buscar ayuda si:", items: ["La pérdida de orina interfiere con tus actividades diarias, vida social o ejercicio", "Te causa angustia emocional o te obliga a usar compresas absorbentes a diario", "Sientes dolor al orinar o ves sangre en la orina (señales de otra afección)"] } },
'Cáncer del cuello uterino' : { intro: "El cáncer de cuello uterino (cáncer cervical) es un tipo de cáncer que se produce en las células del cuello del útero, la parte inferior del útero que se conecta con la vagina. Es altamente prevenible mediante vacunación y cribado regular.", whatIs: { title: "¿Qué es el Cáncer del Cuello Uterino?", text: "Es el crecimiento maligno de las células cervicales, casi siempre causado por una infección persistente y a largo plazo con ciertos tipos de alto riesgo del Virus del Papiloma Humano (VPH). Tarda años en desarrollarse desde células precancerosas hasta cáncer invasivo." }, types: { title: "Tipos Celulares", intro: "Se clasifica según el tipo de célula en la que comenzó:", items: ["Carcinoma de células escamosas (el más común, alrededor del 80-90%, comienza en las células delgadas y planas del exterior del cuello uterino)", "Adenocarcinoma (comienza en las células glandulares productoras de mucosidad en el canal cervical)", "Carcinomas mixtos (tienen características de ambos)"], note: "En sus etapas iniciales y precancerosas, generalmente no presenta síntomas." }, diagnosis: { title: "Detección y Diagnóstico", intro: "La prevención es clave a través de pruebas de detección:", items: ["Prueba de Papanicolaou (Pap smear) para encontrar células anormales antes de que sean cáncer", "Prueba de ADN del VPH", "Colposcopia (si las pruebas previas son anormales, el ginecólogo usa una lente de aumento especial para ver el cuello uterino)", "Biopsia (extracción de tejido para confirmar el cáncer en laboratorio)"], note: "" }, treatment: { title: "Tratamiento", intro: "Las opciones dependen del estadio y de si la mujer desea tener hijos en el futuro:", subsections: [ { title: "Abordajes Oncológicos", items: ["Cirugía conservadora (conización) o Histerectomía simple/radical", "Radioterapia (a menudo combinada con quimioterapia, puede usarse como tratamiento principal en etapas avanzadas)", "Quimioterapia (para reducir tumores grandes o tratar el cáncer diseminado)", "Terapia dirigida o Inmunoterapia (en cánceres recurrentes o metastásicos)"] } ], note: "La vacuna contra el VPH aplicada en la preadolescencia puede prevenir la mayoría de los casos de este cáncer." }, whenToSeekHelp: { title: "¿Cuándo consultar al ginecólogo?", intro: "Debes buscar atención médica fuera de tus chequeos rutinarios si presentas:", items: ["Sangrado vaginal anormal (después de las relaciones sexuales, entre períodos menstruales o después de la menopausia)", "Flujo vaginal acuoso, con sangre, abundante y que puede tener un olor fétido", "Dolor pélvico persistente o dolor intenso durante las relaciones sexuales"] } },
'Bursitis' : { intro: "La bursitis es una afección dolorosa que afecta a las pequeñas bolsas llenas de líquido (bursas) que proporcionan amortiguación a los huesos, tendones y músculos alrededor de las articulaciones. Ocurre cuando estas bolsas se inflaman.", whatIs: { title: "¿Qué es la Bursitis?", text: "Es la inflamación e irritación de una bursa, a menudo como resultado de movimientos repetitivos, presión constante, traumas o, en ocasiones, enfermedades inflamatorias subyacentes o infecciones." }, types: { title: "Ubicaciones Frecuentes", intro: "Puede ocurrir en cualquier articulación, pero es más común en:", items: ["Hombro (bursitis subacromial)", "Codo (bursitis del olécranon o 'codo de estudiante')", "Cadera (bursitis trocantérea)", "Rodilla (bursitis prerrotuliana o 'rodilla de sirvienta')", "Talón (bursitis retrocalcánea)"], note: "Suele estar asociada a tendinitis en la misma articulación." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico suele ser clínico:", items: ["Examen físico palpando la articulación para detectar calor, hinchazón y puntos de dolor específicos", "Ecografía o Resonancia Magnética (si el diagnóstico no es claro o para descartar desgarros de tendones)", "Extracción y análisis de líquido de la bursa (si se sospecha que la bursitis es por infección o gota)"], note: "" }, treatment: { title: "Manejo y Alivio", intro: "El tratamiento inicial busca reducir la inflamación:", subsections: [ { title: "Medidas Conservadoras", items: ["Reposo y protección de la articulación afectada (uso de rodilleras o coderas)", "Aplicación de hielo y medicamentos antiinflamatorios (AINEs)", "Fisioterapia para fortalecer los músculos circundantes", "Infiltración con corticosteroides (una inyección directa en la bursa alivia rápidamente el dolor)", "Cirugía o drenaje (rara vez necesario, salvo en bursitis infectadas o crónicas severas)"] } ], note: "Continuar con la actividad que causó la bursitis retrasará significativamente la curación." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Es recomendable solicitar atención si:", items: ["Tienes dolor articular incapacitante o que inmoviliza por completo la zona", "Observas una hinchazón excesiva, enrojecimiento intenso, hematomas o un bulto muy caliente", "El dolor se acompaña de fiebre (señal de bursitis séptica/infectada, requiere urgencia)"] } },
'Disfunción eréctil' : { intro: "La disfunción eréctil (DE), o impotencia, es la incapacidad persistente para lograr y mantener una erección lo suficientemente firme como para tener relaciones sexuales satisfactorias. Es un problema común que puede causar estrés, problemas de relación y baja autoestima.", whatIs: { title: "¿Qué es la Disfunción Eréctil?", text: "Es un fallo en el complejo proceso que involucra al cerebro, hormonas, emociones, nervios, músculos y vasos sanguíneos para crear una erección. A menudo, es una señal de alerta temprana de enfermedades cardiovasculares ocultas." }, types: { title: "Causas Principales", intro: "Suele dividirse en causas físicas o psicológicas (a menudo combinadas):", items: ["Causas orgánicas/físicas (enfermedad cardíaca, colesterol alto, hipertensión, diabetes, obesidad, tabaquismo, o daño nervioso por cirugía de próstata)", "Causas psicológicas (estrés severo, ansiedad por el desempeño, depresión, problemas de pareja)", "Secundaria a medicamentos (efecto adverso de antidepresivos o fármacos para la presión arterial)"], note: "Tener problemas de erección de vez en cuando no es motivo de preocupación, pero si es constante, requiere evaluación." }, diagnosis: { title: "Evaluación Médica", intro: "El médico, a menudo un urólogo, investigará la causa raíz:", items: ["Historial médico y sexual detallado, y examen físico (incluyendo revisión de pulsos periféricos)", "Análisis de sangre para verificar niveles de testosterona, lípidos, glucosa y función tiroidea", "Ecografía Doppler (para comprobar el flujo sanguíneo en el pene)", "Examen psicológico o cuestionarios de estrés y depresión"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en resolver la causa médica subyacente y mejorar la erección:", subsections: [ { title: "Opciones Terapéuticas", items: ["Medicamentos orales (inhibidores de la PDE5 como sildenafil/Viagra, tadalafilo, que mejoran el flujo sanguíneo)", "Terapia de reemplazo de testosterona (si los niveles son bajos)", "Inyecciones en el pene o supositorios uretrales (alprostadil)", "Bomba de vacío para el pene o cirugía de implante de prótesis de pene (en casos refractarios)", "Asesoramiento psicológico o terapia sexual de pareja"] } ], note: "Mejorar el estilo de vida (perder peso, hacer ejercicio, dejar de fumar) es a menudo el tratamiento inicial más eficaz." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es importante hablar con un profesional si:", items: ["El problema de erección es persistente o empeora progresivamente", "Tienes diabetes, enfermedades cardíacas u otras afecciones conocidas asociadas con la DE", "Experimentas otros síntomas sexuales como eyaculación precoz o retrasada", "El problema está causando gran ansiedad, depresión o conflictos graves en tu relación"] } },
'Hígado graso' : { intro: "La enfermedad del hígado graso es una afección común causada por la acumulación excesiva de grasa en las células del hígado. Aunque es normal tener algo de grasa en el hígado, si supera el 5-10% del peso del órgano, se considera enfermedad.", whatIs: { title: "¿Qué es el Hígado Graso?", text: "Es un trastorno metabólico donde los lípidos se depositan en el tejido hepático. Existen dos tipos principales: la enfermedad del hígado graso por alcohol (asociada al consumo excesivo) y la enfermedad del hígado graso no alcohólico (EHNA, asociada a obesidad y diabetes)." }, types: { title: "Etapas de la Enfermedad", intro: "La afección no alcohólica (EHNA) progresa en varias fases:", items: ["Hígado graso simple (esteatosis): Acumulación de grasa inofensiva sin inflamación.", "Esteatohepatitis no alcohólica (NASH): La grasa causa inflamación y daño a las células hepáticas.", "Fibrosis: La inflamación crónica genera tejido cicatricial alrededor del hígado y los vasos sanguíneos.", "Cirrosis: Daño severo y cicatrización extensa que reemplaza al tejido sano, comprometiendo la vida."], note: "La NASH puede progresar a cáncer de hígado o insuficiencia hepática si no se revierte." }, diagnosis: { title: "Detección", intro: "Suele ser una enfermedad silenciosa descubierta en chequeos de rutina:", items: ["Análisis de sangre (elevación de enzimas hepáticas como AST y ALT)", "Ecografía abdominal (muestra un hígado 'brillante' por la grasa)", "Elastografía transitoria o FibroScan (mide la rigidez del hígado para detectar cicatrices/fibrosis)", "Biopsia hepática (el método definitivo para diagnosticar NASH y cirrosis)"], note: "" }, treatment: { title: "Reversión y Manejo", intro: "No existen medicamentos específicos aprobados para curarlo, el tratamiento es el estilo de vida:", subsections: [ { title: "Medidas Cruciales", items: ["Pérdida de peso gradual (perder del 7% al 10% del peso corporal puede reducir drásticamente la inflamación)", "Dieta mediterránea (alta en verduras, fibra y grasas saludables; evitar azúcar refinada y fructosa)", "Control estricto de la diabetes, colesterol y triglicéridos", "Evitar absolutamente el consumo de alcohol y medicamentos tóxicos para el hígado"] } ], note: "En etapas tempranas (esteatosis simple), el hígado graso es completamente reversible." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda especializada?", intro: "Consulta a un gastroenterólogo o hepatólogo si:", items: ["Tus análisis de sangre de rutina muestran enzimas hepáticas elevadas de forma persistente", "Tienes dolor sordo o pesadez crónica en la parte superior derecha del abdomen", "Presentas síntomas de daño hepático avanzado: fatiga extrema, piel u ojos amarillos (ictericia), o hinchazón abdominal (ascitis)"] } },
'Cáncer de tiroides' : { intro: "El cáncer de tiroides es una enfermedad en la que se forman células malignas en los tejidos de la glándula tiroides, ubicada en la base del cuello. Es uno de los cánceres de más rápido crecimiento en detección, pero afortunadamente la gran mayoría son altamente curables.", whatIs: { title: "¿Qué es el Cáncer de Tiroides?", text: "Es el crecimiento descontrolado de las células tiroideas formando un nódulo o tumor. A menudo no presenta síntomas en sus inicios, pero a medida que crece puede causar dolor, hinchazón en el cuello o problemas para tragar o hablar." }, types: { title: "Tipos de Cáncer", intro: "Se clasifican según el tipo de célula a partir de la cual crecen:", items: ["Papilar (el más común, alrededor del 80%, crece muy lentamente y es altamente curable)", "Folicular (el segundo más común, suele tener buen pronóstico, incluye el cáncer de células de Hürthle)", "Medular (menos común, comienza en células C y a menudo está ligado a síndromes genéticos familiares)", "Anaplásico (muy raro, de crecimiento extremadamente rápido, agresivo y difícil de tratar)"], note: "La exposición a altos niveles de radiación en la infancia es un factor de riesgo comprobado." }, diagnosis: { title: "Diagnóstico", intro: "La evaluación de nódulos sospechosos incluye:", items: ["Ecografía del cuello (para ver si el nódulo es sólido o un quiste de líquido, y su tamaño)", "Biopsia por aspiración con aguja fina (PAAF) guiada por ecografía (el método estándar para confirmar el cáncer)", "Análisis de sangre (para medir las hormonas tiroideas TSH y marcadores como calcitonina para el cáncer medular)", "Pruebas de imagen avanzadas o gammagrafía (para ver si el cáncer se ha propagado)"], note: "" }, treatment: { title: "Tratamiento", intro: "Suele tener tasas de éxito excelentes mediante intervenciones específicas:", subsections: [ { title: "Opciones Oncológicas", items: ["Cirugía (Tiroidectomía total o parcial, el tratamiento principal y más común, junto con extirpación de ganglios linfáticos afectados)", "Terapia con yodo radiactivo (se administra en pastilla tras la cirugía para destruir cualquier célula cancerosa microscópica restante)", "Terapia de hormona tiroidea (pastillas diarias de levotiroxina de por vida para reemplazar la hormona y suprimir la TSH, lo que evita que el cáncer regrese)", "Radioterapia externa o quimioterapia (reservadas generalmente para cáncer anaplásico o estados avanzados)"] } ], note: "Muchos microcarcinomas papilares (tumores muy pequeños) pueden manejarse con 'vigilancia activa' y ecografías regulares sin cirugía inmediata." }, whenToSeekHelp: { title: "¿Cuándo acudir al endocrinólogo?", intro: "Es importante buscar una evaluación si notas:", items: ["Un bulto o nódulo palpable en la parte frontal o lateral del cuello (a menudo lo detectas al afeitarte o maquillarte)", "Cambios en tu voz, incluyendo ronquera constante que no se va", "Dificultad progresiva para tragar alimentos o sentir un 'nudo' en la garganta al tragar", "Dolor en el cuello y la garganta que no está asociado a un resfriado, o ganglios linfáticos inflamados en el cuello de forma crónica"] } },
'Enfermedad de Alzheimer' : { intro: "La enfermedad de Alzheimer es un trastorno neurológico progresivo que hace que el cerebro se encoja (atrofia) y que las neuronas cerebrales mueran. Es la causa más común de demencia, originando un deterioro continuo en el pensamiento, el comportamiento y las habilidades sociales.", whatIs: { title: "¿Qué es el Alzheimer?", text: "Es una enfermedad neurodegenerativa caracterizada por la acumulación anormal de proteínas en el cerebro (placas de beta-amiloide y ovillos de tau). Estas placas bloquean la comunicación entre neuronas y desencadenan procesos inflamatorios que finalmente destruyen el tejido cerebral, borrando la memoria." }, types: { title: "Aparición", intro: "Se clasifica habitualmente por el momento en que se presentan los síntomas:", items: ["Alzheimer de inicio tardío (la forma más común, los síntomas aparecen después de los 65 años, la genética juega un papel, pero no es determinante)", "Alzheimer de inicio temprano (poco común, ocurre en personas entre 30 y 60 años, a menudo tiene un fuerte vínculo genético hereditario)"], note: "Es una enfermedad terminal que generalmente progresa a lo largo de 4 a 8 años desde el diagnóstico." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El diagnóstico se basa en la evaluación clínica y el descarte de otras causas:", items: ["Pruebas neuropsicológicas y cognitivas (evaluación exhaustiva de memoria, lenguaje y resolución de problemas)", "Pruebas de imagen cerebral (Resonancia Magnética o TC para ver el encogimiento del cerebro y descartar tumores/ACV)", "Tomografía por Emisión de Positrones (PET) (para detectar placas de amiloide o problemas de metabolismo cerebral)", "Análisis de líquido cefalorraquídeo o de sangre para biomarcadores de Alzheimer"], note: "El diagnóstico definitivo absoluto solía hacerse solo en la autopsia, pero las pruebas de biomarcadores modernas son muy precisas." }, treatment: { title: "Tratamiento y Manejo", intro: "No existe cura, pero hay tratamientos que ralentizan los síntomas temporalmente:", subsections: [ { title: "Intervenciones", items: ["Medicamentos para los síntomas cognitivos (Inhibidores de colinesterasa como Donepezilo o Rivastigmina, y Memantina)", "Nuevas terapias modificadoras de la enfermedad (Anticuerpos monoclonales intravenosos que eliminan placas de amiloide en etapas muy tempranas)", "Tratamientos para síntomas conductuales (antidepresivos o ansiolíticos para manejar la depresión, agitación o insomnio)", "Adaptación del entorno hogareño (simplificar espacios, eliminar riesgos de caída, ocultar objetos peligrosos)"] } ], note: "El apoyo al cuidador principal es vital, ya que el estrés del cuidado continuo es inmenso." }, whenToSeekHelp: { title: "¿Cuándo buscar evaluación médica?", intro: "Es fundamental acudir a un neurólogo o geriatra si tú o un ser querido presentan:", items: ["Pérdida de memoria que altera la vida cotidiana (olvidar información recién aprendida, hacer la misma pregunta repetidamente)", "Dificultad para planificar o resolver problemas, o problemas para completar tareas familiares como cocinar o manejar dinero", "Desorientación grave de tiempo o lugar (olvidar cómo llegar a casa o no saber en qué año están)", "Colocación de objetos en lugares absurdos (ej. llaves en la nevera) o cambios drásticos de humor o personalidad (sospechas, miedo o apatía)"] } },
'Síndrome de los ovarios poliquísticos (PCOS)' : { intro: "El síndrome de ovario poliquístico (SOP o PCOS en inglés) es un trastorno hormonal frecuente en las mujeres en edad reproductiva. Puede causar períodos menstruales infrecuentes o prolongados, así como niveles excesivos de hormonas masculinas (andrógenos).", whatIs: { title: "¿Qué es el SOP?", text: "Es un desequilibrio metabólico y endocrino donde los ovarios pueden desarrollar numerosas pequeñas acumulaciones de líquido (folículos o 'quistes') y no liberar óvulos regularmente. Está fuertemente ligado a la resistencia a la insulina y es una de las causas principales de infertilidad femenina." }, types: { title: "Características y Criterios", intro: "El síndrome se diagnostica cuando se cumplen al menos dos de los siguientes (Criterios de Rotterdam):", items: ["Irregularidad menstrual (ciclos muy largos, oligomenorrea, o ausencia de regla, amenorrea)", "Exceso de andrógenos (signos clínicos como exceso de vello, o detectados en análisis de sangre)", "Ovarios poliquísticos (múltiples folículos visibles en la ecografía que aumentan el tamaño del ovario)"], note: "A pesar de su nombre, no todas las mujeres con SOP tienen quistes ováricos, y tener quistes no significa necesariamente tener SOP." }, diagnosis: { title: "Evaluación Ginecológica y Endocrina", intro: "Para llegar al diagnóstico se requiere:", items: ["Examen físico y de historial médico detallado (peso, signos de vello facial, acné, acantosis nigricans)", "Análisis de sangre completos (niveles hormonales de testosterona, LH, FSH, así como pruebas de tolerancia a la glucosa y colesterol)", "Ecografía pélvica o transvaginal (para inspeccionar la apariencia y volumen de los ovarios y el grosor del revestimiento uterino)"], note: "" }, treatment: { title: "Tratamiento y Manejo", intro: "El tratamiento se enfoca en las preocupaciones individuales, como la fertilidad, el hirsutismo, el acné o la obesidad:", subsections: [ { title: "Terapias", items: ["Cambios en el estilo de vida (pérdida de peso, dieta baja en carbohidratos simples y ejercicio regular para reducir la resistencia a la insulina)", "Anticonceptivos hormonales (píldoras, parches o anillo para regular el ciclo, reducir el riesgo de cáncer de endometrio y controlar el acné/vello)", "Metformina (medicamento para la diabetes tipo 2 que mejora la resistencia a la insulina y puede reiniciar la ovulación)", "Medicamentos antiandrógenos (para bloquear los efectos de las hormonas masculinas)", "Tratamientos de fertilidad (Clomifeno, Letrozol o FIV si la paciente desea quedar embarazada)"] } ], note: "El control del SOP es a largo plazo para prevenir diabetes tipo 2 y enfermedades cardíacas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación si:", items: ["Tus períodos menstruales son constantemente irregulares, tienes menos de 8 ciclos al año, o la menstruación se detiene por completo", "Notas un crecimiento excesivo de vello en la cara, pecho, abdomen o muslos (hirsutismo) o acné adulto severo", "Estás intentando quedar embarazada sin éxito durante más de 12 meses", "Sufres de aumento de peso inexplicable y áreas de piel oscura y aterciopelada en el cuello o axilas"] } },
'Cardiopatía hipertensiva' : { intro: "La cardiopatía hipertensiva se refiere a una variedad de problemas cardíacos y estructurales que ocurren debido a que la presión arterial alta (hipertensión) se mantiene descontrolada durante un largo período de tiempo, obligando al corazón a trabajar bajo gran tensión.", whatIs: { title: "¿Qué es la Cardiopatía Hipertensiva?", text: "Es el daño crónico al corazón debido a la presión alta. Para bombear sangre contra esta elevada resistencia en los vasos sanguíneos, el músculo del corazón se engrosa y se vuelve rígido, perdiendo eficiencia. Además, la presión daña las arterias coronarias, reduciendo el oxígeno al corazón." }, types: { title: "Complicaciones Principales", intro: "Engloba principalmente dos condiciones mayores:", items: ["Hipertrofia ventricular izquierda (el engrosamiento patológico de la pared principal de bombeo del corazón, lo que dificulta su llenado normal)", "Enfermedad arterial coronaria isquémica (el estrechamiento de las arterias que alimentan al corazón, causando anginas o infartos)", "Insuficiencia cardíaca congestiva (el estadio final donde el corazón engrosado se debilita o se vuelve tan rígido que falla en bombear la sangre)"], note: "Es una de las principales causas de muerte y discapacidad asociadas a la hipertensión." }, diagnosis: { title: "Evaluación Cardiológica", intro: "El cardiólogo buscará signos de daño en el corazón:", items: ["Electrocardiograma (ECG) para detectar signos de engrosamiento del ventrículo izquierdo o problemas eléctricos", "Ecocardiograma (ultrasonido del corazón, el estudio más importante para medir el grosor de las paredes, el tamaño de las cavidades y la función de bombeo)", "Prueba de esfuerzo (ergometría) o angiografía coronaria (para evaluar bloqueos en las arterias del corazón)", "Monitoreo continuo de la presión arterial (MAPA de 24 horas)"], note: "" }, treatment: { title: "Manejo y Control", intro: "El objetivo vital es bajar la presión arterial para detener o revertir parcialmente el daño:", subsections: [ { title: "Intervenciones", items: ["Medicamentos antihipertensivos de por vida (Inhibidores de la ECA, ARA-II, betabloqueantes o bloqueadores de canales de calcio)", "Diuréticos (para eliminar el exceso de líquido y sodio, reduciendo la carga del corazón)", "Modificaciones agresivas del estilo de vida (dieta DASH estricta baja en sal, pérdida de peso, dejar de fumar y limitar el alcohol)", "Control riguroso de otros factores de riesgo como la diabetes y el colesterol elevado"] } ], note: "El daño cardíaco temprano (hipertrofia) a veces puede revertirse si la presión se controla estrictamente." }, whenToSeekHelp: { title: "¿Cuándo buscar atención urgente?", intro: "Si tienes hipertensión conocida y experimentas esto, acude a urgencias:", items: ["Dolor, opresión o pesadez en el pecho que puede irradiarse al brazo o cuello (angina o posible infarto)", "Dificultad súbita o severa para respirar, especialmente al acostarte, o necesidad de dormir con varias almohadas", "Palpitaciones muy aceleradas o irregulares acompañadas de mareos, desmayos o visión borrosa", "Hinchazón notoria y repentina en los pies, tobillos, piernas o abdomen (edema)"] } },
'Estreñimiento' : { intro: "El estreñimiento se caracteriza por deposiciones poco frecuentes o dificultad para evacuar, lo que provoca que las heces sean duras y secas. Aunque es ocasionalmente común en la mayoría de las personas, el estreñimiento crónico puede interferir significativamente con la calidad de vida.", whatIs: { title: "¿Qué es el Estreñimiento?", text: "Clínicamente, se define como tener menos de tres evacuaciones intestinales por semana. Ocurre cuando el colon absorbe demasiada agua de los desechos alimentarios, o si las contracciones musculares del colon son demasiado lentas y perezosas." }, types: { title: "Clasificación", intro: "Puede ser agudo o crónico, y se clasifica por su causa:", items: ["Tránsito lento (los músculos del colon se mueven muy despacio)", "Trastorno de la evacuación o disfunción del suelo pélvico (falta de coordinación de los músculos del recto y el esfínter al intentar defecar)", "Secundario (causado por medicamentos como opioides o hierro, o por enfermedades como hipotiroidismo, diabetes o Parkinson)"], note: "El estilo de vida (poca fibra, sedentarismo, no beber agua) es la causa principal." }, diagnosis: { title: "Evaluación Médica", intro: "Si se vuelve crónico, el médico investigará:", items: ["Examen físico, incluido un tacto rectal para buscar hemorroides, fisuras o disfunción muscular", "Análisis de sangre para descartar hipotiroidismo o altos niveles de calcio", "Tránsito colónico con marcadores radiopacos (para ver qué tan rápido se mueve el alimento)", "Colonoscopia (si se sospecha de un bloqueo, pólipo o cáncer de colon, especialmente en mayores de 50 años)"], note: "" }, treatment: { title: "Manejo y Alivio", intro: "Se aborda escalonadamente, comenzando por lo más natural:", subsections: [ { title: "Opciones de Tratamiento", items: ["Aumento de la ingesta de fibra (frutas, verduras, salvado) e hidratación abundante", "Ejercicio físico regular (para estimular la movilidad intestinal)", "Laxantes formadores de volumen o laxantes osmóticos (polietilenglicol) como primera línea médica", "Laxantes estimulantes o supositorios/enemas (solo para uso ocasional)", "Biorretroalimentación (fisioterapia para reentrenar los músculos pélvicos en casos de disfunción evacuatoria)", "Cirugía (muy rara vez, solo en casos extremos de inercia colónica o bloqueos)"] } ], note: "El uso excesivo de laxantes estimulantes puede volver al intestino dependiente de ellos." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es importante buscar atención médica, ya que podría indicar un problema más grave, si presentas:", items: ["Estreñimiento nuevo o inusual que dura más de tres semanas", "Aparición de sangre en el papel higiénico, en el inodoro o heces alquitranadas", "Dolor abdominal constante y severo, o dolor intenso al defecar", "Pérdida de peso involuntaria sin dieta, o alternancia repentina entre estreñimiento y diarrea"] } },
'Eyaculación precoz' : { intro: "La eyaculación precoz ocurre cuando un hombre eyacula antes de lo deseado, ya sea por él o por su pareja, durante las relaciones sexuales. Es una disfunción sexual masculina muy común que puede generar frustración, ansiedad y evitación de la intimidad.", whatIs: { title: "¿Qué es la Eyaculación Precoz?", text: "Se define clínicamente cuando la eyaculación ocurre casi siempre un minuto (o menos) después de la penetración vaginal, o antes, y existe una incapacidad constante para retrasarla, causando angustia personal significativa." }, types: { title: "Tipos de Presentación", intro: "Se divide principalmente en dos categorías:", items: ["Primaria o de por vida (el problema ha estado presente desde las primeras experiencias sexuales y ocurre casi siempre)", "Secundaria o adquirida (se desarrolla después de haber tenido experiencias sexuales previas sin problemas eyaculatorios)", "Situacional o natural variable (solo ocurre con parejas específicas o bajo ciertas circunstancias, lo cual no es estrictamente un trastorno)"], note: "Suele tener causas psicológicas (ansiedad, estrés, culpa) o biológicas (niveles hormonales anormales, inflamación de la próstata o problemas de tiroides)." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico es eminentemente clínico y confidencial:", items: ["Historial médico y sexual detallado por parte del urólogo o médico general", "Cuestionarios específicos para medir el tiempo de latencia eyaculatoria intravaginal y el impacto emocional", "Examen físico y análisis de sangre u orina (para descartar problemas de próstata, testosterona baja u otros trastornos si hay disfunción eréctil asociada)"], note: "Es muy común que la eyaculación precoz secundaria coexista con la disfunción eréctil." }, treatment: { title: "Tratamiento y Manejo", intro: "Generalmente responde bien a una combinación de terapias:", subsections: [ { title: "Opciones Terapéuticas", items: ["Técnicas conductuales (técnica de 'parar y empezar' o el método de 'compresión' enseñados por terapeutas sexuales)", "Uso de preservativos especiales o anestésicos tópicos (cremas, aerosoles de lidocaína/prilocaína para reducir la sensibilidad del pene)", "Medicamentos orales (antidepresivos ISRS como dapoxetina, paroxetina o sertralina, que tienen como efecto secundario retrasar la eyaculación)", "Medicamentos para la disfunción eréctil (como el sildenafil, a veces ayudan a mantener la erección o reducir la ansiedad)", "Terapia psicológica y asesoramiento de pareja"] } ], note: "Los anestésicos tópicos deben limpiarse antes de la penetración para no transferir el adormecimiento a la pareja." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es totalmente normal y recomendable buscar ayuda profesional si:", items: ["La eyaculación temprana ocurre en la mayoría de tus encuentros sexuales y no puedes controlarla de ninguna manera", "El problema te está causando vergüenza, estrés significativo o depresión", "Estás evitando la intimidad sexual debido al miedo al fracaso, lo que está dañando tu relación de pareja"] } },
'Cáncer de mama' : { intro: "El cáncer de mama es el cáncer que se forma en las células de las mamas (senos). Es el cáncer más común diagnosticado en mujeres a nivel mundial (después del cáncer de piel), aunque también puede presentarse raramente en los hombres.", whatIs: { title: "¿Qué es el Cáncer de Mama?", text: "Es el crecimiento descontrolado y mutación de las células del tejido mamario, generalmente en los conductos lácteos o en los lobulillos glandulares. Estas células anormales pueden formar un tumor que a menudo se puede sentir como un bulto y que puede propagarse (hacer metástasis) a través del sistema linfático a otros órganos." }, types: { title: "Subtipos Biológicos y Clínicos", intro: "No es una sola enfermedad; se clasifica por su origen celular y receptores:", items: ["Carcinoma ductal in situ (CDIS) (no invasivo, limitado a los conductos)", "Carcinoma ductal invasivo (el más común, rompe el conducto e invade el tejido mamario)", "Carcinoma lobulillar invasivo (comienza en las glándulas productoras de leche)", "Clasificación molecular: Receptor de hormonas (estrógeno/progesterona) positivo o negativo; y HER2 positivo o negativo", "Cáncer de mama triple negativo (no tiene ninguno de los tres receptores, es agresivo y difícil de tratar)"], note: "La genética (mutaciones BRCA1 y BRCA2) juega un papel crucial en los cánceres familiares agresivos." }, diagnosis: { title: "Detección y Diagnóstico", intro: "El cribado regular es la mejor arma, seguido de pruebas confirmatorias:", items: ["Mamografía (radiografía del seno, la herramienta principal de cribado para detectar tumores antes de que se sientan)", "Ecografía mamaria (para determinar si un bulto es sólido o un quiste lleno de líquido)", "Resonancia Magnética (RM) de mama (para mujeres de alto riesgo o para ver la extensión del cáncer)", "Biopsia con aguja gruesa (el único método definitivo para extraer tejido y confirmar en laboratorio si es cáncer y qué tipo de receptores tiene)"], note: "" }, treatment: { title: "Tratamiento Oncológico y Quirúrgico", intro: "Se requiere un enfoque multidisciplinario, a menudo combinando terapias:", subsections: [ { title: "Opciones de Manejo", items: ["Cirugía (Tumorectomía/conservadora para extirpar solo el tumor, o Mastectomía para extirpar todo el seno; ambas suelen requerir la biopsia de ganglio centinela en la axila)", "Radioterapia (usada post-cirugía conservadora para destruir células restantes en el pecho)", "Quimioterapia (usada antes de la cirugía para encoger tumores grandes o después para destruir células diseminadas)", "Terapia hormonal (Tamoxifeno o inhibidores de la aromatasa para bloquear el estrógeno en cánceres con receptores positivos)", "Terapia dirigida (Trastuzumab para atacar cánceres HER2 positivos) e Inmunoterapia"] } ], note: "Las decisiones de tratamiento se basan fuertemente en el estadio del cáncer y el perfil genómico del tumor." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico inmediatamente?", intro: "Aparte de hacerte las mamografías anuales a partir de los 40 años, consulta a tu médico de inmediato si notas:", items: ["Un bulto nuevo o engrosamiento en el seno o debajo de la axila que se siente diferente al resto del tejido", "Cambios en el tamaño, forma o apariencia de la mama", "Cambios en la piel del seno, como hoyuelos, frunces o aspecto de 'piel de naranja', o piel escamosa y enrojecida", "Pezón invertido recientemente o secreción de sangre o líquido anormal a través del pezón"] } },
'Cicatriz hipertrófica' : { intro: "Una cicatriz hipertrófica es una cicatriz engrosada, elevada y enrojecida que se desarrolla como una respuesta de curación anormal de la piel tras una lesión. Aunque a menudo se confunden con los queloides, tienen comportamientos y pronósticos diferentes.", whatIs: { title: "¿Qué es una Cicatriz Hipertrófica?", text: "Es el resultado de una sobreproducción excesiva de colágeno durante el proceso de cicatrización de una herida (como cortes, quemaduras o cirugías). A diferencia de los queloides, la cicatriz hipertrófica se mantiene confinada estrictamente a los bordes y límites de la herida original." }, types: { title: "Características", intro: "Suelen distinguirse por:", items: ["Elevación sobre el nivel de la piel normal", "Coloración rosada, roja o púrpura (especialmente al principio)", "Suelen desarrollarse rápidamente tras la lesión (en 1 a 2 meses)", "Pueden mejorar o aplanarse parcialmente de forma espontánea a lo largo de 1 a 3 años"], note: "Aparecen frecuentemente en áreas sometidas a mucha tensión, como las articulaciones, el pecho o la espalda." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El diagnóstico es clínico y muy directo:", items: ["Examen físico visual y palpación de la cicatriz por parte de un dermatólogo o cirujano plástico", "Diferenciación crucial con un queloide (que crece más allá de la herida) para determinar el mejor plan de tratamiento"], note: "Rara vez o nunca se requiere una biopsia." }, treatment: { title: "Manejo y Reducción", intro: "Existen múltiples opciones para aplanar y difuminar la cicatriz:", subsections: [ { title: "Tratamientos", items: ["Láminas o gel de silicona (el tratamiento no invasivo de primera línea, aplicado diariamente sobre la cicatriz)", "Inyecciones de corticosteroides (triamcinolona) inyectadas directamente en la cicatriz para ablandar y aplanar el colágeno excesivo", "Terapia con láser (láser vascular o fraccionado) para reducir el enrojecimiento y mejorar la textura", "Presoterapia (prendas de compresión usadas en cicatrices grandes o quemaduras)", "Cirugía de revisión de cicatriz (como último recurso, ya que la cirugía misma podría crear otra cicatriz anormal)"] } ], note: "Las inyecciones de corticoides pueden requerir varias sesiones mensuales para lograr el efecto deseado." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable buscar atención dermatológica si la cicatriz:", items: ["Produce un picor insoportable, ardor o dolor que afecta tu vida diaria", "Se encuentra sobre una articulación y está tan tensa y rígida (contractura) que limita o impide tu capacidad de movimiento normal", "Te causa angustia emocional severa o problemas estéticos y de autoestima"] } },
'Cáncer de los ovarios' : { intro: "El cáncer de ovario es un tipo de cáncer que comienza en los ovarios o en las trompas de Falopio asociadas. Es conocido como un 'asesino silencioso' porque a menudo no se detecta hasta que se ha propagado dentro de la pelvis y el abdomen.", whatIs: { title: "¿Qué es el Cáncer de Ovarios?", text: "Es el crecimiento maligno de células en las glándulas reproductoras femeninas. Debido a que los ovarios están profundos en la cavidad abdominal, el tumor puede crecer considerablemente e invadir órganos vecinos antes de causar síntomas evidentes." }, types: { title: "Tipos de Tumores Ováricos", intro: "Se clasifican según la célula en la que se originan:", items: ["Tumores epiteliales (el tipo más común, 90% de los casos, comienzan en la capa delgada de tejido que recubre el exterior de los ovarios)", "Tumores estromales (raros, comienzan en el tejido que produce hormonas y sostiene el ovario, a menudo se diagnostican antes que otros tipos)", "Tumores de células germinales (raros, comienzan en las células que producen los óvulos, tienden a ocurrir en mujeres más jóvenes)"], note: "Tener mutaciones genéticas hereditarias (BRCA1 o BRCA2) aumenta masivamente el riesgo de desarrollar este cáncer." }, diagnosis: { title: "Evaluación y Diagnóstico", intro: "La falta de pruebas de cribado efectivas dificulta la detección temprana. El diagnóstico requiere:", items: ["Examen pélvico físico (para palpar si hay masas u ovarios agrandados)", "Ecografía transvaginal o Tomografía Computarizada (TC) de abdomen y pelvis para visualizar el tumor y líquido en el abdomen (ascitis)", "Análisis de sangre para medir el marcador tumoral CA 125 (que suele estar elevado, aunque no es exclusivo del cáncer)", "Cirugía diagnóstica/biopsia (a menudo, la confirmación final y la estadificación se realizan durante la cirugía para extirpar el tumor)"], note: "La prueba de Papanicolaou (Pap) detecta el cáncer de cuello uterino, NO el cáncer de ovario." }, treatment: { title: "Tratamiento Oncológico", intro: "El tratamiento casi siempre implica cirugía seguida de quimioterapia:", subsections: [ { title: "Procedimientos", items: ["Cirugía citorreductora extensa (histerectomía, extirpación de ambos ovarios y trompas, ganglios linfáticos y la mayor cantidad posible de tejido tumoral del abdomen)", "Quimioterapia (administrada por vía intravenosa o directamente en la cavidad abdominal - intraperitoneal - para matar las células cancerosas restantes)", "Terapias dirigidas (inhibidores de PARP o Bevacizumab, especialmente eficaces en tumores con mutaciones BRCA) o inmunoterapia"] } ], note: "El pronóstico mejora drásticamente si la enfermedad se descubre en estadios muy tempranos, antes de salir del ovario." }, whenToSeekHelp: { title: "¿Cuándo consultar al ginecólogo urgentemente?", intro: "Es de vital importancia acudir al médico si experimentas los siguientes síntomas vagos, pero nuevos y casi a diario, por más de dos o tres semanas:", items: ["Hinchazón abdominal persistente o aumento del tamaño de tu vientre (tu ropa te queda apretada repentinamente)", "Sensación de llenura muy rápida al comer, dificultad para comer o pérdida de apetito", "Dolor o presión persistente en la pelvis o la parte baja del abdomen/espalda", "Necesidad urgente o más frecuente de orinar, sin que exista una infección urinaria"] } },
'Contracturas musculares' : { intro: "Una contractura muscular es una contracción continuada e involuntaria de las fibras de un músculo o de sus fibras tendinosas. Se manifiesta como un 'nudo' endurecido y doloroso, limitando el movimiento de la zona afectada.", whatIs: { title: "¿Qué son las Contracturas Musculares?", text: "Es un estado de tensión excesiva en el músculo que no logra relajarse. Esto comprime los vasos sanguíneos locales, dificultando la llegada de sangre y oxígeno, lo que acumula toxinas musculares e intensifica el dolor y el espasmo." }, types: { title: "Causas y Orígenes", intro: "Pueden surgir por distintos motivos en personas sanas:", items: ["Por esfuerzo o sobrecarga (hacer un ejercicio intenso sin calentar o levantar peso excesivo de golpe)", "Por fatiga postural (pasar horas frente a la computadora en una posición incorrecta, típico en cuello y espalda)", "Secundarias a otras lesiones (el músculo se contrae para 'proteger' una articulación lesionada, como tras un esguince)", "Por estrés emocional o ansiedad (que se refleja en tensión física, especialmente en cervicales y trapecios)"], note: "La mayoría son inofensivas, pero muy limitantes e incómodas." }, diagnosis: { title: "Evaluación Física", intro: "El diagnóstico es clínico y rápido:", items: ["Palpación manual directa por parte del médico o fisioterapeuta para detectar la banda tensa y los 'puntos gatillo' dolorosos", "Evaluación del rango de movimiento activo y pasivo del músculo afectado", "Rara vez se necesitan pruebas de imagen, a menos que se sospeche de una hernia de disco u otra lesión subyacente"], note: "" }, treatment: { title: "Relajación y Fisioterapia", intro: "El tratamiento se enfoca en devolver la elasticidad y flujo sanguíneo al músculo:", subsections: [ { title: "Opciones Terapéuticas", items: ["Reposo relativo (evitar la actividad que causa dolor, pero sin inmovilizar completamente la zona)", "Calor local (duchas calientes o mantas térmicas aplicadas 15-20 min para dilatar vasos y relajar)", "Fisioterapia y masajes descontracturantes (la terapia manual es la herramienta más eficaz)", "Punción seca en los puntos gatillo musculares", "Medicamentos (relajantes musculares y antiinflamatorios recetados por cortos períodos)"] } ], note: "El estiramiento suave y gradual es fundamental para evitar la reaparición." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable buscar atención si:", items: ["El dolor es extremadamente agudo, punzante o incapacitante", "La contractura no mejora después de una semana de reposo, calor y autocuidado", "El dolor se irradia por el brazo o la pierna, acompañado de hormigueo, entumecimiento o debilidad (signo de posible compresión nerviosa)", "La zona presenta un hematoma grande o hinchazón aguda tras un golpe (posible rotura muscular)"] } },
'Psoriasis' : { intro: "La psoriasis es una enfermedad crónica autoinmune de la piel que acelera el ciclo de vida de las células cutáneas. Esto hace que las células se acumulen rápidamente en la superficie de la piel, formando escamas y manchas rojas que causan picazón y, a veces, dolor.", whatIs: { title: "¿Qué es la Psoriasis?", text: "Es un trastorno inflamatorio crónico donde el sistema inmunológico hiperactivo envía señales defectuosas que aceleran la producción de células de la piel en días en lugar de semanas. El cuerpo no puede desprenderse de las células viejas lo suficientemente rápido, resultando en placas gruesas y escamosas." }, types: { title: "Tipos y Presentaciones", intro: "Existen varios tipos con diferentes apariencias:", items: ["Psoriasis en placas (la más común, con manchas rojas elevadas cubiertas de escamas plateadas, típicamente en codos, rodillas, cuero cabelludo y espalda baja)", "Psoriasis en gotas (pequeñas manchas en forma de gota desencadenadas a menudo por infecciones bacterianas como estreptococo, común en niños)", "Psoriasis inversa (lesiones rojas lisas en los pliegues de la piel, como axilas o ingles)", "Psoriasis pustulosa (poco común, causa ampollas de pus no infecciosas)", "Artritis psoriásica (una complicación en la que las articulaciones se inflaman y duelen profundamente)"], note: "Es una enfermedad que cursa en ciclos de brotes (desencadenados por estrés, clima, infecciones) y remisiones." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El dermatólogo confirmará la enfermedad mediante:", items: ["Examen visual directo de la piel, el cuero cabelludo y las uñas (las uñas a menudo presentan hoyuelos, decoloración o separación del lecho ungueal)", "Biopsia de piel (en casos atípicos, se extrae una pequeña muestra para examinar bajo el microscopio y descartar otros trastornos, como eczema severo o líquen plano)"], note: "" }, treatment: { title: "Control y Terapias", intro: "No tiene cura, pero los tratamientos pueden controlar los síntomas y detener los brotes y el crecimiento celular:", subsections: [ { title: "Opciones de Tratamiento", items: ["Tratamientos tópicos (cremas de corticosteroides, análogos de vitamina D o retinoides aplicados directamente sobre las placas)", "Fototerapia o terapia de luz (exposición controlada de la piel a luz ultravioleta UVB natural o artificial)", "Medicamentos sistémicos orales (Metotrexato, Ciclosporina, Acitretina para casos moderados a severos)", "Terapias biológicas avanzadas (medicamentos inyectables que bloquean partes específicas del sistema inmunitario alterado)"] } ], note: "Es importante hidratar la piel a diario y evitar los desencadenantes conocidos, como el tabaco o el exceso de alcohol." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico especialista?", intro: "Debes buscar ayuda dermatológica o reumatológica si:", items: ["Las placas de psoriasis cubren grandes áreas de tu cuerpo, causan gran molestia y afectan tu calidad de vida", "Los tratamientos de venta libre o cremas suaves recetadas ya no te hacen efecto", "Sientes dolor, hinchazón o rigidez en las articulaciones (señal temprana de Artritis Psoriásica, que puede causar daño articular permanente si no se trata)", "Tu piel duele intensamente, las lesiones se infectan (pus, rayas rojas) o desarrollan ampollas generalizadas"] } },
'Nefropatía diabética' : { intro: "La nefropatía diabética es una complicación grave y progresiva relacionada con los riñones en personas con diabetes tipo 1 y tipo 2. Afecta la capacidad de los riñones para realizar su trabajo habitual de eliminar los productos de desecho y el exceso de líquido del cuerpo.", whatIs: { title: "¿Qué es la Nefropatía Diabética?", text: "Es el daño a los delicados sistemas de filtración de los riñones (glomérulos). El exceso de azúcar en la sangre durante muchos años sobrecarga y daña estos vasos sanguíneos, provocando que se vuelvan permeables y dejen escapar proteínas vitales hacia la orina, mientras retienen desechos." }, types: { title: "Progresión de la Enfermedad", intro: "Se desarrolla en etapas si no se controla:", items: ["Microalbuminuria (etapa temprana: pequeñas cantidades de proteína albúmina comienzan a filtrarse en la orina, a menudo reversible con buen control)", "Macroalbuminuria (cantidades masivas de proteína en la orina, caída en la tasa de filtración glomerular)", "Enfermedad Renal en Etapa Terminal o ESRD (los riñones fallan por completo, requiriendo terapia de reemplazo)"], note: "Es la causa principal de insuficiencia renal terminal a nivel mundial." }, diagnosis: { title: "Cribado y Detección Regular", intro: "Dado que no presenta síntomas hasta que el daño es severo, la detección preventiva anual en diabéticos es vital:", items: ["Análisis de orina (para detectar la presencia y cantidad de la proteína albúmina)", "Análisis de sangre (prueba de creatinina para estimar la Tasa de Filtración Glomerular o eGFR, que evalúa qué tan bien limpian los riñones)", "Ecografía renal (en etapas avanzadas, para evaluar el tamaño y forma del riñón)"], note: "Las personas con hipertensión además de diabetes tienen un riesgo exponencialmente mayor." }, treatment: { title: "Protección Renal y Manejo", intro: "El tratamiento se enfoca intensamente en prevenir o retrasar el progreso del daño renal:", subsections: [ { title: "Intervenciones", items: ["Control estricto de la glucosa en sangre (mantener niveles óptimos de A1C es el paso más crítico)", "Control estricto de la presión arterial (uso prioritario de medicamentos inhibidores de la ECA o ARA-II, que protegen directamente los riñones además de bajar la presión)", "Uso de nuevos medicamentos para la diabetes (Inhibidores de SGLT2 como dapagliflozina, que han demostrado gran eficacia para proteger el riñón)", "Dieta específica (baja en sodio y proteínas en estadios avanzados)", "Diálisis (hemodiálisis o diálisis peritoneal) o trasplante de riñón (si se alcanza la falla renal terminal)"] } ], note: "Evitar el uso de AINEs (como el ibuprofeno) y el tabaco es crucial para no estresar más los riñones." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Los diabéticos deben someterse a pruebas anuales. Pero busca ayuda inmediata si presentas síntomas de insuficiencia renal avanzada, como:", items: ["Hinchazón excesiva y persistente en pies, tobillos, manos o alrededor de los ojos", "Tu orina tiene mucha espuma o burbujas de forma constante (signo clásico de proteínas en orina)", "Sufres de fatiga extrema inexplicable, dificultad para respirar, pérdida severa de apetito o náuseas/vómitos matutinos", "Sientes picazón generalizada, dificultad para concentrarte y confusión"] } },
'Cálculos en las vías urinarias' : { intro: "Los cálculos en las vías urinarias, o piedras en los riñones (litiasis renal), son depósitos duros de minerales y sales que se forman dentro de los riñones y pueden viajar a los uréteres, vejiga o uretra, causando un dolor extremadamente intenso al intentar expulsarlos.", whatIs: { title: "¿Qué son los Cálculos Urinarios?", text: "Se forman cuando la orina contiene más sustancias que forman cristales (como calcio, oxalato y ácido úrico) de las que el líquido en la orina puede diluir. Al mismo tiempo, a la orina le pueden faltar sustancias que impiden que los cristales se peguen, creando un entorno ideal para formar 'piedras'." }, types: { title: "Tipos de Cálculos", intro: "Saber de qué está hecha la piedra ayuda a prevenir futuros casos:", items: ["Cálculos de calcio (los más comunes, generalmente en forma de oxalato de calcio, ligados a la dieta y ciertas enfermedades)", "Cálculos de ácido úrico (comunes en personas que no beben suficiente líquido o comen una dieta muy alta en proteínas animales o gota)", "Cálculos de estruvita (se forman como respuesta a infecciones de las vías urinarias crónicas y crecen rápido)", "Cálculos de cistina (raros, causados por un trastorno genético que hace que los riñones excreten demasiados aminoácidos)"], note: "Las piedras pequeñas pueden pasar solas sin causar daño, pero las grandes pueden bloquear el tracto urinario." }, diagnosis: { title: "Evaluación Médica", intro: "Ante el dolor tipo cólico nefrítico, el médico realizará:", items: ["Tomografía Computarizada (TC) sin contraste (el método de imagen estándar de oro para ubicar cálculos rápidamente y ver su tamaño, incluso los más pequeños)", "Ecografía abdominal o renal (útil en mujeres embarazadas o niños)", "Análisis de sangre y orina (para detectar infecciones, sangre microscópica o medir niveles de calcio/ácido úrico)", "Análisis de las piedras expulsadas (pasando la orina por un colador para atraparlas y enviarlas al laboratorio)"], note: "" }, treatment: { title: "Alivio y Extracción", intro: "Depende del tamaño de la piedra y los síntomas:", subsections: [ { title: "Abordajes de Tratamiento", items: ["Para piedras pequeñas: Beber de 2 a 3 litros de agua diarios, analgésicos fuertes para el dolor, y medicamentos alfabloqueantes (tamsulosina) para relajar el uréter y facilitar la expulsión natural.", "Para piedras grandes o que causan bloqueo: Litotricia extracorpórea por ondas de choque (ondas de sonido que rompen la piedra en trozos diminutos)", "Ureteroscopia (se inserta un tubo muy delgado con una cámara por la uretra para atrapar y romper la piedra con láser)", "Nefrolitotomía percutánea (cirugía a través de una incisión en la espalda para piedras inusualmente grandes)"] } ], note: "Prevenir la recurrencia bebiendo abundante agua es fundamental, ya que quien ha tenido una piedra tiene un alto riesgo de formar más." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Debes buscar ayuda en un servicio de urgencias de inmediato si experimentas:", items: ["Dolor tan insoportable y agudo en el costado, la espalda (bajo las costillas) o el bajo vientre que no puedes ni siquiera sentarte, estar quieto ni encontrar una posición cómoda", "Dolor severo acompañado de náuseas repetidas y vómitos constantes", "Fiebre y escalofríos intensos (señal clara de una infección atrapada detrás del cálculo bloqueado, una urgencia médica grave)", "Sangre evidente en la orina (color rojo, rosado o marrón) o imposibilidad de orinar en absoluto"] } },
'Enfermedad benigna de las mamas' : { intro: "La enfermedad benigna de las mamas engloba una variedad de afecciones y cambios no cancerosos en el tejido mamario. Estas afecciones son extremadamente comunes, a menudo fluctúan con el ciclo menstrual y, aunque pueden causar bultos o dolor, no representan un peligro vital inmediato.", whatIs: { title: "¿Qué es la Enfermedad Benigna de las Mamas?", text: "Son crecimientos o cambios estructurales en las mamas que no son cáncer (no invaden ni se diseminan). Muchas mujeres experimentan estos cambios fibroquísticos, que consisten en tejidos de aspecto 'grumoso' o abultado causados por respuestas normales a las hormonas mensuales." }, types: { title: "Tipos de Afecciones Benignas", intro: "Se dividen principalmente por cómo se comportan sus células:", items: ["Lesiones no proliferativas (como los quistes simples llenos de líquido, lipomas o cambios fibroquísticos, no aumentan el riesgo de cáncer de mama futuro)", "Lesiones proliferativas sin atipia (crecimiento celular adicional en los conductos o lobulillos, como en los fibroadenomas grandes o papilomas intraductales; elevan muy ligeramente el riesgo de cáncer)", "Hiperplasia atípica (crecimiento excesivo de células anormales en conductos o lobulillos; no es cáncer, pero aumenta sustancialmente el riesgo de desarrollar cáncer en el futuro)"], note: "El Fibroadenoma (un bulto sólido, liso, gomoso y móvil) es el tumor benigno más común en mujeres jóvenes." }, diagnosis: { title: "Evaluación y Descarte de Cáncer", intro: "Cualquier bulto nuevo en la mama debe ser evaluado sistemáticamente por un médico para descartar malignidad:", items: ["Examen clínico de mama", "Mamografía y/o Ecografía mamaria (la ecografía es excelente para diferenciar entre un quiste de líquido y una masa sólida)", "Aspiración con aguja fina (para drenar el líquido de un quiste simple y hacerlo desaparecer de inmediato)", "Biopsia con aguja gruesa (esencial para masas sólidas para analizarlas bajo el microscopio y confirmar al 100% que el tejido es benigno)"], note: "" }, treatment: { title: "Observación y Manejo", intro: "La mayoría de las afecciones benignas no requieren tratamiento médico activo:", subsections: [ { title: "Opciones Clínicas", items: ["Conducta expectante o vigilancia activa (para bultos benignos confirmados, como pequeños fibroadenomas, revisándolos periódicamente)", "Uso de analgésicos de venta libre o anticonceptivos orales (para regular hormonas y reducir el dolor en senos fibroquísticos)", "Drenaje de quistes dolorosos mediante aguja", "Extirpación quirúrgica (escisión) solo si el bulto benigno crece demasiado, duele constantemente, presiona otras estructuras, o si la biopsia revela hiperplasia atípica para prevenir el cáncer"] } ], note: "Reducir la cafeína y usar sostenes de buen soporte deportivo alivia mucho el dolor fibroquístico." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico para revisión?", intro: "Es fundamental acudir a consulta sin demora, incluso si la mayoría de los bultos resultan ser benignos, cuando:", items: ["Descubres un bulto o engrosamiento nuevo y claramente definido en el seno o en la axila que no estaba ahí antes", "Un bulto preexistente cambia de forma o aumenta de tamaño", "Notas una secreción nueva y espontánea en el pezón (especialmente si es sanguinolenta o sale de un solo conducto)", "Observas cambios en la piel del seno (hoyuelos, piel de naranja, enrojecimiento) o el pezón se retrae (se invierte) repentinamente"] } },
'Fobia social' : { intro: "La fobia social, médicamente llamada trastorno de ansiedad social, es mucho más que simple timidez. Es una afección de salud mental crónica y debilitante en la que las interacciones cotidianas causan ansiedad extrema, miedo y conciencia de uno mismo por temor a ser observado o juzgado duramente por los demás.", whatIs: { title: "¿Qué es la Fobia Social?", text: "Es un trastorno de ansiedad marcado por un miedo abrumador a las situaciones sociales o de desempeño. La persona siente un terror constante a sentirse avergonzada, humillada, rechazada o de actuar de una manera que resulte ofensiva, lo que la lleva a evitar dichas situaciones o soportarlas con gran angustia." }, types: { title: "Patrones de Presentación", intro: "Puede ser amplia o específica:", items: ["Ansiedad social generalizada (miedo e incomodidad en casi todas las interacciones sociales diarias, como hablar con extraños, citas, contacto visual o comer en público)", "Ansiedad social específica o de desempeño (el miedo se limita exclusivamente a hablar o actuar frente al público o autoridades, pero no afecta otras interacciones sociales cotidianas)"], note: "Suele comenzar a principios de la adolescencia y, si no se trata, puede durar toda la vida y derivar en depresión o abuso de sustancias." }, diagnosis: { title: "Evaluación Psicológica", intro: "El profesional de salud mental (psicólogo o psiquiatra) diagnostica mediante:", items: ["Entrevistas clínicas para explorar qué situaciones desencadenan el miedo y las respuestas físicas del paciente", "Cuestionarios de autoinforme (como la Escala de Ansiedad Social de Liebowitz)", "Aplicación estricta de los criterios del DSM-5 (el miedo o la evitación debe durar 6 meses o más y causar un deterioro significativo en la vida laboral, social o escolar)"], note: "" }, treatment: { title: "Tratamiento y Superación", intro: "Es altamente tratable y la mayoría de los pacientes mejoran drásticamente con intervención:", subsections: [ { title: "Terapias y Medicación", items: ["Psicoterapia (La Terapia Cognitivo-Conductual o TCC es la más eficaz; ayuda a identificar pensamientos negativos y reemplazar respuestas de miedo. A menudo incluye Terapia de Exposición gradual a situaciones temidas)", "Antidepresivos (ISRS, como sertralina o paroxetina, son la primera línea de tratamiento farmacológico para el uso a largo plazo)", "Betabloqueantes (como el propranolol, que no curan la ansiedad, pero se usan puntualmente antes de eventos específicos para bloquear síntomas físicos como taquicardia, temblores y rubor)"] } ], note: "Participar en grupos de apoyo de TCC con otras personas que padecen lo mismo acelera la curación." }, whenToSeekHelp: { title: "¿Cuándo pedir apoyo profesional?", intro: "Deberías considerar seriamente buscar tratamiento si:", items: ["El miedo a las situaciones sociales hace que canceles planes importantes, faltes al trabajo, a la escuela o a eventos familiares constantemente", "La anticipación de un evento social te produce ataques de pánico completos (corazón acelerado, sudoración intensa, náuseas y mente en blanco)", "Sientes que la vida social es imposible, te aíslas completamente y el problema está afectando tu bienestar general, provocando síntomas depresivos severos"] } },
'Cicatriz queloide' : { intro: "Una cicatriz queloide es un tipo de cicatriz abultada y gruesa que se forma como resultado de una respuesta de curación exagerada de la piel después de una lesión cutánea, como un corte, quemadura, incisión quirúrgica o incluso un simple piercing.", whatIs: { title: "¿Qué es una Cicatriz Queloide?", text: "Es un crecimiento anormal y excesivo de tejido cicatricial denso y fibroso (colágeno). A diferencia de las cicatrices hipertróficas que se limitan a la herida original, los queloides crecen invadiendo los márgenes de la piel sana circundante. Son tumores benignos que no se convierten en cáncer, pero pueden ser muy molestos y antiestéticos." }, types: { title: "Factores de Riesgo", intro: "Suelen ser más frecuentes en:", items: ["Pieles con mayor pigmentación (personas afrodescendientes, asiáticas o hispanas tienen una predisposición genética altísima a desarrollarlos)", "Áreas específicas del cuerpo (lóbulos de las orejas por piercings, la piel sobre el esternón en el centro del pecho, hombros, cuello y espalda superior)", "Personas menores de 30 años"], note: "Pueden tardar semanas o meses en aparecer y continuar creciendo lentamente durante años." }, diagnosis: { title: "Examen Dermatológico", intro: "El diagnóstico es principalmente visual y directo:", items: ["Examen físico por parte de un dermatólogo, observando una cicatriz dura, gomosa, brillante y a menudo de color rojo, púrpura o más oscura que la piel normal, que sobrepasa claramente los límites de la herida inicial", "Rara vez se requiere una biopsia de piel (sólo si se sospecha que podría ser un tumor cutáneo maligno)"], note: "" }, treatment: { title: "Reducción y Manejo", intro: "Son extremadamente difíciles de tratar por completo y tienen una altísima tasa de reaparición, por lo que a menudo se usan tratamientos combinados:", subsections: [ { title: "Opciones de Tratamiento", items: ["Inyecciones intralesionales de corticosteroides (tratamiento principal para aplanar la cicatriz y reducir el dolor e inflamación, se aplican mensualmente)", "Crioterapia (congelar el queloide de adentro hacia afuera con nitrógeno líquido)", "Láminas de silicona o vendajes de presión constantes", "Terapia con láser (para reducir el color rojo y aplanar moderadamente)", "Extirpación quirúrgica (solo recomendada si se combina inmediatamente con inyecciones de esteroides o radioterapia localizada, de lo contrario, la cirugía provocará un nuevo queloide aún más grande)"] } ], note: "La prevención es vital: las personas propensas a queloides deben evitar tatuajes, piercings o cirugías estéticas innecesarias." }, whenToSeekHelp: { title: "¿Cuándo consultar a un dermatólogo?", intro: "Es recomendable programar una cita si:", items: ["La cicatriz queloide continúa creciendo de manera incontrolable después de meses de la lesión inicial", "Produce síntomas muy incómodos como picazón severa, ardor, dolor agudo o extrema sensibilidad al roce de la ropa", "El queloide está ubicado sobre una articulación y es tan grande o rígido que restringe o dificulta el rango normal de movimiento de tu cuerpo"] } },
'Vitiligo' : { intro: "El vitiligo es una enfermedad crónica que causa la pérdida del color (pigmento) de la piel en forma de manchas. Las manchas de color claro o blanco suelen hacerse más grandes con el tiempo. La afección puede afectar la piel de cualquier parte del cuerpo, así como el cabello o el interior de la boca.", whatIs: { title: "¿Qué es el Vitiligo?", text: "Es un trastorno autoinmune en el que el sistema inmunológico ataca y destruye por error los melanocitos, las células responsables de producir melanina (el pigmento que le da color a la piel y el cabello). No es doloroso ni contagioso, pero tiene un inmenso impacto psicosocial." }, types: { title: "Patrones de Presentación", intro: "La pérdida de color se clasifica según su extensión:", items: ["Vitiligo no segmentario o generalizado (el más común, las manchas blancas aparecen de forma simétrica en ambos lados del cuerpo, típicamente en cara, manos, rodillas y zonas de fricción)", "Vitiligo segmentario (las manchas aparecen únicamente en un solo lado o segmento del cuerpo; tiende a presentarse a edades tempranas, progresa por un año y luego se estabiliza)", "Vitiligo focal o localizado (unas pocas manchas en un área muy pequeña) o Universal (casi toda la superficie de la piel pierde su color)"], note: "Suele estar asociado a otras enfermedades autoinmunes como problemas de tiroides o diabetes tipo 1." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El diagnóstico clínico suele ser rápido:", items: ["Examen físico utilizando una Lámpara de Wood (una luz ultravioleta que hace que las áreas de vitiligo brillen intensamente, ayudando a diferenciarlas de infecciones por hongos u otros trastornos de despigmentación)", "Análisis de sangre para chequear la función tiroidea o la presencia de anticuerpos antinucleares (buscando otras condiciones autoinmunes)", "Rara vez biopsia de piel (para confirmar la ausencia total de melanocitos en la lesión)"], note: "" }, treatment: { title: "Repigmentación y Manejo", intro: "No tiene cura definitiva, pero muchos tratamientos buscan detener la progresión y restaurar el color:", subsections: [ { title: "Opciones de Tratamiento", items: ["Protectores solares estrictos y maquillaje camuflador (el sol quema gravemente la piel sin pigmento)", "Cremas tópicas (corticosteroides o inhibidores de la calcineurina como el tacrolimus) para reducir la inflamación autoinmune en la piel", "Fototerapia de banda estrecha UVB (someter la piel a luz ultravioleta en el consultorio, a menudo combinada con medicamentos para estimular la repigmentación)", "Inhibidores orales o tópicos de JAK (Opzelura, tratamientos nuevos aprobados recientemente muy eficaces)", "Cirugía (injertos de piel sana y con pigmento en áreas estables de vitiligo)"] } ], note: "En casos de vitiligo universal, a veces se opta por 'despigmentar' la poca piel normal que queda para emparejar el color." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable consultar a un dermatólogo si:", items: ["Notas que áreas de tu piel, cabello o pestañas pierden color rápidamente, volviéndose completamente blancas de forma asimétrica", "Las manchas blancas se queman fácilmente y causan ampollas cuando te expones brevemente al sol", "La apariencia de tu piel te está causando angustia severa, problemas de autoestima o aislamiento social (se recomienda apoyo psicológico simultáneo)"] } },
'Trastornos de la menstruación' : { intro: "Los trastornos de la menstruación engloban una serie de problemas relacionados con el ciclo menstrual femenino, que pueden afectar su frecuencia, cantidad de flujo o ir acompañados de dolores incapacitantes. Alteran significativamente el bienestar y la salud general de la mujer.", whatIs: { title: "¿Qué son los Trastornos Menstruales?", text: "Son irregularidades en el sangrado o síntomas severos asociados al ciclo reproductivo mensual. Un ciclo menstrual normal varía, pero problemas persistentes fuera de la norma indican desequilibrios hormonales, problemas estructurales (miomas, pólipos) o infecciones que requieren atención." }, types: { title: "Categorías Principales", intro: "Las irregularidades más comunes son:", items: ["Amenorrea (ausencia del periodo por más de 3 meses en mujeres que solían menstruar, o ausencia de la primera regla a los 15 años)", "Dismenorrea (dolor y cólicos menstruales severos, intensos e incapacitantes, a menudo causados por endometriosis)", "Menorragia / Sangrado Uterino Anormal (sangrado inusualmente abundante y prolongado que puede causar anemia)", "Síndrome Premenstrual (SPM) y Trastorno Disfórico Premenstrual (TDPM) (síntomas físicos y psicológicos severos antes del periodo)"], note: "Suelen ser síntomas de afecciones subyacentes, como el Síndrome de Ovarios Poliquísticos (SOP) o alteraciones tiroideas." }, diagnosis: { title: "Evaluación Ginecológica", intro: "Para descubrir la causa exacta, el ginecólogo realizará:", items: ["Un examen pélvico completo y prueba de Papanicolaou", "Ecografía transvaginal o pélvica (para revisar ovarios, útero y grosor del endometrio, buscando miomas o quistes)", "Análisis de sangre detallado (para medir hormonas como estrógeno, progesterona, testosterona, prolactina, función tiroidea y descartar anemia o embarazo)", "Histeroscopia o biopsia de endometrio (en casos de sangrado abundante prolongado o en mujeres posmenopáusicas)"], note: "" }, treatment: { title: "Regulación y Alivio", intro: "El tratamiento se dirige a corregir la causa subyacente y mejorar la calidad de vida:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos hormonales (píldoras anticonceptivas, parches, DIU hormonal Mirena, fundamentales para regular ciclos, reducir sangrados y aliviar cólicos severos)", "AINEs (ibuprofeno, naproxeno o ácido mefenámico) recetados específicamente para el dolor agudo y reducir el sangrado (Dismenorrea)", "Ácido tranexámico (para ayudar a reducir inmediatamente los episodios de sangrado extremadamente abundante)", "Cirugía ginecológica (miomectomía, ablación endometrial, laparoscopia por endometriosis o histerectomía en casos irreversibles y terminados los deseos de maternidad)"] } ], note: "Cambios en el peso (subir o bajar drásticamente) y reducir el estrés extremo a menudo pueden restaurar la menstruación ausente (amenorrea funcional)." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Es indispensable programar una cita con tu ginecólogo de inmediato si experimentas:", items: ["Sangrado menstrual tan intenso que debes empapar y cambiar una o más toallas sanitarias o tampones cada hora, durante varias horas seguidas", "Tus períodos han dejado de aparecer repentinamente durante más de tres meses o la menstruación nunca ha llegado y ya tienes 15 años", "Sangras entre períodos regulares, o presentas cualquier tipo de sangrado vaginal después de haber entrado en la menopausia", "Sufres cólicos menstruales tan paralizantes que no ceden con analgésicos de venta libre y te obligan a faltar a la escuela o al trabajo regularmente"] } },
'Trastorno de la conducta alimentaria' : { intro: "Los trastornos de la conducta alimentaria (TCA) son enfermedades mentales graves y complejas caracterizadas por alteraciones severas en los comportamientos, pensamientos y emociones relacionados con la comida, el peso y la imagen corporal. Tienen las tasas de mortalidad más altas de cualquier enfermedad psiquiátrica.", whatIs: { title: "¿Qué es un TCA?", text: "Son afecciones biológicas y psicológicas donde la comida se utiliza como un mecanismo desadaptativo para hacer frente al estrés profundo o la falta de control en la vida. Afectan drásticamente el funcionamiento físico del cuerpo, la salud ósea, el corazón y el tracto gastrointestinal." }, types: { title: "Principales Trastornos (DSM-5)", intro: "Los trastornos más comunes diagnosticados incluyen:", items: ["Anorexia nerviosa (restricción severa de alimentos, miedo intenso a engordar, bajo peso corporal peligroso y percepción corporal distorsionada)", "Bulimia nerviosa (episodios secretos de atracones masivos seguidos de purgas mediante vómitos, uso de laxantes o ejercicio extremo)", "Trastorno por atracón (comer cantidades inusualmente grandes de comida rápidamente y sentir pérdida de control, pero sin comportamientos de purga; es el TCA más común)", "ARFID o Trastorno por evitación/restricción de la ingesta de alimentos (falta de interés extrema en comer por aversión a texturas/colores de los alimentos o miedo a atragantarse, sin preocupación por la imagen corporal)"], note: "Pueden afectar a personas de cualquier edad, género, raza o tamaño corporal (muchas personas con TCA tienen un peso normal o mayor)." }, diagnosis: { title: "Evaluación Médica y Psiquiátrica", intro: "Se requiere una evaluación multidisciplinaria por el alto riesgo médico:", items: ["Exámenes físicos completos (análisis de sangre para detectar desequilibrios de electrolitos, desnutrición, daños renales, y un electrocardiograma (ECG) para el corazón)", "Evaluación psicológica exhaustiva guiada por los criterios del manual psiquiátrico DSM-5", "Evaluación de la densidad ósea y examen dental (frecuentes daños en el esmalte debido al ácido estomacal en la bulimia)"], note: "" }, treatment: { title: "Recuperación Integral", intro: "La recuperación es totalmente posible y requiere un equipo de profesionales (terapeutas, médicos y dietistas):", subsections: [ { title: "Intervenciones", items: ["Psicoterapia (Terapia Cognitivo-Conductual especializada (TCC-E), Terapia Basada en la Familia (FBT) especialmente efectiva en adolescentes)", "Asesoramiento y rehabilitación nutricional (para aprender hábitos de alimentación normales y restaurar el peso metabólico saludable de manera segura)", "Atención médica y hospitalización (frecuentemente necesaria en casos de anorexia extrema para estabilizar las constantes vitales o riesgo cardíaco)", "Medicación psiquiátrica (antidepresivos como la fluoxetina están aprobados para tratar la bulimia, o estabilizadores para tratar la ansiedad/depresión subyacentes)"] } ], note: "Superar un TCA a menudo lleva meses o años de esfuerzo continuo y apoyo familiar intenso." }, whenToSeekHelp: { title: "¿Cuándo intervenir o pedir ayuda?", intro: "Intervenir tempranamente salva vidas. Busca ayuda profesional inmediata si tú o alguien que amas presenta:", items: ["Pérdida o ganancia de peso dramática y rápida, mareos constantes, desmayos frecuentes, o la desaparición de la menstruación (amenorrea)", "Obsesión extrema por las calorías, los ingredientes, saltarse comidas de forma rutinaria y tener reglas rígidas sobre la comida", "Ir frecuentemente al baño justo después de las comidas, o encontrar grandes cantidades de comida escondida o envoltorios vacíos", "Llamar constantemente a partes del cuerpo 'gordas' o negarse a comer frente a otras personas"] } },
'Cirrosis' : { intro: "La cirrosis es la etapa tardía y severa de la formación de tejido cicatricial (fibrosis) en el hígado. Cada vez que el hígado se lesiona, intenta repararse a sí mismo formando tejido cicatricial. A medida que la cirrosis avanza, se forma cada vez más cicatriz, dificultando el funcionamiento del hígado.", whatIs: { title: "¿Qué es la Cirrosis Hepática?", text: "Es el daño crónico e irreversible del hígado. El tejido cicatricial duro reemplaza gradualmente al tejido hepático blando y sano, bloqueando el flujo de sangre a través del órgano. Esto incapacita al hígado para procesar nutrientes, hormonas, fármacos y toxinas de la sangre, y reduce la producción de proteínas vitales para la coagulación." }, types: { title: "Causas Principales", intro: "No es una enfermedad en sí, sino el resultado final de afecciones crónicas, como:", items: ["Consumo excesivo de alcohol durante muchos años (Cirrosis alcohólica)", "Infección crónica por el virus de la Hepatitis B o de la Hepatitis C", "Enfermedad del hígado graso no alcohólico (vinculada a la obesidad y la diabetes severa descontrolada)", "Enfermedades autoinmunes (Colangitis biliar primaria o hepatitis autoinmune)", "Enfermedades genéticas hereditarias (como la hemocromatosis, donde se acumula demasiado hierro en el hígado)"], note: "El daño hepático causado por la cirrosis generalmente no se puede deshacer." }, diagnosis: { title: "Evaluación Médica", intro: "Dado que es silenciosa al principio, a menudo se descubre en análisis rutinarios:", items: ["Análisis de sangre para verificar la función hepática, problemas de coagulación de la sangre, bilirrubina y detectar virus de hepatitis", "Elastografía por resonancia magnética (MRE) o ecografía transitoria (FibroScan) (pruebas de imagen especiales y no invasivas para detectar la rigidez u endurecimiento del hígado)", "Endoscopia superior (para verificar si hay varices esofágicas o vasos sanguíneos inflamados y peligrosos en el esófago, un síntoma clásico de cirrosis)", "Biopsia hepática (extraer un trozo de tejido para confirmar la gravedad, aunque las imágenes modernas a menudo la hacen innecesaria)"], note: "" }, treatment: { title: "Manejo de Complicaciones y Trasplante", intro: "El objetivo del tratamiento es retrasar el avance de la cicatrización y prevenir complicaciones mortales:", subsections: [ { title: "Tratamientos", items: ["Detener absolutamente el consumo de alcohol o tratar los virus de la hepatitis C o B de manera agresiva (dependiendo de la causa de origen)", "Medicamentos diuréticos y dieta baja en sal (para controlar la peligrosa acumulación de líquido en el abdomen, llamada ascitis)", "Medicamentos para la presión arterial, como betabloqueantes (para prevenir la hemorragia de las varices gástricas o esofágicas)", "Medicamentos para tratar la confusión mental o encefalopatía hepática (como la lactulosa para ayudar a eliminar toxinas)", "Trasplante de hígado (la única cura y última opción de tratamiento cuando el hígado llega a la insuficiencia hepática terminal)"] } ], note: "Vacunarse contra la hepatitis A y B, y la gripe/neumonía, es crítico para prevenir un fallo hepático agudo fatal sobre el crónico." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia absoluta?", intro: "Debes llamar a una ambulancia o ir a urgencias de inmediato si tienes cirrosis y desarrollas:", items: ["Vómitos masivos de sangre roja brillante, u obvias heces de color negro alquitrán y pegajosas (indicativo de rotura de varices, urgencia letal)", "Coloración amarillenta intensa y repentina en la piel y el blanco de los ojos (ictericia severa)", "Confusión repentina, somnolencia profunda, dificultad para hablar, o no saber dónde estás (encefalopatía hepática aguda)", "El abdomen se hincha rápidamente, sintiéndose duro y tenso, acompañado a veces de fiebre y dolor abdominal (infección del líquido ascítico)"] } },
'Cáncer testicular' : { intro: "El cáncer testicular ocurre en los testículos, las glándulas ubicadas dentro del escroto que producen hormonas reproductivas masculinas y espermatozoides. En comparación con otros tipos de cáncer, es poco frecuente, pero es el cáncer más común en hombres jóvenes (entre 15 y 35 años).", whatIs: { title: "¿Qué es el Cáncer Testicular?", text: "Es el crecimiento de células malignas dentro del testículo, formando típicamente un bulto sólido y firme. Afortunadamente, es uno de los cánceres más altamente tratables y curables, incluso cuando se ha diseminado más allá del testículo." }, types: { title: "Tipos de Tumores", intro: "Casi todos los cánceres de testículo comienzan en las células germinales (las que producen el esperma):", items: ["Tumores seminomatosos o seminomas (tienden a crecer y propagarse más lentamente, responden muy bien a la radiación y quimioterapia, comunes en hombres mayores)", "Tumores no seminomatosos (crecen y se propagan rápidamente, tienden a ocurrir en adolescentes o a principios de los 20 años; incluyen el carcinoma embrionario, tumor de saco vitelino y coriocarcinoma)"], note: "Tener un testículo no descendido en la infancia (criptorquidia) es un factor de riesgo muy significativo para el desarrollo de esta enfermedad." }, diagnosis: { title: "Detección y Pruebas", intro: "La detección a menudo comienza con el autoexamen del paciente; los médicos confirmarán con:", items: ["Ecografía testicular (la primera prueba esencial, determina si el bulto es sólido y probablemente canceroso o si es simplemente un quiste lleno de líquido inofensivo)", "Análisis de sangre para marcadores tumorales (midiendo altos niveles de AFP, hCG y LDH en la sangre, que son producidos por los tumores de células germinales)", "Tomografía Computarizada (TC) de abdomen, pelvis y tórax (para verificar, antes de cualquier cirugía, si el cáncer se ha diseminado a los ganglios linfáticos del abdomen o pulmones)", "Orquiectomía radical inguinal (cirugía de extirpación del testículo para realizar la biopsia final; la biopsia directa con aguja en el testículo nunca se hace porque puede diseminar el cáncer)"], note: "" }, treatment: { title: "Intervención Oncológica", intro: "Las posibilidades de curación completa son excelentes. El tratamiento principal es quirúrgico:", subsections: [ { title: "Opciones Terapéuticas", items: ["Orquiectomía radical (cirugía para extirpar todo el testículo afectado; a menudo es el único tratamiento necesario si se detecta tempranamente)", "Vigilancia activa (controles regulares con escáneres y análisis de sangre tras la cirugía si no hay signos de metástasis)", "Quimioterapia (se usa si el cáncer se ha propagado fuera del testículo o para disminuir el riesgo de que regrese)", "Radioterapia (usada a veces, principalmente para los seminomas, enfocada en los ganglios del abdomen)", "Disección de ganglios linfáticos retroperitoneales (RPLND) (cirugía mayor para extirpar los ganglios linfáticos del fondo del abdomen si hay metástasis)"] } ], note: "La cirugía y la quimioterapia pueden afectar la fertilidad, por lo que preservar el esperma en un banco de esperma antes del tratamiento es una recomendación fundamental." }, whenToSeekHelp: { title: "¿Cuándo acudir urgentemente al urólogo?", intro: "Es vital buscar evaluación médica rápida si notas o presentas:", items: ["Un bulto, abultamiento, nódulo firme (del tamaño de un guisante o más grande) en cualquiera de los testículos, que generalmente no causa dolor", "Una sensación repentina de pesadez pronunciada en el escroto, o inflamación del mismo", "Dolor sordo y persistente en el abdomen inferior, en la ingle o en el propio testículo", "Crecimiento repentino o sensibilidad en el tejido de los senos (ginecomastia) provocado por las hormonas que algunos tumores secretan"] } },
'Apnea del sueño de tipo obstructivo' : { intro: "La apnea obstructiva del sueño (AOS) es el trastorno respiratorio más común relacionado con el sueño. Hace que la persona deje de respirar o respire superficialmente repetidas veces durante el sueño, lo que fragmenta el descanso y reduce drásticamente el oxígeno en la sangre.", whatIs: { title: "¿Qué es la Apnea Obstructiva del Sueño?", text: "Es un colapso físico de las vías respiratorias. Durante el sueño profundo, los músculos de la parte posterior de la garganta se relajan excesivamente. Si la vía respiratoria es estrecha, se bloquea por completo, lo que detiene la entrada de aire. El cerebro se despierta parcialmente durante unos segundos para forzar la respiración, y esto puede ocurrir cientos de veces por noche." }, types: { title: "Severidad de la Enfermedad", intro: "Se clasifica por el Índice de Apnea-Hipopnea (IAH), que cuenta cuántas pausas respiratorias de al menos 10 segundos ocurren por hora:", items: ["AOS Leve (5 a 14 episodios de pausa por hora)", "AOS Moderada (15 a 29 episodios por hora)", "AOS Severa o grave (30 o más episodios por hora, a menudo requiriendo tratamiento médico inmediato)"], note: "Los ronquidos muy fuertes e intermitentes son el síntoma estrella de la AOS, pero no todas las personas que roncan la padecen." }, diagnosis: { title: "Estudios del Sueño", intro: "Para diagnosticarla correctamente, el neumólogo o especialista en medicina del sueño prescribirá:", items: ["Polisomnografía nocturna completa en un laboratorio del sueño (el estándar de oro: te conectan equipos que monitorizan tu actividad cerebral, respiración, niveles de oxígeno, y movimientos de piernas y ojos durante toda la noche)", "Estudio del sueño en casa (monitores portátiles más simples que miden el flujo de aire, el oxígeno en sangre y el pulso, útiles para descartar apnea severa)"], note: "El paciente a menudo no recuerda los despertares; es la pareja de cama quien suele notar que la persona deja de respirar o se atraganta." }, treatment: { title: "Tratamiento y Dispositivos", intro: "El tratamiento es altamente efectivo y devuelve la energía vital diurna perdida:", subsections: [ { title: "Terapias Recomendadas", items: ["Terapia CPAP (Presión Positiva Continua en las Vías Respiratorias): Es el tratamiento más común y fiable. Una máquina empuja aire constante a través de una mascarilla para mantener la garganta abierta mientras duermes.", "Dispositivos de avance mandibular u ortodóncicos (aparatos bucales recetados por un dentista que mueven la mandíbula inferior hacia adelante para abrir la vía aérea, útiles en apnea leve)", "Pérdida de peso agresiva, dejar el alcohol antes de dormir y dormir de lado (evitar la postura boca arriba)", "Cirugías como la UPPP (para extirpar tejido vibrante de la garganta) o implantes estimuladores del nervio hipogloso (solo si la CPAP falla por completo)"] } ], note: "La AOS no tratada aumenta inmensamente el riesgo de sufrir hipertensión severa, ataques cardíacos e infartos cerebrales." }, whenToSeekHelp: { title: "¿Cuándo consultar a un médico del sueño?", intro: "Es fundamental acudir a evaluación si tú (o tu pareja nota que tú):", items: ["Roncas con un volumen lo suficientemente alto como para perturbar el sueño de otras personas o te despiertas asustado con un ahogo brusco o jadeo por aire", "Experimentas somnolencia diurna paralizante, te quedas dormido involuntariamente mientras trabajas, ves la televisión o incluso conduces", "Haces pausas silenciosas prolongadas en tu respiración mientras duermes", "Te levantas por las mañanas con dolores de cabeza agudos inexplicables, boca extremadamente seca e irritabilidad o cambios de humor notables"] } },
'Pancreatitis' : { intro: "La pancreatitis es la inflamación repentina o crónica del páncreas, una glándula larga y plana ubicada detrás del estómago en la parte superior del abdomen. El páncreas produce enzimas que ayudan a la digestión y hormonas (como la insulina) que regulan el nivel de azúcar en sangre.", whatIs: { title: "¿Qué es la Pancreatitis?", text: "Se desarrolla cuando las fuertes enzimas digestivas producidas por el páncreas se activan prematuramente mientras todavía están dentro del propio órgano, en lugar de hacerlo en el intestino. Esto provoca que el páncreas comience literalmente a 'digerirse' a sí mismo, causando inflamación aguda y daño tisular profundo." }, types: { title: "Formas de la Enfermedad", intro: "Aparece clínicamente de dos formas distintas:", items: ["Pancreatitis aguda (aparece de forma repentina y grave, y suele durar pocos días; a menudo causada por la migración de un cálculo biliar que bloquea el conducto pancreático, o por un consumo de alcohol excesivo y concentrado)", "Pancreatitis crónica (la inflamación no se cura, empeora con el tiempo provocando daño permanente y cicatrización (fibrosis) del páncreas; la causa más frecuente es el alcoholismo crónico a largo plazo)"], note: "En episodios graves, la inflamación puede provocar que se filtren toxinas al torrente sanguíneo, causando fallos fatales en otros órganos como los pulmones o los riñones." }, diagnosis: { title: "Evaluación Médica Urgente", intro: "Ante el dolor severo, el médico de urgencias indicará:", items: ["Análisis de sangre para medir los niveles de las enzimas pancreáticas (lipasa y amilasa), que suelen estar en niveles extremadamente elevados durante un ataque agudo", "Tomografía Computarizada (TC) de abdomen o Resonancia Magnética (RM) (esenciales para ver la gravedad de la inflamación del páncreas y detectar si hay cálculos biliares, pseudoquistes o zonas muertas (necrosis))", "Ecografía abdominal (útil para detectar cálculos biliares como la causa raíz)", "Análisis de heces (en casos crónicos, para medir si el sistema digestivo está absorbiendo grasa o si el páncreas ya no funciona)"], note: "" }, treatment: { title: "Tratamiento Hospitalario", intro: "Los episodios agudos requieren hospitalización inminente para estabilizar el cuerpo:", subsections: [ { title: "Intervenciones y Manejo", items: ["Ayuno absoluto (suspender toda comida y bebida por la boca durante varios días para que el páncreas no tenga que trabajar ni producir enzimas)", "Líquidos por vía intravenosa (IV) de forma agresiva para prevenir la deshidratación y proteger el flujo de sangre a otros órganos", "Analgésicos potentes por vía intravenosa, ya que el dolor suele ser incapacitante", "Cirugía de vesícula biliar o CPRE (una vez que se controla la pancreatitis, si la causa es una piedra, se debe extirpar la vesícula para que no se repita el ataque)", "En casos crónicos crónicos: suplementos de enzimas digestivas (en pastillas) con cada comida, control de la diabetes y abstinencia total de alcohol para toda la vida"] } ], note: "Retomar la ingesta normal de alimentos será un proceso lento con caldos y dietas blandas antes del alta médica." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Acude a la sala de emergencias o llama al 911 de inmediato si presentas:", items: ["Un dolor extremadamente severo, punzante y constante en la parte superior central del abdomen, que se irradia y atraviesa hacia la espalda", "El dolor empeora tras comer o beber, y no encuentras una posición que lo calme (solo al encorvarte hacia adelante sientes un mínimo alivio)", "El dolor abdominal fuerte se acompaña de fiebre persistente, pulso rápido, náuseas violentas y vómitos repetitivos incontrolables", "Presentas un color amarillento en la piel y el blanco de los ojos (ictericia) o tu abdomen está muy hinchado y sensible al más mínimo roce"] } },
'Varicocele' : { intro: "Un varicocele es un agrandamiento o dilatación anormal de las venas (plexo pampiniforme) que se encuentran dentro del escroto, la bolsa de piel suelta que contiene los testículos. Es una condición venosa comparable a las venas varicosas (várices) que suelen aparecer en las piernas.", whatIs: { title: "¿Qué es un Varicocele?", text: "Se produce cuando las válvulas dentro de las venas que recorren el cordón espermático (el cual sostiene los testículos) fallan en funcionar correctamente, impidiendo que la sangre fluya fluidamente hacia arriba. La sangre retrocede y se acumula en las venas del escroto, dilatándolas. Esta acumulación aumenta la temperatura en los testículos, lo que puede dañar la producción y calidad del esperma." }, types: { title: "Clasificación Clínica", intro: "Se clasifica por su grado de notoriedad y lado del escroto:", items: ["Grado I a III (van desde varicoceles subclínicos, solo detectables por ecografía, hasta los de Grado III, que son venas gruesas, fácilmente visibles y palpables que se ven y sienten como una 'bolsa de gusanos' bajo la piel del escroto)", "Lateralidad (ocurren más del 85% de las veces en el lado izquierdo del escroto debido a la anatomía de las venas abdominales izquierdas, aunque pueden ocurrir en ambos lados)"], note: "Es una de las causas reversibles más comunes de baja producción y mala calidad de los espermatozoides (infertilidad masculina)." }, diagnosis: { title: "Evaluación Urológica", intro: "El urólogo o médico evaluará la condición en el consultorio:", items: ["Examen físico mientras el paciente está de pie, pidiéndole que puje y contenga la respiración (maniobra de Valsalva), lo cual hace que las venas varicosas sobresalgan más", "Ecografía escrotal con Doppler (prueba de ultrasonido que utiliza ondas sonoras para ver si hay flujo sanguíneo retrógrado anormal y medir el diámetro de las venas, descartando otros problemas como masas o hidroceles)", "Análisis o conteo de semen (espermiograma) para verificar si el varicocele está afectando activamente la fertilidad del paciente"], note: "" }, treatment: { title: "Manejo y Corrección Quirúrgica", intro: "La mayoría de los varicoceles que no causan síntomas no requieren tratamiento. Sin embargo, si causan dolor intenso o infertilidad, se tratan:", subsections: [ { title: "Opciones de Tratamiento", items: ["Varicocelectomía microscópica (el método de cirugía más eficaz y seguro: bajo el microscopio, el cirujano corta y amarra de manera precisa las venas hinchadas, redirigiendo la sangre a venas sanas)", "Embolización percutánea de varicocele (un radiólogo intervencionista pasa un tubo muy fino desde una vena de la ingle hasta la vena anormal y coloca espirales (coils) metálicos minúsculos para taponarla y sellarla por dentro sin hacer cortes escrotales)", "Manejo conservador (usar suspensorios testiculares ajustados o analgésicos de venta libre como el ibuprofeno si las molestias son leves o esporádicas)"] } ], note: "Tras el tratamiento quirúrgico para problemas de fertilidad, a menudo la calidad del esperma tarda de 3 a 6 meses en mostrar una mejoría significativa en los análisis." }, whenToSeekHelp: { title: "¿Cuándo consultar a un urólogo especializado?", intro: "Es altamente recomendable que busques evaluación de un médico si presentas:", items: ["Sientes un dolor sordo crónico, una sensación fuerte de pesadez o molestia en un testículo, que empeora claramente al final del día después de estar de pie o hacer esfuerzo físico", "Notas un bulto anormal por encima del testículo o ves o palpas venas torcidas e hinchadas que antes no estaban ahí", "Descubres que uno de los testículos es notable y visiblemente más pequeño que el otro (atrofia testicular) de forma progresiva", "Tú y tu pareja habéis estado intentando lograr un embarazo sin éxito durante un año y tienes venas varicosas escrotales sospechosas"] } },
'Hemorroides' : { intro: "Las hemorroides son venas hinchadas y dilatadas en el ano y la parte inferior del recto, similares a las venas varicosas. Son una causa muy común de sangrado rectal y molestias, afectando a millones de personas.", whatIs: { title: "¿Qué son las Hemorroides?", text: "Son almohadillas de tejido vascular que se han inflamado y estirado debido a un aumento de presión en la zona pélvica o rectal. Pueden causar dolor severo, picazón y sangrado durante o después de las deposiciones." }, types: { title: "Tipos de Hemorroides", intro: "Se clasifican según su ubicación:", items: ["Hemorroides internas (dentro del recto, rara vez causan dolor, pero suelen sangrar sin dolor)", "Hemorroides externas (debajo de la piel alrededor del ano, son las que más duelen, pican y sangran)", "Hemorroides trombosadas (cuando la sangre se acumula en una hemorroide externa y forma un coágulo, causando dolor intenso y un bulto duro)"], note: "El estreñimiento y el esfuerzo al defecar son las causas principales." }, diagnosis: { title: "Diagnóstico Médico", intro: "El médico las diagnostica fácilmente mediante:", items: ["Examen visual de la zona anal (para las externas)", "Tacto rectal (para sentir anormalidades dentro del recto)", "Anoscopia o proctoscopia (uso de un tubo corto con luz para ver las hemorroides internas)"], note: "Es vital descartar que el sangrado provenga de un cáncer de colon." }, treatment: { title: "Manejo y Tratamiento", intro: "Suelen responder bien a cambios en el estilo de vida y tratamientos menores:", subsections: [ { title: "Opciones de Alivio", items: ["Aumento de fibra y líquidos en la dieta para ablandar las heces", "Baños de asiento tibios y cremas/supositorios de venta libre (con hidrocortisona o lidocaína)", "Ligadura con banda elástica (el médico corta la circulación de la hemorroide interna para que se caiga)", "Hemorroidectomía (cirugía para extirpar hemorroides severas y persistentes)"] } ], note: "Evitar pasar mucho tiempo sentado en el inodoro ayuda a prevenir su aparición." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es fundamental consultar a un profesional si:", items: ["Experimentas sangrado rectal por primera vez (nunca asumas que son solo hemorroides)", "El dolor anal es insoportable y constante", "Sientes un bulto duro y muy doloroso en el ano que no mejora con cuidados en casa"] } },
'Manchas de la edad' : { intro: "Las manchas de la edad, también llamadas lentigos solares o manchas hepáticas, son áreas pequeñas y oscuras en la piel. Varían en tamaño y suelen aparecer en las zonas más expuestas al sol, como la cara, las manos, los hombros y los brazos.", whatIs: { title: "¿Qué son las Manchas de la Edad?", text: "Son áreas planas, ovaladas y pigmentadas de la piel causadas por años de exposición a la radiación ultravioleta (UV) del sol. La luz UV acelera la producción de melanina, que se agrupa formando estas manchas inofensivas." }, types: { title: "Características", intro: "Se identifican por:", items: ["Color marrón claro a negro oscuro", "Tamaño variable, desde una peca hasta más de un centímetro", "Aparición agrupada, haciéndolas más notorias", "Suelen aparecer en personas mayores de 50 años, aunque adultos más jóvenes expuestos al sol también pueden tenerlas"], note: "No son cáncer y no requieren tratamiento médico, solo cuidado estético si el paciente lo desea." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El dermatólogo las evalúa para diferenciarlas de lesiones malignas:", items: ["Examen visual directo (inspección clínica)", "Dermatoscopia (uso de lente especial para ver la estructura del pigmento)", "Biopsia de piel (solo si la mancha es irregular o sospechosa de melanoma)"], note: "A menudo se confunden con el melanoma, por lo que es vital la revisión experta." }, treatment: { title: "Aclaramiento y Prevención", intro: "Los tratamientos buscan reducir la pigmentación por razones cosméticas:", subsections: [ { title: "Opciones Estéticas", items: ["Cremas despigmentantes recetadas (hidroquinona o retinoides)", "Terapia con láser o luz pulsada intensa (IPL) para destruir los melanocitos dañados", "Peelings químicos o dermoabrasión (para renovar la capa superior de la piel)", "Uso estricto de protector solar diario para prevenir que se oscurezcan o salgan nuevas"] } ], note: "Cualquier tratamiento aclarador requiere protección solar constante, o las manchas volverán." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Debes buscar evaluación médica inmediata si una mancha:", items: ["Es de color negro muy oscuro o tiene múltiples colores", "Aumenta de tamaño rápidamente, tiene bordes irregulares o es asimétrica", "Sangra, pica, duele o se vuelve costrosa"] } },
'Pie Diabético' : { intro: "El pie diabético es una de las complicaciones más temidas de la diabetes mal controlada. Se caracteriza por la aparición de heridas, úlceras o infecciones destructivas en los pies debido a la falta de sensibilidad nerviosa y mala circulación.", whatIs: { title: "¿Qué es el Pie Diabético?", text: "Es un síndrome que resulta de dos problemas diabéticos mayores: la neuropatía (pérdida de sensación al dolor) y la isquemia (flujo sanguíneo reducido). El paciente no siente un roce o corte en el pie, la herida no sana por falta de sangre, y se infecta rápidamente." }, types: { title: "Complicaciones Asociadas", intro: "El proceso puede derivar en problemas severos:", items: ["Úlceras neuropáticas (heridas abiertas en puntos de presión que el paciente no siente)", "Infecciones profundas que llegan al hueso (osteomielitis)", "Pie de Charcot (deformidad y colapso de las articulaciones del pie por daño nervioso grave)", "Gangrena (muerte del tejido por falta total de sangre, requiriendo amputación)"], note: "Más del 80% de las amputaciones en diabéticos comienzan con una simple úlcera en el pie." }, diagnosis: { title: "Detección y Monitoreo", intro: "La prevención mediante revisión médica regular es vital:", items: ["Examen físico del pie (búsqueda de callosidades, deformidades o heridas ocultas)", "Prueba de sensibilidad con monofilamento (para evaluar la pérdida de nervios)", "Evaluación de los pulsos en el pie y mediciones de presión arterial en el tobillo (para evaluar circulación)", "Radiografías o RM (para descartar infecciones óseas)"], note: "" }, treatment: { title: "Manejo y Cuidado de Heridas", intro: "Requiere un abordaje multidisciplinario agresivo para salvar la extremidad:", subsections: [ { title: "Intervenciones", items: ["Desbridamiento (limpieza quirúrgica de tejido muerto o infectado)", "Descarga de presión (uso de yesos especiales o botas para no pisar la herida)", "Antibióticos fuertes (para infecciones confirmadas)", "Cirugía de revascularización (bypass o angioplastia en la pierna para restaurar el flujo de sangre)", "Amputación (solo como último recurso para salvar la vida del paciente ante infecciones incontrolables)"] } ], note: "El control estricto del azúcar en la sangre es el pilar de la curación." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Un paciente diabético debe ir al médico o urgencias el mismo día si nota:", items: ["Cualquier corte, ampolla o llaga abierta en el pie, por pequeña que sea", "Enrojecimiento anormal, hinchazón o calor en cualquier parte del pie o tobillo", "Cambios en el color de la piel del pie (negro, azulado o grisáceo)", "Secreción de pus o mal olor proveniente de una herida"] } },
'Cambios precancerosos del cuello uterino' : { intro: "Los cambios precancerosos del cuello uterino, a menudo conocidos como displasia cervical, son alteraciones anormales en las células de la superficie del cuello uterino. No son cáncer, pero sin tratamiento, pueden convertirse en cáncer de cuello uterino con el tiempo.", whatIs: { title: "¿Qué es la Displasia Cervical?", text: "Es el crecimiento de células escamosas anormales provocado por una infección persistente de tipos de alto riesgo del Virus del Papiloma Humano (VPH). Estas células no son malignas aún, pero tienen el potencial de mutar a cáncer si se dejan crecer sin vigilancia." }, types: { title: "Grados de Severidad", intro: "Se clasifican según el nivel de anormalidad celular (Neoplasia Intraepitelial Cervical o NIC):", items: ["NIC 1 / Lesión intraepitelial de bajo grado (cambios leves, a menudo desaparecen por sí solos sin tratamiento gracias al sistema inmunológico)", "NIC 2 / Lesión intraepitelial de alto grado moderada (cambios celulares más profundos)", "NIC 3 / Lesión de alto grado severa o carcinoma in situ (cambios muy avanzados que abarcan casi todo el grosor del epitelio, alto riesgo de cáncer invasivo)"], note: "Estos cambios son asintomáticos y solo se descubren mediante pruebas de cribado rutinarias." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Se detectan a través de la ginecología preventiva:", items: ["Prueba de Papanicolaou (Pap smear) que recolecta células para observarlas al microscopio", "Prueba del VPH (para detectar la presencia del virus causante)", "Colposcopia (examen detallado del cuello uterino con un microscopio especial tras aplicar ácido acético para resaltar las células anormales)", "Biopsia dirigida (toma de muestras de las áreas sospechosas para confirmar el grado de NIC en el laboratorio)"], note: "" }, treatment: { title: "Eliminación y Seguimiento", intro: "El tratamiento busca extirpar las células anormales preservando el cuello uterino:", subsections: [ { title: "Opciones Clínicas", items: ["Vigilancia activa (repetición de Papanicolaou en 6-12 meses para NIC 1, esperando que el cuerpo elimine el virus)", "Crioterapia (congelación de las células anormales para destruirlas)", "LEEP / Escisión electroquirúrgica con asa (uso de un alambre con corriente eléctrica para cortar la zona anormal)", "Conización o biopsia en cono (extracción quirúrgica de una porción en forma de cono del cuello uterino, recomendada para NIC 3)"] } ], note: "Tras el tratamiento, la paciente requerirá pruebas de seguimiento más frecuentes." }, whenToSeekHelp: { title: "¿Cuándo programar revisión?", intro: "Dado que no presenta síntomas, la acción principal es preventiva:", items: ["Asegúrate de no faltar a tus pruebas de Papanicolaou regulares según la frecuencia recomendada por tu médico según tu edad y factores de riesgo", "Consulta si presentas sangrado anormal (después del sexo o entre reglas), ya que esto podría indicar que la afección ha avanzado a un estadio superior"] } },
'Distimia' : { intro: "La distimia, clínicamente conocida como Trastorno Depresivo Persistente, es una forma de depresión continua y a largo plazo. Es menos severa que la depresión mayor, pero su duración crónica interfiere significativamente con la capacidad de disfrutar la vida.", whatIs: { title: "¿Qué es la Distimia?", text: "Es un estado de ánimo deprimido crónico. Las personas con distimia pueden sentirse tristes, vacías o sin esperanza la mayor parte del tiempo, durante al menos dos años en adultos, sintiendo que esta pesadumbre es simplemente 'su forma de ser'." }, types: { title: "Manifestación y Riesgos", intro: "Características temporales del trastorno:", items: ["Inicio temprano (antes de los 21 años) o de inicio tardío", "Episodios superpuestos (es común sufrir episodios de depresión mayor encima de la distimia, un cuadro clínico conocido como depresión doble)"], note: "Debido a su naturaleza a largo plazo, afecta profundamente las relaciones, la autoestima y el rendimiento laboral." }, diagnosis: { title: "Evaluación Psicológica", intro: "El especialista evalúa el patrón temporal de los síntomas:", items: ["Entrevista psiquiátrica buscando estado de ánimo deprimido que ocurre la mayor parte del día, durante al menos dos años", "Presencia de al menos dos de los siguientes síntomas: alteraciones del apetito o del sueño, fatiga, baja autoestima, problemas de concentración o sentimientos de desesperanza", "El paciente no ha estado sin síntomas durante más de 2 meses seguidos en ese periodo de dos años"], note: "" }, treatment: { title: "Manejo Terapéutico", intro: "El tratamiento a largo plazo es el enfoque más eficaz:", subsections: [ { title: "Opciones de Tratamiento", items: ["Psicoterapia (Terapia Cognitivo-Conductual para cambiar patrones de pensamiento arraigados o Terapia Interpersonal)", "Medicamentos antidepresivos (ISRS o ISRN, a menudo necesarios para corregir desequilibrios químicos a largo plazo)", "Cambios en el estilo de vida (ejercicio regular, higiene del sueño y técnicas de manejo del estrés)"] } ], note: "El tratamiento puede tardar meses en mostrar beneficios completos, requiriendo paciencia y compromiso." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda?", intro: "Es fundamental buscar apoyo profesional si:", items: ["Sientes que la falta de alegría, la tristeza o el vacío son partes inseparables de ti pero te impiden disfrutar tu vida", "Tus síntomas afectan negativamente tu trabajo, tus estudios o tus relaciones personales", "Experimentas pensamientos repentinos de suicidio, autolesión o de que no vale la pena vivir (urgencia médica)"] } },
'Obesidad mórbida' : { intro: "La obesidad mórbida, o severa, es una condición médica crónica grave caracterizada por una cantidad excesiva y peligrosa de grasa corporal. Se asocia con un riesgo altísimo de desarrollar enfermedades potencialmente mortales y afecta severamente la calidad y esperanza de vida.", whatIs: { title: "¿Qué es la Obesidad Mórbida?", text: "Médicamente, se define como tener un Índice de Masa Corporal (IMC) igual o superior a 40, o un IMC de 35 o más acompañado de problemas de salud graves relacionados con el peso. No es solo un problema de fuerza de voluntad, sino una enfermedad metabólica compleja." }, types: { title: "Comorbilidades Asociadas", intro: "Este grado de obesidad precipita múltiples patologías sistémicas:", items: ["Diabetes tipo 2 (debido a resistencia severa a la insulina)", "Enfermedades cardiovasculares (hipertensión, infartos, accidentes cerebrovasculares)", "Apnea obstructiva del sueño y problemas respiratorios crónicos", "Osteoartritis grave y daño en las articulaciones que soportan peso", "Mayor riesgo de múltiples tipos de cáncer (mama, colon, endometrio)"], note: "El tratamiento no es puramente estético, sino de supervivencia médica." }, diagnosis: { title: "Evaluación Médica Integral", intro: "El abordaje requiere una revisión completa de la salud del paciente:", items: ["Cálculo del IMC y medición del perímetro abdominal", "Análisis de sangre completos (perfil lipídico, glucosa en ayunas, función hepática, tiroides)", "Evaluación cardiológica (ECG) y pruebas de sueño", "Evaluación psicológica y psiquiátrica para detectar trastornos de la conducta alimentaria (ej. atracones) o depresión subyacente"], note: "" }, treatment: { title: "Intervenciones y Cirugía Bariátrica", intro: "Dado que las dietas tradicionales suelen fracasar en la obesidad extrema, las opciones médicas son escalonadas:", subsections: [ { title: "Terapias y Procedimientos", items: ["Modificación intensa del estilo de vida y supervisión nutricional", "Medicamentos antiobesidad recetados (como agonistas del GLP-1, ej. semaglutida o liraglutida) para controlar el apetito y hormonas metabólicas", "Cirugía bariátrica (el tratamiento más efectivo a largo plazo: Bypass gástrico, Manga gástrica o Manga gástrica, que altera la anatomía y las hormonas del sistema digestivo)", "Apoyo psicológico continuo para cambiar la relación emocional con la comida"] } ], note: "La cirugía bariátrica requiere un compromiso vitalicio con la toma de vitaminas y cambios de hábitos alimenticios." }, whenToSeekHelp: { title: "¿Cuándo acudir a un especialista en bariatría?", intro: "Es altamente recomendable buscar ayuda médica especializada si:", items: ["Tu IMC supera los 35 o 40 y los intentos de pérdida de peso tradicionales han fallado repetidamente a lo largo de los años", "Desarrollas problemas de salud graves limitantes (diabetes, apnea del sueño, dolor articular severo) directamente causados por tu peso", "Tu peso interfiere con actividades físicas básicas, como caminar distancias cortas, bañarte o vestirte"] } },
'Depresión posparto' : { intro: "La depresión posparto (DPP) es un trastorno del estado de ánimo complejo y severo que afecta a algunas madres después del parto. Va mucho más allá de la 'tristeza o melancolía posparto' normal (baby blues) y puede interferir con la capacidad de la madre para cuidar de sí misma o de su bebé.", whatIs: { title: "¿Qué es la Depresión Posparto?", text: "Es una complicación médica ligada a los drásticos cambios físicos, hormonales (caída en picado de estrógenos y progesterona) y emocionales que siguen al nacimiento de un hijo. Provoca sentimientos intensos de tristeza, ansiedad, agotamiento y, a menudo, culpa extrema." }, types: { title: "Espectro de Trastornos Posparto", intro: "Existen tres niveles de alteraciones del ánimo tras el parto:", items: ["Baby blues o melancolía posparto (afecta al 70-80% de las madres, dura unas dos semanas con llanto leve y ansiedad, se resuelve sola)", "Depresión posparto (más intensa y duradera, puede aparecer hasta un año después del parto, requiere tratamiento clínico)", "Psicosis posparto (una emergencia médica muy rara y severa, que incluye alucinaciones, delirios, paranoia y riesgo altísimo de dañar al bebé o a sí misma)"], note: "Los padres/hombres también pueden sufrir depresión posparto." }, diagnosis: { title: "Detección y Diagnóstico", intro: "El pediatra o ginecólogo evaluará los síntomas de la madre:", items: ["Uso de herramientas de detección estandarizadas, como la Escala de Depresión Posparto de Edimburgo (EPDS)", "Entrevista clínica evaluando sentimientos de inutilidad, pérdida de interés en el bebé, alteraciones severas de sueño (no poder dormir aunque el bebé duerma)", "Análisis de sangre para descartar disfunciones de la tiroides (que son comunes después del embarazo y simulan síntomas depresivos)"], note: "" }, treatment: { title: "Manejo y Recuperación", intro: "La DPP es altamente tratable y nadie debe sufrirla en silencio:", subsections: [ { title: "Intervenciones", items: ["Psicoterapia (Terapia Cognitivo-Conductual o Terapia Interpersonal, muy eficaces para procesar la nueva identidad materna y manejar el estrés)", "Antidepresivos (como los ISRS, muchos de los cuales son totalmente compatibles y seguros con la lactancia materna)", "Medicamentos específicos recientes (como la brexanolona, aprobada específicamente para inyección intravenosa u oral en DPP severa)", "Aumento del apoyo social y delegación del cuidado del bebé y tareas del hogar para asegurar el descanso de la madre"] } ], note: "Sufrir depresión posparto no significa que se es 'una mala madre'; es una complicación médica real." }, whenToSeekHelp: { title: "¿Cuándo es urgente pedir ayuda?", intro: "Llama a tu médico inmediatamente o acude a urgencias si experimentas:", items: ["Pensamientos intrusivos de hacerte daño a ti misma o de dañar a tu bebé", "Síntomas de psicosis: escuchas voces, ves cosas que no están ahí, o te sientes profundamente desconectada de la realidad", "La tristeza y el llanto duran más de dos semanas, empeoran en lugar de mejorar, o te incapacitan para levantarte de la cama y cuidar de tu hijo"] } },
'Fracturas por compresión o aplastamiento vertebral' : { intro: "Una fractura por compresión vertebral ocurre cuando uno o más huesos de la columna (vértebras) se debilitan y colapsan o se aplastan. La causa subyacente más común, con diferencia, es la osteoporosis, seguida de traumatismos severos o cáncer metastásico.", whatIs: { title: "¿Qué son las Fracturas por Compresión?", text: "Son roturas estructurales en el cuerpo de la vértebra. Cuando el hueso es demasiado frágil, presiones normales como toser, levantar un objeto ligero o agacharse pueden hacer que la parte frontal de la vértebra se acuñe y colapse, causando dolor agudo o crónico." }, types: { title: "Consecuencias Clínicas", intro: "Estas fracturas pueden resultar en deformidades físicas notables a largo plazo:", items: ["Pérdida de estatura (acortamiento progresivo del tronco)", "Cifosis torácica (desarrollo de una postura muy encorvada o 'joroba de viuda' debido a que múltiples vértebras colapsadas en forma de cuña tiran de la columna hacia adelante)", "Dolor de espalda crónico, fatiga muscular y dificultad para respirar o comer por compresión de los órganos internos debido a la deformidad"], note: "Aproximadamente 2/3 de las fracturas vertebrales pasan desapercibidas y son asintomáticas, descubiertas en radiografías por otros motivos." }, diagnosis: { title: "Evaluación Radiológica", intro: "El especialista en columna confirmará la fractura mediante:", items: ["Radiografías de la columna (muestran claramente la forma de cuña o el aplastamiento del hueso)", "Densitometría ósea (DEXA) para confirmar y medir el grado de osteoporosis subyacente", "Resonancia magnética (RM) (vital para determinar si la fractura es aguda/reciente o crónica/vieja, y si hay compresión de la médula espinal o un tumor causándola)"], note: "" }, treatment: { title: "Alivio del Dolor y Estabilización", intro: "El enfoque incluye tratar la fractura actual y prevenir futuras roturas:", subsections: [ { title: "Opciones Médicas y Quirúrgicas", items: ["Reposo breve, analgésicos y uso de corsés o aparatos ortopédicos para dar soporte externo a la columna mientras sana", "Tratamiento médico intensivo de la osteoporosis (medicamentos fijadores de calcio como bifosfonatos) para evitar que las vértebras sanas colapsen después", "Vertebroplastia o Cifoplastia (procedimientos quirúrgicos mínimamente invasivos donde se inyecta cemento óseo especial en la vértebra rota para estabilizarla y aliviar el dolor severo rápidamente)"] } ], note: "La fisioterapia cautelosa es importante después de la curación inicial para fortalecer los músculos que sostienen la espalda." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias o al médico?", intro: "Debes buscar evaluación médica si tienes riesgo de osteoporosis y presentas:", items: ["Dolor de espalda severo, repentino y de aparición brusca (a menudo como un 'pinchazo' agudo) tras un esfuerzo mínimo", "El dolor de espalda empeora significativamente al estar de pie o caminar, pero disminuye al recostarte sobre tu espalda", "Aparición de adormecimiento, debilidad, hormigueo en las piernas, o problemas repentinos para controlar la orina o el intestino (señales de compromiso neurológico grave)"] } },
'Hipotiroidismo' : { intro: "El hipotiroidismo (tiroides hipoactiva) es un trastorno del sistema endocrino en el que la glándula tiroides no produce suficiente cantidad de ciertas hormonas cruciales. Esto ralentiza drásticamente el metabolismo del cuerpo, causando fatiga, aumento de peso y sensibilidad al frío.", whatIs: { title: "¿Qué es el Hipotiroidismo?", text: "Es la deficiencia de hormonas tiroideas (T3 y T4). Cuando estas hormonas bajan, todas las funciones corporales se 'desaceleran'. A menudo es causado por la tiroiditis de Hashimoto, una enfermedad autoinmune donde el cuerpo ataca y destruye su propia glándula tiroidea." }, types: { title: "Causas y Formas Comunes", intro: "Puede originarse por diversos factores médicos o ambientales:", items: ["Tiroiditis de Hashimoto (la causa más común, trastorno autoinmune)", "Tratamiento por hipertiroidismo (cirugía o yodo radiactivo que eliminaron demasiada tiroides)", "Hipotiroidismo congénito (bebés que nacen sin la glándula o con una defectuosa)", "Hipotiroidismo secundario (problemas en la glándula pituitaria que no envía la señal o TSH a la tiroides)"], note: "En etapas tempranas, los síntomas son muy sutiles y se confunden fácilmente con el envejecimiento o el estrés crónico." }, diagnosis: { title: "Pruebas de Sangre Endocrinas", intro: "El diagnóstico es simple y muy preciso mediante análisis de sangre:", items: ["Prueba de TSH (Hormona Estimulante de la Tiroides): Un nivel alto de TSH indica que la pituitaria está tratando desesperadamente de estimular a una tiroides perezosa", "Prueba de T4 libre (Tiroxina): Un nivel bajo de T4 libre, junto con una TSH alta, confirma el diagnóstico clínico de hipotiroidismo primario", "Prueba de anticuerpos antitiroideos (TPO) para confirmar si la causa es la enfermedad autoinmune de Hashimoto"], note: "" }, treatment: { title: "Terapia de Reemplazo Hormonal", intro: "El tratamiento es altamente efectivo, seguro y, en la inmensa mayoría de los casos, de por vida:", subsections: [ { title: "Manejo Médico", items: ["Levotiroxina sintética oral diaria (una píldora que reemplaza la hormona T4 que el cuerpo ya no produce)", "Ajustes periódicos de la dosis mediante análisis de TSH (generalmente cada 6-12 meses una vez que el paciente está estable)", "Debe tomarse con el estómago vacío, idealmente a primera hora de la mañana y esperando antes de comer o tomar otros medicamentos"] } ], note: "Una vez que la dosis es la correcta, los síntomas desaparece por completo y el metabolismo se normaliza." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir análisis de tiroides si experimentas constantemente:", items: ["Cansancio extremo e inexplicable, debilidad muscular o letargo a pesar de dormir bien", "Aumento de peso sin cambios en la dieta, y dificultad extrema para perder peso", "Estreñimiento severo, piel muy seca, uñas quebradizas o caída del cabello inusual", "Sientes mucho frío incluso cuando las demás personas están cómodas o tienen calor", "Períodos menstruales muy abundantes, irregulares o problemas crónicos de infertilidad"] } },
'Trastornos del sueño' : { intro: "Los trastornos del sueño son afecciones que provocan cambios o interrupciones constantes en la forma de dormir. Un trastorno del sueño puede afectar gravemente tu salud, seguridad y calidad de vida, causando privación de sueño y somnolencia diurna paralizante.", whatIs: { title: "¿Qué son los Trastornos del Sueño?", text: "Se trata de problemas persistentes para conciliar el sueño, permanecer dormido, dormir en los momentos equivocados, dormir demasiado, o presentar comportamientos y movimientos anormales durante el descanso nocturno. Interrumpen el ciclo de restauración fundamental del cerebro y el cuerpo." }, types: { title: "Principales Categorías", intro: "Existen más de 80 trastornos del sueño, pero los más frecuentes incluyen:", items: ["Insomnio (dificultad para conciliar o mantener el sueño)", "Apnea del sueño (interrupciones de la respiración durante la noche)", "Síndrome de piernas inquietas (necesidad irresistible y dolorosa de mover las piernas al estar acostado)", "Narcolepsia ('ataques de sueño' irresistibles y repentinos durante el día)", "Parasomnias (comportamientos anormales como sonambulismo, terrores nocturnos o actuar los sueños)"], note: "" }, diagnosis: { title: "Estudios Clínicos del Sueño", intro: "Un especialista en medicina del sueño investigará la causa raíz mediante:", items: ["Polisomnografía (estudio del sueño nocturno en una clínica para monitorizar ondas cerebrales, respiración, frecuencia cardíaca, oxígeno y movimientos oculares)", "Actigrafía (uso de un sensor tipo reloj durante semanas para medir los ciclos de sueño/vigilia en casa)", "Test de Latencia Múltiple del Sueño (MSLT) (para diagnosticar la narcolepsia midiendo cuán rápido te duermes durante el día)"], note: "Un diario de sueño detallado llevado por el paciente es a menudo la primera y mejor herramienta diagnóstica." }, treatment: { title: "Terapias, Dispositivos y Medicación", intro: "El tratamiento varía drásticamente según el trastorno específico detectado:", subsections: [ { title: "Opciones de Tratamiento", items: ["Terapia Cognitivo-Conductual para el Insomnio (TCC-I) (el tratamiento de primera línea, más efectivo a largo plazo que las pastillas para dormir)", "Dispositivos CPAP (máquinas de presión de aire) para la apnea obstructiva del sueño", "Medicación (fármacos hipnóticos para el insomnio severo a corto plazo, agonistas de la dopamina para las piernas inquietas, o estimulantes para la narcolepsia)", "Medidas de higiene del sueño (horarios regulares, evitar pantallas y cafeína de noche, mantener la habitación fresca y oscura)"] } ], note: "Depender rutinariamente de pastillas para dormir de venta libre o melatonina rara vez soluciona el problema de fondo." }, whenToSeekHelp: { title: "¿Cuándo consultar a un especialista en sueño?", intro: "Debes buscar evaluación médica si experimentas:", items: ["Tardas más de 30 minutos en dormirte o te despiertas repetidamente y no puedes volver a dormir, varias veces a la semana durante meses", "Sufres de somnolencia diurna excesiva, cabeceando al volante, en el trabajo o viendo televisión", "Tu pareja de cama reporta que roncas muy fuerte, jadeas, haces pausas al respirar o pateas violentamente durante la noche"] } },
'Diabetes tipo 1' : { intro: "La diabetes tipo 1, una vez conocida como diabetes juvenil o diabetes insulinodependiente, es una afección crónica severa en la que el páncreas produce poca o ninguna insulina por sí mismo.", whatIs: { title: "¿Qué es la Diabetes Tipo 1?", text: "Es una enfermedad autoinmune en la que el sistema inmunológico del cuerpo ataca y destruye por error las células beta (productoras de insulina) en el páncreas. Sin insulina, el cuerpo no puede mover la glucosa (azúcar) de la sangre a las células para obtener energía, provocando niveles de azúcar en sangre letalmente altos." }, types: { title: "Características", intro: "A diferencia de la tipo 2, no está ligada al estilo de vida:", items: ["Suele aparecer en la infancia, adolescencia o en adultos jóvenes (aunque puede desarrollarse a cualquier edad, como en la diabetes LADA)", "Es absolutamente dependiente de la insulina sintética para la supervivencia desde el momento del diagnóstico", "Tiene un fuerte componente genético, combinado con desencadenantes ambientales desconocidos (como posibles virus)"], note: "La cetoacidosis diabética (CAD) es a menudo el primer signo de la enfermedad no diagnosticada, y es una urgencia médica grave." }, diagnosis: { title: "Confirmación de Laboratorio", intro: "El endocrinólogo confirmará el diagnóstico y diferenciará del tipo 2 mediante:", items: ["Análisis de glucosa en sangre aleatoria o en ayunas, y prueba de Hemoglobina A1C (para ver el nivel promedio de azúcar en los últimos meses)", "Prueba de autoanticuerpos relacionados con la diabetes (GADA, IAA, ICA, ZnT8A) (su presencia confirma la naturaleza autoinmune y el diagnóstico de Tipo 1)", "Prueba del Péptido C (para medir si el páncreas aún está produciendo algo de insulina; en el tipo 1 avanzado, es casi nulo)"], note: "" }, treatment: { title: "Manejo Diario Crítico", intro: "Es una enfermedad implacable que requiere gestión 24/7 de por vida:", subsections: [ { title: "Pilares del Tratamiento", items: ["Terapia de insulina obligatoria de por vida (mediante inyecciones múltiples diarias con plumas o una bomba de infusión de insulina continua)", "Monitoreo continuo de glucosa (MCG) (sensores en la piel que leen el azúcar constantemente) o punciones capilares frecuentes en los dedos", "Conteo exacto de carbohidratos (para saber exactamente cuánta insulina inyectarse antes de cada comida)", "Manejo minucioso de la hipoglucemia (azúcar baja) y el ejercicio físico"] } ], note: "Nuevos sistemas de 'páncreas artificial' que conectan el monitor continuo con la bomba de insulina están revolucionando el control de la enfermedad." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Los síntomas de inicio o de cetoacidosis (CAD) son una urgencia vital inminente. Acude al hospital si tú o tu hijo presentan:", items: ["Sed insaciable extrema y necesidad de orinar constantemente (incluso mojando la cama en niños que ya no lo hacían)", "Pérdida de peso muy rápida y repentina a pesar de tener un apetito feroz", "Aliento con olor afrutado o a esmalte de uñas, respiración rápida y profunda, náuseas, vómitos y dolor de estómago (signos clásicos de Cetoacidosis)", "Confusión extrema, letargo, visión borrosa o pérdida del conocimiento"] } },
'Ovarios poliquísticos' : { intro: "El síndrome de ovario poliquístico (SOP o PCOS en inglés) es un trastorno hormonal frecuente en las mujeres en edad reproductiva. Puede causar períodos menstruales infrecuentes o prolongados, así como niveles excesivos de hormonas masculinas (andrógenos).", whatIs: { title: "¿Qué es el SOP?", text: "Es un desequilibrio metabólico y endocrino donde los ovarios pueden desarrollar numerosas pequeñas acumulaciones de líquido (folículos o 'quistes') y no liberar óvulos regularmente. Está fuertemente ligado a la resistencia a la insulina y es una de las causas principales de infertilidad femenina." }, types: { title: "Características y Criterios", intro: "El síndrome se diagnostica cuando se cumplen al menos dos de los siguientes (Criterios de Rotterdam):", items: ["Irregularidad menstrual (ciclos muy largos, oligomenorrea, o ausencia de regla, amenorrea)", "Exceso de andrógenos (signos clínicos como exceso de vello, o detectados en análisis de sangre)", "Ovarios poliquísticos (múltiples folículos visibles en la ecografía que aumentan el tamaño del ovario)"], note: "A pesar de su nombre, no todas las mujeres con SOP tienen quistes ováricos, y tener quistes no significa necesariamente tener SOP." }, diagnosis: { title: "Evaluación Ginecológica y Endocrina", intro: "Para llegar al diagnóstico se requiere:", items: ["Examen físico y de historial médico detallado (peso, signos de vello facial, acné, acantosis nigricans)", "Análisis de sangre completos (niveles hormonales de testosterona, LH, FSH, así como pruebas de tolerancia a la glucosa y colesterol)", "Ecografía pélvica o transvaginal (para inspeccionar la apariencia y volumen de los ovarios y el grosor del revestimiento uterino)"], note: "" }, treatment: { title: "Tratamiento y Manejo", intro: "El tratamiento se enfoca en las preocupaciones individuales, como la fertilidad, el hirsutismo, el acné o la obesidad:", subsections: [ { title: "Terapias", items: ["Cambios en el estilo de vida (pérdida de peso, dieta baja en carbohidratos simples y ejercicio regular para reducir la resistencia a la insulina)", "Anticonceptivos hormonales (píldoras, parches o anillo para regular el ciclo, reducir el riesgo de cáncer de endometrio y controlar el acné/vello)", "Metformina (medicamento para la diabetes tipo 2 que mejora la resistencia a la insulina y puede reiniciar la ovulación)", "Medicamentos antiandrógenos (para bloquear los efectos de las hormonas masculinas)", "Tratamientos de fertilidad (Clomifeno, Letrozol o FIV si la paciente desea quedar embarazada)"] } ], note: "El control del SOP es a largo plazo para prevenir diabetes tipo 2 y enfermedades cardíacas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación si:", items: ["Tus períodos menstruales son constantemente irregulares, tienes menos de 8 ciclos al año, o la menstruación se detiene por completo", "Notas un crecimiento excesivo de vello en la cara, pecho, abdomen o muslos (hirsutismo) o acné adulto severo", "Estás intentando quedar embarazada sin éxito durante más de 12 meses", "Sufres de aumento de peso inexplicable y áreas de piel oscura y aterciopelada en el cuello o axilas"] } },
'Resfriado común' : { intro: "El resfriado común es una infección viral leve pero molesta de la nariz y la garganta (tracto respiratorio superior). Por lo general, es inofensivo y la mayoría de las personas se recuperan por completo en una o dos semanas sin necesidad de tratamiento médico.", whatIs: { title: "¿Qué es un Resfriado?", text: "Es una enfermedad infecciosa causada por más de 200 tipos diferentes de virus (el rinovirus es el más común). Provoca inflamación en las membranas mucosas de la nariz, resultando en estornudos, congestión, dolor de garganta y secreción nasal continua." }, types: { title: "Diferenciación de otras Infecciones", intro: "Es crucial distinguirlo de la gripe o alergias:", items: ["Resfriado: Inicio gradual de síntomas, fiebre ausente o muy leve, estornudos y congestión son los síntomas predominantes, poca afectación del estado general", "Gripe (Influenza): Inicio abrupto, fiebre alta casi siempre presente, dolores musculares severos, fatiga extrema", "Alergias: Solo secreción nasal clara, mucha picazón en los ojos y nariz, estornudos en ráfagas, y dura mientras dure la exposición (semanas o meses) sin fiebre"], note: "Los adultos tienen en promedio 2-3 resfriados al año; los niños pequeños pueden tener hasta 8-10." }, diagnosis: { title: "Diagnóstico", intro: "El diagnóstico es clínico y casero:", items: ["No se requieren pruebas de laboratorio ni visitas al médico en la inmensa mayoría de los casos", "Se basa puramente en la autoevaluación de síntomas típicos (moco, tos leve, dolor de garganta sin placas de pus)"], note: "" }, treatment: { title: "Alivio de Síntomas", intro: "No existe cura ni vacuna para el resfriado. Los antibióticos no sirven contra los virus. El tratamiento busca el confort:", subsections: [ { title: "Remedios Caseros y Fármacos", items: ["Descanso adecuado e hidratación constante (agua, caldos, tés calientes con miel)", "Analgésicos y antipiréticos de venta libre (paracetamol o ibuprofeno) para el malestar y dolores de cabeza", "Descongestionantes nasales o aerosoles de solución salina para destapar la nariz (los aerosoles medicados no deben usarse más de 3 días para evitar efecto rebote)", "Caramelos para la garganta o pastillas para la tos"] } ], note: "No administre medicamentos para la tos y el resfriado de venta libre a niños menores de 4 años sin autorización del pediatra." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Un resfriado se complica a veces en infecciones bacterianas (sinusitis, otitis o neumonía). Consulta al médico si:", items: ["Los síntomas duran más de 10-14 días sin mejoría, o parecen mejorar pero de repente empeoran significativamente (fiebre nueva)", "Tienes fiebre muy alta y persistente, sudoración y escalofríos severos", "Experimentas dolor grave en el pecho, dificultad genuina para respirar o tos que produce moco de color marrón, verde oscuro o con sangre", "Tienes un dolor de oído agudo (sospecha de otitis) o dolor punzante en la frente/mejillas (sospecha de sinusitis bacteriana)"] } },
'Cáncer vesical' : { intro: "El cáncer vesical o de vejiga es uno de los cánceres más comunes y se forma en los tejidos de la vejiga urinaria, el órgano muscular hueco en la parte inferior del abdomen que almacena la orina. La sangre en la orina es, con diferencia, el síntoma más frecuente.", whatIs: { title: "¿Qué es el Cáncer Vesical?", text: "Es el crecimiento descontrolado de células tumorales, casi siempre comenzando en las células uroteliales que recubren el interior de la vejiga. A menudo se detecta en estadios tempranos cuando es altamente tratable, pero tiene una gran tendencia a reaparecer (recurrir), requiriendo vigilancia de por vida." }, types: { title: "Tipos y Estadificación", intro: "El comportamiento del tumor determina el tratamiento:", items: ["Carcinoma urotelial (el más común, también ocurre en los riñones y uréteres)", "Cáncer de vejiga no músculo invasivo (NMIBC) (el tumor está limitado al revestimiento interno de la vejiga y no ha penetrado la pared muscular; buen pronóstico pero alta recurrencia)", "Cáncer de vejiga músculo invasivo (MIBC) (el tumor ha crecido profundamente en la pared muscular del órgano, es más agresivo y requiere tratamientos mayores para evitar metástasis)"], note: "El tabaquismo es el factor de riesgo número uno, causando aproximadamente la mitad de todos los casos de cáncer de vejiga." }, diagnosis: { title: "Detección y Confirmación", intro: "El urólogo empleará métodos visuales y de laboratorio:", items: ["Cistoscopia (la prueba principal: inserción de un tubo delgado con una cámara a través de la uretra para inspeccionar el interior de la vejiga)", "Citología de orina (análisis de una muestra de orina bajo el microscopio para buscar células cancerosas desprendidas)", "Biopsia o Resección Transuretral de Tumor de Vejiga (TURBT) (procedimiento quirúrgico menor para extraer el tumor durante una cistoscopia y analizar su invasividad)", "Tomografía computarizada (urografía por TC) para ver los riñones, uréteres y evaluar si el cáncer se ha diseminado a ganglios cercanos"], note: "" }, treatment: { title: "Opciones Oncológicas y Quirúrgicas", intro: "El manejo varía drásticamente según la invasión del músculo:", subsections: [ { title: "Tratamientos Principales", items: ["Cirugía TURBT (para raspar y extirpar tumores superficiales no invasivos tempranos)", "Terapia intravesical (lavados directos dentro de la vejiga con quimioterapia o inmunoterapia BCG -vacuna de la tuberculosis- para prevenir la recurrencia de tumores superficiales)", "Cistectomía radical (cirugía mayor para extirpar toda la vejiga y construir una nueva vía de derivación urinaria, necesaria en cánceres músculo-invasivos)", "Quimioterapia y radioterapia (a menudo usadas antes de la cirugía para encoger tumores profundos o como alternativa en pacientes inoperables)"] } ], note: "La vigilancia con cistoscopias regulares cada pocos meses es mandatoria durante años tras el tratamiento inicial." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico urgentemente?", intro: "Nunca ignores problemas urinarios. Busca a un urólogo inmediatamente si notas:", items: ["Presencia de sangre en la orina (hematuria), ya sea que la orina se vea de color rojo brillante o marrón óxido, incluso si no te duele nada (la hematuria indolora es la principal señal de alarma)", "Necesidad de orinar con mucha mayor frecuencia de lo habitual o sentir una urgencia repentina y desesperada", "Dolor o ardor al orinar que no se debe a una infección urinaria confirmada", "Dolor pélvico o dolor sordo en un lado de la espalda baja persistente"] } },
'Hepatitis' : { intro: "La hepatitis es la inflamación del hígado, un órgano vital que procesa nutrientes, filtra la sangre y combate infecciones. Cuando el hígado está inflamado o dañado, su función puede verse seriamente afectada, pudiendo llevar a daño crónico, cirrosis o cáncer hepático.", whatIs: { title: "¿Qué es la Hepatitis?", text: "Es una condición inflamatoria hepática. Aunque puede ser causada por toxinas, consumo excesivo de alcohol, ciertos medicamentos o enfermedades autoinmunes, la gran mayoría de los casos son infecciones virales sistemáticas (Hepatitis Viral)." }, types: { title: "Los Virus de la Hepatitis (A, B, C)", intro: "Los virus principales difieren en su modo de transmisión y severidad:", items: ["Hepatitis A (se transmite por alimentos/agua contaminados con heces; causa una enfermedad aguda severa pero de corta duración, el cuerpo la elimina por completo; hay vacuna)", "Hepatitis B (se transmite por fluidos corporales infectados como sangre, semen o durante el parto; puede ser aguda o volverse crónica y causar cirrosis; hay vacuna)", "Hepatitis C (se transmite principalmente por contacto directo con sangre infectada, como compartir agujas; a menudo es silenciosa y se vuelve crónica en el 70-85% de los casos; NO hay vacuna, pero ahora es curable con medicamentos)"], note: "Las hepatitis D y E son menos comunes, pero igualmente graves." }, diagnosis: { title: "Detección y Evaluación del Hígado", intro: "El diagnóstico temprano, especialmente en la Hepatitis C, salva vidas:", items: ["Análisis de sangre para medir enzimas hepáticas (ALT, AST), que estarán muy elevadas si el hígado está inflamado", "Panel serológico viral específico (pruebas de sangre para identificar los antígenos y anticuerpos exactos de los virus A, B o C y ver si la infección es activa o pasada)", "Ecografía abdominal o Elastografía (FibroScan) para comprobar el nivel de cicatrización del hígado (fibrosis o cirrosis)", "Biopsia hepática (cada vez menos común gracias a las imágenes modernas)"], note: "" }, treatment: { title: "Manejo y Medicamentos Antivirales", intro: "El tratamiento depende enteramente del tipo de hepatitis y si es aguda o crónica:", subsections: [ { title: "Intervenciones Médicas", items: ["Hepatitis A: No hay tratamiento específico; requiere reposo, hidratación y tiempo. Prevención mediante vacunación.", "Hepatitis B Crónica: Medicamentos antivirales orales (ej. Entecavir, Tenofovir) de por vida para suprimir el virus y evitar el daño hepático, ya que raramente se cura. Prevención mediante vacunación.", "Hepatitis C: Antivirales de Acción Directa (AAD) orales durante 8 a 12 semanas, que logran erradicar (curar) el virus en más del 95% de los pacientes.", "Hepatitis autoinmune: Corticosteroides e inmunosupresores para frenar el ataque del cuerpo a su propio hígado"] } ], note: "Los pacientes con hepatitis crónica deben abstenerse completamente del alcohol y de medicamentos metabolizados en el hígado como el paracetamol excesivo." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "La hepatitis aguda puede escalar rápidamente a fallo hepático. Busca ayuda médica urgente si presentas:", items: ["Ictericia (tu piel y el blanco de tus ojos adquieren un notorio y súbito color amarillento)", "Tu orina se vuelve muy oscura (color té oscuro o coca-cola) y tus heces se vuelven de color arcilla pálida o masilla", "Experimentas náuseas y vómitos violentos constantes que te impiden retener líquidos", "Sientes confusión inusual, desorientación o letargo profundo (posible encefalopatía hepática)"] } },
'Síndrome de burnout' : { intro: "El síndrome de burnout (o síndrome del trabajador quemado) es un estado de agotamiento físico, emocional y mental extremo resultado del estrés crónico en el lugar de trabajo. No es un simple cansancio, sino un desgaste profundo que anula la motivación y la capacidad de rendimiento.", whatIs: { title: "¿Qué es el Burnout?", text: "Reconocido por la OMS como un fenómeno ocupacional, ocurre cuando un individuo se siente abrumado por demandas constantes, falta de control y falta de reconocimiento. La persona entra en un estado de cinismo, desconexión emocional de su labor y sensación de ineficacia profesional." }, types: { title: "Dimensiones y Síntomas", intro: "El síndrome se caracteriza clásicamente por tres dimensiones principales:", items: ["Agotamiento extremo (sensación de vacío de energía y recursos físicos y emocionales al pensar en el trabajo)", "Despersonalización o cinismo (distanciamiento mental del trabajo, sentimientos de negatividad, frialdad o irritabilidad excesiva hacia clientes, pacientes o compañeros)", "Reducción de la eficacia profesional (sentimiento de incompetencia, caída de la productividad y falta de logros)"], note: "Si no se atiende, el burnout se traduce en problemas físicos reales: insomnio severo, problemas digestivos, dolores de cabeza y vulnerabilidad a enfermedades." }, diagnosis: { title: "Evaluación Psicológica", intro: "No es un diagnóstico médico oficial (como la depresión), pero los profesionales de la salud mental lo evalúan mediante:", items: ["Uso de cuestionarios validados, siendo el más famoso el Inventario de Burnout de Maslach (MBI)", "Entrevistas clínicas para diferenciarlo de la depresión mayor o los trastornos de ansiedad generalizada (el burnout es específico del contexto laboral, aunque puede desembocar en depresión)", "Revisión del entorno laboral (sobrecarga de tareas, conflicto de valores, micromanagement)"], note: "" }, treatment: { title: "Intervención y Recuperación", intro: "La solución al burnout requiere cambios en el entorno laboral y en las estrategias de afrontamiento de la persona:", subsections: [ { title: "Medidas Terapéuticas", items: ["Desconexión temporal (tomar una licencia por enfermedad o vacaciones reales para distanciarse del entorno tóxico)", "Reestructuración laboral (establecer límites rígidos de horas, aprender a decir 'no' a nuevas cargas, renegociar expectativas con los superiores)", "Psicoterapia (para aprender a manejar el estrés, el perfeccionismo y desarrollar resiliencia emocional)", "Prácticas de autocuidado rigurosas (priorizar el sueño innegociable, el ejercicio y actividades de ocio totalmente ajenas a la profesión)"] } ], note: "A menudo, la recuperación completa puede requerir un cambio de departamento, de empresa o incluso de carrera profesional." }, whenToSeekHelp: { title: "¿Cuándo pedir apoyo profesional?", intro: "Debes buscar ayuda psicológica o médica (médico de cabecera/psiquiatra) si:", items: ["Sientes una apatía paralizante y una aversión extrema a ir a trabajar todos los días (los 'domingos por la tarde' son de pura angustia)", "Estás usando el alcohol, drogas, comida en exceso o medicamentos para adormecerte y poder sobrellevar el día laboral", "Experimentas síntomas físicos de estrés crónico (dolor de pecho, palpitaciones, caída de cabello, problemas estomacales diarios)", "Sientes que la desesperanza laboral se está filtrando a tu vida personal, haciéndote perder el interés en tu familia, amigos o pasatiempos"] } },
'Esofagitis por reflujo' : { intro: "La esofagitis por reflujo es la inflamación y daño del revestimiento del esófago (el tubo que lleva la comida desde la garganta hasta el estómago), causada por el retorno constante y anormal de los ácidos gástricos.", whatIs: { title: "¿Qué es la Esofagitis por Reflujo?", text: "Es la complicación más frecuente de la Enfermedad por Reflujo Gastroesofágico (ERGE). Cuando la válvula entre el esófago y el estómago se relaja cuando no debe, el ácido estomacal (y a veces la bilis) sube y quema las células del esófago, creando úlceras dolorosas, sangrado y dificultad para tragar." }, types: { title: "Complicaciones y Progresión", intro: "Si la inflamación crónica no se trata o persiste durante años, puede causar graves consecuencias estructurales:", items: ["Estenosis esofágica (formación de tejido cicatricial denso que estrecha el esófago, provocando que la comida se atasque al tragar)", "Úlceras esofágicas (llagas sangrantes y muy dolorosas en la pared interna)", "Esófago de Barrett (condición precancerosa donde las células del esófago mutan para parecerse a las del intestino, en un intento de soportar el ácido)", "Cáncer de esófago (riesgo drásticamente elevado si existe el Esófago de Barrett no tratado)"], note: "" }, diagnosis: { title: "Evaluación Gastroenterológica", intro: "El diagnóstico requiere visualizar el daño directamente:", items: ["Endoscopia superior (EGD) (el examen más importante: el gastroenterólogo introduce una cámara por la garganta para ver la inflamación, tomar biopsias de tejido y clasificar la severidad de la esofagitis según los Grados de Los Ángeles, de la A a la D)", "Radiografía de tránsito esofágico con bario (para detectar estrechamientos o hernias hiatales gigantes)", "Monitoreo del pH esofágico (si el diagnóstico no es claro, para medir exactamente cuánto ácido está subiendo)"], note: "" }, treatment: { title: "Manejo Médico y Curación del Esófago", intro: "El objetivo principal es suprimir la producción de ácido estomacal para darle tiempo al esófago a cicatrizar por completo:", subsections: [ { title: "Opciones de Tratamiento", items: ["Inhibidores de la Bomba de Protones (IBP) (medicamentos como omeprazol, pantoprazol, esomeprazol; son la terapia más fuerte y eficaz para curar el esófago, usualmente requeridos por 8-12 semanas continuas)", "Modificaciones estrictas del estilo de vida (no acostarse hasta 3 horas después de comer, elevar la cabecera de la cama 15 cm, perder peso, y evitar desencadenantes como café, alcohol, chocolate, menta y comidas muy grasosas)", "Cirugía antirreflujo (Funduplicatura de Nissen) en pacientes jóvenes, con hernias grandes o en quienes no toleran la medicación a largo plazo", "Dilatación endoscópica (si el esófago ya se ha estrechado y los alimentos se atascan)"] } ], note: "Suspender los medicamentos IBP bruscamente puede causar un rebote severo de producción de ácido." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias o al especialista?", intro: "El ardor crónico no debe ignorarse. Busca ayuda médica inmediata si experimentas:", items: ["Disfagia (dificultad constante para tragar o la sensación aterradora de que la comida o las pastillas se quedan atascadas detrás del esternón)", "Vómitos que contienen sangre, coágulos oscuros o material similar a posos de café", "Heces de color negro alquitrán o con sangre evidente (signo de sangrado digestivo alto)", "Pérdida de peso involuntaria y dolor en el pecho constante que podría confundirse con un problema cardíaco"] } },
'Sangrado uterino anormal' : { intro: "El sangrado uterino anormal (SUA) es cualquier sangrado desde el útero que no sigue el patrón del ciclo menstrual típico. Puede significar sangrar entre períodos, sangrar después de tener relaciones sexuales, tener manchas, sangrar mucho más de lo habitual o sangrar después de la menopausia.", whatIs: { title: "¿Qué es el SUA?", text: "Es un síntoma común y un término general para alteraciones en el ciclo menstrual de la mujer, ya sea en cantidad, frecuencia, duración o regularidad. Puede deberse a cambios hormonales (sangrado disfuncional) o a problemas físicos y estructurales dentro del sistema reproductor." }, types: { title: "Causas Estructurales y No Estructurales", intro: "Los médicos clasifican las causas utilizando el acrónimo PALM-COEIN:", items: ["PALM (Causas estructurales físicas): Pólipos endometriales, Adenomiosis (endometriosis en el músculo uterino), Leiomiomas (fibromas), y Malignidad (cáncer o precáncer de útero)", "COEIN (Causas no estructurales): Coagulopatías (trastornos de sangrado hereditarios), disfunción Ovulatoria (como en el SOP), problemas Endometriales, Iatrogénicas (causadas por medicamentos como DIUs o anticoagulantes), y causas No clasificadas"], note: "La disfunción ovulatoria es la causa más frecuente de sangrado anormal en la adolescencia y perimenopausia." }, diagnosis: { title: "Evaluación Ginecológica", intro: "El especialista realizará pruebas para descartar cáncer (especialmente en mujeres mayores) y buscar pólipos o problemas hormonales:", items: ["Prueba de embarazo (siempre el primer paso en mujeres en edad reproductiva)", "Ecografía transvaginal o Sonohisterografía (para visualizar detalladamente pólipos, miomas o el grosor del revestimiento uterino)", "Análisis de sangre para chequear anemia (hemograma), pruebas de coagulación, función tiroidea y hormonas", "Biopsia de endometrio (extracción de una pequeña muestra de tejido del útero en el consultorio, mandatoria para mujeres mayores de 45 años o con factores de riesgo para descartar cáncer)", "Histeroscopia (para mirar dentro del útero con una cámara diminuta)"], note: "" }, treatment: { title: "Manejo Médico o Quirúrgico", intro: "El tratamiento depende directamente de la causa subyacente, el deseo de maternidad futura y la edad:", subsections: [ { title: "Opciones de Tratamiento", items: ["Anticonceptivos hormonales (píldoras, anillo, o el DIU hormonal Mirena, excelentes para controlar sangrados abundantes por disfunción ovulatoria o adenomiosis)", "Ácido tranexámico o AINEs (para reducir la cantidad de sangrado abundante sin hormonas)", "Histeroscopia quirúrgica (para extirpar limpiamente pólipos o miomas submucosos que causan el sangrado)", "Ablación endometrial (cirugía para destruir o quemar permanentemente el revestimiento del útero, deteniendo el sangrado pero impidiendo embarazos futuros)", "Histerectomía (cirugía mayor para extirpar el útero, como último recurso o si se descubre cáncer)"] } ], note: "Un tratamiento exitoso mejora dramáticamente los niveles de energía si la paciente estaba anémica por la pérdida de sangre." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia acudir al ginecólogo?", intro: "Debes buscar atención médica rápida o ir a urgencias si:", items: ["Tienes una hemorragia vaginal tan profusa que debes cambiarte de toalla sanitaria o tampón cada hora, durante dos horas seguidas o más, y expulsas coágulos del tamaño de una moneda de 25 centavos", "Experimentas mareos repentinos, aturdimiento, piel pálida, debilidad extrema o desmayo (signos de choque por pérdida de sangre rápida y anemia aguda)", "Sangras estando embarazada o crees que podrías estarlo (riesgo de aborto o embarazo ectópico)", "Presentas cualquier sangrado, incluso una gota o mancha, si ya has pasado por la menopausia (un año completo sin regla), ya que esto es el síntoma principal del cáncer de endometrio"] } },
'Embarazo ectópico' : { intro: "Un embarazo ectópico ocurre cuando un óvulo fecundado se implanta y crece fuera de la cavidad principal del útero. Un embarazo ectópico no puede continuar con normalidad; el óvulo fecundado no puede sobrevivir y el tejido en crecimiento puede destruir varias estructuras maternas y causar un sangrado que pone en riesgo la vida.", whatIs: { title: "¿Qué es un Embarazo Ectópico?", text: "Normalmente, un óvulo fertilizado desciende por las trompas de Falopio hacia el útero. En un embarazo ectópico, el proceso se atasca. Más del 90% de las veces, la implantación anómala se produce en una de las trompas de Falopio (embarazo tubárico). A medida que el embrión crece, la trompa puede estirarse hasta estallar (ruptura)." }, types: { title: "Ubicaciones y Factores de Riesgo", intro: "Aunque la trompa es lo más común, también puede implantarse en:", items: ["El ovario, la cavidad abdominal o la porción inferior del útero (cuello uterino o cérvix)", "Factores de riesgo importantes: Enfermedad inflamatoria pélvica previa, infecciones pasadas por clamidia o gonorrea (que cicatrizan y bloquean la trompa), endometriosis, tabaquismo, o embarazos anteriores ectópicos", "Uso de DIU o ligadura de trompas (aunque previenen muy bien el embarazo general, si falla y hay embarazo, la probabilidad de que sea ectópico es alta)"], note: "" }, diagnosis: { title: "Diagnóstico Temprano", intro: "El diagnóstico de emergencia es crítico para evitar la ruptura de la trompa:", items: ["Análisis de sangre cuantitativo de hCG (Hormona Gonadotropina Coriónica Humana, la hormona del embarazo) seriado: en un embarazo normal, los niveles de hCG se duplican cada pocos días; en uno ectópico, suben muy lentamente o se estancan", "Ecografía transvaginal de alta resolución (para localizar exactamente dónde está el saco gestacional, confirmar que el útero está vacío y ver si hay sangre libre en la pelvis debido a una rotura)", "Examen pélvico físico cuidadoso (buscando sensibilidad o masas dolorosas en las trompas)"], note: "" }, treatment: { title: "Intervención Urgente", intro: "No hay forma de mover o salvar el embarazo; el tratamiento busca salvar la vida y las trompas de la madre:", subsections: [ { title: "Procedimientos", items: ["Tratamiento médico con Metotrexato (una inyección que detiene el crecimiento celular y hace que el cuerpo reabsorba el embarazo de forma segura; solo se puede usar si se detecta muy temprano, el embrión es pequeño y no hay rotura)", "Cirugía laparoscópica mínimamente invasiva (Salpingostomía: se hace un pequeño corte en la trompa y se extrae el tejido ectópico, preservando la trompa si es posible)", "Salpingectomía quirúrgica (extirpación completa de la trompa de Falopio afectada, necesaria si la trompa se ha roto o está gravemente dañada)"] } ], note: "Tener un embarazo ectópico no impide tener embarazos normales en el futuro, pero aumenta el riesgo de que el siguiente también sea ectópico." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia vital?", intro: "Una trompa de Falopio rota es una hemorragia interna letal inminente. Llama a urgencias o ve de inmediato al hospital si sabes que estás embarazada (o podrías estarlo) y sufres:", items: ["Un dolor pélvico, abdominal o en la zona baja de la espalda repentino, punzante, severo y que te incapacita (a menudo en un solo lado)", "Dolor inusual referido en la punta del hombro o el cuello (causado por la sangre interna que irrita el diafragma)", "Sangrado vaginal anormal, a menudo ligero o manchado, diferente a una regla normal", "Mareos severos, aturdimiento profundo, palidez repentina, desmayo (síncope) o debilidad extrema (signos de choque por sangrado interno)"] } },
'Trastorno de adaptación' : { intro: "Un trastorno de adaptación es una reacción emocional y conductual anormal y excesiva a un estrés identificable o un cambio importante en la vida (como un divorcio, desempleo, enfermedad grave o mudanza). La reacción es más fuerte de lo que se esperaría normalmente para el tipo de evento ocurrido.", whatIs: { title: "¿Qué es un Trastorno de Adaptación?", text: "Es una afección psicológica relacionada con el estrés. Mientras que la mayoría de las personas logran adaptarse y hacer frente a los cambios de la vida en unos meses, las personas con este trastorno tienen dificultades extremas para superarlos, provocando respuestas depresivas, ansiosas o problemas de comportamiento que interfieren seriamente con su vida diaria." }, types: { title: "Subtipos Clínicos", intro: "Se clasifican según los síntomas predominantes que exhibe el paciente:", items: ["Con estado de ánimo deprimido (predominan los lloros, la tristeza, la desesperanza y la pérdida de interés en las actividades)", "Con ansiedad (predomina el nerviosismo extremo, la preocupación, la sensación de estar abrumado y el miedo a la separación)", "Mixto con ansiedad y estado de ánimo deprimido", "Con alteración de la conducta (comportamientos de rebeldía, faltar a la escuela o al trabajo, peleas, destrucción de propiedad; más común en adolescentes)", "No especificado (reacciones físicas, aislamiento social)"], note: "Por definición, los síntomas deben comenzar dentro de los 3 meses posteriores a la ocurrencia del evento estresante." }, diagnosis: { title: "Evaluación Psicológica", intro: "Un terapeuta, psicólogo o psiquiatra diagnosticará el trastorno basándose en los criterios del DSM-5:", items: ["Entrevista clínica exhaustiva identificando claramente los factores estresantes desencadenantes recientes en la vida del paciente", "Evaluación de si la angustia es desproporcionada respecto a la gravedad del factor estresante, considerando el contexto cultural", "Verificación de que los síntomas causan un deterioro grave en el funcionamiento social, laboral o escolar", "Descarte de que los síntomas sean simplemente una exacerbación de un trastorno mental preexistente o parte del duelo normal"], note: "Generalmente, una vez que el evento estresante o sus consecuencias terminan, los síntomas del trastorno no deben durar más de 6 meses." }, treatment: { title: "Apoyo y Psicoterapia", intro: "La mayoría de las personas logran recuperarse rápidamente con un tratamiento breve y enfocado:", subsections: [ { title: "Intervenciones", items: ["Psicoterapia a corto plazo (Terapia Cognitivo-Conductual, asesoramiento o terapia de conversación para proporcionar apoyo emocional, comprender la reacción al estrés y aprender habilidades de afrontamiento y resiliencia)", "Terapia familiar o de grupo (especialmente útil para niños o adolescentes lidiando con divorcios de los padres)", "Medicamentos (se usan raramente y solo a corto plazo; el médico puede prescribir antidepresivos o ansiolíticos temporales para aliviar el insomnio severo, la ansiedad extrema o los síntomas depresivos profundos que impiden realizar la psicoterapia)"] } ], note: "Validar las emociones del paciente y enseñarle a manejar el evento es el objetivo, no cambiar el evento en sí, que a menudo es inalterable." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda profesional?", intro: "Es altamente recomendable consultar a un especialista en salud mental si:", items: ["Han pasado meses desde el evento estresante y, en lugar de mejorar, tus síntomas están empeorando, paralizándote y no logras retomar la rutina de tu vida diaria", "Estás recurriendo al abuso de alcohol, drogas o comportamientos imprudentes como mecanismo para escapar del estrés o la realidad", "Tienes pensamientos intrusivos sobre la muerte, autolesiones o ideas suicidas porque sientes que no puedes soportar la nueva situación (urgencia médica)"] } },
'Heridas' : { intro: "Una herida es cualquier lesión que rompe la piel u otros tejidos del cuerpo. Incluyen cortes, raspaduras, rasguños, pinchazos y quemaduras. Mientras que las heridas menores pueden tratarse en casa y sanan rápidamente, las heridas profundas, sucias o infectadas requieren atención médica profesional.", whatIs: { title: "¿Qué son las Heridas?", text: "Es la interrupción de la continuidad y función normal de la barrera cutánea (la piel) o de las membranas mucosas, a menudo causada por un traumatismo físico externo, cirugía o presión prolongada (úlceras). Permiten que bacterias del exterior entren al cuerpo, generando riesgo de infección." }, types: { title: "Clasificación de las Lesiones", intro: "Se clasifican según cómo ocurrieron y su profundidad:", items: ["Laceraciones y cortes (bordes limpios por objetos afilados como cuchillos o vidrios; pueden sangrar mucho si alcanzan vasos)", "Abrasiones o raspaduras (desgaste superficial de las capas superiores de la piel contra una superficie áspera; dolorosas pero poco sangrantes)", "Punciones o perforaciones (agujeros profundos y estrechos causados por clavos, agujas o dientes de animales; tienen un riesgo muy alto de infección por tétanos ya que la herida se cierra rápidamente por arriba atrapando la suciedad)", "Avulsiones (desgarro forzado y brusco donde una porción de piel se arranca parcial o totalmente)", "Úlceras por presión o escaras (heridas crónicas por falta de circulación al estar mucho tiempo en una misma posición)"], note: "" }, diagnosis: { title: "Evaluación de Severidad", intro: "El médico o enfermera evaluará la herida para determinar el tratamiento adecuado:", items: ["Examen físico inspeccionando la profundidad de la herida, buscando daño subyacente en tendones, músculos, nervios, vasos sanguíneos o fracturas óseas", "Evaluación del grado de contaminación, buscando suciedad, tierra, vidrio, astillas o mordeduras", "Revisión del historial de vacunación contra el tétanos del paciente", "Radiografías o ecografías (solo si se sospecha que quedó un cuerpo extraño profundamente incrustado o si hubo un trauma grave por aplastamiento)"], note: "" }, treatment: { title: "Limpieza, Cierre y Prevención", intro: "El objetivo es detener el sangrado, prevenir infecciones y promover una cicatrización estética:", subsections: [ { title: "Manejo Médico y de Primeros Auxilios", items: ["Limpieza y desbridamiento exhaustivo (lavado profuso con suero fisiológico o agua limpia a presión, el paso más importante para evitar infecciones, y recorte de bordes muertos)", "Cierre de la herida (mediante puntos de sutura, grapas quirúrgicas, pegamento tisular (cianoacrilato) o tiras adhesivas Steri-Strips para heridas profundas y abiertas)", "Profilaxis contra el tétanos (inyección de refuerzo si la última fue hace más de 5 a 10 años, especialmente en heridas sucias o profundas)", "Antibióticos orales o tópicos (recetados rutinariamente para mordeduras de animales/humanos, punciones en el pie o si hay signos tempranos de infección)", "Apósitos estériles y curas regulares para mantener un ambiente húmedo óptimo para la cicatrización"] } ], note: "Las heridas por mordeduras o punciones profundas a menudo se dejan abiertas ('cierre por segunda intención') para que drenen y no atrapen la infección dentro." }, whenToSeekHelp: { title: "¿Cuándo es indispensable acudir a Urgencias?", intro: "No intentes tratar la herida en casa y busca atención médica inmediata si:", items: ["El sangrado es abundante, a chorros o no se detiene después de aplicar presión directa y firme durante 10 a 15 minutos continuos", "La herida es muy profunda, tiene bordes muy separados, exponen músculo, grasa amarillenta, tendones o hueso (necesitará sutura en las primeras 6-12 horas)", "La herida fue causada por la mordedura de un animal o humano, o te pinchaste con un clavo sucio y oxidado (riesgo altísimo de infección grave)", "Presenta signos obvios de infección días después: aumento brusco del dolor, enrojecimiento que se expande rápido, calor, gran hinchazón, supuración de pus amarillo/verde, mal olor o fiebre", "Sientes adormecimiento, pérdida de sensibilidad en la extremidad o no puedes mover los dedos normalmente por debajo del corte (posible nervio o tendón seccionado)"] } },
'Codo de tenista' : { intro: "El codo de tenista, conocido médicamente como epicondilitis lateral, es una afección muy dolorosa que ocurre cuando los tendones de la parte externa del codo se sobrecargan. A pesar de su nombre, no solo lo sufren los tenistas; pintores, carpinteros, cocineros o personas que usan mucho el ratón del ordenador son frecuentemente afectados.", whatIs: { title: "¿Qué es el Codo de Tenista?", text: "Es una lesión por sobreesfuerzo repetitivo (tendinopatía). La contracción continua de los músculos del antebrazo que usas para enderezar y levantar la mano y la muñeca genera pequeños desgarros (microtraumatismos) e inflamación en el tendón (especialmente el extensor carpi radialis brevis) justo donde se une a la prominencia ósea en la parte externa del codo (epicóndilo lateral)." }, types: { title: "Condiciones Similares", intro: "Debe diferenciarse de otras patologías del brazo:", items: ["Codo de golfista o Epicondilitis medial (exactamente el mismo mecanismo, pero el dolor y la inflamación ocurren en la parte INTERNA del codo por usar repetidamente los músculos flexores de la muñeca)", "Bursitis del olécranon (hinchazón y líquido en la parte posterior/punta del codo, frecuentemente por apoyarse mucho tiempo sobre él)", "Atrapamiento del nervio radial (el dolor es similar, pero suele acompañarse de debilidad y sensaciones eléctricas más abajo en el brazo)"], note: "El dolor del codo de tenista puede irradiarse desde la parte externa del codo hasta el antebrazo y la muñeca." }, diagnosis: { title: "Evaluación Médica y Física", intro: "El traumatólogo o médico del deporte diagnostica la epicondilitis habitualmente sin necesidad de pruebas complejas:", items: ["Examen físico detallado y palpación directa del epicóndilo lateral para localizar el punto de dolor máximo", "Pruebas de resistencia funcional (como pedirte que intentes enderezar la muñeca o los dedos, o girar el antebrazo, contra una resistencia aplicada por el médico; esto reproducirá el dolor exacto)", "Radiografías simples (para descartar artritis en el codo o trozos de hueso sueltos)", "Ecografía musculoesquelética o Resonancia Magnética (se utilizan solo si el dolor no mejora tras meses de tratamiento para ver el grado de daño o rotura del tendón)"], note: "" }, treatment: { title: "Recuperación y Fisioterapia", intro: "El codo de tenista sana por sí solo con el tiempo, pero los tratamientos aceleran la curación y controlan el dolor severo:", subsections: [ { title: "Enfoque Terapéutico Escalonado", items: ["Reposo relativo inmediato e imperativo (dejar temporalmente la actividad repetitiva específica que causó la lesión, usando el brazo para otras cosas ligeras)", "Fisioterapia (el pilar del éxito: ejercicios específicos para estirar y fortalecer de manera excéntrica los músculos del antebrazo, además de masajes de fricción transversal)", "Uso de un brazalete ortopédico de contra-fuerza o cincha para el codo (colocado justo debajo del codo, presiona el músculo para aliviar la tensión directa sobre el anclaje del tendón dañado)", "Analgésicos y hielo (AINEs como ibuprofeno para el dolor agudo) e infiltraciones locales (inyecciones de corticosteroides, que brindan gran alivio a corto plazo pero pueden debilitar el tendón a la larga, o PRP -Plasma Rico en Plaquetas- para acelerar la curación biológica)", "Cirugía artroscópica o abierta (se considera como último recurso solo si el dolor es incapacitante y no mejora después de 6 a 12 meses de terapia intensiva)"] } ], note: "Retomar la actividad de impacto (como jugar tenis o pintar) sin haber hecho la fisioterapia de fortalecimiento y sin corregir la técnica provocará una recaída casi garantizada." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación por un especialista si:", items: ["El dolor persiste o empeora a pesar de usar los remedios caseros básicos, reposo y evitar la actividad perjudicial durante un par de semanas", "Sientes un dolor agudo tan fuerte que te debilita el agarre y te impide realizar tareas cotidianas simples, como sostener una taza de café, girar el pomo de una puerta, estrechar una mano o usar herramientas ligeras", "El codo o el brazo se ve notablemente inflamado, rojo, se siente caliente al tacto o notas un bulto anormal", "Sientes incapacidad repentina y severa para flexionar o estirar el brazo por completo, o la articulación parece haberse bloqueado"] } },
'Hipertrofia (hiperplasia) prostática benigna' : { intro: "La Hiperplasia Prostática Benigna (HPB), comúnmente llamada agrandamiento de la próstata, es una afección médica sumamente frecuente a medida que los hombres envejecen. La glándula prostática aumenta de tamaño y puede comprimir la uretra, causando síntomas urinarios muy molestos y bloqueando el flujo de orina fuera de la vejiga.", whatIs: { title: "¿Qué es la HPB?", text: "Es un crecimiento no canceroso (benigno) del tejido celular de la próstata, una glándula con forma de nuez que rodea el conducto urinario (uretra) justo debajo de la vejiga en los hombres. A medida que se agranda, presiona y estrangula la uretra como una abrazadera, lo que obliga a la vejiga a trabajar más duro para expulsar la orina, engrosando y debilitando su músculo con el tiempo." }, types: { title: "Aclaraciones Importantes", intro: "Aunque causa mucha preocupación, se debe tener claro lo siguiente:", items: ["NO es cáncer de próstata y no aumenta en absoluto el riesgo de desarrollarlo en el futuro", "El tamaño de la próstata no siempre determina la gravedad de los síntomas; algunos hombres con próstatas ligeramente agrandadas tienen bloqueos severos, mientras que otros con próstatas muy grandes sufren pocos síntomas urinarios", "Es casi inevitable: afecta a aproximadamente el 50% de los hombres mayores de 50 años, y hasta al 90% de los mayores de 80 años"], note: "Las complicaciones crónicas de ignorarla incluyen infecciones de orina recurrentes, formación de cálculos en la vejiga y daño renal permanente por reflujo de la orina." }, diagnosis: { title: "Evaluación Urológica", intro: "El urólogo determinará la severidad del bloqueo y descartará el cáncer de próstata mediante:", items: ["Evaluación de síntomas (Cuestionario IPSS) y tacto rectal digital (para estimar el tamaño de la glándula y detectar nódulos duros sospechosos de cáncer)", "Análisis de sangre del Antígeno Prostático Específico (PSA) (suele estar algo elevado en la HPB, pero niveles muy altos requieren descartar cáncer)", "Flujometría (mide la fuerza y velocidad del chorro de orina) y medición de orina residual posmiccional mediante ecografía (para ver cuánta orina se queda atrapada en la vejiga tras intentar vaciarla)", "Cistoscopia (uso de una pequeña cámara flexible a través de la uretra para ver el bloqueo desde adentro) o Ecografía transrectal"], note: "" }, treatment: { title: "Medicación y Cirugías Desobstructivas", intro: "Existen múltiples tratamientos muy eficaces; la elección depende del tamaño de la próstata y las molestias:", subsections: [ { title: "Opciones de Tratamiento", items: ["Espera en observación (para hombres con síntomas leves que no molestan mucho, haciendo controles anuales y evitando beber líquidos tarde en la noche o abusar de cafeína)", "Medicamentos orales relajantes: Alfabloqueantes (Tamsulosina, Terazosina) que actúan rápidamente relajando el músculo liso del cuello de la vejiga y la próstata para dejar fluir la orina", "Medicamentos para reducir el tamaño: Inhibidores de la 5-alfa reductasa (Finasterida, Dutasterida) que bloquean los cambios hormonales que hacen crecer la próstata y logran encogerla tras varios meses de uso", "Terapia mínimamente invasiva (Láser verde, terapia con vapor de agua Rezūm, implantes UroLift) que evaporan, queman o comprimen el tejido prostático que obstruye la uretra con mínimos efectos secundarios sexuales", "Cirugía RTUP (Resección Transuretral de la Próstata, el estándar de oro quirúrgico clásico donde el urólogo raspa y recorta el interior de la próstata mediante un instrumento insertado por la uretra)"] } ], note: "Varios medicamentos para el resfriado de venta libre que contienen descongestionantes (como pseudoefedrina) pueden contraer los músculos de la próstata y causar de repente que un hombre con HPB no pueda orinar en absoluto." }, whenToSeekHelp: { title: "¿Cuándo es urgente contactar al médico?", intro: "Acude a emergencias o al urólogo de manera inmediata si te enfrentas a una 'Retención Urinaria Aguda' o complicaciones graves, tales como:", items: ["Incapacidad total, repentina e imperiosa de poder orinar (no sale ni una gota), a menudo acompañada de dolor muy agudo y extrema tensión en la parte inferior del abdomen (la vejiga a punto de estallar)", "Necesidad de levantarte al baño múltiples veces por la noche (nicturia severa) que te impide dormir, urgencia repentina y fuerte de orinar que no puedes contener (incontinencia), o sientes que la vejiga nunca se vacía", "Un chorro de orina inusualmente débil, que gotea al final o que se detiene y comienza varias veces durante la micción", "Notas sangre visible y recurrente en tu orina (hematuria) o tienes fiebre y escalofríos intensos junto con ardor al orinar (infección)"] } },
'Conjuntivitis alérgica' : { intro: "La conjuntivitis alérgica es la inflamación de la capa transparente (conjuntiva) que recubre el interior de los párpados y la parte blanca del globo ocular, producida como una respuesta inmunitaria exagerada frente a sustancias inofensivas como el polen, el polvo o el pelo de las mascotas.", whatIs: { title: "¿Qué es la Conjuntivitis Alérgica?", text: "Es una reacción ocular molesta pero no contagiosa. Cuando tus ojos están expuestos a un alérgeno, el cuerpo libera histamina de los mastocitos, lo que hace que los diminutos vasos sanguíneos de la conjuntiva se hinchen y filtren líquido, provocando ojos extremadamente rojos, llorosos y una picazón intensa." }, types: { title: "Tipos Comunes", intro: "Se divide principalmente por su temporalidad y el desencadenante:", items: ["Conjuntivitis alérgica estacional (es la más frecuente, muy relacionada con la fiebre del heno, causada por altos niveles de esporas de moho o polen de árboles y pastos en primavera y verano)", "Conjuntivitis alérgica perenne (ocurre durante todo el año; los síntomas suelen ser más leves pero crónicos y son provocados por alergias a los ácaros del polvo, plumas o caspa de animales de interior)", "Queratoconjuntivitis vernal o atópica (una forma mucho más severa y crónica de alergia ocular que puede dañar la córnea y la visión de forma permanente si no se trata a fondo, más común en varones jóvenes con eccema o asma)", "Conjuntivitis papilar gigante (relacionada frecuentemente con el uso continuo de lentes de contacto o sensibilidad a las soluciones de limpieza, provocando la formación de bultos bajo el párpado superior)"], note: "A diferencia de las conjuntivitis bacterianas o virales, la alérgica casi SIEMPRE afecta a ambos ojos al mismo tiempo." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El oftalmólogo o alergólogo la identifica rápidamente sin pruebas complejas:", items: ["Examen oftalmológico utilizando una lámpara de hendidura (para ver los párpados hinchados por dentro y descartar infecciones)", "Revisión clínica enfocada en el síntoma clave: la picazón abrumadora y ardiente (el sello distintivo de la alergia), acompañada de secreción transparente y acuosa (no amarilla ni verde como en infecciones)", "Rara vez se necesitan pruebas cutáneas o de sangre para alergias específicas, a menos que no se logre controlar el problema y se necesite identificar al culpable exacto"], note: "" }, treatment: { title: "Alivio y Prevención", intro: "El enfoque es evitar el contacto con el alérgeno y utilizar gotas para bloquear la reacción de la histamina:", subsections: [ { title: "Opciones de Tratamiento", items: ["El primer paso crucial es evitar el frotamiento compulsivo de los ojos, ya que frotarlos empeora mecánicamente la liberación de histamina y empeora drásticamente la inflamación", "Uso abundante de lágrimas artificiales frías sin conservantes (para lavar físicamente el alérgeno y el polen de la superficie del ojo, y calmar el ardor)", "Gotas oftalmológicas antihistamínicas y estabilizadoras de mastocitos de venta libre o recetadas (como la olopatadina, muy eficaces para detener la picazón en minutos)", "Antihistamínicos orales (ayudan si también tienes alergia nasal, pero pueden secar los ojos y empeorar paradójicamente los síntomas oculares si no se combinan con gotas)", "Corticosteroides en gotas oculares (indicados exclusivamente por el oftalmólogo para casos de inflamación severa e incapacitante a corto plazo, ya que su uso prolongado puede causar glaucoma o cataratas)"] } ], note: "Retirar los lentes de contacto temporalmente y usar gafas ayuda a proteger el ojo como barrera contra el polen." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico de los ojos?", intro: "Acude a un oftalmólogo o emergencias para descartar un problema más grave que una alergia si experimentas:", items: ["Dolor severo, constante y agudo dentro del ojo, o tienes la clara sensación de que hay un objeto extraño o arenilla gruesa raspando que no logras sacar", "Experimentas una gran sensibilidad dolorosa y extrema a la luz normal (fotofobia)", "Los ojos tienen una secreción gruesa, amarilla, blanca o verdosa espesa que hace que los párpados amanezcan fuertemente pegados o costrosos por las mañanas (signo típico de infección bacteriana)", "Notas que tu visión se ha vuelto claramente borrosa o ha disminuido y no mejora al parpadear o usar lágrimas, o los síntomas no responden a las gotas antialérgicas tras un par de días"] } },
'Desgaste de cadera' : { intro: "El desgaste de cadera, conocido médicamente como artrosis u osteoartritis de cadera, es una enfermedad degenerativa de las articulaciones. Ocurre cuando el cartílago que amortigua los huesos de la cadera se desgasta gradualmente, causando fricción dolorosa de hueso contra hueso y pérdida de la movilidad de la pierna.", whatIs: { title: "¿Qué es la Artrosis de Cadera?", text: "Es una afección progresiva donde el suave cartílago articular (que actúa como un cojinete lubricado en la articulación esférica de la cadera, donde el fémur encaja en la pelvis) se vuelve áspero, delgado y eventualmente desaparece. El cuerpo intenta reparar el daño creando crecimientos óseos irregulares (osteofitos o espolones), lo que empeora la rigidez articular." }, types: { title: "Factores de Riesgo y Origen", intro: "Se desarrolla lentamente a lo largo de muchos años por varios motivos:", items: ["Osteoartritis primaria (el desgaste 'natural' por la edad y el uso; el factor de riesgo más importante es tener más de 50 años)", "Osteoartritis secundaria (desgaste acelerado originado por problemas previos, como sobrepeso severo, displasia de cadera congénita en la infancia, pinzamiento femoroacetabular, fracturas de cadera pasadas o inflamación como en la artritis reumatoide)"], note: "El dolor de cadera debido a la artrosis curiosamente se siente muy a menudo en la zona de la ingle, en el muslo interno o incluso en la rodilla, y rara vez en la parte exterior del glúteo." }, diagnosis: { title: "Diagnóstico Médico", intro: "El traumatólogo ortopédico diagnosticará la extensión del daño mediante:", items: ["Exploración física detallada, evaluando tu forma de caminar (cojera), buscando dolor específico al rotar o flexionar la cadera y detectando crujidos articulares (crepitación)", "Radiografías de pelvis (la prueba estándar e insustituible para visualizar la reducción o pérdida total del 'espacio' articular entre los huesos de la cadera y la presencia de quistes óseos o espolones)", "En raras ocasiones, Resonancia Magnética (RM) (solo si la radiografía no es concluyente y se sospechan desgarros de tendones o del labrum, o problemas en los tejidos blandos)"], note: "" }, treatment: { title: "Manejo y Reemplazo Articular", intro: "No existe cura para el daño, pero hay múltiples opciones excelentes para el manejo del dolor y la recuperación funcional profunda:", subsections: [ { title: "Enfoque Terapéutico Escalonado", items: ["Modificación de actividades (evitar correr o saltar, optar por natación y ciclismo estático) y pérdida de peso obligatoria para restar estrés mecánico a la articulación", "Uso de un bastón en la mano opuesta a la cadera dolorida (ayuda enormemente a disminuir la presión articular al caminar)", "Fisioterapia para fortalecer los músculos abductores y mejorar el rango de movimiento", "Medicamentos y terapias inyectables (AINEs, y ocasionalmente infiltraciones directas de corticosteroides en la articulación guiadas por ecografía para un alivio severo a corto plazo)", "Cirugía de Reemplazo Total de Cadera o Artroplastia (una de las cirugías más exitosas de la medicina moderna; se sustituye la articulación desgastada por componentes de metal, plástico y cerámica, eliminando casi totalmente el dolor y restaurando el movimiento; recomendada cuando la artrosis es severa e incapacitante)"] } ], note: "Esperar demasiado tiempo para realizar la cirugía de reemplazo si el dolor es extremo puede atrofiar los músculos, dificultando y prolongando la rehabilitación posoperatoria." }, whenToSeekHelp: { title: "¿Cuándo buscar al especialista ortopédico?", intro: "Es fundamental programar una evaluación quirúrgica o médica si experimentas:", items: ["Dolor articular constante en la ingle, muslo o nalgas que te despierta frecuentemente durante la noche o aparece incluso mientras estás acostado descansando", "Rigidez muy notoria en la cadera por las mañanas al levantarte de la cama o después de estar sentado en un coche/silla un rato, lo que te obliga a cojear", "Un dolor o pérdida de rango de movimiento tan limitante que te impide doblarte cómodamente para ponerte los calcetines, atarte los zapatos o cortarte las uñas de los pies", "El dolor interfiere gravemente con tu calidad de vida diaria y los analgésicos convencionales de venta libre o los ejercicios ya no proporcionan alivio significativo"] } },
'Coronavirus COVID-19' : { intro: "El COVID-19 (enfermedad por coronavirus 2019) es una enfermedad infecciosa aguda y altamente contagiosa que afecta principalmente al sistema respiratorio humano. Causó una pandemia global sin precedentes y puede variar desde una infección sin síntomas hasta una insuficiencia respiratoria severa y letal.", whatIs: { title: "¿Qué es el COVID-19?", text: "Es la enfermedad clínica originada por la infección del virus SARS-CoV-2. El virus penetra en las células, especialmente en las vías respiratorias y pulmones, utilizándolas para multiplicarse. La reacción inmunológica inflamatoria masiva del cuerpo para combatir al virus es a menudo la responsable del daño profundo a los pulmones, provocando neumonía, problemas cardiovasculares y coágulos de sangre." }, types: { title: "Espectro Clínico y Secuelas", intro: "La presentación de la enfermedad es extremadamente variada:", items: ["Enfermedad leve o asintomática (la mayoría de los casos, síntomas similares a un fuerte resfriado o gripe común, fiebre, tos seca, dolor de garganta y la característica pérdida abrupta de olfato y gusto)", "Enfermedad severa (progresión hacia la neumonía y dificultad severa para respirar, con caída dramática de los niveles de oxígeno, requiriendo internamiento hospitalario)", "COVID Prolongado o 'Long COVID' (una condición debilitante donde síntomas como fatiga extrema inhabilitante, niebla mental (brain fog), palpitaciones y falta de aire persisten durante muchos meses o años después de que la infección viral activa haya desaparecido)"], note: "El virus se transmite principalmente por las minúsculas gotitas respiratorias y aerosoles que una persona infectada expulsa al hablar, toser, estornudar o respirar de cerca." }, diagnosis: { title: "Pruebas Virales y Detección", intro: "El diagnóstico de confirmación sigue siendo mediante laboratorio:", items: ["Prueba PCR o reacción en cadena de la polimerasa (el estándar de oro, detecta y amplifica material genético del virus a partir de un hisopado nasal profundo o faríngeo, es muy sensible y exacta)", "Pruebas de antígenos o test rápidos caseros (detectan ciertas proteínas del virus mediante un hisopo nasal, dan resultados en 15 minutos; menos sensibles que la PCR, pueden dar falsos negativos al inicio de la infección)", "Oximetría de pulso casera (usar un pequeño aparato en el dedo para monitorear vitalmente que la saturación de oxígeno en la sangre no baje a niveles peligrosos de forma silenciosa)", "Tomografía de tórax (usada en el hospital para evaluar el grado de neumonía y los típicos patrones pulmonares de 'vidrio esmerilado')"], note: "" }, treatment: { title: "Manejo, Prevención y Medicación", intro: "La base de contención son las vacunas, pero existen tratamientos para la infección activa:", subsections: [ { title: "Intervenciones y Protocolos", items: ["Vacunación preventiva y refuerzos (la medida más importante para prevenir la hospitalización, el COVID severo y la muerte, reduciendo también el riesgo de COVID Prolongado)", "Manejo sintomático en casa para casos leves (reposo exhaustivo, hidratación abundante, paracetamol o ibuprofeno para la fiebre y los dolores)", "Antivirales orales específicos (como Paxlovid (nirmatrelvir/ritonavir) o Molnupiravir, recetados obligatoriamente en los primeros 5 días del inicio de los síntomas para pacientes con factores de riesgo de enfermedad grave)", "Tratamiento hospitalario en UCI para cuadros graves (uso de oxígeno suplementario, ventilación mecánica, corticosteroides fuertes como la dexametasona para frenar la inflamación destructiva de los pulmones, y medicamentos anticoagulantes para evitar trombos masivos)"] } ], note: "Los antibióticos NO matan los virus, por lo que no sirven y no se recetan para tratar directamente el COVID-19, a menos que haya una sobreinfección bacteriana secundaria." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias de inmediato?", intro: "El deterioro pulmonar en el COVID puede ser precipitado y engañoso (hipoxia feliz). Llama a los servicios de emergencia (911) sin esperar si tú o el enfermo presentan signos de advertencia de fallo respiratorio:", items: ["Dificultad genuina o problema agudo para respirar al realizar mínimos esfuerzos (o si en el oxímetro casero el nivel de oxígeno marca consistentemente por debajo de 92-90%)", "Dolor constante, pesadez o una presión fuerte e inamovible persistente en el pecho", "Aparición de un estado de confusión mental nueva, gran incapacidad para despertar o mantenerse despierto (letargo profundo)", "Piel, labios o lechos de las uñas de las manos que se vuelven notablemente pálidos, grises o con un tono azulado (cianosis)"] } },
'Urticaria' : { intro: "La urticaria es un brote de ronchas rojas, pálidas o del color de la piel que aparecen de manera repentina en la superficie de la dermis. Se caracterizan por provocar una intensa y desesperante picazón y pueden estar desencadenadas por una reacción alérgica grave o ser totalmente inexplicables.", whatIs: { title: "¿Qué es la Urticaria?", text: "Es una reacción inflamatoria de la piel. Cuando el cuerpo libera histamina en respuesta a un factor desencadenante (como un alérgeno o estrés), el plasma sanguíneo se filtra de los pequeños vasos bajo la piel y se acumula en el tejido. Esto causa hinchazón, enrojecimiento y elevaciones (habones o ronchas) que pican, cambian de tamaño y forma rápidamente, y suelen desaparecer sin dejar rastro en menos de 24 horas, apareciendo otras nuevas." }, types: { title: "Agudeza y Causas", intro: "Se divide médicamente según el tiempo que duran los brotes:", items: ["Urticaria aguda (es la más común, dura menos de seis semanas; típicamente causada por infecciones virales en niños, alergias a alimentos, picaduras de insectos o reacción a medicamentos como la penicilina y analgésicos)", "Urticaria crónica o espontánea (aparece casi a diario y persiste durante más de seis semanas; a menudo la causa es autoinmune y frustrantemente nunca llega a identificarse un desencadenante claro)", "Urticaria física (desencadenada directamente por estímulos físicos externos y predecibles sobre la piel, como la presión de la ropa apretada, el roce, el frío intenso, el calor, el sudor del ejercicio o la luz solar)"], note: "Aproximadamente una quinta parte de las personas experimentarán urticaria aguda en algún momento de su vida." }, diagnosis: { title: "Detección y Evaluación", intro: "El dermatólogo o alergólogo enfoca el diagnóstico en encontrar la raíz (si es posible):", items: ["Examen físico y revisión visual del historial de las ronchas (las ronchas típicas de urticaria palidecen -se vuelven blancas- cuando se presionan, a diferencia de otras erupciones)", "Registro exhaustivo e interrogatorio sobre la dieta reciente, nuevos medicamentos, infecciones o estrés emocional antes del brote", "Pruebas de alergia cutánea o análisis de sangre, generalmente útiles y justificadas solo para las urticarias agudas donde se sospecha un alérgeno específico", "En la urticaria crónica, no suelen pedirse muchas pruebas exhaustivas a menos que se sospeche una enfermedad tiroidea subyacente autoinmune"], note: "" }, treatment: { title: "Tratamiento Antihistamínico y Alivio", intro: "La meta es detener la picazón enloquecedora e inhibir la liberación de histamina en la piel:", subsections: [ { title: "Abordajes Médicos", items: ["Antihistamínicos orales no sedantes de segunda generación diarios (como cetirizina, fexofenadina o loratadina, que son el tratamiento base absoluto y seguro para bloquear el síntoma; a veces el médico indica dosis muy superiores a las habituales del prospecto)", "Corticoesteroides orales (como la prednisona, recetados en un ciclo corto de pocos días solo para brotes muy graves y resistentes que no ceden con antihistamínicos)", "Terapias biológicas o anticuerpos monoclonales (como Omalizumab, administrado mensualmente por inyección a pacientes con urticaria crónica que no han respondido a dosis máximas de antihistamínicos)", "Remedios caseros calmantes (baños fríos, aplicación constante de compresas húmedas frías y lociones de calamina)"] } ], note: "Las cremas antihistamínicas o de cortisona tópicas no suelen ser efectivas y generalmente no se recomiendan para tratar urticarias diseminadas por el cuerpo." }, whenToSeekHelp: { title: "¿Cuándo es una alerta de anafilaxia o emergencia médica?", intro: "La urticaria en la piel puede ser un síntoma temprano de anafilaxia, una reacción alérgica sistémica que amenaza la vida y requiere epinefrina urgente. Ve a emergencias o llama al 911 si las ronchas se acompañan de:", items: ["Hinchazón brusca y desproporcionada (angioedema) en los labios, el interior de la boca, los ojos o un engrosamiento progresivo en la garganta", "Dificultad significativa para tragar, para respirar o sientes sibilancias audibles en el pecho", "Sensación repentina de debilidad extrema, mareo inminente, caída de presión y desmayo", "Mareos severos o sensación de confusión extrema, acompañado de pulso muy rápido"] } },
'Coledocolitiasis' : { intro: "La coledocolitiasis es una afección del sistema biliar en la que uno o más cálculos biliares (piedras formadas comúnmente en la vesícula) salen de esta y se atascan en el conducto biliar común o colédoco, el conducto principal que transporta la bilis desde el hígado y la vesícula hacia el intestino delgado.", whatIs: { title: "¿Qué es la Coledocolitiasis?", text: "Es la obstrucción dolorosa y potencialmente grave del flujo biliar. A diferencia de las piedras que se quedan silenciosas dentro de la vesícula (colelitiasis), si una piedra bloquea el conducto colédoco, la bilis tóxica y las enzimas se acumulan y retroceden rápidamente hacia el hígado, lo que puede causar daño hepático y fuertes infecciones en horas." }, types: { title: "Riesgos y Complicaciones Graves", intro: "Una piedra bloqueando este conducto maestro no se disolverá y precipita problemas médicos urgentes:", items: ["Ictericia obstructiva (la bilis retenida inunda la sangre y vuelve la piel, orina y ojos color amarillo intenso)", "Colangitis aguda (la bilis estancada detrás del cálculo se infecta severamente por bacterias intestinales, causando una infección sistémica de las vías biliares que amenaza la vida en cuestión de horas)", "Pancreatitis aguda biliar (si la piedra se atasca en el punto final del conducto, en la ampolla de Vater, donde también drena el páncreas, las enzimas digestivas retroceden al páncreas, causando una inflamación pancreática crítica y dolorosa)"], note: "Suele afectar con frecuencia a personas con antecedentes conocidos de problemas de cálculos en la vesícula." }, diagnosis: { title: "Confirmación y Estudios de Imagen", intro: "Para localizar el bloqueo exacto en el conducto, los gastroenterólogos usan:", items: ["Análisis de sangre urgentes, evaluando las pruebas de función hepática (niveles muy altos de bilirrubina directa, fosfatasa alcalina y GGT, además de signos de infección por leucocitos elevados)", "Ecografía abdominal (el examen más rápido, que muestra un conducto biliar principal anormalmente dilatado y ancho debido a la presión, aunque la piedra a veces se oculta)", "Colangiopancreatografía por resonancia magnética (CPRM) (el escáner no invasivo más preciso y definitivo para ver claramente los conductos biliares y las piedras retenidas en su interior)", "Ultrasonido endoscópico (EUS) (una pequeña sonda de ultrasonido pasada por la boca hasta el estómago para ver las piedras muy pequeñas que escapan a la resonancia)"], note: "" }, treatment: { title: "Extracción Endoscópica y Cirugía", intro: "Una piedra en el colédoco no desaparecerá sola y el tratamiento es quirúrgicamente resolutivo:", subsections: [ { title: "Procedimientos Desobstructivos", items: ["CPRE (Colangiopancreatografía retrógrada endoscópica): El procedimiento estándar y curativo. Se introduce un endoscopio flexible por la garganta hasta el intestino para llegar al conducto biliar; allí, el médico hace un pequeño corte, atrapa las piedras con una canasta o globo miniatura y las extrae, solucionando el bloqueo instantáneamente.", "Colecistectomía laparoscópica: Después de extraer la piedra del conducto, es casi siempre obligatorio programar la cirugía de extirpación de la vesícula biliar (generalmente en los siguientes días). Si no se quita la vesícula enferma, es casi seguro que soltará nuevas piedras al conducto, repitiendo el cuadro.", "Colocación de un stent biliar temporal (si el cálculo es inusualmente grande y no puede extraerse de inmediato en la CPRE, se inserta un tubo de drenaje para asegurar que la bilis y el pus de la infección puedan fluir)"] } ], note: "Se administran agresivamente antibióticos intravenosos al primer signo de infección y fiebre (colangitis)." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia vital ir al hospital?", intro: "Una piedra obstruyendo la vía biliar es una emergencia médica que no se trata con calmantes. Ve a Urgencias de inmediato si presentas:", items: ["Dolor extremadamente severo, intermitente o constante en la parte superior derecha y central del abdomen que te paraliza y no mejora con analgésicos comunes", "Ictericia aguda repentina: tu piel adquiere un tinte claramente amarillo y la parte blanca de los ojos se tiñe de amarillo fuerte, tu orina se vuelve oscura como el té y las heces son blancas o de color masilla", "Presentas la 'Tríada de Charcot': Fiebre alta repentina, dolores de estómago y color amarillo de piel simultáneos (una señal definitoria de una colangitis aguda mortal si no se trata)", "Náuseas incontrolables con vómitos constantes que acompañan al dolor"] } },
'Dermatitis alérgica' : { intro: "La dermatitis de contacto alérgica es una afección inflamatoria de la piel con picazón y enrojecimiento que se desencadena cuando la piel entra en contacto directo y repetido con una sustancia inofensiva para la mayoría, pero a la cual el sistema inmunológico del paciente se ha vuelto muy sensible y alérgico.", whatIs: { title: "¿Qué es la Dermatitis Alérgica de Contacto?", text: "Es una reacción inmunitaria de tipo retardado (tipo IV) de la piel. A diferencia de un sarpullido inmediato, la erupción no ocurre la primera vez que tocas el alérgeno. Tras años de exposición a una sustancia (ej. el níquel de un reloj), el cuerpo de repente se sensibiliza y desarrolla una reacción celular inflamatoria, y la erupción puede tardar de 48 a 72 horas en aparecer tras el contacto directo con el desencadenante." }, types: { title: "Culpables y Desencadenantes Frecuentes", intro: "Existen miles de alérgenos que pueden causar esta dermatitis específica:", items: ["Metales (el níquel es el alérgeno de contacto más común en el mundo, presente en joyería barata, botones de pantalones, hebillas de cinturones, monturas de gafas)", "Plantas y aceites irritantes (hiedra venenosa, roble venenoso, zumaque)", "Conservantes, ingredientes y fragancias de productos cosméticos de uso diario (cremas faciales, esmaltes de uñas, desodorantes, champús o tintes para el cabello)", "Productos químicos ocupacionales, pegamentos o tintes oscuros de ropa y tintes de cuero", "Ciertas pomadas médicas o antibióticas aplicadas en la piel (sorprendentemente, a menudo desarrollan alergias al bálsamo de neomicina usado en heridas)"], note: "El sarpullido se limita exclusivamente a la zona exacta de la piel que tocó la sustancia, formando a menudo líneas o figuras geométricas distintivas." }, diagnosis: { title: "Evaluación Dermatológica y Pruebas", intro: "El dermatólogo intentará identificar al 'culpable' misterioso:", items: ["Examen físico minucioso de la erupción, prestando especial atención a la ubicación inusual del sarpullido (ej. debajo del anillo, en el lóbulo de la oreja o exactamente en la línea de la cintura)", "Prueba del parche (Patch test): Es la herramienta diagnóstica definitiva. El médico aplica pequeños parches adhesivos empapados con los químicos alérgenos más comunes en la espalda del paciente y se dejan durante 48 horas. Si se desarrolla una roncha o inflamación bajo uno de ellos, se confirma al agresor definitivo"], note: "Las pruebas de parche son completamente diferentes a las pruebas de punción rápida usadas para alergias alimentarias o al polen." }, treatment: { title: "Cura, Manejo y Curación de la Piel", intro: "La solución principal es cortar de raíz el contacto; luego tratar la piel dañada:", subsections: [ { title: "Enfoques Terapéuticos", items: ["Identificación y evitación estricta del alérgeno agresor, retirándolo de tu rutina o utilizando barreras para tocarlo (guantes, forros para la ropa). Esta es la única cura real para evitar que regrese", "Cremas de corticosteroides tópicos recetados (potentes desinflamatorios que detienen la erupción celular, curan la picazón rápidamente y aplanan la piel áspera)", "Corticosteroides orales (ciclos cortos de prednisona oral de una o dos semanas si el sarpullido es extremadamente extenso o si involucra la cara hinchada y los genitales, como ocurre a veces con la hiedra venenosa severa)", "Compresas frías, húmedas y baños de avena caseros para calmar la picazón incontrolable y secar las lesiones que supuran agua"] } ], note: "Incluso con tratamiento, las ampollas o sarpullidos severos pueden tardar de 2 a 4 semanas en sanar por completo y secarse." }, whenToSeekHelp: { title: "¿Cuándo debes acudir a consulta médica?", intro: "Solicita ayuda a un dermatólogo o médico general si la dermatitis de contacto presenta:", items: ["Una erupción tan roja e incómoda que te roba el sueño, o afecta el funcionamiento diario y la picazón es insoportable a pesar de las cremas de farmacia", "El sarpullido aparece de repente y cubre áreas extensas del rostro (hinchazón de ojos) o los genitales", "Se observan signos evidentes de una infección bacteriana secundaria debido al rascado incesante continuo (el sarpullido comienza a desarrollar costras grandes de color amarillo miel, supura pus o las estrías de la piel se vuelven calientes y muy dolorosas al roce)", "El brote de piel inflamada no muestra mejoría tras dos a tres semanas de tratamiento casero de evitación y cremas sin receta"] } },
'Queratocono' : { intro: "El queratocono es un trastorno progresivo y degenerativo del ojo en el cual la córnea, la capa delantera transparente y en forma de cúpula del ojo que enfoca la luz, se debilita estructuralmente. Se adelgaza de manera progresiva y comienza a abultarse hacia afuera, adoptando una forma puntiaguda y de cono, distorsionando drásticamente la visión.", whatIs: { title: "¿Qué es el Queratocono?", text: "Es una enfermedad ectásica de la córnea que se presenta generalmente en la pubertad. A medida que las fibras de colágeno dentro de la córnea se debilitan por la fricción o la genética y no pueden mantener su forma esférica regular, el ojo se deforma como un pequeño balón de fútbol bajo presión, provocando altos niveles de astigmatismo irregular y miopía progresiva." }, types: { title: "Factores de Riesgo y Progresión", intro: "Ciertas actividades de alto impacto lo agravan notablemente:", items: ["Frotarse fuertemente los ojos crónica y vigorosamente (el principal factor ambiental conocido que debilita mecánicamente la córnea y precipita la enfermedad, especialmente en pacientes que tienen alergias severas oculares asociadas)", "Componente genético y afecciones de tejido conectivo, o síndrome de Down", "Alergias crónicas o asma"], note: "Suele iniciarse en la adolescencia y continuar empeorando progresivamente hasta que se estabiliza de forma natural alrededor de los 30 a 40 años de edad." }, diagnosis: { title: "Exámenes Oftalmológicos y Topografía", intro: "A menudo se sospecha cuando un paciente joven no puede corregir su visión con gafas, requiriendo estudios avanzados:", items: ["Topografía corneal (la herramienta más precisa y crucial que traza un mapa 3D computarizado de alta resolución de la curvatura y las áreas de la superficie del ojo, capaz de detectar formas sutiles de queratocono muy precoces de forma segura)", "Paquimetría (medición precisa con un haz de luz o ecografía del espesor o adelgazamiento del tejido corneal en su punto central más delgado)", "Examen meticuloso con lámpara de hendidura por parte del oftalmólogo (buscando signos tardíos como estrías finas verticales dentro del tejido de la córnea, el anillo de Fleischer, o cicatrices por adelgazamiento)"], note: "En sus primeras etapas puede confundirse rutinariamente con un astigmatismo elevado pero normal." }, treatment: { title: "Estabilización y Opciones Visuales", intro: "El tratamiento es escalonado: primero estabilizar que no empeore, y segundo, corregir la visión defectuosa:", subsections: [ { title: "Terapias Correctivas y Quirúrgicas", items: ["Evitar absolutamente frotarse los ojos nunca más (controlando agresivamente las alergias con gotas para detener el ciclo de picor)", "Lentes de contacto rígidos permeables al gas (RGP) o lentes esclerales especiales: la solución estándar de oro. Estos lentes duros se apoyan sobre la parte blanca del ojo creando una nueva superficie ópticamente perfecta frente al cono, restableciendo la visión de forma casi mágica", "Cross-Linking (Reticulación) corneal (el tratamiento más importante: uso de gotas de vitamina B1 o riboflavina más luz UV aplicados sobre el ojo durante una hora para fortalecer y endurecer las fibras de colágeno debilitadas, frenando definitivamente la progresión y abultamiento cónico de la enfermedad)", "Implantes de anillos intracorneales (segmentos de plásticos en forma de luna insertados quirúrgicamente en la córnea para aplanarla y devolverle su forma de cúpula circular)", "Trasplante de córnea / Queratoplastia penetrante (el recurso final, únicamente necesario en casos muy avanzados donde el adelgazamiento extremo crea una gran cicatriz corneal y nubla la vista central que ni los lentes ayudan)"] } ], note: "Ningún paciente con sospecha o historial de queratocono es apto jamás para recibir cirugías refractivas populares para dejar de usar gafas como LASIK o PRK, ya que cortarían y destruirían el tejido frágil." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar al especialista de la visión?", intro: "Es altamente recomendable acudir a un oftalmólogo con experiencia en córneas si tú o tu hijo adolescente presentan:", items: ["Empeoramiento rápido, inestable e inexplicado de la miopía o astigmatismo, donde la prescripción de los anteojos en la óptica cambia bruscamente cada vez que acudes y no logran conseguir una visión clara total", "Deslumbramiento excesivo, fuertes luces difuminadas o percepción de 'halos o estelas fantasma' molestos alrededor de las luces, especialmente marcados al conducir de noche", "Visión doble o ver múltiples imágenes distorsionadas usando un solo ojo", "Aparición y sensación repentina de niebla y dolor ocular (edema agudo) debido a una ruptura brusca interna (hidrops) que inunda la córnea"] } },
'Preeclampsia' : { intro: "La preeclampsia es una complicación potencialmente mortal del embarazo que se desarrolla típicamente después de la semana 20 de gestación en mujeres que previamente tenían la presión arterial normal. Se caracteriza por un rápido aumento de la presión arterial y signos de daño en otros órganos, más frecuentemente en los riñones y en el hígado.", whatIs: { title: "¿Qué es la Preeclampsia?", text: "Es un síndrome vascular originado en la placenta. Los vasos sanguíneos placentarios no se desarrollan con normalidad en los primeros meses de gestación, lo cual restringe el flujo sanguíneo y la oxigenación adecuada. La placenta alterada responde enviando moléculas tóxicas al cuerpo de la madre, provocando una disfunción severa que estrecha los vasos y daña múltiples órganos maternos y afecta el crecimiento del bebé." }, types: { title: "Gravedad, Evolución y Riesgos", intro: "Su progresión puede ser engañosa y fulminante:", items: ["Preeclampsia sin características de gravedad (leve, elevación a 140/90 mmHg que puede estabilizarse y ser vigilada hasta que el bebé madure)", "Preeclampsia con características de gravedad (presiones que superan los 160/110 mmHg, que exigen parto inminente de urgencia o medidas terapéuticas severas)", "Eclampsia (el cuadro más devastador donde la presión no tratada afecta el cerebro, provocando convulsiones masivas o el coma materno)", "Síndrome HELLP (Hemólisis, Enzimas Hepáticas Elevadas, Bajo recuento de Plaquetas): una de las variantes más severas y peligrosas de esta complicación que daña rápidamente la sangre y el hígado"], note: "Tener el primer embarazo, la obesidad, embarazos múltiples (gemelos), hipertensión crónica preexistente o tener más de 35 años aumentan abrumadoramente el riesgo." }, diagnosis: { title: "Detección Obstétrica y Marcadores", intro: "Se detecta mediante un monitoreo riguroso durante las citas rutinarias de control del embarazo:", items: ["Evaluación e identificación de un aumento sostenido en las lecturas de presión arterial por encima de lo normal en múltiples revisiones (una presión superior a 140/90 en reposo después de la mitad del embarazo es el primer gran indicador)", "Análisis general y químico de orina (para detectar niveles inusualmente altos de proteinuria o proteína en la orina, lo cual significa que los riñones están dañados y se están 'goteando')", "Análisis de sangre para la química general de la sangre, función hepática (AST/ALT) y recuento plaquetario para la detección temprana del temido HELLP", "Ecografía obstétrica y doppler especializado en la arteria umbilical (para monitorizar el peso, el tamaño y el sufrimiento, o la restricción del flujo fetal)"], note: "A veces, las presiones altas silenciosas no se presentan con ningún otro síntoma perceptible en las madres al comienzo." }, treatment: { title: "Cura, Contención y Terminación del Embarazo", intro: "El único tratamiento seguro, final y curativo para detener la preeclampsia severa y la toxemia es finalizar el embarazo y expulsar la placenta enferma:", subsections: [ { title: "Protocolos Clínicos Perinatales", items: ["Control, internamiento hospitalario, corticoides para maduración fetal de los pulmones del bebé (y esperar vigilante a que avance un poco el embarazo, si se diagnostica en embarazos lejanos al final de la gestación) bajo reposo absoluto", "Medicamentos y fármacos antihipertensivos agresivos por vía intravenosa (Labetalol o Nifedipina) durante el ingreso, para evitar una catástrofe cerebrovascular en la madre", "Sulfato de magnesio intravenoso (un mineral infundido preventivamente durante y después del parto para proteger el cerebro de la embarazada y evitar drásticamente los ataques convulsivos letales - la Eclampsia)", "Inducción al parto inmediato o cirugía de cesárea de emergencia: sea cual sea la edad del feto, en caso de desarrollar gravedad límite (preeclampsia severa o HELLP)"] } ], note: "Para mujeres con historial previo y riesgo elevadísimo de preeclampsia, la toma profiláctica diaria de aspirina en dosis muy bajas bajo estricta recomendación del ginecólogo al inicio reduce masivamente las posibilidades." }, whenToSeekHelp: { title: "¿Cuándo es una alerta obstétrica inminente y letal?", intro: "Llama de urgencia a tu doctor ginecólogo o dirígete sin ninguna espera al servicio de urgencias y sala de parto más cercano si, en la segunda etapa del embarazo, presentas intempestivamente:", items: ["Cefalea y un fuerte e incapacitante dolor de cabeza pulsátil que no desaparece con un analgésico convencional", "Alteraciones claras en tu vista y visión borrosa (perder visión un instante, ver destellos fuertes y continuos de chispas de luz, destellos negros, y manchas o pérdida de visión)", "Dolor agudo en la zona superior y abdominal superior derecha, exactamente debajo de tus costillas y en el lado de la espalda (debido a hinchazón súbita masiva y el hígado dilatado)", "La aparición notoria de un hinchazón edema en la cara y párpados, o un repentino y enorme aumento de peso rápido por encima de los kilos sanos previstos en una semana"] } },
'Osteoartrosis' : { intro: "La osteoartrosis, frecuentemente llamada artrosis o simplemente osteoartritis, es la forma más prevalente y común de la artritis en las personas mayores. Es una enfermedad degenerativa dolorosa de las articulaciones que afecta a millones, afectando directamente su independencia y la posibilidad de moverse y vivir sin molestias.", whatIs: { title: "¿Qué es la Osteoartrosis?", text: "Es el lento desgaste físico y el fallo completo del recubrimiento protector del tejido cartilaginoso. El cartílago sano se encarga de proteger las extremidades y los bordes de los huesos para permitir que la articulación se deslice, ruede y funcione limpiamente sin fricción. Cuando desaparece, todo el mecanismo de la articulación choca rígidamente e impacta de hueso desnudo contra hueso desnudo. Esto incita y acelera un fuerte cuadro inflamatorio secundario de hinchazón en los ligamentos de las zonas articulares y un grave e intenso dolor sordo." }, types: { title: "Desgaste Articular Principal", intro: "Normalmente se manifiesta y se focaliza más agresivamente en donde hay soporte excesivo de peso mecánico:", items: ["Rodillas y las articulaciones de la Cadera (que cargan con el mayor porcentaje del peso al estar erguidos y al desplazarse, afectando mayormente la calidad de marcha diaria)", "La base de los pulgares o primera base en la mano, y la zona de la base de todos los dedos (rizartrosis o pequeños nudos abultados notorios llamados de Bouchard o Heberden, deformando dolorosamente las manos al tejer, asir y trabajar)", "La columna de manera completa, tanto en la parte inferior de la espalda o zona Lumbar, o superior afectando las raíces espinales en la parte Cervical"], note: "" }, diagnosis: { title: "Valoración en Consultorio de Especialista", intro: "El especialista evaluará detalladamente al paciente y pedirá imágenes de imagenología muy eficaces:", items: ["La Rayo-X es la piedra angular para identificar artrosis severa y confirmar la notable ausencia que ha causado de ese vital espacio articular de 'cojín y aire' que hay entre las dos articulaciones, o diagnosticar el daño visible por crecimiento de un espolón duro de hueso extra o crecimientos esqueléticos o nudos compensatorios, denominados técnicamente 'osteofitos'", "Revisar un dolor constante pero muy localizado o crepitación de ruidos duros en las articulaciones que resuenan cuando te mueves", "Se puede realizar la extracción de una cantidad del líquido de los ligamentos y del recubrimiento articular intraarticular (análisis sinovial o punciones) mediante punción solamente para lograr descartar definitivamente ataques o procesos parecidos que tengan características metabólicas cristalizadas (como se diagnostica la gota o patología del ácido úrico)"], note: "En etapas precoces tempranas e iniciales, antes de aparecer cualquier espolón de desgaste, el paciente padece dolor moderado y los análisis mediante Rayos-X son capaces de verse perfectamente inocentes y normales todavía." }, treatment: { title: "Restaurar Fuerza Muscular, Flexibilidad y Reemplazo Articular", intro: "Se maneja y se reduce su daño progresivo mejorando un modo saludable para frenar su deterioro, ya que los cartílagos perdidos no se sanan de ninguna manera:", subsections: [ { title: "Abordajes Conservadores", items: ["Bajar de grasa y de kilos a base de dieta para lograr el peso recomendado con urgencia, así como un aumento notable en la Fisioterapia o Ejercicios Aeróbicos terapéuticos de agua o fortalecimiento muscular isométrico específico del músculo periférico de soporte en las zonas doloridas. El músculo grande debe soportar y descargar ese esfuerzo diario, que se le exime a la débil coyuntura.", "Tomar analgésicos fuertes diarios (Acetaminofén y desinflamatorios e ibuprofeno potentes de venta libre), o aplicarlo como ungüento gel en la parte lesionada.", "Uso de bastones, correctores biomecánicos especiales y un estilo de zapato suave amortiguado y adaptado, y apoyos y mangas de alivio mecánico", "Intervención fuerte de Inyecciones clínicas ambulatorias directamente introducidas en los tendones afectados de la extremidad con base en anti-dolorosos inmediatos y temporales, en especial los desinflamatorios como los Corticoesteroides o la inyección intraarticular viscosa resbalosa a base de derivado natural del Ácido Hialurónico, que devuelve lubricidad y amortiguamiento por ciertos meses repetitivos", "Someter a una total operación de Cirugía, Artroplastia o Reemplazo Articular articular que cambiará totalmente una rodilla dolorosa e invalidante y su hueso desgastado con reemplazos e implantes especiales sintéticos y artificiales cerámicos de vanguardia si es el tratamiento definitivo para vivir sin limitaciones de invalidez al pasar un proceso duro crónico incontrolable."] } ], note: "Es vital un estiramiento suave para evitar las atrofias del tejido general a todas las edades que acompañan por dolor crónico y limitante." }, whenToSeekHelp: { title: "¿Cuándo es necesario reportar una invalidez médica grave?", intro: "Acude a la consulta especializada al notar:", items: ["Dolores, falta de aguante y malestares insoportables limitantes intensos, constantes crónicos o agudos presentes a cada paso, o que no remiten al momento de descansar tranquilo en el colchón al fin de una jornada en el sofá o por la nocturna inamovible", "Rigidez de hueso articular por la total o temprana pérdida visible y notoria extrema del rango total rotatorio que te incapacita inmensamente en todas las cosas pequeñas y elementales que se hacían con un buen manejo cotidiano físico diario regular (peinarse sin dolor en los brazos o cortarse sin llorar de dolor las puntas en las uñas debido a la rotación o agacharse a caminar en el día a día o sentarse al inodoro)", "Te sientes francamente limitado, tus coyunturas del brazo/piernas o huesos pierden soporte para apoyarse, sientes un crac que duele o inflamación brusca sin motivo aparente por encima en las uniones óseas articulatorias con grandes zonas sensibles, tibias al calor e irritantemente tumefactas"] } },
'Dolor en la inserción del talón' : { intro: "El dolor en la inserción del talón en el retropié, en concreto en la parte posterior, superior o trasera del calcaño donde el tendón principal conectivo grueso está adherido y fijado al hueso inferior de toda la pierna. Resulta una zona muy susceptible a molestias recurrentes.", whatIs: { title: "¿Qué es la Inserción Tendinosa y Dolorosa en el Hueso del Talón?", text: "Es comúnmente una condición tendinopatía insercional del músculo largo tendón de Aquiles, en ocasiones combinada firmemente en un problema conjunto con bolsas pequeñas sinoviales que duelen al inflamarse fuertemente con calcificación o bursitis calcánea retrocalcánea. Se ocasiona cuando el área física que unirá los fuertes y potentes músculos principales isquiotibiales de las piernas traseras con los bordes duros de dicho esqueleto posterior sufre microrroturas progresivas, tirantez aguda continua y sobrecarga, ocasionando micro lesiones con hinchazones profundas al dar cada mínima pisada que te desplace del piso de tu planta." }, types: { title: "Los Tres Puntos Focalizados del Desencadenamiento Doloroso Posterior del Zapato", intro: "Normalmente los afectados sufrirán una combinación crónica patológica que ataca tres factores locales de fricción:", items: ["Tendinitis o patología de Aquiles pura (Inflamación central reactiva puramente del tendón debido a la repetición constante sin descanso que engruesa visiblemente su textura sobre el calcáneo en la parte inferior o posterior y pierde elasticidad del tobillo)", "Deformidad dura de Haglund por exostosis (la cual es un engrosamiento y un bulto muy saliente deformante, o exceso grande y agresivo del hueso mismo central de la región del talón por fricciones de roces diarios apretados, lo cual impactará y lastimará progresivamente a su vez al tejido blanco del Aquiles, como espinas)", "Bursitis y líquidos articulares locales de apoyo retroaquílea dolorosa inflamada en áreas donde debe correr un líquido viscoso para no producir ese daño físico de presión y calce por las estructuras musculares de las zapatillas"] }, diagnosis: { title: "Detecciones Podológicas y Especialización de Ortopedistas", intro: "Las revisiones profundas de las anomalías focales se confirman y apoyan principalmente en:", items: ["El estudio mecánico integral (presión, tacto manual doloroso directo en tu protuberancia saliente enrojecida, de manera y postura firme, verificando de cerca la cojera visible causada o problemas de la tensión muy apretada de pantorrilla de tu zancada natural normal)", "La inspección muy clara y generalizada de Rayos-X simples de la región baja para medir al hueso calcáneo exacto de perfil (donde puede evidenciar enormemente y distinguir bultos óseos crecientes de Haglund con picos agudos prominentes del calcáneo por roces crónicos, desprendimientos calcificados patológicos u osteofitos insertados adheridos en los nudos del Aquiles calcificados de abajo)"], note: "" }, treatment: { title: "Fisioterapia Estricta del Tríceps Sural, Tensión Calzador, Alivios Ortopédicos Físicos", intro: "Tratar esta patología limitadora con total cuidado y no forzar jamás por deporte al hueso dolorido y sus zonas de soporte es mandatorio:", subsections: [ { title: "Estrategias Integradas Médicas Clínicas", items: ["Reposo absoluto, hielo constante general y los paros deportivos inmediatos (la primera fase anti dolor, o de estricto no caminar ni frotar contra ninguna deportiva apretada es clave del manejo y descanso, alternadas en la rehabilitación de alivios y analgésicos desinflamantes o paracetamol)", "Implementación biomecánica inmediata de usar y meter en tus zapatillas alzas, calzas especiales con talones libres ortopédicos elevados o cuñas rígidas específicas con elevadores blandos o zapatos muy acojinados al pisar fuerte. Bajarán de un tajo inmenso todas esas presiones forzadas que frotan el área y los tirones crónicos en el largo del tendón rígido por no estar forzado y jalado tensamente abajo en el zapato ajustado.", "Fisioterapia muy extensa y dirigida estricta excéntrica, ejercicios manuales fisioterapéuticos con contracciones y estiramientos que relajan gradualmente al músculo isquiotibial largo gemelo acortado al tendón posterior. Terapias potentes analgésicas o láser anti rubor de las bursas y ondas enfocadas de choque profundas físicas, para destruir y ablandar dolorosamente el espolón dolorido reactivo crónico inmovilizador que choca o fricciona", "Técnicas infiltratorias quirúrgicas definitivas especializadas con aguja directa de limpieza percutánea. De lo contrario y como la mayor salida en lesiones graves y ruptura total es el abordaje cruento del médico del bisturí ortopédico desbridante local (que abrirá, tallará los cartílagos del área, resecará completamente o quitará esos piquitos, o limará y destruirá los grandes 'bollos de huesos agresivos duros raspantes' y reconectará mecánicamente, usando modernos implantes y suturas los desgarros o ligamentos arrancados perdidos en el tobillo dañado trasero del dolor severo incapacitante)"] } ], note: "Tristemente, no se debe realizar un pinchazo e inyección frecuente analgésica rápida e indolora que traiga Corticoesteroides internos profundos a todo paciente adolorido en su talón de Aquiles, ya que incrementa drásticamente las debilidades o la posibilidad de una fatal ruptura total, violenta o desprendimiento absoluto de emergencia posterior grave y pérdida motora temporal de su pierna a caminar en atletas y gente de a pie por uso abusivo para no reposar el daño." }, whenToSeekHelp: { title: "¿En qué casos clínicos debo requerir urgencias del dolor trasero del Talón?", intro: "Evitar empeorar y requerir consulta temprana siempre del pie. Actuar muy rápido e ir obligatoriamente si ocurren en esa extremidad afectada signos rotundos graves:", items: ["La debilidad es absoluta de pararse y del músculo del empeine largo bajo (Sientes inestabilidad paralizante fuerte, con una muy débil caída por sorpresa rápida sin la pisada adecuada sin apoyo seguro al sostener o cargar tú cuerpo al piso de la habitación) e inflaman exageradamente la porción baja al doblar y girar", "Percibes o escuchas bruscamente los grandes rotos o un ruido crujiente como de cuerdas estallando del tobillo del talón trasero (Chasquidos violentos secos desgarradores auditivos internos del pie trasero agudos o intensos con el pinchazo que incapacita el dar pisadas normal de inmediato hacia al suelo tras impulsos, un síntoma clásico del talón desgarrado desprendido fatal roturado) que arde fuertemente al palpar superficial la zona hundida donde falta carne y hay depresión física anormal donde era tensa o dura (Brechas o huecos o huecos grandes por detrás del hueco doloroso rotoso e inflamado rojo en el calcáneo trasero tobillo sin poder ponerse nunca bajo ningún modo de 'puntillas')"] } },
'Cáncer colorrectal' : { intro: "El cáncer colorrectal es una enfermedad grave en la que se forman células cancerosas (malignas) en los tejidos del colon o del recto, partes del sistema digestivo. Es uno de los cánceres más prevenibles a través de pruebas de detección temprana.", whatIs: { title: "¿Qué es el Cáncer Colorrectal?", text: "Es el crecimiento descontrolado de células, típicamente originado en pólipos adenomatosos precancerosos benignos en el revestimiento interno del intestino grueso o recto. Con el tiempo, algunos de estos pólipos mutan y se vuelven cancerosos, invadiendo la pared intestinal." }, types: { title: "Tipos de Tumores", intro: "Se clasifican por su origen:", items: ["Adenocarcinomas (el tipo más frecuente, originado en células que producen moco)", "Tumores carcinoides gastrointestinales (se originan en células productoras de hormonas)", "GIST o tumores del estroma gastrointestinal", "Linfomas y sarcomas (muy raros en el colon)"], note: "El historial familiar y la edad (mayores de 50) son factores de riesgo clave." }, diagnosis: { title: "Detección", intro: "Las pruebas de cribado salvan vidas al encontrar pólipos antes de que se vuelvan cáncer:", items: ["Colonoscopia (la prueba estándar de oro para ver y extirpar pólipos)", "Análisis de sangre oculta en heces", "Sigmoidoscopia flexible", "Pruebas de ADN en heces", "Tomografía computarizada y resonancia magnética para ver la diseminación"], note: "" }, treatment: { title: "Tratamiento Oncológico", intro: "Suele requerir un abordaje integral:", subsections: [ { title: "Intervenciones", items: ["Polipectomía (extirpación del pólipo durante la colonoscopia, curativo si es temprano)", "Colectomía (cirugía para extirpar la parte enferma del colon y los ganglios linfáticos vecinos)", "Quimioterapia (después de la cirugía para matar células restantes, o antes para reducir el tumor)", "Radioterapia (especialmente en cáncer de recto)", "Inmunoterapia y terapia dirigida (en estadios avanzados o metastásicos)"] } ], note: "En algunos casos quirúrgicos se requiere una colostomía temporal o permanente." }, whenToSeekHelp: { title: "¿Cuándo acudir al gastroenterólogo?", intro: "Es urgente consultar si presentas:", items: ["Sangrado rectal, heces con sangre roja brillante o heces negras (alquitranadas)", "Cambios persistentes en tus hábitos intestinales (diarrea, estreñimiento, sensación de que no se vacía completamente)", "Dolor o molestias abdominales persistentes, gases, cólicos crónicos y pérdida de peso sin causa aparente"] } },
'EIP (infección genital femenina)' : { intro: "La Enfermedad Inflamatoria Pélvica (EIP) es una infección grave de los órganos reproductores femeninos superiores. Ocurre con frecuencia cuando las bacterias de transmisión sexual se propagan desde la vagina o el cuello uterino hasta el útero, las trompas de Falopio o los ovarios.", whatIs: { title: "¿Qué es la EIP?", text: "Es una complicación aguda que surge generalmente por una ETS no tratada, como la clamidia o la gonorrea. Provoca inflamación y cicatrización en los órganos internos. Si no se aborda rápidamente, puede causar daños irreversibles, dolor crónico severo y esterilidad permanente." }, types: { title: "Complicaciones Críticas", intro: "Los problemas a largo plazo si no se trata incluyen:", items: ["Infertilidad tubárica (tejido cicatricial que bloquea completamente las trompas de Falopio)", "Dolor pélvico crónico e incapacitante (por adherencias pélvicas en los intestinos y ovarios)", "Embarazo ectópico fatal (el óvulo fertilizado no puede bajar por la trompa dañada y crece dentro de ella)", "Absceso tubo-ovárico (una acumulación peligrosa de pus infectado que amenaza la vida y requiere cirugía de emergencia)"], note: "Muchas mujeres pueden tener la infección con síntomas muy leves e ignorar que están en peligro." }, diagnosis: { title: "Diagnóstico Ginecológico Inmediato", intro: "El ginecólogo confirmará la infección y su gravedad:", items: ["Examen pélvico físico comprobando un intenso dolor agudo ('signo del candelabro') al mover el cuello uterino y palpando la presencia de masas e inflamación en los ovarios", "Muestras de fluidos (frotis o cultivos del cuello uterino) para diagnosticar con qué bacterias específicas (gonorrea o clamidia) se originó la infección ascendente", "Análisis de sangre para verificar los marcadores inflamatorios agudos o la presencia de fiebre y leucocitos altísimos", "Ecografía pélvica de emergencia (ecografía ginecológica o transvaginal profunda para observar visualmente grandes abscesos purulentos o trompas de Falopio llenas y distendidas por líquido y pus)"], note: "" }, treatment: { title: "Manejo y Erradicación Médica", intro: "Es fundamental tratar agresivamente el cuadro para minimizar los daños estructurales profundos y frenar el avance de las bacterias:", subsections: [ { title: "Intervenciones Sistémicas de Impacto", items: ["Ciclos intensivos con antibióticos sistémicos potentes (orales e inyecciones intramusculares para curar y combatir de inmediato a las bacterias más prevalentes)", "Se requiere tratar paralelamente a los contactos de la pareja o las parejas sexuales para detener completamente los reinfecciones recurrentes de cepas no resueltas", "Hospitalización de máxima urgencia (con fuertes antibióticos o sueros mediante gotero por vía intravenosa total durante los episodios graves que involucren un intenso y constante nivel de dolores severos con fiebre y escalofríos severos)", "Cirugía, Laparotomía de Urgencia en casos vitales (Drenar los abscesos infectados reventados, cortar masas y retirar quirúrgicamente los aparatos o trompas putrefactas o necrosadas que amenacen la vida con Sepsis mortal en casos agudos extremos del cuerpo)."] } ], note: "Aunque los antibióticos curarán toda la carga de infección actual, lamentablemente no podrán revertir ni un poco de la cicatriz de daño a las trompas ni restaurar lo lesionado previamente y permanentemente en la fecundidad de años futuros de la paciente joven." }, whenToSeekHelp: { title: "¿Cuándo asistir inmediatamente de Urgencias al Médico?", intro: "Evita de todos modos las secuelas permanentes irrecuperables en tu vida y órganos femeninos. Reporta de inmediato al centro médico de salud al tener y percibir:", items: ["Fuertes y severos dolores profundos repentinos, molestia o pinchazos incapacitantes persistentes en el bajo vientre, la baja pelvis uterina baja que va desde moderado hasta agudizarse profundamente o agravarse tras el sexo, durante todas las jornadas del mes normal de manera sorda dolorosa pero profunda", "El dolor severo pélvico agudo agónico con picos de repentina fiebre muy altas inexplicables de temperaturas o violentos episodios de tiritones febriles intermitentes que denotan la sepsis grave y purulenta dentro de ti", "Evidente flujo o material abundante secretado con tonos espesos, olores pútridos extraños asquerosos o purulentos amarrillos (leucorrea fétida o signos obvios no normales infecciosos)", "Señal de urgencias como presentar ardores de orina al extremo, severa hemorragia sangrante profusa entre el período fuera del nivel mensual y náusea acompañada del vómito repentino severo asociado a las presiones de bajo tu estómago dolorido pélvico"] } },
'Depresión en los ancianos' : { intro: "La depresión en los adultos mayores es un problema generalizado pero que no forma parte normal del envejecimiento. A menudo no se reconoce ni se recibe tratamiento, lo que disminuye la calidad de vida y aumenta el riesgo de otras enfermedades.", whatIs: { title: "¿Qué es la Depresión en Ancianos?", text: "Es un trastorno del estado de ánimo que en la tercera edad puede presentarse más con síntomas físicos, quejas somáticas y problemas de memoria, en lugar de la clásica tristeza profunda, lo que dificulta su diagnóstico." }, types: { title: "Factores y Presentaciones", intro: "Se asocia fuertemente a otros problemas de la edad:", items: ["Depresión vascular (asociada a problemas de circulación cerebral)", "Depresión secundaria a enfermedades médicas crónicas (Parkinson, cáncer, demencia)", "Depresión por duelo prolongado o aislamiento social"], note: "Suele confundirse con las primeras etapas del Alzheimer (pseudodemencia depresiva)." }, diagnosis: { title: "Evaluación Geriátrica", intro: "El médico o geriatra evaluará:", items: ["Historia clínica y revisión de todos los medicamentos que toma (polifarmacia)", "Cuestionarios específicos como la Escala de Depresión Geriátrica (GDS)", "Pruebas cognitivas para diferenciar entre depresión y demencia verdadera"], note: "" }, treatment: { title: "Manejo Integral", intro: "Responde muy bien al tratamiento si se aborda correctamente:", subsections: [ { title: "Terapias", items: ["Antidepresivos (con dosis ajustadas y cuidado por interacciones con otros fármacos)", "Psicoterapia (terapia cognitivo-conductual o de apoyo)", "Fomento de la actividad física, socialización y apoyo familiar activo"] } ], note: "Tratar los dolores crónicos y problemas de audición o visión ayuda enormemente." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es vital acudir al médico si el adulto mayor:", items: ["Pierde interés en actividades que antes disfrutaba, se aísla o deja de comer", "Se queja constantemente de dolores físicos sin causa médica clara", "Habla sobre sentirse inútil, una carga para los demás, o menciona el deseo de morir"] } },
'Tendinitis, esguinces articulares' : { intro: "Las tendinitis y los esguinces articulares son lesiones musculoesqueléticas muy frecuentes que causan dolor y limitan la movilidad. Aunque afectan estructuras diferentes, a menudo ocurren por causas similares como el sobreesfuerzo, la mala técnica deportiva o los accidentes.", whatIs: { title: "¿Qué son?", text: "La tendinitis es la inflamación de un tendón (el cordón que une el músculo al hueso) por uso repetitivo. Un esguince es el estiramiento o rotura de un ligamento (el tejido duro que conecta dos huesos en una articulación) debido a un movimiento brusco o torcedura." }, types: { title: "Clasificación Común", intro: "Se clasifican según su ubicación y severidad:", items: ["Tendinitis (frecuente en hombro, codo, rodilla y tendón de Aquiles)", "Esguince de Grado 1 (estiramiento leve del ligamento, dolor sin inestabilidad)", "Esguince de Grado 2 (rotura parcial del ligamento, hinchazón moderada)", "Esguince de Grado 3 (rotura completa, incapacidad para usar la articulación, requiere evaluación urgente)"], note: "Ambas lesiones causan inflamación, dolor local y pérdida de función." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico es principalmente físico:", items: ["Exploración física palpando la zona dolorida y realizando maniobras de movilidad", "Radiografías (generalmente para descartar que haya fracturas óseas asociadas)", "Ecografía o Resonancia Magnética (para evaluar daños graves en los tejidos blandos)"], note: "" }, treatment: { title: "Primeros Auxilios y Recuperación", intro: "El tratamiento inicial suele ser conservador (Método RICE):", subsections: [ { title: "Medidas", items: ["Reposo (Rest), Hielo (Ice), Compresión y Elevación de la zona afectada", "Analgésicos y antiinflamatorios de venta libre (AINEs)", "Fisioterapia para restaurar la fuerza y la flexibilidad una vez baje la inflamación", "Inmovilización temporal o cirugía (solo en casos de roturas de grado 3 o tendones gravemente dañados)"] } ], note: "Regresar a la actividad física antes de la curación completa aumenta el riesgo de recaídas crónicas." }, whenToSeekHelp: { title: "¿Cuándo ir al médico?", intro: "Busca atención especializada si:", items: ["Escuchaste un fuerte 'chasquido' en el momento de la lesión", "El dolor es muy intenso y no puedes apoyar peso en la extremidad", "La articulación se hincha masivamente de forma rápida o presenta una deformidad evidente"] } },
'Asma bronquial' : { intro: "El asma bronquial es una enfermedad inflamatoria crónica de las vías respiratorias. Se caracteriza por la hiperreactividad bronquial, lo que significa que los pulmones reaccionan de manera exagerada a ciertos desencadenantes, provocando episodios de dificultad para respirar.", whatIs: { title: "¿Qué es el Asma Bronquial?", text: "Es una afección en la que los bronquios se inflaman, se estrechan y producen mucosidad adicional. Esto bloquea el paso del aire, causando sibilancias (silbidos al respirar), opresión en el pecho y tos persistente, especialmente de noche o de madrugada." }, types: { title: "Desencadenantes y Patrones", intro: "El asma se agudiza por diversas causas:", items: ["Asma alérgica (desencadenada por polen, ácaros, moho, pelo de animales)", "Asma no alérgica (desencadenada por aire frío, humo, estrés o perfumes fuertes)", "Asma inducida por el ejercicio (empeora durante la actividad física intensa)", "Asma ocupacional (exposición a químicos o polvo en el lugar de trabajo)"], note: "La severidad varía desde episodios intermitentes leves hasta casos graves y persistentes." }, diagnosis: { title: "Evaluación Pulmonar", intro: "El neumólogo confirmará el diagnóstico a través de:", items: ["Espirometría (mide la cantidad y la velocidad del aire que puedes exhalar)", "Prueba de reversibilidad bronquial (espirometría antes y después de usar un inhalador broncodilatador)", "Pruebas de alergia cutáneas o de sangre para identificar los desencadenantes"], note: "" }, treatment: { title: "Manejo y Control", intro: "El objetivo es prevenir las crisis y mantener la función pulmonar normal:", subsections: [ { title: "Tratamiento Farmacológico", items: ["Medicamentos de control o mantenimiento (corticosteroides inhalados de uso diario para reducir la inflamación crónica)", "Medicamentos de rescate (broncodilatadores de acción rápida como salbutamol para usar durante una crisis)", "Evitar estrictamente los desencadenantes conocidos"] } ], note: "Todo paciente asmático debe tener un Plan de Acción contra el Asma por escrito proporcionado por su médico." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Usa tu inhalador de rescate y acude a urgencias inmediatamente si:", items: ["Los medicamentos de alivio rápido no mejoran la falta de aire tras varios minutos", "Tienes dificultad para hablar en frases completas o caminar debido a la asfixia", "Sientes que tu pecho se hunde al respirar o tus labios/uñas toman un color azulado"] } },
'Enfermedad de la vesícula biliar' : { intro: "Las enfermedades de la vesícula biliar incluyen diversas afecciones que afectan a este pequeño órgano debajo del hígado, cuya función es almacenar la bilis. Los problemas más comunes surgen cuando el flujo de bilis se bloquea, causando inflamación y un dolor intenso.", whatIs: { title: "¿Qué es?", text: "El término abarca patologías como la formación de cálculos biliares (colelitiasis), la inflamación de la vesícula (colecistitis) aguda o crónica, y los pólipos vesiculares. El bloqueo del conducto cístico por una piedra provoca cólicos biliares dolorosos." }, types: { title: "Afecciones Principales", intro: "Las variantes más frecuentes son:", items: ["Cólico biliar (dolor agudo y temporal causado por una piedra que bloquea transitoriamente el conducto)", "Colecistitis aguda (inflamación severa e infección de la vesícula biliar, una emergencia médica)", "Coledocolitiasis (cálculos atascados en el conducto biliar común, que pueden dañar el hígado o páncreas)", "Disquinesia biliar (la vesícula no se vacía correctamente a pesar de no tener piedras)"], note: "" }, diagnosis: { title: "Detección", intro: "El diagnóstico se basa en síntomas e imágenes:", items: ["Ecografía abdominal (el estándar para ver piedras, pólipos e inflamación de la pared de la vesícula)", "Análisis de sangre (para verificar infección, inflamación y función del hígado/páncreas)", "Gammagrafía biliar o HIDA (para ver cómo funciona y se vacía la vesícula)"], note: "" }, treatment: { title: "Tratamiento y Extirpación", intro: "El manejo depende de la gravedad de los síntomas:", subsections: [ { title: "Opciones", items: ["Modificaciones dietéticas (dieta estricta muy baja en grasas para evitar que la vesícula se contraiga y cause dolor)", "Analgésicos y antibióticos (en casos de colecistitis antes de operar)", "Colecistectomía laparoscópica (cirugía mínimamente invasiva para extirpar la vesícula; es el tratamiento definitivo)"] } ], note: "Se puede vivir una vida completamente normal sin vesícula biliar, ya que la bilis fluye directamente del hígado al intestino." }, whenToSeekHelp: { title: "¿Cuándo ir a urgencias?", intro: "Debes buscar atención médica inmediata si padeces:", items: ["Dolor severo y constante en la parte superior derecha del abdomen que dura varias horas", "Dolor que se irradia hacia la espalda o el omóplato derecho", "Fiebre alta, escalofríos intensos o coloración amarillenta en la piel y los ojos (ictericia)"] } },
'Lunar' : { intro: "Un lunar (nevo melanocítico) es una pequeña marca en la piel causada por células productoras de pigmento (melanocitos) que crecen en grupos. Casi todos los adultos tienen algunos lunares; la mayoría son benignos y no requieren tratamiento.", whatIs: { title: "¿Qué es un Lunar?", text: "Es un crecimiento cutáneo común. Puede ser plano o elevado, liso o áspero, y de color rosado, marrón o negro. Generalmente aparecen durante la infancia y la adolescencia, y pueden cambiar lentamente de aspecto o desaparecer con el tiempo." }, types: { title: "Clasificación Clínica", intro: "Los dermatólogos los agrupan en:", items: ["Lunares comunes (pequeños, bordes definidos, color uniforme)", "Nevos displásicos o atípicos (lunares más grandes, de forma irregular y color desigual, que tienen mayor riesgo de convertirse en melanoma)", "Nevos congénitos (presentes desde el nacimiento)", "Nevos adquiridos (aparecen después del nacimiento a lo largo de la vida)"], note: "La exposición al sol y la genética son los principales determinantes de la cantidad de lunares." }, diagnosis: { title: "Evaluación (Regla ABCDE)", intro: "El diagnóstico y monitoreo lo realiza el paciente y el dermatólogo usando la regla ABCDE para descartar melanoma:", items: ["Asimetría (una mitad no coincide con la otra)", "Bordes (irregulares, festoneados o borrosos)", "Color (varios tonos de marrón, negro, rojo o azul en el mismo lunar)", "Diámetro (mayor a 6 milímetros, como el borrador de un lápiz)", "Evolución (cualquier cambio en tamaño, forma, color o síntomas como picor o sangrado)"], note: "Si un lunar parece sospechoso, se realiza una biopsia (extracción para análisis microscópico)." }, treatment: { title: "Extirpación y Cuidado", intro: "La inmensa mayoría no requiere tratamiento, pero pueden ser extirpados si:", subsections: [ { title: "Razones y Métodos", items: ["Son sospechosos de cáncer de piel (el dermatólogo lo extirpará quirúrgicamente para analizarlo)", "Están en zonas de constante fricción (como la línea del sostén o la zona de afeitado) y se irritan", "Extirpación quirúrgica o rasurado (nunca se deben intentar eliminar lunares en casa con métodos naturales por el riesgo de infección y cáncer no detectado)"] } ], note: "Las revisiones dermatológicas anuales son clave, especialmente para personas con más de 50 lunares o piel clara." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es fundamental acudir a un especialista si tienes un lunar que:", items: ["Cumple con alguno de los criterios de la regla ABCDE (cambia, crece o se oscurece)", "Comienza a picar excesivamente, doler, supurar, formar costras o sangrar sin motivo aparente", "Se ve como el 'patito feo', siendo muy diferente al resto de los lunares de tu cuerpo"] } },
'Tabaquismo' : { intro: "El tabaquismo es una adicción crónica y recurrente al tabaco, fundamentalmente provocada por la nicotina. Es la principal causa de enfermedad prevenible y muerte prematura en el mundo, afectando prácticamente todos los órganos del cuerpo.", whatIs: { title: "¿Qué es el Tabaquismo?", text: "Es una dependencia física y psicológica a la nicotina contenida en los productos del tabaco (cigarrillos, puros, tabaco de liar, vaporizadores). A pesar de conocer sus graves consecuencias (cáncer, EPOC, infartos), el fumador tiene gran dificultad para dejar de consumir." }, types: { title: "Tipos de Consumo e Impacto", intro: "El impacto del tabaquismo incluye:", items: ["Tabaquismo activo (la persona fuma directamente el producto)", "Tabaquismo pasivo o de segunda mano (inhalación del humo por parte de no fumadores cercanos, lo cual también causa enfermedades graves)", "Dependencia a nuevos dispositivos (cigarrillos electrónicos o vapeadores, que también contienen nicotina y químicos dañinos)"], note: "No existe un nivel seguro de consumo de tabaco." }, diagnosis: { title: "Evaluación de la Dependencia", intro: "El médico evalúa el grado de adicción para planificar el tratamiento:", items: ["Cuestionarios médicos (como el Test de Fagerström para evaluar la severidad de la dependencia a la nicotina)", "Evaluación del historial de consumo (paquetes/año) y de intentos previos de abandono", "Evaluación de daños en la salud (espirometría, radiografías)"], note: "" }, treatment: { title: "Cesación Tabáquica", intro: "Dejar de fumar suele requerir múltiples intentos, utilizando un enfoque combinado:", subsections: [ { title: "Estrategias de Apoyo", items: ["Terapia de Reemplazo de Nicotina (TRN) (parches, chicles, pastillas o aerosoles para reducir el síndrome de abstinencia)", "Medicamentos recetados (Vareniclina, Bupropión, que bloquean los receptores de nicotina en el cerebro y reducen el deseo)", "Terapia cognitivo-conductual, asesoramiento psicológico y grupos de apoyo mutuo"] } ], note: "Los beneficios para el corazón y los pulmones comienzan pocas horas después del último cigarrillo." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda médica?", intro: "Debes consultar a un profesional de la salud si:", items: ["Deseas dejar de fumar pero has fracasado en tus intentos por tu cuenta", "Sufres de tos crónica, falta de aliento, o dolor en el pecho", "Experimentas un síndrome de abstinencia severo (irritabilidad, ansiedad, insomnio) al intentar reducir el consumo"] } },
'Anorexia' : { intro: "La anorexia, que como síntoma general significa falta de apetito, suele referirse en el contexto de salud mental a la Anorexia Nerviosa, un trastorno alimentario grave caracterizado por la restricción extrema de la ingesta de alimentos y un miedo profundo a ganar peso.", whatIs: { title: "¿Qué es la Anorexia?", text: "Médicamente, la anorexia es la pérdida del apetito que puede acompañar a infecciones, cáncer o depresión. Psiquiátricamente (Anorexia Nerviosa), es una enfermedad donde la persona percibe su cuerpo con sobrepeso a pesar de estar peligrosamente delgada, llevándola a la inanición." }, types: { title: "Tipos Clínicos (Nerviosa)", intro: "En el trastorno alimentario, existen dos subtipos:", items: ["Tipo restrictivo (la pérdida de peso se logra casi exclusivamente con dietas, ayunos extremos y exceso de ejercicio)", "Tipo de atracones/purgas (se combinan episodios de restricción con el uso de vómitos, laxantes o diuréticos tras consumir pequeñas cantidades de comida)"], note: "Las consecuencias físicas incluyen osteoporosis, daño cardíaco, insuficiencia renal e incluso la muerte." }, diagnosis: { title: "Diagnóstico", intro: "El diagnóstico debe ser multidisciplinario debido al riesgo vital:", items: ["Examen físico para verificar el índice de masa corporal (IMC), la presión arterial baja y el ritmo cardíaco lento", "Análisis de sangre para detectar desequilibrios de electrolitos severos, anemia o problemas renales", "Evaluación psiquiátrica guiada por el DSM-5 para confirmar los patrones de pensamiento y la distorsión de la imagen corporal"], note: "" }, treatment: { title: "Recuperación y Nutrición", intro: "El tratamiento es complejo y requiere estabilizar la salud física y mental:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Renutrición médica (a menudo en el hospital para evitar el peligroso 'síndrome de realimentación')", "Psicoterapia especializada (Terapia Familiar para adolescentes, Terapia Cognitivo-Conductual para adultos)", "Educación nutricional para normalizar los patrones de alimentación", "Uso de antidepresivos o ansiolíticos para tratar problemas psiquiátricos coexistentes"] } ], note: "El paciente a menudo se niega al tratamiento y no reconoce la gravedad de su extrema delgadez." }, whenToSeekHelp: { title: "¿Cuándo intervenir urgentemente?", intro: "Amigos y familiares deben actuar y buscar ayuda médica inmediata si notan:", items: ["Pérdida de peso drástica o peso extremadamente bajo acompañado de excusas constantes para no comer", "Desmayos, mareos extremos, pérdida del período menstrual (amenorrea) o piel seca cubierta de un vello fino (lanugo)", "Rituales extraños con la comida (como pesar todo, cortarla muy pequeña, o cocinar para otros sin comer)"] } },
'Lesión facial' : { intro: "Una lesión facial, o traumatismo maxilofacial, incluye cualquier daño físico en la cara. Abarca desde cortes y laceraciones hasta fracturas complejas en los huesos de la mandíbula, los pómulos, la nariz y las órbitas de los ojos.", whatIs: { title: "¿Qué es un Traumatismo Facial?", text: "Es el daño a los tejidos blandos (piel, nervios, músculos), a los dientes o a los huesos que conforman el rostro. Las causas más comunes son accidentes de tráfico, caídas, agresiones físicas, lesiones deportivas y quemaduras." }, types: { title: "Tipos de Lesiones", intro: "Se clasifican según las estructuras afectadas:", items: ["Lesiones de tejidos blandos (laceraciones, contusiones, que pueden afectar nervios faciales o conductos salivales)", "Fracturas óseas faciales (fractura nasal, fractura mandibular, fractura del hueso cigomático/pómulo, o fracturas de la órbita ocular)", "Lesiones dentoalveolares (dientes fracturados, aflojados o completamente extraídos por el golpe)", "Fracturas complejas Le Fort (fracturas que separan grandes segmentos de los huesos faciales)"], note: "El daño facial puede comprometer la respiración, la visión o la capacidad de comer." }, diagnosis: { title: "Evaluación de Urgencia", intro: "Debido a la proximidad al cerebro y vías respiratorias, la evaluación debe ser rápida:", items: ["Evaluación primaria (ABC) para asegurar la vía aérea, respiración y circulación", "Examen neurológico básico (revisar visión, movimiento ocular, sensación facial)", "Tomografía Computarizada (TC) maxilofacial (el estándar de oro para diagnosticar fracturas faciales)", "Radiografías panorámicas (si se sospechan fracturas de mandíbula o daño dental)"], note: "" }, treatment: { title: "Manejo Quirúrgico y Restaurador", intro: "El tratamiento busca restaurar la función y la estética del rostro:", subsections: [ { title: "Intervenciones", items: ["Limpieza y sutura cuidadosa de laceraciones (a menudo por un cirujano plástico o maxilofacial para minimizar cicatrices)", "Reducción y fijación de fracturas (uso de miniplacas y tornillos de titanio insertados bajo la piel o dentro de la boca para estabilizar los huesos)", "Fijación intermaxilar (atar la mandíbula al maxilar con alambres temporalmente para que suelde el hueso)", "Tratamiento endodóntico o reimplante de dientes caídos"] } ], note: "Un diente caído debe ser reimplantado o colocado en leche fría y llevado al dentista antes de 60 minutos." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Acude a urgencias inmediatamente tras un golpe en la cara si presentas:", items: ["Dificultad para respirar, sangrado nasal o bucal profuso que no se detiene", "Visión doble, pérdida de visión, hundimiento del ojo o incapacidad para moverlo", "Los dientes no encajan correctamente al cerrar la boca, o hay dificultad/dolor extremo para abrirla", "Entumecimiento facial persistente, confusión, pérdida de memoria o salida de líquido claro por la nariz (puede ser líquido cefalorraquídeo)"] } },
'Delgadez' : { intro: "La delgadez o bajo peso ocurre cuando una persona tiene un peso corporal inferior al rango que se considera saludable para su estatura. Puede ser una condición natural o el síntoma de una enfermedad subyacente física o mental.", whatIs: { title: "¿Qué es la Delgadez?", text: "Médicamente se define como tener un Índice de Masa Corporal (IMC) inferior a 18.5. Aunque la sociedad a menudo idealiza la delgadez, un peso peligrosamente bajo priva al cuerpo de los nutrientes necesarios, debilitando el sistema inmunitario y los huesos." }, types: { title: "Causas y Contexto", intro: "La delgadez puede estar motivada por múltiples factores:", items: ["Delgadez constitucional o genética (personas con metabolismo rápido que son sanas y no tienen enfermedades subyacentes)", "Delgadez por enfermedades orgánicas (hipertiroidismo, cáncer, diabetes no controlada, enfermedad celíaca, problemas de malabsorción)", "Delgadez por trastornos de salud mental (Anorexia nerviosa, depresión severa, estrés crónico)"], note: "La pérdida de peso repentina e involuntaria es siempre un signo de alerta médica." }, diagnosis: { title: "Evaluación Médica", intro: "El médico buscará la causa del bajo peso:", items: ["Cálculo del IMC y revisión del historial dietético y patrón de pérdida de peso", "Análisis de sangre y heces (para evaluar hormonas tiroideas, nutrientes, anemia, inflamación intestinal o parásitos)", "Evaluación psicológica (si hay sospecha de un trastorno alimentario)", "Pruebas de imagen (si se sospechan tumores o infecciones crónicas)"], note: "" }, treatment: { title: "Recuperación de Peso", intro: "El tratamiento depende de la causa y busca restaurar un peso saludable:", subsections: [ { title: "Medidas", items: ["Aumento seguro de la ingesta calórica (dietas ricas en nutrientes, proteínas y grasas saludables diseñadas por un nutricionista)", "Tratamiento de la enfermedad subyacente (ej. medicación para el hipertiroidismo o dieta sin gluten para la celiaquía)", "Apoyo psicológico o psiquiátrico (en casos de trastornos alimentarios o depresión)", "Suplementos nutricionales (batidos hipercalóricos)"] } ], note: "Subir de peso requiere paciencia y debe hacerse de manera gradual y nutritiva, evitando la comida chatarra vacía." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental acudir a consulta si:", items: ["Has perdido el 5% o más de tu peso corporal en pocos meses sin intentarlo (sin hacer dieta ni aumentar el ejercicio)", "Te sientes constantemente fatigado, débil, te enfermas a menudo o se te cae mucho el cabello", "Las mujeres experimentan irregularidad o desaparición total del periodo menstrual (amenorrea)", "Sospechas que tu bajo peso está relacionado con el miedo obsesivo a comer o a engordar"] } },
'Colelitiasis' : { intro: "La colelitiasis es el término médico para designar la presencia de cálculos biliares (piedras) en la vesícula biliar. Es una condición muy común, especialmente en mujeres, y la mayoría de las personas que la padecen no presentan síntomas.", whatIs: { title: "¿Qué es la Colelitiasis?", text: "Ocurre cuando las sustancias que componen la bilis (principalmente colesterol o bilirrubina) cristalizan y forman piedras dentro de la vesícula. Mientras estas piedras permanezcan inactivas en la vesícula, a menudo no causan ningún daño ni dolor." }, types: { title: "Composición de los Cálculos", intro: "Se clasifican según su composición química:", items: ["Cálculos de colesterol (son los más frecuentes, representan más del 80% de los casos, a menudo amarillentos)", "Cálculos pigmentarios (hechos de bilirrubina, oscuros, comunes en personas con trastornos sanguíneos como anemia de células falciformes o cirrosis hepática)"], note: "El embarazo, la obesidad, las dietas ricas en grasas y la pérdida de peso muy rápida son factores de riesgo importantes." }, diagnosis: { title: "Detección", intro: "Generalmente se diagnostica cuando aparecen los primeros síntomas o de forma incidental:", items: ["Ecografía abdominal (el método más seguro, preciso y común para identificar cálculos dentro de la vesícula)", "Análisis de sangre (se realizan si hay dolor, para descartar infección, daño hepático o pancreático secundario)", "Resonancia Magnética (RM) o CPRE (si se sospecha que una piedra ha escapado y bloquea los conductos biliares principales)"], note: "" }, treatment: { title: "Manejo y Cirugía", intro: "Si no hay síntomas, no se recomienda tratamiento (solo observación). Si hay síntomas recurrentes:", subsections: [ { title: "Intervenciones", items: ["Colecistectomía laparoscópica (cirugía para extirpar toda la vesícula biliar, es la solución estándar para la colelitiasis sintomática)", "Modificaciones en la dieta (reducir el consumo de grasas ayuda a prevenir los episodios de cólicos dolorosos mientras se espera la cirugía)", "Medicamentos disolventes (ácido ursodesoxicólico; se usa muy raramente y solo para cálculos de colesterol pequeños si el paciente no puede ser operado, tarda meses o años en hacer efecto)"] } ], note: "Romper las piedras con ondas de choque (litotricia) no se usa comúnmente en la vesícula biliar porque las piedras vuelven a formarse." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Acude a urgencias o a un médico rápidamente si presentas un 'cólico biliar' severo:", items: ["Dolor fuerte y repentino en la parte superior derecha o centro del abdomen, que puede irradiarse al hombro derecho y dura de minutos a horas", "Dolor intenso acompañado de náuseas repetidas y vómitos", "Presencia de fiebre, escalofríos, o si tu piel y la parte blanca de los ojos se vuelven amarillas (indicadores de una complicación grave como inflamación o bloqueo de vías)"] } },
'Trastorno de alimentación en la lactancia y en la primera infancia' : { intro: "Los trastornos de alimentación en la lactancia y primera infancia implican el rechazo persistente a comer o la incapacidad para ingerir alimentos adecuadamente, lo que lleva a una pérdida de peso, falta de crecimiento o problemas nutricionales en un bebé o niño pequeño sano.", whatIs: { title: "¿Qué son estos Trastornos?", text: "Son dificultades marcadas y duraderas para alimentarse, que no se explican por afecciones médicas orgánicas subyacentes ni por falta de alimentos disponibles. El niño no consume suficientes nutrientes, lo que resulta en un 'retraso del crecimiento' o falta de medro." }, types: { title: "Formas de Presentación", intro: "Pueden manifestarse de diferentes maneras:", items: ["Trastorno de evitación/restricción de la ingesta de alimentos (ARFID) (rechazo por características sensoriales del alimento, texturas, o por miedo a atragantarse)", "Pica (ingestión persistente de sustancias no nutritivas como tierra, papel o tiza)", "Trastorno de rumiación (regurgitación y remasticación repetida de los alimentos)", "Problemas de interacción cuidador-niño (tensión o conflicto durante la hora de la comida que convierte la alimentación en una batalla)"], note: "Suelen aparecer antes de los 6 años de edad." }, diagnosis: { title: "Evaluación Pediátrica", intro: "El pediatra debe descartar cualquier problema físico primero:", items: ["Examen médico exhaustivo y evaluación del historial de crecimiento (curvas de percentiles de peso y talla)", "Análisis para descartar intolerancias alimentarias, alergias, reflujo gastroesofágico o problemas anatómicos de deglución", "Evaluación psicológica y de las dinámicas familiares durante el momento de la alimentación"], note: "" }, treatment: { title: "Intervención Multidisciplinaria", intro: "El objetivo es restablecer el crecimiento normal y mejorar la relación con la comida:", subsections: [ { title: "Terapias", items: ["Asesoramiento nutricional y establecimiento de rutinas de comida estructuradas sin distracciones", "Terapia de alimentación/ocupacional (para ayudar a los niños con aversiones sensoriales o problemas para masticar/tragar)", "Terapia conductual (para abordar la ansiedad del niño y guiar a los padres en técnicas de refuerzo positivo)", "Tratamiento de cualquier deficiencia nutricional (suplementos)"] } ], note: "Es vital reducir la ansiedad de los padres, ya que la presión excesiva para que el niño coma suele empeorar el rechazo." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Es necesario buscar apoyo profesional si:", items: ["El bebé o niño pierde peso o no gana el peso esperado durante varios meses seguidos", "La hora de comer es consistentemente una fuente de gran estrés, llanto o rabietas extremas", "El niño solo acepta un número extremadamente limitado de alimentos (menos de 5-10 alimentos diferentes)", "El niño se ahoga, tose excesivamente o vomita habitualmente al intentar comer"] } },
'Abuso sexual' : { intro: "El abuso sexual es cualquier actividad sexual no consentida, forzada, coaccionada o en la que la víctima no tiene la capacidad de consentir (como menores de edad, personas bajo los efectos de drogas o con discapacidad intelectual). Es un delito grave y un trauma profundo.", whatIs: { title: "¿Qué es el Abuso Sexual?", text: "Involucra un amplio espectro de comportamientos, desde tocamientos no deseados, acoso verbal explícito, exhibicionismo y voyeurismo, hasta la violación completa. Ocurre cuando se usa la fuerza, la manipulación, la autoridad o el engaño para someter a la víctima a actos sexuales." }, types: { title: "Contextos del Abuso", intro: "Puede ocurrir en diversas dinámicas, la mayoría involucrando a alguien conocido:", items: ["Abuso infantil (perpetrado por adultos o adolescentes mayores contra un niño; incesto si es dentro de la familia)", "Agresión sexual por conocidos (perpetrada por amigos, citas, compañeros de trabajo, lo cual es mucho más común que el asalto por un extraño)", "Violencia sexual en la pareja (violación conyugal)", "Acoso sexual en el lugar de trabajo o en el entorno digital (extorsión sexual)"], note: "El consentimiento debe ser libre, entusiasta y continuo. La ausencia de un 'no' (por miedo o parálisis) no significa 'sí'." }, diagnosis: { title: "Atención Médica y Forense", intro: "Tras una agresión aguda, la atención médica debe ser inmediata e integral:", items: ["Examen médico-legal ('Kit de violación') para recolectar pruebas físicas de ADN, a menudo realizado por enfermeras forenses, preferiblemente en las primeras 72-120 horas", "Pruebas de detección de Enfermedades de Transmisión Sexual (ETS) y embarazo", "Evaluación psicológica inmediata para manejo de crisis traumática"], note: "La víctima no debe ducharse, cambiarse de ropa ni cepillarse los dientes antes de ir al hospital para preservar la evidencia legal." }, treatment: { title: "Apoyo y Recuperación Psicológica", intro: "La recuperación del trauma requiere intervención especializada y apoyo:", subsections: [ { title: "Medidas y Terapias", items: ["Profilaxis médica (antibióticos preventivos para ETS, vacunas y píldora anticonceptiva de emergencia)", "Terapia de trauma a largo plazo (Terapia Cognitivo-Conductual centrada en el trauma o EMDR para manejar el Trastorno de Estrés Postraumático - TEPT)", "Grupos de apoyo para supervivientes de abuso", "Acompañamiento legal y trabajo social (redes de protección y alejamiento del agresor)"] } ], note: "La culpa y la vergüenza nunca son de la víctima. Sanar el daño emocional es un proceso lento que respeta los tiempos de la persona." }, whenToSeekHelp: { title: "¿A dónde acudir?", intro: "El abuso es una emergencia de seguridad y médica:", items: ["Llama a la policía (emergencias) o acude a urgencias del hospital inmediatamente tras una agresión aguda", "Llama a líneas de ayuda locales para víctimas de agresión sexual (brindan asesoramiento confidencial y acompañamiento) a cualquier edad", "Busca ayuda terapéutica si viviste abuso en el pasado y experimentas flashbacks, ansiedad paralizante, repulsión sexual o depresión"] } },
'Embarazo en la adolescencia' : { intro: "El embarazo en la adolescencia o embarazo precoz ocurre cuando una mujer queda embarazada antes de los 19 años. Conlleva desafíos médicos, sociales y emocionales significativos tanto para la joven madre como para el bebé, requiriendo un cuidado prenatal especializado.", whatIs: { title: "¿Qué es el Embarazo en la Adolescencia?", text: "Es la gestación que se produce durante la etapa de desarrollo y transición de la niñez a la edad adulta. Biológicamente, el cuerpo de la adolescente aún está creciendo, lo que la expone a un mayor riesgo de complicaciones físicas durante el embarazo y el parto." }, types: { title: "Riesgos Asociados", intro: "Los embarazos precoces tienen tasas más altas de problemas de salud:", items: ["Riesgos maternos (preeclampsia, anemia severa, eclampsia y mayor probabilidad de parto prolongado o cesárea)", "Riesgos fetales (nacimiento prematuro, bajo peso al nacer, que pueden derivar en problemas respiratorios y de desarrollo para el bebé)", "Impacto socioeconómico (deserción escolar, estigmatización social, menores oportunidades laborales y problemas de salud mental como depresión posparto)"], note: "El riesgo aumenta considerablemente si la adolescente tiene 15 años o menos." }, diagnosis: { title: "Detección y Cuidado Inicial", intro: "El diagnóstico temprano es crítico para asegurar un desarrollo sano:", items: ["Prueba de embarazo en orina o sangre tras un retraso menstrual, náuseas o fatiga inusual", "Confirmación y datación mediante ecografía pélvica o abdominal", "Evaluación médica completa temprana para detectar infecciones (ETS), estado nutricional y nivel de desarrollo físico"], note: "El miedo al rechazo familiar a menudo retrasa trágicamente la búsqueda de cuidado prenatal en adolescentes." }, treatment: { title: "Cuidado Prenatal y Apoyo", intro: "El manejo requiere un enfoque médico y psicosocial exhaustivo:", subsections: [ { title: "Intervenciones", items: ["Control prenatal riguroso y más frecuente para monitorear la presión arterial de la madre y el crecimiento del bebé", "Suplementación nutricional (ácido fólico, hierro, calcio) y educación sobre dietas saludables", "Apoyo psicológico y trabajo social (preparación para la maternidad, orientación sobre opciones reproductivas o adopción si es el caso, y estrategias para continuar la educación escolar)", "Educación y prescripción de métodos anticonceptivos eficaces postparto para evitar embarazos repetidos a corto plazo"] } ], note: "El apoyo incondicional de la familia o del entorno cercano mejora drásticamente los resultados de salud materno-infantiles." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Una adolescente embarazada debe acudir al médico obstetra de inmediato y contactar urgencias si:", items: ["Presenta cualquier sangrado vaginal o dolor abdominal fuerte durante el embarazo", "Siente mareos severos, visión borrosa o dolor de cabeza intenso (señales de presión arterial alta/preeclampsia)", "Experimenta sentimientos abrumadores de tristeza, ansiedad, soledad o tiene pensamientos de hacerse daño a sí misma"] } },
'Deseo sexual inhibido' : { intro: "El deseo sexual inhibido, conocido clínicamente como Trastorno de Deseo Sexual Hipoactivo (en mujeres) o Trastorno de Deseo Sexual Hipoactivo Masculino, es la ausencia o reducción significativa y persistente del interés, fantasías o pensamientos relacionados con el sexo, causando angustia.", whatIs: { title: "¿Qué es el Deseo Sexual Inhibido?", text: "Es una disfunción sexual en la que la persona pierde la motivación para participar en actividades sexuales, a pesar de que el entorno sea propicio. No se trata de una aversión total o de una falta de respuesta física si se inicia el sexo, sino de una carencia profunda del impulso o 'hambre' sexual." }, types: { title: "Tipos y Contexto", intro: "La pérdida de libido puede clasificarse según su aparición:", items: ["Primario (la persona siempre ha tenido un nivel muy bajo de deseo a lo largo de su vida)", "Adquirido/Secundario (el nivel de deseo era normal pero ha disminuido tras un evento médico, hormonal o emocional)", "Situacional (falta de deseo hacia la pareja actual, pero preservado hacia otras personas o en la masturbación)", "Generalizado (falta de deseo en absoluto en cualquier circunstancia)"], note: "Es muy común durante el embarazo, el posparto, la menopausia o periodos de estrés agudo." }, diagnosis: { title: "Evaluación Clínica y Psicológica", intro: "El diagnóstico requiere descartar causas puramente médicas:", items: ["Historial médico completo para revisar medicamentos (antidepresivos ISRS, anticonceptivos u opiáceos suelen destruir la libido)", "Análisis de sangre para verificar niveles de testosterona, estrógenos, prolactina y función tiroidea", "Evaluación psicológica relacional para detectar estrés crónico, depresión, ansiedad o conflictos no resueltos con la pareja"], note: "Se diagnostica como trastorno solo si la falta de deseo causa un malestar personal significativo." }, treatment: { title: "Abordaje Multidisciplinario", intro: "El tratamiento se personaliza según la raíz del problema:", subsections: [ { title: "Opciones Terapéuticas", items: ["Terapia sexual y de pareja (para mejorar la comunicación, resolver conflictos de intimidad y reducir la presión por el desempeño)", "Ajuste de medicamentos (cambiar un antidepresivo por otro con menos efectos secundarios sexuales, como el bupropión)", "Terapia hormonal (terapia de reemplazo de testosterona en hombres, o estrógenos/testosterona en dosis bajas en mujeres posmenopáusicas)", "Medicamentos específicos (como flibanserina o bremelanotida, aprobados para el deseo hipoactivo en mujeres premenopáusicas)"] } ], note: "Promover el bienestar general, el sueño adecuado y reducir el estrés diario son pilares fundamentales." }, whenToSeekHelp: { title: "¿Cuándo consultar a un especialista?", intro: "Es recomendable buscar la ayuda de un terapeuta sexual, ginecólogo o urólogo si:", items: ["La falta de deseo sexual está causando estrés personal intenso o deterioro severo en tu relación de pareja", "La pérdida de la libido ocurrió repentinamente después de empezar un nuevo tratamiento médico o tras un evento vital importante", "El bajo deseo viene acompañado de otros problemas físicos, como dolor durante el acto sexual o disfunción eréctil"] } },
'Artritis reumatoide' : { intro: "La artritis reumatoide es una enfermedad inflamatoria crónica de naturaleza autoinmune. A diferencia del daño por desgaste de la artrosis, la artritis reumatoide afecta el revestimiento de las articulaciones, causando una dolorosa hinchazón que puede eventualmente resultar en erosión ósea y deformidad.", whatIs: { title: "¿Qué es la Artritis Reumatoide?", text: "Es un trastorno autoinmunitario en el cual el sistema inmunológico ataca por error sus propios tejidos, comenzando por la membrana sinovial (la capa que recubre las articulaciones). Esta inflamación crónica destruye el cartílago y el hueso dentro de la articulación, y puede afectar órganos internos como corazón y pulmones." }, types: { title: "Características de la Enfermedad", intro: "Suele presentarse con un patrón clínico muy específico:", items: ["Afectación simétrica (afecta las mismas articulaciones en ambos lados del cuerpo, como ambas muñecas o ambas manos)", "Inicio periférico (generalmente comienza en las articulaciones pequeñas de los dedos de las manos y los pies)", "Enfermedad sistémica (además de dolor articular, causa fatiga extrema, febrícula y pérdida de peso, pudiendo desarrollar 'nódulos reumatoides' bajo la piel)"], note: "Los síntomas se presentan en períodos de exacerbación (brotes) intercalados con períodos de remisión relativa." }, diagnosis: { title: "Diagnóstico Reumatológico", intro: "El reumatólogo basa su diagnóstico en un conjunto de hallazgos:", items: ["Examen físico en busca de articulaciones hinchadas, rojas, calientes al tacto y dolorosas", "Análisis de sangre para detectar inflamación (Velocidad de sedimentación globular VSG, y Proteína C reactiva PCR)", "Análisis de autoanticuerpos (Factor Reumatoide y Anticuerpos péptidos citrulinados cíclicos o anti-CCP, muy específicos para la enfermedad)", "Radiografías y ecografías articulares (para establecer una línea base y monitorear la progresión del daño óseo a lo largo del tiempo)"], note: "" }, treatment: { title: "Tratamiento y Control del Daño", intro: "No tiene cura, pero el tratamiento temprano y agresivo puede detener la destrucción articular:", subsections: [ { title: "Fármacos y Terapias", items: ["FARMEs (Fármacos Antirreumáticos Modificadores de la Enfermedad, como el Metotrexato, que son la piedra angular para frenar el daño en la articulación)", "Agentes biológicos (terapias dirigidas que bloquean partes específicas del sistema inmunitario, usados si los FARMEs clásicos no son suficientes)", "Corticosteroides y AINEs (usados a corto plazo para aliviar rápidamente el dolor y la inflamación aguda durante un brote)", "Fisioterapia para mantener la movilidad, y cirugía (reemplazo articular o reparación de tendones) en casos de daño articular irreversible severo"] } ], note: "La 'ventana de oportunidad' para evitar daños permanentes es empezar el tratamiento en los primeros meses de la enfermedad." }, whenToSeekHelp: { title: "¿Cuándo acudir al reumatólogo?", intro: "Es vital buscar evaluación médica temprana si presentas:", items: ["Dolor articular constante e inflamación en varias articulaciones a la vez, especialmente en manos o pies", "Rigidez matutina severa en las articulaciones que dura más de una hora después de despertarte y comenzar a moverte", "Hinchazón articular acompañada de fatiga profunda e inexplicable y pérdida de energía"] } },
'Enfermedad de los ovarios poliquísticos' : { intro: "El síndrome de ovario poliquístico (SOP o PCOS en inglés) es un trastorno hormonal frecuente en las mujeres en edad reproductiva. Puede causar períodos menstruales infrecuentes o prolongados, así como niveles excesivos de hormonas masculinas (andrógenos).", whatIs: { title: "¿Qué es el SOP?", text: "Es un desequilibrio metabólico y endocrino donde los ovarios pueden desarrollar numerosas pequeñas acumulaciones de líquido (folículos o 'quistes') y no liberar óvulos regularmente. Está fuertemente ligado a la resistencia a la insulina y es una de las causas principales de infertilidad femenina." }, types: { title: "Características y Criterios", intro: "El síndrome se diagnostica cuando se cumplen al menos dos de los siguientes (Criterios de Rotterdam):", items: ["Irregularidad menstrual (ciclos muy largos, oligomenorrea, o ausencia de regla, amenorrea)", "Exceso de andrógenos (signos clínicos como exceso de vello, o detectados en análisis de sangre)", "Ovarios poliquísticos (múltiples folículos visibles en la ecografía que aumentan el tamaño del ovario)"], note: "A pesar de su nombre, no todas las mujeres con SOP tienen quistes ováricos, y tener quistes no significa necesariamente tener SOP." }, diagnosis: { title: "Evaluación Ginecológica y Endocrina", intro: "Para llegar al diagnóstico se requiere:", items: ["Examen físico y de historial médico detallado (peso, signos de vello facial, acné, acantosis nigricans)", "Análisis de sangre completos (niveles hormonales de testosterona, LH, FSH, así como pruebas de tolerancia a la glucosa y colesterol)", "Ecografía pélvica o transvaginal (para inspeccionar la apariencia y volumen de los ovarios y el grosor del revestimiento uterino)"], note: "" }, treatment: { title: "Tratamiento y Manejo", intro: "El tratamiento se enfoca en las preocupaciones individuales, como la fertilidad, el hirsutismo, el acné o la obesidad:", subsections: [ { title: "Terapias", items: ["Cambios en el estilo de vida (pérdida de peso, dieta baja en carbohidratos simples y ejercicio regular para reducir la resistencia a la insulina)", "Anticonceptivos hormonales (píldoras, parches o anillo para regular el ciclo, reducir el riesgo de cáncer de endometrio y controlar el acné/vello)", "Metformina (medicamento para la diabetes tipo 2 que mejora la resistencia a la insulina y puede reiniciar la ovulación)", "Medicamentos antiandrógenos (para bloquear los efectos de las hormonas masculinas)", "Tratamientos de fertilidad (Clomifeno, Letrozol o FIV si la paciente desea quedar embarazada)"] } ], note: "El control del SOP es a largo plazo para prevenir diabetes tipo 2 y enfermedades cardíacas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación si:", items: ["Tus períodos menstruales son constantemente irregulares, tienes menos de 8 ciclos al año, o la menstruación se detiene por completo", "Notas un crecimiento excesivo de vello en la cara, pecho, abdomen o muslos (hirsutismo) o acné adulto severo", "Estás intentando quedar embarazada sin éxito durante más de 12 meses", "Sufres de aumento de peso inexplicable y áreas de piel oscura y aterciopelada en el cuello o axilas"] } },
'Fracturas de cadera' : { intro: "Una fractura de cadera es una rotura en el tercio superior del hueso del muslo (fémur), cerca de la articulación de la cadera. Es una lesión grave, muy común en personas mayores, y requiere cirugía inmediata porque sus complicaciones pueden ser potencialmente mortales.", whatIs: { title: "¿Qué es una Fractura de Cadera?", text: "Es la ruptura del fémur proximal. En ancianos, la osteoporosis (huesos frágiles) suele ser la causa subyacente, haciendo que una simple caída desde su propia altura baste para romper el hueso. En personas jóvenes, suele ser producto de traumatismos de alta energía, como accidentes de coche." }, types: { title: "Clasificación Anatómica", intro: "El tratamiento quirúrgico depende de dónde se rompa el hueso:", items: ["Fractura del cuello femoral (ocurre justo debajo de la cabeza esférica del fémur; es peligrosa porque puede cortar el suministro de sangre a la cabeza del hueso)", "Fractura intertrocantérea (ocurre un poco más abajo del cuello del fémur, entre los trocánteres; es más fácil de fijar y tiene mejor flujo sanguíneo)", "Fractura subtrocantérea (menos común, ocurre por debajo de la zona trocantérea en el eje del hueso)"], note: "" }, diagnosis: { title: "Diagnóstico Clínico y Radiológico", intro: "Suele ser evidente en urgencias, pero se confirma mediante:", items: ["Observación clínica (la pierna afectada suele parecer más corta y el pie está rotado o girado hacia afuera de forma anormal)", "Radiografías de la cadera y pelvis (confirman casi todas las fracturas de cadera)", "Resonancia magnética (RM) o Tomografía Computarizada (TC) (se usan si el paciente tiene un dolor intenso tras una caída pero la fractura es tan fina que no aparece en los rayos X convencionales)"], note: "" }, treatment: { title: "Cirugía de Urgencia y Rehabilitación", intro: "El tratamiento estándar y casi universal es la intervención quirúrgica en las primeras 24-48 horas:", subsections: [ { title: "Opciones Quirúrgicas y Posoperatorias", items: ["Fijación interna con tornillos y placas (se usan tornillos de metal para mantener unidos los fragmentos de hueso mientras sana, común en fracturas intertrocantéreas)", "Reemplazo parcial de cadera (hemiartroplastia, se reemplaza solo la cabeza o bola del fémur rota por una prótesis de metal)", "Reemplazo total de cadera (artroplastia, se reemplaza tanto el extremo superior del fémur como la cavidad del hueso pélvico con prótesis artificiales)", "Fisioterapia intensiva iniciada el mismo día o al día siguiente de la cirugía para evitar coágulos de sangre, neumonía y pérdida muscular"] } ], note: "La inmovilidad prolongada tras una fractura de cadera es la causa principal de la alta mortalidad asociada a esta lesión en ancianos." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Se debe solicitar una ambulancia inmediatamente si, después de una caída, la persona presenta:", items: ["Incapacidad total y repentina de moverse, levantarse del suelo o soportar peso sobre la pierna afectada", "Dolor intenso, severo y agudo en la ingle, la cadera, o la parte superior del muslo", "Moretones pronunciados, hinchazón, o rigidez evidente en el área de la cadera", "Deformidad visible en la pierna (la pierna parece más corta o está girada hacia afuera)"] } },
'Infección urinaria en adultos' : { intro: "Una infección del tracto urinario (ITU) es una infección bacteriana que afecta cualquier parte del sistema urinario: riñones, uréteres, vejiga o uretra. Son sumamente frecuentes, especialmente en mujeres, y causan un molesto ardor y necesidad constante de orinar.", whatIs: { title: "¿Qué es una Infección Urinaria?", text: "Ocurre típicamente cuando las bacterias (más comúnmente E. coli del tracto gastrointestinal) ingresan por el conducto que expulsa la orina (uretra) y se multiplican en la vejiga. Si las defensas del cuerpo fallan, la infección puede causar dolor e inflamación local, o ascender peligrosamente a los riñones." }, types: { title: "Clasificación por Ubicación", intro: "Las infecciones se dividen según dónde se alojen las bacterias:", items: ["Cistitis (infección de la vejiga; la más habitual, causa presión pélvica, micción frecuente y dolorosa)", "Uretritis (infección de la uretra; a menudo relacionada con transmisión sexual en adultos jóvenes)", "Pielonefritis aguda (infección de los riñones; es una condición grave que causa fiebre alta, náuseas y dolor en la espalda alta/costado)"], note: "Las mujeres son más propensas a padecerlas debido a que su uretra es más corta y está más cerca del ano." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico suele ser rápido mediante pruebas de laboratorio:", items: ["Análisis de orina (para detectar glóbulos blancos, glóbulos rojos o la presencia de nitritos/bacterias en la orina)", "Cultivo de orina (para identificar exactamente qué tipo de bacteria está causando la infección y qué antibiótico es capaz de matarla)", "Ecografía o TC del tracto urinario (en casos de infecciones recurrentes o complicadas para descartar anomalías o cálculos renales)"], note: "A veces, en ITUs simples y clásicas en mujeres, el médico recetará tratamiento basándose solo en los síntomas." }, treatment: { title: "Terapia Antibiótica", intro: "El tratamiento principal es médico y orientado a erradicar la bacteria:", subsections: [ { title: "Manejo Clínico", items: ["Antibióticos orales (esenciales para curar la infección; un ciclo corto de 3 días suele bastar para la cistitis simple en mujeres)", "Analgésicos urinarios (como la fenazopiridina, que alivia el ardor intenso en un par de horas pero no cura la infección, tiñendo la orina de naranja)", "Aumento de ingesta de agua (para limpiar el tracto urinario mecánicamente)", "Antibióticos intravenosos y hospitalización (requeridos generalmente para infecciones renales severas)"] } ], note: "Es crítico completar toda la caja de antibióticos recetada, incluso si los síntomas desaparecen en el primer día." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Debes buscar atención médica si presentas:", items: ["Una necesidad urgente, intensa e incontrolable de orinar constantemente, pero solo expulsas unas gotas", "Sensación de ardor agudo o dolor cortante al orinar", "Orina de aspecto turbio, lechoso, con olor fuerte o con un tinte rojizo o rosado (sangre)", "Signos de infección renal: dolor en el flanco o espalda, fiebre, escalofríos, náuseas o vómitos (requiere consulta urgente)"] } },
'Tumor cerebral en adultos' : { intro: "Un tumor cerebral es el crecimiento y la multiplicación de células anormales en el cerebro o en los tejidos cercanos a él. Pueden ser benignos (no cancerosos) o malignos (cancerosos), pero debido al espacio cerrado del cráneo, cualquier tumor que crezca puede causar daño grave al presionar partes del cerebro.", whatIs: { title: "¿Qué es un Tumor Cerebral?", text: "Es una masa de tejido anormal dentro de la cabeza. Los tumores cerebrales primarios se originan en el propio cerebro, mientras que los tumores secundarios (metástasis) son cánceres que comenzaron en otro órgano (como pulmón, mama o colon) y se han diseminado al cerebro, siendo estos últimos mucho más comunes en adultos." }, types: { title: "Tipos de Tumores Primarios", intro: "Existen muchos tipos, nombrados según el tipo de célula donde inician:", items: ["Meningiomas (el tumor cerebral primario más frecuente en adultos, comienza en las membranas que rodean el cerebro, la mayoría son benignos y de crecimiento lento)", "Gliomas (originados en el tejido glial de soporte; el Glioblastoma es el tipo más común de tumor cerebral canceroso y agresivo en adultos)", "Adenomas hipofisarios (crecen en la glándula pituitaria en la base del cerebro, alterando las hormonas)", "Schwannomas o neuromas acústicos (tumores benignos en el nervio del equilibrio y la audición)"], note: "El grado del tumor (del I al IV) indica la rapidez con la que las células crecen y su nivel de malignidad." }, diagnosis: { title: "Evaluación Neurológica", intro: "El neurólogo o neurocirujano indicará:", items: ["Examen neurológico minucioso (comprobar la visión, audición, equilibrio, coordinación, fuerza y reflejos para ubicar qué parte del cerebro falla)", "Resonancia Magnética (RM) del cerebro con contraste (el estudio de imagen más importante y detallado para diagnosticar y mapear tumores cerebrales)", "Tomografía Computarizada (TC) (usada en urgencias para detectar sangrados o si la RM no es posible)", "Biopsia estereotáctica o quirúrgica (obtener una muestra del tumor mediante una aguja guiada a través de un agujero en el cráneo para su análisis patológico)"], note: "" }, treatment: { title: "Enfoque Oncológico y Quirúrgico", intro: "El tratamiento depende del tipo de tumor, su tamaño, ubicación y la salud del paciente:", subsections: [ { title: "Terapias Combinadas", items: ["Cirugía (craneotomía, es el tratamiento de primera línea si el tumor es accesible, para extirpar la mayor cantidad posible sin dañar funciones vitales)", "Radioterapia y Radiocirugía estereotáctica (Gamma Knife) (uso de haces de alta energía o radiación altamente focalizada para destruir restos del tumor o tratar tumores inoperables)", "Quimioterapia (fármacos a menudo en forma de pastillas, como la Temozolomida, usados en tumores malignos como los gliomas)", "Terapia dirigida (medicamentos que atacan anomalías específicas dentro de las células cancerosas)", "Rehabilitación neurológica postratamiento (fisioterapia, terapia ocupacional y del habla)"] } ], note: "Los esteroides (como la dexametasona) se usan frecuentemente para reducir rápidamente la inflamación cerebral alrededor del tumor y aliviar los dolores de cabeza severos." }, whenToSeekHelp: { title: "¿Cuándo es urgente consultar al neurólogo?", intro: "Los síntomas varían enormemente según la ubicación del tumor. Busca atención médica inmediata si experimentas:", items: ["La aparición de dolores de cabeza nuevos o un cambio severo en el patrón de tus dolores de cabeza habituales, especialmente si empeoran al despertar por la mañana o causan vómitos no precedidos de náuseas", "Aparición inexplicable de convulsiones en un adulto que nunca antes las había tenido", "Problemas graduales o repentinos con la visión (visión doble, pérdida de visión periférica), la audición, el habla o el equilibrio", "Pérdida gradual de la fuerza, debilidad, hormigueo o parálisis en un brazo o pierna, o cambios inexplicables en la personalidad o el comportamiento"] } },
'Derrame pleural' : { intro: "Un derrame pleural es una acumulación inusual de líquido alrededor de los pulmones. Específicamente, el líquido se acumula en el espacio pleural, que es el espacio que hay entre las capas de tejido que recubren los pulmones y la cavidad torácica, dificultando la expansión pulmonar al respirar.", whatIs: { title: "¿Qué es un Derrame Pleural?", text: "Comúnmente llamado 'agua en los pulmones', no es una enfermedad en sí, sino una complicación grave de una enfermedad subyacente. El líquido ejerce una presión mecánica externa sobre el pulmón, comprimiéndolo y causando dolor en el pecho, tos seca y severa falta de aire." }, types: { title: "Clasificación Clínica del Líquido", intro: "Analizar el tipo de líquido extraído es fundamental para hallar la causa:", items: ["Derrame trasudativo (líquido claro y acuoso que se filtra debido a una presión alta en los vasos sanguíneos o bajo nivel de proteínas; típicamente causado por Insuficiencia Cardíaca Congestiva o Cirrosis)", "Derrame exudativo (líquido más espeso, rico en proteínas o pus, producto de inflamación, infecciones o lesiones; causado típicamente por Neumonía, Cáncer, Tuberculosis o afecciones autoinmunes)"], note: "Si el derrame pleural se infecta y contiene pus, se le denomina 'empiema', y requiere drenaje y antibióticos urgentes." }, diagnosis: { title: "Detección y Toracocentesis", intro: "El médico neumólogo lo diagnosticará mediante:", items: ["Auscultación del tórax (el médico notará una disminución del sonido respiratorio y matidez al golpear la espalda del lado afectado)", "Radiografía de tórax (la prueba inicial clásica, que muestra un borramiento blanco en la base del pulmón) y Ecografía torácica (para localizar bolsas de líquido)", "Tomografía Computarizada (TC) de tórax (proporciona un detalle superior de los pulmones y busca tumores o neumonías ocultas)", "Toracocentesis diagnóstica (extracción de una muestra de líquido insertando una aguja a través de la espalda para enviarlo a análisis y determinar su origen)"], note: "" }, treatment: { title: "Drenaje y Tratamiento de la Causa", intro: "El objetivo es extraer el líquido para aliviar la asfixia y curar la enfermedad raíz:", subsections: [ { title: "Procedimientos", items: ["Toracocentesis terapéutica (extracción de grandes volúmenes de líquido con aguja para aliviar instantáneamente la dificultad respiratoria)", "Medicamentos (diuréticos si la causa es insuficiencia cardíaca, o antibióticos fuertes si la causa es una neumonía bacteriana)", "Tubo de tórax (drenaje torácico continuo para derrames infectados o recurrentes que necesitan vaciarse durante días)", "Pleurodesis o cirugía toracoscópica (VATS) (inyección de sustancias químicas en la pleura para pegar las capas y evitar que el líquido vuelva a acumularse, usado comúnmente en derrames cancerosos malignos crónicos)"] } ], note: "El derrame pleural volverá a aparecer rápidamente si no se trata la afección original que lo causó (como el corazón o el cáncer)." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Debes buscar atención en un servicio de urgencias sin demora si presentas:", items: ["Falta de aliento aguda, repentina o severa que empeora rápidamente, especialmente al acostarte", "Dolor en el pecho fuerte o agudo (dolor pleurítico) que empeora intensamente cuando tomas una respiración profunda o cuando toses", "Tos persistente e inexplicable que no produce mucosidad (tos seca), acompañada a veces de fiebre y escalofríos intensos", "Incapacidad para respirar a menos que estés sentado erguido"] } },
'Anomalía dentaria' : { intro: "Una anomalía dentaria abarca cualquier malformación genética, congénita o de desarrollo en los dientes, afectando su número, tamaño, forma, color, estructura o momento de erupción. Son alteraciones frecuentes que a menudo requieren tratamiento interdisciplinario para recuperar la función y la estética.", whatIs: { title: "¿Qué son las Anomalías Dentarias?", text: "Son alteraciones en el ciclo de desarrollo embrionario del diente (odontogénesis). Dependiendo de en qué fase del desarrollo ocurrió el problema (durante la formación de la matriz, la calcificación o la erupción), el diente presentará defectos visuales, funcionales o estructurales permanentes." }, types: { title: "Clasificación de Anomalías", intro: "Se agrupan según la característica del diente que resulta afectada:", items: ["Anomalías de número: Agenesia/Hipodoncia (ausencia genética de dientes), Hiperdoncia o dientes supernumerarios (dientes de más, como el mesiodens)", "Anomalías de tamaño: Microdoncia (dientes inusualmente pequeños, común en incisivos laterales en 'grano de arroz') o Macrodoncia (dientes gigantes)", "Anomalías de forma: Dientes fusionados, geminación, dens in dente o taurodontismo", "Anomalías de estructura: Amelogénesis imperfecta (esmalte dental frágil o ausente), Dentinogénesis imperfecta o hipoplasia del esmalte (manchas severas)"], note: "Suelen ser descubiertas durante la etapa de recambio dental en la niñez." }, diagnosis: { title: "Evaluación Odontológica", intro: "El dentista y ortodoncista diagnostican mediante:", items: ["Exploración clínica intraoral visual detallada", "Radiografías panorámicas (ortopantomografía) y periapicales (para contar los dientes en el hueso, evaluar la forma de las raíces y ver dientes adicionales o faltantes)", "Pruebas genéticas en casos raros donde la anomalía dental es parte de un síndrome mayor (como la displasia ectodérmica)"], note: "" }, treatment: { title: "Restauración, Ortodoncia y Cirugía", intro: "El tratamiento es altamente personalizado según el defecto:", subsections: [ { title: "Opciones de Rehabilitación", items: ["Ortodoncia (para abrir espacios si faltan dientes, o alinear el arco dental tras extracciones)", "Extracción quirúrgica (el tratamiento necesario para los dientes supernumerarios que bloquean la erupción de los dientes normales)", "Restauración estética (uso de carillas de porcelana, coronas o resinas compuestas para reconstruir dientes pequeños (microdoncia) o con esmalte defectuoso)", "Implantes dentales o prótesis (para sustituir las agenesias una vez que el paciente alcanza la edad adulta)"] } ], note: "Tratar alteraciones estructurales como la amelogénesis es vital, ya que el esmalte débil causa hipersensibilidad severa y destrucción rápida del diente." }, whenToSeekHelp: { title: "¿Cuándo consultar al odontopediatra?", intro: "Los padres deben llevar a sus hijos a una revisión dental temprana si observan:", items: ["El niño no ha desarrollado ninguno o muy pocos dientes de leche al año de edad, o faltan dientes definitivos en salir a la edad esperada", "Hay una clara asimetría, con un lado de la boca desarrollando dientes y el otro lado vacío por meses", "Los dientes brotan con un aspecto muy amarillento/marrón, con la superficie llena de surcos, se desmoronan fácilmente o son extremadamente pequeños y puntiagudos", "Aparecen dientes adicionales en lugares inusuales (como detrás de los dientes frontales o en el paladar)"] } },
'Hemorragia cerebral' : { intro: "Una hemorragia cerebral, también conocida como hemorragia intracraneal o ataque cerebral hemorrágico, ocurre cuando un vaso sanguíneo defectuoso o debilitado en el cerebro estalla y sangra, derramando sangre en el tejido cerebral circundante y destruyendo células vitales.", whatIs: { title: "¿Qué es una Hemorragia Cerebral?", text: "Es una emergencia neurológica crítica y letal. La sangre derramada forma una acumulación (hematoma) que aumenta drásticamente la presión dentro del cráneo rígido. Esta presión mecánica y la privación de oxígeno (isquemia) a los tejidos cerebrales adyacentes causan daño neurológico rápido e irreversible." }, types: { title: "Ubicación del Sangrado", intro: "El tipo de hemorragia depende de dónde se rompa el vaso:", items: ["Hemorragia intracerebral (la forma más común de sangrado cerebral, ocurre directamente dentro del propio tejido del cerebro; la causa principal es la presión arterial alta crónica no controlada)", "Hemorragia subaracnoidea (sangrado en el espacio entre el cerebro y los tejidos que lo cubren, típicamente causado por la ruptura de un aneurisma cerebral; famoso por causar el 'peor dolor de cabeza de la vida')", "Hematoma subdural o epidural (sangrado entre el cráneo y el cerebro, casi siempre provocado por un golpe o trauma grave en la cabeza)"], note: "El uso de medicamentos anticoagulantes aumenta dramáticamente el riesgo de hemorragias cerebrales espontáneas severas." }, diagnosis: { title: "Evaluación Crítica de Urgencia", intro: "El diagnóstico debe realizarse en minutos al llegar al hospital:", items: ["Tomografía Computarizada (TC) de cabeza sin contraste (el estudio de oro y el más rápido para detectar inmediatamente la presencia de sangre fresca dentro del cerebro y evaluar el tamaño de la hemorragia)", "Resonancia Magnética (RM) del cerebro y Angiografía por RM (para ver detalles finos o identificar malformaciones arteriovenosas o aneurismas)", "Angiografía cerebral con catéter (inyectar colorante directamente en los vasos del cerebro para localizar la fuente exacta de la rotura antes de operar)"], note: "A diferencia del infarto isquémico, aquí NUNCA se deben administrar medicamentos para disolver coágulos." }, treatment: { title: "Estabilización y Cirugía", intro: "El objetivo es detener el sangrado, reducir la presión intracraneal y prevenir el daño cerebral secundario:", subsections: [ { title: "Intervenciones de Emergencia", items: ["Soporte vital intensivo y control estricto de la presión arterial (para evitar que el vaso siga sangrando)", "Reversión de anticoagulantes (si el paciente tomaba medicamentos para diluir la sangre, se administran antídotos inmediatamente)", "Medicamentos para reducir la hinchazón del cerebro (diuréticos osmóticos como el manitol o medicamentos antiepilépticos para prevenir convulsiones)", "Cirugía (Craneotomía de emergencia para drenar el hematoma acumulado y aliviar la presión sobre el cerebro, o clipaje/embolización endovascular si la causa fue un aneurisma roto)"] } ], note: "La rehabilitación neurológica a largo plazo (física, ocupacional, del lenguaje) es crucial para recuperar las funciones perdidas tras superar el evento." }, whenToSeekHelp: { title: "¿Cuándo llamar a una ambulancia (911)?", intro: "Los síntomas ocurren súbitamente y sin aviso. Pide ayuda de urgencia instantánea si hay:", items: ["Un dolor de cabeza repentino, explosivo y extremadamente intenso (con frecuencia descrito como el peor dolor de cabeza imaginable)", "Parálisis, debilidad aguda o entumecimiento repentino en el rostro, un brazo o una pierna, usualmente en un solo lado del cuerpo", "Dificultad repentina para hablar, pronunciar palabras incomprensibles o no entender a los demás, acompañada de confusión o delirio", "Pérdida de la visión en uno o ambos ojos, dificultad súbita severa para caminar, mareos intensos, pérdida del equilibrio o estado de coma inminente"] } },
'Fibromialgia' : { intro: "La fibromialgia es un trastorno crónico y complejo que se caracteriza por un dolor musculoesquelético generalizado y una profunda fatiga, acompañado a menudo por problemas de sueño, memoria y estado de ánimo. Altera sustancialmente la calidad de vida sin causar daño físico visible en los tejidos.", whatIs: { title: "¿Qué es la Fibromialgia?", text: "Es un síndrome de sensibilización central. Los investigadores creen que la fibromialgia amplifica las sensaciones de dolor porque afecta el modo en que el cerebro y la médula espinal procesan las señales dolorosas y no dolorosas. Básicamente, el 'control de volumen' del dolor en el cerebro se queda atascado en un nivel alto." }, types: { title: "Síntomas Clave (La Tríada)", intro: "La presentación clásica incluye tres problemas principales:", items: ["Dolor generalizado severo (un dolor sordo continuo que dura meses, presente en ambos lados del cuerpo y por encima y por debajo de la cintura)", "Fatiga profunda o agotamiento crónico (los pacientes se despiertan cansados, aunque informan haber dormido mucho tiempo, y el sueño suele interrumpirse por el dolor)", "Dificultades cognitivas o 'fibroniebla' ('fibrofog': deterioro de la capacidad para enfocarse, prestar atención y concentrarse mentalmente)"], note: "Suele coexistir con otras condiciones dolorosas como el síndrome del intestino irritable, la migraña o los trastornos de la articulación temporomandibular (ATM)." }, diagnosis: { title: "Diagnóstico Clínico", intro: "No existe una prueba de laboratorio o escáner que pueda confirmar la fibromialgia; es un diagnóstico clínico:", items: ["Historial médico minucioso basado en los criterios del Colegio Americano de Reumatología (presencia de dolor generalizado durante más de tres meses en múltiples áreas específicas del cuerpo)", "Análisis de sangre y pruebas reumatológicas (utilizadas estrictamente para descartar otras enfermedades con síntomas similares, como hipotiroidismo, artritis reumatoide, lupus o polimialgia reumática)", "Evaluación de la gravedad de los síntomas somáticos, la fatiga y los problemas cognitivos acompañantes"], note: "Las personas con fibromialgia se ven saludables por fuera, lo que a menudo lleva a que otros minimicen su dolor." }, treatment: { title: "Manejo Multimodal", intro: "No existe cura, pero los síntomas se pueden manejar combinando medicación y autocuidado activo:", subsections: [ { title: "Opciones Terapéuticas", items: ["Ejercicio aeróbico gradual y constante (caminar, natación, yoga, taichí; es el tratamiento no farmacológico más eficaz respaldado por la ciencia, aunque deba empezarse muy lentamente)", "Medicamentos analgésicos neuromoduladores (Pregabalina, Gabapentina o Duloxetina, que actúan en el cerebro para reducir los nervios hiperactivos y mejorar el sueño)", "Analgésicos de venta libre (el paracetamol puede ayudar, pero los AINEs clásicos como el ibuprofeno, e incluso los opioides, suelen ser ineficaces para el dolor de la fibromialgia)", "Terapia Cognitivo-Conductual (TCC) o terapia de apoyo (para aprender técnicas de manejo del estrés, afrontamiento del dolor crónico y mejora de la higiene del sueño)"] } ], note: "Reducir el estrés vital y mantener un ritmo de actividad equilibrado (sin sobreesforzarse en los días buenos) es crucial." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable solicitar una evaluación reumatológica o de medicina general si:", items: ["Padeces un dolor muscular y articular constante que se extiende por todo tu cuerpo y dura más de tres meses, sin razón aparente", "Sientes un agotamiento extremo que no mejora con el descanso ni durmiendo y que te impide realizar tus actividades laborales o de ocio habituales", "Experimentas problemas notables de concentración mental ('niebla mental') junto con el dolor crónico", "Te sientes deprimido, ansioso o incomprendido debido al impacto del dolor constante en tu rutina"] } },
'Síndrome del colon irritable (IBS)' : { intro: "El síndrome de colon irritable (o SCI / IBS por sus siglas en inglés) es un trastorno común que afecta el estómago y los intestinos, conocidos en conjunto como el tracto gastrointestinal. Es un trastorno funcional, lo que significa que el intestino se ve normal pero no funciona correctamente.", whatIs: { title: "¿Qué es el Síndrome de Colon Irritable?", text: "Es un síndrome crónico caracterizado por calambres abdominales, dolor, gases, distensión abdominal y cambios en los hábitos intestinales. El sistema nervioso que controla el intestino (eje intestino-cerebro) reacciona de manera exagerada a estímulos normales, causando espasmos y problemas de motilidad sin evidencia de daño estructural." }, types: { title: "Subtipos según las Heces", intro: "El tratamiento se guía por el patrón intestinal predominante:", items: ["IBS-D (con predominio de diarrea: heces sueltas y acuosas frecuentes, a menudo con urgencia extrema para evacuar)", "IBS-C (con predominio de estreñimiento: heces duras o grumosas, evacuaciones poco frecuentes y sensación de evacuación incompleta)", "IBS-M (mixto: alternancia impredecible entre episodios de diarrea y episodios de estreñimiento)"], note: "El estrés psicológico y ciertos alimentos son los desencadenantes más poderosos, pero no son la causa de la enfermedad." }, diagnosis: { title: "Evaluación y Criterios Clínicos", intro: "Se diagnostica fundamentalmente descartando otras enfermedades graves:", items: ["Criterios de Roma IV (dolor abdominal recurrente, al menos 1 día a la semana en los últimos 3 meses, asociado con la defecación y con un cambio en la frecuencia o forma de las heces)", "Análisis de heces y sangre (para descartar infección, parásitos, enfermedad celíaca o problemas de tiroides)", "Colonoscopia o endoscopia (generalmente recomendada solo en pacientes mayores de 50 años o si hay 'señales de alarma' como pérdida de peso o sangre en heces, para descartar EII o cáncer)"], note: "Al ser un trastorno funcional, la colonoscopia y las biopsias de un paciente con IBS resultarán perfectamente normales." }, treatment: { title: "Manejo Dietético y Médico", intro: "El objetivo es aliviar los síntomas, y el tratamiento es altamente individualizado:", subsections: [ { title: "Estrategias de Control", items: ["Modificaciones dietéticas severas (implementación de la dieta baja en FODMAPs guiada por un nutricionista, evitar gluten, lactosa, cafeína o alimentos que producen gases)", "Uso de fibra soluble (como el psyllium) para regular tanto el estreñimiento como la diarrea leve", "Medicamentos antiespasmódicos (para aliviar los cólicos abdominales) y laxantes o antidiarreicos específicos (como la Loperamida) según el subtipo de IBS", "Antidepresivos o neuromoduladores en dosis bajas (para calmar los nervios del intestino e interrumpir las señales de dolor al cerebro)", "Terapias psicológicas (Terapia Cognitivo-Conductual, hipnoterapia dirigida al intestino o manejo activo del estrés crónico)"] } ], note: "Llevar un diario de síntomas y alimentos es la herramienta más valiosa para identificar y eliminar los detonantes personales." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes buscar evaluación médica si tus hábitos intestinales han cambiado persistentemente, o de forma URGENTE si presentas 'síntomas de alarma' (que NO son causados por el IBS):", items: ["Pérdida de peso repentina, rápida y sin esfuerzo aparente", "Sangrado rectal activo o encontrar heces oscuras, negras y alquitranadas", "Diarrea que interrumpe tu sueño y te despierta habitualmente en medio de la noche", "Fiebre inexplicada constante, vómitos repetitivos, o dificultad severa para tragar", "Anemia por deficiencia de hierro descubierta en un análisis de rutina"] } },
'Gastroenteritis bacteriana con diarrea infecciosa' : { intro: "La gastroenteritis bacteriana es una inflamación e infección del intestino causada por la presencia de bacterias patógenas, típicamente a través del consumo de alimentos en mal estado o agua contaminada (intoxicación alimentaria). Produce episodios graves y fulminantes de diarrea infecciosa y síntomas digestivos agudos.", whatIs: { title: "¿Qué es la Gastroenteritis Bacteriana?", text: "A diferencia de la gripe estomacal viral común, esta forma ocurre cuando las bacterias colonizan directamente la mucosa del tracto gastrointestinal o producen toxinas nocivas en él. El cuerpo responde con fuertes espasmos musculares y secretando cantidades masivas de líquido para 'lavar' la bacteria hacia fuera, causando la diarrea." }, types: { title: "Bacterias Causantes Comunes", intro: "Dependiendo de la bacteria, la severidad de la infección varía enormemente:", items: ["Salmonella y Campylobacter (causas muy comunes por aves de corral crudas/poco cocinadas o huevos)", "Escherichia coli (E. coli, especialmente cepas productoras de toxina Shiga que pueden causar daño renal severo, a menudo de carne molida o verduras crudas contaminadas)", "Staphylococcus aureus y Shigella (causan brotes severos de diarrea disentérica con sangre)", "Clostridioides difficile (C. diff) (infección bacteriana grave y peligrosa en el colon, típicamente adquirida tras un tratamiento prolongado con antibióticos en un hospital)"], note: "El período de incubación puede variar desde unas pocas horas (toxinas) hasta varios días después de consumir el alimento." }, diagnosis: { title: "Diagnóstico Médico y Laboratorio", intro: "Si la diarrea es severa y prolongada, el médico tratará de identificar al patógeno específico:", items: ["Coprocultivo y pruebas de panel de patógenos gastrointestinales (análisis de una muestra de heces para cultivar la bacteria exacta que causa la infección y detectar sus toxinas)", "Examen físico para buscar signos de deshidratación grave (como letargo, taquicardia o hipotensión)", "Análisis de sangre para verificar los niveles de electrolitos y función renal, especialmente en niños o ancianos"], note: "Las diarreas bacterianas suelen ser más graves, prolongadas y más propensas a causar fiebre alta o sangre en las heces que las virales." }, treatment: { title: "Soporte Hídrico y Antibióticos", intro: "El tratamiento primario es la reposición de líquidos; los medicamentos dependen de la bacteria:", subsections: [ { title: "Opciones Terapéuticas", items: ["Rehidratación intensiva (sales de rehidratación oral constantes, y en casos severos, fluidos intravenosos en el hospital para prevenir un shock hipovolémico)", "Antibióticos específicos (solo se prescriben para ciertas bacterias como Shigella o en casos de C. diff; NO se recomiendan rutinariamente para salmonella leve o ciertas E. coli, ya que pueden empeorar complicaciones)", "Evitar estrictamente los medicamentos antidiarreicos de venta libre (como Loperamida) sin orden médica, ya que impedir la evacuación retiene la bacteria y sus toxinas en el cuerpo, agravando severamente la infección", "Dieta BRAT (plátanos, arroz, compota de manzana y tostadas) una vez que el estómago pueda tolerar los alimentos sólidos"] } ], note: "La higiene rigurosa (lavado de manos) es vital, ya que estas bacterias son altamente contagiosas por vía fecal-oral." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Se requiere atención médica urgente y presencial (Urgencias) si presentas:", items: ["Heces mezcladas con gran cantidad de moco o de sangre roja visible y abundante (disentería)", "Diarrea intensa que dura más de dos o tres días, o incapacidad absoluta de retener ningún líquido en el estómago por 24 horas", "Fiebre persistentemente alta, superior a 39 °C (102 °F)", "Signos críticos de deshidratación (mareo severo, debilidad extrema, confusión, ausencia total de orina o boca muy seca y pastosa)"] } },
'Intolerancia a la lactosa' : { intro: "La intolerancia a la lactosa es un trastorno digestivo muy frecuente caracterizado por la incapacidad de digerir la lactosa, el tipo de azúcar que se encuentra principalmente en la leche y los productos lácteos. A diferencia de una alergia, no es una condición peligrosa para la vida, pero puede ser sumamente incómoda.", whatIs: { title: "¿Qué es la Intolerancia a la Lactosa?", text: "Es una condición causada por la deficiencia de lactasa, una enzima producida en el intestino delgado. Cuando hay muy poca lactasa, la lactosa no digerida pasa entera al colon (intestino grueso), donde las bacterias intestinales normales interactúan con ella y la fermentan, creando gases intensos y ácidos que provocan molestias digestivas agudas." }, types: { title: "Tipos de Deficiencia", intro: "La falta de lactasa puede originarse por diversas razones:", items: ["Intolerancia primaria a la lactosa (la causa más común, dictada por la genética; la producción de lactasa disminuye naturalmente y de forma permanente en la edad adulta después de que termina el destete)", "Intolerancia secundaria a la lactosa (la producción disminuye temporalmente debido a una enfermedad intestinal, como la celiaquía, una gastroenteritis aguda o la enfermedad de Crohn; suele mejorar cuando la condición se cura)", "Intolerancia congénita o del desarrollo (un trastorno autosómico recesivo extremadamente raro en el que los bebés nacen con una ausencia total de lactasa, siendo intolerantes a la leche materna)"], note: "Es muy común en poblaciones de ascendencia asiática, africana, nativa americana e hispana." }, diagnosis: { title: "Detección Clínica", intro: "Si los síntomas son evidentes, los médicos pueden confirmarlo con pruebas específicas:", items: ["Prueba de aliento de hidrógeno (la prueba estándar más precisa; la persona bebe un líquido con alta cantidad de lactosa y se mide el hidrógeno exhalado, que estará elevado si la lactosa no se digiere y se fermenta en el colon)", "Prueba de tolerancia a la lactosa en sangre (mide la glucosa en sangre tras ingerir lactosa; si la glucosa no sube, significa que el cuerpo no descompuso el azúcar lácteo)", "Examen de acidez en las heces (frecuentemente usado en bebés y niños pequeños) o simple dieta de eliminación seguida de reintroducción guiada de lácteos"], note: "" }, treatment: { title: "Manejo Dietético", intro: "No existe cura para aumentar la producción natural de lactasa, pero el control es sumamente sencillo y efectivo:", subsections: [ { title: "Estrategias de Control", items: ["Reducción o eliminación de lácteos en la dieta (buscar alternativas como leche de soja, almendra, avena o arroz, asegurando una ingesta adecuada de calcio y vitamina D)", "Consumo de productos sin lactosa o deslactosados (que ya vienen pretratados con la enzima lactasa)", "Uso de suplementos enzimáticos de lactasa de venta libre (tomar pastillas o gotas de lactasa justo antes de ingerir una comida que contenga lácteos para ayudar al intestino a digerirlos)", "Introducción de porciones muy pequeñas (muchas personas con esta condición pueden tolerar mínimas cantidades de leche entera con las comidas, o consumir quesos duros curados y yogures naturales que tienen cantidades residuales muy bajas de lactosa)"] } ], note: "Es crucial no confundir la intolerancia a la lactosa (un problema digestivo de azúcares) con la alergia a la proteína de la leche (un problema del sistema inmunológico grave)." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable pedir una evaluación clínica si:", items: ["Experimentas hinchazón dolorosa, calambres estomacales y diarrea explosiva entre 30 minutos y dos horas después de comer productos lácteos, y esto es frecuente", "Los síntomas no mejoran después de eliminar rigurosamente toda la lactosa de tu dieta (lo que indicaría otra afección como SII o celiaquía)", "Te preocupa no obtener suficiente calcio debido a tu estricta aversión y evitación de los productos lácteos"] } },
'Prolapso uterino' : { intro: "El prolapso uterino ocurre cuando los músculos y ligamentos del suelo pélvico de una mujer se estiran, se debilitan y ya no proporcionan suficiente soporte vital al útero. Como consecuencia, el útero resbala y cae hacia el canal vaginal, pudiendo asomar fuera del cuerpo en casos graves.", whatIs: { title: "¿Qué es el Prolapso Uterino?", text: "Es una forma de disfunción del suelo pélvico, como una 'hernia' de los órganos femeninos. Cuando la red de soporte falla, el útero desciende (prolapsa) de su posición anatómica natural hacia la vagina, creando una sensación de pesadez o la percepción incómoda de que 'algo se está cayendo' de la pelvis." }, types: { title: "Estadios de Gravedad", intro: "Los ginecólogos clasifican la caída del útero en etapas para planificar el tratamiento:", items: ["Grado 1: El útero desciende solo un poco en la parte superior de la vagina.", "Grado 2: El cuello del útero cae y llega hasta la abertura de la vagina.", "Grado 3: El cuello del útero sobresale y asoma por fuera del orificio vaginal.", "Grado 4 (Procidentia): El útero entero se asoma completamente fuera de la vagina."], note: "Suele estar provocado por múltiples partos vaginales traumáticos o difíciles, la falta de estrógeno tras la menopausia, el envejecimiento y el aumento crónico de la presión abdominal (tos crónica, estreñimiento severo, obesidad)." }, diagnosis: { title: "Evaluación Ginecológica", intro: "El diagnóstico se basa en la queja de la paciente y en un examen físico:", items: ["Examen pélvico físico (generalmente mientras la paciente está acostada y luego de pie, y se le pide que haga esfuerzo como si fuera a defecar para evaluar hasta dónde desciende el útero)", "Cuestionarios médicos especializados (para medir cómo el prolapso afecta la calidad de vida diaria y la función sexual, intestinal o urinaria)", "En raras ocasiones, ecografías o estudios urodinámicos (si el prolapso interfiere severamente con la capacidad de orinar o está asociado a un cistocele, prolapso de vejiga)"], note: "" }, treatment: { title: "Ejercicios, Soportes o Cirugía", intro: "El manejo va desde lo más conservador hasta lo quirúrgico, dependiendo exclusivamente de la molestia que le cause a la mujer:", subsections: [ { title: "Opciones Terapéuticas", items: ["Medidas conservadoras y Fisioterapia Pélvica (para grados leves o asintomáticos, realizar Ejercicios de Kegel intensivos diarios guiados por un experto y perder peso)", "Pesario vaginal (un dispositivo o anillo de silicona removible insertado en la vagina por un médico, que empuja y sostiene físicamente el útero en su lugar; requiere limpieza regular)", "Cirugía reconstructiva del suelo pélvico (laparoscópica o por vagina, para suspender y volver a fijar el útero a los ligamentos pélvicos fuertes con o sin mallas sintéticas)", "Histerectomía vaginal (cirugía para extirpar el útero de forma definitiva; a menudo sugerida en casos de procidentia grave o si no hay deseo de conservar el útero)"] } ], note: "Los estrógenos vaginales tópicos pueden ayudar a fortalecer y mejorar la salud de los tejidos vaginales y prevenir úlceras en mujeres posmenopáusicas con uso de pesario." }, whenToSeekHelp: { title: "¿Cuándo acudir al ginecólogo?", intro: "Debes buscar tratamiento médico para mejorar tu calidad de vida si:", items: ["Sientes una presión constante, pesadez profunda o tracción hacia abajo en la pelvis o la zona lumbar, como si estuvieras 'sentada sobre una pelota pequeña'", "Puedes ver o palpar tejido o un bulto asomando fuera de tu vagina, el cual sangra o presenta úlceras por el roce con la ropa interior", "Sufres dificultades constantes con el control de tus esfínteres (fugas de orina o heces, o necesidad de empujar el bulto vaginal hacia arriba para lograr orinar o evacuar por completo)", "Experimentas dolor o mucha dificultad e incomodidad al mantener relaciones sexuales"] } },
'Aflicción' : { intro: "La aflicción es la reacción emocional universal y natural ante una pérdida significativa. Aunque a menudo se usa como sinónimo de duelo (por la muerte de un ser querido), la aflicción también abarca la tristeza profunda resultante de divorcios, pérdida de salud, desempleo o cambios vitales drásticos.", whatIs: { title: "¿Qué es la Aflicción?", text: "Es un estado psicológico y emocional de sufrimiento profundo. Representa el proceso interno que la persona experimenta al enfrentarse a la separación definitiva de un vínculo importante. No es un estado patológico ni una enfermedad mental, sino una experiencia humana necesaria de adaptación y reajuste ante el dolor." }, types: { title: "Manifestaciones Clínicas", intro: "La aflicción no es solo tristeza, afecta a la persona en su totalidad:", items: ["Manifestaciones emocionales (choque inicial, incredulidad, llanto incontrolable, culpa persistente, enojo hacia otros, apatía profunda y añoranza intensa)", "Manifestaciones físicas (fatiga paralizante, opresión en el pecho, nudo en la garganta, insomnio marcado, pérdida o aumento drástico de apetito, náuseas)", "Manifestaciones cognitivas y conductuales (dificultad severa para concentrarse o tomar decisiones simples, aislamiento social, soñar vívidamente con lo perdido)"], note: "Se suele teorizar en etapas (negación, ira, negociación, depresión y aceptación), aunque no son lineales ni toda persona las experimenta igual." }, diagnosis: { title: "Diferenciación de la Depresión Clínica", intro: "Generalmente no requiere un diagnóstico médico formal, salvo para descartar complicaciones:", items: ["Evaluación clínica psiquiátrica (se utiliza para distinguir la aflicción normal de la Depresión Mayor; en la aflicción, el dolor suele venir en 'olas' asociadas a recuerdos, mientras la autoestima permanece intacta; en la depresión clínica, el ánimo bajo es constante, corrosivo e incluye sentimientos de inutilidad o autodesprecio)", "Identificación del Trastorno de Duelo Prolongado (si la aflicción intensa, incapacitante e invalidante persiste sin mejora alguna durante más de un año, impidiendo rehacer la vida cotidiana)"], note: "" }, treatment: { title: "Acompañamiento y Resiliencia", intro: "La aflicción no se 'cura' con medicamentos, sino que se procesa, integra y acomoda en la vida del individuo:", subsections: [ { title: "Estrategias de Apoyo", items: ["Autocuidado básico, rutinas flexibles, tiempo y paciencia personal extrema (permitirse sentir la tristeza sin suprimirla artificialmente)", "Asesoramiento de duelo o Psicoterapia (ayuda a la persona a trabajar a través de bloqueos emocionales, culpa infundada o tareas de duelo complejas sin olvidar al ser querido o la pérdida)", "Participación activa en grupos de apoyo de duelo (compartir la experiencia con otras personas en la misma situación es uno de los recursos terapéuticos más poderosos)", "Intervenciones psiquiátricas muy puntuales (medicación ocasional y temporal para el insomnio severo o la ansiedad aguda desbordante, siempre bajo control estricto)"] } ], note: "Obligar a una persona afligida a 'seguir adelante rápidamente' o 'superarlo' puede estancar el proceso natural de sanación y causar duelo retardado." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda terapéutica profesional?", intro: "La tristeza es normal, pero debes buscar apoyo psicológico o psiquiátrico urgente si experimentas:", items: ["Sentimientos constantes y activos de no querer seguir vivo, deseos de morir para reunirte con el fallecido, o planes de suicidio", "Un sentimiento extremo de culpa por cosas no relacionadas directamente con la pérdida o la creencia obsesiva y paralizante de que eres responsable directo de la muerte o el evento trágico", "Incapacidad total y absoluta para reanudar tus tareas básicas diarias (comer, asearte, cuidar de tus hijos o ir al trabajo) muchos meses después de la pérdida", "Aparición de alucinaciones (escuchar o ver cosas reales no relacionadas con breves ilusiones transitorias de ver al difunto)"] } },
'Cálculos renales' : { intro: "Los cálculos renales, también llamados nefrolitiasis o piedras en los riñones, son depósitos duros de minerales y sales que se forman dentro del riñón y cristalizan. Su paso a través del tracto urinario es famoso por causar uno de los dolores más severos e intensos que puede experimentar el ser humano.", whatIs: { title: "¿Qué son los Cálculos Renales?", text: "Se forman cuando la orina se vuelve muy concentrada, permitiendo que los minerales (como el calcio y el ácido úrico) cristalicen y se peguen entre sí, formando 'piedras' sólidas en lugar de ser expulsados de forma líquida. Si son diminutas, pueden salir sin síntomas; si crecen, pueden obstruir peligrosamente el uréter." }, types: { title: "Tipos por Composición", intro: "Analizar de qué está hecha la piedra ayuda a determinar su causa subyacente:", items: ["Cálculos de calcio (por mucho, los más comunes, frecuentemente compuestos de oxalato de calcio, ligado a la dieta, sudoración extrema y poco consumo de agua)", "Cálculos de ácido úrico (se forman a menudo en personas que no beben suficientes líquidos, pierden mucho líquido o consumen una dieta muy alta en purinas animales)", "Cálculos de estruvita (se forman casi exclusivamente como reacción a infecciones crónicas del tracto urinario; pueden crecer rápidamente y volverse muy grandes, como 'astas de ciervo')", "Cálculos de cistina (un tipo raro hereditario, donde el riñón secreta demasiados aminoácidos de cistina)"], note: "No beber suficiente agua diariamente es el factor de riesgo universal número uno para su formación." }, diagnosis: { title: "Evaluación Médica de Urgencia", intro: "Durante un episodio de dolor agudo (cólico nefrítico), el médico confirmará la piedra mediante:", items: ["Tomografía Computarizada (TC) de abdomen y pelvis sin contraste (es el estándar de oro médico moderno, pues localiza incluso las piedras más pequeñas y bloqueos del uréter en segundos)", "Ecografía (muy útil en embarazadas, niños o para evitar radiación, para observar la dilatación del riñón por el bloqueo de orina)", "Análisis de orina (para detectar cristales microscópicos, glóbulos rojos o sangre oculta y buscar infecciones asociadas)", "Análisis de sangre para chequear niveles muy altos de ácido úrico, calcio o infección generalizada (glóbulos blancos elevados)"], note: "A los pacientes a menudo se les da un filtro o colador para orinar en casa e intentar 'atrapar' la piedra para enviarla al laboratorio." }, treatment: { title: "Expulsión o Extracción", intro: "Depende del tamaño de la piedra y del dolor o daño que esté causando:", subsections: [ { title: "Opciones de Tratamiento", items: ["Manejo conservador para piedras pequeñas (<5mm): Beber muchísima agua (hasta 3 litros), usar analgésicos fuertes para soportar el paso doloroso de la piedra, y usar fármacos bloqueadores alfa (como la Tamsulosina) para relajar el conducto uretral y expulsarla", "Litotricia extracorpórea por ondas de choque (LEOC) (ondas sonoras intensas que rompen las piedras renales grandes en pequeños trozos similares a arena que pueden orinarse)", "Ureteroscopia (se pasa un tubo súper delgado iluminado y equipado por la uretra y vejiga para llegar al uréter, donde atrapa o rompe la piedra con rayo láser, sin hacer cortes externos)", "Nefrolitotomía percutánea (para piedras extremadamente grandes, extracción quirúrgica mediante un pequeño corte en la zona lumbar de la espalda)"] } ], note: "Para evitar recurrencias, la prevención a largo plazo (cambios en dieta y mucha hidratación) es esencial tras cualquier tratamiento." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Deberías acudir sin demora a urgencias hospitalarias si presentas:", items: ["Un dolor súbito y tan extremadamente punzante o desgarrador en la zona lateral de la espalda baja o inferior del abdomen que no te permite quedarte quieto en ninguna posición", "Dolor cólico severo que viene acompañado de náuseas agudas, incontrolables y vómitos repetidos", "Fiebre alta, sudor frío y escalofríos intensos junto al dolor lumbar (esto indica fuertemente que hay una infección bacteriana bloqueada detrás de la piedra, lo cual es una emergencia potencialmente letal)", "Sangre muy visible, roja oscura o rosada en la orina (hematuria macroscópica) o incapacidad total para vaciar la vejiga"] } },
'Estrabismo' : { intro: "El estrabismo, a menudo conocido como 'ojos bizcos' o 'bizquera', es un trastorno visual en el que los ojos no están alineados correctamente y apuntan en diferentes direcciones. Un ojo puede mirar directamente hacia adelante, mientras que el otro se desvía hacia adentro, afuera, arriba o abajo.", whatIs: { title: "¿Qué es el Estrabismo?", text: "Es una afección resultante del desequilibrio neuromuscular o la falta de coordinación en los seis músculos extraoculares que controlan el movimiento del ojo y lo mantienen fijo. Como los ojos no apuntan al mismo objeto al mismo tiempo, el cerebro recibe dos imágenes diferentes, lo que genera confusión visual severa." }, types: { title: "Clasificación de las Desviaciones", intro: "Se nombra comúnmente según la dirección en que gira el ojo desalineado:", items: ["Endotropia o esotropia (el ojo se desvía o cruza hacia adentro, hacia la nariz; es el tipo más común en bebés)", "Exotropia (el ojo se desvía hacia afuera, alejándose de la nariz, a menudo notorio al enfocar objetos lejanos o cuando el niño está cansado)", "Hipertropia (el ojo se desvía anormalmente hacia arriba)", "Hipotropia (el ojo se desvía hacia abajo)"], note: "En un niño pequeño en desarrollo, el cerebro a menudo ignora o 'suprime' la imagen del ojo desviado para evitar ver doble, lo que, de no tratarse, causa ceguera parcial permanente en ese ojo (ambliopía u ojo vago)." }, diagnosis: { title: "Evaluación Oftalmológica Infantil", intro: "El diagnóstico temprano, antes de los 6 años, es crítico para la recuperación visual. El oftalmólogo pediátrico empleará:", items: ["Prueba del reflejo de luz corneal (Test de Hirschberg) (una linterna brilla en los ojos para ver si el reflejo cae en la misma posición central en ambas pupilas)", "Prueba de oclusión o cover-uncover test (se tapa y destapa un ojo alternativamente mientras el niño mira un objeto, observando si el ojo descubierto hace un movimiento correctivo o salta para tratar de enfocar)", "Examen completo de agudeza visual y refracción dilatando las pupilas del niño (muchos casos de endotropia en niños son causados por una miopía o hipermetropía severa no corregida)"], note: "No todos los cruces de ojos son estrabismo; algunos bebés tienen 'pseudoestrabismo', una ilusión óptica causada por un pliegue de piel ancho sobre el lado nasal del ojo, que se supera al crecer." }, treatment: { title: "Corrección Visual y Muscular", intro: "El objetivo del tratamiento es mejorar la alineación ocular, restaurar la visión binocular normal y prevenir o tratar la ambliopía:", subsections: [ { title: "Opciones Terapéuticas", items: ["Anteojos recetados o lentes prismáticos (suelen ser el primer tratamiento principal y, en muchos casos de 'estrabismo acomodativo', unas gafas que corrijan la hipermetropía extrema son suficientes para enderezar el ojo desviado)", "Terapia de parche (se coloca un parche sobre el ojo bueno, o 'fuerte', obligando y forzando al ojo desviado y débil a trabajar más y fortalecer sus conexiones cerebrales)", "Ejercicios musculares y visuales ortópticos (terapia visual para ciertas formas de exotropia intermitente)", "Cirugía de los músculos extraoculares (para los casos que no mejoran con gafas; el cirujano oftalmológico corta, tensa o afloja músculos específicos del ojo bajo anestesia para realinear los globos oculares mecánicamente)"] } ], note: "El estrabismo no se 'cura solo' al crecer, y un retraso en el tratamiento infantil significa una pérdida visual irremediable en la edad adulta." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar al especialista?", intro: "Es fundamental buscar una evaluación pediátrica oftalmológica rigurosa si:", items: ["Observas que los ojos de tu hijo no se mueven de forma coordinada, cruzan hacia la nariz, o un ojo vaga hacia afuera después de los 3-4 meses de edad (los bebés recién nacidos pueden desviar la mirada esporádicamente de forma normal, pero a los 4 meses debe fijarse)", "El niño entrecierra constantemente un ojo ante la luz solar brillante o inclina y gira repetidamente la cabeza en posiciones extrañas para mirar un libro o la televisión", "Tú, como adulto, experimentas la aparición repentina e inédita de visión doble constante o estrabismo (esto es una urgencia neurológica 'bandera roja' y puede indicar un accidente cerebrovascular, un tumor cerebral maligno, problemas de tiroides o aneurismas)"] } },
'Bulímia' : { intro: "La bulimia nerviosa es un trastorno de la alimentación grave y potencialmente fatal caracterizado por episodios secretos de atracones seguidos de métodos para evitar el aumento de peso, como el vómito autoinducido.", whatIs: { title: "¿Qué es la Bulimia Nerviosa?", text: "Es un trastorno psicológico y alimentario donde la persona ingiere grandes cantidades de comida en poco tiempo, sintiendo pérdida de control, para luego purgarse debido a la culpa y el miedo a engordar." }, types: { title: "Tipos de Comportamiento", intro: "Se divide principalmente en:", items: ["Purgativa (uso de vómitos, laxantes o diuréticos)", "No purgativa (uso de ayuno estricto o ejercicio excesivo para compensar)"], note: "El ciclo de atracón y purga puede ocurrir varias veces a la semana o al día." }, diagnosis: { title: "Diagnóstico", intro: "Un especialista evaluará:", items: ["Examen físico y dental (el ácido del estómago daña el esmalte)", "Análisis de sangre para detectar desequilibrios electrolíticos", "Evaluación psicológica según los criterios del DSM-5"], note: "Las personas con bulimia suelen tener un peso normal o ligero sobrepeso, lo que dificulta su detección." }, treatment: { title: "Tratamiento", intro: "Requiere un enfoque de equipo:", subsections: [ { title: "Opciones", items: ["Psicoterapia (Terapia Cognitivo-Conductual es la más efectiva)", "Antidepresivos (como la fluoxetina)", "Educación nutricional para establecer hábitos saludables"] } ], note: "El tratamiento temprano aumenta las posibilidades de recuperación a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Es urgente buscar apoyo si:", items: ["Sientes que no puedes dejar de comer y luego te purgas", "Tienes mareos constantes, palpitaciones o dolor en el pecho", "Tu vida gira obsesivamente en torno a la comida y el peso"] } },
'Apnea del sueño' : { intro: "La apnea del sueño es un trastorno del sueño potencialmente grave en el que la respiración se detiene y comienza repetidamente durante el descanso nocturno. La forma más común es la obstructiva, que fragmenta el sueño y priva al cuerpo del oxígeno necesario.", whatIs: { title: "¿Qué es la Apnea del Sueño?", text: "Es una alteración respiratoria. En la Apnea Obstructiva, los músculos de la garganta colapsan relajadamente y bloquean el paso del aire. En la Apnea Central, el cerebro olvida enviar la señal a los músculos para que respiren. Ambas provocan microdespertares agobiantes." }, types: { title: "Tipos Principales", intro: "Se clasifica por su origen neurológico o anatómico:", items: ["Apnea Obstructiva del Sueño (AOS) (el tipo más frecuente, causado por un bloqueo físico de las vías aéreas por tejido blando)", "Apnea Central del Sueño (un fallo en el centro de control respiratorio del cerebro; común en pacientes con problemas cardíacos graves o secuelas de ACV)", "Síndrome de Apnea del Sueño Compleja (una mezcla donde los pacientes desarrollan apnea central mientras reciben tratamiento para la obstructiva)"], note: "La obesidad masiva y el cuello ancho son los factores de riesgo anatómico más altos para la forma obstructiva." }, diagnosis: { title: "Evaluación y Estudios del Sueño", intro: "El especialista en medicina del sueño es vital para diagnosticarla:", items: ["Polisomnografía en laboratorio (el estudio nocturno completo que mide ondas cerebrales, oxígeno en sangre, ritmo cardíaco, y esfuerzo respiratorio)", "Monitorización portátil en casa (un kit simplificado para casos muy probables de apnea obstructiva clásica)", "Examen otorrinolaringológico (para buscar pólipos, amígdalas gigantes o tabiques desviados)"], note: "" }, treatment: { title: "Soporte Respiratorio", intro: "El objetivo es mantener abiertas las vías aéreas o regular el cerebro:", subsections: [ { title: "Dispositivos y Hábitos", items: ["Presión Positiva Continua en las Vías Respiratorias o CPAP (una máquina con mascarilla que empuja aire comprimido para evitar el colapso de la garganta; es el 'estándar de oro')", "Dispositivos de avance mandibular (férulas bucales hechas por dentistas para adelantar la mandíbula y ensanchar la garganta)", "Pérdida de peso radical y dejar de fumar", "Cirugía maxilofacial o de garganta (UPPP) (en casos seleccionados de anomalías anatómicas crónicas que no toleran la CPAP)"] } ], note: "Sin tratamiento crónico, el riesgo de desarrollar hipertensión refractaria o un ataque cardíaco inminente es altísimo." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Tú o tu pareja debéis estar atentos y consultar si presentas:", items: ["Ronquidos extremadamente ruidosos y perturbadores, que son interrumpidos por largos silencios seguidos de jadeos, asfixia repentina o bufidos abruptos", "Somnolencia y agotamiento diurno tan extremo e invalidante que te duermes trabajando, viendo televisión o mientras conduces", "Despertares matutinos frecuentes con dolores de cabeza muy fuertes, boca muy reseca o un estado de ánimo irritable y deprimido crónico"] } },
'Trastorno por atracón' : { intro: "El trastorno por atracón (TPA) es el trastorno de la conducta alimentaria más común. Se caracteriza por episodios frecuentes en los que se consume una cantidad inusualmente grande y excesiva de alimentos, sintiendo una falta absoluta de control durante el evento.", whatIs: { title: "¿Qué es el Trastorno por Atracón?", text: "A diferencia de la bulimia, las personas con este trastorno psiquiátrico no se purgan regularmente, no vomitan ni hacen ejercicio excesivo en un intento por 'compensar' o deshacer las calorías del atracón. Por lo tanto, el trastorno suele conducir al sobrepeso extremo o la obesidad." }, types: { title: "Características de los Episodios", intro: "Se diagnostica cuando los atracones ocurren al menos una vez a la semana durante 3 meses, caracterizados por:", items: ["Comer mucho más rápido de lo normal y hasta sentirse incómodamente e incluso dolorosamente lleno", "Ingerir grandes cantidades de comida cuando no se siente hambre física", "Comer solo o a escondidas debido a los sentimientos de profunda vergüenza sobre la cantidad que se ingiere", "Sentirse disgustado con uno mismo, gravemente deprimido o muy culpable inmediatamente después del episodio compulsivo"], note: "Es común que estas personas sufran de ciclos de dietas restrictivas o yo-yo que fracasan y exacerban los atracones." }, diagnosis: { title: "Evaluación Psicológica", intro: "Los médicos y psicólogos utilizan el manual DSM-5 para diagnosticarlo mediante:", items: ["Entrevista clínica detallada y sin prejuicios para abordar los hábitos alimenticios en secreto y la angustia psicológica asociada", "Evaluación médica general y análisis de sangre para detectar complicaciones graves derivadas de la obesidad, como diabetes tipo 2, hipertensión y colesterol alto", "Detección de problemas de salud mental coexistentes, como depresión severa, impulsividad general o trastornos de ansiedad agudos"], note: "" }, treatment: { title: "Manejo Psicoterapéutico y Farmacológico", intro: "El enfoque primario es abordar la relación emocional con la comida antes que la pérdida de peso:", subsections: [ { title: "Estrategias Integrales", items: ["Psicoterapia (La Terapia Cognitivo-Conductual o TCC es la intervención más exitosa y probada; ayuda a identificar los desencadenantes emocionales y desarmar el ciclo del atracón)", "Psicoterapia interpersonal y Terapia dialéctico-conductual (para gestionar el estrés subyacente y las relaciones sociales que provocan los impulsos)", "Medicamentos (Lisdexanfetamina, aprobada por la FDA para moderar los atracones severos al influir en la química cerebral, o antidepresivos inhibidores de la recaptación de serotonina)", "Asesoría nutricional de apoyo (no orientada a dietas restrictivas, sino a la planificación de comidas estructuradas y recuperación de las señales naturales de hambre/saciedad)"] } ], note: "Las dietas estrictas para bajar de peso durante el tratamiento inicial del TPA suelen empeorar irremediablemente los atracones; primero hay que sanar el comportamiento." }, whenToSeekHelp: { title: "¿Cuándo pedir apoyo terapéutico?", intro: "Es altamente recomendable consultar a un profesional de la salud mental especializado en TCA si:", items: ["Te encuentras repetida y compulsivamente comiendo en exceso en secreto hasta enfermarte físicamente, sin poder detener el impulso por pura fuerza de voluntad", "Sientes que tu comportamiento hacia la comida y tu cuerpo controla drásticamente tu vida, tu autoestima y tus emociones diarias", "Usas frecuentemente la comida como tu única y principal estrategia de afrontamiento para manejar el enojo profundo, la tristeza, el aburrimiento o el estrés abrumador"] } },
'Hipoacusia relacionada con la edad' : { intro: "La hipoacusia relacionada con la edad, o presbiacusia, es la pérdida lenta, gradual y progresiva de la audición que ocurre a medida que las personas envejecen. Es una afección extremadamente común, afectando aproximadamente a 1 de cada 3 adultos mayores de 65 años.", whatIs: { title: "¿Qué es la Presbiacusia?", text: "Es un tipo de pérdida auditiva neurosensorial permanente. Se produce debido a la degeneración o muerte paulatina de las delicadas células ciliadas sensoriales microscópicas situadas en lo profundo del oído interno (cóclea), o a cambios en el nervio auditivo que viaja hacia el cerebro." }, types: { title: "Características de la Pérdida Auditiva", intro: "Normalmente presenta los siguientes patrones clínicos distintivos:", items: ["Pérdida de audición bilateral (afecta a ambos oídos casi por igual)", "Incapacidad para escuchar sonidos agudos o de alta frecuencia (como el canto de los pájaros, el timbre del teléfono, o ciertas consonantes como 's', 't', 'k', 'p' y 'f', haciendo que el habla suene murmurada o distorsionada)", "Dificultad extrema para entender conversaciones en entornos muy ruidosos o concurridos (como restaurantes)", "Aparición frecuente de Tinnitus o acúfenos (un zumbido, pitido o zumbido fantasma constante en los oídos)"], note: "Suele pasar desapercibida al principio porque la progresión es muy sutil y lenta." }, diagnosis: { title: "Evaluación Audiológica Exhaustiva", intro: "El especialista, o audiólogo, realizará pruebas para medir la capacidad auditiva exacta y descartar otros problemas:", items: ["Examen físico del oído con otoscopio (para descartar bloqueos físicos y mecánicos reversibles, como un tapón de cera gigante o una infección en el oído medio)", "Audiometría tonal (el paciente entra en una cabina insonorizada y usa auriculares para señalar los sonidos y tonos más bajos que puede escuchar en diferentes rangos y frecuencias)", "Pruebas de reconocimiento de voz (para evaluar qué tan bien comprende las palabras, no solo los tonos simples)"], note: "" }, treatment: { title: "Amplificación y Rehabilitación", intro: "No existe ningún remedio médico o cirugía que 'cure' la presbiacusia o revierta el daño nervioso, pero se gestiona y mitiga maravillosamente con dispositivos:", subsections: [ { title: "Opciones de Rehabilitación Auditiva", items: ["Audífonos digitales modernos o aparatos auditivos (el tratamiento estándar de oro; amplifican selectivamente los sonidos de alta frecuencia perdidos para ayudar a oír de nuevo con claridad)", "Dispositivos de asistencia auditiva complementaria (amplificadores telefónicos, auriculares especiales para la televisión y sistemas de alerta visuales)", "Implantes cocleares (se recomiendan únicamente para personas que tienen pérdida auditiva de grado severo a profundo en quienes los audífonos regulares ya no proporcionan ayuda útil)", "Estrategias de comunicación activa (enseñar a la familia a hablar lentamente, mirarse de frente y reducir el ruido ambiental de fondo)"] } ], note: "Ignorar la pérdida de audición no tratada aísla enormemente a las personas y está directamente vinculada al desarrollo de depresión grave y a un inicio mucho más rápido de la demencia (Alzheimer)." }, whenToSeekHelp: { title: "¿Cuándo agendar una revisión auditiva?", intro: "Debes buscar ayuda profesional o de un audiólogo si notas que sistemáticamente:", items: ["Tienes que pedirle constantemente a tus amigos o familiares que repitan lo que acaban de decir, o te quejas de que 'todos murmuran y no articulan'", "Subes el volumen de la televisión o de la radio a niveles que resultan atronadores e intolerables para otras personas en la casa", "Te resulta casi imposible participar activamente en conversaciones si hay varias personas hablando al mismo tiempo o si hay un fuerte ruido de fondo (restaurantes, fiestas)", "Tienes mucha dificultad para escuchar timbres agudos, llamadas de teléfono celular, o el sonido de la voz aguda de las mujeres o de los niños pequeños"] } },
'Alergia a las proteínas de la leche (niño pequeño)' : { intro: "La alergia a la proteína de la leche de vaca (APLV) es una de las alergias alimentarias más comunes en bebés y niños pequeños. Es una reacción exagerada y perjudicial del sistema inmunológico a una o varias de las proteínas presentes típicamente en la leche de vaca y las fórmulas infantiles comerciales.", whatIs: { title: "¿Qué es la APLV?", text: "Ocurre cuando el frágil sistema inmunológico del bebé identifica por error a las proteínas de la leche bovina (como la caseína o el suero) como invasores peligrosos. Esto provoca una rápida liberación masiva de histamina y otros químicos defensivos que desencadenan graves problemas gástricos, de la piel o respiratorios tras su consumo." }, types: { title: "Vías Inmunológicas y Reacciones", intro: "Se divide médicamente en dos categorías según la rapidez e intensidad de la respuesta inmune del cuerpo:", items: ["Alergia mediada por anticuerpos IgE (reacción clásica rápida; los síntomas aparecen de forma abrupta e inmediata, en minutos o hasta dos horas después de la ingesta de leche; riesgo altísimo de anafilaxia)", "Alergia no mediada por IgE (reacción celular retardada; los síntomas pueden tardar muchas horas o incluso varios días enteros en manifestarse, y predominan los cólicos digestivos graves y prolongados, o la mucosidad con sangre en pañales)", "Reacciones mixtas (el infante presenta una combinación de ambas)"], note: "Es vital no confundir esto con la 'intolerancia a la lactosa', la cual es sumamente infrecuente en lactantes y no involucra al sistema inmunológico en absoluto." }, diagnosis: { title: "Detección Clínica Infantil", intro: "El pediatra alergólogo utiliza la historia clínica y pruebas directas de la leche para diagnosticar:", items: ["Dieta rigurosa de eliminación láctea y dieta de provocación bajo supervisión médica (es la prueba más definitiva para las alergias no mediadas por IgE, quitando la leche y viendo si se detienen los vómitos)", "Pruebas cutáneas de punción (Prick test) con proteína de leche diluida", "Análisis de sangre para medir los anticuerpos IgE específicos contra la leche de vaca", "Pruebas cutáneas de parche para observar reacciones de eccema crónico retardadas"], note: "" }, treatment: { title: "Eliminación Dietética y Nutrición", intro: "El único tratamiento efectivo consiste en la evitación dietética estricta y absoluta:", subsections: [ { title: "Opciones de Manejo Nutricional", items: ["Eliminación total y completa de la proteína de leche de vaca de la dieta del niño (evitando leche, queso, mantequilla, suero, caseína)", "Si el bebé es amamantado, la madre debe eliminar estrictamente de su propia dieta todos los productos lácteos y derivados que contengan proteínas", "Uso de fórmulas lácteas especializadas recetadas (fórmulas extensamente hidrolizadas, donde las proteínas están fragmentadas y destruidas en trozos minúsculos, o fórmulas elementales de aminoácidos para casos muy severos y refractarios)", "Tener y portar un autoinyector de adrenalina o epinefrina (EpiPen) preescrito si la alergia es mediada por IgE severa (para emergencias de asfixia)"] } ], note: "La gran noticia es que la inmensa mayoría de los niños, afortunadamente, superan de forma natural esta alergia cuando alcanzan los 3 a 5 años de edad." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia y qué síntomas vigilar?", intro: "Llama a urgencias pediátricas o acude al hospital inmediatamente si tras tomar biberón o pecho, el bebé presenta:", items: ["Dificultad o esfuerzo extremo para respirar (sibilancias intensas, tos seca ronca), o una hinchazón rápida del rostro, de la lengua y garganta (anafilaxia)", "Vómitos muy fuertes que no cesan o evacuaciones líquidas diarreicas explosivas frecuentemente teñidas con moco rojo y sangre viva", "Aparición masiva, extensa y rápida de urticaria muy roja, con gran picor alrededor de la boca, cara o cuerpo general", "Llanto agudo, debilidad, mareo intenso o flacidez y letargo extremo generalizado en el bebé"] } },
'Glomerulonefritis' : { intro: "La glomerulonefritis es un término que designa la inflamación aguda o crónica de los glomérulos, las unidades de filtración microscópicas y especializadas que existen dentro de los riñones. Cuando los glomérulos se dañan, sus diminutos filtros dejan de purificar la sangre de forma eficiente, permitiendo que células vitales escapen.", whatIs: { title: "¿Qué es la Glomerulonefritis?", text: "Es una grave enfermedad renal en la que la barrera filtrante del riñón se inflama e hincha drásticamente. Al romperse esta fina barrera de filtrado normal, los glóbulos rojos (sangre) y las proteínas valiosas se derraman de forma anormal y se excretan en la orina, mientras que se retienen líquidos y toxinas venenosas en el torrente sanguíneo." }, types: { title: "Presentación y Causas Comunes", intro: "Esta afección puede manifestarse repentinamente o desarrollarse lentamente a lo largo de los años:", items: ["Glomerulonefritis aguda (de desarrollo muy rápido, clásicamente ocurre 1 o 2 semanas después de una infección de garganta bacteriana por estreptococo (faringitis estreptocócica), o por infecciones de la piel en niños, y suele curarse bien)", "Glomerulonefritis autoinmune (causada por el propio cuerpo, como el lupus sistémico, la enfermedad de Berger (Nefropatía por IgA) o el síndrome de Goodpasture)", "Glomerulonefritis crónica (evolución lenta y sorda, a menudo detectada por casualidad, que progresivamente destruye el riñón y lleva a una insuficiencia renal irreversible a largo plazo)"], note: "Es una causa principal en el mundo de insuficiencia renal crónica avanzada." }, diagnosis: { title: "Detección y Confirmación Renal", intro: "A menudo se descubre inicialmente al evaluar la orina por sospecha de otros problemas:", items: ["Análisis general de orina (prueba primordial que revelará fuertemente altos niveles de proteínas (proteinuria) y glóbulos rojos deformados (hematuria) que indican daño al filtro)", "Análisis de sangre profundo (para medir qué tan mal está filtrando el riñón usando la creatinina y el nitrógeno ureico en sangre, o marcadores de enfermedades autoinmunes como anticuerpos antinucleares y complemento)", "Biopsia de riñón percutánea (el examen definitivo y más importante; se extraen cilindros de tejido del riñón con una aguja larga por la espalda para ver bajo microscopio electrónico exactamente qué daña el filtro)"], note: "" }, treatment: { title: "Protección Renal y Manejo Terapéutico", intro: "El objetivo urgente es prevenir la insuficiencia y salvar los glomérulos sanos que queden:", subsections: [ { title: "Opciones Médicas y Farmacológicas", items: ["Control muy agresivo de la presión arterial (usando medicamentos inhibidores de la ECA o antagonistas de receptores ARA, que reducen la presión perjudicial dentro del delicado filtro glomerular)", "Medicamentos diuréticos fuertes y restricción estricta de sal (para eliminar drásticamente la retención anormal de líquidos, hinchazón severa y controlar el edema en piernas)", "Corticosteroides intensivos, ciclofosfamida u otros medicamentos inmunosupresores mayores (para reducir inmediatamente la respuesta inmune errónea si la enfermedad fue causada por el sistema inmunológico hiperactivo o lupus)", "Antibióticos si la enfermedad fue desencadenada por una infección bacteriana estreptocócica aún activa", "Diálisis o trasplante de riñón de emergencia si la afección avanza rápidamente y el órgano sufre una falla renal terminal inminente"] } ], note: "Las formas agudas por estreptococo en niños suelen curarse completamente, mientras que en adultos las enfermedades autoinmunes se tratan como crónicas y prolongadas." }, whenToSeekHelp: { title: "¿Cuándo es indispensable acudir al médico?", intro: "Busca ayuda de urgencia nefrótica si notas:", items: ["Orina de color anormalmente marrón rojizo u oscuro (como té, bebida de cola o coñac), indicando claramente que sangras internamente en los riñones", "Orina con espuma excesiva que no se deshace (signo contundente y característico de la expulsión masiva de grandes cantidades de proteínas vitales)", "Un edema, hinchazón y retención de agua de aparición muy repentina (particularmente abotagamiento y edema severo alrededor de los ojos al despertar, o hinchazón grave en piernas y cara)", "Un desarrollo inexplicable de hipertensión arterial aguda severa, debilidad constante y profunda, o micción muy escasa a lo largo del día"] } },
'Muelas del juicio' : { intro: "Las muelas del juicio, también conocidas clínicamente como terceros molares, son los últimos dientes permanentes en erupcionar. Aparecen en la parte posterior superior e inferior de la boca, generalmente entre las edades de 17 y 25 años. A menudo, la boca no tiene suficiente espacio para ellas, causando serias complicaciones dentales.", whatIs: { title: "¿Qué ocurre con las Muelas del Juicio?", text: "Son reliquias evolutivas y anatómicas del humano. Si tienen suficiente espacio en el maxilar y crecen en posición recta, son dientes útiles e inofensivos. Sin embargo, en la mayoría de las personas, los terceros molares carecen de espacio, quedando impactados (encerrados) debajo de las encías o del hueso, o erupcionando en un ángulo totalmente torcido." }, types: { title: "Formas Clínicas de Impactación", intro: "El problema se clasifica según la posición de crecimiento del diente problemático:", items: ["Erupción sana y completa (la muela sale recta y el paciente puede cepillarla, requiere conservación pero a veces causan daños si la higiene allí atrás no es óptima)", "Impactación parcial de tejido (la muela rompe la encía, pero un colgajo de carne la cubre, atrapando constantemente comida, bacterias y provocando la muy dolorosa pericoronaritis aguda)", "Impactación angular o inclinada (mesioangular, que se acuesta hacia la segunda muela vecina empujándola, o distoangular recostándose hacia atrás del cráneo)", "Impactación ósea completa (el diente se asienta en la base del hueso y no sale en absoluto; asintomático por años, pero puede desarrollar quistes que disuelvan el hueso maxilar circundante)"], note: "El hecho de que las muelas del juicio impactadas 'no duelan' no significa que no estén destruyendo silenciosamente la raíz del diente vecino." }, diagnosis: { title: "Detección y Monitoreo Odontológico", intro: "El dentista u cirujano oral evalúa la necesidad de mantenerlas o sacarlas mediante:", items: ["Chequeos y limpieza dental rutinaria (el dentista sondea los márgenes de las encías traseras en adolescentes buscando problemas)", "Radiografía dental panorámica (ortopantomografía) de toda la cara (la prueba diagnóstica esencial; muestra con total exactitud la presencia y la inclinación de las muelas ocultas antes de que erupcionen, y qué tan cerca están sus largas raíces del vital nervio de la mandíbula inferior)"], note: "" }, treatment: { title: "Resolución Preventiva y Quirúrgica", intro: "La odontología moderna previene que las complicaciones crónicas causen pérdida dental generalizada:", subsections: [ { title: "Opciones de Intervención", items: ["Extracción profiláctica o quirúrgica (el tratamiento curativo estándar: se extirpa el diente bajo anestesia local o sedación profunda para curar el dolor agudo, evitar el desplazamiento o apiñamiento dental, la infección purulenta o la caries intratable de los molares adyacentes; es más fácil y se recupera mucho mejor si se hace entre los 16 y 20 años)", "Observación activa periódica (solo si el diente de juicio ha crecido perfectamente recto y encaja en la mordida, pero requiere un cuidado con hilo dental extremo de por vida)", "Irrigación profunda y enjuagues antibacterianos con clorhexidina (para calmar de urgencia una infección aguda y purulenta del capuchón gingival antes de poder operar en otra cita)"] } ], note: "Se desaconseja esperar hasta experimentar dolores graves a los 40 o 50 años para extirparlas, debido a que el hueso cráneo se solidifica mucho y el riesgo de dañar nervios es mucho mayor." }, whenToSeekHelp: { title: "¿Cuándo es necesario concertar la cirugía dental urgente?", intro: "Pide una revisión imperiosa al odontólogo si padeces síntomas como:", items: ["Inflamación o enrojecimiento muy severo y sensible de la encía detrás del último molar visible, irradiando el dolor hacia la garganta o el oído del mismo lado", "Un sabor de boca horrible y persistente o mal aliento que procede del área trasera del molar afectado (una señal clásica de absceso)", "Rigidez muscular de la mandíbula y dolor intenso que hace muy difícil o casi imposible abrir la boca para comer (trismo)", "Apiñamiento reciente o daño, dolor, u oscurecimiento por presión notable de los incisivos o dientes cercanos de los que la muela está empujando"] } },
'Fisura anal' : { intro: "Una fisura anal es un pequeño pero profundo desgarro o corte doloroso en la fina membrana mucosa delgada y húmeda que recubre la entrada y el canal interno inferior del ano. Es una causa sumamente común de dolor severo relacionado con la defecación, que a menudo se confunde erróneamente con hemorroides.", whatIs: { title: "¿Qué es una Fisura Anal?", text: "Es una rotura lineal en la piel anal, causada por un estiramiento extremo del tejido anal. Esto provoca un dolor insoportable, punzante o cortante (como 'pasar hojas de afeitar o vidrio') que se experimenta principalmente durante e inmediatamente después de intentar tener una evacuación intestinal. Esta agonía también causa que el anillo muscular (esfínter) entre en espasmo fuerte, disminuyendo la curación." }, types: { title: "Causas y Duración de las Fisuras", intro: "El desgarro casi siempre es mecánico, y se agrupa por cuánto tiempo ha persistido:", items: ["Fisura anal aguda (parece un pequeño y limpio corte de papel brillante; es un trauma reciente, típicamente por expulsar heces extremadamente duras, grandes y secas asociadas con el estreñimiento o, a la inversa, por episodios de diarrea grave recurrente, y se curan rápido con tratamiento)", "Fisura anal crónica (la rotura que no ha curado ni cerrado durante más de ocho semanas; se vuelve profunda, a menudo presenta bordes gruesos levantados como cráteres y puede desarrollar un pequeño y doloroso bulto llamado apéndice cutáneo centinela o 'marisca', siendo causada por el constante espasmo del esfínter interno cerrado que corta el flujo de la sangre sanadora hacia la propia herida)", "Causas secundarias inusuales (como por sexo anal vigoroso o partos, y si son múltiples en lugares extraños, por enfermedad de Crohn o infecciones)"], note: "El paciente a menudo evita conscientemente o suprime las ganas de ir al baño para no sufrir el dolor espantoso, lo que endurece aún más la materia fecal, reabriendo y rasgando brutalmente la cicatriz en un ciclo vicioso interminable." }, diagnosis: { title: "Examen Visual Especializado", intro: "Un proctólogo o médico la diagnosticará clínicamente usando sus propios ojos y la evaluación prudente de la lesión:", items: ["Inspección visual directa suave al separar las nalgas externas (la inmensa mayoría de las heridas se encuentran directamente en la zona anal posterior central)", "El examen del tacto rectal doloroso o las sigmoidoscopias intrusivas se evitan absolutamente mientras el espasmo profundo del dolor agudo exista, para no empeorar al paciente, a menos que el médico sospeche sangrado por cáncer o Crohn", "El interrogatorio sobre los síntomas precisos (dolor abrasador que quema durante horas tras hacer de vientre y sangre escasa separada) es a menudo diagnóstico y decisivo por sí mismo"], note: "" }, treatment: { title: "Medidas Terapéuticas y Cirugía", intro: "El objetivo principal del plan es detener el fuerte calambre del músculo y reblandecer y facilitar al máximo las heces para no seguir rompiendo la herida al curarse:", subsections: [ { title: "Rutas de Tratamiento y Recuperación", items: ["Aumento radical del volumen de fibra y laxantes osmóticos médicos (para transformar mecánicamente la materia fecal en texturas blandas extremas e inofensivas en todo momento)", "Baños de asiento tibios y largos, varias veces al día y después de defecar (para inducir mediante calor al esfínter interno muscular en espasmo a que logre relajarse para fluir la sangre y calmar inmensamente la inflamación del ardor local)", "Pomadas anestésicas y cremas vasodilatadoras muy especializadas para receta anal (pomada o crema de nitroglicerina tópica estricta, o bloqueadores de calcio en crema, se frotan directamente para expandir rápidamente las arterias microscópicas sanadoras en el esfínter anal interior para que cicatrice de emergencia el desgarro)", "Inyección profunda de la toxina botulínica de bótox por parte del cirujano en el espasmo anal doloroso", "Cirugía reparadora de Esfinterotomía Lateral Interna del anal (la operación 'estándar y curativa' donde si la fisura es profunda y crónica al tratamiento de meses, el cirujano corta un diminuto fragmento del musculoso anillo anal que estaba atascado en el calambre o espasmo doloroso general perpetuo)"] } ], note: "Las supositorios y cremas clásicas famosas para hemorroides no logran nada y no tienen efecto sanador vascular probado alguno para relajar la grieta del esfínter de la fisura anal." }, whenToSeekHelp: { title: "¿Cuándo acudir para evitar un tratamiento crónico complejo?", intro: "A pesar del tabú doloroso, debes ser examinado médica y proctológicamente urgentemente en lugar de padecer solo en silencio, si:", items: ["Sientes de la nada episodios de dolor punzante e intensamente asfixiante como cristales rotos en la apertura anal que perduran durante varias horas agotadoras después de tu movimiento en el retrete intestinal", "Encuentras repentinamente sangre que es brillante, roja clara e independiente que gotea en forma de rayas sobre la taza del inodoro después del evento doloroso, o manchas frescas en el papel después de limpiarte el papel de limpieza", "A palpas muy cerca de la abertura final y detectas un pequeño y dolorosísimo colgajo bulto o un bultillo crónico prominente adyacente a la úlcera herida de adentro", "La molestia o escozor del desgarre te resulta verdaderamente incapacitante o imposible y la condición general no sana tras dos semanas continuas completas y rigurosas de baños calientes y fibras de frutas"] } },
'Celulitis' : { intro: "La celulitis (no el término cosmético relacionado con hoyuelos de grasa cutánea) es una infección bacteriana aguda grave, potencialmente muy dolorosa, profunda y muy extendida, que afecta primordialmente las capas medias y los tejidos blandos internos ubicados más profundamente debajo y debajo de la dermis.", whatIs: { title: "¿Qué es la Infección de Celulitis?", text: "Es la infección invasiva de las gruesas y ricas redes de tejidos subcutáneos más allá de la superficie, donde bacterias invasivas rápidas causan una gran área de hinchazón y diseminación. Si este cuadro purulento pernicioso infeccioso no trata con éxito mediante fármacos curativos orales de urgencia, estas mortales se extenderán invasivamente hacia adentro, infectando ganglios cercanos o a la preciada y masiva sangre interior a través del todo el torrente circulatorio general, constituyendo entonces sepsis mortal." }, types: { title: "Vías Celulíticas Diseminadas Frecuentes y Tipos de Causas", intro: "Normalmente los temibles y poderosos invasores del ambiente microscópico general que irrumpen son las cepas bacterianas agresivas de cocos estreptococos comunes que viven normalmente intactas en la salud o peligrosísimos estafilococos de pus de orígenes infecciosos por rotura en superficie:", items: ["Celulitis estreptocócica agresiva (diseminándose inmensamente veloz como bordes difuminados dolorosos)", "Celulitis del Estafilococo aureus clásico letal y celulitis temida MRSA (cepa letal purulenta que rechaza casi todos los antimicrobianos clásicos)", "Celulitis posoperatorias supurantes, o celulitis originadas por letales picaduras perjudiciales de grandes y extraños animales y mordeduras sucias directas contaminadas", "Se desencadenan usualmente en pacientes vulnerables y de riesgos que viven con llagas severas o venas en piernas insuficientes (generalmente originados en los tobillos inferiores hinchados y en extremidades crónicamente agrietadas de piernas de la tercera edad), úlceras o diabetes neuropáticas incontroladas diabéticas e hinchadas por edema, aunque una rotura casi inexistente que rompa el rasguño bastará, lo mismo sucede alrededor un corte posquirúrgico reciente, quemadura de llaga rascada de eccemas pruriginosos, y sobre picaduras de moscas y arañazos de pie de atleta"], note: "Suele y típicamente afectar agresivamente una de las largas extremidades de las mitades pantorrillas inferiores en absoluto lado derecho o izquierdo, aunque ocurre en cara infantil profunda letal y letal perineal si la diseminación cutánea se extiende hacia la base ocular profunda orbitaria de celulitis infecciosa del ojo." }, diagnosis: { title: "Evaluación Médica Tópica Vital", intro: "Los especialistas y doctores del centro general valorarán de forma rápida para parar en progreso inflamatorio grave de modo precoz e intensivo:", items: ["Revisión profunda diagnóstica muy urgente basada de inspección clínica táctil experta estricta y rápida a través de la enorme hinchada e infectada pierna herida (buscando indicios obvios calientes, enrojecimiento brillante extendido doloroso, sensibilidad ardiente, contorno no bien elevado difuso) en donde el doctor traza márgenes directos visuales temporales marcando alrededor del borde general caliente pintándolo en las rojeces circundantes general de las zonas superficial con un rotulador dérmico de bolígrafo negro visual de seguimiento real constante para el monitoreo y seguimiento directo urgente del crecimiento cutáneo si la diseminación inflamada es regresiva", "Pruebas vitales urgentes profundas y extracciones generalizadas venosas orgánicas de sangre intensivas o cultivos para la prueba total rápida masiva vital (prescrito y estipulado rutinariamente cuando hay escalofrío letárgico corporal masivo inestable febril descontrolado purulento de abscesos infectados generalizado en riesgo alto general diseminado y de urgencias de toxinas venosas orgánicas)", "Raras vez ecografías visualizadoras en casos que sospechan ocluidas masas subyacentes con trombos severos de profundos coagulos mortales venosos o que se encuentre profundamente abscesado para descartar TVP dolorosas similares"], note: "" }, treatment: { title: "Erradicación Patológica Farmacéutica Rápida", intro: "Un abordaje intensivo antibiótico rápido oral salva rápidamente los peores desastres masivos crónicos general del letal esparcimiento vital y paralización y detención inmediata a través curativo purulento local:", subsections: [ { title: "Terapia Interventiva Farmacéutica", items: ["Curso curativo completo de choque potente estricto en el uso intenso preescrito del consumo oral farmacológico antibiótico curativo sistémico general e imprescindible por la indicación letal del paciente en régimen total de casa y receta entre cinco y hasta 14 largos intensivos obligatorios (de cefalexinas, penicilinas estables fuertes dicloxacilinas o doxiciclinas especializadas contra SARM mortales que ataquen a invasores y logren eliminar a toda toxina remanente y que eviten retornos por culpa interrupción no medicada corta y no lograda de recuperación celular letal en supresión temprana errática de urgencias recaída sistémica patológica cutánea)", "Dosis elevadísima médica intravenosa general (IV) antibiótica total profunda curativa de tratamiento de terapia urgente e ingreso inmediato severo con reposo en hospital de cama severa en todos aquellos enfermos graves débiles de riesgo grave e inmunosuprimidos (pacientes y abuelos adultos frágiles o severamente diabéticos incontrolados con deficiencias, aquellos donde de las orales ya fracasaron por todo, fiebres letales incesables purulentas continuadas extremas altas descontroladas o si la infección perjudicial aguda de inflamación purulenta de tejidos se centra amenazadoramente cerca al cráneo masivo ojo óseo mortal orbital y rostro cerebral grave de la vista o meningitis facial superior general)"] } ], note: "Es vital e importante obligar siempre a guardar el descanso extremo general e implementar una muy necesaria elevación constante por la gravedad en alto nivel superior severo por la cama muy alzada sobre el enfermo paciente y corazón cardíaco el descanso postrado generalizado en todo extremo hinchado infectado patológico general o en pierna (ya sea pierna pantorrilla o miembro de brazos heridos de brazo local lesionada) pues esto estimula enormemente rápidamente que baje mecánicamente la excesiva extrema inflamación y la reducción sanadora e impedimento venoso patológico curativo e hinchado masivo." }, whenToSeekHelp: { title: "¿Cuándo representa de modo directo la urgencia médica hospitalaria y peligrosa en alerta roja de letal progreso y amputación en general extrema de diseminación invasiva total?", intro: "Es fundamentalísima la alarma urgente inmediata masiva total ir veloz hacia a urgencia máxima para salvar pierna local lesionada si detectas:", items: ["El descubrimiento súbito reciente general agudo sobre tu inflamación general pierna cutánea general hinchada e inexplicablemente gran mancha profunda de piel enrojecida intensamente ardiente caliente sensible muy dolorosa grave de que crece masiva veloz enormemente rápido a medida y crece e invade a cada par de las horribles invasoras o extendiéndose en todo el tamaño enorme veloz del perímetro local sin razón del área patológica contigua general rápida", "Padeces o encuentras indudable fiebre repentina letal excesiva y aguda temblorosa en grandes sudores sudorosos intensivos corporales y grandes tiritonas letárgicas purulentas por la profunda gran toxicidad infecciosa de glándulas grandes locales corporales letales venenosas circulantes general o pus fétida evidente y purulenta y segregación severa extrema o severo absceso rojo palpitante agudo con rayas extendiéndose intensas sangrantes, supuración e indicativo letal directo masivo desde los límites purulentos herida rojez cutánea patológica en progreso", "Tú eres o un individuo y persona muy de muy extrema vulnerabilidad y debilidad corporal que ya padece de problemas grandes y preexistentes generalizados letales severos del azúcar de su insuficiencia grave venosa en mala diabetes circulación patológico de diabetes o inmune cáncer (donde tú riesgo real para de pérdida y letal urgencia y gran mortífera sepsis diseminación letal a lo sanguíneo o requerir general una total cirugía profunda en necrosis es gigante extrema)"] } },
'Enfermedades de la tiroides' : { intro: "Las enfermedades de la tiroides son afecciones que alteran la cantidad de hormonas que produce esta pequeña glándula en forma de mariposa ubicada en el cuello. Estas hormonas regulan el metabolismo, la energía y el ritmo cardíaco del cuerpo.", whatIs: { title: "¿Qué son las Enfermedades de la Tiroides?", text: "Son disfunciones de la glándula tiroidea que provocan una producción excesiva (hipertiroidismo) o insuficiente (hipotiroidismo) de hormonas tiroideas, desequilibrando el funcionamiento general del organismo." }, types: { title: "Tipos Frecuentes", intro: "Las alteraciones más habituales incluyen:", items: ["Hipotiroidismo (producción deficiente, causando fatiga y aumento de peso)", "Hipertiroidismo (producción excesiva, causando pérdida de peso y taquicardia)", "Tiroiditis de Hashimoto (enfermedad autoinmune que causa hipotiroidismo)", "Enfermedad de Graves (causa autoinmune de hipertiroidismo)", "Nódulos tiroideos (bultos benignos o malignos en la glándula)"], note: "Los problemas de tiroides son mucho más frecuentes en mujeres que en hombres." }, diagnosis: { title: "Diagnóstico Clínico", intro: "El endocrinólogo evaluará la función tiroidea mediante:", items: ["Análisis de sangre para medir TSH, T3 libre y T4 libre", "Pruebas de anticuerpos tiroideos (para detectar problemas autoinmunes)", "Ecografía tiroidea (para evaluar el tamaño de la glándula y la presencia de nódulos)"], note: "La prueba de TSH es el estándar de oro para detectar problemas de tiroides tempranos." }, treatment: { title: "Manejo y Medicación", intro: "El tratamiento busca restaurar los niveles hormonales normales:", subsections: [ { title: "Terapias de Reemplazo y Control", items: ["Levotiroxina sintética (pastilla diaria de por vida para el hipotiroidismo)", "Medicamentos antitiroideos o yodo radiactivo (para frenar el hipertiroidismo)", "Cirugía (tiroidectomía) para casos severos, nódulos grandes o sospecha de cáncer"] } ], note: "Una vez que los niveles hormonales se estabilizan con medicación, los pacientes llevan una vida completamente normal." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es recomendable solicitar un análisis de tiroides si:", items: ["Sientes una fatiga extrema y constante que no mejora al dormir", "Notas cambios de peso bruscos e inexplicables (subir o bajar) sin alterar tu dieta", "Tienes alteraciones en el ritmo cardíaco, sensibilidad extrema al frío/calor o notas un bulto en la base del cuello"] } },
'Trastorno del espectro autista (TEA)' : { intro: "El trastorno del espectro autista (TEA) es una afección del desarrollo neurológico y cerebral. Afecta la manera en que una persona percibe y socializa con otras personas, lo que causa problemas en la interacción social y la comunicación.", whatIs: { title: "¿Qué es el TEA?", text: "Es una condición neurobiológica que comienza en la primera infancia. La palabra 'espectro' indica que existe una amplia variación en el tipo y la gravedad de los síntomas. Algunas personas con TEA son altamente funcionales, mientras que otras requieren un apoyo sustancial diario." }, types: { title: "Características y Niveles", intro: "El DSM-5 clasifica el TEA por niveles de necesidad de apoyo:", items: ["Nivel 1 (necesita apoyo, antes conocido como Síndrome de Asperger)", "Nivel 2 (necesita apoyo sustancial)", "Nivel 3 (necesita apoyo muy sustancial, a menudo con deficiencias severas de lenguaje y comunicación)", "Patrones de comportamiento restrictivos y repetitivos (rutinas estrictas, aleteo de manos, intereses obsesivos)"], note: "El autismo no es una enfermedad a 'curar', sino una forma diferente de procesar el mundo." }, diagnosis: { title: "Evaluación del Desarrollo", intro: "Se diagnostica mediante la observación del comportamiento:", items: ["Evaluaciones del desarrollo temprano en consultas pediátricas (búsqueda de hitos del lenguaje y juego)", "Evaluación multidisciplinaria (psicólogo, neurólogo, logopeda) para analizar habilidades sociales y cognitivas", "Pruebas genéticas o neurológicas (solo para descartar otros trastornos médicos asociados)"], note: "Un diagnóstico temprano (antes de los 2-3 años) es vital para el desarrollo futuro." }, treatment: { title: "Intervenciones y Apoyo", intro: "El objetivo es maximizar la capacidad de la persona para funcionar y aprender:", subsections: [ { title: "Terapias Educativas y Conductuales", items: ["Terapia de comportamiento y comunicación (como el Análisis Conductual Aplicado o ABA)", "Terapia ocupacional (para mejorar habilidades de la vida diaria y la integración sensorial)", "Terapia del habla (logopedia para mejorar la comunicación verbal y no verbal)", "Apoyo familiar intensivo y programas educativos personalizados en la escuela"] } ], note: "No hay medicamentos para el TEA en sí, pero sí se pueden recetar fármacos para manejar síntomas asociados como la ansiedad o hiperactividad." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Debes buscar una evaluación del desarrollo si el niño:", items: ["No responde a su nombre a los 12 meses de edad", "No señala objetos para mostrar interés o no hace contacto visual sostenido a los 14 meses", "Pierde habilidades de lenguaje o sociales que ya había adquirido a cualquier edad (regresión)", "Presenta movimientos corporales inusuales y repetitivos o reacciones extremas a ciertos sonidos o texturas"] } },
'Aneurisma cerebral' : { intro: "Un aneurisma cerebral es una protuberancia o abombamiento en un vaso sanguíneo del cerebro. A menudo se describe como similar a una mora que cuelga de un tallo. Puede presentar un riesgo de rotura y causar una hemorragia potencialmente mortal.", whatIs: { title: "¿Qué es un Aneurisma Cerebral?", text: "Es una zona débil en la pared de una arteria cerebral que se hincha por la presión de la sangre. La mayoría de los aneurismas pequeños no se rompen ni causan problemas, pero si se rompen, la sangre se derrama alrededor del cerebro (hemorragia subaracnoidea), causando un daño severo inmediato." }, types: { title: "Estados Clínicos", intro: "Se clasifican según su estado de rotura y tamaño:", items: ["Aneurisma roto (una emergencia médica extrema con altas tasas de mortalidad y discapacidad)", "Aneurisma intacto o no roto (a menudo no presenta síntomas y se descubre al hacer pruebas por otros motivos)", "Aneurisma gigante (mide más de 2.5 centímetros y ejerce presión dañina sobre el tejido cerebral o los nervios aunque no se haya roto)"], note: "El tabaquismo y la presión arterial alta son los mayores factores de riesgo para su crecimiento y ruptura." }, diagnosis: { title: "Diagnóstico Neurológico", intro: "Se detectan o evalúan mediante neuroimagen avanzada:", items: ["Tomografía Computarizada (TC) de la cabeza (la prueba más rápida para ver si ha habido sangrado en urgencias)", "Angiografía por TC (ATC) o Angiografía por RM (MRA) (proporcionan imágenes tridimensionales de las arterias del cerebro)", "Angiografía cerebral por catéter (el examen más detallado para mapear el aneurisma antes del tratamiento quirúrgico)"], note: "" }, treatment: { title: "Prevención de la Ruptura y Reparación", intro: "El tratamiento para aneurismas intactos depende del riesgo; los rotos requieren cirugía urgente:", subsections: [ { title: "Intervenciones Quirúrgicas", items: ["Clipaje quirúrgico (el neurocirujano abre el cráneo y coloca un pequeño clip de metal en el cuello del aneurisma para detener el flujo de sangre hacia él)", "Embolización endovascular (se introducen espirales o 'coils' de platino desde una arteria en la ingle hasta el aneurisma para coagularlo, sin abrir el cráneo)", "Desviadores de flujo (tubos similares a stents colocados en la arteria matriz para que la sangre pase de largo del aneurisma)"] } ], note: "Controlar estrictamente la presión arterial es el cuidado preventivo más importante." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Una ruptura de aneurisma exige llamar inmediatamente al 911 si presentas:", items: ["Un dolor de cabeza repentino y sumamente severo (a menudo descrito como el 'peor dolor de cabeza de la vida')", "Náuseas violentas, vómitos, cuello muy rígido o sensibilidad extrema a la luz (fotofobia)", "Visión doble o borrosa repentina, caída del párpado, confusión profunda o pérdida de conocimiento inminente"] } },
'Bocio' : { intro: "El bocio es un aumento anormal del tamaño de la glándula tiroides, ubicada en la base del cuello, justo debajo de la nuez de Adán. Un bocio puede ser un agrandamiento general de toda la glándula o la formación de nódulos individuales irregulares.", whatIs: { title: "¿Qué es el Bocio?", text: "Es el agrandamiento visible o palpable de la tiroides. Indica que la glándula está trabajando anormalmente. No es una enfermedad en sí misma, sino el síntoma físico de afecciones como la deficiencia de yodo, el hipotiroidismo, el hipertiroidismo o tumores benignos." }, types: { title: "Clasificación", intro: "El bocio se clasifica por su forma y función hormonal:", items: ["Bocio endémico (causado por deficiencia de yodo en la dieta, común en ciertas regiones del mundo)", "Bocio difuso (toda la glándula está hinchada y lisa)", "Bocio multinodular (se desarrollan múltiples bultos sólidos o llenos de líquido en la glándula)", "Bocio eutiroideo (la tiroides está grande, pero los niveles hormonales son normales)"], note: "El bocio tóxico ocurre cuando el tejido agrandado produce demasiada hormona tiroidea." }, diagnosis: { title: "Evaluación Endocrina", intro: "El médico identificará la causa subyacente mediante:", items: ["Examen físico del cuello (pidiéndote que tragues para sentir la glándula)", "Análisis de sangre para verificar los niveles de hormonas tiroideas (TSH, T4 libre) y anticuerpos autoinmunes", "Ecografía de tiroides (para ver el tamaño real y si hay nódulos ocultos)", "Biopsia por aspiración con aguja fina (si hay nódulos sospechosos para descartar cáncer)"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "El tamaño del bocio y los niveles hormonales dictan el tratamiento:", subsections: [ { title: "Opciones Médicas", items: ["Observación ('espera vigilante') si el bocio es pequeño y no causa problemas hormonales ni de compresión", "Medicamentos (levotiroxina si la causa es hipotiroidismo, o fármacos antitiroideos si es por hipertiroidismo)", "Yodo radiactivo (para reducir el tamaño del bocio y detener la hiperactividad)", "Cirugía (tiroidectomía para extirpar la glándula si es muy grande, causa dificultad para tragar/respirar o hay sospecha de cáncer)"] } ], note: "La sal yodada ha erradicado en gran medida el bocio endémico en muchos países." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Debes buscar evaluación médica si:", items: ["Notas una hinchazón, bulto o masa evidente en la base de tu cuello", "Sientes una sensación de opresión constante en la garganta o tienes dificultad física para tragar alimentos sólidos", "Experimentas cambios en la voz (ronquera) o dificultad respiratoria al acostarte", "El bulto crece rápidamente en poco tiempo"] } },
'EPOC' : { intro: "La Enfermedad Pulmonar Obstructiva Crónica (EPOC) es una enfermedad inflamatoria crónica de los pulmones que obstruye el flujo de aire desde los pulmones. Los síntomas incluyen dificultad para respirar, tos, producción de mucosidad (esputo) y sibilancias.", whatIs: { title: "¿Qué es la EPOC?", text: "Es un término paraguas que agrupa principalmente dos afecciones: el enfisema pulmonar (destrucción de los alvéolos o sacos de aire) y la bronquitis crónica (inflamación y estrechamiento de los conductos bronquiales). Es una enfermedad progresiva y no reversible, causada casi siempre por la exposición al humo del tabaco." }, types: { title: "Componentes Clínicos", intro: "La mayoría de los pacientes tienen una combinación de ambos componentes:", items: ["Enfisema (las paredes de los sacos de aire se destruyen, atrapando aire y dificultando la exhalación, lo que causa severa falta de aire)", "Bronquitis crónica (producción diaria y excesiva de moco con tos productiva persistente)"], note: "Las exacerbaciones (brotes donde los síntomas empeoran rápidamente) son muy peligrosas y requieren hospitalización." }, diagnosis: { title: "Pruebas de Función Pulmonar", intro: "El neumólogo evaluará el daño pulmonar con:", items: ["Espirometría (la prueba vital y definitiva; mide cuánto aire puedes exhalar con fuerza; un volumen bajo confirma la obstrucción)", "Radiografía de tórax o TC (para evaluar el enfisema y descartar otras enfermedades cardíacas o cáncer)", "Análisis de gases en sangre arterial (para medir la severidad de la falta de oxígeno en el torrente sanguíneo)"], note: "Las personas fumadoras mayores de 40 años con tos crónica deben someterse a una espirometría de rutina." }, treatment: { title: "Manejo a Largo Plazo", intro: "La EPOC no se cura, pero el tratamiento agresivo alivia los síntomas y ralentiza el daño:", subsections: [ { title: "Terapias y Medicación", items: ["Dejar de fumar absolutamente (es la intervención más crítica para detener la destrucción pulmonar)", "Inhaladores broncodilatadores (para abrir las vías respiratorias) y corticosteroides inhalados (para reducir la inflamación)", "Rehabilitación pulmonar (programas de ejercicio supervisado y educación respiratoria)", "Oxigenoterapia suplementaria (para etapas avanzadas con hipoxemia severa)", "Vacunación preventiva (gripe, neumococo, COVID-19) para evitar exacerbaciones infecciosas fatales"] } ], note: "Continuar fumando anula casi por completo los beneficios de cualquier medicamento inhalado." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia (Exacerbación)?", intro: "Acude a urgencias inmediatamente si presentas:", items: ["Falta de aliento grave e inusual que te impide caminar distancias cortas o incluso hablar", "Coloración azul o grisácea en los labios o los lechos ungueales (cianosis por falta de oxígeno)", "Aumento drástico en la cantidad de esputo (flema) o un cambio de color a amarillo oscuro o verde, indicando infección aguda", "Confusión mental, latidos cardíacos acelerados o sensación de que no estás obteniendo ningún beneficio de tus inhaladores de rescate"] } },
'Cistitis aguda' : { intro: "La cistitis aguda es la infección e inflamación repentina de la vejiga urinaria, generalmente causada por una infección bacteriana. Es el tipo más común de infección del tracto urinario (ITU), afectando abrumadoramente más a las mujeres que a los hombres.", whatIs: { title: "¿Qué es la Cistitis Aguda?", text: "Es una condición dolorosa y molesta donde las bacterias (usualmente E. coli proveniente de la flora intestinal) ascienden por la uretra y colonizan la vejiga. La mucosa de la vejiga se irrita y enrojece profundamente, causando una necesidad urgente y dolorosa de orinar constantemente." }, types: { title: "Causas y Contexto", intro: "La gran mayoría son bacterianas, pero existen otras causas:", items: ["Cistitis bacteriana no complicada (infección común en mujeres sanas sin anomalías urinarias, frecuentemente desencadenada tras las relaciones sexuales)", "Cistitis complicada (asociada a catéteres, embarazo, cálculos renales, hombres o próstata agrandada)", "Cistitis no infecciosa (inflamación por radiación pélvica, cistitis intersticial crónica, o por reacciones químicas a espermicidas o jabones)"], note: "Limpiarse de atrás hacia adelante después de ir al baño es una de las principales vías de infección en mujeres." }, diagnosis: { title: "Evaluación Médica Rápida", intro: "El diagnóstico suele ser rápido y directo:", items: ["Evaluación clínica de los síntomas (ardor al orinar y polaquiuria)", "Análisis de orina con tira reactiva (detecta glóbulos blancos, sangre microscópica o nitritos producidos por bacterias)", "Cultivo de orina o urocultivo (tarda 48 horas, se pide para identificar la bacteria exacta si la cistitis es recurrente, complicada o no responde al tratamiento inicial)"], note: "" }, treatment: { title: "Tratamiento Antibiótico", intro: "Las infecciones bacterianas se curan eficazmente con medicamentos:", subsections: [ { title: "Opciones de Manejo", items: ["Antibióticos orales (fosfomicina, nitrofurantoína o trimetoprima-sulfametoxazol por 3 a 7 días, es el tratamiento curativo principal)", "Analgésicos urinarios (como la fenazopiridina, para calmar rápidamente el dolor ardiente mientras el antibiótico hace efecto)", "Hidratación abundante (beber mucha agua ayuda a 'lavar' y expulsar las bacterias de la vejiga)"] } ], note: "Aunque los síntomas suelen desaparecer en 24 horas tras iniciar los antibióticos, detener el tratamiento antes de tiempo fomenta infecciones resistentes más graves." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es indispensable recibir tratamiento médico; no intentes curarlo solo con remedios caseros si tienes:", items: ["Fuerte dolor o escozor al orinar acompañado de urgencia constante (incluso si solo caen gotas)", "Orina turbia, con mal olor fuerte o de color rojizo/rosado (sangre visible)", "Acude a URGENCIA si el cuadro se acompaña de dolor en la zona lumbar (espalda baja), fiebre alta, escalofríos o náuseas (signos de que la infección ha subido a los riñones)"] } },
'Cicatrices de acné' : { intro: "Las cicatrices de acné son marcas permanentes en la piel que resultan de brotes severos de acné inflamatorio (como quistes o nódulos). Ocurren cuando el cuerpo no sana correctamente el daño profundo en la dermis, alterando la textura y el tono del rostro.", whatIs: { title: "¿Qué son las Cicatrices de Acné?", text: "Son alteraciones fibróticas de la piel. Cuando un grano muy inflamado daña los tejidos subyacentes, el cuerpo produce colágeno para reparar la herida. Si produce muy poco colágeno, se forman hundimientos; si produce demasiado, se forman cicatrices elevadas." }, types: { title: "Tipos de Cicatrices", intro: "Se clasifican fundamentalmente por su forma topográfica:", items: ["Cicatrices atróficas o deprimidas (las más comunes en el rostro, incluyen las cicatrices 'en furgón' o en caja (boxcar), 'en picahielo' (icepick) profundas y estrechas, y las onduladas (rolling))", "Cicatrices hipertróficas o queloides (elevadas y gruesas, comunes en el pecho, espalda y línea de la mandíbula, por exceso de colágeno)", "Hiperpigmentación postinflamatoria (manchas rojas u oscuras planas que quedan tras el grano; no son cicatrices verdaderas y suelen desaparecer con los meses)"], note: "Pellizcar, apretar o reventar los granos aumenta drásticamente el riesgo de desarrollar cicatrices permanentes." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El especialista en piel determinará el enfoque a seguir:", items: ["Examen visual con luz rasante para evaluar el tipo exacto, profundidad y extensión de las cicatrices atróficas", "Evaluación de la presencia de acné activo (es imperativo curar primero la infección de acné subyacente antes de intentar tratar las cicatrices)"], note: "" }, treatment: { title: "Revisión y Remodelación de la Piel", intro: "El tratamiento es cosmético y suele requerir múltiples sesiones combinadas para mejorar la textura (no se borran al 100%):", subsections: [ { title: "Técnicas Dermatológicas", items: ["Terapias con láser fraccionado (ablativo y no ablativo, para estimular el colágeno nuevo y alisar la piel)", "Microneedling (microagujas, a veces con radiofrecuencia, para inducir la regeneración de colágeno en cicatrices onduladas)", "Peelings químicos medios y profundos (TCA) (para exfoliar capas dañadas y manchas oscuras)", "Rellenos dérmicos de ácido hialurónico (para elevar temporalmente los hundimientos)", "Subcisión (cirugía menor donde una aguja rompe las fibras cicatriciales que tiran de la piel hacia abajo) o escisión en sacabocados (para cicatrices en picahielo profundas)"] } ], note: "Las cremas de venta libre no pueden rellenar ni curar las cicatrices atróficas reales, solo mejoran las manchas." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Es recomendable visitar a un dermatólogo o médico estético si:", items: ["Las cicatrices te están causando una gran inseguridad, angustia psicológica o problemas de autoestima", "Tienes acné nódulo-quístico severo y doloroso actualmente (el tratamiento temprano con medicamentos fuertes previene la formación de nuevas cicatrices)", "Deseas informarte sobre procedimientos médicos reales y seguros para alisar la piel, evitando remedios caseros abrasivos y peligrosos"] } },
'Epicondilitis humeral' : { intro: "La epicondilitis humeral, comúnmente conocida como 'codo de tenista' (lateral) o 'codo de golfista' (medial), es una lesión dolorosa por sobrecarga. Ocurre cuando los tendones que unen los músculos del antebrazo al hueso del codo se inflaman o se desgarran por microtraumatismos repetitivos.", whatIs: { title: "¿Qué es la Epicondilitis?", text: "Es una tendinopatía degenerativa y dolorosa. A pesar del nombre, rara vez es causada por inflamación aguda (itis), sino por el desgaste crónico y la mala cicatrización de las fibras tendinosas en la protuberancia ósea del codo (epicóndilo) debido a movimientos repetitivos de agarre, giro o extensión de la muñeca." }, types: { title: "Variantes Clínicas", intro: "Dependiendo del tendón afectado, se clasifica en:", items: ["Epicondilitis lateral (Codo de tenista): Afecta la parte exterior del codo, ligada a los músculos que extienden la muñeca hacia atrás.", "Epicondilitis medial (Codo de golfista): Afecta la parte interna del codo, ligada a los músculos que flexionan la muñeca hacia la palma."], note: "Afecta más a trabajadores manuales (carpinteros, pintores, uso intensivo del ratón del ordenador) que a deportistas." }, diagnosis: { title: "Evaluación Musculoesquelética", intro: "El diagnóstico clínico es muy claro y directo:", items: ["Exploración física palpando la prominencia ósea del codo y provocando dolor al resistir el movimiento de extensión o flexión de la muñeca", "Radiografías (sólo para descartar artrosis o calcificaciones en el codo si el dolor es crónico)", "Ecografía o Resonancia Magnética (para ver la magnitud del desgarro tendinoso y el daño estructural en casos que no mejoran)"], note: "" }, treatment: { title: "Rehabilitación y Alivio", intro: "Es una afección rebelde que puede tardar meses en sanar completamente:", subsections: [ { title: "Medidas Conservadoras", items: ["Reposo relativo inmediato (detener completamente la actividad repetitiva que causa el dolor)", "Fisioterapia intensiva (ejercicios excéntricos específicos para fortalecer y regenerar el tendón, es el tratamiento más efectivo a largo plazo)", "Uso de una codera o cincha epicondílea (aplicada debajo del codo para redistribuir la tensión lejos del tendón lastimado)", "Infiltraciones (las de corticosteroides ofrecen alivio rápido pero pueden debilitar el tendón; se prefiere el Plasma Rico en Plaquetas - PRP para regenerar)", "Cirugía (artroscópica o abierta) recomendada solo si el dolor severo incapacitante persiste por más de 6-12 meses"] } ], note: "La corrección ergonómica del puesto de trabajo o la mejora de la técnica deportiva es crucial para evitar recaídas." }, whenToSeekHelp: { title: "¿Cuándo acudir al traumatólogo?", intro: "Debes buscar atención médica si presentas:", items: ["Dolor persistente en la parte externa o interna del codo que empeora drásticamente al agarrar objetos (como una taza de café), dar la mano o girar el pomo de una puerta", "El dolor se irradia hacia abajo por el antebrazo hasta la muñeca", "Debilidad significativa en la mano, al punto de que los objetos se te caen por falta de fuerza de agarre", "Los tratamientos básicos de reposo, hielo y antiinflamatorios no logran mejoría alguna tras varias semanas"] } },
'Dermatitis seborreica' : { intro: "La dermatitis seborreica es una afección cutánea inflamatoria muy común que causa manchas escamosas, enrojecimiento y caspa persistente. Afecta principalmente las áreas del cuerpo con muchas glándulas productoras de grasa (sebáceas), como el cuero cabelludo, la cara y el pecho.", whatIs: { title: "¿Qué es la Dermatitis Seborreica?", text: "Es una respuesta inflamatoria crónica del sistema inmunológico a una levadura natural llamada Malassezia, que vive inofensivamente en la grasa de la piel de todas las personas. En los individuos susceptibles, esta levadura provoca una rápida multiplicación y descamación de las células cutáneas." }, types: { title: "Presentaciones por Edad", intro: "Se manifiesta de formas distintas según la etapa de la vida:", items: ["Costra láctea (en bebés recién nacidos, se presenta como parches de costras gruesas, amarillentas y grasientas en el cuero cabelludo que suelen desaparecer por sí solas antes del primer año)", "Dermatitis seborreica en adultos (condición crónica que presenta brotes y remisiones, afectando la línea del cabello, cejas, aletas de la nariz, detrás de las orejas y el centro del pecho)"], note: "No es contagiosa ni es consecuencia de una mala higiene personal. El estrés y el clima frío/seco suelen desencadenar fuertes brotes." }, diagnosis: { title: "Evaluación Dermatológica", intro: "El diagnóstico clínico suele ser inmediato y visual:", items: ["Examen directo de la piel, evaluando el aspecto característico de las escamas (a menudo amarillentas y de aspecto grasiento) sobre una base de piel roja (eritematosa)", "Rara vez se requiere una biopsia de piel (sólo si no responde al tratamiento o para diferenciarla de la psoriasis o del lupus cutáneo)"], note: "" }, treatment: { title: "Control y Mantenimiento", intro: "No tiene cura definitiva, pero sus síntomas se controlan excelentemente con rutina:", subsections: [ { title: "Opciones de Tratamiento", items: ["Champús medicados de venta libre o recetados (que contienen ketoconazol, sulfuro de selenio, piritionato de zinc o ácido salicílico) usados regularmente para controlar la levadura y la descamación", "Cremas o lociones antimicóticas tópicas para aplicar en el rostro y el cuerpo", "Corticosteroides tópicos de baja potencia (para uso a muy corto plazo para aliviar rápidamente la inflamación aguda y el enrojecimiento severo)", "Inhibidores de la calcineurina (como tacrolimus, una alternativa a los esteroides para uso facial prolongado)"] } ], note: "Para evitar recaídas en el cuero cabelludo, el champú medicado debe dejarse actuar entre 3 a 5 minutos antes de enjuagar." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es recomendable agendar una cita médica si:", items: ["La caspa severa, la picazón o el enrojecimiento no mejoran después de usar champús anticaspa comerciales durante varias semanas", "Te causa mucha vergüenza, ansiedad o afecta tus interacciones sociales debido a las escamas visibles en tu rostro o ropa", "Las áreas afectadas comienzan a doler mucho, expulsan pus, supuran líquido claro o desarrollan costras meliséricas (señales de infección bacteriana secundaria por rascarse)"] } },
'Gigantomastia' : { intro: "La gigantomastia, también conocida como hipertrofia mamaria virginal o macromastia severa, es una afección médica rara caracterizada por un crecimiento excesivo, rápido y desproporcionado del tejido mamario femenino. Puede causar dolor físico severo, problemas posturales y un grave impacto psicológico.", whatIs: { title: "¿Qué es la Gigantomastia?", text: "Es un trastorno benigno del tejido conectivo de la mama. Se define clínicamente cuando el peso del tejido mamario excede el 3% del peso corporal total de la persona, o cuando se requiere la extirpación de al menos 1.000 a 1.500 gramos por seno durante una cirugía de reducción para alcanzar un tamaño normal." }, types: { title: "Desencadenantes y Categorías", intro: "Generalmente es provocada por cambios hormonales drásticos:", items: ["Gigantomastia juvenil o virginal (ocurre durante la pubertad, los senos crecen masivamente en cuestión de meses sin causa tumoral aparente)", "Gigantomastia gestacional (crecimiento explosivo e incapacitante inducido por el embarazo)", "Gigantomastia idiopática (crecimiento espontáneo sin causa u origen hormonal obvio comprobable)", "Gigantomastia inducida por medicamentos (como efecto secundario inusual de ciertos fármacos como la penicilamina)"], note: "El crecimiento es tan rápido que la piel a menudo se estira hasta su límite, provocando estrías severas y ulceraciones." }, diagnosis: { title: "Evaluación Médica Exhaustiva", intro: "El diagnóstico es clínico pero requiere descartar otras patologías graves:", items: ["Examen físico completo por parte del ginecólogo y cirujano plástico, documentando el volumen mamario asimétrico o simétrico", "Ecografía mamaria o Mamografía (para descartar la presencia de grandes tumores mamarios como los tumores filodes gigantes, que pueden simular un crecimiento general)", "Análisis de sangre y pruebas hormonales (para evaluar los niveles de prolactina, estrógenos y función tiroidea)"], note: "" }, treatment: { title: "Reducción Quirúrgica y Alivio", intro: "Debido a que el peso extremo daña la columna y la piel, el tratamiento suele ser quirúrgico:", subsections: [ { title: "Intervenciones", items: ["Mamoplastia de reducción (la cirugía estética y reconstructiva para extirpar varios kilos de tejido mamario y piel, reubicando el pezón; es el tratamiento estándar y más efectivo)", "Mastectomía con reconstrucción simultánea (se considera solo si la gigantomastia es masiva o en casos de alto riesgo de recurrencia)", "Medicamentos antiestrógenos (como tamoxifeno) o inhibidores de prolactina (pueden detener el crecimiento en ciertos casos agudos, pero no encogen significativamente el tejido ya formado)"] } ], note: "En adolescentes con gigantomastia juvenil, la cirugía a menudo se pospone hasta que el crecimiento se estabiliza para evitar una recurrencia que requiera operar de nuevo." }, whenToSeekHelp: { title: "¿Cuándo es urgente consultar al médico?", intro: "Debes buscar ayuda médica especializada (ginecólogo o cirujano) si presentas:", items: ["Crecimiento acelerado, anormal y desproporcionado de los senos en el transcurso de pocas semanas o meses", "Dolor crónico e intratable en el cuello, los hombros y la espalda alta acompañado de surcos profundos y dolorosos causados por los tirantes del sostén", "Entumecimiento, hormigueo o debilidad en los brazos o manos (indicando que el peso del pecho está comprimiendo los nervios de la columna o el cuello)", "Aparición de infecciones crónicas por hongos, erupciones cutáneas severas o heridas abiertas y ulceradas debajo de los pliegues de los senos que no sanan"] } },
'Osteoartritis' : { intro: "La osteoartritis, también conocida como artrosis, es la forma más común de artritis y la principal causa de discapacidad crónica en adultos mayores. Ocurre cuando el cartílago protector que amortigua los extremos de los huesos se desgasta progresivamente con el tiempo.", whatIs: { title: "¿Qué es la Osteoartritis?", text: "Es una enfermedad articular degenerativa de toda la articulación, no solo del cartílago. Implica el deterioro estructural donde el hueso subyacente cambia, el revestimiento articular se inflama y pueden formarse crecimientos óseos ásperos (espolones u osteofitos). El roce de hueso con hueso produce un dolor sordo y rigidez invalidante." }, types: { title: "Ubicaciones y Origen", intro: "Se clasifica por su causa y afecta principalmente las articulaciones que soportan peso o uso repetitivo:", items: ["Osteoartritis primaria (relacionada directamente con el desgaste por la edad, genética y años de uso mecánico)", "Osteoartritis secundaria (desencadenada tempranamente por traumas previos, lesiones deportivas, obesidad extrema o deformidades anatómicas)", "Zonas más afectadas: Rodillas (gonartrosis), Caderas (coxartrosis), Manos (nódulos en los dedos), y la Columna vertebral (cervical y lumbar)"], note: "A diferencia de la artritis reumatoide, la osteoartritis no es una enfermedad autoinmune y rara vez causa síntomas sistémicos como fiebre." }, diagnosis: { title: "Evaluación Médica y Radiológica", intro: "El diagnóstico suele ser claro mediante examen y radiografías:", items: ["Evaluación clínica (búsqueda de rigidez, disminución del movimiento, hinchazón ósea, y dolor que empeora con el movimiento y mejora con el reposo)", "Radiografías simples (el método diagnóstico principal; muestran la pérdida del espacio del cartílago entre los huesos, esclerosis y espolones óseos)", "Resonancia Magnética (solo se usa en casos complejos para ver daños tempranos en tejidos blandos o meniscos que los rayos X no captan)", "Análisis del líquido articular (para descartar gota o infección)"], note: "" }, treatment: { title: "Manejo del Dolor y Movilidad", intro: "El daño estructural no se puede revertir, pero el tratamiento agresivo alivia el dolor y mejora la función enormemente:", subsections: [ { title: "Estrategias de Tratamiento", items: ["Pérdida de peso y Fisioterapia (el tratamiento no farmacológico más crucial; reducir kilos quita presión masiva a caderas y rodillas, y fortalecer los músculos estabiliza la articulación debilitada)", "Analgésicos y antiinflamatorios AINEs (ibuprofeno, naproxeno tópicos u orales para calmar el dolor y la inflamación aguda)", "Infiltraciones intraarticulares (inyecciones de corticosteroides para alivio rápido a corto plazo, o ácido hialurónico para mejorar la lubricación)", "Cirugía de reemplazo articular o artroplastia (sustitución quirúrgica de rodilla o cadera destruida por prótesis artificiales de metal/plástico, considerada cuando el dolor es intratable y limita la vida)"] } ], note: "Mantenerse en movimiento con ejercicios de muy bajo impacto (natación, bicicleta estática) es vital, ya que el sedentarismo empeora la rigidez articular." }, whenToSeekHelp: { title: "¿Cuándo acudir al reumatólogo u ortopedista?", intro: "Es momento de considerar ayuda especializada si:", items: ["El dolor articular y la rigidez son constantes, interfiriendo gravemente con tus tareas cotidianas básicas (caminar, subir escaleras, vestirte)", "Te despiertas con rigidez en las articulaciones que no cede al empezar a moverte, o el dolor te impide dormir por la noche", "La articulación se deforma visualmente, crecen nódulos óseos duros, se siente muy inestable o notas que se 'traba' o hace ruidos de crujido fuerte al usarla"] } },
'Fatiga crónica' : { intro: "El síndrome de fatiga crónica (SFC), también conocido como encefalomielitis miálgica, es una enfermedad compleja y devastadora caracterizada por un agotamiento extremo y profundo que dura al menos seis meses y no puede explicarse por ninguna otra afección médica subyacente.", whatIs: { title: "¿Qué es el Síndrome de Fatiga Crónica?", text: "Es un trastorno neurológico y multisistémico incapacitante. A diferencia del cansancio normal tras un esfuerzo, el rasgo distintivo de esta enfermedad es el 'malestar post-esfuerzo' (PEM): un empeoramiento severo y aplastante de los síntomas después de una mínima actividad física o mental, que el simple reposo no logra aliviar." }, types: { title: "Desencadenantes Potenciales", intro: "No tiene una causa única conocida, pero a menudo se desarrolla repentinamente después de eventos específicos:", items: ["Infecciones virales previas (muchos pacientes informan que el SFC comenzó tras contraer el virus de Epstein-Barr, mononucleosis infecciosa, o más recientemente como secuela del 'COVID prolongado')", "Problemas del sistema inmunológico (disfunciones autoinmunes de bajo grado)", "Desequilibrios hormonales en el eje hipotálamo-hipofisario", "Estrés o trauma físico o psicológico extremo"], note: "Suele ir acompañado de deterioro cognitivo grave (niebla mental), dolor generalizado y alteraciones graves del sueño (sueño no reparador)." }, diagnosis: { title: "Diagnóstico Clínico de Exclusión", intro: "Dado que no existe un biomarcador o prueba de sangre, el diagnóstico requiere excluir todas las demás causas posibles:", items: ["Examen físico profundo e historial clínico para confirmar la presencia del síntoma central (malestar post-esfuerzo) y la fatiga paralizante de más de 6 meses", "Extensa batería de análisis de sangre y orina (excluyendo rigurosamente anemia, hipotiroidismo, diabetes, lupus, infecciones ocultas y esclerosis múltiple)", "Estudios del sueño (para descartar la apnea del sueño u otros trastornos del descanso)", "Evaluación neurológica (para comprobar disfunción autónoma, como el síndrome de taquicardia ortostática postural o POTS, muy común en pacientes con SFC)"], note: "A menudo los pacientes sufren la incomprensión médica al presentar resultados de laboratorio 'normales' mientras están gravemente enfermos." }, treatment: { title: "Manejo de la Energía y Síntomas", intro: "No existe cura ni tratamiento farmacológico aprobado específicamente para la enfermedad; el enfoque es el alivio sintomático:", subsections: [ { title: "Estrategias de Afrontamiento", items: ["Estimulación del ritmo o 'Pacing' (la terapia más crítica: aprender a equilibrar meticulosamente el descanso y la actividad para no superar nunca el límite de energía individual y evitar recaídas (PEM))", "Tratamiento dirigido de síntomas específicos (analgésicos para el dolor muscular y articular, o medicamentos para inducir el sueño profundo)", "Fármacos reguladores autónomos o fludrocortisona (si se diagnostica problemas de presión arterial al estar de pie y mareos ortostáticos)", "Terapia de apoyo y adaptaciones de vida (obtener equipos de movilidad, ajustar horarios laborales, usar tapones o gafas oscuras para la sensibilidad a la luz y ruido)"] } ], note: "La terapia de ejercicio graduado (aumentar el ejercicio progresivamente), históricamente recomendada, hoy es rechazada y contraindicada por expertos porque suele dañar permanentemente a estos pacientes." }, whenToSeekHelp: { title: "¿Cuándo iniciar la búsqueda de diagnóstico?", intro: "Es fundamental buscar a un especialista actualizado en neuroinmunología o medicina interna si:", items: ["Tu fatiga se vuelve tan severa y discapacitante que tu capacidad funcional y de trabajar cae al 50% o menos de tu nivel previo a enfermar", "Experimentas 'choques' profundos (permanecer en cama, enfermo, con febrícula y dolor) durante días enteros después de hacer tareas triviales como bañarte o leer", "Tu memoria y concentración fallan estrepitosamente, y sientes mareos incontrolables, taquicardia o a punto de desmayarte cada vez que intentas mantenerte de pie (intolerancia ortostática)"] } },
'Trastornos cardiovasculares' : { intro: "Los trastornos o enfermedades cardiovasculares (ECV) son un grupo amplio de problemas de salud que afectan el corazón y a todos los vasos sanguíneos del cuerpo. Representan, en conjunto, la principal causa de muerte a nivel mundial, aunque la mayoría de los casos son prevenibles controlando factores de riesgo tempranos.", whatIs: { title: "¿Qué son los Trastornos Cardiovasculares?", text: "Es un término general que engloba cualquier alteración patológica que interrumpa la función de bombeo del corazón, dañe sus válvulas eléctricas o, más comúnmente, restrinja el flujo sanguíneo hacia los órganos vitales mediante el endurecimiento o bloqueo vascular (aterosclerosis)." }, types: { title: "Principales Categorías de ECV", intro: "Las manifestaciones clínicas incluyen algunas de las patologías más letales:", items: ["Cardiopatía isquémica o coronaria (el endurecimiento y bloqueo de las arterias del corazón por placas de colesterol, que desemboca en angina de pecho o infartos de miocardio letales)", "Enfermedades cerebrovasculares (ictus, derrame cerebral o accidente cerebrovascular, donde se corta el flujo de sangre al cerebro)", "Insuficiencia Cardíaca (el corazón falla, debilitándose tanto que pierde la capacidad mecánica de bombear suficiente sangre)", "Arritmias cardíacas (fallos en la red eléctrica del corazón que causan ritmos irregulares, fibrilación auricular o paros cardíacos repentinos)", "Valvulopatías y miocardiopatías (defectos en las 'puertas' o en el grosor del propio músculo del corazón)"], note: "La hipertensión arterial, la diabetes, la hipercolesterolemia y el tabaquismo son los '4 grandes' impulsores de la enfermedad." }, diagnosis: { title: "Batería de Evaluación Cardiológica", intro: "Los cardiólogos emplean múltiples estudios de imagen y eléctricos para diagnosticar las ECV:", items: ["Electrocardiograma (ECG) y Monitor Holter (registran la actividad eléctrica del corazón buscando daños estructurales previos o ritmos caóticos actuales)", "Ecocardiograma o ultrasonido cardíaco (el pilar diagnóstico para ver las válvulas, el tamaño de las cámaras y la fuerza de contracción cardíaca)", "Prueba de esfuerzo (ergometría) (se pone el corazón bajo estrés mecánico en una cinta de correr para revelar la falta de sangre oxigenada en arterias coronarias bloqueadas)", "Cateterismo cardíaco (angiografía) (la prueba definitiva e invasiva usando rayos X y contraste en tiempo real para visualizar exactamente la ubicación de bloqueos en las arterias del corazón)"], note: "" }, treatment: { title: "Intervenciones Médicas y Quirúrgicas", intro: "El tratamiento es escalonado, enfocándose en la causa primaria y la gravedad del daño tisular:", subsections: [ { title: "Manejo Cardiovascular Integral", items: ["Medicamentos crónicos potentes (Estatinas, Betabloqueantes, Inhibidores de la ECA, anticoagulantes y aspirina diaria para estabilizar placas de colesterol, controlar la presión extrema y diluir la sangre)", "Cirugía de Revascularización (como la inserción de endoprótesis vasculares 'stents' por catéter, o cirugía abierta de bypass coronario de emergencia)", "Reparación o sustitución quirúrgica/percutánea de válvulas aórticas o mitrales dañadas", "Implantación de dispositivos electrónicos (Marcapasos, cardiodesfibriladores implantables o DAI)", "Cambio drástico e innegociable de estilo de vida (abandono inmediato del tabaco, dieta cardiosaludable, rehabilitación de ejercicio físico y pérdida de peso obligatoria)"] } ], note: "Sin control médico y un cambio de vida, la enfermedad cardiovascular progresa indefectiblemente hacia ataques mortales." }, whenToSeekHelp: { title: "¿Cuándo solicitar auxilio de Emergencia (911)?", intro: "La sintomatología puede ser brusca. Actúa de inmediato sin dudar si presentas:", items: ["Dolor pesado, opresivo, constrictivo o sensación de asfixia o presión fuerte en el centro del pecho que dura más de unos minutos o se irradia hacia el brazo izquierdo, cuello o mandíbula", "Disnea extrema (falta de aire súbita), sudoración fría, palidez y mareos intensos sin haber hecho esfuerzo físico", "Pérdida súbita y alarmante de la fuerza muscular, el equilibrio o parálisis facial, confusión y dificultad repentina e incomprensible para articular palabras (signos claros y vitales de un accidente cerebrovascular en curso)", "Palpitaciones muy aceleradas o irregulares acompañadas de pérdida transitoria del conocimiento (síncope)"] } },
'Dolor de espalda inespecífico' : { intro: "El dolor de espalda inespecífico es la forma más habitual de molestia lumbar o dorsal (espalda media). Se denomina 'inespecífico' porque, a pesar del dolor o la rigidez, no existe una causa médica grave, daño neurológico ni lesión estructural identificable en la columna vertebral que lo justifique.", whatIs: { title: "¿Qué es el Dolor de Espalda Inespecífico?", text: "Es un dolor mecánico derivado frecuentemente de las estructuras de soporte de la columna: músculos, fascias o ligamentos. Suele ser el resultado de espasmos musculares transitorios provocados por sobrecargas, malas posturas prolongadas (como trabajar sentado frente a un ordenador) o movimientos bruscos inadecuados." }, types: { title: "Duración y Curso", intro: "A diferencia del dolor radicular (como la ciática, que comprime un nervio), este dolor suele limitarse a la propia espalda o glúteos y se clasifica por su temporalidad:", items: ["Agudo (dura desde unos pocos días hasta un máximo de 4 a 6 semanas; es intenso pero suele desaparecer completamente sin tratamiento especializado)", "Subagudo (se prolonga entre 4 y 12 semanas)", "Crónico (persiste ininterrumpidamente durante más de 12 semanas; es complejo de tratar y suele estar influenciado por factores psicológicos y de estrés laboral)"], note: "El 85% de las personas adultas sufrirán un episodio incapacitante de dolor lumbar inespecífico al menos una vez en su vida." }, diagnosis: { title: "Diagnóstico Clínico de Exclusión", intro: "El objetivo principal del médico no es encontrar el músculo exacto que duele, sino descartar problemas severos:", items: ["Evaluación física y cuestionario exhaustivo en busca de 'banderas rojas' clínicas (señales de alerta de infecciones, tumores o fracturas)", "Pruebas neurológicas básicas (revisión de fuerza de las piernas, sensibilidad táctil y reflejos rotulianos para confirmar que la médula espinal o los nervios no están comprometidos)", "EVITAR radiografías o resonancias magnéticas de entrada (las guías médicas desaconsejan fuertemente hacer estudios de imagen en casos agudos inespecíficos, ya que a menudo muestran 'desgaste normal por la edad' que asusta al paciente, pero que no es la verdadera causa del dolor actual)"], note: "" }, treatment: { title: "Manejo del Dolor y Reactivación", intro: "El pilar central del tratamiento no es la cama, sino mantenerse físicamente activo y sin miedo al dolor leve:", subsections: [ { title: "Terapias de Movimiento y Fármacos", items: ["Mantener la movilidad (continuar con las actividades diarias normales tanto como se tolere; el reposo en cama prolongado retrasa la curación, atrofia los músculos y empeora el dolor de espalda drásticamente)", "Terapia térmica (aplicación alternada o directa de calor local o frío en la zona para calmar espasmos)", "Medicamentos orales breves (AINEs como el ibuprofeno, o paracetamol, combinados ocasionalmente con relajantes musculares si el espasmo inicial es agudo)", "Fisioterapia activa y Kinesioterapia (aprender e integrar rutinas de fortalecimiento del núcleo abdominal/core y estiramientos lumbares para prevenir la temida cronicidad)"] } ], note: "Tratamientos pasivos (como los masajes superficiales o la quiropráctica pura) pueden aliviar brevemente, pero no previenen futuros ataques si no se corrigen la debilidad muscular y la postura." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia o descartar enfermedades graves?", intro: "Debes buscar atención de un especialista traumatólogo urgentemente si el dolor en la espalda:", items: ["Ocurre inmediatamente después de un trauma grave, una caída desde cierta altura o un accidente de tráfico considerable", "Se acompaña repentinamente de pérdida absoluta del control para contener la orina o evacuar el intestino (incontinencia)", "Provoca hormigueo profundo, pérdida de sensibilidad en la zona genital y perianal, o debilidad tan severa en las piernas que te impide mantenerte de pie (señales de compresión nerviosa grave o Síndrome de Cola de Caballo)", "Va acompañado de fiebre no explicada o una pérdida de peso involuntaria importante en pocas semanas"] } },
'Enfermedad inflamatoria pélvica (EIP)' : { intro: "La enfermedad inflamatoria pélvica (EIP) es una infección bacteriana aguda o crónica del tracto reproductor superior de la mujer. Afecta el útero, las trompas de Falopio y los ovarios. Si no se diagnostica a tiempo, puede causar daños cicatriciales irreversibles, llevando al dolor crónico y la esterilidad.", whatIs: { title: "¿Qué es la Enfermedad Inflamatoria Pélvica?", text: "Se desarrolla comúnmente cuando bacterias patógenas, usualmente provenientes de enfermedades de transmisión sexual (ETS), ascienden desde la vagina o el cuello uterino hacia los órganos pélvicos profundos. A menudo es silenciosa en sus primeras etapas, causando graves destrozos inflamatorios antes de que la mujer note algún síntoma." }, types: { title: "Agentes Infecciosos Comunes", intro: "Los microorganismos más implicados en esta infección ascendente son:", items: ["Infección por Chlamydia trachomatis (clamidia, la causa subyacente más frecuente que, con gran peligro, suele cursar sin síntomas evidentes)", "Infección por Neisseria gonorrhoeae (bacteria causante de la gonorrea, a menudo desencadena una forma más aguda y dolorosa de la EIP)", "Bacterias de la flora vaginal (en casos infrecuentes, un desequilibrio de las bacterias normales puede introducir infecciones sin ETS, por ejemplo, tras la inserción de un DIU o abortos/partos recientes)"], note: "Las duchas vaginales se desaconsejan absolutamente porque pueden empujar las bacterias de forma mecánica hacia el útero, facilitando la EIP." }, diagnosis: { title: "Diagnóstico Clínico e Invasivo", intro: "Dado que no existe una única prueba simple y definitiva, el ginecólogo evaluará múltiples parámetros:", items: ["Examen pélvico físico (buscar dolor agudo al movilizar el cuello uterino o dolor a la palpación profunda de los ovarios es el signo cardinal del diagnóstico clínico)", "Hisopados cervicales o vaginales (análisis de fluidos para confirmar la infección activa por clamidia, gonorrea u otras bacterias)", "Ecografía pélvica o transvaginal (para observar si las trompas de Falopio están agrandadas o llenas de líquido, y comprobar la presencia peligrosa de un absceso tubo-ovárico)", "Análisis de sangre y prueba de embarazo (para descartar signos de infección general y embarazo ectópico)"], note: "Si el dolor es severo y las pruebas no son concluyentes, se puede requerir una laparoscopia (cirugía con cámara) para ver la infección directamente." }, treatment: { title: "Tratamiento Antibiótico Obligatorio", intro: "El abordaje clínico es urgente para detener la inflamación y prevenir la infertilidad permanente:", subsections: [ { title: "Intervenciones", items: ["Antibióticos de amplio espectro recetados inmediatamente (suele indicarse una inyección inicial seguida de un tratamiento con pastillas orales, cubriendo siempre gonorrea y clamidia, que se debe completar durante 14 días sin falta)", "Tratamiento obligatorio a la pareja (o parejas sexuales) simultáneamente, incluso si no tienen síntomas, para curar la ETS de raíz y evitar que la mujer se reinfecte al volver a mantener relaciones", "Abstinencia sexual estricta (hasta que tanto el paciente como la pareja hayan finalizado la terapia y los síntomas hayan desaparecido)", "Hospitalización y antibióticos intravenosos (necesarios si la paciente no mejora con pastillas, está embarazada, no tolera líquidos, o si un absceso infectado amenaza con romperse en el abdomen)"] } ], note: "El tejido cicatricial que ya se ha formado en las trompas de Falopio como secuela antes del tratamiento no se curará, aumentando drásticamente el riesgo de futuros embarazos ectópicos." }, whenToSeekHelp: { title: "¿Cuándo debes acudir a Urgencias o al Ginecólogo?", intro: "Es fundamental acudir por ayuda médica el mismo día si experimentas:", items: ["Un dolor profundo, sordo y persistente de leve a severo en la parte inferior de la pelvis o el abdomen bajo", "Un flujo vaginal muy anormal, abundante, y a menudo acompañado de un fuerte mal olor (olor a pescado o fétido)", "Sangrado vaginal intermenstrual inexplicable, manchado postcoital, o dolor profundo durante las relaciones sexuales", "Aparición de los síntomas anteriores junto a un cuadro repentino de fiebre que supera los 38.3 °C y vómitos o escalofríos severos (lo cual constituye una urgencia médica)"] } },
'Dislexia' : { intro: "La dislexia es un trastorno específico y persistente del aprendizaje de origen neurobiológico. Se manifiesta como una dificultad profunda e inesperada para la lectura fluida, la escritura y la correcta decodificación de las palabras, y no guarda relación alguna con la falta de inteligencia del individuo.", whatIs: { title: "¿Qué es la Dislexia?", text: "Es una condición neurológica que afecta la forma en que el cerebro del niño o adulto procesa el lenguaje escrito. A la persona le resulta sumamente difícil relacionar las letras (ortografía) con los sonidos que estas representan (fonemas). En consecuencia, leer se convierte en un esfuerzo arduo, lento, plagado de errores y mentalmente agotador." }, types: { title: "Características y Mitos", intro: "Afecta a personas con inteligencia promedio o superior, y no es un problema visual:", items: ["Dificultades en la conciencia fonológica (dificultad crónica para separar o manipular los sonidos de las palabras orales)", "Dificultad en la memoria de trabajo verbal y velocidad de procesamiento lento (requieren más tiempo del habitual para asimilar y responder a la información que leen)", "Mito de las letras al revés (aunque escribir o leer letras en espejo como confundir 'b' con 'd' puede ocurrir en preescolar, no es el síntoma principal y definitorio de la dislexia en edades más avanzadas)"], note: "Es fuertemente hereditaria; un niño que tiene un padre con dislexia posee altas probabilidades de desarrollarla." }, diagnosis: { title: "Evaluación Psicopedagógica Profunda", intro: "Debe ser diagnosticada por un equipo interdisciplinario experto (psicólogo educativo, neuropsicólogo o logopeda):", items: ["Pruebas exhaustivas de rendimiento en lectura, fluidez y ortografía (comparando el nivel lector del paciente con el esperado para su edad y cociente intelectual)", "Evaluación de la conciencia fonológica, habilidades del lenguaje oral y capacidad de la memoria", "Revisión profunda del historial familiar, desarrollo temprano e historia escolar", "Descarte riguroso de problemas de audición y visión o barreras socioculturales que impidan el acceso a la educación"], note: "El diagnóstico formal en escuelas rara vez se confirma antes del final de primer grado, pero las señales de alerta tempranas se observan en el jardín de niños." }, treatment: { title: "Intervención Educativa y Acomodación", intro: "La dislexia es de por vida y no se cura con medicamentos; sin embargo, con métodos específicos el individuo puede aprender a leer fluidamente:", subsections: [ { title: "Estrategias Educativas", items: ["Programas intensivos de instrucción multisensorial y fonética estructurada (metodologías específicas y científicamente comprobadas, como el enfoque Orton-Gillingham, donde el niño aprende usando el oído, la visión y el tacto sistemáticamente)", "Asistencia con tutores y logopedas individualizados (para fortalecer el reconocimiento de palabras, el vocabulario y potenciar las habilidades de descodificación)", "Adaptaciones indispensables en el aula escolar y la universidad (otorgar tiempo extra significativo en los exámenes, evitar obligar al alumno a leer en voz alta frente a toda la clase y permitirle el uso de correctores ortográficos tecnológicos o calculadoras)", "Fomento de la escucha mediante audiolibros como herramienta de acceso a contenidos o software de síntesis de voz que lea textos digitales para que el niño no pierda el ritmo de aprendizaje intelectual"] } ], note: "Proteger y reforzar la salud emocional y la autoestima del niño es de máxima importancia, ya que frecuentemente desarrollan gran frustración, ansiedad extrema ante el fracaso académico y odio hacia la escuela." }, whenToSeekHelp: { title: "¿Cuáles son las señales de alerta para consultar al especialista?", intro: "Los padres o maestros deben solicitar una evaluación psicopedagógica si el niño presenta de forma continua:", items: ["En etapa preescolar: un desarrollo tardío del habla, gran dificultad e incapacidad para aprender nuevas palabras, recordar colores/letras o aprender a crear y reconocer rimas básicas infantiles", "En edad escolar temprana: lee muy por debajo del nivel esperado, invierte u omite palabras enteras frecuentemente y presenta serias y persistentes dificultades para deletrear y para recordar secuencias lógicas de cosas", "Una gran resistencia, evasión o dolor emocional evidente (llantos y frustraciones) al momento de realizar las tareas relacionadas con la escritura o tener que coger un libro"] } },
'Dolor post endodoncia' : { intro: "El dolor post endodoncia es la molestia dental y de las estructuras periapicales (hueso y ligamento) que ocurre de forma transitoria en los días posteriores a haberse sometido a un tratamiento de conductos. Es una reacción común e inflamatoria secundaria al trabajo del dentista en el interior de las raíces.", whatIs: { title: "¿Qué causa el Dolor Tras una Endodoncia?", text: "La endodoncia limpia y extrae el tejido nervioso (pulpa) severamente infectado en el núcleo de las raíces del diente. El dolor posterior o 'flare up' suele ocurrir debido a la inflamación del ligamento periodontal (la fibra que une la raíz al hueso) como resultado del trauma de las limas de limpieza, o por bacterias residuales empujadas hacia el hueso durante el propio tratamiento." }, types: { title: "Sensaciones y Presentación Normal vs. Patológica", intro: "Se divide principalmente según la severidad y duración:", items: ["Molestia normal o moderada (dolor leve y contusión en la mandíbula o en la base del diente, que empeora temporalmente al presionar o masticar; pico de dolor a las 24-48 horas que decrece poco a poco)", "Sensibilidad temporal a los estímulos térmicos (solo si las piezas adyacentes son las sensibles, ya que el diente endodonciado no puede sentir frío o calor tras retirar el nervio)", "Agudización o 'Flare up' severo (poco común, representa solo el 5% de los casos; se caracteriza por un brote agudo repentino, acompañado de una grave inflamación, dolor latiente incontrolable y a veces pus, requiriendo revisión odontológica)"], note: "El hecho de que el tratamiento haya extirpado el nervio del diente no significa que los tejidos de soporte a su alrededor pierdan la capacidad inflamatoria para doler temporalmente." }, diagnosis: { title: "Evaluación Odontológica Secundaria", intro: "Si el dolor es extremo y no mejora, el endodoncista evaluará el éxito del tratamiento inicial:", items: ["Examen de los síntomas relatados por el paciente (como mal olor intraoral repentino o incapacidad absoluta de juntar los dientes)", "Radiografía periapical dental (para observar las raíces limpias, comprobar si algún material de obturación o sellador se filtró fuera de las raíces, o confirmar si se ignoró e infectó un conducto nervioso microscópico escondido en el diente)", "Examen oclusal minucioso (comprobando con papel especial si la pasta o el arreglo temporal chocan prematuramente al cerrar la boca, siendo una causa masiva y corregible de dolor)"], note: "" }, treatment: { title: "Manejo del Dolor y Correcciones", intro: "Para aliviar esta fase inflamatoria curativa natural, los procedimientos suelen ser no invasivos:", subsections: [ { title: "Alivio y Revisión Clínica", items: ["Analgésicos y antiinflamatorios (como Ibuprofeno, a menudo indicado por el dentista para comenzar a tomarlos antes de que la anestesia de la cirugía desaparezca completamente, manteniendo la toma en horarios estrictos los primeros días)", "Ajuste oclusal simple en el consultorio (si el empaste temporal quedó unos milímetros muy alto, el dentista lo raspa ligeramente para que el diente descanse de la presión aplastante y sane el ligamento)", "Re-tratamiento de conductos o retratamiento endodóntico (necesario únicamente en el caso de que la infección original fuera resistente, la anatomía de las raíces tuviera fisuras indetectables o un nervio residual no haya sido limpiado)", "Receta de antibióticos (reservados médicamente de forma estricta para infecciones confirmadas, fiebre o hinchazones palpables y abscesos de la cara)"] } ], note: "Se debe evitar masticar alimentos duros o crujientes en el lado de la boca tratado hasta que se coloque la corona final protectora, para impedir que el diente debilitado se fracture." }, whenToSeekHelp: { title: "¿Cuándo llamar o acudir a tu endodoncista con urgencia?", intro: "Es normal un leve dolor similar a un hematoma por unos días. Llama de urgencia y exige una cita a tu dentista si:", items: ["El dolor del diente no desaparece, es severamente inaguantable o latiente (punzadas), y los analgésicos de venta libre indicados no hacen efecto alguno tras un par de días", "Descubres de pronto una hinchazón o bulto significativo en el interior o exterior de tu boca, mandíbula, cuello o encías cerca del sitio donde trabajaron", "Aparece la expulsión visible de pus o líquido de mal sabor alrededor del sitio de curación dental temporal", "Regresan inexplicablemente las antiguas y agudas sensaciones de sensibilidad y dolor al tomar frío o calor en la zona, lo cual sugiere un fallo en el sellado"] } },
'Parálisis facial' : { intro: "La parálisis facial es la pérdida repentina del movimiento voluntario de los músculos del rostro. Suele afectar exclusivamente a un lado de la cara, provocando que esa mitad parezca caída e inexpresiva, y resulta aterradora al confundirse frecuentemente con un derrame cerebral.", whatIs: { title: "¿Qué es la Parálisis Facial?", text: "Es un fallo grave en la comunicación nerviosa. Ocurre cuando el séptimo par craneal (el nervio facial que atraviesa una estrecha vía ósea y controla las expresiones, el cierre de los ojos y algunos sentidos gustativos) se inflama e hincha de forma desproporcionada o sufre algún daño orgánico, anulando su función casi por completo." }, types: { title: "Causas Primordiales", intro: "Puede ser originada por múltiples causas, por lo que es primordial diferenciarlas en urgencias:", items: ["Parálisis de Bell (por mucho la causa más común, es temporal y de inicio sumamente súbito en 48 hrs; se cree que es el resultado colateral de la reactivación de un virus, como el herpes simple o zóster, que infecta e inflama el nervio)", "Parálisis por traumatismos severos, golpes directos y fracturas en la zona del cráneo que laceran el nervio facial mecánicamente", "Daño neurológico por un accidente cerebrovascular grave o ACV (donde se daña el área motora del cerebro, no el nervio periférico directamente; esto suele implicar otras debilidades en brazos o problemas de habla)", "Secundaria a afecciones y tumores sistémicos (Enfermedad de Lyme por picaduras de garrapatas, tumores en la glándula salival parótida o tumores del propio nervio)"], note: "En la Parálisis de Bell aislada, el paciente, por lo general, se recupera total y completamente de los síntomas con el paso de tres a seis meses." }, diagnosis: { title: "Examen Neurológico Urgente", intro: "Puesto que comparte síntomas graves con los infartos cerebrales, la evaluación debe descartar daños mayores al instante:", items: ["Examen neurológico clínico y veloz de observación pidiendo al paciente parpadear, fruncir el ceño y sonreír. (Diferencia clave: en la Parálisis de Bell la frente está caída e inexpresiva; en un ACV central, la persona aún puede levantar y arrugar la frente a pesar de la parálisis inferior)", "Pruebas de neuroimagen, como la Resonancia Magnética o la Tomografía Computarizada de la cabeza (para encontrar signos ocultos de tumores compresivos, esclerosis múltiple o infartos en zonas profundas)", "Electromiografía o EMG (típicamente realizada semanas después, para comprobar si los nervios o la masa muscular subyacente muestran actividad eléctrica en fase de recuperación)"], note: "" }, treatment: { title: "Terapia Acelerada y Protección del Ojo", intro: "Para las de Bell, el pilar central del éxito es la administración inmediata de medicina antiinflamatoria en los primeros 3 días:", subsections: [ { title: "Cura y Rehabilitación", items: ["Corticosteroides orales recetados de urgencia (como la prednisona, utilizados fuertemente durante la primera semana para reducir brutal y drásticamente la enorme hinchazón del nervio atrapado en el hueso)", "Medicamentos antivirales pesados (a veces combinados junto al esteroide si el doctor sospecha del letal virus de la culebrilla)", "Cuidado intensivo y estricto del ojo paralizado (el ojo no se puede cerrar, impidiendo parpadear, lo que lleva a la resequedad destructiva; el paciente debe instilar lágrimas artificiales constantemente cada hora, usar pomadas lubricantes de noche y colocar esparadrapos en el ojo para dormir)", "Fisioterapia facial progresiva y rehabilitación neuromuscular frente a un espejo (masajear y ayudar mecánicamente al músculo para evitar que su atrofia paralítica se convierta en encogimiento o contracciones permanentes a largo plazo)"] } ], note: "La descompresión quirúrgica, antaño practicada comúnmente, ya no se recomienda debido a los inaceptables altos riesgos de provocar sordera irreparable u originar daños nerviosos faciales irreparables irreversibles." }, whenToSeekHelp: { title: "¿Cuándo es indispensable dirigirse al hospital de urgencia?", intro: "Es fundamental la revisión médica inmediata ante una cara caída para descartar una amenaza vital:", items: ["Amaneces o notas que repentinamente desarrollaste en pocas horas una profunda parálisis incontrolable o una evidente debilidad extrema en un solo lado completo de tu cara", "Descubres un sarpullido severo acompañado de ampollas dolorosas que aparece alrededor del oído dañado o la zona ocular (indicio innegable y grave de Síndrome de Ramsay Hunt)", "La debilidad facial se agrava y avanza, viéndose acompañada por la incapacidad aguda y preocupante para mantener en alto los brazos o las piernas, ceguera repentina repentina, o tartamudeo en las palabras (signo de alerta roja inminente de un infarto o hemorragia cerebral inminente)"] } },
'Apatía sexual' : { intro: "La apatía sexual, a menudo referida como Deseo Sexual Hipoactivo o trastorno de falta de deseo, es un problema psicosexual caracterizado por la carencia recurrente y sustancial, o la ausencia total, de fantasías o intereses sexuales en absoluto. Suele ser fuente principal de conflictos de pareja profundos y ansiedad personal intensa.", whatIs: { title: "¿Qué es la Apatía Sexual?", text: "Es la indiferencia severa y apagada hacia la intimidad sexual. La persona o individuo carece de una motivación endógena normal para buscar la estimulación genital, e incluso la evitan de forma general en todas sus formas. No implica de manera estricta que haya un daño físico para el coito, sino que la respuesta química o la pulsión biológica cerebral se haya disipado." }, types: { title: "Situaciones de Presentación y Prevalencia", intro: "Este trastorno complejo puede fluctuar y clasificarse como:", items: ["Secundario o Adquirido (la causa más habitual; un nivel otrora saludable de la función del interés erótico ha desaparecido después del surgimiento de nuevos cambios biológicos, problemas relacionales o eventos de estrés grave crónicos)", "Apatía Primaria Crónica (falta completa del impulso de atracción física o ausencia del deseo sexual íntimo en un individuo desde la madurez del inicio hasta en la actualidad continuada)", "Trastorno Específico y Relacional o Situacional (donde la falta y evitación total recae estricta o focalizadamente contra una única persona particular íntima, conservando atracción total hacia agentes externos o autosexuales)"], note: "Suele afectar desproporcionadamente más a mujeres maduras menopáusicas, aunque los casos clínicos de los hombres de vida media también van constantemente al alza médica debido a variables modernas." }, diagnosis: { title: "Evaluaciones Profundas de Causas Subyacentes", intro: "Los especialistas sexuales y galenos deben diagnosticar sistemática y muy holísticamente todas las dimensiones:", items: ["Interrogatorio médico en clínica detallado sin tabús, identificando minuciosamente si interfiere un problema biológico (como deficiencias severas graves de niveles endocrinos y testosterónicos orgánicos, deficiencia nutricional profunda, y especialmente los terribles estragos e impacto total por prescripción psiquiátrica de consumo masivo de medicación farmacéutica de tipo antidepresivo y ansiolítico)", "Consulta relacional de la evaluación psicométrica en una extensa y cuidada entrevista (buscando si problemas profundos ocultos subyacentes de las interacciones cotidianas íntimas, infidelidades pasadas o falta abismal comunicacional emocional son la causa verdadera real para que el cerebro repulse el sexo)", "Chequeo físico de anomalías anatómicas o de dolores que produzcan dispareunias dolorosas asociadas"], note: "" }, treatment: { title: "Recuperación Plena y Terapia Erótica Conductual", intro: "Al tratarse normalmente de una afectación mixta psico-corporal, los regímenes para recuperar una intimidad natural son un enfoque doble:", subsections: [ { title: "Terapia y Enfoque Farmacológico", items: ["Modificación farmacéutica inmediata supervisada (la eliminación y cambio de las medicinas psiquiátricas problemáticas conocidas que adormecen y cortan el reflejo químico sexual por versiones y terapias de antidepresivos no depletivos de dopamina)", "Reemplazo integral endocrino de terapias o administración temporal segura (en casos donde se confirman pérdidas vitales estrogénicas dolorosas vulvares en la posmenopausia grave de las pacientes, o hipogonadismo innegable en los análisis para testosterona en déficit orgánico de hombres)", "Terapia relacional en consultas y psicológica (sesiones centradas en dinámicas de comportamiento sexual, ejercicios controlados e interacciones con un sexólogo terapeuta sin focalizaciones directas y estrictamente a la meta y el rendimiento genital, aprendiendo así en casa a des-angustiar paulatinamente la ansiedad)", "Utilización prescrita de estimulantes neuromoduladores modernos para la química funcional psiquiátrica enfocados al deseo cerebral del paciente pre-menopáusico femenino en bajas dosis"] } ], note: "Aceptar a un paciente estresado y presionado al encuentro íntimo es completamente la táctica más contraproducente y errónea posible que agravará indudablemente más toda fobia sexual." }, whenToSeekHelp: { title: "¿En qué circunstancia se torna clínicamente imprescindible solicitar terapia o apoyo?", intro: "Es fundamental programar cita médica especialista de la vida sexual reproductiva del ser, cuando:", items: ["Constatas que la drástica interrupción íntima de cualquier forma de la libido o rechazo produce agobio abrumador personal propio, culpa en las interacciones y gran tristeza general perniciosa para tu rutina", "Las problemáticas asociadas a este problema de cama han desencadenado fuertemente un grave daño colateral e irritante que pone al borde mismo de todo quiebre tu estabilidad marital general", "Empiezas al mismo punto a registrar incapacidad, fallos biológicos o síntomas físicos acompañantes muy dolorosos al ser tocada (dispareunia de la vulva) en los encuentros en que tu intentabas forzarte física o falsamente mentalizada"] } },
'Ictericia del recién nacido' : { intro: "La ictericia del recién nacido es la coloración amarillenta progresiva de la piel y de la parte blanca de los ojos de los recién nacidos, indicativa de altos niveles de una sustancia celular en sangre. Se trata de un problema médico en infantes extremadamente común, que requiere atención cuidadosa temprana y especializada en los casos altos.", whatIs: { title: "¿Qué es la Ictericia Neonatal o del Recién Nacido?", text: "Es un estado químico metabólico resultante o derivado directamente debido a la excesiva acumulación celular del pigmento bilirrubina, provocado cuando existe un alto proceso recambio en el torrente de descomposición muy grande de sus glóbulos rojos por exceso al nacimiento natural. Ocurre muy habitualmente por el simple hecho general en que un hígado normal hepático infantil de la inmadura edad del infante bebé no se logra dar el abasto y procesar veloz el reciclado, expulsión ni eliminación masiva." }, types: { title: "Causas Naturales e Incrementos Grave o Crónicos", intro: "Normalmente transitoria, sus grados son patologías divididas vitales:", items: ["Ictericia fisiológica e inicial (es benigna y la más mayormente observada general; aparece sin riesgos a los dos, y puede durar días inofensivamente hasta desaparecer conforme todo bebé sano, o alimentado sano en su dieta de pecho maternal en primera semana normal se desarrolla en crecimiento interno hepático)", "Ictericia del seno lactante materno y de lactancia a pecho nutricional (una reacción prolongada general tardía que se debe y es a sustancias inhibidoras o muy lenta del alimento natural de la pecho inicial maternal de sustrato general, la insuficiencia muy grande temprana a mamar general deshidratan fuertemente en leche inicial)", "Ictericia y enfermedad patológica destructora (un problema grave severo y grave anormal rápido orgánico desencadenado letalmente desde primerísimo comienzo horas; debido a incompatibilidades de grupo mortales grandes en los factor de grupos RH sanguíneo con las incompatibles toxinas defensivas maternales, grandes letales hemorragias severas de golpe, anomalía u obstrucciones severos)"], note: "Niveles letales muy exacerbados graves sanguíneos venosos, dejados desatendidos a propósito en días o tiempo extremo crónico, generan peligrosamente patologías que desencadenan kernícterus agudo, una sordera extrema y daños neurológicos paralizantes letales irreversibles directos en cerebro." }, diagnosis: { title: "Pruebas Tempranas de Niveles Cuidadosos Infantes", intro: "El especialista evaluará meticulosa y exhaustivamente de urgencia a tiempo para evitar daños cerebrales letales tempranos neonatales:", items: ["El principal chequeo ocular diagnóstico de presión ligera externa infantil, revisando cutáneo ocular y visual y aplicando leve de yemas presión digital en los primeros días post hospitalario frontal y extremidades desde neonatología para revisión observacional aguda", "Medición rápida superficial con dispositivo no letal transcutáneo en sensor fotométrico de bilirrubinómetro directamente iluminando piel del general neonato por lectura de reflectancia de destello leve de pantalla al tejido frontal", "La extracción general clínica de comprobación urgente química analítica en nivel exacto y completo serológico en el talón de suero venoso o por extracciones generales con exactitud de la lectura (obligatorio y rutinaria en neonatos al alta cuando superan márgenes y los índices superan)"], note: "" }, treatment: { title: "Solución Fototerapéutica Curativa General", intro: "Los niveles altos graves venenosos requieren descender la toxicidad en sangre, empleándose:", subsections: [ { title: "Atención Terapéutica Neonatal", items: ["Implementación clínica y uso indispensable agudo general en hospital en cama y equipo fototerapia (luz de espectro especializado potente y no letal en cama intensiva azul que interactúa celularmente química natural degradando bilirrubina pesada y que ayuda a orinar/defecar rápido todo al neonato)", "Fomento riguroso en estimulación de incremento a la toma de leche general o tomas infantiles maternal intensivas con tomas artificiales general (que incrementan fuertemente todos lo movimientos y de sistema y de hidratación purificadora evacuativa fecal)", "Intercambio en transfusión letal extrema de volumen exsanguinotransfusión generalizada sistémica sanguínea curativa directa (una urgencia técnica general si fracasa todo intensiva en neonatos letales de incompatibilidad general severas, sacando la pequeña porción toxica reemplazándola general con una normal de los donantes de sangre universal y buena)"] } ], note: "Es estrictamente erróneo el obsoleto método arriesgado peligroso del infante solar exposición desprotegida aguda a exterior como un tratamiento no curativo; usar exclusivamente curativo la especializada hospitalaria." }, whenToSeekHelp: { title: "¿En qué casos la evaluación médica representa de inmediato y urgente la emergencia hospitalaria inmediata al bebé?", intro: "Exige el ingreso en neonatología u atención de hospital inmediata en caso e de que su infante presente signos mortales inusuales letales o agravamiento de que los tonos como ser en si:", items: ["Percibas de pronto aparición del desarrollo severo general intenso amarillento grave diseminado agudo, y letal o su tonalidad corporal empieza avanzar o profundizar a partes extremas estomacal, su gran barriga y a piernas pies intensivamente", "Detectas un profundo infante bebé en exceso dormido o estado en sueño y debilidad a una intensidad letárgica anormal letal profunda, apático o presenta rigidez letal del cuerpo o está demasiado apático, rechaza total todo a ingerir un mínimo general o alimentación y la mamila", "Ves y presentas o te enfrentas y atestiguas llantos letales desgarradores, extremadamente insoportablemente penetrante e inusual o muy letales del dolor incontrolable incesantes o arqueo cuello convulsivo hacia el nivel la letal hacia espaldilla arqueo cuello anormales de todo infante dolor incesante", "Tu su y de la piel blanco del blanco esférico del ojo infantil y globos oculares internos infantes se tintan en grave esclerótica profunda color y tono amarillo y amarillo fuerte oscuro muy fuerte"] } },
'Hipertensión inducida por el embarazo' : { intro: "La hipertensión inducida por el embarazo es la presión arterial alta que se desarrolla después de la semana 20 de gestación. Si no se controla, puede progresar a condiciones graves como la preeclampsia, poniendo en riesgo la salud de la madre y del bebé.", whatIs: { title: "¿Qué es la Hipertensión inducida por el embarazo?", text: "Es un aumento anormal de la presión arterial durante la gestación en mujeres que previamente tenían una presión normal. A diferencia de la hipertensión crónica, esta suele resolverse después del parto, pero requiere un monitoreo médico estricto para evitar complicaciones orgánicas." }, types: { title: "Tipos de Trastornos Hipertensivos", intro: "Se clasifica según su gravedad y síntomas acompañantes:", items: ["Hipertensión gestacional (presión alta sin proteínas en la orina ni daño a otros órganos)", "Preeclampsia (presión alta acompañada de proteínas en la orina o daño en riñones/hígado)", "Eclampsia (preeclampsia severa que provoca convulsiones)", "Síndrome HELLP (una complicación grave que afecta la sangre y el hígado)"], note: "Tener hipertensión gestacional aumenta el riesgo de desarrollar preeclampsia." }, diagnosis: { title: "Detección y Monitoreo", intro: "El obstetra la detecta en los controles prenatales rutinarios:", items: ["Medición de la presión arterial en cada consulta", "Análisis de orina (para detectar proteinuria)", "Análisis de sangre (para revisar la función del hígado, riñones y plaquetas)", "Ecografías fetales y monitoreo del ritmo cardíaco del bebé"], note: "" }, treatment: { title: "Tratamiento y Manejo", intro: "El tratamiento depende de la presión arterial y de las semanas de gestación:", subsections: [ { title: "Medidas Clínicas", items: ["Monitoreo frecuente de la presión arterial y reposo relativo", "Medicamentos antihipertensivos seguros para el embarazo", "Corticosteroides (para acelerar el desarrollo pulmonar del bebé si se prevé un parto prematuro)", "Parto inducido o cesárea (la única 'cura' definitiva para la preeclampsia, realizada cuando el riesgo supera el beneficio de prolongar el embarazo)"] } ], note: "La aspirina en dosis bajas se puede recetar en el primer trimestre para prevenirla en mujeres de alto riesgo." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a urgencias obstétricas inmediatamente si tienes:", items: ["Dolor de cabeza intenso y persistente que no cede con analgésicos", "Cambios en la visión (visión borrosa, ver manchas, destellos de luz o pérdida temporal de visión)", "Dolor intenso en la parte superior derecha del abdomen o debajo de las costillas", "Hinchazón repentina y severa (edema) en la cara o las manos"] } },
'Hidrocefalia' : { intro: "La hidrocefalia es la acumulación excesiva de líquido cefalorraquídeo (LCR) en las cavidades profundas del cerebro (ventrículos). El exceso de líquido aumenta el tamaño de los ventrículos y ejerce una presión perjudicial sobre el tejido cerebral.", whatIs: { title: "¿Qué es la Hidrocefalia?", text: "A menudo llamada 'agua en el cerebro', es una condición neurológica donde el líquido cefalorraquídeo no fluye, no se absorbe o se produce en exceso. Esta acumulación crea una presión intracraneal alta que puede dañar irreversiblemente el cerebro." }, types: { title: "Tipos de Hidrocefalia", intro: "Puede ser congénita (presente al nacer) o adquirida:", items: ["Hidrocefalia comunicante (el LCR fluye pero no se absorbe adecuadamente)", "Hidrocefalia no comunicante u obstructiva (el flujo del LCR está bloqueado entre los ventrículos)", "Hidrocefalia de presión normal (ocurre en adultos mayores, el líquido se acumula pero la presión suele ser normal, causando demencia o problemas de marcha)", "Hidrocefalia ex vacuo (el cerebro se encoge por lesión o enfermedad, y el LCR llena el espacio extra)"], note: "En los bebés, provoca un agrandamiento anormal y rápido de la cabeza." }, diagnosis: { title: "Evaluación Neurológica", intro: "El diagnóstico se confirma mediante imágenes del cerebro:", items: ["Ecografía cerebral (la prueba inicial habitual en bebés con las fontanelas aún abiertas)", "Resonancia Magnética (RM) del cerebro (la prueba más detallada para identificar la causa del bloqueo en niños y adultos)", "Tomografía Computarizada (TC)", "Punción lumbar (especialmente en adultos para evaluar si la extracción de líquido mejora los síntomas)"], note: "" }, treatment: { title: "Intervención Quirúrgica", intro: "La hidrocefalia requiere tratamiento quirúrgico para drenar el líquido:", subsections: [ { title: "Opciones de Tratamiento", items: ["Sistema de derivación o 'shunt' (un tubo flexible colocado quirúrgicamente que drena el exceso de líquido desde el cerebro hacia el abdomen, donde se absorbe; suele ser de por vida)", "Ventriculostomía endoscópica del tercer ventrículo (ETV) (cirugía donde se hace un pequeño agujero en el ventrículo para permitir que el líquido fluya, evitando el shunt en ciertos pacientes)", "Terapias de rehabilitación (fisioterapia y terapia ocupacional para tratar daños cognitivos o motores previos)"] } ], note: "Las derivaciones pueden bloquearse o infectarse, por lo que requieren vigilancia de por vida." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca atención médica de inmediato si tú, tu hijo o un familiar con un shunt presenta:", items: ["Vómitos repetidos e inexplicables, o letargo y somnolencia extremos", "En bebés: un bulto tenso en la parte superior de la cabeza (fontanela), o los ojos miran hacia abajo ('ojos en sol poniente')", "En adultos con shunt: fiebre, enrojecimiento a lo largo del trayecto del tubo, dolores de cabeza severos o confusión repentina"] } },
'Trastorno bipolar afectivo' : { intro: "El trastorno bipolar afectivo es una condición de salud mental crónica que provoca cambios extremos e inusuales en el estado de ánimo, la energía y la capacidad de funcionamiento, alternando entre episodios de manía (euforia) y depresión profunda.", whatIs: { title: "¿Qué es el Trastorno Bipolar Afectivo?", text: "Es un desequilibrio neuroquímico en el cerebro que causa fluctuaciones anímicas severas. Los episodios anímicos pueden durar días, semanas o meses, interrumpiendo gravemente la vida diaria, las relaciones y el juicio, diferenciándose claramente de los altibajos normales." }, types: { title: "Clasificación de los Trastornos Bipolares", intro: "Existen tres diagnósticos principales:", items: ["Trastorno Bipolar tipo I (se caracteriza por al menos un episodio maníaco grave, a menudo acompañado de episodios depresivos intensos; puede incluir psicosis)", "Trastorno Bipolar tipo II (caracterizado por episodios depresivos mayores y episodios de hipomanía, que es una forma menos extrema de manía)", "Trastorno Ciclotímico (períodos breves y crónicos de síntomas hipomaníacos y depresivos menos severos que duran al menos dos años)"], note: "El riesgo de suicidio es significativamente alto durante la fase depresiva o en episodios mixtos." }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "No existen pruebas de sangre para el trastorno bipolar; el diagnóstico es clínico:", items: ["Evaluación psiquiátrica exhaustiva (historial detallado de los cambios de humor, patrones de sueño y comportamientos)", "Registro de los estados de ánimo diarios (mood charting)", "Examen físico para descartar causas médicas como el hipertiroidismo o el uso de sustancias"], note: "Frecuentemente se diagnostica erróneamente como depresión unipolar si el paciente no menciona sus episodios de euforia pasados." }, treatment: { title: "Estabilización y Mantenimiento", intro: "Es una enfermedad de por vida que requiere tratamiento continuo, incluso cuando el paciente se siente bien:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Medicamentos estabilizadores del estado de ánimo (como el litio o el ácido valproico, que son el pilar del tratamiento)", "Antipsicóticos atípicos o antidepresivos (usados con sumo cuidado para evitar inducir un episodio maníaco)", "Psicoterapia (Terapia Cognitivo-Conductual, psicoeducación y terapia del ritmo interpersonal y social para mantener rutinas de sueño estrictas)", "Terapia electroconvulsiva (TEC) para episodios de manía severa o depresión grave que no responden a medicamentos"] } ], note: "El abandono de la medicación cuando el paciente 'se siente bien' es la causa número uno de recaídas devastadoras." }, whenToSeekHelp: { title: "¿Cuándo es urgente pedir ayuda?", intro: "Acude a urgencias psiquiátricas de inmediato si:", items: ["Sientes una necesidad nula de dormir durante días sin sentirte cansado, acompañado de ideas de grandeza, compras compulsivas o comportamiento temerario (manía aguda)", "Tienes pensamientos, planes o intenciones activas de autolesionarte o cometer suicidio", "Experimentas alucinaciones auditivas, visuales o delirios (desconexión de la realidad)"] } },
'Artritis' : { intro: "La artritis es un término general que abarca más de 100 enfermedades y afecciones relacionadas con la inflamación de las articulaciones. Causa dolor, rigidez y disminución del rango de movimiento, empeorando típicamente con la edad.", whatIs: { title: "¿Qué es la Artritis?", text: "Es la inflamación e hinchazón de una o más articulaciones del cuerpo. Dependiendo del tipo, la artritis puede destruir el cartílago que amortigua los huesos, inflamar el revestimiento articular o estar causada por la acumulación de cristales o infecciones." }, types: { title: "Tipos Más Comunes", intro: "Los dos tipos principales son la artrosis y la artritis reumatoide:", items: ["Artrosis u Osteoartritis (el tipo más común, es el daño por 'desgaste' del cartílago articular a lo largo de los años o tras una lesión)", "Artritis Reumatoide (una enfermedad autoinmune donde el sistema inmunológico ataca el revestimiento de las articulaciones)", "Gota (causada por cristales de ácido úrico que se acumulan en la articulación, frecuentemente en el dedo gordo del pie)", "Artritis psoriásica (asociada a la enfermedad de la piel psoriasis)", "Artritis infecciosa (causada por una bacteria o virus que entra en la articulación)"], note: "" }, diagnosis: { title: "Diagnóstico Reumatológico", intro: "El médico identificará el tipo específico mediante:", items: ["Examen físico para revisar la hinchazón, el enrojecimiento, el calor local y la movilidad de las articulaciones", "Análisis de sangre y líquido articular (para buscar marcadores de inflamación, autoanticuerpos o cristales de ácido úrico)", "Radiografías (para ver pérdida de cartílago y espolones óseos), Ecografías o Resonancias Magnéticas"], note: "" }, treatment: { title: "Manejo del Dolor y Movilidad", intro: "El tratamiento se enfoca en aliviar los síntomas y mejorar el funcionamiento articular:", subsections: [ { title: "Intervenciones", items: ["Medicamentos (analgésicos, AINEs, cremas tópicas o corticosteroides; para la artritis autoinmune se usan FARMEs y agentes biológicos)", "Fisioterapia y ejercicios de bajo impacto (como la natación) para fortalecer los músculos alrededor de la articulación", "Pérdida de peso (para reducir drásticamente el estrés sobre las rodillas y las caderas)", "Cirugía (reparación articular, fusión articular o reemplazo total de la articulación en casos severos de daño irreparable)"] } ], note: "El reposo excesivo empeora la rigidez; mantenerse activo es fundamental para la salud articular." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es recomendable buscar atención médica si:", items: ["El dolor articular, la rigidez o la hinchazón duran más de tres días", "Experimentas rigidez matutina severa que dura más de una hora tras despertarte", "La articulación está muy caliente, enrojecida o se acompaña de fiebre (señal de una posible infección articular, requiere urgencia)"] } },
'Esterilidad' : { intro: "La esterilidad, a menudo utilizada como sinónimo de infertilidad, es la incapacidad biológica de concebir un embarazo después de al menos un año de relaciones sexuales regulares sin el uso de métodos anticonceptivos.", whatIs: { title: "¿Qué es la Esterilidad?", text: "Es un problema del sistema reproductivo que impide lograr o mantener un embarazo. Clínicamente, esterilidad puede referirse a la incapacidad absoluta de concebir (por ausencia de órganos), mientras que la infertilidad implica una dificultad que a menudo es tratable." }, types: { title: "Causas Principales", intro: "El problema puede originarse en cualquier parte del proceso reproductivo:", items: ["Factor femenino (problemas de ovulación como SOP, trompas de Falopio obstruidas, endometriosis, miomas o anomalías uterinas)", "Factor masculino (bajo conteo de espermatozoides, baja motilidad espermática, varicocele o problemas de eyaculación)", "Factor mixto o inexplicado (cuando se combinan problemas de ambos miembros de la pareja, o cuando todas las pruebas resultan normales)"], note: "La edad es el factor más determinante en la fertilidad femenina, disminuyendo drásticamente después de los 35 años." }, diagnosis: { title: "Estudios de Fertilidad", intro: "Ambos miembros de la pareja deben someterse a evaluación simultáneamente:", items: ["Análisis de semen (espermiograma) para evaluar la cantidad, forma y movimiento de los espermatozoides", "Análisis de sangre hormonales femeninos (para verificar la reserva ovárica y la ovulación)", "Ecografía transvaginal e Histerosalpingografía (una radiografía con contraste para ver si las trompas están abiertas)", "Pruebas genéticas en casos seleccionados"], note: "" }, treatment: { title: "Reproducción Asistida y Tratamientos", intro: "Existen múltiples opciones según la causa detectada:", subsections: [ { title: "Opciones Terapéuticas", items: ["Inducción de la ovulación (fármacos como el clomifeno para estimular los ovarios)", "Inseminación artificial / Intrauterina (IIU) (colocar esperma concentrado directamente en el útero durante la ovulación)", "Fecundación in vitro (FIV) (extraer óvulos, fecundarlos en el laboratorio e implantar el embrión en el útero)", "Inyección Intracitoplasmática de Espermatozoides (ICSI) para casos de infertilidad masculina severa", "Cirugía para corregir obstrucciones, varicocele o endometriosis"] } ], note: "El estrés emocional durante los tratamientos de fertilidad es inmenso; el apoyo psicológico es altamente recomendado." }, whenToSeekHelp: { title: "¿Cuándo acudir a un especialista en fertilidad?", intro: "Es el momento de consultar a un médico reproductivo si:", items: ["Has intentado quedar embarazada durante un año (si tienes menos de 35 años) o durante 6 meses (si tienes 35 años o más)", "La mujer tiene períodos muy irregulares, ausentes, o sufre de dolor menstrual extremo (posible endometriosis)", "El hombre tiene antecedentes de problemas testiculares, problemas sexuales o cirugías de próstata/hernias previas", "Has tenido múltiples abortos espontáneos consecutivos"] } },
'Condiloma acuminado' : { intro: "El condiloma acuminado, también conocido como verrugas genitales o anogenitales, es una de las enfermedades de transmisión sexual (ETS) más comunes. Son pequeñas protuberancias o crecimientos carnosos que aparecen en o alrededor de los genitales y el ano.", whatIs: { title: "¿Qué es el Condiloma Acuminado?", text: "Es una infección cutánea causada por cepas de bajo riesgo del Virus del Papiloma Humano (VPH), principalmente los tipos 6 y 11. Aunque son altamente contagiosas por contacto de piel a piel durante el sexo, estas cepas no causan cáncer." }, types: { title: "Características", intro: "Las lesiones pueden variar en su apariencia:", items: ["Pequeñas protuberancias del color de la piel, rosadas o marrones", "Agrupaciones de verrugas que toman la forma de una pequeña coliflor", "Lesiones planas que a veces son tan pequeñas que no se pueden ver a simple vista"], note: "Pueden aparecer en la vulva, paredes vaginales, cuello uterino, pene, escroto, ano, y rara vez en la boca o garganta." }, diagnosis: { title: "Diagnóstico Médico", intro: "El médico las diagnostica mediante observación directa:", items: ["Examen físico visual de la zona genital y anal", "Aplicación de ácido acético (vinagre) que puede volver blancas las verrugas difíciles de ver", "Prueba de Papanicolaou y prueba de VPH (para mujeres, para detectar cambios cervicales causados por cepas asociadas de alto riesgo)", "Rara vez biopsia (solo si sangran, tienen un aspecto atípico o no responden al tratamiento)"], note: "" }, treatment: { title: "Eliminación de Lesiones", intro: "El tratamiento elimina la verruga visible, pero no elimina el virus del cuerpo:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos tópicos recetados (como imiquimod, podofilina o ácido tricloroacético, que el paciente o el médico aplican para destruir el tejido)", "Crioterapia (congelación con nitrógeno líquido)", "Electrocauterización (quemar las verrugas con corriente eléctrica)", "Escisión quirúrgica o tratamiento con láser (para verrugas muy grandes o extensas)"] } ], note: "Las verrugas genitales no se deben tratar nunca con medicamentos de venta libre para verrugas comunes (como las de las manos), ya que el tejido genital es demasiado delicado. La vacuna contra el VPH previene su aparición." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes programar una visita médica si:", items: ["Tú o tu pareja notáis bultos o crecimientos inusuales en la zona genital o anal", "Experimentas picazón, ardor, sangrado o dolor en la zona genital", "Las verrugas interfieren con la micción o causan incomodidad durante las relaciones sexuales"] } },
'Degeneración macular relacionada con la edad (AMD)' : { intro: "La degeneración macular relacionada con la edad (AMD o DMAE) es una enfermedad ocular progresiva que destruye la visión central aguda, la cual es necesaria para ver los objetos claramente y para tareas comunes como leer, reconocer rostros y conducir.", whatIs: { title: "¿Qué es la Degeneración Macular?", text: "Es el deterioro de la mácula, la pequeña zona central de la retina en la parte posterior del ojo. A medida que las células de la mácula envejecen y se descomponen, la imagen enviada al cerebro se vuelve borrosa o presenta un punto ciego en el centro del campo visual. No afecta la visión periférica (lateral)." }, types: { title: "Tipos de DMAE", intro: "Se divide en dos formas principales:", items: ["DMAE Seca (el 80-90% de los casos; progresa lentamente, caracterizada por el adelgazamiento de la mácula y la acumulación de depósitos de proteínas amarillentas llamados drusas)", "DMAE Húmeda o exudativa (menos común pero mucho más grave y rápida; vasos sanguíneos anormales crecen debajo de la retina y gotean sangre o líquido, causando daños severos y cicatrices rápidas en la mácula)"], note: "La forma seca puede convertirse repentinamente en húmeda en cualquier momento." }, diagnosis: { title: "Examen Oftalmológico", intro: "El oftalmólogo realizará pruebas específicas de la retina:", items: ["Examen del fondo de ojo con dilatación pupilar (para buscar drusas o líquido bajo la retina)", "Prueba de la Rejilla de Amsler (una cuadrícula de líneas; si las líneas rectas se ven onduladas o faltan, es un signo clásico de DMAE)", "Tomografía de Coherencia Óptica (OCT) (un escáner que crea imágenes transversales de la retina para identificar adelgazamiento o acumulación de líquidos)", "Angiografía con fluoresceína (se inyecta un tinte para detectar vasos sanguíneos que gotean en la DMAE húmeda)"], note: "" }, treatment: { title: "Manejo y Tratamiento", intro: "No tiene cura, pero se puede frenar su progresión, especialmente en la forma húmeda:", subsections: [ { title: "Opciones Terapéuticas", items: ["Para DMAE Seca: No hay tratamiento médico definitivo, pero se recomienda una combinación específica de vitaminas (fórmula AREDS2 con luteína, zeaxantina, vitamina C, E y Zinc) para retrasar la pérdida de visión", "Para DMAE Húmeda: Inyecciones intravítreas de medicamentos anti-VEGF (como ranibizumab o aflibercept, que se inyectan en el ojo repetidamente para detener el crecimiento y el goteo de los vasos anormales)", "Terapia fotodinámica o fotocoagulación con láser (rara vez utilizada hoy en día para sellar vasos)"] } ], note: "Las ayudas para la baja visión (lupas especiales, luces potentes) son fundamentales para la rehabilitación visual." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al oftalmólogo?", intro: "Es fundamental acudir inmediatamente al oftalmólogo si notas:", items: ["Una alteración repentina y rápida de tu visión central, donde los objetos se ven borrosos de la nada", "Las líneas rectas (como los marcos de las puertas, persianas o postes) comienzan a verse distorsionadas, onduladas o torcidas", "Aparece una mancha oscura, un área vacía o un punto ciego fijo en el centro exacto de tu visión", "Los colores te parecen menos brillantes de lo habitual"] } },
'Dolor oncológico' : { intro: "El dolor oncológico es el dolor que experimentan los pacientes con cáncer. Puede deberse a la propia enfermedad o a los tratamientos oncológicos. El dolor puede ser agudo, crónico, intermitente o constante, y varía enormemente según el tipo de cáncer y la tolerancia de la persona.", whatIs: { title: "¿Qué es el Dolor Oncológico?", text: "Es una experiencia sensorial y emocional desagradable asociada con el cáncer. Puede ocurrir porque un tumor presiona nervios, huesos u órganos (dolor somático/visceral), porque el cáncer invade el hueso, o como efecto secundario de la quimioterapia, radioterapia o cirugía." }, types: { title: "Tipos de Dolor en el Cáncer", intro: "Se clasifica para guiar su tratamiento:", items: ["Dolor nociceptivo (dolor sordo o pulsátil por daño tisular, común cuando el cáncer afecta huesos o músculos)", "Dolor neuropático (dolor ardiente, punzante, u hormigueo intenso causado por daño o presión a los nervios periféricos o a la médula espinal)", "Dolor irruptivo (picos de dolor severo repentino que 'rompen' la barrera de la medicación para el dolor continuo)"], note: "Tener cáncer no significa que debas vivir con dolor; casi todos los dolores oncológicos pueden controlarse." }, diagnosis: { title: "Evaluación del Dolor", intro: "El manejo exitoso depende de una comunicación clara con el equipo médico:", items: ["Uso de escalas del dolor (clasificar el dolor del 0 al 10)", "Diario del dolor (registrar cuándo ocurre, qué lo alivia, qué lo empeora y cómo afecta el sueño o estado de ánimo)", "Pruebas de imagen (RM o TC) o gammagrafías óseas si hay sospecha de que el tumor ha crecido, presiona un nuevo nervio o se ha metastatizado al hueso"], note: "" }, treatment: { title: "Alivio y Cuidados Paliativos", intro: "El tratamiento sigue la 'Escalera Analgésica' de la OMS:", subsections: [ { title: "Escalones de Tratamiento", items: ["Analgésicos no opioides (paracetamol o AINEs para dolor leve)", "Opioides débiles (tramadol, codeína para dolor moderado)", "Opioides fuertes (morfina, fentanilo, oxicodona, metadona para dolor severo continuo)", "Medicamentos coadyuvantes (antidepresivos o anticonvulsivos que son muy efectivos para el dolor neuropático)", "Bloqueos nerviosos, bombas de infusión intratecal o radioterapia paliativa (para encoger el tumor que causa presión)"] } ], note: "El miedo a la adicción a los opioides no debe impedir su uso en pacientes oncológicos; bajo supervisión médica, son seguros y necesarios." }, whenToSeekHelp: { title: "¿Cuándo informar al oncólogo?", intro: "Debes comunicarte con tu equipo médico inmediatamente si:", items: ["El dolor es nuevo, ha cambiado de intensidad drásticamente, o surge en un lugar de tu cuerpo donde no te dolía antes", "Los medicamentos recetados no logran aliviar el dolor irruptivo o sus efectos desaparecen antes de la siguiente dosis", "Los analgésicos te causan efectos secundarios insoportables, como náuseas severas, somnolencia extrema, confusión o estreñimiento paralizante", "El dolor te impide dormir, comer, moverte o te causa desesperación emocional profunda"] } },
'Labio leporino y paladar hendido' : { intro: "El labio leporino y el paladar hendido son defectos de nacimiento o malformaciones congénitas que ocurren cuando los tejidos de la cara y la boca del bebé no se fusionan adecuadamente durante el desarrollo fetal en el útero.", whatIs: { title: "¿Qué son el Labio Leporino y el Paladar Hendido?", text: "El labio leporino es una abertura o fisura en el labio superior. El paladar hendido es una abertura en el techo de la boca (paladar). Pueden presentarse solos o juntos, y de manera unilateral (un solo lado) o bilateral (ambos lados), afectando severamente la alimentación y el habla del recién nacido." }, types: { title: "Presentaciones Clínicas", intro: "Varían en extensión y gravedad:", items: ["Labio leporino incompleto (una muesca en el labio que no llega hasta la nariz)", "Labio leporino completo (la fisura se extiende desde el labio, a través de la encía superior, hasta la base de la nariz)", "Paladar hendido incompleto (hendidura en el paladar blando en la parte posterior de la boca)", "Paladar hendido completo (abertura en el paladar duro y blando, conectando la boca directamente con la cavidad nasal)"], note: "Suelen ser anomalías aisladas, pero también pueden formar parte de síndromes genéticos más complejos." }, diagnosis: { title: "Detección Prenatal y al Nacer", intro: "Se diagnostican fácilmente por observación directa:", items: ["Ecografía prenatal (a menudo puede detectar un labio leporino a partir de la semana 13 de embarazo, aunque el paladar hendido es más difícil de ver antes del nacimiento)", "Examen físico del recién nacido (el médico inspecciona visualmente la cara y el interior de la boca del bebé inmediatamente al nacer)"], note: "" }, treatment: { title: "Cirugía y Rehabilitación", intro: "Requiere un equipo multidisciplinario durante varios años (cirujanos plásticos, ortodoncistas, logopedas):", subsections: [ { title: "Fases del Tratamiento", items: ["Modificaciones en la alimentación (uso de biberones especiales diseñados para bebés con fisuras antes de la cirugía)", "Reparación del labio leporino (cirugía realizada generalmente entre los 3 y 6 meses de edad para cerrar el labio y mejorar la apariencia/función)", "Reparación del paladar hendido (cirugía realizada alrededor de los 10 a 12 meses de edad para cerrar el techo de la boca y prevenir problemas de habla y oído)", "Cirugías de seguimiento (injertos óseos en la encía a los 8-10 años, cirugías ortognáticas o rinoplastias en la adolescencia)", "Terapia del habla y ortodoncia especializada durante la niñez"] } ], note: "Los niños con paladar hendido son muy propensos a infecciones de oído crónicas y acumulación de líquido, por lo que a menudo requieren tubos de drenaje en el tímpano." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda urgente para el bebé?", intro: "Contacta al pediatra o especialista inmediatamente si tu bebé con una hendidura presenta:", items: ["Signos de deshidratación o pérdida de peso porque no puede alimentarse ni succionar adecuadamente con los biberones especiales", "Dificultad para respirar, atragantamiento frecuente o coloración azulada durante la alimentación", "Fiebre, dolor de oído evidente (se tira de las orejas, llora inconsolablemente) o secreción del oído (signo de infección)", "Leche o alimentos que salen continuamente por la nariz de manera que le causan ahogo"] } },
'Cáncer del estómago' : { intro: "El cáncer de estómago, o cáncer gástrico, es el crecimiento de células malignas en el revestimiento del estómago. Es un cáncer que tiende a desarrollarse lentamente durante muchos años y, a menudo, no presenta síntomas alarmantes en sus etapas iniciales.", whatIs: { title: "¿Qué es el Cáncer del Estómago?", text: "Es una enfermedad oncológica donde se forman tumores en las capas del estómago. Comienza casi siempre en la capa más interna productora de moco (adenocarcinoma). Antes de que se desarrolle un verdadero cáncer, a menudo ocurren cambios precancerosos invisibles en el revestimiento interno (gastritis atrófica grave)." }, types: { title: "Tipos de Cáncer Gástrico", intro: "Se clasifican según su ubicación y el tipo de célula:", items: ["Adenocarcinoma (representa el 90-95% de los cánceres de estómago; se subdivide en tipo intestinal y tipo difuso, que es más agresivo)", "Linfoma gástrico (cáncer del tejido del sistema inmunológico en la pared del estómago)", "Tumores del estroma gastrointestinal (GIST) (tumores de los tejidos musculares o de soporte)", "Tumores carcinoides o tumores neuroendocrinos (comienzan en células productoras de hormonas)"], note: "La infección crónica por la bacteria Helicobacter pylori, las dietas altas en alimentos ahumados/salados y el tabaquismo son los principales factores de riesgo." }, diagnosis: { title: "Detección y Estadificación", intro: "Cuando aparecen síntomas digestivos crónicos, se realizan pruebas:", items: ["Endoscopia digestiva alta (el examen principal y fundamental: permite ver el tumor directamente y tomar una biopsia de confirmación)", "Biopsia gástrica (análisis patológico del tejido bajo el microscopio)", "Tomografía Computarizada (TC) de tórax, abdomen y pelvis o PET scan (para ver si el tumor ha invadido otros órganos, el hígado o los ganglios linfáticos, para la estadificación)", "Ecografía endoscópica (EUS) (para ver qué tan profundamente ha penetrado el tumor en las capas de la pared estomacal)"], note: "" }, treatment: { title: "Tratamiento Oncológico", intro: "Depende del estadio de la enfermedad y la ubicación del tumor:", subsections: [ { title: "Opciones Quirúrgicas y Médicas", items: ["Resección endoscópica de la mucosa (para cánceres extremadamente tempranos confinados a la superficie superficial)", "Gastrectomía subtotal o total (extirpación parcial o total del estómago quirúrgicamente, conectando el esófago directamente al intestino delgado)", "Quimioterapia perioperatoria (usada antes de la cirugía para encoger el tumor y después para destruir células remanentes)", "Radioterapia y Quimiorradioterapia", "Terapia dirigida (como Trastuzumab si el tumor es HER2 positivo) e inmunoterapia (en cáncer avanzado)"] } ], note: "Tras una gastrectomía total, los pacientes deben hacer cambios radicales en su dieta, comiendo porciones muy pequeñas y tomando suplementos de vitamina B12 de por vida." }, whenToSeekHelp: { title: "¿Cuándo consultar al gastroenterólogo?", intro: "El cáncer gástrico suele enmascararse como una indigestión común. Busca evaluación médica urgente si presentas:", items: ["Sensación de saciedad precoz severa (sentirte muy lleno después de comer solo unos pocos bocados de comida)", "Pérdida de peso involuntaria y significativa, o una falta de apetito profunda y constante", "Dolor abdominal vago pero persistente localizado por encima del ombligo (boca del estómago) que no cede", "Vómitos frecuentes (a veces con sangre o como 'posos de café'), dificultad para tragar o heces muy negras y pegajosas (sangre oculta)", "Indigestión crónica, acidez estomacal severa o náuseas constantes que no mejoran con antiácidos"] } },
'Acné vulgar' : { intro: "El acné vulgar es la enfermedad cutánea inflamatoria más común. Ocurre cuando los folículos pilosos de la piel se obstruyen con células muertas y sebo (grasa), creando un ambiente donde proliferan bacterias, lo que resulta en la aparición de 'granos' o espinillas.", whatIs: { title: "¿Qué es el Acné Vulgar?", text: "Es un trastorno crónico de la unidad pilosebácea de la piel. Suele aparecer en el rostro, la frente, el pecho, la parte superior de la espalda y los hombros, ya que estas áreas tienen la mayor cantidad de glándulas sebáceas. Es más común durante la adolescencia debido a los cambios hormonales, pero persiste en muchos adultos." }, types: { title: "Tipos de Lesiones Acnéicas", intro: "Se clasifica por la severidad y el tipo de lesión predominante:", items: ["Comedones abiertos (puntos negros) y comedones cerrados (puntos blancos) - acné no inflamatorio leve", "Pápulas y pústulas (granos rojos y granos con cabeza de pus) - acné inflamatorio moderado", "Nódulos y quistes (bultos profundos, sólidos o llenos de líquido, muy dolorosos) - acné severo o noduloquístico, con alto riesgo de dejar cicatrices permanentes"], note: "Frotar o pellizcar los granos empuja la infección más profundamente, empeorando la inflamación y causando cicatrices." }, diagnosis: { title: "Evaluación Clínica", intro: "El dermatólogo puede diagnosticarlo con una simple revisión visual:", items: ["Examen físico de la piel para determinar la gravedad (leve, moderado o severo) y evaluar la presencia de cicatrices", "Interrogatorio sobre la rutina de cuidado de la piel, uso de cosméticos (comedogénicos), ciclo menstrual o uso de medicamentos (como corticosteroides o testosterona)"], note: "No se necesitan pruebas de laboratorio a menos que se sospeche un desequilibrio hormonal grave (como el síndrome de ovario poliquístico en mujeres adultas)." }, treatment: { title: "Tratamiento Dermatológico", intro: "El tratamiento busca reducir el sebo, acelerar el recambio celular y matar las bacterias; los resultados tardan semanas en verse:", subsections: [ { title: "Terapias Tópicas y Sistémicas", items: ["Tratamientos tópicos de venta libre o recetados (Peróxido de benzoilo, ácido salicílico o retinoides tópicos como adapaleno o tretinoína)", "Antibióticos tópicos u orales (clindamicina, doxiciclina) para reducir bacterias e inflamación a corto plazo", "Medicamentos hormonales (píldoras anticonceptivas combinadas o espironolactona para el acné hormonal en mujeres)", "Isotretinoína oral (un retinoide muy potente reservado para el acné quístico grave o resistente; requiere estrictos controles médicos debido a sus efectos secundarios y riesgo de defectos congénitos)", "Terapias de luz o extracciones dermatológicas de comedones en el consultorio"] } ], note: "La consistencia diaria en la rutina de cuidado de la piel (limpieza suave y uso de protectores solares sin aceite) es fundamental." }, whenToSeekHelp: { title: "¿Cuándo acudir al dermatólogo?", intro: "Es recomendable buscar ayuda médica especializada si:", items: ["Los tratamientos y cremas de venta libre no han aclarado tu piel después de un uso constante de 2 a 3 meses", "El acné es quístico, muy doloroso y profundo bajo la piel, formando bultos grandes", "Estás notando la aparición de cicatrices oscuras (hiperpigmentación) o hundidas (cicatrices atróficas) al curarse los granos", "La afección cutánea te está causando una grave angustia emocional, baja autoestima o evitación social"] } },
'Enfermedades gastrointestinales' : { intro: "Las enfermedades gastrointestinales (GI) comprenden una amplísima variedad de afecciones que pueden afectar cualquier parte del tracto digestivo, desde el esófago hasta el estómago, el intestino delgado, el intestino grueso (colon), el recto y los órganos accesorios (hígado, vesícula biliar y páncreas).", whatIs: { title: "¿Qué son las Enfermedades Gastrointestinales?", text: "Son trastornos que impiden el proceso normal de la digestión, absorción de nutrientes o eliminación de desechos. Se dividen en trastornos funcionales (donde el tracto parece normal pero no se mueve o funciona bien) y trastornos estructurales (donde hay daño visible, inflamación o tumores)." }, types: { title: "Categorías Principales", intro: "Las patologías se agrupan en diversas categorías mayores:", items: ["Enfermedades funcionales (Síndrome de Intestino Irritable - SII, dispepsia funcional, estreñimiento crónico)", "Enfermedades por inflamación y úlceras (Enfermedad por Reflujo Gastroesofágico - ERGE, gastritis, úlceras pépticas)", "Enfermedad Inflamatoria Intestinal (EII) (trastornos autoinmunes severos como la Enfermedad de Crohn y la Colitis Ulcerosa)", "Problemas estructurales o mecánicos (hernias, hemorroides, fisuras anales, diverticulitis)", "Cánceres gastrointestinales (cáncer de colon, estómago, páncreas, esófago)"], note: "Los síntomas comunes transversales incluyen acidez, náuseas, dolor abdominal, hinchazón, diarrea o estreñimiento." }, diagnosis: { title: "Diagnóstico Gastroenterológico", intro: "El especialista utiliza pruebas según los síntomas de alarma:", items: ["Endoscopia digestiva alta (para visualizar el esófago, estómago y duodeno y tomar biopsias)", "Colonoscopia (el examen estándar para visualizar el colon, diagnosticar EII o extirpar pólipos precancerosos)", "Pruebas de imagen (Ecografía abdominal, TC o Resonancia Magnética para evaluar hígado, páncreas y vesícula)", "Análisis de laboratorio (análisis de sangre para anemia o inflamación, y de heces para sangrado oculto, bacterias, calprotectina o parásitos)", "Pruebas de función motora (manometría esofágica o estudios de tránsito)"], note: "" }, treatment: { title: "Manejo Integral", intro: "El tratamiento es tan variado como las propias enfermedades:", subsections: [ { title: "Opciones de Tratamiento General", items: ["Modificaciones en la dieta y el estilo de vida (el pilar fundamental para enfermedades funcionales como el SII o ERGE)", "Medicamentos sintomáticos (antiácidos, inhibidores de bomba de protones, antiespasmódicos, laxantes, antidiarreicos)", "Fármacos inmunosupresores o terapia biológica (para controlar y detener el daño autoinmune en Crohn y Colitis Ulcerosa)", "Antibióticos (para erradicar la bacteria H. pylori en úlceras o tratar diverticulitis)", "Intervenciones quirúrgicas (para extirpar tumores, vesículas enfermas, apéndices inflamados o secciones dañadas del intestino)"] } ], note: "La detección temprana (cribado), como la colonoscopia rutinaria después de los 45 años, es vital para prevenir los cánceres GI." }, whenToSeekHelp: { title: "¿Cuándo es urgente consultar al médico?", intro: "Debes buscar atención médica de emergencia o consulta rápida si presentas síntomas de alarma (Banderas Rojas):", items: ["Sangre visible en el vómito, o vómitos con aspecto de 'posos de café'", "Sangrado rectal activo, o heces muy oscuras, pegajosas y alquitranadas", "Dolor abdominal agudo, repentino e insoportable que empeora rápidamente, o abdomen muy rígido al tacto", "Pérdida de peso involuntaria severa acompañada de dificultad persistente para tragar alimentos sólidos o líquidos", "Piel y ojos amarillentos (ictericia), fiebre alta incesante o incapacidad para retener líquidos por 24 horas"] } },
'Enuresis' : { intro: "La enuresis, conocida comúnmente como mojar la cama, es la micción involuntaria durante el sueño que ocurre a una edad en la que se espera que el niño ya tenga control nocturno de la vejiga (generalmente después de los 5 a 7 años). Es un problema muy común y la mayoría de los niños lo superan de forma natural.", whatIs: { title: "¿Qué es la Enuresis Nocturna?", text: "Es la incapacidad del cerebro para despertar al niño cuando su vejiga está llena durante la noche. No es pereza, ni una señal de mala conducta o rebeldía. Es un retraso madurativo del sistema nervioso que controla la vejiga, y a menudo tiene un fuerte componente genético familiar." }, types: { title: "Clasificación Clínica", intro: "Se divide principalmente en dos tipos según el historial del niño:", items: ["Enuresis primaria (el niño nunca ha logrado un período de seis meses seguidos de noches secas; es la forma más común y se debe a un desarrollo inmaduro del control de la vejiga o baja producción de la hormona antidiurética por la noche)", "Enuresis secundaria (el niño vuelve a mojar la cama después de haber tenido control nocturno durante al menos seis meses; a menudo provocada por estrés emocional, estreñimiento, una infección urinaria o aparición de diabetes infantil)"], note: "Afecta a los niños varones con mucha más frecuencia que a las niñas." }, diagnosis: { title: "Evaluación Pediátrica", intro: "El pediatra buscará descartar causas orgánicas ocultas:", items: ["Historial médico detallado sobre los hábitos de bebida del niño, el estrés familiar y los antecedentes de padres mojando la cama", "Examen físico para descartar problemas neurológicos de la columna inferior o estreñimiento severo masivo (que presiona la vejiga)", "Análisis de orina básico (para descartar una infección del tracto urinario o niveles altos de glucosa indicativos de diabetes tipo 1)"], note: "No se requieren pruebas de imagen complejas a menos que haya síntomas diurnos graves (incontinencia despierto)." }, treatment: { title: "Manejo, Paciencia y Alarmas", intro: "El enfoque principal debe ser comprensivo, sin castigos ni humillaciones:", subsections: [ { title: "Intervenciones", items: ["Modificación de hábitos (limitar severamente la ingesta de líquidos 2 horas antes de dormir, ir al baño justo antes de acostarse)", "Alarmas de enuresis o detectores de humedad (el tratamiento a largo plazo más efectivo; un sensor en el pijama o colchón suena cuando detecta la primera gota, condicionando y enseñando al cerebro del niño a despertar con la vejiga llena)", "Medicamentos (Desmopresina, un fármaco oral que disminuye temporalmente la producción de orina durante la noche; a menudo usado para eventos puntuales como campamentos o pijamadas, pero la recaída es común al suspenderlo)", "Tratar el estreñimiento crónico subyacente (si el recto está lleno de heces duras, presiona y reduce la capacidad de la vejiga)"] } ], note: "Premiar las noches secas (refuerzo positivo) y usar protectores de colchón ayudan a reducir la ansiedad del niño y de los padres." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Es recomendable programar una cita médica si:", items: ["El niño sigue mojando la cama frecuentemente después de los 7 años de edad, y le está causando problemas de autoestima o aislamiento social", "El niño empieza a mojar la cama repentinamente después de haber estado seco por las noches durante varios meses (enuresis secundaria)", "La enuresis se acompaña de dolor o ardor al orinar, fiebre, sed inusual extrema o ronquidos muy fuertes (posible apnea del sueño)", "El niño también experimenta incontinencia de orina y escapes incontrolables durante el día estando despierto"] } },
'Amelogénesis imperfecta' : { intro: "La amelogénesis imperfecta es un trastorno hereditario y genético raro que afecta la formación, el espesor y la calcificación del esmalte dental (la capa externa dura y protectora del diente). Afecta tanto a los dientes de leche como a los permanentes, haciéndolos muy frágiles y propensos al deterioro.", whatIs: { title: "¿Qué es la Amelogénesis Imperfecta?", text: "Es una anomalía estructural donde una mutación genética interrumpe la producción normal de las proteínas del esmalte durante la formación del diente. Como resultado, los dientes erupcionan con un esmalte deficiente, extremadamente delgado, blando, con hoyuelos o descolorido, dejándolos vulnerables a un desgaste masivo y sensibilidad severa." }, types: { title: "Clasificación Clínica", intro: "Existen tres tipos principales basados en la fase del defecto del esmalte:", items: ["Tipo Hipoplásico (defecto en la cantidad de esmalte; el esmalte es duro pero extremadamente delgado, haciendo que los dientes sean muy pequeños y tengan hoyuelos o surcos profundos)", "Tipo Hipocalcificado (defecto en la mineralización inicial; el esmalte tiene un grosor normal pero es muy blando, pastoso, opaco y se desgasta o descascarilla rápidamente al masticar)", "Tipo Hipomaduro (defecto en la maduración final; el esmalte es poroso, se tiñe fácilmente de amarillo/marrón y se astilla del diente subyacente con facilidad)"], note: "Suele asociarse a una 'mordida abierta anterior' esquelética y a problemas crónicos de hipersensibilidad dental." }, diagnosis: { title: "Diagnóstico Odontológico", intro: "El odontopediatra o dentista la identifica rápidamente de forma clínica y radiográfica:", items: ["Examen intraoral visual y táctil que revela la apariencia anómala, rugosa o amarillenta (exponiendo la dentina) de prácticamente todos los dientes del arco, no solo de uno", "Radiografías dentales (el esmalte normalmente aparece radiopaco y brillante; en la AI, el esmalte defectuoso puede verse casi igual de oscuro que la dentina o ser invisible por su delgadez)", "Historial médico y familiar (dado que es un trastorno hereditario autosómico o ligado al cromosoma X, a menudo los padres también tienen dientes afectados)"], note: "" }, treatment: { title: "Restauración Integral y Prevención", intro: "El tratamiento es continuo, complejo y comienza en la primera infancia para proteger los dientes y prevenir el dolor crónico:", subsections: [ { title: "Opciones de Tratamiento", items: ["Prevención agresiva de caries (aplicación frecuente de barnices de flúor de alta concentración, selladores dentales y uso de enjuagues desensibilizantes y pastas de dientes recetadas)", "Restauraciones en dientes de leche o jóvenes (uso de coronas preformadas de acero inoxidable o circonio en niños para cubrir y proteger inmediatamente los molares frágiles que se están desmoronando, permitiendo que el niño mastique sin dolor)", "Restauraciones estéticas en dientes permanentes (uso de carillas de porcelana, resinas compuestas de recubrimiento total o coronas completas de cerámica en la adolescencia y edad adulta para reconstruir la forma y color del diente)", "Tratamiento de ortodoncia, e incluso cirugía ortognática en la edad adulta, para corregir problemas asociados de maloclusión o mordida abierta"] } ], note: "Sin tratamiento protésico temprano, los dientes pueden desgastarse rápidamente hasta la línea de las encías, requiriendo extracciones y múltiples implantes." }, whenToSeekHelp: { title: "¿Cuándo acudir urgentemente al odontopediatra?", intro: "Es fundamental la revisión dental temprana. Debes llevar a tu hijo al especialista si observas:", items: ["Los primeros dientes de leche brotan con un color amarillo u opaco, textura áspera, con manchas tiza o surcos visibles, o si parecen desmoronarse o romperse con la comida blanda", "El niño se queja de dolor muy agudo o se niega a comer alimentos/bebidas frías, calientes o dulces debido a una hipersensibilidad dental generalizada extrema", "Los dientes permanentes (a partir de los 6 años) erupcionan descoloridos y sin el brillo blanco perlado y liso del esmalte normal", "Tienen un historial familiar claro de familiares cercanos que perdieron todos sus dientes jóvenes debido a que 'sus dientes eran blandos'"] } },
'Deshidratación' : { intro: "La deshidratación ocurre cuando el cuerpo pierde más líquidos de los que ingiere, lo que provoca que el organismo no tenga suficiente agua y fluidos para llevar a cabo sus funciones normales y vitales. Es una condición peligrosa que puede progresar desde una molestia leve hasta una emergencia potencialmente mortal.", whatIs: { title: "¿Qué es la Deshidratación?", text: "Es el déficit de agua corporal total, a menudo acompañado de una peligrosa pérdida de electrolitos vitales (sodio, potasio, cloruro). Si la pérdida de líquidos no se reemplaza rápidamente, las células se encogen, la presión arterial cae drásticamente y órganos vitales como los riñones, el corazón y el cerebro pueden comenzar a fallar." }, types: { title: "Causas Frecuentes y Vulnerabilidad", intro: "Cualquiera puede deshidratarse, pero el riesgo es mayor por ciertas causas:", items: ["Pérdidas gastrointestinales (la causa médica más común, provocada por gastroenteritis aguda con diarrea severa o vómitos repetidos)", "Aumento de la temperatura corporal o ambiental (fiebre muy alta constante, o sudoración extrema por ejercicio prolongado en clima cálido, provocando un golpe de calor)", "Micción excesiva o pérdida renal (diabetes no diagnosticada o mal controlada, o por el abuso de medicamentos diuréticos)", "Falta de ingesta (enfermedad en la garganta que impide tragar, demencia avanzada o personas ancianas que pierden la sensación de sed)"], note: "Los bebés, los niños pequeños y los adultos mayores son extremadamente vulnerables, y la deshidratación puede ser fatal para ellos en muy poco tiempo." }, diagnosis: { title: "Evaluación Clínica", intro: "El diagnóstico suele ser rápido, basado en los signos físicos y síntomas:", items: ["Examen físico general revisando signos vitales (presión arterial baja que cae al ponerse de pie -hipotensión ortostática-, frecuencia cardíaca rápida o taquicardia)", "Evaluación de las membranas mucosas (boca y lengua muy secas) y de la elasticidad de la piel (turgencia cutánea: un pliegue de piel pellizcado que tarda en volver a su sitio)", "Análisis de orina (para ver si la orina está concentrada, oscura y densa, u observar ausencia total de orina)", "Análisis de sangre en casos severos (para verificar la función renal midiendo la creatinina y detectar desequilibrios severos de electrolitos)"], note: "" }, treatment: { title: "Rehidratación y Prevención", intro: "El tratamiento primordial y urgente es la reposición inmediata de fluidos y sales:", subsections: [ { title: "Niveles de Tratamiento", items: ["Deshidratación leve a moderada: Rehidratación oral. El tratamiento más efectivo es beber Sales de Rehidratación Oral (SRO) de farmacia, que contienen la mezcla perfecta de agua, sales y azúcar; en su defecto, agua o caldos claros, bebiendo a pequeños sorbos frecuentes (evitar jugos azucarados, gaseosas o café, que empeoran la diarrea)", "Deshidratación severa: Intervención hospitalaria de urgencia. Requiere la administración inmediata de líquidos y electrolitos por vía intravenosa (IV) a través de una vena para reponer el volumen sanguíneo y salvar la vida", "Tratamiento de la causa subyacente (fármacos antieméticos para detener los vómitos o medicamentos para bajar la fiebre)"] } ], note: "Las bebidas isotónicas deportivas son útiles para atletas sanos, pero no son la mejor opción médica para niños enfermos con diarrea debido a su alta concentración de azúcar." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica letal?", intro: "Acude a la sala de emergencias (Urgencias) inmediatamente, no esperes, si tú, tu hijo o un adulto mayor presenta signos severos como:", items: ["Letargo extremo, somnolencia profunda, confusión mental inexplicable, irritabilidad extrema constante, o pérdida de la conciencia y desmayos", "Incapacidad para retener ningún tipo de líquido en el estómago durante más de unas horas (vómitos de todo lo que bebe)", "Ausencia de lágrimas al llorar (en niños) y pañales secos durante tres o más horas seguidas", "Ausencia total de orina durante más de 8 horas, u orina de un color ámbar/marrón muy oscuro", "Respiración anormalmente rápida y palpitaciones cardíacas descontroladas", "Ojos profundamente hundidos en sus cuencas, o la fontanela (la zona blanda superior) muy hundida en la cabeza de un bebé"] } },
'Resistencia a la insulina' : { intro: "La resistencia a la insulina es un problema metabólico oculto en el que las células de los músculos, la grasa y el hígado no responden bien a la insulina, impidiéndoles absorber fácilmente la glucosa de la sangre. Es el paso previo y la causa principal de la prediabetes y la diabetes tipo 2.", whatIs: { title: "¿Qué es la Resistencia a la Insulina?", text: "Es una falla en la señalización celular. El páncreas produce insulina, la 'llave' que abre las células para que entre el azúcar y se use como energía. En este estado, las 'cerraduras' de las células se vuelven insensibles o resistentes. Para compensar, el páncreas bombea cantidades masivas de insulina (hiperinsulinemia) intentando forzar a las células a abrirse." }, types: { title: "Efectos y Factores de Riesgo", intro: "Eventualmente, si el páncreas se agota y no puede producir tanta insulina, el azúcar en sangre sube a niveles tóxicos:", items: ["Exceso de grasa abdominal o visceral (la causa y promotor más importante, la grasa alrededor de la cintura es metabólicamente activa y bloquea la insulina)", "Sedentarismo extremo (el músculo inactivo pierde sensibilidad a la insulina)", "Síndrome de Ovario Poliquístico (SOP) y Síndrome Metabólico (condiciones estrechamente ligadas a la resistencia a la insulina)", "Dietas ultraprocesadas de alto índice glucémico y el consumo crónico de azúcares y fructosa líquida"], note: "Generalmente no presenta síntomas obvios, salvo que se desarrolle una afección cutánea llamada acantosis nigricans (piel oscura y aterciopelada en cuello o axilas)." }, diagnosis: { title: "Detección y Exámenes Sanguíneos", intro: "El endocrinólogo o médico internista puede sospechar de ella y diagnosticarla mediante:", items: ["Análisis de glucosa plasmática en ayunas y prueba de Hemoglobina A1C (para ver si el nivel de azúcar ya está en rango de prediabetes)", "Análisis de niveles de insulina en ayunas (niveles de insulina excesivamente altos en ayunas indican que el cuerpo está compensando la resistencia; índice HOMA-IR)", "Evaluación del perfil lipídico (típicamente se presentan triglicéridos muy altos y colesterol 'bueno' HDL muy bajo, lo que sugiere fuerte resistencia a la insulina)", "Examen físico buscando signos como aumento excesivo de la circunferencia de la cintura o presión arterial límite"], note: "" }, treatment: { title: "Reversión y Manejo del Estilo de Vida", intro: "La resistencia a la insulina es una condición altamente reversible con cambios radicales y comprometidos:", subsections: [ { title: "Estrategias Metabólicas", items: ["Pérdida de peso intencionada (perder solo del 5% al 7% del exceso de grasa corporal mejora dramáticamente la sensibilidad celular)", "Ejercicio físico regular y constante (el entrenamiento de fuerza o levantar pesas es crítico, ya que el músculo activo 'quema' glucosa incluso sin insulina)", "Cambios nutricionales drásticos (reducir severamente los carbohidratos refinados, dulces, harinas blancas y azúcares añadidos; optar por fibra, proteínas y grasas saludables)", "Medicamentos orales (como la Metformina, que ayuda a sensibilizar las células y frenar la producción de glucosa del hígado en personas de alto riesgo de diabetes)"] } ], note: "No se puede medicar una mala dieta; los cambios en el estilo de vida son el tratamiento principal, no un complemento." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico y hacerse pruebas?", intro: "Es fundamental realizarte un chequeo metabólico de prevención si no tienes síntomas, pero presentas:", items: ["Un aumento considerable de peso reciente, específicamente notando que tu abdomen o perímetro de cintura se ha expandido mucho (forma de 'manzana')", "Oscurecimiento anormal, engrosamiento o manchas de piel con textura aterciopelada en la parte posterior o los lados de tu cuello, axilas o ingles (Acantosis nigricans)", "Antecedentes de padres o hermanos con diabetes tipo 2, o si tuviste diabetes gestacional durante un embarazo", "Aparición de múltiples acrocordones (pequeños crecimientos o 'verrugas' de piel colgante, especialmente en el cuello y pecho) y fatiga intensa o somnolencia extrema después de comer carbohidratos"] } },
'Abuso sexual infantil' : { intro: "El abuso sexual infantil (ASI) es la participación, coerción o uso de un niño en cualquier actividad o comportamiento de índole sexual. Es uno de los crímenes y traumas más devastadores que puede sufrir un menor, causándole daños psicológicos, emocionales y físicos profundos a corto y largo plazo.", whatIs: { title: "¿Qué es el Abuso Sexual Infantil?", text: "Es cualquier interacción sexual entre un niño (quien no puede dar su consentimiento informado por ley y desarrollo) y un adulto o un niño significativamente mayor o en posición de poder. Abarca desde tocamientos, caricias, exhibicionismo o toma de imágenes explícitas, hasta la penetración o violación. El abusador suele usar la manipulación, el engaño o las amenazas para mantener el abuso en secreto." }, types: { title: "Dinámica y Contextos Comunes", intro: "Contrario a los mitos populares, rara vez ocurre por extraños en la calle:", items: ["Abuso intrafamiliar o incesto (cometido por padres, padrastros, hermanos mayores, tíos o abuelos; es uno de los escenarios más comunes y silenciados)", "Abuso por conocidos de confianza (maestros, entrenadores, cuidadores, líderes religiosos, amigos de la familia)", "Abuso extrafamiliar (cometido por extraños o personas de contacto esporádico)", "Explotación y abuso sexual en línea (grooming, extorsión sexual o producción/consumo de material de abuso infantil a través de internet)"], note: "El abusador típicamente dedica tiempo a ganarse la confianza del niño y de la familia, un proceso conocido como 'grooming' (embaucamiento)." }, diagnosis: { title: "Detección y Reconocimiento de Señales", intro: "Los niños rara vez revelan el abuso directamente por miedo o confusión. Los adultos deben estar alerta a cambios abruptos:", items: ["Señales emocionales/conductuales (cambios repentinos de humor, agresión, aislamiento severo, terrores nocturnos, miedo irracional a quedarse a solas con una persona específica o negarse a ir a ciertos lugares)", "Comportamiento sexualizado inapropiado (el niño actúa o dibuja conocimientos sexuales explícitos que no corresponden a su edad, o juega juegos sexuales coercitivos con otros niños)", "Señales físicas (dolor, picazón, sangrado o hematomas inexplicables en el área genital o anal, infecciones urinarias frecuentes, enuresis o encopresis -orinar/defecar en la ropa- repentinas en un niño ya controlado, aparición de Enfermedades de Transmisión Sexual)"], note: "Si un niño te cuenta sobre un abuso, cree en él y mantén la calma. Nunca lo interrogues agresivamente; eso es trabajo de profesionales forenses." }, treatment: { title: "Protección, Denuncia y Sanación", intro: "La primera y más crítica intervención médica no es clínica, sino de protección legal y seguridad absoluta del menor:", subsections: [ { title: "Pasos de Intervención Urgente", items: ["Garantizar la seguridad inmediata del niño apartándolo del presunto agresor y contactar de inmediato a las autoridades de protección infantil o a la policía", "Evaluación médica y forense especializada en un hospital, preferiblemente por un pediatra capacitado en abuso, para tratar lesiones, prevenir infecciones o ETS de forma delicada", "Psicoterapia especializada en trauma infantil (como la Terapia Cognitivo-Conductual enfocada en el Trauma, TF-CBT, o EMDR) a largo plazo para tratar el Trastorno de Estrés Postraumático (TEPT)", "Terapia de apoyo e intervención familiar (para guiar a los padres protectores sobre cómo ayudar a sanar al niño sin revictimizarlo)"] } ], note: "El trauma no desaparece solo; sin terapia especializada, los efectos del abuso pueden derivar en depresión crónica, adicciones y autolesiones en la edad adulta." }, whenToSeekHelp: { title: "¿A dónde acudir y cómo actuar?", intro: "El abuso sexual es un delito penal y una emergencia absoluta. Si tienes la más mínima sospecha o un niño te revela un abuso:", items: ["No confrontes al abusador ni inicies tu propia investigación, ya que esto pondrá en mayor peligro al niño y podría destruir evidencia legal", "Llama inmediatamente a las líneas de denuncia de abuso infantil de tu país, a los servicios de protección de menores o a la policía local", "Lleva al niño al servicio de urgencias de un hospital pediátrico si sospechas que el abuso es reciente (agudo) para una revisión médica o cuidado de heridas", "Busca ayuda psicológica profesional urgente para el niño; no esperes a que el proceso legal avance para iniciar su proceso de sanación emocional"] } },
'Presión arterial alta (Hipertensión)' : { intro: "La hipertensión, o presión arterial alta, es una afección crónica común y peligrosa en la cual la fuerza que ejerce la sangre contra las paredes de las arterias es consistentemente demasiado alta. Con el tiempo, este exceso de presión daña los vasos sanguíneos y sobrecarga el corazón.", whatIs: { title: "¿Qué es la Hipertensión?", text: "Se define como 'el asesino silencioso'. Ocurre cuando el corazón debe bombear sangre con mucha más fuerza de lo normal para hacerla circular por arterias rígidas o estrechas. Una presión de 130/80 mmHg o superior se considera hipertensión en las guías médicas modernas. Afecta severamente órganos vitales y aumenta exponencialmente el riesgo de infarto y derrame cerebral." }, types: { title: "Tipos y Clasificación", intro: "Se clasifica en dos categorías principales según su origen:", items: ["Hipertensión primaria o esencial (es el 90-95% de los casos en adultos; se desarrolla gradualmente a lo largo de muchos años sin una causa médica única identificable, relacionada con la edad, genética y estilo de vida)", "Hipertensión secundaria (aparece de repente y causa presiones más altas que la primaria; está provocada por una afección médica subyacente identificable, como enfermedad renal severa, tumores suprarrenales, problemas de tiroides o el uso de ciertos medicamentos o drogas)"], note: "Es casi siempre asintomática. Las personas pueden tenerla durante años sin saberlo." }, diagnosis: { title: "Detección y Monitoreo", intro: "Dado que no presenta síntomas de alerta, las mediciones regulares son la única forma de detectarla:", items: ["Medición con tensiómetro de brazo o esfigmomanómetro (el diagnóstico requiere varias lecturas anormalmente altas en consultas diferentes)", "Monitoreo Ambulatorio de Presión Arterial o MAPA de 24 horas (el paciente lleva un medidor durante un día completo para confirmar el diagnóstico y evitar la 'hipertensión de bata blanca', que es el aumento de presión por estrés en el consultorio)", "Análisis de sangre y orina, y electrocardiograma (ECG) para evaluar si ya existe daño en los riñones o el corazón por la hipertensión crónica"], note: "" }, treatment: { title: "Manejo y Control Crónico", intro: "Es una enfermedad que no se cura, pero se controla muy eficazmente con cambios diarios:", subsections: [ { title: "Estrategias de Tratamiento", items: ["Dieta DASH (baja en sodio y sal, rica en potasio, frutas y verduras)", "Actividad física aeróbica regular y pérdida de peso (bajar unos kilos tiene un impacto masivo en reducir los números)", "Restricción severa de alcohol y abandono total del tabaco", "Medicamentos antihipertensivos de por vida (Diuréticos, Inhibidores de la ECA, Bloqueadores de los receptores de angiotensina II -ARA II-, o Bloqueadores de canales de calcio; a menudo se requiere combinar dos o más fármacos)"] } ], note: "Es vital nunca suspender la medicación antihipertensiva repentinamente, ya que puede causar un 'efecto rebote' peligroso." }, whenToSeekHelp: { title: "¿Cuándo es una Crisis o Emergencia Médica?", intro: "Si te mides la presión y tu número superior (sistólica) es 180 o más o el número inferior (diastólica) es 120 o más, espera 5 minutos y vuelve a medir. Si sigue igual de alta, o si presentas estos síntomas, acude a urgencias inmediatamente (Crisis Hipertensiva):", items: ["Dolor o presión intensa y nueva en el pecho, o sensación de falta de aire ahogante", "Dolor de cabeza repentino y severo, acompañado a menudo de confusión extrema o visión doble/borrosa", "Adormecimiento, hormigueo o debilidad profunda repentina en un brazo, una pierna o en el rostro, o dificultad extraña para hablar (posible ACV)", "Hemorragia nasal profusa y constante que no se detiene, o sangrado o dolor repentino en la espalda alta (riesgo aórtico)"] } },
'Avulsión dental' : { intro: "La avulsión dental es la salida, expulsión o desplazamiento total de un diente fuera de su alvéolo óseo (su lugar en la encía y mandíbula) a causa de un traumatismo agudo, un golpe violento o un accidente grave. Es una de las emergencias dentales más serias que existen.", whatIs: { title: "¿Qué es una Avulsión Dental?", text: "Es la 'caída' traumática y completa de un diente definitivo (no de leche), donde el diente entero, incluida su raíz, sale de la boca. Los ligamentos que lo sujetaban al hueso se rasgan por completo. Si se actúa rápida y correctamente, el diente puede reimplantarse y salvarse." }, types: { title: "Manejo según el Tipo de Diente", intro: "La decisión principal depende de si el diente es temporal o permanente:", items: ["Diente permanente (definitivo) de un adulto o adolescente (debe reimplantarse de inmediato para intentar salvarlo, ya que es irreemplazable de forma natural)", "Diente de leche (temporal) de un niño pequeño (generalmente NUNCA se intenta volver a insertar o reimplantar, ya que hacerlo podría empujar y dañar severamente el germen del diente permanente definitivo que está creciendo debajo)"], note: "El factor más importante para el éxito del reimplante es el TIEMPO que el diente pasa fuera del cuerpo (tiempo extraalveolar seco)." }, diagnosis: { title: "Evaluación Odontológica de Urgencia", intro: "Tras llegar al dentista con el diente (o en la boca), el especialista realizará:", items: ["Examen intraoral inmediato para inspeccionar el alvéolo sangrante y descartar que el hueso mandibular se haya fracturado", "Limpieza cuidadosa del área y revisión del estado de los dientes vecinos por si están flojos o rotos", "Radiografías periapicales (para asegurar que no quedaron fragmentos de raíz rotos dentro de la encía y evaluar el daño óseo general)"], note: "El tiempo crítico de oro para salvar el diente es que vuelva a estar en su alvéolo en los primeros 30 a 60 minutos tras el golpe." }, treatment: { title: "Primeros Auxilios y Reimplante", intro: "Tú eres quien inicia el tratamiento en el lugar del accidente. Las acciones inmediatas de primeros auxilios son vitales:", subsections: [ { title: "Pasos de Emergencia y Acción Dental", items: ["En el accidente: Encuentra el diente, recógelo SIEMPRE por la corona (la parte blanca superior que se mastica), ¡nunca toques la raíz amarilla! Si está sucio de tierra, enjuágalo muy suavemente con leche fría o suero (nunca agua del grifo ni lo frotes o cepilles). Intenta volver a colocarlo en su agujero en la encía inmediatamente y muerde una gasa para sostenerlo", "Medio de transporte: Si no puedes volver a insertarlo tú mismo, sumerge el diente inmediatamente en un vaso de leche fría, suero fisiológico o en la propia saliva del paciente. ¡No lo guardes en agua ni seco en un pañuelo!", "Acción Odontológica: El dentista reimplantará el diente, lo fijará (ferulizará) pegándolo con un alambre flexible a los dientes sanos vecinos durante un par de semanas para que el ligamento vuelva a cicatrizar, y prescribirá antibióticos y analgésicos", "Endodoncia obligatoria (tratamiento de conducto): Todos los dientes adultos reimplantados requerirán obligatoriamente que se les extraiga el nervio interno muerto una semana después, para evitar que se infecten gravemente o el cuerpo rechace el diente"] } ], note: "Es vital comprobar si la vacuna del tétanos del paciente está actualizada tras un accidente en el exterior." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia y qué hacer?", intro: "La caída de un diente por golpe es una URGENCIA extrema. Debes acudir volando a tu dentista o a un hospital maxilofacial:", items: ["Inmediatamente después del traumatismo (cada minuto cuenta; la tasa de supervivencia del diente cae en picado después de una hora de estar fuera de la boca)", "Acompañado de alguien y llevando el diente sumergido en leche si no lograste reinsertarlo tú mismo", "Si además del diente caído o flojo, presentas hemorragia grave que no se detiene, mareos intensos, vómitos, amnesia o pérdida de conciencia (lo que indica un posible traumatismo craneal o conmoción cerebral más peligroso que la boca)"] } },
'Síndrome de dolor miofascial' : { intro: "El síndrome de dolor miofascial es un trastorno de dolor crónico, profundo y sordo que afecta a los músculos y la capa de tejido conectivo que los recubre (la fascia). Ocurre cuando se ejerce una presión repetida y excesiva sobre zonas sensibles y contraídas de los músculos.", whatIs: { title: "¿Qué es el Síndrome de Dolor Miofascial?", text: "Es una afección en la cual se forman 'puntos gatillo' (trigger points) hiperirritables y tensos dentro de bandas rígidas del músculo debido a lesiones, estrés o sobreuso repetitivo. Cuando se presiona o estimula uno de estos puntos gatillo en un músculo, causa un dolor intenso y punzante localizado, o, característicamente, 'dolor referido' en partes distantes y aparentemente no relacionadas del cuerpo." }, types: { title: "Causas y Zonas Frecuentes", intro: "Se desarrolla comúnmente en personas con mala higiene postural, ansiedad crónica o por trabajos mecánicos:", items: ["Mala postura crónica prolongada (como estar encorvado sobre un escritorio de ordenador o teléfono, afectando el cuello y los trapecios)", "Microtraumas repetitivos o sobrecarga muscular directa (movimientos constantes en el deporte o empleos manuales físicos pesados)", "Factores psicológicos (la ansiedad y el estrés agudo constante hacen que las personas tensen los músculos de los hombros y la mandíbula involuntariamente durante todo el día, facilitando los nudos)", "Problemas del sueño y deficiencias nutricionales o vitamínicas que impiden la relajación y regeneración muscular"], note: "Aunque casi todo el mundo sufre dolor muscular o 'nudos' por esfuerzo alguna vez, en el síndrome miofascial el dolor y la tensión empeoran o persisten implacablemente durante meses." }, diagnosis: { title: "Evaluación Médica y Palpatoria", intro: "No existen pruebas de rayos X, laboratorio o sangre que muestren este síndrome, el diagnóstico es manual y clínico:", items: ["Palpación profunda y cuidadosa (el médico o fisioterapeuta presiona firmemente zonas específicas de los músculos afectados buscando bandas tensas o nódulos palpables bajo la piel que desencadenen un espasmo brusco local o una mueca de dolor en el paciente)", "Evaluación del 'Dolor Referido' (comprobar si la presión en el cuello produce dolor en la sien, por ejemplo, que es el signo de oro del punto gatillo activo)", "Evaluación de la amplitud de movimiento del cuello u hombro, que estará limitadísima y rígida", "Raramente, exámenes adicionales solo si el médico necesita descartar hernias de disco, desgarros tendinosos o fibromialgia"], note: "" }, treatment: { title: "Desactivación y Relajación Muscular", intro: "El objetivo del tratamiento es desactivar el punto gatillo, aliviar el nudo y reeducar el músculo para que no vuelva a contraerse de esa manera:", subsections: [ { title: "Opciones de Fisioterapia y Medicina", items: ["Infiltraciones de puntos gatillo (el médico inyecta un anestésico local, con o sin corticosteroides de refuerzo, directamente en el corazón del nudo hiperirritable doloroso para 'apagar' el espasmo instantáneamente)", "Punción seca profunda (terapia manual usada por fisioterapeutas donde se inserta una finísima aguja de acupuntura en el punto gatillo muscular sin inyectar nada, provocando un espasmo de liberación y desactivando el calambre doloroso)", "Masoterapia profunda, terapia manual descontracturante y estiramientos continuos dirigidos", "Medicamentos relajantes musculares recetados o antidepresivos en dosis bajas que inhiben las señales nerviosas y mejoran profundamente el sueño restaurador", "Corrección ergonómica del puesto de trabajo, calor húmedo intenso aplicado en casa y reducción activa del estrés mental"] } ], note: "Ignorarlo y tomar analgésicos suaves por su cuenta rara vez resuelve el problema mecánico del punto gatillo encerrado." }, whenToSeekHelp: { title: "¿Cuándo consultar al fisioterapeuta o médico especialista en dolor?", intro: "Es altamente recomendable que reserves una evaluación médica o terapéutica si padeces:", items: ["Un dolor muscular muy focalizado, un nudo persistente, profundo y sordo en la espalda u hombros que empeora en lugar de mejorar con semanas de reposo y masajes en casa", "Padeces de cefaleas tensionales diarias y fuertes o un dolor extraño que se irradia hacia los brazos o piernas y descubres que frotar fuertemente un punto en tu cuello o glúteo alivia ese dolor irradiado momentáneamente", "El dolor te está dificultando severamente conciliar un buen sueño o te obliga a interrumpir tus deportes y tareas mecánicas normales por rigidez dolorosa extrema"] } },
'Esguince' : { intro: "Un esguince es una lesión musculoesquelética aguda, dolorosa y muy frecuente que ocurre cuando un ligamento, la banda fuerte y elástica de tejido conjuntivo que conecta dos huesos y estabiliza una articulación, se estira excesivamente o se desgarra por completo de forma antinatural.", whatIs: { title: "¿Qué es un Esguince?", text: "Es una torcedura repentina, desgarro o estiramiento traumático de los ligamentos articulares, superando su límite máximo de elasticidad natural. La lesión sucede frecuentemente por un movimiento brusco, caída o un golpe en el que la articulación (como el tobillo, la rodilla o la muñeca) se ve forzada violentamente fuera de su posición y rango de movimiento normal." }, types: { title: "Zonas Frecuentes y Grados de Severidad", intro: "El esguince de tobillo (ligamento lateral externo) es, de lejos, el más frecuente. Las lesiones se clasifican y abordan médicamente por su gravedad clínica:", items: ["Grado 1 (Leve): Solo un ligero estiramiento y microdesgarros imperceptibles del ligamento. Hay dolor leve e hinchazón localizada mínima; el paciente aún puede caminar y poner peso, y la articulación es estable.", "Grado 2 (Moderado): Un desgarro parcial o incompleto del ligamento. Resulta en hinchazón muy visible rápida, sensibilidad dolorosa aguda al tocar, hematomas (moretones de sangre oscuros) debajo de la piel y una notable dificultad dolorosa al intentar soportar peso físico sobre el área.", "Grado 3 (Grave o Severo): Una rotura o desgarro total y completo del ligamento, partiendo la conexión por la mitad. Dolor severo inmediato (que a veces desaparece por daño nervioso, pero la zona queda inútil), la articulación es absolutamente inestable, cede o 'baila' al tacto y el paciente es incapaz de usarla en absoluto."], note: "No se debe confundir un esguince (daño de los ligamentos entre huesos) con una distensión o 'tirón' muscular (daño en un músculo o su tendón adjunto)." }, diagnosis: { title: "Evaluación Traumatológica", intro: "El traumatólogo u ortopedista diagnostica en el servicio de urgencias mediante:", items: ["Examen físico local de compresión (el médico tocará y moverá suavemente la articulación afectada empujándola en varias direcciones para comprobar cuán suelta o inestable está y qué zonas ligamentosas específicas duelen)", "Radiografías de rayos X en urgencias (se realizan habitualmente de forma rutinaria y protocolaria, no para ver el ligamento -que es de tejido blando invisible en rayos X- sino para descartar categóricamente que el movimiento brusco no haya fracturado o astillado el hueso también)", "Resonancia Magnética (RM) o Ecografía (indicada únicamente en casos muy severos de grado 3 de deportistas para ver detalladamente la magnitud de la ruptura del tejido blando ligamentos o daño al cartílago, o si no sana tras muchas semanas)"], note: "" }, treatment: { title: "Primeros Auxilios y Recuperación Protocolaria", intro: "El tratamiento primario e inmediato es universal para esguinces comunes, conocido mundialmente por el acrónimo 'RICE' en inglés o 'PRICE' para evitar el agravamiento inflamatorio:", subsections: [ { title: "Pasos Críticos e Intervención", items: ["Protección y Reposo inminente absoluto (dejar de usar y apoyar la extremidad lesionada inmediatamente y usar muletas para esguinces moderados/severos de extremidad inferior)", "Hielo rápido (aplicar compresas de hielo envueltas en tela intensamente durante 15 a 20 minutos varias veces al día las primeras 48 horas vitales para desinflamar rápidamente)", "Compresión y Elevación (vendar la zona ajustada pero sin apretar con vendas elásticas ortopédicas para frenar drásticamente la hinchazón y mantener el miembro lesionado elevado por encima del nivel del corazón el mayor tiempo posible)", "Terapia rehabilitadora y ejercicios de propiocepción (imprescindible después de que la hinchazón baje, de lo contrario la articulación sanará permanentemente inestable y el paciente sufrirá torceduras recurrentes por años)", "Inmovilización con férula bota rígida ortopédica o Cirugía reparadora (solo considerada en roturas completas masivas de grado 3 o en atletas competitivos de élite)"] } ], note: "Retornar al deporte rápidamente antes de que el ligamento cicatrice totalmente en semanas crea un esguince crónico y una articulación peligrosamente laxa o 'floja'." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ir al médico o centro de traumatología?", intro: "Debes buscar ayuda médica hospitalaria el mismo día del accidente sin demora si tras la torcedura presentas:", items: ["No eres capaz de dar ni cuatro pasos, no puedes sostener nada de peso en la pierna, o si la articulación afectada cede repentinamente y se dobla de forma laxa al usarla", "Escuchaste nítidamente o sentiste un fuerte ruido de chasquido, crujido, 'pop' o estallido en la propia articulación exactamente en el momento traumático del accidente", "Experimentas un dolor insoportable que es intenso y continuo, un área completamente entumecida, adormecida u hormigueante en el miembro", "Se forma una inflamación, enrojecimiento deforme e hinchazón severa anormal inminente acompañada de aparición rápida de piel oscura, negra o muy morada sobre una articulación o hueso deformado"] } },
'Falla renal crónica' : { intro: "La falla o enfermedad renal crónica (ERC) es la pérdida lenta, progresiva, silenciosa e irreversible a lo largo de meses o años de la función normal y de filtración de los riñones. Cuando los riñones fallan drásticamente, los desechos tóxicos peligrosos, las toxinas y el exceso de líquido se acumulan en el cuerpo, enfermando severamente al paciente.", whatIs: { title: "¿Qué es la Falla Renal Crónica?", text: "Es el deterioro continuo y final de las delicadas nefronas filtrantes renales. Los riñones dañados no pueden filtrar la sangre, regular la presión arterial, controlar el equilibrio del calcio/fósforo de los huesos, ni producir la hormona vital que crea los glóbulos rojos (eritropoyetina). Las dos causas más masivas a nivel mundial son la Diabetes descontrolada y la Hipertensión Arterial crónica." }, types: { title: "Las 5 Etapas de Progresión de Filtración", intro: "La enfermedad se categoriza midiendo cuán eficientemente los riñones aún logran filtrar la sangre y las toxinas:", items: ["Etapas 1, 2 y 3 o Falla leve a moderada (hay daño físico renal y proteína albúmina anormal escapando en la orina, pero los riñones aún filtran lo suficiente; aquí, la enfermedad es completamente asintomática e indetectable por el paciente)", "Etapa 4 o Falla severa y avanzada (la función renal ha decaído masivamente y los síntomas del fallo como debilidad o retención de agua comienzan a ser intolerables y generalizados)", "Etapa 5, Insuficiencia Renal Terminal o ESRD (los riñones fallan y han dejado de funcionar casi por completo o totalmente; la vida ya no puede mantenerse sin instaurar tratamiento radical de reemplazo renal invasivo)"], note: "El daño renal crónico viejo y las cicatrices del riñón enfermo no tienen cura ni pueden deshacerse o revertirse a sanos; el único fin del tratamiento es retrasar el fallo absoluto final." }, diagnosis: { title: "Detección Sanguínea y Urinaria Médica", intro: "Dado que no duele ni da síntomas tempranos, las pruebas preventivas son la única defensa del diagnóstico:", items: ["Análisis completo de sangre de la eGFR (Tasa de Filtración Glomerular Estimada: la prueba cardinal más importante que mide los niveles tóxicos de creatinina para ver matemáticamente cuánta función renal pura se ha perdido en porcentaje)", "Análisis estricto de orina preventivo anual en diabéticos (para detectar la dañina proteína o sangre silenciosa que el filtro roto de los riñones deja escapar anormalmente)", "Ecografía ultrasonido renal por imágenes (para buscar riñones encogidos, pequeños, cicatrizados o localizar posibles bloqueos físicos por quistes masivos, tumores o cálculos destructivos crónicos obstructivos)", "Biopsia con aguja percutánea (para determinar si una enfermedad autoinmune letal de tratamiento agresivo rápido, como la glomerulonefritis, es la causante principal subyacente del ataque renal)"], note: "" }, treatment: { title: "Manejo Defensivo y Reemplazo Invasivo Terminal", intro: "No existe cura, por lo que se ralentiza agresivamente en las primeras etapas y se reemplaza el órgano en la fase final:", subsections: [ { title: "Control Clínico y Tratamiento Renal", items: ["Control absolutista y agresivo extremo sobre la causa original subyacente de la destrucción y de la presión arterial (mediante uso mandatorio de potentes inhibidores de la ECA o antagonistas ARA, y control muy rígido de los picos mortales del azúcar en sangre de los diabéticos)", "Manejo de complicaciones de la pérdida renal (inyecciones artificiales de eritropoyetina para tratar la anemia severa, diuréticos potentes para forzar la salida de líquido y medicación y suplementos vitamínicos de vitamina D profunda para los huesos que se destruyen)", "Dieta estricta médica muy limitante controlada y baja en proteínas dañinas y evitando el sodio y el potasio en exceso", "Tratamiento sustitutivo final: Terapias vitales y continuas de Diálisis agresiva en máquina purificadora (Hemodiálisis varias veces por semana mediante fístula o Diálisis Peritoneal en el abdomen diario para mantener con vida a la persona que no orina) o, alternativamente, realizar un Trasplante renal definitivo total (cirugía para implantar quirúrgicamente un riñón humano donante nuevo sano y recuperar totalmente la salud normal)"] } ], note: "Evitar rotundamente analgésicos nocivos del grupo AINEs tóxicos (como ibuprofeno o naproxeno sin freno) que masacran letalmente el flujo de los riñones ya debilitados o dañados, es una precaución fundamental y extrema en cualquier enfermo de fallo en los riñones." }, whenToSeekHelp: { title: "¿Cuándo acudir rápidamente al especialista nefrólogo o a Urgencias?", intro: "Es indispensable que vayas de emergencia a un centro o agendes revisión médica si eres diabético o hipertenso y padeces repentinamente:", items: ["Hinchazón excesivamente grande, repentina y de retención extrema letal en tus manos doloridas, tobillos redondos, piernas enteras o en la zona periorbital alrededor profundo de los ojos de los que no consigues deshacerte", "Dificultad súbita o dolor muy profundo asfixiante para poder llegar a respirar y jadear aire (indicativo de la retención letal masiva de líquidos encharcando inundando internamente tus pulmones)", "Sensación constante nauseabunda de tener ganas de vomitar seguidas y repugnancia profunda y pérdida asqueada a toda comida o de apetito, confusión fuerte y somnolencia grave profunda letárgica inusual y gran fatiga debilidad total repentina severa", "Una drástica y notoria desaparición total o falta extrema en la cantidad y número de orina vaciada que expulsas o haces diariamente, o sentir fuerte picazón crónica y muy severa inexplicable a lo largo y ancho en la piel por toda la acumulación masiva subyacente general del tejido tóxico renal en la sangre"] } },
'Traumatismo facial' : { intro: "Una lesión facial, o traumatismo maxilofacial, incluye cualquier daño físico en la cara. Abarca desde cortes y laceraciones hasta fracturas complejas en los huesos de la mandíbula, los pómulos, la nariz y las órbitas de los ojos.", whatIs: { title: "¿Qué es un Traumatismo Facial?", text: "Es el daño a los tejidos blandos (piel, nervios, músculos), a los dientes o a los huesos que conforman el rostro. Las causas más comunes son accidentes de tráfico, caídas, agresiones físicas, lesiones deportivas y quemaduras." }, types: { title: "Tipos de Lesiones", intro: "Se clasifican según las estructuras afectadas:", items: ["Lesiones de tejidos blandos (laceraciones, contusiones, que pueden afectar nervios faciales o conductos salivales)", "Fracturas óseas faciales (fractura nasal, fractura mandibular, fractura del hueso cigomático/pómulo, o fracturas de la órbita ocular)", "Lesiones dentoalveolares (dientes fracturados, aflojados o completamente extraídos por el golpe)", "Fracturas complejas Le Fort (fracturas que separan grandes segmentos de los huesos faciales)"], note: "El daño facial puede comprometer la respiración, la visión o la capacidad de comer." }, diagnosis: { title: "Evaluación de Urgencia", intro: "Debido a la proximidad al cerebro y vías respiratorias, la evaluación debe ser rápida:", items: ["Evaluación primaria (ABC) para asegurar la vía aérea, respiración y circulación", "Examen neurológico básico (revisar visión, movimiento ocular, sensación facial)", "Tomografía Computarizada (TC) maxilofacial (el estándar de oro para diagnosticar fracturas faciales)", "Radiografías panorámicas (si se sospechan fracturas de mandíbula o daño dental)"], note: "" }, treatment: { title: "Manejo Quirúrgico y Restaurador", intro: "El tratamiento busca restaurar la función y la estética del rostro:", subsections: [ { title: "Intervenciones", items: ["Limpieza y sutura cuidadosa de laceraciones (a menudo por un cirujano plástico o maxilofacial para minimizar cicatrices)", "Reducción y fijación de fracturas (uso de miniplacas y tornillos de titanio insertados bajo la piel o dentro de la boca para estabilizar los huesos)", "Fijación intermaxilar (atar la mandíbula al maxilar con alambres temporalmente para que suelde el hueso)", "Tratamiento endodóntico o reimplante de dientes caídos"] } ], note: "Un diente caído debe ser reimplantado o colocado en leche fría y llevado al dentista antes de 60 minutos." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Acude a urgencias inmediatamente tras un golpe en la cara si presentas:", items: ["Dificultad para respirar, sangrado nasal o bucal profuso que no se detiene", "Visión doble, pérdida de visión, hundimiento del ojo o incapacidad para moverlo", "Los dientes no encajan correctamente al cerrar la boca, o hay dificultad/dolor extremo para abrirla", "Entumecimiento facial persistente, confusión, pérdida de memoria o salida de líquido claro por la nariz (puede ser líquido cefalorraquídeo)"] } },
'Trastornos del sueño en personas mayores' : { intro: "Los trastornos del sueño en personas mayores son alteraciones persistentes que dificultan conciliar el sueño, permanecer dormido o lograr un descanso reparador. A medida que las personas envejecen, experimentan cambios naturales en su reloj biológico y estructura del sueño, volviéndose este más ligero y fragmentado, lo que frecuentemente predispone al insomnio.", whatIs: { title: "¿Qué son los Trastornos del Sueño Geriátricos?", text: "Son problemas médicos reales y de comportamiento en la vejez que interrumpen el descanso nocturno esencial. Aunque es normal que los ancianos duerman menos profundamente y se despierten más temprano, padecer insomnio severo, dolor crónico nocturno o asfixias al dormir no es una parte 'normal' y aceptable del envejecimiento natural." }, types: { title: "Problemas y Trastornos Específicos Más Frecuentes", intro: "Varias afecciones distintas suelen agravarse marcadamente en la tercera edad:", items: ["Insomnio de mantenimiento (despertarse varias veces a mitad de la noche y no poder volver a dormirse en horas, la queja más prevalente)", "Apnea obstructiva del sueño y ronquidos graves (ceses y paradas de la respiración nocturna, con gran riesgo de hipertensión y ACV senil)", "Síndrome de las piernas inquietas (SPI) y movimientos periódicos de las extremidades (necesidad ansiosa incontrolable de mover y agitar las piernas, acompañada de calambres u hormigueo, especialmente al acostarse tarde en la noche)", "Trastorno de comportamiento del sueño REM (actuar físicamente y con violencia física o gritos los sueños mientras se duerme, a menudo un signo neurológico premonitorio temprano y muy claro del Parkinson)", "Nicturia (necesidad inevitable de levantarse múltiples veces de la cama para orinar durante la noche por problemas de próstata o vejiga activa)"], note: "Los dolores crónicos de artrosis viejas, los síntomas de acidez estomacal de la hernia de hiato o el uso elevado de múltiples medicinas crónicas (polifarmacia) son causas subyacentes masivas de no dormir." }, diagnosis: { title: "Evaluación del Sueño Médico", intro: "El especialista geriátrico o médico general debe realizar un escrutinio detallado para no medicar en vano:", items: ["Revisión completa, estricta y analítica de todos y cada uno de los medicamentos, pastillas de venta libre que el anciano tome y su dieta", "Uso de un diario de sueño y patrones durante un par de semanas para establecer horarios erróneos (como siestas largas de 3 horas por la tarde)", "Polisomnografía del sueño nocturna en un laboratorio hospitalario (estudio crucial si se sospecha apnea, movimientos periódicos graves de piernas o patología de Parkinson incipiente)"], note: "" }, treatment: { title: "Higiene y Manejo Geriátrico del Sueño", intro: "El abordaje inicial siempre debe ser conductual; las pastillas para dormir en los adultos mayores son altamente problemáticas y peligrosas:", subsections: [ { title: "Terapias Recomendadas y Cuidados", items: ["Terapia Cognitivo-Conductual para el Insomnio (TCC-I) (es el tratamiento inicial de primera elección, reestructurando pensamientos, restringiendo el tiempo total de cama y eliminando la frustración asociada a no poder dormir)", "Higiene rigurosa del sueño en el anciano (establecer y forzar la rutina estricta para acostarse y levantarse a horas fijas, exponerse masivamente a la luz solar matutina clara y prohibir siestas tardías prolongadas o ver TV en la cama)", "Presión Positiva Continua (CPAP) de tratamiento ventilatorio (la solución total y requerida urgentemente para la asfixiante apnea obstructiva de las vías en la noche)", "Uso cauteloso excepcional de fármacos y suplementos específicos (medicación recetada para piernas inquietas, suplementos de melatonina para corregir el reloj biológico de los adultos mayores de forma segura, o antidepresivos/neuromoduladores para el dolor)"] } ], note: "Es absolutamente prioritario evitar el uso habitual de pastillas potentes para dormir clásicas (como sedantes benzodiacepinas) en las personas mayores, ya que aumentan monstruosamente el riesgo de caídas mortales nocturnas con fractura de cadera, somnolencia por efecto residual y confusión grave parecida a la demencia." }, whenToSeekHelp: { title: "¿Cuándo agendar consulta médica especializada?", intro: "Acude a la consulta o al médico para solucionar el problema del sueño de tu familiar si:", items: ["La persona anciana padece de pausas y paros en su propia respiración obvios mientras duerme, jadea profundamente en asfixia o tú observas ronquidos sumamente fuertes asfixiantes", "Sufre de agotamiento diurno y falta de energía paralizante, se queda dormido repentinamente de día de forma continua al leer o en las reuniones impidiéndole realizar actividades diurnas", "Golpea en los sueños a la pareja de cama de forma muy violenta o de repente muestra sonambulismo, caídas por la noche o agresiones extrañas relacionadas con su fase de sueño activo y pesadillas", "Los persistentes y dolorosos problemas de insomnio o las piernas inquietas le provocan y exacerban cuadros de inestabilidad y depresión profunda, cambios de humor letárgicos y mucha y preocupante ansiedad"] } },
'Verrugas genitales' : { intro: "El condiloma acuminado, también conocido como verrugas genitales o anogenitales, es una de las enfermedades de transmisión sexual (ETS) más comunes. Son pequeñas protuberancias o crecimientos carnosos que aparecen en o alrededor de los genitales y el ano.", whatIs: { title: "¿Qué es el Condiloma Acuminado?", text: "Es una infección cutánea causada por cepas de bajo riesgo del Virus del Papiloma Humano (VPH), principalmente los tipos 6 y 11. Aunque son altamente contagiosas por contacto de piel a piel durante el sexo, estas cepas no causan cáncer." }, types: { title: "Características", intro: "Las lesiones pueden variar en su apariencia:", items: ["Pequeñas protuberancias del color de la piel, rosadas o marrones", "Agrupaciones de verrugas que toman la forma de una pequeña coliflor", "Lesiones planas que a veces son tan pequeñas que no se pueden ver a simple vista"], note: "Pueden aparecer en la vulva, paredes vaginales, cuello uterino, pene, escroto, ano, y rara vez en la boca o garganta." }, diagnosis: { title: "Diagnóstico Médico", intro: "El médico las diagnostica mediante observación directa:", items: ["Examen físico visual de la zona genital y anal", "Aplicación de ácido acético (vinagre) que puede volver blancas las verrugas difíciles de ver", "Prueba de Papanicolaou y prueba de VPH (para mujeres, para detectar cambios cervicales causados por cepas asociadas de alto riesgo)", "Rara vez biopsia (solo si sangran, tienen un aspecto atípico o no responden al tratamiento)"], note: "" }, treatment: { title: "Eliminación de Lesiones", intro: "El tratamiento elimina la verruga visible, pero no elimina el virus del cuerpo:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos tópicos recetados (como imiquimod, podofilina o ácido tricloroacético, que el paciente o el médico aplican para destruir el tejido)", "Crioterapia (congelación con nitrógeno líquido)", "Electrocauterización (quemar las verrugas con corriente eléctrica)", "Escisión quirúrgica o tratamiento con láser (para verrugas muy grandes o extensas)"] } ], note: "Las verrugas genitales no se deben tratar nunca con medicamentos de venta libre para verrugas comunes (como las de las manos), ya que el tejido genital es demasiado delicado. La vacuna contra el VPH previene su aparición." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes programar una visita médica si:", items: ["Tú o tu pareja notáis bultos o crecimientos inusuales en la zona genital o anal", "Experimentas picazón, ardor, sangrado o dolor en la zona genital", "Las verrugas interfieren con la micción o causan incomodidad durante las relaciones sexuales"] } },
'Esclerosis múltiple' : { intro: "La esclerosis múltiple (EM) es una enfermedad impredecible y potencialmente discapacitante del cerebro y la médula espinal (el sistema nervioso central) que interrumpe el flujo de información dentro del cerebro y entre el cerebro y el cuerpo. Afecta principalmente a adultos jóvenes y más a menudo a mujeres.", whatIs: { title: "¿Qué es la Esclerosis Múltiple?", text: "Es una enfermedad desmielinizante autoinmune grave. El sistema inmunológico del cuerpo ataca por error y destruye la mielina, la capa protectora grasa y aislante que recubre las fibras nerviosas (neuronas). Esta destrucción forma 'cicatrices' o lesiones (esclerosis) que ralentizan, distorsionan, bloquean o impiden por completo las señales eléctricas enviadas o recibidas por el cerebro nervioso y los nervios periféricos a los músculos." }, types: { title: "Patrones y Evolución del Curso Clínico", intro: "La evolución de la enfermedad y de su brote patológico se clasifica clínicamente en tipos distintos:", items: ["EM Remitente-recurrente (EMRR) (la presentación patológica más común al inicio en más del 80% de enfermos; se caracteriza por agudos y muy severos episodios de brotes neurológicos dolorosos con síntomas nuevos -recaídas- seguidos forzosamente de períodos de recuperación completa o casi total -remisiones- por varios meses)", "EM Secundaria progresiva (EMSP) (ocurre gradualmente después de años de la fase remitente en muchos pacientes; aquí los síntomas y la discapacidad empeoran drásticamente de forma constante sin grandes remisiones y ya no desaparecen)", "EM Primaria progresiva (EMPP) (es poco frecuente y es un subtipo grave y agresivo donde la función nerviosa y motora del paciente empeora progresivamente, lenta y constante desde el mismísimo comienzo original e inicio del diagnóstico temprano sin ningún período real y verdadero de brote o de remisión aliviadora a corto plazo)"], note: "El calor (como las duchas cálidas) a menudo empeora drásticamente temporalmente los propios síntomas presentes." }, diagnosis: { title: "Confirmación y Descarte Clínico Exhaustivo", intro: "El diagnóstico de EM neurológica se basa en el diagnóstico estricto de exclusión y evidencia clínica contundente del médico especialista del daño cerebral:", items: ["Resonancia Magnética (RM) con contraste del sistema nervioso de todo el cerebro cráneo y toda la médula espinal (esencial, es la prueba central y principal porque revela claramente las inconfundibles placas, cicatrices activas o manchas blancas brillantes de desmielinización a lo largo del sistema)", "Punción lumbar del espacio espinal (análisis de una porción del líquido de la médula para identificar proteínas raras o anormales específicas llamadas 'bandas oligoclonales', presentes en EM pero no típicas de las infecciones normales)", "Potenciales evocados nerviosos del médico (prueba externa computarizada muy especial que registra lo veloz o con retraso y lentitud con que el propio cerebro o la propia vista recibe todos los estímulos enviados detectando si hay fibras con retraso mielínico visual)"], note: "" }, treatment: { title: "Manejo de Brotes Críticos y Terapia Crónica Alteradora", intro: "No tiene una cura médica de erradicación total, pero se pueden utilizar medicamentos fuertes para frenar la destrucción profunda nerviosa y manejar la dolorosa espasticidad de la recaída:", subsections: [ { title: "Armas Médicas y Rehabilitación Neurológica", items: ["Terapia aguda y urgente de exacerbación y brotes masivos dolorosos (corticosteroides por vía intravenosa, como las metilprednisolonas durante días, u opcionalmente uso intensivo de la plasmaféresis de recambio plasmático rápido para suprimir la hinchazón inmediata nerviosa inflamatoria causante)", "Medicamentos Crónicos Modificadores de toda la Enfermedad autoinmune severa (terapias inyectables e infusiones monoclonales como Ocrelizumab o interferones, para frenar enormemente la actividad destructiva de las propias defensas o células T/B en EM remitente-recurrente de recaídas crónicas y prevenir gran nueva discapacidad patológica de desarrollo progresivo)", "Alivio y Terapia general de apoyo del entorno paciente (medicamentos de bloque muscular y fisioterapia para la rígida y dolorosa rigidez muscular llamada espasticidad o dolores fuertes parecidos a la corriente de tipo descargas de calambres neuropáticos y antidepresivos vitales)", "Rehabilitación general de gran movilidad del cuerpo y logopedia/terapia ocupacional permanente para la constante función muscular deteriorante vital diaria humana"] } ], note: "Es importantísimo para todos los adultos jóvenes empezar sin demora todo el tipo de terapia recetada fuerte que frene el daño en fases tempranísimas porque el fuerte daño original jamás se repara por completo ni es reversible si mueren todas las fibras de la médula espinal." }, whenToSeekHelp: { title: "¿Cuándo representan URGENCIA y aviso temprano los daños patológicos?", intro: "Es estrictamente perentorio ser muy valorado y examinado urgente de emergencia por algún neurólogo profesional en neurología si observas por primera vez signos sospechosos repentinamente sin causa general aparente:", items: ["Pérdida visual, borrosidad o gran ceguera abrupta parcial muy dolorosa inusual típicamente ocurrida a un solo globo ocular, acompañado siempre de intenso dolor muy constante tras un giro o movida dolorosa del ojo visual de frente (famosa manifestación primera indicativa de neuritis inflamatoria óptica)", "Entumecimiento muy extraño agudo, profunda falta o pérdida total grande de sensibilidad, debilidad extrañísima u hormigueo y paralización que abarca de repente desde arriba toda completa una extremidad de mano o brazo, una pierna completa abajo, el abdomen o en toda la mitad de tu misma cara facial (y dura siempre en conjunto más de largos días continuos)", "Sentir que un hormigueo raro profundo agudo ardiente punzante se refleja o pasa rápida y punzante como un 'rayo con descargas eléctricas horribles intensas de voltaje' directamente desde el fuerte cuello cervical viajando irradiado doloroso a tu propia espalda general siempre y cada sola vez al flexionar mucho hacia adelante abajo la nuca hacia tu propio mentón y tronco torácico (el patológico Signo indicativo de Lhermitte severo)", "Gran falta y pérdida severa repentina alarmante, prolongada incontrolable extrañísima en toda estabilidad corporal física o torpeza profunda descoordinada extraña o inusual temblores fuertes motores corporales de un adulto general en la acción y marcha general a pie"] } },
'Criptorquidia' : { intro: "La criptorquidia, comúnmente llamada testículo no descendido o retención testicular infantil, es la ausencia patológica o falta de desplazamiento natural y anatómico en posición definitiva de uno o ambos testículos dentro de la bolsa baja escrotal antes de producirse el parto.", whatIs: { title: "¿Qué es el grave Testículo no Descendido Pediátrico o Criptorquidia?", text: "Es una gran anomalía congénita y muy común en prematuros de nacimiento en varones pequeños, donde uno (lo normal) o a veces ambos pequeños testículos vitales detienen, estancan e interrumpen completamente todo su viaje o descenso madurativo a través del hueco y conducto inguinal estrecho y quedan anormalmente alojados atrapados de forma retenida o retenidos y atrapados perdidos intraabdominalmente altos internamente o inguinalmente antes del parto en su bajada." }, types: { title: "Variantes en Retención Infantil o Ectopia y Formas de Ubicación Común", intro: "Se divide según cómo, por qué lugar no baja o hacia a dónde es desviado en los pliegues abdominales:", items: ["Testículo retenido intrabdominal u oculto real (escondido muy alto profundamente abdominal e intraabdominalmente imposible en ninguna palpación externa inguinal médica visual)", "Testículo inguinal atrapado palpable (la más general y normal; detenido y varado intermedio dentro total o un poco sobre el anillo y de la cavidad y conducto blando estrecho inguinal inferior del pequeño)", "Testículo ectópico o desviado real grave (donde el pequeño testículo sí ha emprendido y comenzado la vía y bajada inguinal pero tristemente ha errado trágicamente la trayectoria directa final, desviando y yendo al periné profundo blando exterior u otra profunda pared patológica inferior)", "El famoso testículo 'retráctil' inofensivo inofensivo no operado (condición infantil puramente inofensiva o refleja donde solo un pequeño sobreactivo hiperactivo músculo cremáster jala a propósito asustado u sube temporal momentáneamente el testículo sano asustadizo arriba, pero puede de igual modo natural bajarse inmediatamente frotado a su posición de inicio sin necesitar cirugía grave curativa médica real infantil en ningún caso)"], note: "El hecho grave es que los testículos humanos necesitan obligatoriamente de la de muy natural temperatura exterior que es considerable y mucho más inferior temperatura fría de la misma bolsa para su sanidad; no poder solucionarlo si la madurez es total puede alterar la natural y perfecta espermatogénesis posterior de varón maduro para la esterilidad del paciente severa o enorme gran susceptibilidad altísima posterior tumoral." }, diagnosis: { title: "Verificación Neonatal Visual General Manual Estricta Urológica Pediátrica Quirúrgica", intro: "Esta evaluación médica obligatoria será la inicial protocolaria y general por la detección por del examen del doctor experto o médico infantil pediátrico de cabecera:", items: ["Un inmediato gran exhaustivo rápido táctil examen médico muy y sumamente físico y cuidadoso y exploración de la piel y de todos los varones del neonato bebé pequeño o desde las primeras semanas revisadas neonatológicas visualizando muy bien con calor la misma fosa baja e inferior vacía escrotal y palpación exploratoria médica táctil inguinal canalicular experta en el recién niño pequeño", "Eventualmente, la laparoscopia cirugía diagnóstica e inmediata mini y rápida cámara exploratoria introducida abdominal quirúrgicamente mínimamente con anestesia corta muy precisa y necesaria y fundamental y real y directa (sólo y solo exclusiva de modo riguroso para aquellos o cuando todos los ocultos no descendidos bebés son intocables y no son nada detectables o de ningún modo muy y absolutamente nada palpables en la zona superficial canal, debiendo explorarse o encontrarse escondidos los internos del abdomen y no estar ausentes o extintos en agenesias severas testiculares de la misma barriga interna)"], note: "Pruebas o las ecografías muy caras modernas y ultrasonidos se han declarado que no suelen en general considerarse ni siquiera para ningún pequeño niño ni efectivas por que tienen gran grado de alta probabilidad de fracaso médico y diagnóstico infantil y un gran fallo y altísima imprecisión oculta en bebes y escrotos o barrigas pequeñas con los médicos pequeños o glándulas del testículo." }, treatment: { title: "Fijación por Orquidopexia Médica y Descenso Quirúrgico Rápido y Prevención Estricta Infértil", intro: "Si la urología del tiempo general pasa tras los primeros largos varios meses de un niño no reacciona bajando al fondo el descenso a veces solo el fin real del problema testículo pasa quirúrgicamente:", subsections: [ { title: "La Terapia y Operativa Principal Cirugía Urológica y Paliativa Médica Pediátrica Quirúrgica", items: ["Vigilancia atenta o Actitud espectante cautelosa pasiva a menudo observacional muy de prudencia pediátrica primera inicial y primera pediátrica y médica y cautelosa (los doctores pediatras sólo revisarán de reojo de 4 a los muy máximos 6 rápidos meses infantiles puros pues un enorme porcentaje e infantes de varoncitos se los testículos se colocan, completan y logran bajar sanamente el descenso faltante sin ninguna indicación o ayuda de ninguna manera, antes del primer muy gran año o semestre infantil y por ellos solos)", "Gran Cirugía de Fijación Testicular Fuerte Curativa u 'Orquidopexia' y fijado en bolsa profunda o el tratamiento vital infantil curativo definitivo absoluto de rutina rápida total (consistente sumamente obligatoria de manera muy esencial entre un gran rápido margen e ideal recomendado estricto por todo urólogo de 6 u 8 a los muy máximos y de gran prisa y prisa para 18 meses máximos y meses vitales del lactante sano pequeño, y la operación consiste rápida en bajar o hacer traccionar suavemente, reubicar manual u quirúrgico permanentemente de manera segura muy eficaz al rebelde testículo oculto de adentro abdominal en las costuras y asegurar y coser a fondo cosido el saquito pequeño a su posición firme y profunda escrotal baja en una intervención mini de quirófano en hospital muy veloz de tipo ambulatorio quirúrgico leve)"] } ], note: "Postergar mucho esta corrección, gran importante urología o no prestar a una solución antes del grandioso año daña perennemente gran el desarrollo espermatogénico interno general y muy celular permanente infantil varonil aumentando letalmente la incidencia del cáncer testicular futuro en adulto grave varón, pues es vital la cirugía e indispensable por la sanidad del órgano grande varonil testicular blando del escroto en adulto hombre para tener fertilidad de futuro hombre normal." }, whenToSeekHelp: { title: "¿Cuándo preocuparse por evaluación a profundidad del gran urólogo, en niños de gran prisa de tiempo o niño lactante y para la salud muy vital inmediata urgencia pediátrica?", intro: "Es imprescindible y sin ningún aviso requerir el chequeo total en un niño y evaluación continua sin falta pediátrica por profesional de urología si presentas:", items: ["El mismo testículo oculto sigue sin estar presente visible, escondido e impalpable fuertemente o nunca no logra descender a la o el interior bolsa general normal después del de la línea natural estricta pediátrica de los 6 a los mismísimos máximos críticos recomendados urgentes 12 primeros iniciales mes o años muy o rápidos años infantiles primeros de puro bebé neonato varón niño de los del infante varón del primer inicial nacimiento vital y vida para evitar daños y lesiones vitales maduras o cirugía para operar y fertilidad urológica temprana", "De un momento inmediato grande otro u de un súbito de nada ves y ocurre que el pequeño del bebé varón mayor o del tu propio niño pequeño que tiene un testículo escondido de una vez se queja profunda o intensamente fuertemente llorando severamente de extremo rápido intenso gran dolor e insufrible de agonía gran llanto agudo en toda y aguda total sobre la zona interior abdominal o hinchazón baja e inguinal grave masiva dolorosa (urgencia de torsión o de torsión rápida isquémica de su cordón testículo que se requiere de ambulancia de vida rápida por riesgo total a la isquemia inmediata dolorosa del oculto órgano y la gran mortalidad quirúrgica testículo inmediato por necrosis o isquémico en su ingle)"] } },
'Cardiopatía congénita' : { intro: "La cardiopatía congénita es un problema con la estructura y el funcionamiento del corazón que está presente al nacer. Es el tipo más común de anomalía congénita y puede afectar el flujo de sangre a través del corazón y hacia el resto del cuerpo.", whatIs: { title: "¿Qué es la Cardiopatía Congénita?", text: "Son malformaciones en la estructura del corazón (como válvulas, tabiques o arterias) que ocurren durante el desarrollo embrionario en el útero, alterando la circulación de la sangre y el suministro de oxígeno a los órganos vitales." }, types: { title: "Clasificación Principal", intro: "Se divide médicamente en:", items: ["Acianóticas (no causan coloración azulada, como los defectos del tabique interauricular o ventricular)", "Cianóticas (causan un nivel peligrosamente bajo de oxígeno en sangre, provocando coloración azulada, como la Tetralogía de Fallot o la transposición de grandes arterias)"], note: "Muchas cardiopatías leves se resuelven por sí solas en la infancia, mientras que las severas requieren intervención inmediata." }, diagnosis: { title: "Detección Pre y Posnatal", intro: "Se diagnostica frecuentemente durante el embarazo o poco después del nacimiento mediante:", items: ["Ecocardiograma fetal (ecografía especializada durante el embarazo)", "Ecocardiograma pediátrico", "Oximetría de pulso en el recién nacido", "Electrocardiograma (ECG) y radiografía de tórax"], note: "" }, treatment: { title: "Intervenciones Quirúrgicas y Control", intro: "El tratamiento varía drásticamente desde observación hasta trasplantes:", subsections: [ { title: "Opciones de Manejo", items: ["Observación médica en anomalías leves que pueden cerrar solas", "Procedimientos por cateterismo cardíaco intervencionista (para tapar orificios o dilatar válvulas sin cirugía abierta)", "Cirugía a corazón abierto (para reparaciones complejas anatómicas)", "Medicación para mejorar el rendimiento del corazón y controlar arritmias"] } ], note: "Los pacientes operados en la infancia requieren un seguimiento cardiológico especializado de por vida." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia pediátrica?", intro: "Lleva al bebé a urgencias inmediatamente si presenta:", items: ["Cianosis (piel, labios o uñas con coloración azulada, gris o violácea)", "Respiración inusualmente rápida, jadeo o dificultad para respirar (se le hunden las costillas)", "Sudoración fría y fatiga o cansancio extremo al alimentarse", "Desmayos o pérdida de conocimiento"] } },
'Fibrosis pulmonar' : { intro: "La fibrosis pulmonar es una enfermedad pulmonar crónica en la cual el tejido pulmonar profundo se daña, se engrosa y cicatriza. Este tejido cicatricial duro hace que sea cada vez más difícil que los pulmones se expandan y funcionen correctamente.", whatIs: { title: "¿Qué es la Fibrosis Pulmonar?", text: "Es una enfermedad respiratoria progresiva que destruye la arquitectura de los alvéolos (sacos de aire) del pulmón mediante la formación de cicatrices (fibrosis). Esto bloquea el paso del oxígeno desde los pulmones hacia el torrente sanguíneo, causando ahogo constante." }, types: { title: "Causas y Tipos", intro: "Las causas son variadas, destacando:", items: ["Fibrosis pulmonar idiopática (FPI) (la forma más común y mortal, donde la causa exacta es desconocida)", "Fibrosis por enfermedades autoinmunes (secundaria a artritis reumatoide, lupus o esclerodermia)", "Fibrosis pulmonar familiar (hereditaria genética)", "Neumonitis por hipersensibilidad o por exposición a toxinas laborales (asbesto, polvo de carbón o sílice)"], note: "El daño pulmonar causado por la fibrosis es irreversible." }, diagnosis: { title: "Evaluación Neumológica", intro: "El neumólogo utilizará varias pruebas para confirmar el diagnóstico y la gravedad:", items: ["Tomografía computarizada de alta resolución (HRCT) (la prueba de imagen principal que muestra el patrón de panal de abejas de la cicatrización)", "Pruebas de función pulmonar (espirometría para medir el volumen de aire)", "Oximetría de pulso y prueba de caminata de 6 minutos", "Biopsia pulmonar quirúrgica en casos de duda diagnóstica"], note: "" }, treatment: { title: "Manejo y Retraso de la Progresión", intro: "No existe cura médica, el tratamiento busca frenar el avance de las cicatrices:", subsections: [ { title: "Opciones Terapéuticas", items: ["Medicamentos antifibróticos (como Nintedanib o Pirfenidona, que ralentizan la cicatrización pulmonar)", "Oxigenoterapia suplementaria continua (para facilitar la respiración y proteger el corazón)", "Rehabilitación pulmonar (ejercicios y técnicas respiratorias)", "Trasplante de pulmón (la única opción curativa para casos severos y candidatos aptos)"] } ], note: "Tratar el reflujo gástrico es fundamental, ya que la microaspiración de ácidos empeora drásticamente la fibrosis pulmonar." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental buscar a un especialista si tienes:", items: ["Dificultad progresiva e inexplicable para respirar, primero durante el esfuerzo físico y luego en reposo", "Tos seca y entrecortada que persiste durante meses", "Fatiga extrema y debilidad injustificada", "Acropaquia (ensanchamiento y redondeo de las puntas de los dedos de manos o pies) y pérdida de peso sin intentarlo"] } },
'Disco roto' : { intro: "Un disco roto, también conocido médicamente como hernia de disco o disco deslizado, ocurre cuando la parte central blanda de un disco espinal se sale a través de una grieta en el anillo exterior resistente. Puede causar dolor intenso, debilidad y entumecimiento si presiona los nervios circundantes.", whatIs: { title: "¿Qué es un Disco Roto?", text: "Es el desplazamiento del núcleo pulposo (centro gelatinoso) a través del anillo fibroso del disco intervertebral. Al salir de su espacio, el material del disco irrita y comprime químicamente y mecánicamente las raíces nerviosas que salen de la médula espinal." }, types: { title: "Ubicación", intro: "Se clasifican según la zona de la columna donde se produce la rotura:", items: ["Hernia discal lumbar (en la zona baja de la espalda; es la más común y la principal causa de la ciática dolorosa hacia la pierna)", "Hernia discal cervical (en el cuello; causa dolor intenso, debilidad u hormigueo que se irradia hacia los hombros y los brazos)", "Hernia discal torácica (rara, en la espalda media, causando dolor alrededor del pecho o abdomen)"], note: "Curiosamente, muchas personas tienen discos herniados visibles en resonancias magnéticas, pero nunca experimentan ningún síntoma o dolor." }, diagnosis: { title: "Diagnóstico Clínico e Imagen", intro: "El especialista en columna evaluará el grado de compromiso nervioso:", items: ["Examen físico neurológico estricto (evaluación de la fuerza muscular, sensibilidad táctil, reflejos y prueba de elevación de pierna estirada)", "Resonancia Magnética (RM) (el método estándar de oro para confirmar con precisión la rotura del disco y visualizar los nervios comprimidos)", "Electromiografía (EMG) para localizar exactamente qué raíz nerviosa está sufriendo el daño eléctrico"], note: "" }, treatment: { title: "Manejo Conservador y Cirugía", intro: "La mayoría de las roturas de disco se curan solas con el tiempo mediante manejo conservador:", subsections: [ { title: "Intervenciones", items: ["Modificación temporal de actividades, reposo corto y fisioterapia enfocada en el fortalecimiento del 'core'", "Medicamentos (AINEs, analgésicos neuropáticos como gabapentina, relajantes musculares)", "Inyecciones epidurales de esteroides (para apagar la inflamación química directa en el nervio)", "Cirugía de microdiscectomía (extracción del fragmento de disco roto que presiona el nervio; indicada si el dolor incapacitante dura meses o si hay pérdida de función motora)"] } ], note: "Las radiografías simples de la espalda no muestran discos herniados, solo huesos." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia neurológica?", intro: "Acude inmediatamente al hospital si padeces:", items: ["Pérdida de control de la vejiga o los intestinos, o retención urinaria severa", "Anestesia en silla de montar (pérdida progresiva de sensación en los glúteos, cara interna de los muslos o zona genital)", "Debilidad motora grave y repentina en una extremidad (como arrastrar o no poder levantar el pie al caminar, 'pie caído')", "Dolor irradiado que empeora rápida y constantemente a pesar del uso de analgésicos fuertes"] } },
'Hombro congelado' : { intro: "El hombro congelado, conocido médicamente como capsulitis adhesiva, es una afección caracterizada por dolor sordo, pesadez y una rigidez extrema que limita e imposibilita mover la articulación del hombro, tanto por ti mismo como si alguien más intenta mover tu brazo.", whatIs: { title: "¿Qué es el Hombro Congelado?", text: "Es una enfermedad incapacitante en la que la cápsula de tejido conectivo que envuelve la articulación del hombro se inflama severamente, se engrosa, desarrolla tejido cicatricial (adherencias) y se encoge. Esto 'congela' literalmente la cabeza del húmero impidiendo su movimiento rotatorio." }, types: { title: "Fases y Causas", intro: "A menudo afecta más a las mujeres entre 40 y 60 años, y su evolución consta de tres fases largas:", items: ["Fase de congelamiento (dura de 2 a 9 meses; dolor agudo progresivo que empeora de noche y movimiento que se va perdiendo gradualmente)", "Fase congelada (dura de 4 a 12 meses; el dolor puede disminuir, pero el hombro está totalmente rígido, y usarlo para tareas cotidianas es muy difícil)", "Fase de descongelamiento (dura de 5 a 24 meses; la capacidad de movimiento mejora lentamente hasta volver a la normalidad)"], note: "Tener diabetes (especialmente mal controlada), problemas de tiroides o haber tenido el brazo inmovilizado (tras una cirugía o fractura) son los factores de riesgo más importantes." }, diagnosis: { title: "Diagnóstico Funcional", intro: "El traumatólogo realiza un diagnóstico principalmente físico:", items: ["Examen del rango de movimiento activo (lo que el paciente puede mover) y pasivo (cuando el médico mueve el brazo del paciente relajado). En el hombro congelado, el movimiento pasivo está mecánicamente bloqueado", "Radiografías (usadas sólo para confirmar que no haya artrosis severa, tumores o dislocaciones ocultas que causen la inmovilidad)", "Rara vez se requiere RM, a menos que se sospeche de un desgarro grave del manguito rotador concomitante"], note: "" }, treatment: { title: "Rehabilitación y Liberación Articular", intro: "El tratamiento se enfoca fuertemente en controlar el dolor y forzar la recuperación de la movilidad:", subsections: [ { title: "Opciones de Tratamiento", items: ["Analgésicos y antiinflamatorios potentes (AINEs)", "Fisioterapia continua y estiramientos domiciliarios diarios (el paso más importante; debe hacerse a tolerancia para ir 'rompiendo' las adherencias progresivamente)", "Infiltraciones intraarticulares de corticosteroides (muy efectivas en la fase inicial de congelamiento para apagar la inflamación dolorosa)", "Hidrodilatación (inyección de líquido estéril a presión en la articulación para expandir y estirar la cápsula retraída)", "Manipulación bajo anestesia o cirugía de liberación capsular artroscópica (para los casos crónicos y refractarios severos)"] } ], note: "La condición suele ser autolimitada (se resuelve sola), pero el proceso completo de curación natural puede durar agonizantemente hasta tres años sin tratamiento." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es altamente recomendable que busques tratamiento médico y fisioterapéutico temprano si:", items: ["Tienes dolor continuo en el hombro que empeora significativamente por la noche, interrumpiendo tu sueño de manera crónica", "Sientes que el hombro se está volviendo cada vez más rígido con el paso de las semanas", "Eres incapaz de levantar el brazo por encima del nivel de la cabeza o de alcanzar tu espalda para vestirte, lavarte o rascarte", "Padeces de diabetes o enfermedad de la tiroides y comienzas a sentir problemas en el rango de movimiento de tu brazo"] } },
'Envejecimiento cutáneo' : { intro: "El envejecimiento cutáneo es el proceso natural e inevitable de deterioro de la piel con el paso del tiempo. Implica la pérdida paulatina de la arquitectura interna de la dermis y epidermis, causando que la piel pierda elasticidad, humedad, volumen y uniformidad en su color.", whatIs: { title: "¿Qué es el Envejecimiento Cutáneo?", text: "Es el declive biológico del órgano de la piel, causado por dos vías: el envejecimiento intrínseco o cronológico (dictado puramente por los genes y la edad, resultando en piel fina, pálida y arrugas de expresión suaves) y el envejecimiento extrínseco o prematuro (causado por la radiación, daño oxidativo y el estilo de vida)." }, types: { title: "El Factor Externo: El Fotoenvejecimiento", intro: "Más del 80% del daño visible en el rostro es causado por el entorno, no por la edad en sí:", items: ["Fotoenvejecimiento solar (la radiación ultravioleta UVA y UVB del sol destruye agresivamente las fibras de colágeno y elastina, causando arrugas profundas, sequedad severa, queratosis actínicas y manchas hepáticas o léntigos solares oscuros)", "Envejecimiento inducido por tabaco (fumar contrae los vasos sanguíneos capilares de la piel privándola de oxígeno y vitamina A, produciendo la característica piel cetrina o amarillenta y arrugas marcadas peribucales)", "Daño por contaminación ambiental y estrés oxidativo (los radicales libres aceleran la muerte de las células jóvenes de la piel)"], note: "El daño solar es acumulativo desde la infancia, aunque se manifieste visiblemente décadas después." }, diagnosis: { title: "Evaluación Dermatológica y Estética", intro: "El dermatólogo evalúa la salud estructural de la piel y descarta patologías graves:", items: ["Análisis clínico visual y dermatoscopia de manchas (para diferenciar el envejecimiento benigno de las lesiones precancerosas u oncológicas severas)", "Uso de Lámpara de Wood o cámaras multiespectrales (para evaluar los daños de pigmentación en capas profundas y el fotodaño solar acumulado)", "Evaluación de la laxitud, hidratación y grosor de la piel para planificar tratamientos estéticos personalizados"], note: "" }, treatment: { title: "Prevención, Cosmetología y Medicina Estética", intro: "Aunque la edad avanza, los signos externos se pueden prevenir, retrasar y corregir drásticamente:", subsections: [ { title: "Rutas de Tratamiento Rejuvenecedor", items: ["Prevención estricta (el uso diario e innegociable de protector solar de amplio espectro, abandono del tabaquismo y una fuerte hidratación oral/tópica)", "Dermocosmética activa médica (uso de derivados de la vitamina A tópicos como el Retinol o Tretinoína, que están médicamente probados para crear nuevo colágeno, junto con Vitamina C antioxidante y Ácido Hialurónico)", "Tratamientos dermatológicos de regeneración (peelings químicos médicos, microagujas -microneedling- o terapias con láseres fraccionados ablativos para renovar por completo la capa superficial de la piel)", "Medicina estética y rellenos (Neuromoduladores como la toxina botulínica para borrar líneas de expresión dinámicas, o rellenos de ácido hialurónico y bioestimuladores para reponer los volúmenes faciales vaciados)"] } ], note: "Ninguna crema hidratante, por más cara que sea, revertirá arrugas profundas causadas por la destrucción del colágeno estructural; para ello se requieren retinoides recetados o intervenciones estéticas en consultorio." }, whenToSeekHelp: { title: "¿Cuándo acudir obligatoriamente al dermatólogo?", intro: "Más allá del cuidado estético y cosmético, debes asistir a una evaluación médica urgente si debido al daño y fotoenvejecimiento observas:", items: ["El surgimiento en tu cara, brazos o pecho de pequeñas placas ásperas, escamosas o costrosas que no sanan nunca (queratosis actínica, que es una afección precancerosa)", "Lunares o 'manchas de la edad' repentinas que cumplen con la regla ABCDE (cambian de asimetría, bordes, coloración mixta o tamaño creciente rápido)", "Aparición frecuente, fácil e inusual de grandes hematomas o sangrados en brazos y manos tras roces casi imperceptibles (púrpura senil por fragilidad vascular dérmica extrema)"] } },
'Compresión de la médula espinal' : { intro: "La compresión de la médula espinal ocurre cuando se ejerce una presión directa patológica sobre el tejido y los nervios de la médula dentro del conducto de la columna vertebral. Es una condición neurológica sumamente crítica que requiere acción inmediata para salvar la movilidad del paciente.", whatIs: { title: "¿Qué es la Compresión de la Médula Espinal?", text: "Es el estrangulamiento mecánico de la vía principal de comunicación entre el cerebro y el cuerpo. Esta presión daña e interrumpe las señales eléctricas motoras y sensitivas, resultando en un adormecimiento progresivo, debilidad espástica grave y parálisis funcional por debajo del nivel de la compresión en el cuello, tórax o espalda baja." }, types: { title: "Orígenes y Evolución de la Compresión", intro: "Se divide según la causa y la velocidad a la que se desarrolla el atrapamiento:", items: ["Compresión aguda repentina (suele ser una emergencia catastrófica originada por accidentes traumáticos, fracturas espinales desplazadas, formación de abscesos epidurales de pus severos o un hematoma espinal)", "Compresión progresiva o crónica (evoluciona gradualmente en personas mayores debido a espondilosis cervical y lumbar extrema, estenosis espinal calcificada u osteoartritis severa; mielopatía degenerativa)", "Compresión maligna u oncológica (una urgencia médica común en pacientes con cáncer avanzado, donde los tumores hacen metástasis a la vértebra, rompiéndola y aplastando la médula interior)"], note: "Cualquier síntoma asociado con la pérdida del control de esfínteres (vejiga e intestino) representa la indicación máxima de cirugía de emergencia." }, diagnosis: { title: "Evaluación de la Emergencia Neurológica", intro: "El diagnóstico médico rápido determina el futuro neurológico del paciente:", items: ["Resonancia Magnética (RM) de la columna vertebral (el examen absolutamente vital y estándar de oro para ver claramente la médula espinal atrapada y los nervios comprimidos, localizando qué la aplasta)", "Examen neurológico inicial estricto de sensibilidad al pinchazo, temperatura, prueba de reflejos rotulianos y clonus, fuerza muscular y marcha", "Tomografía Computarizada o Mielografía (usadas cuando las RM están contraindicadas o para confirmar el grado de destrucción ósea circundante al nervio)"], note: "" }, treatment: { title: "Cirugía de Descompresión Urgente y Médica", intro: "El abordaje busca retirar el peso y la obstrucción antes de que el tejido medular muera de isquemia (falta de riego sanguíneo):", subsections: [ { title: "Terapias de Primera Línea", items: ["Administración intravenosa altísima y urgente de corticosteroides (la dexametasona a menudo se usa inmediatamente, sobre todo en casos tumorales, para disminuir instantáneamente la inflamación severa en el canal y ganar tiempo antes de la cirugía)", "Cirugía de descompresión neuroquirúrgica (laminectomía, discectomía espinal o resección de masa tumoral para abrir y ampliar físicamente el canal óseo y dejar que el cordón de la médula vuelva a expandirse y respirar)", "Radioterapia urgente y oncológica paliativa (como la primera opción alternativa a la cirugía para destruir muy rápido los tumores en pacientes de cáncer metastásico inoperables o demasiado débiles)"] } ], note: "Cuanto más tiempo pase la médula totalmente comprimida bajo presión antes del tratamiento quirúrgico o médico, mayor será la certeza de una parálisis permanente y en silla de ruedas." }, whenToSeekHelp: { title: "¿Cuándo dirigirse velozmente al hospital?", intro: "Es una urgencia vital que requiere asistencia inmediata al cuarto de emergencias y llamar a los paramédicos si experimentas:", items: ["Entumecimiento total grave, pérdida extraña y aguda de la sensibilidad o inmensa debilidad general que aparece de repente y progresa velozmente en tus piernas, ingles o brazos ('como si te hubieran anestesiado la parte inferior del cuerpo')", "Pérdida inusitada del control vesical o intestinal completo (incontinencia incontinente fecal o de vejiga, o paradójicamente, una repentina incapacidad paralizante para poder expulsar orina o heces a voluntad)", "Imposibilidad abrupta para mantenerte de pie o para poder caminar porque tus piernas sienten una pesadez extrema o tropiezan por falta de orden motriz", "Dolor en la columna o cuello que es sumamente profundo, intenso o en forma de quemadura insoportable que empeora enormemente al toser y de manera muy severa al acostarte de espaldas plano"] } },
'Displasia cervical' : { intro: "La displasia cervical es una afección premaligna asintomática en la que se desarrolla un crecimiento celular atípico y anormal en el tejido de la superficie del cuello uterino (la parte inferior del útero conectada a la vagina). Si no se monitorea o trata a tiempo, podría transformarse en cáncer de cuello uterino.", whatIs: { title: "¿Qué es la Displasia Cervical?", text: "Se trata de un cambio preneoplásico (precanceroso). Casi el 100% de los casos de displasia son causados por la infección de transmisión sexual persistente a largo plazo de las cepas de alto riesgo del Virus del Papiloma Humano (VPH). El cuerpo muchas veces combate al virus y revierte el cambio celular por sí solo, pero si la infección del VPH persiste durante años, las células se vuelven paulatinamente más malignas." }, types: { title: "Grados de Neoplasia Intraepitelial Cervical (NIC)", intro: "El grado de anormalidad se tipifica según la profundidad de la invasión celular en el tejido del cuello:", items: ["NIC 1 / Displasia Leve / Lesión intraepitelial escamosa de bajo grado (LSIL) (cambios menores que afectan solo el tercio inferior del revestimiento celular; raramente requieren cirugía ya que más del 70% de las veces se curan solos gracias al sistema inmunológico de la mujer)", "NIC 2 / Displasia Moderada / Lesión intraepitelial escamosa de alto grado (HSIL) (cambios atípicos presentes en dos tercios de la profundidad celular)", "NIC 3 / Displasia Severa o Carcinoma in situ (las células precancerosas abarcan todo el grosor del epitelio y tienen una probabilidad altísima de romperse hacia el tejido profundo, transformándose oficialmente en cáncer cervical maligno invasivo)"], note: "El tabaquismo activo duplica drásticamente las posibilidades de que una displasia leve avance y escale a grados severos en mujeres con VPH." }, diagnosis: { title: "Detección Preventiva y Confirmación", intro: "Dado que es una enfermedad cien por cien silenciosa (sin síntomas), el único método para detectarla es el chequeo médico rutinario de control:", items: ["Prueba del Papanicolaou rutinario (Pap smear) (para recolectar muestras frotadas del cuello y evaluar al microscopio indicios tempranos de células escamosas atípicas y extrañas)", "Prueba de tipificación de ADN del VPH (para saber de forma exacta si el virus infeccioso presente es el 16, 18 u otras cepas altamente propensas a derivar en el desarrollo de mutación)", "Colposcopia ginecológica y Biopsia (si el Pap es dudoso o positivo, el médico lava el cuello con ácido acético especial e ilumina y amplía visualmente la zona internamente, tomando fragmentos minúsculos directos de las zonas manchadas para análisis de laboratorio definitivos)"], note: "" }, treatment: { title: "Destrucción o Remoción del Tejido Anómalo", intro: "El protocolo terapéutico varía desde la vigilancia cercana para casos iniciales leves, hasta la cirugía preventiva ginecológica estricta:", subsections: [ { title: "Métodos Terapéuticos Quirúrgicos y Destructivos", items: ["Vigilancia clínica exhaustiva o expectante (en la displasia inicial de Grado 1, especialmente recomendada y sugerida en mujeres jóvenes menores de 25 años, con repetición de Papanicolau frecuente para confirmar su reversión biológica natural)", "Procedimiento de escisión electroquirúrgica con asa o LEEP (el tratamiento por excelencia ambulatorio más utilizado para extraer, extirpar y curar permanentemente NIC 2 y NIC 3, donde un alambre caliente delgado corta y quita el tejido dañado enfermo conservando el resto del útero)", "Crioterapia ambulatoria o terapia térmica con láser destructivo (se congela masivamente a muy bajos grados la zona o se evapora el tejido anormal con luces para matar las células de displasia)", "Conización o Biopsia en cono de bisturí frío (para anomalías situadas muy arriba de canal cervical interno y oculto, que extrae una porción grande en forma de cono de gran precisión, usado también como tratamiento radical o biopsia confirmatoria de sospecha de cáncer subyacente temprano)"] } ], note: "La aplicación pediátrica preadolescente de la vacuna Gardasil previene que la paciente alguna vez enfrente estas displasias en su vida de adulta joven." }, whenToSeekHelp: { title: "¿Cuándo es imperativo agendar la consulta en el ginecólogo?", intro: "Esta es la condición de salud silente por definición; por ende, tu máxima protección es realizar tus cribados. Aparte de los controles rutinarios, asiste fuera de plazo si posees estas señales indirectas asociadas a cuellos uterinos inflamados:", items: ["Experimentas y observas sangrado de sangre fresca o manchado vaginal persistente inexplicado justo después del contacto sexual y de mantener penetración (sangrado poscoital o cervicitis de contacto)", "Manchados y desangrados intermitentes inusuales de coloración marrón sucediendo fuera del ciclo y entre varios de tus períodos menstruales", "Presentas un flujo acuoso anormal, copioso y a veces fétido, acompañado ocasionalmente de mucho dolor interior y molestias durante las relaciones sexuales de índole profunda"] } },
'Trombosis venosa profunda' : { intro: "La trombosis venosa profunda (TVP) se origina por la solidificación y formación peligrosa de un grueso coágulo de sangre en el interior de un gran vaso o vena profunda, predominantemente afectando el curso venoso inferior de las pantorrillas, rodillas, muslos o pelvis, creando dolor local e hinchazón de extremidad.", whatIs: { title: "¿Qué es exactamente la TVP?", text: "Es la coagulación intravenosa estancada aguda. Al generarse esta gran masa interna en la vena profunda, se impide o tapona radicalmente el fluido normal de la sangre retornando desde las piernas hasta tu corazón. La patología en la pierna no es lo mortal de la enfermedad, sino su migración: el letal peligro ocurre si la gran masa coagulada de sangre se libera y viaja disparada directo a obstruir los grandes pulmones vitales (creando una mortal Embolia Pulmonar, EP)." }, types: { title: "Causas, Tríada Detonante y Complicación Severa", intro: "Se desarrolla a través de al menos uno de los tres componentes de la clásica 'Tríada de Virchow' biológica:", items: ["Estasis o flujo sanguíneo lentísimo estancado venoso (resultado de permanecer horas o días sin mover absolutamente las piernas por viajes transoceánicos muy largos, convalecencias en cama posoperatoria en hospitales, grandes yesos o la parálisis natural de alguna extremidad lesionada)", "Hipercoagulabilidad o tendencia celular a la sangre espesa y pegajosa (consecuencia de poseer trastornos genéticos familiares de coagulación, padecer cánceres activos, seguir terapias de píldoras anticonceptivas de estrógenos fuertes o el mismo embarazo normal materno)", "Trauma, cirugía general o lesión destructiva de las paredes endoteliales de la vena interna de la pierna (el vaso dañado atrae plaquetas a sí mismo desencadenando erróneamente un coágulo grande para taponar el golpe)", "El Síndrome postrombótico profundo a largo plazo (si la vena no recibe medicación a tiempo, sus válvulas se arruinan de por vida, lo que deriva en una gran e incapacitante hinchazón de tobillo crónica general con piel color café severo que ennegrece para toda la vida)"], note: "Hasta la mitad total enorme de la población de los episodios e incidentes de esta dolencia cursan de forma inusualmente asintomática hasta que sobreviene el bloqueo agudo por embolia." }, diagnosis: { title: "Detección Hematológica Visual de Gran Prontitud y Diagnóstico Rápido", intro: "Es el caso y una fuerte alerta donde la intervención vascular y de análisis diagnóstico precoz por tu doctor se torna vitalmente urgente:", items: ["Ecografía dúplex vascular y el ultrasonido venoso de miembros de las extremidades inferiores directas (la prueba indolora y prueba de máxima utilidad estándar fundamental usada mundialmente para revelar mediante ondas y medir la presencia real sólida o blanda de los trombos coagulados taponando los conductos venosos vitales en lo más profundo de las piernas de la extremidad)", "Examen o gran análisis laboratorial general cuantitativo específico en el paciente urgente de la prueba sanguínea clínica del 'Dímero D' de sangre entera humana (una prueba especializada altísima de exclusión analítica que mide fragmentos de las proteínas del coágulo en sangre; si esta específica proteína coagulante del laboratorio general es sumamente negativa en su valor en pacientes urgentes, elimina totalmente por lo general de forma absoluta casi toda duda de tener un coágulo mayor a esa altura del problema)", "Rara y compleja venografía con contraste por rayo o resonancia magnética en pelvis y tórax (si el caso diagnóstico es oscuro en vasos del estómago interior)"], note: "" }, treatment: { title: "Terapia Resolutiva Médico Anticoagulante Urgente Vital de por Vida", intro: "Su inminente finalidad fundamental trata puramente de evitar radicalmente que la aglomeración y coágulo siga creciendo de masa, se propague y viaje mortíferamente al pulmón general:", subsections: [ { title: "Armas Farmacológicas Interventivas y Dispositivos Reales Quirúrgicos", items: ["Gran terapia agresiva total farmacéutica con múltiples tipos vitales fuertes y rápidos de grandes medicamentos de anticoagulantes de urgencia clínica estricta llamados popular y comúnmente y típicamente 'diluyentes e inhibidores grandes adelgazantes puros' reales de toda la sangre total humana del individuo de por vida e injerencia (como heparina clínica de gran uso vía intravenosa IV inicial, la famosa tradicional antigua warfarina oral severa estricta o medicamentos más nuevos modernos apixabán o el gran rivaroxabán), por lo general tomados crónicamente entre los tempranos meses desde los iniciales urgentes de y para 3 meses puros y mínimos obligatorios a incluso tomados toda y por estricto tratamiento general crónico de su larga etapa en vida de salud vitalicia adulta si existen casos severos recidivantes severos crónicos", "Gran cirugía de disolución y trombólisis masiva para la disolución endovenosa guiada intra y vascular severa (aplicación sumamente peligrosa grande de altísimos de fármacos inyectables destructores deshacedores fuertes intra y de trombos y de disolver puros coagulaciones extremas solo a nivel directo del coágulo masivo por y del catéter para salvar las obstrucciones mortales extremas general severas de un bloqueo total letal del brazo general)", "Inserción de la de un dispositivo metálico quirúrgico e introducido o filtro grande especial vena de inferior o y malla y paraguas para atrapar coágulos y embolias letales pulmonares de paraguas en vena hueca de vena cava del paciente para quienes desangran a muerte y no por y del por por tanto por no pueden general o el tomar y tener los letales anticoagulantes grandes generales", "Medias recetadas apretadas de extremidad, gran y especial nivel severo alto firmeza compresión constante compresión compresión medias apretadas en las pantorrillas de a rodilla todo general durante años posteriores y de grandes paseos continuos al sentarse siempre de pie mucho rato"] } ], note: "La gran medicación en sangre del tipo o y un anticoagulante jamás se atreve y ni llega deshace ni rompe de inmediato o curativo ni elimina todo el coagulado inicial original y antiguo ya solidificado grave anterior viejo ya endurecido existente venoso del cuerpo, esto el y cuerpo lo lo hace el y se el degrada poco a poco corporal el tiempo gradualmente muy progresivo y él mismo cuerpo a sí un por un cuerpo a sí y pero y en los y tiempo con; este impide su el aumento letal en y previene un tamaño mortífero coágulo la en futuro sangre la de propagación a y general pulmonar y el letal al y masivo de viaje pulmonar y un de y del y cuerpo pulmón." }, whenToSeekHelp: { title: "¿Cuándo se alza o hay de o o acudes de una y de emergencia médica hospitalaria y urgencias inminente médica letal y para general de atención crítica y letal masiva atención grave letal en por o el del servicio del urgente?", intro: "Es fundamentalísima la alarma urgente inmediata e intensa masiva total de ir rápido veloz y de o volar de correr en del por al en o ir hacia urgente atención o urgencia a la una general de urgencia y máxima de urgencia o al servicio de médico para si general detectas o por general sufres para salvar por si general de salvar o si y de la el tú en u del mismo tu de o del u o el en un la vida tu de a o al si u un tu cuerpo familiar en u o de a pierna u un en general un o y en si:", items: ["El descubrimiento súbito reciente general agudo sobre tu y en por un gran de intenso hinchazón hinchazón pierna tu general de o tu y una pierna masiva la unilateral general pantorrilla en o en general hinchada al el una e solo de un lado de solo de u pierna una u o pierna masiva e una inexplicablemente por de tu pantorrilla de tu gemelo de el gran e e hinchado general e gran por e inexplicable hinchazón general gran una gran hinchada (casi siempre una es general y sola asimétrica), combinada con de con dolor con sordo muy dolor con un, o dolor opresivo y dolor profundo de como dolor tirante intenso y como un como y dolor como opresivo muy de el en calambre opresivo muy severo sordo severo o tipo un de y severo del calambre calambre sordo un como de en general agudo y un y o dolor tipo intenso por y un agudo tipo dolor muy tipo el intenso tipo fuerte del el tirón tirante de tirante intenso del gemelo calambre o la de un calambre muscular fuerte músculo al en del estar y de y agudo el calambre que a gemelo del de en pierna agudo y que sordo o de del al agudo agudo músculo fuerte muscular al la no y del y músculo o músculo al de gemelo y la se o se caminar gemelo no gemelo se que al del caminar no se dolor", "Una gran visible muy visible un notoria o un roja notable mancha y o mancha o un un área del al la un grande y enrojecida intensamente un o rojez del piel de la pierna intensamente la piel piel en roja de ardiente área rojiza por área de pierna piel de en rojiza y de de la piel muy pierna área enrojecida o en pierna caliente piel o y caliente muy piel y general sensible roja y de y muy inflamada caliente pierna o dolorosa caliente caliente dolorosa la sensible la al roce piel dolorosa enrojecida muy sensible y caliente muy al sensible dolorosa sensible pierna a la tacto a la pierna general caliente la y tacto sensible caliente al la piel que muy que roce al y de caliente al general de tacto del al al o el tacto de y general tacto tacto no al tacto tacto y que al que tacto se y se dolor general tacto no se y que no", "PRESENTAS EL SÍNTOMA O SÍNTOMAS LAS SIGNOS LETALES LOS SÍNTOMAS SIGNOS SÍNTOMAS SÍNTOMAS SÍNTOMAS LETALES SEÑALES DE SEÑALES LETALES EMBOLIA PULMONAR SEÑALES LAS LETALES LOS PULMONAR DE DE SEÑALES PULMONAR SEÑALES LA LA EMBOLIA LAS EMBOLIA DE LETALES LA LA LAS DE LAS PULMONAR LETALES DE EMBOLIA LA DE LA DE EMBOLIA DE EMBOLIA DE DE EMBOLIA (un trombo viaja y bloquea tu pulmón): asfixia o y falta asfixia de de de o aire repentina falta de falta aire repentina o o de falta extrema asfixia y de aire asfixia extrema repentina y falta o y aire o repentina falta de de y o y de o de extrema de de repentina repentina y o o extrema de asfixia y de de de y falta extrema de y aire aire repentina repentina aire extrema repentina aire, dolor al al, dolor el dolor o dolor pecho pecho dolor de dolor al en en al dolor pecho en pecho o respirar pecho de pecho de en el en de al pecho o en en el en pecho dolor pecho pecho en dolor al respirar profundo o toser profundo al respirar al o respirar pecho al toser respirar o respirar respirar toser al o toser profundo al profundo al profundo respirar o toser toser profundo toser o profundo o o o toser o toser respirar profundo, latidos cardíacos latidos acelerados latidos cardíacos cardíacos latidos cardíacos latidos cardíacos latidos muy acelerados acelerados muy latidos muy latidos latidos acelerados cardíacos latidos acelerados latidos muy muy latidos muy cardíacos acelerados acelerados cardíacos muy acelerados acelerados cardíacos muy muy cardíacos rápidos muy rápidos rápidos muy rápidos muy o muy o sudor frío, y frío sudores rápidos o rápidos y o rápidos rápidos rápidos sudor rápidos y o o rápidos y o sudor sudor o rápidos frío y o y y sudor rápidos frío y sudor o frío y y frío o sudor y tos con sudor con y tos tos con tos con y y frío con frío con tos tos tos y sudor y con y y con tos tos tos con sangre con tos con tos sangre sangre sangre con sangre con sangre sangre"] } },
'Cáncer de testículos' : { intro: "El cáncer de testículos ocurre en las glándulas reproductivas masculinas (testículos) dentro del escroto. Aunque es poco común en la población general, es el cáncer más diagnosticado en hombres jóvenes entre los 15 y 35 años.", whatIs: { title: "¿Qué es el Cáncer de Testículos?", text: "Es la proliferación de células malignas dentro de los tejidos testiculares. Es uno de los tipos de cáncer con mayor tasa de curación, superando el 95% si se detecta a tiempo, e incluso respondiendo excelentemente bien a las terapias oncológicas cuando se ha diseminado fuera de la ingle." }, types: { title: "Tipos de Tumores Germinales", intro: "Casi todos estos cánceres comienzan en las células que producen el esperma:", items: ["Seminomas (crecen y se propagan más lentamente, responden de forma extremadamente eficaz y sensible a la radioterapia y quimioterapia, siendo algo más comunes en hombres en la treintena o mayores)", "No seminomas (tienden a crecer y propagarse linfáticamente mucho más rápidamente que los seminomas, e incluyen subtipos como el carcinoma embrionario, tumor del saco vitelino y coriocarcinoma)"], note: "Tener el historial o el antecedente médico infantil de un testículo no descendido (criptorquidia) aumenta en proporciones gigantescas y drásticas el riesgo a lo largo de la vida de padecerlo." }, diagnosis: { title: "Detección Sólida y Confirmación", intro: "El paciente a menudo es el primero en detectar un bulto anormal, tras lo cual se realizan:", items: ["Ecografía del escroto y los testículos (la prueba inmediata por excelencia que revela sin ninguna duda si el bulto sospechoso en cuestión es sólido -tumor- o si es un saco inofensivo lleno y simple de líquido -quiste o hidrocele-)", "Análisis de sangre estricto para medir la alta concentración y cantidad en sangre de marcadores tumorales de tipo hormonal (AFP, hCG y LDH)", "Tomografía Computarizada (TC) de todo el área del abdomen, la pelvis y el tórax entero (exigida obligatoriamente para la etapa de estadificación oncológica del paciente y ver si algún ganglio abdominal o pulmón ya ha sido invadido)", "Orquiectomía radical inguinal (es la operación quirúrgica inicial donde se retira el testículo enfermo por la ingle para su biopsia final; la biopsia con aguja invasiva no se efectúa nunca por riesgo total de esparcir las células)"], note: "" }, treatment: { title: "Extirpación y Tratamiento Complementario", intro: "Es de alta supervivencia y la terapia busca la eliminación total de rastro del tumor en el organismo:", subsections: [ { title: "Pasos Quirúrgicos y Químicos", items: ["Orquiectomía radical (la extirpación física del testículo, suele ser el paso inicial y a veces el único paso curativo requerido en los tumores detectados en fases iniciales y muy prematuras)", "Vigilancia activa rigurosa a largo plazo (realizar escáneres y análisis de marcadores en sangre periódicos de manera estricta y constante en lugar de radiación tras una cirugía de etapa 1 para evitar excesos médicos)", "Radioterapia local de enfoque (utilizada fundamentalmente para los tumores seminomatosos que han penetrado en la vía del retroperitoneo)", "Quimioterapia con cisplatino sistémica e inyecciones intravenosas (necesaria para erradicar las metástasis y a los no seminomas que viajaron a ganglios o pulmones)"] } ], note: "Por causa del daño a la espermatogénesis por las cirugías y quimioterapia intensa, los pacientes deberían buscar y considerar seriamente guardar muestras y utilizar un banco de esperma congelado (criopreservación) previo a empezar a tratarse el cáncer." }, whenToSeekHelp: { title: "¿Cuándo recurrir de forma inminente a valoración de un Urólogo?", intro: "Debes buscar e inspeccionarte con un especialista urológico si en tu autoexamen normal observas o notas síntomas claros o difusos de anomalía, como:", items: ["Detectas visualmente o mediante palpación la presencia en la piel o profundidad de un bulto notable, nódulo firme, callosidad dura o bulto inflamatorio engrosado completamente indoloro y silencioso en uno o ambos testículos", "Sientes y percibes un aumento muy severo del volumen habitual con acumulación súbita muy pronunciada de agua o de líquido claro dentro del escroto, que resulta muy pesada para aguantar", "Experimentas un persistente dolor sordo, una incomodidad prolongada inexplicable, un extraño y pesado adormecimiento u hormigueo tenso que se concentra abajo o muy por debajo del área del estómago y del ombligo (abdomen bajo) o a la altura o a través de toda la misma ingle irradiándose interiormente"] } },
'Obstrucción intestinal' : { intro: "La obstrucción intestinal es un bloqueo patológico que impide de manera parcial o total que los alimentos, líquidos, secreciones y gases transiten libremente por el intestino delgado o grueso, requiriendo atención urgente.", whatIs: { title: "¿Qué es una Obstrucción Intestinal?", text: "Es la detención del tránsito digestivo normal. Puede causar que la presión se acumule en el intestino, lo que, si no se alivia, puede cortar el flujo sanguíneo a los tejidos intestinales y provocar isquemia, necrosis o perforación (peritonitis)." }, types: { title: "Causas y Orígenes", intro: "La interrupción se provoca por un obstáculo físico o por parálisis muscular:", items: ["Obstrucción mecánica (causada por adherencias posquirúrgicas, hernias estranguladas, impactación fecal o tumores sólidos)", "Íleo paralítico (el intestino no tiene un bloqueo físico, pero sus músculos se paralizan temporalmente debido a infecciones, cirugías recientes o ciertos medicamentos)"], note: "Las adherencias abdominales de cirugías pasadas son la causa más común en adultos." }, diagnosis: { title: "Evaluación Médica Urgente", intro: "Se determina mediante exploración y pruebas de imagen:", items: ["Examen físico del abdomen (buscando distensión, rigidez y ruidos intestinales anormales)", "Tomografía Computarizada (TC) o radiografía abdominal (para localizar el punto exacto y la causa del bloqueo)", "Análisis de sangre (para evaluar infecciones o desequilibrios de electrolitos)"], note: "" }, treatment: { title: "Descompresión y Cirugía", intro: "El tratamiento requiere hospitalización inmediata:", subsections: [ { title: "Intervenciones", items: ["Ayuno absoluto y administración de líquidos intravenosos", "Colocación de una sonda nasogástrica (un tubo por la nariz hasta el estómago para succionar aire y líquidos, aliviando la presión)", "Cirugía de urgencia (si hay un bloqueo mecánico completo, estrangulación o tejido muerto)"] } ], note: "Muchos bloqueos parciales o íleos paralíticos mejoran en pocos días solo con reposo intestinal e hidratación IV." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude de inmediato a Urgencias si presentas:", items: ["Dolor abdominal severo, tipo cólico e intermitente", "Incapacidad para evacuar las heces o eliminar gases", "Vómitos repetitivos (especialmente si tienen olor o color fecal)", "Hinchazón y distensión masiva del abdomen"] } },
'Tuberculosis pulmonar' : { intro: "La tuberculosis (TB) pulmonar es una enfermedad infecciosa bacteriana grave que afecta principalmente a los pulmones. Es altamente contagiosa pero prevenible y curable si se trata de forma adecuada y oportuna.", whatIs: { title: "¿Qué es la Tuberculosis Pulmonar?", text: "Es una infección causada por la bacteria Mycobacterium tuberculosis. Se transmite a través del aire cuando una persona enferma tose, estornuda o escupe. La bacteria destruye el tejido pulmonar, causando cavernas y síntomas respiratorios crónicos." }, types: { title: "Fases de la Infección", intro: "No todas las personas infectadas se enferman de inmediato:", items: ["TB Latente (la bacteria está en el cuerpo en estado inactivo, no causa síntomas y no es contagiosa)", "TB Activa (la bacteria se multiplica y causa síntomas, es altamente contagiosa y destructiva)", "TB Miliar o Extrapulmonar (la infección bacteriana se disemina de los pulmones a otros órganos vitales por el torrente sanguíneo)"], note: "Las personas con sistemas inmunológicos debilitados (como VIH) tienen un riesgo extremo de desarrollar TB activa." }, diagnosis: { title: "Detección y Confirmación", intro: "El diagnóstico combina pruebas inmunológicas y radiológicas:", items: ["Prueba cutánea de la tuberculina (PPD) o análisis de sangre (IGRA) para detectar si hay contacto previo con la bacteria", "Radiografía de tórax (busca manchas blancas o cavernas en los pulmones donde se esconde la infección)", "Prueba y cultivo de esputo (analizar la flema bajo microscopio para confirmar la presencia de la bacteria)"], note: "" }, treatment: { title: "Erradicación Antibiótica Prolongada", intro: "El tratamiento de la TB requiere un compromiso muy estricto y largo:", subsections: [ { title: "Medicamentos", items: ["Curso prolongado de antibióticos múltiples (isoniazida, rifampicina, etambutol, pirazinamida) tomados diariamente durante 6 a 9 meses sin interrupción", "Aislamiento respiratorio inicial (durante las primeras semanas hasta que se deje de ser contagioso)", "Terapia Observada Directamente (DOT) para asegurar que el paciente no olvide ninguna dosis"] } ], note: "Suspender los medicamentos antes de tiempo provoca la aparición de cepas de TB multirresistentes, que son extremadamente difíciles y largas de curar." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca ayuda médica inmediata y usa mascarilla si presentas:", items: ["Tos severa y constante que dura más de tres semanas", "Dolor agudo en el pecho, o tos con sangre y mucosidad (esputo)", "Sudores nocturnos excesivos, fiebre recurrente y escalofríos", "Pérdida de peso involuntaria rápida y fatiga profunda"] } },
'Enfermedad fibroquística de las mamas' : { intro: "La enfermedad fibroquística de las mamas (cambios fibroquísticos) es una afección benigna y sumamente común donde el tejido mamario se siente grumoso, denso o con una textura similar a la de una cuerda. No es una enfermedad maligna ni aumenta el riesgo de cáncer.", whatIs: { title: "¿Qué son los cambios fibroquísticos?", text: "Son variaciones en la textura del tejido de los senos que responden intensamente a las fluctuaciones hormonales del ciclo menstrual. Se desarrollan quistes llenos de líquido y un engrosamiento de los tejidos conectivos (fibrosis), volviendo los senos dolorosos, hinchados y sensibles." }, types: { title: "Características", intro: "Los síntomas tienden a fluctuar a lo largo del mes:", items: ["Bultos o masas que se sienten movibles, lisos y bien definidos (a menudo quistes)", "Sensibilidad y dolor que empeoran justo antes de la menstruación y mejoran después de que esta pasa", "Secreción por el pezón no sanguinolenta (generalmente de color verde oscuro o marrón transparente)"], note: "Más de la mitad de las mujeres experimentan estos cambios en algún momento de su vida." }, diagnosis: { title: "Evaluación Médica", intro: "El ginecólogo descartará cualquier problema maligno:", items: ["Examen clínico de las mamas", "Ecografía mamaria (la herramienta ideal para diferenciar quistes de líquido inofensivos de masas sólidas)", "Mamografía (para buscar otras anomalías si la mujer tiene más de 40 años)", "Aspiración con aguja fina (para drenar el líquido del quiste, confirmando el diagnóstico y aliviando el dolor)"], note: "" }, treatment: { title: "Manejo y Alivio", intro: "Si no hay síntomas severos, no requiere tratamiento. De lo contrario, se busca alivio:", subsections: [ { title: "Opciones de Cuidado", items: ["Uso de un sostén de buen soporte y sin aros metálicos constantes", "Analgésicos de venta libre (AINEs como ibuprofeno)", "Aplicación de calor local", "Anticonceptivos orales (para estabilizar los niveles hormonales y reducir la formación de quistes)"] } ], note: "Reducir o eliminar el consumo de cafeína ayuda a muchas mujeres a reducir el dolor y la sensibilidad." }, whenToSeekHelp: { title: "¿Cuándo solicitar revisión?", intro: "Debes ir a tu médico para una revisión exhaustiva si:", items: ["Descubres un bulto nuevo o inusual, o un área de engrosamiento que no desaparece después de tu menstruación", "El dolor en los senos es continuo o empeora progresivamente fuera de tus ciclos", "Aparece una secreción sanguinolenta, clara o espontánea de uno de los pezones"] } },
'Autismo' : { intro: "El Trastorno del Espectro Autista (TEA), o autismo, es una condición del neurodesarrollo caracterizada por diferencias significativas en la comunicación, la interacción social y por la presencia de patrones de comportamiento, intereses o actividades restringidas y repetitivas.", whatIs: { title: "¿Qué es el Autismo?", text: "Es una condición neurobiológica que afecta cómo el cerebro procesa la información. Como es un 'espectro', cada persona lo experimenta de manera muy diferente. Algunas personas autistas tienen habilidades extraordinarias y requieren poco apoyo, mientras que otras pueden tener dificultades severas de aprendizaje o no hablar." }, types: { title: "Niveles de Apoyo", intro: "El DSM-5 clasifica el autismo según el nivel de asistencia que necesita la persona:", items: ["Nivel 1: Requiere apoyo (dificultad para iniciar interacciones sociales, inflexibilidad conductual leve)", "Nivel 2: Requiere apoyo sustancial (déficits marcados en habilidades de comunicación verbal/no verbal, estrés evidente al cambiar el foco de acción)", "Nivel 3: Requiere apoyo muy sustancial (alteraciones severas en la comunicación social, comportamientos repetitivos muy limitantes)"], note: "Suele acompañarse de hiper o hiposensibilidad a estímulos sensoriales (luces, ruidos, texturas de ropa o comida)." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El diagnóstico clínico requiere una evaluación multidisciplinaria especializada:", items: ["Observación directa del comportamiento, juego y habilidades de comunicación del niño", "Evaluación estandarizada por psicólogos, neurólogos infantiles y psiquiatras (ej. escala ADOS-2, ADI-R)", "Descarte de problemas auditivos o trastornos genéticos asociados"], note: "Las señales suelen ser evidentes antes de los 3 años de edad." }, treatment: { title: "Intervenciones y Terapias", intro: "El autismo no tiene cura ni es una enfermedad a erradicar; el enfoque es maximizar el potencial y la independencia:", subsections: [ { title: "Estrategias de Apoyo", items: ["Intervenciones conductuales y educativas tempranas (como el método ABA, terapia ocupacional y del habla)", "Programas educativos individualizados adaptados en la escuela", "Terapia de integración sensorial", "Medicación (únicamente para tratar síntomas asociados o comorbilidades como ansiedad, irritabilidad severa o TDAH)"] } ], note: "La aceptación neurodivergente y la adaptación del entorno son claves para el bienestar de la persona autista." }, whenToSeekHelp: { title: "¿Cuándo sospechar y buscar evaluación?", intro: "Es fundamental buscar una evaluación pediátrica del desarrollo si el niño:", items: ["No responde a su nombre a los 12 meses de edad", "No señala objetos para mostrar interés (como un avión volando) a los 14 meses", "Evita el contacto visual y prefiere jugar absolutamente solo", "Presenta un retraso en el habla o pierde habilidades de lenguaje que ya había adquirido", "Repite palabras o frases exactamente iguales constantemente (ecolalia) o tiene aleteo de manos recurrente"] } },
'Trastorno límite de la personalidad' : { intro: "El trastorno límite de la personalidad (TLP) o borderline es una enfermedad de salud mental que afecta gravemente la capacidad de una persona para regular sus emociones. Esta pérdida de control emocional aumenta la impulsividad y afecta drásticamente cómo la persona se siente consigo misma y sus relaciones con los demás.", whatIs: { title: "¿Qué es el TLP?", text: "Es un trastorno caracterizado por estados de ánimo, comportamiento y relaciones extremadamente inestables. Las personas con TLP suelen tener un terror intenso al abandono (real o imaginario) y presentan dificultades para tolerar estar solos, experimentando emociones como ira inapropiada o vacío crónico." }, types: { title: "Características Centrales", intro: "Los síntomas más prominentes incluyen:", items: ["Miedo intenso al abandono y esfuerzos frenéticos por evitarlo", "Un patrón de relaciones inestables e intensas (idealizar a alguien y luego devaluarlo repentinamente)", "Autoimagen inestable (cambios rápidos en la identidad y valores personales)", "Comportamientos impulsivos y riesgosos (apuestas, sexo inseguro, atracones, conducción temeraria)", "Comportamiento suicida recurrente, gestos o amenazas, y autolesiones (cortes)"], note: "Suele surgir en la edad adulta temprana y mejora gradualmente con la edad y tratamiento." }, diagnosis: { title: "Evaluación Psicológica", intro: "Se diagnostica mediante una evaluación profunda por un psiquiatra o psicólogo clínico:", items: ["Entrevista clínica exhaustiva revisando patrones de vida y síntomas", "Cuestionarios psicológicos para trastornos de personalidad", "Descarte exhaustivo de otros trastornos del estado de ánimo como la depresión o trastorno bipolar"], note: "Los pacientes suelen buscar ayuda primero por crisis de ansiedad o depresión y luego se detecta el TLP." }, treatment: { title: "Manejo y Psicoterapia", intro: "El tratamiento primario e indispensable es la psicoterapia especializada:", subsections: [ { title: "Opciones Terapéuticas", items: ["Terapia Dialéctica Conductual (DBT) (el estándar de oro diseñado específicamente para el TLP; enseña habilidades para controlar las emociones, tolerar la angustia y mejorar las relaciones)", "Terapia centrada en esquemas o psicoterapia centrada en la transferencia", "Medicamentos (no curan el TLP, pero antidepresivos, antipsicóticos atípicos o estabilizadores del ánimo se recetan para tratar los síntomas depresivos, ira o impulsividad severa)", "Hospitalización breve (solo en casos de crisis aguda para mantener al paciente seguro ante riesgo de suicidio)"] } ], note: "La recuperación requiere de mucha paciencia, pero muchas personas con TLP logran una vida estable y satisfactoria." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda urgente?", intro: "Debe solicitarse atención médica o de urgencia psiquiátrica inmediata si:", items: ["La persona se autolesiona de forma severa (como cortes profundos o quemaduras) o tiene ideas suicidas activas", "Los altibajos emocionales y la ira provocan daños graves a otros o violencia física", "Experimenta paranoias intensas o se desconecta de la realidad (disociación) durante episodios de estrés alto"] } },
'Masas cutáneas de grasa' : { intro: "Las masas cutáneas de grasa, conocidas médicamente como lipomas, son bultos redondeados u ovalados de tejido adiposo que crecen justo debajo de la piel. Son tumores benignos extremadamente comunes que rara vez requieren tratamiento a menos que duelan o sean molestos estéticamente.", whatIs: { title: "¿Qué es un Lipoma?", text: "Es un crecimiento lento e inofensivo de las células de grasa encapsuladas en una fina capa fibrosa. Suelen sentirse suaves y pastosos al tacto, y se mueven fácilmente bajo la piel cuando se les presiona con el dedo. Nunca son cáncer." }, types: { title: "Variantes Comunes", intro: "Los lipomas pueden aparecer en cualquier parte del cuerpo, típicamente en:", items: ["Cuello, hombros, espalda, abdomen, brazos y muslos", "Lipomas convencionales (solo grasa, los más frecuentes)", "Angiolipomas (contienen muchos vasos sanguíneos y suelen ser los únicos que duelen)", "Lipomatosis familiar múltiple (condición hereditaria de tener múltiples lipomas por todo el cuerpo)"], note: "La mayoría miden menos de 5 centímetros, pero algunos pueden crecer considerablemente a lo largo de los años." }, diagnosis: { title: "Examen Dermatológico", intro: "El médico suele diagnosticarlos clínicamente en el consultorio:", items: ["Examen físico y palpación directa del bulto blando y móvil", "Ecografía o Resonancia Magnética si el bulto es inusualmente grande, profundo, o tiene características atípicas", "Biopsia (muy rara vez, solo si hay sospecha remota de un liposarcoma, que es un cáncer de grasa raro y de crecimiento rápido)"], note: "" }, treatment: { title: "Observación y Extirpación", intro: "Un lipoma no necesita tratamiento. Sin embargo, si se desea quitar, las opciones son:", subsections: [ { title: "Procedimientos Quirúrgicos", items: ["Vigilancia médica (si el lipoma no causa dolor ni molestias, simplemente se deja en paz)", "Extirpación quirúrgica completa (procedimiento ambulatorio simple con anestesia local; es la cura definitiva, rara vez vuelven a crecer en el mismo lugar)", "Liposucción (usar una aguja y una jeringa grande para extraer la grasa, útil para lipomas grandes en áreas estéticas)"] } ], note: "No se deben intentar pinchar, apretar ni drenar en casa, ya que esto solo causará infecciones graves sin eliminar la cápsula del lipoma." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico para revisión?", intro: "Aunque son inofensivos, debes mostrarle cualquier bulto a un médico para descartar problemas graves, especialmente si:", items: ["El bulto duele, se vuelve sensible, enrojece o se siente caliente", "El tamaño de la masa aumenta muy rápida y repentinamente (los lipomas normales tardan años en crecer un poco)", "Se siente duro, sólido e inamovible (fijo al tejido subyacente), en lugar de blando y movible"] } },
'Lupus' : { intro: "El lupus (lupus eritematoso sistémico o LES) es una enfermedad autoinmune crónica y compleja que causa inflamación en todo el cuerpo. Debido a que puede afectar diversos órganos (piel, articulaciones, riñones, cerebro, corazón), a menudo se le llama 'el gran imitador', ya que sus síntomas imitan otras enfermedades.", whatIs: { title: "¿Qué es el Lupus?", text: "Es una disfunción del sistema inmunológico. En lugar de proteger el cuerpo contra virus y bacterias, el sistema inmune produce autoanticuerpos que atacan y destruyen el tejido conectivo sano de la propia persona, causando dolor crónico, daño orgánico e inflamación persistente." }, types: { title: "Tipos de Lupus", intro: "Existen diferentes formas de la enfermedad:", items: ["Lupus eritematoso sistémico (LES) (el más común y generalizado, afectando múltiples órganos del cuerpo)", "Lupus cutáneo (afecta únicamente la piel, provocando erupciones)", "Lupus inducido por medicamentos (desencadenado por ciertos fármacos, suele desaparecer cuando se suspende la medicación)", "Lupus neonatal (muy raro, ocurre en bebés de madres con lupus, afectando piel, hígado y corazón)"], note: "Es más frecuente en mujeres en edad fértil y se desarrolla con periodos de actividad de la enfermedad (brotes) y remisión." }, diagnosis: { title: "Evaluación Reumatológica Completa", intro: "No existe una sola prueba para el lupus; el diagnóstico requiere unir piezas del rompecabezas:", items: ["Análisis de Anticuerpos Antinucleares (ANA) (prueba de sangre clave, casi todos los pacientes con lupus dan positivo, aunque no es exclusivo del lupus)", "Examen físico buscando la clásica erupción en forma de alas de mariposa en las mejillas y nariz", "Análisis de orina (para comprobar si hay daño en los riñones), de sangre (anemia, plaquetas bajas) y pruebas de marcadores de inflamación", "Biopsia de piel o tejido renal (para observar el daño autoinmune)"], note: "" }, treatment: { title: "Control Autoinmune y Síntomas", intro: "No tiene cura. El tratamiento se centra en apagar la respuesta inmune, prevenir brotes y proteger los órganos:", subsections: [ { title: "Medicamentos Inmunosupresores", items: ["Medicamentos antipalúdicos (Hidroxicloroquina, el pilar central del tratamiento que controla los brotes leves y el dolor articular/cutáneo)", "Corticosteroides (Prednisona, para apagar rápidamente inflamaciones severas en brotes graves)", "Inmunosupresores más fuertes (Metotrexato, Azatioprina) para casos severos que afectan órganos mayores", "Terapias biológicas inyectables (Belimumab, Anifrolumab) y rigurosa protección solar para evitar reactivaciones"] } ], note: "La exposición al sol y el estrés agudo son los principales desencadenantes de los brotes de lupus." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico especialista?", intro: "Es fundamental acudir a un reumatólogo si experimentas una combinación de:", items: ["Una erupción roja en las mejillas y la nariz (eritema malar) que empeora drásticamente con la exposición solar", "Fatiga paralizante, fiebre inexplicada recurrente y pérdida de peso", "Dolor en las articulaciones, rigidez e hinchazón migratoria en el cuerpo", "Dolor punzante en el pecho al respirar profundamente (pleuritis) o dedos que se vuelven pálidos o azules con el frío (Fenómeno de Raynaud)"] } },
'Artrosis' : { intro: "La artrosis, o enfermedad articular degenerativa (osteoartritis), es la forma más común de artritis en el mundo. Ocurre cuando el cartílago liso y protector que recubre los extremos de los huesos de las articulaciones se desgasta de manera progresiva a lo largo de los años.", whatIs: { title: "¿Qué es la Artrosis?", text: "Es una enfermedad crónica y degenerativa de desgaste articular. Al perderse el cartílago amortiguador, el hueso expuesto roza con el otro hueso durante el movimiento, causando inflamación local, fricción dolorosa, espolones óseos (osteofitos) y una pérdida gradual del movimiento en la articulación." }, types: { title: "Factores y Zonas Frecuentes", intro: "Aunque puede dañar cualquier articulación, afecta predominantemente a:", items: ["Rodillas y caderas (articulaciones de carga, muy agravadas por el sobrepeso o la obesidad)", "Columna vertebral (zona lumbar baja y cuello cervical)", "Manos (especialmente en la base del pulgar y las articulaciones de los dedos, formando pequeños nódulos duros)", "Se divide en Primaria (relacionada simplemente con el envejecimiento y la genética) y Secundaria (por traumatismos, cirugías previas o defectos articulares)"], note: "El desgaste del cartílago no puede revertirse ni curarse médicamente." }, diagnosis: { title: "Evaluación Médica y Radiológica", intro: "El diagnóstico de desgaste articular es sumamente visual y clínico:", items: ["Examen físico palpando la articulación, buscando crujidos dolorosos (crepitación), hinchazón ósea y pérdida de rango de movimiento", "Radiografías (rayos X, la herramienta principal que mostrará claramente un espacio más estrecho entre los huesos y la presencia de espolones óseos)", "Resonancia Magnética (RM) (solo se usa en casos complicados para evaluar los tejidos blandos circundantes o meniscos dañados)"], note: "" }, treatment: { title: "Manejo del Dolor y Prótesis", intro: "El enfoque es aliviar el dolor crónico, mantener la función de movimiento y mejorar el estilo de vida:", subsections: [ { title: "Opciones de Terapia", items: ["Pérdida de peso significativa (crítica para aliviar la presión mecánica en rodillas y caderas) y Fisioterapia", "Medicamentos analgésicos de venta libre (paracetamol), antiinflamatorios (AINEs como ibuprofeno oral o en gel tópico)", "Infiltraciones articulares (inyecciones de corticosteroides para alivio rápido de inflamación, o ácido hialurónico para lubricar la articulación temporalmente)", "Cirugía de reemplazo articular total (artroplastia de rodilla o cadera, cuando la articulación está totalmente destruida y el dolor es inmanejable)"] } ], note: "Evitar el movimiento por miedo al dolor es perjudicial; el ejercicio de bajo impacto (natación, bicicleta estática) lubrica las articulaciones y fortalece el músculo que las soporta." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista (reumatólogo o traumatólogo)?", intro: "Deberías pedir ayuda médica ortopédica si:", items: ["El dolor articular crónico o la rigidez te dificulta enormemente realizar tareas cotidianas, como vestirte, subir escaleras o caminar", "Sufres una rigidez matutina en las articulaciones que tarda unos 30 minutos en aflojar", "Las articulaciones afectadas se sienten inestables, 'suenan' ruidosamente y se inflaman tras un día de uso", "Los analgésicos comunes y el reposo ya no te brindan alivio del dolor persistente"] } },
'Trastorno depresivo grave' : { intro: "El trastorno depresivo grave (TDG), también conocido como depresión mayor o depresión clínica, es una enfermedad mental incapacitante y abrumadora que afecta el estado de ánimo general, la energía, el pensamiento y el comportamiento, alterando completamente la vida de la persona.", whatIs: { title: "¿Qué es el Trastorno Depresivo Grave?", text: "Es una condición patológica originada por cambios biológicos y químicos en el cerebro, a menudo provocada por estrés extremo, genética o traumas. No es una simple 'debilidad de carácter' ni se cura 'esforzándose'. El paciente se sumerge en una tristeza constante, apatía profunda y un sentimiento total de vacío que dura semanas o meses continuos." }, types: { title: "Manifestaciones Clínicas Críticas", intro: "Sus síntomas más severos y característicos incluyen:", items: ["Ánimo deprimido casi todo el día, casi todos los días (llanto, vacío o desesperanza profunda)", "Anhedonia o pérdida total y absoluta de placer o interés en casi todas las actividades y pasatiempos", "Alteraciones físicas radicales (insomnio masivo o hipersomnia, pérdida de peso sin dieta o aumento severo de apetito, lentitud motora)", "Dificultad incapacitante para pensar, concentrarse, retener información o tomar la más mínima decisión", "Pensamientos intrusivos y recurrentes de muerte, planificación o intentos directos de suicidio"], note: "" }, diagnosis: { title: "Evaluación Psiquiátrica Formal", intro: "El médico, psiquiatra o psicólogo basa el diagnóstico en directrices estrictas:", items: ["Entrevista psiquiátrica clínica, evaluando criterios exactos del manual diagnóstico (DSM-5) durante un periodo superior a dos semanas seguidas", "Cuestionarios de depresión (PHQ-9) para medir y registrar la gravedad y letalidad de los síntomas", "Examen físico y de laboratorio sanguíneo para descartar con total seguridad problemas de tiroides, falta de vitaminas o infecciones virales ocultas"], note: "" }, treatment: { title: "Intervenciones Multimodales Salva Vidas", intro: "Es una condición altamente tratable. La combinación de medicación y psicoterapia es el protocolo clínico de mayor éxito:", subsections: [ { title: "Terapias Farmacológicas y Psicológicas", items: ["Medicamentos antidepresivos (Inhibidores Selectivos de la Recaptación de Serotonina -ISRS-, que pueden tardar de 3 a 6 semanas en funcionar, o inhibidores duales)", "Psicoterapia profunda (Terapia Cognitivo-Conductual, Terapia Dialéctica Conductual para manejar emociones y reestructurar pensamientos trágicos)", "Terapia electroconvulsiva (TEC), Estimulación Magnética Transcraneal o terapias con Ketamina para pacientes agudos, catatónicos o con resistencia severa a todas las pastillas", "Hospitalización y estancia clínica de salud mental inmediata si el riesgo de autolesión inminente es elevado"] } ], note: "Nadie debe dejar un antidepresivo abruptamente bajo ninguna circunstancia, el síndrome de abstinencia y 'rebote' depresivo es severo." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE buscar intervención?", intro: "Esta es una emergencia médica. Llama de inmediato a emergencias, líneas de prevención o acude al hospital si:", items: ["Tú o la persona afectada planean o expresan firmemente un deseo real de quitarse la vida, o se despiden extrañamente regalando sus cosas", "Experimentas alucinaciones o delirios (episodios psicóticos asociados a la depresión)", "Tu incapacidad para salir de la cama y cuidar de tu higiene personal o comer lleva días y estás desnutrido"] } },
'Fractura coronal' : { intro: "Una fractura coronal es un tipo específico de traumatismo y daño dental. Ocurre cuando se rompe y se pierde una porción de la 'corona' del diente (la parte blanca y visible que se asoma por encima de las encías), usualmente a causa de un impacto físico directo contra la boca.", whatIs: { title: "¿Qué es una Fractura Coronal?", text: "Es la rotura traumática de la estructura superior del diente, comúnmente en los dientes frontales o incisivos. Dependiendo de la profundidad del impacto, el corte puede afectar solamente la primera capa dura (esmalte), la capa intermedia sensible (dentina) o llegar a exponer la pulpa blanda central donde están los nervios y vasos sanguíneos." }, types: { title: "Clasificación de Severidad del Diente Roto", intro: "Los dentistas evalúan el nivel del daño estructural:", items: ["Infracción del esmalte (microfisuras o grietas minúsculas superficiales que no pierden estructura ni requieren tratamiento, solo observación)", "Fractura de esmalte y dentina sin exposición pulpar (el diente se rompe y falta un trozo, es sensible al aire y al frío, pero el nervio está a salvo y no sangra)", "Fractura coronaria complicada o exposición pulpar (el diente se rompe profundamente dejando a la vista un punto rojo sangrante y un nervio expuesto y vivo; produce un dolor agudo y severo)"], note: "Guardar el pedazo de diente roto que se cayó puede ayudar al dentista a pegarlo de nuevo si está intacto." }, diagnosis: { title: "Examen Odontológico de Urgencia", intro: "El especialista determinará el tratamiento realizando:", items: ["Examen intraoral visual, lavando y observando si el nervio está expuesto y evaluando la movilidad del diente dañado", "Transiluminación clínica (iluminar el diente para ver fisuras o fracturas ocultas)", "Radiografías periapicales de la raíz (absolutamente esenciales para descartar que, además de la corona, la raíz dentro del hueso no se haya partido)", "Pruebas de sensibilidad o vitalidad pulpar (con spray frío) para comprobar si el nervio dental murió por el golpe"], note: "" }, treatment: { title: "Restauración y Endodoncia", intro: "El tratamiento varía drásticamente desde un pulido simple hasta terapias de conducto:", subsections: [ { title: "Opciones de Rehabilitación Dental", items: ["Reconstrucción o adhesión (bonding) con resinas compuestas estéticas (empastes blancos) si la rotura es pequeña y no afecta al nervio", "Reunión del fragmento (si lograste llevar el pedazo de diente limpio, el dentista a menudo puede pegarlo con adhesivos de última generación)", "Tratamiento de conducto radicular o endodoncia (si la pulpa nerviosa está expuesta o muere, se debe extraer el tejido infectado y sellar la raíz)", "Coronas de porcelana (si el diente perdió gran parte de su estructura y una resina no aguantaría la fuerza de la mordida)"] } ], note: "Incluso las lesiones leves que parecen estar bien pueden resultar en que el diente se ponga oscuro (muerte del nervio) meses o años después del accidente." }, whenToSeekHelp: { title: "¿Cuándo acudir al dentista de emergencia?", intro: "Es preciso solicitar ayuda o revisión dental a la mayor brevedad si:", items: ["Te partiste un diente y ves un punto rojo, rosado o sangrado salir del mismo centro del interior del diente", "El pedazo de diente roto te causa un dolor lancinante, agudo e insoportable cuando respiras por la boca o bebes algo frío", "Los bordes de la fractura son tan afilados que cortan y hieren severamente tu lengua, tus labios o las mejillas por dentro"] } },
'Blefaritis' : { intro: "La blefaritis es una inflamación ocular crónica muy frecuente que afecta los bordes de los párpados, justamente en el área donde nacen y crecen las pestañas. Hace que los ojos se sientan arenosos, irritados y que los párpados se hinchen, se enrojezcan y piquen.", whatIs: { title: "¿Qué es la Blefaritis?", text: "Es una afección ocular irritante y recurrente producida cuando las minúsculas glándulas sebáceas (glándulas de Meibomio) ubicadas en la base de las pestañas se obstruyen. Esto puede ser provocado por una superpoblación de bacterias normales de la piel, la presencia de ácaros (Demodex) o enfermedades cutáneas como la rosácea o caspa." }, types: { title: "Tipos de Inflamación Palpebral", intro: "La afección se clasifica dependiendo de la parte del párpado afectada:", items: ["Blefaritis anterior (ocurre en el borde externo y frontal del párpado donde se unen las pestañas; originada comúnmente por infección bacteriana -estafilococo- o por caspa severa del cuero cabelludo y las cejas)", "Blefaritis posterior o disfunción de las glándulas de Meibomio (la más común, afecta la parte interna del párpado; las glándulas que producen el componente graso de las lágrimas se tapan)", "Blefaritis mixta (presenta características de ambas, inflamando tanto la base de las pestañas como las glándulas)"], note: "Es la causa principal del molesto y crónico 'síndrome del ojo seco' y de la aparición constante de orzuelos o chalaziones." }, diagnosis: { title: "Examen Oftalmológico Visual", intro: "No se necesitan pruebas de laboratorio complejas; el oftalmólogo la diagnostica con:", items: ["Examen visual utilizando una lámpara de hendidura (un microscopio potente con una luz brillante) para examinar meticulosamente las glándulas del margen de los párpados, la piel y las propias pestañas", "Evaluación de las costras y escamas grasientas (caspa) en la base de las pestañas", "Muestra con hisopo en el párpado (raramente, solo para enviar a cultivo si la infección es grave o no mejora con el tratamiento estándar, descartando bacterias resistentes)"], note: "" }, treatment: { title: "Higiene y Manejo Crónico", intro: "No tiene cura definitiva, pero una rutina de limpieza férrea puede mantener a raya los síntomas por completo:", subsections: [ { title: "Régimen de Limpieza y Terapias", items: ["Compresas tibias y calientes obligatorias (colocadas sobre los ojos cerrados durante 5 a 10 minutos para derretir y aflojar el aceite espeso tapado en las glándulas)", "Higiene estricta de párpados y masajes (lavar los bordes de las pestañas diariamente con un hisopo, agua tibia y champú de bebé muy suave, o toallitas oftalmológicas especiales limpiadoras)", "Medicamentos antibióticos (en pomadas o cremas aplicadas directamente en el borde del ojo, o antibióticos orales como doxiciclina para reducir la carga bacteriana y desinflamar)", "Gotas oftálmicas antiinflamatorias de esteroides (para recetarse a corto plazo si hay hinchazón grave), o lágrimas artificiales (para aliviar el ojo seco secundario)"] } ], note: "El maquillaje de ojos y las lentes de contacto deben ser retirados y suspendidos de inmediato y hasta que la blefaritis se cure por completo." }, whenToSeekHelp: { title: "¿Cuándo solicitar asistencia oftalmológica?", intro: "Programa una revisión con un profesional del ojo si los cuidados de higiene con agua caliente y toallitas en casa no ayudan, y tienes:", items: ["Sensación constante, intensa y desesperante de tener un grano de arena o un cuerpo extraño raspando en los ojos", "Ojos que amanecen completamente pegados, sellados o muy costrosos, haciendo difícil abrirlos por las mañanas", "Pérdida de pestañas, caída inusual de las mismas, o estas empiezan a crecer de forma anormal hacia adentro irritando la córnea (triquiasis)"] } },
'Insuficiencia arterial' : { intro: "La insuficiencia arterial, o enfermedad arterial periférica (EAP), es una alteración cardiovascular frecuente en la que el estrechamiento y endurecimiento de las arterias reducen drásticamente el flujo de sangre y oxígeno a las extremidades, usualmente afectando primero a las piernas y los pies.", whatIs: { title: "¿Qué es la Insuficiencia Arterial?", text: "Es la manifestación sistémica de la aterosclerosis, el mismo proceso de acumulación de placas de colesterol y calcio que causa los ataques cardíacos. Al estrecharse los tubos de transporte, los músculos y tejidos de las piernas no obtienen suficiente oxígeno durante la actividad y, en fases graves, sufren daño estando incluso en reposo." }, types: { title: "Etapas y Progresión Clínica", intro: "La severidad de la falta de flujo marca la gravedad de la enfermedad:", items: ["Asintomática (placas formándose, flujos disminuidos, pero el paciente no siente ningún dolor todavía)", "Claudicación Intermitente (dolor tipo calambre sordo en las pantorrillas, muslos o glúteos que aparece siempre al caminar cierta distancia y desaparece mágicamente a los pocos minutos de reposo)", "Isquemia Crónica que amenaza las extremidades (dolor agudo ardiente en los pies y dedos que duele incluso en la cama durante la noche, piel muy pálida y fría)", "Isquemia Aguda (bloqueo total y repentino por un trombo; la pierna se pone blanca, fría, se paraliza y es una emergencia de amputación)"], note: "Fumar tabaco es el factor de riesgo absoluto más fuerte y letal para desarrollar esta enfermedad y agravarla velozmente." }, diagnosis: { title: "Evaluación Vascular no Invasiva", intro: "El especialista vascular detecta la enfermedad con pruebas de presión y ecografía:", items: ["Prueba del Índice Tobillo-Brazo o ITB (la herramienta inicial más simple y rápida: compara la presión arterial del tobillo con la del brazo; si la del tobillo es inferior, la sangre no llega bien a las piernas)", "Ecografía vascular Doppler (utiliza ondas sonoras para ver directamente la sangre fluyendo y localizar las arterias bloqueadas estrechadas)", "Angiografía por tomografía computarizada (Angio-TC) o cateterismo directo (para trazar un mapa detallado del bloqueo si se requiere cirugía)"], note: "" }, treatment: { title: "Revascularización y Cambios de Hábitos", intro: "La meta es detener el endurecimiento, prevenir el dolor e impedir amputaciones e infartos:", subsections: [ { title: "Terapias de Rescate y Soporte", items: ["Modificaciones de vida radicales e inmediatas (abandonar total y estrictamente el tabaquismo, y una terapia controlada y dolorosa de caminatas para forzar al cuerpo a crear 'nuevos caminos' o circulación colateral)", "Medicamentos prescritos rigurosamente (estatinas para el colesterol, medicamentos para bajar la presión arterial, antiagregantes plaquetarios como aspirina o cilostazol para dilatar vasos y prevenir coágulos)", "Angioplastia y colocación de stent vascular (un tubo minúsculo de malla se expande dentro de la arteria bloqueada a través de un catéter, sin cirugía abierta)", "Cirugía de derivación arterial (bypass periférico), usando una vena del paciente o un tubo artificial para desviar el flujo esquivando y rodeando el segmento bloqueado grave"] } ], note: "Cuidar celosamente la salud de los pies con cremas, calzado apropiado y no caminar descalzo previene que las pequeñas heridas o callosidades terminen en gangrena y amputación." }, whenToSeekHelp: { title: "¿Cuándo es indispensable una emergencia vascular?", intro: "Requieres atención médica rápida o visita a Urgencias (si los síntomas son bruscos) si:", items: ["Experimentas un dolor de pies, calambres y dolor ardiente intenso al dormir por la noche que solo se alivia si te levantas de la cama o cuelgas la pierna fuera de ella", "Observas que tienes llagas, cortadas pequeñas, úlceras o heridas en los dedos de los pies o tobillos que no sanan después de varias semanas o empiezan a volverse negras y con mal olor", "Sientes que tu pie, pierna o brazo de un solo lado se vuelve llamativamente frío al tacto en comparación con el otro, o cambia su color a muy pálido o un tono azulado (urgencia inminente isquémica)"] } },
'Alergias a fármacos' : { intro: "Una alergia a un fármaco o medicamento es una reacción inmunitaria grave, anormal y peligrosa del cuerpo contra un medicamento específico. Cualquier medicamento, ya sea de venta libre, recetado o a base de hierbas, es capaz de inducir una respuesta alérgica o de rechazo profundo.", whatIs: { title: "¿Qué es una Alergia a un Fármaco?", text: "Ocurre cuando tu sistema inmunológico identifica erróneamente un medicamento (que debería curarte) como si fuera una sustancia extraña, tóxica e invasora virulenta (como un virus). En respuesta, el cuerpo crea anticuerpos y libera sustancias químicas como histaminas y citoquinas inflamatorias masivas, lo que desata los síntomas de la reacción alérgica en minutos, horas o días." }, types: { title: "Medicamentos Responsables Comunes y Tipos", intro: "Los fármacos que con más frecuencia desencadenan respuestas alérgicas extremas son:", items: ["Antibióticos, especialmente la penicilina y sus derivados, y las sulfamidas", "Analgésicos y antiinflamatorios (como aspirina e ibuprofeno)", "Medicamentos de quimioterapia oncológica", "Medicamentos para enfermedades autoinmunes", "El tipo de reacción alérgica puede ser 'inmediata' mediada por IgE (peligrosa y ocurre en menos de 1 hora) o 'retardada' mediada por células T (sarpullidos extensos que salen días o semanas tras tomar la pastilla)"], note: "Es vital diferenciar una alergia real (sistema inmunológico) de un 'efecto secundario' de un medicamento (como dolor de estómago por antibióticos, que no es alérgico ni peligroso)." }, diagnosis: { title: "Investigación Clínica Alergológica", intro: "Un diagnóstico erróneo es común; el alergólogo empleará métodos estrictos:", items: ["Historia clínica aguda detalladísima sobre el momento de la ingesta y la manifestación visible del sarpullido", "Pruebas cutáneas especializadas intradérmicas o de parche (solo validadas clínicamente para muy pocos medicamentos, especialmente las penicilinas, y siempre en entorno hospitalario)", "Prueba oral o desafío farmacológico (bajo una estricta vigilancia de emergencia, se administra el medicamento en minidosis progresivas para comprobar si la alergia existe o ya desapareció)", "Análisis sanguíneo (escasamente útiles salvo para confirmar reacciones extremas o síndromes tras el evento)"], note: "" }, treatment: { title: "Atención Inmediata y Substitución Médica", intro: "El tratamiento prioritario es siempre retirar el agresor, tratar los síntomas y encontrar alternativas seguras:", subsections: [ { title: "Intervenciones Críticas", items: ["Suspensión drástica e inmediata de la medicina o del fármaco que está causando la presunta reacción", "Inyección inmediata de Adrenalina o Epinefrina de rescate de urgencia (si hay signos asfixiantes o de anafilaxia letal)", "Administración hospitalaria o domiciliaria de Antihistamínicos orales fuertes o Corticosteroides sistémicos (para calmar los picores, las ronchas y apagar severamente la respuesta y sarpullido inflamatorio en piel y garganta)", "Desensibilización farmacológica alérgica (un proceso médico especializado en un hospital en el cual se fuerza a alguien con alergia conocida, por ejemplo, a la quimioterapia, a tolerarla de emergencia dándole dosis microscópicas en aumento)"] } ], note: "Deberás utilizar un brazalete médico grabado para toda tu vida informando claramente de tus alergias, ya que volver a tomarlo inadvertidamente es letal." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ir a una sala de emergencias (Anafilaxia)?", intro: "Llama al 911 y corre al hospital más cercano o inyéctate adrenalina (EpiPen) al primer signo de anafilaxia o fallo tras tomar cualquier medicamento:", items: ["Dificultad o restricción grave de las vías respiratorias y de la respiración (sientes un silbido en tu pecho al respirar)", "Aparición e hinchazón general severa (edema) repentina, especialmente en tu rostro, en los párpados de tus ojos, en los labios o un 'nudo ahogante' cerrado en la lengua y garganta", "Mareos profundamente severos incontrolables, pulso alterado o rápido que te hace perder por completo el conocimiento, y caída drástica total de la presión arterial y desmayo", "Una urticaria, grandes ampollas, descamaciones graves o erupciones rojas dolorosísimas y generalizadas en tu piel, e incluso sangrado o desprendimiento de las membranas bucales o genitales"] } },
'Quemaduras' : { intro: "Las quemaduras son daños al tejido del cuerpo causados por el calor, sustancias químicas, electricidad, luz solar o radiación. Su gravedad varía ampliamente, desde enrojecimientos superficiales leves hasta daños profundos que ponen en riesgo la vida.", whatIs: { title: "¿Qué son las Quemaduras?", text: "Son lesiones en la piel u otros tejidos orgánicos que causan la muerte celular de las zonas afectadas. La gravedad se determina por la profundidad de la lesión y la extensión de la superficie corporal quemada." }, symptoms: { title: "Síntomas", intro: "Varían según la profundidad del daño cutáneo:", groups: [ { name: "Signos Superficiales", items: ["Enrojecimiento de la piel (eritema)", "Dolor al tacto", "Hinchazón leve"] }, { name: "Signos Profundos", items: ["Aparición de ampollas llenas de líquido", "Piel de aspecto blanco, carbonizado o correoso", "Ausencia de dolor inicial si los nervios fueron destruidos"] } ], warning: "Las quemaduras eléctricas y químicas pueden causar daños internos severos no visibles." }, types: { title: "Grados de Quemaduras", intro: "Se clasifican en tres niveles principales:", items: ["Primer grado (afectan solo la capa externa o epidermis)", "Segundo grado (afectan la epidermis y la dermis inferior, causando ampollas)", "Tercer grado (afectan las capas profundas, grasa y a veces músculo u hueso)"], note: "Las quemaduras de tercer grado siempre requieren atención médica especializada inmediata." }, causes: { title: "Causas Comunes", intro: "Los accidentes más frecuentes involucran:", items: ["Líquidos hirvientes o vapor", "Fuego directo o llamas", "Sustancias químicas fuertes (ácidos o bases)", "Corrientes eléctricas", "Exposición excesiva a radiación UV (sol)"] }, diagnosis: { title: "Evaluación", intro: "El médico evalúa:", items: ["La profundidad del daño tisular", "El porcentaje de superficie corporal total afectada (Regla de los Nueve)", "Posibles lesiones por inhalación de humo en las vías respiratorias"], note: "Las quemaduras graves requieren evaluación en una unidad de quemados hospitalaria." }, treatment: { title: "Tratamiento", intro: "Depende estrictamente del grado y extensión:", subsections: [ { title: "Opciones", items: ["Enfriamiento con agua templada y analgésicos de venta libre (quemaduras leves)", "Cremas antibióticas y apósitos estériles (quemaduras de segundo grado)", "Líquidos intravenosos para prevenir shock, debridamiento y cirugía de injertos de piel (quemaduras severas)"] } ], note: "No se debe aplicar hielo directo, mantequilla ni remedios caseros en quemaduras recientes." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Llama a emergencias o ve al hospital si:", items: ["La quemadura es profunda, carbonizada o seca", "Afecta la cara, manos, pies, genitales o una articulación principal", "La quemadura es por sustancias químicas o electricidad", "El paciente tiene dificultad para respirar"] } },
'Enfermedad de Meniere' : { intro: "La enfermedad de Meniere es un trastorno crónico del oído interno que afecta el equilibrio y la audición. Provoca episodios repentinos y severos de vértigo, acúfenos (zumbidos en los oídos) y una pérdida auditiva fluctuante.", whatIs: { title: "¿Qué es la Enfermedad de Meniere?", text: "Es una afección causada por la acumulación anormal de líquido (endolinfa) en el laberinto, la parte del oído interno que controla el equilibrio y la audición. Esta acumulación interfiere con las señales nerviosas normales que van al cerebro." }, symptoms: { title: "Síntomas", intro: "Los ataques suelen ocurrir sin previo aviso:", groups: [ { name: "Principales", items: ["Episodios graves de vértigo (sensación de que todo gira)", "Pérdida de audición fluctuante, típicamente en un solo oído", "Tinnitus (zumbido, rugido o silbido en el oído)", "Sensación de presión o plenitud en el oído afectado"] } ], warning: "Los episodios de vértigo pueden ser tan severos que provocan caídas abruptas (crisis de Tumarkin)." }, types: { title: "Progresión", intro: "La enfermedad suele avanzar en etapas:", items: ["Etapa temprana (ataques repentinos de vértigo y pérdida auditiva que se recupera)", "Etapa tardía (los ataques de vértigo pueden disminuir, pero la pérdida de audición y el tinnitus se vuelven permanentes)"], note: "Suele afectar a un solo oído, pero en algunos casos puede volverse bilateral." }, causes: { title: "Causas", intro: "Se desconoce la causa exacta, pero se asocia a:", items: ["Drenaje inadecuado del líquido del oído interno", "Respuesta inmunitaria anormal", "Infecciones virales", "Predisposición genética"] }, diagnosis: { title: "Diagnóstico", intro: "El especialista (otorrinolaringólogo) indicará:", items: ["Audiometría para evaluar la pérdida auditiva", "Pruebas de equilibrio (Electronistagmografía o pruebas en silla rotatoria)", "Resonancia Magnética (RM) para descartar otras patologías como tumores cerebrales"], note: "El diagnóstico requiere un historial de ataques recurrentes y hallazgos auditivos confirmados." }, treatment: { title: "Manejo y Tratamiento", intro: "No tiene cura, pero se pueden controlar los síntomas:", subsections: [ { title: "Opciones", items: ["Medicamentos para los mareos y náuseas durante los ataques", "Dieta baja en sal y diuréticos para reducir la retención de líquidos", "Inyecciones en el oído medio (antibióticos o esteroides)", "Cirugía del saco endolinfático o sección del nervio vestibular (casos extremos)"] } ], note: "Las terapias de rehabilitación vestibular pueden ayudar a manejar el desequilibrio entre ataques." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental buscar ayuda si:", items: ["Experimentas episodios repentinos y severos de mareo o vértigo", "Notas pérdida de audición en un oído", "Sientes zumbidos fuertes o presión constante en el oído"] } },
'Escoliosis' : { intro: "La escoliosis es una curvatura lateral anormal de la columna vertebral que ocurre con mayor frecuencia durante el período de crecimiento acelerado justo antes de la pubertad. La mayoría de los casos son leves, pero algunas curvas empeoran a medida que el niño crece.", whatIs: { title: "¿Qué es la Escoliosis?", text: "Normalmente, la columna vertebral se ve recta desde atrás. En la escoliosis, la columna se curva hacia los lados, formando una 'S' o una 'C', y a menudo las vértebras también rotan, causando asimetría en la espalda." }, symptoms: { title: "Señales Físicas", intro: "A menudo es indolora en niños y se detecta visualmente:", groups: [ { name: "Signos Posturales", items: ["Hombros desparejos (uno más alto que el otro)", "Un omóplato que sobresale más que el otro", "Cintura desigual o una cadera más alta", "Inclinación del cuerpo hacia un lado"] } ], warning: "Las curvas muy severas pueden reducir el espacio en el pecho, dificultando el funcionamiento de los pulmones." }, types: { title: "Tipos de Escoliosis", intro: "Se clasifica según su origen:", items: ["Idiopática (la más común, de causa desconocida, aparece en la adolescencia)", "Congénita (presente al nacer debido a malformaciones óseas fetales)", "Neuromuscular (causada por afecciones como parálisis cerebral o distrofia muscular)"], note: "La escoliosis degenerativa puede ocurrir en adultos mayores debido al desgaste espinal." }, causes: { title: "Causas y Factores", intro: "Aunque la idiopática no tiene causa clara, contribuyen:", items: ["Factores genéticos (tiende a darse en familias)", "Afecciones neuromusculares", "Defectos de nacimiento en la columna", "Infecciones o lesiones de la columna (menos común)"] }, diagnosis: { title: "Evaluación Médica", intro: "Se detecta en chequeos escolares o por el pediatra:", items: ["Test de flexión hacia adelante de Adams (el paciente se inclina y se observa asimetría en la espalda)", "Examen neurológico básico", "Radiografías de columna completa (para medir la curva en grados mediante el Ángulo de Cobb)"], note: "Curvas mayores a 10 grados se diagnostican oficialmente como escoliosis." }, treatment: { title: "Opciones de Tratamiento", intro: "El manejo depende de la madurez ósea y la gravedad de la curva:", subsections: [ { title: "Intervenciones", items: ["Observación y chequeos regulares (para curvas leves en niños en crecimiento)", "Uso de corsé ortopédico (para prevenir que la curva empeore durante el estirón de crecimiento)", "Fisioterapia específica (ejercicios Schroth)", "Cirugía de fusión espinal (para curvas graves, generalmente mayores de 45-50 grados)"] } ], note: "Los corsés no corrigen la curva existente, pero son muy eficaces para detener su avance." }, whenToSeekHelp: { title: "¿Cuándo consultar al traumatólogo?", intro: "Solicita una revisión ortopédica si notas:", items: ["Desnivel evidente en los hombros, caderas o cintura de tu hijo", "Dolor de espalda inusual o limitante en un niño o adolescente", "Dificultad para respirar relacionada con una deformidad en el pecho"] } },
'Alta miopía' : { intro: "La alta miopía, o miopía magna, es un error de refracción severo en el que el globo ocular se alarga excesivamente. No es solo la necesidad de usar gafas gruesas; es una condición patológica que aumenta drásticamente el riesgo de complicaciones oculares graves.", whatIs: { title: "¿Qué es la Alta Miopía?", text: "Se define como una miopía superior a -6.00 dioptrías o un globo ocular con una longitud axial anormal. El alargamiento extremo estira y adelgaza la retina y otras estructuras posteriores del ojo, haciéndolas vulnerables a daños." }, symptoms: { title: "Síntomas Visuales", intro: "Además de la visión borrosa clásica:", groups: [ { name: "Señales y Complicaciones", items: ["Visión de lejos extremadamente borrosa sin corrección", "Aparición frecuente de moscas volantes (miodesopsias) y destellos de luz", "Visión distorsionada (metamorfopsias) si afecta la mácula", "Pérdida de campo visual si ocurre un desprendimiento"] } ], warning: "Es una causa principal de ceguera evitable si ocurren complicaciones maculares o retinianas." }, types: { title: "Clasificación", intro: "Se diferencia de la miopía común por sus implicaciones:", items: ["Miopía simple (defecto refractivo estable)", "Miopía patológica/magna (crecimiento ocular continuo con cambios degenerativos en la retina, coroides y esclerótica)"], note: "Suele desarrollarse en la niñez temprana y puede seguir progresando en la adultez." }, causes: { title: "Factores Causales", intro: "Tiene un fuerte componente hereditario:", items: ["Genética (altamente hereditaria si ambos padres son miopes)", "Elongación excesiva del eje anteroposterior del globo ocular", "Factores ambientales y falta de tiempo al aire libre en la infancia"] }, diagnosis: { title: "Evaluación Oftalmológica", intro: "Requiere monitoreo estricto de por vida:", items: ["Examen de refracción visual completo", "Fondo de ojo con pupila dilatada (crítico para revisar la retina periférica)", "Tomografía de coherencia óptica (OCT) para evaluar la mácula", "Ecografía ocular para medir la longitud axial"], note: "Las revisiones anuales o semestrales son obligatorias." }, treatment: { title: "Manejo y Corrección", intro: "Combina corrección visual y prevención de ceguera:", subsections: [ { title: "Tratamientos", items: ["Corrección con gafas de alto índice o lentes de contacto especiales", "Cirugía refractiva (Lentes intraoculares fáquicas o ICL, a menudo preferidas sobre láser por el grosor de la córnea)", "Fotocoagulación con láser (para sellar desgarros retinianos preventivos)", "Inyecciones anti-VEGF (si desarrollan neovascularización macular miope)"] } ], note: "El láser refractivo clásico (LASIK) a menudo no se recomienda si el grado es demasiado alto." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "Acude a urgencias oftalmológicas de inmediato si:", items: ["Sufres una lluvia repentina de moscas volantes o destellos luminosos", "Sientes que una 'cortina' negra cubre una parte de tu visión (signo de desprendimiento de retina)", "Pierdes la visión central de forma súbita"] } },
'Desgaste de rodilla' : { intro: "El desgaste de rodilla, médicamente conocido como artrosis de rodilla o gonartrosis, es la enfermedad degenerativa más común que afecta a esta articulación. Provoca dolor progresivo, pérdida de movilidad y afecta la calidad de vida.", whatIs: { title: "¿Qué es el Desgaste de Rodilla?", text: "Es la degradación y pérdida gradual del cartílago hialino, el tejido liso que recubre y amortigua los extremos de los huesos en la rodilla (fémur y tibia). Al perder este amortiguador, los huesos rozan entre sí, generando inflamación y espolones óseos." }, symptoms: { title: "Síntomas Clásicos", intro: "Los síntomas se desarrollan lentamente a lo largo de los años:", groups: [ { name: "Sensaciones y Movilidad", items: ["Dolor en la rodilla que empeora al caminar, subir escaleras o estar de pie", "Rigidez articular, especialmente por la mañana (que mejora en menos de 30 minutos) o tras estar sentado", "Crujidos, chasquidos o sensación de fricción al mover la rodilla (crepitación)", "Hinchazón dura y pérdida de flexibilidad"] } ], warning: "En etapas avanzadas, el dolor ocurre incluso en reposo y puede causar deformidad visible ('piernas arqueadas')." }, types: { title: "Clasificación", intro: "Se divide según su causa de origen:", items: ["Artrosis primaria (relacionada con el envejecimiento, la genética y el desgaste natural)", "Artrosis secundaria (consecuencia de lesiones antiguas, fracturas, roturas de menisco/ligamentos previas o sobrepeso extremo)"], note: "Afecta más frecuentemente a personas mayores de 50 años." }, causes: { title: "Factores de Riesgo", intro: "El desgaste se acelera por:", items: ["Edad avanzada", "Obesidad (cada kilo extra ejerce gran presión sobre la rodilla)", "Traumatismos o lesiones deportivas pasadas", "Sobrecarga ocupacional (trabajos que implican arrodillarse mucho)", "Debilidad muscular en las piernas"] }, diagnosis: { title: "Diagnóstico Médico", intro: "El traumatólogo lo confirma mediante:", items: ["Examen físico evaluando puntos de dolor, deformidad y rango de movimiento", "Radiografías de rodilla (muestran un estrechamiento del espacio entre los huesos y osteofitos)", "Rara vez Resonancia Magnética (solo para evaluar tejidos blandos o meniscos concomitantes)"], note: "" }, treatment: { title: "Manejo y Cirugía", intro: "El cartílago no se regenera, el objetivo es el alivio sintomático:", subsections: [ { title: "Opciones de Tratamiento", items: ["Pérdida de peso fundamental y Fisioterapia para fortalecer los cuádriceps", "Analgésicos (Paracetamol) y antiinflamatorios (AINEs) orales o tópicos", "Infiltraciones articulares (corticosteroides para inflamación rápida o ácido hialurónico para lubricación)", "Cirugía de reemplazo articular (artroplastia total o parcial de rodilla, altamente exitosa en estadios finales)"] } ], note: "Mantenerse en movimiento con ejercicios de bajo impacto (ciclismo, natación) es esencial; el sedentarismo empeora la artrosis." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Solicita ayuda médica ortopédica si:", items: ["El dolor de rodilla no mejora con descanso y medicación básica", "La rodilla cede, falsea o se 'traba' mientras caminas", "Tienes un dolor tan fuerte que te despierta por la noche o impide tus actividades diarias", "Notas una hinchazón importante y deformidad en la pierna"] } },
'Trastorno de identidad de género' : { intro: "El Trastorno de Identidad de Género, hoy clasificado clínicamente en el DSM-5 como Disforia de Género, se refiere a la angustia profunda y el malestar que siente una persona cuando su identidad de género interna no coincide con el sexo que se le asignó al nacer.", whatIs: { title: "¿Qué es la Disforia de Género?", text: "Ser transgénero o tener una identidad de género diversa no es una enfermedad mental. Sin embargo, la 'disforia' es el diagnóstico clínico que describe la intensa aflicción emocional y psicológica resultante de esta incongruencia, la cual requiere atención médica, psicológica y a menudo de afirmación de género para aliviar el sufrimiento." }, symptoms: { title: "Manifestaciones Clínicas", intro: "Se presenta de manera diferente en niños y adultos, pero incluye:", groups: [ { name: "Indicadores Emocionales y Sociales", items: ["Una fuerte convicción de tener el género opuesto (o un género alternativo)", "Deseo intenso de deshacerse de las características sexuales primarias o secundarias (pechos, vello, genitales)", "Angustia severa, ansiedad y depresión vinculadas a la apariencia corporal", "Fuerte preferencia por la vestimenta, los roles y las amistades asociadas al género experimentado"] } ], warning: "La disforia no tratada tiene altísimas tasas de depresión grave, aislamiento y riesgo de suicidio." }, types: { title: "Aparición", intro: "El momento de inicio define las necesidades de apoyo:", items: ["Disforia de género de inicio en la infancia (a menudo observada a través del juego y la negativa a usar cierta ropa)", "Disforia de género en adolescentes y adultos (se intensifica brutalmente con los cambios corporales incontrolables de la pubertad)"], note: "No todas las personas con variabilidad de género experimentan disforia clínica." }, causes: { title: "Causas", intro: "La identidad de género es intrínseca:", items: ["Factores biológicos complejos (desarrollo prenatal del cerebro)", "Factores hormonales y genéticos", "NO es una 'fase', una elección de estilo de vida ni el resultado de la crianza"] }, diagnosis: { title: "Evaluación Especializada", intro: "Un profesional de la salud mental especializado realiza la evaluación:", items: ["Entrevistas clínicas profundas basadas en los criterios del DSM-5", "Confirmación de que la incongruencia y la angustia han persistido por al menos seis meses", "Evaluación de la salud mental general para tratar posibles condiciones concurrentes (ansiedad, depresión)"], note: "El diagnóstico clínico es a menudo un requisito previo necesario para acceder a coberturas médicas para tratamientos físicos de afirmación." }, treatment: { title: "Atención de Afirmación de Género", intro: "El tratamiento no busca cambiar la identidad de la persona, sino alinear su cuerpo y rol social para aliviar la disforia:", subsections: [ { title: "Opciones de Intervención", items: ["Psicoterapia de apoyo (para acompañar el proceso de exploración, autoaceptación y transición social, no para 'curar' la identidad)", "Transición social (cambio de pronombres, nombre, vestimenta y expresión de género)", "Tratamientos hormonales (bloqueadores de pubertad en jóvenes, o terapia de reemplazo hormonal feminizante/masculinizante en adultos)", "Cirugías de afirmación de género (cirugías torácicas o genitales, según los objetivos y necesidades del individuo adulto)"] } ], note: "El apoyo familiar incondicional es el factor protector más grande contra las consecuencias trágicas en salud mental de jóvenes con disforia." }, whenToSeekHelp: { title: "¿Cuándo buscar apoyo profesional?", intro: "Es fundamental buscar ayuda especializada y compasiva si:", items: ["Los sentimientos de incongruencia sobre tu género causan dolor emocional continuo, ansiedad o desesperación", "Estás considerando comenzar una transición médica y necesitas orientación sobre los procesos hormonales y quirúrgicos", "Tienes pensamientos de hacerte daño o suicidarte debido a la insatisfacción con tu cuerpo o el rechazo social"] } },
'Cáncer de piel en célula basal' : { intro: "El cáncer de piel en célula basal (carcinoma basocelular) es el tipo de cáncer de piel más común en el mundo. Aunque es un tumor maligno, crece de forma extremadamente lenta, casi nunca se propaga (hace metástasis) a otras partes del cuerpo y es altamente curable si se trata a tiempo.", whatIs: { title: "¿Qué es el Carcinoma Basocelular?", text: "Es una alteración maligna que comienza en las células basales, un tipo de célula de la capa superior de la piel que produce células nuevas a medida que mueren las viejas. Es causado por el daño genético provocado por la radiación ultravioleta (UV) acumulada durante años." }, symptoms: { title: "Signos Visuales", intro: "Aparece usualmente en zonas expuestas al sol (cabeza, cuello, rostro):", groups: [ { name: "Apariencia de las Lesiones", items: ["Un bulto perlado o ceroso, a menudo con vasos sanguíneos diminutos visibles en la superficie", "Una llaga abierta que sangra, supura, forma costra, sana y vuelve a sangrar repetidamente", "Una mancha plana, similar a una cicatriz de color blanco o amarillo ceroso sin bordes definidos", "Un parche rojizo o irritado en el pecho o la espalda"] } ], warning: "Rara vez causa dolor o molestias, por lo que a menudo la gente lo ignora creyendo que es una espinilla persistente." }, types: { title: "Tipos Clínicos", intro: "Se divide según su forma de crecimiento:", items: ["Nodular (el más común, un bulto perlado)", "Superficial (parece una mancha de eccema rojo)", "Morfeiforme o esclerosante (el más invasivo localmente, parece una cicatriz blanca y plana y sus raíces van profundas)"], note: "El color de la lesión puede variar y, a veces, puede ser oscuro en personas con tonos de piel más oscuros." }, causes: { title: "Factores Causales", intro: "Está directamente relacionado con el sol:", items: ["Exposición prolongada e intermitente a los rayos UV del sol a lo largo de la vida", "Uso de camas solares o lámparas de bronceado", "Piel clara, pecas y cabello rubio o pelirrojo (menor protección de melanina)", "Edad avanzada y antecedentes familiares"] }, diagnosis: { title: "Evaluación Dermatológica", intro: "El diagnóstico es rápido en consulta:", items: ["Examen clínico de la piel utilizando un dermatoscopio (lupa especial iluminada)", "Biopsia de la lesión cutánea (se adormece el área, se raspa o corta el bulto y se envía al laboratorio para confirmación celular)"], note: "" }, treatment: { title: "Extirpación y Cura", intro: "El objetivo es eliminar todo el cáncer; las tasas de éxito superan el 95%:", subsections: [ { title: "Tratamientos Procedimentales", items: ["Escisión quirúrgica (cortar el tumor junto con un margen de piel sana)", "Cirugía Micrográfica de Mohs (el tratamiento de oro para la cara: el cirujano retira y examina el tejido capa por capa en el microscopio hasta no ver cáncer, preservando la mayor cantidad de piel sana)", "Curetaje y electrodesecación (raspar el tumor y quemar la base con electricidad, usado en tumores superficiales)", "Cremas tópicas quimioterápicas (como Imiquimod o Fluorouracilo) para lesiones superficiales iniciales", "Crioterapia (congelación) o Radioterapia (en pacientes que no pueden operarse)"] } ], note: "Quien ha tenido un carcinoma basocelular tiene un riesgo muy alto de desarrollar otro en el futuro; las revisiones anuales son obligatorias." }, whenToSeekHelp: { title: "¿Cuándo visitar al dermatólogo?", intro: "Pide una cita si notas en tu piel:", items: ["Un bulto 'perlado', una llaga o espinilla que sangra y no se cura completamente después de 3 a 4 semanas", "Una herida que forma una costra, se cae y vuelve a sangrar repetidamente en el mismo lugar exacto", "Una mancha parecida a una cicatriz blanca o amarilla que crece lentamente"] } },
'Dolor en la espalda' : { intro: "El dolor en la espalda, particularmente la lumbalgia, es una de las razones más comunes por las que las personas acuden al médico o faltan al trabajo. Puede variar desde un dolor sordo y constante hasta un dolor punzante y repentino que dificulta el movimiento.", whatIs: { title: "¿Qué es el Dolor de Espalda?", text: "Es una molestia física que ocurre a lo largo de la columna vertebral o los músculos asociados, desde el cuello hasta la pelvis. En la gran mayoría de los casos es de origen mecánico, resultante del estrés o tensión en músculos, ligamentos o discos." }, symptoms: { title: "Características del Dolor", intro: "La forma en que duele indica a menudo su causa:", groups: [ { name: "Tipos de Dolor", items: ["Dolor muscular generalizado (sordo y constante, empeora con ciertas posturas)", "Dolor punzante o fulgurante (similar a una descarga eléctrica)", "Dolor radicular (dolor que baja e irradia por la pierna, a menudo bajo la rodilla, indicando compresión nerviosa)", "Dolor que empeora al levantar peso, agacharse o caminar, y mejora al recostarse"] } ], warning: "Si el dolor se acompaña de pérdida del control de esfínteres, es una urgencia vital (Síndrome de Cauda Equina)." }, types: { title: "Clasificación Temporal", intro: "El dolor se clasifica por su duración:", items: ["Agudo (aparece repentinamente tras un esfuerzo, dura de unos días a unas semanas)", "Subagudo (dura entre 4 y 12 semanas)", "Crónico (persiste durante 12 semanas o más, incluso después de tratada la lesión inicial)"], note: "El dolor agudo rara vez requiere estudios de imagen invasivos iniciales." }, causes: { title: "Causas Comunes", intro: "El origen puede ser muscular, óseo o nervioso:", items: ["Distensión muscular o de ligamentos (levantar peso excesivo repetidamente)", "Discos abultados o rotos (hernias discales que presionan nervios)", "Osteoartritis (desgaste de las articulaciones de la columna)", "Irregularidades esqueléticas (escoliosis severa)", "Osteoporosis (provocando fracturas por compresión vertebral)"] }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Para dolores persistentes, el médico investigará:", items: ["Examen físico neurológico (revisando la capacidad de sentarse, pararse, fuerza y reflejos)", "Radiografías (muestran solo problemas de huesos, artrosis o fracturas)", "Resonancia Magnética o TC (si hay signos de dolor nervioso o sospecha de hernia de disco)", "Análisis de sangre (para descartar infecciones o cáncer, si hay signos de alarma)"], note: "" }, treatment: { title: "Manejo y Recuperación", intro: "El tratamiento inicial suele ser conservador:", subsections: [ { title: "Terapias", items: ["Medicamentos (Analgésicos de venta libre, AINEs, relajantes musculares por periodos cortos)", "Aplicación de frío/calor y mantenerse activo (el reposo absoluto en cama está contraindicado y empeora el problema)", "Fisioterapia (el tratamiento principal a mediano plazo para fortalecer la musculatura del core y mejorar la flexibilidad)", "Inyecciones de cortisona en el espacio epidural", "Cirugía (reservada como última opción para dolor radicular crónico intratable o inestabilidad espinal)"] } ], note: "Cuidar la postura y el peso corporal previenen futuras recaídas." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Contacta a un médico de inmediato si el dolor de espalda:", items: ["Sigue a un traumatismo fuerte (como una caída o accidente de tráfico)", "Viene acompañado de problemas intestinales o de la vejiga nuevos", "Está acompañado de fiebre inexplicable o pérdida de peso involuntaria", "Provoca debilidad grave, entumecimiento u hormigueo intenso en una o ambas piernas"] } },
'Hidrocele' : { intro: "Un hidrocele es un tipo de inflamación del escroto que ocurre cuando se acumula líquido en el recubrimiento delgado que rodea el testículo. Es común en los recién nacidos y suele desaparecer sin tratamiento, pero también puede desarrollarse en niños mayores y hombres adultos.", whatIs: { title: "¿Qué es un Hidrocele?", text: "Es una colección de líquido seroso, benigna e indolora, entre las capas de la túnica vaginal del testículo. Hace que el escroto (la bolsa que contiene los testículos) luzca hinchado o agrandado, similar a un globo lleno de agua." }, symptoms: { title: "Síntomas", intro: "Generalmente no causa dolor, sino una molestia física:", groups: [ { name: "Signos Clínicos", items: ["Agrandamiento e hinchazón en uno o ambos lados del escroto", "Sensación de pesadez o arrastre en el escroto (en adultos)", "La hinchazón a menudo cambia de tamaño a lo largo del día, siendo menor por la mañana y mayor tras la actividad"] } ], warning: "Si el aumento de tamaño va acompañado de dolor agudo y repentino, podría ser una torsión testicular, no un hidrocele." }, types: { title: "Tipos de Hidrocele", intro: "Se clasifican según su comunicación con el abdomen:", items: ["Hidrocele comunicante (común en bebés, el conducto por donde el testículo bajó al escroto no se cerró, permitiendo que el líquido abdominal entre y salga del escroto)", "Hidrocele no comunicante (el conducto está cerrado, pero el cuerpo no absorbe el líquido atrapado; puede ocurrir en adultos por inflamación o lesión)"], note: "Los hidroceles en adultos a menudo se relacionan con infecciones locales o traumatismos." }, causes: { title: "Causas y Factores", intro: "Las causas difieren por la edad:", items: ["En bebés: Desarrollo embrionario normal donde el conducto inguinal no se sella.", "En adultos: Lesiones escrotales, inflamación del testículo o del epidídimo (epididimitis), infecciones, o en casos raros, tumores testiculares."] }, diagnosis: { title: "Evaluación Urológica", intro: "El diagnóstico es rápido en consulta:", items: ["Examen físico del escroto hinchado (el médico notará que el bulto contiene líquido y no es una masa sólida)", "Prueba de transiluminación (al aplicar una linterna brillante sobre el escroto, la luz traspasa el líquido transparente del hidrocele)", "Ecografía testicular (para confirmar y descartar definitivamente hernias, tumores sólidos o infecciones)"], note: "" }, treatment: { title: "Manejo y Cirugía", intro: "Si no causa molestias, el tratamiento no es urgente:", subsections: [ { title: "Intervenciones", items: ["Observación (la mayoría de los hidroceles en lactantes desaparecen solos antes del año de vida)", "Hidrocelectomía (cirugía ambulatoria a través de una incisión en el escroto o la ingle para drenar el líquido y extirpar/suturar el saco que lo produce, evitando que regrese)", "Aspiración con aguja (drenaje del líquido, aunque casi siempre el líquido vuelve a acumularse rápidamente, usado solo si la cirugía no es posible)"] } ], note: "Es un procedimiento de bajo riesgo con tasas de éxito casi totales tras la cirugía." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes buscar evaluación médica si:", items: ["Tú o tu hijo presentan una hinchazón nueva o creciente en el escroto", "La hinchazón escrotal se vuelve repentinamente dolorosa o enrojecida", "Un bebé todavía tiene hidrocele después del año de edad", "Notas un bulto sólido y duro dentro del escroto, en lugar de una hinchazón suave"] } },
'Lesiones ligamentarias en mano y muñeca' : { intro: "Las lesiones ligamentarias en la mano y la muñeca son desgarros o estiramientos severos de las bandas de tejido resistente que mantienen unidos los huesos. Son causadas casi siempre por caídas donde la persona intenta detenerse apoyando la mano abierta.", whatIs: { title: "¿Qué son estas Lesiones?", text: "Se trata de esguinces en la compleja red de pequeños ligamentos que dan estabilidad a la muñeca y los dedos. Cuando la articulación se dobla o flexiona más allá de su límite natural, los ligamentos se rompen, causando inestabilidad, pérdida de fuerza de agarre y dolor agudo." }, symptoms: { title: "Síntomas", intro: "Dependen de la gravedad del desgarro:", groups: [ { name: "Señales Inmediatas", items: ["Dolor severo e inmediato en la muñeca o articulación del dedo", "Hinchazón rápida y aparición de moretones (hematomas) locales", "Sensación de 'chasquido' o 'pop' en el momento de la lesión", "Incapacidad para mover la mano normalmente, debilidad en el agarre o articulación inestable (floja)"] } ], warning: "Algunas lesiones de muñeca, como la del ligamento escafolunar, pueden causar artritis crónica grave si no se diagnostican rápido." }, types: { title: "Lesiones Específicas Comunes", intro: "Afectan zonas clave de la mano:", items: ["Esguince de muñeca común (estiramiento de ligamentos menores)", "Desgarro del ligamento escafolunar (una lesión grave y frecuente en la muñeca que separa los huesos del carpo)", "Pulgar del esquiador o guardabosques (rotura del ligamento colateral cubital del pulgar, imposibilitando pellizcar o agarrar objetos)", "Esguinces de las articulaciones de los dedos (frecuentes en deportes de pelota)"], note: "Se clasifican en grados del 1 (leve) al 3 (rotura completa)." }, causes: { title: "Mecanismo de Lesión", intro: "Ocurren por traumatismos directos o palancas articulares:", items: ["Caer sobre una mano extendida (la causa número uno de esguinces de muñeca)", "Impactos bruscos en deportes (como que un balón golpee la punta del dedo extendido)", "Torsiones violentas por el uso de herramientas o en accidentes automovilísticos"] }, diagnosis: { title: "Evaluación Ortopédica", intro: "Requiere un examen minucioso por un especialista en mano:", items: ["Examen físico con maniobras de provocación para probar la estabilidad de la articulación", "Radiografías (necesarias siempre para descartar pequeñas fracturas óseas muy comunes en la mano, como la del hueso escafoides)", "Resonancia Magnética o Arteriografía (para confirmar roturas completas de ligamentos no visibles en radiografías)"], note: "" }, treatment: { title: "Inmovilización y Reparación Quirúrgica", intro: "El objetivo es que el ligamento cicatrice y estabilice el hueso:", subsections: [ { title: "Tratamientos", items: ["Protocolo RICE (Reposo, Hielo, Compresión, Elevación) y AINEs orales", "Inmovilización con férulas, muñequeras rígidas o yesos (vital para permitir que el ligamento rasgado se una y sane en la posición correcta durante semanas)", "Rehabilitación y terapia de mano (para recuperar el rango de movimiento tras la inmovilización)", "Cirugía ortopédica (suturar o anclar el ligamento rasgado al hueso) necesaria en roturas de Grado 3 o inestabilidad crónica"] } ], note: "Ignorar un esguince grave en la mano a menudo conduce a dolores crónicos insoportables meses después y a artrosis prematura." }, whenToSeekHelp: { title: "¿Cuándo es urgente consultar?", intro: "Ve a emergencias o visita a un traumatólogo si:", items: ["El dolor es intenso, el dedo/muñeca se ve deformado, doblado o fuera de su lugar natural", "Eres incapaz de agarrar, sostener un bolígrafo o apretar la mano sin dolor extremo", "El dolor y la hinchazón en la muñeca no mejoran notablemente tras 48 horas de reposo y hielo"] } },
'Adenomiosis' : { intro: "La adenomiosis es una afección ginecológica en la que el tejido que normalmente recubre el interior del útero (endometrio) crece hacia la pared muscular profunda del útero (miometrio). A menudo causa un agrandamiento del útero y puede ser sumamente dolorosa.", whatIs: { title: "¿Qué es la Adenomiosis?", text: "Es un trastorno uterino benigno. Al igual que en la menstruación normal, este tejido desplazado dentro del músculo uterino sigue respondiendo a las hormonas; se engrosa, se degrada y sangra con cada ciclo. Esto atrapa sangre en el músculo uterino, inflamándolo y causando calambres severos y sangrados masivos." }, symptoms: { title: "Manifestaciones Clínicas", intro: "Puede ser asintomática, pero usualmente causa:", groups: [ { name: "Síntomas", items: ["Sangrado menstrual extremadamente abundante y prolongado (menorragia)", "Calambres pélvicos agudos y dolorosos similares a cuchillazos (dismenorrea) que empeoran con la edad", "Dolor pélvico crónico o pesadez en el bajo vientre", "Dolor intenso durante las relaciones sexuales (dispareunia)"] } ], warning: "La pérdida masiva de sangre por esta afección frecuentemente provoca anemia severa y fatiga crónica." }, types: { title: "Formas de Crecimiento", intro: "Puede afectar al útero de dos maneras:", items: ["Adenomiosis difusa (el tejido anormal se disemina ampliamente por toda la pared muscular del útero, engrosándolo globalmente)", "Adenomioma focal (el tejido forma un nódulo o tumoración sólida localizada, que a menudo se confunde con un mioma uterino)"], note: "Suele afectar a mujeres entre los 30 y 50 años que ya han tenido hijos." }, causes: { title: "Causas y Factores", intro: "La causa exacta no se conoce con certeza, pero se sospecha de:", items: ["Crecimiento invasivo del tejido (teoría de que cirugías uterinas previas, como cesáreas, rompen la barrera y permiten la invasión)", "Orígenes en el desarrollo embrionario uterino", "Inflamación uterina posparto", "Dependencia estrogénica (crece en presencia de hormonas y desaparece tras la menopausia)"] }, diagnosis: { title: "Evaluación Ginecológica", intro: "Suele diagnosticarse a través de los síntomas e imágenes:", items: ["Examen pélvico físico (el útero se siente agrandado, a veces al doble o triple de su tamaño normal, y a menudo es muy sensible y doloroso al tacto)", "Ecografía transvaginal (para ver el engrosamiento de la pared y descartar pólipos o tumores)", "Resonancia Magnética pélvica (la herramienta más precisa para confirmar el diagnóstico y diferenciarla de los fibromas/miomas)"], note: "El único diagnóstico 100% definitivo ocurre examinando el útero extraído tras una histerectomía." }, treatment: { title: "Manejo Hormonal y Cirugía", intro: "El tratamiento depende de los síntomas y si la paciente desea futuros embarazos:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos antiinflamatorios (AINEs) (para el dolor agudo, tomados días antes de la regla)", "Terapia hormonal (DIU liberador de levonorgestrel como Mirena, píldoras anticonceptivas continuas para detener el sangrado y encoger el tejido, siendo el tratamiento de primera línea muy eficaz)", "Ablación endometrial (destruir el revestimiento interno, aunque no siempre llega al tejido profundo)", "Embolización de arterias uterinas (cortar el flujo de sangre a la adenomiosis)", "Histerectomía (la extirpación total del útero es la única cura definitiva, reservada para síntomas severos refractarios)"] } ], note: "La enfermedad se resuelve y desaparece naturalmente una vez que la mujer atraviesa la menopausia." }, whenToSeekHelp: { title: "¿Cuándo consultar al ginecólogo?", intro: "Es fundamental buscar revisión médica especializada si experimentas:", items: ["Sangrado menstrual tan denso que necesitas usar múltiples toallas sanitarias a la vez o cambiarlas cada hora, y expulsas coágulos de sangre muy grandes", "Calambres menstruales insoportables que te incapacitan y que interfieren totalmente con tu vida laboral o rutinas diarias", "Diagnósticos repetidos de anemia debido a la cantidad de sangre que pierdes mes a mes"] } },
'Venas varicosas' : { intro: "Las venas varicosas (várices) son venas retorcidas, dilatadas e hinchadas que se pueden ver justo debajo de la superficie de la piel. Aunque pueden aparecer en cualquier parte del cuerpo, son sumamente comunes en las piernas y los pies debido a la presión de estar de pie.", whatIs: { title: "¿Qué son las Várices?", text: "Ocurren debido a la insuficiencia venosa. Las venas tienen válvulas unidireccionales que empujan la sangre hacia el corazón en contra de la gravedad. Cuando estas válvulas se debilitan o se dañan, la sangre retrocede y se estanca en las venas inferiores, aumentando la presión, estirándolas y volviéndolas tortuosas, abultadas y de color azul o púrpura." }, symptoms: { title: "Síntomas Físicos", intro: "Además de la alteración estética, causan problemas circulatorios:", groups: [ { name: "Molestias Comunes", items: ["Venas retorcidas y abultadas (a menudo como cordones bajo la piel)", "Sensación de dolor, pesadez sorda y cansancio crónico en las piernas", "Ardor, picazón intensa, calambres musculares y pulsaciones alrededor de las venas", "Hinchazón (edema) de la parte inferior de las piernas o tobillos, peor al final del día"] } ], warning: "A largo plazo, pueden causar cambios en el color de la piel, endurecimiento del tobillo y formación de úlceras venosas abiertas muy difíciles de curar." }, types: { title: "Clasificación de Insuficiencia", intro: "Varían desde pequeñas marcas hasta enfermedad venosa severa:", items: ["Arañas vasculares o telangiectasias (versiones más pequeñas, rojas o azules, similares a una telaraña superficial)", "Várices tronculares (venas gruesas y nudosas que protruyen)", "Insuficiencia Venosa Crónica (cuando las varices causan edema severo permanente y llagas cutáneas)"], note: "El riesgo aumenta fuertemente con la edad, el embarazo, la obesidad y la genética (antecedentes familiares)." }, causes: { title: "Causas y Detonantes", intro: "La debilidad de las válvulas se acelera por presiones constantes:", items: ["Permanecer mucho tiempo de pie o sentado en la misma postura (trabajos sedentarios o estáticos)", "El embarazo (el volumen de sangre aumenta y el feto presiona las venas pélvicas)", "Sobrepeso severo (presión adicional en las piernas)", "Factores hormonales y envejecimiento"] }, diagnosis: { title: "Examen Vascular", intro: "El especialista vascular o flebólogo evalúa el grado de reflujo venoso:", items: ["Examen físico inspeccionando las piernas mientras el paciente está de pie", "Ecografía Doppler venosa (la prueba de oro indispensable; utiliza ultrasonido para observar el flujo sanguíneo y verificar si hay coágulos o válvulas fallando internamente)"], note: "" }, treatment: { title: "Alivio y Procedimientos Curativos", intro: "Si las molestias son intensas o las complicaciones son serias, el tratamiento busca cerrar o quitar la vena defectuosa:", subsections: [ { title: "Tratamientos Mínimamente Invasivos", items: ["Uso estricto de medias de compresión graduada y elevación de las piernas al descansar", "Escleroterapia (inyección de una espuma química en venas pequeñas para cerrarlas y que el cuerpo las reabsorba)", "Ablación endovenosa por láser o radiofrecuencia (se inserta un catéter caliente en la vena grande dañada para sellarla desde adentro)", "Flebectomía ambulatoria (extracción de las varices superficiales a través de pequeños pinchazos en la piel)", "Cirugía de extracción y ligadura de venas (stripping) para casos extremadamente severos"] } ], note: "Cerrar una vena varicosa no daña la circulación, ya que la sangre simplemente toma desvíos por venas sanas y más profundas." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es preciso buscar evaluación médica especializada si:", items: ["Las venas varicosas duelen severamente, dificultan caminar o han empeorado rápidamente", "Se desarrolla una llaga o úlcera en la piel cerca del tobillo", "La piel sobre la variz se vuelve muy roja, caliente, dura o muy sensible (signo de flebitis o trombo superficial)", "Una variz sangra incontrolablemente tras un mínimo roce o golpe (necesita compresión firme y urgencias)"] } },
'Esofagitis' : { intro: "La esofagitis es la inflamación que daña los tejidos del esófago, el tubo muscular que transporta la comida y los líquidos desde la boca hasta el estómago. Es una condición muy dolorosa que dificulta severamente la deglución.", whatIs: { title: "¿Qué es la Esofagitis?", text: "Es la irritación y ulceración del revestimiento interno del esófago. Si no se trata, la inflamación crónica puede causar complicaciones graves, como la formación de cicatrices que estrechan el conducto (estenosis esofágica) e impiden tragar, o daños precancerosos." }, symptoms: { title: "Síntomas Digestivos", intro: "Los signos principales afectan la acción de comer:", groups: [ { name: "Malestares", items: ["Dificultad para tragar (disfagia), con sensación de que la comida se atasca en el pecho", "Dolor intenso al tragar líquidos o sólidos (odinofagia)", "Dolor agudo en el centro del pecho que ocurre detrás del esternón, especialmente al comer", "Acidez estomacal crónica, náuseas y vómitos"] } ], warning: "Si hay impactación de alimentos (la comida se traba y no baja ni sube), es una emergencia médica que requiere endoscopia urgente." }, types: { title: "Causas y Tipos", intro: "Se clasifica por la causa directa de la irritación:", items: ["Esofagitis por reflujo (la más común, causada por el ácido del estómago que retrocede crónicamente en la ERGE)", "Esofagitis eosinofílica (inflamación de tipo alérgico donde se acumulan glóbulos blancos en el esófago, a menudo relacionada con alergias a alimentos)", "Esofagitis inducida por medicamentos (causada por el contacto prolongado de pastillas como el ibuprofeno, doxiciclina o potasio, al tragarlas sin agua suficiente)", "Esofagitis infecciosa (rara en personas sanas, pero grave en inmunodeprimidos; causada por hongos como la cándida o virus como el herpes o citomegalovirus)"], note: "" }, diagnosis: { title: "Endoscopia y Biopsia", intro: "El gastroenterólogo confirmará el tipo de daño y su extensión mediante:", items: ["Endoscopia digestiva alta (el examen clave: un tubo con cámara permite ver la inflamación, úlceras o anillos en el esófago)", "Biopsia esofágica (toma de muestras de tejido durante la endoscopia para analizar infecciones, cáncer o contar los eosinófilos de las alergias)", "Tránsito esofágico con bario (radiografía tomando líquido de contraste para ver el estrechamiento del tubo)"], note: "" }, treatment: { title: "Tratamiento Dirigido", intro: "El manejo está destinado a curar la causa específica y sanar la mucosa:", subsections: [ { title: "Terapéuticas Médicas", items: ["Para el reflujo: Medicamentos que bloquean el ácido (Inhibidores de Bomba de Protones como omeprazol) para permitir la cicatrización", "Para las alergias: Corticosteroides deglutidos y dietas de eliminación estrictas de alérgenos alimentarios (como lácteos, trigo, huevo)", "Para las pastillas: Beber siempre un vaso grande de agua al tomarlas y no acostarse por 30 minutos", "Para infecciones: Medicamentos antimicóticos o antivirales específicos", "Dilatación endoscópica: Procedimiento físico para ensanchar un esófago que se ha cerrado por cicatrices"] } ], note: "Ignorar la esofagitis crónica por ácido puede llevar al Esófago de Barrett, una condición premaligna." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca ayuda médica inmediata si experimentas:", items: ["Dolor en el pecho severo que dura más de un par de minutos (puede confundirse con un infarto)", "Tienes un bocado de comida atascado en el esófago que no puedes tragar ni vomitar", "Dificultad extrema para tragar hasta el punto de que no logras beber líquidos", "Vómitos con sangre o heces fecales que se ven oscuras o alquitranadas"] } },
'Amenorrea primaria' : { intro: "La amenorrea primaria es el término médico para describir la ausencia total y el fracaso de la aparición del primer ciclo menstrual (menarquia) en una adolescente que ya ha alcanzado la edad en la cual la menstruación debería haber comenzado naturalmente.", whatIs: { title: "¿Qué es la Amenorrea Primaria?", text: "Clínicamente se diagnostica cuando una adolescente cumple 15 años y no ha tenido su primera menstruación (incluso si presenta desarrollo normal de los senos y el vello púbico), o a los 13 años si no ha comenzado ningún signo de desarrollo físico de la pubertad." }, symptoms: { title: "Signos Acompañantes", intro: "El síntoma central es la falta de regla, pero suele haber otras señales:", groups: [ { name: "Señales Físicas Relacionadas", items: ["Falta de desarrollo de los senos (telarquia)", "Dolor pélvico o abdominal cíclico mensual sin sangrado visible", "Ausencia de crecimiento acelerado (talla baja)", "Desarrollo anormal de vello facial, acné o voz profunda (signos de andrógenos altos)"] } ], warning: "Si hay dolor abdominal cíclico, puede existir un bloqueo estructural que impide la salida de la sangre menstrual." }, types: { title: "Causas y Orígenes", intro: "Las causas son variadas e incluyen problemas hormonales o defectos de nacimiento anatómicos:", items: ["Anomalías cromosómicas y genéticas (como el Síndrome de Turner, donde los ovarios no se desarrollan correctamente)", "Problemas hipotalámicos o hipofisarios (el cerebro no envía la señal hormonal adecuada para iniciar el ciclo, a menudo por estrés extremo, trastornos alimentarios graves, bajo peso corporal o exceso de atletismo de alto rendimiento)", "Fallo ovárico prematuro", "Malformaciones anatómicas del tracto reproductivo (útero ausente, himen imperforado o tabique vaginal transverso que no deja salir el flujo)"], note: "" }, diagnosis: { title: "Evaluación Ginecológica y Endocrina", intro: "Es fundamental realizar un estudio completo para hallar la raíz del retraso:", items: ["Examen físico para evaluar el nivel del desarrollo de los caracteres sexuales secundarios (Escala de Tanner) y descartar anomalías genitales", "Análisis de sangre para medir un panel hormonal exhaustivo (FSH, LH, Prolactina, TSH, hormonas tiroideas)", "Ecografía pélvica o RM (para confirmar visualmente la presencia y estructura normal del útero, los ovarios y el canal vaginal)", "Análisis genético (cariotipo) si se sospecha de un síndrome cromosómico"], note: "" }, treatment: { title: "Terapia Hormonal y Quirúrgica", intro: "El tratamiento es altamente específico a la causa encontrada:", subsections: [ { title: "Opciones de Corrección", items: ["Terapias de reemplazo hormonal (administración de estrógenos y progesterona para inducir la pubertad, proteger los huesos y provocar ciclos menstruales si hay fallo ovárico)", "Tratamiento de la causa subyacente (modificación de dieta, aumento de peso y reducción de ejercicio en casos de atletas o anorexia para restablecer el ciclo natural)", "Cirugía ginecológica correctiva (procedimiento quirúrgico menor para abrir un himen imperforado o corregir bloqueos anatómicos vaginales)", "Asesoría especializada sobre fertilidad futura (en casos de ausencia de útero u ovarios)"] } ], note: "El abordaje psicológico es muy importante dada la ansiedad que esta condición causa en las adolescentes." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra o ginecólogo?", intro: "Es obligatorio agendar una evaluación médica especializada si una joven:", items: ["Llega a los 15 años y no ha tenido su primer período menstrual, independientemente del resto de su desarrollo físico", "Llega a los 13 años y no presenta ningún crecimiento de los senos", "Pasan más de tres años entre el inicio del crecimiento de los senos y la llegada del primer periodo"] } },
'Ojo rojo' : { intro: "El 'ojo rojo' es un signo clínico universal y extremadamente común que ocurre cuando los diminutos vasos sanguíneos que se encuentran en la superficie del ojo se expanden (dilatan), inyectándose de sangre. Suele ser causado por irritaciones leves, pero también puede ser señal de una enfermedad ocular amenazante.", whatIs: { title: "¿Qué es el Ojo Rojo?", text: "Es la hiperemia (aumento de sangre) de la conjuntiva o de los vasos esclerales profundos. Puede afectar a uno o ambos ojos, y su presentación va desde un color rosado leve hasta un rojo sangre intenso, pudiendo acompañarse de dolor, picazón o secreción según su causa." }, symptoms: { title: "Síntomas Acompañantes Importantes", intro: "El enrojecimiento puede ir acompañado de:", groups: [ { name: "Signos Clínicos", items: ["Secreción acuosa, mucosa o purulenta (legañas verdes/amarillas)", "Sensación de arenilla, ardor o picor intenso", "Dolor ocular agudo y profundo, sensibilidad a la luz (fotofobia)", "Visión borrosa o halos alrededor de las luces"] } ], warning: "Un ojo rojo indoloro suele ser inofensivo; un ojo rojo con dolor severo y pérdida de visión es una emergencia oftalmológica." }, types: { title: "Causas Principales", intro: "Los orígenes van desde lo trivial hasta lo peligroso:", items: ["Causas comunes no graves: Conjuntivitis viral, bacteriana o alérgica ('ojo rosa'), fatiga visual por pantallas, ojo seco, irritantes ambientales, humo o hemorragia subconjuntival (vaso roto sin dolor)", "Causas urgentes y graves: Úlcera o infección corneal (queratitis, a menudo por uso de lentes de contacto), Glaucoma agudo de ángulo cerrado, Uveítis o escleritis, y traumas oculares penetrantes"], note: "" }, diagnosis: { title: "Evaluación Oftalmológica", intro: "El especialista determinará la gravedad buscando 'banderas rojas':", items: ["Examen visual directo con Lámpara de Hendidura (microscopio ocular) para evaluar la córnea y la cámara anterior", "Tinción con gotas de fluoresceína y luz azul (para iluminar y detectar úlceras o arañazos dolorosos en la córnea)", "Medición de la presión intraocular con un tonómetro (vital para descartar glaucoma agudo)", "Revisión de las pupilas y respuesta a la luz"], note: "" }, treatment: { title: "Alivio y Tratamiento Dirigido", intro: "Nunca se debe automedicar un ojo rojo doloroso; el tratamiento depende de la causa:", subsections: [ { title: "Opciones Terapéuticas", items: ["Uso de lágrimas artificiales y compresas frías (para el ojo seco, alergias e irritaciones simples)", "Colirios con antibióticos o antivirales (para infecciones confirmadas)", "Colirios antihistamínicos (para el picor alérgico)", "Corticosteroides en gotas (para desinflamación severa como la uveítis, recetados solo y exclusivamente por oftalmólogos)", "Tratamiento de urgencia para el Glaucoma (medicamentos inmediatos por vía oral y gotas para bajar la presión del ojo)"] } ], note: "Evita usar gotas 'blanqueadoras' comerciales (descongestionantes) de uso prolongado, ya que causan efecto rebote y empeoran el enrojecimiento crónico." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia y debes ir a urgencias?", intro: "Acude a un oftalmólogo o al hospital el mismo día de manera urgente si tu ojo rojo se acompaña de:", items: ["Pérdida de visión repentina, visión borrosa significativa o si ves halos anillos alrededor de las luces", "Dolor ocular intenso o punzante (no solo irritación o sensación de roce)", "Extrema e insoportable sensibilidad a la luz (fotofobia, duele abrir el ojo en una habitación iluminada)", "Viene acompañado de náuseas o vómitos", "Ocurre directamente después de un golpe traumático en el ojo o la penetración de un producto químico"] } },
'Comportamiento psicótico' : { intro: "El comportamiento psicótico o episodio psicótico es un conjunto grave de síntomas mentales que indican que una persona ha perdido parcial o totalmente el contacto con la realidad. Altera de forma radical cómo el cerebro procesa la información, modificando profundamente la forma de pensar, percibir y actuar.", whatIs: { title: "¿Qué es la Psicosis?", text: "La psicosis no es una enfermedad en sí misma, sino un síndrome clínico o estado mental que se presenta en varios trastornos psiquiátricos, problemas neurológicos o intoxicaciones graves. El cerebro genera experiencias sensoriales y creencias que son completamente reales para el paciente, pero falsas en la realidad externa." }, symptoms: { title: "Síntomas Nucleares", intro: "Los dos síntomas principales que definen un episodio psicótico son:", groups: [ { name: "Distorsiones de Realidad", items: ["Alucinaciones (percepciones falsas y muy reales; como escuchar voces que comentan, ordenan o insultan, ver cosas inexistentes, o sentir tactos imaginarios)", "Delirios (creencias y convicciones falsas, irracionales e inquebrantables, incluso ante pruebas lógicas en contra; ej. creer que se es perseguido, espiado, envenenado o que se tienen poderes divinos)", "Pensamiento desorganizado (habla incoherente, saltos ilógicos de un tema a otro, descarrilamiento de las frases)", "Comportamiento motor anómalo o catatonia (desde agitación extrema hasta inmovilidad rígida como una estatua)"] } ], warning: "La persona en estado psicótico agudo carece por completo de 'introspección': no sabe ni acepta que su mente está enferma." }, types: { title: "Causas Subyacentes Frecuentes", intro: "La psicosis puede ser desencadenada por múltiples condiciones graves:", items: ["Enfermedades psiquiátricas primarias (Esquizofrenia, Trastorno Bipolar en fase maníaca extrema, o Depresión Mayor con características psicóticas)", "Psicosis inducida por sustancias o tóxicos (sobredosis de drogas estimulantes como metanfetaminas, cocaína, LSD, o el síndrome de abstinencia alcohólica severo -Delirium Tremens-)", "Causas orgánicas o médicas (infecciones cerebrales, tumores, Alzheimer, deficiencia severa de vitamina B12, o fiebres extremas)"], note: "El estrés emocional o trauma masivo (como en el Trastorno por Estrés Postraumático o psicosis posparto) también puede fracturar temporalmente la mente." }, diagnosis: { title: "Evaluación Psiquiátrica de Urgencia", intro: "Requiere una valoración clínica exhaustiva para hallar la causa:", items: ["Entrevista psiquiátrica clínica, si el paciente puede comunicarse, o con la ayuda de familiares para el historial de síntomas", "Análisis toxicológico de orina y sangre (para descartar drogas ilícitas o medicinas)", "Pruebas de imagen neurológica (RM o TC cerebral) para asegurar que un tumor o lesión neurológica no esté causando el delirio", "Análisis de líquido cefalorraquídeo si se sospecha encefalitis o infecciones en el cerebro"], note: "" }, treatment: { title: "Estabilización y Medicación", intro: "El tratamiento agudo busca calmar el cerebro y proteger al paciente:", subsections: [ { title: "Intervenciones Críticas", items: ["Administración de Antipsicóticos (medicamentos de primera línea inyectables u orales para estabilizar los químicos cerebrales, como la dopamina, y detener las alucinaciones/delirios)", "Hospitalización psiquiátrica inmediata (frecuentemente involuntaria) para garantizar la seguridad del paciente mientras los medicamentos hacen efecto", "Tratamiento de la causa raíz médica o desintoxicación total (si es inducida por drogas)", "Terapia psicológica a largo plazo y psicoeducación familiar tras superar la crisis aguda para evitar recaídas"] } ], note: "Sin tratamiento rápido, la psicosis aguda puede llevar a comportamientos extremadamente peligrosos y trágicos." }, whenToSeekHelp: { title: "¿Cuándo solicitar asistencia de emergencia?", intro: "Una crisis psicótica es una URGENCIA PSiquiátrica extrema. Llama a los servicios de emergencia o protección civil de inmediato si alguien:", items: ["Habla y responde abiertamente a 'voces' o personas invisibles", "Manifiesta paranoias extremas (ej. bloquea puertas, cree que la comida está envenenada, que lo persiguen organizaciones secretas)", "Actúa con agitación descontrolada, agresividad inusual o confusión profunda e incomprensible", "Muestra intenciones, planes o expresa que las 'voces' le ordenan hacerse daño a sí mismo o matar/lastimar a otras personas"] } },
'Síndrome de caídas' : { intro: "El síndrome de caídas es una de las grandes problemáticas y síndromes geriátricos (junto a la demencia o incontinencia) que afecta la calidad de vida en la tercera edad. Se caracteriza por la propensión o ocurrencia de caídas repetitivas, involuntarias y frecuentes en adultos mayores.", whatIs: { title: "¿Qué es el Síndrome de Caídas?", text: "No es un simple accidente fortuito; es un marcador clínico de fragilidad que indica un deterioro del control del equilibrio, la marcha o el estado de salud general. Sus consecuencias son devastadoras, siendo la principal causa de fracturas de cadera, pérdida de independencia, ingreso en residencias y letalidad por traumatismos cráneo-encefálicos en ancianos." }, types: { title: "Causas Multifactoriales", intro: "Las caídas en ancianos casi siempre resultan de una suma de factores combinados:", items: ["Factores extrínsecos o ambientales (el entorno: alfombras sueltas, mala iluminación, ausencia de barras de sujeción en baños, calzado inadecuado, escalones rotos)", "Factores intrínsecos médicos (arritmias cardíacas que causan síncope, Parkinson, hipotensión ortostática al levantarse rápido, debilidad muscular grave, problemas de visión no corregidos, cataratas o vértigo)", "Factores iatrogénicos o medicamentosos (la causa evitable más importante: uso de polifarmacia, especialmente sedantes, pastillas para dormir, benzodiacepinas, antidepresivos y antihipertensivos fuertes que causan mareos letargos)"], note: "El 'Síndrome Post-Caída' (el miedo paralizante extremo a volver a caer) hace que el anciano deje de caminar, atrofiando aún más sus músculos y garantizando una nueva caída fatal." }, diagnosis: { title: "Evaluación Geriátrica Integral", intro: "Un anciano que se cae debe ser evaluado por un médico geriatra para hallar el origen:", items: ["Revisión estricta y eliminación de toda la lista de medicamentos prescritos", "Prueba funcional de 'Levántate y Anda' (Timed Up and Go) para medir el equilibrio dinámico, la fuerza y la velocidad de marcha de la persona al levantarse de una silla", "Evaluación neurológica, examen de la agudeza visual y cardiovascular (electrocardiograma para descartar arritmias silenciosas que causen desmayos repentinos)", "Evaluación del estado cognitivo (las personas con demencia sufren muchísimas más caídas)"], note: "" }, treatment: { title: "Prevención, Fisioterapia y Entorno", intro: "El tratamiento busca erradicar los riesgos y empoderar físicamente al mayor:", subsections: [ { title: "Estrategias de Intervención", items: ["Modificación urgente de la medicación (suspender pastillas sedantes o reducir drásticamente las dosis de antihipertensivos bajo supervisión médica)", "Fisioterapia intensiva de fortalecimiento muscular y entrenamiento del equilibrio (como Tai Chi, esencial para recuperar los reflejos que evitan caer al tropezar)", "Adaptación arquitectónica de la vivienda (quitar alfombras, iluminar pasillos con sensores, instalar barras agarraderas en la bañera y el inodoro)", "Prescripción de ayudas técnicas adecuadas (andadores o bastones correctamente calibrados) y corrección de la visión (operar cataratas)"] } ], note: "Las sujeciones físicas nunca son la solución; empeoran la debilidad y causan estrangulamientos." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico geriatra o a urgencias?", intro: "Es preciso intervenir médicamente y buscar ayuda profesional si:", items: ["El adulto mayor sufre dos o más caídas en un periodo de 6 a 12 meses, incluso si no se lesiona físicamente", "La caída fue provocada por una pérdida de conocimiento repentina, un desmayo o mareo fuerte antes de golpear el suelo", "Tras la caída existe un dolor intenso e incapacitante en cadera o espalda (riesgo de fractura), o un golpe fuerte en la cabeza con somnolencia posterior", "La persona anciana empieza a arrastrar los pies repentinamente, se agarra a todos los muebles por miedo extremo a caer y rechaza salir de casa"] } },
'Parálisis cerebral' : { intro: "La parálisis cerebral es un grupo de trastornos que causan problemas del movimiento, el equilibrio y la postura, siendo la discapacidad motora más frecuente en la infancia.", whatIs: { title: "¿Qué es la Parálisis Cerebral?", text: "Es un daño o desarrollo anormal en las partes del cerebro que controlan el movimiento muscular, ocurriendo generalmente antes de nacer, durante el parto o en los primeros años de vida." }, types: { title: "Tipos de Parálisis", intro: "Se clasifica según el trastorno motor predominante:", items: ["Espástica (la más común, músculos rígidos)", "Discinética (movimientos incontrolables o retorcidos)", "Atáxica (problemas de equilibrio y coordinación)", "Mixta (combinación de síntomas)"], note: "No empeora con el tiempo, pero los síntomas pueden cambiar." }, diagnosis: { title: "Evaluación Neurológica", intro: "Se diagnostica observando el desarrollo del niño:", items: ["Examen físico y neurológico (retrasos motores)", "Resonancia Magnética (RM) del cerebro (para identificar lesiones)", "Electroencefalograma (EEG) si hay convulsiones asociadas"], note: "Puede tardar meses o años en diagnosticarse definitivamente." }, treatment: { title: "Manejo y Terapias", intro: "No tiene cura, pero la intervención temprana mejora la calidad de vida:", subsections: [ { title: "Opciones de Tratamiento", items: ["Fisioterapia y terapia ocupacional", "Terapia del habla y lenguaje", "Medicamentos relajantes musculares (como baclofeno o inyecciones de bótox)", "Cirugía ortopédica (para alargar músculos o corregir deformidades)"] } ], note: "Requiere un equipo multidisciplinario continuo." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Es fundamental buscar evaluación si el bebé:", items: ["Es incapaz de sostener la cabeza o no se da la vuelta a la edad esperada", "Siente los músculos muy rígidos o, por el contrario, muy flácidos", "No se sienta, gatea o camina en los hitos de desarrollo normales"] } },
'Síndrome nefrótico' : { intro: "El síndrome nefrótico es un trastorno renal que hace que el cuerpo excrete demasiada proteína en la orina. A menudo produce hinchazón en varias partes del cuerpo y requiere tratamiento especializado.", whatIs: { title: "¿Qué es el Síndrome Nefrótico?", text: "Se produce por daños en los diminutos vasos sanguíneos (glomérulos) de los riñones que filtran los desechos. Al dañarse, permiten que proteínas vitales de la sangre, como la albúmina, se filtren y se pierdan en la orina." }, types: { title: "Causas y Tipos", intro: "Puede ser primario o secundario a otra enfermedad:", items: ["Enfermedad de cambios mínimos (la causa más común en niños)", "Glomeruloesclerosis focal y segmentaria (tejido cicatricial en los glomérulos)", "Nefropatía membranosa (engrosamiento de la membrana)", "Secundario a enfermedades sistémicas (como diabetes o lupus)"], note: "Aumenta el riesgo de infecciones y de formación de coágulos sanguíneos." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico requiere pruebas de laboratorio:", items: ["Análisis de orina (para medir la cantidad masiva de proteínas)", "Análisis de sangre (para verificar niveles bajos de albúmina y altos de colesterol)", "Biopsia de riñón (esencial en adultos para determinar la causa exacta)"], note: "" }, treatment: { title: "Tratamiento y Control", intro: "El objetivo es tratar la causa subyacente y controlar los síntomas:", subsections: [ { title: "Intervenciones", items: ["Medicamentos para la presión arterial (Inhibidores de la ECA o ARA-II para proteger los riñones)", "Diuréticos (para ayudar a eliminar la retención de líquidos severa)", "Medicamentos inmunosupresores o corticosteroides (para reducir la inflamación autoinmune)", "Anticoagulantes (si hay riesgo de trombos) y dieta baja en sal"] } ], note: "El control del colesterol también es necesario mediante estatinas." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Solicita atención médica si presentas:", items: ["Hinchazón severa (edema), particularmente alrededor de los ojos y en los tobillos o pies", "Orina espumosa o con burbujas excesivas (signo de proteína)", "Aumento de peso inexplicable debido a la retención de líquidos extrema", "Fatiga severa o pérdida de apetito"] } },
'Dislalia' : { intro: "La dislalia es un trastorno en la articulación de los fonemas, por el cual el niño tiene problemas para pronunciar correctamente ciertos sonidos o grupos de sonidos, ya sea por omisión, sustitución o distorsión.", whatIs: { title: "¿Qué es la Dislalia?", text: "Es una alteración del lenguaje muy común en la infancia. El niño no tiene ninguna alteración del sistema nervioso central ni problemas auditivos, pero presenta dificultad física para colocar los órganos articulatorios (lengua, labios) en la posición correcta." }, types: { title: "Clasificación Logopédica", intro: "Existen varios tipos según su origen:", items: ["Dislalia evolutiva o fisiológica (fase normal del desarrollo del lenguaje que desaparece sola)", "Dislalia funcional (mal funcionamiento de los órganos articulatorios sin causa orgánica)", "Dislalia audiógena (causada por deficiencia auditiva; si el niño no oye bien, no pronuncia bien)", "Dislalia orgánica o disglosia (causada por malformaciones físicas, como labio leporino o frenillo lingual corto)"], note: "Es el trastorno del habla más común en los niños en edad preescolar." }, diagnosis: { title: "Evaluación Fonoaudiológica", intro: "El logopeda o fonoaudiólogo diagnosticará el problema mediante:", items: ["Evaluación de la articulación (se le pide al niño que repita palabras o nombre imágenes)", "Examen anatómico de la boca, lengua, labios y paladar", "Prueba de audición (audiometría) para descartar sordera leve"], note: "" }, treatment: { title: "Terapia y Reeducación", intro: "Con el tratamiento adecuado, el pronóstico es excelente:", subsections: [ { title: "Estrategias de Intervención", items: ["Terapia del lenguaje con un logopeda (ejercicios de repetición y posicionamiento de la lengua)", "Ejercicios de gimnasia bucofacial (para fortalecer labios y lengua)", "Ejercicios de respiración y soplo", "Intervención quirúrgica (solo si existe una barrera física, como cortar un frenillo lingual corto)"] } ], note: "La participación de los padres y el apoyo en casa sin presionar al niño es vital." }, whenToSeekHelp: { title: "¿Cuándo consultar a un especialista?", intro: "Es recomendable visitar a un logopeda si:", items: ["Un niño mayor de 4 años tiene un habla ininteligible para personas fuera de su entorno familiar", "Omite o sustituye sonidos constantemente (por ejemplo, dice 'tasa' en lugar de 'casa')", "Muestra frustración o se niega a hablar porque no le entienden", "Sospechas que el niño tiene problemas auditivos frecuentes por otitis"] } },
'Linfoma de Hodgkin' : { intro: "El linfoma de Hodgkin es un tipo de cáncer del sistema linfático, que es parte del sistema inmunológico del cuerpo. Puede afectar a personas de cualquier edad, pero es más común en adultos jóvenes (entre 20 y 40 años) y en mayores de 55 años.", whatIs: { title: "¿Qué es el Linfoma de Hodgkin?", text: "Es el crecimiento maligno de un tipo específico de glóbulo blanco llamado linfocito. Estas células anormales (llamadas células de Reed-Sternberg) se acumulan en los ganglios linfáticos, haciendo que se hinchen y comprometiendo la capacidad del cuerpo para combatir infecciones." }, types: { title: "Tipos de Linfoma de Hodgkin", intro: "Se divide según la apariencia de las células bajo el microscopio:", items: ["Linfoma de Hodgkin clásico (la forma más común; incluye esclerosis nodular, celularidad mixta, depleción linfocítica y rico en linfocitos)", "Linfoma de Hodgkin con predominio linfocítico nodular (una variante más rara que crece muy lentamente y tiene tratamientos diferentes)"], note: "Es uno de los tipos de cáncer más tratables y curables, con altas tasas de supervivencia." }, diagnosis: { title: "Diagnóstico y Estadificación", intro: "Las pruebas para detectarlo incluyen:", items: ["Biopsia de ganglio linfático (es la única prueba que confirma el diagnóstico al encontrar las células de Reed-Sternberg)", "Examen físico para palpar ganglios inflamados en cuello, axilas o ingle", "Tomografía por emisión de positrones (PET) y TC (para estadificar la enfermedad y ver si se ha diseminado a otros ganglios u órganos)", "Análisis de sangre y, raramente, biopsia de médula ósea"], note: "" }, treatment: { title: "Oncología y Quimioterapia", intro: "El tratamiento se enfoca en destruir las células malignas y lograr la remisión:", subsections: [ { title: "Opciones de Tratamiento", items: ["Quimioterapia (el tratamiento principal, generalmente una combinación de fármacos administrados por vía intravenosa)", "Radioterapia (a menudo se usa después de la quimioterapia para atacar ganglios específicos afectados)", "Inmunoterapia (medicamentos que estimulan el sistema inmunológico, como nivolumab o pembrolizumab, para casos recurrentes)", "Trasplante de células madre (médula ósea) en caso de que el cáncer reaparezca tras los tratamientos iniciales"] } ], note: "Es vital un seguimiento oncológico a largo plazo, ya que los tratamientos pueden tener efectos secundarios años después." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Debes buscar evaluación médica si presentas:", items: ["Hinchazón o bultos indoloros persistentes en los ganglios linfáticos del cuello, axilas o ingles", "Fiebre persistente inexplicable o sudores nocturnos intensos que empapan la ropa", "Pérdida de peso rápida y sin causa aparente (más del 10% del peso corporal)", "Picazón intensa y generalizada en todo el cuerpo, o dolor en los ganglios tras beber alcohol"] } },
'Infección aguda del oído' : { intro: "La infección aguda del oído, conocida médicamente como otitis media aguda, es una dolorosa infección del oído medio (el espacio lleno de aire detrás del tímpano). Es sumamente frecuente en lactantes y niños pequeños.", whatIs: { title: "¿Qué es una Infección Aguda del Oído?", text: "Ocurre cuando una bacteria o un virus infecta el líquido acumulado en el oído medio, provocando que se forme pus y haya presión contra el tímpano. Usualmente, es la complicación de un resfriado, alergia o infección respiratoria que bloquea la trompa de Eustaquio." }, types: { title: "Condiciones Relacionadas", intro: "El oído medio puede presentar variaciones clínicas:", items: ["Otitis media aguda (infección activa, rápida, con dolor severo y fiebre)", "Otitis media con derrame (el líquido se queda atrapado en el oído medio sin infección bacteriana, a menudo después de que la fase aguda ha pasado)", "Otitis media crónica con derrame (el líquido permanece durante meses, afectando la audición)"], note: "En niños pequeños, como no pueden expresar el dolor, a menudo se tiran de las orejas y lloran intensamente." }, diagnosis: { title: "Examen Pediátrico", intro: "El médico diagnosticará la infección visualmente:", items: ["Otoscopia (el médico usa un otoscopio para mirar el tímpano, buscando enrojecimiento, abultamiento o pus)", "Timpanometría (un dispositivo sella el canal y mide cómo se mueve el tímpano en respuesta a cambios de presión del aire)"], note: "" }, treatment: { title: "Manejo y Antibióticos", intro: "Muchas infecciones desaparecen solas, por lo que el enfoque es prudente:", subsections: [ { title: "Intervenciones", items: ["Analgésicos (ibuprofeno o paracetamol para reducir el dolor intenso y la fiebre)", "Vigilancia sin antibióticos (en niños sanos de ciertas edades, los médicos esperan 48 horas para ver si el cuerpo combate la infección viral)", "Antibióticos orales (amoxicilina es el tratamiento de elección si la infección es grave, en ambos oídos o en bebés menores de 6 meses)", "Tubos de timpanostomía (cirugía menor para insertar pequeños tubos en los tímpanos que drenan el líquido, usada para infecciones crónicas y repetitivas)"] } ], note: "Las gotas óticas no deben usarse si existe sospecha de que el tímpano está perforado." }, whenToSeekHelp: { title: "¿Cuándo buscar atención médica?", intro: "Llama a tu médico o pediatra si:", items: ["El dolor de oído es severo y aparece repentinamente, o dura más de un día", "Se observa supuración de líquido, pus o sangre que sale del oído", "El niño está letárgico, irritable en extremo o tiene fiebre alta", "Existen signos de pérdida auditiva (no responde a sonidos de bajo volumen)"] } },
'Adenoides agrandadas' : { intro: "Las adenoides son pequeños parches de tejido linfático ubicados en la parte posterior del conducto nasal. Al igual que las amígdalas, ayudan a atrapar gérmenes en los niños, pero cuando las adenoides se agrandan, pueden causar graves problemas respiratorios.", whatIs: { title: "¿Qué son las Adenoides Agrandadas?", text: "Es la hipertrofia o inflamación crónica de las glándulas adenoides. A menudo se agrandan en los niños al combatir infecciones o alergias. Si se vuelven demasiado grandes, bloquean las vías respiratorias superiores y las trompas de Eustaquio que conectan con los oídos." }, types: { title: "Complicaciones Secundarias", intro: "Su hipertrofia puede detonar otros síndromes:", items: ["Respiración bucal crónica (que a largo plazo puede alterar la forma del rostro y la mordida del niño)", "Apnea obstructiva del sueño infantil (pausas en la respiración al dormir)", "Otitis media recurrente (infecciones de oído constantes por bloqueo del drenaje normal)"], note: "Las adenoides son grandes en la niñez, pero naturalmente se encogen y desaparecen en la adolescencia y edad adulta." }, diagnosis: { title: "Evaluación Médica", intro: "El otorrinolaringólogo o pediatra realizará:", items: ["Examen físico y evaluación del historial de ronquidos o infecciones del niño", "Endoscopia nasal (usando un pequeño tubo con cámara flexible por la nariz para ver directamente el tamaño de las adenoides, ya que no se ven por la boca)", "Radiografía lateral de cráneo o cuello (puede mostrar el estrechamiento de las vías respiratorias)"], note: "" }, treatment: { title: "Tratamiento Médico o Quirúrgico", intro: "Dependerá de cuán graves sean los síntomas obstructivos:", subsections: [ { title: "Opciones Terapéuticas", items: ["Corticosteroides nasales en aerosol (ayudan a desinflamar y encoger temporalmente el tejido adenoideo)", "Antibióticos (si el agrandamiento se debe a una infección bacteriana activa)", "Adenoidectomía (cirugía ambulatoria muy común para extirpar las adenoides, frecuentemente realizada junto a la extracción de amígdalas o colocación de tubos en los oídos)"] } ], note: "La recuperación de la cirugía suele ser rápida (unos pocos días) y mejora radicalmente la calidad del sueño." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental la revisión pediátrica si tu hijo:", items: ["Respira crónicamente por la boca durante el día, teniendo la nariz tapada sin estar resfriado", "Ronca muy fuerte, jadea o hace pausas en la respiración mientras duerme (signos de apnea)", "Sufre de infecciones de oído de manera constante (otitis recurrente)", "Tiene una voz gangosa ('nasal') persistente"] } },
'Cerumen (cera del oído)' : { intro: "El cerumen, o cera del oído, es una sustancia natural y saludable que el cuerpo produce para proteger, limpiar y lubricar el conducto auditivo. Sin embargo, cuando se acumula en exceso y se endurece, puede bloquear el oído y causar pérdida de audición.", whatIs: { title: "¿Qué es el Taponamiento por Cerumen?", text: "Ocurre cuando las glándulas producen más cera de la que puede eliminarse naturalmente, o cuando la cera se empuja profundamente hacia el interior (típicamente por el uso de hisopos de algodón), creando un tapón sólido contra el tímpano que bloquea las ondas sonoras." }, types: { title: "Tipos de Acumulación", intro: "La cera varía de persona a persona:", items: ["Impactación blanda (cera amarilla y pegajosa, fácil de irrigar)", "Impactación dura u oscura (cera seca, muy oxidada, que requiere gotas para ablandarse antes de extraerse)", "Cerumen genético (algunas personas producen cerumen húmedo, otras cerumen seco y escamoso)"], note: "El uso constante de audífonos o tapones para los oídos favorece la impactación de la cera." }, diagnosis: { title: "Diagnóstico Otoscópico", intro: "Es un diagnóstico muy rápido en consulta:", items: ["El médico, enfermera o especialista revisa el conducto auditivo con un otoscopio provisto de luz", "El examen confirmará si la pérdida auditiva se debe a un tapón marrón/negro que bloquea el tímpano o a otro problema subyacente"], note: "" }, treatment: { title: "Limpieza y Extracción", intro: "El tapón debe retirarse cuidadosamente sin dañar el tímpano:", subsections: [ { title: "Procedimientos Seguros", items: ["Gotas para ablandar el cerumen (de venta libre con peróxido de hidrógeno, aceite de bebé o glicerina aplicadas en casa)", "Irrigación del oído (el médico usa una jeringa para lanzar un chorro de agua tibia a presión que enjuaga la cera hacia afuera)", "Extracción manual (el otorrinolaringólogo usa curetas minúsculas especiales o un dispositivo de succión/aspiración bajo visión microscópica)"] } ], note: "NUNCA debes intentar usar velas para los oídos ('ear candling') ni hisopos para sacar tapones, ya que causan daños, quemaduras y empujan la cera más adentro." }, whenToSeekHelp: { title: "¿Cuándo solicitar asistencia médica?", intro: "Acude a un centro de salud si tienes:", items: ["Pérdida de audición repentina o parcial en un oído, o sensación de tener el oído completamente tapado", "Zumbidos, pitidos o ruidos internos en el oído (tinnitus)", "Dolor de oído o sensación de presión insoportable", "Mareos, vértigo, o tos crónica que no se explica por otra causa (un tapón puede estimular el nervio vago en el oído)"] } },
'Tenosinovitis' : { intro: "La tenosinovitis es la dolorosa inflamación de la vaina sinovial (el tejido lleno de líquido protector) que envuelve a un tendón. Provoca dolor agudo e hinchazón al mover la articulación afectada, impidiendo el deslizamiento suave del tendón.", whatIs: { title: "¿Qué es la Tenosinovitis?", text: "Los tendones están cubiertos por una vaina que secreta líquido sinovial para reducir la fricción. Cuando hay un sobreesfuerzo, lesión o una enfermedad inflamatoria (como artritis), esta vaina se irrita, se hincha y atrapa al tendón, dificultando gravemente su movimiento." }, types: { title: "Formas Clínicas Específicas", intro: "Las presentaciones más conocidas toman nombres propios:", items: ["Tenosinovitis de De Quervain (afecta los tendones del pulgar en la muñeca, causa dolor intenso al agarrar objetos)", "Dedo en gatillo o tenosinovitis estenosante (el tendón del dedo se atasca y el dedo se queda doblado, saltando como un resorte al enderezarlo)", "Tenosinovitis infecciosa (una emergencia donde bacterias infectan la vaina, a menudo tras un pinchazo o mordedura en la mano)"], note: "Es una enfermedad ocupacional muy común en personas que realizan movimientos repetitivos con las manos y muñecas." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico clínico es muy característico:", items: ["Examen físico palpando el tendón buscando dolor, hinchazón o crujidos (crepitación) al movimiento", "Maniobra de Finkelstein (específica para De Quervain: flexionar el pulgar hacia la palma y desviar la muñeca, lo cual provoca dolor agudo)", "Ecografía musculoesquelética o RM (para visualizar el engrosamiento del tendón y el líquido acumulado en la vaina)"], note: "" }, treatment: { title: "Desinflamación y Rehabilitación", intro: "Se requiere reducir la inflamación para liberar el tendón atrapado:", subsections: [ { title: "Opciones de Tratamiento", items: ["Reposo absoluto de la zona e inmovilización con férula (muy efectivo en etapas iniciales)", "Antiinflamatorios (AINEs) orales o en gel", "Inyecciones de corticosteroides locales (a menudo el tratamiento de elección y el más rápido para detener la inflamación en De Quervain o dedo en gatillo)", "Fisioterapia y ejercicios de estiramiento suave", "Cirugía de liberación tendinosa (si los síntomas persisten o son crónicos, se realiza un corte en la vaina para que el tendón vuelva a deslizarse)"] } ], note: "La tenosinovitis infecciosa requiere hospitalización, cirugía de lavado de urgencia y antibióticos intravenosos para evitar la destrucción del tendón." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental solicitar atención si:", items: ["Sientes dolor intenso al mover un dedo, la muñeca o el tobillo, y te resulta imposible hacer tu trabajo habitual", "Aparece un bulto rojo, doloroso y muy caliente en el trayecto de un tendón (sospecha de infección aguda)", "Uno de tus dedos se queda 'trabado' en posición doblada y duele al intentar enderezarlo"] } },
'Enfermedad inflamatoria intestinal' : { intro: "La Enfermedad Inflamatoria Intestinal (EII) es un término general que describe trastornos que implican inflamación crónica, destructiva y prolongada de los tejidos del tracto digestivo. Es una enfermedad inmunológica de por vida.", whatIs: { title: "¿Qué es la EII?", text: "Es una afección autoinmune en la que el sistema de defensas del cuerpo ataca por error a la mucosa que recubre el estómago o el intestino. Esta inflamación perpetua causa úlceras profundas, sangrado, diarrea incesante y dolor abdominal debilitante." }, types: { title: "Los Dos Tipos Principales", intro: "Existen dos condiciones médicas primarias bajo este término:", items: ["Enfermedad de Crohn (puede afectar cualquier parte del tracto digestivo, desde la boca hasta el ano; la inflamación a menudo es profunda y salta secciones sanas del intestino)", "Colitis Ulcerosa (afecta exclusivamente el revestimiento superficial del intestino grueso o colon y el recto; la inflamación es continua y sin parches sanos)"], note: "No se debe confundir con el Síndrome del Intestino Irritable (SII), que es un problema funcional y no causa inflamación ni úlceras." }, diagnosis: { title: "Evaluación Digestiva Exhaustiva", intro: "El diagnóstico requiere pruebas invasivas y confirmación histológica:", items: ["Colonoscopia con biopsias múltiples (es la herramienta definitiva; permite visualizar el daño ulceroso y analizar el tejido)", "Análisis de heces (para medir la 'calprotectina fecal', un marcador muy preciso de inflamación intestinal, y descartar infecciones)", "Enteroresonancia o Entero-TC (escáneres de imagen con contraste para evaluar el intestino delgado, donde la colonoscopia no llega, buscando fístulas o estrechamientos)"], note: "" }, treatment: { title: "Supresión Inmune y Cirugía", intro: "No tiene cura. El objetivo es alcanzar y mantener la remisión profunda (detener la inflamación):", subsections: [ { title: "Arsenal Terapéutico", items: ["Medicamentos antiinflamatorios (aminosalicilatos o corticosteroides para frenar brotes agudos rápidamente)", "Inmunosupresores y Terapias Biológicas (como Infliximab o Adalimumab, que son el estándar moderno para modificar la enfermedad bloqueando proteínas del sistema inmune)", "Modificaciones nutricionales rigurosas y vitaminas (especialmente hierro y B12, debido a la malabsorción y anemia)", "Cirugía mayor (resección de intestinos gravemente dañados, eliminación de fístulas, o extirpación completa del colon -colectomía- en casos severos)"] } ], note: "Vivir con EII aumenta el riesgo de desarrollar cáncer de colon, requiriendo colonoscopias preventivas anuales." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico o urgencias?", intro: "Los brotes pueden ser peligrosos. Busca atención rápida si experimentas:", items: ["Diarrea persistente durante semanas o episodios diarios que te incapacitan", "Presencia visible de sangre roja brillante, coágulos o mucosidad abundante en el inodoro", "Dolor y cólicos abdominales severos que no calman, acompañados de fiebre inexplicable", "Pérdida de peso rápida sin hacer dieta, fatiga paralizante extrema y dolores en las articulaciones"] } },
'Melanoma' : { intro: "El melanoma es el tipo de cáncer de piel más grave y letal. Se desarrolla en los melanocitos, las células que producen la melanina (el pigmento que le da color a la piel). Puede formarse en cualquier parte del cuerpo, incluso en ojos o zonas no expuestas al sol.", whatIs: { title: "¿Qué es el Melanoma?", text: "Es un tumor maligno que, a diferencia de otros cánceres de piel, tiene una alta tendencia a propagarse rápidamente (metástasis) a otras partes vitales del cuerpo, como los ganglios linfáticos, el hígado, los pulmones y el cerebro, si no se detecta y extirpa en sus primeras fases." }, types: { title: "Tipos de Crecimiento", intro: "Se dividen principalmente por cómo crecen:", items: ["Melanoma de extensión superficial (el más común, crece horizontalmente sobre la piel antes de penetrar profundo)", "Melanoma nodular (altamente agresivo, crece rápidamente hacia abajo en profundidad como un bulto oscuro)", "Lentigo maligno melanoma (se desarrolla comúnmente en la cara de adultos mayores tras años de daño solar)", "Melanoma lentiginoso acral (aparece en las palmas, plantas de los pies o debajo de las uñas, y es más común en personas de piel oscura)"], note: "Las quemaduras solares graves con ampollas sufridas durante la infancia duplican el riesgo de melanoma en la edad adulta." }, diagnosis: { title: "La Regla ABCDE y Biopsia", intro: "El dermatólogo busca signos visuales de malignidad celular:", items: ["Análisis visual mediante la regla ABCDE: Asimetría, Bordes (irregulares), Color (cambiante o desigual), Diámetro (mayor de 6mm), Evolución (cambia de forma o sangra)", "Dermatoscopia clínica (inspección magnificada especializada del lunar)", "Biopsia por escisión completa (se retira todo el lunar sospechoso y un margen de piel para enviarlo a patología; nunca se debe 'raspar' un melanoma superficialmente)"], note: "La medición de la 'profundidad de Breslow' en la biopsia dictará exactamente la agresividad del cáncer." }, treatment: { title: "Extirpación y Oncología Sistémica", intro: "El tratamiento oncológico varía drásticamente según el estadio de la enfermedad:", subsections: [ { title: "Procedimientos", items: ["Cirugía de escisión amplia (tratamiento principal y definitivo para melanomas en fase inicial 0 o I)", "Biopsia del ganglio linfático centinela (en el momento de la cirugía, para comprobar si el cáncer ha empezado a viajar)", "Inmunoterapia oncológica (Pembrolizumab, Nivolumab, medicamentos revolucionarios que programan tu propio sistema inmune para destruir el cáncer diseminado)", "Terapia dirigida o Targeted therapy (fármacos que atacan específicamente los tumores con mutación genética BRAF)", "Radioterapia o quimioterapia (usadas menos frecuentemente en la actualidad gracias al éxito de la inmunoterapia)"] } ], note: "La detección precoz significa una tasa de curación superior al 99%; el diagnóstico tardío disminuye drásticamente la supervivencia." }, whenToSeekHelp: { title: "¿Cuándo agendar una revisión urgente de un lunar?", intro: "Debes buscar la opinión de un dermatólogo de manera inminente si notas:", items: ["Un lunar nuevo que aparece en la edad adulta, o uno viejo que cambia rápidamente de forma, pica, duele o sangra espontáneamente", "Un lunar negro o muy oscuro que es el 'patito feo' y luce completamente distinto a todos los demás en tu cuerpo", "Una mancha oscura, raya o banda de color marrón/negro que aparece debajo de la uña de tus manos o pies (sin haberte golpeado)"] } },
'Nódulo tiroideo' : { intro: "Un nódulo tiroideo es un crecimiento anormal, bulto o masa (sólida o llena de líquido) que se forma dentro de la glándula tiroides, ubicada en la base del cuello. Son sumamente comunes y, afortunadamente, más del 90% de ellos son completamente benignos (no cancerosos).", whatIs: { title: "¿Qué es un Nódulo Tiroideo?", text: "Es una pequeña tumefacción en el tejido de la tiroides. La mayoría de las veces no causan síntomas ni alteran la función de la glándula, y a menudo se descubren por accidente durante pruebas médicas de imagen para el cuello por otras razones (hallazgo incidental)." }, types: { title: "Tipos de Masas", intro: "Existen múltiples razones para su formación:", items: ["Nódulos coloides (los más comunes, crecimientos benignos de tejido tiroideo normal)", "Quistes tiroideos (cavidades llenas de líquido o sangre, casi siempre inofensivos)", "Nódulos hiperfuncionantes o autónomos ('nódulos calientes' que producen exceso de hormonas sin control, causando hipertiroidismo)", "Cáncer de tiroides (menos del 10% de los nódulos son malignos, suelen ser tumores duros y fijos)"], note: "Factores como deficiencia de yodo (rara hoy en día) o la tiroiditis de Hashimoto pueden propiciar su aparición." }, diagnosis: { title: "Evaluación Endocrina y Ecográfica", intro: "El objetivo clínico principal es descartar que el nódulo sea un cáncer:", items: ["Ecografía tiroidea (el examen indispensable y más preciso para evaluar el tamaño, la forma sólida/líquida, los bordes y buscar calcificaciones sospechosas)", "Análisis de sangre (para medir la hormona TSH y saber si el nódulo está afectando el metabolismo del cuerpo o causando hipertiroidismo)", "Punción y Aspiración con Aguja Fina o PAAF (si la ecografía muestra un nódulo sospechoso o grande, el médico usa una aguja minúscula para extraer células y mandarlas al patólogo para buscar cáncer)"], note: "" }, treatment: { title: "Vigilancia, Yodo o Cirugía", intro: "El manejo clínico depende exclusivamente del resultado de la biopsia y la función del nódulo:", subsections: [ { title: "Opciones Terapéuticas", items: ["Vigilancia clínica expectante (seguimiento rutinario anual con ecografía para nódulos benignos que no crecen ni causan molestias)", "Cirugía de extirpación tiroidea (para nódulos confirmados o sospechosos de cáncer, o nódulos benignos gigantes que ahogan o dificultan tragar al paciente)", "Yodo radiactivo o medicamentos antitiroideos (usado específicamente para tratar 'nódulos calientes' que causan hipertiroidismo, destruyéndolos de forma no invasiva)", "Ablación térmica (terapias con calor o radiofrecuencia para reducir el tamaño de nódulos benignos grandes sin cirugía)"] } ], note: "La gran mayoría de pacientes nunca requerirán tratamiento quirúrgico ni desarrollarán cáncer por tener nódulos." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico endocrinólogo?", intro: "Debes buscar evaluación médica si notas o sientes en tu cuello:", items: ["Un bulto palpable, firme y endurecido que notas de repente o que puedes ver en el espejo al tragar saliva", "Dificultad progresiva inexplicable para tragar la comida, o sensación constante de tener una pastilla atascada en la garganta", "Cambios persistentes en la voz, como volverse ronca o perder fuerza, que no están asociados a un resfriado", "Pérdida de peso repentina, temblores o palpitaciones (indicios de que el nódulo está soltando demasiada hormona tiroidea)"] } },
'Insuficiencia renal aguda' : { intro: "La insuficiencia renal aguda (IRA), o lesión renal aguda, es una afección crítica que ocurre cuando los riñones pierden repentinamente (en cuestión de horas o pocos días) su capacidad vital para filtrar los productos de desecho tóxicos de la sangre.", whatIs: { title: "¿Qué es la Insuficiencia Renal Aguda?", text: "Es un fracaso repentino y orgánico. Al detenerse el riñón, los niveles de desechos metabólicos se acumulan a niveles peligrosos y el equilibrio químico de los fluidos y electrolitos de tu cuerpo se descontrola, pudiendo ser mortal rápidamente si no se instaura tratamiento médico intensivo." }, types: { title: "Causas y Orígenes Anatómicos", intro: "Las causas se dividen clásicamente en tres categorías:", items: ["Causas Prerrenales (el problema ocurre ANTES del riñón: una caída brusca y masiva de la presión o flujo de sangre a los riñones por hemorragia, shock o deshidratación severa)", "Causas Intrínsecas o Renales (daño directo DENTRO del tejido del riñón: provocado por toxinas, metales, abuso de medicamentos como el ibuprofeno, o inflamaciones autoinmunes como la glomerulonefritis)", "Causas Posrenales (el problema ocurre DESPUÉS del riñón: obstrucción mecánica que impide que la orina salga, haciendo que se regrese y destruya el riñón; típicamente cálculos renales grandes o próstata muy agrandada)"], note: "Es más frecuente en pacientes que ya están hospitalizados por enfermedades agudas, ancianos o en unidades de cuidados intensivos." }, diagnosis: { title: "Pruebas de Urgencia Hospitalaria", intro: "El diagnóstico médico debe ser extremadamente rápido para salvar el riñón:", items: ["Análisis de sangre crítico (la creatinina y el nitrógeno ureico (BUN) estarán disparados, indicando retención tóxica; y niveles de potasio peligrosamente altos que amenazan al corazón)", "Monitorización exhaustiva del volumen de producción de orina en 24 horas (en la IRA a menudo se detiene o disminuye drásticamente la orina)", "Análisis de orina (para detectar cilindros celulares, sangre o proteína)", "Ecografía o Ultrasonido renal (la imagen primordial para confirmar de inmediato si hay una piedra bloqueando el uréter y dilatando el riñón)"], note: "" }, treatment: { title: "Soporte Vital y Diálisis Aguda", intro: "Si se identifica y se revierte la causa subyacente a tiempo, los riñones a menudo pueden curarse y recuperar su función normal:", subsections: [ { title: "Intervenciones Médicas Críticas", items: ["Fluidos intravenosos (IV) abundantes (si la causa es la falta de riego sanguíneo o deshidratación) o diuréticos fuertes (si la causa es exceso de líquido que los riñones no pueden procesar)", "Tratamiento de emergencia para el potasio en sangre alto (medicamentos o calcio IV para proteger el corazón de sufrir arritmias letales)", "Diálisis temporal de urgencia (conectar al paciente a una máquina que filtra su sangre artificialmente durante días o semanas hasta que sus propios riñones sanen y vuelvan a encenderse)", "Cirugía urológica o colocación de stents/sondas (para remover piedras o próstatas que obstruyen el paso de orina)"] } ], note: "Una IRA grave requiere estancia en la Unidad de Cuidados Intensivos (UCI)." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia de vida o muerte?", intro: "Llama a urgencias o dirígete al hospital más cercano si observas:", items: ["Disminución drástica, brusca o cese total de la producción de orina durante un día entero", "Hinchazón generalizada masiva, principalmente en las piernas, los tobillos y alrededor de los ojos (retención de líquidos)", "Falta de aire severa inexplicable, confusión mental intensa aguda, convulsiones o estado de coma", "Dolor o pesadez opresiva en el pecho (por acumulación de líquido en los pulmones o en la membrana que cubre el corazón)"] } },
'Espondilitis anquilosante' : { intro: "La espondilitis anquilosante es un tipo de artritis inflamatoria autoinmune crónica que afecta primariamente a la columna vertebral. Causa una inflamación dolorosa entre las vértebras y en las articulaciones donde la columna se une con la pelvis (sacroilíacas).", whatIs: { title: "¿Qué es la Espondilitis Anquilosante?", text: "Es una enfermedad reumatológica. La inflamación constante y crónica provoca que el cuerpo intente 'curar' el daño fabricando hueso nuevo. Este hueso nuevo une o 'fusiona' permanentemente las vértebras de la columna (anquilosis), volviéndola rígida e inflexible, forzando una postura encorvada hacia adelante." }, types: { title: "Manifestaciones Adicionales", intro: "Aunque la columna es el objetivo central, es una enfermedad sistémica:", items: ["Afectación axial (dolor inflamatorio predominante en la espalda baja y nalgas)", "Afectación periférica (inflamación dolorosa en grandes articulaciones como caderas, hombros o rodillas)", "Entesitis (dolor en los lugares donde los tendones se unen al hueso, clásicamente en el talón de Aquiles o planta del pie)", "Uveítis (inflamación aguda, roja y muy dolorosa del ojo, una complicación frecuente asociada)"], note: "Aparece con mayor frecuencia en hombres jóvenes entre los 15 y 30 años de edad, y el retraso en el diagnóstico es tristemente común." }, diagnosis: { title: "Evaluación Reumatológica", intro: "Diferenciar este dolor mecánico del dolor inflamatorio es clave:", items: ["Examen físico del rango de movilidad de la columna y de la expansión del tórax al respirar", "Radiografías de la pelvis (para buscar sacroilitis o erosión/fusión en las articulaciones sacroilíacas) y Resonancia Magnética (para detectar inflamación temprana meses antes de que se vea daño en los rayos X)", "Prueba genética de sangre HLA-B27 (la gran mayoría de las personas con la enfermedad portan este gen, aunque tener el gen no significa que tendrás la enfermedad)"], note: "Un 'dolor de espalda' que mejora con el ejercicio físico y empeora terriblemente con el reposo en cama es la señal cardinal clínica inflamatoria." }, treatment: { title: "Frenar la Progresión Biológica", intro: "No existe cura, pero la medicación moderna frena la deformidad y permite una vida activa:", subsections: [ { title: "Opciones Terapéuticas Clave", items: ["Antiinflamatorios no esteroideos (AINEs como indometacina o naproxeno en altas dosis, son la primera línea de tratamiento y muy eficaces)", "Terapias Biológicas inyectables o intravenosas (Inhibidores del TNF o inhibidores de IL-17, medicamentos revolucionarios para casos severos que detienen la inflamación autoinmune profunda y previenen la fusión espinal)", "Fisioterapia diaria e higiene postural estricta (esencial e innegociable para mantener la columna móvil, flexible y erecta el mayor tiempo posible)", "Cirugía de reemplazo articular (para caderas gravemente dañadas) o corrección espinal (raramente usada, para enderezar deformidades severas)"] } ], note: "Fumar tabaco acelera y empeora severamente la fusión ósea de la columna en esta patología." }, whenToSeekHelp: { title: "¿Cuándo consultar al reumatólogo?", intro: "No asumas que eres 'demasiado joven para tener dolor de espalda'. Busca evaluación si:", items: ["Tienes dolor de espalda baja o en los glúteos que comenzó antes de los 40 años, de forma gradual, y que lleva durando más de 3 meses", "El dolor empeora por la noche o te despierta en la segunda mitad de la noche, forzándote a levantarte y caminar", "Notas que el dolor mejora mucho después de hacer ejercicio ligero, pero empeora significativamente al descansar o al permanecer inactivo", "Experimentas un ojo rojo, que duele a la luz de manera insoportable (uveítis) de forma súbita"] } },
'Infarto cerebral' : { intro: "Un infarto cerebral (accidente cerebrovascular isquémico, ataque cerebral o ictus) es una emergencia médica crítica que ocurre cuando se bloquea o interrumpe abruptamente el flujo de sangre a una parte del cerebro. Las células cerebrales, privadas de oxígeno, comienzan a morir en minutos.", whatIs: { title: "¿Qué es un Infarto Cerebral Isquémico?", text: "Es el equivalente a un ataque al corazón, pero en el cerebro. Ocurre mayormente por un coágulo de sangre (trombo) que se forma en las arterias del cerebro estrechadas por placas (aterosclerosis), o por un coágulo que viaja desde el corazón u otra parte del cuerpo y se atasca en el cerebro (embolia)." }, types: { title: "Clasificación Vascular", intro: "Casi el 85% de todos los derrames son isquémicos:", items: ["ACV Trombótico (el coágulo se forma directamente en una arteria cerebral muy enferma)", "ACV Embólico (el coágulo se forma lejos, clásicamente por la arritmia de Fibrilación Auricular en el corazón, y viaja hasta el cerebro)", "Ataque Isquémico Transitorio (AIT o 'mini-derrame') (los síntomas de parálisis ocurren pero el coágulo se disuelve solo en minutos o pocas horas, sin dejar daño permanente; es la mayor advertencia de que viene un derrame letal)"], note: "El 'AIT' nunca debe ignorarse, ya que un tercio de las personas sufrirá un gran infarto cerebral días después." }, diagnosis: { title: "Escáneres de Emergencia a Contrarreloj", intro: "El diagnóstico en urgencias debe ser instantáneo para salvar tejido:", items: ["Tomografía Computarizada (TC) de cráneo de urgencia sin contraste (se hace al instante de llegar al hospital para descartar un sangrado/hemorragia; si no hay sangre, se confirma que es isquémico y se procede a disolver el coágulo)", "Angiografía por TC (para ver qué vaso exacto está taponado)", "Resonancia Magnética (RM) del cerebro (para detectar qué tejido está muerto y qué tejido es aún rescatable)", "Ecocardiograma y monitoreo cardíaco posterior (para buscar el origen del coágulo)"], note: "El lema mundial médico es: 'Tiempo es Cerebro'." }, treatment: { title: "Destrucción del Coágulo en Ventana Crítica", intro: "Los tratamientos médicos más eficaces solo pueden administrarse en las primeras 3 a 4.5 horas tras el inicio del primer síntoma:", subsections: [ { title: "Tratamientos Agudos y Preventivos", items: ["Medicamentos Trombolíticos intravenosos (tPA o alteplasa: es el fármaco milagroso 'destructor de coágulos' que disuelve la obstrucción; solo puede darse en las primeras 4 horas)", "Trombectomía Mecánica Endovascular (un cirujano neurovascular inserta un microcatéter por la pierna hasta el cerebro para atrapar y extraer físicamente el coágulo; amplía la ventana de rescate hasta 24 horas en ciertos casos)", "Anticoagulantes o antiagregantes plaquetarios posteriores (aspirina, clopidogrel, para prevenir un segundo ataque inminente)", "Rehabilitación intensiva inmediata (fisioterapia, logopedia y terapia ocupacional para obligar al cerebro a re-aprender conexiones y recuperar la movilidad o el habla)"] } ], note: "Es vital anotar la HORA EXACTA en la que la persona fue vista normal por última vez; esto decide qué tratamiento puede recibir." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911 (Regla FAST / CAMALEÓN)?", intro: "Los síntomas ocurren sin aviso previo. Si observas cualquiera de ellos, llama a emergencias al instante. Usa el acrónimo FAST (Face, Arms, Speech, Time):", items: ["FACE (Cara caída): Pide a la persona que sonría. ¿Se le cae o desvía un lado de la boca o la cara hacia abajo?", "ARMS (Brazos débiles): Pide que levante ambos brazos. ¿Un brazo se cae, no puede levantarlo o se desvía incontrolablemente?", "SPEECH (Dificultad para hablar): Pide que repita una frase simple. ¿Arrastra las palabras, habla raro o es incapaz de entenderte o responder lógicamente?", "TIME (Tiempo de llamar): Si observas algo de esto, el tiempo corre. Anota la hora y busca ayuda hospitalaria en ambulancia inmediatamente."] } },
'Nefritis lúpica' : { intro: "La nefritis lúpica es una complicación seria y muy frecuente del Lupus Eritematoso Sistémico (LES). Ocurre cuando los autoanticuerpos del lupus atacan las estructuras microscópicas de los riñones que filtran los desechos, causando inflamación aguda e insuficiencia.", whatIs: { title: "¿Qué es la Nefritis Lúpica?", text: "Es una enfermedad autoinmune renal. El lupus hace que el cuerpo produzca proteínas inmunológicas perjudiciales que viajan por la sangre y se atascan en los glomérulos del riñón. Esto provoca una enorme inflamación, daño en los filtros y fuga masiva de proteínas y sangre a la orina, lo que, de no detenerse, destruye el riñón." }, types: { title: "Clases o Grados de Daño (Patológico)", intro: "El daño se clasifica biopsiando el riñón, lo que guía el tratamiento estricto:", items: ["Clase I y II (enfermedad mesangial mínima o proliferativa, suele tener buen pronóstico general)", "Clase III y IV (nefritis focal o difusa, son las formas más agresivas y destructivas, requieren de la quimioterapia inmunosupresora más fuerte para detener el fallo renal agudo)", "Clase V (nefritis membranosa, a menudo caracterizada por pérdida extrema de proteínas y edemas sistémicos)", "Clase VI (esclerosis avanzada, el riñón está totalmente destruido y cicatrizado de manera irreversible)"], note: "Hasta un 60% de los pacientes con lupus desarrollarán nefritis en algún momento de la enfermedad." }, diagnosis: { title: "Detección Temprana y Confirmatoria", intro: "Dado que no duele, la monitorización constante en los pacientes con lupus es obligatoria:", items: ["Análisis de Orina rutinario (el hallazgo principal y más temprano es la proteína albúmina alta en orina, a veces acompañada de sangre invisible microscópica)", "Análisis de sangre para evaluar la función (niveles creatinina elevados indican que la filtración está fallando)", "Biopsia Renal (el estándar de oro obligatorio e indiscutible; se extrae un minúsculo cilindro del riñón con una aguja en quirófano para determinar la Clase exacta de la inflamación y cuán agresivo debe ser el tratamiento)"], note: "" }, treatment: { title: "Inmunosupresión Agresiva", intro: "El tratamiento debe ser contundente para inducir la remisión del brote antes de perder el órgano:", subsections: [ { title: "Fármacos y Protocolos", items: ["Corticosteroides en dosis altísimas (metilprednisolona intravenosa o prednisona oral) para aplastar rápidamente el ataque inflamatorio inmediato", "Inmunosupresores pesados (Micofenolato de Mofetilo, Ciclofosfamida intravenosa, Azatioprina) para deprimir el sistema inmunitario destructivo a largo plazo", "Terapias biológicas modernas (Belimumab, Rituximab) para casos difíciles que rechazan el primer tratamiento", "Medicamentos antihipertensivos (Inhibidores de la ECA) para proteger directamente el filtro del riñón de la presión destructiva", "Diálisis o trasplante renal (si se llega a la fase irreversible terminal)"] } ], note: "Es vital un seguimiento estricto con el nefrólogo y el reumatólogo; el tratamiento dura años." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia?", intro: "Si padeces lupus y no tienes control regular, debes acudir a Urgencias o a tu médico si observas:", items: ["Un aumento repentino, masivo y descontrolado de la hinchazón (edema), especialmente en las piernas, los tobillos, las manos o amanecer con los ojos totalmente hinchados", "La orina se ve permanentemente muy espumosa, como si hubiera jabón en la taza del baño (proteinuria grave)", "Orina de color rosado oscuro, rojo, café o color té (sangre franca en vías urinarias)", "Aparición de presión arterial extremadamente alta, dolores de cabeza confusos o falta de aire inusual al acostarte"] } },
'Acalasia' : { intro: "La acalasia es un trastorno muy poco frecuente del esófago (el tubo que lleva el alimento al estómago). Produce una grave e implacable dificultad para tragar, haciendo que los alimentos sólidos y líquidos se atasquen dolorosamente en el pecho antes de llegar al estómago.", whatIs: { title: "¿Qué es la Acalasia?", text: "Es una parálisis del movimiento y del esfínter esofágico. Los nervios dentro del esófago se dañan de manera incurable. Por un lado, el músculo esofágico inferior no se relaja ni se abre para permitir que el alimento caiga al estómago. Por otro lado, la musculatura pierde el movimiento de 'onda' (peristaltismo) que empuja la comida hacia abajo." }, types: { title: "Subtipos Clínicos de Manometría", intro: "Se divide médicamente en tres tipos que responden de manera distinta a las cirugías:", items: ["Acalasia Tipo I o Clásica (pérdida total del movimiento muscular del cuerpo esofágico sin presión o presurización)", "Acalasia Tipo II (pérdida total del movimiento, pero con una intensa acumulación de presión y compresión esofágica; suele tener la mejor respuesta a la cirugía)", "Acalasia Tipo III o Espástica (la más difícil y dolorosa, acompañada de contracciones espásticas erráticas, intensas y dolorosas del esófago antes de que la comida se atasque)"], note: "No se conoce la causa, pero se sospecha que una respuesta autoinmune (posiblemente gatillada por un virus) destruye gradualmente las neuronas del esófago." }, diagnosis: { title: "Pruebas Digestivas Clave", intro: "Suele confundirse erróneamente con el reflujo (ERGE) durante años; su diagnóstico definitivo exige:", items: ["Manometría esofágica de alta resolución (la prueba dorada definitiva; se introduce un tubo con sensores de presión por la nariz hasta el estómago mientras el paciente traga agua para ver qué músculos fallan y confirmar que el esfínter inferior no se relaja)", "Esofagograma o Tránsito con bario (radiografías bebiendo líquido de contraste para ver el esófago enormemente dilatado y el esfínter inferior afilado, llamado clásicamente imagen en 'pico de pájaro')", "Endoscopia superior (imprescindible para descartar que un tumor o cáncer esté bloqueando el esfínter inferior de forma engañosa, llamado 'pseudoacalasia')"], note: "" }, treatment: { title: "Intervenciones Físicas y Quirúrgicas", intro: "No existen pastillas curativas ni remedios. Los tratamientos deben forzar mecánicamente la apertura del esfínter:", subsections: [ { title: "Procedimientos Dilatadores y Cortes", items: ["Miotomía de Heller laparoscópica (el tratamiento quirúrgico de oro: se corta quirúrgicamente el músculo del esfínter inferior esofágico desde el exterior para abrirlo de forma permanente; a menudo acompañado de una cirugía anti-reflujo)", "POEM (Miotomía Endoscópica por Vía Oral) (un procedimiento vanguardista sin incisiones donde se corta el músculo desde el interior del esófago a través de un tubo endoscópico)", "Dilatación neumática por balón (procedimiento bajo sedación donde se infla un gran globo médico en el esófago para desgarrar a la fuerza los músculos apretados; puede requerir repetirse)", "Inyecciones de Toxina Botulínica (Bótox) (paralizan el músculo y lo abren temporalmente; solo dura unos pocos meses y se reserva para pacientes muy ancianos que no pueden ser operados)"] } ], note: "Tras el tratamiento de acalasia, la gran mayoría de los pacientes desarrollarán reflujo gástrico permanente, ya que la 'válvula' de bloqueo gástrico ha sido destruida médicamente." }, whenToSeekHelp: { title: "¿Cuándo consultar a un gastroenterólogo especializado?", intro: "Es fundamental buscar revisión experta si el malestar del estómago no cede y presentas:", items: ["Dificultad constante y cada vez más grave para tragar (disfagia), primero con carnes o panes sólidos y luego incluso con agua y líquidos", "Regurgitación incontrolable de comida no digerida (comida que vuelve a subir a la boca horas después de haberla comido, con sabor a comida, no a ácido)", "Tos incesante por la noche, episodios de ahogo mientras duermes o repetidas neumonías (por aspirar comida acumulada hacia los pulmones)", "Dolor opresivo o calambres en el centro del pecho (después de comer) y pérdida de peso radical y profunda involuntaria"] } },
'Cistitis' : { intro: "La cistitis es la inflamación de la vejiga. En la inmensa mayoría de los casos, esta inflamación dolorosa es causada por una infección bacteriana y recibe el nombre de infección urinaria de la vejiga. Puede ser extremadamente dolorosa y una gran molestia si es recurrente.", whatIs: { title: "¿Qué es la Cistitis?", text: "Es la irritación infecciosa del revestimiento interno de la vejiga. Usualmente ocurre cuando bacterias dañinas (normalmente Escherichia coli, que vive en el intestino) se abren paso y suben desde el exterior por la uretra y se adhieren a las paredes de la vejiga. Es mucho más común en las mujeres adultas activas por la anatomía de su tracto urinario corto." }, types: { title: "Causas e Infecciones", intro: "Aunque la gran mayoría son infecciosas, puede estar mediada por irritantes:", items: ["Cistitis bacteriana o infección del tracto urinario (la clásica infección, provocada por coito, retención de orina o higiene incorrecta)", "Cistitis intersticial o Síndrome de Vejiga Dolorosa (una dolorosa enfermedad crónica no infecciosa en la que la pared de la vejiga está crónicamente inflamada sin bacterias)", "Cistitis inducida por medicamentos, radiación, o uso prolongado de sonda o catéter (efecto secundario destructivo de la quimioterapia o tratamiento del cáncer pélvico)", "Cistitis química (por hipersensibilidad alérgica a baños de espuma, espermicidas, aerosoles higiénicos o papel higiénico perfumado)"], note: "Las infecciones bacterianas que no se detienen a tiempo en la vejiga viajarán hacia arriba y causarán infecciones renales severas (pielonefritis)." }, diagnosis: { title: "Detección de Laboratorio Inmediata", intro: "Se diagnostica fácilmente con síntomas y muestra clínica:", items: ["Análisis de orina mediante tiras reactivas (revelan inflamación -leucocitos- o presencia de sangre y nitritos casi instantáneamente)", "Cultivo de orina o Urocultivo (la prueba de laboratorio fundamental que tarda 48 hrs; identifica qué cepa específica de bacteria está causando la infección y detalla exactamente qué familia de antibiótico la aniquila y cuál es resistente)", "Cistoscopia visual (solo reservada para cistitis intersticiales o infecciones graves y repetitivas, usando un tubo con cámara insertado en la uretra para buscar cáncer o defectos)"], note: "" }, treatment: { title: "Terapia Antibiótica y Paliativa", intro: "El manejo para las causas bacterianas es totalmente efectivo y curativo:", subsections: [ { title: "Enfoques y Curas", items: ["Medicamentos antibióticos (como Nitrofurantoína, Fosfomicina, o Cefalexina; el dolor disminuye drásticamente en 24-48 horas, pero debe terminarse la caja prescrita para no crear bacterias mutantes resistentes)", "Medicamentos analgésicos genitourinarios (la Fenazopiridina adormece el tejido ardiente y calma los espasmos de la vejiga en horas, tiñendo la orina de color naranja oscuro inofensivo)", "Aumento masivo en la hidratación (agua para diluir y lavar las bacterias remanentes por arrastre)", "En casos de Cistitis Intersticial, el enfoque es crónico: cambios estrictos de dieta (evitar café, ácidos), estiramientos pélvicos, y medicamentos orales como Pentosano o instilaciones directamente en la vejiga"] } ], note: "Para prevención en mujeres propensas, orinar obligatoriamente antes y, sobre todo, después del coito o actividad sexual elimina mecánicamente cualquier bacteria subida a la uretra." }, whenToSeekHelp: { title: "¿Cuándo solicitar asistencia de tu médico?", intro: "Acude o agenda cita lo más antes posible si presentas:", items: ["Necesidad apremiante, desesperada e intensa de orinar constantemente (incluso justo después de haber vaciado la vejiga), expulsando solo pequeñísimas gotas", "Sensación aguda de fuego, punzadas, dolor o escozor severo al terminar o durante el acto de orinar", "Una orina con aspecto anormalmente opaco o muy turbio, de olor extremadamente fétido e insoportable", "Muestras de sangre pura o orina intensamente rosada o rojiza, o acompañamiento de dolor lumbar profundo acompañado de picos de fiebre y escalofríos (emergencia renal indicativa)"] } },
'Derrame cerebral' : { intro: "Un derrame cerebral, también denominado accidente cerebrovascular (ACV), ictus o ataque cerebral, es una emergencia médica catastrófica que se produce cuando se interrumpe abruptamente el suministro de sangre vital a una porción del cerebro, o cuando estalla o revienta un vaso sanguíneo en el interior del cráneo.", whatIs: { title: "¿Qué es un Derrame Cerebral?", text: "Es el cese brusco del flujo sanguíneo neurológico. El cerebro es un órgano exigente; si no recibe oxígeno y nutrientes frescos ni por unos pocos minutos, las delicadas neuronas cerebrales comienzan a asfixiarse y morir permanentemente, originando un daño cerebral, parálisis, pérdida del habla e incluso la muerte clínica si no se revierte de inmediato." }, types: { title: "Naturaleza Vascular del Infarto o Sangrado", intro: "Se divide en dos grandísimos grupos de abordaje totalmente opuesto en urgencias:", items: ["ACV Isquémico o infarto cerebral (representa casi el 87% de casos; la causa absoluta es una obstrucción, a menudo por un coágulo de sangre de la arteria carótida u originado en el corazón -embolia-, o por paredes engrosadas por aterosclerosis -trombosis- que asfixia y mata el tejido)", "ACV Hemorrágico o hemorragia cerebral (menos común pero con altísima mortalidad; sucede cuando una vena débil o aneurisma de la cabeza se rompe y estalla, inundando en sangre y aplastando el tejido cerebral contiguo -causa principal: presión arterial alta extrema-)", "Ataque isquémico transitorio (AIT) o miniderrame (una gran bandera roja; el coágulo tapona la vena temporalmente y los síntomas aterradores ocurren, pero se disuelve o mueve a los pocos minutos; avisa firmemente que un derrame total es inminente en los próximos días)"], note: "El tabaco, la hipertensión grave, el sobrepeso, y la Fibrilación Auricular cardíaca son sus mayores promotores." }, diagnosis: { title: "El Factor 'Tiempo' y Exámenes en Cuarto de Emergencia", intro: "El reloj corre; el diagnóstico urgente decide si el paciente recibe medicación que le salvará del deterioro:", items: ["Tomografía Computarizada (TC) de urgencia vital rápida y sin contraste al momento del ingreso al hospital (el estudio fundamental para determinar en minutos si el cerebro está sangrando o si es un infarto isquémico obstruido; esto determina la medicación inmediata)", "Resonancia Magnética (RM) del cerebro, angiografía de TC (para hallar exactamente qué vena cuello/cerebro se taponó)", "Electrocardiograma y eco-doppler (para investigar de dónde vino disparado el coágulo originario, a menudo el corazón o carótidas)", "Análisis de nivel de glucosa en el lugar (un nivel bajísimo de azúcar puede causar síntomas idénticos a los de un ACV)"], note: "" }, treatment: { title: "La Terapia 'Trombolítica' Inmediata y Extracción de Trombos", intro: "El tipo de derrame dicta todo el tipo de terapia de urgencia, pero la actuación y premura de las primeras 4 horas salva:", subsections: [ { title: "Rescates Clínicos en Sala de Choque", items: ["Para Isquémico Agudo (antes de las 4,5 hrs.): Terapia trombolítica intravenosa de urgencia (Inyección del Alteplasa tPA, el único y grandioso fármaco capaz de disolver velozmente el coágulo en el cerebro y salvar del daño letal al paciente)", "Trombectomía endovascular mecánica (para coágulos masivos; un cirujano interviene y mete un cable/catéter micro por la ingle hasta el cerebro para enganchar y retirar el trombo sólido atrapado en la arteria cerebral, efectivo hasta 24 hrs después)", "Para Hemorrágico o Derrame por Rotura: NUNCA tPA; cirugía neurológica de urgencia (craneotomía) para drenar el líquido sanguíneo que estruja al cerebro, clampar el vaso o colocar espirales por catéter, y medicación potente para bajar de golpe la tensión de la sangre", "Rehabilitación y Prevención: Anticoagulantes crónicos y aspirina de por vida, más el riguroso y extenuante programa de fisioterapia y del logopeda para reeducar la extremidad muerta o devolver el habla del lenguaje (Afasia)"] } ], note: "Por cada largo minuto que el ACV quede sin tratamiento médico y de paso bloqueado en el cuerpo, pierdes alrededor e irremediablemente de 2 millones de neuronas cerebrales vitales." }, whenToSeekHelp: { title: "¿Cuándo ejecutar la llamada de Ambulancia - REGLA F.A.S.T o C.A.M.A.L.E.O.N?", intro: "Llama inmediatamente a emergencias hospitalarias (no asumas que se pasará, no duermas) si observas repentinamente:", items: ["F de 'Face' (Asimetría en el rostro): Pide que sonría. ¿Un lado lateral de la cara inferior de su labio o comisura cuelga hacia abajo repentinamente?", "A de 'Arms' (Brazos): Pide a la persona que eleve a la altura los dos brazos. ¿Siente imposibilidad u observa que uno de los brazos recae inerte y débil rápidamente?", "S de 'Speech' (Habla extraña): Pide hablar repitiendo una oración sencilla normal. ¿El paciente arrastra la voz y se oye como borracho, tiene incapacidad patológica de decirla o es ininteligible?", "T de 'Time' (Tiempo de URGENCIA de llamada): Anota inmediatamente a qué hora exacta comenzó todo y llama al 911 al ver tan solo 1 de todos estos fallos neurológicos vitales"] } },
'Erosión Dental' : { intro: "La erosión dental es el desgaste anormal y progresivo, el derretimiento y pérdida química irreversible de la durísima estructura de protección de tus dientes: el esmalte dental (la sustancia más firme de todo el organismo humano). Es causada exclusivamente por la invasión de ácidos fuertes no provenientes de la biopelícula o de bacterias.", whatIs: { title: "¿Qué es la Erosión y Disolución del Esmalte?", text: "A diferencia enorme de las conocidas y temidas clásicas caries dentales (provocadas lentamente por el ácido biológico que segrega la bacteria dental de placa por azúcar), la erosión patológica es la pérdida física directa destructiva química en el duro diente mediante sustancias sumamente ácidas de naturaleza intrínseca biológica del paciente o de dieta externa, lo que vuelve los frágiles dientes huecos, muy amarillos y crónicamente hipersensibles dolorosos." }, types: { title: "Orígenes Fisiológicos Digestivos o Comportamientos", intro: "Se clasifican fundamentalmente por dónde proviene y se genera el agente de ácido fuerte causante:", items: ["Erosión Intrínseca Digestiva Patológica (la causa más grave crónica y muy devastadora, causada repetidamente por los ácidos biológicos e hiperácidos del propio estómago que suben a la garganta tras el reflujo y la ERGE, y a menudo detrás de los grandes dientes, en embarazos por hiperémesis, o por patología de purga de la anorexia/bulimia nerviosa)", "Erosión Extrínseca Dietética Dietaria (originada exclusivamente de factores del entorno del individuo; consumo severo masivo de alimentos agresivos, típicamente bebidas y refrescos oscuros carbonatados y bebidas deportivas diarias ácidas, vinos repetitivos o por morder chupando jugo directo ácido de limones puros o por pastillas de vitamina C efervescentes)"], note: "El paciente jamás debe cepillarse fuertemente el esmalte dolorido dental justo instantes luego de ingerir y haber estado en contacto directo con líquido o vómito muy ácido, pues destruirá el esmalte que aún yace blando; se debe siempre aguardar mínimo de 45 a 60 minutos para que se re-mineralice la estructura con tu propia saliva en boca." }, diagnosis: { title: "Detección Odontológica Temprana de Signos", intro: "El especialista y experto dentista u odontólogo detectará su aparición en los diagnósticos precoces:", items: ["La directa revisión odontológica y exploración clínica e intensa (detectando el desgaste general pulido; una pérdida del brillo esmaltado claro blanco brillante o perlado en favor a una extraña textura transparente o superficie dental vitrificada excesivamente limpia y lisa, especialmente a nivel de las paredes cóncavas interiores por atrás en dientes muy del frente)", "Aparición de surcos o depresiones grandes en taza pequeñas en la gran superficie superior lisa desgastada de la masticación (donde se han 'disuelto' pequeñas cuencas)", "Prueba y confirmación del dolor extremo o punzada nerviosa aguda cuando se arroja el chorro ligero de aire a temperatura de consultorio muy fría de presión contra el cuellito o centro de la pieza expuesta subyacente (dentina)"], note: "" }, treatment: { title: "Neutralización y Restituciones Múltiples Reparadoras", intro: "Ningún esmalte biológico ya disuelto volverá jamás a regenerarse. La reparación consistirá obligatoriamente en estabilizar el origen digestivo pernicioso y reponer la forma estética del recubrimiento faltante perdido en consulta:", subsections: [ { title: "Técnicas Restauradoras Profesionales", items: ["Control estricto de la causa médica e hiperácida intrínseca subyacente grave (requiriendo frecuentemente interconsultas con expertos para el grave control de problemas alimenticios mentales con un psiquiatra, o usar potentes medicamentos del tubo de reflujo -IBP u omeprazol- de su aparato gastrointestinal recetados de por vida mediante gastroenterólogo)", "Terapia y manejo tópico desensibilizante y de flúor reforzante por odontólogo (colocación abundante y continua de capas o barnices médicos remineralizantes protectores de flúor de alta potencia que endurezcan el núcleo restante del diente inferior)", "Relleno preventivo (en la etapa de pequeñas lesiones localizadas, el dentista rellenará el huequito concavado directo utilizando adhesivo o resinas compuestas de color blanco natural dental)", "Coronas de porcelana gruesa (el gran método absoluto salvador en estados ya terminales; una corona encapuchará integralmente como si fuera un casco dental enterizo para evitar su eventual rotura por ser muy pequeños y finos al partir)"] } ], note: "El dolor e hipersensibilidad al morder frío indica a menudo el nivel inicial de que el esmalte se va; si de repente los dientes en la zona del frente superior parecen translúcidos oscuros de color al trasluz y luego amarillos macizos debajo, es dentina al descubierto." }, whenToSeekHelp: { title: "¿Cuándo recurrir y programar pronto la visita al higienista dentista?", intro: "Reserva de forma puntual y pronta cita si tienes presentimientos físicos dentales agudos tales como:", items: ["El surgimiento agudo repentino constante de alta gran hipersensibilidad o una verdadera y espantosa 'punzada dolorosa aguda parecida a un clavo' que recorre tu nervio al masticar cualquier elemento frío o al tragar grandes líquidos helados y sorber agua congelada", "Los filos transparentes delgados, inferiores, afilados de los incisivos delanteros dentales de sonrisa sufren roturas con extremada y asombrosa e inusual facilidad ante comidas normales y los bordes son translúcidos en su final", "Identificas o palpas al repasar un notorio o claro hoyo hundido al borde superficial cóncavo 'como rampa' del cuello gingival final superior dental o notas en la revisión espejada que tu mordida entera es notablemente e irreversiblemente más amarilla mate fuerte que antes a pesar del cepillado (estás observando la propia dentina interior directamente viva y destapada)"] } },
'Trastorno obsesivo compulsivo (TOC)' : { intro: "El trastorno obsesivo-compulsivo (TOC) es una afección mental crónica en la que una persona tiene pensamientos incontrolables y recurrentes (obsesiones) y comportamientos (compulsiones) que siente la necesidad de repetir una y otra vez.", whatIs: { title: "¿Qué es el TOC?", text: "Es un trastorno de ansiedad grave. Las obsesiones generan gran angustia, y las compulsiones son intentos temporales de aliviar esa ansiedad, creando un ciclo rígido que interfiere con la vida diaria." }, symptoms: { title: "Síntomas", intro: "Se divide en obsesiones y compulsiones:", groups: [ { name: "Obsesiones", items: ["Miedo a los gérmenes o contaminación", "Pensamientos prohibidos o tabúes", "Necesidad de simetría perfecta"] }, { name: "Compulsiones", items: ["Lavado de manos excesivo", "Comprobar cosas repetidamente (como puertas cerradas)", "Contar compulsivamente"] } ], warning: "Realizar estos rituales no da placer, solo un alivio temporal de la ansiedad." }, types: { title: "Temáticas Comunes", intro: "El TOC suele centrarse en temas específicos:", items: ["Limpieza y contaminación", "Duda y comprobación", "Orden y simetría", "Pensamientos intrusivos inaceptables"], note: "Los síntomas pueden fluctuar en intensidad a lo largo del tiempo." }, causes: { title: "Causas", intro: "Se desconoce la causa exacta, pero influyen:", items: ["Factores genéticos e historia familiar", "Biología y química cerebral (anomalías en la serotonina)", "Entorno (infecciones infantiles o traumas)"] }, diagnosis: { title: "Diagnóstico", intro: "Lo realiza un profesional de salud mental:", items: ["Evaluación psicológica detallada", "Aplicación de criterios del manual DSM-5", "Descarte de otros trastornos como ansiedad generalizada o esquizofrenia"], note: "El paciente suele reconocer que sus obsesiones son irracionales." }, treatment: { title: "Tratamiento", intro: "Es altamente tratable:", subsections: [ { title: "Opciones", items: ["Psicoterapia (Terapia de Exposición y Prevención de Respuesta - EPR)", "Medicamentos (Antidepresivos ISRS)"] } ], note: "La combinación de terapia y medicación ofrece los mejores resultados." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca ayuda profesional si:", items: ["Las obsesiones y compulsiones consumen más de una hora al día", "Causan gran angustia emocional", "Interfieren con el trabajo, la escuela o la vida social"] } },
'Enfermedad renal' : { intro: "La enfermedad renal implica que los riñones están dañados y no pueden filtrar la sangre como deberían. Esto puede causar que los desechos se acumulen en el cuerpo, llevando a otros problemas de salud graves.", whatIs: { title: "¿Qué es la Enfermedad Renal?", text: "Es el deterioro progresivo o agudo de la función de los riñones. Cuando fallan, el cuerpo retiene exceso de líquidos y toxinas, y se altera la producción de glóbulos rojos y la salud ósea." }, symptoms: { title: "Síntomas", intro: "En etapas tempranas es silenciosa; luego aparecen:", groups: [ { name: "Signos Clínicos", items: ["Fatiga y debilidad", "Hinchazón en pies, tobillos o cara", "Cambios en la frecuencia de orinar (muy a menudo o casi nada)", "Orina espumosa o con sangre", "Picazón persistente en la piel"] } ], warning: "El daño renal crónico es irreversible; la detección temprana es la única forma de detenerlo." }, types: { title: "Clasificación", intro: "Se divide principalmente por su temporalidad:", items: ["Enfermedad Renal Crónica (ERC) (progresiva y a largo plazo)", "Lesión Renal Aguda (LRA) (pérdida repentina de la función, a menudo reversible)", "Enfermedad poliquística renal (trastorno genético)"], note: "" }, causes: { title: "Causas", intro: "Las principales causas a nivel mundial son:", items: ["Diabetes (tipo 1 y 2)", "Presión arterial alta (hipertensión)", "Glomerulonefritis (inflamación de los filtros renales)", "Uso prolongado de medicamentos tóxicos para el riñón (AINEs)"] }, diagnosis: { title: "Diagnóstico", intro: "Se detecta con pruebas simples de laboratorio:", items: ["Análisis de sangre (Creatinina y Tasa de Filtración Glomerular - TFG)", "Análisis de orina (búsqueda de proteínas/albúmina)", "Ecografía renal para ver la estructura del riñón"], note: "" }, treatment: { title: "Tratamiento", intro: "Busca frenar el daño y manejar los síntomas:", subsections: [ { title: "Estrategias", items: ["Control estricto de la presión arterial y el azúcar en sangre", "Dieta renal (baja en sodio, potasio y proteínas)", "Medicamentos para la anemia y protección renal (IECA/ARA II)", "Diálisis o trasplante en etapas terminales"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental realizar chequeos si:", items: ["Tienes diabetes o hipertensión (revisión anual obligatoria)", "Notas hinchazón inexplicable en extremidades", "Tu orina tiene mucha espuma o sangre"] } },
'Rechazo al trasplante' : { intro: "El rechazo al trasplante es un proceso en el cual el sistema inmunológico del receptor ataca el órgano o tejido trasplantado (injerto) porque lo reconoce como un cuerpo extraño, intentando destruirlo.", whatIs: { title: "¿Qué es el Rechazo al Trasplante?", text: "Es una respuesta inmunitaria normal. El cuerpo humano está diseñado para destruir cualquier tejido extraño (como bacterias o virus). Al recibir un órgano nuevo, el sistema inmune detecta proteínas diferentes (antígenos) y lanza un ataque celular contra él." }, symptoms: { title: "Síntomas", intro: "Dependen del órgano trasplantado, pero en general incluyen:", groups: [ { name: "Signos Sistémicos y Locales", items: ["Fiebre, escalofríos y sensación general de enfermedad", "Dolor o inflamación en la zona del órgano trasplantado", "Disminución de la función del órgano (ej. menos orina si es riñón, ictericia si es hígado)"] } ], warning: "Un rechazo agudo puede ocurrir en cualquier momento y requiere tratamiento inmunosupresor de emergencia." }, types: { title: "Tipos de Rechazo", intro: "Se clasifican por el tiempo en que ocurren:", items: ["Rechazo hiperagudo (ocurre minutos u horas después del trasplante; el órgano debe extraerse de inmediato)", "Rechazo agudo (ocurre en las primeras semanas o meses; es muy común y tratable)", "Rechazo crónico (ocurre lentamente a lo largo de años, dañando el órgano de forma irreversible)"], note: "" }, causes: { title: "Causas", intro: "El origen es puramente inmunológico:", items: ["Incompatibilidad de antígenos (HLA) entre donante y receptor", "Niveles inadecuados de medicamentos inmunosupresores", "Infecciones que 'despiertan' al sistema inmunológico"] }, diagnosis: { title: "Diagnóstico", intro: "Se debe confirmar el daño al órgano:", items: ["Biopsia del órgano trasplantado (el estándar de oro para confirmar el rechazo)", "Análisis de sangre (para verificar la función del órgano, ej. creatinina para riñón)", "Ecografía o Doppler para revisar el flujo sanguíneo al órgano"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es detener el ataque del sistema inmunológico:", subsections: [ { title: "Opciones Médicas", items: ["Aumento de la dosis de los medicamentos inmunosupresores actuales", "Corticosteroides en dosis altas por vía intravenosa", "Uso de anticuerpos fuertes (como globulina antitimocítica)", "Plasmaféresis para limpiar los anticuerpos de la sangre"] } ], note: "Los pacientes trasplantados deben tomar medicamentos antirrechazo de por vida." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Contacta a tu equipo de trasplante de inmediato si:", items: ["Tienes fiebre superior a 38°C", "Sientes dolor en el área del trasplante", "Notas una caída repentina en la función del órgano (ej. dejas de orinar)"] } },
'Síndrome de Sjogren' : { intro: "El Síndrome de Sjögren es un trastorno autoinmune crónico en el que el sistema inmunológico del cuerpo ataca por error sus propias glándulas productoras de humedad, principalmente las glándulas salivales y lagrimales.", whatIs: { title: "¿Qué es el Síndrome de Sjögren?", text: "Es una enfermedad reumatológica que causa sequedad extrema. Los glóbulos blancos atacan las glándulas exocrinas, reduciendo drásticamente la producción de lágrimas y saliva, lo que puede dañar la superficie de los ojos y la boca." }, symptoms: { title: "Síntomas", intro: "Los dos síntomas principales son la sequedad:", groups: [ { name: "Síntomas Clásicos", items: ["Ojos secos (sensación de ardor, picazón o arena en los ojos)", "Boca seca (dificultad para tragar alimentos secos, hablar o saborear)", "Dolor articular, hinchazón y rigidez", "Fatiga severa", "Piel seca y sequedad vaginal"] } ], warning: "La falta de saliva aumenta masivamente el riesgo de caries dentales severas y candidiasis oral." }, types: { title: "Clasificación", intro: "Se divide en dos formas:", items: ["Síndrome de Sjögren primario (ocurre por sí solo, sin otra enfermedad autoinmune)", "Síndrome de Sjögren secundario (ocurre junto con otra enfermedad autoinmune, como artritis reumatoide o lupus)"], note: "" }, causes: { title: "Causas", intro: "Es una enfermedad autoinmune de causa desconocida, influenciada por:", items: ["Predisposición genética", "Factores ambientales (una infección viral o bacteriana puede ser el detonante)", "Hormonas (afecta abrumadoramente a mujeres, especialmente tras la menopausia)"] }, diagnosis: { title: "Diagnóstico", intro: "Requiere múltiples pruebas para confirmar el daño y la autoinmunidad:", items: ["Análisis de sangre (búsqueda de anticuerpos específicos Anti-Ro/SSA y Anti-La/SSB)", "Prueba de Schirmer (tiras de papel para medir la producción de lágrimas)", "Biopsia del labio (para examinar las glándulas salivales menores y confirmar la inflamación)"], note: "" }, treatment: { title: "Tratamiento", intro: "Se centra en aliviar los síntomas y prevenir complicaciones:", subsections: [ { title: "Terapias", items: ["Lágrimas artificiales y pomadas lubricantes oculares", "Medicamentos para estimular la saliva (pilocarpina o cevimelina)", "Inmunosupresores (hidroxicloroquina o metotrexato) para tratar el dolor articular y sistémico", "Buena higiene dental y visitas frecuentes al dentista"] } ], note: "Beber agua a pequeños sorbos constantemente es vital." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Busca ayuda especializada (reumatólogo u oftalmólogo) si:", items: ["Tus ojos están constantemente rojos, irritados y no toleras la luz", "Tienes dificultad para tragar alimentos secos sin agua", "Presentas inflamación recurrente en las glándulas salivares (debajo de la mandíbula)"] } },
'Cuello torcido' : { intro: "El cuello torcido, médicamente conocido como tortícolis, es una afección dolorosa en la que los músculos del cuello, particularmente el esternocleidomastoideo, sufren un espasmo, causando que la cabeza se incline hacia un lado y la barbilla apunte hacia el otro.", whatIs: { title: "¿Qué es la Tortícolis?", text: "Es una contracción muscular involuntaria y sostenida en el cuello. Puede ser temporal, debido a una mala postura al dormir, o crónica y severa, limitando drásticamente el rango de movimiento de la cabeza y causando un dolor intenso." }, symptoms: { title: "Síntomas", intro: "El cuadro es típicamente físico y visible:", groups: [ { name: "Signos Clínicos", items: ["Incapacidad o dolor extremo al intentar mover la cabeza normalmente", "La cabeza está inclinada o girada hacia un lado de forma fija", "Músculos del cuello visiblemente tensos, rígidos o inflamados", "Dolor de cabeza o temblores musculares en el cuello"] } ], warning: "Si la rigidez del cuello se acompaña de fiebre alta y dolor de cabeza intenso, podría ser meningitis, una urgencia letal." }, types: { title: "Tipos de Tortícolis", intro: "Se divide por su causa y momento de aparición:", items: ["Tortícolis muscular aguda (la más común, por mala postura o frío, desaparece en unos días)", "Tortícolis congénita (presente al nacer, por acortamiento del músculo en el útero)", "Tortícolis espasmódica o distonía cervical (un trastorno neurológico crónico doloroso donde el cerebro envía señales erróneas al músculo)"], note: "" }, causes: { title: "Causas", intro: "Las causas varían desde mecánicas hasta neurológicas:", items: ["Dormir en una posición incómoda sin buen soporte", "Traumatismos (latigazo cervical en accidentes)", "Estrés emocional intenso que tensa la musculatura", "Problemas genéticos o neurológicos (en la distonía cervical)"] }, diagnosis: { title: "Diagnóstico", intro: "El médico diagnostica mediante la exploración física:", items: ["Palpación de los músculos del cuello para detectar espasmos", "Evaluación del rango de movimiento", "Radiografías o RM solo si se sospecha de hernias discales, problemas vertebrales o si el dolor no cede en semanas"], note: "" }, treatment: { title: "Tratamiento", intro: "El objetivo es relajar el músculo y aliviar el dolor:", subsections: [ { title: "Medidas", items: ["Aplicación de calor local y reposo (para la tortícolis aguda común)", "Fisioterapia y estiramientos suaves", "Medicamentos (relajantes musculares, AINEs como ibuprofeno)", "Inyecciones de toxina botulínica (Bótox) (el tratamiento de oro para la distonía cervical crónica, paralizando el músculo espástico)", "Cirugía (muy raro, para alargar el músculo en tortícolis congénita severa)"] } ], note: "Usar un collarín cervical sin indicación médica puede empeorar la condición al atrofiar los músculos." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Busca atención médica rápida si:", items: ["La rigidez del cuello se acompaña de fiebre alta, confusión o náuseas", "El dolor se irradia hacia los brazos con sensación de hormigueo o debilidad", "El espasmo no mejora en absoluto después de una semana de cuidados en casa"] } },
'Trauma ocular' : { intro: "Un trauma ocular es cualquier lesión física o química que sufre el ojo. Puede variar desde un rasguño superficial en la córnea hasta lesiones penetrantes graves que amenazan la visión permanentemente, siendo una emergencia médica oftalmológica.", whatIs: { title: "¿Qué es el Trauma Ocular?", text: "Es el daño a la compleja y delicada estructura del globo ocular o sus anexos (párpados, órbita) causado por un impacto contundente, un objeto punzante, calor o salpicaduras de sustancias químicas tóxicas." }, symptoms: { title: "Síntomas", intro: "Los signos varían según la gravedad del impacto:", groups: [ { name: "Signos de Alarma", items: ["Dolor ocular intenso y constante", "Pérdida de visión repentina, visión doble o visión borrosa", "Sangrado dentro del ojo (hifema) o alrededor del ojo (ojo morado severo)", "Incapacidad para abrir el ojo o moverlo normalmente", "Sensación insoportable de tener algo dentro del ojo"] } ], warning: "Nunca intentes frotar el ojo, aplicar presión ni retirar un objeto que esté clavado en el globo ocular." }, types: { title: "Tipos de Lesiones", intro: "Se clasifican por el mecanismo de la herida:", items: ["Traumatismo contuso (golpe cerrado, ej. por una pelota o puño; puede causar fracturas orbitales o hifema)", "Traumatismo penetrante/perforante (un objeto afilado corta y atraviesa la pared del ojo)", "Abrasión corneal (un rasguño en la superficie, muy doloroso pero generalmente cura bien)", "Quemadura química (salpicadura de ácidos o bases, como lejía; una urgencia absoluta)"], note: "" }, causes: { title: "Causas", intro: "Ocurren comúnmente en accidentes:", items: ["Accidentes de tráfico y explosión de bolsas de aire (airbags)", "Lesiones deportivas (pelotas de tenis, squash, golpes)", "Accidentes laborales o domésticos (herramientas, astillas de madera o metal voladoras)", "Salpicaduras de productos de limpieza químicos"] }, diagnosis: { title: "Evaluación Oftalmológica de Urgencia", intro: "El especialista evaluará el daño inmediatamente:", items: ["Evaluación de la agudeza visual (si el paciente puede abrir el ojo)", "Examen con lámpara de hendidura y tinción con fluoresceína (para ver cortes o abrasiones en la córnea)", "Medición de la presión intraocular", "Tomografía Computarizada (TC) de las órbitas (para buscar fracturas de huesos o cuerpos extraños alojados profundamente)"], note: "" }, treatment: { title: "Tratamiento y Cirugía", intro: "Depende estrictamente del tipo de lesión:", subsections: [ { title: "Intervenciones", items: ["Lavado ocular continuo y masivo inmediato (el único y vital tratamiento para quemaduras químicas antes de ir al médico)", "Gotas antibióticas y parches oculares (para abrasiones corneales)", "Cirugía de urgencia (para suturar cortes en el globo ocular, reparar fracturas orbitales o extraer cuerpos extraños penetrantes)"] } ], note: "El uso de gafas de protección en el trabajo y el deporte previene el 90% de los traumas oculares graves." }, whenToSeekHelp: { title: "¿Cuándo ir a urgencias?", intro: "Cualquier golpe fuerte en el ojo requiere revisión. Ve a urgencias de inmediato si:", items: ["Una sustancia química salpicó tus ojos (lávalos con agua durante 15 minutos sin parar antes de ir al hospital)", "Tienes un corte visible en el ojo o un objeto clavado", "Hay sangre acumulada en la parte inferior de la parte coloreada de tu ojo (hifema)", "Tu visión cambió repentinamente, ves doble o no ves nada"] } },
'Trastorno del sueño por ansiedad' : { intro: "El trastorno del sueño por ansiedad es una condición en la que los altos niveles de estrés, preocupación crónica y ansiedad provocan insomnio persistente, dificultad para mantener el sueño o pesadillas, creando un círculo vicioso que empeora la salud mental.", whatIs: { title: "¿Qué es este Trastorno?", text: "Es la alteración del ciclo de descanso causada por la hiperactividad del sistema nervioso. La ansiedad mantiene al cerebro en un estado de 'lucha o huida', liberando cortisol y adrenalina, lo que hace físicamente imposible que la persona se relaje lo suficiente para dormir profundamente." }, symptoms: { title: "Síntomas", intro: "Afecta tanto la noche como el día:", groups: [ { name: "Nocturnos y Diurnos", items: ["Dificultad extrema para quedarse dormido (mente acelerada o pensamientos intrusivos)", "Despertares frecuentes en medio de la noche con taquicardia o sudoración", "Despertar muy temprano en la madrugada sin poder volver a dormir", "Fatiga paralizante durante el día, irritabilidad y dificultad para concentrarse"] } ], warning: "La privación crónica de sueño agrava los trastornos de ansiedad, creando un bucle difícil de romper." }, types: { title: "Manifestaciones", intro: "El insomnio ansioso puede presentarse como:", items: ["Insomnio de inicio (incapacidad para conciliar el sueño al acostarse)", "Insomnio de mantenimiento (incapacidad para mantener el sueño continuo)", "Trastorno de pesadillas o terrores nocturnos derivados de traumas o estrés agudo"], note: "" }, causes: { title: "Causas", intro: "La causa raíz es la falta de regulación emocional y el estrés:", items: ["Trastorno de Ansiedad Generalizada (TAG)", "Ataques de pánico nocturnos", "Preocupación excesiva por problemas laborales, financieros o de salud", "Ansiedad de desempeño respecto al propio sueño (miedo a no poder dormir)"] }, diagnosis: { title: "Evaluación Médica y Psicológica", intro: "Se diagnostica evaluando los patrones de sueño y la salud mental:", items: ["Diario del sueño (registro de horarios, despertares y pensamientos antes de dormir)", "Entrevista clínica psicológica para evaluar el nivel de ansiedad y depresión", "Polisomnografía (estudio del sueño en clínica, usado solo si se sospecha apnea del sueño u otros trastornos físicos que imitan la ansiedad)"], note: "" }, treatment: { title: "Tratamiento y Hábitos", intro: "Se debe tratar la ansiedad subyacente, no solo el síntoma del insomnio:", subsections: [ { title: "Terapias", items: ["Terapia Cognitivo-Conductual para el Insomnio (TCC-I) (el tratamiento de primera línea, más eficaz que las pastillas a largo plazo para reestructurar la relación con el sueño)", "Higiene del sueño (horarios estrictos, evitar pantallas antes de dormir, habitación oscura y fresca)", "Técnicas de relajación profunda (meditación, respiración diafragmática, mindfulness)", "Medicamentos (ansiolíticos o antidepresivos sedantes recetados temporalmente; se evitan las pastillas para dormir a largo plazo por riesgo de dependencia)"] } ], note: "Usar alcohol para intentar dormir empeora drásticamente la calidad del sueño en la segunda mitad de la noche." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Busca ayuda profesional si:", items: ["Tus problemas para dormir duran más de un mes y afectan gravemente tu rendimiento diurno", "La hora de ir a la cama te produce ataques de ansiedad, pánico o miedo", "Sientes que la falta de sueño te está llevando a la depresión extrema o pensamientos oscuros"] } },
'Absceso anal' : { intro: "Un absceso anal es una dolorosa acumulación de pus que se forma cerca del ano. Ocurre cuando una de las pequeñas glándulas que se encuentran en el interior del canal anal se bloquea e infecta con bacterias.", whatIs: { title: "¿Qué es un Absceso Anal?", text: "Es una cavidad infectada llena de pus ubicada debajo de la piel en la región perianal. Si no se trata y se drena adecuadamente, el absceso crecerá, causará un dolor insoportable y puede derivar en una fístula anal (un túnel anormal desde el intestino hacia la piel)." }, symptoms: { title: "Síntomas", intro: "Los signos de infección son rápidos y muy dolorosos:", groups: [ { name: "Síntomas Locales y Sistémicos", items: ["Dolor punzante, constante y muy agudo en la zona anal, que empeora intensamente al sentarse o al toser", "Un bulto palpable, rojo, inflamado y muy caliente cerca del ano", "Supuración de pus o líquido con mal olor", "Fiebre, escalofríos y malestar general (signos de infección grave)"] } ], warning: "En pacientes con diabetes o inmunodeprimidos, un absceso anal puede progresar rápidamente a una infección sistémica letal (sepsis o gangrena de Fournier)." }, types: { title: "Tipos por Ubicación", intro: "Se clasifican según su profundidad anatómica:", items: ["Absceso perianal (el más común, superficial y justo debajo de la piel alrededor del ano)", "Absceso isquiorrectal (más profundo, en el espacio graso junto al recto)", "Absceso interesfintérico (entre los músculos del esfínter anal)"], note: "" }, causes: { title: "Causas", intro: "El origen es casi siempre infeccioso:", items: ["Infección de una cripta o glándula anal bloqueada (la causa más frecuente)", "Fisura anal infectada", "Enfermedades de Transmisión Sexual (ETS)", "Enfermedad inflamatoria intestinal, como la enfermedad de Crohn"] }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico clínico es generalmente obvio en consulta:", items: ["Examen físico visual y palpación de la región perianal (a menudo no se hace tacto rectal si el dolor es extremo hasta sedar al paciente)", "Ecografía endoanal o Resonancia Magnética (solo en casos donde el absceso es muy profundo y no se ve en la superficie, o para evaluar trayectos fistulosos)"], note: "" }, treatment: { title: "Drenaje Quirúrgico", intro: "Los antibióticos por sí solos no curan un absceso; el pus debe salir:", subsections: [ { title: "Intervenciones", items: ["Drenaje quirúrgico urgente (el tratamiento estándar: el cirujano hace una incisión bajo anestesia local o general para vaciar el pus y limpiar la cavidad)", "Antibióticos (se recetan después del drenaje solo si hay fiebre, celulitis extensa, o el paciente tiene diabetes/inmunidad baja)", "Baños de asiento tibios y analgésicos para el dolor postoperatorio"] } ], note: "Cerca del 50% de los abscesos anales desarrollarán posteriormente una fístula anal que requerirá una segunda cirugía." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "No esperes a que estalle solo. Ve al médico o a urgencias de inmediato si:", items: ["Sientes un bulto muy doloroso y caliente junto al ano que te impide sentarte o caminar", "Tienes fiebre, escalofríos y sudoración nocturna acompañando el dolor anal", "Observas salida de pus abundante o sangrado anal continuo"] } },
'Enfermedad celíaca (esprúe)' : { intro: "La enfermedad celíaca, o esprúe celíaco, es una enfermedad digestiva autoinmune grave que daña el intestino delgado e interfiere con la absorción de nutrientes de los alimentos cuando la persona consume gluten (una proteína presente en el trigo, cebada y centeno).", whatIs: { title: "¿Qué es la Enfermedad Celíaca?", text: "No es una simple alergia o intolerancia alimentaria, es una afección autoinmune. Cuando un celíaco ingiere gluten, su sistema inmunológico reacciona atacando y destruyendo las vellosidades microscópicas (vellosidades intestinales) que recubren el intestino delgado, impidiendo la absorción de vitaminas, minerales y nutrientes esenciales." }, types: { title: "Formas de Presentación", intro: "Los síntomas varían enormemente, y algunos pacientes no tienen síntomas digestivos:", items: ["Celíaca clásica (síntomas digestivos graves como diarrea crónica, pérdida de peso, dolor abdominal)", "Celíaca no clásica (síntomas extraintestinales como anemia severa crónica, osteoporosis prematura, fatiga extrema o infertilidad)", "Celíaca asintomática o silente (el daño intestinal ocurre sin síntomas evidentes, detectada por análisis de familiares)"], note: "A menudo se asocia con una erupción cutánea crónica y con mucha picazón llamada dermatitis herpetiforme." }, diagnosis: { title: "Pruebas de Sangre y Endoscopia", intro: "Para que el diagnóstico sea válido, el paciente DEBE estar consumiendo gluten de forma regular durante las pruebas:", items: ["Análisis de sangre (prueba de anticuerpos antitransglutaminasa tisular (tTG-IgA), que suelen estar muy elevados en celíacos activos)", "Endoscopia digestiva alta con biopsia del duodeno (el estándar de oro definitivo; el gastroenterólogo toma muestras del intestino delgado para observar bajo el microscopio la destrucción de las vellosidades)", "Pruebas genéticas (HLA-DQ2 y HLA-DQ8, usadas para descartar la enfermedad si salen negativas)"], note: "Nunca inicies una dieta sin gluten antes de hacerte las pruebas médicas, ya que falseará los resultados de los análisis." }, treatment: { title: "Dieta Estricta de por Vida", intro: "La única cura y tratamiento existente es la dieta:", subsections: [ { title: "Manejo Nutricional", items: ["Dieta 100% libre de gluten de por vida (eliminar completamente trigo, cebada, centeno, avena contaminada y cualquier alimento procesado que contenga trazas)", "Suplementación vitamínica intensiva inicial (para corregir deficiencias graves de hierro, calcio, vitamina D y B12 debido a la malabsorción pasada)", "Educación nutricional experta para evitar la contaminación cruzada en la cocina y restaurantes"] } ], note: "Con una dieta estricta sin gluten, el intestino delgado suele curarse por completo y las vellosidades vuelven a crecer en unos meses o años." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Es fundamental buscar evaluación especializada en digestivo si:", items: ["Sufres de diarrea crónica, dolor abdominal, o heces pálidas, grasosas y malolientes que flotan", "Padeces de anemia por falta de hierro que no se explica o no mejora con pastillas de hierro", "Tienes una pérdida de peso involuntaria importante, fatiga crónica o, en el caso de los niños, un retraso significativo en el crecimiento o la talla", "Aparece una erupción cutánea muy pruriginosa con pequeñas ampollas en codos y rodillas (dermatitis herpetiforme)"] }, causes: { title: "Causas", intro: "Es una enfermedad de origen genético desencadenada por el entorno:", items: ["Predisposición genética (presencia de genes HLA-DQ2 o DQ8)", "Ingesta de gluten (el desencadenante ambiental necesario)", "Factores ambientales adicionales (infecciones gastrointestinales severas o estrés físico extremo pueden activar la enfermedad en personas genéticamente predispuestas)"] } },
'Cáncer de cabeza y cuello' : { intro: "El cáncer de cabeza y cuello es un grupo de cánceres que generalmente comienzan en las células escamosas que recubren las superficies húmedas del interior de la cabeza y el cuello, como la boca, la nariz, la garganta y la laringe.", whatIs: { title: "¿Qué es este Cáncer?", text: "Se trata de tumores malignos que surgen en el tracto aerodigestivo superior. Estos cánceres son muy destructivos localmente y pueden afectar gravemente funciones vitales y cotidianas como respirar, tragar, hablar e incluso la apariencia del rostro." }, symptoms: { title: "Síntomas Persistentes", intro: "Los síntomas a menudo imitan dolencias comunes pero no desaparecen:", groups: [ { name: "Señales de Alarma", items: ["Una llaga o úlcera en la boca o en la lengua que no sana en más de 3 semanas", "Un bulto o masa indolora en el cuello que crece lentamente", "Dolor de garganta crónico, ronquera persistente o cambios en la voz", "Dificultad o dolor extremo al tragar (disfagia)", "Sangrado inusual por la nariz o la boca, o dolor crónico en un solo oído"] } ], warning: "Cualquier ronquera que dure más de un mes en un fumador requiere una evaluación de las cuerdas vocales con urgencia." }, types: { title: "Localización del Tumor", intro: "Se clasifican según el lugar donde se originan:", items: ["Cáncer de cavidad oral (labios, lengua, encías, paladar)", "Cáncer de faringe (garganta, amígdalas, base de la lengua)", "Cáncer de laringe (caja de la voz o cuerdas vocales)", "Cáncer de senos paranasales y cavidad nasal", "Cáncer de glándulas salivales"], note: "" }, causes: { title: "Factores de Riesgo Principales", intro: "El riesgo está fuertemente vinculado a hábitos y virus:", items: ["Uso de tabaco (fumar cigarrillos, puros, pipa o mascar tabaco es el factor de riesgo más importante)", "Consumo excesivo de alcohol (el uso combinado de alcohol y tabaco multiplica el riesgo enormemente)", "Infección por el Virus del Papiloma Humano (VPH) (causa principal del cáncer orofaríngeo en personas jóvenes no fumadoras)", "Exposición ocupacional a polvos de madera, asbesto o químicos"] }, diagnosis: { title: "Evaluación y Biopsia", intro: "El otorrinolaringólogo o cirujano maxilofacial realizará:", items: ["Endoscopia o Laringoscopia (un tubo delgado con luz y cámara para observar la garganta, laringe y cuerdas vocales)", "Biopsia (extracción de una muestra de tejido del tumor o del ganglio del cuello para confirmar si hay células cancerosas bajo el microscopio)", "Pruebas de imagen (TC, RM o PET scan para estadificar el cáncer y ver si ha invadido huesos maxilares o hecho metástasis)"], note: "" }, treatment: { title: "Tratamiento Oncológico", intro: "El tratamiento es agresivo para preservar la función:", subsections: [ { title: "Terapias Intervencionistas", items: ["Cirugía oncológica (para extirpar el tumor y los ganglios linfáticos del cuello; a veces requiere cirugía reconstructiva facial compleja)", "Radioterapia (uso de rayos de alta energía, a menudo la terapia principal para el cáncer de laringe temprano para preservar la voz)", "Quimioterapia (generalmente combinada con radiación en etapas avanzadas)", "Terapia dirigida e Inmunoterapia (para cánceres que se han propagado o reaparecido)"] } ], note: "La rehabilitación postoperatoria con logopedas y nutricionistas es esencial si se afecta la capacidad de tragar o hablar." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico especialista?", intro: "No ignores los síntomas. Pide cita si presentas:", items: ["Un bulto en el cuello que dura más de dos semanas y no duele", "Una llaga blanca o roja en las encías o lengua que no cicatriza en 15 días", "Sensación constante de tener algo atorado en la garganta o dolor agudo que irradia hacia un oído al intentar tragar"] } },
'Intolerancia al gluten' : { intro: "La intolerancia al gluten, médicamente conocida como Sensibilidad al Gluten No Celíaca (SGNC), es una afección en la que las personas experimentan síntomas intestinales y extraintestinales tras consumir gluten, pero sin tener enfermedad celíaca ni alergia al trigo.", whatIs: { title: "¿Qué es la Sensibilidad al Gluten No Celíaca?", text: "Es un síndrome donde la ingesta de gluten (una proteína presente en el trigo, cebada y centeno) desencadena síntomas similares a los de la celiaquía (como hinchazón, diarrea y fatiga cerebral), pero sin que exista un daño autoinmune al revestimiento del intestino delgado (vellosidades) y sin respuesta alérgica letal." }, types: { title: "Diferenciación Clínica", intro: "Es fundamental no confundirla con patologías más graves:", items: ["Difiere de la Enfermedad Celíaca (donde el gluten destruye permanentemente el intestino delgado y causa malabsorción severa)", "Difiere de la Alergia al Trigo (una reacción inmediata y potencialmente mortal mediada por anticuerpos IgE que afecta la respiración)"], note: "Actualmente se investiga si el culpable es realmente el gluten, o si son otros carbohidratos fermentables en el trigo (FODMAPs)." }, causes: { title: "Causas", intro: "El origen biológico es desconocido, pero se postula que:", items: ["No es una respuesta autoinmune", "Puede ser una reacción a los inhibidores de amilasa-tripsina (ATIs) presentes en el trigo", "Podría estar vinculada a una intolerancia general a los carbohidratos fermentables (FODMAPs)"] }, diagnosis: { title: "Diagnóstico por Exclusión", intro: "No existe ninguna prueba de sangre, genética o biopsia que diagnostique esta sensibilidad; se diagnostica descartando lo demás:", items: ["Pruebas para Enfermedad Celíaca (análisis de sangre tTG-IgA y endoscopia/biopsia intestinal, que deben resultar negativas)", "Pruebas de alergia al trigo (que deben resultar negativas)", "Dieta de eliminación y reintroducción (el diagnóstico se confirma si los síntomas desaparecen al quitar el gluten estrictamente y regresan de forma evidente al reintroducirlo)"], note: "Es vital NO dejar de comer gluten antes de realizarse las pruebas de celiaquía, ya que esto arrojará falsos negativos peligrosos." }, treatment: { title: "Manejo Dietético", intro: "El único tratamiento eficaz es ajustar la alimentación:", subsections: [ { title: "Estrategias de Vida", items: ["Dieta libre de gluten o reducida en gluten (eliminando panes, pastas, cervezas y alimentos procesados que contengan trigo, cebada o centeno)", "A diferencia del celíaco, el paciente con intolerancia al gluten a menudo puede tolerar pequeñas trazas o la contaminación cruzada sin sufrir daños graves", "Consulta con un nutricionista dietista para asegurar una ingesta adecuada de fibra y vitaminas del grupo B"] } ], note: "Muchos pacientes notan mejoras asombrosas en su 'niebla mental' y fatiga crónica al suspender el trigo." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico digestivo?", intro: "Debes buscar evaluación médica formal antes de iniciar cualquier dieta si:", items: ["Sufres dolor de estómago, gases excesivos y diarrea cada vez que comes pan o pastas", "Sientes una fatiga extrema inexplicable, dolor en las articulaciones y dolores de cabeza constantes relacionados con tus comidas", "Tienes antecedentes familiares de enfermedad celíaca y quieres asegurarte de no padecerla antes de cambiar tu dieta"] }, symptoms: { title: "Síntomas", intro: "Afecta el sistema digestivo y el estado general:", groups: [ { name: "Manifestaciones", items: ["Dolor abdominal, hinchazón severa (gases) y diarrea o estreñimiento", "Fatiga letárgica y 'niebla mental' (dificultad para concentrarse)", "Dolor en las articulaciones y dolor de cabeza", "Erupciones cutáneas leves"] } ], warning: "Nunca autodiagnostiques la intolerancia al gluten sin descartar antes la enfermedad celíaca con un médico." } },
'Juanetes' : { intro: "Un juanete, conocido médicamente como hallux valgus, es una protuberancia ósea dolorosa y anormal que se forma en la articulación de la base del dedo gordo del pie. Esta deformidad altera la estructura del pie y dificulta el uso de calzado normal.", whatIs: { title: "¿Qué es un Juanete?", text: "Se produce cuando algunos de los huesos de la parte frontal del pie se salen de su lugar. Esto hace que el dedo gordo del pie se doble y apunte bruscamente hacia los dedos más pequeños, forzando a la articulación en la base del dedo gordo a sobresalir, formando un bulto óseo duro, rojo y doloroso." }, types: { title: "Condiciones Relacionadas", intro: "Existen variantes de esta deformidad:", items: ["Hallux Valgus o Juanete clásico (en el dedo gordo del pie)", "Juanete de sastre o juanetillo (una protuberancia similar que se desarrolla en la base del dedo pequeño o quinto dedo del pie)", "Juanetes en adolescentes (menos dolorosos pero con fuerte componente genético familiar)"], note: "Suelen progresar y empeorar con el tiempo si no se corrigen o se sigue usando calzado dañino." }, causes: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de un juanete es multifactorial:", items: ["Estructura o tipo de pie heredado (genética)", "Uso de zapatos apretados, demasiado estrechos o con tacones altos (que empujan los dedos hacia una forma puntiaguda antinatural)", "Artritis reumatoide (condición inflamatoria de las articulaciones)", "Forma de caminar o estrés constante en el pie"] }, diagnosis: { title: "Evaluación Ortopédica", intro: "El diagnóstico es visual y radiológico:", items: ["Examen físico del pie (el médico observará la deformidad, enrojecimiento y evaluará el rango de movimiento de la articulación del dedo)", "Radiografías del pie tomadas mientras el paciente está de pie soportando peso (esenciales para medir los ángulos de desviación de los huesos y planificar una posible cirugía)"], note: "" }, treatment: { title: "Manejo Conservador y Cirugía", intro: "El tratamiento va desde el alivio del calzado hasta la reconstrucción ósea:", subsections: [ { title: "Opciones Terapéuticas", items: ["Cambios en el calzado (usar zapatos anchos y cómodos con suficiente espacio para los dedos, evitando tacones)", "Almohadillas protectoras para juanetes y separadores de dedos de venta libre para evitar el roce", "Soportes para el arco del pie o plantillas ortopédicas personalizadas (para distribuir la presión de forma uniforme)", "Medicamentos antiinflamatorios (AINEs) y aplicación de hielo para episodios de dolor agudo", "Cirugía ortopédica o bunionectomía (el único método que elimina el juanete realineando quirúrgicamente los huesos, tendones y nervios; reservado para dolor severo e incapacitante)"] } ], note: "La cirugía requiere una recuperación larga, a menudo semanas sin apoyar el pie o con botas ortopédicas." }, whenToSeekHelp: { title: "¿Cuándo consultar a un traumatólogo o podólogo?", intro: "Es recomendable buscar atención especializada si:", items: ["El bulto en la base del dedo gordo es muy doloroso y te impide caminar o realizar tus actividades normales", "El dedo gordo se superpone, cruza o aplasta a los otros dedos del pie", "Ya no encuentras ningún zapato que te quede bien o que no te cause un dolor insoportable", "Presentas enrojecimiento extremo, calor o hinchazón en la articulación (que podría indicar gota o infección)"] }, symptoms: { title: "Síntomas", intro: "Los signos son visuales y dolorosos:", groups: [ { name: "Características", items: ["Un bulto abultado y duro en el exterior de la base del dedo gordo del pie", "Enrojecimiento, hinchazón o dolor profundo alrededor de la articulación", "Callos o callosidades donde el primer y segundo dedo se rozan entre sí", "Dolor continuo o dolor intermitente agudo al caminar o usar zapatos", "Rango de movimiento limitado en el dedo gordo del pie"] } ], warning: "Ignorar un juanete severo puede llevar a bursitis, dedos en martillo y deformidad permanente de todo el pie." } },
'Infección del oído' : { intro: "Una infección de oído (a menudo otitis media aguda) es una inflamación dolorosa del oído medio, el espacio lleno de aire detrás del tímpano que contiene los diminutos huesos vibratorios del oído. Es la principal razón por la que los padres llevan a sus hijos al médico.", whatIs: { title: "¿Qué es una Infección del Oído?", text: "Es una afección en la que bacterias o virus infectan y atrapan líquido detrás del tímpano. Esto suele ocurrir cuando la trompa de Eustaquio (el canal que drena el oído hacia la garganta) se hincha y se bloquea debido a un resfriado, una alergia o una infección sinusal, provocando acumulación de pus y presión dolorosa." }, types: { title: "Variantes de Otitis", intro: "Se divide según la parte afectada y la presencia de líquido:", items: ["Otitis media aguda (OMA) (infección rápida y dolorosa con pus detrás del tímpano)", "Otitis media con derrame (el líquido se queda atrapado en el oído medio sin infección bacteriana activa, a menudo tras curarse una OMA, causando sordera temporal)", "Otitis externa o 'oído de nadador' (infección en el canal auditivo externo, desde el tímpano hacia fuera, causada por humedad atrapada o bacterias en el agua)"], note: "Las infecciones del oído medio son mucho más comunes en niños debido a que sus trompas de Eustaquio son más estrechas y horizontales." }, diagnosis: { title: "Examen Clínico", intro: "El diagnóstico es visual mediante herramientas de consultorio:", items: ["Otoscopia (el médico usa un instrumento con luz para mirar directamente el tímpano; si está rojo, abultado o tiene pus detrás, indica infección aguda)", "Timpanometría (un pequeño dispositivo que sella el canal auditivo y mide cómo se mueve el tímpano en respuesta a cambios de presión del aire; detecta líquido atrapado)", "Prueba de audición (audiometría) en niños que han tenido infecciones crónicas recurrentes o líquido durante meses"], note: "" }, treatment: { title: "Manejo de Dolor y Antibióticos", intro: "El tratamiento depende de la edad, la gravedad y el origen (viral o bacteriano):", subsections: [ { title: "Rutas Terapéuticas", items: ["Manejo del dolor (es la prioridad inmediata: ibuprofeno o paracetamol, y compresas tibias sobre la oreja; el dolor intenso suele preceder a la rotura del tímpano)", "Enfoque de 'esperar y ver' (en niños mayores de 2 años con síntomas leves, se espera 48 horas sin antibióticos, ya que el sistema inmune elimina la mayoría de las infecciones virales por sí solo)", "Antibióticos orales (amoxicilina es la primera opción para infecciones bacterianas graves, fiebre alta o en bebés menores de 6 meses)", "Gotas antibióticas para los oídos (usadas exclusivamente para la otitis externa o si hay tubos de ventilación)", "Tubos de timpanostomía (cirugía menor para insertar pequeños tubos de drenaje en el tímpano en niños con infecciones constantes que dañan su audición y desarrollo del habla)"] } ], note: "Nunca uses hisopos de algodón para limpiar los oídos; empujan la cera y las bacterias hacia el tímpano, aumentando el riesgo de infección." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia al médico?", intro: "Acude a tu pediatra o a urgencias rápidamente si observas:", items: ["El dolor de oído es súbito, extremadamente severo e insoportable", "El niño está letárgico, no deja de llorar de manera irritable y constante, o presenta fiebre de 39 °C o más", "Notas salida de pus visible, líquido amarillento o sangrado drenando fuera de la oreja (signo de que el tímpano se ha perforado por la presión)", "El niño pequeño no reacciona a los sonidos o parece tener pérdida de audición", "En adultos, si el dolor se acompaña de hinchazón roja detrás de la oreja o rigidez en el cuello"] }, symptoms: { title: "Síntomas", intro: "Los síntomas varían entre adultos y niños:", groups: [ { name: "En Bebés y Niños Pequeños", items: ["Llorar más de lo normal, irritabilidad y dificultad para dormir", "Tirarse, frotarse o agarrarse constantemente de las orejas", "Fiebre y pérdida de apetito", "Pus o líquido drenando del oído"] }, { name: "En Adultos", items: ["Dolor punzante de oído", "Sensación de presión o bloqueo", "Pérdida temporal de audición y zumbidos"] } ], warning: "La fiebre alta en un bebé menor de 3 meses siempre es una emergencia hospitalaria." }, causes: { title: "Causas", intro: "Principalmente obstrucciones anatómicas e infecciones:", items: ["Resfriados comunes y gripe (inflaman las trompas de Eustaquio)", "Bacterias como Streptococcus pneumoniae y Haemophilus influenzae", "Alergias severas o humo de segunda mano (tabaco)", "Alimentación con biberón mientras el bebé está acostado boca arriba"] } },
'Presbicia' : { intro: "La presbicia, comúnmente llamada vista cansada, es la pérdida gradual y natural de la capacidad de los ojos para enfocar activamente en objetos cercanos. Es una parte normal e inevitable del envejecimiento que se hace evidente habitualmente entre los 40 y 45 años de edad.", whatIs: { title: "¿Qué es la Presbicia?", text: "Es una condición fisiológica relacionada con la edad. En un ojo joven, el cristalino (la lente natural dentro del ojo) es flexible y cambia de forma para enfocar de cerca o de lejos. Con la edad, el cristalino se endurece, se vuelve rígido y los músculos que lo controlan se debilitan, haciendo imposible enfocar nítidamente letras pequeñas o labores de cerca." }, types: { title: "Diferencia con otros defectos", intro: "No debe confundirse con otras condiciones refractivas:", items: ["Difiere de la hipermetropía (la hipermetropía es un ojo demasiado corto desde el nacimiento, la presbicia es un cristalino rígido por la edad)", "Suele combinarse (puedes ser miope para ver de lejos y, al cumplir 45 años, desarrollar presbicia para ver de cerca, requiriendo lentes bifocales o progresivos)"], note: "Afecta absolutamente a todas las personas en el mundo a medida que envejecen, sin excepción." }, causes: { title: "Causas", intro: "Su origen es puramente biológico y degenerativo:", items: ["Endurecimiento paulatino y pérdida de flexibilidad del cristalino del ojo debido a los años", "Debilitamiento del músculo ciliar que comprime el cristalino", "Uso de ciertos medicamentos como antidepresivos o antihistamínicos (pueden precipitar síntomas tempranos)"] }, diagnosis: { title: "Examen Optométrico", intro: "Se diagnostica fácilmente con un examen ocular de rutina:", items: ["Examen básico de agudeza visual y refracción (lectura de una tabla a distancia y lectura de un texto a 30 centímetros de la cara)", "Examen oftalmológico completo con dilatación pupilar (para descartar otras enfermedades de la vejez como glaucoma, cataratas o degeneración macular)"], note: "Es aconsejable que todos los adultos se realicen un examen ocular completo de base a los 40 años." }, treatment: { title: "Corrección Óptica y Opciones Quirúrgicas", intro: "No se puede curar ni revertir, pero es muy fácil de corregir:", subsections: [ { title: "Herramientas de Corrección", items: ["Anteojos de lectura simples de venta libre (gafas de farmacia para personas que no tienen otros problemas de visión)", "Lentes graduados bifocales o progresivos (la solución ideal si el paciente ya usa gafas para miopía o astigmatismo; integran la graduación de lejos y de cerca en el mismo cristal)", "Lentes de contacto multifocales o monovisión (un ojo ajustado para lejos y otro para cerca)", "Cirugía refractiva (LASIK para monovisión) o cirugía de implante de lentes intraoculares multifocales (generalmente recomendada si la persona ya necesita operarse de cataratas)"] } ], note: "Leer con poca luz no 'daña' los ojos de forma permanente, pero sí causa un agotamiento y dolor de cabeza mucho mayor." }, whenToSeekHelp: { title: "¿Cuándo acudir al oftalmólogo u optometrista?", intro: "Programa una revisión ocular si:", items: ["Descubres que instintivamente alejas el teléfono celular o los libros estirando los brazos al máximo para poder leerlos claramente ('síndrome de los brazos cortos')", "Sufres frecuentes dolores de cabeza, dolor ocular o cansancio extremo y fatiga visual (astenopía) después de leer, coser o trabajar en la computadora", "Tu visión borrosa de cerca te impide leer menús de restaurantes, etiquetas de medicamentos o realizar tu trabajo cómodamente"] }, symptoms: { title: "Síntomas", intro: "Los primeros signos aparecen al leer:", groups: [ { name: "Problemas Visuales de Cerca", items: ["Visión borrosa al leer letras a una distancia normal de lectura (30-40 cm)", "Tendencia a alejar el material de lectura (estirar los brazos) para aclarar las letras", "Cansancio ocular extremo, ardor o dolor de cabeza tras realizar trabajos minuciosos de cerca", "Necesidad de luz más brillante de lo normal para poder leer"] } ], warning: "La pérdida súbita de la visión o la visión doble no son síntomas de presbicia y requieren atención médica de emergencia." } },
'Fistula dental o en encía' : { intro: "Una fístula dental, o fístula en la encía (parulis), es un pequeño bulto o grano parecido a una espinilla que se forma en la superficie de la encía. Es un canal de drenaje biológico creado por el cuerpo para liberar el pus producido por una infección grave en la raíz de un diente profundo.", whatIs: { title: "¿Qué es una Fístula Dental?", text: "Es una vía de escape. Cuando una caries muy profunda o un golpe matan el nervio del diente, se forma un absceso purulento en el hueso maxilar (en la punta de la raíz). Al acumularse, la presión extrema busca una salida, perforando el hueso y la encía para drenar el pus tóxico hacia la boca, creando un pequeño túnel o fístula." }, types: { title: "Origen de la Infección", intro: "El absceso que causa la fístula puede originarse por dos vías:", items: ["Origen endodóntico o periapical (infección en el nervio y raíz del diente por caries o trauma; es la causa más común)", "Origen periodontal (infección originada en las bolsas de las encías por piorrea o enfermedad periodontal avanzada, sin que el nervio del diente esté muerto)"], note: "La presencia de la fístula a menudo alivia el dolor intenso, ya que el pus se drena y libera la presión atrapada en el hueso, engañando al paciente de que 'ya se curó'." }, causes: { title: "Causas Principales", intro: "Siempre es indicativo de una infección bacteriana viva:", items: ["Caries dental extensa y no tratada que penetra hasta la pulpa nerviosa", "Muerte del nervio dental (necrosis pulpar) secundaria a un fuerte golpe en el diente (trauma)", "Tratamientos de conducto (endodoncias) antiguos que han fracasado y se han reinfectado", "Enfermedad periodontal severa (periodontitis)"] }, diagnosis: { title: "Examen Dental Radiográfico", intro: "El dentista diagnosticará la causa exacta rastreando el origen:", items: ["Examen visual clínico de la encía (observando el pequeño bulto rojo o amarillento supurante)", "Radiografía periapical (fundamental; mostrará una mancha oscura -pérdida de hueso y absceso- en la raíz del diente responsable)", "Fistulografía con gutapercha (el dentista introduce suavemente un pequeño e indoloro cono de goma dentro del granito de la encía y toma una radiografía; el cono trazará el camino exacto hasta la raíz del diente culpable, indicando cuál tratar)"], note: "" }, treatment: { title: "Eliminación de la Infección (Endodoncia)", intro: "Los antibióticos NO curan una fístula dental; solo calman temporalmente. El diente debe ser tratado:", subsections: [ { title: "Tratamientos Definitivos", items: ["Tratamiento de conductos o Endodoncia (el dentista limpia, desinfecta y sella el interior del diente muerto y sus raíces; la fístula de la encía desaparecerá sola en pocos días una vez eliminada la causa)", "Re-tratamiento de conductos o Cirugía apical (si un diente ya endodonciado falla y se infecta de nuevo)", "Extracción del diente (si la pieza dental está tan destruida por la caries que no se puede salvar ni reconstruir)", "Drenaje del absceso y limpieza periodontal profunda (si la infección es puramente de las encías)"] } ], note: "NUNCA debes pinchar, apretar o reventar el granito de la encía con agujas caseras, podrías causar una infección peligrosa." }, whenToSeekHelp: { title: "¿Cuándo pedir cita de urgencia al dentista?", intro: "Es estrictamente necesario acudir a una clínica dental si:", items: ["Observas un pequeño bulto parecido a una espinilla en la encía, especialmente si supura un líquido de mal sabor (incluso si no te duele nada)", "Sufres de un dolor de muelas agudo, palpitante e intenso", "Presentas hinchazón severa en un lado de la cara, el cuello o la mandíbula inferior", "Aparece fiebre alta, dificultad repentina para tragar o problemas para respirar (infección sistémica severa, acude a un hospital)"] }, symptoms: { title: "Síntomas", intro: "Los síntomas abarcan la encía y el diente asociado:", groups: [ { name: "Señales", items: ["Un pequeño bulto inflamado, a menudo rojo o amarillo, en las encías", "Mal sabor de boca persistente y mal aliento (debido al pus que se drena lentamente en la boca)", "Dolor al masticar o al golpear ligeramente el diente afectado", "Sensación de que el diente está 'más alto' o se mueve ligeramente", "El dolor agudo de muelas suele desaparecer de golpe en el momento en que la fístula revienta y drena la presión"] } ], warning: "La desaparición del dolor no indica curación; el hueso de tu mandíbula seguirá infectándose y disolviéndose hasta que un dentista limpie la raíz." } },
'Hipercolesterolemia familiar' : { intro: "La hipercolesterolemia familiar (HF) es un grave trastorno genético heredado que causa niveles anormal y peligrosamente altos de lipoproteína de baja densidad (colesterol LDL, el colesterol 'malo') desde el nacimiento y a lo largo de toda la vida, aumentando drásticamente el riesgo de enfermedad cardíaca temprana.", whatIs: { title: "¿Qué es la Hipercolesterolemia Familiar?", text: "A diferencia del colesterol alto común asociado a malas dietas u obesidad, la HF es una mutación en los genes. El cuerpo carece de los receptores adecuados en el hígado para captar y eliminar el colesterol LDL de la sangre. En consecuencia, el colesterol tóxico se acumula en las arterias desde la infancia, causando aterosclerosis, angina e infartos mortales a edades muy jóvenes (30, 40 o 50 años)." }, types: { title: "Clasificación Genética de Severidad", intro: "Se clasifica dependiendo de si el individuo heredó el gen mutado de uno o de ambos padres:", items: ["HF Heterocigota (HeFH) (la forma más común, 1 en 250 personas; se hereda el gen de solo un padre. Los niveles de LDL oscilan entre 190 y 400 mg/dL. Los infartos ocurren a menudo entre los 30 y 50 años si no se trata)", "HF Homocigota (HoFH) (forma extremadamente rara y letal; se hereda el gen mutado de ambos padres. Los niveles de LDL superan los 500 o incluso 1000 mg/dL. Sin un tratamiento masivo como un trasplante de hígado, los infartos y enfermedades cardíacas fatales ocurren en la niñez o adolescencia)"], note: "Una persona con HF tiene 20 veces más probabilidades de desarrollar enfermedad coronaria prematura que la población general." }, causes: { title: "Causas y Herencia", intro: "El origen es puramente genético:", items: ["Mutaciones en los genes LDLR, APOB o PCSK9", "Es una afección autosómica dominante (si uno de tus padres la tiene, tienes un 50% de probabilidades de heredarla)", "Ninguna cantidad de dieta, veganismo o ejercicio intenso podrá curar o bajar a niveles normales el colesterol de alguien con HF genética sin el uso de medicación fuerte"] }, diagnosis: { title: "Diagnóstico Clínico y Genético", intro: "La detección temprana pediátrica salva vidas:", items: ["Perfil lipídico sanguíneo (hallazgo de niveles de LDL superiores a 190 mg/dL en adultos o mayores a 160 mg/dL en niños)", "Historial familiar exhaustivo (es el mayor indicador; el médico buscará un historial de padres, tíos o abuelos que sufrieron infartos o muerte súbita antes de los 55 años en hombres o 65 en mujeres)", "Examen físico buscando xantomas o arco corneal en jóvenes", "Pruebas genéticas de ADN (confirman definitivamente la mutación y permiten detectar a otros familiares afectados - cribado en cascada)"], note: "" }, treatment: { title: "Tratamiento Médico Agresivo", intro: "Requiere medicamentos potentes de por vida para bajar el LDL y proteger las arterias:", subsections: [ { title: "Intervenciones Farmacológicas", items: ["Estatinas en dosis muy altas (Atorvastatina, Rosuvastatina) como primera y principal línea de defensa, usadas desde la infancia o adolescencia", "Ezetimiba (fármaco que impide la absorción del colesterol en el intestino, añadido a las estatinas)", "Inhibidores de la PCSK9 (Evolocumab o Alirocumab; revolucionarias inyecciones subcutáneas mensuales que logran descensos masivos del LDL en pacientes con HF que no responden a estatinas)", "Aféresis de LDL (un procedimiento similar a la diálisis donde una máquina limpia el colesterol directamente de la sangre cada pocas semanas, usado en HF Homocigota grave)"] } ], note: "Una dieta muy baja en grasas saturadas y hacer ejercicio son de apoyo obligatorio, pero insuficientes por sí solos." }, whenToSeekHelp: { title: "¿Cuándo exigir pruebas a tu médico?", intro: "No existen síntomas obvios. Debes realizarte un panel de colesterol, sin importar lo joven o delgado que seas, si:", items: ["Tienes familiares de primer grado (padres, hermanos, hijos) diagnosticados con hipercolesterolemia familiar", "En tu familia existen numerosos casos de infartos de miocardio, colocación de stents o muerte cardíaca súbita en personas jóvenes (hombres menores de 55 años o mujeres menores de 65 años)", "Tus análisis de sangre rutinarios muestran un colesterol LDL superior a 190 mg/dL", "Notas la aparición de depósitos abultados y amarillentos de grasa bajo la piel en los tendones de los nudillos de las manos, rodillas, o en el tendón de Aquiles en tus talones (xantomas)"] }, symptoms: { title: "Señales Físicas de Acumulación", intro: "Normalmente el colesterol alto es silencioso, pero la HF severa provoca depósitos visibles de colesterol debido a la saturación extrema:", groups: [ { name: "Signos Clínicos Exclusivos de HF", items: ["Xantomas tendinosos (nódulos duros e indoloros de colesterol depositados en el tendón de Aquiles, codos o nudillos de las manos)", "Xantelasmas (manchas planas y amarillentas de grasa bajo la piel de los párpados o alrededor de los ojos en personas jóvenes)", "Arco corneal (un anillo visible gris, blanco o blanquecino alrededor del iris coloreado del ojo; es normal en ancianos, pero en personas menores de 45 años indica fuertemente HF genética)", "Angina de pecho (dolor torácico por arterias estrechas) a una edad muy temprana"] } ], warning: "La aparición de xantomas en los tendones de un niño o joven es casi indicativo y patognomónico del diagnóstico de HF." } },
'Espondiloartropatía' : { intro: "Las espondiloartropatías (o espondiloartritis) son un grupo de enfermedades autoinmunes e inflamatorias graves de la familia de las artritis. Estas afecciones atacan principalmente la columna vertebral y las articulaciones sacroilíacas (donde la columna se une a la pelvis), causando dolor lumbar crónico y rigidez extrema.", whatIs: { title: "¿Qué es la Espondiloartropatía?", text: "A diferencia de la artritis reumatoide, que destruye las articulaciones pequeñas de las manos, la espondiloartritis provoca inflamación profunda (entesitis) en los lugares donde los ligamentos y tendones se adhieren al hueso, especialmente en la columna. Si no se trata con medicación agresiva, la inflamación crónica obliga al cuerpo a formar hueso nuevo de manera equivocada, fusionando y soldando las vértebras entre sí, creando una columna de 'caña de bambú' totalmente rígida." }, types: { title: "Enfermedades del Grupo", intro: "La familia de las espondiloartropatías abarca varias enfermedades relacionadas:", items: ["Espondilitis anquilosante (el subtipo principal y más común; afecta predominantemente la columna y articulaciones sacroilíacas en hombres jóvenes)", "Artritis psoriásica (inflamación articular destructiva que ocurre en personas que padecen psoriasis cutánea)", "Artritis reactiva (síndrome de Reiter; dolor articular y ocular que se dispara y comienza repentinamente tras una infección intestinal o una ETS como la clamidia)", "Artritis enteropática (asociada directamente a Enfermedades Inflamatorias Intestinales severas como Crohn o Colitis Ulcerosa)", "Espondiloartritis axial no radiográfica (existen los síntomas típicos y dolor, pero el daño de los huesos aún no es visible en las radiografías tradicionales)"], note: "Gran parte de los pacientes con estas enfermedades comparten un marcador genético sanguíneo común llamado HLA-B27." }, causes: { title: "Causas y Factores Genéticos", intro: "Se considera una enfermedad de origen inmunológico:", items: ["Genética (la presencia del gen HLA-B27 aumenta en gran medida el riesgo, aunque no todos los que lo tienen desarrollan la enfermedad)", "Fallo del sistema inmunitario (ataca los tejidos sanos articulares)", "Infecciones (bacterias estomacales o urinarias previas actúan como detonante en la artritis reactiva)"] }, diagnosis: { title: "Diagnóstico Reumatológico e Imágenes", intro: "El retraso en el diagnóstico es el mayor problema, a menudo de años. El reumatólogo utilizará:", items: ["Historia clínica identificando las características clásicas del 'dolor de espalda inflamatorio' (empeora en la noche/reposo y mejora con movimiento/AINEs)", "Resonancia Magnética (RM) de las articulaciones sacroilíacas (la prueba de oro moderna, capaz de detectar inflamación activa y edema óseo tempranamente, años antes de que se dañe el hueso)", "Radiografías de pelvis y columna (en etapas tardías muestran fusión ósea o daño en la articulación sacroilíaca - sacroileítis)", "Análisis de sangre genético para el marcador HLA-B27 y marcadores inflamatorios como la Proteína C Reactiva (PCR)"], note: "" }, treatment: { title: "Terapias Biológicas y Control Autoinmune", intro: "El objetivo es detener la inflamación en seco para prevenir la deformidad y la fusión de los huesos de la columna:", subsections: [ { title: "Tratamientos", items: ["AINEs a dosis altas (antiinflamatorios no esteroideos como Indometacina, Meloxicam o Naproxeno; son el primer escalón y muy eficaces en etapas tempranas)", "Terapias Biológicas avanzadas (inhibidores del TNF-alfa como Adalimumab, Infliximab, o inhibidores de IL-17; medicamentos inyectables revolucionarios que apagan moléculas del sistema inmune, frenando el avance de la enfermedad)", "Fármacos antirreumáticos (FARMEs como sulfasalazina o metotrexato, útiles para desinflamar extremidades como rodillas o muñecas, pero no para la columna)", "Fisioterapia diaria y estricta (realizar estiramientos y ejercicios posturales todos los días es médicamente indispensable para evitar que la columna se fusione en una postura encorvada)"] } ], note: "Fumar tabaco acelera y empeora masivamente el daño estructural y la fusión de los huesos en pacientes con espondiloartritis." }, whenToSeekHelp: { title: "¿Cuándo derivar o acudir al Reumatólogo?", intro: "Es crítico que un paciente joven con 'dolor de espalda' sea evaluado si presenta banderas rojas inflamatorias:", items: ["Tienes un dolor de espalda baja o en la zona de los glúteos que comenzó de manera gradual e insidiosa antes de cumplir los 40 años", "El dolor empeora por las mañanas, acompañado de una rigidez extrema en el cuerpo que dura más de 30 a 60 minutos, o te despierta sistemáticamente de madrugada forzándote a caminar", "El dolor y la rigidez de espalda MEJORAN notablemente al hacer ejercicio o actividad física, pero EMPEORAN drásticamente si te quedas sentado o en reposo", "Sufres de inflamaciones dolorosas en tendones (entesitis), clásicamente en el talón de Aquiles, o inflamación recurrente y aguda de un ojo rojo, lloroso y fotofóbico (uveítis)"] }, symptoms: { title: "Síntomas y Órganos Afectados", intro: "Los síntomas van más allá del dolor de espalda, pues es una afección sistémica:", groups: [ { name: "Manifestaciones Clínicas", items: ["Dolor lumbar, dolor alternante en las nalgas y rigidez severa por las mañanas (dolor de espalda inflamatorio)", "Inflamación asimétrica de grandes articulaciones periféricas (hinchazón en rodillas, tobillos o caderas)", "Entesitis (dolor punzante en la planta del pie -fascitis plantar- o en el tendón de Aquiles, donde el tendón se une al hueso)", "Dedo en salchicha o dactilitis (inflamación difusa y completa de un dedo entero de la mano o el pie)", "Uveítis (inflamación grave, muy dolorosa y roja de la capa media del ojo, sensible a la luz)", "Fatiga profunda, cansancio crónico y afecciones inflamatorias del intestino o psoriasis cutánea asociada"] } ], warning: "Si la columna se fusiona completamente en una posición flexionada, el paciente no podrá levantar la cabeza para mirar hacia adelante, y aumenta gravísimamente el riesgo de sufrir fracturas vertebrales en traumas menores." } },
'Insuficiencia renal' : { intro: "La insuficiencia renal es un término general que describe la condición médica grave en la cual los riñones pierden su capacidad de filtrar eficazmente los desechos, el exceso de líquidos y las toxinas de la sangre, lo que provoca que estos se acumulen en el cuerpo a niveles peligrosos.", whatIs: { title: "¿Qué es la Insuficiencia Renal?", text: "Es la pérdida de la función de los órganos vitales encargados de limpiar la sangre. Además de filtrar desechos, los riñones sanos regulan la presión arterial, equilibran electrolitos (sodio, potasio), promueven la salud ósea y estimulan la producción de glóbulos rojos. Cuando fallan, todas estas funciones colapsan sistémicamente." }, types: { title: "Categorías por Velocidad de Daño", intro: "La insuficiencia se presenta en dos formas radicalmente distintas en la práctica médica:", items: ["Insuficiencia (o Lesión) Renal Aguda (IRA/LRA): Es una falla repentina, aguda y súbita, ocurriendo en cuestión de horas o pocos días. Suele ser reversible si se trata la causa subyacente rápidamente de emergencia (común por deshidratación extrema, traumas, toxicidad o bloqueos por piedras).", "Enfermedad o Insuficiencia Renal Crónica (ERC): Es una pérdida gradual, progresiva, silenciosa e irreversible de la función renal durante meses o décadas. Su daño es permanente, y se divide en 5 etapas, siendo la última la Enfermedad Renal Terminal (ERT). Las causas principales son la Diabetes y la Hipertensión alta crónica."], note: "La fase crónica inicial no duele ni causa síntomas hasta que el daño renal supera el 80%." }, causes: { title: "Causas y Promotores de la Insuficiencia", intro: "Las causas difieren según sea aguda o crónica:", items: ["Causas crónicas comunes: Diabetes Mellitus (Nefropatía diabética, causa #1), Hipertensión arterial descontrolada, Enfermedad renal poliquística (genética) o Glomerulonefritis (autoinmune).", "Causas agudas comunes: Caída masiva de presión arterial (hemorragias, sepsis), medicamentos tóxicos nefrotóxicos (uso masivo de ibuprofeno, medios de contraste), u obstrucciones graves (próstata enorme o cálculos renales)."] }, diagnosis: { title: "Evaluación Médica y Laboratorial", intro: "Se detecta mediante pruebas sanguíneas y urinarias preventivas y diagnósticas:", items: ["Análisis de sangre para medir la Creatinina sérica (si el riñón no filtra, la creatinina de los músculos sube en la sangre) y calcular la eGFR (Tasa de Filtración Glomerular estimada).", "Análisis de orina (para detectar proteínas vitales como la albúmina que se escapan del filtro, o la presencia de sangre).", "Ecografía renal (muestra el tamaño del riñón: encogido en la enfermedad crónica, o inflamado/bloqueado en la aguda).", "Biopsia de riñón percutánea (para determinar enfermedades autoinmunes específicas que destruyen el glomérulo)."], note: "" }, treatment: { title: "Manejo, Prevención y Terapias de Reemplazo", intro: "El tratamiento difiere si es aguda (intentar curar) o crónica (retrasar avance y reemplazar función):", subsections: [ { title: "Abordajes Generales", items: ["Para insuficiencia crónica: Control estricto absoluto de la diabetes y la hipertensión, usando medicación protectora (IECA, ARA-II, inhibidores SGLT2) y dieta renal (baja en sodio, proteínas y potasio).", "Para insuficiencia aguda: Soporte intravenoso con fluidos, corrección urgente de potasio letal, suspender nefrotóxicos y resolver bloqueos.", "Tratamiento de complicaciones: Medicación para anemia (eritropoyetina), fijadores de fósforo y vitamina D para huesos.", "Terapias de reemplazo (cuando eGFR es menor a 15): Diálisis peritoneal o Hemodiálisis (máquina que filtra la sangre) o, la mejor opción final, un Trasplante de Riñón humano."] } ], note: "Nadie se 'cura' de una insuficiencia renal crónica; el objetivo es ganar tiempo y calidad de vida antes de requerir diálisis." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias nefróticas?", intro: "Debes buscar ayuda hospitalaria inmediata si presentas signos de uremia severa y fallo avanzado:", items: ["Hinchazón masiva, severa o repentina (edema) en tobillos, piernas o cara", "Falta de aire aguda, dificultad extrema para respirar o dolor en el pecho (por acumulación de líquidos en los pulmones o el corazón)", "Fatiga paralizante acompañada de náuseas, vómitos repetidos, asco a la comida o un fuerte sabor metálico u olor a amoníaco en la boca", "Picazón corporal intensa intratable, calambres musculares o disminución drástica e inexplicable en la cantidad de orina diaria"] }, symptoms: { title: "Síntomas (En Fases Avanzadas)", intro: "El cuerpo se intoxica sistémicamente al no poder depurarse:", groups: [ { name: "Signos Clínicos de Uremia", items: ["Retención de líquidos (pies, tobillos, piernas o rostro hinchados)", "Fatiga extrema, cansancio profundo, anemia letárgica y dificultad severa de concentración", "Orina muy espumosa (proteinuria), coloración muy oscura o cambios drásticos en la frecuencia urinaria nocturna", "Pérdida profunda de apetito, náuseas, vómitos y sabor metálico constante", "Picazón cutánea severa y calambres musculares"] } ], warning: "Un aumento drástico y no filtrado de los niveles de potasio en la sangre puede causar un paro cardíaco repentino y fatal." } },
'Insuficiencia aguda del riñón' : { intro: "La insuficiencia aguda del riñón, o Lesión Renal Aguda (LRA), es un episodio crítico y rápido en el cual los riñones pierden de manera repentina, en cuestión de horas o muy pocos días, su capacidad para filtrar productos de desecho y equilibrar los fluidos en la sangre.", whatIs: { title: "¿Qué es la Insuficiencia Aguda del Riñón?", text: "Es un fracaso brusco de los órganos de filtración, a menudo ocasionado por un evento extremo. A diferencia del fallo renal crónico (que tarda años), esta condición genera una emergencia médica en la que las toxinas y fluidos corporales suben a niveles letales rápidamente. Sin embargo, con tratamiento intensivo y rápido, suele ser reversible y los riñones pueden recuperar su funcionamiento normal." }, types: { title: "Causas y Orígenes del Fallo", intro: "Los médicos categorizan este fallo agudo por la ubicación anatómica del problema:", items: ["Causas Prerrenales (el problema está en la falta de flujo sanguíneo al riñón: hemorragia masiva, deshidratación extrema por vómitos/diarrea, shock sistémico o fallo cardíaco severo)", "Causas Intrínsecas o Renales (el daño directo está en el propio tejido del riñón: por el consumo de medicamentos altamente tóxicos como sobredosis de ibuprofeno (AINEs), toxinas de contraste radiológico, destrucción muscular por trauma severo (rabdomiólisis) o enfermedades autoinmunes de ataque rápido)", "Causas Posrenales u Obstructivas (el problema está 'después' del riñón, bloqueando la salida de la orina: hiperplasia benigna de próstata gigante, cálculos renales masivos bilaterales, tumores de vejiga o cáncer pélvico)"], note: "Esta condición ocurre frecuentemente como una complicación grave en personas que ya están hospitalizadas en la unidad de cuidados intensivos." }, diagnosis: { title: "Evaluación Hospitalaria Crítica", intro: "El diagnóstico debe ser sumamente veloz para detener la acumulación tóxica:", items: ["Exámenes de sangre de urgencia (muestran un pico altísimo y repentino de creatinina, nitrógeno ureico (BUN) y el peligrosísimo aumento de potasio en la sangre)", "Monitorización exhaustiva de la producción de orina (oliguria: orinar muy poco o absolutamente nada en 24 horas es una señal de advertencia vital)", "Análisis de orina y electrolitos (para descartar infección severa o destrucción de células)", "Ecografía o ultrasonido del riñón (la prueba de imagen principal, crucial para confirmar inmediatamente si hay un gran bloqueo físico urente en los uréteres o próstata)"], note: "" }, treatment: { title: "Soporte Vital y Recuperación", intro: "El tratamiento en el hospital o UCI se enfoca en tratar la causa exacta para 'encender' el riñón de nuevo y prevenir complicaciones fatales del corazón:", subsections: [ { title: "Estrategias de Salvamento", items: ["Fluidos intravenosos (IV) masivos y agresivos (si la causa fue deshidratación o baja presión arterial)", "Diuréticos recetados de alta potencia (si la causa es la acumulación tóxica de líquidos y edema pulmonar)", "Tratamiento de urgencia para el hiperpotasemia (uso de insulina, glucosa o calcio intravenoso para forzar al potasio a salir de la sangre, previniendo así una parada cardíaca inminente)", "Liberación de la obstrucción (colocación inmediata de una sonda Foley en la vejiga o cirugía urológica para retirar piedras que bloqueen los tubos)", "Diálisis temporal de urgencia (conectar al paciente a la máquina de filtrado de sangre (hemodiálisis) durante días o semanas hasta que el riñón inflamado se cure y vuelva a trabajar)"] } ], note: "Es vital retirar inmediatamente de la pauta del paciente todos los medicamentos potencialmente nefrotóxicos (antibióticos fuertes, AINEs)." }, whenToSeekHelp: { title: "¿Cuándo ir directamente a Urgencias Médicas?", intro: "La lesión renal aguda es una emergencia vital médica. Ve al hospital o llama al 911 si experimentas:", items: ["Disminución brusca, severa o paralización completa de tu capacidad para orinar durante un día o más", "Hinchazón generalizada y repentina y muy fuerte (edema de gran volumen en piernas, tobillos o hinchazón de la cara)", "Dificultad o asfixia muy aguda y dolorosa al respirar (indicativo del riñón dejando pasar agua al pulmón)", "Dolor y fuerte presión opresiva en el pecho, ritmo cardíaco irregular o arritmias", "Letargo extremo inexplicable, somnolencia muy profunda, desmayo, confusión mental total o presencia de convulsiones agudas"] }, symptoms: { title: "Síntomas Clave Agudos", intro: "Los síntomas aparecen rápidamente a medida que falla la filtración:", groups: [ { name: "Manifestaciones Físicas Graves", items: ["Oliguria o anuria (disminución del volumen de orina diario, aunque a veces el flujo es normal)", "Retención de líquidos o edemas periféricos y en pulmones", "Falta de aire aguda", "Fatiga paralizante y letargo mental", "Náuseas profundas e incapacidad de retener alimentos", "Dolor en el pecho o ritmo cardíaco anormal"] } ], warning: "La acumulación de potasio (hiperpotasemia) secundaria a un fallo renal agudo puede matar al paciente provocando un paro cardíaco sin dar otros síntomas antes." } },
'Enfermedad renal terminal' : { intro: "La Enfermedad Renal Terminal (ERT), o Insuficiencia Renal en Etapa Terminal (ESRD), es la última y definitiva fase de la enfermedad renal crónica. Ocurre cuando los riñones han sufrido un daño masivo, perdiendo aproximadamente entre el 85% y 90% de su capacidad para funcionar y filtrar.", whatIs: { title: "¿Qué es la Enfermedad Renal Terminal?", text: "Es el estadio 5 del daño renal. En esta fase irreversible, la filtración glomerular es casi nula y los riñones ya no pueden realizar sus tareas vitales de limpiar la sangre de toxinas (uremia), equilibrar los líquidos corporales ni fabricar hormonas. El cuerpo se envenena progresivamente a sí mismo. A partir de este momento, es imposible sobrevivir de forma natural, requiriendo terapia médica artificial o un órgano donado." }, types: { title: "Enfermedades Causantes", intro: "Es el colapso funcional final resultante de patologías previas destructivas no controladas a largo plazo:", items: ["Nefropatía Diabética (la principal y más predominante causa de ERT en el mundo, por años de niveles destructivos altos de azúcar)", "Hipertensión Arterial crónica severa y no tratada", "Glomerulonefritis (inflamación e injuria autoinmune a los filtros renales)", "Enfermedad renal poliquística (patología genética y hereditaria que llena el riñón de quistes que lo destruyen)", "Uso y abuso sistemático durante muchos años de medicamentos nefrotóxicos (ej. abuso abusivo prolongado de antiinflamatorios como ibuprofeno)"], note: "El paciente terminal a menudo sufre severamente complicaciones derivadas (como desnutrición uremica grave, anemia severa y daño severo en los huesos por falta de calcio y exceso de fósforo)." }, diagnosis: { title: "Evaluación Médica Clínica", intro: "El diagnóstico médico está pautado rígidamente por marcadores de sangre:", items: ["Prueba de Tasa de Filtración Glomerular Estimada o eGFR (el diagnóstico definitorio principal ocurre cuando la TFG cae y permanece permanentemente por debajo de los 15 ml/minuto)", "Niveles séricos tóxicos altos (acumulación y medición letal y alta de creatinina, nitrógeno ureico en sangre -BUN-, y potasio sérico)", "Exámenes adicionales preventivos (radiografías o ultrasonidos solo para determinar el estado atrófico cicatrizal del órgano restante)"], note: "" }, treatment: { title: "Terapias Vitales de Reemplazo Invasivo (TRS)", intro: "Los riñones no sanarán. Las únicas alternativas para mantener a la persona con vida son:", subsections: [ { title: "Modos de Tratamiento", items: ["Hemodiálisis por máquina clínica (el tratamiento más extendido; la sangre de las venas del paciente sale y es bombeada y limpiada a través de un enorme filtro mecánico artificial exterior, varias horas al día, 3 o más días por semana, usualmente usando un acceso en el brazo o fístula arteriovenosa)", "Diálisis Peritoneal domiciliaria (se introduce permanentemente un catéter blando en el abdomen del propio paciente; diariamente y en casa se instila líquido limpiador especial en la cavidad abdominal para que su propia membrana biológica -peritoneo- filtre las toxinas)", "Trasplante Renal de donante (el mejor tratamiento médico, el 'estándar de oro' curativo y de mayor libertad, que implica la cirugía mayor para recibir e implantar quirúrgicamente el riñón sano y vital de un familiar vivo o de un donante fallecido compatible)", "Tratamiento o manejo médico conservador (usado por ancianos frágiles; renunciar a las agresivas máquinas y centrarse exclusivamente en la comodidad, control de dolor y la calidad de los últimos días y meses de vida en paliativos)"] } ], note: "Todos los trasplantados o pacientes requieren, adicionalmente, un régimen sumamente estricto de dieta baja en sodio, control del potasio, de fósforo, manejo preciso y minucioso de líquidos, además de medicamentos inyectables para anemia (eritropoyetina)." }, whenToSeekHelp: { title: "¿Cuándo acudir a URGENCIAS si ya eres un paciente renal?", intro: "Es indispensable la acción hospitalaria de urgencia médica si sufres o si padeces una alteración terminal de tus síntomas basales:", items: ["Desarrollas una severa, inaguantable y repentina sensación ahogante de asfixia y dificultad enorme para atrapar aire (indica un peligroso edema agudo de pulmón por líquido no dializado)", "Experimentas dolor de pecho y de miocardio severo, punzante o arritmias y latidos incontrolables irregulares del corazón, debilidad general extrema inusual y desfallecimiento inminente (a menudo debido a niveles hiperpotasémicos mortales u ataque cardíaco)", "Padeces confusión grave con estado mental fuertemente alterado, letargo incontrolable, pérdida y de conciencia severa o convulsiones uremicas"] }, symptoms: { title: "Síntomas Agudos del Envenenamiento Uremico", intro: "Los signos clínicos generales son muy severos y afectan cada sistema del organismo:", groups: [ { name: "Síntomas y Clínica", items: ["Hinchazón edema de retención severa y evidente en piernas, cara y brazos", "Cansancio total profundo, falta crónica letárgica de energía e insuficiencia respiratoria severa (anemia urémica)", "Disfunción gástrica de náuseas o de asco intenso constante por alimentos, rechazo y vómitos matutinos repetitivos", "Prurito extremo, muy dolorosa y extensa picazón en piel con un fuerte aliento amoniacal e inusual sabor a hierro o metálico en paladar", "Calambres intensísimos musculares dolorosos en reposo nocturno o problemas serios del patrón de sueño"] } ], warning: "La acumulación no eliminada del mortal y alto potasio interfiere en la actividad eléctrica natural de todo tu corazón y sin atención es letal." } },
'Bursitis epitroclear' : { intro: "La bursitis epitroclear es la inflamación de la bursa ubicada en la parte interna del codo, cerca de la epitróclea. A menudo se asocia con el 'codo de golfista' o epicondilitis medial, causando dolor en la cara interna del codo que puede irradiarse al antebrazo.", whatIs: { title: "¿Qué es la Bursitis Epitroclear?", text: "Es la inflamación y aumento de líquido en la bolsa sinovial (bursa) situada sobre la epitróclea (el hueso prominente en la parte interna del codo), lo que reduce su capacidad para amortiguar el roce entre huesos y tendones." }, symptoms: { title: "Síntomas", intro: "Los signos se concentran en la parte interna del codo:", groups: [ { name: "Signos Clínicos", items: ["Dolor y sensibilidad en la parte interna del codo", "Hinchazón visible o bulto en la zona de la epitróclea", "Aumento del dolor al flexionar la muñeca o agarrar objetos", "Enrojecimiento y calor local"] } ], warning: "Si el codo está muy caliente y rojo, y hay fiebre, podría ser una bursitis infecciosa." }, types: { title: "Tipos", intro: "Se puede clasificar por su origen:", items: ["Bursitis aséptica (por sobrecarga o trauma, sin infección)", "Bursitis séptica (causada por una infección bacteriana)"], note: "Es común que coexista con la tendinitis de los músculos flexores." }, causes: { title: "Causas", intro: "Suele deberse a la sobrecarga mecánica:", items: ["Movimientos repetitivos del brazo y la muñeca (ej. golf, béisbol, uso de herramientas)", "Traumatismo directo o golpe en la parte interna del codo", "Apoyar los codos sobre superficies duras por tiempo prolongado", "Infecciones (si hay heridas en la piel)"] }, diagnosis: { title: "Diagnóstico", intro: "El diagnóstico es principalmente clínico:", items: ["Examen físico del codo (palpación y pruebas de movilidad)", "Ecografía (para confirmar la acumulación de líquido en la bursa)", "Aspiración de líquido (si se sospecha infección o gota)"], note: "" }, treatment: { title: "Tratamiento", intro: "El tratamiento suele ser conservador:", subsections: [ { title: "Medidas Terapéuticas", items: ["Reposo y aplicación de hielo en la zona afectada", "Analgésicos y antiinflamatorios no esteroideos (AINEs)", "Fisioterapia para estiramiento y fortalecimiento", "Infiltración con corticosteroides (en casos persistentes)", "Antibióticos (solo si es bursitis séptica)"] } ], note: "Evitar la actividad que desencadenó el problema es clave para la recuperación." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Busca atención médica si:", items: ["El dolor del codo no mejora con reposo después de un par de semanas", "Aparece un bulto grande que duele al tacto", "Tienes fiebre, escalofríos o la zona está muy roja y caliente"] } },
'Amenorrea secundaria' : { intro: "La amenorrea secundaria es la ausencia de períodos menstruales durante tres o más meses consecutivos en una mujer que previamente menstruaba de forma regular, o durante seis meses en una mujer con ciclos irregulares.", whatIs: { title: "¿Qué es la Amenorrea Secundaria?", text: "Es la interrupción del ciclo menstrual regular. A diferencia de la amenorrea primaria (donde la regla nunca comenzó), en la secundaria la menstruación se detiene debido a desequilibrios hormonales, problemas físicos, estrés o cambios extremos en el estilo de vida." }, symptoms: { title: "Síntomas", intro: "El síntoma principal es la falta de regla, pero puede acompañarse de:", groups: [ { name: "Señales Frecuentes", items: ["Ausencia de menstruación por 3 a 6 meses", "Secreción de leche por los pezones (galactorrea)", "Pérdida de cabello", "Dolor de cabeza o cambios en la visión", "Exceso de vello facial (hirsutismo)", "Acné severo"] } ], warning: "La causa más común y natural de la amenorrea secundaria es el embarazo, el cual siempre debe descartarse primero." }, types: { title: "Causas y Clasificación", intro: "Se puede clasificar según su origen fisiológico:", items: ["Amenorrea hipotalámica (por pérdida de peso, estrés o ejercicio extremo)", "Trastornos hipofisarios (tumores benignos como prolactinomas)", "Trastornos ováricos (Síndrome de Ovario Poliquístico o fallo ovárico prematuro)", "Alteraciones uterinas (adherencias o síndrome de Asherman)"], note: "" }, causes: { title: "Factores Desencadenantes", intro: "Existen múltiples razones para la interrupción del ciclo:", items: ["Embarazo, lactancia o menopausia (causas naturales)", "Uso o suspensión de anticonceptivos hormonales", "Estrés mental crónico o severo", "Trastornos de la alimentación (anorexia, bulimia)", "Problemas de la glándula tiroides"] }, diagnosis: { title: "Evaluación Médica", intro: "El ginecólogo realizará diversas pruebas para hallar la causa:", items: ["Prueba de embarazo (el primer paso indispensable)", "Análisis de sangre para evaluar niveles hormonales (prolactina, FSH, TSH, testosterona)", "Ecografía pélvica o transvaginal (para revisar ovarios y útero)", "Prueba de provocación con progestina (para comprobar los niveles de estrógeno)"], note: "" }, treatment: { title: "Tratamiento", intro: "El tratamiento se enfoca en la causa subyacente:", subsections: [ { title: "Intervenciones", items: ["Terapia hormonal (píldoras anticonceptivas o estrógeno/progesterona para reiniciar el ciclo)", "Cambios en el estilo de vida (reducir el estrés, ajustar el ejercicio, alcanzar un peso saludable)", "Medicamentos específicos (ej. para tratar alteraciones de la tiroides o SOP)", "Cirugía (raramente, para extirpar tumores hipofisarios o tratar adherencias uterinas)"] } ], note: "El pronóstico de recuperación de la fertilidad y regularidad del ciclo es generalmente muy bueno con el tratamiento adecuado." }, whenToSeekHelp: { title: "¿Cuándo acudir al ginecólogo?", intro: "Es importante programar una revisión si:", items: ["Tus periodos se han detenido por tres meses o más y no estás embarazada", "Experimentas síntomas como dolores de cabeza inexplicables, problemas de visión o secreción de los pezones", "Sufres de pérdida o aumento de peso drástico junto con la ausencia del periodo"] } },
'Cáncer de endometrio' : { intro: "El cáncer de endometrio es un tipo de cáncer que comienza en el útero, específicamente en la capa de células que forman el revestimiento interior (el endometrio). Es el cáncer ginecológico más frecuente.", whatIs: { title: "¿Qué es el Cáncer de Endometrio?", text: "Es el crecimiento maligno y descontrolado de las células endometriales. Afortunadamente, se suele detectar en etapas tempranas debido a que produce sangrado vaginal anormal, lo que alerta a las pacientes a buscar atención médica." }, symptoms: { title: "Síntomas", intro: "El signo más revelador es el sangrado inusual:", groups: [ { name: "Señales Físicas", items: ["Sangrado vaginal o manchado después de la menopausia", "Sangrado entre períodos menstruales (en mujeres premenopáusicas)", "Dolor pélvico persistente", "Flujo vaginal anormal, acuoso o teñido de sangre"] } ], warning: "Cualquier sangrado vaginal que ocurra después de la menopausia no es normal y debe ser evaluado de inmediato." }, types: { title: "Tipos Celulares", intro: "Se clasifica por su agresividad y dependencia hormonal:", items: ["Tipo 1 (Endometrioide, el más común, crece lentamente y a menudo depende del estrógeno)", "Tipo 2 (No endometrioide, menos común pero mucho más agresivo y con mayor tendencia a propagarse)"], note: "El pronóstico es excelente si se extirpa antes de que se extienda fuera del útero." }, causes: { title: "Factores de Riesgo", intro: "Está fuertemente ligado al equilibrio hormonal:", items: ["Niveles altos de estrógeno sin progesterona equilibrante", "Obesidad (el tejido graso produce estrógeno adicional)", "Menstruación a una edad temprana o menopausia tardía", "Nunca haber estado embarazada", "Terapia hormonal para el cáncer de mama (Tamoxifeno)"] }, diagnosis: { title: "Diagnóstico", intro: "El ginecólogo realizará pruebas para confirmar el tejido:", items: ["Ecografía transvaginal (para medir el grosor del endometrio)", "Histeroscopia (para mirar dentro del útero con una cámara pequeña)", "Biopsia endometrial (extracción de una muestra de tejido en el consultorio, es la prueba definitiva)"], note: "El Papanicolaou no es una prueba confiable para detectar el cáncer de endometrio." }, treatment: { title: "Opciones Oncológicas", intro: "La cirugía es el pilar del tratamiento:", subsections: [ { title: "Terapias", items: ["Histerectomía (cirugía para extirpar el útero, ovarios y trompas)", "Radioterapia (para destruir células restantes en la pelvis)", "Terapia hormonal (progestina para bloquear el crecimiento celular)", "Quimioterapia (para estadios avanzados)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Solicita consulta urgente si:", items: ["Experimentas cualquier tipo de sangrado, manchado o flujo con sangre después de la menopausia", "Tus menstruaciones se vuelven repentinamente muy abundantes o sangras entre periodos", "Sufres de dolor pélvico nuevo e inexplicable"] } },
'Insuficiencia crónica del riñón' : { intro: "La insuficiencia crónica del riñón (enfermedad renal crónica) es la pérdida progresiva, gradual e irreversible de la función renal a lo largo de meses o años, lo que impide al cuerpo filtrar los desechos tóxicos de la sangre.", whatIs: { title: "¿Qué es la Insuficiencia Crónica?", text: "Es el deterioro continuo de las nefronas (filtros) de los riñones. A diferencia de un fallo agudo, este daño no se puede revertir. Los riñones pierden su capacidad de eliminar agua, regular la presión y limpiar la sangre, llevando a una acumulación tóxica en el organismo." }, symptoms: { title: "Síntomas", intro: "Suele ser silenciosa hasta que el daño es avanzado:", groups: [ { name: "Signos Clínicos", items: ["Hinchazón (edema) en piernas, tobillos o rostro", "Fatiga extrema, debilidad y anemia", "Náuseas, vómitos y pérdida de apetito", "Cambios en la frecuencia urinaria (orinar mucho de noche)", "Picazón intensa en la piel", "Calambres musculares"] } ], warning: "En sus primeras etapas no causa ningún síntoma; solo se detecta mediante análisis de laboratorio." }, types: { title: "Etapas de la Enfermedad", intro: "Se mide según la Tasa de Filtración Glomerular (TFG):", items: ["Etapas 1-3 (Daño leve a moderado, a menudo asintomático, el objetivo es frenar el avance)", "Etapa 4 (Daño severo, los síntomas se vuelven notorios y se prepara al paciente para el fallo)", "Etapa 5 (Insuficiencia renal terminal, requiere diálisis o trasplante para sobrevivir)"], note: "" }, causes: { title: "Causas Principales", intro: "Las enfermedades sistémicas son los mayores culpables:", items: ["Diabetes (tipo 1 o tipo 2, la causa número uno)", "Hipertensión arterial crónica", "Glomerulonefritis (inflamación autoinmune)", "Enfermedad renal poliquística (genética)", "Uso prolongado de medicamentos tóxicos para los riñones"] }, diagnosis: { title: "Evaluación Médica", intro: "El nefrólogo utiliza marcadores sanguíneos y urinarios:", items: ["Análisis de sangre (para medir la creatinina y calcular la TFG)", "Análisis de orina (para detectar pérdida de proteína o albúmina)", "Ecografía renal (para ver si los riñones están encogidos o dañados estructuralmente)"], note: "" }, treatment: { title: "Manejo y Diálisis", intro: "Se busca frenar el daño y tratar las complicaciones:", subsections: [ { title: "Intervenciones", items: ["Control estricto de la presión arterial (medicamentos IECA o ARA-II) y el azúcar en sangre", "Dieta renal estricta (reducir sodio, potasio y proteínas)", "Medicamentos para la anemia y para proteger los huesos", "Hemodiálisis o diálisis peritoneal (cuando la función cae por debajo del 15%)", "Trasplante de riñón"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Ve a emergencias o consulta a tu nefrólogo si:", items: ["Retienes líquidos de manera masiva, sintiendo que te falta el aire al acostarte", "Sientes confusión profunda o letargo", "Tienes náuseas constantes que te impiden comer"] } },
'Mieloma múltiple' : { intro: "El mieloma múltiple es un tipo de cáncer de la sangre que se forma en un tipo de glóbulo blanco llamado célula plasmática, el cual se encuentra en la médula ósea y normalmente ayuda a combatir infecciones.", whatIs: { title: "¿Qué es el Mieloma Múltiple?", text: "En esta enfermedad, las células plasmáticas cancerosas se acumulan en la médula ósea, desplazando a las células sanguíneas sanas. En lugar de producir anticuerpos útiles, estas células malignas producen proteínas anormales (proteína M) que pueden dañar los riñones y destruir los huesos." }, symptoms: { title: "Síntomas (Criterios CRAB)", intro: "Los síntomas a menudo se recuerdan con el acrónimo CRAB:", groups: [ { name: "Manifestaciones Clínicas", items: ["C (Calcio alto): Sed extrema, confusión y dolor de estómago", "R (Renal): Insuficiencia renal y problemas para orinar", "A (Anemia): Fatiga paralizante, debilidad y palidez", "B (Bones/Huesos): Dolor óseo intenso (especialmente en la espalda, costillas o caderas) y fracturas fáciles"] } ], warning: "El dolor de espalda agudo e inexplicable en un adulto mayor debe ser investigado a fondo." }, types: { title: "Fases de la Enfermedad", intro: "Se clasifica según su actividad:", items: ["Gammapatía monoclonal de significado incierto (GMSI) (condición precancerosa benigna)", "Mieloma múltiple latente (asintomático, de crecimiento lento)", "Mieloma múltiple activo (produce síntomas, daño orgánico y requiere tratamiento inmediato)"], note: "" }, causes: { title: "Factores de Riesgo", intro: "No tiene una causa única clara, pero se asocia a:", items: ["Edad avanzada (más común en mayores de 65 años)", "Raza (es dos veces más común en personas afrodescendientes)", "Antecedentes familiares de mieloma o GMSI", "Exposición a ciertas sustancias químicas o radiación"] }, diagnosis: { title: "Diagnóstico Hematológico", intro: "El hematólogo/oncólogo realizará varias pruebas:", items: ["Análisis de sangre y orina (para detectar la proteína monoclonal 'M' y problemas renales)", "Aspirado y biopsia de médula ósea (para confirmar el porcentaje de células plasmáticas cancerosas)", "Pruebas de imagen (Radiografías óseas, RM o PET scan para detectar lesiones 'en sacabocados' en los huesos)"], note: "" }, treatment: { title: "Terapias Oncológicas", intro: "Ha habido enormes avances en el tratamiento del mieloma:", subsections: [ { title: "Intervenciones", items: ["Terapia dirigida (inhibidores del proteasoma como Bortezomib)", "Inmunoterapia (Daratumumab o células CAR-T para potenciar el sistema inmune)", "Corticosteroides (Dexametasona, piedra angular del tratamiento)", "Quimioterapia tradicional y bisfosfonatos para proteger el hueso", "Trasplante de células madre (médula ósea) autólogo"] } ], note: "Aunque actualmente se considera incurable, las nuevas terapias han convertido al mieloma en una enfermedad crónica manejable durante muchos años." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es fundamental buscar evaluación si presentas:", items: ["Un dolor de huesos sordo, profundo y persistente, particularmente en la espalda o el pecho", "Fatiga severa y debilidad extrema", "Infecciones recurrentes que no sanan", "Náuseas constantes, confusión o pérdida de peso inexplicable"] } },
'Nariz bulbosa' : { intro: "La nariz bulbosa, médicamente conocida como Rinofima, es una afección cutánea que hace que la nariz adquiera un aspecto agrandado, rojo, abultado y deforme. Es una complicación grave y tardía de la rosácea.", whatIs: { title: "¿Qué es el Rinofima?", text: "Es el engrosamiento severo de la piel de la nariz, provocado por la hipertrofia (agrandamiento) de las glándulas sebáceas y el tejido conectivo circundante. Aunque históricamente se asoció injustamente con el alcoholismo, es en realidad un subtipo avanzado de la enfermedad inflamatoria rosácea." }, symptoms: { title: "Síntomas Visuales", intro: "Los cambios son físicos, progresivos e inconfundibles:", groups: [ { name: "Apariencia Nasal", items: ["Agrandamiento gradual de la nariz con forma de bulbo", "Piel engrosada, gruesa y muy roja o purpúrea", "Poros extremadamente dilatados y prominentes", "Superficie nasal irregular, con bultos o nódulos", "Piel grasosa"] } ], warning: "En casos muy avanzados, el tejido puede crecer tanto que obstruye las fosas nasales y dificulta la respiración." }, types: { title: "Variantes Clínicas", intro: "El dermatólogo puede clasificarla según el tejido predominante:", items: ["Forma glandular (poros enormes, secreción de sebo)", "Forma fibroangiomatosa (roja, con muchas venas pequeñas visibles - telangiectasias)", "Forma actínica (masas nodulares de tejido fibroso por daño solar)"], note: "Es casi exclusiva de hombres mayores de 50 años, aunque la rosácea es más común en mujeres." }, causes: { title: "Causas", intro: "Su origen es la inflamación crónica:", items: ["Rosácea no tratada a largo plazo (causa principal)", "Factores genéticos (tendencia familiar a la rosácea severa)", "Dilatación crónica de los vasos sanguíneos faciales"] }, diagnosis: { title: "Examen Dermatológico", intro: "Generalmente no requiere pruebas de laboratorio:", items: ["Diagnóstico clínico visual por parte del dermatólogo", "Biopsia de piel (rara vez, solo para descartar carcinomas basocelulares u otros cánceres que puedan ocultarse bajo el tejido deformado)"], note: "" }, treatment: { title: "Corrección Médica y Quirúrgica", intro: "Los medicamentos no revierten el rinofima avanzado; se requiere cirugía para remodelar la nariz:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos orales (Isotretinoína o antibióticos para reducir la inflamación y el tamaño de las glándulas en etapas muy tempranas)", "Cirugía con láser (Láser de CO2 o Erbium para esculpir y vaporizar el tejido sobrante con precisión)", "Electrocirugía o criocirugía", "Dermoabrasión o escisión con bisturí (para afeitar y retirar el tejido engrosado, devolviendo a la nariz su forma original)"] } ], note: "La cirugía estética reconstructiva ofrece resultados psicológicos y físicos excelentes." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Pide cita con un dermatólogo si:", items: ["Notas que la piel de tu nariz se está volviendo permanentemente roja, engrosada o abultada", "Sufres de rosácea y notas que está empeorando o cambiando la forma de tu nariz", "El tamaño de tu nariz comienza a dificultar tu respiración o afecta severamente tu autoestima"] } },
'Control de emociones' : { intro: "Las dificultades en el control de emociones, o desregulación emocional, implican la incapacidad de una persona para manejar y responder a las experiencias emocionales de una manera saludable, lo que conduce a explosiones afectivas, aislamiento o sufrimiento psicológico severo.", whatIs: { title: "¿Qué es la Desregulación Emocional?", text: "Es la incapacidad del cerebro para modular las respuestas emocionales. La persona experimenta emociones (como ira, tristeza o miedo) con una intensidad abrumadora, duración prolongada y una gran dificultad para calmarse y volver a un estado basal, lo que interfiere con su vida y sus relaciones." }, symptoms: { title: "Señales Clínicas", intro: "Se manifiesta de formas internas o externas:", groups: [ { name: "Conductuales y Emocionales", items: ["Arranques de ira intensos o rabietas desproporcionadas", "Llantos incontrolables o cambios de humor rápidos", "Comportamientos impulsivos (conducir temerariamente, gastos excesivos)", "Autolesiones o amenazas de suicidio como mecanismo de escape", "Supresión emocional (entumecimiento o incapacidad para sentir)"] } ], warning: "Cuando la falta de control emocional resulta en autolesiones o violencia, se convierte en una urgencia psiquiátrica." }, types: { title: "Trastornos Asociados", intro: "Suele ser un síntoma central de otras condiciones de salud mental:", items: ["Trastorno Límite de la Personalidad (TLP) (caracterizado por inestabilidad emocional crónica)", "Trastorno por Déficit de Atención e Hiperactividad (TDAH)", "Trastorno de Estrés Postraumático (TEPT) o trauma complejo", "Trastorno Bipolar", "Trastornos de Ansiedad severos"], note: "No es un defecto de carácter, sino una dificultad neurobiológica y psicológica real." }, causes: { title: "Causas Subyacentes", intro: "Es una combinación de biología y entorno:", items: ["Trauma infantil, abuso o negligencia (el cerebro aprende a estar en estado de alerta constante)", "Vulnerabilidad genética o biológica (amígdala hiperactiva)", "Falta de modelado de habilidades de afrontamiento en la infancia", "Estrés crónico abrumador"] }, diagnosis: { title: "Evaluación Psicológica", intro: "Realizada por un psicólogo o psiquiatra:", items: ["Entrevista clínica exhaustiva para evaluar los patrones de reacción del paciente", "Evaluación de antecedentes de trauma", "Uso de cuestionarios clínicos para diagnosticar posibles trastornos de personalidad o del estado de ánimo subyacentes"], note: "" }, treatment: { title: "Psicoterapia y Herramientas", intro: "El tratamiento se basa en aprender a tolerar y regular las emociones:", subsections: [ { title: "Terapias Efectivas", items: ["Terapia Dialéctica Conductual (DBT) (el estándar de oro para la desregulación; enseña habilidades de tolerancia a la angustia, atención plena y regulación emocional)", "Terapia Cognitivo-Conductual (TCC) (para identificar pensamientos irracionales que desencadenan emociones extremas)", "Prácticas de Mindfulness y meditación", "Medicamentos (antidepresivos o estabilizadores del ánimo para tratar los trastornos subyacentes y reducir la reactividad del cerebro)"] } ], note: "Aprender a hacer pausas entre la emoción y la reacción es el objetivo principal de la terapia." }, whenToSeekHelp: { title: "¿Cuándo buscar terapia profesional?", intro: "Es fundamental buscar ayuda de un terapeuta si:", items: ["Tus reacciones emocionales están destruyendo tus relaciones personales, familiares o laborales", "Sientes que tus emociones te controlan a ti en lugar de tú a ellas", "Recurres al alcohol, las drogas o las autolesiones para calmar tu dolor emocional o tu ira", "Sientes una tristeza, vacío o rabia constante que no puedes apagar"] } },
'Pancreatitis aguda' : { intro: "La pancreatitis aguda es la inflamación súbita, severa y rápida del páncreas, un órgano vital situado detrás del estómago. Es una emergencia médica que causa un dolor abdominal insoportable y requiere hospitalización inmediata.", whatIs: { title: "¿Qué es la Pancreatitis Aguda?", text: "Ocurre cuando las enzimas digestivas que produce el páncreas se activan prematuramente mientras aún están dentro del órgano. Estas poderosas enzimas comienzan a 'digerir' y destruir el propio tejido pancreático, causando hinchazón extrema, daño a los vasos sanguíneos y sangrado interno." }, symptoms: { title: "Síntomas de Urgencia", intro: "El dolor es el síntoma cardinal:", groups: [ { name: "Cuadro Clínico", items: ["Dolor abdominal superior repentino, muy intenso y punzante que atraviesa hacia la espalda", "El dolor empeora al comer o al acostarse boca arriba", "Náuseas incontrolables y vómitos violentos", "Fiebre, pulso rápido y sudoración fría", "Abdomen muy sensible, rígido o hinchado al tacto"] } ], warning: "En casos graves, puede causar una caída mortal de la presión arterial, shock o insuficiencia multiorgánica (pulmones o riñones)." }, types: { title: "Grados de Severidad", intro: "Se clasifica clínicamente para determinar el cuidado:", items: ["Leve (inflamación sin fallo de otros órganos, suele resolverse en una semana con líquidos)", "Moderada (complicaciones locales o fallo orgánico transitorio que se resuelve en menos de 48 hrs)", "Grave o Severa (falla orgánica persistente, necrosis del páncreas o infección; alta tasa de mortalidad)"], note: "" }, causes: { title: "Desencadenantes Principales", intro: "La inmensa mayoría de los casos se debe a dos factores:", items: ["Cálculos biliares (la causa #1; una piedra sale de la vesícula y bloquea el conducto pancreático)", "Consumo excesivo de alcohol (causa principal en pacientes recurrentes)", "Niveles extremadamente altos de triglicéridos en sangre", "Reacción a ciertos medicamentos o traumas abdominales"] }, diagnosis: { title: "Diagnóstico Hospitalario", intro: "Confirmado rápidamente en la sala de urgencias:", items: ["Análisis de sangre (los niveles de las enzimas pancreáticas, amilasa y lipasa, estarán elevados hasta 3 veces su valor normal)", "Tomografía Computarizada (TC) de abdomen con contraste (para visualizar la inflamación, necrosis o pseudoquistes)", "Ecografía (para verificar si la causa son cálculos biliares)"], note: "" }, treatment: { title: "Soporte Vital e Intervención", intro: "El tratamiento inicial busca que el páncreas descanse y se cure:", subsections: [ { title: "Manejo en Hospital", items: ["Ayuno total inicial (nada por la boca) para detener la producción de enzimas", "Hidratación intravenosa (IV) agresiva y continua para prevenir el shock y proteger los riñones", "Analgésicos intravenosos potentes para controlar el dolor extremo", "Cirugía (CPRE para extraer cálculos biliares obstructivos, colecistectomía para sacar la vesícula, o cirugía para limpiar tejido pancreático muerto/infectado)"] } ], note: "Evitar el alcohol y controlar las grasas en la dieta es imperativo para evitar una recurrencia o desarrollar pancreatitis crónica." }, whenToSeekHelp: { title: "¿Cuándo llamar a emergencias?", intro: "La pancreatitis aguda es una urgencia vital. Acude al hospital si presentas:", items: ["Un dolor abdominal insoportable, repentino y central que se irradia a la espalda, impidiéndote encontrar una posición cómoda", "Incapacidad para dejar de vomitar", "Piel fría y pegajosa, confusión, respiración rápida o coloración amarillenta (ictericia)"] } },
'Accidente cerebrovascular isquémico' : { intro: "Un accidente cerebrovascular isquémico (infarto cerebral o derrame) es una emergencia médica catastrófica que ocurre cuando un coágulo de sangre bloquea un vaso sanguíneo, cortando el suministro de oxígeno y nutrientes a una parte del cerebro.", whatIs: { title: "¿Qué es el ACV Isquémico?", text: "Representa casi el 87% de todos los derrames cerebrales. Al interrumpirse el flujo de sangre, las neuronas cerebrales comienzan a asfixiarse y mueren en cuestión de minutos. El daño neurológico causa pérdida de funciones como el habla, el movimiento o la visión." }, symptoms: { title: "Signos F.A.S.T (Rápido)", intro: "Los síntomas aparecen de golpe. Usa la regla FAST:", groups: [ { name: "Síntomas Neurológicos Repentinos", items: ["Cara caída (Face): Una mitad de la cara se adormece o la sonrisa es asimétrica.", "Brazos débiles (Arms): Incapacidad para levantar o mantener ambos brazos en alto.", "Dificultad para hablar (Speech): Habla arrastrada, confusa o incapacidad para entender.", "Tiempo (Time): Si notas alguno de estos signos, llama al 911 de inmediato."] } ], warning: "Cada minuto que pasa sin tratamiento mueren millones de neuronas. No esperes a ver si los síntomas mejoran." }, types: { title: "Mecanismo del Coágulo", intro: "Se divide por el origen del bloqueo:", items: ["ACV Trombótico (un coágulo se forma directamente en una arteria cerebral estrechada por placas de colesterol)", "ACV Embólico (un coágulo se forma en otra parte, como el corazón debido a una arritmia, y viaja hasta el cerebro)", "Ataque Isquémico Transitorio (AIT) (un mini-derrame donde el bloqueo se disuelve solo; es una advertencia máxima de un ACV inminente)"], note: "" }, causes: { title: "Factores de Riesgo", intro: "Relacionados con la salud cardiovascular:", items: ["Presión arterial alta (el factor de riesgo más importante)", "Fibrilación auricular (arritmia cardíaca)", "Tabaquismo, diabetes y colesterol alto", "Edad avanzada y obesidad"] }, diagnosis: { title: "Escáneres de Emergencia", intro: "Al llegar a urgencias, el diagnóstico debe ser instantáneo:", items: ["Tomografía Computarizada (TC) de cabeza sin contraste (se hace de inmediato para descartar sangrado y confirmar que es isquémico)", "Resonancia Magnética (RM) del cerebro (detecta el tejido cerebral dañado)", "Angiografía y Ecocardiograma (para localizar el coágulo y su origen)"], note: "El médico debe saber la hora exacta en la que el paciente fue visto 'normal' por última vez." }, treatment: { title: "Destrucción del Coágulo (Trombolisis)", intro: "El tratamiento debe administrarse en las primeras 3 a 4.5 horas:", subsections: [ { title: "Intervenciones Críticas", items: ["Medicamento Trombolítico (tPA / alteplasa inyectada por vena para disolver el coágulo y salvar el cerebro; solo efectivo si se da muy rápido)", "Trombectomía endovascular (un neurocirujano introduce un catéter desde la ingle hasta el cerebro para extraer mecánicamente el coágulo)", "Anticoagulantes o antiagregantes (aspirina) para evitar nuevos trombos", "Rehabilitación intensiva posterior (física, ocupacional y del habla)"] } ], note: "Si el paciente llega tarde al hospital, los medicamentos para disolver coágulos ya no se pueden usar." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911?", intro: "Llama a emergencias de forma inmediata si la persona experimenta, repentinamente:", items: ["Pérdida de fuerza o parálisis en un lado del cuerpo o la cara", "Incapacidad para hablar, encontrar palabras o comprender lo que se le dice", "Pérdida de visión en uno o ambos ojos", "Mareo muy severo, pérdida del equilibrio o caídas inexplicables"] } },
'Inestabilidad Glenohumeral' : { intro: "La inestabilidad glenohumeral es una afección en la cual la cabeza del hueso del brazo (húmero) se sale, parcial o totalmente, de su cavidad en el hombro (glenoides). Esto causa dolor, pérdida de fuerza y una sensación constante de que el hombro está suelto o se va a salir.", whatIs: { title: "¿Qué es la Inestabilidad del Hombro?", text: "El hombro es la articulación con mayor movilidad del cuerpo, pero también la más inestable. Cuando los ligamentos, la cápsula o el rodete glenoideo (labrum) que mantienen el hueso en su lugar se estiran o desgarran (generalmente tras una dislocación traumática), el hombro pierde su anclaje y se luxa repetidamente con movimientos cotidianos." }, types: { title: "Dirección de la Inestabilidad", intro: "Se clasifica según hacia dónde se sale el hueso:", items: ["Inestabilidad Anterior (el 95% de los casos; el hueso se sale hacia el frente, común al lanzar una pelota o por caídas apoyando el brazo)", "Inestabilidad Posterior (el hueso se sale hacia atrás, común tras convulsiones o descargas eléctricas)", "Inestabilidad Multidireccional (el hombro está suelto en todas direcciones debido a ligamentos naturalmente hiperelaxos o 'dobles articulaciones', sin trauma previo)"], note: "Una sola dislocación en una persona joven aumenta masivamente el riesgo de inestabilidad crónica para el resto de su vida." }, diagnosis: { title: "Evaluación Ortopédica", intro: "El traumatólogo realiza pruebas físicas específicas para provocar la sensación de que el hombro se sale:", items: ["Examen físico (Test de Aprehensión: el médico rota el brazo hacia atrás, y si el paciente siente miedo de que se salga, es positivo)", "Radiografías (para ver si hay fracturas en el borde de la cavidad glenoidea o en el húmero tras las dislocaciones repetidas)", "Artro-Resonancia Magnética (se inyecta contraste en el hombro y se hace una RM; es la prueba de oro para ver los desgarros en los ligamentos y el labrum)"], note: "" }, treatment: { title: "Fortalecimiento y Reparación Artroscópica", intro: "El tratamiento depende del nivel de actividad del paciente y del daño anatómico:", subsections: [ { title: "Opciones Terapéuticas", items: ["Fisioterapia intensiva (el tratamiento inicial para la inestabilidad multidireccional; fortalece los músculos del manguito rotador para que 'abracen' y suplanten a los ligamentos débiles)", "Modificación de la actividad (evitar deportes de contacto o lanzamientos por encima de la cabeza)", "Cirugía artroscópica (Reparación de Bankart: se usan pequeños anclajes y suturas para volver a coser los ligamentos y el labrum desgarrado al hueso)", "Cirugía abierta (como el procedimiento de Latarjet, usado si hay pérdida de hueso severa debido a docenas de dislocaciones previas)"] } ], note: "Después de la cirugía, el brazo deberá estar inmovilizado en un cabestrillo de 4 a 6 semanas, seguido de meses de rehabilitación." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias o al traumatólogo?", intro: "Una luxación activa es una emergencia ortopédica. Busca ayuda médica si:", items: ["Sufres un golpe y tu hombro se ve visiblemente deformado, cuadrado o fuera de lugar, acompañado de un dolor insoportable (¡NO intentes acomodarlo tú mismo!)", "Sientes repetidamente que tu hombro 'cede', se resbala o hace un chasquido doloroso al nadar, lanzar o dormir", "Tienes una sensación de 'brazo muerto' o entumecimiento eléctrico que baja por el brazo tras un movimiento brusco"] }, causes: { title: "Causas y Factores", intro: "La inestabilidad suele originarse por:", items: ["Traumatismo severo (la causa más común; una dislocación traumática rasga la cápsula)", "Microtraumatismos repetitivos (lanzadores de béisbol, nadadores, tenistas que estiran los ligamentos crónicamente)", "Hiperlaxitud ligamentaria genética (personas que son excesivamente flexibles por naturaleza)"] } },
'Litiasis renal' : { intro: "La litiasis renal, comúnmente conocida como piedras o cálculos en los riñones, es la formación de masas sólidas y duras de minerales y sales dentro de las vías urinarias. Producen uno de los dolores más intensos que se pueden experimentar en la medicina.", whatIs: { title: "¿Qué es la Litiasis Renal?", text: "Ocurre cuando la orina se concentra en exceso, lo que permite que los minerales (como calcio o ácido úrico) cristalicen y se agrupen formando piedras. Mientras están en el riñón no duelen, pero cuando descienden e intentan pasar por los estrechos conductos (uréteres) hacia la vejiga, causan un espasmo doloroso extremo conocido como cólico nefrítico." }, types: { title: "Composición de las Piedras", intro: "El tratamiento preventivo depende de lo que esté hecha la piedra:", items: ["Litiasis cálcica (oxalato de calcio o fosfato; representan el 80% de los casos, ligadas a baja hidratación y alta ingesta de sal o proteína animal)", "Litiasis de ácido úrico (comunes en personas con gota o dietas ricas en carnes)", "Litiasis de estruvita (crecen rápidamente como resultado de infecciones urinarias crónicas)", "Litiasis de cistina (rara, causada por un trastorno genético hereditario)"], note: "La falta de consumo diario de agua es el detonante universal para todos los tipos de litiasis." }, diagnosis: { title: "Diagnóstico de Urgencia e Imagen", intro: "El diagnóstico se basa en el dolor característico y estudios de imagen:", items: ["Tomografía Computarizada (TC) de abdomen sin contraste (la prueba de elección y más precisa en urgencias; detecta el tamaño exacto, la ubicación de la piedra y si hay obstrucción)", "Ecografía renal (útil para ver dilatación del riñón y evitar radiación, especialmente en embarazadas)", "Análisis de orina (para detectar glóbulos rojos -sangre invisible- y descartar infección concomitante)", "Análisis de la composición de la piedra (filtrando la orina en casa para atraparla y enviarla al laboratorio)"], note: "" }, treatment: { title: "Expulsión Natural o Cirugía", intro: "El manejo depende del tamaño del cálculo y si hay daño al riñón:", subsections: [ { title: "Opciones Clínicas", items: ["Tratamiento expulsivo médico (para piedras pequeñas < 5mm): Hidratación masiva, analgésicos fuertes (AINEs u opioides) y bloqueadores alfa (tamsulosina) para dilatar el uréter y facilitar su salida.", "Litotricia extracorpórea por ondas de choque (máquina externa que emite ondas sonoras para pulverizar la piedra grande en arena, permitiendo que se orine)", "Ureteroscopia (se introduce un tubo fino con cámara por la uretra hasta el uréter para romper la piedra con láser y extraer los fragmentos con una canastilla)", "Nefrolitotomía percutánea (cirugía mínimamente invasiva por la espalda para extraer cálculos gigantes)"] } ], note: "Una persona que ha tenido una piedra tiene un 50% de probabilidad de tener otra en los próximos 5 años si no cambia su hidratación." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia vital?", intro: "Debes dirigirte de inmediato a la sala de urgencias si experimentas:", items: ["Dolor lumbar o abdominal súbito, intermitente y tan atroz que te impide sentarte o encontrar una posición de alivio", "Dolor extremo acompañado de náuseas severas y vómitos", "Fiebre y escalofríos intensos junto con el dolor (esto indica que el riñón está obstruido e infectado, lo que puede causar sepsis letal en horas)", "Orina de color rojo oscuro o marrón evidente, o incapacidad total para orinar"] }, symptoms: { title: "Síntomas Clásicos", intro: "El 'cólico nefrítico' presenta:", groups: [ { name: "Cuadro Clínico", items: ["Dolor punzante e intenso en el flanco (costado) y la espalda baja", "El dolor irradia hacia la ingle o los testículos/labios vaginales a medida que la piedra baja", "Sensación de ardor al orinar o necesidad constante de ir al baño expulsando solo gotas", "Orina rosada, roja o marrón (hematuria)"] } ], warning: "Un cálculo bloqueado puede dañar irreversiblemente el riñón si no se alivia la presión." } },
'Insomnio crónico' : { intro: "El insomnio crónico es un trastorno del sueño persistente que dificulta enormemente la capacidad de conciliar el sueño, mantenerse dormido durante la noche, o hace que te despiertes demasiado temprano sin poder volver a dormir, afectando gravemente la salud diurna.", whatIs: { title: "¿Qué es el Insomnio Crónico?", text: "A diferencia de una noche ocasional de mal sueño, el insomnio crónico se diagnostica cuando los problemas para dormir ocurren al menos tres noches a la semana y persisten durante tres meses o más. El cerebro se queda atrapado en un estado de 'hiperalerta', impidiendo que el cuerpo logre el descanso reparador necesario para funcionar." }, types: { title: "Clasificación Clínica", intro: "Se divide por su causa subyacente:", items: ["Insomnio primario (el problema del sueño es la afección en sí misma, no está directamente causado por otra enfermedad, sino a menudo por ansiedad condicionada hacia el propio hecho de dormir)", "Insomnio secundario o comórbido (la causa raíz es otra condición: dolor crónico de artrosis, depresión severa, apnea del sueño, reflujo gastroesofágico, o el uso de medicamentos estimulantes)"], note: "El miedo y la frustración de 'no poder dormir' generan adrenalina, lo que empeora el ciclo de insomnio." }, diagnosis: { title: "Evaluación Médica y Patrones", intro: "El médico o especialista en sueño evaluará tus hábitos y salud mental:", items: ["Historia clínica y revisión exhaustiva de medicamentos y consumo de cafeína/alcohol", "Uso de un diario de sueño durante 2 semanas (anotando horas de acostarse, tiempo que tarda en dormir y despertares)", "Cuestionarios psicológicos (para detectar ansiedad o depresión subyacente)", "Polisomnografía (estudio del sueño en laboratorio, solo se pide si se sospecha de apnea del sueño o movimientos periódicos de piernas, no por insomnio puro)"], note: "" }, treatment: { title: "Terapia Conductual y Fármacos", intro: "La medicación no es la solución definitiva; el cambio de hábitos es crucial:", subsections: [ { title: "Terapias Efectivas", items: ["Terapia Cognitivo-Conductual para el Insomnio (TCC-I) (el tratamiento de primera línea, científicamente más eficaz que las pastillas; incluye restricción del sueño, control de estímulos y reestructuración mental)", "Higiene estricta del sueño (mantener un horario inamovible para levantarse, habitación completamente oscura y fría, cero pantallas azules una hora antes de dormir)", "Técnicas de relajación profunda (mindfulness, respiración diafragmática)", "Medicamentos hipnóticos o ansiolíticos (recetados solo para uso a muy corto plazo, ya que generan tolerancia, dependencia y no curan la causa)"] } ], note: "Acostarse en la cama dando vueltas frustrado empeora el problema; si no duermes en 20 minutos, debes levantarte a hacer algo relajante en otra habitación hasta tener sueño." }, whenToSeekHelp: { title: "¿Cuándo acudir a un profesional?", intro: "Es fundamental buscar ayuda médica especializada si:", items: ["La falta de sueño te causa fatiga paralizante, irritabilidad severa o incapacidad para concentrarte en el trabajo/escuela", "Te sientes peligrosamente somnoliento mientras conduces o manejas maquinaria", "Recurres al alcohol o a pastillas de venta libre constantemente para intentar 'noquearte'", "El insomnio te está llevando a estados profundos de desesperación, depresión clínica o ansiedad generalizada"] } },
'Taquicardia' : { intro: "La taquicardia es un término médico que describe una frecuencia cardíaca anormalmente rápida mientras el cuerpo está en reposo. En un adulto promedio, se considera taquicardia cuando el corazón late a más de 100 latidos por minuto sin estar haciendo ejercicio.", whatIs: { title: "¿Qué es la Taquicardia?", text: "Es una arritmia (trastorno del ritmo cardíaco) causada por una interrupción de los impulsos eléctricos normales que controlan el bombeo del corazón. Si el corazón late demasiado rápido, no tiene tiempo suficiente para llenarse de sangre entre latidos, lo que disminuye el oxígeno que llega al cerebro y al cuerpo." }, types: { title: "Orígenes y Tipos Comunes", intro: "El tipo depende de en qué parte del corazón se origina la señal errónea:", items: ["Taquicardia sinusal (un aumento rápido pero normal del latido, en respuesta a ejercicio, fiebre, estrés, miedo intenso, anemia o cafeína; el 'marcapasos' natural funciona bien, solo que rápido)", "Taquicardia Supraventricular - TSV (episodios repentinos de latidos muy rápidos originados en las cavidades superiores del corazón; comunes en jóvenes y a menudo no letales)", "Fibrilación auricular y Aleteo auricular (latidos caóticos, rápidos e irregulares en las aurículas, con alto riesgo de coágulos y ACV)", "Taquicardia Ventricular - TV (originada en las cavidades inferiores de bombeo; es extremadamente peligrosa y puede escalar rápidamente a fibrilación ventricular, causando paro cardíaco y muerte súbita)"], note: "" }, diagnosis: { title: "Detección Eléctrica", intro: "El cardiólogo necesita capturar el episodio para diagnosticarlo:", items: ["Electrocardiograma (ECG) en reposo (la prueba fundamental para registrar el ritmo eléctrico instantáneo)", "Monitor Holter o grabadora de eventos (dispositivo portátil para grabar el corazón durante 24h a 30 días, esencial si las taquicardias van y vienen)", "Ecocardiograma (ultrasonido para verificar la estructura y fuerza del músculo cardíaco)", "Prueba de esfuerzo y análisis de sangre (para descartar hipertiroidismo o problemas de electrolitos)"], note: "" }, treatment: { title: "Frenar el Ritmo y Prevención", intro: "El tratamiento busca ralentizar los latidos y evitar futuros episodios:", subsections: [ { title: "Opciones Médicas y Quirúrgicas", items: ["Maniobras vagales (técnicas físicas como toser fuerte o poner hielo en la cara para estimular el nervio vago y frenar ciertas TSV)", "Medicamentos antiarrítmicos o betabloqueantes (para enlentecer el pulso y estabilizar los canales eléctricos)", "Cardioversión eléctrica (choque eléctrico bajo sedación para 'reiniciar' el ritmo en urgencias)", "Ablación con catéter (procedimiento invasivo muy efectivo donde se queman con radiofrecuencia las células cardíacas específicas que están creando las chispas erróneas)", "Desfibrilador Automático Implantable (DAI) (marcapasos interno de rescate para pacientes con riesgo de taquicardia ventricular mortal)"] } ], note: "Evitar detonantes como drogas estimulantes (cocaína), bebidas energéticas excesivas, tabaco y alcohol es vital." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Algunas taquicardias son inofensivas (como por nervios), pero Llama al 911 o acude a urgencias si un ritmo cardíaco acelerado (palpitaciones) se presenta repentinamente junto con:", items: ["Dolor, presión o molestia en el pecho (posible infarto)", "Dificultad aguda para respirar o sensación de asfixia", "Mareos severos, aturdimiento extremo, o si sientes que estás a punto de desmayarte", "Pérdida de conocimiento o desmayo real (síncope)"] }, symptoms: { title: "Síntomas Clínicos", intro: "Al no bombear bien, el cuerpo alerta de la falta de sangre:", groups: [ { name: "Señales Físicas", items: ["Sensación de que el corazón late desbocado, aletea o da saltos bruscos en el pecho (palpitaciones)", "Pulso acelerado perceptible en el cuello o la muñeca", "Falta de aire, debilidad repentina y fatiga inusual", "Mareo ligero o sensación de desvanecimiento"] } ], warning: "Una taquicardia ventricular sostenida se convierte en paro cardíaco en cuestión de minutos." } },
'Leucemia': { intro: "La leucemia es un tipo de cáncer en la sangre que comienza en la médula ósea, donde se producen las células sanguíneas. Requiere diagnóstico temprano y tratamiento especializado para manejar la proliferación anormal de glóbulos blancos.", whatIs: { title: "¿Qué es la Leucemia?", text: "La leucemia es un cáncer de los tejidos que forman la sangre en el cuerpo, incluyendo la médula ósea y el sistema linfático. Provoca que la médula ósea produzca una gran cantidad de glóbulos blancos anormales que no funcionan correctamente." }, symptoms: { title: "Síntomas Comunes de la Leucemia", intro: "Los síntomas pueden ser sutiles al principio y varían según el tipo de leucemia:", groups: [ { name: "Síntomas sistémicos", items: ["Fiebre o escalofríos", "Fatiga persistente y debilidad", "Pérdida de peso sin intentarlo", "Sudoración excesiva, especialmente de noche"] }, { name: "Síntomas específicos", items: ["Infecciones frecuentes o graves", "Tendencia a sangrar o formar hematomas con facilidad", "Ganglios linfáticos inflamados", "Dolor en los huesos o articulaciones"] } ], warning: "Los síntomas iniciales pueden parecerse a los de una gripe común; si no desaparecen, es crucial consultar a un médico." }, types: { title: "Tipos de Leucemia", intro: "La leucemia se clasifica según su velocidad de progresión y el tipo de célula afectada:", items: ["Leucemia linfoblástica aguda (LLA)", "Leucemia mieloide aguda (LMA)", "Leucemia linfocítica crónica (LLC)", "Leucemia mieloide crónica (LMC)"], note: "Las leucemias agudas progresan rápidamente, mientras que las crónicas empeoran lentamente." }, causes: { title: "Causas y Factores de Riesgo", intro: "No se conoce la causa exacta, pero existen factores que aumentan el riesgo:", items: ["Tratamientos oncológicos previos (quimioterapia o radioterapia)", "Trastornos genéticos como el síndrome de Down", "Exposición a ciertos químicos (como el benceno)", "Antecedentes familiares de leucemia", "Tabaquismo (especialmente para la LMA)"] }, diagnosis: { title: "¿Cómo se Diagnostica la Leucemia?", intro: "El proceso diagnóstico suele incluir:", items: ["Análisis de sangre (hemograma completo)", "Aspirado y biopsia de médula ósea", "Punción lumbar (en algunos casos)", "Pruebas genéticas y moleculares de las células"], note: "La biopsia de médula ósea es la prueba definitiva para confirmar el diagnóstico." }, treatment: { title: "Tratamientos para la Leucemia", intro: "El tratamiento depende del tipo, edad y estado de salud general:", subsections: [ { title: "Opciones comunes", items: ["Quimioterapia (tratamiento principal)", "Terapia dirigida o biológica", "Radioterapia", "Trasplante de células madre (médula ósea)"] } ], note: "El tratamiento suele ser prolongado e involucra un equipo oncológico multidisciplinario." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención médica inmediata si presentas:", items: ["Fiebre alta persistente", "Sangrado inusual o que no se detiene", "Moretones repentinos sin causa aparente", "Infecciones recurrentes que no mejoran"] } },
'Drogadicción': { intro: "La drogadicción, también llamada trastorno por consumo de sustancias, es una enfermedad crónica que afecta el cerebro y el comportamiento humano. Interfiere severamente con la capacidad de controlar el uso de medicamentos o drogas (legales o ilegales).", whatIs: { title: "¿Qué es la Drogadicción?", text: "Es un trastorno cerebral que se caracteriza por la búsqueda y el consumo compulsivo de sustancias, a pesar de las consecuencias nocivas. Provoca cambios en la estructura y el funcionamiento del cerebro que pueden ser duraderos." }, symptoms: { title: "Síntomas Comunes de la Drogadicción", intro: "Los síntomas abarcan cambios conductuales, físicos y emocionales:", groups: [ { name: "Síntomas conductuales", items: ["Necesidad intensa de consumir la droga", "Incapacidad para detener el consumo", "Gastar dinero que no se tiene en drogas", "Descuidar responsabilidades laborales o familiares"] }, { name: "Síntomas físicos", items: ["Tolerancia (necesitar más cantidad para el mismo efecto)", "Síntomas de abstinencia al detener el consumo", "Cambios bruscos de peso", "Deterioro del aspecto físico y la higiene"] } ], warning: "La sobredosis es una emergencia médica potencialmente mortal; requiere intervención inmediata." }, types: { title: "Tipos de Sustancias Comunes", intro: "La adicción puede desarrollarse hacia diferentes tipos de sustancias:", items: ["Depresores (alcohol, benzodiazepinas)", "Estimulantes (cocaína, metanfetamina)", "Opioides (heroína, fentanilo, analgésicos recetados)", "Alucinógenos (LSD, psilocibina)", "Cannabinoides (marihuana)"], note: "La adicción a medicamentos recetados es tan grave como la adicción a drogas ilegales." }, causes: { title: "Causas y Factores de Riesgo", intro: "La adicción surge por una combinación compleja de factores:", items: ["Genética y antecedentes familiares", "Entorno social y presión de grupo", "Traumas o abuso en la infancia", "Trastornos de salud mental concurrentes (depresión, ansiedad)", "Exposición temprana a las drogas"] }, diagnosis: { title: "¿Cómo se Diagnostica la Drogadicción?", intro: "El diagnóstico requiere una evaluación exhaustiva:", items: ["Evaluación psiquiátrica o psicológica", "Revisión de los criterios del DSM-5", "Análisis de sangre u orina (para detectar sustancias en el cuerpo)", "Historial médico y social detallado"], note: "El reconocimiento del problema por parte del paciente es a menudo el paso más difícil hacia el diagnóstico." }, treatment: { title: "Tratamientos para la Drogadicción", intro: "El tratamiento debe ser personalizado y a menudo incluye:", subsections: [ { title: "Opciones comunes", items: ["Desintoxicación médica (manejo de la abstinencia)", "Terapias conductuales (individual y familiar)", "Medicación (para adicciones específicas como opioides o alcohol)", "Grupos de apoyo y rehabilitación a largo plazo"] } ], note: "La recuperación es un proceso continuo; las recaídas son posibles pero manejables." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es vital buscar ayuda cuando:", items: ["El consumo afecta tus relaciones, trabajo o salud", "Sientes que no puedes dejar de consumir", "Experimentas síndrome de abstinencia al no consumir", "Tú o alguien más corre peligro debido al consumo"] } },
'Acidez': { intro: "La acidez es una sensación de ardor incómoda en el pecho, justo detrás del esternón, que suele presentarse después de comer. Aunque episodios ocasionales son comunes, cuando es frecuente puede indicar la presencia de enfermedad por reflujo gastroesofágico (ERGE).", whatIs: { title: "¿Qué es la Acidez?", text: "La acidez estomacal se produce cuando el ácido del estómago regresa hacia el tubo que transporta los alimentos desde la boca hasta el estómago (esófago). Este ácido irrita el revestimiento del esófago, causando la sensación de quemazón." }, symptoms: { title: "Síntomas Comunes de la Acidez", intro: "Los síntomas suelen empeorar por la noche o al estar recostado:", groups: [ { name: "Síntomas principales", items: ["Ardor en el pecho (pirosis) después de comer", "Sabor amargo o ácido en la garganta o boca", "Dolor que empeora al acostarse o inclinarse hacia adelante"] }, { name: "Síntomas relacionados", items: ["Tos crónica", "Ronquera o dolor de garganta", "Dificultad ocasional para tragar"] } ], warning: "Si la acidez se acompaña de dolor en el brazo, mandíbula o dificultad para respirar, busca ayuda urgente, ya que puede confundirse con un ataque cardíaco." }, types: { title: "Tipos de Problemas Relacionados con la Acidez", intro: "La acidez se puede clasificar según su frecuencia y severidad:", items: ["Acidez ocasional (desencadenada por ciertos alimentos)", "Enfermedad por reflujo gastroesofágico (ERGE)", "Reflujo laringofaríngeo (ácido que llega a la laringe)"], note: "La ERGE requiere tratamiento médico prolongado para evitar daños en el esófago." }, causes: { title: "Causas y Factores de Riesgo", intro: "Varios factores pueden relajar el esfínter esofágico o aumentar el ácido:", items: ["Alimentos picantes, grasos, fritos o cítricos", "Consumo de chocolate, menta, café o alcohol", "Sobrepeso u obesidad", "Embarazo", "Acostarse inmediatamente después de comer", "Tabaquismo"] }, diagnosis: { title: "¿Cómo se Diagnostica la Acidez?", intro: "Para la acidez crónica (ERGE), los médicos pueden usar:", items: ["Historial clínico y evaluación de síntomas", "Endoscopia superior", "Monitoreo del pH ambulatorio", "Manometría esofágica (para evaluar los movimientos musculares)"], note: "La acidez ocasional suele diagnosticarse simplemente por los síntomas reportados." }, treatment: { title: "Tratamientos para la Acidez", intro: "El manejo suele ir de lo más simple a lo más complejo:", subsections: [ { title: "Opciones comunes", items: ["Cambios en la dieta (evitar desencadenantes)", "Antiácidos de venta libre", "Bloqueadores H2 (famotidina, etc.)", "Inhibidores de la bomba de protones (omeprazol, pantoprazol)"] } ], note: "Elevar la cabeza al dormir y perder peso son cambios de estilo de vida muy efectivos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico si:", items: ["La acidez ocurre más de dos veces por semana", "Los medicamentos de venta libre no alivian los síntomas", "Tienes dificultad o dolor al tragar", "Presentas pérdida de peso inexplicable"] } },
'Contractura de Dupuytren': { intro: "La contractura de Dupuytren es una deformidad de la mano que se desarrolla lentamente con el paso de los años. Afecta la capa de tejido que se encuentra debajo de la piel de la palma de la mano, causando que uno o más dedos se doblen hacia la palma.", whatIs: { title: "¿Qué es la Contractura de Dupuytren?", text: "Es una afección progresiva donde se forman nódulos gruesos de tejido en la palma de la mano. Con el tiempo, estos nódulos crean cordones de tejido duro que tiran de los dedos, generalmente el anular y el meñique, impidiendo que se estiren por completo." }, symptoms: { title: "Síntomas Comunes de la Contractura de Dupuytren", intro: "La afección progresa en diferentes etapas con síntomas particulares:", groups: [ { name: "Primeras etapas", items: ["Nódulos bajo la piel de la palma", "Sensibilidad inicial en la zona", "Hoyuelos o arrugas en la piel de la palma"] }, { name: "Etapas avanzadas", items: ["Cordones gruesos de tejido en la palma", "Incapacidad para aplanar la mano sobre una mesa", "Dedos permanentemente flexionados hacia la palma"] } ], warning: "Rara vez causa dolor, pero la pérdida de función de la mano puede ser severa." }, types: { title: "Fases de la Enfermedad", intro: "Más que tipos, la enfermedad se clasifica por su etapa de evolución:", items: ["Fase nodular (formación de bultos)", "Fase de cordón (tejido se engrosa formando bandas)", "Fase de contractura (los dedos se curvan permanentemente)"], note: "No todos los pacientes con nódulos desarrollan la contractura de los dedos." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta es desconocida, pero tiene un fuerte componente genético:", items: ["Herencia (antecedentes familiares)", "Ascendencia del norte de Europa", "Ser hombre y mayor de 50 años", "Diabetes", "Tabaquismo y consumo de alcohol"] }, diagnosis: { title: "¿Cómo se Diagnostica la Contractura de Dupuytren?", intro: "El diagnóstico es fundamentalmente clínico e incluye:", items: ["Examen físico visual de las manos", "Palpación de la palma para buscar nódulos o cordones", "Prueba de aplanamiento de la mano sobre una superficie ('mesa test')", "Evaluación de la movilidad de los dedos"], note: "Casi nunca se requieren radiografías o resonancias magnéticas para esta afección." }, treatment: { title: "Tratamientos para la Contractura de Dupuytren", intro: "Si no hay contractura severa, solo se observa. Si afecta la función, se usa:", subsections: [ { title: "Opciones comunes", items: ["Inyecciones de esteroides (para reducir la inflamación temprana)", "Inyección de colagenasa (medicamento que disuelve el cordón)", "Fasciotomía con aguja (romper el tejido a través de la piel)", "Cirugía (extirpación del tejido afectado)"] } ], note: "La recurrencia es común, incluso después de un tratamiento exitoso." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Se recomienda acudir al especialista cuando:", items: ["No puedes colocar la mano plana sobre una mesa", "La curvatura de los dedos interfiere con tus actividades diarias", "Sientes dolor (aunque no es lo habitual)", "Notas un avance rápido de la deformidad"] } },
'Insuficiencia venosa crónica': { intro: "La insuficiencia venosa crónica (IVC) es un problema prolongado en el cual las venas no pueden bombear suficiente sangre rica en oxígeno de vuelta al corazón, lo que causa que la sangre se acumule (estasis) en las piernas.", whatIs: { title: "¿Qué es la Insuficiencia Venosa Crónica?", text: "Ocurre cuando las válvulas de las venas de las piernas, que evitan que la sangre retroceda, están dañadas o no funcionan bien. Esto provoca que la sangre se acumule en las extremidades inferiores, aumentando la presión en las venas y provocando síntomas crónicos." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen empeorar después de estar de pie por largos períodos:", groups: [ { name: "Síntomas iniciales", items: ["Hinchazón (edema) en piernas y tobillos", "Sensación de pesadez o cansancio en las piernas", "Dolor o calambres en las piernas", "Venas varicosas visibles"] }, { name: "Síntomas avanzados", items: ["Cambios en el color de la piel (pigmentación marrón)", "Piel engrosada y endurecida", "Úlceras venosas, especialmente cerca de los tobillos"] } ], warning: "Si notas una úlcera o herida en la pierna que no sana, es vital buscar atención médica para evitar infecciones graves." }, types: { title: "Clasificación (CEAP)", intro: "Se clasifica según la gravedad clínica de los signos visibles:", items: ["Estadio 1: Arañas vasculares (telangiectasias)", "Estadio 2: Venas varicosas", "Estadio 3: Edema (hinchazón)", "Estadio 4: Cambios en la piel (pigmentación)", "Estadio 5/6: Úlceras cicatrizadas o activas"], note: "El tratamiento temprano puede evitar que la condición progrese a los estadios más graves." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño en las válvulas venosas puede ser provocado por:", items: ["Trombosis venosa profunda (coágulo previo)", "Edad avanzada", "Antecedentes familiares", "Obesidad", "Embarazo", "Trabajos que requieren estar de pie o sentado prolongadamente"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista vascular evaluará tu circulación mediante:", items: ["Examen físico minucioso de las piernas", "Ecografía Doppler venosa (para ver el flujo sanguíneo y las válvulas)", "Historial clínico sobre coágulos previos"], note: "La ecografía es una prueba indolora y es el estándar de oro para este diagnóstico." }, treatment: { title: "Tratamientos para la Insuficiencia Venosa Crónica", intro: "El objetivo es mejorar el flujo sanguíneo y evitar complicaciones:", subsections: [ { title: "Opciones comunes", items: ["Uso de medias de compresión graduada", "Elevación de las piernas al descansar", "Medicamentos flebotónicos o para prevenir coágulos", "Procedimientos mínimamente invasivos (ablación, escleroterapia) o cirugía"] } ], note: "El cuidado meticuloso de la piel es esencial para prevenir úlceras." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico si presentas:", items: ["Hinchazón dolorosa en una o ambas piernas", "Cambios oscuros en el color de la piel de las pantorrillas", "Heridas en los tobillos que tardan en sanar", "Las venas varicosas duelen, sangran o están enrojecidas"] } },
'Hipoacusia en bebés': { intro: "La hipoacusia en bebés es la pérdida total o parcial de la capacidad auditiva presente desde el nacimiento o desarrollada en los primeros meses de vida. Su detección e intervención tempranas son críticas para el desarrollo del lenguaje y la comunicación.", whatIs: { title: "¿Qué es la Hipoacusia en Bebés?", text: "Es una deficiencia auditiva que puede afectar a uno o ambos oídos. Dado que los bebés aprenden a hablar imitando los sonidos de su entorno, cualquier grado de pérdida de audición puede retrasar significativamente su desarrollo cognitivo y del lenguaje." }, symptoms: { title: "Signos Comunes de Hipoacusia", intro: "Los síntomas varían según la edad del bebé, pero incluyen:", groups: [ { name: "De 0 a 3 meses", items: ["No se sobresalta con los ruidos fuertes", "No reacciona a la voz de sus padres", "No produce sonidos de arrullo"] }, { name: "De 4 a 12 meses", items: ["No voltea la cabeza hacia la fuente de un sonido", "Deja de balbucear o el balbuceo no se vuelve más complejo", "No responde a su nombre o a palabras familiares como 'no'"] } ], warning: "Los problemas de audición a menudo son invisibles, de ahí la importancia del cribado neonatal universal." }, types: { title: "Tipos de Hipoacusia", intro: "Se clasifica según la parte del oído afectada:", items: ["Hipoacusia conductiva (problema en el oído externo o medio)", "Hipoacusia neurosensorial (daño en el oído interno o nervio auditivo)", "Hipoacusia mixta (combinación de ambas)"], note: "La conductiva a menudo es temporal y tratable, mientras que la neurosensorial suele ser permanente." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas pueden ser genéticas o adquiridas:", items: ["Factores genéticos o hereditarios", "Infecciones maternas durante el embarazo (rubéola, citomegalovirus, sífilis)", "Bajo peso al nacer o nacimiento prematuro", "Falta de oxígeno al nacer", "Ictericia grave (niveles altos de bilirrubina)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se realiza mediante pruebas objetivas que no requieren respuesta del bebé:", items: ["Emisiones otoacústicas (EOA)", "Potenciales evocados auditivos del tronco encefálico (PEATC)", "Cribado auditivo neonatal (realizado antes del alta hospitalaria)"], note: "Si un bebé no pasa el cribado inicial, se requieren pruebas audiológicas completas antes de los 3 meses de edad." }, treatment: { title: "Tratamientos e Intervenciones", intro: "El tratamiento depende de la causa y el tipo de pérdida auditiva:", subsections: [ { title: "Opciones comunes", items: ["Audífonos pediátricos (incluso desde el primer mes de vida)", "Implantes cocleares (para hipoacusia neurosensorial profunda)", "Tratamiento médico/quirúrgico (para infecciones o problemas anatómicos)", "Terapia del lenguaje y aprendizaje de lengua de señas"] } ], note: "El objetivo es iniciar la intervención antes de que el bebé cumpla los 6 meses de edad." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta al pediatra inmediatamente si:", items: ["Tu bebé no pasó el cribado auditivo en el hospital", "Sientes que el bebé no responde a sonidos o a tu voz", "El desarrollo del lenguaje (balbuceo, primeras palabras) parece retrasado", "Ha tenido infecciones de oído recurrentes"] } },
'Trastornos en la alimentación del anciano': { intro: "Los trastornos en la alimentación en adultos mayores abarcan diversas dificultades para ingerir alimentos adecuadamente, lo que lleva a un déficit nutricional. Es un problema geriátrico crucial que impacta la calidad de vida, la inmunidad y la mortalidad.", whatIs: { title: "¿Qué son los Trastornos en la Alimentación del Anciano?", text: "Son condiciones en las cuales un adulto mayor presenta una ingesta calórica o nutricional insuficiente. A diferencia de los trastornos psiquiátricos clásicos de alimentación, en la tercera edad suelen ser secundarios a problemas físicos, emocionales, sociales o neurológicos." }, symptoms: { title: "Síntomas y Signos Comunes", intro: "Las señales de alerta pueden ser físicas y de comportamiento:", groups: [ { name: "Signos físicos", items: ["Pérdida de peso involuntaria", "Desgaste muscular (sarcopenia)", "Fatiga constante o debilidad", "Cicatrización lenta de heridas", "Problemas de masticación o tos al comer"] }, { name: "Signos conductuales", items: ["Falta de apetito o negarse a comer", "Dejar comida intacta en el plato", "Aislamiento social durante las comidas", "Quejas de que la comida no tiene sabor"] } ], warning: "La desnutrición en ancianos puede llevar a caídas, hospitalizaciones frecuentes e incluso la muerte." }, types: { title: "Tipos de Trastornos y Dificultades", intro: "Las alteraciones de la alimentación en la tercera edad incluyen:", items: ["Anorexia del envejecimiento (pérdida de apetito fisiológica)", "Disfagia (dificultad para tragar)", "Desnutrición calórico-proteica", "Trastornos de la masticación (edentulismo)"], note: "La depresión y el deterioro cognitivo (como en el Alzheimer) son causas mayores de estos trastornos." }, causes: { title: "Causas y Factores de Riesgo", intro: "Generalmente es un problema multifactorial conocido como las '9 D':", items: ["Dentición (mala salud oral)", "Disfagia", "Diarrea o problemas gastrointestinales", "Depresión o demencia", "Disfunción física (artritis que impide cocinar)", "Drogas (efectos secundarios de polifarmacia)", "Dinero (pobreza)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La valoración geriátrica integral es esencial e incluye:", items: ["Herramientas de cribado nutricional (MNA - Mini Nutritional Assessment)", "Examen físico detallado y evaluación del índice de masa corporal (IMC)", "Análisis de sangre (para revisar proteínas, vitaminas y función orgánica)", "Evaluación de la deglución (si hay tos al comer)"], note: "Es vital revisar los medicamentos que el paciente toma, ya que muchos quitan el apetito." }, treatment: { title: "Tratamientos e Intervenciones", intro: "El enfoque es multidisciplinario y orientado a la causa subyacente:", subsections: [ { title: "Opciones comunes", items: ["Modificación de texturas de alimentos (dietas blandas o purés)", "Suplementos nutricionales orales", "Revisión y ajuste de medicamentos", "Asistencia durante las comidas y socialización", "Apoyo psicológico o tratamiento para la depresión"] } ], note: "Las comidas deben ser nutritivas, apetitosas y pequeñas pero frecuentes." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Se debe buscar atención médica geriátrica cuando:", items: ["El anciano ha perdido peso sin intentarlo (ej. ropa floja)", "Tose frecuentemente al tragar líquidos o sólidos", "Se niega constantemente a comer durante varios días", "Parece deshidratado, letárgico o confundido"] } },
'Lesión cerebral en bebés': { intro: "Una lesión cerebral en bebés se refiere a cualquier daño en el cerebro que ocurra durante el embarazo, el parto o en la infancia temprana. Dependiendo de la severidad y el área afectada, puede causar secuelas físicas, cognitivas o del desarrollo a largo plazo.", whatIs: { title: "¿Qué es una Lesión Cerebral en Bebés?", text: "Es el daño a las células cerebrales inmaduras debido a la falta de oxígeno, traumas físicos, infecciones o problemas metabólicos. Este daño puede interrumpir el desarrollo normal del cerebro y provocar condiciones como la parálisis cerebral." }, symptoms: { title: "Síntomas y Signos de Alerta", intro: "Los síntomas pueden notarse inmediatamente después de nacer o meses después:", groups: [ { name: "En el recién nacido", items: ["Dificultad para respirar por sí mismo", "Convulsiones", "Tono muscular anormal (muy rígido o muy flácido)", "Letargo extremo o dificultad para alimentarse"] }, { name: "En el desarrollo posterior", items: ["Retraso en los hitos del desarrollo (gatear, sentarse, caminar)", "Movimientos corporales asimétricos", "Problemas de audición o visión", "Dificultades en el aprendizaje o el comportamiento"] } ], warning: "Cualquier convulsión en un bebé requiere atención médica de emergencia inmediata." }, types: { title: "Tipos Comunes de Lesiones Cerebrales", intro: "Las lesiones se clasifican según su causa y fisiología:", items: ["Encefalopatía Hipóxico-Isquémica (EHI - falta de oxígeno y flujo sanguíneo)", "Hemorragia intracraneal (sangrado en el cerebro)", "Leucomalacia periventricular (LPV - daño a la materia blanca)", "Lesión cerebral traumática (por accidentes o síndrome del bebé sacudido)"], note: "La EHI es una de las principales causas de daño cerebral durante el parto." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño puede surgir de diversas complicaciones obstétricas o posnatales:", items: ["Asfixia perinatal (complicaciones con el cordón umbilical o placenta)", "Infecciones maternas (citomegalovirus, herpes) o neonatales (meningitis)", "Nacimiento prematuro extremo", "Ictericia no tratada (kernícterus)", "Traumatismo físico durante un parto difícil"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es crítico e involucra:", items: ["Ecografía craneal (especialmente en prematuros)", "Resonancia magnética (RM) del cerebro (la imagen más detallada)", "Electroencefalograma (EEG) para detectar convulsiones", "Examen neurológico clínico continuo"], note: "Las imágenes por RM a menudo revelan el momento y la extensión del daño cerebral." }, treatment: { title: "Tratamientos", intro: "El tejido cerebral muerto no puede regenerarse, por lo que el tratamiento se centra en minimizar el daño continuo y maximizar la función:", subsections: [ { title: "Opciones comunes", items: ["Hipotermia terapéutica (enfriamiento cerebral si se inicia poco después del nacimiento)", "Control de convulsiones con medicamentos", "Terapia física, ocupacional y del habla temprana", "Soporte nutricional y respiratorio"] } ], note: "La neuroplasticidad del cerebro infantil permite que otras áreas asuman algunas funciones dañadas si se recibe terapia temprana." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a emergencias si tu bebé:", items: ["Sufre cualquier tipo de golpe severo en la cabeza", "Presenta movimientos rítmicos anormales (convulsiones)", "Muestra una flacidez repentina o letargo inusual", "No alcanza de manera evidente los hitos del desarrollo según su edad"] } },
'Artritis psoriásica': { intro: "La artritis psoriásica es un tipo de artritis inflamatoria que afecta a algunas personas que tienen psoriasis, una enfermedad de la piel que causa manchas rojas escamosas. Requiere tratamiento continuo para prevenir el daño articular permanente.", whatIs: { title: "¿Qué es la Artritis Psoriásica?", text: "Es una enfermedad autoinmune crónica en la que el sistema inmunológico ataca las células y tejidos sanos, causando inflamación en las articulaciones y sobreproducción de células cutáneas. Puede afectar cualquier articulación del cuerpo." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden fluctuar (brotes y remisiones) e incluyen:", groups: [ { name: "Síntomas articulares", items: ["Articulaciones hinchadas, rígidas y dolorosas", "Hinchazón en los dedos de manos o pies que parecen 'salchichas' (dactilitis)", "Dolor en la parte baja de la espalda o el cuello", "Dolor en los puntos de anclaje de tendones (entesitis)"] }, { name: "Síntomas relacionados", items: ["Placas escamosas en la piel (psoriasis)", "Cambios en las uñas (hoyuelos, separación del lecho ungueal)", "Fatiga generalizada", "Inflamación ocular (uveítis)"] } ], warning: "Si no se trata, la inflamación prolongada puede destruir permanentemente la articulación." }, types: { title: "Patrones de Afectación", intro: "La enfermedad puede presentarse de varias formas:", items: ["Oligoarticular asimétrica (afecta pocas articulaciones de un solo lado)", "Poliarticular simétrica (similar a la artritis reumatoide)", "Predominante en articulaciones interfalángicas distales (cerca de las uñas)", "Espondilitis (afecta la columna vertebral)", "Artritis mutilante (una forma rara y destructiva)"], note: "El patrón de la enfermedad puede cambiar a lo largo del tiempo." }, causes: { title: "Causas y Factores de Riesgo", intro: "Al igual que otras enfermedades autoinmunes, es una combinación de factores:", items: ["Tener psoriasis (el mayor factor de riesgo)", "Antecedentes familiares (fuerte componente genético, como el HLA-B27)", "Desencadenantes ambientales (infecciones, estrés físico o trauma)", "Tener entre 30 y 50 años"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es principalmente clínico e incluye para descartar otras artritis:", items: ["Examen de las articulaciones, piel y uñas", "Radiografías (para ver daños óseos característicos)", "Análisis de sangre (Factor Reumatoide suele ser negativo, PCR elevada)", "Líquido articular (para descartar gota)"], note: "Un diagnóstico temprano por parte de un reumatólogo es vital." }, treatment: { title: "Tratamientos", intro: "El objetivo es controlar la inflamación y prevenir el daño articular:", subsections: [ { title: "Opciones comunes", items: ["AINEs (antiinflamatorios no esteroideos para el dolor leve)", "FAMEs (fármacos antirreumáticos modificadores de la enfermedad como el metotrexato)", "Terapias biológicas (inhibidores de TNF, interleucinas)", "Fisioterapia y protección articular"] } ], note: "El tratamiento a menudo requiere colaboración entre un reumatólogo y un dermatólogo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico si tienes psoriasis y desarrollas:", items: ["Dolor o hinchazón inexplicable en las articulaciones", "Rigidez matutina persistente", "Hinchazón completa de un dedo de la mano o del pie", "Cambios notables en la textura o color de las uñas"] } },
'Linfoma no Hodgkin': { intro: "El linfoma no Hodgkin es un tipo de cáncer del sistema linfático, una parte crucial del sistema inmunológico que ayuda al cuerpo a combatir infecciones. Los tumores se desarrollan a partir de glóbulos blancos llamados linfocitos.", whatIs: { title: "¿Qué es el Linfoma no Hodgkin?", text: "Es un término general para un grupo diverso de cánceres de la sangre. Se caracteriza por el crecimiento descontrolado de linfocitos (células B o células T) que se acumulan en los ganglios linfáticos y otros tejidos u órganos." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden ser generales y parecerse a otras enfermedades:", groups: [ { name: "Síntomas físicos", items: ["Inflamación indolora de los ganglios linfáticos (cuello, axilas o ingle)", "Hinchazón o dolor abdominal", "Dolor en el pecho, tos o dificultad para respirar"] }, { name: "Síntomas 'B' (sistémicos)", items: ["Fiebre persistente sin infección aparente", "Sudoración nocturna profusa", "Pérdida de peso significativa e inexplicable", "Fatiga severa"] } ], warning: "La presencia de síntomas 'B' indica a menudo una enfermedad más avanzada y requiere evaluación médica pronta." }, types: { title: "Tipos de Linfoma no Hodgkin", intro: "Existen decenas de subtipos, pero generalmente se dividen por su agresividad y célula de origen:", items: ["Linfomas de células B (como el Linfoma difuso de células B grandes, que es agresivo)", "Linfomas foliculares (de crecimiento lento o indolentes)", "Linfomas de células T (menos comunes)", "Linfoma del manto"], note: "Saber el subtipo exacto es crucial, ya que dicta el protocolo de tratamiento." }, causes: { title: "Causas y Factores de Riesgo", intro: "Aunque la causa a menudo se desconoce, los factores de riesgo incluyen:", items: ["Edad avanzada (más común en mayores de 60 años)", "Sistema inmunológico debilitado (VIH/SIDA, trasplantes)", "Infecciones virales previas (Epstein-Barr, Hepatitis C)", "Exposición a ciertos pesticidas o herbicidas", "Historial de otras enfermedades autoinmunes"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere pruebas específicas del tejido afectado:", items: ["Biopsia de un ganglio linfático (extirpación total o parcial, es la prueba de confirmación)", "Análisis de sangre y orina", "Pruebas de imagen (TC, PET, resonancia magnética)", "Aspirado y biopsia de médula ósea (para evaluar si el cáncer se ha propagado)"], note: "Una biopsia con aguja fina a menudo no es suficiente para un diagnóstico preciso de este linfoma." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del subtipo, el estadio y la salud del paciente:", subsections: [ { title: "Opciones comunes", items: ["Quimioterapia (a menudo combinada)", "Inmunoterapia / Terapia dirigida (como Rituximab)", "Radioterapia (para zonas localizadas)", "Trasplante de células madre (para casos que recaen)", "Espera vigilante (solo observación para linfomas indolentes asintomáticos)"] } ], note: "Las tasas de supervivencia han mejorado significativamente gracias a las nuevas terapias biológicas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes consultar a un médico si presentas:", items: ["Bultos en el cuello, axilas o ingle que no desaparecen en unas semanas", "Fiebres y sudores nocturnos recurrentes", "Pérdida de peso rápida sin dieta", "Dificultad prolongada para respirar o tos crónica inexplicable"] } },
'Ausencia de la menstruación': { intro: "La ausencia de la menstruación, conocida médicamente como amenorrea, no es una enfermedad en sí misma, sino un síntoma de otra condición subyacente. Puede ser normal en ciertas etapas de la vida, pero requiere evaluación si ocurre fuera de estas situaciones.", whatIs: { title: "¿Qué es la Amenorrea?", text: "Es la ausencia de períodos menstruales en una mujer en edad reproductiva. Se divide en primaria (cuando nunca ha comenzado la menstruación a los 15 años) y secundaria (cuando una mujer que menstruaba regularmente deja de hacerlo por tres meses o más)." }, symptoms: { title: "Síntomas Relacionados", intro: "El síntoma principal es no tener el período, pero dependiendo de la causa, pueden aparecer:", groups: [ { name: "Cambios físicos", items: ["Secreción de leche por los pezones (galactorrea)", "Caída del cabello", "Dolor pélvico", "Cambios en la visión"] }, { name: "Cambios hormonales", items: ["Crecimiento de vello facial excesivo (hirsutismo)", "Acné persistente", "Sofocos o sequedad vaginal"] } ], warning: "Si has sido sexualmente activa, el primer paso es descartar un embarazo." }, types: { title: "Tipos de Amenorrea", intro: "Se clasifica en dos tipos principales:", items: ["Amenorrea Primaria (no haber tenido la primera regla a los 15 años)", "Amenorrea Secundaria (interrupción de reglas previas por más de 3-6 meses)"], note: "La amenorrea secundaria es mucho más común." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas son variadas, desde lo natural hasta desequilibrios graves:", items: ["Causas naturales (embarazo, lactancia, menopausia)", "Trastornos del estilo de vida (estrés extremo, bajo peso corporal, ejercicio excesivo)", "Desequilibrios hormonales (Síndrome de Ovario Poliquístico, problemas de tiroides, tumores hipofisarios)", "Problemas estructurales (anomalías uterinas o vaginales)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico buscará la causa subyacente mediante:", items: ["Prueba de embarazo (el primer paso obligado)", "Análisis de sangre hormonales (prolactina, hormonas tiroideas, FSH, estrógeno)", "Ecografía pélvica", "Prueba de provocación con progestina (para ver si falta estrógeno)"], note: "Llevar un registro de tus ciclos previos y de tus hábitos de dieta/ejercicio ayudará al diagnóstico." }, treatment: { title: "Tratamientos para la Amenorrea", intro: "El tratamiento se enfoca exclusivamente en la causa subyacente:", subsections: [ { title: "Opciones comunes", items: ["Modificaciones de estilo de vida (reducir el estrés, ganar peso, moderar el ejercicio)", "Terapia de reemplazo hormonal (anticonceptivos orales)", "Medicamentos para trastornos específicos (tiroides, SOP)", "Cirugía (en caso de problemas estructurales o tumores)"] } ], note: "Restaurar la menstruación es importante para proteger la densidad ósea a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar consejo médico si:", items: ["Tus períodos se detienen abruptamente por más de tres ciclos", "Tienes 15 años y aún no has menstruado", "Experimentas dolor pélvico agudo o crónico", "Notas cambios físicos abruptos como crecimiento de vello facial"] } },
'Infección aguda de las vías urinarias (IVU aguda)': { intro: "Una infección aguda de las vías urinarias (IVU) es una infección dolorosa e incómoda en cualquier parte del sistema urinario (riñones, uréteres, vejiga o uretra). La mayoría de estas infecciones ocurren en las vías urinarias inferiores (vejiga y uretra).", whatIs: { title: "¿Qué es una IVU Aguda?", text: "Se produce cuando bacterias, comúnmente provenientes del tracto digestivo (como E. coli), ingresan a la uretra y se multiplican en la vejiga. Genera una respuesta inflamatoria aguda que causa síntomas molestos al orinar." }, symptoms: { title: "Síntomas Comunes de una IVU", intro: "Las IVU inferiores y superiores tienen algunos síntomas distintos:", groups: [ { name: "Síntomas de infección en la vejiga (Cistitis)", items: ["Necesidad intensa y constante de orinar", "Sensación de ardor al orinar (disuria)", "Orinar frecuentemente en pequeñas cantidades", "Orina turbia, oscura, o con olor fuerte", "Dolor pélvico (en mujeres)"] }, { name: "Síntomas de infección en los riñones (Pielonefritis)", items: ["Dolor en la parte superior de la espalda y los costados", "Fiebre alta y escalofríos", "Náuseas y vómitos"] } ], warning: "Si presentas fiebre, dolor de espalda o vómitos, la infección puede haber llegado a los riñones, lo cual es una emergencia que requiere atención médica rápida." }, types: { title: "Tipos de IVU", intro: "Dependiendo de la zona afectada se denominan de diferente manera:", items: ["Cistitis (infección de la vejiga)", "Uretritis (infección de la uretra)", "Pielonefritis (infección de los riñones)"], note: "Las infecciones renales son el tipo más grave de IVU." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las mujeres tienen mayor riesgo debido a que su uretra es más corta. Otros factores incluyen:", items: ["Actividad sexual", "Uso de ciertos métodos anticonceptivos (diafragmas, espermicidas)", "Menopausia (cambios en el tejido urinario por falta de estrógeno)", "Anomalías en las vías urinarias o bloqueos (como cálculos renales)", "Uso de catéteres urinarios"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es rápido y generalmente requiere:", items: ["Análisis de orina (para detectar glóbulos blancos, rojos o bacterias)", "Cultivo de orina (para identificar la bacteria exacta y qué antibiótico la elimina)"], note: "En infecciones recurrentes, se pueden solicitar ecografías o cistoscopias para descartar anomalías." }, treatment: { title: "Tratamientos", intro: "El tratamiento estándar son los antibióticos:", subsections: [ { title: "Opciones comunes", items: ["Antibióticos orales recetados por el médico (es vital completar el ciclo)", "Analgésicos urinarios (fenazopiridina para aliviar el ardor rápido)", "Aumento en el consumo de líquidos (para limpiar el tracto urinario)"] } ], note: "No abandones los antibióticos aunque te sientas mejor en el primer día; esto evita la resistencia bacteriana." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un médico o clínica si presentas:", items: ["Ardor y dolor agudo al orinar", "Sangre en la orina", "Fiebre con escalofríos", "Dolor punzante en la parte baja de la espalda o el costado"] } },
'Orzuelo': { intro: "Un orzuelo es un bulto rojo y doloroso cerca del borde del párpado que puede parecerse a un grano o una espinilla. Suele ser causado por una infección bacteriana y, aunque molesto, raramente es un problema grave y a menudo desaparece por sí solo.", whatIs: { title: "¿Qué es un Orzuelo?", text: "Es una inflamación localizada en el párpado originada por la infección de las glándulas sebáceas (glándulas de Zeis o de Meibomio) en la base de las pestañas, habitualmente causada por bacterias estafilococos." }, symptoms: { title: "Síntomas Comunes", intro: "El inicio suele ser repentino y los síntomas incluyen:", groups: [ { name: "Signos visibles", items: ["Un bulto rojo en el párpado, similar a un grano", "Hinchazón general del párpado", "Lagrimeo ocular", "Aparición de un punto amarillento (pus) en el centro del bulto"] }, { name: "Sensaciones", items: ["Dolor focalizado en el párpado", "Sensación de cuerpo extraño en el ojo", "Sensibilidad a la luz"] } ], warning: "Nunca aprietes, pinches ni intentes reventar un orzuelo, ya que la infección podría propagarse al resto del ojo." }, types: { title: "Tipos de Orzuelo", intro: "Se clasifican según su ubicación en el párpado:", items: ["Orzuelo externo (en la base de la pestaña, el más común)", "Orzuelo interno (dentro del párpado, en una glándula de Meibomio)"], note: "A veces se confunde con el chalazión, que es un quiste indoloro resultante de una glándula bloqueada (no infectada)." }, causes: { title: "Causas y Factores de Riesgo", intro: "La principal causa es la bacteria *Staphylococcus*, pero los riesgos incluyen:", items: ["Frotarse los ojos con las manos sucias", "Usar lentes de contacto sin desinfectarlos adecuadamente", "No quitarse el maquillaje de los ojos antes de dormir", "Uso de cosméticos viejos o caducados", "Padecer blefaritis (inflamación crónica del párpado) o rosácea"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Por lo general, no se requieren pruebas especiales:", items: ["Inspección visual del párpado y el ojo por parte de un médico", "Examen con luz para descartar otros problemas oculares"], note: "Un médico general o un oftalmólogo pueden diagnosticarlo a simple vista." }, treatment: { title: "Tratamientos para el Orzuelo", intro: "La mayoría mejoran en unos pocos días con cuidados en casa:", subsections: [ { title: "Opciones comunes", items: ["Compresas tibias aplicadas sobre el párpado cerrado (10-15 minutos, 3-4 veces al día)", "Limpieza suave del párpado", "Antibióticos en pomada o gotas (si no mejora o se agrava)", "Drenaje quirúrgico menor (realizado solo por un médico si no drena solo)"] } ], note: "Evita usar maquillaje para los ojos y lentes de contacto hasta que el orzuelo se haya curado por completo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico si:", items: ["El orzuelo no mejora después de 48 horas de cuidados en casa", "El enrojecimiento y la hinchazón se extienden a toda la mejilla o cara", "Tienes problemas en tu visión", "El orzuelo sangra excesivamente"] } },
'Dentición': { intro: "La dentición es el proceso natural por el cual los primeros dientes de un bebé (dientes de leche o temporales) comienzan a romper las encías. Suele empezar alrededor de los 6 meses, aunque puede variar, y a veces resulta un período incómodo tanto para el bebé como para los padres.", whatIs: { title: "¿Qué es la Dentición?", text: "Es el movimiento y la erupción de los dientes primarios a través de las encías del niño. Es un hito normal del desarrollo que ocurre gradualmente desde los primeros meses hasta aproximadamente los tres años de edad." }, symptoms: { title: "Síntomas Comunes de la Dentición", intro: "Algunos bebés no presentan molestias, pero otros pueden tener:", groups: [ { name: "Síntomas físicos en la boca", items: ["Encías rojas, inflamadas o sensibles", "Babeo excesivo", "Deseo de morder, masticar o chupar objetos duros"] }, { name: "Cambios de comportamiento", items: ["Irritabilidad y llanto sin razón aparente", "Problemas para dormir o despertares frecuentes", "Rechazo temporal a la comida debido a la molestia", "Frotarse las mejillas o tirar de las orejas"] } ], warning: "La dentición NO causa fiebre alta (más de 38°C), vómitos ni diarrea. Si el bebé presenta esto, se debe a una enfermedad, no a los dientes." }, types: { title: "Cronología de la Erupción", intro: "Aunque no hay 'tipos' de dentición, existen fases según los dientes:", items: ["Incisivos centrales inferiores y superiores (6-12 meses)", "Incisivos laterales (9-16 meses)", "Primeros molares (13-19 meses)", "Caninos o colmillos (16-23 meses)", "Segundos molares (23-33 meses)"], note: "El momento exacto varía, pero los dientes suelen salir en pares simétricos." }, causes: { title: "Proceso Biológico", intro: "La dentición es causada simplemente por la maduración del esqueleto facial:", items: ["Desarrollo biológico normal programado genéticamente", "Crecimiento de las raíces de los dientes que empujan la corona hacia las encías"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No requiere diagnóstico médico formal, los padres o pediatras lo notan por:", items: ["Examen visual y táctil de las encías (se siente un bulto duro bajo la encía)", "La aparición del borde blanco del diente"], note: "Los chequeos regulares con el pediatra confirman un desarrollo dental adecuado." }, treatment: { title: "Manejo y Alivio", intro: "El objetivo es aliviar la incomodidad temporal de las encías:", subsections: [ { title: "Opciones seguras", items: ["Frotar suavemente las encías con un dedo limpio o una gasa húmeda", "Ofrecer anillos de dentición fríos (no congelados)", "Alimentos fríos o purés (si ya come sólidos)", "Analgésicos pediátricos (paracetamol o ibuprofeno) solo bajo recomendación médica"] } ], note: "Evita geles anestésicos tópicos con benzocaína, collares de ámbar y remedios homeopáticos no regulados debido a riesgos de toxicidad o asfixia." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a tu pediatra o dentista pediátrico si:", items: ["El bebé tiene fiebre, diarrea o síntomas de resfriado (no es por la dentición)", "No ha salido ningún diente para los 15-18 meses", "La irritabilidad es extrema e inconsolable", "Observas un hematoma de erupción (quiste azulado) que causa mucho dolor"] } },
'Hipertensión pulmonar': { intro: "La hipertensión pulmonar es un tipo de presión arterial alta grave que afecta las arterias de los pulmones y el lado derecho del corazón. Requiere tratamiento continuo porque puede llevar a insuficiencia cardíaca y es potencialmente mortal.", whatIs: { title: "¿Qué es la Hipertensión Pulmonar?", text: "Ocurre cuando los pequeños vasos sanguíneos de los pulmones (arterias pulmonares) se estrechan, bloquean o destruyen. Esto hace que sea más difícil para la sangre fluir a través de los pulmones, aumentando la presión sanguínea y obligando al corazón a trabajar más duro." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas se desarrollan lentamente, a menudo pasan desapercibidos durante años:", groups: [ { name: "Síntomas respiratorios y cardíacos", items: ["Dificultad para respirar (disnea) al hacer ejercicio y luego en reposo", "Fatiga rápida y debilidad", "Dolor o presión en el pecho", "Palpitaciones cardíacas o frecuencia cardíaca acelerada"] }, { name: "Síntomas de insuficiencia avanzada", items: ["Mareos o episodios de desmayo (síncope)", "Hinchazón (edema) en los tobillos, piernas y ocasionalmente abdomen", "Coloración azulada en los labios y la piel (cianosis)"] } ], warning: "Los desmayos y el dolor de pecho al hacer esfuerzo son señales de alarma que requieren atención inmediata." }, types: { title: "Grupos de Hipertensión Pulmonar (OMS)", intro: "Se clasifica en 5 grupos según la causa subyacente:", items: ["Grupo 1: Hipertensión Arterial Pulmonar (HAP) (idiopática, genética o por drogas)", "Grupo 2: Causada por enfermedades del lado izquierdo del corazón", "Grupo 3: Causada por enfermedades pulmonares (EPOC, apnea del sueño)", "Grupo 4: Causada por coágulos sanguíneos crónicos (tromboembólica)", "Grupo 5: Causada por trastornos varios o inexplicables"], note: "Identificar el grupo correcto es esencial para elegir el tratamiento adecuado." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas varían dependiendo del grupo al que pertenezca:", items: ["Insuficiencia del lado izquierdo del corazón o enfermedad valvular", "Enfermedades pulmonares crónicas como EPOC o fibrosis", "Embolias pulmonares repetidas (coágulos)", "Enfermedades autoinmunes (esclerodermia, lupus)", "Uso de ciertos medicamentos para adelgazar o drogas ilegales", "Apnea del sueño severa"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "A menudo es difícil de diagnosticar tempranamente. Las pruebas incluyen:", items: ["Ecocardiograma (para ver el tamaño del corazón y estimar presiones)", "Cateterismo del corazón derecho (la prueba definitiva y más precisa)", "Pruebas de función pulmonar", "Gammagrafía de ventilación/perfusión (V/Q) para buscar coágulos"], note: "El cateterismo cardíaco es indispensable para confirmar el diagnóstico." }, treatment: { title: "Tratamientos para la Hipertensión Pulmonar", intro: "Aunque no tiene cura (excepto en algunos casos del Grupo 4), se puede manejar:", subsections: [ { title: "Opciones comunes", items: ["Medicamentos vasodilatadores y terapia dirigida a las vías moleculares (Grupo 1)", "Diuréticos y anticoagulantes", "Oxigenoterapia", "Tratamiento de la enfermedad subyacente (Grupos 2 y 3)", "Cirugía (tromboendarterectomía o trasplante de pulmón/corazón en casos graves)"] } ], note: "El tratamiento requiere el manejo de un centro especializado en hipertensión pulmonar." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca evaluación médica urgente si experimentas:", items: ["Falta de aire progresiva e inexplicable durante tus actividades diarias", "Desmayos o mareos intensos al subir escaleras", "Hinchazón severa y repentina en las piernas", "Dolor en el pecho al realizar esfuerzo físico"] } },
'Trastornos de la voz' : { intro: "Los trastornos de la voz afectan la capacidad de producir sonidos claros, alterando el tono, volumen o calidad vocal, lo que dificulta la comunicación diaria y requiere evaluación especializada.", whatIs: { title: "¿Qué son los Trastornos de la voz?", text: "Son alteraciones en el funcionamiento de las cuerdas vocales o la laringe que producen cambios anormales en la voz. A diferencia de una ronquera temporal por un resfriado, estos trastornos persisten y afectan significativamente el habla." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían según la causa, pero suelen incluir:", groups: [ { name: "Cambios en la voz", items: ["Ronquera prolongada", "Voz áspera, velada o entrecortada", "Pérdida temporal o total de la voz", "Cambios bruscos o incapacidad para controlar el tono"] }, { name: "Sensaciones físicas", items: ["Dolor o tensión en la garganta al hablar", "Sensación de un bulto en la garganta", "Fatiga vocal rápida", "Necesidad constante de carraspear"] } ], warning: "Si la ronquera dura más de dos o tres semanas sin causa evidente, es vital consultar a un otorrinolaringólogo." }, types: { title: "Clasificación Principal", intro: "Se dividen generalmente en tres grupos:", items: ["Trastornos orgánicos estructurales (nódulos, pólipos, quistes)", "Trastornos neurogénicos (parálisis de cuerdas vocales)", "Trastornos funcionales (fatiga por mal uso vocal sin lesión visible)"], note: "Identificar el tipo exacto es fundamental para el éxito del tratamiento." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas más frecuentes incluyen:", items: ["Abuso o mal uso de la voz (gritar, forzar el tono)", "Reflujo gastroesofágico (ERGE)", "Infecciones respiratorias agudas o crónicas", "Tabaquismo y exposición a irritantes", "Lesiones nerviosas por cirugías en cuello o tórax", "Estrés y factores psicológicos"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "El diagnóstico clínico incluye:", items: ["Laringoscopia (examen visual de las cuerdas vocales)", "Análisis acústico y aerodinámico de la voz", "Examen físico del cuello", "Evaluación foniátrica o logopédica"], note: "En ocasiones pueden requerirse estudios de imagen o biopsias si hay lesiones sospechosas." }, treatment: { title: "Tratamientos para los Trastornos de la Voz", intro: "El tratamiento depende del diagnóstico exacto e incluye:", subsections: [ { title: "Opciones comunes", items: ["Terapia de la voz (logopedia o rehabilitación vocal)", "Reposo vocal estricto", "Medicamentos (antiácidos para el reflujo, antibióticos)", "Cirugía laringológica (fonocirugía) para extirpar lesiones"] } ], note: "La higiene vocal y la intervención temprana mejoran el pronóstico en la mayoría de los casos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Se recomienda acudir al médico cuando:", items: ["Los cambios en la voz duran más de tres semanas", "Aparece dolor al hablar o tragar", "Se presenta dificultad para respirar o estridor", "Se escupe sangre al toser o carraspear"] } },
'Parálisis espástica' : { intro: "La parálisis espástica es una afección neuromuscular que causa rigidez, tensión extrema y dificultad para controlar el movimiento de los músculos, impactando la movilidad y autonomía de quien la padece.", whatIs: { title: "¿Qué es la Parálisis espástica?", text: "Es un tipo de trastorno motor caracterizado por espasmos musculares y un aumento anormal del tono muscular (espasticidad). Ocurre debido a daños en las vías del sistema nervioso central que controlan el movimiento voluntario." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas afectan principalmente la función motora e incluyen:", groups: [ { name: "Alteraciones motoras", items: ["Músculos rígidos y permanentemente tensos", "Movimientos espasmódicos, torpes o incontrolables", "Reflejos tendinosos exagerados", "Marcha en tijera o dificultad para caminar"] }, { name: "Complicaciones físicas", items: ["Dolor muscular y articular profundo", "Contracturas (acortamiento permanente de los músculos)", "Deformidades óseas y articulares con el tiempo"] } ], warning: "La falta de tratamiento puede llevar a contracturas permanentes que imposibiliten el movimiento de la articulación afectada." }, types: { title: "Condiciones Relacionadas", intro: "La espasticidad es un síntoma común en condiciones como:", items: ["Parálisis cerebral espástica (la forma más común)", "Esclerosis múltiple", "Lesiones de la médula espinal", "Accidente cerebrovascular (ACV)", "Traumatismo craneoencefálico severo"], note: "La extensión (monoplejia, hemiplejia, diplejia, cuadriplejia) varía según la lesión." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se origina por daño neurológico debido a:", items: ["Falta de oxígeno en el cerebro durante el parto", "Infecciones cerebrales (meningitis, encefalitis)", "Enfermedades neurodegenerativas", "Hemorragias o infartos cerebrales", "Traumas físicos graves en la cabeza o columna"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico y apoyado en pruebas como:", items: ["Examen neurológico detallado", "Evaluación del tono muscular y los reflejos", "Resonancia magnética (RM) del cerebro y médula", "Electromiografía (EMG) para medir la actividad eléctrica muscular"], note: "El objetivo del diagnóstico es encontrar la causa subyacente para guiar el manejo." }, treatment: { title: "Tratamientos Disponibles", intro: "El objetivo es mejorar la calidad de vida, aliviar el dolor y mantener la función:", subsections: [ { title: "Opciones comunes", items: ["Fisioterapia, terapia ocupacional y estiramientos continuos", "Medicamentos orales (como baclofeno, tizanidina o diazepam)", "Inyecciones locales de toxina botulínica (Botox)", "Cirugía ortopédica o rizotomía dorsal selectiva (neurocirugía)"] } ], note: "El tratamiento requiere un enfoque multidisciplinario y continuo durante toda la vida." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es crucial contactar a un especialista si:", items: ["La rigidez muscular empeora repentinamente", "El dolor interfiere con el sueño o actividades básicas", "Se desarrollan llagas o úlceras por presión", "Aparecen signos de contractura articular permanente"] } },
'Pinzamiento Subacromial' : { intro: "El pinzamiento subacromial es una de las causas más frecuentes de dolor de hombro. Se produce cuando los tendones del manguito rotador se comprimen o atrapan en el espacio debajo del acromion, limitando la movilidad del brazo.", whatIs: { title: "¿Qué es el Pinzamiento Subacromial?", text: "Es una afección dolorosa del hombro que ocurre cuando los tendones del manguito rotador o la bursa subacromial se pellizcan o rozan contra el hueso superior del hombro (acromion) al elevar el brazo." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen desarrollarse gradualmente e incluyen:", groups: [ { name: "Dolor y molestias", items: ["Dolor en la parte frontal y lateral del hombro", "Dolor agudo al levantar el brazo por encima de la cabeza", "Dolor nocturno que dificulta dormir sobre el lado afectado", "Sensación de pinchazo o ardor"] }, { name: "Limitaciones físicas", items: ["Debilidad generalizada en el hombro o brazo", "Pérdida de rango de movimiento", "Sensación de chasquido o crujido al mover la articulación"] } ], warning: "Ignorar los síntomas puede llevar al desgaste progresivo o incluso a la rotura total del tendón del manguito rotador." }, types: { title: "Fases del Pinzamiento", intro: "Clínicamente se puede clasificar en etapas:", items: ["Estadio I: Inflamación y edema (común en jóvenes menores de 25)", "Estadio II: Fibrosis y tendinitis engrosada (entre 25 y 40 años)", "Estadio III: Desgarro del tendón y cambios óseos (mayores de 40 años)"], note: "El estadio determina si el tratamiento puede ser conservador o requiere cirugía." }, causes: { title: "Causas y Factores de Riesgo", intro: "El pinzamiento suele deberse a:", items: ["Movimientos repetitivos del brazo por encima de la cabeza (natación, tenis, pintura)", "Anatomía del hombro (acromion curvo o en gancho)", "Espolones óseos por envejecimiento", "Mala postura crónica", "Traumatismos o caídas previas sobre el hombro"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista en ortopedia realiza:", items: ["Exploración física con pruebas de provocación de dolor (test de Neer, test de Hawkins)", "Radiografías para detectar espolones óseos o variaciones anatómicas", "Ecografía o Resonancia Magnética (RM) para evaluar el daño en los tendones y la bursa"], note: "A veces se inyecta un anestésico local; si el dolor desaparece, confirma el diagnóstico." }, treatment: { title: "Tratamientos", intro: "Se inicia casi siempre con un enfoque conservador:", subsections: [ { title: "Opciones comunes", items: ["Reposo relativo y evitar movimientos que desencadenen el dolor", "Fisioterapia para fortalecer los músculos estabilizadores de la escápula", "Medicamentos antiinflamatorios no esteroideos (AINEs)", "Inyecciones de corticosteroides en el espacio subacromial", "Cirugía (acromioplastia o descompresión subacromial) si no hay mejora tras meses de tratamiento"] } ], note: "La recuperación requiere paciencia y constancia en los ejercicios de rehabilitación." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debe evaluar su hombro un médico si:", items: ["El dolor de hombro dura más de unas pocas semanas", "Hay incapacidad repentina para levantar el brazo", "Siente debilidad extrema o el brazo 'cede'", "El dolor le impide conciliar el sueño"] } },
'Trastornos por inmunodeficiencia' : { intro: "Los trastornos por inmunodeficiencia impiden que el cuerpo combata adecuadamente las infecciones y enfermedades. Este déficit en las defensas naturales hace que las personas afectadas sean extremadamente vulnerables a problemas de salud recurrentes.", whatIs: { title: "¿Qué son los Trastornos por inmunodeficiencia?", text: "Son condiciones en las que una o más partes del sistema inmunológico no funcionan correctamente o están ausentes. Esto impide que el organismo neutralice virus, bacterias, hongos y parásitos de forma eficaz." }, symptoms: { title: "Síntomas Comunes", intro: "La principal señal de alerta son las infecciones inusuales:", groups: [ { name: "Infecciones frecuentes", items: ["Neumonías, bronquitis o sinusitis crónicas y repetitivas", "Infecciones de oído frecuentes", "Infecciones que requieren antibióticos intravenosos para curarse", "Aparición de infecciones por microorganismos oportunistas"] }, { name: "Otros signos clínicos", items: ["Retraso en el crecimiento o desarrollo en niños", "Problemas digestivos crónicos (diarrea recurrente, pérdida de peso)", "Inflamación de órganos internos o ganglios linfáticos", "Trastornos autoinmunes asociados"] } ], warning: "Cualquier persona que sufra infecciones graves recurrentes debe ser evaluada por un inmunólogo de inmediato." }, types: { title: "Tipos de Inmunodeficiencia", intro: "Se clasifican fundamentalmente en dos categorías:", items: ["Inmunodeficiencias primarias (congénitas/genéticas, como el Síndrome de DiGeorge o Inmunodeficiencia Común Variable)", "Inmunodeficiencias secundarias (adquiridas por enfermedades, fármacos o factores ambientales, como el VIH/SIDA)"], note: "Las inmunodeficiencias secundarias son mucho más comunes que las primarias." }, causes: { title: "Causas y Factores de Riesgo", intro: "El origen depende del tipo de trastorno:", items: ["Mutaciones o defectos genéticos hereditarios (primarias)", "Infecciones severas que destruyen células inmunes, como el VIH (secundarias)", "Tratamientos médicos prolongados (quimioterapia, inmunosupresores para trasplantes)", "Enfermedades crónicas graves (diabetes severa, desnutrición extrema)", "Pérdida de proteínas por enfermedades renales crónicas"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "El proceso diagnóstico es exhaustivo e incluye:", items: ["Historial médico familiar y personal detallado", "Análisis de sangre para medir niveles de glóbulos blancos, linfocitos T/B e inmunoglobulinas", "Pruebas de función inmunológica y respuesta a vacunas", "Pruebas genéticas en caso de sospecha de inmunodeficiencia primaria"], note: "El diagnóstico temprano, especialmente en recién nacidos, es vital para prevenir daños orgánicos irreparables." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento busca prevenir infecciones y mejorar la inmunidad:", subsections: [ { title: "Opciones comunes", items: ["Tratamiento riguroso y preventivo con antibióticos, antivirales y antifúngicos", "Terapia de reemplazo de inmunoglobulinas (anticuerpos intravenosos o subcutáneos)", "Terapias biológicas como interferón", "Trasplante de células madre hematopoyéticas (médula ósea) para casos graves", "Tratamiento específico de la enfermedad subyacente (ej. antirretrovirales para VIH)"] } ], note: "Las medidas de higiene extrema y evitar la exposición a personas enfermas son fundamentales en el manejo diario." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulte a un especialista si usted o su hijo presentan:", items: ["Dos o más neumonías en un año", "Necesidad de antibióticos intravenosos para curar una infección", "Infecciones recurrentes de piel, órganos o mucosas profundas", "Antecedentes familiares de enfermedades de inmunodeficiencia primaria"] } },
'Niveles elevados de colesterol y triglicéridos' : { intro: "Tener niveles elevados de colesterol y triglicéridos en la sangre (dislipidemia) es un factor de riesgo silencioso pero grave. Suele pasar desapercibido, pero aumenta drásticamente la probabilidad de sufrir enfermedades cardíacas y accidentes cerebrovasculares.", whatIs: { title: "¿Qué son la Hipercolesterolemia y la Hipertrigliceridemia?", text: "Se refiere a una concentración anormalmente alta de lípidos (grasas) en la sangre. El exceso de colesterol LDL ('malo') favorece la formación de placas en las arterias, mientras que los triglicéridos altos endurecen las paredes arteriales." }, symptoms: { title: "Síntomas", intro: "La característica más peligrosa de esta condición es su naturaleza asintomática. Sin embargo, en niveles extremos puede haber señales:", groups: [ { name: "Signos visibles (solo en niveles muy altos o genéticos)", items: ["Xantomas (depósitos amarillentos de grasa bajo la piel en tendones o párpados)", "Arco corneal (un anillo gris claro alrededor del iris del ojo)", "Dolor abdominal agudo (si los triglicéridos son lo suficientemente altos como para causar pancreatitis)"] }, { name: "Síntomas de complicaciones", items: ["Dolor en el pecho (angina) por arterias obstruidas", "Dificultad para respirar por problemas coronarios", "Síntomas de accidente cerebrovascular (dificultad para hablar, parálisis facial)"] } ], warning: "Dado que no suele presentar síntomas hasta que ocurre una emergencia, las pruebas de detección periódicas son la única forma confiable de diagnóstico." }, types: { title: "Tipos de Lípidos Relevantes", intro: "El perfil lipídico evalúa varios componentes:", items: ["Colesterol LDL (lipoproteínas de baja densidad, o 'colesterol malo')", "Colesterol HDL (lipoproteínas de alta densidad, o 'colesterol bueno')", "Triglicéridos (el tipo más común de grasa en el cuerpo)", "Colesterol Total (la suma de la cantidad de colesterol en la sangre)"], note: "El objetivo clínico es mantener el LDL y los triglicéridos bajos, y el HDL alto." }, causes: { title: "Causas y Factores de Riesgo", intro: "Esta alteración metabólica es el resultado de múltiples factores:", items: ["Dieta rica en grasas saturadas, grasas trans y azúcares simples", "Falta de actividad física y sedentarismo", "Sobrepeso u obesidad", "Genética y antecedentes familiares (hipercolesterolemia familiar)", "Consumo excesivo de alcohol y tabaquismo", "Otras enfermedades médicas como diabetes o hipotiroidismo no controlado"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se diagnostica a través de una prueba de sangre sencilla:", items: ["Perfil lipídico completo (análisis de sangre en ayunas)", "Evaluación de antecedentes familiares", "Medición de la presión arterial y azúcar en sangre para evaluar el riesgo cardiovascular global"], note: "Las pautas recomiendan que los adultos se realicen un panel de lípidos cada 4 a 6 años, o más frecuentemente si hay factores de riesgo." }, treatment: { title: "Tratamientos", intro: "El manejo combina cambios en el estilo de vida con intervenciones farmacológicas:", subsections: [ { title: "Opciones comunes", items: ["Cambios en la dieta (dieta mediterránea, rica en fibra, reducción de grasas saturadas)", "Ejercicio aeróbico regular y pérdida de peso", "Abandono del tabaquismo y limitación del alcohol", "Medicamentos reductores de colesterol (estatinas, ezetimiba, inhibidores de PCSK9)", "Medicamentos reductores de triglicéridos (fibratos, suplementos de omega-3 recetados)"] } ], note: "El tratamiento es a menudo a largo plazo o de por vida para mantener los niveles bajo control." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debe consultar a un médico para evaluar sus niveles de colesterol si:", items: ["Tiene antecedentes familiares de colesterol alto o ataques cardíacos tempranos", "Es mayor de 20 años y nunca se ha hecho un perfil lipídico", "Padece diabetes, obesidad o hipertensión arterial", "Experimenta dolor en el pecho, falta de aire o mareos inexplicables (signos de complicaciones)"] } },
'Estenosis aórtica' : { intro: "La estenosis aórtica es una de las enfermedades valvulares cardíacas más comunes y graves. Ocurre cuando la válvula aórtica del corazón se estrecha, impidiendo que la sangre fluya con normalidad hacia el resto del cuerpo y obligando al corazón a trabajar en exceso.", whatIs: { title: "¿Qué es la Estenosis Aórtica?", text: "Es el estrechamiento u obstrucción de la válvula aórtica, que es la 'puerta' que permite el paso de sangre rica en oxígeno desde el ventrículo izquierdo del corazón hacia la aorta, la arteria principal del cuerpo." }, symptoms: { title: "Síntomas Comunes", intro: "Puede ser asintomática durante años. Cuando la válvula se estrecha severamente, aparecen síntomas como:", groups: [ { name: "Síntomas cardíacos y respiratorios", items: ["Dolor, opresión o presión en el pecho (angina de pecho), especialmente durante el ejercicio", "Falta de aire, particularmente con el esfuerzo o al acostarse", "Palpitaciones (sensación de latidos rápidos o aleteo en el pecho)"] }, { name: "Síntomas sistémicos", items: ["Sensación de desmayo, mareos o pérdida de conocimiento (síncope) al realizar actividad física", "Fatiga severa y debilidad general", "Hinchazón en los tobillos y los pies (edema) en etapas avanzadas"] } ], warning: "La aparición de síntomas (dolor en el pecho, desmayos, falta de aire) indica que la enfermedad es grave y requiere atención médica urgente." }, types: { title: "Clasificación por Gravedad", intro: "La estenosis aórtica se evalúa según su severidad:", items: ["Leve (generalmente asintomática, requiere monitoreo)", "Moderada (puede o no tener síntomas, requiere seguimiento cercano)", "Severa (presencia de síntomas, requiere intervención quirúrgica o de cateterismo)"], note: "La progresión de leve a severa puede tomar años o suceder rápidamente en pacientes mayores." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas varían principalmente según la edad del paciente:", items: ["Acumulación de calcio en la válvula relacionada con el envejecimiento (causa más común en adultos mayores)", "Defecto cardíaco congénito (nacer con una válvula aórtica bicúspide en lugar de tricúspide)", "Fiebre reumática infantil (puede dañar la válvula y causar estenosis décadas después)", "Radioterapia previa en el área del tórax", "Factores de riesgo cardiovascular tradicionales (hipertensión, colesterol alto)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El cardiólogo confirma el diagnóstico utilizando:", items: ["Auscultación cardíaca (detección de un soplo cardíaco característico con el estetoscopio)", "Ecocardiograma (prueba estándar de oro para evaluar el grosor y movimiento de la válvula)", "Electrocardiograma (ECG) para detectar engrosamiento del músculo cardíaco", "Prueba de esfuerzo (solo si el paciente es asintomático)", "Cateterismo cardíaco (en casos complejos para medir presiones exactas)"], note: "El ecocardiograma es la herramienta más importante para determinar la gravedad y el momento de la cirugía." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento definitivo para la estenosis severa es el reemplazo de la válvula:", subsections: [ { title: "Opciones médicas e intervencionistas", items: ["Seguimiento ecocardiográfico regular (para casos leves y moderados)", "Medicamentos para aliviar los síntomas o tratar la insuficiencia cardíaca concurrente (no curan la estenosis)", "Reemplazo quirúrgico de la válvula aórtica a corazón abierto (SAVR)", "Reemplazo de la válvula aórtica transcatéter (TAVI/TAVR), un procedimiento menos invasivo", "Valvuloplastia con globo (generalmente para niños o adultos muy inestables)"] } ], note: "La elección entre cirugía abierta y TAVI depende de la edad, el riesgo quirúrgico y la salud general del paciente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busque atención de emergencia o contacte a su médico si:", items: ["Experimenta dolor en el pecho o presión inexplicable", "Siente mareos intensos o se desmaya durante una actividad física", "Desarrolla dificultad repentina para respirar", "Un médico ha detectado un soplo cardíaco nuevo durante un examen de rutina"] } },
'Hipotiroidismo en adultos' : { intro: "El hipotiroidismo en adultos es una afección endocrina común y tratable. Al disminuir la producción de hormonas tiroideas, el metabolismo del cuerpo se ralentiza, afectando todo, desde los niveles de energía hasta la temperatura corporal y la digestión.", whatIs: { title: "¿Qué es el Hipotiroidismo?", text: "Es una condición en la que la glándula tiroides, ubicada en el cuello, no produce suficiente cantidad de ciertas hormonas cruciales (T3 y T4). Como resultado, las funciones metabólicas del cuerpo se vuelven lentas." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas tienden a desarrollarse lentamente a lo largo de los años e incluyen:", groups: [ { name: "Síntomas físicos", items: ["Fatiga extrema y debilidad", "Aumento de peso inexplicable", "Sensibilidad aumentada al frío", "Piel seca y cabello ralo o quebradizo", "Estreñimiento crónico", "Ritmo cardíaco lento (bradicardia)", "Ronquera o hinchazón en la cara (mixedema)"] }, { name: "Síntomas cognitivos y emocionales", items: ["Problemas de memoria o dificultad para concentrarse ('niebla mental')", "Estado de ánimo depresivo", "Ciclos menstruales irregulares o abundantes"] } ], warning: "Si no se trata, el hipotiroidismo severo puede llevar a un mixedema coma, una complicación rara pero potencialmente mortal." }, types: { title: "Clasificación Clínica", intro: "Se puede dividir según su origen o severidad:", items: ["Hipotiroidismo primario (problema en la propia glándula tiroides)", "Hipotiroidismo secundario (problema en la glándula pituitaria que no estimula la tiroides)", "Hipotiroidismo subclínico (niveles de TSH ligeramente elevados con hormonas T3/T4 normales)"], note: "La gran mayoría de los casos en adultos corresponden al tipo primario." }, causes: { title: "Causas y Factores de Riesgo", intro: "La disminución en la producción de hormonas puede deberse a:", items: ["Enfermedad de Hashimoto (trastorno autoinmune y la causa más común)", "Tratamiento previo con yodo radiactivo (para el hipertiroidismo)", "Cirugía de tiroides (tiroidectomía total o parcial)", "Radioterapia en la cabeza o el cuello", "Efectos secundarios de ciertos medicamentos (como el litio o la amiodarona)", "Deficiencia de yodo (rara en países desarrollados)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es simple y se basa en análisis de sangre específicos:", items: ["Prueba de TSH (Hormona Estimulante de la Tiroides), que suele estar elevada", "Prueba de T4 libre (tiroxina), que suele estar baja", "Prueba de anticuerpos antitiroideos (para confirmar si la causa es la enfermedad de Hashimoto)", "Evaluación de síntomas clínicos e historial médico"], note: "Un nivel alto de TSH es el indicador más sensible de que la tiroides está fallando." }, treatment: { title: "Tratamiento para el Hipotiroidismo", intro: "El tratamiento es altamente efectivo y generalmente consiste en:", subsections: [ { title: "Terapia de reemplazo hormonal", items: ["Uso diario de levotiroxina sintética oral (reemplaza la hormona T4 faltante)", "Ajustes de dosis basados en análisis de sangre de TSH cada 6 a 8 semanas al inicio", "Monitoreo anual una vez que se estabiliza la dosis", "Mantener la misma marca del medicamento o consultar al médico antes de cambiar"] } ], note: "El tratamiento suele ser de por vida, pero permite a los pacientes llevar una vida completamente normal y libre de síntomas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulte a un médico para una evaluación de la tiroides si:", items: ["Se siente inusualmente cansado o apático sin razón aparente", "Nota un aumento de peso constante a pesar de no cambiar su dieta", "Tiene piel seca persistente, pérdida de cabello o hinchazón facial", "Sufre de estreñimiento severo y prolongado o estado de ánimo depresivo resistente al tratamiento"] } },
'Síndrome de dificultad respiratoria en neonatos' : { intro: "El síndrome de dificultad respiratoria (SDR) en neonatos es una emergencia respiratoria que afecta principalmente a los bebés prematuros. Sus pulmones inmaduros carecen de una sustancia vital llamada surfactante, dificultando enormemente la respiración y la oxigenación adecuada.", whatIs: { title: "¿Qué es el Síndrome de Dificultad Respiratoria Neonatal?", text: "Anteriormente conocido como enfermedad de la membrana hialina, es un trastorno respiratorio en recién nacidos (casi siempre prematuros) caracterizado por la incapacidad de los pulmones para mantenerse inflados debido a la falta de surfactante pulmonar natural." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "Los síntomas generalmente aparecen inmediatamente después del parto o en las primeras horas de vida:", groups: [ { name: "Dificultad respiratoria evidente", items: ["Respiración rápida y superficial (taquipnea)", "Quejido audible al exhalar", "Retracciones (hundimiento de la piel entre o debajo de las costillas al respirar)", "Ensanchamiento de las fosas nasales (aleteo nasal)"] }, { name: "Signos de hipoxia (falta de oxígeno)", items: ["Piel o labios con coloración azulada (cianosis)", "Breves pausas en la respiración (apnea)", "Disminución del movimiento y de la respuesta a estímulos (letargo)"] } ], warning: "El SDR es una condición crítica que requiere atención inmediata en una Unidad de Cuidados Intensivos Neonatales (UCIN)." }, types: { title: "Severidad de la Enfermedad", intro: "La gravedad del SDR está directamente relacionada con la edad gestacional:", items: ["Leve (requiere algo de oxígeno suplementario)", "Moderado (requiere presión positiva continua en las vías respiratorias - CPAP)", "Severo (requiere intubación, ventilación mecánica y administración de surfactante)"], note: "Cuanto más prematuro es el bebé, mayor es la probabilidad de que el síndrome sea severo." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa principal es la inmadurez pulmonar, agravada por factores como:", items: ["Nacimiento prematuro (antes de la semana 37, especialmente antes de la semana 28)", "Genética familiar de SDR en hermanos mayores", "Madre con diabetes gestacional", "Parto por cesárea sin trabajo de parto previo", "Asfixia perinatal (falta de oxígeno durante el parto)", "Gestación múltiple (gemelos o trillizos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico lo realizan los neonatólogos utilizando:", items: ["Evaluación física y observación del patrón respiratorio del recién nacido", "Radiografía de tórax (que muestra una apariencia característica de 'vidrio esmerilado' en los pulmones)", "Análisis de gases en sangre arterial (para medir los niveles bajos de oxígeno y altos de dióxido de carbono)", "Ecocardiograma (para descartar problemas cardíacos congénitos)"], note: "El diagnóstico precoz permite administrar el tratamiento rápidamente y prevenir complicaciones a largo plazo." }, treatment: { title: "Manejo y Tratamiento en la UCIN", intro: "El objetivo es proporcionar soporte respiratorio hasta que los pulmones del bebé maduren y produzcan su propio surfactante:", subsections: [ { title: "Intervenciones clave", items: ["Terapia de reemplazo de surfactante artificial a través de un tubo endotraqueal", "Soporte respiratorio no invasivo (como CPAP nasal para mantener los pulmones abiertos)", "Ventilación mecánica (respirador artificial) para casos severos", "Administración cuidadosa de oxígeno, líquidos intravenosos y nutrición", "Medicamentos prenatales (corticosteroides a la madre antes del parto para acelerar la maduración pulmonar del feto)"] } ], note: "Gracias a los avances médicos modernos como el surfactante artificial, la supervivencia de estos recién nacidos es altísima." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda?", intro: "Para prevenir o manejar el SDR, es importante:", items: ["Recibir atención prenatal temprana y regular durante el embarazo", "Buscar ayuda médica inmediata si hay signos de trabajo de parto prematuro (contracciones antes de la semana 37)", "Garantizar que el parto prematuro ocurra en un hospital equipado con una UCIN de alto nivel"] } },
'Síndrome del túnel carpiano' : { intro: "El síndrome del túnel carpiano es una neuropatía por compresión extremadamente común que afecta la mano y la muñeca. Provoca dolor, entumecimiento y hormigueo, interfiriendo significativamente con las actividades cotidianas, especialmente aquellas que requieren habilidades manuales finas.", whatIs: { title: "¿Qué es el Síndrome del túnel carpiano?", text: "Es una condición causada por la presión excesiva sobre el nervio mediano a su paso por el túnel carpiano (un paso estrecho de ligamentos y huesos en la base de la mano). Este nervio controla la sensibilidad y el movimiento de varios dedos." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen comenzar gradualmente y empeorar con el tiempo:", groups: [ { name: "Síntomas sensitivos", items: ["Hormigueo o entumecimiento en los dedos pulgar, índice, medio y parte del anular", "Sensación de pequeñas descargas eléctricas en esos dedos", "Dolor o ardor que sube por el brazo hacia el hombro", "Los síntomas suelen despertar al paciente durante la noche"] }, { name: "Síntomas motores", items: ["Debilidad en la mano y dificultad para realizar movimientos finos (como abotonarse una camisa)", "Tendencia a dejar caer objetos involuntariamente", "Pérdida de sensibilidad al calor o al frío en los dedos afectados"] } ], warning: "Si la compresión nerviosa persiste sin tratamiento, puede causar daño permanente y atrofia de los músculos de la base del pulgar." }, types: { title: "Fases del Síndrome", intro: "La evolución de la enfermedad se clasifica en:", items: ["Fase inicial (síntomas intermitentes, predominantemente nocturnos)", "Fase intermedia (síntomas diurnos constantes durante actividades como conducir o usar el teléfono)", "Fase avanzada (pérdida de sensibilidad severa, debilidad muscular constante y atrofia)"], note: "El tratamiento es mucho más exitoso si se inicia en las fases tempranas." }, causes: { title: "Causas y Factores de Riesgo", intro: "Suele ser causado por una combinación de factores que reducen el espacio del túnel carpiano:", items: ["Anatomía individual (tener un túnel carpiano naturalmente más pequeño)", "Movimientos repetitivos de la muñeca o la mano (trabajo en línea de ensamblaje, uso prolongado de herramientas vibratorias)", "Condiciones inflamatorias como la artritis reumatoide", "Cambios hormonales durante el embarazo o la menopausia", "Otras condiciones médicas (obesidad, diabetes, hipotiroidismo)", "Traumatismos previos (fracturas o esguinces de muñeca)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un médico puede diagnosticarlo mediante:", items: ["Historial médico detallado de los síntomas", "Examen físico con pruebas de provocación (Signo de Tinel y Prueba de Phalen)", "Electromiografía (EMG) y estudios de conducción nerviosa (para medir el daño en el nervio)", "Ecografía de la muñeca para evaluar el nervio mediano"], note: "Las pruebas electrofisiológicas (EMG) son fundamentales para confirmar el diagnóstico y evaluar la gravedad." }, treatment: { title: "Tratamientos para el Túnel Carpiano", intro: "El tratamiento varía desde medidas conservadoras hasta cirugía, dependiendo de la gravedad:", subsections: [ { title: "Opciones de tratamiento", items: ["Uso de una férula o muñequera inmovilizadora (especialmente de noche)", "Medicamentos antiinflamatorios (AINEs) para aliviar el dolor a corto plazo", "Inyecciones de corticosteroides directamente en el túnel carpiano para reducir la inflamación severa", "Pausas frecuentes, estiramientos de muñeca y cambios ergonómicos en el lugar de trabajo", "Cirugía de liberación del túnel carpiano (cortar el ligamento para aliviar la presión sobre el nervio) si los síntomas son graves o persistentes"] } ], note: "La cirugía tiene una alta tasa de éxito y suele proporcionar alivio permanente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es recomendable consultar a un médico especialista si:", items: ["El dolor y el hormigueo interfieren constantemente con sus actividades diarias o le impiden dormir", "Comienza a notar debilidad en la mano o se le caen las cosas repetidamente", "Los síntomas no mejoran después de semanas de reposo y evitar actividades repetitivas", "Nota atrofia (hundimiento) del músculo en la base del pulgar"] } },
'Atrofia muscular espinal' : { intro: "La atrofia muscular espinal (AME) es un trastorno genético neurodegenerativo severo. Provoca una debilidad muscular progresiva que afecta la capacidad de moverse, tragar y, en casos graves, de respirar, requiriendo un enfoque médico especializado y multidisciplinario.", whatIs: { title: "¿Qué es la Atrofia muscular espinal?", text: "Es una enfermedad genética hereditaria que destruye progresivamente las neuronas motoras inferiores en la médula espinal y el tronco encefálico. Estas neuronas son esenciales para controlar la actividad muscular voluntaria esencial, como hablar, caminar, tragar y respirar." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían ampliamente según la edad de inicio y el tipo, pero incluyen fundamentalmente:", groups: [ { name: "Síntomas motores", items: ["Debilidad muscular progresiva, a menudo simétrica (más severa en piernas y tronco que en brazos)", "Falta de control de la cabeza en bebés", "Dificultad progresiva para sentarse, gatear o caminar", "Fasciculaciones (espasmos musculares sutiles) y arreflexia (ausencia de reflejos tendinosos)"] }, { name: "Complicaciones vitales", items: ["Problemas severos para tragar o succionar (disfagia)", "Dificultades respiratorias progresivas", "Deformidades óseas secundarias, como escoliosis severa, debido a la debilidad muscular"] } ], warning: "En los bebés menores de 6 meses, las dificultades respiratorias y de deglución representan una emergencia médica inmediata." }, types: { title: "Clasificación (Tipos de AME)", intro: "Se clasifica en diferentes tipos según la edad de inicio y los hitos motores alcanzados:", items: ["Tipo 1 (Enfermedad de Werdnig-Hoffmann): Inicio antes de los 6 meses, no logran sentarse sin apoyo; es el tipo más grave.", "Tipo 2 (Intermedia): Inicio entre 6 y 18 meses, logran sentarse pero nunca caminan de forma independiente.", "Tipo 3 (Enfermedad de Kugelberg-Welander): Inicio después de los 18 meses, logran caminar, pero pueden perder la capacidad más tarde.", "Tipo 4 (Inicio en adultos): Aparece en la edad adulta, causa debilidad leve a moderada y no acorta la esperanza de vida."], note: "El tipo está determinado genéticamente por el número de copias de un gen de 'respaldo' llamado SMN2." }, causes: { title: "Causas Genéticas", intro: "La AME es una enfermedad autosómica recesiva causada por:", items: ["Mutación o deleción del gen SMN1 (gen de supervivencia de la motoneurona 1)", "Falta de producción de la proteína SMN, esencial para la salud y supervivencia de las neuronas motoras", "Para desarrollar la enfermedad, un niño debe heredar una copia del gen mutado de ambos padres (portadores asintomáticos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es crítico para la eficacia de los tratamientos actuales. Se basa en:", items: ["Prueba genética molecular en sangre (el estándar de oro, detecta mutaciones en el gen SMN1)", "Revisión clínica exhaustiva y del historial familiar", "Electromiografía (EMG) o biopsia muscular (ahora raramente utilizadas gracias a las pruebas genéticas precisas)", "Cribado neonatal (disponible en varios países para detectar la enfermedad en recién nacidos asintomáticos)"], note: "El cribado neonatal ha revolucionado el manejo, permitiendo el tratamiento antes de que mueran las neuronas motoras." }, treatment: { title: "Terapias y Tratamiento", intro: "Aunque tradicionalmente era incurable, hoy existen tratamientos revolucionarios que modifican el curso de la enfermedad:", subsections: [ { title: "Terapias modificadoras de la enfermedad y cuidado integral", items: ["Terapia génica (Zolgensma) administrada como una infusión intravenosa única (generalmente en menores de 2 años)", "Terapias de modificación del empalme genético (Nusinersen por inyección espinal o Risdiplam oral diario)", "Manejo respiratorio agresivo (ventilación no invasiva, asistencia para toser)", "Fisioterapia y equipos de asistencia (sillas de ruedas, bipedestadores) para mantener la función y prevenir deformidades", "Soporte nutricional, como tubos de alimentación si la deglución es insegura"] } ], note: "Los tratamientos no revierten el daño neuronal ya establecido, por lo que la intervención temprana es la clave absoluta del éxito." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda?", intro: "Consulte a un pediatra o neurólogo si observa en su hijo:", items: ["Un bebé se siente inusualmente 'blando' o hipotónico (síndrome del bebé flácido)", "El niño no alcanza hitos motores como sostener la cabeza, sentarse o caminar", "Una pérdida repentina o gradual de las habilidades motoras que el niño ya había adquirido", "Dificultades evidentes al respirar, toser debilmente o problemas consistentes para alimentarse"] } },
'Trastornos asociados con el vértigo' : { intro: "Los trastornos asociados con el vértigo generan episodios debilitantes de mareo ilusorio. Quienes los padecen sienten falsamente que ellos o el mundo a su alrededor están girando bruscamente, a menudo acompañados de náuseas y problemas severos de equilibrio.", whatIs: { title: "¿Qué son los trastornos de Vértigo?", text: "El vértigo no es una enfermedad en sí, sino un síntoma de trastornos subyacentes que afectan el oído interno (sistema vestibular) o, con menos frecuencia, las partes del cerebro que procesan el equilibrio y la orientación espacial." }, symptoms: { title: "Síntomas y Manifestaciones", intro: "Los episodios varían en duración e intensidad, pero casi siempre incluyen:", groups: [ { name: "Síntomas vestibulares", items: ["Sensación intensa de giro, balanceo o inclinación", "Pérdida de equilibrio e inestabilidad al caminar o ponerse de pie", "Movimientos oculares espasmódicos e involuntarios (nistagmo)", "Sensación de desmayo o de 'cabeza vacía'"] }, { name: "Síntomas asociados", items: ["Náuseas severas y vómitos", "Zumbido en los oídos (acúfenos o tinnitus)", "Pérdida temporal de la audición o sensación de plenitud en el oído afectado", "Dolor de cabeza agudo (en el caso de la migraña vestibular)"] } ], warning: "Si el vértigo se acompaña de debilidad en un lado del cuerpo, dificultad para hablar o visión doble, busque ayuda en urgencias, ya que podría indicar un derrame cerebral." }, types: { title: "Principales Trastornos Causantes", intro: "Las causas más comunes de vértigo periférico (del oído interno) incluyen:", items: ["Vértigo Posicional Paroxístico Benigno (VPPB): Episodios cortos desencadenados por cambios en la posición de la cabeza.", "Enfermedad de Ménière: Episodios prolongados con pérdida de audición, tinnitus y plenitud en el oído.", "Neuritis Vestibular: Vértigo intenso y constante de inicio repentino causado por inflamación del nervio vestibular, a menudo posterior a una infección viral.", "Migraña Vestibular: Mareos asociados a antecedentes de migrañas, con o sin dolor de cabeza en el momento."], note: "El VPPB es, con diferencia, la causa más común de vértigo en adultos." }, causes: { title: "Causas y Factores Desencadenantes", intro: "Los problemas en el sistema del equilibrio pueden ser provocados por:", items: ["Desplazamiento de pequeños cristales de calcio (otoconias) dentro del oído interno (causa del VPPB)", "Acumulación anormal de líquido en el oído interno (causa de Ménière)", "Infecciones virales o bacterianas del oído interno", "Traumatismos craneales o lesiones cervicales", "Ciertos medicamentos ototóxicos o alteraciones vasculares cerebrales"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "Para determinar la causa exacta, el médico (a menudo un otorrinolaringólogo o neurólogo) realiza:", items: ["Anamnesis detallada sobre la duración, frecuencia y desencadenantes de los episodios", "Examen físico neurológico y ocular (observación de nistagmo)", "Maniobra de Dix-Hallpike (para confirmar o descartar VPPB)", "Pruebas audiológicas y vestibulares (videonistagmografía - VNG)", "Resonancia magnética cerebral en casos atípicos o si hay síntomas neurológicos concurrentes"], note: "Describir con precisión si el mareo es un 'giro' o simplemente un 'aturdimiento' es crucial para el diagnóstico." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento se enfoca en tratar la enfermedad subyacente y aliviar los síntomas agudos:", subsections: [ { title: "Intervenciones específicas", items: ["Maniobras de reposicionamiento canalicular (como la Maniobra de Epley) para curar el VPPB", "Medicamentos supresores vestibulares (meclizina, diazepam) y antieméticos para aliviar las náuseas en ataques agudos", "Rehabilitación vestibular (terapia física especializada para entrenar al cerebro a compensar el déficit de equilibrio)", "Dieta baja en sal y diuréticos para la enfermedad de Ménière", "Medicamentos profilácticos para las migrañas (en caso de migraña vestibular)", "Cirugía (rara vez requerida, solo para casos intratables severos)"] } ], note: "La mayoría de los trastornos del vértigo son tratables y muchos se resuelven espontáneamente con el tiempo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Solicite asistencia médica de inmediato si el vértigo aparece súbitamente y se acompaña de:", items: ["Dolor de cabeza repentino y extremadamente severo", "Fiebre alta persistente", "Dificultad repentina para ver, hablar o caminar derecho", "Debilidad o entumecimiento en un lado del rostro o cuerpo", "Pérdida de conciencia o caídas repetidas inexplicables"] } },
'Bronconeumonía' : { intro: "La bronconeumonía es una forma común e inflamatoria de neumonía que afecta parches localizados dentro de los pulmones. Puede ser grave, especialmente en niños pequeños, ancianos y personas con sistemas inmunológicos comprometidos, requiriendo intervención médica oportuna.", whatIs: { title: "¿Qué es la Bronconeumonía?", text: "Es una infección aguda que causa inflamación en los bronquiolos (pequeños conductos de aire) y en los alvéolos circundantes de los pulmones. Esto provoca que los sacos de aire se llenen de pus y fluidos, dificultando el intercambio de oxígeno." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden variar desde leves hasta potencialmente mortales, y generalmente incluyen:", groups: [ { name: "Síntomas respiratorios", items: ["Tos persistente que produce flema gruesa (moco amarillo, verde o con sangre)", "Dificultad para respirar (disnea) o respiración rápida", "Dolor punzante o agudo en el pecho que empeora al toser o respirar profundamente", "Respiración ruidosa, sibilancias o quejidos al respirar (especialmente en niños)"] }, { name: "Síntomas sistémicos", items: ["Fiebre alta y repentina acompañada de escalofríos intensos", "Fatiga extrema y debilidad muscular", "Sudoración profusa", "Confusión o cambios mentales (muy común en adultos mayores o en casos graves)"] } ], warning: "La dificultad severa para respirar o el dolor intenso en el pecho son motivos para buscar atención de urgencias sin demora." }, types: { title: "Clasificación por Entorno de Adquisición", intro: "Médicamente, las neumonías se dividen según dónde se contrajeron:", items: ["Adquirida en la comunidad (NAC): Contraída en el entorno general fuera de un entorno médico. Es la más común.", "Adquirida en el hospital (nosocomial): Contraída durante una estadía hospitalaria (suele involucrar bacterias más resistentes).", "Por aspiración: Ocurre cuando se inhalan alimentos, líquidos o vómito hacia los pulmones."], note: "Las formas adquiridas en el hospital suelen ser más peligrosas y difíciles de tratar." }, causes: { title: "Causas Infecciosas", intro: "Puede ser provocada por diversos microorganismos, pero los más frecuentes son:", items: ["Bacterias (como Streptococcus pneumoniae, Haemophilus influenzae, Staphylococcus aureus)", "Virus respiratorios (como el virus de la influenza, VSR, adenovirus o SARS-CoV-2)", "Hongos (raro, generalmente afecta solo a personas inmunodeprimidas o expuestas a grandes cantidades de esporas)", "Inhalación de sustancias tóxicas o aspiración de contenido gástrico"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico y radiológico suele incluir:", items: ["Evaluación física (el médico escucha crepitantes o sibilancias en los pulmones con el estetoscopio)", "Radiografía de tórax (confirma la presencia y extensión de la infección con manchas parcheadas características)", "Pulsioximetría para medir el nivel de oxígeno en la sangre", "Análisis de sangre y cultivo de esputo para identificar el germen exacto y guiar el uso de antibióticos"], note: "La radiografía de tórax es la prueba más importante y definitiva para diagnosticar una bronconeumonía." }, treatment: { title: "Tratamiento y Cuidados", intro: "El tratamiento depende directamente de la causa y la gravedad de la infección:", subsections: [ { title: "Enfoques médicos", items: ["Antibióticos recetados (el tratamiento fundamental si la causa es bacteriana, deben terminarse todos los días indicados)", "Antivirales o antifúngicos (si la causa es un virus específico o un hongo)", "Medicamentos para la fiebre y el dolor (como ibuprofeno o paracetamol)", "Terapia de oxígeno y líquidos intravenosos (requeridos si el paciente está hospitalizado)", "Reposo prolongado y aumento significativo en la ingesta de líquidos claros"] } ], note: "La mayoría de las personas con bronconeumonía leve mejoran en una a dos semanas con tratamiento domiciliario adecuado." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Inmediata?", intro: "Es fundamental acudir a emergencias u hospital si:", items: ["Presenta dificultad severa para respirar, falta de aliento en reposo o respiración muy rápida", "Hay un tono azulado o grisáceo en los labios o las uñas (cianosis)", "La fiebre se mantiene consistentemente por encima de 39°C o no baja con medicamentos", "Experimenta dolor en el pecho intolerable o un estado de confusión mental repentino"] } },
'Tumor cerebral en niños' : { intro: "Un diagnóstico de tumor cerebral en niños es una experiencia aterradora para cualquier familia. Afortunadamente, los avances en la neurooncología pediátrica han mejorado drásticamente los tratamientos y las tasas de supervivencia, ofreciendo esperanza para un futuro saludable.", whatIs: { title: "¿Qué es un Tumor Cerebral Pediátrico?", text: "Es el crecimiento anormal de células en el cerebro o en los tejidos que lo rodean. Estos tumores pueden ser benignos (no cancerosos) o malignos (cancerosos), pero ambos pueden ser peligrosos debido a la presión que ejercen en el espacio cerrado del cráneo." }, symptoms: { title: "Síntomas y Signos", intro: "Los síntomas dependen del tamaño, tipo y ubicación del tumor, y pueden ser sutiles al principio:", groups: [ { name: "Síntomas de presión intracraneal", items: ["Dolores de cabeza frecuentes o severos (que suelen empeorar al despertar por la mañana)", "Vómitos inexplicables, a menudo en forma de 'escopetazo' y preferentemente por la mañana", "Aumento inusual del tamaño de la cabeza en bebés (macrocefalia)"] }, { name: "Síntomas neurológicos específicos", items: ["Problemas de visión (visión doble, borrosa o movimientos oculares inusuales)", "Dificultad persistente con el equilibrio, torpeza o problemas al caminar", "Convulsiones sin antecedentes de epilepsia", "Cambios marcados en el comportamiento, letargo inusual o declive repentino en el rendimiento escolar"] } ], warning: "Los vómitos matutinos recurrentes junto con dolor de cabeza persistente son una bandera roja que requiere evaluación neurológica inmediata." }, types: { title: "Tipos Frecuentes en Niños", intro: "Existen muchos tipos de tumores cerebrales, los más comunes en pediatría incluyen:", items: ["Astrocitomas (frecuentemente benignos y de lento crecimiento)", "Meduloblastomas (tumores malignos agresivos que comienzan en el cerebelo)", "Ependimomas (se desarrollan en las áreas donde fluye el líquido cefalorraquídeo)", "Gliomas del tronco encefálico (tumores ubicados en la base del cerebro)"], note: "El pronóstico y la agresividad del tratamiento están dictados por el tipo histológico específico." }, causes: { title: "Causas y Factores de Riesgo", intro: "En la gran mayoría de los casos de tumores cerebrales infantiles, la causa exacta es desconocida:", items: ["Alteraciones o mutaciones genéticas aleatorias que ocurren en el desarrollo celular", "Afecciones genéticas hereditarias (como Neurofibromatosis, Esclerosis Tuberosa o Síndrome de Li-Fraumeni) aumentan significativamente el riesgo", "La exposición previa a dosis altas de radiación (generalmente médica) en el área de la cabeza es un factor de riesgo documentado"], note: "No se ha demostrado que los teléfonos móviles o traumatismos craneales comunes causen tumores cerebrales." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El proceso diagnóstico es complejo y de alta tecnología, e incluye:", items: ["Examen neurológico completo para evaluar la visión, audición, equilibrio, coordinación y reflejos", "Resonancia magnética (RM) del cerebro y, a menudo, de la médula espinal (el estándar de oro de imagen)", "Tomografía computarizada (TC) en situaciones de urgencia", "Biopsia (extracción quirúrgica de una muestra de tejido para determinar el tipo exacto de células en el laboratorio)"] }, treatment: { title: "Tratamientos Oncológicos Pediátricos", intro: "El plan de tratamiento se personaliza en un centro oncológico especializado e incluye:", subsections: [ { title: "Principales modalidades terapéuticas", items: ["Cirugía neurooncológica (para extirpar la mayor cantidad de tumor de forma segura sin dañar tejido cerebral sano)", "Radioterapia (rayos X de alta energía o terapia de protones para matar células cancerosas, evitando su uso en niños muy pequeños para proteger el desarrollo cerebral)", "Quimioterapia (uso de potentes medicamentos para destruir células cancerosas, administrados por vía intravenosa, oral o en el líquido cefalorraquídeo)", "Terapias dirigidas (medicamentos de nueva generación que atacan anomalías específicas dentro de las células cancerosas)", "Rehabilitación intensiva posterior al tratamiento (terapia física, ocupacional y del habla)"] } ], note: "El seguimiento a largo plazo es esencial debido a los posibles efectos tardíos del tratamiento en el cerebro en desarrollo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Pediátrica Urgente?", intro: "Lleve a su hijo al médico o a emergencias de inmediato si presenta:", items: ["Convulsiones de nueva aparición", "Pérdida súbita y severa del equilibrio o problemas para caminar", "Alteraciones inexplicables y persistentes en la visión o un ojo que se desvía", "Episodios recurrentes de vómitos matutinos sin diarrea u otros signos de infección gástrica"] } },
'Degeneración macular' : { intro: "La degeneración macular relacionada con la edad (DMAE) es una de las principales causas de pérdida de visión grave en personas mayores de 60 años. Aunque no causa ceguera total, destruye lentamente la visión central, que es crucial para leer, conducir y reconocer rostros.", whatIs: { title: "¿Qué es la Degeneración macular?", text: "Es una enfermedad progresiva del ojo que daña la mácula (una pequeña área en el centro de la retina). La mácula es responsable de la visión central nítida y detallada que permite enfocar objetos que están directamente frente a nosotros." }, symptoms: { title: "Síntomas Visuales", intro: "En sus primeras etapas, a menudo no presenta síntomas. A medida que avanza, los signos incluyen:", groups: [ { name: "Alteraciones en la visión", items: ["Zonas borrosas u oscuras (puntos ciegos) en el centro de su campo visual", "Distorsión visual; las líneas rectas, como marcos de puertas, parecen onduladas o torcidas", "Necesidad constante de luz más brillante al leer o realizar trabajos de cerca", "Dificultad creciente para reconocer rostros o adaptarse a niveles de luz más bajos"] }, { name: "Características del desarrollo", items: ["Puede afectar un solo ojo primero, haciendo que el otro compense sin que el paciente note el problema", "No afecta la visión periférica (lateral), por lo que rara vez resulta en ceguera total en la oscuridad"] } ], warning: "Ver líneas rectas onduladas es un síntoma urgente de DMAE 'húmeda' que requiere inyecciones oculares rápidas para salvar la visión." }, types: { title: "Tipos de Degeneración Macular", intro: "La enfermedad se manifiesta en dos formas principales:", items: ["DMAE Seca (Atrófica): La forma más común (80-90%). Caracterizada por el adelgazamiento de la mácula y la acumulación de depósitos amarillos (drusas) bajo la retina. Progresa lentamente.", "DMAE Húmeda (Exudativa): Menos común pero mucho más grave. Vasos sanguíneos anormales crecen bajo la retina, goteando sangre y líquido. Puede causar pérdida de visión rápida y devastadora."], note: "La forma seca puede convertirse repentinamente en la forma húmeda en cualquier momento." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta no se conoce del todo, pero está ligada a una combinación de factores:", items: ["Envejecimiento (el factor de riesgo más grande e inevitable)", "Genética y antecedentes familiares de DMAE", "Tabaquismo (fumar duplica el riesgo de desarrollarla)", "Raza (es más común en personas caucásicas)", "Obesidad, presión arterial alta no controlada y enfermedades cardiovasculares", "Dieta pobre en nutrientes antioxidantes y alta en grasas saturadas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un oftalmólogo u optómetra puede diagnosticarla en un examen ocular de rutina mediante:", items: ["Examen del fondo del ojo (con las pupilas dilatadas para buscar drusas en la retina)", "Prueba de la rejilla de Amsler (una cuadrícula para detectar si el paciente ve las líneas rectas como onduladas)", "Tomografía de Coherencia Óptica (OCT) (escáner láser detallado para ver cortes transversales de la retina y detectar líquido)", "Angiografía con fluoresceína (para la forma húmeda, se inyecta un tinte en el brazo para ver si hay vasos sanguíneos goteando en el ojo)"] }, treatment: { title: "Tratamientos y Manejo", intro: "No existe cura, pero los tratamientos pueden ralentizar la progresión o estabilizar la visión:", subsections: [ { title: "Opciones de intervención", items: ["Para la forma Seca: Combinación específica de vitaminas y minerales antioxidantes (Fórmula AREDS2) para ralentizar el daño en etapas intermedias o avanzadas", "Para la forma Húmeda: Inyecciones de medicamentos anti-VEGF en el ojo periódicamente (detienen el crecimiento y goteo de los vasos anormales)", "Terapia fotodinámica y cirugía con láser (menos comunes, para ciertos tipos de DMAE húmeda)", "Rehabilitación visual (uso de lupas especiales, iluminación adecuada y tecnología adaptativa)"] } ], note: "Las inyecciones oculares para la forma húmeda son un milagro médico moderno, previniendo la pérdida de visión severa en la mayoría de los pacientes si se inician a tiempo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Oftalmológica?", intro: "Contacte a su oftalmólogo inmediatamente si:", items: ["Nota que las líneas rectas repentinamente se ven onduladas, torcidas o rotas", "Aparece un punto ciego repentino, borroso u oscuro en el centro de su campo de visión", "Hay una disminución drástica y rápida en la nitidez de su visión central", "Si es mayor de 60 años, debe realizarse exámenes de la vista con dilatación de pupila cada 1-2 años, incluso sin síntomas"] } },
'Agujero macular' : { intro: "Un agujero macular es un pequeño desgarro anatómico en el centro de la retina. Causa visión borrosa y distorsionada en el área central, lo que afecta profundamente la capacidad del paciente para leer, ver rostros y enfocar detalles finos.", whatIs: { title: "¿Qué es un Agujero macular?", text: "Es un defecto, desgarro o rotura de espesor total o parcial en la mácula (la zona central de la retina del ojo). A diferencia de la degeneración macular, que es un deterioro celular, el agujero es una apertura física real en el tejido." }, symptoms: { title: "Síntomas Visuales", intro: "Suele desarrollarse lentamente y en sus inicios puede pasar inadvertido, manifestándose luego como:", groups: [ { name: "Problemas en la visión central", items: ["Ligera visión borrosa o neblinosa (primer síntoma)", "Distorsión visual pronunciada; las líneas rectas o caras parecen onduladas (metamorfopsia)", "Aparición de un punto oscuro o zona vacía y fija en el centro de la visión", "Gran dificultad para leer letras pequeñas o enhebrar una aguja"] }, { name: "Naturaleza de los síntomas", items: ["Por lo general afecta solo a un ojo (aunque con el tiempo puede ocurrir en el otro)", "El síntoma empeora gradualmente si el agujero no se cierra de forma natural o quirúrgicamente", "No causa ningún tipo de dolor físico en el ojo"] } ], warning: "Cualquier aparición de un punto ciego central o líneas distorsionadas es una emergencia oftalmológica para prevenir daño permanente a la retina." }, types: { title: "Etapas de Formación", intro: "El agujero macular evoluciona a través de varias fases:", items: ["Etapa 1 (Inminente/Quiste): El vítreo comienza a tirar de la mácula. Sin desgarro real aún. Muchos se resuelven solos sin intervención.", "Etapa 2 (Agujero pequeño): Aparece un pequeño desgarro físico, afectando la visión.", "Etapa 3 (Agujero grande completo): El desgarro es completo pero aún hay una adherencia parcial del vítreo al disco óptico.", "Etapa 4 (Agujero macular completo y desprendimiento vítreo): Separación completa del vítreo y el agujero está en su tamaño máximo."], note: "El momento de la cirugía depende de la etapa y del impacto en la visión del paciente." }, causes: { title: "Causas y Factores Relacionados", intro: "La causa más común está relacionada con los cambios por la edad en el interior del ojo:", items: ["Contracción del humor vítreo (el gel que llena el ojo). Al envejecer, este gel se encoge y tira fuertemente de la mácula, rompiéndola", "Tracción vitreomacular crónica", "Traumatismos o golpes severos y directos en el ojo", "Ser muy miope (alta miopía)", "Antecedentes de desprendimiento de retina u otras enfermedades oculares severas", "Hinchazón de la mácula a largo plazo (edema macular) por diabetes u otras condiciones"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista en retina lo diagnostica fácilmente a través de:", items: ["Examen de fondo de ojo con pupilas dilatadas (el médico puede ver visualmente el agujero)", "Tomografía de Coherencia Óptica (OCT), la prueba definitiva y más importante; utiliza luz para escanear y crear imágenes transversales precisas de la retina, confirmando el tamaño y la profundidad del agujero", "Angiografía fluoresceínica (ocasionalmente para descartar otras causas vasculares)"], note: "La OCT es indolora, rápida y proporciona imágenes espectaculares de alta resolución del desgarro retinal." }, treatment: { title: "Procedimientos y Cirugía", intro: "El tratamiento varía según la etapa del agujero y los síntomas:", subsections: [ { title: "Enfoque quirúrgico", items: ["Observación cautelosa (para agujeros etapa 1, ya que pueden cerrarse solos en algunos pacientes)", "Inyecciones intravítreas de ocriplasmina (medicamento en el ojo que disuelve las fibras que tiran de la mácula, útil en pocos casos seleccionados)", "Vitrectomía (el tratamiento principal y más exitoso: cirugía para remover el gel vítreo que tira de la retina)", "Uso de un gas intraocular temporal durante la vitrectomía. Una burbuja de gas se inserta en el ojo para presionar los bordes del agujero y ayudar a que sane", "Posicionamiento estricto boca abajo durante varios días o semanas después de la cirugía (vital para que la burbuja de gas haga presión en la parte posterior del ojo)"] } ], note: "La vitrectomía tiene un éxito de cierre de más del 90%, y la mayoría de los pacientes recuperan una visión central funcional." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda con el Especialista?", intro: "Es fundamental acudir rápidamente al oftalmólogo si:", items: ["Siente que hay una mancha negra u opaca en el centro de su visión de un ojo", "Se da cuenta de que las letras saltan, se borran o faltan partes de palabras al leer", "Ve las baldosas del baño, marcos de ventanas o bordes rectos como líneas deformadas", "Experimenta cualquier cambio repentino en la calidad de su visión, independientemente de que no haya dolor"] } },
'Aneurisma' : { intro: "Un aneurisma es una protuberancia o abombamiento anormal en la pared de un vaso sanguíneo. Si no se detecta y llega a romperse, puede causar un sangrado interno potencialmente mortal, requiriendo atención médica de emergencia.", whatIs: { title: "¿Qué es un Aneurisma?", text: "Es el ensanchamiento o dilatación localizada de una arteria, causada por la debilidad en la pared del vaso sanguíneo. Puede ocurrir en cualquier parte del cuerpo, pero los más comunes y graves se localizan en el cerebro o en la aorta." }, symptoms: { title: "Síntomas Comunes", intro: "Los aneurismas intactos rara vez presentan síntomas. Si crecen o se rompen, pueden causar:", groups: [ { name: "Aneurisma roto (Emergencia)", items: ["Dolor de cabeza repentino y extremadamente severo (si es cerebral)", "Dolor agudo y punzante en el pecho, abdomen o espalda (si es aórtico)", "Pérdida de conocimiento, náuseas, vómitos o ritmo cardíaco acelerado"] }, { name: "Aneurisma intacto pero grande", items: ["Dolor localizado encima o detrás del ojo", "Cambios en la visión o pupilas dilatadas", "Sensación pulsátil en el abdomen"] } ], warning: "Un dolor de cabeza súbito y 'el peor de su vida' o un dolor de espalda/pecho desgarrador es una emergencia médica absoluta." }, types: { title: "Tipos Principales", intro: "Se clasifican según su ubicación:", items: ["Aneurisma aórtico (abdominal o torácico)", "Aneurisma cerebral (o intracraneal)", "Aneurismas periféricos (en arterias de las piernas, cuello o riñones)"], note: "El riesgo de ruptura depende del tamaño y la tasa de crecimiento del aneurisma." }, causes: { title: "Causas y Factores de Riesgo", intro: "La debilidad de la pared arterial puede deberse a:", items: ["Presión arterial alta crónica (hipertensión)", "Aterosclerosis (acumulación de placa de colesterol en las arterias)", "Tabaquismo (uno de los mayores factores de riesgo)", "Antecedentes familiares o factores genéticos (como el síndrome de Marfan)", "Traumatismos o infecciones en los vasos sanguíneos"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se descubren accidentalmente durante estudios por otros motivos, o mediante:", items: ["Tomografía computarizada (TC) o Angiografía por TC", "Resonancia magnética (RM) o Angiografía por RM", "Ecografía (muy común para detectar aneurismas aórticos abdominales)", "Angiografía cerebral (estudio invasivo con contraste)"], note: "El diagnóstico temprano y el monitoreo regular son claves para prevenir la ruptura." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento depende del tamaño, ubicación y si se ha roto:", subsections: [ { title: "Enfoques médicos y quirúrgicos", items: ["Monitoreo médico cuidadoso y control estricto de la presión arterial (para aneurismas pequeños)", "Cirugía abierta de 'clipaje' (para aneurismas cerebrales) o reemplazo con injerto (para la aorta)", "Cirugía endovascular (colocación de coils/espirales o stents), un enfoque menos invasivo"] } ], note: "Dejar de fumar y controlar la presión arterial son las medidas preventivas más importantes." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Llame al servicio de emergencias inmediatamente si experimenta:", items: ["Dolor de cabeza súbito e inusualmente intenso", "Dolor repentino y agudo en el pecho, el abdomen o la espalda", "Pérdida repentina de visión, dificultad para hablar o debilidad en un lado del cuerpo"] } },
'Asimetría facial' : { intro: "La asimetría facial ocurre cuando una mitad del rostro no coincide visualmente con la otra. Aunque una ligera asimetría es normal y común, un cambio repentino o pronunciado puede ser un signo de una afección médica subyacente grave.", whatIs: { title: "¿Qué es la Asimetría facial?", text: "Es la falta de proporción o equilibrio entre el lado derecho e izquierdo de la cara. Puede afectar los músculos, los nervios, el tejido blando o la estructura ósea, y puede estar presente desde el nacimiento o desarrollarse repentinamente." }, symptoms: { title: "Síntomas y Señales", intro: "Las manifestaciones varían según la causa, e incluyen:", groups: [ { name: "Asimetría muscular o nerviosa", items: ["Caída repentina de un lado de la cara o de la boca", "Dificultad para sonreír, cerrar un ojo o fruncir el ceño", "Babeo involuntario por un lado de la boca"] }, { name: "Asimetría estructural", items: ["Mandíbula o mentón desviados", "Ojos o pómulos a diferentes alturas", "Desarrollo desigual del tejido facial con el paso del tiempo"] } ], warning: "Si la asimetría aparece de forma brusca, acompañada de debilidad en el brazo o dificultad para hablar, llame a urgencias (posible derrame cerebral)." }, types: { title: "Tipos de Asimetría", intro: "Se puede clasificar en función de su origen:", items: ["Asimetría congénita o genética (presente al nacer, como labio leporino o síndromes craneofaciales)", "Asimetría adquirida de forma aguda (como por Parálisis de Bell o un ACV)", "Asimetría dental/esquelética (problemas de mordida, desviación de mandíbula)"], note: "El tiempo de aparición (lento vs. repentino) es el dato clínico más importante." }, causes: { title: "Causas y Factores", intro: "Las causas pueden ser variadas, desde inofensivas hasta emergencias:", items: ["Derrame cerebral (accidente cerebrovascular) o ataque isquémico transitorio", "Parálisis de Bell (inflamación temporal del nervio facial)", "Traumatismos o fracturas faciales", "Problemas dentales severos o pérdida de dientes", "Tumores de la glándula parótida o del cuello", "Genética y envejecimiento natural"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico realizará una evaluación para determinar la causa subyacente:", items: ["Examen neurológico completo para evaluar los pares craneales", "Tomografía computarizada (TC) o Resonancia Magnética (RM) del cerebro para descartar ACV o tumores", "Radiografías faciales o dentales si se sospecha un problema óseo", "Electromiografía (EMG) para evaluar la salud del nervio facial"], note: "En casos de inicio súbito, el diagnóstico debe ser inmediato." }, treatment: { title: "Opciones de Tratamiento", intro: "El manejo depende exclusivamente de la causa:", subsections: [ { title: "Abordajes terapéuticos", items: ["Atención médica de emergencia con trombolíticos (si es un derrame cerebral)", "Corticosteroides y antivirales, además de protección ocular (para la Parálisis de Bell)", "Cirugía ortognática o tratamientos de ortodoncia (para causas esqueléticas o dentales)", "Fisioterapia facial para recuperar el tono muscular", "Toxina botulínica (Botox) o cirugía plástica/reconstructiva para mejorar la simetría estética"] } ], note: "La Parálisis de Bell suele resolverse por sí sola en unos meses con tratamiento temprano." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Es crucial buscar atención médica inmediata si:", items: ["La cara se cae o paraliza repentinamente", "Se acompaña de debilidad, entumecimiento en otras partes del cuerpo o dificultad para hablar", "Experimenta visión doble, mareos severos o confusión", "Aparece tras un golpe fuerte en la cabeza o la cara"] } },
'Herpes zóster (culebrilla)' : { intro: "El herpes zóster, comúnmente conocido como culebrilla, es una dolorosa erupción cutánea viral. Es causada por el mismo virus que provoca la varicela, el cual puede permanecer latente en el cuerpo durante décadas antes de reactivarse.", whatIs: { title: "¿Qué es el Herpes zóster?", text: "Es una infección viral que causa una erupción dolorosa con ampollas. Ocurre cuando el virus de la varicela-zóster se reactiva en el tejido nervioso cerca de la médula espinal o el cerebro, extendiéndose a lo largo de una vía nerviosa hacia la piel." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen afectar solo una pequeña sección de un lado del cuerpo e incluyen:", groups: [ { name: "Fase inicial (prodrómica)", items: ["Dolor, ardor, entumecimiento o sensación de hormigueo en un lado del cuerpo", "Sensibilidad extrema al tacto", "Fiebre, dolor de cabeza, fatiga o sensibilidad a la luz"] }, { name: "Fase activa", items: ["Erupción roja que aparece unos días después del dolor", "Ampollas llenas de líquido que se abren y forman costras", "Picazón intensa"] } ], warning: "Si la erupción aparece cerca o dentro del ojo (herpes zóster oftálmico), requiere tratamiento inmediato para evitar daño visual permanente." }, types: { title: "Presentaciones Clínicas", intro: "Aunque suele ser localizado, puede tener formas graves:", items: ["Herpes zóster localizado (afecta un solo dermatoma o banda de nervios, a menudo en el torso)", "Herpes zóster oftálmico (afecta el nervio trigémino facial, amenazando el ojo)", "Herpes zóster ótico o Síndrome de Ramsay Hunt (afecta los nervios faciales y auditivos)", "Herpes zóster diseminado (erupción generalizada, común en personas inmunodeprimidas)"], note: "La neuralgia posherpética es una complicación común donde el dolor persiste meses o años después de la erupción." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es causado por la reactivación del virus varicela-zóster. Los factores que lo desencadenan incluyen:", items: ["Envejecimiento (el riesgo aumenta significativamente a partir de los 50 años)", "Sistema inmunológico debilitado (por VIH/SIDA, cáncer o tratamientos médicos)", "Uso prolongado de esteroides o medicamentos inmunosupresores", "Estrés físico o emocional extremo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente, el diagnóstico es clínico:", items: ["Evaluación visual de la erupción característica en forma de banda", "Historial médico del paciente (antecedentes de varicela)", "En casos dudosos, cultivo o prueba de PCR del líquido de las ampollas para confirmar el virus"], note: "Un diagnóstico en las primeras 72 horas desde la erupción es clave para iniciar antivirales." }, treatment: { title: "Tratamientos", intro: "No existe cura, pero el tratamiento temprano reduce la gravedad y complicaciones:", subsections: [ { title: "Opciones farmacológicas", items: ["Medicamentos antivirales orales (aciclovir, valaciclovir o famciclovir) dentro de las primeras 72 horas", "Analgésicos y cremas tópicas (como capsaicina o lidocaína) para el control del dolor", "Corticosteroides en casos seleccionados para reducir la inflamación", "Anticonvulsivos o antidepresivos tricíclicos para tratar la neuralgia posherpética prolongada"] } ], note: "La vacuna contra el herpes zóster (Shingrix) es altamente recomendada y efectiva para adultos mayores de 50 años." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulte a un médico sin demora si:", items: ["La erupción y el dolor se localizan cerca del ojo", "Tiene un sistema inmunológico debilitado", "El sarpullido es extenso y muy doloroso", "La erupción no mejora o hay signos de infección bacteriana secundaria (calor, enrojecimiento extremo)"] } },
'Abuso del alcohol' : { intro: "El abuso del alcohol, médicamente conocido como trastorno por consumo de alcohol (TCA), es una enfermedad crónica que afecta la capacidad de una persona para detener o controlar su consumo, a pesar de las graves consecuencias sociales, ocupacionales y de salud.", whatIs: { title: "¿Qué es el Trastorno por consumo de alcohol?", text: "Es un patrón de consumo de alcohol que implica problemas para controlar la bebida, preocupación constante por el alcohol, y la necesidad de beber más para lograr el mismo efecto (tolerancia), llegando a experimentar síntomas de abstinencia cuando se detiene." }, symptoms: { title: "Síntomas y Comportamientos", intro: "Los signos varían desde leves hasta severos, e incluyen:", groups: [ { name: "Síntomas conductuales y sociales", items: ["Incapacidad para limitar la cantidad de alcohol consumida", "Deseo fuerte o necesidad imperiosa de beber", "Incumplimiento de obligaciones importantes en el trabajo, la escuela o el hogar", "Continuar bebiendo a pesar de los problemas físicos, sociales o interpersonales que causa"] }, { name: "Síntomas físicos (Tolerancia y Abstinencia)", items: ["Necesidad de beber más alcohol para sentir su efecto", "Aparición de náuseas, sudoración, temblores o insomnio al dejar de beber (síndrome de abstinencia)", "Beber alcohol en situaciones peligrosas, como al conducir"] } ], warning: "La abstinencia severa (delirium tremens) puede causar convulsiones, alucinaciones y ser potencialmente mortal, requiriendo desintoxicación médica." }, types: { title: "Clasificación de la Gravedad", intro: "El TCA se clasifica según el número de síntomas presentes:", items: ["Leve (presencia de 2 a 3 síntomas según los criterios del DSM-5)", "Moderado (presencia de 4 a 5 síntomas)", "Grave (presencia de 6 o más síntomas)", "Consumo excesivo episódico (binge drinking), que también conlleva altos riesgos de salud"], note: "Incluso un trastorno leve puede escalar y causar daños significativos a largo plazo." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es una enfermedad compleja influenciada por factores como:", items: ["Genética y antecedentes familiares de problemas con el alcohol", "Factores psicológicos (depresión, ansiedad, trauma, altos niveles de estrés)", "Factores sociales y ambientales (presión de grupo, cultura de consumo)", "Empezar a consumir alcohol a una edad temprana", "Antecedentes de cirugía bariátrica (aumenta el riesgo de sensibilidad metabólica al alcohol)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es clínico y psicológico:", items: ["Evaluación médica y entrevistas basadas en los criterios del DSM-5", "Uso de cuestionarios estandarizados (como el test AUDIT o CAGE)", "Análisis de sangre para evaluar el daño a órganos internos (como la función hepática) y detectar el consumo reciente"], note: "La honestidad del paciente durante la evaluación es fundamental para un diagnóstico preciso." }, treatment: { title: "Tratamientos y Rehabilitación", intro: "La recuperación es un proceso continuo que suele requerir múltiples enfoques:", subsections: [ { title: "Opciones de intervención", items: ["Desintoxicación supervisada médicamente (para manejar la abstinencia de forma segura)", "Terapia cognitivo-conductual (TCC) y asesoramiento psicológico individual o familiar", "Programas de apoyo mutuo y grupos de 12 pasos (como Alcohólicos Anónimos)", "Medicamentos aprobados (como naltrexona, acamprosato o disulfiram) para reducir los antojos o disuadir el consumo", "Tratamiento de afecciones de salud mental concurrentes (patología dual)"] } ], note: "No existe un tratamiento único; el éxito requiere un plan personalizado y un fuerte sistema de apoyo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es hora de buscar ayuda si:", items: ["Siente que no puede controlar cuánto bebe o detenerse una vez que empieza", "Amigos o familiares han expresado preocupación por su forma de beber", "Siente culpa después de beber o necesita beber a primera hora de la mañana", "Ha experimentado 'lagunas' mentales o consecuencias legales debido al alcohol"] } },
'Esclerodermia' : { intro: "La esclerodermia es un grupo de enfermedades autoinmunes raras que provocan el endurecimiento y estiramiento crónico de la piel y los tejidos conectivos. En sus formas más graves, puede afectar los órganos internos y comprometer seriamente la salud.", whatIs: { title: "¿Qué es la Esclerodermia?", text: "Es una enfermedad reumática autoinmune crónica. Ocurre cuando el sistema inmunológico ataca por error el tejido sano, provocando una sobreproducción y acumulación de colágeno, la proteína que forma los tejidos conectivos del cuerpo." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían ampliamente de una persona a otra, afectando diferentes sistemas:", groups: [ { name: "Síntomas cutáneos y vasculares", items: ["Zonas de piel dura, engrosada y tirante (a menudo en los dedos, manos y cara)", "Fenómeno de Raynaud (dedos de manos y pies que se vuelven blancos, azules o rojos, y duelen en respuesta al frío o estrés)", "Llagas o úlceras en las yemas de los dedos", "Aparición de pequeñas manchas rojas en la piel (telangiectasias)"] }, { name: "Afectación de órganos internos", items: ["Reflujo gastroesofágico severo, dificultad para tragar o problemas de motilidad intestinal", "Dificultad para respirar y reducción de la capacidad de ejercicio (si afecta los pulmones)", "Presión arterial alta aguda o insuficiencia renal (crisis renal esclerodérmica)"] } ], warning: "La dificultad progresiva para respirar o un aumento repentino de la presión arterial son urgencias médicas en pacientes con esclerodermia." }, types: { title: "Tipos de Esclerodermia", intro: "Se divide en dos categorías principales:", items: ["Esclerodermia localizada: Afecta solo la piel y tejidos subcutáneos (tipos Morfea y Lineal). Frecuente en niños.", "Esclerosis sistémica cutánea limitada: Afecta la piel de manos/cara y frecuentemente causa el Síndrome de CREST.", "Esclerosis sistémica cutánea difusa: Afecta áreas amplias de la piel y conlleva un alto riesgo de daño temprano a órganos internos (pulmones, corazón, riñones)."], note: "El tipo difuso requiere un monitoreo médico mucho más riguroso." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta de la sobreproducción de colágeno es desconocida, pero intervienen:", items: ["Funcionamiento anormal del sistema inmunológico (autoinmunidad)", "Predisposición genética (ciertos genes aumentan la susceptibilidad)", "Factores ambientales (exposición a ciertos virus, medicamentos o productos químicos tóxicos, como sílice o disolventes)", "Es mucho más común en mujeres que en hombres, generalmente apareciendo entre los 30 y 50 años"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es difícil de diagnosticar porque sus síntomas imitan otras enfermedades. Requiere:", items: ["Examen físico minucioso de la piel", "Análisis de sangre para detectar autoanticuerpos específicos (como anticuerpos antinucleares, anti-Scl-70, anticentrómero)", "Pruebas de función pulmonar y tomografía computarizada (TC) de tórax para evaluar compromiso pulmonar", "Ecocardiograma para revisar el corazón y la presión pulmonar", "Biopsia de piel (en algunos casos para confirmar alteraciones del colágeno)"], note: "El diagnóstico debe ser manejado por un reumatólogo especializado." }, treatment: { title: "Tratamientos", intro: "No existe cura, pero los tratamientos pueden controlar los síntomas y prevenir complicaciones:", subsections: [ { title: "Opciones de manejo", items: ["Medicamentos inmunosupresores (micofenolato, metotrexato) para frenar la actividad de la enfermedad", "Vasodilatadores (bloqueadores de los canales de calcio) para tratar el fenómeno de Raynaud y mejorar el flujo sanguíneo", "Inhibidores de la bomba de protones para el reflujo ácido", "Medicamentos específicos para la hipertensión pulmonar o crisis renal", "Fisioterapia y terapia ocupacional para mantener la movilidad de las articulaciones y la flexibilidad de la piel"] } ], note: "El manejo de la enfermedad sistémica requiere un equipo médico multidisciplinario." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Médica?", intro: "Consulte a un médico si presenta:", items: ["Engrosamiento, tirantez o endurecimiento inexplicable de la piel de las manos o el rostro", "Cambios drásticos de color y dolor en los dedos ante el frío (Raynaud de inicio reciente)", "Dificultad progresiva para tragar o acidez estomacal severa y constante", "Dificultad nueva para respirar al realizar actividades cotidianas"] } },
'Falta de fluidez en el lenguaje' : { intro: "La falta de fluidez en el lenguaje, comúnmente conocida como tartamudez u otros trastornos de la fluidez, afecta el flujo normal y el ritmo del habla. Puede tener un profundo impacto en la comunicación, la autoestima y las interacciones sociales de una persona.", whatIs: { title: "¿Qué son los Trastornos de la Fluidez?", text: "Son interrupciones en la continuidad, ritmo, velocidad y esfuerzo del habla. La persona sabe exactamente lo que quiere decir, pero tiene dificultades para producir el flujo de palabras de manera continua y sin esfuerzo." }, symptoms: { title: "Síntomas Comunes", intro: "Las disfluencias pueden manifestarse de varias formas:", groups: [ { name: "Síntomas vocales", items: ["Repetición de sonidos, sílabas o palabras enteras (p. ej., 'p-p-p-perro')", "Prolongación de sonidos dentro de una palabra (p. ej., 'sssssssssapo')", "Bloqueos o silencios antes o durante las palabras (incapacidad para emitir sonido)", "Uso frecuente de interjecciones ('eh', 'um') para evitar palabras difíciles"] }, { name: "Comportamientos secundarios", items: ["Tensión visible en la cara, cuello o cuerpo al hablar", "Parpadeo rápido, tics faciales o apretar los puños", "Evitación extrema de ciertas palabras, situaciones sociales o hablar por teléfono"] } ], warning: "La ansiedad severa relacionada con el habla puede llevar al aislamiento social significativo." }, types: { title: "Tipos de Disfluencia", intro: "Existen tres tipos principales según su origen:", items: ["Tartamudez del desarrollo (la más común, aparece en la infancia temprana durante la adquisición del lenguaje)", "Tartamudez neurogénica (adquirida por lesiones cerebrales, ACV o enfermedades neurodegenerativas)", "Taquilalia o farfulleo (habla excesivamente rápida y desorganizada, a menudo el hablante no es consciente)", "Tartamudez psicógena (rara, surge tras un trauma emocional severo)"], note: "Es normal que los niños pequeños pasen por una fase temporal de disfluencia entre los 2 y 5 años." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas son complejas y a menudo multifactoriales:", items: ["Factores genéticos (tiende a ser hereditaria, existiendo anomalías en el control motor del habla heredadas)", "Anomalías en la coordinación de las vías cerebrales que controlan el lenguaje", "Traumas neurológicos (ACV, tumores o traumatismos craneoencefálicos en el caso neurogénico)", "Dinámicas familiares estresantes o expectativas de comunicación muy altas pueden exacerbarla (pero no la causan)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un patólogo del habla y el lenguaje (logopeda) realiza una evaluación integral:", items: ["Observación directa del habla del niño o adulto en diferentes contextos y situaciones de lectura", "Análisis de la frecuencia, tipo de disfluencias y comportamientos físicos secundarios", "Evaluación de las habilidades generales de lenguaje, vocabulario y comprensión", "Evaluación del impacto emocional y social del trastorno en la vida diaria del paciente"], note: "En adultos con inicio repentino, se requiere una evaluación neurológica completa." }, treatment: { title: "Terapia y Manejo", intro: "El objetivo no es necesariamente 'curar', sino mejorar la fluidez y la confianza:", subsections: [ { title: "Opciones terapéuticas", items: ["Terapia del habla temprana para niños (enfoque directo e indirecto con participación de los padres)", "Técnicas de modificación de la tartamudez (aprender a tartamudear más suavemente y con menos tensión)", "Técnicas de modelado de fluidez (hablar más lento, regular la respiración)", "Terapia cognitivo-conductual (TCC) para reducir la ansiedad, el miedo y la evitación social", "Dispositivos electrónicos que alteran la retroalimentación auditiva del paciente"] } ], note: "La intervención temprana en preescolares tiene la mayor tasa de éxito en la resolución del problema." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulte a un logopeda si:", items: ["El niño tiene más de 5 años y las repeticiones son frecuentes o están empeorando", "Se observan tensión facial, esfuerzo vocal o frustración al hablar", "La falta de fluidez dura más de 6 meses", "El trastorno comienza repentinamente en la edad adulta", "El problema provoca evitación social o bajo rendimiento escolar/laboral"] } },
'Insomnio psicofisiológico (aprendido)' : { intro: "El insomnio psicofisiológico es un trastorno del sueño persistente impulsado por la ansiedad y comportamientos aprendidos. Se convierte en un ciclo frustrante: el miedo a no poder dormir causa la misma excitación que impide conciliar el sueño.", whatIs: { title: "¿Qué es el Insomnio psicofisiológico?", text: "También conocido como insomnio condicionado o aprendido, ocurre cuando una persona desarrolla una excesiva preocupación y ansiedad por no poder dormir. El entorno de la cama se asocia inconscientemente con el estado de alerta y la frustración, en lugar de la relajación." }, symptoms: { title: "Síntomas y Patrones", intro: "Los afectados presentan un patrón clásico de activación nocturna:", groups: [ { name: "Síntomas al intentar dormir", items: ["Excitación mental excesiva ('mente acelerada') al acostarse", "Tensión muscular, aumento de la frecuencia cardíaca al acercarse la hora de dormir", "Esfuerzo mental agotador por intentar 'forzar' el sueño", "Sensación de fatiga extrema durante el día, pero incapacidad para tomar siestas"] }, { name: "Comportamientos condicionados", items: ["Capacidad para dormir sin problemas cuando no están en su propia cama (sofá, hotel, sillón)", "Dormirse fácilmente frente al televisor, pero despertarse completamente alerta al trasladarse a la cama"] } ], warning: "El uso crónico y no supervisado de somníferos para tratar este insomnio puede generar dependencia y empeorar el problema subyacente." }, types: { title: "Relación con otros trastornos", intro: "Suele diferenciarse de otros tipos de insomnio:", items: ["A diferencia del insomnio idiopático (causa biológica desconocida desde la infancia), el psicofisiológico es adquirido.", "A diferencia del insomnio comórbido (causado directamente por depresión, dolor o apnea), aquí el problema principal es la ansiedad por el sueño en sí."], note: "Es común que este insomnio comience por un evento estresante externo, pero persista mucho tiempo después de que el estrés original haya desaparecido." }, causes: { title: "Causas y Desarrollo", intro: "El desarrollo de este trastorno sigue un proceso de condicionamiento:", items: ["Desencadenante inicial (un período de estrés agudo, dolor, duelo o cambios de turno que provoca insomnio temporal)", "Preocupación subsiguiente por la falta de sueño y el impacto en el rendimiento diurno", "Asociación negativa (condicionamiento): la cama y la rutina de noche se convierten en señales neurológicas de estrés y alerta", "Malos hábitos de sueño (quedarse en la cama frustrado, mirar el reloj constantemente, usar pantallas)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico lo realiza un especialista en sueño basándose en:", items: ["Entrevista clínica detallada sobre la historia, patrones de sueño y pensamientos sobre el dormir", "Uso de un diario de sueño de 1 a 2 semanas y cuestionarios de ansiedad", "Exclusión de causas médicas, psiquiátricas o relacionadas con medicamentos", "Polisomnografía (estudio del sueño en laboratorio) solo si se sospecha apnea del sueño u otros trastornos físicos subyacentes"], note: "El indicador clave es dormir mejor fuera del dormitorio habitual." }, treatment: { title: "Tratamiento y Reentrenamiento", intro: "El objetivo es romper la asociación negativa con la cama. La primera línea de tratamiento es psicológica:", subsections: [ { title: "Terapias conductuales", items: ["Terapia Cognitivo-Conductual para el Insomnio (TCC-I), el estándar de oro y más efectivo que los medicamentos", "Terapia de control de estímulos (usar la cama solo para dormir/sexo; levantarse si no se duerme en 20 minutos)", "Restricción del sueño (limitar el tiempo en la cama para aumentar la presión biológica de sueño)", "Higiene del sueño (horarios regulares, evitar cafeína/alcohol, ambiente oscuro y fresco)", "Técnicas de relajación (relajación muscular progresiva, meditación, biofeedback)"] } ], note: "Los medicamentos hipnóticos pueden usarse a corto plazo, pero no resuelven el condicionamiento psicológico subyacente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda?", intro: "Consulte a un especialista en sueño o psicólogo clínico si:", items: ["El insomnio ocurre al menos 3 noches por semana durante más de 3 meses", "La preocupación por el sueño domina sus pensamientos durante el día", "La fatiga está afectando gravemente su trabajo, conducción o relaciones personales", "Depende del alcohol o pastillas de venta libre para lograr dormir"] } },
'Fluorosis' : { intro: "La fluorosis es una condición cosmética y física que afecta principalmente a los dientes (y rara vez a los huesos) debido a una sobreexposición sostenida al flúor durante etapas críticas del desarrollo infantil.", whatIs: { title: "¿Qué es la Fluorosis?", text: "Es una alteración en la estructura del esmalte dental (y en casos extremos, del tejido óseo) causada por el consumo excesivo de fluoruro durante los primeros ocho años de vida, cuando los dientes permanentes se están formando bajo las encías." }, symptoms: { title: "Síntomas Visuales y Físicos", intro: "La fluorosis dental no causa dolor, solo afecta la apariencia. Los síntomas se dividen por gravedad:", groups: [ { name: "Fluorosis dental (Leve a Moderada)", items: ["Aparición de pequeñas manchas o estrías de color blanco tiza opaco en la superficie del diente", "Las manchas pueden cubrir hasta el 50% de la superficie del diente", "El esmalte dental se siente liso al tacto"] }, { name: "Fluorosis dental grave y esquelética", items: ["Manchas oscuras (de color marrón a negro) incrustadas en el esmalte", "Superficie dental rugosa, picada y con el esmalte frágil o desmenuzado", "En la fluorosis esquelética (endémica en zonas con agua muy rica en flúor natural): rigidez y dolor en las articulaciones, calcificación de ligamentos y deformidades óseas"] } ], warning: "La fluorosis solo ocurre mientras los dientes se desarrollan; los adultos no pueden desarrollar fluorosis dental por el flúor." }, types: { title: "Niveles de Severidad (Índice de Dean)", intro: "La fluorosis dental se clasifica clínicamente en:", items: ["Dudosa/Muy leve: Algunas manchas blancas esparcidas, difícilmente visibles.", "Leve: Áreas blancas opacas más extensas, pero no afectan todo el diente.", "Moderada: Afecta a todas las superficies dentales, con un claro desgaste o manchas marrones leves.", "Severa: Esmalte muy dañado, poroso, con fosas profundas y manchas marrones extensas."], note: "En la mayoría de los países desarrollados, los casos son exclusivamente de nivel muy leve a leve." }, causes: { title: "Causas y Fuentes de Flúor", intro: "Se produce por ingerir demasiado flúor crónicamente en la infancia a través de:", items: ["Tragar frecuentemente pasta de dientes o enjuagues bucales fluorados en lugar de escupirlos", "Consumo excesivo de suplementos de flúor en gotas o pastillas", "Agua potable de pozos naturales con niveles anormalmente altos de flúor geológico", "Fórmulas infantiles preparadas regularmente con agua muy fluorada"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un dentista diagnostica la afección fácilmente mediante:", items: ["Examen visual clínico rutinario de los dientes", "Evaluación del historial de consumo de agua, dieta y hábitos de higiene dental durante la infancia", "En casos de sospecha de fluorosis esquelética, se utilizan radiografías, densitometría ósea y análisis de sangre/orina"], note: "Es importante que el dentista la diferencie de caries tempranas, deficiencias nutricionales o uso de antibióticos como la tetraciclina." }, treatment: { title: "Tratamiento y Estética", intro: "La fluorosis leve no requiere tratamiento médico. Los casos moderados o graves se abordan estéticamente:", subsections: [ { title: "Procedimientos dentales", items: ["Blanqueamiento dental profesional (para quitar manchas superficiales en casos leves)", "Microabrasión del esmalte (eliminar una capa microscópica del esmalte afectado)", "Adhesión dental (aplicar una resina del color del diente para cubrir las manchas)", "Carillas de porcelana o coronas (para los casos más severos con daño estructural al esmalte)"] } ], note: "La prevención es vital: supervisar a los niños pequeños mientras se cepillan para asegurarse de que usan solo un tamaño de 'guisante' de pasta y que escupen." }, whenToSeekHelp: { title: "¿Cuándo Buscar Consulta Dental?", intro: "Debe programar una visita al dentista u ortodoncista si:", items: ["Nota manchas blancas marcadas, líneas o coloración marrón en los dientes permanentes de su hijo a medida que erupcionan", "El esmalte de los dientes de su hijo parece picado, rugoso o se astilla con facilidad", "Desea opciones estéticas para mejorar la apariencia de su propia sonrisa afectada por fluorosis"] } },
'Miastenia grave' : { intro: "La miastenia grave es un trastorno neuromuscular crónico que causa debilidad severa y fatiga en los músculos voluntarios. Sus síntomas fluctúan a lo largo del día, empeorando con la actividad y mejorando con el descanso.", whatIs: { title: "¿Qué es la Miastenia grave?", text: "Es una enfermedad autoinmune en la que los anticuerpos destruyen la comunicación normal entre los nervios y los músculos. Esto bloquea la transmisión de las señales nerviosas (acetilcolina), impidiendo que los músculos se contraigan con fuerza." }, symptoms: { title: "Síntomas Característicos", intro: "La debilidad muscular puede afectar diferentes partes del cuerpo e incluye:", groups: [ { name: "Síntomas oculares y faciales", items: ["Caída de uno o ambos párpados (ptosis) - a menudo el primer síntoma", "Visión doble (diplopía) que mejora al cerrar un ojo", "Pérdida de la expresión facial (parece una 'sonrisa forzada')", "Debilidad en la mandíbula al masticar carne o alimentos duros"] }, { name: "Síntomas bulbares y sistémicos", items: ["Dificultad progresiva para tragar (disfagia), con riesgo de asfixia", "Cambios en la voz (suena nasal o muy apagada)", "Debilidad en los brazos, manos, dedos, piernas y cuello", "Dificultad para respirar por debilidad de los músculos del pecho"] } ], warning: "Una 'crisis miasténica' es una emergencia donde los músculos respiratorios se debilitan tanto que requieren asistencia con un ventilador para respirar." }, types: { title: "Subtipos Clínicos", intro: "Se puede clasificar según los músculos afectados y los anticuerpos:", items: ["Miastenia grave ocular (la debilidad se limita solo a los músculos de los ojos y párpados)", "Miastenia grave generalizada (afecta músculos oculares, faciales, bulbares y de las extremidades)", "Miastenia neonatal transitoria (bebés nacidos de madres con la enfermedad, que generalmente se recuperan en semanas)"], note: "Hasta un 15% de los pacientes tienen un tumor en la glándula timo (timoma) asociado con la enfermedad." }, causes: { title: "Causas y Fisiopatología", intro: "El origen es un ataque del propio sistema inmunológico autoinmune:", items: ["Producción de autoanticuerpos que bloquean o destruyen los receptores de acetilcolina en la unión neuromuscular", "Anticuerpos contra la tirosina quinasa específica del músculo (MuSK) o LRP4", "Anomalías en la glándula timo (órgano del sistema inmune en el pecho) que parece desencadenar la producción de estos anticuerpos", "Puede empeorar por fatiga, enfermedades, estrés, calor extremo o ciertos medicamentos (betabloqueantes, algunos antibióticos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El neurólogo utiliza una combinación de pruebas especializadas:", items: ["Examen neurológico detallado para evaluar reflejos y fuerza muscular", "Análisis de sangre para detectar niveles altos de anticuerpos receptores de acetilcolina o anticuerpos MuSK", "Electromiografía de fibra simple (EMG) para medir la comunicación eléctrica entre el nervio y el músculo", "Prueba de la bolsa de hielo ocular o prueba de edrofonio (Tensilon) para ver si hay una mejora temporal de la fuerza", "Tomografía computarizada (TC) o resonancia magnética (RM) del tórax para buscar un timoma"], note: "El diagnóstico temprano es vital para prevenir complicaciones graves respiratorias y de deglución." }, treatment: { title: "Tratamientos y Terapias", intro: "El tratamiento es altamente efectivo para restaurar la fuerza muscular:", subsections: [ { title: "Intervenciones médicas y quirúrgicas", items: ["Inhibidores de la colinesterasa (como la piridostigmina) para mejorar la comunicación nervio-músculo temporalmente", "Inmunosupresores (corticosteroides, azatioprina, micofenolato, rituximab) para detener el ataque inmunológico", "Plasmaféresis o inmunoglobulina intravenosa (IGIV) para tratamientos rápidos durante una crisis severa", "Timectomía (cirugía para extirpar la glándula timo), que puede mejorar significativamente o incluso curar a muchos pacientes", "Nuevas terapias dirigidas (anticuerpos monoclonales como eculizumab o efgartigimod)"] } ], note: "La mayoría de los pacientes pueden llevar una vida normal con el tratamiento médico continuo adecuado." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Busque atención de emergencia inmediatamente si:", items: ["Tiene dificultad repentina o grave para respirar o necesita esforzarse mucho para tomar aire", "Comienza a atragantarse con frecuencia al tragar líquidos o alimentos", "Experimenta dificultad para masticar, sostener la cabeza erguida o caminar", "Sufre episodios de visión doble o caída de los párpados de aparición reciente"] } },
'Coágulo en las piernas' : { intro: "Un coágulo de sangre en la pierna, conocido médicamente como Trombosis Venosa Profunda (TVP), es una afección vascular peligrosa. Si el coágulo se desprende, puede viajar a los pulmones y causar una embolia pulmonar, lo cual es potencialmente fatal.", whatIs: { title: "¿Qué es la Trombosis Venosa Profunda (TVP)?", text: "Es la formación de un trombo (coágulo de sangre) en una vena profunda del cuerpo, típicamente en la pantorrilla, el muslo o la pelvis. Este coágulo bloquea el flujo sanguíneo normal y causa una grave inflamación local." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "La TVP puede ocurrir sin síntomas notables, pero a menudo se presenta con:", groups: [ { name: "Síntomas en la pierna afectada", items: ["Hinchazón (edema) repentina, generalmente en una sola pierna", "Dolor intenso, calambres o sensibilidad, que a menudo comienza en la pantorrilla o el muslo", "Enrojecimiento o decoloración (tono azulado o pálido) de la piel en la zona afectada", "La piel sobre el coágulo se siente inusualmente caliente al tacto"] }, { name: "Signos de Embolia Pulmonar (Emergencia)", items: ["Falta de aire repentina e inexplicable", "Dolor punzante en el pecho que empeora al respirar profundamente", "Tos con sangre y mareos o desmayos"] } ], warning: "La combinación de hinchazón dolorosa en una pierna seguida de dificultad para respirar es una emergencia extrema (TVP progresando a Embolia Pulmonar)." }, types: { title: "Tipos de Coágulos Venosos", intro: "Las condiciones trombóticas en las extremidades inferiores se dividen en:", items: ["Trombosis Venosa Profunda (TVP): Ocurre en las venas profundas, es la más peligrosa por el riesgo de embolia.", "Tromboflebitis superficial: Coágulos en venas cerca de la superficie de la piel. Causan dolor y enrojecimiento, pero rara vez viajan a los pulmones."], note: "La TVP profunda requiere un tratamiento anticoagulante inmediato y riguroso." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los coágulos se forman cuando el flujo sanguíneo se ralentiza o se altera:", items: ["Inmovilidad prolongada (reposo en cama en el hospital, vuelos largos o viajes en coche sin pausas)", "Lesión directa en la vena por cirugía mayor (especialmente de cadera o rodilla), traumatismos o fracturas óseas", "Condiciones que aumentan la coagulación (cáncer, embarazo, uso de anticonceptivos orales o terapia hormonal, tabaquismo, obesidad)", "Trastornos genéticos de la coagulación heredados (como el Factor V de Leiden)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Dado que es una urgencia, el médico debe confirmar rápidamente usando:", items: ["Ecografía Doppler venosa de las piernas (la prueba principal, no invasiva y que visualiza el flujo de sangre y el coágulo)", "Análisis de sangre del dímero D (niveles elevados sugieren la presencia de degradación de un coágulo)", "Venografía (prueba más antigua con contraste, raramente usada hoy salvo casos complejos)", "Tomografía computarizada o RM si se sospecha que el coágulo está en el abdomen o pelvis o si ya viajó al pulmón"], note: "El diagnóstico ecográfico debe realizarse ante la más mínima sospecha clínica." }, treatment: { title: "Tratamiento y Prevención", intro: "El objetivo principal es evitar que el coágulo crezca o viaje a los pulmones:", subsections: [ { title: "Estrategias de manejo", items: ["Medicamentos anticoagulantes o 'diluyentes de la sangre' (heparina, warfarina, apixabán, rivaroxabán) durante meses", "Trombolíticos (medicamentos potentes para disolver coágulos por vía intravenosa, usados solo en casos muy severos)", "Colocación de un filtro en la vena cava inferior (para atrapar coágulos antes de que lleguen al pulmón, si el paciente no puede tomar anticoagulantes)", "Uso de medias de compresión graduada (para reducir la hinchazón y prevenir el síndrome postrombótico)", "Elevación frecuente de las piernas y caminar regularmente"] } ], note: "La anticoagulación a menudo debe mantenerse de 3 a 6 meses, o indefinidamente si el paciente tiene factores de riesgo persistentes." }, whenToSeekHelp: { title: "¿Cuándo Buscar Atención Médica de Urgencia?", intro: "Debe acudir inmediatamente al servicio de emergencias médicas si:", items: ["Su pierna o brazo se hincha repentinamente, se enrojece y se vuelve doloroso y caliente", "Presenta dolor en el pecho, dificultad repentina e intensa para respirar, o tose sangre", "Se marea profusamente o experimenta latidos cardíacos muy rápidos junto con el dolor en la pierna"] } },
'Adherencias' : { intro: "Las adherencias son bandas anormales de tejido cicatricial denso. Actúan como una 'cinta adhesiva' interna que une órganos y tejidos que normalmente deberían estar separados y moverse libremente, causando a menudo dolor crónico u obstrucciones graves.", whatIs: { title: "¿Qué son las Adherencias?", text: "Son formaciones de tejido fibroso interno que se desarrollan como una respuesta del cuerpo a la cicatrización después de una cirugía, infección o inflamación. Principalmente ocurren en el abdomen y la pelvis, pegando órganos entre sí (como los intestinos a la pared abdominal)." }, symptoms: { title: "Síntomas y Complicaciones", intro: "Muchas adherencias no causan problemas, pero cuando lo hacen, los síntomas incluyen:", groups: [ { name: "Síntomas digestivos y abdominales", items: ["Dolor abdominal crónico, sordo o en forma de calambres agudos, a menudo alrededor del ombligo", "Hinchazón severa, náuseas recurrentes y vómitos", "Incapacidad para evacuar gases o heces (signo de obstrucción intestinal)"] }, { name: "Síntomas pélvicos y reproductivos", items: ["Dolor pélvico crónico persistente o dolor intenso durante las relaciones sexuales (dispareunia)", "Infertilidad femenina (si las adherencias bloquean las trompas de Falopio)"] } ], warning: "Una obstrucción intestinal parcial o total causada por adherencias es una emergencia quirúrgica potencialmente mortal si se estrangula el intestino." }, types: { title: "Ubicaciones Comunes", intro: "Las adherencias se clasifican generalmente por su ubicación en el cuerpo:", items: ["Adherencias abdominales (la forma más común, unen intestinos, omento, estómago o hígado)", "Adherencias pélvicas (involucran útero, ovarios, trompas de Falopio y vejiga)", "Adherencias cardíacas (entre el corazón y el pericardio tras cirugía cardíaca)", "Adherencias en articulaciones (como el 'hombro congelado' capsulitis adhesiva)"], note: "Las adherencias son la causa número uno de obstrucción del intestino delgado en adultos." }, causes: { title: "Causas y Factores Desencadenantes", intro: "El cuerpo forma adherencias en un intento de reparar tejidos dañados debido a:", items: ["Cirugías abdominales o pélvicas previas (como apendicectomías, cesáreas, histerectomías o cirugías de vesícula; es la causa más frecuente)", "Enfermedades inflamatorias (Enfermedad de Crohn, apendicitis, enfermedad pélvica inflamatoria)", "Endometriosis (tejido similar al revestimiento del útero que crece fuera de él)", "Infecciones abdominales (peritonitis) o tratamientos de radioterapia en el área pélvica/abdominal"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "Son muy difíciles de diagnosticar porque no aparecen claramente en exámenes estándar:", items: ["Historial médico minucioso evaluando cirugías previas y el tipo de dolor", "Tomografía computarizada (TC) o radiografías de abdomen con contraste (para buscar obstrucciones intestinales, aunque no ven las adherencias en sí)", "Cirugía laparoscópica (la única forma definitiva de confirmar y ver las adherencias directamente)", "Histerosalpingografía o ecografía (para evaluar el bloqueo de trompas en casos de infertilidad)"], note: "Frecuentemente, las adherencias se diagnostican y tratan simultáneamente durante una cirugía exploratoria." }, treatment: { title: "Manejo y Cirugía", intro: "Dado que la cirugía en sí misma puede causar más adherencias, se manejan con precaución:", subsections: [ { title: "Enfoque de tratamiento", items: ["Enfoque conservador (para dolor crónico leve o bloqueos parciales): dieta baja en residuos, fluidos intravenosos, analgésicos", "Lisis de adherencias (Adhesiólisis): cirugía laparoscópica o abierta para cortar cuidadosamente las bandas de cicatriz y liberar los órganos", "Uso de barreras antiadherentes (láminas o geles especiales colocados durante la cirugía) para intentar prevenir la formación de nuevas cicatrices", "Tratamiento de fertilidad asistida (FIV) si las adherencias pélvicas no pueden repararse quirúrgicamente"] } ], note: "La cirugía solo se recomienda si las adherencias causan dolor debilitante, obstrucción o problemas graves de infertilidad." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Quirúrgica Urgente?", intro: "Diríjase de inmediato a un servicio de emergencias si ha tenido cirugías abdominales previas y experimenta:", items: ["Dolor abdominal intenso, progresivo y constante, similar a calambres severos", "Vómitos repetidos e incapacidad para retener líquidos o alimentos", "Distensión (hinchazón) masiva del abdomen", "Imposibilidad total de expulsar gases o defecar durante más de 24 horas"] } },
'Coagulopatía' : { intro: "Una coagulopatía es un trastorno del sistema de coagulación de la sangre. Puede manifestarse de dos maneras peligrosas: impidiendo que la sangre coagule adecuadamente (provocando hemorragias graves) o causando una coagulación excesiva (formando trombos que bloquean vasos sanguíneos).", whatIs: { title: "¿Qué es una Coagulopatía?", text: "Es una afección en la cual la capacidad de la sangre para formar coágulos normales está deteriorada. Esto se debe a una deficiencia, disfunción o ausencia de las proteínas esenciales de la sangre conocidas como 'factores de coagulación' o de las plaquetas." }, symptoms: { title: "Síntomas Comunes", intro: "Los trastornos de sangrado (los más comunes) se manifiestan principalmente con:", groups: [ { name: "Signos de sangrado superficial", items: ["Aparición fácil de moretones grandes (equimosis) sin un golpe evidente", "Hemorragias nasales frecuentes, abundantes y difíciles de detener", "Sangrado prolongado por cortes pequeños, extracciones dentales o cirugías menores", "Menstruaciones anormalmente pesadas y prolongadas en las mujeres (menorragia)"] }, { name: "Signos de hemorragia grave profunda", items: ["Sangrado espontáneo dentro de las articulaciones (hemartrosis), causando dolor agudo e hinchazón", "Sangrado en músculos profundos o tejidos blandos", "Sangrado en el tracto digestivo (heces negras o con sangre) o hematuria (sangre en la orina)", "Hemorragia intracraneal (la complicación más letal, causando dolor de cabeza y problemas neurológicos)"] } ], warning: "Cualquier traumatismo en la cabeza en una persona con coagulopatía diagnosticada requiere una tomografía computarizada inmediata, incluso sin síntomas evidentes." }, types: { title: "Tipos y Clasificación", intro: "Se dividen fundamentalmente en congénitas (hereditarias) y adquiridas:", items: ["Enfermedad de Von Willebrand (la coagulopatía hereditaria más común, por falta de esta proteína esencial)", "Hemofilia A (deficiencia del factor VIII) y Hemofilia B (deficiencia del factor IX)", "Coagulopatía Intravascular Diseminada (CID) (una emergencia médica adquirida donde la sangre coagula masivamente y luego sangra al agotar los factores)", "Deficiencia de vitamina K o coagulopatía por enfermedad hepática grave"], note: "Las formas adquiridas suelen ser complicaciones secundarias de otras enfermedades graves o del uso de ciertos medicamentos." }, causes: { title: "Causas y Desencadenantes", intro: "Los problemas en los factores de coagulación surgen debido a:", items: ["Mutaciones genéticas heredadas (en Hemofilias y enf. de Von Willebrand)", "Enfermedad hepática crónica (cirrosis, hepatitis severa), ya que el hígado produce casi todos los factores de coagulación", "Efectos secundarios de medicamentos (sobredosis de anticoagulantes, ciertos antibióticos)", "Falta de Vitamina K (esencial para sintetizar factores de coagulación)", "Transfusiones masivas de sangre (que diluyen los factores de coagulación)", "Reacciones autoinmunes severas o infecciones abrumadoras (sepsis)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere una evaluación hematológica exhaustiva con pruebas de laboratorio:", items: ["Análisis de sangre básicos: Recuento de plaquetas", "Pruebas de tiempos de coagulación: Tiempo de protrombina (TP/INR) y Tiempo de tromboplastina parcial activada (TTPa)", "Ensayos de factores de coagulación específicos (para identificar la deficiencia exacta de factores VIII, IX, Von Willebrand, etc.)", "Pruebas de función hepática y niveles de vitamina K"], note: "Un historial familiar detallado de problemas de sangrado es crucial para guiar el diagnóstico de los tipos hereditarios." }, treatment: { title: "Tratamientos Especializados", intro: "El tratamiento es muy específico y depende de la causa exacta y el tipo de deficiencia:", subsections: [ { title: "Terapias de reemplazo y manejo", items: ["Terapia de reemplazo de factores de coagulación intravenosos (preventiva o a demanda, p. ej., para hemofílicos)", "Desmopresina (DDAVP) para estimular la liberación del factor de Von Willebrand", "Transfusiones de plasma fresco congelado o crioprecipitado en casos de emergencia por sangrado agudo", "Administración de Vitamina K (si hay deficiencia o para revertir ciertos anticoagulantes)", "Medicamentos antifibrinolíticos (ácido tranexámico) para prevenir la descomposición de los coágulos mucosos (boca, útero)"] } ], note: "Las personas con coagulopatías congénitas deben recibir atención en centros de tratamiento especializados en hematología." }, whenToSeekHelp: { title: "¿Cuándo Buscar Atención Médica de Urgencia?", intro: "Es fundamental buscar asistencia médica inmediata si la persona afectada:", items: ["Sufre cualquier tipo de golpe fuerte en la cabeza o el abdomen", "Tiene un sangrado que no se detiene después de 10 a 15 minutos de presión continua", "Presenta dolor intenso e hinchazón repentina en articulaciones (rodillas, codos)", "Experimenta un dolor de cabeza repentino, intenso, acompañado de confusión o vómitos", "Vomita sangre o tiene heces oscuras, alquitranadas o sanguinolentas"] } },
'Psicosis' : { intro: "La psicosis es un término médico psiquiátrico que describe una pérdida de contacto severa con la realidad. No es una enfermedad en sí misma, sino un síntoma profundo de diversas condiciones subyacentes, que interfiere drásticamente con la capacidad de percibir el mundo de manera lógica y compartida.", whatIs: { title: "¿Qué es la Psicosis?", text: "Es un estado mental anormal donde la persona experimenta dificultades procesando la información. Esto provoca que vean, escuchen o crean cosas que no son reales. Implica una desorganización profunda del pensamiento y la percepción." }, symptoms: { title: "Síntomas Principales", intro: "Un episodio psicótico se caracteriza fundamentalmente por dos síntomas clave y alteraciones del pensamiento:", groups: [ { name: "Alteraciones de la percepción y creencia", items: ["Alucinaciones: Percibir cosas inexistentes (frecuentemente escuchar voces insultantes o amenazantes, o ver cosas)", "Delirios: Creencias falsas e inquebrantables, a menudo paranoicas o de grandeza (ej. creer que se es perseguido o se tiene una misión divina)"] }, { name: "Desorganización mental y comportamental", items: ["Pensamiento y habla gravemente desorganizados (saltar de un tema a otro sin lógica, inventar palabras)", "Comportamiento motor extraño, agitado o completamente catatónico (inmóvil e insensible)", "Pérdida de emociones, abandono del cuidado personal y aislamiento social extremo"] } ], warning: "Durante un brote psicótico, el individuo rara vez tiene 'conciencia de enfermedad' (anosognosia), por lo que un familiar debe buscar ayuda." }, types: { title: "Trastornos Asociados", intro: "La psicosis es el síntoma principal en varios trastornos mentales y físicos:", items: ["Esquizofrenia (el trastorno psicótico crónico más común)", "Trastorno bipolar o depresión mayor con características psicóticas (psicosis afectiva)", "Trastorno esquizoafectivo (combina síntomas de esquizofrenia y trastornos del estado de ánimo)", "Psicosis inducida por sustancias (debido a drogas alucinógenas, estimulantes o alcohol)", "Psicosis orgánica o médica (por demencia, infecciones cerebrales, tumores o delirium)"], note: "El primer episodio psicótico en jóvenes (entre 15 y 25 años) requiere intervención médica intensiva inmediata." }, causes: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de la psicosis es multifactorial, involucrando:", items: ["Predisposición genética (antecedentes familiares de trastornos psicóticos)", "Desequilibrios químicos en el cerebro (particularmente hiperactividad de la dopamina)", "Traumas psicológicos severos, estrés extremo o abuso durante la infancia", "Consumo excesivo de drogas recreativas (cannabis de alta potencia, metanfetaminas, LSD)", "Enfermedades neurológicas orgánicas, privación extrema de sueño o fiebres muy altas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere una evaluación exhaustiva por parte de un psiquiatra, que incluye:", items: ["Entrevista psiquiátrica clínica detallada evaluando el estado mental del paciente", "Entrevistas con familiares para determinar el inicio y gravedad de los cambios de comportamiento", "Análisis de sangre y pruebas de toxicología (para descartar el consumo de drogas o trastornos metabólicos)", "Neuroimagen (Resonancia Magnética o TC cerebral) y EEG para descartar causas neurológicas (tumores, epilepsia temporal)"], note: "Descartar causas médicas o inducidas por drogas es el primer paso vital antes de diagnosticar esquizofrenia." }, treatment: { title: "Intervenciones y Terapias", intro: "El tratamiento de la psicosis requiere un enfoque médico y psicológico combinado:", subsections: [ { title: "Opciones de estabilización y mantenimiento", items: ["Medicamentos antipsicóticos (neurolépticos) como pilar fundamental del tratamiento para equilibrar los neurotransmisores", "Hospitalización psiquiátrica aguda en casos donde hay riesgo para la persona o para los demás", "Terapia cognitivo-conductual (TCC) adaptada para psicosis (ayuda al paciente a lidiar con los síntomas y evaluar la realidad de sus creencias)", "Programas de apoyo familiar, psicoeducación y rehabilitación psicosocial (para ayudar al paciente a reintegrarse a la sociedad y al trabajo)"] } ], note: "La recuperación es posible. El tratamiento temprano tras el primer brote psicótico mejora drásticamente el pronóstico a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Psiquiátrica Urgente?", intro: "Acuda inmediatamente a un servicio de emergencias médicas o psiquiátricas si usted o un ser querido:", items: ["Habla sobre intenciones de hacerse daño a sí mismo o a otras personas", "Muestra una paranoia severa, creyendo que está en peligro inminente y actuando agresivamente", "Se vuelve incapaz de cuidar de sus necesidades básicas de supervivencia (comer, beber, higiene)", "Habla constantemente con personas invisibles o está aterrorizado por alucinaciones incontrolables"] } },
'Estenosis pilórica' : { intro: "La estenosis pilórica es un problema grave que afecta el tracto gastrointestinal de los lactantes (bebés muy pequeños). Causa vómitos explosivos constantes que, si no se diagnostican rápidamente, conducen a una deshidratación severa y pérdida de peso que amenazan la vida del recién nacido.", whatIs: { title: "¿Qué es la Estenosis pilórica?", text: "Es el engrosamiento e hinchazón anormal del músculo del píloro (la válvula que conecta el estómago con el intestino delgado). Al engrosarse, esta válvula se estrecha fuertemente (estenosis), impidiendo que la leche y los alimentos pasen del estómago al intestino." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "Los síntomas raramente están presentes al nacer; suelen aparecer entre las 3 y 5 semanas de vida:", groups: [ { name: "Síntomas digestivos", items: ["Vómitos 'en proyectil' o explosivos (la leche es expulsada con gran fuerza, a menudo a centímetros de distancia) poco después de alimentarse", "Hambre constante o irritabilidad del bebé inmediatamente después de haber vomitado", "Ondas visibles y ondulatorias en la parte superior del abdomen del bebé justo antes de vomitar (el estómago tratando de forzar la comida)"] }, { name: "Signos de complicaciones graves", items: ["Deshidratación rápida (menos pañales mojados, letargo, fontanela o 'mollera' hundida, llanto sin lágrimas)", "Estancamiento en el crecimiento y pérdida progresiva de peso", "Estreñimiento prolongado (heces escasas) debido a la falta de alimentos llegando a los intestinos"] } ], warning: "Cualquier vómito violento y repetido en un bebé menor de 2 meses requiere evaluación en emergencias el mismo día." }, types: { title: "Tipos y Presentación", intro: "Clínicamente, la afección es muy específica:", items: ["Estenosis hipertrófica del píloro infantil (la forma clásica, adquirida en el primer mes de vida).", "La condición es de 4 a 5 veces más común en niños varones que en niñas, y frecuentemente afecta a los hijos primogénitos."], note: "Es importante que el médico la diferencie de un simple reflujo gastroesofágico (donde el bebé babea o regurgita la leche sin fuerza)." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta por la que este músculo se hipertrofia (engrosa) es desconocida, pero se asocia con:", items: ["Factores genéticos (hay un fuerte componente de herencia familiar, especialmente si uno de los padres la tuvo)", "Factores ambientales y factores hormonales posnatales", "Uso temprano de ciertos antibióticos (como la eritromicina) en las dos primeras semanas de vida del bebé", "Tabaquismo materno o uso de biberones (alimentación artificial) se han relacionado débilmente como factores de riesgo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra o el especialista de urgencias confirmará el diagnóstico usando:", items: ["Examen físico minucioso (el médico puede palpar a menudo un bulto en el abdomen con forma de 'oliva', que es el músculo engrosado)", "Ecografía abdominal (la prueba de elección, no invasiva, que muestra el engrosamiento del músculo pilórico con claridad absoluta)", "Análisis de sangre completos para evaluar la gravedad de la deshidratación y los desequilibrios de electrolitos", "Estudio de tránsito esofagogastroduodenal con bario (radiografía, solo si la ecografía no es concluyente)"], note: "Antes de cualquier tratamiento definitivo, la estabilización de los niveles de líquidos en el bebé es el paso más urgente." }, treatment: { title: "Cirugía y Recuperación", intro: "La condición se resuelve mediante una cirugía de rutina de alta efectividad, pero requiere preparación previa:", subsections: [ { title: "Protocolo de tratamiento", items: ["Terapia intensiva con fluidos intravenosos para rehidratar al bebé y corregir desequilibrios químicos (el paso inicial crítico)", "Cirugía correctiva (Piloromiotomía): un procedimiento mínimamente invasivo (generalmente laparoscópico) donde el cirujano corta la capa exterior del músculo pilórico engrosado para permitir que la válvula se expanda y la comida pase", "Reanudación gradual de la alimentación con leche materna o fórmula dentro de las 12 a 24 horas posteriores a la cirugía"] } ], note: "La piloromiotomía es curativa, tiene muy bajo riesgo de complicaciones y el bebé suele ser dado de alta en un par de días." }, whenToSeekHelp: { title: "¿Cuándo Llevar al Bebé a Urgencias?", intro: "Busque atención médica de emergencia pediátrica de inmediato si su bebé:", items: ["Vomita con gran fuerza la mayor parte o toda la toma, repetidas veces", "Parece inusualmente irritable, débil, muy somnoliento o letárgico", "No ha mojado un pañal en varias horas", "Muestra signos visibles de pérdida de peso o está inusualmente demacrado"] } },
'Dolor de rodilla' : { intro: "El dolor de rodilla es una de las quejas musculoesqueléticas más frecuentes en personas de todas las edades. Dado que la rodilla es una articulación compleja que soporta gran parte del peso del cuerpo, puede lesionarse fácilmente o sufrir desgaste con el tiempo, afectando drásticamente la movilidad diaria.", whatIs: { title: "¿Qué es el Dolor de rodilla?", text: "Es un síntoma común que indica un problema en la estructura compleja de la articulación de la rodilla, la cual está compuesta por huesos, cartílago, ligamentos, tendones y bolsas de líquido (bursas). Puede originarse por una lesión repentina, un uso excesivo o una afección médica crónica." }, symptoms: { title: "Síntomas y Signos Asociados", intro: "El dolor rara vez ocurre de forma aislada. La gravedad y ubicación varían, pero los síntomas acompañantes incluyen:", groups: [ { name: "Limitaciones de movilidad", items: ["Dolor severo que impide apoyar el peso en la pierna afectada", "Rigidez extrema por la mañana o después de estar sentado", "Incapacidad para enderezar o flexionar la rodilla completamente", "Sensación de debilidad o inestabilidad ('la rodilla cede' o falla al caminar)"] }, { name: "Signos físicos", items: ["Hinchazón e inflamación visible (aumento de volumen) alrededor de la articulación", "Enrojecimiento y sensación de calor al tacto", "Ruidos crujientes, chasquidos o estallidos dolorosos al mover la articulación (crepitación)", "Deformidad visible en el contorno normal de la rodilla"] } ], warning: "Una rodilla que de repente no soporta peso, está masivamente hinchada o presenta deformidad es una emergencia ortopédica." }, types: { title: "Clasificación según la Causa", intro: "El dolor suele categorizarse según su origen mecánico o sistémico:", items: ["Lesiones agudas (fracturas, desgarro del ligamento cruzado anterior - LCA, desgarro de menisco)", "Problemas mecánicos (cuerpos libres articulares, luxación de rótula)", "Problemas de sobreuso crónico (tendinitis rotuliana, síndrome de dolor patelofemoral o 'rodilla de corredor')", "Tipos de artritis (osteoartritis degenerativa, artritis reumatoide, gota o artritis infecciosa)"], note: "Localizar si el dolor es frontal, lateral o posterior ayuda al médico a diagnosticar la estructura afectada." }, causes: { title: "Causas y Factores de Riesgo", intro: "La articulación de la rodilla es altamente vulnerable debido a:", items: ["Práctica de deportes de alto impacto (fútbol, baloncesto, esquí, que implican giros bruscos o saltos)", "Sobrepeso u obesidad (aumenta drásticamente la presión y el desgaste del cartílago, precipitando la osteoartritis)", "Falta de flexibilidad, calentamiento inadecuado o desequilibrios de fuerza muscular en piernas y caderas", "Envejecimiento natural y desgaste del cartílago (artrosis)", "Traumatismos directos, accidentes automovilísticos o caídas fuertes", "Anomalías biomecánicas preexistentes (pies planos, discrepancia en longitud de las piernas)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico para identificar el tejido dañado requiere:", items: ["Historial detallado sobre cómo y cuándo empezó el dolor o cómo ocurrió la lesión", "Examen físico con pruebas de estrés específicas (tirar y empujar la articulación para evaluar la estabilidad de los ligamentos)", "Radiografías (Rayos X) para detectar fracturas, desgaste del espacio articular o espolones óseos", "Resonancia magnética (RM) (el mejor método para ver tejidos blandos como desgarros de menisco, ligamentos o músculos)", "Análisis del líquido sinovial (extracción de líquido con aguja para descartar infección bacteriana o cristales de gota)"], note: "En problemas de rodilla, la RM ha reemplazado a la cirugía exploratoria con gran precisión." }, treatment: { title: "Opciones de Tratamiento", intro: "El manejo va desde el autocuidado hasta el reemplazo articular total:", subsections: [ { title: "Terapias escalonadas", items: ["Manejo agudo inicial con el protocolo RICE: Reposo, Hielo (Ice), Compresión (vendaje) y Elevación de la pierna", "Uso de antiinflamatorios no esteroideos (AINEs) o analgésicos para controlar el dolor y la inflamación", "Fisioterapia rigurosa (para fortalecer los músculos que estabilizan la rodilla, especialmente cuádriceps e isquiotibiales)", "Inyecciones articulares (corticosteroides para inflamación severa, o ácido hialurónico como lubricante temporal)", "Cirugía artroscópica mínimamente invasiva (para reparar meniscos o ligamentos rasgados)", "Reemplazo parcial o total de rodilla (artroplastia) para casos de artritis destructiva avanzada en adultos mayores"] } ], note: "La pérdida de peso guiada y el ejercicio de bajo impacto son la cura a largo plazo más efectiva para el dolor artrítico crónico." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico Traumatólogo?", intro: "Es imprescindible acudir al médico sin demora si:", items: ["No puede poner ningún peso sobre su rodilla o siente que la pierna va a colapsar bajo su peso", "La rodilla está visiblemente deformada después de un trauma", "Tiene inflamación severa y súbita de la rodilla acompañada de enrojecimiento y fiebre (riesgo de infección)", "Experimenta un dolor de rodilla insoportable que empeora rápidamente, o es incapaz de estirarla por completo"] } },
'Púrpura trombocitopénica idiopática (ITP)' : { intro: "La púrpura trombocitopénica idiopática (ITP) es un trastorno de la sangre caracterizado por una disminución anormal en el número de plaquetas, lo que dificulta la coagulación y provoca la aparición de hematomas y sangrados excesivos sin causa aparente.", whatIs: { title: "¿Qué es la ITP?", text: "Es una enfermedad autoinmune en la cual el sistema inmunológico ataca y destruye por error las plaquetas de la sangre (células necesarias para la coagulación normal), dejándolas en niveles peligrosamente bajos." }, symptoms: { title: "Síntomas Comunes", intro: "A veces no presenta síntomas graves, pero cuando ocurren, incluyen:", groups: [ { name: "Signos en la piel", items: ["Aparición fácil y excesiva de moretones (púrpura)", "Pequeñas manchas rojizas o moradas en la piel que parecen un sarpullido (petequias), generalmente en la parte inferior de las piernas"] }, { name: "Problemas de sangrado", items: ["Sangrado prolongado por cortes menores", "Sangrado espontáneo de las encías o la nariz", "Sangre en la orina o en las heces", "Flujo menstrual inusualmente abundante"] } ], warning: "Un sangrado que no se detiene o un sangrado en el cerebro (aunque raro) es una emergencia médica que requiere tratamiento inmediato." }, types: { title: "Clasificación de la ITP", intro: "Se divide principalmente en dos formas según su duración:", items: ["ITP Aguda (a corto plazo): Común en niños, generalmente aparece después de una infección viral y suele desaparecer sola en menos de 6 meses.", "ITP Crónica (a largo plazo): Más común en adultos (especialmente mujeres jóvenes) y dura más de 6 meses o incluso años."], note: "Los niños rara vez necesitan tratamiento médico intensivo, mientras que los adultos a menudo sí lo requieren." }, causes: { title: "Causas y Factores de Riesgo", intro: "La destrucción de las plaquetas ocurre debido a:", items: ["Un mal funcionamiento del sistema inmunológico que produce anticuerpos contra las propias plaquetas", "En los niños, a menudo se desencadena por una infección viral reciente (como paperas o gripe)", "Infecciones crónicas en adultos, como el VIH, la hepatitis C o la bacteria H. pylori", "No es una enfermedad contagiosa ni se transmite de persona a persona"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para diagnosticar la ITP y descartar otras causas de bajo recuento de plaquetas, el médico realiza:", items: ["Un examen físico completo para buscar signos de sangrado, petequias o agrandamiento del bazo", "Análisis de sangre completo (Hemograma) para verificar si el número de plaquetas es bajo mientras los glóbulos rojos y blancos son normales", "Frotis de sangre (observar la sangre bajo un microscopio)", "En casos raros o en adultos mayores, un examen de médula ósea para descartar problemas de producción de células sanguíneas"], note: "El diagnóstico de ITP a menudo se hace por descarte de otras enfermedades de la sangre." }, treatment: { title: "Opciones de Tratamiento", intro: "El objetivo no es curar la enfermedad, sino mantener niveles seguros de plaquetas:", subsections: [ { title: "Enfoque médico", items: ["Observación y monitoreo cuidadoso (a menudo el único 'tratamiento' necesario para los niños)", "Corticosteroides (como prednisona) para reducir la actividad del sistema inmunológico", "Inmunoglobulina intravenosa (IGIV) para aumentar rápidamente el recuento de plaquetas en casos de sangrado crítico", "Medicamentos agonistas del receptor de trombopoyetina (para estimular a la médula ósea a producir más plaquetas)", "Esplenectomía (cirugía para extirpar el bazo) si los medicamentos no funcionan, ya que el bazo es donde se destruyen muchas plaquetas"] } ], note: "Las personas con ITP deben evitar medicamentos de venta libre que afecten la coagulación, como la aspirina o el ibuprofeno." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Consulte a un médico de urgencias o hematólogo si:", items: ["Presenta un sangrado abundante que no puede detenerse aplicando presión durante 15 minutos", "Experimenta dolores de cabeza severos repentinos o confusión (posible sangrado intracraneal)", "Nota la aparición repentina de múltiples moretones grandes o un sarpullido de petequias generalizado", "Observa sangre en sus heces, orina o vómitos"] } },
'Postura jorobada' : { intro: "La postura jorobada, conocida médicamente como cifosis, es una curvatura exagerada hacia adelante de la parte superior de la espalda. Aunque puede afectar a cualquier edad, es común en adolescentes por malos hábitos posturales o en adultos mayores debido a problemas de la columna vertebral.", whatIs: { title: "¿Qué es la Cifosis (Postura jorobada)?", text: "Es una deformidad de la columna vertebral en la que la zona dorsal (parte superior de la espalda) presenta una curva hacia adelante superior a los 50 grados, dando a la espalda un aspecto redondeado o encorvado." }, symptoms: { title: "Síntomas y Signos Físicos", intro: "Las manifestaciones varían según la gravedad de la curvatura:", groups: [ { name: "Síntomas visuales y físicos", items: ["Hombros caídos y espalda visiblemente redondeada o con una 'joroba'", "La cabeza tiende a inclinarse hacia adelante en relación con el resto del cuerpo", "Dolor leve a severo en la parte media o superior de la espalda", "Rigidez o tensión muscular en la espalda y el cuello"] }, { name: "Complicaciones graves", items: ["Dificultad para respirar (si la curva severa comprime los pulmones)", "Problemas digestivos como reflujo ácido o dificultad para tragar", "Entumecimiento o debilidad en las piernas (si hay compresión nerviosa)"] } ], warning: "Si la curvatura aparece rápidamente o va acompañada de debilidad en las piernas o pérdida de control de esfínteres, requiere evaluación neurológica urgente." }, types: { title: "Tipos de Cifosis", intro: "Se clasifica según su causa subyacente:", items: ["Cifosis postural: La más común, causada por encorvarse constantemente. No hay daño estructural en los huesos.", "Cifosis de Scheuermann: Aparece en la adolescencia; las vértebras tienen forma de cuña en lugar de ser rectangulares.", "Cifosis congénita: Presente al nacer debido a un desarrollo anormal de la columna fetal.", "Cifosis relacionada con la edad (osteoporótica): Causada por fracturas por compresión en vértebras debilitadas por la osteoporosis."], note: "La cifosis postural es la única que el paciente puede corregir activamente enderezándose." }, causes: { title: "Causas y Factores de Riesgo", intro: "El encorvamiento de la columna puede originarse por:", items: ["Malos hábitos de postura prolongados (uso del celular, computadoras, cargar mochilas pesadas de forma incorrecta)", "Osteoporosis y adelgazamiento de los huesos (común en mujeres mayores)", "Degeneración de los discos espinales por el envejecimiento", "Enfermedades que afectan la columna, como espina bífida, enfermedad de Paget, o tumores", "Tratamientos previos de radiación en la columna durante la niñez"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un traumatólogo u ortopedista confirmará el diagnóstico mediante:", items: ["Examen físico (prueba de inclinación hacia adelante de Adam para evaluar la curva de la columna)", "Radiografías de la columna vertebral (para medir el ángulo exacto de la curvatura y ver deformidades óseas)", "Pruebas de densidad ósea (Densitometría) si se sospecha osteoporosis", "Resonancia magnética (RM) si hay síntomas neurológicos o se sospecha de un tumor o infección"], note: "Medir el ángulo de Cobb en la radiografía es fundamental para clasificar la gravedad." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento depende del tipo de cifosis, la edad y la severidad:", subsections: [ { title: "Intervenciones comunes", items: ["Fisioterapia y ejercicios de fortalecimiento del núcleo y la espalda (efectivo para la cifosis postural)", "Uso de analgésicos para controlar el dolor de espalda recurrente", "Medicamentos para la osteoporosis para prevenir futuras fracturas de vértebras", "Uso de un corsé ortopédico (especialmente en adolescentes con cifosis de Scheuermann en crecimiento)", "Cirugía de fusión espinal (solo para curvaturas extremadamente severas que causan dolor intratable o comprometen órganos internos)"] } ], note: "Mantener un peso saludable y hacer ejercicio regular previene el empeoramiento en muchos casos." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico?", intro: "Es recomendable buscar evaluación médica si:", items: ["Nota que la curva en su espalda alta empeora progresivamente", "Experimenta dolor de espalda persistente o intenso que interfiere con su vida diaria", "Tiene dificultad para respirar de forma profunda y sin esfuerzo", "Siente hormigueo, debilidad o entumecimiento en las piernas o brazos"] } },
'Tapón de cerumen' : { intro: "El tapón de cerumen es una causa muy común y reversible de pérdida de audición. Ocurre cuando la cera natural producida por el oído se acumula y se endurece, bloqueando el canal auditivo e interrumpiendo el paso del sonido.", whatIs: { title: "¿Qué es un Tapón de cerumen?", text: "Es una obstrucción del conducto auditivo externo causada por la acumulación excesiva o impactación de cerumen (cera). El cerumen es una secreción normal que protege y limpia el oído, pero a veces no se expulsa adecuadamente." }, symptoms: { title: "Síntomas Comunes", intro: "La obstrucción del oído puede causar molestias como:", groups: [ { name: "Alteraciones auditivas", items: ["Disminución temporal o pérdida parcial de la audición en el oído afectado", "Zumbidos, pitidos o ruidos en el oído (tinnitus)", "Sensación de plenitud, taponamiento o de tener el 'oído ocupado'"] }, { name: "Síntomas físicos y molestias", items: ["Dolor leve o sensación de presión en el oído (otalgia)", "Picazón interna constante", "Mareos leves o alteraciones del equilibrio (menos frecuente)", "Tos refleja (porque la cera presiona un nervio en el canal auditivo)"] } ], warning: "Nunca introduzca hisopos de algodón, horquillas o llaves en el oído; esto solo empuja el tapón más profundamente y puede perforar el tímpano." }, types: { title: "Características de la Impactación", intro: "Aunque es una sola condición, se puede describir por sus características:", items: ["Cerumen blando: Acumulación reciente o de textura naturalmente blanda, fácil de lavar.", "Cerumen duro/seco: Tapones antiguos y compactados que requieren agentes ablandadores antes de la extracción.", "Impactación total: Bloquea el 100% del canal, causando síntomas auditivos graves.", "Impactación parcial: Permite pasar algo de sonido, pero causa molestias y riesgo de infección."], note: "El color del cerumen varía naturalmente del amarillo claro al negro oscuro y no indica infección." }, causes: { title: "Causas y Factores de Riesgo", intro: "El cerumen suele salir por sí solo. Los tapones se forman principalmente debido a:", items: ["Uso de hisopos de algodón (bastoncillos) que empujan la cera hacia adentro y la compactan", "Uso frecuente de audífonos intraurales o tapones para los oídos que bloquean la salida natural de la cera", "Anatomía del canal auditivo (canales inusualmente estrechos, curvos o con mucho vello)", "Sobreproducción de cerumen provocada por el estrés, la genética o condiciones de la piel (eczema)", "Envejecimiento (el cerumen se vuelve más seco y difícil de expulsar en los adultos mayores)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es visual, rápido e indoloro. El médico o especialista realiza:", items: ["Otoscopia: El uso de un otoscopio (un instrumento con luz y aumento) para mirar dentro del canal auditivo y confirmar la presencia del bloqueo", "Evaluación de los síntomas del paciente para descartar infecciones o daños en el tímpano"], note: "Un diagnóstico correcto es vital para asegurar que la pérdida auditiva no sea causada por problemas neurológicos o del oído medio." }, treatment: { title: "Métodos de Extracción Segura", intro: "La extracción debe realizarse de forma segura, preferiblemente por un profesional:", subsections: [ { title: "Opciones de tratamiento clínico", items: ["Uso de gotas cerumenolíticas (peróxido de hidrógeno, glicerina, aceite mineral) aplicadas en casa durante unos días para ablandar la cera", "Irrigación del oído (lavado con agua tibia a presión suave) en el consultorio médico", "Extracción manual utilizando un pequeño instrumento curvo (cureta), una sonda de succión o micropinzas bajo visión directa del médico", "Evitar las 'velas de oído' (conoterapia), ya que no tienen evidencia científica de funcionar y pueden causar quemaduras graves"] } ], note: "Si usted tiene antecedentes de tímpano perforado o cirugía de oído, nunca debe intentar lavar el oído en casa ni usar gotas sin receta." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Médico?", intro: "Debe programar una cita médica si:", items: ["La pérdida de audición es repentina o muy molesta", "Experimenta dolor agudo de oído, fiebre o supuración de líquido amarillento/verdoso (posible infección)", "Sufre de mareos intensos o problemas serios de equilibrio", "Los tratamientos de venta libre para ablandar la cera no han funcionado después de varios días"] } },
'Violencia de género' : { intro: "La violencia de género es un grave problema de salud pública y de derechos humanos. Comprende cualquier acto perjudicial perpetrado contra una persona en base a las diferencias socialmente asignadas (género), causando un profundo daño físico, sexual, psicológico o económico.", whatIs: { title: "¿Qué es la Violencia de Género?", text: "Es cualquier tipo de agresión física, psicológica, sexual o institucional, dirigida hacia una persona por su identidad de género o sexo. Afecta abrumadoramente a las mujeres y niñas, y se basa en desigualdades de poder sistémicas y discriminación." }, symptoms: { title: "Signos y Consecuencias en la Salud", intro: "Las víctimas a menudo sufren graves secuelas de salud física y mental, que incluyen:", groups: [ { name: "Consecuencias físicas", items: ["Lesiones inexplicables, moretones, fracturas o quemaduras frecuentes", "Dolor crónico, síndromes de fatiga y dolores de cabeza persistentes", "Trastornos gastrointestinales derivados del estrés extremo", "Infecciones de transmisión sexual o embarazos no deseados en casos de violencia sexual"] }, { name: "Consecuencias psicológicas y de comportamiento", items: ["Depresión severa, ansiedad clínica y ataques de pánico", "Trastorno de Estrés Postraumático (TEPT) e insomnio agudo", "Aislamiento de familiares y amigos, baja autoestima y miedo constante", "Comportamientos autolesivos o ideación suicida"] } ], warning: "Si usted o alguien que conoce está en peligro físico inminente, llame inmediatamente a los servicios de emergencia o a las líneas directas de atención a víctimas locales." }, types: { title: "Tipos de Violencia", intro: "La violencia de género se manifiesta de múltiples formas, a menudo superpuestas:", items: ["Violencia física (golpear, empujar, estrangular o usar armas)", "Violencia psicológica o emocional (insultos, humillaciones, aislamiento, control coercitivo, luz de gas o 'gaslighting')", "Violencia sexual (cualquier acto sexual no consentido, coerción, acoso o explotación)", "Violencia económica (controlar las finanzas, prohibir trabajar, negar recursos básicos)", "Violencia digital (acoso en línea, control de redes sociales, difusión de imágenes íntimas sin consentimiento)"], note: "El maltrato psicológico y económico suele ser la antesala del abuso físico." }, causes: { title: "Raíces y Factores de Riesgo", intro: "No existe una excusa válida para la violencia. Sus raíces son sociales y estructurales:", items: ["Normas culturales y sociales que fomentan la desigualdad de género y la subordinación de la mujer", "Antecedentes de exposición a la violencia en la niñez (ciclo intergeneracional)", "Dependencia económica extrema respecto al abusador", "El consumo abusivo de alcohol o drogas por parte del agresor (actúa como catalizador, no como causa raíz)", "Falta de redes de apoyo social o aislamiento comunitario"] }, diagnosis: { title: "Detección en el Ámbito Médico", intro: "El personal de salud está capacitado para identificar signos de abuso mediante:", items: ["Preguntas de rutina en consultas médicas sobre seguridad en el hogar y relaciones personales", "Evaluación de lesiones que no coinciden con la explicación de cómo ocurrieron", "Identificación de patrones de consultas frecuentes por síntomas psicosomáticos inespecíficos", "Observación de dinámicas controladoras si la pareja acompaña al paciente a la consulta médica"], note: "Los médicos mantienen la confidencialidad, salvo excepciones legales de riesgo de vida extremo." }, treatment: { title: "Intervención y Apoyo", intro: "El abordaje requiere protección legal, apoyo psicológico y atención médica:", subsections: [ { title: "Recursos y Vías de Acción", items: ["Atención médica de urgencia para tratar lesiones físicas o profilaxis tras violencia sexual", "Terapia psicológica especializada en trauma para la recuperación emocional y el empoderamiento", "Contacto con líneas de ayuda nacionales, refugios de emergencia y organizaciones de apoyo a la mujer", "Asesoramiento legal para la obtención de órdenes de restricción o protección judicial", "Elaboración de un 'Plan de Seguridad' con profesionales para planificar una salida segura del entorno abusivo"] } ], note: "Romper el silencio es el primer paso. El objetivo primordial es garantizar la seguridad física y emocional inmediata de la persona afectada." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Pida ayuda inmediata a servicios de emergencia (policía, líneas de la mujer, hospitales) si:", items: ["Sufre agresiones físicas, amenazas con armas o intentos de asfixia/estrangulamiento", "Teme razonablemente por su vida, la integridad de sus hijos o de sus mascotas", "Está siendo retenida contra su voluntad o le impiden comunicarse con el exterior", "Necesita atención médica por golpes, violencia sexual o crisis de salud mental severa"] } },
'Varicela' : { intro: "La varicela es una infección viral muy contagiosa conocida por causar un sarpullido con picazón extrema y ampollas en todo el cuerpo. Antiguamente una enfermedad común de la infancia, hoy es prevenible gracias a la vacunación sistemática.", whatIs: { title: "¿Qué es la Varicela?", text: "Es una enfermedad infecciosa causada por el virus varicela-zóster. Produce una erupción cutánea pruriginosa con ampollas llenas de líquido que posteriormente se rompen y forman costras. Aunque suele ser leve en niños, puede ser grave en adultos y personas inmunodeprimidas." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas aparecen entre 10 y 21 días después de la exposición al virus:", groups: [ { name: "Síntomas iniciales (Fase prodrómica)", items: ["Fiebre leve a moderada", "Sensación de fatiga, malestar general o irritabilidad", "Pérdida de apetito y dolor de cabeza"] }, { name: "Evolución de la erupción (Sarpullido)", items: ["Fase 1: Bultos elevados de color rosa o rojo (pápulas) que brotan en varios días", "Fase 2: Las pápulas se convierten rápidamente en pequeñas ampollas llenas de líquido (vesículas)", "Fase 3: Las ampollas se rompen, filtran líquido y se cubren con costras protectoras", "Picazón intensa en todo el cuerpo, a veces afectando el interior de la boca, garganta o zona genital"] } ], warning: "No se debe dar aspirina a niños o adolescentes con varicela, ya que puede desencadenar el Síndrome de Reye, una complicación rara pero mortal." }, types: { title: "Riesgos y Complicaciones", intro: "Generalmente es una enfermedad única, pero el virus permanece en el cuerpo:", items: ["Varicela no complicada: Curso normal en niños sanos, resolviéndose en un par de semanas.", "Varicela grave o complicada: Puede causar neumonía viral, encefalitis (inflamación del cerebro) o infecciones bacterianas severas en la piel.", "Herpes zóster (culebrilla): Años o décadas después de la varicela, el virus inactivo en los nervios puede reactivarse causando esta dolorosa erupción."], note: "El riesgo de complicaciones es mayor en bebés, adolescentes, embarazadas y personas con sistemas inmunes debilitados." }, causes: { title: "Causas y Transmisión", intro: "Es provocada por el virus varicela-zóster (VZV). Es extremadamente contagiosa a través de:", items: ["Inhalación de gotitas respiratorias en el aire cuando una persona infectada tose o estornuda", "Contacto directo con el líquido que supura de las ampollas abiertas", "Una persona es contagiosa desde 48 horas antes de que aparezca el sarpullido hasta que todas las ampollas se hayan cubierto de costras"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente no requiere pruebas complejas, el médico la diagnostica mediante:", items: ["Examen físico visual confirmando el aspecto clásico del sarpullido y las etapas concurrentes de las ampollas", "Evaluación de los síntomas concurrentes como fiebre y exposición reciente", "Pruebas de laboratorio (análisis de sangre o cultivo del líquido de la ampolla) solo si el diagnóstico es incierto o hay complicaciones graves"], note: "Se recomienda llamar al médico antes de ir a la clínica para evitar contagiar a otros pacientes en la sala de espera." }, treatment: { title: "Tratamiento y Cuidados", intro: "Para personas sanas, el tratamiento se centra en aliviar los síntomas mientras el cuerpo combate el virus:", subsections: [ { title: "Medidas de alivio y médicas", items: ["Baños de agua tibia con avena coloidal o bicarbonato de sodio para calmar la picazón", "Uso de loción de calamina en las áreas afectadas (no usar cerca de los ojos)", "Antihistamínicos orales para controlar la picazón severa e inducir el sueño", "Medicamentos para la fiebre que no contengan aspirina (como paracetamol/acetaminofén)", "Medicamentos antivirales (como el aciclovir) prescritos solo para pacientes de alto riesgo si se inician en las primeras 24 horas", "Prevención: La vacuna contra la varicela es la medida más efectiva, administrada en dos dosis en la infancia"] } ], note: "Es crucial evitar rascarse para prevenir infecciones bacterianas secundarias en la piel y cicatrices permanentes." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Médico?", intro: "Consulte a un profesional de la salud de inmediato si la persona con varicela:", items: ["Tiene el sarpullido extendido a uno o ambos ojos", "Presenta un área de piel muy roja, caliente, sensible e hinchada (signo de infección bacteriana)", "Experimenta mareos severos, desorientación, latidos rápidos, temblores o dificultad grave para respirar", "La fiebre supera los 39 °C (102 °F) de forma constante"] } },
'Queratoglobo' : { intro: "El queratoglobo es una deformidad ocular sumamente rara que afecta la córnea (la capa transparente frontal del ojo). A diferencia de otras deformidades localizadas, hace que toda la córnea se vuelva extremadamente delgada y adquiera forma esférica, comprometiendo gravemente la visión.", whatIs: { title: "¿Qué es el Queratoglobo?", text: "Es un trastorno degenerativo y no inflamatorio del ojo. Se caracteriza por un adelgazamiento generalizado, de borde a borde, del tejido de la córnea, lo que hace que esta sobresalga hacia adelante formando un globo casi perfecto en lugar de su curva suave natural." }, symptoms: { title: "Síntomas Visuales", intro: "Los síntomas suelen aparecer en la primera infancia o adolescencia, empeorando progresivamente:", groups: [ { name: "Problemas de visión", items: ["Miopía extrema (dificultad severa para ver de lejos)", "Astigmatismo irregular alto, causando visión distorsionada, borrosa o doble", "Deslumbramiento constante y gran sensibilidad a la luz (fotofobia)", "Necesidad de cambiar la graduación de las gafas con mucha frecuencia"] }, { name: "Signos físicos", items: ["Ojos que parecen anormalmente saltones o grandes debido a la córnea globulosa", "Adelgazamiento extremo de la córnea, haciéndola excepcionalmente frágil", "Cicatrices en la córnea en casos avanzados"] } ], warning: "Debido a la extrema delgadez del tejido, cualquier golpe menor en el ojo puede causar una rotura corneal (perforación del ojo), que es una emergencia quirúrgica catastrófica." }, types: { title: "Diferencia con otros trastornos corneales", intro: "A menudo se confunde con condiciones similares, pero tiene características únicas:", items: ["A diferencia del Queratocono (donde solo el centro/parte inferior se adelgaza en forma de cono), en el Queratoglobo toda la córnea se adelgaza y abomba.", "A diferencia de la Degeneración Marginal Pelúcida (donde el adelgazamiento es estrictamente en la banda inferior de la córnea)."], note: "El queratoglobo es bilateral (afecta a ambos ojos) y suele ser más grave y difícil de tratar que el queratocono." }, causes: { title: "Causas y Factores Genéticos", intro: "El origen exacto se desconoce, pero está fuertemente ligado a defectos genéticos del colágeno:", items: ["Asociación con enfermedades del tejido conectivo hereditarias (como el Síndrome de Ehlers-Danlos o la osteogénesis imperfecta - 'huesos de cristal')", "Asociación con la amaurosis congénita de Leber (una enfermedad rara de la retina)", "A menudo, hay antecedentes familiares de trastornos del colágeno", "A diferencia del queratocono, no suele estar tan asociado con frotarse vigorosamente los ojos"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El oftalmólogo especialista en córnea requiere equipos avanzados para confirmar el diagnóstico:", items: ["Topografía corneal computarizada (crea un mapa 3D de la superficie del ojo para ver la forma globular característica)", "Paquimetría (mide el grosor de la córnea, revelando un adelgazamiento masivo de borde a borde, a menudo de 1/3 del grosor normal)", "Examen con lámpara de hendidura (para visualizar el adelgazamiento y descartar otras patologías oculares)", "Evaluación sistémica conjunta con genetistas o reumatólogos para descartar síndromes de tejido conectivo asociados"], note: "El diagnóstico temprano es vital no solo para la visión, sino para educar al paciente sobre el altísimo riesgo de trauma." }, treatment: { title: "Manejo y Opciones Quirúrgicas", intro: "El tratamiento es un gran desafío médico debido a la fragilidad extrema del ojo:", subsections: [ { title: "Opciones terapéuticas", items: ["Uso constante de gafas de protección (policarbonato) para prevenir cualquier traumatismo ocular accidental", "Gafas convencionales para etapas iniciales, aunque rápidamente se vuelven ineficaces", "Lentes de contacto esclerales rígidos grandes (que se apoyan en la parte blanca del ojo sin tocar la frágil córnea) para corregir la visión", "Cross-linking corneal (tratamiento con vitamina B2 y luz UV) para endurecer el colágeno restante y detener la progresión", "Trasplante de córnea (Queratoplastia penetrante u otras técnicas avanzadas) como último recurso. Es una cirugía de altísimo riesgo en estos pacientes debido a la falta de tejido sano en los bordes para suturar el injerto"] } ], note: "La educación sobre la protección ocular estricta a lo largo de toda la vida es el aspecto más crítico del manejo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Atención Oftalmológica Urgente?", intro: "Acuda inmediatamente a un servicio de emergencias o cirujano oftalmólogo si:", items: ["Sufre cualquier tipo de golpe directo en el ojo, la cara o la cabeza", "Experimenta un dolor ocular repentino, intenso y agudo", "La visión se vuelve blanca, extremadamente nublada o se pierde repentinamente (signo de hidropesía corneal aguda o rotura)", "Siente que hay salida de líquido caliente del ojo"] } },
'Accidente cerebrovascular' : { intro: "Un accidente cerebrovascular (ACV), comúnmente llamado derrame cerebral, es una emergencia médica crítica. Ocurre cuando se interrumpe el flujo de sangre a una parte del cerebro, privando a las células cerebrales del oxígeno y los nutrientes necesarios, provocando su muerte en minutos.", whatIs: { title: "¿Qué es un Accidente cerebrovascular?", text: "Es una lesión neurológica repentina causada por el bloqueo de una arteria cerebral (falta de riego sanguíneo) o por la ruptura de un vaso sanguíneo en el cerebro (hemorragia). Cada segundo sin tratamiento resulta en la pérdida de millones de neuronas." }, symptoms: { title: "Síntomas de Alerta Inmediata (F.A.S.T.)", intro: "Los síntomas aparecen de forma repentina. Es vital recordar la regla mnemotécnica FAST (en inglés) o buscar:", groups: [ { name: "Signos principales (Emergencia)", items: ["Asimetría facial: Caída o parálisis repentina de un lado del rostro, o sonrisa torcida", "Debilidad en los brazos: Incapacidad repentina para levantar ambos brazos a la misma altura o entumecimiento en un lado", "Dificultad para hablar: Habla arrastrada, confusa, o incapacidad total para hablar o entender lo que se le dice"] }, { name: "Otros síntomas repentinos", items: ["Pérdida de visión repentina, visión borrosa o doble en uno o ambos ojos", "Dificultad brusca para caminar, pérdida de equilibrio o coordinación, o mareos severos", "Dolor de cabeza severo, súbito y sin causa conocida (frecuente en ACV hemorrágico)"] } ], warning: "El tiempo es cerebro. No espere a ver si los síntomas mejoran. Llame a una ambulancia inmediatamente." }, types: { title: "Tipos de ACV", intro: "Se clasifican según el mecanismo que interrumpe el flujo sanguíneo:", items: ["ACV Isquémico (87% de los casos): Causado por un coágulo de sangre que bloquea una arteria que va al cerebro.", "ACV Hemorrágico (13% de los casos): Causado por la ruptura y sangrado de un vaso sanguíneo debilitado (aneurisma) dentro del cerebro.", "Ataque Isquémico Transitorio (AIT o 'mini derrame'): Una interrupción temporal del flujo sanguíneo; los síntomas duran minutos u horas, pero es un preaviso grave de un futuro ACV mayor."], note: "El tratamiento es diametralmente opuesto según el tipo, por lo que el diagnóstico por imagen rápido es vital." }, causes: { title: "Causas y Factores de Riesgo", intro: "Ciertas condiciones aumentan drásticamente el riesgo de sufrir un ACV:", items: ["Presión arterial alta (el factor de riesgo controlable más importante)", "Fibrilación auricular (latidos cardíacos irregulares que pueden formar coágulos)", "Tabaquismo y exposición al humo de segunda mano", "Colesterol alto, diabetes no controlada y obesidad", "Antecedentes familiares de ACV o enfermedad cardiovascular", "Edad (el riesgo aumenta significativamente a partir de los 55 años)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Al llegar a urgencias, el equipo médico actuará con extrema rapidez realizando:", items: ["Tomografía computarizada (TC) cerebral sin contraste (prueba inmediata para ver si hay sangrado y descartar el ACV hemorrágico)", "Resonancia magnética (RM) del cerebro (para detectar daños tempranos en el tejido cerebral)", "Angiografía por TC o RM (para localizar con precisión la arteria bloqueada o el aneurisma roto)", "Examen neurológico clínico y escala de ACV del NIH", "Análisis de sangre, ecocardiograma y ultrasonido de carótidas para encontrar el origen del problema"], note: "El objetivo es confirmar si es isquémico o hemorrágico en los primeros minutos de llegada al hospital." }, treatment: { title: "Intervenciones de Emergencia y Rehabilitación", intro: "El tratamiento inmediato depende exclusivamente del tipo de ACV:", subsections: [ { title: "Isquémico vs. Hemorrágico", items: ["Para Isquémicos: Administración intravenosa de medicamentos trombolíticos (TPA o Alteplasa) para disolver el coágulo, administrado idealmente dentro de las primeras 3 a 4.5 horas del inicio de los síntomas", "Trombectomía mecánica (cateterismo para extraer físicamente el coágulo del cerebro en arterias grandes)", "Para Hemorrágicos: Control agresivo de la presión arterial, reversión de anticoagulantes y, en ocasiones, cirugía para aliviar la presión del cerebro o reparar el aneurisma (clipaje o embolización)", "Rehabilitación: Fisioterapia, terapia ocupacional y terapia del habla son fundamentales para recuperar habilidades perdidas y adaptar el cerebro (neuroplasticidad)"] } ], note: "La prevención secundaria con medicamentos (anticoagulantes, estatinas, antihipertensivos) es obligatoria tras el alta." }, whenToSeekHelp: { title: "¿Cuándo Llamar a Urgencias?", intro: "Actúe inmediatamente frente a CUALQUIER síntoma de alerta:", items: ["Anote la hora exacta en la que la persona fue vista normal por última vez y llame al servicio de emergencias (911/112)", "NO deje que la persona conduzca", "NO le dé a la persona comida, bebida o aspirina (si resulta ser un sangrado, la aspirina lo empeorará)", "Acuda al hospital más cercano con unidad especializada en accidentes cerebrovasculares si es posible"] } },
'Úlcera gastroduodenal aguda' : { intro: "Una úlcera gastroduodenal es una llaga abierta y dolorosa que se desarrolla en el revestimiento interno del estómago o en la primera parte del intestino delgado (duodeno). Es una afección común del sistema digestivo que causa un dolor ardiente característico.", whatIs: { title: "¿Qué es una Úlcera Peptica/Gastroduodenal?", text: "Es una lesión erosiva en la mucosa del tracto gastrointestinal. Ocurre cuando los ácidos gástricos que ayudan a digerir los alimentos dañan las paredes del estómago o el duodeno, sobrepasando las barreras de moco protectoras de estos órganos." }, symptoms: { title: "Síntomas y Molestias Digestivas", intro: "El síntoma clásico es el dolor de estómago recurrente:", groups: [ { name: "Síntomas habituales", items: ["Dolor ardiente o punzante en la parte superior del abdomen (epigastrio) o en medio del pecho", "El dolor a menudo ocurre con el estómago vacío, entre comidas o por la noche", "Alivio temporal del dolor al comer ciertos alimentos que neutralizan el ácido o tomar antiácidos", "Sensación de plenitud rápida al comer, hinchazón o eructos frecuentes"] }, { name: "Signos de complicaciones graves", items: ["Vómitos (que pueden contener sangre roja o parecer granos de café oscuros)", "Heces oscuras, negras y alquitranadas o con sangre visible (melena)", "Pérdida de peso inexplicable y pérdida severa del apetito", "Dolor abdominal repentino, severo e insoportable (posible perforación de la úlcera)"] } ], warning: "Vomitar sangre o tener heces negras como el alquitrán indica una hemorragia digestiva interna, requiriendo atención en la sala de emergencias." }, types: { title: "Ubicaciones Principales", intro: "Se clasifican según la parte del tracto digestivo donde se formen:", items: ["Úlcera gástrica: Localizada en el revestimiento interno del propio estómago.", "Úlcera duodenal: Localizada en el interior del duodeno, la primera parte del intestino delgado. Es el tipo más común.", "Úlcera esofágica: Menos frecuente, ubicada en la parte inferior del esófago (a menudo asociada con reflujo ácido severo)."], note: "Las úlceras duodenales suelen doler horas después de comer y mejorar con la ingesta, mientras que las gástricas pueden doler poco después de comer." }, causes: { title: "Causas y Desencadenantes Principales", intro: "Contrario a la creencia popular, el estrés y la comida picante no causan úlceras. Se deben principalmente a:", items: ["Infección por la bacteria Helicobacter pylori (H. pylori), la causa más común que debilita el revestimiento protector de moco", "Uso regular, prolongado o en dosis altas de analgésicos AINEs (como aspirina, ibuprofeno, naproxeno o diclofenaco)", "Fumar cigarrillos, que retrasa la curación y aumenta el riesgo", "Consumo excesivo de alcohol, que irrita y erosiona el revestimiento del estómago", "Uso concurrente de esteroides o anticoagulantes junto con los AINEs aumenta el riesgo significativamente"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El gastroenterólogo confirmará el diagnóstico y buscará la bacteria H. pylori mediante:", items: ["Endoscopia superior (EGD): El estándar de oro. Se introduce un tubo flexible con cámara por la garganta para examinar el estómago y duodeno directamente", "Biopsia: Toma de pequeñas muestras de tejido durante la endoscopia para examinarlas en el laboratorio", "Pruebas no invasivas para H. pylori: Prueba de aliento con urea (muy precisa), análisis de heces o análisis de sangre", "Tránsito de la parte superior del tracto digestivo (Rayos X con ingesta de bario), utilizado con menos frecuencia hoy en día"], note: "Si se encuentra una úlcera gástrica, siempre se debe hacer una biopsia para descartar cáncer de estómago." }, treatment: { title: "Tratamientos y Cura", intro: "El tratamiento se enfoca en sanar la llaga y eliminar la causa subyacente:", subsections: [ { title: "Régimen médico farmacológico", items: ["Antibióticos (una combinación de dos o más durante 14 días) si se detecta la bacteria H. pylori, para erradicar la infección por completo", "Inhibidores de la bomba de protones (IBP, como omeprazol, pantoprazol) para reducir drásticamente la producción de ácido estomacal y permitir la curación", "Bloqueadores de los receptores H2 o antiácidos para un alivio más rápido de los síntomas", "Protectores de la mucosa estomacal (como el sucralfato o misoprostol)", "Suspensión inmediata de medicamentos AINEs si fueron la causa de la úlcera", "Cirugía endoscópica (solo si la úlcera sangra activamente, se aplica calor o grapas para detener el sangrado)"] } ], note: "Completar todo el ciclo de antibióticos es vital para evitar la recurrencia de la bacteria H. pylori." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias?", intro: "Busque atención médica inmediata si experimenta cualquiera de los siguientes síntomas de alarma:", items: ["Vomita un material oscuro que parece posos de café, o sangre roja brillante", "Nota que sus heces son pegajosas, de color negro alquitrán, o tienen sangre visible", "Sufre un dolor abdominal de aparición repentina, agudo y punzante que no cede", "Experimenta mareos severos, confusión, desmayos o dificultad para respirar (signos de pérdida masiva de sangre)"] } },
'Rodilla vara' : { intro: "La rodilla vara (Genu varum) es una condición ortopédica en la que las piernas se curvan hacia afuera a la altura de las rodillas, dando la apariencia de 'piernas arqueadas'. Es una parte normal del desarrollo en bebés, pero puede requerir tratamiento si persiste o es asimétrica en niños mayores o adultos.", whatIs: { title: "¿Qué es la Rodilla vara (Piernas arqueadas)?", text: "Es una alineación anormal de los miembros inferiores. Cuando una persona está de pie con los pies y tobillos tocándose, las rodillas permanecen separadas, creando un arco hacia afuera en lugar de una línea recta de la cadera al tobillo." }, symptoms: { title: "Síntomas y Observaciones Físicas", intro: "A menudo es una queja cosmética, pero puede presentar síntomas mecánicos:", groups: [ { name: "En bebés y niños pequeños (Fisiológica)", items: ["Curvatura visible y simétrica de ambas piernas hacia afuera", "Caminar con los pies girados hacia adentro (marcha de paloma) y cierta torpeza al empezar a caminar", "No hay dolor asociado"] }, { name: "En adolescentes y adultos (Patológica)", items: ["Molestias, dolor o tensión en las caderas, rodillas y/o tobillos", "Cojera persistente o dificultad para correr y participar en deportes", "Diferencia de longitud en las piernas (si el arqueamiento es asimétrico)", "Desgaste asimétrico de la suela de los zapatos"] } ], warning: "Un arqueamiento severo, empeoramiento progresivo después de los 3 años de edad, o curvatura en una sola pierna son signos de un problema médico subyacente." }, types: { title: "Tipos de Arqueamiento", intro: "Se clasifica según su causa y si es parte del desarrollo normal:", items: ["Genu varum fisiológico: Es normal en niños menores de 2 años, causado por la posición fetal en el útero, y se corrige solo.", "Enfermedad de Blount: Un trastorno de crecimiento del hueso de la espinilla (tibia) que hace que la pierna se arquee severamente. Puede ocurrir en niños pequeños o adolescentes.", "Raquitismo: Arqueamiento provocado por huesos blandos y débiles debido a deficiencia severa de vitamina D o problemas renales.", "Osteoartritis severa: En adultos mayores, el desgaste del cartílago en la parte interna de la rodilla puede arquear progresivamente la pierna."], note: "El arqueamiento normal suele alcanzar su punto máximo a los 18 meses y desaparecer hacia los 3 años." }, causes: { title: "Causas y Factores Relacionados", intro: "Dependiendo de la edad, las piernas arqueadas pueden ser causadas por:", items: ["Desarrollo fisiológico normal en la primera infancia", "Enfermedad de Blount (a menudo asociada con sobrepeso u obesidad en la infancia y caminar a una edad muy temprana)", "Mala nutrición extrema (Raquitismo por falta prolongada de vitamina D o calcio)", "Enfermedad de Paget del hueso (condición metabólica en adultos)", "Traumatismos o fracturas previas en la rodilla o tibia que sanaron incorrectamente (malunión)", "Acondroplasia (la forma más común de enanismo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El ortopedista infantil o de adultos evalúa la condición mediante:", items: ["Examen físico observando al paciente estar de pie y caminar para ver su patrón de marcha (evaluando asimetría o torción)", "Medición de la distancia entre las rodillas cuando el paciente está acostado", "Radiografías de miembros inferiores (telerradiografías desde la cadera al tobillo) para medir los ejes mecánicos y evaluar las placas de crecimiento", "Análisis de sangre para evaluar los niveles de vitamina D, calcio o buscar problemas genéticos en casos sospechosos de raquitismo"], note: "El médico observará cuidadosamente si la placa de crecimiento en la tibia muestra anomalías características de la Enfermedad de Blount." }, treatment: { title: "Manejo Ortopédico", intro: "El tratamiento depende directamente de la causa subyacente y la edad:", subsections: [ { title: "Opciones terapéuticas", items: ["Observación ('espera vigilante') para niños pequeños con genu varum fisiológico, ya que el 99% se corrige espontáneamente", "Suplementos de vitamina D y calcio de alta dosis si la causa es el raquitismo nutricional", "Uso de aparatos ortopédicos especiales (ortesis rodilla-tobillo-pie modificadas) en la enfermedad de Blount en etapas tempranas en niños muy pequeños", "Cirugía ortopédica (osteotomía, donde se corta y realinea el hueso, o crecimiento guiado insertando pequeñas placas en la placa de crecimiento) para adolescentes o casos graves que causan dolor o daño en la articulación", "Reemplazo de rodilla en adultos mayores si la deformidad es causada por artritis avanzada"] } ], note: "La fisioterapia o zapatos especiales no corrigen la alineación ósea de las piernas arqueadas." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Ortopedista?", intro: "Solicite una evaluación médica para su hijo si:", items: ["El arqueamiento de las piernas es asimétrico (una pierna es recta y la otra arqueada)", "La curvatura de las piernas es muy pronunciada o está empeorando en lugar de mejorar", "El niño tiene más de 3 años y todavía tiene las piernas significativamente arqueadas", "Siente dolor persistente en las rodillas o cojea visiblemente al caminar", "El niño es de estatura excepcionalmente baja para su edad"] } },
'Dependencia del alcohol' : { intro: "La dependencia del alcohol, también conocida como alcoholismo grave o adicción física al alcohol, es la forma más severa del trastorno por consumo de alcohol. Es una enfermedad del cerebro crónica y recurrente donde el cuerpo exige el alcohol para funcionar normalmente, generando graves síntomas físicos al dejarlo.", whatIs: { title: "¿Qué es la Dependencia del alcohol?", text: "Es una afección médica en la cual la química del cerebro se ha alterado por el consumo crónico y excesivo de alcohol. Esto provoca una compulsión física y psicológica incontrolable por beber, pérdida total del control sobre la cantidad consumida y la aparición de un doloroso síndrome de abstinencia si el consumo cesa abruptamente." }, symptoms: { title: "Síntomas y Señales de Adicción", intro: "Se distingue por la alteración de la tolerancia y la reacción física al detenerse:", groups: [ { name: "Síntomas físicos (Abstinencia y Tolerancia)", items: ["Fuerte tolerancia: Necesidad de beber cantidades cada vez mayores de alcohol para sentir embriaguez o su efecto habitual", "Temblores matutinos incontrolables en las manos (que se calman bebiendo alcohol)", "Sudoración profusa, latidos cardíacos rápidos, náuseas o vómitos al pasar horas sin beber", "Consumir alcohol a primera hora de la mañana para evitar los síntomas de abstinencia"] }, { name: "Síntomas psicológicos y conductuales", items: ["Obsesión y planificación constante sobre cómo y cuándo conseguir la próxima bebida", "Intentos repetidos y fallidos de reducir el consumo o dejar de beber de forma independiente", "Abandono de actividades sociales, pasatiempos o responsabilidades laborales a favor de beber", "Beber en secreto, esconder botellas o mentir sobre la cantidad que se consume"] } ], warning: "Dejar de beber repentinamente sin supervisión médica en casos de dependencia severa (el Delirium Tremens) puede causar convulsiones mortales." }, types: { title: "Fases y Complicaciones", intro: "La dependencia es una progresión hacia problemas sistémicos:", items: ["Dependencia fisiológica (presencia de tolerancia física y síndrome de abstinencia evidente).", "Comorbilidad psiquiátrica (con frecuencia coexiste y empeora trastornos de depresión o ansiedad aguda).", "Complicaciones orgánicas terminales (cirrosis hepática irreversible, pancreatitis aguda, miocardiopatía alcohólica y daño neurológico como el síndrome de Wernicke-Korsakoff)."], note: "El alcoholismo afecta absolutamente todos los órganos del cuerpo humano." }, causes: { title: "Causas y Neurobiología", intro: "La dependencia no es un fallo moral, es una enfermedad neurobiológica causada por:", items: ["Cambios en el cerebro: El alcohol sobreestimula los centros de recompensa (dopamina) y deprime el sistema nervioso; con el tiempo, el cerebro deja de producir sus propios químicos calmantes y requiere el alcohol para evitar la ansiedad extrema", "Predisposición genética: Las variaciones genéticas pueden hacer que ciertas personas procesen el alcohol de manera que les genere más placer o menos efectos nocivos iniciales", "Factores ambientales: Trauma infantil, estrés crónico severo y fácil disponibilidad del alcohol desde temprana edad", "Trastornos concurrentes: Las personas suelen automedicarse para la depresión o el trauma no resuelto"] }, diagnosis: { title: "¿Cómo se Diagnostica Médicamente?", intro: "Un psiquiatra o médico especialista en adicciones realizará:", items: ["Evaluación clínica exhaustiva utilizando los criterios de diagnóstico del DSM-5 para el trastorno por consumo de alcohol severo", "Análisis de sangre para identificar daño hepático, enzimas elevadas (GGT, AST, ALT), problemas de coagulación y anemia", "Entrevistas estructuradas sobre patrones y cantidad de consumo, intentos de dejarlo y el impacto en la vida diaria", "Evaluación de la salud mental para identificar patologías duales (depresión, TEPT, trastorno bipolar)"], note: "La negación del paciente es un síntoma cardinal de la enfermedad; a menudo se requiere información colateral de los familiares." }, treatment: { title: "Desintoxicación y Rehabilitación", intro: "El tratamiento de la dependencia física siempre requiere atención médica profesional:", subsections: [ { title: "Fases del tratamiento", items: ["Desintoxicación médica (el primer paso, supervisado en hospital o clínica ambulatoria): uso de benzodiacepinas para prevenir convulsiones y controlar los peligrosos síntomas de abstinencia de forma segura", "Medicamentos a largo plazo (Naltrexona para bloquear el placer del alcohol, Acamprosato para restaurar la química cerebral, o Disulfiram para causar reacción adversa al beber)", "Terapia individual y grupal continua (TCC, terapia dialéctica conductual, entrevistas motivacionales)", "Programas de internamiento residencial (centros de rehabilitación) de 30 a 90 días para separar al paciente de sus desencadenantes", "Grupos de apoyo mutuo a largo plazo, como Alcohólicos Anónimos (AA), esenciales para prevenir recaídas"] } ], note: "La adicción es una enfermedad crónica; una recaída no significa que el tratamiento haya fracasado, sino que necesita ajustarse." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda o Urgencias?", intro: "Solicite ayuda psiquiátrica o de urgencias si la persona:", items: ["Decide dejar de beber después de meses o años de consumo intenso diario (requiere prevención médica de abstinencia)", "Experimenta alucinaciones severas, confusión profunda, ritmo cardíaco irregular o fiebre (Delirium Tremens) al dejar de beber", "Sufre de temblores intensos, convulsiones o ataques de pánico repentinos por falta de alcohol", "Expresa pensamientos de suicidio, desesperanza extrema o presenta coloración amarillenta en la piel y los ojos (ictericia)"] } },
'Gota aguda' : { intro: "La gota aguda es una forma extremadamente dolorosa y repentina de artritis inflamatoria. Afecta típicamente a una sola articulación (a menudo el dedo gordo del pie), causando un dolor abrasador que puede despertar a una persona de un sueño profundo.", whatIs: { title: "¿Qué es un Ataque de Gota Aguda?", text: "Es una crisis inflamatoria en una articulación provocada por la cristalización y acumulación de ácido úrico. Cuando el cuerpo no procesa o elimina bien el ácido úrico, este forma cristales afilados en forma de aguja dentro de la articulación, desencadenando una respuesta inflamatoria masiva e inmediata del sistema inmunológico." }, symptoms: { title: "Síntomas Clásicos", intro: "Los ataques de gota son repentinos, usualmente ocurriendo durante la noche, e incluyen:", groups: [ { name: "Características del dolor", items: ["Dolor articular súbito, pulsátil, ardiente y de intensidad casi insoportable", "La articulación más frecuentemente afectada es la base del dedo gordo del pie (podagra), aunque puede ocurrir en tobillos, rodillas, muñecas o dedos", "El dolor es más intenso dentro de las primeras 4 a 12 horas desde que comienza"] }, { name: "Signos visibles en la articulación", items: ["Inflamación, hinchazón severa y enrojecimiento brillante alrededor de la articulación", "La zona se siente caliente y es extremadamente sensible al tacto (incluso el roce de la sábana de la cama resulta intolerable)", "Limitación severa del movimiento; incapacidad total para apoyar el peso sobre el pie afectado"] } ], warning: "Si el dolor articular se acompaña de fiebre alta o escalofríos, debe descartarse urgentemente una infección bacteriana (artritis séptica)." }, types: { title: "Etapas de la Enfermedad", intro: "La gota progresa a través de fases si no se manejan los niveles de ácido úrico:", items: ["Hiperuricemia asintomática (niveles altos de ácido úrico en sangre, pero sin ataques ni dolor previo).", "Gota aguda (el ataque de dolor repentino e inflamación que dura desde unos días hasta un par de semanas).", "Gota intercrítica (períodos sin síntomas entre ataques de gota, que pueden ser meses o años).", "Gota tofácea crónica (acumulación avanzada de cristales bajo la piel que forman bultos indoloros llamados 'tofos' y dañan los huesos de forma permanente)."], note: "El daño articular permanente puede evitarse completamente si se inicia la terapia a tiempo." }, causes: { title: "Causas y Desencadenantes", intro: "La cristalización del ácido úrico se ve favorecida por factores genéticos y de estilo de vida:", items: ["Dieta rica en purinas (carnes rojas, vísceras como el hígado, mariscos y algunos pescados ricos en grasa)", "Consumo excesivo de alcohol (especialmente cerveza y licores fuertes)", "Consumo de bebidas azucaradas con alto contenido de jarabe de maíz de alta fructosa", "Enfermedades subyacentes (obesidad mórbida, hipertensión arterial no tratada, diabetes, insuficiencia renal)", "Medicamentos diuréticos (pastillas para el agua) y dosis bajas de aspirina, que dificultan que los riñones eliminen el ácido", "Antecedentes familiares de gota y ser hombre entre 30 y 50 años (las mujeres suelen desarrollarla tras la menopausia)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para confirmar un diagnóstico preciso, el médico puede solicitar:", items: ["Aspiración de líquido articular (Artrocentesis): El estándar de oro; el médico usa una aguja para extraer líquido de la articulación dolorida y busca cristales de ácido úrico bajo el microscopio", "Análisis de sangre para medir los niveles de ácido úrico (aunque pueden ser engañosamente normales durante un ataque agudo)", "Ecografía musculoesquelética (puede detectar rápidamente cristales de urato incrustados en el cartílago, signo del 'doble contorno')", "Radiografías (generalmente inútiles en ataques agudos iniciales, pero se usan para buscar daños crónicos en las articulaciones)"], note: "Es vital extraer líquido para diferenciar definitivamente la gota de la artritis infecciosa o la pseudogota." }, treatment: { title: "Tratamiento de la Crisis y Prevención", intro: "El tratamiento se divide en detener el ataque agudo y prevenir futuros episodios a largo plazo:", subsections: [ { title: "Medicamentos durante un ataque agudo", items: ["Antiinflamatorios no esteroideos (AINEs) a dosis altas (como indometacina o naproxeno), recetados lo antes posible", "Colchicina (un analgésico específico y antiguo para la gota, muy efectivo si se toma en las primeras 24 horas del ataque)", "Corticosteroides (prednisona oral o inyección directa en la articulación) si el paciente no tolera los AINEs", "Nota vital: NO se deben iniciar ni detener medicamentos que disminuyen el ácido úrico (como alopurinol) en medio de un ataque agudo, ya que empeorarán el dolor"] }, { title: "Prevención a largo plazo", items: ["Modificación del estilo de vida (pérdida de peso, dieta baja en purinas, evitar la cerveza y reducir la fructosa)", "Medicamentos reductores de urato (Alopurinol o Febuxostat) para tomar diariamente de por vida una vez resuelto el ataque agudo", "Medicamentos uricosúricos (Probenecid) para ayudar a los riñones a eliminar más ácido úrico"] } ], note: "El ataque agudo suele resolverse completamente en 7 a 14 días incluso sin tratamiento, pero la inflamación daña silenciosamente la articulación." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Médico de Urgencia?", intro: "Solicite atención médica prioritaria si experimenta:", items: ["Un dolor articular repentino e insoportable por primera vez, especialmente en el pie o el tobillo", "La articulación inflamada se siente anormalmente caliente y está acompañada de fiebre alta o escalofríos severos (sospecha de infección articular grave)", "El enrojecimiento se extiende rápidamente hacia arriba por la pierna o el brazo (sospecha de celulitis)", "Los medicamentos recetados para la gota no están disminuyendo el dolor después de 48 horas"] } },
'Absceso del ano y el recto' : { intro: "Un absceso anorrectal es una afección muy dolorosa y aguda causada por una acumulación de pus localizada cerca del ano o en el área profunda del recto. A menudo es el resultado de la infección de una pequeña glándula anal y requiere drenaje quirúrgico oportuno.", whatIs: { title: "¿Qué es un Absceso anorrectal?", text: "Es una cavidad infectada llena de pus (bacterias, tejido muerto y glóbulos blancos) que se forma bajo la piel cerca del ano o en los tejidos profundos que rodean el recto. Es una infección bacteriana aguda que no responde únicamente a los antibióticos." }, symptoms: { title: "Síntomas y Malestares", intro: "El absceso provoca un malestar intenso y progresivo, que incluye:", groups: [ { name: "Síntomas locales", items: ["Dolor perianal constante, punzante y agudo, que empeora bruscamente al sentarse, toser o intentar defecar", "Aparición de un bulto hinchado, rojo, caliente y extremadamente sensible al tacto en el borde del ano", "Secreción de pus o sangre por el ano si el absceso comienza a abrirse por sí solo"] }, { name: "Síntomas sistémicos de infección", items: ["Fiebre, escalofríos intensos y sudoración", "Malestar general, fatiga y dolores corporales (semejantes a una gripe severa)", "Estreñimiento o dolor profundo dentro del abdomen y la pelvis baja (frecuente en abscesos rectales profundos)"] } ], warning: "Si la infección se propaga (especialmente en pacientes diabéticos o inmunodeprimidos), puede causar gangrena de Fournier o sepsis, infecciones masivas y mortales." }, types: { title: "Clasificación Anatómica", intro: "Los abscesos se clasifican según su ubicación y profundidad:", items: ["Absceso perianal: El tipo más común (superficial); se ve y se siente justo debajo de la piel en el borde anal.", "Absceso isquiorrectal: Se forma en el espacio profundo de grasa y tejido a los lados del recto. Más grande y difícil de localizar externamente.", "Absceso interesfinteriano y supraelevador: Infecciones complejas muy profundas entre o por encima de los músculos del esfínter anal. Requieren cirugía mayor en quirófano."], note: "La mitad de los abscesos anales desarrollan una fístula anal (un túnel anormal desde la glándula infectada hasta la piel) después de sanar." }, causes: { title: "Causas y Factores de Riesgo", intro: "La infección suele originarse por el bloqueo de una cripta o glándula anal:", items: ["Infección aguda de las glándulas anales que normalmente lubrican el canal anal (causa principal)", "Enfermedades inflamatorias intestinales (especialmente la Enfermedad de Crohn)", "Fisuras anales (desgarros en la piel del ano) que se infectan por contacto con las heces", "Infecciones de transmisión sexual (ITS) en el área anorrectal", "Diabetes o sistemas inmunológicos debilitados (VIH, pacientes en quimioterapia) que reducen la defensa contra bacterias"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un cirujano general, proctólogo o médico de urgencias lo diagnostica mediante:", items: ["Examen físico y visual del área anal y tacto rectal cuidadoso (para abscesos perianales y superficiales)", "Tomografía computarizada (TC) de la pelvis o Resonancia Magnética (RM) (fundamentales si el médico sospecha que el absceso es profundo o no se puede palpar fácilmente)", "Ecografía endoanal (ultrasonido intrarectal) para evaluar abscesos complejos o sospecha de fístulas"], note: "El examen físico suele ser tan doloroso que a veces solo se puede realizar bajo anestesia en el quirófano." }, treatment: { title: "Drenaje Quirúrgico", intro: "Los antibióticos NO curan un absceso por sí solos. El pus debe ser evacuado:", subsections: [ { title: "Procedimientos médicos", items: ["Incisión y drenaje (I&D) de emergencia: El médico realiza un corte sobre el absceso para permitir que salga el pus, la sangre y aliviar la presión instantáneamente", "Anestesia local en el consultorio (para abscesos perianales simples y pequeños)", "Drenaje quirúrgico bajo anestesia general en el quirófano (para abscesos grandes, profundos, o en pacientes diabéticos)", "Uso de antibióticos después del drenaje (solo recomendados para pacientes inmunodeprimidos, diabéticos, con infecciones extensas o si hay signos de celulitis)", "Cirugía posterior para tratar una fístula anal, que se desarrolla en el 50% de los pacientes semanas o meses después"] } ], note: "El alivio del dolor es dramático e casi inmediato después de que el cirujano drena el absceso." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias de Inmediato?", intro: "El absceso anal es una urgencia quirúrgica. Busque ayuda médica de inmediato si:", items: ["Tiene un dolor severo o un bulto rojo palpitante cerca del ano y desarrolla fiebre o escalofríos", "Nota una secreción maloliente repentina, pus espeso o sangrado significativo en la zona anal", "No puede orinar, no puede defecar debido al dolor paralizante, o tiene dolor profundo en la pelvis baja", "Es diabético o está bajo tratamiento inmunosupresor y nota dolor o enrojecimiento anal"] } },
'Enfermedades y dolor crónico' : { intro: "El dolor crónico no es solo un síntoma, a menudo es reconocido como una enfermedad compleja en sí misma. Es un dolor persistente que dura meses o años, superando el tiempo normal de curación de los tejidos, impactando devastadoramente la movilidad, el estado de ánimo y la calidad de vida.", whatIs: { title: "¿Qué es el Dolor crónico?", text: "Es un dolor que persiste durante 3 a 6 meses o más. A diferencia del dolor agudo (que es una alarma útil de que el cuerpo está herido), en el dolor crónico el sistema nervioso sigue enviando señales de dolor meses o años después de la lesión original, o sin que exista una lesión física clara." }, symptoms: { title: "Síntomas Físicos y Emocionales", intro: "El dolor crónico es un trastorno de cuerpo y mente que presenta:", groups: [ { name: "Naturaleza del dolor", items: ["Sensación de ardor, punzadas, descarga eléctrica o dolor sordo constante en articulaciones, músculos o espalda", "Hipersensibilidad extrema: dolor provocado por roces o estímulos que normalmente no deberían doler (alodinia)", "Rigidez matutina persistente y fatiga física extrema a pesar de descansar"] }, { name: "Consecuencias de salud mental y sistémicas", items: ["Alteraciones severas del sueño y fatiga crónica insuperable", "Desarrollo de problemas de salud mental como depresión clínica, ansiedad severa o irritabilidad constante", "Niebla mental, problemas de memoria y dificultad de concentración", "Aislamiento social y pérdida de capacidad laboral"] } ], warning: "La combinación de dolor intratable e insomnio crónico aumenta peligrosamente el riesgo de depresión severa e ideación suicida." }, types: { title: "Categorías de Dolor Crónico", intro: "Se agrupa en diferentes tipos, lo que dicta su tratamiento:", items: ["Dolor nociceptivo crónico (por daño continuo en los tejidos o articulaciones, como la osteoartritis severa).", "Dolor neuropático crónico (por daño a los nervios o sistema nervioso, como la neuropatía diabética, ciática o neuralgia del trigémino).", "Dolor nociplástico / Síndromes de dolor central (el sistema nervioso se vuelve hipersensible sin daño tisular obvio, como la Fibromialgia o el Síndrome del Intestino Irritable).", "Dolor oncológico (dolor crónico debido al cáncer avanzado o los tratamientos contra él)."], note: "Es muy común que los pacientes sufran de dolor mixto (por ejemplo, dolor de espalda estructural más daño nervioso)." }, causes: { title: "Causas y Orígenes Comunes", intro: "El dolor crónico puede comenzar tras una lesión que sanó mal o por afecciones continuas:", items: ["Condiciones inflamatorias articulares y autoinmunes (Artritis reumatoide, lupus)", "Problemas estructurales o degenerativos de la columna vertebral (hernias de disco, estenosis espinal)", "Lesiones nerviosas traumáticas, amputaciones (dolor del miembro fantasma) o daño nervioso por diabetes", "Síndromes de dolor primario (Endometriosis, Fibromialgia, Migrañas crónicas, Cistitis intersticial)", "A veces, el dolor persiste después de una cirugía exitosa (dolor crónico postoperatorio) debido a la sensibilización central del cerebro"] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "Es un proceso complejo porque el dolor es subjetivo. Especialistas en manejo del dolor usan:", items: ["Historial médico exhaustivo, evaluaciones de escalas de dolor y uso de diarios de dolor", "Exámenes neurológicos para evaluar daños en los nervios, reflejos y pérdida de sensibilidad", "Estudios de imagen (RM, TC) para identificar causas nociceptivas, aunque a menudo no muestran correlación con el nivel de dolor reportado (especialmente en fibromialgia)", "Evaluaciones psicológicas exhaustivas para medir el impacto de la depresión, el estrés y la ansiedad en la percepción del dolor"], note: "Si las pruebas médicas no muestran una lesión física, no significa que el dolor sea 'imaginario'; el sistema nervioso de la persona está enfermo." }, treatment: { title: "Enfoque Multidisciplinario del Manejo", intro: "El dolor crónico rara vez se cura por completo; el objetivo es recuperar la funcionalidad y la calidad de vida:", subsections: [ { title: "Terapias combinadas (Clínicas de Dolor)", items: ["Medicamentos neuromoduladores: Antidepresivos (duloxetina, amitriptilina) y anticonvulsivos (gabapentina, pregabalina) que calman los nervios sobreexcitados", "Intervenciones procedimentales: Inyecciones de puntos gatillo, bloqueos nerviosos, ablación por radiofrecuencia (quemar el nervio doloroso)", "Dispositivos médicos implantados: Estimuladores de la médula espinal o bombas intratecales de medicamentos", "Rehabilitación física: Fisioterapia especializada, ejercicios aeróbicos acuáticos de bajo impacto y reacondicionamiento gradual", "Terapia psicológica: Terapia cognitivo-conductual (TCC) o Terapia de Aceptación y Compromiso (ACT) para reentrenar el cerebro y cambiar la reacción emocional ante el dolor", "Uso cuidadoso y altamente monitoreado de analgésicos convencionales, minimizando el uso de opiáceos fuertes debido al alto riesgo de adicción y tolerancia"] } ], note: "Las clínicas especializadas en el manejo del dolor ofrecen los mejores resultados al tratar el aspecto biológico, psicológico y social simultáneamente." }, whenToSeekHelp: { title: "¿Cuándo Derivar a un Especialista?", intro: "Debe solicitar la derivación a una clínica de manejo del dolor si:", items: ["Ha experimentado un dolor continuo casi todos los días durante más de 3 a 6 meses", "El dolor lo ha obligado a dejar de trabajar, dejar sus pasatiempos o evitar interactuar con su familia", "Su estado de ánimo es consistentemente bajo, sufre ataques de ansiedad o llora de desesperación a causa del dolor", "Está tomando dosis crecientes de analgésicos o múltiples medicamentos pero no logra un alivio significativo"] } },
'Rosácea' : { intro: "La rosácea es una enfermedad inflamatoria crónica de la piel que afecta principalmente el centro del rostro. Produce episodios de enrojecimiento intenso, vasos sanguíneos visibles y pequeñas protuberancias similares al acné, causando a menudo una importante frustración estética y emocional.", whatIs: { title: "¿Qué es la Rosácea?", text: "Es una condición dermatológica prolongada que provoca inflamación en la piel de las mejillas, nariz, barbilla y frente. Aunque a menudo se confunde erróneamente con el acné adolescente, eczema o alergias cutáneas, la rosácea es una patología distinta originada por hiperreactividad vascular." }, symptoms: { title: "Síntomas y Apariencia", intro: "Los síntomas tienden a aparecer en brotes intermitentes e incluyen:", groups: [ { name: "Síntomas clásicos en la piel del rostro", items: ["Enrojecimiento facial constante, similar a una quemadura de sol que no desaparece o tendencia a ruborizarse con extremada facilidad", "Arañas vasculares (telangiectasias): pequeños vasos sanguíneos rojos e hinchados visibles en la nariz y mejillas", "Aparición de pápulas y pústulas (protuberancias rojas o granos con pus) que se asemejan al acné de los adultos, pero sin presencia de puntos negros (comedones)", "Sensación de ardor, escozor, piel sensible, caliente y extremadamente seca"] }, { name: "Síntomas oculares y estructurales avanzados", items: ["Ojos inyectados en sangre, llorosos, secos o con sensación de tener arenilla (rosácea ocular); párpados hinchados", "Engrosamiento irregular de la piel de la nariz, dándole un aspecto bulboso y agrandado (rinofima, más común en hombres)"] } ], warning: "Si no se trata, la rosácea ocular crónica puede causar complicaciones en la córnea y pérdida de visión; requiere evaluación por un oftalmólogo." }, types: { title: "Subtipos de Rosácea", intro: "La rosácea se clasifica en cuatro subtipos principales (muchas personas experimentan más de uno simultáneamente):", items: ["Subtipo 1 (Eritematotelangiectásica): Predominan el rubor agudo, enrojecimiento constante y vasos sanguíneos visibles.", "Subtipo 2 (Papulopustular): Acné de la rosácea, con hinchazón roja y granos llenos de pus.", "Subtipo 3 (Fimatosa): La piel se engrosa y desarrolla una textura irregular, especialmente alrededor de la nariz (rinofima).", "Subtipo 4 (Ocular): Afecta exclusivamente o predominantemente a los ojos y párpados."], note: "La enfermedad puede progresar de un subtipo leve a uno más grave si no se establecen cuidados tempranos." }, causes: { title: "Causas y Desencadenantes", intro: "La causa subyacente exacta es desconocida (posible combinación de genes y reacción exagerada del sistema inmune/vasos sanguíneos), pero los brotes son activados por:", items: ["Exposición a la radiación ultravioleta del sol o ráfagas de viento frío", "Temperaturas extremas (duchas de agua muy caliente, saunas, o climas gélidos)", "Bebidas alcohólicas (especialmente el vino tinto) o bebidas muy calientes como café o té", "Alimentos muy picantes o especiados", "Ejercicio cardiovascular intenso", "Estrés emocional intenso o ansiedad severa", "Uso de cosméticos irritantes, exfoliantes agresivos, o medicamentos que dilatan los vasos sanguíneos", "Posible sobrepoblación en la piel de un ácaro microscópico normal llamado Demodex folliculorum"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existen análisis de sangre ni pruebas médicas definitivas. El dermatólogo basa el diagnóstico en:", items: ["Examen visual detallado de la piel del rostro y de la zona de los ojos", "Historial clínico exhaustivo sobre el patrón de los episodios de enrojecimiento y los factores desencadenantes específicos del paciente", "Diferenciación médica para descartar activamente condiciones similares (Lupus eritematoso sistémico, dermatitis seborreica, dermatitis de contacto o acné vulgar)"], note: "Llevar un diario detallado de comidas y actividades ayuda enormemente al dermatólogo a identificar qué detona los brotes en cada paciente." }, treatment: { title: "Tratamiento Dermatológico y Control", intro: "La rosácea no tiene cura definitiva, pero el tratamiento temprano y constante logra controlar excelentemente los síntomas:", subsections: [ { title: "Estrategias combinadas", items: ["Terapias tópicas recetadas: Geles o cremas antiinflamatorias y antiparasitarias (como ivermectina, ácido azelaico, metronidazol o brimonidina para constreñir los vasos sanguíneos rojos)", "Antibióticos orales (como la doxiciclina en dosis bajas antiinflamatorias) para los brotes graves con pústulas e inflamación ocular", "Terapias con láser y luz pulsada intensa (IPL) (extremadamente efectivas para destruir selectivamente los vasos sanguíneos visibles y reducir el enrojecimiento base de forma permanente)", "Cirugía dermatológica con láser o bisturí eléctrico (para remodelar el exceso de tejido nasal en casos de rinofima avanzado)", "Rutina estricta de cuidado de la piel: Uso diario e innegociable de protector solar mineral (óxido de zinc), limpiadores faciales ultra suaves sin fragancias y humectantes restauradores de barrera", "Lágrimas artificiales y limpieza estricta de los bordes de los párpados para el manejo del subtipo ocular"] } ], note: "Las cremas con corticosteroides (cortisona) deben evitarse por completo, ya que empeorarán drásticamente los síntomas a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Dermatólogo u Oftalmólogo?", intro: "Busque consejo médico especializado si:", items: ["Experimenta un enrojecimiento facial prolongado, persistente y molesto que no desaparece", "Sus ojos están constantemente irritados, rojos o se sienten como si tuvieran arena adentro", "Nota que la piel de su nariz se está volviendo más gruesa, áspera o abultada", "Los productos cosméticos y de farmacia habituales para el acné solo empeoran y queman más su rostro"] } },
'Pie equino varo' : { intro: "El pie equino varo (también conocido como pie zambo o talipes equinovarus) es una deformidad musculoesquelética congénita compleja del pie y tobillo. Aunque su apariencia al nacer puede ser alarmante, con el tratamiento temprano adecuado, casi todos los niños logran caminar, correr y llevar una vida perfectamente normal.", whatIs: { title: "¿Qué es el Pie equino varo?", text: "Es una anomalía congénita (presente al nacer) donde los tendones que conectan el músculo de la pierna al pie son demasiado cortos y rígidos. Como resultado, el pie del bebé está torcido hacia adentro y apuntando drásticamente hacia abajo, haciendo que la planta del pie mire hacia el lado o incluso hacia arriba." }, symptoms: { title: "Apariencia y Señales Clínicas", intro: "La deformidad es visualmente obvia desde el nacimiento o en las ecografías prenatales:", groups: [ { name: "Características estructurales del pie", items: ["El pie apunta fuertemente hacia abajo (posición equina)", "La mitad delantera del pie se tuerce hacia adentro (aducto)", "El talón y el pie se giran hacia adentro (posición en varo)", "El pie puede parecer estar completamente al revés en casos severos", "A menudo, el pie afectado es ligeramente más pequeño y el músculo de la pantorrilla de esa pierna es visiblemente más delgado (atrofia muscular) que la pierna sana"] } ], warning: "Si no se trata agresivamente desde las primeras semanas de vida, el niño eventualmente intentará caminar sobre los bordes externos y superiores del pie, causando callos dolorosos e incapacidad severa." }, types: { title: "Clasificación de la Afección", intro: "Puede presentarse en diversas formas según su severidad o causa subyacente:", items: ["Pie zambo idiopático (aislado): El tipo más común; ocurre en un bebé por lo demás completamente sano. Puede afectar un pie o ambos (bilateral, en la mitad de los casos).", "Pie zambo sindrómico: Asociado con otros problemas neuromusculares subyacentes presentes al nacer, como espina bífida (mielomeningocele) o artrogriposis.", "Pie zambo posicional: El pie está doblado por estar apretado en el útero, pero es totalmente flexible (a diferencia del verdadero pie zambo, que es rígido). Se resuelve fácilmente con estiramientos."], note: "El tratamiento de los casos sindrómicos suele ser más largo, más propenso a recaídas y a veces requiere abordajes quirúrgicos más extensos." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta del pie zambo idiopático (aislado) no se conoce completamente, pero se cree que intervienen:", items: ["Factores genéticos fuertes (si uno de los padres o un hermano mayor tuvo la condición, las probabilidades de que el bebé la tenga son drásticamente mayores)", "Desarrollo embrionario anormal de los tendones y músculos en las semanas iniciales del embarazo", "Factores ambientales maternos: Se ha demostrado que fumar cigarrillos durante el embarazo aumenta significativamente el riesgo, especialmente si hay antecedentes genéticos familiares", "Infecciones prenatales tempranas o falta de líquido amniótico (oligohidramnios)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico es muy directo, basado en la forma y rigidez del pie:", items: ["Ecografía prenatal rutinaria (frecuentemente es posible detectarlo en el ultrasonido alrededor de la semana 20 de gestación, permitiendo a los padres asesorarse tempranamente)", "Examen físico inmediato después del parto, donde el pediatra intentará mover el pie y notará la rigidez que impide llevarlo a una posición normal", "Radiografías u otras pruebas de imagen (generalmente no son necesarias para confirmar el diagnóstico, pero el ortopedista puede pedirlas más adelante para evaluar la anatomía ósea interna y la progresión del tratamiento)"], note: "El diagnóstico prenatal no permite tratar al bebé en el útero, pero es valioso para preparar la logística del tratamiento postnatal inmediato." }, treatment: { title: "El Método Ponseti", intro: "El tratamiento estándar de oro a nivel mundial, altamente exitoso y poco invasivo, debe comenzar idealmente entre la semana 1 y 2 de vida:", subsections: [ { title: "Fases del tratamiento (Método Ponseti)", items: ["Fase de enyesado secuencial: El médico ortopedista estira muy suavemente el pie del bebé hacia la posición correcta y coloca un yeso desde los dedos hasta la ingle. Esto se hace semanalmente, usando de 5 a 7 yesos consecutivos para corregir gradualmente la rotación y la torsión hacia adentro.", "Fase de tenotomía (Cirugía menor): Casi el 80-90% de los bebés necesitarán una pequeña cirugía antes del último yeso para cortar y liberar el tendón de Aquiles (que está demasiado tenso). Esto se hace a menudo con anestesia local; el tendón sana rápidamente a una longitud normal en el último yeso.", "Fase de retención con aparatos ortopédicos (La etapa más crítica): Para evitar que el pie vuelva a torcerse, el niño DEBE usar una férula especial (zapatos unidos a una barra rígida de abducción). Al principio, lo usa 23 horas al día durante meses, y luego exclusivamente durante las siestas y las noches hasta los 4 o 5 años de edad.", "Cirugía ortopédica mayor: Reservada solo para casos muy graves, rígidos, síndromicos o si los padres no cumplieron con el riguroso uso del aparato ortopédico y ocurrió una recaída severa."] } ], note: "El fracaso del tratamiento ocurre abrumadoramente cuando los padres no siguen las estrictas instrucciones del uso del aparato ortopédico nocturno." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Ortopedista Infantil?", intro: "El manejo del pie zambo es de manejo altamente especializado:", items: ["Programe una cita con un especialista en ortopedia pediátrica (preferiblemente uno certificado en el Método Ponseti) durante su embarazo si se detectó la deformidad en la ecografía", "Inicie el contacto con el especialista en los primeros días después del nacimiento; retrasar el enyesado disminuye la increíble flexibilidad de los ligamentos del recién nacido", "Acuda al médico de inmediato si su hijo está en la fase de férula nocturna y el pie parece estar empezando a torcerse hacia adentro nuevamente (recaída)"] } },
'Enfermedades renales' : { intro: "Las enfermedades renales afectan la capacidad de los riñones para filtrar los desechos y el exceso de líquidos de la sangre. Cuando la función renal disminuye, pueden acumularse niveles peligrosos de toxinas en el cuerpo, requiriendo atención médica especializada.", whatIs: { title: "¿Qué son las Enfermedades renales?", text: "Son un grupo de afecciones que dañan los riñones y reducen su capacidad para mantener el equilibrio químico del cuerpo, regular la presión arterial y producir hormonas esenciales para la salud de los huesos y la sangre." }, symptoms: { title: "Síntomas Comunes", intro: "En las etapas iniciales suelen ser silenciosas. A medida que avanzan, incluyen:", groups: [ { name: "Signos físicos", items: ["Hinchazón (edema) en piernas, tobillos, pies o alrededor de los ojos", "Fatiga extrema, debilidad y problemas para concentrarse", "Cambios en la frecuencia al orinar (más a menudo por la noche) o sangre en la orina", "Piel seca y picazón persistente"] }, { name: "Síntomas sistémicos", items: ["Presión arterial alta difícil de controlar", "Falta de aliento debido a la acumulación de líquido en los pulmones", "Náuseas, vómitos y pérdida de apetito", "Calambres musculares"] } ], warning: "La aparición de dificultad para respirar severa o hinchazón generalizada repentina es una emergencia médica." }, types: { title: "Tipos de Enfermedad Renal", intro: "Se clasifican según su evolución y causa:", items: ["Enfermedad Renal Crónica (ERC): Pérdida gradual de la función renal durante meses o años.", "Lesión Renal Aguda (LRA): Daño repentino a los riñones, a menudo reversible si se trata rápidamente.", "Cálculos renales (piedras en los riñones)", "Infecciones renales (Pielonefritis)", "Enfermedad poliquística renal (trastorno genético con quistes en los riñones)"], note: "La ERC se clasifica en 5 etapas, siendo la etapa 5 la falla renal que requiere diálisis o trasplante." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las dos causas principales de la enfermedad renal crónica son:", items: ["Diabetes (el nivel alto de azúcar daña los filtros de los riñones)", "Hipertensión arterial (daña los vasos sanguíneos renales)", "Enfermedades autoinmunes como el lupus o la nefropatía por IgA", "Uso prolongado de medicamentos que dañan los riñones (como el ibuprofeno a altas dosis)", "Antecedentes familiares de insuficiencia renal", "Infecciones recurrentes del tracto urinario"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "La evaluación se realiza mediante pruebas sencillas:", items: ["Análisis de sangre para medir la creatinina y calcular la Tasa de Filtración Glomerular (TFG)", "Análisis de orina para detectar la presencia de proteínas (albuminuria) o sangre", "Ecografía renal para evaluar el tamaño y la estructura de los riñones", "Biopsia renal en casos específicos para determinar la causa exacta del daño"], note: "La detección temprana mediante análisis de sangre y orina rutinarios es vital para personas con diabetes o hipertensión." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en ralentizar la progresión y manejar los síntomas:", subsections: [ { title: "Manejo médico", items: ["Control estricto de la presión arterial y el azúcar en la sangre", "Medicamentos para reducir las proteínas en la orina (IECA o ARA-II)", "Cambios en la dieta (reducción de sodio, proteínas, potasio y fósforo)", "Diuréticos para ayudar a eliminar el exceso de líquido", "Diálisis (hemodiálisis o diálisis peritoneal) o trasplante de riñón en etapas finales (falla renal)"] } ], note: "Un estilo de vida saludable y el control de enfermedades crónicas pueden detener o retrasar el daño renal severo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulte a un nefrólogo o médico general si:", items: ["Nota hinchazón persistente en sus piernas, rostro o abdomen", "Tiene cambios drásticos en sus hábitos urinarios (orina espumosa, muy oscura o con sangre)", "Siente fatiga constante acompañada de náuseas inexplicables", "Tiene diabetes o presión alta y nunca se ha hecho un chequeo de la función renal"] } },
'Trastornos de lenguaje' : { intro: "Los trastornos de lenguaje afectan la capacidad de una persona para comprender o usar las palabras de manera efectiva. Pueden presentarse en niños durante su desarrollo o en adultos tras una lesión cerebral, impactando significativamente la comunicación y el aprendizaje.", whatIs: { title: "¿Qué son los Trastornos de lenguaje?", text: "Son alteraciones neurológicas o del desarrollo que dificultan la adquisición, comprensión o expresión del lenguaje hablado o escrito. Difieren de los trastornos del habla (como la tartamudez), ya que el problema radica en el procesamiento de las palabras y su significado, no en la articulación física del sonido." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían según sea un trastorno expresivo o receptivo:", groups: [ { name: "Lenguaje expresivo", items: ["Dificultad para encontrar las palabras correctas al hablar", "Uso de oraciones muy cortas o gramaticalmente incorrectas", "Vocabulario limitado en comparación con niños de la misma edad", "Dificultad para contar una historia o explicar un evento claramente"] }, { name: "Lenguaje receptivo", items: ["Dificultad para entender lo que otros dicen o seguir instrucciones largas", "Falta de comprensión de bromas, sarcasmo o lenguaje figurado", "Respuestas que parecen desconectadas de la conversación", "Problemas para aprender nuevas palabras"] } ], warning: "En los adultos, la pérdida repentina de la capacidad de entender o hablar es una emergencia médica que sugiere un accidente cerebrovascular." }, types: { title: "Tipos Principales", intro: "Se clasifican según su origen y manifestación:", items: ["Trastorno del Desarrollo del Lenguaje (TDL): Aparece en la infancia sin una causa neurológica obvia.", "Afasia: Trastorno adquirido (común en adultos) causado por daño cerebral, como un ACV o un traumatismo.", "Trastorno de lenguaje expresivo: Dificultad para transmitir mensajes.", "Trastorno de lenguaje receptivo: Dificultad para entender mensajes.", "Trastorno mixto: Combina dificultades expresivas y receptivas."], note: "La intervención temprana es crucial para el desarrollo social y académico en los niños." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas dependen de si el trastorno es del desarrollo o adquirido:", items: ["Factores genéticos y antecedentes familiares (muy común en el TDL)", "Lesiones cerebrales (traumatismo craneoencefálico, accidente cerebrovascular, tumores cerebrales)", "Condiciones neurológicas subyacentes (autismo, parálisis cerebral)", "Pérdida de audición crónica en la primera infancia", "Falta extrema de estimulación lingüística temprana (casos raros)"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "Un patólogo del habla y lenguaje (logopeda) o un neuropsicólogo realiza la evaluación mediante:", items: ["Pruebas estandarizadas de vocabulario, comprensión y gramática adaptadas a la edad", "Observación de la interacción comunicativa en entornos naturales", "Evaluaciones audiológicas para descartar pérdida de audición", "Evaluación neurológica (y neuroimagen como RM) si se sospecha un daño cerebral adquirido"], note: "En niños, el diagnóstico diferencial es clave para distinguirlo de trastornos del espectro autista o discapacidad intelectual." }, treatment: { title: "Terapia y Manejo", intro: "El tratamiento se basa en la rehabilitación y adaptación constante:", subsections: [ { title: "Enfoques terapéuticos", items: ["Terapia del habla y lenguaje individualizada para mejorar vocabulario y gramática", "Ejercicios de comprensión auditiva y juegos de roles sociales", "Uso de sistemas de comunicación aumentativa y alternativa (CAA) en casos severos (tabletas, tableros de imágenes)", "Capacitación a los padres para estimular el lenguaje en casa", "Rehabilitación neurocognitiva para pacientes con afasia pos-ACV"] } ], note: "El pronóstico mejora drásticamente con terapia intensiva y apoyo familiar o escolar." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental consultar a un especialista si:", items: ["Un niño de 2 años no dice palabras o frases de dos palabras, o un niño de 3 años es incomprensible", "El niño no sigue instrucciones simples o parece no escuchar cuando se le habla", "Un adulto pierde de forma repentina o gradual la capacidad de hablar, escribir o entender lo que lee", "La frustración por no poder comunicarse provoca problemas de conducta severos o aislamiento social"] } },
'Agrandamiento de la próstata' : { intro: "El agrandamiento de la próstata, conocido como hiperplasia prostática benigna (HPB), es una condición extremadamente común en hombres a medida que envejecen. Al crecer la glándula, presiona la uretra y causa molestias urinarias significativas que pueden afectar la calidad de vida y el sueño.", whatIs: { title: "¿Qué es la Hiperplasia Prostática Benigna (HPB)?", text: "Es el crecimiento no canceroso de la glándula prostática, que rodea la uretra (el conducto que transporta la orina fuera del cuerpo) en los hombres. Al agrandarse, la próstata aprieta la uretra, dificultando el vaciado completo de la vejiga." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas del tracto urinario inferior (STUI) empeoran progresivamente e incluyen:", groups: [ { name: "Síntomas de vaciado (Obstructivos)", items: ["Flujo de orina débil, lento o que se detiene y comienza", "Dificultad para comenzar a orinar (titubeo)", "Goteo prolongado después de terminar de orinar", "Sensación de que la vejiga no se vacía por completo"] }, { name: "Síntomas de almacenamiento (Irritativos)", items: ["Necesidad urgente y repentina de orinar", "Aumento de la frecuencia urinaria durante el día", "Necesidad de levantarse múltiples veces durante la noche para orinar (nicturia)", "Incontinencia urinaria por urgencia"] } ], warning: "La incapacidad total y repentina para orinar (retención urinaria aguda) es una emergencia médica dolorosa que requiere la inserción de un catéter inmediato." }, types: { title: "Progresión de la Enfermedad", intro: "La HPB es una afección progresiva que se clasifica por el impacto de los síntomas:", items: ["HPB leve: Síntomas presentes pero que no interfieren significativamente con la vida diaria.", "HPB moderada a severa: Los síntomas causan molestias importantes, interrumpen el sueño y afectan la calidad de vida.", "HPB complicada: Presencia de daño renal, infecciones urinarias recurrentes, cálculos en la vejiga o sangre en la orina debido a la obstrucción severa."], note: "El tamaño de la próstata no siempre determina la gravedad de los síntomas; próstatas ligeramente agrandadas pueden causar síntomas graves y viceversa." }, causes: { title: "Causas y Factores de Riesgo", intro: "El agrandamiento prostático es una parte natural del envejecimiento masculino:", items: ["Envejecimiento (es raro antes de los 40 años, pero afecta a más del 50% de los hombres a los 60 años)", "Cambios en el equilibrio de las hormonas sexuales masculinas (especialmente la testosterona y la dihidrotestosterona o DHT) a medida que el hombre envejece", "Antecedentes familiares de agrandamiento de la próstata", "Condiciones médicas como la diabetes y enfermedades cardíacas", "Estilo de vida (la obesidad aumenta el riesgo, mientras que el ejercicio regular lo disminuye)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo evaluará la próstata y descartará otras afecciones (como el cáncer de próstata) mediante:", items: ["Cuestionario de síntomas (Índice Internacional de Síntomas Prostáticos - IPSS)", "Tacto rectal (DRE) para evaluar el tamaño y la consistencia de la próstata", "Análisis de sangre del Antígeno Prostático Específico (PSA) para detectar inflamación o riesgo de cáncer", "Prueba de flujo urinario (uroflujometría) para medir la fuerza de la micción", "Ecografía pélvica o transrectal para medir el volumen exacto de la próstata y la orina residual en la vejiga"], note: "El agrandamiento de la próstata (HPB) NO es cáncer de próstata ni aumenta el riesgo de padecerlo." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento va desde la observación hasta la cirugía, dependiendo de la molestia:", subsections: [ { title: "Enfoques terapéuticos", items: ["Espera vigilante y cambios en el estilo de vida (reducir líquidos antes de dormir, limitar cafeína y alcohol) para síntomas leves", "Medicamentos alfabloqueadores (tamsulosina) para relajar los músculos de la próstata y el cuello de la vejiga", "Medicamentos inhibidores de la 5-alfa reductasa (finasterida) para encoger lentamente la glándula prostática", "Terapias mínimamente invasivas (Rezum - vapor de agua, UroLift - implantes que abren la uretra, terapia láser)", "Cirugía tradicional (Resección transuretral de la próstata - RTUP) para extirpar la parte interna de la próstata que bloquea el flujo"] } ], note: "La cirugía moderna ofrece alivio a largo plazo con menores riesgos de efectos secundarios sexuales que en el pasado." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Urólogo?", intro: "Debe programar una visita médica si:", items: ["Se despierta varias veces por la noche para orinar, afectando su descanso", "Siente dolor, ardor o molestias al orinar, o nota sangre en su orina", "No puede controlar la necesidad de orinar o tiene fugas frecuentes", "Siente que su vejiga no se vacía por completo después de usar el baño", "Es incapaz de orinar en absoluto (acuda a emergencias)"] } },
'Síndrome de Down' : { intro: "El síndrome de Down es una condición genética de por vida que afecta el desarrollo físico y cognitivo. Con el apoyo adecuado, la intervención temprana y una atención médica integral, las personas con esta condición pueden llevar vidas saludables, productivas y altamente satisfactorias.", whatIs: { title: "¿Qué es el Síndrome de Down?", text: "Es un trastorno genético (cromosómico) causado por la presencia de una copia extra, total o parcial, del cromosoma 21. Este material genético adicional altera el curso normal del desarrollo, provocando características físicas específicas y grados variables de discapacidad intelectual." }, symptoms: { title: "Características Físicas y Cognitivas", intro: "Las características varían ampliamente de una persona a otra, pero suelen incluir:", groups: [ { name: "Rasgos físicos comunes", items: ["Rostro aplanado, especialmente en el puente nasal, y ojos en forma almendrada rasgados hacia arriba", "Cuello corto, orejas pequeñas y lengua que tiende a protruir", "Tono muscular débil (hipotonía) y articulaciones anormalmente laxas o flexibles", "Estatura más baja en la niñez y la edad adulta", "Manchas blancas diminutas en el iris del ojo (manchas de Brushfield) y un solo pliegue en la palma de la mano"] }, { name: "Desarrollo cognitivo y de comportamiento", items: ["Discapacidad intelectual de leve a moderada (rara vez severa)", "Retraso en el desarrollo del habla y del lenguaje", "Períodos de atención más cortos y posibles dificultades de aprendizaje", "En general, muestran una gran sociabilidad y empatía"] } ], warning: "Los bebés con hipotonía severa pueden tener dificultades para alimentarse y requieren atención pediátrica especializada temprana." }, types: { title: "Variaciones Genéticas", intro: "Existen tres tipos genéticos de síndrome de Down, que no se pueden distinguir por la apariencia física:", items: ["Trisomía 21 (95% de los casos): Cada célula del cuerpo tiene tres copias separadas del cromosoma 21 en lugar de las dos habituales.", "Síndrome de Down por translocación (3-4%): Parte del cromosoma 21 extra se adhiere a otro cromosoma antes o en la concepción.", "Síndrome de Down con mosaicismo (1-2%): Algunas células tienen tres copias del cromosoma 21, pero otras células tienen las dos copias normales. Pueden tener menos características de la condición."], note: "El tipo por translocación es el único que puede ser heredado de uno de los padres (portador sano)." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es causado por un error aleatorio en la división celular en el óvulo, el espermatozoide o el embrión:", items: ["El factor de riesgo más significativo es la edad materna: el riesgo aumenta exponencialmente en mujeres mayores de 35 años al momento de concebir", "Tener ya un hijo con síndrome de Down aumenta el riesgo en embarazos futuros", "Ser portador de la translocación genética para el síndrome de Down (tanto hombres como mujeres pueden transmitirla)", "No es causado por el estilo de vida de los padres, factores ambientales ni nada que los padres hayan hecho antes o durante el embarazo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se puede detectar antes o después del nacimiento mediante:", items: ["Pruebas de detección prenatal: Análisis de sangre materna (ADN fetal libre) y ecografías (para medir la translucencia nucal) que estiman el riesgo", "Pruebas de diagnóstico prenatal: Amniocentesis o muestreo de vellosidades coriónicas (CVS) que analizan los cromosomas fetales para un diagnóstico definitivo al 100%", "Diagnóstico postnatal: Basado inicialmente en la apariencia física del bebé al nacer y confirmado mediante un análisis de sangre del recién nacido llamado cariotipo"], note: "Las pruebas de diagnóstico prenatal conllevan un riesgo muy pequeño de aborto espontáneo, por lo que suelen ofrecerse a mujeres con alto riesgo en las pruebas de detección." }, treatment: { title: "Apoyo e Intervención Médica", intro: "No existe cura, pero la intervención temprana transforma la calidad de vida:", subsections: [ { title: "Cuidado multidisciplinario", items: ["Programas de intervención temprana (fisioterapia para el tono muscular, terapia del habla para la comunicación, y terapia ocupacional)", "Educación especial e inclusión en escuelas regulares mediante Programas de Educación Individualizada (IEP)", "Evaluaciones médicas regulares para detectar y tratar afecciones de salud comunes (defectos cardíacos congénitos presentes en el 50% de los bebés, problemas de visión/audición, hipotiroidismo y enfermedad celíaca)", "Apoyo psicológico y grupos de apoyo para las familias", "Formación vocacional y programas de vida independiente para adultos jóvenes"] } ], note: "La esperanza de vida ha aumentado drásticamente; hoy, muchas personas con síndrome de Down viven hasta los 60 años o más." }, whenToSeekHelp: { title: "¿Cuándo Buscar Asesoramiento Médico?", intro: "Se recomienda buscar orientación genética o pediátrica especializada si:", items: ["Está embarazada y las pruebas de detección prenatal indican un alto riesgo de anomalías cromosómicas", "Tiene un hijo con síndrome de Down y está planificando otro embarazo", "Es un padre o cuidador que nota que el niño no está alcanzando los hitos de desarrollo esperados con el apoyo actual", "El paciente (niño o adulto) experimenta cambios repentinos de comportamiento, pérdida de habilidades o apnea del sueño"] } },
'Convulsiones febriles' : { intro: "Las convulsiones febriles son episodios aterradores para cualquier padre, pero generalmente son inofensivos. Ocurren en niños pequeños sanos como respuesta directa a un aumento rápido de la temperatura corporal, a menudo causado por una infección común.", whatIs: { title: "¿Qué son las Convulsiones febriles?", text: "Son espasmos o sacudidas musculares incontrolables que ocurren en niños, por lo general entre los 6 meses y los 5 años de edad, en respuesta a una fiebre alta (generalmente superior a 38 °C o 100.4 °F). No son epilepsia." }, symptoms: { title: "Síntomas y Apariencia del Episodio", intro: "El episodio suele ocurrir el primer día de la enfermedad febril e incluye:", groups: [ { name: "Manifestaciones motoras y físicas", items: ["Pérdida de la conciencia y falta de respuesta a voces o estímulos", "Rigidez súbita del cuerpo, brazos y piernas, seguida de sacudidas rítmicas o espasmos violentos", "Los ojos pueden ponerse en blanco o la mirada quedarse fija", "Puede haber babeo, espumarajos en la boca o vómitos", "La piel puede volverse ligeramente pálida o azulada momentáneamente por la alteración respiratoria"] }, { name: "Fase postictal (después de la convulsión)", items: ["El niño suele estar profundamente dormido, confundido, muy cansado o irritable durante unos minutos a una hora", "No hay parálisis ni debilidad focal persistente"] } ], warning: "Si la convulsión dura más de 5 minutos o el niño presenta dificultad grave para respirar, llame a los servicios de emergencia (911/112) inmediatamente." }, types: { title: "Clasificación Clínica", intro: "Los médicos las dividen en dos tipos principales para evaluar el riesgo:", items: ["Convulsión febril simple: La más común. Dura desde unos segundos hasta 15 minutos, afecta a todo el cuerpo (generalizada) y no se repite dentro del mismo período de 24 horas.", "Convulsión febril compleja: Dura más de 15 minutos, afecta solo a una parte del cuerpo (focal) o se repite en un período de 24 horas."], note: "Las convulsiones febriles simples NO causan daño cerebral, discapacidad intelectual ni aumentan significativamente el riesgo de epilepsia futura." }, causes: { title: "Desencadenantes Comunes", intro: "La convulsión es provocada por la fiebre, no por la infección en sí:", items: ["Infecciones virales (la causa más frecuente, como la roseola, la gripe o infecciones del tracto respiratorio superior)", "Infecciones bacterianas (como infecciones de oído o del tracto urinario)", "Aumento repentino de la temperatura corporal (a menudo, la convulsión ocurre antes de que los padres siquiera noten que el niño tiene fiebre)", "Reacción post-vacunación (un riesgo muy pequeño y temporal de fiebre después de vacunas como la triple vírica MMR, no de la vacuna en sí)", "Fuerte predisposición genética (si un padre tuvo convulsiones febriles, el niño tiene mayor riesgo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El objetivo del médico en urgencias es descubrir la causa de la fiebre y descartar infecciones graves:", items: ["Examen físico pediátrico exhaustivo para encontrar el foco de la infección (oídos, garganta, pulmones)", "Análisis de orina o sangre si la fuente de la fiebre no es evidente", "Punción lumbar (extracción de líquido de la médula espinal) para descartar meningitis o encefalitis, especialmente en bebés menores de 12 meses o si hay rigidez de cuello", "Un electroencefalograma (EEG) o escáner cerebral generalmente NO es necesario para una convulsión febril simple"], note: "El diagnóstico de una convulsión febril es de exclusión, asegurando que no haya una infección en el sistema nervioso central." }, treatment: { title: "Primeros Auxilios y Manejo Médico", intro: "Durante la convulsión, el objetivo es evitar lesiones físicas al niño:", subsections: [ { title: "Qué hacer durante la convulsión", items: ["Acueste al niño de lado en una superficie segura (para evitar atragantamientos) y afloje la ropa alrededor de su cuello", "NO intente detener sus movimientos, no lo sujete", "NO ponga absolutamente nada en su boca (no se tragará la lengua)", "Observe el reloj para saber exactamente cuánto dura la convulsión"] }, { title: "Tratamiento posterior", items: ["Medicamentos para reducir la fiebre (paracetamol o ibuprofeno) para aliviar el malestar, aunque no previenen futuras convulsiones febriles", "Tratamiento de la infección subyacente (antibióticos si es bacteriana)", "En casos de convulsiones complejas o muy prolongadas, el médico puede recetar medicamentos anticonvulsivos de rescate (como diazepam rectal) para tener en casa"] } ], note: "Dar baños de agua fría o frotar alcohol no previene la convulsión y puede causar más estrés o escalofríos en el niño." }, whenToSeekHelp: { title: "¿Cuándo Llamar a Urgencias?", intro: "Busque atención médica de emergencia de inmediato si el niño:", items: ["Tiene una convulsión que dura más de 5 minutos continuos", "Presenta vómitos severos, rigidez en el cuello, o problemas respiratorios durante o después de la convulsión", "Parece inusualmente somnoliento, no responde o no se recupera rápidamente después del episodio", "La convulsión afecta solo a un lado de su cuerpo (focal)", "Es su primer episodio de convulsión (debe ser evaluado por un médico de inmediato para descartar meningitis)"] } },
'Divertículo de Meckel' : { intro: "El divertículo de Meckel es la malformación congénita más común del tracto gastrointestinal. Es un pequeño saco que sobresale de la pared del intestino delgado. Aunque está presente desde el nacimiento, la mayoría de las personas nunca tienen síntomas, pero cuando se inflama, causa una urgencia abdominal.", whatIs: { title: "¿Qué es un Divertículo de Meckel?", text: "Es un vestigio o remanente del conducto onfalomesentérico (una estructura embrionaria que conecta el saco vitelino con el intestino del feto). Si este conducto no se cierra y absorbe por completo antes de nacer, deja una pequeña bolsa ciega en la parte inferior del intestino delgado (íleon)." }, symptoms: { title: "Síntomas y Complicaciones", intro: "Solo el 2% al 3% de las personas con esta anomalía desarrollan síntomas, típicamente en la infancia:", groups: [ { name: "Hemorragia digestiva (El síntoma más común en niños)", items: ["Evacuación de grandes cantidades de sangre oscura o de color rojo ladrillo por el recto", "Heces con aspecto de 'jalea de grosella'", "La hemorragia suele ser completamente indolora, pero puede causar anemia severa, palidez y fatiga rápida"] }, { name: "Síntomas inflamatorios u obstructivos (Comunes en adultos y niños mayores)", items: ["Dolor abdominal severo y sensibilidad, a menudo cerca del ombligo o en la parte inferior derecha del abdomen (imita una apendicitis aguda)", "Náuseas, vómitos repetidos e hinchazón abdominal", "Incapacidad para evacuar gases o heces debido a la obstrucción intestinal"] } ], warning: "La presencia de grandes cantidades de sangre en las heces de un niño pequeño es una emergencia médica que requiere hospitalización inmediata." }, types: { title: "Características del Tejido Ectópico", intro: "El problema surge porque el divertículo suele contener tejidos que no pertenecen allí:", items: ["Tejido de la mucosa gástrica (estómago): Es el más común. Este tejido produce ácido clorhídrico, que ulcera y sangra el intestino delgado adyacente (que no está diseñado para tolerar ácido).", "Tejido pancreático ectópico: Menos común, pero también puede causar inflamación u obstrucción.", "Complicaciones secundarias: El saco puede invertirse (intususcepción), girar sobre sí mismo (vólvulo) causando obstrucción, o inflamarse (diverticulitis de Meckel)."], note: "Los síntomas tienden a ocurrir antes de los 10 años de edad, siendo más frecuentes y severos en niños que en niñas." }, causes: { title: "Causas y Desarrollo", intro: "Es estrictamente una condición congénita (presente en el nacimiento):", items: ["Fracaso en la obliteración (cierre) del conducto onfalomesentérico durante las semanas 5 a 7 de la gestación fetal", "No está relacionado con la dieta, el estilo de vida, la genética hereditaria clara ni ninguna acción de la madre durante el embarazo", "Es una anomalía anatómica fortuita que sigue la 'regla de los 2': Afecta al 2% de la población, está a 2 pies de la válvula ileocecal, mide 2 pulgadas de largo y suele presentar síntomas antes de los 2 años de edad"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico puede ser un desafío médico porque sus síntomas imitan otras enfermedades intestinales. Se requiere:", items: ["Gammagrafía de Meckel (la prueba más precisa para hemorragias en niños): Se inyecta un marcador radiactivo leve que es absorbido específicamente por el tejido gástrico ectópico dentro del divertículo, resaltándolo en una cámara especial", "Tomografía computarizada (TC) de abdomen con contraste (útil en adultos para detectar inflamación u obstrucción)", "Endoscopia capsular inalámbrica (tragar una pequeña cámara) para buscar el origen de un sangrado misterioso en el intestino delgado", "Laparoscopia exploratoria (cirugía de ojo de cerradura) si las pruebas de imagen no son concluyentes pero los síntomas son agudos"], note: "En muchos casos de adultos, se descubre accidentalmente durante una cirugía abdominal por otra causa, como una apendicitis sospechosa." }, treatment: { title: "Opciones de Tratamiento y Cirugía", intro: "El manejo es exclusivamente quirúrgico para los pacientes sintomáticos:", subsections: [ { title: "Intervenciones quirúrgicas", items: ["Resección quirúrgica del divertículo: Extirpación de la bolsa ciega (diverticulectomía) generalmente mediante cirugía laparoscópica mínimamente invasiva", "Resección intestinal parcial: Si el ácido ha causado una úlcera grande, perforación o daño en el intestino delgado adyacente, el cirujano extirpará el divertículo junto con una pequeña sección del intestino dañado y unirá los extremos sanos", "Transfusiones de sangre previas a la cirugía para estabilizar a los niños que han presentado sangrado rectal masivo", "Si se descubre incidentalmente en una cirugía por otro motivo, el cirujano puede extirparlo preventivamente para evitar problemas futuros, dependiendo de la edad y el riesgo del paciente"] } ], note: "La recuperación quirúrgica es rápida y la extirpación cura el problema de forma permanente sin afectar la función digestiva." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias Médicas?", intro: "Busque atención médica de emergencia para su hijo o para usted si presenta:", items: ["Cantidades significativas de sangre en las heces o sangre roja oscura/granate sin dolor", "Dolor abdominal agudo, repentino e intenso que no desaparece o empeora", "Vómitos continuos acompañados de hinchazón abdominal o incapacidad para defecar", "Signos de pérdida de sangre severa (mareos extremos, palidez, frecuencia cardíaca rápida o desmayos)"] } },
'Traumatismo dental' : { intro: "Un traumatismo dental es cualquier lesión física sufrida en los dientes, los labios, las encías o el hueso maxilar circundante. Desde un simple diente astillado hasta un diente completamente arrancado (avulsión), el tratamiento rápido es crucial para salvar la sonrisa y prevenir infecciones.", whatIs: { title: "¿Qué es un Traumatismo dental?", text: "Es el daño traumático a las estructuras orodentales causado por un impacto o fuerza externa. Puede involucrar la fractura de la corona o la raíz del diente, el aflojamiento del diente dentro de su cavidad, o su desplazamiento o expulsión total de la mandíbula." }, symptoms: { title: "Tipos de Lesiones y Síntomas", intro: "Los signos varían desde daños cosméticos menores hasta emergencias complejas:", groups: [ { name: "Daño estructural al diente", items: ["Diente astillado, agrietado o fracturado (puede exponer la pulpa nerviosa causando dolor agudo o sensibilidad al aire/frío)", "Decoloración repentina del diente (se vuelve gris o rosado oscuro, indicando daño interno o sangrado del nervio)", "Dolor intenso al morder o tocar el diente afectado"] }, { name: "Daño a los tejidos de soporte", items: ["Diente aflojado o móvil (subluxación)", "Diente hundido hacia la encía (intrusión) o extraído parcialmente (extrusión)", "Diente arrancado por completo de la boca (avulsión)", "Encías o labios cortados, sangrantes, hinchados y con hematomas severos"] } ], warning: "Un diente permanente arrancado de raíz (avulsionado) debe reimplantarse en un plazo máximo de 30 a 60 minutos para tener buenas posibilidades de supervivencia." }, types: { title: "Clasificación de las Fracturas Dentales", intro: "Las fracturas se clasifican para guiar el tratamiento:", items: ["Infracción del esmalte: Grieta menor en la capa exterior; a menudo no requiere tratamiento.", "Fractura de la corona no complicada: Rompe el esmalte y la dentina, pero no expone el nervio (pulpa).", "Fractura de la corona complicada: Exposición directa del nervio dental doloroso; requiere tratamiento de conducto.", "Fractura de raíz: La ruptura ocurre por debajo de la línea de las encías, a menudo requiriendo la extracción del diente si no se estabiliza.", "Luxación: El diente está intacto pero fuera de su posición normal."], note: "Los dientes de leche (temporales) arrancados nunca se vuelven a colocar en la boca, para no dañar el germen del diente permanente debajo." }, causes: { title: "Causas y Factores Comunes", intro: "Los traumatismos bucales son altamente prevalentes y ocurren debido a:", items: ["Accidentes deportivos sin uso de protectores bucales (fútbol, baloncesto, hockey, artes marciales)", "Caídas accidentales (muy común en niños pequeños que están aprendiendo a caminar)", "Accidentes de tráfico, en bicicleta o monopatín", "Masticar objetos excesivamente duros (hielo, caramelos duros) o usar los dientes como herramientas", "Altercados físicos o violencia facial"] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "El dentista o endodoncista evaluará la viabilidad del diente mediante:", items: ["Examen visual y palpación para verificar la movilidad de los dientes adyacentes y el hueso", "Radiografías dentales (periapicales y panorámicas) para detectar fracturas de raíz invisibles y daños en el hueso maxilar", "Pruebas de vitalidad pulpar (pruebas de frío o térmicas) para verificar si el nervio del diente sigue vivo o está dañado", "Examen neurológico básico para descartar lesiones en la cabeza, conmociones cerebrales o fracturas de mandíbula (si el trauma fue severo)"], note: "El seguimiento a largo plazo (meses o años) es necesario, ya que el nervio del diente puede morir mucho tiempo después del golpe." }, treatment: { title: "Tratamiento y Primeros Auxilios", intro: "El pronóstico depende de las medidas tomadas inmediatamente después del accidente:", subsections: [ { title: "Procedimientos odontológicos", items: ["Para un diente arrancado (Permanente): Tómelo solo por la corona (la parte blanca), no toque la raíz. Enjuáguelo suavemente con leche (no agua). Intente recolocarlo en el hueco, o guárdelo en leche, saliva o suero fisiológico y corra al dentista en menos de una hora.", "Dientes fracturados: El dentista reconstruirá el diente usando resina del color del diente (bonding) o colocando una corona. Si el nervio está expuesto, se requerirá tratamiento de conducto (endodoncia).", "Dientes móviles o desplazados: El dentista los reubicará a su posición correcta y los unirá temporalmente (ferulización) a los dientes vecinos con un alambre o resina durante 2 a 4 semanas para que sanen.", "Sutura de tejidos blandos lacerados (labios, encías) y prescripción de antibióticos para prevenir abscesos.", "Evaluación de la necesidad de una vacuna contra el tétanos si la herida se contaminó con tierra."] } ], note: "La prevención mediante el uso de protectores bucales hechos a medida durante la práctica deportiva reduce el riesgo de lesiones severas en un 90%." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias Dentales?", intro: "Acuda a un dentista de urgencias u hospital inmediatamente si:", items: ["Se le ha caído completamente un diente permanente", "Tiene un diente dolorosamente fuera de posición, empujado hacia adentro, flojo o fracturado gravemente con sangrado", "Tiene dificultad para respirar, tragar o cerrar la mandíbula debido al dolor o la desviación", "Experimenta mareos, pérdida de memoria, vómitos continuos o dolor de cabeza intenso tras el golpe en la cara (vaya a la sala de emergencias médicas por posible conmoción)"] } },
'Cáncer' : { intro: "El cáncer no es una sola enfermedad, sino un amplio grupo de más de 100 patologías diferentes. Todas comparten una característica común y letal: el crecimiento descontrolado y la propagación anormal de células en el cuerpo. El diagnóstico temprano y los tratamientos oncológicos modernos salvan millones de vidas anualmente.", whatIs: { title: "¿Qué es el Cáncer?", text: "Es una enfermedad genética originada a nivel celular. Las células humanas normales crecen, se dividen y mueren de manera ordenada. En el cáncer, el ADN de la célula sufre mutaciones que desactivan las señales de detención y muerte celular; las células defectuosas se multiplican sin control, formando masas de tejido llamadas tumores (excepto en los cánceres de sangre, como la leucemia)." }, symptoms: { title: "Signos y Síntomas de Advertencia", intro: "Los síntomas varían drásticamente dependiendo de qué órgano esté afectado, pero las señales generales incluyen:", groups: [ { name: "Cambios físicos notables", items: ["Aparición de un bulto, engrosamiento o masa palpable debajo de la piel (como en los senos o testículos)", "Cambios evidentes en un lunar o en la piel (asimetría, bordes irregulares, cambio de color, sangrado)", "Pérdida de peso rápida, drástica e inexplicable", "Fatiga extrema y debilidad que no mejora con el descanso", "Sudores nocturnos profusos y fiebre recurrente sin causa infecciosa evidente"] }, { name: "Síntomas funcionales u orgánicos", items: ["Dolor nuevo y persistente que no cede (dolor de huesos, dolores de cabeza agudos continuos)", "Cambios en los hábitos intestinales (diarrea crónica, estreñimiento severo, sangre en las heces) o urinarios", "Tos persistente, voz ronca o tos con sangre", "Dificultad progresiva para tragar o indigestión constante", "Llagas en la boca o en la piel que no cicatrizan después de varias semanas"] } ], warning: "Tener uno de estos síntomas no significa que tenga cáncer (hay muchas causas benignas), pero requiere evaluación médica sin demora." }, types: { title: "Clasificación Principal", intro: "Los cánceres se denominan según el órgano donde se originan y el tipo de célula:", items: ["Carcinomas: El tipo más común (mama, pulmón, próstata, colon). Comienzan en la piel o en los tejidos que recubren los órganos internos.", "Sarcomas: Se originan en huesos, cartílagos, grasa, músculos o vasos sanguíneos.", "Leucemias: Cánceres de los tejidos que forman la sangre, como la médula ósea. Producen grandes cantidades de glóbulos blancos anormales.", "Linfomas y Mielomas: Comienzan en las células del sistema inmunológico (ganglios linfáticos y células plasmáticas).", "Cánceres del sistema nervioso central: Tumores que se desarrollan en el cerebro y la médula espinal."], note: "Si un cáncer de mama se propaga al hígado, se llama cáncer de mama metastásico, no cáncer de hígado." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño al ADN es causado por una combinación de factores hereditarios y ambientales:", items: ["Consumo de tabaco (la principal causa de cáncer y de muerte por cáncer en todo el mundo)", "Factores genéticos heredados (como las mutaciones en los genes BRCA1/BRCA2 para cáncer de mama y ovario)", "Radiación (exceso de luz ultravioleta del sol, camas de bronceado, radiación ionizante industrial o gas radón)", "Ciertas infecciones virales y bacterianas (VPH para cáncer de cuello uterino, Hepatitis B y C para cáncer de hígado, H. pylori para cáncer de estómago)", "Estilo de vida poco saludable (obesidad grave, consumo excesivo de alcohol, dieta pobre en fibra y alta en carnes ultraprocesadas)", "Envejecimiento (la gran mayoría de los cánceres se diagnostican en personas mayores de 65 años)"] }, diagnosis: { title: "¿Cómo se Diagnostica y Estadifica?", intro: "El proceso diagnóstico busca confirmar la presencia de células cancerosas y evaluar si se han diseminado (estadificación):", items: ["Biopsia celular o de tejido: El único método definitivo. Se extrae una muestra de tejido y un patólogo la examina bajo el microscopio para detectar células cancerosas", "Estudios de diagnóstico por imagen (Tomografía Computarizada, Resonancia Magnética, PET, Ecografía o Rayos X) para ver el tamaño del tumor y si hay metástasis en otros órganos", "Pruebas endoscópicas (colonoscopia, broncoscopia) para visualizar directamente el interior del cuerpo y tomar biopsias", "Análisis de sangre para detectar marcadores tumorales (como el PSA o CA-125), aunque no son concluyentes por sí solos", "Pruebas genómicas del tumor (para identificar las mutaciones de ADN específicas del tumor y guiar el tratamiento personalizado)"], note: "El cáncer se clasifica típicamente en Estadios del I al IV. El Estadio I es temprano y localizado; el Estadio IV significa que se ha propagado a otras partes del cuerpo." }, treatment: { title: "Opciones de Tratamiento Oncológico", intro: "El tratamiento suele ser multimodal, gestionado por un equipo de oncólogos y cirujanos:", subsections: [ { title: "Modalidades de tratamiento", items: ["Cirugía oncológica: El objetivo principal para tumores sólidos aislados; implica extirpar el tumor y los tejidos o ganglios linfáticos circundantes", "Quimioterapia: Uso de medicamentos sistémicos potentes administrados por vía intravenosa o pastillas para matar células de división rápida en todo el cuerpo (causa caída del cabello y náuseas)", "Radioterapia: Uso de haces de alta energía (Rayos X o protones) focalizados para destruir las células cancerosas en un área específica", "Inmunoterapia: Tratamientos revolucionarios que estimulan o 'entrenan' al propio sistema inmunológico del paciente para que reconozca y ataque el cáncer", "Terapia dirigida: Medicamentos de precisión diseñados para atacar anomalías genéticas específicas dentro de las células cancerosas sin dañar tanto a las células sanas", "Terapia hormonal: Se usa para privar de hormonas a los cánceres que dependen de ellas para crecer (muy común en el cáncer de mama y próstata)", "Trasplante de células madre o médula ósea (para cánceres de sangre)", "Cuidados paliativos: Tratamiento centrado en aliviar el dolor, los síntomas físicos y el estrés de una enfermedad grave, independientemente de la etapa del cáncer"] } ], note: "La detección temprana (mediante mamografías, colonoscopias, pruebas de Papanicolaou) es el factor más determinante para lograr la curación." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Médico?", intro: "No demore la consulta médica si nota:", items: ["Cualquier bulto nuevo, duro o creciente en su cuerpo", "Pérdida de peso de varios kilos en poco tiempo sin haber hecho dieta ni ejercicio", "Sangrado o secreción inusual por cualquier orificio (boca, nariz, recto, uretra, vagina)", "Dolores constantes o síntomas extraños que no desaparecen después de un par de semanas", "Un cambio sospechoso en la apariencia, color o tamaño de un lunar existente en la piel"] } },
'Dolor de cabeza' : { intro: "El dolor de cabeza (cefalea) es uno de los síntomas médicos más comunes, afectando a la mayoría de las personas en algún momento de su vida. Aunque la gran mayoría son molestos pero inofensivos, algunos tipos pueden ser incapacitantes o, rara vez, indicar una condición médica subyacente grave.", whatIs: { title: "¿Qué es un Dolor de cabeza?", text: "Es cualquier dolor que se percibe en cualquier región de la cabeza o la parte superior del cuello. El cerebro en sí no siente dolor, ya que carece de receptores de dolor; la cefalea proviene de la inflamación o tracción de los vasos sanguíneos, músculos, nervios craneales o meninges que rodean el cerebro." }, symptoms: { title: "Síntomas y Características", intro: "El patrón, la ubicación y el tipo de dolor ayudan a identificar su origen:", groups: [ { name: "Tipos de dolor comunes", items: ["Dolor opresivo, constante, en forma de banda alrededor de toda la cabeza (cefalea tensional)", "Dolor punzante, sordo o palpitante intenso, a menudo limitado a un solo lado de la cara o cabeza (migraña)", "Dolor detrás del ojo y la frente, o en los pómulos, que empeora al inclinarse hacia adelante (cefalea sinusal)", "Dolor intenso, explosivo y extremadamente severo que rodea un ojo, a menudo provocando lagrimeo y congestión nasal del mismo lado (cefalea en racimos)"] }, { name: "Síntomas asociados importantes", items: ["Sensibilidad extrema a la luz (fotofobia) o al ruido (fonofobia), náuseas y vómitos (típicos de migrañas)", "Rigidez muscular severa en el cuello, hombros y cuero cabelludo", "Cambios visuales o 'auras' (luces intermitentes, puntos ciegos) antes de que comience el dolor de cabeza"] } ], warning: "El dolor de cabeza súbito, explosivo y 'el peor de su vida' (cefalea en trueno) es una emergencia médica y un signo característico de aneurisma cerebral roto." }, types: { title: "Clasificación Principal", intro: "Médicamente, los dolores de cabeza se dividen en dos categorías amplias:", items: ["Cefaleas primarias: El dolor de cabeza es la enfermedad en sí misma, no un síntoma de otra afección. Ejemplos: Cefalea tensional (la más común, relacionada con estrés muscular), Migrañas, y Cefalea en racimos.", "Cefaleas secundarias: El dolor es un síntoma de otra enfermedad o problema estructural subyacente. Ejemplos: dolor de cabeza por sinusitis, deshidratación, resaca, traumatismo craneal, glaucoma, tumor cerebral o meningitis.", "Dolor de cabeza por uso excesivo de medicamentos (cefalea de rebote): Ocurre cuando se toman analgésicos para el dolor de cabeza con demasiada frecuencia, volviendo crónico el dolor."], note: "Las migrañas crónicas pueden ser tan severamente debilitantes que se consideran una discapacidad neurológica." }, causes: { title: "Causas y Desencadenantes Frecuentes", intro: "Los desencadenantes varían ampliamente según la persona y el tipo de cefalea:", items: ["Estrés emocional intenso, ansiedad aguda o depresión", "Tensión y contracturas musculares en el cuello, mandíbula (bruxismo) o espalda superior debido a mala postura (ej. exceso de uso de pantallas)", "Cambios hormonales (especialmente fluctuaciones de estrógeno en mujeres alrededor del ciclo menstrual)", "Desencadenantes dietéticos: deshidratación grave, saltarse comidas, consumo excesivo de cafeína (o abstinencia repentina), alcohol, o ciertos alimentos (quesos añejos, carnes curadas, MSG, edulcorantes artificiales)", "Factores ambientales: luces brillantes o parpadeantes, ruidos fuertes, cambios bruscos en el clima o la presión barométrica, olores fuertes y falta de sueño"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para diagnosticar el tipo de cefalea, el médico (a menudo un neurólogo) se basa fundamentalmente en:", items: ["Un historial médico minucioso evaluando la frecuencia, intensidad, ubicación, y síntomas asociados (un diario de dolores de cabeza es extremadamente útil)", "Examen físico y neurológico completo (evaluando la visión, el equilibrio, los reflejos y la fuerza)", "Análisis de sangre (para buscar infecciones subyacentes o problemas de la tiroides si es secundario)", "Resonancia magnética (RM) o tomografía computarizada (TC) de la cabeza (generalmente reservadas solo para descartar problemas graves como tumores, sangrados o anomalías vasculares si el patrón del dolor es sospechoso o de inicio repentino)"], note: "Para la gran mayoría de los dolores de cabeza crónicos tensionales o migrañas, las pruebas de imagen cerebral resultan completamente normales." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento depende del diagnóstico exacto y se divide en prevención y alivio agudo:", subsections: [ { title: "Medicamentos y Terapias", items: ["Tratamiento agudo (abortivo): Analgésicos de venta libre (paracetamol, ibuprofeno, naproxeno) para dolores leves; Triptanes (como sumatriptán) recetados específicamente para detener las migrañas moderadas o graves de inmediato.", "Terapias preventivas (profilácticas): Medicamentos diarios para reducir la frecuencia si el paciente sufre episodios constantes (antidepresivos tricíclicos, betabloqueantes, anticonvulsivos, o inyecciones de Botox en cabeza y cuello para migrañas crónicas severas).", "Nuevos fármacos monoclonales (inhibidores del CGRP) diseñados específicamente para prevenir migrañas crónicas intratables.", "Terapias complementarias: Terapia cognitivo-conductual (TCC) para el manejo del estrés, fisioterapia cervical, acupuntura, y biorretroalimentación (biofeedback).", "Modificaciones del estilo de vida: Beber abundante agua, establecer horarios estrictos de sueño, usar filtros de luz azul en pantallas y hacer ejercicio aeróbico regular."] } ], note: "Para evitar la 'cefalea de rebote', se recomienda no tomar analgésicos de venta libre más de 2 o 3 veces por semana." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias o al Neurólogo?", intro: "El dolor de cabeza requiere evaluación médica urgente en el hospital si:", items: ["Es extremadamente repentino y severo (alcanza el dolor máximo en segundos)", "Viene acompañado de fiebre alta, rigidez extrema en el cuello, confusión mental, convulsiones o visión doble", "Experimenta debilidad en un lado de la cara o el cuerpo, dificultad para hablar o caminar (signos de derrame cerebral)", "El dolor empeora al acostarse, toser o hacer esfuerzo físico, o lo despierta a mitad de la noche", "Es un dolor de cabeza nuevo o severo en alguien mayor de 50 años o con antecedentes de cáncer", "El dolor comienza después de un traumatismo o golpe fuerte en la cabeza"] } },
'Úlceras e infecciones corneales' : { intro: "Una úlcera corneal (o queratitis infecciosa) es una llaga abierta en la córnea, la capa transparente en la parte delantera del ojo. Es una emergencia oftalmológica dolorosa y severa que, si no se trata rápida y agresivamente, puede causar cicatrices permanentes, daño visual severo o ceguera irreversible.", whatIs: { title: "¿Qué es una Úlcera Corneal?", text: "Es una erosión o defecto en el tejido de la superficie de la córnea, casi siempre causado por una infección microbiana masiva y agresiva, a menudo iniciada por una lesión menor previa, frotarse el ojo vigorosamente, o el mal uso de lentes de contacto." }, symptoms: { title: "Síntomas Visuales y Físicos", intro: "Los síntomas progresan rápidamente, y son intensamente molestos:", groups: [ { name: "Síntomas sensoriales en el ojo", items: ["Dolor ocular agudo, punzante o palpitante (a menudo tan severo que dificulta dormir)", "Sensación constante y muy irritante de tener un cuerpo extraño, polvo o arena debajo del párpado", "Sensibilidad extrema y dolorosa a la luz brillante (fotofobia severa)", "Visión borrosa, nublada o reducción rápida y dramática de la agudeza visual"] }, { name: "Signos visibles e inflamatorios", items: ["Enrojecimiento severo de la esclerótica (la parte blanca del ojo), a menudo más intenso alrededor del iris", "Aparición de un punto blanco o gris difuso visible a simple vista en la córnea transparente", "Secreción excesiva de lágrimas, pus espeso o líquido amarillo-verdoso acumulándose en la esquina del ojo", "Párpados extremadamente hinchados que pueden ser difíciles de abrir"] } ], warning: "Cualquier persona que use lentes de contacto y desarrolle un ojo rojo y doloroso debe quitarse el lente inmediatamente y acudir al oftalmólogo el mismo día." }, types: { title: "Tipos de Queratitis/Úlceras Infecciosas", intro: "Se clasifican por el tipo de microorganismo que causa la infección agresiva:", items: ["Úlceras Bacterianas: La forma más rápida, severa y común (frecuente en usuarios de lentes de contacto y tras abrasiones corneales).", "Úlceras Virales: Causadas frecuentemente por el virus del herpes simple (causa úlceras dendríticas en forma de rama) o el virus varicela-zóster.", "Úlceras Fúngicas (Hongos): A menudo resultado de lesiones agrícolas, ramas de árboles que raspan el ojo, o uso excesivo de gotas con esteroides.", "Queratitis por Acanthamoeba: Una infección parasitaria devastadora e intratable causada por lavar o nadar con lentes de contacto en agua dulce (ríos, lagos, piscinas) o usar agua del grifo para limpiarlos."], note: "Las infecciones no microbianas también pueden causar úlceras (por sequedad ocular severa, parálisis de Bell o quemaduras químicas)." }, causes: { title: "Causas y Factores de Riesgo Principales", intro: "La córnea intacta es muy resistente, pero una vez dañada, es vulnerable:", items: ["Mala higiene de los lentes de contacto (dormir con ellos puestos es el factor de riesgo número uno para las úlceras bacterianas graves)", "Abrasiones o rasguños corneales previos (por polvo metálico, ramas de árboles, papel, uñas de bebés)", "Síndrome de ojo seco severo continuo (la falta de lágrimas protectoras permite que los párpados erosionen la córnea seca)", "Enfermedades autoinmunes que causan inflamación en el ojo (artritis reumatoide)", "Deficiencia severa de vitamina A", "Uso prolongado de gotas oftálmicas esteroides, que debilitan la respuesta inmunitaria del ojo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un oftalmólogo debe realizar el diagnóstico de inmediato utilizando:", items: ["Examen visual detallado con una lámpara de hendidura (un microscopio especial iluminado) para ver el tamaño y la profundidad exacta de la úlcera", "Tinciones corneales con gotas de fluoresceína (un tinte amarillo-naranja) que se ilumina con luz azul, resaltando el daño de la superficie corneal brillante y claramente", "Raspado corneal (cultivo): El médico raspa suavemente la base de la úlcera con una espátula minúscula para recolectar tejido e identificar exactamente qué bacteria, hongo o virus está causando el problema", "Exámenes para evaluar si la infección ha penetrado a la cámara anterior del ojo, causando inflamación interna profunda (hipopión)"], note: "El cultivo es vital, ya que el tratamiento con el antibiótico o antifúngico incorrecto empeorará la situación." }, treatment: { title: "Tratamientos Oftalmológicos de Emergencia", intro: "El manejo debe ser intenso y disciplinado desde el primer momento:", subsections: [ { title: "Enfoques terapéuticos tópicos e invasivos", items: ["Gotas oftálmicas de antibióticos, antifúngicos o antivirales fortificadas (de alta concentración) aplicadas con extrema frecuencia, inicialmente cada 15 a 30 minutos de día y de noche, reduciéndolas a medida que la úlcera sana", "Gotas ciclopléjicas dilatorias (como la atropina) para paralizar el músculo del ojo, aliviar el intenso dolor de los espasmos y prevenir complicaciones internas", "Pastillas para el dolor (analgésicos orales)", "Importante: NO se deben prescribir gotas o pomadas con corticosteroides en la fase inicial de una úlcera infecciosa, ya que acelerarán drásticamente el daño del tejido corneal", "Tratamientos quirúrgicos: En casos extremos donde la córnea está a punto de perforarse (romperse) o la cicatriz resultante bloquea la visión central, el único tratamiento definitivo es un trasplante de córnea (queratoplastia)"] } ], note: "Nunca use un parche ocular en un ojo con una úlcera bacteriana, ya que esto crea un ambiente oscuro y cálido que favorece el crecimiento bacteriano explosivo." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Médico Especialista?", intro: "Considere esto como una emergencia oftalmológica. Busque a un oftalmólogo (no a un optómetra ni un médico general) u hospital si:", items: ["Su ojo se vuelve intensamente rojo, doloroso y extremadamente sensible a la luz en cuestión de horas", "Nota una mancha blanca o grisácea en la parte transparente de su ojo", "Es usuario de lentes de contacto y presenta cualquier molestia aguda persistente, visión nublada o secreción ocular espesa", "Ha sufrido un rasguño, un traumatismo en el ojo o un cuerpo extraño le ha entrado y el dolor no mejora"] } },
'Cervicitis' : { intro: "La cervicitis es una inflamación e irritación común del cuello uterino (el extremo inferior del útero que se abre hacia la vagina). Aunque a menudo no presenta síntomas y pasa desapercibida, si se deja sin tratar, las infecciones que la causan pueden propagarse hacia el útero o las trompas de Falopio y comprometer gravemente la fertilidad futura.", whatIs: { title: "¿Qué es la Cervicitis?", text: "Es la inflamación del tejido del cérvix o cuello uterino. Es el equivalente femenino de la uretritis en los hombres. Generalmente es la respuesta del cuerpo a una infección transmitida sexualmente, pero también puede ser provocada por irritaciones químicas o lesiones físicas." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "La mayoría de las mujeres (hasta un 50%) son asintomáticas. Sin embargo, cuando se presentan síntomas, los más comunes son:", groups: [ { name: "Secreciones y Sangrado", items: ["Flujo vaginal inusual, anormal y persistente (puede ser abundante, de color amarillo, verde pálido o tener aspecto similar al pus)", "Sangrado vaginal anormal fuera del período menstrual", "Sangrado o manchado leve después de tener relaciones sexuales (síntoma muy característico y motivo de alerta)", "Sangrado o manchado leve después de un examen pélvico o examen de Papanicolaou"] }, { name: "Molestias pélvicas y urinarias", items: ["Dolor o molestia en la parte baja del abdomen o en la región pélvica", "Dolor profundo durante el coito (dispareunia)", "Sensación de ardor, dolor, irritación o aumento de la frecuencia al orinar", "El cuello uterino se vuelve friable (enrojecido, inflamado y sangra muy fácilmente al tocarlo con un hisopo médico)"] } ], warning: "Si el flujo anormal se acompaña de fiebre, náuseas o un dolor abdominal pélvico repentino y severo, podría indicar Enfermedad Pélvica Inflamatoria (EPI), requiriendo atención médica urgente." }, types: { title: "Tipos y Orígenes de la Afección", intro: "Se divide principalmente en dos grandes categorías, dependiendo de su causa raíz:", items: ["Cervicitis Infecciosa (aguda): Causada abrumadoramente por bacterias u otros microorganismos de transmisión sexual. Requiere tratamiento con antibióticos.", "Cervicitis No Infecciosa (crónica): Causada por factores ambientales, reacciones alérgicas o traumatismos físicos en la zona vaginal. No mejora con antibióticos."], note: "Identificar la bacteria exacta es fundamental, ya que tratar un tipo con la medicina equivocada no curará la inflamación." }, causes: { title: "Causas, Patógenos y Factores de Riesgo", intro: "Las infecciones de transmisión sexual son la causa número uno de esta patología:", items: ["Infecciones bacterianas de transmisión sexual (ITS): La clamidia y la gonorrea son responsables de la gran mayoría de los casos.", "Infecciones virales y parasitarias: Virus del herpes simple genital (VHS-2), Tricomoniasis (parásito), o el virus del papiloma humano (VPH).", "Otras infecciones vaginales: Proliferación de bacterias normales de la vagina (vaginosis bacteriana) o infecciones por micoplasmas (Mycoplasma genitalium).", "Causas no infecciosas y reacciones alérgicas: Reacción a los espermicidas, al látex de los condones, duchas vaginales frecuentes, jabones perfumados agresivos, o cuerpos extraños olvidados (como un tampón o un capuchón cervical).", "Factores de riesgo: Múltiples parejas sexuales, sexo sin protección (sin preservativo), o tener antecedentes previos de ITS."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un ginecólogo o médico de atención primaria diagnostica la afección durante un examen pélvico mediante:", items: ["Visualización clínica: El médico usa un espéculo para ver directamente si el cuello uterino está rojo, hinchado, y si hay pus amarillo o verde saliendo del canal cervical", "Prueba de friabilidad del cuello uterino: Al tocarlo suavemente con un hisopo de algodón, el cuello sangra de manera inusual", "Toma de muestras y cultivos (exudado endocervical o vaginal) para buscar el ADN específico de Clamidia, Gonorrea o Tricomoniasis", "Pruebas de Papanicolaou para examinar la presencia de células inflamadas o anormales asociadas al VPH", "Análisis microscópico de laboratorio (montaje húmedo) del flujo vaginal en el mismo consultorio"], note: "Debido a la alta tasa de casos asintomáticos, las pruebas de detección de clamidia y gonorrea anuales son recomendadas en mujeres jóvenes sexualmente activas." }, treatment: { title: "Enfoque de Tratamiento y Curación", intro: "El objetivo del tratamiento médico es erradicar la infección y prevenir el daño permanente a los órganos reproductivos:", subsections: [ { title: "Intervenciones farmacológicas y cuidado", items: ["Antibióticos recetados: El pilar del tratamiento infeccioso. Si se sospecha fuertemente de una ITS, el médico iniciará antibióticos de amplio espectro incluso antes de que lleguen los resultados del cultivo (generalmente pastillas orales, o una inyección intramuscular para la gonorrea).", "Antivirales o antiparasitarios, si se identifica herpes o tricomoniasis.", "Tratamiento obligatorio para la pareja sexual: Para prevenir la reinfección recurrente ('ping-pong'), las parejas deben ser tratadas simultáneamente con antibióticos, incluso si no presentan síntomas masculinos evidentes.", "Abstinencia temporal: Evitar todas las relaciones sexuales hasta que tanto la paciente como su(s) pareja(s) hayan completado todos los días del medicamento.", "Suspensión de agentes irritantes (duchas vaginales, jabones íntimos) si el diagnóstico es cervicitis no infecciosa."] } ], note: "Si el tratamiento falla o la cervicitis es crónica, el médico puede evaluar procedimientos de criocirugía (congelación) o terapia láser para eliminar el tejido inflamado." }, whenToSeekHelp: { title: "¿Cuándo Ir al Médico o al Ginecólogo?", intro: "Es fundamental programar una revisión médica ginecológica sin demora si usted experimenta:", items: ["Un flujo o secreción vaginal constante, de color o textura inusual y mal olor persistente", "Sangrado vaginal o manchado de sangre inexplicable entre períodos o inmediatamente después de tener relaciones sexuales", "Dolor pélvico profundo e inusual durante el acto sexual que antes no ocurría", "Desea hacerse pruebas de detección de ITS si ha tenido relaciones de riesgo y le preocupa tener una infección asintomática"] } },
'Flebitis' : { intro: "La flebitis es la inflamación de una vena. Es una afección vascular común que causa dolor, endurecimiento y enrojecimiento localizado. A menudo se combina con la formación de un coágulo de sangre (tromboflebitis), variando de un problema superficial menor a una urgencia médica grave si afecta las venas profundas de la pierna.", whatIs: { title: "¿Qué es la Flebitis y Tromboflebitis?", text: "La flebitis simplemente significa inflamación de las paredes de una vena. Cuando esta inflamación se debe o resulta en la formación de un trombo (un coágulo de sangre) adherido a la pared interna de la vena, se denomina tromboflebitis. Afecta predominantemente a las venas de las piernas o los brazos." }, symptoms: { title: "Síntomas Visuales y Físicos", intro: "Los síntomas tienden a aparecer rápidamente en un área muy localizada alrededor de la vena afectada:", groups: [ { name: "Síntomas en Flebitis Superficial", items: ["Enrojecimiento intenso (eritema) de la piel a lo largo del trayecto de la vena inflamada", "Hinchazón visible y sensación de calor irradiado al tacto sobre la vena", "La vena inflamada se palpa como un cordón duro, rígido o nudoso bajo la piel (ya no es blanda ni comprimible)", "Dolor sordo, palpitante, picazón severa y sensibilidad al presionar o mover la extremidad afectada"] }, { name: "Síntomas en Flebitis Profunda (TVP)", items: ["Hinchazón global de toda la pierna o el brazo, no solo una zona localizada", "Dolor profundo, calambres o sensación de pesadez intensa en la pantorrilla o el muslo", "Puede no presentar enrojecimiento obvio y la vena en sí no se palpa dura bajo la piel, pero la pantorrilla está tensa", "Falta de aire o dolor agudo en el pecho (Si el coágulo profundo se desprende y viaja a los pulmones, provocando Embolia Pulmonar)"] } ], warning: "Si la hinchazón dolorosa de la pierna se acompaña súbitamente de dificultad para respirar o tos con sangre, busque ayuda de emergencia al instante." }, types: { title: "Tipos de Flebitis según su Profundidad", intro: "Es vital diferenciar entre los dos tipos debido al nivel de peligro:", items: ["Tromboflebitis Venosa Superficial: Ocurre en las venas que están justo debajo de la piel (venas varicosas). Generalmente es benigna, dolorosa pero no pone en peligro la vida porque los coágulos rara vez se desprenden hacia el pulmón.", "Tromboflebitis Venosa Profunda (TVP): Ocurre en el sistema venoso principal profundo entre los músculos de la pierna. Es una condición de alto riesgo, ya que un coágulo grande puede desprenderse fácilmente hacia órganos vitales."], note: "Ocasionalmente, una flebitis superficial grave e ignorada puede extenderse hasta penetrar en el sistema venoso profundo." }, causes: { title: "Causas y Factores de Riesgo", intro: "La inflamación venosa se desencadena por traumatismos locales o flujo sanguíneo ralentizado:", items: ["Trauma local directo: La causa más común de flebitis superficial en el brazo es la irritación causada por catéteres intravenosos (IV) en los hospitales o por inyecciones repetidas.", "Inmovilidad prolongada: Viajes largos en avión, reposo absoluto en cama o inmovilización tras una cirugía o fractura causan estasis sanguínea (la sangre no circula).", "Venas varicosas crónicas preexistentes (conducen al estancamiento de la sangre en las piernas).", "Cirugías mayores, traumas físicos y lesiones en las piernas.", "Estados de hipercoagulabilidad: Cáncer, embarazo, uso de terapia de reemplazo hormonal o píldoras anticonceptivas, o trastornos genéticos de la coagulación.", "Fumar cigarrillos y la obesidad aumentan sustancialmente el riesgo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico depende de descartar la flebitis profunda (TVP) en las piernas mediante:", items: ["Examen físico clínico: El médico buscará el enrojecimiento superficial, calor y palpará la dureza del 'cordón' venoso.", "Ecografía Doppler (Ultrasonido venoso): Es la prueba diagnóstica estándar y de oro; visualiza directamente el flujo de sangre en las venas y localiza la presencia, tamaño y ubicación exacta de los coágulos de sangre (especialmente para confirmar o descartar una TVP profunda).", "Análisis de sangre para el Dímero D: Una prueba que detecta trozos de coágulos de sangre en degradación (un nivel alto sugiere problemas de coagulación).", "Cultivo de sangre o de las vías intravenosas, si el médico sospecha que la causa original es una infección bacteriana de la vena (flebitis infecciosa)."], note: "Casi toda sospecha de flebitis en las extremidades inferiores requerirá una ecografía Doppler." }, treatment: { title: "Opciones Terapéuticas", intro: "El tratamiento difiere radicalmente si la flebitis es superficial o profunda:", subsections: [ { title: "Para Flebitis Superficial", items: ["Reposo con elevación periódica de la extremidad afectada para reducir la hinchazón", "Compresas o paños tibios sobre el área enrojecida", "Antiinflamatorios no esteroideos orales (como ibuprofeno o diclofenaco) para aliviar el dolor intenso y la inflamación aguda de la vena", "Uso de medias de compresión graduada firmes", "A menudo se resuelve por completo con cuidados caseros en pocas semanas."] }, { title: "Para Tromboflebitis Profunda", items: ["Anticoagulantes recetados ('diluyentes de sangre' como warfarina, heparina, rivaroxabán) durante meses para evitar que el coágulo crezca y prevenir su migración a los pulmones", "Trombolíticos (fármacos disolventes de coágulos fuertes) o inserción de un filtro en la vena cava en casos de alto riesgo en hospitales"] } ], note: "La flebitis en el brazo tras una inyección requiere retirar el catéter IV de inmediato." }, whenToSeekHelp: { title: "¿Cuándo Buscar Atención Médica?", intro: "Acuda al médico o a emergencias de forma prioritaria si:", items: ["Desarrolla hinchazón grave, dolor repentino y enrojecimiento en una pierna o brazo", "Los síntomas de una flebitis superficial empeoran progresivamente, se vuelven muy calientes o provocan fiebre", "Tiene factores de riesgo (como inmovilidad, embarazo o cáncer) y nota pesadez y calambres inusuales en la pantorrilla", "Experimenta dificultad repentina para respirar o tos inexplicada (signo de embolia pulmonar)"] } },
'Crisis respiratoria en recién nacidos' : { intro: "La crisis respiratoria en el período neonatal agrupa múltiples condiciones que dificultan la transición del bebé a la respiración fuera del útero. Es la causa más frecuente de ingreso de recién nacidos a las unidades de cuidados intensivos, requiriendo reanimación experta y soporte de oxígeno inmediato para proteger su cerebro en desarrollo.", whatIs: { title: "¿Qué es la Dificultad o Crisis Respiratoria Neonatal?", text: "Es cualquier afección que impide a un bebé recién nacido oxigenar su sangre adecuadamente inmediatamente o poco después del parto. Ocurre cuando los pulmones no logran adaptarse al ambiente lleno de aire debido a inmadurez, obstrucción o inflamación." }, symptoms: { title: "Signos Vitales y Respiratorios de Alerta", intro: "Los signos clínicos de esfuerzo y fallo respiratorio en el recién nacido son muy visuales y alarmantes:", groups: [ { name: "Trabajo y esfuerzo respiratorio", items: ["Respiración muy rápida (taquipnea, más de 60 respiraciones por minuto sostenidas)", "Quejido expiratorio (un sonido ronco, audible como un gemido en cada exhalación, ya que el bebé intenta mantener los pulmones abiertos)", "Aleteo nasal continuo (las fosas nasales se abren exageradamente para intentar succionar más aire)", "Retracciones o tiraje (la piel y músculos se hunden entre las costillas, debajo del esternón o en el cuello con cada inhalación)"] }, { name: "Signos de hipoxia (Bajo oxígeno)", items: ["Coloración azul oscuro o grisácea (cianosis) persistente en los labios, lengua, cara y el cuerpo central (la acrocianosis, o manos/pies azules, es normal temporalmente en bebés sanos)", "Letargo profundo, flacidez (bajo tono muscular) o incapacidad total para llorar", "Pausas prolongadas en la respiración de más de 20 segundos (apnea) o ritmo cardíaco lento (bradicardia)"] } ], warning: "La asfixia perinatal severa (falta de oxígeno antes o durante el parto) puede causar un daño neurológico irreversible en minutos si el bebé no es reanimado con presión positiva." }, types: { title: "Principales Causas Clínicas", intro: "Existen diferentes diagnósticos médicos específicos para esta crisis:", items: ["Taquipnea Transitoria del Recién Nacido (TTRN): Ocurre frecuentemente en partos por cesárea; el líquido pulmonar no se elimina lo suficientemente rápido. Suele ser benigna y se resuelve en unos días.", "Síndrome de Dificultad Respiratoria (SDR o enfermedad de membrana hialina): Clásico en bebés prematuros; los pulmones colapsan porque carecen de surfactante.", "Síndrome de Aspiración de Meconio (SAM): Un bebé a término u post-término que sufre estrés en el útero inhala meconio (sus primeras heces) hacia los pulmones, provocando inflamación química severa e infección.", "Neumonía congénita o sepsis temprana: Infecciones adquiridas en el canal de parto (como Streptococcus del grupo B).", "Anomalías congénitas: Hernia diafragmática (órganos abdominales en el tórax) o problemas cardíacos graves."], note: "El historial de nacimiento (prematuro vs. cesárea a término vs. parto con meconio) guía el diagnóstico inicial." }, causes: { title: "Factores de Riesgo en el Embarazo y Parto", intro: "El riesgo de problemas respiratorios neonatales se incrementa en embarazos con:", items: ["Parto prematuro (la causa más grave de falta de madurez pulmonar)", "Diabetes materna o hipertensión no controlada en la madre", "Parto por cesárea sin que haya existido trabajo de parto previo (reduce la expulsión natural de líquido de los pulmones del bebé)", "Sufrimiento fetal crónico que lleva a la expulsión de meconio en el saco amniótico", "Infecciones maternas (como la corioamnionitis)", "Anomalías estructurales del feto o partos múltiples (gemelos, trillizos)"] }, diagnosis: { title: "¿Cómo se Diagnostica y Evalúa?", intro: "En la sala de partos o la UCIN (Unidad de Cuidados Intensivos Neonatales), el neonatólogo utilizará:", items: ["Puntuación de Apgar, evaluando color, esfuerzo respiratorio, tono, reflejos y frecuencia cardíaca en el minuto 1 y 5", "Oximetría de pulso o gasometría arterial para medir de inmediato los niveles bajos de oxígeno y la acumulación de dióxido de carbono en la sangre del cordón o del bebé", "Radiografía de tórax frontal (fundamental para confirmar TTRN, SDR, neumonía, o visualizar si el bebé aspiró meconio)", "Ecocardiograma rápido en caso de que los pulmones estén claros pero el bebé siga azul, indicando un probable defecto cardíaco congénito o hipertensión pulmonar", "Cultivos de sangre y punción lumbar si hay sospecha de infección neonatal temprana"], note: "El examen físico, especialmente escuchar los pulmones del bebé (sibilancias vs asimetría de aire), es el paso más rápido." }, treatment: { title: "Soporte Vital y Atención en UCIN", intro: "El bebé requiere intervención respiratoria inmediata según la severidad:", subsections: [ { title: "Tratamientos principales", items: ["Suministro de oxígeno suplementario continuo y caldeado a través de una campana u cánula nasal", "CPAP Nasal (Presión Positiva Continua en las Vías Respiratorias): Máscara con presión de aire constante para evitar que los frágiles sacos pulmonares colapsen entre respiraciones", "Intubación endotraqueal y ventilación mecánica completa (para soporte vital en casos de falla respiratoria inminente o apneas)", "Administración de Surfactante exógeno directo a los pulmones (salva vidas en bebés muy prematuros con SDR)", "Antibióticos intravenosos empíricos amplios en caso de aspiración de meconio o sospecha de neumonía/sepsis", "Nutrición intravenosa y monitoreo meticuloso del pH sanguíneo y glucosa hasta que el bebé pueda respirar y comer por sí solo"] } ], note: "La gran mayoría de los bebés a término con dificultad leve mejoran rápidamente en pocos días con asistencia mínima." }, whenToSeekHelp: { title: "¿Qué Debe Esperar la Familia?", intro: "Si usted acaba de dar a luz y nota que su bebé no está bien:", items: ["Informe a la enfermera inmediatamente si, una vez en su habitación, el bebé respira muy rápido de forma continua, gruñe o la piel a su alrededor se hunde al respirar", "Acuda al área de emergencias si su bebé es dado de alta pero luego se vuelve flácido, letárgico, rechaza la alimentación severamente o sus labios se vuelven azulados", "Los bebés en la UCIN están altamente monitoreados, pero es importante que los padres pregunten a los médicos sobre el soporte que está requiriendo"] } },
'Fimosis' : { intro: "La fimosis es una afección común del pene no circuncidado en la que el prepucio es demasiado estrecho para retraerse y exponer el glande. Aunque suele ser completamente normal y fisiológica en bebés y niños pequeños, puede requerir atención médica si persiste en la adolescencia o causa infecciones dolorosas y problemas urinarios.", whatIs: { title: "¿Qué es la Fimosis?", text: "Es la incapacidad de retraer (deslizar hacia atrás) completamente el prepucio sobre la cabeza del pene (el glande). Esta estrechez impide una adecuada higiene del área subprepucial y, en algunos casos, puede obstruir el flujo normal de la orina." }, symptoms: { title: "Síntomas y Señales", intro: "La mayoría de las veces no causa molestias en la infancia, pero puede tornarse sintomática:", groups: [ { name: "Síntomas obstructivos y funcionales", items: ["Imposibilidad o gran dificultad para retraer el prepucio sin forzarlo", "El prepucio se abomba, se hincha o 'hace un globo' al orinar (la orina llena el saco del prepucio antes de salir con dificultad)", "Chorro de orina muy débil o delgado, o dolor al orinar (disuria)", "Dificultad, dolor o tirantez intensa durante las erecciones o la actividad sexual en adolescentes y adultos"] }, { name: "Síntomas de complicaciones (Infecciones)", items: ["Enrojecimiento, hinchazón aguda, picazón y dolor intenso en la punta del pene y el prepucio (Balanopostitis)", "Acumulación frecuente de esmegma espeso bajo el prepucio que se infecta y produce secreción de pus o mal olor", "Sangrado leve del prepucio debido a desgarros por intentar retraer la piel apretada a la fuerza"] } ], warning: "La 'Parafimosis' (si el prepucio apretado se retrae y queda atrapado detrás de la cabeza del pene estrangulándolo) es una emergencia médica dolorosa urgente." }, types: { title: "Clasificación por Origen", intro: "La condición se divide médicamente en dos categorías esenciales:", items: ["Fimosis Fisiológica: Es la forma natural; casi todos los niños nacen con un prepucio apretado y pegado al glande. A medida que el niño crece, tiene erecciones naturales y se baña, la piel se afloja y se separa por sí sola (generalmente antes de los 5 a 7 años).", "Fimosis Patológica (Adquirida o Cicatricial): Ocurre cuando un prepucio previamente retráctil se vuelve estrecho y rígido. Es el resultado de cicatrices, inflamación crónica, o afecciones de la piel (Liquen escleroso), y requiere tratamiento definitivo."], note: "Los médicos enfatizan nunca retraer o jalar a la fuerza el prepucio de un bebé sano, ya que causa micro-rasgaduras que llevan a la verdadera fimosis patológica cicatricial." }, causes: { title: "Causas y Factores Desencadenantes", intro: "Mientras la fisiológica es normal, el anillo estrecho patológico se desarrolla por:", items: ["Forzar prematuramente la retracción del prepucio en niños pequeños (mala práctica común que crea tejido cicatricial inelástico)", "Infecciones repetidas del prepucio y del glande (balanopostitis) o higiene muy deficiente debajo de la piel", "Balanitis xerótica obliterante (liquen escleroso), una condición crónica inflamatoria de la piel que crea un anillo blanco endurecido y cicatricial en la punta del prepucio", "Cateterismo uretral traumático", "La diabetes no controlada en adultos a menudo promueve infecciones por hongos que llevan a la inflamación del prepucio y su endurecimiento"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un pediatra, urólogo general o urólogo pediatra diagnostica el problema mediante:", items: ["Evaluación clínica visual y examen físico del pene (el médico intentará evaluar la retracción con extrema suavidad)", "Evaluación de la presencia del 'anillo fibroso blanco' tenso en el extremo del prepucio, indicativo de fimosis patológica y cicatricial", "Preguntas sobre el historial de infecciones urinarias, infecciones repetidas del glande, dolor con las erecciones o si alguna vez se forzó la piel del niño"], note: "Rara vez se necesitan otras pruebas, a menos que existan infecciones concurrentes que requieran cultivo de orina." }, treatment: { title: "Enfoque Terapéutico y Quirúrgico", intro: "El tratamiento va desde estiramientos hasta cirugía curativa, evitando soluciones forzadas:", subsections: [ { title: "Opciones de intervención", items: ["Observación y paciencia (para la fimosis fisiológica en niños preescolares sin síntomas ni infecciones; instruir buena higiene suave sin forzar)", "Cremas con corticosteroides tópicos (betametasona o hidrocortisona): Aplicadas en la punta del prepucio durante 4 a 6 semanas junto con estiramientos suaves diarios en la bañera, tienen una altísima tasa de éxito para adelgazar y aflojar el anillo estrecho.", "Tratamiento de infecciones con cremas antifúngicas o antibióticas.", "Prepucioplastia quirúrgica o dorsal slit: Una pequeña incisión longitudinal en la banda estrecha del prepucio para ensancharlo, conservando el prepucio general.", "Circuncisión total quirúrgica: Extirpación completa del prepucio, la cura definitiva para los casos de fimosis cicatricial patológica, infecciones graves persistentes (liquen escleroso) o cuando las cremas y la dilatación fallan."] } ], note: "La aplicación diligente y correcta de cremas esteroides prescritas evita la necesidad de circuncisión en una vasta mayoría de niños." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico?", intro: "Es prudente programar una revisión médica pediátrica o urológica si:", items: ["Su hijo tiene más de 7-10 años de edad, o entra en la pubertad, y el prepucio aún está inmovible o muy apretado", "Observa enrojecimiento pronunciado crónico, inflamación masiva, dolor al intentar orinar, o sangrado alrededor del prepucio", "El niño experimenta globo prepucial marcado donde solo caen gotas al intentar orinar", "El prepucio está atascado e hinchado dolorosamente detrás de la cabeza del pene, y no puede devolverlo a su posición original (Emergencia - Parafimosis)"] } },
'Bursitis retrocalcánea' : { intro: "La bursitis retrocalcánea es una inflamación molesta y dolorosa que ocurre en la parte posterior del talón. Es una lesión por sobreuso sumamente común entre corredores y atletas, y a menudo ocurre de manera simultánea con problemas en el tendón de Aquiles, dificultando significativamente caminar o usar zapatos cerrados.", whatIs: { title: "¿Qué es la Bursitis retrocalcánea?", text: "Es la inflamación e hinchazón aguda de la bursa retrocalcánea, un pequeño saco lleno de líquido lubricante ubicado en la parte posterior del talón, exactamente entre el hueso del talón (calcáneo) y la inserción del fuerte tendón de Aquiles. Su función es evitar que el tendón roce con el hueso." }, symptoms: { title: "Síntomas de Dolor e Inflamación", intro: "El dolor generalmente se desarrolla de manera gradual e incluye:", groups: [ { name: "Molestias en la zona del talón", items: ["Dolor severo y sordo en la parte posterior del talón, especialmente cuando se presiona la parte posterior del tobillo o al estar de puntillas", "El dolor empeora drásticamente al levantarse de la cama y dar los primeros pasos por la mañana (o después de estar mucho tiempo sentado)", "Dolor que se agrava al correr, saltar, caminar cuesta arriba o usar zapatos con parte trasera rígida", "Mejora parcial o reducción del dolor cuando se camina descalzo o con sandalias abiertas por detrás"] }, { name: "Signos físicos visibles", items: ["Hinchazón esponjosa, bulto o enrojecimiento visible y sensible al tacto en la parte de atrás del talón, justo por encima del zapato", "La piel puede sentirse más caliente de lo normal", "Rigidez extrema en la parte inferior de la pantorrilla y el tendón"] } ], warning: "Si la hinchazón es muy repentina, extremadamente dolorosa al más mínimo toque y la piel está brillante y muy roja, el médico debe descartar una infección de la bursa." }, types: { title: "Asociaciones Clínicas (Síndrome de Haglund)", intro: "La afección a menudo está estructuralmente ligada a otra condición ósea:", items: ["Enfermedad o Síndrome de Haglund (la 'bomba de Haglund'): Muchas personas con esta bursitis tienen un crecimiento óseo extra (espolón o protuberancia prominente) en la parte superior posterior del hueso del talón. Este espolón roza físicamente contra la bursa y el tendón continuamente, causando inflamación crónica y repetitiva (deformidad de Haglund).", "Tendinopatía de Aquiles concurrente: Frecuentemente, tanto el tendón como la bursa están inflamados al mismo tiempo."], note: "El calzado rígido que frota constantemente esta área promueve tanto la bursitis como la formación ósea reactiva de Haglund." }, causes: { title: "Causas y Factores Estresantes Biomecánicos", intro: "El problema subyacente es la fricción excesiva repetida en la zona del tendón:", items: ["Sobrecarga atlética: Aumentar repentinamente la distancia, velocidad o intensidad del entrenamiento (especialmente correr en colinas o superficies duras)", "Uso de zapatos inapropiados: Zapatos demasiado apretados, rígidos o que frotan el talón trasero vigorosamente (común con botas, patines de hielo o zapatos de vestir de tacón alto, por eso se llama la 'protuberancia del zapato de tacón')", "Falta de flexibilidad severa en los músculos de la pantorrilla y el tendón de Aquiles, lo que tensa el tendón contra la bursa", "Anomalías biomecánicas del pie, como exceso de pronación (pie plano), que altera el ángulo del talón al caminar", "Enfermedades inflamatorias sistémicas subyacentes (artritis reumatoide, gota o artritis psoriásica) pueden causarla raramente sin un factor atlético evidente"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un podólogo, ortopedista o especialista en medicina deportiva realiza la evaluación:", items: ["Examen físico clínico minucioso, apretando el área entre el tendón y el hueso del talón; el dolor a la palpación en los bordes laterales y mediales de la inserción de Aquiles sugiere fuertemente esta bursitis.", "Evaluación de la marcha y revisión del desgaste del calzado o la presencia de una protuberancia ósea dura subyacente (deformidad de Haglund).", "Radiografías (Rayos X) del tobillo, vitales para detectar si existe el espolón óseo o deformidad en el hueso del talón que esté causando físicamente el roce.", "Ecografía o Resonancia magnética (RM) del pie (la forma ideal para visualizar el tamaño exacto de la bursa inflamada llena de líquido y confirmar si hay desgarros menores en el tendón de Aquiles adyacente)."], note: "Distinguir esto de la simple tendinitis de Aquiles es importante, ya que una inyección de esteroides en el lugar equivocado (en el tendón) puede causar una ruptura del mismo." }, treatment: { title: "Rehabilitación y Prevención", intro: "El manejo es casi siempre conservador en etapas tempranas:", subsections: [ { title: "Enfoques terapéuticos no quirúrgicos", items: ["Descanso inmediato de las actividades de alto impacto, aplicando el protocolo RICE (Reposo, Hielo frecuente, Compresión y Elevación)", "Uso de calzado con respaldo suave (abierto atrás), o colocar taloneras o plantillas en el zapato para elevar el talón, reduciendo la presión y tensión en la parte posterior", "Uso de medicamentos antiinflamatorios (AINEs) orales", "Fisioterapia intensiva, centrada en estiramientos profundos de la pantorrilla y el tendón de Aquiles, y terapia con ultrasonido", "Inyecciones de corticosteroides guiadas por ecografía directamente dentro de la bursa (muy útiles, pero administradas con gran precaución por especialistas para evitar bañar el tendón de Aquiles, lo que aumenta el riesgo de rotura)"] }, { title: "Cirugía", items: ["Si fallan todos los métodos durante meses, el cirujano puede extirpar la bursa inflamada (bursectomía) y rasurar quirúrgicamente el espolón óseo de Haglund para eliminar la fuente de fricción para siempre."] } ], note: "Hacer estiramientos adecuados de la pantorrilla antes y después del ejercicio previene drásticamente la recurrencia." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Podólogo u Ortopedista?", intro: "Es altamente recomendable que busque atención médica especializada si:", items: ["El dolor de talón ha persistido durante más de una a dos semanas a pesar de descansar y aplicar hielo", "Desarrolla una protuberancia visible, sensible y enrojecida en la parte superior posterior de su talón", "Experimenta un 'chasquido', estallido repentino o debilidad aguda e incapacidad de levantar el pie del suelo (vaya inmediatamente al médico, ya que esto indica una rotura grave del tendón de Aquiles)"] } },
'Osteoporosis por Climaterio' : { intro: "La osteoporosis por climaterio, o posmenopáusica, es una condición silenciosa que debilita los huesos tras la menopausia. La caída drástica de estrógenos acelera la pérdida de densidad ósea, aumentando significativamente el riesgo de fracturas graves ante caídas menores.", whatIs: { title: "¿Qué es la Osteoporosis Posmenopáusica?", text: "Es una enfermedad metabólica ósea que ocurre en mujeres durante y después del climaterio (menopausia). Se caracteriza por una disminución de la masa ósea y el deterioro de la estructura del hueso, volviéndolo poroso, frágil y altamente susceptible a fracturas." }, symptoms: { title: "Síntomas y Señales", intro: "A menudo se le llama la 'enfermedad silenciosa' porque no presenta síntomas hasta que un hueso se rompe, pero puede manifestar:", groups: [ { name: "Signos estructurales progresivos", items: ["Pérdida de estatura con el tiempo (hasta varios centímetros)", "Postura encorvada o desarrollo de una joroba en la parte superior de la espalda (cifosis)", "Dolor de espalda severo o crónico, a menudo causado por una vértebra colapsada o fracturada", "Huesos que se fracturan con mucha más facilidad de lo esperado (frecuentemente en muñecas, caderas o columna)"] } ], warning: "Una fractura de cadera en una mujer mayor es una emergencia médica grave que puede comprometer permanentemente su movilidad e independencia." }, types: { title: "Factores Aceleradores", intro: "La velocidad de pérdida ósea puede verse agravada por:", items: ["Menopausia precoz (antes de los 45 años) o extirpación quirúrgica de los ovarios", "Bajo peso corporal o índice de masa corporal (IMC) muy bajo", "Estilo de vida sedentario y tabaquismo", "Uso prolongado de ciertos medicamentos (como corticosteroides)"], note: "Las mujeres pueden perder hasta el 20% de su densidad ósea en los primeros 5 a 7 años después de la menopausia." }, causes: { title: "Causas y Biología", intro: "La raíz del problema es hormonal:", items: ["Falta de estrógeno: Esta hormona femenina es fundamental para proteger y mantener la fuerza de los huesos. Al llegar la menopausia, los ovarios dejan de producirla.", "Desequilibrio en la remodelación ósea: El cuerpo descompone el tejido óseo viejo más rápido de lo que puede crear tejido óseo nuevo.", "Deficiencia crónica de calcio y vitamina D a lo largo de la vida", "Antecedentes familiares de osteoporosis o fracturas de cadera"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico se realiza de forma rápida e indolora mediante:", items: ["Densitometría ósea (DEXA): La prueba estándar de oro. Es una radiografía de baja dosis que mide los minerales en los huesos, generalmente en la cadera y la columna", "Análisis de sangre y orina para evaluar los niveles de calcio, vitamina D y marcadores de formación o degradación ósea", "Evaluación de riesgo FRAX (un algoritmo que calcula la probabilidad de sufrir una fractura mayor en los próximos 10 años)"], note: "Se recomienda una densitometría basal para todas las mujeres a partir de los 65 años, o antes si tienen factores de riesgo." }, treatment: { title: "Opciones de Tratamiento y Prevención", intro: "El objetivo es detener la pérdida ósea y prevenir fracturas:", subsections: [ { title: "Medicamentos y estilo de vida", items: ["Bifosfonatos (alendronato, risedronato) para ralentizar la degradación ósea", "Terapia hormonal (estrógenos) o moduladores selectivos de los receptores de estrógenos (raloxifeno) en casos específicos y evaluando riesgos", "Terapias biológicas inyectables (denosumab) o formadores de hueso (teriparatida) para osteoporosis severa", "Suplementación obligatoria de Calcio y Vitamina D", "Ejercicios de soporte de peso y fortalecimiento muscular (caminar, pesas ligeras, yoga) para estimular la formación ósea y mejorar el equilibrio"] } ], note: "La prevención de caídas en el hogar (eliminar alfombras sueltas, buena iluminación) es tan importante como los medicamentos." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Ginecólogo o Endocrinólogo?", intro: "Busque evaluación médica si:", items: ["Está entrando en la menopausia o ha pasado por ella y desea evaluar su riesgo óseo", "Ha sufrido una fractura por un golpe leve o una caída desde su propia altura", "Nota que está perdiendo estatura o su postura se está encorvando", "Experimenta un dolor de espalda súbito e intenso sin motivo aparente"] } },
'Tristeza' : { intro: "La tristeza es una emoción humana natural y universal frente a la pérdida, la decepción o las dificultades. Sin embargo, cuando se vuelve profunda, persistente y comienza a interferir con la capacidad de funcionar en la vida diaria, puede ser un indicio de un trastorno del estado de ánimo que requiere apoyo profesional.", whatIs: { title: "¿Qué es la Tristeza vs. Depresión?", text: "La tristeza es una reacción emocional temporal a un evento estresante o doloroso. A diferencia de la depresión clínica, la tristeza suele presentarse en oleadas, a menudo vinculadas a pensamientos sobre una pérdida específica, y la persona aún puede disfrutar de ciertas actividades o consolarse." }, symptoms: { title: "Manifestaciones Comunes", intro: "Los signos de tristeza normal frente a problemas adaptativos incluyen:", groups: [ { name: "Síntomas emocionales y físicos", items: ["Sentimientos de vacío, llanto, o desánimo temporal", "Dificultad temporal para concentrarse o dormir bien tras un evento adverso", "Retraimiento social breve", "Sensación de fatiga o falta de energía"] }, { name: "Señales de alerta (Transición a Depresión)", items: ["La tristeza es constante, durando la mayor parte del día, casi todos los días durante más de dos semanas", "Pérdida total de interés o placer en actividades que antes se disfrutaban (anhedonia)", "Sentimientos de inutilidad extrema, culpa excesiva o pensamientos de muerte y suicidio"] } ], warning: "Si la tristeza se acompaña de pensamientos de hacerse daño o de que la vida no vale la pena, busque ayuda psicológica o psiquiátrica de emergencia inmediatamente." }, types: { title: "Contextos de la Tristeza", intro: "La tristeza puede manifestarse en diferentes contextos psicológicos:", items: ["Tristeza normal (reactiva): Respuesta saludable a eventos de la vida (rupturas, estrés laboral, decepciones).", "Duelo no complicado: Tristeza profunda tras la muerte de un ser querido; suele disminuir lentamente con el tiempo.", "Trastorno de adaptación con estado de ánimo deprimido: Reacción más intensa de lo esperado ante un factor estresante, afectando el funcionamiento.", "Trastorno Depresivo Mayor: Una enfermedad médica donde la tristeza es profunda, generalizada e incapacitante."], note: "Es completamente válido buscar apoyo terapéutico incluso para la tristeza normal o el duelo." }, causes: { title: "Desencadenantes Comunes", intro: "A diferencia de la depresión endógena, la tristeza suele tener una causa identificable:", items: ["Pérdida de un ser querido, mascota o una relación importante (duelo)", "Cambios drásticos de vida (mudanzas, pérdida de empleo, jubilación)", "Problemas de salud crónicos, dolor constante o diagnósticos médicos graves", "Conflictos familiares severos o aislamiento social prolongado", "Fluctuaciones hormonales (síndrome premenstrual, posparto, perimenopausia)"] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "Un psicólogo o psiquiatra evalúa la tristeza para determinar si es un síntoma de un trastorno mayor:", items: ["Entrevista clínica exhaustiva sobre la duración, intensidad y el impacto de los sentimientos en la vida diaria", "Uso de cuestionarios de detección de depresión (como el PHQ-9)", "Evaluación de antecedentes médicos y uso de medicamentos o sustancias que puedan alterar el estado de ánimo", "Diferenciación entre el duelo normal y el trastorno de duelo prolongado o depresión mayor"], note: "No hay pruebas de laboratorio para la tristeza, pero se pueden solicitar análisis para descartar problemas de tiroides que imitan la depresión." }, treatment: { title: "Manejo y Apoyo Emocional", intro: "El abordaje depende de si la tristeza es adaptativa o parte de un trastorno:", subsections: [ { title: "Estrategias de afrontamiento y terapia", items: ["Terapia psicológica (como la Terapia Cognitivo-Conductual) para procesar emociones, aprender estrategias de afrontamiento y reformular pensamientos negativos", "Grupos de apoyo emocional (muy efectivos para el duelo o enfermedades crónicas)", "Prácticas de autocuidado: Ejercicio regular (libera endorfinas), mantener rutinas de sueño estrictas y una dieta equilibrada", "Técnicas de mindfulness y meditación para reducir la reactividad emocional", "Medicamentos antidepresivos (solo si la evaluación médica determina que la tristeza ha evolucionado hacia un trastorno depresivo o de ansiedad)"] } ], note: "Permitirse sentir tristeza y expresarla (llorar, hablar con alguien de confianza) es fundamental para procesarla de manera saludable." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Contacte a un profesional de la salud mental si:", items: ["La tristeza dura más de dos semanas consecutivas y no parece aliviarse con el tiempo", "Interfiere seriamente con su capacidad para trabajar, estudiar, comer o dormir", "Empieza a recurrir al alcohol o a las drogas para intentar aliviar el dolor emocional", "Siente que la vida carece de sentido o ha tenido pensamientos de acabar con su vida"] } },
'Ronquido' : { intro: "El ronquido es un sonido áspero o ruidoso que se produce durante el sueño. Aunque suele ser motivo de bromas o quejas por parte de la pareja, los ronquidos fuertes y crónicos pueden ser el principal síntoma de la apnea obstructiva del sueño, una afección médica grave que requiere tratamiento.", whatIs: { title: "¿Qué es el Ronquido?", text: "Es el sonido vibratorio que se genera cuando el aire fluye por los tejidos relajados de la garganta mientras se respira durante el sueño. Esta relajación hace que las vías respiratorias se estrechen y vibren al paso del aire." }, symptoms: { title: "Síntomas y Señales Relacionadas", intro: "El ronquido en sí es el síntoma principal, pero a menudo se acompaña de:", groups: [ { name: "Indicadores de ronquido simple", items: ["Ruido respiratorio fuerte durante el sueño, a menudo empeorando al dormir boca arriba", "Boca seca o dolor de garganta al despertar", "Sueño inquieto o fragmentado"] }, { name: "Signos de alarma de Apnea del Sueño", items: ["Pausas observables en la respiración durante el sueño, seguidas de jadeos o asfixia repentina (a menudo notado por la pareja)", "Somnolencia diurna excesiva, fatiga extrema o dificultad para concentrarse en el trabajo", "Dolores de cabeza matutinos", "Presión arterial alta difícil de controlar"] } ], warning: "Si se despierta asfixiándose o jadeando por aire, es crucial descartar la apnea del sueño para prevenir riesgos cardíacos severos." }, types: { title: "Tipos y Gravedad", intro: "El ronquido varía en intensidad y frecuencia:", items: ["Ronquido ocasional: Ligero y poco frecuente, a menudo inducido por cansancio extremo, alcohol o resfriados. No es preocupante.", "Ronquido primario: Ronquido crónico y fuerte que no va acompañado de pausas respiratorias (apneas) ni afecta gravemente la calidad del sueño.", "Síndrome de Apnea Obstructiva del Sueño (SAOS): El ronquido se acompaña de bloqueos totales o parciales de las vías respiratorias, reduciendo los niveles de oxígeno en sangre."], note: "Más del 50% de las personas que roncan fuertemente de forma habitual padecen apnea obstructiva del sueño." }, causes: { title: "Causas y Factores de Riesgo", intro: "Cualquier condición que estreche las vías respiratorias puede causar ronquidos:", items: ["Anatomía de la boca y garganta (paladar blando bajo y grueso, amígdalas agrandadas, o úvula alargada)", "Sobrepeso u obesidad (el tejido graso adicional en el cuello presiona las vías respiratorias)", "Consumo de alcohol o sedantes antes de acostarse (relajan excesivamente los músculos de la garganta)", "Congestión nasal crónica, alergias o desviación del tabique nasal", "Dormir boca arriba (la gravedad hace que la lengua y el paladar blando colapsen hacia atrás)", "Edad (la garganta se vuelve más estrecha y el tono muscular disminuye al envejecer)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para determinar si el ronquido es peligroso, un médico o especialista en sueño realizará:", items: ["Evaluación de la historia clínica y cuestionarios sobre los hábitos de sueño (frecuentemente entrevistando a la pareja de cama)", "Examen físico del cuello, boca y garganta para buscar obstrucciones anatómicas", "Polisomnografía (estudio del sueño en laboratorio): La prueba definitiva que monitorea ondas cerebrales, oxígeno en sangre, frecuencia cardíaca y respiración durante toda la noche", "Estudio del sueño en el hogar (una versión simplificada del monitor que el paciente usa en su propia cama)"], note: "El estudio del sueño es indispensable para saber si hay episodios de asfixia o caída de oxígeno (apnea)." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento va desde cambios en el estilo de vida hasta dispositivos médicos o cirugía:", subsections: [ { title: "Medidas y dispositivos", items: ["Pérdida de peso significativa (a menudo es el tratamiento más efectivo)", "Dormir de lado en lugar de boca arriba (terapia posicional) y evitar el alcohol antes de dormir", "Dispositivos de avance mandibular (boquillas dentales hechas a medida) que empujan la mandíbula inferior hacia adelante para abrir la garganta", "Máquina CPAP (Presión Positiva Continua en las Vías Respiratorias) para quienes también tienen apnea del sueño; es una mascarilla que bombea aire para mantener la garganta abierta", "Tiras nasales o dilatadores externos para problemas leves de nariz", "Cirugía (como la Uvulopalatofaringoplastia - UPPP o cirugía nasal) para extirpar exceso de tejido o corregir tabiques desviados en casos donde otros métodos fallan"] } ], note: "Las almohadas o aerosoles 'antirronquidos' de venta libre rara vez proporcionan una cura real para los ronquidos severos." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico?", intro: "Debe buscar una evaluación médica si:", items: ["Sus ronquidos son tan fuertes que molestan el sueño de otras personas", "Su pareja nota que usted deja de respirar, jadea o se atraganta mientras duerme", "Se siente agotado, irritable o se queda dormido fácilmente durante el día", "Se despierta frecuentemente con dolor de cabeza o sensación de no haber descansado"] } },
'Dependencia emocional' : { intro: "La dependencia emocional es un patrón psicológico en el que una persona necesita excesivamente la aprobación, afecto y presencia de otra (generalmente su pareja) para sentirse segura o valiosa. Este apego extremo a menudo conduce a relaciones tóxicas, pérdida de identidad y profundo sufrimiento emocional.", whatIs: { title: "¿Qué es la Dependencia Emocional?", text: "Es un estado psicológico caracterizado por una vinculación afectiva excesiva e insana hacia otra persona. El individuo dependiente subordina sus propias necesidades, deseos y bienestar para mantener la relación a cualquier costo, operando desde un miedo intenso al abandono." }, symptoms: { title: "Síntomas y Comportamientos", intro: "Las señales de dependencia emocional son conductuales y cognitivas:", groups: [ { name: "Comportamientos en la relación", items: ["Miedo constante, irracional y paralizante al abandono o al rechazo", "Necesidad extrema de validación y aprobación constante de la pareja", "Renuncia a actividades, amigos, familiares o intereses propios para dedicar todo el tiempo a la relación", "Incapacidad para tomar decisiones por sí mismo sin el consejo o consentimiento del otro", "Tolerancia al abuso, la infidelidad o el maltrato con tal de no perder a la persona"] }, { name: "Síntomas emocionales internos", items: ["Ansiedad severa, pánico o sensación de vacío cuando la pareja no está presente o no responde de inmediato", "Baja autoestima; sentir que no se tiene valor sin la otra persona", "Celos patológicos y necesidad constante de controlar los movimientos del otro por inseguridad"] } ], warning: "La dependencia emocional extrema es el principal factor de riesgo para permanecer en situaciones de violencia de género o abuso doméstico." }, types: { title: "Patrones Relacionales Comunes", intro: "La dependencia suele manifestarse en dinámicas específicas:", items: ["Dependencia de pareja: La más común, donde el mundo gira exclusivamente en torno a la pareja romántica.", "Codependencia: Un patrón donde la persona se vuelve adicta a 'rescatar' o cuidar a una pareja con problemas (adicciones, inmadurez), sintiéndose útil solo a través del sacrificio.", "Dependencia familiar o filial: Necesidad extrema de la aprobación de los padres o hijos en la edad adulta.", "Búsqueda constante de relaciones (relaciones liana): Incapacidad de estar soltero; al terminar una relación, se busca inmediatamente otra para llenar el vacío."], note: "Los dependientes emocionales suelen sentirse atraídos inconscientemente por personas dominantes, narcisistas o emocionalmente indisponibles." }, causes: { title: "Causas y Raíces Psicológicas", intro: "Los orígenes suelen radicar en el desarrollo temprano y la autoestima:", items: ["Baja autoestima crónica y falta de confianza en el propio criterio", "Carencias afectivas o apego ansioso/inseguro desarrollado en la infancia (padres ausentes, sobreprotectores o impredecibles)", "Miedo profundo a la soledad (autofobia)", "Traumas pasados de abandono, rechazo o relaciones abusivas previas", "Creencias culturales o mitos sobre el 'amor romántico' (la idea de encontrar la 'media naranja' que complete la vida)"] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "No es un diagnóstico psiquiátrico oficial en sí mismo, pero los psicólogos lo evalúan mediante:", items: ["Entrevistas clínicas enfocadas en el historial de relaciones del paciente y sus patrones de ruptura", "Evaluación de la autoestima, la ansiedad por separación y el estilo de apego", "Uso de cuestionarios estructurados (como el Cuestionario de Dependencia Emocional CDE)", "Descartar o confirmar la presencia del Trastorno de la Personalidad Dependiente (un diagnóstico psiquiátrico más grave y generalizado)"], note: "El primer y más difícil paso del diagnóstico es que el paciente reconozca y acepte que tiene una adicción a la relación." }, treatment: { title: "Terapia y Recuperación", intro: "La recuperación es similar al tratamiento de una adicción, enfocándose en la reconstrucción del 'yo':", subsections: [ { title: "Abordajes Psicológicos", items: ["Psicoterapia individual (Terapia Cognitivo-Conductual o Terapia de Esquemas) para identificar y modificar patrones de pensamiento irracionales y miedos subyacentes", "Trabajo intensivo en la autoestima, la asertividad y la construcción de la propia identidad independiente", "Establecimiento de límites saludables ('Contacto Cero' si se está intentando superar una ruptura tóxica)", "Terapia EMDR si la dependencia proviene de traumas infantiles no resueltos", "Grupos de apoyo (como Dependientes Anónimos o Codependientes Anónimos - CoDA) para compartir experiencias y romper el aislamiento"] } ], note: "Aprender a tolerar y disfrutar la soledad es un hito crucial en la recuperación del dependiente emocional." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Psicológica?", intro: "Busque terapia si se da cuenta de que:", items: ["Su relación le causa más sufrimiento y ansiedad que felicidad, pero se siente incapaz de terminarla", "Ha perdonado infidelidades repetidas, faltas de respeto o abuso físico/emocional por miedo a quedarse solo", "Siente que no sabe quién es usted ni qué le gusta hacer sin su pareja", "Experimenta ataques de pánico o ansiedad extrema cuando su pareja no le responde un mensaje o se va a trabajar"] } },
'Trastornos de las glándulas salivales' : { intro: "Las glándulas salivales producen la saliva esencial para digerir los alimentos, proteger los dientes y tragar. Cuando estas glándulas se bloquean, infectan o desarrollan tumores, pueden causar dolor, hinchazón facial aguda y problemas significativos en la boca, requiriendo evaluación médica u odontológica.", whatIs: { title: "¿Qué son los Trastornos de las Glándulas Salivales?", text: "Son afecciones clínicas que afectan el funcionamiento o la estructura de las principales glándulas productoras de saliva (parótidas, submandibulares y sublinguales) o de los cientos de glándulas menores en la boca, provocando alteraciones en la secreción, inflamación o dolor." }, symptoms: { title: "Síntomas de Alerta", intro: "Los síntomas varían según el problema subyacente, pero a menudo incluyen:", groups: [ { name: "Síntomas locales en cara y boca", items: ["Hinchazón dolorosa en la cara, cuello o debajo de la mandíbula (a menudo ocurre o empeora justo antes o durante las comidas)", "Sabor muy desagradable o salado en la boca (generalmente pus de una infección)", "Boca crónicamente seca (xerostomía), lo que dificulta masticar, hablar o tragar", "Dolor al abrir la boca o al masticar alimentos", "Aparición de un bulto firme o masa indolora en la mejilla o debajo del mentón"] }, { name: "Síntomas sistémicos", items: ["Fiebre, escalofríos y malestar general (si hay una infección aguda bacteriana o viral)", "Dolor de garganta o enrojecimiento severo en el piso de la boca"] } ], warning: "La hinchazón dolorosa, roja y caliente debajo de la mandíbula acompañada de fiebre alta requiere antibióticos inmediatos para prevenir la propagación de la infección." }, types: { title: "Trastornos Más Comunes", intro: "Existen múltiples problemas que pueden afectar a estas glándulas:", items: ["Sialolitiasis (Cálculos salivales): Pequeñas piedras de calcio que bloquean los conductos salivales, causando dolor intenso al comer.", "Sialadenitis: Infección bacteriana de la glándula salival, a menudo secundaria a un bloqueo por cálculos o deshidratación severa.", "Infecciones virales: La más conocida son las paperas (parotiditis), que causa hinchazón de ambas glándulas parótidas.", "Síndrome de Sjögren: Una enfermedad autoinmune crónica que destruye las glándulas salivales y lagrimales, causando boca y ojos extremadamente secos.", "Tumores: Pueden ser benignos (adenoma pleomórfico, el más común) o malignos. Suelen aparecer como nódulos indoloros de crecimiento lento."], note: "La gran mayoría de los tumores en la glándula parótida (la más grande) son benignos." }, causes: { title: "Causas y Factores de Riesgo", intro: "El mal funcionamiento y bloqueo pueden deberse a:", items: ["Deshidratación crónica o consumo de medicamentos que secan la boca (antihistamínicos, antidepresivos, diuréticos), lo que espesa la saliva y facilita la formación de cálculos", "Mala higiene bucal que permite a las bacterias ascender por el conducto salival", "Enfermedades autoinmunes (Sjögren, Artritis Reumatoide)", "Infecciones virales sistémicas (VIH, virus de la gripe, paperas)", "Exposición previa a radioterapia en la cabeza y el cuello"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "Un otorrinolaringólogo o un cirujano maxilofacial evaluará la condición usando:", items: ["Examen físico palpando las glándulas en el cuello, mejillas y el interior de la boca para sentir masas o presionar para ver si sale pus", "Ecografía de cuello y cara (muy eficaz para detectar piedras de calcio o quistes)", "Tomografía computarizada (TC) o Resonancia Magnética (RM) para tumores, infecciones profundas o cálculos que la ecografía no ve claramente", "Sialografía (Rayos X usando contraste inyectado en el conducto salival para ver bloqueos)", "Biopsia por aspiración con aguja fina (PAAF) si se detecta un tumor o masa para descartar cáncer", "Análisis de sangre para detectar enfermedades autoinmunes como el Síndrome de Sjögren"], note: "El historial de síntomas relacionados con las comidas es la pista principal para diagnosticar cálculos salivales." }, treatment: { title: "Opciones de Tratamiento", intro: "El tratamiento depende estrictamente de la causa del trastorno:", subsections: [ { title: "Medidas médicas y quirúrgicas", items: ["Para cálculos salivales (piedras): Estimular el flujo de saliva chupando dulces ácidos (sin azúcar), bebiendo mucha agua y aplicando masajes cálidos. Si no sale, el médico puede extraerla masajeando o mediante una pequeña incisión/sialoendoscopia.", "Para infecciones (Sialadenitis): Antibióticos potentes, analgésicos, compresas tibias y rehidratación intravenosa si es necesario.", "Para el Síndrome de Sjögren: Sustitutos de saliva, medicamentos para estimular la secreción (pilocarpina), enjuagues bucales con flúor para prevenir caries por sequedad e inmunosupresores.", "Para tumores o quistes: Cirugía para extirpar la masa o toda la glándula salival afectada (a menudo requiere técnicas precisas para no dañar el nervio facial que atraviesa la glándula parótida)."] } ], note: "Mantenerse bien hidratado es la mejor prevención para la mayoría de los problemas de glándulas salivales." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Médico u Otorrinolaringólogo?", intro: "Solicite una consulta médica de valoración si:", items: ["Presenta una hinchazón debajo de la mandíbula o delante de la oreja que no desaparece en unos días", "Experimenta un dolor agudo y punzante en la boca o cara cada vez que intenta comer", "Desarrolla fiebre alta junto con hinchazón y enrojecimiento en el cuello", "Nota un bulto o masa dura, de crecimiento lento, en la mejilla, el cuello o el paladar (incluso si no duele)"] } },
'Fibroadenoma de mama' : { intro: "Un fibroadenoma de mama es el tipo más común de bulto mamario no canceroso en mujeres jóvenes. Aunque descubrir cualquier masa en los senos causa alarma, los fibroadenomas son lesiones benignas que no ponen en peligro la vida y a menudo requieren solo observación clínica.", whatIs: { title: "¿Qué es un Fibroadenoma?", text: "Es un tumor benigno (no canceroso) sólido de la mama compuesto por tejido glandular y conectivo (fibroso). Se siente como una canica firme, lisa o gomosa bajo la piel que se mueve fácilmente cuando se la empuja con los dedos." }, symptoms: { title: "Síntomas y Características", intro: "Generalmente, los fibroadenomas no causan dolor y son descubiertos por la paciente o un médico al tacto:", groups: [ { name: "Características del bulto al tacto", items: ["Bordes claramente definidos, lisos y regulares", "Textura firme o elástica (como de goma)", "Altamente móvil (se desliza o 'escapa' bajo los dedos al palparlo)", "Generalmente indoloro, aunque pueden volverse sensibles al tacto justo antes de la menstruación"] }, { name: "Tamaño y presentación", items: ["Suelen medir entre 1 y 3 centímetros, pero algunos pueden crecer mucho más (fibroadenomas gigantes)", "Pueden aparecer solos o en múltiples cantidades, en uno o en ambos senos al mismo tiempo"] } ], warning: "Todo bulto mamario nuevo o un cambio en el tejido del seno DEBE ser evaluado por un médico para descartar con certeza el cáncer de mama, incluso si parece inofensivo." }, types: { title: "Tipos de Fibroadenomas", intro: "Los patólogos clasifican los fibroadenomas en varias categorías:", items: ["Fibroadenomas simples: El tipo más común; las células se ven uniformes bajo el microscopio y no aumentan el riesgo de cáncer de mama.", "Fibroadenomas complejos: Contienen cambios como quistes, depósitos de calcio o tejido agrandado. Las mujeres con estos pueden tener un riesgo muy ligeramente mayor de desarrollar cáncer de mama en el futuro.", "Fibroadenomas juveniles: Se presentan en niñas o adolescentes (10 a 18 años). Pueden crecer rápidamente pero a menudo se encogen con el tiempo.", "Fibroadenomas gigantes: Tumores que superan los 5 centímetros (2 pulgadas) y pueden desplazar o presionar el tejido mamario sano, requiriendo su extirpación."], note: "Los fibroadenomas a menudo reducen su tamaño e incluso desaparecen por sí solos después de la menopausia." }, causes: { title: "Causas y Factores Relacionados", intro: "Se desconoce la causa exacta, pero la evidencia apunta fuertemente a factores hormonales:", items: ["Respuesta exagerada a las hormonas reproductivas, particularmente el estrógeno", "Aparecen con mayor frecuencia durante los años reproductivos (entre los 15 y los 35 años)", "Tienden a crecer en tamaño durante el embarazo o al recibir terapia hormonal/anticonceptivos orales", "Tienden a encogerse cuando los niveles de hormonas disminuyen, especialmente durante y después de la menopausia"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para asegurar que el bulto no es cáncer, el ginecólogo o mastólogo utilizará la evaluación 'triple':", items: ["Examen físico clínico de los senos", "Estudios de imagen: Una ecografía mamaria (prueba preferida para mujeres menores de 30 años con tejido denso) para confirmar que el bulto es sólido y no un quiste de líquido. Si la mujer es mayor, se solicitará una mamografía.", "Biopsia por punción con aguja gruesa (Core biopsy): Procedimiento donde el médico extrae muestras de tejido del bulto bajo anestesia local guiado por ecografía, para analizarlas en laboratorio y confirmar al 100% que es un fibroadenoma benigno"], note: "En mujeres jóvenes, si la ecografía es clásicamente indicativa de un fibroadenoma simple, el médico puede decidir solo monitorearlo sin necesidad inmediata de biopsia." }, treatment: { title: "Opciones de Tratamiento", intro: "Muchos fibroadenomas no necesitan tratamiento médico si se confirma que son benignos:", subsections: [ { title: "Abordajes recomendados", items: ["Observación ('espera vigilante'): Chequeos clínicos periódicos y ecografías repetidas cada 6 a 12 meses para confirmar que el bulto no está creciendo ni cambiando", "Escisión quirúrgica (tumorectomía): Cirugía ambulatoria para extirpar el bulto. Se recomienda si es un fibroadenoma complejo, si es muy grande, si causa dolor, si crece rápidamente o por simple tranquilidad de la paciente", "Crioablación: Procedimiento menos invasivo en el cual el médico inserta un dispositivo con forma de varilla a través de la piel y utiliza gas extremadamente frío para congelar y destruir el tejido del fibroadenoma"] } ], note: "Extirpar un fibroadenoma no impide que puedan crecer otros nuevos en el futuro." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Especialista?", intro: "Debe programar una visita con su ginecólogo o médico si:", items: ["Descubre un bulto nuevo en sus senos durante el autoexamen", "Nota cambios en el tamaño, forma o textura de sus senos", "Tiene un bulto que ya había sido revisado por un médico pero que de repente parece haber crecido o doler", "Presenta hoyuelos, fruncimiento, o la piel de la mama se ve como 'piel de naranja', o el pezón se retrae"] } },
'Reducción de grasa (adiposidades)' : { intro: "La acumulación de adiposidades localizadas o exceso de grasa corporal es una preocupación médica, estética y metabólica muy común. Más allá del control de peso general, existen acúmulos de grasa resistentes a dietas y ejercicios que requieren enfoques médicos especializados para su reducción o eliminación.", whatIs: { title: "¿Qué son las Adiposidades Localizadas?", text: "Es la acumulación excesiva y anormal de tejido adiposo (células grasas) en áreas específicas del cuerpo, como el abdomen, caderas, muslos, papada o flancos. A diferencia de la obesidad generalizada, estas áreas suelen estar determinadas genéticamente y son muy difíciles de movilizar con cambios en el estilo de vida." }, symptoms: { title: "Evaluación y Características Clínicas", intro: "Las adiposidades se evalúan tanto por su ubicación como por su impacto en la salud:", groups: [ { name: "Características físicas", items: ["Presencia de pliegues o protuberancias de grasa desproporcionadas en relación con el resto del cuerpo", "Grasa subcutánea blanda que se puede pellizcar fácilmente bajo la piel (grasa periférica)", "Depósitos de grasa celulítica (piel de naranja) frecuentemente en muslos y glúteos", "Lipomastia (acumulación de grasa en los senos masculinos)"] }, { name: "Impacto metabólico (Grasa visceral)", items: ["Abdomen tenso, prominente y duro (grasa visceral acumulada alrededor de los órganos internos), la cual es metabólicamente peligrosa", "Mayor riesgo asociado a hipertensión, resistencia a la insulina y colesterol alto (si la adiposidad es central/visceral)"] } ], warning: "La grasa visceral (intraabdominal) aumenta significativamente el riesgo de enfermedades cardiovasculares y diabetes tipo 2, requiriendo un enfoque médico más allá del estético." }, types: { title: "Tipos de Tejido Adiposo y Condiciones", intro: "El manejo difiere según el tipo y la distribución de la grasa:", items: ["Grasa subcutánea: Grasa localizada justo bajo la piel. Responde bien a tratamientos estéticos y quirúrgicos, pero es menos perjudicial para la salud metabólica.", "Grasa visceral: Rodea los órganos vitales. Solo responde a pérdida de peso general (dieta/ejercicio) y no puede tratarse con liposucción.", "Lipedema: Una condición médica crónica y dolorosa, casi exclusiva de mujeres, donde la grasa se acumula simétricamente en las piernas y brazos, resistente a la dieta.", "Lipomas: Tumores benignos de tejido graso que forman bultos bajo la piel y suelen requerir escisión quirúrgica simple."], note: "Los tratamientos de contorno corporal estético solo son efectivos para la grasa subcutánea." }, causes: { title: "Causas y Factores Predisponentes", intro: "La acumulación de grasa rebelde obedece a múltiples factores:", items: ["Genética (el factor principal que determina dónde el cuerpo almacena sus reservas de grasa predeterminadas)", "Cambios hormonales (pubertad, embarazo, menopausia y andropausia, o problemas de tiroides/insulina)", "Superávit calórico prolongado (consumir más calorías de las que se queman)", "Estilo de vida sedentario y envejecimiento (ralentización del metabolismo basal)", "Uso crónico de ciertos medicamentos (como corticosteroides o antidepresivos)"] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "Médicos estéticos, cirujanos plásticos o endocrinólogos evalúan las adiposidades mediante:", items: ["Examen físico visual y medición de pliegues cutáneos con un plicómetro (para grasa subcutánea)", "Medición del índice de masa corporal (IMC) y circunferencia de la cintura (para evaluar el riesgo metabólico)", "Bioimpedancia o escáneres DEXA para calcular el porcentaje exacto de grasa corporal y masa magra", "Análisis de sangre para descartar síndrome metabólico, problemas de tiroides o resistencia a la insulina", "Ecografía de tejidos blandos si hay sospecha de lipomas o hernias"], note: "Es crucial diferenciar entre la adiposidad localizada cosmética y la obesidad clínica que requiere manejo metabólico." }, treatment: { title: "Métodos de Reducción Médica y Quirúrgica", intro: "Las opciones van desde tratamientos no invasivos hasta cirugía para remodelar el cuerpo:", subsections: [ { title: "Opciones terapéuticas (para grasa subcutánea)", items: ["Tratamientos no invasivos (Criolipólisis): Congelación de células grasas localizadas (ej. CoolSculpting), las cuales son eliminadas naturalmente por el cuerpo en semanas.", "Tratamientos mínimamente invasivos: Inyecciones de ácido desoxicólico (Kybella) para destruir grasa bajo el mentón, o terapias de radiofrecuencia/ultrasonido (HIFU) para tensar y reducir.", "Liposucción/Lipoescultura: El método quirúrgico tradicional y más definitivo. Un cirujano plástico aspira físicamente las células grasas de las áreas problemáticas.", "Procedimientos bariátricos (Cirugía metabólica, balón gástrico, medicamentos inyectables tipo GLP-1 como Ozempic o Saxenda): Exclusivos para pacientes con obesidad clínica significativa, bajo estricta prescripción médica.", "Manejo nutricional y deportivo: Déficit calórico estructurado por un nutriólogo y entrenamiento de fuerza/hipertrofia para mejorar la composición corporal basal."] } ], note: "Ningún procedimiento estético de reducción de grasa sustituye un estilo de vida saludable; si el paciente gana peso, la grasa puede acumularse en otras áreas." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico Especialista?", intro: "Es recomendable buscar evaluación con un nutriólogo, endocrinólogo o cirujano si:", items: ["Su circunferencia de cintura supera los límites saludables (más de 88 cm en mujeres o 102 cm en hombres), indicando riesgo cardiovascular", "Ha intentado dieta y ejercicio de forma rigurosa pero tiene acúmulos de grasa resistentes que afectan su autoestima", "Sufre dolor, moretones frecuentes o pesadez extrema en las piernas (síntomas de posible lipedema)", "Desea opciones quirúrgicas o inyectables seguras y necesita discutir los riesgos y beneficios con un profesional certificado"] } },
'Anemia ferropénica en niños' : { intro: "La anemia ferropénica (por deficiencia de hierro) es el trastorno nutricional más común en la infancia. El hierro es vital para el desarrollo cerebral y físico de los niños; su falta sostenida provoca cansancio extremo, debilidad, retraso en el crecimiento y problemas de aprendizaje y atención.", whatIs: { title: "¿Qué es la Anemia Ferropénica Infantil?", text: "Es una condición en la que la sangre carece de una cantidad adecuada de glóbulos rojos sanos debido a una escasez de hierro en el cuerpo. El hierro es necesario para producir hemoglobina, la proteína de los glóbulos rojos que transporta el oxígeno vital a todos los órganos del niño." }, symptoms: { title: "Síntomas y Signos de Alerta", intro: "Los casos leves pueden pasar desapercibidos, pero a medida que las reservas de hierro caen, se observa:", groups: [ { name: "Síntomas físicos visibles", items: ["Palidez notoria en la piel, los labios, el interior de los párpados o debajo de las uñas", "Cansancio persistente, debilidad o letargo inusual en el niño", "Manos y pies frecuentemente fríos", "Uñas quebradizas o con forma de cuchara (coiloniquia)", "Frecuencia cardíaca inusualmente rápida (taquicardia) o soplos cardíacos"] }, { name: "Síntomas conductuales y cognitivos", items: ["Irritabilidad extrema o cambios frecuentes de humor", "Falta de apetito o rechazo general a la comida", "Pica: Un antojo inusual por comer cosas no nutritivas como tierra, hielo, pintura, papel o tiza", "Dificultad de concentración en la escuela o retraso en las habilidades motoras y del habla en bebés"] } ], warning: "La deficiencia severa y prolongada de hierro en los dos primeros años de vida puede causar daños irreversibles en el desarrollo cognitivo del niño." }, types: { title: "Etapas de la Deficiencia", intro: "La condición empeora progresivamente si no se corrige la dieta:", items: ["Agotamiento de las reservas de hierro: El nivel de hierro almacenado (ferritina) baja, pero la hemoglobina aún es normal. No hay anemia todavía.", "Deficiencia de hierro sin anemia: La producción de glóbulos rojos comienza a verse afectada, pero aún dentro del límite bajo normal.", "Anemia ferropénica manifiesta: La hemoglobina desciende por debajo del nivel normal y los glóbulos rojos se vuelven pequeños y pálidos (microcíticos e hipocrómicos), causando síntomas obvios."], note: "Los bebés prematuros y los lactantes alimentados exclusivamente con leche de vaca entera (antes del año) tienen el mayor riesgo." }, causes: { title: "Causas y Factores de Riesgo en Niños", intro: "La deficiencia casi siempre se debe a una nutrición inadecuada o necesidades de rápido crecimiento:", items: ["Dieta baja en hierro: Es común en bebés que hacen la transición a alimentos sólidos sin recibir cereales o purés fortificados con hierro, o en niños pequeños 'quisquillosos' para comer", "Consumo excesivo de leche de vaca en niños pequeños: La leche de vaca es pobre en hierro, dificulta su absorción de otros alimentos, y si toman demasiada, se llenan y no comen alimentos nutritivos", "Periodos de crecimiento rápido: Durante los primeros dos años de vida y en la pubertad (especialmente en las niñas que comienzan a menstruar), el cuerpo necesita cantidades extras de hierro", "Problemas de absorción: Enfermedades intestinales como la enfermedad celíaca", "Pérdida de sangre (menos común): Sangrado intestinal lento por intolerancia a la leche de vaca entera, o menstruaciones abundantes en adolescentes"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra diagnosticará la anemia mediante análisis de sangre de rutina:", items: ["Hemograma completo (Biometría Hemática): Mide el nivel de hemoglobina y evalúa el tamaño de los glóbulos rojos (que suelen ser anormalmente pequeños en la anemia ferropénica)", "Prueba de Ferritina sérica: La prueba más precisa para medir la cantidad de hierro almacenado en el cuerpo del niño", "Niveles de Hierro en suero y Capacidad total de fijación de hierro (TIBC)", "Análisis de reticulocitos (para ver si la médula ósea está produciendo suficientes glóbulos rojos nuevos)"], note: "La Academia Americana de Pediatría recomienda realizar pruebas de detección de anemia a todos los bebés rutinariamente entre los 9 y 12 meses de edad." }, treatment: { title: "Tratamiento y Corrección Dietética", intro: "El manejo requiere suplementación médica y modificaciones nutricionales a largo plazo:", subsections: [ { title: "Intervenciones recomendadas", items: ["Suplementos de hierro en gotas o jarabe recetados por el pediatra (tomados diariamente durante varios meses para reponer las reservas, nunca se debe dar hierro por cuenta propia ya que en exceso es tóxico)", "Tomar el suplemento de hierro con vitamina C (como jugo de naranja) para maximizar la absorción, y evitar tomarlo junto con leche o lácteos", "Mejora en la dieta: Incluir carnes rojas magras, aves, pescado, frijoles, lentejas, vegetales de hoja verde oscuro y cereales fortificados con hierro", "Limitar el consumo de leche de vaca entera a no más de 16-24 onzas (aproximadamente medio litro) al día para niños de 1 a 5 años", "En adolescentes con sangrado menstrual intenso, el médico puede recetar pastillas anticonceptivas para reducir la pérdida de sangre"] } ], note: "Es normal que los suplementos de hierro vuelvan las heces del niño de color negro oscuro o verde oscuro; esto no es motivo de alarma." }, whenToSeekHelp: { title: "¿Cuándo Llevar al Niño al Pediatra?", intro: "Solicite una cita médica si observa en su hijo:", items: ["Extrema palidez generalizada o fatiga y falta de energía constante", "Se come tierra, masca hielo repetidamente u otros objetos no comestibles (Pica)", "Ha estado expuesto a dietas muy restrictivas, vegetarianas estrictas sin suplementación, o bebe grandes cantidades de leche de vaca en lugar de comer alimentos sólidos", "Nota dificultad para respirar o latidos cardíacos muy rápidos mientras el niño juega o descansa"] } },
'Cardiopatías' : { intro: "Las cardiopatías, o enfermedades del corazón, son la principal causa de muerte a nivel mundial. Engloban una amplia gama de afecciones que afectan la estructura, las válvulas, el ritmo eléctrico o los vasos sanguíneos del corazón, pudiendo derivar en ataques cardíacos mortales o insuficiencia cardíaca crónica.", whatIs: { title: "¿Qué son las Cardiopatías?", text: "Es un término general ('enfermedad cardiovascular') utilizado para describir múltiples problemas y patologías que afectan al corazón. Estas afecciones impiden que el corazón bombee sangre rica en oxígeno de manera eficiente al resto del cuerpo, ya sea por conductos bloqueados, debilidad muscular o fallos eléctricos." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Los síntomas varían ampliamente dependiendo del tipo específico de afección cardíaca, pero los principales son:", groups: [ { name: "Síntomas Clásicos de Enfermedad Coronaria o Infarto", items: ["Dolor, opresión, pesadez o presión en el pecho (angina) que puede irradiarse al brazo izquierdo, mandíbula, cuello o espalda", "Dificultad repentina o severa para respirar, con o sin esfuerzo", "Sudoración fría e inexplicable, náuseas o mareos intensos"] }, { name: "Síntomas de Insuficiencia Cardíaca o Arritmias", items: ["Hinchazón (edema) crónica en piernas, tobillos, pies o abdomen debido a la retención de líquidos", "Fatiga extrema y debilidad que impide realizar actividades rutinarias", "Palpitaciones (sensación de latidos acelerados, aleteo o latidos omitidos en el pecho)", "Desmayos frecuentes (síncope) o mareos al ponerse de pie"] } ], warning: "El dolor o presión en el pecho opresiva, acompañada de falta de aire y sudor frío, es la señal inconfundible de un ataque cardíaco (infarto) en progreso: llame a emergencias (911) inmediatamente." }, types: { title: "Clasificación de Enfermedades del Corazón", intro: "Se dividen principalmente según el área funcional del corazón afectada:", items: ["Enfermedad de las arterias coronarias (EAC): La más común; acumulación de placa (colesterol) que estrecha las arterias (aterosclerosis), causando infartos.", "Arritmias cardíacas: Problemas con el sistema eléctrico del corazón (late demasiado rápido, lento o irregular, como en la Fibrilación Auricular).", "Cardiopatía congénita: Problemas en la estructura del corazón presentes desde el nacimiento (ej. un agujero en el corazón).", "Enfermedad de las válvulas cardíacas: Válvulas que no se abren lo suficiente (estenosis) o no se cierran bien (regurgitación o prolapso).", "Cardiomiopatía: Enfermedad directa del músculo cardíaco, que se vuelve anormalmente grueso, rígido o dilatado e incapaz de bombear con fuerza."], note: "La insuficiencia cardíaca suele ser el resultado final de dejar estas enfermedades sin tratar, donde el corazón queda demasiado débil para satisfacer las necesidades del cuerpo." }, causes: { title: "Causas y Factores de Riesgo Sistémicos", intro: "El deterioro del corazón suele ser el resultado de un estilo de vida poco saludable sumado a la genética:", items: ["Presión arterial alta (Hipertensión): El factor que más desgasta el corazón, obligándolo a trabajar más duro", "Niveles altos de colesterol LDL ('malo') y triglicéridos en sangre", "Tabaquismo y exposición crónica al humo de segunda mano (daña directamente las paredes arteriales)", "Diabetes no controlada (los niveles altos de azúcar dañan los nervios y vasos sanguíneos)", "Obesidad severa, sedentarismo y dietas ricas en grasas saturadas, trans y exceso de sal", "Estrés crónico severo y falta prolongada de sueño", "Antecedentes familiares de enfermedad cardíaca temprana (antes de los 55 años) o envejecimiento natural"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "El cardiólogo determinará la salud exacta del corazón a través de:", items: ["Electrocardiograma (ECG): Registra la actividad eléctrica para detectar infartos pasados o arritmias activas", "Ecocardiograma: Ultrasonido que muestra la anatomía del corazón, cómo laten sus cavidades y cómo funcionan sus válvulas", "Prueba de esfuerzo (Ergometría): Monitorea el corazón mientras el paciente camina en una cinta de correr para ver cómo responde al esfuerzo físico", "Monitor Holter: Dispositivo portátil que registra el ritmo cardíaco durante 24-48 horas", "Cateterismo cardíaco (Angiografía coronaria): Estudio invasivo para visualizar el interior de las arterias coronarias inyectando contraste para buscar bloqueos exactos"], note: "Los análisis de sangre para medir enzimas cardíacas (Troponina) son la prueba de urgencia para confirmar un ataque al corazón." }, treatment: { title: "Opciones de Tratamiento y Recuperación", intro: "El tratamiento varía drásticamente desde pastillas preventivas hasta cirugía a corazón abierto:", subsections: [ { title: "Enfoque clínico e intervencionista", items: ["Modificaciones urgentes del estilo de vida: Dieta cardiosaludable (mediterránea o DASH), abandono total del tabaquismo, control de peso y ejercicio prescrito", "Medicamentos: Estatinas (para colesterol), betabloqueantes y antihipertensivos (para la presión arterial), anticoagulantes (para prevenir coágulos en arritmias) y diuréticos", "Procedimientos mínimamente invasivos: Angioplastia y colocación de stents (mallas de metal) para abrir arterias bloqueadas; Ablación con catéter para quemar circuitos eléctricos defectuosos en arritmias", "Dispositivos médicos implantables: Marcapasos (para ritmos lentos) o Desfibriladores Automáticos Implantables (DAI) para prevenir muertes súbitas", "Cirugía abierta: Cirugía de derivación coronaria (Bypass), reemplazo de válvulas cardíacas dañadas, o trasplante de corazón en casos terminales"] } ], note: "La rehabilitación cardíaca guiada es fundamental para los pacientes que se recuperan de un infarto o cirugía mayor." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias Médicas?", intro: "No dude en llamar a una ambulancia o ir a urgencias si experimenta:", items: ["Dolor opresivo, presión, llenura o molestia como un 'peso' en el centro del pecho que dura más de unos minutos", "Dolor en el pecho que se irradia hacia uno o ambos brazos, la espalda, el cuello, la mandíbula o el estómago", "Falta repentina y extrema de aliento, incluso estando en reposo", "Sensación repentina de mareo intenso, desmayos (síncope) o sudor frío inexplicable asociado a palpitaciones rápidas"] } },
'Dermatitis por contacto' : { intro: "La dermatitis por contacto es una erupción cutánea pruriginosa (que pica intensamente) y enrojecida. Ocurre como una reacción directa de la piel al tocar sustancias irritantes o alérgenos. Aunque no es contagiosa ni pone en peligro la vida, puede ser sumamente incómoda hasta que se identifica y elimina el agente causante.", whatIs: { title: "¿Qué es la Dermatitis por Contacto?", text: "Es una inflamación aguda o crónica de la piel que se produce tras la exposición directa y física a una sustancia externa. La piel reacciona enrojeciéndose, hinchándose y picando de manera insoportable en el área exacta que estuvo en contacto con la sustancia." }, symptoms: { title: "Síntomas y Aspecto de la Piel", intro: "La erupción suele tener límites muy claros y aparece en las partes del cuerpo directamente expuestas:", groups: [ { name: "Síntomas agudos (inmediatos o retardados)", items: ["Erupción roja brillante, inflamada y altamente pruriginosa (picor intenso y constante)", "Aparición de pequeñas protuberancias que pueden convertirse en ampollas llenas de líquido transparente (vesículas), que pueden supurar o formar costras", "Sensación de ardor, quemazón intensa o sensibilidad dolorosa en la piel afectada", "A menudo, el sarpullido toma la forma del objeto que lo causó (como una banda alrededor de la muñeca por un reloj)"] }, { name: "Síntomas crónicos (si el contacto es constante)", items: ["Piel extremadamente seca, agrietada, escamosa y engrosada (liquenificación)", "Oscurecimiento de la piel y fisuras dolorosas, a menudo en las manos"] } ], warning: "Si la erupción de dermatitis alérgica ocurre en la cara y causa una inflamación masiva de los párpados impidiendo la visión, debe tratarse como una urgencia médica dermatológica." }, types: { title: "Tipos Principales", intro: "Médicamente se divide en dos tipos fundamentales con diferentes mecanismos:", items: ["Dermatitis de contacto irritativa (80% de los casos): Daño físico directo a la capa protectora externa de la piel. Ocurre en cualquier persona expuesta a sustancias químicas fuertes (lejía, ácidos) o al frotado constante (lavado frecuente de manos con jabón fuerte). Suele ser dolorosa y ardiente.", "Dermatitis de contacto alérgica (20% de los casos): Es una reacción retardada del sistema inmunológico que ataca un alérgeno específico. Puede tardar de 24 a 72 horas en aparecer tras el contacto. El síntoma principal es la picazón intensa."], note: "Una persona puede desarrollar alergia a un producto cosmético o metal que ha usado durante años sin problemas previos." }, causes: { title: "Desencadenantes y Sustancias Culpables", intro: "Literalmente miles de sustancias pueden causar esta reacción. Los culpables más habituales son:", items: ["Níquel: El alérgeno principal a nivel mundial. Presente en joyas de fantasía, hebillas de cinturones, botones de jeans y cremalleras", "Plantas venenosas: Hiedra venenosa, zumaque venenoso y roble venenoso (la resina urushiol causa ampollas severas)", "Productos de cuidado personal e higiene: Fragancias fuertes, tintes para el cabello, conservantes en cosméticos, esmaltes de uñas o jabones antibacteriales", "Productos de limpieza del hogar o solventes industriales (lejía, detergentes, disolventes, cemento)", "Ciertos medicamentos tópicos: Cremas antibióticas (neomicina), anestésicos locales o antihistamínicos en crema", "Goma, látex (guantes) y adhesivos médicos"] }, diagnosis: { title: "¿Cómo se Diagnostica el Alérgeno?", intro: "El dermatólogo o alergólogo actúa como un detective para descubrir el desencadenante:", items: ["Historia clínica detallada sobre pasatiempos, profesión, cosméticos recientes o excursiones a la naturaleza", "Examen físico del patrón y ubicación del sarpullido (la ubicación suele revelar el alérgeno, ej. lóbulos de las orejas = aretes)", "Pruebas del parche (Patch Test): La herramienta diagnóstica definitiva para el tipo alérgico. Se colocan pequeños parches con docenas de alérgenos sospechosos en la espalda durante 48 horas para ver a cuál reacciona la piel", "En casos atípicos, puede ser necesaria una biopsia de piel para descartar otros trastornos dermatológicos como la psoriasis"], note: "La prueba del parche es diferente de las pruebas de alergia cutáneas comunes por pinchazo, que se usan para alergias respiratorias o alimentarias." }, treatment: { title: "Medidas de Alivio y Curación", intro: "La curación es imposible sin identificar y evitar la sustancia causante:", subsections: [ { title: "Tratamientos médicos y caseros", items: ["Eliminación inmediata: Lavar profusamente el área con agua y jabón suave tras el contacto conocido", "Cremas o ungüentos con corticosteroides tópicos recetados (el pilar del tratamiento) para suprimir drásticamente la inflamación y la picazón", "Corticosteroides orales o inyectables (prednisona) para casos graves, especialmente si el sarpullido cubre una gran parte del cuerpo o la cara", "Antihistamínicos orales (solo útiles para ayudar al paciente a dormir y reducir ligeramente la picazón)", "Baños de avena coloidal, compresas húmedas y frías, y abundante crema hidratante (emolientes) para reparar la barrera de la piel"] } ], note: "Evitar rascarse a toda costa; rascarse rompe las ampollas e invita a infecciones bacterianas secundarias que requerirán antibióticos." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Dermatólogo o Médico?", intro: "Solicite ayuda médica si el sarpullido:", items: ["No muestra signos de mejora después de dos semanas de cuidados básicos y evitación del agente", "Es tan pruriginoso o doloroso que lo mantiene despierto toda la noche o lo distrae del trabajo", "Se extiende rápidamente, afecta su rostro, párpados, u órganos genitales de manera severa", "Las ampollas comienzan a supurar pus amarillo/verde, o la piel está caliente y muy sensible (signos de infección bacteriana secundaria)"] } },
'Demencia vascular' : { intro: "La demencia vascular es la segunda forma más común de demencia, después del Alzheimer. Se produce por un flujo sanguíneo reducido al cerebro, a menudo tras sufrir múltiples microinfartos cerebrales o derrames, afectando severamente el razonamiento, la planificación, el juicio y la memoria.", whatIs: { title: "¿Qué es la Demencia vascular?", text: "Es un declive progresivo y severo de las habilidades cognitivas (pensamiento) causado por daños microscópicos o problemas de bloqueo en los vasos sanguíneos que irrigan el cerebro. Esto priva de oxígeno vital a diferentes regiones del tejido cerebral, provocando la muerte de neuronas." }, symptoms: { title: "Síntomas Cognitivos y Neurológicos", intro: "A diferencia del Alzheimer (cuyo síntoma principal es la pérdida de memoria), la demencia vascular se manifiesta más por problemas en el razonamiento rápido y la toma de decisiones:", groups: [ { name: "Deterioro cognitivo y mental", items: ["Dificultad evidente para prestar atención, concentrarse o resolver problemas simples", "Lentitud extrema en el pensamiento o la comprensión", "Problemas graves de planificación, organización o seguimiento de instrucciones con múltiples pasos (deterioro de funciones ejecutivas)", "Confusión repentina (a menudo de noche) o desorientación profunda", "Pérdida de memoria (suele presentarse en etapas posteriores, a diferencia del Alzheimer)"] }, { name: "Síntomas conductuales y físicos", items: ["Inestabilidad al caminar (marcha arrastrada) o caídas frecuentes sin motivo aparente", "Problemas urinarios como necesidad urgente de orinar o incontinencia", "Cambios bruscos de humor, llanto o risa inapropiados, o profunda depresión (muy común)", "Lapsos repentinos de debilidad leve o entumecimiento asimétrico en el cuerpo"] } ], warning: "Si el deterioro cognitivo aparece de forma muy repentina tras un ACV (accidente cerebrovascular) visible, es demencia vascular posterior a un derrame." }, types: { title: "Progresión y Causas Subyacentes", intro: "El patrón de declive de esta demencia es característico:", items: ["Demencia multiinfarto: Causada por numerosos derrames cerebrales pequeños a lo largo del tiempo. Los síntomas ocurren en un patrón 'escalonado' o de 'peldaños de escalera' (una pérdida repentina de habilidades que se estabiliza, seguida de otro declive abrupto, a diferencia del declive suave y continuo del Alzheimer).", "Demencia vascular por enfermedad de vasos pequeños subcortical (Enfermedad de Binswanger): Causada por un daño generalizado y sutil de los pequeños vasos sanguíneos profundos del cerebro.", "Demencia por infarto estratégico: Ocurre cuando un único coágulo o derrame destruye una zona muy crítica y específica del cerebro responsable del pensamiento o la memoria."], note: "Muchos pacientes de edad avanzada tienen 'demencia mixta', lo que significa que presentan tanto la patología de la demencia vascular como la enfermedad de Alzheimer al mismo tiempo." }, causes: { title: "Causas Directas y Factores de Riesgo", intro: "La raíz de la demencia vascular son los mismos factores que causan enfermedades cardíacas y derrames:", items: ["Derrames cerebrales silenciosos (isquémicos o hemorrágicos) que dañan progresivamente partes del cerebro sin que el paciente lo note claramente al principio", "Presión arterial alta crónica no tratada (el factor de riesgo más importante para dañar los pequeños vasos cerebrales)", "Enfermedades cardíacas subyacentes (especialmente la Fibrilación Auricular, que lanza coágulos al cerebro)", "Diabetes incontrolada (los altos niveles de azúcar dañan silenciosamente todos los vasos sanguíneos del cuerpo)", "Colesterol alto persistente, tabaquismo activo y envejecimiento avanzado", "Aterosclerosis (acumulación de placas de grasa que endurecen las arterias cerebrales)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere una extensa evaluación clínica y neurológica para diferenciarla del Alzheimer:", items: ["Revisión profunda del historial médico buscando evidencias de derrames pasados, hipertensión, diabetes o enfermedades vasculares", "Pruebas neuropsicológicas y cognitivas complejas: Evalúan memoria, juicio, velocidad de procesamiento, resolución de problemas y lenguaje (los pacientes vasculares suelen fallar más en la velocidad y resolución)", "Resonancia Magnética Cerebral (RM) o Tomografía Computarizada (TC): Esencial para confirmar el diagnóstico; muestra infartos antiguos recientes, lagunas cerebrales o anomalías generalizadas en la sustancia blanca (leucoaraiosis)", "Análisis de sangre para descartar deficiencias vitamínicas (B12) o hipotiroidismo que imitan la demencia"], note: "El diagnóstico es fundamental, ya que tratar agresivamente los factores de riesgo cardiovascular puede detener o frenar la progresión de la enfermedad, algo que no se puede hacer en el Alzheimer." }, treatment: { title: "Manejo Médico y Prevención Secundaria", intro: "No existe cura para reparar el daño cerebral existente, pero el tratamiento se centra obsesivamente en prevenir un daño mayor:", subsections: [ { title: "Opciones farmacológicas y apoyo", items: ["Control estricto e innegociable de la presión arterial, glucosa en sangre y colesterol mediante medicación (antagonistas del calcio, estatinas, insulina)", "Uso de anticoagulantes o antiplaquetarios (aspirina, clopidogrel) para prevenir futuros coágulos sanguíneos o derrames cerebrales", "Medicamentos para el Alzheimer (inhibidores de colinesterasa o memantina), que a veces se recetan para ayudar modestamente con los síntomas cognitivos de la demencia vascular", "Antidepresivos para manejar los cambios de humor y la depresión acompañante", "Rehabilitación neuropsicológica, terapia ocupacional y del habla para maximizar la independencia restante", "Apoyo intensivo a los cuidadores familiares, preparación del hogar para evitar caídas y apoyo psicosocial"] } ], note: "Lo que es bueno para el corazón es bueno para el cerebro; dejar de fumar y hacer ejercicio reduce el riesgo dramáticamente." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Neurólogo o Geriatra?", intro: "Es fundamental buscar asistencia de un especialista si el adulto mayor:", items: ["Muestra problemas de confusión severa, lentitud en el pensamiento o desorientación repentina que no tenía hace unos meses", "Sufrió recientemente un accidente cerebrovascular menor o 'Ataque Isquémico Transitorio' (AIT) y parece haber perdido capacidades cognitivas posteriores", "Muestra un patrón evidente de caminar de manera arrastrada combinado con problemas graves de incontinencia urinaria y memoria", "Se ríe o llora incontrolablemente sin motivo aparente (labilidad emocional) sumado a un pensamiento desorganizado"] } },
'Deseo sexual hipoactivo' : { intro: "El trastorno de deseo sexual hipoactivo (TDSH) es la forma más común de disfunción sexual femenina, aunque también afecta a hombres. Implica una pérdida profunda, persistente y angustiante del interés por el sexo y los pensamientos sexuales, afectando severamente la calidad de vida y las relaciones de pareja.", whatIs: { title: "¿Qué es el Deseo Sexual Hipoactivo (TDSH)?", text: "Es una condición clínica caracterizada por la ausencia o disminución recurrente de fantasías sexuales y del deseo de iniciar o participar en la actividad sexual. Para ser diagnosticado como un trastorno médico, esta falta de deseo debe causar una marcada angustia personal o dificultades interpersonales en la persona afectada." }, symptoms: { title: "Síntomas y Criterios Clínicos", intro: "El TDSH no se trata de tener menos relaciones sexuales que antes, sino de la pérdida de interés genuino que genera sufrimiento:", groups: [ { name: "Pérdida de impulsos e interés", items: ["Pérdida parcial o total de los pensamientos o fantasías sexuales espontáneas", "Falta general de interés en iniciar encuentros íntimos o en responder a los intentos de inicio por parte de la pareja", "Reducción significativa o nula de la excitación sexual y placer durante casi todos los encuentros sexuales", "Falta de interés en cualquier tipo de actividad sexual (ya sea en pareja o autostimulación)"] }, { name: "Impacto emocional", items: ["Sentimientos profundos de angustia, frustración personal, sensación de insuficiencia o tristeza extrema debido a la falta de deseo", "Aparición de problemas significativos, distancia o conflictos y resentimiento en la relación de pareja"] } ], warning: "Si la falta de deseo ocurre de manera repentina o se acompaña de dolor intenso durante las relaciones, debe evaluarse de inmediato para descartar un problema ginecológico o metabólico agudo." }, types: { title: "Clasificación Psiquiátrica (DSM-5)", intro: "Para guiar el tratamiento, se debe evaluar si el problema es global o condicionado:", items: ["Generalizado frente a Situacional: ¿La falta de deseo ocurre con cualquier pareja y en cualquier contexto (generalizado) o solo con la pareja actual y no en otras situaciones (situacional)?", "Adquirido frente a De por Vida: ¿Se desarrolló en algún momento de la vida después de un período de función sexual normal (adquirido), o la persona nunca ha experimentado deseo sexual (de por vida)?"], note: "Es vital diferenciar el TDSH de la asexualidad, la cual es una orientación sexual natural que NO genera angustia personal ni se considera un trastorno médico." }, causes: { title: "Raíces Biológicas y Psicológicas", intro: "El deseo sexual es altamente complejo. Sus causas pueden ser puramente físicas, psicológicas o una mezcla de ambas:", items: ["Causas biológicas: Desequilibrios de los neurotransmisores (dopamina baja, serotonina alta), deficiencia de testosterona en hombres y mujeres, menopausia, problemas de tiroides (hipotiroidismo) o fatiga crónica", "Efectos secundarios farmacológicos: Es muy común tras el uso crónico de ciertos antidepresivos (ISRS), píldoras anticonceptivas de altas dosis hormonales o medicamentos para la presión arterial", "Factores psicológicos: Estrés extremo en el trabajo o la familia, problemas severos de autoestima y la imagen corporal, historial de trauma o abuso sexual pasado, depresión clínica o trastornos de ansiedad", "Factores relacionales: Conflictos graves no resueltos con la pareja, falta de comunicación, aburrimiento en la rutina sexual, infidelidades previas o problemas de confianza"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El enfoque diagnóstico es profundo y empático, realizado por sexólogos clínicos, ginecólogos o psiquiatras:", items: ["Historial médico y sexual exhaustivo, conversando abiertamente sobre la vida sexual pasada y presente, las actitudes hacia el sexo, y los problemas en la relación", "Uso de herramientas de detección validadas (como el Cuestionario de Deseo Sexual Reducido) para evaluar la angustia de la paciente", "Revisión meticulosa de todos los medicamentos actuales y suplementos para identificar efectos secundarios inhibidores del deseo", "Análisis de sangre (perfil hormonal femenino/masculino, prolactina, panel tiroideo, y niveles de hierro/vitaminas) para descartar problemas físicos y endocrinos claros"], note: "El médico debe asegurarse de que la falta de deseo no sea secundaria a otra disfunción, como el vaginismo o la dispareunia (dolor real durante el coito)." }, treatment: { title: "Opciones Terapéuticas y Médicas", intro: "El tratamiento es altamente personalizado y a menudo incluye una combinación de medicamentos y consejería:", subsections: [ { title: "Abordajes combinados", items: ["Asesoramiento psicológico y terapia sexual: Fundamental para abordar problemas de relación, educación sexual, estrés y trauma (a menudo involucrando a la pareja). Uso de Terapia Cognitivo-Conductual (TCC) o terapia basada en mindfulness.", "Modificación de medicamentos: Cambiar o reducir las dosis de antidepresivos inhibidores de la libido por otros que no afecten el deseo (ej. bupropión).", "Terapia hormonal (Mujeres): Uso de terapia de estrógeno sistémico o local (si el problema se asocia a dolor por sequedad vaginal menopáusica), o tratamientos fuera de indicación oficial (off-label) con pequeñas dosis de testosterona", "Terapia hormonal (Hombres): Terapia de reemplazo de testosterona si los niveles séricos están clínicamente bajos.", "Medicamentos aprobados por la FDA (para mujeres premenopáusicas): Flibanserina (una píldora diaria que afecta la química cerebral) o Bremelanotida (una inyección antes del acto sexual), ambos diseñados para estimular los centros cerebrales del deseo.", "Cambios de estilo de vida: Reducción del estrés, terapia de pareja para reavivar la intimidad emocional fuera del dormitorio, y priorizar el tiempo libre."] } ], note: "Recuperar el deseo lleva tiempo; no existen píldoras mágicas instantáneas que resuelvan el componente relacional del problema." }, whenToSeekHelp: { title: "¿Cuándo Buscar a un Sexólogo o Ginecólogo?", intro: "Es recomendable consultar a un profesional de la salud especializado si:", items: ["La pérdida completa del deseo sexual o de los pensamientos íntimos le está causando una gran tristeza, frustración o angustia emocional diaria", "Los problemas de deseo están amenazando la estabilidad de su matrimonio o relación", "Siente que no tiene deseo físico, pero intelectual y emocionalmente desearía volver a tener intimidad", "Nota que la pérdida de libido comenzó exactamente después de iniciar un nuevo tratamiento médico (antidepresivos, anticonceptivos, etc.)"] } },
'Aversión al sexo' : { intro: "La aversión al sexo, o Trastorno de Aversión Sexual, es una fobia extrema y profunda relacionada con cualquier forma de intimidad sexual física. Quienes la padecen experimentan repulsión, pánico y asco intenso ante el contacto genital, lo que va mucho más allá de una simple pérdida temporal de deseo.", whatIs: { title: "¿Qué es el Trastorno de Aversión Sexual?", text: "Es una aversión extrema y evitación persistente de todo (o casi todo) el contacto sexual genital con una pareja. Frente a un estímulo sexual o un encuentro inminente, la persona sufre un profundo asco, rechazo físico e incluso síntomas severos de pánico, en lugar de simple desinterés." }, symptoms: { title: "Manifestaciones Psicológicas y Físicas", intro: "Es fundamentalmente una reacción de ansiedad y rechazo fóbico severo:", groups: [ { name: "Reacciones emocionales extremas", items: ["Sentimiento de repulsión profunda, asco incontrolable o terror ante la idea o la realidad del contacto sexual", "Ansiedad severa y anticipatoria abrumadora cuando se espera que haya interacción íntima", "Desarrollo de elaboradas estrategias de evasión para evitar la cama, irse a dormir en diferentes momentos o crear argumentos para mantener alejada a la pareja", "La reacción de aversión puede desencadenarse incluso por un simple beso o toque físico no genital si se percibe que puede llevar al sexo"] }, { name: "Síntomas físicos de pánico (ataques de ansiedad)", items: ["Taquicardia, palpitaciones violentas, hiperventilación o falta de aire ante el intento de contacto", "Náuseas intensas, mareos severos, sudores fríos o incluso desmayos y vómitos inducidos por el miedo al contacto genital"] } ], warning: "Obligar o presionar a una persona que sufre aversión sexual no hace más que re-traumatizarla y agravar exponencialmente la fobia clínica." }, types: { title: "Diferenciación de Condiciones", intro: "Es importante distinguir la aversión de otras afecciones menos severas:", items: ["A diferencia del Deseo Sexual Hipoactivo (TDSH), donde simplemente no hay interés, en la aversión hay un sentimiento activo de repulsión o miedo agudo.", "A diferencia de la Asexualidad, donde hay falta de atracción innata sin miedo ni asco.", "A diferencia de la dispareunia o vaginismo, la aversión ocurre antes de cualquier penetración, impulsada mentalmente por el asco, no necesariamente por el dolor físico.", "Puede ser selectiva (asco hacia el olor o el fluido genital específico) o generalizada (asco hacia cualquier tipo de contacto físico íntimo)."], note: "Históricamente era una categoría oficial del DSM, hoy se considera y trata más bien como una fobia específica o un subtipo grave de ansiedad o TEPT en sexología clínica." }, causes: { title: "Orígenes y Traumas Pasados", intro: "Este trastorno suele estar profundamente arraigado en experiencias traumáticas o aprendizajes destructivos:", items: ["Trauma sexual previo: Abuso sexual infantil, incesto, agresión sexual severa o violaciones (la causa subyacente más frecuente y poderosa)", "Educación y antecedentes culturales restrictivos: Crianza en un entorno profundamente puritano o religioso extremo donde el sexo fue enseñado constantemente como algo sucio, pecaminoso, vergonzoso o peligroso", "Experiencias sexuales iniciales dolorosas, humillantes o traumáticas durante la adolescencia", "Disfunción sexual grave y prolongada en la pareja (dolor severo al tener relaciones que llevó, a través del condicionamiento clásico, a tener fobia al acto mismo)", "En algunos casos raros, problemas severos de autoestima y rechazo patológico a la propia imagen corporal"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere alta sensibilidad y es llevado a cabo por psiquiatras o sexólogos clínicos:", items: ["Evaluación clínica exhaustiva sobre la naturaleza exacta del miedo, asco o ansiedad experimentada", "Historial traumático confidencial (buscando signos no detectados de TEPT u otros abusos en el historial de la persona)", "Diferenciar la aversión de un simple conflicto matrimonial o falta de atracción hacia la pareja actual", "Determinar si el paciente sufre de otras fobias concurrentes, depresión clínica profunda o trastorno obsesivo-compulsivo (TOC) relacionado con el miedo a los fluidos o la contaminación"], note: "El paciente a menudo se siente profundamente avergonzado, defectuoso o culpable frente a su pareja por no poder tolerar el contacto." }, treatment: { title: "Enfoque de Terapia Intensiva", intro: "El tratamiento médico no se basa en píldoras hormonales, sino en un proceso psicológico cuidadoso para desaprender el miedo:", subsections: [ { title: "Rehabilitación psicosexual", items: ["Terapia EMDR (Desensibilización y Reprocesamiento por Movimientos Oculares) o terapias especializadas en trauma, si la aversión está vinculada a un abuso sexual pasado", "Terapia Cognitivo-Conductual (TCC) y desensibilización sistemática: Técnicas clásicas de fobia donde el paciente es expuesto de forma mental y luego física, de manera extremadamente lenta, gradual y controlada, a estímulos íntimos", "Técnica de Focalización Sensorial (Masters y Johnson): Ejercicios estrictamente no sexuales y no genitales, realizados en pareja, diseñados para restablecer la confianza en el contacto físico (caricias, masajes) sin la presión o expectativa del sexo genital", "Medicación psiquiátrica: Uso de ansiolíticos (medicamentos contra la ansiedad) a corto plazo o antidepresivos (ISRS) para calmar el sistema nervioso reactivo del paciente y permitir que la terapia psicológica funcione", "Terapia de pareja indispensable, para educar a la otra persona y lograr un ambiente de apoyo absoluto, sin presiones"] } ], note: "La curación es posible, pero suele ser un proceso terapéutico a largo plazo; requiere gran paciencia de ambas partes." }, whenToSeekHelp: { title: "¿Cuándo Iniciar la Terapia?", intro: "Se debe buscar de inmediato la ayuda de un sexólogo clínico y terapeuta especializado en traumas si:", items: ["Sufre ataques de pánico incontrolables, náuseas extremas o llanto incontrolable ante la perspectiva de intimidad sexual", "Lleva meses o años inventando excusas constantes para evitar ir a la cama con su pareja por miedo al contacto físico", "Su vida matrimonial está al borde del colapso debido a la incapacidad de participar en cualquier forma de afecto sexual", "Reconoce que su aversión está basada en un trauma no resuelto que le impide vivir una vida plena y feliz"] } },
'Insuficiencia venosa' : { intro: "La insuficiencia venosa crónica es una enfermedad circulatoria de las piernas en la que las válvulas de las venas se dañan. En lugar de empujar la sangre hacia arriba en contra de la gravedad hacia el corazón, la sangre fluye hacia atrás y se acumula en las extremidades, causando hinchazón, venas varicosas prominentes y dolor continuo.", whatIs: { title: "¿Qué es la Insuficiencia Venosa Crónica (IVC)?", text: "Es una condición progresiva de los vasos sanguíneos. Las venas de las piernas tienen pequeñas válvulas unidireccionales para mantener la sangre circulando hacia el corazón. Cuando estas válvulas se vuelven débiles o se dañan, la sangre se estanca (reflujo venoso) aumentando la presión en las piernas." }, symptoms: { title: "Síntomas y Señales Físicas", intro: "Los síntomas suelen empeorar hacia el final del día o después de estar de pie y mejoran al acostarse:", groups: [ { name: "Síntomas sensoriales en las piernas", items: ["Dolor sordo, pesadez extrema o sensación de fatiga profunda en las piernas y las pantorrillas", "Calambres intensos en las piernas por la noche (espasmos musculares) y síndrome de piernas inquietas", "Dolor punzante o ardor continuo en la zona de las pantorrillas, que se alivia inmediatamente al levantar las piernas", "Fuerte picazón (prurito) recurrente a lo largo de las venas"] }, { name: "Signos visuales de deterioro", items: ["Hinchazón (edema) progresiva en la parte inferior de las piernas, tobillos y pies, especialmente por la tarde", "Aparición de venas varicosas (venas abultadas, retorcidas y moradas en la superficie de la piel) y arañas vasculares", "Cambios en el color y la textura de la piel en tobillos o espinillas (se vuelve gruesa, escamosa y de color marrón oscuro debido al depósito de hierro de los glóbulos rojos descompuestos)", "Úlceras varicosas (llagas abiertas) cerca de los tobillos que son muy difíciles de curar"] } ], warning: "El desarrollo de úlceras abiertas que no sanan cerca de los tobillos indica una etapa avanzada de la enfermedad (Estadio 6) con alto riesgo de infección ósea severa." }, types: { title: "Clasificación de Severidad (Sistema CEAP)", intro: "El daño venoso avanza en seis niveles estandarizados internacionalmente:", items: ["C0 y C1: Sin signos visibles iniciales, seguidos por la aparición de pequeñas telangiectasias (arañas vasculares).", "C2 y C3: Presencia clara de venas varicosas palpables prominentes, y posteriormente, desarrollo de hinchazón (edema).", "C4: Alteraciones irreversibles de la piel y tejido subcutáneo (pigmentación marrón, eczema venoso y endurecimiento profundo de la piel).", "C5 y C6: Etapa avanzada con la aparición de úlceras cicatrizadas en los tobillos (C5) o úlceras activas que no sanan y supuran (C6)."], note: "El tratamiento conservador temprano evita que el paciente llegue a las etapas crónicas de ulceración de la piel." }, causes: { title: "Causas y Factores de Riesgo", intro: "Cualquier cosa que aumente la presión sobre las venas o dañe las válvulas, como:", items: ["Antecedentes de un coágulo de sangre previo en la pierna (Trombosis Venosa Profunda o TVP), la cual daña irremediablemente las válvulas venosas (Síndrome postrombótico)", "Permanecer de pie o sentado en la misma posición durante períodos prolongados en el trabajo (cajeros, cirujanos, guardias)", "Genética y debilidad hereditaria de las paredes venosas", "Embarazos múltiples (por la presión abdominal y los altos niveles de progesterona que relajan las venas)", "Sobrepeso crónico u obesidad masiva", "Envejecimiento y falta generalizada de actividad física y tono muscular en las pantorrillas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un angiólogo o cirujano vascular realiza el diagnóstico definitivo mediante:", items: ["Examen físico clínico exhaustivo de las piernas en posición de pie para observar el patrón de hinchazón, venas dilatadas y la decoloración de la piel", "Ecografía Doppler Dúplex Venosa (El estándar de oro no invasivo). Esencial para visualizar directamente si las válvulas están filtrando sangre hacia abajo (reflujo) y detectar bloqueos o coágulos profundos", "Tomografía computarizada (TC) o resonancia magnética (RM) venosa en casos complejos donde se sospecha una compresión pélvica profunda (como el Síndrome de May-Thurner)"], note: "La ecografía Doppler es completamente indolora y proporciona un mapa exacto para decidir el mejor enfoque quirúrgico si es necesario." }, treatment: { title: "Terapias de Soporte y Cirugía Vascular", intro: "El tratamiento no puede reparar una válvula dañada, pero puede mejorar drásticamente el flujo y los síntomas:", subsections: [ { title: "Manejo desde el hogar hasta el quirófano", items: ["Uso constante de medias de compresión graduada (medicinales, no estéticas) que aplican una fuerte presión en el tobillo para empujar la sangre hacia arriba (es el pilar absoluto del tratamiento)", "Elevación estricta de las piernas por encima del nivel del corazón varias veces al día y evitar el sedentarismo", "Medicamentos flebotónicos (como la diosmina) para mejorar temporalmente el tono venoso y ayudar con el dolor o la hinchazón pesada", "Escleroterapia (inyección de una espuma química para colapsar y cerrar venas superficiales dañadas o arañas vasculares)", "Ablación endovenosa térmica (con láser o radiofrecuencia): El tratamiento moderno preferido para cerrar la vena safena enferma desde el interior mediante un catéter", "Flebectomía ambulatoria (extracción de varices grandes a través de microincisiones en la piel bajo anestesia local)"] } ], note: "Las cirugías tradicionales abiertas ('stripping') hoy en día se realizan raramente, siendo reemplazadas por tratamientos láser de recuperación ultrarrápida." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Cirujano Vascular?", intro: "Debe solicitar asistencia de un especialista vascular de forma oportuna si:", items: ["La pesadez en las piernas y el dolor son intensos y limitan sus actividades diarias", "Comienza a notar que la piel de sus tobillos o espinillas se vuelve de color marrón, rojo escamoso o muy áspera y dura", "Se desarrollan llagas abiertas, pústulas o sangrado frecuente en la parte inferior de su pierna", "Las medias de compresión básicas y los descansos con las piernas en alto ya no proporcionan alivio a la hinchazón"] } },
'Pérdida auditiva relacionada con la edad' : { intro: "La pérdida auditiva relacionada con la edad, o presbiacusia, es una disminución gradual y natural de la capacidad para escuchar que afecta a uno de cada tres adultos mayores de 65 años. El problema principal no es solo la pérdida de volumen, sino la falta de claridad: los sonidos agudos se pierden, haciendo que las conversaciones parezcan murmullos incomprensibles.", whatIs: { title: "¿Qué es la Presbiacusia?", text: "Es un tipo de pérdida auditiva neurosensorial, progresiva, bilateral y permanente, asociada directamente con el envejecimiento del sistema auditivo. Se produce por la lenta destrucción o desgaste de las delicadas células ciliadas del oído interno (cóclea) que traducen las ondas sonoras en señales nerviosas cerebrales." }, symptoms: { title: "Síntomas y Retos de Comunicación", intro: "Dado que es un proceso muy lento, la persona a menudo no lo nota al principio, pero su familia sí:", groups: [ { name: "Problemas con la comprensión del habla", items: ["Sensación constante de que la gente 'murmura' o no pronuncia bien las palabras", "Las voces de mujeres y niños pequeños (sonidos agudos) son especialmente difíciles de entender", "Dificultad severa para seguir conversaciones o entender el habla cuando hay ruido de fondo, como en restaurantes o reuniones ruidosas", "Incapacidad para distinguir ciertas consonantes agudas de sonido similar (como la 's', 'f', 't', 'p' y 'sh')"] }, { name: "Cambios en el comportamiento diario", items: ["Tener que subir inusualmente alto el volumen del televisor, la radio o el teléfono (causando molestias a otros)", "Pedir frecuentemente a las personas que repitan lo que acaban de decir", "Sensación molesta de zumbido, pitido incesante o rugido en uno o ambos oídos (tinnitus)", "Aislamiento social extremo: el afectado evita fiestas, conversaciones telefónicas o reuniones por fatiga mental y miedo a responder incorrectamente"] } ], warning: "La pérdida auditiva severa no tratada en personas mayores está vinculada estrechamente con un riesgo mucho mayor y una progresión más rápida de aislamiento, depresión grave y demencia." }, types: { title: "Naturaleza de la Condición", intro: "Esta pérdida de audición tiene características distintivas frente a otros problemas de oído:", items: ["Es bilateral y simétrica: Afecta a ambos oídos de manera aproximadamente igual. Si la pérdida de audición es repentina o ocurre solo en un oído, NO es presbiacusia y requiere atención médica inmediata para descartar tumores o infecciones.", "Es progresiva: Nunca mejora de forma natural y avanza lentamente con la edad.", "Es neurosensorial: Implica daño al nervio o a las células ciliadas profundas, a diferencia de la pérdida 'conductiva' causada por cera, fluidos o daños en el tímpano."], note: "La pérdida progresiva de las frecuencias altas es la marca registrada clásica de la presbiacusia." }, causes: { title: "Causas y Factores Aceleradores", intro: "Es principalmente un proceso de desgaste natural de las partes mecánicas y nerviosas del oído, agravado por:", items: ["Envejecimiento natural: La causa subyacente más común (degeneración de las células ciliadas en la cóclea)", "Acumulación de exposición a ruidos fuertes (trauma acústico crónico): Toda una vida trabajando en entornos ruidosos, escuchando música alta o uso de maquinaria pesada sin protección", "Factores hereditarios (la genética influye en cuán pronto y cuán rápido se degradará la audición)", "Afecciones médicas asociadas (la presión arterial alta, la diabetes o enfermedades cardiovasculares reducen el suministro vital de sangre a la cóclea, acelerando su muerte celular)", "Uso histórico de medicamentos ototóxicos (ciertos antibióticos potentes o drogas de quimioterapia que dañan el oído de forma permanente)"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El diagnóstico clínico requiere un especialista para confirmar la presbiacusia y descartar causas curables:", items: ["Examen físico del canal auditivo (otoscopia) por un médico para descartar rápidamente un simple tapón de cera (cerumen), infecciones de oído u otros problemas mecánicos del tímpano", "Prueba con diapasón (prueba de Weber y Rinne) para una evaluación de detección inicial", "Audiometría tonal completa: La prueba definitiva realizada por un audiólogo en una cabina insonorizada. El paciente usa auriculares y levanta la mano ante tonos en diferentes frecuencias y volúmenes, generando un audiograma detallado", "Pruebas de reconocimiento de voz o discriminación del habla para evaluar qué tan bien comprende las palabras el cerebro del paciente"], note: "El audiograma típicamente mostrará una curva descendente característica, revelando una caída dramática en la capacidad de escuchar tonos altos." }, treatment: { title: "Opciones y Ayudas Auditivas", intro: "Aunque la pérdida celular es médicamente irreversible, la amplificación y rehabilitación son muy exitosas:", subsections: [ { title: "Soluciones de amplificación y adaptación", items: ["Audífonos digitales (el tratamiento fundamental): Pequeños ordenadores miniaturizados programados por un audiólogo para amplificar selectivamente y de forma inteligente solo las frecuencias agudas que el paciente ha perdido, mientras filtran el ruido de fondo (no solo suben el volumen como los aparatos antiguos).", "Implantes cocleares: Reservados como tratamiento quirúrgico para personas con pérdida auditiva neurosensorial profunda donde los audífonos más potentes ya no proporcionan ninguna ayuda para entender el habla.", "Dispositivos de asistencia auditiva: Teléfonos con amplificadores especiales, auriculares Bluetooth para la televisión o sistemas de alerta visuales (luces intermitentes para timbres o alarmas de humo).", "Rehabilitación aural (logopedia): Entrenamiento para ayudar a las personas y a sus familias a adaptar estrategias de comunicación (mirar la cara para leer los labios sutilmente, reducir ruidos de fondo, hablar claro pero sin gritar).", "Lectura de labios y uso de aplicaciones móviles de transcripción de voz a texto en tiempo real para apoyar en situaciones muy difíciles."] } ], note: "Retrasar el uso de audífonos (por negación o vanidad estética) hace que el cerebro del paciente 'olvide' cómo procesar los sonidos correctamente, dificultando drásticamente el uso de audífonos en el futuro." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Médico o Audiólogo?", intro: "Usted (o un familiar) debe programar una prueba auditiva profesional urgente si:", items: ["Comienza a frustrarse regularmente en situaciones sociales y prefiere quedarse en casa porque el esfuerzo por entender a otros lo agota", "Otras personas le comentan a menudo que usted habla inusualmente alto o tiene el volumen del televisor a niveles ensordecedores", "Frecuentemente escucha que le hablan pero cree firmemente que las personas están 'murmurando' en voz muy baja", "Sufre una pérdida de audición brusca, dolor agudo, vértigo severo, supuración del oído o el problema es en un solo oído (banderas rojas neurológicas)"] } },
'Cardiomiopatía dilatada' : { intro: "La cardiomiopatía dilatada es una enfermedad grave y progresiva del músculo cardíaco. Provoca que el ventrículo izquierdo (la cámara principal de bombeo del corazón) se estire, se agrande y se vuelva delgado y débil, perdiendo drásticamente su fuerza para bombear sangre a los pulmones y al cuerpo.", whatIs: { title: "¿Qué es la Cardiomiopatía Dilatada?", text: "Es el tipo más común de enfermedad del músculo cardíaco (miocardiopatía). El problema se origina porque el músculo de la cavidad principal del corazón se dilata como un globo viejo y pierde su capacidad contráctil. Esto puede conducir a insuficiencia cardíaca, arritmias mortales y formación de coágulos." }, symptoms: { title: "Síntomas y Signos de Insuficiencia", intro: "Los pacientes pueden estar años sin síntomas, pero una vez que el corazón comienza a fallar, la fatiga y el exceso de líquido se vuelven extremos:", groups: [ { name: "Síntomas relacionados con el flujo y líquidos (Insuficiencia Cardíaca)", items: ["Falta severa de aire (disnea) con un esfuerzo físico mínimo o al intentar realizar tareas domésticas básicas", "Dificultad aguda para respirar al acostarse plano en la cama (ortopnea), lo que obliga a dormir sentado o usando múltiples almohadas", "Despertar abruptamente a mitad de la noche con sensación de asfixia, pánico y necesidad de buscar aire (disnea paroxística nocturna)", "Hinchazón notable y progresiva (edema) en piernas, tobillos, pies, y aumento masivo de peso por acumulación de líquido en el abdomen"] }, { name: "Síntomas sistémicos y eléctricos", items: ["Fatiga insuperable, agotamiento extremo y debilidad profunda (debido al bajo oxígeno llegando a los músculos)", "Palpitaciones anormales del corazón (sensación de aleteo, latidos acelerados o pérdida de un latido)", "Mareos frecuentes, sensación de aturdimiento y episodios de desmayo (síncope)"] } ], warning: "Un aumento de peso repentino (ej. 2-3 libras en un día), acompañado de fuerte falta de aire, indica que los pulmones se están llenando de líquido: acuda a emergencias de inmediato." }, types: { title: "Complicaciones Mayores de la Dilatación", intro: "Un corazón agrandado y débil es terreno fértil para complicaciones graves:", items: ["Insuficiencia cardíaca progresiva e intratable (la consecuencia inevitable y principal de la dilatación).", "Arritmias cardíacas peligrosas, incluyendo fibrilación auricular o ritmos anormales que pueden causar un paro cardíaco súbito.", "Tromboembolismo (formación de coágulos de sangre letales dentro de las cavidades del corazón debido a que la sangre se estanca, los cuales pueden dispararse al cerebro y causar un ACV masivo).", "Problemas de válvulas cardíacas: Al dilatarse el ventrículo, arrastra las puertas de las válvulas (válvula mitral) impidiendo que se cierren, causando una fuga hacia atrás (regurgitación mitral severa)."], note: "Es la causa más frecuente que conduce a la necesidad de un trasplante de corazón en todo el mundo." }, causes: { title: "Causas y Orígenes", intro: "El daño al músculo cardíaco que provoca esta debilidad tiene múltiples orígenes (a menudo la causa exacta nunca se encuentra, y se le llama 'idiopática'):", items: ["Genética (hasta 1/3 de los casos son heredados de padres a hijos, conocidos como miocardiopatía dilatada familiar)", "Infecciones virales previas que atacaron directamente el músculo cardíaco causando inflamación severa (Miocarditis viral)", "Ataques cardíacos graves pasados (Cardiopatía isquémica) que dejaron cicatrices muertas y obligaron al resto del corazón a estirarse en compensación", "Enfermedades autoinmunes (Lupus, enfermedad celíaca, sarcoidosis)", "Abuso crónico y severo de alcohol o uso de drogas ilícitas (cocaína, anfetaminas)", "Efecto tóxico por el uso prolongado de ciertos medicamentos de quimioterapia contra el cáncer (como doxorrubicina)", "Miocardiopatía periparto (una forma rara que ocurre en mujeres en el último mes de embarazo o justo después del parto)"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El cardiólogo determinará la función exacta del bombeo del corazón (Fracción de Eyección) mediante pruebas precisas:", items: ["Ecocardiograma (ultrasonido del corazón): La prueba esencial de diagnóstico que mostrará instantáneamente las cavidades cardíacas abultadas y débiles, las fugas en las válvulas, y calculará qué tan pobre es el bombeo de sangre (Fracción de Eyección reducida)", "Radiografía de tórax (detecta fácilmente si el corazón en sí está agrandado y si hay derrames de líquido en los pulmones)", "Electrocardiograma (ECG) para detectar las arritmias constantes derivadas de la enfermedad", "Resonancia Magnética cardíaca (RM) que ayuda a identificar cicatrices diminutas y si la causa es inflamatoria o genética", "Cateterismo cardíaco o biopsia (estudios invasivos) para examinar la anatomía interna, abrir vasos bloqueados o tomar una pequeña muestra del tejido muscular del corazón para detectar inflamaciones o problemas genéticos raros", "Análisis de sangre genéticos (especialmente indicados si el paciente tiene familiares que fallecieron súbitamente a temprana edad)"], note: "Una Fracción de Eyección normal es del 50-70%; los pacientes con cardiomiopatía dilatada suelen tener niveles alarmantemente inferiores (20-40%)." }, treatment: { title: "Opciones Médicas e Intervenciones Quirúrgicas", intro: "Aunque la curación estructural rara vez es posible, se trata vigorosamente con medicamentos e intervenciones prolongando años la supervivencia:", subsections: [ { title: "Pilares del manejo", items: ["Terapias farmacológicas intensivas para Insuficiencia Cardíaca: Inhibidores de la ECA, bloqueadores de receptores de angiotensina II, inhibidores de la neprilisina (Entresto), betabloqueantes, inhibidores de SGLT2 y aldosterona. Estos medicamentos reducen drásticamente la carga de trabajo del corazón débil.", "Diuréticos recetados de por vida para eliminar la sobrecarga y estancamiento masivo de líquido del cuerpo a través de la orina.", "Anticoagulantes de prescripción obligatoria para prevenir los coágulos si el paciente desarrolló la arritmia de fibrilación auricular o tiene coágulos visibles en el corazón.", "Procedimientos con dispositivos: Colocación de un Desfibrilador Automático Implantable (DAI) bajo la piel del pecho para prevenir la muerte súbita reiniciando el corazón si ocurre una arritmia mortal, o un marcapasos biventricular (TRC) para resincronizar los latidos y mejorar el bombeo.", "Intervención quirúrgica avanzada final: Colocación de una bomba mecánica externa (Dispositivo de Asistencia Ventricular Izquierda o DAVI) como apoyo, o un Trasplante de Corazón definitivo si el paciente es elegible y todos los medicamentos han fracasado."] } ], note: "La abstinencia absoluta de alcohol, una restricción severa y controlada de la ingesta diaria de líquidos y de sal (sodio) son absolutamente obligatorias para la supervivencia." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Cardiólogo Inmediatamente?", intro: "Considere su estado inestable y solicite evaluación médica urgente si presenta:", items: ["Problemas serios para recuperar el aliento realizando tareas triviales o en reposo absoluto", "Despertarse repetidas y abruptamente en medio de la noche tosiendo o asfixiándose", "Desmayo repentino inexplicado, pulso acelerado o sentir el pecho revoloteando salvajemente y a punto de colapsar", "Crecimiento progresivo del abdomen o que sus zapatos/anillos ya no le quedan debido a un inicio rápido de hinchazón dura en piernas o manos"] } },
'Tumores o protuberancias en las mamas' : { intro: "Los tumores o protuberancias en las mamas son masas de tejido que se desarrollan en el seno. Aunque descubrir un bulto puede generar gran ansiedad, la inmensa mayoría son de naturaleza benigna (no cancerosos), aunque siempre requieren una evaluación médica oportuna para un diagnóstico certero.", whatIs: { title: "¿Qué son los Tumores mamarios?", text: "Son crecimientos o masas de tejido anormal dentro de la glándula mamaria. Pueden estar compuestos por tejido glandular sólido, tejido conectivo fibroso, o ser sacos llenos de líquido (quistes). Su aparición y tamaño suelen estar fuertemente influenciados por los ciclos hormonales." }, symptoms: { title: "Síntomas y Características", intro: "Las características del bulto al tacto son fundamentales para la evaluación inicial:", groups: [ { name: "Características físicas", items: ["Presencia de un bulto palpable, que puede sentirse gomoso, firme o como una uva blanda", "El bulto puede ser móvil (se desliza bajo la piel) o estar adherido y fijo al tejido profundo", "Sensibilidad, dolor o pesadez en el área, especialmente en los días previos a la menstruación"] }, { name: "Signos de advertencia (Banderas rojas)", items: ["Cambios en la textura de la piel del seno (como hoyuelos o apariencia de 'piel de naranja')", "Retracción del pezón (el pezón se hunde repentinamente hacia adentro)", "Secreción espontánea por el pezón, especialmente si es sanguinolenta o de un solo seno"] } ], warning: "Cualquier bulto nuevo que se sienta duro como una piedra, indoloro y con bordes irregulares debe ser evaluado urgentemente por un especialista." }, types: { title: "Tipos Comunes", intro: "Los bultos mamarios se clasifican en varias categorías según su composición:", items: ["Quistes mamarios: Sacos redondos llenos de líquido, muy comunes y benignos.", "Fibroadenomas: Tumores sólidos, lisos y benignos, muy frecuentes en mujeres jóvenes.", "Papilomas intraductales: Pequeños crecimientos similares a verrugas dentro de un conducto de leche cerca del pezón.", "Mastopatía fibroquística: Áreas grumosas y dolorosas generalizadas relacionadas con el ciclo menstrual.", "Cáncer de mama: Tumores malignos que requieren tratamiento oncológico inmediato."], note: "Es imposible saber con certeza si un bulto es benigno o maligno solo con tocarlo; las pruebas de imagen son obligatorias." }, causes: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de estas protuberancias suele estar estrechamente ligado a:", items: ["Fluctuaciones normales de las hormonas reproductivas (estrógeno y progesterona) a lo largo de la vida", "Uso prolongado de terapias de reemplazo hormonal o pastillas anticonceptivas", "Infecciones del tejido mamario (mastitis, que puede formar un absceso o bulto lleno de pus, común durante la lactancia)", "Traumatismos o golpes fuertes en el pecho (pueden causar necrosis grasa, que se siente como un bulto)", "Antecedentes familiares de enfermedades mamarias benignas o malignas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para determinar la naturaleza de la protuberancia, el médico utiliza la llamada 'triple evaluación':", items: ["Examen físico clínico de ambas mamas y palpación de los ganglios linfáticos en las axilas", "Estudios de imagen: Ecografía mamaria (ideal para diferenciar entre quistes líquidos y masas sólidas, y para mujeres jóvenes) y Mamografía", "Resonancia magnética (RM) mamaria en casos complejos o en mujeres con tejido mamario extremadamente denso", "Biopsia por punción: Extracción de una pequeña muestra de tejido con aguja bajo anestesia local para análisis microscópico si la masa es sólida"], note: "Si la ecografía confirma sin lugar a dudas que se trata de un quiste simple de líquido, a menudo no se requiere biopsia." }, treatment: { title: "Opciones de Tratamiento", intro: "El manejo depende exclusivamente del diagnóstico exacto del bulto:", subsections: [ { title: "Tratamientos según el tipo", items: ["Observación clínica: Muchos quistes pequeños y fibroadenomas indoloros no requieren tratamiento y solo se monitorean periódicamente.", "Aspiración con aguja fina: Se utiliza para drenar el líquido de un quiste grande o doloroso, lo que generalmente lo hace desaparecer por completo.", "Cirugía (Tumorectomía): Extirpación quirúrgica del bulto si es muy grande, si crece rápidamente, causa dolor o si la biopsia muestra células atípicas o cáncer.", "Tratamiento con antibióticos y drenaje: Si la protuberancia es causada por una infección bacteriana (absceso)."] } ], note: "Familiarizarse con el aspecto y tacto normal de sus senos (autoconciencia mamaria) es vital para detectar cambios a tiempo." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Mastólogo o Ginecólogo?", intro: "Solicite una evaluación médica sin demora si:", items: ["Descubre un bulto o engrosamiento nuevo y diferente en el seno o en el área de la axila", "Un bulto preexistente no desaparece, crece o cambia de forma después de su ciclo menstrual", "Nota enrojecimiento, descamación, calor o costras en la piel del seno o en la areola", "Observa que una de sus mamas cambia drásticamente de tamaño o forma de manera repentina"] } },
'Dedos en garra' : { intro: "Los dedos en garra son una deformidad dolorosa del pie en la que las articulaciones de los dedos pequeños se flexionan y curvan de manera anormal, adquiriendo la apariencia de la garra de un animal. Esta condición dificulta caminar cómodamente y encontrar calzado adecuado debido a la fricción constante.", whatIs: { title: "¿Qué son los Dedos en garra?", text: "Es una deformidad estructural en la que los dedos del pie (generalmente desde el segundo hasta el quinto) se doblan hacia arriba en la articulación donde el dedo se une al pie, y luego se curvan bruscamente hacia abajo en las articulaciones medias y distales, clavándose en el suelo." }, symptoms: { title: "Síntomas y Molestias", intro: "Los síntomas progresan de una molestia estética a un dolor limitante:", groups: [ { name: "Deformidad visible", items: ["Los dedos adoptan una forma encorvada permanente en forma de 'C' invertida", "Dificultad progresiva para estirar los dedos de los pies de forma voluntaria", "En etapas tempranas los dedos son flexibles y se pueden enderezar con la mano; en etapas avanzadas, se vuelven completamente rígidos"] }, { name: "Dolor y lesiones en la piel", items: ["Dolor intenso al caminar o usar zapatos cerrados", "Formación de callos gruesos y dolorosos (helomas) en la parte superior del dedo (por el roce con el zapato) y en la punta del dedo (por la presión contra el suelo)", "Aparición de llagas o úlceras abiertas si la fricción es muy severa"] } ], warning: "Si padece diabetes, un callo en un dedo en garra puede convertirse rápidamente en una úlcera infectada grave que pone en riesgo el dedo; requiere atención podológica urgente." }, types: { title: "Fases de la Deformidad", intro: "La afección se clasifica según la movilidad de las articulaciones:", items: ["Dedos en garra flexibles: Las articulaciones aún se pueden mover manualmente. Es la etapa ideal para iniciar el tratamiento conservador y evitar la cirugía.", "Dedos en garra rígidos: Los tendones se han acortado tanto y las articulaciones se han calcificado de tal forma que los dedos están fijos en la posición de garra. Generalmente requieren corrección quirúrgica."], note: "Se diferencian del 'dedo en martillo' porque el dedo en garra afecta a ambas articulaciones del dedo, no solo a la articulación media." }, causes: { title: "Causas y Factores Biomecánicos", intro: "La deformidad es el resultado de un desequilibrio entre los músculos y tendones que controlan los dedos:", items: ["Uso prolongado de zapatos inadecuados (zapatos demasiado cortos, apretados o tacones altos que empujan los dedos contra la punta del zapato)", "Daño a los nervios (neuropatía) causado frecuentemente por la diabetes o el alcoholismo, lo que debilita los músculos del pie", "Afecciones neurológicas que alteran el tono muscular (parálisis cerebral, polio, accidente cerebrovascular)", "Problemas estructurales del pie (tener el arco del pie inusualmente alto o pies planos muy pronunciados)", "Enfermedades inflamatorias de las articulaciones, como la artritis reumatoide"] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "El diagnóstico es principalmente clínico por parte de un podólogo o traumatólogo:", items: ["Examen físico visual detallado de los pies mientras el paciente está de pie y sentado", "Evaluación de la flexibilidad de los dedos manipulando suavemente cada articulación para clasificar si es una garra flexible o rígida", "Pruebas neurológicas básicas en el pie (para verificar la sensibilidad y descartar daño a los nervios por diabetes)", "Radiografías (Rayos X) del pie para observar la estructura ósea exacta y descartar artritis severa en las articulaciones afectadas"], note: "El médico también revisará minuciosamente el calzado habitual del paciente para identificar factores agravantes." }, treatment: { title: "Tratamientos Ortopédicos y Quirúrgicos", intro: "El tratamiento depende de cuán rígidos estén los dedos:", subsections: [ { title: "Opciones según la etapa", items: ["Cambios en el calzado: Usar zapatos con una puntera ancha, profunda y sin tacón para evitar que el zapato presione la parte superior de los dedos.", "Dispositivos ortopédicos: Uso de plantillas a medida, almohadillas protectoras (tubos de silicona) para evitar callos, y férulas nocturnas para estirar los dedos flexibles.", "Fisioterapia: Ejercicios específicos (como usar los dedos de los pies para recoger canicas o arrugar una toalla) para fortalecer y estirar los músculos intrínsecos del pie.", "Cuidado podológico regular: Recorte y alisado profesional de los callos dolorosos.", "Cirugía ortopédica: Para dedos rígidos, el cirujano puede alargar o reubicar los tendones, o realizar una artrodesis (fusionar los huesos del dedo para mantenerlo permanentemente recto)."] } ], note: "Tratar de cortar o arrancar los callos en casa con cuchillas puede provocar infecciones peligrosas." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Podólogo?", intro: "Es altamente recomendable agendar una revisión si:", items: ["Nota que sus dedos están empezando a curvarse y le resulta incómodo estirarlos", "Desarrolla callos dolorosos o llagas rojas en la parte superior o en las puntas de los dedos", "Siente dolor punzante en el pie al caminar, lo que le obliga a alterar su forma normal de pisar", "Tiene diabetes y nota cualquier deformidad o enrojecimiento nuevo en sus pies"] } },
'Anemia por deficiencia de hierro en los niños' : { intro: "La anemia por deficiencia de hierro es el problema nutricional infantil más frecuente a nivel global. Ocurre cuando el niño no tiene suficiente hierro para fabricar hemoglobina, reduciendo el oxígeno en la sangre y provocando fatiga constante, palidez y, si es severa, retrasos en el desarrollo cognitivo y motor.", whatIs: { title: "¿Qué es esta Anemia Infantil?", text: "Es una disminución de los glóbulos rojos sanos debido a una carencia de hierro. Sin suficiente hierro, la médula ósea no puede producir hemoglobina (la proteína roja encargada de transportar oxígeno). Como resultado, los órganos y tejidos del niño no reciben el oxígeno necesario para crecer y funcionar." }, symptoms: { title: "Síntomas y Alertas Conductuales", intro: "Los niños pueden adaptarse a la anemia leve sin síntomas, pero al empeorar se observa:", groups: [ { name: "Síntomas físicos", items: ["Palidez marcada en la piel, el interior de los labios, las encías y debajo de las uñas", "Cansancio inexplicable, letargo y falta de energía para jugar", "Manos y pies frecuentemente fríos", "Ritmo cardíaco acelerado (el corazón bombea más rápido para compensar la falta de oxígeno) o mareos al ponerse de pie"] }, { name: "Alteraciones en el desarrollo y comportamiento", items: ["Irritabilidad constante y dificultad para calmar al niño", "Pica (un trastorno alimentario donde el niño tiene ansias irresistibles de comer hielo, tierra, arcilla o papel)", "Retraso en alcanzar hitos del desarrollo motor o problemas de atención en la escuela", "Pérdida de apetito recurrente"] } ], warning: "La deficiencia severa de hierro en los años cruciales de formación (0 a 3 años) puede causar déficits permanentes en el coeficiente intelectual y el comportamiento si no se trata a tiempo." }, types: { title: "Etapas de la Carencia", intro: "El proceso ocurre gradualmente antes de llegar a la anemia total:", items: ["Fase 1 (Agotamiento de reservas): Disminuye la ferritina (el hierro almacenado), pero los análisis de hemoglobina aún salen normales.", "Fase 2 (Eritropoyesis deficiente en hierro): Las reservas se agotan y la médula ósea empieza a fabricar glóbulos rojos de menor calidad.", "Fase 3 (Anemia clínica manifiesta): Cae la hemoglobina; los glóbulos rojos son pequeños (microcíticos) y pálidos (hipocrómicos). Los síntomas físicos aparecen claramente."], note: "Los exámenes de rutina en el primer año de vida están diseñados para atrapar el problema en las primeras fases." }, causes: { title: "Causas y Factores de Riesgo", intro: "El cuerpo del niño en crecimiento demanda mucho hierro; las carencias se deben a:", items: ["Dieta pobre en hierro: Frecuente tras los 6 meses si la lactancia materna exclusiva no se complementa con alimentos ricos en hierro, o en niños muy selectivos para comer.", "Consumo excesivo de leche de vaca: La leche de vaca bloquea la absorción de hierro y no contiene hierro; si un niño pequeño bebe demasiada, se llena y rechaza la comida sólida nutritiva.", "Periodos de crecimiento acelerado: Los bebés prematuros, los lactantes y las niñas adolescentes (por el inicio de la menstruación) requieren más hierro de lo habitual.", "Problemas de absorción gástrica: Condiciones como la enfermedad celíaca o problemas intestinales.", "Pérdida de sangre silenciosa: Sangrado intestinal microscópico provocado por una reacción a proteínas de la leche de vaca entera administrada antes del primer año de vida."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra realiza un diagnóstico certero mediante pruebas de sangre:", items: ["Biometría hemática completa (Hemograma): Revela niveles bajos de hemoglobina y glóbulos rojos inusualmente pequeños y pálidos.", "Prueba de Ferritina: Mide las reservas reales de hierro en el cuerpo; es la prueba más sensible para detectar la deficiencia temprana.", "Examen físico buscando palidez, frecuencia cardíaca anormal y evaluando la curva de crecimiento y desarrollo del niño."], note: "Es vital no autodiagnosticar ni dar suplementos de hierro a un niño sin pruebas de sangre, ya que el exceso de hierro es sumamente tóxico para los menores." }, treatment: { title: "Tratamiento y Reeducación Alimentaria", intro: "El tratamiento requiere reponer las reservas médicas y mejorar la dieta diaria:", subsections: [ { title: "Intervenciones clínicas y dietéticas", items: ["Suplementación oral: Gotas o jarabes de hierro recetados por el pediatra (generalmente sulfato ferroso) durante 3 a 6 meses para rellenar completamente las reservas corporales.", "Mejora en la absorción: Dar el hierro junto con vitamina C (como jugo de naranja o fresas) y separarlo completamente de la ingesta de leche o suplementos de calcio, que bloquean su absorción.", "Ajustes dietéticos: Incluir carnes rojas magras, hígado, pollo, legumbres (lentejas, frijoles) y cereales infantiles fortificados con hierro.", "Reducción de lácteos: Limitar la leche de vaca a un máximo de 500-700 ml (16-24 onzas) al día en niños pequeños para fomentar el apetito por alimentos sólidos."] } ], note: "Se advertirá a los padres que el suplemento de hierro típicamente tiñe las heces del niño de un color negro oscuro inofensivo." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Pediatra?", intro: "Programe una cita para una evaluación nutricional y de sangre si su hijo:", items: ["Luce notablemente pálido y se cansa mucho más rápido que otros niños de su misma edad", "Presenta el hábito extraño de masticar hielo, papel o tierra de manera insistente", "Basa su dieta casi exclusivamente en leche de biberón y rechaza sistemáticamente las carnes y vegetales", "Tiene un retraso evidente en sus habilidades para hablar, caminar o interactuar socialmente"] } },
'Estreñimiento en niños' : { intro: "El estreñimiento en niños es un problema pediátrico sumamente común y frustrante. Se caracteriza por evacuaciones intestinales poco frecuentes, duras y dolorosas. A menudo comienza cuando el niño retiene voluntariamente las heces por miedo al dolor o porque no quiere interrumpir su tiempo de juego.", whatIs: { title: "¿Qué es el Estreñimiento Infantil?", text: "Es una alteración en el patrón de las deposiciones, donde el niño tiene menos de tres evacuaciones por semana, o sus heces son grandes, secas, duras y difíciles de expulsar. Esta condición causa incomodidad abdominal significativa y puede llevar a un ciclo vicioso de retención y más dolor." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Los síntomas van más allá de la simple falta de evacuación diaria:", groups: [ { name: "Problemas con las deposiciones", items: ["Evacuaciones intestinales dolorosas que hacen llorar o quejarse al niño", "Heces muy duras, secas o en forma de bolitas pequeñas (como de conejo)", "Heces tan anchas y voluminosas que pueden obstruir el inodoro", "Rastros de sangre roja brillante en el papel higiénico o en la superficie de las heces (por pequeñas fisuras anales)"] }, { name: "Comportamientos y síntomas físicos", items: ["'Comportamiento de retención': el niño cruza las piernas, aprieta los glúteos, se pone de puntillas o hace muecas para evitar hacer caca", "Dolor de estómago constante que mejora temporalmente después de una evacuación grande", "Manchas de heces líquidas en la ropa interior (encopresis), que ocurren cuando heces blandas se filtran alrededor de un tapón de heces duras retenidas", "Falta de apetito o irritabilidad inusual"] } ], warning: "Si el estreñimiento se acompaña de fiebre, vómitos, pérdida de peso, o un abdomen severamente hinchado y duro, se requiere atención médica de emergencia." }, types: { title: "Causas y Contextos Frecuentes", intro: "Existen etapas críticas en la infancia donde el estreñimiento es más probable que comience:", items: ["Transición alimentaria: Al pasar de la leche materna/fórmula a los alimentos sólidos, o al cambiar de la cuna a alimentos con baja fibra.", "Entrenamiento para ir al baño (Control de esfínteres): Si el proceso es estresante o se presiona al niño antes de que esté listo, puede rebelarse reteniendo las heces.", "El inicio de la etapa escolar: Muchos niños sienten aversión o vergüenza por usar los baños públicos de la escuela y retienen las ganas hasta llegar a casa.", "Estreñimiento funcional (más del 90% de los casos): No hay una enfermedad subyacente; el problema es conductual o dietético."], note: "Rara vez (menos del 5%), el estreñimiento crónico severo desde el nacimiento es causado por problemas nerviosos intestinales como la enfermedad de Hirschsprung." }, causes: { title: "Desencadenantes Comunes", intro: "El ciclo del estreñimiento suele originarse por una combinación de factores:", items: ["Retención voluntaria: La causa número uno. Si un niño tuvo una evacuación dolorosa, asociará el baño con dolor y retendrá instintivamente las siguientes deposiciones, lo que hace que las heces se sequen y duelan aún más al salir.", "Dieta pobre en fibra: Alta ingesta de ultraprocesados, comida rápida, dulces, y escasez de frutas, verduras y granos enteros.", "Falta de hidratación: No beber suficiente agua pura durante el día.", "Cambios en la rutina: Viajes, estrés familiar, o climas muy calurosos que causan deshidratación.", "Ciertos medicamentos: Suplementos de hierro, algunos antiácidos o medicamentos para el TDAH.", "Alergia a la proteína de la leche de vaca (en algunos niños pequeños)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra diagnostica la condición principalmente mediante la historia clínica:", items: ["Entrevista detallada con los padres sobre la dieta del niño, hábitos de baño y cuándo comenzó el problema", "Examen físico del abdomen para palpar masas de heces duras retenidas", "Inspección visual del área anal para detectar fisuras (pequeños desgarros dolorosos)", "Rara vez se necesitan radiografías de abdomen, a menos que el médico necesite confirmar la cantidad de retención fecal ('impactación')"], note: "El médico buscará diferenciar si el problema de ensuciar la ropa interior es por rebosamiento (estreñimiento severo) o por otros problemas de comportamiento." }, treatment: { title: "Manejo y Reeducación Intestinal", intro: "Curar el estreñimiento crónico lleva meses y requiere paciencia, dieta y laxantes pediátricos:", subsections: [ { title: "Pilares del Tratamiento", items: ["Desimpactación médica (fase inicial): Si el niño está muy bloqueado, el médico recetará laxantes orales fuertes (como polietilenglicol) o supositorios/enemas infantiles para limpiar el intestino acumulado de forma segura.", "Mantenimiento con laxantes osmóticos: Uso diario y prolongado de ablandadores de heces suaves (como Miralax/Macrogol o lactulosa) para mantener las heces blandas y sin dolor, rompiendo el miedo psicológico del niño a evacuar. (Estos no causan dependencia).", "Reentrenamiento intestinal: Sentar al niño en el inodoro durante 5 a 10 minutos después de las comidas (aprovechando el reflejo gastrocólico natural), asegurándose de que tenga un taburete bajo los pies para que las rodillas estén más altas que las caderas.", "Modificaciones en la dieta: Aumentar drásticamente el consumo de agua y alimentos ricos en fibra (ciruelas pasas, peras, frijoles, avena), y reducir temporalmente el exceso de lácteos y plátanos.", "Sistemas de recompensa: Usar tablas de pegatinas para premiar al niño por sentarse e intentarlo, sin castigarlo nunca por accidentes o ensuciar la ropa."] } ], note: "Retirar los medicamentos ablandadores demasiado pronto es la causa más común de recaída; el intestino necesita meses para encogerse a su tamaño normal." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Pediatra?", intro: "Es fundamental consultar al médico si el estreñimiento dura más de dos semanas o se acompaña de:", items: ["Sangre roja y fresca mezclada con las heces o goteando en la taza del inodoro", "Manchas constantes de heces líquidas y malolientes en la ropa interior de un niño que ya controlaba esfínteres", "El niño experimenta dolor abdominal severo o vómitos de color verde/amarillo", "Pérdida de peso inexplicable o el niño se niega sistemáticamente a comer", "Aparición de tejido que sobresale por el ano (prolapso rectal)"] } },
'Influenza' : { intro: "La influenza, comúnmente conocida como la gripe, es una infección respiratoria viral altamente contagiosa. Aunque a menudo se confunde con el resfriado común, la influenza ataca de forma repentina y mucho más violenta, pudiendo causar complicaciones graves como neumonía, especialmente en grupos vulnerables.", whatIs: { title: "¿Qué es la Influenza (La Gripe)?", text: "Es una enfermedad respiratoria aguda causada por los virus de la influenza que infectan la nariz, la garganta y, a veces, los pulmones. A diferencia de un resfriado (que se desarrolla lentamente), la gripe golpea de repente, causando fiebre alta y dolores corporales severos." }, symptoms: { title: "Síntomas y Características", intro: "Los síntomas de la influenza aparecen repentinamente e incluyen:", groups: [ { name: "Síntomas sistémicos principales", items: ["Fiebre alta (a menudo por encima de 38°C o 100.4°F) y escalofríos intensos", "Dolores musculares y articulares severos (mialgia), frecuentemente en la espalda, brazos y piernas", "Fatiga extrema y debilidad que puede durar semanas, obligando al paciente a guardar cama", "Dolor de cabeza intenso"] }, { name: "Síntomas respiratorios y gastrointestinales", items: ["Tos seca y persistente que puede volverse severa", "Dolor de garganta irritante", "Congestión o secreción nasal (más común en niños que en adultos)", "Algunos niños pueden presentar vómitos y diarrea, pero esto es raro en adultos"] } ], warning: "Dificultad repentina para respirar, dolor en el pecho, confusión mental o labios azulados son emergencias médicas absolutas durante un cuadro de gripe." }, types: { title: "Tipos de Virus de la Influenza", intro: "Existen varios tipos de virus que causan brotes estacionales o pandemias:", items: ["Influenza Tipo A: El más común y el más grave. Es responsable de las pandemias mundiales (como la H1N1) porque muta rápidamente y también infecta a animales (aves, cerdos).", "Influenza Tipo B: Causa brotes estacionales de gripe y solo afecta a los humanos. Los síntomas son similares al tipo A pero generalmente menos severos.", "Influenza Tipo C: Causa enfermedades respiratorias muy leves, a menudo sin síntomas, y no provoca epidemias.", "Influenza Tipo D: Afecta principalmente al ganado y no se sabe que cause enfermedades en humanos."], note: "La vacuna contra la gripe estacional (anual) está diseñada específicamente para proteger contra las cepas circulantes proyectadas de los virus A y B." }, causes: { title: "Transmisión y Contagio", intro: "El virus de la influenza es agresivo y se propaga con extremada facilidad:", items: ["Transmisión por gotas: Las personas infectadas transmiten el virus al toser, estornudar o hablar, esparciendo gotas invisibles que aterrizan en las bocas o narices de las personas cercanas (hasta a 2 metros de distancia).", "Contacto con superficies: Tocar una superficie u objeto (manijas de puertas, teléfonos) que tiene el virus y luego tocarse la propia boca, nariz o los ojos.", "Período de contagio: Los adultos son contagiosos desde 1 día antes de que comiencen los síntomas hasta 5 a 7 días después de enfermarse. Los niños pueden ser contagiosos por más tiempo.", "El virus sobrevive y se propaga mejor en climas fríos y secos, razón por la cual la temporada de gripe alcanza su punto máximo en invierno."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente, los médicos diagnostican la gripe basándose en los síntomas y la presencia del virus en la comunidad, pero pueden usar pruebas:", items: ["Pruebas Rápidas de Diagnóstico de Influenza (RIDT): Se usa un hisopo largo para tomar una muestra de la parte posterior de la nariz o la garganta. Ofrece resultados en 15 minutos, pero puede dar falsos negativos.", "Ensayos Moleculares Rápidos (PCR): Mucho más precisos que las pruebas rápidas tradicionales, detectan el material genético del virus en hospitales o clínicas.", "Evaluación clínica de complicaciones: El médico usará un estetoscopio para escuchar los pulmones buscando signos tempranos de neumonía, o prescribirá una radiografía de tórax si hay dificultad para respirar."], note: "El tratamiento antiviral es más efectivo si se inicia temprano, por lo que a menudo se prescribe basándose solo en los síntomas clínicos." }, treatment: { title: "Manejo, Tratamiento y Prevención", intro: "El tratamiento se centra en aliviar los síntomas y prevenir complicaciones mayores:", subsections: [ { title: "Tratamientos y cuidados", items: ["Descanso absoluto en cama y aislamiento en casa para evitar contagiar a otros", "Hidratación abundante (agua, caldos, electrolitos) para evitar la deshidratación por la fiebre", "Medicamentos de venta libre (paracetamol o ibuprofeno) para controlar la fiebre y el dolor muscular (Nunca dar aspirina a niños o adolescentes por el riesgo de Síndrome de Reye)", "Medicamentos Antivirales recetados (como oseltamivir/Tamiflu, zanamivir o baloxavir): Pueden acortar la enfermedad en 1 o 2 días y prevenir complicaciones graves como la neumonía si se toman dentro de las primeras 48 horas tras el inicio de los síntomas", "Prevención: La vacunación anual es la herramienta más efectiva para prevenir la infección grave, especialmente crucial para embarazadas, ancianos, niños pequeños y personas con enfermedades crónicas (asma, diabetes)"] } ], note: "Los antibióticos son completamente inútiles contra los virus de la gripe, a menos que el paciente desarrolle una infección bacteriana secundaria como la neumonía." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Urgencias Médicas?", intro: "La gripe puede ser mortal. Busque atención médica inmediata si usted o su hijo presentan:", items: ["Dificultad grave para respirar, falta de aire o dolor severo en el pecho/abdomen", "Mareos repentinos, confusión profunda, letargo extremo o incapacidad para despertar (especialmente en niños)", "Vómitos severos o persistentes que impiden retener líquidos", "Síntomas de gripe que parecen mejorar, pero luego regresan abruptamente con una fiebre altísima y una tos mucho peor", "Convulsiones (en niños)"] } },
'Cifoescoliosis' : { intro: "La cifoescoliosis es una deformidad compleja de la columna vertebral que combina dos curvaturas anormales simultáneas: una corvadura hacia adelante (cifosis o 'joroba') y una desviación lateral en forma de 'S' o 'C' (escoliosis). Puede causar desde asimetría estética leve hasta problemas cardíacos y respiratorios graves en casos severos.", whatIs: { title: "¿Qué es la Cifoescoliosis?", text: "Es una afección ortopédica tridimensional de la columna. El paciente presenta tanto una curvatura lateral (escoliosis) como una curvatura excesiva hacia atrás en la región torácica (cifosis). Esta deformidad combinada altera significativamente la postura, la caja torácica y la alineación general del tronco." }, symptoms: { title: "Síntomas y Alteraciones Posturales", intro: "La gravedad de los síntomas está directamente relacionada con el grado de la curva:", groups: [ { name: "Signos físicos y ortopédicos", items: ["Postura marcadamente encorvada acompañada de inclinación hacia un lado", "Asimetría evidente: Un hombro, escápula (omóplato) o cadera parece estar mucho más alto o prominente que el otro", "Apariencia de joroba pronunciada en la espalda al inclinarse hacia adelante", "Dolor de espalda crónico, rigidez muscular y fatiga extrema tras permanecer de pie o sentado"] }, { name: "Complicaciones sistémicas (En casos severos)", items: ["Dificultad para respirar profundamente o falta de aire (la deformidad de la caja torácica restringe la capacidad de los pulmones para expandirse)", "Infecciones respiratorias recurrentes debido a la mala ventilación pulmonar", "Presión sobre el corazón, afectando su capacidad para bombear sangre eficientemente (cor pulmonale)", "Problemas digestivos o neurológicos si la curva comprime órganos internos o nervios espinales"] } ], warning: "El desarrollo de dificultad respiratoria en reposo o debilidad y entumecimiento en las piernas requiere evaluación médica urgente y a menudo intervención quirúrgica." }, types: { title: "Tipos por Origen", intro: "La cifoescoliosis puede aparecer en cualquier etapa de la vida, dependiendo de su causa:", items: ["Idiopática: La forma más común, aparece sin causa conocida durante el estirón de crecimiento de la adolescencia (cifoescoliosis del adolescente).", "Congénita: Presente desde el nacimiento debido a un desarrollo anormal de los huesos de la columna (vértebras malformadas) en el útero.", "Neuromuscular: Causada por trastornos subyacentes que afectan los nervios o músculos, impidiendo que sostengan la columna (parálisis cerebral, distrofia muscular, espina bífida).", "Degenerativa: Aparece en adultos mayores debido a osteoporosis severa, desgaste de los discos y fracturas por compresión de las vértebras."], note: "Las formas neuromusculares y congénitas tienden a ser más agresivas y progresar más rápido que la forma idiopática." }, causes: { title: "Causas y Factores de Progresión", intro: "El origen estructural se debe a diversas patologías óseas o musculares:", items: ["Malformación de las vértebras fetales (fallo de formación o de segmentación)", "Desequilibrios musculares severos alrededor de la columna debido a afecciones neurológicas", "Enfermedades del tejido conectivo (como el Síndrome de Marfan o el Síndrome de Ehlers-Danlos)", "Traumatismos espinales graves, tumores vertebrales o infecciones profundas (como tuberculosis espinal)", "Desgaste asimétrico por osteoporosis severa en la tercera edad"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El traumatólogo ortopedista requiere imágenes precisas para evaluar las curvas:", items: ["Examen físico inicial: Evaluación de la postura y prueba de flexión hacia adelante de Adam (para revelar prominencias o jorobas asimétricas)", "Radiografías de columna completa (frente y perfil): Fundamentales para medir los ángulos exactos de la escoliosis (Ángulo de Cobb) y la cifosis, y monitorear su progresión", "Resonancia magnética (RM) de la columna: Usada sistemáticamente para descartar anomalías en la médula espinal (como tumores o quistes) que puedan estar causando la curva", "Pruebas de función pulmonar (espirometría): Esenciales para medir si la deformidad está comprometiendo la capacidad pulmonar del paciente", "Ecocardiograma si se sospecha compromiso o compresión cardíaca"], note: "El seguimiento radiológico regular es vital en niños y adolescentes en crecimiento para interceptar una progresión rápida." }, treatment: { title: "Opciones Ortopédicas y Quirúrgicas", intro: "El tratamiento busca detener la progresión de la curva y prevenir daños a los pulmones y el corazón:", subsections: [ { title: "Enfoque escalonado del tratamiento", items: ["Observación y Fisioterapia: Para curvas leves. Incluye ejercicios específicos para fortalecer el núcleo y mejorar la postura, aunque no curan ni corrigen la deformidad ósea.", "Uso de corsé ortopédico (Bracing): El tratamiento estándar para niños y adolescentes que aún están creciendo y tienen curvas moderadas. Deben usar el corsé rígido hecho a medida entre 16 y 23 horas al día para evitar que la curva empeore.", "Cirugía de fusión espinal: El tratamiento definitivo para curvas severas (generalmente mayores de 45-50 grados), progresivas o que causan problemas respiratorios. El cirujano utiliza varillas, tornillos y ganchos de metal para enderezar la columna y fusionar las vértebras con injertos óseos, formando un solo hueso sólido.", "Manejo del dolor en adultos con inyecciones de corticosteroides, medicamentos o terapia física dirigida si la cirugía no es una opción."] } ], note: "La cirugía de fusión espinal es compleja, pero corrige drásticamente la deformidad y mejora la calidad de vida a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Especialista en Columna?", intro: "Se debe buscar una evaluación ortopédica especializada si:", items: ["Nota que los hombros, caderas o cintura de su hijo adolescente están desnivelados o asimétricos", "El paciente experimenta dolor de espalda que se vuelve constante e incapacitante", "Aparece dificultad repentina para respirar o cansancio extremo al realizar actividades cotidianas leves", "Nota una alteración repentina en la forma de caminar o pérdida de sensibilidad y fuerza en las piernas"] } },
'Estenosis mitral' : { intro: "La estenosis mitral es una enfermedad grave de las válvulas del corazón. Ocurre cuando la válvula mitral se engrosa y se estrecha, bloqueando el flujo adecuado de sangre y provocando que esta se acumule en los pulmones. Históricamente es una secuela directa de la fiebre reumática sufrida en la infancia.", whatIs: { title: "¿Qué es la Estenosis Mitral?", text: "Es el estrechamiento de la abertura de la válvula mitral, que separa las dos cámaras del lado izquierdo del corazón (la aurícula y el ventrículo). Este estrechamiento impide que la sangre fluya libremente hacia la cámara de bombeo principal, causando un aumento masivo de presión hacia atrás, inundando los pulmones con líquido." }, symptoms: { title: "Síntomas Cardíacos y Respiratorios", intro: "Los síntomas pueden tardar décadas en aparecer tras el daño inicial, y se agravan con el estrés físico:", groups: [ { name: "Síntomas de congestión pulmonar", items: ["Dificultad progresiva para respirar (disnea), especialmente durante el esfuerzo físico o el ejercicio", "Falta de aire intensa al acostarse en la cama (ortopnea), requiriendo dormir con varias almohadas", "Despertarse abruptamente por la noche sintiendo que se asfixia (disnea paroxística nocturna)", "Tos persistente, que a veces puede producir esputo teñido de sangre (hemoptisis)"] }, { name: "Síntomas sistémicos de fallo cardíaco", items: ["Fatiga extrema y debilidad paralizante al intentar hacer actividades cotidianas", "Palpitaciones o sensación de latidos cardíacos irregulares, rápidos y desordenados (fibrilación auricular)", "Hinchazón notoria (edema) en los pies, tobillos y acumulación de líquido en el abdomen", "Aparición de un tono púrpura oscuro o azulado en las mejillas (facies mitral) en casos muy avanzados"] } ], warning: "La estenosis mitral conlleva un riesgo elevadísimo de desarrollar coágulos de sangre en el corazón que pueden viajar al cerebro y causar un derrame cerebral masivo." }, types: { title: "Complicaciones Clínicas", intro: "El bloqueo del flujo sanguíneo desata una reacción en cadena en el corazón y pulmones:", items: ["Hipertensión pulmonar: La sangre atascada aumenta peligrosamente la presión en las arterias de los pulmones.", "Insuficiencia cardíaca derecha: Como resultado de la presión pulmonar, el lado derecho del corazón se agota y falla, causando hinchazón en el cuerpo.", "Fibrilación auricular (FA): El estiramiento de la aurícula izquierda altera el sistema eléctrico, provocando que la cámara tiemble caóticamente en lugar de latir, lo que forma coágulos de sangre.", "Edema pulmonar agudo: Inundación repentina y potencialmente mortal de los pulmones con líquido."], note: "El embarazo, debido al aumento del volumen de sangre, puede hacer que una estenosis mitral previamente silenciosa se vuelva sintomática y peligrosa rápidamente." }, causes: { title: "Causas y Origen Histórico", intro: "A diferencia de otras enfermedades valvulares, la causa principal está muy bien definida:", items: ["Fiebre reumática: Es, con abrumadora diferencia, la causa principal. Es una complicación autoinmune de una infección de garganta por estreptococos no tratada en la infancia. El sistema inmune ataca y cicatriza las válvulas del corazón décadas antes de que aparezcan los síntomas.", "Calcificación relacionada con la edad: Acumulación severa de calcio en el anillo de la válvula en adultos mayores (aunque rara vez causa estenosis severa por sí sola).", "Defectos cardíacos congénitos: Muy raros, donde los bebés nacen con una válvula mitral estrecha.", "Otras causas inusuales: Radioterapia previa en el tórax por cáncer, enfermedades autoinmunes graves como el lupus o artritis reumatoide, o tumores cardíacos benignos (mixomas) que bloquean la válvula."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El cardiólogo puede detectar el problema inicialmente usando un estetoscopio y confirmarlo con pruebas:", items: ["Auscultación: Escuchar un soplo cardíaco característico (un chasquido de apertura seguido de un retumbo sordo) que indica el paso turbulento de la sangre por la válvula estrecha", "Ecocardiograma (Ultrasonido cardíaco): Es el estándar de oro y la prueba más importante. Visualiza directamente las valvas engrosadas, mide el área de apertura exacta de la válvula y evalúa la presión en los pulmones", "Electrocardiograma (ECG): Para detectar latidos irregulares (fibrilación auricular) o agrandamiento de las cámaras del corazón", "Radiografía de tórax: Para observar el agrandamiento del corazón o la presencia de líquido en los pulmones", "Ecocardiograma transesofágico (ETE): Un ecógrafo insertado por el esófago para obtener imágenes de altísima resolución de la válvula y buscar coágulos ocultos antes de una cirugía"], note: "Cualquier persona con antecedentes infantiles de fiebre reumática debe someterse a ecocardiogramas periódicos en la edad adulta." }, treatment: { title: "Manejo Médico y Corrección Quirúrgica", intro: "Los medicamentos controlan los síntomas, pero reparar la válvula mecánicamente es la única cura:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicación sintomática: Diuréticos (para eliminar el líquido de los pulmones e hinchazón de las piernas), betabloqueantes o digoxina (para ralentizar el corazón y tratar la fibrilación auricular), y anticoagulantes obligatorios (para prevenir derrames cerebrales letales si hay fibrilación auricular).", "Valvuloplastia mitral con globo (percutánea): Tratamiento no quirúrgico de primera línea. Se guía un catéter con un globo desinflado desde la ingle hasta el corazón; el globo se infla en la válvula para romper el tejido cicatricial y ensanchar la apertura. Ideal para válvulas que aún son flexibles.", "Comisurotomía o reparación quirúrgica a corazón abierto: El cirujano corta las partes fusionadas de la válvula o elimina depósitos de calcio para restaurar la apertura.", "Reemplazo de la válvula mitral: Si la válvula está demasiado destruida, rígida o calcificada, se extirpa mediante cirugía a corazón abierto y se sustituye por una válvula artificial mecánica (requiere anticoagulantes de por vida) o biológica (de tejido animal)."] } ], note: "La valvuloplastia con globo puede retrasar la necesidad de una cirugía mayor durante muchos años con excelentes resultados." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias?", intro: "Es crítico buscar atención médica de emergencia si experimenta:", items: ["Falta de aliento repentina, extrema y aterradora (sensación de ahogo inminente), especialmente si está acostado", "Dolor punzante o presión severa en el pecho, junto con palpitaciones muy rápidas e irregulares", "Tos repentina que produce esputo espumoso de color rosado o con sangre brillante", "Desmayo repentino o aparición súbita de parálisis, confusión o problemas para hablar (síntomas de derrame cerebral por un coágulo)"] } },
'Enfermedad cerebrovascular' : { intro: "La enfermedad cerebrovascular engloba varios trastornos que afectan peligrosamente los vasos sanguíneos que irrigan el cerebro. Esta afección es la principal responsable del deterioro cognitivo por falta de riego y la precursora directa de los accidentes cerebrovasculares (derrames), representando una de las mayores causas de mortalidad mundial.", whatIs: { title: "¿Qué es la Enfermedad Cerebrovascular?", text: "Es un grupo de condiciones caracterizadas por la alteración o interrupción del flujo sanguíneo normal hacia el tejido cerebral. Ocurre cuando las arterias que nutren el cerebro se bloquean, se estrechan peligrosamente, sufren malformaciones o se rompen, privando a las neuronas del oxígeno vital." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Los síntomas dependen de qué vaso esté afectado y cuán grave sea el bloqueo de oxígeno:", groups: [ { name: "Síntomas progresivos o crónicos", items: ["Deterioro paulatino de las habilidades de pensamiento, memoria o concentración (demencia vascular temprana)", "Mareos frecuentes, problemas de equilibrio o episodios de vértigo inexplicables", "Dolores de cabeza crónicos severos o latidos en los oídos (acúfenos)"] }, { name: "Síntomas agudos (AIT o pre-derrame)", items: ["Pérdida temporal de la visión en un ojo (amaurosis fugaz), a menudo descrita como una 'cortina' que cae sobre el ojo", "Episodios breves (Ataques Isquémicos Transitorios - AIT) de debilidad, entumecimiento repentino en un lado de la cara o el cuerpo", "Dificultad súbita y temporal para articular palabras o comprender el habla", "Estos síntomas pueden durar minutos u horas y desaparecer, pero son la máxima advertencia de un derrame inminente"] } ], warning: "Un Ataque Isquémico Transitorio (AIT) es una emergencia médica absoluta; tener uno significa que un derrame cerebral mayor y permanente es inminente en los próximos días." }, types: { title: "Condiciones Cerebrovasculares Principales", intro: "Esta enfermedad general incluye varias patologías específicas de los vasos:", items: ["Estenosis carotídea: Estrechamiento severo de las grandes arterias carótidas en el cuello por placas de colesterol, restringiendo el flujo principal al cerebro.", "Aneurismas cerebrales: Abultamiento o globo en la pared débil de una arteria cerebral que corre el riesgo inminente de estallar y causar una hemorragia letal.", "Malformaciones arteriovenosas (MAV): Enredos anormales de vasos sanguíneos en el cerebro presentes desde el nacimiento que pueden sangrar.", "Enfermedad de vasos pequeños: Daño microvascular por hipertensión prolongada, principal causa de la demencia vascular.", "Accidente Cerebrovascular (ACV): La culminación aguda de la enfermedad cerebrovascular, donde el tejido muere (infarto) por falta total de sangre o hemorragia."], note: "El control estricto de la presión arterial es la defensa más poderosa contra todos estos tipos de enfermedades." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño progresivo a las arterias cerebrales se debe casi siempre a la aterosclerosis (placa vascular) y al estilo de vida:", items: ["Presión arterial alta crónica no controlada (Hipertensión), el factor que más daña y debilita las arterias del cerebro", "Colesterol alto persistente, que forma las placas que bloquean las arterias carótidas", "Fibrilación auricular (ritmo cardíaco irregular) y otras enfermedades cardíacas", "Tabaquismo intenso (aumenta drásticamente la formación de placas y debilita la pared de los aneurismas)", "Diabetes mellitus (los altos niveles de azúcar dañan el endotelio de los vasos sanguíneos finos del cerebro)", "Factores no modificables: Edad avanzada, antecedentes familiares de derrames, y enfermedades hereditarias de la coagulación o del tejido conectivo"] }, diagnosis: { title: "¿Cómo se Diagnostica Preventivamente?", intro: "Para evitar un derrame, los médicos investigan la salud de las arterias cerebrales mediante:", items: ["Ecografía Doppler de las arterias carótidas: Una prueba rápida, indolora y vital que usa ondas sonoras para detectar si las arterias del cuello están estrechadas u obstruidas por colesterol", "Angiografía por Tomografía Computarizada (ATC) o Angiografía por Resonancia Magnética (ARM): Imágenes 3D avanzadas que muestran mapas detallados de los vasos sanguíneos del cuello y el cerebro para detectar aneurismas, estenosis o malformaciones", "Angiografía cerebral convencional: Prueba invasiva donde se inyecta contraste a través de un catéter guiado hasta el cerebro para obtener imágenes exactas de bloqueos o aneurismas", "Electrocardiograma (ECG) o monitor Holter para descartar que el problema provenga de coágulos del corazón (arritmias)"], note: "A menudo, se descubren estenosis carotídeas severas al escuchar un 'soplo' en el cuello con un estetoscopio durante un examen físico de rutina." }, treatment: { title: "Tratamiento Médico y Quirúrgico", intro: "El enfoque es estrictamente preventivo, buscando limpiar las arterias o reparar los defectos antes de que ocurra un daño cerebral agudo:", subsections: [ { title: "Intervenciones preventivas y correctivas", items: ["Control médico agresivo: Medicamentos antiplaquetarios (aspirina, clopidogrel) o anticoagulantes para evitar coágulos, estatinas de alta potencia para reducir y estabilizar las placas de colesterol, y medicamentos para la presión arterial.", "Endarterectomía carotídea: Cirugía abierta en el cuello donde el cirujano abre la arteria carótida, 'raspa' y extrae físicamente la placa de colesterol acumulada para restaurar el flujo libre al cerebro.", "Angioplastia y colocación de stent: Procedimiento menos invasivo donde se infla un globo para abrir la arteria estrecha y se deja una malla metálica (stent) para mantenerla abierta.", "Tratamiento de aneurismas: Embolización endovascular (colocación de espirales/coils de platino a través de un catéter para bloquear el flujo al aneurisma) o clipaje quirúrgico craneal (abrir el cráneo para poner un clip en el cuello del globo y evitar que estalle)."] } ], note: "La endarterectomía reduce masivamente el riesgo de sufrir un derrame cerebral en personas con estenosis carotídea superior al 70%." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias?", intro: "Cualquier signo neurológico agudo es una emergencia absoluta. Llame al 911/emergencias si experimenta:", items: ["Caída repentina de un lado de la cara al intentar sonreír", "Debilidad o entumecimiento súbito en un brazo o pierna, imposibilitando levantarlos", "Dificultad repentina, incluso por unos segundos, para hablar, pronunciar palabras o entender lo que le dicen", "Pérdida brusca y temporal de la visión en un ojo, como si bajara una persiana", "Dolor de cabeza explosivo, el peor de su vida, sin causa conocida (signo inconfundible de aneurisma roto)"] } },
'Trombocitopenia' : { intro: "La trombocitopenia es una afección de la sangre en la que se tiene un recuento anormalmente bajo de plaquetas, las células microscópicas encargadas de detener las hemorragias. Dependiendo de su gravedad, puede variar desde una condición asintomática hasta un problema potencialmente mortal que provoca sangrados internos incontrolables.", whatIs: { title: "¿Qué es la Trombocitopenia?", text: "Es una deficiencia del número de plaquetas en la sangre circulante. Las plaquetas (o trombocitos) se agrupan y forman coágulos o tapones temporales en los vasos sanguíneos lesionados. Un nivel normal es de 150,000 a 450,000 plaquetas por microlitro; la trombocitopenia se diagnostica cuando hay menos de 150,000." }, symptoms: { title: "Síntomas y Señales de Alerta de Sangrado", intro: "Los síntomas solo aparecen cuando los niveles de plaquetas son preocupantemente bajos (a menudo por debajo de 50,000):", groups: [ { name: "Síntomas en la piel y mucosas", items: ["Aparición espontánea, rápida y fácil de moretones grandes (equimosis o púrpura) sin haber sufrido golpes fuertes", "Sarpullido de manchas del tamaño de la cabeza de un alfiler, rojizas o púrpuras, generalmente en la parte inferior de las piernas (petequias)", "Sangrado prolongado, inusual e imparable por cortes menores o raspaduras", "Sangrado espontáneo y frecuente de las encías (al cepillarse) o de la nariz"] }, { name: "Signos de sangrado severo interno", items: ["Presencia de sangre en la orina (hematuria) o heces oscuras, negras o con sangre roja fresca", "Flujos menstruales inusualmente prolongados o extremadamente abundantes (menorragia)", "Dolor de cabeza repentino, intenso o confusión (indicativo del riesgo más grave: sangrado cerebral)", "Fatiga severa y debilidad"] } ], warning: "Un recuento de plaquetas por debajo de 10,000 es una emergencia hematológica extrema, ya que puede ocurrir una hemorragia cerebral espontánea y fatal." }, types: { title: "Mecanismos Subyacentes de la Deficiencia", intro: "El número de plaquetas baja por tres razones principales:", items: ["Problemas de producción: La médula ósea no fabrica suficientes plaquetas (debido a leucemia, anemia aplásica, toxinas, infecciones virales severas o falta de vitamina B12/ácido fólico).", "Destrucción aumentada: El sistema inmunológico se confunde y destruye las plaquetas sanas en la sangre (Púrpura Trombocitopénica Inmunitaria/Idiopática o por reacción a medicamentos graves).", "Atrapamiento de plaquetas: El bazo (un órgano que filtra la sangre) se agranda, actúa como una esponja y atrapa demasiadas plaquetas, retirándolas de la circulación (a menudo causado por cirrosis hepática severa)."], note: "El embarazo a veces causa una caída leve y temporal en el recuento de plaquetas que se resuelve tras el parto (trombocitopenia gestacional)." }, causes: { title: "Causas y Desencadenantes Comunes", intro: "Esta condición es a menudo un síntoma de un trastorno médico subyacente:", items: ["Enfermedades autoinmunes graves como Lupus o Artritis Reumatoide, donde los anticuerpos atacan las plaquetas", "Tratamientos contra el cáncer (quimioterapia y radioterapia), que suprimen agresivamente la capacidad de la médula ósea para fabricar plaquetas", "Consumo excesivo crónico de alcohol, que deprime la producción de plaquetas y causa daño hepático que agranda el bazo", "Efecto secundario grave de ciertos medicamentos (como la heparina, la quinina o ciertos antibióticos y anticonvulsivos)", "Infecciones virales sistémicas fuertes como la Hepatitis C, VIH, Epstein-Barr, o enfermedades transmitidas por mosquitos como el Dengue grave", "Exposición a productos químicos tóxicos industriales como pesticidas, benceno o arsénico"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico para determinar cuán bajo es el nivel y por qué se produce incluye:", items: ["Biometría hemática completa (Hemograma): La prueba principal que cuenta exactamente cuántas plaquetas hay en la sangre", "Frotis de sangre periférica: Observación de una gota de sangre bajo el microscopio para verificar la apariencia de las plaquetas y descartar enfermedades de la sangre raras", "Examen físico buscando agrandamiento del bazo (palpando el abdomen) y evidencia de sangrados en la piel (petequias)", "Aspirado y biopsia de médula ósea: Un procedimiento especializado para evaluar si la fábrica de células sanguíneas en el centro de los huesos está sana o infiltrada por cáncer", "Análisis de sangre para detectar infecciones subyacentes (VIH, Hepatitis) o anticuerpos destructores de plaquetas"], note: "Es vital repasar todos los medicamentos y suplementos que toma el paciente, ya que suspender la pastilla correcta a menudo cura el problema." }, treatment: { title: "Manejo Médico y Prevención de Hemorragias", intro: "El tratamiento es específico a la causa y la gravedad de la deficiencia:", subsections: [ { title: "Opciones de Tratamiento", items: ["Observación cautelosa (para casos leves y asintomáticos) evitando medicamentos que alteren la coagulación como aspirina, ibuprofeno o naproxeno", "Medicamentos inmunosupresores: Corticosteroides (prednisona) como primera línea para detener la destrucción inmunológica de las plaquetas", "Inmunoglobulina intravenosa (IGIV) para un aumento rápido, aunque temporal, del recuento de plaquetas en situaciones de emergencia", "Medicamentos estimuladores de plaquetas (agonistas del receptor de la trombopoyetina como eltrombopag) que obligan a la médula ósea a producir más", "Transfusiones de plaquetas y sangre en la sala de urgencias si hay una hemorragia activa, incontrolable o antes de una cirugía mayor", "Esplenectomía (cirugía para extirpar el bazo) si el bazo es el responsable de destruir o atrapar masivamente las plaquetas y los medicamentos fallan"] } ], note: "Las personas con plaquetas muy bajas deben evitar estrictamente deportes de contacto, usar hilo dental con fuerza o cualquier actividad con alto riesgo de traumatismo." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias?", intro: "Acuda a un hospital de inmediato si usted sabe que tiene plaquetas bajas o si presenta:", items: ["Cualquier sangrado incontrolable que no se detiene aplicando presión constante después de 10 a 15 minutos", "Aparición repentina de un sarpullido generalizado de puntos rojos finos (petequias) o grandes moretones sin haberse golpeado", "Sangre en el vómito, tos con sangre, o heces negras y alquitranadas", "Un golpe fuerte en la cabeza, incluso si se siente bien inicialmente (debido al inmenso riesgo de sangrado cerebral progresivo)"] } },
'Alopecia en hombres' : { intro: "La alopecia en hombres, también conocida como calvicie de patrón masculino, es la causa más común de pérdida de cabello. Aunque es un proceso natural y biológico para millones de hombres a nivel mundial, la pérdida capilar a menudo genera un fuerte impacto emocional y en la autoestima, motivando la búsqueda de tratamientos médicos y estéticos.", whatIs: { title: "¿Qué es la Alopecia Androgenética Masculina?", text: "Es una condición genética y hormonal crónica en la que los folículos pilosos del cuero cabelludo se encogen progresivamente hasta detener la producción de cabello. El cabello nuevo se vuelve cada vez más fino, corto y débil (miniaturización), hasta que los folículos se atrofian por completo de forma permanente." }, symptoms: { title: "Patrón de Pérdida Capilar", intro: "La caída de cabello en este tipo de alopecia sigue un patrón altamente predecible (Escala de Norwood):", groups: [ { name: "Signos progresivos", items: ["Comienza con el adelgazamiento lento del cabello y el retroceso de la línea de implantación capilar en la frente y las sienes (formando las clásicas 'entradas' en forma de 'M')", "Adelgazamiento progresivo y pérdida de densidad en la coronilla (la parte superior trasera de la cabeza o 'coronilla')", "Con el tiempo, las entradas y la calva de la coronilla se unen, dejando una zona completamente calva en la parte superior", "El cabello en los lados y la parte posterior de la cabeza (zona donante) generalmente permanece intacto, ya que esos folículos son genéticamente resistentes a la hormona causante"] } ], warning: "Si la caída de cabello es en parches redondos lisos (alopecia areata), va acompañada de dolor, cicatrices, descamación, o ocurre en todo el cuerpo, requiere evaluación médica por un trastorno inmunológico o sistémico." }, types: { title: "Diferenciación de Causas de Pérdida de Cabello", intro: "No toda pérdida de cabello en hombres es alopecia de patrón masculino:", items: ["Alopecia Androgenética: La calvicie común, progresiva y predecible impulsada por genética y hormonas (más del 95% de los casos en hombres).", "Efluvio telógeno: Caída difusa y repentina en todo el cuero cabelludo desencadenada por estrés extremo, trauma físico, enfermedades graves o medicamentos. Suele ser reversible.", "Alopecia Areata: Enfermedad autoinmune donde el cuerpo ataca sus propios folículos, dejando parches completamente calvos y redondos del tamaño de una moneda.", "Alopecia cicatricial: Inflamación agresiva que destruye el folículo y lo reemplaza con tejido cicatricial brillante, impidiendo el crecimiento permanente."], note: "La presencia de antecedentes familiares de calvicie tanto por el lado materno como paterno es el indicador más fuerte de alopecia androgenética." }, causes: { title: "Causas, Genética y Hormonas", intro: "La calvicie masculina se debe a la sensibilidad heredada a un derivado de la testosterona:", items: ["Dihidrotestosterona (DHT): Es el factor clave. Los folículos pilosos genéticamente susceptibles en la frente y la coronilla son atacados lentamente por la DHT, que acorta la fase de crecimiento del cabello hasta asfixiar el folículo.", "Predisposición Genética: Un rasgo fuertemente hereditario transmitido por los genes de ambos lados de la familia.", "Envejecimiento: La prevalencia aumenta directamente con la edad (afecta hasta al 80% de los hombres a los 80 años).", "La calvicie de patrón masculino NO es causada por usar sombreros, lavarse el cabello frecuentemente, mala circulación o caspa, contrario a los mitos populares."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El dermatólogo o especialista en restauración capilar puede diagnosticarla rápidamente:", items: ["Examen visual clínico y evaluación del patrón de miniaturización usando una escala médica (Norwood-Hamilton)", "Tricoscopia (uso de un dermatoscopio especial para magnificar el cuero cabelludo y examinar el grosor variable de los cabellos individuales y la salud de la piel)", "Prueba de tracción suave para evaluar cuántos cabellos caen fácilmente, ayudando a descartar caídas agudas por estrés (efluvio telógeno)", "Generalmente NO se requieren análisis de sangre ni biopsias, a menos que el médico sospeche de problemas de tiroides, deficiencia de hierro o infecciones por hongos en casos atípicos"], note: "El tratamiento temprano, en las primeras etapas de retroceso, tiene las mejores probabilidades de salvar el cabello restante." }, treatment: { title: "Tratamientos Médicos y Quirúrgicos", intro: "Actuar temprano es crucial; es más fácil mantener el cabello existente que hacer crecer cabello nuevo en zonas ya calvas:", subsections: [ { title: "Enfoques comprobados", items: ["Finasterida o Dutasterida (Oral): Medicamentos recetados que inhiben la enzima que convierte la testosterona en DHT, deteniendo eficazmente la caída en la gran mayoría de los hombres y, a menudo, logrando que el cabello miniaturizado vuelva a crecer grueso.", "Minoxidil (Tópico u Oral): Líquido o espuma que se aplica directamente en el cuero cabelludo dos veces al día para dilatar los vasos sanguíneos y estimular el folículo, prolongando la fase de crecimiento capilar.", "Terapia de Plasma Rico en Plaquetas (PRP): Se extrae sangre del paciente, se procesa para concentrar las plaquetas y se inyecta en el cuero cabelludo para nutrir y estimular los folículos débiles.", "Trasplante Capilar (Técnicas FUE o FUSS): La única solución permanente para restaurar el cabello en zonas ya completamente calvas. El cirujano extrae folículos sanos y resistentes a la DHT de la parte posterior de la cabeza y los implanta uno a uno en las zonas despobladas.", "Láser de baja potencia y terapias cosméticas (fibras capilares, micropigmentación) para mejorar el aspecto visual."] } ], note: "Los medicamentos (Finasterida/Minoxidil) deben usarse de por vida para mantener sus resultados; si se suspenden, la caída del cabello se reanudará en pocos meses." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Dermatólogo?", intro: "Es recomendable consultar a un especialista si:", items: ["Sufre una caída de cabello de inicio rápido y repentino que deja parches calvos o clareos masivos en cuestión de semanas", "El cuero cabelludo muestra enrojecimiento intenso, costras, dolor, picazón severa o descamación evidente junto con la pérdida de cabello", "La pérdida de cabello ocurre de forma atípica (en cejas, pestañas o cuerpo general)", "Desea iniciar un tratamiento médico comprobado para la calvicie y evaluar las opciones de trasplante antes de que la pérdida sea total"] } },
'Absceso de Bartolino' : { intro: "El absceso de Bartolino es una condición ginecológica aguda y muy dolorosa. Se desarrolla en los labios vaginales cuando una pequeña glándula encargada de la lubricación íntima se bloquea y posteriormente se infecta masivamente, formando un bulto lleno de pus que interfiere con el caminar, sentarse o tener relaciones sexuales.", whatIs: { title: "¿Qué es un Absceso de Bartolino?", text: "Es una acumulación dolorosa de pus localizada en una de las glándulas de Bartolino, situadas a cada lado de la abertura vaginal posterior. Ocurre cuando el conducto de la glándula se obstruye, formándose primero un quiste de líquido, que luego es invadido por bacterias, provocando una severa infección." }, symptoms: { title: "Síntomas y Evolución", intro: "La afección progresa rápidamente de una molestia leve a un dolor incapacitante en pocos días:", groups: [ { name: "Síntomas locales intensos", items: ["Aparición de un bulto muy sensible o inflamado en un lado de la entrada de la vagina (labios mayores)", "El bulto crece rápidamente, tornándose caliente al tacto, rojo y extremadamente doloroso", "Dolor agudo e insoportable que empeora drásticamente al sentarse, caminar, rozar la ropa interior o durante las relaciones sexuales", "A veces, el absceso puede romperse por sí solo, produciendo un alivio inmediato del dolor seguido de una secreción de pus espeso y con mal olor"] }, { name: "Síntomas sistémicos (Infección avanzada)", items: ["Fiebre de más de 38°C (100.4°F) y escalofríos", "Hinchazón que se extiende a todo ese lado de la vulva y ganglios linfáticos inflamados en la ingle", "Dificultad e incomodidad profunda al orinar"] } ], warning: "Si el absceso es muy grande, provoca fiebre alta y rayas rojas en la piel vulvar, debe ser drenado urgentemente en emergencias para evitar una sepsis (infección en la sangre)." }, types: { title: "Quiste vs. Absceso", intro: "Es crucial entender la diferencia en la progresión de la glándula bloqueada:", items: ["Quiste de Bartolino (Etapa inicial): El conducto está bloqueado y el líquido lubricante se acumula. Se siente un bulto indoloro, suave y a menudo no requiere tratamiento si no causa molestias.", "Absceso de Bartolino (Etapa infecciosa): Bacterias ingresan al quiste existente. El líquido se convierte en pus a presión, causando dolor agudo, fiebre e inflamación inmediata que exige atención médica urgente."], note: "Es muy común que estos abscesos reaparezcan (recurrencia) si no se realiza un procedimiento adecuado para mantener el conducto abierto permanentemente." }, causes: { title: "Causas y Bacterias Responsables", intro: "El bloqueo inicial suele deberse a inflamación local o mucosa espesa, seguido de infección bacteriana:", items: ["Bacterias intestinales comunes (Escherichia coli o E. coli) que migran desde el ano hacia la zona vaginal, siendo la causa más frecuente", "Infecciones de transmisión sexual (ITS), como la gonorrea (Neisseria gonorrhoeae) o la clamidia (Chlamydia trachomatis), especialmente en mujeres jóvenes activas sexualmente", "Otras bacterias de la piel o del tracto respiratorio (como estafilococos o estreptococos)", "Uso de ropa interior excesivamente ajustada, traumatismos locales menores o mala higiene íntima que favorecen la obstrucción del conducto"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El ginecólogo o médico de urgencias lo diagnostica mediante un examen directo y rápido:", items: ["Examen físico pélvico minucioso: El médico observará y palpará la hinchazón rojiza en la zona de la glándula de Bartolino (suele ser inconfundible por su apariencia y dolor extremo a la palpación)", "Toma de muestras (cultivo de exudado): El médico utilizará un hisopo para recoger una muestra del pus o las secreciones del cuello uterino para identificar la bacteria exacta (E. coli, Gonorrea, Clamidia) y guiar el uso del antibiótico correcto", "Biopsia: Si la paciente tiene más de 40 años o ha pasado por la menopausia, el médico puede enviar un pequeño trozo de tejido de la glándula a analizar para descartar un cáncer vulvar subyacente raro"], note: "El dolor a menudo es tan intenso que las pacientes requieren que el procedimiento de examen sea extremadamente delicado." }, treatment: { title: "Drenaje y Prevención Quirúrgica", intro: "Los antibióticos solos no curan un absceso estructurado; el pus debe ser evacuado físicamente:", subsections: [ { title: "Procedimientos médicos", items: ["Incisión y drenaje simples (para alivio inmediato): El médico hace un pequeño corte bajo anestesia local en el consultorio, exprimiendo el pus. Sin embargo, si solo se hace esto, el absceso casi siempre volverá a formarse al cerrarse la herida.", "Colocación de un Catéter de Word: Es el tratamiento preferido. Tras drenar el pus, se inserta un pequeño tubo de goma con un globo diminuto en la glándula y se deja allí de 4 a 6 semanas. Esto obliga al tejido a sanar alrededor del tubo, creando un nuevo conducto permanente (epitelización) para que los fluidos salgan, evitando recaídas.", "Marsupialización (cirugía): Para abscesos muy grandes o recurrentes. El cirujano abre el quiste, lo vacía, y luego cose los bordes del quiste directamente a la piel vaginal exterior, creando una abertura permanente en forma de bolsa.", "Baños de asiento tibios 3 a 4 veces al día (solo útiles para ayudar a romper un quiste inicial o promover la curación tras la cirugía).", "Terapia con antibióticos orales solo si la celulitis (enrojecimiento cutáneo) es severa, hay fiebre, o si el cultivo resulta positivo para una ITS."] } ], note: "Intentar exprimir o reventar el absceso fuertemente en casa es peligroso y empeorará la inflamación o propagará la infección profundamente." }, whenToSeekHelp: { title: "¿Cuándo Ir al Ginecólogo o Urgencias?", intro: "Busque atención médica el mismo día si:", items: ["Descubre un bulto doloroso cerca de la apertura de la vagina que no mejora tras dos o tres días de baños de asiento tibios", "El dolor se vuelve tan agudo, pulsátil e intenso que no puede sentarse recta ni caminar normalmente", "El bulto va acompañado de escalofríos severos, malestar general o fiebre por encima de 38°C", "El absceso se rompió solo, pero sigue teniendo un dolor intenso, supuración maloliente constante o el área circundante sigue roja e inflamada"] } },
'Trastorno de oposición desafiante' : { intro: "El trastorno de oposición desafiante (TOD) es un trastorno del comportamiento en la infancia. Va mucho más allá de las típicas rabietas infantiles, caracterizándose por un patrón crónico, implacable y destructivo de ira, irritabilidad, hostilidad y desobediencia deliberada dirigida hacia los padres, profesores y figuras de autoridad.", whatIs: { title: "¿Qué es el Trastorno de Oposición Desafiante (TOD)?", text: "Es un trastorno psiquiátrico pediátrico donde el niño exhibe un patrón de comportamiento enfadado, argumentativo y desafiante persistente. Este comportamiento no es solo una fase difícil; interfiere gravemente con el funcionamiento diario del niño, su vida escolar, y causa un estrés extremo y disfunción dentro del núcleo familiar." }, symptoms: { title: "Síntomas y Patrones Conductuales", intro: "Para el diagnóstico, el comportamiento hostil debe durar al menos 6 meses y presentar varios de estos signos:", groups: [ { name: "Estado de ánimo iracundo o irritable", items: ["Pérdida de control de los estribos con extrema facilidad y frecuencia desproporcionada", "Se muestra crónicamente resentido, enfadado, amargado y susceptible (se molesta fácilmente por cosas triviales hechas por otros)", "Reacciones explosivas y hostiles continuas ante la menor frustración o solicitud"] }, { name: "Comportamiento argumentativo y desafiante", items: ["Discute activamente de forma agresiva y constante con los adultos o figuras de autoridad (maestros, padres)", "Se niega activa y desafiantemente a cumplir con las reglas, normas o peticiones simples de los adultos", "Molesta e irrita deliberadamente a otras personas para provocar una reacción", "Culpa constantemente a los demás por sus propios errores, mal comportamiento o malas calificaciones", "Actúa de forma rencorosa o vengativa al menos dos veces en los últimos 6 meses (como destruir la propiedad de un hermano tras una pelea)"] } ], warning: "Si la rebeldía del niño se agrava hasta llegar a la crueldad con los animales, destrucción de propiedades, robos graves o agresión física, el TOD puede estar evolucionando hacia un Trastorno de la Conducta (más grave e ilegal)." }, types: { title: "Gravedad e Impacto", intro: "El TOD varía en intensidad y puede limitarse a un entorno o extenderse:", items: ["TOD Leve: Los síntomas desafiantes y enojados ocurren únicamente en un entorno, generalmente en el hogar familiar.", "TOD Moderado: Algunos comportamientos desafiantes severos ocurren en al menos dos entornos diferentes (ej. en casa y en la escuela, afectando las relaciones y el aprendizaje).", "TOD Grave: Los comportamientos agresivos y de oposición ocurren constantemente en tres o más entornos (casa, escuela, con sus compañeros o en público)."], note: "Es excepcionalmente común que el TOD coexista con el TDAH (Trastorno por Déficit de Atención e Hiperactividad), trastornos de ansiedad o discapacidades del aprendizaje." }, causes: { title: "Causas y Factores Contribuyentes", intro: "No existe una sola causa, es una combinación compleja de factores biológicos, genéticos y ambientales:", items: ["Genética y neurobiología: Fuerte predisposición si en la familia hay antecedentes de TDAH, trastornos del estado de ánimo (depresión/bipolaridad) o problemas graves de abuso de sustancias.", "Disposición natural del niño: Temperamento intrínsecamente difícil, impulsividad extrema o una baja tolerancia innata a la frustración emocional desde edad muy temprana.", "Dinámica familiar y crianza: Prácticas de crianza demasiado duras, inconsistentes, negligentes o extremadamente punitivas, donde la disciplina se aplica con ira.", "Factores ambientales y trauma: Estrés tóxico crónico en el hogar (pobreza, violencia doméstica), abuso emocional/físico, o abandono, que llevan al niño a luchar por el control.", "Déficits en el procesamiento cognitivo de las normas sociales y las emociones ajenas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El psiquiatra o psicólogo infantil debe realizar una evaluación exhaustiva y cuidadosa:", items: ["Entrevistas clínicas en profundidad con los padres, cuidadores y el propio niño para documentar el historial conductual", "Recopilación de información de múltiples fuentes (cuestionarios estandarizados llenados por maestros, cuidadores diurnos y familiares)", "Evaluación psicológica integral para descartar y tratar condiciones coexistentes imperativas (como la ansiedad, el TDAH o la depresión, que a menudo causan la irritabilidad en niños)", "Diferenciar el comportamiento de los cambios de humor esperados o de crisis temporales relacionadas con el desarrollo o eventos estresantes recientes (como un divorcio reciente)"], note: "El diagnóstico nunca se debe basar en un solo incidente de mal comportamiento o un ataque de ira aislado." }, treatment: { title: "Intervenciones y Terapias Especializadas", intro: "El tratamiento no busca castigar al niño, sino reestructurar la dinámica de comunicación familiar completa:", subsections: [ { title: "Terapias conductuales y psicológicas", items: ["Entrenamiento en el manejo de padres (PMT): El tratamiento más crucial. Enseña a los padres técnicas específicas de disciplina positiva, consistencia, establecimiento de límites firmes pero calmados, y cómo reforzar positivamente los comportamientos de colaboración para no entrar en luchas de poder.", "Terapia de Interacción Padres-Hijos (PCIT): Un terapeuta observa la interacción en tiempo real a través de un espejo unidireccional y guía a los padres con un auricular sobre cómo responder a las rabietas o la desobediencia de manera constructiva.", "Terapia Cognitivo-Conductual (TCC) para el niño: Para enseñarle cómo manejar su propia ira incontrolable, identificar sus desencadenantes, resolver problemas de forma no agresiva y mejorar la empatía hacia los demás.", "Entrenamiento en habilidades sociales para el niño y la familia para mejorar la resolución de conflictos interpersonales.", "Medicación: No existe una pastilla para el TOD en sí, pero los médicos pueden recetar fuertemente medicación si el niño tiene TDAH o ansiedad severa coexistente, ya que tratar esos problemas a menudo reduce drásticamente el comportamiento desafiante."] } ], note: "Sin intervención profesional, los niños con TOD tienen un altísimo riesgo de fracaso escolar profundo, rechazo social crónico y desarrollo de problemas de abuso de sustancias en la adolescencia." }, whenToSeekHelp: { title: "¿Cuándo Buscar a un Psiquiatra o Psicólogo Infantil?", intro: "Se requiere intervención urgente de un profesional de salud mental infantil si su hijo:", items: ["Muestra una ira constante, rebeldía y discusiones diarias que están destruyendo la paz en el hogar o llevando a la ruptura familiar", "Está siendo suspendido, expulsado o falla constantemente en la escuela debido a su actitud hacia los maestros y compañeros", "Parece enfadarse a propósito para hacer daño emocional a sus hermanos o padres y no muestra ningún remordimiento real tras el incidente", "Los padres se sienten completamente agotados, deprimidos, asustados del niño o incapaces de manejar la crianza de manera efectiva"] } },
'Uveítis' : { intro: "La uveítis es una inflamación grave del interior del ojo (la úvea). Esta dolorosa condición no es una simple conjuntivitis; si no se diagnostica y trata agresivamente con medicamentos específicos (a menudo esteroides), puede causar un daño interno devastador que lleva a la formación de cataratas severas, glaucoma y pérdida permanente de la visión.", whatIs: { title: "¿Qué es la Uveítis?", text: "Es la inflamación destructiva de la úvea, la capa intermedia y rica en vasos sanguíneos de la pared del ojo (que incluye el iris, el cuerpo ciliar y la coroides). Es responsable de suministrar sangre a la retina. La inflamación hace que el ojo se ponga muy rojo, duela intensamente y la visión se nuble." }, symptoms: { title: "Síntomas Visuales y Físicos de Alarma", intro: "Los síntomas suelen aparecer repentinamente y empeorar con extremada rapidez (en horas o días):", groups: [ { name: "Molestias oculares críticas", items: ["Enrojecimiento severo y profundo del ojo (generalmente más intenso alrededor del borde de color del iris, a diferencia de la conjuntivitis rosada común)", "Dolor ocular agudo, sordo y punzante que a menudo empeora drásticamente al intentar leer o enfocar", "Sensibilidad extrema y dolorosa a la luz brillante (fotofobia), forzando a usar gafas de sol incluso en interiores"] }, { name: "Alteraciones graves de la visión", items: ["Visión notablemente borrosa, nublada o confusa (como mirar a través de niebla o agua sucia)", "Aparición repentina de numerosas moscas volantes oscuras (puntos, hilos o manchas que flotan agresivamente en el campo de visión)", "Pérdida de la visión periférica o disminución drástica y repentina de la agudeza visual central"] } ], warning: "Un ojo rojo profundo y doloroso asociado con sensibilidad extrema a la luz (fotofobia) NUNCA debe tratarse con gotas de farmacia comerciales; requiere atención oftalmológica inmediata." }, types: { title: "Clasificación Anatómica", intro: "Se clasifica médicamente por la zona específica del ojo que está inflamada:", items: ["Uveítis anterior (Iritis): La forma más común. Afecta la parte frontal del ojo (el iris). Suele ser dolorosa y repentina, pero es la más fácil de tratar.", "Uveítis intermedia: Inflamación del líquido gelatinoso en el centro del ojo (el cuerpo vítreo). Frecuentemente indolora, pero causa visión borrosa y cientos de moscas volantes.", "Uveítis posterior (Coroiditis o Retinitis): Inflamación de la parte posterior del ojo (retina y coroides). Es más rara pero mucho más peligrosa, progresa lentamente y amenaza seriamente la visión central.", "Panuveítis: La forma más devastadora, donde la inflamación severa afecta agresivamente todas las capas (frontal, media y posterior) del ojo simultáneamente."], note: "La uveítis posterior requiere un seguimiento a largo plazo porque es muy propensa a recurrencias graves (brotes) que destruyen tejido retiniano." }, causes: { title: "Causas Sistémicas, Infecciosas e Inmunitarias", intro: "A menudo, la causa exacta nunca se descubre (idiopática), pero cuando se encuentra, suele ser:", items: ["Enfermedades autoinmunes y sistémicas (la causa más común): Espondilitis anquilosante, Artritis reactiva, Lupus, Enfermedad inflamatoria intestinal (Crohn/Colitis), Psoriasis, o Sarcoidosis (donde el cuerpo ataca sus propios tejidos oculares).", "Infecciones víricas severas y ocultas: El virus del herpes simple (VHS), el virus varicela-zóster (culebrilla ocular), Citomegalovirus (CMV) o VIH.", "Infecciones bacterianas o parasitarias sistémicas: Sífilis, Tuberculosis, enfermedad de Lyme, o Toxoplasmosis (causada por parásitos a menudo provenientes de las heces de los gatos o carne cruda).", "Traumatismos físicos directos, cirugías intraoculares recientes o golpes penetrantes muy fuertes en el ojo.", "A veces, el gen específico HLA-B27 aumenta genéticamente la propensión a padecer uveítis anterior crónica."] }, diagnosis: { title: "¿Cómo se Diagnostica a Fondo?", intro: "El oftalmólogo (a menudo un subespecialista en retina) utiliza pruebas avanzadas:", items: ["Examen completo con lámpara de hendidura (microscopio binocular brillante): El médico observará la parte delantera del ojo en busca de glóbulos blancos inflamatorios (células) o proteínas (flare) flotando en la cámara anterior (líquido frente al iris).", "Examen de fondo de ojo con pupilas dilatadas al máximo para examinar meticulosamente la retina, los nervios y los vasos sanguíneos posteriores en busca de cicatrices o actividad inflamatoria (uveítis posterior).", "Tonometría para medir la presión dentro del ojo (la inflamación puede causar glaucoma agudo o hipotensión ocular grave).", "Análisis de sangre sistémicos completos, radiografías de tórax o pruebas de ADN reumatológicas (como el factor HLA-B27) buscando la causa subyacente si la uveítis es grave, recurrente o afecta ambos ojos.", "En casos difíciles, análisis del líquido acuoso del ojo mediante una punción fina para cultivos de virus (PCR)."], note: "El diagnóstico de una enfermedad autoinmune sistémica a menudo comienza después de que el oftalmólogo descubre la uveítis en el paciente." }, treatment: { title: "Manejo Antiinflamatorio Urgente", intro: "El tratamiento debe iniciarse de inmediato para detener la inflamación y prevenir la cicatrización interna:", subsections: [ { title: "Terapias oftalmológicas e inmunosupresoras", items: ["Gotas oftálmicas potentes de corticosteroides (El pilar inicial): Se aplican intensamente (ej. cada hora) para reducir drásticamente la inflamación en la uveítis anterior.", "Gotas oftálmicas dilatadoras (ciclopléjicos, como la atropina o ciclopentolato): Paralizan el músculo del iris para aliviar enormemente el dolor punzante y evitar que la pupila se pegue peligrosamente al cristalino (sinequias).", "Inyecciones de esteroides o pastillas de cortisona (Prednisona) por vía oral si la inflamación es posterior, intermedia o no responde a las gotas.", "Antibióticos o medicamentos antivirales específicos si el oftalmólogo descubre que una infección es la causa raíz de la uveítis.", "Medicamentos inmunosupresores sistémicos a largo plazo (metotrexato, micofenolato o terapias biológicas avanzadas como infliximab/adalimumab) indicados por un reumatólogo para personas que padecen uveítis autoinmune severa, crónica y recurrente en ambos ojos."] } ], note: "El paciente NUNCA debe suspender abruptamente las gotas de esteroides; la dosis debe reducirse lentamente según lo indique el oftalmólogo para evitar una reactivación brutal (efecto rebote)." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Oftalmólogo de Inmediato?", intro: "Considere esto una urgencia médica y acuda de inmediato a emergencias oftalmológicas si:", items: ["Sufre un dolor intenso e inusual en el ojo que se agrava al exponerse a la luz, acompañado de enrojecimiento", "Nota un cambio repentino, una nubosidad grave en la visión o una pérdida en partes de su campo visual", "Aparecen súbitamente numerosas moscas volantes oscuras junto con una sensación de dolor profundo dentro del globo ocular", "Usted tiene una enfermedad autoinmune diagnosticada (como espondilitis anquilosante o artritis) y desarrolla síntomas de conjuntivitis dolorosa"] } },
'Edema macular' : { intro: "El edema macular es una complicación ocular severa caracterizada por la acumulación de líquido en el centro de la retina. Resulta a menudo de la diabetes o tras cirugías oculares y provoca una visión borrosa y distorsionada devastadora en el centro del campo visual, impidiendo leer, conducir o reconocer rostros finamente.", whatIs: { title: "¿Qué es el Edema Macular?", text: "Es la inflamación y acumulación anormal de líquido (hinchazón) en la mácula, la zona diminuta en el centro exacto de la retina en la parte posterior del ojo. La mácula es responsable de la visión central nítida, de alta resolución y en color. Cuando se llena de líquido, las células fotorreceptoras se deforman, distorsionando gravemente la imagen." }, symptoms: { title: "Pérdida de Visión Central y Signos", intro: "La afección no causa dolor físico en el ojo, pero afecta profundamente la calidad de la visión:", groups: [ { name: "Problemas centrales de visión", items: ["Visión borrosa, opaca o 'lavada' (colores pálidos o desteñidos) estrictamente en la parte central de su visión", "Las líneas rectas (como el borde de una puerta, las persianas o los renglones de un texto) se ven severamente onduladas, torcidas o rotas (metamorfopsia)", "Dificultad progresiva o repentina extrema para leer la letra pequeña, enhebrar una aguja o ver detalles finos", "Aparición de un punto oscuro, gris, nublado o un área vacía fija directamente en el centro de su campo visual"] } ], warning: "Sin un tratamiento agresivo con inyecciones intraoculares, el líquido acumulado prolongadamente puede destruir permanentemente las células nerviosas de la mácula y causar ceguera central." }, types: { title: "Variantes Según su Causa Clínica", intro: "El edema macular tiene diferentes nombres dependiendo de la enfermedad subyacente que lo provocó:", items: ["Edema Macular Diabético (EMD): La causa más frecuente a nivel mundial. Los vasos sanguíneos dañados por el alto nivel de azúcar en sangre gotean suero y lípidos dentro de la mácula.", "Edema Macular Cistoideo (EMC o Síndrome de Irvine-Gass): La forma más común tras una cirugía de cataratas, desprendimiento de retina o problemas inflamatorios. El líquido se acumula formando quistes con aspecto de pétalos de flor.", "Edema secundario a Oclusión Vascular (CRVO/BRVO): Causado por un 'infarto ocular' donde una vena de la retina se bloquea por un coágulo, aumentando masivamente la presión que filtra líquido a la mácula.", "Edema por Uveítis crónica (inflamación inflamatoria persistente del ojo)."], note: "El paciente conserva la visión periférica (lateral), por lo que rara vez termina en una oscuridad total, pero pierde la visión funcional." }, causes: { title: "Causas y Factores Dañinos para los Vasos Oculares", intro: "La acumulación de líquido siempre se debe a que los diminutos vasos sanguíneos de la retina se vuelven porosos y 'gotean':", items: ["Diabetes Mellitus (Tanto Tipo 1 como Tipo 2), especialmente si los niveles de azúcar (HbA1c) están mal controlados durante años", "Cirugía ocular reciente (principalmente la cirugía de cataratas u operaciones por glaucoma)", "Oclusión de la vena central o rama de la vena de la retina (a menudo asociada con presión arterial muy alta, colesterol alto o glaucoma preexistente)", "Enfermedades inflamatorias crónicas del ojo interno (uveítis severa)", "Toxicidad inducida por ciertos medicamentos (ej. uso prolongado de niacina o ciertos colirios para el glaucoma)", "Trastornos genéticos raros de la retina (como la retinitis pigmentaria) o tumores intraoculares"] }, diagnosis: { title: "¿Cómo se Diagnostica con Precisión?", intro: "El especialista en retina lo diagnosticará realizando pruebas tecnológicas altamente detalladas:", items: ["Tomografía de Coherencia Óptica (OCT): Es la prueba más importante, rápida e indolora. Actúa como un ultrasonido láser, creando imágenes transversales 3D microscópicas de la retina, revelando la hinchazón exacta y midiendo el grosor del edema en micras.", "Examen del fondo de ojo dilatado: El oftalmólogo mira directamente dentro del globo ocular con lentes especiales para detectar los vasos con fugas, microsangrados o manchas lipídicas (exudados duros).", "Angiografía con fluoresceína (AFG): Prueba donde se inyecta un tinte amarillo seguro en la vena del brazo del paciente; el tinte viaja hasta el ojo y una cámara especial toma fotos rápidas que muestran exactamente los puntos donde los capilares de la retina están goteando activamente fluido y causando el daño.", "Uso de la rejilla de Amsler (evaluación rápida donde el paciente observa una cuadrícula para marcar áreas de distorsión)."], note: "La prueba OCT es esencial para diagnosticar el problema de inmediato y para medir si los tratamientos están reduciendo exitosamente el volumen del líquido." }, treatment: { title: "Inyecciones Intraoculares y Terapias Láser", intro: "Los tratamientos modernos revolucionarios han reemplazado a la cirugía y logran resultados extraordinarios si se administran a tiempo:", subsections: [ { title: "Opciones terapéuticas de primera línea", items: ["Inyecciones intravítreas de anti-VEGF (ranibizumab, aflibercept, bevacizumab): El tratamiento estándar y milagroso actual. El oftalmólogo inyecta un medicamento directamente en el interior del ojo tras anestesiarlo. Esto bloquea la molécula que causa las fugas y reduce rápidamente la hinchazón de los vasos (requiere inyecciones regulares frecuentes durante el primer año).", "Inyecciones o implantes de corticosteroides intraoculares (triamcinolona, implantes de dexametasona): Potentes medicamentos antiinflamatorios que se liberan lentamente en el ojo durante meses (se usan si el anti-VEGF falla o para la uveítis, aunque aumentan el riesgo de glaucoma y cataratas).", "Gotas oftálmicas AINEs (antiinflamatorios no esteroideos): Usadas preventivamente o como tratamiento inicial suave tras cirugías de cataratas simples.", "Fotocoagulación con láser focal: Un tratamiento más antiguo usado para sellar con pequeños quemazos precisos las fugas críticas de los vasos sanguíneos periféricos y detener el daño progresivo.", "Vitrectomía (Cirugía retiniana): Extraer el gel vítreo que tira de la mácula y realizar un pelaje de membrana si el edema está causado por una tracción o tensión física sobre la retina."] } ], note: "Las inyecciones intraoculares suenan aterradoras, pero son procedimientos muy rápidos, prácticamente indoloros bajo anestesia local, y salvan la visión." }, whenToSeekHelp: { title: "¿Cuándo Acudir Urgentemente al Retinólogo?", intro: "Solicite una consulta oftalmológica especializada de inmediato si:", items: ["Percibe que las líneas rectas (como los bordes de la pantalla de su teléfono, una puerta o una mesa) se ven onduladas, torcidas o distorsionadas", "Experimenta una pérdida o borrosidad repentina, opaca y confusa directamente en el centro de su visión", "Tiene diabetes diagnosticada y de repente le resulta muy difícil leer, o ve una mancha oscura persistente en su visión frontal", "Se ha sometido a una cirugía de cataratas recientemente y su visión clara inicial se vuelve gradualmente borrosa o deformada"] } },
'Atresia esofágica' : { intro: "La atresia esofágica es un defecto congénito raro pero extremadamente crítico en el que el esófago (el tubo que conecta la boca con el estómago) no se forma correctamente y no se conecta al estómago, impidiendo que el recién nacido pueda tragar saliva o alimentarse. Es una emergencia quirúrgica neonatal que debe repararse en los primeros días de vida.", whatIs: { title: "¿Qué es la Atresia Esofágica (AE)?", text: "Es una grave malformación estructural congénita. Durante el desarrollo del feto, el esófago no logra desarrollarse como un solo tubo continuo. En su lugar, el esófago superior termina en una bolsa ciega (sin salida), y el segmento inferior conecta directamente a los pulmones o al estómago, interrumpiendo el paso de cualquier alimento hacia el sistema digestivo." }, symptoms: { title: "Señales de Emergencia al Nacer", intro: "Los signos son obvios inmediatamente después de que el bebé nace y se manifiestan rápidamente:", groups: [ { name: "Síntomas obstructivos y atragantamiento", items: ["Babeo masivo, constante, espeso y burbujeante inmediatamente después del nacimiento (la saliva no puede ser tragada y regresa a la boca)", "Atragantamiento violento, tos fuerte o arcadas inmediatas si se intenta la primera alimentación (con fórmula o pecho), porque la leche choca contra la bolsa ciega y rebota", "Vómito o regurgitación total de cualquier líquido inmediatamente tras intentar tragar"] }, { name: "Síntomas de aspiración y dificultad respiratoria", items: ["Cambio de color del bebé a azulado (cianosis) durante la alimentación o al babear mucho, debido a la falta de oxígeno", "Dificultad evidente para respirar si el bebé aspira la saliva hacia la tráquea o si los jugos gástricos del estómago suben a los pulmones (si hay una fístula conectada)", "El abdomen puede parecer anormalmente grande, tenso y lleno de aire si el estómago está conectado a la tráquea"] } ], warning: "Si no se diagnostica rápidamente y se intenta alimentar al bebé, la leche ingresará a los pulmones, provocando una neumonía por aspiración grave o un ahogamiento letal." }, types: { title: "Tipos y Complicaciones (Fístula)", intro: "La atresia esofágica en el 90% de los casos va acompañada de otro problema anatómico respiratorio:", items: ["Atresia Esofágica con Fístula Traqueoesofágica (FTE) Distal: El tipo más común (85% de los casos). El esófago superior termina en una bolsa ciega, y el esófago inferior que viene del estómago está anormalmente conectado a la tráquea (vía respiratoria).", "Atresia Esofágica aislada (sin fístula): Ambos extremos del esófago terminan en bolsas ciegas y ninguno se conecta a la tráquea.", "Tipo H (FTE aislada): El esófago es un solo tubo continuo hacia el estómago, pero hay un pequeño túnel o agujero (fístula en forma de H) que conecta y filtra el esófago a la tráquea. Suele diagnosticarse meses después, ya que el niño se atraganta o tiene neumonías frecuentes al beber líquidos."], note: "Esta malformación ocurre en aproximadamente 1 de cada 4000 recién nacidos y pertenece a un grupo de anomalías congénitas relacionadas (Síndrome de VACTERL)." }, causes: { title: "Causas y Formación en el Embarazo", intro: "Es un defecto del desarrollo en las primeras fases del embarazo:", items: ["El fallo en el desarrollo embrionario ocurre entre la cuarta y sexta semana de gestación. Normalmente, la tráquea y el esófago comienzan como un solo tubo y luego se separan, pero en esta condición, el proceso de separación falla.", "Genética (a veces ocurre en asociación con anomalías de cromosomas como la Trisomía 18 o la Trisomía 21/Síndrome de Down)", "Asociaciones de VACTERL: Casi la mitad de los bebés con atresia esofágica tienen otros defectos de nacimiento graves concurrentes que afectan los huesos (Vertebral), Ano, Corazón (Cardiaco), Tráquea, Esófago, Riñones (Renal) y Extremidades (Limbs).", "No hay evidencia de que algo que la madre haya hecho, comido o evitado durante el embarazo haya causado el defecto."] }, diagnosis: { title: "¿Cómo se Detecta Prenatal y Postnatalmente?", intro: "El diagnóstico suele iniciarse antes de que nazca el bebé o inmediatamente después en la sala de partos:", items: ["Señales en ecografías prenatales: A menudo, el obstetra detecta Polihidramnios (exceso de líquido amniótico grave, porque el feto no puede tragar y procesar el líquido) y una burbuja estomacal inusualmente pequeña o invisible en el ultrasonido del embarazo.", "Prueba de inserción de sonda (al nacer): Si el pediatra sospecha el defecto debido a babeo masivo, intentará pasar suavemente una pequeña sonda de alimentación de goma blanda por la nariz o la boca hacia el estómago; en la atresia esofágica, la sonda se atascará en la bolsa ciega o se enrollará y saldrá por la boca.", "Radiografía de tórax y abdomen (postnatal): Confirma definitivamente el diagnóstico, mostrando la sonda de alimentación rizada y atorada en la bolsa esofágica superior sin llegar al estómago.", "Ecocardiogramas y ecografías renales exhaustivas para buscar defectos concurrentes letales en el corazón o los riñones inmediatamente después del nacimiento."], note: "El uso de líquidos de contraste radiológico por vía oral no se recomienda por el inmenso riesgo de aspiración a los pulmones." }, treatment: { title: "Cirugía de Reparación Neonatal Urgente", intro: "El defecto requiere reparación estructural inmediata en la UCIN (Unidad de Cuidados Intensivos Neonatales):", subsections: [ { title: "Manejo preoperatorio y cirugía principal", items: ["Estabilización inmediata: Se prohíbe cualquier intento de alimentación oral y el bebé recibe líquidos y nutrición exclusivamente por vía intravenosa.", "Aspiración continua: Se coloca un pequeño tubo de succión en la bolsa esofágica superior para aspirar continuamente la saliva antes de que el bebé se atragante o la inhale.", "Cirugía correctiva (Tratamiento curativo): En los primeros días de vida, bajo anestesia general, un cirujano pediátrico cierra o desconecta el túnel anormal que va a la tráquea (fístula) y luego une cuidadosamente (anastomosis) los dos extremos separados del esófago para formar un tubo continuo.", "Para casos con una brecha esofágica larga: Si los dos extremos del esófago están demasiado separados, es imposible unirlos en la primera cirugía. El cirujano realizará una gastrostomía (un tubo de alimentación directamente al estómago) y luego, meses después, hará una serie de cirugías complejas de elongación esofágica o reemplazo."] } ], note: "Incluso después de una cirugía exitosa, es muy común que el niño padezca Reflujo Gastroesofágico (ERGE) severo y estrechez (estenosis) en la cicatriz del esófago, requiriendo medicación y posibles dilataciones con globo futuras." }, whenToSeekHelp: { title: "¿Qué Señales Atender como Futura Madre?", intro: "Aunque la gran mayoría se diagnostica en el hospital, debe prestar atención a:", items: ["Durante el embarazo: Informe a su obstetra y pida una evaluación detallada con especialistas fetales si su ecografía de rutina muestra exceso de líquido amniótico (polihidramnios) junto con un estómago fetal invisible o muy pequeño.", "En el hospital tras nacer: Si la enfermera le da su bebé para el primer intento de amamantar y el bebé escupe inmediatamente grandes cantidades de mucosidad blanca espumosa o su rostro se pone azul oscuro, llame a los médicos a gritos para detener la alimentación y evaluar de inmediato la atresia.", "Años después de la cirugía: Como estos niños sufren de debilidad en los músculos esofágicos para toda la vida, los padres deben vigilar el atragantamiento severo con pedazos grandes de comida, neumonías recurrentes, acidez estomacal crónica y evitar la desnutrición."] } },
'Peritonitis' : { intro: "La peritonitis es una inflamación grave y potencialmente mortal del peritoneo, la membrana de tejido similar a la seda que recubre la pared interna del abdomen y cubre la mayoría de los órganos abdominales. Generalmente es el resultado de una infección bacteriana o fúngica que requiere atención médica de emergencia.", whatIs: { title: "¿Qué es la Peritonitis?", text: "Es una infección o inflamación de la cavidad abdominal. Ocurre cuando bacterias o fluidos irritantes (como bilis, ácido estomacal o heces) ingresan al área normalmente estéril del peritoneo, provocando una respuesta inflamatoria masiva y rápida." }, symptoms: { title: "Síntomas y Signos de Alerta", intro: "Los síntomas se desarrollan rápidamente y el dolor es severo:", groups: [ { name: "Síntomas abdominales", items: ["Dolor abdominal intenso, continuo y difuso que empeora con cualquier movimiento, tos o presión", "Abdomen rígidamente duro, hinchado o distendido (abdomen 'en tabla')", "Sensibilidad extrema extrema al tacto (dolor de rebote al soltar la presión)"] }, { name: "Síntomas sistémicos", items: ["Fiebre alta, escalofríos y sudoración profusa", "Náuseas intensas, vómitos repetidos y pérdida total de apetito", "Incapacidad para evacuar heces o expulsar gases", "Ritmo cardíaco acelerado (taquicardia) y reducción en la producción de orina"] } ], warning: "Un abdomen duro como una tabla acompañado de dolor intenso y fiebre es una emergencia quirúrgica absoluta; la demora puede derivar en sepsis mortal." }, types: { title: "Clasificación por Origen", intro: "Se clasifica principalmente en dos tipos:", items: ["Peritonitis secundaria: La forma más común. Causada por la ruptura o perforación de un órgano abdominal (como una apendicitis reventada o una úlcera perforada).", "Peritonitis bacteriana espontánea (PBE): Desarrollada como complicación de una enfermedad hepática crónica (cirrosis) o renal, donde el líquido acumulado en el abdomen (ascitis) se infecta sin una perforación evidente.", "Peritonitis asociada a diálisis: Infección introducida a través del catéter en pacientes que reciben diálisis peritoneal."], note: "La peritonitis no tratada rápidamente conduce a una infección generalizada en la sangre (sepsis) y al fallo multiorgánico." }, causes: { title: "Causas y Desencadenantes", intro: "Cualquier ruptura en el tracto gastrointestinal puede desencadenarla:", items: ["Apendicitis aguda que se rompe y derrama pus y bacterias en el abdomen", "Úlcera estomacal perforada o diverticulitis perforada en el colon", "Traumatismos abdominales graves (como heridas de cuchillo o disparos)", "Pancreatitis severa (la inflamación aguda del páncreas puede propagarse al peritoneo)", "Complicaciones de una cirugía gastrointestinal reciente o enfermedad inflamatoria pélvica severa"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico en urgencias es rápido y clínico:", items: ["Examen físico minucioso palpando la rigidez del abdomen (defensa muscular)", "Análisis de sangre para detectar un conteo elevadísimo de glóbulos blancos (signo de infección masiva)", "Radiografías, Ecografías o Tomografía Computarizada (TC) de abdomen para localizar agujeros, perforaciones o acumulaciones de líquido infectado", "Paracentesis: Extracción de líquido del abdomen con una aguja para analizarlo en laboratorio y confirmar el tipo de bacteria (esencial en la PBE)"], note: "El tratamiento con antibióticos suele iniciarse incluso antes de confirmar los resultados del laboratorio." }, treatment: { title: "Intervenciones de Emergencia", intro: "Es una condición crítica que requiere hospitalización inmediata:", subsections: [ { title: "Cirugía y Medicación", items: ["Antibióticos intravenosos (IV) de amplio espectro inmediatos para combatir la infección en la sangre y el abdomen.", "Cirugía abdominal de emergencia (laparotomía) para la peritonitis secundaria: el cirujano extirpará el tejido infectado, cerrará la perforación (como extirpar un apéndice roto) y lavará exhaustivamente la cavidad abdominal con solución salina.", "Líquidos intravenosos y medicamentos para mantener la presión arterial y sostener las funciones vitales.", "Analgésicos potentes para el manejo del dolor severo.", "En la peritonitis por diálisis, a menudo se administran medicamentos directamente en el líquido de diálisis y puede requerirse la retirada del catéter."] } ], note: "La recuperación depende de la rapidez con la que se inicie el tratamiento quirúrgico y antibiótico." }, whenToSeekHelp: { title: "¿Cuándo Ir a Emergencias?", intro: "Acuda inmediatamente al hospital más cercano si:", items: ["Desarrolla un dolor abdominal repentino, insoportable e implacable", "Su abdomen se siente inusualmente duro al tacto, tenso e hinchado", "Experimenta dolor abdominal intenso acompañado de fiebre alta, escalofríos o vómitos constantes", "Tiene cirrosis hepática y presenta dolor abdominal o confusión leve (riesgo de PBE)"] } },
'Angina inestable' : { intro: "La angina inestable es un síndrome coronario agudo y una advertencia crítica de que un ataque cardíaco inminente podría ocurrir. A diferencia del dolor de pecho predecible por esfuerzo, la angina inestable ocurre en reposo o con un patrón cambiante y más severo, requiriendo atención médica de urgencia inmediata.", whatIs: { title: "¿Qué es la Angina Inestable?", text: "Es una afección en la cual el corazón no recibe suficiente flujo de sangre y oxígeno, provocando dolor en el pecho. Se denomina 'inestable' porque el dolor es impredecible, ocurre incluso en reposo, es más intenso que la angina habitual y no se alivia rápidamente con descanso o medicamentos." }, symptoms: { title: "Síntomas y Señales de Peligro", intro: "El dolor torácico es el sello distintivo y tiene características específicas:", groups: [ { name: "Naturaleza del dolor de pecho", items: ["Dolor aplastante, opresión severa, pesadez o sensación de quemazón en el centro del pecho", "El dolor aparece repentinamente en reposo o al hacer muy poco esfuerzo, o incluso despierta al paciente por la noche", "Dura más que la angina estable típica (a menudo más de 15 a 20 minutos)", "Puede irradiarse (extenderse) hacia el brazo izquierdo, el cuello, la mandíbula inferior, el hombro o la espalda"] }, { name: "Síntomas sistémicos acompañantes", items: ["Dificultad repentina e inexplicable para respirar (falta de aire)", "Sudoración fría y profusa (diaforesis)", "Náuseas, mareos severos o sensación de desmayo inminente", "Fatiga extrema o debilidad repentina (especialmente en mujeres)"] } ], warning: "La angina inestable es una emergencia médica. El riesgo de que progrese a un infarto de miocardio masivo (ataque al corazón) o a una arritmia mortal es altísimo." }, types: { title: "Diferenciación de la Angina", intro: "Es crucial entender la diferencia para medir el nivel de urgencia:", items: ["Angina Estable: Predecible. Ocurre con el esfuerzo físico (como subir escaleras) y desaparece en pocos minutos con descanso o nitroglicerina sublingual.", "Angina Inestable: Impredecible. Es un dolor nuevo, ocurre en reposo, o es un dolor preexistente que se vuelve repentinamente más frecuente, más prolongado o más doloroso.", "Angina Variante (de Prinzmetal): Rara, causada por un espasmo temporal de las arterias coronarias, a menudo por la noche, no siempre por placa crónica."], note: "La angina inestable pertenece a la categoría médica de 'Síndrome Coronario Agudo', junto con los infartos agudos de miocardio." }, causes: { title: "Causas y Patología Coronaria", intro: "Se produce por la reducción crítica del flujo sanguíneo al músculo cardíaco:", items: ["Ruptura de placa aterosclerótica: La causa más común. Una placa de grasa (colesterol) en la pared de una arteria coronaria se rompe, y se forma un pequeño coágulo de sangre sobre ella que bloquea casi por completo el vaso.", "Aterosclerosis severa (endurecimiento y estrechamiento crónico de las arterias)", "Factores de riesgo principales: Hipertensión arterial, colesterol alto, tabaquismo activo, diabetes no controlada, obesidad, sedentarismo y antecedentes familiares de cardiopatía temprana", "Uso de drogas estimulantes (como la cocaína) que pueden causar espasmos severos en las arterias del corazón"] }, diagnosis: { title: "¿Cómo se Diagnostica en Emergencias?", intro: "El equipo médico actuará contra reloj para evaluar el corazón:", items: ["Electrocardiograma (ECG): La prueba más rápida e importante. Evalúa la actividad eléctrica del corazón y detecta signos de isquemia (falta de sangre) o infarto en curso.", "Análisis de sangre para enzimas cardíacas (Troponinas): Mide si ya hay daño o muerte del músculo cardíaco. (En la angina inestable pura, la troponina puede ser normal, si está elevada ya es un infarto).", "Ecocardiograma: Para ver si el músculo cardíaco está bombeando débilmente.", "Angiografía coronaria (Cateterismo): Prueba invasiva donde se inyecta tinte en las arterias del corazón para ver exactamente dónde está el bloqueo y qué tan severo es."], note: "Todo dolor de pecho nuevo o en reposo se trata como un ataque cardíaco hasta que las pruebas demuestren lo contrario." }, treatment: { title: "Intervenciones y Revascularización", intro: "El objetivo es restaurar el flujo de sangre, aliviar el dolor y prevenir un infarto total:", subsections: [ { title: "Tratamiento médico y quirúrgico", items: ["Medicación inmediata: Aspirina, nitroglicerina para dilatar los vasos, heparina u otros anticoagulantes potentes para disolver coágulos, y medicamentos antiplaquetarios (clopidogrel, ticagrelor).", "Oxigenoterapia y analgésicos fuertes (si la nitroglicerina no detiene el dolor).", "Angioplastia y Stent (Intervención Coronaria Percutánea): El tratamiento estándar para abrir la arteria bloqueada. Un cardiólogo introduce un catéter con un globo, lo infla para aplastar la placa y deja una pequeña malla de alambre (stent) para mantener la arteria abierta.", "Cirugía de derivación coronaria (Bypass): En casos donde múltiples arterias están severamente bloqueadas y no se pueden arreglar con stents, el cirujano crea un nuevo camino para la sangre usando un vaso sanguíneo de otra parte del cuerpo."] } ], note: "El alta hospitalaria requerirá rehabilitación cardíaca y cambios estrictos de por vida en la dieta y el estilo de vida." }, whenToSeekHelp: { title: "¿Cuándo Llamar Inmediatamente a Urgencias?", intro: "No intente conducir usted mismo al hospital. Llame a emergencias si:", items: ["Siente una presión, opresión, pesadez o dolor nuevo o inusual en el centro del pecho que dura más de un par de minutos", "Su angina habitual y diagnosticada ocurre de repente mientras está en reposo o durmiendo", "La medicación con nitroglicerina que usa normalmente no alivia su dolor de pecho habitual después de 5 minutos", "El dolor en el pecho viene acompañado de sudoración profusa, náuseas, debilidad extrema o dificultad respiratoria"] } },
'Colitis ulcerosa' : { intro: "La colitis ulcerosa es una enfermedad intestinal inflamatoria crónica y debilitante. Provoca inflamación continua y úlceras en el revestimiento más profundo del intestino grueso (colon) y el recto, causando cólicos abdominales severos, diarrea frecuente con sangre y un impacto profundo en la calidad de vida.", whatIs: { title: "¿Qué es la Colitis Ulcerosa?", text: "Es una de las principales formas de Enfermedad Inflamatoria Intestinal (EII). En esta condición, el sistema inmunológico reacciona de forma anormal y ataca el revestimiento interno del colon y del recto, provocando una inflamación sostenida que erosiona el tejido y forma llagas sangrantes (úlceras)." }, symptoms: { title: "Síntomas y Brotes Clínicos", intro: "Los síntomas suelen desarrollarse gradualmente y ocurren en ciclos de brotes y remisiones:", groups: [ { name: "Síntomas gastrointestinales", items: ["Diarrea persistente, a menudo acompañada de pus o sangre roja brillante (el síntoma más común)", "Dolor abdominal sordo, calambres severos y cólicos dolorosos, típicamente aliviados temporalmente tras defecar", "Necesidad urgente e incontrolable de defecar, a menudo despertando al paciente por la noche", "Tenesmo: dolor rectal y una fuerte sensación de necesidad de evacuar incluso cuando los intestinos están vacíos"] }, { name: "Síntomas sistémicos de enfermedad crónica", items: ["Pérdida de peso involuntaria y disminución del apetito", "Fatiga extrema y letargo crónico (a menudo secundario a la anemia por pérdida de sangre)", "Fiebre leve durante los brotes severos", "Afecciones fuera del colon: inflamación ocular (uveítis), dolor o hinchazón en las articulaciones, y problemas en la piel o el hígado"] } ], warning: "Un brote severo que cause más de seis deposiciones con sangre al día, fiebre rápida y dolor abdominal intenso requiere hospitalización inmediata debido al riesgo de deshidratación grave o perforación del colon (megacolon tóxico)." }, types: { title: "Clasificación por Extensión", intro: "La gravedad y los síntomas dependen de qué parte del colon está inflamada:", items: ["Proctitis ulcerosa: La inflamación se limita solo a la zona más cercana al recto. Los síntomas pueden ser solo sangrado rectal y tenesmo.", "Proctosigmoiditis: Afecta el recto y la parte inferior del colon (colon sigmoideo). Causa dolor abdominal en el lado izquierdo y diarrea con sangre.", "Colitis izquierda: La inflamación se extiende desde el recto hasta el colon descendente. Causa dolor severo en el lado izquierdo y pérdida de peso.", "Pancolitis: Afecta a todo el colon en su totalidad. Causa brotes muy severos de diarrea sanguinolenta, fatiga profunda y dolor abdominal generalizado."], note: "El riesgo de desarrollar cáncer de colon aumenta significativamente después de padecer pancolitis durante 8 a 10 años." }, causes: { title: "Causas y Disparadores del Sistema Inmune", intro: "La causa exacta sigue siendo desconocida, pero se considera una interacción compleja de factores:", items: ["Disfunción del sistema inmunológico: El sistema inmunitario responde agresivamente a virus, bacterias o incluso a los alimentos en el intestino, atacando por error las células sanas del tracto digestivo.", "Genética: Es más común en personas con antecedentes familiares de la enfermedad (los factores genéticos predisponen al sistema inmunológico hiperactivo).", "Desencadenantes ambientales e intestinales: Cambios en el microbioma intestinal (bacterias normales del intestino).", "Estrés y ciertos alimentos: Aunque no causan la enfermedad, ciertos alimentos (lácteos, especias) y el alto estrés emocional pueden desencadenar un brote agudo o empeorar los síntomas significativamente."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El gastroenterólogo requiere confirmar la inflamación y descartar otras infecciones:", items: ["Colonoscopia con biopsia: La prueba definitiva. Un tubo flexible con cámara recorre todo el colon, permitiendo ver la inflamación y las úlceras, y extraer muestras de tejido para confirmar la enfermedad bajo el microscopio.", "Sigmoidoscopia flexible: Similar a la colonoscopia, pero solo examina la parte inferior del colon y el recto (a veces preferida durante brotes muy severos).", "Análisis de heces: Para descartar infecciones bacterianas, parasitarias o virus que imiten los síntomas, y buscar sangre oculta y marcadores de inflamación (como la calprotectina fecal).", "Análisis de sangre para detectar anemia (por sangrado crónico) o signos altos de inflamación (proteína C reactiva)."], note: "Es crucial diferenciarla de la Enfermedad de Crohn, la otra gran EII, que puede afectar cualquier parte del tracto digestivo desde la boca hasta el ano." }, treatment: { title: "Tratamiento Médico y Cirugía Curativa", intro: "El objetivo es inducir la remisión, controlar la inflamación y prevenir brotes futuros:", subsections: [ { title: "Estrategias de manejo", items: ["Antiinflamatorios intestinales: Medicamentos como los aminosalicilatos (mesalamina) administrados por vía oral, supositorios o enemas para reducir la inflamación en el revestimiento del colon (primera línea de defensa).", "Corticosteroides (prednisona): Para brotes agudos y severos, pero no se usan a largo plazo debido a sus graves efectos secundarios.", "Inmunomoduladores y Terapias Biológicas: Medicamentos potentes (azatioprina, infliximab, adalimumab) que atacan proteínas específicas del sistema inmunitario para detener la inflamación crónica desde la raíz.", "Cirugía (Proctocolectomía restauradora): Si los medicamentos fallan, la enfermedad es severa o hay células precancerosas, se extirpa quirúrgicamente todo el colon y el recto. A diferencia de Crohn, la extirpación del colon CURA la colitis ulcerosa de forma definitiva. Frecuentemente se construye una bolsa interna (reservorio ileoanal) para que el paciente pueda evacuar sin necesidad de una bolsa de ostomía externa.", "Soporte nutricional y suplementos de hierro para combatir la anemia y la desnutrición."] } ], note: "Las revisiones periódicas con colonoscopia son obligatorias a largo plazo para detectar a tiempo cualquier signo de cáncer colorrectal." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Gastroenterólogo o Urgencias?", intro: "Contacte a su médico de inmediato si experimenta:", items: ["Episodios continuos de diarrea profusa que no responden a los tratamientos antidiarreicos básicos", "Presencia visible de sangre, moco o pus en las heces en varias ocasiones", "Dolor abdominal constante y severo acompañado de fiebre sin razón aparente", "Despertar frecuentemente de madrugada con una urgencia incontrolable de defecar", "Pérdida de peso inexplicada y fatiga crónica"] } },
'Tumor nasal' : { intro: "Un tumor nasal o paranasal es un crecimiento anormal de tejido dentro de los conductos nasales o las cavidades de los senos paranasales. Aunque muchos son tumores benignos, los que son malignos (cáncer) pueden ser destructivos debido a su cercanía a estructuras vitales como los ojos y el cerebro, requiriendo intervención especializada urgente.", whatIs: { title: "¿Qué son los Tumores Nasales y Paranasales?", text: "Son masas celulares que crecen fuera de control en el revestimiento de la cavidad nasal (el espacio detrás de la nariz) o en los senos paranasales (los huecos llenos de aire en los huesos del rostro). Pueden ser benignos (no cancerosos, como pólipos o papilomas) o malignos (cancerosos, como carcinomas)." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "En sus etapas iniciales, a menudo imitan síntomas inofensivos de resfriados o alergias, pero persisten o empeoran:", groups: [ { name: "Síntomas nasales persistentes", items: ["Congestión u obstrucción nasal constante, frecuentemente en un solo lado (unilateral) que no mejora con medicamentos", "Secreción nasal crónica (mucosidad), que a menudo drena por un solo lado de la nariz", "Hemorragias nasales (epistaxis) recurrentes e inexplicables", "Disminución notable o pérdida total del sentido del olfato (anosmia)", "Drenaje de moco hacia la parte posterior de la garganta (goteo posnasal) con mal olor constante"] }, { name: "Signos avanzados y neurológicos", items: ["Dolor, presión o hinchazón en la cara, especialmente alrededor de las mejillas, los ojos o la frente", "Bulto o masa palpable en el interior de la nariz, en el rostro o en el paladar (cielo de la boca)", "Dolor de cabeza crónico que no responde a analgésicos", "Cambios en la visión (visión doble, ojos llorosos, o un ojo que parece sobresalir o abultarse)", "Entumecimiento, dolor continuo en la parte superior de los dientes o aflojamiento dental sin causa odontológica"] } ], warning: "La congestión y sangrado nasal persistente que ocurre sistemáticamente en un solo lado de la nariz en adultos es una bandera roja que debe ser examinada por un especialista." }, types: { title: "Tipos de Tumores Frecuentes", intro: "Los tumores en esta zona abarcan una amplia variedad histológica:", items: ["Pólipos nasales: Masas en forma de lágrima, inflamatorias y totalmente benignas, muy comunes en personas con alergias crónicas.", "Papiloma invertido: Un tumor benigno agresivo que crece en la cavidad nasal; destruye el hueso circundante y tiene el potencial de transformarse en cáncer (requiere cirugía exhaustiva).", "Carcinoma de células escamosas: El tipo más común de cáncer maligno nasal; se forma en las células planas que recubren los conductos.", "Adenocarcinoma: Cáncer maligno que surge de las glándulas productoras de moco en los senos paranasales (frecuente en carpinteros).", "Melanoma mucoso: Cáncer agresivo muy raro originado en las células que dan pigmento, desarrollándose en la mucosa nasal."], note: "Los tumores malignos paranasales son relativamente raros, representando solo el 1% de todos los cánceres corporales." }, causes: { title: "Factores de Riesgo Ambientales y Laborales", intro: "A diferencia de muchos otros tumores, los cánceres nasales tienen fuertes vínculos con la exposición ocupacional prolongada:", items: ["Exposición crónica en el trabajo a polvos industriales: Polvo de madera (riesgo enorme para ebanistas y carpinteros), polvo de cuero, polvo de harina o textiles.", "Exposición a productos químicos tóxicos: Vapores de pegamentos, formaldehído, níquel, cromo y gases de mostaza.", "Tabaquismo intenso (aumenta significativamente el riesgo de carcinoma de células escamosas en esta área).", "Infección por el Virus del Papiloma Humano (VPH), relacionado con algunos tipos de tumores benignos y malignos en la cavidad nasal.", "Los pólipos nasales benignos se asocian a asma crónica, rinitis alérgica severa o fibrosis quística."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El otorrinolaringólogo y el oncólogo utilizan técnicas precisas para ver y muestrear el tejido:", items: ["Endoscopia nasal: El paso inicial crucial. Se introduce un tubo muy fino con una cámara iluminada por la nariz para observar toda la cavidad y los senos paranasales en busca de masas sospechosas.", "Tomografía computarizada (TC) de senos paranasales: Especialmente detallada para ver si el tumor ha invadido o destruido los huesos del cráneo o de las cuencas oculares.", "Resonancia Magnética (RM) del cráneo y la cara: Proporciona el mejor contraste para diferenciar el tejido tumoral del moco atrapado, y ver si hay invasión hacia el cerebro o los ojos.", "Biopsia endoscópica: Durante la endoscopia, el cirujano extrae un fragmento del tumor para enviarlo a patología y confirmar si hay células cancerosas exactas."], note: "Dado que esta área está anatómicamente repleta de nervios y vasos cruciales, las imágenes precisas son vitales antes de cualquier incisión." }, treatment: { title: "Manejo Quirúrgico y Oncológico", intro: "El plan de tratamiento es agresivo y se adapta según la benignidad o malignidad de la masa:", subsections: [ { title: "Estrategias de intervención", items: ["Cirugía endoscópica nasal: Para tumores benignos (como pólipos o papilomas), el cirujano utiliza cámaras y herramientas milimétricas a través de las fosas nasales para extirpar el tumor sin hacer cortes externos en el rostro.", "Cirugía abierta maxilofacial o craneofacial: Para tumores cancerosos grandes o agresivos. Puede requerir abrir el rostro, el paladar o trabajar junto con neurocirujanos si el tumor toca la base del cráneo. A menudo se requiere cirugía reconstructiva posterior.", "Radioterapia: Haces de alta energía aplicados al tumor, a menudo combinados con cirugía para destruir cualquier célula cancerosa microscópica restante o como tratamiento primario si la cirugía no es posible.", "Quimioterapia: Medicamentos sistémicos usados raramente por sí solos, generalmente combinados con radioterapia para tumores malignos agresivos o en etapas muy avanzadas.", "Medicamentos con corticosteroides (sprays o píldoras) para reducir temporalmente masas puramente inflamatorias como los pólipos benignos."] } ], note: "Debido a la compleja anatomía de la cara, el tratamiento oncológico en esta área suele ser realizado por equipos multidisciplinarios en centros especializados." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Otorrinolaringólogo?", intro: "Solicite una revisión médica especializada inmediata si nota:", items: ["Congestión nasal o 'nariz tapada' severa que ocurre sistemáticamente en un solo lado y dura más de un mes", "Episodios recurrentes de hemorragias nasales sin explicación evidente, a menudo unilaterales", "Dolor persistente, hinchazón profunda o sensación de presión asimétrica alrededor de un solo ojo, mejilla o frente", "Aflojamiento de los dientes superiores o cambios en la forma en que encaja su dentadura sin causa odontológica clara", "Problemas de visión recientes (visión doble) acompañados de síntomas nasales"] } },
'Abuso de drogas y farmacodependencia' : { intro: "El abuso de drogas y la farmacodependencia, clínicamente conocidos como Trastorno por Consumo de Sustancias (TCS), son enfermedades cerebrales complejas y crónicas. Provocan la búsqueda y el uso compulsivo de drogas, alcohol o medicamentos recetados, a pesar de las consecuencias devastadoras en la salud, la familia y la vida profesional del individuo.", whatIs: { title: "¿Qué es el Trastorno por Consumo de Sustancias?", text: "Es un patrón de uso repetido e incontrolable de una o más sustancias psicoactivas que altera profundamente la estructura y el funcionamiento del cerebro, especialmente sus circuitos de recompensa, autocontrol y toma de decisiones. No es una simple falta de fuerza de voluntad, sino una afección médica reconocida." }, symptoms: { title: "Síntomas Físicos, Psicológicos y Conductuales", intro: "Los signos abarcan múltiples áreas de la vida del individuo, evidenciando la pérdida de control:", groups: [ { name: "Indicadores conductuales y psicológicos", items: ["Ansia incontrolable, fuerte y obsesiva (craving) por consumir la sustancia", "Incapacidad para detener el consumo o reducir la dosis, a pesar de múltiples intentos de hacerlo y del deseo genuino de parar", "Continuar usando la droga a pesar de saber que causa o agrava problemas físicos graves, psicológicos o legales", "Abandono de responsabilidades importantes (faltar al trabajo o a la escuela, negligencia familiar)", "Aislamiento social, abandono de pasatiempos anteriores y cambios drásticos de círculo de amigos"] }, { name: "Signos físicos (Dependencia)", items: ["Tolerancia aguda: Necesidad de dosis cada vez más altas y frecuentes de la droga para lograr el efecto inicial o el 'subidón'", "Síndrome de abstinencia: Aparición de síntomas físicos violentos (sudores, temblores, ansiedad severa, vómitos, insomnio, convulsiones) cuando el efecto de la sustancia desaparece", "Deterioro físico general, cambios drásticos de peso, alteraciones severas del sueño y pupilas inusualmente dilatadas o contraídas"] } ], warning: "Una sospecha de sobredosis (respiración extremadamente lenta, pérdida de conciencia, labios o uñas azuladas, falta de respuesta al dolor) es una emergencia de vida o muerte; llame a los servicios de rescate y administre Naloxona si hay sospecha de opioides." }, types: { title: "Sustancias Frecuentemente Abusadas", intro: "La dependencia puede desarrollarse a partir de drogas ilegales o medicamentos legales recetados:", items: ["Opioides recetados y heroína (como fentanilo, oxicodona, morfina): Extremadamente adictivos, suprimen la respiración y causan un síndrome de abstinencia brutal.", "Estimulantes (cocaína, metanfetaminas, anfetaminas recetadas para TDAH): Causan paranoia, daño cardíaco rápido y comportamiento errático.", "Depresores del sistema nervioso (Benzodiacepinas, Xanax, Valium): Causa adicción física severa; la abstinencia sin supervisión médica puede causar convulsiones mortales.", "Cannabis (marihuana): Puede causar dependencia psicológica severa y falta de motivación a largo plazo, especialmente si el uso comienza en la adolescencia temprana.", "Alcohol y nicotina (drogas legales de altísimo impacto adictivo y orgánico)."], note: "Es común el 'policonsumo' (uso de varias drogas combinadas), lo cual multiplica el riesgo de reacciones tóxicas mortales." }, causes: { title: "Causas, Factores de Riesgo y Neurobiología", intro: "La adicción es un cruce complejo entre vulnerabilidad biológica y exposición:", items: ["Impacto cerebral profundo: Las drogas inundan el cerebro con dopamina (neurotransmisor del placer). Con el uso crónico, el cerebro deja de producir dopamina natural, lo que deprime al usuario, quien necesita la droga solo para sentirse 'normal'.", "Predisposición genética: Representa entre el 40% y el 60% del riesgo de que una persona desarrolle una adicción.", "Factores psicológicos (automedicación): Alta incidencia en personas con trauma infantil, Trastorno de Estrés Postraumático (TEPT), depresión profunda o ansiedad clínica no tratada.", "Factores ambientales: Presión social temprana, disponibilidad fácil de drogas en el hogar o la comunidad, y estrés crónico.", "Edad del primer consumo: Usar drogas durante la adolescencia (cuando el cerebro aún se está desarrollando en sus funciones de autocontrol) es el mayor factor de riesgo temporal."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "Los psiquiatras o especialistas en adicciones utilizan evaluaciones clínicas estandarizadas:", items: ["Entrevistas clínicas estructuradas usando los criterios del Manual Diagnóstico y Estadístico de los Trastornos Mentales (DSM-5) para clasificar el trastorno como leve, moderado o grave según el número de síntomas presentes.", "Pruebas de toxicología (análisis de orina, sangre o cabello) para identificar el tipo de sustancias activas en el cuerpo.", "Examen físico y neurológico exhaustivo para identificar daños a órganos (hígado, corazón, pulmones) o enfermedades infecciosas a menudo asociadas con drogas (VIH, Hepatitis B o C por compartir agujas).", "Evaluación psiquiátrica completa para detectar diagnósticos duales (coexistencia innegable de trastornos de salud mental, vital para el éxito del tratamiento)."], note: "La negación rotunda de que existe un problema y la minimización de la gravedad del consumo son síntomas centrales de la enfermedad misma." }, treatment: { title: "Rehabilitación, Desintoxicación y Terapia", intro: "El tratamiento debe ser holístico, a largo plazo y enfocado en la prevención de recaídas:", subsections: [ { title: "Fases del tratamiento médico y psicológico", items: ["Desintoxicación médicamente supervisada: El paso inicial crítico. Consiste en limpiar el cuerpo de la sustancia controlando los síntomas peligrosos de abstinencia con medicamentos (como metadona o buprenorfina para opioides, y benzodiacepinas para el alcohol).", "Centros de tratamiento residencial (Rehabilitación de 30-90 días): Aislamiento del entorno tóxico para un trabajo terapéutico intensivo diario.", "Tratamiento Asistido por Medicamentos (MAT): Medicaciones a largo plazo (como Naltrexona, Metadona o Suboxone) que reducen enormemente los antojos (cravings) biológicos y previenen la recaída sin causar un 'subidón'.", "Terapia conductual: Terapia Cognitivo-Conductual (TCC) para identificar desencadenantes emocionales y cambiar los comportamientos; Terapias motivacionales y de Manejo de Contingencias.", "Apoyo de pares de por vida: Participación activa en grupos de 12 pasos (Narcóticos Anónimos, Alcohólicos Anónimos) o grupos como SMART Recovery.", "Tratamiento simultáneo de patologías duales: Abordar psiquiátricamente la depresión o ansiedad subyacente que impulsaba el uso de la sustancia."] } ], note: "La adicción es una enfermedad crónica; una recaída no indica fracaso del tratamiento, sino que el plan de intervención debe reevaluarse o ajustarse." }, whenToSeekHelp: { title: "¿Cuándo Buscar Intervención o Urgencias?", intro: "Debe buscar asesoramiento profesional especializado o ayuda de emergencia si:", items: ["Se da cuenta de que no puede pasar un solo día sin consumir la sustancia y su tolerancia es cada vez mayor", "Sus seres queridos, colegas de trabajo o la escuela le han expresado repetidamente que su consumo está afectando sus responsabilidades o su comportamiento", "Siente temblores, náuseas severas o ansiedad extrema cuando han pasado algunas horas desde su último consumo (abstinencia física)", "Incurre en comportamientos ilegales, deudas extremas, o roba para financiar su necesidad de drogas", "Presenta cualquier cambio grave de salud física, como abscesos en la piel, dolores de pecho o cambios violentos de estado de ánimo"] } },
'Dolor de nervio o dolor nervioso' : { intro: "El dolor de nervio, clínicamente llamado dolor neuropático, es uno de los síndromes de dolor crónico más severos y difíciles de tratar. Surge cuando los nervios del sistema nervioso se dañan o funcionan mal, enviando señales de dolor abrasador, eléctrico o punzante al cerebro, a menudo sin ninguna lesión visible en la piel.", whatIs: { title: "¿Qué es la Neuropatía (Dolor Nervioso)?", text: "Es un tipo de dolor originado por una lesión, enfermedad o disfunción directa en los nervios sensoriales del sistema nervioso central o periférico. A diferencia del dolor nociceptivo (causado por un golpe, quemadura o herida), el dolor neuropático es una 'falsa alarma' generada por nervios dañados que malinterpretan estímulos inofensivos." }, symptoms: { title: "Síntomas y Sensaciones Característicos", intro: "Los pacientes describen este dolor con términos muy específicos, diferentes al dolor muscular u óseo:", groups: [ { name: "Naturaleza del dolor", items: ["Dolor severo que se describe como quemazón, ardor hirviente, o similar al roce con ortigas", "Sensación de descargas eléctricas o relámpagos de dolor punzante y rápido que recorren un brazo o pierna", "Sensación punzante constante ('como si clavaran miles de alfileres y agujas' profundamente en la piel)", "Entumecimiento profundo o pérdida de la sensación del tacto (paradoja de 'dolor en una zona dormida')"] }, { name: "Hipersensibilidad neurológica", items: ["Alodinia: Dolor extremo provocado por estímulos que normalmente no deberían doler en absoluto (como el suave roce de una sábana, el viento o el agua tibia de la ducha)", "Hiperalgesia: Un estímulo levemente doloroso (como un pellizco suave) se siente como un dolor excruciante y desproporcionado", "El dolor a menudo empeora drásticamente durante la noche y en reposo"] } ], warning: "La pérdida repentina y progresiva de sensibilidad en los pies, combinada con dolor ardiente, aumenta drásticamente el riesgo de desarrollar úlceras inadvertidas y amputaciones si se sufre de diabetes." }, types: { title: "Formas Comunes de Neuropatía", intro: "El dolor neuropático abarca una amplia variedad de síndromes:", items: ["Neuropatía periférica diabética: La causa más común mundialmente. Daño generalizado a los nervios de los pies y manos ('patrón de guante y calcetín') debido a los altos niveles de azúcar.", "Neuralgia posherpética: Dolor quemante severo que persiste meses o años en la misma zona de la piel donde se tuvo un brote de herpes zóster (culebrilla).", "Neuralgia del trigémino: Dolor facial similar a fuertes descargas eléctricas, activado por masticar, hablar o lavarse la cara.", "Radiculopatía (Ciática): Dolor punzante que baja por la pierna causado por la compresión o irritación de un nervio que sale de la columna (frecuentemente por una hernia discal).", "Dolor del miembro fantasma: Dolor neuropático sentido en el área de una extremidad que ha sido amputada."], note: "El dolor neuropático rara vez desaparece por sí solo una vez que se cronifica, requiriendo intervención médica a largo plazo." }, causes: { title: "Causas y Orígenes del Daño Nervioso", intro: "Cualquier condición que interrumpa, irrite o destruya las vainas protectoras de los nervios puede causarlo:", items: ["Diabetes Mellitus no controlada crónicamente (destruye silenciosamente la microcirculación que alimenta a los nervios).", "Infecciones virales graves (Herpes zóster, VIH/SIDA, Enfermedad de Lyme, Sífilis).", "Compresión física de los nervios: Tumores, hernias de disco espinal o síndrome del túnel carpiano.", "Efectos neurotóxicos de tratamientos médicos: Es un efecto secundario muy común de potentes agentes de quimioterapia oncológica o radioterapia prolongada.", "Deficiencias nutricionales graves, especialmente la falta crónica de Vitamina B12 o ácido fólico.", "Toxinas y venenos: Consumo crónico de alcohol (neuropatía alcohólica), envenenamiento por metales pesados (plomo, mercurio).", "Enfermedades autoinmunes (Lupus, Artritis reumatoide) o enfermedades desmielinizantes como la Esclerosis Múltiple."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El neurólogo o especialista en dolor debe mapear el daño para encontrar la causa raíz:", items: ["Historia clínica extremadamente detallada: El médico le pedirá que describa el dolor usando palabras específicas (ardor, eléctrico, punzante) y dibujará un mapa de su cuerpo marcando las áreas dolorosas.", "Examen neurológico completo: Pruebas de sensibilidad al tacto, temperatura, vibración (con diapasón), fuerza muscular y reflejos osteotendinosos.", "Electromiografía (EMG) y Estudios de Conducción Nerviosa (NCS): Pruebas clave donde se envían pequeñas corrientes eléctricas y se insertan finas agujas en los músculos para medir la velocidad, fuerza y daño de las señales eléctricas a lo largo de los nervios.", "Análisis de sangre para descartar de inmediato diabetes, deficiencia de vitamina B12, trastornos renales y toxinas circulantes.", "Resonancia Magnética (RM) del cerebro y la columna vertebral para buscar tumores o discos herniados que estén pellizcando grandes raíces nerviosas."], note: "Es vital un diagnóstico exacto porque los analgésicos comunes (ibuprofeno, paracetamol) no funcionan para el dolor neuropático." }, treatment: { title: "Abordaje Multidisciplinario del Dolor", intro: "Curar un nervio dañado a menudo es imposible, el objetivo es 'calmar' la sobreactividad eléctrica y aliviar los síntomas:", subsections: [ { title: "Terapias neurológicas", items: ["Medicamentos Neuromoduladores (Anticonvulsivos): Es el tratamiento de primera línea. Fármacos como la gabapentina o la pregabalina estabilizan los nervios sobreexcitados y reducen significativamente las descargas eléctricas.", "Antidepresivos Tricíclicos y duales (como amitriptilina, duloxetina o venlafaxina): Ayudan a alterar las sustancias químicas cerebrales y los circuitos que perciben y procesan el dolor nervioso.", "Analgésicos tópicos potentes: Parches de lidocaína (anestésico local) o cremas/parches de capsaicina (extracto de chile) aplicados directamente sobre la piel dolorida.", "Bloqueos nerviosos: Inyecciones de anestésicos locales y esteroides directamente alrededor del grupo de nervios irritados, u opciones como la ablación por radiofrecuencia para silenciar temporalmente el nervio.", "Neuroestimulación implantada: Inserción de electrodos (como el estimulador de la médula espinal o TENS) que envían impulsos eléctricos indoloros bloqueando físicamente las señales de dolor antes de que lleguen al cerebro.", "Fisioterapia y control exhaustivo de enfermedades base (ej. control glicémico impecable para diabéticos)."] } ], note: "La constancia es clave; los medicamentos neuromoduladores pueden tardar de 2 a 4 semanas de uso continuo en alcanzar su máximo efecto analgésico." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Neurólogo o Especialista?", intro: "Solicite una evaluación médica neurológica si experimenta:", items: ["Sensación persistente de hormigueo, entumecimiento, ardor o pinchazos intensos en sus manos o pies que va empeorando con las semanas", "Su dolor se describe como 'choques eléctricos', ráfagas ardientes, y los analgésicos de farmacia no proporcionan ningún alivio", "Una sábana rozando su piel o una temperatura fría provoca una respuesta de dolor extrema e insoportable", "Presenta debilidad focal o nota que un grupo muscular está perdiendo fuerza, tiene problemas para agarrar objetos o tropieza constantemente al caminar"] } },
'Trastornos hormonales' : { intro: "Los trastornos hormonales ocurren cuando existe un desequilibrio en el sistema endocrino, es decir, cuando se produce demasiada o muy poca cantidad de una o más hormonas esenciales. Dado que las hormonas actúan como mensajeros químicos que controlan casi todo en el cuerpo (desde el metabolismo hasta la reproducción), cualquier desajuste puede causar síntomas generalizados y severos.", whatIs: { title: "¿Qué es un Desequilibrio o Trastorno Hormonal?", text: "Es una disfunción en las glándulas endocrinas (como la tiroides, páncreas, suprarrenales, ovarios o testículos) que provoca una producción excesiva (hiperfunción) o insuficiente (hipofunción) de hormonas, alterando drásticamente el equilibrio metabólico, físico y emocional del organismo." }, symptoms: { title: "Síntomas Comunes de Alerta", intro: "Debido a la gran cantidad de hormonas diferentes, los síntomas varían enormemente, pero los indicadores generales incluyen:", groups: [ { name: "Síntomas físicos y metabólicos", items: ["Aumento o pérdida de peso rápida e inexplicable a pesar de no cambiar la dieta o el ejercicio", "Fatiga crónica extrema, letargo o debilidad muscular sin causa física aparente", "Intolerancia severa y repentina al calor o al frío (transpiración profusa repentina o escalofríos constantes)", "Sed excesiva y orina muy frecuente (síntomas clásicos de diabetes o desequilibrios de glucosa)", "Caída o adelgazamiento del cabello excesivo, o crecimiento de vello oscuro no deseado en la cara/cuerpo en mujeres (hirsutismo)"] }, { name: "Síntomas reproductivos y emocionales", items: ["Periodos menstruales muy irregulares, ausentes (amenorrea) o sangrado inusualmente abundante en mujeres", "Pérdida drástica del deseo sexual (libido), disfunción eréctil en hombres o infertilidad en ambos sexos", "Cambios bruscos de humor, ataques de ansiedad persistente, irritabilidad extrema o depresión clínica", "Aparición de acné severo y resistente a tratamientos en la edad adulta"] } ], warning: "Una crisis suprarrenal (caída masiva de cortisol con dolor abdominal, confusión y presión arterial peligrosamente baja) o un coma diabético son emergencias endocrinas mortales." }, types: { title: "Trastornos Endocrinos Frecuentes", intro: "El diagnóstico se basa en la glándula específica que está fallando:", items: ["Trastornos de la Tiroides: Hipotiroidismo (metabolismo lento, fatiga, aumento de peso) o Hipertiroidismo (metabolismo acelerado, pérdida de peso, taquicardia).", "Síndrome de Ovario Poliquístico (SOP): Desequilibrio de hormonas sexuales femeninas, causante principal de infertilidad, quistes ováricos, acné y exceso de vello.", "Trastornos del Páncreas: Diabetes Mellitus tipo 1 y 2, donde la falta o resistencia a la insulina impide el control del azúcar en sangre.", "Trastornos de las Glándulas Suprarrenales: Síndrome de Cushing (exceso extremo de cortisol, u hormona del estrés) o Enfermedad de Addison (falta crítica de cortisol y aldosterona).", "Desequilibrios de las hormonas sexuales: Menopausia temprana en mujeres, o hipogonadismo (niveles de testosterona muy bajos) en hombres."], note: "A menudo, el problema real está en la glándula pituitaria (la 'glándula maestra' del cerebro) que da órdenes erróneas a las demás glándulas." }, causes: { title: "Causas y Disparadores", intro: "Los desequilibrios hormonales pueden originarse en factores crónicos o agudos:", items: ["Enfermedades autoinmunes: La causa más común de trastornos del sistema endocrino. El cuerpo ataca sus propias glándulas (Enfermedad de Hashimoto para hipotiroidismo, Diabetes tipo 1 para páncreas).", "Tumores, quistes o adenomas benignos que crecen dentro de la glándula endocrina (especialmente en la tiroides o pituitaria), alterando o hiperestimulando su producción.", "Uso prolongado de medicamentos fuertes, como los corticosteroides (prednisona), esteroides anabólicos para culturismo o quimioterapia.", "Estrés crónico y severo continuo, falta crónica de sueño o trastornos alimentarios severos (anorexia) que deprimen el sistema reproductivo y hormonal.", "Factores genéticos hereditarios y lesiones físicas o radioterapia extensa en zonas glandulares."] }, diagnosis: { title: "¿Cómo se Diagnostican?", intro: "El endocrinólogo es el especialista principal para resolver estos misterios médicos mediante:", items: ["Análisis de sangre y orina exhaustivos: El estándar de oro. Miden los niveles exactos de hormonas circulantes (como TSH para la tiroides, cortisol, testosterona, estrógeno, insulina) y detectan autoanticuerpos.", "Pruebas de estimulación y supresión hormonal: Exámenes dinámicos y especializados donde se inyecta una hormona y se analiza la sangre horas después para ver si la glándula responde correctamente.", "Estudios de imagen: Ecografías de la tiroides o de los ovarios (para SOP), Resonancias Magnéticas (RM) de la cabeza (para buscar tumores minúsculos en la glándula pituitaria) o Tomografías Computarizadas (TC) de las glándulas suprarrenales sobre los riñones.", "Toma de biopsia con aguja fina guiada por ultrasonido si se descubre un nódulo o masa sospechosa en la tiroides."], note: "El momento del análisis de sangre es clave; muchas hormonas (como el cortisol o la testosterona) varían drásticamente dependiendo de la hora del día o del ciclo menstrual de la mujer." }, treatment: { title: "Opciones de Terapia Endocrina", intro: "Casi todos los trastornos hormonales son tratables, logrando un retorno a la normalidad fisiológica:", subsections: [ { title: "Terapia de reemplazo y regulación", items: ["Terapia de Reemplazo Hormonal (TRH): Si una glándula está destruida o falla (hipofunción), el tratamiento es simplemente tomar una pastilla que sustituye la hormona faltante (como la levotiroxina para el hipotiroidismo, inyecciones de testosterona o insulina diaria para diabéticos).", "Medicamentos supresores: Si el problema es la hiperfunción, se recetan medicamentos para bloquear, reducir o frenar la producción y liberación excesiva de la hormona (como medicamentos antitiroideos).", "Cirugía glandular o radioterapia focalizada: Para extirpar tumores benignos o nódulos activos en las glándulas (muy común en la tiroides o en la pituitaria), o para remover partes de glándulas que están irremediablemente sobreactivas.", "Modificaciones intensivas del estilo de vida y nutrición (especialmente críticas para condiciones como el Síndrome de Ovario Poliquístico o la resistencia a la insulina / prediabetes), incluyendo pérdida de peso y ejercicio de resistencia para sensibilizar a la insulina."] } ], note: "La gran mayoría de los tratamientos de reemplazo hormonal (como para tiroides o diabetes tipo 1) deben mantenerse durante toda la vida." }, whenToSeekHelp: { title: "¿Cuándo Consultar a un Endocrinólogo?", intro: "Debe programar una visita médica especializada si:", items: ["Experimenta fatiga profunda e inexplicable acompañada de aumento o pérdida de peso inusual a pesar de tener una dieta estable", "Observa un crecimiento nuevo y constante de vello en su rostro, pecho o abdomen siendo mujer, o alteraciones drásticas en su ciclo menstrual habitual", "Tiene sed constante y siente la necesidad urgente de orinar muchas veces a lo largo del día y de la noche", "Siente palpitaciones aceleradas constantes en reposo, manos sudorosas, temblores nerviosos o un bulto hinchado en la parte frontal inferior de su cuello (bocio)"] } },
'Retraso del desarrollo' : { intro: "Un retraso del desarrollo ocurre cuando un niño no alcanza los hitos esperados para su edad en habilidades físicas, de lenguaje, cognitivas o sociales. La identificación y la intervención especializada tempranas son absolutamente fundamentales, ya que los cerebros jóvenes son altamente moldeables (neuroplasticidad) y pueden recuperar mucho terreno perdido.", whatIs: { title: "¿Qué es el Retraso del Desarrollo?", text: "Es una condición pediátrica en la que un bebé o niño pequeño progresa o aprende a un ritmo significativamente más lento que la mayoría de los niños de su misma edad biológica en áreas funcionales clave. No es simplemente ser 'un poco lento', sino mostrar un patrón constante de no alcanzar los hitos normativos." }, symptoms: { title: "Áreas y Señales de Retraso", intro: "Los signos varían enormemente dependiendo del área de desarrollo afectada y la edad del niño:", groups: [ { name: "Retrasos motores y físicos (Gruesos y finos)", items: ["Motor grueso: Incapacidad de sostener la cabeza a los 4 meses, no sentarse sin apoyo a los 9 meses, no caminar a los 18 meses", "Tono muscular anormal: El bebé se siente inusualmente rígido (espasticidad) o flácido como una 'muñeca de trapo' (hipotonía)", "Motor fino: Dificultad o incapacidad para agarrar o transferir objetos de una mano a otra al año de edad, o no usar agarre de pinza (dedos pulgar e índice)"] }, { name: "Retrasos en comunicación y área socio-cognitiva", items: ["Habla y Lenguaje: No balbucear a los 9 meses, no señalar cosas o no decir palabras simples (como 'mamá') al año, o no formar oraciones cortas a los 2.5 años", "Social y Emocional: Falta notable de contacto visual directo, no responder a su nombre al año, o no mostrar sonrisas sociales tempranas", "Cognitivo: Falta de juego imitativo, no buscar objetos escondidos, o pérdida de habilidades previamente adquiridas (regresión)"] } ], warning: "Cualquier pérdida progresiva y repentina de habilidades motoras, de habla o sociales que el niño ya dominaba anteriormente (regresión) es una emergencia neurológica que requiere evaluación inmediata." }, types: { title: "Categorías de Retraso", intro: "Los pediatras evalúan el problema en función de la amplitud del déficit:", items: ["Retraso específico del desarrollo: El niño está por detrás de sus pares en solo una área particular (por ejemplo, solo en el habla o solo en habilidades motoras), pero su desarrollo en el resto de áreas es completamente normal.", "Retraso Global del Desarrollo (RGD): Es un diagnóstico más serio utilizado generalmente en niños menores de 5 años. Se aplica cuando el niño muestra déficits significativos en dos o más áreas importantes del desarrollo simultáneamente (motor, lenguaje, cognitivo y social). A menudo precede a un diagnóstico de discapacidad intelectual u otros trastornos mayores."], note: "Muchos niños que muestran un retraso específico temprano 'alcanzan' a sus compañeros completamente antes de comenzar la escuela si reciben terapias a tiempo." }, causes: { title: "Causas y Factores Contribuyentes", intro: "Los retrasos a menudo son síntomas de condiciones ocultas médicas, genéticas o ambientales:", items: ["Problemas en el embarazo y parto: Nacimiento muy prematuro, bajo peso extremo al nacer, falta de oxígeno en el cerebro durante el parto (asfixia), o uso de alcohol/drogas y mala nutrición materna en el embarazo.", "Factores genéticos o cromosómicos (como el Síndrome de Down, el Síndrome del X frágil o distrofias musculares).", "Infecciones neonatales severas (meningitis bacteriana, encefalitis) o infecciones prenatales de la madre (como citomegalovirus o rubeola).", "Pérdida de audición oculta profunda o problemas severos de la visión no detectados.", "Trastornos del Espectro Autista (TEA) o Parálisis Cerebral (que a menudo se manifiestan inicialmente como retrasos motores o del habla).", "Factores ambientales extremos: Negligencia profunda, falta extrema de estimulación física o verbal en el hogar (privación social) o exposición crónica al plomo ambiental."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "Se requiere un equipo de desarrollo infantil y neuropsicólogos para confirmar y evaluar la magnitud del problema:", items: ["Evaluaciones y cuestionarios de detección del desarrollo rutinarios realizados por el pediatra (como el cuestionario ASQ) en citas estándar de 9, 18 y 30 meses.", "Evaluación multidisciplinaria intensiva: Pruebas estandarizadas a través del juego y la observación administradas por neurólogos infantiles, fonoaudiólogos (logopedas), terapeutas ocupacionales y fisioterapeutas.", "Pruebas de audición y visión formales: El paso obligatorio e inmediato para todos los niños con sospecha de retraso en el lenguaje o motor para descartar pérdida sensorial.", "Pruebas genéticas y metabólicas en sangre (para buscar trastornos hereditarios o errores innatos del metabolismo que afecten el cerebro).", "Resonancia magnética (RM) del cerebro si el neurólogo infantil sospecha parálisis cerebral, malformaciones cerebrales congénitas o un trastorno neurológico degenerativo."], note: "El diagnóstico temprano es crítico; el programa de intervención temprana debe iniciar de inmediato incluso antes de que se confirme la causa subyacente del retraso." }, treatment: { title: "Terapia y Programa de Intervención Temprana", intro: "El tratamiento se basa en la neuro-rehabilitación constante, el juego estructurado y el entrenamiento a los padres:", subsections: [ { title: "Enfoques terapéuticos especializados", items: ["Terapia del habla y lenguaje: Fonoaudiólogos enseñan a mejorar la musculatura para articular sonidos, aumentar el vocabulario, usar gestos o, si el niño es no verbal, utilizar métodos de comunicación aumentativa y alternativa (pantallas con imágenes).", "Fisioterapia pediátrica (Terapia Física): Ayuda al niño a desarrollar o mejorar sus habilidades motoras gruesas (equilibrio, control de la cabeza, sentarse, gatear, caminar y correr) fortaleciendo los músculos y el tono.", "Terapia Ocupacional: Intervención dirigida a mejorar las habilidades motoras finas esenciales (usar tijeras, agarrar lápices, atarse zapatos), la coordinación ojo-mano y el procesamiento sensorial (tolerancia a texturas y ruidos).", "Terapia y apoyo psicológico conductual (como el análisis conductual aplicado o ABA) si el retraso está asociado a trastornos del espectro autista u otros problemas severos de conducta.", "Programas estatales de intervención temprana subsidiados, donde terapeutas acuden al hogar o a la guardería para entrenar directamente a los padres en cómo estimular al niño en el día a día."] } ], note: "La participación constante, amorosa y activa de la familia replicando los ejercicios terapéuticos diariamente en casa es la variable que más predice el éxito del tratamiento." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Pediatra?", intro: "Confíe en sus instintos como padre o madre. Solicite una evaluación de desarrollo sin demoras si:", items: ["Su bebé de 4 meses no puede sostener su cabeza en alto o de 9 meses no puede sentarse solo", "Su bebé de 12 meses no gatea o no dice ninguna palabra ni busca comunicarse con gestos", "Su hijo de 18 meses no puede caminar o no señala objetos con el dedo", "Su hijo no responde o no gira la cabeza cuando le llaman por su nombre a partir del primer año", "Cualquier regresión o pérdida súbita de una habilidad física o de lenguaje que el niño ya había logrado alcanzar previamente"] } },
'Amenaza de aborto espontáneo' : { intro: "Una amenaza de aborto es una complicación frecuente y estresante durante el primer trimestre del embarazo, caracterizada por la aparición de sangrado vaginal y dolor abdominal. Afortunadamente, a pesar del sangrado alarmante, con reposo y seguimiento ecográfico, más de la mitad de estos embarazos continúan con éxito hasta el nacimiento.", whatIs: { title: "¿Qué es una Amenaza de Aborto Espontáneo?", text: "Es un diagnóstico médico utilizado cuando una mujer embarazada de menos de 20 semanas experimenta sangrado vaginal y cólicos, pero el cuello uterino permanece cerrado y la ecografía muestra que el feto sigue con vida dentro del útero. Significa que existe un riesgo de perder el embarazo, pero el aborto aún no ha ocurrido." }, symptoms: { title: "Síntomas y Señales Tempranas", intro: "Los signos varían desde leves y transitorios hasta intensos, e incluyen:", groups: [ { name: "Sangrado y molestias", items: ["Sangrado vaginal en las primeras semanas del embarazo (puede variar desde un manchado ligero de color marrón o rosado, hasta sangrado rojo brillante similar a la regla)", "Cólicos abdominales bajos leves a moderados, parecidos al dolor menstrual o calambres uterinos", "Dolor sordo, bajo y persistente en la región de la espalda baja"] }, { name: "Signos de advertencia extrema", items: ["Sangrado muy abundante (empapar más de una compresa gruesa por hora) que contiene coágulos grandes o grumos de tejido grueso", "Dolor abdominal agudo, punzante e insoportable que se concentra en un solo lado del abdomen (puede ser un signo grave de embarazo ectópico)"] } ], warning: "Cualquier sangrado vaginal o dolor abdominal intenso en el embarazo es una razón absoluta para acudir al servicio de urgencias gineco-obstétricas u hospital para una evaluación por ecografía." }, types: { title: "Diferenciación Clínica del Aborto", intro: "El ginecólogo clasificará la situación según los hallazgos en la revisión pélvica y el ultrasonido:", items: ["Amenaza de aborto: Sangrado y cólicos, pero el cuello uterino está firmemente cerrado y hay latido fetal presente en el ultrasonido. El embarazo aún es viable.", "Aborto inevitable: El sangrado y los calambres son muy severos y el examen muestra que el cuello uterino ya se ha abierto (dilatado). El embarazo no podrá continuar.", "Aborto incompleto: El embarazo se ha detenido; parte del tejido fetal o placentario ha sido expulsado, pero otra parte sigue retenida dentro del útero, causando sangrado continuo.", "Aborto retenido (o diferido): El embrión dejó de desarrollarse o no tiene latido cardíaco, pero el cuello uterino está cerrado y no hay signos físicos de aborto ni sangrado."], note: "El manchado leve (spotting) sin dolor intenso es increíblemente común en las primeras semanas por la implantación del embrión y a menudo no representa una verdadera 'amenaza'." }, causes: { title: "Causas y Factores Reales", intro: "En la gran mayoría de los casos de abortos tempranos, el evento es biológicamente inevitable y no es culpa de la madre:", items: ["Anomalías cromosómicas aleatorias (la causa principal que explica casi el 70% de los casos); el embrión tenía un defecto genético severo en la fecundación y no podía desarrollarse para formar un bebé sano", "Anomalías en la cavidad uterina (como fibromas grandes que interfieren con la placenta, o insuficiencia del cuello uterino)", "Niveles anormalmente bajos de progesterona en la madre en la fase inicial", "Infecciones sistémicas severas, fiebre muy alta, o enfermedades crónicas maternas no controladas (como diabetes muy descompensada, trastornos autoinmunes de la coagulación o problemas de tiroides graves)", "El estrés emocional extremo, el ejercicio moderado o mantener relaciones sexuales durante el embarazo NO causan una amenaza de aborto espontáneo."] }, diagnosis: { title: "¿Cómo Evalúa la Situación el Especialista?", intro: "Para determinar la viabilidad y salud del embrión, el equipo médico utilizará pruebas específicas:", items: ["Examen pélvico clínico: El ginecólogo comprobará visualmente con un espéculo si el cuello uterino está cerrado o ha comenzado a abrirse, y de dónde proviene el sangrado.", "Ecografía transvaginal (ultrasonido): La herramienta fundamental de diagnóstico de emergencia para ver si el saco gestacional está en su lugar y, crucialmente, detectar la presencia de latidos cardíacos fetales rítmicos y medir el desarrollo en semanas.", "Análisis de sangre para evaluar los niveles de beta-hCG (hormona del embarazo) a lo largo del tiempo (normalmente los niveles deben duplicarse cada pocos días en embarazos muy tempranos viables).", "Examen de tipo de sangre y factor Rh de la madre (para administrar una vacuna de inmunoglobulina Rh si la madre es Rh negativa y tiene sangrado)."], note: "A veces, un ultrasonido realizado antes de la semana 6 puede no revelar un latido, requiriendo repetir la prueba a la semana siguiente para confirmar." }, treatment: { title: "Manejo Clínico y Medidas de Precaución", intro: "La medicina moderna no puede detener o revertir un aborto en progreso causado por anomalías genéticas profundas, pero apoya un embarazo viable:", subsections: [ { title: "Indicaciones médicas", items: ["Reposo relativo o en cama (limitación estricta de actividades físicas extenuantes, evitar levantar peso y abstinencia total de relaciones sexuales o inserción de tampones para no irritar el cuello uterino).", "Suplementación con hormonas (Progesterona oral, vaginal o inyectada): A menudo se receta fuertemente para apoyar el embarazo en las primeras semanas si los niveles naturales de la paciente son demostrablemente bajos o hay antecedentes previos de abortos de repetición.", "Administración preventiva de analgésicos seguros como el acetaminofén/paracetamol para el dolor leve (se prohíbe el uso de ibuprofeno u otros AINEs por riesgo de hemorragia y daño embrionario).", "Inyección de Inmunoglobulina Anti-D (RhoGAM) si el grupo sanguíneo de la madre es Rh negativo, para prevenir incompatibilidad o ataques inmunológicos en futuros embarazos tras el episodio de sangrado."] } ], note: "La gran mayoría de las mujeres que experimentan sangrado y dolor y se diagnostican con 'amenaza de aborto', tendrán un cese natural de los síntomas en unos días y el embarazo seguirá su curso normal." }, whenToSeekHelp: { title: "¿Cuándo Acudir Rápidamente a Urgencias?", intro: "Cualquier mujer embarazada con sangrado debe ser revisada por un médico el mismo día, pero busque asistencia de emergencia crítica e inmediata si:", items: ["El sangrado vaginal se vuelve tan pesado que empapa una toalla sanitaria gruesa en menos de una hora durante más de dos horas seguidas", "Sufre mareos extremos, debilidad repentina, confusión severa o episodios de desmayo franco", "Expulsa coágulos gruesos del tamaño de una moneda grande o tejido que parece carnoso desde la vagina (guarde el tejido en un recipiente limpio para que el médico lo analice)", "El dolor se vuelve unilateral intenso y punzante en el abdomen o si presenta fiebre y escalofríos"] } },
'Malabsorción' : { intro: "El síndrome de malabsorción es un trastorno crónico y multifactorial del tracto digestivo. Ocurre cuando el intestino delgado pierde su capacidad para digerir y absorber adecuadamente nutrientes esenciales de los alimentos ingeridos, desencadenando una grave desnutrición sistemática a pesar de que la persona tenga un apetito y consumo de alimentos completamente normal.", whatIs: { title: "¿Qué es la Malabsorción?", text: "Es una afección del sistema digestivo en la que las paredes del intestino delgado (las microvellosidades) son incapaces de absorber vitaminas, minerales, carbohidratos, grasas o proteínas de manera eficiente hacia el torrente sanguíneo. Esto provoca que el cuerpo pase hambre de nutrientes a nivel celular." }, symptoms: { title: "Síntomas Gastrointestinales y Deficiencias Clínicas", intro: "Las manifestaciones se dividen en problemas directos en el inodoro y los efectos de estar desnutrido:", groups: [ { name: "Síntomas digestivos", items: ["Diarrea crónica, voluminosa y persistente", "Esteatorrea: Las heces son inusualmente pálidas, de apariencia grasosa, flotan en el inodoro, y tienen un olor excepcionalmente fétido y asqueroso (señal clave de incapacidad para absorber las grasas)", "Hinchazón o distensión abdominal masiva y dolorosa, acompañada de abundantes gases y flatulencia tras comer", "Ruidos intestinales frecuentes (borborigmos) y cólicos"] }, { name: "Síntomas sistémicos por deficiencias crónicas", items: ["Pérdida de peso significativa, rápida y sin esfuerzo, o retraso grave del crecimiento en el caso de bebés y niños", "Debilidad muscular progresiva y desgaste generalizado o pérdida de masa muscular", "Anemia persistente (palidez, cansancio) debido a la incapacidad de absorber hierro o vitamina B12", "Ceguera nocturna (falta de vitamina A), sangrado de encías y tendencia exagerada a moretones (falta de vitamina K), y fragilidad o dolor en los huesos y calambres (falta severa de calcio y vitamina D)"] } ], warning: "Si la malabsorción no se diagnostica y trata, especialmente en niños, el daño por deficiencias neurológicas u óseas severas puede volverse permanente." }, types: { title: "Deficiencias Específicas Frecuentes", intro: "A menudo el problema afecta solo a grupos de nutrientes particulares:", items: ["Malabsorción generalizada: Implica la destrucción de grandes áreas del intestino; el cuerpo no absorbe ni grasas, ni azúcares, ni proteínas (común en celiaquía severa o tras una resección del intestino).", "Malabsorción de carbohidratos: Incapacidad de digerir azúcares específicos (la intolerancia a la lactosa es la más común).", "Malabsorción de grasas: Ocurre a menudo por insuficiencia de enzimas del páncreas o problemas biliares, lo que conduce rápidamente a heces flotantes y pérdida de vitaminas A, D, E y K.", "Malabsorción de Vitamina B12 (Anemia Perniciosa): Ocurre frecuentemente en estómagos dañados o en la enfermedad de Crohn."], note: "La malabsorción de grasas es la más evidente clínicamente y la que provoca deficiencias de salud más peligrosas rápidamente." }, causes: { title: "Causas y Enfermedades Desencadenantes", intro: "El síndrome no es una enfermedad única, es un síntoma grave provocado por fallos en otras estructuras:", items: ["Enfermedad Celíaca y Enfermedad de Crohn: Afecciones autoinmunes devastadoras que causan inflamación destructiva aplanando directamente las paredes absorbentes del intestino delgado.", "Insuficiencia Exocrina del Páncreas: Enfermedades severas (como Pancreatitis Crónica severa, Fibrosis Quística o cáncer de páncreas) donde el páncreas no produce o no segrega las enzimas necesarias para deshacer y digerir la comida.", "Problemas en el hígado o conductos biliares: Falta de bilis necesaria para absorber las grasas de forma adecuada.", "Síndrome del intestino corto o cirugía bariátrica extensa: Afecciones donde grandes porciones del tracto digestivo o el intestino han sido extirpadas quirúrgicamente, dejando poca longitud para la absorción.", "Sobrecrecimiento bacteriano en el intestino delgado (SIBO), uso prolongado agresivo de ciertos antibióticos o infecciones parasitarias intestinales crónicas como la Giardiasis."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El gastroenterólogo usa un enfoque por pasos para detectar qué falla y por qué:", items: ["Análisis extenso de heces (Prueba de grasa en heces de 72 horas): La prueba estándar más fiable. Si hay gran cantidad de grasa excretada en las heces, significa claramente que no se está absorbiendo.", "Análisis de sangre integrales: Pruebas clave para medir la presencia en la sangre de hierro, calcio, vitaminas B12 y folato, o la deficiencia de albúmina y factores de coagulación; así como anticuerpos y serología específica para la enfermedad celíaca.", "Pruebas de aliento con carbohidratos (D-xilosa o lactosa) para descubrir intolerancias enzimáticas específicas y problemas de crecimiento bacteriano intestinal excesivo.", "Endoscopia superior, colonoscopia y biopsia del intestino delgado: El paso definitivo donde se toma un diminuto trozo de la pared intestinal para confirmar, bajo el microscopio, si las vellosidades de absorción están aplanadas, destruidas por una inflamación celular o intactas.", "Imágenes del abdomen (Tomografía o RM) para identificar si el páncreas está calcificado y fallando (pancreatitis crónica)."], note: "El paciente a menudo debe pasar semanas registrando un diario exacto de sus dietas para aislar cuál nutriente específico le provoca los ataques digestivos." }, treatment: { title: "Estrategias de Reemplazo y Curación", intro: "El tratamiento es agresivo y se concentra simultáneamente en manejar los síntomas y reparar las deficiencias mortales:", subsections: [ { title: "Manejo médico y dieta terapéutica", items: ["Dietas de exclusión estrictas y de por vida (la base del tratamiento en muchas afecciones): Dieta absolutamente y para siempre libre de gluten en el caso exclusivo de padecer enfermedad celíaca, o eliminación total y radical de la lactosa si se detecta intolerancia aguda.", "Terapia de Reemplazo de Enzimas Pancreáticas (PERT): Administrar al paciente cápsulas que contienen enormes dosis de enzimas digestivas antes de cada comida o bocadillo para digerir la grasa, fundamental si padece de insuficiencia del páncreas o fibrosis quística.", "Antibióticos intestinales específicos o medicamentos antiparasitarios fuertes si se diagnostica un sobrecrecimiento bacteriano (SIBO) o infecciones severas como Giardia.", "Suplementos de reposición masiva (administrados a menudo por inyección intramuscular o vía intravenosa al principio, ya que el intestino no asimilaría las pastillas) de altas dosis de Vitamina B12, Ácido fólico, Vitamina D, Calcio e inyecciones de hierro, para combatir la anemia celular.", "Soporte nutricional avanzado especializado en el hospital (nutrición parenteral) para pacientes con casos terminalmente severos de desnutrición y síndrome de intestino corto profundo."] } ], note: "Una vez que se identifica y se retira el agente agresor (ej. gluten) o se aportan las enzimas digestivas, las vellosidades dañadas del intestino delgado generalmente pueden repararse por sí solas tras varios meses." }, whenToSeekHelp: { title: "¿Cuándo Contactar de Urgencia al Gastroenterólogo?", intro: "No demore y busque evaluación de medicina interna especializada si:", items: ["Presenta deposiciones crónicas pálidas, inusualmente malolientes, voluminosas, o que dejan una capa grasienta muy brillante y persistente en el inodoro y son difíciles de tirar de la cadena", "Ha experimentado una pérdida rápida de varios kilos de su peso corporal, se ve a menudo demacrado, pero no está intencionalmente a dieta y come cantidades normales", "Las heces son muy líquidas, el niño o el bebé presenta una tripa dura, voluminosa e hinchada y no está ganando la altura o el peso acordes a su curva de edad (falta de medro)", "Se siente mareado todo el tiempo y sufre frecuentemente sangrado en la encía inexplicado, adormecimiento severo de los pies o problemas visuales en la oscuridad"] } },
'Trastorno del desarrollo de la lectura' : { intro: "El trastorno específico del desarrollo de la lectura, más conocido como dislexia, es el trastorno de aprendizaje más común de origen neurobiológico infantil. Afecta severamente la fluidez, la capacidad de reconocer palabras de forma precisa y la ortografía en individuos con una inteligencia completamente normal.", whatIs: { title: "¿Qué es la Dislexia (Trastorno de Lectura)?", text: "Es una discapacidad de aprendizaje de base neurológica que afecta crónicamente la forma en que el cerebro procesa el lenguaje escrito y hablado. Provoca una dificultad grave y persistente en el aprendizaje de la lectura fluida, ya que al paciente le cuesta identificar los sonidos del habla (conciencia fonológica) y comprender cómo se relacionan y conectan con las letras del alfabeto (decodificación)." }, symptoms: { title: "Síntomas y Retos Educativos", intro: "Se manifiesta claramente cuando el niño entra a la escuela primaria, aunque puede haber señales tempranas:", groups: [ { name: "Signos en la lectura y escritura", items: ["Dificultad evidente y gran lentitud, esfuerzo e imprecisión para leer en voz alta", "Problemas frecuentes al invertir el orden de las letras en palabras cortas (por ejemplo, leer 'se' en lugar de 'es', o 'los' por 'sol')", "Escritura o dictado severamente defectuoso o incomprensible y mala ortografía con errores básicos y recurrentes", "Lectura entrecortada y pérdida constante del hilo de la narración en la lectura comprensiva", "Dificultad o incapacidad total para memorizar rimas infantiles o deletrear verbalmente su propio nombre"] }, { name: "Síntomas conductuales por frustración", items: ["Ansiedad intensa, llanto o gran rechazo sistemático a leer en el aula o a completar las tareas escolares en casa relacionadas con texto", "El alumno a menudo entiende perfectamente los conceptos verbales profundos, pero falla estrepitosamente en los exámenes o pruebas donde se requiere responder de forma escrita o leer velozmente", "Baja autoestima académica, autodesprecio o sensación errónea de ser 'tonto' frente a los otros niños de clase"] } ], warning: "Si no se trata y apoya educativamente en la primaria baja, el fracaso escolar severo provocado por la dislexia se agrava progresivamente por desmoralización, estrés y retraso sistemático del aprendizaje." }, types: { title: "Diferenciación de Afecciones Concurrentes", intro: "Se manifiesta frecuentemente acompañada de otras discapacidades del aprendizaje:", items: ["Dislexia Fonológica: El subtipo principal y abrumadoramente más común; implica un déficit extremo para aprender o descomponer las partes o sonidos individuales que forman una palabra y unirlas.", "Dislexia Superficial (ortográfica): Los individuos pueden descifrar las palabras usando reglas fonéticas, pero fallan en reconocer o almacenar las 'imágenes de palabras completas', por lo que siempre leen lentos sin alcanzar la fluidez automática en la lectura rápida.", "Comorbilidades: Es increíblemente prevalente que un niño disléxico tenga diagnósticos asociados reales, como Disgrafía (dificultad crónica y dolor con la escritura motora), Discalculia (trastorno de las matemáticas), o coexistencia de Trastorno por Déficit de Atención e Hiperactividad (TDAH)."], note: "La dislexia no se trata de un problema en el campo visual; los niños disléxicos no 'ven' las palabras saltando ni las letras al revés por un error óptico, sino que el cerebro falla en decodificar mentalmente los patrones impresos." }, causes: { title: "Causas y Disfunciones Neurológicas", intro: "Es un problema neurobiológico y hereditario, no resultado de la pereza o un mal entorno escolar:", items: ["Diferencias estructurales y de conectividad en el cerebro: Los escáneres funcionales por resonancia magnética (fMRI) muestran que las áreas cruciales de la parte izquierda del cerebro involucradas en el procesamiento profundo del lenguaje y la decodificación ortográfica funcionan de forma distinta, menos activa y diferente que en un lector tradicional.", "Altísimo factor hereditario y genético (si uno de los progenitores padece dislexia o severos problemas en el aprendizaje pasados de alto en la escuela, hay enormes probabilidades de que los hijos la presenten).", "Factores prenatales: Exposiciones a eventos que alteran el neurodesarrollo primitivo, bajo peso al nacer intenso, nacimiento excesivamente prematuro y otras afecciones perinatales.", "Es un mito que la dislexia esté directamente causada por una instrucción escolar de mala calidad o negligencia de los padres; aunque un ambiente muy estimulante ayuda a sobrellevarla, no la cura."] }, diagnosis: { title: "¿Cómo se Detecta y Diagnostica Múltiplemente?", intro: "Solo puede ser certificada por especialistas, requiriendo pruebas exhaustivas con protocolos estandarizados de edad y rendimiento intelectual:", items: ["Entrevistas psicosociales extensas y profundas, con el historial de educación, del entorno del aula y pruebas tempranas al nivel de primaria con los padres y docentes.", "Pruebas Neuropsicológicas y de Aprendizaje completas (aplicadas de forma independiente por psicólogos educativos): Estas pruebas evaluarán rigurosamente todos los componentes de la habilidad de lectura, como la conciencia fonológica crucial, lectura automática fluida, retención de memoria de letras o el reconocimiento y deletreo profundo del vocabulario.", "Pruebas Psicométricas y Cognitivas (test estandarizados del coeficiente intelectual o CI): Necesarias fundamentalmente para descartar sin duda una discapacidad intelectual; las personas disléxicas tienen habitualmente habilidades e inteligencia general normal, igual al promedio, e incluso superior a él.", "Pruebas exhaustivas médicas pediátricas, oftálmicas completas y de audición obligatorias, como primer escalón a la evaluación, para confirmar que todo rastro de discapacidad en la visión de las letras o los problemas auditivos (no poder oír correctamente o ver la pizarra) queda rotundamente descartado en el diagnóstico temprano."], note: "Dado que es muy común, las escuelas progresistas realizan rutinariamente evaluaciones preventivas de detección e intervención temprana de la conciencia fonológica antes de iniciar primer grado." }, treatment: { title: "Enfoque Educativo Terapéutico Específico", intro: "No existen pastillas o curas para sanar y revertir la dislexia a largo plazo. Sin embargo, su abordaje es muy manejable, utilizando estrategias específicas basadas en programas educativos para el individuo:", subsections: [ { title: "Adaptaciones e Intervenciones Especiales Escolares", items: ["Instrucción tutorial fonológica e individualizada (Aproximación Multisensorial y Orton-Gillingham): Técnicas avaladas exhaustivas de intervención diaria para enseñarle intensivamente las reglas, códigos o sonidos combinando todos los sentidos corporales (tocando y dibujando letras de arena, escuchando ritmos) para trazar rutas neuronales compensatorias en el cerebro.", "Intervenciones por parte del Logopeda especializado y fonoaudiólogo para mejorar severamente el vocabulario, las rimas, y la producción fonológica auditiva básica.", "Plan o Programa Educativo Personalizado Individual o Sección 504 formal (para el ámbito escolar general): Las escuelas deben establecer por ley protocolos específicos tales como asignarle más de un 50% de tiempo adicional para cada examen crucial en clase, proporcionar instrucción oral alternativa a los largos cuestionarios, o la reducción masiva de tareas o lecturas densas en voz alta obligatorias frente a los compañeros para eludir graves ataques de pánico escolares.", "Uso de Herramientas y Apoyo de Tecnología de Asistencia en el día a día para evitar problemas en el fracaso adulto (Uso de software estandarizado de lectura de pantalla para que el ordenador lea su libro de texto de audio, usar software de predicción y corrección ortográfica o dictado directo por micrófono verbal, etc.)."] } ], note: "Fomentar un autoestima alta e identificar otras habilidades creativas y fortalezas de resolución (artes visuales y deportes o liderazgo) es igual de crítico como lo es la propia enseñanza correctiva de lectura en este duro y largo trayecto mental." }, whenToSeekHelp: { title: "¿Cuándo y A Quién Pedir Atención Profesional Rápida?", intro: "Abogue fuertemente por buscar orientación del consejero escolar, psicólogo escolar y pediatra, sin excusas ni tardanzas temporales, si su hijo/a en la escuela primaria está pasando por:", items: ["Llora amargamente con frecuencia o finge continuas enfermedades o dolores gástricos y de cabeza por las mañanas solo para poder esquivar las tareas de lectura obligatoria o asistir a la escuela en general", "En el paso de jardín de infantes al primer grado de edad o seis años muestra una enorme torpeza o retrasos a nivel de habla graves y tiene severas complicaciones insuperables en tareas de separar y aplaudir sílabas", "Es elogiado abiertamente por el profesor o adultos por ser un niño extremadamente brillante, resolutivo e imaginativo durante debates orales profundos, pero misteriosa o llamativamente fracasa sistemáticamente para deletrear palabras como 'mi', 'el', 'la', de manera correcta en la página escrita"] } },
'Discapacidad intelectual' : { intro: "La discapacidad intelectual es una condición permanente del neurodesarrollo caracterizada por deficiencias significativas en el funcionamiento intelectual y el comportamiento adaptativo del paciente. Su diagnóstico temprano, acompañado de terapias especializadas y educación inclusiva, es crucial para maximizar la autonomía del individuo y proporcionarle habilidades vitales para llevar una vida plena e independiente dentro de sus capacidades funcionales.", whatIs: { title: "¿Qué es la Discapacidad Intelectual (DI)?", text: "Antiguamente denominada retraso mental, es un trastorno originado antes de los 18 años que altera el desarrollo cerebral limitando profundamente la capacidad mental general de una persona (como aprender en profundidad, razonar de modo abstracto y tomar decisiones críticas) y mermando gravemente su comportamiento adaptativo (las habilidades conceptuales diarias, interpersonales y sociales que usamos rutinariamente cada jornada para comunicarnos, trabajar y subsistir)." }, symptoms: { title: "Principales Hitos del Desarrollo Afectado y Conductas Atípicas", intro: "Los primeros síntomas observables ocurren frecuentemente en bebés y preescolares con notorios desfasajes biológicos, tales como:", groups: [ { name: "Retrasos conductuales adaptativos (Habilidades sociales, lingüísticas y físicas)", items: ["Adquisición muy lenta, o casi inexistente comparada con los estándares esperables, del proceso motor grueso (sentarse de manera equilibrada, gatear activamente o empezar a caminar sin asistencia) durante la niñez temprana", "Complicaciones masivas, muy evidentes o retrasos prolongados en las áreas del desarrollo lingüístico y fonoaudiológico (dificultades pronunciadas para hablar con claridad las frases de estructura lógica de manera esperable o entender mensajes verbales orales)", "Imposibilidad profunda e inoperancia repetida ante el intento social de aseo diario o las rutinas domésticas más normales de higiene individual independiente tales como alimentarse a solas, el aseo o saber de seguridad corporal, ir al baño, vestirse por las mañanas", "Incapacidad constante o extremada de predecir o entender instintivamente lo que desencadena lógicamente que una conducta riesgosa conlleva duras e inmediatas consecuencias negativas o físicas ante el accionar y el entorno real"] }, { name: "Indicadores en funciones del intelecto y cognición escolar o resolutiva", items: ["Grandes impedimentos de larga trayectoria académica y cognitiva, fallando de modo patente para almacenar en la memoria rutinas e internalizar las reglas básicas sociales establecidas en el entorno o no acatar el espacio personal o la noción real del dinero circulante y tiempo natural", "Gran o severo grado de limitación constante en procesos lógicos de solución y resolución de problemáticas con más de dos secuencias de trabajo e imposibilidad constante frente a procesos matemáticos y analógicos rutinarios o básicos"] } ], warning: "Si la carencia de las habilidades cognitivas e incapacidades sociales se presenta abruptamente o el niño presenta un comportamiento o regresiones del aprendizaje muy rápidas o con ataques masivos de ansiedad o pánico físico y convulsivo en cuestión de pocos días o en la temprana adolescencia de las etapas de edad, resulta inminente una pronta hospitalización y evaluación profunda médica especializada." }, types: { title: "Sistema Categórico Actual e Impacto Funcional", intro: "Se evalúa y se categoriza globalmente la profundidad en niveles según la funcionalidad de los pacientes para brindar y medir el soporte especializado adecuado y oportuno del requerimiento diario que poseen en su comunidad:", items: ["Leve (CI entre 50 y 69 aproximadamente): Abarcan la absoluta mayoría y a gran parte (casi el 85%) de la incidencia de las personas que poseen tal disfuncionalidad en la sociedad; en su niñez y edad adulta la adquisición escolar básica de conocimiento para leer o calcular los números matemáticos se encuentra retrasada a una edad estándar del desarrollo del pensamiento del período primario escolar superior de una de seis y hasta de 12 o de 11 años biológicos normales aproximadamente.", "Moderado (CI rondando y marcando 35 a 49): Requieren constantemente bastante apoyo escolar continuo para alcanzar y poseer ciertos aprendizajes formativos o funcionales de habilidades sociales básicas del accionar social como la comprensión lógica verbal pero frecuentemente alcanzan la suficiente aptitud de la autonomía operativa e incorporan los oficios vocacionales rudimentarios o las tareas productivas de menor calibre si permanecen en instalaciones supervisadas y adaptadas a ellos.", "Grave (CI inferior a niveles estables de 34 hasta 20): Precisan ayuda masiva o sostén prolongado intensivo e instructivo general a todo tiempo cada día para que entiendan cabalmente sus nociones del espacio conceptual social de alfabetización comunicativa; sus destrezas principales para los autocuidados básicos biológicos en casa necesitarán, siempre para el accionar y sin omisión a ninguna, soporte y un andamiaje tutorial constante bajo la atención de terceros las jornadas enteras de la vida adulta regular en el futuro para evitar su colapso total general.", "Profundo: Comúnmente tienen graves o enormes padecimientos a nivel estructural subyacente de naturaleza de fallas y condiciones neurológicas; necesitan un apoyo general profundo sin descansos de la autonomía total e incluso permanente supervisión ininterrumpida biológica en sus residencias asistidas las veinticuatro horas."], note: "Los recientes protocolos o consensos de psiquiatría se orientan muchísimo menos, cada jornada más, al índice histórico obsoleto de 'CI' medido en pruebas cerradas, centrándose más en medir exhaustiva y cuidadosamente con tests psicológicos modernos la cuota exacta de apoyatura para integrarlos e instruirlos adaptativamente a todos por igual para la reinserción e integración en ambientes neurotípicos del progreso en los que coexisten." }, causes: { title: "Patologías Asociadas de Origen a Deficiencias en Casos Comprobados", intro: "Cualquier padecimiento o acontecimiento traumático cerebral durante la formación física embriológica gestacional del período de desarrollo intrauterino o durante la pre-pubertad o el nacimiento fetal es perjudicial en la estructura base biológica normal de las funciones orgánicas neurológicas principales; aunque frecuentemente los orígenes pueden deberse o estar asociados al:", items: ["Problemas patológicos, trisomías cromosómicas profundas, carencias y defectos hereditarios y genéticos biológicos severos desde la creación concepcional (Como padecimientos principales predominantes diagnosticados el Síndrome de Down, el extendido Síndrome neuro-comportamental de fragilidad de X, o el Síndrome Prader-Willi de origen de alteración o desbalance patológico cromosómico).", "Incidentes peligrosos vinculados al mal control ambiental médico del riesgo extremo durante el embarazo formativo natural que desencadenaron malformación: Presencia de síndromes tóxicos teratogénicos y un uso habitual o un daño biológico permanente agudo en caso al someter y de someterse al alto índice del feto a los consumos y drogas ilícitas graves por adicción incontrolable severa e infecciones maternas fuertes de agentes víricos tóxicos o del Trastorno del neurodesarrollo profundo englobado y ligado fuertemente al espectro general extendido que se identifica grave por causa patológica real debido al alcohol gestacional sistémico diagnosticado severo durante una ingesta alcohólica excesivamente extrema en el proceso por falta abstinente real materna.", "Asfixia obstétrica, lesiones del trabajo durante la complicación aguda o laborioso parto asfixiante cerebral extremo o los nacimientos muy precipitados antes o con semanas excesivamente marcadas sin término u oxígeno (isquemia global severa).", "Golpes graves craneales letales traumáticos que se presentan infantiles después del nacimiento patológico tras secuelas en la edad y crecimiento neurológico u otras posibles enfermedades (como una meningitis bacteriana y del encefalo crónico agresivo profundo o en su defecto de afecciones e intoxicaciones progresivas ambientales persistentes como los plomos pesados severos en tuberías de vivienda antigua en barrios industriales precarios sin urbanizar)."] }, diagnosis: { title: "¿En Qué Exámenes Prácticos Consisten Las Técnicas de Corroboración Principal Diagnosticadas?", intro: "Evaluación formal exhaustiva para un dictamen clínico adecuado a largo y prolongado progreso general del desarrollo temprano; y que generalmente son guiadas exhaustiva e integralmente y solicitadas en equipo completo transdisciplinario con herramientas probadas por parte de psicólogos e intervención experta infantil neuropsiquiátrica, por pediatras, el equipo psicopedagogo educacional integral de inclusión profunda o por el asistente y trabajador genético si la prueba clínica exige descarte principal en base a:", items: ["Evaluaciones psicosociales cognitivas generales y los test aplicados del Coeficiente Psicométrico Clínico Intelectual (Ej.: Test Wechsler de Inteligencia u otras pruebas validadas formalmente para cada nivel socioeconómico exacto y adaptativo a los estándares formativos del CI total estándar evaluados a lo largo).", "Verificaciones precisas del funcionamiento diario vital y la maduración progresiva comportamental social y de capacidad física del manejo personal comunicativo adaptativo de habilidades básicas conductuales instrumentales tales como en particular por caso la prueba e inventario formal estándar VAB de madurez y el manual Escala Conductual Evaluativa Adaptativa y Cognitiva general (para registrar profundamente qué tan solvente para integrarse resultará y cuánto apoyo y atención en realidad le otorgarán en conjunto para valerse a todos e identificar lo mejor sus niveles deficientes reales en el individuo en situaciones comparadas sin pre-condicionar su CI base en aislamiento general total).", "Identificaciones de anomalías causales a cargo principal por parte clínica con análisis especializados amplios exhaustivos neurológicos para rastrear anomalías del metabolismo biológico, neuroimágenes (resonancias, TCs cerebrales para ubicar alteraciones cerebrales base e investigar y rastrear dismorfias o las patologías subyacentes), o cribados sistémicos de la salud sanguínea o exámenes exhaustivos minuciosos cariotípicos de microarreglos en la base de la secuenciación completa molecular si el patrón sintomático sindrómico corporal indica rastrear y dictaminar o descubrir posibles alteraciones genéticas complejas e incurables y prevenir a futuro e indagar un factor clínico degenerativo para todos su familia del lazo heredado posible."], note: "La atención global general nunca asume jamás apresuradamente por deducción general al diagnosticar de primer instante; y se requiere exhaustivamente constatar repetidas e innegables debilidades que demuestren severidad en simultaneidad constante en ambos y múltiples aspectos vitales para dar un cierre categórico y certificar una patología tal." }, treatment: { title: "Servicios y Herramientas del Soporte y Rehabilitación Integral Adaptada e Intervención Específica", intro: "Carece a nivel universal y base científica definitiva de cura farmacológica en específico que solvente y cambie para bien en su totalidad general una función cognoscitiva neuro-estructural cerebral deficiente basal o restablezca niveles de función perdidos, pero todos los múltiples abordajes de intervención temprana resultan cruciales para modificar las trayectorias para mejor funcionalidad global que impulsan el desarrollo pleno en ambientes tolerantes, mediante las vías de planes individualizados y estructurados del aprendizaje para sus aptitudes máximas y de adaptación:", subsections: [ { title: "Atención Integrada Temprana Y de Servicios Básicos Orientados en Educación de por vida y Planes de Habilidades Funcionales y de Apoyos Sistémicos Generalizados del Autocuidado", items: ["Plan de Educación o de Integración Escolar Individualizada formal para los ambientes escolares de educación neurotípica e integración social guiado y adaptado del ritmo regular al alcance total de todos sus logros u objetivos (como el PEI educativo).", "La crucial terapia logopédica para ayudar a incentivar profundamente las barreras verbales que fomenten todo lo indispensable a potenciar la fluida función comunicativa base, la psicomotricidad, las bases cognitivas y enseñar metodologías o sistemas pictóricos si la persona se encuentra en una de las vías extremas para hablar con lenguaje hablado limitante (ej. Comunicación Aumentativa), la terapia ocupacional intensificada y fomento constante del desarrollo en terapias conductuales sociales en comunidad (para fomentar en forma estandarizada los oficios en caso del grupo adulto mayor en residencias y entrenar de forma repetida rutinas para que asuman autocuidados biológicos o prevengan e insertarse).", "La utilización fundamental médica terapéutica farmacológica auxiliar para solventar paralelamente e incorporar a la rutina si las patologías anexas asociadas graves e incapacitantes de control al caso presenten en simultaneidad ataques incontrolables generalizados convulsivos focales severos crónicos persistentes, hiperactividad o el descontrol TDAH grave, depresión base sistémica, manías o las ansiedades profundas e irritabilidad psicosocial aguda asociadas en crisis e inestabilidad del ánimo prolongadas o agudas perjudiciales incontrolables por carencia de adaptación."] } ], note: "Promover en todos sus años en el ambiente los programas para dotarles de independencia general gradual a todos mediante talleres especializados con integración comunitaria y laborales asistidos en tareas controladas supervisadas o repetitivas logran impactos profundos excelentes que dotan de una elevadísima dignidad e incontestable calidad e igualdad general social o de calidad total en su progreso integral y funcional de su vida entera de persona o familia e individuo particular en grupo y a lo ancho mundial a todas horas en ambiente seguro total de soporte absoluto de equidad y diversidad y neuro-equidad continua o universal asistida progresiva general e irrestricta." }, whenToSeekHelp: { title: "¿En Qué Ocasiones Se Deben Reportar Banderas Para Buscar Intervención Inmediata con Atención Inicial Integral o de la Asistencia del Sector Temprano e Investigaciones de Derivación Clínicas Pediátricas por Discapacidad Base?", intro: "Agende y coordine fuertemente sin reparo con su centro para la asistencia e intervención inmediata local pediátrica sin dilatar si sospechan o han de visualizar firmes en su crecimiento y desarrollo integral del pequeño en la niñez temprana un caso de involución biológica con pautas, signos que aseveren en general los indicadores como por causa:", items: ["El notable estancamiento y prolongada regresión y retrasos muy claros durante un período extenso y persistente superior a varios u otros meses cronológicos frente a cualquier patrón general psicomotor infantil típico si no reacciona al juego repetido para alcanzar hitos primarios estipulados u obligatorios a su respectiva y correspondiente etapa inicial del aprendizaje (tardanza extrema en gateo normal para movilizar e integrar la curiosidad u observar o voltear el contacto e ignorar para no oír de lejos).", "La extrema desconexión o grave apatía en absoluto sin reaccionar afectivamente o mirar ni con seguimiento social con la vista ante intentos normales y la falta incomprensible a las solicitudes de imitación vocal expresiva o para expresar un juego infantil general del aprendizaje o una palabra u otra seña si pasó en abundancia un primer año o año y medio inicial de la etapa infantil integral general normal del aprendizaje que en todo ambiente familiar logre comunicar social e integrar un lenguaje por básico al menos comunicativo que es requerimiento mínimo comunicativo funcional integral por caso a tiempo total para los otros e integrarse en guarderías de un período escolar en todo su ambiente."] } },
'Enfermedad vascular periférica' : { intro: "La enfermedad vascular periférica es una patología circulatoria en la que el estrechamiento severo de las arterias disminuye el suministro de sangre, principalmente a las extremidades inferiores. Es una manifestación crítica de la aterosclerosis sistémica; quienes la padecen tienen un altísimo riesgo concomitante de sufrir ataques cardíacos o derrames cerebrales, siendo el dolor opresivo al caminar su síntoma inicial más devastador.", whatIs: { title: "¿Qué es la Enfermedad Arterial Periférica (EAP)?", text: "Es un trastorno progresivo de la circulación sanguínea causado por la formación de depósitos crónicos de placa grasa (colesterol y calcio) dentro de las paredes arteriales, que estrechan o bloquean completamente los vasos que nutren los músculos de las piernas y, con menor frecuencia, los brazos o los riñones." }, symptoms: { title: "Manifestaciones Físicas y Sensoriales", intro: "Los síntomas clásicos de advertencia progresan desde molestias leves hasta un daño isquémico grave si no se corrige la circulación:", groups: [ { name: "Síntomas inducidos por el ejercicio", items: ["Claudicación intermitente (el sello clínico de la EAP): Un dolor, calambre intenso, debilidad y pesadez que aparece en las pantorrillas, muslos o glúteos al caminar o subir escaleras de manera predecible, y que desaparece mágicamente tras descansar unos minutos", "El dolor siempre regresa casi inmediatamente si el paciente retoma la actividad física al mismo nivel"] }, { name: "Síntomas en etapas crónicas avanzadas e isquemia grave", items: ["Aparición de un dolor sordo y urente insoportable en los pies y dedos de los pies incluso estando en absoluto reposo o durmiendo por la noche", "Heridas, úlceras isquémicas dolorosas o úlceras oscuras en los dedos de los pies o en las piernas que no cicatrizan después de semanas", "Decoloración evidente de las piernas (tono azulado pálido o rojizo muy oscuro si están colgando) y un fuerte descenso de la temperatura en una extremidad inferior (pie inusualmente frío) al comparar con la otra pierna", "Pérdida localizada del vello en las piernas, piel brillante, delgada y tensa con notable disminución en el crecimiento de las uñas"] } ], warning: "Cualquier desarrollo súbito y repentino de dolor severo en reposo, pérdida de sensación o un cambio abrupto a un color gris/pálido o negro (necrosis/gangrena) en las extremidades requiere intervención quirúrgica endovascular inmediata en el mismo día para prevenir la amputación radical inminente." }, types: { title: "Etapas y Categorización de Progreso", intro: "La gravedad se clasifica mediante protocolos médicos (como la clasificación de Fontaine o Rutherford) que evalúan la urgencia del bloqueo circulatorio:", items: ["Enfermedad Periférica Asintomática (Grado leve): La mayoría de los pacientes (hasta un 50%) inicialmente no notan signos claros o los atribuyen erróneamente al simple envejecimiento muscular.", "Claudicación Intermitente Limitante (Grado moderado): La distancia a la que aparece el calambre muscular al caminar se acorta progresivamente, volviendo las rutinas de la vida diaria en un desafío agotador.", "Isquemia Crónica que Amenaza las Extremidades / Isquemia Crítica en Reposo (Grado final devastador): El bloqueo arterial ahora es tan masivo y extendido que la sangre no es suficiente ni para mantener sanos los tejidos básicos del pie en reposo, lo que invariablemente lleva a úlceras isquémicas muy necróticas o amputación mayor si la revascularización hospitalaria fracasa rotundamente."], note: "La presencia clínica del síntoma claro de claudicación intermitente indica que casi con certeza existen graves o múltiples bloqueos asintomáticos a nivel de la enfermedad coronaria del paciente." }, causes: { title: "Factores Principales Desencadenantes de Riesgo Isquémico Subyacente", intro: "El depósito obstructivo en la pared de las arterias (aterosclerosis periférica severa generalizada) está fuertemente impulsado por factores de estilo de vida evitables y controlables y enfermedades sistémicas no reguladas:", items: ["El tabaquismo activo persistente crónico y severo o antecedentes crónicos fuertes de fumador (el factor pronóstico más abrumador, poderoso e individual que incrementa hasta 400% el riesgo relativo de aparición acelerada y amputación para desarrollar esta afección periférica específica en toda la población clínica evaluada y generalizada de pacientes frente a no fumadores de manera contundente y progresiva).", "La Diabetes Mellitus mal controlada sostenida o crónica (los azúcares y glucosa elevados sistemáticamente destruyen la pared endotelial de la base capilar fina y aceleran enormemente los bloqueos letales progresivos extensos en la extremidad o pie con alto riesgo agravado concurrente para generar una úlcera o complicación neuropática irreversible al pie o al tobillo).", "Edad (mayor de 50 a 65 años) sumado a la hipertensión crónica agresiva que lesiona la arteria severamente a la par del colesterol general y el índice del colesterol perjudicial de los valores LDL persistentemente hiperlipidémicos en el rango metabólico gravemente incontrolado general asintomático del paciente.", "Antecedentes familiares de arteriopatías coronarias o aterosclerosis familiar sistémica y genética en las paredes venosas periféricas inflamatorias crónicas."] }, diagnosis: { title: "¿En Qué Consisten y Cuáles Son Las Modalidades Opciones De Herramientas Diagnosticadas de Evaluación en Vascular Periférico?", intro: "Para clasificar formalmente su nivel agudo y determinar e individualizar la gravedad general e integridad circulatoria precisa al detalle se recurre principalmente al control urológico/cirujano vascular, a cardiólogos invasivos, para la implementación diagnóstica:", items: ["Índice Tobillo-Brazo (ITB u ABI): El método no invasivo más eficiente inicial estándar diagnóstico fundamental de primera elección u estándar de medida universal, muy rápido (comparando las presiones sanguíneas arteriales formales mediante un tensiómetro normal en los brazos contraído frente o contra los tobillos tomadas en reposo; si en su diferencia la presión en la extremidad inferior cae estrepitosamente significa un déficit diagnóstico circulatorio arterial contundente y seguro).", "Exploración Física Vascular Inmediata: Palpación especializada meticulosa de todos los pulsos pedios y poplíteos localizados tras y por detrás de las rodillas del paciente o en todos los tobillos para rastrear si los pulsos latentes desaparecieron del mapa físico del cuerpo por la oclusión y buscando oclusiones venosas por ecografías en el estetoscopio soplos sistólicos ruidosos arteriales en cuellos o venas por flujos bloqueados o arremolinados de forma grave e identificar asimetrías del pulso latente profundo en urgencias u hospitalarias graves al tiempo agudo en control básico exhaustivo o si es muy leve por rutina.", "Ecografía vascular Doppler Dúplex a color y detallada que visualiza de manera en tiempo real la integridad general progresiva estructural o para ver zonas puntuales o venas periféricas colapsadas con placas obstructivas severas o de forma superficial que determinan el área focalizada afectada para realizar posteriormente el mapeado cartográfico anatómico e iniciar la reconstrucción.", "Prueba en la caminadora: Evaluaciones de resistencia clínica donde se usa para desencadenar el síntoma bajo revisión formal o reproducir en un entorno formal clínico si es real claudicación (haciéndole al individuo forzar caminatas en banda para calcular a los qué kilómetros frena por los fuertes calambres inducidos).", "Imágenes angiográficas invasivas especializadas por Resonancia Magnética o ATC (Angiotomografía Computarizada detallada a base de iodo intravascular u opacos): Imprescindibles en fase previa operativa o plan quirúrgico que crean mapeo de imagen vascular radiológica invasiva de todo el recorrido para buscar cómo saltar los atascos venosos en la zona quirúrgica específica para el baipás o plan de stent focal en oclusiones completas del bloqueo isquémico en reposo crónico general de extremidades arteriales totales."] }, treatment: { title: "Abordajes Terapéuticos Intervencionistas O Medidas De Prevención Extrema Para La Gestión del Rescate Severo e Integral", intro: "Para rescatar el pie vascular de la amputación del miembro grave general y poder prevenir el progreso de ataques mortales colaterales a distancia el plan es sumamente estricto e incluye un proceso crónico e intensivo vital para paliar e iniciar terapia rehabilitatoria y quirúrgica obligatoria para las isquemias periféricas:", subsections: [ { title: "Manejos y Opciones Clínicas Base para las Claudicaciones Límite e Intervención Para Recuperar Miembros Crónicos Agudos Generalizados y Tratamientos Sistémicos Prolongados Integrados del Nivel Isquémico", items: ["Modificaciones del estilo en forma dramática de vida u obligación primaria para detener toda destrucción arterial, que con abrumadora urgencia imperiosa dicta sin dudar abandonar permanentemente en seco y por siempre el hábito del fumador con el tabaquismo (esto salva extremidades enteras inmediatamente y frena al síntoma mejor que mil medicamentos generales o drogas crónicas del control rutinario), combinados obligatoriamente al régimen de un ejercicio altamente especializado llamado 'Terapia de caminata guiada y controlada por claudicación', forzando y entrenando con dolor controlado la extremidad isquémica isquémica isquémica para forzar médicamente al desarrollo físico biológico progresivo gradual secundario arterial colateral vascular profundo a los tejidos que reemplaza las vías del flujo viejo e induce nuevos conductos diminutos vitales en reposo profundo a meses si se sigue al pie del dolor del calambre guiado (rehabilitación estructurada supervisada indispensable).", "Optimización y tratamiento polifarmacológico estricto del paciente para impedir complicaciones generales mortales coronarias a futuro, instaurando la administración sistemática intensiva diaria crónica general con medicamentos antiplaquetarios recetados de por vida (como la aspirina de baja dosis, y el fuerte cilostazol o el clopidogrel para lograr calmar enormemente y ampliar la distancia de caminata previa del síntoma del dolor grave agudo de isquemia general del movimiento o los calambres). Y recetar terapias estatinas con rigor crónico extremo y control innegociable incesante estricto para colesterol, de los lípidos o para el hiperglucémico que acompaña al cuadro base periférico general asintomático del paciente al inicio.", "Intervenciones percutáneas invasivas de revascularización mínimamente complejas modernas u opción rápida quirúrgica: Mediante el Angioplastia, se introduce un catéter guía especial con globo o con tecnología de un balón y luego se despliega y se aplica un Stent (malla para aplastar al interior las paredes de la arteria engrasada con lesiones ateroescleróticas muy estenosadas y abrir y mantener permeable un vaso periférico en zonas afectadas con lesiones para restaurar drásticamente los flujos de sangre isquémico total e impedir una isquemia crítica aguda general por cierre percutáneo invasivo moderno).", "Cirugía convencional y revascularización extrema arterial abierta (Derivación / Bypass periférico total profundo complejo y a gran escala abierta ortopédico-vascular en zonas muy destruidas): Tratamiento reservado para largas arterias en el trayecto calcificadas y crónicas, obstruidas fuertemente y no reparables con catéter stent, en el que el gran equipo y el especialista cirujano conectan vasos sanguíneos extraídos superficialmente (injerto de vena autógena) desde venas del propio u artificial para desviar de largo y saltar o bypassear con sangre limpia en un desvío nuevo al gran conducto bloqueado crónico y reestablecer flujo vivo al pie antes del último grado a considerar."] } ], note: "Las amputaciones mayores se dejan en este siglo solo para el último caso desesperado inevitable necrótico si falla irreversiblemente toda la terapia circulatoria médica u otras técnicas avanzadas en pacientes periféricos avanzados de alta comorbilidad por obstrucciones crónicas totales diseminadas en el tobillo en la extremidad diabética." }, whenToSeekHelp: { title: "¿Cuándo se ha de llamar sin dilación y cuándo reportarlo Inmediatamente Al Especialista a tiempo por las Isquemias en el Entorno Domiciliario de manera vital en consulta de Angiología?", intro: "Considere acudir con carácter urgente impostergable, reportándolo inmediatamente y pida asesoría y diríjase o llame directamente a un centro cardiovascular mayor especializado integral o de salud hospitalaria perentorio u a las emergencias con el Angiólogo para evitar complicaciones a corto plazo irreversible, reportando si experimenta y siente el afectado repentinamente, en o tras alguna afección diagnosticada periférica:", items: ["El desarrollo o aparición brusca repentina o extremadamente severa del dolor profundo urente, ardiente que se describe y ubica intolerable persistente del pie y la pantorrilla, al intentar acostarse por las noches (isquemia profunda clínica del dolor isquémico continuo que alivia temporal al dejar colgando el pie un poco de la cama de la sábana de alivio parcial)", "Heridas crónicas en piernas, úlceras gangrenosas o erosiones cutáneas infectadas superficialmente del miembro diabético, raspaduras o simples roces dolorosos que llevan más o superan con evidencia las varias semanas enteras activas o de duración purulenta roja supurante abierta y no mejoran o cicatrizan o cierran con todos los apósitos indicados al primer tiempo en la zona del tejido en pies, empeine o rodillas del nivel de afección por necrosis base con tejido putrefacto aparente u ennegrecido periféricamente de la isquemia crítica progresiva", "Color pálido amoratado general progresivo intenso general, en tono cadavérico, cambios muy drásticos en las puntas de uña o dedos y pies cianóticos sin dolor o con ausencia y extremidades crónicamente rígidas paralizadas o gélidas (sin temperatura alguna con o sin el roce o pulso general)."] } },
'Incontinencia fecal' : { intro: "La incontinencia fecal es la incapacidad incontrolada de retener gases o heces, resultando en pérdidas accidentales o episodios incontrolados desde el recto. Aunque es un tema que genera una inmensa vergüenza y aislamiento social paralizante, es mucho más común de lo que se admite y suele ser completamente tratable médicamente.", whatIs: { title: "¿Qué es la Incontinencia Fecal?", text: "Es la pérdida involuntaria de control sobre las deposiciones y los esfínteres, provocando el escape inesperado de heces (sólidas o líquidas) o gases intestinales en momentos y lugares inapropiados. Se origina por un fallo estructural o funcional en el complejo mecanismo del recto, la pelvis y los nervios." }, symptoms: { title: "Tipos de Pérdida y Sintomatología", intro: "Los pacientes experimentan la incontinencia en diferentes niveles de gravedad y control consciente:", groups: [ { name: "Tipos de eventos involuntarios", items: ["Incontinencia de urgencia: Siente una necesidad extrema, abrumadora e inminente de defecar, pero es físicamente incapaz de llegar al inodoro a tiempo o apretar el esfínter antes de que ocurra la pérdida masiva", "Incontinencia pasiva: No hay absolutamente ninguna advertencia ni sensación o ganas previas, y el paciente simplemente encuentra heces o ensuciamiento constante ('manchado') en la ropa interior o al levantarse"] }, { name: "Síntomas asociados crónicos", items: ["Irritación severa, sarpullido ardoroso o picazón insoportable (prurito anal) alrededor del ano debido a la constante humedad y el contacto con material fecal agresivo para la piel", "Diarrea recurrente (frecuentemente la incontinencia líquida es el síntoma secundario a la diarrea) o estreñimiento paralizante simultáneo, flatulencia excesiva y distensión dolorosa en el abdomen"] } ], warning: "La incontinencia súbita y severa que surge repentinamente con problemas dolorosos profundos u hormigueo inusual persistente al ir en la parte de silla de montar u en piernas inferiores podría revelar un síntoma neuro-crítico grave medular de urgencia aguda inmediata (Síndrome de Cola de Caballo)." }, types: { title: "Mecanismo del Fallo Estructural", intro: "La incontinencia surge de la alteración de uno o más componentes clave de la anatomía pélvica inferior:", items: ["Daño del esfínter anal (Músculo): Desgarros en los músculos anales en anillos que bloquean la salida fecal. Es altamente prevalente secundario a traumas severos perineales obstétricos muy profundos o episiotomías agresivas prolongadas del trabajo del parto con desgarro agudo de tercer o cuarto grado en mujeres tras partos en la vida adulta en el futuro.", "Daño en los nervios pudendos: Ruptura neurológica periférica medular anal donde la falta del nervio local le quita al músculo el tono (no se contraen) y el recto ya no siente ('ciego al tacto') las heces presentes debido a tensión crónica en las mujeres en el estreñimiento o lesiones a nivel neurológico como en pacientes con la esclerosis múltiple, la demencia o las secuelas espinales neuropáticas.", "Pérdida de la adaptabilidad o de la pared rectal por afecciones: Un recto crónicamente rígido de cicatrices profundas quirúrgicas locales previas de quimioterapias y por radiación o de enfermedades crónicas de inflamación profunda (EII, Chron o ulcerosa) incapaz de distenderse o de estirarse o retener contenido volumétrico para evacuar hasta poder ir a un cuarto de control o hasta el WC.", "Impactación de material endurecido (paradoja diarreica común general profunda muy grave en los ancianos o el estreñimiento crónico): La retención extrema prolongada masiva y no tratada del material seco anal y heces bloqueadas fuertemente profundas debilita, distiende un esfínter masivo, permitiendo y causando secundariamente en la misma ocasión la filtración de material acuoso fecal líquido escapándose continuamente muy por encima de dicho tapón crónico sólido bloqueando un paso o escape líquido involuntario."], note: "Es vital un diagnóstico porque un gran porcentaje general y enorme es reversible identificando el origen muscular vs el neurológico en la zona basal o a nivel rectal." }, causes: { title: "Factores de Riesgo Primordiales y Desencadenantes Principales Patológicos de Etiología de la Incontinencia Total Fecal", intro: "Los motivos del déficit muscular están basados muchas veces en una conjunción del trauma mecánico, de problemas quirúrgicos subyacentes severos y de patologías digestivas concurrentes mayores y de vida en general:", items: ["Lesión muscular ginecológica aguda y prolongada directa al suelo perianal postparto (a menudo con un efecto de latencia que se presenta silencioso y el problema anal surge por primera vez recién al iniciar fuertemente la edad de la menopausia en pacientes obstétricas antiguas con roturas pélvicas perineales no advertidas totalmente).", "Complicaciones iatrogénicas o consecuencias en la técnica y daño o error u secuela de múltiples cirugías previas ano-rectales en un intento por solucionar grandes abscesos crónicos profundos en el lugar, cirugías complejas fistulosas agresivas o tratar fisuras crónicas extensas mediante técnicas y hemorroides del corte muscular del tracto digestivo perianal excesivo donde los nervios anales de contención del músculo perianal interno fallaron para restablecer los bordes anales del cierre voluntario y esfínter interno por lo que quedó con secuela anal inelástica residual postquirúrgica crónica total o un trauma nervioso pélvico persistente.", "Afecciones severas neuro-cognitivas y degenerativas de nivel de deterioro sistémico neurológico diabético (la progresión o de patologías con ACV muy grandes en pacientes), así como lesiones traumáticas de la médula.", "Presencia clínica agresiva y continua grave por el padecimiento subyacente intestinal (ejemplo crónico recurrente y masivo del SII y de la Diarrea o el estreñimiento crónico agudo severo persistentes con distensión permanente del tubo rectal o el mal uso constante muy prolongado repetido de enemas pesados laxantes y los catárticos que insensibilizan permanentemente de control el intestino largo en la última porción rectal pélvica local profunda en el individuo)."] }, diagnosis: { title: "¿En Qué Se Basa La Exhaustiva Revisión Formal e Instancia Diagnóstica y Exploratoria Por Falla De Pérdidas?", intro: "Dado el estigma del diagnóstico general en adultos mayores, los especialistas en proctología (coloproctólogos) o los urólogos y ginecólogos y de suelo pélvico aplicarán test con absoluto resguardo clínico integral:", items: ["Revisión del historial general integral minucioso clínico pélvico y un examen dactilar cuidadoso del tacto perianal (buscando verificar con el dedo lubricado cómo de débil es la contracción interna al pedírsele empujar o contraer apretando si falta en reposo el anillo base anal).", "Manometría anorrectal minuciosa e indolora especializada: Herramienta del dispositivo sensor de presión crucial inflable en un globo milimétrico en un tubo con múltiples canales dentro de la región para medir de manera asombrosa, muy sensible precisa, todos los reflejos del tono en un músculo al toser o qué tal o cuanta rigidez muscular de fuerza, del tiempo de expulsión natural posee cada anillo basal concéntrico con cada contracción para identificar deficiencias nerviosas y el control voluntario anal y retención frente al empuje general coordinado expulsivo.", "Ecografía transanal (Endoanal 3D o Resonancia Magnética anal pélvica de alta precisión profunda general) con una minúscula sonda ultrasonográfica fina indolora, utilizada esencialmente para observar al músculo bajo capa en detalle interno profundo anatómico buscando si existe e identificar desgarros, adelgazamientos, la atrofia del nivel celular u de lesiones antiguas previas en mujeres tras un parto o si hay debilidad o daños esfinterianos invisibles o traumas antiguos directos musculares anales al esfínter local profundo crónico a visualizar.", "Defecografía, sigmoidoscopia y colonoscopia general con cámaras flexibles en tracto grueso u otro estudio complementario integral de tránsito rápido (Para detectar una inflamación aguda tumoral o un bloqueo por masas prolapsadas obstructivas rectales internas invisibles al dolor o el nivel agudo u orígenes sangrantes base severos colónicos crónicos ocultos generales e incontrolables crónicos agudos sistémicos perjudiciales crónicos para todos al largo trayecto)."], note: "Llevar la iniciativa general y escribir e ingresar todos los síntomas precisos anotados a conciencia minuciosa en los llamados o conocidos 'Diarios o de registro general detallados del diario del síntoma defecatorio' con la frecuencia aguda precisa de manchado y urgencia anal líquida le provee información base inicial contundente general a cualquier facultativo del equipo al diagnóstico clínico rápido y eficaz a todos y el abordaje e identificar o medir severidad sin obviar suvergüenza clínica del problema persistente." }, treatment: { title: "Enfoque Específico Tratamiento Funcional Conservador Múltiple Integrado Clínico del Manejo y Rescate Del Piso General Restaurativo e Invasivo en Urgencia Quirúrgica Severa Progresiva", intro: "A menudo con terapias conductuales médicas del tipo base generales que se escalan hasta las quirúrgicas complejas las posibilidades del mejoramiento clínico hoy logran reducir sustancialmente al límite y resolver a veces un cuadro perianal agudo y masivo o curar con el abordaje de mejora total base perenne si se sigue al tiempo la corrección conservadora clínica integral de rescate inicial a fondo por el terapeuta:", subsections: [ { title: "Terapias Intervencionistas Fisiológicas Médicas y del Hábitat Terapéutico Funcional Básico y de Inserción Quirúrgica Especializada en Reconstrucción Profunda Generalizada de Restauración Final en el Quirófano Pélvico Avanzado", items: ["Modificación exhaustiva a toda nutrición del bolo general o con un uso dirigido antiespasmódico con los agentes formadores de una hez o de las masas compactadas dietéticas de fibras y antidiarreicos fuertes recetados (loperamida base, u inyecciones para el síntoma de retención crónico con medicamentos laxantes osmóticos) dependiendo fuertemente su condición primaria, su ingesta base y el causante (hacer heces o más gruesas voluminosas firmes y blandas y más formadas o vaciar correctamente de forma temprana al recto obstruido y curar todos o los vaciados constantes por enema).", "Terapia fundamental general reeducativa muscular especializada clave del fisioterapeuta: Entrenamiento o fisioterapia anal y biorretroalimentación (Biofeedback pélvico de piso) junto a fisioterapeuta de alto rendimiento; un asombroso sistema visual usando la pantalla u otras señales acústicas muy sensible al tiempo que le enseñan con fuerza al paciente a notar con ejercicios (Kegel avanzados) nuevamente sus nervios o fortalecer músculos atrofiados y reconectarlos del control basal anal para ganar conciencia del umbral y recuperar fuerza de contención retentiva sin dolor y sin cirugía la fuerza original profunda anal.", "Reparación Quirúrgica Especializada Básica, reconstrucciones de esfínteres desgarrados u Esfinteroplastia anal en las lesiones postparto: Las cirugías consisten en que el gran cirujano vuelve e intenta conectar con sutura perianal los bordes libres musculares separados en desgarros del extremo o anillo inferior perineales viejos unidos por cicatrices y con esto los vuelve una vez más superpuestos, dándoles así tensión anatómica con control.", "Tratamientos o los injertos innovadores u Opciones con la intervención técnica en neuroestimulación invasiva (Implante temporal u definitivo avanzado sacral medular, o PTNS de inyección): Aplicaciones inyectables en la zona para ganar volúmenes u uso de un estimulador general sacro muy eficaz y sutil implantado en las vértebras por marcapasos o de un pequeño cable de corriente eléctrico muy bajo imperceptible directo en todos aquellos que regulan desde el plexo, controlan la acción refleja base a la médula en aquellos que carezcan total de reflejo neural (inyección eléctrica moduladora para regular la contracción fallida neuromuscular nerviosa severa) si ningún fármaco da los resultados previos e interfiere a largo con su trabajo u vida.", "El paso definitivo quirúrgico para casos o traumas neurológicos absolutos muy desastrosos o destructivos donde las fallas no den tregua: Desvío base profundo permanente (colostomía) exterior general con extirpación anal si es necesario y en saco abdominal y evitar problemas agudos e infecciones y así asegurar higiene global, pero la cirugía moderna intenta y pospone al máximo este desvío definitivo estomatológico si otra tecnología menos invasiva pudiese sanar al canal anal natural por defecto o en primera orden sin llegar a esto último."] } ], note: "Cualquier persona a cualquier etapa debería perder totalmente el pudor a usar sin culpa apósitos base, ropa o productos o apósitos específicos íntimos mientras recobra y se interviene al músculo bajo las terapias hasta curarse integral y no deba frenar en extremo sus libertades." }, whenToSeekHelp: { title: "¿En Qué Ocasiones Consultar Al Experto Coloproctólogo De Modo Clínico Inicial y Urgente o A Consulta Inicial Urgente y Continua de Apoyo En Emergencia Inmediata del Problema Perianal Evidente General?", intro: "No es en absoluto ni nunca parte inherente a los padecimientos de vejez irremediable normal a soportarse en silencio, diríjase pronto pidiendo y programando cita u emergencia al equipo ginecológico perianal sin retraso y confíe su padecimiento general si en el cuadro nota, evalúa y sufre:", items: ["El constante o imprevisto escape manchado anal u accidental involuntario súbito de material de heces, y las pérdidas crónicas repentinas fecales y o líquidos tras cualquier actividad cotidiana sencilla de un par de veces frecuentes de días o si sucede a semanas e interfiere con un fuerte temor o su estado diario limitando salir del inodoro del hogar a lugares para evitar todos y posibles episodios constantes.", "Hay indicios obvios agudos severos inflamatorios graves muy severos que persistan alrededor crónicos locales o sangrados rectales profundos constantes por ano acompañando a toda o a otra de esta filtración y además existiese dolor muy opresivo insoportable o masa dolorosa pélvica base.", "Pierde repentina totalmente el control por debilidad espinal luego y después un doloroso episodio o traumatismo lumbar o cervical acompañado crónico agudo por debilidades motoras de parálisis brusca súbita a causa en la zona perineal e ingle combinada con parálisis de pierna u hormigueo inusual de vejiga inactiva o descontrol en toda una retención general brusca dolorosa intensa súbita y continua u orina por pérdida nerviosa medular profunda que requiere emergencia hospitalaria (alivio vital quirúrgico súbito base e isquémico neurológico central medular u agudo en su progresión aguda paralizante a horas de desarrollarse por caudas equinas)."] } },
'Parálisis del nervio facial' : { intro: "La parálisis del nervio facial (frecuentemente conocida como parálisis de Bell) es una debilidad repentina en los músculos de una mitad del rostro. Aunque su aparición súbita suele alarmar por su similitud con un derrame cerebral, generalmente es una inflamación nerviosa temporal y reversible.", whatIs: { title: "¿Qué es la Parálisis del nervio facial?", text: "Es la pérdida de control voluntario de los músculos faciales en un lado de la cara, causada por la inflamación, compresión o daño del séptimo par craneal (nervio facial), el cual controla las expresiones, el parpadeo y parte del sentido del gusto." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas aparecen rápidamente, a menudo de la noche a la mañana:", groups: [ { name: "Alteraciones motoras", items: ["Caída evidente de la mitad del rostro y dificultad para hacer expresiones (sonreír, fruncir el ceño)", "Incapacidad para cerrar completamente el ojo del lado afectado", "Babeo involuntario por la comisura de los labios"] }, { name: "Alteraciones sensoriales", items: ["Dolor alrededor de la mandíbula o detrás de la oreja del lado afectado", "Aumento de la sensibilidad al sonido en un oído (hiperacusia)", "Pérdida del sentido del gusto en la parte frontal de la lengua", "Sequedad ocular severa por la falta de parpadeo"] } ], warning: "Si la parálisis facial se acompaña de debilidad en un brazo, dificultad para hablar o confusión, es una emergencia médica absoluta (posible accidente cerebrovascular)." }, types: { title: "Tipos y Causas", intro: "Se clasifica según su origen clínico:", items: ["Parálisis de Bell (Idiopática): La más común, a menudo vinculada a una infección viral transitoria que inflama el nervio.", "Síndrome de Ramsay Hunt: Causada por el virus del herpes zóster; incluye parálisis, dolor extremo y ampollas en el oído.", "Parálisis traumática o tumoral: Daño directo al nervio por una fractura de cráneo o compresión por un tumor facial/cerebral."], note: "En la Parálisis de Bell, a diferencia de un derrame cerebral, la frente también se paraliza por completo." }, causes: { title: "Causas Frecuentes", intro: "La inflamación que comprime el nervio en su estrecho canal óseo suele deberse a:", items: ["Infecciones virales reactivadas (Herpes simple, virus de la varicela-zóster, Epstein-Barr)", "Enfermedad de Lyme (transmitida por garrapatas)", "Infecciones del oído medio no tratadas", "Diabetes e hipertensión (aumentan el riesgo de inflamación nerviosa)", "Cambios bruscos de temperatura o estrés extremo (factores desencadenantes observacionales)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico y de exclusión:", items: ["Examen neurológico clínico para comprobar que la debilidad se limita solo al nervio facial y evaluar el cierre del ojo", "Resonancia magnética (RM) o Tomografía Computarizada (TC) para descartar tumores, derrames cerebrales o fracturas si el inicio es atípico", "Electromiografía (EMG) tras unas semanas para evaluar la gravedad del daño nervioso y predecir el tiempo de recuperación", "Análisis de sangre para descartar infecciones como la enfermedad de Lyme o diabetes no diagnosticada"], note: "El médico le pedirá que levante las cejas; si no puede hacerlo en el lado afectado, es un signo clásico de lesión periférica (Bell)." }, treatment: { title: "Tratamiento y Protección", intro: "El tratamiento temprano es vital para reducir la inflamación y prevenir daño ocular:", subsections: [ { title: "Manejo médico", items: ["Corticosteroides orales (prednisona): Muy efectivos si se inician dentro de las primeras 72 horas para desinflamar el nervio.", "Medicamentos antivirales (valaciclovir): A menudo recetados junto con esteroides si se sospecha una causa viral severa.", "Protección ocular estricta: Uso de lágrimas artificiales durante el día, geles lubricantes por la noche y parche ocular para evitar úlceras corneales irreversibles.", "Fisioterapia facial: Masajes y ejercicios específicos para mantener el tono muscular mientras el nervio se regenera."] } ], note: "La gran mayoría de los pacientes (alrededor del 80%) se recuperan por completo en un plazo de semanas a varios meses." }, whenToSeekHelp: { title: "¿Cuándo Ir a Urgencias?", intro: "Debe buscar evaluación médica inmediata si:", items: ["Experimenta parálisis o debilidad facial repentina (para descartar un derrame cerebral)", "El ojo afectado se vuelve intensamente rojo, doloroso o sufre cambios en la visión", "Aparecen ampollas dolorosas dentro o alrededor del oído", "La parálisis se extiende gradualmente durante semanas (sugiere un tumor en lugar de una parálisis aguda)"] } },
'Celiaquía' : { intro: "La celiaquía (o enfermedad celíaca) es una enfermedad autoinmune crónica del sistema digestivo. En los pacientes celíacos, la ingesta de gluten desencadena una respuesta inmunológica destructiva que daña el intestino delgado, impidiendo la absorción de nutrientes vitales y causando desde problemas digestivos hasta desnutrición severa.", whatIs: { title: "¿Qué es la Enfermedad Celíaca?", text: "Es un trastorno autoinmunitario hereditario. Cuando una persona celíaca consume gluten (una proteína presente en el trigo, la cebada y el centeno), su sistema inmunológico ataca por error las vellosidades del intestino delgado. Sin estas vellosidades, el cuerpo no puede absorber vitaminas, minerales ni calorías adecuadamente." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los síntomas varían enormemente y pueden afectar todo el cuerpo, no solo el estómago:", groups: [ { name: "Síntomas digestivos clásicos", items: ["Diarrea crónica, maloliente o heces grasosas y pálidas (esteatorrea)", "Hinchazón severa, exceso de gases y distensión abdominal dolorosa", "Pérdida de peso inexplicable a pesar de un apetito normal", "Estreñimiento crónico (especialmente común en niños)"] }, { name: "Síntomas sistémicos (por malabsorción)", items: ["Anemia por deficiencia de hierro que no responde a suplementos", "Fatiga crónica profunda y debilidad", "Osteoporosis temprana o pérdida de densidad ósea", "Erupción cutánea con picazón extrema y ampollas (dermatitis herpetiforme)", "Hormigueo y entumecimiento en pies y manos (neuropatía)"] } ], warning: "En los niños, la celiaquía no diagnosticada puede causar un retraso irreversible en el crecimiento, baja estatura y pubertad tardía." }, types: { title: "Formas de Presentación", intro: "La enfermedad puede manifestarse de diferentes maneras clínicas:", items: ["Celiaquía clásica: Presenta síntomas digestivos graves y signos claros de malabsorción.", "Celiaquía no clásica: Sin síntomas digestivos evidentes; se manifiesta con anemia, fatiga, migrañas, infertilidad o problemas neurológicos.", "Celiaquía asintomática (silenciosa): El paciente no nota síntomas, pero el intestino está siendo destruido. Suele descubrirse al evaluar a familiares de un paciente celíaco.", "Dermatitis herpetiforme: La manifestación en la piel de la intolerancia al gluten, caracterizada por ampollas muy pruriginosas en codos, rodillas y glúteos."], note: "No debe confundirse con la sensibilidad al gluten no celíaca o la alergia al trigo, que no causan daño autoinmune al intestino." }, causes: { title: "Causas y Desencadenantes", intro: "Es una condición genética que requiere un desencadenante ambiental:", items: ["Predisposición genética: Presencia de los genes HLA-DQ2 y HLA-DQ8 (si no se tienen estos genes, es casi imposible desarrollar celiaquía).", "Exposición al gluten: Ingerir alimentos con trigo, cebada, centeno, o avena contaminada.", "Activación inmunológica: A veces, la enfermedad 'despierta' o se activa por primera vez después de un evento estresante, como una cirugía, un embarazo, un parto, una infección viral severa o estrés emocional profundo.", "Asociación autoinmune: Es mucho más común en personas con diabetes tipo 1, enfermedad de la tiroides autoinmune o síndrome de Down."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es vital NO dejar de comer gluten antes de las pruebas médicas, o los resultados serán falsos:", items: ["Análisis de sangre (Serología): Búsqueda de niveles elevados de autoanticuerpos específicos, principalmente los anticuerpos antitransglutaminasa tisular (tTG-IgA).", "Pruebas genéticas: Para descartar la enfermedad si la serología es dudosa (buscando los genes HLA-DQ2/DQ8).", "Endoscopia superior con biopsia del intestino delgado: El estándar de oro definitivo. El gastroenterólogo toma pequeñas muestras del intestino para ver bajo el microscopio si las vellosidades están aplanadas o destruidas.", "Biopsia de piel: Si se sospecha dermatitis herpetiforme."], note: "Eliminar el gluten antes de la endoscopia permite que el intestino sane, ocultando la evidencia de la enfermedad." }, treatment: { title: "Tratamiento y Estilo de Vida", intro: "Actualmente, no existe una cura farmacológica. El único tratamiento eficaz es dietético:", subsections: [ { title: "Dieta y recuperación", items: ["Dieta 100% libre de gluten de por vida: Eliminación estricta y total de cualquier alimento, salsa, o medicamento que contenga trazas de trigo, cebada, centeno, malta o levadura de cerveza.", "Prevención de la contaminación cruzada: Usar utensilios, tostadoras y superficies de corte separadas en la cocina para evitar consumir migas de gluten invisibles.", "Suplementos nutricionales iniciales: Prescritos por un médico para reponer rápidamente las deficiencias graves de hierro, calcio, zinc, vitamina B12 y vitamina D.", "Tratamiento de la dermatitis herpetiforme: Medicamentos orales como la dapsona para calmar la picazón de la piel, junto con la dieta sin gluten.", "Seguimiento médico anual: Para monitorear los niveles de anticuerpos en sangre y asegurar la curación intestinal y ósea."] } ], note: "Con una dieta estricta, el intestino delgado suele sanar por completo en un plazo de 6 meses a 2 años." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Gastroenterólogo?", intro: "Solicite una evaluación médica si:", items: ["Padece diarrea persistente, dolor abdominal crónico o heces pálidas y malolientes durante más de dos semanas", "Ha sido diagnosticado con anemia o fatiga crónica que no mejora con suplementos normales", "Su hijo está en un percentil de crecimiento muy bajo, tiene el abdomen hinchado y diarrea crónica", "Tiene un familiar de primer grado (padre, hijo, hermano) con enfermedad celíaca confirmada, incluso si usted no tiene síntomas"] } },
'Fractura de la pelvis' : { intro: "Una fractura de la pelvis es una rotura en uno o más de los huesos que forman el anillo pélvico protector en la base de la columna. Puede variar desde una fisura leve en un atleta hasta una lesión catastrófica y potencialmente mortal por un accidente de tránsito grave que causa hemorragias internas masivas.", whatIs: { title: "¿Qué es una Fractura de Pelvis?", text: "Es la interrupción de la estructura ósea del anillo pélvico (formado por el íleon, el isquion, el pubis, el sacro y el cóccix). Dado que la pelvis protege vasos sanguíneos mayores y órganos vitales (vejiga, intestinos, genitales), su fractura puede generar complicaciones sistémicas muy graves." }, symptoms: { title: "Síntomas y Evaluación Inicial", intro: "Los síntomas dependen de la fuerza del impacto y el desplazamiento del hueso:", groups: [ { name: "Síntomas traumatológicos", items: ["Dolor intenso y paralizante en la ingle, la cadera, la parte baja de la espalda o los glúteos", "El dolor empeora drásticamente al intentar mover las piernas o al intentar caminar", "Incapacidad total para soportar peso o pararse sobre las piernas", "Hinchazón severa y aparición rápida de grandes hematomas (moretones) sobre los huesos de la cadera o el perineo"] }, { name: "Signos de complicaciones (Emergencias)", items: ["Sangrado por la vagina, el recto o la uretra (indica que el hueso roto perforó un órgano interno)", "Adormecimiento u hormigueo en la ingle o las piernas (daño nervioso)", "Mareos extremos, palidez, piel fría o pérdida de conocimiento (signos de shock por hemorragia interna masiva)"] } ], warning: "Una fractura inestable de pelvis en un accidente automovilístico es una emergencia de reanimación crítica; el paciente puede desangrarse internamente en minutos." }, types: { title: "Clasificación de las Fracturas Pélvicas", intro: "Los ortopedistas las clasifican según la estabilidad mecánica del anillo pélvico:", items: ["Fracturas Estables: Solo se rompe una parte del anillo pélvico y los huesos permanecen en su lugar. Comunes en caídas de ancianos (fracturas por avulsión o impacto menor). Sanan bien con reposo.", "Fracturas Inestables: Rupturas en dos o más lugares del anillo pélvico, desplazando los huesos. Suelen ser el resultado de traumas de altísima energía (accidentes de auto, caídas desde gran altura). Requieren cirugía urgente.", "Fracturas por estrés: Fisuras finas o 'grietas' en el hueso, frecuentes en corredores de larga distancia debido al impacto repetitivo sobre el hueso pélvico.", "Fracturas por fragilidad: Ocurren en personas con osteoporosis severa tras una simple caída estando de pie o incluso al girar en la cama."], note: "El anillo pélvico es como un pretzel; es muy difícil romperlo en un solo lugar sin que ceda o se rompa en otro punto opuesto." }, causes: { title: "Mecanismos de Lesión", intro: "La causa dicta generalmente la gravedad de la fractura:", items: ["Traumatismos de alta energía (Causa principal de fracturas inestables): Choques frontales o laterales en vehículos, atropellos a peatones, accidentes de motocicleta o caídas desde varios pisos de altura.", "Traumatismos de baja energía (Causa de fracturas estables): Tropezones y caídas a nivel del suelo, especialmente en adultos mayores con huesos debilitados por osteoporosis.", "Fuerzas de tracción muscular (Fracturas por avulsión): Muy comunes en adolescentes y atletas donde un músculo se contrae tan violentamente que arranca un pedazo de hueso pélvico donde está insertado.", "Daño por radiación pélvica previa o cáncer que se ha propagado al hueso."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La evaluación en la sala de urgencias es rápida e incluye:", items: ["Estabilización inicial: En traumas graves, los médicos primero aseguran las vías respiratorias y la presión arterial antes de examinar los huesos.", "Examen físico: El médico evaluará cuidadosamente la sensibilidad, la estabilidad aplicando presión suave en las caderas, y revisará los pulsos y reflejos en las piernas.", "Radiografías (Rayos X): La primera prueba de imagen para ver el hueso pélvico y la articulación de la cadera desde varios ángulos.", "Tomografía Computarizada (TC): Fundamental en casi todos los traumas pélvicos. Ofrece imágenes 3D de alta resolución de los huesos y muestra si hay hemorragias internas ocultas o daños a la vejiga/vasos sanguíneos.", "Resonancia Magnética (RM): Utilizada principalmente para detectar fracturas por estrés muy finas en atletas que no aparecen en las radiografías normales."], note: "Se puede requerir un examen urológico o ginecológico con contraste si se sospecha daño en las vías urinarias." }, treatment: { title: "Opciones Ortopédicas y Quirúrgicas", intro: "El tratamiento difiere radicalmente según la estabilidad de la fractura:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Para fracturas estables y por avulsión: Tratamiento conservador. Requiere reposo relativo, uso de muletas o andador para no apoyar peso durante varias semanas (descarga de peso), analgésicos fuertes y medicamentos anticoagulantes para prevenir trombosis en las piernas por inmovilidad.", "Para fracturas inestables (Emergencia): Colocación de un fijador o aglutinante pélvico externo temporal en urgencias para 'apretar' y cerrar la pelvis, deteniendo hemorragias internas potencialmente mortales.", "Fijación externa: Cirugía donde se insertan clavos de metal en los huesos y se conectan a un marco fuera del cuerpo para mantenerlos estables.", "Fijación interna (Reducción abierta): Cirugía mayor donde se realinean los fragmentos de hueso y se sujetan internamente con placas de acero resistentes y tornillos de por vida.", "Embolización angiográfica: Un radiólogo intervencionista inserta un catéter para encontrar el vaso sanguíneo pélvico que sangra y lo bloquea internamente para salvar la vida del paciente.", "Fisioterapia intensiva: Imprescindible en todos los casos tras el alta para reaprender a caminar y fortalecer la musculatura."] } ], note: "La recuperación de una cirugía de pelvis inestable puede llevar de 6 meses a un año, y el dolor crónico residual es común." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias?", intro: "Una fractura pélvica requiere evaluación médica hospitalaria inmediata si:", items: ["Ha sufrido un accidente de tráfico, impacto fuerte o una caída de gran altura", "Un adulto mayor se cae y se queja de un dolor intenso en la cadera, ingle o glúteo y es incapaz de levantarse", "Aparece sangre en la orina o incapacidad para orinar tras un golpe fuerte en el área pélvica", "Siente que los huesos de la cadera 'crujen' o se mueven inusualmente al intentar moverse"] } },
'Ambliopía' : { intro: "La ambliopía, popularmente conocida como 'ojo vago', es un trastorno del desarrollo visual en la infancia. Ocurre cuando el cerebro y el ojo no trabajan juntos correctamente; el cerebro favorece a un ojo y suprime las imágenes del ojo más débil, lo que lleva a una pérdida de visión permanente si no se corrige antes de los 8 años.", whatIs: { title: "¿Qué es la Ambliopía?", text: "Es una disminución de la agudeza visual en un ojo que, por lo demás, es anatómicamente normal. Se desarrolla durante los primeros años de vida (período de plasticidad cerebral) porque el cerebro ignora las señales de ese ojo, impidiendo que los nervios visuales se desarrollen por completo." }, symptoms: { title: "Señales Físicas y de Comportamiento", intro: "La afección es difícil de detectar porque el niño no se queja (no sabe que su visión es anormal) y el ojo bueno compensa el déficit:", groups: [ { name: "Signos observables en el niño", items: ["Un ojo que se desvía constantemente hacia adentro, hacia afuera, arriba o abajo (estrabismo asociado)", "El niño entrecierra los ojos frecuentemente, cierra un ojo a plena luz o inclina la cabeza para ver mejor la televisión o la pizarra", "Falta de percepción de profundidad adecuada (tropieza con frecuencia, tiene problemas para atrapar una pelota o calcular distancias)", "Resultados consistentemente deficientes en los exámenes de detección de la vista de la escuela"] }, { name: "Pruebas caseras simples", items: ["El niño llora, se irrita mucho o intenta quitarse la mano de la cara si los padres le tapan en forma de juego su 'ojo bueno' (porque con el otro no ve bien)"] } ], warning: "La ambliopía rara vez se resuelve por sí sola. Si no se diagnostica y trata antes de que el desarrollo visual del cerebro se complete (alrededor de los 8 a 10 años), el niño tendrá una pérdida visual de por vida." }, types: { title: "Causas y Tipos Clínicos", intro: "Se clasifica según el problema subyacente que confunde al cerebro:", items: ["Ambliopía Estrábica (la más común): Causada por un desalineamiento de los ojos (estrabismo). Para evitar ver doble, el cerebro simplemente 'apaga' o ignora la imagen del ojo desviado.", "Ambliopía Refractiva (anisometrópica): Causada por una diferencia enorme en la graduación entre ambos ojos (ej. un ojo es muy miope y el otro ve perfecto). El cerebro ignora la imagen borrosa. Es la más difícil de detectar porque los ojos se ven rectos y normales.", "Ambliopía por Deprivación: La forma más grave y urgente. Una barrera física (como una catarata congénita infantil, un párpado muy caído o una cicatriz en la córnea) bloquea completamente la entrada de luz y formación de imagen en el ojo del bebé."], note: "La ambliopía generalmente afecta un solo ojo, pero en casos raros de problemas refractivos severos bilaterales, puede afectar ambos." }, causes: { title: "Factores de Riesgo", intro: "El desarrollo de esta falla neurológica visual está asociado a:", items: ["Antecedentes familiares genéticos de ambliopía, estrabismo o cataratas infantiles", "Nacimiento prematuro extremo o bajo peso al nacer", "Retrasos generales en el desarrollo neurológico o infantil", "Falta de exámenes oftalmológicos regulares durante los primeros 4 años de vida", "Condiciones físicas que impiden que el ojo capte imágenes claras durante los primeros meses de vida"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Solo puede ser diagnosticada con precisión por un oftalmólogo pediátrico u optometrista:", items: ["Examen oftalmológico pediátrico: En bebés, se evalúa cómo siguen un objeto con la mirada y su reacción al ocluirles un ojo.", "Uso de gotas de dilatación especiales para relajar los músculos de enfoque del niño y medir la necesidad exacta de gafas (refracción ciclopléjica) de manera objetiva, sin depender de sus respuestas.", "Uso de instrumentos iluminados (oftalmoscopio) para buscar cataratas u obstrucciones internas.", "Evaluación de la alineación de los ojos mediante pruebas de oclusión (tapar y destapar) para buscar estrabismo."], note: "Los pediatras recomiendan pruebas de agudeza visual formales e instrumentales desde los 3 años de edad como mínimo." }, treatment: { title: "Terapias de Reeducación Visual", intro: "El tratamiento obliga al cerebro a reconectar y usar el ojo ignorado:", subsections: [ { title: "Opciones de corrección y terapia", items: ["Corrección del defecto óptico: El primer y más importante paso es usar gafas de prescripción exacta para corregir miopía, hipermetropía o astigmatismo. Solo esto cura muchos casos refractivos.", "Terapia de Oclusión (Parche): El tratamiento de oro. Se coloca un parche adhesivo sobre el ojo Fuerte (el bueno) durante 2 a 6 horas al día. Esto obliga al cerebro a 'trabajar' y procesar las imágenes del ojo débil, creando nuevas conexiones neuronales.", "Gotas oftálmicas de penalización (Atropina): Se aplica una gota de atropina en el ojo fuerte una o dos veces por semana para nublar su visión de cerca, obligando al niño a usar el ojo débil (excelente alternativa si el niño se arranca el parche constantemente).", "Filtro de Bangerter: Un filtro semitransparente que se pega en el lente de la gafa del ojo fuerte para difuminar la visión y forzar el uso del ojo vago.", "Cirugía de los músculos oculares: Si la causa es un estrabismo severo, la cirugía alineará los ojos, pero aún se necesitará el uso de parches y gafas después para reeducar la visión cerebral.", "Cirugía inmediata de cataratas congénitas en bebés."] } ], note: "La constancia de los padres con el parche es el factor más determinante para el éxito; el tratamiento puede durar meses o años." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Oftalmólogo Pediátrico?", intro: "Programe un examen de la vista completo para su hijo si:", items: ["Nota que uno de los ojos de su bebé divaga, cruza o se desvía consistentemente después de los 3 meses de edad", "El niño se queja de no poder ver la pizarra en la escuela o inclina la cabeza de manera inusual al dibujar", "Hay un historial familiar directo de estrabismo, ojo vago o uso de anteojos gruesos desde la primera infancia", "Nota un reflejo blanco o turbio dentro de la pupila del niño (especialmente visible en fotografías con flash)"] } },
'Síndrome de dolor regional complejo' : { intro: "El Síndrome de Dolor Regional Complejo (SDRC) es una condición de dolor crónico poco común pero devastadora. Suele afectar un solo brazo o pierna tras una lesión, cirugía o infarto, desarrollándose cuando el sistema nervioso central y periférico reacciona exageradamente y entra en un ciclo de retroalimentación de dolor e inflamación perpetua.", whatIs: { title: "¿Qué es el SDRC?", text: "Es un trastorno neurológico y neuroinflamatorio crónico en el cual el cerebro percibe y envía señales de dolor abrasador continuo, muy desproporcionadas en relación a la gravedad de la lesión original. La extremidad afectada sufre cambios dramáticos en la temperatura, el color de la piel, la hinchazón y una sensibilidad paralizante al tacto." }, symptoms: { title: "Síntomas Clásicos y Progresivos", intro: "Los síntomas cambian con el tiempo y pueden propagarse desde el área original lesionada:", groups: [ { name: "Sensaciones de dolor extremo", items: ["Dolor urente constante, punzante o descrito como 'ardor por fuego' en el brazo, pierna, mano o pie afectado", "Alodinia: Hipersensibilidad extrema donde el más mínimo roce (como la ropa, el agua tibia, o una brisa de aire) causa un dolor agónico insoportable", "Hiperalgesia: Respuesta de dolor enormemente exagerada a un estímulo ligeramente doloroso"] }, { name: "Cambios autonómicos y tróficos (Tejidos)", items: ["Alteraciones notables de la temperatura: El área afectada fluctúa entre sentirse helada y sudorosa, o extremadamente caliente y roja, en comparación con la extremidad sana", "Cambios marcados en el color de la piel: Se vuelve manchada, pálida, roja brillante, o de color púrpura/azulado", "Hinchazón (edema) severa y rigidez articular en la extremidad afectada", "La piel se vuelve brillante, muy delgada y tensa", "Crecimiento rápido inusual, o posterior pérdida y estancamiento, del vello y las uñas en el área", "Espasmos musculares severos, temblores y debilidad motora (atrofia) a medida que la condición avanza"] } ], warning: "Si no se diagnostica y trata de manera agresiva en los primeros meses, la extremidad puede sufrir contracturas permanentes, deformidad y atrofia muscular irreversible." }, types: { title: "Tipos de SDRC", intro: "Los médicos dividen la condición en dos tipos basados en la evidencia de lesión nerviosa:", items: ["SDRC Tipo I (antes conocido como Distrofia Simpática Refleja): Ocurre en el 90% de los pacientes. Se desencadena tras una enfermedad o lesión de tejidos (como un esguince o fractura) donde NO hay daño directo comprobado a los nervios principales.", "SDRC Tipo II (antes conocido como Causalgia): Tiene exactamente los mismos síntomas y progresión, pero se presenta inmediatamente después de una lesión o corte claro, directo y verificable en un nervio principal periférico."], note: "El estrés emocional y la ansiedad intensa empeoran drásticamente todos los síntomas del SDRC." }, causes: { title: "Desencadenantes Comunes", intro: "Aunque la causa del 'cortocircuito' neurológico no se comprende del todo, a menudo es desencadenado por:", items: ["Trauma físico (la causa más frecuente): Fracturas óseas (especialmente fracturas de muñeca), esguinces severos, aplastamientos o contusiones en extremidades.", "Cirugías ortopédicas y procedimientos médicos invasivos en brazos o piernas", "Colocación prolongada o excesivamente apretada de un yeso inmovilizador", "Ataques cardíacos o accidentes cerebrovasculares (pueden desencadenar el SDRC en el hombro o brazo afectado, conocido como síndrome hombro-mano)", "Pequeños cortes, infecciones locales o lesiones por esfuerzo repetitivo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existe una sola prueba para confirmar el SDRC; es un diagnóstico clínico basado en los Criterios de Budapest:", items: ["Examen físico neurológico minucioso: El médico busca signos evidentes de asimetría térmica, cambios en el color de la piel, sudoración e hipersensibilidad táctil", "Radiografías (Rayos X): Pueden mostrar pérdida irregular de minerales en los huesos (osteoporosis moteada) en la extremidad afectada en etapas avanzadas", "Resonancia magnética (RM) para buscar daños estructurales subyacentes u otras causas del dolor", "Estudios de gammagrafía ósea trifásica: Frecuentemente muestran una absorción o flujo sanguíneo anormalmente alto o bajo en las articulaciones afectadas", "Pruebas de sudoración termorreguladora o termografía para medir variaciones asimétricas de temperatura corporal de un lado al otro"], note: "El diagnóstico diferencial es vital; deben descartarse artritis severa, síndrome compartimental, trombosis o infecciones antes de declarar que es SDRC." }, treatment: { title: "Manejo del Dolor y Rehabilitación", intro: "Requiere un enfoque multidisciplinario agresivo para reprogramar el sistema nervioso:", subsections: [ { title: "Terapias escalonadas", items: ["Fisioterapia y Terapia Ocupacional (El pilar absoluto): Ejercicios de movimiento suave y desensibilización constante (frotar diferentes texturas en la piel) para entrenar al cerebro a no percibir el tacto como dolor y prevenir atrofias.", "Medicamentos Neuromoduladores: Gabapentina o pregabalina para el dolor nervioso, antidepresivos tricíclicos (amitriptilina) para alterar la percepción del dolor cerebral.", "Corticosteroides orales (etapa temprana) o AINEs para reducir la inflamación severa inmediata.", "Inyecciones de bloqueos de los nervios simpáticos: Inyectar anestésico a lo largo de la columna vertebral para bloquear los nervios del sistema nervioso simpático que controlan el flujo sanguíneo de la extremidad.", "Estimulación de la médula espinal (TENS o implantes): Dispositivos que envían corrientes eléctricas diminutas a la médula para enmascarar e interrumpir las señales de dolor antes de que lleguen al cerebro.", "Terapia psicológica y de biofeedback para enseñar a controlar las respuestas autónomas del cuerpo ante el estrés del dolor continuo.", "En casos refractarios severos: Bombas intratecales de medicamentos (morfina directamente a la médula) o infusiones intravenosas experimentales de ketamina."] } ], note: "La recuperación de la función completa y remisión del dolor es muy posible si el tratamiento intensivo comienza en los primeros 3 meses posteriores a la lesión desencadenante." }, whenToSeekHelp: { title: "¿Cuándo Buscar al Especialista en Dolor?", intro: "Solicite derivación médica neurológica inmediata si experimenta:", items: ["Dolor severo, ardiente, incontrolable y continuo en un miembro que persiste mucho después de que la fractura, cirugía o esguince original debería haber sanado por completo", "La piel de esa extremidad se vuelve tan hipersensible que no tolera usar un calcetín o que le caiga agua de la ducha", "Nota cambios dramáticos en el color de la piel, la temperatura o hinchazón evidente en un solo brazo o pierna", "Observa que las articulaciones de la zona dolorida se están volviendo rígidamente bloqueadas"] } },
'Hemofilia' : { intro: "La hemofilia es un trastorno hemorrágico genético y hereditario grave. En esta afección, la sangre no coagula adecuadamente debido a la ausencia o deficiencia de proteínas esenciales (factores de coagulación), lo que provoca sangrados prolongados y peligrosos espontáneos, especialmente dentro de las articulaciones y los músculos profundos.", whatIs: { title: "¿Qué es la Hemofilia?", text: "Es un defecto genético recesivo en el cual el cuerpo no produce suficiente cantidad de ciertas proteínas en el plasma sanguíneo, conocidas como factores de coagulación. Como resultado, tras una lesión o cirugía (o incluso espontáneamente), el paciente sangra durante mucho más tiempo de lo normal, no de forma más rápida, sino más prolongada." }, symptoms: { title: "Síntomas y Señales de Sangrado", intro: "Los signos varían según el nivel de deficiencia del factor y suelen aparecer en la infancia temprana:", groups: [ { name: "Sangrados externos e inducidos", items: ["Sangrado excesivo, prolongado e imparable tras cortes menores, rasguños, extracciones dentales, vacunas o cirugías", "Sangrado nasal frecuente (epistaxis) que es extremadamente difícil de detener", "Aparición de moretones (equimosis) inusualmente grandes, profundos y frecuentes por golpes leves", "Sangrado incontrolable por el cordón umbilical o tras la circuncisión en el recién nacido"] }, { name: "Sangrados internos profundos (El mayor peligro)", items: ["Hemartrosis (sangrado dentro de las articulaciones): Provoca dolor agudo, hinchazón, calor y rigidez extrema. Afecta típicamente rodillas, codos y tobillos sin traumatismo previo aparente.", "Sangrado profundo en los músculos (hematomas musculares), causando dolor sordo, hinchazón tensa y compresión nerviosa.", "Sangrado en el cerebro (la complicación más temida), evidenciado por dolores de cabeza repentinos, vómitos repetidos, letargo, convulsiones o visión doble", "Sangre visible en la orina (hematuria) o heces negras alquitranadas"] } ], warning: "Cualquier golpe fuerte en la cabeza, cuello o abdomen en un paciente hemofílico, aunque parezca no tener síntomas inmediatos, es una emergencia médica que requiere infusión del factor de coagulación." }, types: { title: "Tipos Principales y Severidad", intro: "Se clasifica por el factor proteico exacto que falta en la sangre:", items: ["Hemofilia A (Clásica): El tipo más común (80% de los casos). Causada por la deficiencia o ausencia del Factor de Coagulación VIII.", "Hemofilia B (Enfermedad de Christmas): Causada por la deficiencia o ausencia del Factor de Coagulación IX.", "Nivel Severo (Menos del 1% de factor): Sufren sangrados articulares espontáneos frecuentes sin motivo aparente.", "Nivel Moderado (1% a 5%): Sangran tras lesiones menores, pero rara vez de forma espontánea.", "Nivel Leve (5% a 40%): A menudo no se diagnostican hasta que tienen una cirugía mayor, accidente grave o extracción dental donde sangran profusamente."], note: "La Hemofilia C (deficiencia del factor XI) es muy rara, presenta síntomas más leves y puede afectar a ambos sexos por igual." }, causes: { title: "Genética y Herencia", intro: "Es un trastorno hereditario ligado al cromosoma X:", items: ["Patrón ligado al cromosoma X: El gen defectuoso está en el cromosoma X. Debido a que los hombres solo tienen un cromosoma X (XY), si heredan el gen defectuoso de su madre, padecerán la enfermedad.", "Mujeres portadoras: Las mujeres tienen dos cromosomas X (XX). Si heredan un gen defectuoso, el otro gen sano compensa, por lo que son 'portadoras'. Generalmente no tienen la enfermedad grave, pero pueden transmitirla a sus hijos varones (y tener menstruaciones muy abundantes).", "Mutación espontánea: Cerca de 1/3 de los bebés con hemofilia no tienen antecedentes familiares previos; el gen muta de forma nueva en el desarrollo fetal.", "Hemofilia adquirida (extremadamente rara): El sistema inmunitario de una persona sana ataca de repente sus propios factores de coagulación debido al embarazo, cáncer o enfermedades autoinmunes."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se evalúa rápidamente si hay un historial familiar o sangrados prolongados en el bebé:", items: ["Análisis de sangre para evaluar la capacidad de coagulación: Pruebas de Tiempo de Tromboplastina Parcial activada (TTPa) y Tiempo de Protrombina (TP). En hemofílicos, el TTPa está característicamente prolongado.", "Ensayos de factores de coagulación: La prueba definitiva. Mide la cantidad exacta de factor VIII y factor IX en la sangre para determinar el tipo de hemofilia y su severidad (leve, moderada o grave).", "Pruebas genéticas moleculares: Para identificar la mutación exacta y permitir la detección en otros miembros de la familia femenina (portadoras).", "Diagnóstico prenatal: Muestreo de vellosidades coriónicas o amniocentesis para detectar hemofilia en el feto si hay antecedentes maternos conocidos."], note: "Las pruebas en bebés con factores de riesgo genéticos pueden hacerse extrayendo sangre del cordón umbilical inmediatamente después del nacimiento." }, treatment: { title: "Terapia de Reemplazo e Innovaciones", intro: "El tratamiento central es reponer el factor proteico faltante en la sangre del paciente:", subsections: [ { title: "Intervenciones preventivas y de urgencia", items: ["Terapia de reemplazo a demanda: Inyección intravenosa del factor de coagulación concentrado (VIII o IX) fabricado sintéticamente (recombinante) o derivado de plasma, administrada inmediatamente cuando ocurre una lesión o comienza un sangrado articular para detenerlo.", "Terapia profiláctica continua: Infusiones intravenosas rutinarias (2 o 3 veces por semana) del factor en casa para prevenir los sangrados articulares espontáneos antes de que ocurran, preservando las articulaciones a largo plazo (el estándar para niños con hemofilia severa).", "Nuevos anticuerpos biespecíficos (Hemlibra / Emicizumab): Inyecciones subcutáneas periódicas (bajo la piel) muy revolucionarias que imitan el trabajo del factor VIII para la Hemofilia A severa, previniendo sangrados de forma muy efectiva.", "Desmopresina (DDAVP): Una hormona sintética nasal o inyectable que estimula al cuerpo a liberar factor VIII almacenado, útil solo para la hemofilia A leve.", "Agentes antifibrinolíticos (ácido tranexámico): Medicamentos orales que evitan la descomposición de los coágulos, vitales durante procedimientos dentales o de mucosas.", "Fisioterapia y rehabilitación articular intensiva para reparar y mantener la fuerza muscular alrededor de las articulaciones dañadas por sangrados repetidos (artropatía hemofílica)."] } ], note: "Una complicación médica grave es el desarrollo de 'inhibidores': el cuerpo rechaza y destruye el medicamento del factor inyectado, requiriendo terapias de bypass muy costosas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Asistencia Hematológica Urgente?", intro: "Considere una alerta roja médica y acuda a urgencias si el paciente con hemofilia:", items: ["Sufre un traumatismo en la cabeza o una caída fuerte, incluso si no hay sangrado o chichón visible", "Comienza a tener una articulación (rodilla, tobillo, codo) que se siente caliente, hace burbujas, duele intensamente o le impide moverla o caminar", "Presenta dolor abdominal agudo persistente, dolores de cabeza que no ceden, rigidez en el cuello o somnolencia extrema", "Sufre un corte profundo en la lengua, la boca o el cuello que podría comprometer la vía respiratoria al hincharse de sangre", "El sangrado no cede con la infusión a demanda habitual en el hogar"] } },
'Síndrome del intestino corto' : { intro: "El Síndrome del intestino corto (SIC) es una grave condición de malabsorción física. Ocurre cuando se ha extirpado quirúrgicamente o ha nacido sin una gran porción del intestino delgado, lo que incapacita al cuerpo para absorber suficientes nutrientes, vitaminas y fluidos de los alimentos para sostener la vida, requiriendo soporte nutricional especializado.", whatIs: { title: "¿Qué es el Síndrome del Intestino Corto?", text: "Es un complejo trastorno de deficiencia nutricional grave. Ocurre cuando el individuo carece de una longitud suficiente de intestino delgado sano y funcional (generalmente queda menos de 200 centímetros). Al tener una zona de absorción tan reducida, los alimentos líquidos y nutrientes pasan rápidamente y se expulsan del cuerpo sin ser aprovechados." }, symptoms: { title: "Manifestaciones Diarias y Carenciales", intro: "Los síntomas son devastadores para el equilibrio de fluidos y la nutrición básica:", groups: [ { name: "Síntomas digestivos continuos", items: ["Diarrea crónica, masiva, acuosa y frecuente (el síntoma más abrumador, ya que el intestino no puede absorber los fluidos ingeridos)", "Heces pálidas, inusualmente malolientes y muy grasosas (esteatorrea) por la incapacidad de procesar las grasas", "Dolor abdominal severo, retortijones intensos, cólicos, exceso de gases y distensión (hinchazón)", "Ardor o irritación perianal severa debido al flujo constante y ácido de la diarrea"] }, { name: "Signos críticos de desnutrición clínica", items: ["Pérdida de peso drástica y severa en adultos, y retraso extremo del crecimiento o desgaste muscular en niños", "Deshidratación crónica (boca seca, sed extrema, disminución en la orina y orina muy oscura)", "Fatiga severa, debilidad letárgica y palidez por anemia (falta de hierro, folato y B12)", "Moretones fáciles (falta de vitamina K), dolor o debilidad ósea (falta de calcio y vitamina D)"] } ], warning: "La deshidratación repentina y los desequilibrios de electrolitos (pérdida de potasio y sodio) por la diarrea incesante pueden causar arritmias cardíacas fatales." }, types: { title: "Fases y Adaptación Intestinal", intro: "La gravedad depende de qué porción exacta del intestino se extirpó, pero la recuperación sigue fases:", items: ["Fase Aguda (Semanas a meses post-cirugía): Diarrea masiva de fluidos y pérdida de peso descontrolada. El paciente es absolutamente dependiente de nutrición intravenosa.", "Fase de Adaptación (1 a 2 años post-cirugía): El remanente del intestino delgado comienza a engrosarse y sus vellosidades crecen asombrosamente intentando compensar y absorber más nutrientes. La diarrea disminuye gradualmente.", "Fase de Mantenimiento: El intestino ha alcanzado su máxima adaptación funcional. Algunos pacientes logran depender de la comida oral y suplementos, mientras que otros requerirán nutrición artificial intravenosa de por vida."], note: "La extirpación del íleon terminal y la válvula ileocecal causa la forma más severa de deficiencia, ya que es donde se absorbe la vitamina B12, las sales biliares y se retiene el tránsito del bolo alimenticio." }, causes: { title: "Causas y Antecedentes Quirúrgicos", intro: "El síndrome suele ser el resultado secundario necesario de una cirugía para salvar la vida del paciente:", items: ["Enfermedad de Crohn severa: Es la causa principal en adultos. La inflamación crónica requiere cirugías repetidas para extirpar segmentos enfermos del intestino a lo largo de los años.", "Isquemia mesentérica (infarto intestinal): Bloqueo repentino de las arterias o venas que alimentan el intestino delgado, lo que causa la muerte masiva de los tejidos y requiere su extirpación de urgencia.", "Enterocolitis necrosante (en bebés prematuros): Infección grave que destruye el intestino del recién nacido.", "Vólvulo intestinal: Torsión completa de una porción del intestino sobre sí mismo, cortando el riego sanguíneo y obligando a la extirpación quirúrgica.", "Traumatismos abdominales severos (accidentes de tráfico, heridas por arma de fuego) o daño severo por radioterapia abdominal contra el cáncer."] }, diagnosis: { title: "¿Cómo se Evalúa y Controla?", intro: "El equipo de gastroenterología y nutrición diagnostica el grado de fallo mediante:", items: ["Historial quirúrgico exhaustivo para mapear exactamente cuántos centímetros de yeyuno e íleon quedan y si existe la válvula ileocecal o parte del colon", "Estudios de química sanguínea continuos y exhaustivos para vigilar peligrosas caídas de calcio, magnesio, potasio, proteínas, hierro y perfiles de vitaminas liposolubles (A, D, E, K)", "Tránsito del intestino delgado o enterografía por TAC/RM: Técnicas radiológicas con bario para medir el tamaño, dilatación y longitud del intestino funcional restante", "Análisis volumétrico de heces de 72 horas para determinar la cantidad de grasa excretada y electrolitos perdidos en las deposiciones"], note: "El paciente estará bajo un control casi hospitalario continuo para evitar carencias graves." }, treatment: { title: "Soporte Nutricional Complejo e Intervenciones", intro: "El objetivo vital es nutrir al cuerpo e incentivar la hiper-adaptación del intestino restante:", subsections: [ { title: "Terapias de alimentación, farmacológicas y cirugías", items: ["Nutrición Parenteral Total (NPT): El tratamiento de supervivencia primario. Mezcla personalizada de proteínas, grasas, vitaminas y azúcar infundida directamente en una vena central mayor del cuerpo, puenteando completamente el intestino inútil (algunos lo requieren por la noche todos los días de su vida).", "Nutrición Enteral: Uso de tubos de alimentación gástrica (sondas G) aplicados lentamente para estimular las paredes del intestino restante a adaptarse sin sobrecargarlo de diarrea.", "Medicamentos de freno intestinal (Antimotilidad): Loperamida, codeína u octreotida a dosis muy altas para ralentizar masivamente los intestinos y darles tiempo de absorber algo de fluidos y comida oral.", "Factores de crecimiento hormonal (Teduglutida o análogos de GLP-2): Inyecciones innovadoras que estimulan activamente el crecimiento del recubrimiento de las vellosidades intestinales para mejorar drásticamente la capacidad de absorción, permitiendo a muchos pacientes dejar la NPT intravenosa.", "Dietas complejas fraccionadas: 6 a 8 comidas diminutas al día, separación estricta de beber líquidos mientras se come, restricción total de azúcares simples (que jalan agua y causan diarrea violenta), y uso riguroso de soluciones de rehidratación oral (Sales ORS).", "Cirugías de alargamiento intestinal: Procedimientos altamente especializados (procedimientos STEP o Bianchi) donde el cirujano corta el intestino ancho remanente por la mitad y lo cose en serie para duplicar su longitud, o en último caso, un trasplante total de intestino (con alto riesgo de rechazo)."] } ], note: "El mayor riesgo a largo plazo de la dependencia prolongada de la NPT intravenosa es la insuficiencia hepática terminal y las infecciones mortales de la vía venosa central (sepsis)." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias Hospitalarias?", intro: "Quienes viven con este síndrome deben ir de urgencia al hospital si:", items: ["Experimentan signos de deshidratación severa incontrolable (ojos hundidos, desmayos constantes, ausencia de orina y pulso acelerado)", "El catéter venoso central para la NPT muestra enrojecimiento, supuración, dolor, o si el paciente desarrolla una fiebre alta repentina o escalofríos severos (signos inminentes de sepsis mortal)", "Presentan dolor abdominal nuevo y punzante, incapacidad de expulsar gases o vómitos intensos, indicando una posible obstrucción de los intestinos adheridos", "Tienen fracturas óseas por traumas mínimos o sangrados inusuales, alertando deficiencias terminales de minerales"] } },
'Infección crónica de los senos paranasales' : { intro: "La sinusitis crónica o infección crónica de los senos paranasales es una afección prolongada e irritante que dura semanas o meses. A diferencia de un resfriado común, provoca una inflamación persistente en las cavidades del rostro, causando congestión nasal dolorosa, presión en la frente y dificultades graves para respirar por la nariz y oler.", whatIs: { title: "¿Qué es la Sinusitis Crónica?", text: "Es una inflamación e hinchazón continua del tejido que recubre las cavidades óseas detrás del rostro, la frente y los ojos (los senos paranasales), que se prolonga durante 12 semanas o más a pesar de los intentos de tratamiento médico, impidiendo el drenaje normal de la mucosidad." }, symptoms: { title: "Síntomas Persistentes e Inflamatorios", intro: "El paciente debe lidiar con una presión incómoda diaria, que incluye al menos dos de los siguientes síntomas continuos:", groups: [ { name: "Síntomas nasales", items: ["Secreción nasal espesa, descolorida (amarillenta o verdosa) que drena desde la nariz o baja continuamente por la parte posterior de la garganta (goteo posnasal)", "Obstrucción nasal severa o congestión, que obliga a respirar constantemente por la boca", "Reducción significativa o pérdida total de los sentidos del olfato y del gusto"] }, { name: "Síntomas faciales y secundarios", items: ["Dolor, extrema sensibilidad, hinchazón o sensación de opresión severa alrededor de los ojos, mejillas, nariz o la frente", "El dolor facial a menudo empeora al inclinarse hacia adelante", "Dolor en la mandíbula superior y en los dientes superiores (la raíz del diente está muy cerca de los senos paranasales inflamados)", "Tos irritante que a menudo empeora de noche o por la mañana", "Mal aliento crónico (halitosis) y fatiga general prolongada"] } ], warning: "Si la hinchazón y el dolor facial se propagan y causan enrojecimiento intenso, visión doble o abultamiento alrededor del ojo o la frente, puede indicar una propagación grave de la infección y requiere atención médica inmediata." }, types: { title: "Diferenciación de la Sinusitis", intro: "Se categoriza por su duración y por el desarrollo de anomalías físicas:", items: ["Sinusitis Aguda: Dura menos de 4 semanas, generalmente secundaria a un resfriado viral y ocasionalmente bacteriana. Se resuelve por completo.", "Sinusitis Crónica con Pólipos Nasales: La inflamación crónica hace que el revestimiento desarrolle tumores benignos blandos en forma de gota de agua que bloquean físicamente los conductos y destruyen el olfato.", "Sinusitis Crónica sin Pólipos: Inflamación continua de las cavidades mucosas sin obstrucciones físicas aparentes.", "Rinosinusitis Fúngica Alérgica: Reacción inmunológica exagerada y alérgica a esporas de hongos normales presentes en el aire, que resulta en una mucosidad espesa, dura y elástica parecida a la mantequilla de maní."], note: "Curiosamente, en la mayoría de los casos crónicos (de más de 3 meses), el problema no es principalmente una 'infección' bacteriana, sino una enfermedad inflamatoria o respuesta autoinmune alérgica persistente de las vías." }, causes: { title: "Desencadenantes y Factores Anatómicos", intro: "La inflamación interminable se origina en bloqueos, alergias e irritantes subyacentes:", items: ["Pólipos nasales: Crecimientos indoloros que sellan los pequeños pasajes sinusales como un tapón, atrapando bacterias y secreciones", "Alergias crónicas no controladas (rinitis alérgica severa, fiebre del heno, alergias al moho o los ácaros del polvo)", "Tabique nasal muy desviado o cornetes agrandados (espolones óseos) que bloquean mecánicamente la salida y drenaje natural de los senos paranasales", "Infecciones respiratorias frecuentes y asma severa concurrente", "Afecciones médicas sistémicas que espesan la mucosa, como la Fibrosis Quística, reflujo gastroesofágico (ERGE) o sistemas inmunológicos muy deprimidos (VIH)", "Irritantes ambientales crónicos: Tabaquismo activo, exposición al humo o gran exposición a la contaminación industrial del aire"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El otorrinolaringólogo investigará las cavidades faciales profundamente mediante:", items: ["Endoscopia nasal (Rinoscopia): El médico inserta un tubo flexible iluminado (endoscopio) por las fosas nasales para ver en vivo cualquier pólipo, secreción o anormalidad bloqueando los diminutos canales de drenaje de los senos paranasales.", "Tomografía Computarizada (TC) de senos paranasales: El método diagnóstico radiológico estándar. Muestra imágenes 3D de alta resolución de la inflamación profunda que el endoscopio no alcanza a ver y ayuda a evaluar si el bloqueo requiere cirugía.", "Cultivos de secreciones nasales y nasofaríngeas guiados por endoscopia (NO el hisopo frontal simple) para identificar con precisión un hongo, o identificar si una bacteria específica resistente a los antibióticos está involucrada.", "Pruebas de punción de alergias para buscar y atacar un desencadenante alérgico fuerte."], note: "Las radiografías faciales simples no son útiles ni detalladas para evaluar la sinusitis crónica y ya casi no se recomiendan." }, treatment: { title: "Manejo Médico Escalado y Cirugía Desobstructiva", intro: "El objetivo es reducir implacablemente la inflamación y mantener los conductos permanentemente abiertos y drenando:", subsections: [ { title: "Terapias de primera línea y opciones avanzadas", items: ["Lavados nasales diarios masivos con solución salina estéril: El paso más básico, barato y útil para remover el exceso irritante de alérgenos y mocos estancados.", "Aerosoles y gotas con corticosteroides tópicos nasales (como fluticasona o mometasona): La medicación principal recetada a largo plazo para prevenir y tratar agresivamente la inflamación de la mucosa profunda.", "Corticosteroides orales o inyectables temporales (prednisona): Usados en ciclos cortos para casos graves, en especial si hay pólipos grandes que deben encogerse rápidamente, dada su eficacia radical antiinflamatoria, aunque sus efectos secundarios evitan su uso continuo.", "Antibióticos recetados de espectro especializado por periodos prolongados (de 3 a 4 semanas o más) pero SOLO si se ha confirmado por cultivo o persistencia sintomática la superposición clara de una infección bacteriana aguda secundaria sobre la crónica.", "Fármacos biológicos modernos (Dupilumab/Mepolizumab): Inyectables indicados exclusivamente en pacientes con sinusitis crónica con pólipos y asma que controlan las vías inflamatorias inmunológicas.", "Cirugía Endoscópica Nasosinusal Funcional (FESS): La opción final y muy exitosa cuando fallan los medicamentos. Con instrumentos diminutos, el cirujano corta y extirpa los pólipos, limpia el tejido engrosado e infectado y amplía quirúrgicamente todas las aberturas naturales de los senos paranasales para asegurar que jamás se tapen de nuevo."] } ], note: "Aunque la cirugía abre los conductos de forma increíble y alivia síntomas al instante, los lavados salinos y el spray con esteroides nasales deben mantenerse por vida si no el tejido volverá a inflamarse." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Otorrinolaringólogo u Hospital?", intro: "Solicite derivación rápida con un especialista, alergólogo o diríjase a urgencias si experimenta:", items: ["Los síntomas no mejoran tras ciclos completos de tratamiento con varios antibióticos dados por un médico general y se arrastran más de 12 semanas", "Hinchazón dolorosa repentina, enrojecimiento brillante alrededor o inflamación evidente de uno o ambos ojos", "Cambios bruscos de visión (su visión es doble u el globo ocular sobresale o se desplaza de lugar)", "Confusión intensa inesperada, dolor de cabeza extremo en la frente acompañado de rigidez severa en el cuello (signo de que la infección bacteriana ha alcanzado el cerebro causando meningitis)"] } },
'Síncope' : { intro: "El síncope es el término médico para lo que comúnmente se conoce como un desmayo. Aunque en la inmensa mayoría de los casos (como el provocado por ver sangre, el estrés intenso o estar mucho de pie) es totalmente benigno, en adultos mayores o en casos repentinos puede ser el síntoma centinela de un problema cardíaco mortal oculto.", whatIs: { title: "¿Qué es el Síncope (Desmayo)?", text: "Es una pérdida transitoria, súbita y breve del conocimiento y del control postural o tono muscular, seguida de una recuperación espontánea, rápida y completa, en segundos o pocos minutos. Ocurre cuando el flujo sanguíneo y el oxígeno hacia el cerebro disminuyen bruscamente de manera temporal." }, symptoms: { title: "Señales de Advertencia Previas y Presentación", intro: "Los pacientes suelen experimentar un breve estado de alerta pre-sincopal antes de colapsar, y al despertar relatan:", groups: [ { name: "Pródromos o síntomas previos (segundos o minutos antes)", items: ["Sensación profunda y repentina de mareo intenso, inestabilidad o aturdimiento ligero (sensación de que la cabeza flota)", "Visión de 'túnel' (oscurecimiento de la visión periférica), visión borrosa de puntos brillantes o pérdida de visión repentina momentánea", "Piel fría y pegajosa repentina, palidez facial extrema y sudoración profusa inexplicable", "Náuseas agudas o fuerte malestar en el área abdominal y bostezos repetidos", "Sensación repentina de debilidad total en las piernas (las rodillas 'se doblan') y zumbido de oídos (acúfenos)"] }, { name: "El episodio en sí y el despertar", items: ["Pérdida total del conocimiento con caída súbita y colapso flácido o en desplome hacia el suelo", "Ocasionalmente pueden producirse unas cuantas y breves sacudidas y contracciones mioclónicas (parecidas a temblores), pero no una convulsión extensa, epiléptica o rígida duradera", "A diferencia de las convulsiones, la recuperación a la consciencia total y vigilia clara es rápida (a menudo menos de un minuto), sin la profunda confusión mental (estado post-ictal) que dura horas en epilepsias"] } ], warning: "El síncope que ocurre sin ninguna advertencia, de la nada, especialmente mientras se hace ejercicio físico o que cursa con fuertes palpitaciones de pecho previas, sugiere fuertemente una arritmia cardíaca grave potencialmente letal y requiere hospitalización en alerta roja." }, types: { title: "Tipos de Síncope y Orígenes Anatómicos", intro: "Se clasifican fundamentalmente en tres amplias y distintas categorías:", items: ["Síncope Reflejo o Neuromediado (El más inofensivo y la gran mayoría): Incluye al Síncope Vasovagal. Una respuesta nerviosa exagerada ante dolor, visión de sangre, emociones fuertes, o calor intenso; los vasos sanguíneos de las piernas se abren o el ritmo cardíaco decae repentinamente y la presión se hunde (hipotensión transitoria).", "Síncope Ortostático (Hipotensión Ortostática): Desmayo al levantarse demasiado deprisa desde la cama o una silla. El cuerpo falla o tarda en bombear la sangre venosa contra la gravedad a tiempo (frecuente en deshidratados, diabéticos con problemas nerviosos autonómicos, o por la toma de medicamentos fuertes para la tensión).", "Síncope Cardiogénico (El más mortífero y peligroso): Desmayo provocado porque una arritmia fulminante (el corazón late a velocidad extrema u omite latidos críticos), infartos no percibidos previos o una enfermedad anatómica obstructiva vascular del corazón (estenosis aórtica extrema) detienen momentáneamente el flujo efectivo de sangre de salida del órgano vital hacia la cabeza."], note: "El Síncope Situacional (un subtipo vasovagal) se dispara a veces por un exceso extremo del nervio vago y esfuerzo tras actos concretos como solo el hecho de toser con fuerza, defecar dolorosamente, reír muy fuerte o tragar profundamente." }, causes: { title: "Factores y Causas Inmediatas de Caídas de Tensión Cardíacas", intro: "A menudo el detonante biológico inmediato detrás del flujo ausente cerebral se ve potenciado y originado por combinaciones críticas de debilidad:", items: ["Problemas estructurales de la frecuencia y ritmos del corazón (Taquicardias y Bradicardias severas), o por estenosis severa en grandes válvulas del corazón, siendo la urgencia máxima diagnosticada del cardiólogo.", "Deshidratación crítica extrema, ayunos severos o hemorragias agudas internas crónicas no detectables y abundantes que derivan en muy poca volemia circulante sanguínea (por ej. sangrado gástrico u anemia extrema).", "Reacciones farmacológicas: Personas polimedicadas con grandes dosis superpuestas de betabloqueantes o agentes hipotensores combinados con un diurético fuerte, o dosis altas e inadecuadas de insulina.", "Desencadenantes nerviosos o estímulos vasovagales: Exposición prolongada y de horas continuas de pie parado inmóvil (típica caída de los jóvenes que cantan coros, por el acumulamiento pasivo de la sangre venosa hacia la parte inferior sin actividad muscular gemelar), exposición muy prolongada masiva y sofocante o asfixiante al calor extremo exterior, un fuerte estado de miedo pánico asfixiante abrumador repentino o ansiedad al límite ante un dolor agudísimo agudo."] }, diagnosis: { title: "¿Cómo se Evalúa y Distingue su Origen Inmediato Excluyendo Cuadros Epilépticos?", intro: "Dado que las consecuencias a nivel letal oscilan inmensamente del origen, el diagnóstico cardiológico urgente y neurológico debe aislar rápidamente la posibilidad de un infarto por sobre una bajada de azúcar simple:", items: ["El Historial Clínico Exhaustivo Relatado: El 50% del diagnóstico es pura descripción en base al paciente; se cuestiona exactamente sobre los últimos segundos antes, y la de sus testigos presenciales inmediatos que detallan los síntomas de la escena del color del rostro, contracciones o la confusión que duró tras ser alzado.", "Electrocardiograma (ECG): Es absolutamente la primera e innegociable evaluación diagnóstica de oro de admisión por el urgenciólogo o cardiólogo, obligatoria para detectar e intentar localizar una anomalía de origen eléctrico o si existen paros arrítmicos de latidos peligrosos o anomalías estructurales ocultas que expliquen el síncope sin preaviso o aviso, como el QT prolongado peligroso letal o síndrome de Brugada.", "Prueba de Inclinación Pasiva o Mesa Basculante Clínica Especializada (Tilt Table Test): Para casos de diagnóstico elusivos sospechosos de tipo vasovagal o autonómico, el paciente se ata y reclina asegurado gradualmente a 70 grados de elevación sostenidos al menos veinte minutos midiendo continuamente presión arterial continua y latidos cardiológicos profundos al detectar cuando caen estrepitosamente simulando la provocación del evento para captarlo y determinar que es su problema de fallos de compensación.", "Ecocardiograma Estructural y Monitor portátil Holter implantable: Para evaluar la fuerza real de cavidad, o grabar durante al menos 24 a horas a todo mes de registro de un mes un ritmo eléctrico de vida normal diario asintomático del desmayado crónico impredecible buscando caídas o paradas súbitas en latidos ocultos transitorios de minutos ausentes de flujo que resulten peligrosas mortales in situ (como bloqueos).", "Pruebas de la caída de presión en cama de Ortostatismo tomadas sentado y después a pie seguidas para medir variaciones inmediatas clínicas por los cambios en el volumen interno, glucosa y de nivel de biometría metabólica hemática del riñón para descartar deshidratación grave o un derrame oculto en sangre masiva interna oculta."] }, treatment: { title: "Estrategias de Previsión de Seguridad O Control Preventivo e Implante Quirúrgico Correctivo Cardíaco Preventivo", intro: "Los pacientes o sujetos son frecuentemente prevenidos sobre pautas pero ante síncopes complejos de letalidad cardiogénica probados se aplican medidas avanzadas médicas intensivas cardiológicas:", subsections: [ { title: "Abordajes Terapéuticos y Opciones y Precauciones Anti-Síncope Clínicas", items: ["El Síncope Neuromediado Benigno General (Terapia preventiva o Vasovagal): Evitar los desencadenantes, levantarse sumamente lento y fraccionar comidas. Usar contramedidas musculares preventivas inmediatamente si siente u empieza el aturdimiento pre-síncope o se experimenta mareo temprano en el evento (como cruzar y apretar las dos piernas entre sí fuertemente, apretar con firmeza sostenida fuerte de ambas manos en tensión extrema y agacharse rápido para forzar la circulación de los líquidos hacia los niveles al cerebro al tiempo hasta abortar la caída).", "Modificaciones nutricionales obligatorias o de la ingesta base líquida y fármacos para la Hipotensión Ortostática Crónica de la tercera edad: Incremento masivo de agua y consumo de volumen muy importante de ingesta extra de la sal o sales minerales (con la aprobación médica), ajustes severos al régimen reduciendo la sobredosis excesiva o contraproducente y perjudicial a presiones u de pastillas o medicinas fuertes de tensión y la indicación de recetar medidas y medicamentos sintéticos especiales presores del vaso y corticoides de aumento volemia y compresión fuerte (Midodrina y la Fludrocortisona, si fallan medias presoras estrictas altas u otros de control en el flujo capilar base circulatorio).", "Síncope Cardiogénico Severo Tratado de Rescate (arritmias o daños): Si existen alteraciones ventriculares arrítmicas agudas recurrentes de fallo o los bloqueos profundos rítmicos cardíacos mortales comprobados en pacientes, la colocación endovascular e inserción urgente del marcapasos base intracardíaco o en último y máximo grado el vital y extremo de colocar el Desfibrilador Automático Implantable Quirúrgico (DAI para aplicar las descargas mortales eléctricas e impedir la muerte si sufren el paro del corazón por choque fulminante grave o fibrilaciones agudas u operaciones y reemplazo urgentes estenóticas de sus válvulas de corazón fallidas obstructivas al corazón profundo o la ablación y quema directa en sala especializada de catéter invasivo para las taquicardias severas focales mortales perjudiciales comprobadas base de choque arrítmico en su patología del flujo y su gravedad vital)."] } ], note: "La simple recostada en la cama del decúbito, al elevar fuertemente de manera manual sus extremidades tras el paciente sufrir el mareo presincopal previene y a menudo alivia rápidamente las secuelas e interrumpe una caída por choque base inminente." }, whenToSeekHelp: { title: "¿En Qué Ocasiones Se Insta Obligadamente a Llamar Inmediato a Urgencias O Área de Emergencia Tras Un Choque Sincopal de Desvanecimiento Repentino Grave o Alerta por Peligro?", intro: "Todos los ancianos mayores y también en casos en infantes e inesperados el adulto deben buscar una valoración perentoria, rápida urgencióloga del cuadro tras cada evento del desmayo general; pida asesoría o llame inmediatamente u si se detecta a:", items: ["Ocurre por entero bruscamente de improvisto totalmente y de inmediato y no cuenta usted con y no recuerda de absolutamente y sintió sin percibir los indicios típicos iniciales como las advertencias de transpiración, las leves náuseas y ni rastro u aviso leve premonitorio y en pleno ejercicio agudo activo o tras sentir agudas puntadas fuertes intensas coronarias o molestias asfixiantes en pecho pre-desmayo general u a nivel cardíaco asfixiante previo inminente.", "Es usted una de la personas sin causa del desmayo repetido, u ocurre al sujeto por la espalda en postura acostada total (una alarma neurológica enorme o rítmica letal si cae o presenta un síncope sin haber estado de pie contra base u inacción por la posición gravedad), en la etapa e incidente, al individuo o ha demorado u pasó inusualmente demorando gran tiempo extremo mayor a dos a tres muy angustiosos o unos prolongados varios minutos o tiempo prolongadísimo tendido u en recobrar conciencia general mental de un golpe sin sentido general completo de la normalidad al despertar o de su recuperación u base temporal sin conciencia aguda total de ubicación.", "Ha sufrido usted daños u sangrado severos internos u y secuelas traumatológicas grandes con graves laceraciones del dolor general durante al derrumbe a gran escala por pérdida rápida motriz o una persona en familia tuvo de hecho o de historial familiar muerte u casos crónicos cardiológicos por fallecimiento cardíaco severo imprevisto inesperado letal a jóvenes en su cuadro u familia en general al historial genético predeterminado arrítmico comprobable a base y la herencia sin dudas de nivel basal letal del corazón de familia."] } },
'Fractura de antebrazo' : { intro: "Una fractura de antebrazo implica la rotura de uno o de los dos huesos largos (el radio y el cúbito) que conectan el codo con la muñeca. Es una de las lesiones ortopédicas más habituales tanto en niños (por accidentes de juego) como en adultos (por caídas u osteoporosis), requiriendo inmovilización estricta o intervención quirúrgica dependiendo de su complejidad.", whatIs: { title: "¿Qué es una Fractura de Antebrazo?", text: "Es la interrupción de la continuidad ósea del radio (el hueso situado en el lado del dedo pulgar) y/o del cúbito (el hueso en el lado del dedo meñique). Las roturas pueden ocurrir cerca de la muñeca (extremo distal), en el medio de los huesos (diáfisis) o cerca del codo (extremo proximal)." }, symptoms: { title: "Síntomas y Señales Visuales", intro: "Los síntomas son inmediatamente dolorosos y obvios, impidiendo el uso normal del brazo:", groups: [ { name: "Signos clínicos del traumatismo", items: ["Dolor severo, punzante y agudo en la zona de la rotura, que empeora intensamente al mínimo intento de mover la mano o rotar la palma", "Deformidad visible, inusual y antinatural en el contorno del brazo (por ejemplo, el brazo parece doblado en un ángulo extraño o el hueso hace una curva pronunciada donde no debería)", "Hinchazón inmediata, rápida y progresiva en la zona, acompañada de la aparición de moretones (equimosis) oscuros horas después"] }, { name: "Síntomas neurológicos de alerta (Riesgo circulatorio)", items: ["Entumecimiento, hormigueo o dolor eléctrico que baja hasta los dedos de la mano o falta de fuerza aguda incontrolable (indica que el hueso roto está pellizcando o comprimiendo los nervios cercanos importantes o la arteria principal)", "Imposibilidad total de girar el brazo (rotación para poner la palma hacia arriba o hacia abajo)"] } ], warning: "Si el hueso ha perforado la piel (fractura abierta o expuesta), debe considerarse una urgencia quirúrgica mayor e inmediata debido al altísimo riesgo de una infección ósea catastrófica y necrosis." }, types: { title: "Clasificación de las Fracturas por Patrón y Lugar", intro: "Los ortopedistas designan nombres específicos a la fractura según cómo y dónde se rompan:", items: ["Fractura de Colles: La más común (especialmente en mayores); rotura de la parte baja del radio cerca de la muñeca tras caer apoyando la mano abierta.", "Fractura en tallo verde o de rodete: Casi exclusiva de los niños. El hueso del niño, que es más flexible, se dobla y se agrieta de forma incompleta por un solo lado, en lugar de partirse limpiamente en dos piezas enteras.", "Fracturas de diáfisis de ambos huesos: Rotura tanto del radio como del cúbito en su zona media. Muy inestables y dolorosas; ocurren por golpes directos fortísimos.", "Fractura de Monteggia o Galeazzi: Lesiones combinadas y muy peligrosas donde uno de los dos huesos largos se rompe, pero simultáneamente la articulación acompañante en la muñeca o el codo se disloca violentamente de su lugar."], note: "El tipo exacto de rotura, y si las partes del hueso siguen alineadas ('fractura no desplazada') o no ('fractura desplazada'), dictará si se usa solo yeso o placa metálica quirúrgica." }, causes: { title: "Causas y Mecanismos de Impacto Comunes", intro: "El impacto violento es el causante del trauma, variando según la situación de la vida:", items: ["Caída sobre un brazo estirado con la mano apoyada para amortiguar el impacto (la forma más clásica en todas las edades, transmitiendo la fuerza y fracturando fuertemente la zona baja del antebrazo)", "Golpe directo y directo contundente: Ocurre frecuentemente por tratar de protegerse y levantar el brazo instintivamente para detener y defenderse de un golpe u objeto pesado que cae (generalmente fractura el cúbito, conocida biológicamente y como la 'fractura del bastonazo')", "Lesiones traumáticas en el deporte y de alto impacto severas (fútbol, patinaje y ciclismo sin protección y los accidentes extremos automovilísticos de tránsito frontal que involucran fuerzas complejas en las partes en choque)", "Huesos frágiles (causa sistémica degenerativa subyacente): Personas de muy avanzada edad que padecen osteoporosis sufren roturas del antebrazo incluso con traumatismos mínimos o al apoyarse al levantarse de una silla o tras tropezones simples."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El personal médico realizará la evaluación basándose rápidamente en imágenes y sensibilidad:", items: ["Evaluación clínica prioritaria en el consultorio: Revisión inicial del compromiso y para constatar urgentemente la circulación vital sintiendo el pulso de la muñeca para asegurar que hay riego sanguíneo, y probar la sensación neurológica nerviosa general de la sensibilidad táctil en los dedos para evitar daños graves a largo plazo en extremidad y el flujo circulatorio y nervioso vital al nivel capilar distal.", "Radiografías de rutina en urgencias médicas (Rayos X convencionales y directos de múltiples frentes de vistas y el de perfil): Son el estándar diagnóstico de urgencias irremplazable rápido u barato y totalmente suficiente para poder captar todo un brazo u su totalidad de las articulaciones cercanas a donde la fractura, el tipo del rasgo de rotura angular, la cantidad total de esquirlas diseminadas es visualizada con total profundidad y el exacto nivel del o grado real severo del desplazamiento o dislocamiento huesudo o de desviación o luxaciones si ocurriesen asimétricas y que requiera al especialista cirujano actuar o guiar y reducir si existe deformidad articular evidente severa al paciente.", "Ocasionalmente Tomografía y la RM para lesiones sumamente complejas o sutiles y que afecten o que lleguen profundas o involucren al cartílago general o articulaciones adyacentes a nivel complejo y en pedazos del hueso o no detectables o evidentes en niños muy infantes del cartílago inmaduro o no solidificado."] }, treatment: { title: "Opciones Ortopédicas y Quirúrgicas de Manejo", intro: "El tratamiento dependerá enteramente de qué tan separado esté el hueso y si el paciente requiere precisión anatómica (la rotación):", subsections: [ { title: "Tratamiento de Reducción, Estabilización e Inmovilización Extensa Quirúrgica o Cerrada Conservadora en Pacientes General y Traumatológica del Nivel de Dolor de Fracturas", items: ["La opción de reducción o tratamiento cerrado o Inmovilizador y control conservador no cruento simple y rutinario: Exclusivo y destinado principal y mayoritariamente a las simples fisuras en tallo pediátrico infantil, las fracturas perfectamente estables lisas o donde las puntas del rasgo del trazo del hueso largo continúan firmes y anatómicamente alineadas donde corresponde. Si está un poco u muy chueco u desviado, el mismo y médico traumatólogo puede dormir al brazo sedado y enderezarlo muy fuerte u acomodarlo (reducción manual general y maniobras ortopédicas cerradas del brazo o hueso en clínica e instituto sin incisiones cutáneas ni bisturí del área), antes y después de inmovilizar de inmediato colocando fuertemente un yeso, un yeso parcial abierto o soporte u férula larga por cuatro y o hasta a de tres o u en varias de las de doce meses en base a las semanas seis continuas a semanas o curación fisiológica.", "El procedimiento principal u de fijación con intervenciones complejas de cirugía y quirúrgica ortopédica (Osteosíntesis abierta avanzada, interna, y general de reducción y para estabilización o la y ORIF con y por intervención placa directa) al paciente u traumatológico del adulto: Altamente o el requerido indispensable estricto si o cuando todo el brazo o huesos largos de antebrazo adultos de ambas diáfisis están dislocados separados o hay fragmentos grandes, cuando u existe compromiso neurovascular grave severo agudo de la zona general expuesta, cuando se atraviesa la piel externa e infección. El gran ortopedista abrirá, realineará perfectamente a mano los trazos los fragmentos y los fijará solidificando rígida y unirá mecánicamente y rígidamente todo con fuertes gruesas placas de tornillos o titanio e intramedulares o varillas quirúrgicos de acero permanente internos y de alta dureza a la o por vida, asegurando y brindando al o o el permitir recuperar un o temprano la rotación vital normal y rehabilitación sin yeso para siempre temprano a los días posoperatorio, reduciendo y con o fisioterapia."] } ], note: "La rehabilitación posterior intensiva con el especialista (fisioterapeuta y de mano y dedo) una vez extraído un yeso o pos-operado y después es casi de importancia idéntica que la cirugía y de tratamiento a la operación inicial misma, si el sujeto, usted, y o desea de recuperar absolutamente toda la movilidad completa flexora al giro de fuerza de muñeca de brazo para la rotación basal total general u o pronosupinación sin limitación de dolor que o y la atrofia del músculo no provoque cronicidad o debilidad u artritis futura y o a tiempo o su brazo quede fijo para la rutina basal u de tiempo y uso laboral general y normal u y completo al paciente en unos seis meses o base larga." }, whenToSeekHelp: { title: "¿En Qué Momento De Riesgo Solicitar Ir o y Consultar por Emergencias Inmediatamente U de Manera Rápida U Urgente Traumática General Ortopédica Al Especialista Tras Trauma Por Sospecha En Caso U Fuerte Al Impacto O De la Caída en Antebrazo En O y de y o General?", intro: "Cualquier deformación por una fractura posible u clara aparente del antebrazo es motivo de traslado urgente traumatológico a emergencias (mientras no coma o beba líquidos hasta saber que no necesitará el quirófano para ser anestesiado en emergencia), pero hágalo o active el protocolo con más celeridad u emergencia inmediata paramédica local hospitalaria o en emergencia general del área por complicaciones graves y daño de isquemia u a riesgo inminente u severo colateral agudo de amputación de tejido secundario grave a nivel neurológico sí:", items: ["Usted o su hijo sufren de dolor pero a esto usted nota y tiene una protuberancia visible con fractura ósea evidente severa aguda perforante expuesta aguda y que ha atravesado o rompió drásticamente desgarrando fuerte la piel profunda o existe una u hemorragia franca exterior al cuerpo (cubra firmemente con algo y venda y una tela gasa puramente estéril para frenar y sin hurgar y no manipular para que no ingrese la infección al cuerpo)", "Los dedos de su respectiva o de la base e inferior muñeca o mano afectada fracturada del paciente o o se encuentran, se empiezan y o perciben inusualmente o de pronto profundamente fríos, con de tono azulados violáceo intensos extraños, sumamente morados o pálidos de forma cadavérica anormal e intensa comparados al lado sano y o al control opuesto, advirtiendo compromiso muy u arterial grave por estrangulación isquémica.", "Ha perdido profunda repentinamente total o parcial o totalmente absolutamente u u gran o de sensibilidad u motriz, el nervio no reacciona, tiene gran grado de debilidad dolor agudo general que adormece dolor incontrolable adormecimiento o cosquilleo a tipo de aguja punzante agudo constante o agónico en todo brazo que no mengua u ni cede si se inmoviliza indicando o aplastamiento neurológico de síndrome de compresión vascular aguda profunda a tratar en sala y o quirúrgica general (el Síndrome Compartimental severo de presión)."] } },
'Obesidad infantil' : { intro: "La obesidad infantil es una afección médica grave que afecta a niños y adolescentes. Es particularmente preocupante porque el peso adicional suele provocar el inicio temprano de problemas de salud que antes se consideraban exclusivos de los adultos, como diabetes, presión arterial alta y colesterol alto.", whatIs: { title: "¿Qué es la Obesidad infantil?", text: "Se define como un exceso de grasa corporal que impacta negativamente la salud y el bienestar de un niño. Clínicamente, se diagnostica cuando el Índice de Masa Corporal (IMC) del niño es igual o superior al percentil 95 para niños de la misma edad y sexo." }, symptoms: { title: "Síntomas y Signos Visibles", intro: "No todos los niños con kilos de más tienen sobrepeso por una enfermedad, pero los signos de obesidad clínica incluyen:", groups: [ { name: "Indicadores físicos", items: ["Aumento de peso excesivo y rápido en relación con el crecimiento en altura", "Acumulación visible de tejido adiposo (grasa) alrededor del abdomen, pecho y rostro", "Estrías en el abdomen, caderas o muslos", "Acantosis nigricans (oscurecimiento aterciopelado de la piel, a menudo alrededor del cuello o las axilas, signo de resistencia a la insulina)"] }, { name: "Complicaciones asociadas", items: ["Dificultad para respirar al hacer esfuerzo físico o asma empeorada", "Apnea obstructiva del sueño (ronquidos fuertes o pausas en la respiración al dormir)", "Dolor persistente en las articulaciones que soportan peso (caderas, rodillas, tobillos)", "Baja autoestima, aislamiento social o síntomas de depresión"] } ], warning: "La aparición de oscurecimiento en el cuello (acantosis) es una señal de advertencia crítica de que el niño está en alto riesgo de desarrollar diabetes tipo 2." }, types: { title: "Clasificación Pediátrica", intro: "El estado de peso se clasifica usando las tablas de crecimiento del IMC:", items: ["Sobrepeso: IMC entre el percentil 85 y el 94.", "Obesidad: IMC en el percentil 95 o superior.", "Obesidad grave: IMC en el percentil 120 del percentil 95, o un IMC absoluto de 35 o más."], note: "El médico pediatra siempre debe evaluar la curva de crecimiento a lo largo del tiempo, no solo en una única visita." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es el resultado de un desequilibrio calórico influenciado por múltiples factores:", items: ["Dieta hipercalórica: Consumo frecuente de alimentos ultraprocesados, comida rápida, golosinas y, muy especialmente, bebidas azucaradas o jugos.", "Estilo de vida sedentario: Exceso de tiempo frente a pantallas (teléfonos, videojuegos, televisión) y falta de juego activo o deporte al aire libre.", "Factores familiares y genéticos: Los niños de padres obesos tienen un riesgo drásticamente mayor debido tanto a la genética compartida como a los hábitos alimenticios del hogar.", "Factores psicológicos: Comer en exceso para lidiar con el estrés, el aburrimiento o problemas emocionales.", "Causas médicas raras (menos del 1%): Trastornos hormonales como el hipotiroidismo o síndromes genéticos como el Síndrome de Prader-Willi."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra realiza una evaluación integral para determinar el riesgo de salud:", items: ["Cálculo del IMC (Índice de Masa Corporal) y su representación en las tablas de crecimiento estandarizadas", "Revisión detallada de los antecedentes médicos familiares (diabetes, enfermedades cardíacas)", "Análisis de sangre en ayunas para medir niveles de colesterol, triglicéridos y azúcar en la sangre (glucosa e insulina)", "Evaluación de la salud mental y los patrones de sueño del niño"], note: "El diagnóstico de obesidad no busca estigmatizar, sino identificar riesgos tempranos para prevenir daños a largo plazo." }, treatment: { title: "Manejo y Cambio de Estilo de Vida", intro: "El tratamiento exitoso requiere el compromiso y cambio de hábitos de toda la familia, no solo del niño:", subsections: [ { title: "Estrategias familiares y médicas", items: ["Modificaciones nutricionales: Priorizar frutas, verduras, granos enteros y proteínas magras. Eliminar por completo las bebidas azucaradas y limitar estrictamente la comida rápida.", "Aumento de la actividad física: Al menos 60 minutos de juego activo, deporte o ejercicio aeróbico todos los días.", "Reducción del tiempo de pantalla: Limitar el uso recreativo de pantallas a un máximo de 2 horas diarias.", "Terapia conductual familiar: Psicología para ayudar a modificar la relación de la familia con la comida y fomentar la autoestima del niño.", "Medicamentos o Cirugía Bariátrica: Reservados de manera exclusiva para adolescentes mayores con obesidad extrema y complicaciones médicas graves que no han respondido a cambios en el estilo de vida."] } ], note: "Es vital que los padres no pongan al niño a 'dieta estricta' por su cuenta sin supervisión, ya que esto puede frenar su crecimiento vertical o generar trastornos alimentarios." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Pediatra?", intro: "Solicite una revisión médica formal de salud y nutrición si:", items: ["Le preocupa que la tasa de aumento de peso de su hijo parezca desproporcionada en comparación con su crecimiento en altura", "El niño comienza a quejarse de dolor en las rodillas o caderas al correr o jugar", "Nota que el niño ronca muy fuerte, se asfixia o hace pausas al respirar durante la noche", "Aparecen manchas oscuras en la piel del cuello o las axilas", "Su hijo está siendo acosado (bullying) por su peso y muestra signos de aislamiento o tristeza profunda"] } },
'Aborto incompleto' : { intro: "Un aborto incompleto es una complicación obstétrica en la cual un embarazo se ha interrumpido, pero el cuerpo de la mujer no ha logrado expulsar todo el tejido fetal o placentario del útero. Requiere atención médica oportuna para prevenir infecciones severas (sepsis) o hemorragias abundantes.", whatIs: { title: "¿Qué es un Aborto Incompleto?", text: "Es la expulsión parcial de los productos de la concepción (tejido del embarazo) antes de las 20 semanas de gestación. Debido a que el útero retiene fragmentos de placenta o tejido, no puede contraerse adecuadamente para detener el sangrado, lo que provoca dolor prolongado y sangrado continuo." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "El cuadro clínico es evidente tras la pérdida del embarazo y se caracteriza por:", groups: [ { name: "Síntomas principales", items: ["Sangrado vaginal abundante y continuo que no se detiene (generalmente mucho más fuerte que un período menstrual normal)", "Expulsión visible de coágulos de sangre grandes o fragmentos de tejido grisáceo o carnoso", "Cólicos abdominales o pélvicos intensos, punzantes y persistentes (el útero intentando expulsar los restos)", "El dolor y el sangrado persisten días después de lo que parecía ser un aborto espontáneo"] }, { name: "Signos de complicación (Infección o Hemorragia masiva)", items: ["Fiebre (temperatura superior a 38°C o 100.4°F) y escalofríos", "Flujo o secreción vaginal con muy mal olor (fétido)", "Mareos extremos, debilidad, aturdimiento, piel pálida o desmayos (signos de pérdida de sangre peligrosa)", "Dolor abdominal que se vuelve rígido y constante, más allá de los cólicos intermitentes"] } ], warning: "Empapar más de dos toallas sanitarias tamaño maxi por hora durante dos horas consecutivas es una hemorragia potencialmente mortal que requiere atención en la sala de urgencias de inmediato." }, types: { title: "Contexto Clínico", intro: "El aborto incompleto forma parte del espectro clínico de la pérdida temprana del embarazo:", items: ["Aborto inevitable: El sangrado y el dolor han comenzado, el cuello uterino está abierto, pero aún no ha salido tejido.", "Aborto incompleto: El cuello uterino está abierto y ya salió parte del tejido, pero aún quedan restos dentro del útero.", "Aborto completo: Todo el tejido del embarazo ha sido expulsado de forma natural; el útero está vacío, el cuello uterino se ha cerrado y el sangrado disminuye rápidamente.", "Aborto séptico: Un aborto incompleto que se ha infectado gravemente, poniendo en peligro la vida de la mujer."], note: "El diagnóstico de un aborto incompleto se realiza frecuentemente tras un aborto con medicamentos (píldoras abortivas) o un aborto espontáneo natural." }, causes: { title: "Causas y Factores Subyacentes", intro: "La retención de tejido ocurre por razones mecánicas o fisiológicas tras la pérdida del embarazo:", items: ["El embrión o feto ha dejado de desarrollarse (a menudo por anomalías cromosómicas aleatorias) y el proceso natural del cuerpo para expulsar el tejido no se completa eficazmente.", "Fallo en la contracción uterina: Si un fragmento de placenta se adhiere fuertemente, el útero no puede cerrarse por completo para cortar los vasos sanguíneos sangrantes.", "Complicación de un aborto inducido (médico o quirúrgico) donde un pequeño resto no fue extraído o evacuado correctamente.", "Factores anatómicos maternos, como fibromas uterinos o un útero con forma irregular, que dificultan la expulsión natural completa."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El ginecólogo u obstetra confirmará la retención de tejido mediante:", items: ["Examen pélvico: El médico utiliza un espéculo para verificar si el cuello uterino (cérvix) sigue dilatado (abierto) y si hay tejido atascado en el canal cervical.", "Ecografía pélvica o transvaginal: La herramienta diagnóstica definitiva. Permite ver el interior del útero y confirmar visualmente si hay fragmentos retenidos de placenta o saco gestacional (el útero no se ve vacío o muestra una 'línea endometrial engrosada y heterogénea').", "Análisis de sangre (Hemograma): Para medir la cantidad de sangre que ha perdido la paciente (hemoglobina) y evaluar si hay un aumento de glóbulos blancos que indique infección.", "Niveles de hormona hCG (Gonadotropina coriónica humana) para descartar embarazos ectópicos o realizar seguimiento."], note: "Es vital informar al médico si usted ha notado la expulsión de tejido en casa; si es posible, llevarlo en un recipiente limpio ayuda a patología a confirmar el tejido." }, treatment: { title: "Opciones de Evacuación Uterina", intro: "El tratamiento es obligatorio para vaciar el útero, prevenir infecciones y detener el sangrado. Existen tres enfoques:", subsections: [ { title: "Opciones de Manejo Clínico", items: ["Manejo Expectante (Observación): Si la retención es muy pequeña y la paciente está estable, el médico puede esperar unas semanas para ver si el cuerpo lo expulsa naturalmente con el próximo sangrado.", "Manejo Médico (Fármacos): Administración de pastillas como Misoprostol (por vía oral o vaginal) que provocan fuertes contracciones uterinas para expulsar el tejido restante en casa de forma similar a una menstruación fuerte.", "Manejo Quirúrgico (Legrado o AMEU): El procedimiento de elección si el sangrado es masivo o hay infección. Se realiza una Aspiración Manual Endouterina (AMEU) o un legrado instrumental (D&C) bajo anestesia o sedación para raspar o succionar suavemente el interior del útero y dejarlo completamente limpio.", "Uso de antibióticos profilácticos si se realiza una intervención o si hay sospecha de infección uterina inicial.", "Inyección de Inmunoglobulina Rh si el grupo sanguíneo de la paciente es Rh negativo."] } ], note: "Tras una evacuación quirúrgica exitosa, el sangrado abundante suele detenerse en cuestión de horas y el dolor agudo desaparece rápidamente." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias Obstétricas?", intro: "Busque atención médica de urgencia hospitalaria inmediatamente si usted sabe que tuvo un aborto recientemente y presenta:", items: ["Sangrado vaginal extremo, donde empapa múltiples toallas sanitarias de tamaño grande en muy poco tiempo (una o más por hora)", "Expulsa coágulos de sangre que son del tamaño de un limón o de una pelota de golf", "Dolor pélvico repentino, desgarrador o calambres insoportables que no ceden con analgésicos comunes", "Tiene fiebre, siente escalofríos intensos o nota un flujo vaginal de mal olor", "Siente que se va a desmayar, está pálida, sudorosa o experimenta confusión mental severa"] } },
'Agrandamiento de adenoides' : { intro: "El agrandamiento de adenoides, o hipertrofia adenoidea, es un problema pediátrico frecuente. Estas glándulas se inflaman por infecciones o alergias, y al hincharse, bloquean el espacio detrás de la nariz, provocando que el niño respire crónicamente por la boca, ronque fuerte e incluso sufra pausas respiratorias peligrosas durante el sueño.", whatIs: { title: "¿Qué es la Hipertrofia Adenoidea?", text: "Las adenoides son pequeños parches de tejido inmunológico situados en la parte más alta de la garganta, justo detrás de las fosas nasales (no se pueden ver mirando por la boca). Su trabajo es atrapar gérmenes. El agrandamiento ocurre cuando este tejido se hincha anormalmente, obstruyendo la vía aérea nasal y los conductos de los oídos." }, symptoms: { title: "Síntomas Nasales y del Sueño", intro: "Los síntomas son un resultado directo de la obstrucción del flujo de aire y el drenaje de los oídos:", groups: [ { name: "Problemas respiratorios y faciales", items: ["Respiración constante y ruidosa por la boca (el niño casi nunca respira por la nariz)", "Voz nasal, congestionada o 'gangosa' (como si siempre tuviera un resfriado severo)", "Labios secos o agrietados y mal aliento crónico debido a la respiración bucal constante", "Desarrollo de la 'faz adenoidea' (cara alargada, mandíbula inferior caída, alteraciones en la mordida dental) debido a respirar por la boca durante años"] }, { name: "Complicaciones del sueño y de los oídos", items: ["Ronquidos fuertes y persistentes todas las noches", "Apnea obstructiva del sueño pediátrica (el niño deja de respirar por unos segundos, hace una pausa y luego jadea por aire mientras duerme)", "Infecciones frecuentes o crónicas del oído medio (otitis media), dolor de oídos o líquido acumulado detrás del tímpano", "Pérdida temporal de audición o retraso en el habla debido al líquido atascado en los oídos"] } ], warning: "La apnea del sueño causada por adenoides gigantes interfiere con el oxígeno cerebral del niño, causando fatiga, problemas graves de atención escolar o hiperactividad (similar al TDAH)." }, types: { title: "Diferenciación Anatómica", intro: "Las adenoides son parte del 'anillo de Waldeyer' y suelen afectarse junto con las amígdalas:", items: ["Hipertrofia Adenoidea Aislada: Solo las adenoides están agrandadas, causando principalmente síntomas nasales y de oído.", "Hipertrofia Amigdalo-Adenoidea: Agrandamiento simultáneo de amígdalas (visibles en la garganta) y adenoides (ocultas). Causa la obstrucción más severa del sueño y dificultades para tragar.", "Adenoiditis infecciosa: Episodio agudo donde las adenoides están activamente infectadas por bacterias, causando fiebre y moco purulento nasal espeso."], note: "Es normal que las adenoides crezcan durante la primera infancia, alcanzando su tamaño máximo entre los 3 y 5 años, pero normalmente se encogen y casi desaparecen en la adolescencia." }, causes: { title: "Causas del Agrandamiento Crónico", intro: "El tejido adenoideo se inflama en respuesta a la sobreestimulación inmunológica:", items: ["Infecciones virales y bacterianas recurrentes del tracto respiratorio superior (resfriados comunes constantes). El tejido se hincha para combatir la infección, pero a veces no vuelve a su tamaño normal una vez pasada.", "Rinitis alérgica crónica (alergias graves al polvo, polen, ácaros o caspa de mascotas) que mantiene las adenoides irritadas permanentemente.", "Exposición continua al humo del tabaco ambiental (humo de segunda mano).", "Genética: Algunos niños simplemente tienen un tejido linfático que tiende a crecer de manera desproporcionada ante irritantes menores."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Dado que no se pueden ver simplemente abriendo la boca, el otorrinolaringólogo pediátrico utiliza:", items: ["Endoscopia nasal: Un tubo minúsculo y flexible con una cámara se inserta suavemente por la fosa nasal del niño para visualizar directamente las adenoides en la parte posterior e inspeccionar el porcentaje exacto de bloqueo de la vía aérea.", "Radiografía lateral de cuello y cráneo: Una placa de rayos X de perfil que muestra claramente el perfil de las adenoides agrandadas y el estrechamiento de la columna de aire.", "Examen físico buscando signos de respiración bucal crónica y examinando los oídos con un otoscopio para ver si hay líquido atrapado o tímpanos retraídos.", "Polisomnografía (estudio del sueño) si se sospecha apnea del sueño severa."], note: "La endoscopia nasal en niños, aunque incómoda, es muy rápida y es la herramienta de evaluación más precisa." }, treatment: { title: "Tratamiento Médico y Cirugía (Adenoidectomía)", intro: "El tratamiento escalona desde medicamentos antiinflamatorios hasta la extirpación quirúrgica:", subsections: [ { title: "Medidas conservadoras y quirúrgicas", items: ["Aerosoles nasales con corticosteroides (como la fluticosona) recetados durante varias semanas o meses; pueden encoger exitosamente adenoides moderadamente agrandadas en niños con alergias.", "Antibióticos orales si el médico sospecha de una infección bacteriana activa crónica alojada en el tejido adenoideo.", "Cirugía de Adenoidectomía: El tratamiento definitivo y curativo si los medicamentos fallan. Se realiza bajo anestesia general; el cirujano raspa, quema o cauteriza el tejido a través de la boca abierta del niño (sin cortes externos).", "Cirugía combinada: Frecuentemente se extirpan las adenoides, las amígdalas (amigdalectomía) y se insertan pequeños tubos de ventilación (diábolos) en los tímpanos durante la misma intervención para resolver simultáneamente la apnea del sueño y las infecciones de oído crónicas."] } ], note: "La recuperación de una adenoidectomía sola es muy rápida (2-3 días) y extirpar estas glándulas no debilita en absoluto el sistema inmunológico del niño, ya que otros órganos asumen la defensa." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Pediatra u Otorrinolaringólogo?", intro: "Lleve a su hijo a una evaluación médica especializada si observa que:", items: ["El niño respira exclusivamente por la boca durante el día y tiene problemas para masticar con la boca cerrada", "Ronca fuertemente la mayoría de las noches y parece atragantarse, resoplar o tener pausas en su respiración al dormir", "Sufre de infecciones de oído de repetición (más de tres o cuatro en un año) o su escuela reporta que parece no escuchar bien las instrucciones", "Tiene una congestión nasal espesa crónica o goteo posnasal que nunca desaparece a pesar de no estar resfriado", "Muestra cansancio excesivo, mal humor crónico, déficit de atención o mal rendimiento escolar (probablemente por mal dormir)"] } },
'Hidrocele de la túnica vaginal del testículo (proceso vaginal)' : { intro: "Un hidrocele es una acumulación indolora de líquido alrededor de uno o ambos testículos, provocando que el escroto se hinche. Es sumamente común en bebés recién nacidos varones (desapareciendo por sí solo) pero también puede aparecer en hombres adultos como resultado de una lesión o inflamación testicular.", whatIs: { title: "¿Qué es un Hidrocele?", text: "Es un tipo de inflamación en el escroto. Ocurre cuando se acumula líquido seroso claro en la 'túnica vaginal', que es la bolsa o saco delgado que rodea individualmente cada testículo. Este saco normalmente contiene unas pocas gotas de líquido para lubricación, pero en el hidrocele se llena en exceso." }, symptoms: { title: "Síntomas y Señales Visuales", intro: "El hidrocele en sí mismo rara vez duele. Los síntomas son predominantemente mecánicos y visuales:", groups: [ { name: "Signos físicos", items: ["Hinchazón o agrandamiento visible en uno o ambos lados del escroto", "El escroto se siente pesado, lleno o como si tuviera un 'globo de agua' liso y tenso en su interior", "Generalmente es completamente indoloro al tacto (la ausencia de dolor es un rasgo clave)", "En adultos, la pesadez puede causar una molestia sorda o sensación de arrastre, especialmente hacia el final del día", "El tamaño de la hinchazón puede fluctuar (disminuye en reposo por la mañana y aumenta al estar de pie durante el día) si es del tipo 'comunicante'"] } ], warning: "Si la hinchazón escrotal es de aparición repentina y se acompaña de dolor testicular agudo e intenso, NO es un hidrocele; podría ser torsión testicular, una emergencia médica que requiere cirugía en horas." }, types: { title: "Clasificación (Comunicante vs. No Comunicante)", intro: "El mecanismo del hidrocele define su clasificación, fundamental para el tratamiento:", items: ["Hidrocele Comunicante: Más común en bebés. El saco del testículo (proceso vaginal) no se cerró por completo después de que los testículos descendieron antes del nacimiento. Existe un conducto abierto hacia el abdomen, permitiendo que el líquido abdominal fluya hacia el escroto (y a menudo se asocia con una hernia inguinal).", "Hidrocele No Comunicante: El canal hacia el abdomen sí se cerró, pero el líquido adicional quedó atrapado en el saco escrotal y el cuerpo no puede absorberlo correctamente. Es el tipo más común en adultos."], note: "El hidrocele no comunicante no cambia de tamaño si el paciente se acuesta o llora, mientras que el comunicante sí." }, causes: { title: "Causas y Origen", intro: "Las causas varían drásticamente dependiendo de la edad del paciente:", items: ["En bebés (Congénito): Fallo en el cierre del proceso vaginal (el tubo por donde descienden los testículos desde el abdomen al escroto) durante el desarrollo fetal, dejando que el líquido gotee y se estanque.", "En adultos (Adquirido): Generalmente el resultado de inflamación o lesión localizada.", "Epididimitis u Orquitis: Infección o inflamación severa de los conductos testiculares o del propio testículo.", "Traumatismos o golpes directos recientes en la ingle o los testículos.", "Posquirúrgico: Una complicación relativamente frecuente a los pocos meses de haberse sometido a una cirugía de hernia inguinal o de varicocele.", "Rara vez, puede ser causado por un tumor testicular o bloqueo de líquidos causado por parásitos (filariasis en regiones tropicales)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo o médico general puede diagnosticarlo rápidamente con maniobras sencillas:", items: ["Examen físico: El médico palpará el escroto. Un hidrocele se siente liso, blando y lleno de líquido. Si se puede palpar fácilmente el testículo duro dentro del líquido, es diagnóstico.", "Prueba de transiluminación: El médico brillará una linterna fuerte directamente detrás de la bolsa escrotal en una habitación oscura. Si es un hidrocele, la luz atravesará el líquido claro (el escroto se iluminará de color rojizo), lo que no sucedería si fuera una masa sólida como un tumor o sangre.", "Ecografía escrotal (ultrasonido): La prueba confirmatoria y definitiva. Se realiza rutinariamente para descartar con total seguridad tumores testiculares, hernias inguinales estranguladas o alteraciones del flujo sanguíneo."], note: "Es vital examinar si el bulto escrotal contiene un asa de intestino (hernia), lo que requiere cirugía pediátrica." }, treatment: { title: "Observación y Reparación Quirúrgica (Hidrocelectomía)", intro: "El tratamiento depende de la edad, el tamaño y si causa molestias:", subsections: [ { title: "Manejo según edad del paciente", items: ["En bebés varones: La regla general es la observación pura. Casi todos los hidroceles no comunicantes se resuelven por sí solos y el cuerpo absorbe el líquido antes de que el niño cumpla el primer año de vida. Si persiste más allá del año u año y medio, se requiere cirugía debido al riesgo persistente de hernia concurrente.", "En hombres adultos: Si el hidrocele es pequeño y no causa dolor ni molestias estéticas, no requiere tratamiento. Se le indica al paciente usar ropa interior de soporte firme.", "Aspiración con aguja: El médico drena el líquido con una jeringa y puede inyectar un medicamento esclerosante. Sin embargo, el líquido casi siempre regresa en meses, por lo que rara vez se recomienda, excepto en hombres que no pueden soportar una cirugía.", "Cirugía (Hidrocelectomía): El tratamiento definitivo para hidroceles grandes, incómodos o comunicantes. Mediante una incisión menor en el escroto o en la ingle inferior, el cirujano drena el líquido y extirpa o pliega el saco para que el líquido no vuelva a acumularse. Suele ser ambulatoria."] } ], note: "La hidrocelectomía en bebés se realiza a través de un pequeño corte en la ingle (no en el escroto) para reparar simultáneamente el conducto abdominal abierto." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Urólogo o Urgencias?", intro: "Busque atención médica para usted o su hijo si:", items: ["Nota hinchazón persistente o un nuevo bulto en el escroto, incluso si no le duele (para descartar tumores testiculares)", "Usted o su hijo desarrollan un dolor súbito, repentino y severo en el testículo o escroto (emergencia médica)", "La hinchazón del escroto en un bebé no ha desaparecido tras cumplir los 12 a 18 meses de edad", "La hinchazón cambia de tamaño a lo largo del día, apareciendo más grande al estar de pie o al llorar (hidrocele comunicante)"] } },
'Gingivitis ulceronecrosante aguda' : { intro: "La Gingivitis Ulceronecrosante Aguda (GUNA), también conocida históricamente como 'Boca de trinchera', es una infección dolorosa, agresiva y destructiva de las encías. A diferencia de la gingivitis común (indolora), esta enfermedad causa úlceras severas, sangrado profuso y muerte del tejido de las encías debido al estrés extremo, tabaquismo y mala higiene.", whatIs: { title: "¿Qué es la GUNA (Boca de Trinchera)?", text: "Es una forma severa y aguda de enfermedad periodontal inflamatoria. Se caracteriza por una infección masiva de bacterias patógenas que atacan y destruyen (necrosan) rápidamente el tejido gingival, especialmente las papilas interdentales (las puntas de encía con forma de triángulo que se encuentran entre los dientes)." }, symptoms: { title: "Síntomas Bucales Severos y Rápidos", intro: "Los síntomas aparecen casi de un día para otro y son extremadamente incómodos:", groups: [ { name: "Daño estructural en encías", items: ["Dolor intenso, severo y constante en las encías, que empeora enormemente al comer o cepillarse", "Encías de color rojo brillante que sangran profusamente ante el menor contacto o incluso de forma espontánea", "Las 'puntas' de las encías entre los dientes (papilas) aparecen aplastadas, hundidas o en forma de 'cráter' (úlceras perforadas)", "Presencia de una capa gruesa, grisácea o amarillenta de tejido muerto (pseudomembrana) sobre las úlceras"] }, { name: "Síntomas sistémicos y odoríficos", items: ["Halitosis extrema y muy característica (mal aliento fétido, a veces con un regusto metálico crónico en la boca)", "Aumento de la salivación o sensación pastosa constante en la boca", "Fiebre leve, malestar general, fatiga extrema", "Ganglios linfáticos inflamados y dolorosos en el cuello o debajo de la mandíbula"] } ], warning: "Si no se trata agresivamente, la infección destruirá rápidamente el hueso de soporte dental (periodontitis ulceronecrosante), provocando la pérdida permanente de los dientes afectados en poco tiempo." }, types: { title: "Evolución y Condiciones Relacionadas", intro: "La GUNA es parte de un espectro de enfermedades necrosantes:", items: ["Gingivitis Ulceronecrosante (GUN): La infección y necrosis se limitan estrictamente al tejido blando de las encías.", "Periodontitis Ulceronecrosante (PUN): La infección ha avanzado más profundo, destruyendo tanto la encía como el ligamento periodontal y el hueso alveolar que sostiene el diente.", "Estomatitis Necrosante: Extremadamente rara; la necrosis masiva se extiende más allá de las encías hacia las mejillas internas o los labios (Noma, común en países con desnutrición severa extrema)."], note: "Históricamente se le llamó 'boca de trinchera' en la Primera Guerra Mundial por afectar a los soldados en el frente debido al estrés extremo y la mala higiene." }, causes: { title: "Causas Bacterianas y Factores Inmunosupresores", intro: "Es provocada por un crecimiento excesivo de bacterias específicas (espiroquetas y fusobacterias) debido a una caída drástica en las defensas locales:", items: ["Higiene bucal extremadamente pobre o inexistente, permitiendo que la placa dental y el sarro se acumulen masivamente", "Estrés psicológico o emocional agudo e intenso (el factor desencadenante más común en estudiantes universitarios o personas bajo crisis)", "Tabaquismo severo (el tabaco reduce el flujo sanguíneo y la inmunidad en las encías, y casi todos los pacientes con GUNA son fumadores)", "Nutrición deficiente grave (falta de vitaminas esenciales) o privación de sueño prolongada", "Sistema inmunológico deprimido (como en pacientes con infección por VIH no tratada o sometidos a quimioterapia)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico lo realiza rápidamente un odontólogo o periodoncista mediante:", items: ["Inspección clínica visual directa: El dentista reconoce inmediatamente el olor fétido característico, el sangrado espontáneo y las úlceras en forma de cráter recubiertas por la membrana grisácea.", "Evaluación del dolor del paciente ante un sondaje periodontal suave.", "Toma de radiografías dentales panorámicas o periapicales para evaluar si la infección ya ha destruido o disuelto el hueso de soporte bajo las encías (periodontitis).", "Análisis de sangre y pruebas de detección de VIH o problemas de azúcar, si el paciente presenta esta infección pero afirma tener buena higiene y no sufrir estrés, ya que indica un sistema inmunológico ocultamente colapsado."], note: "Los frotis bacterianos bajo microscopio rara vez se necesitan porque la presentación clínica en el consultorio es inconfundible." }, treatment: { title: "Tratamiento de Choque y Desbridamiento", intro: "El tratamiento detiene la destrucción del tejido, cura la infección y alivia el dolor drásticamente en días:", subsections: [ { title: "Intervención odontológica y médica", items: ["Desbridamiento profesional inmediato: El dentista limpia cuidadosamente (a menudo bajo anestesia local) todo el sarro, la placa bacteriana y el tejido necrótico gris (muerto) de los dientes y encías afectadas con herramientas ultrasónicas.", "Uso riguroso de enjuagues bucales antimicrobianos recetados (Clorhexidina) o enjuagues tibios con peróxido de hidrógeno diluido o agua con sal en casa varias veces al día.", "Antibióticos sistémicos orales (frecuentemente Metronidazol, Amoxicilina o Penicilina) recetados invariablemente para matar la cepa específica de bacterias agresivas y tratar la fiebre/ganglios.", "Analgésicos de venta libre (Ibuprofeno) para manejar el fuerte dolor inicial.", "Control absoluto de factores de riesgo: Detener el tabaquismo, dormir adecuadamente y mejorar la nutrición de forma inmediata.", "Instrucción de higiene bucal extremadamente estricta en el hogar usando cepillos ultra suaves hasta que las úlceras sanen, seguido de cirugías para reformar las encías hundidas (gingivoplastia) si el daño estructural fue severo."] } ], note: "Con tratamiento con antibióticos y limpieza, la mejoría del dolor es espectacular y ocurre en las primeras 24 a 48 horas." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Dentista de Urgencia?", intro: "Solicite una cita odontológica de emergencia si experimenta:", items: ["Encías repentinamente muy adoloridas, que parecen haber sido 'cortadas' en las puntas entre los dientes y sangran profusamente", "Mal aliento severo, inusual y fuerte que no mejora al cepillarse los dientes superficialmente", "Presencia de un tejido pastoso gris o amarillo desprendiéndose del borde de sus dientes", "Fiebre y ganglios del cuello inflamados concurrentes con dolor de encías y dificultad severa para tragar alimentos sólidos"] } },
'Estenosis de la válvula aórtica' : { intro: "La estenosis de la válvula aórtica es una de las enfermedades cardiovasculares más graves y comunes en personas mayores. Ocurre cuando la válvula principal de salida del corazón se vuelve rígida, estrecha y calcificada. Esto obliga al corazón a trabajar a marchas forzadas para expulsar la sangre, lo que eventualmente provoca insuficiencia cardíaca y riesgo de muerte súbita.", whatIs: { title: "¿Qué es la Estenosis Aórtica?", text: "Es el estrechamiento u obstrucción de la válvula aórtica, situada entre el ventrículo izquierdo (la cámara de bombeo principal) y la aorta (la arteria principal que lleva sangre al resto del cuerpo). Al no abrirse completamente, restringe severamente el flujo de sangre rica en oxígeno hacia el cerebro y el cuerpo." }, symptoms: { title: "Síntomas Clínicos Tardíos y Críticos", intro: "Puede ser silenciosa durante décadas. Cuando el estrechamiento se vuelve severo, los síntomas clásicos de alarma incluyen:", groups: [ { name: "La triada clásica de síntomas cardíacos", items: ["Angina de pecho: Dolor, opresión o sensación de aplastamiento en el pecho, especialmente al hacer un esfuerzo físico, caminar o subir escaleras.", "Síncope: Mareos graves, aturdimiento profundo o desmayos repentinos, frecuentemente desencadenados por el ejercicio (porque el cerebro no recibe suficiente sangre).", "Disnea: Falta de aire progresiva o dificultad para respirar severa al realizar actividades que antes eran fáciles, o al acostarse en la cama."] }, { name: "Síntomas sistémicos adicionales", items: ["Fatiga extrema inusual, debilidad generalizada y pérdida de energía", "Palpitaciones rápidas o latidos irregulares (aleteo en el pecho)", "Hinchazón por retención de líquidos (edema) en tobillos y pies (signo de que el corazón ya está fallando)"] } ], warning: "La aparición de síntomas (dolor de pecho, desmayos o falta de aire por esfuerzo) en un paciente con estenosis aórtica indica que la esperanza de vida se ha reducido drásticamente sin cirugía (a menudo a menos de 2 a 3 años)." }, types: { title: "Clasificación de Gravedad", intro: "Los cardiólogos evalúan el daño calculando el tamaño del agujero de la válvula y la presión de la sangre:", items: ["Estenosis leve: La válvula está algo rígida, pero el flujo es adecuado. No hay síntomas; solo requiere monitoreo médico anual.", "Estenosis moderada: Mayor estrechamiento y el músculo cardíaco comienza a engrosarse (hipertrofia) por el esfuerzo. Monitoreo clínico cercano.", "Estenosis severa/crítica: El área de la válvula es mínima (menos de 1 cm²). Obligatoriamente presenta síntomas, la presión interna del corazón es muy alta y la cirugía de reemplazo es imperativa."], note: "El músculo cardíaco intentará compensar la válvula estrecha engrosando sus paredes, pero eventualmente este músculo grueso se cansará y fallará (insuficiencia cardíaca)." }, causes: { title: "Causas y Enfermedades Relacionadas", intro: "Las válvulas se estrechan y calcifican por tres motivos principales:", items: ["Degeneración calcificada por la edad: La causa más común en adultos mayores (senil). Con los años, los depósitos de calcio en la sangre se acumulan y petrifican las valvas flexibles de la válvula.", "Defecto congénito (Válvula Aórtica Bicúspide): Algunas personas nacen con una válvula que tiene solo dos valvas (cúspides) en lugar de las tres normales. Se desgasta mucho más rápido y causa estenosis severa típicamente en personas entre 40 y 60 años.", "Fiebre reumática: Una complicación de infecciones estreptocócicas en la infancia. El tejido de la válvula se cicatriza, engrosa y fusiona, impidiendo que se abra. Es menos común hoy en países desarrollados.", "Enfermedad renal crónica severa o radioterapia extensa en el área del tórax en el pasado."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un soplo cardíaco detectado en una revisión de rutina es el primer indicio, seguido de:", items: ["Ecocardiograma (Ultrasonido cardíaco): El estándar de oro diagnóstico. Visualiza el grosor de la válvula, mide exactamente a qué velocidad viaja la sangre a través del bloqueo y evalúa si el ventrículo izquierdo está dañado o engrosado.", "Auscultación con estetoscopio: El médico escucha un soplo áspero o fuerte característico en el pecho.", "Electrocardiograma (ECG): Para buscar signos de engrosamiento del corazón izquierdo o detectar arritmias peligrosas.", "Prueba de esfuerzo en cinta rodante (Solo para pacientes que afirman no tener síntomas): Para ver si el ejercicio destapa síntomas ocultos o caídas de la presión arterial de forma segura.", "Cateterismo Cardíaco y Angiografía: Inserción de un tubo en la ingle hasta el corazón para medir presiones exactas si el ecocardiograma no es claro, y para examinar si hay bloqueos en las arterias coronarias antes de operar."], note: "Es vital un seguimiento frecuente; una estenosis leve puede volverse severa en un lapso de meses a unos pocos años." }, treatment: { title: "Reemplazo Valvular y Manejo", intro: "No existen medicamentos que puedan disolver el calcio o abrir la válvula mecánicamente. La única solución a la estenosis severa es reemplazarla:", subsections: [ { title: "Opciones Intervencionistas y Quirúrgicas", items: ["Reemplazo quirúrgico de válvula aórtica (SAVR): Cirugía tradicional a corazón abierto. El cirujano detiene el corazón, extirpa la válvula calcificada y la sustituye por una mecánica (duradera, pero requiere anticoagulantes de por vida) o biológica (hecha de tejido de vaca o cerdo, no requiere anticoagulantes pero dura unos 15 años).", "Reemplazo de la válvula aórtica transcatéter (TAVR o TAVI): Un procedimiento revolucionario menos invasivo (sin abrir el pecho). Se inserta una válvula biológica de reemplazo, comprimida dentro de un catéter, a través de una arteria en la ingle hasta el corazón. Al llegar a la vieja válvula enferma, la nueva válvula se infla con un globo, aplastando la vieja y asumiendo su lugar. Ofrece recuperación muy rápida y es ideal para personas mayores.", "Valvuloplastia con globo: Tratamiento paliativo o puente para pacientes muy inestables. Un globo abre la válvula temporalmente, pero a menudo se estrecha de nuevo meses después.", "Medicamentos de soporte: Fármacos para la presión y diuréticos para mantener los fluidos pulmonares bajo control hasta el día de la cirugía."] } ], note: "La decisión entre cirugía abierta (SAVR) o TAVI depende estrictamente de la edad del paciente, su riesgo quirúrgico y si tiene otras enfermedades asociadas." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Cardiólogo de Urgencia?", intro: "Es motivo de intervención médica inmediata si se sabe que tiene estenosis o si de la nada usted presenta:", items: ["Aparición repentina de dolor profundo, presión, llenura u opresión opresiva bajo el esternón al caminar, que se alivia al sentarse", "Episodios donde se marea intensamente, su visión se oscurece o se desmaya repentinamente durante un esfuerzo físico leve", "Incapacidad abrupta para respirar normalmente o sensación de asfixia al acostarse o tras una actividad ligera", "Sensación constante de que su corazón se acelera, late de forma irregular y su cuerpo sufre de fatiga total inexplicable"] } },
'Dolor somático' : { intro: "El dolor somático es el tipo de dolor físico más común que experimentan las personas. Se produce en la piel, los músculos, los huesos, las articulaciones o el tejido conectivo en respuesta a un traumatismo, inflamación o lesión directa. A diferencia del dolor de nervios, es una señal defensiva normal y saludable del sistema nervioso indicando daño en el cuerpo.", whatIs: { title: "¿Qué es el Dolor Somático?", text: "Es un tipo de dolor nociceptivo originado en el sistema musculoesquelético o la piel. Se activa cuando los nociceptores (receptores específicos del dolor) en estos tejidos detectan daño físico directo, presión intensa, cortes o temperaturas extremas, enviando una advertencia inmediata al cerebro." }, symptoms: { title: "Características y Percepción del Dolor", intro: "El dolor somático es típicamente muy claro, fácil de describir e identificar en el cuerpo:", groups: [ { name: "Dolor somático superficial (Piel)", items: ["Dolor agudo, punzante, palpitante o cortante (como al cortarse con papel o rasparse la piel)", "Extremadamente fácil de localizar con un solo dedo ('el dolor está exactamente aquí')", "La zona suele estar enrojecida, hinchada y muy sensible al tocarla o rozarla ligeramente", "Aparece instantáneamente en el momento de la lesión superficial"] }, { name: "Dolor somático profundo (Músculos, Huesos, Articulaciones)", items: ["Dolor sordo, intenso, profundo, calambres o como un 'dolor de muelas' en los huesos o músculos (ej. un esguince de tobillo o un hueso roto)", "Empeora de manera predecible con el movimiento de la extremidad afectada o al aplicar peso/presión directa", "Puede irradiarse (extenderse) ligeramente a zonas musculares circundantes debido a espasmos reflejos", "Difícil de localizar con un punto exacto, el paciente tiende a frotar toda la zona general que duele"] } ], warning: "Si un dolor muscular profundo y sordo en el brazo izquierdo u hombro viene acompañado de falta de aire y sudor, no es dolor somático ortopédico, es un infarto (dolor visceral referido)." }, types: { title: "Diferenciación del Dolor Nociceptivo", intro: "Los médicos categorizan el origen físico del dolor para tratarlo correctamente:", items: ["Dolor somático: Proviene de la 'envoltura' del cuerpo (piel, huesos, músculos, articulaciones). Ejemplos: cortes, tendinitis, artritis, fracturas o desgarros musculares.", "Dolor visceral (En contraposición): Proviene de los órganos internos (estómago, corazón, intestinos). Se siente profundo, opresivo, vago, acompañado de náuseas o sudores (ej. apendicitis, cólico biliar).", "Dolor neuropático (En contraposición): Proviene de nervios dañados, sintiéndose como ardor o electricidad (ej. ciática)."], note: "El dolor somático puede ser agudo (lesión reciente que sana en días/semanas) o crónico (dolor artrítico que dura años)." }, causes: { title: "Causas y Lesiones Frecuentes", intro: "El origen del dolor somático es casi siempre un estímulo físico o mecánico obvio o una inflamación:", items: ["Traumatismos físicos directos: Fracturas óseas, esguinces de ligamentos o desgarros de fibras musculares.", "Lesiones menores en la superficie: Cortes, laceraciones, quemaduras en la piel por calor o raspaduras graves.", "Inflamación articular y enfermedades crónicas: Artrosis (desgaste del cartílago), artritis reumatoide o ataques de gota.", "Sobrecarga muscular severa: Dolor y calambres después de un ejercicio extremo o levantar pesas de forma inadecuada (agujetas severas o tendinitis).", "Tensión y espasmos: Dolores de espalda mecánicos comunes debidos a mala postura o hernia de disco presionando ligamentos.", "Daño tisular quirúrgico: El dolor punzante en la incisión de la piel después de cualquier cirugía."] }, diagnosis: { title: "¿Cómo Evalúa el Médico el Origen?", intro: "El diagnóstico es clínico y busca identificar la estructura ósea o muscular lesionada:", items: ["Entrevista médica detallada y evaluación del tipo de dolor usando la escala del 1 al 10, y determinando si movimientos específicos lo agravan o lo calman.", "Examen físico y ortopédico: El médico palpará, presionará y moverá la articulación o músculo buscando identificar la inflamación exacta, el espasmo o la pérdida de rango de movimiento.", "Radiografías (Rayos X): Primera línea para confirmar dolor óseo causado por fracturas severas, microfisuras o desgaste por artrosis.", "Ecografía musculoesquelética o Resonancia Magnética (RM): Utilizada para ver detalladamente si existe un desgarro de tendones, rotura de ligamentos ocultos o inflamación muscular interna."], note: "El dolor somático es la queja médica más fácil de investigar porque existe una lesión orgánica estructural medible." }, treatment: { title: "Opciones Analgésicas y Fisioterapéuticas", intro: "Responde excelentemente a medicamentos comunes y enfoques de medicina deportiva:", subsections: [ { title: "Tratamientos farmacológicos y rehabilitación", items: ["Medicamentos Antiinflamatorios No Esteroideos (AINEs): El tratamiento de elección y primera línea (Ibuprofeno, Naproxeno, Diclofenaco, Celecoxib) porque combaten directamente la inflamación del tejido que causa la irritación nerviosa.", "Analgésicos de venta libre: Paracetamol (acetaminofén) para calmar dolores somáticos óseos leves o moderados que no involucran inflamación aguda.", "Protocolo RICE para lesiones musculares agudas: Reposo (Rest), Hielo (Ice) en las primeras 48 hrs, Compresión y Elevación de la extremidad.", "Relajantes musculares (como ciclobenzaprina) para romper el ciclo de espasmos dolorosos en la espalda o el cuello.", "Fisioterapia y masajes profundos para restaurar la función, estirar músculos acortados e inhibir puntos gatillo (nudos musculares).", "Corticosteroides: Inyectados directamente en una articulación o tendón doloroso (como en una rodilla con artrosis o un hombro con bursitis) para proporcionar meses de alivio masivo.", "Opioides (tramadol, oxicodona): Se recetan rara vez y solo a muy corto plazo para un dolor somático postoperatorio extremo o por fracturas múltiples."] } ], note: "La aplicación de hielo reduce la inflamación aguda de un golpe reciente, mientras que el calor mejora el dolor somático crónico y muscular al fomentar la relajación." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Traumatólogo o Emergencias?", intro: "El dolor somático requiere intervención médica especializada rápida si:", items: ["El dolor proviene de un traumatismo y es imposible mover la extremidad, o existe una deformidad visual en el brazo/pierna (posible fractura luxada)", "El dolor muscular o articular intenso está acompañado de enrojecimiento masivo repentino, piel muy caliente y fiebre general alta (sospecha de infección grave en la articulación o la piel)", "El dolor de espalda es profundo tras una caída y se acompaña de incapacidad repentina para retener la orina o adormecimiento entre las piernas", "Un dolor agudo e inexplicable persiste en los huesos y lo despierta consistentemente por las noches"] } },
'Adherencia intraperitoneal' : { intro: "Las adherencias intraperitoneales son bandas anormales de tejido cicatricial denso que se forman dentro de la cavidad abdominal. Actúan como una cinta adhesiva interna, uniendo órganos que normalmente son resbaladizos y móviles (como asas intestinales o el útero) a la pared abdominal o entre sí, lo que puede causar dolor pélvico crónico u obstrucciones digestivas severas.", whatIs: { title: "¿Qué son las Adherencias Intraperitoneales?", text: "Son cicatrices fibrosas en el peritoneo (la membrana interna que rodea los órganos abdominales). Ocurren como respuesta del sistema inmunológico a daños previos. Normalmente, los órganos abdominales se deslizan entre sí suavemente; las adherencias los pegan firmemente, impidiendo que el intestino se mueva y contraiga con normalidad." }, symptoms: { title: "Síntomas Abdominales e Intestinales", intro: "Muchas personas tienen adherencias postquirúrgicas sin síntomas, pero cuando se vuelven restrictivas causan:", groups: [ { name: "Síntomas de dolor pélvico o abdominal crónico", items: ["Dolor abdominal vago, sordo o persistente que a menudo ocurre cerca de una cicatriz quirúrgica antigua o alrededor del ombligo", "Dolor punzante o tirante profundo al estirarse bruscamente, girar el torso o cambiar de postura", "Dolor pélvico intenso en mujeres, a menudo empeorando durante la ovulación o durante el sexo profundo (dispareunia)"] }, { name: "Síntomas de Obstrucción Intestinal (Bandera Roja)", items: ["Dolor abdominal tipo cólico, insoportable y en forma de olas o espasmos muy fuertes", "Distensión (hinchazón) abdominal muy severa y dolorosa, acompañada de náuseas agudas", "Vómitos repetidos repetitivos de alimentos o líquidos biliosos verdosos", "Incapacidad abrupta y total para evacuar heces o liberar gases anales (íleo paralítico u obstrucción)"] } ], warning: "Una obstrucción intestinal causada por un intestino estrangulado por una adherencia es una emergencia médica letal si no se opera rápidamente, ya que el tejido intestinal comenzará a pudrirse (isquemia)." }, types: { title: "Consecuencias Ginecológicas y Digestivas", intro: "El impacto de estas bandas cicatriciales depende del órgano que terminen uniendo:", items: ["Adherencias intestinales: Causan el 60-70% de todas las obstrucciones del intestino delgado en adultos; el intestino se 'tuerce' alrededor del tejido cicatricial como una manguera acodada.", "Adherencias pélvicas ginecológicas: Frecuentes tras cesáreas u operaciones en ovarios. Pegan las trompas de Falopio al útero o intestinos.", "Infertilidad mecánica femenina: Si la adherencia bloquea o retuerce las trompas de Falopio, el óvulo no puede descender ni los espermatozoides pueden subir, impidiendo la concepción natural.", "Adherencias del hígado/vesícula (Síndrome de Fitz-Hugh-Curtis): Bandas cicatriciales tipo 'cuerdas de violín' que causan dolor agudo en la parte superior derecha del vientre."], note: "El riesgo de formar adherencias pélvicas severas aumenta dramáticamente con cada cirugía abdominal sucesiva que el paciente tenga." }, causes: { title: "Causas Quirúrgicas y Factores de Daño Tisular", intro: "Cualquier inflamación o lesión grave dentro del espacio intraperitoneal provoca esta cicatrización desordenada:", items: ["Cirugías abdominales y pélvicas previas (la causa en más del 90% de los casos sintomáticos). Apendicectomías, histerectomías, cesáreas, cirugías de extirpación de vesícula o de colon.", "La técnica quirúrgica (como dejar sangre seca en el abdomen, el roce prolongado de órganos o dejar suturas) fomenta la cicatrización fibrosa reactiva.", "Enfermedades inflamatorias severas no tratadas: Apendicitis reventada, diverticulitis con perforación, peritonitis, o Enfermedad de Crohn severa.", "Endometriosis: Enfermedad en mujeres donde el tejido uterino sangra dentro del abdomen, provocando una masiva y severa inflamación cicatricial que fusiona múltiples órganos pélvicos ('pelvis congelada').", "Infecciones abdominales profundas: Enfermedad Inflamatoria Pélvica (EIP) provocada por infecciones de transmisión sexual (clamidia/gonorrea) crónicas no tratadas.", "Radioterapia abdominal pélvica extensa aplicada para destruir cáncer."] }, diagnosis: { title: "¿Cómo se Evalúan y Descubren?", intro: "Son difíciles de diagnosticar porque el tejido fibroso de la cicatriz no es visible en radiografías ni ecografías comunes:", items: ["Revisión del historial quirúrgico: El diagnóstico a menudo se asume si el paciente tiene cicatrices de cirugías abdominales y ahora presenta dolor crónico u obstrucción inexplicable.", "Tomografía Computarizada (TC) de abdomen con contraste: Aunque no muestra las adherencias delgadas directamente, muestra de manera contundente la obstrucción, el asa intestinal inflamada y el lugar exacto del 'acodamiento' del intestino.", "Tránsito intestinal o radiografías de tórax/abdomen: Para ver los niveles líquidos y de aire que confirman que hay un atasco intestinal (íleo).", "Histerosalpingografía (HSG) o ecografía ginecológica para mujeres infértiles, buscando trompas bloqueadas.", "Cirugía Laparoscópica de exploración: El único método diagnóstico definitivo, seguro y 100% concluyente. El cirujano inserta una cámara en el abdomen para mirar en alta definición las bandas de cicatrices y los órganos unidos."], note: "Los médicos a menudo diagnostican las adherencias solo por exclusión, una vez que han descartado todas las demás afecciones gastrointestinales (como úlceras o tumores)." }, treatment: { title: "Manejo Quirúrgico (Adhesiólisis) y Dieta Preventiva", intro: "La paradoja médica es que la cirugía se usa para cortar las adherencias, pero la cirugía en sí misma puede causar más adherencias en el futuro:", subsections: [ { title: "Aproximaciones al tratamiento", items: ["Observación y manejo conservador: Si el bloqueo es parcial o la persona sufre crisis leves esporádicas. Se receta ayuno, rehidratación intravenosa en el hospital y una dieta permanente baja en fibra insoluble (para que los alimentos pasen fácilmente por áreas estrechas) junto con reposo intestinal mediante sonda nasogástrica para descomprimir.", "Cirugía de Lisis de Adherencias (Adhesiólisis laparoscópica): Procedimiento electivo o de emergencia. El cirujano corta y libera cuidadosamente las bandas de tejido fibroso usando pequeñas incisiones para liberar las tripas u órganos reproductivos inmovilizados, mejorando el dolor pélvico severo o la infertilidad de inmediato.", "Cirugía de resección intestinal (urgencia extrema): Si la adherencia bloqueó y estranguló el intestino por muchas horas, el tramo de intestino isquémico y muerto debe extirparse para salvar la vida del paciente.", "Medidas preventivas en quirófano: Durante la adhesiólisis, el cirujano moderno aplica barreras antiadherentes especiales (láminas o mallas de hidrogel bioabsorbibles como Seprafilm) entre los órganos al terminar la operación, en un intento de evitar que el tejido crudo y cortado se vuelva a fusionar mientras sana."] } ], note: "Solo se opta por cortar quirúrgicamente las adherencias (adhesiólisis) cuando causan obstrucción del intestino, limitan críticamente la fertilidad de la mujer o el dolor crónico es intratable." }, whenToSeekHelp: { title: "¿Cuándo Acudir Rápidamente a Emergencias Quirúrgicas?", intro: "Es estrictamente una emergencia si alguna vez ha tenido cirugía abdominal y de pronto desarrolla:", items: ["Una interrupción violenta de sus movimientos intestinales (no ha podido pasar ningún gas, flatulencia o deposición de heces durante un período mayor a 24 horas)", "Vómitos incontrolables y repetitivos, de color biliar (verde o amarillo oscuro), tras intentar comer o beber cualquier cosa", "Calambres o espasmos estomacales repentinos muy agudos en oleadas de dolor insoportable y constante", "Una distensión masiva repentina, notando que el estómago se hincha visiblemente, tenso y rígidamente duro de palpar"] } },
'Candidiasis vaginal' : { intro: "La candidiasis vaginal es una infección fúngica extremadamente común e inofensiva pero sumamente irritante. Afecta hasta al 75% de las mujeres en algún momento de sus vidas, provocando una picazón intensa, enrojecimiento vaginal y un flujo espeso y blanco grumoso. Se trata fácilmente con antimicóticos de corta duración.", whatIs: { title: "¿Qué es la Candidiasis Vaginal (Infección por levaduras)?", text: "Es una vaginitis (inflamación de la vagina y la vulva) causada por el crecimiento excesivo de un hongo microscópico llamado Candida, más frecuentemente *Candida albicans*. Este hongo vive naturalmente y en paz en la flora vaginal normal de la mayoría de las mujeres sanas, pero problemas u hormonas pueden hacer que se multiplique fuera de control." }, symptoms: { title: "Síntomas, Ardor y Características del Flujo", intro: "Los síntomas de una infección por hongos son locales, limitados a la región vulvovaginal, y suelen empeorar en los días previos a la menstruación:", groups: [ { name: "Irritación vulvar y dolor", items: ["Picazón o comezón (prurito vulvar) extremadamente intensa en la vulva y en el exterior de la vagina (el síntoma más característico y molesto)", "Enrojecimiento brillante, hinchazón y piel agrietada en la zona íntima de la vulva", "Sensación de fuerte ardor abrasador, especialmente al intentar orinar o durante las relaciones sexuales (dispareunia)", "Dolor general y malestar pélvico superficial o sensibilidad vulvar constante"] }, { name: "Alteraciones inconfundibles del flujo vaginal", items: ["Aparición de un flujo vaginal abundante, muy espeso, blanco y grumoso, que tiene la apariencia de queso cottage o requesón", "El flujo de la candidiasis *NO* huele mal; usualmente no tiene olor (o un levísimo olor a levadura de pan). Si el flujo tiene mal olor a pescado, indica otra infección vaginal (vaginosis)"] } ], warning: "Si los síntomas son severos al punto de causar pequeñas fisuras o llagas sangrantes en la vulva por rascarse masivamente, o si tiene cuatro o más infecciones documentadas en un año, se trata de una candidiasis recurrente y complicada que necesita tratamiento oral prolongado." }, types: { title: "Infecciones Simples y Complicadas", intro: "Los médicos catalogan el caso en dos niveles para establecer si necesita cremas o tratamiento agresivo:", items: ["Candidiasis no complicada (90% de los casos): Síntomas típicos (leves a moderados), ocurren raramente o de forma aislada, son causadas por *C. albicans*, y ocurren en una mujer con sistema inmunológico fuerte. Responden casi de inmediato al tratamiento corto.", "Candidiasis complicada (severa o recurrente): Episodios muy dolorosos que causan cortes vulvares e hinchazón roja masiva; la mujer padece más de 4 episodios en un año (Vaginitis candidiásica recurrente); afecta a mujeres embarazadas, diabéticas con nivel alto de azúcar, inmunodeprimidas, o está causada por una cepa de hongos muy resistente llamada *Candida glabrata*."], note: "La candidiasis vaginal NO se considera una Infección de Transmisión Sexual (ITS). Las mujeres sin vida sexual activa pueden desarrollarla." }, causes: { title: "Causas y Desencadenantes Comunes del Crecimiento Fúngico", intro: "El hongo Candida toma el control cuando la cantidad de bacterias protectoras 'buenas' de la vagina (lactobacilos) muere o el ambiente ácido se desequilibra:", items: ["Uso reciente de antibióticos de amplio espectro: Destruyen las bacterias buenas naturales y fuertes del cuerpo, permitiendo al hongo colonizar las paredes vaginales (causa abrumadoramente frecuente).", "Aumento extremo del nivel de estrógeno y alteraciones hormonales: Durante el embarazo, en mujeres tomando tratamientos de reemplazo hormonal activo o píldoras anticonceptivas de altas dosis de estrógenos.", "Diabetes no controlada: La orina y las secreciones vaginales con altos niveles de azúcar proveen alimento directo y abrumador para el crecimiento masivo incontrolable de la levadura.", "Sistema inmunológico deprimido: Por altos niveles de estrés severo, quimioterapia, el uso crónico de esteroides médicos o infección por VIH.", "Mantenimiento de humedad y calor constante: Ropa interior de nylon muy ajustada, trajes de baño mojados de gimnasia puestos durante largas horas, almohadillas perfumadas o duchas vaginales innecesarias que destruyen el pH balanceado natural."] }, diagnosis: { title: "¿Cómo se Diagnostica Clínicamente?", intro: "Para episodios iniciales, el ginecólogo debe evaluar y no asumir que es cándida, usando:", items: ["Examen pélvico físico: El médico inspeccionará si la vulva está roja e hinchada y comprobará la presencia directa del típico flujo grumoso espeso blanco pegado al cuello del útero.", "Análisis de flujo o Montaje en húmedo vaginal: Se toma una muestra indolora del flujo y se mira a nivel celular en el consultorio bajo el microscopio (a menudo agregando solución de hidróxido de potasio KOH), donde las estructuras de hifas ('raíces' fúngicas) y esporas levaduriformes se revelan claramente de inmediato.", "Cultivo vaginal en laboratorio clínico: Si los episodios se repiten obstinadamente tras los tratamientos normales con fluconazol, se enviará una muestra fuerte al laboratorio durante unos días de cultivo para averiguar si se trata de una cepa de candida extraña resistente (ej. C. Krusei)."], note: "Es vital un primer diagnóstico formal, ya que los estudios muestran que hasta dos tercios de las mujeres que compran cremas en la farmacia auto-diagnosticándose, en realidad padecen de otras infecciones como la Vaginosis Bacteriana." }, treatment: { title: "Tratamiento Antimicótico Rápido", intro: "La curación es habitualmente rápida con el uso de antifúngicos (antimicóticos):", subsections: [ { title: "Soluciones de Farmacia y Médicas", items: ["Antimicóticos tópicos (cremas y supositorios intravaginales): Medicamentos azólicos como Miconazol, Clotrimazol o Terconazol, disponibles en la farmacia sin receta para casos simples. Vienen en regímenes nocturnos intensivos de uno, tres o siete días que se aplican dentro de la vagina y alivian los síntomas de ardor velozmente.", "Medicación antifúngica oral recetada: Una dosis única oral de pastilla de Fluconazol (Diflucan) recetada por el médico. Ojo: El Fluconazol de ingesta oral general está estrictamente contraindicado en mujeres cursando un embarazo, debiendo estas usar siempre obligatoriamente óvulos cremosos vaginales.", "Tratamiento y prevención a largo plazo para candidiasis crónica recurrente: Si hay 4 episodios o más en doce meses, el médico prescribirá un plan exigente que inicia con Fluconazol oral cada tres días al principio, seguido con dosis semanales orales preventivas durante los siguientes seis meses para limpiar totalmente las cepas enquistadas.", "Terapia de control básico diabético general para reducir permanentemente y mantener la hemoglobina glicosilada al mínimo y cortar el 'alimento' base recurrente constante al agresivo hongo vulvar vaginal.", "Sustitución o ajuste fuerte de pastillas anticonceptivas con alto contenido estrogénico."] } ], note: "Aunque los síntomas pruriginosos pueden aliviarse al final del primer o segundo día del tratamiento en cremas vaginales de varios días, se debe completar estrictamente toda la caja o dosis requerida recetada." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Ginecólogo o Consulta Médica?", intro: "Es obligatorio solicitar diagnóstico y evitar automedicarse tratamientos comerciales si:", items: ["Es su primer ataque y episodios de flujo con picazón de la zona íntima (para asegurarse definitivamente del diagnóstico correcto de un hongo micótico y no otra ITS u otras vaginitis bacterianas)", "Las cremas comunes de farmacia comercial para candidiasis fueron aplicadas, pero usted nota síntomas de ardor persistente después del final al concluir el tratamiento completo sugerido", "Usted nota una descarga vaginal masiva de tonalidad amarilla clara verdosa u olor fuerte tipo putrefacto de pescado a amoníaco o está sufriendo síntomas febriles generales", "Usted está cursando un cuadro general y un embarazo comprobado"] } },
'Infección de las vías urinarias (IVU) en adultos' : { intro: "Una infección de las vías urinarias (IVU) ocurre cuando gérmenes microscópicos invasores, principalmente bacterias, ingresan por la uretra y se multiplican agresivamente en el sistema urinario estéril. Aunque las IVU de la vejiga son extremadamente dolorosas con la necesidad constante de orinar, pueden volverse críticas si la infección asciende velozmente hacia los riñones, causando daño o sepsis bacteriana en sangre.", whatIs: { title: "¿Qué es una Infección del Tracto Urinario (IVU)?", text: "Es una infección patológica que afecta cualquier parte del sistema urinario: la uretra (uretritis), la vejiga (cistitis), o los uréteres y los riñones (pielonefritis). Las mujeres tienen un riesgo masivamente mayor de desarrollarlas porque su uretra es significativamente más corta y está muy cerca del orificio anal, facilitando el tránsito bacteriano a la vejiga." }, symptoms: { title: "Síntomas Agudos, Dolor al Orinar y Urgencias", intro: "Los síntomas inferiores son irritantes e inconfundibles en su inicio, pero varían y se vuelven generalizados cuando ascienden a los riñones:", groups: [ { name: "Síntomas del tracto inferior (Vejiga / Cistitis)", items: ["Sensación y escozor ardiente o ardiente dolor punzante al final y al intentar orinar (Disuria, síntoma más universal)", "Urgencia repentina y extrema de ir al baño que aparece inmediatamente, incluso cuando la vejiga contiene solo unas gotas", "Frecuencia urinaria de vaciado agudo de gota a gota a cada instante u hora del día en el inodoro", "La orina se presenta con un aspecto fuertemente turbio, espeso o de un mal olor asqueroso inusual parecido al amoníaco", "Aparición notable en retrete o papel al limpiar de sangre (orina color rosado rojo - hematuria) originada por el sangrado interno profundo de la irritación de la mucosa y calambres abdominales sordos en el bajo vientre justo en la pelvis femenina"] }, { name: "Señales superiores Críticas (Infección de Riñones / Pielonefritis aguda)", items: ["Fiebre súbita que puede superar o rondar los 38°C (101°F) o más", "Escalofríos intensos profundos o con sacudidas bruscas incontroladas sistémicas y corporales generales", "Náuseas generales persistentes en el tiempo u con episodios fuertes repetidos de vómitos gástricos de base", "Dolor unilateral punzante sordo contundente focalizado y grave en todo un lado superior en espalda y del costado (en ángulo costovertebral debajo rígidamente al centro de las costillas y riñones de flanco dorsal lumbar intenso)"] } ], warning: "La aparición abrupta repentina simultánea a la fiebre junto al dolor agudo de la zona espinal lumbar espalda de los flancos acompañado a debilidad confusión e incapacidad de caminar implica una pielonefritis renal con peligro latente grave y requiere administración fuerte de antibióticos intravenosos masivos general hospitalarios inmediatos." }, types: { title: "Clasificación por Gravedad, Ubicación en Anatomía Urinaria", intro: "Dependiendo anatómicamente del tramo en el que han infestado las bacterias de manera patológica, la denominación, el riesgo real o potencial en su tracto y tratamiento varían considerablemente en riesgo crónico de peligro:", items: ["Uretritis (Inferior): Afectación infecciosa aislada aguda en la uretra exterior donde sale orina (usualmente de ITS como micoplasma).", "Cistitis simple u Infección Urinaria Inferior Base: Un episodio leve a moderado y súper común general que causa molestias general de infección bacteriana general localizada de presión dolor puro de pared a toda nivel base o de la pared en la vejiga interna donde reposa temporal orina y evacua a corto o sin afectar ni dañar u o avanzar y presentar riesgo a la fiebre o vías sistémicas del riñón y a curar sin falla (La IVU no complicada a resolver habitualmente en su mayoría y de días con medicina en caso clásico general de sexo de mujeres).", "Pielonefritis (IVU Superior Complicada o Aguda Urgente Pediátrica/Adultos y en Gestantes o Diabéticas): Severísima patología muy seria por propagación al migrar retrograda de invasión general al flujo a tubos hacia u ascendido al u de sistema renal pélvico de uno a o ambos generalizado al riñón interior a u y filtrado y tejido a causa de que los síntomas e hinchazón causan riesgo profundo de shock del sistema.", "Infección recurrente, de repetitivas o Cistitis a la repetición crónica general femenina de cuadro bacteriano profundo por reinfección bacteriana resistente (mujeres o cuadro general del más en número tres veces aisladas documentadas a todo nivel año)"], note: "En pacientes mayores ancianos que sufran deterioro crónico profundo o demencia, una inusitada agitación abrupta o letargo o extrema y un súbito delirio de desorientación alucinatorios nocturnos muy inexplicables en sus mentes repentinos suelen, de manera llamativa ser por la infección subyacente silenciosa sin más dolor clásico general u urinario presente que deban curar por IVU oculta a ancianos." }, causes: { title: "Bacterias, Anatomía del Factor a Exposición Desencadenante Infecciosa de Causas Invasivas", intro: "Se desarrollan e inician exclusivamente cuando las potentes cepas de bacterias gastrointestinales propias reubican u y cruzan su sitio seguro u general colónico logrando escalar agresiva u la vía u a multiplicarse en orina aséptica de entrada por u orificio uretral u general exterior:", items: ["Bacteria patológica gastrointestinal Escherichia coli o (E. coli): Microorganismo bacteriano de procedencia general a ser la abrumadora o más grande de casi 80 a o de causa exclusiva u 90 por de infección y patógeno a migrar la vejiga e inflamando de origen intestinal normal anal pero u de causar la gran inflamación destructora al instalarse en ambiente urinario invasor.", "La intensa actividad u general en coito o sexual en mujer de fricción intensa repetida a introducir u base (comúnmente o llamada la Cistitis inicial y de etapa de luna miel u recién u donde facilita arrastre o ingreso bacterial al tracto corto exterior anal externo vaginal).", "Mala higiene de baño de atrás adelante en su arrastre u al evacuar hacia las extremidades delanteras vulvares o el u no beber abundantes líquidos a lo a largo el día para diluir el material concentrado impidiendo una correcta base general al lavado natural continuo arrastre diario por dilución uretral constante en la limpieza del vaciado del tracto vesical a exterior expulsivo protector al u o patógenos.", "Uso por o prolongado a causa crónico base médico o y u colocaciones hospitalarias de u catéter y postración intubada a de la de urinario sondas de drenaje externas insertadas (foco frecuente en hospitales a IVU y origen patológico letal para el anciano o quirúrgico base nosocomial general en sangre de sepsis).", "Condiciones físicas e interferencias urinarias: Cálculo riñón, la próstata muy fuertemente agrandada prostática (HPB u bloqueo del varón base el cual del que estanca peligrosamente general el volumen urinario completo que incita caldo en vejigas de cultivo bacteriano patógeno general agudo letal de residuo u orina crónica o infección y postraumática obstructiva basal a causa u o base de vaciado débil neurológico diabético general crónico) o alteración severa atrofia vulvar sin moco post menopáusica estrogenica reduciendo de protección general biológica."] }, diagnosis: { title: "¿Qué Exámenes Y Controles Médicos Detectarán Rápidamente la Bacteria Urinaria Exacta de Muestreo Fuerte?", intro: "Para iniciar un fármaco y o a terapia de descarte de forma basal segura, efectiva y o sin resistencia y detectar en emergencia base a curar la bacteria que provoca y ataca el tracto es fundamental proceder o sin dar y receta ciegamente con un procedimiento de:", items: ["Análisis Examen General Básico Rápido Tira (Examen microscópico en Orina u de EGO rápida y urinario completo en de emergencia base leucocito). Con su muestra al orinar buscando confirmar y en orina rastros y o a concentraciones evidentes elevadas obvias u anormalmente a la nitritos y células y defensas como glóbulos u o glóbulos inflamatorios o blancos de sangre general al cuerpo reaccionando a combatir.", "Urocultivo o el Examen Oro Fidedigno del Análisis de Laboratorio Sembrado Completo: Sembrar y realizar a dejar crecer el u su cultivo del frasco orina recogida limpia técnica estricta al laboratorio de cultivo con discos un par para aislar de de bacterias por tiempo y de a nivel preciso general con Antibiograma que dictaminará formalmente el patógeno con qué especie de antibiótico exacto aniquilará a cepas de ese del individuo para asegurar no haya resistencia peligrosa medicamentosa en la pastilla prescripta final.", "La evaluación inicial o Ecografía abdominal y pélvica renal de nivel a de a riñón y a vejiga por imagenologia o radiográfica TC para o a las buscar descartando u para descartar obstrucciones anatómicas masivas agudas u malformaciones riñón general si ocurren o a recurrencias u el caso basal muy reiterativas más crónica a base general infantil y hombres o en niño pequeño en su cuadro base o de una obstrucción u prostática a u o de litiasis general.", "Cistoscopia visual en las recurrentes de mujeres repetidas o crónicas dolorosas: Otorga al médico visual con sonda interna el diagnóstico basal del interior de la inflamación del forro y mucosa e inspeccionar para de u interior visual u un dolor pélvico inflamatorio de u crónico del u a por de cuadro dolor ginecológico u vejigas intersticial si antibiótico de u la cultivo dio falsos y negativos generales en la orina sin crecimiento repetido por semanas de la sintomatología pero de ardor presente."], note: "El recipiente de orina, antes, se debe e instruir su de la limpieza técnica obligatoria el de o a tomar chorro del chorro final y no la de iniciar, limpiar de a vulva labios externa inicial y o a base en hombre prepucio base en de a evitar falso u bacteriano contaminación u vaginal que falsearía del a general diagnóstico final en su placa analítica médica del u u laboratorio patológico general en un o paciente sin síntomas urinarios." }, treatment: { title: "Antibioticoterapia de Choque Farmacológico Oral Rápida O Intravenosa en Emergencias a Tratamientos Hidratantes Frecuentes, Para y Alivio y la Cure Prevención y Manejo Del Cuadro Infeccioso", intro: "La recuperación e inicio curativo a lo de días de cuadro o basal y depende a general del control general o del nivel base en zona anatómica u si se prescribe de lo de su antibiótico para sanarla al de fondo u a y general:", subsections: [ { title: "Planes Base Sistémicos Generales Agudos, Prescripción Farmacológica a Seguir o Cistitis o Para Infecciones Pielonefritis Recurrentes Superiores A Combatir y Urológico", items: ["Curso Farmacológico General de o Primera Antibioticoterapia recetada u línea estándar oral a corto y general del esquema u empírico (Tres a días o a los o de una cinco a y como a semana base): Uso a la a primera base u de medicamentos e antibióticos y fluoroquinolonas u Nitrofurantoína oral rápida general, el y Sulfametoxazol, fosfomicina en sobre o trimetoprima con el para y exterminar las en cepas base comunes del u e inferior de vejiga de a la de primera al a en urgencias y o consulta ambulatorio u y en caso basal u general de respuesta si del al y y sin un dolor en riñones general grave en un caso de orina o paciente normal con cultivo o ambulatoria y o e ITS y general sin complicación severa o a y basal.", "Medicación antiespasmódica Analgésica Urinaria Tópica Anestésica para dolor de urgencias e (Fenazopiridina genérica del Phenazo, Pyridium): Pastillas para el u dolor agudo u a adormecer general e adormece a y y o paraliza y u el quemazón de dolor o o ardor del u forro vesical para y o calmar de síntomas rápidos iniciales ardientes o a orinar mientras a antibiótico surte el ataque basal u de alivio en primeras y la del horas a tomarlo a en un de urgencia u en días (nota médica: teñirá del tinte color fluorescente fuerte orina a naranja fosforescente a inofensivo fuertemente en su el en retrete o de manera basal muy asustadizo pero muy normal al excretarla u general por paciente a las o un horas u días en cuadro general al dolor a curarse o al evacuar a u nivel del fármaco).", "Administración endovenosa u e hospitalización a e general de base urgente en u antibiótico inyectable intravenosa a dosis y amplio general en a gran dosis agresiva suero a urgencias u a de manera u: Por si general de u infección pielonefritis renal basal ya afectó u al por dolor fiebre el estado general en e riñón y fiebre vómitos basal para o mujeres por embarazos muy severos infecciosos u si a a general sufre diabéticos para y de su cura o que amenace o ancianos por con cuadro u su septicemia shock basal inminente general sistémico incontrolable severo.", "Incremento basal general a abundante extremo u por ingesta para vaciado y beber líquido basal continuo (muy alta u del ingesta de para agua pura e la del líquido abundante natural del y u o del en y arándanos al jugo u cápsulas de cranberry extracto concentrado para no su evitar si de a general adherencias recurrente e general para el ayudar y expulsión arrastrando la y u en el u lavar la de u u vejiga pared en general la limpieza natural orina sin aguantar o urgencias o a vaciar frecuente u sin y sin u base del y retrasos y en o al del nivel base y general al la día y prevenir o a posteriores si es general y en y la paciente de con profilaxis de un recetado profiláctico a uso basal prolongado meses o a estrógenos de pomadas si post edad general menopausia aguda severa u a la zona externa vulvar ginecológica u basal o del y en u nivel vaginal a recuperar mucosa del tejido biológico barrera o)."] } ], note: "Por leve u y lo que al segundo parezca curado el o u un del y o del síntoma debe o u a terminarse estrictamente todo la a base o y la píldora u receta caja antibiótica completa general o la por y para e general en y sin base suspender el o un a al sentir la mejoría al o y y sin duda al y el para del general del a evitar recurrencias del a resistente al o y generar de bacterias crónica aguda y peligrosa basal a u del cuadro super resistente la infección basal de mes al a u de general a futuro médico u de la vía o a riñón urinario y de un en del general paciente o para el sano u alivio definitivo o y de salud." }, whenToSeekHelp: { title: "¿Cuándo Contactarse de la Emergencia Rápido al Nivel del u O Llamar A Su Un o Al Servicio U O Especialidad Médica a o Urgente De Médicos u Diagnóstico y Cita a Urgencia De Evaluar por Riesgos en la Sintomatología Inicial y General?", intro: "Lleve del o u pida atención a u de urgencias médicas hospital inmediata, sin u a esperar a y a o u general la base a consulta a un día médico o general u urgencias si la y en o al de u la orina de sufre al percibir un cuadro y se agrava:", items: ["Percibe, orina repetidamente sangre obvia al retrete con dolor u y experimenta u ardiente muy cortante como e u y cristales aguda que u lo le despierta o incapacita del al de vaciado para u en dolor o seguir a de base vida en y al instante de general del de la de ardor sin ceder general dolor y con dolor punzante en inferior del en vejiga y abdomen o pélvico o del pelvis del en y u de bajo constante u en u la general en urgencia muy constante sin y sin dolor de parar a de cese a general en la la en urgencia basal en de a y general y u el vaciar pero no al en nada y con o del salir orina.", "El adulto un mayor o la persona anciano en su u anciano cuidado comienza inusualmente y con u una de e confusión u delirium al o agitado sin base del razón brusca e en y letargo total de mental abrupta al en cama (debe descartarse a las orina general infección grave oculta de a bacteriemia a la y urgencias sin duda a y de y al cuadro en de ancianos u del asintomáticos a el o con incontinencias o febriles general en demencias al de sin que al u y u manifiesten el clásico urgencia por sí).", "Tiene en dolor el general dolor e dolor punzante u de a opresivo a unilateral de en en o el a todo flanco al del nivel espalda, escalofríos al temblores por tiritona del y fiebre en alta en el base aguda vómitos y constante general malestar e severo y a la fiebre al nivel en los por las a sobre en a base más al o en y general los a temperatura superior u general por 38 o a y del nivel en y y de pielonefritis basal sospechosa muy aguda y crítica sistémica a la vida a curar a en su nivel por su u o su hospital a ingreso de vena al de hospital por urgencias general del a vida y a a o general en y nivel renal del base en y en horas."] } },
'El tartamudeo y los niños' : { intro: "El tartamudeo infantil, conocido médicamente como disfemia, es un trastorno temprano de la fluidez del habla en el cual el niño sabe exactamente qué quiere decir, pero el flujo natural y continuo de sus palabras se interrumpe por bloqueos, prolongaciones o repeticiones de sonidos. Suele aparecer entre los 2 y los 5 años, una etapa de explosión del vocabulario, y aunque causa gran preocupación a los padres, a menudo es una fase transitoria de desarrollo.", whatIs: { title: "¿Qué es el Tartamudeo en los Niños?", text: "Es una alteración neuromotora involuntaria en el ritmo y la cadencia del habla. El niño repite sonidos o sílabas (co-co-como), estira vocales (mmmi gato), o sufre 'bloqueos' silenciosos donde se queda atascado, sin poder emitir la palabra a pesar del esfuerzo físico evidente." }, symptoms: { title: "Síntomas y Comportamientos de la Disfemia", intro: "Los signos van más allá de la disfluencia y a menudo se acompañan de estrés físico visible al intentar comunicarse:", groups: [ { name: "Síntomas directos del habla", items: ["Repeticiones de palabras de una sola sílaba ('yo-yo-yo quiero')", "Prolongaciones audibles de sonidos específicos al inicio de la palabra ('sssssapo')", "Bloqueos tensos antes o en medio de una palabra (el niño abre la boca, pero no sale sonido)", "Uso de muletillas (eh, um) o evitación de ciertas palabras largas cambiando el vocabulario para ocultar el tartamudeo"] }, { name: "Comportamientos secundarios (Tensión o Frustración)", items: ["Signos de esfuerzo extremo en el rostro al intentar sacar una palabra, como parpadear rápidamente", "Tics motores, temblores en los labios o mandíbula, apretar los puños o mover la cabeza bruscamente acompañando el bloqueo del habla", "Aparición de ansiedad, frustración o llanto al hablar, llegando a la negativa total o silencio si se siente presionado", "Aumento severo del tartamudeo únicamente bajo estados de estrés, fatiga profunda, emoción extrema o cuando intenta hablar muy rápido para que no lo interrumpan"] } ], warning: "Corregir al niño bruscamente, pedirle que 'respire profundo' o burlarse, agravará severamente su ansiedad por hablar y convertirá una tartamudez transitoria del desarrollo en un problema crónico psicológico persistente." }, types: { title: "Evolución y Tipos de Disfluencias", intro: "Es fundamental diferenciar entre el tartamudeo que necesita tratamiento y el que es parte del desarrollo normal:", items: ["Disfluencia típica del desarrollo (Tartamudeo evolutivo transitorio): Es sumamente normal. Ocurre entre los 2 y 5 años cuando las ideas del niño fluyen más rápido de lo que sus pequeños músculos del habla pueden coordinar. Suelen repetir palabras enteras, NO hay bloqueos tensos faciales, el niño no se da cuenta y generalmente desaparece solo en menos de 6 a 12 meses.", "Tartamudez persistente: El niño lucha visiblemente con los sonidos y muestra bloqueos fijos y repetición de letras individuales ('p-p-p-perro'). Puede prolongarse hasta la escuela primaria si no se interviene.", "Tartamudeo neurogénico: Causado por una afección médica cerebral abrupta, como un accidente cerebrovascular, traumatismo craneoencefálico, que daña las redes neuronales responsables del lenguaje (muy raro en niños sin trauma).", "Tartamudeo psicógeno: Aún más raro, aparece repentinamente después de un trauma emocional agudo y devastador."], note: "Más del 75% de los niños pequeños que atraviesan una fase de disfluencia del desarrollo se recuperan natural y completamente sin ninguna terapia especializada en unos meses." }, causes: { title: "Factores Causales y Orígenes Neurobiológicos", intro: "La tartamudez no está provocada por la ansiedad de los padres, ni por ser un niño 'nervioso'. Es de base biológica:", items: ["Genética (El factor de riesgo más poderoso): Alrededor del 60% de los niños que tartamudean tienen un familiar cercano que también tartamudea o lo hizo en la niñez. Si continúa después de la niñez temprana, la heredabilidad juega un gran papel.", "Diferencias en el procesamiento neurológico: Los escáneres cerebrales en niños con disfemia persistente muestran que procesan el lenguaje y controlan el área motora en el hemisferio del cerebro de una manera ligeramente diferente y menos coordinada (las vías cerebrales motoras y del habla no se comunican de forma impecable y rápida).", "Desarrollo rápido y asíncrono en la primera infancia: El nivel cognitivo y el enorme vocabulario que el niño adquiere supera sus habilidades motrices bucales y laríngeas que aún son inmaduras para sostener la ráfaga verbal.", "Dinámicas de vida estresantes y ambiente (Un agravante, no una causa): Las mudanzas, el nacimiento de un hermano, conflictos en el hogar, o padres que hablan a un ritmo extremadamente acelerado a su alrededor exacerban el tartamudeo biológico subyacente."] }, diagnosis: { title: "¿Cómo se Evalúa Diagnósticamente al Niño?", intro: "El especialista y patólogo del habla-lenguaje (logopeda o fonoaudiólogo pediátrico) lo examina mediante juego y observación interactiva:", items: ["Evaluación e historial clínico profundo junto a los padres: Indagando exactamente cuándo empezaron las interrupciones, la frecuencia exacta, si hay antecedentes familiares idénticos, y cuánto ha durado el período (más de 6 meses es una bandera roja para no esperar).", "Análisis de las muestras y patrones del habla: Grabar y analizar el habla natural del niño contando un cuento, enumerando elementos, o respondiendo preguntas bajo leve estrés cognitivo, anotando el tipo predominante exacto de disfluencia (repetición vs bloqueo físico) y calculando la tasa porcentual en sus discursos.", "Evaluación minuciosa de las reacciones conductuales emocionales secundarias del menor frente a sus bloqueos al trabarse frente al examinador (para comprobar si ya ha desarrollado miedo social u obstinación física en sus labios).", "Exámenes para determinar la capacidad de inteligencia, el lenguaje articulatorio en general, su nivel global de comprensión oral del idioma, el rango de su extenso y receptivo vocabulario comparativo a sus pares, además del descarte formal final neurológico de otros déficits o trastornos fonológicos cruzados y del comportamiento asociado (como TDAH en la niñez temprana)."], note: "En un niño que apenas comienza con signos leves y no tiene dolor emocional al respecto, la actitud principal diagnóstica es el abordaje conservador llamado de 'espera vigilante' activa mensual por al menos un año preescolar." }, treatment: { title: "Apoyo, Intervención y Terapias Logopédicas", intro: "No existe cura o pastilla milagrosa, pero la intervención temprana especializada o logopédica proporciona una asombrosa efectividad de mitigación antes del inicio de etapa de grado primario de educación social escolar:", subsections: [ { title: "Entrenamiento directo infantil, programas e instrucciones para el núcleo de padres", items: ["Terapia y Entrenamiento Directo del Habla en sesión interactiva (Enfoque Fluidez Modelada): Un terapeuta del lenguaje ayuda profundamente al pequeño mediante juegos a aprender lentamente y modificar físicamente cómo él produce e inicia sus sonidos (utilizando inicios del aliento vocal relajados suaves, un habla más paulatina lenta, un uso fácil e indoloro y contacto de labios y control sutil laringeo para desaprender tics tensionales bloqueantes fijos frente a bloqueos en pánico).", "El abordaje Terapéutico Indirecto TCC e Instrucción (Programa o Método de Palin o programa integral Parent-Child Interaction - Lidcombe en el Reino Unido): Los logopedas no intervienen directo presionando al niño; intervienen en entrenar exhaustiva e ininterrumpidamente a sus padres sobre cómo modificar sus propias velocidades al hablar en el hogar todos los días, utilizar frases en ritmos extremadamente muy cortas, pausadas sin urgencias para establecer un gran clima en casa y permitir que logren de esa manera ser ejemplo fluente para facilitar al sistema neuromotor del crío su ajuste neuronal espontáneo natural de maduración en casa libremente.", "Terapia de Aceptación o el enfoque de Asesoramiento Psicológico a futuro: Enseñar tanto como para padres a cómo manejar u responder ante las burlas y lidiar con ansiedades ante los atascos prolongados a nivel psicosocial que pueda enfrentar por los estigmas en grados mayores educativos para el éxito social sin culpa u obstáculo emocional."] } ], note: "La pauta o mejor regla sagrada central para todo padre en el hogar durante este episodio es la escucha constante de su hijo manteniendo siempre firme e imperturbable el gran y atento contacto ocular visual del ojo con él, sin impaciencia mientras esté trancado atascado o con bloques en la boca, sin terminar, adivinar o interrumpirle la oración completa." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Profesional, Pediatra y Derivar de Urgencias y Emergencias Al Fonoaudiólogo?", intro: "Intervenir rápidamente antes o a poco de comenzar los cursos en edad preescolar previene gran sufrimiento, busque ayuda u asista urgente si usted evalúa la tartamudez general en o del niño con signos y comportamientos de advertencias claras si ocurre:", items: ["El caso de una tartamudez biológica de disfluencia y su problema ha continuado presentándose ininterrumpidamente sin ninguna leve mejora y ha durado a lo o por bastante y a base a lo largo a la frecuencia de duración de persistencia mayor en total general a los seis a un año u a más los nueve y doce completos a un par o 6 o unos doce meses en tiempo continuado ininterrumpido a su edad base", "Si aparece y notan y si además su niño ya o comienza e inició y al comenzar en la primaria se retrasa a una etapa a mayor avanzada general a los 5 e inició a hablar tras años y no ha sido y no antes si aparece un y en una edad a más a los cinco y tres cinco años base o años base la primera la vez de niño (una base y alerta que a requiere terapia al de inmediato a o base)", "Muestra en gestos, o si su o el niño se frustra mucho, comienza o a frustrarse a o por enojarse agudamente muy y de reacciona a esquivar en y llora evitar u el llanto el para el nivel dejar el uso y en de a rechazo de hablar y de su nivel oral y e o e evitar palabras a nivel el lenguaje verbal para no a en su sufrir y trabarse frente o y en público el grupo", "Cualquier a y si u la a la del o aparición de cualquier rasgo un del súbito, a por e como y o por y el en niño la general el brusca en si por súbito del habla el con de una con dolor de general facial de por general y la musculatura la extrema u tensión y tics en ojo u a en espasmo a cabeza un o a base un brusco o de temblor en las a y músculos mandíbula"] } },
'Cálculos en el tracto urinario' : { intro: "Los cálculos en el tracto urinario, conocidos como 'piedras' en los riñones o vías urinarias, son depósitos duros de minerales y sales. Su paso por los estrechos conductos urinarios provoca el cólico nefrítico, uno de los dolores más agudos y agonizantes que existen en la práctica clínica.", whatIs: { title: "¿Qué es la Urolitiasis?", text: "Es la formación y acumulación de masas cristalizadas sólidas (litos) en los riñones, uréteres, vejiga o uretra. Se forman cuando la orina se concentra demasiado, permitiendo que los minerales (como calcio o ácido úrico) cristalicen y se unan." }, symptoms: { title: "Síntomas y el Cólico Nefrítico", intro: "Las piedras pequeñas pueden no causar síntomas, pero cuando se mueven o bloquean el flujo, provocan:", groups: [ { name: "Características del dolor", items: ["Dolor severo, punzante y repentino en la espalda, el costado o debajo de las costillas (cólico renal)", "Dolor que se irradia y desciende hacia la parte baja del abdomen y la ingle", "Dolor que viene en oleadas o espasmos y fluctúa en intensidad", "Imposibilidad de encontrar una posición cómoda para aliviar el dolor"] }, { name: "Síntomas urinarios y sistémicos", items: ["Sangre visible en la orina (hematuria), que puede verse rosada, roja o marrón", "Necesidad constante y urgente de orinar, o micción en pequeñas cantidades", "Sensación de ardor intenso al orinar", "Náuseas agudas y vómitos debido a la intensidad del dolor", "Fiebre y escalofríos (si hay una infección sobreagregada)"] } ], warning: "La combinación de dolor severo de riñón con fiebre alta y escalofríos es una emergencia médica, ya que indica una infección grave por el bloqueo." }, types: { title: "Composición de los Cálculos", intro: "Saber de qué está hecha la piedra es vital para prevenir futuras formaciones:", items: ["Cálculos de calcio (oxalato de calcio): Los más comunes, a menudo causados por dieta, altas dosis de vitamina D o trastornos metabólicos.", "Cálculos de ácido úrico: Comunes en personas que pierden mucho líquido, comen una dieta altísima en proteínas o tienen gota.", "Cálculos de estruvita: Se forman en respuesta a una infección del tracto urinario crónico y pueden crecer rápidamente y volverse gigantes (coraliformes).", "Cálculos de cistina: Muy raros, causados por un trastorno genético hereditario (cistinuria)."], note: "Guardar la piedra si se expulsa al orinar (usando un colador) es fundamental para que el laboratorio la analice." }, causes: { title: "Factores de Riesgo", intro: "Los cálculos se forman por un desequilibrio químico y de líquidos:", items: ["Deshidratación crónica (no beber suficiente agua es la causa principal)", "Dietas ricas en sodio (sal), proteínas animales y azúcares", "Obesidad y aumento de peso rápido", "Enfermedades digestivas o cirugía de bypass gástrico (alteran la absorción de calcio)", "Antecedentes familiares o personales de cálculos renales"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de emergencia busca confirmar el bloqueo y el tamaño de la piedra:", items: ["Tomografía computarizada (TC) sin contraste del abdomen: La prueba de imagen estándar y más precisa, detecta piedras diminutas y la dilatación del riñón.", "Ecografía renal: Muy usada y segura, aunque puede pasar por alto cálculos pequeños en el uréter.", "Análisis de orina para buscar sangre microscópica, cristales o bacterias de infección.", "Análisis de sangre para medir niveles de calcio, ácido úrico y la función renal."], note: "El tamaño de la piedra (medido en milímetros) dictará si el paciente puede expulsarla por sí solo o necesita cirugía." }, treatment: { title: "Opciones de Expulsión y Cirugía", intro: "El tratamiento depende del tamaño de la piedra y del dolor:", subsections: [ { title: "Manejo conservador (piedras pequeñas)", items: ["Beber de 2 a 3 litros de agua diarios para ayudar a expulsar la piedra", "Analgésicos potentes para soportar el proceso de expulsión", "Medicamentos alfabloqueadores (como la tamsulosina) para relajar los músculos del uréter y facilitar el paso de la piedra de forma más rápida y menos dolorosa"] }, { title: "Procedimientos para piedras grandes", items: ["Litotricia extracorpórea por ondas de choque (LEOC): Usa ondas sonoras intensas desde fuera del cuerpo para romper la piedra en fragmentos diminutos que se puedan orinar.", "Ureteroscopia: Se pasa un tubo muy fino con una cámara por la uretra y vejiga hasta el uréter para atrapar la piedra o romperla con láser.", "Nefrolitotomía percutánea: Cirugía mínimamente invasiva donde se extrae un cálculo muy grande directamente del riñón a través de un pequeño corte en la espalda."] } ], note: "Una vez expulsada, un nutriólogo o nefrólogo debe ajustar la dieta del paciente para evitar que se formen nuevas piedras." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Urgencias?", intro: "Debe buscar atención hospitalaria de emergencia si experimenta:", items: ["Un dolor tan agudo e implacable que no puede quedarse quieto o sentarse", "Dolor acompañado de náuseas repetitivas o vómitos incontrolables", "Dolor acompañado de fiebre y escalofríos intensos", "Sangre muy evidente o coágulos al orinar", "Dificultad o incapacidad total para orinar"] } },
'Ano imperforado' : { intro: "El ano imperforado es un defecto de nacimiento (congénito) en el que la abertura hacia el ano falta o está bloqueada. Es una malformación anorrectal grave que impide al recién nacido evacuar las heces de forma normal, requiriendo diagnóstico y cirugía correctiva en los primeros días de vida.", whatIs: { title: "¿Qué es el Ano Imperforado?", text: "Es una anomalía del desarrollo embrionario donde la porción final del tracto digestivo (recto y ano) no se desarrolla correctamente. Puede presentarse como un ano que simplemente no tiene abertura, un recto que termina en una bolsa ciega, o una fístula (conexión anormal) hacia el tracto urinario o genital." }, symptoms: { title: "Señales Inmediatas al Nacer", intro: "La condición se descubre rutinariamente en el examen físico inicial del recién nacido:", groups: [ { name: "Signos clínicos evidentes", items: ["Ausencia visual del orificio anal en la exploración física del recién nacido", "El bebé no expulsa meconio (la primera caca del recién nacido) dentro de las primeras 24 a 48 horas de vida", "Las heces o el meconio salen por lugares anormales, como la vagina, el escroto, la base del pene o al orinar (indica presencia de una fístula)", "Hinchazón o distensión abdominal progresiva y visible", "Vómitos repetitivos de contenido abdominal (a menudo de color verdoso o bilioso)"] } ], warning: "Si la condición pasa desapercibida (lo cual es extremadamente raro bajo cuidado médico) y el bebé es alimentado, sufrirá una obstrucción intestinal rápida y potencialmente letal." }, types: { title: "Clasificación de la Malformación", intro: "El cirujano pediátrico clasifica el defecto para planificar la cirugía:", items: ["Malformación 'baja': El recto ha descendido casi por completo y está muy cerca de la piel, y los músculos de control intestinal suelen estar intactos y funcionales. Tiene un excelente pronóstico.", "Malformación 'alta': El recto termina muy por encima de la musculatura pélvica normal. Es más compleja de reparar y a menudo requiere múltiples cirugías y más desafíos para el control fecal futuro.", "Presencia de fístulas: Muy a menudo, el intestino se conecta erróneamente a la vejiga o la uretra (en niños) o a la vagina (en niñas)."], note: "Aproximadamente el 50% de los bebés con esta condición tienen anomalías en otros órganos (Síndrome VACTERL: defectos vertebrales, cardíacos, traqueales, esofágicos y renales)." }, causes: { title: "Causas y Desarrollo Fetal", intro: "Es un fallo temprano en la formación de los órganos:", items: ["La malformación ocurre entre la quinta y séptima semana de embarazo, cuando el tracto gastrointestinal inferior se está separando del tracto urogenital.", "La causa exacta se desconoce (es multifactorial o idiopática), aunque tiene bases genéticas complejas.", "No está relacionado con nada que la madre haya hecho, comido o evitado durante su embarazo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es inmediato y requiere pruebas para evaluar la anatomía interna:", items: ["Examen físico visual en la sala de partos (el pediatra examina rutinariamente la permeabilidad anal de todo recién nacido).", "Radiografías abdominales especiales (invertidas o de perfil) tras esperar unas horas para que el gas intestinal baje y muestre exactamente dónde termina la bolsa ciega del recto.", "Ecografía abdominal y espinal para detectar el nivel de la malformación y buscar problemas en los riñones o médula espinal (altamente asociados).", "Ecocardiograma para descartar defectos en el corazón."], note: "Determinar con precisión si es una malformación 'alta' o 'baja' dicta si la cirugía se hace en un solo paso o en varias etapas." }, treatment: { title: "Reparación Quirúrgica Neonatal", intro: "El tratamiento es estrictamente quirúrgico para crear un ano funcional:", subsections: [ { title: "Procedimientos Quirúrgicos", items: ["Para defectos 'bajos': Cirugía inmediata de un solo paso (Anoplastia perineal) en los primeros días de vida, abriendo la piel y uniendo el recto al orificio anal recién creado.", "Para defectos 'altos' o complejos (Enfoque en etapas): 1) Colostomía inicial al nacer (se desvía el intestino hacia una bolsa en la pared abdominal para que el bebé pueda evacuar y crecer sano). 2) Meses después, la cirugía principal (Anorectoplastia sagital posterior o PSARP) para reconstruir el recto, desconectar fístulas y crear el ano. 3) Finalmente, cierre de la colostomía semanas después.", "Programa de dilatación anal en casa: Los padres deben dilatar suavemente el nuevo ano del bebé diariamente durante meses para evitar que la cicatriz se encoja o cierre."] } ], note: "El seguimiento a largo plazo es crucial. Muchos niños requerirán programas de manejo intestinal (laxantes, enemas) durante la infancia para lograr la continencia fecal." }, whenToSeekHelp: { title: "¿Cuándo Solicitar Atención Médica Inmediata?", intro: "Esta condición es una emergencia neonatal. Se requiere acción inmediata si:", items: ["Acaba de dar a luz fuera de un entorno hospitalario y nota que su bebé no tiene abertura anal o el área se ve anormal", "Su recién nacido no ha tenido su primera deposición oscura (meconio) en las primeras 24 horas y su vientre se inflama", "Observa que hay heces saliendo por los genitales del bebé o por la orina"] } },
'Neuronitis vestibular' : { intro: "La neuronitis vestibular es una afección del oído interno que causa un episodio agudo y repentino de vértigo severo. Provocada por la inflamación del nervio que controla el equilibrio, esta condición puede ser aterradora e incapacitante, dificultando estar de pie o caminar sin sentir que el mundo da vueltas de manera violenta.", whatIs: { title: "¿Qué es la Neuronitis Vestibular?", text: "Es la inflamación del nervio vestibular, una rama del octavo nervio craneal situado en el oído interno y encargado de enviar información de equilibrio y orientación espacial al cerebro. Al inflamarse, el nervio envía señales erróneas, creando una ilusión masiva de movimiento (vértigo)." }, symptoms: { title: "Síntomas Clásicos y Repentinos", intro: "Aparece de forma abrupta, a menudo al despertar, e incluye:", groups: [ { name: "Síntomas vestibulares agudos", items: ["Vértigo severo e implacable: Sensación intensa de que uno mismo o la habitación giran rápidamente", "Desequilibrio extremo e inestabilidad al intentar caminar, tendiendo a caerse hacia un lado", "Náuseas profundas y episodios repetidos de vómitos causados por el mareo constante", "Nistagmo: Movimiento espasmódico, rápido e involuntario de los ojos que saltan de un lado a otro", "Sensación de confusión espacial y dificultad para enfocar la vista durante el movimiento"] } ], warning: "La neuronitis vestibular NO causa pérdida de audición ni síntomas neurológicos (como debilidad facial). Si tiene vértigo más pérdida de audición, se llama Laberintitis; si hay debilidad, puede ser un derrame cerebral." }, types: { title: "Fases de la Enfermedad", intro: "La recuperación ocurre en etapas predecibles:", items: ["Fase Aguda (1 a 3 días): Los síntomas son severos e incapacitantes. El vértigo es constante, incluso al estar acostado en absoluto reposo. Requiere reposo en cama.", "Fase de Recuperación (semanas a meses): El vértigo constante desaparece, pero el paciente siente mareos o desequilibrio al hacer movimientos rápidos de la cabeza.", "Fase Crónica (ocasional): Si el cerebro no compensa bien el daño del nervio, el paciente puede quedar con una sensación de inestabilidad o mareo crónico ante giros rápidos."], note: "El cuadro severo inicial asusta mucho, pero la neuronitis vestibular es un problema benigno que casi siempre se cura completamente con el tiempo." }, causes: { title: "Causas e Inflamación Viral", intro: "Se cree casi universalmente que es de origen viral:", items: ["Infección viral directa del nervio vestibular (como los virus que causan resfriados comunes, influenza o infecciones respiratorias)", "Reactivación de virus latentes en el nervio, como el virus del herpes simple (el del fuego labial) o el virus de la varicela zóster", "A menudo, los pacientes reportan haber tenido un resfriado, dolor de garganta o infección gastrointestinal unas semanas antes del ataque repentino de vértigo", "No es contagiosa en sí misma, aunque el virus original que la causó sí pudo haberlo sido"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico o neurólogo la diagnostica por exclusión y signos clínicos clave:", items: ["Examen físico ocular: Buscar el nistagmo (los ojos laten repetidamente hacia el oído sano).", "Prueba de Impulso Cefálico (Head Impulse Test o vHIT): El médico gira rápidamente la cabeza del paciente para ver si los ojos pierden momentáneamente la fijación en un objetivo, confirmando el daño en el nervio del oído.", "Descarte obligatorio de ACV: El médico verificará si hay habla arrastrada, pérdida de audición, debilidad o asimetría facial. (Un derrame cerebeloso puede imitar el vértigo).", "Pruebas auditivas (audiometría) para confirmar que la audición está perfectamente normal, lo que la distingue de la laberintitis o la enfermedad de Ménière.", "Resonancia magnética (RM) cerebral solo si se sospecha un derrame u otros problemas neurológicos atípicos."], note: "El diagnóstico temprano calma al paciente, ya que el terror a tener un tumor o un derrame agrava enormemente el cuadro de ansiedad." }, treatment: { title: "Manejo Sintomático y Rehabilitación", intro: "El tratamiento se divide en calmar la crisis aguda y entrenar al cerebro después:", subsections: [ { title: "Fármacos y Rehabilitación", items: ["Fase Aguda (primeros 3 días): Uso de supresores vestibulares fuertes (meclizina, diazepam o dimenhidrinato) y potentes antieméticos (ondansetrón) para detener los vómitos y el vértigo atroz.", "Corticosteroides (Prednisona): Si se administran en los primeros días, reducen rápidamente la inflamación del nervio y aceleran drásticamente la curación a largo plazo.", "Suspensión rápida de fármacos supresores: Tras las primeras 72 horas, SE DEBEN suspender los medicamentos para mareos, ya que impiden que el cerebro aprenda a compensar el daño.", "Rehabilitación Vestibular: Ejercicios físicos específicos recetados por un fisioterapeuta donde el paciente mueve la cabeza y los ojos repetidamente para 'reprogramar' el cerebro y que se acostumbre a las nuevas señales del oído interno, eliminando la inestabilidad residual."] } ], note: "Es crucial empezar a moverse y caminar, aunque cause mareos, unos días después de la crisis; el reposo prolongado retrasa severamente la recuperación del equilibrio." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias Inmediatamente?", intro: "Un vértigo severo siempre debe ser evaluado por un médico. Acuda a urgencias si el vértigo repentino se acompaña de:", items: ["Dificultad o cambios en el habla (habla arrastrada o confusa)", "Debilidad, parálisis o entumecimiento en un brazo, pierna o un lado de la cara", "Visión doble persistente, pérdida de visión o ceguera temporal", "Fiebre muy alta, dolor de cabeza nuevo extremadamente intenso o rigidez en el cuello", "Incapacidad total de caminar sin caerse al suelo o pérdida de conciencia"] } },
'Falla cardíaca' : { intro: "La falla cardíaca (o insuficiencia cardíaca) no significa que el corazón ha dejado de latir, sino que el músculo cardíaco se ha vuelto demasiado débil o rígido para bombear la sangre con la eficacia que el cuerpo necesita. Es una afección crónica y progresiva que provoca congestión de líquidos en los pulmones y extremidades.", whatIs: { title: "¿Qué es la Falla Cardíaca?", text: "Es un síndrome clínico complejo en el que el corazón no puede llenarse de sangre adecuadamente o no tiene la fuerza suficiente para expulsarla. Como resultado, la sangre retrocede y se acumula en las venas y pulmones, mientras que los órganos no reciben suficiente oxígeno y nutrientes." }, symptoms: { title: "Síntomas y Señales de Congestión", intro: "Los síntomas reflejan el atasco de líquidos y la falta de oxígeno en el cuerpo:", groups: [ { name: "Síntomas pulmonares y respiratorios", items: ["Disnea: Falta de aire progresiva al hacer esfuerzos (como subir escaleras) y, en etapas avanzadas, incluso estando en reposo", "Ortopnea: Necesidad de usar varias almohadas o dormir sentado porque la falta de aire empeora al acostarse plano", "Despertar repentinamente por la noche asfixiándose o tosiendo (Disnea paroxística nocturna)", "Tos crónica persistente o sibilancias que pueden producir un moco blanco o rosado espumoso"] }, { name: "Síntomas sistémicos y físicos", items: ["Edema severo: Hinchazón notable y progresiva en los pies, tobillos, piernas y en el abdomen (ascitis)", "Aumento de peso rápido (por retención de agua), como ganar 1 o 2 kilos en un solo día", "Fatiga extrema, cansancio profundo y debilidad general", "Dificultad para concentrarse o confusión debido a un menor flujo de sangre al cerebro"] } ], warning: "Si de pronto tose flema espumosa de color rosado acompañada de una falta de aire aterradora y palpitaciones, está sufriendo un edema pulmonar agudo y necesita una ambulancia urgente." }, types: { title: "Tipos de Falla Cardíaca", intro: "La insuficiencia se clasifica según qué parte del bombeo está fallando:", items: ["Falla cardíaca sistólica (Fracción de eyección reducida - HFrEF): El ventrículo izquierdo se agranda, pierde fuerza muscular y no puede 'exprimir' y bombear la sangre con suficiente fuerza.", "Falla cardíaca diastólica (Fracción de eyección preservada - HFpEF): El músculo cardíaco está fuerte pero se ha vuelto grueso y extremadamente rígido, por lo que no puede relajarse para llenarse de suficiente sangre entre latidos.", "Falla cardíaca del lado derecho: Generalmente ocurre como resultado de la falla del lado izquierdo. La sangre retrocede hacia las venas, causando inflamación masiva en el abdomen y las piernas."], note: "La fracción de eyección (el porcentaje de sangre bombeada en cada latido) es el valor clínico más importante para diagnosticar y tratar el tipo de falla." }, causes: { title: "Causas y Enfermedades Detonantes", intro: "La falla cardíaca casi siempre es el resultado final de otras enfermedades que han dañado o agotado el corazón a lo largo de los años:", items: ["Enfermedad de las arterias coronarias y ataques cardíacos (la causa más común): Un infarto previo deja un tejido cicatricial muerto que debilita permanentemente el bombeo del corazón.", "Presión arterial alta crónica (Hipertensión): Obliga al corazón a trabajar con tanta fuerza durante años que el músculo se engrosa y se vuelve rígido.", "Cardiomiopatía (enfermedad directa del músculo cardíaco) por factores genéticos, infecciones virales o uso crónico de drogas y alcohol.", "Enfermedad de las válvulas cardíacas (válvulas estrechas o con fugas que exigen un sobreesfuerzo al corazón).", "Arritmias cardíacas severas y no controladas (como la fibrilación auricular).", "Diabetes, obesidad severa o apnea del sueño profunda."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere pruebas precisas para ver el daño estructural del corazón:", items: ["Ecocardiograma: La prueba central y más importante. Utiliza ultrasonido para ver el corazón latiendo, mide el tamaño de las cámaras y calcula la Fracción de Eyección exacta.", "Análisis de sangre (Péptido natriurético tipo B o BNP): Una hormona que el corazón libera en la sangre cuando está estirado y estresado; niveles altos confirman la falla cardíaca.", "Radiografía de tórax: Permite ver si el corazón está agrandado y si hay derrames de líquido blanco inundando los pulmones oscuros.", "Electrocardiograma (ECG): Detecta latidos anormales o daño por un ataque cardíaco anterior.", "Cateterismo cardíaco: Para verificar si hay bloqueos coronarios subyacentes que puedan arreglarse para mejorar la fuerza del corazón."], note: "El diagnóstico se clasifica en 4 clases funcionales (NYHA, del I al IV), donde la clase IV significa que hay síntomas de falta de aire incluso en absoluto reposo." }, treatment: { title: "Manejo Médico Crónico y Dispositivos", intro: "No tiene cura (salvo trasplante), pero un tratamiento médico riguroso prolonga la vida años y mejora drásticamente los síntomas:", subsections: [ { title: "Terapia y soporte avanzado", items: ["La cuádruple terapia farmacológica: El pilar moderno. Combina inhibidores (ECA/ARNI como Entresto), Betabloqueantes, inhibidores de SGLT2 y antagonistas de aldosterona para proteger el corazón, ralentizar su desgaste y mejorar su bombeo.", "Diuréticos ('pastillas para orinar', como furosemida) para evacuar agresivamente el líquido acumulado en pulmones y piernas, y aliviar la respiración.", "Modificación innegociable de hábitos: Restricción severa de sal (sodio) y control de la cantidad de líquidos ingeridos al día, control de peso diario en casa, y abandono absoluto de tabaco/alcohol.", "Dispositivos implantables: Marcapasos biventricular (Terapia de resincronización) para hacer que ambos lados del corazón latan al unísono, o un Desfibrilador Implantable (DAI) para detener arritmias mortales repentinas.", "En etapas terminales: Uso de bombas mecánicas (DAVI) o derivación a lista de trasplante de corazón."] } ], note: "Pesarse cada mañana es vital; un aumento de más de 1.5 kg en dos días indica retención de líquido peligrosa y requiere ajuste de medicamentos." }, whenToSeekHelp: { title: "¿Cuándo Acudir a Emergencias Médicas?", intro: "La descompensación del corazón ocurre rápido. Vaya al hospital sin dudarlo si:", items: ["Experimenta un episodio de falta de aire repentina y severa que no cede, especialmente si se acompaña de tos con espuma o sangre", "Siente un dolor agudo, presión o molestia asfixiante en el pecho", "Experimenta un desmayo repentino y una pérdida de conocimiento, o debilidad profunda que le impide sostenerse", "Su ritmo cardíaco se vuelve repentinamente muy rápido, palpitante e irregular, acompañado de mareos"] } },
'Dedo del pie en martillo' : { intro: "El dedo del pie en martillo es una deformidad estructural dolorosa y progresiva de los dedos menores del pie. Ocurre cuando la articulación media del dedo se dobla de forma rígida hacia abajo, asemejándose a un martillo, lo que provoca roce extremo contra el calzado y dolor incapacitante al caminar.", whatIs: { title: "¿Qué es el Dedo en Martillo?", text: "Es una anomalía biomecánica en la que existe una contractura por flexión en la articulación interfalángica proximal (la articulación media del dedo). Afecta típicamente al segundo, tercer o cuarto dedo del pie, forzando la articulación media a apuntar hacia arriba mientras la punta del dedo apunta bruscamente hacia abajo." }, symptoms: { title: "Signos Clínicos y Problemas de Piel", intro: "El problema comienza como una simple molestia visual pero escala a dolor físico:", groups: [ { name: "Deformidad anatómica", items: ["El dedo del pie se dobla de forma antinatural en su articulación media, tomando forma de 'V' invertida o martillo", "Incapacidad progresiva para flexionar o estirar el dedo afectado por completo", "En etapas tempranas, la articulación puede enderezarse con la mano (martillo flexible), pero eventualmente se congela en esa posición (martillo rígido)"] }, { name: "Dolor y afecciones cutáneas asociadas", items: ["Dolor intenso y punzante en la articulación media doblada al usar zapatos, especialmente si son cerrados", "Aparición de callos gruesos, duros o 'ojos de gallo' dolorosos en la parte superior de la articulación media (debido a la fricción constante contra el techo del zapato)", "Callosidades en la yema o punta del dedo afectado por la presión directa contra el suelo", "Enrojecimiento, hinchazón o sensación de ardor severo en la articulación deformada"] } ], warning: "Para los pacientes diabéticos o con mala circulación, un callo formado por un dedo en martillo puede ulcerarse rápidamente, infectarse y llevar a un riesgo real de amputación." }, types: { title: "Etapas de Rigidez", intro: "Clínicamente, la deformidad se clasifica por su flexibilidad para determinar si se necesita cirugía:", items: ["Dedo en martillo flexible: La condición está en sus primeras etapas. Todavía puede enderezar el dedo con sus manos, lo que permite tratamientos simples (férulas, cambios de zapato).", "Dedo en martillo semi-rígido: Mayor resistencia al estiramiento; el tejido conectivo comienza a encogerse y fijarse.", "Dedo en martillo rígido: Ocurre en etapas crónicas avanzadas. Los tendones están completamente tensos y las articulaciones congeladas o con artritis. El dedo ya no puede moverse, la cirugía es la única forma de realinearlo."], note: "Se diferencia del 'dedo en mazo' (que afecta solo la articulación más cercana a la uña) y del 'dedo en garra' (que dobla ambas articulaciones del dedo)." }, causes: { title: "Causas y Biomecánica", intro: "Es el resultado directo de un desequilibrio de fuerza entre los músculos y tendones que mantienen el dedo recto:", items: ["Calzado inadecuado (Causa principal): Zapatos demasiado estrechos en la punta o tacones altos. Forzan a los dedos a encogerse, flexionarse y aglomerarse, impidiendo que el músculo se estire.", "Anatomía del pie y genética: Tener el segundo dedo más largo que el dedo gordo (pie de Morton) lo hace susceptible de doblarse dentro de un zapato de tamaño normal. Pies excesivamente planos o con arcos muy altos.", "Traumatismos: Un golpe severo en el dedo del pie, una fractura que sanó mal o un esguince articular.", "Enfermedades subyacentes: Artritis reumatoide (que destruye y desvía las articulaciones), o daño nervioso por diabetes o un accidente cerebrovascular que altera el equilibrio muscular del pie."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico por parte de un podiatra o traumatólogo ortopédico es visual y mecánico:", items: ["Examen físico directo: Evaluación visual de la deformidad y palpación para medir el rango de movimiento y clasificar si es flexible o rígida.", "Evaluación de la marcha y el calzado para identificar problemas biomecánicos subyacentes o calzado agresivo.", "Evaluación de los callos asociados y el estado circulatorio/nervioso del pie.", "Radiografías (Rayos X) en posición de pie para observar el grado exacto de desviación de los huesos, detectar si las articulaciones están artríticas o luxadas, y planificar una posible cirugía."], note: "A menudo se diagnostica junto a la presencia de juanetes (Hallux Valgus), ya que el dedo gordo desviado suele empujar y aplastar al segundo dedo, causándole el defecto en martillo." }, treatment: { title: "Alivio Ortopédico y Corrección Quirúrgica", intro: "El objetivo es aliviar la presión dolorosa en el callo y devolver la función mecánica:", subsections: [ { title: "Soluciones conservadoras y de quirófano", items: ["Cambio inmediato de calzado: Usar zapatos con una puntera ancha, alta y profunda (toe box amplio) y evitar tacones de más de 5 centímetros para quitar la presión directa del dedo doblado.", "Dispositivos protectores: Almohadillas en forma de dona o protectores de silicona para evitar que el callo de la articulación frote contra el zapato.", "Órtesis o plantillas personalizadas: Para equilibrar los músculos del pie y evitar que la deformidad avance en dedos flexibles.", "Férulas o vendajes (Taping): Usados para sujetar y tratar de estirar el dedo en posición recta (solo útil en casos muy tempranos y flexibles).", "Cirugía ortopédica (para casos rígidos y dolorosos): El cirujano puede cortar y alargar los tendones acortados (tenotomía), o extirpar un pequeño trozo de hueso en la articulación media y fijarla temporalmente con un alfiler (artrodesis) para dejar el dedo permanentemente recto y sin dolor."] } ], note: "No intente tratar, cortar o 'curar' el callo superior con navajas o medicamentos ácidos sin prescripción, ya que esto crea heridas profundas sobre la articulación." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Especialista del Pie?", intro: "Debe programar una visita con su podólogo o médico ortopedista si:", items: ["El dolor en el dedo del pie afecta severamente su capacidad para caminar, correr o realizar sus actividades cotidianas", "El desarrollo de los callos en la zona doblada se vuelve rojo, extremadamente doloroso o se abre formando una llaga", "La deformidad del dedo empeora notablemente a lo largo de los meses o se ha vuelto rígido e inamovible", "Es un paciente diagnosticado con diabetes o problemas de circulación y nota cualquier cambio estructural, callo profundo o dolor en sus pies"] } },
'Hipocondría' : { intro: "La hipocondría, actualmente diagnosticada como Trastorno de Ansiedad por Enfermedad, es un problema psiquiátrico en el cual una persona vive aterrorizada y obsesionada con la idea de tener o poder contraer una enfermedad grave. Esta ansiedad extrema persiste a pesar de las repetidas pruebas médicas normales, consumiendo por completo la vida y la energía mental del individuo.", whatIs: { title: "¿Qué es el Trastorno de Ansiedad por Enfermedad?", text: "Es un trastorno somatomorfo severo donde la persona interpreta erróneamente sensaciones corporales normales (un latido rápido, un ligero dolor, un ruido intestinal) o problemas menores como signos inequívocos de una patología letal. La preocupación se centra en el miedo a la enfermedad en sí, más que en el síntoma." }, symptoms: { title: "Síntomas y Comportamientos Obsesivos", intro: "Los síntomas son predominantemente psicológicos y se traducen en acciones compulsivas:", groups: [ { name: "Preocupaciones cognitivas y miedos", items: ["Preocupación persistente, intensa y paralizante por tener una enfermedad grave, oculta y no diagnosticada", "Magnificación mental: interpretar estornudos, dolores de cabeza menores o la sudoración normal como el comienzo de una enfermedad catastrófica", "Un alto nivel de ansiedad sobre el estado general de salud (pensar todo el día en el propio cuerpo)", "Facilidad extrema para alarmarse por problemas de salud ajenos o noticias médicas en internet"] }, { name: "Comportamientos compulsivos o evasivos", items: ["Examinar repetida y compulsivamente el propio cuerpo en busca de bultos, manchas o signos de enfermedad ('body checking')", "Búsqueda excesiva de información médica en internet ('cibercondría'), lo que incrementa el pánico", "Visitar constantemente a diferentes médicos, someterse a resonancias o analíticas repetidas y no creer los resultados tranquilizadores (Tipo de búsqueda de atención)", "Evitar por completo las citas médicas, hospitales o análisis de sangre por el pánico extremo a que le confirmen el diagnóstico fatal (Tipo de evitación de atención)"] } ], warning: "Cuando la obsesión se convierte en un delirio somático (creer al 100% y de forma irracional que un órgano se está pudriendo), puede indicar un trastorno psicótico subyacente más severo." }, types: { title: "Diferencia con otros Trastornos Somatomorfos", intro: "Es clave diferenciar la ansiedad por enfermedad de problemas similares:", items: ["Trastorno de Ansiedad por Enfermedad (Antigua hipocondría): La persona experimenta CERO síntomas físicos o síntomas muy leves, pero el terror mental a enfermar es inmenso.", "Trastorno de Síntomas Somáticos: La persona experimenta síntomas físicos reales y muy molestos (como dolor crónico general), y tiene una ansiedad desproporcionada sobre esos síntomas específicos.", "Trastorno Obsesivo-Compulsivo (TOC): A menudo coexisten; la preocupación por la enfermedad actúa como la obsesión, y el chequeo corporal es la compulsión.", "Ansiedad normal de salud: Preocuparse temporalmente por un síntoma y quedarse totalmente tranquilo tras la visita al médico (lo cual el hipocondríaco es incapaz de hacer)."], note: "El término 'hipocondría' se ha eliminado médicamente porque resultaba estigmatizante, peyorativo y despectivo para los pacientes." }, causes: { title: "Raíces y Factores de Riesgo", intro: "El origen suele ser una mezcla de vulnerabilidad psicológica, creencias aprendidas y estrés:", items: ["Malentendido cognitivo: Una tendencia biológica a ser hiperconsciente y catastrofizar las sensaciones físicas del cuerpo, teniendo una nula tolerancia a la incertidumbre.", "Experiencias infantiles o trauma: Haber tenido una enfermedad grave en la infancia, o tener padres extremadamente ansiosos que hipervigilaban la salud de sus hijos.", "Experiencias pasadas de enfermedades en la familia: Haber presenciado el sufrimiento o muerte de un ser querido por una enfermedad repentina y grave.", "Exceso de estrés actual: La ansiedad por la vida o problemas no resueltos se canaliza de forma inconsciente hacia la preocupación por la salud corporal.", "Coexistencia psiquiátrica: Más del 60% de los pacientes tienen también trastornos de ansiedad generalizada o depresión mayor."] }, diagnosis: { title: "¿Cómo se Evalúa Psiquiátricamente?", intro: "El diagnóstico clínico requiere separar el problema psicológico de cualquier enfermedad física real:", items: ["Evaluación física exhaustiva por parte del médico de cabecera para confirmar que, de hecho, no existe una enfermedad médica grave subyacente que explique los temores.", "Evaluación psiquiátrica clínica utilizando los criterios del DSM-5, confirmando que la preocupación intensa e irracional por la enfermedad ha estado presente durante al menos 6 meses.", "Evaluación del deterioro funcional: Medir cuánto interfiere este miedo con el trabajo del paciente, sus finanzas (por exceso de gastos en médicos privados) y sus relaciones familiares.", "Descartar otros trastornos mentales como la esquizofrenia, el trastorno de pánico severo o la dismorfia corporal."], note: "El médico nunca debe decirle al paciente que 'todo está en su cabeza'; el sufrimiento emocional y la ansiedad que experimenta son absoluta y dolorosamente reales." }, treatment: { title: "Terapia Cognitiva y Farmacológica", intro: "El tratamiento se enfoca en gestionar la ansiedad y recuperar la calidad de vida, sin centrarse en los síntomas físicos:", subsections: [ { title: "Estrategias de psicoterapia y manejo", items: ["Terapia Cognitivo-Conductual (TCC): Es el tratamiento estándar y más efectivo. Ayuda al paciente a identificar sus creencias catastróficas, enseñarle a tolerar la incertidumbre normal del cuerpo y cambiar el comportamiento compulsivo de buscar reaseguro médico (dejar de googlear síntomas y dejar de revisar su cuerpo).", "Medicamentos Antidepresivos (ISRS como la fluoxetina o sertralina): Si el paciente sufre de altos niveles de ansiedad generalizada o depresión, estos medicamentos disminuyen drásticamente el terror obsesivo.", "Establecimiento de un médico único: Una estrategia fundamental es tener solo un médico de cabecera de confianza y programar visitas regulares preestablecidas y breves para calmar la ansiedad, con la prohibición estricta de visitar especialistas privados, ir a urgencias o pedir resonancias a menos que el médico de cabecera lo autorice.", "Prácticas de manejo del estrés, meditación y entrenamiento de relajación para calmar la respuesta biológica del miedo."] } ], note: "La curación toma tiempo, ya que se deben reentrenar vías cerebrales de respuesta al miedo profundamente arraigadas en el paciente." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Psicólogo o Psiquiatra?", intro: "Se requiere intervención psicológica formal cuando la preocupación por la salud:", items: ["Domina gran parte de su día a día y le impide disfrutar de su familia, su trabajo o sus pasatiempos habituales", "Provoca un nivel de angustia abrumadora y lo lleva a ataques de pánico o a una depresión profunda por la creencia inminente de muerte", "Le lleva a gastar recursos financieros significativos en múltiples doctores, resonancias, exámenes de sangre o pruebas de laboratorio repetidas buscando una respuesta que confirme su miedo", "Causa que amigos o familiares se sientan frustrados y distanciados porque usted constantemente pide reafirmación de que no está enfermo"] } },
'Desregulación disruptiva del estado de ánimo' : { intro: "El Trastorno de Desregulación Disruptiva del Estado de Ánimo (TDDEA) es un diagnóstico psiquiátrico pediátrico relativamente nuevo. Creado para clasificar a los niños que presentan una irritabilidad severa y crónica, junto con estallidos de ira extremos y frecuentes, diferenciándolos así del trastorno bipolar pediátrico y evitando la medicación excesiva.", whatIs: { title: "¿Qué es el TDDEA?", text: "Es un trastorno clínico en niños (de entre 6 y 18 años) caracterizado por una irritabilidad profunda, grave y constante, sumada a rabietas verbales o físicas extremas que son completamente desproporcionadas en intensidad o duración para la situación y la edad de desarrollo del niño." }, symptoms: { title: "Síntomas Clave y Estallidos", intro: "Para el diagnóstico, el comportamiento debe ser grave y constante, no un mal humor pasajero:", groups: [ { name: "Estallidos de ira (Rabietas severas)", items: ["Arrebatos de mal genio severos y recurrentes (ya sea verbalmente, mediante gritos furiosos, o físicamente, rompiendo cosas o golpeando personas)", "Estos estallidos ocurren típicamente, como promedio, de tres a más veces por semana", "La reacción explosiva es groseramente desproporcionada en intensidad (ej. destruir la habitación por perder un juego de mesa)", "El comportamiento es claramente inapropiado para el nivel de desarrollo o la edad biológica del niño"] }, { name: "Estado de ánimo basal", items: ["Entre las crisis explosivas, el estado de ánimo general del niño es crónicamente y persistentemente irritable, enojado, resentido o triste la inmensa mayor parte del día, casi todos los días", "Esta irritabilidad constante es fácilmente observable por otras personas (padres, maestros, compañeros)", "El deterioro ocurre en al menos dos entornos (en casa y en la escuela), siendo muy grave en al menos uno de ellos"] } ], warning: "A diferencia del trastorno bipolar, los niños con TDDEA no experimentan episodios prolongados de euforia, manía, grandiosidad o falta de necesidad de sueño; su problema base es la irritabilidad pura." }, types: { title: "Diferenciación y Diagnóstico Correcto", intro: "El TDDEA se introdujo para evitar sobre-diagnosticar Trastorno Bipolar en niños coléricos:", items: ["Frente al Trastorno Bipolar: El bipolar cursa en ciclos marcados de semanas de euforia extrema (manía) seguidas de depresión profunda. El TDDEA no tiene ciclos, la irritabilidad es constante y crónica todos los días.", "Frente al Trastorno de Oposición Desafiante (TOD): Aunque son similares, el TDDEA se centra más en la desregulación emocional profunda y los arranques violentos anímicos que en la pura desobediencia desafiante del TOD. Si un niño cumple los criterios de ambos, solo se le diagnostica TDDEA.", "Comorbilidades: Los niños con TDDEA tienen a menudo de forma coexistente TDAH (Déficit de Atención), trastornos de ansiedad clínica o depresión profunda."], note: "El diagnóstico de TDDEA no debe hacerse por primera vez antes de los 6 años ni después de los 18 años, y los síntomas deben haber durado al menos 12 meses." }, causes: { title: "Orígenes y Neurología de la Emoción", intro: "Las causas son una mezcla de vulnerabilidad cerebral y contexto de vida:", items: ["Disfunción neurobiológica: Dificultades en las áreas y redes del cerebro responsables de procesar, regular y calmar las emociones negativas, la frustración y los impulsos.", "Genética e historial familiar: A menudo hay antecedentes de trastornos del estado de ánimo (depresión severa, ansiedad severa) en los padres, más que bipolaridad.", "Temperamento infantil: Niños que desde bebés mostraban un temperamento excepcionalmente difícil, alta reactividad emocional o llanto inconsolable y constante.", "Factores psicosociales (agravantes): Trauma temprano, estrés crónico en el hogar, pobreza, dinámicas de crianza severamente conflictivas o falta de apego seguro pueden exacerbar biológicamente la desregulación."] }, diagnosis: { title: "¿Cómo Evalúa el Psiquiatra Infantil?", intro: "Es un diagnóstico que requiere evaluación minuciosa por un especialista en salud mental pediátrica:", items: ["Revisión del historial de desarrollo y comportamiento del niño usando pautas estrictas del DSM-5-TR", "Entrevistas estructuradas con los padres para documentar la frecuencia exacta de los estallidos y el ánimo constante del niño entre rabietas", "Informes estandarizados de las escuelas o maestros sobre el desempeño y comportamiento con los compañeros (la disfunción social es obligatoria)", "Evaluación para descartar agresividad debida al espectro autista, discapacidad intelectual, ansiedad pura no tratada, traumas por abuso reciente o reacción a medicamentos (como cortisona o estimulantes)"], note: "El objetivo del diagnóstico correcto es evitar que el niño reciba cócteles peligrosos de medicamentos antipsicóticos pesados innecesariamente." }, treatment: { title: "Terapias de Regulación y Apoyo Psiquiátrico", intro: "El enfoque suele ser doble: enseñar habilidades de tolerancia a la frustración y apoyo con medicación si es indispensable:", subsections: [ { title: "Abordajes psicológicos y farmacológicos", items: ["Terapia Cognitivo-Conductual (TCC): Esencial para que el niño aprenda a identificar las señales tempranas de su frustración, procesar pensamientos distorsionados y usar mecanismos de afrontamiento (relajación, respiración) antes de explotar.", "Capacitación en el manejo de padres (PMT): Enseña a los padres a no intensificar las crisis, cómo recompensar los intentos de control emocional del niño, e ignorar o lidiar con las conductas disruptivas de forma predecible, tranquila y firme.", "Intervenciones escolares y apoyo educativo: Desarrollar un plan de educación especial para que los maestros sepan cómo desactivar una crisis potencial en el aula.", "Medicación: Antidepresivos (ISRS, para reducir la irritabilidad de base), medicamentos estimulantes (si el niño también tiene TDAH para mejorar el control de impulsos), o, en casos de estallidos extremadamente violentos e inmanejables, antipsicóticos atípicos (Risperidona, Aripiprazol) a corto plazo."] } ], note: "Los niños con TDDEA tienen un alto riesgo de desarrollar depresión clínica o ansiedad generalizada severa en la vida adulta, no necesariamente trastorno bipolar." }, whenToSeekHelp: { title: "¿Cuándo Solicitar una Evaluación Psiquiátrica Urgente?", intro: "Busque atención profesional de salud mental para su hijo/a si:", items: ["Las rabietas son tan violentas e intensas que se vuelve peligroso para sí mismo, para usted o para sus hermanos, o destruye constantemente objetos de la casa", "Usted siente que debe 'caminar sobre cáscaras de huevo' todos los días porque el niño siempre está enfadado y la mínima cosa provoca una explosión incontrolable", "La escuela está a punto de expulsar o suspender al niño debido a su incapacidad para controlar sus emociones en el aula", "El niño verbaliza un odio profundo hacia sí mismo después de la crisis o expresa deseos de no vivir"] } },
'Trastorno de pánico con agorafobia' : { intro: "El trastorno de pánico con agorafobia es una de las condiciones psiquiátricas más limitantes. Comienza con ataques de ansiedad aterradores e inesperados, y evoluciona hacia un miedo paralizante a sufrir otro ataque en lugares públicos. Como resultado, la persona comienza a evitar salir o enfrentar situaciones sociales, llegando en casos extremos a no poder abandonar su propio hogar.", whatIs: { title: "¿Qué es el Pánico y la Agorafobia?", text: "El trastorno de pánico se define por sufrir ataques de pánico repentinos y abrumadores. La agorafobia se desarrolla como consecuencia: es el miedo irracional a estar en espacios abiertos, multitudes, transporte público o fuera de casa solo, por temor a no poder escapar o no recibir ayuda médica si ocurre un nuevo ataque de pánico." }, symptoms: { title: "El Ciclo del Miedo y la Evitación", intro: "Los síntomas se dividen entre la crisis biológica y el comportamiento de escape:", groups: [ { name: "El Ataque de Pánico (Manifestaciones físicas severas)", items: ["Aparición repentina, en minutos, de taquicardia violenta, palpitaciones fuertes o dolor en el pecho", "Dificultad extrema para respirar, sensación de ahogo, asfixia o hiperventilación", "Sudoración profusa, temblores incontrolables o sacudidas corporales", "Mareos severos, aturdimiento, sensación de desmayo y hormigueo en extremidades", "Miedo absoluto, visceral e inminente a morir (creer que es un infarto) o a perder el control y volverse loco", "Desrealización (sensación de que el entorno es irreal) o despersonalización (sentirse fuera del propio cuerpo)"] }, { name: "Síntomas y comportamientos Agorafóbicos", items: ["Ansiedad constante y anticipatoria sobre cuándo ocurrirá el siguiente ataque", "Evitación fóbica y activa de lugares específicos: centros comerciales, cines, puentes, autobuses, aviones o supermercados", "Necesidad imperiosa de estar siempre acompañado por una persona 'segura' (pareja o familiar) para atreverse a salir de casa", "Ataque de pánico automático al solo pensar o ser forzado a ir a uno de estos lugares temidos"] } ], warning: "Los ataques de pánico imitan a la perfección un ataque cardíaco. En el primer episodio, es correcto acudir a urgencias para descartar un evento cardiovascular real." }, types: { title: "Relación Diagnóstica Actual (DSM-5)", intro: "Históricamente se veían como un solo trastorno, hoy se diagnostican formalmente por separado pero interactúan:", items: ["Trastorno de pánico (Puro): La persona tiene ataques, pero no altera su rutina ni evita lugares significativamente.", "Agorafobia (Pura): Miedo a espacios públicos o de difícil escape, que a veces se presenta sin haber sufrido nunca un ataque de pánico completo (poco común).", "Trastorno de Pánico CON Agorafobia: El cuadro clásico severo, donde el terror al ataque de pánico es el combustible que alimenta y construye la agorafobia restrictiva."], note: "La evitación agorafóbica no calma el problema, sino que lo agrava drásticamente al enseñarle al cerebro que esos lugares son verdaderamente peligrosos." }, causes: { title: "Causas y Factores Desencadenantes", intro: "El sistema de alarma biológico (lucha o huida) se avería debido a:", items: ["Genética e historia familiar: Fuerte vulnerabilidad biológica a la ansiedad extrema heredada.", "Anormalidades cerebrales: Hipersensibilidad en la amígdala (el centro del miedo del cerebro) o desequilibrios en neurotransmisores como la serotonina.", "Estrés agudo importante: Pérdida de un ser querido, estrés laboral extremo, cambios importantes en la vida o traumas severos.", "Consumo de sustancias estimulantes: Altas dosis de cafeína, cocaína, anfetaminas o abstinencia de drogas/alcohol que desencadenan el primer ataque biológico.", "Tendencia psicológica a malinterpretar sensaciones corporales benignas (ej. un leve mareo se interpreta como un tumor o desmayo inminente)."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El psiquiatra o psicólogo clínico evalúa la interacción entre los ataques y el miedo limitante:", items: ["Descartar causas médicas u orgánicas primero (hipertiroidismo, problemas cardíacos, asma, feocromocitoma o abuso de cafeína/drogas) mediante un electrocardiograma y análisis de sangre completos.", "Evaluación psicológica basada en los criterios del DSM-5: Confirmar que los ataques son recurrentes y repentinos, y han sido seguidos por un mes o más de miedo constante a tener otro.", "Evaluar la presencia de agorafobia: Confirmar el miedo intenso y la evitación activa de al menos dos de estas situaciones: usar transporte público, estar en espacios abiertos, en espacios cerrados (tiendas), hacer cola o estar en medio de una multitud, o estar fuera de casa solo.", "Medir el grado de discapacidad en la vida familiar, laboral y social del paciente."], note: "El diagnóstico temprano previene que la agorafobia se solidifique; es mucho más fácil tratar el pánico antes de que la persona deje de salir de casa." }, treatment: { title: "Terapia de Exposición y Estabilización Médica", intro: "El trastorno es altamente tratable y la inmensa mayoría de los pacientes recuperan su libertad:", subsections: [ { title: "Intervenciones clave", items: ["Terapia Cognitivo-Conductual (TCC): El tratamiento de oro y el más efectivo. Enseña a cambiar los pensamientos catastróficos. Incluye Terapia de Exposición Interoceptiva (provocar síntomas físicos leves en terapia para perderles el miedo) y Exposición In Vivo (enfrentar gradualmente y de forma segura los lugares temidos sin escapar).", "Medicamentos Antidepresivos (ISRS/IRSN): Sertralina, Paroxetina, Escitalopram, o Venlafaxina. Actúan reequilibrando los químicos del cerebro para evitar que los ataques biológicos se disparen; deben tomarse diariamente a largo plazo.", "Medicamentos Ansiolíticos rápidos (Benzodiacepinas como Alprazolam o Clonazepam): Usados únicamente a muy corto plazo o en emergencias absolutas para calmar ataques agudos (conllevan un altísimo riesgo de adicción física si se abusa de ellos).", "Técnicas de regulación fisiológica: Entrenamiento estricto en respiración diafragmática profunda, relajación muscular progresiva y reducción absoluta de cafeína, alcohol y estimulantes."] } ], note: "La clave de la terapia psicológica no es 'no sentir ansiedad', sino aprender que la ansiedad es muy incómoda pero no es peligrosa ni mortal." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Profesional de Salud Mental?", intro: "Es crucial iniciar un tratamiento médico psiquiátrico y psicológico si:", items: ["Ha experimentado crisis de terror repentinas acompañadas de taquicardia o asfixia en más de una ocasión, y vive con el miedo constante de que le vuelva a pasar", "Se da cuenta de que está modificando su ruta al trabajo, evitando tiendas, transporte público o eventos sociales importantes por el temor a sentirse mal o no poder escapar", "Solo se siente capaz de salir de su hogar si está acompañado por una persona de extrema confianza, o se ha vuelto completamente prisionero en su propia casa (confinado en el hogar)", "Se apoya secretamente en el consumo de alcohol o sedantes para poder enfrentar salidas obligatorias o compromisos públicos"] } },
'Obstrucción del conducto lagrimal' : { intro: "Una obstrucción del conducto lagrimal es una anomalía ocular donde el delicado sistema de drenaje del ojo se bloquea parcial o totalmente. En lugar de drenar las lágrimas hacia la nariz, el líquido se desborda, causando un ojo crónicamente lloroso, irritado y frecuentemente infectado. Es enormemente común en bebés recién nacidos, pero puede afectar a adultos por otras causas.", whatIs: { title: "¿Qué es el Conducto Lagrimal Bloqueado (Dacrioestenosis)?", text: "Normalmente, las lágrimas producidas por las glándulas lagrimales lubrican el ojo y luego drenan hacia pequeños orificios en las esquinas internas de los párpados, bajando por un canal (conducto nasolagrimal) hasta la nariz. Una obstrucción en cualquier parte de esta 'tubería' impide que las lágrimas salgan del ojo, creando estancamiento e infecciones." }, symptoms: { title: "Síntomas y Signos de la Vía Bloqueada", intro: "Los signos afectan principalmente un solo ojo, aunque pueden ocurrir en ambos:", groups: [ { name: "Síntomas de desbordamiento (Mecánicos)", items: ["Epífora: Lagrimeo constante y excesivo, las lágrimas ruedan por la mejilla continuamente incluso si el paciente no está llorando o emocionado", "Aparición frecuente de costras gruesas ('lagañas') en las pestañas, dificultando abrir el ojo por las mañanas", "Visión borrosa intermitente causada por el exceso de película lagrimal sobre la superficie del ojo"] }, { name: "Síntomas de complicación inflamatoria (Dacriocistitis)", items: ["Aparición de pus amarillento, mucosidad espesa o secreción verde en la esquina interior del ojo", "Enrojecimiento severo de la parte blanca del ojo y del párpado", "Hinchazón, un bulto rojo muy sensible y doloroso cerca de la esquina interna del ojo, al lado de la nariz (infección aguda del saco lagrimal)", "Fiebre leve o localizada"] } ], warning: "La hinchazón dolorosa extrema y fiebre alrededor del saco lagrimal indica dacriocistitis aguda, requiriendo atención oftalmológica e inicio rápido de antibióticos para prevenir complicaciones graves en los tejidos oculares." }, types: { title: "Clasificación por Edad", intro: "El pronóstico y las causas varían si el problema aparece en el nacimiento o en la edad adulta:", items: ["Congénita (En recién nacidos): Es la más frecuente (afecta a 1 de cada 5 bebés). Usualmente se debe a una membrana delgada que no se rompió para abrir el conducto al momento de nacer. El 90% se abre y cura por sí solo antes del primer año de edad.", "Adquirida (En adultos): Es menos común y ocurre cuando un conducto lagrimal previamente normal se bloquea progresivamente debido a inflamación, envejecimiento o traumatismos. Casi siempre requiere cirugía para resolverse."], note: "El riesgo de obstrucción en adultos es más alto en mujeres mayores debido a que sus conductos son naturalmente más estrechos." }, causes: { title: "Causas y Factores Desencadenantes", intro: "El sistema de canales puede obstruirse por varias patologías subyacentes:", items: ["Desarrollo embrionario incompleto (causa principal en infantes, un bloqueo en la válvula de Hasner)", "Cambios relacionados con la edad (los pequeños orificios u ostium lagrimal se estrechan o colapsan de forma natural con los años en adultos)", "Infecciones crónicas repetidas del ojo (conjuntivitis, herpes ocular) o inflamación crónica de los senos paranasales/nariz", "Traumatismos físicos directos, fracturas o cirugías nasales/faciales previas que aplastaron la vía ósea de drenaje", "Desarrollo de pólipos nasales, tumores, o quistes obstructivos dentro de la cavidad nasal cerca de la salida del conducto", "Uso prolongado de ciertas gotas oculares fuertes (como las usadas para el glaucoma) o toxicidad por tratamientos oncológicos (quimioterapia)"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El oftalmólogo realizará pruebas para localizar exactamente en qué nivel de la tubería está el bloqueo:", items: ["Examen ocular clínico: El médico inspeccionará el párpado, la esquina del ojo, presionará suavemente el saco lagrimal buscando salida de pus, y descartará alergias, glaucoma o córnea dañada.", "Prueba de drenaje de fluoresceína: Se coloca una gota de tinte naranja inofensivo en el ojo. Si tras cinco minutos el ojo sigue lleno de tinte y no ha bajado a la nariz, indica obstrucción clara.", "Sondaje lagrimal e irrigación (en adultos): Procedimiento en el consultorio donde se inyecta suavemente líquido (solución salina) con una jeringa y cánula roma por la esquina del ojo; si el fluido no llega a la garganta del paciente, confirma un bloqueo interno profundo.", "Dacriocistografía o resonancia magnética en casos muy complejos donde se sospecha de un tumor oculto obstruyendo la vía."], note: "Para los bebés, el diagnóstico a menudo es clínico sin requerir irrigación en las visitas pediátricas de rutina." }, treatment: { title: "Manejo desde Masajes hasta Cirugía Reparadora", intro: "El tratamiento va escalando desde opciones conservadoras a procedimientos en quirófano:", subsections: [ { title: "En bebés e infantes", items: ["Observación conservadora: Se prefiere esperar, ya que casi todos se abren naturalmente. Limpiar las costras con agua tibia y gasa estéril.", "Masaje del saco lagrimal (Masaje de Crigler): Presionar firme pero suavemente con el dedo índice hacia abajo en la esquina interna del ojo varias veces al día, buscando crear presión hidrostática que rompa la membrana interna obstruida.", "Sondaje quirúrgico: Si no mejora a los 10-12 meses, un oftalmólogo introducirá con mucha delicadeza un fino alambre de metal bajo anestesia muy breve para destapar la membrana (tasa de éxito del 90%).", "Antibióticos tópicos en gotas o pomada solo si existe una infección activa aguda y purulenta."] }, { title: "En pacientes adultos", items: ["Dacriocistorrinostomía (DCR): La solución definitiva y estándar para conductos totalmente cerrados por años. Se realiza cirugía endoscópica o incisional menor para perforar el hueso y crear un nuevo y permanente desvío de drenaje entre el saco lagrimal bloqueado y la cavidad de la nariz interna.", "Colocación de stents y tubos de silicona temporal o usar globos inflables diminutos para ensanchar y mantener abiertas zonas de estrechamiento parcial o leve."] } ], note: "Cualquier gota antibiótica curará la infección temporal, pero tan pronto como se suspenda, la infección regresará si no se soluciona mecánicamente la obstrucción de fondo." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Oftalmólogo o Pediatra?", intro: "Debe programar una visita con el médico ocular si:", items: ["El ojo (suyo o de su bebé) está constantemente lloroso durante varias semanas, interfiriendo con la visión normal", "Presenta episodios repetidos o frecuentes de conjuntivitis aparente o aparición de 'lagañas' abundantes por la mañana", "Aparece un bulto visible, caliente, hinchado y enrojecido entre el ojo y la nariz que causa dolor al tocarlo (riesgo infeccioso grave)", "El problema persiste en su bebé después de haber cumplido de 9 a 12 meses de edad, a pesar de los masajes en el conducto recomendados"] } },
'Capsulitis adhesiva' : { intro: "La capsulitis adhesiva, ampliamente conocida como 'hombro congelado', es una afección ortopédica dolorosa e incapacitante. Se caracteriza por un endurecimiento rígido extremo y dolor sordo en la articulación del hombro, que avanza muy lentamente durante meses, impidiendo a la persona realizar tareas simples como peinarse o alcanzar un estante alto.", whatIs: { title: "¿Qué es la Capsulitis Adhesiva (Hombro Congelado)?", text: "Es la inflamación, el engrosamiento y la cicatrización progresiva de la cápsula articular del hombro (el envoltorio resistente de tejido conectivo que rodea la articulación y los fluidos lubricantes). Al engrosarse, esta cápsula se encoge alrededor del hueso como una faja rígida, formando adherencias fuertes que bloquean casi todo movimiento articular mecánico." }, symptoms: { title: "Progresión de los Síntomas", intro: "Es un proceso traicionero que evoluciona típicamente a través de tres fases claramente marcadas, que juntas pueden durar de 1 a 3 años:", groups: [ { name: "Etapa de congelamiento (Fase de Dolor: 2 a 9 meses)", items: ["Aparición progresiva y lenta de un dolor sordo y profundo en la parte exterior o frontal del hombro", "El dolor empeora agresivamente con cualquier movimiento o al tratar de estirar el brazo", "Intenso dolor punzante al intentar dormir sobre el hombro afectado por la noche", "Comienza la limitación leve pero progresiva del rango de movimiento"] }, { name: "Etapa congelada (Fase de Rigidez: 4 a 12 meses)", items: ["El dolor en reposo a menudo comienza a disminuir y se vuelve soportable, pero la rigidez se vuelve extrema", "Pérdida dramática y casi total de la movilidad en todas las direcciones (incapacidad total de levantar el brazo lateralmente o rotarlo detrás de la espalda)", "Uso forzado de los músculos del cuello y espalda para intentar compensar y mover el brazo (encogimiento de hombros)"] }, { name: "Etapa de descongelamiento (Fase de Recuperación: 5 a 24 meses)", items: ["El rango de movimiento comienza a regresar lenta y gradualmente", "La rigidez desaparece progresivamente hasta que se logra la normalidad o casi normalidad articular"] } ], warning: "Si hay un dolor insoportable y debilidad profunda que aparece justo después de un traumatismo agudo o una caída severa, podría ser un desgarro grave del manguito rotador, no un hombro congelado." }, types: { title: "Asociaciones Clínicas", intro: "A menudo se cataloga en función de cómo comenzó la inflamación:", items: ["Primaria (Idiopática): La condición comienza de forma espontánea y progresiva sin ningún factor desencadenante o lesión evidente. Es el tipo más frustrante.", "Secundaria: Se desarrolla tras un evento conocido, como una lesión directa de hombro, una inmovilización prolongada en cabestrillo tras una cirugía de brazo, o tras un ACV (derrame cerebral) que paraliza el movimiento de la extremidad superior.", "Sistémica: Fuertemente vinculada a otras enfermedades metabólicas o crónicas subyacentes del paciente."], note: "Curiosamente, es mucho más prevalente en mujeres y suele presentarse en personas de entre 40 y 60 años." }, causes: { title: "Causas y Poblaciones de Alto Riesgo", intro: "Aunque la ciencia no entiende completamente por qué la cápsula se inflama y se vuelve fibrótica, los riesgos están clarísimos:", items: ["Diabetes Mellitus: Es el factor de riesgo número uno; hasta el 20% de los pacientes diabéticos sufren de hombro congelado y, a menudo, es más grave y resistente al tratamiento.", "Inmovilidad física forzada: Cualquier inmovilización tras una cirugía mamaria (mastectomía), fractura de brazo, rotura del manguito rotador o ACV fomenta el endurecimiento masivo y rápido de la cápsula inactiva.", "Trastornos endocrinos de la tiroides (tanto hipotiroidismo como hipertiroidismo).", "Enfermedades cardiovasculares crónicas y la enfermedad de Parkinson parecen mostrar una mayor asociación clínica.", "No está causado por usar demasiado el brazo (sobreuso mecánico), y generalmente, el brazo dominante se ve menos afectado que el otro."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El diagnóstico es inminentemente clínico, basado en los hallazgos mecánicos en la consulta médica:", items: ["Examen físico específico del médico traumatólogo: La prueba definitiva y clave es evaluar tanto la movilidad 'activa' (cuando el paciente mueve el brazo solo) como la movilidad 'pasiva' (cuando el paciente se relaja por completo y el médico intenta levantar y rotar el brazo).", "La marca diagnóstica distintiva: En el hombro congelado verdadero, ni siquiera el médico con fuerza externa puede levantar o rotar el brazo del paciente más allá de cierto límite porque el tejido articular rígido se lo impide mecánicamente.", "Radiografías de hombro: Generalmente se solicitan solo para descartar que el bloqueo del brazo no sea culpa de una artritis degenerativa severa o un crecimiento de hueso (espolón).", "Resonancia magnética (RM) y Ecografía: Usadas en casos confusos para descartar roturas masivas de tendones en el manguito rotador."], note: "A diferencia del desgarro del tendón (donde el paciente no puede moverlo, pero el médico sí puede levantar el brazo flácido), en la capsulitis ni el médico puede moverlo." }, treatment: { title: "Manejo Fisioterapéutico, Dolor y Procedimientos Avanzados", intro: "El tratamiento requiere paciencia profunda y se enfoca en controlar el dolor hasta lograr restaurar la movilidad articular final:", subsections: [ { title: "Terapias escalonadas de tratamiento", items: ["Medicamentos antiinflamatorios (AINEs) o analgésicos fuertes en la etapa inicial de 'congelamiento' intenso para poder conciliar el sueño.", "Inyecciones intrarticulares de corticosteroides (Cortisona): Sumamente efectivas si se inyectan en la primera fase para detener rápidamente el dolor inflamatorio masivo, aunque solas no curan la rigidez estructural.", "Fisioterapia rigurosa, continua y progresiva (El pilar central): Realización de ejercicios pasivos de estiramiento forzado tolerables bajo supervisión o en el hogar (ejercicios de polea, escalada de pared, estiramiento de la cápsula) una vez que el dolor agudo cede.", "Distensión articular (Hidrodilatación): Un radiólogo inyecta una mezcla enorme de líquido esterilizado, esteroides y anestesia directa y profundamente en el hombro guiado por ultrasonido para intentar 'estirar' la cápsula desde el interior con la presión y romper las adherencias restrictivas.", "Manipulación del hombro bajo anestesia general: En casos crónicos rebeldes. El paciente está dormido y relajado mientras el cirujano tuerce fuertemente el brazo para desgarrar físicamente los cordones de tejido cicatricial congelado.", "Cirugía por Artroscopia de hombro: Procedimiento de último recurso, mínimamente invasivo, donde el cirujano inserta instrumentos muy finos con luz para cortar selectivamente porciones tensas profundas de la cápsula rígida y liberar totalmente el movimiento bloqueado."] } ], note: "La gran mayoría de los pacientes consiguen la recuperación casi total dentro de 1 a 2 años solo con fisioterapia constante e inyecciones de cortisona sin recurrir al quirófano." }, whenToSeekHelp: { title: "¿Cuándo Contactar al Traumatólogo de Forma Oportuna?", intro: "Consulte a su médico o a un ortopedista deportivo especializado prontamente si:", items: ["El dolor es tan intenso y profundo a lo largo de su brazo u hombro que perturba drásticamente sus noches impidiendo su descanso", "Descubre de repente y de manera evidente que no puede realizar tareas antes sencillas y cotidianas (como abrochar el sujetador en la espalda, pasarse un peine o ponerse un cinturón en el coche)", "Notablemente pierde un grado alarmante de movimiento físico por semanas y empieza a encoger los músculos del cuello con esfuerzo visible tratando de mover el codo hacia adelante u hacia la parte de arriba lateral", "Posee antecedente crítico previo diabético o acaba de pasar por alguna cirugía reciente inmovilizadora o derrame donde mantuvieron inactivo su hombro general durante largo tiempo"] } },
'Sordera' : { intro: "La sordera, o pérdida de la capacidad auditiva, es una afección que impide percibir los sonidos parcial o totalmente. Puede afectar a uno o ambos oídos y tiene un impacto profundo en la comunicación, el aprendizaje y la interacción social si no se maneja adecuadamente.", whatIs: { title: "¿Qué es la Sordera o Pérdida Auditiva?", text: "Es la disminución o pérdida completa de la capacidad para oír. Se produce cuando hay un problema o daño en alguna parte del oído (externo, medio o interno), en el nervio auditivo o en las vías cerebrales que procesan el sonido." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Los signos varían desde leves dificultades hasta la pérdida total:", groups: [ { name: "Problemas de percepción", items: ["Dificultad para entender palabras, especialmente con ruido de fondo o en multitudes", "Tener que pedir frecuentemente a los demás que hablen más despacio, más claro o que repitan", "Necesidad de subir el volumen de la televisión o la radio a niveles que resultan inusualmente altos para otros"] }, { name: "Síntomas asociados", items: ["Zumbidos, silbidos o pitidos constantes en los oídos (tinnitus)", "Sensación de tener el oído tapado o lleno", "Aislamiento social y fatiga por el gran esfuerzo mental que requiere intentar escuchar y comprender"] } ], warning: "La pérdida de audición súbita en uno o ambos oídos es una urgencia médica que debe ser evaluada por un otorrinolaringólogo en menos de 48 horas para intentar revertir el daño." }, types: { title: "Tipos de Pérdida Auditiva", intro: "Se clasifica según la parte del sistema auditivo afectada:", items: ["Hipoacusia conductiva: Problema en el oído externo o medio que bloquea el paso del sonido (ej. tapón de cerumen, líquido, huesos dañados). Suele ser reversible médica o quirúrgicamente.", "Hipoacusia neurosensorial: Daño en el oído interno (cóclea) o en el nervio auditivo. Es la más común en adultos y suele ser permanente.", "Hipoacusia mixta: Una combinación de pérdida conductiva y neurosensorial en el mismo oído."], note: "El grado de pérdida se clasifica en leve, moderado, severo o profundo según el volumen de decibelios que la persona no puede percibir." }, causes: { title: "Causas y Factores de Riesgo", intro: "La audición puede dañarse por factores mecánicos, ambientales o del envejecimiento:", items: ["Presbiacusia (envejecimiento natural): Desgaste gradual de las células ciliadas del oído interno con la edad.", "Exposición crónica al ruido (trauma acústico): Uso de auriculares a volumen alto, maquinaria pesada, conciertos o disparos sin protección.", "Genética e historia familiar de sordera.", "Infecciones: Otitis media crónica, meningitis, sarampión o paperas.", "Medicamentos ototóxicos: Algunos antibióticos muy potentes y medicamentos de quimioterapia que dañan el oído interno.", "Traumatismos craneoencefálicos o perforaciones del tímpano."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un audiólogo u otorrinolaringólogo realizará pruebas especializadas indoloras:", items: ["Otoscopia: Examen visual del canal auditivo y el tímpano para buscar cera, inflamación o daños físicos.", "Audiometría tonal: La prueba estándar en una cabina insonorizada. El paciente usa auriculares y señala cada vez que escucha tonos en diferentes frecuencias y volúmenes.", "Timpanometría: Mide el movimiento del tímpano para detectar líquido en el oído medio.", "Pruebas de emisiones otoacústicas y respuestas auditivas del tronco encefálico (BERA/PEATC) para evaluar la vía nerviosa, usadas comúnmente en recién nacidos."], note: "El cribado auditivo neonatal (en las primeras semanas de vida) es vital para asegurar el desarrollo del lenguaje en los bebés." }, treatment: { title: "Ayudas Auditivas y Tratamientos", intro: "El tratamiento depende directamente de la causa y el tipo de sordera:", subsections: [ { title: "Opciones tecnológicas y médicas", items: ["Extracción de tapones de cera o tratamiento con antibióticos para infecciones de oído (soluciona rápidamente pérdidas conductivas simples).", "Audífonos digitales (Auxiliares auditivos): Dispositivos que se colocan dentro o detrás de la oreja para amplificar el sonido y mejorar la claridad en sorderas neurosensoriales.", "Implantes cocleares: Dispositivos quirúrgicos avanzados para sorderas severas o profundas que puentean el oído dañado y estimulan directamente el nervio auditivo.", "Cirugía de oído: Para reparar tímpanos perforados (timpanoplastia) o corregir huesos rígidos en el oído medio (estapedectomía).", "Sistemas de asistencia: Implantes osteointegrados (BAHA), lectura de labios, y aprendizaje de lengua de signos para apoyo comunicativo."] } ], note: "El uso de audífonos modernos no solo mejora la audición, sino que previene el aislamiento social y ralentiza el deterioro cognitivo en adultos mayores." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Otorrinolaringólogo?", intro: "Es fundamental realizar una evaluación auditiva si:", items: ["Experimenta una pérdida de audición brusca, repentina o inexplicable de un día para otro", "Presenta dolor de oído intenso, supuración de líquido, sangre o pus", "Tiene un zumbido agudo o rugido (tinnitus) constante que interfiere con su sueño o concentración", "Sufre de mareos intensos, pérdida de equilibrio o vértigo asociados a la disminución auditiva"] } },
'Dolor terminal' : { intro: "El dolor terminal, o dolor al final de la vida, es un dolor crónico, complejo e intenso asociado con las etapas finales de enfermedades incurables avanzadas. Su adecuado manejo es la piedra angular de los cuidados paliativos, asegurando que el paciente pase sus últimos días con la mayor dignidad, confort y paz posibles, libre de sufrimiento evitable.", whatIs: { title: "¿Qué es el Dolor Terminal?", text: "Es el dolor profundo e incapacitante que experimentan los pacientes en fase terminal de enfermedades graves (como cáncer metastásico avanzado, insuficiencia cardíaca terminal o ELA). No es solo físico; es un concepto de 'dolor total' que abarca la angustia psicológica, social y espiritual de enfrentarse al final de la vida." }, symptoms: { title: "Características del Dolor y Sufrimiento", intro: "El dolor en cuidados paliativos tiene patrones específicos que requieren vigilancia continua:", groups: [ { name: "Tipos de crisis físicas", items: ["Dolor basal constante: Un dolor continuo, de fondo y predecible que está presente la mayor parte del día", "Dolor irruptivo: Picos de dolor agudo, repentino, punzante y severo que 'rompen' el efecto de la medicación analgésica basal", "Dolor incidental: Picos de dolor causados por actividades necesarias, como girarse en la cama, toser o recibir curaciones"] }, { name: "Sufrimiento asociado (Dolor Total)", items: ["Ansiedad severa, agitación o delirio causado por el dolor no controlado", "Depresión profunda, miedo a la muerte y sensación de pérdida de autonomía", "Disnea (falta de aire asfixiante) y fatiga extrema que acompañan y empeoran la percepción del dolor"] } ], warning: "Ningún paciente terminal debe 'soportar' el dolor con estoicismo; la falta de alivio del dolor al final de la vida es una urgencia paliativa que debe tratarse con medicamentos fuertes de forma inmediata." }, types: { title: "Mecanismos Físicos del Dolor", intro: "Clínicamente, el médico clasifica el dolor para recetar el fármaco correcto:", items: ["Dolor nociceptivo somático: Daño en los tejidos, huesos o músculos (ej. metástasis óseas). Suele ser constante y punzante.", "Dolor nociceptivo visceral: Afecta los órganos internos (ej. tumor en el hígado o páncreas). Suele sentirse como cólicos profundos o presión difusa.", "Dolor neuropático: Causado por nervios dañados o aplastados por tumores. Se describe como quemazón, ardor hirviente o descargas eléctricas agudas."], note: "Es extremadamente común que el paciente paliativo experimente los tres tipos de dolor simultáneamente." }, causes: { title: "Causas y Origen del Sufrimiento", intro: "El dolor terminal se origina por la enfermedad en sí y las complicaciones de la postración:", items: ["El crecimiento tumoral directo (el cáncer comprime nervios vitales, invade huesos frágiles o bloquea órganos e intestinos)", "Complicaciones debidas a la inmovilidad prolongada (formación de escaras dolorosas o úlceras por presión profunda en la piel)", "Espasmos musculares severos o rigidez articular debido a la falta de movimiento o debilidad", "Secuelas permanentes de tratamientos invasivos previos (dolor crónico por radiación, cicatrices quirúrgicas o neuropatía inducida por quimioterapia)"] }, diagnosis: { title: "¿Cómo se Evalúa y Mide?", intro: "Dado que el dolor es subjetivo, la comunicación es vital. El equipo paliativo evalúa mediante:", items: ["Escalas de dolor: Uso frecuente de la escala del 0 al 10, o escalas visuales de caras si el paciente tiene dificultad para hablar", "Evaluación observacional: Si el paciente está inconsciente o sufre demencia, el personal evaluará gestos de dolor (ceño fruncido, quejidos, rigidez corporal, respiración agitada)", "Evaluación del 'Dolor Total': Entrevistas con psicólogos y trabajadores sociales para medir el nivel de sufrimiento emocional, miedos no resueltos y angustia espiritual de la familia y el paciente"], note: "La evaluación del dolor se realiza a diario y a veces cada hora, ajustando las dosis de rescate según la necesidad del momento." }, treatment: { title: "Manejo Paliativo y Analgesia Avanzada", intro: "El objetivo es el confort absoluto. El miedo a la 'adicción' no tiene relevancia en el manejo del dolor terminal:", subsections: [ { title: "Escalera analgésica e intervenciones", items: ["Opioides fuertes (La piedra angular): Fármacos como la morfina, fentanilo, metadona o buprenorfina. Se administran en parches, gotas sublinguales, o mediante bombas de infusión subcutánea/intravenosa continua que liberan medicación constante 24/7.", "Dosis de rescate ('Bolos'): Dosis adicionales rápidas de opioides de acción ultrarrápida que se administran cuando ocurre una crisis de dolor irruptivo agudo.", "Medicamentos coadyuvantes: Anticonvulsivos o antidepresivos para calmar el dolor neuropático (de nervios), esteroides (dexametasona) para reducir la inflamación tumoral, y bifosfonatos para aliviar el dolor de huesos.", "Bloqueos nerviosos o anestesia regional: Intervenciones donde un especialista en dolor inyecta anestésicos directamente en los nervios o la médula espinal para adormecer zonas grandes intratables.", "Sedación paliativa: En las horas o días finales, si el sufrimiento o la asfixia son completamente refractarios (imposibles de controlar), se induce médicamente el sueño profundo para asegurar una transición sin angustia ni dolor consciente."] } ], note: "El control del dolor casi siempre viene acompañado de tratamiento estricto para evitar el estreñimiento severo y las náuseas causados por los opioides." }, whenToSeekHelp: { title: "¿Cuándo Avisar al Equipo Paliativo?", intro: "Los cuidadores familiares deben contactar de urgencia a su médico u hospicio si el paciente:", items: ["Muestra signos de dolor irruptivo severo que no disminuye 30 minutos después de administrar la dosis de rescate habitual", "Presenta efectos secundarios angustiantes por los analgésicos, como vómitos imparables, delirio alucinatorio, o estreñimiento de varios días", "Tiene dificultad visible y agónica para respirar o ahogo", "El paciente o la familia están emocionalmente desbordados y necesitan asistencia psicosocial de emergencia"] } },
'Síndrome del intestino irritable' : { intro: "El Síndrome del Intestino Irritable (SII) es un trastorno gastrointestinal funcional extremadamente común y crónico. Aunque causa calambres abdominales dolorosos, hinchazón severa y alteraciones impredecibles del tránsito intestinal (diarrea o estreñimiento), a diferencia de otras enfermedades, no provoca daños estructurales ni inflamación visible en el tracto digestivo.", whatIs: { title: "¿Qué es el Síndrome del Intestino Irritable (SII)?", text: "Es un trastorno funcional del sistema digestivo; es decir, el intestino se ve normal en las pruebas médicas, pero no funciona normalmente. Existe un problema de comunicación en el eje 'cerebro-intestino', haciendo que los músculos del colon sean hipersensibles y se contraigan de forma desordenada o espasmódica." }, symptoms: { title: "Síntomas y Molestias Digestivas", intro: "Los síntomas varían en gravedad y tienden a aparecer y desaparecer (brotes), exacerbados por la comida o el estrés:", groups: [ { name: "Síntomas abdominales principales", items: ["Dolor abdominal tipo cólico o calambre, frecuentemente localizado en la parte inferior, que suele aliviarse (parcial o totalmente) al defecar o expulsar gases", "Exceso de gases crónico y distensión abdominal (hinchazón masiva, a menudo empeorando a lo largo del día)", "Sensación constante de evacuación incompleta (sentir que aún necesita ir al baño después de haberlo hecho)"] }, { name: "Alteraciones en las heces", items: ["Diarrea repentina, a menudo con necesidad urgente de correr al baño, especialmente por las mañanas o después de comer", "Estreñimiento persistente, con heces duras o en forma de bolitas, requiriendo gran esfuerzo", "Aparición de moco blanco o transparente recubriendo las heces (muy característico, pero inofensivo en el SII)"] } ], warning: "El SII NO causa sangrado rectal, fiebre ni pérdida de peso involuntaria. Si estos síntomas de 'alarma' están presentes, se debe descartar una enfermedad inflamatoria intestinal o cáncer." }, types: { title: "Subtipos Clínicos de SII", intro: "Para recetar el tratamiento correcto, los gastroenterólogos clasifican el SII según el patrón de las heces:", items: ["SII con predominio de diarrea (SII-D): Frecuentes evacuaciones sueltas, acuosas y urgencia apremiante.", "SII con predominio de estreñimiento (SII-C): Esfuerzo prolongado, heces duras, poco frecuentes y dolor abdominal bloqueante.", "SII con hábitos intestinales mixtos (SII-M): El paciente alterna caóticamente entre episodios de diarrea severa y estreñimiento profundo.", "SII no clasificado (SII-U): Los síntomas no encajan claramente en las categorías anteriores, pero existe el dolor funcional clásico."], note: "Una persona puede cambiar de un subtipo a otro a lo largo de los años." }, causes: { title: "Causas y Desencadenantes", intro: "No existe una causa única; el SII es el resultado de múltiples factores neurológicos y digestivos:", items: ["Contracciones musculares anormales: El colon se contrae con demasiada fuerza (causando diarrea y dolor) o muy débilmente (causando estreñimiento).", "Hipersensibilidad visceral (nerviosa): Los nervios intestinales son extremadamente sensibles, percibiendo el gas normal como un dolor insoportable (anomalía cerebro-intestino).", "Infección intestinal grave previa (Gastroenteritis aguda): Un ataque severo de bacterias o virus puede desencadenar un SII permanente meses después (SII postinfeccioso).", "Desencadenantes dietéticos: Intolerancias fermentativas a ciertos carbohidratos complejos (los alimentos FODMAPs, como ajo, cebolla, trigo, lácteos, legumbres o edulcorantes artificiales).", "Desencadenantes emocionales: El estrés agudo crónico, la ansiedad y la depresión no causan el SII, pero sus picos empeoran dramáticamente los brotes."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico de exclusión basado en criterios clínicos estrictos (Criterios de Roma IV):", items: ["Evaluación del patrón de dolor: Dolor abdominal recurrente, en promedio al menos 1 día a la semana durante los últimos 3 meses, asociado con la defecación o cambios en la forma/frecuencia de las heces.", "Análisis de sangre y heces: Principalmente para excluir activamente anemia, parásitos, marcadores de inflamación (calprotectina) y la enfermedad celíaca.", "Colonoscopia o endoscopia superior: Generalmente NO se necesitan en pacientes jóvenes con síntomas típicos, pero se realizan en mayores de 50 años o en quienes presentan síntomas de alarma para descartar cáncer de colon o colitis ulcerosa.", "Pruebas de intolerancia a la lactosa o sobrecrecimiento bacteriano (SIBO)."], note: "Un diagnóstico de SII es positivo; significa que su intestino está estructuralmente sano y a salvo de enfermedades letales." }, treatment: { title: "Manejo Nutricional y Farmacológico", intro: "El tratamiento es altamente personalizado, enfocado en controlar los síntomas para recuperar la calidad de vida:", subsections: [ { title: "Dieta, medicamentos y mente", items: ["Dieta baja en FODMAPs: La intervención nutricional más exitosa. Guiada por un nutricionista, se eliminan temporalmente alimentos altamente fermentables (cebolla, lácteos, trigo, ciertas frutas) y se reintroducen lentamente para identificar intolerancias exactas.", "Fibras solubles (como el psyllium): Para ayudar a suavizar el estreñimiento sin generar exceso de gases.", "Medicamentos antiespasmódicos (mebeverina, pinaverio): Para relajar el músculo intestinal y cortar el cólico de raíz.", "Para SII-D (diarrea): Antidiarreicos (loperamida), resinas fijadoras de ácidos biliares o antibióticos específicos no absorbibles (rifaximina) para equilibrar la flora.", "Para SII-C (estreñimiento): Laxantes osmóticos suaves o medicamentos modernos (linaclotida) que aumentan la secreción de líquido en el intestino.", "Neuromoduladores (Antidepresivos en dosis bajas): Ayudan a 'silenciar' los nervios hipersensibles del intestino para el dolor crónico.", "Terapia psicológica (TCC o hipnoterapia dirigida al intestino) para controlar la ansiedad que detona los episodios."] } ], note: "Llevar un diario detallado de alimentos, síntomas y estados de ánimo es esencial para que el médico identifique sus detonantes personales." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Gastroenterológica?", intro: "Consulte a un médico de forma urgente si sus síntomas de intestino irritable están acompañados de las siguientes 'banderas rojas':", items: ["Sangrado rectal evidente o heces de color negro muy oscuro (alquitrán)", "Pérdida de peso involuntaria sin estar a dieta", "El dolor abdominal es tan severo que lo despierta a mitad de la noche (el SII típico rara vez interrumpe el sueño profundo)", "Presenta fiebre persistente, vómitos, o si tiene más de 50 años y es la primera vez que experimenta estos cambios intestinales"] } },
'Hiperhidrosis' : { intro: "La hiperhidrosis es una condición médica caracterizada por una sudoración anormal, excesiva e impredecible que supera con creces lo que el cuerpo necesita para regular su temperatura. Provoca humedad constante en manos, axilas o pies, generando una profunda vergüenza, ansiedad social y dificultades en las actividades diarias.", whatIs: { title: "¿Qué es la Hiperhidrosis?", text: "Es un trastorno hiperactivo de las glándulas sudoríparas (principalmente las glándulas ecrinas). En esta afección, los nervios que envían señales a las glándulas sudoríparas se 'encienden' y trabajan constantemente a máxima capacidad, incluso cuando la persona está en reposo y en un ambiente fresco." }, symptoms: { title: "Síntomas y Retos Cotidianos", intro: "La sudoración es lo suficientemente profusa como para gotear e interferir con la vida normal:", groups: [ { name: "Manifestaciones físicas", items: ["Sudoración extrema que empapa frecuentemente la ropa, requiriendo cambios de camisa varias veces al día", "Palmas de las manos constantemente frías, resbaladizas y húmedas (a menudo goteando líquido)", "Plantas de los pies empapadas en sudor, lo que arruina el calzado y favorece infecciones por hongos (pie de atleta) y mal olor crónico", "Sudor incontrolable en el rostro o la frente ante la más mínima situación de estrés social"] }, { name: "Impacto psicosocial limitante", items: ["Ansiedad social profunda, fobia y evitación extrema del contacto físico (como negarse a dar un apretón de manos)", "Dificultad mecánica para realizar tareas diarias (las manos mojadas resbalan en el teclado, el volante, herramientas, o manchan los papeles al escribir)", "Infecciones recurrentes de la piel en áreas constantemente húmedas (ingles, axilas)"] } ], warning: "La sudoración excesiva de aparición brusca en un adulto, especialmente si ocurre empapando las sábanas por la noche, es un síntoma de alarma que requiere evaluación para descartar infecciones ocultas, problemas de tiroides o linfomas." }, types: { title: "Clasificación Principal", intro: "Se divide en dos tipos según su origen y extensión en el cuerpo:", items: ["Hiperhidrosis Focal Primaria: Es la forma más común. Afecta áreas muy específicas y simétricas (ambas palmas de las manos, ambas plantas de los pies, ambas axilas o el rostro). Comienza generalmente en la infancia o la adolescencia. Ocurre sin ninguna otra afección médica subyacente.", "Hiperhidrosis Generalizada Secundaria: La sudoración excesiva ocurre por todo el cuerpo, no solo en áreas focales, y es un síntoma causado por otra enfermedad médica subyacente o un medicamento. Suele comenzar en la edad adulta y puede manifestarse intensamente mientras se duerme."], note: "El tipo focal primario rara vez ocurre durante el sueño profundo; el paciente suele despertar seco y comienza a sudar al estar alerta." }, causes: { title: "Causas Sistémicas y Nerviosas", intro: "Los factores desencadenantes difieren según el tipo de hiperhidrosis:", items: ["Causa Primaria (Focal): Defecto genético heredado en el sistema nervioso simpático que sobreestimula las glándulas sudoríparas. Empeora drásticamente con la ansiedad, el nerviosismo o emociones fuertes, creando un círculo vicioso de estrés y sudor.", "Causas Secundarias (Generalizada): Problemas hormonales (hipertiroidismo, menopausia con sofocos severos).", "Enfermedades infecciosas graves (tuberculosis, endocarditis) u oncológicas (leucemia, linfoma de Hodgkin).", "Efecto secundario de medicamentos (especialmente ciertos antidepresivos ISRS, medicamentos para la diabetes o tratamientos oncológicos).", "Trastornos neurológicos periféricos o enfermedad de Parkinson."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El dermatólogo confirmará la gravedad y descartará causas secundarias mediante:", items: ["Examen físico clínico enfocado en el patrón de la sudoración (simétrico vs asimétrico, focal vs generalizado).", "Prueba de yodo-almidón: El médico aplica yodo en la piel sudorosa y espolvorea almidón; las zonas de sudoración extrema se vuelven azul oscuro/negro intenso, ayudando a mapear el área a tratar.", "Prueba de papel de filtro: Se pesa un papel antes y después de colocarlo sobre el área sudorosa para cuantificar el volumen exacto de sudor producido.", "Análisis de sangre y orina: Obligatorios en adultos con aparición reciente para descartar hiperactividad de la tiroides (TSH), hipoglucemia, o infecciones latentes."], note: "Saber si hay un patrón familiar es clave, ya que gran parte de los pacientes focales tienen un padre o hermano con el mismo problema." }, treatment: { title: "Manejo y Terapias Clínicas", intro: "Existen múltiples escalones de tratamiento, comenzando desde lo tópico hasta lo quirúrgico:", subsections: [ { title: "Escalones de tratamiento dermatológico", items: ["Antitranspirantes clínicos recetados (Cloruro de aluminio hexahidratado): Se aplican de noche sobre piel seca; bloquean físicamente los poros del sudor (pueden causar irritación severa en la piel si se aplican mal).", "Iontoforesis: Un dispositivo médico casero que pasa una corriente eléctrica leve a través del agua donde el paciente sumerge sus manos o pies. Se realiza semanalmente e inactiva temporalmente las glándulas sudoríparas.", "Inyecciones de Toxina Botulínica (Botox): Tratamiento altamente efectivo (estándar de oro para axilas); las inyecciones bloquean temporalmente el nervio que activa el sudor, logrando sequedad total por 6 a 12 meses.", "Medicamentos anticolinérgicos orales (como la oxibutinina): Pastillas que secan las secreciones del cuerpo (sudor, pero también saliva y lágrimas).", "Terapias con microondas (miraDry): Destruye permanentemente las glándulas sudoríparas en las axilas con energía térmica.", "Simpatectomía Torácica Endoscópica (STE): Cirugía definitiva de último recurso. Se cortan o pinzan los nervios simpáticos en el pecho responsables del sudor de las manos. Puede provocar sudoración compensatoria grave (sudar masivamente en espalda o muslos)."] } ], note: "El Botox ha transformado la vida de los pacientes, ofreciendo resultados casi inmediatos con mínimos efectos secundarios locales." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Dermatólogo o Médico General?", intro: "Se debe buscar intervención médica seria si el sudor:", items: ["Interfiere severamente o imposibilita su rutina diaria, su trabajo, o lo ha vuelto fóbico al contacto social", "Se produce en forma de sudores fríos nocturnos empapadores que lo despiertan y lo obligan a cambiar las sábanas (bandera roja)", "Comenzó de manera repentina y generalizada a lo largo de todo el cuerpo en la edad adulta", "Va acompañado de pérdida de peso inexplicable, palpitaciones, dolor de pecho o fiebre constante"] } },
'Displasia del desarrollo de la cadera' : { intro: "La displasia del desarrollo de la cadera (DDC) es una anomalía frecuente en bebés donde la articulación de la cadera no se forma correctamente. Puede ser desde una ligera inestabilidad hasta una dislocación completa de la pierna. Su detección en los primeros meses de vida es esencial para prevenir cojera permanente y artritis dolorosa en la edad adulta.", whatIs: { title: "¿Qué es la Displasia de Cadera (DDC)?", text: "Es una afección ortopédica infantil donde la 'bola' superior del hueso del muslo (cabeza del fémur) no encaja firmemente y de manera profunda en la 'cavidad' de la pelvis (el acetábulo). La cavidad suele ser demasiado plana, permitiendo que el fémur se deslice parcial o totalmente fuera de su lugar." }, symptoms: { title: "Signos Clínicos en Bebés y Niños", intro: "La DDC es silenciosa y no le causa dolor al bebé, por lo que el pediatra y los padres deben observar signos anatómicos:", groups: [ { name: "En recién nacidos y lactantes (hasta los 6 meses)", items: ["Inestabilidad: Un 'clic' o 'chasquido' sordo que el médico o los padres sienten al abrir o separar las piernas del bebé para cambiarle el pañal", "Asimetría en los pliegues cutáneos de los muslos o nalgas (un lado tiene más rollitos que el otro)", "Restricción de movimiento: Una pierna (la cadera afectada) no se puede abrir o separar hacia afuera tan ampliamente como la otra", "Una pierna parece visiblemente más corta que la otra"] }, { name: "En niños mayores que ya caminan", items: ["Cojera evidente o marcha de pato ('marcha de Trendelenburg' si afecta ambas caderas)", "Caminar apoyándose en la punta del pie en el lado afectado para compensar la diferencia de longitud", "Curvatura exagerada de la espalda baja (hiperlordosis lumbar)"] } ], warning: "Cualquier asimetría al abrir las piernitas del bebé al cambiar el pañal debe ser informada al pediatra de inmediato, ya que el tratamiento temprano es la clave del éxito curativo." }, types: { title: "Grados de Severidad", intro: "La malformación se presenta en un espectro de gravedad progresiva:", items: ["Cadera displásica o inmadura: La cavidad pélvica es plana, pero la bola está en su lugar. Puede estabilizarse sola con el crecimiento inicial.", "Cadera subluxable/luxable: La bola está en el acetábulo pero está suelta, y puede empujarse temporalmente hacia afuera durante el examen médico.", "Subluxación: La cabeza del fémur está parcialmente fuera de la cavidad, pero mantiene cierto contacto.", "Luxación franca (Dislocación): La cabeza del fémur está completamente fuera de la cavidad pélvica y reposa en un lugar anormal superior."], note: "Afecta el lado izquierdo con mayor frecuencia que el derecho, y es de cuatro a cinco veces más común en niñas que en niños." }, causes: { title: "Factores de Riesgo Anatómicos y del Embarazo", intro: "Se debe a factores mecánicos que aprietan o aflojan las caderas antes o después del nacimiento:", items: ["Presentación de nalgas (posición podálica): El mayor factor de riesgo. Los bebés sentados en el útero en el último trimestre sufren fuerzas que estiran las cápsulas de la cadera fuera de lugar.", "Antecedentes familiares (genética): Alta probabilidad si padres o hermanos tuvieron DDC.", "Sexo femenino (las niñas responden fuertemente a las hormonas relaxinas de la madre, aflojando excesivamente sus ligamentos).", "Oligohidramnios: Poco líquido amniótico durante el embarazo restringe severamente el espacio de movimiento del feto.", "Prácticas de crianza perjudiciales: Envolver al bebé apretadamente con las piernas extendidas y juntas (swaddling extremo tradicional) impide el sano desarrollo de la cavidad."] }, diagnosis: { title: "¿Cómo se Detecta y Confirma?", intro: "La detección requiere maniobras físicas expertas y luego se confirma con imágenes radiológicas:", items: ["Maniobras pediátricas (Ortolani y Barlow): El pediatra en cada visita de niño sano rota suavemente las caderas del recién nacido para sentir si la articulación se sale (Barlow) o se vuelve a encajar con un clonk (Ortolani).", "Prueba de Galeazzi/Allis: Doblar las rodillas del bebé acostado para comprobar si una está más baja que la otra (indicativo de dislocación).", "Ecografía de caderas: La herramienta de oro diagnóstica para bebés de 1 a 4 meses de edad. El cartílago del bebé no se ve en rayos X; el ultrasonido revela la estructura y posición con total claridad.", "Radiografía de pelvis: Prueba definitiva a partir de los 4 a 6 meses de edad, cuando el cartílago comienza a osificarse y formarse hueso visible."], note: "Los exámenes de rutina a menudo no son suficientes; cualquier bebé con factores de riesgo (especialmente niñas de nalgas) debe recibir una ecografía obligatoria a las 6 semanas de vida." }, treatment: { title: "Arneses, Reducción y Cirugía Ortopédica", intro: "El éxito depende directamente de la edad de inicio; cuanto más temprano, menos invasivo:", subsections: [ { title: "Ruta terapéutica temporal", items: ["Desde el nacimiento hasta los 6 meses (Arnés de Pavlik): Tratamiento estándar. Es un sistema de correas suaves que mantiene las caderas del bebé flexionadas y abiertas (posición de rana). Al mantener la bola centrada, la cavidad pélvica se moldea y profundiza de forma natural en unas pocas semanas (90% de éxito).", "De 6 meses a 2 años (Reducción cerrada y Yeso Espica): Si el arnés falla o se diagnosticó tarde. Bajo anestesia general, el ortopedista manipula la cadera suavemente para ponerla en su lugar y coloca un yeso corporal desde el pecho hasta los tobillos durante meses para fijarla.", "A partir de los 2 años o casos complejos (Reducción abierta/Osteotomía): Cirugía mayor ortopédica para limpiar tejido bloqueante, alargar tendones, reubicar el hueso manualmente y, a menudo, cortar y reorientar el fémur o el hueso pélvico para reconstruir el techo de la cadera, seguido de un yeso espica."] } ], note: "Incluso después de un tratamiento infantil exitoso, el paciente requerirá seguimientos ortopédicos periódicos hasta alcanzar la edad adulta para asegurar que el hueso madura rectamente." }, whenToSeekHelp: { title: "¿Cuándo Solicitar Evaluación Ortopédica?", intro: "Es crucial pedir a su pediatra una derivación si usted detecta al vestir a su bebé:", items: ["Que un pliegue grueso de grasa en el muslo interno no tiene un pliegue idéntico en la misma altura del otro muslo", "Siente un crujido o sonido de 'clic' sordo cada vez que separa las piernas del bebé al limpiar sus genitales", "Al bañar al bebé y doblar sus rodillas juntas, una rodilla se ve claramente más baja que la compañera", "Si su bebé ya camina, nota que cojea, se tambalea significativamente o arrastra un pie"] } },
'Lesión corneal' : { intro: "Una lesión corneal, comúnmente una abrasión corneal, es un rasguño u herida superficial en el domo transparente del ojo. Debido a la inmensa cantidad de terminaciones nerviosas en la córnea, un raspón minúsculo causa un dolor intenso y abrumador, sensación de cuerpo extraño y un lagrimeo constante y profuso.", whatIs: { title: "¿Qué es una Abrasión o Lesión Corneal?", text: "Es la pérdida o disrupción de la capa epitelial superficial (la 'piel') de la córnea debido a un trauma físico mecánico o químico. La córnea es la ventana transparente frontal del ojo que refracta la luz; dañarla provoca dolor extremo, alteraciones visuales e invita a infecciones intraoculares graves." }, symptoms: { title: "Síntomas Visuales y Dolorosos Repentinos", intro: "Los síntomas aparecen casi instantáneamente tras el evento traumático e incluyen:", groups: [ { name: "Sensaciones de Dolor y Molestia", items: ["Dolor ocular muy agudo, punzante o cortante (que empeora drásticamente al abrir y cerrar el párpado)", "Sensación intensa y constante de tener arena, polvo o un cuerpo extraño atrapado en el ojo, incluso cuando ya se ha sacado la partícula", "Imposibilidad o extrema dificultad para mantener el ojo abierto", "Fotofobia severa (dolor agudo a los ojos al mirar cualquier fuente de luz, interior o exterior)"] }, { name: "Signos inflamatorios", items: ["Lagrimeo profuso, espasmódico e incontrolable del ojo afectado", "Enrojecimiento intenso (ojo inyectado en sangre)", "Visión borrosa ocasional, provocada por el exceso de lágrimas o hinchazón"] } ], warning: "Toda exposición química en el ojo (como limpiadores de hogar alcalinos, cal o cemento) es una de las mayores urgencias oftalmológicas que existen; lave el ojo inmediatamente con agua corrida durante 20 minutos antes de ir a urgencias." }, types: { title: "Tipos de Lesiones de la Superficie del Ojo", intro: "Las lesiones varían desde rasguños menores hasta desgarros que amenazan la vista:", items: ["Abrasión corneal superficial: Un rasguño simple. El epitelio cicatriza y se reemplaza naturalmente en 24 a 48 horas sin dejar secuelas si no se infecta.", "Úlcera corneal: Una abrasión que se ha infectado bacterianamente o por uso de lentes de contacto; forma un defecto profundo en el estroma corneal, altamente peligroso.", "Cuerpo extraño incrustado: Una partícula de metal, esmeril o viruta de madera que se ha clavado físicamente en la córnea y está oxidándose.", "Laceración corneal penetrante: Un corte profundo causado por herramientas o vidrios que atraviesa todas las capas de la córnea, derramando el líquido intraocular (emergencia quirúrgica de reparación)."], note: "Las abrasiones causadas por materia vegetal (como un rasguño con la rama de un árbol o pasto) tienen un alto riesgo de desarrollar una destructiva infección por hongos." }, causes: { title: "Causas y Eventos Traumáticos Frecuentes", intro: "La córnea está siempre expuesta, por lo que es vulnerable a:", items: ["Impactos mecánicos directos cotidianos: El más clásico es recibir un rasguño accidental con la uña de un bebé, el borde de una hoja de papel, o la rama de un arbusto", "Partículas arrastradas por el viento: Arena, aserrín, polvo o cenizas que quedan atrapadas bajo el párpado y rayan el ojo cada vez que el paciente parpadea", "Mal uso de lentes de contacto: Uso prolongado, dormir con lentes puestos, lentes agrietados, sucios o mal ajustados que rozan y erosionan la córnea (causa principal de lesiones complicadas)", "Restregarse los ojos bruscamente con los puños cuando se siente picazón o se cree tener un objeto dentro", "Maquillaje en los ojos (rasguños con el aplicador del rímel) o quemaduras por rizadores calientes"] }, diagnosis: { title: "¿Cómo se Evalúa y Confirma la Herida?", intro: "El diagnóstico médico requiere teñir el ojo para visualizar el rayón invisible:", items: ["Examen de agudeza visual para documentar cualquier pérdida de capacidad visual base", "Tinción con gotas de Fluoresceína: El oftalmólogo o médico de urgencias pone una gota de tinte amarillo-naranja indoloro en el ojo. Bajo una luz azul (lámpara de cobalto), cualquier rasguño o abrasión brilla en verde fluorescente brillante, mostrando la forma y profundidad exactas de la herida", "Examen con Lámpara de Hendidura (microscopio): Para revisar el tamaño de la herida, buscar signos de infección temprana y voltear delicadamente (eversión) los párpados buscando partículas ocultas", "NO se aplican anestésicos tópicos para que el paciente se los lleve a casa, ya que inhiben gravemente la curación corneal y enmascaran empeoramientos graves"], note: "El médico extraerá cualquier cuerpo extraño microscópico restante usando un pequeño instrumento romo o aguja especializada." }, treatment: { title: "Cuidados, Antibióticos y Curación Corneal", intro: "El tejido superficial corneal se cura asombrosamente rápido, pero requiere prevenir infecciones a toda costa:", subsections: [ { title: "Tratamiento de apoyo ocular", items: ["Gotas o pomadas de antibióticos profilácticos (oftálmicos): Recetados rutinariamente para usar durante varios días, impidiendo que la herida abierta contraiga una infección bacteriana letal o úlcera", "Lágrimas artificiales lubricantes intensivas (sin conservantes) para proporcionar confort y evitar que el párpado irrite más el tejido en curación", "Gotas dilatadoras del iris (ciclopléjicos): Si el dolor y los espasmos musculares del ojo son muy intensos", "Analgesia oral: Ibuprofeno o paracetamol para reducir el severo dolor en las primeras 24 horas", "Evitar el frotado: Usar gafas de sol (para fotofobia) y no tocar el ojo. El uso de parches oculares apretados ya no se recomienda de rutina, pues eleva la temperatura y aumenta el riesgo de infección bacteriana", "Prohibición absoluta de usar lentes de contacto o maquillaje hasta que el médico confirme que la curación de la piel es total"] } ], note: "Las abrasiones menores sanan completamente en 1 a 3 días. Las lesiones causadas por lentes de contacto requieren gotas antibióticas más fuertes para combatir la peligrosa bacteria Pseudomonas." }, whenToSeekHelp: { title: "¿Cuándo Acudir Inmediatamente al Oftalmólogo o Urgencias?", intro: "No minimice el dolor ocular ni espere que sane solo. Busque ayuda médica de emergencia si:", items: ["Se salpicó el ojo con algún producto químico (limpiador doméstico, ácido o lejía); tras lavar con agua durante 20 minutos, corra al hospital", "Siente que todavía hay algo clavado o alojado en el ojo a pesar de haber lagrimeado o intentado lavarlo suavemente", "El dolor agudo en el ojo empeora al segundo día, en lugar de mejorar de forma constante, o nota secreción amarillenta-verdosa espesa", "Presenta una nubosidad repentina y persistente en su visión, o dolor intolerable al ver hacia áreas iluminadas"] } },
'Absceso periamigdalino' : { intro: "El absceso periamigdalino es una infección bacteriana dolorosa, avanzada y potencialmente grave de la garganta. Ocurre cuando se forma una bolsa llena de pus en los tejidos profundos al lado y detrás de la amígdala. Es una complicación aguda de una amigdalitis estreptocócica no tratada que bloquea peligrosamente la capacidad de abrir la boca, tragar e incluso respirar.", whatIs: { title: "¿Qué es un Absceso Periamigdalino?", text: "Es una acumulación localizada de pus (material purulento infeccioso) en el espacio que rodea la amígdala palatina, en la parte posterior de la garganta. Suele ser unilateral (de un solo lado) y provoca que la amígdala y el tejido adyacente se hinchen de forma masiva hacia el centro, desplazando a la campanilla (úvula)." }, symptoms: { title: "Síntomas Clásicos y Signos de Alarma", intro: "Los síntomas avanzan en pocos días desde un simple dolor de garganta a un cuadro altamente restrictivo:", groups: [ { name: "Síntomas locales en faringe y boca", items: ["Dolor de garganta extremadamente agudo y punzante, predominantemente en un solo lado, que empeora intensamente al intentar tragar", "Disfagia severa (imposibilidad de tragar incluso la propia saliva), lo que provoca babeo constante e incontrolable", "Voz de 'papa caliente': El habla suena gangosa, apagada o como si la persona tuviera algo ardiendo o atorado en el fondo de la boca", "Trismo: Dificultad marcada o dolor físico agudo al intentar abrir la mandíbula o la boca (la inflamación afecta el músculo masticador)"] }, { name: "Signos sistémicos de infección profunda", items: ["Fiebre alta, sudoración y escalofríos intensos", "Mal aliento muy fuerte, metálico o putrefacto y sabor fétido en la boca", "Hinchazón notable, dolor y sensibilidad en las glándulas linfáticas del cuello y la mandíbula, y dolor irradiado al oído del mismo lado", "Al examinar la boca, la úvula (campanilla) está severamente empujada, torcida y desplazada hacia el lado sano (no infectado)"] } ], warning: "Si la hinchazón es tan masiva que el paciente no puede acostarse por ahogo o presenta estridor (un sonido silbante agudo al inhalar), existe riesgo inminente de cierre total de la vía respiratoria; es una urgencia de extrema prioridad." }, types: { title: "Etapas de Formación de la Infección", intro: "La afección es la fase final de una cadena inflamatoria faríngea:", items: ["Amigdalitis aguda inicial: Infección bacteriana común de las propias amígdalas (dolorosas pero sin formación de pus externo localizado).", "Celulitis periamigdalina: La infección escapa de la amígdala e invade el tejido circundante. La garganta se hincha, duele y se enrojece, pero aún no se ha formado un 'bolsillo' líquido de pus (fase que a veces se resuelve solo con antibióticos fuertes).", "Absceso periamigdalino conformado: El pus se ha condensado formando una cavidad líquida a presión, y el absceso debe ser evacuado (drenado) físicamente de urgencia."], note: "Ocurre casi siempre en adolescentes mayores y adultos jóvenes; paradójicamente, los niños pequeños rara vez desarrollan abscesos de este tipo." }, causes: { title: "Bacterias y Factores de Origen", intro: "Casi siempre es el resultado de un tratamiento insuficiente en el paso anterior:", items: ["La causa base es casi universalmente una infección estreptocócica agresiva (Faringoamigdalitis por Streptococcus del grupo A) o una mezcla de múltiples bacterias anaerobias y aerobias de la boca", "Falta de tratamiento oportuno o dosis incompleta de antibióticos durante una amigdalitis bacteriana aguda previa", "Mononucleosis infecciosa recurrente o concurrente que deprime localmente el tejido", "Infecciones dentales crónicas graves (como muelas del juicio inferiores impactadas) que migran hacia el tejido de la faringe", "Tabaquismo crónico, que irrita las membranas mucosas, afecta el tejido linfático local y aumenta la incidencia del cuadro bacteriano"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "El diagnóstico es eminentemente clínico, a menudo en el servicio de Urgencias u Otorrinolaringología:", items: ["Evaluación e inspección física visual: El médico usa un depresor lingual y una linterna, observando la inflamación masiva asimétrica, el enrojecimiento, el pilar palatino abultado y la clara desviación de la úvula.", "Ecografía intraoral rápida o aspiración diagnóstica con aguja: Si el tejido está duro o no se sabe si ya es un absceso líquido (para localizar exactamente dónde clavar la aguja).", "Tomografía Computarizada (TC) de cuello con contraste: Utilizada si hay sospecha de que la infección se ha extendido profundamente hacia el pecho o tejidos del cuello (absceso retrofaríngeo) o si el paciente no puede abrir la boca en absoluto.", "Cultivo del pus extraído y pruebas rápidas de estreptococo en hisopo."], note: "El signo clínico distintivo e innegable de esta afección es la úvula torcida hacia el lado contrario a causa del enorme volumen purulento empujándola." }, treatment: { title: "Drenaje Urgente y Terapias Infecciosas", intro: "El manejo requiere vaciar de manera experta la colección de pus inmediatamente para aliviar el bloqueo respiratorio:", subsections: [ { title: "Intervenciones procedimentales y médicas", items: ["Aspiración con aguja o Incisión y Drenaje (I&D): El tratamiento de elección inmediata en emergencias. Tras rociar anestesia local (lidocaína/adrenalina) en la garganta, el médico pincha el absceso con una aguja larga para succionar el pus, o realiza un corte (incisión) con un bisturí abriendo la bolsa para que la materia infectada drene completamente hacia afuera.", "El alivio del dolor, trismo y fiebre tras extraer la presión del pus es, a menudo, casi mágico, instantáneo y radical.", "Antibióticos sistémicos intravenosos (en hospital) u orales de dosis alta (como amoxicilina-ácido clavulánico o clindamicina) para esterilizar el tejido circundante de las bacterias remanentes.", "Rehidratación intravenosa de emergencia para pacientes que han estado sin poder tragar líquidos durante días, analgésicos fuertes para la garganta y gárgaras desinfectantes suaves.", "Amigdalectomía en caliente (extirpación de urgencia de la amígdala completa) reservada solo para casos gravísimos donde el drenaje falla, o amigdalectomía programada unos meses después si el paciente tiene historial recurrente de abscesos repetidos."] } ], note: "No intente nunca drenar la inflamación faríngea en casa. Cerca de las amígdalas pasa la vital arteria carótida, que podría perforarse si se intenta un abordaje aficionado." }, whenToSeekHelp: { title: "¿Cuándo Acudir Inmediatamente a la Sala de Emergencias?", intro: "Diríjase a la emergencia hospitalaria si sufre de un grave dolor de garganta reciente acompañado de cualquiera de los siguientes:", items: ["No puede tragar líquidos, comienza a babear incontrolablemente y su voz suena como si tuviera algo atascado u ahogándole", "Le resulta físicamente difícil, muy rígido o imposible abrir la boca, separando los dientes solo unos milímetros (trismo)", "Tiene dificultad para respirar con normalidad, siente asfixia o su respiración se vuelve audiblemente aguda o ruidosa (estridor)", "Nota dolor o hinchazón severa en el cuello y picos de fiebre o escalofríos paralizantes de instauración súbita"] } },
'Gastrosquisis' : { intro: "La gastrosquisis es un defecto congénito visible y grave de la pared abdominal, en el cual el bebé nace con una apertura al lado del ombligo por donde escapan los intestinos. Como se han desarrollado flotando sin protección en el líquido amniótico, los intestinos nacen irritados, y el bebé requiere de cirugía neonatal vital en las primeras horas para insertarlos de vuelta en el cuerpo.", whatIs: { title: "¿Qué es la Gastrosquisis?", text: "Es una anomalía del desarrollo embrionario donde los músculos que forman la pared del abdomen anterior no se unen ni se cierran correctamente. Deja un agujero constante (generalmente al lado derecho del cordón umbilical) por el cual sobresalen (hernian) grandes porciones de intestino delgado o grueso del feto hacia el exterior, flotando desnudos." }, symptoms: { title: "Características Estructurales al Nacer", intro: "Es un defecto anatómico visible externamente. Las características críticas de esta afección incluyen:", groups: [ { name: "Apariencia general y daño orgánico", items: ["Presencia de un defecto o agujero de 2 a 4 centímetros en el abdomen, estrictamente lateral al cordón umbilical intacto", "Bucles de intestino, y a veces el estómago o el hígado, se encuentran completamente fuera del cuerpo al nacer", "Ausencia de un saco o membrana protectora (a diferencia del onfalocele), lo que deja los intestinos totalmente expuestos y desnudos", "Debido a la exposición química a los desechos en el líquido amniótico (orina fetal) por meses, los intestinos nacen oscuros, severamente engrosados, inflamados, rígidos ('acartonados') y apelmazados (pelvis o peritonitis química)"] }, { name: "Complicaciones clínicas del recién nacido", items: ["Riesgo masivo e instantáneo de pérdida de calor corporal grave e hipotermia porque los órganos vitales calientes están en el exterior", "Pérdida inmensa de líquidos y deshidratación al nacer por evaporación tisular", "Fallo total inicial para procesar o digerir la leche o comida temporalmente (disfunción intestinal prolongada)"] } ], warning: "Tener los intestinos expuestos fuera del vientre crea un peligro crítico e inminente de contraer infecciones generalizadas mortales (sepsis neonatal) y deshidratación; el bebé debe introducirse inmediatamente en un ambiente médico estéril caliente (Bolsa silo/bowel bag)." }, types: { title: "Gravedad de la Presentación", intro: "La urgencia depende del grado de daño que los intestinos sufrieron estando afuera:", items: ["Gastrosquisis simple: El agujero no estrangula la base y los intestinos que están fuera están razonablemente sanos, en buena posición y sin otras perforaciones.", "Gastrosquisis compleja: Menos común, ocurre cuando los intestinos están retorcidos (vólvulo), necrosados (se pudrió parte del tejido por falta de sangre que fluía hacia afuera del agujero pequeño), o existe atresia intestinal simultánea (el intestino no se formó de manera continua por la isquemia).", "El tipo complejo a menudo requerirá una posterior resección intestinal (quitar el área muerta) e implica meses de terapias y estancia hospitalaria."], note: "A diferencia del Onfalocele, los niños nacidos con Gastrosquisis generalmente NO presentan altos índices de trastornos cromosómicos o anomalías cardíacas severas; el resto de su cuerpo suele estar muy sano." }, causes: { title: "Factores de Riesgo en el Embarazo y el Embrión", intro: "Es una falla anatómica vascular o embrionaria durante el primer trimestre (semana 4 a 8). Sus causas directas no están confirmadas, pero está ligada a factores maternos inusuales:", items: ["Edad materna muy joven: Es uno de los pocos defectos de nacimiento que es dramáticamente más frecuente si la madre es adolescente o menor de 20 años", "Fumar cigarrillos fuertemente antes y durante las primeras etapas del embarazo", "Consumo excesivo de alcohol y uso de drogas recreativas (como cocaína o metanfetaminas) al principio del embarazo", "Uso concurrente de medicamentos vasoactivos (como ciertos descongestionantes con pseudoefedrina o la toma crónica de aspirina alta dosis) en el primer trimestre, que pueden interrumpir vasos que nutren la formación de la piel del vientre", "Bajo Índice de Masa Corporal (IMC) materno o infecciones genitourinarias reportadas tempranas en mujeres gestantes"] }, diagnosis: { title: "¿Cómo se Detecta Prenatalmente?", intro: "Rara vez es una sorpresa en la sala de partos; casi siempre se detecta durante el embarazo:", items: ["Prueba de sangre materna rutinaria (Alfafetoproteína AFP): Entre las semanas 15 y 20, un nivel anormalmente elevado y alarmante en sangre es un fuerte indicador del escape de proteínas desde las tripas fetales hacia el saco materno", "Ecografía fetal detallada (ultrasonido): El diagnóstico oficial y confirmatorio. Se observan claramente las asas del intestino flotando libremente en el líquido oscuro fuera del abdomen del bebé ya en el segundo trimestre (semana 18-20)", "Ecocardiogramas prenatales exhaustivos de rutina y monitorización periódica continua con ultrasonido para verificar si el bebé está engordando, si hay suficiente líquido amniótico o si los intestinos se dilatan gravemente (sufrimiento intestinal)", "Planificación médica crucial: Permite organizar obligatoriamente que el parto ocurra en un gran hospital terciario equipado con Unidad de Cuidados Intensivos Neonatales Quirúrgica especializada, a cargo de neonatólogos y cirujanos."], note: "El parto vaginal a menudo sigue siendo muy seguro para un bebé con gastrosquisis, por lo que la cesárea se reserva generalmente para situaciones donde el bebé tiene estrés, no rutinaria por el defecto." }, treatment: { title: "Estabilización, Silo de Reducción y Cirugía Intestinal", intro: "El objetivo es reintegrar los intestinos suavemente al vientre y cerrar el agujero sin estrangular los órganos:", subsections: [ { title: "Intervenciones Quirúrgicas Neonatales Intensivas", items: ["Reanimación de emergencia: Al nacer, el bebé no come; es inmediatamente intubado o estabilizado, puesto bajo calor radiante y los intestinos se envuelven cuidadosamente en plástico tibio y húmedo y se administran antibióticos intravenosos masivos preventivos.", "Cierre primario (Reducción quirúrgica inmediata): Si hay pocos intestinos expuestos y el abdomen del bebé está estirado, el cirujano insertará los intestinos, suturará el agujero y formará un ombligo artificial inmediatamente horas después del parto bajo anestesia.", "Reducción y cierre por etapas (Silo quirúrgico): El tratamiento habitual. El abdomen del recién nacido es demasiado pequeño para acomodar intestinos tan inflamados; cerrarlo forzosamente aplastaría los pulmones y el riñón. Se cuelga un saco de silicona estéril (Silo) lleno de intestinos por encima del bebé, y por varios días a una semana, la gravedad y compresiones manuales diarias empujan milimétricamente el intestino dentro del abdomen estirándolo hasta que finalmente quepan y el cirujano cierre el parche (cierre final).", "Alimentación Intravenosa Total (NPT): El bebé será alimentado 100% a través de una vía en su vena central (sin usar la boca) durante las primeras y duras semanas, ya que los intestinos inflamados deben sanar y aprender a contraerse lentamente antes de tolerar unas gotas de leche materna."] } ], note: "La nutrición en el hospital tomará varias semanas prolongadas. A largo plazo, una inmensa mayoría de estos infantes crecen sanos con cicatrices abdominales, y llevan una vida gastrointestinal completamente ordinaria." }, whenToSeekHelp: { title: "¿Qué Debe Esperar y Vigilar Durante el Embarazo o Tras el Alta?", intro: "El manejo de la Gastrosquisis es hospitalario intenso. Las acciones maternas prioritarias consisten en:", items: ["En el embarazo: Asistir rigurosamente a cada cita y derivación ecográfica del embarazo para monitorear complicaciones y asegurar en qué ciudad se programará el parto con el equipo especialista", "Tras el alta hospitalaria meses después: Debe contactar y alertar al pediatra cirujano si su bebé en recuperación repentinamente comienza a vomitar líquido teñido de verde/bilis reiteradamente, lo que indica un peligroso bloqueo abdominal post-quirúrgico o adherencia intestinal grave", "Reportar estreñimiento doloroso crónico en el lactante o fiebre repentina y letargo profundo inusual en casa"] } },
'Cáncer del páncreas' : { intro: "El cáncer de páncreas es una de las neoplasias oncológicas malignas más sigilosas y agresivas. Es un desafío clínico formidable porque sus síntomas iniciales son vagos e inespecíficos, impidiendo su descubrimiento temprano. Cuando finalmente causa molestias evidentes (como la piel amarilla e ictericia indolora), el tumor a menudo ya se ha diseminado, limitando fuertemente las opciones curativas.", whatIs: { title: "¿Qué es el Cáncer de Páncreas?", text: "Es la formación invasiva de células malignas (tumores) en los tejidos del páncreas, un órgano glandular situado profundamente detrás del estómago, que es vital tanto para segregar hormonas y controlar la glucosa (insulina) como para producir poderosos jugos que digieren las comidas que ingerimos." }, symptoms: { title: "Síntomas Difusos y Alertas Avanzadas", intro: "Durante las etapas precoces es asintomático. Cuando avanza e invade ductos u órganos adyacentes provoca:", groups: [ { name: "Síntomas obstructivos y digestivos", items: ["Ictericia profunda e indolora (el síntoma revelador más temprano en los tumores de la cabeza pancreática): la piel entera y el blanco de los ojos (esclerótica) se tornan amarillo brillante repentinamente", "Orina muy oscura (color té fuerte, coñac o marrón)", "Heces pálidas, grises o de color arcilla, a veces grasosas y flotantes (esteatorrea) por la interrupción de los jugos pancreáticos y biliares", "Pérdida alarmante de apetito (anorexia generalizada), y pérdida drástica, pronunciada y sin justificación de varios kilos de peso (síndrome caquéctico)"] }, { name: "Signos metabólicos y el dolor visceral", items: ["Dolor epigástrico (abdominal central) persistente y sordo, que invariablemente se irradia profundamente hacia la espalda central u hombros", "Aparición súbita y atípica de Diabetes Mellitus tipo 2 severa en adultos mayores (sin antecedentes), o descontrol drástico en diabéticos crónicos, causada porque el tumor asfixia las células productoras de insulina", "Picazón corporal grave e incesante (prurito intenso generalizado derivado del almacenamiento de sales biliares circulando en sangre por la ictericia)", "Formación inexplicable de coágulos de sangre severos o flebitis repetitiva profunda en las piernas (Síndrome de Trousseau)"] } ], warning: "Cualquier desarrollo súbito y acelerado de coloración amarilla en la piel (ictericia) en un paciente adulto sin dolor abdominal es una sospecha de extrema y máxima prioridad oncológica para descartar cáncer de cabeza de páncreas." }, types: { title: "Clasificación Oncológica (Exocrinos y Endocrinos)", intro: "El tipo determina cuán devastador es y su tratamiento biológico:", items: ["Adenocarcinoma pancreático exocrino (más del 90%): Cáncer agresivo y mortífero desarrollado a partir de las células de los conductos que fabrican las enzimas digestivas secretorias del páncreas.", "Tumores neuroendocrinos del páncreas (NET) o del islote (menos del 5%): Tipos de cáncer increíblemente más raros, desarrollados en las células pancreáticas segregadoras de hormonas (insulinoma, gastrinoma, glucagonoma). Tienden a tener un curso muy distinto, un crecimiento biológico mucho más lento y una supervivencia a largo plazo superior, pero causan hiper-producción hormonal aguda sistémica (hipoglucemias extremas o úlceras).", "Neoplasias mucinosas papilares intraductales (IPMN): Tumores pancreáticos inicialmente benignos que producen sacos y líquidos, pero que se consideran precancerosos y deben extirparse a menudo antes de que muten."], note: "El factor decisivo general es su anatomía. Un tumor en la 'Cabeza' del páncreas tapa rápido la vía biliar causando ictericia visible temprana; un tumor en la 'Cola' o 'Cuerpo' es silente, pudiendo llegar a dimensiones enormes inoperables antes de evidenciar dolor local." }, causes: { title: "Causas Sistémicas, Factores Genéticos y Tabaco", intro: "Se forma mediante múltiples mutaciones complejas en su ADN, pero factores identificados aumentan notablemente el riesgo:", items: ["El Tabaquismo Severo: El riesgo prevenible directo más fuerte; los fumadores tienen más del doble de riesgo fatal de sufrirlo.", "Obesidad Crónica extrema (y la acumulación inflamatoria severa de grasa visceral abdominal), e inactividad persistente", "Diabetes Mellitus sistémica (a largo plazo, y sobre todo es una luz roja alerta si aparece rápida tras los 55 años).", "Pancreatitis crónica prolongada y continua agudizada por abuso e ingesta letal sostenida de alcohol durante la vida adulta general.", "Carga genética y mutaciones familiares hereditarias comprobables (alrededor del 10%): Mutaciones germinales del gen BRCA1 o BRCA2 (asociados a cáncer de mama familiar), Síndrome de Lynch, Síndrome de Peutz-Jeghers, o Pancreatitis familiar congénita, ameritan pruebas preventivas a parientes."], note: "A diferencia del cáncer de colon, pólipos, mamas y próstata, actualmente no existen análisis de detección temprana eficaces en sangre masiva global para encontrar tempranamente este cáncer en la población asintomática general sin riesgo." }, diagnosis: { title: "¿Cómo se Detecta y Analiza el Avance y Estadificación?", intro: "Para el abordaje, el gastroenterólogo o el cirujano oncólogo requerirá inmediatamente obtener las siguientes imágenes profundas:", items: ["Tomografía Computarizada de Protocolo o Panel Pancreático Multifase e infusión doble con contraste radiológico avanzado o RM: Es la piedra angular básica e insustituible para obtener cortes visuales detallados exactos de si hay tumores e identificar minuciosamente y dictaminar si los vasos venosos sanguíneos esplácnicos o mesentéricos vitales críticos locales están rodeados por dicho tumor o tapados (estadiando así de inmediato su resecabilidad límite de urgencia quirúrgica).", "Ultrasonido/Ecografía Endoscópica (USE / EUS) y Biopsia con aguja fina por endoscopia (FNA): Se traga con endoscopio por estómago y se posa sobre la zona del páncreas directo visualizándolo al centímetro sin hueso obstruyendo, usando después el tubo una inyección para tomar aspiración guiada en masa de células confirmando fehacientemente su patología al nivel de laboratorio patológico oncológico de origen sin hacer una gran cirugía inicial al cuerpo del enfermo de base.", "Colangiopancreatografía Retrógrada Endoscópica paliativa biliar (CPRE): Procedimiento muy invasivo al canal visual usado para desbloquear temporalmente el conducto biliar con un pequeño cilindro de plástico alambre o 'stent' de urgencia, aliviando rápidamente de ictericia crítica a un paciente al restaurar al hígado del flujo temporal.", "Análisis base marcador o Antígeno en Sangre (CA 19-9): Una prueba orientativa que no diagnostica por base exclusiva, pero en combinación ayuda inmensamente a revisar y monitorear un seguimiento para confirmar posteriormente y determinar si la severidad o quimioterapia basal ha disminuido un marcador que estaba al máximo en la curva general."], note: "A la evaluación inicial, el objetivo crítico y absoluto de un médico es definir si está o pertenece al 20% de pacientes que son 'resecables' (operables curables), 'borderline' (al límite quirúrgico) o del restante donde ya hay metástasis local o distante en el hígado." }, treatment: { title: "La Gran Intervención Quirúrgica Radical, Terapias Adyuvantes o Paliativas", intro: "Su tratamiento requiere uno de los equipos quirúrgicos de cirugía general pancreato-hepática y oncológica de más alta capacidad mundial:", subsections: [ { title: "Aproximaciones Clínicas Complejas Oncológicas", items: ["Cirugía extensa de Resección del Procedimiento de Whipple invasivo masivo (Pancreatoduodenectomía): Apto solo en etapas uno y dos iniciales sin ramificaciones. El gran equipo cirujano realiza una reconstrucción, cortando la cabeza total del órgano, todo o parte y vaciado del duodeno general, la ampolla biliar, vesícula vesicular general en bloque para extraer e inhibir al sistema de masa, y conectando la cola libre para reorientar a las vías intestinales (Operación curativa masiva).", "Quimioterapia General Adyuvante (y neoadyuvante a veces radioterapia): La indicación basal oncológica a iniciar antes del plan cirugía para derretir bordes tumefactos, y casi imprescindible usar a todos tras las resecciones grandes extirpadas postquirúrgicas de Whipple o en pacientes general paliativos al reducir en gran y dramática forma la propagación y retrasar la terminal enfermedad.", "Inmunoterapias y Terapia molecular dirigida avanzada (Medicamentos como los Inhibidores biológicos u de reparación tipo PARP Olaparib, que ofrecen gran esperanza a y exclusivamente en los enfermos donde la célula mutante se confirmó basal positiva o con prueba germinal directa en los síndromes familiares BRCA1/2, a de manera dirigida oncológica).", "Atención para la Inmensa Terapia Cuidadora de Soporte Paliativo general (Alivio del sufrimiento intensivo doloroso general mediante severos bloqueos de agujas para matar ganglios celíacos nerviosos centrales, administrar cápsulas pesadas obligatorias general pancreáticas para asimilar la grasa biliar digestiva al perder su páncreas real y usar insulina artificial estricta en su post de diabetes base general)."] } ], note: "Aunque los índices o cifras pasadas oncológicos fueron y son sumamente desafiantes lúgubres de manera prolongada en pronóstico general para erradicación, la prolongación en meses o sobrevida basal por medio de nuevas técnicas múltiples y combinación ha aumentado en grandes esperanzas contemporáneas o quimioterápicas FOLFIRINOX de la medicina de hoy mundial." }, whenToSeekHelp: { title: "¿En Qué Situaciones Alarmantes o Indicadores Acudir Urgente a un Internista y Derivar Al Especialista Analítico Oncológico?", intro: "Considere de riesgo serio general si en edad media e historia mayor de los adultos no ceden los hallazgos de signos o no asocia un patrón de patología clara acudiendo a un profesional frente a:", items: ["Detecta sin un solo día al paso de las semanas súbitamente una tonalidad pigmentada amarilla e ictérica de sus ojos en fondo blanco, picazón muy extrema total sin base e hialina u tez asumiendo ese mismo matiz y dolor abdominal en centro sordo de forma persistente y contundente hacia a espaldas intensas", "Ha comenzado sin de base querer a o disminuir masa, tallas u en un grado severísimo la talla y de peso velozmente extrema (incluso 10 libras) a lo y y en menos semanas o a su asqueo total a cualquier cosa general a lo apetecible comiendo sin parar base de un saciado al rápido u general dolor tras una cena", "El médico y de emergencia de rutina de la analítica la ha comunicado e o indica de diabetes clínica u aparición insulínica altísima que o usted o en su cuerpo sufre de alta de aparición repentinamente a o tras la edad y edad madura 55 con peso sin tener obeso ni antecedentes patológicos genéticos base al respecto de tipo familiar de esta diabetes base o diabetes de o tipo dos clásica", "Ha notado de base crónico general, de e las heces flotando masivamente, pegajosas al de general u el y y aceitosas heces crónicas pálidas con fuerte fetidez extrema sin diarrea, lo cual indica que la glándula ha tapado severamente los canales digestivos para disolver base crónicamente en el nivel a al a estómago."] } },
'Mucocele' : { intro: "Un mucocele es un bulto redondo e inofensivo que a menudo aparece en el interior del labio inferior tras morderse accidentalmente. Aunque asusta por su aparición rápida, no es cáncer ni es contagioso, siendo simplemente un pequeño 'globo' de saliva acumulada proveniente de una glándula salival lesionada que requiere atención odontológica menor si no desaparece solo.", whatIs: { title: "¿Qué es un Mucocele (Quiste de Extravasación Mucosa)?", text: "Es una tumefacción benigna o quiste inflamatorio superficial en la boca. Ocurre cuando el diminuto conducto de una glándula salival menor (las que tapizan el interior de los labios y mejillas) se rompe, daña u obstruye. La saliva se derrama y se acumula en el tejido blando subyacente, formando un globo liso." }, symptoms: { title: "Síntomas y Aspecto Clínico", intro: "El paciente notará un bulto muy distintivo con estas características específicas:", groups: [ { name: "Características del nódulo", items: ["Aparición rápida de una protuberancia en forma de cúpula en el interior del labio (con mayor frecuencia el labio inferior), en la pared interna de las mejillas (mucosa yugal), o debajo de la lengua (donde toma el nombre de ránula)", "Es indoloro, a menos que se haya infectado secundariamente por morderlo constantemente", "Tiene un tamaño variable, desde muy pequeño (1 o 2 milímetros) hasta varios centímetros", "Su color es característico: a menudo parece translúcido o tiene un tono azulado claro/perlino", "Se siente blando, liso, móvil y lleno de líquido (fluctuante) al tocarlo con la lengua"] }, { name: "Ciclo de rotura y recurrencia", items: ["El quiste a menudo puede romperse espontáneamente o al morderlo, drenando un líquido salival pegajoso transparente y 'desapareciendo', pero es muy propenso a volver a llenarse e hincharse semanas después en el mismo lugar exacto"] } ], warning: "Nunca debe intentar reventarlo o exprimirlo en casa con agujas, ya que rara vez elimina la glándula rota subyacente y solo genera heridas sangrantes e infecciones graves en la boca." }, types: { title: "Diferenciación de Nódulos Salivales", intro: "Existen dos tipos principales según su mecanismo de formación:", items: ["Mucocele por extravasación: El más común (sobre todo en niños y adultos jóvenes). Se debe a una mordedura o traumatismo mecánico directo en la zona; la glándula y el conducto se rompen, derramando saliva ('moco') directamente entre las fibras del tejido.", "Mucocele de retención (Quiste de retención mucosa): El conducto no está roto, sino bloqueado (quizás por un pequeño cálculo salival o tapón epitelial). El tubo se hincha como un globo de agua con saliva. Es más frecuente en adultos mayores.", "Ránula: Un mucocele muy específico, extenso y a menudo grande que se forma en la base del suelo de la boca, bajo la lengua (originado en la glándula sublingual) y que requiere cirugía delicada e inmediata para no interferir con el tragar."], note: "La gran mayoría ocurren en el labio inferior; si un bulto constante similar a un mucocele aparece en el labio superior o en la zona del paladar superior, se sospecha fuertemente de patología oncológica o un tumor salival menor y exige biopsia absoluta." }, causes: { title: "Causas Físicas y Factores Exponentes", intro: "Se asocia primordialmente con los hábitos físicos y traumas menores orales:", items: ["Trauma oral recurrente o mordeduras repetidas ('tic' nervioso de pellizcar, succionar o morder constantemente el propio labio inferior o la parte interna de las mejillas, a menudo por estrés crónico o concentración)", "Impactos maxilares durante juegos deportivos o deportes de contacto (golpes leves contra los labios)", "Aparatos de ortodoncia: Frenillos metálicos ('brackets'), alambres ásperos, o un diente muy afilado que roza continuada e involuntariamente contra la mucosa labial al masticar a diario", "Cirugía oral previa en el área (como extracciones donde los retractores pellizcan la mejilla, rompiendo glándulas anexas superficiales)"] }, diagnosis: { title: "¿Cómo se Examina su Inocuidad?", intro: "Generalmente, el cirujano maxilofacial, dentista o médico familiar puede diagnosticar el problema de inmediato en la cita:", items: ["Examen visual minucioso: La lesión y el bulto son sumamente clásicos y tienen una historia oral de trauma (como un rasguño dental), y en muchos diagnósticos su simple fluctuación y matiz azul translúcido bastan para su diagnóstico clínico patognomónico.", "Biopsia de excisión: Un odontólogo y patólogo maxilofacial tomará y extraerá íntegramente la porción lesionada si el nódulo es muy profundo (duro y no fluctúa), ha perdurado durante más de 30 o 40 días inmutable o si de forma persistente surge en una región anatómica inusual como el paladar blando para poder dictaminar en microscopio su patología y con firmeza absoluta corroborar a final y a simple análisis celular para descartar, de una vez, tumores mayores y otros cánceres graves de tejido glandular subyacentes o carcinomas mucoepidermoides."], note: "Los mucoceles infantiles suelen desvanecerse sin ningún tratamiento especializado de tres a seis semanas; a lo contrario de adultos, donde persistirán de manera recalcitrante." }, treatment: { title: "Enfoque Terapéutico Quirúrgico Básico de la Afección", intro: "El objetivo es resolver las recaídas eliminando la glándula base rota, pero si no le estorba, la curación natural es posible:", subsections: [ { title: "Aproximaciones al Manejo Odontológico General", items: ["Ningún tratamiento o espera activa inicial: Si la afección es totalmente de pequeño diámetro temporal y reciente e indoloro, a lo cual su propio organismo disuelve o seca y se encapsula en absorción biológica en cuestión y semanas tempranas.", "Escisión y extracción quirúrgica conservadora: La técnica estandarizada resolutiva y absoluta universal para casos en donde se estanca crónicamente o retorna al llenarse un saco. El cirujano bucal con anestésico y jeringa local aplica un pequeño o superficial corte y corta y limpia sin esfuerzo y rápidamente no exclusivamente la simple cápsula salival visible, sino y también arranca o interrumpe para siempre el saco base o diminuta glándula inferior accesoria (pequeñas pelotitas de tejido anexas que gotean sin parar) adyacente para prever y asegurar una recurrencia totalmente nula.", "Marsupialización perimetral: Técnica utilizada sobre todo para las variantes sublinguales (Ránulas muy ensanchadas) creando intencionalmente en cirugía un diminuto y pequeño orificio cicatrizado nuevo u permanente sin extracción total pero con el uso directo hacia afuera de suturas, garantizando un cauce o tubo natural por vía externa para drenar las glándulas más difíciles mayores de acceso por donde siga drenando normal a los tejidos y saliva al paciente en vez de extirpar su glándula en casos de complicaciones masivas y sublinguales.", "Terapias como Láser o la crioablación (congelamiento destructivo extremo del saco en la pared mucosa) o de un uso de inyecciones del nivel corticoesteroideo basal intralesional reducen el riesgo si un caso persiste antes de intentar intervenir al paciente con la hoja y el bisturí en personas vulnerables e infantiles a a traumas dentales operatorios agudos."] } ], note: "Es trascendental al final curar o lijar u arreglar el factor de la fricción (es decir un alambre salido u los arreglos dentales puntiagudos del aparato general) pues aunque un cirujano remueva toda el daño en base actual de tejido, otra glándula u mucosa anexa adyacente a su lado se romperá inevitable y de misma manera formándolo si la mordedura al paciente sigue perpetuando de fricción física en el lugar." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Dentista, Clínico o Diagnóstico Oral Seguro?", intro: "Lleve la anomalía ante un dentista o su profesional estomatólogo en caso general de manera o programada si detecta que o para si a usted:", items: ["El nódulo, quiste, o masa basal intraoral ha subsistido por persistencia superior e indefinida por a más general más del mes e incluso semanas a pesar e incluso sin haber provocado molestia ninguna", "Ha aumentado significativamente el tamaño del globo y un bulto y e ha empezado a interrumpir o obstruir sus vías general y sus formas diarias de habla en dicción general, impide del y tragar saliva alimentos e interferir para al comer en gran base u de la del masticar", "Se muestra general o a presentar sangrados ulcerados masivos en a u se torna excesiva roja irritada la pared a un nivel ulceroso sangrando tras rozar por un cepillo o sin herida base y o o duele de forma fuerte basal dolor agudo", "Usted a o u descubrió o su paciente nota e siente una pequeña masita firme parecida e bulto adherida en o en partes del interior y tejido de piso un del piso duro blando bucal u del paladar superior y general (cielo duro o del y en paladar blando y de techo base), donde en forma a o un el cual tumor glandular u cáncer salival base se da presenta de la en a lo del con más de un riesgo en forma a descartar oncológica y temprana a la a urgencia de intervención a general a descartar"] } },
'Colesterol' : { intro: "Los niveles altos de colesterol (hipercolesterolemia) son un asesino silencioso. Es una alteración metabólica en la que se acumula demasiada grasa en la sangre. Sin causar síntomas directos, este exceso se deposita lentamente en las paredes de las arterias, endureciéndolas y aumentando críticamente el riesgo de infartos y derrames cerebrales.", whatIs: { title: "¿Qué es el Colesterol Alto (Dislipidemia)?", text: "El colesterol es una sustancia cerosa y parecida a la grasa que el hígado produce naturalmente para construir células sanas y hormonas. El trastorno ocurre cuando hay una cantidad anormalmente alta de lípidos (grasas) circulando en el torrente sanguíneo, lo que fomenta la formación de placas peligrosas (aterosclerosis)." }, symptoms: { title: "Ausencia de Síntomas", intro: "La característica más engañosa del colesterol alto es que no se siente:", groups: [ { name: "Condición asintomática", items: ["En la inmensa mayoría de las personas, no hay síntomas físicos de advertencia, mareos, ni dolor que indique que los niveles están altos.", "La única forma de saberlo es mediante un análisis de sangre (perfil lipídico)."] }, { name: "Signos avanzados y complicaciones graves", items: ["Xantomas: En casos genéticos extremos, pueden aparecer depósitos amarillentos de grasa bajo la piel alrededor de los párpados (xantelasma) o en los tendones de los talones.", "Angina de pecho (dolor torácico) o dificultad para respirar (cuando las arterias del corazón ya están bloqueadas por la placa)", "Ataque isquémico transitorio o accidente cerebrovascular (cuando se bloquean las arterias que van al cerebro)"] } ], warning: "Esperar a sentir síntomas para revisar su colesterol significa esperar a que ocurra un evento cardiovascular grave. La prevención y las pruebas de laboratorio son la única defensa." }, types: { title: "Tipos de Colesterol y Lípidos", intro: "El impacto en la salud depende de qué tipo de grasa está elevada:", items: ["LDL (Lipoproteína de baja densidad): Conocido como el colesterol 'malo'. Un nivel alto lleva a la acumulación de placa en las arterias.", "HDL (Lipoproteína de alta densidad): Conocido como el colesterol 'bueno'. Ayuda a recoger el exceso de colesterol en la sangre y lo devuelve al hígado para su eliminación. Un nivel BAJO de HDL es peligroso.", "Triglicéridos: El tipo más común de grasa en el cuerpo (proveniente de las calorías no utilizadas). Niveles altos endurecen las arterias y aumentan el riesgo cardíaco.", "Colesterol total: Es la suma del contenido total de colesterol en la sangre (LDL + HDL + 20% de los triglicéridos)."], note: "El objetivo clínico moderno no es solo bajar el colesterol total, sino bajar agresivamente el LDL y subir el HDL." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los niveles están determinados por lo que come, cómo vive y lo que hereda:", items: ["Mala alimentación: Consumo alto de grasas saturadas (carnes rojas, mantequilla, embutidos) y grasas trans (comida rápida, bollería industrial).", "Falta de ejercicio y sedentarismo: Reduce el colesterol 'bueno' (HDL) y fomenta el aumento de peso.", "Obesidad: Tener un Índice de Masa Corporal (IMC) de 30 o más aumenta notablemente el riesgo.", "Tabaquismo: El tabaco daña las paredes de los vasos sanguíneos, haciéndolos más propensos a acumular grasa, y reduce el HDL.", "Edad: A medida que se envejece, la química del cuerpo cambia y el hígado se vuelve menos eficiente eliminando el colesterol LDL.", "Hipercolesterolemia familiar (Genética): Una alteración heredada que impide al cuerpo eliminar el colesterol LDL desde el nacimiento, causando infartos en jóvenes."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se requiere una sencilla prueba de laboratorio en sangre:", items: ["Perfil lipídico completo: Un análisis de sangre, generalmente tomado tras 9 a 12 horas de ayuno absoluto (solo agua), para medir el Colesterol total, LDL, HDL y Triglicéridos.", "Evaluación del riesgo cardiovascular global: El médico no solo mira los números, sino que los cruza con su edad, presión arterial, diabetes y tabaquismo para determinar su riesgo real de sufrir un infarto a 10 años."], note: "La Asociación Americana del Corazón recomienda que todos los adultos se hagan una prueba de colesterol cada 4 a 6 años a partir de los 20 años de edad." }, treatment: { title: "Tratamiento Médico y Cambios de Estilo de Vida", intro: "El tratamiento requiere un compromiso a largo plazo con la salud:", subsections: [ { title: "Dieta, ejercicio y fármacos", items: ["Dieta Cardiosaludable (Dieta Mediterránea): Rica en fibra soluble (avena, frijoles, frutas), grasas saludables (aceite de oliva, aguacate) y ácidos grasos omega-3 (salmón), eliminando grasas saturadas y trans.", "Pérdida de peso y ejercicio: 150 minutos a la semana de actividad aeróbica moderada para elevar el HDL.", "Estatinas (Atorvastatina, Rosuvastatina): Los medicamentos de primera línea y más efectivos. Bloquean la sustancia que el hígado necesita para producir colesterol y ayudan a reabsorber el colesterol acumulado en las arterias.", "Inhibidores de la absorción de colesterol (Ezetimiba): Limitan la absorción del colesterol de los alimentos en el intestino delgado.", "Inhibidores de PCSK9 o Incliniseran: Inyecciones de nueva generación altamente potentes para pacientes con colesterol genéticamente alto o que no toleran las estatinas.", "Fibratos o suplementos puros de Omega-3 recetados (Específicamente para bajar triglicéridos muy elevados)."] } ], note: "Las estatinas son medicamentos de por vida; suspenderlas hará que el colesterol vuelva a subir a sus niveles peligrosos originales." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Médico?", intro: "Agende una cita para un chequeo preventivo si:", items: ["Tiene más de 20 años y no conoce sus niveles de colesterol", "Tiene antecedentes en su familia directa de ataques cardíacos, derrames cerebrales o colesterol alto antes de los 55 años", "Padece de diabetes, obesidad o hipertensión arterial", "Experimenta cualquier dolor opresivo en el pecho, falta de aire inusual o entumecimiento en la cara (Acuda a emergencias inmediatamente)"] } },
'Ascitis' : { intro: "La ascitis es una grave complicación médica que consiste en la acumulación anormal y patológica de grandes cantidades de líquido en el interior de la cavidad abdominal (peritoneo). Es frecuentemente la consecuencia final de una enfermedad hepática avanzada (cirrosis) y requiere manejo médico crónico, ya que causa una dolorosa distensión del abdomen y severa dificultad para respirar.", whatIs: { title: "¿Qué es la Ascitis?", text: "Es el derrame y acumulación de líquido seroso, a veces varios litros, en el espacio entre los órganos abdominales y la pared del abdomen (cavidad peritoneal). Ocurre cuando la presión en los vasos sanguíneos del hígado es demasiado alta y el hígado no puede producir suficientes proteínas para retener el líquido en la sangre." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "La manifestación más evidente es el cambio drástico en la forma del cuerpo:", groups: [ { name: "Distensión y volumen abdominal", items: ["Hinchazón o distensión abdominal masiva, tensa y en constante aumento (el abdomen parece un globo fuertemente inflado)", "Aumento de peso rápido e inexplicable (kilos en cuestión de semanas o días) debido a la pura acumulación de agua", "El ombligo puede estirarse hasta volverse plano o protruir hacia afuera (hernia umbilical)"] }, { name: "Síntomas opresivos y sistémicos", items: ["Falta de aire (disnea) o dificultad para respirar profundamente, especialmente al acostarse, porque el líquido aplasta el diafragma y los pulmones", "Sensación de saciedad precoz extrema (sentirse lleno tras comer muy pocos bocados) por la compresión del estómago", "Hinchazón grave concurrente en las piernas y los tobillos (edema periférico)", "Dolor abdominal sordo, pesadez o severo dolor de espalda baja"] } ], warning: "Si la hinchazón abdominal se acompaña repentinamente de fiebre alta, dolor abdominal agudo o confusión mental, es una emergencia por Peritonitis Bacteriana Espontánea (infección del líquido)." }, types: { title: "Clasificación Clínica del Líquido", intro: "Los médicos analizan el líquido para clasificar la enfermedad causal (Gradiente de albúmina SAAG):", items: ["Ascitis por Hipertensión Portal (SAAG alto): Causada casi siempre por cirrosis hepática o insuficiencia cardíaca severa. Es un trasudado (líquido claro y bajo en proteínas).", "Ascitis Inflamatoria/Maligna (SAAG bajo): Causada por cáncer esparcido en el abdomen (metástasis peritoneal), tuberculosis abdominal o pancreatitis severa. Es un exudado (líquido turbio y rico en células/proteínas).", "Ascitis Quilosa: Muy rara; el líquido tiene aspecto lechoso debido a la filtración de linfa rica en grasas desde conductos linfáticos dañados o por tumores."], note: "El 80% de todos los casos de ascitis en el mundo occidental son consecuencia directa de la cirrosis por daño hepático (alcoholismo o hepatitis viral)." }, causes: { title: "Causas y Disparadores Principales", intro: "El líquido se filtra de los órganos debido a fallos sistémicos severos:", items: ["Cirrosis hepática (cicatrización irreversible del hígado): Aumenta drásticamente la presión en la vena porta (hipertensión portal) y disminuye la albúmina en sangre, lo que fuerza al líquido a escapar de los vasos sanguíneos hacia la barrera peritoneal.", "Insuficiencia cardíaca congestiva derecha grave: El corazón no bombea bien y la sangre se estanca en el cuerpo, filtrándose al abdomen.", "Cáncer avanzado (Ascitis maligna): Especialmente cáncer de ovario, páncreas, estómago, colon o hígado que ha hecho metástasis al revestimiento del peritoneo.", "Insuficiencia renal crónica severa o síndrome nefrótico (pérdida masiva de proteínas en la orina).", "Pancreatitis aguda grave o tuberculosis peritoneal (infección)."] }, diagnosis: { title: "¿Cómo se Diagnostica y Estudia?", intro: "El hepatólogo o médico internista requiere confirmar la presencia de fluido y su causa:", items: ["Examen físico clínico: El médico percutirá (dará golpecitos) el abdomen buscando un sonido de 'matidez cambiante' o el signo de la 'oleada líquida'.", "Ecografía abdominal (Ultrasonido): Es extremadamente sensible y puede detectar volúmenes tan pequeños como 50 ml de líquido ascitico; también evalúa la forma del hígado y bazo.", "Paracentesis diagnóstica: Un procedimiento crucial e ineludible. El médico inserta una aguja larga y fina en el abdomen bajo anestesia local para extraer una muestra del líquido. Esta muestra se envía al laboratorio para buscar bacterias, proteínas, nivel de albúmina y células cancerosas.", "Análisis de sangre generales (perfil hepático, renal, coagulación y plaquetas) para determinar cuán dañado está el hígado."], note: "La paracentesis es vital no solo para el diagnóstico, sino para salvar la vida si el líquido se ha infectado espontáneamente." }, treatment: { title: "Manejo Drenante, Diuréticos y Control", intro: "El tratamiento se enfoca en eliminar el exceso de líquido y tratar la falla de los órganos subyacentes:", subsections: [ { title: "Opciones terapéuticas de la ascitis", items: ["Restricción severa de sal (Sodio): Es el paso número uno e innegociable. Consumir menos de 2000 mg de sodio al día, y a menudo restricción de la cantidad de agua y líquidos que se beben diariamente.", "Diuréticos (Pastillas para orinar): Medicamentos potentes (como Espironolactona combinada con Furosemida) que obligan a los riñones a excretar el exceso de sodio y agua del cuerpo a través de la orina.", "Paracentesis Terapéutica (Drenaje de gran volumen): Si los diuréticos no funcionan o el paciente no puede respirar, el médico inserta una aguja gruesa y drena físicamente litros de líquido (a veces 5 a 10 litros de una sola vez) para dar alivio inmediato, reponiendo proteínas (albúmina) vía intravenosa.", "TIPS (Derivación portosistémica intrahepática transyugular): Un procedimiento radiológico invasivo donde se coloca un stent en el hígado para redirigir la sangre y reducir la hipertensión portal en casos de ascitis rebelde o refractaria.", "Tratamiento oncológico (Quimioterapia o cirugía) si la ascitis es de origen canceroso.", "Trasplante de hígado: La única cura definitiva para la ascitis inducida por la etapa terminal de la cirrosis hepática."] } ], note: "La ascitis no es una enfermedad que se cura con pastillas una sola vez; requiere un estricto manejo de por vida en la ingesta de sal." }, whenToSeekHelp: { title: "¿Cuándo Acudir Rápidamente a Urgencias?", intro: "La ascitis es una condición avanzada. Busque asistencia médica inmediata si un paciente con ascitis conocida presenta:", items: ["Fiebre (incluso febrícula), dolor de estómago de nueva aparición o escalofríos severos (sospecha de Infección Bacteriana Espontánea)", "Confusión repentina, somnolencia extrema, letargo, o si no reconoce a sus familiares (Encefalopatía hepática por acumulación de toxinas en el cerebro)", "Vómitos con sangre fresca o heces oscuras como el alquitrán (rotura de várices esofágicas)", "Aumento de volumen abdominal tan masivo que le es imposible respirar acostado"] } },
'Neuropatía diabética' : { intro: "La neuropatía diabética es un tipo de daño nervioso grave y permanente que ocurre si se tiene diabetes. A lo largo de los años, los niveles altos de azúcar en sangre lesionan lentamente las delicadas fibras nerviosas de todo el cuerpo, comenzando generalmente en las piernas y los pies, lo que puede derivar en úlceras dolorosas o amputaciones.", whatIs: { title: "¿Qué es la Neuropatía Diabética?", text: "Es una complicación neurológica crónica y degenerativa de la diabetes mellitus (tipo 1 y tipo 2). El exceso prolongado de glucosa, sumado a niveles altos de grasas (triglicéridos) en sangre, destruye mecánicamente los pequeños vasos sanguíneos que nutren y oxigenan a los nervios (microangiopatía), provocando su asfixia y mal funcionamiento." }, symptoms: { title: "Síntomas y Señales de Falla Nerviosa", intro: "Los síntomas dependen del tipo de nervios afectados y se desarrollan de forma gradual, a menudo pasando desapercibidos al principio:", groups: [ { name: "Neuropatía periférica (Piernas, Pies y Manos)", items: ["Hormigueo crónico o sensación de 'alfileres y agujas', que frecuentemente empeora por la noche", "Pérdida absoluta de la sensibilidad al dolor, al frío o al calor (el paciente puede pisar un clavo o quemarse y no sentirlo)", "Dolor agudo, punzante, calambres profundos o ardor severo en los pies y pantorrillas", "Hipersensibilidad extrema (el simple roce de la sábana de la cama causa un dolor excruciante)", "Debilidad muscular progresiva y pérdida de equilibrio al caminar"] }, { name: "Neuropatía autonómica (Órganos internos)", items: ["Mareos intensos o desmayos al ponerse de pie repentinamente (hipotensión ortostática)", "Problemas gástricos graves (Gastroparesia): Náuseas, vómitos, saciedad con pocos bocados y distensión debido a la parálisis del estómago", "Incontinencia urinaria, retención de orina o infecciones urinarias frecuentes por falta de tono vesical", "Sudoración profusa inexplicable (especialmente al comer) o ausencia patológica de sudor en los pies", "Disfunción eréctil severa en hombres y sequedad vaginal en mujeres"] } ], warning: "La pérdida de sensibilidad es la causa principal de amputaciones diabéticas. Una herida minúscula o ampolla en un pie entumecido puede infectarse hasta el hueso sin que el paciente lo note." }, types: { title: "Categorías del Daño Nervioso", intro: "Existen cuatro tipos principales de neuropatía en la diabetes:", items: ["Neuropatía periférica (Polineuropatía simétrica distal): El tipo más común; daña primero los nervios más largos (pies y piernas) y luego las manos.", "Neuropatía autonómica: Daña los nervios que controlan órganos vitales involuntarios (corazón, vejiga, estómago, intestinos, ojos).", "Neuropatía proximal (Amiotrofia diabética): Daño a los nervios de los glúteos, caderas o muslos. Causa dolor punzante en un solo lado del cuerpo y debilidad severa para levantarse de una silla.", "Neuropatía focal (Mononeuropatía): Daño súbito y repentino a un nervio específico, frecuentemente en la mano (túnel carpiano), la cabeza, el torso o la pierna. Causa debilidad aislada o visión doble y dolor detrás de un ojo."], note: "Un paciente con mal control glucémico prolongado a menudo sufrirá de neuropatía periférica y autonómica al mismo tiempo." }, causes: { title: "Causas y Aceleradores del Daño", intro: "Es el resultado de un desgaste metabólico prolongado. El riesgo aumenta exponencialmente por:", items: ["Mal control crónico del azúcar en la sangre (Hemoglobina A1c persistentemente alta durante años)", "Años de duración de la enfermedad: El riesgo de daño nervioso es muy alto después de padecer diabetes durante 10 años o más", "Enfermedad renal concomitante (las toxinas no filtradas por los riñones dañan aún más los nervios)", "Exceso de peso, un IMC elevado y falta de actividad física", "Tabaquismo severo (el tabaco estrecha y endurece aún más los vasos sanguíneos vitales de los pies)", "Hipertensión arterial (presión alta crónica)"] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "Los médicos realizan exámenes físicos especializados en la consulta:", items: ["Prueba del Monofilamento: El estándar de oro clínico. El endocrinólogo o podólogo presiona un fino filamento de nylon en varios puntos de la planta del pie del paciente (con los ojos cerrados) para evaluar si ha perdido la sensibilidad táctil protectora.", "Examen neurológico clínico: Comprobación de reflejos tendinosos profundos (como el reflejo rotuliano o de rodilla) y la capacidad de sentir vibraciones utilizando un diapasón en los tobillos.", "Pruebas de conducción nerviosa (NCS): Electrodos aplicados en la piel envían pequeñas corrientes para medir la rapidez y fuerza con que los nervios de brazos y piernas transmiten las señales eléctricas.", "Electromiografía (EMG): Se insertan agujas ultrafinas en los músculos para medir descargas eléctricas musculares y localizar la neuropatía."], note: "La Asociación Americana de Diabetes exige un examen completo y exhaustivo de los pies al menos una vez al año para todo paciente diabético." }, treatment: { title: "Manejo Glicémico, Analgesia y Cuidado de los Pies", intro: "El daño a los nervios no se puede revertir, pero la progresión se detiene estabilizando el metabolismo:", subsections: [ { title: "Control, dolor y prevención", items: ["Control glucémico impecable: Es el único tratamiento que detiene el avance del daño. Requiere estricto cumplimiento de dietas, monitoreo continuo y medicamentos (insulina o pastillas) para mantener el nivel de azúcar en sangre en el rango objetivo.", "Medicamentos para el dolor nervioso (Neuromoduladores): Los analgésicos normales no sirven. Se recetan anticonvulsivos (Pregabalina, Gabapentina) o antidepresivos (Duloxetina, Amitriptilina) que calman las señales erráticas de dolor eléctrico en el cerebro.", "Tratamientos tópicos: Parches de lidocaína o cremas de capsaicina aplicados en los pies para el dolor ardiente.", "Cuidado diario del pie diabético (Crucial): Inspeccionar ambos pies visualmente cada noche buscando cortes o ampollas invisibles, usar calcetines sin costuras, zapatos ortopédicos anchos, cortar las uñas en línea recta por un podólogo profesional y jamás caminar descalzo.", "Manejo de neuropatía autonómica: Comidas más pequeñas y frecuentes (para la gastroparesia), medicamentos para mejorar el vaciado de la vejiga o tratar la disfunción eréctil."] } ], note: "Bajo ninguna circunstancia el paciente debe usar almohadillas térmicas eléctricas o bolsas de agua caliente en los pies para calentarlos, ya que la falta de sensibilidad provocará quemaduras de tercer grado masivas." }, whenToSeekHelp: { title: "¿Cuándo Contactar Urgentemente al Endocrinólogo o Podólogo?", intro: "Es una urgencia diabética de primera línea si usted percibe:", items: ["Una ampolla, corte, rasguño o llaga en su pie que no ha comenzado a sanar visiblemente después de dos o tres días", "La zona del pie está roja, muy caliente, hinchada o supura pus/líquido maloliente (infección bacteriana profunda que puede llegar al hueso)", "Experimenta mareos severos y desmayos cada vez que se levanta de la cama o de una silla", "Aparece dolor, hormigueo continuo o ardor urente en las manos o los pies que interfiere drásticamente con su capacidad de conciliar el sueño"] } },
'Cáncer bucal' : { intro: "El cáncer bucal u oral es un crecimiento tumoral maligno agresivo que se desarrolla en cualquier parte de la boca. Aunque frecuentemente pasa desapercibido en sus primeras etapas porque no duele, es altamente curable si se detecta a tiempo, estando estrechamente vinculado al consumo de tabaco, alcohol intenso y virus papiloma humano.", whatIs: { title: "¿Qué es el Cáncer Bucal?", text: "Es un tipo de cáncer de cabeza y cuello donde células anormales crecen y se multiplican sin control dentro de la cavidad oral. Puede desarrollarse en los labios, las encías, la lengua, el revestimiento interno de las mejillas, el paladar (cielo de la boca) o el piso de la boca (debajo de la lengua)." }, symptoms: { title: "Llagas, Manchas y Síntomas Físicos", intro: "Los síntomas tempranos suelen imitar problemas dentales o aftas comunes, pero la clave es su persistencia prolongada:", groups: [ { name: "Lesiones visuales y llagas (Alertas rojas)", items: ["Una llaga, úlcera o afta profunda en el labio o dentro de la boca que no cicatriza ni mejora después de dos semanas", "Manchas blancas gruesas (Leucoplasia) o manchas de color rojo intenso (Eritroplasia) en el interior de la boca, encías o lengua que no se raspan ni desaparecen", "Un bulto, protuberancia, engrosamiento, o una costra rugosa en el labio, la mejilla interior o la lengua"] }, { name: "Síntomas mecánicos y dolorosos avanzados", items: ["Aflojamiento repentino e inexplicable de dientes en una zona (sin que exista enfermedad de las encías general)", "Dificultad o dolor crónico al intentar masticar, tragar, hablar o mover la mandíbula o la lengua", "Dolor persistente de oídos (frecuentemente unilateral) pero sin que exista una infección de oído subyacente", "Sensación constante de tener algo atorado en la garganta o cambios drásticos en la forma en que encajan las dentaduras postizas", "Aparición de un bulto indoloro que crece lentamente en el área del cuello (ganglios linfáticos con metástasis)"] } ], warning: "Toda llaga oral o mancha blanca/roja que dure más de 14 días sin cicatrizar debe ser biopsiada obligatoriamente; es el signo de cáncer oral número uno." }, types: { title: "Tipos Histológicos Principales", intro: "La naturaleza de las células afectadas define la agresividad del cáncer:", items: ["Carcinoma de Células Escamosas (90% de los casos): Comienza en las células planas y delgadas (escamosas) que recubren los labios y el interior de toda la boca. Es el tipo dominante indiscutible.", "Carcinoma Verrugoso: Un subtipo de crecimiento muy lento del carcinoma de células escamosas que rara vez hace metástasis, con aspecto de verruga gruesa.", "Cáncer de glándulas salivales menores (Adenocarcinomas): Ocurre en las glándulas dispersas por el paladar blando y mucosas.", "Melanoma Mucoso Oral: Extremadamente raro y agresivo; se desarrolla en las células productoras de pigmento (melanocitos) de los labios o las encías, formando manchas oscuras."], note: "El cáncer bucal relacionado con el VPH ocurre con mayor frecuencia en la base posterior de la lengua y en las amígdalas (orofaringe), afectando a pacientes más jóvenes y sin historial de tabaco." }, causes: { title: "Factores de Riesgo Oncológicos Modificables", intro: "Este cáncer es, en la gran mayoría de los casos, consecuencia directa del estilo de vida o infecciones virales:", items: ["Consumo de Tabaco de cualquier tipo: Cigarrillos, puros, pipas y, de manera críticamente alta, el tabaco de mascar o polvo (snuff), que triplican o cuadruplican el riesgo y causan el cáncer directamente en la zona donde se mastica el tabaco.", "Consumo excesivo de alcohol crónico: Los grandes bebedores tienen alto riesgo, pero las personas que beben alcohol masivamente y fuman tabaco tienen un riesgo sinérgico letal (hasta 15 veces mayor).", "Infección por el Virus del Papiloma Humano (VPH 16): La causa de mayor crecimiento actualmente, responsable del drástico aumento del cáncer oral y de garganta en personas jóvenes, no fumadoras.", "Exposición solar intensa (rayos UV) crónica y prolongada sin protección labial (principal causa del cáncer en el labio inferior).", "Sistema inmunológico debilitado crónicamente o desnutrición severa (dietas bajas en frutas y vegetales frescos)."] }, diagnosis: { title: "¿Cómo se Evalúa y Estadifica?", intro: "El dentista o cirujano maxilofacial es la primera línea de detección, utilizando:", items: ["Examen rutinario de detección de cáncer oral: Inspección visual y palpación profunda de la lengua, paladar, encías y el piso de la boca durante una visita dental, buscando bultos duros o parches anormales de tejido.", "Biopsia de tejido (el único método de diagnóstico real): Se aplica anestesia local y se extrae una muestra de la llaga o zona blanca/roja con bisturí (biopsia por incisión) o con una aguja hueca para ser evaluada por un patólogo bajo microscopio buscando células malignas.", "Prueba de VPH (hibridación in situ) aplicada a la muestra de biopsia para determinar la causa y pronóstico (los tumores VPH positivos suelen responder mejor al tratamiento).", "Estudios de imagen oncológica (TC, RM, Escáner PET de cabeza y cuello): Son fundamentales una vez confirmado el cáncer para determinar si el tumor ha penetrado en el hueso maxilar o se ha diseminado a los ganglios linfáticos del cuello o los pulmones."], note: "La detección temprana por parte del dentista salva vidas; las etapas iniciales (I y II) tienen una tasa de curación superior al 80%." }, treatment: { title: "Extirpación Quirúrgica y Oncología de Cabeza y Cuello", intro: "El tratamiento a menudo requiere equipos multidisciplinarios debido al impacto en la respiración, el habla y la estética facial:", subsections: [ { title: "Modalidades de Tratamiento", items: ["Cirugía oncológica radical: El tratamiento principal para tumores pequeños. Consiste en la extirpación quirúrgica completa del tumor en la boca junto con un margen de tejido sano alrededor. A menudo incluye disección del cuello (extirpar ganglios linfáticos linfáticos circundantes en el cuello para detener la metástasis).", "Cirugía reconstructiva reconstructiva: En tumores grandes que requirieron extirpar partes de la mandíbula o la lengua, los cirujanos utilizan colgajos de hueso o músculo de otras partes del cuerpo (como la pierna) para reconstruir el rostro y permitir al paciente tragar y hablar de nuevo.", "Radioterapia externa: Uso intensivo de haces de alta energía dirigidos al área afectada después de la cirugía para matar células remanentes, o como tratamiento primario en tumores pequeños inoperables.", "Quimioterapia y Terapias Dirigidas (Cetuximab): Fármacos agresivos combinados casi siempre con radioterapia para tumores avanzados, voluminosos o que se han propagado.", "Rehabilitación obligatoria post-tratamiento: Logopedas, fonoaudiólogos y nutricionistas para enseñar al paciente a hablar y tragar nuevamente de manera segura."] } ], note: "Tras el diagnóstico, el cese inmediato, absoluto y total del tabaco y alcohol es mandatorio, o el riesgo de desarrollar un segundo tumor mortal es inmenso." }, whenToSeekHelp: { title: "¿Cuándo Acudir Rápidamente al Dentista o Maxilofacial?", intro: "Solicite una cita de valoración prioritaria urgente si observa en su boca:", items: ["Una úlcera, afta o corte en la encía, debajo de la lengua o en el interior del labio que no cicatriza en absoluto después de dos o tres semanas", "Aparición de manchas blanquecinas rugosas o rojo oscuro sangrantes y sin dolor en la mucosa oral", "Un crecimiento carnoso o bulto duro inusual que parece estar creciendo lentamente", "Experimenta un dolor crónico, adormecimiento persistente de los labios o dolor al intentar tragar saliva o alimentos"] } },
'Onicomicosis' : { intro: "La onicomicosis es una infección fúngica de las uñas (generalmente en los pies, rara vez en las manos) profundamente tenaz y muy difícil de curar. Aunque empieza como una mancha blanca o amarillenta menor, el hongo penetra lentamente debajo de la uña, volviéndola gruesa, deforme y quebradiza, lo que puede causar dolor al caminar y gran incomodidad estética.", whatIs: { title: "¿Qué es la Onicomicosis (Hongos en las Uñas)?", text: "Es una infección crónica causada por la proliferación de organismos microscópicos fúngicos (dermatofitos, levaduras o mohos) que invaden el lecho ungueal (la piel debajo de la uña) y la placa ungueal (la parte dura de queratina). Los hongos prosperan digiriendo activamente la queratina de la uña." }, symptoms: { title: "Síntomas Visuales y Estructurales de la Uña", intro: "Los síntomas son típicamente inofensivos al principio, pero desfiguran la uña de manera progresiva:", groups: [ { name: "Cambios en el aspecto y textura", items: ["Decoloración oscura o amarillenta visible: La uña adquiere un tono amarillo opaco, marrón, verdoso oscuro o aparecen múltiples puntos/rayas de color blanco tiza en la superficie", "Engrosamiento extremo o hipertrofia de la uña, haciendo casi imposible cortarla con cortaúñas normales", "Distorsión severa de la forma o levantamiento total (la uña se separa físicamente del lecho ungueal rosado subyacente, dejando un espacio hueco)", "Fragilidad y desmoronamiento; la uña se vuelve quebradiza, polvorienta y los bordes se astillan constantemente", "Acumulación de detritos o polvo grisáceo fétido de mal olor atrapado debajo del borde de la uña afectada"] }, { name: "Síntomas físicos (Casos avanzados)", items: ["Dolor o presión sorda y pulsátil en el dedo afectado al usar zapatos apretados, debido a que la uña hiper-engrosada choca con el calzado", "Dificultad o dolor al caminar, correr o estar de pie prolongadamente si la afección involucra la uña del dedo gordo del pie"] } ], warning: "Si usted padece de diabetes, neuropatía o mala circulación, no intente cortar o tratar una uña fúngica en casa; una microherida puede desatar una celulitis (infección bacteriana grave en toda la pierna)." }, types: { title: "Patrones de Invasión Fúngica", intro: "El hongo invade la uña de diferentes maneras, lo que ayuda al dermatólogo a diagnosticarlo:", items: ["Onicomicosis Subungueal Distal y Lateral: Es el patrón más común (más del 80%). Causada por el dermatofito (Trichophyton rubrum). El hongo comienza en la punta de la uña (borde libre) o a los lados y avanza lentamente hacia la base o cutícula.", "Onicomicosis Superficial Blanca: Aparecen manchas blancas polvorientas y secas directamente sobre la superficie superior de la lámina de la uña del pie. La uña no se engrosa inicialmente.", "Onicomicosis Subungueal Proximal: Menos común. La infección comienza en la cutícula (la base) y se extiende hacia la punta. Es muy frecuente en personas con VIH o con el sistema inmunológico severamente comprometido.", "Onicomicosis por Candida (Levadura): Ocurre frecuentemente en las uñas de las manos de personas que mantienen las manos crónicamente sumergidas en agua (meseros, limpiadores). Se acompaña de inflamación y enrojecimiento severo en el borde de la piel."], note: "El pie de atleta (infección fúngica en la piel entre los dedos) a menudo ocurre simultáneamente y es el punto de origen desde el cual el hongo salta e invade la uña." }, causes: { title: "Causas, Hongos Dermatofitos y Riesgos del Ambiente", intro: "Los microorganismos prosperan exclusivamente en entornos oscuros, cálidos y muy húmedos:", items: ["Dermatofitos ambientales: Un grupo de hongos que necesitan la proteína queratina para vivir, causantes de la inmensa mayoría de las infecciones de pies.", "Caminar descalzo en ambientes públicos constantemente húmedos (bordes de piscinas públicas, gimnasios, baños, saunas o duchas compartidas).", "Calzado inadecuado: Uso crónico de zapatos cerrados, de materiales sintéticos no transpirables y apretados, sumado a medias empapadas en sudor.", "Envejecimiento: Es abrumadoramente más común en adultos mayores debido a una menor circulación sanguínea en las extremidades, años de exposición repetida a hongos y uñas que crecen de manera más lenta y gruesa.", "Microtraumatismos constantes: Corredores, bailarinas o uso de zapatos que aprietan la punta, causando que la uña se separe milimétricamente de la piel, creando una puerta de entrada para que el hongo se aloje.", "Condiciones médicas: Diabetes, psoriasis, enfermedad arterial periférica, sistema inmunológico debilitado, o usar uñas acrílicas constantes que atrapan humedad y levaduras."] }, diagnosis: { title: "¿Cómo se Diagnostica Clínicamente?", intro: "Para no confundirlo con psoriasis o traumas de la uña (que lucen igual), el dermatólogo o podólogo recurre a:", items: ["Examen visual experto de todas las uñas y del espacio interdigital de la piel del pie (buscando descamación o pie de atleta crónico).", "Recolección de muestra y recorte de uñas (Raspado Ungueal): El médico corta o raspa meticulosamente los restos polvorientos que hay debajo de la uña amarilla.", "Examen directo de Hidróxido de Potasio (KOH): Se coloca la muestra raspada bajo un microscopio con químicos para destruir la queratina; esto permite visualizar instantáneamente en el consultorio si las hebras de hongos (hifas) están presentes y confirmar la infección.", "Cultivo fúngico de laboratorio: La muestra se envía a un laboratorio para crecer en una placa Petri. Tarda varias semanas, pero es indispensable para averiguar exactamente qué cepa específica de hongo o moho es el culpable, y así recetar el medicamento de vía oral preciso si el estándar falla.", "Prueba PAS (tinción histológica con ácido peryódico de Schiff) de un trozo o recorte de uña en laboratorios patológicos, siendo la prueba más cara pero la más precisa existente en la actualidad."], note: "Aproximadamente el 50% de las uñas amarillas y gruesas NO son hongos; pueden ser daño físico de los zapatos o afecciones dermatológicas autoinmunes, por lo que iniciar pastillas hepatotóxicas sin confirmación de laboratorio es mala praxis clínica." }, treatment: { title: "Abordaje Antimicótico Sistémico, Tópico y Láser", intro: "Es famoso por ser desesperantemente resistente al tratamiento. Ninguna crema penetra bien la placa dura de la uña; se requiere tenacidad prolongada:", subsections: [ { title: "Arsenal Farmacológico e Intervencionista", items: ["Antifúngicos de ingesta oral (La primera y mejor línea curativa): Medicamentos sistémicos agresivos como Terbinafina (Lamisil) o Itraconazol administrados en formato de pastilla diaria ininterrumpida durante 12 a 16 dolorosas semanas completas para las uñas de pies. Viajan por la sangre, depositándose bajo la matriz ungular y asegurando que la parte nueva de la uña crezca totalmente libre y limpia del hongo. (Requiere exámenes de control estricto de transaminasas de función del hígado, ya que pueden ser altamente hepatotóxicos).", "Lacas de uñas medicadas (Esmaltes tópicos médicos recetados): Como la Ciclopirox (Penlac) o Efinaconazol (Jublia). El paciente pinta la uña cada noche durante 48 largas semanas. Su tasa de éxito o eficacia es pobre y baja si se usa sola, siendo útil solo para infecciones iniciales y muy superficiales.", "Tratamiento con terapias de láser o luz focalizada (Láser Nd:YAG o similares): Dirigen haces intensos de luz a la uña a través de sesiones ambulatorias, teóricamente destruyendo térmicamente al hongo subyacente (sus resultados de cura general son variables, no están cubiertos universalmente y requieren complemento y desbridamiento manual).", "Avulsión o extracción quirúrgica o química de la lámina ungueal (Extracción del dedo): Como última opción final para uñas extremadamente o patológicamente dolorosas y engrosadas severas; el podólogo arranca toda la placa ungular bajo anestesia de bloqueo para curar el lecho infectado directamente desde la base limpia y aplicar el antifúngico in situ a la piel."] } ], note: "La uña del pie sano tarda hasta 12 o 18 meses biológicos en reemplazar completamente la uña desde la base hasta la punta; el paciente no verá la curación hasta un año después de haber finalizado el medicamento recetado de 3 meses." }, whenToSeekHelp: { title: "¿En Qué Casos Derivar a Especialidad Médica (Podólogo o Dermatología)?", intro: "Agende cita clínica de revisión profesional para iniciar el cultivo diagnóstico fúngico y no aplique más remedios 'naturales' y caseros de escasa penetración cuando:", items: ["El engrosamiento masivo u amarillento progresivo en sus uñas ha vuelto imposible e inmanejable físicamente poder cortarlas o recortarlas de forma higiénica", "El grosor anormal severo de las uñas genera un dolor crónico, contundente o pulsátil continuo en el dedo simplemente por la presión de ponerse un calcetín ajustado o zapatos de diario", "La uña deformada o amarilla está generando una intensa rojez cutánea, hinchazón del tejido adyacente circundante de inflamación o secreción supurante de sangre en el contorno y perímetro cutáneo ungular", "Padece diabetes general no controlada y observa u visualiza por primera vez un cambio mínimo en el color de sus uñas (el cuidado podológico profiláctico y preventivo inmediato debe ser absoluto)"] } },
'Perimenopausia' : { intro: "La perimenopausia es la fase de transición natural hacia la menopausia, marcando el final de los años reproductivos de una mujer. Durante este período, los niveles hormonales fluctúan caóticamente, provocando una variedad de síntomas físicos y emocionales antes del cese definitivo de la menstruación.", whatIs: { title: "¿Qué es la Perimenopausia?", text: "Es el tiempo durante el cual el cuerpo de la mujer hace la transición natural y gradual hacia la menopausia. Los ovarios comienzan a producir menos estrógeno de forma errática. Puede durar desde unos pocos meses hasta más de diez años, finalizando oficialmente cuando la mujer pasa 12 meses consecutivos sin tener su período menstrual." }, symptoms: { title: "Síntomas y Cambios Físicos", intro: "Las fluctuaciones de estrógeno provocan síntomas que varían ampliamente en intensidad:", groups: [ { name: "Irregularidades menstruales", items: ["Ciclos más largos o más cortos de lo habitual", "Flujo menstrual inusualmente escaso o excesivamente abundante", "Saltarse uno o varios períodos menstruales seguidos"] }, { name: "Síntomas vasomotores y emocionales", items: ["Sofocos repentinos y sudores nocturnos intensos que interrumpen severamente el sueño", "Sequedad vaginal, molestias durante las relaciones sexuales y disminución del deseo (libido)", "Cambios bruscos de humor, irritabilidad, ansiedad y mayor riesgo de depresión leve a moderada", "Fatiga constante, problemas de concentración o memoria a corto plazo ('niebla mental') y urgencia urinaria"] } ], warning: "Aunque los períodos sean irregulares e impredecibles, la ovulación aún puede ocurrir y el embarazo sigue siendo posible; se deben usar métodos anticonceptivos hasta confirmar la menopausia." }, types: { title: "Fases de la Transición", intro: "El proceso se divide generalmente en dos etapas principales:", items: ["Perimenopausia temprana: Los ciclos menstruales comienzan a ser irregulares, variando en duración por siete días o más de un mes a otro.", "Perimenopausia tardía: Se caracteriza por saltarse dos o más ciclos menstruales y experimentar períodos de amenorrea (ausencia de sangrado) de 60 días o más, frecuentemente acompañada de sofocos más severos."], note: "El tabaquismo activo puede adelantar el inicio de la perimenopausia en uno o dos años en comparación con mujeres no fumadoras." }, causes: { title: "Causas y Factores que la Adelantan", intro: "Es un proceso biológico natural e inevitable, pero ciertos factores determinan su momento de inicio:", items: ["Envejecimiento natural: La reserva de folículos en los ovarios disminuye y estos se vuelven menos sensibles a las hormonas cerebrales que estimulan la ovulación.", "Genética e historia familiar: La edad en la que una mujer experimenta la perimenopausia suele estar fuertemente ligada a la edad en la que su madre o hermanas la experimentaron.", "Tratamientos oncológicos o médicos: La quimioterapia, la radioterapia pélvica o la extirpación quirúrgica de un ovario pueden desencadenarla prematuramente.", "Factores de estilo de vida: Las mujeres que fuman de manera crónica o tienen un índice de masa corporal (IMC) extremadamente bajo tienden a entrar en esta fase tempranamente."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico y se basa en el historial de la paciente:", items: ["Evaluación del historial menstrual: El ginecólogo evaluará minuciosamente los cambios en la regularidad, duración y volumen del sangrado.", "Evaluación de síntomas concurrentes: Presencia de sofocos, alteraciones del sueño y cambios de humor inexplicables.", "Análisis de sangre (opcionales): Medición de la hormona foliculoestimulante (FSH) y el estrógeno, aunque sus niveles fluctúan tanto diariamente durante esta fase que una sola prueba rara vez es concluyente o necesaria.", "Pruebas de la glándula tiroides (TSH): Para descartar que los síntomas (como la fatiga extrema o irregularidades menstruales) sean causados por hipotiroidismo, que imita los signos menopáusicos."], note: "El médico se centrará primordialmente en descartar pólipos, fibromas o cáncer endometrial como causas del sangrado anormal intenso antes de atribuirlo simplemente a la perimenopausia." }, treatment: { title: "Manejo de Síntomas", intro: "El tratamiento no detiene el proceso de envejecimiento ovárico, sino que busca mejorar radicalmente la calidad de vida:", subsections: [ { title: "Terapias médicas y alivio localizado", items: ["Terapia hormonal (estrógeno y progesterona) en dosis bajas: El tratamiento sistémico más efectivo, si no hay contraindicaciones, para aliviar los sofocos severos y sudores nocturnos.", "Antidepresivos (ISRS/IRSN): Medicamentos como la paroxetina o la venlafaxina son muy efectivos para reducir los sofocos y estabilizar el humor en mujeres que no pueden o no desean tomar terapia hormonal.", "Estrógeno vaginal local: En forma de cremas, anillos o tabletas para tratar la sequedad profunda, la atrofia y el dolor en las relaciones sexuales sin afectar todo el cuerpo.", "Anticonceptivos orales de dosis baja: Utilizados a menudo para regularizar el sangrado caótico, detener las fluctuaciones hormonales y aliviar los síntomas simultáneamente.", "Modificaciones del estilo de vida: Vestir en capas, mantener la habitación fresca, evitar el alcohol, las comidas picantes y la cafeína (detonantes de sofocos), y mantener un peso saludable mediante ejercicio regular."] } ], note: "El uso de suplementos naturales (como isoflavonas de soja, maca o cohosh negro) tiene eficacia variable y siempre debe consultarse con el ginecólogo para evitar interacciones medicamentosas." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Ginecólogo?", intro: "Debe programar una consulta médica si los síntomas afectan su bienestar o si el sangrado es alarmante:", items: ["El sangrado menstrual es tan abundante que empapa una toalla sanitaria o tampón de tamaño máximo cada hora durante más de dos horas seguidas", "El sangrado dura sistemáticamente más de siete u ocho días consecutivos", "Experimenta manchado o sangrado vaginal inexplicable entre sus períodos regulares o justo después de tener relaciones sexuales", "Los sofocos o los cambios de humor son tan intensos y paralizantes que no le permiten dormir, causan depresión profunda o le impiden funcionar normalmente en el trabajo"] } },
'Distrofia muscular' : { intro: "La distrofia muscular agrupa a un conjunto de enfermedades genéticas raras y devastadoras que causan debilidad progresiva y pérdida de la masa muscular. Con el tiempo, la degeneración continua impide la movilidad independiente, la función respiratoria y la salud cardíaca, requiriendo atención médica multidisciplinaria de por vida.", whatIs: { title: "¿Qué es la Distrofia Muscular?", text: "Es un grupo de más de 30 trastornos hereditarios en los que mutaciones en genes específicos interfieren con la producción de proteínas vitales (como la distrofina) necesarias para formar y mantener los músculos sanos. Sin estas proteínas, las fibras musculares se rompen, mueren y son reemplazadas por grasa y tejido cicatricial." }, symptoms: { title: "Síntomas y Progresión Física", intro: "Los síntomas suelen aparecer en la primera infancia, especialmente en niños varones, e incluyen de forma progresiva:", groups: [ { name: "Señales motoras tempranas (2 a 5 años)", items: ["Retraso evidente para empezar a caminar, caídas muy frecuentes y torpeza inusual generalizada", "Dificultad manifiesta para levantarse desde una posición sentada o acostada en el suelo (Maniobra de Gowers: el niño tiene que 'trepar' por sus propias piernas empujándose con las manos para ponerse de pie)", "Caminar constantemente de puntillas o tener una marcha de pato (balanceante) con el abdomen hacia adelante", "Músculos de las pantorrillas inusualmente grandes y firmes (pseudohipertrofia, donde el músculo sano es reemplazado por tejido adiposo)"] }, { name: "Síntomas avanzados y complicaciones", items: ["Pérdida progresiva y total de la capacidad de caminar (requiriendo dependencia de una silla de ruedas generalmente antes de la adolescencia temprana)", "Dificultades severas para tragar alimentos y riesgo de asfixia", "Desarrollo de escoliosis grave (curvatura torcida de la columna) debido a la profunda debilidad de los músculos de soporte de la espalda", "Problemas respiratorios y complicaciones cardíacas letales (miocardiopatía dilatada) por el debilitamiento del músculo del corazón e intercostales"] } ], warning: "Si nota que su hijo pequeño tiene pantorrillas desproporcionadamente grandes, camina de puntillas y debe usar sus manos sobre sus rodillas para poder enderezarse desde el piso, solicite una evaluación neurológica pediátrica de inmediato." }, types: { title: "Tipos Principales de Distrofia", intro: "Se clasifican según el gen mutado, el momento de inicio y los músculos afectados primero:", items: ["Distrofia Muscular de Duchenne (DMD): La forma más común y agresiva en niños. Afecta casi exclusivamente a varones debido a una carencia total de la proteína distrofina; el deterioro es rápido.", "Distrofia de Becker: Similar a Duchenne pero más leve y de progresión más lenta hacia la edad adulta; el cuerpo produce distrofina, pero es defectuosa, corta o insuficiente.", "Distrofia Miotónica (Enfermedad de Steinert): La forma más común de inicio en adultos. Se caracteriza por miotonía (incapacidad total de relajar los músculos después de contracciones, ej. no poder soltar un pomo de puerta).", "Distrofia Facioescapulohumeral (FSHD): Debilidad que comienza y afecta típicamente primero a los músculos de la cara (dificultad para sonreír o cerrar los ojos), los hombros y la parte superior de los brazos.", "Distrofia de Cinturas: Afecta primeramente a los músculos de las caderas y los hombros, manifestándose en la infancia o la edad adulta temprana."], note: "Aunque las niñas muy rara vez desarrollan la forma severa de Duchenne, pueden ser 'portadoras' y presentar síntomas de debilidad muscular leve o problemas cardíacos graves en la edad adulta." }, causes: { title: "Causas, Genética y Herencia", intro: "El origen es estrictamente genético, sin relación alguna con el estilo de vida o factores prenatales prevenibles:", items: ["Mutaciones genéticas ligadas al cromosoma X (Duchenne y Becker): Las madres son portadoras del gen mutado en uno de sus dos cromosomas X y lo transmiten de forma asintomática. Los hijos varones (XY) que heredan el cromosoma X defectuoso desarrollarán inevitablemente la enfermedad, ya que no tienen un segundo cromosoma X para compensar.", "Mutaciones espontáneas (De novo): Hasta en un 30% de todos los casos de Duchenne, no existen antecedentes familiares previos en absoluto; la mutación genética destructiva ocurre de manera espontánea y aleatoria en el óvulo o durante la división celular del embrión temprano.", "Fisiopatología de la Distrofina: Esta proteína gigantesca actúa como un 'amortiguador' y ancla esencial dentro de las membranas de las fibras musculares. En su ausencia, el esfuerzo del movimiento cotidiano desgarra las células musculares, provocando inflamación crónica y muerte del tejido."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El neurólogo infantil utilizará pruebas moleculares y químicas para confirmar la enfermedad:", items: ["Análisis de sangre de enzimas musculares (Creatina Quinasa - CK): Las fibras musculares rotas liberan enzimas hacia la sangre. Niveles astronómicamente altos de CK en un niño sin lesiones recientes o ejercicio extremo sugieren fuertemente distrofia.", "Pruebas genéticas de ADN: El examen definitivo (estándar de oro). A través de una simple muestra de sangre, detecta la mutación exacta o la deleción en el gen de la distrofina, evitando procedimientos dolorosos.", "Electromiografía (EMG): Inserción de electrodos de aguja fina en el músculo para medir su actividad eléctrica y confirmar que la debilidad extrema proviene de una enfermedad del propio músculo (miopatía) y no de un daño en los nervios de la médula.", "Biopsia muscular (menos común en la era moderna de la genética): Extracción quirúrgica de un pequeño trozo de músculo para analizarlo mediante tinción y buscar visualmente la ausencia total de distrofina bajo el microscopio.", "Evaluación cardíaca rutinaria (Ecocardiograma) e interconsulta respiratoria para evaluar daños silentes tempranos."], note: "Confirmar el diagnóstico genéticamente es fundamental, ya que hoy en día existen medicamentos diseñados para tratar mutaciones genéticas muy específicas (terapia dirigida)." }, treatment: { title: "Manejo Clínico, Fisioterapia y Terapias Genéticas", intro: "Aunque actualmente no existe una cura, los tratamientos modernos han mejorado drásticamente la calidad y la esperanza de vida:", subsections: [ { title: "Intervenciones médicas, de soporte y rehabilitación", items: ["Corticosteroides diarios (Prednisona o Deflazacort): Son la piedra angular del tratamiento farmacológico. Ralentizan significativamente la degeneración muscular, mejoran la fuerza pulmonar y pueden prolongar la capacidad del niño para caminar de forma independiente durante varios años adicionales.", "Nuevas terapias genéticas y de 'salto de exón': Medicamentos intravenosos recientemente aprobados (como Eteplirsen, Golodirsen, Viltolarsen o terapias génicas de microdistrofina) que engañan a las células para que produzcan una proteína funcional parcial, ralentizando el curso letal de la enfermedad en mutaciones específicas.", "Soporte cardiológico temprano: Uso de inhibidores de la ECA y betabloqueantes antes de que aparezcan síntomas de insuficiencia cardíaca, protegiendo el músculo cardíaco de la dilatación severa.", "Rehabilitación intensiva: Fisioterapia diaria, uso innegociable de férulas nocturnas y estiramientos para retrasar las dolorosas contracturas (tendones acortados y congelados) que deforman las articulaciones de los tobillos y rodillas.", "Cirugía Ortopédica: Alargamiento de tendones o cirugía mayor de fusión espinal de urgencia si la escoliosis amenaza con comprimir los pulmones.", "Soporte respiratorio asistido: Uso de dispositivos como máquinas BiPAP (ventilación no invasiva) por la noche, y máquinas de asistencia mecánica para toser (CoughAssist) para limpiar los pulmones de secreciones y evitar neumonías fatales en etapas avanzadas de inmovilidad en silla de ruedas."] } ], note: "La participación de un equipo multidisciplinario altamente coordinado (neurólogos, neumólogos, cardiólogos, ortopedistas y psicólogos) es absolutamente vital para prolongar la supervivencia más allá de la adolescencia." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Pediatra Neurológico?", intro: "Es crucial solicitar una evaluación temprana del desarrollo psicomotor si su hijo o bebé:", items: ["Muestra un retraso significativo para aprender a sentarse solo, gatear, o no logra dar pasos de forma independiente después de los 15 a 18 meses de edad", "Experimenta caídas constantes, torpeza motora extrema y parece no tener fuerza en las piernas para correr o saltar como sus compañeros", "Muestra una técnica inusual y forzada para levantarse del piso, apoyando firmemente las manos en sus propias rodillas, espinillas y muslos para poder enderezar el tronco (Signo de Gowers positivo)", "Tiene pantorrillas que se ven anormal y desproporcionadamente firmes o agrandadas en comparación con el volumen delgado del resto de sus extremidades"] } },
'Parto prematuro' : { intro: "El parto prematuro ocurre cuando se desencadenan contracciones regulares que abren el cuello del útero antes de que el bebé esté completamente maduro y listo para nacer. Es la principal causa de morbilidad y mortalidad neonatal a nivel mundial, ya que los bebés prematuros enfrentan riesgos vitales de problemas respiratorios, neurológicos, hemorragias cerebrales y de desarrollo a largo plazo.", whatIs: { title: "¿Qué es el Trabajo de Parto Prematuro?", text: "Es el proceso fisiológico de inicio de parto (contracciones uterinas continuas que resultan en dilatación y borramiento del cuello uterino) que ocurre demasiado temprano: después de la semana 20 de embarazo y antes de completar la semana 37. Un embarazo saludable a término completo debería durar 40 semanas para el desarrollo óptimo del feto." }, symptoms: { title: "Síntomas y Señales de Alarma Temprana", intro: "Los síntomas pueden ser sutiles o parecerse a las incomodidades normales del final del embarazo, por lo que la vigilancia constante es la clave de la prevención:", groups: [ { name: "Contracciones y dolor persistente", items: ["Contracciones uterinas regulares, frecuentes e indoloras o dolorosas (una sensación rítmica de que el abdomen se endurece como un balón de baloncesto y luego se relaja), que ocurren 4 o más veces en una hora", "Dolor sordo, constante y rítmico en la parte baja de la espalda (zona lumbar) que no cede ni mejora al descansar, cambiar de posición o hidratarse", "Calambres abdominales en la parte inferior, con una sensación similar a los fuertes dolores de la menstruación, que a veces vienen acompañados de episodios de diarrea repentina"] }, { name: "Cambios pélvicos y flujo vaginal", items: ["Presión pélvica muy intensa o sensación inusual de que el bebé está empujando hacia abajo para salir de la vagina", "Cambio drástico en el flujo vaginal normal (volviéndose repentinamente más acuoso, excesivamente mucoso, o desprendimiento del tapón mucoso)", "Manchado rosado o sangrado vaginal directo de color rojo brillante", "Rotura prematura de membranas: un chorro súbito de líquido claro o un goteo caliente y constante de fluido desde la vagina (romper fuente de manera adelantada)"] } ], warning: "Si usted tiene menos de 37 semanas y experimenta contracciones regulares (cada 10-15 minutos) o pierde líquido por la vagina, no espere al día siguiente; acuda inmediatamente al área de urgencias obstétricas, ya que ganar horas es crucial para inyectar medicación para los pulmones del bebé." }, types: { title: "Clasificación según la Edad Gestacional y Origen", intro: "Los riesgos letales y de salud crónica para el recién nacido dependen directamente de cuán temprano nazca en el calendario:", items: ["Prematuro extremo: Nacido a las 28 semanas de gestación o menos. Tienen un riesgo inmenso de mortalidad, parálisis cerebral, ceguera y requieren soporte vital respiratorio invasivo inmediato en la UCIN.", "Muy prematuro: Nacido entre las 28 y las 32 semanas de gestación.", "Prematuro moderado a tardío: Nacido entre las 32 y las 37 semanas completas. Tienen excelentes tasas de supervivencia, pero aún pueden sufrir apnea del sueño, problemas respiratorios leves, ictericia y dificultades graves para succionar y alimentarse.", "Parto prematuro espontáneo (inicia por sí solo sin razón aparente) frente a Parto prematuro indicado por medicina (el obstetra induce el parto o hace cesárea tempranamente para salvar la vida de la madre o el bebé por preeclampsia grave, desprendimiento de placenta o restricción del crecimiento fetal)."], note: "En la prematurez, cada semana, e incluso cada día extra que el bebé logra permanecer oxigenado dentro del útero materno, mejora de manera estadísticamente drástica su supervivencia y pronóstico neurológico a largo plazo." }, causes: { title: "Causas, Factores de Riesgo e Infecciones", intro: "Aunque la causa exacta de que un útero comience a contraerse temprano a menudo es un misterio biológico, el riesgo global aumenta contundentemente por:", items: ["Antecedentes obstétricos directos: Haber tenido un parto prematuro previo es el factor de riesgo número uno y más predictivo para que vuelva a suceder en futuros embarazos.", "Sobredistensión uterina: Un embarazo múltiple (llevar gemelos, trillizos o más), o un exceso severo de líquido amniótico (polihidramnios), lo que estira el útero más allá de su capacidad prematuramente.", "Infecciones sistémicas o locales: Infecciones del tracto urinario severas, infecciones vaginales crónicas (vaginosis bacteriana), o corioamnionitis (infección del líquido amniótico), cuyas bacterias liberan prostaglandinas que detonan contracciones explosivas.", "Problemas del útero o del cérvix: Cuello uterino anatómicamente corto detectado por ecografía, o incompetencia cervical (el cuello uterino se abre y acorta silenciosamente y sin dolor bajo el peso del bebé), anomalías del útero bicorne o miomas grandes.", "Complicaciones maternas y placentarias: Preeclampsia (hipertensión), diabetes gestacional, problemas de coagulación profunda o un intervalo entre embarazos demasiado corto (menos de 6 a 18 meses).", "Estilo de vida y trauma ambiental: Tabaquismo activo, uso de drogas ilícitas (sobre todo cocaína que causa desprendimiento de placenta), estrés psicológico crónico severo continuo, violencia doméstica o falta extrema de atención médica prenatal."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica la Gravedad en Emergencias?", intro: "En urgencias de maternidad, el objetivo absoluto es confirmar si existe dilatación real y trabajo de parto activo:", items: ["Monitorización fetal y tocodinamometría uterina: Se colocan cinturones con sensores en el abdomen de la madre para registrar electrónicamente y medir la fuerza, duración y frecuencia exacta de las contracciones uterinas, así como el ritmo cardíaco del bebé para descartar sufrimiento fetal.", "Examen pélvico clínico y Ecografía transvaginal urgente: El obstetra especialista medirá con precisión milimétrica la longitud del cuello uterino mediante ultrasonido interno para ver si se ha acortado o si se está abriendo por dentro formando un embudo (embudización cervical), lo cual es predictor inminente de parto.", "Prueba de Fibronectina Fetal (fFN): Se toma rápidamente una muestra de las secreciones vaginales profundas con un hisopo estéril. Si esta 'proteína pegamento' (que une el saco amniótico al revestimiento del útero) se encuentra anormalmente presente en la vagina, significa que el saco se está desprendiendo y hay un altísimo riesgo de parto inminente.", "Análisis de orina urgente y cultivos de exudado vaginal profundo para detectar bacterias, clamidia, gonorrea o estreptococo del grupo B ocultos causantes de los espasmos."], note: "Una prueba de fibronectina fetal de resultado 'negativo' tiene un valor clínico altamente tranquilizador, indicando con más del 95% de seguridad que es muy poco probable que la mujer dé a luz prematuramente en las próximas dos semanas." }, treatment: { title: "Tratamiento Tocolítico, Maduración Fetal y Prevención Pélvica", intro: "El objetivo hospitalario inmediato es retrasar el parto el mayor tiempo posible para dar ventana de acción a los medicamentos que protegen el cerebro y maduran los pulmones del feto:", subsections: [ { title: "Intervenciones médicas hospitalarias agudas y crónicas", items: ["Medicamentos Tocolíticos (Frenadores de parto): Fármacos agresivos (como nifedipino, indometacina, sulfato de magnesio o terbutalina) administrados por vía oral o intravenosa para relajar el músculo uterino y detener las contracciones temporalmente (generalmente logran ganar de 48 a 72 horas vitales, no detienen el parto para siempre).", "Corticosteroides prenatales (Inyecciones de Betametasona o Dexametasona): La intervención más crucial y salvavidas. Se administran a la madre en dos inyecciones intramusculares separadas por 24 horas para acelerar drásticamente la producción de surfactante en los pulmones inmaduros del bebé, previniendo el letal síndrome de dificultad respiratoria y reduciendo masivamente hemorragias cerebrales y necrosis intestinal al nacer.", "Sulfato de Magnesio neuroprotector: Administrado a la madre por vía intravenosa (goteo continuo) si el parto antes de las 32 semanas se considera inminente e imparable, utilizado exclusivamente para neuroproteger el frágil cerebro del bebé prematuro y reducir el riesgo severo de parálisis cerebral infantil.", "Antibióticos profilácticos intravenosos inmediatos: Administrados para prevenir infecciones mortales en el bebé (sepsis) si la bolsa de agua (fuente) ya se ha roto y hay exposición bacteriana.", "Estrategias de prevención a largo plazo (si se detecta riesgo antes de los síntomas): Para mujeres embarazadas con antecedentes obstétricos de prematuridad o cuello corto en ecografía temprana, se prescriben inyecciones o supositorios diarios de hormona progesterona. Alternativamente, se programa un 'Cerclaje cervical' (cirugía para coser fuertemente el cuello uterino y mantenerlo cerrado mecánicamente) en el primer trimestre."] } ], note: "Si el parto prematuro es activo, imparable o las condiciones de salud materno-fetales son letales, todo intento de frenarlo se suspende y el equipo avanzado de neonatología debe estar presente directamente en el quirófano para recibir, intubar e incubar al bebé en su primer segundo de vida." }, whenToSeekHelp: { title: "¿Cuándo Acudir al Servicio Triage Obstétrico Inmediatamente?", intro: "No dude ni por un segundo y vaya al servicio de urgencias de maternidad en el hospital más cercano al instante si cursa un embarazo menor a 37 semanas y presenta:", items: ["Contracciones abdominales dolorosas o indoloras (vientre duro como una piedra repetidamente) que se dan con una frecuencia de cada 10 a 15 minutos, sin ceder al tomar reposo total", "Escape o un chorro evidente de líquido claro o teñido por la vagina que moja su ropa interior de forma continua, indicando rotura prematura de membranas", "Sangrado vaginal agudo, ya sea de color rojo brillante o de tipo hemorrágico, acompañado de dolor intenso y constante abdominal (signos de desprendimiento prematuro de placenta normoinserta)", "Una sensación de presión pélvica extremadamente severa hacia abajo en la vagina y el ano, o dolor lumbar profundo rítmico similar al de la regla menstrual"] } }, 
'Alcoholismo' : { intro: "El alcoholismo, clínicamente conocido como trastorno por consumo de alcohol, es una enfermedad crónica y progresiva caracterizada por la dependencia física y psicológica al alcohol, afectando gravemente la salud, las relaciones y la vida laboral.", whatIs: { title: "¿Qué es el Alcoholismo?", text: "Es una enfermedad cerebral primaria que altera los circuitos de recompensa, motivación y memoria. Provoca una incapacidad para controlar el consumo de alcohol a pesar de sus consecuencias negativas evidentes y destructivas." }, symptoms: { title: "Síntomas y Señales de Adicción", intro: "Los signos abarcan cambios físicos, psicológicos y conductuales profundos:", groups: [ { name: "Síntomas conductuales", items: ["Fuerte necesidad o ansia incontrolable de beber (craving)", "Incapacidad para limitar la cantidad de alcohol o detenerse una vez que se empieza", "Beber en secreto, esconder alcohol o mentir sobre la cantidad consumida"] }, { name: "Síntomas físicos de dependencia", items: ["Tolerancia: necesidad de beber más para sentir el mismo efecto", "Síndrome de abstinencia: temblores, sudoración, náuseas o ansiedad al intentar dejar de beber", "Beber a primera hora de la mañana para calmar los nervios o la resaca"] } ], warning: "El síndrome de abstinencia severo (Delirium Tremens) puede causar alucinaciones, convulsiones y ser mortal si no recibe tratamiento médico inmediato." }, types: { title: "Niveles de Gravedad", intro: "El trastorno se clasifica según el número de criterios diagnósticos que presenta el paciente:", items: ["Leve: Presencia de 2 a 3 síntomas, a menudo pasando desapercibido socialmente.", "Moderado: Presencia de 4 a 5 síntomas, con un impacto evidente en la vida diaria.", "Grave: Presencia de 6 o más síntomas, indicando una dependencia física y psicológica total que domina la vida del individuo."], note: "El llamado 'alcohólico funcional' sigue estando en grave riesgo de daño orgánico silencioso (como cirrosis) a pesar de mantener su trabajo o vida social." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es una patología multifactorial que no se debe a una simple falta de voluntad:", items: ["Genética: Antecedentes familiares de problemas con el alcohol aumentan drásticamente el riesgo biológico", "Salud mental (Patología dual): Uso del alcohol como automedicación para lidiar con depresión, trauma, trastorno de estrés postraumático (TEPT) o ansiedad", "Factores sociales y ambientales: Presión de grupo, entorno familiar disfuncional o alta disponibilidad desde temprana edad", "Edad de inicio: Comenzar a beber en la adolescencia interfiere con el desarrollo cerebral y multiplica el riesgo de adicción futura"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico lo realizan psiquiatras o médicos especializados mediante:", items: ["Entrevistas clínicas utilizando los criterios estandarizados del manual DSM-5", "Cuestionarios de detección rápida (como el test AUDIT o CAGE) para evaluar el patrón de consumo", "Análisis de sangre para evaluar la función hepática (transaminasas, GGT) y el daño a otros órganos", "Evaluación psicológica completa para identificar trastornos mentales concurrentes"], note: "La negación es un síntoma central de la enfermedad, por lo que a menudo se requiere información de familiares cercanos para un diagnóstico preciso." }, treatment: { title: "Rehabilitación y Tratamiento Integral", intro: "El tratamiento es a largo plazo y requiere un enfoque combinado, ya que la enfermedad es crónica:", subsections: [ { title: "Fases del tratamiento", items: ["Desintoxicación médica supervisada (fase aguda): Uso de medicamentos (como benzodiacepinas) en un entorno clínico para prevenir convulsiones mortales durante la abstinencia", "Programas de rehabilitación (paciente interno o ambulatorio intensivo) con terapia cognitivo-conductual para cambiar patrones de pensamiento y manejo de factores desencadenantes", "Medicamentos anti-craving: Fármacos recetados (como naltrexona, acamprosato o disulfiram) que reducen el deseo de beber o causan reacciones adversas al hacerlo", "Grupos de apoyo mutuo: Asistencia a grupos como Alcohólicos Anónimos (A.A.) o SMART Recovery, vitales para mantener la sobriedad a largo plazo"] } ], note: "Las recaídas son comunes y forman parte del proceso de recuperación; no significan un fracaso, sino una señal para ajustar el plan de tratamiento." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Urgente?", intro: "Debe buscar intervención médica o psiquiátrica inmediata si usted o un ser querido:", items: ["Intenta dejar de beber y experimenta temblores violentos, ritmo cardíaco acelerado, alucinaciones o convulsiones (emergencia médica)", "Sufre vómitos con sangre, dolor abdominal intenso o la piel/ojos se vuelven de color amarillo (ictericia por daño hepático)", "Expresa pensamientos suicidas o de autolesión bajo la influencia del alcohol o durante la abstinencia", "Se da cuenta de que el alcohol está destruyendo su familia, trabajo o salud, pero se siente totalmente incapaz de parar por sí solo"] } },
'Ateroesclerosis' : { intro: "La ateroesclerosis es una enfermedad progresiva en la que se acumula placa (grasa, colesterol y otras sustancias) en las paredes de las arterias, endureciéndolas y estrechándolas.", whatIs: { title: "¿Qué es la Ateroesclerosis?", text: "Es el endurecimiento y estrechamiento de las arterias debido a la acumulación de placa. Limita el flujo de sangre rica en oxígeno a los órganos y otras partes del cuerpo, siendo la causa principal de infartos y derrames cerebrales." }, types: { title: "Clasificación", intro: "Se nombra según la zona afectada:", items: ["Enfermedad coronaria (arterias del corazón)", "Enfermedad carotídea (arterias del cerebro)", "Enfermedad arterial periférica (piernas y brazos)", "Ateroesclerosis renal (riñones)"], note: "Es un proceso sistémico; si hay placas en una zona, suele haber en otras." }, diagnosis: { title: "Diagnóstico", intro: "Evaluación cardiovascular:", items: ["Análisis de sangre (perfil lipídico)", "Electrocardiograma (ECG) y Prueba de esfuerzo", "Ecografía Doppler (para ver el flujo sanguíneo)", "Angiografía (cateterismo para ver bloqueos)"], note: "Suele ser silenciosa y asintomática hasta que ocurre un bloqueo crítico o infarto." }, treatment: { title: "Tratamiento", intro: "Se centra en frenar el avance y evitar coágulos:", subsections: [ { title: "Opciones", items: ["Cambios en el estilo de vida (dieta saludable, ejercicio, dejar de fumar)", "Medicamentos (estatinas para el colesterol, antihipertensivos, aspirina para evitar trombos)", "Procedimientos quirúrgicos (angioplastia con stent, cirugía de bypass)"] } ], note: "La prevención desde la juventud es el tratamiento más eficaz." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia?", intro: "Llama a urgencias si presentas:", items: ["Dolor o presión en el pecho (angina o infarto)", "Dificultad repentina para respirar", "Debilidad, parálisis en un lado de la cara o cuerpo, o dificultad para hablar (derrame cerebral)", "Dolor severo y palidez repentina en una pierna"] } },
'Miocardiopatías' : { intro: "Las miocardiopatías son enfermedades del músculo cardíaco que dificultan que el corazón bombee sangre al resto del cuerpo, pudiendo provocar insuficiencia cardíaca, arritmias o muerte súbita.", whatIs: { title: "¿Qué son las Miocardiopatías?", text: "Son alteraciones en las que el músculo del corazón se vuelve anormalmente grande, grueso, rígido o se reemplaza por tejido cicatricial, debilitando significativamente su capacidad de contracción y bombeo eléctrico." }, types: { title: "Tipos Principales", intro: "Se clasifican según el cambio en el músculo:", items: ["Miocardiopatía dilatada (el ventrículo izquierdo se agranda y debilita; la más común)", "Miocardiopatía hipertrófica (el músculo se engrosa anormalmente, a menudo es genética)", "Miocardiopatía restrictiva (el músculo se vuelve rígido y no se llena de sangre bien)", "Displasia arritmogénica del ventrículo derecho (el músculo se reemplaza por grasa)"], note: "Algunas formas son hereditarias y otras adquiridas por toxinas o infecciones." }, diagnosis: { title: "Evaluación Cardiológica", intro: "Se detectan evaluando la función estructural:", items: ["Ecocardiograma (ultrasonido, la prueba de oro para ver el tamaño y movimiento del corazón)", "Electrocardiograma (ECG) y monitor Holter", "Resonancia Magnética (RM) cardíaca", "Pruebas genéticas y biopsia endomiocárdica (raro)"], note: "Puede ser asintomática en sus etapas iniciales." }, treatment: { title: "Manejo y Soporte", intro: "El objetivo es controlar los síntomas y prevenir el paro cardíaco:", subsections: [ { title: "Intervenciones", items: ["Medicamentos (betabloqueantes, inhibidores de la ECA, diuréticos, antiarrítmicos)", "Dispositivos implantables (marcapasos o Desfibrilador Automático Implantable - DAI)", "Cirugía (miectomía septal para la forma hipertrófica)", "Trasplante de corazón (en casos terminales y refractarios)"] } ], note: "El control estricto de la presión arterial y evitar el alcohol son vitales." }, whenToSeekHelp: { title: "¿Cuándo consultar al cardiólogo?", intro: "Busca ayuda médica inmediata si experimentas:", items: ["Dificultad para respirar grave, incluso en reposo", "Desmayos inexplicables (síncope) o aturdimiento frecuente", "Palpitaciones, latidos cardíacos muy rápidos o irregulares", "Hinchazón severa (edema) en piernas, tobillos o abdomen"] } },
'Prolapso rectal' : { intro: "El prolapso rectal ocurre cuando una parte o la totalidad de la pared del recto (la última sección del intestino grueso) se desliza de su lugar normal y asoma a través de la abertura anal.", whatIs: { title: "¿Qué es el Prolapso Rectal?", text: "Es la protrusión del tejido rectal a través del ano. Suele ocurrir por el debilitamiento crónico de los músculos y ligamentos del suelo pélvico. A menudo causa incontinencia fecal y sensación de bulto, afectando gravemente la calidad de vida." }, types: { title: "Grados de Prolapso", intro: "Se clasifica por su severidad:", items: ["Prolapso mucoso o parcial (solo el revestimiento interno sobresale; común en niños y asociado a hemorroides)", "Prolapso de espesor total (la pared del recto entera sale por el ano; la forma más común)", "Procidencia o prolapso interno (el recto se pliega sobre sí mismo pero no sale por el ano; causa dificultad para evacuar)"], note: "Afecta con mayor frecuencia a mujeres mayores, aunque puede presentarse en ambos sexos a cualquier edad." }, diagnosis: { title: "Diagnóstico Proctológico", intro: "El especialista evaluará la protrusión:", items: ["Examen físico visual y tacto rectal (a menudo pidiendo al paciente que puje o haga fuerza como si fuera al baño)", "Colonoscopia (para descartar pólipos, tumores u otras lesiones)", "Pruebas de fisiología anorrectal (manometría anorrectal y defecografía para evaluar la fuerza del esfínter)"], note: "Es muy importante que el médico diferencie el prolapso de unas hemorroides grandes." }, treatment: { title: "Manejo y Cirugía", intro: "El tratamiento definitivo para adultos es quirúrgico:", subsections: [ { title: "Opciones de Tratamiento", items: ["Tratamiento conservador (dieta rica en fibra, agua y laxantes suaves para evitar el esfuerzo al evacuar; suele ser suficiente en niños)", "Ejercicios de Kegel (para fortalecer el suelo pélvico en fases muy leves)", "Cirugía perineal (se extirpa o fija el recto a través del ano; común en ancianos frágiles)", "Cirugía abdominal o rectopexia (fijación del recto al hueso sacro, a menudo con malla, por laparoscopia; es la más duradera)"] } ], note: "El prolapso rectal en niños pequeños a menudo se resuelve solo tratando el estreñimiento." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Es fundamental buscar evaluación proctológica si:", items: ["Sientes o ves una masa de tejido rojizo que sale del ano tras evacuar", "Sufres de pérdida de control intestinal (incontinencia de gases o heces)", "Tienes sangrado rectal o secreción de moco constante", "El bulto prolapsado no se puede volver a introducir con presión suave (riesgo de estrangulamiento)"] } },
'Adenoma de tiroides' : { intro: "Un adenoma de tiroides es un tumor o crecimiento benigno (no canceroso) que se desarrolla en la glándula tiroides, ubicada en la base del cuello. Son muy comunes y la mayoría no causa problemas.", whatIs: { title: "¿Qué es un Adenoma Tiroideo?", text: "Es un nódulo formado por tejido tiroideo normal que se ha agrupado y encapsulado. Mientras que la mayoría son inactivos (no funcionales), algunos adenomas pueden producir hormonas tiroideas de forma independiente, alterando el equilibrio del cuerpo." }, types: { title: "Tipos por Función", intro: "Se clasifican según su actividad hormonal:", items: ["Adenoma no tóxico o frío (no produce hormonas; es asintomático y suele descubrirse por casualidad)", "Adenoma tóxico o caliente (produce un exceso descontrolado de hormonas tiroideas, provocando hipertiroidismo)", "Adenoma folicular (término patológico, se diferencia del carcinoma folicular solo tras ser extirpado y analizado)"], note: "Los adenomas rara vez se vuelven cancerosos." }, diagnosis: { title: "Evaluación Endocrinológica", intro: "El objetivo principal es asegurar que no sea cáncer:", items: ["Ecografía tiroidea (determina el tamaño, características sólidas o quísticas del nódulo)", "Análisis de sangre (TSH, T3 y T4 para saber si el adenoma es hiperactivo)", "Biopsia por punción y aspiración con aguja fina - PAAF (para analizar las células y descartar malignidad)", "Gammagrafía tiroidea (identifica si es un nódulo 'caliente' que produce hormonas o 'frío')"], note: "" }, treatment: { title: "Vigilancia o Extirpación", intro: "El manejo depende de los síntomas y de si produce hormonas:", subsections: [ { title: "Opciones de Manejo", items: ["Vigilancia activa (ecografías anuales para nódulos inactivos y benignos que no crecen)", "Yodo radiactivo (pastilla que destruye las células del adenoma tóxico para frenar el hipertiroidismo sin cirugía)", "Medicamentos antitiroideos (para controlar los síntomas del hipertiroidismo)", "Cirugía o lobectomía (para extirpar el adenoma si es muy grande, dificulta tragar, es tóxico o hay sospecha de cáncer)"] } ], note: "La ablación por radiofrecuencia es una técnica moderna no quirúrgica para reducir adenomas benignos grandes." }, whenToSeekHelp: { title: "¿Cuándo consultar al especialista?", intro: "Pide cita con el endocrinólogo si:", items: ["Palpas un bulto nuevo o endurecimiento en la base del cuello", "Tienes dificultad para tragar, respirar o sientes cambios en la voz", "Presentas síntomas de hipertiroidismo: pérdida de peso súbita, palpitaciones, nerviosismo, o temblores en las manos"] } },
'Piedras en el riñón' : { intro: "Las piedras en el riñón (litiasis renal) son depósitos duros de minerales y sales que se forman dentro de los riñones. Su paso por las vías urinarias provoca el cólico nefrítico, considerado uno de los dolores más severos en medicina.", whatIs: { title: "¿Qué son las Piedras en el Riñón?", text: "Se forman cuando la orina se concentra demasiado, lo que permite que los minerales cristalicen y se agrupen. Las piedras pequeñas pueden expulsarse sin síntomas, pero las más grandes pueden bloquear el flujo de orina en el uréter, causando inflamación y un dolor atroz." }, types: { title: "Tipos por Composición", intro: "El material de la piedra dicta su prevención:", items: ["Cálculos de calcio (oxalato de calcio; los más comunes, favorecidos por deshidratación y alta sal/proteína)", "Cálculos de ácido úrico (comunes en personas con gota o que comen mucha carne y poco líquido)", "Cálculos de estruvita (aparecen por infecciones urinarias, crecen rápido y pueden ser gigantes)", "Cálculos de cistina (por un trastorno genético raro)"], note: "El factor desencadenante universal es no beber suficiente agua." }, diagnosis: { title: "Diagnóstico Clínico", intro: "En urgencias, se confirma rápidamente para aliviar el dolor:", items: ["Tomografía Computarizada (TC) de abdomen sin contraste (la mejor prueba para ver el tamaño y posición exacta de la piedra)", "Ecografía (muy útil para evitar radiación, especialmente en niños y embarazadas)", "Análisis de orina (para detectar sangre o infección) y de sangre", "Análisis de la piedra expulsada (para conocer su composición)"], note: "" }, treatment: { title: "Expulsión o Extracción", intro: "El manejo depende del tamaño y si causa bloqueo peligroso:", subsections: [ { title: "Opciones de Tratamiento", items: ["Tratamiento expulsivo médico (beber mucha agua, analgésicos fuertes y fármacos relajantes como tamsulosina para piedras < 5mm)", "Litotricia extracorpórea por ondas de choque (pulveriza piedras grandes desde fuera del cuerpo usando ondas sonoras)", "Ureteroscopia (introducir un tubo por la uretra con láser para romper y sacar la piedra sin cortes)", "Nefrolitotomía percutánea (cirugía menor a través de la espalda para cálculos masivos)"] } ], note: "Sin prevención, el 50% de los pacientes desarrollarán otra piedra en 5 años." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "Busca ayuda médica inmediata si experimentas:", items: ["Dolor lumbar o abdominal súbito, tan insoportable que no te deja sentarte ni encontrar una posición de alivio", "Dolor acompañado de náuseas repetidas y vómitos", "Fiebre alta y escalofríos (emergencia vital, indica riñón bloqueado e infectado)", "Sangre roja o marrón en la orina, o incapacidad total para orinar"] } },
'Caspa' : { intro: "La caspa es una afección dermatológica muy común del cuero cabelludo que causa la descamación de la piel, a menudo acompañada de picazón leve. Aunque no es contagiosa ni grave, puede ser vergonzosa y difícil de tratar.", whatIs: { title: "¿Qué es la Caspa?", text: "Es una forma leve de dermatitis seborreica. Ocurre cuando el ciclo de renovación de las células del cuero cabelludo se acelera anormalmente. A menudo está relacionada con una respuesta exagerada al hongo 'Malassezia', que vive naturalmente en la piel y se alimenta de los aceites del cuero cabelludo." }, types: { title: "Causas y Diagnósticos Diferenciales", intro: "La descamación puede tener diferentes orígenes:", items: ["Caspa común / Dermatitis seborreica leve (escamas blancas o amarillas, piel grasosa y enrojecida)", "Piel seca (escamas pequeñas y secas, sin enrojecimiento, común en invierno)", "Dermatitis de contacto alérgica (reacción a champús, tintes o productos para el cabello)", "Psoriasis del cuero cabelludo (placas rojas muy gruesas con escamas plateadas firmemente adheridas)"], note: "El estrés, los climas fríos y los cambios hormonales pueden desencadenar o empeorar los brotes de caspa." }, diagnosis: { title: "Evaluación Dermatológica", intro: "Por lo general, no requiere un diagnóstico médico complejo:", items: ["Examen visual del cuero cabelludo, el cabello y las zonas grasas del rostro (cejas, aletas nasales)", "Si es muy severa, el dermatólogo puede hacer un raspado suave para descartar una infección por hongos (tiña de la cabeza)"], note: "" }, treatment: { title: "Control con Champús Medicados", intro: "No tiene cura definitiva, pero se controla fácilmente con una buena higiene:", subsections: [ { title: "Opciones de Cuidado", items: ["Lavado diario con champú normal (para reducir la grasa en casos leves)", "Champús anticaspa de venta libre (alternando ingredientes activos: Piritionato de zinc, Ketoconazol, Sulfuro de selenio o Alquitrán de hulla)", "Corticosteroides tópicos o champús de receta (recetados por un dermatólogo para reducir inflamación y picazón severa)"] } ], note: "Para que un champú medicado funcione, se debe masajear el cuero cabelludo y dejar actuar la espuma durante al menos 5 minutos antes de enjuagar." }, whenToSeekHelp: { title: "¿Cuándo acudir al dermatólogo?", intro: "Es recomendable buscar ayuda médica si:", items: ["Has usado champús anticaspa comerciales regularmente durante semanas y los síntomas no mejoran", "El cuero cabelludo está muy rojo, hinchado, supurante o doloroso", "La descamación y el enrojecimiento se extienden agresivamente hacia tu frente, orejas, cejas o pecho", "La picazón es tan intensa que te rascas hasta hacerte sangrar o interfiere con tu sueño"] } },
'Angina crónica' : { intro: "La angina crónica, o angina de pecho estable, es un síndrome clínico caracterizado por un dolor, molestia o presión predecible y recurrente en el centro del pecho. Se desencadena típicamente por el esfuerzo físico o el estrés y se alivia con el reposo.", whatIs: { title: "¿Qué es la Angina Crónica?", text: "Es un síntoma directo de la enfermedad de las arterias coronarias. Ocurre cuando las arterias que alimentan el corazón están estrechadas por la acumulación de placa (aterosclerosis). En reposo, el corazón recibe suficiente sangre, pero al hacer esfuerzo, no recibe el oxígeno extra necesario, generando el dolor isquémico." }, types: { title: "Tipos de Angina", intro: "Es vital diferenciarla de cuadros agudos:", items: ["Angina estable crónica (sigue un patrón predecible, dura pocos minutos y cede al descansar o usar nitroglicerina)", "Angina inestable (NO es crónica; aparece en reposo, es impredecible y más intensa, indicando un infarto inminente)", "Angina microvascular (espasmos en los diminutos vasos sanguíneos del corazón, más común en mujeres)", "Angina de Prinzmetal (vasoespasmo coronario que ocurre en reposo, generalmente de noche)"], note: "La angina crónica indica que el riesgo de sufrir un ataque al corazón es elevado." }, diagnosis: { title: "Evaluación Cardiológica", intro: "El objetivo es identificar el nivel de obstrucción arterial:", items: ["Electrocardiograma (ECG) en reposo", "Prueba de esfuerzo (ergometría en cinta o bicicleta para provocar y registrar la isquemia)", "Ecocardiograma o Ecocardiograma de estrés", "Angiografía coronaria (cateterismo, la prueba definitiva para ver visualmente el bloqueo de las arterias)"], note: "" }, treatment: { title: "Manejo Preventivo y Revascularización", intro: "El tratamiento busca evitar el infarto, aliviar el dolor y mejorar la supervivencia:", subsections: [ { title: "Intervenciones", items: ["Medicamentos de rescate (Nitroglicerina sublingual para detener los ataques de dolor inmediatamente)", "Medicamentos preventivos (Betabloqueantes, calcioantagonistas, Aspirina y Estatinas para el colesterol)", "Cambios estrictos de estilo de vida (control de presión/diabetes, dieta sana, ejercicio supervisado y no fumar)", "Procedimientos quirúrgicos (Angioplastia con stent para abrir la arteria o Cirugía de bypass coronario)"] } ], note: "La nitroglicerina dilata los vasos sanguíneos casi instantáneamente; siempre debe llevarse encima." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia (Angina Inestable)?", intro: "La angina estable puede volverse inestable. Llama al 911 si:", items: ["El dolor o presión en el pecho aparece mientras estás en total reposo o durmiendo", "El dolor es mucho más severo, dura más tiempo o es diferente a tus ataques habituales de angina", "El dolor no desaparece después de descansar y usar 3 dosis de tu medicación de nitroglicerina (espaciadas cada 5 min)", "El dolor se irradia a la mandíbula, brazo izquierdo o espalda, junto con sudor frío y náuseas"] } },
'Linfedema' : { intro: "El linfedema es una hinchazón (edema) crónica, anormal y a menudo dolorosa, que ocurre generalmente en uno de los brazos o piernas. Se produce cuando el sistema linfático sufre daños o bloqueos, impidiendo el drenaje adecuado del líquido linfático.", whatIs: { title: "¿Qué es el Linfedema?", text: "Es la acumulación de linfa (un líquido rico en proteínas) en los tejidos blandos. Normalmente, este líquido se filtra a través de los ganglios linfáticos, pero si estos son extirpados o dañados, el líquido se estanca, causando una hinchazón progresiva que endurece la piel (fibrosis)." }, types: { title: "Clasificación por Origen", intro: "Se divide en dos categorías principales:", items: ["Linfedema secundario (la causa abrumadoramente más común; provocado por daño directo a los ganglios linfáticos debido a cirugías oncológicas -como la mastectomía-, tratamientos de radioterapia, infecciones severas o traumatismos)", "Linfedema primario (una condición hereditaria o congénita muy rara en la que los vasos linfáticos se desarrollan de forma anormal, puede aparecer al nacer, en la pubertad o en la adultez)"], note: "Es una complicación muy temida y conocida entre las sobrevivientes de cáncer de mama." }, diagnosis: { title: "Evaluación Vascular y Linfática", intro: "El diagnóstico clínico temprano previene daños irreversibles:", items: ["Examen físico (medición y comparación de la circunferencia de ambas extremidades y evaluación de la textura de la piel, como el 'Signo de Stemmer')", "Ecografía Doppler (para descartar que la hinchazón sea por un coágulo de sangre -Trombosis Venosa Profunda-)", "Linfogammagrafía (se inyecta un tinte radiactivo para escanear y visualizar el flujo y los bloqueos en el sistema linfático)", "Resonancia Magnética (RM) (para confirmar cambios en los tejidos blandos)"], note: "" }, treatment: { title: "Terapia Descongestiva Compleja", intro: "No tiene cura, pero se puede controlar y reducir el volumen significativamente:", subsections: [ { title: "Manejo y Rehabilitación", items: ["Drenaje linfático manual (un masaje especializado, muy suave, que estimula el flujo del líquido hacia vasos sanos)", "Vendajes de compresión multicapa (para exprimir el líquido hacia fuera de la extremidad afectada)", "Prendas de compresión (mangas o medias médicas apretadas para usar a diario y mantener la reducción de volumen)", "Ejercicios terapéuticos descongestivos", "Cirugía avanzada (microcirugía de derivación linfático-venosa o transferencia de ganglios linfáticos en centros especializados)"] } ], note: "Las personas con linfedema deben cuidar su piel obsesivamente (hidratación profunda) para evitar la entrada de bacterias, ya que son muy propensas a infecciones graves." }, whenToSeekHelp: { title: "¿Cuándo acudir a Urgencias o al Especialista?", intro: "Es fundamental la revisión médica inmediata si presentas riesgo de celulitis (infección aguda):", items: ["El brazo o pierna hinchada se vuelve repentinamente muy rojo, caliente al tacto, doloroso o con rayas rojas (infección letal potencial)", "Presentas fiebre alta o escalofríos inexplicables junto con la hinchazón", "Notas una nueva hinchazón en una extremidad, semanas, meses o años después de haber recibido un tratamiento contra el cáncer o cirugía de ganglios"] } },
'Cáncer de vejiga' : { intro: "El cáncer de vejiga es uno de los cánceres urológicos más comunes. Se origina en la vejiga, el órgano hueco y muscular de la pelvis que almacena la orina. Su síntoma principal y más temprano es la aparición de sangre en la orina sin dolor.", whatIs: { title: "¿Qué es el Cáncer de Vejiga?", text: "Comienza con mayor frecuencia en las células uroteliales, que recubren el interior de la vejiga (y de los riñones y uréteres). Suele detectarse en etapas tempranas y superficiales, cuando es altamente tratable. Sin embargo, tiene una tasa de recurrencia sumamente alta, exigiendo un seguimiento de por vida." }, types: { title: "Tipos Celulares y de Invasión", intro: "El pronóstico depende de su nivel de penetración en la pared:", items: ["Carcinoma urotelial o de células transicionales (el tipo más común, casi el 90% de los casos)", "Cáncer superficial o no invasivo (el tumor solo está en la capa interna, no ha tocado el músculo)", "Cáncer músculo-invasivo (agresivo; el tumor ha crecido profundamente hacia la gruesa capa muscular de la vejiga, aumentando el riesgo de metástasis)"], note: "Fumar tabaco es el factor de riesgo absoluto número uno; los fumadores tienen de 3 a 4 veces más probabilidades de contraerlo." }, diagnosis: { title: "Cistoscopia y Patología", intro: "La evaluación urológica es directa y visual:", items: ["Cistoscopia (la prueba principal: el urólogo introduce un tubo delgado con cámara por la uretra para examinar visualmente todo el interior de la vejiga)", "Citología de orina (análisis al microscopio de una muestra de orina para buscar células cancerosas sueltas)", "Biopsia o RTUV (Resección Transuretral) (durante la cistoscopia, se corta el tumor y se envía a patología para confirmar el cáncer y su profundidad)", "Tomografía Computarizada (TC) o Urograma (para evaluar riñones y ver si hay invasión pélvica)"], note: "" }, treatment: { title: "Resección, Inmunoterapia y Cirugía", intro: "El manejo varía drásticamente si el cáncer ha tocado o no el músculo de la vejiga:", subsections: [ { title: "Protocolos Oncológicos", items: ["Cirugía RTUV (Resección Transuretral) (para extirpar tumores superficiales tempranos sin cortes externos)", "Inmunoterapia Intravesical con BCG (se introduce la bacteria debilitada de la tuberculosis directamente dentro de la vejiga para activar el sistema inmunológico y que este mate el cáncer; muy eficaz para evitar recurrencias)", "Cistectomía radical (cirugía mayor para extirpar la vejiga por completo en casos invasivos; se crea una nueva vía, estoma o neovejiga, para que la orina salga del cuerpo)", "Quimioterapia y Radioterapia sistémica (para tumores agresivos o metastásicos)"] } ], note: "Incluso tras un tratamiento exitoso temprano, el paciente debe someterse a cistoscopias cada 3 a 6 meses durante años." }, whenToSeekHelp: { title: "¿Cuándo consultar al urólogo de urgencia?", intro: "El signo de alerta es claro y no debe ignorarse nunca:", items: ["Presencia de sangre visible en la orina (hematuria); puede ser de color rojo brillante, rosado o color cola, y frecuentemente NO duele en absoluto", "Ganas inusualmente frecuentes, urgentes y dolorosas de orinar que no se curan tras un tratamiento con antibióticos (simulando una cistitis resistente)", "Dolor pélvico o dolor de espalda persistente en un solo lado"] } },
'Cáncer de pene' : { intro: "El cáncer de pene es una enfermedad maligna poco frecuente en la que se forman células cancerosas en la piel o en los tejidos internos del pene. Si se detecta y diagnostica de manera temprana, es altamente curable con cirugía conservadora.", whatIs: { title: "¿Qué es el Cáncer de Pene?", text: "La gran mayoría de estos tumores son carcinomas de células escamosas que se originan en la piel y los tejidos húmedos del glande (la cabeza del pene) o bajo el prepucio. Suele comenzar como una lesión indolora que crece muy lentamente y puede propagarse a los ganglios linfáticos de las ingles si se ignora." }, types: { title: "Factores de Riesgo y Subtipos", intro: "Su origen está fuertemente asociado a la higiene y los virus:", items: ["Carcinoma de células escamosas (representa el 95% de los casos)", "Melanoma del pene (un cáncer de piel agresivo muy raro)", "Factores de Riesgo: Infección por el Virus del Papiloma Humano (VPH, presente en más de la mitad de los casos), tabaquismo activo, y falta de higiene crónica bajo el prepucio (esmegma)", "Hombres no circuncidados (la circuncisión infantil elimina casi por completo el riesgo de desarrollar este cáncer)"], note: "El miedo, el tabú y la vergüenza son las principales causas de mortalidad, ya que los hombres ocultan la lesión al médico hasta que es demasiado tarde." }, diagnosis: { title: "Examen Físico y Biopsia", intro: "El diagnóstico urológico es directo y rápido:", items: ["Examen físico del pene y de la ingle (para comprobar si hay llagas, bultos y si los ganglios linfáticos están inflamados o endurecidos)", "Biopsia de la lesión (el urólogo adormece la zona y extrae una pequeña muestra de tejido de la llaga o bulto para confirmación microscópica de cáncer)", "Ecografía, Tomografía Computarizada (TC) o RM (solo utilizadas si se confirma el cáncer, para buscar ganglios invadidos o metástasis pélvicas)"], note: "" }, treatment: { title: "Conservación de Órgano y Oncología", intro: "El objetivo es curar el cáncer preservando la mayor función sexual y urinaria posible:", subsections: [ { title: "Opciones Quirúrgicas y Ablativas", items: ["Cirugía conservadora o Cirugía Micrográfica de Mohs (para tumores superficiales y tempranos, se extirpa solo la capa cancerosa preservando el pene intacto)", "Circuncisión (a menudo el primer paso si el tumor está únicamente en el prepucio)", "Láser, Crioterapia o Quimioterapia Tópica (para lesiones precancerosas o muy incipientes)", "Penectomía parcial o total (amputación quirúrgica de una parte o de todo el pene, necesaria solo en tumores grandes e invasivos profundos que se dejaron avanzar)", "Extirpación de ganglios linfáticos inguinales y Radioterapia (si el cáncer se ha diseminado)"] } ], note: "La detección temprana es vital; la supervivencia a 5 años es superior al 85% si está localizado." }, whenToSeekHelp: { title: "¿Cuándo acudir al urólogo o médico?", intro: "Supera la vergüenza y busca evaluación inmediata si notas en el pene:", items: ["Un área de piel que se vuelve más gruesa o cambia de color (un sarpullido rojo o blanco) que no desaparece", "Un bulto, nódulo, úlcera, ampolla o llaga abierta (con o sin dolor) en el glande o bajo el prepucio que no sana en pocas semanas", "Secreción persistente y maloliente, o sangrado debajo del prepucio", "Hinchazón inexplicable o aparición de bultos duros en la zona de la ingle (ganglios)"] } },
'Fibrosis quística' : { intro: "La fibrosis quística (FQ) es un trastorno genético hereditario, crónico y grave, que causa daños severos en el sistema respiratorio, el sistema digestivo y otros órganos del cuerpo. Aunque la esperanza de vida era corta, los tratamientos modernos permiten que muchos pacientes lleguen a la edad adulta.", whatIs: { title: "¿Qué es la Fibrosis Quística?", text: "Es causada por un gen defectuoso que altera una proteína que regula el movimiento de la sal y el agua en las células. Esta mutación hace que las secreciones mucosas del cuerpo (como el moco, el sudor y los jugos digestivos), que deberían ser fluidas y lubricantes, se vuelvan increíblemente espesas y pegajosas. Estos fluidos taponan conductos y vías respiratorias, convirtiéndose en un foco para infecciones mortales." }, types: { title: "Órganos Impactados", intro: "La enfermedad es multisistémica, atacando dos sistemas vitales:", items: ["Afectación Pulmonar (el moco espeso bloquea los pulmones, provocando infecciones pulmonares bacterianas crónicas, destrucción del tejido y fallo respiratorio eventual)", "Afectación Pancreática y Digestiva (el moco tapona los conductos del páncreas, impidiendo que las enzimas lleguen al intestino; esto causa malabsorción de grasas, desnutrición severa y diabetes relacionada con FQ)", "Afectación reproductiva (casi todos los hombres con FQ son infértiles porque el conducto deferente está ausente o bloqueado)"], note: "Es una enfermedad autosómica recesiva: un niño debe heredar una copia del gen defectuoso de AMBOS padres para tener la enfermedad." }, diagnosis: { title: "Detección Genética y Neonatal", intro: "El diagnóstico suele realizarse en el primer año de vida:", items: ["Prueba de detección del recién nacido (prueba del talón al nacer, busca niveles altos de una enzima específica o el gen mutado)", "Prueba del sudor (la prueba estándar de oro para la FQ; se estimula la sudoración y se mide la cantidad de sal/cloruro, que es anormalmente alta en estos pacientes)", "Pruebas genéticas de ADN (para confirmar las mutaciones exactas del gen CFTR, como la común Delta F508)", "Pruebas de función pulmonar y cultivos de esputo regulares"], note: "" }, treatment: { title: "Moduladores Genéticos y Manejo Diario", intro: "El tratamiento es exhaustivo, intensivo y requiere horas de dedicación diaria:", subsections: [ { title: "Terapias Respiratorias y Digestivas", items: ["Moduladores del CFTR (Trikafta, Orkambi; son fármacos revolucionarios recientes que corrigen el funcionamiento de la proteína defectuosa a nivel celular, mejorando masivamente los síntomas en mutaciones específicas)", "Terapia de limpieza de vías respiratorias y Fisioterapia (uso diario de chalecos vibratorios, percusión en el pecho o técnicas de tos para aflojar y expulsar el moco)", "Antibióticos y mucolíticos inhalados (medicamentos frecuentes para prevenir infecciones crónicas letales)", "Reemplazo de enzimas pancreáticas (pastillas que deben tomarse con cada comida para poder absorber los nutrientes) y vitaminas liposolubles", "Trasplante de pulmón (opción de rescate en fase terminal de falla respiratoria)"] } ], note: "Las personas con FQ no deben acercarse a menos de dos metros entre sí debido al altísimo riesgo de pasarse bacterias resistentes ('regla de los 6 pies')." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra o médico?", intro: "Debes buscar evaluación urgente para tu hijo o bebé si observas:", items: ["Sabor extremadamente salado al besar la piel del bebé (primer síntoma clásico)", "Tos crónica persistente y muy productiva, o episodios de sibilancias repetitivas que imitan al asma grave", "Infecciones pulmonares recurrentes (neumonía o bronquitis frecuente)", "Heces muy voluminosas, pálidas, grasosas y con un olor inusualmente fétido", "Poco o nulo aumento de peso y retraso en el crecimiento, a pesar de tener un buen apetito constante"] } },
'Crup' : { intro: "El crup, conocido clínicamente como laringotraqueobronquitis, es una infección respiratoria infantil muy común y altamente contagiosa. Provoca una inflamación de las vías respiratorias superiores y se caracteriza por una tos muy particular que suena como el ladrido de una foca.", whatIs: { title: "¿Qué es el Crup?", text: "Es generalmente causado por una infección viral (como el virus parainfluenza). El virus inflama y estrecha el espacio de la laringe (caja de la voz) y la tráquea. Dado que las vías respiratorias de los niños pequeños ya son estrechas, esta leve inflamación restringe la entrada de aire, provocando respiración ruidosa y la tos de 'ladrido'." }, types: { title: "Presentaciones Clínicas", intro: "Afecta casi exclusivamente a niños entre 6 meses y 3 años de edad:", items: ["Crup viral agudo (el más común, comienza lentamente con síntomas de un resfriado común, como goteo nasal y fiebre leve, y luego desarrolla la tos perruna)", "Crup espasmódico (aparece de forma repentina en medio de la noche, a menudo sin fiebre ni resfriado previo, y puede estar relacionado con alergias o reflujo; el niño se despierta asustado, tosiendo)"], note: "El sello distintivo del crup es que los síntomas empeoran dramáticamente durante la noche o cuando el niño está llorando/agitado." }, diagnosis: { title: "Evaluación Pediátrica Visual y Auditiva", intro: "El diagnóstico es enteramente clínico y de observación por parte del médico:", items: ["Evaluación del sonido de la tos perruna y de la presencia de 'estridor' (un sonido agudo, áspero y rechinante que el niño hace al tomar aire, indicando que la vía aérea está muy cerrada)", "Examen físico para descartar infecciones más graves y letales (como la epiglotitis, que causa babeo masivo y fiebre alta)", "Rara vez se utiliza una radiografía de cuello, la cual podría mostrar el clásico 'signo del campanario' (un estrechamiento en punta de la tráquea)"], note: "No se requieren análisis de sangre rutinarios." }, treatment: { title: "Corticosteroides y Alivio en el Hogar", intro: "La mayoría de los casos son leves y se pueden manejar exitosamente en casa:", subsections: [ { title: "Opciones de Manejo Clínico y Casero", items: ["Corticosteroides (el tratamiento médico principal de urgencia y pediatría; una sola dosis oral de dexametasona desinflama poderosamente las vías respiratorias y previene complicaciones graves horas después)", "Mantener la calma extrema (el llanto aumenta el requerimiento de oxígeno y cierra más la garganta, empeorando el cuadro asfixiante)", "Aire frío y húmedo (sacar al niño arropado al aire frío de la noche, o dejar que respire el aire frío del congelador, reduce la inflamación laríngea agudamente)", "Epinefrina nebulizada (adrenalina inhalada con máscara en la sala de emergencias; actúa en minutos para abrir vías aéreas críticas y salvar vidas)"] } ], note: "Los medicamentos antitusígenos de farmacia no funcionan en absoluto para el crup." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Llama a emergencias (911) o acude velozmente a un hospital pediátrico si el niño:", items: ["Hace un ruido agudo y ronco (estridor) constante, tanto al tomar aire como al expulsarlo, incluso cuando está en reposo y tranquilo", "Tiene tanta dificultad para respirar que la piel entre sus costillas, sobre su esternón o cuello se hunde profundamente (tiraje)", "Comienza a babear en exceso y parece no poder tragar ni su propia saliva", "Su piel, boca, labios o uñas adquieren una coloración azulada, pálida o grisácea (cianosis por falta de oxígeno)", "Parece extremadamente cansado, aletargado, inquieto por falta de aire o no responde con normalidad"] } },
'Arrancamiento compulsivo del cabello' : { intro: "El arrancamiento compulsivo del cabello, o tricotilomanía, es un trastorno mental que implica un impulso irresistible y recurrente de arrancarse el propio cabello del cuero cabelludo, cejas u otras áreas del cuerpo.", whatIs: { title: "¿Qué es la Tricotilomanía?", text: "Es un trastorno del control de impulsos y obsesivo-compulsivo. A pesar de los intentos de detenerse, la tensión aumenta hasta que la persona se arranca el pelo, lo que le brinda un alivio temporal que suele ir seguido de profunda culpa o vergüenza." }, types: { title: "Tipos de Comportamiento", intro: "El arrancamiento puede ocurrir de dos maneras:", items: ["Automático (sin darse cuenta, a menudo mientras se lee, estudia o ve televisión)", "Consciente o Enfocado (intencionalmente para aliviar tensión emocional o ansiedad)"], note: "Muchas personas presentan ambos tipos de comportamiento." }, diagnosis: { title: "Diagnóstico", intro: "Se diagnostica clínica y psicológicamente:", items: ["Evaluación psiquiátrica de los impulsos y comportamientos", "Examen físico para descartar causas dermatológicas (como alopecia areata o infecciones por hongos)"], note: "El paciente a menudo intenta ocultar la pérdida de cabello con sombreros o maquillaje." }, treatment: { title: "Tratamiento", intro: "El tratamiento principal es psicológico:", subsections: [ { title: "Intervenciones", items: ["Terapia Cognitivo-Conductual (específicamente Entrenamiento de Reversión de Hábitos, para reconocer el impulso y sustituirlo por otra acción)", "Terapia de Aceptación y Compromiso (ACT)", "Medicamentos (antidepresivos ISRS o reguladores del estado de ánimo pueden ayudar en algunos casos)"] } ], note: "El apoyo familiar sin juicios es fundamental para el éxito del tratamiento." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda?", intro: "Acude a un profesional de la salud mental si:", items: ["No puedes dejar de arrancarte el cabello y tienes zonas calvas visibles", "Sientes que el impulso controla tu vida", "Sufres de angustia extrema, aislamiento social o evitas actividades por vergüenza"] } },
'Verrugas del pene' : { intro: "Las verrugas del pene (condiloma acuminado) son crecimientos blandos y carnosos en el pene o la zona genital causados por la infección de transmisión sexual del Virus del Papiloma Humano (VPH).", whatIs: { title: "¿Qué son las Verrugas Genitales?", text: "Es la manifestación clínica de ciertas cepas de bajo riesgo del VPH (típicamente los tipos 6 y 11). Son altamente contagiosas mediante el contacto directo de piel con piel durante las relaciones sexuales." }, types: { title: "Apariencia", intro: "Las lesiones pueden variar visualmente:", items: ["Bultos pequeños, del color de la piel, marrones o rosados", "Agrupaciones que toman la forma de una coliflor", "Lesiones planas muy sutiles en el tallo, el glande, el prepucio o alrededor del ano"], note: "Pueden pasar meses desde la exposición al virus hasta la aparición de las verrugas." }, diagnosis: { title: "Diagnóstico", intro: "El médico o urólogo realiza el diagnóstico principalmente de forma visual:", items: ["Examen físico directo de los genitales", "Aplicación de ácido acético (vinagre) para blanquear lesiones microscópicas", "Biopsia (rara vez, solo si las verrugas son atípicas, sangran o no responden a tratamientos)"], note: "" }, treatment: { title: "Tratamiento y Eliminación", intro: "El virus no tiene cura, pero las verrugas pueden eliminarse:", subsections: [ { title: "Opciones de Tratamiento", items: ["Cremas tópicas recetadas (imiquimod, podofilotoxina aplicadas por el paciente)", "Crioterapia (congelación con nitrógeno líquido en el consultorio)", "Electrocauterización o tratamiento con láser", "Escisión quirúrgica para verrugas muy grandes"] } ], note: "NUNCA utilices tratamientos para verrugas de las manos (venta libre) en los genitales, ya que causan quemaduras severas." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Programa una cita urológica o dermatológica si:", items: ["Aparecen protuberancias nuevas en tus genitales", "Sientes picazón, ardor o presentas sangrado al rozar la zona o tras el sexo", "Tu pareja ha sido diagnosticada con VPH o verrugas genitales"] } },
'Fractura de fémur' : { intro: "Una fractura de fémur es la rotura del hueso del muslo, el hueso más largo, pesado y fuerte del cuerpo humano. Debido a su resistencia, romper un fémur sano requiere un impacto de altísima energía.", whatIs: { title: "¿Qué es una Fractura de Fémur?", text: "Es la pérdida de continuidad ósea en el muslo. En jóvenes, suele ser producto de accidentes automovilísticos o caídas de gran altura. En ancianos, una simple caída desde su propia altura puede romper el cuello del fémur debido a la osteoporosis." }, types: { title: "Tipos de Fracturas", intro: "Se clasifican por la ubicación y el patrón de rotura:", items: ["Fractura proximal o de cadera (cerca de la pelvis, común en ancianos)", "Fractura de la diáfisis femoral (en el eje central del hueso largo)", "Fractura supracondílea o distal (justo por encima de la rodilla)", "Patrón: transversal, oblicua, espiral, conminuta (múltiples fragmentos) o abierta (el hueso perfora la piel)"], note: "Las fracturas abiertas son emergencias extremas por el alto riesgo de infección ósea." }, diagnosis: { title: "Diagnóstico Traumatológico", intro: "Es evidente clínica e imagenológicamente:", items: ["Examen físico (la pierna afectada suele verse más corta y rotada, con dolor intenso y deformidad del muslo)", "Radiografías de rayos X de la pierna completa, cadera y rodilla", "Tomografía Computarizada (TC) (a veces necesaria para planificar la cirugía en fracturas muy astilladas)"], note: "" }, treatment: { title: "Cirugía y Rehabilitación", intro: "La inmensa mayoría de fracturas de fémur requieren operación inmediata:", subsections: [ { title: "Opciones Quirúrgicas", items: ["Clavo intramedular (el estándar de oro: insertar una barra de titanio por el centro del hueso)", "Fijación con placas y tornillos (atornillados por el exterior del hueso)", "Fijador externo (pines fuera de la piel, usado temporalmente en pacientes politraumatizados graves)", "Reemplazo de cadera (si la fractura es en la cabeza del fémur en pacientes mayores)"] } ], note: "La fisioterapia temprana es vital para volver a caminar y evitar la atrofia del músculo cuádriceps." }, whenToSeekHelp: { title: "¿Cuándo llamar a emergencias?", intro: "Un fémur roto es una emergencia. Llama a una ambulancia (no muevas al paciente) si hay:", items: ["Trauma severo seguido de dolor insoportable en el muslo, ingle o rodilla", "Deformidad visible, acortamiento de la pierna o un hueso asomando por la piel", "Incapacidad total para mover la pierna o soportar el mínimo peso"] } },
'Síndrome de resistencia a la insulina' : { intro: "El síndrome de resistencia a la insulina es una alteración metabólica silenciosa en la que las células de los músculos, la grasa y el hígado dejan de responder eficazmente a la insulina, exigiendo al páncreas producir cantidades excesivas para regular la glucosa.", whatIs: { title: "¿Qué es la Resistencia a la Insulina?", text: "La insulina es la llave que permite que la glucosa de la sangre entre a las células para darles energía. Cuando las células se vuelven 'resistentes', el cuerpo necesita producir niveles anormalmente altos de insulina (hiperinsulinemia) para mantener el azúcar normal. A largo plazo, el páncreas se agota, derivando en prediabetes y diabetes tipo 2." }, types: { title: "Fases y Patologías Asociadas", intro: "Es el motor principal de varios problemas de salud:", items: ["Fase compensatoria (la glucosa en sangre es normal, pero los niveles de insulina están disparados; la persona engorda fácilmente)", "Síndrome metabólico (se combina con obesidad abdominal, colesterol alto e hipertensión)", "Asociación directa con el Síndrome de Ovario Poliquístico (SOP) y el Hígado Graso no alcohólico"], note: "Es provocada principalmente por el exceso de grasa visceral (abdominal), el sedentarismo y dietas altas en carbohidratos simples." }, diagnosis: { title: "Detección Temprana y Laboratorio", intro: "Los chequeos metabólicos son la única forma de descubrirlo a tiempo:", items: ["Análisis de sangre de insulina en ayunas y glucosa en ayunas (para calcular el índice HOMA-IR, el marcador más preciso)", "Examen físico buscando acantosis nigricans (manchas oscuras y aterciopeladas en el cuello, axilas o ingles, un signo clásico visible)", "Prueba de tolerancia a la glucosa oral o Hemoglobina A1C"], note: "Un nivel de azúcar en sangre normal no descarta la resistencia a la insulina si la insulina basal está por las nubes." }, treatment: { title: "Reversión mediante Estilo de Vida", intro: "Esta condición es altamente reversible antes de que se convierta en diabetes:", subsections: [ { title: "Intervenciones Metabólicas", items: ["Pérdida de peso enfocada en la grasa abdominal (es la intervención más potente y curativa)", "Ejercicio físico regular (especialmente el entrenamiento de fuerza y pesas, que aumenta la sensibilidad muscular a la insulina instantáneamente)", "Nutrición estricta (reducir drásticamente los azúcares, jugos y carbohidratos refinados, aumentando la fibra y proteínas)", "Medicamentos (como la Metformina, recetada por médicos para ayudar a sensibilizar las células si la dieta no es suficiente)"] } ], note: "El ejercicio hace que el músculo absorba glucosa sin necesitar insulina, aliviando la carga del páncreas." }, whenToSeekHelp: { title: "¿Cuándo solicitar un chequeo endocrinológico?", intro: "No esperes a sentirte mal. Busca una evaluación médica si:", items: ["Tu perímetro abdominal es muy grande (forma de manzana) o has ganado mucho peso que no logras bajar", "Notas el oscurecimiento y engrosamiento de la piel en tu cuello o axilas (Acantosis nigricans)", "Sufres de fatiga extrema y somnolencia abrumadora inmediatamente después de comer", "Tienes antecedentes familiares de diabetes tipo 2 o padeciste diabetes gestacional"] } },
'Acné rosácea' : { intro: "La rosácea (comúnmente mal llamada acné rosácea) es una enfermedad inflamatoria crónica de la piel que afecta principalmente el rostro. Provoca episodios de enrojecimiento intenso, vasos sanguíneos visibles y a menudo pequeños bultos rojos llenos de pus.", whatIs: { title: "¿Qué es la Rosácea?", text: "A diferencia del acné juvenil (que se debe a poros tapados por sebo), la rosácea es un trastorno de hiperreactividad vascular e inflamación profunda de la piel central del rostro (mejillas, nariz, frente). Se exacerba en ciclos de brotes y remisiones por factores externos." }, types: { title: "Subtipos Clínicos", intro: "Se divide en cuatro formas principales que pueden coexistir:", items: ["Eritematotelangiectásica (enrojecimiento persistente y venitas de araña visibles)", "Papulopustulosa (rojez acompañada de granos que parecen acné, muy común en mujeres de mediana edad)", "Fimatosa (la piel se engrosa y se vuelve irregular, comúnmente agrandando la nariz, conocido como rinofima, más frecuente en hombres)", "Ocular (los ojos se vuelven rojos, secos, irritados y los párpados se inflaman)"], note: "Es más frecuente en mujeres de piel clara mayores de 30 años." }, diagnosis: { title: "Diagnóstico Dermatológico", intro: "No existen análisis de sangre para la rosácea:", items: ["El dermatólogo la diagnostica basándose en la inspección visual del rostro y el historial de síntomas", "Ocasionalmente se hacen pruebas para descartar otras enfermedades que causan rojez, como el Lupus o eczemas severos"], note: "Identificar qué desencadena los brotes es parte del proceso diagnóstico personal." }, treatment: { title: "Manejo y Control de Brotes", intro: "No tiene cura, pero se controla con rutinas de piel y medicamentos:", subsections: [ { title: "Tratamientos", items: ["Evitación estricta de desencadenantes (sol, calor, estrés, comidas picantes, alcohol, vino tinto y baños calientes)", "Tratamientos tópicos (geles de metronidazol, ivermectina, ácido azelaico o brimonidina para reducir la rojez)", "Antibióticos orales (como la doxiciclina en dosis bajas para aprovechar su efecto antiinflamatorio, no para matar bacterias)", "Terapia con láser o luz pulsada intensa (IPL) para eliminar los vasos sanguíneos visibles (telangiectasias)", "Cirugía o láser ablativo para remodelar la nariz en casos de rinofima avanzado"] } ], note: "Los limpiadores faciales agresivos, exfoliantes granulados y productos con alcohol empeorarán gravemente la rosácea." }, whenToSeekHelp: { title: "¿Cuándo consultar al dermatólogo?", intro: "Es importante buscar atención médica especializada si:", items: ["Tienes un enrojecimiento constante en el rostro que no se va y te causa incomodidad", "Los granos y espinillas no responden en absoluto a los tratamientos de venta libre para el acné común", "Sientes los ojos constantemente secos, con sensación de arena, o tus párpados están inflamados (rosácea ocular)", "Notas que la piel de tu nariz se está volviendo más gruesa, roja y abultada"] } },
'Pubertad precoz' : { intro: "La pubertad precoz ocurre cuando el cuerpo de un niño comienza a transformarse en el de un adulto (pubertad) demasiado pronto. Se diagnostica cuando estos cambios comienzan antes de los 8 años en las niñas y antes de los 9 años en los niños.", whatIs: { title: "¿Qué es la Pubertad Precoz?", text: "Es el despertar prematuro del eje hormonal. El cerebro comienza a secretar hormonas (GnRH) que estimulan los ovarios o testículos para producir estrógeno o testosterona antes de tiempo. Esto no solo causa cambios físicos y emocionales inmaduros, sino que hace que los huesos crezcan rápido pero se fusionen pronto, dejando al niño con una estatura adulta muy baja." }, types: { title: "Tipos de Pubertad Precoz", intro: "Depende de dónde se origine el problema hormonal:", items: ["Central (la más común; el proceso normal de la pubertad empieza antes de tiempo sin que haya un problema médico subyacente identificable, aunque a veces se debe a tumores cerebrales)", "Periférica (menos común; el cerebro no manda la señal, sino que los estrógenos o testosterona son producidos anormalmente por quistes en los ovarios, tumores testiculares o problemas en las glándulas suprarrenales)"], note: "Es significativamente más frecuente en niñas que en niños." }, diagnosis: { title: "Evaluación Endocrinológica Pediátrica", intro: "El endocrinólogo infantil debe determinar la causa y frenar el proceso:", items: ["Examen físico minucioso del desarrollo sexual", "Radiografía de la mano y la muñeca (para determinar la 'edad ósea'; los huesos crecen demasiado rápido en esta afección)", "Análisis de sangre (para medir los niveles de las hormonas sexuales, tiroideas y de crecimiento)", "Resonancia Magnética (RM) del cerebro (fundamental en niños varones y algunos casos centrales para descartar tumores hipofisarios) o ecografía pélvica/testicular"], note: "" }, treatment: { title: "Frenar el Reloj Biológico", intro: "El tratamiento detiene el desarrollo sexual hasta que el niño alcance la edad apropiada:", subsections: [ { title: "Intervenciones Médicas", items: ["Terapia con análogos de la GnRH (el tratamiento estándar para la central: se aplican inyecciones mensuales o implantes que bloquean la producción de hormonas y 'pausan' la pubertad; los efectos son reversibles al dejar la medicación)", "Tratamiento de afecciones subyacentes (cirugía si la causa es un tumor ovárico, testicular o cerebral que produce hormonas)", "Apoyo psicológico (esencial para el niño, que puede sentirse confundido y diferente a sus compañeros)"] } ], note: "Si no se trata, el niño será el más alto de su clase inicialmente, pero al dejar de crecer temprano, terminará siendo un adulto de muy baja estatura." }, whenToSeekHelp: { title: "¿Cuándo llevar al niño al pediatra?", intro: "Es motivo de consulta endocrinológica urgente si notas signos de maduración antes de los 8 años (niñas) o 9 años (niños):", items: ["Desarrollo del botón mamario o primera menstruación en niñas pequeñas", "Crecimiento anormal de los testículos y el pene, o cambio de voz en niños", "Aparición de vello púbico o en las axilas, acompañado de olor corporal (sudor) tipo adulto", "Un 'estirón' de crecimiento físico de altura repentino y extremadamente rápido"] } },
'Retraso en el desarrollo psicomotor' : { intro: "El retraso en el desarrollo psicomotor (RDP) es un diagnóstico clínico utilizado cuando un bebé o un niño pequeño no alcanza los hitos del desarrollo motor, cognitivo, del lenguaje o social en el tiempo o la secuencia esperada para su edad cronológica.", whatIs: { title: "¿Qué es el Retraso Psicomotor?", text: "Es un signo de alerta que indica que el sistema nervioso central (cerebro y médula espinal) no está madurando al ritmo normal. No es una enfermedad en sí, sino un síntoma que requiere investigación. Puede ser global (afecta todas las áreas) o aislado (solo motricidad o solo lenguaje)." }, types: { title: "Áreas de Afectación", intro: "El retraso puede observarse en una o varias esferas:", items: ["Motricidad gruesa (controlar la cabeza, sentarse, gatear, caminar)", "Motricidad fina (agarrar objetos pequeños, manipular, dibujar)", "Área de Lenguaje y comunicación (balbucear, primeras palabras, comprensión)", "Área social y conductual (contacto visual, respuesta a la sonrisa, juego)"], note: "Un retraso global (dos o más áreas) a menudo señala condiciones genéticas o neurológicas más serias." }, diagnosis: { title: "Evaluación Pediátrica y Neurológica", intro: "La intervención temprana depende de un diagnóstico preciso:", items: ["Monitoreo continuo de hitos en las visitas de niño sano", "Pruebas de tamizaje estandarizadas del desarrollo (escalas de Denver, Haizea-Llevant)", "Evaluación por un neuropediatra (si el retraso es severo o global)", "Pruebas genéticas, metabólicas, de audición y visuales (para descartar síndromes de fondo, sordera o ceguera)", "Resonancia Magnética cerebral (para buscar lesiones cerebrales o malformaciones)"], note: "El concepto de 'ya hablará o ya caminará, hay que darle tiempo' sin evaluación médica es un error grave." }, treatment: { title: "Estimulación e Intervención Temprana", intro: "El cerebro infantil es altamente plástico (moldeable); la terapia intensiva temprana es vital:", subsections: [ { title: "Terapias de Apoyo", items: ["Fisioterapia pediátrica (para mejorar la fuerza muscular, el equilibrio y la motricidad gruesa)", "Terapia ocupacional (para mejorar la motricidad fina y la integración sensorial)", "Fonoaudiología o terapia de lenguaje", "Programas de estimulación temprana integral", "Tratamiento médico específico si se encuentra una causa subyacente (ej. hipotiroidismo congénito)"] } ], note: "La participación constante de los padres aplicando los ejercicios terapéuticos en casa diariamente es el factor más decisivo en la mejoría." }, whenToSeekHelp: { title: "¿Cuándo saltan las alarmas pediátricas?", intro: "Acude a tu pediatra para una evaluación especializada si tu bebé:", items: ["A los 4 meses: No sostiene la cabeza con firmeza, o no sonríe a las personas", "A los 9 meses: No puede sentarse sin ayuda o no balbucea", "A los 12 meses: No se pone de pie apoyándose en muebles, no señala cosas", "A los 18 meses: No camina de forma independiente o no dice palabras sueltas", "A CUALQUIER EDAD: Si el niño PIERDE una habilidad que ya había logrado (ej. dejó de hablar o de caminar)"] } },
'Infección urinaria recurrente' : { intro: "Una infección urinaria recurrente (ITU recurrente) se define médicamente como la aparición de dos o más infecciones de la vejiga (cistitis) o del tracto urinario en un periodo de seis meses, o tres o más infecciones confirmadas en un año.", whatIs: { title: "¿Qué son las ITU Recurrentes?", text: "Son reinfecciones persistentes del sistema urinario por bacterias. En la mayoría de las mujeres, cada episodio es una nueva infección por bacterias del intestino (como E. coli) que suben por la uretra. En algunos casos, puede ser la misma bacteria original que nunca fue completamente erradicada o que formó biopelículas defensivas en la vejiga." }, types: { title: "Clasificación de la Recurrencia", intro: "El médico las distingue para orientar el tratamiento:", items: ["Reinfección (una bacteria completamente nueva causa la nueva infección; representa el 80% de los casos)", "Recaída (la misma cepa bacteriana sobrevive al antibiótico inicial y reaparece poco después de terminar el tratamiento; sugiere problemas renales o de próstata)", "ITU no complicada recurrente (en mujeres jóvenes y sanas con anatomía normal)", "ITU complicada (asociada a cálculos renales, sondas, diabetes, inmunosupresión o anomalías en las vías urinarias)"], note: "Las relaciones sexuales son el desencadenante más común de reinfecciones en mujeres jóvenes." }, diagnosis: { title: "Evaluación Urológica Avanzada", intro: "Un cuadro repetitivo requiere investigar anomalías ocultas:", items: ["Urocultivos de orina seriados (es obligatorio cultivar la orina para confirmar que es realmente una infección y no otra enfermedad como cistitis intersticial, e identificar a qué antibiótico es sensible la bacteria)", "Ecografía renal y de vías urinarias (para descartar piedras en los riñones o vejigas que no se vacían bien)", "Cistoscopia (inserción de un tubo con cámara en la vejiga para descartar tumores, pólipos o inflamación crónica)", "Medición del volumen residual posmiccional"], note: "" }, treatment: { title: "Prevención Profiláctica y Hábitos", intro: "El objetivo es romper el ciclo de infecciones continuas:", subsections: [ { title: "Estrategias de Manejo", items: ["Profilaxis antibiótica poscoital (tomar una sola pastilla de antibiótico inmediatamente después de tener relaciones sexuales)", "Profilaxis antibiótica continua a dosis bajas (tomar una minidosis diaria de antibiótico durante 6 a 12 meses para mantener la orina estéril)", "Terapia con estrógenos vaginales tópicos (en mujeres posmenopáusicas, reconstruye el tejido urogenital haciéndolo resistente a bacterias)", "Aumento masivo de la ingesta de agua (orinar frecuentemente 'lava' las bacterias) y suplementos de extracto de arándano rojo o D-manosa"] } ], note: "Orinar inmediatamente después del coito es la medida mecánica preventiva más importante en mujeres." }, whenToSeekHelp: { title: "¿Cuándo derivar a un Urólogo?", intro: "No te acostumbres a vivir con infecciones. Busca a un especialista si:", items: ["Sufres más de tres infecciones urinarias confirmadas con laboratorio en un año", "El dolor y ardor pélvico persiste incluso después de terminar los antibióticos recetados y con cultivos de orina negativos", "Los episodios se acompañan de dolor lumbar fuerte, fiebre alta o sangre franca en la orina", "Eres un hombre y tienes una infección urinaria (en hombres casi siempre es complicada o ligada a la próstata)"] } },
'Accidente cerebrovascular hemorrágico' : { intro: "Un accidente cerebrovascular (ACV) hemorrágico, también conocido como derrame cerebral hemorrágico, es una emergencia médica catastrófica que ocurre cuando un vaso sanguíneo debilitado en el cerebro se rompe, filtrando sangre a alta presión en el tejido cerebral circundante.", whatIs: { title: "¿Qué es un ACV Hemorrágico?", text: "A diferencia del ACV isquémico (causado por un coágulo), el hemorrágico es un estallido vascular. La sangre derramada forma una masa que irrita y comprime físicamente el tejido cerebral blando (aumentando la presión intracraneal), destruyendo las neuronas. Aunque representan solo el 15% de los derrames cerebrales, son responsables de un porcentaje desproporcionado de las muertes." }, types: { title: "Tipos de Hemorragia", intro: "Se clasifican por la ubicación exacta de la rotura dentro de la cabeza:", items: ["Hemorragia intracerebral (el vaso estalla directamente dentro del tejido cerebral profundo; casi siempre es consecuencia de años de hipertensión arterial mal controlada que debilita las arterias)", "Hemorragia subaracnoidea (el sangrado ocurre en el espacio entre el cerebro y la membrana que lo recubre; suele ser causado por la ruptura de un aneurisma cerebral o una malformación arteriovenosa)"], note: "El uso de drogas ilícitas como la cocaína o las anfetaminas puede provocar picos de presión arterial que rompan vasos sanguíneos en personas jóvenes." }, diagnosis: { title: "Escáneres Críticos en Urgencias", intro: "El diagnóstico de emergencia debe realizarse en minutos para decidir el tratamiento:", items: ["Tomografía Computarizada (TC) de cráneo sin contraste (la prueba de imagen primordial y más rápida para visualizar inmediatamente la sangre fresca brillante acumulada en el cerebro)", "Angiografía por TC o por Resonancia Magnética (para mapear los vasos sanguíneos y encontrar el punto exacto de la rotura, el aneurisma o la malformación vascular)", "Punción lumbar (se realiza ocasionalmente en sospechas de hemorragia subaracnoidea si la TC inicial parece normal pero los síntomas son claros)"], note: "Nunca se administran medicamentos 'destructores de coágulos' (tPA) en este tipo de derrame, ya que empeorarían el sangrado fatalmente." }, treatment: { title: "Estabilización y Cirugía Neurológica", intro: "El tratamiento inmediato se enfoca en controlar el sangrado, reducir la presión en el cerebro y prevenir otro estallido:", subsections: [ { title: "Intervenciones de Rescate", items: ["Control médico agresivo e instantáneo de la presión arterial (mediante fármacos intravenosos para evitar que el vaso siga bombeando sangre al hematoma)", "Reversión inmediata de medicamentos anticoagulantes (si el paciente los tomaba, mediante antídotos o plasma fresco)", "Cirugía endovascular (embolización con espirales de platino guiadas por catéter para sellar el aneurisma roto desde adentro)", "Craneotomía quirúrgica (abrir el cráneo para clipear quirúrgicamente el vaso roto, drenar el charco de sangre masivo y aliviar la presión letal sobre el tallo cerebral)"] } ], note: "La supervivencia y la recuperación dependen drásticamente del tamaño de la hemorragia y de la rapidez de la intervención." }, whenToSeekHelp: { title: "¿Cuándo activar el código Ictus (Llamar al 911)?", intro: "El derrame hemorrágico golpea de golpe y con una severidad extrema. Busca una ambulancia al instante ante:", items: ["La aparición súbita del 'peor dolor de cabeza de tu vida', a menudo descrito como un estallido o trueno en la cabeza", "Náuseas violentas, vómitos, rigidez en el cuello o pérdida repentina y prolongada de la conciencia", "Parálisis inmediata, caída o entumecimiento total de un lado del rostro, un brazo o una pierna", "Dificultad súbita e incapacitante para hablar (balbuceo), articular palabras o entender lo que otros dicen"] } },
'Diplopía (visión doble)' : { intro: "La diplopía, conocida comúnmente como visión doble, es la percepción simultánea de dos imágenes de un solo objeto. Puede ser un problema oftalmológico menor relacionado con la lente del ojo, o un síntoma de alarma neurológica grave.", whatIs: { title: "¿Qué es la Diplopía?", text: "Es un fallo en la coordinación visual. Normalmente, los ojos apuntan con precisión al mismo objetivo y el cerebro fusiona ambas imágenes en una sola imagen 3D. Si los ojos están desalineados por un problema muscular o nervioso, o si hay un defecto en la superficie de un ojo, el cerebro ve dos imágenes desplazadas (horizontal, vertical o diagonalmente)." }, types: { title: "Diferenciación Clínica Fundamental", intro: "El tipo de diplopía es la clave absoluta para el diagnóstico:", items: ["Diplopía Monocular (si tapas un ojo y ves normal, pero tapas el otro y el ojo descubierto SIGUE viendo doble. Esto siempre es un problema físico del ojo mismo, como astigmatismo, cataratas o sequedad extrema, y no es una emergencia neurológica)", "Diplopía Binocular (ves doble con ambos ojos abiertos, pero la visión doble DESAPARECE por completo al tapar cualquiera de los dos ojos. Significa que los ojos están desalineados, lo que indica un problema en los músculos oculares, los nervios craneales que los controlan, o en el cerebro)"], note: "La diplopía binocular de aparición repentina es una emergencia médica." }, diagnosis: { title: "Evaluación Neurológica y Oftalmológica", intro: "El especialista evaluará inmediatamente el origen del defecto de alineación:", items: ["Examen oftalmológico completo (para descartar problemas corneales o de cataratas en la monocular)", "Evaluación de la motilidad ocular y de los nervios craneales (el médico pedirá que sigas un objeto con los ojos para identificar qué músculo o nervio específico está paralizado)", "Resonancia Magnética (RM) del cerebro o Tomografía Computarizada (obligatorias en diplopía binocular nueva para descartar tumores cerebrales, aneurismas, accidente cerebrovascular o esclerosis múltiple)", "Análisis de sangre (para descartar Miastenia Gravis o enfermedad tiroidea ocular -Enfermedad de Graves-)"], note: "" }, treatment: { title: "Corrección Oftálmica o Neurológica", intro: "El tratamiento depende estrictamente de curar la causa que produce la visión doble:", subsections: [ { title: "Opciones de Manejo", items: ["Uso temporal de un parche ocular (solo para aliviar el síntoma molesto de la visión doble mientras se investiga la causa)", "Lentes con prismas (anteojos especiales que doblan la luz para que las dos imágenes coincidan y se fusionen en una, ideal para desalineaciones leves o crónicas)", "Cirugía de los músculos extraoculares (para corregir el estrabismo estructural realineando los ojos físicamente)", "Tratamiento de la causa subyacente (cirugía de cataratas, esteroides para problemas de tiroides o atención de emergencia por derrame cerebral)"] } ], note: "El cerebro de un niño suprime rápidamente la visión doble apagando el ojo afectado (ojo vago); el cerebro adulto no puede hacerlo, por eso resulta tan perturbador." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia hospitalaria?", intro: "Acude INMEDIATAMENTE a urgencias si la visión doble (diplopía binocular) aparece de forma súbita, especialmente si se acompaña de:", items: ["Dolor de cabeza severo, confusión o un traumatismo craneal reciente", "Párpado caído (ptosis), pupila dilatada anormalmente, o dolor al mover el ojo", "Debilidad, entumecimiento en un lado del cuerpo, o dificultad repentina para hablar, sonreír o tragar (banderas rojas clásicas de un derrame cerebral o aneurisma)"] } },
'Hematoma epidural' : { intro: "Un hematoma epidural es una acumulación peligrosa y letal de sangre entre el hueso del cráneo y la duramadre (la capa exterior resistente que protege el cerebro). Suele ser consecuencia directa de un traumatismo craneal por un accidente grave o un golpe fuerte en la sien.", whatIs: { title: "¿Qué es un Hematoma Epidural?", text: "Es una hemorragia intracraneal de urgencia. A menudo ocurre porque el golpe fractura el cráneo (típicamente el hueso temporal) y desgarra la arteria meníngea media. La sangre arterial se bombea a alta presión hacia ese pequeño espacio cerrado, creando un coágulo masivo que empuja, aplasta y desplaza rápidamente el tejido cerebral blando." }, types: { title: "Presentación Clínica y Evolución", intro: "Su progresión es aguda, rápida y engañosa:", items: ["Patrón clásico del 'Intervalo Lúcido' (ocurre en muchos pacientes: tras el golpe, la persona queda inconsciente brevemente, despierta, parece actuar y hablar con total normalidad durante unas horas (el intervalo lúcido), hasta que el hematoma crece tanto que el paciente entra en un estado de coma rápido y profundo)", "Agudo (el desarrollo de síntomas severos ocurre en minutos u horas después de la lesión craneal)", "Herniación cerebral (si no se drena, la sangre empuja el cerebro hacia la base del cráneo, comprimiendo el tronco encefálico y causando la muerte o muerte cerebral irreversible)"], note: "Esta lesión es predominantemente arterial (alta presión), a diferencia del hematoma subdural, que es venoso (baja presión y más lento)." }, diagnosis: { title: "Escáneres Cerebrales de Emergencia", intro: "El diagnóstico debe realizarse en minutos para salvar la vida del paciente:", items: ["Tomografía Computarizada (TC) de cabeza de emergencia sin contraste (el estudio definitivo y más rápido; revelará clásicamente una mancha blanca, densa y en forma de lente biconvexa (forma de limón) empujando el cerebro y desviando su línea media)", "Examen neurológico continuo y urgente (evaluación de la Escala de Coma de Glasgow y revisión estricta de las pupilas, ya que una pupila agrandada y fija es signo inminente de compresión cerebral grave)"], note: "No hay tiempo para Resonancias Magnéticas en casos agudos." }, treatment: { title: "Cirugía Descompresiva de Salvamento", intro: "El hematoma epidural agudo sintomático es una de las mayores emergencias neuroquirúrgicas; requiere abrir la cabeza para salvar el cerebro:", subsections: [ { title: "Procedimientos Quirúrgicos", items: ["Craneotomía de emergencia (el neurocirujano retira una sección del cráneo para exponer el hematoma, succionar el coágulo masivo de sangre, lavar el área, encontrar la arteria desgarrada que está sangrando y cauterizarla o ligarla para detener la hemorragia)", "Trepanación (en situaciones extremas, hacer un agujero (trépano) rápido en el cráneo para liberar la presión a chorro inmediatamente antes de la cirugía mayor)", "Intubación y medicamentos (diuréticos osmóticos) para manejar la presión en el cerebro antes de la cirugía", "Observación estricta en UCI para pequeños hematomas asintomáticos"] } ], note: "Si el paciente es operado rápidamente antes de entrar en coma profundo, el pronóstico neurológico suele ser excelente." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA VITAL?", intro: "Cualquier golpe fuerte en la cabeza requiere evaluación. Llama a la ambulancia inmediatamente si la persona:", items: ["Sufrió un trauma, perdió el conocimiento, se despertó y pareció estar bien, pero horas después comienza a estar sumamente letárgica, confundida o a vomitar explosivamente", "Presenta dolor de cabeza de intensidad creciente, agudo e intolerable", "Muestra debilidad progresiva en un lado del cuerpo, dificultad para hablar o entra en estado de coma", "Tiene una pupila de un ojo visiblemente mucho más grande y dilatada que la del otro (signo de que el cerebro se está aplastando)"] } },
'Miedos y fobias' : { intro: "Una fobia específica es un trastorno de ansiedad intenso y abrumador caracterizado por un miedo irracional, desproporcionado y persistente hacia un objeto, situación, actividad o animal específico que en realidad representa poco o ningún peligro real.", whatIs: { title: "¿Qué son las Fobias?", text: "A diferencia del miedo normal y preventivo, una fobia es paralizante. La persona que la sufre experimenta una ansiedad tan extrema que puede desencadenar un ataque de pánico completo. El individuo organiza su vida y altera drásticamente sus rutinas diarias con el único objetivo de evitar a toda costa el contacto con el desencadenante." }, types: { title: "Categorías de Fobias", intro: "Existen cientos de fobias, pero se agrupan clínicamente en categorías:", items: ["Fobias a los animales (zoofobia, aracnofobia -arañas-, cinofobia -perros-, ofidiofobia -serpientes-)", "Fobias al entorno natural (acrofobia -alturas-, astrafobia -tormentas-, hidrofobia -agua profunda-)", "Fobias situacionales (claustrofobia -espacios cerrados o ascensores-, aerofobia -volar en aviones-)", "Fobia a la sangre/inyecciones/daño (hemofobia o tripanofobia, que a diferencia de otras, a menudo provoca una caída brusca de la presión arterial y desmayos reales)", "Agorafobia (el miedo complejo a estar en lugares abiertos o multitudes donde escapar sería difícil)"], note: "La persona suele ser plenamente consciente de que su miedo es ilógico e irracional, pero se siente incapaz de controlarlo físicamente." }, diagnosis: { title: "Evaluación Psicológica", intro: "Se diagnostica en consulta mediante los criterios manuales (DSM-5):", items: ["Entrevista clínica y psicológica profunda para evaluar la intensidad, duración y origen del miedo", "Criterios diagnósticos clave (el miedo es casi inmediato al ver el objeto, la persona lo evita activamente, el miedo dura 6 meses o más, y causa un deterioro o disfunción significativa en el trabajo, estudios o vida personal)"], note: "" }, treatment: { title: "Terapia de Exposición y Reacondicionamiento", intro: "Las fobias específicas tienen una de las tasas de éxito de tratamiento más altas de la psicología:", subsections: [ { title: "Enfoques Terapéuticos", items: ["Terapia de Exposición / Desensibilización sistemática (el estándar de oro curativo absoluto; el psicólogo expone al paciente al objeto temido de forma gradual, progresiva y en un entorno seguro, hasta que el cerebro 'aprende' que no hay peligro real y la ansiedad se extingue)", "Terapia Cognitivo-Conductual (TCC) (para desafiar las creencias catastróficas y aprender técnicas de relajación)", "Terapia de exposición mediante Realidad Virtual (RV) (especialmente útil para el miedo a volar o a las alturas)", "Medicamentos a corto plazo (ansiolíticos como benzodiacepinas o betabloqueantes recetados ocasionalmente solo para suprimir el pánico físico inmediato antes de enfrentar un vuelo en avión necesario, no curan la fobia)"] } ], note: "Huir o evitar constantemente el objeto temido solo refuerza e incrementa el poder de la fobia en el cerebro." }, whenToSeekHelp: { title: "¿Cuándo solicitar apoyo profesional?", intro: "Debes buscar ayuda psicológica terapéutica si:", items: ["El miedo irracional paraliza tu capacidad para desenvolverte en el trabajo, viajar o disfrutar de tu vida familiar y social", "Te está impidiendo buscar atención médica necesaria (como no ir al dentista o no vacunarte debido a una fobia severa a las agujas)", "Experimentas ataques de pánico violentos con palpitaciones, asfixia o sudoración extrema cuando te enfrentas (o incluso solo al pensar) en el desencadenante"] } },
'Comunicación interauricular' : { intro: "La comunicación interauricular (CIA) es un defecto de nacimiento caracterizado por un orificio en la pared (tabique) que separa las dos cavidades superiores del corazón (aurículas).", whatIs: { title: "¿Qué es la Comunicación Interauricular?", text: "Es una cardiopatía congénita que permite que la sangre recién oxigenada fluya desde la aurícula izquierda a la derecha, mezclándose con la sangre pobre en oxígeno. Los orificios pequeños suelen cerrarse solos en la niñez, pero los grandes pueden requerir cirugía." }, symptoms: { title: "Síntomas", intro: "Muchos bebés nacen sin síntomas, pero en casos de orificios grandes pueden presentar:", groups: [ { name: "Signos Comunes", items: ["Dificultad para respirar, especialmente al hacer ejercicio", "Fatiga rápida y sudoración al comer (en bebés)", "Infecciones pulmonares frecuentes", "Soplo cardíaco (un sonido sibilante en el corazón)"] } ], warning: "A largo plazo, un defecto no tratado puede causar insuficiencia cardíaca derecha, arritmias o hipertensión pulmonar." }, types: { title: "Tipos de CIA", intro: "Se clasifican según la ubicación del orificio en el tabique:", items: ["Ostium secundum (la más común, en el medio del tabique)", "Ostium primum (en la parte inferior del tabique, frecuentemente asociada a problemas de válvulas)", "Seno venoso (en la parte superior)"], note: "" }, diagnosis: { title: "Diagnóstico", intro: "Se detecta mediante auscultación y se confirma con imagenología:", items: ["Ecocardiograma (la prueba principal, utiliza ondas sonoras para crear imágenes del corazón)", "Electrocardiograma (ECG)", "Radiografía de tórax"], note: "" }, treatment: { title: "Tratamiento", intro: "Depende del tamaño del orificio y la edad del paciente:", subsections: [ { title: "Opciones de Cierre", items: ["Observación médica y ecocardiogramas periódicos en niños pequeños", "Cierre por cateterismo (se inserta un parche o tapón mediante un tubo desde la ingle hasta el corazón)", "Cirugía a corazón abierto (para cerrar el agujero con suturas o parches en casos de anatomía compleja)"] } ], note: "La mayoría de los procedimientos tienen una altísima tasa de éxito a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Consulta a un cardiólogo o pediatra si notas:", items: ["Dificultad evidente para respirar o cansancio extremo sin motivo", "Latidos cardíacos muy rápidos, salteados o fuertes (palpitaciones)", "Coloración azulada en la piel (cianosis), indicando un flujo de oxígeno muy deficiente"] } },
'Cáncer endometrial' : { intro: "El cáncer endometrial es un tipo de cáncer que comienza en el útero, específicamente en la capa de células que forman su revestimiento interior (el endometrio). Es el cáncer ginecológico más frecuente.", whatIs: { title: "¿Qué es el Cáncer Endometrial?", text: "Es el crecimiento maligno y descontrolado de las células del endometrio. Afortunadamente, a menudo se detecta en etapas tempranas porque produce sangrado vaginal anormal, lo que alerta a las pacientes a buscar atención médica de forma oportuna." }, symptoms: { title: "Síntomas Clave", intro: "El signo más revelador y temprano es el sangrado inusual:", groups: [ { name: "Señales Físicas", items: ["Sangrado vaginal, goteo o manchado después de la menopausia", "Sangrado entre períodos menstruales (en mujeres premenopáusicas)", "Dolor pélvico persistente o dolor durante el coito", "Flujo vaginal anormal, acuoso o teñido de sangre y a veces maloliente"] } ], warning: "Cualquier sangrado vaginal que ocurra en una mujer posmenopáusica nunca es normal y debe ser evaluado de inmediato por un especialista." }, types: { title: "Tipos Celulares", intro: "Se clasifica clínicamente por su agresividad y dependencia hormonal:", items: ["Tipo 1 (Endometrioide, representa la mayoría de los casos; crece lentamente y a menudo su crecimiento es estimulado por un exceso de estrógeno)", "Tipo 2 (No endometrioide, como el seroso o de células claras; es menos común pero mucho más agresivo, crece rápido y no depende del estrógeno)"], note: "Si se detecta de manera temprana, extirpar el útero quirúrgicamente a menudo cura el cáncer endometrial tipo 1." }, diagnosis: { title: "Detección y Confirmación", intro: "El ginecólogo no puede detectarlo con un Papanicolaou normal; requerirá:", items: ["Ecografía transvaginal (para medir el grosor del endometrio y ver anomalías estructurales)", "Histeroscopia (el médico inserta un tubo muy delgado con una cámara por la vagina para observar directamente el interior del útero)", "Biopsia endometrial (la extracción de una muestra de tejido del útero en el consultorio, siendo esta la prueba definitiva para confirmar el cáncer)"], note: "" }, treatment: { title: "Opciones Oncológicas", intro: "La cirugía es el pilar y el tratamiento principal:", subsections: [ { title: "Terapias Quirúrgicas y Adyuvantes", items: ["Histerectomía total (cirugía para extirpar el útero y el cuello uterino, a menudo retirando también ovarios y trompas de Falopio - salpingooforectomía bilateral)", "Radioterapia (para destruir cualquier célula cancerosa restante en la pelvis, reduciendo el riesgo de recaída)", "Terapia hormonal (como altas dosis de progestina para bloquear el crecimiento celular en tumores sensibles a hormonas)", "Quimioterapia (usada generalmente para estadios avanzados o cánceres de Tipo 2)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo solicitar revisión ginecológica?", intro: "Busca consulta de manera urgente si:", items: ["Experimentas cualquier tipo de sangrado, manchado o flujo teñido de sangre después de haber entrado en la menopausia", "Tus menstruaciones se vuelven repentinamente muy abundantes o sangras abundantemente entre periodos regulares", "Sufres de dolor pélvico o presión en el bajo vientre de nueva aparición que no desaparece"] } },
'Delirium' : { intro: "El delirium, o síndrome confusional agudo, es un cambio grave, rápido y fluctuante en el estado mental de una persona. Causa confusión profunda, desorientación espacial y temporal, y una incapacidad severa para pensar o recordar con claridad.", whatIs: { title: "¿Qué es el Delirium?", text: "Es una alteración aguda del cerebro. A diferencia de la demencia (que es crónica y progresiva), el delirium aparece de golpe (en horas o días) y suele ser un síntoma de un problema médico grave subyacente, como una infección, un desequilibrio químico o la toxicidad de medicamentos. Es altamente reversible si se trata la causa raíz." }, types: { title: "Tipos de Presentación", intro: "Los pacientes pueden mostrar comportamientos opuestos:", items: ["Delirium hiperactivo (el paciente está agitado, inquieto, con cambios rápidos de humor, y puede tener alucinaciones o delirios)", "Delirium hipoactivo (el paciente está inusualmente somnoliento, retraído, lento para responder o letárgico; este tipo a menudo pasa desapercibido)", "Delirium mixto (los síntomas fluctúan entre la hiperactividad agitada y la hipoactividad letárgica a lo largo del día)"], note: "Es extremadamente común en adultos mayores que están hospitalizados o en cuidados intensivos (UCI)." }, diagnosis: { title: "Evaluación Médica de Urgencia", intro: "El diagnóstico es clínico y se centra en buscar el desencadenante oculto:", items: ["Evaluación del estado mental (comprobando conciencia, atención y pensamiento lógico)", "Examen físico y revisión exhaustiva de todos los medicamentos que toma el paciente (incluyendo los de venta libre)", "Análisis de sangre y orina (para detectar infecciones ocultas, como una infección urinaria en un anciano, problemas hepáticos o renales)", "Pruebas de imagen cerebral (TC o RM para descartar un derrame cerebral o hemorragias si hay trauma)"], note: "" }, treatment: { title: "Abordaje y Cuidado de la Causa", intro: "El tratamiento requiere abordar inmediatamente la condición médica que disparó la confusión:", subsections: [ { title: "Estrategias Clínicas y de Apoyo", items: ["Tratar la infección subyacente (antibióticos para neumonía o infección urinaria) o restaurar electrolitos y fluidos", "Ajustar, suspender o cambiar medicamentos que puedan estar causando toxicidad neurológica", "Atención de apoyo ambiental (mantener la habitación tranquila, bien iluminada de día, con relojes y calendarios a la vista para reorientar al paciente)", "Medicamentos antipsicóticos en dosis muy bajas (solo usados si la agitación severa pone en peligro físico al paciente o impide su tratamiento médico vital)"] } ], note: "Tener familiares presentes que actúen con calma y recuerden al paciente dónde está es una terapia sumamente efectiva." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia?", intro: "El delirium requiere atención médica hospitalaria inmediata. Llama a urgencias si un paciente anciano o enfermo presenta:", items: ["Cambios muy rápidos y bruscos en su personalidad, pasando de ser lógico a no reconocer a sus familiares en cuestión de horas", "Confusión extrema, lenguaje incomprensible o incapacidad total para mantener el hilo de un pensamiento", "Alucinaciones visuales o auditivas marcadas, acompañadas de agitación o agresividad inusual", "Somnolencia tan profunda de la que es casi imposible despertarle"] } },
'Balanitis' : { intro: "La balanitis es la inflamación dolorosa del glande (la cabeza o extremo del pene). A menudo, el prepucio (la piel suelta que cubre el glande) también se inflama, una condición conocida simultáneamente como balanopostitis.", whatIs: { title: "¿Qué es la Balanitis?", text: "Es una irritación cutánea muy común, que afecta con mayor frecuencia a hombres y niños que no están circuncidados. Las condiciones cálidas y húmedas debajo del prepucio crean un ambiente ideal para que los hongos o bacterias proliferen si la higiene no es meticulosa, causando dolor y enrojecimiento." }, types: { title: "Causas y Factores Promotores", intro: "Puede ser infecciosa o no infecciosa:", items: ["Infección por hongos (candidiasis, la causa más común, a menudo asociada a la diabetes)", "Infección bacteriana (estreptococo u otras bacterias asociadas a la mala higiene o a una ETS)", "Irritación de contacto (causada por el uso de jabones fuertes, geles de ducha perfumados, espermicidas o preservativos que irritan la mucosa)", "Condiciones dermatológicas subyacentes (como la psoriasis, eccema o liquen escleroso)"], note: "El riesgo de balanitis crónica se multiplica enormemente en pacientes con diabetes mellitus no controlada." }, diagnosis: { title: "Evaluación Urológica o Dermatológica", intro: "Suele diagnosticarse fácilmente durante un examen físico de la zona íntima:", items: ["Examen visual del glande y del prepucio por un médico general, urólogo o dermatólogo", "Frotis o cultivo con hisopo (se toma una pequeña muestra de la secreción del pene para analizar en laboratorio si hay bacterias o levaduras causantes)", "Análisis de sangre o de orina (para detectar diabetes subyacente si la infección es recurrente)"], note: "" }, treatment: { title: "Higiene y Curas Tópicas", intro: "El tratamiento se basa en eliminar la infección y mejorar la higiene local:", subsections: [ { title: "Intervenciones Comunes", items: ["Cremas antimicóticas o pomadas para hongos (como el clotrimazol o miconazol, si la causa es candidiasis)", "Cremas con corticosteroides suaves (para reducir rápidamente la hinchazón, el enrojecimiento y el picor en balanitis irritativas o por alergia)", "Antibióticos orales o en crema (si hay una infección bacteriana confirmada)", "Circuncisión quirúrgica (se recomienda como tratamiento definitivo en casos de balanitis grave y repetitiva o si el prepucio se ha retraído y estrechado irreversiblemente por las cicatrices - fimosis)"] } ], note: "Lavar el pene diariamente retrayendo suavemente el prepucio y secando muy bien la zona es la prevención fundamental." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Debes buscar atención médica si los cuidados de higiene básica no mejoran el problema en un par de días, y especialmente si:", items: ["Experimentas dolor punzante al orinar o incapacidad para retraer el prepucio (fimosis)", "Notas una secreción espesa, amarillenta o de olor muy fétido bajo el prepucio", "El prepucio se queda atascado detrás de la cabeza del pene y no puede volver a cubrirlo, causando hinchazón rápida y dolorosa (parafimosis, una emergencia médica absoluta)", "Se forman úlceras dolorosas o llagas sangrantes en el glande"] } },
'Conducta' : { intro: "El trastorno de la conducta es un diagnóstico psiquiátrico grave que se presenta en niños y adolescentes. Se distingue por un patrón repetitivo y persistente de comportamiento en el que se violan flagrantemente los derechos básicos de otras personas o las principales normas sociales apropiadas para la edad.", whatIs: { title: "¿Qué es el Trastorno de Conducta?", text: "Es una alteración del comportamiento infantil o juvenil que va mucho más allá de la rebeldía adolescente típica. Involucra una crueldad intencional, agresividad, comportamiento antisocial sostenido y una alarmante falta de empatía o remordimiento por el daño causado a personas, animales o propiedades." }, types: { title: "Tipos por Edad de Inicio y Gravedad", intro: "El pronóstico depende de la edad en que comienzan los síntomas:", items: ["Tipo de inicio en la infancia (los síntomas agresivos aparecen antes de los 10 años; es más severo, ocurre frecuentemente en varones y tiene mayor riesgo de evolucionar a un trastorno de personalidad antisocial en la adultez)", "Tipo de inicio en la adolescencia (los síntomas surgen después de los 10 años; la persona suele tener mejores relaciones sociales con compañeros y un mejor pronóstico de rehabilitación)", "Comportamientos clave: agresión a personas o animales (acoso, peleas físicas, crueldad), destrucción de la propiedad (vandalismo, provocar incendios intencionales), engaño o robo, y violaciones graves de las reglas (fugarse de casa, absentismo escolar crónico)"], note: "Frecuentemente coexiste con el Trastorno por Déficit de Atención e Hiperactividad (TDAH), el trastorno de oposición desafiante o trastornos del aprendizaje." }, diagnosis: { title: "Evaluación Psicológica Integral", intro: "Requiere una valoración profunda por un psiquiatra infantil o psicólogo especializado:", items: ["Entrevistas clínicas estructuradas con los padres, maestros y el propio menor para documentar el patrón de comportamiento (que debe durar al menos 12 meses)", "Evaluación del entorno familiar y social para identificar factores de estrés, abuso, trauma o violencia intrafamiliar", "Evaluación cognitiva y de aprendizaje para descartar frustraciones originadas en discapacidades intelectuales no detectadas"], note: "" }, treatment: { title: "Psicoterapia Familiar y Conductual", intro: "El tratamiento es un proceso a largo plazo que requiere el compromiso absoluto de la familia y la escuela:", subsections: [ { title: "Intervenciones Terapéuticas", items: ["Entrenamiento en el manejo de padres (enseñar a los padres técnicas consistentes y eficaces para imponer disciplina, límites claros y promover comportamientos positivos)", "Terapia Cognitivo-Conductual (TCC) para el menor (para enseñarle habilidades de resolución de problemas, control de la ira, empatía y control de impulsos)", "Terapia familiar sistémica (para mejorar la comunicación y la dinámica de interacción en el hogar)", "Medicación (no trata directamente el trastorno de conducta, pero se usa para tratar problemas coexistentes muy comunes como el TDAH, la depresión severa o la impulsividad explosiva)"] } ], note: "Los castigos físicos o las intervenciones puramente punitivas tipo 'campamento militar' suelen empeorar el comportamiento y la agresión del menor." }, whenToSeekHelp: { title: "¿Cuándo buscar intervención especializada?", intro: "Es urgente solicitar ayuda psiquiátrica infantil si tu hijo:", items: ["Muestra crueldad física intencional hacia los animales de compañía o hacia niños más pequeños", "Se involucra en peleas físicas con uso de armas o herramientas peligrosas", "Miente de forma compulsiva para estafar, roba objetos de valor o se escapa repetidamente de la casa durante la noche", "Muestra una total ausencia de culpa, remordimiento o empatía cuando sus acciones lastiman seriamente a otras personas"] } },
'Úlceras venosas' : { intro: "Las úlceras venosas (o úlceras de estasis venosa) son llagas superficiales crónicas que aparecen en la piel de la parte inferior de las piernas, frecuentemente por encima y alrededor del tobillo interior. Son la consecuencia directa de una mala circulación sanguínea venosa sostenida en el tiempo.", whatIs: { title: "¿Qué es una Úlcera Venosa?", text: "Es una herida abierta en la pierna que tarda semanas, meses o incluso años en sanar. Ocurre cuando las válvulas dentro de las venas de las piernas fallan y la sangre retrocede y se estanca (insuficiencia venosa). El aumento de presión daña los diminutos vasos capilares y la piel, provocando que el tejido se descomponga y se abra formando una llaga." }, types: { title: "Signos Clínicos y Estadios Previos", intro: "Antes de que la úlcera se abra, la pierna muestra claros signos de sufrimiento circulatorio:", items: ["Edema venoso (hinchazón crónica de la pierna que empeora al final del día)", "Dermatitis por estasis (la piel del tobillo se vuelve roja, seca, con escamas y pica intensamente)", "Lipodermatosclerosis (la piel y la grasa de la parte inferior de la pierna se vuelven duras, leñosas y se tiñen de un color marrón oscuro permanente debido a la descomposición de la sangre acumulada)", "La úlcera final (suele ser superficial, de bordes irregulares, llorosa o exudativa, y a menudo indolora a menos que se infecte)"], note: "Cualquier golpe o rasguño menor en una pierna con insuficiencia venosa puede desencadenar una gran úlcera que no cicatriza." }, diagnosis: { title: "Evaluación Vascular y de Heridas", intro: "El especialista vascular o el experto en heridas realizará:", items: ["Examen físico visual de la pierna, los pulsos y la herida (comprobando la profundidad, el tamaño y la presencia de tejido muerto o infección)", "Ecografía Doppler venosa de las piernas (el estudio esencial para observar cómo fluye la sangre y detectar las válvulas fallidas o un coágulo de sangre oculto -TVP-)", "Cálculo del Índice Tobillo-Brazo (ITB) (para descartar insuficiencia arterial; si las arterias también están bloqueadas, el tratamiento con compresión es peligroso)"], note: "" }, treatment: { title: "Compresión y Curación de Heridas", intro: "La herida no cerrará hasta que se corrija el problema de la presión y estancamiento de la sangre:", subsections: [ { title: "Protocolo de Tratamiento", items: ["Terapia de compresión graduada (el pilar fundamental; usar vendajes elásticos médicos multicapa o medias de compresión fuertes que empujen el líquido de vuelta al corazón)", "Elevación de las piernas (el paciente debe elevar las piernas por encima del nivel del corazón varias veces al día para reducir la presión por gravedad)", "Cuidado local de la herida (limpieza regular, desbridamiento del tejido muerto y uso de apósitos especializados que absorben el exceso de líquido)", "Cirugía o ablación de venas (destruir o extirpar las venas varicosas o perforantes dañadas con láser o radiofrecuencia para curar la úlcera de forma definitiva y evitar recaídas)", "Antibióticos (únicamente si la úlcera muestra signos claros de infección bacteriana y celulitis)"] } ], note: "Sin compresión constante y medias adecuadas de por vida, el riesgo de que la úlcera vuelva a abrirse tras sanar es casi del 70%." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "No esperes a que la llaga se cierre sola, pues solo empeorará. Busca ayuda médica si:", items: ["Tienes un rasguño, herida o llaga en la pierna o tobillo que no ha mostrado signos de curación en 2 semanas", "La pierna circundante se vuelve caliente, muy enrojecida, hinchada o el dolor aumenta bruscamente (signos de infección celulítica)", "La úlcera comienza a supurar mucho pus amarillento, verdoso o despide un mal olor penetrante", "Sufres de escalofríos o fiebre repentina"] } },
'Codo de niñera' : { intro: "El codo de niñera (subluxación de la cabeza del radio) es una dislocación parcial, temporal y muy dolorosa de los huesos del codo. Es una de las lesiones articulares más frecuentes en la primera infancia, afectando casi exclusivamente a niños de entre 1 y 4 años de edad.", whatIs: { title: "¿Qué es el Codo de Niñera?", text: "Ocurre cuando el ligamento anular (un anillo de tejido duro que sostiene el hueso del codo en su lugar) se desliza temporalmente sobre la cabeza del hueso del radio tras un tirón. En los niños pequeños, los ligamentos son elásticos y los huesos no están completamente formados, por lo que un tirón brusco del brazo desplaza la articulación y atrapa el ligamento." }, types: { title: "Mecanismo Típico de Lesión", intro: "Casi siempre es el resultado de un tirón repentino de la mano o la muñeca del niño mientras su brazo está extendido y estirado:", items: ["Levantar al niño por las manos o muñecas para subir un bordillo o entrar a un coche", "Girar o balancear al niño por los brazos o las manos mientras se juega ('el columpio humano')", "Agarrar bruscamente la mano del niño para evitar que se caiga o cruce una calle", "Tirar del brazo a través de la manga de un abrigo o chaqueta apretada"], note: "El niño responde con llanto instantáneo y luego se niega rotundamente a usar el brazo lesionado, manteniéndolo pegado al cuerpo, ligeramente flexionado, sin querer rotar la palma hacia arriba." }, diagnosis: { title: "Diagnóstico Clínico Directo", intro: "El diagnóstico de este síndrome es extremadamente claro y visual para un médico o pediatra de urgencias:", items: ["Examen físico (el médico observará la postura típica protectora del brazo y el relato de los padres sobre el tirón previo)", "Palpación suave (no hay inflamación visible extrema, hematomas profundos ni deformidad estructural masiva como en una fractura grave)", "Radiografías (generalmente NO son necesarias en absoluto si el historial es clásico de codo de niñera, pero se ordenan si el médico sospecha que podría haber un hueso fracturado tras una caída)"], note: "" }, treatment: { title: "Maniobra de Reducción Médica Rápida", intro: "Es un problema sumamente fácil y veloz de corregir por un profesional capacitado:", subsections: [ { title: "Procedimiento en Consulta", items: ["Reducción cerrada manual (el pediatra o médico de urgencias aplica una maniobra física rápida y experta, doblando y rotando la muñeca o el antebrazo del niño de manera específica para volver a colocar el ligamento suelto en su posición natural sobre la cabeza del radio)", "El alivio es casi instantáneo; muchos niños vuelven a usar su brazo con total normalidad para jugar a los pocos minutos de la maniobra", "No requiere yesos, inmovilizaciones largas ni cirugía"] } ], note: "NUNCA debes intentar enderezar el brazo o hacer esta maniobra por tu cuenta en casa, ya que si es una fractura real oculta, el daño será gravísimo." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias o al pediatra?", intro: "Debes buscar ayuda médica si el brazo del niño queda inmovilizado:", items: ["El niño se niega a utilizar uno de sus brazos o se queja intensamente al intentar moverlo o si alguien lo toca", "El brazo cuelga flojo al costado del cuerpo y el niño llora de forma persistente tras un tirón", "Observas una hinchazón muy severa, la articulación del codo está desfigurada o sospechas que se ha producido una fractura real por un impacto fuerte directo"] } },
'Aborto espontáneo' : { intro: "El aborto espontáneo es la pérdida natural y no intencional de un embarazo antes de la semana 20 de gestación. Es la complicación más frecuente del embarazo temprano; aproximadamente 1 de cada 4 o 5 embarazos reconocidos médicamente termina en pérdida.", whatIs: { title: "¿Qué es el Aborto Espontáneo?", text: "Es el cese del desarrollo fetal temprano. La inmensa mayoría de las pérdidas en el primer trimestre ocurren porque el feto no se está desarrollando con normalidad debido a problemas cromosómicos aleatorios y fatales en la división celular. No es causado por ejercicio, estrés, trabajo o sexo, y rara vez es 'culpa' de las acciones de la madre." }, types: { title: "Tipos Clínicos de Aborto", intro: "Los médicos utilizan términos específicos para describir el estado del proceso:", items: ["Amenaza de aborto (sangrado vaginal o dolor abdominal presentes, pero el cuello del útero está cerrado y el embarazo aún es viable y puede continuar)", "Aborto inevitable (el sangrado y los calambres aumentan, y el cuello uterino se abre; el aborto no se puede detener)", "Aborto incompleto (se expulsa parte del tejido fetal o de la placenta, pero algunos restos se quedan en el útero, requiriendo intervención)", "Aborto completo (el cuerpo expulsa por completo todo el tejido del embarazo sin necesidad de intervención médica)", "Aborto diferido o retenido (el embrión muere o no se desarrolla, pero el cuerpo no reconoce la pérdida y el tejido permanece en el útero sin sangrado ni dolor)", "Aborto recurrente (tres o más pérdidas consecutivas de embarazos, requiere un estudio genético e inmunológico exhaustivo)"], note: "" }, diagnosis: { title: "Confirmación Ecográfica y Hormonal", intro: "El ginecólogo confirmará el estado del embarazo y la viabilidad:", items: ["Ecografía transvaginal o pélvica (la herramienta clave para revisar el desarrollo del saco gestacional, el embrión y, principalmente, verificar la presencia o ausencia de los latidos del corazón fetal)", "Análisis de sangre en serie (para medir si los niveles de la hormona del embarazo, la gonadotropina coriónica humana o hCG, están aumentando adecuadamente o están disminuyendo)", "Examen pélvico físico (para comprobar si el cuello uterino ha comenzado a dilatarse y abrirse)"], note: "" }, treatment: { title: "Manejo Médico y Evacuación Uterina", intro: "El tratamiento busca prevenir hemorragias severas o infecciones si el cuerpo no limpia el tejido por completo:", subsections: [ { title: "Opciones Terapéuticas", items: ["Manejo expectante o conservador (permitir y esperar a que el aborto ocurra y finalice de forma totalmente natural en casa en las semanas siguientes, si no hay riesgos de infección)", "Tratamiento médico farmacológico (medicamentos recetados como el misoprostol, tomados por vía oral o vaginal, que inducen contracciones uterinas para forzar la expulsión del tejido retenido más rápidamente)", "Tratamiento quirúrgico o legrado (Dilatación y Legrado, D&C, o aspiración al vacío; un procedimiento en quirófano donde el médico retira y limpia suavemente el interior del útero para prevenir infecciones o detener hemorragias graves)", "Apoyo psicológico incondicional (es fundamental tratar el duelo de la pérdida perinatal, que genera sentimientos de culpa, ansiedad y depresión)"] } ], note: "Físicamente, el útero suele recuperarse muy rápido y es posible ovular e intentar otro embarazo sano en apenas semanas o un par de meses, según la recomendación del doctor." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia o requieres revisión médica?", intro: "Llama a tu médico o acude a las urgencias obstétricas de inmediato si estás embarazada y tienes:", items: ["Sangrado vaginal importante (que empape más de una toalla sanitaria gruesa en una sola hora)", "Expulsión de grandes coágulos de sangre, tejido sólido o material de color grisáceo/rosado por la vagina", "Dolores abdominales, calambres severos o dolor agudo e insoportable en el bajo vientre o parte baja de la espalda", "Fiebre alta, escalofríos, mareos severos o secreción vaginal con un olor muy fétido (indicativo de una infección grave y letal o aborto séptico)"] } },
'Trastornos del desarrollo sexual' : { intro: "Los trastornos del desarrollo sexual (TDS), conocidos también como intersexualidad o diferencias del desarrollo sexual (DSD), son un grupo de afecciones congénitas raras en las que el desarrollo cromosómico, gonadal o anatómico del sexo es atípico o no coincide con los estándares de desarrollo exclusivamente masculino o femenino.", whatIs: { title: "¿Qué son los Trastornos del Desarrollo Sexual?", text: "Son variaciones biológicas que ocurren durante el desarrollo del feto en el útero. Un individuo puede nacer con genética femenina (XX) pero con anatomía externa de apariencia masculina, genética masculina (XY) pero anatomía externa femenina, o nacer con genitales ambiguos o atípicos y características tanto de tejido ovárico como testicular." }, types: { title: "Clasificación Biológica de los Síndromes", intro: "Se agrupan según su origen genético y hormonal primario:", items: ["Hiperplasia Suprarrenal Congénita (HSC) (la causa más común de genitales ambiguos en recién nacidos 46, XX; las glándulas suprarrenales producen exceso de hormonas masculinas, y sin tratamiento de cortisol puede ser una emergencia médica al nacer)", "Síndrome de Insensibilidad a los Andrógenos (SIA) (una persona con cromosomas 46, XY que produce testosterona, pero sus células son insensibles a ella; desarrollan genitales externos femeninos pero carecen de útero y ovarios)", "Disgenesia gonadal mixta o pura (los testículos u ovarios no se desarrollan correctamente)", "Anomalías en los cromosomas sexuales (como el Síndrome de Turner, 45,X, o el Síndrome de Klinefelter, 47,XXY, que afectan el desarrollo gonadal y la pubertad)"], note: "Estas condiciones subrayan que el sexo biológico es un espectro, no un concepto absolutamente binario, mediado por complejas señales genéticas." }, diagnosis: { title: "Evaluación Médica Pediátrica y Genética", intro: "El diagnóstico requiere extrema sensibilidad por parte de un equipo médico multidisciplinario, a menudo desde el nacimiento:", items: ["Evaluación clínica al nacer si los genitales son atípicos", "Análisis genético del cariotipo o secuenciación genética de ADN (para determinar el patrón de los cromosomas sexuales: XX, XY o mosaicos)", "Extensas pruebas de niveles hormonales y electrolitos en sangre (para diagnosticar urgencias como la pérdida de sal en la hiperplasia suprarrenal)", "Pruebas de imagen pélvica avanzadas (ecografía o RM abdominal para confirmar la presencia o ausencia de órganos reproductivos internos como útero, testículos ocultos o tejido gonadal)"], note: "" }, treatment: { title: "Asignación, Manejo Hormonal y Ética", intro: "El tratamiento actual enfatiza la atención médica, no las cirugías puramente estéticas infantiles:", subsections: [ { title: "Apoyo y Opciones", items: ["Asignación de género basada en una evaluación integral y el pronóstico de desarrollo futuro con apoyo familiar", "Terapia de Reemplazo Hormonal (TRH) (para desencadenar los cambios de la pubertad, mantener la densidad ósea y alinear las características sexuales en la adolescencia)", "Cirugía (las guías modernas aconsejan fuertemente retrasar las cirugías reconstructivas o extirpaciones genitales electivas irreversibles hasta que el niño crezca lo suficiente para participar en la decisión y otorgar su consentimiento, excepto en casos donde la anatomía bloquea el flujo de orina o hay un riesgo inminente de cáncer gonadal)", "Apoyo psicológico continuo y profundo (para el individuo y la familia para manejar la identidad, el estigma social y temas de fertilidad futura)"] } ], note: "El enfoque médico ha cambiado radicalmente para respetar el derecho del individuo sobre su propio cuerpo y evitar traumas quirúrgicos en bebés." }, whenToSeekHelp: { title: "¿Cuándo es necesaria la evaluación especializada?", intro: "Es fundamental el seguimiento con un endocrinólogo pediatra o genetista cuando:", items: ["Un bebé nace con genitales atípicos, ambiguos o es difícil determinar su sexo visualmente al nacer (se requiere descartar la crisis suprarrenal que pierde sal)", "Un adolescente sufre de un grave retraso de la pubertad (no hay desarrollo de senos en las chicas ni agrandamiento testicular en los chicos a los 14 años)", "Una adolescente llega a los 15-16 años con desarrollo físico femenino pero sin que se inicie nunca la menstruación (amenorrea primaria)", "Existen anomalías uretrales (como hipospadias severas) o los testículos no logran descender al escroto"] } },
'Enfermedad de Osgood-Schlatter' : { intro: "La enfermedad de Osgood-Schlatter es una afección muy común que causa dolor crónico e hinchazón en la parte delantera e inferior de la rodilla, justo por debajo de la rótula. Afecta principalmente a niños y adolescentes durante sus etapas o rachas de crecimiento acelerado (el estirón).", whatIs: { title: "¿Qué es la Enfermedad de Osgood-Schlatter?", text: "Es una 'apofisitis por tracción' e irritación mecánica. Durante el estirón de la adolescencia, los músculos del muslo (cuádriceps) tiran repetidamente del tendón rotuliano, el cual se ancla en el hueso de la tibia. Esta tracción constante irrita y a veces inflama la zona de crecimiento del hueso (tuberosidad tibial), creando un pequeño y doloroso bulto óseo." }, types: { title: "Factores Desencadenantes", intro: "Suele afectar con severidad a jóvenes con un perfil específico:", items: ["Adolescentes deportistas que practican deportes que exigen correr, saltar, frenar repentinamente o patear (fútbol, baloncesto, gimnasia, ballet, atletismo)", "Afecta clásicamente a niños (varones) de 12 a 14 años y a niñas de 10 a 13 años (el rango coincide con el inicio de sus estirones rápidos)", "Puede presentarse en una sola rodilla, que es lo más habitual, o a menudo en ambas rodillas a la vez"], note: "Esta no es una enfermedad degenerativa ni artritis; es una molestia del desarrollo óseo." }, diagnosis: { title: "Evaluación Ortopédica o Pediátrica", intro: "Suele ser un diagnóstico bastante directo y clínico sin necesidad de grandes pruebas:", items: ["Examen físico palpando la protuberancia ósea justo debajo de la rodilla (la cual suele ser sumamente sensible y dolorosa al tacto o a la presión directa)", "Radiografía de la rodilla (generalmente solo se realiza para observar con claridad la inflamación del hueso de crecimiento y, sobre todo, para descartar descartar cualquier otra causa del dolor como fisuras o tumores óseos en el joven)"], note: "" }, treatment: { title: "Tratamiento de Reposo y Alivio", intro: "La condición tiene un pronóstico excelente; se autolimita y mejora considerablemente a medida que los huesos dejan de crecer:", subsections: [ { title: "Opciones de Manejo Doméstico", items: ["Modificación del nivel de actividad física (limitar fuertemente o hacer pausas en los deportes de salto y carrera hasta que el dolor intenso ceda; no es necesario dejar de moverse por completo, pero sí evitar forzar la zona)", "Aplicar compresas frías o hielo en la protuberancia de la rodilla dolorida inmediatamente después de hacer deporte", "Uso de medicamentos analgésicos y antiinflamatorios (como ibuprofeno o naproxeno de venta libre) durante los brotes de inflamación", "Uso de cintas protectoras o tiras rotulianas para sostener el tendón debajo de la rótula y disipar algo del esfuerzo", "Ejercicios terapéuticos guiados para estirar de manera eficaz los isquiotibiales rígidos y los cuádriceps de los muslos"] } ], note: "Aunque el dolor a menudo desaparece cuando el adolescente deja de crecer, el pequeño bulto óseo por debajo de su rodilla puede ser permanente y notorio para toda la vida." }, whenToSeekHelp: { title: "¿Cuándo solicitar revisión de tu médico?", intro: "Es recomendable visitar a un pediatra o traumatólogo si:", items: ["El dolor del niño en la rodilla se vuelve tan intenso que interfiere profundamente en su capacidad para participar y disfrutar de las actividades o rutinas de la vida diaria", "La rodilla además está significativamente roja, se siente muy caliente al tacto, o se nota excesivamente bloqueada e inflamada con líquido", "El niño empieza a presentar fiebre, debilidad repentina en la pierna, o problemas severos continuados al caminar"] } },
'Hiperplasia prostática' : { intro: "La hiperplasia prostática benigna (HPB) es el agrandamiento fisiológico no canceroso (benigno) de la glándula prostática en los hombres a medida que envejecen. Afecta drásticamente la calidad de la micción y puede crear severas molestias del tracto urinario inferior.", whatIs: { title: "¿Qué es la Hiperplasia Prostática Benigna?", text: "La próstata es una pequeña glándula que rodea el tubo (uretra) que transporta la orina desde la vejiga hacia afuera del pene. Al crecer y agrandarse debido a los cambios hormonales del envejecimiento masculino natural, la próstata estrangula, presiona y oprime el conducto uretral, bloqueando dolorosa y progresivamente el flujo de orina." }, types: { title: "Síntomas y Problemas Urinarios", intro: "Los signos varían mucho, pero tienden a empeorar silenciosa y progresivamente con los años si no hay tratamiento:", items: ["Flujo de orina intermitente, vacilante, excesivamente débil o que no tiene la fuerza habitual de antes", "La fuerte y desesperada necesidad de orinar de forma urgente, constante o incontrolable (incontinencia por urgencia)", "Aumento masivo e insoportable en la frecuencia para orinar por la noche, impidiendo dormir (nicturia)", "Gran esfuerzo y tensión física requerida abdominalmente solo para lograr comenzar a orinar y gotear al final", "Sensación clara de no poder vaciar la vejiga por completo tras ir al baño"], note: "El agrandamiento prostático NO es cáncer de próstata y NO aumenta en modo alguno el riesgo de padecer cáncer, aunque ambas condiciones pueden coexistir en ancianos." }, diagnosis: { title: "Detección y Evaluaciones Urológicas", intro: "El urólogo necesita descartar la presencia del cáncer prostático y medir el grado del daño por obstrucción urinaria:", items: ["Tacto rectal o examen digital rectal del médico (evaluación básica donde el urólogo palpa físicamente el tamaño y forma de la próstata mediante el recto)", "Análisis general de orina (para descartar una infección asociada) y prueba de sangre de PSA (Antígeno Prostático Específico) para evaluar factores prostáticos o de tumor", "Flujometría urinaria simple (una prueba en la que se orina en un recipiente que mide la velocidad y el volumen de la fuerza del chorro)", "Ecografía prostática y determinación del residuo de orina posmiccional (para confirmar la cantidad de mililitros que retiene la vejiga)"], note: "" }, treatment: { title: "Medicamentos de Apertura y Terapias Quirúrgicas", intro: "Hay una multiplicidad de tratamientos, desde pastillas sencillas hasta modernas técnicas de invasión mínima con láser:", subsections: [ { title: "Enfoque Terapéutico y Quirúrgico", items: ["Vigilancia médica activa (si los problemas o síntomas son muy leves y no alteran la vida)", "Tratamiento farmacológico de alfabloqueantes (como tamsulosina, que relaja y abre rápidamente los músculos de la próstata y del cuello de la vejiga para dejar pasar el fluido)", "Medicamentos inhibidores de la 5-alfa reductasa (como finasterida, que combaten la hormona que hace que la glándula crezca, reduciendo lentamente su tamaño en varios meses)", "Terapias modernas y mínimamente invasivas (uso de vapor de agua para destruir tejidos, elevación uretral prostática UroLift o terapia láser HoLEP para ampliar la vía)", "Resección Transuretral Quirúrgica de la Próstata (RTUP) u otras operaciones para raspar y extirpar las porciones problemáticas del exceso de glándula cuando el bloqueo se torna total o falla la medicina"] } ], note: "Ciertos remedios descongestionantes para resfriados que contienen sustancias como pseudoefedrina pueden contraer los músculos de la próstata y causar una retención o bloqueo urgente y doloroso al instante." }, whenToSeekHelp: { title: "¿Cuándo acudir inmediatamente a emergencias médicas o al médico?", intro: "Debes de visitar a tu médico para discutir de forma proactiva tus síntomas urinarios, pero resulta una emergencia urológica grave acudir al hospital si:", items: ["Sufres repentinamente de retención urinaria aguda (incapacidad absoluta y dolorosa de expulsar una sola gota de orina a pesar de sentir la vejiga muy llena)", "Ves u observas claramente y a simple vista un rastro de sangre en la orina", "Tienes dolor muy intenso y ardor inusual en tu tracto urinario", "Comienzas a experimentar fiebre elevada inexplicada, escalofríos severos o fuerte malestar, combinados con las molestias para ir a orinar"] } },
'Oclusión de las venas retinianas' : { intro: "La oclusión de las venas retinianas, a menudo descrita popularmente como un 'derrame ocular interno', es el bloqueo brusco de las pequeñas venas o ramificaciones venosas que se encargan de transportar la sangre desde la retina (la capa de tejido sensible a la luz en el fondo del ojo) de vuelta hacia el corazón.", whatIs: { title: "¿Qué es una Oclusión Venosa de la Retina?", text: "Es esencialmente el equivalente oftalmológico o visual a tener un infarto o trombosis en el ojo. Cuando el flujo de retorno venoso se tapona debido a un coágulo o aterosclerosis, la sangre fresca no puede salir; esto causa presión, filtraciones masivas de sangre y líquido al tejido ocular, dañando la mácula, e interrumpiendo abruptamente la visión clara." }, types: { title: "Tipos de Obstrucciones Retinianas", intro: "Se categoriza de acuerdo a qué vena crucial exacta resulta ser bloqueada:", items: ["Oclusión de rama de la vena retiniana (OVRR) (ocurre cuando se bloquea tan solo una de las pequeñas venas ramificadas, causando pérdida de visión periférica o central, suele ser menos severa)", "Oclusión de la vena central de la retina (OVCR) (ocurre cuando se bloquea por completo y de golpe la vena principal enorme del ojo; provoca una pérdida profunda de la visión total del ojo)"], note: "Padecer factores como diabetes mal controlada, el glaucoma crónico y especialmente una presión arterial alta crónica son las principales condiciones o factores de riesgo que causan las oclusiones." }, diagnosis: { title: "Examen Oftalmológico Profundo", intro: "El especialista y experto en retina evaluará de inmediato el estado del bloqueo y daño:", items: ["Examen visual directo del fondo de ojo dilatando las pupilas (donde el oftalmólogo descubrirá grandes manchas o hemorragias y un daño clásico en la retina en forma de salpicaduras o llamas)", "Tomografía de Coherencia Óptica o (OCT) (una prueba fotográfica no invasiva para visualizar fluidos y medir la importante hinchazón central severa en la mácula)", "Angiografía con contraste de fluoresceína (inyectando colorante rápido por el brazo y fotografiando las venas del ojo para ver dónde no hay riego de flujo de sangre de inmediato)"], note: "" }, treatment: { title: "Tratamiento por Inyección y Prevención de Ceguera", intro: "No existe cura para abrir mecánicamente la vena en el ojo cerrado, el tratamiento busca evitar complicaciones devastadoras como el edema macular crónico o el desarrollo de neovascularización peligrosa:", subsections: [ { title: "Terapias Oculares Intraoculares y Procedimientos", items: ["Inyecciones intravítreas o directly en el ojo con medicamentos anti-VEGF (medicación como Ranibizumab o Aflibercept inyectada mensualmente en la cámara del ojo que inhibe proteínas letales y detiene dramáticamente las fugas y los vasos sanguíneos aberrantes)", "Inyecciones y administración rápida de esteroides y corticoides (para abatir e impedir la gran hinchazón macular o el edema persistente intraocular)", "Cirugía de fotocoagulación ocular con láser focal (para sellar las fugas por quemadura y destruir con alta energía áreas isquémicas frágiles sin sangre previniendo el glaucoma secundario sangrante neovascular)"] } ], note: "Para evitar la ocurrencia en el otro ojo sano y futuro, es fundamental manejar estrictamente todos los niveles sistémicos cardiovasculares de presión alta, lípidos y colesterol, y la glucemia." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ver a un oftalmólogo especialista de inmediato?", intro: "Nunca debe ser pospuesto. Contacta con atención ocular especializada urgente inmediatamente y acude sin pausa alguna si:", items: ["De un modo y forma súbita, sin ningún tipo de dolor premonitorio o físico, tu visión general en uno solo de los dos ojos se nubla enormemente o desaparece de un apagón de la noche a la mañana", "Tu panorama de visión y perspectiva general empieza a verse con severos bloqueos o amplias zonas ensombrecidas y difuminadas permanentemente", "Sufres la rápida aparición de nubes completas masivas de moscas oscuras y extrañas volantes y centelleos repetitivos ante el ojo involucrado que interfieren o borran una porción grande del campo"] } },
'Laberíntitis' : { intro: "La laberintitis es una inflamación del laberinto, una parte del oído interno que controla la audición y el equilibrio. Suele presentarse de forma repentina y causa mareos intensos y problemas auditivos.", whatIs: { title: "¿Qué es la Laberintitis?", text: "Es una afección típicamente causada por una infección viral (como un resfriado o gripe) o, menos frecuentemente, bacteriana. La inflamación interfiere con las señales que el oído interno envía al cerebro, provocando desorientación espacial severa." }, types: { title: "Causas y Tipos", intro: "Se clasifica por su origen infeccioso:", items: ["Laberintitis viral (la más común, a menudo sigue a una infección del tracto respiratorio superior)", "Laberintitis bacteriana (más grave, puede ser causada por una infección del oído medio que se propaga)", "Laberintitis autoinmune (rara)"], note: "El vértigo puede durar días y la recuperación total tomar semanas." }, diagnosis: { title: "Evaluación Médica", intro: "El diagnóstico es clínico y por exclusión:", items: ["Examen físico y neurológico (buscando nistagmo, que es el movimiento involuntario de los ojos)", "Pruebas de audición (audiometría)", "Resonancia Magnética (RM) para descartar ACV o tumores cerebrales si los síntomas son atípicos"], note: "" }, treatment: { title: "Manejo y Recuperación", intro: "El tratamiento se enfoca en aliviar los síntomas y tratar la infección subyacente:", subsections: [ { title: "Opciones Terapéuticas", items: ["Medicamentos vestibulares y antieméticos (como meclizina o diazepam para frenar el vértigo y las náuseas)", "Corticosteroides (prednisona) para reducir la inflamación del nervio", "Antibióticos (solo si se confirma origen bacteriano)", "Terapia de rehabilitación vestibular (ejercicios para reentrenar el cerebro y recuperar el equilibrio)"] } ], note: "Es vital hacer reposo en cama durante los ataques agudos y evitar cambios bruscos de postura." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias?", intro: "El vértigo puede imitar un derrame cerebral. Busca ayuda inmediata si presentas:", items: ["Vértigo incapacitante repentino acompañado de pérdida de audición", "Visión doble, debilidad, entumecimiento o parálisis en un lado del cuerpo", "Dificultad para hablar o confusión profunda"] } },
'Hiperparatiroidismo' : { intro: "El hiperparatiroidismo es una afección en la que una o más de las glándulas paratiroideas (cuatro glándulas diminutas en el cuello) se vuelven hiperactivas y producen demasiada hormona paratiroidea (PTH), elevando peligrosamente el calcio en la sangre.", whatIs: { title: "¿Qué es el Hiperparatiroidismo?", text: "El exceso de PTH obliga al cuerpo a extraer calcio de los huesos (debilitándolos) y a absorber más calcio de los alimentos y los riñones. Esto provoca hipercalcemia (calcio alto en sangre), lo que daña los huesos, forma cálculos renales y afecta el sistema nervioso." }, types: { title: "Tipos Clínicos", intro: "Depende de la causa subyacente:", items: ["Primario (un tumor benigno o adenoma en la glándula hace que trabaje en exceso; es el más común)", "Secundario (las glándulas producen más PTH en respuesta a otra enfermedad que baja el calcio, como la insuficiencia renal crónica o deficiencia grave de vitamina D)", "Terciario (las glándulas se vuelven autónomas tras años de hiperparatiroidismo secundario)"], note: "A menudo se descubre accidentalmente en análisis de sangre de rutina antes de que haya síntomas." }, diagnosis: { title: "Detección Endocrina", intro: "El endocrinólogo confirmará el diagnóstico a través de:", items: ["Análisis de sangre (hallazgo simultáneo de calcio alto y PTH anormalmente alta)", "Densitometría ósea (DEXA) para evaluar cuánta masa ósea se ha perdido (osteoporosis)", "Ecografía de cuello y Gammagrafía con Sestamibi (para localizar exactamente qué glándula tiene el adenoma antes de operar)"], note: "" }, treatment: { title: "Cirugía y Medicación", intro: "La cirugía es la única cura real para el hiperparatiroidismo primario:", subsections: [ { title: "Intervenciones", items: ["Paratiroidectomía (cirugía mínimamente invasiva para extirpar la glándula o glándulas enfermas)", "Vigilancia activa (si es leve, no hay daño óseo ni renal, monitoreando el calcio anualmente)", "Calcimiméticos (medicamentos como Cinacalcet que engañan a la glándula para que produzca menos PTH)", "Bisfosfonatos (para proteger y reconstruir los huesos debilitados)"] } ], note: "Beber mucha agua es crucial para prevenir la formación de piedras en los riñones." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Solicita un chequeo si experimentas síntomas vagos de hipercalcemia:", items: ["Fatiga severa inexplicable y depresión", "Dolor en los huesos y en las articulaciones", "Episodios repetitivos de cálculos renales (piedras)", "Micción excesiva, náuseas constantes o confusión mental"] } },
'Cálculo en el conducto biliar' : { intro: "Un cálculo en el conducto biliar (coledocolitiasis) ocurre cuando una piedra, formada típicamente en la vesícula biliar, se escapa y se atasca en el conducto colédoco, el tubo principal que transporta la bilis desde el hígado y la vesícula hacia el intestino.", whatIs: { title: "¿Qué es la Coledocolitiasis?", text: "Es una obstrucción biliar. Cuando la piedra bloquea este tubo, la bilis se estanca y retrocede hacia el hígado y el torrente sanguíneo. Esto no solo causa cólicos insoportables, sino que puede desencadenar infecciones graves o pancreatitis aguda si bloquea el conducto pancreático compartido." }, types: { title: "Orígenes de los Cálculos", intro: "Pueden clasificarse según dónde se originaron:", items: ["Cálculos secundarios (el 95% de los casos; se forman en la vesícula biliar y migran hacia el conducto)", "Cálculos primarios (poco comunes; se forman directamente dentro del conducto biliar principal, a menudo debido a infecciones previas)"], note: "Suelen estar compuestos principalmente de colesterol endurecido o pigmentos biliares." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "Requiere imágenes de precisión para localizar el bloqueo:", items: ["Ecografía abdominal (el primer paso, detecta la dilatación de los conductos y piedras en la vesícula)", "Colangiopancreatografía por Resonancia Magnética (CPRM) (el mejor examen no invasivo para ver los conductos en 3D)", "Análisis de sangre (mostrarán bilirrubina elevada y enzimas hepáticas muy alteradas)", "CPRE (Colangiopancreatografía retrógrada endoscópica, es a la vez diagnóstico y tratamiento)"], note: "" }, treatment: { title: "Extracción y Cirugía", intro: "El cálculo atascado debe ser extraído obligatoriamente para evitar daño hepático:", subsections: [ { title: "Procedimientos Intervencionistas", items: ["CPRE (el gastroenterólogo introduce un tubo con cámara por la boca hasta el intestino, localiza el conducto biliar y extrae la piedra con una canastilla o balón)", "Colecistectomía laparoscópica (después de limpiar el conducto, se debe extirpar la vesícula biliar mediante cirugía para evitar que más piedras caigan al conducto en el futuro)", "Antibióticos intravenosos (si existe fiebre o infección de los conductos - colangitis)"] } ], note: "La CPRE suele realizarse de urgencia y proporciona un alivio inmediato de la obstrucción." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia vital?", intro: "Una obstrucción biliar es una emergencia médica. Ve al hospital de inmediato si presentas:", items: ["Dolor severo, agudo y continuo en el lado superior derecho del abdomen", "Coloración amarillenta obvia en tu piel y en la parte blanca de tus ojos (Ictericia)", "Fiebre alta con escalofríos intensos (sospecha de Colangitis, que es letal en horas)", "Heces de color muy pálido, arcilla o blanco, y orina oscura como el té"] } },
'Quiste sebáceo' : { intro: "Un quiste sebáceo (médicamente llamado quiste epidermoide o quiste pilar) es un bulto no canceroso de crecimiento lento bajo la piel. Suele aparecer en el rostro, el cuello, el cuero cabelludo o el torso, y contiene un material espeso y maloliente.", whatIs: { title: "¿Qué es un Quiste Sebáceo?", text: "Ocurre cuando las células de la superficie de la piel (epidermis) se mueven hacia el interior y se multiplican, formando un saco cerrado en lugar de desprenderse. Este saco se llena de queratina, una proteína que parece una pasta blanca o amarilla. No son verdaderos quistes de glándulas sebáceas, aunque el público los llama así." }, types: { title: "Tipos de Quistes Cutáneos", intro: "Existen dos tipos principales según su tejido de origen:", items: ["Quistes epidermoides (se forman a partir de las células de la piel, son comunes en la cara, cuello y tronco)", "Quistes pilares o triquilemales (se originan en la raíz de los folículos pilosos, ocurren casi exclusivamente en el cuero cabelludo)"], note: "A menudo tienen un pequeño 'punto' o poro central oscuro en la superficie de la piel." }, diagnosis: { title: "Examen Dermatológico", intro: "El diagnóstico es simple y visual:", items: ["El médico o dermatólogo lo diagnosticará tocando el bulto y examinando la piel (es móvil, redondo y liso)", "Ocasionalmente, si el bulto es inusual o muy grande, puede pedir una ecografía o enviar el tejido extraído a patología para descartar cáncer cutáneo"], note: "" }, treatment: { title: "Drenaje y Extirpación", intro: "Los quistes pequeños asintomáticos no necesitan tratamiento. Si molestan o se infectan, requieren intervención:", subsections: [ { title: "Procedimientos Menores", items: ["Inyección de corticosteroides (para reducir la inflamación si el quiste está hinchado pero no infectado)", "Incisión y drenaje (se hace un corte, se extrae el pus y la queratina, pero el quiste suele volver a crecer si no se saca la cápsula o saco)", "Escisión quirúrgica completa (el único método curativo definitivo; se extrae el quiste entero con su saco o cápsula bajo anestesia local para evitar recurrencias)", "Antibióticos orales (solo si hay celulitis o una infección secundaria diseminada en la piel)"] } ], note: "NUNCA intentes reventar o exprimir un quiste en casa. Esto empuja la queratina hacia la piel circundante causando una infección severa y una cicatriz dolorosa." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Pide una cita con tu dermatólogo o médico si el quiste:", items: ["Crece rápidamente de tamaño o se vuelve muy doloroso al tacto", "Se vuelve rojo, caliente y empieza a supurar un líquido de olor fétido (está infectado)", "Aparece en un lugar que constantemente se irrita con la ropa o un peine", "Te molesta estéticamente y deseas que te lo extirpen"] } },
'Artritis gotosa aguda' : { intro: "La artritis gotosa aguda, o simplemente gota, es un tipo de artritis inflamatoria extremadamente dolorosa. Se presenta como ataques repentinos y severos de dolor, enrojecimiento y sensibilidad en las articulaciones, afectando característicamente la base del dedo gordo del pie.", whatIs: { title: "¿Qué es la Gota?", text: "Es una enfermedad metabólica y reumática. Ocurre cuando el cuerpo produce demasiado ácido úrico o los riñones no lo excretan bien. Este ácido úrico en exceso se acumula y forma cristales microscópicos afilados (en forma de aguja) dentro de la articulación, lo que desencadena un ataque masivo del sistema inmunológico y una inflamación feroz." }, types: { title: "Fases de la Enfermedad", intro: "La gota progresa en etapas si los niveles de ácido úrico no se controlan:", items: ["Hiperuricemia asintomática (ácido úrico alto en sangre, pero sin ataques ni dolor)", "Gota aguda (el ataque doloroso repentino que dura de unos días a un par de semanas)", "Gota intercrítica (períodos sin síntomas entre los ataques de gota)", "Gota tofácea crónica (acumulación permanente de bultos duros de cristales de urato llamados 'tofos' bajo la piel y en articulaciones, causando daño óseo irreversible)"], note: "El alcohol, la carne roja y los mariscos (altos en purinas) pueden desencadenar un ataque." }, diagnosis: { title: "Evaluación Clínica y Articular", intro: "El diagnóstico preciso es clave para distinguirla de una infección articular:", items: ["Análisis del líquido sinovial (el 'estándar de oro': el reumatólogo extrae líquido de la articulación hinchada y observa los cristales de urato bajo un microscopio polarizado)", "Análisis de sangre (para medir el nivel de ácido úrico, aunque puede ser normal durante un ataque agudo)", "Ecografía articular o Tomografía (TC) de doble energía (para detectar depósitos de cristales en los cartílagos)"], note: "" }, treatment: { title: "Apagar el Ataque y Control de Ácido Úrico", intro: "El tratamiento se divide en calmar la crisis y prevenir futuros episodios:", subsections: [ { title: "Intervenciones Farmacológicas", items: ["Para el ataque agudo: Antiinflamatorios AINEs fuertes (Indometacina, Naproxeno), Colchicina, o Corticosteroides (orales o inyectados directamente en la articulación)", "Para prevención crónica (reductores de ácido úrico): Medicamentos como Alopurinol o Febuxostat (deben tomarse de por vida para mantener el ácido úrico bajo y disolver los cristales; no se inician durante el ataque agudo)", "Modificación de la dieta (evitar alcohol, vísceras, mariscos y bebidas azucaradas con fructosa) y pérdida de peso"] } ], note: "No dejes de tomar el Alopurinol durante un ataque agudo si ya lo estabas tomando, pero no inicies uno nuevo hasta que el dolor pase." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Acude a emergencias o al reumatólogo rápidamente si:", items: ["Experimentas un dolor articular súbito e insoportable (a menudo te despierta en medio de la noche y no toleras ni el roce de la sábana)", "La articulación está muy caliente, hinchada, roja y rígida", "Presentas fiebre alta o escalofríos (lo que puede indicar una infección articular grave, que es una emergencia)"] } },
'Craneosinostosis' : { intro: "La craneosinostosis es un defecto congénito (de nacimiento) en el cual uno o más de los espacios fibrosos flexibles (suturas) entre los huesos del cráneo del bebé se cierran y se fusionan prematuramente, antes de que el cerebro termine de crecer por completo.", whatIs: { title: "¿Qué es la Craneosinostosis?", text: "El cráneo de un bebé está formado por varias placas óseas separadas por suturas que permiten que la cabeza crezca a medida que el cerebro se expande. Si una de estas costuras se cierra antes de tiempo, el cerebro sigue creciendo, empujando el cráneo en otras direcciones y provocando una forma de la cabeza anormal e irregular." }, types: { title: "Tipos de Fusión", intro: "Se nombran según la sutura específica que se cierra prematuramente:", items: ["Sagital o Escafocefalia (el tipo más común; el cierre de la sutura superior forzando la cabeza a crecer larga y estrecha)", "Coronal (afecta la sutura que va de oreja a oreja, causando una frente aplanada de un lado o de ambos)", "Metópica o Trigonocefalia (fusión de la sutura de la frente, dándole a la cabeza una forma triangular puntiaguda)", "Lambdoidea (muy rara, aplanamiento de la parte posterior de la cabeza)"], note: "La mayoría de los casos ocurren al azar, pero algunos están vinculados a síndromes genéticos (como el Síndrome de Crouzon o Apert)." }, diagnosis: { title: "Evaluación Pediátrica y Neuroquirúrgica", intro: "Se diagnostica visualmente y se confirma con imágenes:", items: ["Examen físico (el pediatra notará la forma inusual de la cabeza y palpará que la 'fontanela' o punto blando está ausente o anormal)", "Medición rigurosa de la circunferencia craneal en cada visita de niño sano", "Tomografía Computarizada (TC) 3D del cráneo (la prueba definitiva para ver exactamente qué suturas están fusionadas y planificar la cirugía)", "Pruebas genéticas (si se sospecha un síndrome hereditario asociado)"], note: "No se debe confundir con la plagiocefalia posicional (cabeza plana por dormir en una sola posición), que no requiere cirugía." }, treatment: { title: "Cirugía Craneofacial y Cascos", intro: "El tratamiento casi siempre implica cirugía para aliviar la presión en el cerebro y corregir la forma:", subsections: [ { title: "Opciones Quirúrgicas", items: ["Cirugía endoscópica mínimamente invasiva (se realiza en bebés menores de 3 a 6 meses; el cirujano abre la sutura cerrada con instrumentos pequeños, seguido del uso de un casco moldeador ortopédico durante meses para guiar el crecimiento)", "Cirugía a cielo abierto o Reconstrucción de la bóveda craneal (para bebés mayores de 6 meses o casos complejos; el neurocirujano retira, remodela y vuelve a colocar los huesos del cráneo en la forma correcta sin necesidad de usar cascos después)"] } ], note: "Sin tratamiento, la presión dentro del cráneo puede aumentar, causando ceguera, retraso mental o convulsiones." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Es fundamental la revisión médica de tu bebé si observas:", items: ["Una forma del cráneo marcadamente asimétrica, inusualmente larga, estrecha o triangular que no mejora en las primeras semanas de vida", "No logras palpar o sentir la 'fontanela' (punto blando) en la parte superior de la cabeza del recién nacido", "Un borde duro o cresta ósea que sobresale y se palpa a lo largo del cráneo del bebé", "Crecimiento muy lento o nulo de la circunferencia de la cabeza en las revisiones pediátricas"] } },
'Mastopatia fibroquística' : { intro: "La mastopatía fibroquística, también conocida como cambios o enfermedad fibroquística de las mamas, es una afección benigna y sumamente común donde el tejido mamario se siente denso, con bultos o texturas similares a una cuerda. Produce dolor que fluctúa con el ciclo menstrual.", whatIs: { title: "¿Qué son los cambios fibroquísticos?", text: "Se considera una variación normal del tejido del seno, no una enfermedad patológica. El tejido mamario responde de forma exagerada a las hormonas mensuales (estrógeno y progesterona), desarrollando quistes inofensivos llenos de líquido y un aumento del tejido fibroso conectivo, lo que causa dolor e inflamación antes de la regla." }, types: { title: "Componentes del Tejido", intro: "Los cambios físicos en la mama incluyen dos elementos principales:", items: ["Quistes mamarios (sacos redondos u ovalados llenos de líquido que aumentan de tamaño y duelen antes del periodo)", "Fibrosis (tejido de soporte que se vuelve prominente, firme y gomoso al tacto, similar a un cordón)"], note: "Estos cambios NO aumentan el riesgo de padecer cáncer de mama, a menos que una biopsia revele hiperplasia atípica." }, diagnosis: { title: "Evaluación Ginecológica (Descartar Cáncer)", intro: "El médico debe asegurarse de que los bultos no sean malignos:", items: ["Examen clínico de mama (el médico palpa la textura de la mama y su relación con el ciclo menstrual)", "Ecografía o Ultrasonido mamario (la mejor prueba para diferenciar rápidamente si un bulto es un quiste líquido inofensivo o una masa sólida)", "Mamografía (para buscar anomalías, especialmente en mujeres mayores de 40 años)", "Aspiración con aguja fina (para drenar el líquido del quiste, lo cual confirma que es un quiste y alivia el dolor)"], note: "" }, treatment: { title: "Alivio del Dolor y Manejo", intro: "Si la afección no causa molestias, no se necesita tratamiento. Para el dolor intenso:", subsections: [ { title: "Opciones de Cuidado", items: ["Uso de un sostén de buen soporte, especialmente de estilo deportivo, durante el día y la noche en los días de dolor", "Medicamentos antiinflamatorios (ibuprofeno o paracetamol) para el dolor premenstrual", "Anticonceptivos orales (las pastillas regulan las hormonas y previenen o disminuyen la formación de los quistes dolorosos)", "Reducción o eliminación estricta de cafeína (café, refrescos, chocolate) y restricción de sal; ayuda a muchas mujeres a reducir los síntomas significativamente", "Aspiración de líquido (si un quiste en particular es grande y muy doloroso, el médico lo drena con una aguja en la clínica)"] } ], note: "Los síntomas tienden a disminuir drásticamente o desaparecer por completo después de la menopausia." }, whenToSeekHelp: { title: "¿Cuándo solicitar revisión médica inmediata?", intro: "Siempre debes confirmar que un bulto es fibroquístico y no cáncer. Acude al médico si:", items: ["Encuentras un bulto nuevo, firme y duro en la mama que antes no estaba", "Tienes áreas de engrosamiento o bultos que no desaparecen ni cambian de tamaño después de que termina tu menstruación", "Un bulto preexistente diagnosticado como fibroquístico comienza a crecer o a cambiar de repente", "Notas una secreción de líquido transparente, rojo o sanguinolento por el pezón"] } },
'Subluxación vertebral' : { intro: "Una subluxación vertebral es un término clínico utilizado, predominantemente en el campo de la quiropráctica, para describir una ligera desalineación o movimiento biomecánico anormal de una de las vértebras de la columna. Médicamente, implica una pérdida parcial del contacto en una articulación.", whatIs: { title: "¿Qué es una Subluxación Vertebral?", text: "A diferencia de una luxación completa (donde los huesos se separan totalmente por un accidente), la subluxación es una pérdida parcial de la posición de la articulación intervertebral. En el ámbito quiropráctico, se argumenta que esta desalineación menor altera la función nerviosa al interferir con las señales de la médula espinal." }, types: { title: "Ubicaciones y Conceptos", intro: "Se clasifica según el área afectada de la columna:", items: ["Subluxación cervical (en el cuello, puede causar dolores de cabeza, mareos y dolor irradiado a los hombros)", "Subluxación torácica (en la parte media de la espalda)", "Subluxación lumbar (en la espalda baja, asociada con dolores locales y dolor en piernas)"], note: "En la medicina alopática tradicional, el término se reserva para desplazamientos reales visibles en radiografías (como la espondilolistesis leve)." }, diagnosis: { title: "Evaluación Física e Imágenes", intro: "Dependiendo del enfoque (médico o quiropráctico), el diagnóstico incluye:", items: ["Examen físico (palpación de la columna buscando tensión muscular extrema, asimetría, o pérdida de rango de movimiento)", "Evaluación neurológica (verificar reflejos y fuerza para asegurar que no hay nervios atrapados)", "Radiografías de la columna (para confirmar desalineaciones estructurales o descartar fracturas o artrosis)", "Resonancia Magnética (si se sospecha que la desalineación está pellizcando la médula o causando hernias)"], note: "" }, treatment: { title: "Manejo Muscular y Articular", intro: "El tratamiento busca restaurar el movimiento y aliviar la tensión:", subsections: [ { title: "Intervenciones", items: ["Fisioterapia o terapia manual (para estirar los ligamentos, fortalecer la musculatura de soporte o 'core' y relajar la tensión)", "Manipulación o Ajuste Quiropráctico (aplicación de una fuerza controlada y rápida en la articulación para 'realinear' o restaurar la movilidad de la vértebra)", "Medicamentos (AINEs o relajantes musculares temporales para los espasmos)", "Reeducación postural para evitar la sobrecarga asimétrica crónica de la columna"] } ], note: "Mantener una buena postura y un peso saludable evita tensiones en los ligamentos vertebrales." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico traumatólogo/neurólogo?", intro: "Una desalineación dolorosa debe evaluarse urgentemente si presenta signos de daño nervioso ('banderas rojas'):", items: ["El dolor de espalda es resultado directo de un traumatismo severo (accidente de auto o caída grave)", "Sientes entumecimiento, debilidad severa, hormigueo o 'corriente eléctrica' que baja por tus brazos o piernas", "Tienes dificultades para controlar tus intestinos o la vejiga", "El dolor empeora agresivamente o se acompaña de fiebre inexplicable"] } },
'Restricción del crecimiento intrauterino' : { intro: "La restricción del crecimiento intrauterino (RCIU) es una complicación del embarazo en la cual el feto (bebé no nato) es significativamente más pequeño de lo que debería ser para su edad gestacional, debido a que no está creciendo al ritmo normal en el útero.", whatIs: { title: "¿Qué es el RCIU?", text: "Clínicamente, se diagnostica cuando el peso fetal estimado está por debajo del percentil 10. Ocurre cuando el feto no recibe el oxígeno y los nutrientes necesarios para crecer a un ritmo saludable, poniendo en riesgo el desarrollo de sus órganos y aumentando el riesgo de muerte fetal o complicaciones graves al nacer." }, types: { title: "Clasificación Fetal", intro: "Se divide en dos categorías basadas en cuándo y cómo afecta al desarrollo:", items: ["RCIU Simétrico o Primario (comienza temprano en el embarazo, todas las partes del cuerpo del feto, incluida la cabeza y el abdomen, son uniformemente pequeñas; suele deberse a anomalías genéticas o infecciones fetales como citomegalovirus)", "RCIU Asimétrico o Secundario (comienza más tarde, en el tercer trimestre; la cabeza y el cerebro crecen de tamaño normal, pero el cuerpo y el abdomen son muy pequeños; generalmente causado por problemas de la placenta o hipertensión materna)"], note: "El RCIU asimétrico es el más común y ocurre porque el feto desvía instintivamente todos los pocos nutrientes hacia el cerebro (el órgano más importante) y el corazón, 'sacrificando' el hígado y la grasa del cuerpo." }, diagnosis: { title: "Monitoreo Prenatal Estricto", intro: "El diagnóstico es ecográfico y requiere seguimiento frecuente:", items: ["Medición de la altura del fondo uterino (en las citas, el médico mide el vientre materno; si mide menos de lo esperado, levanta la sospecha)", "Ecografía fetal obstétrica (para medir exactamente la cabeza, abdomen y hueso del fémur del feto y calcular su peso estimado)", "Ecografía Doppler (fundamental para medir y observar el flujo de sangre en el cordón umbilical y en el cerebro fetal; muestra si la placenta está fallando)", "Monitorización de la frecuencia cardíaca fetal (Prueba en reposo) y evaluación del líquido amniótico"], note: "" }, treatment: { title: "Manejo Obstétrico y Parto", intro: "No existe un medicamento para hacer crecer al bebé dentro del útero; el tratamiento depende de sopesar el riesgo de mantenerlo dentro frente al riesgo de un parto prematuro:", subsections: [ { title: "Intervenciones y Decisiones", items: ["Monitoreo fetal intensivo (ecografías y doppler cada semana o dos veces por semana para asegurar que el bebé no está en sufrimiento agudo)", "Tratamiento de las enfermedades maternas subyacentes (controlar agresivamente la hipertensión, diabetes, o sugerir reposo)", "Inyecciones de corticosteroides a la madre (si se debe adelantar el parto prematuramente, para madurar rápidamente los pulmones del bebé)", "Parto inducido o cesárea de emergencia (es el tratamiento definitivo; si el Doppler indica que el flujo de sangre en el cordón umbilical es inverso o ausente, el bebé debe nacer inmediatamente para sobrevivir, incluso si es muy prematuro)"] } ], note: "Dejar de fumar y no consumir alcohol ni drogas son las medidas preventivas más importantes que puede tomar la madre." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia obstétrica?", intro: "Una madre con diagnóstico de RCIU debe acudir al hospital de inmediato si:", items: ["Nota una disminución drástica o ausencia total de los movimientos, patadas o actividad del bebé en el vientre durante el día", "Presenta dolor abdominal agudo, sangrado vaginal o rotura de membranas (romper fuente)", "Experimenta síntomas de preeclampsia severa: dolores de cabeza que no ceden, visión borrosa o hinchazón facial extrema"] } },
'Ludopatía' : { intro: "La ludopatía, también llamada trastorno por juego de apuestas o juego patológico, es un trastorno grave del control de impulsos. Consiste en la necesidad incontrolable y obsesiva de seguir apostando a pesar de los estragos económicos, sociales y psicológicos que esto causa en la vida de la persona.", whatIs: { title: "¿Qué es la Ludopatía?", text: "Es una adicción conductual reconocida oficialmente. A nivel neurológico, apostar estimula los sistemas de recompensa y dopamina del cerebro de la misma manera que lo hacen el alcohol o las drogas. El ludópata pierde la capacidad de detenerse, persiguiendo compulsivamente sus pérdidas, lo que lleva a deudas masivas y destrucción familiar." }, types: { title: "Tipos de Jugadores", intro: "Las dinámicas de la adicción varían:", items: ["Jugador de acción o escape (apuesta principalmente para evadir problemas de la vida, depresión o estrés; prefiere juegos repetitivos como las tragaperras/slots)", "Jugador de acción (apuesta por la emoción, la adrenalina y la falsa creencia de que pueden 'vencer al sistema' con sus habilidades, como en el póker o apuestas deportivas)", "Juego compulsivo progresivo (comienza ocasionalmente, pero las ganancias iniciales y luego las pérdidas desencadenan una obsesión fuera de control)"], note: "La facilidad de acceso a los casinos online y apuestas en el móvil ha convertido esta adicción en una epidemia silenciosa." }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "Se diagnostica mediante criterios clínicos psiquiátricos (DSM-5):", items: ["Evaluación clínica de la conducta de juego (el diagnóstico requiere mostrar al menos 4 comportamientos problemáticos, como mentir sobre el dinero, apostar cantidades cada vez mayores para sentir emoción, o pedir dinero prestado por desesperación)", "Evaluación de la salud mental general para detectar trastornos concurrentes y comorbilidades (el TDAH, el trastorno bipolar, la depresión y el abuso de alcohol son muy frecuentes en ludópatas)"], note: "Los pacientes mienten y ocultan patológicamente el problema, por lo que a menudo son las familias arruinadas quienes buscan el diagnóstico." }, treatment: { title: "Terapia y Reestructuración Conductual", intro: "El tratamiento requiere abstinencia total de las apuestas y reeducación mental:", subsections: [ { title: "Intervenciones Clínicas y de Apoyo", items: ["Terapia Cognitivo-Conductual (TCC) (el tratamiento psicológico principal para ayudar a cambiar los pensamientos irracionales sobre el azar y aprender a lidiar con el impulso de jugar)", "Grupos de apoyo mutuo (como Jugadores Anónimos, basados en el programa de los 12 pasos, vitales para mantener la abstinencia a largo plazo)", "Medicamentos (antidepresivos ISRS o estabilizadores del estado de ánimo pueden ayudar si hay depresión coexistente; fármacos como la Naltrexona -usados para el alcoholismo- han demostrado reducir el 'ansia' neurológica por apostar)", "Medidas de protección y bloqueo financiero (entregar el control del dinero a la pareja, autoexclusión legal y prohibición de entrada a casinos físicos y plataformas online)"] } ], note: "Tratar solo las deudas de un ludópata sin tratar la adicción garantiza que volverá a jugar y endeudarse aún más." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda profesional urgente?", intro: "La adicción al juego es una crisis vital. Busca ayuda psiquiátrica o acude a urgencias si:", items: ["Tú o tu familiar tienen pensamientos o planes de suicidio como única 'salida' a las deudas abrumadoras acumuladas", "Has cometido delitos, robos o fraudes para conseguir dinero con el cual apostar o pagar deudas de juego", "La adicción ha provocado la pérdida o puesto en grave riesgo tu empleo, tu matrimonio, tus relaciones familiares o tu vivienda", "Sientes ansiedad paralizante y ataques de pánico ante la imposibilidad de ir a jugar"] } },
'Afecciones asociadas con la ictericia' : { intro: "La ictericia es la coloración amarillenta de la piel, las membranas mucosas y la parte blanca de los ojos (esclerótica). No es una enfermedad en sí misma, sino el síntoma clínico inequívoco de que existe una enfermedad subyacente que impide al cuerpo procesar la bilirrubina.", whatIs: { title: "¿Qué provoca la Ictericia?", text: "La bilirrubina es un desecho amarillo que se produce cuando el cuerpo destruye los glóbulos rojos viejos. El hígado debe filtrar esta toxina de la sangre y enviarla al intestino a través de la bilis. La ictericia ocurre si hay destrucción masiva de sangre, si el hígado está enfermo y no puede filtrarla, o si hay un bloqueo que impide que la bilis salga hacia el intestino." }, types: { title: "Afecciones Subyacentes y Causas", intro: "Se clasifica en tres categorías según dónde ocurra el problema anatómico:", items: ["Ictericia Prehepática (antes del hígado: destrucción masiva y rápida de glóbulos rojos, como en anemias hemolíticas, malaria o incompatibilidad de grupo sanguíneo, sobrepasando la capacidad de un hígado sano)", "Ictericia Hepática (en el hígado: daño directo a las células hepáticas que les impide procesar la bilirrubina, causado por Hepatitis viral A, B o C, Cirrosis alcohólica, hígado graso severo o cáncer de hígado)", "Ictericia Poshepática u obstructiva (después del hígado: la bilis está procesada pero no puede salir; causada típicamente por cálculos biliares atascados en el conducto colédoco, cáncer de páncreas o cáncer de vías biliares)"], note: "La ictericia fisiológica del recién nacido es inofensiva y común, ya que su hígado es inmaduro; se trata con luces azules (fototerapia)." }, diagnosis: { title: "Pruebas Hepáticas y de Imagen", intro: "El médico debe localizar rápidamente el origen del bloqueo o daño:", items: ["Análisis completo de sangre (Panel hepático para medir bilirrubina directa/indirecta, enzimas ALT, AST, fosfatasa alcalina, que indicarán si el problema es del hígado o de los conductos)", "Ecografía abdominal (el primer estudio por imagen clave para detectar cálculos biliares o un páncreas inflamado)", "Tomografía computarizada (TC) o Resonancia Magnética (RM) del abdomen (para buscar tumores abdominales o pancreáticos)", "CPRE (endoscopia con rayos X) para ver y tratar directamente los conductos biliares obstruidos"], note: "" }, treatment: { title: "Tratamiento Causal", intro: "La ictericia desaparece únicamente cuando se trata y cura la enfermedad que la está provocando:", subsections: [ { title: "Intervenciones", items: ["Tratamiento Quirúrgico o Endoscópico (si la ictericia es obstructiva: extirpación de la vesícula biliar o uso de CPRE para extraer un cálculo del conducto biliar, o cirugía oncológica para tumores)", "Medicamentos antivirales o esteroides (si la causa es hepatitis viral activa o hepatitis autoinmune)", "Abstinencia total y radical de alcohol y fármacos tóxicos para el hígado", "Fototerapia (luces UV) o transfusiones de sangre (para casos graves de ictericia neonatal)"] } ], note: "La ictericia obstructiva suele acompañarse de orina muy oscura (color coñac) y heces extremadamente pálidas (color arcilla blanca)." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Cualquier aparición de ictericia en un adulto requiere evaluación médica. Acude a urgencias inmediatamente si el tinte amarillo en tu piel se acompaña de:", items: ["Dolor abdominal agudo, severo e insoportable en el lado derecho o centro del estómago", "Fiebre alta repentina y escalofríos intensos y temblorosos (signo de colangitis, una infección letal de la bilis estancada)", "Confusión mental profunda, somnolencia, desorientación o letargo (encefalopatía hepática indicando falla inminente del hígado)", "Vómitos de sangre o heces de color negro alquitranado"] } },
'Úlcera péptica' : { intro: "Una úlcera péptica es una llaga abierta, dolorosa y profunda que se desarrolla en el revestimiento interno protector del estómago (úlcera gástrica) o en la primera porción del intestino delgado (úlcera duodenal).", whatIs: { title: "¿Qué es una Úlcera Péptica?", text: "Normalmente, una gruesa capa de moco protege el estómago de sus propios ácidos corrosivos digestivos. Si esta capa mucosa se rompe o reduce, los potentes ácidos queman el tejido subyacente, formando una llaga o 'cráter'. A diferencia de un simple ardor de estómago, es una herida física real en el órgano." }, types: { title: "Causas y Ubicación", intro: "Las úlceras no son causadas por el estrés cotidiano ni por comer comida picante. Las verdaderas causas son:", items: ["Infección por la bacteria Helicobacter pylori (la causa número uno; esta bacteria vive en el moco estomacal y lo inflama y debilita hasta crear úlceras, especialmente duodenales)", "Uso crónico y abuso de analgésicos AINEs (medicamentos de venta libre como el ibuprofeno, naproxeno o aspirina tomados diariamente; bloquean las sustancias químicas que protegen el estómago de los ácidos)", "Úlcera gástrica (localizada en el estómago, el dolor suele empeorar inmediatamente después de comer al segregar ácido)", "Úlcera duodenal (localizada en el intestino delgado superior, el dolor suele aliviar temporalmente al comer, pero despierta al paciente de noche por hambre/acidez)"], note: "Fumar tabaco y beber mucho alcohol retrasan masivamente la curación de la úlcera y facilitan que la bacteria haga daño." }, diagnosis: { title: "Endoscopia y Detección de Bacterias", intro: "El gastroenterólogo requiere confirmar la presencia de la úlcera y la bacteria:", items: ["Endoscopia digestiva superior (el estándar de oro definitivo; se pasa un tubo con cámara por la garganta para ver directamente la llaga, determinar su tamaño y descartar riesgo de cáncer de estómago)", "Pruebas de H. pylori (prueba de aliento de urea, examen de antígenos en heces o análisis de la biopsia tomada durante la endoscopia; si sale positiva, debe ser aniquilada o la úlcera volverá a salir)", "Tránsito esofagogastroduodenal o Serie GI (radiografías tomando un líquido de contraste blanco de bario que hace que las úlceras se vean en los rayos X)"], note: "" }, treatment: { title: "Cura, Antibióticos y Antiácidos", intro: "Las úlceras pépticas son curables con regímenes médicos estrictos:", subsections: [ { title: "Terapias Médicas Combinadas", items: ["Terapia de Erradicación (si se confirma H. pylori, se requiere un ciclo muy agresivo de dos o tres antibióticos diferentes tomados al mismo tiempo durante 14 días para matar la bacteria)", "Inhibidores de la Bomba de Protones (IBP) (medicamentos como el omeprazol o pantoprazol, el pilar curativo: bloquean la producción de ácido del estómago casi por completo, dándole a la llaga las semanas que necesita para cerrarse y sanar)", "Protectores de la mucosa gástrica (medicamentos como el sucralfato, que cubren y 'parchan' físicamente la úlcera para protegerla de la irritación ácida)", "Suspensión inmediata de los AINEs (si tomas ibuprofeno o aspirina por dolor, tu médico te los cambiará por paracetamol, que no daña el estómago)", "Cirugía de emergencia (solo si la úlcera es tan profunda que perfora el estómago, haciendo un agujero, o sangra profusamente y no se puede cauterizar con el endoscopio)"] } ], note: "Ignorar el tratamiento de una úlcera puede provocar que perfore y haga un agujero total en el estómago (peritonitis), lo cual es mortal." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia?", intro: "Una úlcera sangrante es una urgencia de vida o muerte. Acude al hospital si experimentas:", items: ["Vómitos repetitivos de sangre roja brillante, o que tienen el aspecto exacto de 'posos o granos de café' oscuros", "Evacuación de heces extremadamente negras, pegajosas y como alquitrán (señal de sangre antigua digerida desde el estómago)", "Dolor abdominal repentino, agudo, insoportable e incesante, con el estómago duro y rígido como una tabla (posible úlcera perforada)", "Mareo extremo, debilidad paralizante al levantarse, dificultad para respirar y desmayos (signos de pérdida masiva de sangre interna)"] } },
'Defensas bajas' : { intro: "Las defensas bajas, o inmunodeficiencia, ocurren cuando el sistema inmunológico del cuerpo no funciona adecuadamente, dejando a la persona altamente vulnerable a infecciones frecuentes, inusuales o más graves de lo normal.", whatIs: { title: "¿Qué son las Defensas Bajas?", text: "Es un estado clínico en el que la respuesta inmunitaria está comprometida. Puede ser primaria (presente desde el nacimiento por defectos genéticos) o secundaria (adquirida a lo largo de la vida debido a desnutrición, virus como el VIH, cáncer, quimioterapia, o estrés crónico extremo)." }, types: { title: "Tipos de Inmunodeficiencia", intro: "Se dividen según su origen:", items: ["Inmunodeficiencias primarias (enfermedades genéticas raras que afectan el desarrollo del sistema inmune desde la infancia)", "Inmunodeficiencias secundarias (causadas por factores externos: medicamentos inmunosupresores, edad avanzada, infecciones virales, diabetes mal controlada)"], note: "El estrés prolongado y la falta crónica de sueño suprimen temporalmente, pero de forma severa, la función inmunológica." }, diagnosis: { title: "Evaluación Médica", intro: "El inmunólogo o médico general evaluará el conteo celular y de anticuerpos:", items: ["Hemograma completo (análisis de sangre para medir los niveles de glóbulos blancos)", "Prueba de niveles de inmunoglobulinas (para ver si el cuerpo produce suficientes anticuerpos)", "Pruebas de VIH o hepatitis", "Evaluación clínica del historial de infecciones del último año"], note: "" }, treatment: { title: "Fortalecimiento y Tratamiento Médico", intro: "Depende estrictamente de la causa de la debilidad inmunológica:", subsections: [ { title: "Opciones Terapéuticas", items: ["Tratamiento de la causa subyacente (controlar la diabetes, terapia antirretroviral para VIH)", "Antibióticos y antifúngicos profilácticos (para prevenir infecciones antes de que ocurran en pacientes de alto riesgo)", "Terapia de reemplazo de inmunoglobulinas (infusiones de anticuerpos intravenosos para quienes no pueden producirlos)", "Cambios radicales en estilo de vida (dieta rica en micronutrientes, sueño profundo y reducción de estrés)"] } ], note: "Las vacunas con virus vivos atenuados pueden ser peligrosas para personas con inmunosupresión severa." }, whenToSeekHelp: { title: "¿Cuándo acudir a un especialista?", intro: "Debes buscar evaluación inmunológica si en el transcurso de un año presentas:", items: ["Infecciones recurrentes que no mejoran con dos o más ciclos de antibióticos", "Neumonías frecuentes, bronquitis crónica o infecciones de los senos paranasales recurrentes", "Aparición de infecciones inusuales u oportunistas (infecciones por hongos crónicas en la boca o piel)", "Necesidad de recibir antibióticos por vía intravenosa para curar infecciones comunes"] } },
'Síndrome de apnea obstructiva del sueño' : { intro: "El Síndrome de Apnea Obstructiva del Sueño (SAOS) es un trastorno respiratorio grave en el cual la respiración se detiene y se reanuda repetidamente durante el descanso nocturno, arruinando la calidad del sueño.", whatIs: { title: "¿Qué es el SAOS?", text: "Ocurre cuando los músculos de la parte posterior de la garganta se relajan excesivamente al dormir, causando que la vía respiratoria colapse o se bloquee por completo. El cerebro detecta la falta de oxígeno y provoca un microdespertar para forzar un jadeo o ronquido explosivo que reabre la garganta; esto puede suceder cientos de veces por noche." }, types: { title: "Clasificación de Severidad", intro: "Se mide mediante el Índice de Apnea-Hipopnea (IAH), que cuenta los bloqueos por hora:", items: ["Leve (5 a 14 pausas respiratorias por hora)", "Moderada (15 a 30 pausas por hora)", "Severa (más de 30 pausas por hora; el paciente pasa una gran parte de la noche asfixiándose brevemente)"], note: "El sobrepeso y tener un cuello ancho son los factores de riesgo anatómico más grandes, aunque personas delgadas también pueden padecerla." }, diagnosis: { title: "Estudios del Sueño", intro: "La apnea no puede diagnosticarse despierto, requiere monitorización nocturna:", items: ["Polisomnografía en laboratorio (el estudio de oro; el paciente duerme en una clínica conectado a sensores de ondas cerebrales, oxígeno, ritmo cardíaco y movimiento)", "Poligrafía respiratoria domiciliaria (un monitor portátil que se usa en casa para medir oxígeno y flujo de aire; útil para casos evidentes)"], note: "Quien sufre la apnea rara vez recuerda los ahogos; casi siempre es la pareja de cama quien da la voz de alarma." }, treatment: { title: "Soporte Respiratorio", intro: "Es una condición muy tratable que devuelve inmediatamente la energía diurna:", subsections: [ { title: "Opciones de Intervención", items: ["Presión Positiva Continua en las Vías Respiratorias (CPAP) (el tratamiento principal; una mascarilla que empuja aire a presión para mantener la garganta abierta)", "Pérdida de peso significativa (puede curar la afección si está causada por obesidad)", "Dispositivos de avance mandibular (férulas dentales para adelantar la mandíbula inferior en apneas leves)", "Cirugía maxilofacial o de paladar (solo si el paciente no tolera la CPAP y hay anomalías estructurales graves)"] } ], note: "La apnea no tratada multiplica el riesgo de sufrir hipertensión refractaria, infartos de miocardio y accidentes cerebrovasculares." }, whenToSeekHelp: { title: "¿Cuándo consultar al neumólogo o especialista del sueño?", intro: "Es crucial buscar diagnóstico médico si:", items: ["Tus ronquidos son tan fuertes que interrumpen el sueño de tu pareja", "Te despiertas a menudo con una sensación de asfixia, jadeo brusco o corazón acelerado", "Experimentas una somnolencia diurna paralizante (te quedas dormido involuntariamente mientras trabajas o conduces)", "Te levantas sistemáticamente con dolor de cabeza, boca muy seca y cambios de humor severos"] } },
'Lesiones de Lefort' : { intro: "Las lesiones de Le Fort son patrones clásicos de fracturas complejas, severas y de alta energía en los huesos del tercio medio facial (el maxilar superior y la cara). Son emergencias de cirugía maxilofacial generalmente causadas por traumatismos contundentes masivos.", whatIs: { title: "¿Qué son las Fracturas de Le Fort?", text: "Son líneas de fractura que separan, en diferentes niveles, el maxilar superior del resto del cráneo, descritas inicialmente por el cirujano René Le Fort. Ocurren debido a impactos violentos de frente, como los que se sufren en accidentes automovilísticos sin cinturón de seguridad, agresiones con objetos contundentes o caídas de gran altura." }, types: { title: "Clasificación de Le Fort", intro: "Se dividen en tres grados según la altura de la fractura en el rostro:", items: ["Le Fort I (Fractura horizontal, 'paladar flotante': separa los dientes superiores y el paladar duro del resto del maxilar)", "Le Fort II (Fractura piramidal: abarca los dientes, los huesos nasales y la parte inferior de las órbitas oculares; el centro del rostro se hunde)", "Le Fort III (Disyunción craneofacial completa: la fractura atraviesa las órbitas de los ojos, separando literalmente toda la cara de la base del cráneo; muy grave)"], note: "Es común que un paciente presente diferentes tipos de Le Fort en cada lado del rostro simultáneamente." }, diagnosis: { title: "Evaluación Maxilofacial de Urgencia", intro: "Debido a la gravedad, la prioridad es asegurar que el paciente pueda respirar:", items: ["Evaluación primaria de trauma (asegurar vía aérea, ya que los huesos rotos pueden bloquear la garganta)", "Tomografía Computarizada (TC) maxilofacial y craneal con reconstrucción 3D (el estándar absoluto para ver con precisión las líneas de fractura antes de operar)", "Examen físico buscando el signo clínico característico de movilidad: el cirujano sostiene la cabeza e intenta mover los dientes superiores para ver si el rostro 'flota'"], note: "" }, treatment: { title: "Fijación y Reconstrucción Quirúrgica", intro: "El objetivo es restaurar la anatomía de la cara, la oclusión dental y la visión:", subsections: [ { title: "Pasos Quirúrgicos", items: ["Intubación o traqueostomía de emergencia si la vía aérea está colapsada", "Reducción abierta y fijación interna (RAFI) (la cirugía definitiva donde se exponen los huesos rotos y se unen de forma rígida usando miniplacas y tornillos de titanio permanentes)", "Fijación intermaxilar (bloqueo de la mandíbula con alambres temporalmente para asegurar que los dientes encajen perfectamente al sanar)"] } ], note: "La presencia de un 'ojo morado de mapache' bilateral a menudo indica fracturas profundas en la base del cráneo asociadas." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia de vida o muerte?", intro: "Cualquier impacto de alta energía en el rostro requiere ir al hospital en ambulancia, especialmente si:", items: ["Hay sangrado nasal o bucal profuso e incontrolable", "La persona tiene dificultad para respirar o tragar, o pierde el conocimiento", "El rostro parece visiblemente aplanado, alargado o deforme (cara de 'plato')", "Los dientes superiores no encajan con los inferiores al cerrar la boca, o hay pérdida de visión/visión doble", "Gotea un líquido transparente e incoloro por la nariz (podría ser líquido cefalorraquídeo escapando del cerebro)"] } },
'Molusco contagioso' : { intro: "El molusco contagioso es una infección cutánea viral frecuente y benigna que causa la aparición de pequeñas protuberancias o nódulos (pápulas) en la piel. Es muy común en niños pequeños, pero puede afectar a adultos.", whatIs: { title: "¿Qué es el Molusco Contagioso?", text: "Es provocado por un poxvirus. Las lesiones son pequeñas (del tamaño de una cabeza de alfiler o un guisante), de color perla o piel, y tienen un característico 'hoyuelo' u ombligo en el centro. Se transmite fácilmente por contacto directo de piel a piel o tocando objetos contaminados (toallas, juguetes)." }, types: { title: "Presentación según Edad", intro: "La ubicación de los moluscos indica su modo de transmisión:", items: ["En niños (aparecen típicamente en la cara, cuello, axilas y brazos, contagiados al jugar o en piscinas)", "En adultos (generalmente se considera una Infección de Transmisión Sexual si aparecen en el abdomen bajo, pubis, genitales o cara interna de los muslos)", "En personas inmunodeprimidas (como pacientes con VIH; las lesiones son gigantes, muy numerosas y resistentes al tratamiento)"], note: "Rara vez causan dolor, pero pueden picar severamente." }, diagnosis: { title: "Inspección Dermatológica", intro: "Es un diagnóstico rápido de consultorio:", items: ["Examen físico visual (el dermatólogo reconoce de inmediato la forma de cúpula con el hoyuelo central)", "Biopsia de piel o raspado (muy infrecuente, usado solo si las lesiones son atípicas para descartar verrugas genitales u otros problemas cutáneos)"], note: "" }, treatment: { title: "Manejo y Destrucción Local", intro: "En niños sanos, el cuerpo suele eliminar el virus solo (tarda de 6 meses a 2 años). Si se requiere tratamiento:", subsections: [ { title: "Procedimientos", items: ["Crioterapia (congelar y destruir cada bultito con nitrógeno líquido)", "Curetaje (el médico raspa físicamente el núcleo blanco del molusco con un instrumento afilado bajo anestesia local)", "Terapias tópicas (aplicación en clínica de cantaridina -el 'jugo de escarabajo'- que crea una ampolla para levantar el molusco, o cremas recetadas en casa como podofilotoxina o imiquimod)"] } ], note: "Rascar las lesiones hace que el virus se esparza en forma de línea hacia otras áreas del cuerpo y aumenta el riesgo de infección bacteriana con pus." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "Debes buscar evaluación médica si:", items: ["Los bultos aparecen en el área genital de un adulto (requiere tratamiento para no contagiar a las parejas)", "Las lesiones se vuelven muy rojas, calientes, dolorosas o supuran pus (señal de que se han infectado con bacterias por rascarse)", "El sarpullido se está propagando rápidamente por el cuerpo, causando gran incomodidad estética o picor severo"] } },
'Embarazo abdominal' : { intro: "El embarazo abdominal es una forma excepcionalmente rara y extremadamente peligrosa de embarazo ectópico en el cual el embrión se implanta y se desarrolla fuera del útero y de las trompas de Falopio, directamente dentro de la cavidad abdominal (peritoneal) de la madre.", whatIs: { title: "¿Qué es un Embarazo Abdominal?", text: "Normalmente, un óvulo fecundado se adhiere dentro del útero. En un embarazo abdominal, la placenta trata de encontrar suministro de sangre adhiriéndose agresivamente a los órganos abdominales internos de la madre, como los intestinos, el hígado o el epiplón. Esto plantea un riesgo catastrófico de hemorragia masiva si la placenta se desprende o si los órganos se rompen por el crecimiento fetal." }, types: { title: "Clasificación de Origen", intro: "Se clasifica según cómo llegó el embrión al abdomen:", items: ["Embarazo abdominal primario (muy raro; el óvulo fue fertilizado e inmediatamente se implantó en el abdomen sin entrar jamás a las trompas)", "Embarazo abdominal secundario (el más común; comenzó como un embarazo ectópico en la trompa de Falopio, la cual se rompió, expulsando al embrión al abdomen donde se re-implantó en los intestinos)"], note: "A diferencia de otros embarazos ectópicos, a veces el feto puede sobrevivir semanas o meses, pero el riesgo de muerte súbita para la madre es prohibitivo." }, diagnosis: { title: "Diagnóstico Clínico y Ecográfico Fino", intro: "Suele ser muy difícil de diagnosticar tempranamente y a menudo se descubre por complicaciones:", items: ["Ecografía transvaginal y abdominal (puede mostrar un útero vacío mientras el feto se observa flotando entre los intestinos o cerca del hígado)", "Resonancia Magnética (RM) pélvica/abdominal (vital para planificar la cirugía; muestra exactamente a qué órganos vitales está adherida y conectada la placenta)", "Niveles de hCG (hormona del embarazo) anormales o que no suben como deberían", "Dolor severo materno al moverse, o sensación de que los movimientos fetales son 'demasiado superficiales' justo bajo la piel"], note: "" }, treatment: { title: "Cirugía de Emergencia y Control de Hemorragia", intro: "El tratamiento requiere la finalización inmediata del embarazo mediante cirugía mayor; no es seguro continuarlo:", subsections: [ { title: "Abordaje Quirúrgico Crítico", items: ["Laparotomía exploratoria urgente (cirugía abierta del abdomen para extraer al feto antes de que ocurra una rotura mortal)", "Manejo de la placenta (el mayor desafío: si la placenta está fuertemente adherida a los intestinos o vasos sanguíneos mayores, intentar arrancarla causará una hemorragia masiva y letal; los cirujanos frecuentemente dejan la placenta adentro y ligan su suministro de sangre para que el cuerpo la absorba lentamente durante meses)", "Medicamentos (se usa Metotrexato si parte de la placenta se deja en el cuerpo para ayudar a destruir ese tejido restante)", "Transfusiones de sangre masivas preparadas en quirófano"] } ], note: "Es una de las emergencias obstétricas más complejas; la supervivencia de la madre depende de la cirugía en un hospital de alto nivel." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia obstétrica inminente?", intro: "Llama a urgencias o dirígete de inmediato al hospital si estás embarazada y experimentas:", items: ["Dolor abdominal súbito, extremadamente agudo y severo que se irradia a la punta del hombro (signo clásico de sangrado interno en el abdomen)", "Sangrado vaginal anormal acompañado de cólicos intensos", "Mareos severos repentinos, palidez extrema, pulso rápido, debilidad profunda o desmayos (síntomas directos de shock hemorrágico)"] } },
'Tos crónica' : { intro: "La tos crónica es una tos molesta y constante que dura ocho semanas o más en los adultos, o cuatro semanas en los niños. Más que una enfermedad en sí misma, es un síntoma de alarma persistente de un problema respiratorio, digestivo o ambiental subyacente.", whatIs: { title: "¿Qué es la Tos Crónica?", text: "La tos es un reflejo protector normal para limpiar las vías respiratorias. Sin embargo, cuando se vuelve crónica, indica una irritación perpetua. Interrumpe severamente el sueño, causa agotamiento físico, dolor en el pecho, ronquera e incluso pérdida del control de la vejiga debido al esfuerzo constante." }, types: { title: "Causas Primarias", intro: "En más del 90% de los casos no fumadores, se debe a una de estas tres causas:", items: ["Síndrome de goteo posnasal (mucosidad de las alergias o sinusitis que gotea por la parte posterior de la garganta, irritándola constantemente)", "Asma (especialmente el 'asma variante de tos', donde la tos seca es el único síntoma sin que haya sibilancias)", "Reflujo Gastroesofágico o ERGE (los ácidos del estómago suben al esófago y a veces a la garganta o pulmones, provocando un reflejo de tos irritativa, a menudo sin sentir ardor estomacal)"], note: "El tabaquismo y los medicamentos para la presión arterial (inhibidores de la ECA, como el enalapril) son también culpables directos frecuentes." }, diagnosis: { title: "Investigación Neumológica y Alergológica", intro: "Para detener la tos, el médico debe encontrar su origen:", items: ["Radiografía de tórax o Tomografía (TC) (para descartar problemas mortales como cáncer de pulmón o fibrosis antes de buscar causas simples)", "Espirometría y pruebas de función pulmonar (para detectar asma o EPOC)", "Pruebas de alergia y evaluación de senos paranasales (para rinitis o goteo posnasal)", "pH-metría esofágica de 24 horas (un sensor mide si sube ácido desde el estómago al esófago)"], note: "" }, treatment: { title: "Tratamiento Causal", intro: "La tos crónica solo se cura atacando la enfermedad base; los jarabes para la tos rara vez funcionan:", subsections: [ { title: "Enfoques de Tratamiento", items: ["Para Goteo Posnasal: Antihistamínicos orales, descongestionantes o corticosteroides nasales en aerosol para detener la mucosidad.", "Para Asma: Inhaladores con broncodilatadores y corticosteroides para desinflamar los bronquios.", "Para Reflujo Ácido: Inhibidores de la bomba de protones (Omeprazol), comer comidas más pequeñas y no acostarse hasta 3 horas después de cenar.", "Para medicamentos: El médico cambiará el antihipertensivo IECA por otro fármaco de una familia diferente.", "Dejar de fumar y evitar la exposición al humo ambiental."] } ], note: "Suprimir una tos crónica con codeína o pastillas fuertes sin buscar la causa puede encubrir una enfermedad grave en avance." }, whenToSeekHelp: { title: "¿Cuándo es un síntoma de alerta roja?", intro: "Consulta a un médico sin demora si la tos no desaparece tras un mes, y acude a URGENCIAS si la tos:", items: ["Expulsa flemas que contienen hilos de sangre roja, coágulos oscuros o esputo de un color rosa espumoso", "Se acompaña de una dificultad evidente y angustiante para respirar o dolor en el pecho constante", "Está asociada con pérdida de peso no intencionada, sudores empapadores nocturnos o fiebre alta (podría indicar tuberculosis o cáncer)", "Provoca que te ahogues, vomites o te desmayes por la intensidad del ataque"] } },
'Angina estable' : { intro: "La angina estable (o angina de pecho crónica) es un síndrome doloroso y recurrente en el pecho que se desencadena de forma predecible por el esfuerzo físico o el estrés emocional fuerte, y se alivia rápidamente al descansar o con medicación.", whatIs: { title: "¿Qué es la Angina Estable?", text: "Es el síntoma clásico de la enfermedad de las arterias coronarias. Debido a la acumulación de placas de colesterol (aterosclerosis), las arterias del corazón están parcialmente bloqueadas. En reposo, la sangre fluye bien, pero cuando caminas rápido, subes escaleras o te enojas, el corazón exige más oxígeno del que las tuberías estrechas pueden proveer, generando el dolor de advertencia (isquemia)." }, types: { title: "Diferenciación de Gravedad", intro: "Es fundamental distinguir su patrón frente a las emergencias:", items: ["Angina estable (es predecible, los episodios son similares, dura menos de 5 minutos, aparece con el ejercicio y cede al descansar o usar nitroglicerina)", "Angina inestable (ES UNA URGENCIA: aparece en total reposo, dura más de 15 minutos, es un dolor nuevo o más fuerte y no se alivia con pastillas; precede a un infarto inminente)", "Angina de Prinzmetal (ocurre en reposo a medianoche o madrugada debido a un espasmo puro de la arteria, no siempre por colesterol)"], note: "El dolor a menudo se describe más como una opresión, pesadez o 'un elefante sentado en el pecho' que como un dolor punzante." }, diagnosis: { title: "Evaluación Cardiológica", intro: "El cardiólogo necesita medir cuánta sangre le falta al corazón durante el esfuerzo:", items: ["Electrocardiograma (ECG) en reposo (a menudo sale normal si no hay dolor en ese momento)", "Prueba de esfuerzo física o farmacológica (caminar en cinta o usar medicamentos para acelerar el corazón mientras se monitoriza si el ECG muestra falta de oxígeno)", "Ecocardiograma de estrés (ultrasonido del corazón antes y después del esfuerzo)", "Angiografía coronaria / Cateterismo (la prueba de oro; se inyecta tinte en las arterias del corazón por un tubo desde la muñeca para ver exactamente dónde y qué tan grave es el bloqueo)"], note: "" }, treatment: { title: "Manejo Médico y Revascularización", intro: "El objetivo es prevenir un ataque cardíaco fatal y eliminar el dolor diario:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos de alivio rápido (Nitroglicerina sublingual o en spray, ensancha las arterias casi al instante deteniendo el dolor en minutos)", "Fármacos preventivos crónicos (Betabloqueantes para ralentizar el corazón, estatinas para frenar el colesterol, y aspirina diaria para evitar coágulos mortales sobre la placa)", "Modificación estricta de vida (dejar de fumar es el paso más crítico, además de controlar agresivamente diabetes e hipertensión)", "Intervenciones invasivas (si las medicinas no funcionan o el bloqueo es mortal: Angioplastia y colocación de un stent de malla metálica para mantener la arteria abierta, o Cirugía de Bypass de corazón abierto)"] } ], note: "Una persona diagnosticada siempre debe llevar su pastilla de nitroglicerina consigo." }, whenToSeekHelp: { title: "¿Cuándo se convierte en una Emergencia por Infarto (Llamar 911)?", intro: "La angina estable puede transformarse en un ataque cardíaco mortal. Pide una ambulancia de inmediato si:", items: ["El dolor o la opresión en el pecho aparece sorpresivamente mientras estás sentado en reposo absoluto o durmiendo", "El dolor dura más de 10-15 minutos y es notablemente más severo de lo habitual", "El dolor no desaparece en absoluto tras haber descansado y haber tomado tus dosis de emergencia de nitroglicerina (espaciadas cada 5 minutos)", "El dolor se irradia hacia tu mandíbula inferior, el cuello, la espalda o todo el brazo izquierdo, acompañado de sudoración fría, náuseas extremas o sensación inminente de muerte"] } },
'Colangitis' : { intro: "La colangitis es una infección bacteriana severa y aguda de los conductos biliares (los tubos que transportan la bilis desde el hígado y la vesícula biliar hacia el intestino). Es una emergencia médica grave que puede llevar a sepsis mortal en cuestión de horas si no se trata.", whatIs: { title: "¿Qué es la Colangitis Aguda?", text: "Se desarrolla cuando existe una obstrucción física en el conducto biliar común (coledoco). Al no poder fluir hacia el intestino, la bilis se estanca y la presión aumenta drásticamente. Las bacterias del intestino suben hacia este líquido estancado, multiplicándose rápidamente y entrando al torrente sanguíneo general del paciente." }, types: { title: "Causas de la Obstrucción", intro: "Para que haya infección, primero debe haber un bloqueo. Las causas incluyen:", items: ["Cálculos biliares (la causa más común en un 80% de los casos; una piedra escapa de la vesícula y atasca el conducto principal)", "Tumores malignos (cáncer de las vías biliares, cáncer de cabeza de páncreas o cáncer de vesícula que aplastan el conducto)", "Estenosis o cicatrices benignas (estrechamiento del tubo por cirugías previas o inflamación crónica)", "Parásitos o gusanos en los conductos biliares (más común en ciertas zonas de Asia)"], note: "Existe una variante autoinmune crónica llamada Colangitis Biliar Primaria, pero es una enfermedad lenta y distinta de la colangitis aguda infecciosa." }, diagnosis: { title: "Detección de Emergencia Hospitalaria", intro: "El diagnóstico debe ser muy rápido. Se sospecha clínicamente por la 'Tríada de Charcot':", items: ["Tríada de Charcot clásica: 1. Dolor intenso en lado derecho superior del abdomen. 2. Fiebre alta y escalofríos. 3. Ictericia (piel y ojos amarillos)", "Análisis de sangre urgentes (mostrarán leucocitos elevadísimos por la infección, y bilirrubina y enzimas hepáticas disparadas por el bloqueo)", "Ecografía abdominal o Tomografía Computarizada (TC) (para visualizar el conducto dilatado y confirmar si hay piedras o tumores bloqueando)", "Colangiopancreatografía por Resonancia Magnética (CPRM) (imágenes 3D detalladas de los conductos)"], note: "" }, treatment: { title: "Descompresión Biliar y Antibióticos", intro: "El paciente debe ser ingresado al hospital, a menudo en cuidados intensivos. El tratamiento es doble:", subsections: [ { title: "Rescate Médico", items: ["Antibióticos intravenosos de amplio espectro inmediatos (para combatir la sepsis en sangre y estabilizar al paciente)", "Fluidos intravenosos (IV) y estabilización de la presión arterial y signos vitales", "Drenaje biliar urgente mediante CPRE (el tratamiento definitivo de oro: un gastroenterólogo introduce un tubo por la boca hasta el conducto obstruido, corta el esfínter y extrae el cálculo biliar o coloca un tubo (stent) para que el pus y la bilis salgan y el hígado se salve)", "Drenaje transhepático percutáneo (si la CPRE falla, un radiólogo clava una aguja por el lado del cuerpo directo al hígado para drenar la bilis externamente)", "Extirpación de la vesícula (Colecistectomía) días después de superar la infección, para prevenir que bajen nuevas piedras"] } ], note: "Sin un drenaje físico (desatascar el tubo), los antibióticos por sí solos casi nunca pueden curar la infección purulenta atrapada." }, whenToSeekHelp: { title: "¿Cuándo ir directamente a Urgencias Médicas?", intro: "La colangitis es potencialmente fatal. Ve a emergencias o llama al 911 al instante si presentas la combinación de:", items: ["Dolor severo e intermitente en la parte superior derecha del abdomen, justo debajo de las costillas", "Aparición repentina de fiebre superior a 38.5 °C con escalofríos intensos o temblores en el cuerpo", "Tu piel y el blanco de tus ojos adquieren un tono amarillento evidente (ictericia)", "Muestras signos de shock: confusión mental aguda, somnolencia profunda, letargo extremo o presión arterial muy baja (Pentada de Reynolds, signo de extrema gravedad)"] } },
'Infección recurrente de las vías urinarias' : { intro: "Las infecciones recurrentes de las vías urinarias (IVU recurrentes o cistitis de repetición) son una condición frustrante en la que una persona sufre de dolorosas infecciones de vejiga de forma repetitiva. Se define clínicamente como tener dos o más infecciones confirmadas en seis meses, o tres o más en un año.", whatIs: { title: "¿Qué son las IVU Recurrentes?", text: "Afectan abrumadoramente a las mujeres debido a la corta longitud de su uretra. Se producen cuando bacterias perjudiciales (típicamente Escherichia coli del intestino) entran reiteradamente a la vejiga. En lugar de ser un evento aislado, el tracto urinario de la paciente se vuelve altamente susceptible a continuos ataques." }, types: { title: "Tipos de Recurrencia", intro: "Los médicos clasifican las repeticiones para saber cómo atacarlas:", items: ["Reinfección (representa el 80% de los casos: la infección anterior se curó completamente, pero una nueva bacteria externa subió por la uretra y comenzó una infección desde cero semanas después)", "Recaída (la misma cepa de bacteria original nunca murió del todo con los antibióticos anteriores, se escondió en las paredes de la vejiga -formando biopelículas- o riñones, y volvió a multiplicarse días después)"], note: "En mujeres sanas premenopáusicas, el desencadenante más fuerte de las reinfecciones son las relaciones sexuales." }, diagnosis: { title: "Investigación Urológica", intro: "Para las infecciones crónicas, no basta con una tira de orina de farmacia. Se requieren pruebas precisas:", items: ["Urocultivo o cultivo de orina formal obligatorio (para confirmar si hay bacterias reales o si el dolor es causado por otro síndrome, y para que el laboratorio pruebe exactamente qué antibiótico mata a esa cepa específica resistente)", "Ecografía de riñones y vejiga (para confirmar que la vejiga se vacía por completo y descartar la presencia de piedras que alberguen bacterias)", "Cistoscopia (si las infecciones son graves o con sangre; el urólogo introduce una pequeña cámara en la vejiga para buscar pólipos, divertículos o tumores ocultos)"], note: "" }, treatment: { title: "Prevención, Profilaxis y Hormonas", intro: "El tratamiento se aleja de dar antibióticos aleatorios cada vez, enfocándose en la prevención sistemática:", subsections: [ { title: "Terapias de Mantenimiento", items: ["Profilaxis antibiótica poscoital (si el sexo es el desencadenante, tomar una única pastilla pequeña de antibiótico recetado inmediatamente después del coito)", "Profilaxis continua en dosis bajas (tomar una dosis mínima de antibiótico todas las noches durante 6 a 12 meses para 'esterilizar' la vejiga a largo plazo y romper el ciclo)", "Terapia de estrógenos vaginales en crema o anillo (vital para mujeres en la menopausia; el estrógeno fortalece y engrosa la piel de la vagina y uretra, creando una barrera biológica contra las bacterias y restaurando el lactobacillus bueno)", "Suplementos de prevención (D-manosa, un tipo de azúcar que engaña a la E. coli para que no se pegue a la vejiga, y extractos concentrados de arándano rojo)", "Aumento radical de agua diaria y no posponer jamás las ganas de orinar"] } ], note: "La limpieza y limpieza de la zona íntima en mujeres debe ser siempre rigurosamente de adelante hacia atrás tras ir al baño para evitar arrastrar heces." }, whenToSeekHelp: { title: "¿Cuándo es imperativo acudir a un Urólogo?", intro: "Deja de automedicarte con remedios de farmacia. Busca a un especialista si:", items: ["Sufres más de tres episodios dolorosos al orinar en un solo año", "Tus síntomas de ardor y urgencia no desaparecen a los 2 o 3 días de haber iniciado el tratamiento con un antibiótico recetado", "El dolor urinario se acompaña súbitamente de fiebre, dolor fuerte en la espalda baja (zona lumbar), náuseas y escalofríos (esto indica que la infección escapó de la vejiga y llegó a los riñones -pielonefritis-, una emergencia médica)", "Ves sangre roja brillante visible o coágulos constantes en la orina"] } },
'Displasia congénita de la cadera' : { intro: "La displasia del desarrollo de la cadera (DDC) es una afección que ocurre cuando la articulación de la cadera de un bebé no se forma adecuadamente. En una cadera sana, la cabeza redondeada del fémur encaja firmemente en la cavidad de la pelvis; en la displasia, esta cavidad es demasiado plana o poco profunda.", whatIs: { title: "¿Qué es la Displasia de Cadera?", text: "Es una inestabilidad articular presente al nacer o desarrollada en los primeros meses de vida. La cabeza del fémur puede estar suelta (pudiendo salirse de su sitio y volver a entrar), o puede estar completamente dislocada y fuera del acetábulo. Si no se corrige a tiempo, causará cojera severa, dolor y artritis prematura y destructiva en la vida adulta joven." }, types: { title: "Grados de Severidad", intro: "Se clasifica según cuán suelta esté la articulación:", items: ["Cadera luxada (el grado más grave, la cabeza del fémur está totalmente fuera de la cavidad en reposo)", "Cadera luxable (la cadera está en su sitio, pero puede ser empujada o dislocada fácilmente hacia afuera durante el examen médico)", "Cadera subluxable o displásica (la cabeza del fémur está en su sitio, pero no encaja bien porque la cavidad es muy plana, rozando anormalmente)"], note: "Es más común en niñas, en bebés que vienen de nalgas (posición podálica) durante el parto, en el primer hijo, o si hay antecedentes familiares de la afección." }, diagnosis: { title: "Evaluación Pediátrica Temprana", intro: "La detección oportuna en los primeros meses es vital para evitar cirugías mayores:", items: ["Examen físico neonatal (el pediatra realiza las maniobras de Ortolani y Barlow: flexiona y abre las caderas del recién nacido buscando sentir o escuchar un 'clic' o 'chasquido' que indica que el hueso entra o sale)", "Ecografía de cadera (la prueba de imagen de elección para bebés menores de 4-6 meses, ya que sus caderas aún son de cartílago blando y no se ven en radiografías; recomendada por precaución si el bebé venía de nalgas)", "Radiografía pélvica (utilizada después de los 6 meses de edad, cuando los huesos de la cadera ya han comenzado a calcificarse y son visibles)"], note: "" }, treatment: { title: "Corrección Ortopédica y Arnés", intro: "El tratamiento temprano aprovecha el rápido crecimiento del bebé para 'moldear' la cadera en la forma correcta sin operar:", subsections: [ { title: "Fases de Tratamiento", items: ["Arnés de Pavlik (en bebés menores de 6 meses; un dispositivo de correas blandas que mantiene las piernas del bebé separadas y flexionadas como una rana durante meses, forzando a la cabeza del fémur a descansar profundo en la cavidad y estimular su correcta formación; tiene una eficacia altísima)", "Reducción cerrada bajo anestesia (para bebés mayores de 6 meses o si el arnés falla; el cirujano manipula el hueso hacia su lugar en quirófano y coloca al bebé en una escayola o yeso corporal rígido -yeso espica- durante varios meses)", "Reducción abierta quirúrgica (si el niño es mayor de 18 meses o el hueso no entra; se opera abriendo la cadera para limpiar tejidos y reubicar el fémur de forma permanente, a menudo requiriendo cortar y reposicionar el hueso pélvico)"] } ], note: "Envolver o fajar a los bebés con las piernas rectas y apretadas (swaddling estricto) aumenta enormemente el riesgo de dislocarles las caderas." }, whenToSeekHelp: { title: "¿Cuándo sospechar y alertar al pediatra?", intro: "Es fundamental que el médico revise al bebé si notas asimetrías:", items: ["Una de las piernas del bebé parece notablemente más corta que la otra", "Los pliegues de grasa en la piel de los muslos o nalgas del bebé son desiguales (hay más pliegues de un lado que del otro)", "Notas una disminución de la movilidad o que el bebé mueve menos una pierna que la otra, o hace un ruido de chasquido constante al cambiarle el pañal", "En un niño más mayor o que ya camina: notas que cojea, camina como un pato (marcha de ánade) o camina sobre las puntas de los pies en una sola pierna"] } },
'Encefalopatía hepática' : { intro: "La encefalopatía hepática es un síndrome de declive neurológico y psiquiátrico grave que ocurre en personas con enfermedad del hígado avanzada o cirrosis severa. Provoca confusión intensa, alteración de la personalidad e incluso la entrada en estado de coma.", whatIs: { title: "¿Qué es la Encefalopatía Hepática?", text: "Es una intoxicación del cerebro. Cuando el hígado falla y ya no puede filtrar las toxinas absorbidas de los intestinos (especialmente el amoníaco derivado de las proteínas), estos potentes venenos metabólicos evaden el filtro hepático y viajan libremente por el torrente sanguíneo hacia el cerebro. Las toxinas interrumpen la función celular cerebral y causan hinchazón, apagando la conciencia de la persona." }, types: { title: "Grados de Severidad (Clasificación de West Haven)", intro: "El deterioro mental se divide en cuatro grados de progresión:", items: ["Grado 1 o Mínima (sutiles cambios de personalidad, irritabilidad, falta de concentración, inversión del patrón de sueño -duerme de día, vigilia de noche-, a menudo pasa desapercibido para quienes no viven con el paciente)", "Grado 2 (confusión obvia, letargo, desorientación en el tiempo, comportamiento extraño e inapropiado)", "Grado 3 (somnolencia severa o estupor, la persona está casi inconsciente pero puede ser despertada temporalmente por estímulos dolorosos, habla balbuceos incomprensibles)", "Grado 4 (coma hepático total, sin respuesta al dolor; el riesgo de muerte cerebral y fallecimiento es inminente)"], note: "Un paciente puede saltar de una confusión leve a un coma profundo en cuestión de horas si hay un desencadenante fuerte como una infección." }, diagnosis: { title: "Evaluación Neurológica de Urgencia", intro: "El diagnóstico es eminentemente clínico en un paciente con daño hepático conocido:", items: ["Prueba del Asterixis (el signo clínico estrella: el médico pide al paciente que estire los brazos con las muñecas flexionadas hacia arriba; si hay daño por toxinas, las manos darán sacudidas o 'aleteos' rápidos e involuntarios como un pájaro)", "Evaluación del estado mental, orientación y capacidad cognitiva para determinar el grado de avance", "Análisis de sangre para medir los niveles de amoníaco sérico, aunque los niveles no siempre se correlacionan perfectamente con la gravedad del coma", "Búsqueda exhaustiva del desencadenante (análisis de sangre u orina, placa de tórax para buscar infecciones, o examen de heces buscando hemorragia digestiva)"], note: "" }, treatment: { title: "Eliminación de Toxinas y Cuidados Intensivos", intro: "El tratamiento requiere estabilizar al paciente y obligar a los intestinos a expulsar las toxinas rápidamente:", subsections: [ { title: "Terapia de Limpieza Intestinal", items: ["Lactulosa (el tratamiento de primera línea de oro: un jarabe laxante recetado que atrapa el amoníaco tóxico en el intestino y provoca múltiples diarreas para expulsarlo antes de que llegue a la sangre; el objetivo es que el paciente tenga de 2 a 4 deposiciones blandas al día)", "Antibióticos intestinales (como la Rifaximina, tomada junto con la lactulosa; esteriliza selectivamente el intestino para matar las bacterias que producen el amoníaco letal)", "Tratar la causa desencadenante inminente (detener el sangrado de varices en el esófago, tratar una infección de orina severa, corregir la deshidratación aguda o parar ciertos medicamentos sedantes)", "Trasplante de Hígado (la solución curativa final para pacientes con insuficiencia crónica irreversible donde los episodios de encefalopatía y coma no se detienen)"] } ], note: "Es un error común prohibir el consumo de proteínas en la dieta para bajar el amoníaco; esto desnutre letalmente al paciente cirrótico y empeora el cuadro." }, whenToSeekHelp: { title: "¿Cuándo es una Emergencia de Vida o Muerte?", intro: "Para los familiares de un paciente con cirrosis, la aparición de encefalopatía es una URGENCIA HOSPITALARIA ABSOLUTA. Llama al 911 o ve a urgencias si el enfermo:", items: ["Presenta una confusión repentina, no sabe qué día es o dónde está, y dice cosas sin ningún sentido lógico", "Cambia bruscamente de personalidad, volviéndose agresivo, paranoico o sumamente agitado", "Experimenta un letargo extremo, debilidad inusual, somnolencia profunda a mitad del día y resulta difícil despertarlo", "Muestra un temblor o sacudida constante y evidente en las manos al intentar agarrar un objeto", "Tiene aliento con un olor característico muy dulzón o a humedad fuerte (fetor hepaticus)"] } },
'Enfermedad ovárica poliquística' : { intro: "El síndrome o enfermedad de ovarios poliquísticos (SOP) es el trastorno hormonal y metabólico crónico más frecuente en mujeres en edad reproductiva. Provoca un grave desequilibrio en las hormonas sexuales, derivando en problemas de menstruación, exceso de vello y dificultades para quedar embarazada.", whatIs: { title: "¿Qué es el SOP?", text: "Es una disfunción sistémica, a menudo impulsada por una resistencia del cuerpo a la insulina. Esto hace que el páncreas segregue insulina en exceso, la cual estimula a los ovarios a producir demasiados andrógenos (hormonas masculinas, como testosterona). Como resultado, los ovarios no logran desarrollar y liberar óvulos maduros regularmente (anovulación), y esos folículos atascados se ven en la ecografía como pequeños quistes." }, types: { title: "Criterios Clínicos (Rotterdam)", intro: "El SOP se diagnostica cuando se cumplen al menos dos de estas tres características:", items: ["1. Períodos irregulares o ausentes (ciclos menstruales de más de 35 días de duración o menos de 8 menstruaciones en un año completo)", "2. Hiperandrogenismo clínico o laboratorial (niveles altos de hormonas masculinas en sangre, o signos físicos visibles como vello oscuro en cara/pecho o acné quístico severo)", "3. Ovarios poliquísticos (la ecografía revela ovarios agrandados que contienen 12 o más folículos inmaduros dispuestos en un patrón de 'collar de perlas')"], note: "El término 'poliquístico' es engañoso; no son quistes de enfermedad o tumores peligrosos, son simplemente óvulos que se estancaron y no maduraron." }, diagnosis: { title: "Evaluación Endocrinológica y Ginecológica", intro: "El médico debe descartar otros problemas de tiroides o glándulas suprarrenales que imitan al SOP:", items: ["Historial médico minucioso (sobre peso, aparición de acné en la adultez, ritmo de las menstruaciones)", "Examen físico completo (evaluando la obesidad abdominal, pérdida de cabello, y acantosis nigricans: parches de piel oscura y aterciopelada en cuello y axilas debido a la insulina alta)", "Análisis de sangre (perfil de hormonas sexuales FSH/LH, testosterona libre, glucosa en ayunas, prueba de tolerancia a la glucosa y perfil de colesterol)", "Ecografía transvaginal o pélvica (para medir el tamaño de los ovarios y contar los folículos estancados)"], note: "" }, treatment: { title: "Manejo Metabólico y Control Hormonal", intro: "El SOP no tiene una cura definitiva, pero el tratamiento agresivo del estilo de vida y medicación controla casi todos sus estragos:", subsections: [ { title: "Terapias Centrales", items: ["Pérdida de peso y dieta estricta (el pilar fundamental: perder apenas un 5% al 10% de la grasa corporal reduce la insulina y, frecuentemente, reinicia las ovulaciones y la regla por sí solo. Es vital una dieta baja en azúcares y harinas refinadas)", "Anticonceptivos hormonales orales (la primera línea médica para quienes no buscan embarazo; las píldoras regulan el ciclo, protegen el útero contra el cáncer de endometrio y reducen drásticamente el acné y el vello)", "Medicamentos para la resistencia a la insulina (como la Metformina, que baja los niveles de azúcar e insulina, ayudando indirectamente a ovular y bajar peso)", "Medicamentos antiandrógenos (como la Espironolactona, que bloquea el efecto masculino en la piel, reduciendo el vello grueso del rostro y pecho)", "Medicamentos para la fertilidad (si se desea embarazo, se usan inductores de ovulación como Letrozol o Clomifeno en ciclos controlados)"] } ], note: "Las mujeres con SOP tienen un riesgo sumamente alto a largo plazo de desarrollar Diabetes Tipo 2, Síndrome Metabólico, e Hipertensión, por lo que el control del peso no es estético, es vital." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar a un ginecólogo o endocrino?", intro: "Debes programar una revisión integral exhaustiva si experimentas:", items: ["Tus menstruaciones han desaparecido por completo durante varios meses (si no estás embarazada), o son erráticas, tardando más de 35 a 45 días entre cada periodo", "Desarrollas un crecimiento alarmante de vello terminal (grueso y oscuro) en la cara, mentón, cuello, abdomen o muslos internos", "Padeces de un acné quístico doloroso y profundo a lo largo de tu mandíbula o espalda baja en la edad adulta, y no responde a cremas comunes", "Has estado intentando activamente lograr un embarazo durante más de 12 meses (o 6 meses si eres mayor de 35 años) sin ningún éxito"] } },
'TEPT' : { intro: "El trastorno de estrés postraumático (TEPT) es una afección de salud mental grave desencadenada por haber experimentado o presenciado un evento aterrador, traumático o que puso en peligro la vida.", whatIs: { title: "¿Qué es el TEPT?", text: "Es una alteración neurológica y psicológica donde el cerebro se queda 'atascado' en un estado de alerta y peligro constante mucho tiempo después de que la amenaza real haya pasado, reviviendo el trauma repetidamente y evitando estímulos asociados." }, types: { title: "Tipos de Presentación", intro: "Se puede clasificar según el momento de aparición y la duración:", items: ["TEPT agudo (los síntomas duran entre 1 y 3 meses después del evento)", "TEPT crónico (los síntomas persisten por más de 3 meses, a veces durante años)", "TEPT de inicio retardado (los síntomas comienzan 6 meses o más después del evento traumático)", "TEPT complejo (C-PTSD) (causado por trauma crónico y prolongado, como abuso infantil continuo o violencia doméstica)"], note: "Los desencadenantes o 'triggers' pueden ser sonidos, olores, lugares o palabras que transportan a la persona al evento." }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "Un profesional de salud mental diagnostica la afección basándose en criterios del DSM-5:", items: ["Evaluación clínica exhaustiva del historial del trauma y los síntomas", "Presencia de síntomas intrusivos (flashbacks, pesadillas)", "Conductas de evitación extrema de lugares o recuerdos", "Alteraciones negativas en la cognición y el estado de ánimo (culpa, desapego, amnesia)"], note: "" }, treatment: { title: "Psicoterapia y Medicación", intro: "El tratamiento es altamente efectivo y busca procesar el trauma de forma segura:", subsections: [ { title: "Opciones Terapéuticas", items: ["Terapia de Desensibilización y Reprocesamiento por Movimientos Oculares (EMDR) (terapia de primera línea muy efectiva para reprocesar memorias traumáticas)", "Terapia Cognitivo-Conductual (TCC) centrada en el trauma y Terapia de Exposición Prolongada", "Medicamentos (Antidepresivos ISRS como sertralina o paroxetina para controlar la ansiedad severa y la depresión asociada)", "Medicamentos para bloquear las pesadillas (como prazosina)"] } ], note: "Evitar hablar del trauma a largo plazo suele reforzar y empeorar los síntomas del TEPT." }, whenToSeekHelp: { title: "¿Cuándo solicitar ayuda profesional o de urgencia?", intro: "Debes buscar ayuda psiquiátrica o llamar a líneas de emergencia si:", items: ["Experimentas pensamientos intrusivos de muerte o planeas suicidarte o hacerte daño", "Los síntomas (flashbacks, insomnio, ansiedad) duran más de un mes después del evento y te impiden funcionar en el trabajo o la escuela", "Estás usando alcohol o drogas en exceso para 'adormecer' el dolor y poder dormir"] } },
'Trauma' : { intro: "Un trauma físico (o traumatismo) es una lesión, herida o daño físico severo sufrido por el cuerpo humano debido a un impacto violento, un accidente, una fuerza mecánica externa o una agresión.", whatIs: { title: "¿Qué es un Trauma Médico?", text: "En la medicina de urgencias, el trauma se refiere a un daño físico agudo y repentino que compromete las estructuras del cuerpo (huesos, órganos, vasos sanguíneos, piel). Si es lo suficientemente grave (trauma mayor), puede poner en peligro la vida inmediatamente debido a pérdida de sangre, daño cerebral o fallo respiratorio." }, types: { title: "Mecanismos de Lesión", intro: "Se clasifica por cómo la fuerza impactó el cuerpo:", items: ["Trauma contuso o cerrado (impacto fuerte sin romper la piel, como en un accidente automovilístico, caídas de altura o golpes deportivos; puede causar hemorragias internas ocultas mortales)", "Trauma penetrante (un objeto perfora la piel y entra al cuerpo, como heridas por arma de fuego, arma blanca o empalamiento)", "Politraumatismo (el paciente sufre lesiones graves simultáneas en múltiples órganos o sistemas, como cabeza, tórax y extremidades a la vez)"], note: "" }, diagnosis: { title: "Evaluación Primaria de Emergencia", intro: "En la sala de urgencias, se aplica el protocolo vital ABCDE:", items: ["A (Vía Aérea) y B (Respiración): Asegurar que el paciente pueda respirar e intubarlo si es necesario", "C (Circulación): Detener hemorragias masivas y reponer sangre o líquidos", "D (Déficit neurológico): Evaluar el nivel de conciencia (Escala de Glasgow) y el daño cerebral", "E (Exposición): Desvestir al paciente para buscar lesiones ocultas", "Imágenes de emergencia (Ecografía FAST en trauma, Rayos X de tórax/pelvis y Tomografía Computarizada de cuerpo entero)"], note: "" }, treatment: { title: "Soporte Vital y Cirugía de Rescate", intro: "El objetivo es estabilizar las constantes vitales y reparar el daño estructural:", subsections: [ { title: "Intervenciones", items: ["Control inmediato de hemorragias mediante torniquetes, vendajes compresivos o medicamentos coagulantes", "Cirugía de control de daños (operaciones rápidas para detener el sangrado interno en el abdomen, tórax o cerebro)", "Estabilización ortopédica (fijadores externos o cirugía para huesos rotos)", "Ingreso a la Unidad de Cuidados Intensivos (UCI) para soporte multiorgánico"] } ], note: "La 'hora dorada' es crítica: recibir atención quirúrgica definitiva en los primeros 60 minutos del trauma aumenta enormemente la supervivencia." }, whenToSeekHelp: { title: "¿Cuándo llamar a una ambulancia (911)?", intro: "Cualquier traumatismo de alta energía requiere evaluación hospitalaria. Pide ayuda inmediata si:", items: ["La persona ha perdido el conocimiento, está muy confundida o no responde tras el impacto", "Existe un sangrado profuso que no se detiene con presión directa", "Hay dificultad evidente para respirar, dolor intenso en el pecho o el abdomen, o signos de shock (piel pálida, fría y sudorosa, pulso muy rápido)", "Se sospecha de una lesión en la cabeza, el cuello o la columna vertebral (NUNCA mueva al paciente a menos que haya peligro inminente de fuego o explosión)"] } },
'Esclerosis sistémica' : { intro: "La esclerosis sistémica, también conocida como esclerodermia, es una enfermedad autoinmune crónica, progresiva y rara, caracterizada por el endurecimiento y engrosamiento excesivo de la piel, los vasos sanguíneos y, a menudo, los órganos internos.", whatIs: { title: "¿Qué es la Esclerosis Sistémica?", text: "Es un trastorno del tejido conectivo. El sistema inmunológico ataca los tejidos del cuerpo, causando que las células produzcan cantidades masivas y anormales de colágeno (la proteína estructural). Este exceso de colágeno se acumula, creando un tejido rígido, grueso y cicatrizal (fibrosis) que limita el movimiento y asfixia a los órganos vitales como pulmones, corazón y riñones." }, types: { title: "Formas de Esclerodermia", intro: "La enfermedad se divide según su extensión en el cuerpo:", items: ["Esclerodermia localizada (afecta únicamente zonas específicas de la piel y músculos subyacentes, formando parches o bandas duras; no afecta órganos internos)", "Esclerosis sistémica cutánea limitada (afecta la piel de los dedos, manos y cara; progresa lentamente y a menudo se asocia con el Síndrome CREST)", "Esclerosis sistémica cutánea difusa (muy grave y de avance rápido; afecta grandes áreas de la piel del torso y extremidades, y ataca velozmente los pulmones, los riñones y el sistema digestivo)"], note: "El Fenómeno de Raynaud (dedos que se vuelven blancos y azules con el frío por espasmos vasculares) suele ser el primerísimo síntoma de la enfermedad, apareciendo años antes que el endurecimiento." }, diagnosis: { title: "Evaluación Reumatológica", intro: "Es difícil de diagnosticar en sus inicios. El reumatólogo utilizará:", items: ["Examen físico minucioso (evaluando el engrosamiento de la piel en los dedos -esclerodactilia- y cara)", "Capilaroscopia del lecho ungueal (observar las cutículas de las uñas con un microscopio para ver vasos sanguíneos anormales)", "Análisis de sangre autoinmunes (buscando anticuerpos específicos como ANA, anti-Scl-70 o anticentrómero)", "Ecocardiograma, pruebas de función pulmonar o TC de tórax (para evaluar tempranamente si el corazón o los pulmones están siendo cicatrizados)"], note: "" }, treatment: { title: "Control Inmunosupresor y Sintomático", intro: "No existe un medicamento que detenga o cure la superproducción de colágeno, el tratamiento ataca complicaciones específicas:", subsections: [ { title: "Terapias Dirigidas", items: ["Vasodilatadores (como bloqueadores de los canales de calcio o sildenafilo para abrir los vasos, tratar el severo fenómeno de Raynaud y evitar úlceras en los dedos)", "Inmunosupresores (Metotrexato, Micofenolato o Ciclofosfamida para frenar el ataque del sistema inmune y proteger los pulmones)", "Inhibidores de la bomba de protones (IBP) (para tratar el reflujo gástrico severo causado por la rigidez del esófago)", "Antifibróticos (como Nintedanib) para pacientes que desarrollan fibrosis pulmonar", "Medicamentos para la presión arterial (IECA, vitales para proteger a los riñones de una 'crisis renal esclerodérmica' mortal)"] } ], note: "Mantener el cuerpo muy abrigado, especialmente las manos y los pies, es absolutamente esencial para evitar crisis vasculares." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Debes buscar ayuda especializada o de urgencia si ya estás diagnosticado o si tienes síntomas como:", items: ["Tus dedos se vuelven dolorosamente blancos, azules y luego rojos con el frío o el estrés, o desarrollan úlceras dolorosas en las yemas que no sanan", "Notas un endurecimiento progresivo, rigidez y pérdida de flexibilidad en la piel de tus manos, brazos o rostro", "Sufres una dificultad repentina, nueva o progresiva para respirar (falta de aire) o una tos seca continua (riesgo pulmonar)", "Tu presión arterial se dispara repentinamente acompañada de un dolor de cabeza severo (alerta máxima de crisis renal)"] } },
'Trastorno de personalidad narcisista' : { intro: "El trastorno de personalidad narcisista (TPN) es una afección mental caracterizada por un sentido desmesurado de la propia importancia, una necesidad profunda y constante de atención y admiración excesivas, y una profunda falta de empatía por los demás.", whatIs: { title: "¿Qué es el TPN?", text: "Es un patrón crónico de grandiosidad y comportamiento egocéntrico. Detrás de esta máscara de extrema confianza y superioridad, se esconde una autoestima sumamente frágil, que es vulnerable a la más mínima crítica. Estas personas suelen monopolizar las conversaciones, menospreciar a quienes consideran inferiores y explotar a otros para alcanzar sus metas." }, types: { title: "Subtipos Clínicos (No Oficiales pero Reconocidos)", intro: "La manifestación del narcisismo varía según la persona:", items: ["Narcisista grandioso o manifiesto (extrovertido, arrogante, dominante, exhibicionista y claramente centrado en sí mismo)", "Narcisista vulnerable o encubierto (introvertido, hipersensible, se siente constantemente ofendido, se hace la víctima y alberga una grandiosidad secreta y un profundo resentimiento)", "Narcisista maligno (presenta rasgos de narcisismo mezclados con psicopatía, sadismo o comportamiento antisocial; disfruta manipulando y dañando a otros)"], note: "Suele causar muchos problemas en muchas áreas de la vida, como las relaciones de pareja, el trabajo, la escuela o los asuntos económicos." }, diagnosis: { title: "Evaluación Psicológica", intro: "El diagnóstico lo realiza un psiquiatra o psicólogo clínico:", items: ["Entrevista clínica en profundidad", "Evaluación según los criterios del DSM-5 (debe cumplir al menos 5 de 9 características, como fantasías de éxito ilimitado, creencia de ser 'especial', exigencia de admiración excesiva, falta de empatía y envidia crónica)", "Evaluación de trastornos concurrentes (suele presentarse junto con depresión, ansiedad, trastorno bipolar o abuso de sustancias)"], note: "Las personas con TPN casi nunca buscan tratamiento para su narcisismo, sino que acuden por depresión o ansiedad tras un fracaso personal o un divorcio." }, treatment: { title: "Psicoterapia a Largo Plazo", intro: "El tratamiento es un desafío significativo porque el paciente rara vez acepta que tiene un problema:", subsections: [ { title: "Enfoques Terapéuticos", items: ["Psicoterapia conversacional (el pilar del tratamiento; busca ayudar a la persona a relacionarse con los demás de una manera más positiva y compasiva, y a entender las causas de sus emociones y comportamientos)", "Terapia Cognitivo-Conductual (TCC) (para identificar y alterar creencias distorsionadas sobre sí mismo y los demás)", "Terapia basada en la mentalización o Terapia centrada en esquemas", "Medicación (no existen pastillas para curar el TPN, pero se prescriben antidepresivos o ansiolíticos para tratar síntomas de depresión severa o ansiedad que a menudo acompañan al trastorno)"] } ], note: "Para los familiares o parejas de una persona con TPN, buscar terapia individual es crucial para establecer límites y sanar el abuso emocional (gaslighting)." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda profesional?", intro: "Es fundamental buscar asistencia psicológica si:", items: ["Te das cuenta de que tus relaciones personales o laborales fracasan continuamente debido a conflictos de poder o sentimientos de incomprensión", "Sientes una depresión abrumadora, ansiedad o pensamientos suicidas porque la vida no cumple con tus expectativas de perfección o éxito", "Alguien de tu entorno cercano sufre de esto y te encuentras agotado, manipulado, aislado o sufriendo de abuso psicológico crónico"] } },
'Lesión maxilofacial' : { intro: "Una lesión maxilofacial se refiere a cualquier trauma físico significativo que afecte los tejidos blandos y/o los huesos de la cara, la boca y las mandíbulas. Pueden ir desde laceraciones simples hasta fracturas complejas que desfiguran el rostro.", whatIs: { title: "¿Qué es una Lesión Maxilofacial?", text: "Es un daño estructural en el cráneo facial (maxilar superior, mandíbula inferior, pómulos -huesos cigomáticos-, nariz u órbitas de los ojos). Son lesiones muy delicadas porque la cara contiene vías respiratorias, órganos de los sentidos y nervios críticos. Las causas principales son accidentes de coche, peleas físicas, caídas y traumas deportivos." }, types: { title: "Clasificación de Fracturas Comunes", intro: "El impacto determina qué huesos faciales colapsan:", items: ["Fracturas mandibulares (la mandíbula inferior se rompe, causando una mala mordida y dolor al hablar o masticar)", "Fracturas del cigomático (ruptura del pómulo, aplanando el costado de la cara y a menudo atrapando los músculos del ojo)", "Fracturas orbitales (rotura de la cuenca del ojo, el ojo puede hundirse o la visión verse doble)", "Fracturas nasales (la fractura facial más común, deformidad y sangrado de la nariz)", "Fracturas de Le Fort (fracturas masivas que separan el maxilar del cráneo)"], note: "" }, diagnosis: { title: "Evaluación Traumatológica Urgente", intro: "El especialista maxilofacial evalúa la gravedad usando tecnología 3D:", items: ["Asegurar las vías respiratorias (A y B del trauma) es el paso vital inicial", "Tomografía Computarizada (TC) de macizo facial (el estudio estándar y perfecto que genera un mapa en 3D de todos los huesos rotos para que el cirujano planifique cómo unirlos)", "Examen oftalmológico (si hay daño cerca del ojo) y examen de oclusión (para ver si los dientes encajan bien)"], note: "" }, treatment: { title: "Reconstrucción y Fijación Quirúrgica", intro: "El objetivo es restaurar la función (respirar, masticar, ver) y la estética facial:", subsections: [ { title: "Intervenciones Médicas", items: ["Limpieza y sutura especializada por cirugía plástica o maxilofacial para tejidos blandos (para minimizar cicatrices)", "Reducción y Fijación Interna Rígida (la cirugía principal: los cirujanos exponen el hueso roto desde dentro de la boca o incisiones ocultas, lo alinean y lo atornillan permanentemente con miniplacas de titanio)", "Fijación intermaxilar (atar o bloquear la mandíbula superior e inferior juntas con alambres o gomas durante semanas para inmovilizar los huesos mientras sanan)", "Tratamiento de conducto o extracción para dientes rotos o avulsionados"] } ], note: "La aplicación de hielo inmediato y mantener la cabeza elevada son los primeros auxilios básicos para minimizar la gran hinchazón facial." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia hospitalaria?", intro: "Acude a la sala de emergencias inmediatamente después de un golpe en la cara si experimentas:", items: ["Dificultad o imposibilidad para respirar, o sangrado incontrolable por nariz o boca", "Cambios en la visión, visión doble (diplopía) o incapacidad para mover el ojo en todas direcciones", "Sientes que tus dientes no encajan correctamente al morder, tienes la mandíbula trabada, o hay dientes extremadamente flojos o caídos", "Entumecimiento severo en las mejillas, labios o nariz (indica que un nervio facial ha sido cortado o aplastado)"] } },
'Pericarditis' : { intro: "La pericarditis es la inflamación repentina e irritación del pericardio, la membrana delgada en forma de saco de dos capas que rodea y protege el corazón. Provoca un dolor de pecho agudo e intenso que a menudo asusta a los pacientes porque simula un ataque cardíaco.", whatIs: { title: "¿Qué es la Pericarditis?", text: "Normalmente, las dos capas del pericardio se deslizan suavemente una sobre la otra lubricadas por un poco de líquido. Cuando se inflaman, estas capas se vuelven ásperas y rozan entre sí cada vez que el corazón late o los pulmones se expanden, creando un dolor punzante en el pecho (fricción pericárdica)." }, types: { title: "Tipos de Pericarditis", intro: "Se clasifica por cuánto tiempo dura el cuadro:", items: ["Aguda (comienza de repente y dura menos de tres semanas, es la más común)", "Incesante (dura de cuatro a seis semanas sin interrupción, a pesar del tratamiento)", "Recurrente (ocurre un nuevo episodio después de que el primero se había curado y pasado semanas sin síntomas)", "Crónica constrictiva (una complicación grave a largo plazo donde el pericardio se vuelve grueso, rígido y cicatrizado, comprimiendo el corazón e impidiéndole llenarse de sangre)"], note: "La gran mayoría de los casos agudos son de origen idiopático (causa desconocida) o secundarios a una infección viral reciente (como un resfriado severo o COVID-19)." }, diagnosis: { title: "Evaluación Cardiológica de Urgencia", intro: "El médico debe descartar que el dolor de pecho sea un infarto mortal:", items: ["Auscultación con estetoscopio (el médico escuchará un sonido clásico de 'roce pericárdico' en el corazón)", "Electrocardiograma (ECG) (crucial; la pericarditis muestra un patrón eléctrico específico de elevación del ST en todas las derivaciones que la diferencia del ataque cardíaco)", "Ecocardiograma o ultrasonido del corazón (para ver si hay un exceso peligroso de líquido acumulado alrededor del corazón, llamado derrame pericárdico)", "Análisis de sangre (para medir marcadores de inflamación masiva como la PCR o la velocidad de sedimentación globular)"], note: "" }, treatment: { title: "Desinflamación y Drenaje", intro: "El tratamiento se enfoca en apagar la inflamación agresiva y calmar el dolor:", subsections: [ { title: "Opciones Médicas", items: ["Dosis altas de AINEs (Ibuprofeno, Indometacina o Aspirina son la primera línea de defensa para desinflamar el saco y quitar el dolor; pueden usarse durante semanas)", "Colchicina (un poderoso medicamento antiinflamatorio añadido al ibuprofeno que reduce drásticamente el riesgo de que la pericarditis vuelva a aparecer en el futuro)", "Corticosteroides (Prednisona, usados únicamente si los AINEs y la colchicina fallan, debido a que pueden aumentar las recaídas si se usan mal)", "Pericardiocentesis de urgencia (si hay un derrame masivo que está aplastando al corazón -taponamiento cardíaco-, el cardiólogo clava una aguja en el pecho para drenar el líquido y salvar la vida del paciente)"] } ], note: "El reposo físico estricto y no hacer ejercicio cardiovascular es imperativo hasta que el dolor desaparezca y el médico lo autorice." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911 o ir a urgencias?", intro: "Es imposible diferenciar en casa la pericarditis de un infarto. Llama a emergencias de inmediato si presentas:", items: ["Un dolor agudo, punzante e intenso en el centro o el lado izquierdo de tu pecho", "El dolor empeora fuertemente cuando toses, tragas, respiras profundo o al acostarte boca arriba", "El dolor mejora notablemente o se alivia al sentarte e inclinarte hacia adelante", "Tienes dificultad para respirar severa, palpitaciones o debilidad repentina y desmayo (posible taponamiento cardíaco)"] } },
'Síndrome de dolor pélvico' : { intro: "El síndrome de dolor pélvico crónico (SDPC) es una afección compleja y muy frustrante caracterizada por un dolor continuo o intermitente en la región inferior del abdomen o la pelvis, que persiste durante seis meses o más.", whatIs: { title: "¿Qué es el Dolor Pélvico Crónico?", text: "Es un dolor que puede ser sordo, punzante o presentarse como calambres pesados. No es una enfermedad única, sino un síndrome multifactorial. Puede originarse por problemas ginecológicos, urológicos, gastrointestinales, nerviosos o musculares del suelo pélvico, y a menudo la causa exacta es muy difícil de identificar." }, types: { title: "Causas y Trastornos Asociados", intro: "El dolor pélvico suele ser el síntoma de condiciones ocultas:", items: ["Origen Ginecológico: Endometriosis (tejido uterino creciendo fuera del útero), adenomiosis, fibromas o enfermedad pélvica inflamatoria crónica", "Origen Urológico: Cistitis intersticial (síndrome de vejiga dolorosa) o prostatitis crónica (en hombres)", "Origen Gastrointestinal: Síndrome del intestino irritable (SII) o diverticulitis crónica", "Origen Muscular/Nervioso: Espasmos severos de la musculatura del suelo pélvico o atrapamiento del nervio pudendo"], note: "En muchos casos, el dolor pélvico persiste incluso después de que la enfermedad original haya sido tratada, debido a una sensibilización del sistema nervioso central." }, diagnosis: { title: "Evaluación Multidisciplinaria", intro: "Requiere paciencia y múltiples pruebas para descartar problemas graves:", items: ["Examen pélvico completo (para localizar áreas de sensibilidad, espasmos musculares o masas)", "Ecografía pélvica o transvaginal, y Resonancia Magnética (para visualizar órganos internos)", "Laparoscopia diagnóstica (una cirugía menor con cámara que es el único método definitivo para confirmar o descartar la presencia de endometriosis)", "Análisis de orina y cultivos (para descartar infecciones crónicas)", "Evaluación de la salud mental (el dolor crónico severo frecuentemente causa depresión y ansiedad, que a su vez empeoran la percepción del dolor)"], note: "" }, treatment: { title: "Manejo del Dolor y Terapias Físicas", intro: "A menudo requiere una combinación de tratamientos; rara vez una sola pastilla lo cura:", subsections: [ { title: "Opciones de Tratamiento", items: ["Medicamentos (Analgésicos, relajantes musculares, antidepresivos tricíclicos o anticonvulsivos -como pregabalina- que son muy efectivos para 'apagar' el dolor de los nervios dañados)", "Terapia hormonal (anticonceptivos orales o DIU hormonal si la causa es dolor menstrual, endometriosis o adenomiosis)", "Fisioterapia del suelo pélvico (realizada por expertos, incluye masajes internos, estiramientos y biofeedback para liberar espasmos musculares crónicos, siendo una de las terapias más exitosas)", "Inyecciones de puntos gatillo o bloqueos nerviosos locales con anestesia", "Cirugía (como extirpación de lesiones de endometriosis, o en casos extremos, histerectomía)"] } ], note: "La psicoterapia es una herramienta vital para aprender a convivir y manejar el impacto del dolor diario en la calidad de vida." }, whenToSeekHelp: { title: "¿Cuándo consultar a un especialista en dolor pélvico?", intro: "Debes buscar ayuda médica exhaustiva si:", items: ["El dolor pélvico interrumpe tus actividades diarias, te impide hacer ejercicio, trabajar o dormir", "El dolor ocurre intensamente durante o después de tener relaciones sexuales (dispareunia), afectando tu vida íntima", "Sufres de dolor severo al orinar o al tener una evacuación intestinal", "El dolor se acompaña de sangrado menstrual extremadamente abundante, fiebre inexplicable o pérdida de peso"] } },
'Ataque cardíaco' : { intro: "Un ataque cardíaco, conocido clínicamente como infarto agudo de miocardio (IAM), es una emergencia médica de extrema gravedad en la que se interrumpe abruptamente el flujo de sangre a una parte del corazón. Sin oxígeno, el músculo cardíaco comienza a morir rápidamente.", whatIs: { title: "¿Qué es un Infarto de Miocardio?", text: "Ocurre cuando una de las arterias coronarias que nutre el corazón se bloquea por completo. Usualmente, esto pasa cuando una placa de colesterol (aterosclerosis) se rompe dentro de la arteria, y el cuerpo forma un coágulo de sangre masivo sobre ella para 'curarla', taponando completamente el tubo e impidiendo el paso de sangre." }, types: { title: "Tipos de Infarto", intro: "Los médicos los clasifican en Urgencias según su gravedad eléctrica en el electrocardiograma (ECG):", items: ["Infarto con elevación del segmento ST (IAMCEST) (la arteria coronaria está bloqueada al 100%; es la emergencia más letal y destructiva, requiere abrir la arteria de inmediato con cirugía o fármacos)", "Infarto sin elevación del segmento ST (IAMSEST) (la arteria está parcialmente bloqueada o el flujo está muy reducido; el daño es menor pero requiere ingreso hospitalario urgente y tratamiento)", "Infarto silente (un ataque al corazón que ocurre sin síntomas evidentes o con síntomas que se confunden con indigestión, descubierto meses después en un chequeo rutinario)"], note: "El factor tiempo es crucial. 'Tiempo es músculo': cada minuto que el corazón pasa sin sangre, más tejido muere de forma irreversible, derivando en insuficiencia cardíaca futura." }, diagnosis: { title: "Pruebas de Urgencia (Sala de Choque)", intro: "El diagnóstico debe hacerse en los primeros 10 minutos de llegar al hospital:", items: ["Electrocardiograma (ECG) (la primera e inmediata prueba, registra la actividad eléctrica y muestra al instante si el corazón está sufriendo daño severo y de qué tipo)", "Análisis de sangre para enzimas cardíacas (la Troponina; cuando el músculo del corazón muere, libera esta proteína a la sangre; su nivel alto confirma el infarto)", "Angiografía coronaria (cateterismo cardíaco de emergencia: se introduce un tubo desde la muñeca o la ingle para inyectar tinte y ver en rayos X exactamente qué arteria está tapada)", "Ecocardiograma posterior (para evaluar cuánto músculo murió y la fuerza de bombeo restante)"], note: "" }, treatment: { title: "Destapamiento Arterial y Rescate Vital", intro: "El objetivo de los primeros 90 minutos es restaurar el flujo sanguíneo:", subsections: [ { title: "Intervenciones Críticas Inmediatas", items: ["Angioplastia y colocación de stent coronario (el tratamiento de oro: el cardiólogo introduce un globo para abrir la arteria tapada y deja una malla de metal -stent- para mantenerla abierta, salvando la vida del paciente)", "Medicamentos trombolíticos (si el hospital no tiene sala de cateterismo, inyectan potentes fármacos 'rompe-coágulos' por la vena para disolver el tapón)", "Aspirina y nitroglicerina administradas en la misma ambulancia para afinar la sangre y dilatar los vasos", "Cirugía de bypass coronario de urgencia (solo si hay demasiadas arterias bloqueadas simultáneamente)"] } ], note: "Tras el alta, el paciente deberá tomar obligatoriamente una batería de medicamentos de por vida (Aspirina, Estatinas para el colesterol, Betabloqueantes) y cambiar radicalmente su estilo de vida." }, whenToSeekHelp: { title: "¿Cuándo llamar a una Ambulancia (Emergencia Vital)?", intro: "NUNCA conduzcas tú mismo al hospital. Llama al 911 de inmediato si experimentas:", items: ["Dolor, presión, opresión, pesadez o sensación de compresión (como un elefante sentado) en el centro de tu pecho que dura más de unos minutos o va y viene", "El dolor del pecho se irradia hacia tu brazo izquierdo (o ambos brazos), la espalda, el cuello, la mandíbula inferior o el estómago", "Falta de aire repentina y severa (con o sin dolor en el pecho)", "Sudoración fría y profusa inexplicable, palidez, náuseas, vómitos, aturdimiento intenso o desmayo", "En las mujeres, los síntomas pueden ser 'atípicos', como fatiga extrema, indigestión severa o dolor de espalda agudo sin dolor de pecho"] } },
'Fibromiositis' : { intro: "La fibromiositis es un término médico antiguo y obsoleto que históricamente se utilizaba para describir el dolor y la inflamación en los músculos y sus tejidos conectivos circundantes. En la medicina moderna, este concepto ha sido reemplazado casi en su totalidad por dos diagnósticos mucho más precisos: el Síndrome de Dolor Miofascial y la Fibromialgia.", whatIs: { title: "¿Qué es (o era) la Fibromiositis?", text: "Anteriormente se creía que era una verdadera 'miositis' (inflamación de las fibras musculares). Sin embargo, estudios demostraron que en condiciones como la fibromialgia o los puntos gatillo, no existe una inflamación celular real en el músculo. Hoy en día, los médicos utilizan el término 'Síndrome de dolor miofascial' para el dolor muscular focalizado por nudos, y 'Fibromialgia' para el dolor generalizado crónico." }, types: { title: "Diagnósticos Actuales", intro: "Si te han mencionado 'fibromiositis', probablemente padezcas una de estas dos condiciones:", items: ["Síndrome de Dolor Miofascial (dolor localizado en un músculo específico causado por 'puntos gatillo' o nudos hiperirritables tras una mala postura o sobreesfuerzo repetitivo; el dolor a menudo se irradia a otra zona al presionar el nudo)", "Fibromialgia (un trastorno de dolor crónico sistémico y generalizado en todo el cuerpo, acompañado de fatiga extrema, problemas de sueño y niebla mental o problemas de memoria; es un problema de procesamiento del dolor en el cerebro, no de inflamación muscular)"], note: "" }, diagnosis: { title: "Evaluación Médica (Reumatología o Manejo del Dolor)", intro: "El diagnóstico es enteramente clínico, ya que no hay daños en radiografías ni en sangre:", items: ["Para dolor miofascial: El médico palpará buscando bandas tensas musculares y presionará puntos específicos para ver si desencadenan el dolor (puntos gatillo)", "Para fibromialgia: Se diagnostica si el paciente ha tenido dolor generalizado en múltiples áreas del cuerpo durante más de tres meses, acompañado de fatiga severa y trastornos del sueño", "Análisis de sangre y pruebas de tiroides se realizan sistemáticamente solo para descartar que el dolor sea por lupus, artritis reumatoide, hipotiroidismo o falta de vitaminas"], note: "" }, treatment: { title: "Manejo del Dolor y Terapias Físicas", intro: "Los tratamientos no curan la afección base, pero logran controlar los síntomas para recuperar una vida normal:", subsections: [ { title: "Estrategias Terapéuticas Activas", items: ["Para el Síndrome Miofascial: Fisioterapia, masajes descontracturantes profundos, aplicación de calor, estiramientos, inyecciones de anestésico directamente en los puntos gatillo dolorosos, o punción seca", "Para la Fibromialgia: El ejercicio aeróbico regular y de bajo impacto (caminar, nadar) es la medicina más probada y eficaz", "Medicamentos neuromoduladores: Fármacos como la Duloxetina, Pregabalina o Amitriptilina (que actúan en el sistema nervioso para calmar las señales de dolor), y relajantes musculares", "Terapia Cognitivo-Conductual (TCC): Esencial para ayudar a los pacientes a manejar el estrés mental que multiplica los espasmos musculares y el dolor crónico"] } ], note: "Los analgésicos opioides fuertes y narcóticos están fuertemente contraindicados, ya que no son eficaces para el dolor fibrálgico o miofascial y generan adicción letal." }, whenToSeekHelp: { title: "¿Cuándo solicitar evaluación reumatológica?", intro: "Es importante buscar atención médica adecuada para dejar de sufrir en silencio si:", items: ["Tienes dolor muscular profundo, rigidez constante o 'nudos' en la espalda, cuello y hombros que no desaparecen tras semanas de descanso y analgésicos de venta libre", "Te despiertas por la mañana sintiéndote agotado y dolorido como si te hubieran golpeado, a pesar de haber dormido 8 horas", "El dolor generalizado está arruinando tu calidad de vida, limitando tu capacidad para trabajar, concentrarte, hacer ejercicio o disfrutar de tu familia"] } },
'Cetoacidosis diabética' : { intro: "La cetoacidosis diabética (CAD) es una complicación aguda, gravísima y potencialmente mortal de la diabetes. Ocurre predominantemente en personas con diabetes tipo 1, aunque también puede suceder en la tipo 2 bajo estrés extremo, cuando el cuerpo produce niveles altísimos de ácidos tóxicos en la sangre.", whatIs: { title: "¿Qué es la Cetoacidosis Diabética?", text: "Aparece cuando el cuerpo no tiene suficiente insulina (la llave que permite a las células usar el azúcar). Sin insulina, las células mueren de hambre por falta de glucosa. En un intento desesperado por obtener energía, el cuerpo empieza a quemar grasa rápidamente. Este proceso produce subproductos altamente tóxicos y ácidos llamados 'cetonas'. Si las cetonas se acumulan rápido, la sangre se vuelve ácida y envenena el cuerpo entero." }, types: { title: "Factores Desencadenantes", intro: "La CAD raramente ocurre de la nada; suele haber un gatillo:", items: ["Enfermedad o infección severa (como neumonía, COVID o infección urinaria, que hacen que el cuerpo produzca hormonas como adrenalina, que contrarrestan la poca insulina que hay)", "Omisión de dosis de insulina (saltarse inyecciones, o que la bomba de insulina se dañe u obstruya sin que el paciente lo note)", "Falta de diagnóstico (a menudo, la CAD es la aterradora primera señal por la que un niño o joven descubre que tiene diabetes tipo 1 por primera vez)"], note: "Si no se trata velozmente en el hospital, desemboca en un edema cerebral (hinchazón del cerebro), coma diabético y la muerte." }, diagnosis: { title: "Pruebas de Emergencia y Laboratorio", intro: "El diagnóstico hospitalario debe ser rápido y contundente:", items: ["Análisis de glucosa en sangre (suele revelar niveles peligrosamente altos de azúcar, por encima de 250 mg/dL)", "Análisis de cetonas en sangre u orina (el hallazgo definitivo de grandes cantidades de cuerpos cetónicos)", "Gasometría arterial (un análisis de sangre de la arteria para medir el pH; revelará que la sangre es anormal y peligrosamente ácida)", "Panel metabólico básico para comprobar si los electrolitos (potasio, sodio) están desequilibrados y si los riñones están sufriendo por la deshidratación masiva"], note: "Las personas con diabetes deben tener en casa tiras reactivas de orina para medir cetonas y prevenir llegar al hospital." }, treatment: { title: "Cuidados Intensivos y Reposición", intro: "El tratamiento requiere ingreso hospitalario de urgencia, generalmente en la UCI:", subsections: [ { title: "Pilares del Tratamiento de Rescate", items: ["Terapia agresiva con líquidos intravenosos (IV) (para rehidratar masivamente el cuerpo que ha perdido litros de agua orinando el exceso de azúcar, y para diluir las cetonas)", "Insulina intravenosa continua (el tratamiento curativo; un goteo directo a la vena que revierte inmediatamente el proceso, haciendo que el cuerpo deje de quemar grasa y deje de fabricar ácidos)", "Reposición de electrolitos (especialmente Potasio; la insulina empuja el potasio de vuelta a las células, bajando su nivel en sangre bruscamente, por lo que el médico debe inyectar potasio para evitar que el corazón se pare)"] } ], note: "Una vez estabilizado, el médico investigará qué infección u omisión provocó la crisis para evitar que se repita." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA DE VIDA O MUERTE?", intro: "Dirígete a la sala de emergencias o llama al 911 de inmediato si tú (o tu hijo) tienes diabetes, el azúcar marca más de 250 mg/dL (o 300) que no baja, y presentas:", items: ["Sed insaciable extrema y una necesidad de orinar incesante y masiva", "Náuseas violentas y vómitos repetidos y constantes (lo que impide hidratarse)", "Dolor abdominal muy severo e inexplicable", "Aliento con un olor muy extraño, afrutado o dulce (similar al olor del quitaesmalte de uñas o manzanas podridas, síntoma cardinal de las cetonas)", "Respiración profunda, rápida y jadeante (respiración de Kussmaul, el cuerpo intentando expulsar el ácido)", "Confusión mental, letargo, debilidad extrema, aturdimiento profundo o desmayos"] } },
'Embarazo de bajo riesgo' : { intro: "Un embarazo de bajo riesgo es la progresión natural, normal y saludable de la gestación en una mujer sana, en la cual ni ella ni el feto presentan antecedentes médicos, problemas genéticos o complicaciones obstétricas que pongan en peligro sus vidas o su salud general.", whatIs: { title: "¿Qué significa el Bajo Riesgo?", text: "Significa que las probabilidades de tener una complicación grave durante el embarazo o el parto son extremadamente bajas. La madre está sana, tiene una edad adecuada, el feto se desarrolla a un ritmo normal según los estándares ecográficos, y se espera que el nacimiento se produzca a término (entre las 37 y 42 semanas de embarazo) sin necesidad de intervenciones complejas de emergencia." }, types: { title: "Criterios para Considerarse de Bajo Riesgo", intro: "Para que un médico o matrona lo clasifique así, deben cumplirse ciertas condiciones ideales:", items: ["Ausencia absoluta de enfermedades crónicas previas en la madre (como hipertensión arterial crónica, diabetes preexistente tipo 1 o 2, enfermedades cardíacas, renales, autoinmunes como el lupus, o problemas graves de tiroides no controlados)", "Un embarazo de un solo bebé (es decir, no hay gemelos ni trillizos, los cuales aumentan por sí solos el riesgo de parto prematuro)", "Un historial obstétrico sin problemas mayores (no haber sufrido partos prematuros anteriores, no tener historial de abortos de repetición inexplicables o muerte fetal, no haber tenido preeclampsia severa en el pasado)", "La madre se encuentra en un peso corporal saludable y en un rango de edad ideal (usualmente no es menor de 18 ni mayor de 35 años, aunque mujeres de 35 o más que están muy sanas a menudo tienen embarazos sin ningún problema)"], note: "Es vital entender que un embarazo de 'bajo riesgo' no es un embarazo de 'cero riesgo'; cualquier embarazo requiere un monitoreo cuidadoso, ya que su estado o clasificación puede cambiar rápidamente a lo largo de los meses." }, diagnosis: { title: "Controles Prenatales y Seguimiento Rutinario", intro: "El objetivo del médico u obstetra es monitorear a la paciente para asegurar que todo el proceso siga siendo normal:", items: ["Visitas médicas periódicas y regulares (usualmente cada 4 semanas en los primeros trimestres, cada 2 semanas desde la semana 28, y cada semana en el último mes para medir la presión arterial materna, el aumento de peso y el ritmo cardíaco del bebé)", "Análisis de sangre y de orina de rutina (para descartar signos tempranos y ocultos de diabetes gestacional a la mitad del embarazo, anemia por falta de hierro, o problemas de infecciones urinarias asintomáticas)", "Ecografías o ultrasonidos estándar (al menos una principal entre las semanas 18 y 22 para revisar toda la anatomía del feto al detalle, y a veces otras para confirmar la fecha de parto inicial o la posición final del bebé)"], note: "" }, treatment: { title: "Cuidados, Hábitos y Preparación", intro: "En esta categoría no hay tratamientos médicos para enfermedades, sino suplementación de prevención y fomento de bienestar de vida:", subsections: [ { title: "Pautas y Recomendaciones", items: ["Consumo diario estricto de vitaminas prenatales que contengan Ácido Fólico (al menos 400 mcg, crucial para evitar defectos irreversibles en el tubo neural y cerebro del bebé) y un suplemento de hierro adicional si el médico lo recomienda", "Mantener una nutrición excelente y equilibrada, lavando muy bien frutas y verduras, cocinando bien las carnes y evitando totalmente alimentos de alto riesgo infeccioso (como quesos no pasteurizados, sushi de pescado crudo, embutidos o alcohol de cualquier tipo)", "Realizar ejercicio físico moderado y aprobado (como caminatas, natación o yoga para embarazadas), lo cual mejora la resistencia y disminuye los fuertes dolores de espalda pélvicos", "Asistir de manera proactiva a clases informativas de preparación y educación para el parto"] } ], note: "Las mujeres con embarazos de bajo riesgo a menudo son candidatas perfectas para que su parto y vigilancia sean liderados o atendidos exclusivamente por matronas experimentadas, y pueden intentar el parto natural vaginal sin gran medicalización." }, whenToSeekHelp: { title: "¿Cuándo debes acudir a Urgencias Obstétricas?", intro: "Incluso si todo va perfecto y tienes bajo riesgo, una emergencia puede surgir. Dirígete inmediatamente a urgencias médicas o llama a tu médico si tienes:", items: ["Un sangrado vaginal que es de color rojo brillante o abundante (no un leve manchado marrón), especialmente si está acompañado de calambres", "Experimentas un dolor o presión abdominal que sea agudo, repentino, intenso, constante o que no desaparece al descansar", "Padeces dolores de cabeza muy severos y continuos, ves manchas o destellos de luz, o tienes una hinchazón muy repentina e inusual en el rostro o en las manos (son los signos clásicos de la peligrosa preeclampsia)", "Sientes que te sale o pierdes un líquido claro y acuoso por la vagina en un chorro o goteo constante antes de la semana 37 (rotura prematura de membranas o 'romper fuente')", "Te das cuenta de que tu bebé ha dejado de moverse por completo de forma súbita, o que el patrón de sus patadas ha disminuido drásticamente en comparación a su rutina diaria normal", "Sufres de fiebre alta o tienes fuertes ardores dolorosos constantes al orinar"] } },
'Cáncer de útero' : { intro: "El cáncer de útero es la aparición y crecimiento descontrolado de células anormales y malignas en los tejidos del útero. Existen principalmente dos tipos: el que nace en la pared interna (endometrio) y el que nace en los músculos del útero (sarcoma).", whatIs: { title: "¿Qué es el Cáncer de Útero?", text: "El término agrupa a dos grandes enfermedades, aunque casi siempre se usa para referirse al Cáncer de Endometrio, que representa más del 90% de los casos. Este tipo es el cáncer ginecológico más común en países desarrollados. Como a menudo provoca sangrado vaginal anormal desde temprano, suele detectarse en sus primeras etapas, cuando el pronóstico de supervivencia tras la cirugía es inmejorable." }, types: { title: "Tipos Oncológicos y Clasificación", intro: "Médicamente, se separan por la capa uterina afectada y el tipo de célula:", items: ["Cáncer de endometrio (Adenocarcinoma): Comienza en las glándulas del revestimiento interno del útero (endometrio). Su causa suele estar fuertemente vinculada a un desequilibrio hormonal (exceso de estrógeno en el cuerpo de la mujer sin progesterona que lo contrarreste).", "Sarcoma uterino: Un tipo de tumor sumamente raro pero muy agresivo que se origina en el músculo profundo de la pared uterina (miometrio) o en su tejido conectivo.", "Carcinosarcoma uterino: Un tipo mixto e infrecuente que tiene características de ambas patologías."], note: "El cáncer del cuello uterino (cérvix) es una enfermedad completamente diferente originada por el VPH, a pesar de estar conectado al útero." }, diagnosis: { title: "Procedimientos de Confirmación Especializada", intro: "El cáncer de útero NO se puede detectar con el examen preventivo del Papanicolaou. El ginecólogo ordenará:", items: ["Ecografía transvaginal o pélvica (la herramienta inicial y más importante, mediante ultrasonido el médico mide el grosor del revestimiento interno endometrial; si es anormalmente grueso, es una alerta principal)", "Biopsia de endometrio en consultorio (el paso fundamental; el médico inserta un tubo fino a través de la vagina hasta el útero para succionar una pequeña muestra de tejido y enviarla a los patólogos para buscar células cancerosas)", "Histeroscopia diagnóstica ambulatoria (insertar un diminuto telescopio iluminado en el útero para visualizar pólipos o tumores e inspeccionar directamente)", "Tomografías o Resonancia Magnética de pelvis y abdomen (solo realizadas tras confirmarse el cáncer, con el fin de evaluar si las células malignas se han diseminado -estadificación- a la vejiga, intestinos o ganglios linfáticos pélvicos)"], note: "" }, treatment: { title: "Intervenciones Quirúrgicas y Adyuvantes", intro: "La cirugía extirpativa es el primer y más importante paso, curando la inmensa mayoría de casos si el cáncer no ha atravesado la pared uterina:", subsections: [ { title: "Terapia y Enfoque Oncológico", items: ["Cirugía de Histerectomía (el tratamiento de oro: el ginecólogo oncólogo extirpa completamente y extrae el útero junto con el cuello uterino; casi siempre se incluyen y extirpan también ambos ovarios y trompas de Falopio -salpingooforectomía- y algunos ganglios pélvicos preventivamente)", "Radioterapia local y pélvica (frecuentemente administrada semanas después de la cirugía para aniquilar cualquier célula tumoral que haya quedado oculta en la pelvis o la zona de la vagina superior, y reducir fuertemente el riesgo de recaída y retorno)", "Terapia médica hormonal bloqueadora (el uso de progesterona en pastillas fuertes para detener y frenar el avance celular si el tumor dependía del estrógeno y se ha extendido)", "Quimioterapia e Inmunoterapia general sistémica (fármacos por vena que se utilizan en casos donde el cáncer es un sarcoma, es del tipo 2 agresivo, o si el tumor original ha hecho gran metástasis invadiendo y saliendo fuera del entorno pélvico hacia los pulmones o el abdomen lejano)"] } ], note: "La extirpación radical total del útero provoca que la mujer no pueda volver a quedar embarazada y, si se le quitan los ovarios de joven, le inducirá una menopausia prematura y repentina." }, whenToSeekHelp: { title: "¿Cuándo es imperativo ir a urgencias o al ginecólogo?", intro: "De la alerta y atención rápida de la mujer dependen las altas tasas de curación. Ve al médico velozmente si presentas:", items: ["El síntoma principal e inequívoco de alerta máxima: CUALQUIER tipo de sangrado vaginal, flujo rosado, gotas pequeñas o grandes hemorragias, manchas, si tú ya has pasado por la etapa de la menopausia (la falta de regla de un año)", "Si eres más joven y tienes menstruación, un sangrado anormalmente errático e inusual entre tus ciclos menstruales (sangrados intermenstruales)", "Periodos menstruales que de manera repentina son exageradamente prolongados en su duración o que expulsan enormes y anormales coágulos continuos", "Un dolor opresivo sordo, un peso o un calambre profundo y crónico instalado en la zona pélvica o la parte inferior del estómago que es constante y muy doloroso al mantener relaciones sexuales profundas y no mejora en semanas"] } },
'TAG' : { intro: "El Trastorno de Ansiedad Generalizada (TAG) es una afección mental crónica y debilitante en la que la persona experimenta una preocupación y tensión excesivas, persistentes y difíciles de controlar sobre diversos eventos o actividades cotidianas.", whatIs: { title: "¿Qué es el TAG?", text: "Es un estado de ansiedad constante que no está ligado a una amenaza real y única. El cerebro del paciente hiperanaliza escenarios catastróficos frente a situaciones normales (trabajo, salud, dinero o familia). Esta preocupación es desproporcionada y altera significativamente la calidad de vida y el descanso." }, types: { title: "Síntomas y Manifestaciones", intro: "El TAG afecta tanto la mente como el cuerpo físico:", items: ["Pensamientos intrusivos y preocupación incesante que no se puede 'apagar' a voluntad", "Inquietud motora, sensación de estar 'al límite' o con los nervios de punta", "Fatiga crónica, agotamiento fácil y problemas graves de concentración (niebla mental)", "Tensión muscular persistente (especialmente en cuello, hombros y mandíbula)", "Trastornos del sueño (dificultad para conciliar el sueño o despertares continuos)"], note: "Para un diagnóstico oficial, los síntomas deben estar presentes la mayor parte de los días durante al menos seis meses." }, diagnosis: { title: "Evaluación Psiquiátrica y Psicológica", intro: "El diagnóstico clínico requiere descartar problemas físicos que imitan la ansiedad:", items: ["Entrevista clínica exhaustiva con un psicólogo o psiquiatra (basada en el manual DSM-5)", "Análisis de sangre y pruebas de función tiroidea (para descartar hipertiroidismo, que genera síntomas idénticos a la ansiedad)", "Revisión de consumo de sustancias (el exceso de cafeína, medicamentos o abstinencia pueden causar cuadros similares)"], note: "" }, treatment: { title: "Terapia Conductual y Regulación Química", intro: "El TAG es muy tratable, y una combinación de herramientas es el estándar de oro:", subsections: [ { title: "Opciones de Tratamiento", items: ["Terapia Cognitivo-Conductual (TCC) (el tratamiento psicológico más eficaz; enseña a identificar y modificar los patrones de pensamiento catastróficos y las reacciones ante el estrés)", "Medicamentos antidepresivos de mantenimiento (los ISRS, como escitalopram o sertralina, y los IRSN, son la primera línea médica para regular la química cerebral a largo plazo)", "Medicamentos ansiolíticos o para crisis (Benzodiacepinas o Buspirona, recetados generalmente a corto plazo para mitigar ataques agudos)", "Técnicas de regulación del sistema nervioso (meditación mindfulness, respiración diafragmática profunda y ejercicio aeróbico regular)"] } ], note: "La recuperación lleva tiempo y los medicamentos pueden tardar de 4 a 6 semanas en mostrar su máximo beneficio." }, whenToSeekHelp: { title: "¿Cuándo solicitar asistencia profesional?", intro: "Es fundamental buscar apoyo médico y terapéutico si:", items: ["Sientes que la preocupación excesiva interfiere directamente con tu trabajo, tus relaciones o tu capacidad para disfrutar la vida", "Experimentas ataques de pánico repentinos (taquicardia intensa, falta de aire, miedo a morir o perder el control)", "Te sientes profundamente deprimido, aislado, o recurres al alcohol o drogas para poder relajarte", "Tienes pensamientos de hacerte daño o ideas suicidas (acude a urgencias o llama a líneas de ayuda de inmediato)"] } },
'Nefrolitiasis' : { intro: "La nefrolitiasis, comúnmente conocida como cálculos renales o piedras en los riñones, es la formación de masas sólidas de minerales y sales cristalizadas dentro de la estructura de los riñones, provocando un dolor severo al desplazarse.", whatIs: { title: "¿Qué es la Nefrolitiasis?", text: "Es una enfermedad metabólica y urológica. Ocurre cuando hay un desequilibrio en la orina: demasiados elementos formadores de cristales (calcio, oxalato, ácido úrico) y muy poco líquido o sustancias que impidan que se peguen. Mientras la piedra está en el riñón rara vez duele, pero si cae y bloquea el estrecho uréter, provoca un espasmo violento (cólico nefrítico)." }, types: { title: "Tipos por Composición Química", intro: "Saber de qué está hecha la piedra es vital para evitar que se formen nuevas:", items: ["Cálculos de oxalato o fosfato de calcio (los más comunes, un 80% de los casos; ligados a baja hidratación y alta sal en la dieta)", "Cálculos de ácido úrico (comunes en personas con dietas ricas en carnes rojas y mariscos, o que padecen gota)", "Cálculos de estruvita (se forman casi exclusivamente como resultado de infecciones urinarias crónicas y crecen muy rápido)", "Cálculos de cistina (extremadamente raros, causados por un trastorno genético de los riñones)"], note: "La falta de ingesta abundante de agua es el denominador común en la mayoría de los episodios." }, diagnosis: { title: "Diagnóstico Clínico y de Urgencia", intro: "Ante el dolor incapacitante, el médico debe localizar el bloqueo con precisión:", items: ["Tomografía Computarizada (TC) abdominal sin contraste (la prueba definitiva de urgencia; detecta la piedra más minúscula y evalúa si hay daño u obstrucción severa en el riñón)", "Ecografía o ultrasonido renal (usada a menudo en mujeres embarazadas o niños para evitar la radiación, aunque es menos precisa para piedras pequeñas)", "Análisis de sangre y orina (para comprobar los niveles de creatinina, buscar infección oculta y sangre microscópica)", "Filtrado de la orina en casa para atrapar la piedra y llevarla a análisis de laboratorio"], note: "" }, treatment: { title: "Manejo del Dolor y Extracción", intro: "El abordaje depende enteramente del tamaño de la piedra y su posición anatómica:", subsections: [ { title: "Opciones Clínicas y Quirúrgicas", items: ["Terapia expulsiva conservadora (para piedras de menos de 5mm: beber de 2.5 a 3 litros de agua, analgésicos fuertes y medicamentos alfabloqueantes como tamsulosina para relajar el conducto uretral y dejarla caer sola)", "Litotricia extracorpórea por ondas de choque (LEOC) (una máquina externa envía fuertes ondas de sonido al riñón que pulverizan la piedra en arena para poder orinarla)", "Ureteroscopia quirúrgica (el urólogo introduce una microcámara por la uretra, sube hasta la piedra y la atrapa con una canastilla o la rompe con un láser; no requiere incisiones)", "Nefrolitotomía percutánea (cirugía a través de la espalda reservada para cálculos masivos que ocupan todo el riñón)"] } ], note: "Sin cambios radicales en la hidratación y la dieta, el riesgo de volver a formar un cálculo en los próximos 5 años es de un 50%." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias inmediatamente?", intro: "El cólico nefrítico es una de las afecciones más dolorosas. Ve a urgencias de inmediato si presentas:", items: ["Dolor lumbar o en el flanco abdominal tan severo, agudo y punzante que te impide sentarte, hablar o encontrar una sola posición cómoda", "El dolor incontrolable está acompañado de náuseas repetitivas y vómitos constantes", "Desarrollas fiebre alta y escalofríos intensos junto con el dolor (esto es una emergencia médica letal que indica que el riñón está bloqueado e infectado, pudiendo causar sepsis)", "Notas sangre de color rojo brillante o marrón en la orina, o de repente no puedes orinar en absoluto"] } },
'Sinusitis crónica' : { intro: "La sinusitis crónica, o rinosinusitis crónica, es una afección común en la que las cavidades alrededor de los conductos nasales (los senos paranasales) se inflaman e hinchan profundamente durante al menos 12 semanas consecutivas, a pesar de los intentos de tratamiento médico.", whatIs: { title: "¿Qué es la Sinusitis Crónica?", text: "Es una enfermedad inflamatoria prolongada. Normalmente, los senos paranasales están vacíos y llenos de aire. Cuando se inflaman de forma crónica, se bloquean y se llenan de mucosidad espesa, lo que interfiere con el drenaje normal, dificulta la respiración por la nariz y causa un dolor sordo y constante de presión en la cara." }, types: { title: "Causas y Subtipos", intro: "Esta inflamación crónica rara vez es por una simple bacteria; suele deberse a problemas anatómicos o inmunes:", items: ["Sinusitis crónica con pólipos nasales (crecimientos de tejido blando en forma de uva dentro de la nariz que bloquean físicamente los conductos)", "Sinusitis crónica sin pólipos (inflamación pura de la mucosa)", "Causas anatómicas (desviación severa del tabique nasal que tapona el drenaje)", "Alergias crónicas (como la rinitis alérgica severa, asma o fiebre del heno)", "Infecciones por hongos o deficiencias del sistema inmunológico"], note: "Fumar y la exposición constante a contaminantes o polvo exacerba gravemente la inflamación de la mucosa." }, diagnosis: { title: "Evaluación Otorrinolaringológica", intro: "El diagnóstico médico debe identificar exactamente por qué no drena la nariz:", items: ["Endoscopia nasal (el especialista introduce un tubo muy delgado con luz y cámara por la nariz para inspeccionar visualmente los senos, detectar pólipos y buscar bloqueos)", "Tomografía Computarizada (TC) de senos paranasales (la prueba de imagen de oro para obtener un mapa detallado en 3D de la anatomía y ver el tejido o mucosidad oculta donde el endoscopio no llega)", "Pruebas cutáneas de alergia (para identificar si un alérgeno ambiental está causando el daño constante)", "Cultivos de mucosidad nasal (para descartar o confirmar hongos o bacterias súper resistentes)"], note: "" }, treatment: { title: "Desinflamación y Drenaje Quirúrgico", intro: "El objetivo primario es reducir la inflamación y mantener abiertos los canales de drenaje:", subsections: [ { title: "Abordajes Médicos y Quirúrgicos", items: ["Lavados nasales diarios (irrigaciones con solución salina usando botellas o dispositivos neti pot para limpiar los irritantes mecánicamente)", "Corticosteroides nasales en aerosol (el tratamiento de primera línea para apagar la inflamación a largo plazo)", "Corticosteroides orales (como la prednisona, recetados en cursos cortos y potentes para casos severos con pólipos masivos)", "Terapias biológicas inyectables (como dupilumab, para pólipos graves resistentes a esteroides)", "Cirugía Endoscópica Funcional de Senos Paranasales (CESS) (cuando todo lo demás falla, el cirujano usa herramientas por la nariz para agrandar físicamente las aberturas naturales y extirpar pólipos)"] } ], note: "Los antibióticos tradicionales casi nunca curan la sinusitis crónica, ya que suele ser un problema de inflamación y no de infección." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar al médico especialista?", intro: "Debes buscar evaluación médica avanzada si has tenido varios episodios de sinusitis aguda o si presentas:", items: ["Congestión nasal severa, presión en la frente, dolor de dientes superiores o detrás de los ojos que dura más de 12 semanas", "Pérdida casi total de los sentidos del olfato y el gusto", "Presentas síntomas de alarma (emergencia): fiebre alta repentina, hinchazón muy dolorosa y enrojecimiento alrededor o debajo de un ojo, visión doble o visión borrosa, o rigidez extrema en el cuello"] } },
'Cáncer de piel escamocelular' : { intro: "El cáncer de piel escamocelular, o carcinoma de células escamosas, es el segundo tipo más común de cáncer de piel. Aunque no suele ser tan agresivo como el melanoma, si no se trata, puede crecer profundamente, dañar nervios o propagarse (hacer metástasis) a otras partes del cuerpo.", whatIs: { title: "¿Qué es el Carcinoma de Células Escamosas?", text: "Es un crecimiento descontrolado y anormal de las células escamosas, que conforman las capas media y externa de la piel. Es el resultado directo y acumulativo del daño en el ADN celular provocado por la exposición prolongada a la radiación ultravioleta (UV) del sol o de las camas de bronceado a lo largo de los años." }, types: { title: "Ubicaciones y Apariencia", intro: "Suele aparecer en las áreas más expuestas y dañadas por el sol:", items: ["Rostro, cuero cabelludo calvo, orejas, cuello, labios y el dorso de las manos", "Puede verse como un nódulo rojo y firme al tacto", "A menudo se presenta como una llaga plana que está constantemente cubierta por una costra áspera o escamosa", "Puede formarse sobre una cicatriz vieja, úlceras crónicas en las piernas o en las membranas mucosas (como la boca o los genitales)"], note: "A menudo está precedido por lesiones ásperas precancerosas conocidas como 'queratosis actínicas'." }, diagnosis: { title: "Examen Dermatológico Definitivo", intro: "El diagnóstico temprano garantiza tasas de curación casi totales:", items: ["Examen físico minucioso (el dermatólogo evaluará toda la piel del paciente y observará la lesión sospechosa de cerca, a menudo con un dermatoscopio)", "Biopsia de piel (la única prueba que confirma el cáncer; el médico adormece el área y extrae una parte o toda la lesión para que un patólogo la examine bajo un microscopio)"], note: "" }, treatment: { title: "Extirpación y Curación", intro: "El tratamiento depende del tamaño del tumor, su profundidad y dónde está ubicado en el cuerpo:", subsections: [ { title: "Opciones de Destrucción Tumoral", items: ["Escisión quirúrgica (el tratamiento más común: el médico corta el cáncer junto con un pequeño margen perimetral de piel completamente sana para asegurar que no quede nada)", "Cirugía Micrográfica de Mohs (el estándar de oro para tumores en el rostro, orejas o manos; el cirujano retira y analiza el tejido capa por minúscula capa en el laboratorio durante la misma cirugía, preservando al máximo el tejido estético sano)", "Curetaje y electrodesecación (se raspa el tumor y se quema la base con una aguja eléctrica, útil para cánceres pequeños)", "Radioterapia, quimioterapia tópica (cremas) o Inmunoterapia sistémica (usada exclusivamente si el tumor es inoperable o ha hecho metástasis a los ganglios linfáticos)"] } ], note: "Las personas que han tenido un carcinoma de células escamosas tienen un alto riesgo de desarrollar otro, por lo que requerirán controles de la piel de cuerpo entero cada 6 a 12 meses." }, whenToSeekHelp: { title: "¿Cuándo acudir urgentemente al dermatólogo?", intro: "Es fundamental programar una revisión médica inmediata si encuentras en tu piel:", items: ["Una costra, úlcera o llaga que sangra, se cae, intenta sanar, y vuelve a sangrar repetidamente en el mismo lugar exacto durante más de un mes", "Un bulto rojo, áspero y duro al tacto que está creciendo rápidamente en tamaño, especialmente en zonas expuestas al sol", "Cualquier parche rojo que se descama intensamente, duele al tocarlo o desarrolla un cuerno grueso de queratina en la superficie"] } },
'Adenomioma' : { intro: "Un adenomioma es un tumor o crecimiento focal benigno (no canceroso) que se forma en el útero. Es esencialmente una versión localizada y encapsulada de la adenomiosis, donde el tejido que recubre el útero invade su pared muscular.", whatIs: { title: "¿Qué es un Adenomioma?", text: "Normalmente, el endometrio (la capa que sangra cada mes) está solo en el interior de la cavidad uterina. En el caso de un adenomioma, un grupo de este tejido endometrial penetra profundamente y se incrusta en el miometrio (el músculo del útero), formando un nódulo o bulto sólido. Al igual que el periodo, este tejido sangra y se inflama cada mes dentro del músculo, causando mucho dolor." }, types: { title: "Diferenciación con otras Masas", intro: "Los adenomiomas se confunden habitualmente con otras patologías ginecológicas:", items: ["Diferencia con los Fibromas (Miomas): Los fibromas son tumores puros de músculo duro con bordes muy claros y fáciles de separar del útero; el adenomioma, en cambio, no tiene bordes definidos, está entremezclado e infiltrado en el músculo sano, lo que hace su extirpación mucho más difícil.", "Adenomiosis difusa: A diferencia del adenomioma (que es un solo bulto localizado), la adenomiosis difusa afecta engrosando a todo el útero de manera general."], note: "Su causa es incierta, pero depende absolutamente del estrógeno para crecer y provocar síntomas." }, diagnosis: { title: "Investigación y Pruebas Ginecológicas", intro: "Por ser tan similar a los miomas, el diagnóstico requiere de buena imagenología:", items: ["Ecografía transvaginal o pélvica (la prueba inicial, puede mostrar una masa heterogénea asimétrica en la pared muscular del útero)", "Resonancia Magnética Pélvica (RM) (el estándar de oro para diferenciar sin dudas un adenomioma de un fibroma común, lo cual es vital antes de planear cualquier cirugía)", "Histeroscopia o biopsia (a veces se utilizan para descartar que el sangrado no sea causado por cáncer endometrial)"], note: "" }, treatment: { title: "Manejo Médico o Resolución Quirúrgica", intro: "El tratamiento se basa en la severidad del dolor, el sangrado y el deseo de la mujer de quedar embarazada en el futuro:", subsections: [ { title: "Intervenciones", items: ["Fármacos antiinflamatorios (AINEs como ibuprofeno para controlar severamente el dolor durante la menstruación)", "Terapias hormonales (Anticonceptivos orales, parches o el DIU hormonal Mirena; son la primera línea de defensa para detener el sangrado excesivo y 'secar' o encoger el tejido aberrante)", "Ablación endometrial o embolización de arterias uterinas (procedimientos para reducir el sangrado sin quitar el útero)", "Cirugía de resección o adenomiomectomía (intentar cortar solo el tumor; es complejo porque sus bordes se funden con el útero sano)", "Histerectomía (la extirpación completa del útero es la única cura definitiva al 100%, elegida cuando la mujer ya no desea tener hijos y los síntomas son incapacitantes)"] } ], note: "La afección y sus dolorosos síntomas desaparecerán de forma natural cuando la mujer alcance la menopausia (al caer los niveles de estrógeno)." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar al ginecólogo?", intro: "Debes agendar una cita médica especialista si padeces de:", items: ["Menstruaciones extremadamente abundantes (menorragia), necesitando cambiar toallas o tampones cada 1 o 2 horas, o expulsando coágulos del tamaño de una moneda", "Cólicos menstruales insoportables, punzantes e incapacitantes que empeoran a medida que envejeces y no ceden con analgésicos normales", "Un dolor sordo, crónico y de presión en el bajo vientre o la pelvis en cualquier momento del mes", "Dolor intenso y profundo durante las relaciones sexuales"] } },
'Malformación anorrectal' : { intro: "Una malformación anorrectal (MAR) o ano imperforado es un defecto congénito complejo que ocurre mientras el feto se desarrolla en el útero. Significa que el ano (la abertura por donde salen las heces) o el recto (la porción final del intestino) no se formaron correctamente.", whatIs: { title: "¿Qué es una Malformación Anorrectal?", text: "Es una anomalía estructural al nacer. Puede presentarse de varias formas: el ano puede faltar por completo, estar en el lugar equivocado, o el recto puede estar conectado anormalmente a otros órganos (como la uretra, la vejiga o la vagina) mediante un túnel llamado fístula. Esto impide que el bebé evacúe sus heces de manera normal y segura." }, types: { title: "Clasificación Pediátrica Quirúrgica", intro: "Se dividen según dónde y cómo termina el intestino del bebé (altas o bajas):", items: ["Lesiones bajas (el recto ha bajado casi por completo a través de los músculos del esfínter, pero hay una membrana de piel sobre el ano o es extremadamente estrecho)", "Lesiones altas (el recto termina mucho antes de llegar a los músculos del suelo pélvico o esfínteres, siendo casos más complejos)", "Presencia de Fístulas (casi todos los bebés con MAR tienen una fístula que conecta su intestino con la vejiga en niños, o con la vagina/vestíbulo en niñas, expulsando las heces por la vía urinaria)"], note: "Frecuentemente se asocian a otros problemas de nacimiento conocidos como asociación VACTERL (defectos vertebrales, cardíacos, traqueales, renales y de extremidades)." }, diagnosis: { title: "Detección Neonatal e Imagenología", intro: "El diagnóstico es muy evidente inmediatamente después del nacimiento:", items: ["Examen físico del recién nacido (el pediatra neonatólogo observará directamente la ausencia de ano en el chequeo inicial en la sala de partos)", "Ecografía abdominal y pélvica, o radiografía lateral del bebé (invertido) para medir la distancia exacta entre el final del intestino ciego y la piel, crucial para planear la operación", "Ecocardiograma, ecografía de columna y riñones (obligatorios para buscar otras malformaciones ocultas asociadas a nivel cardíaco o renal)"], note: "" }, treatment: { title: "Reconstrucción Quirúrgica Neonatal", intro: "Todos los bebés con este diagnóstico requieren cirugía para poder defecar y sobrevivir; los pasos dependen de la gravedad:", subsections: [ { title: "Fases Quirúrgicas Comunes", items: ["Anoplastia perineal inmediata (para malformaciones bajas sencillas, el cirujano abre y conecta el recto directamente a la piel en los primeros días de vida)", "Fase 1 de Colostomía temporal (en casos altos o complejos, se crea una bolsa en el abdomen para desviar las heces en el primer día de vida, permitiendo al bebé comer y crecer seguro sin ensuciar la zona pélvica)", "Fase 2 de Tracción y Reconstrucción (Cirugía de Peña o PSARP: meses después, el cirujano pediátrico desciende el recto, cierra las fístulas urinarias/vaginales y crea el ano anatómicamente dentro de los músculos del esfínter original)", "Fase 3 de Cierre de colostomía (semana o meses después, se reconecta el intestino para que el niño use su nuevo ano)"] } ], note: "Muchos de estos niños necesitarán seguimiento médico estricto por años y terapias para manejar el estreñimiento crónico o la incontinencia fecal a medida que crecen." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia en el recién nacido?", intro: "Esta condición se detecta en el hospital al nacer. Sin embargo, un retraso diagnóstico es una emergencia quirúrgica si:", items: ["El bebé recién nacido no expulsa el meconio (la primera caca oscura y alquitranada) en sus primeras 24 a 48 horas de vida", "El bebé desarrolla un vientre sumamente hinchado (distensión abdominal), llora inconsolablemente por dolor o comienza a vomitar líquidos de color verde oscuro (bilis)", "Observas que las heces del bebé salen a través de la abertura urinaria de su pene, o a través de la vagina en una niña"] } },
'Cardiopatía coronaria' : { intro: "La cardiopatía coronaria (o enfermedad de las arterias coronarias) es la afección cardíaca más común en el mundo y la principal causa de muerte global. Ocurre cuando los vasos sanguíneos vitales que nutren al propio músculo del corazón se estrechan o bloquean severamente.", whatIs: { title: "¿Qué es la Cardiopatía Coronaria?", text: "Es el resultado directo de la aterosclerosis. A lo largo de los años, una placa dura y pegajosa compuesta de colesterol, grasa y calcio se acumula en las paredes internas de las arterias coronarias. Esto reduce drásticamente el espacio por el que fluye la sangre, privando al corazón del oxígeno y los nutrientes necesarios para latir, especialmente bajo esfuerzo físico." }, types: { title: "Manifestaciones Clínicas", intro: "Esta falta de flujo de sangre se puede manifestar de dos maneras principales:", items: ["Angina de pecho estable (un dolor o presión crónica y predecible en el pecho que se produce al hacer ejercicio o bajo estrés y que desaparece rápidamente al descansar)", "Síndrome Coronario Agudo (SCA) o Infarto de miocardio (una emergencia mortal en la que la placa de colesterol se rompe de repente, formando un coágulo de sangre que tapona la arteria al 100%, matando el tejido muscular del corazón por asfixia en minutos)"], note: "El tabaquismo, la diabetes y la presión arterial alta son los destructores más rápidos y letales de las arterias coronarias." }, diagnosis: { title: "Evaluación y Pruebas Vasculares", intro: "El diagnóstico preciso busca detectar si el corazón está sufriendo por falta de sangre:", items: ["Electrocardiograma (ECG) (registra la actividad eléctrica, pudiendo detectar infartos pasados o actuales)", "Prueba de esfuerzo (ergometría, se hace caminar al paciente en una cinta para ver cómo reacciona el corazón bajo presión)", "Ecocardiograma o Ecografía de estrés (para observar qué partes de la pared muscular del corazón no se mueven bien por falta de flujo)", "Cateterismo cardíaco o angiografía (el estándar de oro definitivo: se inyecta un tinte visible en rayos X por un tubo hasta el corazón para revelar el lugar y porcentaje exacto de obstrucción en cada arteria)"], note: "" }, treatment: { title: "Destapando Arterias y Control Médico", intro: "No tiene cura, pero se controla y las arterias se pueden abrir mecánicamente para evitar la muerte:", subsections: [ { title: "Terapias Intervencionistas y Farmacológicas", items: ["Cambios innegociables en el estilo de vida (dejar de fumar inmediatamente, dieta muy baja en grasas saturadas, control estricto de glucosa y ejercicio regular)", "Medicamentos para salvar el corazón (Estatinas para bajar agresivamente el colesterol, Aspirina para evitar coágulos mortales, y Betabloqueantes/Inhibidores de la ECA para relajar el corazón y bajar la presión)", "Angioplastia y colocación de Stent (procedimiento mínimamente invasivo donde se infla un pequeño globo dentro de la arteria tapada y se deja una malla de metal para mantenerla abierta)", "Cirugía de derivación coronaria o Bypass (cirugía a corazón abierto para crear un nuevo camino para la sangre, esquivando las arterias bloqueadas usando venas tomadas de la pierna o el pecho del paciente)"] } ], note: "Los pacientes que sobreviven a un infarto o se ponen un stent deben tomar religiosamente su medicación para evitar que este se vuelva a tapar en el futuro." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911 (Emergencia de Infarto)?", intro: "Si la enfermedad avanza al bloqueo total, es un ataque cardíaco. Llama a la ambulancia inmediatamente si sufres:", items: ["Un dolor de pecho agudo, opresión extrema, pesadez o sensación de que te aprietan fuertemente el centro del pecho", "Dolor o malestar persistente que se irradia hacia tu brazo izquierdo, la espalda, ambos hombros, el cuello, la mandíbula inferior o el área del estómago", "Sensación repentina de falta de aire asfixiante, acompañada de sudoración fría, náuseas, mareos o debilidad extrema y sensación de muerte inminente"] } },
'Infección del riñón' : { intro: "Una infección del riñón, cuyo nombre médico es pielonefritis, es un tipo severo y potencialmente peligroso de infección del tracto urinario (ITU). Si no se trata rápida y agresivamente con antibióticos, la infección puede destruir irreversiblemente los riñones o esparcir las bacterias por toda la sangre (sepsis mortal).", whatIs: { title: "¿Qué es la Pielonefritis?", text: "Generalmente, ocurre cuando las bacterias patógenas (como la E. coli) entran al cuerpo a través de la uretra, se multiplican en la vejiga (causando una cistitis común) y, de no ser detenidas, continúan viajando hacia arriba por los tubos de los uréteres hasta invadir profundamente el tejido interno de uno o ambos riñones." }, types: { title: "Causas y Complicaciones", intro: "Puede ser aguda o crónica, y se agrava por bloqueos:", items: ["Pielonefritis aguda (episodio súbito, repentino y doloroso con fiebre alta, es el cuadro clínico más común)", "Pielonefritis crónica (inflamaciones renales repetitivas que pasan desapercibidas y causan cicatrización permanente del riñón; a menudo por anomalías de nacimiento o reflujo de orina)", "Factores de riesgo mecánicos (si tienes piedras en el riñón o una próstata agrandada que bloquean el flujo de orina, el riesgo de que una bacteria se multiplique y llegue al riñón se dispara inmensamente)"], note: "Es más frecuente en mujeres debido a su uretra corta, pero en hombres o niños siempre es considerada una infección 'complicada' que requiere mucha atención médica." }, diagnosis: { title: "Detección Analítica y de Laboratorio", intro: "El diagnóstico en urgencias es rápido y confirmatorio mediante análisis biológicos:", items: ["Análisis general de orina (revelará niveles altísimos de glóbulos blancos -leucocitos-, bacterias y posiblemente sangre, indicando una infección mayor)", "Cultivo de orina (fundamental para determinar qué tipo exacto de bacteria está atacando el riñón y, crucialmente, identificar a qué antibiótico es sensible o resistente)", "Cultivo de sangre o Hemocultivo (se realiza en pacientes graves o con fiebre muy alta para comprobar si la bacteria ha cruzado a la sangre, causando bacteriemia)", "Ecografía o Tomografía Computarizada (TC) del riñón (para confirmar que el riñón no está bloqueado por una piedra que impida curar la infección, o para buscar abscesos de pus)"], note: "" }, treatment: { title: "Terapia Antibiótica Estricta", intro: "El tratamiento es imperativo y siempre requiere medicación prescrita, jamás remedios caseros:", subsections: [ { title: "Abordaje Médico Infeccioso", items: ["Antibióticos orales de amplio espectro (el tratamiento de primera línea de oro para casos no complicados; deben tomarse durante 7 a 14 días estrictos, incluso si te sientes mejor al segundo día, para no crear bacterias mutantes)", "Ingreso y hospitalización (si estás vomitando mucho, deshidratado, embarazada, o tienes fiebre muy alta, necesitarás antibióticos y líquidos directos por vía intravenosa en el hospital)", "Analgésicos fuertes o antipiréticos (para controlar el dolor de espalda intenso y bajar la fiebre)", "Cirugía urgente o nefrostomía (solo y exclusivamente si un cálculo o piedra renal bloqueada es la causa, para drenar el pus y la orina estancada y salvar el órgano)"] } ], note: "Beber cantidades masivas de agua es clave durante la recuperación para obligar mecánicamente a las bacterias a 'lavarse' y salir por el tracto urinario." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias médicas de inmediato?", intro: "Una infección renal puede convertirse en una sepsis letal en horas. Acude al hospital sin demora si experimentas dolor y ardor al orinar o urgencia, combinados con:", items: ["Fiebre muy alta, escalofríos severos o tiritonas corporales incontrolables", "Un dolor sordo, intenso, profundo y punzante en la zona media de la espalda (zona lumbar), el flanco, el costado, o irradiado hacia la ingle o bajo vientre", "Náuseas continuas o vómitos persistentes que te impiden retener los medicamentos y líquidos, o dolor abdominal agudo", "Tu orina es visualmente turbia, huele asquerosamente mal, o ves sangre clara, rosada o marrón mezclada en el inodoro"] } },
'Deficiencia de la hormona del crecimiento' : { intro: "La deficiencia de la hormona del crecimiento (GHD, por sus siglas en inglés) es un trastorno médico endocrinológico grave en el cual la glándula pituitaria (una pequeña glándula en la base del cerebro) no produce una cantidad suficiente de somatotropina, la hormona vital encargada del crecimiento y la regulación del metabolismo del cuerpo.", whatIs: { title: "¿Qué es la Deficiencia de GH?", text: "Es un fracaso en las señales de desarrollo del cuerpo. En los niños, su impacto es evidente: produce un crecimiento anormalmente lento y resulta en una baja estatura extrema, aunque sus proporciones corporales son normales. En los adultos, la hormona ya no dicta la altura, pero es crucial, y su deficiencia provoca alteraciones drásticas en la composición corporal, pérdida de masa muscular, problemas óseos y profundo agotamiento." }, types: { title: "Orígenes y Manifestaciones por Edad", intro: "La afección se clasifica según cuándo y por qué aparece:", items: ["GHD Congénita (los bebés nacen con la deficiencia, a veces vinculada a malformaciones genéticas del cerebro o de la pituitaria; suelen tener niveles bajos de azúcar letales al nacer y un crecimiento detenido desde los primeros meses)", "GHD Adquirida (ocurre más tarde en la niñez o en la edad adulta; suele ser la consecuencia directa de un traumatismo craneoencefálico severo, radioterapia en el cerebro, un tumor de la hipófisis u operaciones neuroquirúrgicas)", "GHD Idiopática (en la gran mayoría de los niños, no se puede encontrar y diagnosticar una causa médica evidente de la falla pituitaria)"], note: "Es vital diferenciarla del simple 'retraso constitucional' (niños que crecen tarde pero alcanzan estatura normal) y de las bajitas estaturas genéticas familiares." }, diagnosis: { title: "Pruebas de Estimulación Endocrina", intro: "Un endocrinólogo no puede simplemente medir el nivel de hormona, ya que esta se secreta en pulsos rápidos por la noche. Las pruebas incluyen:", items: ["Pruebas de provocación o estimulación hormonal (el estándar de oro médico: se inyecta un medicamento en el brazo del niño que obligatoriamente debería hacer que la pituitaria dispare la hormona del crecimiento; luego se extrae sangre cada 30 minutos por horas para ver si hubo un pico normal. Si los niveles se quedan bajos y planos, confirma la deficiencia)", "Análisis de sangre para marcadores (IGF-1 y IGFBP-3; proteínas producidas por el hígado en respuesta a la GH, mucho más estables de medir)", "Resonancia Magnética (RM) del cerebro y del hipotálamo (absolutamente obligatoria para descartar masas, tumores o quistes hipofisarios ocultos)", "Radiografía de la mano y muñeca izquierda (para determinar la 'edad ósea'; en niños con GHD los huesos maduran de forma increíblemente atrasada respecto a su edad real)"], note: "" }, treatment: { title: "Reemplazo Hormonal Diario", intro: "El tratamiento es altamente eficaz y exitoso si se inicia temprano en la niñez, antes de que los huesos terminen de fusionarse en la adolescencia:", subsections: [ { title: "Terapia de Reemplazo Sistémica", items: ["Inyecciones subcutáneas de Somatropina (hormona del crecimiento humana sintética y recombinante; es el tratamiento universal, se debe inyectar todos y cada uno de los días bajo la piel con dispositivos similares a los bolígrafos de insulina de diabéticos, durante años enteros hasta alcanzar la altura adulta o el hueso se cierre)", "Tratamiento y reemplazo en adultos (dosis más bajas de la misma hormona para reconstruir la densidad de los huesos, restaurar la fuerza de los músculos, revertir el agotamiento extremo crónico y reducir la grasa abdominal patológica)", "Cirugía cerebral (en el caso adquirido, si un gran tumor de la pituitaria es el que está aplastando las células y causando la deficiencia original)"] } ], note: "Los suplementos alimenticios comerciales, pastillas o polvos anunciados como 'estimuladores de la hormona del crecimiento' no funcionan en absoluto y son fraudes; solo la hormona inyectada es médicamente real y aprobada." }, whenToSeekHelp: { title: "¿Cuándo es imperativo acudir a un endocrinólogo pediatra?", intro: "El tiempo es fundamental para tratar a los niños con éxito. Pide evaluación pediátrica profunda si observas:", items: ["Que tu hijo está creciendo menos de 5 centímetros en total al año desde que cumplió los 3 años de edad", "Que la estatura de tu hijo se ha estancado de golpe o cae rápida y drásticamente hacia abajo en las líneas de la curva de la gráfica de crecimiento de su edad en los controles del pediatra", "Que el niño aparenta físicamente ser mucho, mucho menor que sus compañeros de clase, tiene proporciones de 'bebé' con acumulación de grasa facial o troncal inusual", "Que se aproxima la edad de la pubertad adolescente sin ningún tipo de desarrollo sexual"] } },
'Infección por VIH' : { intro: "El VIH (Virus de la Inmunodeficiencia Humana) es una infección viral crónica e incurable que ataca y destruye progresivamente el sistema inmunológico del cuerpo. Si no se trata adecuadamente, el VIH debilita severamente las defensas, conduciendo eventualmente a la enfermedad conocida como SIDA (Síndrome de Inmunodeficiencia Adquirida).", whatIs: { title: "¿Qué es la Infección por VIH?", text: "El VIH es un virus de transmisión sanguínea y sexual. Su objetivo biológico es invadir y destruir un tipo de glóbulo blanco muy específico y vital, las células T CD4, que son los 'generales' del sistema inmunitario del cuerpo. Al reducirse el número de estas células, el organismo humano pierde su capacidad de combatir y vencer infecciones comunes y ciertos tipos de cáncer, quedando expuesto a peligros letales." }, types: { title: "Fases y Progresión Viral Clínicas", intro: "Sin medicamentos, el virus avanza destruyendo al paciente a lo largo de los años en tres etapas:", items: ["Fase 1: Infección aguda (de 2 a 4 semanas después del contagio; el paciente puede sufrir síntomas intensos similares a una gripe severa o mononucleosis, mientras el virus se multiplica explosivamente y es altamente contagioso en la sangre)", "Fase 2: Latencia clínica o fase crónica asintomática (el virus sigue multiplicándose pero a niveles bajos; esta fase silenciosa puede durar hasta 10 años o más sin ningún síntoma, pero el paciente sigue contagiando el virus si no toma medicación)", "Fase 3: SIDA (la etapa terminal y fatal sin tratamiento; el sistema inmunológico está completamente devastado (menos de 200 células CD4) y el paciente sufre de infecciones 'oportunistas' catastróficas, neumonías raras, tuberculosis o cánceres severos que normalmente el cuerpo mataría fácil)"], note: "El VIH se transmite principalmente a través del contacto sexual sin preservativo, compartiendo agujas o jeringas intravenosas para drogas, y de una madre infectada no tratada a su bebé durante el embarazo, el parto o la lactancia materna." }, diagnosis: { title: "Pruebas de Detección de Laboratorio Inmune", intro: "Saber tu estado es vital. No se puede diagnosticar por síntomas, ya que el virus se esconde. Se usan:", items: ["Pruebas de antígenos/anticuerpos en sangre venosa (la prueba de laboratorio de oro; busca anticuerpos producidos contra el virus y la proteína p24 producida por el propio virus; puede detectar el VIH desde los 18 a 45 días tras la exposición)", "Pruebas de carga viral o Ácidos Nucleicos NAT (busca la presencia real de la carga del virus en la sangre, es muy costosa pero puede confirmar la infección tan solo de 10 a 33 días después del contagio)", "Pruebas rápidas de anticuerpos en el dedo o saliva caseras (son útiles para cribado inicial, pero si salen positivas, siempre y obligatoriamente deben ser confirmadas por pruebas de sangre de un laboratorio y médico)"], note: "" }, treatment: { title: "Terapia Antirretroviral (TAR) y Prevención Farmacológica", intro: "Aunque no hay cura mágica, los medicamentos actuales son milagrosos: paralizan al virus y permiten vivir una vida completamente larga y normal:", subsections: [ { title: "Tratamientos, Control Diario y Profilaxis", items: ["Tratamiento Antirretroviral (TAR) de por vida (uso diario ininterrumpido de píldoras o inyecciones bimestrales que combinan fármacos para bloquear al virus, impidiendo totalmente que se multiplique y dando la oportunidad al sistema inmunitario de regenerarse a niveles sanos y recuperar las células CD4)", "Indetectable es igual a Intransmisible (I=I) (el tratamiento TAR es tan poderoso y eficaz hoy en día que reduce la cantidad de virus en el cuerpo a un nivel 'indetectable' en los análisis; la ciencia ha comprobado irrefutablemente que una persona indetectable no puede transmitir el virus por vía sexual a otra persona)", "PrEP o Profilaxis Preexposición (píldoras preventivas diarias que pueden tomar las personas sanas que no tienen el virus para reducir su riesgo de infectarse por sexo casi en un 99%)", "PEP o Profilaxis Posexposición (pastillas de emergencia, que debes tomar obligatoriamente en las 72 horas posteriores a una posible exposición de riesgo al virus -violación o rotura de preservativo- para intentar evitar y abortar que la infección se instale y agarre en el cuerpo)"] } ], note: "Una persona diagnosticada de forma temprana y que toma su TAR rigurosamente a diario, tiene la misma esperanza y años de vida que alguien sin VIH." }, whenToSeekHelp: { title: "¿Cuándo acudir a revisión, emergencias o buscar pruebas?", intro: "Es fundamental buscar atención médica y testeo especializado en infecciones inmediatamente si:", items: ["Crees que has estado potencialmente expuesto al virus en los últimos 3 días (rotura de condón, agresión, uso de agujas ajenas) para que un médico de urgencias te recete las pastillas preventivas PEP de emergencia antes de 72 horas", "Presentas la repentina aparición (semanas después de un contacto de riesgo sin protección) de fiebre alta, escalofríos, sudores intensos y profusos por la noche, ganglios y nodos linfáticos muy inflamados en el cuello o ingle, sarpullidos o fatiga tipo gripe severa, y dolor de garganta y boca", "Tienes una vida sexual activa con múltiples parejas; el consejo de salud estándar es hacerse la prueba analítica sanguínea del VIH y enfermedades venéreas cada 6 o 12 meses de manera estrictamente preventiva e informativa"] } },
'Congoja' : { intro: "La congoja, frecuentemente conocida como duelo profundo (grief o bereavement), es la respuesta humana y natural de sufrimiento ante una pérdida inmensa, habitualmente la muerte de un ser querido cercano, un hijo o una pareja. Aunque es un proceso normal de la vida, su impacto mental, emocional y físico es devastador y asimilable a un trauma grave.", whatIs: { title: "¿Qué es el Duelo Profundo o Congoja?", text: "Es la experiencia multidimensional y sumamente dolorosa de vivir sin lo que se amaba. Afecta los pensamientos, las emociones más profundas, los comportamientos físicos e interrumpe radicalmente el sueño y el apetito. El cerebro en estado de duelo se encuentra bajo un estrés tóxico y abrumador mientras intenta reconfigurar una realidad en la que la persona ya no existe." }, types: { title: "El Espectro del Duelo y Trastorno Clínico", intro: "Aunque la congoja no es una enfermedad psiquiátrica estándar, puede convertirse en una si el cerebro es incapaz de procesarla con el tiempo:", items: ["Duelo agudo normal (la respuesta inicial esperada; oleadas intensas de llanto, shock, negación, ira y dolor abrumador que van disminuyendo gradualmente en intensidad con el paso de los meses, y la persona, aunque triste, puede volver a funcionar en su vida)", "Duelo anticipado (la congoja y el sufrimiento empiezan antes de que ocurra la pérdida real, muy común cuando un familiar es diagnosticado con una enfermedad terminal larga o cáncer y Alzheimer)", "Trastorno de Duelo Prolongado o Complicado (una condición clínica grave añadida al DSM-5; ocurre cuando pasa más de un año y el dolor inicial agudo, la incredulidad, el anhelo paralizante o la amargura por la muerte NO disminuyen en absoluto, e impiden completamente que la persona retome cualquier rutina de la vida, aislándola en un estado de congelación emocional)"], note: "El duelo no tiene un cronograma fijo y no es lineal (no sigue las famosas 'etapas' paso a paso, sino que viene en forma de oleadas impredecibles de tristeza)." }, diagnosis: { title: "Evaluación del Duelo Complicado por Psiquiatría", intro: "Si la congoja incapacita al individuo a largo plazo, el psicólogo o psiquiatra evaluará los criterios de riesgo mental:", items: ["Entrevista clínica y de contención emocional compasiva", "Evaluación de los criterios diagnósticos (para el trastorno prolongado se busca anhelo intenso de la persona que ocupa la mente gran parte del día, negación crónica del suceso o evitación constante de cualquier cosa que recuerde a la muerte, prolongado más de 12 meses)", "Análisis estricto para diferenciar o hallar coexistencia del duelo con una Depresión Mayor Severa o con el Trastorno de Estrés Postraumático (TEPT, si la muerte fue violenta o trágica)", "Evaluación innegociable y directa de ideas, planes o pensamientos suicidas en el afectado"], note: "" }, treatment: { title: "Terapia de Apoyo, Sanación Psicológica y Farmacología", intro: "El objetivo del tratamiento no es 'olvidar' al fallecido ni borrar la tristeza, sino enseñar a la mente a procesar la herida para poder integrar el dolor y avanzar en la vida:", subsections: [ { title: "Rutas de Acompañamiento y Terapia", items: ["Terapia del Duelo Complicado o Psicoterapia (el estándar primordial de tratamiento; una modalidad psicológica centrada en procesar el trauma de la pérdida, restaurar las relaciones y redefinir las metas vitales sin el ser querido)", "Grupos de apoyo y terapia grupal de duelo (conectar con otras personas que han sufrido la muerte de un hijo o cónyuge es uno de los mayores factores de salvación y prevención del aislamiento total)", "Terapia Cognitivo-Conductual (TCC) (para ayudar a reestructurar y manejar los sentimientos extremos de culpa inmerecida, ira profunda, reproche u obsesión sobre cómo ocurrió la muerte)", "Medicamentos farmacológicos (el duelo normal no se medica para no bloquear las emociones; sin embargo, si el médico diagnostica depresión clínica coexistente grave, ataques de pánico o insomnio severo incapacitante de meses, se recetarán temporalmente antidepresivos -ISRS- o pastillas para dormir)"] } ], note: "Es vital ser muy paciente; presionar a alguien con frases como 'tienes que superarlo ya' o 'sé fuerte' aumenta el dolor; la congoja necesita ser expresada." }, whenToSeekHelp: { title: "¿Cuándo es imperativo buscar urgencia y apoyo psiquiátrico?", intro: "Debes buscar ayuda profesional y de líneas de salud mental de inmediato, sin importar el tiempo transcurrido, si experimentas:", items: ["Pensamientos constantes, planificación e ideación suicida, o un deseo persistente y real de querer morir o lastimarte para estar junto a la persona fallecida", "Una incapacidad severa de mantener y cuidarte a ti mismo y tu higiene diaria, negándote por completo a comer, salir de la cama o abandonar la casa por meses", "Sientes que el tiempo se ha congelado, tu dolor no ha disminuido en absoluto después de doce largos meses, y la angustia profunda y el anhelo dominan obsesiva y completamente tu día a día, destruyendo tu trabajo y demás relaciones personales", "El desarrollo de alucinaciones (fuera de las de consuelo del inicio) o crees ciegamente y te comportas como si la persona fallecida estuviera aún viva y presente"] } },
'Lesiones ligamentarias de rodillas' : { intro: "Las lesiones ligamentarias de la rodilla abarcan esguinces, desgarros parciales o rupturas completas de uno o varios de los cuatro potentes ligamentos (bandas de tejido conectivo) que unen el fémur con la tibia y le dan estabilidad mecánica y estructura a la articulación de la rodilla, siendo lesiones temidas y devastadoras, especialmente en el mundo del deporte de contacto o alto impacto.", whatIs: { title: "¿Qué es una Lesión de los Ligamentos de Rodilla?", text: "La rodilla humana depende de cuatro ligamentos para no desarmarse. Cuando un impacto severo, una torcedura extrema o un freno muy brusco llevan a la rodilla más allá de su rango límite de movimiento físico, la fuerza sobrepasa a los ligamentos y estos se estiran en exceso (esguince) o, en el peor de los casos, se rompen y parten por la mitad o se desprenden del hueso (ruptura total). Esto inutiliza la función biomecánica normal de la pierna y causa una peligrosa inestabilidad crónica ('pierna de trapo') si no se opera o repara." }, types: { title: "Tipos de Ligamentos y Su Rotura Traumática", intro: "Existen cuatro ligamentos principales en tu rodilla, y su rotura depende del mecanismo del accidente:", items: ["Rotura del Ligamento Cruzado Anterior o LCA (es con diferencia la más común, temida y operada; ocurre a menudo en fútbol, esquí o baloncesto por frenadas súbitas o cambios letales de dirección rápidos, o al caer mal de un salto. Da una inmensa inestabilidad para correr o girar)", "Lesión del Ligamento Cruzado Posterior o LCP (menos común, requiere de un impacto directo extremo y de altísima fuerza contra la parte frontal alta de la tibia o rodilla doblada, típico del 'golpe contra el salpicadero' en accidentes de coche a alta velocidad o al caer fuertemente de rodillas)", "Esguince del Ligamento Colateral Medial o LCM (situado en la parte interna de la rodilla; se rompe habitualmente y con dolor agudo por un impacto o golpe violento lateral desde fuera hacia adentro sobre la articulación, muy común en entradas de rugby y esquí)", "Lesión del Ligamento Colateral Lateral o LCL (ubicado en el lado de afuera; se lesiona por golpes en la parte interna)"], note: "Es tristemente habitual sufrir la 'Tríada infeliz', que es un desgarro grave, destructivo y simultáneo del LCA, del LCM y del menisco medial en un solo accidente grave de giro extremo." }, diagnosis: { title: "Evaluación Traumatológica Inmediata y Resonancia", intro: "Para conocer el diagnóstico y el destino del ligamento, el cirujano ortopédico realizará pruebas imperativas:", items: ["Examen físico articular y maniobras de gaveta especiales de la consulta (es el primer y fundamental paso médico; el traumatólogo agarrará y traccionará la tibia y la rodilla hacia adelante o a los lados comprobando su movilidad anormal. Por ejemplo, en la prueba de Lachman, si el hueso se desliza y 'cede' demasiado hacia adelante sin tope, indicará de inmediato una rotura total del importante LCA interno)", "Resonancia Magnética (RM) (el método estándar de oro médico y de uso obligatorio innegociable; a diferencia de los rayos X, la RM permite a los especialistas 'ver' claramente por dentro los propios tejidos blandos y mostrar con una asombrosa precisión el desgarro, inflamación o rotura por completo de cada filamento o tendón)", "Radiografías de rayos X de urgencia clásicas (se utilizan rutinariamente en hospitales siempre tras la caída y antes, no para ver el ligamento invisible en ellas, sino para descartar y verificar que el violento giro no haya causado una fractura grave de hueso o arrancado pedazos de la tibia -fractura por avulsión-)"], note: "" }, treatment: { title: "RICE, Rehabilitación Intensa o Reconstrucción de Quirófano", intro: "El tratamiento difiere monumentalmente dependiendo de cuál es el ligamento desgarrado y si el paciente desea recuperar su vida deportiva:", subsections: [ { title: "Terapias de Acción Médico-Deportivas", items: ["Protocolo de Primeros Auxilios R.I.C.E (para todos los esguinces inmediatos: absoluto Reposo de piernas, altísimo uso de Hielo continuo e indirecto en bolsa las primeras 48 hs para la inflamación, Compresión fuerte y Elevación máxima con cojín por encima del cuerpo para deshinchar), más fármacos antiinflamatorios (AINEs como ibuprofeno)", "Inmovilización ortopédica (uso médico obligatorio del uso de férulas inmovilizadoras, rodilleras rígidas largas y el uso de muletas sin poder poner peso para esguinces colaterales o esguinces puros menores mientras cicatrizan de forma natural durante semanas)", "Fisioterapia especializada y severa (ejercicios intensivos de rango y fortalecer enormemente el músculo del cuádriceps; el tratamiento principal y único necesario para desgarros o esguinces conservadores, e imprescindible tras operaciones)", "Cirugía mayor de Reconstrucción Ligamentaria Artroscópica (el único tratamiento definitivo y eficaz si hay una rotura completa total del LCA en una persona joven, deportista y atlética. El ligamento roto y destruido no se cose, sino que el cirujano toma el tendón rotuliano del paciente -o un tendón isquiotibial de un donante-, le hace unos túneles en el hueso, e implanta el nuevo tejido como un ligamento nuevo con tornillos. La rehabilitación dura de 6 a 12 meses)"] } ], note: "Tratar de regresar al impacto deportivo o al salto antes de la autorización y del permiso estricto del médico especialista y la fisioterapia final a menudo desencadena una dolorosa segunda nueva rotura aún más rápida de los implantes o de ligamentos sanos." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia al traumatólogo de hospital?", intro: "Una rotura exige atención inmediata traumatológica. Ve a una consulta de urgencias hospitalaria y NO CAMINES sobre ella si observas:", items: ["Durante la caída, golpe o el giro torcido, escuchaste, y además sentiste internamente un claro ruido de rotura, un estallido, un chasquido o un 'pop' o estruendo fuerte dentro de la propia articulación (señal clara e indiscutible de que el LCA o los cruzados han estallado o cedido por completo en dos)", "La rodilla o articulación se inflama, se enrojece e hincha de manera monstruosa, enorme o muy severa y dura en los primeros minutos e instantes a muy escasas horas posteriores inmediatas a sufrir tu caída y lesión deportiva fuerte", "Se percibe y experimenta en repetidas situaciones una espantosa y notoria sensación en la articulación de gran aflojamiento grave e 'inestabilidad', una percepción peligrosa de que la rodilla 'te cede', falla por debajo o está totalmente desconectada o suelta y se dobla de forma muy incorrecta por tu propio peso en tu intento al pisar el suelo y tratar de soportar tu peso del cuerpo al andar en movimiento", "Padeces o sufres un dolor local profundo muy fuerte, una intensidad dolorosísima agudizada persistente, y tienes la articulación general de tu rodilla totalmente inmovilizada que te hace absolutamente imposible e incapacitante no solo poder doblar ni un grado, ni extenderla recta ni moverla sino tampoco soportar o realizar ningún intento general de un paso normal o apoyo para mantener el más mínimo esfuerzo sin muletas"] } },
'Enfermedades terminales' : { intro: "Las enfermedades terminales son afecciones médicas avanzadas, progresivas e incurables en las cuales la esperanza de vida es limitada y el enfoque médico cambia de intentar curar a proveer confort.", whatIs: { title: "¿Qué es una Enfermedad Terminal?", text: "Es una condición de salud irreversible que no responde a los tratamientos curativos médicos y que conducirá a la muerte en un periodo de tiempo previsible. En esta etapa, el enfoque integral se desplaza hacia los cuidados paliativos y el manejo del sufrimiento." }, types: { title: "Condiciones Comunes Asociadas", intro: "Incluyen una variedad de patologías en sus estadios finales:", items: ["Cánceres metastásicos o resistentes a tratamiento", "Insuficiencia cardíaca congestiva terminal", "Enfermedad Pulmonar Obstructiva Crónica (EPOC) grave", "Enfermedades neurodegenerativas avanzadas (Alzheimer profundo, Esclerosis Lateral Amiotrófica)", "Insuficiencia renal o hepática en fase final sin opción a trasplante"], note: "El reconocimiento de la fase terminal permite a la familia tomar decisiones sobre los cuidados al final de la vida." }, diagnosis: { title: "Evaluación Médica de Pronóstico", intro: "El diagnóstico de terminalidad es un juicio clínico complejo basado en:", items: ["Evidencia de progresión rápida y objetiva de la enfermedad a pesar de los tratamientos óptimos", "Deterioro severo del estado físico (evaluado con escalas como Karnofsky o ECOG)", "Decisión conjunta entre el equipo médico, el paciente y la familia de suspender tratamientos agresivos inútiles"], note: "" }, treatment: { title: "Cuidados Paliativos y Hospicio", intro: "El tratamiento no busca curar, sino proporcionar la máxima calidad de vida posible:", subsections: [ { title: "Manejo Integral", items: ["Control agresivo y prioritario del dolor (mediante analgésicos opioides fuertes como la morfina)", "Alivio de síntomas asfixiantes o incómodos (manejo de la disnea, náuseas, agitación y delirium)", "Atención de hospicio o 'hospice' (asistencia médica en el hogar o centros especializados)", "Apoyo psicológico, espiritual y de duelo profundo para el paciente y todos sus familiares cercanos"] } ], note: "Los cuidados paliativos no aceleran ni retrasan la muerte, simplemente afirman la vida y reconocen la muerte como un proceso natural." }, whenToSeekHelp: { title: "¿Cuándo solicitar Cuidados Paliativos?", intro: "Es fundamental pedir ayuda al equipo de paliativos si el paciente:", items: ["Sufre dolores severos que no se logran controlar con la medicación normal", "Experimenta un sufrimiento respiratorio o ahogo persistente", "Requiere soporte emocional y psicológico intenso ante el miedo y la ansiedad del proceso final"] } },
'Enfermedad de von Willebrand' : { intro: "La enfermedad de von Willebrand es el trastorno hemorrágico hereditario más común en los seres humanos. Se caracteriza por un sangrado prolongado o excesivo debido a una anomalía en la coagulación de la sangre.", whatIs: { title: "¿Qué es la Enfermedad de von Willebrand?", text: "Para que la sangre forme coágulos y detenga un sangrado, necesita proteínas especiales. Las personas con esta enfermedad tienen niveles bajos, o una disfunción, del 'Factor de von Willebrand', una proteína clave que actúa como 'pegamento' para ayudar a las plaquetas a unirse y sellar los vasos sanguíneos rotos." }, types: { title: "Tipos de la Enfermedad", intro: "Se clasifica en tres tipos principales según su gravedad:", items: ["Tipo 1 (la más común y leve; hay un nivel bajo de factor de von Willebrand pero este funciona correctamente)", "Tipo 2 (el nivel es normal, pero la proteína tiene un defecto estructural y no funciona bien)", "Tipo 3 (muy rara y grave; hay una ausencia total del factor de von Willebrand y de factor VIII, causando hemorragias profundas)"], note: "Es una condición genética autosómica, lo que significa que afecta por igual a hombres y mujeres, aunque en las mujeres es más evidente por las menstruaciones." }, diagnosis: { title: "Diagnóstico Hematológico", intro: "Requiere pruebas de sangre especializadas:", items: ["Medición del antígeno del factor de von Willebrand (cantidad de proteína)", "Actividad del cofactor de ristocetina (para ver si la proteína funciona y pega las plaquetas)", "Nivel de Factor VIII de coagulación (que suele estar disminuido)", "Análisis del historial de sangrado familiar y personal"], note: "" }, treatment: { title: "Manejo y Prevención de Hemorragias", intro: "No tiene cura, pero se trata eficazmente para prevenir episodios graves:", subsections: [ { title: "Opciones de Tratamiento", items: ["Desmopresina (DDAVP) (una hormona sintética en spray nasal o inyectable que estimula al cuerpo a liberar más factor de von Willebrand de sus reservas)", "Terapias de reemplazo (infusiones intravenosas de factor de von Willebrand concentrado para los Tipos 2 y 3, o antes de cirugías mayores)", "Medicamentos antifibrinolíticos (como el ácido tranexámico para estabilizar el coágulo, muy útil en extracciones dentales)", "Anticonceptivos hormonales (píldoras o DIU para controlar la menstruación muy abundante en mujeres)"] } ], note: "Las personas con esta enfermedad deben evitar terminantemente la aspirina, el ibuprofeno y otros AINEs, ya que empeoran el sangrado." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico hematólogo?", intro: "Debes buscar evaluación si presentas:", items: ["Sangrados nasales repetitivos, abundantes, y que duran más de 10 minutos a pesar de hacer presión", "Menstruaciones extremadamente abundantes, prolongadas o que expulsan grandes coágulos (menorragia)", "Sangrado excesivo prolongado tras un corte menor, un procedimiento dental o una cirugía", "Aparición frecuente de grandes y abultados moretones (hematomas) sin un golpe que los justifique"] } },
'Malformación arteriovenosa cerebral' : { intro: "Una malformación arteriovenosa (MAV) cerebral es una maraña anormal de vasos sanguíneos en el cerebro que conecta las arterias directamente con las venas, saltándose la red de capilares protectores normales.", whatIs: { title: "¿Qué es una MAV Cerebral?", text: "Normalmente, las arterias llevan sangre a alta presión, la cual se frena al pasar por los diminutos capilares antes de llegar a las venas de baja presión. En una MAV, este salto directo hace que la sangre de altísima presión golpee las delgadas paredes venosas, estirándolas peligrosamente y creando un altísimo riesgo de rotura (derrame hemorrágico)." }, symptoms: { title: "Síntomas", intro: "Pueden no causar síntomas hasta que se rompen, pero a veces provocan:", groups: [ { name: "Signos Neurológicos", items: ["Convulsiones repentinas sin antecedentes previos", "Dolor de cabeza intenso y localizado en un área específica", "Debilidad muscular progresiva o entumecimiento en una parte del cuerpo", "Pérdida de visión o dificultades graves con el habla", "Un sonido de soplo o zumbido pulsátil en el cráneo que el paciente puede oír"] } ], warning: "La ruptura y sangrado de una MAV es una emergencia médica catastrófica que amenaza la vida en minutos." }, types: { title: "Características", intro: "Son defectos presentes al nacer (congénitos):", items: ["MAVs rotas (sintomáticas, causan hemorragia intracraneal y daño cerebral agudo)", "MAVs no rotas (a menudo descubiertas por accidente al hacer un escáner cerebral por otras razones, como un golpe)"], note: "Se cree que se forman durante el desarrollo fetal, pero rara vez son genéticamente hereditarias." }, diagnosis: { title: "Diagnóstico por Imagen Avanzada", intro: "Los neurólogos y neurocirujanos requieren mapear los vasos:", items: ["Tomografía Computarizada (TC) de cráneo (la primera prueba en urgencias para ver si hay sangrado activo)", "Resonancia Magnética (RM) del cerebro (para detallar la ubicación exacta y el tamaño del nido de vasos)", "Angiografía cerebral por cateterismo (el estándar de oro; se inyecta contraste a través de la ingle hasta el cerebro para ver los vasos sanguíneos detalladamente en rayos X)"], note: "" }, treatment: { title: "Intervenciones Neuroquirúrgicas", intro: "El tratamiento depende del riesgo de ruptura y la ubicación en el cerebro:", subsections: [ { title: "Opciones de Tratamiento", items: ["Vigilancia y manejo médico (para MAVs en zonas intocables del cerebro o sin síntomas, usando medicación para prevenir convulsiones y bajar la presión arterial)", "Resección quirúrgica (el neurocirujano abre el cráneo y extrae físicamente toda la MAV; si se retira completa, es curativa)", "Embolización endovascular (se inyecta un material o 'pegamento' médico a través de un catéter para bloquear las arterias de la MAV y cerrarla desde adentro)", "Radiocirugía estereotáctica (Gamma Knife, usa radiación altamente enfocada para destruir los vasos anormales de la MAV a lo largo de meses sin cirugía abierta)"] } ], note: "Las decisiones de tratamiento en MAVs no rotas son sumamente complejas debido a los riesgos quirúrgicos frente a los riesgos de un sangrado futuro." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA VITAL?", intro: "Llama al 911 de inmediato si experimentas:", items: ["El 'peor dolor de cabeza de tu vida', repentino y explosivo", "Cualquier convulsión de inicio reciente", "Debilidad, parálisis, adormecimiento en la cara o extremidades", "Confusión extrema, náuseas violentas o pérdida del conocimiento"] } },
'Hematoma subdural crónico' : { intro: "Un hematoma subdural crónico es una acumulación peligrosa de sangre vieja, descompuesta y fluidos en la superficie del cerebro, específicamente bajo su capa protectora externa (la duramadre). Es una patología intracraneal sumamente frecuente en personas mayores.", whatIs: { title: "¿Qué es un Hematoma Subdural Crónico?", text: "Al envejecer, el cerebro se encoge de forma natural, lo que tensa las pequeñas 'venas puente' que van del cerebro al cráneo. Un trauma en la cabeza mínimo o casi imperceptible puede desgarrar una de estas frágiles venas, provocando un sangrado muy lento (gota a gota) que tarda semanas o meses en formar una gran bolsa de sangre que termina aplastando el cerebro." }, symptoms: { title: "Síntomas de Compresión Lenta", intro: "Los síntomas aparecen semanas después del golpe, imitando otras enfermedades:", groups: [ { name: "Cambios Neurológicos Graduales", items: ["Dolor de cabeza sordo y persistente que empeora progresivamente", "Confusión, problemas de memoria repentinos o apatía (frecuentemente diagnosticado erróneamente como demencia rápida o Alzheimer)", "Debilidad en un lado del cuerpo, torpeza y caídas inexplicables", "Dificultad para hablar o caminar (arrastrar los pies)", "Letargo profundo, somnolencia extrema y, finalmente, estado de coma"] } ], warning: "Los pacientes y familias a menudo no recuerdan ningún golpe en la cabeza porque el trauma original fue muy leve (como golpearse con una puerta de armario)." }, types: { title: "Factores de Riesgo Clínicos", intro: "Ciertos factores predisponen fuertemente al paciente:", items: ["Edad avanzada (personas mayores de 60 años por atrofia cerebral)", "Uso crónico de medicamentos anticoagulantes o antiagregantes (Aspirina, Sintrom, Eliquis)", "Consumo crónico y severo de alcohol (que atrofia el cerebro y destruye factores de coagulación del hígado)", "Convulsiones frecuentes"], note: "" }, diagnosis: { title: "Escáneres Cerebrales y Confirmación", intro: "La imagenología revela instantáneamente la masa sobre el cerebro:", items: ["Tomografía Computarizada (TC) de cráneo sin contraste (es el examen más rápido y estándar; la sangre vieja del hematoma crónico se ve de color oscuro o grisáceo, distinta a la sangre fresca y blanca del agudo, y muestra cómo el cerebro está siendo empujado y desviado)", "Resonancia Magnética (RM) (puede mostrar detalles más precisos de colecciones pequeñas o múltiples)"], note: "" }, treatment: { title: "Evacuación Quirúrgica Mínima", intro: "El objetivo es aliviar mecánicamente la presión sobre el cerebro asfixiado:", subsections: [ { title: "Procedimientos", items: ["Cirugía de agujero de trépano (el tratamiento más frecuente: el neurocirujano perfora uno o dos pequeños agujeros en el cráneo, abre la duramadre, drena y lava la sangre oscura licuada y deja un tubo de drenaje temporal)", "Craneotomía (una cirugía mayor abriendo un área más grande de cráneo si la sangre es muy sólida y gruesa)", "Embolización de la arteria meníngea media (un procedimiento menos invasivo para bloquear los vasos que alimentan la membrana del hematoma)", "Manejo médico y esteroides (para hematomas pequeñísimos sin síntomas graves, observándolos con TC repetidas)"] } ], note: "La mejora neurológica tras el drenaje suele ser asombrosamente rápida en cuestión de horas o días." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias neurológicas?", intro: "Es fundamental buscar revisión médica urgente para un adulto mayor si:", items: ["Ha sufrido una caída menor o golpe en la cabeza en las últimas semanas y ahora comienza a mostrar cambios notables en su comportamiento o estado mental", "Presenta una somnolencia profunda inusual y es difícil mantenerlo despierto", "Experimenta nueva debilidad en las piernas, pierde el equilibrio al caminar o siente entumecimiento en un lado del cuerpo"] } },
'Absceso de las amígdalas' : { intro: "Un absceso de las amígdalas, o absceso periamigdalino, es una infección bacteriana aguda y dolorosa en la que se acumula una gran bolsa de pus en los tejidos ubicados alrededor o detrás de una de las amígdalas en el fondo de la garganta.", whatIs: { title: "¿Qué es un Absceso Periamigdalino?", text: "Es una complicación severa de una amigdalitis no tratada (infección de garganta). Las bacterias, a menudo del tipo Estreptococo, rompen los límites de la amígdala e invaden los espacios profundos del cuello. La inflamación y el saco de pus resultante crecen tanto que pueden empujar la campanilla hacia un lado y amenazar con bloquear las vías respiratorias." }, symptoms: { title: "Síntomas Clásicos", intro: "Los signos son agudos, en un solo lado y muy dolorosos:", groups: [ { name: "Signos Locales", items: ["Dolor de garganta extremadamente severo, mucho peor en un lado", "Incapacidad o dolor espantoso al intentar tragar incluso la propia saliva, lo que provoca babeo constante", "Voz apagada, gruesa y gangosa, conocida médicamente como 'voz de patata caliente'", "Dificultad o imposibilidad física para abrir la boca por completo (trismo debido al espasmo muscular por el pus)", "Fiebre alta, escalofríos y mal aliento fétido", "Hinchazón enorme visible en el fondo del paladar y ganglios del cuello inflamados"] } ], warning: "Si el absceso se rompe en la garganta y el pus baja a los pulmones, puede causar una neumonía fatal." }, types: { title: "Factores Relacionados", intro: "Suele surgir de amigdalitis repetitivas:", items: ["Más común en adolescentes y adultos jóvenes", "Asociado a amigdalitis estreptocócica no curada o a mala salud dental (infecciones en las encías)", "Es casi siempre unilateral (ocurre solo en un lado de la garganta a la vez)"], note: "" }, diagnosis: { title: "Evaluación Otorrinolaringológica", intro: "Se diagnostica mayormente por la apariencia visual característica:", items: ["Examen físico directo (el médico iluminará la garganta y verá la enorme hinchazón del paladar blando empujando la úvula -campanilla- lejos del absceso)", "Aspiración con aguja (si se extrae pus de la hinchazón, se confirma el absceso)", "Tomografía Computarizada (TC) de cuello con contraste (solo si el médico sospecha que la infección se ha extendido peligrosamente hacia el pecho o las venas yugulares)"], note: "" }, treatment: { title: "Drenaje del Pus y Antibióticos Urgentes", intro: "Las pastillas de antibióticos por sí solas no penetran la bolsa de pus; es obligatoria la intervención física:", subsections: [ { title: "Procedimientos de Urgencia", items: ["Incisión y drenaje (el tratamiento principal: se aplica anestesia local y el otorrinolaringólogo hace un pequeño corte en el paladar con un bisturí para exprimir y vaciar todo el pus)", "Aspiración con aguja (usar una jeringa grande para sacar el pus)", "Antibióticos intravenosos (IV) de alta dosis o penicilina oral fuerte inmediatamente después del drenaje", "Corticosteroides (esteroides para reducir rápidamente la inflamación aguda de la vía aérea y permitir al paciente comer)", "Amigdalectomía de emergencia (extirpar las amígdalas en el momento si el absceso es recurrente o inmanejable)"] } ], note: "El alivio del dolor tras la salida de la presión del pus es casi instantáneo." }, whenToSeekHelp: { title: "¿Cuándo correr a urgencias médicas?", intro: "Un absceso periamigdalino es una urgencia de las vías aéreas. Ve al hospital de inmediato si:", items: ["Tu dolor de garganta es tan intenso que no puedes pasar tu propia saliva y babeas", "Sientes que te asfixias, te ahogas o tienes un sonido ronco agudo al intentar respirar", "Eres incapaz de abrir bien la mandíbula o hablar con claridad (trismo)"] } },
'Trastorno de la personalidad esquizoide' : { intro: "El trastorno de la personalidad esquizoide es una afección mental poco común y de por vida en la que una persona tiene un patrón consistente de desapego extremo, indiferencia hacia las relaciones sociales y una gama muy limitada de expresión emocional.", whatIs: { title: "¿Qué es el Trastorno de Personalidad Esquizoide?", text: "Es un modo crónico de ser. Las personas con este trastorno suelen ser vistas como 'solitarias' crónicas. A diferencia de las personas con fobia social que desean tener amigos pero sienten miedo, las personas esquizoides genuinamente no tienen ningún deseo ni necesidad de intimidad, relaciones o contacto humano cercano, eligiendo siempre estar solas." }, symptoms: { title: "Comportamientos y Emociones", intro: "Se caracteriza por un aislamiento emocional profundo y voluntario:", groups: [ { name: "Rasgos Clave (Criterios DSM)", items: ["Falta de deseo o disfrute de las relaciones interpersonales cercanas, incluyendo ser parte de una familia", "Preferencia casi exclusiva por actividades, trabajos o hobbies completamente solitarios", "Poco o nulo interés en tener experiencias o relaciones sexuales con otra persona", "Indiferencia total ante los elogios o las críticas duras de los demás", "Frialdad emocional constante, desapego o un afecto visiblemente 'aplanado' (no muestran alegría, ira ni tristeza)"] } ], warning: "Aunque el nombre suena similar, la personalidad esquizoide NO es esquizofrenia; el paciente está conectado a la realidad, no tiene alucinaciones ni delirios psicóticos." }, types: { title: "Factores de Riesgo y Origen", intro: "Sus causas no están claras, pero incluyen:", items: ["Fuertes componentes genéticos (antecedentes familiares de trastornos del espectro de la esquizofrenia o trastorno esquizotípico)", "Desarrollo temprano (niños que sufrieron negligencia emocional extrema o falta de apego por parte de los padres en la primera infancia)", "Temperamento natural desde la infancia de evitación de estímulos"], note: "Suele hacerse evidente en la adolescencia tardía o en los primeros años de la edad adulta." }, diagnosis: { title: "Evaluación Psicológica", intro: "El diagnóstico lo realiza un psiquiatra o psicólogo clínico:", items: ["Entrevista clínica profunda evaluando la historia de vida, relaciones y funcionamiento laboral", "Aplicación de los criterios diagnósticos del DSM-5", "Diferenciación crucial con el espectro del autismo (TEA), el trastorno de personalidad por evitación o episodios de depresión profunda severa"], note: "Es muy raro que las personas con este trastorno busquen atención médica por voluntad propia, ya que su aislamiento no les causa angustia." }, treatment: { title: "Desafíos de la Terapia a Largo Plazo", intro: "El tratamiento es difícil, ya que el paciente no suele percibir un problema y rechaza el entorno terapéutico:", subsections: [ { title: "Opciones Psicológicas", items: ["Psicoterapia individual (enfocada en mejorar gradualmente la capacidad de la persona para comunicarse, leer señales sociales y tolerar interacciones en entornos laborales)", "Terapia Cognitivo-Conductual (para modificar expectativas sobre las relaciones y el aislamiento)", "Terapia de grupo (puede ayudarles a practicar interacciones sociales básicas en un entorno altamente seguro y no amenazante)", "Medicamentos (solo se prescriben si la persona desarrolla una depresión secundaria grave o una ansiedad paralizante severa, no para curar el trastorno de personalidad)"] } ], note: "El objetivo realista no es convertir al paciente en alguien extrovertido, sino en ayudarlo a funcionar mejor en la sociedad, el trabajo y en un mínimo contacto social necesario." }, whenToSeekHelp: { title: "¿Cuándo sugerir atención profesional?", intro: "Dado el aislamiento, un familiar o el propio paciente podría buscar ayuda si:", items: ["El profundo aislamiento comienza a causar un nivel crítico de disfunción que hace imposible mantener un trabajo o medios de supervivencia", "Aparecen síntomas superpuestos de depresión clínica intensa y desesperanza paralizante"] } },
'Relaciones insanas' : { intro: "Las relaciones insanas, a menudo referidas coloquialmente como 'tóxicas' o abusivas, son dinámicas interpersonales disfuncionales en las que el comportamiento de una o ambas partes es dañino, manipulador, agotador o directamente destructivo para el bienestar emocional, mental o físico de la persona.", whatIs: { title: "¿Qué caracteriza a una Relación Insana?", text: "Son relaciones (de pareja, amistades, laborales o familiares) donde no existe el respeto mutuo, la comunicación abierta ni la confianza. Predomina un patrón de control extremo, desequilibrio de poder, falta de empatía, y donde el conflicto constante y el sufrimiento eclipsan cualquier aspecto positivo, dañando profundamente la autoestima de la persona." }, symptoms: { title: "Señales de Alerta (Red Flags)", intro: "El abuso puede ser sutil o abierto, y abarca comportamientos como:", groups: [ { name: "Indicadores de Abuso y Control", items: ["Aislamiento forzado (tu pareja intenta alejarte de tu familia, amigos o actividades independientes)", "Comportamiento posesivo y celos enfermizos disfrazados de 'amor' o 'cuidado'", "Gaslighting (manipulación psicológica severa donde te hacen dudar de tu propia memoria, cordura o percepción de la realidad)", "Violencia verbal y emocional constante (insultos, menosprecio, críticas destructivas o humillaciones públicas y privadas)", "Explosiones de ira impredecibles o tener que caminar 'sobre cáscaras de huevo' para evitar sus enfados", "Falta total de responsabilidad o disculpas verdaderas (siempre tú tienes la culpa de todo)"] } ], warning: "Cualquier forma de violencia física o coerción sexual cruzada el límite a una relación abiertamente abusiva e ilegal." }, types: { title: "Formas de Daño y Ciclos", intro: "Estas relaciones suelen perpetuarse en ciclos dolorosos:", items: ["El ciclo de abuso (Fase de tensión creciente, Fase del incidente de agresión/estallido, y Fase de 'Luna de Miel' o reconciliación con falsas promesas de cambio)", "Dependencia emocional y apego ansioso", "Codependencia severa o habilitación de comportamientos adictivos"], note: "El abuso emocional a largo plazo causa cambios neurológicos literales similares al trauma severo (TEPT complejo)." }, diagnosis: { title: "Evaluación del Daño Psicológico", intro: "No es una enfermedad médica por sí misma, pero un terapeuta evaluará los daños colaterales:", items: ["Detección de síntomas de Depresión clínica profunda y pérdida de la identidad", "Evaluación de Trastornos de Ansiedad, ataques de pánico o Trastorno de Estrés Postraumático (TEPT)", "Análisis de la dinámica de la relación y de la seguridad física de la persona afectada"], note: "" }, treatment: { title: "Restablecimiento de Límites y Sanación", intro: "El tratamiento se centra enteramente en la persona que sufre, para recuperar su autonomía:", subsections: [ { title: "Pasos de Recuperación Psicológica", items: ["Psicoterapia individual profunda (para reconstruir la autoestima destruida, reconocer patrones de abuso, y romper las cadenas de la dependencia traumática y emocional)", "Establecimiento de límites inquebrantables y rígidos frente al agresor", "Terapia de desvinculación (preparación y estrategias seguras para abandonar permanentemente la relación si hay peligro de agresiones)", "La Terapia de Pareja está firmemente contraindicada y es muy peligrosa si existe un historial continuo de abuso emocional, control coercitivo o violencia física"] } ], note: "Romper el ciclo requiere apoyo masivo de familiares y grupos de ayuda." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda de emergencia o profesional?", intro: "No esperes a que cambien o empeoren las cosas. Busca apoyo inmediato de terapeutas o líneas de ayuda si:", items: ["Te sientes físicamente amenazado, sientes miedo o sufres agresiones físicas", "Tus amistades y familiares te han advertido reiteradamente que la relación te está destruyendo y estás totalmente aislado", "Sientes una ansiedad incontrolable, depresión, o tienes pensamientos de suicidio como vía de escape de la relación"] } },
'Trastornos de la marcha' : { intro: "Los trastornos de la marcha son anomalías, alteraciones y desviaciones significativas en la manera o el patrón de caminar (marcha) de una persona. Pueden resultar en pérdida del equilibrio, tropezones incesantes, debilidad o una alta propensión a sufrir caídas peligrosas.", whatIs: { title: "¿Qué es un Trastorno de la Marcha?", text: "La capacidad de caminar de forma coordinada requiere un complejo y perfecto engranaje entre el cerebro, los nervios, la médula espinal, el oído interno (equilibrio), los músculos y las articulaciones óseas. Cuando una lesión, enfermedad o el envejecimiento daña cualquiera de estas partes, el patrón natural de caminar se arruina y se vuelve patológico." }, types: { title: "Patrones Clásicos Patológicos", intro: "La forma visual de caminar indica dónde está el daño neurológico u óseo:", items: ["Marcha Parkinsoniana (pasos muy cortos y rápidos, arrastrando los pies, postura rígida encorvada hacia adelante, dificultad para arrancar y sin balanceo de brazos)", "Marcha Hemiparética o de segador (una pierna rígida que se arrastra trazando un semicírculo en el suelo; secuela clásica después de sufrir un Derrame Cerebral)", "Marcha Atáxica (caminar con las piernas muy separadas, tambaleante y desequilibrado como si la persona estuviera ebria; indica daño en el cerebelo o nervios profundos)", "Marcha de Pato o miopática (balanceo exagerado de las caderas al caminar, característico de distrofias musculares severas o caderas dislocadas)", "Pie caído o marcha en estepaje (el paciente debe levantar exageradamente la rodilla para evitar que la punta del pie dormido o paralizado roce el suelo al dar el paso, por nervio dañado)"], note: "" }, diagnosis: { title: "Evaluación Neurológica y Ortopédica Exhaustiva", intro: "El especialista requiere observar al paciente y realizar escáneres:", items: ["Evaluación clínica observacional estricta (el médico pide al paciente caminar en línea recta, caminar sobre sus talones y de puntillas para ver la mecánica del fallo)", "Examen neurológico (medición profunda de reflejos espinales, tono muscular, fuerza motora y sensibilidad)", "Resonancia Magnética (RM) del cerebro o la médula espinal (para detectar esclerosis múltiple, tumores, hernias discales o secuelas de ACV ocultas)", "Electromiografía (EMG) (para medir si los impulsos eléctricos de los nervios a los músculos están cortados)"], note: "" }, treatment: { title: "Rehabilitación y Tratamiento Causal", intro: "El tratamiento no es único, depende estrictamente de la enfermedad base que lo causa:", subsections: [ { title: "Terapias Intervencionistas y Físicas", items: ["Fisioterapia exhaustiva y reentrenamiento de la marcha (el pilar fundamental para recuperar el equilibrio y fortalecer los músculos compensatorios)", "Dispositivos ortopédicos de asistencia médica (férulas AFO rígidas para mantener el pie caído levantado, bastones, o andadores para evitar fracturas por caídas)", "Tratamiento de las enfermedades primarias subyacentes (medicación de Levodopa para corregir los pasos de Parkinson, o cirugía lumbar urgente si una hernia asfixia el nervio ciático de la pierna)", "Inyecciones de Toxina Botulínica (Bótox) en músculos específicos para relajar músculos demasiado rígidos (espasticidad)"] } ], note: "Las caídas por trastornos de la marcha son la principal causa de fracturas de cadera y muerte secundaria en personas de la tercera edad." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia a un neurólogo?", intro: "Debes buscar evaluación médica prioritaria si presentas:", items: ["Un cambio brusco y repentino en tu forma de caminar (esto es un signo cardinal de un derrame cerebral o compresión medular aguda)", "Has comenzado a tropezar constantemente sin razón o sufres caídas frecuentes en las últimas semanas", "Sientes un entumecimiento fuerte y debilidad (pérdida de fuerza) en una o ambas piernas y te es difícil levantarte de la silla", "Comienzas a arrastrar los pies notablemente o notas temblores o rigidez muscular severa incontrolable"] } },
'Nevos' : { intro: "Los nevos melanocíticos, conocidos popularmente en todo el mundo simplemente como 'lunares', son crecimientos de la piel muy comunes y generalmente benignos (inofensivos) compuestos de células que producen el pigmento de color (los melanocitos).", whatIs: { title: "¿Qué son los Nevos (Lunares)?", text: "Son agrupaciones concentradas de las células que dan color a nuestra piel. Aparecen habitualmente durante la infancia, la niñez y hasta la adolescencia temprana como pequeñas manchas o bultos de color marrón, negro o del tono de la piel. Un adulto promedio y saludable tiene entre 10 y 40 lunares inofensivos." }, types: { title: "Tipos de Lunares", intro: "Los dermatólogos los clasifican según cuándo aparecieron y cómo se ven:", items: ["Nevo adquirido común (los lunares ordinarios redondos, simétricos y de un solo color que aparecen después de nacer, el riesgo de cáncer en ellos es muy bajo)", "Nevo congénito (un lunar grande con el que la persona nace directamente; los de tamaño gigante tienen mayor riesgo de transformarse en cáncer en el futuro)", "Nevo displásico o atípico (lunares grandes, de forma extraña e irregular, o con múltiples colores y bordes borrosos; parecen melanoma, pero son benignos, aunque quien tiene muchos de estos posee un riesgo heredado muy alto de desarrollar cáncer de piel)"], note: "Es normal que los lunares cambien muy lentamente durante el crecimiento, se oscurezcan en el embarazo o se abulten y palidezcan en la vejez." }, diagnosis: { title: "La Regla ABCDE y Dermatoscopia", intro: "La tarea clínica principal es diferenciar un lunar sano del mortal melanoma:", items: ["Examen visual rutinario de la piel por un dermatólogo", "Dermatoscopia (el uso de una herramienta clínica de aumento profundo iluminada para ver el patrón del pigmento por debajo de la superficie de la piel y descartar malignidad)", "Examen personal y de advertencia por la Regla ABCDE de los lunares: Asimetría, Bordes (irregulares), Color (varios en uno), Diámetro (más grande que una goma de borrar) y Evolución (que cambie, crezca, pique o sangre)", "Biopsia de piel por escisión total (si el médico sospecha la más mínima alteración maligna celular, cortará todo el lunar con un margen de seguridad para enviarlo a patología microscópica)"], note: "" }, treatment: { title: "Observación o Extirpación Quirúrgica", intro: "La gran mayoría de los lunares no deben tocarse ni medicarse, solo observarse:", subsections: [ { title: "Manejo y Opciones", items: ["Vigilancia médica periódica o mapeo corporal (revisión de la piel una vez al año obligatoria en personas con decenas de lunares atípicos o piel muy blanca)", "Extirpación quirúrgica menor de afeitado (shave) u escisión (para eliminar un lunar por completo, ya sea porque duele al roce con la ropa, o porque el médico sospecha que sus células son o se volverán precancerosas)", "Uso obsesivo y estricto del protector solar (la herramienta preventiva primordial número uno para evitar que la radiación UV del sol haga mutar los lunares estables hacia tumores mortales)"] } ], note: "NUNCA debes intentar eliminar, raspar, quemar o cortar un lunar en casa con remedios caseros, ya que puedes ocultar el cáncer y promover infecciones graves y cicatrices." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE la revisión por el dermatólogo?", intro: "Cualquier cambio notorio o rápido en un lunar indica un peligro extremo de cáncer. Acude de inmediato si un lunar:", items: ["Empieza repentinamente a picar, a dar dolor, a formar costras oscuras o si sangra espontáneamente sin haberlo golpeado", "Tiene un tamaño muy asimétrico (una mitad no es igual a la otra) o presenta bordes extraños, irregulares y borrosos", "Combina varios colores extraños (zonas azules, rojas, blancas y negras muy oscuras a la vez)", "El lunar o mancha es el llamado 'Patito Feo' (luce y resalta de manera completamente diferente al resto de lunares en tu cuerpo)", "Eres un adulto y aparece una mancha negra o lunar totalmente nuevo y de crecimiento súper rápido (la mayoría de lunares nuevos pasados los 30 años son muy sospechosos)"] } },
'Enfermedad de Legg-Calve-Perthes' : { intro: "La enfermedad de Legg-Calvé-Perthes es un trastorno ortopédico infantil poco frecuente y muy grave que ocurre en la articulación de la cadera, caracterizado por una interrupción perjudicial y temporal del flujo sanguíneo a la cabeza del hueso del fémur.", whatIs: { title: "¿Qué es Legg-Calvé-Perthes?", text: "Es una condición infantil de necrosis avascular (muerte de tejido óseo por falta de riego). Cuando la cabeza redondeada (la 'bola') del fémur se queda sin sangre, las células óseas mueren, haciendo que el hueso blando se aplane y se rompa fácilmente bajo el peso del niño. Con el tiempo, el cuerpo restaura el flujo y el hueso se remodela, pero si sana de forma aplanada o deforme, provocará cojera y artritis dolorosísima y temprana." }, types: { title: "Perfil y Etapas", intro: "Es un proceso que dura varios años y evoluciona en fases destructivas y curativas:", items: ["Fase de Necrosis inicial (muerte celular, el dolor comienza y el hueso pierde densidad)", "Fase de Fragmentación (el cuerpo limpia el hueso muerto; es la fase más peligrosa donde el hueso puede aplanarse y colapsar al caminar)", "Fase de Reosificación (crece nuevo hueso para reemplazar la 'bola')", "Fase de Curación y Remodelación residual (el hueso toma su forma final; si no es completamente redonda y lisa, causará problemas mecánicos de por vida)", "Es cinco veces más común en niños (varones) que en niñas, y suele atacar entre las edades de 4 y 10 años, generalmente a una sola cadera"], note: "El origen y la causa exacta de la repentina falta de riego de sangre siguen siendo totalmente desconocidos en la medicina." }, diagnosis: { title: "Exámenes Radiológicos Ortopédicos", intro: "El especialista en ortopedia pediátrica determinará el alcance del daño óseo mediante:", items: ["Examen físico del rango de la pierna (evaluando la profunda falta de movilidad, rigidez severa en rotación y la atrofia notable del músculo del muslo por no usar la pierna dolorida)", "Radiografías de la cadera (esenciales y continuas a lo largo de los años para ver las etapas; mostrarán directamente la cabeza femoral blanca aplanada o rota en pedazos)", "Resonancia Magnética (RM) (la prueba vital para la detección temprana profunda de la zona, ya que puede revelar claramente que el riego sanguíneo ha cesado mucho antes de que el daño estructural aparezca en los rayos X)"], note: "" }, treatment: { title: "Reposo Estricto y Preservación Quirúrgica", intro: "El objetivo urgente es obligar y mantener a la cabeza femoral ablandada dentro de la protección de su cavidad (acetábulo) para que sane de forma perfectamente redonda:", subsections: [ { title: "Intervenciones Prolongadas", items: ["Descanso total de la carga (restricción completa y prohibición de realizar actividades de alto impacto, saltos o correr, e inmovilización de meses usando muletas o silla de ruedas)", "Fisioterapia y estiramientos continuos rigurosos para no perder el movimiento articular de la ingle", "Uso de yesos tipo 'Espica' de Petrie o aparatos ortopédicos de separación de piernas de abducción (para forzar a la cabeza del fémur a sanar confinada y moldeada dentro del molde pélvico)", "Cirugías ortopédicas de reorientación (osteotomía) (cortar y reubicar quirúrgicamente los huesos y rotarlos para mantenerlos fuertemente encajados si el niño es mayor de 8 años o el caso es avanzado y muy grave)"] } ], note: "Los niños que contraen la enfermedad siendo muy pequeños (menores de 6 años) tienen mucho mejor pronóstico de curación redonda perfecta porque tienen muchos más años de crecimiento natural por delante." }, whenToSeekHelp: { title: "¿Cuándo debes llevar al niño al doctor de urgencia?", intro: "Pide cita rápidamente si tu hijo o niño de primaria presenta de manera persistente:", items: ["Una cojera visible al caminar, trotar o correr que no se va después de un par de días", "Se queja de un dolor sordo, rígido o constantes molestias agudas en el área de la ingle, la propia cadera, o referido en todo el muslo y la rodilla", "El dolor y los síntomas empeoran dramáticamente al final del día escolar o tras actividad física intensa, y mejoran significativamente al estar acostados descansando", "Notas un acortamiento visual de una de sus piernas o rigidez que le impide abrir la ingle como una rana"] } },
'Visión baja' : { intro: "La visión baja, o baja visión, es un estado de pérdida visual severa e irreversible que no se puede corregir adecuadamente con gafas graduadas regulares, uso de lentes de contacto, medicamentos o intervenciones quirúrgicas. Hace que realizar tareas cotidianas vitales sea un desafío monumental.", whatIs: { title: "¿Qué es la Baja Visión?", text: "Es una discapacidad visual crónica significativa, pero no llega a ser una ceguera total (es decir, la persona aún conserva un resto visual o percepción de luz y formas). El deterioro puede ser central (pérdida de la visión en el centro por una mancha oscura persistente) o periférico (pérdida de la visión lateral y de los bordes, como la 'visión de túnel')." }, types: { title: "Enfermedades Oculares Causantes", intro: "Las patologías subyacentes que producen esta destrucción visual crónica son:", items: ["Degeneración Macular Relacionada con la Edad (DMAE) (causa principal; destruye lentamente la aguda y enfocada visión central para leer o ver caras)", "Glaucoma avanzado destructivo (el asesino silencioso; alta presión que mata el nervio óptico, borrando permanentemente todo el campo visual lateral periférico)", "Retinopatía Diabética Severa (el azúcar en la sangre causa sangrado masivo y cicatrices irreparables ciegas en la retina profunda)", "Cataratas graves y no operables en algunos ancianos", "Retinosis Pigmentaria (una rara enfermedad genética que causa ceguera nocturna total progresiva y visión en túnel estricta)"], note: "Aunque su aparición es más probable en ancianos o personas con diabetes, las lesiones traumáticas severas del ojo pueden provocarla a cualquier edad." }, diagnosis: { title: "Evaluación Especializada en Visión", intro: "Un examen tradicional de gafas no es suficiente; el oftalmólogo experto en baja visión requerirá:", items: ["Evaluación exhaustiva de la Agudeza Visual remanente (usando tablas optométricas y cartas de lectura especiales diseñadas para vista muy pobre y evaluar contrastes)", "Examen completo del Fondo de Ojo con dilatación de pupilas severa y uso de la lámpara de hendidura", "Pruebas estrictas de perimetría o campo visual (para mapear qué partes exactas y ciegas de la visión central o lateral periférica de la persona han sido destruidas)"], note: "" }, treatment: { title: "Rehabilitación Visual y Herramientas Ópticas", intro: "Puesto que el daño celular del ojo es permanente e incurable, el tratamiento consiste en rehabilitar a la persona para potenciar al máximo el resto de la visión útil que aún le quede:", subsections: [ { title: "Ayudas Ópticas, Adaptación y Tecnología", items: ["Uso clínico de ayudas ópticas potentes y de receta específica (lupas de alta potencia iluminadas con luz médica, gafas microscópicas complejas o minitelescopios adheridos a los anteojos para ver de lejos)", "Sistemas de televisión y circuito cerrado (CCTV) de magnificación gigante (cámaras que proyectan el texto enorme de libros en una pantalla grande, permitiendo la lectura)", "Modificaciones agresivas del entorno de vida (añadir luces focalizadas ultra potentes, usar alto contraste en el hogar como platos blancos en manteles negros, y uso de grandes etiquetas o pintura táctil)", "Rehabilitación ocupacional profunda (aprender técnicas y a usar bastones para navegar las calles con seguridad, y utilización de programas lectores de texto de computadora con gran síntesis de voz inteligente para celulares)"] } ], note: "El profundo y severo impacto psicológico y depresivo por la devastadora pérdida de la visión y de la autonomía exige frecuentemente apoyo de terapeutas psiquiátricos." }, whenToSeekHelp: { title: "¿Cuándo pedir una consulta oftalmológica seria?", intro: "Es indispensable acudir a la evaluación y ayuda clínica si, a pesar de llevar tus gafas bien graduadas puestas, tú o tu familiar mayor experimentan o empiezan a padecer:", items: ["Una grave y notable dificultad u oscurecimiento constante para leer libros, el periódico, revisar facturas, coser, cocinar los alimentos o reconocer los rasgos finos del rostro de tus seres queridos", "Toda la luz parece siempre insuficiente para ver y te parece todo oscuro, o al contrario, un resplandor leve y reflejo te ciegan dolorosa y totalmente", "Tropiezas bruscamente de manera repetitiva o te chocas en seco con puertas, sillas o muebles por no percatarte de que existen o no verlos de reojo", "Tienes una persistente y oscura mancha negra grisácea permanente y borrosa estancada y fija en el centro exacto de tu línea de visión frontal visual"] } },
'Cáncer del hígado' : { intro: "El cáncer de hígado es un tipo de cáncer que comienza en las células hepáticas. El tipo más común es el carcinoma hepatocelular, que suele desarrollarse en personas con enfermedades hepáticas crónicas.", whatIs: { title: "¿Qué es el Cáncer del Hígado?", text: "Es el crecimiento descontrolado de células anormales en el hígado. A menudo, es secundario a una cirrosis previa o a una infección crónica por los virus de la hepatitis B o C, lo que deteriora la función de este órgano vital." }, types: { title: "Tipos Principales", intro: "Se clasifica según el tipo de célula donde se origina:", items: ["Carcinoma hepatocelular (el más común, comienza en los hepatocitos)", "Colangiocarcinoma (cáncer de las vías biliares dentro del hígado)", "Hepatoblastoma (un tipo raro que afecta a niños pequeños)"], note: "Los tumores que se diseminan al hígado desde otros órganos (metástasis) no se consideran cáncer de hígado primario." }, diagnosis: { title: "Evaluación Diagnóstica", intro: "El médico utilizará varias pruebas para confirmar la presencia del tumor:", items: ["Análisis de sangre (para medir la función hepática y el marcador tumoral alfafetoproteína o AFP)", "Pruebas de imagen (Ecografía, Tomografía Computarizada o Resonancia Magnética del abdomen)", "Biopsia hepática (extracción de tejido, aunque a veces se evita si las imágenes son concluyentes para no propagar el cáncer)"], note: "" }, treatment: { title: "Tratamiento Oncológico", intro: "Depende de la etapa del cáncer y de la salud general del hígado:", subsections: [ { title: "Opciones Quirúrgicas y Médicas", items: ["Cirugía para extirpar el tumor (resección hepática)", "Trasplante de hígado (reemplazar el hígado enfermo por uno sano)", "Terapias localizadas (ablación por radiofrecuencia o crioablación para destruir el tumor)", "Terapias dirigidas, inmunoterapia o quimioterapia para casos avanzados"] } ], note: "La prevención mediante la vacuna contra la hepatitis B y el control del consumo de alcohol es fundamental." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Acude a un especialista si presentas de forma persistente:", items: ["Pérdida de peso involuntaria y pérdida de apetito severa", "Dolor en la parte superior derecha del abdomen o dolor en el hombro derecho", "Coloración amarillenta de la piel y los ojos (ictericia)", "Hinchazón o acumulación de líquido en el abdomen (ascitis)"] } },
'Hipospadias' : { intro: "El hipospadias es una anomalía congénita en los niños en la cual la abertura de la uretra (el conducto que transporta la orina y el semen) no se encuentra en la punta del pene.", whatIs: { title: "¿Qué es el Hipospadias?", text: "Es un defecto de nacimiento del tracto reproductor masculino. En lugar de abrirse en el extremo del glande, la uretra se abre en algún punto a lo largo de la parte inferior del pene o, en casos graves, en el escroto o perineo." }, types: { title: "Niveles de Gravedad", intro: "Se clasifica según la ubicación de la abertura:", items: ["Anterior o distal (cerca de la punta del pene, es la forma más leve y común)", "Medio (en el cuerpo o tallo del pene)", "Posterior o proximal (cerca de la base del pene o en el escroto, siendo la forma más severa)"], note: "Suele acompañarse de un prepucio incompleto (forma de capucha) y una curvatura del pene hacia abajo (encordamiento)." }, diagnosis: { title: "Diagnóstico", intro: "Es un diagnóstico visual al nacer:", items: ["Examen físico del recién nacido en la sala de partos o durante los primeros chequeos pediátricos", "En casos graves, pruebas genéticas o de imagen para descartar otros trastornos del desarrollo sexual"], note: "Los niños con hipospadias no deben ser circuncidados al nacer, ya que el tejido del prepucio puede necesitarse para la cirugía reconstructiva." }, treatment: { title: "Cirugía Reconstructiva", intro: "El tratamiento es quirúrgico para restaurar la función y la apariencia:", subsections: [ { title: "Procedimiento", items: ["Cirugía correctiva (generalmente realizada entre los 6 y 18 meses de edad)", "Reparación de la abertura de la uretra para llevarla a la punta del pene", "Enderezamiento del pene si existe curvatura (cordé)", "Reconstrucción del prepucio o circuncisión utilizando el tejido sobrante"] } ], note: "La cirugía suele tener un alto porcentaje de éxito, permitiendo una micción y función sexual normal en la edad adulta." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra urológico?", intro: "Es necesario buscar evaluación si notas en tu bebé:", items: ["La abertura de la uretra no está en la punta del pene", "El chorro de orina sale rociado o en una dirección anormal", "El pene tiene una curvatura evidente hacia abajo, especialmente durante una erección"] } },
'Síndrome de distrofia simpática refleja' : { intro: "El síndrome de distrofia simpática refleja (DSR), actualmente clasificado como Síndrome de Dolor Regional Complejo (SDRC) tipo I, es una afección de dolor crónico que suele afectar a un brazo o una pierna después de una lesión o trauma.", whatIs: { title: "¿Qué es el Síndrome de Distrofia Simpática Refleja?", text: "Es una disfunción del sistema nervioso central o periférico que reacciona de forma exagerada a un daño tisular. El cerebro sigue enviando señales de dolor intenso y continuo mucho tiempo después de que la lesión original (como una fractura o esguince) haya sanado." }, types: { title: "Tipos de SDRC", intro: "Existen dos tipos principales con síntomas similares:", items: ["Tipo I (Distrofia simpática refleja): Ocurre después de una enfermedad o lesión que no dañó directamente un nervio en la extremidad afectada.", "Tipo II (Causalgia): Ocurre después de una lesión nerviosa clara y confirmada."], note: "El dolor es desproporcionado en relación con la gravedad de la lesión inicial." }, diagnosis: { title: "Evaluación Clínica", intro: "No existe una sola prueba definitiva, el diagnóstico se basa en:", items: ["Historia clínica y examen físico minucioso (buscando cambios en la piel, hinchazón y alteraciones de temperatura en la extremidad)", "Gammagrafía ósea (puede mostrar cambios en el flujo sanguíneo o el metabolismo del hueso)", "Resonancia Magnética (RM) (para descartar problemas tisulares o articulares)", "Pruebas de sudoración y temperatura simétrica"], note: "" }, treatment: { title: "Manejo del Dolor y Rehabilitación", intro: "El tratamiento debe ser temprano y multidisciplinario:", subsections: [ { title: "Opciones Terapéuticas", items: ["Fisioterapia activa (crucial para mantener la extremidad en movimiento y prevenir la atrofia muscular)", "Medicamentos (analgésicos, antidepresivos, anticonvulsivos para el dolor nervioso, y corticosteroides)", "Bloqueos nerviosos simpáticos (inyecciones de anestésicos para bloquear las señales de dolor)", "Estimulación de la médula espinal (implante de un dispositivo en casos crónicos severos)"] } ], note: "La inmovilización prolongada empeora la afección; mover la extremidad es vital." }, whenToSeekHelp: { title: "¿Cuándo acudir al especialista en dolor?", intro: "Busca atención médica si experimentas:", items: ["Dolor urente o punzante severo y constante en un brazo, pierna, mano o pie", "Cambios en el color de la piel (roja, azulada o pálida) y en la temperatura de la extremidad afectada", "Hinchazón constante, rigidez articular o cambios anormales en el crecimiento de uñas y vello"] } },
'Deformidad en valgo del dedo gordo' : { intro: "La deformidad en valgo del dedo gordo, comúnmente conocida como juanete (hallux valgus), es una protuberancia ósea que se forma en la articulación en la base del dedo gordo del pie, causando que este se desvíe hacia los demás dedos.", whatIs: { title: "¿Qué es el Hallux Valgus?", text: "Es una alteración biomecánica progresiva del pie. Los huesos de la parte frontal se desalinean, haciendo que el primer metatarsiano sobresalga hacia afuera y la falange del dedo gordo apunte hacia adentro. Esta fricción crea una bursa inflamada y hueso extra (el juanete)." }, types: { title: "Clasificación", intro: "Se evalúa según el ángulo de desviación:", items: ["Leve (ángulo de deformidad pequeño, a menudo asintomático)", "Moderado (desviación notoria, dolor al usar calzado ajustado)", "Severo (el dedo gordo puede cruzarse por encima o por debajo del segundo dedo, causando dolor crónico y callosidades)"], note: "La genética, la forma del pie y el uso prolongado de zapatos estrechos o de tacón alto son los principales responsables." }, diagnosis: { title: "Evaluación Podológica/Ortopédica", intro: "El diagnóstico es visual y se confirma con placas:", items: ["Examen físico del pie en reposo y de pie (soportando peso)", "Radiografías de los pies (para medir los ángulos exactos entre los huesos y evaluar el grado de artrosis en la articulación)"], note: "" }, treatment: { title: "Manejo Conservador y Cirugía", intro: "El tratamiento inicial busca aliviar el dolor, pero solo la cirugía corrige la deformidad:", subsections: [ { title: "Opciones", items: ["Cambio de calzado (usar zapatos de horma ancha, sin tacón, que no aprieten los dedos)", "Almohadillas para juanetes, espaciadores de dedos y plantillas ortopédicas", "Analgésicos y hielo para la inflamación aguda", "Cirugía u osteotomía (cortar y realinear los huesos; indicada solo cuando el dolor es incapacitante y altera la calidad de vida)"] } ], note: "No se recomienda operar un juanete que no duele únicamente por motivos estéticos." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico o podólogo?", intro: "Acude a un especialista si presentas:", items: ["Dolor continuo en la base del dedo gordo que te impide caminar o hacer tus actividades", "Dificultad severa para encontrar zapatos que te queden bien o no te duelan", "Enrojecimiento extremo e hinchazón en la articulación (podría indicar bursitis o gota)", "Disminución en el movimiento de tu dedo gordo"] } },
'Miedo' : { intro: "El miedo es una emoción humana natural y de supervivencia frente a una amenaza real. Sin embargo, cuando el miedo se vuelve irracional, abrumador, desproporcionado e interfiere con la vida diaria, se clasifica como una fobia o un trastorno de ansiedad.", whatIs: { title: "¿Qué es el Miedo Patológico (Fobia)?", text: "Es un tipo de trastorno de ansiedad. Mientras que el miedo normal es una respuesta a un peligro inmediato, el miedo fóbico desencadena una respuesta de 'lucha o huida' intensa ante situaciones, objetos o animales que no representan un peligro real, provocando evitación severa." }, types: { title: "Categorías Comunes de Miedos Extremos", intro: "Las fobias se agrupan en:", items: ["Fobias específicas (miedo a volar, a las alturas, a las arañas, a las inyecciones)", "Fobia social o trastorno de ansiedad social (miedo intenso a la evaluación pública y al juicio de los demás)", "Agorafobia (miedo a lugares donde escapar podría ser difícil, como multitudes o espacios abiertos/cerrados)"], note: "El paciente sabe que su miedo es irracional, pero no puede controlarlo físicamente." }, diagnosis: { title: "Evaluación Psicológica", intro: "El diagnóstico se basa en el impacto en la vida de la persona:", items: ["Entrevista clínica con un psicólogo o psiquiatra", "Evaluación según el manual DSM-5 (el miedo dura más de 6 meses y causa un malestar clínico significativo)"], note: "" }, treatment: { title: "Terapia y Reacondicionamiento", intro: "Las fobias y miedos extremos son altamente tratables:", subsections: [ { title: "Intervenciones", items: ["Terapia de Exposición (la más efectiva; exponer al paciente gradual y seguramente a lo que teme hasta que la ansiedad disminuya)", "Terapia Cognitivo-Conductual (TCC) para cambiar los patrones de pensamiento irracionales", "Medicamentos (betabloqueantes o ansiolíticos usados ocasionalmente para controlar los síntomas físicos de pánico en situaciones ineludibles)"] } ], note: "Evitar el objeto de miedo a largo plazo refuerza y empeora el trastorno." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda profesional?", intro: "Debes buscar apoyo psicológico si:", items: ["El miedo te produce ataques de pánico (taquicardia, falta de aire, sudoración, sensación de muerte)", "La evitación altera tu rutina diaria, trabajo, escuela o relaciones sociales", "Sientes que el miedo ha tomado el control de tus decisiones vitales"] } },
'Delirio' : { intro: "El delirio (o delirium, síndrome confusional agudo) es un cambio repentino, grave y fluctuante en la función mental. Causa confusión aguda, incapacidad para pensar con claridad y una desconexión severa con el entorno.", whatIs: { title: "¿Qué es el Delirio?", text: "Es una emergencia médica que afecta la atención y la conciencia. A diferencia de la demencia (que es una enfermedad cerebral lenta y progresiva), el delirio aparece de golpe, a menudo en el transcurso de horas o días, y usualmente es provocado por una enfermedad física grave, infecciones, toxicidad o desequilibrio metabólico." }, types: { title: "Tipos de Presentación", intro: "Puede presentarse de maneras opuestas:", items: ["Hiperactivo (la persona está agitada, inquieta, agresiva, con alucinaciones o paranoias)", "Hipoactivo (la persona está inusualmente aletargada, somnolienta, retraída y lenta para responder)", "Mixto (alterna entre estados de agitación y letargo a lo largo del día)"], note: "Es muy común en pacientes ancianos hospitalizados o tras una cirugía (delirio posoperatorio)." }, diagnosis: { title: "Evaluación de Urgencia", intro: "El objetivo es encontrar la causa física subyacente:", items: ["Evaluación del estado mental e historia clínica (usualmente proporcionada por familiares que notan el cambio brusco)", "Análisis de sangre y orina (para detectar infecciones urinarias, neumonía, problemas renales o hepáticos)", "Revisión exhaustiva de medicamentos (la polifarmacia y los sedantes son grandes causantes)", "Pruebas de imagen cerebral (TC) si se sospecha un evento neurológico o caída"], note: "" }, treatment: { title: "Tratamiento Causal y Soporte", intro: "El delirio desaparece al curar lo que lo está provocando:", subsections: [ { title: "Intervenciones Médicas", items: ["Tratar la causa subyacente (antibióticos para infecciones, corrección de líquidos y electrolitos, suspensión de fármacos tóxicos)", "Intervenciones ambientales (mantener la habitación tranquila, bien iluminada, con relojes y calendarios, y presencia de familiares para reorientar)", "Medicamentos antipsicóticos en dosis bajas (solo si el paciente está en peligro de lastimarse a sí mismo o al personal médico)"] } ], note: "Restringir físicamente a un paciente con delirio suele empeorar drásticamente la agitación." }, whenToSeekHelp: { title: "¿Cuándo es una urgencia?", intro: "Llama a urgencias o ve al hospital si un familiar, especialmente mayor, presenta:", items: ["Un cambio brusco y repentino en su personalidad o estado mental", "Confusión extrema, no reconoce dónde está ni a sus familiares", "Alucinaciones visuales y agitación severa o agresividad inusual", "Somnolencia profunda e incapacidad para mantenerse despierto"] } },
'Encopresis' : { intro: "La encopresis es la evacuación involuntaria de heces (ensuciar la ropa interior) en niños que ya tienen la edad suficiente para haber aprendido a controlar sus esfínteres, generalmente mayores de 4 años.", whatIs: { title: "¿Qué es la Encopresis?", text: "En la gran mayoría de los casos, no es un problema de comportamiento o pereza, sino una afección física causada por un estreñimiento crónico severo. Las heces duras se acumulan y bloquean el recto, estirando los nervios. Con el tiempo, el niño pierde la sensación de que necesita ir al baño, y las heces líquidas más nuevas se filtran alrededor de la masa dura, manchando la ropa." }, types: { title: "Clasificación Clínica", intro: "Se divide principalmente en dos tipos:", items: ["Encopresis retentiva (asociada al estreñimiento crónico; es la más común. El niño retiene las heces por miedo al dolor al defecar)", "Encopresis no retentiva (menos común, sin estreñimiento; a menudo vinculada a estrés emocional profundo, trastorno de oposición desafiante o problemas de entrenamiento de esfínteres)"], note: "El niño a menudo oculta la ropa sucia por vergüenza y culpa." }, diagnosis: { title: "Evaluación Pediátrica", intro: "El médico buscará confirmar la impactación fecal:", items: ["Examen físico del abdomen (a menudo se puede palpar una masa dura de heces) y tacto rectal", "Radiografía abdominal (para visualizar la cantidad de heces acumuladas en el colon y confirmar el estreñimiento crónico)"], note: "" }, treatment: { title: "Desimpactación y Reeducación", intro: "El tratamiento requiere tiempo y paciencia, centrándose en vaciar el intestino y mantenerlo blando:", subsections: [ { title: "Fases del Tratamiento", items: ["Desimpactación (limpiar el colon de heces duras mediante enemas, supositorios o laxantes osmóticos fuertes bajo supervisión médica)", "Terapia de mantenimiento (uso diario de laxantes suaves como polietilenglicol durante meses para asegurar que las heces sean siempre blandas y el colon recupere su tamaño y sensibilidad)", "Modificación del comportamiento (establecer rutinas: sentar al niño en el inodoro durante 5-10 minutos después de cada comida)", "Dieta rica en fibra y aumento masivo de líquidos"] } ], note: "Castigar o avergonzar al niño empeora el problema, ya que aumenta la ansiedad y la retención." }, whenToSeekHelp: { title: "¿Cuándo consultar al pediatra?", intro: "Programa una cita médica si:", items: ["Tu hijo mayor de 4 años ensucia su ropa interior con heces frecuentemente", "El niño experimenta dolor al defecar o evita ir al baño", "Notas episodios alternados de estreñimiento severo y diarrea líquida", "El problema causa aislamiento social o baja autoestima en el niño"] } },
'Inseguridad' : { intro: "La inseguridad emocional es una sensación profunda de duda, falta de confianza en uno mismo y ansiedad respecto a las propias capacidades, valor o posición en las relaciones con los demás. Cuando es severa, puede ser un síntoma de un trastorno de salud mental.", whatIs: { title: "¿Qué es la Inseguridad Patológica?", text: "Es un estado psicológico donde la persona se siente constantemente amenazada por el rechazo o el fracaso. Puede paralizar el desarrollo personal, generar celos destructivos en las relaciones, fobia social, y está estrechamente ligada a la baja autoestima y trastornos de ansiedad." }, types: { title: "Áreas de Afectación", intro: "La inseguridad puede manifestarse en diferentes esferas:", items: ["Inseguridad relacional (celos extremos, miedo al abandono, apego ansioso)", "Inseguridad social (ansiedad social, miedo a ser juzgado o humillado en público)", "Inseguridad laboral o académica (síndrome del impostor, perfeccionismo paralizante)", "Inseguridad corporal (trastornos de la imagen corporal, dismorfia)"], note: "Suele originarse por experiencias traumáticas tempranas, estilos de apego inseguros en la infancia o acoso escolar." }, diagnosis: { title: "Evaluación Psicológica", intro: "Un terapeuta evalúa si la inseguridad es parte de un trastorno mayor:", items: ["Entrevista clínica para evaluar patrones de pensamiento y comportamiento", "Evaluación de síntomas de Trastorno de Ansiedad Generalizada, Fobia Social o Depresión", "Análisis de la dinámica de las relaciones interpersonales de la persona"], note: "" }, treatment: { title: "Psicoterapia y Desarrollo Personal", intro: "El objetivo es reconstruir la autoeficacia y modificar creencias limitantes:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Terapia Cognitivo-Conductual (TCC) (para identificar y desafiar los pensamientos autocríticos y distorsionados)", "Terapia de Aceptación y Compromiso (ACT) o Mindfulness", "Entrenamiento en habilidades sociales y asertividad", "Terapia de pareja (si la inseguridad está destruyendo la relación por celos o dependencia)"] } ], note: "La validación externa constante no cura la inseguridad; el trabajo debe ser interno." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda terapéutica?", intro: "Es altamente recomendable consultar a un psicólogo si la inseguridad:", items: ["Te impide perseguir metas laborales, académicas o conocer gente nueva", "Provoca celos obsesivos, control o dependencia emocional tóxica hacia tu pareja", "Te causa angustia constante, depresión, aislamiento social o ataques de ansiedad", "Deriva en trastornos alimentarios o autolesiones por odio hacia ti mismo"] } },
'Alergia al moho, la caspa y el polvo' : { intro: "Las alergias al moho, la caspa de animales y los ácaros del polvo son reacciones exageradas del sistema inmunológico a sustancias ambientales en interiores que, para la mayoría de las personas, son completamente inofensivas. Se manifiestan como rinitis alérgica o asma.", whatIs: { title: "¿Qué son las Alergias de Interior?", text: "El sistema inmunitario identifica erróneamente estas partículas (alérgenos) como invasores peligrosos y produce anticuerpos (IgE). Cada vez que respiras polvo, esporas de moho o piel muerta de mascotas (caspa), tu cuerpo libera histamina, causando inflamación en la nariz, ojos y pulmones." }, types: { title: "Tipos de Alérgenos Comunes", intro: "Los desencadenantes principales en el hogar son:", items: ["Ácaros del polvo (insectos microscópicos que viven en colchones, almohadas, alfombras y se alimentan de piel humana)", "Caspa de mascotas (escamas de piel muerta, saliva y orina de perros, gatos o roedores; el pelo en sí no es el alérgeno principal)", "Esporas de moho (hongos microscópicos que crecen en lugares húmedos y oscuros como baños, sótanos o paredes con filtraciones)"], note: "Estas alergias suelen ser 'perennes', es decir, causan síntomas crónicos durante todo el año, no solo en primavera." }, diagnosis: { title: "Pruebas Alergológicas", intro: "El alergólogo confirmará a qué eres sensible exactamente:", items: ["Prueba de punción cutánea (Prick test) (se aplican extractos de alérgenos en el brazo y se pincha la piel; si eres alérgico, aparece una roncha roja en minutos)", "Análisis de sangre (IgE específica) (para medir la cantidad de anticuerpos contra alérgenos específicos si las pruebas cutáneas no se pueden realizar)"], note: "" }, treatment: { title: "Evitación y Control Médico", intro: "El mejor tratamiento es reducir la exposición y bloquear la respuesta inmune:", subsections: [ { title: "Manejo y Terapias", items: ["Control ambiental en casa (fundas antiácaros en colchones, quitar alfombras, usar deshumidificadores, bañar a las mascotas y usar filtros HEPA)", "Antihistamínicos orales (cetirizina, loratadina para estornudos y picor)", "Corticosteroides nasales en aerosol (el tratamiento más eficaz para la congestión crónica e inflamación nasal)", "Inmunoterapia (vacunas contra la alergia o gotas sublinguales; entrenan al sistema inmunológico gradualmente para dejar de reaccionar al alérgeno)"] } ], note: "Evitar que la mascota duerma en el dormitorio de la persona alérgica es crucial." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Busca tratamiento médico especializado si:", items: ["Tus síntomas de alergia (congestión, estornudos) duran todo el año e interfieren con tu sueño o rendimiento", "Los medicamentos de venta libre no logran controlar tus síntomas de manera efectiva", "Sientes opresión en el pecho, silbidos al respirar (sibilancias) o te falta el aire (signos de que la alergia está desencadenando asma)"] } },
'Aneurisma aórtico' : { intro: "Un aneurisma aórtico es una dilatación, abultamiento o ensanchamiento anormal y peligroso en la pared de la aorta, la arteria principal y más grande del cuerpo que lleva la sangre desde el corazón al resto del organismo.", whatIs: { title: "¿Qué es un Aneurisma de la Aorta?", text: "La pared de la aorta puede debilitarse por la edad, la hipertensión o placas de colesterol. La presión constante de la sangre que bombea el corazón hace que esta zona débil se infle como un globo. Si el aneurisma crece demasiado, puede desgarrarse (disección) o estallar (ruptura), causando una hemorragia interna masiva y a menudo mortal." }, types: { title: "Ubicaciones Principales", intro: "Se dividen según la zona del cuerpo donde ocurren:", items: ["Aneurisma aórtico abdominal (AAA) (ocurre en la parte de la aorta que pasa por el abdomen; es el tipo más común y a menudo asintomático)", "Aneurisma aórtico torácico (AAT) (ocurre en la parte de la aorta que atraviesa el pecho)"], note: "Los hombres mayores de 65 años con antecedentes de tabaquismo tienen el mayor riesgo de desarrollar un AAA." }, diagnosis: { title: "Detección por Imágenes", intro: "Suelen crecer silenciosamente y se descubren en pruebas por otras razones:", items: ["Ecografía abdominal (la prueba principal y más común para detectar y medir aneurismas abdominales; a menudo se usa como cribado en fumadores mayores)", "Tomografía Computarizada (TC) o Angio-TC (proporciona imágenes detalladas del tamaño y forma exacta del aneurisma para planificar cirugías)", "Resonancia Magnética (RM) y Ecocardiograma (para evaluar aneurismas torácicos)"], note: "" }, treatment: { title: "Vigilancia o Reparación Quirúrgica", intro: "El tratamiento depende estrictamente del tamaño del aneurisma y la velocidad a la que crece:", subsections: [ { title: "Intervenciones", items: ["Espera vigilante (para aneurismas pequeños; el médico receta fármacos para bajar la presión arterial/colesterol y hace ecografías cada 6 o 12 meses)", "Reparación endovascular (EVAR) (procedimiento mínimamente invasivo; se inserta un tubo de malla o endoprótesis recubierta por la arteria de la ingle hasta la aorta para reforzar la pared débil desde adentro)", "Cirugía abierta (el cirujano abre el pecho o abdomen, retira la sección dañada de la aorta y cose un tubo sintético en su lugar)"] } ], note: "Dejar de fumar y controlar la presión arterial son las únicas formas de frenar su crecimiento." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia de vida o muerte?", intro: "Una rotura o disección aórtica es una de las mayores emergencias médicas. Llama al 911 de inmediato si sientes:", items: ["Un dolor repentino, desgarrador, punzante o intenso en la espalda, el abdomen o el pecho (a menudo descrito como si 'algo se rasgara por dentro')", "Caída brusca de la presión arterial, mareo extremo, palidez, sudoración fría, pulso rápido o desmayo", "Una sensación pulsátil fuerte (como un latido del corazón) constante y anormal cerca del ombligo"] } },
'Accidente cardiovascular' : { intro: "Un accidente cardiovascular es un término amplio que se refiere a eventos agudos y críticos que afectan el corazón o el cerebro debido a un problema repentino en los vasos sanguíneos (isquemia o hemorragia). Generalmente se utiliza para referirse a un infarto de miocardio (ataque cardíaco) o a un accidente cerebrovascular (derrame cerebral).", whatIs: { title: "¿Qué es un Evento Cardiovascular Agudo?", text: "Es la interrupción repentina del suministro de sangre rica en oxígeno a un órgano vital. En el corazón, causa la muerte del músculo cardíaco (infarto). En el cerebro, causa la muerte de las neuronas (ictus). Ambos son causados mayoritariamente por la enfermedad de las arterias coronarias o carótidas, donde placas de colesterol se rompen y forman coágulos." }, types: { title: "Eventos Principales", intro: "Las dos emergencias primarias incluyen:", items: ["Ataque cardíaco (Infarto Agudo de Miocardio): Bloqueo en una arteria coronaria. Los síntomas incluyen opresión en el pecho, dolor en el brazo izquierdo, falta de aire y sudor frío.", "Accidente Cerebrovascular (ACV o Derrame): Puede ser isquémico (coágulo en el cerebro) o hemorrágico (rotura de vaso). Los síntomas incluyen parálisis facial, debilidad en un brazo y dificultad para hablar."], note: "Ambas condiciones comparten los mismos factores de riesgo: hipertensión, diabetes, tabaquismo, colesterol alto y obesidad." }, diagnosis: { title: "Pruebas de Emergencia Hospitalaria", intro: "El diagnóstico debe ser inmediato para salvar el tejido:", items: ["Para ataque cardíaco: Electrocardiograma (ECG) instantáneo y análisis de sangre para enzimas cardíacas (Troponinas)", "Para accidente cerebrovascular: Tomografía Computarizada (TC) de cráneo inmediata sin contraste para ver si hay sangrado, y evaluación neurológica rápida", "Angiografías (para ver el interior de los vasos sanguíneos afectados)"], note: "" }, treatment: { title: "Restauración del Flujo Sanguíneo", intro: "El tiempo es el factor más crítico; el tratamiento busca destapar el vaso sanguíneo en las primeras horas:", subsections: [ { title: "Intervenciones Críticas", items: ["Medicamentos Trombolíticos (fármacos por vena que disuelven los coágulos de sangre, aplicables tanto en infartos como en derrames isquémicos si el paciente llega a tiempo)", "Cateterismo y Angioplastia (para el corazón, inflar un globo y colocar un stent en la arteria)", "Trombectomía Mecánica (para el cerebro, extracción física del coágulo con un catéter)", "Cirugía de Bypass (para el corazón) o cirugía para aliviar presión/clipar aneurismas (para derrames hemorrágicos)"] } ], note: "La rehabilitación posterior y la medicación de por vida (aspirina, estatinas) son obligatorias para evitar recurrencias." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911?", intro: "Son emergencias absolutas donde los minutos cuentan. Llama a una ambulancia INMEDIATAMENTE si observas:", items: ["Dolor o presión aplastante en el pecho que se irradia a la mandíbula o brazo", "Caída repentina de un lado de la cara (sonrisa torcida)", "Debilidad repentina o imposibilidad de levantar un brazo", "Dificultad súbita para hablar, pronunciar palabras o comprender lo que se dice", "Falta de aire severa, sudoración fría, mareo extremo o pérdida de conocimiento"] } },
'Diarrea crónica' : { intro: "La diarrea crónica se define como la alteración en las evacuaciones, produciendo heces sueltas, acuosas o líquidas que persisten de manera continua o intermitente durante cuatro semanas o más.", whatIs: { title: "¿Qué es la Diarrea Crónica?", text: "A diferencia de una diarrea aguda y temporal (usualmente infecciosa), la diarrea crónica es un síntoma prolongado que indica un problema subyacente crónico en el tracto digestivo, como una mala absorción, inflamación, o trastornos en la motilidad intestinal que interfieren enormemente con la vida del paciente." }, types: { title: "Tipos y Causas Subyacentes", intro: "Se categoriza médicamente según su origen funcional:", items: ["Diarrea osmótica (sustancias no absorbidas retienen agua en el intestino, ej. intolerancia a la lactosa)", "Diarrea secretora (el intestino secreta demasiada agua, a menudo por toxinas o ciertos tumores endocrinos)", "Diarrea inflamatoria (hay daño en el tejido, presencia de sangre o pus, típico de Crohn o Colitis Ulcerosa)", "Trastornos de la motilidad (el alimento pasa muy rápido, clásico del Síndrome de Intestino Irritable - SII)"], note: "Enfermedades como la celiaquía o problemas de la glándula tiroides (hipertiroidismo) son causantes muy frecuentes." }, diagnosis: { title: "Evaluación Gastroenterológica", intro: "Se requiere un estudio detallado para encontrar al verdadero culpable:", items: ["Análisis de heces detallado (para buscar bacterias persistentes, parásitos, sangre oculta, grasa y medir la calprotectina)", "Análisis de sangre (para descartar celiaquía, problemas de tiroides, inflamación y malnutrición)", "Colonoscopia y/o endoscopia superior con biopsias (esenciales para visualizar inflamación o cáncer de colon)", "Pruebas de aliento (para diagnosticar sobrecrecimiento bacteriano - SIBO o intolerancias alimentarias)"], note: "" }, treatment: { title: "Manejo Nutricional y Farmacológico", intro: "El tratamiento se dirige estrictamente a la causa raíz descubierta:", subsections: [ { title: "Intervenciones", items: ["Dietas de eliminación y modificaciones nutricionales (si hay intolerancias o enfermedad celíaca)", "Medicamentos antidiarreicos y antiespasmódicos (como loperamida, para reducir el tránsito)", "Fármacos antiinflamatorios o biológicos (para controlar la Enfermedad Inflamatoria Intestinal)", "Antibióticos o antiparasitarios específicos (si la causa es un patógeno crónico)"] } ], note: "La reposición constante de líquidos y electrolitos es crucial para evitar una deshidratación lenta y sostenida." }, whenToSeekHelp: { title: "¿Cuándo es imperativo ir al médico?", intro: "No debes normalizar el vivir con diarrea. Acude al especialista o a urgencias si presentas:", items: ["Diarrea persistente por más de tres semanas, sin mejoras, y que interrumpe tu descanso nocturno", "Pérdida de peso significativa y rápida sin intentarlo", "Presencia visible de sangre roja brillante o heces negras como el alquitrán", "Dolor abdominal severo continuo, fiebre inexplicable o episodios de mareos extremos al ponerte de pie (deshidratación)"] } },
'Cambios en la piel inducidos por el sol' : { intro: "Los cambios en la piel inducidos por el sol, comúnmente conocidos como fotoenvejecimiento, son las alteraciones prematuras en la textura, tono, firmeza y salud general de la piel causadas por la exposición crónica y sin protección a los rayos ultravioleta (UV).", whatIs: { title: "¿Qué es el Fotoenvejecimiento?", text: "El daño solar es acumulativo. A lo largo de la vida, la radiación ultravioleta penetra la epidermis y destruye las fibras de colágeno y elastina de la dermis profunda. Esto hace que la piel pierda su soporte estructural, volviéndose flácida, arrugada, manchada y extremadamente propensa a desarrollar lesiones cancerosas." }, types: { title: "Manifestaciones Clínicas Visibles", intro: "El sol provoca múltiples daños evidentes:", items: ["Lentigos solares o manchas de la edad (manchas planas, marrones u oscuras en cara, manos y brazos)", "Elastosis solar (piel amarillenta, engrosada y con arrugas muy profundas)", "Telangiectasias (pequeños vasos sanguíneos rotos o 'arañas vasculares' en mejillas y nariz)", "Queratosis actínicas (lesiones precancerosas: parches ásperos, escamosos y rojizos que a veces duelen o sangran)"], note: "El 80% del envejecimiento visible del rostro humano es culpa del sol, no de la edad." }, diagnosis: { title: "Examen Dermatológico", intro: "El dermatólogo evalúa el daño y descarta malignidad:", items: ["Examen físico integral de la piel de todo el cuerpo", "Dermatoscopia (uso de un instrumento de aumento iluminado para ver el pigmento profundo de las manchas)", "Biopsia de piel (esencial y obligatoria si se sospecha que una mancha áspera se ha convertido en carcinoma o melanoma)"], note: "" }, treatment: { title: "Prevención, Reparación y Cosmética Médica", intro: "El daño estructural no se cura con cremas hidratantes, requiere intervención activa:", subsections: [ { title: "Tratamientos y Procedimientos", items: ["Protección solar estricta (el uso diario e innegociable de factor SPF 50+, sombreros y evitar horas pico es el único método para frenar el daño)", "Retinoides tópicos recetados (Tretinoína; el único compuesto probado para reparar parcialmente el colágeno dañado y atenuar manchas)", "Procedimientos dermatológicos (Peelings químicos, terapias con luz pulsada -IPL-, o láseres fraccionados para eliminar las capas externas dañadas y renovar la piel)", "Crioterapia con nitrógeno líquido (para congelar y destruir las queratosis actínicas precancerosas)"] } ], note: "Las cámaras de bronceado son extremadamente dañinas y aceleran el fotoenvejecimiento y el riesgo de cáncer al máximo." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ver a un dermatólogo?", intro: "Más allá de la estética, busca revisión médica para descartar cáncer si:", items: ["Tienes una mancha áspera (queratosis) que no desaparece, es sensible al tacto o sangra al frotarla", "Un lunar nuevo o existente cambia rápidamente de forma, crece, pica, sangra o tiene bordes irregulares y múltiples colores (Regla ABCDE)", "Aparece una pequeña úlcera o herida en tu rostro, oreja o cuero cabelludo que no sana después de 4 semanas"] } },
'Deficiencia de vitamina D' : { intro: "La deficiencia de vitamina D ocurre cuando el cuerpo no tiene o no retiene los niveles suficientes de esta vitamina y hormona esencial. Es fundamental para la absorción de calcio, el mantenimiento de huesos fuertes, la función muscular y la respuesta del sistema inmunológico.", whatIs: { title: "¿Qué es la Deficiencia de Vitamina D?", text: "A diferencia de otras vitaminas, la vitamina D es producida por nuestra propia piel cuando nos exponemos a la luz solar directa. Si no nos exponemos al sol, no consumimos alimentos ricos en ella, o nuestros riñones/intestinos no la procesan adecuadamente, los niveles bajan dramáticamente, volviendo los huesos frágiles y quebradizos (raquitismo en niños y osteomalacia/osteoporosis en adultos)." }, types: { title: "Causas y Factores de Riesgo", intro: "La deficiencia suele estar promovida por el estilo de vida o enfermedades:", items: ["Baja exposición solar (personas que viven en latitudes altas, trabajan siempre en interiores o usan ropa que cubre todo el cuerpo)", "Tono de piel oscuro (la melanina reduce la capacidad de la piel para producir vitamina D)", "Problemas de malabsorción digestiva (personas con celiaquía, enfermedad de Crohn o que han tenido cirugías de bypass gástrico)", "Obesidad severa (la grasa corporal secuestra y atrapa la vitamina D, sacándola de la sangre)"], note: "En los adultos mayores, los riñones son menos eficientes al convertir la vitamina D a su forma activa." }, diagnosis: { title: "Análisis Sanguíneo Endocrino", intro: "La deficiencia suele ser asintomática hasta que es severa. Se detecta con:", items: ["Examen de sangre de 25-hidroxivitamina D (la única prueba precisa para saber si los niveles son óptimos, insuficientes o deficientes)", "Análisis de calcio y fósforo en sangre", "Densitometría ósea (DEXA) para comprobar si la deficiencia prolongada ya ha causado osteoporosis o adelgazamiento del hueso"], note: "" }, treatment: { title: "Suplementación y Exposición Segura", intro: "Es altamente tratable y reversible con la dosis adecuada:", subsections: [ { title: "Opciones de Tratamiento", items: ["Suplementos orales de venta libre o recetados (Vitamina D3 -colecalciferol- o D2 en dosis altas de choque seguidas de dosis de mantenimiento diario/semanal)", "Aumento de la exposición solar segura (10 a 15 minutos diarios en brazos y piernas antes de aplicar el protector solar, dependiendo del índice UV local)", "Dieta enriquecida (aumentar el consumo de pescados grasos como salmón, yemas de huevo o lácteos y cereales fortificados)"] } ], note: "Tomar demasiada vitamina D en suplementos por cuenta propia puede causar toxicidad y exceso de calcio en sangre (hipercalcemia)." }, whenToSeekHelp: { title: "¿Cuándo consultar al médico?", intro: "Pide una revisión analítica si te encuentras en un grupo de riesgo o presentas:", items: ["Dolor óseo profundo, sordo y persistente, especialmente en la espalda, pelvis o piernas", "Debilidad muscular progresiva o calambres que te dificultan levantarte de una silla o subir escaleras", "Fatiga crónica y agotamiento inexplicable que no mejora al dormir", "Sufres una fractura ósea tras una caída muy leve o un impacto menor"] } },
'Hombro doloroso' : { intro: "El 'hombro doloroso' es un término clínico amplio utilizado para describir cualquier dolor localizado en la compleja articulación del hombro, la cual es la más móvil del cuerpo humano pero también la más inestable y susceptible a lesiones por desgaste o sobreesfuerzo.", whatIs: { title: "¿Qué es el Síndrome del Hombro Doloroso?", text: "No es una enfermedad por sí misma, sino un síntoma de alarma. El hombro está compuesto por huesos, la cápsula articular, bursas (bolsas de líquido) y un grupo de músculos y tendones conocido como el manguito rotador. El daño, inflamación o pellizco en cualquiera de estas estructuras resulta en dolor e impotencia funcional." }, types: { title: "Patologías Subyacentes Frecuentes", intro: "El dolor puede provenir de varias condiciones específicas:", items: ["Tendinitis o desgarro del Manguito Rotador (inflamación o rotura de los tendones por esfuerzo repetitivo al levantar el brazo, común en pintores o deportistas)", "Bursitis subacromial (inflamación de la bursa que amortigua los tendones)", "Hombro congelado o Capsulitis adhesiva (rigidez extrema de la cápsula articular que impide por completo mover el brazo)", "Síndrome de pinzamiento (el tendón roza y se atasca contra el hueso del omóplato al levantar el brazo)", "Artrosis (desgaste del cartílago, más común con la edad)"], note: "" }, diagnosis: { title: "Evaluación Ortopédica y Pruebas", intro: "El traumatólogo localizará la causa exacta del dolor mediante:", items: ["Examen físico y maniobras mecánicas (el médico moverá el brazo y pedirá que hagas fuerza contra resistencia para identificar qué tendón o músculo específico está dañado)", "Radiografías (para descartar artritis severa, calcificaciones en los tendones o fracturas)", "Ecografía musculoesquelética o Resonancia Magnética (RM) (para ver los tejidos blandos y confirmar desgarros parciales o totales de ligamentos y tendones)"], note: "" }, treatment: { title: "Fisioterapia y Control Inflamatorio", intro: "El tratamiento inicial es siempre conservador y de rehabilitación:", subsections: [ { title: "Intervenciones", items: ["Reposo relativo (evitar posiciones y movimientos por encima de la cabeza, pero no inmovilizar totalmente para evitar que se 'congele')", "Analgésicos y antiinflamatorios (AINEs)", "Fisioterapia (vital para fortalecer los músculos alrededor del manguito y recuperar la biomecánica correcta)", "Infiltraciones (inyecciones locales de corticosteroides para reducir rápidamente la inflamación aguda)", "Cirugía artroscópica (si hay un desgarro tendinoso total, artrosis severa o si fracasa el tratamiento conservador tras varios meses)"] } ], note: "El dolor de hombro que no se atiende a tiempo suele derivar en rigidez crónica y debilidad muscular severa." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Busca atención traumatológica temprana, y acude de urgencia si:", items: ["Experimentas un dolor agudo e inmovilizante en el hombro tras una caída, traumatismo o al levantar un objeto pesado (posible dislocación o desgarro agudo)", "El hombro se ve visiblemente deformado o fuera de su lugar natural", "El dolor empeora agresivamente por la noche y es imposible dormir sobre ese lado", "Eres totalmente incapaz de levantar el brazo para peinarte, vestirte o alcanzar un estante", "Sientes debilidad extrema o el brazo se te 'cae' al intentar sostener un peso"] } },
'Cefalea en racimo' : { intro: "La cefalea en racimo (o dolor de cabeza en racimos) es un trastorno neurológico extraordinariamente doloroso. Se caracteriza por ataques de dolor insoportable, unilateral y punzante, que ocurren en ráfagas o 'racimos' cíclicos durante semanas o meses, seguidos de periodos sin dolor.", whatIs: { title: "¿Qué es la Cefalea en Racimo?", text: "A menudo descrita como 'el dolor más fuerte que un ser humano puede soportar' o 'cefalea suicida'. A diferencia de la migraña, que te hace querer acostarte a oscuras, el dolor en racimo produce una inquietud tan violenta que el paciente camina de un lado a otro o se mece por la agonía. Se cree que su origen radica en una anomalía en el hipotálamo (el reloj biológico del cerebro)." }, types: { title: "Fases y Desencadenantes", intro: "Tiene un patrón temporal muy estricto e inusual:", items: ["Patrón de ataque (el dolor suele durar entre 15 minutos y 3 horas; ocurre varias veces al día, frecuentemente despertando a la persona a la misma hora cada noche)", "Episódica (la más común, el período de ataques dura semanas a meses, seguido de meses o años de remisión absoluta)", "Crónica (los ataques ocurren por más de un año sin ningún período de remisión largo)"], note: "El consumo de alcohol, y a veces ciertos olores fuertes, son los detonantes más seguros durante un ciclo activo." }, diagnosis: { title: "Examen Neurológico", intro: "El diagnóstico se basa firmemente en el patrón del dolor:", items: ["Historia clínica detallada del dolor unilateral (siempre en un solo lado) y los síntomas autonómicos", "Examen neurológico completo", "Resonancia Magnética (RM) del cerebro (se realiza siempre una vez para descartar absolutamente tumores, aneurismas o malformaciones vasculares, pero en la cefalea en racimo la RM sale limpia)"], note: "" }, treatment: { title: "Intervención de Aborto y Prevención", intro: "Los analgésicos comunes (ibuprofeno, paracetamol) no sirven porque actúan demasiado lento. El tratamiento debe ser instantáneo:", subsections: [ { title: "Opciones de Acción Rápida y Mantenimiento", items: ["Oxigenoterapia pura (el tratamiento de choque de oro; inhalar oxígeno al 100% mediante mascarilla interrumpe el ataque doloroso en unos 15 minutos en la mayoría de pacientes)", "Triptanes de acción rápida (como inyecciones subcutáneas de sumatriptán o aerosoles nasales, recetados para abortar la crisis)", "Terapia preventiva (imprescindible; medicamentos como Verapamilo, corticoides o galcanezumab se toman diariamente durante el 'racimo' para evitar que ocurran los ataques)", "Estimulación del nervio vago o bloqueos nerviosos locales en la base del cráneo para casos refractarios severos"] } ], note: "El paciente debe evitar estrictamente cualquier gota de alcohol o tabaco mientras esté pasando por un período de racimo activo." }, whenToSeekHelp: { title: "¿Cuándo acudir de emergencia?", intro: "Aunque la cefalea en racimo es benigna, su presentación imita problemas graves. Acude a Urgencias inmediatamente si:", items: ["Tienes 'el peor dolor de cabeza de tu vida', especialmente si aparece por primera vez de forma explosiva y repentina", "El dolor viene acompañado de fiebre, rigidez dura en el cuello (sospecha de meningitis), confusión mental o convulsiones", "Experimentas debilidad muscular en un lado del cuerpo, entumecimiento o dificultad súbita para hablar y pronunciar palabras (banderas rojas de un derrame cerebral)", "Los ataques actuales están generando pensamientos autodestructivos incontrolables o ideas suicidas por el dolor extremo"] }, symptoms: { title: "Síntomas Clásicos Acompañantes", intro: "El dolor atroz siempre se centra detrás o alrededor de un ojo, acompañado de signos en el mismo lado de la cara:", groups: [ { name: "Signos Autonómicos (Unilaterales)", items: ["Enrojecimiento intenso y lagrimeo masivo en el ojo del lado del dolor", "Párpado caído o hinchado (ptosis)", "Congestión nasal severa o secreción (moqueo) solo por esa fosa nasal", "Sudoración profunda en la frente o cara del lado afectado", "Agitación e inquietud motora incontrolable"] } ], warning: "Si hay debilidad en el brazo o dificultad para hablar, no es cefalea en racimo, es una urgencia neurológica." } },
'Peritonitis asociada con diálisis' : { intro: "La peritonitis asociada con la diálisis es una infección bacteriana aguda y peligrosa del peritoneo (la membrana que recubre la cavidad abdominal y los órganos), que ocurre exclusivamente en pacientes que están en tratamiento de diálisis peritoneal por insuficiencia renal.", whatIs: { title: "¿Qué es esta Peritonitis?", text: "En la diálisis peritoneal, el paciente se introduce un líquido especial en el abdomen a través de un catéter permanente para limpiar su sangre. Si durante la manipulación del tubo se introducen bacterias de las manos, la piel o el ambiente, estas proliferan en el líquido abdominal caliente, creando una infección interna masiva y potencialmente letal." }, types: { title: "Orígenes de la Infección", intro: "Los microorganismos ingresan por diversas fallas:", items: ["Contaminación táctil (la causa más común, bacterias de la piel como Estafilococos entran al tocar la conexión del tubo sin higiene estricta)", "Infección del orificio de salida o del túnel del catéter (la piel alrededor del tubo se infecta y las bacterias viajan hacia adentro)", "Origen entérico o intestinal (menos común pero muy grave; bacterias del propio intestino del paciente cruzan al peritoneo debido a estreñimiento severo, diverticulitis o perforaciones)"], note: "Es la complicación y motivo de fracaso más frecuente por la cual los pacientes deben abandonar este tipo de diálisis." }, diagnosis: { title: "Detección Inmediata y Análisis del Líquido", intro: "El diagnóstico temprano es crítico y se basa en el aspecto de los desechos:", items: ["Líquido de efluente turbio (es el signo diagnóstico clave; al vaciar el líquido del abdomen, en lugar de ser cristalino, sale turbio, turbulento o blanco)", "Recuento de células y cultivo del líquido peritoneal (se extrae una muestra urgente para el laboratorio; si los glóbulos blancos están altos, se confirma, y el cultivo indicará qué antibiótico requiere la bacteria)", "Examen clínico (dolor abdominal) y análisis de sangre"], note: "" }, treatment: { title: "Antibioterapia de Choque", intro: "Se debe tratar antes de que la infección dañe permanentemente la membrana peritoneal o cause sepsis:", subsections: [ { title: "Protocolos Urgentes", items: ["Antibióticos intraperitoneales (el tratamiento principal: se inyectan fuertes dosis de antibióticos directamente en las bolsas de líquido de diálisis para atacar la infección en el abdomen localmente)", "Antibióticos intravenosos (si el paciente presenta fiebre alta o infección sanguínea - sepsis)", "Extracción quirúrgica del catéter (si la infección es causada por hongos, no mejora tras 5 días de antibióticos, o es repetitiva, el catéter debe ser retirado inmediatamente y el paciente deberá pasar a hemodiálisis por máquina en el brazo)"] } ], note: "La prevención mediante el lavado de manos quirúrgico y el uso de mascarilla en cada recambio diario de líquidos es la única manera de evitarla." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA MÉDICA?", intro: "Es una urgencia absoluta. Si eres paciente de diálisis peritoneal, contacta a tu centro de diálisis o ve a urgencias INMEDIATAMENTE si:", items: ["Notas que la bolsa de líquido drenado se ve borrosa, turbia, blanquecina o tiene hebras como 'nubes' flotando en ella", "Sientes un dolor abdominal súbito, difuso, fuerte y sensibilidad extrema al presionar tu vientre", "Desarrollas fiebre repentina, escalofríos, temblores o náuseas y vómitos", "El sitio por donde sale el catéter en la piel está muy rojo, supura pus o duele"] } },
'Párpados caídos' : { intro: "Los párpados caídos, conocidos médicamente como ptosis palpebral, consisten en el descenso anormal del párpado superior sobre el ojo. Puede variar desde una caída leve apenas perceptible, hasta cubrir por completo la pupila y bloquear totalmente la visión.", whatIs: { title: "¿Qué es la Ptosis Palpebral?", text: "Es un problema neuromuscular, tendinoso o mecánico. Ocurre cuando el músculo elevador del párpado superior (el encargado de mantener el ojo abierto) se debilita, se estira, se desgarra o pierde su señal nerviosa. Puede ser un simple síntoma de la edad o una alarma de enfermedades neurológicas serias." }, types: { title: "Causas y Orígenes", intro: "Se clasifica dependiendo del mecanismo de la falla:", items: ["Ptosis aponeurótica o senil (la más común, ocurre por el envejecimiento natural; el tendón del músculo elevador se estira y se afloja lentamente)", "Ptosis congénita (presente en bebés desde el nacimiento, si el músculo no se desarrolló bien)", "Ptosis neurogénica o miogénica (causada por daño a los nervios o enfermedades neuromusculares graves como la Miastenia Gravis, el Síndrome de Horner o un ACV)", "Ptosis mecánica (el párpado cae porque pesa mucho, debido a tumores, quistes masivos de grasa o hinchazón severa)"], note: "Frotarse agresivamente los ojos durante años y el uso crónico de lentes de contacto duros aumentan mucho el riesgo de estirar el tendón palpebral." }, diagnosis: { title: "Examen Oftalmológico y Neurológico", intro: "El especialista determinará si es estético o neurológico:", items: ["Examen oftalmológico exhaustivo (medición exacta de los milímetros de caída, función pupilar y fuerza del músculo elevador)", "Prueba de campo visual (para probar médica y legalmente cuánto de tu visión superior está bloqueada por la piel, lo cual aprueba cirugías en seguros médicos)", "Prueba del cubito de hielo o análisis de sangre (si hay sospecha de Miastenia Gravis, el párpado caído suele empeorar al final del día por la fatiga)", "Resonancia Magnética (RM) cerebral (obligatoria si el párpado cayó de golpe, buscando tumores compresivos o aneurismas)"], note: "" }, treatment: { title: "Cirugía Reparadora", intro: "El tratamiento definitivo es físico, reparando el soporte del ojo:", subsections: [ { title: "Opciones de Intervención", items: ["Cirugía de Ptosis o Blefaroplastia funcional (el tratamiento de elección; bajo anestesia local, el cirujano acorta y tensa el tendón del músculo elevador para levantar el párpado a su altura normal)", "Cirugía de suspensión frontal (en casos severos o congénitos sin músculo funcional, el párpado se 'cuelga' del músculo de la frente -ceja- con silicona o tendón)", "Tratamiento de la enfermedad subyacente (uso de pastillas para la miastenia gravis o gotas especiales -oximetazolina- que elevan temporalmente el párpado levemente)", "Muletas para párpados (alambres adosados a las gafas para sujetar el párpado si no es posible operar)"] } ], note: "Si un niño nace con ptosis severa, DEBE operarse rápido; si el párpado tapa la pupila en la infancia, el cerebro desconectará ese ojo, causando ceguera permanente por ambliopía (ojo vago)." }, whenToSeekHelp: { title: "¿Cuándo es una ALARMA NEUROLÓGICA o URGENCIA?", intro: "La caída repentina del párpado puede advertir de un derrame o tumor. Ve a urgencias INMEDIATAMENTE si:", items: ["El párpado de uno o ambos ojos se cae de forma súbita, repentina, en cuestión de minutos, horas o de un día para otro", "La caída del párpado viene acompañada de visión doble abrupta (diplopía)", "Notas debilidad en el brazo o pierna, hormigueo, dificultad para sonreír o tragar (signos de infarto cerebral)", "Acompaña a un dolor de cabeza severo e inusual o la pupila del ojo afectado se ve diferente a la otra (más dilatada o contraída)"] } },
'Lesión renal aguda' : { intro: "La lesión renal aguda (LRA), antes conocida como insuficiencia renal aguda, es un episodio brusco en el cual los riñones de una persona pierden de manera repentina y crítica su capacidad de filtrar los productos tóxicos de la sangre. Puede desarrollarse en pocas horas o en un par de días.", whatIs: { title: "¿Qué es la LRA?", text: "Es un colapso abrupto en el sistema de purificación del organismo. La función de filtrado cae en picado, lo que hace que los desechos (como la creatinina y la urea) se acumulen rápidamente hasta niveles que pueden ser mortales. Además, altera dramáticamente el equilibrio de líquidos y electrolitos vitales como el potasio." }, types: { title: "Las Tres Categorías de Causas", intro: "Se divide médicamente en tres grupos según el origen del fallo:", items: ["LRA Prerrenal (Disminución drástica del flujo de sangre hacia los riñones. Causas: deshidratación severa, sangrado masivo, choque séptico, insuficiencia cardíaca aguda)", "LRA Intrarrenal o Intrínseca (Daño directo a las propias células y filtros de los riñones. Causas: toxicidad por ciertos antibióticos o uso masivo de AINEs, medios de contraste radiológicos, o enfermedades autoinmunes de ataque rápido)", "LRA Posrenal u Obstructiva (Obstrucción física que impide la salida de la orina, lo que causa presión retrógrada y destrucción del riñón. Causas: próstata extremadamente agrandada, cálculos renales bloqueando uréteres o tumores)"], note: "Es una afección muy frecuente y temida en pacientes que se encuentran internados en la unidad de cuidados intensivos (UCI)." }, diagnosis: { title: "Diagnóstico Clínico Urgente", intro: "La velocidad en el diagnóstico es fundamental para evitar la muerte y la necesidad de diálisis permanente:", items: ["Análisis de sangre y química sanguínea (monitorización crítica de los picos de Creatinina sérica, Nitrógeno Ureico -BUN- y el peligrosísimo Potasio)", "Medición exhaustiva de la producción de orina (si la persona orina muy poco, oliguria, o nada, anuria, en un periodo de 24 hrs, es una señal de fallo grave)", "Análisis general de orina (para detectar si hay glóbulos rojos, proteínas o cilindros celulares)", "Ecografía renal (fundamental para identificar si los conductos urinarios están dilatados por una obstrucción urgente)"], note: "" }, treatment: { title: "Soporte y Reversión del Fallo", intro: "A diferencia del fallo crónico, la LRA puede curarse si la causa se aborda con suma rapidez:", subsections: [ { title: "Manejo Hospitalario Inmediato", items: ["Administración vigorosa de líquidos intravenosos (IV) (si el paciente sufrió una deshidratación o pérdida de sangre que 'secó' el riñón)", "Corrección de desequilibrios mortales (uso urgente de medicamentos como insulina, calcio y resinas para bajar el nivel de potasio en la sangre y evitar un paro cardíaco)", "Tratamiento urológico (si hay bloqueo posrenal, inserción rápida de una sonda vesical o cirugía de riñón para liberar el taponamiento)", "Diálisis temporal o Terapia de Reemplazo Renal Continua (TRRC) (la máquina sustituye al riñón limpiando la sangre mientras los riñones inflamados descansan y se curan a lo largo de semanas)"] } ], note: "Cualquier medicamento que dañe el riñón se suspende inmediatamente. La recuperación completa de la función renal es muy posible." }, whenToSeekHelp: { title: "¿Cuándo acudir a URGENCIAS?", intro: "Es una condición de riesgo vital inmediato. Acude a urgencias médicas si experimentas de repente:", items: ["Reducción extrema o interrupción total en tu volumen y capacidad de orinar durante más de un día", "Hinchazón generalizada masiva, aguda y dolorosa, en especial retención de líquidos grave en las piernas, pies o la cara", "Una fuerte e inexplicable sensación de asfixia y de dificultad para respirar de forma súbita (líquido invadiendo los pulmones)", "Fuerte sensación opresiva de presión torácica, fatiga aplastante o gran confusión mental, letargo y hasta convulsiones"] } },
'Meningioma en adultos' : { intro: "Un meningioma es el tipo más común de tumor cerebral primario detectado en adultos. Se origina en las meninges, las tres capas de membrana dura protectora que rodean y cubren directamente el cerebro y la médula espinal justo debajo del cráneo.", whatIs: { title: "¿Qué es un Meningioma?", text: "Técnicamente, no es un tumor del tejido propio del cerebro. Crece en las coberturas externas, pero a medida que se hace grande, presiona y aplasta severamente el tejido cerebral, los nervios craneales y los vasos sanguíneos vitales de su alrededor. Afortunadamente, alrededor del 90% son tumores biológicamente benignos (no cancerosos) y de un crecimiento extremadamente lento." }, types: { title: "Grados Patológicos (OMS)", intro: "La Organización Mundial de la Salud los clasifica según su agresividad celular:", items: ["Grado I: Benignos (los más frecuentes; crecen muy despacio a lo largo de muchos años, sus células son similares a las normales)", "Grado II: Atípicos (tienen una tasa de crecimiento más rápido, un comportamiento biológico intermedio y una probabilidad significativamente mayor de volver a crecer tras la cirugía)", "Grado III: Anaplásicos o malignos (raros pero agresivos, crecen velozmente como el cáncer y se diseminan, invadiendo el propio cerebro o el hueso)"], note: "Son mucho más frecuentes en mujeres mayores, y se sabe que las hormonas (estrógeno/progesterona) y los antecedentes de fuertes radioterapias en la cabeza influyen en su crecimiento." }, diagnosis: { title: "Escáneres Neurológicos de Precisión", intro: "Al crecer tan despacio, muchos no dan síntomas hasta que son grandes. El neurólogo los detecta con:", items: ["Resonancia Magnética (RM) del cerebro con contraste (es la prueba de oro absoluta; muestra la anatomía detallada, el tamaño del tumor, y una característica 'cola dural' iluminada que es clásica de los meningiomas)", "Tomografía Computarizada (TC) (se usa para evaluar si el tumor se ha calcificado, lo cual es común, o si está dañando el hueso del cráneo cercano)", "Biopsia de tejido (por lo general, el neurocirujano no pincha el cerebro antes; se obtiene una muestra en el quirófano durante la cirugía de extirpación para confirmar el Grado)"], note: "" }, treatment: { title: "Vigilancia, Radiación o Extirpación", intro: "El tratamiento depende fuertemente del tamaño, el crecimiento y los síntomas que ocasione:", subsections: [ { title: "Estrategias Neuroquirúrgicas", items: ["Observación o 'Esperar y Ver' (para meningiomas pequeños, descubiertos por casualidad y que no causan ningún síntoma, a menudo se realizan Resonancias anuales, ya que pueden no crecer nunca)", "Craneotomía y extirpación quirúrgica (la meta principal si hay síntomas; el neurocirujano abre el cráneo y busca extirpar la masa tumoral completa; a menudo curativo si es Grado I y se saca todo)", "Radiocirugía estereotáctica o Gamma Knife (para tumores muy profundos inoperables o pequeños restos posquirúrgicos; no es cirugía cortante, sino haces de radiación extremadamente enfocados que matan el tumor con precisión milimétrica)", "Radioterapia fraccionada (para aquellos de Grado II o III agresivos para prevenir recurrencias constantes)"] } ], note: "Después del tratamiento, los pacientes necesitarán escáneres cerebrales regulares de por vida, ya que pueden reaparecer años después." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE la revisión neurológica?", intro: "El cerebro compensa la presión hasta cierto punto. Busca evaluación médica urgente si padeces:", items: ["Convulsiones repentinas o ataques epilépticos de cualquier tipo en la edad adulta (sin un diagnóstico previo)", "Dolores de cabeza nuevos o diferentes que empeoran inexorablemente con los meses, especialmente al despertar por las mañanas", "Pérdida de la visión progresiva, visión doble o que se te oscurezca la vista (signo de que está aplastando el nervio óptico)", "Debilidad en brazos o piernas, cambios inusuales y severos en la personalidad, memoria o alteraciones al hablar"] }, symptoms: { title: "Síntomas de Compresión", intro: "Los síntomas dependen de la parte del cerebro que esté siendo aplastada:", groups: [ { name: "Signos Clínicos Neurológicos", items: ["Dolor de cabeza progresivo y persistente", "Alteraciones visuales y pérdida de olfato (anosmia)", "Problemas de equilibrio, inestabilidad o pérdida de audición", "Debilidad asimétrica o entumecimiento"] } ], warning: "Un ataque epiléptico siempre requiere un escáner cerebral urgente para descartar masas compresivas." } },
'Personalidad psicopática' : { intro: "La personalidad psicopática (evaluada clínicamente dentro del Trastorno de la Personalidad Antisocial o TPA grave) es una profunda alteración neurobiológica y psiquiátrica de la empatía. Se caracteriza por un patrón crónico de desprecio total hacia las normas sociales y los derechos, sentimientos o seguridad de los demás, acompañado de una aguda falta de remordimiento.", whatIs: { title: "¿Qué es la Psicopatía?", text: "Es una condición severa de la personalidad. A diferencia de una persona que comete un error por impulsividad y siente culpa, el individuo con rasgos psicopáticos tiene un cerebro que no procesa el miedo ni la conexión emocional (empatía afectiva) de forma normal. Ven a las demás personas estrictamente como objetos, herramientas o instrumentos para su propia ganancia, diversión o beneficio, manipulándolos sin el menor cargo de conciencia." }, types: { title: "Rasgos y Espectro Antisocial", intro: "A menudo se divide social y criminológicamente, aunque clínicamente están bajo el paraguas del TPA:", items: ["Psicopatía pura (suele tener una base más neurobiológica/genética; el individuo es calculador, frío, encantador superficialmente, planifica meticulosamente y no siente empatía ni vínculos emocionales)", "Sociopatía (suele tener una base más ambiental/traumática en la infancia; el individuo es más impulsivo, errático, propenso a estallidos de ira, pero puede llegar a formar algún vínculo, aunque disfuncional)", "Un porcentaje menor de psicópatas se convierte en delincuentes violentos; muchos son 'psicópatas de cuello blanco' exitosos que explotan empresas, mienten y arruinan psicológica o económicamente a sus familias"] }, diagnosis: { title: "Evaluación Psiquiátrica Forense", intro: "El diagnóstico es complejo y a menudo se realiza en contextos legales, ya que rara vez acuden por voluntad propia:", items: ["Evaluación clínica psiquiátrica estricta (basada en el historial de vida; para el diagnóstico de Trastorno Antisocial en el DSM-5, el individuo debe tener más de 18 años y haber mostrado un trastorno de conducta grave -como crueldad animal o robos- antes de los 15 años)", "Escala de Calificación de Psicopatía Revisada de Hare (PCL-R) (el estándar de oro forense; una herramienta detallada que evalúa 20 rasgos como egocentrismo, falta de remordimiento, encanto superficial, mentira patológica y estilo de vida parasitario)"], note: "El individuo suele ser experto en mentir y engañar en la evaluación clínica." }, treatment: { title: "Manejo Institucional y Comorbilidades", intro: "La psicopatía pura se considera una de las condiciones mentales más resistentes y difíciles de tratar; no existe pastilla ni cura para la falta de empatía:", subsections: [ { title: "Abordajes Terapéuticos", items: ["Terapia Psicológica tradicional (la terapia empática y de introspección tradicional suele fracasar rotundamente, y en muchos casos es perjudicial, ya que el psicópata solo aprende nuevas formas de entender y manipular las emociones del terapeuta y de los demás)", "Terapia Cognitivo-Conductual o Programas Estructurados (enfocados puramente en el autointerés: se les enseña que los comportamientos agresivos o ilegales tienen consecuencias negativas ineludibles para ellos mismos, modificando su comportamiento por conveniencia, no por moral)", "Tratamiento psiquiátrico farmacológico de comorbilidades (se pueden usar estabilizadores del ánimo o antipsicóticos únicamente para reducir la irritabilidad grave, agresividad impulsiva explosiva o si existe un abuso de sustancias concomitante)", "Manejo y restricción ambiental (en casos de psicopatía severa violenta, el sistema de justicia penal y los entornos estructurados de máxima seguridad suelen ser el único manejo para proteger a la sociedad)"] } ], note: "El enfoque psicológico más crítico de este trastorno se dirige a tratar a las VÍCTIMAS: las familias o parejas, enseñándoles tácticas para establecer límites inquebrantables, proteger sus bienes y desvincularse (Contacto Cero)." }, whenToSeekHelp: { title: "¿Cuándo es imperativo buscar ayuda y protección?", intro: "Para las personas que interactúan, conviven o son pareja de alguien con estos rasgos, la intervención es vital para su propia seguridad. Busca ayuda profesional, legal o policial si:", items: ["Eres víctima constante de violencia física, emocional grave, o de control coercitivo y aislamiento", "Experimentas un 'gaslighting' tan extremo (la persona miente con una frialdad y seguridad absolutas sobre hechos reales, culpándote a ti de todo) que has comenzado a dudar de tu propia cordura y memoria", "Descubres un patrón continuado, sin rastro de remordimiento, de robos económicos grandes, fraudes o engaños destructivos hacia ti o hacia la familia"] } },
'Neuralgia glosofaríngea' : { intro: "La neuralgia glosofaríngea es un síndrome de dolor facial y de cuello extremadamente raro y agonizante. Afecta al noveno par craneal (el nervio glosofaríngeo), provocando ataques súbitos e impredecibles de dolor agudo parecido a una descarga eléctrica en la parte posterior de la garganta, lengua y oído.", whatIs: { title: "¿Qué es la Neuralgia Glosofaríngea?", text: "Es una condición neuropática severa. El nervio encargado de transmitir la sensibilidad de la garganta y la lengua se irrita o daña gravemente. En consecuencia, estímulos normales y cotidianos (como tragar) disparan un 'cortocircuito' de dolor fulgurante. Se asemeja en severidad a la neuralgia del trigémino, pero localizada profundamente en la garganta y el área de las amígdalas." }, types: { title: "Causas de la Irritación Nerviosa", intro: "Se divide por el origen de la compresión del nervio:", items: ["Idiopática o por Compresión Vascular (la más frecuente: un vaso sanguíneo sano -arteria o vena- en la base del cerebro pulsa y late contra la raíz del nervio, desgastando su capa protectora e irritándolo crónicamente)", "Secundaria a patologías (causada por el crecimiento de tumores o cánceres en la garganta o cuello que aplastan el nervio, o por daños secundarios a la esclerosis múltiple)"], note: "Suele afectar a adultos mayores de 50 años." }, diagnosis: { title: "Evaluación Neurológica Exquisita", intro: "El neurólogo o el especialista en dolor deben aislar la zona del ataque:", items: ["Prueba de provocación y anestesia tópica (el médico toca la parte posterior de la amígdala con un hisopo para intentar desencadenar el ataque. Luego, aplica un spray anestésico fuerte; si el dolor mejora inmediatamente al volver a tocar, el diagnóstico casi se confirma)", "Examen neurológico exhaustivo", "Resonancia Magnética (RM) del cerebro de alta resolución y Angio-RM (el examen vital para ver milimétricamente si una arteria está enrollada en el nervio o si existe un tumor oculto)"], note: "" }, treatment: { title: "Medicación Neuropática y Descompresión", intro: "Los analgésicos normales (ibuprofeno, morfina) NO funcionan para el dolor de nervios; el tratamiento debe estabilizar la electricidad:", subsections: [ { title: "Terapias Farmacológicas y Quirúrgicas", items: ["Medicamentos Anticonvulsivos (como la Carbamazepina, Oxcarbazepina o Gabapentina, son la primera línea de defensa de oro; estos fármacos 'calman' los disparos eléctricos hiperactivos del nervio dañado)", "Antidepresivos tricíclicos (usados en dosis bajas para modular el dolor nervioso crónico)", "Bloqueos nerviosos (inyecciones locales de anestésico potente en la parte posterior de la garganta o el cuello para cortar temporalmente la señal del dolor)", "Cirugía de Descompresión Microvascular (el tratamiento curativo neuroquirúrgico más definitivo si los fármacos fallan: un neurocirujano abre el cráneo y coloca una pequeña almohadilla de teflón entre el vaso sanguíneo que palpita y el nervio, separándolos para siempre)", "Rizotomía (cirugía destructiva para cortar intencionadamente la raíz del nervio y apagar el dolor)"] } ], note: "Es crítico tomar los anticonvulsivos diariamente según lo recetado, no solo cuando hay dolor, para mantener al nervio suprimido." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ir al médico o a emergencias?", intro: "Debes buscar valoración de neurología si presentas crisis de dolor que te impiden comer y, acudir a urgencias vitales si:", items: ["Experimentas latigazos severos, punzadas brutales o dolor ardiente y eléctrico en lo profundo de la garganta, amígdalas o en el interior del oído al hacer actividades como tragar alimentos o líquidos, hablar, toser, reír o masticar", "Sufres de Síncope asociado: si durante el repentino ataque de dolor intenso de garganta sientes mareos extremos, tu presión arterial se desploma súbitamente, o llegas a perder el conocimiento o desmayarte (una complicación peligrosa porque el nervio también regula el ritmo del corazón)"] } },
'Alergias a las mascotas' : { intro: "Las alergias a las mascotas son reacciones inmunológicas exageradas a las proteínas que se encuentran en las células de la piel (caspa), la saliva o la orina de un animal. Es un problema muy común, especialmente con gatos y perros.", whatIs: { title: "¿Qué es una Alergia a Mascotas?", text: "Tu sistema inmunológico identifica por error una proteína inofensiva del animal como si fuera un invasor peligroso (como un virus o bacteria). En respuesta, produce anticuerpos IgE que desencadenan la liberación de histamina, causando inflamación instantánea en las vías respiratorias, ojos o piel." }, types: { title: "Manifestaciones Clínicas", intro: "Los síntomas pueden presentarse de varias formas:", items: ["Rinitis alérgica (estornudos, congestión, picor nasal y goteo constante)", "Conjuntivitis alérgica (ojos rojos, llorosos, con picazón intensa e hinchados)", "Asma alérgica (dificultad para respirar, opresión en el pecho, tos y sibilancias)", "Dermatitis de contacto (urticaria, ronchas rojas o eccema en las zonas donde el animal te lamió o tocó)"], note: "El pelo del animal no es el alérgeno principal, pero actúa como una trampa que acumula caspa, polvo y polen." }, diagnosis: { title: "Evaluación Alergológica", intro: "El especialista confirmará la alergia mediante:", items: ["Prueba cutánea de alergia (Prick test: se aplica un extracto de la proteína animal en la piel y se pincha ligeramente para observar si hay reacción)", "Análisis de sangre para IgE específica (si las pruebas cutáneas no son posibles)", "Historial clínico correlacionando los síntomas con la exposición al animal"], note: "" }, treatment: { title: "Manejo y Control", intro: "El objetivo es reducir la exposición y bloquear los síntomas:", subsections: [ { title: "Opciones Terapéuticas", items: ["Medidas ambientales (crear zonas libres de mascotas, purificadores de aire HEPA, lavar al animal frecuentemente)", "Antihistamínicos orales o en gotas oculares (para bloquear el picor y estornudos)", "Corticosteroides nasales (la medicación más eficaz para la congestión crónica)", "Inmunoterapia (vacunas contra la alergia: inyecciones regulares de dosis minúsculas del alérgeno para 'desensibilizar' al sistema inmune permanentemente)"] } ], note: "No existen perros o gatos verdaderamente 100% 'hipoalergénicos', ya que todos producen saliva y caspa." }, whenToSeekHelp: { title: "¿Cuándo es urgente ir al médico?", intro: "Busca atención médica de inmediato si la alergia desencadena un ataque de asma grave:", items: ["Tienes una dificultad extrema para respirar o sientes que te asfixias", "Sientes dolor, opresión fuerte en el pecho o escuchas silbidos fuertes al tomar aire", "Tus síntomas de congestión interrumpen completamente tu sueño y afectan tu vida diaria a pesar de los medicamentos"] } },
'Comunicación interventricular' : { intro: "La comunicación interventricular (CIV) es el defecto cardíaco congénito (de nacimiento) más común. Se caracteriza por la presencia de un orificio anómalo en el tabique o pared que separa las dos cavidades inferiores del corazón (los ventrículos derecho e izquierdo).", whatIs: { title: "¿Qué es la Comunicación Interventricular?", text: "En un corazón sano, la sangre rica en oxígeno del ventrículo izquierdo se bombea al cuerpo. Con una CIV, la alta presión del lado izquierdo empuja la sangre oxigenada a través del orificio hacia el ventrículo derecho. Esto hace que el corazón y los pulmones trabajen el doble, sobrecargándolos de volumen sanguíneo." }, types: { title: "Clasificación Anatómica", intro: "Se dividen según el lugar del tabique donde se encuentra el orificio:", items: ["CIV Membranosa (el tipo más frecuente, ubicada cerca de las válvulas cardíacas)", "CIV Muscular (ubicada en la parte inferior y muscular del tabique; muchos de estos orificios se cierran solos durante la infancia)", "CIV del tracto de entrada o salida (ubicadas justo donde la sangre entra o sale de los ventrículos)"], note: "El tamaño del orificio (pequeño, mediano o grande) es el factor más crítico para determinar los síntomas y el tratamiento." }, diagnosis: { title: "Detección Cardiológica", intro: "A menudo se diagnostica en los primeros días de vida por un sonido inusual:", items: ["Auscultación pediátrica (el médico escucha un 'soplo cardíaco' fuerte y característico con el estetoscopio)", "Ecocardiograma (la prueba de oro; un ultrasonido del corazón que muestra exactamente el tamaño del agujero y cuánta sangre pasa a través de él)", "Electrocardiograma (ECG) y Radiografía de tórax (para ver si el corazón está agrandado o los pulmones tienen exceso de líquido)"], note: "" }, treatment: { title: "Observación y Corrección Quirúrgica", intro: "El tratamiento depende estrictamente del tamaño del defecto y los síntomas del bebé:", subsections: [ { title: "Intervenciones", items: ["Conducta expectante (los orificios pequeños no se operan; simplemente se vigilan con ecocardiogramas porque a menudo se cierran solos a medida que el niño crece)", "Medicamentos (diuréticos y fármacos para la presión arterial para ayudar al corazón a bombear y evitar la acumulación de líquido en los pulmones de bebés con CIV grandes)", "Reparación quirúrgica a corazón abierto (el cirujano coloca un parche sobre el orificio; es la técnica definitiva para orificios grandes que causan síntomas)", "Cierre por cateterismo (en casos seleccionados, se inserta un tapón de malla a través de un tubo desde la ingle hasta el corazón sin abrir el pecho)"] } ], note: "Sin cirugía, una CIV grande no tratada causará insuficiencia cardíaca infantil grave e hipertensión pulmonar irreversible (Síndrome de Eisenmenger)." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias pediátricas?", intro: "Si tu bebé ha sido diagnosticado o presenta síntomas, busca ayuda inmediata si:", items: ["Se cansa excesivamente y suda frío o copiosamente mientras intenta alimentarse, lo que le impide ganar peso", "Su respiración es anormalmente rápida, pesada, o se le hunden las costillas al respirar (tiraje)", "Muestra una coloración azulada o grisácea en los labios, las encías o alrededor de la boca (cianosis)"] } },
'Úlcera gástrica' : { intro: "Una úlcera gástrica es una llaga abierta, profunda y dolorosa que se forma en el revestimiento interno protector (la mucosa) del estómago. Es un tipo de úlcera péptica que puede causar un dolor ardiente muy intenso, especialmente después de comer.", whatIs: { title: "¿Qué es una Úlcera Gástrica?", text: "El estómago produce ácidos muy potentes para digerir la comida. Normalmente, una gruesa capa de moco protege al estómago de quemarse a sí mismo. Cuando esta barrera mucosa se debilita o se daña, el ácido corroe el tejido subyacente, creando un 'cráter' o úlcera sangrante." }, types: { title: "Causas Principales", intro: "El estrés o la comida picante no causan úlceras; las verdaderas causas son:", items: ["Infección por Helicobacter pylori (una bacteria muy común que infecta el estómago, inflama la mucosa y rompe las defensas, causando la mayoría de las úlceras)", "Uso crónico de AINEs (analgésicos como el ibuprofeno, naproxeno o aspirina; estos bloquean las enzimas que producen la capa de moco protector, dejando al estómago indefenso)"], note: "Fumar tabaco y beber alcohol en exceso no causan la úlcera directamente, pero empeoran masivamente el daño y evitan que sane." }, diagnosis: { title: "Endoscopia y Pruebas", intro: "Para ver la úlcera y confirmar si es benigna o maligna:", items: ["Endoscopia digestiva alta (el examen más preciso: el gastroenterólogo introduce un tubo con cámara por la boca para ver la úlcera en vivo y tomar biopsias para descartar cáncer de estómago)", "Pruebas de H. pylori (análisis de aliento con urea, de antígenos en heces o durante la propia endoscopia)", "Tránsito esofagogastroduodenal (radiografías bebiendo líquido de bario blanco)"], note: "" }, treatment: { title: "Supresión Ácida y Erradicación Bacteriana", intro: "Las úlceras son curables si se elimina el agente agresor:", subsections: [ { title: "Opciones Médicas", items: ["Inhibidores de la Bomba de Protones (IBP) (medicamentos como Omeprazol o Pantoprazol que apagan casi por completo la producción de ácido estomacal, dando tiempo a la llaga para cicatrizar)", "Terapia de erradicación (si hay H. pylori, se recetan 2 o 3 antibióticos simultáneos durante 14 días para matar la bacteria definitivamente)", "Suspensión de AINEs (el médico cambiará el analgésico a Paracetamol)", "Cirugía de urgencia (solo si la úlcera es tan profunda que perfora el estómago o causa una hemorragia masiva)"] } ], note: "Tomar leche no cura las úlceras; aunque alivia un poco momentáneamente, luego estimula una mayor producción de ácido que empeora el dolor." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA DE VIDA O MUERTE?", intro: "Una úlcera que sangra o perfora el estómago es letal. Ve a urgencias de inmediato si presentas:", items: ["Vómitos repetitivos de sangre roja brillante, o vómitos oscuros que parecen 'posos de café' molido", "Heces extremadamente negras, pegajosas y con un olor fétido intenso (melena, que es sangre digerida)", "Dolor abdominal repentino, agudísimo, que se siente como una puñalada y vuelve tu abdomen rígido y duro como una tabla (posible perforación)", "Mareos extremos, palidez, debilidad al ponerte de pie o desmayos por la pérdida de sangre interna"] } },
'Queratosis: tumores benignos de la piel' : { intro: "La queratosis seborreica es el tipo más común de tumor cutáneo benigno (no canceroso) en adultos mayores. Son crecimientos superficiales de la piel que a menudo tienen un aspecto escamoso, verrugoso o como si hubieran sido 'pegados' sobre la piel.", whatIs: { title: "¿Qué son las Queratosis Seborreicas?", text: "Son acumulaciones inofensivas de células inmaduras de la piel (queratinocitos). Aunque su apariencia oscura e irregular a veces asusta a los pacientes por su similitud con el melanoma, son completamente benignas, no son contagiosas y jamás se convierten en cáncer de piel." }, types: { title: "Apariencia Visual", intro: "Sus características clínicas son muy particulares:", items: ["Color (varían desde el color carne claro hasta el marrón oscuro o casi negro)", "Textura (tienen una superficie cerosa, áspera o con pequeñas escamas, a veces similar a una costra gruesa)", "Forma (suelen ser redondas u ovaladas, y parecen estar superficialmente 'adheridas' o pegadas a la piel como arcilla)"], note: "Tienen una fuerte predisposición genética y aumentan en número con la edad; es normal tener decenas de ellas en el pecho y la espalda." }, diagnosis: { title: "Detección Dermatológica", intro: "Un dermatólogo rara vez se equivoca al verlas:", items: ["Examen visual con dermatoscopio (el médico usa una lupa iluminada que muestra estructuras clásicas de la queratosis y descarta instantáneamente el cáncer de piel)", "Biopsia de piel (solo se realiza si la lesión es inusualmente oscura, de bordes extraños o sangra fácilmente, para asegurar que no oculta un melanoma)"], note: "" }, treatment: { title: "Observación y Remoción Estética", intro: "No requieren ningún tratamiento médico porque son inofensivas. Si se desean quitar por estética o roce, se puede hacer:", subsections: [ { title: "Procedimientos en Consultorio", items: ["Crioterapia (congelar la queratosis con nitrógeno líquido; la lesión se seca y se cae en un par de semanas)", "Electrocirugía y legrado (adormecer la zona, raspar el bulto con una cureta y sellar la piel con calor)", "Láser ablativo (evapora la lesión limpiamente)"] } ], note: "NUNCA intentes rascar, arrancar o usar remedios caseros para quemar estas lesiones, ya que dejarás cicatrices permanentes y riesgo de infección severa." }, whenToSeekHelp: { title: "¿Cuándo pedir evaluación dermatológica?", intro: "Debes acudir a un médico de la piel para asegurar el diagnóstico si:", items: ["Aparece un crecimiento muy rápido de numerosas lesiones oscuras en poco tiempo (Signo de Leser-Trélat, que raramente indica un problema interno)", "La lesión sangra con facilidad al roce de la ropa, duele, pica intensamente o se inflama", "No estás absolutamente seguro de si la mancha nueva es una queratosis inofensiva o un lunar canceroso sospechoso"] } },
'Espondilitis' : { intro: "La espondilitis es un término que describe la inflamación de las vértebras de la columna. El tipo más grave y común es la Espondilitis Anquilosante, una enfermedad autoinmune crónica que causa dolor de espalda bajo intenso y puede llegar a fusionar los huesos de la columna.", whatIs: { title: "¿Qué es la Espondilitis Anquilosante?", text: "Es una artritis inflamatoria sistémica. El sistema inmunológico ataca las articulaciones sacroilíacas (donde la columna se une a la pelvis) y los ligamentos de la columna. Como respuesta al daño crónico, el cuerpo forma hueso nuevo, soldando las vértebras entre sí (anquilosis), creando una columna rígida como el bambú." }, types: { title: "Características y Tipos de Inflamación", intro: "Afecta principalmente el eje axial del cuerpo, pero no solo ahí:", items: ["Espondilitis anquilosante clásica (afecta columna y pelvis, diagnosticable por radiografías)", "Espondiloartritis axial no radiográfica (existen los síntomas típicos y dolor, pero el daño de los huesos aún no es visible en las radiografías)", "Afectación periférica (inflamación severa en tendones -entesitis- como el talón de Aquiles, o en grandes articulaciones como caderas)", "Uveítis (inflamación ocular autoinmune, una complicación extraarticular muy frecuente)"], note: "Suele comenzar en hombres jóvenes, entre los 15 y 30 años de edad, mucho antes de lo que comúnmente se espera para un 'dolor de espalda'." }, diagnosis: { title: "Diagnóstico Reumatológico", intro: "El diagnóstico temprano es vital para evitar la deformidad:", items: ["Historial de 'dolor de espalda inflamatorio' (empeora en reposo/noche y mejora con el ejercicio)", "Resonancia Magnética (RM) de las articulaciones sacroilíacas (la prueba más sensible para ver inflamación activa temprana)", "Análisis de sangre para el antígeno HLA-B27 (un gen fuertemente asociado a la enfermedad, aunque no definitivo)", "Radiografías (muestran daño tardío o fusión)"], note: "" }, treatment: { title: "Terapias Biológicas y Movimiento", intro: "El tratamiento detiene la progresión y mantiene la movilidad:", subsections: [ { title: "Intervenciones", items: ["AINEs (antiinflamatorios no esteroideos a dosis altas, el primer tratamiento efectivo)", "Terapias Biológicas (inhibidores del TNF o IL-17; inyecciones que apagan el sistema inmunológico específico, frenando drásticamente el daño óseo)", "Fisioterapia diaria estricta (ejercicios de postura y estiramientos son médicamente obligatorios para evitar que la columna se fusione encorvada)"] } ], note: "Fumar tabaco es letal para esta enfermedad, ya que acelera masivamente la fusión y rigidez de la columna." }, whenToSeekHelp: { title: "¿Cuándo consultar al reumatólogo?", intro: "Debes sospechar de dolor inflamatorio y buscar ayuda si:", items: ["Tienes dolor en la espalda baja o glúteos que comenzó antes de los 40 años y dura más de 3 meses", "El dolor de espalda te despierta en la segunda mitad de la noche, forzándote a levantarte y caminar", "Notas que tu dolor MEJORA con la actividad física, pero EMPEORA si te quedas sentado o en reposo", "Sufres de un ojo repentinamente rojo, muy doloroso y extremadamente sensible a la luz (uveítis)"] } },
'Calvicie de patrón masculino' : { intro: "La calvicie de patrón masculino, o alopecia androgénica, es la causa más común de pérdida de cabello en los hombres. Se caracteriza por un patrón muy predecible de retroceso de la línea de nacimiento del cabello y debilitamiento en la coronilla de la cabeza.", whatIs: { title: "¿Qué es la Alopecia Androgénica?", text: "Es una condición genética y hormonal. En los hombres predispuestos genéticamente, los folículos pilosos del cuero cabelludo son extremadamente sensibles a la dihidrotestosterona (DHT), un derivado de la testosterona. La DHT hace que los folículos se encojan progresivamente, produciendo cabello cada vez más fino hasta que finalmente mueren y dejan de producir pelo por completo." }, types: { title: "Patrón de Pérdida (Escala de Norwood)", intro: "La pérdida de pelo no es aleatoria, sigue etapas claras:", items: ["Retroceso de la línea del cabello frontal (las famosas 'entradas' en las sienes)", "Adelgazamiento en el vértice o coronilla (la parte superior trasera de la cabeza)", "Fusión de ambas zonas (dejando finalmente solo un anillo de cabello en forma de herradura alrededor de los lados y la parte posterior de la cabeza)"], note: "El cabello de los lados y la nuca es genéticamente resistente a la DHT, por eso no se cae." }, diagnosis: { title: "Examen Clínico Dermatológico", intro: "Es un diagnóstico visual clásico que no suele requerir pruebas:", items: ["Examen físico del patrón típico de caída y miniaturización del cabello", "Tricoscopia (uso de una lente de aumento en el consultorio para ver los folículos miniaturizados)", "Análisis de sangre (solo si la caída es atípica, irregular, o para descartar deficiencias de hierro o problemas de tiroides)"], note: "" }, treatment: { title: "Bloqueo Hormonal y Restauración", intro: "Los folículos muertos no pueden revivir, por lo que el tratamiento busca salvar los vivos:", subsections: [ { title: "Opciones de Tratamiento", items: ["Finasterida o Dutasterida oral (el tratamiento médico más efectivo; pastillas recetadas que bloquean la enzima que convierte la testosterona en DHT, deteniendo la caída e incluso engrosando el pelo débil)", "Minoxidil tópico u oral (loción, espuma o pastilla que aumenta el flujo sanguíneo al folículo, estimulando el crecimiento y alargando la fase de crecimiento del pelo)", "Trasplante capilar o injerto (cirugía donde se extraen folículos resistentes a la DHT de la nuca y se implantan quirúrgicamente en las zonas calvas; es la única solución definitiva para el área ya muerta)"] } ], note: "Cualquier tratamiento médico para la calvicie (Minoxidil/Finasterida) es de uso continuo de por vida; si se suspenden, la calvicie avanzará rápidamente a su estado natural." }, whenToSeekHelp: { title: "¿Cuándo consultar a un tricólogo o dermatólogo?", intro: "Es ideal iniciar tratamiento en los primeros signos de adelgazamiento. Acude de inmediato si:", items: ["La pérdida de cabello es atípica, repentina, a mechones o deja zonas calvas en forma de moneda (alopecia areata)", "El cuero cabelludo presenta enrojecimiento extremo, picazón severa, dolor o descamación (infecciones o liquen plano)", "La caída del cabello te genera ansiedad severa, depresión o un impacto grave en tu autoestima"] } },
'Gestión de emociones' : { intro: "Las dificultades en la gestión de emociones, o desregulación emocional, se refieren a la incapacidad persistente para manejar, tolerar y responder adecuadamente a las experiencias emocionales de la vida, provocando reacciones desproporcionadas y sufrimiento mental.", whatIs: { title: "¿Qué es la Desregulación Emocional?", text: "Normalmente, el cerebro puede experimentar una emoción intensa y luego volver a un estado de calma (homeostasis). Cuando la gestión falla, las emociones como la ira, la tristeza o el miedo son abrumadoramente intensas, duran demasiado tiempo y escapan al control de la persona, afectando su comportamiento y relaciones interpersonales." }, types: { title: "Manifestaciones Clínicas", intro: "Se presenta a través de comportamientos inadaptativos:", items: ["Reacciones explosivas (ataques de ira, gritos incontrolables o rabietas en adultos ante frustraciones menores)", "Supresión emocional (evitar sentir por completo, entumecimiento afectivo o desconexión -disociación-)", "Comportamientos impulsivos (comer en exceso, consumo de drogas, autolesiones o gastos imprudentes como forma rápida de calmar la ansiedad)", "Sensibilidad al rechazo extrema (percibir ataques donde no los hay)"], note: "Suele ser un síntoma central de trastornos como el Trastorno Límite de la Personalidad (TLP), TDAH, TEPT complejo o Depresión." }, diagnosis: { title: "Evaluación Psicológica", intro: "Un terapeuta o psiquiatra evaluará el impacto en la vida diaria:", items: ["Entrevista clínica exhaustiva sobre patrones de reacción, historia de trauma infantil y dinámica familiar", "Cuestionarios de regulación emocional y de personalidad", "Evaluación de comorbilidades (descartar trastornos del estado de ánimo u orgánicos)"], note: "" }, treatment: { title: "Entrenamiento Terapéutico", intro: "La regulación emocional es una habilidad que se puede enseñar y entrenar en el cerebro:", subsections: [ { title: "Terapias Efectivas", items: ["Terapia Dialéctica Conductual (DBT) (es el tratamiento de oro absoluto; enseña módulos estrictos de tolerancia a la angustia, mindfulness y regulación emocional)", "Terapia Cognitivo-Conductual (TCC) (para reestructurar los pensamientos catastróficos que alimentan la emoción extrema)", "Prácticas de conexión cuerpo-mente (técnicas de respiración diafragmática, meditación y biofeedback para calmar el sistema nervioso simpático)", "Medicación psiquiátrica (estabilizadores del ánimo o antidepresivos para reducir la reactividad basal del cerebro y facilitar la terapia)"] } ], note: "Crear el hábito de hacer una 'pausa' de segundos entre sentir el estímulo y emitir la reacción es la meta principal." }, whenToSeekHelp: { title: "¿Cuándo pedir ayuda profesional urgente?", intro: "Debes buscar apoyo de salud mental si tu intensidad emocional te lleva a:", items: ["Realizar actos de autolesión (cortes, golpes) o tener pensamientos suicidas como la única vía de escape al dolor emocional", "Cometer actos de agresión física o violencia hacia otras personas o destrucción de propiedad en momentos de ira", "Perder repetidamente trabajos, parejas y amigos debido a tu comportamiento impredecible o controlador", "Recurrir al abuso de alcohol, pastillas o drogas ilícitas diariamente para poder 'apagar' tu mente y tolerar el día"] } },
'Infección complicada de las vías urinarias' : { intro: "Una infección complicada de las vías urinarias (IVU complicada) es una infección bacteriana del sistema urinario que se produce en pacientes con factores de riesgo anatómicos, médicos o inmunológicos, lo que la hace mucho más difícil de curar y con mayor riesgo de daño renal.", whatIs: { title: "¿Qué es una IVU Complicada?", text: "A diferencia de una simple cistitis en una mujer joven sana, una IVU se considera 'complicada' cuando hay condiciones subyacentes que facilitan la infección, impiden que la orina fluya normalmente o debilitan las defensas del paciente. Requieren tratamientos antibióticos prolongados y, a menudo, ingreso hospitalario para evitar una sepsis (infección en la sangre)." }, types: { title: "Factores de Complicación", intro: "Se clasifica como complicada si ocurre en presencia de:", items: ["Anomalías anatómicas (obstrucciones por piedras en los riñones, próstata agrandada o estenosis uretral)", "Cuerpos extraños (pacientes que usan sondas urinarias permanentes, catéteres o tienen stents ureterales)", "Pacientes de alto riesgo (hombres, mujeres embarazadas, niños pequeños, ancianos frágiles)", "Inmunodepresión (pacientes con diabetes severa, trasplantados renales o en quimioterapia)", "Bacterias multirresistentes (infecciones contraídas dentro del hospital o resistentes a múltiples fármacos)"], note: "" }, diagnosis: { title: "Evaluación Clínica y Bacteriológica", intro: "El diagnóstico debe ser agresivo para evitar el daño renal:", items: ["Urocultivo obligatorio (análisis de orina de laboratorio esencial para identificar la bacteria exacta y su perfil de resistencia a los antibióticos)", "Análisis de sangre (hemograma, creatinina y proteína C reactiva para ver si hay afectación renal o inicio de sepsis)", "Ecografía renal o Tomografía Computarizada (TC) (indispensables para descartar obstrucciones purulentas, cálculos renales o abscesos en el riñón)"], note: "" }, treatment: { title: "Terapia Antibiótica Avanzada", intro: "Los antibióticos de tres días no funcionan aquí; el tratamiento debe ser robusto:", subsections: [ { title: "Abordajes Médicos", items: ["Antibióticos intravenosos (IV) en el hospital (a menudo necesarios inicialmente para controlar la fiebre y la infección sistémica, usando fármacos potentes como cefalosporinas de 3ra generación o carbapenémicos)", "Cursos prolongados de antibióticos orales (tras el alta, el tratamiento suele durar de 7 a 14 días o más, guiados por el resultado del cultivo)", "Resolución de la causa anatómica (retirar o cambiar sondas infectadas, desobstruir el riñón mediante cirugía láser para piedras o tratar la próstata hiperplásica)"] } ], note: "Completar hasta la última pastilla de la caja de antibióticos es crítico para evitar crear superbacterias letales." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia médica?", intro: "Cualquier IVU en un hombre o embarazada debe revisarse. Acude a urgencias rápidamente si los síntomas urinarios van acompañados de:", items: ["Fiebre muy alta, escalofríos severos o tiritonas violentas", "Un dolor sordo, constante e insoportable en la zona lumbar baja (espalda) o en los flancos (signo de que el riñón está gravemente infectado - pielonefritis)", "Náuseas agudas, incapacidad para dejar de vomitar y deshidratación", "Orina de color rojo oscuro (sangre franca) u orina con un olor extremadamente fétido a putrefacción", "Confusión mental profunda repentina, letargo o mareos severos (especialmente en pacientes ancianos, signo de sepsis inminente)"] } },
'Deficiencia articulatoria' : { intro: "Una deficiencia articulatoria, también conocida en la logopedia como trastorno de la articulación o dislalia, es un problema motor o físico del habla en el que una persona tiene dificultades crónicas para producir y formar correctamente ciertos sonidos (fonemas).", whatIs: { title: "¿Qué es un Trastorno de Articulación?", text: "A diferencia de un problema del lenguaje (saber qué palabras usar), la deficiencia articulatoria es un problema de ejecución física. El niño o adulto sabe qué quiere decir, pero los órganos fonoarticulatorios (la lengua, los labios, el paladar, los dientes o la mandíbula) no se posicionan o mueven de la manera correcta para emitir el sonido preciso." }, types: { title: "Errores Comunes en la Articulación", intro: "Los problemas se manifiestan típicamente en cuatro formas (SODA):", items: ["Sustitución (cambiar un sonido por otro, ej. decir 'tasa' en lugar de 'casa', o 'perro' por 'pedo')", "Omisión (dejar fuera un sonido en la palabra, ej. decir 'pato' como 'pao')", "Distorsión (el sonido se produce, pero suena extraño o 'arrastrado', como el ceceo - lisp - al pronunciar la 'S' interdental)", "Adición (añadir sonidos extra a una palabra)"], note: "Es completamente normal que los niños pequeños cometan estos errores mientras aprenden a hablar, pero deben superarse a ciertas edades." }, diagnosis: { title: "Evaluación Logopédica y Anatómica", intro: "Un logopeda o fonoaudiólogo determinará la causa y severidad:", items: ["Examen de los órganos fonoarticulatorios (revisar si hay un frenillo lingual corto -anquiloglosia-, paladar hendido o problemas graves de maloclusión dental)", "Prueba estandarizada de articulación (pedir al paciente que nombre imágenes o repita palabras para mapear qué fonemas específicos fallan)", "Evaluación auditiva (audiometría obligatoria, ya que si un niño tiene pérdida auditiva leve por otitis crónicas, no escuchará bien los sonidos y, por ende, los articulará mal)"], note: "" }, treatment: { title: "Terapia de Reeducación del Habla", intro: "Es un problema altamente corregible con terapia enfocada:", subsections: [ { title: "Intervenciones Clínicas", items: ["Terapia del habla y lenguaje (el logopeda enseña a la persona exactamente dónde y cómo colocar la lengua y los labios para formar el sonido correcto, repitiéndolo en sílabas, palabras y frases)", "Ejercicios de praxias bucofaciales (gimnasia muscular para fortalecer los labios y dar agilidad a la lengua)", "Intervención quirúrgica menor u odontológica (si la causa es anatómica, como cortar un frenillo corto limitante o usar ortodoncia para alinear los dientes)"] } ], note: "La práctica diaria en casa de los ejercicios dados por el logopeda es el factor más determinante para el éxito del tratamiento." }, whenToSeekHelp: { title: "¿Cuándo consultar a un logopeda?", intro: "Es fundamental buscar una evaluación profesional temprana si:", items: ["El habla del niño resulta muy ininteligible (difícil de entender) para personas ajenas a la familia inmediata después de los 3 o 4 años de edad", "El niño muestra frustración extrema, se enoja o se niega a hablar porque los demás no lo comprenden", "Errores articulatorios específicos (como no poder pronunciar la R vibrante o cecear la S) persisten más allá de los 6 a 7 años", "La dificultad del habla le está causando burlas escolares o afectando su capacidad para aprender a leer y escribir (conciencia fonológica)"] } },
'Trastorno fonológico' : { intro: "El trastorno fonológico es un trastorno de los sonidos del habla, comúnmente diagnosticado en la infancia. A diferencia del trastorno articulatorio (que es un problema físico para mover la boca), el trastorno fonológico es de origen cognitivo y lingüístico; el cerebro del niño no comprende las reglas ni los patrones de los sonidos del lenguaje.", whatIs: { title: "¿Qué es un Trastorno Fonológico?", text: "El niño tiene la capacidad física de pronunciar un sonido, pero su cerebro simplifica las reglas del idioma. Por ejemplo, el niño puede ser perfectamente capaz de pronunciar la letra 'C' sola, pero en su mente ha creado la regla de que todas las palabras que empiezan por 'C' deben pronunciarse con 'T'. Así, 'casa' se vuelve 'tasa'. Agrupan estos errores en patrones constantes." }, types: { title: "Patrones de Simplificación Comunes", intro: "Los niños utilizan procesos fonológicos normales al empezar a hablar, pero en este trastorno, persisten demasiado tiempo:", items: ["Frontalización (usar sonidos producidos en la parte frontal de la boca en lugar de los de atrás; ej. decir 'toma' por 'coma')", "Reducción de grupos consonánticos (quitar una consonante de un grupo; ej. decir 'pato' en vez de 'plato')", "Omisión de consonantes finales (dejar las palabras sin terminar; ej. decir 'arbo' por 'árbol')", "Asimilación (un sonido de la palabra influye y cambia a otro; ej. decir 'bobo' en vez de 'lobo')"], note: "Esta dificultad interfiere gravemente con la inteligibilidad del niño (qué tanto le entienden los demás)." }, diagnosis: { title: "Evaluación de Inteligibilidad", intro: "Un patólogo del habla y el lenguaje (logopeda) debe diferenciarlo de otros problemas:", items: ["Análisis de una muestra de habla espontánea conversacional (para identificar los patrones sistémicos de error que el niño aplica)", "Pruebas estandarizadas de fonología y articulación", "Examen de audición riguroso (una pérdida auditiva conductiva leve por líquido en los oídos a menudo impide que el niño perciba las diferencias sutiles entre los sonidos)", "Evaluación de la conciencia fonológica (la habilidad de segmentar las palabras en sonidos, vital para la futura lectura)"], note: "" }, treatment: { title: "Terapia de Reorganización Lingüística", intro: "El tratamiento no se centra en mover la lengua, sino en enseñar al cerebro las reglas del sonido:", subsections: [ { title: "Enfoques Logopédicos", items: ["Enfoque de contrastes mínimos (terapia donde el logopeda usa pares de palabras que difieren en un solo sonido, como 'beso' y 'peso', para que el niño reconozca que cambiar el sonido cambia el significado completo de la palabra)", "Entrenamiento en conciencia fonológica (juegos de rimas y separación de sílabas)", "Terapia de ciclos (enfocarse en un patrón fonológico erróneo durante unas semanas y luego pasar a otro, imitando el desarrollo natural del lenguaje)"] } ], note: "No tratar un trastorno fonológico a tiempo está directamente vinculado a graves dificultades futuras en el aprendizaje de la lectura y la escritura (dislexia)." }, whenToSeekHelp: { title: "¿Cuándo solicitar evaluación profesional?", intro: "Es fundamental buscar la ayuda de un logopeda si notas que:", items: ["Alrededor de los 3 años, las personas ajenas a la familia entienden menos del 50% de lo que dice el niño", "Al cumplir los 4 años, el habla del niño sigue siendo muy difícil de comprender (debería ser inteligible en un 90-100% para extraños)", "El niño omite sistemáticamente las consonantes iniciales o finales de casi todas las palabras", "Muestra frustración visible o evita participar en conversaciones debido a la barrera de comunicación"] } },
'Gingivoestomatitis' : { intro: "La gingivoestomatitis es una infección viral muy contagiosa y dolorosa de la boca y las encías. Afecta predominantemente a bebés y niños pequeños, siendo a menudo la forma en que el cuerpo reacciona a su primera exposición al virus del herpes simple.", whatIs: { title: "¿Qué es la Gingivoestomatitis?", text: "Es una afección aguda caracterizada por la inflamación generalizada, el enrojecimiento severo y la aparición de múltiples llagas, ampollas y úlceras dolorosas en las encías, el interior de las mejillas, el paladar, la lengua y a veces los labios. Las llagas hacen que sea extremadamente doloroso para el niño comer o beber." }, types: { title: "Causas y Virus Implicados", intro: "Es causada por infecciones virales agresivas en la mucosa oral:", items: ["Virus del Herpes Simple Tipo 1 (VHS-1) (es la causa más común, conocida como gingivoestomatitis herpética primaria; tras la infección inicial, el virus se queda latente de por vida y causa los 'fuegos' labiales ocasionales)", "Virus Coxsackie (causante de la enfermedad de 'mano, pie y boca', que produce llagas similares en la boca junto con sarpullido en manos y pies)", "Bacterias u hongos (causas muy raras, usualmente por una higiene dental extremadamente pobre)"], note: "El virus se contagia fácilmente a través del contacto con la saliva infectada (compartir juguetes llevados a la boca, utensilios o besos)." }, diagnosis: { title: "Evaluación Pediátrica Visual", intro: "El diagnóstico clínico suele ser rápido e inconfundible:", items: ["Examen físico bucal (el pediatra observará encías inflamadas que sangran fácilmente y las múltiples úlceras características blanquecinas/amarillentas con halo rojo)", "Evaluación de los ganglios linfáticos del cuello (que suelen estar muy inflamados y sensibles)", "Rara vez se requiere un cultivo viral o frotis de la llaga para confirmar la presencia de herpes, a menos que el paciente esté inmunodeprimido"], note: "" }, treatment: { title: "Control del Dolor e Hidratación", intro: "La enfermedad tiene un curso de 1 a 2 semanas. El objetivo vital es evitar la deshidratación:", subsections: [ { title: "Medidas de Apoyo y Fármacos", items: ["Hidratación exhaustiva (ofrecer líquidos fríos constantemente, paletas de hielo, agua o suero oral pediátrico; evitar jugos cítricos, ácidos o alimentos salados que quemen las llagas)", "Analgésicos y antipiréticos (Ibuprofeno o paracetamol en dosis precisas para controlar el dolor intenso y la fiebre alta, NUNCA aspirina)", "Enjuagues bucales 'Mágicos' o anestésicos tópicos (recetados por el médico para adormecer las encías minutos antes de comer; deben usarse con extrema precaución en niños para no afectar el reflejo de tragar)", "Medicamentos antivirales (como el Aciclovir oral, pero solo es eficaz si se administra en las primeras 72 horas desde el inicio de los síntomas para acortar levemente la enfermedad)"] } ], note: "Las encías pueden seguir sangrando ligeramente incluso varios días después de que la fiebre haya desaparecido." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ir a emergencias o al pediatra?", intro: "La complicación más grave y común es la deshidratación severa. Ve al hospital de inmediato si el niño:", items: ["Se niega por completo a beber cualquier tipo de líquido y no ha orinado (o no ha mojado un pañal) en más de 6 a 8 horas", "Llora sin lágrimas, tiene la boca completamente reseca, los ojos hundidos o parece extremadamente débil y letárgico", "Presenta fiebre muy alta, persistente e incontrolable que no baja con medicamentos", "Babea profusamente de forma constante y es incapaz de tragar su propia saliva (riesgo de asfixia o infección más profunda)"] } },
'Hepatitis C' : { intro: "La hepatitis C es una infección viral crónica y grave que causa inflamación y daño progresivo en el hígado. Se transmite principalmente a través del contacto directo con sangre infectada. Hoy en día, es una enfermedad altamente curable.", whatIs: { title: "¿Qué es la Hepatitis C?", text: "Es una enfermedad causada por el Virus de la Hepatitis C (VHC). A diferencia de la hepatitis A, que suele ser aguda y pasajera, la hepatitis C frecuentemente se vuelve una infección crónica y silenciosa que, a lo largo de décadas, puede destruir el hígado causando cirrosis y cáncer hepático sin que el paciente se dé cuenta." }, types: { title: "Fases de la Infección", intro: "La enfermedad tiene dos etapas clínicas principales:", items: ["Hepatitis C aguda (ocurre en los primeros 6 meses tras la exposición al virus; la mayoría de las personas no tienen síntomas y un porcentaje menor logra eliminar el virus de forma natural)", "Hepatitis C crónica (si el cuerpo no elimina el virus, la infección se vuelve permanente, atacando lentamente al hígado a lo largo de los años)"], note: "Las principales vías de contagio son compartir agujas, tatuajes o piercings con material no esterilizado, y transfusiones de sangre previas a 1990." }, diagnosis: { title: "Pruebas de Sangre y Evaluación Hepática", intro: "Dado que es una enfermedad silenciosa, el cribado mediante análisis de sangre es vital:", items: ["Prueba de anticuerpos contra el VHC (el primer paso; indica si alguna vez has estado expuesto al virus)", "Prueba de ARN del VHC o carga viral (si los anticuerpos son positivos, esta prueba confirma si el virus sigue activo y multiplicándose en tu sangre)", "Genotipado (para saber qué tipo específico o cepa del virus tienes, lo que antes dictaba el tratamiento)", "Elastografía hepática o FibroScan (una ecografía especializada para medir el nivel de cicatrización o cirrosis que ya ha sufrido el hígado)"], note: "" }, treatment: { title: "Cura con Antivirales de Acción Directa", intro: "La hepatitis C ha vivido una revolución médica; ahora se cura casi en el 100% de los casos:", subsections: [ { title: "Terapia Farmacológica", items: ["Antivirales de Acción Directa (AAD) (el tratamiento de oro absoluto: medicamentos orales que se toman diariamente durante 8 a 12 semanas y que erradican el virus por completo, con muy pocos efectos secundarios)", "Abstinencia de alcohol (vital para no acelerar el daño hepático mientras dura el tratamiento)", "Trasplante de hígado (solo necesario si el virus ya causó una cirrosis terminal o insuficiencia hepática irreversible antes de ser descubierto)"] } ], note: "Haberse curado de hepatitis C no genera inmunidad; si te expones a sangre infectada nuevamente, puedes volver a contagiarte." }, whenToSeekHelp: { title: "¿Cuándo solicitar pruebas o acudir al médico?", intro: "Debes pedirle a tu médico una prueba de sangre para Hepatitis C si:", items: ["Naciste entre 1945 y 1965 (la generación con mayor incidencia), o si alguna vez te hiciste un tatuaje en un lugar no regulado", "Has compartido agujas o jeringas, incluso si fue una sola vez hace muchos años", "Presentas síntomas tardíos de daño hepático: fatiga crónica extrema, coloración amarillenta de la piel u ojos (ictericia), orina oscura o hinchazón y líquido en el abdomen"] } },
'Dermatitis y úlceras por estasis' : { intro: "La dermatitis por estasis es una inflamación y cambio de coloración persistente en la piel de la parte inferior de las piernas, provocada por una mala circulación venosa. Si no se trata, la piel se debilita tanto que se rompe, formando llagas abiertas llamadas úlceras por estasis venosa.", whatIs: { title: "¿Qué son la Dermatitis y Úlceras por Estasis?", text: "Es una consecuencia directa de la Insuficiencia Venosa Crónica. Cuando las válvulas de las venas de las piernas fallan, la sangre se estanca (estasis) y aumenta la presión en los capilares. Esto hace que líquido y glóbulos rojos se filtren hacia los tejidos de la piel, causando una severa inflamación, picazón, oscurecimiento de la piel y, eventualmente, la muerte del tejido que forma una úlcera dolorosa." }, symptoms: { title: "Evolución de los Síntomas", intro: "Los problemas progresan desde una simple hinchazón hasta heridas graves:", groups: [ { name: "Señales Cutáneas y Vasculares", items: ["Hinchazón profunda en los tobillos que empeora al final del día", "Piel extremadamente reseca, con picazón intensa, enrojecida o escamosa alrededor de los tobillos", "La piel de la espinilla se vuelve gruesa, dura y de un color marrón oscuro o cobrizo (hemosiderina)", "Aparición de una llaga superficial húmeda que exuda líquido y no cicatriza (la úlcera)"] } ], warning: "Rascarse la piel afectada por estasis casi siempre desencadena una herida que se convertirá en una úlcera difícil de cerrar." }, types: { title: "Factores Agravantes", intro: "Se relaciona estrechamente con afecciones cardiovasculares y el estilo de vida:", items: ["Varices graves no tratadas", "Antecedentes de coágulos de sangre en las piernas (Trombosis Venosa Profunda)", "Obesidad severa y sedentarismo extremo (la falta de uso de los gemelos impide bombear la sangre hacia arriba)", "Insuficiencia cardíaca congestiva"], note: "" }, diagnosis: { title: "Evaluación Dermatológica y Vascular", intro: "Requiere un enfoque conjunto entre el dermatólogo y el cirujano vascular:", items: ["Examen físico visual del aspecto clásico de la piel y palpación de la dureza del tejido (lipodermatosclerosis)", "Ecografía Doppler de las piernas (esencial para confirmar que las venas no están funcionando y detectar reflujo venoso o coágulos ocultos)", "Cultivo de la úlcera (si se sospecha que la llaga se ha infectado con bacterias)"], note: "" }, treatment: { title: "Compresión y Cuidado de Heridas", intro: "Las cremas no curarán la piel si no se soluciona primero el problema de la presión sanguínea subyacente:", subsections: [ { title: "Medidas Terapéuticas", items: ["Terapia de compresión (el tratamiento más crítico: uso diario e innegociable de medias o vendajes elásticos de alta compresión médica para empujar el líquido de regreso al corazón)", "Elevación de las piernas por encima del nivel del pecho varias veces al día", "Cremas con corticosteroides tópicos (para apagar el intenso picor y la inflamación de la dermatitis en fases agudas)", "Cuidado clínico de las úlceras (limpieza médica constante, parches especiales que absorben el exceso de exudado y antibióticos si hay infección)", "Cirugía o láser vascular (para cerrar o extirpar las venas varicosas defectuosas que causan el problema de raíz)"] } ], note: "Las úlceras por estasis pueden tardar meses en sanar completamente y exigen extrema paciencia y constancia." }, whenToSeekHelp: { title: "¿Cuándo acudir al médico?", intro: "No ignores los cambios de color en tus tobillos. Busca atención de inmediato si:", items: ["La piel de tus pantorrillas se vuelve roja, caliente al tacto y el dolor aumenta bruscamente (signo de celulitis infecciosa letal)", "Aparece una pequeña úlcera o herida abierta que no se cierra tras una o dos semanas", "La llaga comienza a supurar un líquido espeso, amarillento, verdoso o tiene un olor muy desagradable", "Sientes escalofríos o presentas fiebre asociada al dolor en la pierna"] } },
'Celotipia' : { intro: "La celotipia, también conocida como síndrome de Otelo o celos patológicos, es un trastorno psiquiátrico grave y delirante. La persona que lo padece está absolutamente e irracionalmente convencida de que su pareja le es infiel, sin tener ninguna prueba real o evidencia lógica que lo respalde.", whatIs: { title: "¿Qué es la Celotipia?", text: "No es un simple ataque de celos normal. Es un trastorno delirante y destructivo. La mente del individuo construye una realidad paralela y obsesiva sobre la traición de su pareja. Cada mirada, retraso mínimo o gesto inofensivo es interpretado como una 'prueba irrefutable' de la infidelidad. La persona celotípica pierde el control, invadiendo la privacidad de su pareja y destruyendo la relación mediante vigilancia y acusaciones incesantes." }, symptoms: { title: "Comportamientos y Patrones", intro: "Se manifiesta mediante una obsesión controladora extrema:", groups: [ { name: "Señales de Alarma Psicológica", items: ["Revisión constante y obsesiva del teléfono, correos, redes sociales y pertenencias de la pareja", "Interrogatorios exhaustivos y agresivos sobre a dónde fue la pareja, con quién habló o por qué tardó minutos de más", "Aislamiento forzado (intentar que la pareja no vea a amigos, familiares o compañeros de trabajo por miedo irracional)", "Falsas acusaciones continuas de aventuras con completos extraños o amigos cercanos", "Seguimiento físico, espionaje o contratación de investigadores privados sin motivo real"] } ], warning: "La celotipia es una de las causas principales de violencia de género, violencia doméstica y feminicidios. Si hay agresión, la víctima debe ponerse a salvo inmediatamente." }, types: { title: "Causas Subyacentes", intro: "Este trastorno rara vez aparece aislado, suele estar vinculado a:", items: ["Inseguridad profunda, baja autoestima extrema y un miedo patológico y ansioso al abandono", "Trastornos de la personalidad (como el Trastorno Paranoide, Límite o Narcisista)", "Abuso crónico de alcohol o drogas (el alcoholismo es un desencadenante biológico inmensamente común del síndrome de Otelo)", "Trastornos orgánicos (demencia temprana, Alzheimer o Parkinson, donde el cerebro pierde capacidad lógica)"], note: "" }, diagnosis: { title: "Evaluación Psiquiátrica", intro: "Es un diagnóstico complejo porque el paciente jura que tiene la razón:", items: ["Evaluación clínica psiquiátrica (se basa en la entrevista con el paciente y, fundamentalmente, en la información aportada por la pareja o familiares, ya que el paciente negará tener un problema)", "Evaluación de trastornos comórbidos (buscar signos de esquizofrenia, depresión severa o alcoholismo oculto)", "Evaluación de riesgo y seguridad (el psiquiatra debe determinar urgentemente si la pareja corre peligro físico)"], note: "" }, treatment: { title: "Intervención Psicológica y Psicofarmacología", intro: "Tratar a una persona con celotipia es un reto inmenso porque carecen de 'conciencia de enfermedad' (no creen estar enfermos, creen estar siendo engañados):", subsections: [ { title: "Terapéuticas Clave", items: ["Medicación Antipsicótica (el pilar para el delirio; fármacos como risperidona, olanzapina o pimozida ayudan a atenuar los pensamientos irracionales y la paranoia severa)", "Antidepresivos ISRS (para reducir los comportamientos obsesivo-compulsivos y la extrema ansiedad subyacente)", "Terapia Cognitivo-Conductual (TCC) individual (para intentar que el paciente identifique distorsiones cognitivas, aunque su eficacia en el delirio puro es limitada sin medicación)", "Terapia de pareja (MUY controvertida y a menudo desaconsejada hasta que el agresor esté medicado y estable, ya que puede usarse para justificar más abusos)"] } ], note: "La pareja de una persona celotípica debe recibir terapia individual urgente para lidiar con el trauma del abuso psicológico y aprender a establecer límites de seguridad." }, whenToSeekHelp: { title: "¿Cuándo intervenir o buscar ayuda urgente?", intro: "Para la pareja que sufre las consecuencias, es imperativo buscar ayuda (psicológica o policial) si:", items: ["Las acusaciones de infidelidad se vuelven agresivas, intimidantes o van acompañadas de gritos y amenazas", "Sientes que estás caminando sobre 'cáscaras de huevo', cambiando tu forma de vestir, actuar o aislando tus amistades solo para evitar detonar su ira y celos", "Eres víctima de violencia física, te retienen contra tu voluntad o dañan tus pertenencias durante un ataque de celos", "La persona amenaza con suicidarse o con hacerte daño si lo abandonas o si 'descubre' la infidelidad"] } },
'Infertilidad masculina' : { intro: "La infertilidad masculina se define como la incapacidad de un hombre para lograr que una mujer fértil quede embarazada tras un año o más de relaciones sexuales regulares y sin protección. Es la causa principal o contribuyente en aproximadamente la mitad de todos los casos de problemas de fertilidad en parejas.", whatIs: { title: "¿Qué causa la Infertilidad Masculina?", text: "Para concebir, un hombre debe producir espermatozoides sanos, en cantidad suficiente, con buena movilidad (capacidad de nadar) y forma (morfología), y debe existir un conducto despejado para que el semen sea eyaculado en la vagina. Un fallo, obstrucción o desequilibrio hormonal en cualquiera de estos pasos resulta en infertilidad." }, types: { title: "Causas Fisiológicas y Médicas", intro: "Los problemas se originan por alteraciones en la producción o el transporte:", items: ["Varicocele (la causa reversible más común; venas hinchadas en el escroto que calientan los testículos y matan los espermatozoides)", "Infecciones (enfermedades de transmisión sexual como clamidia o gonorrea, o inflamación de la próstata/epidídimo que bloquean los conductos o causan cicatrices)", "Problemas de eyaculación (eyaculación retrógrada, donde el semen entra a la vejiga en lugar de salir por el pene, a menudo causado por diabetes o cirugía de próstata)", "Desequilibrios hormonales (niveles bajos de testosterona o problemas en la glándula pituitaria)", "Exposición a toxinas o estilo de vida (uso de esteroides anabólicos, tabaquismo severo, abuso de alcohol, radiación o trabajar con mucho calor)"], note: "El uso de suplementos de testosterona recetados o de gimnasio detiene casi por completo la producción natural de esperma, causando infertilidad severa temporal o permanente." }, diagnosis: { title: "Evaluación Urológica y Andrológica", intro: "El estudio del hombre es el paso más rápido y sencillo en la evaluación de una pareja:", items: ["Análisis de semen o espermiograma (la prueba fundamental; el laboratorio evalúa la cantidad, la forma, la movilidad y la vitalidad de los espermatozoides en una muestra)", "Examen físico genital completo (el urólogo buscará varicoceles, atrofia testicular o falta de conductos deferentes)", "Análisis de sangre (para medir niveles de testosterona, FSH, LH y prolactina)", "Ecografía escrotal o transrectal (para ver obstrucciones en los conductos eyaculadores o tumores)"], note: "" }, treatment: { title: "Cirugía, Medicación y Reproducción Asistida", intro: "Dependiendo de la causa, muchos hombres pueden recuperar la fertilidad o lograr ser padres con ayuda clínica:", subsections: [ { title: "Opciones de Tratamiento", items: ["Cirugía de Varicocelectomía (ligar las venas hinchadas del escroto mejora dramáticamente la calidad del esperma en pocos meses)", "Cirugía de reversión de vasectomía o desobstrucción de conductos", "Tratamientos hormonales (medicamentos como el Clomifeno para estimular al cerebro a ordenar a los testículos que fabriquen más esperma)", "Inyección Intracitoplasmática de Espermatozoides o ICSI (la maravilla de la ciencia reproductiva: si el hombre tiene muy pocos espermatozoides o no se mueven, el biólogo extrae un solo espermatozoide sano con una aguja y lo inyecta directamente dentro del óvulo de la mujer en el laboratorio)"] } ], note: "Incluso si no hay ningún espermatozoide en el semen eyaculado, los urólogos a menudo pueden extraerlos directamente del testículo mediante una biopsia quirúrgica para usarlos en FIV." }, whenToSeekHelp: { title: "¿Cuándo consultar a un especialista en fertilidad?", intro: "Debes programar una cita con un urólogo o andrólogo si:", items: ["Tú y tu pareja no han logrado el embarazo tras 12 meses de relaciones sexuales regulares sin protección (o 6 meses si tu pareja femenina es mayor de 35 años)", "Tienes problemas continuos para lograr o mantener una erección (disfunción eréctil) o problemas de eyaculación", "Sientes dolor crónico, molestias, un bulto o inflamación evidente en el área de los testículos o el escroto", "Tienes antecedentes de cirugías en los testículos, próstata o hernias inguinales en la infancia, o un testículo no descendido"] } },
'Bacteriuria asintomática' : { intro: "La bacteriuria asintomática es una afección médica en la cual hay presencia confirmada de bacterias en la orina (en cantidades significativas), pero el paciente no experimenta absolutamente ningún síntoma de infección urinaria, como dolor, ardor, fiebre o urgencia.", whatIs: { title: "¿Qué es la Bacteriuria Asintomática?", text: "Normalmente, la orina es un líquido estéril. Sin embargo, en muchas personas (especialmente ancianos y mujeres), las bacterias pueden colonizar la vejiga y vivir allí pacíficamente sin inflamar el tejido ni causar enfermedad. El cuerpo simplemente tolera la presencia de estas bacterias." }, types: { title: "Poblaciones Frecuentes", intro: "Es un hallazgo de laboratorio sumamente común, no una enfermedad de la que asustarse, especialmente en:", items: ["Adultos mayores, sobre todo en residencias de ancianos (hasta el 50% de las mujeres mayores la tienen y es normal para ellas)", "Personas que usan sondas o catéteres urinarios permanentes (la colonización bacteriana ocurre siempre en un 100% al cabo de unos días)", "Mujeres jóvenes sanas (es menos común pero puede ocurrir)", "Pacientes con diabetes o lesiones de la médula espinal"], note: "En la inmensa mayoría de las personas, no requiere ni se debe dar tratamiento." }, diagnosis: { title: "Hallazgo Incidental en Laboratorio", intro: "Generalmente se descubre por accidente cuando se realiza un análisis por otras razones:", items: ["Cultivo de orina (Urocultivo) positivo con un alto recuento de bacterias (típicamente más de 100,000 colonias), pero la persona interrogada asegura no sentir ningún dolor ni ardor al orinar", "Análisis de orina con tira reactiva que muestra nitritos o leucocitos, pero en ausencia total de síntomas clínicos"], note: "La clave médica es la palabra 'asintomática': la clínica del paciente importa más que el papel del laboratorio." }, treatment: { title: "Por Qué NO Tratar con Antibióticos", intro: "El consenso mundial de la infectología y la urología es NO TRATAR la bacteriuria asintomática en la población general:", subsections: [ { title: "Regla de Oro y Excepciones Vitales", items: ["No se prescriben antibióticos (tratar a alguien sin síntomas no previene futuras infecciones, daña su flora intestinal, causa efectos secundarios innecesarios y crea 'superbacterias' resistentes que serán imposibles de matar en el futuro)", "EXCEPCIÓN 1: Mujeres embarazadas (DEBEN ser tratadas obligatoriamente; en el embarazo, esta bacteriuria silenciosa tiene un riesgo altísimo de subir a los riñones, causar pielonefritis, parto prematuro y bajo peso al nacer)", "EXCEPCIÓN 2: Personas que van a someterse a una cirugía urológica o prostática (deben recibir antibióticos antes de la incisión para que la bacteria no entre a la sangre)", "EXCEPCIÓN 3: En algunos pacientes con trasplante renal reciente"] } ], note: "Es un error médico muy común y obsoleto recetar antibióticos a ancianos solo porque su orina huele fuerte o su cultivo es positivo, si no tienen fiebre, ardor o confusión aguda." }, whenToSeekHelp: { title: "¿Cuándo la condición cambia y requiere atención?", intro: "La bacteriuria asintomática solo se convierte en un problema si deja de ser asintomática. Consulta a tu médico si empiezas a notar:", items: ["Ardor intenso, dolor o escozor evidente cada vez que vas al baño a orinar", "Una necesidad repentina, desesperada y urgente de orinar muchas veces al día", "Fiebre, escalofríos, náuseas o dolor sordo y punzante en la parte baja de la espalda (flancos), lo que indica que la infección ha atacado los riñones", "Si estás embarazada, debes asistir puntualmente a todos tus cultivos de orina prenatales de rutina"] } },
'Hombro de tenista' : { intro: "En el ámbito médico y ortopédico, el 'hombro de tenista' no se refiere a una sola enfermedad, sino a un conjunto de lesiones por uso excesivo y microtraumatismos en el hombro, típicas en deportistas de raqueta y atletas que realizan potentes movimientos repetitivos del brazo por encima de la cabeza.", whatIs: { title: "¿Qué ocurre en el Hombro por los Deportes de Raqueta?", text: "El movimiento explosivo del saque o el remate en el tenis y el pádel exige una fuerza y rotación extremas de la articulación del hombro. Con el tiempo, esta tensión violenta y repetitiva provoca el pinzamiento, la inflamación profunda y el desgarro progresivo de los tendones que estabilizan el brazo (el manguito rotador) o del cartílago interno (el labrum)." }, types: { title: "Patologías Específicas Frecuentes", intro: "El término suele englobar las siguientes lesiones específicas:", items: ["Tendinitis o desgarro del manguito rotador (inflamación o rotura del tendón supraespinoso, causando dolor agudo al intentar levantar el brazo lateralmente)", "Síndrome de pinzamiento subacromial (los tendones se pellizcan y rozan contra el hueso del omóplato al realizar el saque)", "Lesión de SLAP (un desgarro grave del labrum, el anillo de cartílago que rodea la cavidad del hombro, muy común al frenar el brazo bruscamente tras golpear la bola)", "Bursitis subacromial (inflamación del saco de líquido que amortigua el hombro)"], note: "No debe confundirse con el 'Codo de tenista' (epicondilitis lateral), que afecta a los tendones del antebrazo en la parte externa del codo." }, diagnosis: { title: "Evaluación Ortopédica y Biomecánica", intro: "Un especialista en medicina deportiva debe evaluar exactamente qué estructura ha fallado:", items: ["Examen físico especializado (el médico rotará tu brazo y aplicará resistencia en ángulos específicos para reproducir el dolor, como el Test de Neer o de Jobe para el pinzamiento)", "Ecografía musculoesquelética (excelente y rápida para visualizar bursitis aguda o tendones engrosados e inflamados)", "Resonancia Magnética (RM) o Artro-RM (la prueba definitiva innegociable; si se inyecta contraste en el hombro, revela con precisión milimétrica los desgarros complejos del cartílago labrum o rupturas totales del manguito que requieren cirugía)"], note: "" }, treatment: { title: "Rehabilitación, Descanso y Cirugía", intro: "El tratamiento temprano previene la necesidad del quirófano:", subsections: [ { title: "Opciones de Recuperación", items: ["Reposo deportivo estricto (suspender los saques, remates y levantamientos pesados por encima de la cabeza, pero mantener la movilidad baja para no congelar el hombro)", "Fisioterapia intensiva (el pilar fundamental: reequilibrar la biomecánica, estirar la cápsula posterior y fortalecer los músculos de la escápula para que el hombro no roce)", "Medicamentos AINEs e Hielo (para apagar la inflamación química y el dolor profundo)", "Inyecciones de corticosteroides o plasma rico en plaquetas (PRP) en el espacio subacromial", "Cirugía artroscópica (si la fisioterapia falla tras 3-6 meses o si hay una rotura completa del tendón, el cirujano inserta una cámara y anclajes para volver a coser el tendón al hueso)"] } ], note: "Corregir la técnica del saque con un entrenador es la única forma de evitar recaer una vez sanado." }, whenToSeekHelp: { title: "¿Cuándo es imperativo visitar al traumatólogo deportivo?", intro: "Debes suspender el deporte de inmediato y buscar atención médica si:", items: ["Sientes un dolor profundo e inmovilizante, o escuchaste un fuerte 'chasquido' dentro del hombro en el momento exacto de golpear o sacar la pelota", "Eres incapaz de levantar o mantener tu brazo elevado a la altura de tu cabeza por debilidad real, o sientes que el brazo 'se cae' al bajarlo", "El dolor del hombro es tan persistente que te despierta o no te deja dormir por la noche al apoyarte sobre él", "Sientes que el hombro 'cruje', 'se traba' o tienes una sensación punzante de que el brazo se va a dislocar al moverlo"] } },
'Displasia broncopulmonar' : { intro: "La displasia broncopulmonar (DBP) es una enfermedad pulmonar crónica y grave que afecta principalmente a bebés prematuros que nacen con pulmones inmaduros y requieren terapias de oxígeno prolongadas o el uso de ventiladores mecánicos (respiradores) para sobrevivir a sus primeros días de vida.", whatIs: { title: "¿Qué es la Displasia Broncopulmonar?", text: "Es una lesión cicatricial de los pulmones. Para mantener con vida a un bebé muy prematuro, los médicos deben bombear aire y oxígeno a presión hacia sus frágiles vías respiratorias. Paradójicamente, la fuerza mecánica de la máquina y la toxicidad del oxígeno puro inflaman, estiran en exceso y dañan los delicados y minúsculos alvéolos pulmonares en desarrollo, dejándolos con cicatrices que dificultan enormemente su respiración futura." }, types: { title: "Factores de Riesgo en la UCIN", intro: "Es el trastorno respiratorio crónico más común de la infancia prematura, ligado estrechamente a:", items: ["Grado de prematuridad (los bebés nacidos antes de las 28 semanas de gestación o que pesan menos de 1000 gramos tienen el riesgo más alto, ya que sus pulmones apenas empezaban a formarse)", "Síndrome de Dificultad Respiratoria Neonatal (la carencia de surfactante pulmonar natural al nacer obliga a usar los respiradores mecánicos)", "Infecciones (neumonías o sepsis durante la estadía en la Unidad de Cuidados Intensivos Neonatales que agravan la inflamación pulmonar)", "Presencia de Conducto Arterioso Persistente (un problema cardíaco que inunda los pulmones de sangre, dificultando más la respiración)"], note: "A medida que el bebé crece y desarrolla tejido pulmonar nuevo y sano, los síntomas de la DBP generalmente mejoran de forma notable, aunque pueden quedar secuelas de asma." }, diagnosis: { title: "Diagnóstico Clínico Neonatal", intro: "El diagnóstico se basa en el tiempo que el bebé ha necesitado soporte vital:", items: ["Criterio diagnóstico temporal (el neonatólogo diagnostica DBP si el bebé prematuro sigue necesitando oxígeno suplementario continuo o soporte respiratorio cuando alcanza las 36 semanas de edad posmenstrual, es decir, casi un mes antes de su fecha original de nacimiento)", "Radiografía de tórax (muestra los pulmones con un aspecto anormal, esponjoso, con áreas sobreinfladas y cicatrices blancas en lugar de estar oscuros y limpios)", "Análisis de gases en sangre y monitoreo continuo de oximetría para ver qué tan bien (o mal) está oxigenando el bebé su sangre por sí mismo"], note: "" }, treatment: { title: "Soporte Respiratorio y Nutrición Agresiva", intro: "No existe una cura mágica para revertir el daño y la cicatrización; el tratamiento se enfoca en asistir al bebé mientras sus pulmones crecen y se reparan solos con el tiempo:", subsections: [ { title: "Intervenciones en la UCIN y el Hogar", items: ["Oxigenoterapia prolongada (suministrar oxígeno continuo y cuidadoso mediante cánulas nasales, a menudo durante meses, incluso después de irse a casa)", "Nutrición altísima en calorías (los bebés con DBP gastan inmensas cantidades de energía solo en el esfuerzo físico de intentar respirar, por lo que requieren fórmulas especiales o sondas de alimentación para no desnutrirse y poder generar tejido nuevo)", "Diuréticos (medicamentos fundamentales para hacer que el bebé orine más y eliminar la peligrosa acumulación de líquido en los pulmones, que los hace pesados y rígidos)", "Broncodilatadores inhalados y corticosteroides (para relajar los músculos de las vías respiratorias y reducir la violenta inflamación tisular)", "Inmunización estricta (inyecciones del medicamento palivizumab -Synagis- en invierno para protegerlos desesperadamente del letal Virus Sincitial Respiratorio o VSR)"] } ], note: "Muchos niños que superan la DBP son dados de alta con sus tubos de oxígeno a casa y requieren un cuidado y monitoreo familiar excepcional durante el primer año." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA VITAL tras el alta médica?", intro: "Los pulmones de un niño con DBP tienen muy poca reserva funcional. Un simple resfriado puede ser mortal. Corre a urgencias pediátricas o llama al 911 si el bebé:", items: ["Presenta un intenso tiraje o retracción (la piel del pecho se hunde profunda y desesperadamente debajo de las costillas o el cuello con cada respiración)", "Comienza a respirar mucho más rápido de lo habitual o emite gruñidos rítmicos y quejidos al soltar el aire", "Sus labios, lengua, o la piel alrededor de su boca se vuelven de un tono azulado oscuro o gris (cianosis severa)", "Muestra aleteo nasal evidente (las fosas nasales se abren al máximo buscando aire)", "Está inusualmente letárgico, pálido, flácido y no tiene fuerza ni para intentar alimentarse de su biberón"] } },
'Sonrisa gingival' : { intro: "La sonrisa gingival (o exceso de exhibición gingival) es una alteración estética y anatómica en la que una persona expone una cantidad desproporcionada y excesiva de tejido de la encía superior (usualmente más de 3 o 4 milímetros) al sonreír alegremente.", whatIs: { title: "¿Qué es una Sonrisa Gingival?", text: "A diferencia de una enfermedad que causa dolor o acorta la vida, la sonrisa gingival es principalmente una preocupación estética o de proporciones. No obstante, ocurre debido a variaciones biomecánicas o de desarrollo en los dientes, las encías, los músculos faciales del labio superior o la estructura del hueso maxilar superior." }, types: { title: "Causas y Factores Estructurales", intro: "Para tratarla correctamente, el odontólogo debe identificar exactamente por qué se muestra tanta encía:", items: ["Causa Muscular o labio hipermóvil (el músculo que levanta el labio superior es demasiado fuerte o reactivo y tira del labio muy arriba al sonreír, exponiendo la encía)", "Causa Dentaria o erupción pasiva alterada (los dientes superiores son normales, pero al crecer no rompieron la encía por completo, quedando atrapados y tapados por un exceso de tejido gingival, haciendo que los dientes luzcan pequeños y cuadrados)", "Causa Esquelética o exceso maxilar vertical (el hueso de la mandíbula superior creció exageradamente hacia abajo, siendo más largo de lo normal, exponiendo hueso y encía)", "Causa Labial (el labio superior es anatómicamente más corto de lo normal)"], note: "A menudo, la sonrisa gingival puede ser una combinación simultánea de dos o más de estas causas biológicas." }, diagnosis: { title: "Evaluación Odontológica y Facial", intro: "El especialista (ortodoncista, periodoncista o cirujano maxilofacial) realizará un análisis de sonrisa:", items: ["Análisis cefalométrico y fotográfico (estudio de las proporciones del rostro, el tamaño del labio en reposo y en sonrisa plena)", "Examen periodontal y sondeo (para medir qué parte del diente está cubierta inútilmente por la encía y determinar el nivel de la unión de la raíz)", "Radiografías laterales de cráneo (para confirmar si el hueso maxilar superior ha crecido de forma anormal hacia abajo)"], note: "" }, treatment: { title: "Opciones de Corrección y Armonización", intro: "El tratamiento varía drásticamente dependiendo de cuál sea el origen exacto del problema:", subsections: [ { title: "Terapias Estéticas y Quirúrgicas", items: ["Infiltración de Toxina Botulínica - Bótox (el tratamiento no invasivo y rápido para el labio hipermóvil; el médico inyecta botox para paralizar y relajar levemente los músculos elevadores, evitando que el labio suba tanto. Dura de 4 a 6 meses)", "Gingivectomía o alargamiento de corona (cirugía periodontal rápida y menor donde el dentista usa un láser o bisturí para recortar y eliminar el exceso de encía, descubriendo la verdadera y hermosa longitud del diente oculto debajo)", "Ortodoncia o brackets (en casos leves donde los dientes frontales están muy inclinados hacia abajo, se usan aparatos para empujarlos intrusivamente hacia arriba en el hueso)", "Cirugía Ortognática (el procedimiento mayor y definitivo para el exceso esquelético; un cirujano maxilofacial corta el hueso del maxilar superior, quita el exceso y lo reposiciona hacia arriba, fijándolo con placas de titanio)"] } ], note: "Muchos pacientes consiguen resultados espectaculares y definitivos simplemente combinando la cirugía de corte de encías (gingivectomía) con carillas dentales para armonizar el tamaño de sus dientes." }, whenToSeekHelp: { title: "¿Cuándo considerar la visita al especialista?", intro: "Dado que no es una patología peligrosa, la búsqueda de ayuda radica en tu nivel de confort:", items: ["Sientes una profunda timidez, vergüenza o complejos psicológicos severos que te obligan a ocultar constantemente tu boca con la mano o a reprimir tus sonrisas en público o en fotos", "El exceso de encía te impide cerrar tus labios cómodamente estando en reposo (incompetencia labial), lo que causa que respires continuamente por la boca y tengas la garganta y encías resecas o inflamadas", "Presentas un desgaste dental excesivo, mala mordida o dolores articulares en la mandíbula acompañando tu problema estético"] } },
'Desviación Septal' : { intro: "Una desviación septal ocurre cuando el tabique nasal, que es la delgada pared de cartílago y hueso que divide el interior de la nariz en dos fosas nasales o conductos, está significativamente desplazado o inclinado hacia un lado.", whatIs: { title: "¿Qué es el Tabique Nasal Desviado?", text: "Idealmente, el tabique debería estar perfectamente centrado, haciendo que las dos vías respiratorias nasales sean de igual tamaño. Cuando está desviado severamente, una de las fosas nasales es más pequeña o más estrecha que la otra. Esta asimetría interrumpe el flujo normal de aire y el drenaje de mucosidad, lo que puede causar bloqueos respiratorios crónicos, infecciones y dolor facial." }, types: { title: "Causas y Naturaleza de la Desviación", intro: "Casi el 80% de la población mundial tiene un tabique ligeramente torcido sin saberlo. Se convierte en problema médico según su origen y grado:", items: ["Congénita o de desarrollo (la persona nace con la desviación porque ocurrió durante el desarrollo fetal, o el tabique se va torciendo gradualmente y sin trauma a medida que el rostro crece y se expande en la niñez y adolescencia)", "Adquirida por Traumatismo (la causa más evidente; el tabique se fractura o desplaza bruscamente por el impacto de un accidente automovilístico, un golpe jugando al fútbol, peleas, caídas o tropiezos en la infancia)", "Puede provocar de forma paralela la hipertrofia o agrandamiento de los cornetes nasales (unas estructuras esponjosas dentro de la nariz) en el lado 'más amplio', bloqueando así ambos lados de la nariz simultáneamente"], note: "Un tabique desviado no puede enderezarse por sí solo; una vez que el cartílago está torcido, permanece así de por vida a menos que se opere." }, diagnosis: { title: "Evaluación Otorrinolaringológica", intro: "El especialista del oído, nariz y garganta evaluará qué tan grave es la obstrucción anatómica:", items: ["Examen físico directo usando un espéculo nasal y una luz brillante (para dilatar y ver el cartílago torcido a simple vista en la entrada de la nariz)", "Endoscopia nasal (el médico introduce un tubo delgado, flexible e iluminado con una cámara pequeña para examinar profundamente las porciones traseras, óseas y más altas del tabique, y evaluar las aberturas de los senos paranasales)", "Tomografía Computarizada (TC) de los senos paranasales (a menudo ordenada si la desviación está causando sinusitis crónica recurrente y el médico necesita un mapa quirúrgico en 3D)"], note: "" }, treatment: { title: "Tratamiento Médico Paliativo vs. Corrección Quirúrgica", intro: "Las medicinas solo tratan y alivian temporalmente los síntomas; el único método para enderezar el cartílago torcido es la cirugía de bisturí:", subsections: [ { title: "Opciones de Manejo y Cirugía Definitiva", items: ["Manejo farmacológico inicial (uso de aerosoles de corticosteroides nasales, descongestionantes y antihistamínicos para desinflamar la mucosa hinchada o tratar alergias concurrentes, logrando abrir un poco más el conducto bloqueado)", "Tiras nasales adhesivas (para abrir mecánicamente y levantar las válvulas nasales y facilitar la respiración nocturna en casos leves)", "Septoplastia (la cirugía correctiva estándar y definitiva: el cirujano trabaja por dentro de la nariz, levanta la membrana mucosa, corta y extrae los pedazos torcidos de hueso o cartílago, y vuelve a colocar todo en el centro exacto. La recuperación dura de 1 a 2 semanas)", "Rinoseptoplastia (si el paciente, además de no poder respirar por el tabique desviado, tiene la nariz torcida o aguileña por fuera, el cirujano endereza la estructura interna y altera estéticamente el puente nasal exterior en una sola operación)"] } ], note: "Usar gotas descongestionantes de farmacia por más de 3 días seguidos causa un 'efecto rebote' peligroso que empeora la congestión y hace a la nariz adicta a la medicina." }, whenToSeekHelp: { title: "¿Cuándo es necesario consultar a un médico especialista?", intro: "Deberías agendar una evaluación con el otorrinolaringólogo si experimentas:", items: ["Obstrucción o congestión nasal crónica e intratable, especialmente en un solo lado de la nariz, que no mejora en absoluto con medicamentos de alergia ni jarabes", "Despertares nocturnos por sequedad de boca debido a que te ves obligado a dormir respirando permanentemente por la boca", "Ronquidos increíblemente fuertes, respiración muy ruidosa al dormir o desarrollo de apnea obstructiva del sueño (paradas de respiración nocturnas)", "Infecciones de los senos paranasales (sinusitis) repetitivas, dolor sordo de presión facial constante en la cara, o hemorragias nasales frecuentes y abundantes"] } },
'Enfermedad de Crohn' : { intro: "La enfermedad de Crohn es un tipo grave e incurable de enfermedad inflamatoria intestinal (EII). Provoca inflamación crónica, ulceración profunda y daños graves en los tejidos del tracto digestivo, lo que puede causar dolor abdominal debilitante y desnutrición que amenazan la vida.", whatIs: { title: "¿Qué es la Enfermedad de Crohn?", text: "Es una afección autoinmune implacable. En circunstancias normales, tu sistema inmunitario ataca bacterias dañinas. En el Crohn, por un error biológico, tus defensas atacan a los alimentos inofensivos, las bacterias buenas y al propio revestimiento del intestino, provocando una inflamación tan profunda que atraviesa todas las capas de la pared intestinal, dejando zonas enfermas intercaladas con zonas sanas ('lesiones salteadas')." }, types: { title: "Ubicaciones y Complicaciones", intro: "A diferencia de la Colitis Ulcerosa (que solo ataca el colon), el Crohn puede aparecer en CUALQUIER lugar desde la boca hasta el ano:", items: ["Ileocolitis (la forma más común, afecta la última parte del intestino delgado (íleon) y el intestino grueso (colon) al mismo tiempo)", "Iteítis (afecta y estrecha exclusivamente el íleon, la parte final del intestino delgado donde se absorbe la vitamina B12 y ácidos biliares)", "Enfermedad perianal (una complicación destructiva y dolorosísima donde se forman fístulas -túneles de infección- o profundos abscesos purulentos alrededor de la piel del ano)", "Complicaciones estructurales (la inflamación profunda constante genera tejido cicatricial duro que estrecha el intestino causando un 'bloqueo o estenosis', o crea perforaciones que obligan a intervenciones quirúrgicas de urgencia)"], note: "Suele diagnosticarse frecuentemente en personas jóvenes, entre los 20 y los 30 años, y su origen se sospecha fuertemente genético y ambiental." }, diagnosis: { title: "Pruebas Digestivas y Endoscópicas", intro: "El gastroenterólogo requiere observar directamente el daño intestinal para confirmar la enfermedad:", items: ["Colonoscopia con intubación del íleon terminal (es el examen estándar de oro y obligatorio; el médico inserta una cámara, visualiza las úlceras características y, vitalmente, extrae múltiples biopsias de tejido para que un patólogo confirme las células de Crohn en laboratorio)", "Entero-Resonancia Magnética (Entero-RM) o Tomografía Computarizada (Entero-TC) (fundamentales y precisas para evaluar las zonas del intestino delgado a las que el colonoscopio no llega, y localizar exactamente bloqueos o abscesos ocultos)", "Análisis de Heces (para medir la Calprotectina fecal, un marcador químico directo y extremadamente fiable del nivel de inflamación e ira del intestino, y para descartar infecciones por parásitos)", "Análisis de sangre (para revisar signos severos de anemia por malabsorción, hierro bajo o inflamación general - PCR)"], note: "" }, treatment: { title: "Inmunosupresión y Terapias Biológicas", intro: "La meta suprema es detener en seco el ataque inmunitario para alcanzar la 'remisión profunda' y que el intestino cicatrice por dentro:", subsections: [ { title: "Arsenal Médico y Cirugía", items: ["Terapias Biológicas avanzadas (el tratamiento moderno más potente y eficaz; medicamentos inyectables intravenosos como Infliximab, Adalimumab o Ustekinumab que bloquean proteínas exactas del sistema inmune -como TNF o IL-12/23-, apagando la inflamación profunda de raíz)", "Corticosteroides sistémicos (Prednisona, usados únicamente por cortos periodos de semanas para 'apagar el incendio' durante un brote agudo muy severo; nunca como tratamiento a largo plazo debido a sus tóxicos efectos secundarios)", "Inmunomoduladores tradicionales (como Azatioprina o Metotrexato en pastillas, que deprimen de manera más amplia el sistema inmune para evitar recaídas)", "Nutrición Enteral o exclusión dietética (utilizar batidos de fórmulas líquidas especiales recetadas por meses para dar descanso absoluto al intestino mientras sana)", "Cirugía de resección intestinal (si un pedazo de intestino se bloquea por cicatrices rígidas o forma una fístula gigante inmanejable, el cirujano extirpa ese segmento dañado y une las partes sanas; no cura la enfermedad, que casi siempre regresa)"] } ], note: "El tabaquismo activo es el peor enemigo del paciente con Crohn; fumar duplica agresivamente el número de brotes, cirugías y daños intestinales." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE buscar atención médica hospitalaria?", intro: "Los brotes y ataques agudos de Crohn pueden escalar rápidamente a emergencias letales. Acude de inmediato si presentas:", items: ["Dolor o cólicos abdominales extremadamente severos, punzantes e insoportables que no ceden, acompañados de imposibilidad para defecar o expulsar gases (alerta de obstrucción intestinal total)", "Episodios de diarrea continua, descontrolada e inmanejable (a menudo más de 5-10 veces al día) que causan deshidratación rápida, mareos o desmayos al ponerte de pie", "Presencia visible de sangre, ya sea brillante o heces negras y alquitranadas, flotando de manera constante en el inodoro", "Fiebre alta, escalofríos intensos o sudores nocturnos acompañados de un dolor profundo y pulsátil alrededor del ano (indicativo de un absceso de pus formándose)", "Pérdida de peso radical, drástica, y una fatiga paralizante e inexplicable durante semanas"] } },
'Cáncer laríngeo' : { intro: "El cáncer laríngeo, o cáncer de laringe (la caja de la voz), es una enfermedad oncológica agresiva que comienza en los tejidos del conducto respiratorio superior del cuello. Afecta directamente la capacidad de una persona para hablar, tragar alimentos con seguridad y respirar adecuadamente.", whatIs: { title: "¿Qué es el Cáncer de Laringe?", text: "Es el crecimiento descontrolado y maligno de células (casi siempre carcinomas de células escamosas) en las paredes interiores de la laringe. La laringe alberga las cuerdas vocales que producen la voz y la epiglotis, la válvula vital que se cierra cuando tragas para impedir que la comida o los líquidos caigan y ahoguen tus pulmones. A medida que el tumor crece, altera y destruye estas funciones críticas." }, types: { title: "Clasificación Anatómica y Factores Letales", intro: "Se clasifica dependiendo de la parte exacta de la caja de la voz donde se asienta el tumor:", items: ["Glótico (cáncer que comienza exactamente en las propias cuerdas vocales; debido a que cambia la voz muy temprano causando ronquera instantánea, suele detectarse a tiempo en etapas 1 o 2, teniendo tasas de curación excelentes)", "Supraglótico (cáncer en la zona superior de la laringe, por encima de las cuerdas vocales e incluyendo la epiglotis; suele descubrirse tarde cuando ya causa dolor al tragar o un bulto en el cuello)", "Subglótico (cáncer en la parte más baja de la laringe, justo donde se une a la tráquea; es extremadamente raro y el más difícil de detectar tempranamente)", "Factores de Riesgo Letales (El consumo conjunto de tabaquismo abundante y el abuso de alcohol crónico disparan y multiplican exponencialmente el riesgo; además de la infección previa por el Virus del Papiloma Humano -VPH-)"], note: "Fumar y beber a la vez es una bomba para la garganta; el alcohol actúa como un disolvente, permitiendo que los químicos cancerígenos del humo del cigarrillo penetren profundamente en los tejidos celulares del cuello." }, diagnosis: { title: "Exploración Endoscópica y Biopsia de Cuello", intro: "El otorrinolaringólogo y oncólogo deben confirmar visual y microscópicamente el tumor:", items: ["Laringoscopia o Endoscopia con tubo flexible (el primer y más importante paso en la consulta; el médico introduce un tubo delgadísimo e iluminado por la nariz para observar e inspeccionar minuciosamente el movimiento de las cuerdas vocales y buscar masas carnosas rojas o blancas sospechosas)", "Biopsia Quirúrgica (el único diagnóstico irrefutable del cáncer; a menudo requiere anestesia general en quirófano para arrancar y tomar muestras profundas del tejido dañado y enviarlas a patología)", "Tomografía Computarizada (TC), Resonancia Magnética (RM) del cuello o PET Scan (estas imágenes sofisticadas son absolutamente esenciales para ver y medir si el tumor ya atravesó el cartílago, o si ya viajó y se esparció e invadió los ganglios linfáticos del cuello o los pulmones)"], note: "" }, treatment: { title: "Preservación de la Voz y Cirugía Radical", intro: "El objetivo principal del tratamiento es erradicar completamente el cáncer y, siempre que sea posible, salvar la voz natural del paciente y su capacidad de tragar:", subsections: [ { title: "Intervenciones y Opciones Oncológicas", items: ["Radioterapia de haz externo (a menudo el tratamiento preferido y único de primera línea para los tumores y cánceres de laringe muy pequeños y tempranos, ya que las tasas de curación son altas y logra salvar intactas la anatomía y las cuerdas vocales)", "Cirugía conservadora o láser transoral (usando microcirugía láser por la boca en estadios iniciales para evaporar o cortar con altísima precisión el tumor superficial sin abrir el cuello)", "Laringectomía Total y Radical (la cirugía mayor definitiva reservada para los cánceres grandes o avanzados; el cirujano amputa y extrae toda la laringe entera. El paciente perderá por completo y para siempre su voz natural y pasará a respirar de por vida por un agujero o estoma permanente practicado en la base frontal del cuello)", "Quimioterapia sistémica y fármacos o Terapias Dirigidas (administradas por las venas, a menudo al mismo tiempo que la radioterapia en tumores intermedios avanzados, para intentar encogerlos masivamente y evitar así la amputación del cuello)"] } ], note: "Tras una laringectomía total de extracción, el paciente requerirá de intensos meses de profunda y frustrante rehabilitación con un logopeda especializado para aprender complejas y nuevas formas de comunicación y volver a hablar (usando una punción traqueoesofágica o hablando con voz esofágica de eructo)." }, whenToSeekHelp: { title: "¿Cuándo es obligatorio e innegociable ver a un especialista ORL?", intro: "El diagnóstico temprano del cáncer de garganta literalmente salva la voz de ser extirpada. Debes exigir una revisión de tus cuerdas vocales si padeces:", items: ["Tienes una ronquera continua, cambios en el tono, aspereza en la voz o te quedas afónico que persiste por más de 3 o 4 semanas seguidas y no se cura (especialmente imperativo si eres un fumador)", "Sientes un dolor agudo crónico o un pinchazo punzante e irradiado en la garganta o inexplicablemente en un solo oído (dolor referido) cada vez que pasas comida, saliva o al tragar", "Descubres al tacto un bulto asimétrico, ganglio, nódulo firme e indoloro, o hinchazón sólida que va creciendo de forma constante en el exterior o lados del cuello", "Desarrollas una persistente y angustiosa dificultad real o sensación de ahogo respiratorio, una extraña tos crónica seca que no cesa o comienzas repentinamente a expulsar flemas acompañadas de hilos oscuros o gotas de sangre viva"] } },
'Hipoglucemia' : { intro: "La hipoglucemia es una afección que ocurre cuando los niveles de glucosa (azúcar) en la sangre caen por debajo de lo normal y necesario para que el cuerpo funcione. Es una emergencia metabólica sumamente común en personas con diabetes.", whatIs: { title: "¿Qué es la Hipoglucemia?", text: "La glucosa es la principal fuente de energía de tu cuerpo y de tu cerebro. Cuando los niveles caen demasiado (generalmente por debajo de 70 mg/dL), el cerebro literalmente se queda sin 'combustible', desencadenando una respuesta de estrés de emergencia en todo el organismo, y si no se corrige rápido, puede causar la muerte cerebral." }, types: { title: "Causas y Desencadenantes", intro: "Casi siempre está ligada a los tratamientos para la diabetes, pero hay otras causas:", items: ["Hipoglucemia diabética (la más común, por inyectarse demasiada insulina, saltarse una comida o hacer ejercicio intenso sin comer)", "Hipoglucemia reactiva o posprandial (ocurre unas horas después de comer, a veces tras cirugías gástricas o por exceso de producción de insulina natural)", "Hipoglucemia en ayunas (causada por tumores en el páncreas -insulinomas-, consumo severo de alcohol sin comer o enfermedades hepáticas graves)"], note: "El alcohol bloquea la capacidad del hígado de liberar glucosa de emergencia a la sangre, causando bajadas peligrosas." }, diagnosis: { title: "Detección Rápida y Médica", intro: "El diagnóstico debe ser inmediato para tratarla al instante:", items: ["Glucómetro capilar o medidor continuo (el pinchazo en el dedo revelará niveles bajos instantáneamente, a menudo menores a 70 mg/dL)", "Análisis de sangre de laboratorio (glucosa, insulina, péptido C, si se está investigando hipoglucemia en alguien sin diabetes)", "La Tríada de Whipple (criterio médico: 1. Síntomas de glucosa baja, 2. Glucosa baja comprobada en sangre, 3. Los síntomas desaparecen al comer azúcar)"], note: "" }, treatment: { title: "Regla del 15 y Rescate", intro: "El tratamiento es la ingesta inmediata de azúcares simples de rápida absorción:", subsections: [ { title: "Rescate Inmediato", items: ["La 'Regla de los 15' (consumir 15 gramos de carbohidratos de acción rápida, como medio vaso de jugo o refresco no dietético, o tabletas de glucosa; esperar 15 minutos y volver a medir. Si sigue bajo, repetir)", "Comida de mantenimiento (una vez que el azúcar suba a más de 70, comer un snack con proteínas o carbohidratos complejos, como medio sándwich, para evitar que vuelva a caer)", "Inyección de Glucagón de emergencia (un medicamento inyectable o nasal que la familia debe administrar si el paciente diabético está inconsciente y no puede tragar)", "Glucosa intravenosa (administrada por paramédicos o en urgencias para casos severos o de coma)"] } ], note: "NUNCA intentes darle comida o líquidos por la boca a una persona que está convulsionando o perdiendo el conocimiento, ya que se ahogará y el líquido irá a los pulmones." }, whenToSeekHelp: { title: "¿Cuándo llamar al 911 o ir a urgencias?", intro: "Una hipoglucemia severa mata rápidamente. Pide ayuda vital inmediata si:", items: ["La persona se desmaya, pierde el conocimiento o entra en estado de coma", "La persona está experimentando convulsiones", "El paciente está demasiado confuso o combativo para tragar algo dulce", "El azúcar en la sangre no sube y los síntomas no mejoran después de haber aplicado la 'Regla de los 15' dos veces"] }, symptoms: { title: "Síntomas Físicos y Neurológicos", intro: "El cuerpo lanza fuertes señales de alarma impulsadas por la adrenalina:", groups: [ { name: "Señales Tempranas (Leves a Moderadas)", items: ["Temblores incontrolables en las manos", "Sudoración fría y profusa", "Palpitaciones y ritmo cardíaco muy acelerado", "Hambre extrema y repentina", "Irritabilidad intensa, ansiedad o nerviosismo"] }, { name: "Señales Severas (Daño Neurológico)", items: ["Confusión mental, comportamiento extraño o habla arrastrada (similar a estar ebrio)", "Visión borrosa o doble", "Pérdida de la coordinación motora", "Convulsiones y pérdida de conciencia"] } ], warning: "Algunos diabéticos de larga data desarrollan 'hipoglucemia inadvertida', donde su cuerpo ya no lanza señales de advertencia como temblores, y caen desmayados sin previo aviso." } },
'Aborto electivo o terapéutico' : { intro: "Un aborto electivo o terapéutico es el procedimiento médico o quirúrgico realizado por profesionales de la salud para interrumpir y finalizar un embarazo de manera segura y controlada.", whatIs: { title: "¿Qué es la Interrupción del Embarazo?", text: "Es la terminación voluntaria de la gestación. Se llama 'electivo' cuando se realiza por decisión personal de la paciente debido a motivos sociales, personales o económicos. Se llama 'terapéutico' cuando el embarazo representa un riesgo grave para la vida o la salud física/mental de la madre, o si el feto presenta malformaciones congénitas incompatibles con la vida." }, types: { title: "Métodos de Procedimiento", intro: "Existen dos vías principales para realizarlo, dependiendo de las semanas de gestación:", items: ["Aborto farmacológico o con medicamentos (usualmente seguro hasta las 10-11 semanas; se usan pastillas -Mifepristona y Misoprostol- que detienen el desarrollo del embarazo y provocan contracciones para vaciar el útero, similar a un aborto espontáneo natural fuerte)", "Aborto quirúrgico por Aspiración Manual Endouterina - AMEU (usado generalmente en el primer trimestre; un procedimiento clínico rápido bajo anestesia local o sedación donde se usa succión suave para vaciar el útero)", "Aborto quirúrgico por Dilatación y Evacuación - D&E (utilizado en el segundo trimestre; un procedimiento que requiere dilatación del cuello del útero y herramientas quirúrgicas además de succión)"], note: "En entornos médicos y legales, el aborto es uno de los procedimientos ginecológicos más seguros y comunes que existen, y no afecta la fertilidad futura de la mujer." }, diagnosis: { title: "Evaluación Médica Previa", intro: "Antes del procedimiento, el proveedor de salud debe confirmar varios parámetros:", items: ["Ecografía pélvica o transvaginal (absolutamente necesaria para confirmar las semanas exactas de embarazo y asegurar que no sea un embarazo ectópico -fuera del útero-, el cual requiere otro tratamiento de emergencia)", "Análisis de sangre (para verificar el tipo de sangre y el factor Rh de la mujer; si es Rh negativo, necesitará una inyección de inmunoglobulina para proteger futuros embarazos)", "Evaluación de historial médico (para decidir si es más seguro usar pastillas o cirugía)"], note: "" }, treatment: { title: "Cuidado Posterior e Intervención", intro: "El proceso clínico requiere seguimiento para asegurar que el útero esté limpio:", subsections: [ { title: "Cuidados y Anticoncepción", items: ["Reposo relativo tras el procedimiento y uso de analgésicos (ibuprofeno) y almohadillas térmicas para los intensos calambres", "Uso de toallas sanitarias en lugar de tampones o copas menstruales durante las primeras semanas para prevenir infecciones bacterianas", "Inicio inmediato de un método anticonceptivo (DIU, implante o píldoras), ya que la ovulación y la fertilidad pueden regresar tan rápido como en dos semanas después del aborto", "Ecografía de seguimiento (a las dos semanas, fundamental si fue con pastillas, para confirmar que no han quedado restos de tejido retenidos en el útero)"] } ], note: "Es completamente normal experimentar sangrado, manchado y cólicos que van y vienen durante varias semanas posteriores a la interrupción." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE contactar al hospital o clínica?", intro: "Aunque las complicaciones graves son extremadamente raras, debes buscar asistencia de urgencia si presentas:", items: ["Sangrado masivo y peligroso: empapas completamente dos toallas sanitarias grandes (maxi-pads) por hora, durante dos horas consecutivas", "Tienes fiebre de 38 °C o más que persiste después del primer día", "Experimentas un dolor abdominal o pélvico atroz que empeora rápidamente en lugar de mejorar, o que no cede con analgésicos fuertes", "Sientes un olor extremadamente fétido o a putrefacción proveniente de tu flujo vaginal", "Sufres de desmayos inexplicables, mareos severos al estar de pie, o confusión"] } },
'Hiperlordosis' : { intro: "La hiperlordosis es una curvatura excesiva o exagerada hacia adentro de la columna vertebral. Aunque la columna natural tiene curvas leves para absorber impactos, en la hiperlordosis esta curva se vuelve tan pronunciada que ejerce una gran presión dolorosa sobre la zona lumbar (espalda baja) o cervical (cuello).", whatIs: { title: "¿Qué es la Hiperlordosis?", text: "Popularmente conocida como 'espalda ensillada' o postura de 'pato'. A nivel lumbar, la pelvis se inclina demasiado hacia adelante, lo que hace que los glúteos sobresalgan exageradamente hacia atrás y el abdomen se proyecte hacia adelante. Este desequilibrio biomecánico aplasta los discos intervertebrales y fatiga la musculatura posterior crónicamente." }, types: { title: "Ubicación y Causas Comunes", intro: "Puede afectar el cuello o la espalda baja:", items: ["Hiperlordosis Lumbar (la más frecuente; se ubica en la espalda baja, y a menudo es causada por obesidad visceral, embarazo, o pasar demasiadas horas sentado, lo que acorta los músculos flexores de la cadera y debilita los glúteos y el abdomen)", "Hiperlordosis Cervical (una curva muy marcada en el cuello, frecuentemente asociada a la postura de 'cabeza adelantada' por mirar pantallas y celulares constantemente)", "Causas secundarias estructurales (como la espondilolistesis -un hueso de la columna se desliza hacia adelante-, osteoporosis o enanismo acondroplásico)"], note: "Un core (músculos abdominales) débil es el principal culpable muscular, ya que no puede sostener la pelvis en una posición neutral." }, diagnosis: { title: "Evaluación Postural y Radiológica", intro: "El diagnóstico clínico suele ser inmediato y muy visual:", items: ["Examen físico y postural de pie (el médico observará al paciente de perfil en una superficie plana; si hay un gran espacio entre la espalda baja y la pared al recostarse, es indicativo)", "Evaluación neurológica (para comprobar si la curva está pellizcando nervios ciáticos, causando hormigueo)", "Radiografías de la columna (rayos X laterales para medir con exactitud los grados de la curvatura de las vértebras)"], note: "" }, treatment: { title: "Reeducación Biomecánica", intro: "La mayoría de los casos de origen postural son altamente reversibles con ejercicio:", subsections: [ { title: "Manejo Físico y Terapia", items: ["Fisioterapia activa estricta (el pilar del tratamiento: estirar profundamente los flexores de cadera rígidos y fortalecer masivamente los músculos abdominales, oblicuos y glúteos)", "Reeducación postural (enseñar al cerebro a mantener la pelvis basculada hacia atrás en posición neutra al estar de pie o caminar)", "Pérdida de peso significativa (especialmente en la zona abdominal, para quitar el peso que tira de la columna hacia adelante)", "Medicación ocasional (relajantes musculares y AINEs para los espasmos de la espalda baja)", "Cirugía espinal (extremadamente rara, solo usada si hay daños neurológicos severos o una causa ósea grave como una espondilolistesis resbalada)"] } ], note: "Dormir boca abajo agrava enormemente la hiperlordosis lumbar y el dolor; se recomienda dormir de lado con una almohada entre las rodillas." }, whenToSeekHelp: { title: "¿Cuándo consultar a un traumatólogo o fisioterapeuta?", intro: "Es momento de buscar intervención médica si:", items: ["El dolor de espalda baja es constante, agudo y no mejora tras semanas de corrección de postura o ejercicios", "Sientes que tu postura te está limitando físicamente o los músculos de tu espalda sufren espasmos severos frecuentes", "Experimentas dolor eléctrico, hormigueo, debilidad, adormecimiento o pérdida de sensación que viaja por tus nalgas hacia una o ambas piernas (signo de que la curva está aplastando un nervio)", "Pierdes el control de tus intestinos o de la vejiga (incontinencia repentina), lo que es una emergencia espinal vital"] } },
'Hombro de nadador' : { intro: "El 'hombro de nadador' es un término clínico que engloba un conjunto de lesiones por sobrecarga en la articulación del hombro, muy comunes en nadadores de élite y aficionados. Se debe a la fricción y presión repetitiva sobre los tendones durante los millones de rotaciones del brazo en el agua.", whatIs: { title: "¿Qué es el Hombro de Nadador?", text: "Principalmente, se trata de un Síndrome de Pinzamiento Subacromial combinado a menudo con tendinitis del manguito rotador. Cada vez que el nadador saca y lanza el brazo hacia adelante (especialmente en crol o mariposa), el tendón del músculo supraespinoso choca y se 'pellizca' contra el arco de hueso (acromion) que está por encima, causando inflamación, microdesgarros y un dolor agudo e invalidante." }, types: { title: "Lesiones Componentes", intro: "Esta patología suele incluir varias afecciones simultáneas:", items: ["Tendinitis del Manguito Rotador (inflamación profunda de los tendones que estabilizan el hombro)", "Bursitis (inflamación de la pequeña bolsa de líquido que debería actuar como colchón y evitar la fricción entre el hueso y el tendón)", "Tendinitis bicipital (inflamación del tendón del músculo bíceps en la parte delantera del hombro)", "Inestabilidad anterior del hombro o daño del Labrum (la cápsula se vuelve laxa por el exceso de estiramiento en la tracción de la brazada)"], note: "Tener una mala técnica de nado (cruzar la línea media del cuerpo con la mano al entrar al agua) es el desencadenante técnico y biomecánico número uno." }, diagnosis: { title: "Evaluación Ortopédica y Deportiva", intro: "El médico especialista deportivo buscará aislar qué tendón se está pellizcando:", items: ["Examen físico con pruebas de provocación (como el test de Neer o de Hawkins, donde el doctor levanta y rota tu brazo para ver si se reproduce el dolor agudo y confirmar el pellizco)", "Ecografía articular de alta resolución (el examen de primera línea más rápido y eficaz para ver la inflamación del tendón, líquido de bursitis o pequeños desgarros)", "Resonancia Magnética (RM) (requerida para ver el cartílago profundo -labrum- y descartar roturas totales masivas de tendones que requieran cirugía)"], note: "" }, treatment: { title: "Recuperación y Corrección de Técnica", intro: "La recuperación requiere descansar el tendón dañado mientras se corrige el desequilibrio muscular:", subsections: [ { title: "Protocolo de Rehabilitación", items: ["Descanso deportivo inmediato de la natación (o usar aletas para nadar solo con piernas sin usar los brazos durante semanas)", "Fisioterapia especializada (el tratamiento de oro absoluto; enfocada en fortalecer los músculos fijadores de la escápula -trapecio inferior, romboides- y estirar el pecho y la cápsula posterior del hombro, para 'abrir' el espacio donde pasa el tendón)", "Modificación y corrección de la técnica de nado con un entrenador profesional (imprescindible para no recaer al volver al agua)", "Medicamentos AINEs (ibuprofeno) e hielo post-entrenamiento (para reducir la inflamación química)", "Inyecciones locales de corticoides (solo en casos de dolor resistente crónico)", "Cirugía artroscópica (raramente, solo si se ha producido un desgarro grave del tendón que no cicatriza y el paciente no puede ni levantar el brazo)"] } ], note: "Nadar ignorando y soportando el dolor en el hombro solo causará que el tendón pase de inflamado a desgarrado, terminando finalmente con una cirugía." }, whenToSeekHelp: { title: "¿Cuándo acudir al traumatólogo deportivo?", intro: "Debes salir del agua y pedir cita médica rápidamente si:", items: ["El dolor es agudo, punzante e insoportable y se presenta cada vez que tu brazo entra al agua o durante la fase de 'tirón'", "Tienes dolor sordo crónico en reposo, o te despiertas del dolor en la noche al acostarte sobre ese hombro", "Sientes debilidad obvia al levantar objetos fuera del agua, o tu brazo se 'cae' o pierde toda su fuerza de manera repentina", "Sientes que el hombro 'cruje' o tienes la sensación real de que la articulación se está saliendo o está muy laxa y suelta"] } },
'Artritis por gota crónica' : { intro: "La artritis gotosa crónica (gota tofácea crónica) es la etapa más avanzada, dolorosa y destructiva de la enfermedad de la gota. Ocurre en pacientes con niveles tóxicos de ácido úrico no controlados durante muchos años, causando deformidad articular permanente.", whatIs: { title: "¿Qué es la Gota Crónica?", text: "La gota inicial se presenta como ataques de dolor repentinos que desaparecen en días. Sin embargo, si la hiperuricemia (ácido úrico alto en la sangre) no se trata de raíz, los cristales microscópicos de urato dejan de ser temporales y se depositan permanentemente en grandes masas duras dentro y alrededor de las articulaciones, destruyendo el hueso y el cartílago irremediablemente." }, types: { title: "Características y Complicaciones", intro: "En esta fase, la enfermedad afecta profundamente la anatomía y órganos:", items: ["Aparición de Tofos (nódulos gruesos, bultos y tumores blancos o amarillentos de cristales puros bajo la piel, típicamente en dedos, codos, orejas y pies)", "Artritis erosiva continua (el dolor, la hinchazón y la rigidez articular ya no desaparecen entre ataques, convirtiéndose en un dolor sordo y de por vida)", "Daño renal grave y formación crónica de cálculos renales (piedras) masivos de ácido úrico que pueden derivar en insuficiencia renal"], note: "Llegar a la fase de gota crónica puede tomar entre 10 y 15 años de ataques de gota aguda mal tratados o mal medicados." }, diagnosis: { title: "Evaluación Reumatológica Avanzada", intro: "El diagnóstico confirma el daño estructural masivo causado por los cristales:", items: ["Análisis y extracción del líquido sinovial o biopsia de un tofo (el especialista extrae una muestra y observa bajo el microscopio polarizado la masiva presencia de cristales en forma de aguja)", "Análisis de sangre para ácido úrico y función renal (creatinina)", "Radiografías articulares (rayos X que revelan lesiones destructivas clásicas en 'sacabocados' donde el cristal ha carcomido o derretido el hueso)", "Ecografía articular o Tomografía Computarizada (TC) de doble energía (identifica visualmente la carga y depósitos de cristales de color verde brillante en el interior del cuerpo)"], note: "" }, treatment: { title: "Disolución de Tofos y Cirugía", intro: "El único objetivo es disolver estas rocas biológicas reduciendo el ácido úrico a niveles mínimos:", subsections: [ { title: "Manejo Farmacológico Intenso", items: ["Terapia reductora de urato de por vida (Altas dosis de Alopurinol o Febuxostat diarias; el objetivo innegociable es forzar el nivel de ácido úrico en sangre por debajo de 5.0 mg/dL para que los tofos se deshagan con los años)", "Pegloticasa (Krystexxa) (un medicamento muy potente administrado por goteo intravenoso en el hospital para los casos crónicos y refractarios severos; disuelve los tofos gigantescos de cristales que otros medicamentos no pueden destruir)", "Analgésicos crónicos (Colchicina diaria o AINEs para manejar el dolor sordo basal)", "Cirugía ortopédica destructiva (si los tofos se ulceran, se infectan, rompen tendones o deforman por completo las manos/pies y causan inmovilidad, el cirujano debe extirparlos o fusionar las articulaciones muertas)"] } ], note: "Sin un cambio dietético severo (quitar alcohol, cerveza, carne roja, vísceras y sirope de fructosa), las pastillas no funcionarán eficientemente." }, whenToSeekHelp: { title: "¿Cuándo es URGENTE ver a tu médico o cirujano?", intro: "La gota crónica requiere un seguimiento hiperestricto. Acude de urgencia si:", items: ["Tus tofos se han vuelto extremadamente grandes y te imposibilitan usar calzado, sostener un vaso o flexionar tus dedos y codos", "La piel sobre los bultos blancos (tofos) se rompe, se úlcera o comienza a supurar un material espeso blanco parecido a la tiza o a la pasta de dientes", "Los tofos rotos se vuelven calientes al tacto, muy rojos y la persona presenta fiebre o escalofríos (indica una infección bacteriana secundaria severa encima del tofo que puede causar una sepsis general)"] } },
'Tumor de la médula espinal' : { intro: "Un tumor de la médula espinal es una masa celular o crecimiento anormal de tejido que se desarrolla dentro de la médula espinal o a su alrededor, en las membranas y huesos de la columna vertebral. Son afecciones graves que, incluso siendo benignas, pueden causar parálisis y daño permanente por compresión física.", whatIs: { title: "¿Qué es un Tumor Espinal?", text: "Es un bulto patológico en el canal estrecho y cerrado de la columna. El peligro radica en la falta de espacio: a medida que el tumor (sea maligno canceroso o benigno inofensivo) crece, aplasta inexorablemente los vitales conductos nerviosos y vasos sanguíneos de la médula espinal, interrumpiendo las señales motoras (movimiento) y sensitivas del cuerpo entero." }, types: { title: "Ubicación Anatómica del Crecimiento", intro: "Su localización define su gravedad y las opciones quirúrgicas para sacarlo:", items: ["Tumores intramedulares (nacen dentro del tejido interno y blando de la propia médula espinal; como ependimomas o astrocitomas, son los más difíciles de extirpar sin dejar secuelas y daños)", "Tumores intradurales-extramedulares (crecen dentro del saco protector aracnoideo que recubre la médula, pero por fuera del cordón de nervios; frecuentemente son meningiomas o schwannomas, muchos son benignos)", "Tumores extradurales o óseos espinales (son los más comunes y destructivos; crecen en los huesos de las vértebras. En un 90% de los casos no son primarios, sino metástasis de otros cánceres (como mama, pulmón o próstata) que han viajado por la sangre y se han alojado en la columna espinal)"], note: "El dolor de espalda causado por un tumor espinal tiene una característica distintiva: suele empeorar gravemente durante la noche cuando el paciente está acostado en su cama en reposo." }, diagnosis: { title: "Diagnóstico Neurológico y de Imagen de Rescate", intro: "Detectarlos rápido es esencial para salvar la capacidad de caminar del paciente:", items: ["Resonancia Magnética (RM) con contraste intravenoso de la columna (el estudio supremo y absolutamente definitivo de mayor precisión; ilumina y resalta el tumor, la médula espinal y los minúsculos nervios aplastados al detalle)", "Tomografía Computarizada de la columna y el cuerpo completo (para observar detalladamente la destrucción del hueso vertebral, o buscar si hay un tumor principal en los pulmones o riñones)", "Biopsia de aguja o quirúrgica (vital para determinar el tipo celular exacto y si el tumor es un cáncer maligno para planificar la quimioterapia; a veces se hace simultáneamente mientras el cirujano opera para extirpar la masa)"], note: "" }, treatment: { title: "Neurocirugía y Oncología Especializada", intro: "El tratamiento requiere de una intervención agresiva y urgente en equipos médicos complejos:", subsections: [ { title: "Terapias Dirigidas", items: ["Dosis masivas de Corticosteroides intravenosos (como Dexametasona; dados inmediatamente en urgencias para desinflamar dramáticamente y disminuir el hinchazón del tejido nervioso y salvar la movilidad temporal de la médula espinal)", "Cirugía Neurológica de Extirpación (el objetivo supremo; los cirujanos utilizan sofisticados microscopios y neuromonitorización eléctrica en tiempo real para separar y sacar la masa de la médula intentando no tocar el tejido sano de los nervios)", "Radioterapia especializada (frecuentemente utilizada para los tumores inoperables en el centro medular, o tras la cirugía, para matar los restos de metástasis tumorales óseas, y también sirve como potente sedante de dolores terminales)", "Quimioterapia y terapia dirigida (usada especialmente según la agresividad del cáncer originario o tipos específicos de células)"] } ], note: "La cirugía espinal tumoral conlleva siempre un riesgo neurológico altísimo y requiere a menudo semanas de rehabilitación de marcha y física posoperatoria." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA y requiere llamar a la sala de emergencias o al 911?", intro: "Una médula aplastada muere de prisa. Debes ir al servicio hospitalario inmediato si presentas las 'Banderas Rojas':", items: ["Sientes una profunda debilidad y paralización rápida o la súbita pérdida motriz total en una o ambas de tus piernas o brazos (por ejemplo, te levantas de la cama o silla y tus piernas no responden, ceden o se doblan y colapsan)", "Padeces y sufres de repente una grave incontinencia e incontrolable falta o cese de control en los movimientos para orinar en la vejiga o tus intestinos (o por el contrario, retención extrema total)", "Padeces o sientes de súbito entumecimiento 'en silla de montar' (pérdida aguda grave de sensación en los glúteos, el ano, y cara interna de entre los muslos)", "Presentas un dolor en la columna o la espalda que es crónico, sordo y que es horriblemente peor al tumbarte a dormir en la cama y nunca es aliviado con ibuprofeno"] } },
'Trastorno de pánico' : { intro: "El trastorno de pánico es una condición psiquiátrica de ansiedad caracterizada por ataques de pánico (o crisis de angustia) frecuentes, súbitos e intensos. Estos episodios aterradores vienen acompañados de síntomas físicos tan severos que la persona siente un pavor real e inminente de morir o perder la razón.", whatIs: { title: "¿Qué es el Trastorno de Pánico?", text: "Es la activación errónea de la alarma de supervivencia del cerebro. El sistema de 'lucha o huida' inunda el cuerpo con adrenalina pura sin que exista ningún peligro real o desencadenante externo evidente. Lo que convierte esto en un 'trastorno' no es solo tener un ataque aislado, sino vivir en un miedo anticipatorio constante y obsesivo sobre cuándo y dónde atacará la próxima crisis." }, types: { title: "Manifestaciones y Complicaciones", intro: "Los ataques son abrumadores y a menudo originan trastornos secundarios:", items: ["El ataque de pánico típico (alcanza su punto máximo de terror paralizante en unos 10 minutos e incluye taquicardia desbocada, asfixia, sudoración fría, temblores violentos, náuseas, y sensación de desrealización -sentir que no estás en tu cuerpo-)", "Agorafobia (una complicación gravísima que afecta a 1 de cada 3 pacientes; desarrollan tanto terror a tener un ataque en público o donde sea difícil recibir ayuda -como supermercados, puentes o cines- que terminan por no salir nunca de su casa)"], note: "Muchas personas visitan repetidamente las salas de urgencias en ambulancia creyendo que están sufriendo un infarto cardíaco letal, y todos sus exámenes salen perfectos." }, diagnosis: { title: "Evaluación Psiquiátrica y Exclusión Médica", intro: "El diagnóstico requiere descartar exhaustivamente problemas físicos primero:", items: ["Examen físico completo y electrocardiograma -ECG- (el médico debe asegurarse absolutamente de que el corazón esté sano y de que los síntomas de pecho no sean por arritmias o infartos reales)", "Análisis de sangre para perfil tiroideo (un problema de la glándula de tiroides hiperactiva causa síntomas idénticos de taquicardia y pánico biológico)", "Evaluación psicológica extensa con base en los criterios médicos del DSM-5 (el paciente experimenta ataques de repetición, e invierte al menos 1 mes modificando sus conductas vitales para evitar que vuelvan a suceder)"], note: "" }, treatment: { title: "Control, Medicación y Reeducación Cognitiva", intro: "Es altamente tratable; el objetivo es que el paciente recupere la normalidad de su vida sin miedo:", subsections: [ { title: "Terapias Fundamentales", items: ["Terapia Cognitivo-Conductual (TCC) (es el tratamiento más exitoso de todos; enseña a la persona a reinterpretar la inofensividad de los síntomas físicos y emplea la Terapia de Exposición para simular hiperventilaciones o taquicardias y perderles el miedo lentamente)", "Medicamentos Antidepresivos ISRS y los IRSN (como Sertralina, Fluoxetina o Venlafaxina; se toman diariamente como preventivos y bajan enormemente el volumen de excitabilidad y reactividad de la amígdala cerebral, erradicando los ataques a lo largo de las semanas)", "Medicamentos Ansiolíticos o Benzodiacepinas (como el Alprazolam o Lorazepam; medicamentos potentes usados únicamente como píldoras de rescate para uso de muy corto plazo cuando el pánico extremo se presenta, debido a su alto poder adictivo)"] } ], note: "Huir o evitar constantemente los lugares donde ocurrió un ataque solo fortalece inmensamente a la fobia y al propio pánico para el futuro." }, whenToSeekHelp: { title: "¿Cuándo buscar ayuda terapéutica especializada?", intro: "Intervenir tempranamente es la clave antes de que la agorafobia paralice la vida. Pide cita si:", items: ["Experimentas ataques de miedo súbito e intenso acompañados de opresión y dolor en el pecho, asfixia, temblores y sudor", "Has dejado de hacer cosas que antes disfrutabas, evitas utilizar transportes públicos, o dejas de ir al supermercado por terror absoluto a padecer un ataque en dichos sitios", "Te encuentras obsesionado y angustiado y el miedo domina todas las facetas sobre '¿Qué pasará?' en la inminencia de tu próximo ataque", "Sientes que el miedo prolongado e incontrolable te ha empezado a ocasionar gran tristeza depresiva o recurres al alcohol y otras sustancias y drogas nocivas para tranquilizar de alguna manera la ansiedad severa subyacente de tus nervios"] } },
'Enfermedad de Hirschsprung' : { intro: "La enfermedad de Hirschsprung es una grave afección y malformación congénita, detectada habitualmente en recién nacidos, que afecta el intestino grueso (el colon) y ocasiona dificultades severas y letales para el paso de las heces.", whatIs: { title: "¿Qué es esta Enfermedad Intestinal?", text: "Ocurre debido a una malformación durante el desarrollo fetal. Las células nerviosas (ganglionares) que controlan los movimientos musculares rítmicos del intestino nunca terminan de formarse en el tramo final del colon o el recto. Sin estos nervios, esa porción del intestino está paralizada o constantemente contraída, deteniendo el avance de las heces. Esto causa un bloqueo masivo y destructivo, distendiendo enormemente el intestino sano que queda por encima (megacolon tóxico)." }, types: { title: "Extensión de la Carencia de Nervios", intro: "Se clasifica por la longitud del segmento intestinal sin nervios:", items: ["Segmento corto (representa el 80% de los casos; la falta de nervios se limita al recto y a la parte inferior del colon sigmoide)", "Segmento largo (la carencia nerviosa abarca porciones mucho más extensas del colon)", "Aganglionosis colónica total (muy rara; afecta a todo el intestino grueso y a veces a parte del delgado)"], note: "Es más frecuente en niños varones y tiene una fuerte asociación con trastornos genéticos como el Síndrome de Down." }, diagnosis: { title: "Detección Neonatal y Quirúrgica", intro: "El pediatra o cirujano empleará pruebas específicas ante la sospecha de obstrucción:", items: ["Biopsia rectal (el 'estándar de oro'; el cirujano extrae un diminuto fragmento del revestimiento del recto para confirmar bajo el microscopio la ausencia total de células nerviosas ganglionares)", "Radiografía abdominal con enema de contraste (se introduce bario por el ano para visualizar en rayos X la zona estrecha y enferma, y la zona superior masivamente dilatada)", "Manometría anorrectal (se infla un pequeño globo en el recto para medir los reflejos de los músculos del esfínter)"], note: "" }, treatment: { title: "Corrección Quirúrgica Definitiva", intro: "Esta enfermedad siempre requiere cirugía para salvar la vida del paciente:", subsections: [ { title: "Fases del Procedimiento", items: ["Cirugía de 'descenso' (pull-through): El cirujano pediátrico extirpa la parte del colon que no tiene nervios y empuja (desciende) la parte sana del intestino conectándola directamente al ano.", "Cirugía en dos etapas con colostomía (si el niño está muy enfermo o el intestino está muy inflamado, primero se realiza una colostomía temporal para que el intestino sane, y meses después se realiza la cirugía de descenso definitiva).", "Cuidados postoperatorios (entrenamiento intestinal y manejo de dieta, ya que los niños operados pueden seguir sufriendo episodios de estreñimiento o incontinencia)."] } ], note: "Incluso después de la cirugía exitosa, los niños tienen un riesgo alto de desarrollar enterocolitis (una inflamación del intestino grave)." }, whenToSeekHelp: { title: "¿Cuándo es una emergencia en el recién nacido o bebé?", intro: "El diagnóstico y tratamiento deben ser muy rápidos. Acude a urgencias o al pediatra si el bebé:", items: ["No expulsa su primer excremento (el meconio oscuro) dentro de las primeras 48 horas de vida", "Tiene el vientre inusualmente hinchado y duro (distensión abdominal severa)", "Vomita líquido de color verde brillante (vómito bilioso, signo claro de obstrucción intestinal total)", "Presenta fiebre, diarrea fétida o letargo extremo (signos de enterocolitis)"] } },
'Arterioesclerosis' : { intro: "La arterioesclerosis es una afección vascular progresiva en la que las paredes de las arterias se endurecen, engruesan y pierden su elasticidad, dificultando el flujo normal de la sangre a través del cuerpo.", whatIs: { title: "¿Qué es la Arterioesclerosis?", text: "Es un término general que abarca varias enfermedades en las que los vasos sanguíneos que transportan el oxígeno pierden su flexibilidad. La forma más común e importante es la 'Aterosclerosis', que implica la acumulación de placas pegajosas de grasa y colesterol en las paredes de las arterias, estrechándolas hasta bloquear el paso de la sangre." }, types: { title: "Tipos y Clasificaciones", intro: "Existen tres formas principales de arterioesclerosis:", items: ["Aterosclerosis (la más letal y común; formación de placas de grasa en las arterias medianas y grandes, como las del corazón y cerebro)", "Arteriosclerosis de Mönckeberg (endurecimiento y calcificación de la capa media de las arterias, común en personas mayores pero que no suele obstruir el flujo)", "Arterioloesclerosis (engrosamiento de las arterias muy pequeñas, frecuentemente causado por la hipertensión crónica o la diabetes)"], note: "Esta condición es la causa subyacente principal de la gran mayoría de los ataques cardíacos y derrames cerebrales en el mundo." }, diagnosis: { title: "Evaluación del Riesgo Cardiovascular", intro: "El diagnóstico busca detectar la placa de colesterol antes de que bloquee totalmente la arteria:", items: ["Análisis de sangre en ayunas (para medir el colesterol total, LDL, HDL, triglicéridos y azúcar en sangre)", "Electrocardiograma (ECG) y Prueba de Esfuerzo (para ver si el corazón sufre isquemia por arterias estrechas al hacer ejercicio)", "Ecografía Doppler (para evaluar el flujo de sangre en las arterias de las piernas o el cuello)", "Tomografía Computarizada (TC) de calcio coronario (mide la cantidad de calcio en las placas de las arterias del corazón)"], note: "" }, treatment: { title: "Modificación de Vida y Fármacos", intro: "El daño no se puede revertir por completo, pero se puede detener su avance y prevenir trombos:", subsections: [ { title: "Intervenciones Preventivas y Quirúrgicas", items: ["Cambios estrictos y radicales en la dieta (abandonar grasas trans y azúcares), dejar el tabaco por completo y hacer ejercicio aeróbico frecuente", "Medicamentos para el colesterol (las Estatinas son el pilar para estabilizar las placas y evitar que se rompan)", "Medicamentos antihipertensivos y anticoagulantes (como la aspirina diaria) para prevenir infartos", "Intervención quirúrgica (Angioplastia con stent para abrir arterias bloqueadas mecánicamente, o Cirugía de Bypass si el bloqueo es masivo e inoperable de otra forma)"] } ], note: "La ateroesclerosis no produce síntomas durante décadas hasta que la arteria se estrecha más del 70% o la placa se rompe bruscamente." }, whenToSeekHelp: { title: "¿Cuándo es URGENCIA VITAL (Llamar al 911)?", intro: "La arterioesclerosis silenciosa se manifiesta a través de sus complicaciones letales. Pide una ambulancia de inmediato si sientes:", items: ["Dolor o fuerte presión aplastante en el pecho, que se irradia a la mandíbula o brazo izquierdo (Ataque al corazón)", "Entumecimiento repentino en la cara, brazo o pierna, y dificultad brusca para hablar o entender (Derrame cerebral isquémico)", "Un dolor agudo e insoportable en una pierna, que de repente se vuelve pálida y fría (Isquemia aguda de extremidad)"] } },
'Dolor de hombro' : { intro: "El dolor de hombro es una queja traumatológica sumamente frecuente que abarca cualquier tipo de molestia o incapacidad funcional que afecte a la articulación del hombro o a los músculos, ligamentos y tendones que la rodean.", whatIs: { title: "¿Qué origina el dolor de hombro?", text: "El hombro (la articulación glenohumeral) es la articulación con mayor rango de movimiento del cuerpo, lo que la hace altamente inestable y propensa al desgaste. El dolor suele derivar de daños en el 'manguito rotador' (el grupo de músculos que mantiene el hueso en su lugar), inflamación de las bolsas de líquido (bursas) o desgaste de los huesos por artritis." }, types: { title: "Patologías Causantes más Frecuentes", intro: "Las causas se dividen por el tipo de tejido afectado:", items: ["Patología del Manguito Rotador (tendinitis o desgarros parciales/totales de los tendones, causa dolor al levantar el brazo)", "Bursitis subacromial (inflamación aguda de la bolsa lubricante del hombro)", "Hombro congelado o capsulitis (una rigidez progresiva y paralizante de toda la articulación)", "Inestabilidad o dislocación (cuando la cabeza del hueso se sale de su cavidad por un golpe)", "Osteoartritis (desgaste y destrucción crónica del cartílago protector con la edad)"], note: "El dolor que se siente en el hombro pero que empeora al mover el cuello podría ser un dolor referido de una hernia de disco cervical." }, diagnosis: { title: "Examen Ortopédico de Rango de Movimiento", intro: "El médico traumatólogo debe evaluar qué movimiento exacto produce el fallo:", items: ["Examen físico (el médico moverá tu brazo en varias direcciones para comprobar si el problema es de rigidez o de debilidad del tendón)", "Radiografías de rayos X (siempre el primer paso para descartar artrosis, fracturas o espolones óseos)", "Ecografía articular (rápida y eficaz para ver tendones inflamados o líquido en la bursa)", "Resonancia Magnética (RM) (el estudio definitivo para confirmar desgarros musculares o lesiones en el cartílago profundo -labrum-)"], note: "" }, treatment: { title: "Terapia Física o Cirugía de Reparación", intro: "Dependiendo del daño, el enfoque va del reposo al quirófano:", subsections: [ { title: "Protocolo de Acción", items: ["Reposo relativo y modificación de la actividad (evitar levantar peso o hacer movimientos por encima de la cabeza)", "Fisioterapia constante (la cura más efectiva para la mayoría de los casos, para fortalecer los músculos alrededor de la articulación)", "AINEs y medicación antiinflamatoria (como el ibuprofeno, en periodos cortos)", "Infiltraciones (inyecciones de corticoides directamente en la articulación para desinflamación rápida y potente)", "Cirugía artroscópica (si el tendón está roto por completo y el paciente es activo, o para raspar hueso artrósico)"] } ], note: "Ignorar el dolor de hombro y seguir forzándolo puede convertir una simple inflamación en un desgarro irreparable del tendón." }, whenToSeekHelp: { title: "¿Cuándo acudir a urgencias ortopédicas?", intro: "No esperes a que el dolor pase si hay señales de daño estructural mayor:", items: ["Sufres una caída o golpe fuerte y tu hombro parece visiblemente deformado, desencajado o escuchaste un fuerte chasquido (dislocación o fractura)", "El dolor es tan agudo que te impide por completo mover o despegar el brazo de tu cuerpo", "Sientes debilidad repentina e inusual al intentar sostener un objeto liviano", "El brazo, mano o dedos se sienten profundamente entumecidos, fríos o con 'hormigueo' constante"] } },
'Hernia crural' : { intro: "Una hernia crural (o hernia femoral) ocurre cuando una porción de tejido, generalmente grasa o un pequeño segmento de intestino, se empuja a través de un punto débil en la pared muscular del abdomen y baja hacia el canal femoral, en la zona de la ingle y la parte superior del muslo.", whatIs: { title: "¿Qué es una Hernia Crural?", text: "A diferencia de las hernias inguinales (mucho más comunes y que ocurren más arriba), las hernias crurales se sitúan justo debajo del pliegue de la ingle, en el canal por donde pasan los vasos sanguíneos grandes hacia la pierna. Debido a que este canal es extremadamente estrecho y rígido, estas hernias tienen un altísimo riesgo de quedar 'estranguladas', cortando el flujo de sangre al intestino atrapado." }, types: { title: "Diferenciación y Factores de Riesgo", intro: "Tienen características que las hacen únicas e identificables:", items: ["Son mucho más frecuentes en mujeres mayores (debido a la estructura más ancha de la pelvis femenina)", "Frecuentemente se confunden con hernias inguinales o con ganglios linfáticos inflamados en la ingle", "Suelen ser pequeñas y a menudo no causan un bulto visible hasta que ocurre una complicación grave", "Factores de riesgo: obesidad, tos crónica, esfuerzo crónico al ir al baño o embarazos múltiples que debilitan la zona pélvica"], note: "Debido al alto riesgo de estrangulamiento, los médicos recomiendan operar casi todas las hernias crurales en cuanto se detectan." }, diagnosis: { title: "Examen Físico y Pruebas de Imagen", intro: "El cirujano evaluará el bulto en la ingle para determinar qué tipo de hernia es:", items: ["Examen físico en camilla y de pie (el médico te pedirá que tosas o pujes para ver si el bulto protruye en el pliegue del muslo)", "Ecografía de la región inguinal (la prueba más rápida y precisa para confirmar si el bulto es una hernia, y si contiene intestino o solo grasa)", "Tomografía Computarizada (TC) (se usa si hay sospechas de que el intestino ya está bloqueado o atrapado)"], note: "" }, treatment: { title: "Corrección Quirúrgica Necesaria", intro: "A diferencia de otras hernias pequeñas que se pueden 'vigilar', las crurales requieren casi siempre reparación con bisturí:", subsections: [ { title: "Opciones Quirúrgicas", items: ["Cirugía abierta de hernia (el cirujano hace una incisión en la ingle, empuja el intestino o tejido de vuelta al abdomen y repara la debilidad del canal cosiendo una malla sintética de refuerzo)", "Cirugía laparoscópica (mínimamente invasiva, se realizan pequeños agujeros y se inserta una cámara y herramientas para colocar la malla desde dentro; la recuperación es más rápida)"] } ], note: "No existen fajas ni ejercicios que puedan curar o hacer retroceder una hernia crural." }, whenToSeekHelp: { title: "¿Cuándo ir directamente al Hospital por Riesgo Vital?", intro: "Una hernia que se 'estrangula' provoca la muerte del intestino en cuestión de horas. Ve a URGencias inmediatamente si:", items: ["El bulto de la ingle se vuelve repentinamente muy doloroso, firme, duro al tacto y no se puede volver a empujar hacia adentro (hernia encarcelada)", "La piel sobre el bulto se vuelve de color rojo oscuro o morado", "Presentas síntomas de obstrucción intestinal aguda: náuseas severas, vómitos repetitivos y no puedes expulsar gases ni defecar", "Aparece fiebre alta o escalofríos repentinos"] } },
'Infecciones frecuentes de garganta' : { intro: "Las infecciones frecuentes de garganta, médicamente denominadas faringoamigdalitis recurrente, implican episodios repetitivos de inflamación severa e infección en la faringe y, de manera muy característica, en las amígdalas palatinas.", whatIs: { title: "¿Qué son las Infecciones Frecuentes de Garganta?", text: "Las amígdalas son masas de tejido linfático situadas a ambos lados de la parte posterior de la garganta. Actúan como la primera línea de defensa del sistema inmunológico, atrapando gérmenes que entran por la boca y la nariz. Sin embargo, en algunas personas (especialmente niños en edad escolar y adolescentes), estas amígdalas se ven superadas y se convierten en el problema mismo: sus profundas grietas (criptas) albergan colonias crónicas de bacterias que el cuerpo no puede erradicar por completo, lo que desencadena un ciclo interminable de infecciones dolorosas mes tras mes." }, symptoms: { title: "Síntomas de un Episodio Agudo", intro: "Durante cada recaída de faringoamigdalitis, los síntomas típicos incluyen:", groups: [ { name: "Síntomas Locales y Sistémicos", items: ["Dolor de garganta agudo, intenso y punzante que hace que tragar saliva, líquidos o comida sea casi intolerable (odinofagia)", "Amígdalas visiblemente inflamadas, enrojecidas y a menudo cubiertas por placas blancas, pus amarillento o una película grisácea", "Inflamación y gran sensibilidad en los ganglios linfáticos del cuello y debajo de la mandíbula", "Fiebre alta, a menudo con inicio repentino y escalofríos", "Mal aliento muy marcado (halitosis) debido a la acumulación de bacterias y pus en las criptas", "Dolor de cabeza, malestar estomacal y fatiga general"] } ], warning: "Si una infección parece localizarse masivamente en un solo lado de la garganta, empujando la úvula (campanilla) hacia el lado opuesto, causando dificultad extrema para abrir la boca y tragar saliva, puede ser un Absceso Periamigdalino (una bolsa de pus profunda que requiere drenaje de emergencia por un otorrino)." }, types: { title: "Causas y Agentes Patógenos", intro: "Las infecciones pueden ser virales, pero la repetición crónica severa suele ser bacteriana:", items: ["Bacterias (El culpable principal): El Estreptococo del grupo A (Streptococcus pyogenes) es responsable de las amigdalitis bacterianas más severas y recurrentes. Si no se erradica por completo, puede formar 'biopelículas' resistentes dentro de las amígdalas.", "Virus: Epstein-Barr (mononucleosis), adenovirus o rinovirus. Suelen venir con síntomas de resfriado (tos, congestión), mientras que el estreptococo casi nunca da tos.", "Factores anatómicos: Amígdalas muy grandes y con cráteres profundos (amígdalas crípticas) que atrapan restos de comida y bacterias.", "Ambiente: Alta exposición en escuelas y guarderías (efecto ping-pong de contagio)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para evitar el abuso de antibióticos, es crítico determinar si la causa de la recurrencia es bacteriana:", items: ["Prueba rápida de detección de antígenos para Estreptococo (Hisopado faríngeo): El médico frota un hisopo en las amígdalas para detectar la bacteria en 10 minutos.", "Cultivo de exudado faríngeo: Si la prueba rápida es negativa pero la sospecha clínica es alta, la muestra se envía al laboratorio para que las bacterias crezcan (tarda 48 horas).", "Criterios clínicos de recurrencia: Se documenta la frecuencia. Se considera patológico tener 7 episodios en el último año, o 5 episodios anuales en los últimos dos años consecutivos."], note: "Los episodios virales recurrentes no se curan con antibióticos y solo requieren medidas de alivio sintomático." }, treatment: { title: "Tratamientos", intro: "El objetivo es detener los episodios agudos y, si la calidad de vida está destruida, eliminar la fuente del problema:", subsections: [ { title: "Manejo Médico y Quirúrgico", items: ["Antibióticos (Penicilina o Amoxicilina): Son la única cura si la prueba de estreptococo es positiva. Deben tomarse durante 10 días completos sin interrupción para erradicar la bacteria y evitar complicaciones graves como la Fiebre Reumática (que daña el corazón).", "Analgésicos y antipiréticos: Ibuprofeno o Paracetamol para el dolor y la fiebre.", "Amigdalectomía (Extirpación quirúrgica de las amígdalas): Si el niño o adulto cumple los criterios de frecuencia extrema (más de 7 veces en un año), si las infecciones causan convulsiones febriles, si el tamaño de las amígdalas asfixia al paciente por la noche (apnea del sueño), o si ha habido un absceso periamigdalino, el otorrinolaringólogo recomendará extirparlas quirúrgicamente. Bajo anestesia general, se retiran las amígdalas, terminando permanentemente con el ciclo de infecciones."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o a tu médico si presentas:", items: ["Dificultad evidente para respirar o tragar, llegando al punto en que babeas por no poder pasar tu propia saliva", "Fiebre superior a 39°C (102.2°F) que no cede con analgésicos", "Un dolor de garganta extremadamente fuerte que se concentra solo en un lado del cuello (sospecha de absceso)", "Tus hijos están tomando antibióticos mes a mes sin una resolución a largo plazo"] } },
'Acalasia esofágica' : { intro: "La acalasia esofágica es un trastorno motor neuromuscular primario, raro e incurable del esófago, el tubo muscular que transporta los alimentos desde la garganta hasta el estómago.", whatIs: { title: "¿Qué es la Acalasia?", text: "Para tragar normalmente, los músculos del esófago deben contraerse en forma de ondas (peristaltismo) para empujar la comida hacia abajo, y el anillo muscular inferior (esfínter esofágico inferior o EEI) debe relajarse para abrir la puerta al estómago. En la acalasia, los nervios que controlan este proceso mueren o se degeneran. El esófago queda paralizado y no puede empujar la comida, y lo que es peor, el esfínter inferior se queda contraído permanentemente y se niega a abrirse. Como resultado, la comida, los líquidos y la saliva se atascan y se pudren en un esófago cada vez más estirado y dilatado, sin poder llegar al estómago." }, symptoms: { title: "Síntomas y Alertas Clásicas", intro: "Los síntomas se desarrollan muy lentamente, a menudo a lo largo de meses o años:", groups: [ { name: "Síntomas Digestivos y Asfixiantes", items: ["Disfagia: Dificultad progresiva e innegable para tragar. Curiosamente, a los pacientes a menudo les resulta más difícil tragar líquidos fríos y sólidos blandos que otros alimentos, sintiendo que la comida se atasca firmemente a la altura del pecho.", "Regurgitación de comida no digerida: Devolver comida o saliva retenida horas después de haber comido, sin sabor ácido (ya que la comida nunca llegó al estómago).", "Pérdida de peso drástica, desnutrición y miedo psicológico a comer.", "Dolor o presión fuerte en el pecho que puede confundirse con un ataque cardíaco.", "Tos nocturna persistente o asfixia en la cama: Al acostarse plano, el contenido podrido atrapado en el esófago sube y se derrama en los pulmones, provocando aspiración y riesgo de neumonía.", "Acidez estomacal crónica que no mejora en absoluto con pastillas antiácidas (a menudo mal diagnosticada como reflujo ERGE)."] } ], warning: "La regurgitación nocturna no solo arruina el sueño y la calidad de vida, sino que el riesgo de micro-aspirar alimentos hacia los pulmones puede causar infecciones respiratorias fatales. Además, el estancamiento crónico de alimentos eleva el riesgo de desarrollar cáncer de esófago a largo plazo." }, types: { title: "Causas y Origen Neurológico", intro: "El daño es el resultado de la destrucción de las células nerviosas, provocado por:", items: ["Idiopática: En la mayoría de los casos mundiales, la causa es un misterio absoluto. Se sospecha una respuesta autoinmune, donde el cuerpo ataca y destruye los ganglios nerviosos del propio esófago, posiblemente desencadenado por una infección viral inofensiva previa.", "Enfermedad de Chagas: En Centro y Sudamérica, la infección por el parásito *Trypanosoma cruzi* destruye directamente los nervios de los órganos huecos, provocando un cuadro idéntico a la acalasia clásica (así como dilatación del colon y corazón).", "Pseudoacalasia: Rara vez, un cáncer de estómago infiltrante u otros tumores malignos pueden estrangular el esfínter esofágico, simulando perfectamente los síntomas de la acalasia."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamental realizar pruebas funcionales y visuales, ya que suele confundirse erróneamente con simple reflujo:", items: ["Manometría Esofágica: La prueba de oro y la más precisa e importante. Se introduce un tubo fino con sensores de presión a través de la nariz hasta el estómago. El paciente traga agua y la máquina mide la fuerza de las contracciones. En la acalasia, confirma la parálisis de las ondas y que el esfínter inferior no se relaja al tragar.", "Tránsito Esofágico con Bario (Radiografía): El paciente traga un líquido de contraste espeso (bario). En la radiografía, el médico observa un esófago inmensamente dilatado por el líquido acumulado, y un final que termina en un hilo muy fino y estrecho, dando la clásica imagen radiológica en 'pico de pájaro' o 'punta de lápiz'.", "Endoscopia Superior (Gastroscopia): Fundamental para descartar cáncer. Se ve el esófago dilatado y el tubo de la cámara encuentra resistencia o un salto al intentar atravesar el esfínter hacia el estómago."], note: "" }, treatment: { title: "Tratamientos", intro: "No existe cura que devuelva el movimiento muscular al esófago. Todos los tratamientos son mecánicos y buscan destruir, relajar o cortar a la fuerza la válvula inferior (EEI) para que la gravedad permita que la comida caiga al estómago:", subsections: [ { title: "Terapias Endoscópicas y Quirúrgicas (Definitivas)", items: ["Miotomía Endoscópica Transoral (POEM): La técnica moderna y preferida. Sin cortes externos en el abdomen, el cirujano inserta un endoscopio por la boca, crea un túnel dentro del revestimiento de la pared del esófago y corta de arriba abajo los músculos del esfínter paralizado. Es altamente exitosa y la recuperación es rápida.", "Miotomía de Heller Laparoscópica: El enfoque quirúrgico clásico. A través de pequeños orificios en el abdomen, el cirujano corta las fibras musculares externas del esfínter esofágico inferior. Como destruir la válvula causará reflujo ácido masivo, siempre se acompaña de una 'funduplicatura' (envolver el estómago alrededor del esófago para crear una barrera antirreflejo suave).", "Dilatación Neumática: El gastroenterólogo introduce un globo resistente desinflado en el esfínter durante una endoscopia y lo infla violentamente para desgarrar y romper a la fuerza las fibras musculares cerradas. A menudo requiere repetirse a lo largo de los años y conlleva un pequeño riesgo de perforar el esófago."] }, { title: "Tratamientos Médicos (Soporte Temporal)", items: ["Inyección de Toxina Botulínica (Botox): Se inyecta Botox en el esfínter durante una endoscopia para paralizar el músculo estresado y que se abra. El efecto dura solo de 3 a 6 meses. Se reserva estrictamente para personas muy ancianas o frágiles que no sobrevivirían a la cirugía o la dilatación."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita de inmediato una evaluación por gastroenterología si:", items: ["Sientes que la comida sólida y los líquidos se te atascan sistemáticamente detrás del esternón al tragar", "Regurgitas comida no digerida hacia tu boca horas después de haber comido, o te despiertas asfixiándote y tosiendo con comida o saliva en la garganta durante la noche", "Has perdido peso significativamente y tienes miedo o ansiedad a la hora de sentarte a comer por miedo a ahogarte"] } },
'Reflujo vesicoureteral' : { intro: "El reflujo vesicoureteral (RVU) es el flujo anormal de orina que retrocede desde la vejiga hacia los conductos (uréteres) y, frecuentemente, hasta los riñones. Es una condición diagnosticada comúnmente en bebés y niños pequeños.", whatIs: { title: "¿Qué es el Reflujo Vesicoureteral?", text: "Normalmente, la orina fluye en una sola dirección: de los riñones, bajando por los uréteres, hacia la vejiga. Un mecanismo de válvula unidireccional evita que la orina retroceda. En el RVU, esta válvula es defectuosa o no se cierra por completo. Esto permite que la orina estancada regrese hacia los riñones. El peligro principal es que si la orina en la vejiga contiene bacterias (una infección), estas bacterias viajarán directamente a los riñones, causando infecciones renales graves (pielonefritis) que pueden dejar cicatrices permanentes y dañar la función renal." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "El RVU por sí mismo no causa dolor ni síntomas visibles. Generalmente se descubre solo cuando el niño desarrolla una infección del tracto urinario (IVU). Los síntomas de una IVU en niños incluyen:", groups: [ { name: "Síntomas Infecciosos en Bebés y Niños", items: ["Fiebre alta, a menudo sin otra causa obvia (como un resfriado)", "Irritabilidad extrema, llanto inexplicable y falta de apetito", "Vómitos o diarrea", "Orina turbia, con mal olor o presencia de sangre", "En niños mayores: dolor al orinar, necesidad urgente de ir al baño, dolor en el abdomen o en un costado (espalda baja)"] } ], warning: "Una fiebre alta en un bebé pequeño o recién nacido es una emergencia y debe ser evaluada de inmediato, ya que las infecciones renales recurrentes por RVU pueden causar insuficiencia renal crónica o presión arterial alta en la vida adulta." }, types: { title: "Tipos y Causas", intro: "Se divide en dos categorías según su origen:", items: ["RVU Primario: Es el tipo más común. El niño nace con un defecto congénito en la válvula donde el uréter entra en la vejiga. A medida que el niño crece y la vejiga madura, el defecto a menudo se corrige por sí solo.", "RVU Secundario: Ocurre cuando hay un bloqueo anatómico o un daño en los nervios de la vejiga que impide que se vacíe correctamente. La presión empuja la orina hacia arriba (común en condiciones como la espina bífida o válvulas de uretra posterior)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere pruebas de imagen especializadas para visualizar el flujo de la orina:", items: ["Ecografía renal y vesical: La primera prueba para evaluar si los riñones están dilatados o tienen cicatrices.", "Cistouretrografía miccional seriada (CUMS): La prueba de oro y obligatoria para confirmar el RVU. Se introduce un líquido de contraste en la vejiga a través de una sonda y se toman radiografías mientras la vejiga se llena y mientras el niño orina, mostrando si el líquido retrocede a los riñones.", "Gammagrafía renal (DMSA o MAG3): Para verificar si las infecciones pasadas han dejado cicatrices permanentes o daño en la función de los riñones."], note: "El RVU se clasifica en grados del I al V. El Grado I es leve (el reflujo solo llega al uréter), mientras que el Grado V es severo (uréteres severamente dilatados y torcidos con reflujo hasta el riñón)." }, treatment: { title: "Tratamientos", intro: "El enfoque depende del grado del RVU y la edad del niño. Muchos casos leves se curan solos al crecer:", subsections: [ { title: "Manejo Médico y Quirúrgico", items: ["Espera vigilante: Para grados bajos (I, II y algunos III). El médico monitorea al niño y trata rápidamente cualquier infección que aparezca, esperando que la válvula madure y se cierre con la edad.", "Antibióticos Profilácticos: Dosis muy bajas de antibióticos administradas diariamente para prevenir que las bacterias se multipliquen en la orina estancada, evitando así las infecciones renales mientras se espera que el RVU desaparezca.", "Inyección endoscópica (Deflux): Procedimiento ambulatorio mínimamente invasivo. El urólogo inyecta un gel especial en la pared de la vejiga cerca de la abertura del uréter para crear un bulto que actúa como una nueva válvula.", "Reimplantación Ureteral (Cirugía Abierta o Robótica): Para RVU severo (grados IV y V) o si el niño sigue teniendo infecciones a pesar de los antibióticos. El cirujano desconecta el uréter y lo vuelve a conectar a la vejiga creando un túnel más largo que funciona como una válvula antirreflujo perfecta."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu pediatra de inmediato si tu hijo:", items: ["Tiene fiebre inexplicable y sin otros síntomas de resfriado, especialmente si es menor de 2 años", "Se queja de dolor intenso al orinar o dolor en la espalda baja", "Tiene infecciones urinarias repetitivas (más de una vez en un año)"] } },
'Insuficiencia en el crecimiento' : { intro: "La insuficiencia en el crecimiento, a menudo llamada 'retraso del desarrollo' (Failure to Thrive, en inglés), es un término médico general utilizado para describir a bebés y niños cuyo peso, o la velocidad a la que aumentan de peso, está significativamente por debajo de lo esperado para su edad y sexo.", whatIs: { title: "¿Qué es la Insuficiencia en el Crecimiento?", text: "No es una enfermedad específica en sí misma, sino un síntoma crítico de desnutrición crónica. Ocurre cuando un niño no recibe, no puede retener o no puede utilizar las calorías y nutrientes necesarios para crecer y desarrollarse biológicamente. Durante los primeros tres años de vida, el cerebro y el cuerpo humano crecen a una velocidad asombrosa. Si este proceso se ve interrumpido de manera prolongada por falta de energía, puede provocar daños a largo plazo o irreversibles en el desarrollo cognitivo (intelectual), motor y emocional del niño." }, symptoms: { title: "Síntomas y Patrones de Alarma", intro: "El pediatra lo diagnostica trazando medidas en una curva de crecimiento. Los signos visibles incluyen:", groups: [ { name: "Signos Físicos y de Comportamiento", items: ["Peso que cae drásticamente, cruzando dos o más líneas percentilares principales en la gráfica de crecimiento del pediatra (por ejemplo, caer del percentil 50 al percentil 10)", "Peso constantemente por debajo del tercer o quinto percentil para su edad", "En etapas avanzadas, el crecimiento en longitud (estatura) y el tamaño de la cabeza (perímetro cefálico) también se detienen", "Retrasos evidentes en el desarrollo físico y motor (tardan mucho en darse la vuelta, sentarse o caminar)", "Falta de interés en su entorno, apatía, cansancio extremo o irritabilidad inusual", "Ausencia de llanto, expresión facial plana, o falta de respuesta al contacto visual o a las sonrisas"] } ], warning: "Si no se interviene, la desnutrición severa afecta el crecimiento del cerebro. Un bebé que pierde peso de forma continua es una emergencia pediátrica que requiere evaluación médica completa para encontrar la causa." }, types: { title: "Causas y Factores Contribuyentes", intro: "Se divide médicamente en causas relacionadas con la ingesta y absorción de calorías:", items: ["Ingesta calórica inadecuada: Es la causa más común. Puede deberse a problemas de lactancia, errores al preparar la fórmula (diluirla demasiado), rechazo a comer por problemas sensoriales o dinámicas familiares estresantes y pobreza (inseguridad alimentaria).", "Absorción inadecuada de nutrientes: El niño come, pero su cuerpo no asimila los alimentos. Causado por celiaquía, fibrosis quística, alergias alimentarias severas o enfermedad inflamatoria intestinal.", "Aumento de la demanda metabólica: El niño quema demasiadas calorías porque su cuerpo está luchando contra un problema de salud. Causado por defectos cardíacos congénitos, hipertiroidismo, infecciones crónicas, o problemas pulmonares."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un trabajo de investigación pediátrica multidisciplinaria:", items: ["Historial dietético y diario de comidas: El médico o nutricionista analizará exactamente qué, cuánto y cómo come el niño durante varios días.", "Examen físico y revisión del historial de gráficas de crecimiento: Para determinar cuándo empezó exactamente el retraso.", "Observación de la alimentación: Observar la dinámica entre la madre/padre y el bebé durante las comidas para detectar problemas de succión, tragar o interacción.", "Análisis de laboratorio (Sangre, orina y heces): Solo se ordenan para descartar causas médicas subyacentes (como anemia, infecciones urinarias ocultas, celiaquía o problemas tiroideos) si la historia dietética no revela el problema."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere un enfoque de equipo (pediatra, dietista, trabajador social, terapeuta del habla):", subsections: [ { title: "Manejo Nutricional y Médico", items: ["Realimentación intensiva controlada: Aumentar la cantidad y la densidad calórica de los alimentos. Se pueden usar fórmulas altas en calorías, añadir grasas saludables a las papillas o suplementos nutricionales líquidos. El aumento debe ser monitoreado para evitar el peligroso 'síndrome de realimentación'.", "Terapia de alimentación: Si el niño tiene problemas físicos para tragar o aversiones sensoriales severas a la textura de la comida, un logopeda o terapeuta ocupacional entrena al niño para comer de forma segura.", "Tratamiento de la enfermedad subyacente: Cirugía para defectos cardíacos, dieta sin gluten para la celiaquía, o medicamentos para el reflujo severo.", "Apoyo familiar: Enseñar a los padres técnicas de alimentación positivas, establecer rutinas de comida y proporcionar recursos socioeconómicos si la familia no puede costear alimentos suficientes."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu pediatra de inmediato si tu bebé o hijo pequeño:", items: ["Parece estar perdiendo peso, sus ropas le quedan holgadas o su rostro se ve demacrado", "Se niega a comer consistentemente o tiene vómitos y diarrea severos después de comer", "Es excepcionalmente pasivo, no muestra interés en los juguetes y parece carecer de energía todo el día"] } },
'Diarrea bacteriana' : { intro: "La diarrea bacteriana (a menudo parte de un cuadro de gastroenteritis infecciosa) es una inflamación del estómago e intestinos causada por la ingestión de bacterias patógenas, lo que resulta en deposiciones frecuentes, acuosas y, a veces, sanguinolentas.", whatIs: { title: "¿Qué es la Diarrea Bacteriana?", text: "Normalmente, los intestinos absorben el líquido de los alimentos a medida que pasan. Cuando consumes alimentos o agua contaminados con bacterias dañinas (como por mala higiene o cocción inadecuada), estos microorganismos invaden el revestimiento del intestino o liberan toxinas fuertes. El intestino se inflama gravemente y, como mecanismo de defensa y daño, no puede absorber líquidos y comienza a secretar agua adicional, lo que provoca una diarrea líquida e incontrolable (intoxicación alimentaria)." }, symptoms: { title: "Síntomas y Alertas Infecciosas", intro: "A diferencia de una simple indigestión, las infecciones bacterianas suelen causar síntomas más sistémicos y violentos:", groups: [ { name: "Signos Clínicos y Gastrointestinales", items: ["Diarrea acuosa frecuente y explosiva, a veces con un olor particularmente fétido", "Sangre roja brillante, mucosidad o pus visible en las heces (disentería, un signo clave de bacterias invasivas)", "Calambres abdominales intensos, dolores punzantes y retorcijones", "Náuseas continuas y episodios de vómitos", "Fiebre (a menudo alta), escalofríos y fatiga profunda"] } ], warning: "El peligro real no es la bacteria, sino la DESHIDRATACIÓN. Si pierdes líquidos y electrolitos vitales más rápido de lo que los repones, puedes entrar en shock hipovolémico y sufrir daño en órganos mayores. En niños pequeños y ancianos, esto puede ser fatal en cuestión de 24-48 horas." }, types: { title: "Bacterias Culpables Comunes", intro: "Las infecciones generalmente provienen de alimentos mal manipulados:", items: ["Salmonella: Frecuente por carne de aves cruda, huevos o contacto con reptiles.", "Campylobacter: Una de las causas más comunes, a menudo por pollo poco cocinado o agua contaminada.", "Escherichia coli (E. coli): Algunas cepas productoras de toxina Shiga (STEC) provienen de carne picada cruda y pueden causar un síndrome fatal que destruye los riñones (Síndrome Urémico Hemolítico).", "Shigella: Altamente contagiosa, se propaga por contacto de persona a persona o alimentos (común en guarderías).", "Clostridioides difficile (C. diff): Ocurre casi exclusivamente después de tomar antibióticos, los cuales destruyen la flora intestinal buena, permitiendo que esta bacteria tóxica prolifere causando diarrea grave."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La mayoría de las diarreas leves no necesitan pruebas, pero si son graves, el médico requerirá:", items: ["Coprocultivo (Cultivo de heces): El estándar de oro. El laboratorio cultiva una muestra de tus heces para identificar exactamente qué bacteria te enfermó y qué antibiótico la matará.", "Análisis de sangre: Para buscar signos de infección sistémica severa o problemas renales debido a la deshidratación."], note: "" }, treatment: { title: "Tratamientos", intro: "El pilar absoluto del tratamiento es la hidratación; los antibióticos se usan con mucha precaución:", subsections: [ { title: "Manejo Hídrico y Médico", items: ["Rehidratación Oral (SRO): La intervención más crítica. Beber Soluciones de Rehidratación Oral (sueros de farmacia) es superior al agua pura o bebidas deportivas, ya que contienen la proporción exacta de sal, azúcar y potasio que tus intestinos necesitan absorber.", "Rehidratación Intravenosa (IV): En urgencias, si el paciente vomita incesantemente o presenta signos de deshidratación severa (ausencia de orina, letargo, sequedad extrema).", "Uso Prudente de Antibióticos: SOLO se prescriben para infecciones graves con fiebre alta, heces con sangre (disentería) comprobada, C. diff, o en personas inmunodeprimidas (como la Azitromicina o Ciprofloxacino). Para muchas bacterias leves (como algunas E. coli o Salmonella), los antibióticos no se dan porque pueden prolongar el estado de portador de la bacteria o aumentar el riesgo de complicaciones renales.", "Evitar los Antidiarreicos: NUNCA tomes medicamentos que paralizan el intestino (como Loperamida/Fortasec) si tienes fiebre alta o sangre en las heces. Estos medicamentos evitan que el cuerpo expulse la bacteria, atrapando las toxinas en el intestino y empeorando drásticamente la enfermedad."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o al médico inmediatamente si:", items: ["Presentas diarrea que dura más de 2 a 3 días (o 24 horas en un bebé)", "Ves sangre abundante o heces de color negro alquitranado", "Sufres una fiebre superior a los 39°C (102°F) y dolor abdominal que te impide moverte", "Tienes signos de deshidratación grave: boca pastosa y muy seca, mareos profundos al ponerte de pie, o no has orinado en más de 6-8 horas"] } },
'Leiomioma' : { intro: "Un leiomioma es el término médico formal y patológico para describir un tumor benigno (no canceroso) de músculo liso. Aunque pueden formarse en cualquier parte del cuerpo con este tejido (como intestinos o vasos sanguíneos), son abrumadoramente más comunes en el útero de la mujer, donde se conocen popularmente como miomas o fibromas uterinos.", whatIs: { title: "¿Qué es un Leiomioma Uterino?", text: "El útero es una bolsa de músculo liso diseñada para expandirse durante el embarazo. Un leiomioma comienza cuando una sola célula de este músculo muta y comienza a multiplicarse rápidamente bajo la influencia de las hormonas femeninas (estrógeno y progesterona). El resultado es la formación de un nódulo o masa dura, parecida al caucho. Son excepcionalmente comunes: se estima que hasta el 70-80% de las mujeres desarrollarán leiomiomas en algún momento de sus vidas antes de los 50 años. El riesgo de que se transformen en cáncer (leiomiosarcoma) es prácticamente inexistente." }, symptoms: { title: "Síntomas y Afectaciones", intro: "Muchas mujeres los tienen y nunca presentan síntomas (se descubren por casualidad en una ecografía). Sin embargo, cuando causan problemas, interfieren drásticamente con la calidad de vida:", groups: [ { name: "Trastornos Menstruales", items: ["Menorragia: Sangrado menstrual profuso, donde la mujer expulsa grandes coágulos y empapa compresas o tampones en una o dos horas, a menudo llevando a la anemia", "Periodos menstruales que se extienden más de una semana", "Manchado recurrente entre los periodos regulares"] }, { name: "Síntomas por Compresión Pélvica", items: ["Sentimiento de peso constante, presión o dolor sordo en la parte baja del abdomen y pelvis", "Aumento de la frecuencia urinaria o dificultad para vaciar la vejiga (cuando el leiomioma es grande y aplasta la vejiga)", "Estreñimiento o dolor lumbar crónico (cuando el leiomioma presiona el intestino o los nervios posteriores)", "Infertilidad, abortos espontáneos recurrentes, o dolor intenso durante las relaciones sexuales"] } ], warning: "El dolor pélvico no suele ser intenso, pero si un leiomioma sufre una pérdida repentina de flujo sanguíneo (degeneración) o si un leiomioma con 'tallo' se retuerce sobre sí mismo, causará un dolor abdominal agudo fulminante y fiebre, siendo una urgencia médica." }, types: { title: "Clasificación Anatómica", intro: "Los leiomiomas se clasifican según en qué capa del útero crezcan, lo que dicta los síntomas:", items: ["Submucosos: Crecen abultándose hacia la cavidad interior del útero. Son los que causan los peores sangrados y problemas severos de fertilidad.", "Intramurales: Crecen incrustados en medio de la gruesa pared muscular. Son los más comunes y agrandan el tamaño global del útero.", "Subserosos: Crecen hacia afuera del útero, en la cavidad pélvica. Causan problemas principalmente al presionar los órganos vecinos (vejiga o intestinos)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fácil de detectar en exámenes ginecológicos de rutina:", items: ["Examen Pélvico Físico: El ginecólogo notará que el útero se siente duro, agrandado o con forma abultada irregular.", "Ecografía Transvaginal: La prueba diagnóstica primaria. Utiliza ondas de sonido para mostrar la ubicación exacta y el tamaño de los leiomiomas de manera rápida e indolora.", "Histeroscopia: Para ver leiomiomas submucosos, se introduce un pequeño telescopio iluminado a través de la vagina hacia el interior del útero.", "Resonancia Magnética (RM): Ofrece imágenes 3D de alta definición, útiles antes de planificar una cirugía compleja para extirparlos."], note: "" }, treatment: { title: "Tratamientos", intro: "La 'espera en observación' es la regla para los asintomáticos. Si hay síntomas, los tratamientos buscan frenar el sangrado o extirpar el tumor preservando (o no) el útero:", subsections: [ { title: "Manejo Médico Conservador", items: ["Píldoras anticonceptivas o DIU hormonal (Mirena): No encogen los leiomiomas, pero son excelentes para detener los sangrados abundantes y reducir los cólicos.", "Ácido Tranexámico: Fármaco no hormonal que se toma durante la regla para ayudar a coagular y frenar la hemorragia grave.", "Agonistas de la GnRH (ej. Lupron): Inyecciones que frenan la producción de estrógenos en el cerebro, provocando una menopausia temporal. Sin hormonas, los leiomiomas se encogen drásticamente. Se usan a menudo meses antes de la cirugía para reducir el tamaño del tumor y frenar la anemia."] }, { title: "Procedimientos Mínimamente Invasivos y Quirúrgicos", items: ["Embolización de Arterias Uterinas: Un radiólogo inyecta partículas diminutas en las arterias que alimentan el útero, cortando el suministro de sangre a los tumores. Sin sangre, se encogen y mueren (no recomendado si se desean futuros embarazos).", "Miomectomía: Extirpación quirúrgica solo de los leiomiomas, conservando el útero intacto. Es el tratamiento de elección para mujeres que sufren síntomas pero desean tener hijos en el futuro.", "Histerectomía: Extirpación total del útero. Es la única cura 100% definitiva que asegura que nunca volverán a crecer, utilizada cuando la paciente ya no desea embarazos y los síntomas son insoportables."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una revisión ginecológica si presentas:", items: ["Menstruaciones tan abundantes que limitan tu vida diaria, manchando ropa y sábanas de forma regular", "Sientes un bulto duro en tu bajo abdomen o notas que ha crecido", "Dolor pélvico persistente, pesadez inusual o problemas para vaciar tu vejiga", "Sangrado vaginal irregular que aparece entre tus ciclos menstruales normales"] } },
'Infección urinaria complicada' : { intro: "Una infección de las vías urinarias (IVU) complicada es una infección urinaria, a menudo grave, que ocurre en una persona que tiene factores de riesgo anatómicos, funcionales o médicos preexistentes que reducen la eficacia de los tratamientos habituales, aumentando masivamente la probabilidad de que la infección dañe los riñones o pase al torrente sanguíneo (septicemia).", whatIs: { title: "¿Qué es una IVU Complicada?", text: "Una cistitis normal (IVU no complicada) ocurre en una mujer sana y se cura con tres días de antibióticos orales. Sin embargo, una IVU se considera 'complicada' si ocurre en hombres (ya que anatómicamente es raro que un hombre sano adquiera una IVU sin un bloqueo subyacente), en mujeres embarazadas, en ancianos frágiles, o si el paciente tiene sondas urinarias, diabetes, cálculos renales o un sistema inmunológico débil. En estos casos, las bacterias pueden atrincherarse en el cuerpo, formar biopelículas resistentes a los medicamentos, o escalar rápidamente a los riñones." }, symptoms: { title: "Síntomas y Alertas de Gravedad Sistémica", intro: "Los síntomas abarcan la zona urinaria, pero frecuentemente involucran a todo el cuerpo, señalando que la infección se está propagando:", groups: [ { name: "Síntomas Urinarios y Sistémicos Críticos", items: ["Dolor intenso, escozor extremo o dificultad para orinar (y la orina puede ser turbia, roja o con un olor pútrido fuerte)", "Fiebre alta, a menudo por encima de 39°C (102°F), acompañada de temblores y escalofríos agudos", "Dolor sordo, fuerte y punzante en los costados de la espalda (zona lumbar) o debajo de las costillas (indicador claro de que la infección ha llegado al riñón)", "Náuseas continuas y vómitos repetidos, impidiendo la retención de agua y medicamentos", "Debilidad generalizada masiva", "Cambios bruscos de estado mental: letargo, confusión, delirios o agitación (especialmente en personas mayores de 65 años, este puede ser el ÚNICO síntoma inicial de una sepsis por infección urinaria)"] } ], warning: "Toda IVU complicada requiere evaluación urgente. El riesgo de Urosepsis (infección en la sangre que origina falla de órganos múltiples y choque séptico letal) es muy alto si se retrasa la terapia antimicrobiana o no se quita el bloqueo físico de la vía urinaria." }, types: { title: "Factores Complicadores", intro: "Una IVU recibe la etiqueta de 'complicada' si la bacteria está apoyada por:", items: ["Anomalías Anatómicas o Bloqueos: Próstata agrandada (HPB) que no deja vaciar la vejiga, cálculos renales (piedras) donde las bacterias se esconden en la porosidad de la piedra evadiendo los fármacos, o estrechez en los uréteres.", "Cuerpos Extraños: Pacientes portadores de catéteres urinarios permanentes (sondas vesicales) o tubos en los riñones (nefrostomías). Las bacterias forman biopelículas impenetrables sobre el plástico.", "Inmunosupresión y Metabolismo: Pacientes con Diabetes Mellitus (la orina dulce alimenta a las bacterias), cáncer en quimioterapia, trasplantados de órganos, o infección por VIH.", "Embarazo: Todo embarazo vuelve complicada una IVU debido al riesgo de parto prematuro y a que los uréteres están dilatados, facilitando el paso de gérmenes al riñón materno.", "Infecciones Nosocomiales: Infecciones adquiridas dentro de un hospital, ya que las bacterias hospitalarias (como *Pseudomonas* o *Klebsiella*) suelen ser multirresistentes a antibióticos comunes."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "A diferencia de las IVU simples, aquí la investigación de laboratorio e imagenología es estricta y obligatoria:", items: ["Urianálisis y Urocultivo: Es innegociable. No se puede recetar a ciegas. La orina DEBE ser cultivada para aislar la bacteria e identificar con precisión el antibiograma (qué antibióticos funcionan y a cuáles es resistente la bacteria).", "Análisis de sangre y Hemocultivos: Para medir la inflamación general y verificar si las bacterias se han filtrado a la sangre (bacteriemia).", "Imágenes Médicas de Urgencia (TC abdominal o Ecografía Renal): Críticas para buscar problemas de fontanería (bloqueos). El médico necesita saber si hay una piedra en el riñón o un absceso de pus atascado que necesite drenaje quirúrgico antes de que la medicación pueda hacer efecto."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es agresivo, a menudo requiriendo ingreso hospitalario, terapias largas y desobstrucción:", subsections: [ { title: "Manejo Antimicrobiano e Intervencionista", items: ["Hospitalización y Antibióticos Intravenosos (IV): La mayoría de los pacientes severamente enfermos, vomitando o con signos de sepsis requieren ingreso hospitalario. Se inician de inmediato antibióticos IV de amplio espectro (como Ceftriaxona o Piperacilina-Tazobactam) para golpear rápido a la bacteria, ajustándolos días después según el resultado del urocultivo. El tratamiento total dura entre 10 y 14 días (o más).", "Remoción de la Causa Obstructiva (Urología Intervencionista): El antibiótico no servirá si la vía está tapada. El urólogo debe retirar de inmediato piedras atascadas mediante láser, cambiar o retirar la sonda vesical infectada, o poner un catéter Doble-J temporal para desatascar un riñón bloqueado y permitir la salida del pus.", "Hidratación Masiva: Fluidos intravenosos en el hospital para apoyar a los riñones, aumentar la presión sanguínea y promover el flujo de la orina.", "Manejo Ambulatorio: En casos menos graves que toleren la vía oral, se recetan antibióticos fuertes orales como Fluoroquinolonas (Ciprofloxacino) bajo vigilancia estrecha."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias médicas o acude de inmediato a urgencias hospitalarias si presentas dolor urinario y perteneces a un grupo de riesgo (diabético, embarazada, con cálculos o catéter) y notas:", items: ["Fiebre incontrolable, sudoración fría y escalofríos severos con castañeteo de dientes", "Imposibilidad total de orinar (retención urinaria)", "El paciente se muestra repentinamente aletargado, extremadamente dormido, o comienza a decir cosas incoherentes (especialmente familiares de edad avanzada)", "Vómitos severos repetitivos y dolor agudo en un costado de la espalda baja"] } },
'Trastorno Déficit de atención e hiperactividad' : { intro: "El Trastorno por Déficit de Atención e Hiperactividad (TDAH) es uno de los trastornos del neurodesarrollo crónicos más frecuentes, originado en la infancia y que a menudo perdura hasta la edad adulta, caracterizado por un patrón neurológico persistente de inatención profunda, exceso de actividad física incontrolable e impulsividad que interfiere severamente con el funcionamiento y el desarrollo de la persona.", whatIs: { title: "¿Qué es el TDAH?", text: "El TDAH no es un problema de mala crianza, falta de inteligencia o simple 'pereza'. Es un trastorno biológico cerebral demostrable. Las investigaciones indican que el cerebro de una persona con TDAH muestra diferencias en el desarrollo anatómico y fallos en las redes de comunicación de neurotransmisores vitales (dopamina y noradrenalina) en la corteza prefrontal, el 'director de orquesta' del cerebro encargado de la función ejecutiva. Como resultado, la persona carece del freno biológico para filtrar distracciones, planificar, organizar tareas aburridas o quedarse quieta cuando se requiere." }, symptoms: { title: "Síntomas y Manifestaciones Clínicas", intro: "Los síntomas deben manifestarse en más de un entorno (por ejemplo, en casa y en la escuela/trabajo) y ser desproporcionados para la edad:", groups: [ { name: "Síntomas de Inatención (El Cerebro sin Filtro)", items: ["Cometer frecuentemente errores por descuido profundo en tareas escolares o laborales, y no prestar atención a los detalles pequeños", "Dificultad monumental para mantener la concentración y la atención continua en tareas o juegos largos que no resultan altamente estimulantes", "Parecer no escuchar cuando se le habla directamente (como si tuviera la mente en otro lugar)", "Fracaso crónico para seguir y terminar instrucciones, tareas o deberes (empieza proyectos pero se distrae con otra cosa a la mitad)", "Problemas severos para organizarse (escritorios o habitaciones caóticas, gestión de tiempo pésima, llega tarde sistemáticamente)", "Pérdida frecuente de cosas esenciales (llaves, móviles, carteras, gafas, tareas escolares)", "Distracción fácil por estímulos completamente externos e irrelevantes, y un olvido patológico constante de las rutinas diarias"] }, { name: "Síntomas de Hiperactividad e Impulsividad (El Motor sin Frenos)", items: ["Incapacidad para quedarse quieto: Mueve constantemente las manos, golpetea los pies o se retuerce en el asiento", "Levantarse de la silla en situaciones donde se espera que permanezca sentado (en el aula o en la oficina)", "Sensación constante de inquietud interna, o correr y trepar en situaciones inapropiadas", "Hablar de forma excesiva y atropellada", "Responder precipitosamente a preguntas antes de que hayan terminado de formularlas", "Interrumpir o entrometerse agresivamente e instintivamente en las conversaciones o juegos de los demás, y gran dificultad y sufrimiento por tener que esperar su turno en una fila"] } ], warning: "En adultos, la hiperactividad física a menudo desaparece, transformándose en una sensación paralizante de ansiedad, inquietud mental, cambios de trabajo constantes, abuso de drogas, mala conducción y problemas crónicos de pareja debido a la impulsividad." }, types: { title: "Presentaciones (Tipos) del TDAH", intro: "El TDAH se diagnostica según el perfil de síntomas dominante:", items: ["Presentación Combinada: El tipo más clásico y común. El paciente muestra suficientes síntomas graves tanto del criterio de inatención como del de hiperactividad-impulsividad.", "Presentación Predominantemente Inatenta: A menudo llamado 'TDA' (sin la H). Típicamente más diagnosticado en niñas, quienes pasan desapercibidas en la escuela porque no molestan en clase, sino que se la pasan soñando despiertas y fracasando académicamente en silencio.", "Presentación Predominantemente Hiperactiva-Impulsiva: Menos común, caracterizada por extrema impulsividad y movimiento sin tantos problemas graves de atención."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existe una prueba de sangre o resonancia para el TDAH. Se diagnostica clínicamente:", items: ["Evaluación Clínica y Psiquiátrica Integral: Realizada por un psiquiatra, psicólogo o neurólogo. Se evalúa el historial completo, buscando confirmar que los síntomas estaban presentes antes de los 12 años de edad.", "Cuestionarios Estandarizados (Escalas): Es imperativo recoger información de múltiples fuentes. El médico requiere cuestionarios llenados por los padres, el propio paciente y, crucialmente, los profesores del colegio para ver cómo se comporta en diferentes entornos.", "Diagnóstico Diferencial: Exámenes para descartar si la falta de atención se debe a problemas de visión/audición, traumas emocionales severos, ansiedad, depresión, dislexia o falta de sueño (apnea)."], note: "Es muy común que el TDAH venga acompañado (comorbilidad) de trastornos de ansiedad, autismo, trastorno negativista desafiante y discapacidades del aprendizaje." }, treatment: { title: "Tratamientos", intro: "El TDAH se trata más eficazmente con una combinación agresiva (terapia multimodal) de medicación, modificaciones en el entorno y terapia conductual:", subsections: [ { title: "Manejo Farmacológico", items: ["Medicamentos Estimulantes del SNC (La Primera Línea): Sorprendentemente, los estimulantes como el Metilfenidato (Ritalin, Concerta) o las Anfetaminas (Adderall, Vyvanse) calman y enfocan el cerebro con TDAH. Son los tratamientos psiquiátricos más efectivos existentes en medicina. Funcionan aumentando la dopamina en el cerebro, encendiendo las áreas del 'control de frenos', logrando que el niño o adulto se concentre de manera casi inmediata en su dosis óptima.", "Medicamentos No Estimulantes: La Atomoxetina (Strattera), Guanfacina o antidepresivos (Bupropión) se recetan si el paciente no tolera los estimulantes, tiene problemas severos de corazón o tics, o problemas de adicción previos."] }, { title: "Terapias Psicológicas y Modificación del Entorno", items: ["Terapia Conductual: En niños, la terapia NO va dirigida al niño, sino a los PADRES y PROFESORES. Consiste en enseñarles sistemas rigurosos de recompensas y consecuencias inmediatas, rutinas estrictas y refuerzo positivo estructurado para modificar el comportamiento del niño.", "Terapia Cognitivo-Conductual (TCC) en Adultos: Indispensable para ayudar al adulto a desaprender malos hábitos, organizarse, manejar el tiempo con herramientas visuales y superar la baja autoestima y frustración de años de fracasos.", "Acomodaciones Educativas (Planes IEP/504): Modificaciones legales en la escuela, como sentar al niño en la primera fila, otorgarle tiempo extra para los exámenes y realizar instrucciones paso a paso."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Programa una evaluación psiquiátrica o neurológica si tú o tu hijo presentan un patrón constante donde:", items: ["Los problemas de atención y despiste están causando un fracaso académico claro, bajas calificaciones repetidas, o problemas constantes de disciplina con los maestros en el colegio", "Como adulto, sientes que no puedes mantener un trabajo estable por errores descuidados, siempre llegas tarde, o la impulsividad está dañando seriamente tus relaciones de pareja", "Tu hijo tiene grandes dificultades sociales, no logra hacer o mantener amigos debido a la agresividad o impulsividad en los juegos"] } },
'Nutrición y salud emocional' : { intro: "La conexión entre la nutrición y la salud emocional, objeto de estudio del campo emergente de la psiquiatría nutricional, reconoce que la calidad y los tipos de alimentos que ingerimos tienen un impacto directo, químico y fisiológico en el estado de ánimo, los niveles de ansiedad, la energía y la salud mental general de una persona.", whatIs: { title: "El Eje Intestino-Cerebro", text: "La salud mental y el intestino están biológicamente entrelazados. El tracto gastrointestinal no solo digiere comida, está revestido de millones de neuronas (el sistema nervioso entérico). Además, el microbioma intestinal (las bacterias que viven en nuestro intestino) es responsable de producir más del 90% de la serotonina del cuerpo, el neurotransmisor químico de la 'felicidad'. Cuando consumimos dietas inflamatorias y ultraprocesadas, destruimos las bacterias buenas, provocando inflamación sistémica. Esta inflamación viaja directamente al cerebro y a la sangre, bloqueando la producción de hormonas de bienestar, aumentando drásticamente la vulnerabilidad a trastornos de salud mental." }, symptoms: { title: "Síntomas Físicos y Emocionales del Desequilibrio Dietético", intro: "Una nutrición deficiente e inflamatoria puede exacerbar o mimetizar trastornos psicológicos:", groups: [ { name: "Síntomas Relacionados con la Mala Dieta", items: ["Cambios de humor extremos, irritabilidad o caídas emocionales bruscas que coinciden con los picos y valles de azúcar en la sangre (la montaña rusa de la insulina tras comer grandes cantidades de dulces)", "Fatiga crónica abrumadora, letargo y falta de motivación", "Niebla mental (brain fog): Incapacidad para concentrarse, pesadez en el pensamiento y problemas de memoria", "Empeoramiento comprobable de los síntomas de la depresión clínica y los niveles de ansiedad crónica", "Problemas de sueño y de la regulación de energía durante el día"] } ], warning: "La comida nunca sustituye la ayuda profesional en crisis psiquiátricas graves. Si alguien sufre depresión mayor o ideas suicidas, la dieta es un apoyo complementario crucial a la medicación y terapia, jamás un tratamiento único de urgencia." }, types: { title: "Mecanismos y Deficiencias Culposas", intro: "Los problemas de salud emocional nutricional surgen principalmente por dos vías:", items: ["Deficiencias de Micronutrientes Esenciales: La carencia de Vitamina B12 (vital para nervios y estado de ánimo, crítica en veganos estrictos), Vitamina D (vinculada al trastorno afectivo estacional y depresión), Magnesio y Zinc.", "Déficit de Ácidos Grasos Omega-3: El cerebro es principalmente grasa. La falta de Omega-3 (presente en el salmón y nueces) altera las membranas celulares del cerebro, vinculándose directamente con tasas más altas de depresión y déficit de atención.", "Dieta Inflamatoria (La Dieta Occidental Estándar): Consumo masivo de azúcares refinados, grasas trans y alimentos ultraprocesados que promueven la 'disbiosis intestinal' (muerte de bacterias beneficiosas) e inflaman las redes neuronales.", "Salto de comidas y Deshidratación: Ayunos forzados o no beber agua aumentan la liberación de cortisol (hormona del estrés) y adrenalina, disparando ansiedad biológica."] }, diagnosis: { title: "¿Cómo se Evalúa el Impacto Nutricional?", intro: "Una evaluación psiquiátrica nutricional combina el estado mental con analíticas corporales:", items: ["Evaluación de Dieta y Estado de Ánimo: El profesional de la salud o nutricionista pedirá que mantengas un diario detallado para vincular qué comes exactamente con tus bajones de humor diarios.", "Análisis de Sangre Completo: Búsqueda estricta de deficiencias ocultas (Niveles de Vitamina D, Ferritina, Hierro, Folato, Vitamina B12, panel de tiroides y glucosa en ayunas).", "Evaluación de Salud Intestinal: Abordar cualquier síndrome crónico del intestino irritable (SII), estreñimiento o intolerancias que dañen la absorción de nutrientes y la flora intestinal."], note: "" }, treatment: { title: "Tratamientos Nutricionales Preventivos", intro: "El enfoque busca desinflamar el cuerpo y 'alimentar' las bacterias buenas del intestino y el tejido cerebral:", subsections: [ { title: "Intervenciones Dietéticas de Psiquiatría Nutricional", items: ["Adopción de una Dieta Antiinflamatoria (Dieta Mediterránea): Es el plan más respaldado por la ciencia psiquiátrica. Basada masivamente en verduras crudas, frutas, cereales integrales gruesos, aceite de oliva virgen extra y pescados grasos. Ha demostrado reducir significativamente el riesgo y gravedad de la depresión en ensayos clínicos.", "Inclusión de Probióticos y Prebióticos: Consumir alimentos fermentados vivos (Kéfir, Chucrut crudo, Kombucha, Yogur natural) para repoblar agresivamente el microbioma de bacterias que producen serotonina y reducen la ansiedad del cerebro.", "Eliminación Estricta de Azúcares y Procesados: Cortar radicalmente los picos de glucosa deteniendo el consumo de bollería, refrescos, harinas blancas y alimentos fritos, que agotan la energía cerebral y causan bajones emocionales abruptos a la tarde.", "Suplementación Dirigida: Consumo pautado de altas dosis de EPA/DHA (Aceite de Pescado u Omega-3), Vitamina D3 (especialmente en invierno) y suplementos de complejo B, únicamente tras comprobar su déficit en analítica.", "Hábitos de Alimentación Consciente (Mindful Eating): Comer en ambientes relajados, masticar bien y evitar comer por estrés, reparando la relación psicológica con la comida y el intestino."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Considera consultar a un equipo de psiquiatra, psicólogo y nutricionista clínico si:", items: ["Sientes que tus niveles de energía y tus ánimos son como una montaña rusa incontrolable que parece estar ligada a lo que comes (o a cuando dejas de comer)", "Padeces problemas crónicos de digestión (gases, diarreas, estreñimiento) que empeoran simultáneamente cuando tienes picos fuertes de estrés o ansiedad, un ciclo que arruina tu calidad de vida", "Estás lidiando con depresión o ansiedad que no mejora del todo con terapias tradicionales y tu dieta actual se basa principalmente en comida rápida o procesada"] } },
'Ptosis' : { intro: "La ptosis, médicamente conocida como blefaroptosis, es la caída del párpado superior sobre el ojo. Puede afectar a un solo ojo o a ambos, y variar desde una caída leve hasta cubrir por completo la pupila y bloquear la visión normal.", whatIs: { title: "¿Qué es la Ptosis?", text: "Nuestros párpados se mantienen abiertos gracias a un músculo específico (el músculo elevador del párpado). En la ptosis, este músculo, o el nervio que lo controla, se debilita, se estira o sufre daño. Como resultado, el párpado cede ante la gravedad. Si la caída es lo suficientemente pronunciada, obstruye parcial o totalmente el campo visual superior, obligando a la persona a inclinar la cabeza hacia atrás o a fruncir la frente constantemente para poder ver." }, symptoms: { title: "Síntomas y Señales Físicas", intro: "El síntoma principal es visual, pero las compensaciones corporales causan otros problemas:", groups: [ { name: "Signos Clínicos y Compensatorios", items: ["Caída visible de uno o ambos párpados superiores (el ojo parece más pequeño o adormilado)", "Bloqueo de la visión superior, obligando al paciente a levantar la barbilla o arquear las cejas para ver", "Fatiga ocular y dolor de cabeza tensional severo por el esfuerzo constante de los músculos de la frente", "En los niños, la ptosis puede causar que el cerebro ignore ese ojo, desarrollando una ceguera funcional (ambliopía u ojo vago) si no se corrige"] } ], warning: "Si la caída del párpado ocurre de manera muy rápida o repentina, especialmente si se acompaña de pupilas de diferente tamaño, debilidad facial, visión doble o dolor de cabeza agudo, es una alerta roja de un problema neurológico grave (como un Accidente Cerebrovascular, Síndrome de Horner, o un aneurisma cerebral) y requiere acudir a urgencias inmediatamente." }, types: { title: "Causas y Clasificación", intro: "La debilidad del párpado puede originarse desde el nacimiento o desarrollarse con el tiempo:", items: ["Ptosis Aponeurótica (Involutiva o Senil): La causa más común. Con el envejecimiento, el tendón del músculo elevador simplemente se estira y se afloja de su punto de anclaje.", "Ptosis Congénita: Presente desde el nacimiento. El músculo elevador no se desarrolló correctamente en el útero.", "Ptosis Neurogénica: Daño a los nervios que controlan el músculo (como en la miastenia gravis o parálisis del tercer par craneal).", "Ptosis Mecánica o Traumática: Un peso adicional tira del párpado hacia abajo (como un tumor o inflamación), o un golpe desgarra el músculo o los tendones, a veces ocurre tras cirugías oculares previas como la de cataratas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un oftalmólogo u oculoplástico evaluará la causa y la severidad:", items: ["Examen ocular completo con lámpara de hendidura: Para evaluar la salud general del ojo.", "Mediciones del párpado: El médico utilizará una regla milimetrada para medir exactamente qué tanto cubre el párpado a la pupila y para evaluar la fuerza residual del músculo elevador.", "Examen neurológico básico y pruebas de imagen (RM o TC) si se sospecha de un tumor, aneurisma o problemas en los nervios del cerebro.", "Prueba de Tensilon (o similar) o análisis de sangre, para descartar Miastenia Gravis en casos de ptosis fluctuante que empeora por la tarde."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento casi siempre es quirúrgico si la ptosis afecta la visión o la estética de forma importante:", subsections: [ { title: "Opciones Quirúrgicas y de Soporte", items: ["Cirugía de Reparación de Ptosis (Avanzamiento del Elevador): El procedimiento más común. El cirujano ocular hace una incisión en el pliegue natural del párpado, encuentra el músculo elevador estirado, lo acorta o lo tensa y lo vuelve a coser firmemente a su posición original (se hace con anestesia local).", "Suspensión Frontal: Si el músculo del párpado está completamente paralizado o es inútil (común en casos congénitos), el cirujano une el párpado al músculo de la frente (músculo frontal) usando una banda de silicona o tejido propio del cuerpo. Así, el paciente usa las cejas para levantar el párpado.", "Gafas con 'Muletas' para Ptosis: Para personas que no son candidatas a cirugía, se puede añadir un pequeño alambre a la montura de las gafas que sostiene físicamente el párpado hacia arriba.", "Gotas para los ojos (Oximetazolina oftálmica): Un medicamento en gotas de prescripción reciente que estimula un pequeño músculo oculto en el párpado (músculo de Müller), ayudando a abrir el ojo de forma temporal en casos leves."] } ], note: "Es vital tratar la ptosis congénita en niños rápidamente para asegurar que el cerebro desarrolle vías visuales normales." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca evaluación con un oftalmólogo si:", items: ["La caída del párpado te obliga a forzar el cuello hacia atrás o interfiere con tu capacidad para leer o conducir", "Si notas un párpado caído repentino en cuestión de horas o días", "Si un niño pequeño parece tener un ojo permanentemente medio cerrado"] } },
'Tumor cerebral canceroso (metastásico)' : { intro: "Un tumor cerebral metastásico, o metástasis cerebral, es un tumor canceroso maligno que se origina en otra parte del cuerpo y se propaga (hace metástasis) a través del torrente sanguíneo o el sistema linfático hasta alojarse y crecer en el tejido del cerebro.", whatIs: { title: "¿Qué es un Tumor Cerebral Metastásico?", text: "Es crucial entender que este NO es un cáncer cerebral original (primario). Por ejemplo, si el cáncer de pulmón viaja al cerebro, el tumor en la cabeza está compuesto por células de cáncer de pulmón mutadas, no por células cerebrales. En los adultos, los tumores metastásicos son, con diferencia, el tipo más común de tumor cerebral, superando abrumadoramente en número a los tumores que se inician en el propio cerebro. A menudo se forman múltiples tumores simultáneamente en distintas áreas de la cabeza." }, symptoms: { title: "Síntomas y Alertas Neurológicas", intro: "El cráneo es una caja cerrada de hueso duro. A medida que los tumores y la inflamación que los rodea crecen, aplastan el cerebro sano contra el hueso, causando síntomas por aumento de presión o por destrucción de áreas específicas:", groups: [ { name: "Síntomas por Presión Intracraneal Elevada", items: ["Dolores de cabeza crónicos, opresivos y nuevos que suelen empeorar notablemente por la mañana al despertar, al toser o agacharse", "Náuseas repentinas y vómitos explosivos, a menudo matutinos", "Confusión progresiva, letargo severo, alteraciones de la memoria y cambios profundos y evidentes en la personalidad o el comportamiento", "Convulsiones de nueva aparición (desde temblores locales hasta ataques epilépticos completos) en alguien sin antecedentes"] }, { name: "Síntomas Neurológicos Focales", items: ["Debilidad progresiva, entumecimiento o parálisis en un solo lado del cuerpo, brazo, pierna o cara", "Dificultad evidente para articular palabras o para comprender lo que otros dicen (afasia)", "Pérdida de la visión lateral, visión doble o movimientos oculares incontrolables", "Pérdida del equilibrio, marcha tambaleante y falta de coordinación motora severa"] } ], warning: "Cualquier persona con antecedentes de cáncer en el pasado que comience a sufrir dolores de cabeza extraños, cambios de humor o una primera convulsión, debe someterse a una evaluación neurológica inmediata. Las metástasis pueden ocurrir años después de que el cáncer original fuera aparentemente curado." }, types: { title: "Cánceres Primarios Culpables", intro: "Técnicamente, cualquier cáncer puede viajar al cerebro, pero ciertos tumores tienen una alta afinidad biológica por colonizar el tejido cerebral:", items: ["Cáncer de Pulmón (Es el responsable de más de la mitad de todos los tumores cerebrales metastásicos)", "Cáncer de Mama", "Melanoma (El cáncer de piel más agresivo)", "Cáncer de Riñón (Carcinoma de células renales)", "Cáncer de Colon y Recto"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico preciso de estos tumores secundarios requiere imágenes de alta resolución:", items: ["Resonancia Magnética (RM) del cerebro con contraste (Gadolinio): Es el estudio fundamental, el 'estándar de oro'. Muestra exactamente el número, tamaño y ubicación de los tumores, y el halo de inflamación (edema) alrededor de ellos.", "Tomografía Computarizada (TC) de Cuerpo Entero o PET Scan: Si se encuentra un tumor en el cerebro y la persona no sabía que tenía cáncer, se utilizan estas exploraciones del resto del cuerpo para 'buscar' el origen primario (como los pulmones o los senos).", "Biopsia Estereotáctica: Si el paciente no tiene un diagnóstico previo de cáncer en otra parte del cuerpo, un neurocirujano tomará una muestra minúscula del tumor cerebral con una aguja guiada por ordenador para examinarla bajo el microscopio y determinar de dónde provino realmente el tumor."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo principal es aliviar los síntomas neurológicos controlando la presión y, en muchos casos, erradicar o controlar los tumores en el cerebro:", subsections: [ { title: "Tratamientos de Alivio y Terapias Oncológicas", items: ["Corticosteroides (Dexametasona): La intervención médica inmediata e indispensable. Dosis altas reducen rápidamente la hinchazón y el edema alrededor de los tumores, aliviando el dolor de cabeza y revirtiendo parálisis parciales casi como por arte de magia en horas, comprando tiempo para otros tratamientos.", "Medicamentos Anticonvulsivos: Se recetan si el paciente ha tenido convulsiones.", "Radiocirugía Estereotáctica (Gamma Knife o CyberKnife): Es el tratamiento preferido moderno para metástasis cerebrales pequeñas (menos de 3 cm). Se disparan cientos de haces de radiación minúsculos y focalizados con precisión láser directa y exclusivamente sobre los tumores, sin abrir el cráneo y minimizando el daño al tejido cerebral sano circundante.", "Radioterapia Holocraneal (WBRT): Si hay demasiados tumores dispersos por todo el cerebro (generalmente más de 5 a 10), se irradia el cerebro entero. Aunque es efectivo para matar células ocultas, conlleva riesgos importantes de pérdida de memoria y deterioro cognitivo a largo plazo.", "Neurocirugía Abierta (Craneotomía): Utilizada si hay un solo tumor grande que causa una presión mortal sobre el cerebro, o si el tumor está en un área donde su extirpación puede mejorar drásticamente la calidad de vida inmediata.", "Inmunoterapia y Terapias Dirigidas: Medicamentos sistémicos modernos que logran cruzar la barrera hematoencefálica (como ciertas pastillas contra mutaciones específicas de cáncer de pulmón o melanoma) que encogen los tumores desde dentro y potencian el propio sistema inmunológico del paciente."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención de emergencia o contacta a tu oncólogo de inmediato si tienes antecedentes de cáncer y notas:", items: ["Un dolor de cabeza severo y persistente que te despierta por la noche o va acompañado de náuseas fuertes al amanecer", "Episodios de debilidad en una pierna o brazo, pérdida de coordinación, o torpeza al caminar", "Sufres una convulsión o ataque, o tus familiares notan cambios muy inusuales y rápidos en tu estado de alerta, lenguaje o memoria"] } },
'Acumulación de placa en las arterias' : { intro: "La acumulación de placa en las arterias, conocida médicamente como aterosclerosis, es una enfermedad vascular silenciosa, lenta y progresiva en la que los vasos sanguíneos se endurecen, se engrosan y se estrechan debido al depósito de materiales en sus paredes internas.", whatIs: { title: "¿Qué es la Aterosclerosis?", text: "Nuestras arterias son como tuberías lisas y elásticas que transportan sangre limpia y oxigenada a todo el cuerpo. A lo largo de la vida, si el revestimiento interno de estas 'tuberías' sufre daños (por presión alta, toxinas del humo o azúcar alta), sustancias como el colesterol malo (LDL), grasas, desechos celulares, calcio y fibrina se introducen y se incrustan en la pared de la arteria. Esta mezcla forma una masa dura y pegajosa llamada 'placa'. A medida que la placa crece durante décadas, la arteria se estrecha peligrosamente, estrangulando el flujo sanguíneo hacia órganos vitales como el corazón, el cerebro y las piernas." }, symptoms: { title: "Síntomas y Señales (Depende del Órgano Afectado)", intro: "El gran peligro de la aterosclerosis es que es asintomática (sin síntomas) hasta que la arteria está severamente bloqueada o la placa se rompe bruscamente, provocando que se forme un coágulo que tapa el vaso por completo:", groups: [ { name: "Si ocurre en las Arterias del Corazón (Enfermedad Coronaria)", items: ["Angina de pecho: Un dolor opresivo, presión profunda o ardor en el pecho que suele ocurrir durante el esfuerzo físico o estrés y se alivia con el descanso", "Falta de aire o dificultad para respirar severa", "Si la placa se rompe y bloquea totalmente, causa un Infarto de Miocardio (ataque al corazón) con dolor desgarrador, sudoración fría y riesgo de muerte"] }, { name: "Si ocurre en las Arterias del Cerebro (Enfermedad Carotídea)", items: ["Ataques Isquémicos Transitorios (AIT): Entumecimiento o debilidad repentina y temporal en los brazos, piernas o en un lado de la cara, dificultad para hablar o pérdida de visión en un ojo", "Si el bloqueo es permanente, causa un Accidente Cerebrovascular Isquémico (Derrame o Ictus cerebral), que deja daño neurológico permanente"] }, { name: "Si ocurre en las Arterias de las Piernas (Enfermedad Arterial Periférica)", items: ["Claudicación intermitente: Dolor intenso tipo calambre muscular en las pantorrillas, muslos o glúteos al caminar, que obliga a la persona a detenerse y desaparece al descansar unos minutos", "Piernas o pies fríos, disminución del pulso en los pies, y llagas en los dedos que no sanan"] }, { name: "Si ocurre en las Arterias de los Riñones", items: ["Presión arterial extremadamente alta que no responde a los medicamentos (Hipertensión renovascular)", "Insuficiencia renal crónica progresiva"] } ], warning: "La aterosclerosis es el enemigo público número uno de la salud mundial, siendo la causa raíz subyacente de la inmensa mayoría de ataques cardíacos y accidentes cerebrovasculares letales." }, types: { title: "Causas y Factores de Riesgo", intro: "El proceso de daño arterial está directamente dictado por factores del estilo de vida y genéticos:", items: ["Colesterol Alto (Dislipidemia): Especialmente niveles elevados de lipoproteínas de baja densidad (LDL) y bajos niveles de colesterol protector (HDL).", "Tabaquismo: Fumar es devastador; los químicos del tabaco queman directamente la pared arterial y hacen que la sangre sea muy pegajosa, acelerando masivamente la placa.", "Hipertensión (Presión arterial alta constante): La alta presión mecánica rompe físicamente las paredes de las arterias con el tiempo.", "Diabetes Mellitus y Resistencia a la Insulina: El exceso prolongado de azúcar en la sangre daña y oxida de manera profunda y silenciosa los vasos sanguíneos enteros.", "Sedentarismo, obesidad, dieta rica en ultraprocesados y grasas saturadas, y la edad avanzada.", "Antecedentes genéticos familiares: Familiares cercanos que sufrieron ataques al corazón o derrames cerebrales a temprana edad."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Los médicos realizan chequeos preventivos e imágenes para detectar bloqueos ocultos:", items: ["Análisis de Sangre Rápidos: Perfil lipídico completo (colesterol y triglicéridos) y pruebas de azúcar en sangre.", "Ecografía Doppler: Usa ultrasonido para medir el flujo de sangre y detectar visualmente los bloqueos (se usa comúnmente en el cuello para las carótidas o en las piernas).", "Prueba de esfuerzo (Ergometría): Evaluación de la función del corazón en una cinta de correr.", "Índice Tobillo-Brazo (ITB): Compara la presión de la sangre en el tobillo con la del brazo para detectar si las arterias de las piernas están tapadas.", "Puntuación de Calcio Coronario (Escáner TC de corazón): Una tomografía rápida sin contraste que mide exactamente la cantidad de placa endurecida y calcificada acumulada en las arterias del corazón, revelando el riesgo de infarto futuro a 10 años.", "Angiografía (Cateterismo): Prueba invasiva definitiva que inyecta un contraste de tinte en la sangre bajo rayos X para ver los bloqueos arteriales exactos y destaparlos en ese momento."] }, treatment: { title: "Tratamientos", intro: "El daño establecido es difícil de revertir completamente, pero se puede detener la progresión agresivamente y desatascar las tuberías bloqueadas:", subsections: [ { title: "Control de Estilo de Vida y Medicamentos", items: ["Modificación Estricta del Estilo de Vida: Es el paso primordial. Dejar absolutamente el cigarrillo, seguir una dieta cardíaca (como la dieta Mediterránea, baja en grasas trans, sodio y carnes rojas) y ejercicio aeróbico de 30 a 45 minutos al día.", "Estatinas (como Atorvastatina, Rosuvastatina): Los medicamentos de oro. Reducen drásticamente el colesterol LDL en el hígado y, más importante, reducen la inflamación en las arterias y 'estabilizan' o endurecen las placas blandas para evitar que se rompan y formen coágulos.", "Medicamentos Antiagregantes Plaquetarios: Como la Aspirina a dosis baja o el Clopidogrel. Hacen que las plaquetas de la sangre sean 'resbaladizas', para que si una placa se rompe, la sangre no coagule y no se produzca un infarto.", "Control de Enfermedades Bases: Pastillas agresivas para controlar la presión arterial (IECA o Betabloqueadores) y la diabetes."] }, { title: "Procedimientos Quirúrgicos de Revascularización", items: ["Angioplastia y Stent: Un cardiólogo o cirujano vascular infla un balón diminuto dentro de la arteria bloqueada (en el corazón o piernas) para aplastar la placa contra las paredes y abrir el vaso, dejando implantado un pequeño tubo de malla metálica (stent) para que la arteria no colapse.", "Endarterectomía Carotídea: Cirugía donde se abre el cuello y se 'limpia' literalmente la placa que tapa la arteria carótida para prevenir un derrame cerebral inminente.", "Cirugía de Bypass (Derivación): Si hay demasiados bloqueos masivos, el cirujano utiliza un vaso sanguíneo sano de la pierna o el pecho para crear un puente (bypass) que saltee el tramo tapado, conectando la sangre limpia por encima y por debajo del bloqueo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La aterosclerosis requiere control médico y revisiones anuales desde la adultez. Pero acude a una sala de emergencias a máxima velocidad si sientes:", items: ["Opresión insoportable, dolor punzante, ardor o pesadez en el centro de tu pecho, que sube a la garganta o viaja a los brazos", "Entumecimiento repentino, parálisis, caída de la mitad de tu cara o la incapacidad repentina para poder hablar, balbucear o pronunciar palabras correctamente (Emergencia de Ictus Cerebral)", "Sufres calambres musculares tan severos en las piernas al caminar que te obligan a pararte tras pocos metros"] } },
'Almorranas' : { intro: "Las almorranas, médicamente y clínicamente conocidas bajo el término correcto de hemorroides, son conglomerados o cojinetes de venas normales situadas en la zona inferior del recto y en el ano que se han hinchado, inflamado y dilatado de forma patológica, dolorosa y persistente.", whatIs: { title: "¿Qué son las Hemorroides (Almorranas)?", text: "Es una afección extraordinariamente común y extendida (afectando a más de la mitad de las personas antes de los 50 años). Las venas del canal anal están diseñadas para actuar como pequeñas almohadillas llenas de sangre que ayudan a cerrar el ano y controlar la defecación. Sin embargo, cuando estos vasos sanguíneos y sus tejidos de soporte sufren un exceso de presión fuerte y repetitiva, las paredes de las venas se estiran anormalmente, se hinchan de forma irreversible, se irritan y se vuelven sumamente frágiles, colgando fuera de su posición. Son el equivalente rectal a sufrir de venas varicosas en las piernas." }, symptoms: { title: "Síntomas y Alertas Hemorroidales", intro: "La sintomatología es muy dependiente de la ubicación exacta donde las venas se hayan hinchado (adentro del intestino o afuera en la piel anal):", groups: [ { name: "Hemorroides Internas (Dentro del Recto)", items: ["Sangrado rectal indoloro: El síntoma indiscutible más común. El paciente nota manchas repentinas de sangre de color rojo brillante o rutilante en el papel higiénico al limpiarse, o gotas goteando libremente en la taza del inodoro justo al final de la evacuación intestinal.", "Por lo general, al estar dentro, NO duelen ni se sienten, ya que el recto carece de fibras nerviosas sensibles al dolor.", "Prolapso: En casos avanzados, las hemorroides internas se agrandan tanto que, al empujar para defecar, el bulto blando de venas es empujado y sale físicamente a través del orificio del ano hacia el exterior, causando una sensación de bulto y plenitud (que a veces el paciente debe empujar de nuevo hacia adentro con el dedo)."] }, { name: "Hemorroides Externas (Debajo de la Piel que Rodea el Ano)", items: ["Picazón profunda, rascado constante e irritación ardiente alrededor de los pliegues de la zona anal.", "Dolor sordo, molestia punzante e incomodidad física evidente, que empeora abrumadoramente al estar mucho tiempo sentado en sillas duras o al higienizarse.", "Aparición de uno o varios bultos blandos, hinchados y sensibles al tacto justo en los bordes del orificio anal exterior.", "Trombosis Hemorroidal (Complicación severa): Si la sangre de una hemorroide externa se estanca, de pronto puede formar un coágulo de sangre duro (trombo). Esto genera una urgencia muy dolorosa: de un día para otro se forma un bulto muy tenso, firme, de color morado o azulado en el borde del ano que causa un dolor punzante y agónico al sentarse, toser o moverse."] } ], warning: "Importante advertencia de salud: NUNCA, bajo ningún concepto clínico, asumas por tu cuenta que cualquier sangrado rectal, heces oscuras u observadas con manchas provienen solo de 'simples almorranas'. El sangrado indoloro también es la señal principal, cardinal y de advertencia de problemas letales tempranos como el Cáncer Colorrectal o la enfermedad de pólipos malignos intestinales, y exige obligatoriamente evaluación por un digestivo o colonoscopia." }, types: { title: "Causas y Factores Desencadenantes", intro: "El debilitamiento venoso se desencadena principalmente por el estrés mecánico, la presión pélvica crónica y problemas en el tránsito de heces:", items: ["Estreñimiento Crónico y Esfuerzo Severo (La Causa Rey): Tener heces duras obliga a la persona a apretar, hacer muchísima fuerza empujando (maniobra de Valsalva profunda) de manera prolongada en el inodoro o baño; esto dispara la presión sanguínea en la pelvis, inflando las venas y destruyendo la elasticidad anal.", "Permanecer sentados periodos extremadamente largos en la taza del retrete (leyendo revistas, usando teléfonos móviles), lo que relaja los músculos del periné y hace que las venas caigan llenas de sangre y tensión.", "El Embarazo, Gestación y Parto: Una causa altísima. El peso enorme del útero en crecimiento aplasta directamente la gran vena pélvica impidiendo el retorno de la sangre de la mitad inferior del cuerpo, sumado al inmenso y violento esfuerzo abdominal de empujar durante el trabajo de parto que causa explosiones hemorroidales inmediatas.", "Obesidad o sobrepeso marcado, tener una dieta sistemáticamente ausente, pobre en verduras y deficiente en fibra pura o cereales, sedentarismo laboral y realizar levantamientos pesados de pesas en el gimnasio a diario, o trabajos bruscos continuos de construcción."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un especialista (Cirujano General o Proctólogo / Gastroenterólogo) confirma las hemorroides de manera segura e indolora:", items: ["Inspección Externa e Historial Clínico: El médico observa directamente el anillo anal externo buscando fisuras o bultos trombosados y examina el área.", "Tacto Rectal (Examen Digital Rápido): El médico introduce un dedo enguantado suavemente lubricado unos centímetros en el conducto anal. Sirve para evaluar y comprobar el tono de los músculos del esfínter de la persona, buscar crecimientos extraños o bultos duros cancerígenos y masas, y palpar venas dilatadas gruesas internas.", "Anoscopia o Proctoscopia Corta: A veces el médico introduce un pequeño y corto tubo acrílico hueco transparente con luz un par de centímetros para abrir e inspeccionar visualmente y a todo color el estado interior de las paredes del canal del recto y las hemorroides.", "Colonoscopia General Completa: Si el paciente tiene edad de riesgo (usualmente mayor de 45-50 años) o sangra rojo oscuro, el especialista mandará obligatoriamente una cámara por todo el intestino largo preventivamente en hospital ambulatorio para certificar la exclusión o buscar tumores pólipos colon-rectales subyacentes escondidos arriba de las hemorroides."] }, treatment: { title: "Tratamientos", intro: "El tratamiento progresa en pasos; la inmensa mayoría de las crisis y almorranas inflamadas desaparecen con remedios en casa y reeducación, reservando las intervenciones a casos sangrantes y fallidos rebeldes que colapsan la calidad de vida:", subsections: [ { title: "Manejo Tópico, Conservador e Higiénico Causal", items: ["Aumento Radical y Drástico de Fibra en la Dieta Diaria Pura y Fluida: Consumir sin falta suplementos naturales a diario de cáscara de Psyllium (Metamucil), abundante avena pura, legumbres y, lo más crítico, un consumo estricto de dos a tres litros de agua continuos. La idea curativa principal es que las heces fecales sean esponjosas, hidratadas, abundantes y resbaladizas, para poder defecar velozmente en menos de 2 minutos y sin empujar o apretar ningún músculo doloroso y evitar el trauma interno al conducto.", "Baños de Asiento (Sitz Baths): Sentarse, sumergir el culo y remojar el área inferior en una palangana, bidé o bañera pequeña conteniendo agua tibia pura a temperatura calmante (sin jabones) durante 10 a 15 minutos, dos o tres veces fuertes al día. Esta terapia humilde alivia poderosamente los espasmos musculares anales, afloja el músculo constreñido, mejora el riego de las venas de retorno y quita la picazón quemante.", "Cremas Antihemorroidales Tópicas y Supositorios (Manejo Agudo Temporal): Utilizar ungüentos, pomadas o toallitas que contienen fórmulas con Hidrocortisona local, anestésicos de Lidocaína o extracto de Hamamelis (Ejemplo comercial: Preparación H). Reducen dramáticamente la inflamación y dolor punzante ardiente. Sin embargo, no deben usarse ni untarse continuamente durante más de una semana bajo ningún concepto porque la cortisona adelgaza severamente, atrofia y pudre la piel del ano permanentemente y la empeora.", "Educación Urinaria y de Baño: No aplazar jamás el impulso urgente o el deseo matutino natural de ir a obrar o al baño. No utilizar por higiene toscos papeles higiénicos ásperos perfumados o rasposos que causen microcortes; lavar la zona suavemente con agua íntima en bidet, ducha o en su defecto usar toallitas limpiadoras húmedas puras de bebé."] }, { title: "Procedimientos Quirúrgicos y Mínimamente Invasivos Especializados (Gastro-Proctología)", items: ["Ligadura con Banda Elástica de Goma: El tratamiento ambulatorio en consulta e indoloro más común, exitoso y habitual del mundo para las hemorroides internas grandes y prolapsadas crónicas que sangran. El especialista liga, succiona o atrapa firmemente la base interior de la vena abultada con anillos de gomitas de látex apretadas, ahorcándola. La vena, estrangulada y privada de flujo de la sangre de forma total, se marchita, se necrosa, se pudre en 3 a 5 días y simplemente se cae muerta marchita por el inodoro junto con una cicatriz curativa natural.", "Escleroterapia Inyectable o Coagulación Láser (Fotocoagulación Infrarroja): Procedimientos muy veloces en consulta que usan inyecciones de químicos cicatrizantes letales o potentes quemaduras láser caloríficas intensas directas que achicharran el tejido sangrante encogiéndolo fuertemente de cicatriz endurecida, matando y encogiendo así los vasos capilares.", "Extirpación de Trombosis Hemorroidal Externa: Si el paciente con gran dolor punzante en el margen se presenta con el trombo agudo las primeras 48 o 72 horas insoportables en urgencia, el médico bajo rápida anestesia local cortará y extirpará, vaciando de forma manual el saco del coágulo azul atascado brindando un enorme e inmediato e instantáneo alivio doloroso y agudo a la crisis de compresión.", "Hemorroidectomía (Cirugía Mayor Abierta General Curativa): Realizada por un proctólogo mediante anestesia espinal, raquídea y sedación. Es la extracción definitiva y extirpación de raíz radical total curativa de todas y cada una de las hemorroides colgantes enfermas (cortando en bloque los tejidos). Asegura que jamás volverá, curando casos extremos avanzados grados 3 y 4 o externos gigantes combinados. Es sumamente temida en pacientes dado que su dolor en la recuperación de la primera semana para las primeras veces de ir al baño al evacuar es brutal, postoperatoriamente punzante doloroso agudo y duro en la carne perianal operada cruda."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Dirígete y contacta de inmediato al doctor especialista, proctólogo en clínica o servicio médico directo y urgencias gastrointestinales si experimentas, adviertes o te percatas al ir al baño de:", items: ["El sangrado o manchado en el retrete es excesivamente copioso, no frena de ninguna forma y resulta inusualmente abundante, o si las deposiciones y materias te lucen extrañamente alquitranadas de un marrón negruzco denso asfáltico (sangrado estomacal oculto y alto que marca alta gravedad gástrica úlceras o patologías graves digestivas, nunca hemorroides)", "Tienes síntomas o sensación de debilidad extrema postrante de repente, palidez mortal blanca severa o te sientes débil por un gran desvanecimiento y falta masiva por mareos crónicos y continuos a causa directa repetitiva de una pérdida de sangre (por gran sangrado constante silencioso diario goteo anémico)", "Si una hemorroide exterior hinchada se vuelve masiva o repentinamente tan dura de piedra azulada purpurina oscura y dolorosa causante de incapacidad total o dolores para siquiera caminar o posarte sentada una sola silla y sufres gran fiebre o temblores dolorosos agudos de punción en crisis"] } },
'Lipoma cervical' : { intro: "Un lipoma cervical es un crecimiento o tumor localizado completamente inofensivo, liso y de naturaleza puramente benigna compuesto en su totalidad de tejido y células de grasa acumulada, que se desarrolla lenta y superficialmente de forma encapsulada justo por debajo de la piel en cualquier parte de la región del cuello, la base posterior del cuello, la nuca o debajo de la mandíbula.", whatIs: { title: "¿Qué es un Lipoma de Cuello (Lipoma Cervical)?", text: "Es biológica, estructural y patológicamente clasificado como el tumor de tejidos blandos, carne y grasos más abundante y común que aparece sin más en el cuerpo de los adultos en general. Es primordial recalcar con fuerza tranquilizadora que estos bultos en el cuello NO son cánceres mortales ni tumores patológicos diseminantes de ninguna categoría. Generalmente se sitúan en el plano blando que separa el tejido superficial de la piel delgada visible exterior y las capas gruesas de los músculos interiores que cubren al cuello humano. Se encuentran encapsulados dentro de una delgada y fina membrana biológica cerrada que contiene el lobulillo o la grasa blanda y amarillenta. Crecen a un ritmo extremadamente pausado y lentísimo durante varios y dilatados años, la mayor parte del tiempo, deteniendo su expansión de tamaño una vez alcanzan un tamaño de un par de centímetros, manteniéndose pasivos o desapercibidos." }, symptoms: { title: "Síntomas Clásicos y Características Táctiles Distintivas", intro: "Los síntomas en sí rara vez provocan una queja médica directa generalizada salvo por una molestia visual o preocupación puramente física de apariencia abultada o un requerimiento estético, ya que en la inmensa porción del historial médico consisten asintomáticamente en:", groups: [ { name: "Características Visibles al Tacto (Exploración de Piel Directa y Externa)", items: ["Aparición notoria pero lenta a la palpación de un bulto redondo pequeño de textura y composición sumamente suave, de naturaleza gomosa blanda asombrosa (similar a presionar masilla u goma de borrar) y que, críticamente para su diagnóstico natural benigno, es extremadamente móvil, se hunde, se desvía, es resbaladizo, se aplasta con facilidad o se mueve al tratar de presionarlo libremente contra el tejido con uno de tus dedos por la piel.", "Casi el cien por cien absolutos de los casos descritos nunca son en absoluto dolorosos, no pican o provocan escozor o gran enrojecimiento superficial si el tejido cutáneo encima es sano o el bulto blando de grasa no ha sido apretado intencionalmente agresivamente al tocarlo.", "El crecimiento general biológico es casi imperceptible en meses de desarrollo en los cuales aumentará gradualmente sin alarma o sin cambio súbito.", "La piel, la dermis exterior que lo recubre o envuelve se ve de manera habitual, de igual color y enrojecimiento al cuello de alrededor sin manchas, lesiones y con la superficie perfecta."] }, { name: "Síntomas Compresivos Molestos Interiores Extraños (Si el tamaño lo exige o crece en zona extraña nerviosa)", items: ["Si el tamaño que adquiere el lipoma llega a engrosar a proporciones de muchos centímetros densos e inusuales bajo los músculos del lado de las cervicales y cuellos gruesos, podría llegar en efecto muy excepcionalmente a presionar e impactar físicamente muy de cerca con ramificaciones y cuerdas y nervios pélvicos profundos originando o emitiendo dolor eléctrico agudo esporádico irradiado en hombros o nuca.", "Por su peso o tamaño grande excesivo crónico de la nuca causaría restricciones limitadas, pesadez leve o incomodidad extraña y un roce notable en las camisas y cuellos al poder mover y doblar por completo el grado del cuello del cuerpo o torcer y asomar la mirada al intentar mover los músculos que se topan apretados por esta masa."] } ], warning: "IMPORTANTE PRECAUCIÓN DE CUELLO EN MASA: Cualquier otro nódulo palpable o un repentino y asombroso abultamiento nodular aparecido y crecido en un lapso corto de velocidad asombrosa o rápida que localices en el centro del cuello e ingle linfática y por tanto resulte presentar al tacto una masa extremadamente rígida dura parecida en firmeza como piedra de pared rocosa, fuertemente pegada u adherida al tejido profundo fijo de los músculos y que sea dolorosa a presión o de rápido crecimiento general y veloz y que no tenga ninguna movilización que resbale. Estos síntomas mencionados de firmeza son una bandera de alarma roja o un requerimiento inmediato para biopsia de urgencia para un descarte maligno de tumores profundos en vías linfáticas o ganglios duros enfermos, quistes densos cancerosos e hinchazones agresivas por sarcoma del que NUNCA es propio un lipoma dócil." }, types: { title: "Causas Sistémicas, Factores e Hipótesis del Crecimiento", intro: "Los dermatólogos cirujanos aún desconocen una causa subyacente directa de porqué un bulto y el tejido y el desarrollo de grasa muten espontáneo de aglomeramiento, sin embargo los mayores desencadenantes de origen natural de sospecha incluyen fuertemente:", items: ["El Peso Dominante del Componente Genético Familiar (Herencia de Familia Autonómica): Las características genéticas heredadas son enormemente el desencadenante de lejos, principal causante general, o mayormente predominantes en pacientes con varios; si ambos o uno solo de los padres de tu línea consanguínea padecieron o les nacieron a menudo o han presentado de adultos varios e idénticos y molestos bultos de lipoma blando al cuerpo o de forma múltiple y brazos en sí, en general tu riesgo predecible y carga para crearlos a ti se incrementa en altos índices fuertemente.", "La Edad Biológica Prevalente Fija: Aparecen usualmente entre los pacientes adultos de la etapa mediana media de la vida que están experimentando y en edades medias que transcurren aproximadamente la zona poblacional estadística entre un bloque grande los cuarenta años a los gloriosos sesenta o en las edades por los 40 a 60 años en particular. No suelen en efecto ni manifestarse biológicamente con gran frecuencia y de forma natural a la mayoría de casi todas las franjas y porciones de la edad y pubertad de niños sanos.", "Problemas Endocrinos e Historial Fuerte Metabólico Adiposo: Los pacientes que lidian permanentemente en sí o crónicamente a fondo padecen enfermedades de la alta asimetría general u obesidad alta y patologías, alteraciones grasas crónicas corporales grandes en el hígado graso o a su vez las inmensas ingestas con las descompensaciones o altos rangos que sufren de colesterol pesado, o diabetes alta del control endocrinológico del metabolismo que aglomeren grasa extra, sufren incidencias e infecciones propensas que en ocasiones incitan la aparición o acumulo tumoral o lipomatosis general múltiple.", "Teoría de Traumatismo Mecánico (Conmoción Contusa Local): Resulta ser sumamente frecuente para los cirujanos presenciar un inicio natural agudo y posterior que ocurre poco luego y como resultado e impacto orgánico del cuerpo originado a meses después del desarrollo profundo de que una persona reciba directamente un profundo y masivo golpe cerrado e impacto brutal grande o gran hematoma sobre la zona particular, que al curarse reaccione hiperactivamente un crecimiento y lipoma nuevo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente la evaluación del experto y ojo clínico dermatológico puro de cabecera visual diagnostican tranquilizadoramente estos en unos momentos mediante tácticas en consultorio para excluir lesiones y nódulos profundos subyacentes letales de forma infalible:", items: ["Examen Médico Visual Directo Físico y Análisis Palpatorio Experto: El médico cirujano evaluará de manera física externa visual las propiedades estéticas externas y mediante un tacto generalizado con los dedos las dimensiones concretas y verificará con contundencia médica si el quiste o lipoma presenta resbalabilidad blanda (movilidad suave), es suave no adherida para establecer e indicar visualmente las probabilidades clínicas seguras e indudablemente altas de que sea benigno el tumor adiposo sin pedir nada extra.", "Ecografía o Ultrasonido Simple de las Partes Blandas Cervicales y del Tejido Cutáneo en Consulta: Esta prueba tecnológica de imagen segura a la piel que resulta de onda rápida y sumamente rutinaria indolora confirma e identifica inequívocamente al cien por cien que el tejido interno denso está y se halla compuesto en la bolsa blanca y compactamente solo y exclusivamente de células adiposas y lobulillos de la grasa inerte amarilla bajo la piel en una imagen o pantalla para diferenciar o distinguir la bolsa blanca asombrosamente de otro ganglio linfático e inflamado por bacteria o un quiste lleno de agua/líquido.", "Resonancia Magnética Anatómica 3D (RM en máquina o Escáner CT de Tomografía): Opcional o utilizada a la larga sólo y únicamente en el escenario muy excepcional que ocurre si en sí un gran lipoma atípico a la profundidad haya invadido gran o enorme densidad corporal profunda sub-muscular creciendo enorme que aparente, abrace y sea masivo ahogando los tractos que enreden vías profundas de arterias de cuello mayor en la profundidad de tu masa muscular de tu cervical que en la placa complique operarse con los nervios entrelazados extrañamente y cause una seria sospecha a liposarcoma atípico canceroso en cuello que en radiología requiera planeamiento extenso anatómico para evitar grandes cirugías perjudiciales para los nervios durante corte general e intervención del cuello.", "Biopsia Histológica del Tejido con Aguja Extirpada Cilíndrica (Punción PAAF): Solo en sí y estrictamente requerido si en algún escenario en tu clínica de imagen o prueba el bulto o un bulto no es la grasa e imágenes arrojan de duda sospechosa u arrojan masas tumorales duras mixtas a las del cáncer (Sarcomas raros lipomatosos agresivos en la piel) de las que los doctores sacan al instante bajo aguja gruesa fina un ínfimo pedacito minúsculo por piel en quirófano de la carne sospechosa extrayéndola para estudiarla al microscopio de anatomía y afirmar sin dudas el grado de la benignidad de forma segura final."] }, treatment: { title: "Tratamientos", intro: "En abrumadora mayoría o totalidad general de todo un alto y vasto rango en diagnósticos estables y benignos indoloros a lo largo y por tiempo la decisión final de la conducta de actuación y el plan elegido se decantan médicamente u optan al no llevar tratamiento directo del bulto si la persona convive estéticamente o médicamente e idóneamente de forma silenciosa u óptima dejando al pequeño lipoma cervical intacto para preservar su salud sin intervenir:", subsections: [ { title: "Opciones Generales Terapéuticas Procedimentales Definitivas de Acción y Retiro Extirpador", items: ["Plan y Enfoque Quirúrgico Menor de Resección Completa Quirúrgica Escisional Abierta Definitiva Local: Es la resolución u opción definitiva permanente, el abordaje total y la cura absoluta curativa principal de raíz para la elección estética si al paciente realmente ya le incomoda visualmente la estética fea del nódulo inflamado bulto a su lado, en que aumenta el dolor por rozamiento excesivo o cuando es un diagnóstico extraño. El cirujano general experto anestesiará con pinchazo el área en consulta local y mediante anestésico cutáneo y hace quirúrgicamente e indoloro un pequeñísimo corte o una corta e imperceptible incisión con un bisturí abriendo la parte de la piel blanda general profunda extrayendo físicamente u oralmente sacando intacta o sacando de raíz a mano de cirujano la cápsula envuelta, bola, saquito con la membrana de la pared blanda entera a fondo llena enteramente de la amarilla grasa pura, cerrando las paredes a suturas e impidiendo así que queden focos mínimos que faciliten y posibiliten de manera que vuelva e inicien a surgir por un renacimiento recaídas lipomatosas, con alta e impecable garantía de eliminación a largo plazo y curativo total.", "Extracción mediante Vaciado de Liposucción Profunda y Técnica Suctora: Si se opta por razones por estética extrema u estética de belleza puras ya que es el bulto blando bastante expandido al cuello general del paciente o bastante ancho de gran volumen largo a todo lo largo y de grasa que no desearía tener cicatrices estéticas o feas largas incisivas post-operatorias con marca, un cirujano de belleza e injerto plástico mete cánulas y jeringas de absorción lipoaspiradora con pequeñas punciones aspirando disolviendo o succionando fuertemente el sebo licuado y vaciando el contenido blanco, aunque estadísticamente este método superficial es peor y no limpia al saco cápsula entera que lo envolvía lo cual trae muchas veces como riesgo secundario con posibilidad a meses vista al recrudecimiento celular, propensión al resurgimiento posterior de llenado nuevo en bolsas, al quedarse células de pared del lipoma anterior vivo o vivo interno a regenerar.", "Terapia Inyectable Mínima Lipo-Disolvente por Aguja Cutánea de Corticosteroide y Fármacos Enzimáticos (Kybella / Ácido Desoxicólico Disolutorio Químico): Utilizados inyectados de manera aislada en raras excepciones menos comunes a cirugías o raras en países con acceso alternativo costoso, este ácido quemador se inyecta fuertemente e internaliza una sustancia líquida química muy fuerte y reductora natural del cuerpo adentro e internamente del globo masivo adiposo por la piel para descomponer destructivamente encogiendo el núcleo de toda o gran parte de la materia viva grasosa del depósito interior y forzar quemándola fuertemente a las células de que se reabsorban logrando destruir un par de medidas al bulto para hacerlo a la vista plano o alisar sus rebordes estéticos del cuello o para pacientes incapaces inhabilitados inoperables al rechazar de raíz la extracción abierta tradicional en bisturí."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Reserva de inmediato una exploración, valoración de triaje en clínica, atención profunda o visita general con el equipo o unidad en cirugía dermatológica a gran nivel de control prioritaria exhaustiva o cita a dermatología especialista, u otorrino, si has advertido u originado de repente una gran sospecha por presentar tu y notar:", items: ["El abultamiento de masa del tamaño general de la nuca ha empezado a originar biológicamente crecimiento acelerado y de veloz expansión de repente y visible general y rápida velocidad asustadiza o sorpresiva masivamente, en muy poco transcurso del tiempo o en un periodo corto extraño visible que se triplique y desborde sin ser controlable.", "Presentas e identificas en ti molestias que te limitan ahogándote un roce agudo al mover con rigidez las áreas musculares cercanas, si al tacto este mismo nódulo lipomatoso produce o ha tornado en intenso daño punzante e inesperado muy duro que irradia dolor o ha adoptado rigidez que traba tu articulación, al paso del nervio impidiéndote o causándote la imposibilidad de deglutir fácil y tragar e imposibilitando o cerrando parcialmente el cuello que genere compresión limitante del canal en tu faringe y área digestiva principal.", "Aparece u ocurre algún endurecimiento petrificante fijo no resbaladizo, cambios colorados agresivos fuertes morados a la mancha de la dermis encimada y una rigidez pegada que no desliza a presión u adherencia rocosa del bulto al fondo que genere gran inflamación de fiebre sistémica y la inflamación exterior caliente de piel no típica en absoluto para un suave e inerte y sencillo acúmulo natural adiposo blando sano de una de una forma asombrosamente anormal."] } },
'Asma inducido por el ejercicio' : { intro: "El asma inducido por el ejercicio, médicamente conocido como broncoconstricción inducida por el ejercicio (BIE), es un estrechamiento temporal de las vías respiratorias inferiores que se desencadena por la actividad física aeróbica vigorosa.", whatIs: { title: "¿Qué es el Asma Inducido por el Ejercicio?", text: "Normalmente, al respirar por la nariz, el aire se calienta y humedece antes de llegar a los pulmones. Durante el ejercicio intenso, las personas tienden a respirar rápida y profundamente por la boca, inhalando aire frío y seco. Este impacto físico y térmico provoca una inflamación aguda y un espasmo (contracción) de los músculos que rodean los bronquios, estrechando los conductos y atrapando el flujo de aire, lo que genera un ahogo asfixiante poco después de iniciar el esfuerzo o al detenerse." }, symptoms: { title: "Síntomas y Alertas Respiratorias", intro: "Los síntomas suelen alcanzar su punto máximo entre 5 y 15 minutos después de iniciar el ejercicio, o justo al terminarlo:", groups: [ { name: "Síntomas Pulmonares", items: ["Tos seca y persistente (a menudo el primer o único síntoma evidente en los niños)", "Sibilancias (un silbido agudo o pitido audible al intentar exhalar o vaciar los pulmones)", "Opresión profunda en el pecho, descrita como una banda apretada alrededor del tórax", "Falta de aire inusual, fatiga prematura y una sensación de asfixia desproporcionada al nivel de condición física del individuo", "Evitación del deporte o bajo rendimiento físico constante"] } ], warning: "Ignorar la opresión en el pecho y forzarse a seguir corriendo durante un ataque puede provocar una crisis de asma grave y asfixiante. Es vital detenerse y usar el inhalador de rescate al primer síntoma." }, types: { title: "Causas y Desencadenantes", intro: "El espasmo bronquial es provocado por el esfuerzo, pero se agrava enormemente por el entorno:", items: ["Inhalación de aire frío y seco (deportes de invierno como esquí o correr en la mañana helada).", "Contaminación ambiental y altos niveles de polen en el aire al ejercitarse en exteriores.", "Sustancias químicas irritantes, como los vapores de cloro concentrados en las piscinas cubiertas.", "Infecciones respiratorias recientes (como un resfriado o gripe que deja las vías aéreas sensibles).", "Tener asma crónica subyacente (el 90% de las personas con asma crónica también sufren asma por ejercicio)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es clínico y se confirma con pruebas de función pulmonar:", items: ["Espirometría basal: Para medir la capacidad pulmonar en reposo.", "Prueba de provocación con ejercicio: El paciente corre en una cinta rodante o pedalea en una bicicleta estática hasta agotarse; luego se repite la espirometría para comprobar si el volumen de aire cae significativamente (generalmente más de un 10-15%).", "Prueba de reversibilidad: Se administra un broncodilatador tras el ejercicio para comprobar si los conductos se abren y la respiración vuelve a la normalidad."] }, treatment: { title: "Tratamientos", intro: "El objetivo es prevenir el espasmo antes de que ocurra, permitiendo a la persona realizar cualquier deporte sin limitaciones:", subsections: [ { title: "Manejo Farmacológico y Profiláctico", items: ["Broncodilatadores de acción corta (SABA): Como el Salbutamol/Albuterol. Es el tratamiento de oro. Se deben inhalar 2 o 3 dosis aproximadamente 15 minutos ANTES de comenzar a hacer ejercicio para abrir y proteger los pulmones durante horas. También sirven como rescate si ocurre un ataque.", "Corticosteroides inhalados: Si el paciente tiene asma crónica o los broncodilatadores solos no bastan, se recetan inhaladores antiinflamatorios diarios (como Fluticasona) para calmar la sensibilidad base de los pulmones.", "Antagonistas de los receptores de leucotrienos (Montelukast): Una pastilla diaria que bloquea los químicos de la inflamación y es muy útil para el asma alérgica y deportiva.", "Modificación de la rutina: Realizar un calentamiento largo y progresivo (15 minutos) antes del ejercicio intenso, y un enfriamiento gradual; usar una bufanda sobre la boca en climas muy fríos para calentar el aire."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención médica de urgencia si:", items: ["Los síntomas no mejoran tras usar el inhalador de rescate (Salbutamol) después de un ataque", "La falta de aire es tan severa que no puedes hablar en oraciones completas", "Notas una coloración azulada o grisácea en los labios o las uñas (cianosis, señal crítica de falta de oxígeno)"] } },
'Enfermedad cardíaca isquémica' : { intro: "La enfermedad cardíaca isquémica (también llamada cardiopatía isquémica o enfermedad de las arterias coronarias) es la principal causa de muerte a nivel mundial. Es una afección en la que el flujo de sangre rica en oxígeno que llega al músculo del corazón se reduce críticamente o se bloquea por completo.", whatIs: { title: "¿Qué es la Cardiopatía Isquémica?", text: "El corazón necesita un suministro constante de sangre para latir. Esta sangre llega a través de las arterias coronarias. A lo largo de los años, depósitos de colesterol, grasa, calcio y células inflamatorias se acumulan en las paredes internas de estas arterias, formando una costra dura llamada 'placa' (aterosclerosis). A medida que las arterias se estrechan y endurecen, el corazón se asfixia lentamente. Cuando la demanda de oxígeno supera a la oferta (por ejemplo, al subir escaleras), el músculo cardíaco sufre isquemia (falta de riego), provocando un dolor opresivo y alarmante." }, symptoms: { title: "Síntomas y Señales de Alarma Crítica", intro: "La enfermedad puede progresar en silencio durante décadas, pero cuando se manifiesta, el dolor es inconfundible:", groups: [ { name: "Síntomas de Insuficiencia Crónica (Angina de Pecho)", items: ["Dolor o presión profunda, sorda y aplastante en el centro del pecho (como si un elefante estuviera sentado sobre el tórax)", "El dolor a menudo se irradia o viaja hacia el hombro izquierdo, el brazo izquierdo, el cuello, la mandíbula o la espalda", "Estos episodios de angina son típicamente provocados por el esfuerzo físico, estrés emocional, o frío extremo, y ceden rápidamente tras unos minutos de descanso o al tomar nitroglicerina"] }, { name: "El Infarto (Emergencia Aguda por Rotura de Placa)", items: ["Si la placa de colesterol se agrieta o se rompe, el cuerpo forma un coágulo de sangre masivo en segundos para intentar 'sellar' la herida, bloqueando el 100% de la arteria.", "Esto causa un Infarto Agudo de Miocardio (Ataque al corazón).", "El dolor opresivo no cede con el descanso, dura más de 15-20 minutos, y se acompaña de sudoración fría profusa, náuseas, vómitos, mareos extremos y un miedo inminente a morir."] } ], warning: "En las mujeres, en personas de la tercera edad y en diabéticos, los síntomas pueden ser atípicos (sin dolor de pecho evidente). Pueden sentir solo una fatiga extrema y repentina, falta de aire asfixiante, o dolor sordo en el estómago, lo que a menudo retrasa un diagnóstico vital." }, types: { title: "Factores de Riesgo Principales", intro: "La formación de placa está dictada por una mezcla letal de genética y estilo de vida:", items: ["Hiperlipidemia: Niveles altos de colesterol LDL ('malo') y bajos de HDL ('bueno').", "Tabaquismo: El factor modificable más destructivo, que oxida las grasas y corroe directamente las paredes arteriales.", "Hipertensión (Presión arterial alta): Golpea y micro-desgarra las arterias constantemente.", "Diabetes y Resistencia a la Insulina: El exceso de azúcar inflama sistemáticamente los vasos sanguíneos.", "Obesidad central (grasa abdominal), sedentarismo prolongado y estrés crónico.", "Historial familiar fuerte de infartos a edades tempranas (padres o hermanos antes de los 55 años)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El cardiólogo buscará obstrucciones anatómicas y evaluará la función de bombeo:", items: ["Electrocardiograma (ECG): Detecta daño eléctrico previo o si el paciente está sufriendo un infarto en ese mismo momento.", "Prueba de Esfuerzo (Ergometría): El paciente corre en una cinta para ver si el corazón sufre isquemia bajo demanda de trabajo.", "Ecocardiograma: Ecografía para ver el movimiento de las paredes del corazón y la fuerza de las válvulas.", "Angiografía Coronaria (Cateterismo Cardíaco): La prueba de oro y definitiva. Un tubo llega al corazón desde la muñeca o la ingle, inyectando un tinte que brilla en los rayos X, mostrando exactamente qué arteria está tapada y en qué porcentaje."] }, treatment: { title: "Tratamientos", intro: "El objetivo es abrir el flujo de sangre, aliviar el dolor, evitar la muerte del tejido (infarto) y prolongar la vida:", subsections: [ { title: "Manejo Farmacológico", items: ["Medicamentos antiagregantes: Aspirina diaria o Clopidogrel para evitar que las plaquetas formen coágulos mortales.", "Estatinas: Medicamentos esenciales (Atorvastatina, Rosuvastatina) que no solo bajan el colesterol, sino que estabilizan la placa para que no se rompa.", "Betabloqueadores e Inhibidores de la ECA: Reducen el ritmo cardíaco, bajan la presión arterial y quitan carga de trabajo al corazón.", "Nitroglicerina: Ensancha y dilata las arterias temporalmente para aliviar los ataques de angina al instante."] }, { title: "Revascularización Quirúrgica e Intervencionista", items: ["Angioplastia y Colocación de Stent (ICP): Durante el cateterismo, el médico infla un pequeño globo en la arteria tapada para aplastar la placa contra las paredes, e inmediatamente coloca un cilindro de malla metálica (stent) recubierto de medicamentos para mantener el conducto permanentemente abierto.", "Cirugía de Bypass Coronario (Derivación): En bloqueos masivos y múltiples, los cirujanos a corazón abierto toman una vena sana de la pierna o pecho y crean un 'puente' que salta la zona bloqueada, llevando la sangre limpia directamente al músculo que la necesita."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es una situación de máxima emergencia (Llama al 911/Emergencias) si:", items: ["Sientes un peso aplastante o ardor en el centro del pecho que dura más de cinco minutos", "El dolor irradia al brazo izquierdo, a ambos brazos, al cuello o a la mandíbula inferior", "Acompañas la molestia torácica de falta de aire aguda, sudores fríos, palidez o vómitos"] } },
'Tartamudeo' : { intro: "El tartamudeo (o disfemia) es un trastorno del habla en el que el flujo o la fluidez normal de las palabras se ve interrumpido por repeticiones, bloqueos o prolongaciones involuntarias de sonidos y sílabas.", whatIs: { title: "¿Qué es el Tartamudeo?", text: "Es una condición neurológica y del desarrollo. Las personas que tartamudean saben exactamente qué es lo que quieren decir, pero su cerebro y los músculos del habla pierden la coordinación temporal para producir la palabra de forma fluida. Es muy común en niños pequeños que están aprendiendo a hablar, pero en un porcentaje de casos persiste hasta la edad adulta, generando un fuerte impacto emocional y ansiedad social." }, symptoms: { title: "Síntomas y Señales de Conducta", intro: "Los síntomas pueden variar significativamente según la situación (empeorando con el estrés o hablando por teléfono):", groups: [ { name: "Síntomas Físicos y Vocales", items: ["Repetición de sonidos, sílabas o palabras enteras (ej. 'p-p-p-perro')", "Prolongación de sonidos dentro de una palabra (ej. 'sssssssol')", "Bloqueos silenciosos: Pausas completas en las que la persona intenta hablar pero no sale ningún sonido", "Tensión física visible en la cara, temblor de labios o mandíbula, y parpadeo rápido al luchar para sacar una palabra", "Sustitución de palabras: Cambiar rápidamente una palabra difícil por otra más fácil para evitar el tartamudeo"] } ], warning: "El mayor impacto del tartamudeo no es físico, sino psicológico: a menudo conduce al aislamiento social, evitación de hablar en público, baja autoestima y fobia social severa." }, types: { title: "Causas y Tipos", intro: "El tartamudeo se clasifica según su origen:", items: ["Tartamudeo del Desarrollo: El más común. Ocurre en niños menores de 5 años mientras sus habilidades de lenguaje aún están madurando. La genética juega un papel enorme (suele darse en familias).", "Tartamudeo Neurogénico: Puede aparecer a cualquier edad tras un daño cerebral, como un derrame cerebral, un tumor o un traumatismo craneoencefálico grave, donde las redes del habla se interrumpen.", "Tartamudeo Psicógeno: Es extremadamente raro; se origina tras un trauma emocional masivo o en ciertos trastornos psiquiátricos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es evaluado por un patólogo del habla y el lenguaje (logopeda):", items: ["Evaluación del habla: El terapeuta escuchará a la persona hablar en diferentes contextos (leyendo en voz alta, conversando bajo presión) para analizar el tipo y la frecuencia de las disfluencias.", "Evaluación del impacto psicosocial: Medir cómo afecta el tartamudeo a la vida diaria y escolar/laboral del paciente.", "Evaluación del desarrollo (en niños) para diferenciarlo de las disfluencias normales de la infancia temprana."], note: "" }, treatment: { title: "Tratamientos", intro: "No existe una 'cura' rápida en adultos, pero hay terapias muy efectivas para mejorar la fluidez y reducir la ansiedad:", subsections: [ { title: "Manejo y Terapia del Habla", items: ["Terapia del Habla y Lenguaje (Logopedia): Es el tratamiento principal. Enseña al paciente técnicas de 'habla fluida' (como hablar más lento, prolongar ligeramente las vocales y controlar la respiración diafragmática) para reducir los bloqueos.", "Terapia Cognitivo-Conductual (TCC): Fundamental en adultos para cambiar las formas de pensar sobre el tartamudeo, reducir el pánico al hablar y disminuir la evitación de situaciones sociales.", "Dispositivos electrónicos: Se utilizan auriculares especiales que reproducen la voz de la persona con un ligero retraso o alteración de tono (retroalimentación auditiva retardada), lo que neurológicamente induce fluidez en algunos pacientes.", "Apoyo para padres: En los niños, el tratamiento a menudo se centra en enseñar a los padres a hablar de forma más relajada y a no presionar ni interrumpir al niño cuando se bloquea."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca la evaluación de un terapeuta del habla si:", items: ["El tartamudeo en un niño dura más de 6 meses, empeora, o ocurre junto con tensión física visible en el rostro", "El niño empieza a evitar hablar o parece frustrado", "Eres un adulto y el tartamudeo te está causando problemas serios de estrés, ansiedad o limitando tu carrera profesional"] } },
'Blefaroespasmo' : { intro: "El blefaroespasmo es una contracción muscular involuntaria, crónica y espasmódica de los músculos de los párpados. En casos severos, puede causar el cierre forzado de los ojos hasta el punto de generar 'ceguera funcional'.", whatIs: { title: "¿Qué es el Blefaroespasmo?", text: "Forma parte de un grupo de trastornos neurológicos del movimiento llamados distonías. No se trata del simple 'tic' o temblor temporal en el ojo que la mayoría de la gente tiene por cansancio o exceso de café (mioquimia). El blefaroespasmo (específicamente el 'esencial benigno') es un cierre de los párpados bilateral, fuerte, incontrolable y crónico, originado por un fallo en los ganglios basales del cerebro, que son los encargados de regular la coordinación muscular." }, symptoms: { title: "Síntomas y Evolución", intro: "La afección suele ser progresiva y comienza de manera muy sutil:", groups: [ { name: "Síntomas Visuales y Motores", items: ["Inicio temprano: Aumento en la frecuencia del parpadeo, sensación de sequedad ocular, irritación o gran sensibilidad a la luz brillante (fotofobia).", "Desarrollo: Parpadeo que se convierte en espasmos fuertes, guiños prolongados o contracciones que obligan a cerrar los ojos (apraxia de apertura palpebral).", "Casos severos: Los párpados pueden cerrarse con tanta fuerza que la persona queda 'ciega' temporalmente, siendo incapaz de abrirlos durante minutos u horas, impidiendo leer, conducir o caminar seguro.", "El espasmo afecta siempre a ambos ojos al mismo tiempo, aunque puede empezar en uno.", "Los síntomas desaparecen por completo mientras la persona está profundamente dormida."] } ], warning: "Aunque los ojos (la córnea, la retina) están perfectamente sanos y ven bien, el paciente puede quedar legal y funcionalmente ciego si el cerebro no permite que los párpados se abran." }, types: { title: "Causas y Desencadenantes", intro: "La causa médica exacta del tipo 'esencial' se desconoce, pero el espasmo puede empeorar o desencadenarse por:", items: ["Fatiga severa, estrés emocional intenso o falta de sueño", "Luces muy brillantes, resplandor del sol o viento fuerte", "Síndrome de Ojo Seco severo (a menudo coexiste y empeora el problema)", "Efecto secundario de ciertos medicamentos (como algunos fármacos psiquiátricos para el Parkinson o neurolépticos)", "A veces, el blefaroespasmo se extiende a la boca y la mandíbula inferior, una condición combinada conocida como Síndrome de Meige."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico estrictamente clínico por parte de un oftalmólogo o neurooftalmólogo:", items: ["Examen físico ocular completo: Para descartar que la causa sea una irritación severa de la córnea (como un cuerpo extraño o glaucoma) que esté forzando al ojo a cerrarse por protección.", "Evaluación Neurológica: Para observar el patrón de los espasmos y diferenciarlo del espasmo hemifacial (que afecta a un solo lado de la cara entera, no solo a ambos ojos)."], note: "No existe un análisis de sangre ni un escáner cerebral por resonancia magnética que pueda 'ver' el blefaroespasmo esencial." }, treatment: { title: "Tratamientos", intro: "No tiene cura definitiva, pero sus síntomas pueden controlarse drásticamente en la gran mayoría de los pacientes:", subsections: [ { title: "Terapia de Primera Línea y Cirugía", items: ["Inyecciones de Toxina Botulínica (Botox): Es el tratamiento de oro, el más seguro y exitoso. Se inyectan cantidades minúsculas de la toxina directamente en los músculos alrededor del ojo y los párpados. Esto paraliza o debilita temporalmente el músculo responsable del espasmo. El alivio llega en unos días y dura de 3 a 4 meses, tras lo cual se debe repetir la inyección de por vida.", "Gotas Lubricantes (Lágrimas Artificiales): Tratamiento indispensable para combatir el ojo seco, que es un fuerte desencadenante de las contracciones.", "Medicamentos Orales: Se usan (como clonazepam, lorazepam o trihexifenidilo) si el Botox pierde efecto, aunque suelen tener resultados mixtos e impredecibles y muchos efectos secundarios como somnolencia.", "Miectomía Quirúrgica: Si las inyecciones de Botox fallan por completo, el cirujano oftalmólogo puede realizar una operación para extirpar parte o la totalidad de las fibras de los músculos del párpado (orbicular de los párpados) responsables de forzar el cierre del ojo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita atención neuro-oftalmológica si:", items: ["Tienes espasmos o parpadeos tan fuertes o continuos en ambos ojos que te impiden mantenerlos abiertos por varios segundos", "Tus párpados se cierran solos con fuerza mientras estás intentando conducir un coche o caminar en la calle", "El cierre del ojo está acompañado de otros tics faciales en la boca o el cuello"] } },
'Diverticulosis' : { intro: "La diverticulosis es una afección anatómica muy frecuente del sistema digestivo, caracterizada por la presencia de divertículos: pequeñas bolsas, hernias o sacos abultados que se forman y sobresalen hacia afuera en la pared interna del colon (el intestino grueso).", whatIs: { title: "¿Qué es la Diverticulosis?", text: "Imagina un neumático viejo o una cámara de aire que tiene un bulto en una zona débil. Eso es un divertículo en el colon. La diverticulosis en sí misma no es una infección; es simplemente la existencia física de estas bolsas. Es extremadamente común en las sociedades occidentales a medida que las personas envejecen. La inmensa mayoría de las personas con diverticulosis nunca lo sabrán y no tendrán problemas. El peligro surge si una de estas bolsas se desgarra e infecta, lo que transforma la condición en una enfermedad grave llamada 'Diverticulitis'." }, symptoms: { title: "Síntomas de la Diverticulosis (vs. Diverticulitis)", intro: "Es fundamental separar la simple presencia de bolsas de su infección:", groups: [ { name: "Diverticulosis (No infectada)", items: ["Por lo general es completamente asintomática (sin síntomas)", "Puede haber cólicos abdominales muy leves, hinchazón abdominal esporádica o cambios sutiles hacia el estreñimiento"] }, { name: "Signos de Alarma: Progresión a DIVERTICULITIS (Infección)", items: ["Dolor abdominal agudo, repentino, intenso y constante, casi siempre localizado en la parte INFERIOR IZQUIERDA del abdomen", "Fiebre, escalofríos y temblores", "Náuseas y vómitos", "Abdomen sensible o doloroso al tacto", "Aparición de sangre roja brillante en las heces o sangrado rectal masivo (hemorragia diverticular)"] } ], warning: "Una diverticulitis aguda no tratada puede perforar completamente el colon, derramando heces en el abdomen y causando una peritonitis mortal. Requiere hospitalización urgente." }, types: { title: "Causas y Factores de Riesgo", intro: "Las bolsas se forman por alta presión dentro del tubo intestinal:", items: ["Dieta baja en fibra (La causa principal): La falta de fibra produce heces pequeñas, secas y duras. El colon tiene que hacer contracciones y esfuerzos masivos para moverlas, y esta enorme presión interna empuja el revestimiento interno del colon a través de los puntos más débiles del músculo.", "Edad avanzada: Más de la mitad de las personas mayores de 60 años y casi todas las mayores de 80 años tienen diverticulosis.", "Sedentarismo, obesidad, y el tabaquismo", "Uso regular de AINEs (como Ibuprofeno, Aspirina) y esteroides aumenta el riesgo de sangrado de los divertículos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se descubre por casualidad durante exámenes por otras razones:", items: ["Colonoscopia: El método más común. El médico ve directamente las pequeñas cavidades u hoyos en la pared del colon.", "Tomografía Computarizada (TC) de Abdomen: Es la prueba obligatoria y de oro si se sospecha Diverticulitis (infección). Permite ver si la bolsa está inflamada o si se ha roto y formado un absceso de pus fuera del intestino.", "Enema de bario: Una radiografía con contraste que resalta las bolsas (menos usada hoy en día)."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento de la diverticulosis se enfoca en prevenir que progrese a diverticulitis, mientras que la infección requiere intervención médica severa:", subsections: [ { title: "Manejo Preventivo (Diverticulosis)", items: ["Aumento de Fibra: Dieta muy rica en frutas, verduras, legumbres, salvado y cereales integrales, o suplementos de fibra (Psyllium). Esto hace que las heces sean grandes y blandas, reduciendo la presión en el colon.", "Aumento de hidratación: Beber mucha agua es necesario si se consume fibra, o el estreñimiento empeorará.", "Nota: Antiguamente se prohibía comer nueces, semillas o palomitas de maíz por miedo a que se atascaran en las bolsas. La ciencia actual ha demostrado que esto es falso; se pueden comer sin riesgo."] }, { title: "Manejo Agudo (Diverticulitis - Infección)", items: ["Antibióticos y Dieta Líquida: Para ataques leves, se trata en casa con antibióticos orales fuertes (Ciprofloxacino y Metronidazol) y una dieta estricta de líquidos claros por unos días para dar descanso al intestino.", "Hospitalización y Antibióticos IV: Para ataques graves, dolor extremo o incapacidad de beber líquidos.", "Cirugía de Resección del Colon: Si el divertículo se perfora, se forma un gran absceso o los ataques de diverticulitis son crónicos y repetitivos cada año. El cirujano corta y extirpa el segmento del colon que tiene las bolsas y vuelve a unir los extremos sanos. (En urgencias, a veces se requiere dejar una bolsa de colostomía temporal)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No retrases la atención médica o visita a urgencias si presentas:", items: ["Dolor severo, constante y agudo en el lado inferior izquierdo de tu estómago (fosa ilíaca izquierda)", "Experimentas fiebre y escalofríos al mismo tiempo que dolor abdominal", "Ves sangrado evidente y abundante al ir al baño a defecar"] } },
'Neoplasia intraepitelial cervical' : { intro: "La neoplasia intraepitelial cervical (NIC o CIN, por sus siglas en inglés) es una condición médica pre-cancerosa caracterizada por el crecimiento anormal de células atípicas en la superficie del cuello uterino (la entrada al útero desde la vagina).", whatIs: { title: "¿Qué es la Neoplasia Intraepitelial Cervical?", text: "Es crucial entender que la NIC NO es cáncer. Son cambios o mutaciones celulares previas al cáncer (displasia). Cuando las células del cuello uterino son infectadas por el Virus del Papiloma Humano (VPH), pueden empezar a cambiar su forma y comportamiento. Si no se detectan y se dejan avanzar durante varios años o décadas, estas células anormales pueden eventualmente cruzar la membrana basal de los tejidos, convirtiéndose en un cáncer de cuello uterino invasivo. La detección de la NIC mediante citologías permite curar la enfermedad antes de que el cáncer llegue a existir." }, symptoms: { title: "Síntomas (La Condición Silenciosa)", intro: "El mayor peligro de la NIC es su total invisibilidad:", groups: [ { name: "Ausencia de Síntomas", items: ["La NIC en etapas 1, 2 e incluso 3 es COMPLETAMENTE asintomática. No causa dolor, no produce alteraciones en la regla, ni causa flujo inusual ni dolor durante las relaciones sexuales.", "Por lo tanto, la única manera de saber que la tienes es sometiéndote rutinariamente a una prueba de Papanicolaou (citología) o una prueba de VPH.", "Solo si la NIC ya ha evolucionado a cáncer invasivo, se presentará sangrado poscoital (después de tener relaciones sexuales) o sangrado entre los periodos menstruales."] } ], warning: "Saltarse los exámenes ginecológicos anuales o bianuales es el factor de riesgo número uno para permitir que una lesión NIC curable se transforme en un cáncer mortal." }, types: { title: "Clasificación de Severidad (Grados de CIN)", intro: "Los patólogos clasifican la NIC según qué tan profundo ha crecido la capa de células anormales en el tejido del cuello uterino:", items: ["NIC 1 (CIN 1 o Displasia Leve): Cambios celulares anormales confinados solo al tercio inferior del tejido epitelial. La inmensa mayoría de las infecciones de NIC 1 desaparecerán por sí solas gracias al sistema inmunológico sin ningún tratamiento.", "NIC 2 (CIN 2 o Displasia Moderada): Cambios anormales que ocupan hasta dos tercios del tejido. Requiere tratamiento o un seguimiento médico sumamente estricto.", "NIC 3 (CIN 3, Displasia Severa o Carcinoma in situ): Las células anormales ocupan casi todo o todo el grosor del tejido (más de dos tercios). Es una lesión precancerosa de alto grado que requiere extirpación quirúrgica obligatoria para evitar el cáncer."] }, causes: { title: "Causas y Factores de Riesgo", intro: "El origen de la NIC está vinculado casi exclusivamente a una infección viral:", items: ["Infección Persistente por el Virus del Papiloma Humano (VPH): Más del 99% de las lesiones NIC son causadas por cepas de alto riesgo del VPH (principalmente las cepas 16 y 18), transmitidas a través de las relaciones sexuales.", "Tabaquismo: Fumar multiplica drásticamente las posibilidades de que una infección leve por VPH progrese a NIC 3 y cáncer. Los carcinógenos del tabaco se concentran en el moco cervical y destruyen la inmunidad local.", "Inmunosupresión: Condiciones como la infección por VIH limitan la capacidad del cuerpo para combatir y eliminar el VPH.", "No estar vacunada contra el VPH antes de iniciar la vida sexual."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El proceso de diagnóstico es preventivo y escalonado:", items: ["Prueba de Papanicolaou (Citología Cervical): Examen de cribado primario. El ginecólogo frota suavemente el cuello uterino para raspar células sueltas y enviarlas al laboratorio para ver si están mutando.", "Prueba de ADN del VPH: A menudo se hace junto con el Papanicolaou para detectar si la paciente porta el virus de alto riesgo.", "Colposcopia: Si el Papanicolaou es anormal, el ginecólogo utiliza un microscopio especial (colposcopio) con una luz potente para visualizar el cuello uterino de cerca, aplicando líquidos (ácido acético) que hacen que el tejido precanceroso se vuelva blanco.", "Biopsia Cervical: El paso definitivo. Durante la colposcopia, el médico 'pellizca' un minúsculo trozo de tejido de la mancha blanca sospechosa. El patólogo diagnostica bajo el microscopio si es NIC 1, 2 o 3."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del grado (NIC 1, 2 o 3), la edad de la paciente y sus deseos de embarazo futuro. El objetivo es destruir o extirpar las células mutadas:", subsections: [ { title: "Observación y Manejo Activo", items: ["Espera en Observación (Para NIC 1): El tratamiento estándar suele ser no hacer nada excepto repetir el Papanicolaou en 6 o 12 meses. El sistema inmunológico de una mujer joven curará el NIC 1 por sí solo en el 70-90% de los casos.", "Procedimiento de Escisión Electroquirúrgica con Asa (LEEP): El tratamiento más común y rápido para NIC 2 y NIC 3. El ginecólogo usa un asa de alambre fino cargado con corriente eléctrica en la consulta para rebanar y retirar una capa fina del cuello uterino que contiene las células precancerosas.", "Crioterapia: Congelación extrema de la zona anormal del cuello uterino usando nitrógeno líquido para matar las células mutadas.", "Conización Quirúrgica (Biopsia en Cono): Si la lesión es NIC 3 grave o se adentra mucho en el canal cervical, el cirujano utiliza un bisturí o láser en el quirófano para extirpar una pieza de tejido en forma de cono más profunda del cuello uterino.", "Histerectomía: Extirpación del útero completo. Es muy rara para NIC, pero puede elegirse en mujeres que ya no desean tener hijos, han pasado la menopausia y tienen lesiones recurrentes obstinadas de NIC 3."] } ], note: "Todos los tratamientos para la NIC curan el problema sin necesidad de quimioterapia ni radiación. Prevenirla vacunándose contra el VPH en la adolescencia es la medida más efectiva existente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Dado que no hay síntomas, la responsabilidad está en la prevención proactiva:", items: ["Debes cumplir estrictamente con tus citas ginecológicas y realizarte la prueba de Papanicolaou/VPH cada 1, 3 o 5 años según la indicación de tu médico", "Acude urgentemente a ginecología si tienes cualquier sangrado o manchado vaginal después de tener relaciones sexuales o dolor de causa desconocida"] } },
'Ectropión' : { intro: "El ectropión es una afección anatómica ocular en la que el margen del párpado (generalmente el párpado inferior) se pliega, se tuerce o se evierte hacia afuera, dejando expuesta la superficie interna del párpado y el globo ocular al aire.", whatIs: { title: "¿Qué es el Ectropión?", text: "Nuestros párpados funcionan como el 'limpiaparabrisas' del ojo, cerrándose herméticamente para esparcir las lágrimas y proteger la delicada superficie ocular. En el ectropión, debido a debilidad muscular, cicatrices o problemas nerviosos, el párpado cae hacia adelante y se despega del ojo. Como resultado, las lágrimas no logran bañar el ojo ni drenar hacia el conducto lagrimal (situado en la esquina del párpado), derramándose por la mejilla. Esta exposición constante deja la conjuntiva y la córnea crónicamente resecas, rojas y muy propensas a infecciones graves y ulceración." }, symptoms: { title: "Síntomas y Señales Físicas", intro: "El aspecto visual es muy característico, y las quejas se deben a la exposición ocular:", groups: [ { name: "Síntomas Oculares", items: ["El párpado inferior se ve flácido y visiblemente 'colgado' hacia afuera, mostrando el tejido rojo interior (conjuntiva)", "Ojos extremadamente llorosos (Epífora): Paradójicamente, la sequedad del ojo provoca que la glándula produzca un exceso de lágrimas de reflejo, pero como el párpado caído no las dirige al conducto de drenaje, caen como llanto constante por la cara", "Sensación constante de sequedad ocular o de tener 'arena' dentro del ojo", "Enrojecimiento severo crónico, irritación e inflamación de la parte blanca del ojo y del revestimiento del párpado", "Sensibilidad a la luz intensa y secreciones o mucosidad seca en las pestañas al despertar"] } ], warning: "Si la córnea (la ventana frontal del ojo) está expuesta permanentemente a la sequedad, puede desarrollar una úlcera corneal dolorosa. Una úlcera no tratada puede perforar el ojo o dejar cicatrices opacas que causan ceguera permanente." }, types: { title: "Causas y Clasificación", intro: "El músculo del párpado (orbicular) puede debilitarse o ser arrastrado por diferentes problemas:", items: ["Ectropión Involutivo (Senil): Es la causa abrumadoramente más común. Con la edad avanzada, los tendones y músculos alrededor del ojo pierden su tensión elástica y la gravedad simplemente hace que el párpado ceda y caiga.", "Ectropión Paralítico: Causado por una parálisis del nervio facial (como en la Parálisis de Bell o daño por tumor). Sin fuerza nerviosa, los músculos del ojo se apagan y el párpado se desploma.", "Ectropión Cicatricial: Ocurre cuando quemaduras severas, cirugías de párpados previas defectuosas (blefaroplastias), o enfermedades de la piel tiran o tensan la piel de la mejilla hacia abajo, arrastrando al párpado consigo.", "Ectropión Mecánico: Un tumor benigno o maligno que pesa mucho sobre el párpado, arrastrándolo hacia abajo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El oftalmólogo lo diagnosticará en una visita rutinaria en la clínica:", items: ["Examen físico: Observación visual directa de la flacidez del párpado y la incapacidad del paciente para cerrar el ojo por completo.", "Evaluación de los tendones: El médico jalará suavemente el párpado para evaluar cuánto 'rebote' o tono le queda (Prueba del chasquido o 'Snap-back test').", "Evaluación con Lámpara de Hendidura: Examen detallado bajo aumento del globo ocular para verificar que la córnea no se haya ulcerado o dañado por la sequedad crónica."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento inicial busca proteger el ojo expuesto, pero la única cura definitiva es mecánica (cirugía):", subsections: [ { title: "Manejo de Soporte (Sintomático)", items: ["Lágrimas artificiales y pomadas lubricantes espesas: Son críticas. Se aplican frecuentemente durante el día y obligatoriamente por la noche para mantener la córnea mojada y evitar que se seque e infecte.", "Cinta o parche: En la parálisis de Bell o mientras se espera a la cirugía, el paciente puede tener que cerrar el ojo con cinta adhesiva médica antes de dormir para asegurar que no quede abierto.", "Limpiar correctamente el ojo: Se enseña al paciente a limpiarse las lágrimas siempre frotando de forma ascendente (hacia arriba y hacia la nariz) para no estirar más el párpado hacia abajo."] }, { title: "Tratamiento Quirúrgico (Definitivo)", items: ["Cirugía de Tensor Lateral (Acortamiento del Párpado): Es el procedimiento más común para el ectropión por edad (involutivo). Se realiza con anestesia local. El cirujano corta un pequeño trozo del borde externo del párpado, estira el músculo flácido y lo vuelve a anclar y coser firmemente al hueso orbital, devolviendo la tensión 'de banda elástica' normal.", "Injerto de piel: Si el ectropión es por cicatrices (cicatricial), el cirujano deberá tomar piel de detrás de la oreja o el párpado superior y hacer un parche bajo el ojo para liberar la tensión que tiraba del párpado hacia abajo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca a un oftalmólogo sin dudarlo si:", items: ["Notas que tu párpado está visiblemente caído, rojo e invertido hacia afuera", "Tienes un lagrimeo incesante o necesitas estar limpiándote el ojo constantemente", "Comienzas a experimentar dolor ocular agudo, visión borrosa o alta sensibilidad a la luz, lo cual sugiere que la córnea ya está gravemente lastimada por la sequedad"] } },
'Neuropatía del nervio ciático' : { intro: "La neuropatía del nervio ciático, conocida mundialmente de forma común como 'ciática', es una condición médica intensamente dolorosa caracterizada por un dolor radiante que viaja a lo largo del trayecto del nervio ciático.", whatIs: { title: "¿Qué es la Ciática?", text: "El nervio ciático es el nervio más largo y grueso de todo el cuerpo humano; se origina agrupando varias raíces nerviosas en la parte baja de la espalda (columna lumbar), pasa profundamente a través de los glúteos y baja por la parte posterior de cada pierna hasta el pie. Cuando la raíz de este enorme cable eléctrico es aplastada, pellizcada, irritada o inflamada mecánicamente (generalmente en la columna vertebral), emite una descarga dolorosa aguda a lo largo de toda su extensión anatómica. La ciática no es una enfermedad en sí misma, sino un fuerte síntoma de que hay un daño estructural oculto en la espalda baja." }, symptoms: { title: "Síntomas y Distribución del Dolor", intro: "El patrón del dolor ciático es inconfundible y clásico:", groups: [ { name: "Dolor Irradiado y Sensorial", items: ["Dolor severo que casi siempre afecta ÚNICAMENTE a un lado del cuerpo (una sola pierna y glúteo)", "El dolor se origina en la parte baja de la espalda o el glúteo y se 'dispara' hacia abajo por la parte posterior del muslo, cruzando la rodilla y bajando por la pantorrilla a veces hasta los dedos de los pies", "El tipo de dolor suele ser muy agudo, descrito como descargas eléctricas, calambres fulminantes, ardor ardiente o puñaladas (no es un dolor sordo muscular)", "El dolor empeora dramáticamente al estar sentado por periodos prolongados, al toser, al estornudar o al hacer un movimiento brusco (porque esto aumenta la presión en el canal espinal)", "Aparición de entumecimiento profundo, hormigueo o sensación de 'alfileres y agujas' a lo largo de la pierna o el pie"] } ], warning: "BANDERAS ROJAS (Urgencia de Quirófano): Si el dolor de ciática viene acompañado de pérdida de fuerza total en la pierna (por ejemplo, el 'pie caído', donde el pie se arrastra), entumecimiento alrededor del área genital ('anestesia en silla de montar') o pérdida súbita del control de los esfínteres (no poder contener la orina o las heces), indica un Síndrome de Cola de Caballo. Es una compresión nerviosa masiva terminal que exige cirugía antes de 24 horas para no quedar paralizado." }, types: { title: "Causas y Sitios de Compresión", intro: "El nervio puede ser pellizcado en varios niveles por la anatomía de la columna:", items: ["Hernia Discal Lumbar: Es, de lejos, la causa número uno. Uno de los discos de goma entre las vértebras lumbares (L4, L5, S1) se agrieta, y su gelatina interior se filtra y presiona físicamente la raíz del nervio ciático, quemándola con agentes químicos.", "Estenosis Espinal Lumbar: El canal por donde bajan los nervios en la columna se estrecha debido al crecimiento de espolones óseos y al desgaste propio de la edad (osteoartritis).", "Espondilolistesis: Una vértebra se resbala o desliza hacia adelante sobre otra, pellizcando el nervio a su paso.", "Síndrome del Músculo Piriforme: El nervio ciático no se pellizca en la espalda, sino profundamente en la nalga, donde el músculo piriforme sufre un espasmo y comprime al nervio por debajo de él.", "Embarazo (por presión directa del útero), obesidad o traumatismos en la pelvis."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico para confirmar un daño radicular se hace a través del examen clínico y la neuroimagen:", items: ["Prueba de Elevación de la Pierna Recta (Prueba de Lasègue): El doctor te pide que te recuestes boca arriba y levantará tu pierna estirada lentamente. Si sientes dolor eléctrico intenso que se dispara por debajo de la rodilla entre los 30 y 70 grados de elevación, confirma fuertemente que la raíz del nervio está atrapada o herniada.", "Examen Neurológico Físico: Evaluar la fuerza del pie, los reflejos del tobillo y de la rodilla y la sensibilidad a lo largo de la pierna.", "Resonancia Magnética (RM) Lumbar: La prueba diagnóstica absoluta (estándar de oro). Visualiza en alta definición cada disco y muestra con exactitud dónde el nervio está siendo aplastado.", "Electromiografía (EMG): Si se planea cirugía o hay debilidad prolongada, mide si el impulso eléctrico de la pierna está permanentemente dañado."] }, treatment: { title: "Tratamientos", intro: "Aunque sumamente doloroso e incapacitante, el 80% al 90% de los casos de ciática por hernia de disco mejoran drásticamente solos sin necesidad de bisturí dentro de unas semanas:", subsections: [ { title: "Tratamientos Conservadores y de Analgesia", items: ["Reposo Relativo a muy corto plazo y Movilidad: El reposo absoluto en cama por semanas está científicamente contraindicado porque empeora la debilidad. Se recomienda actividad moderada soportable e higiene postural.", "Medicamentos de Amplio Espectro: Antiinflamatorios (Ibuprofeno, Naproxeno) y relajantes musculares para el espasmo agudo. Dado que es dolor de nervio, los analgésicos normales a veces fallan; por lo que el médico usará medicamentos neuromoduladores específicos para los nervios (Gabapentina o Pregabalina) o antidepresivos que bloquean el dolor crónico.", "Fisioterapia: El tratamiento no invasivo más duradero. Ejercicios focalizados de Método McKenzie o Pilates para fortalecer poderosamente el corsé muscular del núcleo central (core abdominal), estirar flexores y mejorar la biomecánica vertebral para que las vértebras dejen en paz al disco.", "Inyecciones Epidurales de Esteroides: Si las pastillas fallan, un médico especialista inyecta fuertes corticosteroides antiinflamatorios, guiado por rayos X, directamente alrededor del nervio pinchado en la columna espinal, generando alivio sustancial que dura meses."] }, { title: "Tratamiento Quirúrgico (Si Conservador Falla)", items: ["Microdiscectomía: Si luego de 3 meses el dolor es insoportable o hay debilidad progresiva paralizante en el pie. El neurocirujano extirpa mediante microscopio únicamente la punta o hernia del disco que aprieta al nervio, respetando el resto de la columna, logrando a menudo un cese del dolor ciático al día siguiente."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita asistencia médica por trauma espinal si:", items: ["El dolor eléctrico en la pierna persiste empeorando por semanas en lugar de calmarse y te impide completamente caminar o mantenerte en pie", "Observas que tienes una pérdida de fuerza evidente en tu pierna (por ejemplo, te tropiezas con tu propio zapato o el pie cae sin fuerza al andar)", "Sufres de incontinencia urinaria, fecal o tienes adormecida toda el área pélvica íntima, debes ir de urgencias de forma inmediata a la clínica"] } },
'Daño renal' : { intro: "El daño renal o insuficiencia renal es un deterioro biológico y una patología médica grave que describe la pérdida parcial o completa de la capacidad y función de los riñones para actuar como los filtros fundamentales del cuerpo. Este daño destruye el sistema de desintoxicación del cuerpo, impidiendo a los órganos procesar los desechos tóxicos, filtrar el agua y estabilizar los químicos críticos de la sangre.", whatIs: { title: "¿Qué es el Daño o la Falla Renal?", text: "Los riñones contienen un millón de filtros milimétricos en forma de embudo llamados nefronas que extraen basura y fluidos por la sangre haciendo la orina pura y reteniendo los metales necesarios. Cuando el tejido del riñón entra en contacto o es acribillado crónicamente por un factor químico destructivo como la alta glucosa de la diabetes y la presión hipertensiva de la sangre que machaca el sistema de vasos durante décadas o sufre una infección, esos filtros capilares microscópicos (glomérulos) se queman, se cicatrizan, colapsan o se vuelven inactivos de manera irreversible provocando una acumulación y envenenamiento extremo letal y masivo crónico de los líquidos, toxinas, exceso de urea o ácidos acumulados. Este daño es una espada de doble filo: Daño Renal Agudo (ocurre en días y se cura) o Enfermedad Renal Crónica (silencioso por décadas y es irreversible terminal)." }, symptoms: { title: "Síntomas y Señales Físicas Inconfundibles de Intoxicación Sanguínea", intro: "En los estadios iniciales (Causas crónicas del riñón), la pérdida no causará ninguna alarma visible ya que el riñón posee enorme reserva (solo se nota el daño al usar análisis tras perder casi más de 70% funcional general de ambos órganos). Al decaer drásticamente o con lesión grave a gran velocidad en forma repentina o aguda avanzada, surgen:", groups: [ { name: "Síntomas Generales Urinarios y Sistémicos Físicos", items: ["Hinchazón profunda o retención enorme y evidente de líquidos blandos o fofos en áreas declives (edemas de retención pesada marcados usualmente en ambos pies hinchados, tobillos hinchados y gran abotargamiento general blando peri-ocular matinal en las bolsas alrededor de los párpados de la cara).", "Aparición notable en retrete de un orinado excesivamente muy turbio o burbujeante, como hacer espuma blanca incesante espesa y duradera que cuesta bajar, o que contenga trazos de la sangre (Signo masivo directo irreversible u orgánico de escape alto incontrolable y pérdida severa de proteínas y glóbulos por fallas letales de filtros).", "Gran fatiga diaria inexplicable u aletargamiento crónico severo inmanejable provocado fuertemente además por la gran acumulación e intoxicación general por orina y urea circulante en el cerebro sumado al hecho y aparición grave repentina natural de que el riñón descompuesto no puede jamás fabricar suficientes estimuladores hormonales EPO e inducirá inevitablemente Anemia masiva profunda y debilidad y palidez fuerte del cuerpo con poco glóbulo rojo para la médula.", "Confusión cerebral grave por letargo y sabor muy metálico químico ácido repentino crónico u olor y náuseas diarias al probar alimentos y vómitos y reducción fatal e incapacitante masiva del volumen natural para ir al baño de forma total que resulta al ser insuficiencia oligúrica (no generar ya uretra)."] } ], warning: "Si una persona padece insuficiencia urológica profunda, no controlada en grado terminal o muy aguda, los riñones dejan de regular bruscamente la sangre reteniendo gran potasio químico (Hiperpotasemia extrema). Altos minerales por sangre son la primer causa oculta fulminante tóxica que colapsará al músculo cardiaco en paradas e inmensas arritmias masivas repentinas de riesgo para la vida." }, types: { title: "Diferenciación entre Enfermedad Aguda (Reversible) y Daño Crónico", intro: "El pronóstico de tu riñón depende drásticamente sobre si el daño lo originó un ataque sorpresivo del mes, o fue paulatino:", items: ["Daño (Lesión) Renal Aguda (LRA o IRA): El tejido sano es asfixiado, quemado o estresado brutal o sorpresivamente en unos solos días limitados por un evento masivo del exterior. Usualmente curable si se alivia. Causas: Deshidratación fulminante, gran pérdida del sistema de choque circulatorio de presión, bloqueos obstructivos anatómicos bruscos (piedras urinarias atascando ambos embudos), infecciones por Sepsis del torrente, o toxicidad o fallos directos mortales medicados al riñón debido a abusar intensivamente de las pastillas calmantes de gran volumen del Ibuprofeno/AINEs crónico letal y dolor.", "Enfermedad Renal Crónica Progresiva (ERC): Un marchitamiento gradual silencioso imparable en los túbulos y el centro vital por meses de destrucción paulatina. Las grandiosas causas dominantes del mundo en adultos: Principalmente es masacrada fuertemente al tiempo debido al 1) Mal control masivo y prolongado diario metabólico de la Diabetes Mellitus o Azúcar, y la 2) Destrucción contante violenta cardiovascular pesada de una Presión Arterial Altísima o Hipertensión y por fin a trastornos hereditarios Poliquísticos sistémicos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico rápido a través de la química de laboratorio estandarizada en sangre y creatinina para identificar la función:", items: ["Análisis Vitales Sanguíneos Completos Básicos (Examen y Medición de la Creatinina y BUN/Urea en laboratorio): La creatinina sube fuertemente como producto general basal y proporcional a un daño en un análisis e indica a tu médico a qué ritmo el cuerpo la retira usando TFG (Tasa de Filtración).", "Análisis Urinarios Complejos para Proteínas Totales (Ratio general Albúmina-Creatinina) Urianálisis por 24 Horas: Evalúa directamente el paso del filtro celular a través del fallo de su barrera de los tejidos al hallar y calcular cuánta y cuánta inmensa proteína se arroja letalmente al retrete perdiéndose por los hoyos de los riñones y dictaminando daño celular crónico directo o severa desnutrición.", "Biopsia Quirúrgica Renales Aguda bajo Punción y Ecografía y TAC de volumen morfológico general pélvico si el médico busca un origen o anomalías de tumores genéticas y daños y si sospecha por fallo y no tiene el riñón diagnóstico directo."] }, treatment: { title: "Tratamientos", intro: "Un tratamiento del riñón busca primordial e imperativamente tratar estrictamente agresivamente de paralizar de forma contundente al avance metabólico crónico y fatal originario de tu cuerpo o enfermedad que ataca tu vaso previniendo por fin tu diálisis artificial obligatoria final:", subsections: [ { title: "Manejo Primario Farmacológico Sistémico Fundamental y Restricción Severa", items: ["Control Radical Básico Diabético o Metabólico Inversivo de Fármacos, Antihipertensivos o Presión Total Vital Sanguíneo y Renal: Reducir y tratar obligatoriamente cualquier hipertensión alta general es innegociable. Recetar al enfermo directamente la familia de gran protección farmacológica del IECA e inhibidor o ARA-II potentes. Protegen y prolongan contundentemente mucho el daño general renal general vascular interno además.", "Restricción e Imposiciones Sistémicas Dietéticas Clínicas y Estrictas Orgánicas Constantes Invariables de Sustancias por Especialista Alimentario para aliviar con dureza drásticamente todo el trabajo crónico biológico duro celular químico procesador en los filtros. Control radical e indispensable por la nutrición rebajando sodio (sal blanca severa), moderando un volumen bajo de su ingesta o proteína tóxica en comida, bajando potasio excesivo y moderando el nivel grande crónico excesivo de fósforo celular o la carne para que las glándulas suprarrenales y los deshechos puedan descansar.", "Detener radical, permanente y para siempre sin excepciones por la recomendación expresa ningún u otro fármaco destructivo directo nefrotóxico (Toda la familia perjudicial AINE y antiinflamatoria, o inyecciones que procesen o se maten y exijan del hígado crónico y el riñón)."] }, { title: "Terapia y Reemplazo Extracorpórea de Etapas Terminales Últimas Funcionales (End-Stage Renal Disease ESRD)", items: ["Diálisis Crónica Vital (Hemodiálisis con Máquina Clínica Hospitalaria Sanguínea o por Vía Diálisis Peritoneal Infiltrada Doméstica Diario Constante y Diaria): Cuando los filtros o el tejido funcional orgánico basal de la capacidad global se colapsa, quiebra al nivel terminal perdiendo o funcionando bajando la medición bajo al rango o cifra mortal o minúscula fatal y crítica menor crónico agudo irreversible del <15%, se requiere conectar de por vida las venas para purificar artificial y exteriormente las máquinas que hagan la filtración vital tres tiempos por semana ininterrumpidamente.", "Cirugía de Trasplante Completo Urológico de Trasplante General de Donante con Compatibilidad Renales Sanos General u Órganos: Es la última solución permanente orgánica para no someterse a terapias de purificación externa de fluidos."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es mandatario concertar e interponer un encuentro y un requerimiento formal evaluativo generalizado de atención emergente urológica para nefrología especializada en sangre para revisar internamente al paciente con rapidez con prontitud sin dudar si se constata a continuación fuertemente algún signo u observar:", items: ["Detectar o si te ha resultado al presenciar muy bruscamente durante mucho rato e ir regularmente al inodoro, una extraña o altísima acumulación turbia e inexplicable de una espuma densa alta constante general y que no se rompe tras tirar la cadena, que indica pérdida pesada al riñón.", "Has comenzado con letargo a sentir fatiga crónica intensa y tener piernas masivamente hinchadas y sin zapato al mismo modo general constante sin que bajen en días si además padeces de la obesidad diabética base o de presiones.", "Tu uretra general deja un grado u volumen bajísimo radical ausente severo en goteos en general o detienes bruscamente casi de golpe tu capacidad corporal y líquido fisiológico global basal en urgencia no pudiendo de manera general arrojar y vaciar una suficiente u orina en doce tiempos en tus 12 horas por todo tu cuerpo."] } },
'Absceso cerebral' : { intro: "Un absceso cerebral es una acumulación peligrosa de pus, células inmunitarias y otros materiales infectados dentro del cerebro, producto de una infección bacteriana o fúngica. Es una emergencia médica y neuroquirúrgica potencialmente letal.", whatIs: { title: "¿Qué es un Absceso Cerebral?", text: "A diferencia de las infecciones en la piel, un absceso en el cerebro es un problema crítico porque el cráneo no puede expandirse. A medida que la bolsa de pus crece en tamaño, presiona y aplasta el tejido cerebral sano y delicado que la rodea. Esta presión intracraneal interrumpe las funciones normales del cerebro, corta el flujo sanguíneo y puede causar daño neurológico irreversible." }, symptoms: { title: "Síntomas y Señales Neurológicas", intro: "Los síntomas pueden desarrollarse lentamente a lo largo de semanas o de forma repentina:", groups: [ { name: "Síntomas de Presión y Alerta", items: ["Dolor de cabeza sordo, constante y severo que empeora de manera progresiva y no responde a los analgésicos habituales (suele ser el primer y más común síntoma)", "Fiebre y escalofríos (aunque no siempre están presentes)", "Cambios en el estado mental: confusión profunda, letargo, irritabilidad o coma", "Convulsiones de nueva aparición", "Náuseas y vómitos explosivos (signo clásico de alta presión en el cráneo)"] }, { name: "Síntomas Neurológicos Focales", items: ["Debilidad muscular repentina, parálisis o entumecimiento en un lado del cuerpo", "Cambios en la visión, visión doble o dificultad para hablar", "Dificultad para caminar, falta de coordinación o pérdida del equilibrio"] } ], warning: "Si el absceso estalla dentro del cerebro, el pus infectado se derrama en el líquido cefalorraquídeo, causando una inflamación masiva (ventriculitis o meningitis fulminante) que a menudo resulta fatal en cuestión de horas." }, types: { title: "Causas y Origen de la Infección", intro: "Las bacterias u hongos deben encontrar una vía para llegar al cerebro, generalmente a través de:", items: ["Infección contigua (Propagación local): La causa más común. Una infección grave y no tratada en el oído medio (otitis), mastoiditis, sinusitis aguda severa o un absceso dental grave se abre paso directamente a través de los huesos del cráneo hasta el cerebro.", "Propagación a través de la sangre (Siembra hematógena): Bacterias que viajan desde una infección en otra parte del cuerpo, típicamente de los pulmones (neumonía) o del corazón (endocarditis infecciosa).", "Traumatismo directo: Una herida de bala, una fractura de cráneo penetrante o una complicación de una neurocirugía reciente.", "Inmunosupresión: Las personas con VIH, en quimioterapia o que toman inmunosupresores tienen un alto riesgo, a menudo por infecciones raras de hongos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico debe ser inmediato para evitar la muerte del tejido cerebral:", items: ["Tomografía Computarizada (TC) de Cabeza con Contraste: A menudo es la primera prueba de urgencia. Muestra el absceso como un 'anillo' brillante rodeado de un área oscura de inflamación.", "Resonancia Magnética (RM) del Cerebro: Es mucho más precisa y sensible que la TC; ayuda a distinguir un absceso de un tumor cerebral o un derrame.", "Biopsia o Aspiración con aguja: El neurocirujano introduce una aguja fina guiada por imágenes directamente en el cerebro para extraer una muestra de pus. Este paso es el 'estándar de oro' porque identifica exactamente qué bacteria está causando el problema para elegir el antibiótico perfecto.", "Análisis de Sangre: Para medir marcadores de infección masiva."], note: "La punción lumbar (extracción de líquido espinal) a menudo está contraindicada si hay un absceso grande, ya que la extracción de líquido puede causar que el cerebro se hernie (se desplace) fatalmente debido a la presión alterada." }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere ingreso hospitalario en cuidados intensivos y suele implicar una combinación de cirugía y medicación agresiva:", subsections: [ { title: "Manejo Quirúrgico y Médico", items: ["Aspiración Quirúrgica o Drenaje: Es casi siempre necesario si el absceso mide más de 2 centímetros o amenaza con estallar. El neurocirujano perfora el cráneo y drena el pus guiado por computadora para descomprimir el cerebro.", "Craneotomía (Extirpación abierta): Si el absceso es muy grande, de pared gruesa o no responde a la aspiración, el cirujano abre el cráneo y extirpa físicamente el absceso entero.", "Antibióticos Intravenosos (IV): Tratamiento masivo y prolongado. Una vez drenado el pus, el paciente recibe antibióticos por vía intravenosa directa durante 6 a 8 semanas ininterrumpidas.", "Corticosteroides (Dexametasona): Para reducir la hinchazón cerebral aguda e inflamación peligrosa alrededor de la zona del absceso.", "Medicamentos Anticonvulsivos: Para prevenir o tratar las crisis epilépticas que causa la cicatriz del absceso en el cerebro."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a Urgencias (llama al 911) inmediatamente si:", items: ["Desarrollas un dolor de cabeza repentino, explosivo y constante, especialmente si recientemente has tenido una infección grave de oídos, senos nasales o dental", "Tienes convulsiones sin antecedentes previos", "Experimentas confusión profunda, letargo extremo o debilidad repentina en un lado de tu cuerpo o cara"] } },
'Gastritis crónica' : { intro: "La gastritis crónica es la inflamación, irritación y desgaste prolongado y persistente del revestimiento interno del estómago (la mucosa gástrica). A diferencia de la gastritis aguda, que aparece de forma súbita, la crónica se desarrolla lentamente a lo largo de meses o años.", whatIs: { title: "¿Qué es la Gastritis Crónica?", text: "El estómago está revestido por una capa de mucosidad que lo protege del poderoso ácido que utiliza para digerir los alimentos. En la gastritis crónica, esta barrera se debilita. Con el tiempo, la inflamación prolongada desgasta y afina la mucosa gástrica, destruyendo las células productoras de ácido y enzimas. Esta condición puede progresar silenciosamente, causando cambios en las células del estómago que aumentan significativamente el riesgo de desarrollar úlceras pépticas o cáncer de estómago a largo plazo." }, symptoms: { title: "Síntomas y Malestares", intro: "Sorprendentemente, muchas personas con gastritis crónica no tienen síntomas hasta que hay un daño importante. Cuando ocurren, incluyen:", groups: [ { name: "Síntomas Digestivos Superiores", items: ["Dolor sordo, molestia, pesadez o sensación de ardor constante en la parte superior del abdomen (boca del estómago)", "Sensación de plenitud extrema o saciedad temprana después de comer unas pocas porciones de alimento", "Pérdida de apetito y pérdida de peso inexplicable a lo largo de los meses", "Náuseas crónicas, a veces acompañadas de vómitos leves", "Sensación de hinchazón abdominal constante, eructos e indigestión"] } ], warning: "Si de repente vomitas sangre o un material que parece granos de café molido, o si notas que tus heces son de un color negro alquitranado, brillante y de mal olor (melena), es un signo de que tu estómago está sufriendo una hemorragia interna grave. Exige atención de emergencia." }, types: { title: "Causas y Tipos", intro: "La gastritis crónica tiene causas específicas, clasificadas generalmente en dos grandes tipos:", items: ["Infección por *Helicobacter pylori* (Tipo B): Es la causa más común en el mundo. Esta bacteria se aloja en el moco del estómago, evadiendo los ácidos, y causa una inflamación persistente. A menudo se adquiere en la infancia y dura toda la vida si no se trata.", "Gastritis Autoinmunitaria (Tipo A): El propio sistema inmunológico ataca y destruye las células del estómago sanas por error. Destruye un factor necesario para absorber la Vitamina B12, causando una complicación grave llamada Anemia Perniciosa (y daños en los nervios).", "Factores Químicos/Tóxicos (Gastropatía reactiva): Por el uso prolongado de pastillas analgésicas (AINEs como Ibuprofeno, Naproxeno o Aspirina), consumo excesivo y crónico de alcohol, o reflujo persistente de bilis desde el intestino delgado hacia el estómago."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para ver el daño crónico, el gastroenterólogo debe mirar dentro del estómago:", items: ["Endoscopia Digestiva Alta: Es la prueba de oro. El médico introduce un tubo flexible con una cámara por la garganta para examinar visualmente el enrojecimiento, adelgazamiento y daño del revestimiento estomacal.", "Biopsia Gástrica: Durante la endoscopia, se toman pequeñas muestras de tejido del estómago para analizar al microscopio; esto confirma la inflamación crónica, busca bacterias o verifica si hay cambios celulares precancerosos (metaplasia intestinal).", "Pruebas de *H. pylori*: Se puede detectar la bacteria mediante un análisis de aliento (prueba del aliento con urea), un análisis de heces o durante la biopsia.", "Análisis de sangre: Para detectar anemia (por sangrado crónico o falta de vitamina B12) o anticuerpos autoinmunes."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en eliminar el agente irritante para permitir que el revestimiento del estómago sane lentamente:", subsections: [ { title: "Manejo Médico y Estilo de Vida", items: ["Terapia de Erradicación de *H. pylori*: Si la bacteria es la causa, se prescribe un tratamiento agresivo de 10 a 14 días combinando dos antibióticos potentes (como Amoxicilina y Claritromicina) junto con un reductor de ácido. Es vital terminar todas las pastillas para curarla.", "Inhibidores de la Bomba de Protones (IBP) y Bloqueadores H2: Medicamentos como el Omeprazol, Pantoprazol o Famotidina que bloquean drásticamente la producción de ácido estomacal, reduciendo la irritación y dando tiempo al estómago para curar sus heridas.", "Suplementos de Vitamina B12: Obligatorios mediante inyecciones mensuales para los pacientes con gastritis autoinmunitaria que no pueden absorber la vitamina de los alimentos.", "Cambios estrictos en el estilo de vida: Suspender por completo el alcohol, dejar de fumar (que retrasa la cicatrización gástrica), suspender permanentemente los analgésicos AINEs (cambiar a Paracetamol) y evitar alimentos extremadamente irritantes (picantes, muy grasos, cítricos excesivos)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una cita con tu médico de cabecera o gastroenterología si:", items: ["Sufres de malestar estomacal, dolor ardiente y pérdida de apetito que no mejora después de una semana de cuidados", "Tus síntomas de indigestión te despiertan por la noche o te impiden comer adecuadamente", "Ve a urgencias inmediatamente si vomitas sangre o tienes evacuaciones de color negro intenso"] } },
'Neumotórax' : { intro: "Un neumotórax, comúnmente conocido como 'pulmón colapsado', es una emergencia médica que ocurre cuando el aire se escapa del pulmón y se filtra en el espacio que existe entre los pulmones y la pared del tórax (la cavidad pleural).", whatIs: { title: "¿Qué es un Neumotórax?", text: "La respiración funciona gracias a un vacío (presión negativa) en el pecho que mantiene a los pulmones inflados y pegados a las costillas. Si se hace un agujero en la superficie del pulmón o en la pared del pecho, el aire se cuela en este espacio. Este aire acumulado no tiene por dónde salir y ejerce una enorme presión física sobre el exterior del pulmón blando, aplastándolo e impidiendo que se expanda cuando la persona intenta inhalar. Como resultado, una parte o la totalidad del pulmón colapsa, cortando el suministro de oxígeno al cuerpo." }, symptoms: { title: "Síntomas y Alertas Respiratorias", intro: "Los síntomas suelen presentarse de manera abrupta, repentina y aguda:", groups: [ { name: "Síntomas Clásicos", items: ["Dolor en el pecho repentino, muy agudo y punzante en un solo lado (el lado del pulmón afectado) que empeora drásticamente al intentar respirar profundo o al toser", "Dificultad repentina y grave para respirar (disnea) o sensación de asfixia", "Latidos del corazón muy acelerados (taquicardia)", "Respiración superficial y muy rápida", "Coloración azulada en la piel o los labios (cianosis) si el nivel de oxígeno baja dramáticamente"] } ], warning: "Neumotórax a Tensión: Es la complicación más letal. Ocurre cuando el aire entra a la cavidad pleural pero no puede salir, creando un efecto de válvula. La presión dentro del pecho aumenta tanto que no solo aplasta el pulmón, sino que empuja y deforma el corazón y los grandes vasos sanguíneos, deteniendo el flujo de sangre. Provoca shock, pérdida de conciencia y muerte en minutos si no se descomprime con una aguja." }, types: { title: "Tipos y Causas Frecuentes", intro: "El agujero en el pulmón puede ser espontáneo, causado por una enfermedad o por un accidente violento:", items: ["Neumotórax Espontáneo Primario: Ocurre en personas completamente sanas, sin enfermedad pulmonar. Causa clásica: ruptura de una pequeña ampolla de aire congénita (bula) en la superficie del pulmón. Es típicamente común en hombres jóvenes, altos y delgados, a menudo fumadores.", "Neumotórax Espontáneo Secundario: Ocurre en personas con enfermedades pulmonares crónicas subyacentes, como EPOC (enfisema severo), asma, fibrosis quística o neumonía, debido a que su tejido pulmonar ya está débil y destruido.", "Neumotórax Traumático: Causado por un impacto físico contundente o penetrante en el tórax. Por ejemplo, una costilla fracturada que perfora el pulmón, una herida de bala, una puñalada, o accidentes automovilísticos.", "Neumotórax Iatrogénico: Una complicación accidental de un procedimiento médico (como biopsias de pulmón o inserción de catéteres centrales cerca del cuello)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico médico debe ser muy rápido, usualmente en la sala de urgencias:", items: ["Radiografía de tórax (frontal): Es la prueba principal y la más rápida. Muestra claramente la bolsa de aire negro rodeando el pulmón y el borde del pulmón encogido, colapsado en el centro del pecho.", "Ecografía de tórax: Se usa en urgencias para detectar rápidamente la falta de 'deslizamiento pulmonar' normal en la caja torácica.", "Tomografía Computarizada (TC) de Tórax: Proporciona imágenes muy detalladas en 3D. A menudo se utiliza para ver el tamaño exacto, para encontrar neumotórax pequeños ocultos por un traumatismo grave o para detectar si hay más bullas/ampollas en los pulmones listas para estallar."], note: "En un neumotórax a tensión severo (emergencia vital), el médico no esperará a las radiografías; pinchará el pecho con una aguja de inmediato basándose en los síntomas y la asimetría del tórax." }, treatment: { title: "Tratamientos", intro: "El objetivo es aliviar la presión sobre el pulmón extrayendo el aire atrapado para que pueda volver a inflarse y sanar el agujero:", subsections: [ { title: "Manejo Respiratorio y Cirugía", items: ["Observación Médica: Si el neumotórax es pequeñísimo y el paciente respira bien, se puede administrar oxígeno puro (que acelera la reabsorción de aire) y simplemente esperar unos días bajo observación en el hospital hasta que el pulmón se expanda solo.", "Aspiración con Aguja: El médico adormece la zona entre las costillas, introduce una aguja unida a una jeringa, y aspira el aire sobrante para descomprimir el pulmón.", "Colocación de un Tubo Torácico (Drenaje Pleural): El tratamiento estándar para neumotórax grandes. Se inserta un tubo de plástico a través del pecho (entre las costillas) hasta la cavidad pleural y se conecta a un sistema de vacío que chupa el aire continuamente, permitiendo que el pulmón permanezca inflado hasta que la herida o ampolla original sane y se selle por sí sola (suele tardar varios días).", "Cirugía (Pleurodesis o Resección): Si el neumotórax no se cura con el tubo, o si es la segunda o tercera vez que al paciente le ocurre un colapso pulmonar en su vida. Un cirujano de tórax realiza una cirugía por cámara (VATS) para encontrar y grapar/extirpar las bullas de aire débiles. A menudo aplican una sustancia química o rayan la superficie del pulmón (pleurodesis) para crear cicatrices, forzando al pulmón a pegarse de forma permanente a la pared de las costillas, asegurando que jamás vuelva a colapsar."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es una situación de urgencia vital ineludible. Llama al 911 o acude al hospital más cercano si:", items: ["Sientes un dolor agudo, de aparición súbita, en un lado del pecho que te corta la respiración repentinamente", "Te resulta cada vez más difícil tomar una bocanada de aire después de sufrir una caída fuerte o un golpe en las costillas", "Si ya has sufrido un neumotórax en el pasado y de pronto sientes ese 'dolor familiar' y falta de aire otra vez"] } },
'Neuralgia del trigémino' : { intro: "La neuralgia del trigémino (o tic doloroso) es una condición de dolor crónico neuropático que afecta al nervio trigémino, el gran nervio craneal (el 5º nervio craneal) responsable de transportar todas las sensaciones desde el rostro, la mandíbula y la frente hacia el cerebro.", whatIs: { title: "¿Qué es la Neuralgia del Trigémino?", text: "Es descrita por los pacientes y médicos como una de las condiciones de dolor físico más severas, insoportables y excruciantes conocidas en la medicina humana. Ocurre cuando el nervio trigémino está irritado o dañado. Esto causa que el nervio se vuelva hipersensible e inestable, enviando de forma espontánea señales eléctricas masivas y fulminantes de dolor al cerebro ante los estímulos más leves e inofensivos." }, symptoms: { title: "Síntomas y Desencadenantes", intro: "El dolor no es continuo como un dolor de muelas normal, sino que se caracteriza por 'ataques' o descargas relámpago:", groups: [ { name: "Características del Dolor", items: ["Episodios de dolor intenso, punzante y agudo, que se siente literalmente como una fuerte descarga eléctrica, un relámpago o puñaladas en la cara", "Ataques de dolor espontáneos o episodios desencadenados que duran desde unos pocos segundos hasta un par de minutos, para luego desaparecer de golpe", "El dolor ataca predominantemente a un solo lado de la cara (muy rara vez afecta a ambos lados al mismo tiempo)", "El dolor se centra habitualmente en la mandíbula inferior, los dientes, las encías, los labios o la mejilla (lo que a menudo hace que los pacientes crean erróneamente que tienen un problema dental gravísimo y pidan extracciones de molares innecesarias)", "Los episodios de ataques dolorosos pueden ocurrir repetidas veces durante días o meses (fase de brote), y luego entrar en remisión durante meses o años (sin dolor), pero la enfermedad tiende a empeorar y ser más frecuente con la edad"] }, { name: "Desencadenantes Comunes", items: ["Incluso el toque o la vibración más ligera y banal desencadena el ataque fulminante. Ejemplos de 'detonantes':", "Lavarse los dientes o masticar alimentos", "Afeitarse, maquillarse o lavarse la cara suavemente", "El simple roce de una brisa de viento frío o el aire acondicionado en la mejilla", "Sonreír, hablar o tragar líquidos"] } ], warning: "La calidad de vida se ve tan profundamente afectada por el miedo a la siguiente 'descarga' dolorosa, que el paciente puede dejar de comer, de cepillarse los dientes, aislarse socialmente, y desarrollar depresiones severas." }, types: { title: "Causas y Compresión Nerviosa", intro: "En la inmensa mayoría de los casos, la causa es una compresión física mecánica del nervio en la profundidad del cráneo:", items: ["Compresión Vascular (La causa número uno): En la base del cerebro, donde el nervio trigémino sale hacia la cara, un vaso sanguíneo normal (usualmente una arteria serpenteante o endurecida) descansa apoyándose sobre el nervio. Con cada latido del corazón, la arteria pulsa y frota constantemente contra el nervio a lo largo de los años. Esta fricción continua desgasta la capa de mielina (el recubrimiento aislante) del nervio, dejándolo 'pelado' y provocando que sus fibras eléctricas hagan un cortocircuito doloroso.", "Esclerosis Múltiple (EM): Esta enfermedad autoinmune destruye directamente la mielina en todo el cuerpo, incluido el nervio trigémino. Muy común si la neuralgia afecta a pacientes jóvenes.", "Tumores: Un crecimiento en el cerebro que aplasta físicamente el nervio.", "Daño traumático: Cirugías faciales mayores, traumatismos craneales o daño tras accidentes maxilofaciales o dentales extremos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico que requiere gran pericia neurológica, basado en las descripciones del paciente y neuroimagen avanzada:", items: ["Examen Físico Neurológico: El neurólogo evaluará exactamente qué áreas de la cara duelen al tacto para determinar qué rama de las 3 del nervio trigémino está afectada.", "Resonancia Magnética (RM) Cerebral de Alta Resolución (Protocolo FIESTA): Es la prueba de oro crucial y obligatoria. La RM tradicional a menudo no lo ve, se requieren secuencias especiales milimétricas para visualizar directamente la base del cráneo y detectar si hay un pequeño vaso sanguíneo chocando y aplastando la raíz del nervio, o para buscar placas de Esclerosis Múltiple o tumores profundos."], note: "El paso diagnóstico más frustrante para el paciente es visitar primero a múltiples dentistas, quienes en ocasiones realizan endodoncias o extraen dientes sanos porque el dolor es engañosamente similar a una infección de la raíz dental severa." }, treatment: { title: "Tratamientos", intro: "El dolor de la neuralgia del trigémino NO responde a los analgésicos convencionales como el ibuprofeno o incluso a los fuertes narcóticos (opioides). Requiere frenar los nervios o separarlos:", subsections: [ { title: "Manejo Farmacológico (Primera Línea)", items: ["Fármacos Anticonvulsivos (Carbamazepina, Oxcarbazepina): Originalmente diseñados para la epilepsia, estos medicamentos son el tratamiento estándar y la piedra angular. Funcionan bloqueando los disparos eléctricos caóticos en los nervios, calmando el dolor de forma drástica en la mayoría de los pacientes. A menudo, su fuerte eficacia sirve incluso para confirmar el diagnóstico de la enfermedad.", "Antiespasmódicos Musculares (Baclofeno) o Neuromoduladores (Pregabalina, Gabapentina): Se añaden para potenciar el efecto de los anticonvulsivos o si el paciente experimenta grandes temblores faciales acompañando al dolor.", "Inyecciones de Toxina Botulínica (Botox): Ocasionalmente, aplicadas en la cara, bloquean temporalmente los nervios sensoriales para pacientes que no toleran las altas dosis de pastillas requeridas."] }, { title: "Intervenciones Quirúrgicas (Cuando los medicamentos fallan o pierden efecto)", items: ["Descompresión Microvascular (DMV): Es la cirugía de oro, la más compleja pero la que ofrece el alivio más duradero e inmediato. Un neurocirujano abre un pequeño orificio detrás de la oreja en el cráneo, levanta la arteria pulsante que está frotando el nervio trigémino y coloca una pequeña almohadilla de teflón esponjoso entre ellos de por vida, eliminando el cortocircuito.", "Radiocirugía Estereotáctica (Gamma Knife): Un procedimiento no invasivo sin cortes. Se enfocan potentes haces de radiación en un punto específico para dañar y quemar de manera controlada e indolora la raíz del nervio trigémino en el interior del cerebro. Al dañar el nervio, este deja de poder transmitir las señales eléctricas de dolor (los resultados pueden tardar un mes en notarse).", "Rizotomía por Radiofrecuencia o Inyección de Glicerol: El médico clava una larga aguja a través de la mejilla del paciente hasta la base del cerebro, calentando o envenenando las fibras del nervio para adormecer de manera parcial la mitad de la cara de la persona para siempre, cortando el dolor."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Deberías acudir inmediatamente a un neurólogo o especialista en manejo del dolor si:", items: ["Sufres de ataques fulminantes, como descargas eléctricas que duran segundos, en tu cara, mandíbula o mejilla, y que no tienen explicación", "Los episodios de dolor extremo te han provocado un miedo paralizante a cepillarte los dientes, beber agua fría o sonreír, por miedo a desencadenarlo", "Tu dentista te asegura que tus muelas están perfectamente sanas, pero el dolor de 'muelas' persiste a niveles insoportables"] } },
'Exceso de flujo vaginal - leucorrea' : { intro: "La leucorrea es el término médico general utilizado para describir las secreciones o flujo vaginal. Tener flujo vaginal es una función normal, sana y vital del cuerpo femenino para limpiar, humectar y proteger los órganos reproductivos. Sin embargo, un cambio abrupto y persistente en la cantidad, textura, olor o color de estas secreciones a menudo es la primera señal de un desequilibrio profundo, irritación o una infección vaginal subyacente.", whatIs: { title: "¿Qué significa un Exceso de Flujo (Leucorrea Anormal)?", text: "Es importante entender la normalidad: El flujo vaginal normal consiste en líquido de las glándulas cervicales mezclado con células viejas y bacterias saludables (Lactobacilos). Suele ser transparente o de color blanco lechoso pálido, y su volumen varía naturalmente a lo largo del mes (siendo más espeso, elástico como clara de huevo y abundante justo antes y durante la ovulación). No obstante, la leucorrea se vuelve 'anormal' cuando el equilibrio químico de la vagina se altera. Si las bacterias protectoras mueren o si se introducen patógenos externos, se produce una inflamación agresiva en la vagina o el cuello uterino, dando lugar a un torrente de secreciones irritantes, fétidas o coloridas conocidas como vaginitis." }, symptoms: { title: "Síntomas y Señales de Diagnóstico según su Apariencia", intro: "Las características físicas del flujo anormal son una guía excelente para identificar la causa médica subyacente:", groups: [ { name: "Signos Clásicos de Flujo Anormal Infeccioso", items: ["Flujo Grisáceo, Blanco Turbio o Acuoso con Olor Fuerte: Frecuentemente descrito con un inconfundible y muy desagradable olor a 'pescado', el cual suele empeorar notablemente después de tener relaciones sexuales o lavarse con jabones. No suele causar dolor, pero sí molestia. (Signo clásico de Vaginosis Bacteriana).", "Flujo Grueso, Grumoso y Blanco: Similar en apariencia a la cuajada o al requesón (queso cottage). Generalmente no huele mal, pero se acompaña de un picor intenso, enrojecimiento y ardor desesperante en los labios y entrada de la vagina. (Signo clásico de Infección por Hongos o Candidiasis).", "Flujo de color Verde, Amarillo o Espumoso: Acompañado de mal olor fuerte, picor importante en los genitales, irritación y dolor intenso al orinar. (Signo clásico de Tricomoniasis, un parásito de transmisión sexual).", "Flujo Manchado de Sangre, Marrón o Pus denso: Fuera del periodo menstrual normal, puede estar acompañado de un intenso dolor pélvico o ardor persistente en la uretra. (Puede indicar infecciones de transmisión sexual profundas como Gonorrea, Clamidia, o problemas severos del cuello uterino)."] } ], warning: "Advertencia Peligrosa: Si notas un repentino exceso de flujo purulento, con muy mal olor y de color amarillo o verdoso, y además experimentas un fuerte dolor o calambres en la parte baja del abdomen (pelvis) acompañados de fiebre, esto es una alerta máxima de Enfermedad Inflamatoria Pélvica (EIP). La EIP es una infección destructiva que sube a los ovarios y trompas de Falopio, requiriendo antibióticos inmediatos para prevenir la infertilidad permanente." }, types: { title: "Causas y Factores Desencadenantes", intro: "Los motivos del flujo excesivo anormal son en su inmensa mayoría debido a alteraciones biológicas o patógenos:", items: ["Vaginosis Bacteriana (VB): La causa infecciosa número uno en mujeres jóvenes. Es un crecimiento excesivo y un desequilibrio de las bacterias 'malas' naturales de la vagina por sobre las bacterias protectoras. Factores de riesgo incluyen tener una nueva pareja sexual o el uso continuo de duchas vaginales.", "Candidiasis (Infección por Hongos/Levaduras): Un crecimiento excesivo del hongo *Candida albicans*, que vive normalmente sin dar problemas en la vagina. Es disparado fuertemente por el uso de antibióticos potentes (que matan las bacterias buenas que controlan el hongo), niveles altos crónicos de azúcar en sangre (diabetes), el uso de ropa interior húmeda/sintética prolongado o el embarazo.", "Enfermedades de Transmisión Sexual (ITS): Tricomoniasis, Clamidia y Gonorrea. Estas bacterias y parásitos infectan el cuello uterino causando una cervicitis purulenta.", "Causas no infecciosas o Irritantes Químicos (Vaginitis alérgica): Reacciones de la piel y mucosas a jabones fuertemente perfumados, papel higiénico con olor, detergentes de ropa atrapados en la tela, baños de burbujas excesivos, o alergias graves al látex de los preservativos o espermicidas.", "Cuerpos Extraños Retenidos: Un tampón viejo, un trozo de condón roto, capuchones cervicales o esponjas olvidadas dentro del canal vaginal causarán en pocos días un flujo masivo, verde/grisáceo y extremadamente fétido e inflamatorio por descomposición.", "Atrofia Vaginal (Síndrome Genitourinario de la Menopausia): En mujeres posmenopáusicas, la brusca y total falta del estrógeno hace que las gruesas paredes vaginales se hagan de papel, se sequen y se hinchen, causando un flujo acuoso irregular y manchados sanguinolentos dolorosos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un ginecólogo necesita ver físicamente el flujo y analizarlo en laboratorio para dar una cura correcta y no empeorar la flora de la paciente:", items: ["Examen Pélvico (Visual y Físico): El médico inserta un espéculo en la vagina para revisar si la inflamación, las llagas o el flujo rojo, verde o de queso están localizados solo en las paredes o emergen directamente desde adentro del cuello del útero.", "Toma de Muestra y Examen en Fresco con Microscopio: El médico usa un pequeño hisopo de algodón para tomar un poco del flujo vaginal, lo coloca en un cristal de vidrio con unas gotas de líquido y lo revisa en el mismo momento bajo el microscopio. Esto permite distinguir al instante visualmente el movimiento del parásito de la tricomoniasis, las hifas del hongo cándida, o las bacterias pegadas a las células (clue cells) de la vaginosis bacteriana.", "Cultivos de Laboratorio y Pruebas PCR de ADN: Se envían hisopos sellados al laboratorio central. Es la única manera exacta y definitiva de confirmar una infección aguda de transmisión sexual (ITS) como Gonorrea y Clamidia, o si se tiene un hongo 'mutante' súper resistente a las cremas normales.", "Prueba de pH Vaginal: El papel tornasol mide la acidez; un ambiente muy alcalino (menos ácido de lo normal) apunta fuerte a una vaginosis o tricomoniasis."], note: "Es muy común que las mujeres compren en la farmacia cremas contra los hongos al ver el primer flujo extraño, cuando en realidad sufren de Vaginosis Bacteriana. Empeoran la situación gastando dinero en cremas que no matan la bacteria." }, treatment: { title: "Tratamientos", intro: "Cada infección requiere un arsenal médico diferente. NUNCA se usa el mismo tratamiento para un hongo que para una bacteria:", subsections: [ { title: "Manejo Farmacológico Curativo e Higiénico", items: ["Para Infecciones Fúngicas (Candidiasis): Los médicos recetan potentes cremas antimicóticas o supositorios en forma de óvulos que se introducen profundo en la vagina por la noche (Clotrimazol, Miconazol) de venta libre o recetados. En infecciones persistentes y recurrentes que no sanan, se manda la 'cura definitiva', un poderoso fármaco antihongos oral en pastilla llamado Fluconazol (Diflucan).", "Para Vaginosis Bacteriana (VB): Jamás se curará con cremas para hongos. Requiere matar la bacteria con antibióticos recetados que respeten la otra flora. El médico receta pastillas de Metronidazol para tomar o cremas de Clindamicina o geles de Metronidazol aplicados con aplicador dentro del área afectada durante una semana.", "Para Tricomoniasis (Infección parasitaria): El único tratamiento efectivo e inmediato es un antibiótico masivo y rápido (típicamente una macro-dosis única de pastillas de Metronidazol o Tinidazol). ATENCIÓN: Es 100% obligatorio y vital que tu pareja sexual reciba exactamente la misma medicina y se trate al mismo tiempo; si no, volverán a pegárselo mutuamente eternamente (efecto ping-pong).", "Para Atrofia Vaginal (Menopausia): El tratamiento de elección y totalmente curativo es reponer las hormonas perdidas usando cremas, geles o anillos especiales con dosis micro y puras de Estrógeno Vaginal. Restaura la humedad de la piel, su grosor y curará los manchados en semanas.", "Higiene y Protección Diaria: Cambiar de inmediato a usar ropa interior de hilo de algodón 100%, dormir sin ropa interior si es posible, evitar prendas de lycra ajustadas y mallas deportivas de nylon (ya que atrapan el sudor), y abandonar para siempre las duchas vaginales, jabones íntimos de olores químicos y espumas porque asesinan la flora protectora natural, dejando vía libre a los patógenos."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una revisión de ginecología inmediatamente si:", items: ["Tu flujo vaginal de pronto huele mal y ha cambiado fuertemente a color amarillo, verde o gris", "Sufres de ardor constante y un picor insoportable, rojo e intenso en los labios genitales o al orinar, o tienes una secreción similar a queso cortado", "Ves manchados de sangre oscura recurrentes fuera de los días de tu periodo, y no estás tomando pastillas anticonceptivas nuevas", "Sientes dolor ardiente o un olor repulsivo después de las relaciones sexuales, lo que podría indicar una ITS en progreso"] } },
'Calvicie de patrón femenino' : { intro: "La calvicie de patrón femenino, conocida clínicamente bajo el término alopecia androgenética femenina, es la causa fundamental, más extendida y común de pérdida de cabello en las mujeres, originada por la combinación letal de una profunda predisposición genética (heredada de los padres) y alteraciones en el metabolismo hormonal, principalmente la sensibilidad del cabello a las hormonas sexuales andrógenas.", whatIs: { title: "¿Qué es la Calvicie de Patrón Femenino?", text: "El ciclo de vida normal de un folículo piloso incluye crecer, descansar y luego caerse para dejar paso a un pelo grueso y sano nuevo. En la alopecia androgenética, los folículos en el cuero cabelludo se vuelven hipersensibles biológicamente a las hormonas. Con el paso de los años, ocurre un proceso destructivo lento llamado 'miniaturización'. Cada vez que un pelo grueso viejo cae, el folículo encogido y debilitado produce un pelo nuevo mucho más delgado, corto, fino y débil que el anterior, un proceso similar al de una planta marchitándose gradualmente en tierra pobre. Eventualmente, el folículo deja de producir cabello por completo, volviéndose inactivo para siempre y resultando en una falta de densidad tan grande que el cuero cabelludo se hace notoriamente visible." }, symptoms: { title: "Síntomas y Evolución Visual", intro: "A diferencia drástica de la calvicie masculina (donde los hombres pierden la primera línea de la frente formando grandes 'entradas' y grandes calvas circulares en la coronilla), el patrón de pérdida en las mujeres es completamente diferente, difuso y más sutil:", groups: [ { name: "Signos Clínicos Principales y Evolución de Ludwig", items: ["Afinamiento Generalizado Central: El síntoma indiscutible es un adelgazamiento de los cabellos en la parte superior y superior-central de la cabeza, conservando siempre la línea del cabello intacta encima de la frente sin que retroceda", "Ensanchamiento de la Raya del Pelo: La 'línea de separación' natural del cabello donde las mujeres dividen su peinado comienza a verse cada vez más ancha de forma alarmante, como un 'árbol de navidad' si se mira desde arriba, y cada vez es más difícil de ocultar el cuero cabelludo rosa al peinarse", "Disminución Drástica del Volumen Total: Sentir físicamente que la coleta (o el moño) al recoger el cabello es la mitad de gruesa que hace cinco años, o que el pelo carece de cuerpo y no se mantiene al peinarse", "No ocurre caída a 'puñados' (efluvio), sino que a lo largo de meses y años, la mujer nota que los pelos que caen no están siendo reemplazados por otros fuertes", "A diferencia de los hombres, las mujeres casi nunca (rara vez) se vuelven completamente calvas, sufriendo un grave afinamiento general en la zona superior pero preservando siempre los cabellos en la parte de la nuca y encima de las orejas"] } ], warning: "Si de pronto comienzas a perder grandes puñados masivos de cabello al mismo tiempo que te duchas o te pasas la mano por la cabeza, formando rápidamente parches redondos despoblados donde la piel queda lisa (calvas circulares lisas), esto no es calvicie genética; es Alopecia Areata, una emergencia autoinmune donde las defensas atacan velozmente al cabello. También puede ser un efluvio telógeno por un estrés intenso o post-parto que curará solo." }, types: { title: "Causas, Genética y Desencadenantes", intro: "Se trata de un fallo y sensibilidad de origen mixto y profundamente arraigado a las hormonas femeninas:", items: ["Genética Familiar Implacable: Es el factor más abrumador. Si tu madre, tías, abuelas maternas o incluso mujeres de la rama paterna sufrieron de afinamiento capilar en la vejez o en la edad media, el riesgo genético y la sensibilidad hereditaria son enormes.", "Cambios Hormonales Relacionados con la Menopausia: Una parte inmensa de los diagnósticos ocurre a partir de los 50 y 60 años. Antes de la menopausia, los altos niveles de estrógenos protegen activamente la raíz del folículo capilar de la testosterona. Durante la menopausia, la producción de estrógenos de la mujer cae en picado hacia el suelo; sin ese poderoso 'escudo protector' de estrógeno, los folículos quedan a merced y expuestos a la agresión biológica de los andrógenos (hormonas masculinas) naturales que todavía fluyen, lo que mata la raíz (caída capilar) y, al mismo tiempo, engrosa el vello facial (bigote y barbilla).", "Síndrome de Ovario Poliquístico (SOP): Esta es una de las razones subyacentes críticas y patológicas por las cuales mujeres súper jóvenes y de mediana edad comienzan a ver calvicie. El SOP genera ovarios que producen una marea masiva, descontrolada y excesiva de andrógenos, lo que acelera brutalmente la miniaturización de la corona de la cabeza años antes.", "Efecto Adverso de Píldoras Anticonceptivas: Empezar o dejar ciertos tipos de anticonceptivos o terapias con hormonas exógenas puede desencadenar un cambio brusco del entorno de la testosterona."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para comenzar los costosos y largos tratamientos, el dermatólogo especialista en tricología primero debe estar 100% seguro de que se trata de calvicie genética y NO de una anemia o problema curable subyacente:", items: ["Examen Visual Físico, Clínica Tropológica e Historial del Patrón (Escala de Ludwig): El dermatólogo evaluará bajo su lupa especializada y con luz el patrón de la caída, revisando en la consulta si existe afinamiento central manteniendo la línea y un ensanchamiento agudo de la raya, y elaborando una historia hereditaria minuciosa.", "Tricoscopia Digital: El método de oro no invasivo. El doctor usa un microscopio con cámara especializado llamado dermatoscopio capilar puesto directamente contra el cuero cabelludo del paciente; esto le permite observar y contar científicamente que más del 20% de los folículos visibles en las raíces están atrofiados y son débiles (folículos miniaturizados).", "Análisis de Sangre Rigurosos e Imprescindibles: Es obligatorio para todo dermatólogo enviar a la mujer a hacerse pruebas de sangre detalladas de niveles de hormonas tiroideas (T3, T4, TSH) que alteran mucho el pelo, revisar que el Hierro y la Ferritina no estén severamente agotados por menstruaciones, y pedir niveles crudos y agresivos de hormonas andrógenas y testosterona para confirmar si la mujer sufre o no del peligroso Síndrome de Ovarios Poliquísticos y problemas de fertilidad.", "Biopsia de Cuero Cabelludo (Punzón de piel): Es excepcionalmente rara en este problema y solo se usa como 'último recurso' drástico si el dermatólogo ve cicatrices rojas, ardor inflamatorio o no tiene claro si la caída de cabello se debe a otras de las cientos de enfermedades inmunes graves como el lupus cutáneo o la alopecia cicatricial (que sí son destructivas e irreversibles)."] }, treatment: { title: "Tratamientos", intro: "No existe cura milagrosa que regenere un folículo muerto para siempre. El objetivo real, duro y prolongado de la medicina moderna es 'despertar' y engrosar a los folículos miniaturizados enfermos antes de que mueran, y frenar contundentemente la progresión futura de la calvicie:", subsections: [ { title: "Medicamentos Tópicos Estimulantes del Crecimiento (Primera Línea de Defensa)", items: ["Minoxidil Tópico (Solución Líquida o Espuma al 2% o al 5%): Es el único fármaco milagroso aprobado oficialmente en el mundo por la FDA de Estados Unidos y Europa específicamente para regenerar cabellos en el patrón femenino. Aplicado meticulosamente frotando en el cuero cabelludo (nunca en el largo del cabello) una o dos veces cada día a las raíces, sin parar. Es un fuerte vasodilatador que estimula la sangre forzando la apertura de canales de potasio en la raíz; despierta de golpe a los folículos moribundos encogidos obligándolos brutalmente a volver a su fase de crecimiento (Anágena) produciendo cabellos muy fuertes, gruesos, sanos y tupidos. \nAdvertencia vital de uso del Minoxidil: El medicamento no actúa inmediatamente; el paciente no verá ningún pelo nuevo hasta los 4, 6 o incluso 10 meses continuos de aplicárselo todos los días sin fallar. Peor aún, al comenzar a usarlo en el primer mes, el medicamento causa intencionadamente un episodio temible de caída masiva incontrolable llamado 'Efecto Shedding', para que los pelos viejos y enfermos se caigan dejando paso libre al nuevo pelo regenerado (causa pánico a las mujeres que lo abandonan prematuramente). Si se suspende el tratamiento diario con este fármaco de por vida, absolutamente todo el cabello nuevo regenerado sano se caerá repentinamente, volviendo inexorablemente la calvicie a los cuatro meses de dejar de ponérselo."] }, { title: "Tratamiento Oral Hormonal, Fármacos Antiandrógenos y Bloqueadores Sistémicos", items: ["Medicamentos Antiandrógenos Fuertes (Espironolactona o Flutamida): Es el tratamiento interno y hormonal de mayor impacto, especialmente y comúnmente usado para todas las mujeres diagnosticadas en edad reproductiva que además sufren de SOP, acné incontrolable y mucho vello facial u ovario poliquístico con hiperandrogenismo. Son poderosas pastillas que se recetan médicamente para ser tomadas para que bloqueen ciegamente a los receptores de testosterona en todo el organismo, bloqueando de la raíz todo el daño que los andrógenos le estaban haciendo a la cabeza. ADVERTENCIA: No se puede tomar si se intenta estar embarazada o embarazada, y obliga a una mujer joven a usar píldoras anticonceptivas obligatoriamente, ya que causan deformidades y feminizan a un posible feto varón (bloqueando las hormonas masculinas de los embriones) con graves riesgos.", "Finasterida o Dutasterida en Pastillas: Usadas abrumadoramente como el tratamiento milagro para hombres, rara vez son dadas para mujeres en etapa de ovulación por su inmenso peligro de monstruosas malformaciones en fetos, sin embargo, su eficacia es brillante y sí suelen dárselas a escondidas 'off-label' los especialistas a las mujeres valientes mayores que ya están bien asentadas en la menopausia terminal porque frenan y apagan definitivamente a la enzima que destruye al folículo."] }, { title: "Terapias Procedimentales Regenerativas Altamente Innovadoras", items: ["Terapia P.R.P. Inyectado (Plasma Rico en Plaquetas Infiltrado): Una rama costosa de la medicina moderna y regenerativa altamente exitosa que complementa los fármacos. El cirujano tricólogo extrae un par de frascos de tu propia sangre del brazo en consulta; luego usa centrifugadoras especiales para separar, concentrar y extraer puramente tus plaquetas y tus factores propios biológicos del crecimiento celular. Luego inyectan y re-infiltran todo el concentrado de factor directamente, mediante profundos y numerosos pinchazos indoloros con finas micro-jeringas de aguja bajo la piel de la cabeza (dermis radicular) para obligar a una reparación profunda, a un engrosamiento de los tejidos vivos marchitos de las células madre del cabello. Requieren dolorosas y largas sesiones al año repetidas en quirófano.", "Trasplante y Cirugía Micro-Capilar de Folículos (Microinjerto Método FUE avanzado): Considerado el único método infalible del mundo si el pelo y la raíz ya están totalmente muertos, extintos y perdidos. El neuro-cirujano capilar rapa una pequeña y delgada franja del paciente y usa instrumentos especiales bajo microscopio de precisión para extirpar a mano a uno, miles y miles de raíces de folículos gruesos sanos ('Unidades Foliculares Inmunes') y genéticamente invencibles por su ubicación de la parte robusta de atrás de la nuca y por encima de sus orejas, de la parte occipital. Acto seguido los clasifica bajo luz para sembrarlos, abrirlos e inyectarlos re-plantando los agujeros por agujeros calvos en todo el ancho y la raya pobre superior donde la chica presentaba un ensanchamiento por años y le había clareado su cuero. Tras la cirugía, los folículos sanan para siempre en su nueva zona para dar como resultado un bosque de pelo perenne grueso de 10 a 12 meses."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Cuanto más pronto un folículo en proceso de encogimiento se evalúe y rescate médicamente para detenerlo en lugar de ignorarlo, más altas serán las probabilidades de conservarlo intacto evitando que pase al grado terminal. Llama urgentemente para concertar una visita con el centro clínico especializado de Tricología y dermatología si:", items: ["Notas que repentinamente pierdes mechones enormes al levantarte o pasarte la mano que te provocan parches con círculos asombrosamente lisos de pura piel en la cabeza, esto marca que el cabello está bajo fuerte ataque en enfermedades inmunológicas complejas y requiere atención de corticoides potentes.", "Comienzas la edad biológica natural de la dura transición de la temida perimenopausia terminal y, además de sufrir un afinamiento difuso del cabello o de notar su calidad decaer o retroceder fuertemente, notas el crecimiento alarmantemente grueso y excesivo simultáneo de pelaje de barba áspera, bigote y tórax junto con un marcado cambio crónico del peso o cambios irregulares que acusan un hiperandrogenismo grave y subyacente que un especialista endocrinólogo tiene que parar mediante su reevaluación biológica médica hormonal del ciclo general.", "El sufrimiento psicosocial causado por la pérdida gradual del cabello ha comenzado a diezmar de manera absoluta e incapacitante tu autoestima y estabilidad social mental al punto en el que evitas el contacto público directo para la tranquilidad, por la obsesión y el odio por perder folículos o tener complejos destructivos estéticos agudos con gran dolor mental y un pánico inmenso e hiriente por estar sufriendo calvicie terminal aparente."] } },
'Temblor inducido por fármacos' : { intro: "El temblor inducido por fármacos (o temblor medicamentoso) es un movimiento muscular rítmico, repetitivo y tembloroso, totalmente involuntario, que aparece como una reacción adversa o un efecto secundario temporal de tomar medicamentos recetados, ciertas toxinas o sustancias químicas.", whatIs: { title: "¿Qué es el Temblor Inducido por Medicamentos?", text: "A diferencia del Parkinson o los temblores familiares genéticos que tienen un origen degenerativo o estructural profundo y empeoran a lo largo de décadas, el temblor medicamentoso comienza poco después de que una persona inicia un nuevo tratamiento farmacológico, le aumentan drásticamente la dosis que tomaba o al mezclar sustancias. Lo que sucede neurológicamente es que estos fármacos específicos penetran en el cerebro, alterando temporalmente, sobre-estimulando fuertemente o agotando temporalmente las vías de los neurotransmisores químicos, y generando potentes señales excitatorias musculares." }, symptoms: { title: "Síntomas y Alertas Clásicas de Farmacotoxina", intro: "Los signos clínicos distintivos y diferenciadores del temblor provocado por drogas consisten en:", groups: [ { name: "Características del Temblor Motriz y Manifestación", items: ["Es abrumadoramente un 'Temblor de Acción' o Postural (temblor cinético): Significa que ocurre y se hace intenso precisamente cuando la persona está sosteniendo los brazos extendidos frente a ella, o realizando una tarea fina o intención como intentar sostener una taza llena, pintar, alimentarse y atarse los botones (no empeora cuando la persona está durmiendo o tiene el brazo suelto sin hacer nada y apoyado flojo en un regazo)", "Suele ser un temblor muy rítmico y de frecuencia alta (muy fino y sumamente rápido y molesto), en contraposición a las sacudidas lentas, grandes o en forma de contar monedas típicas en los pacientes con Parkinson.", "Es eminentemente bilateral por diseño y distribución: Significa universalmente y casi de modo absoluto que al paciente le tiemblan amabas y dos manos y ambos lados del cuerpo (incluida la cabeza o barbilla en pacientes crónicos) asombrosa y exactamente con la misma intensidad simétrica y velocidad, sin que una mano se vea libre de vibrar", "Aparece con una rapidez abrumadora semanas, meses o en algunos casos solo al poco par de horas inmediatamente ligadas, precisas y concordantes a cuando el médico receta un medicamento diferente y un aumento o ajuste nuevo muy intenso a la terapia habitual del paciente, lo cual crea el cuadro clásico temporal de acción."] } ], warning: "Importante advertencia clínica: Si observas que tú o alguien presenta el famoso temblor de 'descanso', es decir, los brazos o las manos tiemblan violenta, gruesa y asimétricamente solo mientras están reposando y cruzados pero desaparecen en el instante preciso de intentar levantar algo, lo más probable es que sea una Enfermedad de la neurodegeneración del Parkinson en fase activa." }, types: { title: "Los Fármacos y Medicinas Más Culpables y Culpables Clásicos (Provocadores de Temblores Biológicos)", intro: "El sistema nervioso a menudo es fuertemente estimulado por ciertos tipos bien conocidos de familias farmacológicas de químicos muy prescriptos, entre los cuales abundan por su acción directa los siguientes grupos principales:", items: ["Inhaladores y Rescate para el Asma, la Bronquitis y la EPOC Crónica: Son abrumadoramente la causa número uno más habitual en pacientes diarios mundiales. Los fármacos broncodilatadores directos (Agonistas Beta-2 Adrenérgicos en formato potente o de bomba masiva, como el famoso Salbutamol o Albuterol). Esta clase de drogas respiratorias están literalmente e inherentemente diseñadas científicamente con el propósito médico de ser potentes estimulantes potentes de relajación para las vías respiratorias. Abren los pulmones bloqueados al instante, pero el poderoso estimulante sobrante pasa a la sangre llegando velozmente a los nervios y excita los músculos periféricos hasta temblar la mano, y aumenta drásticamente las palpitaciones a un ritmo cardiaco de forma temporal. El temblor desaparecerá gradualmente sin más complicaciones horas después del pico agudo o inyectado que alivia tu ahogo pulmonar agudo.", "Medicamentos Psiquiátricos (De amplio impacto neurológico): Particular y fuertemente la familia masiva de Antidepresivos fuertes clásicos del espectro de las Monoaminas o inhibidores fuertes recaptadores de serotonina (SSRI) en tratamientos, y abrumadoramente todos los tratamientos de Litio estabilizadores o Valproatos administrados y usados en pastillas rutinarias y agresivas para controlar o frenar severamente y fuertemente con altas dosis el padecimiento crónico del Trastorno Bipolar en fase maníaca; el temblor es un efecto muy bien descrito y esperado para estos.", "Estimulantes del Sistema Nervioso y Tóxicos: Los psicoestimulantes puros (para tratar el Déficit de Atención grave infantil TDAH, como el Ritalín, el Metilfenidato o Adderall/Anfetaminas) son altamente propensos, además de análogos legales masivos o excesivos descontrolados, como consumir a diario y sin moderación inmensas tazas letales de fuerte cafeína, nicotina masiva por tabaco, o anfetaminas ilegales que hiperestimulan al SNC periférico hasta agotar las defensas musculares.", "Tiroides Exceso: Si los médicos administran o inyectan grandes dosis recetadas de hormona tiroidea fuerte y sintética suplementaria artificial (como lo hace la dosis de la Levotiroxina inyectada a todos los enfermos y a los enfermos en estado hipotiroideo), y la dosis sobrepasa el grado de necesidad diaria provocando que los receptores químicos simulen el padecimiento biológico agresivo de un Hipertiroidismo 'ficticio', causarán palpitaciones crónicas veloces y el característico temblor veloz de una tiroides fuera de sus casillas corporales.", "Inmunosupresores fuertísimos: Utilizados a diario agresivamente contra enfermedades biológicas autoinmunes graves como reumatismo crónico inflamatorio crónico terminal o recetadas durante años prolongados a una persona que tenga en sus venas trasplantes de corazón y riñones frescos insertados para apagar cualquier ataque biológico de los linfocitos de sangre que provocan el rechazo terminal y fracaso de los órganos injertados artificiales (Específicamente Ciclosporina grave inyectada o el poderoso Tacrolimus).", "Medicamentos Neurolépticos u Antipsicóticos Graves: Tratamientos severos o antináuseas que cruzan la sangre directamente del cerebro fuertemente con mucha potencia química causando algo masivo que apaga al bloqueo de la dopamina o daña al cuerpo como reacción un terrible 'Parkinsonismo Inducido Ficticio' o movimientos y tics faciales musculares involuntarios bizarros."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico que requiere que un médico neurólogo realice un verdadero y complicado trabajo de 'detective' químico farmacéutico evaluando meticulosamente y haciendo rastreo e historial estricto con sus registros:", items: ["Revisión del Historial Farmacológico Completo, Exhaustivo y Sistemático de toda la Historia Médica Actual o Retirada de Prescripciones con la Línea Temporal (Anamnesis): Es la prueba más vital absoluta e importante con gran deferencia en la medicina. El médico analizará paso por paso si la línea de tiempo biológica de la aparición o exacerbación e inicio agudo del nuevo temblor físico y los tics del paciente coinciden innegablemente y claramente en una temporalidad temporal fuerte directa y estrecha a los días e inicios o momentos exactos precisos a cuando comenzó, ajustó en gramos o se prescribió temporalmente la terapia con un químico nuevo causante que interviene fuertemente en el caso y sea la familia de agentes inductores.", "Pruebas Neurológicas Minuciosas de Evaluación Práctica del Movimiento y Observación del Deterioro del Acto y Físico (Examen Neurológico Focalizado): El psiquiatra en clínica o médico de cabecera que hace inspecciones te exigirá de forma activa realizar y mostrar ejercicios estandarizados para evaluar la frecuencia y amplitud aguda fina midiendo si tu caso se describe con precisión de manera bilateral postural extendiendo o apoyando las extremidades fijas o escribiendo al sostener objetos.", "Análisis y Descarte Toxicológico Completo Urgente en Sangre Venosa Periférica de Rango Terapéutico en Suero Inmediato de Laboratorio Diagnóstico General Complejo y Hormonas del Eje: Resultan excepcionalmente determinantes cuando se hace un protocolo general clínico donde, si los doctores de emergencia psiquiátrica clínica descubren fuertemente bajo niveles toxicológicos y determinan analizando sangre la peligrosa sospecha o posibilidad ineludible de envenenamiento y nivel superior de toxinas que miden fuertemente la medicación, el nivel preciso por intoxicación letal altísima aguda por sales e ingredientes estabilizadores prescritos, midiendo por ejemplo en urgencias los picos químicos y el grado concentrado tóxico en pastillas crónicas o agudas como los niveles por la sangre que sobrepasaron al Litio en el cuerpo; o, también, analizando con hormonas la sobredosis excesiva o mala función del medicamento fuerte en pruebas químicas por sobredosis inducida intencional como en niveles suprimiendo TSH baja que provocan un hipertiroidismo de la tiroxina."] }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere de prudencia, una paciencia metódica cuidadosa por parte de un profesional que modere la química en sangre alterada causante de las contracciones, priorizando los síntomas sin descuidar ni desatender o suspender el efecto sanador curativo necesario u orgánico de tu enfermedad originaria que impulsó la prescripción:", subsections: [ { title: "Manejo Médico, Ajustes Farmacológicos Graduales Curativos Cautelosos", items: ["El Primer Paso: Control Cauteloso, Suspensión, Ajustes Cuidadosos, Escalonamiento Inverso Temporal y Supresión Gradual Clínica, Asistida Fuerte pero Controlada del Fármaco Ofensor Inductor Bajo Orden Directa Supervisión Médica y Autorización Experta. Si la medicina responsable del daño y tic biológico que te hace temblar es el inductor, no pone para nada ni expone inmediatamente a ningún gran o crónico y grave o severo riesgo ni al bienestar urgente ni a peligro el sistema general de tu salud crónica que debe ser prioritaria, entonces tu médico puede, e intentará, de gran modo suprimir reduciendo fuertemente u optimizando de modo muy cuidadoso fraccionando progresivamente la dosis aguda a un grado minúsculo mínimo que cure tu dolor sin los temblores molestos para tu bienestar personal, o procederá si hay gran intolerancia a cambiar el principio a drogas modernas similares de otra clase, buscando alternativas farmacéuticas mucho más orgánicas, estables o con mejores perfiles que no invadan químicamente.", "Tratamiento Complementario Anti-Temblor (En Caso de Riesgos Intocables con la Supresión): Si un paciente sufre una enfermedad que causa un inmenso y trágico riesgo crítico o deceso grave u hostil peligroso a la salud biológica letal si detiene su curación aguda base (como pacientes en diálisis postrasplantados orgánicos letales, problemas en convulsión fatal que eviten o deban utilizar el antiepiléptico agresivo), y sencillamente su condición biológica le prohíbe el detener la pauta prescriptiva original bajo riesgo de muerte; el doctor optará recetando en cambio con contundencia por otro medicamento fuerte y nuevo (los populares fármacos cardíacos Betabloqueantes orales, o por gran eficacia general de Propranolol inhibidor del receptor beta u otros depresores potentes musculares suaves y anticolinérgicos alternos), con el propósito final curativo de actuar y lograr por contrapeso en sangre 'apagar o silenciar o adormecer' permanentemente la excitación nerviosa fina y bloquear desde otro circuito todos y cada uno de los estímulos o temblores de efecto que te impidan vivir una calidad con paz sin retirar el medicamento vital del paciente."] } ], note: "¡ALERTA DE SEGURIDAD VITAL DEL PACIENTE! No es en absoluto responsable o aconsejado desde la responsabilidad personal, clínica o en ningún caso médico, que usted deba o pueda JAMÁS decidir reducir fuertemente la pauta temporal e indicaciones de las cajas que consuma deteniendo la vía y suspendiendo abruptamente la rutina, el tratamiento o las ingestas vitales y posología recomendada de ningún compuesto o grupo antidepresivo químico y antipsicótico psiquiátrico de la familia biológica y los estabilizadores crónicos sin consultar a los facultativos médicos de forma directa antes, debido al enorme e inmenso grado destructivo, crónico grave e insufrible pánico a reacciones por daño neurológico temporal irreversible fuerte del síndrome de la abstinencia severa o el efecto rebote." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental que mantengas y acudas muy responsable y urgentemente para establecer un control y concertar obligatoriamente una extensa y crucial consulta con tus especialistas para contactar a cualquier facultativo, centro y profesional neurólogo o emergencias para una pronta inspección que preste atención clínica e intervención general y precisa de tu afección urológica o tu pauta física o respiratoria con carácter importante y serio en el historial si tu situación personal involucra, sospecha o notas fuertemente alguna gran emergencia particular con urgencia en el historial si padeces o presentas en ti o familiares los síntomas:", items: ["Si presentas el temblor que, tras un inicio reciente de los químicos prescritos que usas para el asma fuerte temporal o las píldoras del trastorno psiquiátrico de bipolaridad graves (Litio u orgánico estabilizador antipsicótico valproato crónico) agudo por el doctor del psiquiatra que lo recetó nuevo, ha resultado volverse extremadamente tan grande, invasivo crónico asfixiante abrumador y con severo desorden progresivo a tu vida personal impidiendo grave o fuertemente realizar por completo tus capacidades para tu ocupación funcional y con tareas domésticas normales impidiendo gravemente las manos que alimenten tu boca o beber a diario con torpeza perdiendo agua y destruyendo cualquier calidad u orden general manual con control propio en tu cuerpo para funcionar por ti misma sin poder evitar sacudidas y requerimientos ajenos, por el gran efecto incesante del nivel tóxico o intenso y exacerbación perniciosa agresiva o persistente general de este fármaco.", "Sufres, además de un abrumador temblor agudo con debilidad fina y sacudida constante en movimiento de la mano periférica inmanejable severa que no te deja tranquilo y quieto de noche o al escribir de forma diaria y fuerte repetitiva general por ti y tu equilibrio que te molesta, te enfrentas sorpresivamente y al mismo y paralelo instante con otros signos sumamente nuevos repentinos biológicos peligrosos o intensos y de gravedad fatal envenenante crítica letal (como alucinaciones graves neurológicas por confusión que te anublan o asustan tu intelecto general psiquiátrico por pánico fuerte y agresivo del exterior por una falta de oxígeno cognitivo general y fatiga o un letargo muy brusco de debilidad aguda con desorientación aguda inusual con espasmos), indicando el peligro grave masivo e inminente de un envenenamiento extremo que destruya la base interna letal u órgano u toxicidad fulminante de emergencia sistémica orgánica en torrente por una intoxicación u sobredosis mortal sanguínea."] } },
'Patologías del crecimiento' : { intro: "Las patologías o trastornos del crecimiento son afecciones que impiden que los niños alcancen la estatura o el peso normales esperados para su edad y sexo, reflejando una desviación significativa en sus curvas de crecimiento pediátricas.", whatIs: { title: "¿Qué son los Trastornos del Crecimiento?", text: "El crecimiento físico es un indicador clave de la salud general de un niño. Un trastorno del crecimiento ocurre cuando un niño crece a un ritmo anormalmente lento (baja estatura) o, menos frecuentemente, anormalmente rápido. Esto no se refiere a ser 'un poco bajito' por genética familiar, sino a una falla en la tasa de velocidad de crecimiento que puede indicar un problema subyacente hormonal, genético, nutricional o sistémico que requiere evaluación." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Las señales se detectan principalmente midiendo al niño con el tiempo:", groups: [ { name: "Indicadores Clínicos", items: ["El niño crece menos de 5 centímetros (2 pulgadas) por año después de los 3 años de edad", "La estatura o el peso del niño cae bruscamente o 'cruza' hacia abajo dos o más líneas percentilares en su tabla de crecimiento del pediatra", "El niño es significativamente más bajo que sus compañeros de clase de la misma edad", "Desarrollo puberal muy retrasado (ausencia de cambios corporales en la adolescencia) o pubertad inusualmente precoz", "Apariencia inmadura para su edad cronológica, o proporciones corporales anormales (brazos o piernas muy cortos en comparación con el tronco)"] } ], warning: "Si un niño deja de crecer repentinamente y comienza a quejarse de dolores de cabeza matutinos frecuentes o problemas de visión, debe ser evaluado neurológicamente para descartar un tumor en la glándula pituitaria." }, causes: { title: "Causas Principales", intro: "El crecimiento deficiente puede tener múltiples orígenes:", items: ["Deficiencia de la Hormona del Crecimiento (GHD): La glándula pituitaria en el cerebro no produce suficiente hormona del crecimiento.", "Factores Genéticos y Síndromes: Síndrome de Turner (en niñas), Síndrome de Prader-Willi, o displasias esqueléticas (como la acondroplasia, que causa enanismo).", "Enfermedades Sistémicas Crónicas: Celiaquía (intolerancia al gluten severa no diagnosticada que impide la absorción de nutrientes), insuficiencia renal crónica, problemas cardíacos congénitos o fibrosis quística.", "Retraso Constitucional del Crecimiento y la Pubertad: Niños que son 'maduradores lentos', crecen despacio y entran en la pubertad tarde, pero finalmente alcanzan una altura normal de adultos.", "Desnutrición o estrés psicológico extremo (enanismo psicosocial)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El endocrinólogo pediátrico realizará un estudio exhaustivo:", items: ["Revisión histórica de las Curvas de Crecimiento: Es el primer paso vital para ver el patrón a lo largo de los años.", "Radiografía de Edad Ósea: Se toma una placa de la mano y muñeca izquierda para ver si la maduración de los huesos ('edad ósea') coincide con la edad real del niño o está retrasada.", "Análisis de Sangre: Para medir IGF-1 (un indicador de la hormona del crecimiento), hormonas tiroideas (T4, TSH), descartar celiaquía y anemia.", "Pruebas de Estimulación de la Hormona del Crecimiento: Una prueba en el hospital donde se administran medicamentos para forzar a la glándula a liberar la hormona y ver si responde adecuadamente.", "Resonancia Magnética (RM) del cerebro si se sospecha un problema pituitario."] }, treatment: { title: "Tratamientos", intro: "El tratamiento debe estar dirigido estrictamente a la causa subyacente:", subsections: [ { title: "Opciones de Manejo Endocrino y Médico", items: ["Terapia con Hormona del Crecimiento Sintética (Somatropina): Inyecciones diarias bajo la piel, administradas durante años hasta que se cierran las placas de crecimiento óseo. Se usa para deficiencia de hormonas, Síndrome de Turner, y niños nacidos muy pequeños para su edad gestacional que no recuperan el tamaño.", "Reemplazo Hormonal Adicional: Uso de Levotiroxina si la causa es hipotiroidismo.", "Tratamiento de la Enfermedad Base: Implementar una dieta estricta sin gluten (para la celiaquía) frecuentemente resulta en un 'estirón' de crecimiento masivo compensatorio en cuestión de meses.", "Observación ('Esperar y Ver'): En el caso del retraso constitucional, a menudo solo se tranquiliza a los padres de que el niño crecerá a su propio ritmo sin medicamentos."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta con tu pediatra si:", items: ["Notas que tu hijo sigue usando la misma talla de ropa o zapatos durante más de un año mientras sus amigos crecen", "El niño se ve a sí mismo mucho más pequeño que sus compañeros y esto le causa un estrés emocional severo o problemas de autoestima", "El pediatra te informa que tu hijo ha caído drásticamente en los percentiles de su gráfica de crecimiento"] } },
'Hipotiroidismo congénito' : { intro: "El hipotiroidismo congénito es una condición médica presente en el recién nacido, caracterizada por la producción parcial o totalmente nula de hormonas tiroideas por parte de la glándula tiroides del bebé.", whatIs: { title: "¿Qué es el Hipotiroidismo Congénito?", text: "Las hormonas tiroideas son el 'combustible' metabólico del cuerpo. En los bebés recién nacidos, estas hormonas son absolutamente críticas e insustituibles para el desarrollo y maduración del cerebro humano, así como para el crecimiento físico normal. Si un bebé nace sin una glándula tiroides que funcione y no recibe hormonas artificiales en las primeras semanas de vida, sufrirá un retraso mental grave, profundo e irreversible (una condición histórica y médicamente conocida como cretinismo), además de un fallo total en su crecimiento físico." }, symptoms: { title: "Síntomas y Señales (Silenciosos)", intro: "El mayor peligro es que los recién nacidos NO muestran síntomas obvios al nacer (porque están parcialmente protegidos por las hormonas de su madre). A medida que semanas pasan, aparecen:", groups: [ { name: "Signos Clínicos Tardíos en Bebés", items: ["Ictericia prolongada (coloración amarillenta en piel y ojos que dura inusualmente mucho tiempo después de nacer)", "Lentitud extrema, letargo, bebé que duerme demasiado y es muy difícil de despertar para alimentarlo", "Llanto muy ronco y áspero, y problemas de atragantamiento al tomar el biberón o el pecho", "Lengua anormalmente grande que parece sobresalir de la boca (macroglosia)", "Aspecto hinchado en la cara, piel muy seca, y extremidades frías", "Estreñimiento severo y vientre abultado, frecuentemente con una gran hernia umbilical", "Músculos muy flácidos y sin tono (hipotonía)"] } ], warning: "Esperar a que aparezcan estos síntomas físicos para diagnosticar a un bebé significa que el cerebro ya ha sufrido un daño permanente. Por esta razón, el cribado neonatal es obligatorio y una emergencia de salud pública preventiva mundial." }, types: { title: "Causas y Origen", intro: "El fallo de la glándula suele ser un accidente de desarrollo fetal:", items: ["Disgenesia Tiroidea: Es la causa más común (80-85% de los casos). La glándula tiroides del bebé simplemente no se forma en absoluto, se forma muy pequeña, o se forma en un lugar equivocado del cuello (tiroides ectópica).", "Dishormonogénesis: La glándula tiroides tiene un tamaño normal y está en el lugar correcto, pero debido a un defecto genético, es incapaz de fabricar químicamente la hormona.", "Falta severa de yodo en la dieta de la madre durante el embarazo (rara en países desarrollados, pero es la principal causa de retraso mental prevenible a nivel mundial).", "Hipotiroidismo transitorio: La madre estaba tomando medicamentos antitiroideos o tenía anticuerpos que pasaron al bebé, lo que apaga temporalmente la tiroides del recién nacido por unos meses."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es una carrera contra el reloj para salvar el cerebro del niño:", items: ["Tamiz Neonatal (La Prueba del Talón): Es una prueba universal. A las 48-72 horas de nacer, se le pincha el talón al bebé para tomar unas gotas de sangre en un papel filtro. El laboratorio mide el nivel de TSH (hormona estimulante del cerebro) o T4 (tiroxina).", "Análisis de Sangre Confirmatorio: Si el tamiz sale alterado (TSH muy alta y T4 muy baja), se debe extraer sangre de la vena de inmediato para confirmarlo y empezar el tratamiento ese mismo día.", "Ecografía o Gammagrafía Tiroidea (Opcional): Se usa después de iniciar el tratamiento para ver si la glándula del bebé existe o está fuera de lugar, lo que ayuda a saber si la condición será de por vida o temporal."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es simple, extraordinariamente barato, y 100% efectivo si se inicia en las primeras 2 a 3 semanas de vida del bebé:", subsections: [ { title: "Manejo Hormonal", items: ["Reemplazo con Levotiroxina: Es el único tratamiento. Se administra diariamente una pastilla triturada de hormona tiroidea sintética (Levotiroxina) mezclada con un poquito de leche materna o fórmula, dada con una cucharilla o jeringa al bebé.", "Monitoreo Estricto: El pediatra y endocrinólogo infantil realizarán análisis de sangre cada 1 o 2 meses durante el primer año de vida, y luego con menor frecuencia, para asegurar que la dosis de la pastilla aumenta adecuadamente a medida que el niño crece y gana peso.", "Tratamiento de por vida: Para los niños con disgenesia tiroidea, tomarán esta pastilla por el resto de su vida."] } ], note: "Un bebé diagnosticado mediante la prueba del talón y tratado inmediatamente con levotiroxina tendrá un desarrollo intelectual (coeficiente intelectual), un crecimiento físico y una vida exactamente igual y normal a la de cualquier otro niño." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca ayuda pediátrica inmediata si:", items: ["Por alguna razón, tu bebé no recibió la 'Prueba del Talón' (Tamiz Neonatal) antes de salir del hospital tras el nacimiento", "El pediatra o el hospital te llama informando que el tamiz de tu bebé salió alterado (no esperes ni un día para acudir a la cita)", "Tu bebé tiene un par de semanas de nacido, duerme profundamente todo el día, llora muy ronco, tiene la lengua grande y sufre estreñimiento inusual"] } },
'Adherencia pélvica' : { intro: "Las adherencias pélvicas son bandas anormales de tejido cicatricial denso y fibroso que se forman dentro de la pelvis, haciendo que órganos internos que normalmente están separados y resbalan entre sí (como el útero, los ovarios, las trompas de Falopio, los intestinos y la vejiga) se 'peguen' o se fusionen unos a otros.", whatIs: { title: "¿Qué son las Adherencias Pélvicas?", text: "El interior del abdomen y la pelvis está recubierto por un tejido liso (el peritoneo). Cuando este tejido se inflama severamente o sufre un corte durante una cirugía, el proceso natural de curación del cuerpo a veces se sale de control. Produce redes de cicatrices pegajosas como si fueran una tela de araña rígida. Estas adherencias atan los órganos, impidiendo que se muevan libremente. Si las trompas de Falopio se pegan, bloquean el paso de los óvulos (causando infertilidad). Si los intestinos se pegan, pueden torcerse y causar dolor o bloqueos." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Muchas mujeres tienen adherencias sin saberlo, pero cuando causan tensión en los órganos, provocan:", groups: [ { name: "Síntomas Dolorosos y Reproductivos", items: ["Dolor pélvico crónico, sordo y persistente que se siente como tirones o estiramientos en el interior del vientre", "Dispareunia: Dolor muy agudo o profundo durante las relaciones sexuales (especialmente en ciertas posturas que mueven el útero o el cuello uterino atado)", "Infertilidad: Imposibilidad de quedar embarazada (las adherencias distorsionan la anatomía de los ovarios y las trompas, atrapando los óvulos)", "Dolor intenso durante la ovulación o menstruaciones inusualmente dolorosas", "Aumento del dolor con movimientos repentinos, al estirarse, o incluso al ir al baño (si el intestino está adherido al útero)", "Síntomas de obstrucción intestinal: Cólicos severos, náuseas, vómitos e incapacidad para expulsar gases o heces (urgencia médica)"] } ], warning: "Si tienes un historial de cirugías pélvicas y sufres un dolor abdominal repentino tipo retorcijón paralizante, con vómitos e hinchazón del vientre, una adherencia podría estar estrangulando tus intestinos (obstrucción intestinal). Requiere sala de emergencias inmediata." }, types: { title: "Causas y Factores Desencadenantes", intro: "El tejido cicatricial se forma invariablemente como respuesta a un trauma o inflamación previa en la pelvis:", items: ["Cirugías pélvicas o abdominales previas: La causa más frecuente. Incluye cesáreas, extirpación de quistes ováricos, cirugías de miomas (miomectomía), extirpación del apéndice (apendicectomía) o cirugía intestinal. La manipulación de los órganos y el secado del tejido en el quirófano promueven las cicatrices.", "Enfermedad Inflamatoria Pélvica (EIP): Infecciones graves de transmisión sexual (como clamidia o gonorrea) que suben al útero y las trompas, causando una inflamación masiva y cicatrización severa que sella las trompas.", "Endometriosis: El tejido similar al endometrio sangra fuera del útero cada mes, provocando una irritación química profunda que hace que la sangre vieja actúe como un 'pegamento', fusionando ovarios e intestinos formando la llamada 'pelvis congelada'.", "Ruptura de apendicitis o infecciones intraabdominales graves pasadas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico difícil porque el tejido cicatricial es invisible en la mayoría de las pruebas de imagen normales:", items: ["Revisión del Historial Médico: El médico sospechará adherencias si el paciente tiene dolor crónico, infertilidad y un historial de infecciones graves, endometriosis o cirugías previas.", "Ecografía o Tomografía Computarizada (TC): Rara vez muestran las adherencias en sí. Solo sirven para descartar otras causas de dolor (como quistes, tumores) o para diagnosticar una obstrucción intestinal causada por las adherencias.", "Laparoscopia Diagnóstica: Es la única manera segura (el estándar de oro) de diagnosticar las adherencias pélvicas. Bajo anestesia general, un ginecólogo introduce una pequeña cámara iluminada por el ombligo para mirar directamente dentro del abdomen, confirmar las bandas cicatriciales y cortarlas en el mismo momento."], note: "" }, treatment: { title: "Tratamientos", intro: "El manejo de las adherencias es un equilibrio delicado, ya que la cirugía para eliminarlas puede, paradójicamente, causar la formación de nuevas adherencias al sanar:", subsections: [ { title: "Enfoque Médico y Quirúrgico", items: ["Manejo Conservador del Dolor: Si el dolor es tolerable, se utilizan AINEs (Ibuprofeno, Naproxeno) y anticonceptivos hormonales (si las adherencias son por endometriosis) para reducir los espasmos y el dolor pélvico, evitando la cirugía.", "Fisioterapia del Suelo Pélvico y Masaje Visceral: Técnicas especializadas de masaje interno y externo que pueden ayudar a estirar el tejido cicatricial, relajar la musculatura espasmódica y aliviar el dolor al tener sexo.", "Adhesiólisis Laparoscópica (Cirugía): Si las adherencias causan infertilidad confirmada, dolor incapacitante o están obstruyendo los órganos, el cirujano utiliza herramientas microscópicas o láser a través de laparoscopia para cortar y quemar las cicatrices, separando los órganos con mucho cuidado.", "Prevención Quirúrgica (Uso de Barreras): Durante la cirugía, para evitar que las paredes recién separadas se vuelvan a pegar, los cirujanos modernos insertan geles, mallas especiales absorbibles (barreras antiadherentes) o líquidos especiales en la pelvis antes de cerrar las incisiones para mantener los órganos 'separados' mientras sanan."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta con tu ginecólogo o especialista en fertilidad si:", items: ["Llevas meses sufriendo un dolor pélvico profundo que empeora durante el sexo y tienes un historial de cesáreas o infecciones pélvicas", "Llevas más de un año intentando quedar embarazada sin éxito y sabes que padeciste infecciones de transmisión sexual severas en el pasado", "Sientes espasmos o retorcijones abdominales agudos y repentinos acompañados de náuseas y dificultad para expulsar gases"] } },
'Pesadillas constantes' : { intro: "El trastorno de pesadillas es un tipo de trastorno del sueño (una parasomnia) caracterizado por sueños repetitivos, prolongados y extremadamente vívidos que resultan aterrorizantes para quien los sufre, provocando despertares bruscos, angustia emocional profunda y un deterioro importante en la calidad de vida diurna.", whatIs: { title: "¿Qué son las Pesadillas Constantes?", text: "Todo el mundo tiene malas pesadillas ocasionalmente. Sin embargo, cuando ocurren de forma constante y severa, se convierten en un trastorno. A diferencia de los terrores nocturnos (donde el niño o adulto grita pero sigue dormido y no recuerda nada), las pesadillas ocurren durante la fase de sueño REM (la etapa de sueño profundo y activo donde soñamos). El soñador se despierta bruscamente en un estado de alerta total, con el corazón acelerado, recordando perfectamente la amenaza detallada (persecuciones, ataques, caídas, fracasos) y a menudo siente tanto miedo que es incapaz de volver a conciliar el sueño esa noche." }, symptoms: { title: "Síntomas y Consecuencias Psicológicas", intro: "El trastorno va más allá del sueño en sí, afectando la vida de vigilia del paciente:", groups: [ { name: "Características del Despertar y Diurnas", items: ["Despertares abruptos con un recuerdo muy claro, detallado y angustiante del sueño que acababa de ocurrir", "Palpitaciones, sudoración y respiración acelerada al despertar, pero la persona sabe quién es y dónde está inmediatamente", "Miedo agudo y ansiedad anticipatoria a la hora de ir a la cama (lo que provoca retrasar la hora de dormir a propósito)", "Fatiga diurna crónica, somnolencia, irritabilidad y problemas graves de concentración en el trabajo o la escuela debido a la pérdida repetida de sueño reparador", "Sentimientos persistentes de tristeza, ansiedad diurna o depresión derivados del contenido oscuro de los sueños"] } ], warning: "Si las pesadillas constantes replican, directa o simbólicamente, un evento traumático severo que el paciente vivió en la realidad (accidentes, guerras, abuso), son un síntoma cardinal del Trastorno de Estrés Postraumático (TEPT) y requieren un enfoque psiquiátrico de trauma especializado." }, types: { title: "Causas y Desencadenantes", intro: "Las pesadillas frecuentes rara vez son aleatorias; son una manifestación de la actividad cerebral alterada por:", items: ["Estrés y Ansiedad Severa: La causa número uno. Preocupaciones crónicas por la familia, el trabajo, duelos recientes, o transiciones de vida importantes que el cerebro intenta 'procesar' bajo estrés durante el sueño REM.", "Trastorno de Estrés Postraumático (TEPT): El trauma no resuelto se manifiesta a través de pesadillas recurrentes y perturbadoras del evento traumático.", "Medicamentos: Ciertos fármacos tienen efectos secundarios directos sobre los neurotransmisores del sueño REM. Especialmente los antidepresivos (ISRS), betabloqueantes para la presión arterial, medicamentos para el Parkinson, o las pastillas para dejar de fumar.", "Abuso o abstinencia de sustancias: Consumir alcohol en exceso (que suprime el sueño REM inicialmente pero causa un rebote brutal de pesadillas cuando el alcohol se metaboliza de madrugada), y la abstinencia de pastillas para dormir o sedantes.", "Falta de sueño crónica (privación del sueño) que crea un rebote de la fase REM cuando el paciente finalmente logra dormir profundamente.", "Afecciones médicas asociadas: Apnea del sueño (los micro-despertares por falta de aire pueden disparar malos sueños), migrañas o fiebre alta."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico psiquiátrico y de medicina del sueño:", items: ["Historia clínica y Diario de Sueño: El médico pedirá al paciente que registre cuántas veces se despierta, qué come o bebe antes de dormir, sus medicamentos y el nivel de estrés diurno.", "Evaluación psicológica exhaustiva: Para buscar signos de ansiedad profunda, depresión o trauma (TEPT).", "Polisomnografía (Estudio del Sueño en laboratorio): Generalmente NO es necesario para las pesadillas puras, pero el médico lo solicitará si sospecha de apnea del sueño (ronquidos fuertes) o movimientos periódicos de las piernas que estén interrumpiendo el descanso natural y causando los malos sueños."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es reducir la frecuencia de las pesadillas reprogramando cómo el cerebro procesa las emociones durante el sueño, y reducir el miedo de ir a la cama:", subsections: [ { title: "Manejo Psicológico, Cognitivo y Farmacológico", items: ["Terapia de Ensayo en Imaginación (IRT - Imagery Rehearsal Therapy): Es el tratamiento psicológico estándar de oro más exitoso. Bajo guía de un terapeuta, el paciente recuerda la pesadilla recurrente mientras está despierto y consciente, y reescribe conscientemente el final de la pesadilla para que tenga un desenlace positivo, neutral o de victoria. Luego, ensaya y visualiza mentalmente este nuevo final seguro cada día. Esto 'reprograma' el subconsciente del cerebro reduciendo la pesadilla.", "Terapia Cognitivo-Conductual (TCC) general y Técnicas de Reducción de Estrés: Aprender a manejar la ansiedad diurna y establecer una rutina de relajación profunda estricta antes de dormir.", "Medicamentos para el TEPT: Si las pesadillas son producto de TEPT, el psiquiatra a menudo receta Prazosina. Originalmente un medicamento para la presión arterial, este fármaco bloquea el efecto de la adrenalina en el cerebro, previniendo eficazmente los terrores nocturnos y las pesadillas severas asociadas al trauma.", "Ajuste de medicamentos habituales: El médico puede revisar si tu medicación para el corazón o antidepresivos está causando los sueños, alterando la dosis o cambiando el fármaco."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No debes resignarte a dormir mal. Busca la ayuda de un psiquiatra o un especialista en medicina del sueño si:", items: ["Las pesadillas te ocurren varias veces a la semana o te impiden dormir lo suficiente de forma continuada", "Desarrollas un miedo abrumador e irracional a ir a la cama o a quedarte solo en la oscuridad", "Las pesadillas interfieren gravemente con tu capacidad de concentrarte y funcionar en el trabajo al día siguiente", "Sientes que los sueños están relacionados con un trauma, abuso o accidente de tu pasado que no has podido superar"] } },
'Cifosis' : { intro: "La cifosis es el término médico que describe la curvatura natural de la columna vertebral en la parte superior de la espalda (región torácica). Sin embargo, cuando esta curvatura se vuelve anormalmente exagerada y excesiva (más de 50 grados), provocando que la espalda se encorve hacia adelante y se vea redondeada, se considera una condición patológica, conocida coloquialmente como 'joroba'.", whatIs: { title: "¿Qué es la Cifosis (Hipercifosis)?", text: "La columna vertebral sana tiene curvas naturales que le ayudan a absorber impactos y sostener el peso de la cabeza. En una cifosis patológica (hipercifosis), las vértebras de la parte superior de la espalda adquieren una forma acuñada o se colapsan sobre sí mismas, lo que empuja los hombros hacia adelante y la cabeza hacia abajo. Dependiendo de la causa, la curvatura puede ser simplemente postural (corregible con esfuerzo) o estructuralmente rígida, donde los propios huesos están deformados o aplastados y no pueden enderezarse." }, symptoms: { title: "Síntomas y Señales Físicas", intro: "Los síntomas varían desde una leve preocupación estética en adolescentes hasta problemas físicos graves en adultos mayores:", groups: [ { name: "Síntomas Físicos Generales", items: ["Espalda visiblemente encorvada, redondeada, con los hombros caídos y la cabeza proyectada hacia adelante (postura de joroba)", "Dolor leve a severo en la parte media y superior de la espalda, que empeora al estar de pie o sentado prolongadamente", "Fatiga muscular constante y rigidez en la espalda y el cuello, ya que los músculos deben trabajar extra para mantener la cabeza erguida contra la gravedad", "Incapacidad o dificultad física para ponerse completamente recto al apoyarse contra una pared plana"] }, { name: "Síntomas en Casos Severos (Avanzados)", items: ["Dificultad para respirar o sentir falta de aire (la curvatura extrema comprime la caja torácica, dejando menos espacio para que los pulmones se expandan)", "Problemas digestivos o reflujo ácido severo (porque la postura comprime el estómago hacia abajo)", "Entumecimiento, debilidad o dolor agudo que baja por las piernas (si la deformidad de la columna está pinchando o estirando la médula espinal o los nervios)"] } ], warning: "Si la curvatura espinal se desarrolla rápidamente en una persona mayor acompañada de dolor repentino de espalda, suele indicar una nueva fractura por compresión (por osteoporosis) que requiere tratamiento médico rápido para prevenir mayores colapsos de los huesos vertebrales." }, types: { title: "Tipos de Cifosis y sus Causas", intro: "La cifosis no es una enfermedad única; el tipo dicta el tratamiento a seguir:", items: ["Cifosis Postural: La más común. Típica en adolescentes, oficinistas y personas sedentarias. Los huesos son de forma normal, pero el individuo tiene malos hábitos, pasando horas encorvado sobre mesas o móviles. Los ligamentos se estiran. Es flexible y la persona PUEDE ponerse derecha si se le pide y hace fuerza.", "Cifosis de Scheuermann: Un trastorno del desarrollo que aparece en adolescentes. Por un fallo genético en el crecimiento, varias vértebras crecen en forma de cuña o triángulo en lugar de rectángulos, bloqueándose juntas. Crea una joroba rígida, angular y muy dolorosa que el paciente NO puede enderezar.", "Cifosis Osteoporótica (Por Edad): Frecuente en mujeres posmenopáusicas mayores. La osteoporosis vuelve los huesos tan frágiles que la parte frontal de las vértebras se aplasta o fractura silenciosamente por el simple peso del cuerpo, colapsando la columna hacia adelante con el tiempo.", "Cifosis Congénita: Un defecto de nacimiento raro en el cual la columna vertebral del bebé no se forma correctamente en el vientre materno. A menudo requiere cirugía temprana antes de que aplaste la médula espinal."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista en columna (traumatólogo o neurocirujano) realizará una evaluación de postura y ósea:", items: ["Test de flexión hacia adelante de Adams: El médico te pedirá que te inclines hacia adelante por la cintura. Esto hace que la curva cifótica (la joroba) sea más obvia y permite distinguir si es estructural (angulosa) o postural (suave).", "Radiografías de Columna de Perfil (de pie): Es el estándar para el diagnóstico definitivo. Permite al médico medir los grados exactos del Ángulo de Cobb de la curva espinal, y permite VER si las vértebras tienen forma de cuña (Scheuermann) o si están aplastadas y fracturadas (Osteoporosis).", "Pruebas de Función Pulmonar (Espirometría): Se solicitan si la curvatura es muy extrema y parece estar ahogando la respiración del paciente.", "Densitometría Ósea (DEXA): Obligatoria en adultos mayores con cifosis progresiva para diagnosticar y medir el grado de osteoporosis subyacente.", "Resonancia Magnética (RM): Solo si hay signos nerviosos (entumecimiento en brazos o piernas) para ver si la médula espinal está siendo pellizcada en el canal espinal doblado."] }, treatment: { title: "Tratamientos", intro: "La cifosis postural no requiere intervenciones agresivas, pero las formas estructurales (Scheuermann u Osteoporóticas) necesitan tratamientos para evitar el deterioro continuo:", subsections: [ { title: "Manejo Físico, Conservador y Médico", items: ["Fisioterapia Intensa: Para la cifosis postural y de Scheuermann. Los ejercicios no pueden cambiar la forma de un hueso de cuña, pero fortalecer poderosamente los músculos extensores de la espalda y el 'core', y estirar los músculos del pecho (pectorales acortados), mejora radicalmente la postura, elimina el dolor y frena el progreso de la curva.", "Medicamentos: Analgésicos (AINEs) para el dolor. Muy importante: iniciar medicación potente fijadora de hueso (Bifosfonatos, Denosumab, etc.) en pacientes con cifosis por osteoporosis para evitar que más vértebras se fracturen y colapsen en el futuro.", "Uso de Corsés Ortopédicos Rígidos (Bracing): Únicamente útil en adolescentes (niños en pleno crecimiento) con Enfermedad de Scheuermann moderada. El corsé obliga a la columna a crecer más derecha mientras los huesos aún son maleables, previniendo que la deformidad se vuelva grave y requiera cirugía en la adultez."] }, { title: "Intervenciones Quirúrgicas", items: ["Cirugía de Fusión Espinal: Reservada para cifosis severas (curvas mayores de 70-75 grados en Scheuermann o congénitas), dolor incontrolable que interfiere en la vida, o curvas que están aplastando el corazón o pulmones. El cirujano ortopédico coloca tornillos y barras de titanio y metal a lo largo de la columna para forzar la espalda a enderezarse y luego fusiona (pega) los huesos permanentemente en esa nueva posición recta.", "Cifoplastia o Vertebroplastia: Para cifosis osteoporóticas agudas y recientes. El cirujano inyecta cemento óseo médico dentro de la vértebra fracturada y aplastada, inflando el hueso nuevamente y endureciéndolo para estabilizar el colapso y aliviar el dolor casi de inmediato."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita evaluación con traumatología o a tu médico general si:", items: ["Notas que tu espalda superior se redondea visiblemente hacia adelante o tus hijos desarrollan una postura jorobada que no logran corregir al ponerse de pie", "El encorvamiento está acompañado de dolores de espalda crónicos profundos y persistentes, o molestias al respirar profundamente", "Si eres una persona mayor y de repente sientes un crujido sordo o un dolor muy agudo en el centro de tu espalda al toser, levantar algo o simplemente sentarte (posible fractura por compresión silenciosa)"] } },
'Tumor del riñón o Tumor renal' : { intro: "Un tumor de riñón, o cáncer de riñón, se desarrolla cuando las células sanas de uno o ambos riñones mutan y crecen sin control, formando una masa sólida. El tipo más común en adultos es el carcinoma de células renales, responsable de la mayoría de los diagnósticos, mientras que el tumor de Wilms es más común en niños pequeños.", whatIs: { title: "¿Qué es el Cáncer Renal?", text: "Los riñones son dos órganos en forma de frijol ubicados en la parte posterior del abdomen que filtran y limpian la sangre, produciendo orina. La mayoría de los cánceres renales se inician en el revestimiento de los túbulos minúsculos que realizan este filtrado. Uno de los mayores desafíos del cáncer de riñón es su naturaleza silenciosa; a menudo no causa ningún dolor ni síntomas hasta que la masa tumoral ha crecido considerablemente y es grande, lo que hace que frecuentemente se descubra por accidente cuando se realiza un escáner por un motivo médico completamente diferente." }, symptoms: { title: "Síntomas y Señales de Advertencia", intro: "En estadios tempranos, un tumor renal es casi siempre asintomático. Cuando el tumor crece lo suficiente o comienza a sangrar, los signos de alarma incluyen:", groups: [ { name: "Síntomas Clásicos y Urológicos", items: ["Sangre visible en la orina (Hematuria): Es el síntoma principal y a menudo la única señal de alerta. La orina puede verse de color rojo brillante, rosada oscura, o color refresco de cola. A veces la sangre es microscópica y solo se detecta en laboratorio, o es intermitente (aparece y desaparece).", "Un dolor sordo, constante y profundo o una punzada debajo de las costillas, en la espalda o en los lados (flancos) que no desaparece y no está relacionado con un golpe o movimiento", "Aparición o palpación física de un bulto anormal, masa dura o hinchazón notoria en un lado del abdomen o en la parte baja de la espalda"] }, { name: "Síntomas Sistémicos (Paraneoplásicos o de Avance Cáncerígeno)", items: ["Pérdida de peso rápida e inexplicable, y pérdida de apetito persistente", "Fiebre baja recurrente (generalmente por la tarde o noche) que no es causada por una infección de gripe o garganta", "Cansancio agudo, fatiga profunda y letargo que no se cura durmiendo, frecuentemente a causa de anemia subyacente inducida por el tumor", "Aparición repentina de presión arterial alta resistente a medicamentos", "Aparición repentina de varices dolorosas en el escroto (varicocele izquierdo) en los hombres (el tumor grande bloquea el drenaje venoso del testículo)"] } ], warning: "Cualquier persona, sea hombre o mujer, que vea sangre o la orina teñida de rojo oscuro en su inodoro, de forma indolora y repentina, debe contactar a un urólogo y someterse a una ecografía urgente. Es cáncer urológico (de riñón o vejiga) hasta demostrarse lo contrario mediante imágenes." }, types: { title: "Causas y Factores de Riesgo", intro: "El cáncer de riñón se asocia fuertemente al estilo de vida y a ciertas exposiciones, así como a síndromes genéticos:", items: ["Tabaquismo: El factor de riesgo modificable más grande; el humo aumenta el riesgo exponencialmente ya que las toxinas del tabaco se filtran y concentran en los riñones.", "Obesidad (IMC alto): Se cree que las hormonas adicionales que produce el tejido graso desequilibran y promueven mutaciones celulares.", "Hipertensión Crónica y Uso Prolongado de Analgésicos: Tomar excesivamente AINEs o analgésicos fuertes a lo largo de décadas o tener la presión descontrolada daña el sistema de los riñones y fomenta tumores.", "Exposición ocupacional: Manipulación rutinaria o inhalación prolongada de sustancias químicas como asbesto, tricloroetileno o cadmio (baterías, metales).", "Enfermedad Renal Crónica e Historial de Diálisis prolongado: Causa quistes en los riñones degenerados que a la larga se vuelven tumores.", "Síndromes Hereditarios y Genéticos: Ciertas familias tienen mutaciones raras, en particular la Enfermedad de Von Hippel-Lindau (VHL), el Síndrome de Birt-Hogg-Dubé y el Carcinoma Papilar Hereditario, donde pacientes extremadamente jóvenes pueden desarrollar múltiples cánceres en ambos riñones."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un tumor de riñón se detecta principalmente mediante imágenes médicas, a menudo sin necesidad de biopsias iniciales:", items: ["Ecografía (Ultrasonido) Abdominal: Generalmente el primer paso. Identifica de manera rápida y sin radiación si el dolor de riñón se debe a un quiste de agua inofensivo, a una piedra en el riñón o a una masa sólida y preocupante.", "Tomografía Computarizada (TC) de Abdomen con Contraste o Resonancia Magnética (RM): La prueba de oro y la más crítica de todas. Ofrece una vista milimétrica en 3D del interior del riñón para saber el tamaño exacto del tumor, qué tanto tejido invade, si se ha comido la vena renal principal y si existen ganglios linfáticos inflamados alrededor listos para hacer metástasis.", "Análisis Clínicos: Exámenes de orina completos para verificar y confirmar la presencia de glóbulos rojos (hematuria), pruebas de función renal y pruebas hepáticas sistémicas para determinar si el paciente es apto para quirófano.", "Biopsia Renal: Tradicionalmente, rara vez se realiza para tumores renales sólidos si la TC o la ecografía indican claramente que es cáncer maligno, ya que el riesgo de esparcir células al puncionar o causar una hemorragia es alto; se suele extraer directamente. Se utiliza únicamente si el estado de salud de un paciente es demasiado débil para cirugía y se necesita confirmar qué medicinas utilizar o si existen dudas razonables de que pudiera ser un linfoma o metástasis de otro cáncer diferente."], note: "" }, treatment: { title: "Tratamientos", intro: "El carcinoma de células renales tradicionalmente no responde bien a la radioterapia ni a la quimioterapia convencional; el pilar principal de tratamiento y la única vía potencial de cura es extirpar físicamente el tumor quirúrgicamente:", subsections: [ { title: "Intervenciones Quirúrgicas (Nefrectomías)", items: ["Nefrectomía Radical (La Cirugía Clásica): Implica extirpar por completo el riñón entero que tiene el tumor, la grasa perirrenal circundante, los ganglios linfáticos vecinos y, a veces, la glándula suprarrenal ubicada encima del riñón. El ser humano puede vivir una vida normal con solo el riñón sano restante, que asumirá el trabajo completo de limpieza del cuerpo.", "Nefrectomía Parcial (Cirugía Conservadora de Nefronas): Es el tratamiento preferido moderno y la mejor opción si el tumor es pequeño (menos de 4-7 cm). El cirujano extrae minuciosamente el tumor con márgenes de seguridad limpios y deja el resto del tejido renal sano, reconstruyendo los conductos. Se prefiere en pacientes jóvenes, diabéticos o personas que de todos modos podrían tener problemas de fallo del otro riñón en un futuro próximo.", "Técnicas Quirúrgicas Mínimamente Invasivas (Laparoscópicas y Robóticas): Actualmente, tanto las nefrectomías parciales como las radicales no suelen requerir una gran incisión en el costado, realizándose en la mayoría de los casos mediante brazos robóticos e instrumentos introducidos a través de un par de agujeros muy pequeños en el vientre para tener una recuperación drásticamente más rápida."] }, { title: "Terapias Ablativas, Inmunológicas y Dirigidas (Si es Inoperable o Metastásico)", items: ["Crioterapia o Ablación por Radiofrecuencia (RFA): Si el paciente es anciano, sufre enfermedades severas de corazón y no soporta una cirugía profunda, se introduce una aguja por la espalda y el tumor se destruye quemándolo con calor intenso (radiofrecuencia) o congelándolo agresivamente con gases extremadamente fríos (crioablación).", "Inhibidores de la Tirosina Cinasa y Terapia Dirigida (Anti-Angiogénicos): Son medicamentos de pastillas orales sofisticados (Sunitinib, Pazopanib, Cabozantinib). Como el cáncer de riñón muta forzando al cuerpo a construir miles de vasos sanguíneos nuevos que alimenten el tumor para crecer, estas pastillas apagan y boicotean las señales del tumor para formar venas, literalmente 'matando de hambre' al cáncer cortando su flujo sanguíneo. Imprescindible para metástasis.", "Inmunoterapia Moderna (Nivolumab, Ipilimumab): Aprobada como revolución médica para casos avanzados o metastásicos; inyecciones que desbloquean el sistema inmunitario del propio cuerpo humano instruyendo y ayudando a los glóbulos blancos (Linfocitos T) a encontrar las células cancerígenas escurridizas y matarlas naturalmente."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Ignorar los síntomas tempranos urológicos retrasa fatalmente un diagnóstico que salva vidas y órganos. Contacta con tu médico de cabecera o urólogo sin dudarlo si:", items: ["Observas una vez o continuamente un color rosa, rojizo, cola o sangre pura y coágulos en tu orina al ir al baño (especialmente si no sientes absolutamente ningún dolor ni ardor al orinar, excluyendo un cólico)", "Palpas un endurecimiento extraño, bulto profundo o abultamiento en los flancos laterales por encima de tus caderas que se siente distinto del otro lado", "Desarrollas una fiebre baja y constante acompañada de fatiga atroz y pérdida masiva de peso de varios kilos sin intentar dietas"] } },
'Atresia duodenal' : { intro: "La atresia duodenal es una malformación estructural grave y congénita (presente al momento del nacimiento) en la cual la primera porción del intestino delgado (llamada el duodeno, que conecta el estómago con el resto de los intestinos) no se desarrolla correctamente durante el embarazo, quedando completamente obstruida, sin paso, o desconectada. Esta atresia corta de golpe el camino natural del tubo digestivo para dejar pasar alimentos y fluidos.", whatIs: { title: "¿Qué es la Atresia Duodenal?", text: "Durante la etapa fetal en el vientre de la madre, el tubo intestinal inicialmente se desarrolla como un tubo de tejido sólido y compacto. A las pocas semanas, las células del medio de este tubo sólido se deshacen, creando un hueco cilíndrico abierto para que pasen las cosas (proceso llamado recanalización). En la atresia duodenal, el proceso falla; el hueco nunca se forma, dejando una barrera cerrada y sólida, o un estrechamiento tan profundo en medio del duodeno que bloquea todo paso. En consecuencia, el líquido amniótico que el feto traga habitualmente durante el embarazo, o la leche materna que recibe después del parto, queda violentamente atrapado y acumulado sin salida en el estómago, que se infla masivamente, creando una urgencia vital por deshidratación y riesgo de rotura interna." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los signos en el bebé recién nacido suelen ser extraordinariamente evidentes y de alarma rápida en las primeras horas posteriores al parto:", groups: [ { name: "Signos Vitales y Clínicos en Recién Nacidos", items: ["Vómitos Incesantes, Explosivos y Biliosos: Es la señal cardinal de oro de la obstrucción intestinal. A diferencia del reflujo normal del bebé que escupe leche blanca, los vómitos de atresia duodenal son copiosos y de color amarillo-verdoso o ámbar oscuro intenso (porque contienen bilis, ya que el bloqueo suele estar justo por debajo del lugar donde la bilis gotea en el intestino).", "Estómago Hinchado y Tenso (Distensión Abdominal): El abdomen o barriguita del bebé aparece inusualmente prominente, inflada e hinchada justo en la parte superior central (debajo de las costillas) y vacía o hundida (escafoide) en la parte baja, porque la leche y los jugos gástricos se acumulan y llenan el estómago al no poder pasar de esa barrera.", "Ausencia de Evacuaciones (Retraso o Falta de Meconio): El bebé produce poca cantidad, se retrasa, o en los peores casos, no logra expulsar en absoluto la primera deposición oscura y pegajosa tras nacer (el meconio).", "Deshidratación Crítica, Pérdida Rápida de Peso, Trastornos Salinos y Apatía: Debido a los vómitos continuos de leche y secreciones."] } ], warning: "Si un bebé recién nacido experimenta reiterados vómitos de color verde-amarillento (vómito bilioso o de bilis) durante sus primeras tomas, los cuidadores médicos detienen automáticamente las alimentaciones. Ese vómito nunca es considerado 'normal'; se trata de una obstrucción o atresia y debe someterse a imágenes urgentes e intervención pediátrica sin pérdida de tiempo." }, types: { title: "Asociaciones Médicas y Sindromáticas", intro: "La atresia duodenal no siempre ocurre en el vacío. Frecuentemente los bebés sufren esta malformación como parte de anomalías más grandes en su desarrollo intrauterino:", items: ["Síndrome de Down (Trisomía 21): A la atresia duodenal se le conoce ampliamente en el campo de la neonatología porque alrededor del 30% a 40% de todos los bebés nacidos con atresia del duodeno padecen este síndrome.", "Prematuridad y Bajo Peso: Un gran número de estos niños no alcanzan el final del tercer trimestre o su crecimiento intrauterino se ve afectado.", "Malformaciones Conjuntas de la VACTERL: Defectos cardíacos genéticos de válvulas (Cardiopatías), ano imperforado u otras malformaciones esofágicas o renales están altamente vinculadas como fallos concurrentes.", "Páncreas Anular: Un desarrollo deforme del tejido del páncreas que crece envolviendo la porción del duodeno en forma de anillo cerrado, estrangulándolo herméticamente desde afuera."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "En los sistemas de salud modernos, casi todos los casos se detectan mediante ultrasonido rutinario antes incluso de que la madre se ponga de parto:", items: ["Ecografía Prenatal (Signo de la Doble Burbuja y Polihidramnios): El ginecólogo puede diagnosticarlo mediante ultrasonido materno al ver muchísimo líquido amniótico acumulado en el útero de la madre (polihidramnios, porque el feto traga el líquido pero no pasa a los intestinos por el bloqueo). En el feto se aprecia un estómago inmenso e hinchado de líquido, y un duodeno cercano con un saco inflado contiguo, formando el icónico 'Signo de Doble Burbuja' ecográfico negro.", "Radiografía Simple Pediátrica de Abdomen con el Bebé Erguido: Si no se vio en el vientre, a los pocos minutos de nacer (al presenciar los vómitos de bilis verde), se toman rayos X del bebé de pie o sentado. Muestra clásicamente el Signo Diagnóstico de la 'Doble Burbuja' inconfundible de aire y gas; el aire está únicamente acumulado dentro de la burbuja que es el estómago y la burbuja siguiente que es el duodeno inicial, pero no se aprecia ningún otro rastro ni sombra blanca de gas a lo largo de todos los intestinos inferiores, ya que por el nudo apretado de la atresia no pasa nada de gas al colón.", "Ecocardiograma: Por la enorme asociación y probabilidad de problemas cardíacos y de trisomía 21 paralelos, se hace de rutina una ecografía al corazón infantil antes de programar y meter al bebé a quirófano."] }, treatment: { title: "Tratamientos", intro: "La curación es pura y exclusivamente una intervención de descompresión con cirugía pediátrica de máxima especialidad y emergencia controlada; no se soluciona nunca con medicamentos:", subsections: [ { title: "Fase de Soporte Vital Urgente y Estabilización (UCIN)", items: ["Aspiración y Suspensión de Vía Oral (Ayuno Absoluto): Está totalmente prohibido darle leche al bebé, se interrumpe la dieta. Inmediatamente el pediatra pasa una pequeña sonda o tubo por la nariz o boca directo hacia abajo al estómago hinchado para empezar a succionar, drenar constantemente los líquidos de bilis y ácido y así evitar el colapso del órgano estomacal, aliviar su dolor y lo más importante: que el bebé no asfixie al vomitar (evitar que broncoaspire el fluido hacia sus pequeños pulmones sanos).", "Reanimación de Líquidos e Hidratación Endovenosa Fuerte: Como está perdiendo ácido y fluidos por los vómitos contantes, el bebé recibe altas dosis de hidratación de fluidos intravenosos con dextrosa (glucosa) para reparar su desequilibrio de electrolitos, calmar la sangre química, y nutrición TPN profunda mientras es programado para quirófano."] }, { title: "Corrección Quirúrgica Neonatal (Cirugía Anatómica de Bypass)", items: ["Duodenoduodenostomía (El Estándar de Excelencia Curativa): Es el tratamiento que restaura la continuidad del tubo digestivo para la vida entera. El cirujano pediátrico ingresa al diminuto abdomen (vía abierta o técnica de laparoscopia con cámaras), hace un corte en la porción ciega sana antes del nudo bloqueado superior, y realiza un segundo corte en el otro tubo inferior ciego y libre que pasa debajo del tejido cerrado; ambas porciones sueltas del duodeno las cose juntas delicadamente lado a lado (anastomosis) fabricando con sus manos un nuevo empalme artificial, un 'Bypass' natural para que la leche de la madre se desvíe completamente salteando el área tapada o destruida. La recuperación total y la alimentación oral reinicia unas semanas posteriores cuando los intestinos operados se despiertan y sanan sin fugas químicas y las cicatrices se absorben."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Generalmente es diagnosticado obligatoriamente y no puedes pasar por alto esta emergencia por ti mismo estando bajo observación o postparto; avisa en el acto al enfermero u obstetra de planta cuando:", items: ["El recién nacido expulsa abundantes, enérgicos y extraños vómitos de color netamente verdoso oscuro profundo u amarillento, incluso después de su primera toma minúscula", "Observas que su barriguita de la zona superior está notablemente inflamada o inflada muy asimétrica frente al pecho", "La madre de control fetal, recibe indicaciones de tener niveles peligrosamente anormales o muy abundantes de líquido en los ultrasonidos finales indicando Polihidramnios severo, pidiendo consulta pre-neonatal"] } },
'Enfermedad coronaria (CHD)' : { intro: "La enfermedad coronaria (CHD, por sus siglas en inglés) es el tipo más común de enfermedad cardíaca y la principal causa de muerte en el mundo, resultante de la reducción del flujo sanguíneo al músculo del corazón.", whatIs: { title: "¿Qué es la Enfermedad Coronaria?", text: "Ocurre cuando las arterias coronarias (los principales vasos sanguíneos que suministran oxígeno y nutrientes al corazón) se endurecen y se estrechan. Esto se debe a la acumulación crónica de placas formadas por colesterol, grasas y calcio en las paredes internas de las arterias (aterosclerosis). Cuando el conducto se vuelve muy estrecho, el corazón no recibe suficiente oxígeno, especialmente bajo esfuerzo físico o estrés." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Puede ser silenciosa durante décadas, pero a medida que las arterias se bloquean, provoca:", groups: [ { name: "Síntomas Cardiovasculares", items: ["Angina de pecho: Dolor, opresión, pesadez o sensación de ardor en el centro del pecho que frecuentemente se desencadena por esfuerzo físico y se alivia con el reposo", "Falta de aire o dificultad para respirar (disnea) extrema tras realizar actividades que antes eran fáciles", "Fatiga inusual y debilidad profunda", "Dolor que se irradia hacia el brazo izquierdo, el cuello, la mandíbula o la espalda"] } ], warning: "Si una placa de colesterol se rompe de repente, se forma un coágulo que bloquea la arteria por completo en segundos, provocando la muerte del músculo cardíaco (Infarto de Miocardio o ataque al corazón). Es una emergencia médica de vida o muerte (911)." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño a las paredes arteriales es progresivo y está fuertemente vinculado al estilo de vida:", items: ["Tabaquismo: El humo del tabaco daña directamente el revestimiento de las arterias y acelera la acumulación de placa.", "Presión arterial alta crónica (hipertensión), que ejerce una fuerza destructiva sobre los vasos.", "Niveles altos de colesterol 'malo' (LDL) y triglicéridos.", "Diabetes y resistencia a la insulina.", "Sedentarismo, obesidad y dietas altas en grasas trans y saturadas.", "Factores no modificables: Edad avanzada, sexo masculino y tener antecedentes familiares directos de ataques al corazón a edades tempranas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Los cardiólogos evalúan el corazón en reposo y bajo estrés:", items: ["Electrocardiograma (ECG): Para registrar la actividad eléctrica y buscar signos de infartos pasados o actuales.", "Ecocardiograma: Una ecografía para ver cómo bombean las paredes del corazón.", "Prueba de Esfuerzo (Ergometría): El paciente camina en una cinta de correr mientras está conectado a monitores para ver si el corazón se queda sin oxígeno cuando se le exige más trabajo.", "Angiografía Coronaria (Cateterismo): La prueba definitiva. Se introduce un tubo largo desde la ingle o la muñeca hasta el corazón y se inyecta contraste para ver exactamente (con rayos X) dónde y qué tan grave es el bloqueo en las arterias."] }, treatment: { title: "Tratamientos", intro: "El objetivo es detener la formación de placas, aliviar los síntomas y destapar los vasos críticos:", subsections: [ { title: "Manejo Médico y Modificación de Estilo de Vida", items: ["Cambios vitales: Dejar de fumar (innegociable), dieta saludable para el corazón (mediterránea), pérdida de peso y ejercicio cardiovascular regular.", "Medicamentos Reductores de Colesterol: Estatinas (como Atorvastatina) estabilizan la placa para que no se rompa y bajan el LDL.", "Medicamentos Cardiovasculares: Betabloqueadores (para relajar el corazón y reducir su carga de trabajo), Aspirina diaria a dosis baja (para evitar coágulos mortales), y Nitroglicerina (para dilatar los vasos y aliviar rápidamente el dolor de angina)."] }, { title: "Procedimientos de Revascularización", items: ["Angioplastia y colocación de Stent (Intervención Percutánea): Un cardiólogo infla un diminuto globo dentro de la arteria obstruida para abrirla y deja una malla de alambre (stent) para mantenerla abierta permanentemente.", "Cirugía de Bypass Coronario (CABG): Cirugía a corazón abierto. El cirujano toma una vena sana de la pierna o pecho y crea un 'puente' que desvía el flujo de sangre alrededor de la arteria bloqueada, restaurando el oxígeno al músculo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a urgencias sin demora si experimentas:", items: ["Dolor o presión aplastante en el pecho que dura más de unos minutos o que va y viene", "El dolor en el pecho se irradia a los hombros, el brazo izquierdo o la mandíbula", "El malestar se acompaña de sudor frío repentino, mareos extremos, debilidad o náuseas (síntomas de infarto inminente)"] } },
'Fístula gastrointestinal' : { intro: "Una fístula gastrointestinal es una conexión anormal, un conducto o 'túnel' que se forma entre el estómago o los intestinos y otro órgano del cuerpo, o que se abre paso directamente a través de la piel del abdomen.", whatIs: { title: "¿Qué es una Fístula Gastrointestinal?", text: "Normalmente, el tracto digestivo es un sistema cerrado que procesa los alimentos y ácidos. Cuando la pared del intestino se daña gravemente, puede perforarse y adherirse a un tejido cercano, creando una fuga. Esto permite que los fluidos altamente corrosivos e infectados del estómago o las heces se escapen por este túnel hacia lugares donde no pertenecen. Si el túnel conecta dos partes del intestino, se llama fístula enteroentérica; si conecta el intestino con la piel y gotea hacia el exterior, se llama fístula enterocutánea." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas varían según hacia dónde se filtren los líquidos digestivos:", groups: [ { name: "Síntomas Externos (Fístulas Enterocutáneas)", items: ["Filtración visible de fluidos intestinales (que pueden oler a heces, ser bilis verde o líquido turbio) a través de una herida abierta en la piel del abdomen", "Dolor intenso, enrojecimiento, irritación extrema y excoriación de la piel alrededor del área donde sale el líquido"] }, { name: "Síntomas Internos y Sistémicos", items: ["Dolor y sensibilidad abdominal constante y severa", "Fiebre alta, escalofríos y temblores (debido a la infección interna o peritonitis)", "Diarrea crónica, deshidratación profunda y alteraciones de los electrolitos", "Pérdida de peso muy rápida y desnutrición severa (ya que el cuerpo pierde los alimentos antes de poder absorber sus nutrientes)"] } ], warning: "Una fístula gastrointestinal que derrama contenido al interior de la cavidad abdominal (sin salida a la piel) causará una sepsis (infección en sangre) fatal muy rápidamente. Requiere cirugía de reanimación inmediata." }, types: { title: "Causas y Factores de Riesgo", intro: "Las fístulas rara vez ocurren de forma espontánea sin una patología severa previa:", items: ["Complicación Posquirúrgica (La causa más común, 80% de los casos): Fugas en las uniones (anastomosis) después de una cirugía abdominal para extirpar parte del intestino o por cáncer.", "Enfermedad Inflamatoria Intestinal: Muy característico y común en la Enfermedad de Crohn debido a la inflamación profunda que atraviesa las paredes del intestino.", "Diverticulitis severa (infección de las bolsas del colon que estallan y se pegan a la vejiga o la vagina).", "Traumatismos penetrantes en el abdomen (heridas de bala o arma blanca) o radioterapia agresiva para el cáncer pélvico."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para sellar la fuga, los cirujanos necesitan visualizar exactamente dónde inicia y termina el túnel:", items: ["Tomografía Computarizada (TC) de Abdomen con contraste: La prueba más esencial. Localiza la fístula, mide su tamaño y detecta si hay abscesos (bolsas de pus) peligrosos formándose en el abdomen.", "Fistulografía: Si la fístula tiene un agujero en la piel, el médico inyecta un líquido de contraste por ese orificio y toma radiografías para ver todo el recorrido del túnel hacia adentro del cuerpo.", "Estudios con ingestión de Bario: Se traga un líquido de contraste que brilla en los rayos X para ver por dónde se escapa a lo largo del tracto digestivo superior."] }, treatment: { title: "Tratamientos", intro: "El tratamiento es un desafío médico largo. Algunas fístulas pueden cerrarse solas si se controla la infección y la nutrición; otras requieren reconstrucción quirúrgica:", subsections: [ { title: "Manejo Médico y Quirúrgico", items: ["Control de la Infección: Antibióticos intravenosos agresivos y drenaje por radiología de cualquier bolsa de pus que se haya formado dentro del abdomen.", "Reposo Intestinal y Nutrición Parenteral Total (NPT): Para que el túnel sane, debe dejar de pasar comida y ácido por él. El paciente deja de comer por la boca por completo durante semanas, recibiendo todos los nutrientes directamente en la vena (NPT) para 'secar' la fístula.", "Cuidado experto de la piel: Si drena por la piel, se utilizan bolsas de ostomía y pastas barrera para recoger los fluidos corrosivos y proteger la carne de la quemadura ácida.", "Medicamentos para reducir los fluidos: Fármacos como la Somatostatina u Octreotida se inyectan para frenar drásticamente la producción de jugos gástricos e intestinales.", "Cirugía de Resección Intestinal: Si la fístula no se cierra sola tras meses de NPT, el cirujano debe abrir el abdomen, cortar y extirpar la sección del intestino que tiene el orificio, y volver a conectar los extremos sanos del intestino."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Ve a la sala de emergencias de inmediato si te has sometido a cirugía abdominal recientemente o tienes enfermedad de Crohn y notas:", items: ["La salida de fluidos, pus con mal olor, o heces a través de una incisión quirúrgica que parecía estar sanando", "Fiebre alta, dolor de estómago insoportable que empeora al moverte, o abdomen que se vuelve duro como una tabla", "Vómitos constantes e incapacidad para retener líquidos"] } },
'Ronchas o habones' : { intro: "Las ronchas o habones, médicamente conocidas como urticaria, son una reacción de la piel muy común caracterizada por la aparición repentina de bultos o parches elevados, de color rojo o pálido, que causan una picazón intensa.", whatIs: { title: "¿Qué son las Ronchas o Urticaria?", text: "La urticaria es una respuesta del sistema inmunológico. Cuando el cuerpo entra en contacto con un desencadenante (alergia, virus, estrés, etc.), ciertas células de la piel llamadas mastocitos se abren y liberan grandes cantidades de histamina y otros químicos. La histamina hace que los vasos sanguíneos minúsculos goteen líquido hacia las capas superficiales de la piel, formando las ronchas hinchadas. Las ronchas tienen una característica única: son muy volátiles, cambiando de tamaño, fusionándose, desvaneciéndose en unas pocas horas y apareciendo en otra parte del cuerpo de un momento a otro." }, symptoms: { title: "Síntomas y Características Visibles", intro: "Los signos varían desde unos pocos puntos hasta cubrir el cuerpo entero:", groups: [ { name: "Apariencia de la Piel", items: ["Placas, ronchas o habones en relieve, que pueden ser del tamaño de un guisante o tan grandes como un plato", "El color suele ser rojizo, pero el centro a menudo se vuelve blanco (palidece) al presionarlo con el dedo", "Picazón extrema, punzante o sensación de ardor incontrolable", "Erupción migratoria: Una roncha individual rara vez dura más de 24 horas en el mismo lugar; desaparecen sin dejar cicatriz mientras otras nuevas surgen en otras zonas."] } ], warning: "Si las ronchas aparecen de golpe tras tomar un medicamento, comer o una picadura, y se acompañan de hinchazón profunda debajo de la piel en los labios, los ojos o la lengua (angioedema), o sientes dificultad para respirar o tragar, es el comienzo de una anafilaxia mortal. Exige uso de Epinefrina y 911 de inmediato." }, types: { title: "Tipos de Urticaria", intro: "El tratamiento difiere según cuánto tiempo ha durado la afección:", items: ["Urticaria Aguda: Dura menos de 6 semanas. Es la inmensa mayoría de los casos. A menudo desaparece en unos días. Causada por reacciones alérgicas o infecciones virales transitorias.", "Urticaria Crónica (Espontánea): Ocurre casi todos los días y dura MÁS de 6 semanas (a veces años). Rara vez es una alergia a algo externo; a menudo es un problema autoinmune donde el propio cuerpo ataca a los mastocitos de la piel sin un desencadenante claro.", "Urticaria Inducible (Física): Las ronchas aparecen solo debido a un estímulo físico exacto: frotar la piel (dermografismo), frío extremo, calor, luz solar, vibración o sudor por ejercicio (urticaria colinérgica)."] }, causes: { title: "Causas y Desencadenantes Frecuentes", intro: "Encontrar la causa de las agudas es fácil, pero en las crónicas suele ser un misterio:", items: ["Alimentos alergénicos (nueces, cacahuetes, huevos, mariscos).", "Medicamentos (Penicilina, Aspirina, Ibuprofeno, medicamentos para la presión).", "Infecciones virales (resfriados o infecciones en niños son la causa número uno de ronchas agudas no alérgicas).", "Picaduras de insectos, látex, caspa de mascotas o polen.", "Estrés emocional intenso, problemas de tiroides o trastornos autoinmunes como el lupus (comunes en la urticaria crónica)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El dermatólogo o alergólogo lo diagnostica por la historia clínica:", items: ["Examen visual (si no hay ronchas en la visita, las fotos tomadas con el móvil son de gran ayuda).", "Para la urticaria aguda, el médico hará preguntas de investigación precisas ('¿qué comiste hoy?', '¿has tomado analgésicos nuevos?').", "Pruebas de alergia (Prick test) o análisis de sangre (si hay sospecha de alergia alimentaria o ambiental).", "Para la urticaria crónica, NO se suelen hacer pruebas de alergia extensas porque casi nunca son la causa; se pueden hacer análisis de tiroides o de marcadores autoinmunes."] }, treatment: { title: "Tratamientos", intro: "El objetivo del tratamiento es bloquear la histamina para calmar la picazón y hacer desaparecer los bultos:", subsections: [ { title: "Manejo Farmacológico", items: ["Antihistamínicos orales (no sedantes): Como la Cetirizina, Loratadina o Fexofenadina. Son el tratamiento de oro. Para la urticaria severa, el médico a menudo receta dosis hasta cuatro veces más altas que las dosis normales de las cajas para lograr apagar la reacción.", "Corticosteroides orales (Prednisona): Para brotes severos, agudos y generalizados que no responden a los antihistamínicos, se usa un ciclo corto de esteroides (3-5 días) para bajar la inflamación brutal. No se usan a largo plazo.", "Terapias Biológicas (Omalizumab / Xolair): En pacientes con urticaria crónica espontánea incontrolable que llevan meses sufriendo a pesar de tomar antihistamínicos altos, estas inyecciones mensuales bloquean el anticuerpo IgE y pueden curar el problema casi como por arte de magia.", "Autocuidados: Baños frescos, usar ropa holgada de algodón y evitar el calor, el alcohol o los AINEs, ya que todos ellos dilatan los vasos y empeoran la picazón."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Urgencias médicas inmediatas (911) si tus ronchas vienen con:", items: ["Dificultad para respirar, opresión en el pecho, o sibilancias", "Sensación de que tu garganta se cierra o la lengua/labios se hinchan desproporcionadamente", "Mareos severos o sensación de desmayo (bajada de presión arterial)"] } },
'Cardiopatía cianótica' : { intro: "Una cardiopatía cianótica es una categorización clínica de diversos defectos cardíacos congénitos (anomalías en la estructura del corazón presentes al nacer) que causan un nivel anormalmente bajo de oxígeno en la sangre que se distribuye al cuerpo.", whatIs: { title: "¿Qué es una Cardiopatía Cianótica?", text: "El lado derecho del corazón bombea sangre 'azul' (sin oxígeno) a los pulmones, y el lado izquierdo bombea sangre 'roja' (rica en oxígeno) a los órganos del cuerpo. En estos defectos, debido a problemas en las válvulas, a conexiones arteriales cruzadas, o a agujeros en las paredes del corazón, la sangre azul sin oxígeno se desvía directamente hacia el cuerpo sin pasar por los pulmones. Esta sangre desoxigenada que circula por las arterias tiñe los tejidos, dando a la piel, los labios y las uñas del bebé un color azulado o púrpura característico llamado cianosis." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "El color es la primera señal, a menudo visible poco después del nacimiento o en las primeras semanas:", groups: [ { name: "Signos Físicos y Comportamiento", items: ["Cianosis: Tinte azulado, grisáceo o púrpura oscuro en los labios, el interior de la boca, las encías, los dedos de manos y pies, y la piel general.", "Respiración acelerada, pesada y ruidosa, y dificultad para respirar de forma continua.", "Falta de aumento de peso y retraso en el crecimiento, ya que el cuerpo quema demasiada energía intentando oxigenarse.", "Fatiga extrema y sudoración profusa al intentar alimentarse del pecho o biberón.", "Acropaquia (dedos en palillo de tambor): Ensanchamiento redondeado de las puntas de los dedos de las manos y pies en niños mayores con la condición no reparada."] } ], warning: "Crisis Hipercianóticas (Crisis de Fallot): Ocurren episodios súbitos y letales donde el nivel de oxígeno cae a plomo. El bebé llora incontrolablemente, se pone muy azul o gris, entra en pánico y puede convulsionar o desmayarse. Es una emergencia médica absoluta que exige intervención inmediata." }, types: { title: "Tipos de Defectos Cianóticos", intro: "La cianosis puede ser causada por varias malformaciones estructurales diferentes:", items: ["Tetralogía de Fallot: La cardiopatía cianótica más común. Una combinación de cuatro defectos (agujero entre ventrículos, válvula pulmonar estrecha, aorta desplazada y músculo derecho grueso).", "Transposición de las Grandes Arterias (TGA): Las dos arterias principales que salen del corazón están invertidas o conectadas al revés. La sangre con oxígeno solo da vueltas en los pulmones, y la sangre sin oxígeno da vueltas por el cuerpo.", "Atresia Tricúspide: La válvula que conecta las cámaras derechas del corazón no existe (es sólida).", "Tronco Arterioso: Nacer con un solo vaso sanguíneo grande que sale del corazón en lugar de dos separados, mezclando sangre roja y azul."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se diagnostica inmediatamente tras el nacimiento o durante la ecografía fetal:", items: ["Oximetría de pulso (Cribado neonatal): Prueba indolora que mide el oxígeno en sangre colocando un sensor en la mano o el pie del bebé. Niveles crónicamente bajos indican el problema.", "Ecocardiograma: La prueba de oro y la más vital. Esta ecografía del corazón muestra la estructura defectuosa exacta, el tamaño de los agujeros, el estado de las válvulas y cómo se está desviando mal la sangre.", "Radiografía de tórax (puede mostrar un corazón anormalmente grande o con formas específicas, como el corazón en forma de 'bota' en la Tetralogía de Fallot).", "Cateterismo cardíaco: A veces necesario para medir las presiones exactas de sangre dentro del corazón antes de la cirugía."] }, treatment: { title: "Tratamientos", intro: "Casi todos los niños con este tipo de cardiopatía requerirán cirugía mayor para sobrevivir y tener una vida normal:", subsections: [ { title: "Manejo Médico Urgente y Cirugía", items: ["Medicamentos de rescate (Prostaglandinas): Si el bebé nace con ciertos defectos (como TGA), su única vía de vida es un pequeño conducto fetal. Los médicos administran inmediatamente Prostaglandina intravenosa para mantener este conducto abierto artificialmente hasta que se pueda operar.", "Procedimientos Paliativos (Temporales): Si el bebé es muy pequeño y prematuro, se pueden realizar cateterismos (como la Septostomía con balón para rasgar un agujero que mezcle la sangre) o colocar una derivación (Shunt de Blalock-Taussig) mediante cirugía para forzar un poco de sangre hacia los pulmones para que el bebé crezca unos meses.", "Cirugía a Corazón Abierto Definitiva: El cirujano cardiotorácico infantil repara el corazón cerrando los agujeros con parches, reconectando las arterias invertidas a sus cámaras correctas, o ensanchando las válvulas obstruidas. Las tasas de éxito son muy altas, pero a menudo requieren cirugías de revisión en el futuro a medida que el niño crece."] } ], note: "Incluso después de una reparación quirúrgica exitosa, los pacientes requieren seguimiento con un cardiólogo especialista en enfermedades congénitas de por vida para monitorear el ritmo cardíaco y la función de las válvulas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias inmediatamente si tu bebé o hijo pequeño:", items: ["Desarrolla una coloración azulada alrededor de la boca, los labios o los dedos mientras llora o come", "Está excesivamente somnoliento, flojo (sin tono muscular), inusualmente pálido y no responde al contacto normal", "Respira muy rápido, con esfuerzo, con hundimiento del pecho o hace gruñidos al final de cada respiración"] } },
'Bocio multinodular tóxico' : { intro: "El bocio multinodular tóxico (BMNT) es un agrandamiento de la glándula tiroides que contiene múltiples bultos o nódulos que se han vuelto hiperactivos. Estos nódulos producen un exceso incontrolado de hormona tiroidea, causando un cuadro clínico de hipertiroidismo.", whatIs: { title: "¿Qué es el Bocio Multinodular Tóxico?", text: "Normalmente, la glándula tiroides en el cuello responde a las señales del cerebro para producir la cantidad exacta de hormonas que el metabolismo necesita. Sin embargo, a lo largo de los años (a menudo debido a una falta crónica de yodo en la dieta), la tiroides puede crecer y formar múltiples nódulos (bocio multinodular). Ocasionalmente, uno o más de estos nódulos mutan y se vuelven 'autónomos' o 'tóxicos'. Empiezan a fabricar y liberar hormonas tiroideas por su cuenta, ignorando la orden del cerebro de detenerse, lo que acelera peligrosamente el motor de todos los órganos del cuerpo." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas combinan un problema físico en el cuello con una sobrecarga hormonal sistémica:", groups: [ { name: "Síntomas Locales (Efecto de Masa)", items: ["Agrandamiento visible y palpable en la base del cuello (un bocio), a menudo de aspecto asimétrico y con múltiples bultos", "Dificultad o molestia al tragar alimentos (disfagia)", "Sensación de presión, asfixia o dificultad para respirar al acostarse, si el bocio es muy grande y presiona la tráquea", "Ronquera o cambios en la voz"] }, { name: "Síntomas de Hipertiroidismo (Por Exceso Hormonal)", items: ["Pérdida de peso rápida e involuntaria, a pesar de tener un apetito feroz", "Palpitaciones cardíacas continuas, latidos rápidos (taquicardia) o ritmos cardíacos irregulares", "Sensación constante de calor, sudoración excesiva e intolerancia a climas cálidos", "Temblores finos en las manos y debilidad en los músculos de los muslos o brazos", "Nerviosismo intenso, ansiedad, irritabilidad, insomnio y fatiga por agotamiento", "Movimientos intestinales muy frecuentes o diarrea"] } ], warning: "En adultos mayores, el exceso prolongado de hormonas tiroideas desencadena frecuentemente una arritmia cardíaca grave llamada Fibrilación Auricular (aumentando el riesgo de derrame cerebral) y empeora drásticamente la osteoporosis y el riesgo de fracturas." }, types: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de esta enfermedad es un proceso crónico de envejecimiento de la glándula:", items: ["Evolución natural de un bocio previo: Suele aparecer en pacientes mayores de 60 años que han tenido un bocio nodular benigno (no tóxico) durante muchos años o décadas.", "Deficiencia de Yodo en la dieta durante la juventud: Es la causa más fuerte de bocios en el mundo; la tiroides crece intentando atrapar el poco yodo disponible y desarrolla nódulos para compensar.", "Mutaciones genéticas espontáneas en células tiroideas individuales que encienden permanentemente el 'interruptor' de producción hormonal.", "Ser mujer y tener edad avanzada incrementa sustancialmente el riesgo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere probar la sobrecarga de hormonas y encontrar el nódulo culpable:", items: ["Análisis de sangre (Perfil Tiroideo): La prueba TSH (hormona estimulante de la tiroides) estará extremadamente baja (suprimida a casi cero por el cerebro), mientras que las hormonas tiroideas libres (T3 y T4) estarán muy altas.", "Ecografía de Cuello: Mapea la anatomía de la tiroides, confirma la presencia de múltiples nódulos y evalúa si hay alguno con características sospechosas de cáncer.", "Gammagrafía Tiroidea (con yodo radiactivo): La prueba clave para diferenciarlo de otras enfermedades (como Graves). Se ingiere un yodo inofensivo. La máquina muestra que los nódulos hiperactivos o 'tóxicos' absorben todo el yodo de forma oscura (nódulos 'calientes'), mientras que el resto de la glándula normal se apaga."] }, treatment: { title: "Tratamientos", intro: "El objetivo es destruir de forma definitiva las fábricas de hormonas descontroladas (los nódulos tóxicos) o extirparlas físicamente:", subsections: [ { title: "Opciones de Terapia Definitiva", items: ["Yodo Radiactivo (I-131): El tratamiento de elección más común y seguro en adultos mayores. El paciente toma una cápsula de yodo radiactivo, el cual es absorbido casi exclusivamente por los nódulos hiperactivos. La radiación destruye esos nódulos desde adentro en unas semanas, encogiendo el bocio y curando el exceso hormonal sin cirugía.", "Cirugía (Tiroidectomía total o subtotal): La mejor opción si el bocio es gigantesco, está presionando y asfixiando la tráquea, si hay sospecha de cáncer de tiroides en la ecografía, o si el paciente no puede recibir yodo radiactivo. Tras extirpar la tiroides, el paciente tomará hormona en pastilla diaria (levotiroxina) de por vida.", "Medicamentos Antitiroideos (Metimazol o Propiltiouracilo): Pastillas que bloquean temporalmente la producción de hormonas. A diferencia de la enfermedad de Graves, estos fármacos rara vez 'curan' un bocio tóxico. Se utilizan principalmente para estabilizar los niveles hormonales del paciente durante unos meses antes de aplicar yodo radiactivo o entrar a cirugía de forma segura.", "Betabloqueadores (como Propranolol): Se administran inmediatamente para calmar el ritmo cardíaco acelerado y los temblores mientras actúan las terapias principales."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico general o endocrinólogo si:", items: ["Notas que tu cuello se está agrandando o puedes ver o sentir bultos al tacto", "Sufres palpitaciones cardíacas fuertes mientras estás en reposo sentado en el sofá", "Estás perdiendo peso rápidamente sin cambiar tu dieta, sientes debilidad o estás inexplicablemente agitado o sudoroso todo el tiempo"] } },
'Adenoma hipofisario secretor de prolactina' : { intro: "El adenoma hipofisario secretor de prolactina, universalmente conocido como prolactinoma, es el tipo más frecuente de tumor benigno (no canceroso) que afecta a la glándula pituitaria (hipófisis), ubicada en la base del cerebro.", whatIs: { title: "¿Qué es un Prolactinoma?", text: "La glándula pituitaria es del tamaño de un guisante y controla las hormonas principales del cuerpo. En este trastorno, las células normales que producen la hormona prolactina mutan y crecen formando un tumor, provocando la liberación descontrolada de enormes cantidades de esta hormona a la sangre. La prolactina es la hormona encargada de preparar los senos y estimular la producción de leche en las mujeres embarazadas. Fuera del embarazo, los niveles tóxicamente altos de prolactina envían una señal falsa al cerebro que inhibe y apaga por completo las hormonas reproductivas sexuales normales (estrógenos y testosterona) tanto en mujeres como en hombres." }, symptoms: { title: "Síntomas y Disfunción Reproductiva", intro: "Los síntomas provienen del 'apagón' de las hormonas sexuales y, si el tumor es muy grande, del aplastamiento del cerebro:", groups: [ { name: "Síntomas Exclusivos en Mujeres", items: ["Galactorrea: Producción y secreción de leche por uno o ambos pezones sin estar embarazada ni en período de lactancia", "Trastornos menstruales severos: Periodos erráticos, infrecuentes (oligomenorrea) o la desaparición total de la menstruación (amenorrea) durante meses", "Infertilidad debido a la falta de ovulación (es una de las causas más frecuentes y tratables de infertilidad femenina)", "Sequedad vaginal y dolor intenso durante el sexo debido a los bajísimos niveles de estrógeno"] }, { name: "Síntomas Exclusivos en Hombres", items: ["Disminución brusca o pérdida total de la libido (deseo sexual)", "Disfunción eréctil severa e intratable con pastillas comunes (por falta de testosterona)", "Infertilidad por recuento bajo o nulo de espermatozoides", "Ginecomastia (crecimiento anormal del tejido mamario), pérdida de vello facial/corporal, e incluso secreción de leche (muy raro)"] }, { name: "Síntomas Físicos por Compresión del Tumor (Macroadenomas)", items: ["Dolores de cabeza crónicos y persistentes debido a la presión en el cráneo", "Deterioro de la vista: Especialmente la pérdida de visión periférica (visión de túnel) porque un tumor gigante aplasta los nervios ópticos cruzados (quiasma óptico) justo por encima de la glándula"] } ], warning: "En los hombres, los síntomas sexuales suelen ignorarse por vergüenza, permitiendo que el tumor crezca durante años de forma silenciosa. Con frecuencia, los hombres no son diagnosticados hasta que el tumor es masivo (macroadenoma) y empiezan a perder la vista o sufren de fuertes dolores de cabeza." }, types: { title: "Clasificación Tumoral", intro: "El tratamiento y los síntomas compresivos dependen de su tamaño anatómico en la resonancia:", items: ["Microprolactinoma: El tumor mide menos de 1 centímetro (10 mm) de diámetro. Es la abrumadora mayoría de los casos encontrados en mujeres, ya que ellas buscan ayuda médica temprano por la pérdida de la regla.", "Macroprolactinoma: El tumor mide más de 1 centímetro (10 mm). Mucho más agresivos y comunes en hombres. Tienen alto riesgo de dañar la visión u otras hormonas sanas al aplastar la glándula pituitaria circundante."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es una combinación precisa de endocrinología e imágenes cerebrales:", items: ["Análisis de Sangre para Prolactina: La primera prueba. Niveles abrumadoramente elevados de prolactina (por ejemplo, cientos o miles de veces por encima de lo normal) son un indicador casi seguro de un prolactinoma. A menudo también se miden niveles de testosterona, estrógenos y hormonas tiroideas para evaluar el daño general.", "Descarte de otras causas: El embarazo o la lactancia real, problemas severos de hipotiroidismo, y el uso de fuertes medicamentos psiquiátricos (como antipsicóticos o antidepresivos) pueden disparar la prolactina de forma no tumoral.", "Resonancia Magnética (RM) del cerebro (enfocada en la silla turca con contraste): Es el método definitivo. Muestra el tamaño exacto del tumor en la pituitaria, si está sangrando por dentro, o si está empujando los nervios de los ojos.", "Examen oftalmológico de campo visual: Requerido si la RM muestra que el tumor roza los nervios ópticos."] }, treatment: { title: "Tratamientos", intro: "Los prolactinomas son únicos entre todos los tumores cerebrales: rara vez requieren una cirugía. Responden milagrosamente bien a un tratamiento en pastillas:", subsections: [ { title: "Manejo Farmacológico (La Gran Cura) y Alternativas", items: ["Medicamentos Agonistas de la Dopamina (Cabergolina o Bromocriptina): Es el tratamiento estándar y de oro absoluto. Estas pastillas imitan la dopamina en el cerebro, frenando la producción de prolactina. Funcionan de maravilla: en cuestión de días o semanas, los niveles hormonales vuelven a la normalidad, las mujeres vuelven a menstruar y ovular, y el tumor se reduce físicamente encogiéndose de tamaño hasta desaparecer de la resonancia magnética. Suelen tomarse durante varios años bajo estrecha vigilancia endocrina.", "Cirugía Transesfenoidal (Neurocirugía): Se considera una opción secundaria. El cirujano extirpa el tumor a través de la nariz y los senos paranasales. Solo se recurre a la cirugía si los medicamentos causan efectos secundarios insoportables, si el paciente tiene un tipo de tumor raro resistente a los fármacos, o si la visión está siendo rápidamente destruida por un tumor enorme que amenaza con ceguera inminente y no hay tiempo para esperar a que las pastillas funcionen.", "Radioterapia (Gamma Knife): El último recurso posible. Radiación de alta precisión usada si ni los medicamentos ni la cirugía logran controlar el crecimiento agresivo del tumor, con el riesgo de destruir permanentemente el resto de las hormonas pituitarias sanas con los años."] } ], note: "La fertilidad regresa rápidamente tras iniciar la Cabergolina. Las mujeres con prolactinomas que quedan embarazadas requieren atención endocrina y obstétrica conjunta especializada, ya que el tumor podría hincharse durante el embarazo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una cita con ginecología, urología o endocrinología si:", items: ["Tu periodo menstrual es errático, falla sistemáticamente durante meses, o tienes dificultades para quedar embarazada", "Notas que de tus senos (siendo hombre o mujer no embarazada) sale secreción lechosa blanquecina", "Eres un hombre que ha perdido bruscamente el deseo sexual y presenta incapacidad severa de erección inexplicable", "Sufres de dolores de cabeza frontales combinados con problemas para ver por el rabillo del ojo (perder los bordes de la visión)"] } },
'Hiperplasia suprarrenal congénita' : { intro: "La hiperplasia suprarrenal congénita (HSC) es un grupo de trastornos genéticos y hereditarios crónicos que afectan el funcionamiento de las glándulas suprarrenales, dos pequeños órganos con forma de nuez situados justo encima de cada riñón que son esenciales para la supervivencia.", whatIs: { title: "¿Qué es la Hiperplasia Suprarrenal Congénita?", text: "Las glándulas suprarrenales fabrican tres tipos vitales de hormonas: cortisol (la hormona de respuesta al estrés y mantenedora del azúcar), mineralocorticoides (que retienen el sodio y mantienen la presión arterial), y andrógenos (hormonas sexuales masculinas presentes en ambos sexos). En la HSC, los bebés nacen con un error genético que hace que sus glándulas carezcan de una enzima clave (casi siempre la 21-hidroxilasa) necesaria para fabricar cortisol. Al detectar esta falla mortal, el cerebro entra en pánico y estimula las glándulas sin descanso, forzándolas a crecer masivamente (hiperplasia). Como las glándulas están rotas y no pueden terminar de fabricar cortisol, toda la materia prima estimulada se desvía y se convierte en enormes y tóxicas cantidades de andrógenos, masculinizando y desequilibrando todo el cuerpo." }, symptoms: { title: "Síntomas y Señales Críticas", intro: "Los síntomas dependen de la severidad del fallo enzimático. La forma 'clásica' (grave) se nota al nacer o en la niñez, la 'no clásica' (leve) en la adolescencia o adultez:", groups: [ { name: "Forma Clásica Severa en Recién Nacidos (Pérdida de Sal - Emergencia Letal)", items: ["Genitales ambiguos en niñas al nacer: El exceso masivo de hormonas masculinas en el vientre materno hace que los genitales externos de la niña se asemejen a los de un niño (clítoris muy agrandado y labios fusionados), aunque sus órganos reproductivos internos femeninos (útero y ovarios) sean totalmente normales. Los niños nacen con apariencia normal.", "Crisis de Pérdida de Sal (Crisis Suprarrenal): Ocurre en los primeros días o semanas de vida porque tampoco pueden retener sodio. El bebé sufre vómitos explosivos, diarrea aguda, pérdida de peso alarmante, deshidratación fulminante, letargo profundo, azúcar peligrosamente bajo, shock circulatorio y coma fatal si no es ingresado en UCI para recibir esteroides."] }, { name: "Forma Clásica Simple Virilizante en Niños y Niñas", items: ["Pubertad extremadamente precoz: Aparición de vello púbico y axilar grueso, olor corporal y acné severo a edades inapropiadas, como a los 3, 4 o 5 años.", "Crecimiento óseo acelerado en la infancia inicial (son mucho más altos que sus compañeros de clase), pero los huesos se fusionan (cierran) muy temprano, resultando en una estatura de adulto extremadamente baja."] }, { name: "Forma No Clásica (Leve) en Adolescentes y Adultos Jóvenes", items: ["A menudo imita el Síndrome de Ovario Poliquístico en mujeres jóvenes.", "Desarrollo de acné quístico severo incontrolable", "Hirsutismo (crecimiento de vello oscuro y grueso en la cara, barbilla o pecho en mujeres) y calvicie de patrón masculino", "Periodos menstruales muy irregulares o ausentes, e infertilidad", "Baja estatura e inicio temprano de vello corporal"] } ], warning: "Para los pacientes con HSC clásica, un episodio de vómitos severos, diarrea grave o una cirugía son potencialmente mortales. Su cuerpo no puede fabricar más cortisol ante este estrés fisiológico físico, lo que desencadena una crisis suprarrenal fulminante. Requieren invariablemente inyecciones de hidrocortisona de emergencia." }, types: { title: "Causa y Factor Genético", intro: "La enfermedad es puramente un fallo heredado del ADN:", items: ["Deficiencia de 21-hidroxilasa: Responsable de más del 95% de los casos.", "Herencia Autosómica Recesiva: El trastorno NO aparece de la nada; ambos padres (incluso si están completamente sanos) deben portar el gen defectuoso recesivo oculto y pasarlo juntos al bebé. En parejas donde ambos son portadores, hay un 25% de probabilidad en cada embarazo de tener un hijo enfermo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "En la actualidad, las formas graves a menudo se detectan a tiempo para salvar la vida de los bebés, o incluso durante el embarazo:", items: ["Cribado Neonatal Sistémico (Prueba del talón): La gran mayoría de los países desarrollados hacen un pinchazo en el talón del recién nacido a las 48 horas para medir el nivel de 17-OH progesterona (que estará estratosféricamente alto en la HSC), lo que salva a los bebés de la crisis de sal.", "Análisis de Sangre Hormonal Completo: En niños o adultos con síntomas leves, se miden los andrógenos, cortisol, y la 17-OH progesterona basal y tras estímulo con ACTH sintético.", "Pruebas Genéticas de Sangre: Diagnóstico definitivo confirmando mutaciones en el gen CYP21A2.", "Diagnóstico Prenatal: Mediante amniocentesis genética si los padres saben que tienen un alto riesgo de tener un hijo afectado por casos anteriores."] }, treatment: { title: "Tratamientos", intro: "No existe cura genética, la enfermedad es de por vida. El tratamiento exige el reemplazo meticuloso e ininterrumpido de las hormonas que faltan, suplantando el trabajo de las glándulas dañadas para apagar el exceso de andrógenos:", subsections: [ { title: "Manejo Hormonal Vital, Quirúrgico y Preventivo", items: ["Reemplazo de Glucocorticoides (Hidrocortisona o Prednisona): Es el tratamiento principal y obligatorio de por vida para reemplazar el cortisol faltante. Esto engaña al cerebro diciéndole que la glándula ya está trabajando, por lo que el cerebro apaga el estímulo y las hormonas masculinas bajan drásticamente.", "Reemplazo de Mineralocorticoides (Fludrocortisona) y Sal: Cruciales para los pacientes 'perdedores de sal' con el fin de ayudar a sus riñones a retener el sodio y mantener estable su presión arterial, frecuentemente apoyados con píldoras de sal de sodio extras en bebés.", "Pautas de Dosificación de Estrés (Regla de Oro de Emergencia): Los pacientes, padres y profesores son entrenados exhaustivamente en que, ante cualquier fiebre alta, gripe fuerte, rotura de un hueso o vómitos, la dosis de esteroides debe duplicarse o triplicarse inmediatamente para evitar el shock y la muerte, portando siempre jeringas de hidrocortisona de emergencia para pinchar en el muslo si hay vómito.", "Cirugía Reconstructiva: En las niñas con genitales severamente ambiguos y masculinizados, un equipo de urólogos pediatras expertos en desórdenes del desarrollo sexual puede ofrecer cirugía reconstructiva compleja entre los 2 y 6 meses de vida para mejorar la funcionalidad y apariencia de los genitales femeninos urológicos.", "Tratamientos para la infertilidad y Antiandrógenos (para la forma no clásica en adultos) si se busca embarazo o se desea bloquear el vello facial excesivo."] } ], note: "Con un cumplimiento férreo de los medicamentos, control endocrinológico infantil continuo y atención médica aguda en momentos de estrés, las personas con HSC pueden tener una esperanza de vida normal, un desarrollo adecuado y lograr tener hijos sanos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es una situación de urgencia pediátrica o de desarrollo especializada. Actúa si:", items: ["El recién nacido se vuelve excesivamente letárgico, no quiere despertar para comer, sufre vómitos constantes tipo proyectil y parece estar perdiendo mucho peso en sus primeros días de vida en casa", "Notas signos perturbadores de pubertad en tu hijo o hija pequeño de 4 o 5 años, como vello en las axilas, olor corporal adulto, crecimiento de los genitales y un estirón de altura muy rápido", "Una joven adolescente sufre de acné indomable, vello facial de patrón masculino e irregularidad crónica en la regla"] } },
'Parálisis de Erb-Duchenne' : { intro: "La parálisis de Erb-Duchenne (o parálisis de Erb) es una forma de parálisis del brazo causada por una lesión en el grupo superior de los nervios principales del brazo (el plexo braquial), específicamente en las raíces nerviosas cervicales C5 y C6.", whatIs: { title: "¿Qué es la Parálisis de Erb-Duchenne?", text: "El plexo braquial es una red de nervios cerca del cuello que proporciona movimiento y sensibilidad al hombro, brazo, mano y dedos. En la parálisis de Erb, los nervios superiores se estiran, se desgarran o se arrancan de la médula espinal, generalmente debido a un traumatismo por tracción. Esto provoca debilidad o pérdida total de movimiento en el hombro y el bíceps." }, symptoms: { title: "Síntomas y Postura Característica", intro: "A menudo se identifica inmediatamente después del nacimiento por la posición del brazo del bebé:", groups: [ { name: "Signos Clínicos (Postura de 'propina de mesero')", items: ["El brazo cuelga inerte al costado del cuerpo", "El brazo está rotado hacia adentro (hacia el cuerpo)", "El codo está completamente extendido (recto) y el antebrazo está girado de modo que la palma mira hacia atrás", "Debilidad o incapacidad para levantar el brazo o flexionar el codo", "Pérdida de sensibilidad en la parte exterior del brazo"] } ], warning: "Si la lesión afecta también a las raíces nerviosas inferiores (C8-T1), se denomina parálisis global del plexo braquial, donde la mano y los dedos también quedan paralizados, empeorando el pronóstico." }, causes: { title: "Causas y Factores de Riesgo", intro: "Casi siempre es resultado de un estiramiento forzado del cuello y el hombro:", items: ["Distocia de hombros: La causa más común en recién nacidos. Durante un parto difícil, la cabeza del bebé sale, pero el hombro se atasca detrás del hueso pélvico de la madre, forzando un estiramiento extremo del cuello para liberar al bebé.", "Bebés muy grandes (macrosomía) o partos de nalgas.", "En adultos: Traumatismos graves, como accidentes de motocicleta o caídas sobre el hombro y la cabeza, que separan violentamente el cuello del hombro."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es principalmente clínico y neurológico:", items: ["Examen físico: El pediatra o neurólogo evalúa la debilidad muscular y la ausencia de reflejos (como el reflejo de Moro asimétrico en bebés).", "Electromiografía (EMG) y Estudios de Conducción Nerviosa: Para evaluar qué tan grave es el daño a la señal eléctrica del nervio.", "Radiografías o Resonancia Magnética (RM): Para descartar fracturas de clavícula (que pueden imitar la falta de movimiento por dolor) o visualizar un desgarro nervioso desde la médula (avulsión)."] }, treatment: { title: "Tratamientos", intro: "El tratamiento depende de la gravedad del desgarro nervioso; muchos bebés se recuperan naturalmente:", subsections: [ { title: "Rehabilitación y Cirugía", items: ["Fisioterapia diaria: Es el tratamiento principal. Movimientos de rango de movimiento pasivo para mantener las articulaciones flexibles y evitar que los músculos se atrofien o se acorten permanentemente (contracturas) mientras el nervio sana.", "Inyecciones de Toxina Botulínica (Botox): En músculos específicos para equilibrar las fuerzas y prevenir deformidades articulares.", "Cirugía Nerviosa (Microcirugía): Si no hay recuperación a los 3-6 meses de edad, un neurocirujano puede realizar injertos nerviosos (tomar un nervio de la pierna para empalmar el nervio roto) o transferencias nerviosas para devolver la función al brazo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita evaluación pediátrica urgente si:", items: ["Notas que tu bebé recién nacido no mueve un brazo en absoluto o lo mantiene en una posición rígida y anormal al costado", "Un brazo parece flácido o no reacciona a los estímulos táctiles como el otro"] } },
'Síndrome de Williams' : { intro: "El síndrome de Williams (o síndrome de Williams-Beuren) es un trastorno genético del desarrollo poco frecuente, caracterizado por problemas cardiovasculares, rasgos faciales distintivos y un perfil cognitivo y de personalidad único.", whatIs: { title: "¿Qué es el Síndrome de Williams?", text: "Esta condición es causada por la deleción (pérdida) de un pequeño segmento de material genético en el cromosoma 7. Esta región eliminada incluye el gen de la elastina, una proteína que proporciona elasticidad a los vasos sanguíneos y otros tejidos del cuerpo. La falta de esta proteína explica muchos de los problemas físicos, mientras que la pérdida de otros genes cercanos da forma a las diferencias neurológicas." }, symptoms: { title: "Síntomas y Características", intro: "Los individuos con este síndrome presentan un patrón de rasgos médicos, faciales y psicológicos:", groups: [ { name: "Rasgos Faciales y Físicos ('Facies Élfica')", items: ["Frente amplia, puente nasal aplanado con una nariz corta y respingona", "Mejillas llenas, boca ancha con labios gruesos y mentón pequeño", "Problemas dentales (dientes pequeños, muy espaciados o ausentes)", "Hipercalcemia en la infancia (niveles elevados de calcio en la sangre que causan irritabilidad extrema y cólicos)"] }, { name: "Perfil Neurológico y de Personalidad", items: ["Personalidad extremadamente extrovertida, empática y excesivamente amigable, incluso con extraños (falta de ansiedad social normal)", "Retraso en el desarrollo y discapacidad intelectual de leve a moderada", "Ansiedad severa y fobias (especialmente a ruidos fuertes o zumbidos, conocido como hiperacusia)", "Fuerte afinidad y talento musical a pesar de otras dificultades de aprendizaje"] }, { name: "Problemas Cardiovasculares", items: ["Estenosis aórtica supravalvular (SVAS): Estrechamiento de la arteria principal justo por encima del corazón (el riesgo médico más grave y común)"] } ], warning: "Las complicaciones cardiovasculares, especialmente la estenosis aórtica, pueden causar insuficiencia cardíaca súbita. Requieren monitoreo cardiológico de por vida." }, causes: { title: "Causas y Genética", intro: "Es un trastorno genético, pero casi nunca se hereda:", items: ["Mutación de novo: En la inmensa mayoría de los casos, la deleción en el cromosoma 7 (7q11.23) ocurre al azar durante la formación del óvulo o el espermatozoide antes de la concepción.", "Si una persona tiene el síndrome de Williams, tiene un 50% de probabilidad de transmitirlo a sus hijos (herencia autosómica dominante)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La sospecha clínica se confirma invariablemente con pruebas genéticas:", items: ["Prueba de hibridación in situ con fluorescencia (FISH): Una prueba de sangre genética especializada que busca específicamente si falta el gen de la elastina en el cromosoma 7.", "Análisis de microarreglos cromosómicos (CMA): Para identificar el tamaño exacto de la porción genética faltante.", "Ecocardiograma: Obligatorio e inmediato tras el diagnóstico para evaluar la estructura del corazón y los vasos sanguíneos.", "Análisis de calcio en sangre (especialmente en bebés)."] }, treatment: { title: "Tratamientos", intro: "No existe cura para el síndrome. El tratamiento se enfoca en manejar los síntomas médicos y maximizar el potencial de desarrollo:", subsections: [ { title: "Manejo Médico y Multidisciplinario", items: ["Cardiología: Chequeos regulares y, si la estenosis aórtica o pulmonar es grave, cirugía de corazón abierto para ensanchar los vasos sanguíneos estrechados.", "Nutrición: Dieta baja en calcio y vitamina D si el paciente sufre de hipercalcemia.", "Terapias del desarrollo: Terapia del habla, ocupacional y física desde una edad temprana para abordar los retrasos motores y mejorar el aprendizaje.", "Apoyo Psicológico: Terapia cognitivo-conductual para manejar la ansiedad extrema, las fobias y el TDAH concurrente.", "Educación Especial: Programas escolares adaptados que aprovechen sus fortalezas verbales y musicales, mientras apoyan sus debilidades visuoespaciales."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama la atención de tu pediatra si tu hijo:", items: ["Presenta retrasos significativos para alcanzar los hitos del desarrollo (sentarse, caminar)", "El pediatra detecta un soplo cardíaco inusual durante una revisión de rutina", "Tiene problemas graves de alimentación, cólicos extremos inexplicables y vómitos en la infancia temprana (posible hipercalcemia)"] } },
'Espasticidad' : { intro: "La espasticidad es un trastorno motor caracterizado por un aumento anormal, continuo e involuntario del tono muscular (rigidez), lo que provoca que los músculos se mantengan contraídos y tensos, dificultando el movimiento normal, la postura y el habla.", whatIs: { title: "¿Qué es la Espasticidad?", text: "El movimiento muscular normal requiere un equilibrio perfecto entre las señales del cerebro que ordenan a los músculos contraerse y las que ordenan relajarse. En la espasticidad, una lesión en el sistema nervioso central (cerebro o médula espinal) rompe este circuito de comunicación. Las señales que inhiben la contracción se bloquean, dejando a los músculos en un estado de hiperactividad constante. Los músculos se contraen de forma refleja y poderosa al intentar estirarlos." }, symptoms: { title: "Síntomas Comunes", intro: "La gravedad varía desde una leve rigidez hasta contracciones dolorosas incontrolables:", groups: [ { name: "Signos Clínicos y Funcionales", items: ["Hipertonía: Resistencia fuerte y repentina al estiramiento pasivo de un músculo (como una navaja que se cierra de golpe).", "Espasmos musculares involuntarios, dolorosos y a menudo rápidos", "Clonus: Contracciones musculares rítmicas y rápidas (temblores), frecuentemente en el tobillo al apoyar el pie", "Posturas anormales y fijas (por ejemplo, puños apretados, brazos flexionados contra el pecho, o piernas que se cruzan como tijeras al caminar - marcha en tijera)", "Reflejos tendinosos profundos hiperactivos y exagerados (al golpear la rodilla con un martillo)", "Dolor sordo en los músculos tensos y fatiga extrema"] } ], warning: "Si la espasticidad no se trata con fisioterapia y estiramientos, el músculo y los tendones acortados se congelarán permanentemente en esa posición, causando una deformidad irreversible llamada contractura articular." }, types: { title: "Causas y Origen", intro: "Es un síntoma de un daño neurológico superior, nunca un problema del músculo en sí. Causado por:", items: ["Parálisis Cerebral: La causa más común en niños (daño cerebral antes, durante o poco después del nacimiento).", "Esclerosis Múltiple (EM): Afecta comúnmente las piernas, causando gran rigidez en adultos.", "Accidente Cerebrovascular (Ictus): Provoca espasticidad típicamente en un solo lado del cuerpo (hemiplejia).", "Traumatismos Craneoencefálicos graves o Lesiones de la Médula Espinal.", "Enfermedades neurodegenerativas como la ELA (Esclerosis Lateral Amiotrófica)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es diagnosticada clínicamente por un neurólogo o fisiatra:", items: ["Examen Físico y Neurológico: El médico evaluará el tono muscular doblando y estirando las extremidades del paciente a diferentes velocidades, evaluando los reflejos y la postura.", "Escala de Ashworth Modificada: Una herramienta clínica para clasificar numéricamente la gravedad de la resistencia del músculo.", "Pruebas de Imagen (RM o TC) del cerebro y la médula espinal para localizar la lesión exacta que está causando la interrupción de las señales nerviosas."] }, treatment: { title: "Tratamientos", intro: "El objetivo no es 'curar' el daño cerebral, sino relajar los músculos para mejorar la movilidad, aliviar el dolor y prevenir deformidades:", subsections: [ { title: "Terapias Físicas y Medicamentos", items: ["Fisioterapia y Terapia Ocupacional: El pilar absoluto del manejo. Ejercicios diarios de estiramiento pasivo y activo para alargar el músculo, fortalecimiento de los músculos opuestos y uso de férulas (ortesis) para mantener las articulaciones estiradas.", "Relajantes Musculares Orales: Fármacos como el Baclofeno, Tizanidina o Diazepam que actúan en el sistema nervioso para calmar la actividad muscular. Pueden causar mucha somnolencia.", "Inyecciones de Toxina Botulínica (Botox): Altamente efectivas para la espasticidad focal. Se inyecta directamente en el músculo más rígido, paralizándolo parcialmente y permitiendo meses de alivio y rehabilitación sin afectar el resto del cuerpo.", "Bomba de Baclofeno Intratecal: Para la espasticidad severa generalizada. Se implanta quirúrgicamente una bomba en el abdomen que inyecta el medicamento directamente en el líquido de la médula espinal, requiriendo dosis minúsculas y sin causar sueño.", "Cirugía Ortopédica o Neurocirugía (Rizotomía Dorsal Selectiva): Cortar nervios sensoriales específicos en la médula para cortar el arco reflejo hiperactivo, o cirugías de alargamiento de tendones si ya hay contracturas severas."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico especialista si tú o tu hijo:", items: ["Experimentan rigidez muscular que interfiere con actividades diarias, como vestirse, caminar o asearse", "Sufren de calambres o espasmos dolorosos recurrentes que los despiertan por la noche", "Notas que las articulaciones (codos, rodillas, manos) están cada vez más difíciles de enderezar completamente"] } },
'Adenoma secretante' : { intro: "Un adenoma secretante (o adenoma hipofisario funcional) es un tumor benigno (no canceroso) que se forma en la glándula pituitaria (hipófisis) en la base del cerebro, el cual produce y libera cantidades excesivas de hormonas activas al torrente sanguíneo.", whatIs: { title: "¿Qué es un Adenoma Secretante?", text: "La glándula pituitaria es la 'glándula maestra' del cuerpo, responsable de enviar hormonas que controlan la tiroides, las glándulas suprarrenales, el crecimiento y las funciones reproductivas. En este trastorno, un grupo de células de la pituitaria muta y forma un bulto. A diferencia de los adenomas no funcionantes (que solo causan problemas por su tamaño), un adenoma secretante se comporta como una fábrica de hormonas fuera de control, inundando el cuerpo con químicos que causan graves síndromes endocrinos." }, symptoms: { title: "Síntomas y Síndromes Endocrinos", intro: "Los síntomas dependen exclusivamente de QUÉ hormona está sobreproduciendo el tumor, además de posibles síntomas por compresión si el tumor crece mucho:", groups: [ { name: "Síntomas por Tumor Gigante (Macroadenoma)", items: ["Dolores de cabeza crónicos por presión en el cráneo", "Pérdida de la visión periférica (visión de túnel) porque el tumor aplasta el quiasma óptico (nervios visuales cruzados sobre la pituitaria)"] }, { name: "Prolactinoma (Exceso de Prolactina - El más común)", items: ["En mujeres: Producción de leche materna sin estar embarazada (galactorrea), menstruaciones irregulares o ausentes (amenorrea) e infertilidad.", "En hombres: Disfunción eréctil, pérdida de deseo sexual, agrandamiento de los senos (ginecomastia) y pérdida de vello corporal."] }, { name: "Somatotropinoma (Exceso de Hormona del Crecimiento)", items: ["En adultos causa Acromegalia: Engrosamiento grotesco de manos, pies y rasgos faciales, sudoración y dolores articulares.", "En niños causa Gigantismo: Crecimiento de estatura desproporcionado."] }, { name: "Corticotropinoma (Exceso de ACTH)", items: ["Causa la Enfermedad de Cushing: Aumento de peso rápido en el tronco, cara de 'luna llena', estrías moradas en el abdomen, debilidad muscular profunda y presión arterial alta severa."] } ], warning: "Si un adenoma sufre una hemorragia interna repentina (Apoplejía Pituitaria), causará un dolor de cabeza fulminante, pérdida de visión rápida y colapso cardiovascular por falta aguda de hormonas. Es una emergencia neuroquirúrgica inminente." }, types: { title: "Causas y Genética", intro: "El origen de estos tumores suele ser esporádico:", items: ["Mutaciones de ADN adquiridas (esporádicas): Ocurren al azar en una célula pituitaria y no se heredan.", "Neoplasia Endocrina Múltiple Tipo 1 (NEM 1): Un raro trastorno genético hereditario que hace que las personas desarrollen múltiples tumores en las glándulas endocrinas, incluida la pituitaria, el páncreas y las paratiroides."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una combinación de endocrinología y neuroimagen:", items: ["Análisis completos de sangre y orina: Para medir los niveles de las hormonas producidas por la pituitaria (Prolactina, GH, IGF-1, ACTH, Cortisol) y confirmar qué eje hormonal está fuera de control.", "Resonancia Magnética (RM) Cerebral con Gadolinio: El método de imagen más sensible. Permite visualizar la glándula pituitaria con alta precisión para detectar el tamaño exacto del tumor (microadenoma < 1cm, macroadenoma > 1cm) y su proximidad a los nervios ópticos.", "Examen de Campo Visual: Un oftalmólogo evalúa si el tumor ha comenzado a cegar zonas de la visión periférica del paciente."] }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del tipo de hormona que secrete el tumor. El objetivo es curar el exceso hormonal, detener el crecimiento y preservar la visión:", subsections: [ { title: "Manejo Médico, Quirúrgico y Radioterápico", items: ["Medicamentos (Primera línea para Prolactinomas): Sorprendentemente, los tumores secretores de prolactina casi nunca se operan primero. Fármacos agonistas de la dopamina (Cabergolina o Bromocriptina) encogen el tumor drásticamente y normalizan las hormonas en pocos meses tomando pastillas.", "Cirugía Transesfenoidal (Primera línea para el resto): Para adenomas que secretan hormona del crecimiento (Acromegalia) o ACTH (Cushing). El neurocirujano introduce instrumentos endoscópicos a través de la nariz y los senos paranasales para extirpar el tumor sin necesidad de abrir el cráneo.", "Medicamentos de Segunda Línea: Análogos de la somatostatina (para frenar la hormona del crecimiento) o inhibidores de esteroides si la cirugía no puede extirpar todo el tumor.", "Radioterapia (Gamma Knife o Radiocirugía Estereotáctica): Se utiliza si parte del tumor permanece después de la cirugía y sigue siendo hormonalmente activo, o en pacientes inoperables. Destruye las células tumorales de forma lenta y precisa a lo largo de los años."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un endocrinólogo o a tu médico si experimentas:", items: ["Secreción inusual de líquido o leche por los pezones (sin embarazo)", "Ausencia inexplicable de tus periodos menstruales junto con pérdida de visión lateral", "Aumento de peso muy rápido, aparición de estrías moradas intensas, o cambios inexplicables en la forma de tus manos, mandíbula o talla de zapatos"] } },
'Mioma' : { intro: "Un mioma uterino (también conocido como leiomioma o fibroma) es un tumor sólido, duro y no canceroso (benigno) compuesto de tejido muscular y fibroso que crece en la pared del útero de la mujer. Son sumamente comunes durante los años fértiles.", whatIs: { title: "¿Qué es un Mioma?", text: "El útero está formado por capas de músculo liso diseñadas para expandirse durante el embarazo y contraerse en el parto. A veces, una sola célula muscular muta y se multiplica bajo la influencia de las hormonas femeninas, formando un nódulo o masa similar a una pelota de goma. Los miomas nunca se convierten en cáncer. Pueden ser diminutos como un guisante o crecer tanto como un melón, distorsionando y agrandando la forma de la matriz." }, symptoms: { title: "Síntomas y Molestias", intro: "Muchísimas mujeres tienen miomas y nunca lo saben porque no causan síntomas. Cuando sí causan problemas (generalmente dependiendo de su ubicación y tamaño), provocan:", groups: [ { name: "Síntomas Menstruales y Reproductivos", items: ["Sangrado menstrual extremadamente abundante (menorragia), con expulsión de grandes coágulos de sangre", "Periodos menstruales muy prolongados (que duran más de una semana)", "Anemia severa, debilidad y fatiga crónica como resultado de la enorme pérdida de sangre mes a mes", "Dificultad para quedar embarazada o abortos espontáneos recurrentes (especialmente si el mioma crece dentro de la cavidad del útero)"] }, { name: "Síntomas por Efecto de Masa (Compresión)", items: ["Presión, pesadez o dolor sordo en la región pélvica baja", "Necesidad constante y urgente de orinar o incapacidad para vaciar la vejiga por completo (si el mioma presiona la vejiga urinaria)", "Estreñimiento o dolor en la parte baja de la espalda (si el mioma presiona el recto o los nervios espinales)", "Dolor profundo durante las relaciones sexuales (dispareunia)"] } ], warning: "Si experimentas un dolor pélvico repentino, agudo y punzante acompañado de fiebre, un mioma que cuelga de un tallo puede haberse retorcido cortando su propio suministro de sangre (torsión del mioma), requiriendo cirugía de urgencia." }, types: { title: "Tipos de Miomas por Ubicación", intro: "La posición del mioma dicta los síntomas:", items: ["Intramurales: Crecen dentro de la pared muscular del útero. Son los más comunes y causan que el útero se sienta agrandado.", "Subserosos: Crecen proyectándose hacia afuera del útero, hacia la cavidad pélvica. Suelen presionar otros órganos causando síntomas de 'peso', pero no alteran tanto la menstruación.", "Submucosos: Crecen abultándose hacia el interior de la cavidad uterina hueca. Son la causa principal de hemorragias menstruales severas, dolorosas y de problemas de infertilidad.", "Pediculados: Están unidos al útero por una base estrecha o 'tallo', como un hongo."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El ginecólogo los detecta frecuentemente por accidente en exámenes de rutina:", items: ["Examen Pélvico: El médico palpará un útero agrandado, firme o de forma irregular.", "Ecografía Transvaginal: La prueba principal e indolora. Utiliza ondas sonoras para crear una imagen clara de la pared uterina, confirmando la cantidad, tamaño y ubicación exacta de los miomas.", "Histeroscopia: Se introduce una cámara muy fina por la vagina hacia el útero. Vital si la paciente tiene hemorragias severas o infertilidad, para ver directamente los miomas submucosos.", "Resonancia Magnética (RM): Solo se utiliza si el diagnóstico no está claro, se planea una cirugía compleja para preservar el útero, o para descartar raros cánceres uterinos."], note: "" }, treatment: { title: "Tratamientos", intro: "Si los miomas no causan problemas, no necesitan tratamiento ('espera vigilante'). Si interfieren con la vida o la salud, las opciones van desde pastillas hasta cirugías:", subsections: [ { title: "Manejo Médico y Quirúrgico Conservador de Órgano", items: ["Medicamentos hormonales: Las píldoras anticonceptivas o los DIU liberadores de progesterona (Mirena) NO reducen el tamaño de los miomas, pero controlan y detienen exitosamente los sangrados menstruales pesados y los cólicos.", "Agonistas de la GnRH (Lupron): Inyecciones que ponen temporalmente a la mujer en estado de menopausia química. Sin hormonas, los miomas se encogen dramáticamente y la anemia mejora. Solo se usan por unos meses antes de una cirugía para facilitar la extracción.", "Ácido Tranexámico: Medicamento no hormonal que se toma durante la regla para ayudar a que la sangre coagule y reducir la hemorragia.", "Embolización de Arterias Uterinas (UAE): Un radiólogo inyecta partículas plásticas diminutas en las arterias que alimentan el útero. Sin sangre, los miomas se mueren de hambre y se encogen. Es no quirúrgico, pero no se recomienda si se desea un embarazo futuro.", "Miomectomía: Extracción quirúrgica exclusiva de los miomas, reconstruyendo el útero. Es el tratamiento ideal para mujeres que desean preservar su fertilidad y tener hijos. Puede hacerse por laparoscopia, histeroscopia o cirugía abierta."] }, { title: "Cirugía Definitiva", items: ["Histerectomía: Extirpación quirúrgica completa del útero. Es la única cura definitiva garantizada para los miomas, asegurando que nunca vuelvan a crecer. Implica el fin de la capacidad de gestar y de la menstruación."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Programa una cita con tu ginecólogo si presentas:", items: ["Dolor pélvico o pesadez crónica que no desaparece", "Menstruaciones excesivamente abundantes, donde necesitas cambiarte la compresa o el tampón cada hora, o manchas la ropa y las sábanas por la noche", "Periodos que duran repetidamente más de 8 a 10 días", "Dificultad evidente para orinar o vaciar la vejiga"] } },
'Eclampsia' : { intro: "La eclampsia es una complicación extremadamente grave, rara y potencialmente mortal del embarazo, el parto o el puerperio inmediato. Representa la fase más crítica de los trastornos hipertensivos del embarazo, marcando el momento en que la preeclampsia (presión arterial alta y daño a los órganos) evoluciona causando convulsiones incontrolables en la madre.", whatIs: { title: "¿Qué es la Eclampsia?", text: "Durante el embarazo, algunas mujeres desarrollan preeclampsia, una condición en la que los vasos sanguíneos se contraen y se dañan, elevando peligrosamente la presión arterial y afectando a órganos como los riñones, el hígado y el cerebro. Cuando esta inflamación y alta presión abruman y lesionan el cerebro de la madre, las neuronas sufren un cortocircuito eléctrico masivo. Este fallo desencadena convulsiones tónico-clónicas (ataques) o, en el peor de los casos, un coma profundo. La eclampsia pone en riesgo inminente de asfixia y muerte tanto a la madre como al feto debido al desprendimiento de la placenta o hemorragia cerebral." }, symptoms: { title: "Síntomas Precursores y Crisis", intro: "Antes de la convulsión, el cuerpo suele dar señales de alerta neurológica muy fuertes (preeclampsia con criterios de severidad):", groups: [ { name: "Señales de Alerta de Emergencia Inminente", items: ["Dolor de cabeza agudo, pulsátil y severo que no se alivia con medicamentos comunes", "Alteraciones visuales dramáticas: ver puntos negros (escotomas), destellos de luz, visión borrosa o pérdida temporal de la visión", "Dolor intenso, opresivo o sensación de quemazón en la parte superior derecha del abdomen, justo debajo de las costillas (dolor de hígado)", "Aumento repentino y masivo de la hinchazón (edema), especialmente en la cara, las manos y alrededor de los ojos", "Cambios mentales bruscos: confusión, agitación o nerviosismo extremo"] }, { name: "La Crisis (Eclampsia)", items: ["Aparición de convulsiones tónico-clónicas (el cuerpo se pone rígido, seguido de sacudidas rítmicas incontrolables violentas)", "Pérdida total del conocimiento durante y después de la convulsión", "Incapacidad de respirar durante la convulsión, lo que corta el flujo de oxígeno al bebé"] } ], warning: "Toda mujer embarazada debe saber que un dolor de cabeza extremo, visión borrosa y dolor bajo las costillas derechas a partir de la semana 20 de gestación es una urgencia absoluta y debe ir a la sala de partos o emergencias de inmediato." }, types: { title: "Causas y Factores de Riesgo", intro: "La causa raíz radica en un desarrollo defectuoso de la placenta desde las primeras etapas del embarazo:", items: ["Vasos placentarios estrechos: La placenta no se ancla bien al útero y recibe mala circulación. La placenta enferma libera toxinas a la sangre materna que dañan todo el endotelio (revestimiento de las venas) del cuerpo de la madre.", "Falta de Control Prenatal: Mujeres que desarrollan preeclampsia silenciosa pero no acuden al médico para medirse la presión.", "Factores de riesgo: Ser el primer embarazo, tener antecedentes de preeclampsia previa, obesidad severa, hipertensión crónica o diabetes previas, embarazo múltiple (gemelos) o tener más de 35 años o menos de 20."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de eclampsia es clínico visual (ver la convulsión) en un contexto de preeclampsia:", items: ["Presencia de convulsiones generalizadas en una mujer embarazada o recién parida que no pueden atribuirse a epilepsia u otras causas cerebrales (como un tumor o drogas).", "Medición de presión arterial (suele estar peligrosamente elevada, por ejemplo, >160/110 mmHg).", "Análisis de orina (buscando niveles masivos de proteína, proteinuria).", "Análisis de sangre urgente: Para evaluar si el hígado y los riñones están fallando, y para descartar el Síndrome HELLP (destrucción de glóbulos rojos, enzimas hepáticas elevadas y plaquetas bajas, una variante crítica)."] }, treatment: { title: "Tratamientos", intro: "La eclampsia es una emergencia de vida o muerte. El tratamiento exige estabilizar a la madre y dar a luz al bebé lo más rápido posible, ya que la única cura real para la enfermedad es sacar la placenta enferma del cuerpo:", subsections: [ { title: "Intervenciones de Emergencia", items: ["Sulfato de Magnesio: El pilar absoluto del tratamiento. Es un medicamento que se administra de inmediato por vía intravenosa. Es extraordinariamente efectivo para deprimir el sistema nervioso central, detener la convulsión en curso y prevenir convulsiones futuras. Supera con creces a cualquier otro medicamento anticonvulsivo tradicional.", "Control de la Presión Arterial: Se administran medicamentos intravenosos rápidos (Labetalol, Hidralazina o Nifedipino) para bajar la presión arterial de la madre a un nivel seguro y evitar un derrame cerebral masivo.", "Soporte Respiratorio: Administrar oxígeno y colocar a la paciente de lado para evitar que se asfixie con su vómito o lengua durante la crisis.", "Parto Inmediato (El Tratamiento Definitivo): Una vez que la madre deja de convulsionar y sus signos vitales están controlados, se debe proceder al parto de inmediato. Si el cuello uterino está listo y el bebé es estable, se puede inducir el parto vaginal, pero frecuentemente se requiere una cesárea de emergencia por el bienestar del feto."] } ], note: "El riesgo no desaparece al cortar el cordón umbilical. El riesgo de sufrir eclampsia y convulsiones sigue siendo muy alto durante las primeras 48 horas postparto, e incluso hasta semanas después. La madre debe seguir tomando medicamentos en casa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de urgencias de maternidad sin dudarlo ni un minuto si estás embarazada (más de 20 semanas) o acabas de dar a luz y presentas:", items: ["Dolor de cabeza pulsátil que empeora y no desaparece con Paracetamol", "Cambios en la visión: ves puntos ciegos, lucecitas, luces intermitentes, o tu vista se vuelve borrosa", "Dolor fuerte en la boca del estómago o debajo de las costillas del lado derecho", "Si alguien presencia a una mujer embarazada sufrir una convulsión, debe llamar al 911 de inmediato, colocarla de lado y proteger su cabeza de golpes"] } },
'Trastorno esquizoafectivo' : { intro: "El trastorno esquizoafectivo es una afección de salud mental compleja y crónica caracterizada por una combinación superpuesta de síntomas de psicosis (como los de la esquizofrenia) y síntomas severos de alteraciones del estado de ánimo (como los del trastorno bipolar o la depresión mayor).", whatIs: { title: "¿Qué es el Trastorno Esquizoafectivo?", text: "Se sitúa en un punto intermedio entre la esquizofrenia y los trastornos del estado de ánimo. Para el paciente, esto significa vivir en un péndulo de sufrimiento doble: por un lado, experimenta episodios en los que pierde contacto con la realidad, sufriendo alucinaciones auditivas, paranoia y pensamientos desorganizados. Por otro lado, sufre de ciclos severos de ánimo, ya sea cayendo en una depresión oscura e inmovilizante, o disparándose hacia un estado maníaco de hiperactividad extrema. Debido a esta mezcla de síntomas, a menudo es difícil de diagnosticar y tratar inicialmente." }, symptoms: { title: "Síntomas y Ciclos Clínicos", intro: "La presentación varía mucho entre personas, pero involucra dos dominios de síntomas:", groups: [ { name: "Síntomas Psicóticos (Esquizofrenia)", items: ["Alucinaciones: Ver, escuchar (lo más común es escuchar voces críticas o de mando), o sentir cosas que no existen en la realidad", "Delirios: Creencias falsas, fijas y a menudo paranoicas que la persona mantiene firmemente a pesar de las pruebas lógicas en contra (creer que están siendo espiados, perseguidos, o que tienen poderes especiales)", "Pensamiento y habla desorganizada: Saltar de un tema a otro sin lógica, hablar de forma incomprensible (ensalada de palabras) o responder preguntas con frases no relacionadas", "Comportamiento motor extraño o catatonia, y falta de higiene personal"] }, { name: "Síntomas del Estado de Ánimo (Estado de Ánimo Mayor)", items: ["Fase Depresiva: Tristeza profunda y abrumadora, sentimientos de vacío, llanto incontrolable, incapacidad para sentir placer, alteraciones en el sueño/apetito y fuertes pensamientos suicidas.", "Fase Maníaca (en el Tipo Bipolar): Estado de euforia repentina, grandiosidad, necesidad mínima de dormir durante días, hablar a gran velocidad, pensamientos acelerados y participación en conductas de alto riesgo y destructivas."] } ], warning: "Este trastorno conlleva un altísimo riesgo de aislamiento social, falta de vivienda, abuso de drogas (usadas para automedicarse y apagar las voces o la tristeza) y un riesgo muy elevado de intento de suicidio." }, types: { title: "Tipos de Trastorno", intro: "Existen dos tipos clínicamente diagnosticables dependiendo de los síntomas del estado de ánimo:", items: ["Tipo Bipolar: La persona experimenta episodios de psicosis mezclados con episodios de manía clínica (euforia y excitación extrema) y, a menudo, episodios de depresión mayor.", "Tipo Depresivo: La persona experimenta episodios de psicosis únicamente con episodios de depresión mayor profunda, sin presentar nunca estados de euforia o manía."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico psiquiátrico exigente que requiere tiempo y observación minuciosa para diferenciarlo de la esquizofrenia pura o el trastorno bipolar puro:", items: ["Criterios Clínicos (DSM-5): El psiquiatra debe confirmar que el paciente ha experimentado alucinaciones o delirios durante al menos dos semanas seguidas SIN que haya existido ningún episodio de alteración del estado de ánimo (ni depresión ni manía). Esto demuestra que el problema psicótico existe por sí solo.", "Evaluación longitudinal: Además del período de dos semanas de psicosis pura, los síntomas severos del estado de ánimo (depresión/manía) deben haber estado presentes durante la mayor parte de la duración total de la enfermedad.", "Evaluación médica y toxicológica: Análisis de sangre, escáneres cerebrales (RM) y paneles de drogas para descartar que los síntomas psicóticos sean causados por el abuso de metanfetaminas, alcoholismo crónico, tumores cerebrales, epilepsia del lóbulo temporal o problemas graves de tiroides."] }, treatment: { title: "Tratamientos", intro: "No existe cura, pero es altamente tratable con una combinación rigurosa y de por vida de medicamentos y psicoterapia:", subsections: [ { title: "Manejo Farmacológico y Psicológico", items: ["Medicamentos Antipsicóticos (Neurolépticos): Son el pilar para tratar los delirios y alucinaciones. Fármacos como la Paliperidona, Risperidona u Olanzapina ayudan a organizar el pensamiento y reconectar a la persona con la realidad (a menudo se usan versiones inyectables mensuales para asegurar el cumplimiento).", "Estabilizadores del Estado de Ánimo o Antidepresivos: Se recetan según el tipo de trastorno. El Litio, el Ácido Valproico o la Lamotrigina se utilizan para el tipo Bipolar, y los antidepresivos (ISRS) para el tipo Depresivo. Frecuentemente, el paciente debe tomar una polifarmacia (mezcla de varios medicamentos) diaria.", "Psicoterapia (TCC): Enseña a la persona a comprender su enfermedad, a desafiar la validez de los delirios ('probar la realidad'), a identificar señales tempranas de recaída y a manejar el profundo estigma social y la depresión.", "Entrenamiento en Habilidades para la Vida (Rehabilitación Social): Centrado en lo práctico: ayudar a la persona a aprender habilidades sociales básicas, mantener una buena higiene, gestionar el dinero y encontrar un empleo con apoyo para evitar la marginación y el desamparo institucional."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La persona afectada a menudo no es consciente de que está enferma (anosognosia), por lo que la familia debe intervenir. Busca atención psiquiátrica de urgencia si tú o tu ser querido:", items: ["Hablan sobre o planifican lastimarse a sí mismos, lastimar a otras personas, o sienten una desesperanza absoluta inmanejable", "Comienzan a hablar con personas inexistentes, expresan miedos paranoicos intensos y absurdos, o se vuelven incomprensibles", "Dejan de bañarse, de comer adecuadamente, o muestran una agitación eufórica incontrolable durante días sin dormir"] } },
'Estenosis raquídea' : { intro: "La estenosis raquídea es un estrechamiento de los espacios dentro de la columna vertebral, lo que puede ejercer presión sobre la médula espinal y los nervios que se extienden por ella.", whatIs: { title: "¿Qué es la Estenosis Raquídea?", text: "Es una condición degenerativa que ocurre más frecuentemente en la parte baja de la espalda (lumbar) y en el cuello (cervical). A medida que el canal espinal se estrecha debido al desgaste y al envejecimiento, comprime los nervios, causando dolor crónico, entumecimiento y debilidad muscular en las extremidades." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen aparecer gradualmente y empeorar con el tiempo:", groups: [ { name: "Síntomas según la ubicación", items: ["Estenosis Lumbar: Dolor, pesadez o calambres en las piernas al estar de pie o caminar por periodos prolongados (claudicación neurogénica), que se alivia notablemente al inclinarse hacia adelante (como al apoyarse en un carrito de supermercado) o al sentarse.", "Estenosis Cervical: Entumecimiento, hormigueo o debilidad en un brazo, mano, pierna o pie, dolor de cuello y problemas de equilibrio o torpeza al caminar."] } ], warning: "En casos graves, la estenosis cervical puede causar disfunción de la médula espinal (mielopatía), provocando parálisis y pérdida permanente de control de los esfínteres." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa más común es el desgaste óseo relacionado con la edad (artrosis):", items: ["Osteoartritis: El desgaste del cartílago provoca la formación de crecimientos óseos (espolones óseos) que invaden el canal espinal.", "Hernias de disco: El material blando del disco se seca, se agrieta y se filtra, presionando los nervios.", "Engrosamiento de los ligamentos: Las cuerdas que mantienen unida la columna pueden volverse gruesas y rígidas con los años, abultándose hacia el canal.", "Traumatismos de la columna vertebral, tumores o enfermedades óseas como la enfermedad de Paget.", "Estenosis congénita (nacer con un canal espinal estrecho)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista en columna requiere pruebas de imagen detalladas para ver la compresión:", items: ["Resonancia Magnética (RM): La prueba de elección para ver claramente los nervios, los discos blandos y determinar exactamente qué tan apretados están los nervios.", "Tomografía Computarizada (TC) o Mielograma por TC: Muy útil para ver la estructura del hueso y los espolones óseos (especialmente en personas que no pueden hacerse una RM).", "Radiografías simples de la columna: Para detectar artrosis, pérdida de altura de los discos o cambios en la alineación."] }, treatment: { title: "Tratamientos", intro: "El tratamiento se inicia con opciones conservadoras para controlar el dolor y mantener la función:", subsections: [ { title: "Manejo Médico, Físico y Quirúrgico", items: ["Fisioterapia: El pilar no quirúrgico. Ejercicios específicos para fortalecer la espalda, mejorar el equilibrio y enseñar posturas de flexión lumbar que abren el canal espinal y alivian la presión.", "Medicamentos: AINEs (Ibuprofeno, Naproxeno) para la inflamación, antidepresivos para el dolor nervioso crónico o medicamentos anticonvulsivos (Gabapentina o Pregabalina) para reducir el daño nervioso.", "Inyecciones de esteroides: Las inyecciones epidurales aplican un potente antiinflamatorio directamente alrededor del nervio pellizcado para brindar un alivio prolongado.", "Procedimientos de descompresión mínimamente invasivos (MILD): Se usa en casos lumbares para remover porciones de ligamentos engrosados sin cirugía abierta.", "Cirugía Espinal (Laminectomía o Fusión Espinal): La solución definitiva cuando los síntomas son incapacitantes. El cirujano extirpa parte de la vértebra (la lámina) o los espolones óseos para crear más espacio y 'liberar' los nervios, fijando la columna con tornillos si esta se vuelve inestable."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención médica de neurocirugía o urgencias si:", items: ["Experimentas entumecimiento severo, debilidad o pérdida de sensibilidad que se extiende por tus piernas", "Tienes dificultad repentina para caminar sin tropezar o mantener tu equilibrio", "Pierdes la capacidad para controlar la orina o las heces (Síndrome de cola de caballo, emergencia absoluta)"] } },
'Cataratas congénitas' : { intro: "Las cataratas congénitas son áreas nubladas u opacas en el cristalino del ojo que están presentes desde el nacimiento o se desarrollan durante el primer año de vida del bebé.", whatIs: { title: "¿Qué son las Cataratas Congénitas?", text: "El cristalino es la lente natural del ojo, que normalmente es transparente para permitir que la luz pase hacia la retina. Cuando un bebé nace con cataratas, esta lente es opaca o turbia, impidiendo que el ojo enfoque imágenes claras. Si el cerebro del bebé no recibe una imagen nítida, las conexiones visuales no se desarrollarán, lo que provocará una pérdida de visión profunda, permanente e irreversible (ambliopía o 'ojo vago') si no se opera rápidamente." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los signos a menudo son notados por los padres en las primeras semanas de vida o por el pediatra en el examen del recién nacido:", groups: [ { name: "Signos Visuales y de Comportamiento", items: ["Leucocoria: Una mancha blanca, grisácea o un reflejo blanquecino en la pupila del ojo (que normalmente debería verse negra). A menudo es muy evidente en fotografías con flash (donde falta el reflejo rojo normal).", "Movimientos oculares inusuales, rápidos, rítmicos e incontrolables de lado a lado (nistagmo).", "Estrabismo: Los ojos no parecen mirar en la misma dirección (ojos cruzados o desviados).", "Falta de conciencia visual: El bebé no sigue los objetos en movimiento con la mirada o no fija la atención en el rostro de los padres a los 2-3 meses de edad."] } ], warning: "Una catarata densa y central en un recién nacido es una emergencia oftalmológica. La ventana crítica para operar y permitir que el cerebro aprenda a ver es muy corta (generalmente entre las 4 y 8 semanas de vida)." }, types: { title: "Causas y Factores de Riesgo", intro: "Las cataratas en bebés pueden deberse a múltiples factores ocurridos durante la gestación:", items: ["Factores Genéticos: Es la causa más común (hasta el 50% de los casos bilaterales). Se heredan de uno de los padres (herencia autosómica dominante).", "Infecciones intrauterinas (Síndrome TORCH): Ocurre si la madre se infecta durante el embarazo con rubéola, toxoplasmosis, citomegalovirus, herpes simple o sífilis.", "Trastornos metabólicos: Como la galactosemia, una incapacidad genética para descomponer un tipo de azúcar de la leche, lo que hace que se acumulen toxinas en el cristalino.", "Traumatismos o inflamaciones fetales durante el embarazo.", "A menudo aparecen solas, pero a veces forman parte de un síndrome cromosómico más amplio, como el Síndrome de Down."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico debe ser muy temprano para salvar la vista:", items: ["Examen del reflejo rojo: La prueba estándar que realiza el pediatra en el hospital al nacer y en las primeras revisiones. Utiliza un oftalmoscopio para iluminar el ojo; si el reflejo rojo de la retina está bloqueado o ausente, se deriva de urgencia al especialista.", "Examen oftalmológico pediátrico exhaustivo: El especialista utiliza gotas para dilatar las pupilas y evaluar el tamaño, la ubicación y la densidad de la opacidad en el cristalino.", "Análisis de sangre, pruebas genéticas y de orina: Si no hay antecedentes familiares, el pediatra realizará pruebas para descartar infecciones maternas o enfermedades metabólicas sistémicas subyacentes."] }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere cirugía inmediata y, más importante aún, años de estricta rehabilitación visual:", subsections: [ { title: "Cirugía y Rehabilitación del Ojo", items: ["Cirugía de Extracción de Cataratas: Si la catarata es grande y bloquea el centro visual, debe operarse en las primeras semanas de vida. Bajo anestesia general, el cirujano utiliza herramientas microscópicas para deshacer y aspirar el cristalino opaco del bebé.", "Corrección Óptica Obligatoria: Una vez que se extrae el cristalino natural, el ojo no puede enfocar la luz. El bebé necesitará urgentemente lentes de contacto pediátricos especiales (la opción más común y segura para lactantes), gafas gruesas o, en algunos casos y edades, el cirujano implantará un Lente Intraocular (LIO) artificial de forma permanente.", "Terapia de Oclusión (Uso de Parches): Este es el paso más largo y crítico. Tras la cirugía, el cerebro del niño favorecerá el ojo sano. Para evitar la ceguera permanente (ambliopía), los padres deben tapar el ojo 'bueno' con un parche durante varias horas al día durante años, obligando al cerebro a usar y fortalecer las vías visuales del ojo operado."] } ], note: "Las cataratas congénitas muy pequeñas o que no bloquean el centro de la visión no siempre necesitan cirugía inmediata, pero requieren un monitoreo extremadamente estricto." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a un oftalmólogo pediátrico de urgencia si:", items: ["Ves un punto blanco, una película gris o cualquier falta de oscuridad en la pupila de tu bebé", "Tu hijo no establece contacto visual a los 3 meses de edad, o sus ojos 'bailan' y se mueven bruscamente sin enfocar", "Notas que el reflejo del ojo en las fotografías con flash sale blanco en lugar del típico 'ojo rojo'"] } },
'Próstata agrandada' : { intro: "La próstata agrandada, médicamente denominada Hiperplasia Prostática Benigna (HPB), es un crecimiento excesivo y no canceroso de la glándula prostática. Es una condición extremadamente común que afecta a la mayoría de los hombres a medida que envejecen, causando molestias urinarias significativas.", whatIs: { title: "¿Qué es la Hiperplasia Prostática Benigna?", text: "La próstata es una glándula masculina del tamaño de una nuez que se encuentra justo debajo de la vejiga y envuelve la uretra (el tubo por el que sale la orina). Durante la vida de un hombre, la próstata pasa por periodos de crecimiento. Cuando este crecimiento se vuelve excesivo, la próstata aprieta y 'estrangula' la uretra, bloqueando físicamente el flujo normal de orina. Como la vejiga tiene que hacer mucha fuerza para superar este bloqueo, su músculo se vuelve más grueso, irritado y eventualmente pierde la capacidad de vaciarse por completo. Es fundamental destacar que la HPB NO es cáncer de próstata ni se convierte en cáncer." }, symptoms: { title: "Síntomas y Molestias Urinarias", intro: "Los síntomas del tracto urinario inferior (STUI) empeoran gradualmente con los años:", groups: [ { name: "Síntomas de Vaciado y Almacenamiento", items: ["Necesidad urgente y repentina de orinar, a menudo con dificultad para posponerla", "Aumento extremo de la frecuencia urinaria, especialmente levantándose múltiples veces por la noche para ir al baño (nicturia)", "Dificultad para iniciar el chorro de orina (vacilación), debiendo hacer fuerza con el abdomen", "Chorro de orina débil, lento, que a menudo se detiene y comienza de nuevo de forma intermitente", "Goteo prolongado después de haber terminado de orinar", "Sensación constante de que la vejiga no se ha vaciado por completo después de usar el baño"] } ], warning: "Si la uretra se bloquea por completo, el hombre sufrirá 'Retención Aguda de Orina', caracterizada por un dolor agonizante en la parte baja del abdomen y la incapacidad absoluta de hacer una sola gota de orina. Esto requiere acudir a urgencias de inmediato para colocar una sonda que vacíe la vejiga." }, types: { title: "Complicaciones de la HPB Severa", intro: "Si la vejiga nunca se vacía por completo debido a la próstata, el estancamiento de la orina causa:", items: ["Infecciones crónicas y recurrentes del tracto urinario (IVU)", "Formación de cálculos (piedras) en la vejiga", "Sangrado en la orina (hematuria) debido a la irritación de venas dilatadas", "Daño irreversible a la vejiga (pierde su capacidad de contraerse) y daño renal severo por el retroceso de la orina hacia los riñones."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo evalúa el tamaño de la glándula y el impacto del bloqueo:", items: ["Tacto Rectal (TR): El examen más básico y crucial. El médico inserta un dedo enguantado y lubricado en el recto para palpar el tamaño, la forma y buscar nódulos duros en la próstata.", "Antígeno Prostático Específico (PSA): Análisis de sangre para descartar el cáncer de próstata (el PSA puede estar elevado por la HPB, por infección o por cáncer).", "Análisis de Orina: Para descartar infecciones o rastros de sangre.", "Flujometría y Orina Residual Postmiccional: El paciente orina en un dispositivo que mide la fuerza del chorro, y luego se usa una ecografía en el abdomen bajo para ver cuánta orina quedó atrapada en la vejiga.", "Cistoscopia o Ecografía Transrectal: Si se planea una cirugía, se usa una cámara por el pene o una sonda por el recto para medir el tamaño exacto en gramos de la próstata y visualizar el bloqueo."] }, treatment: { title: "Tratamientos", intro: "El tratamiento va desde pastillas hasta cirugías mínimamente invasivas, dependiendo de cuánto afecten los síntomas a la vida del paciente:", subsections: [ { title: "Manejo Médico (Pastillas)", items: ["Alfa-bloqueadores (Tamsulosina, Alfuzosina, Silodosina): Son la primera línea. Relajan rápidamente los músculos del cuello de la vejiga y de la próstata, haciendo que orinar sea mucho más fácil en cuestión de días.", "Inhibidores de la 5-alfa reductasa (Finasterida, Dutasterida): Actúan sobre las hormonas (bloqueando la DHT) para encoger y reducir el tamaño físico de la próstata agrandada. Tardan hasta 6 meses en hacer efecto completo y se usan en próstatas muy grandes.", "Terapia Combinada y Cialis: A menudo se combinan ambos medicamentos. El Tadalafilo (Cialis) en dosis diaria baja también está aprobado para relajar las vías urinarias además de tratar la disfunción eréctil."] }, { title: "Opciones Quirúrgicas y Procedimientos", items: ["Resección Transuretral de la Próstata (RTUP): El estándar de oro quirúrgico. El cirujano inserta un instrumento por el pene y usa energía eléctrica para 'raspar' y remover por dentro el tejido prostático que bloquea el conducto.", "Terapias Mínimamente Invasivas (UroLift, Rezum): UroLift usa pequeños implantes para 'grapar' o abrir a los lados los lóbulos de la próstata como una cortina. Rezum usa inyecciones de vapor de agua hirviendo para destruir el tejido excedente. Ambas causan muchos menos efectos secundarios sexuales que la RTUP.", "Cirugía Láser (HoLEP, GreenLight): Utiliza un láser de alta potencia para derretir o extirpar el tejido prostático que bloquea la uretra, ideal para próstatas gigantes y pacientes con medicamentos anticoagulantes."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una cita de revisión con urología si tienes molestias urinarias, pero acude a urgencias inmediatamente si:", items: ["No puedes orinar en absoluto y sientes un dolor intenso en la parte baja del abdomen", "Ves sangre roja o coágulos visibles y abundantes en tu orina", "Sufres ardor extremo al orinar, acompañado de fiebre o escalofríos (infección urinaria grave)"] } },
'Infección crónica del oído' : { intro: "La infección crónica del oído, médicamente conocida como Otitis Media Crónica (OMC), es una infección duradera y persistente o recurrente del oído medio. A menudo se caracteriza por la perforación permanente del tímpano y la supuración continua de líquido.", whatIs: { title: "¿Qué es la Infección Crónica del Oído?", text: "Una infección normal del oído (otitis media aguda) es dolorosa, pero sana rápidamente con o sin antibióticos. Sin embargo, cuando la trompa de Eustaquio (el canal de drenaje del oído) falla crónicamente, la infección, la inflamación y el líquido se quedan estancados detrás del tímpano durante meses o años. Esta inflamación perpetua causa que un agujero (perforación) en el tímpano no pueda cerrarse, permitiendo la supuración constante. A largo plazo, las toxinas bacterianas y la inflamación pueden disolver literalmente los diminutos y vitales huesecillos de la audición, causando sordera profunda." }, symptoms: { title: "Síntomas y Alertas", intro: "Irónicamente, el oído crónico suele doler mucho menos que una infección aguda, porque el tímpano roto libera la presión. Sus síntomas son crónicos y molestos:", groups: [ { name: "Síntomas Otológicos a Largo Plazo", items: ["Supuración de oído crónica o recurrente (otorrea): Es el signo principal. Salida de líquido continuo por el canal auditivo, que puede ser aguado, espeso como pus, a veces manchado de sangre y frecuentemente con un olor extremadamente fétido.", "Pérdida de audición notoria y progresiva en el oído enfermo", "Sensación persistente de plenitud, taponamiento o presión en el oído", "Zumbidos en el oído afectados (Tinnitus) y dolor sordo y de baja intensidad"] } ], warning: "Si la infección crónica no se trata y el paciente empieza a sufrir vértigo grave (mareos que dan vueltas), debilidad en un lado de la cara, o dolor e hinchazón severa detrás de la oreja, la infección ha invadido el cráneo (mastoiditis) o los nervios, y es una urgencia vital." }, types: { title: "Complicaciones Mayores (Colesteatoma)", intro: "Una de las peores consecuencias de un oído que no drena bien es el Colesteatoma:", items: ["Colesteatoma: Es un quiste cutáneo destructivo. Debido a la presión negativa en el oído, las células de la piel del tímpano son succionadas hacia adentro, creando un saco o quiste de piel muerta que se infecta crónicamente. No es cáncer, pero actúa como un tumor destructivo que disuelve y erosiona los huesos de la audición, el hueso del cráneo e incluso expone el cerebro a una meningitis si no se extirpa con cirugía compleja."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El otorrinolaringólogo realizará un examen profundo de la estructura del oído:", items: ["Otoscopia bajo microscopio: En la clínica, el médico usa un microscopio y una herramienta de succión para aspirar suavemente el pus del canal y poder ver si hay una perforación en el tímpano, daño en los huesecillos o la masa blanca de un colesteatoma.", "Audiometría (Prueba de audición): Obligatoria para medir con precisión el grado de daño conductivo o nervioso en la audición del paciente.", "Tomografía Computarizada (TC) del Hueso Temporal: Esencial y requerida antes de cualquier cirugía. Proporciona imágenes muy detalladas de las cavidades aéreas del oído y del hueso mastoideo (cráneo) para ver cuán extensa es la infección, el daño a los huesos y planificar el abordaje del bisturí."], note: "" }, treatment: { title: "Tratamientos", intro: "Los antibióticos en pastillas rara vez curan una OMC avanzada. Se requiere limpieza experta y cirugía para detener el daño y cerrar el oído:", subsections: [ { title: "Manejo Médico y Precauciones", items: ["Limpieza microscópica en consulta (Aural Toilet): El otorrino debe aspirar meticulosamente los escombros infectados, costras y pus del oído de forma regular.", "Gotas Óticas Antibióticas (con Fluroroquinolonas y esteroides): Aplicadas directamente en el oído después de limpiarlo, administran una dosis de antibiótico miles de veces superior a la de las pastillas directamente sobre el tejido enfermo, sin efectos secundarios en el resto del cuerpo.", "Precauciones de agua absolutas: El paciente tiene estrictamente prohibido que le entre agua al oído (al ducharse o nadar se deben usar tapones a medida) para evitar que bacterias nuevas entren por el agujero del tímpano."] }, { title: "Opciones Quirúrgicas (Cura Definitiva)", items: ["Timpanoplastia: Cirugía ambulatoria donde el especialista toma un pequeño injerto de tejido (tejido conectivo detrás de la oreja del paciente) y lo usa como un 'parche' permanente para cerrar el agujero del tímpano, sellando el oído medio de las infecciones externas.", "Mastoidectomía y Reconstrucción Osicular: Si la infección está arraigada en los huecos del hueso del cráneo, o si hay un colesteatoma, el cirujano abre el hueso mastoideo (detrás de la oreja) con un taladro quirúrgico para raspar y erradicar toda la enfermedad. En la misma cirugía, puede usar prótesis microscópicas de titanio para reemplazar los huesecillos de la audición disueltos e intentar restaurar el nivel de audición."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca asistencia urgente del otorrinolaringólogo o acude al hospital si:", items: ["Un oído te supura líquido o pus de forma ininterrumpida por más de dos semanas, o la supuración tiene un olor sumamente asqueroso", "Sufres vértigo agudo o parálisis de los músculos faciales de ese lado de la cara", "Sientes un dolor intenso e hinchazón roja, sensible y caliente en el hueso duro que está justo detrás de la oreja (Mastoiditis aguda)"] } },
'Sangrado nasal' : { intro: "Un sangrado nasal, también conocido por el término médico de epistaxis, es la pérdida de sangre que se produce desde el revestimiento interior (mucosa) de la nariz. Aunque ver mucha sangre suele generar pánico, la gran mayoría de los sangrados nasales son eventos menores, inofensivos y muy comunes en niños y adultos.", whatIs: { title: "¿Qué es la Epistaxis?", text: "La nariz tiene un trabajo crucial: calentar y humidificar el aire que respiramos. Para lograr esto, su revestimiento interior tiene una red extremadamente densa de vasos sanguíneos diminutos que están ubicados muy cerca de la superficie, a la intemperie. Esta red vascular es increíblemente frágil; cuando el aire reseca la mucosa o hay un rasguño menor, estos vasos se rompen y sangran copiosamente. Las hemorragias pueden ocurrir en la parte delantera de la nariz (anteriores) o en lo profundo de la parte posterior (posteriores)." }, symptoms: { title: "Síntomas y Clasificación", intro: "El sangrado se divide en dos tipos que determinan su gravedad:", groups: [ { name: "Sangrados Anteriores (Comunes y Leves)", items: ["La sangre fluye hacia afuera desde una de las fosas nasales, típicamente al sentarse o estar de pie", "Representan el 90% de los casos. Ocurren en el tabique inferior delantero (Plexo de Kiesselbach). Suelen detenerse fácilmente con primeros auxilios básicos en casa."] }, { name: "Sangrados Posteriores (Graves e Incontrolables)", items: ["La hemorragia se origina alto y profundo dentro de la nariz. La sangre fluye abundantemente por la parte posterior de la garganta hacia el estómago, incluso si el paciente está sentado erguido.", "El paciente puede atragantarse, toser o vomitar sangre oscura.", "Son mucho más comunes en personas mayores, aquellos con presión arterial alta o problemas de vasos sanguíneos. Frecuentemente requieren intervención en el hospital para detenerlos."] } ], warning: "Tragar mucha sangre causa una severa irritación en el estómago, lo que inevitablemente resultará en náuseas profundas y vómitos de sangre que parecen granos de café, lo cual no debe confundirse con una hemorragia estomacal." }, types: { title: "Causas y Factores de Riesgo", intro: "Las causas abarcan desde el ambiente hasta condiciones sistémicas:", items: ["Aire seco y calefacción en interiores (La causa número uno, reseca y agrieta las costras nasales).", "Traumatismos menores: Hurgarse la nariz con el dedo (muy común en niños), rascarse las costras, o sonarse la nariz con fuerza explosiva.", "Uso diario de medicamentos: Anticoagulantes (Warfarina), antiagregantes (Aspirina diaria, Clopidogrel), o abusar de aerosoles nasales descongestionantes e inhaladores de alergia.", "Condiciones estructurales o infecciosas: Tabique desviado, sinusitis, alergias crónicas, o uso de cocaína por vía nasal.", "Hipertensión arterial (La presión alta rara vez causa el sangrado por sí sola, pero hace que, una vez que el vaso se rompe, sea extremadamente difícil detener el flujo).", "Trastornos raros de coagulación (Enfermedad de Von Willebrand o hemofilia)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico de urgencias o el otorrino buscará el vaso roto mediante:", items: ["Examen Físico: El médico utiliza un espéculo nasal, succión y una fuente de luz fuerte para aspirar los coágulos e identificar el punto exacto de sangrado en el tabique.", "Endoscopia Nasal: Si no se ve la fuente en la parte delantera, el otorrino inserta un tubo de fibra óptica muy delgado para explorar el fondo de la nariz y encontrar el vaso posterior sangrante.", "Análisis de Sangre: Solo se solicitan (conteo de plaquetas y tiempos de coagulación) si el sangrado es masivo, el paciente está en shock, o hay un historial largo de sangrados incontrolables repetitivos."] }, treatment: { title: "Tratamientos", intro: "La mayoría se detienen en casa con técnica adecuada, pero los rebeldes requieren cauterización médica:", subsections: [ { title: "Primeros Auxilios Correctos (En Casa)", items: ["La Postura Clave: Siéntate derecho y siempre INCLINA LA CABEZA HACIA ADELANTE (nunca hacia atrás, ya que tragarás sangre).", "Pinzar correctamente: Usa tu pulgar e índice para apretar o pinzar FUERTEMENTE la parte BLANDA completa de la nariz (las aletas, justo por debajo del hueso duro) contra la cara.", "Mantener la presión: Presiona sin aflojar ni soltar en absoluto durante un mínimo de 10 a 15 minutos cronometrados (respira por la boca). Poner hielo sobre el puente nasal también ayuda a encoger los vasos.", "Descongestionantes: Puedes aplicar 1 o 2 aplicaciones de spray nasal descongestionante (como Oximetazolina) en el algodón antes de pinzar, ya que contrae los vasos rotos al instante."] }, { title: "Tratamientos Médicos (Urgencias y Otorrino)", items: ["Cauterización Química: El médico adormece el interior de la nariz y usa un palito recubierto con Nitrato de Plata para 'quemar' y sellar químicamente el vaso sanguíneo responsable.", "Taponamiento Nasal: Si la cauterización falla, se empaqueta la fosa nasal firmemente con gasas especializadas, esponjas hemostáticas o pequeños balones inflables para ejercer presión mecánica y directa sobre las arterias. Suelen dejarse allí 2 o 3 días.", "Cirugía de Ligadura Endoscópica: En sangrados posteriores incontrolables o pacientes con anticoagulantes severos, el cirujano utiliza cámaras para encontrar la arteria de alimentación y atarla (ligarla) con clips.", "Embolización Arterial: Un radiólogo intervencionista introduce un catéter desde la ingle hasta la cara e inyecta partículas diminutas en la arteria nasal sangrante para bloquearla y sellar el escape permanentemente."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias (911) o acude al hospital sin demora si:", items: ["El sangrado no se detiene después de realizar la presión directa correcta (apretar la nariz inclinándose hacia adelante) por más de 20 minutos seguidos", "El sangrado fue causado por un accidente automovilístico, un golpe fuerte o una fractura en el rostro", "Sientes que la sangre baja a raudales por tu garganta provocándote atragantamiento, debilidad extrema, mareos severos o dificultad para respirar", "Estás tomando anticoagulantes fuertes (como la Warfarina) y sufres una hemorragia nasal"] } },
'Trastorno del control de los impulsos' : { intro: "Los trastornos del control de los impulsos engloban una categoría de trastornos psiquiátricos y de salud mental graves en los cuales una persona es crónicamente incapaz de resistir el impulso, la necesidad repentina, la tentación o el deseo abrumador de realizar una acción que es perjudicial para sí misma o para los demás.", whatIs: { title: "¿Qué son los Trastornos de Control de Impulsos?", text: "El sello distintivo de esta condición es el ciclo neurológico y emocional del acto. La persona experimenta una acumulación de tensión emocional extrema, ansiedad incontrolable y una excitación casi dolorosa antes de cometer el acto. Durante la realización del acto (ya sea robar un objeto inútil o provocar un incendio), el individuo siente una descarga inmediata de alivio, placer, gratificación y calma profunda. Sin embargo, minutos o horas después, esta sensación se desploma y es reemplazada por sentimientos paralizantes de culpa intensa, arrepentimiento, vergüenza, y promesas de 'no volver a hacerlo nunca más', las cuales inevitablemente fracasan cuando la tensión vuelve a acumularse. Es fundamental entender que estas personas no actúan por maldad o interés lógico, sino por un fallo en el 'freno' químico del cerebro." }, symptoms: { title: "Tipos de Trastornos y sus Síntomas Específicos", intro: "Los síntomas están definidos por el tipo de impulso destructivo que la persona no puede detener:", groups: [ { name: "Cleptomanía (Robo Compulsivo)", items: ["Impulso irresistible y recurrente de robar objetos en tiendas o casas de otras personas.", "Los objetos robados NO son necesarios para el uso personal de la persona, ni son robados por su valor monetario (a menudo roban bolígrafos, golosinas baratas o adornos).", "Frecuentemente, el cleptómano tira los objetos a la basura, los regala o los acumula en secreto, sintiendo una culpa y vergüenza devastadoras."] }, { name: "Piromanía (Provocación Compulsiva de Incendios)", items: ["Fascinación, interés intenso, curiosidad o atracción abrumadora y peligrosa por el fuego y su parafernalia.", "Provocación deliberada de incendios para liberar tensión o ansiedad. No se hace por venganza, lucro económico (cobro de seguros), sabotaje político ni bajo la influencia de delirios psicóticos."] }, { name: "Trastorno Explosivo Intermitente (TEI)", items: ["Estallidos y episodios repentinos y repetidos de ira agresiva o violencia física y verbal que son brutalmente desproporcionados a la situación o provocación que los causó.", "Romper objetos, destruir la casa, golpear paredes, agresiones en el tráfico (Road rage) o agresiones domésticas, seguidas de remordimiento inmediato."] } ], warning: "Estos trastornos destruyen la vida social y civil de quien los padece. Frecuentemente derivan en antecedentes penales crónicos, encarcelamiento, despidos laborales constantes, quiebra familiar y riesgo masivo de suicidio debido al peso de la vergüenza secreta." }, types: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de esta incapacidad para 'frenar' es una compleja mezcla biológica y ambiental:", items: ["Desequilibrios Neuroquímicos: Fallos en las vías de recompensa del cerebro y deficiencia funcional de ciertos neurotransmisores. Alteraciones en la dopamina (que impulsa la búsqueda compulsiva del placer) y una baja actividad de la serotonina (la sustancia química que nos da paciencia y control de impulsos).", "Herencia Genética: Existe un alto grado de vulnerabilidad hereditaria. Las personas que tienen familiares de primer grado con trastornos por abuso de sustancias (alcohol, drogas) o trastorno bipolar tienen un riesgo mucho más alto.", "Entorno de Crianza Disfuncional y Trauma: Haber crecido en hogares donde había violencia doméstica severa, abuso físico o sexual, caos constante o castigos impredecibles, lo que daña el desarrollo de la corteza prefrontal del niño (el centro de toma de decisiones y control).", "Efecto Secundario de Medicamentos: Paradójicamente, las medicaciones que aumentan la dopamina, que se usan para tratar la Enfermedad de Parkinson (agonistas de la dopamina), pueden desencadenar trastornos severos de los impulsos, como juego patológico crónico, en pacientes que antes no tenían problemas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una evaluación psiquiátrica clínica muy meticulosa, ya que los pacientes mienten por vergüenza:", items: ["Evaluación Psiquiátrica y Psicológica: El clínico evaluará el historial del patrón de comportamiento y los ciclos de 'tensión, acto, y culpa', a menudo utilizando los estrictos criterios del Manual DSM-5 de la Asociación Estadounidense de Psiquiatría.", "Diagnóstico Diferencial: El paso más crucial. El psiquiatra DEBE descartar que el comportamiento agresivo o de robo no sea causado por el Trastorno Bipolar (fase de manía), Trastorno Antisocial de la Personalidad (psicopatía), abuso de drogas, demencia, Trastorno de Oposición Desafiante en niños, o Tumores en el Lóbulo Frontal del cerebro."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es a largo plazo, complejo, y requiere que la persona admita primero el problema. Combina reestructuración mental y medicación para fortalecer los 'frenos' del cerebro:", subsections: [ { title: "Terapia y Medicación Psiquiátrica", items: ["Terapia Cognitivo-Conductual (TCC): Es la terapia de primera elección. Ayuda y entrena al paciente a reconocer los desencadenantes (pensamientos o lugares) que disparan sus impulsos de robar o enfadarse. Incluye 'Entrenamiento en Reversión de Hábitos' y técnicas de afrontamiento para detenerse, respirar o hacer una acción contraria cuando sienten que el nivel de tensión comienza a subir.", "Antidepresivos (Inhibidores Selectivos de la Recaptación de Serotonina - ISRS): Fármacos potentes como la Fluoxetina (Prozac), Paroxetina o Sertralina se recetan muy comúnmente para aumentar la serotonina en el cerebro, reduciendo obsesiones y aumentando el control químico sobre los impulsos en la cleptomanía y TEI.", "Estabilizadores del Estado de Ánimo y Anticonvulsivos: Medicamentos como el Litio, el Ácido Valproico o la Carbamazepina son vitales y muy efectivos en el Trastorno Explosivo Intermitente para disminuir la agresividad fulminante y estabilizar el humor.", "Terapia Familiar y Grupos de Apoyo: El trabajo con la familia es necesario, así como acudir a grupos basados en los 12 pasos (similares a los de adicciones), los cuales brindan comprensión sin juicio moral, reducen la vergüenza y ayudan al paciente a ser responsable frente a otros."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude urgentemente a un profesional de la psiquiatría o a urgencias médicas si:", items: ["Sientes que tus impulsos violentos son incontrolables y pones en peligro físico inminente la vida de tus familiares, niños o mascotas", "Comienzas a participar en actividades ilegales que sabes que arruinarán tu vida (robar o fuego), pero sientes que es más fuerte que tu voluntad el no hacerlo", "El peso del secreto, las consecuencias de tus actos y la vergüenza posterior te provocan depresión profunda o pensamientos suicidas para acabar con el problema"] } },
'Dolor de columna' : { intro: "El dolor de columna, o dolor de espalda generalizado, es una afección que involucra dolor, pesadez, rigidez o tensión que afecta a cualquier segmento del eje espinal, incluyendo la región del cuello (cervical), la parte media de la espalda conectada a las costillas (dorsal o torácica), o, muy comúnmente, la parte baja (lumbar).", whatIs: { title: "¿Qué es el Dolor de Columna?", text: "La columna vertebral es una obra maestra de la biomecánica, compuesta por 33 huesos superpuestos (vértebras), separados por discos esponjosos que actúan como amortiguadores elásticos, y mantenidos en su lugar por una intrincada red de docenas de ligamentos, articulaciones y músculos posturales. Además, en el centro de esta estructura ósea viaja la delicada médula espinal. El dolor de columna suele ser 'mecánico' o axial, lo que significa que el problema es una sobrecarga de los músculos y articulaciones (como un esguince). Sin embargo, puede ser radicular o 'nervioso' si alguna de las estructuras dañadas, como un disco, se rompe y presiona los nervios eléctricos que salen hacia las piernas o los brazos." }, symptoms: { title: "Síntomas y Clasificación de Zonas", intro: "Los síntomas te dirán claramente si el dolor es muscular, o si un nervio está atrapado y pidiendo auxilio:", groups: [ { name: "Síntomas Musculoesqueléticos (Mecánicos)", items: ["Dolor sordo, pesadez continua y sensación de tensión y 'quemazón' localizada a lo largo de la columna vertebral y los músculos de la espalda", "Espasmos musculares severos (la espalda se 'traba' o se contrae de repente, impidiendo que la persona pueda enderezarse)", "El dolor a menudo empeora drásticamente con ciertas posturas (estar sentado o de pie mucho tiempo, o doblarse para recoger algo del suelo) y mejora o desaparece temporalmente al acostarse en posición horizontal", "Rigidez extrema por las mañanas al intentar levantarse de la cama, que va mejorando a medida que se entra en calor y movimiento"] }, { name: "Síntomas Nerviosos Irradiados (Radiculopatía o Ciática)", items: ["Dolor agudo, eléctrico o con sensación de descarga fulminante que se origina en la columna (cuello o lumbar) y viaja por todo el brazo, el glúteo o la parte posterior de la pierna hasta el pie", "Sensación de entumecimiento, acorchamiento o de tener 'alfileres y agujas' profundamente clavados en las extremidades", "Pérdida de fuerza real (por ejemplo, dificultad para caminar de puntillas, agarrar cosas o levantar la punta del pie, un síntoma llamado pie caído)"] } ], warning: "Llamadas 'Banderas Rojas': El dolor de columna no siempre es benigno. Si aparece acompañado de fiebre inexplicable, pérdida drástica de peso, o es un dolor agudo que despierta a la persona en mitad de la noche y NO se alivia con ninguna postura, es indispensable descartar infecciones espinales severas o tumores metastásicos (cáncer de otros órganos diseminado a los huesos)." }, types: { title: "Causas y Factores de Riesgo Principales", intro: "La inmensa mayoría de los dolores de columna son resultado del impacto de nuestro estilo de vida o del envejecimiento estructural:", items: ["Malas posturas crónicas y sedentarismo: Trabajar horas encorvado frente a ordenadores, dormir en colchones hundidos, y la falta de ejercicio debilita drásticamente los músculos de sostén (el 'core' abdominal y lumbar), sobrecargando los ligamentos.", "Esfuerzos agudos y Traumatismos: Levantar cajas pesadas usando la espalda en lugar de las piernas, movimientos de torsión bruscos que causan esguinces (tirones) de los grandes músculos de la espalda, accidentes de tráfico o caídas graves.", "Enfermedad Degenerativa del Disco y Osteoartritis: Con los años, los discos que amortiguan las vértebras se deshidratan, se secan y se aplastan. El cartílago se desgasta y los huesos rozan, formando picos óseos dolorosos llamados osteofitos (artrosis de columna).", "Hernias de Disco (Discos Abultados o Rotos): El relleno gelatinoso interno de un disco espinal revienta y sale de su pared debido al estrés, aplastando literalmente y quemando con químicos inflamatorios los nervios espinales adyacentes.", "Anomalías Esqueléticas y Óseas: Curvaturas severas en adultos mayores (como la Escoliosis o Cifosis grave), y muy peligrosamente la Osteoporosis, donde los huesos porosos y débiles se fracturan y colapsan sobre sí mismos por el simple peso del cuerpo (fractura por compresión vertebral)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista evaluará si el dolor requiere intervención urgente o simple rehabilitación:", items: ["Evaluación Física y Neurológica: El médico te pedirá caminar de puntillas y de talones, evaluará los reflejos de las rodillas con un martillo, medirá tu capacidad de flexión hacia adelante, y hará la prueba de elevación de la pierna recta para ver si saltan chispas de dolor que confirmen nervios pinzados.", "Radiografías de Columna (Rayos X): Muy útiles en personas mayores o tras un trauma para detectar fracturas, desviación de la columna, o desgaste severo y artritis de las articulaciones de los huesos.", "Resonancia Magnética (RM) de Columna: Es, sin excepción, el estándar de oro. Ninguna otra prueba puede mostrar los tejidos blandos con tanta perfección. Detecta cada hernia de disco, desgarro muscular y mide milimétricamente si los nervios o la médula espinal están siendo estrangulados en el canal espinal.", "Tomografía Computarizada (TC) o Electromiografía (EMG): La TC evalúa las estructuras de los huesos y calcificaciones ocultas, mientras que el EMG mide la transmisión de corriente en los nervios, indicando si un nervio del brazo o pierna está siendo dañado desde la columna."], note: "Curiosamente, el 80% de los dolores de columna no muestran ninguna alteración grave en una resonancia, ya que el dolor es puramente muscular. Al mismo tiempo, muchas personas sanas y sin dolor muestran hernias en las resonancias, por lo que tratar la imagen en lugar de los síntomas del paciente es un gran error médico." }, treatment: { title: "Tratamientos", intro: "Salvo casos de peligro neurológico, el enfoque moderno exige movimiento y rehabilita activamente, desechando por completo las recomendaciones antiguas de pasar semanas en cama, lo cual destruye la espalda:", subsections: [ { title: "Manejo Conservador, Terapias Físicas e Intervenciones Médicas", items: ["Autocuidado Activo y Físico: Usar bolsas de hielo envueltas en toallas las primeras 48 horas de un tirón para bajar la inflamación brutal, y posteriormente almohadillas de calor húmedo para relajar y soltar el espasmo de los músculos paralizados. Tratar de mantener la rutina de caminatas a pesar del dolor leve.", "Fisioterapia y Reeducación Muscular: El pilar central de toda la medicina de columna. Fisioterapeutas diseñan programas de estiramiento progresivo y, crucialmente, ejercicios intensivos para crear un corsé de acero natural fortaleciendo los músculos abdominales y extensores lumbares. Pilates, yoga terapéutico y natación son altamente beneficiosos.", "Medicación de Soporte: Para que el paciente pueda soportar la rehabilitación física, se prescriben AINEs (Ibuprofeno, Naproxeno o Celecoxib) en cursos cortos, analgésicos más fuertes (como Tramadol) o relajantes musculares estrictamente por las noches para cortar el ciclo de 'espasmo-dolor'. En dolor neuropático ardiente por ciática, los antidepresivos (Amitriptilina) o anticonvulsivos (Pregabalina) ayudan a modular el dolor.", "Infiltraciones y Bloqueos de Dolor Espinal: Bajo control y guía de una máquina de Rayos X (Fluoroscopia) en quirófano, un especialista en dolor clava una aguja larga e inyecta una mezcla de anestésicos locales y corticosteroides extremadamente potentes directamente en el espacio epidural de la columna, bañando el nervio irritado o las articulaciones con inflamatorio para lograr alivios de meses."] }, { title: "Enfoques Quirúrgicos (Última Instancia)", items: ["Cirugía de Columna Mayor (Descompresión, Discectomía o Artrodesis/Fusión): Menos del 5% de los pacientes de columna llegan a este extremo. El neurocirujano o cirujano ortopédico opera únicamente si el dolor de ciática no responde tras meses de infiltraciones o terapias, o si existe una debilidad muscular y atrofia paralizante progresiva confirmada. Implica raspar hueso, quitar la parte reventada del disco, y a veces colocar grandes tornillos de titanio y varillas para dejar inmovilizadas y fusionadas permanentemente dos vértebras inestables."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Dirígete inmediatamente al servicio de traumatología de urgencias o neurocirugía si presentas alguna de las siguientes Banderas Rojas críticas:", items: ["El dolor ocurrió repentinamente después de haber sufrido un accidente severo, un impacto a alta velocidad o tras una caída importante de altura (potencial fractura inestable de columna)", "Comienzas a perder o te resulta imposible el control voluntario de tus esfínteres (no puedes contener la orina o te haces caca encima sin darte cuenta), o toda la zona de la ingle y los genitales ('silla de montar') está dormida y anestesiada (Síndrome de la Cola de Caballo, compresión terminal que puede ser permanente sin cirugía horas después)", "Observas que desarrollas una 'debilidad' o cojera obvia y nueva en las piernas, arrastrando la punta de tu zapato al caminar porque no tienes fuerza en los pies", "El dolor agudo viene acompañado de fiebre intensa que no tiene explicación, o tienes antecedentes previos de sufrir cáncer"] } },
'Dolor de espalda' : { intro: "El dolor de espalda es una de las razones más comunes por las que las personas acuden al médico o faltan al trabajo, y es una causa principal de discapacidad en todo el mundo.", whatIs: { title: "¿Qué es el Dolor de Espalda?", text: "Es una afección que puede variar desde un dolor muscular sordo, constante y molesto, hasta una sensación punzante aguda y repentina. Puede ser agudo (dura unas pocas semanas) o crónico (dura más de tres meses), y a menudo se debe a problemas mecánicos en la estructura de la columna vertebral, como músculos, ligamentos o discos intervertebrales." }, symptoms: { title: "Síntomas Comunes", intro: "El dolor de espalda puede tener muchas características dependiendo de la causa:", groups: [ { name: "Signos Físicos y Neurológicos", items: ["Dolor muscular sordo, pesadez o rigidez en la zona lumbar, media o cervical", "Dolor punzante o cortante que se irradia hacia los glúteos y baja por la parte posterior de la pierna (ciática)", "Dolor que empeora drásticamente al inclinarse, levantar peso, estar de pie o caminar", "Dolor que mejora temporalmente al reclinarse o acostarse", "Espasmos musculares severos que limitan por completo la movilidad del torso"] } ], warning: "Si el dolor de espalda aparece tras una caída grave, o se acompaña de pérdida de peso inexplicable, fiebre nocturna, o pérdida de control de los intestinos o la vejiga, es una emergencia médica que indica un posible daño nervioso severo, infección o tumor." }, causes: { title: "Causas y Factores de Riesgo", intro: "La mayoría de los dolores de espalda agudos son mecánicos, impulsados por:", items: ["Distensión muscular o de ligamentos por levantamiento pesado repetido o un movimiento brusco y torpe", "Abultamiento, hernia o rotura de discos intervertebrales (el material blando dentro del disco presiona un nervio)", "Osteoartritis que afecta las articulaciones de la columna vertebral (estenosis espinal)", "Osteoporosis (los huesos vertebrales se vuelven porosos y frágiles, sufriendo microfracturas por compresión)", "Anomalías esqueléticas (como la escoliosis severa en la edad adulta)", "Factores de estilo de vida: Sedentarismo, obesidad (exceso de carga en la columna), tabaquismo (reduce el flujo sanguíneo a los discos) y estrés o depresión crónicos."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico examinará tu espalda, postura y evaluará tu capacidad para sentarte, pararte, caminar y levantar las piernas:", items: ["Radiografías (Rayos X): Muestran la alineación de los huesos y detectan signos de artritis, desgaste o fracturas.", "Resonancia Magnética (RM) o Tomografía Computarizada (TC): Las mejores pruebas para revelar hernias de disco, problemas en los músculos, tendones, nervios y vasos sanguíneos.", "Análisis de sangre: Para descartar infecciones ocultas o problemas inflamatorios sistémicos.", "Electromiografía (EMG): Mide los impulsos eléctricos de los nervios y confirma la compresión nerviosa causada por hernias o estenosis espinal."], note: "Es común que las imágenes muestren hernias o desgaste natural en personas que NO tienen ningún dolor; por eso, las imágenes siempre deben correlacionarse con el examen físico." }, treatment: { title: "Tratamientos", intro: "La mayoría de los dolores de espalda agudos mejoran radicalmente en un mes con tratamiento conservador en el hogar:", subsections: [ { title: "Opciones Médicas, Terapias y Quirúrgicas", items: ["Autocuidado: Mantenerse activo en la medida de lo posible (el reposo en cama prolongado atrofia los músculos y empeora el dolor), usar compresas frías las primeras 48 horas y luego calor húmedo.", "Medicamentos: Analgésicos de venta libre (Ibuprofeno, Naproxeno) y, para dolores muy intensos a corto plazo, relajantes musculares recetados.", "Fisioterapia: El tratamiento no quirúrgico más efectivo a largo plazo. Consiste en ejercicios guiados para aumentar la flexibilidad, fortalecer masivamente los músculos del core y la espalda, y reeducar la postura.", "Infiltraciones epidurales de cortisona: Inyecciones de antiinflamatorios potentes en el espacio alrededor de la médula espinal para disminuir la inflamación grave en las raíces nerviosas (alivio de meses).", "Cirugía (Laminectomía, Discectomía o Fusión): Se reserva estrictamente para el dolor estructural crónico que no responde tras meses de terapias, y que causa debilidad muscular progresiva en las piernas o compresión nerviosa confirmada incapacitante."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a emergencias o a un especialista en columna si tu dolor de espalda:", items: ["Aparece inmediatamente después de un accidente de tráfico, una caída, o un golpe en la espalda", "Causa nuevos y repentinos problemas para orinar o defecar (incontinencia)", "Está acompañado de fiebre alta, enrojecimiento o hinchazón en la espalda", "Causa debilidad progresiva, entumecimiento o un hormigueo pesado en una o ambas piernas que llega hasta la rodilla o el pie"] } },
'Absceso mamario' : { intro: "Un absceso mamario es una acumulación dolorosa y localizada de pus que se forma en el tejido del seno debajo de la piel, casi siempre como resultado de una infección bacteriana aguda no tratada.", whatIs: { title: "¿Qué es un Absceso Mamario?", text: "Es una complicación infecciosa. Ocurre con mayor frecuencia en mujeres en etapa de lactancia (mastitis lactacional) debido a conductos galactóforos estancados u obstruidos, o por grietas en el pezón que permiten a las bacterias de la piel o de la boca del bebé entrar en el tejido profundo del seno. El cuerpo responde enviando glóbulos blancos para combatir la bacteria, y el resultado de esta batalla celular forma una bolsa de pus y tejido muerto (absceso). Sin embargo, también puede afectar a mujeres que no amamantan y, en raras ocasiones, a hombres, a menudo asociado al tabaquismo." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los síntomas suelen aparecer rápidamente y ser intensos tras un episodio previo de dolor y enrojecimiento (mastitis):", groups: [ { name: "Síntomas Locales en el Seno", items: ["Aparición de un bulto claramente palpable, fluctuante (blando), extremadamente doloroso y caliente al tacto", "Enrojecimiento intenso y brillante de la piel sobre la zona afectada del pecho", "Hinchazón severa y endurecimiento (induración) de una zona específica de la mama", "Supuración de pus amarillo o verde a través del pezón o a través de la piel debilitada", "Piel muy tensa, brillante o que parece a punto de romperse sobre el bulto"] }, { name: "Síntomas Sistémicos de Infección", items: ["Fiebre moderada a alta y escalofríos repentinos", "Fatiga extrema, dolores musculares y malestar general (síntomas similares a una gripe fuerte)"] } ], warning: "Si estás amamantando y notas una zona roja, dura y dolorida en el pecho acompañada de fiebre, debes buscar tratamiento antibiótico para la mastitis inmediatamente para evitar que evolucione y se enquiste en un absceso." }, types: { title: "Causas y Factores de Riesgo", intro: "La infección suele ser bacteriana (frecuentemente *Staphylococcus aureus*). Los factores desencadenantes incluyen:", items: ["Mastitis no tratada durante la lactancia (la causa abrumadora y principal)", "Grietas, fisuras, mordeduras o heridas superficiales en los pezones que sirven como puerta de entrada a patógenos", "Tabaquismo crónico: Fuertemente asociado a abscesos subareolares recurrentes en mujeres no lactantes, debido a que el tabaco daña y deforma permanentemente los conductos galactóforos detrás del pezón (ectasia ductal).", "Condiciones de salud como diabetes mal controlada, obesidad, o tener un sistema inmunológico debilitado", "Traumatismos recientes en el pecho o complicaciones tras un piercing en el pezón"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico médico combina la palpación física con imagenología para ver el interior del seno:", items: ["Examen físico clínico: El ginecólogo o cirujano palpará el bulto para comprobar si es fluctuante (líquido) o sólido.", "Ecografía mamaria: Es la prueba de elección, rápida y sin radiación. Diferencia claramente una bolsa de líquido infectado (absceso que debe drenarse) de una zona de tejido inflamado sólido (mastitis pura que solo requiere antibióticos).", "Aspiración con aguja: El médico puede introducir una aguja en la zona y extraer una pequeña cantidad de líquido. Si sale pus, confirma el absceso; además, el líquido se envía a cultivo para saber exactamente qué bacteria lo causa y ajustar el antibiótico."], note: "En mujeres que no amamantan y especialmente en las mayores, si la ecografía es sospechosa, se puede realizar una biopsia una vez curada la infección para asegurar que el bulto no oculta un tipo de cáncer de mama inflamatorio." }, treatment: { title: "Tratamientos", intro: "Un absceso diagnosticado nunca se curará solo con antibióticos, la bolsa de pus gruesa debe ser vaciada mecánicamente:", subsections: [ { title: "Procedimientos de Drenaje y Manejo Médico", items: ["Aspiración con aguja fina guiada por ecografía: Para abscesos pequeños (menos de 3-5 cm) o en pacientes lactantes. El radiólogo o cirujano adormece la piel y usa una jeringa guiada por ultrasonido para extraer todo el pus. Es el método preferido porque no requiere cortes ni deja cicatriz grande, aunque suele requerir repetirse en visitas consecutivas durante varios días hasta que deje de rellenarse.", "Incisión y drenaje quirúrgico (I&D): Si el absceso es muy grande, profundo, crónico o no mejora con las punciones de aguja, el cirujano realiza un pequeño corte con bisturí (bajo anestesia local o general breve) para vaciar completamente la cavidad, romper tabiques internos de pus y, a menudo, deja una pequeña mecha o tubo de drenaje de goma unos días para asegurar que drene todo.", "Antibióticos: Obligatorios (como Dicloxacilina o Cefalexina) para combatir la infección circundante en el tejido (celulitis).", "Manejo de la lactancia: Si se extrae por aguja o la incisión está lejos de la areola, a menudo se fomenta fuertemente a la madre a seguir amamantando o a extraerse leche de ese lado, ya que vaciar la leche regularmente ayuda a limpiar los conductos y acelera la curación (la leche infectada no daña el estómago ácido del bebé sano)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un médico, ginecólogo o a urgencias de maternidad inmediatamente si:", items: ["Sientes un bulto rojo, muy localizado, doloroso y caliente en el pecho que no mejora tras 24 horas de masajes, vaciado de leche o aplicar calor", "Desarrollas fiebre alta y escalofríos intensos junto con dolor en la mama", "La piel de tu pecho se ve excepcionalmente tensa, brillante, o comienza a supurar un líquido oscuro o amarillento"] } },
'Trastorno del desarrollo del lenguaje expresivo' : { intro: "El trastorno del desarrollo del lenguaje expresivo es una afección neurológica del desarrollo infantil en la cual un niño tiene una capacidad significativamente por debajo de lo esperado para su edad para utilizar el lenguaje hablado y comunicarse, a pesar de poseer una inteligencia normal y una comprensión adecuada del lenguaje de los demás.", whatIs: { title: "¿Qué es el Trastorno del Lenguaje Expresivo?", text: "A diferencia de un trastorno del lenguaje receptivo (donde el niño tiene problemas profundos para entender lo que las personas le dicen), en el trastorno exclusivamente expresivo el niño comprende perfectamente su entorno, obedece instrucciones complejas y entiende conceptos, pero su cerebro tiene enormes dificultades para 'recuperar' las palabras correctas de su memoria, organizarlas gramaticalmente y estructurar oraciones para expresar verbalmente sus pensamientos, ideas o necesidades. A menudo se sienten como si tuvieran las palabras 'en la punta de la lengua' pero no pueden emitirlas." }, symptoms: { title: "Síntomas y Retrasos Notorios", intro: "Los signos de alarma se hacen evidentes cuando el niño comienza a hablar o intenta formar frases:", groups: [ { name: "Indicadores Lingüísticos y Verbales", items: ["Vocabulario expresivo extremadamente limitado y pobre en comparación con otros niños de su edad", "Dificultad evidente para aprender palabras nuevas y problemas crónicos para recordar y nombrar objetos cotidianos (anomia)", "Uso constante de palabras inespecíficas de relleno (como 'eso', 'aquello', 'la cosa esa') en lugar del nombre real de los objetos", "Estructura oracional muy por debajo de su edad: Uso de oraciones extremadamente cortas, fragmentadas, simplificadas o desordenadas", "Omisión frecuente de palabras clave en las oraciones (como preposiciones, artículos, o verbos conectores)", "Gran dificultad para contar una historia lineal, relatar un evento que les ocurrió en el colegio o mantener una conversación fluida", "Errores gramaticales crónicos que los niños de su edad ya dominan (por ejemplo, fallar constantemente en conjugar verbos en pasado o plurales)"] } ], warning: "Es crucial no confundir este trastorno neurológico con un niño que es simplemente un 'hablante tardío' o que es tímido. Si un niño no está juntando dos palabras con sentido a los 2 años, o su habla es incomprensible, requiere una evaluación del desarrollo inmediata para aprovechar la ventana de máxima plasticidad cerebral." }, types: { title: "Causas y Factores de Riesgo", intro: "A menudo no se identifica una causa médica única o un daño orgánico visible, pero las raíces están en el desarrollo cerebral:", items: ["Factores Genéticos: Fuerte heredabilidad. Es muy común encontrar antecedentes familiares directos de padres o hermanos que tuvieron problemas de lenguaje, lectura o aprendizaje escolar.", "Desarrollo Neurológico: Anomalías sutiles en las redes cerebrales responsables del procesamiento verbal y la memoria de trabajo fonológica (sin que existan lesiones, tumores o daños evidentes).", "Condiciones Preexistentes: Los niños nacidos muy prematuramente o con bajo peso al nacer tienen mayores tasas de desarrollo de este trastorno.", "Comorbilidades: Frecuentemente coexiste, precede o anuncia problemas futuros como dislexia, Trastorno por Déficit de Atención e Hiperactividad (TDAH), o dificultades generales de aprendizaje académico."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico formal es realizado por un equipo multidisciplinario pediátrico:", items: ["Evaluación Audiológica (Prueba de Audición): Es SIEMPRE el primer paso y obligatorio. Se debe descartar que el niño hable mal simplemente porque sufre de pérdida auditiva (por ejemplo, líquido crónico en los oídos tras múltiples otitis).", "Evaluación del Patólogo del Habla y el Lenguaje (Logopeda): Es la prueba central. El especialista utiliza pruebas, herramientas lúdicas y juegos estandarizados para evaluar rigurosamente el vocabulario expresivo del niño, sus habilidades gramaticales y narrativas, y contrastarlas con sus excelentes habilidades de comprensión (receptivas).", "Evaluación Psicológica o Neuropsicológica: Para descartar Discapacidad Intelectual generalizada, Trastorno del Espectro Autista (TEA) u otros retrasos del desarrollo global."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere una intervención educativa, no médica, y la participación activa e intensiva de la familia:", subsections: [ { title: "Intervención Temprana y Terapias", items: ["Terapia del Habla y el Lenguaje (Logopedia): Es el pilar absoluto del tratamiento. El terapeuta trabaja individualmente con el niño mediante juegos estructurados, repetición de patrones, modelado de frases y ejercicios de enriquecimiento de vocabulario para enseñarle a organizar y recuperar palabras. A los niños mayores se les enseñan estrategias de compensación (como dar definiciones cuando olvidan una palabra exacta).", "Entrenamiento e Intervención Familiar: Los terapeutas capacitan a los padres para que estimulen el lenguaje en casa constantemente. Técnicas como: no interrumpir al niño, darle mucho tiempo para responder, expandir sus frases (si el niño dice 'coche azul', el padre responde 'sí, es un coche azul grande y rápido'), y narrar las acciones de la rutina diaria.", "Apoyo y Adaptaciones Escolares (IEP): En el colegio, el niño necesita un Plan de Educación Individualizado. Esto puede incluir tiempo adicional para pruebas o hablar, asignaciones visuales, evitar la presión extrema de leer o responder en público sin aviso, y asistencia especializada continua para la lectura y escritura."] } ], note: "Cuanto antes comience la terapia del lenguaje (incluso desde los 2 o 3 años), mejores serán las perspectivas académicas a largo plazo, ya que el lenguaje expresivo es la base para aprender a leer y escribir." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un pediatra de inmediato para obtener una derivación a logopedia si:", items: ["Tu hijo no balbucea a los 12 meses, no señala ni usa gestos (como decir adiós con la mano) a los 14 meses, no usa palabras simples a los 18 meses, o no junta dos palabras con sentido a los 2 años", "Notas que el niño se frustra de forma extrema, hace rabietas constantes, se golpea o se aísla socialmente de otros niños precisamente porque no puede hacerse entender", "Sientes que el vocabulario de tu hijo es inusualmente pobre para su edad, aunque parezca entender todo lo que le pides y realiza las tareas que le ordenas"] } },
'Ovario poliquístico' : { intro: "El ovario poliquístico, a menudo como manifestación principal del Síndrome de Ovario Poliquístico (SOP), es un trastorno endocrino, metabólico y reproductivo muy común. Se caracteriza por un desequilibrio de las hormonas reproductivas que provoca problemas en los ovarios, impidiendo la ovulación normal y causando síntomas en todo el cuerpo femenino.", whatIs: { title: "¿Qué es el Síndrome de Ovario Poliquístico?", text: "A pesar de su nombre, las mujeres con este síndrome no tienen 'quistes' enfermos o tumores en los ovarios que requieran ser operados. En un ciclo menstrual normal, un folículo (un pequeño saco de líquido) crece en el ovario, madura un óvulo y lo libera (ovulación). En el ovario poliquístico, debido a alteraciones hormonales (principalmente niveles inusualmente altos de andrógenos u hormonas masculinas, y resistencia a la insulina), estos folículos comienzan a crecer pero se estancan y nunca maduran lo suficiente para liberar el óvulo. Al no ovular, estos folículos inmaduros se van acumulando en los bordes del ovario mes a mes, dándole al ovario un aspecto agrandado y lleno de pequeñas 'perlas' o múltiples quistecitos al verlo en una ecografía. Como la ovulación se detiene, también lo hace el ciclo menstrual normal." }, symptoms: { title: "Síntomas y Características Visibles", intro: "Los síntomas suelen presentarse por primera vez en la pubertad y empeoran fuertemente con el aumento de peso:", groups: [ { name: "Irregularidades Reproductivas", items: ["Ciclos menstruales muy irregulares y erráticos, tener muy pocos periodos al año (oligomenorrea) o la ausencia total de la menstruación (amenorrea) durante meses", "Sangrados uterinos disfuncionales: cuando la menstruación finalmente ocurre, puede ser anormalmente abundante y prolongada", "Infertilidad o grandes dificultades para concebir un hijo debido a la falta de ovulación (es una de las principales causas de infertilidad femenina)"] }, { name: "Signos por Exceso de Andrógenos (Hormonas Masculinas)", items: ["Hirsutismo: Crecimiento excesivo, grueso y oscuro de vello en áreas inusuales para las mujeres, como el labio superior, la barbilla, el cuello, el pecho, el abdomen o la espalda", "Acné adulto severo, quístico o persistente, especialmente a lo largo de la línea de la mandíbula y el cuello, y piel muy grasa", "Pérdida de cabello, afinamiento severo o calvicie con patrón masculino en la parte superior de la cabeza (alopecia androgénica)"] }, { name: "Problemas Metabólicos Asociados", items: ["Aumento de peso incontrolable y dificultad extrema para adelgazar, con acumulación de grasa específicamente en el abdomen", "Acantosis nigricans: Zonas de piel oscurecida, gruesa y de aspecto aterciopelado en los pliegues del cuello, las ingles o debajo de los senos (es un signo directo de que el cuerpo tiene demasiada insulina)"] } ], warning: "El SOP no es solo un problema de fertilidad o cosmético. La inflamación crónica y la resistencia a la insulina subyacentes aumentan drásticamente el riesgo de desarrollar Diabetes Tipo 2, Presión Arterial Alta, Apnea del Sueño severa y, a largo plazo, Cáncer de Endometrio (debido a la acumulación de revestimiento uterino por la falta de menstruación)." }, types: { title: "Causas y Factores Desencadenantes", intro: "El SOP es el resultado de un entorno metabólico y genético complejo:", items: ["Resistencia a la Insulina: Es el motor principal del síndrome. Las células del cuerpo se vuelven 'sordas' a la insulina. El páncreas debe producir cantidades masivas de insulina para compensar. Este exceso de insulina tóxica en la sangre viaja a los ovarios y los sobrestimula, obligándolos a detener la ovulación y a fabricar testosterona y otros andrógenos en grandes cantidades.", "Desequilibrio Hormonal Hipofisario: Alteración en las hormonas luteinizante (LH) y foliculoestimulante (FSH) del cerebro, lo que interfiere con el ritmo del ciclo ovárico.", "Inflamación Crónica de Bajo Grado: Se ha demostrado que las mujeres con SOP tienen niveles altos de inflamación generalizada en su cuerpo, lo que incita a los ovarios a producir andrógenos.", "Factores Genéticos: Si tu madre o hermana tiene SOP, tus probabilidades de padecerlo son exponencialmente más altas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existe una sola prueba definitiva. El ginecólogo y el endocrinólogo diagnostican el SOP utilizando los 'Criterios de Rotterdam', donde se deben cumplir al menos dos de las siguientes tres condiciones:", items: ["1. Ovulación irregular: Ciclos menstruales impredecibles, escasos o ausentes.", "2. Hiperandrogenismo: Signos físicos (exceso de vello severo, acné) o análisis de sangre que confirmen niveles elevados de hormonas masculinas libres (como testosterona).", "3. Ovarios de aspecto poliquístico en ecografía: Una ecografía pélvica transvaginal que muestre ovarios agrandados que contienen 12 o más folículos diminutos agrupados como un 'collar de perlas' en la periferia."], note: "El médico también debe ordenar análisis de sangre exhaustivos (curva de glucosa, insulina, perfil de colesterol, hormonas tiroideas y prolactina) para descartar otros problemas hormonales que imitan al SOP y evaluar el riesgo inminente de diabetes." }, treatment: { title: "Tratamientos", intro: "El SOP no tiene una cura definitiva, pero sus síntomas y riesgos se pueden controlar con gran éxito combinando potentes cambios de estilo de vida con medicamentos específicos (dependiendo de si el objetivo de la paciente es controlar los síntomas, o quedar embarazada):", subsections: [ { title: "Manejo Metabólico (El Pilar del Tratamiento)", items: ["Pérdida de Peso y Dieta: Es el tratamiento número uno, el más poderoso y fundamental. Perder tan solo entre el 5% y el 10% del peso corporal reduce drásticamente los niveles de insulina y andrógenos, y a menudo es suficiente para que la ovulación y la menstruación regresen a la normalidad de forma natural. La dieta debe ser estricta: baja en carbohidratos refinados, azúcares y con índice glucémico bajo.", "Ejercicio Regular: Vital para sensibilizar los músculos a la insulina y quemar el azúcar en la sangre, combatiendo la resistencia a la insulina frontalmente."] }, { title: "Terapias Farmacológicas", items: ["Para regular el ciclo y los síntomas físicos: Anticonceptivos Hormonales Combinados (píldoras de estrógeno y progestina). Son la base del tratamiento para mujeres que no buscan embarazo. Restauran el sangrado mensual (protegiendo contra el cáncer de endometrio), suprimen la producción de testosterona, detienen el crecimiento de nuevo vello facial y limpian agresivamente el acné.", "Para la Resistencia a la Insulina: Metformina. Un medicamento clásico para la diabetes que baja los niveles de insulina en el cuerpo, lo que indirectamente baja los andrógenos, ayuda a perder peso y puede reiniciar la ovulación natural.", "Para el exceso de vello (Hirsutismo): Medicamentos Antiandrógenos (como la Espironolactona), que bloquean poderosamente los efectos de la testosterona en la piel y los folículos pilosos (deben tomarse junto con anticonceptivos debido a riesgos de defectos de nacimiento si hay embarazo). Cremas tópicas (Eflornitina) o depilación láser.", "Para tratar la Infertilidad: Si la mujer desea quedar embarazada, los anticonceptivos se suspenden y se recetan inductores de la ovulación orales (Letrozol es actualmente la primera opción, o Clomifeno). Si estos fallan, se recurre a inyecciones de gonadotropinas o a la Fecundación In Vitro (FIV)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una cita con tu ginecólogo o endocrinólogo sin dudarlo si:", items: ["Tus periodos menstruales han desaparecido durante varios meses, o tienes sangrados erráticos con más de 35 días de separación constante entre ciclos", "Notas un crecimiento inusual, rápido y oscuro de vello en tu rostro, barbilla, pecho o abdomen, acompañado de acné persistente en la edad adulta", "Llevas más de 12 meses (o 6 meses si eres mayor de 35 años) manteniendo relaciones sexuales sin protección buscando un embarazo, sin lograrlo"] } },
'Condromalacia rotuliana' : { intro: "La condromalacia rotuliana (a menudo llamada erróneamente síndrome de dolor patelofemoral o 'rodilla del corredor') es una afección degenerativa que describe el ablandamiento, el desgaste y la rotura física del cartílago articular liso que recubre la parte inferior o posterior de la rótula.", whatIs: { title: "¿Qué es la Condromalacia Rotuliana?", text: "La rótula es el pequeño hueso redondo en la parte delantera de la rodilla. Su parte posterior está recubierta de un cartílago extremadamente duro y pulido que funciona como el teflón, permitiendo que la rótula se deslice suavemente, sin fricción y sin dolor, sobre un surco en el hueso del muslo (fémur) cuando doblas y estiras la pierna. En la condromalacia, debido a años de fricción anormal, este 'teflón' protector se deshilacha, se ablanda (como una esponja mojada), se agrieta y, en etapas avanzadas, se desgasta por completo dejando el hueso expuesto. Esta pérdida de superficie lisa genera un roce áspero, inflamación crónica severa y un dolor mecánico y punzante muy limitante, siendo muy frecuente en adultos jóvenes, mujeres, deportistas y personas mayores." }, symptoms: { title: "Síntomas y Señales Mecánicas", intro: "El dolor está íntima y mecánicamente relacionado con el aumento de la presión y la flexión sobre la rótula:", groups: [ { name: "Síntomas Clínicos del Roce", items: ["Dolor sordo, punzante o quemante profundo en la parte delantera de la rodilla, exactamente debajo, detrás o alrededor de los bordes de la rótula", "El dolor empeora agresivamente al realizar actividades que aplastan la rótula contra el fémur, especialmente: bajar escaleras, correr cuesta abajo, hacer sentadillas (squats) profundas, arrodillarse o hacer zancadas", "Signo del 'Cine' o la 'Butaca': Dolor agudo, presión y rigidez intensa en la rodilla al intentar levantarse o estirar la pierna después de haber estado sentado con las rodillas dobladas durante mucho tiempo (viajes en avión, el cine, o trabajar en un escritorio)", "Crepitación notable: Sensación física de crujido, chasquidos ásperos o un ruido de 'rechinamiento' casi como pisar grava (arenilla) dentro de la rodilla al doblarla y estirarla", "Hinchazón leve e intermitente alrededor de los bordes de la rótula tras realizar ejercicio, y sensación eventual de que la rodilla 'cede' o pierde fuerza"] } ], warning: "Ignorar repetidamente este dolor y seguir realizando deportes de alto impacto, saltos o sentadillas profundas sin rehabilitar los músculos, acelerará la destrucción física del cartílago restante. Una vez que el cartílago se desgasta hasta el hueso, la condición se convierte en artrosis rotuliana prematura, un daño articular que es permanente y doloroso de por vida." }, types: { title: "Causas y Factores Desencadenantes", intro: "La destrucción del cartílago es un problema puro de física biomecánica; la rótula no viaja centrada por su riel y choca contra los bordes:", items: ["Mala alineación rotuliana (Mal tracking): Es la causa número uno. Debido a desequilibrios de fuerza en las piernas, la rótula se tira o se desvía crónicamente hacia la parte exterior (lateral) del surco del fémur, rozando el hueso continuamente como un tren descarrilado.", "Desequilibrio Muscular Crónico: Tener un músculo cuádriceps débil (específicamente la parte interior, el vasto medial, que sostiene la rótula en su sitio) y tener excesiva rigidez, acortamiento o tensión en la banda iliotibial (ITB), los músculos isquiotibiales o las pantorrillas.", "Anatomía Genética: Personas con pies planos extremos (exceso de pronación al pisar, que hace que la rodilla se tuerza hacia adentro), rodillas valgas (en forma de 'X'), o personas que nacen con una rótula inusualmente alta (patela alta) o un surco del fémur demasiado plano (displasia troclear).", "Sobrecarga repetitiva deportiva: Aumentar súbitamente la intensidad, kilómetros o peso en los entrenamientos, especialmente en corredores, ciclistas, gimnastas y jugadores de baloncesto.", "Trauma directo agudo: Un golpe fuerte directamente sobre la rótula (caída fuerte de rodillas al suelo) que fractura o daña microscópicamente el cartílago blando."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista evaluará la biomecánica de tu pierna y visualizará el daño interior:", items: ["Examen físico clínico: El traumatólogo, médico deportivo o fisioterapeuta evaluará cómo te agachas, presionará directamente la rótula contra el fémur pidiendo que contraigas el muslo (Prueba de cepillo o Zohlen) para confirmar la crepitación y el dolor local, y evaluará el ángulo y la fuerza de tu cuádriceps y cadera.", "Radiografías (Rayos X) en proyección axial o 'Skyline': Muestran desde arriba si la rótula está descentrada (subluxada), chocando contra un borde del fémur, o si ya hay espolones de hueso artrítico.", "Resonancia Magnética (RM): Es la prueba de oro y la única que permite al médico VER físicamente la textura, las grietas, las fisuras profundas y el adelgazamiento del cartílago blando. Con la RM, la condromalacia se clasifica en 4 grados de severidad (del Grado 1: ablandamiento leve, al Grado 4: pérdida total del cartílago con hueso expuesto)."], note: "" }, treatment: { title: "Tratamientos", intro: "A menos que el daño cartilaginoso sea total (Grado 4 avanzado), la inmensa mayoría de las condromalacias mejoran espectacularmente sin entrar a quirófano, gracias a la reeducación biomecánica estricta de la pierna:", subsections: [ { title: "Fase Aguda (Control del Dolor)", items: ["Protocolo de Modificación y Reposo: El primer paso es de sentido común: dejar de hacer ABSOLUTAMENTE las actividades que provocan el dolor. Cambiar deportes de impacto o sentadillas profundas por natación suave o ejercicios sin flexión de rodilla. Usar hielo 15 minutos tras la actividad para apagar la inflamación ardiente.", "Medicamentos y Suplementos: Analgésicos antiinflamatorios (Ibuprofeno, Naproxeno) solo para el dolor agudo. Aunque su eficacia es muy debatida en estudios médicos, algunos médicos recomiendan suplementos largos de Glucosamina y Condroitina, o inyecciones de Ácido Hialurónico intraarticular para intentar proteger o lubricar el cartílago blando restante."] }, { title: "Rehabilitación Física (La cura a largo plazo)", items: ["Fisioterapia intensiva y específica: Es el tratamiento más fundamental y efectivo. El fisioterapeuta creará un programa para fortalecer masiva y aisladamente el músculo cuádriceps medial (VMO) y los abductores de la cadera. Músculos fuertes tirarán de la rótula devolviéndola al centro de su riel, eliminando el roce de inmediato.", "Flexibilidad y Estiramientos: Sesiones diarias para alargar y relajar los isquiotibiales y estirar mecánicamente la banda iliotibial (a menudo dolorosa) con masajes profundos o rodillos de espuma (foam rollers).", "Ortesis y Apoyo Biomecánico: Uso temporal de rodilleras de centrado patelar (con un orificio u aro de silicona que abraza la rótula y no la deja salirse), uso de vendajes neuromusculares (Taping rotuliano) antes de entrenar, y uso indispensable de Plantillas Ortopédicas si el paciente tiene pie plano o mala pisada que arruina el ángulo de la rodilla."] }, { title: "Opciones Quirúrgicas (Último Recurso)", items: ["Cirugía Artroscópica Mínimamente Invasiva: Se considera ÚNICAMENTE tras 6-12 meses de fisioterapia estricta fallida. El cirujano traumatólogo entra con una cámara a la rodilla. Si el cartílago está deshilachado (forma 'cuerdas' que causan dolor al raspar), utiliza instrumental motorizado para pulirlo, alisarlo y limpiarlo (condroplastia/desbridamiento).", "Liberación Lateral (Lateral Release): Si la rótula está demasiado tirada hacia afuera por culpa de ligamentos extremadamente rígidos, el cirujano hace cortes estratégicos en los ligamentos laterales (retináculo lateral) para aflojarlos y permitir que la rótula regrese a deslizarse centrada en su surco."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide cita con fisioterapia, médico del deporte o traumatólogo si:", items: ["El dolor frontal de tu rodilla se ha vuelto constante y no desaparece tras unas semanas de evitar el ejercicio de impacto y descansar", "Sentarte en tu escritorio de trabajo o en el coche te provoca punzadas de dolor agudo al intentar levantarte", "Sientes ruidos de molienda o crujidos fuertes (como si tuvieras arena), acompañados de hinchazón repentina de la rodilla", "La rodilla cede repetidamente bajo tu peso al caminar (falla por inhibición del dolor)"] } },
'Agorafobia' : { intro: "La agorafobia es un trastorno de ansiedad mental y conductual sumamente complejo, paralizante y a menudo incomprendido. Se caracteriza por un miedo irracional, intenso y persistente a encontrarse en lugares, entornos o situaciones específicas en las que la persona siente que escapar podría ser difícil, físicamente embarazoso o que, en caso de sufrir un ataque de pánico o síntomas angustiantes repentinos, no habría ayuda inmediata disponible.", whatIs: { title: "¿Qué es la Agorafobia?", text: "Existe un mito popular de que la agorafobia es simplemente el 'miedo a salir de casa' o a los 'espacios abiertos'. En realidad, la dinámica es mucho más profunda: es el miedo al pánico en sí mismo. En casi todos los casos, la agorafobia se desarrolla como una complicación de un Trastorno de Pánico previo. Una persona sufre un ataque de pánico brutal e inesperado en un lugar público (como un tren o un cine). El cerebro, aterrorizado por la experiencia, asocia inconscientemente ese lugar con el peligro mortal del pánico. Para evitar sufrir otro ataque, la persona comienza a evitar ese lugar. Luego, la ansiedad anticipatoria se extiende a evitar situaciones similares, luego a evitar cualquier lugar concurrido, hasta que la conducta de evitación se vuelve tan extrema que el único lugar que el individuo percibe como 'seguro' es el interior de su propia casa, destruyendo por completo su capacidad para llevar una vida normal o independiente." }, symptoms: { title: "Síntomas Psicológicos, Físicos y de Conducta", intro: "El trastorno se manifiesta por una combinación del miedo profundo a las situaciones y los síntomas físicos que estallan al enfrentarlas:", groups: [ { name: "Situaciones y Entornos Típicamente Temidos y Evitados", items: ["El miedo central se desencadena, casi universalmente, en dos o más de estas situaciones vitales:", "Estar en cualquier tipo de transporte público (viajar en autobuses, metros, trenes, barcos o aviones, o a veces, conducir un auto por carreteras sin salida o en tráfico denso)", "Estar en espacios abiertos, anchos y extensos (estacionamientos enormes, puentes largos, parques masivos sin refugio cercano)", "Estar confinado en espacios cerrados y pequeños (tiendas pequeñas, cines, teatros, ascensores o túneles sin ventanas)", "Hacer cola en la caja de un supermercado, estar de pie en una fila donde hay que esperar, o encontrarse en medio de una multitud densa de gente", "El simple hecho de salir de casa estando completamente solo (requiriendo obligatoriamente la presencia de un 'compañero seguro' como el cónyuge o la madre para salir)"] }, { name: "Síntomas Físicos Agudos de Pánico (Si se exponen al miedo)", items: ["Taquicardia severa (corazón acelerado o palpitaciones fuertes) y presión aguda en el pecho", "Hiperventilación, sensación de asfixia o de no poder introducir aire en los pulmones", "Sudoración profusa repentina, escalofríos y temblores incontrolables en el cuerpo", "Mareos severos, sensación de aturdimiento, inestabilidad o desmayo inminente", "Náuseas agudas, malestar gastrointestinal, y la necesidad repentina de ir al baño (que intensifica el miedo a la vergüenza pública)", "Miedo catastrófico de estar sufriendo un infarto, volverse loco, perder completamente el control del cuerpo o temor a morir inminentemente"] }, { name: "Consecuencias Conductuales (Efecto dominó)", items: ["Ansiedad anticipatoria: Pasar horas o días sufriendo ansiedad extrema solo pensando en un viaje que se debe hacer.", "Evitación total y absoluta: Alterar rutas del trabajo, renunciar al empleo, dejar de visitar a la familia o negarse a salir de casa durante meses o años para no enfrentarse a la ansiedad."] } ], warning: "Si no se trata, la agorafobia es una de las condiciones psiquiátricas más incapacitantes. El paciente a menudo desarrolla depresión clínica mayor, ideación suicida y problemas severos de abuso de alcohol o drogas sedantes, utilizados como intento desesperado de automedicarse para aliviar el miedo a salir." }, types: { title: "Causas y Factores Desencadenantes", intro: "La agorafobia raramente aparece de la nada; el desarrollo del trastorno está impulsado por la biología, la personalidad y el entorno:", items: ["Trastorno de Pánico Subyacente (Causa Primaria): La inmensa mayoría de las agorafobias surgen tras experimentar uno o más ataques de pánico espontáneos. El cerebro condiciona una respuesta fóbica, y el miedo a 'tener miedo otra vez' inicia la cadena de evitación.", "Temperamento y Personalidad: Personas que biológicamente tienen un sistema nervioso simpático muy reactivo, personas con tendencias ansiosas, perfeccionistas, con necesidad excesiva de control o que se angustian mucho ante situaciones nuevas y desconocidas.", "Experiencias de vida traumáticas: Haber sufrido eventos dolorosos de niño o adulto (como abusos graves, la muerte súbita de un padre o ataques personales) puede predisponer al cerebro a percibir el mundo exterior como hostil.", "Genética: Tener familiares consanguíneos (padres, hermanos) que sufren de trastornos de pánico severos u otras fobias multiplica significativamente la probabilidad biológica de padecer la enfermedad."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico formal lo realiza un profesional de la salud mental (psicólogo clínico o psiquiatra) mediante entrevistas estructuradas:", items: ["Evaluación Diagnóstica Integral: El clínico hablará detalladamente sobre los síntomas, cuándo ocurren, qué los desencadena, los miedos catastrofistas del paciente y cómo esto ha restringido su vida diaria y laboral.", "Criterios del DSM-5 (Manual Diagnóstico): El diagnóstico oficial de agorafobia exige que la persona presente un miedo abrumador y desproporcionado sobre al menos dos (2) de las cinco situaciones clave (transporte, espacios cerrados, espacios abiertos, hacer fila/multitudes, salir de casa solo); que evite activamente estas situaciones casi siempre, debido al miedo de que el escape sea difícil o no haya ayuda si tiene síntomas incapacitantes o de pánico; y que esta evitación continua haya durado 6 meses o más y cause un sufrimiento clínico significativo.", "Exámenes Médicos Físicos: Es imperativo que un médico de cabecera realice exámenes iniciales (ECG, pruebas de tiroides, toxicológicas) para descartar firmemente que los síntomas físicos de taquicardia o asfixia no se deban a problemas de corazón (arritmias), hipertiroidismo o asma no tratada."], note: "" }, treatment: { title: "Tratamientos", intro: "A pesar de ser paralizante, la agorafobia es un trastorno altamente tratable. Recuperar la libertad no sucede de la noche a la mañana, sino que es un proceso clínico que requiere romper permanentemente el circuito neurológico del miedo:", subsections: [ { title: "Intervención Psicológica Principal", items: ["Terapia Cognitivo-Conductual (TCC): Es el estándar de oro, el tratamiento más eficaz y duradero. El psicólogo ayuda al paciente a comprender que sus pensamientos de desastre ('voy a morir', 'voy a desmayarme frente a todos') son irracionales e inexactos. Se enseñan técnicas prácticas de relajación profunda, reestructuración cognitiva y control de la respiración para no huir cuando empieza la ansiedad.", "Terapia de Exposición Gradual y Sistemática (El paso curativo): Como parte vital de la TCC, el terapeuta diseña un plan para enfrentarse a las fobias. Esto se hace de forma extremadamente lenta y controlada (desensibilización). Por ejemplo: primero el paciente se imagina salir al coche, otro día camina hasta la puerta, semanas después viaja en autobús acompañado del terapeuta. Al enfrentarse repetidamente a la situación, sin huir y viendo que el 'desastre' no ocurre, el cerebro desaprende el miedo por habituación.", "Terapia de Realidad Virtual (RV): Una tecnología moderna y muy útil donde el paciente, usando gafas 3D en un consultorio seguro, se enfrenta a simulaciones de trenes, aviones o multitudes, lo que permite la terapia de exposición a un ritmo seguro antes de salir al mundo real."] }, { title: "Tratamiento Farmacológico (Soporte Químico)", items: ["Antidepresivos (ISRS e IRSN): Medicamentos recetados como la Sertralina (Zoloft), Paroxetina (Paxil), Fluoxetina o Venlafaxina. Son la primera línea farmacológica. Regulan los químicos del cerebro (serotonina) a largo plazo, reduciendo drásticamente la intensidad general de la ansiedad subyacente y la frecuencia de los ataques de pánico (tardan semanas en hacer efecto).", "Ansiolíticos (Benzodiazepinas): Fármacos sedantes potentes de acción muy rápida (como Alprazolam o Clonazepam). Los psiquiatras los recetan únicamente para tomar a corto plazo o como 'pastillas de rescate' en situaciones de pánico extremo incontrolable. Nunca deben ser el tratamiento principal a largo plazo debido a su gravísimo riesgo de adicción, tolerancia y sedación que interfiere con la TCC."] } ], note: "Para tener éxito, el paciente debe aceptar sentir la incomodidad de la ansiedad durante el tratamiento. Tratar la agorafobia sin exponerse lentamente al exterior rara vez funciona." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No pospongas el tratamiento esperando que desaparezca solo; la agorafobia tiende a empeorar y atraparte. Pide ayuda psicológica o psiquiátrica inmediata si:", items: ["El miedo a sufrir un ataque de ansiedad está afectando tus relaciones personales y te está obligando a limitar drásticamente tus lugares, aislarte socialmente, perder oportunidades laborales o abandonar la escuela", "Estás cambiando tu vida para acomodarte al miedo (evitando conducir en autopistas, evitando tiendas abarrotadas, cancelando viajes, o no pudiendo dejar a tu 'acompañante seguro')", "Tú o un ser querido no pueden salir de casa en absoluto debido al pánico aterrorizante, o experimentas depresión grave y pensamientos de no querer vivir por culpa de esta limitación extrema"] } },
'Pielonefritis' : { intro: "La pielonefritis es una infección bacteriana aguda, severa e inflamatoria que afecta al tejido de uno o ambos riñones y a la pelvis renal (el embudo donde se recoge la orina). Es, en esencia, la complicación y escalada más peligrosa de una infección del tracto urinario (ITU) inferior.", whatIs: { title: "¿Qué es la Pielonefritis?", text: "La orina en el cuerpo suele ser un ambiente estéril. La inmensa mayoría de las infecciones renales no empiezan en el riñón. Todo comienza cuando bacterias (normalmente las de las heces) entran por el orificio de la uretra y colonizan la vejiga (causando cistitis o infección de orina normal). Si esta infección de vejiga no se trata rápida o adecuadamente con antibióticos, o si el paciente tiene problemas inmunológicos o anatómicos, las bacterias comienzan a viajar 'río arriba' a través de los tubos (uréteres) hasta llegar al riñón. Una vez alojadas dentro del tejido renal, las bacterias se multiplican explosivamente provocando una inflamación brutal, hinchazón del órgano y formación de pus microscópico. Esta infección profunda es muy peligrosa porque el riñón filtra toda la sangre del cuerpo; si la bacteria cruza del riñón infectado hacia la sangre, puede provocar una septicemia fulminante (shock séptico) que amenaza la vida en horas." }, symptoms: { title: "Síntomas y Alertas Sistémicas", intro: "Los síntomas de una pielonefritis aparecen rápidamente, a menudo a las pocas horas de iniciar, y son incomparablemente más sistémicos, intensos y violentos que el simple ardor al orinar de una cistitis básica:", groups: [ { name: "Síntomas de Infección General y Severa", items: ["Fiebre muy alta y repentina (generalmente superior a 39°C o 102°F), a menudo el primer síntoma de advertencia grave", "Escalofríos intensos, temblores incontrolables (tiritonas) y sudoración profusa", "Náuseas agudas, vómitos repetidos y pérdida total o incapacidad de ingerir alimentos o líquidos por malestar extremo", "Sensación de fatiga aplastante, letargo profundo, dolor muscular, malestar general o confusión mental repentina (especialmente en pacientes ancianos, lo que indica posible paso de la infección a la sangre)"] }, { name: "Síntomas Urinarios y Renales Directos", items: ["Dolor intenso, sordo y constante en la espalda baja, en la zona lumbar lateral, el costado del torso (dolor de flanco), o en el abdomen/ingle; característicamente localizado en el lado del riñón que está infectado", "Molestias clásicas de infección de orina previas o actuales: dolor, escozor, ardor agudo al orinar (disuria) y necesidad desesperada, urgente y muy frecuente de ir al baño a hacer solo gotas", "La orina presenta un aspecto muy turbio, denso, opaco o de color muy oscuro, con un olor fuerte, rancio y sumamente desagradable, y frecuentemente puede verse sangre (hematuria rosada o rojiza)"] } ], warning: "Si los episodios de pielonefritis ocurren de manera repetitiva crónica en una persona a lo largo de los años, o si una infección aguda no recibe atención de emergencia, las lesiones purulentas se curarán dejando grandes cicatrices muertas de tejido (fibrosis renal). Esto destruye permanentemente las nefronas y puede llevar, con el tiempo, a enfermedad renal crónica progresiva, hipertensión severa o, en última instancia, pérdida del riñón e insuficiencia renal terminal." }, types: { title: "Causas, Patógenos y Factores de Riesgo", intro: "El patógeno indiscutible en más del 80% de los casos es la bacteria *Escherichia coli* (*E. coli*), proveniente de la flora intestinal y rectal. Aunque cualquier persona sana puede contraerla tras una cistitis desafortunada, existen factores que multiplican gigantescamente las probabilidades de que la bacteria suba al riñón:", items: ["Ser Mujer y la Actividad Sexual: Las mujeres tienen una altísima tasa de pielonefritis porque su uretra es anatómicamente muy corta y está extremadamente cerca del ano, lo que permite un acceso rápido y fácil de las bacterias a la vejiga. La actividad sexual intensa facilita el empuje mecánico de estas bacterias hacia el conducto urinario.", "Embarazo: Es un factor de riesgo crítico. El útero en crecimiento aplasta físicamente los uréteres y ralentiza el flujo de orina. Además, los cambios hormonales aflojan los músculos del tracto urinario, facilitando que la orina con bacterias retroceda o se estanque en el camino a los riñones.", "Obstrucción Mecánica Urinaria (Bloqueo anatómico): Si algo interrumpe el flujo 'río abajo', la orina vieja e infectada se estanca y lava bacterias hacia atrás. Esto es provocado por piedras en el riñón (cálculos ureterales) trabadas en los conductos, una próstata hiperplásica y agrandada en hombres mayores, tumores o problemas neurológicos de la vejiga.", "Reflujo Vesicoureteral (RVU): Una condición anatómica congénita, muy común y peligrosa en bebés y niños pequeños, donde las válvulas de la vejiga no cierran bien, permitiendo que la orina de la vejiga fluya al revés y vuelva a inyectarse en los riñones cada vez que el niño orina.", "Sistema Inmunológico Debilitado o Medicamentos: Pacientes con diabetes mellitus descontrolada, personas infectadas con VIH, pacientes en terapias contra el cáncer o tomando drogas inmunosupresoras contra el rechazo de órganos tienen las defensas destruidas y no pueden repeler las infecciones.", "Uso Médico de Sondas y Catéteres: Pacientes hospitalizados con una sonda vesical permanente, o instrumentos médicos introducidos en las vías urológicas (cistoscopias, retiro de piedras) que arrastran bacterias de los hospitales directamente al tracto interno."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Ante los síntomas de alarma, el médico urgenciólogo confirmará el ataque renal, identificará al invasor y descartará complicaciones graves u obstrucciones antes de administrar el tratamiento definitivo:", items: ["Análisis de Orina (Urianálisis completo): Es la prueba rápida e inmediata. El laboratorio busca concentraciones elevadas y alarmantes de glóbulos blancos (leucocituria/piuria, señal inconfundible de inflamación e infección en los riñones), sangre oculta y la presencia masiva de nitritos y bacterias. Se busca específicamente la presencia de 'cilindros leucocitarios', formaciones que solo se crean dentro de los túbulos renales y confirman la pielonefritis.", "Urocultivo con Antibiograma: La prueba más indispensable y obligatoria. Se envía la orina en condiciones estériles a la incubadora del laboratorio para dejar crecer físicamente la bacteria culpable. Esto identifica exactamente si es *E. coli* u otra cepa multirresistente de hospital, y, más crucialmente, se prueban antibióticos sobre ella para decirle al médico qué medicina la matará (antibiograma). Tarda de 48 a 72 horas.", "Hemograma completo y Hemocultivo (Análisis de sangre): Si el paciente llega a urgencias con fiebre altísima, letargo o presión baja, el médico extraerá sangre de la vena e incubará cultivos de sangre de emergencia para descartar bacteriemia o que la infección esté nadando letalmente por todo el torrente circulatorio.", "Imágenes Médicas (Ecografía Renal, TAC Abdominopélvico o Resonancia Magnética): Generalmente, una pielonefritis no complicada en una mujer joven sana NO requiere escaner. SIN EMBARGO, si la fiebre no cede tras 72 horas con antibióticos intravenosos potentes, si hay sangre extrema y dolor cólico brutal, o si el paciente es hombre, anciano o diabético, se debe hacer de urgencia una Tomografía Computarizada o Ecografía Renal para descartar abscesos renales grandes (bolsas de pus) o para verificar que no haya una piedra de riñón letal que esté taponando el conducto e impidiendo curar la infección."] }, treatment: { title: "Tratamientos", intro: "El tratamiento de la pielonefritis no puede demorarse y descansa íntegramente sobre una terapia antibiótica específica y rápida, cuya agresividad depende de lo enfermo que esté el paciente y si existen complicaciones de riesgo:", subsections: [ { title: "Manejo Antibiótico y de Urgencia", items: ["Infección no complicada (Manejo Ambulatorio / en Casa): Si el paciente es un adulto joven y saludable, está bien hidratado, tiene fiebre manejable y no vomita los medicamentos, el médico de urgencias recetará un régimen de antibióticos orales fuertes (frecuentemente Fluoroquinolonas como Ciprofloxacino, Levofloxacino, o una Cefalosporina/Trimetoprima, si las tasas de resistencia lo permiten) para tomar en casa de manera estricta durante unos 7 a 14 días seguidos. Es absolutamente imprescindible no dejar ninguna pastilla y terminar todas las dosis, incluso si la fiebre, los escalofríos y el dolor lumbar desaparecen completamente a los dos días. Parar antes de tiempo crea superbacterias resistentes y asegura una recaída renal mucho más brutal a la semana siguiente.", "Infección severa (Ingreso Hospitalario Intravenoso): Si la infección amenaza la vida (el paciente es un anciano, tiene signos de sepsis, vómitos incontrolables que impiden beber pastillas y agua, está severamente deshidratado o se trata de una mujer embarazada), requerirá hospitalización inmediata obligatoria en cama. Recibirá hidratación masiva y antibióticos de amplio y máximo espectro directamente por suero intravenoso (IV) (como Ceftriaxona o Carbapenémicos) durante unos días hasta que la fiebre caiga, el dolor ceda y el paciente mejore, pudiendo irse de alta con pastillas para completar el mes.", "Tratamiento de Soporte para el Dolor y la Deshidratación: Durante los primeros días críticos, se recetan potentes medicamentos analgésicos y antipiréticos (Paracetamol, u ocasionalmente AINEs) para calmar la fiebre abrasadora y las punzadas en la espalda, mientras el paciente debe forzarse a beber cantidades industriales de agua pura (si sus riñones se lo permiten) para arrastrar y orinar las bacterias constantemente."] }, { title: "Intervenciones Quirúrgicas Complicadas", items: ["Procedimientos de Rescate Estructural o Extracción de Piedras: Si la pielonefritis es secundaria y provocada por un problema estructural obstructivo (como una piedra enorme en el riñón que tapa el uréter, o una próstata deformada), los antibióticos por vena no servirán de nada porque no pueden penetrar al riñón cerrado y lleno de pus. Un urólogo deberá entrar al quirófano de urgencia e introducir herramientas o un stent (catéter interno doble J) por las vías, o poner un tubo directamente en la espalda (nefrostomía percutánea) para desatascar físicamente la tubería y permitir que el pus del riñón fluya al exterior; las piedras deben ser desintegradas. En niños con reflujo vesicoureteral crónico grave, pueden requerir cirugía reparadora de válvulas ureterales si las infecciones amenazan la cicatrización temprana de los riñones infantiles."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No esperes a que 'se pase con agua'. La infección renal es una escalada muy grave. Acude o llama a un centro de urgencias del hospital si en ti o tu familiar observas alguna de las siguientes señales:", items: ["Llevas con síntomas de cistitis y de pronto experimentas fiebre repentina muy alta acompañada de escalofríos profundos que te hacen tiritar los dientes incontrolablemente, debilidad postrante o confusión mental repentina", "Sufres un dolor nuevo, muy profundo, molesto e insoportable a los lados o la espalda baja (zona de los riñones), que empeora si golpeas suavemente esa zona", "Las molestias o dolores van acompañados de vómitos severos e incapacidad total de mantener el agua en el estómago por las náuseas, signos de deshidratación extrema u orina de un color parecido al coñac oscuro y sangriento"] } },
'Subluxación' : { intro: "Una subluxación es el desplazamiento parcial o incompleto de un hueso desde su posición normal dentro de una articulación. Aunque los huesos aún mantienen algo de contacto, la estructura se desestabiliza y causa dolor agudo.", whatIs: { title: "¿Qué es una Subluxación?", text: "A diferencia de una luxación completa (dislocación), donde los huesos de la articulación se separan totalmente, en una subluxación la separación es solo parcial. Las superficies articulares aún se tocan, pero están desalineadas. Esto estira o desgarra los ligamentos, tendones y la cápsula articular circundante, lo que puede volver la articulación inestable e hiperlaxa a largo plazo." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos son similares a los de una luxación, pero generalmente menos severos en cuanto a deformidad:", groups: [ { name: "Síntomas Físicos y Sensoriales", items: ["Dolor agudo e inmediato en la articulación al moverla o aplicar peso", "Sensación de inestabilidad, como si la articulación fuera a 'ceder' o 'salirse'", "Hinchazón visible y enrojecimiento o moretones alrededor del área", "Pérdida de la amplitud de movimiento normal", "Entumecimiento u hormigueo leve si hay un nervio temporalmente pellizcado"] } ], warning: "Si la articulación vuelve a su lugar por sí sola (se subluxa y se reduce espontáneamente), los ligamentos pueden quedar estirados, aumentando drásticamente el riesgo de que el problema se repita con movimientos menores." }, causes: { title: "Causas y Factores de Riesgo", intro: "Generalmente es el resultado de un trauma físico o laxitud de los tejidos:", items: ["Traumatismos directos: Caídas, accidentes automovilísticos o impactos en deportes de contacto.", "Movimientos bruscos: Torsiones violentas de una articulación (muy común en el hombro, la rótula de la rodilla o el tobillo).", "Hiperlaxitud articular: Personas que nacen con ligamentos muy elásticos (como en el Síndrome de Ehlers-Danlos) son muy propensas a subluxaciones crónicas.", "Desgaste degenerativo: La artrosis debilita las estructuras que mantienen la articulación en su lugar."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere evaluar la alineación ósea y el daño a los tejidos blandos:", items: ["Examen físico: El médico evaluará la estabilidad de la articulación, el dolor y la inflamación.", "Radiografías (Rayos X): Esenciales para confirmar que la articulación no está completamente dislocada y para descartar fracturas asociadas.", "Resonancia Magnética (RM): Se solicita posteriormente para ver la gravedad de los desgarros en los ligamentos, el cartílago o los tendones que se estiraron durante el evento."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento busca aliviar el dolor, devolver la estabilidad y prevenir recurrencias:", subsections: [ { title: "Manejo y Rehabilitación", items: ["Reducción: Si el hueso no ha vuelto a su lugar por sí solo, un médico lo acomodará suavemente (reducción cerrada) bajo anestesia local o sedación leve.", "Inmovilización: Uso de un cabestrillo, férula o rodillera durante unos días o semanas para permitir que los ligamentos inflamados cicatricen.", "Protocolo RICE: Reposo, Hielo, Compresión y Elevación en las primeras 48 horas.", "Fisioterapia: El tratamiento más crítico a largo plazo. Ejercicios para fortalecer masivamente los músculos que rodean la articulación, creando un 'corsé' muscular que compense los ligamentos estirados.", "Cirugía: Se considera solo si la articulación sufre subluxaciones crónicas y repetitivas que limitan la vida diaria, para tensar y reparar los ligamentos (ej. cirugía de estabilización del hombro o de la rótula)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o a un traumatólogo si:", items: ["Sientes un dolor intenso tras un impacto y la articulación se ve deformada o no puedes moverla", "La articulación está visiblemente hinchada y sientes que cede al soportar tu peso", "Experimentas entumecimiento, palidez o frialdad en la extremidad por debajo de la lesión (posible daño nervioso o vascular)"] } },
'Tromboflebitis' : { intro: "La tromboflebitis es un proceso inflamatorio que hace que se forme un coágulo de sangre (trombo) que bloquea una o más venas, generalmente en las piernas. Puede ocurrir en venas cercanas a la superficie de la piel o en venas profundas dentro del músculo.", whatIs: { title: "¿Qué es la Tromboflebitis?", text: "Es una afección vascular de dos partes: 'trombo' (coágulo) y 'flebitis' (inflamación de la vena). Cuando el flujo de sangre se vuelve lento debido a la inmovilidad, o si la pared de la vena se daña, la sangre puede coagularse. Si esto ocurre en las venas superficiales justo bajo la piel, es doloroso pero rara vez peligroso. Sin embargo, si ocurre en una vena profunda del músculo (Trombosis Venosa Profunda o TVP), es una emergencia médica grave porque el coágulo puede soltarse y viajar a los pulmones." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen de si la vena afectada es superficial o profunda:", groups: [ { name: "Tromboflebitis Superficial", items: ["Aparición de un 'cordón' rojo, duro y muy sensible justo debajo de la superficie de la piel", "Calor, dolor y enrojecimiento localizado a lo largo de la vena afectada", "Hinchazón leve alrededor de la vena inflamada"] }, { name: "Trombosis Venosa Profunda (TVP)", items: ["Hinchazón severa y repentina de toda la pierna, tobillo o pie (generalmente en un solo lado)", "Dolor intenso tipo calambre pesado en la pantorrilla o el muslo, que empeora al caminar o estar de pie", "Piel de la pierna afectada que se siente inusualmente caliente y puede adquirir un tono rojizo o azulado pálido"] } ], warning: "Si tienes un coágulo profundo y de repente sientes una falta de aire extrema, dolor en el pecho al respirar profundo o toses sangre, el coágulo se ha roto y ha llegado a los pulmones (Embolia Pulmonar). Llama al 911 de inmediato." }, types: { title: "Clasificación por Ubicación", intro: "El tratamiento difiere radicalmente según la profundidad de la vena:", items: ["Tromboflebitis Superficial (o flebitis): Afecta las venas visibles. Rara vez causa embolias porque estas venas no tienen el calibre ni el flujo directo principal hacia el corazón.", "Trombosis Venosa Profunda (TVP): Afecta las grandes venas 'autopista' dentro de los músculos de la pantorrilla, el muslo o la pelvis. Requiere tratamiento agresivo para evitar la muerte por embolia."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Los coágulos se forman por factores que alteran la sangre o las venas (la Tríada de Virchow):", items: ["Inactividad prolongada: Viajes largos en avión o coche, o estar en cama tras una cirugía o enfermedad (la sangre se estanca).", "Lesión en la vena: Debido a un traumatismo, inserción de un catéter intravenoso (IV) o uso de agujas.", "Hipercoagulabilidad: Tener cáncer, estar embarazada, usar píldoras anticonceptivas, terapia de reemplazo hormonal, o padecer trastornos genéticos de la coagulación (como el Factor V Leiden).", "Otros riesgos: Edad avanzada, obesidad, tabaquismo y tener varices severas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico vascular realizará pruebas para ubicar el coágulo:", items: ["Ecografía Doppler (Ultrasonido venoso): Es la prueba de oro, rápida e indolora. Permite ver el coágulo directamente dentro de la vena y medir si el flujo de sangre está bloqueado.", "Prueba de Dímero D (Análisis de sangre): Mide una sustancia que se libera cuando un coágulo se disuelve. Si es negativa, es muy poco probable que tengas una TVP.", "Tomografía Computarizada (TC) o Resonancia Magnética (RM): Se utilizan para buscar coágulos profundos en el abdomen o si se sospecha una embolia pulmonar en el tórax."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento busca calmar la inflamación y, sobre todo, evitar que el coágulo crezca o se mueva:", subsections: [ { title: "Manejo Superficial y Profundo", items: ["Tratamiento de la Tromboflebitis Superficial: Suele resolverse sola. Se trata con AINEs (Ibuprofeno) para el dolor, elevación de la pierna, aplicación de calor húmedo y uso de medias de compresión graduada.", "Tratamiento de la Trombosis Venosa Profunda (TVP): Requiere Anticoagulantes de inmediato (inyecciones de heparina o pastillas como Apixabán, Rivaroxabán o Warfarina) que se toman durante 3 a 6 meses. No 'disuelven' el coágulo existente, pero evitan que crezca mientras el propio cuerpo lo reabsorbe.", "Trombolíticos: En casos de TVP muy extensas y graves, se inyectan fuertes medicamentos disuelve-coágulos directamente en la vena a través de un catéter, aunque conllevan alto riesgo de hemorragia.", "Filtro de la Vena Cava Inferior: Si el paciente no puede tomar anticoagulantes (ej. tiene un sangrado activo en otra zona), el cirujano inserta un pequeño filtro de metal en la vena principal del abdomen para atrapar cualquier coágulo antes de que llegue a los pulmones."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es una urgencia médica si:", items: ["Una de tus piernas se hincha drásticamente, se enrojece y te duele mucho al caminar", "La vena inflamada en la superficie de la piel empeora, la zona se vuelve muy dura o te da fiebre", "Sientes dolor de pecho punzante o dificultad súbita para respirar (Embolia Pulmonar)"] } },
'Pólipos colorrectales' : { intro: "Los pólipos colorrectales son crecimientos anormales de tejido que se forman en el revestimiento interno del colon (intestino grueso) o el recto. Aunque la gran mayoría son benignos (no cancerosos), algunos tipos pueden transformarse en cáncer colorrectal con el paso del tiempo si no se extirpan.", whatIs: { title: "¿Qué son los Pólipos Colorrectales?", text: "El colon constantemente produce células nuevas para renovar su revestimiento interno. Cuando hay un error genético local en este proceso, las células crecen y se dividen más de lo debido, formando un pequeño bulto o masa (un pólipo). Pueden tener forma de pequeño hongo con un tallo (pediculados) o ser planos como una mancha en la pared (sésiles). Extirparlos cuando son pequeños es la medida preventiva más eficaz contra el cáncer de colon." }, symptoms: { title: "Síntomas y Alertas", intro: "Los pólipos rara vez causan síntomas; la mayoría de las personas no saben que los tienen hasta que se los detectan en un examen de rutina. Si son grandes, pueden causar:", groups: [ { name: "Signos Frecuentes", items: ["Sangrado rectal: Notar sangre roja brillante en el papel higiénico o en el inodoro", "Cambio en el color de las heces: La sangre proveniente de un pólipo alto en el colon puede hacer que las heces se vean negras o con rayas rojas oscuras", "Cambios en los hábitos intestinales: Estreñimiento o diarrea que dura más de una semana", "Dolor abdominal, cólicos o dolor sordo (si un pólipo muy grande obstruye parcialmente el intestino)", "Anemia por deficiencia de hierro: El sangrado microscópico crónico e invisible de un pólipo a lo largo del tiempo reduce los glóbulos rojos, causando fatiga extrema y palidez"] } ], warning: "Debido a la ausencia total de síntomas en las etapas iniciales y precancerosas, las pruebas de cribado (colonoscopia) a partir de los 45 años son la única forma de salvar vidas detectándolos a tiempo." }, types: { title: "Tipos de Pólipos", intro: "El patólogo los analiza bajo el microscopio para evaluar el riesgo de cáncer:", items: ["Pólipos Adenomatosos (Adenomas): Representan aproximadamente dos tercios de los pólipos. Tienen el potencial de convertirse en cáncer, por lo que se consideran lesiones precancerosas y deben extirparse siempre.", "Pólipos Serrados (Hiperplásicos): A menudo son inofensivos y de bajo riesgo si son pequeños y están en la parte final del colon. Sin embargo, los adenomas serrados grandes o en la parte superior del colon sí tienen riesgo de cáncer.", "Pólipos Inflamatorios: Aparecen como reacción a la inflamación intestinal (como en la enfermedad de Crohn o la colitis ulcerosa). No son precancerosos en sí, pero la enfermedad que los causa sí eleva el riesgo de cáncer en general."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El riesgo de desarrollar pólipos aumenta significativamente con:", items: ["Edad: Es mucho más común en personas mayores de 45-50 años.", "Antecedentes familiares: Tener un padre, hermano o hijo con pólipos o cáncer de colon.", "Estilo de vida: Dieta rica en carnes rojas y grasas y pobre en fibra, obesidad, tabaquismo y consumo elevado de alcohol.", "Afecciones hereditarias raras: Como la Poliposis Adenomatosa Familiar (PAF) o el Síndrome de Lynch, que causan la formación de cientos de pólipos a edades muy tempranas.", "Enfermedad Inflamatoria Intestinal crónica."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico y cribado son fundamentales:", items: ["Colonoscopia: El estándar de oro. El gastroenterólogo inserta un tubo largo y flexible con una cámara (colonoscopio) por el recto para examinar todo el colon. Si encuentra pólipos, puede extirparlos en el mismo momento.", "Pruebas de sangre oculta en heces (SOH o FIT): Exámenes de laboratorio que buscan rastros microscópicos de sangre o ADN anormal de pólipos en una muestra de heces. Si salen positivos, requieren colonoscopia.", "Colonoscopia virtual (Colografía por TC): Una tomografía computarizada especial que crea imágenes 3D del colon. Es menos invasiva, pero si se ve un pólipo, habrá que hacer una colonoscopia tradicional para quitarlo."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento más seguro y efectivo es la eliminación total del pólipo:", subsections: [ { title: "Procedimiento de Extirpación", items: ["Polipectomía durante colonoscopia: El médico pasa un asa de alambre a través del colonoscopio, enlaza el pólipo, lo corta y cauteriza la base para evitar el sangrado. Es indoloro y cura el problema en el acto.", "Cirugía Mínimamente Invasiva: Si el pólipo es demasiado grande o difícil de alcanzar con el colonoscopio, se puede requerir una cirugía laparoscópica para extraer la pequeña porción del colon donde se asienta.", "Cirugía de resección completa (Proctocolectomía): Reservada para pacientes con síndromes genéticos raros (como PAF) que desarrollan cientos de pólipos incontrolables; se extirpa el colon y el recto para evitar un cáncer seguro al 100%."] } ], note: "Tras extirpar adenomas, el paciente deberá someterse a colonoscopias de seguimiento cada 3 o 5 años, ya que las personas que forman pólipos tienden a formar otros nuevos en el futuro." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu gastroenterólogo o médico de cabecera si:", items: ["Tienes 45 años o más (para programar tu colonoscopia preventiva, incluso sin síntomas)", "Notas sangrado rectal de cualquier tipo, sangre en el papel, o heces muy oscuras", "Sufres un cambio drástico en tus hábitos intestinales que dura más de un par de semanas", "Experimentas fatiga severa inexplicable y palidez (posible anemia por sangrado oculto)"] } },
'Cáncer de esófago' : { intro: "El cáncer de esófago es una enfermedad maligna y agresiva que se desarrolla en el tubo largo y hueco (el esófago) que transporta los alimentos y líquidos desde la garganta hasta el estómago.", whatIs: { title: "¿Qué es el Cáncer de Esófago?", text: "El tumor se origina en el revestimiento interno del esófago y, a medida que crece, se propaga hacia las capas musculares externas y, eventualmente, a otras partes del cuerpo. Debido a la gran elasticidad del esófago, el tumor puede crecer significativamente antes de causar bloqueos o síntomas, lo que a menudo lleva a diagnósticos en etapas tardías y avanzadas." }, symptoms: { title: "Síntomas y Alertas", intro: "Los síntomas no suelen aparecer hasta que el tumor restringe el paso de los alimentos:", groups: [ { name: "Síntomas Deglutorios y Generales", items: ["Dificultad para tragar (Disfagia): El síntoma más característico. Comienza con dificultad para tragar sólidos (como pan o carne) y, a medida que el tubo se cierra, progresa a dificultad para tragar líquidos.", "Sensación de que la comida se queda atascada en el pecho detrás del esternón", "Pérdida de peso rápida e involuntaria (debido a problemas para comer y a la agresividad del cáncer)", "Dolor o presión constante en el pecho, la espalda o dolor quemante al tragar (Odinofagia)", "Ardor de estómago (acidez) que empeora gravemente, o indigestión crónica constante", "Ronquera inexplicable, tos crónica y vómitos con sangre o material oscuro"] } ], warning: "La dificultad progresiva para tragar (que obliga a la persona a cambiar su dieta a papillas o líquidos) nunca debe ignorarse ni atribuirse a 'nervios'. Requiere una endoscopia urgente." }, types: { title: "Tipos de Cáncer de Esófago", intro: "Existen dos tipos principales, determinados por el tipo de células que mutan:", items: ["Adenocarcinoma: Es el tipo más común en países occidentales. Comienza en las células que producen mucosidad en la parte inferior del esófago (cerca del estómago). Está casi exclusivamente ligado a la enfermedad por reflujo ácido prolongado y a una condición precancerosa llamada 'Esófago de Barrett'.", "Carcinoma de Células Escamosas: Se forma en las células planas que recubren la parte superior y media del esófago. Su incidencia está fuertemente relacionada con el tabaquismo intenso, el consumo excesivo de alcohol y dietas muy pobres en nutrientes."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño crónico al tejido esofágico desencadena las mutaciones:", items: ["Enfermedad por Reflujo Gastroesofágico (ERGE): El ácido del estómago que quema constantemente la parte baja del esófago provoca 'Esófago de Barrett' (un cambio celular premaligno) y multiplica enormemente el riesgo de adenocarcinoma.", "Consumo de tabaco: Fumar o masticar tabaco.", "Consumo excesivo de alcohol: Y el riesgo se dispara aún más si se combina con tabaco.", "Obesidad (aumenta la presión gástrica y el reflujo).", "Acostumbrar beber líquidos o tés extremadamente calientes (queman y dañan crónicamente el revestimiento esofágico).", "Acalasia (un trastorno que dificulta el paso de la comida al estómago)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para observar el tumor y estadificarlo, se utilizan métodos endoscópicos e imágenes:", items: ["Endoscopia Superior (Gastroscopia): El paso fundamental. El médico inserta un tubo flexible con cámara por la garganta para ver el tumor de forma directa.", "Biopsia: Durante la endoscopia, el médico corta pequeños trozos de tejido sospechoso para examinarlos bajo el microscopio y confirmar el cáncer.", "Ecografía Endoscópica (USE): Un endoscopio con ultrasonido en la punta; es la mejor forma de ver qué tan profundo ha penetrado el tumor en la pared del esófago y si los ganglios locales están afectados.", "Tomografía Computarizada (TC) de tórax y abdomen, o escáner PET: Para determinar si el cáncer ha hecho metástasis (se ha diseminado) a pulmones, hígado o huesos."], note: "" }, treatment: { title: "Tratamientos", intro: "El plan de tratamiento depende de la etapa, ubicación del tumor y salud del paciente:", subsections: [ { title: "Enfoque Quirúrgico y Oncológico", items: ["Cirugía (Esofagectomía): La opción curativa principal en etapas tempranas. El cirujano extirpa la parte cancerosa del esófago (y a veces parte del estómago superior), y luego tira del estómago hacia el pecho o usa un trozo de intestino para conectarlo a la parte sana restante del esófago, reconstruyendo el tracto digestivo.", "Quimioterapia y Radioterapia: A menudo se administran juntas (quimiorradiación neoadyuvante) antes de la cirugía para reducir el tamaño del tumor y facilitar su extirpación. También se usan como tratamiento principal si el paciente no puede operarse o si el cáncer está avanzado, para aliviar síntomas y prolongar la vida.", "Inmunoterapia (Nivolumab, Pembrolizumab): Ayuda al propio sistema inmunológico a atacar el cáncer, usada frecuentemente en cánceres avanzados o metastásicos.", "Terapia Endoscópica: Para cánceres muy tempranos o pre-cánceres (Esófago de Barrett), se pueden remover por endoscopia (resección mucosa endoscópica) o quemar con láser o radiofrecuencia."] }, { title: "Tratamientos Paliativos", items: ["Colocación de un stent esofágico: Si el tumor inoperable bloquea el paso, se coloca un tubo expansible de metal por endoscopia para mantener el esófago abierto y permitir al paciente comer y tragar líquidos."] } ], note: "La cirugía de esófago es muy compleja y el proceso de recuperación requiere grandes ajustes en la alimentación, ingiriendo comidas muy pequeñas y frecuentes." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un gastroenterólogo con carácter de urgencia si experimentas:", items: ["Dificultad o dolor persistente al intentar tragar alimentos sólidos, como si se atascaran a mitad del pecho", "Acidez estomacal crónica o reflujo que de repente empeora severamente", "Pérdida de peso involuntaria rápida acompañada de tos o ronquera continua", "Vómitos oscuros que parecen posos de café o presencia de sangre"] } },
'Artritis bacteriana' : { intro: "La artritis bacteriana, médicamente conocida como artritis séptica o infecciosa, es una infección intensamente dolorosa y de rápida progresión en el interior de una articulación. Es una verdadera urgencia médica, ortopédica y reumatológica.", whatIs: { title: "¿Qué es la Artritis Bacteriana?", text: "El interior de una articulación (el líquido sinovial y el cartílago) es un ambiente normalmente estéril. Cuando bacterias patógenas logran ingresar a este espacio, se multiplican rápidamente en el líquido sinovial. El sistema inmunológico del cuerpo responde con una inflamación masiva que, en lugar de proteger, libera enzimas tóxicas que, junto con las bacterias, destruyen el cartílago que recubre los huesos en cuestión de días u horas, causando un daño articular irreversible si no se drena." }, symptoms: { title: "Síntomas y Manifestaciones", intro: "Los síntomas aparecen de forma extremadamente repentina (usualmente en horas) y afectan clásicamente a una sola articulación (más frecuentemente la rodilla, pero también cadera, hombro, codo o muñeca):", groups: [ { name: "Síntomas Articulares Agudos", items: ["Dolor articular agudo, severo e insoportable que empeora drásticamente al menor movimiento", "Hinchazón masiva y tensión visible en la articulación debido a la acumulación de pus (derrame articular)", "La piel sobre la articulación se vuelve muy roja y notablemente caliente al tacto", "Incapacidad total para soportar peso sobre la extremidad o para moverla voluntariamente"] }, { name: "Síntomas Sistémicos", items: ["Fiebre alta, a menudo acompañada de escalofríos y temblores", "Sensación de malestar general, fatiga extrema, debilidad y letargo (especialmente en niños pequeños y ancianos)"] } ], warning: "El dolor articular acompañado de fiebre nunca debe ignorarse. Es artritis séptica hasta que se demuestre lo contrario. La destrucción del cartílago puede comenzar a ser permanente en tan solo 24-48 horas." }, types: { title: "Causas y Vías de Infección", intro: "El agente más común es la bacteria *Staphylococcus aureus* (estafilococo). Ingresan a la articulación por:", items: ["Propagación por el torrente sanguíneo (Bacteriemia): La vía más común. Una infección en otro lugar (garganta, piel, vías urinarias) pasa a la sangre y se aloja en la articulación.", "Inoculación Directa: Una herida punzante que penetra hasta la articulación, una mordedura de animal o una inyección intraarticular (infiltración) contaminada.", "Propagación de una infección cercana: Una infección ósea subyacente (osteomielitis) que se rompe hacia la articulación.", "En jóvenes sexualmente activos, la bacteria de la gonorrea (*Neisseria gonorrhoeae*) puede causar artritis infecciosa (Artritis Gonocócica)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico debe ser inmediato para salvar la articulación:", items: ["Artrocentesis (Análisis del líquido sinovial): El procedimiento de oro y obligatorio. El médico introduce una aguja en la articulación inflamada para extraer líquido. Si hay infección, el líquido se verá espeso, amarillento y turbio (pus), con un recuento altísimo de glóbulos blancos. Se envía a cultivar para identificar la bacteria exacta.", "Análisis de sangre: Muestra signos claros de infección severa (glóbulos blancos elevados, PCR y VSG altas) y el hemocultivo detecta si la bacteria está en la sangre.", "Radiografías o Ecografías: La ecografía sirve para confirmar la presencia de líquido (derrame) en articulaciones profundas como la cadera. Las radiografías simples no muestran la infección temprana, pero sirven para ver daños óseos previos."], note: "" }, treatment: { title: "Tratamientos", intro: "La base del tratamiento es vaciar el pus tóxico y matar la bacteria con antibióticos intravenosos:", subsections: [ { title: "Manejo Médico y Quirúrgico", items: ["Drenaje Articular: Es imperativo vaciar el pus de la articulación para frenar la destrucción del cartílago y aliviar el dolor por presión. En articulaciones accesibles como la rodilla, se puede hacer con una aguja grande repetidas veces; sin embargo, en infecciones densas, de la cadera o del hombro, se requiere Lavado Artroscópico (una cirugía por cámara donde el cirujano lava intensamente toda la articulación por dentro con suero).", "Antibióticos Intravenosos (IV): Deben iniciarse en el hospital de forma inmediata, inicialmente con medicamentos de amplio espectro hasta que el cultivo indique qué antibiótico es el ideal. El tratamiento suele durar entre 2 y 6 semanas (pasando a pastillas orales hacia el final).", "Reposo Articular Inicial: Férula o inmovilización por unos días para el dolor severo, pero seguida pronto de movimientos pasivos para evitar que la articulación quede rígida de por vida."] } ], note: "Las personas con prótesis articulares (rodillas o caderas de metal) tienen mayor riesgo; una infección en una prótesis casi siempre requiere una cirugía mayor para extraer y cambiar el implante artificial." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a Urgencias de Inmediato si tú o tu hijo presentan:", items: ["Dolor severo, repentino e inexplicable en una sola articulación (como rodilla, codo o cadera) que impide cualquier movimiento", "La articulación se hincha, se enrojece rápidamente y está ardiendo al tacto", "Los síntomas articulares se acompañan de fiebre alta y malestar repentino"] } },
'Codo dislocado en niños' : { intro: "El codo dislocado en niños pequeños, conocido médicamente como 'codo de niñera' (o subluxación de la cabeza del radio), es una de las lesiones articulares más comunes y frecuentes en los primeros años de vida (típicamente entre los 1 y 4 años de edad).", whatIs: { title: "¿Qué es el Codo de Niñera?", text: "A diferencia de una dislocación completa de codo en un adulto, esta es una subluxación (desplazamiento parcial). En los niños muy pequeños, los huesos y ligamentos aún están flojos y en desarrollo. Cuando se tira bruscamente del brazo o la mano del niño, el ligamento elástico (ligamento anular) que sujeta el hueso del antebrazo (el radio) cerca del codo se resbala y queda pellizcado o atrapado en la articulación del codo. Esto causa un dolor agudo e inmediato, y el niño deja de usar el brazo por completo." }, symptoms: { title: "Síntomas y Comportamiento Típico", intro: "El cuadro clínico es extremadamente clásico y reconocible por los pediatras y médicos de urgencias:", groups: [ { name: "Signos Post-Tirón", items: ["Llanto repentino y muy fuerte justo después de un tirón del brazo, mano o muñeca", "Impotencia Funcional Funcional (Pseudoparálisis): El niño se niega absoluta y tercamente a mover o usar el brazo afectado", "Postura clásica: El niño sostiene el brazo dolorido apretado contra el costado de su vientre, con el codo ligeramente doblado (flexionado) y la palma de la mano girada hacia abajo (pronación)", "El llanto inicial puede cesar mientras el brazo permanezca quieto y apoyado, pero el niño llorará de dolor si alguien intenta moverle o examinarle el codo"] } ], warning: "A simple vista, el codo NO se ve hinchado, deformado ni con moretones. Si hay hinchazón severa, enrojecimiento o deformidad ósea clara, es probable que se trate de una fractura (como una fractura supracondílea) y no de un simple codo de niñera." }, types: { title: "Causas Frecuentes", intro: "El origen es casi siempre mecánico debido a un 'estiramiento' axial (tirón) del brazo del niño:", items: ["Levantar bruscamente al niño por las manos o muñecas (ej. para ayudarle a subir un escalón alto o acera).", "Balancear al niño sosteniéndolo por los brazos o las manos (el típico juego de 'volar').", "Tirar del brazo rápidamente para evitar que el niño se caiga o cruce la calle.", "El niño tropieza o se deja caer al suelo dejando el peso de su cuerpo colgado mientras un adulto lo sostiene de la mano.", "A veces ocurre por rodar de forma extraña sobre el brazo durante el sueño, o forcejeando para ponerle una chaqueta apretada (causas de torsión)."], note: "A partir de los 5 o 6 años, los ligamentos del niño se engrosan y fortalecen lo suficiente como para que esta lesión casi nunca vuelva a ocurrir." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico se basa por completo en la historia de lo sucedido y la postura del niño:", items: ["Evaluación clínica: El médico notará la postura característica y la ausencia de inflamación externa. A menudo no se necesita nada más.", "Radiografías (Rayos X): Generalmente NO son necesarias y de hecho resultarán 'normales' (los rayos X no ven el ligamento atrapado). Solo se solicitan si la historia del tirón no está clara, si el niño se golpeó el codo directamente, si hay mucha hinchazón (para descartar fractura de clavícula o codo), o si la maniobra de corrección falla."], note: "" }, treatment: { title: "Tratamientos", intro: "Es un problema sumamente fácil de curar por un profesional médico en cuestión de segundos:", subsections: [ { title: "Procedimiento de Reducción", items: ["Maniobra de Reducción: El médico de urgencias o pediatra realizará un movimiento rápido, muy específico y firme con la mano y el antebrazo del niño (como la hiperpronación o supinación/flexión) para liberar el ligamento pellizcado y que el hueso del radio vuelva a su anillo. A menudo, el médico sentirá un sutil 'clic' bajo su pulgar cuando el hueso regresa a su lugar.", "Alivio Inmediato: El movimiento duele un segundo y el niño llorará, pero pasados 5 a 15 minutos, el dolor desaparece casi mágicamente y el niño comenzará a jugar y usar su brazo con normalidad como si nada hubiera pasado.", "Inmovilización: No se requiere yeso, cabestrillo ni inmovilización si es un episodio agudo resuelto con éxito.", "Educación: Los padres reciben instrucciones estrictas de levantar al niño siempre por las axilas o el torso, nunca por las muñecas o antebrazos, ya que los niños que sufren esta lesión son propensos a repetirla semanas o meses después."] } ], note: "NUNCA debes intentar hacer esta maniobra por ti mismo en casa o dejar que lo haga alguien sin formación médica, podrías agravar una fractura oculta no diagnosticada." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a Urgencias o al pediatra el mismo día si:", items: ["Tu hijo llora tras un tirón de brazo y luego se niega a mover ese brazo por más de unos minutos", "El niño protege el brazo dejándolo colgado a un lado tras jugar bruscamente", "La regla es: si el niño evita usar el brazo, necesita una evaluación médica para asegurar que no hay fracturas o un codo de niñera que requiera ser recolocado"] } },
'Tumor medular' : { intro: "Un tumor medular es un crecimiento de tejido anormal en forma de masa que se desarrolla dentro o alrededor de la médula espinal, o en los huesos de la columna (vértebras). Estos tumores amenazan seriamente el sistema nervioso central debido al limitado espacio dentro del canal espinal.", whatIs: { title: "¿Qué es un Tumor Medular?", text: "La médula espinal es un tubo frágil de nervios vitales protegido por el hueso de la columna vertebral. Cualquier crecimiento tumoral en esta área estrecha (sea benigno o maligno) es peligroso, ya que a medida que la masa crece, presiona, aplasta o destruye directamente las vías nerviosas que comunican el cerebro con el resto del cuerpo. Esto provoca daños neurológicos severos que pueden llevar a la parálisis permanente." }, symptoms: { title: "Síntomas y Alertas Neurológicas", intro: "Los síntomas dependen de la ubicación del tumor a lo largo de la columna y de la velocidad de crecimiento, y a menudo progresan lentamente:", groups: [ { name: "Síntomas Primarios de Dolor", items: ["Dolor de espalda constante, sordo y profundo: Es a menudo el síntoma inicial. Es distintivo porque el dolor NO se alivia con el reposo y a menudo empeora notablemente por la noche al acostarse, interrumpiendo el sueño.", "Dolor irradiado (Radicular): Dolor agudo o descargas eléctricas que bajan por los brazos o las piernas, o alrededor del pecho y abdomen, indicando que el tumor presiona un nervio de salida."] }, { name: "Síntomas Neurológicos y Compresivos (Avanzados)", items: ["Entumecimiento, hormigueo profundo o pérdida de sensibilidad al frío y al calor en las piernas, brazos o en la zona del torso", "Debilidad muscular progresiva en brazos o piernas, provocando torpeza, caídas frecuentes o incapacidad para caminar", "Pérdida inusual del control intestinal o de la vejiga (incontinencia urinaria o fecal) debido a la compresión severa de la médula baja", "Espasticidad, rigidez o parálisis franca en etapas tardías si la médula espinal se corta o aplasta completamente"] } ], warning: "La aparición progresiva de debilidad o torpeza en las piernas, combinada con la pérdida repentina del control de la orina o heces, y un dolor de espalda nocturno, conforman una urgencia médica y neuroquirúrgica inmediata para evitar parálisis permanente." }, types: { title: "Clasificación de los Tumores", intro: "Se clasifican según su ubicación anatómica precisa respecto a la médula y las meninges (capas protectoras):", items: ["Extradurales (Vertebrales): Tumores fuera del saco protector de la médula, creciendo en los propios huesos de las vértebras. Son la abrumadora mayoría, y en adultos casi siempre son metástasis (cáncer de mama, pulmón o próstata que se propagó a los huesos de la columna).", "Intradurales - Extramedulares: Crecen dentro de la capa que cubre la médula, pero fuera de la médula en sí. Son a menudo benignos y de crecimiento lento, comprimiendo la médula desde fuera (Meningiomas, originados en las membranas, o Schwannomas/Neurofibromas, en las raíces nerviosas).", "Intramedulares: El tipo más difícil de tratar. Crecen DENTRO del propio tejido interno de la médula espinal, expandiéndola por dentro (Astrocitomas, Ependimomas)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Como ocurre con muchos tumores primarios del sistema nervioso, la causa directa es incierta:", items: ["La gran mayoría de tumores primarios aparecen sin ninguna causa clara.", "Cáncer diseminado (Metástasis): La causa de la mayoría de los tumores espinales, propagados por la sangre.", "Trastornos genéticos hereditarios predisponentes: Neurofibromatosis (Tipo 1 y Tipo 2), Enfermedad de Von Hippel-Lindau, y esclerosis tuberosa, las cuales hacen que los pacientes desarrollen múltiples tumores benignos en los nervios y la médula."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico rápido mediante neuroimagen detallada es crítico para prevenir daño permanente:", items: ["Resonancia Magnética (RM) de Columna con contraste: El estándar de oro absoluto e innegociable. Produce imágenes sumamente detalladas que muestran el tumor, la médula espinal nerviosa y el grado de compresión o daño. Es indispensable para localizar problemas intramedulares.", "Tomografía Computarizada (TC) de Columna: Excelente para ver los tumores en el hueso vertebral y el grado de destrucción ósea que compromete la estabilidad de la columna.", "Biopsia Estereotáctica o Abierta: Extraer un pedazo del tumor para examinarlo bajo el microscopio. Generalmente se hace durante la cirugía principal o con una aguja guiada por TC en tumores vertebrales."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es aliviar la presión sobre la médula espinal inmediatamente, preservar la función neurológica y tratar el tumor (extirpación o control):", subsections: [ { title: "Intervenciones Quirúrgicas y Oncológicas", items: ["Corticosteroides (Dexametasona): La primera medida de emergencia. Dosis muy altas reducen drásticamente la inflamación masiva que rodea al tumor, aliviando rápidamente la compresión de la médula e incluso revirtiendo parálisis temporalmente antes de la cirugía.", "Microcirugía de Resección: El enfoque primario para tumores primarios intramedulares e intradurales. Mediante un microscopio quirúrgico de alta potencia y monitoreo eléctrico de los nervios, el neurocirujano abre la médula o el canal y separa el tumor del tejido neural frágil. Los tumores benignos (meningiomas) a menudo se curan por completo con esto.", "Cirugía de Estabilización Vertebral: Si un tumor metastásico ha destruido la vértebra y la columna colapsa presionando los nervios, se usan tornillos, varillas de titanio y cemento óseo para estabilizar los huesos y evitar la parálisis.", "Radioterapia: Frecuentemente usada después de la cirugía para destruir restos de tumor microscópicos, o en pacientes inoperables. En metástasis dolorosas en los huesos, la radioterapia dirigida paliativa es el tratamiento de primera elección.", "Quimioterapia y Terapia Dirigida: Usadas de acuerdo al tipo celular específico del tumor, pero a menudo tienen acceso limitado debido a la barrera hematoencefálica-espinal."] } ], note: "La rehabilitación y fisioterapia neuro-motora tras la cirugía es esencial para recuperar la función y fuerza en las extremidades afectadas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita atención médica neurológica de emergencia si:", items: ["Desarrollas un dolor de espalda fuerte, continuo y nuevo que empeora claramente cuando te acuestas en la cama por la noche", "Empiezas a sentir las piernas torpes, débiles, o pierdes el equilibrio repetidas veces al caminar", "Sientes hormigueo pesado o entumecimiento en el pecho, abdomen o extremidades que no desaparece", "Pierdes la capacidad de controlar voluntariamente cuando orinas o defecas"] } },
'Síndrome de Turner' : { intro: "El síndrome de Turner es un trastorno genético que afecta exclusivamente a las mujeres, provocado por la ausencia total o parcial de un cromosoma X, lo que altera el desarrollo físico y reproductivo.", whatIs: { title: "¿Qué es el Síndrome de Turner?", text: "Las mujeres normalmente tienen dos cromosomas X (XX). En el síndrome de Turner, uno de estos cromosomas falta o está incompleto. Esta alteración genética se produce de forma aleatoria durante la formación de las células reproductoras de los padres o en las primeras etapas de la división celular del embrión, provocando baja estatura, fallos en el desarrollo de los ovarios y diversos problemas médicos y estructurales." }, symptoms: { title: "Síntomas y Características", intro: "Los signos pueden variar de leves a muy notorios, a menudo detectables al nacer o en la infancia:", groups: [ { name: "Signos Físicos y Clínicos", items: ["Baja estatura (es el síntoma más constante; sin tratamiento, la altura promedio adulta es mucho menor de lo normal)", "Cuello corto, a menudo con pliegues de piel adicionales que van desde la parte superior de los hombros hasta los lados del cuello (cuello alado o 'pterigium colli')", "Línea del cabello baja en la parte posterior de la nuca y orejas de implantación baja", "Tórax ancho con pezones muy separados", "Hinchazón (linfedema) en las manos y los pies, especialmente visible al nacer"] }, { name: "Desarrollo y Complicaciones", items: ["Fallo ovárico prematuro: los ovarios dejan de funcionar, provocando falta de desarrollo de los senos, ausencia de menstruación (amenorrea) e infertilidad casi universal", "Defectos cardíacos congénitos (especialmente problemas en la válvula aórtica o coartación de la aorta)", "Problemas renales, mayor riesgo de presión arterial alta, diabetes y problemas de tiroides"] } ], warning: "Los problemas cardíacos asociados al Síndrome de Turner pueden ser potencialmente mortales; toda niña o mujer diagnosticada debe someterse a una evaluación cardiológica exhaustiva." }, types: { title: "Tipos Genéticos", intro: "La gravedad de los síntomas a menudo depende de la genética celular:", items: ["Monosomía X: El cromosoma X falta por completo en todas las células del cuerpo (ocurre en aproximadamente la mitad de los casos).", "Mosaicismo: Algunas células tienen los dos cromosomas XX normales, mientras que otras tienen solo uno. Los síntomas suelen ser más leves.", "Anomalías del cromosoma X: Las células tienen una copia normal del cromosoma X y otra alterada o incompleta."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Puede diagnosticarse antes del nacimiento, durante la infancia o en la adolescencia:", items: ["Pruebas prenatales: Ecografía (detecta acumulación de líquido en el cuello o problemas cardíacos) o análisis de ADN fetal libre en sangre materna, confirmado por amniocentesis.", "Cariotipo: Es el análisis de sangre definitivo que se realiza tras el nacimiento. Cuenta y evalúa los cromosomas de las células para confirmar la falta o alteración del cromosoma X.", "Análisis de hormonas: Para comprobar los niveles de hormonas ováricas (FSH y LH, que suelen estar muy elevadas intentando estimular a los ovarios que no responden)."] }, treatment: { title: "Tratamientos", intro: "No existe cura genética, pero los tratamientos hormonales pueden mejorar enormemente el desarrollo físico y la calidad de vida:", subsections: [ { title: "Terapias Hormonales y Soporte", items: ["Terapia con Hormona del Crecimiento (Somatotropina): Iniciada en la infancia temprana mediante inyecciones diarias, es fundamental para aumentar la velocidad de crecimiento y lograr una estatura adulta más cercana a la normal.", "Terapia de Reemplazo de Estrógenos: Comienza alrededor de los 11 o 12 años para inducir los cambios físicos de la pubertad (desarrollo de los senos, tamaño del útero) y se mantiene hasta la edad típica de la menopausia para proteger la salud ósea.", "Tratamientos de Fertilidad: La gran mayoría de las mujeres con síndrome de Turner no pueden concebir naturalmente, pero pueden quedar embarazadas mediante fecundación in vitro (FIV) utilizando óvulos de donantes.", "Manejo Multidisciplinario: Controles regulares con cardiólogos, endocrinólogos, otorrinolaringólogos y apoyo psicológico."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un pediatra o endocrinólogo infantil si:", items: ["Notas que tu hija crece a un ritmo mucho más lento que las niñas de su edad", "No presenta signos de pubertad al llegar a la adolescencia (12-13 años) o no tiene su primer periodo menstrual a los 15 años", "Observas las características físicas típicas como cuello ancho o hinchazón inusual en manos y pies"] } },
'Poliquistosis ovárica' : { intro: "La poliquistosis ovárica, mundialmente conocida como Síndrome de Ovario Poliquístico (SOP), es el trastorno endocrino y metabólico más común en mujeres en edad reproductiva. Provoca desequilibrios hormonales severos que afectan la menstruación, la fertilidad y la apariencia física.", whatIs: { title: "¿Qué es el SOP?", text: "A pesar de su nombre, no se trata simplemente de 'quistes' en los ovarios. De hecho, los folículos (sacos llenos de líquido donde crecen los óvulos) no maduran lo suficiente como para liberar un óvulo, por lo que la ovulación se detiene o es muy irregular. Estos folículos inmaduros se acumulan en los ovarios, dándoles un aspecto 'poliquístico' en la ecografía. El verdadero problema central es una producción anormalmente alta de andrógenos (hormonas masculinas) y una fuerte resistencia a la insulina en el cuerpo de la mujer." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas suelen comenzar alrededor de la época de la primera menstruación o al ganar mucho peso:", groups: [ { name: "Irregularidades Reproductivas", items: ["Periodos menstruales muy irregulares, infrecuentes (oligomenorrea) o ausencia total de la menstruación (amenorrea)", "Sangrados inusualmente abundantes cuando finalmente ocurre el periodo", "Infertilidad o gran dificultad para quedar embarazada debido a la falta de ovulación"] }, { name: "Signos por Exceso de Andrógenos (Hormonas Masculinas)", items: ["Hirsutismo: Crecimiento excesivo y grueso de vello en zonas típicamente masculinas (cara, barbilla, pecho, abdomen o espalda)", "Acné severo, persistente o que aparece en la edad adulta (especialmente en la mandíbula y el cuello)", "Pérdida de cabello con patrón masculino (alopecia androgénica) o afinamiento del pelo", "Oscurecimiento y engrosamiento de la piel (acantosis nigricans) en los pliegues del cuello, ingles o debajo de los senos (un signo directo de resistencia a la insulina)"] } ], warning: "El SOP no es solo un problema de fertilidad; es una afección metabólica profunda que aumenta enormemente el riesgo de desarrollar diabetes tipo 2, presión arterial alta, apnea del sueño y cáncer de endometrio a largo plazo si no se controla." }, types: { title: "Causas y Factores de Riesgo", intro: "Es un síndrome multifactorial, fuertemente influenciado por:", items: ["Resistencia a la insulina: Las células no responden bien a la insulina, por lo que el páncreas produce más. El exceso de insulina estimula a los ovarios a producir demasiada testosterona.", "Inflamación de bajo grado: Las mujeres con SOP tienden a tener una inflamación crónica que estimula a los ovarios a producir andrógenos.", "Genética: Tener antecedentes familiares (madre o hermanas con SOP) multiplica significativamente el riesgo de padecerlo.", "Exceso de peso u obesidad (aunque las mujeres delgadas también pueden tener SOP, el exceso de grasa empeora drásticamente la resistencia a la insulina y los síntomas)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existe una sola prueba para el SOP. Se diagnostica frecuentemente usando los 'Criterios de Rotterdam', donde deben cumplirse dos de las siguientes tres condiciones:", items: ["1. Ciclos menstruales irregulares o ausentes (anovulación).", "2. Signos físicos (exceso de vello, acné) o análisis de sangre que confirmen niveles elevados de andrógenos (testosterona libre).", "3. Ecografía pélvica que muestre ovarios agrandados con múltiples folículos inmaduros (ovarios poliquísticos).", "Además, el médico ordenará análisis de sangre para medir la glucosa, el colesterol y descartar otros problemas de tiroides o glándulas suprarrenales."] }, treatment: { title: "Tratamientos", intro: "No tiene cura, pero se controla muy bien combinando cambios en el estilo de vida y medicación según el objetivo (fertilidad, acné o regulación menstrual):", subsections: [ { title: "Opciones de Manejo General", items: ["Pérdida de peso y dieta: Es el tratamiento de primera línea y el más poderoso. Perder solo del 5 al 10% del peso corporal puede restaurar la ovulación regular, reducir los niveles de insulina y disminuir el exceso de vello.", "Píldoras anticonceptivas combinadas (estrógeno y progestina): El tratamiento principal para mujeres que no desean embarazo. Regulan el ciclo, protegen contra el cáncer de endometrio y reducen drásticamente el acné y el exceso de vello.", "Metformina: Un medicamento para la diabetes que mejora la resistencia a la insulina, ayuda a bajar los niveles de andrógenos y a reiniciar la ovulación.", "Medicamentos Antiandrógenos (como la Espironolactona): Se recetan específicamente para bloquear los efectos de la testosterona en la piel y detener el acné severo y el crecimiento de vello.", "Tratamientos de Fertilidad: Si se busca el embarazo, se recetan inductores de la ovulación (Letrozol o Clomifeno) o se recurre a la Fecundación In Vitro (FIV)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una cita con tu ginecólogo o endocrinólogo si:", items: ["Tienes menos de ocho periodos menstruales al año o tus periodos se detienen por completo sin estar embarazada", "Llevas más de un año intentando quedar embarazada sin éxito", "Notas un crecimiento repentino y excesivo de vello oscuro en tu rostro o pecho, o acné adulto incontrolable"] } },
'Deseo sexual hiperactivo' : { intro: "El deseo sexual hiperactivo, clínicamente referido como Trastorno de Comportamiento Sexual Compulsivo (o hipersexualidad), es una intensa y persistente preocupación por fantasías, impulsos y conductas sexuales que la persona siente que están fuera de su control y que causan un malestar significativo.", whatIs: { title: "¿Qué es el Comportamiento Sexual Compulsivo?", text: "A diferencia de tener un libido naturalmente alto o disfrutar del sexo frecuente, este trastorno se define por la 'compulsión' y la pérdida de control. El individuo utiliza el comportamiento sexual (ya sea pornografía, masturbación, múltiples parejas, pago por sexo o cibersexo) como un mecanismo de escape para lidiar con el estrés, la ansiedad, la depresión o el vacío emocional. Estas conductas continúan a pesar de generar graves consecuencias negativas, como la ruina financiera, la destrucción del matrimonio, pérdida de empleo o riesgos para la salud física." }, symptoms: { title: "Síntomas y Señales de Conducta", intro: "Las señales de que la sexualidad se ha vuelto una compulsión destructiva incluyen:", groups: [ { name: "Patrones de Pensamiento y Acción", items: ["Impulsos y fantasías sexuales crónicas y muy intensas que consumen tanto tiempo que interfieren con las responsabilidades diarias y el trabajo", "Sentirse impulsado a realizar ciertos comportamientos sexuales y luego sentir una profunda vergüenza, culpa o remordimiento justo después de hacerlo", "Hacer intentos repetidos, pero infructuosos, de reducir, controlar o detener las conductas sexuales o el consumo de pornografía", "Usar el comportamiento sexual como una forma de escapar de otros problemas, como la soledad, la tristeza, la ira o el estrés", "Participar en actividades sexuales peligrosas, de alto riesgo, o ilegales sin importar las consecuencias para uno mismo o para los demás"] } ], warning: "Si los impulsos sexuales compulsivos involucran prácticas no consensuadas o ilegales, el riesgo social y legal es extremo y requiere intervención psiquiátrica y legal urgente." }, types: { title: "Causas y Factores Desencadenantes", intro: "El origen de la hipersexualidad es complejo y a menudo combina factores neurológicos y psicológicos:", items: ["Desequilibrios químicos cerebrales: Niveles altos de sustancias químicas vinculadas a las vías de recompensa y placer del cerebro (dopamina, serotonina y norepinefrina).", "Enfermedades Neurológicas: Condiciones que afectan partes del cerebro que controlan el comportamiento (como la demencia frontotemporal, epilepsia, tumores cerebrales o lesiones en la cabeza).", "Efecto secundario de medicamentos: Algunos medicamentos, especialmente los que se usan para tratar la enfermedad de Parkinson (agonistas de la dopamina), pueden causar un comportamiento sexual compulsivo repentino.", "Trauma y factores psicológicos: Historial de abuso físico, emocional o sexual en la infancia, así como trastornos concurrentes como depresión severa, TDAH o adicción a sustancias."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es diagnosticado por un psicólogo o psiquiatra especializado en adicciones y trastornos sexuales:", items: ["Entrevista clínica exhaustiva: El profesional evaluará detalladamente los patrones de comportamiento, su frecuencia, los detonantes emocionales y el grado de impacto destructivo en la vida del paciente.", "Cuestionarios y escalas de evaluación estandarizadas para el comportamiento sexual compulsivo.", "Evaluación psiquiátrica completa para diagnosticar posibles trastornos concurrentes (ansiedad, trastorno bipolar, abuso de drogas).", "Examen médico o neurológico (si se sospecha que la causa es un medicamento o una lesión cerebral)."], note: "Es esencial una comunicación honesta y sin censura; el profesional no está ahí para juzgar moralmente, sino para tratar una condición médica." }, treatment: { title: "Tratamientos", intro: "El tratamiento es muy similar al de las adicciones a sustancias, buscando recuperar el control y establecer límites saludables:", subsections: [ { title: "Manejo Psicológico y Farmacológico", items: ["Psicoterapia (Terapia Cognitivo-Conductual - TCC): Es el pilar del tratamiento. Ayuda al paciente a identificar los desencadenantes emocionales de sus impulsos, a modificar los pensamientos que llevan a actuar de forma compulsiva y a aprender formas saludables de manejar el estrés sin recurrir al sexo.", "Terapia psicodinámica: Útil para explorar traumas profundos del pasado o conflictos emocionales inconscientes.", "Grupos de apoyo y programas de 12 pasos (como Adictos al Sexo Anónimos): Proporcionan un espacio seguro, responsabilidad y estrategias de prevención de recaídas compartidas con personas que enfrentan el mismo problema.", "Medicamentos: Se pueden recetar antidepresivos (ISRS, como fluoxetina o sertralina) para ayudar con la obsesión y la ansiedad; estabilizadores del estado de ánimo; Naltrexona (utilizada para tratar adicciones); o, en casos extremos y peligrosos, medicamentos antiandrógenos para reducir biológicamente el deseo sexual excesivo."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca ayuda psicológica o psiquiátrica inmediata si:", items: ["Sientes que has perdido completamente el control sobre tus impulsos o comportamientos sexuales", "Tus conductas sexuales están causando dolor profundo a tu pareja, arruinando tus finanzas o poniendo en riesgo tu trabajo", "Tus impulsos te están llevando a involucrarte en comportamientos sexuales altamente arriesgados, sin protección o ilegales", "Te sientes deprimido, desesperado o tienes pensamientos suicidas a causa de tu comportamiento"] } },
'Infección viral de las vías respiratorias bajas' : { intro: "Una infección viral de las vías respiratorias bajas es una enfermedad inflamatoria que afecta la parte inferior del sistema respiratorio, es decir, la tráquea, los bronquios, los bronquiolos y los alvéolos (los sacos de aire de los pulmones).", whatIs: { title: "¿Qué son estas Infecciones?", text: "A diferencia de un resfriado común que se queda en la nariz y la garganta (vías altas), estos virus descienden hacia el pecho. Al invadir las células pulmonares, los virus provocan inflamación, hinchazón y producción excesiva de moco. Esto estrecha las vías respiratorias y dificulta el paso del oxígeno a la sangre. Las formas más comunes de estas infecciones son la bronquitis aguda, la bronquiolitis (típicamente en bebés) y la neumonía viral." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas reflejan la irritación y obstrucción pulmonar:", groups: [ { name: "Síntomas Respiratorios Severos", items: ["Tos intensa y persistente, que a menudo comienza seca pero luego produce flema o moco (claro, blanco o amarillento)", "Sibilancias (un silbido agudo o 'pitido' al exhalar el aire)", "Dificultad para respirar (disnea) o sensación de opresión y dolor sordo en el pecho", "Respiración anormalmente rápida (taquipnea), muy notoria en bebés y niños pequeños", "Fiebre (que puede variar de baja a muy alta), escalofríos y fatiga generalizada", "Tiraje: En bebés, se nota cómo la piel se hunde entre las costillas o debajo del cuello al hacer esfuerzo para respirar"] } ], warning: "Si la inflamación es lo suficientemente severa como para impedir que el oxígeno llegue a la sangre, la piel o los labios pueden volverse de color azulado o grisáceo (cianosis), lo cual es una emergencia médica inmediata." }, types: { title: "Causas y Virus Culpables", intro: "Múltiples virus pueden bajar a los pulmones, siendo los más comunes:", items: ["Virus Sincitial Respiratorio (VSR): Es la causa número uno de bronquiolitis y neumonía viral en bebés menores de un año, y también muy peligroso para adultos mayores.", "Virus de la Influenza (Gripe): Una causa principal de neumonía viral aguda durante los meses de invierno.", "Coronavirus (incluyendo SARS-CoV-2 / COVID-19): Puede causar neumonía severa y síndrome de dificultad respiratoria aguda.", "Rinovirus, Adenovirus y Metaneumovirus humano.", "Factores de riesgo que empeoran la infección: Fumar, exposición al humo de segunda mano, asma subyacente, edad muy temprana (prematuros) o avanzada, y sistemas inmunes debilitados."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico evalúa la función pulmonar y busca descartar bacterias:", items: ["Auscultación con estetoscopio: El médico escuchará sonidos crujientes (estertores), sibilancias o disminución del paso de aire en los pulmones.", "Oximetría de pulso: Un sensor indoloro en el dedo para medir los niveles de oxígeno en sangre.", "Hisopado nasal o faríngeo: Pruebas rápidas o PCR para identificar exactamente qué virus está causando el problema (como VSR, Gripe o COVID).", "Radiografía de tórax: Se utiliza para determinar si la infección ha progresado a neumonía y para asegurar que no haya complicaciones como líquido alrededor del pulmón."], note: "Los antibióticos NO curan las infecciones virales, por lo que es vital confirmar que no es una infección bacteriana." }, treatment: { title: "Tratamientos", intro: "El tratamiento es de soporte, enfocado en ayudar al paciente a respirar y aliviar los síntomas mientras el sistema inmunológico elimina el virus:", subsections: [ { title: "Manejo Médico y de Soporte", items: ["Hidratación y Reposo: Beber muchos líquidos ayuda a aflojar el moco denso para que pueda toserse más fácilmente.", "Oxigenoterapia: En casos graves donde el nivel de oxígeno en la sangre es bajo, se suministra oxígeno mediante cánulas nasales o mascarilla en el hospital.", "Broncodilatadores: Inhaladores o nebulizaciones (como el Albuterol/Salbutamol) se usan para relajar y abrir las vías respiratorias si hay sibilancias o antecedentes de asma.", "Medicamentos Antivirales: Fármacos específicos (como Oseltamivir para la gripe, o Paxlovid para COVID-19) pueden acortar la enfermedad si se inician en los primeros dos días.", "Antipiréticos: Paracetamol o Ibuprofeno para controlar la fiebre y el dolor de pecho (nunca aspirina en niños).", "Soporte respiratorio avanzado: Los bebés con VSR severo o adultos con neumonía viral crítica pueden requerir ingreso en UCI para ventilación mecánica (intubación)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias o llama al 911 si tú o tu hijo presentan:", items: ["Dificultad evidente y severa para respirar, o incapacidad para decir una frase completa sin detenerse a tomar aire", "Coloración azulada en los labios, el rostro o las uñas", "Letargo profundo, confusión extrema, o si un bebé deja de orinar o alimentarse por el esfuerzo de respirar", "El pecho se hunde profundamente al respirar o las fosas nasales se abren exageradamente (aleteo nasal)"] } },
'Displasia del desarrollo de la articulación de la cadera' : { intro: "La displasia del desarrollo de la cadera (DDC) es una afección pediátrica frecuente en la cual la articulación de la cadera no se forma ni encaja correctamente. El problema puede estar presente al nacer o desarrollarse durante el primer año de vida del bebé.", whatIs: { title: "¿Qué es la Displasia de Cadera?", text: "La articulación de la cadera es como una bola (cabeza del fémur) que encaja en un enchufe o cavidad cóncava (el acetábulo en la pelvis). En la DDC, la cavidad de la pelvis es demasiado plana o poco profunda. Debido a esto, la bola del fémur está suelta y puede resbalar parcialmente fuera del enchufe (subluxación) o deslizarse por completo fuera de él (luxación). Si no se corrige a tiempo, los huesos crecen deformados, provocando cojera permanente, piernas de diferente longitud y artritis severa y dolorosa en la edad adulta temprana." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los bebés no sienten dolor por la DDC. Las señales son físicas y asimétricas:", groups: [ { name: "Signos en Bebés y Recién Nacidos", items: ["Asimetría en los pliegues de la piel de los muslos o glúteos (un lado tiene más pliegues o son más profundos que el otro)", "Una pierna parece visiblemente más corta que la otra", "Movilidad reducida o rigidez en una cadera (por ejemplo, al cambiar el pañal, una pierna no se abre hacia afuera con tanta facilidad como la otra)", "Un sonido o sensación de 'clic' o 'pop' (chasquido) perceptible cuando el pediatra mueve o abre las caderas del bebé"] }, { name: "Signos en Niños Mayores (Que ya caminan)", items: ["Cojera notable al caminar o balanceo anormal (marcha de pato) si ambas caderas están afectadas", "Caminar de puntillas en un pie para compensar que esa pierna es más corta", "Curvatura exagerada de la columna (lordosis) y prominencia de los glúteos"] } ], warning: "El diagnóstico tardío (después de que el niño comienza a caminar) requiere cirugías complejas de reconstrucción ósea; la detección en los primeros meses de vida permite tratamientos simples y no invasivos." }, types: { title: "Causas y Factores de Riesgo", intro: "Aunque la causa exacta es desconocida, influyen fuertemente la genética y el entorno uterino:", items: ["Presentación de nalgas: El factor de riesgo mecánico más alto. Si el bebé estuvo sentado o con los pies hacia abajo en el útero durante las últimas semanas de embarazo, las caderas sufren presión anormal.", "Antecedentes familiares (padres o hermanos que tuvieron displasia de cadera o requirieron prótesis de cadera muy jóvenes).", "Ser el primer hijo (el útero de la madre está más apretado).", "Sexo femenino: Las niñas tienen hasta 4 o 5 veces más probabilidades de padecerlo debido a que responden a las hormonas relaxinas de la madre, haciendo que sus propios ligamentos sean más elásticos y la cadera más inestable.", "Falta de líquido amniótico (oligohidramnios) durante el embarazo.", "Prácticas de envoltura (swaddling): Envolver fuertemente a los bebés con las piernas rectas y juntas empeora la displasia; los bebés siempre deben tener espacio para doblar las rodillas como 'ranitas'."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La DDC se busca activamente en todas las revisiones del niño sano:", items: ["Maniobras de Barlow y Ortolani: El pediatra examina físicamente al recién nacido moviendo y abriendo sus piernas. Estas maniobras buscan sentir físicamente si la bola del fémur se sale y vuelve a entrar en la cavidad con un chasquido palpable.", "Ecografía de Cadera: Es la prueba de oro para bebés menores de 6 meses (antes de que los huesos se calcifiquen por completo). Es segura, utiliza sonido y permite ver perfectamente el cartílago, la profundidad de la cavidad y si el hueso está bien colocado.", "Radiografías (Rayos X): Se utilizan en bebés mayores de 6 meses y niños, ya que sus huesos ya están lo suficientemente calcificados para verse bien en los rayos X."], note: "Se recomienda una ecografía de cadera de rutina a las 6 semanas de vida para TODOS los bebés que nacieron de nalgas o que tienen antecedentes familiares." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende completamente de la edad del niño; cuanto más pequeño, más fácil:", subsections: [ { title: "Manejo Ortopédico y Quirúrgico", items: ["Arnés de Pavlik (0 a 6 meses de edad): Es el tratamiento estándar y altamente exitoso. Es un dispositivo de correas suaves que mantiene las piernas del bebé separadas y dobladas (como una rana). Esta postura fuerza a la bola a empujar constantemente contra el fondo de la cavidad, moldeándola para que crezca profunda y normal. Se usa de 1 a 3 meses.", "Reducción Cerrada y Yeso Espica (6 a 18 meses): Si el arnés no funciona o el niño es mayor, el traumatólogo coloca el hueso en su sitio bajo anestesia general (sin abrir con bisturí) y coloca un yeso que cubre desde el torso hasta las piernas para mantener la cadera fija durante varios meses.", "Reducción Abierta (Cirugía, niños mayores de 18 meses): El cirujano debe abrir la cadera con bisturí para limpiar el tejido cicatricial, colocar el hueso en la cavidad y a menudo cortar y reposicionar los huesos de la pelvis o el fémur (osteotomía) para que encajen. Se sigue de un yeso espica."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama la atención de tu pediatra de inmediato si:", items: ["Notas que un muslo de tu bebé tiene más pliegues de grasa que el otro", "Una de las piernas parece no abrirse tan fácilmente hacia afuera como la otra al cambiarle el pañal", "Al bañar al bebé, sientes o escuchas un crujido mecánico al moverle las piernas", "Tu niño mayor camina con cojera o favorece claramente una pierna"] } },
'Disfunción de la trompa de Eustaquio' : { intro: "La disfunción de la trompa de Eustaquio es un problema auditivo y de presión muy común en el cual el pequeño canal que conecta el oído medio con la parte posterior de la garganta no se abre o no se cierra correctamente.", whatIs: { title: "¿Qué es la Trompa de Eustaquio y su Disfunción?", text: "La trompa de Eustaquio normalmente está cerrada, pero se abre por fracciones de segundo cuando tragamos, masticamos o bostezamos. Esta acción permite que el aire entre al oído medio para igualar la presión a ambos lados del tímpano y drena los fluidos hacia la garganta. Si las paredes de esta trompa se inflaman (se hinchan) o se bloquean con mucosidad, la trompa queda sellada. Esto crea un vacío (presión negativa) en el oído medio que chupa el tímpano hacia adentro, causando dolor, amortiguación del sonido y acumulación de líquido." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas simulan la sensación de cuando desciende un avión, pero de forma persistente:", groups: [ { name: "Síntomas Otológicos", items: ["Sensación constante de taponamiento, plenitud o de tener los oídos 'llenos de agua'", "Pérdida temporal de audición o audición amortiguada y lejana", "Dolor en los oídos o una sensación de presión incómoda y profunda", "Zumbidos, silbidos o ruidos en los oídos (Tinnitus)", "Sensación de estallido, crujidos o 'clics' al tragar o bostezar", "Mareos leves o problemas sutiles de equilibrio"] } ], warning: "Si la disfunción persiste durante mucho tiempo, el líquido atrapado en el oído medio se infectará (otitis media), o la presión negativa crónica retraerá tanto el tímpano que puede adherirse a los huesecillos o perforarse." }, types: { title: "Causas y Factores Desencadenantes", intro: "La trompa suele bloquearse por inflamación o cambios mecánicos:", items: ["Infecciones virales: El resfriado común o la gripe inflaman la nariz y la garganta, cerrando la trompa.", "Alergias (Rinitis alérgica): La causa principal de inflamación crónica de las mucosas y aumento de secreciones.", "Infecciones de los senos paranasales (sinusitis crónicas).", "Cambios rápidos de presión barométrica: Volar en avión, bucear o subir a montañas altas (barotrauma).", "Agrandamiento de las adenoides: Muy común en niños. Este tejido linfático puede crecer tanto que bloquea físicamente la apertura de las trompas en la garganta.", "Reflujo gastroesofágico severo: El ácido que llega a la garganta irrita la abertura de la trompa."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es clínico y audiológico:", items: ["Otoscopia: El médico (general u otorrino) usa un instrumento con luz para mirar dentro del oído. Observará si el tímpano está retraído (succionado hacia adentro), enrojecido o si hay burbujas y líquido atrapado detrás de él.", "Timpanometría: Una prueba rápida e indolora que mide cómo reacciona el tímpano a los cambios de presión del aire en el canal auditivo, confirmando inmediatamente si hay presión negativa rígida en el oído medio.", "Pruebas de audición (Audiometría) si la pérdida de audición es persistente."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es desinflamar la mucosa y forzar la apertura del conducto para igualar la presión:", subsections: [ { title: "Medidas Caseras y Manejo Médico", items: ["Ejercicios simples: Masticar chicle, bostezar forzadamente, tragar líquidos o usar dispositivos de inflado nasal por globos (Otovent) para abrir mecánicamente la trompa.", "Maniobra de Valsalva: Taparse la nariz, cerrar la boca y soplar aire suavemente hacia los oídos para forzar la apertura de las trompas.", "Medicamentos Descongestionantes: Sprays nasales (como la oximetazolina) o pastillas (pseudoefedrina) reducen la hinchazón rápidamente, pero los sprays no deben usarse más de 3 días.", "Corticosteroides Nasales (ej. Fluticasona): Muy eficaces para desinflamar las trompas si la causa subyacente es la rinitis alérgica crónica.", "Antihistamínicos: Si las alergias son el desencadenante principal."] }, { title: "Intervenciones Quirúrgicas (Casos Crónicos)", items: ["Miringotomía y tubos de ventilación (Diábolos): Si el líquido no drena durante meses, el otorrino hace un pequeño agujero en el tímpano y coloca un minúsculo tubo plástico. Esto ventila artificialmente el oído desde afuera mientras la trompa sana por dentro.", "Dilatación con globo de la trompa de Eustaquio: Un procedimiento moderno donde el cirujano inserta un pequeño globo por la nariz hasta la trompa y lo infla para ensancharla físicamente."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico de cabecera o a un otorrino si:", items: ["La sensación de oídos taponados o pérdida de audición dura más de un par de semanas después de un resfriado", "Sientes dolor de oído intenso o te sale supuración líquida, sangre o pus por el canal auditivo", "Tus síntomas empeoran con fiebre alta"] } },
'Hernia diafragmática' : { intro: "Una hernia diafragmática es una anomalía médica grave en la que existe una abertura o desgarro en el diafragma, la capa de músculo fuerte que separa la cavidad del pecho (donde están los pulmones y el corazón) de la cavidad abdominal (donde están los intestinos, el estómago y el hígado).", whatIs: { title: "¿Qué es una Hernia Diafragmática?", text: "A través de este agujero anormal, los órganos abdominales (como el intestino, el estómago, el bazo o el hígado) son succionados hacia arriba y penetran en la cavidad torácica. Esto representa una amenaza letal de dos formas: primero, el intestino puede torcerse y morir (estrangulación); y segundo, los órganos abdominales ocupan el espacio destinado a los pulmones, aplastándolos y dificultando gravemente la respiración." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los síntomas dependen totalmente de si la hernia es de nacimiento (congénita) o adquirida de adulto:", groups: [ { name: "En Recién Nacidos (Hernia Congénita - Emergencia)", items: ["Dificultad extrema para respirar inmediatamente después del nacimiento (respiración rápida, quejidos)", "Cianosis (coloración azul o púrpura intensa en la piel y los labios por falta crítica de oxígeno)", "Ritmo cardíaco muy acelerado (taquicardia)", "El abdomen del bebé se ve inusualmente plano o hundido (porque los órganos están arriba en el pecho)", "El médico escucha sonidos intestinales en el pecho y menos sonidos respiratorios en uno de los pulmones (generalmente el izquierdo)"] }, { name: "En Adultos (Hernia Adquirida/Traumática)", items: ["Falta de aliento severa tras un traumatismo en el abdomen o el pecho", "Dolor intenso en el pecho o el abdomen que puede irradiarse al hombro", "Náuseas agudas, vómitos, incapacidad para evacuar o tragar, y ruidos intestinales escuchados en el pecho"] } ], warning: "La hernia diafragmática congénita (HDC) es una emergencia pediátrica letal, ya que los pulmones del bebé no pudieron crecer ni desarrollarse en el útero al estar aplastados por los intestinos (hipoplasia pulmonar)." }, types: { title: "Tipos por Origen", intro: "Existen dos orígenes fundamentales:", items: ["Hernia Diafragmática Congénita (HDC): El diafragma no se cierra correctamente en el feto alrededor de la octava semana de embarazo. El 80% ocurre en el lado izquierdo. A menudo se acompaña de otros defectos de nacimiento graves (corazón, cerebro).", "Hernia Diafragmática Adquirida (Traumática): Ocurre en adultos debido a traumatismos cerrados y contundentes muy violentos (accidentes automovilísticos, caídas desde gran altura) o traumatismos penetrantes (puñaladas o disparos que atraviesan el diafragma)."], note: "No debe confundirse con la Hernia de Hiato (hiatal), una afección mucho menos grave donde parte del estómago sube por el orificio natural del esófago." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico suele ser visual mediante imágenes:", items: ["Ecografía Prenatal: La HDC suele detectarse antes del nacimiento durante el ultrasonido rutinario del segundo trimestre. El médico ve el estómago o el intestino flotando junto al corazón del feto.", "Radiografía de Tórax: La prueba principal post-parto o tras un accidente. Muestra los intestinos llenos de aire o líquido ocupando el espacio del pulmón en la caja torácica.", "Tomografía Computarizada (TC): Se usa a menudo en adultos tras un accidente para confirmar el desgarro del músculo diafragmático.", "Gasometría arterial: Para medir la severidad de la falta de oxígeno en sangre."], note: "" }, treatment: { title: "Tratamientos", intro: "Toda hernia diafragmática requiere intervención quirúrgica para devolver los órganos a su sitio y cerrar el diafragma:", subsections: [ { title: "Manejo Neonatal (HDC)", items: ["Soporte Vital Inmediato: Al nacer, el bebé debe ser intubado (se inserta un tubo respiratorio en la tráquea y se conecta a un respirador) inmediatamente. No se usa mascarilla, ya que bombearía aire a los intestinos en el pecho, aplastando más el pulmón.", "ECMO (Oxigenación por Membrana Extracorpórea): Si los pulmones del bebé están demasiado subdesarrollados para oxigenar la sangre incluso con un respirador, se usa una máquina de bypass corazón-pulmón compleja como soporte vital extremo.", "Cirugía de Reparación: Una vez que el bebé es estable (a menudo días después de nacer), los cirujanos infantiles devuelven los órganos al abdomen y cosen el agujero del diafragma, a menudo usando un parche de material sintético (Gore-Tex)."] }, { title: "Manejo en Adultos", items: ["Cirugía de Emergencia (Laparotomía o Toracotomía): Se reubican los órganos estrangulados en el abdomen, se repara el tejido intestinal dañado y se sutura el desgarro del diafragma muscular."] } ], note: "Los bebés que sobreviven a la HDC a menudo enfrentan problemas de salud a largo plazo, como asma, reflujo crónico y problemas de desarrollo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es un evento de emergencia absoluta:", items: ["En el embarazo, si se diagnostica HDC, debes ser derivada inmediatamente a un centro médico de alta complejidad especializado en medicina fetal y UCI neonatal para planificar el parto", "En un adulto, si tras sufrir un accidente grave de tráfico o golpe empiezas a sufrir falta de aire extrema, dolor de pecho y náuseas, llama al 911 indicando el traumatismo"] } },
'Perforación gastrointestinal' : { intro: "La perforación gastrointestinal es la formación de un orificio completo en la pared de cualquier parte del tracto digestivo (estómago, intestino delgado o grueso). Es una emergencia médica y quirúrgica potencialmente letal.", whatIs: { title: "¿Qué es una Perforación Gastrointestinal?", text: "Normalmente, el tracto digestivo es un tubo cerrado. Si se forma un agujero, los contenidos altamente tóxicos (ácido estomacal, bacterias, bilis y heces) se derraman en la cavidad abdominal estéril. Esto provoca una inflamación masiva (peritonitis) y una infección fulminante que puede pasar rápidamente a la sangre (septicemia) y causar un shock mortal." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los síntomas aparecen de forma abrupta y brutal:", groups: [ { name: "Síntomas Abdominales Severos", items: ["Dolor abdominal repentino, agudo e insoportable que empeora con cualquier movimiento", "Abdomen 'en tabla': la barriga se vuelve rígida, dura como una piedra al tacto y extremadamente sensible", "Náuseas intensas y vómitos", "Fiebre alta, escalofríos y temblores", "Falta de aire, latidos cardíacos rápidos y debilidad extrema (signos de shock séptico)"] } ], warning: "Una perforación intestinal nunca se cura sola. El dolor agudo que causa un abdomen rígido es motivo de llamada inmediata a emergencias (911)." }, causes: { title: "Causas y Factores de Riesgo", intro: "El orificio puede ser provocado por enfermedades inflamatorias o traumatismos:", items: ["Úlceras pépticas graves (en estómago o duodeno) que atraviesan la pared celular", "Apendicitis aguda que no se opera a tiempo y se rompe", "Diverticulitis severa (bolsas en el colon que se infectan y estallan)", "Enfermedad inflamatoria intestinal (Crohn o Colitis Ulcerosa)", "Trauma físico (herida de bala, puñalada o golpe fuerte en el abdomen)", "Complicación de un procedimiento médico (como una colonoscopia o endoscopia superior)", "Ingestión de cuerpos extraños afilados o ácidos corrosivos"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico debe ser extremadamente rápido en la sala de urgencias:", items: ["Radiografía simple de tórax o abdomen (detecta 'aire libre' atrapado debajo del diafragma, lo que confirma que el tubo digestivo tiene un agujero)", "Tomografía Computarizada (TC) de abdomen y pelvis con contraste (la prueba más precisa para ver la ubicación exacta del agujero y la extensión de la peritonitis)", "Análisis de sangre (mostrarán una elevación extrema de glóbulos blancos y marcadores de infección masiva)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere reanimación inmediata seguida de cirugía de urgencia:", subsections: [ { title: "Manejo Quirúrgico y Médico", items: ["Cirugía de Emergencia (Laparotomía): El cirujano abre el abdomen para cerrar el orificio (con puntos), extirpar la parte del intestino podrida (resección intestinal) y limpiar a fondo toda la cavidad abdominal (lavado peritoneal).", "Creación de un Estoma (Colostomía/Ileostomía temporal): Frecuentemente, el intestino está demasiado inflamado para volver a unirse de forma segura. El cirujano desvía el intestino hacia la pared del abdomen hacia una bolsa externa para que sane, y lo vuelve a unir meses después.", "Antibióticos Intravenosos: Dosis masivas de amplio espectro para combatir la peritonitis y la sepsis.", "Soporte en UCI: Líquidos intravenosos, oxígeno y medicamentos para la presión arterial para tratar el shock séptico."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias sin dudarlo si:", items: ["Sientes un dolor abdominal súbito, desgarrador y que te dobla del dolor", "Tu abdomen se siente duro, rígido e intocable", "Acompañas un dolor de estómago intenso con fiebre, vómitos y confusión mental"] } },
'Dolor de cadera' : { intro: "El dolor de cadera es una queja muy común que no siempre se origina en la articulación de la cadera misma. Dependiendo de qué lo cause, el dolor puede sentirse en la ingle, el muslo, la parte exterior del glúteo o incluso irradiarse hacia la rodilla.", whatIs: { title: "¿Qué es el Dolor de Cadera?", text: "La cadera es una articulación de rótula y cavidad muy estable, pero que soporta una gran carga. El dolor puede surgir del desgaste del cartílago, de los ligamentos, músculos y tendones que la rodean, o incluso de los nervios de la espalda baja (dolor referido). Determinar la ubicación exacta del dolor es la clave principal para descubrir su origen." }, symptoms: { title: "Síntomas y Localización", intro: "El lugar donde te duele indica el problema probable:", groups: [ { name: "Según la Ubicación", items: ["Dolor en el interior de la cadera o en la ingle: Generalmente indica un problema real dentro de la articulación (como Artrosis de cadera, pinzamiento o desgarro del labrum).", "Dolor en la parte exterior de la cadera, muslo o glúteo: Típicamente causado por problemas en los tejidos blandos que rodean la articulación (como Bursitis trocantérea, tendinitis o ciática de la columna).", "Dolor al cargar peso, cojera al caminar, rigidez extrema por la mañana, o pérdida del rango de movimiento para ponerse calcetines o zapatos."] } ], warning: "Si eres un adulto mayor y sientes dolor de cadera severo e imposibilidad para mover la pierna tras una caída menor, asume que es una fractura de cadera hasta que una radiografía demuestre lo contrario." }, types: { title: "Causas y Enfermedades Comunes", intro: "Los problemas varían drásticamente según la edad y la actividad:", items: ["Osteoartritis (Artrosis): La causa número uno en adultos mayores. El cartílago se desgasta y los huesos rozan (dolor profundo en la ingle).", "Bursitis Trocantérea: Inflamación de la bolsa de líquido en la parte exterior de la cadera. Duele mucho al acostarse de ese lado.", "Tendinitis o distensiones musculares: Por sobrecarga deportiva (corredores).", "Fracturas de cadera o estrés: Comunes en osteoporosis o impacto traumático.", "Necrosis avascular: Muerte del hueso de la cabeza del fémur por falta de riego sanguíneo (asociada al uso de esteroides o alcoholismo).", "Desgarro del labrum acetabular: Rotura del anillo de cartílago que sella la articulación (común en deportistas jóvenes)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista evaluará la mecánica de tu cadera:", items: ["Examen físico: El médico rotará, doblará y estirará tu pierna para ver qué movimiento exacto desencadena el dolor.", "Radiografías de la pelvis y caderas: La primera prueba para ver artritis, fracturas o espolones óseos.", "Resonancia Magnética (RM): Si las radiografías son normales, la RM revelará desgarros de tendones, inflamación de la bursa o necrosis avascular.", "Inyección de diagnóstico: Se inyecta anestesia dentro de la articulación; si el dolor desaparece, el problema está definitivamente dentro de la cadera."], note: "" }, treatment: { title: "Tratamientos", intro: "Varía desde el reposo hasta el reemplazo articular:", subsections: [ { title: "Opciones de Manejo Escalonado", items: ["Reposo y Modificación: Evitar dormir sobre el lado dolorido, no correr y usar hielo/calor.", "Fisioterapia: Ejercicios para fortalecer los músculos alrededor de la cadera (glúteos y core) para descargar la articulación.", "Medicamentos: Analgésicos y AINEs (Ibuprofeno, Meloxicam) para la inflamación.", "Infiltraciones: Inyecciones de corticosteroides guiadas por ecografía directamente en la articulación o la bursa para un alivio prolongado de meses.", "Cirugía Artroscópica: Cirugía por cámara (mínimamente invasiva) para reparar desgarros del labrum o limpiar cartílago suelto.", "Reemplazo Total de Cadera (Artroplastia): Si la artrosis ha destruido la articulación y el dolor interfiere con la vida diaria, se reemplaza la articulación por una prótesis de titanio y cerámica (cirugía altamente exitosa)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o al traumatólogo de inmediato si:", items: ["No puedes mover la pierna o eres incapaz de soportar peso sobre ella", "El dolor es agudo, repentino, y tu pierna se ve acortada o girada en un ángulo extraño", "El dolor de cadera está acompañado de fiebre, enrojecimiento y calor local (posible infección articular)"] } },
'Absceso intraabdominal' : { intro: "Un absceso intraabdominal es una acumulación localizada de pus infectado dentro de la cavidad abdominal. Es una complicación grave que requiere drenaje médico inmediato y antibióticos.", whatIs: { title: "¿Qué es un Absceso Intraabdominal?", text: "Se forma como un mecanismo de defensa del cuerpo. Cuando ocurre una infección, una ruptura intestinal o una fuga tras una cirugía en el abdomen, el sistema inmunológico intenta contener la infección envolviéndola en una cápsula de tejido fibroso para evitar que se propague por toda la cavidad (lo que causaría peritonitis fatal). El resultado es un 'saco' lleno de bacterias vivas y muertas, glóbulos blancos y tejido destruido (pus) que los antibióticos por sí solos no pueden penetrar." }, symptoms: { title: "Síntomas y Alertas", intro: "Los síntomas pueden ser engañosos al principio, pero empeoran progresivamente:", groups: [ { name: "Signos Infecciosos y Abdominales", items: ["Fiebre persistente, a menudo con picos altos, escalofríos y sudores nocturnos", "Dolor sordo y constante en una zona específica del abdomen (donde se ubica el absceso)", "Hinchazón abdominal, náuseas, vómitos y pérdida total del apetito", "Debilidad generalizada, fatiga extrema y pérdida de peso", "Alteraciones intestinales (diarrea o incapacidad para evacuar)"] } ], warning: "Un absceso que se rompe libera pus de golpe en toda la cavidad abdominal, provocando un shock séptico que puede matar al paciente en horas si no se opera." }, types: { title: "Causas y Origen", intro: "El pus no aparece de la nada; el absceso siempre es secundario a otro problema:", items: ["Complicación posquirúrgica: La causa más común (fuga en la sutura de los intestinos tras una cirugía de colon o estómago).", "Apendicitis perforada: El apéndice estalla y el cuerpo aísla la infección formando un absceso a su alrededor.", "Diverticulitis complicada: Infección grave de las bolsas del colon que forma abscesos pélvicos.", "Enfermedad Inflamatoria Intestinal (Enfermedad de Crohn).", "Infección de la vesícula biliar o del páncreas (pancreatitis severa).", "Enfermedad inflamatoria pélvica en mujeres (absceso tubo-ovárico)."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamental encontrar la ubicación exacta del absceso:", items: ["Tomografía Computarizada (TC) del abdomen con contraste: Es el método definitivo. Muestra el tamaño, la ubicación exacta y si hay más de una bolsa de pus.", "Ecografía abdominal: Menos precisa que la TC por los gases intestinales, pero útil y rápida en pacientes delgados o mujeres embarazadas.", "Análisis de sangre: Muestran recuentos de glóbulos blancos muy elevados e inflamación generalizada (PCR alta)."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere vaciar mecánicamente el pus, ya que los antibióticos no pueden atravesar la gruesa pared del absceso:", subsections: [ { title: "Drenaje y Manejo Infeccioso", items: ["Drenaje Percutáneo Guiado por Imagen: Es el tratamiento de primera línea moderno. Un radiólogo intervencionista inserta una aguja fina y un tubo de plástico (catéter) a través de la piel directamente hasta el absceso, guiándose con el escáner TC o ecografía. El pus drena en una bolsa externa durante días hasta vaciarse.", "Cirugía Abierta o Laparoscópica: Si el absceso es inaccesible con aguja, si hay múltiples abscesos complejos, o si el drenaje percutáneo falla, un cirujano debe abrir el abdomen para limpiar físicamente todo el pus y reparar el daño intestinal original.", "Antibióticos Intravenosos (IV): Obligatorios de inmediato y administrados durante semanas para evitar que la infección pase a la sangre (sepsis).", "Apoyo nutricional intravenoso si el paciente no puede comer debido a la gravedad abdominal."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención hospitalaria urgente si:", items: ["Tienes fiebre constante que no cede con medicamentos básicos, especialmente si te operaron del abdomen hace unas semanas", "Sientes un bulto doloroso o una zona de sensibilidad extrema en el vientre", "El dolor abdominal va en aumento continuo acompañado de vómitos y letargo"] } },
'Laringotraqueobronquitis aguda' : { intro: "La laringotraqueobronquitis aguda, universalmente conocida como 'crup', es una infección respiratoria viral muy frecuente en niños pequeños que causa hinchazón en las cuerdas vocales (laringe) y la tráquea, obstruyendo la respiración.", whatIs: { title: "¿Qué es el Crup?", text: "El crup afecta principalmente a niños entre los 6 meses y los 3 años, porque sus vías respiratorias son diminutas. Cuando un virus infecta esta zona, el tejido se hincha y estrecha el paso del aire. Esto provoca el síntoma característico del crup: una tos estridente y metálica que suena exactamente como el ladrido de un perro o una foca, y un ruido agudo al tomar aire." }, symptoms: { title: "Síntomas y Evolución", intro: "La enfermedad suele comenzar como un resfriado leve, pero empeora bruscamente, sobre todo de noche:", groups: [ { name: "Síntomas Respiratorios Clásicos", items: ["Tos perruna o de foca (tos áspera, seca y metálica)", "Estridor inspiratorio (un ruido agudo y rasposo que hace el niño al INHALAR, cuando el aire pasa a la fuerza por la garganta estrecha)", "Ronquera aguda al hablar o llorar", "Fiebre baja a moderada y congestión nasal", "Los síntomas siempre son drásticamente peores por la noche y suelen mejorar por la mañana, durando de 3 a 5 noches"] } ], warning: "Si el estridor (el ruido rasposo) se escucha incluso cuando el niño está en reposo y tranquilo, o si el niño babea y no puede tragar su propia saliva, la inflamación es severa y requiere urgencias. El babeo puede ser signo de epiglotitis, una emergencia letal." }, types: { title: "Causas y Desencadenantes", intro: "Es causado por los virus habituales del resfriado y la gripe:", items: ["Virus Parainfluenza (el causante del 75% de los casos de crup)", "Virus Sincitial Respiratorio (VSR), Adenovirus, y los virus de la influenza", "Crup Espasmódico: A veces, el niño tiene episodios de crup repentinos de madrugada sin tener fiebre o resfriado previo, causado a menudo por alergias o reflujo gástrico."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de crup es clínico; un pediatra lo reconoce al instante solo escuchando la tos:", items: ["Examen físico: Observar la respiración, el estridor y descartar otras infecciones (con cuidado de no usar depresores de lengua en la garganta para no empeorar el espasmo).", "Radiografía de cuello: Solo se pide si el caso es atípico o el médico sospecha que el niño se tragó un objeto. El crup clásico muestra un estrechamiento en forma de 'punta de lápiz' o 'campanario' en la tráquea.", "Oximetría de pulso: Para asegurar que el niño tiene buen oxígeno en la sangre."], note: "" }, treatment: { title: "Tratamientos", intro: "La gran mayoría de los casos de crup son leves y se tratan en casa. Los severos requieren reducir la inflamación urgentemente:", subsections: [ { title: "Manejo Casero y Médico", items: ["Mantener la calma: El llanto, el miedo y la agitación estrechan más la vía aérea y empeoran muchísimo el estridor. Calmar al niño es el primer tratamiento.", "Aire frío o húmedo: Llevar al niño al exterior en la noche fría o abrir el congelador para que respire aire frío, o sentarse en el baño con el vapor de una ducha caliente, relaja las cuerdas vocales temporalmente.", "Corticosteroides (Dexametasona): El tratamiento de oro médico. Una sola dosis oral o inyectable de Dexametasona reduce la inflamación de la garganta durante varios días y cura la inmensa mayoría de los casos de urgencias.", "Epinefrina Nebulizada (Adrenalina racémica): En casos graves en urgencias, el niño respira adrenalina a través de una mascarilla, lo que abre las vías respiratorias en 10-15 minutos (requiere observación hospitalaria posterior porque el efecto rebota a las dos horas)."] } ], note: "NUNCA debes darle medicamentos para la tos de venta libre a un niño con crup, no ayudan con la hinchazón y pueden ser peligrosos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias (911) o acude al hospital inmediatamente si el niño:", items: ["Hace un ruido fuerte y estridente (estridor) tanto al inhalar como al exhalar, o mientras está tranquilo y en reposo", "Babea profusamente y no puede tragar saliva, o no puede emitir sonidos", "Tiene la piel pálida, se le hunden las costillas al respirar (tiraje severo) o está inusualmente somnoliento y aletargado"] } },
'Conducto arterial persistente' : { intro: "El conducto arterial persistente (CAP) es un defecto cardíaco congénito (presente al nacer) donde un vaso sanguíneo fetal esencial no se cierra adecuadamente después de que el bebé nace.", whatIs: { title: "¿Qué es el CAP?", text: "Antes de nacer, el bebé no usa sus pulmones para respirar; recibe oxígeno de la madre. Un vaso sanguíneo grande (el conducto arterial) conecta las dos arterias principales del corazón para desviar la sangre lejos de los pulmones. Normalmente, este vaso se cierra de forma permanente en las primeras 24 a 72 horas de vida. En el CAP, el conducto permanece abierto (persistente), permitiendo que la sangre rica en oxígeno del corazón se mezcle continuamente con la sangre pobre en oxígeno en los pulmones. Esto inunda los pulmones con demasiada sangre y hace que el corazón tenga que bombear el doble de fuerte." }, symptoms: { title: "Síntomas y Señales en el Bebé", intro: "Un CAP pequeño puede no causar nunca síntomas. Un CAP grande es peligroso y causa insuficiencia cardíaca:", groups: [ { name: "Síntomas en Bebés y Niños (CAP grande)", items: ["Respiración muy rápida, pesada o dificultad para respirar, especialmente al momento de alimentarse", "Sudoración extrema durante la alimentación o el llanto", "Fatiga rápida y falta de energía", "Fallo de medro (el bebé no gana peso ni crece de forma adecuada debido al gasto masivo de calorías para respirar)", "Infecciones respiratorias inferiores muy frecuentes (neumonías o bronquitis recurrentes)"] } ], warning: "Si no se cierra, un CAP grande no tratado con los años provocará un daño irreversible en los vasos sanguíneos pulmonares (Hipertensión Pulmonar) e insuficiencia cardíaca terminal (Síndrome de Eisenmenger)." }, types: { title: "Causas y Factores de Riesgo", intro: "A menudo no hay una causa clara, pero se presenta fuertemente asociado a:", items: ["Prematuridad extrema: Los bebés nacidos mucho antes de tiempo (menos de 28 semanas de gestación) tienen un riesgo altísimo de CAP porque sus vasos no están maduros para cerrarse solos.", "Síndrome de rubéola congénita: Si la madre contrae rubéola en el embarazo.", "Factores genéticos y síndromes cromosómicos (como el Síndrome de Down).", "Nacer a grandes altitudes geográficas (por la menor presión de oxígeno en el aire)."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se diagnostica poco después del nacimiento o en las primeras revisiones pediátricas:", items: ["Auscultación del corazón: El pediatra escuchará un soplo cardíaco inconfundible, continuo, que suena como una 'máquina de vapor' ('soplo en maquinaria').", "Ecocardiograma: La prueba de oro absoluta. El ultrasonido muestra directamente el tamaño del conducto abierto y mide cuánta sangre se está escapando hacia los pulmones.", "Radiografía de tórax: A menudo muestra un corazón agrandado y pulmones congestionados con líquido.", "Electrocardiograma (ECG): Para comprobar el aumento de tamaño y esfuerzo de las cámaras del corazón."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del tamaño, los síntomas y la edad del bebé (prematuro vs. a término):", subsections: [ { title: "Cierre del Defecto", items: ["Observación: Si el bebé es prematuro y el CAP es pequeño, el médico puede esperar unas semanas, ya que a menudo se cierra por sí solo a medida que el niño crece.", "Medicamentos (solo en Prematuros): Fármacos antiinflamatorios especiales como la Indometacina o el Ibuprofeno administrados por vía intravenosa, bloquean las sustancias químicas que mantienen el conducto abierto, forzando a que se encoja y cierre.", "Cierre con Cateterismo (Procedimiento de Elección): Para niños mayores y adultos. Un cardiólogo introduce un catéter por la vena de la ingle, llega al corazón, e inserta un pequeño 'tapón' o espiral de alambre (coil) para sellar el vaso de forma permanente sin cirugía abierta.", "Cirugía a corazón abierto (Ligadura): Si el defecto es inusualmente grande, o en bebés muy pequeños donde no se puede usar catéter, un cirujano hace un corte entre las costillas y ata físicamente el conducto con suturas."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Contacta al pediatra o acude a urgencias pediátricas si el bebé:", items: ["Se cansa rápidamente, suda mucho o respira rápido e irregular al tomar el biberón o pecho", "No está aumentando de peso a pesar de alimentarlo regularmente", "Notas un tinte azulado o gris alrededor de sus labios durante el llanto o la alimentación"] } },
'Estenosis uretral' : { intro: "La estenosis uretral es una afección en la que la uretra, el tubo que transporta la orina y el semen desde la vejiga hacia el exterior del cuerpo, se estrecha de manera anormal y obstruye el flujo urinario. Es un problema anatómico mucho más frecuente en los hombres.", whatIs: { title: "¿Qué es una Estenosis Uretral?", text: "La pared interna de la uretra está formada por un tejido delicado. Si este tejido sufre un desgarro, inflamación o infección, se cura formando tejido cicatricial (fibrosis) grueso y duro. Esta cicatriz reduce el diámetro del conducto (como si pellizcaras una manguera de agua). La vejiga tiene que empujar cada vez más fuerte para expulsar la orina y, con el tiempo, no puede vaciarse por completo, dañando los riñones y la vejiga, y causando dolor persistente." }, symptoms: { title: "Síntomas Comunes", intro: "El paciente a menudo nota cambios graduales en su forma de orinar a lo largo de meses o años:", groups: [ { name: "Síntomas Obstructivos y de Vaciado", items: ["Flujo de orina notablemente débil, lento o en forma de rocío/pulverización fina", "Dificultad o necesidad de hacer mucho esfuerzo con los músculos del abdomen para empezar a orinar", "Vaciado incompleto (sensación de que la vejiga sigue llena después de ir al baño)", "Goteo prolongado después de haber terminado de orinar", "Micción muy frecuente, incluso levantándose muchas veces por la noche", "Dolor o ardor sordo en la uretra o la pelvis al orinar o eyacular", "Infecciones recurrentes del tracto urinario (IVU) o inflamación de la próstata y testículos por la orina estancada"] } ], warning: "Si el conducto se cierra por completo, ocurre una Retención Aguda de Orina. La vejiga se hincha y causa un dolor agonizante y la incapacidad absoluta para orinar, siendo una urgencia que requiere vaciado hospitalario." }, types: { title: "Causas y Desencadenantes", intro: "La formación de la cicatriz siempre es resultado de un daño previo (a veces ocurrido años antes de los síntomas):", items: ["Traumatismo pélvico o perineal: Caídas a horcajadas (golpearse la zona entre el ano y el escroto en la barra de una bicicleta o en una valla), o fracturas de la pelvis.", "Procedimientos médicos previos: La causa más común. Irritación por tener puesta una sonda vesical mucho tiempo, o cirugías en la próstata o vejiga que lesionaron la uretra con los instrumentos.", "Infecciones: Enfermedades de transmisión sexual previas no tratadas a tiempo (Gonorrea o Clamidia).", "Inflamación crónica: Enfermedades de la piel como el Liquen Escleroso que afectan la punta del pene.", "Cáncer uretral o radioterapia para cáncer de próstata (raras)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo ubicará exactamente dónde está la estrechez y qué tan larga es:", items: ["Flujometría (Prueba de flujo urinario): El paciente orina en un inodoro especial que mide la velocidad y la fuerza del chorro.", "Uretrografía retrógrada: Es la prueba principal y crucial. Se inyecta un líquido de contraste en la uretra y se toman rayos X para ver exactamente el lugar y la longitud del estrechamiento cicatricial.", "Cistoscopia: El médico inserta una pequeña cámara flexible en la uretra con lubricante anestésico para visualizar directamente la zona estrechada desde adentro."], note: "" }, treatment: { title: "Tratamientos", intro: "No existen medicamentos para disolver cicatrices; el tratamiento siempre es urológico:", subsections: [ { title: "Opciones de Intervención Quirúrgica", items: ["Dilatación Uretral: El urólogo inserta varillas de metal o globos progresivamente más anchos para estirar y desgarrar la cicatriz. Es rápido y ambulatorio, pero a menudo la cicatriz vuelve a cerrarse (alta tasa de recurrencia).", "Uretrotomía Interna Óptica: Usando una cámara y un cuchillo minúsculo o láser, el cirujano hace un corte en la cicatriz para abrir el conducto desde adentro. Eficaz para estrecheces cortas por primera vez.", "Uretroplastia (Cirugía Reconstructiva Abierta): El tratamiento de oro y definitivo para estenosis largas o que regresan constantemente. El cirujano abre la zona, extirpa por completo la porción cicatrizada del conducto y lo reconstruye (frecuentemente usando un injerto de tejido sano extraído de la pared interna de la mejilla del paciente - injerto de mucosa bucal)."] } ], note: "Tratar de dilatar agresiva y repetidamente una uretra muy cicatrizada suele empeorar la estenosis a largo plazo, por lo que la uretroplastia es la mejor solución curativa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca asistencia urológica si:", items: ["Notas que tu flujo de orina se ha vuelto débil, intermitente o en forma de spray", "Sufres de infecciones urinarias repetidas (raro en hombres sanos sin obstrucción)", "Ve a emergencias de inmediato si te duele intensamente el abdomen bajo y no puedes hacer pis en absoluto"] } },
'Síndrome femororrotuliano' : { intro: "El síndrome femororrotuliano, a menudo llamado síndrome de dolor patelofemoral o simplemente 'rodilla de corredor', es una afección muy frecuente que se caracteriza por causar un dolor sordo y molesto en la parte frontal de la rodilla y alrededor de la rótula.", whatIs: { title: "¿Qué es el Síndrome Femororrotuliano?", text: "La rótula (patela) está diseñada para deslizarse suavemente hacia arriba y hacia abajo sobre un surco en la parte inferior del hueso del muslo (fémur) cuando doblas y estiras la pierna. En este síndrome, debido a sobrecarga, desequilibrio muscular o problemas de alineación, la rótula no viaja de manera recta (mal tracking). Como resultado, raspa excesivamente contra los bordes del surco del fémur, causando fricción constante, inflamación del tejido subyacente e irritación del cartílago blando." }, symptoms: { title: "Síntomas y Desencadenantes Comunes", intro: "El dolor está fuertemente ligado a ciertas actividades repetitivas:", groups: [ { name: "Características del Dolor y la Fricción", items: ["Dolor crónico, sordo y punzante en la parte anterior de la rodilla, justo detrás, debajo o alrededor de los bordes de la rótula", "El dolor empeora dramáticamente al hacer esfuerzo en la flexión (subir, pero sobre todo, bajar escaleras, cuestas o correr cuesta abajo)", "Signo del Teatro (o de la butaca): Dolor agudo o rigidez al levantarse después de estar sentado con las rodillas dobladas durante un tiempo largo (como en un viaje en avión o en el cine)", "Chasquidos audibles, crepitación o sensación de roce áspero ('grinding') al agacharse o doblar la rodilla profundamente", "Hinchazón leve intermitente (rara vez es severa)"] } ], warning: "Aunque es extremadamente doloroso y limitante, este síndrome rara vez requiere cirugía. Sin embargo, si se ignora la biomecánica defectuosa durante años, el cartílago puede dañarse permanentemente, derivando en condromalacia patelar y artrosis prematura." }, types: { title: "Causas y Factores de Riesgo", intro: "Es un problema puramente mecánico y de sobrecarga, influenciado por:", items: ["Sobrecarga deportiva brusca: Aumentar rápidamente los días de entrenamiento, la distancia al correr, hacer sentadillas repetitivas o subir escaleras de golpe.", "Debilidad muscular y desequilibrios: Tener un músculo cuádriceps débil (especialmente la porción interna) y caderas/glúteos débiles hace que la rótula pierda su estabilizador principal y 'tiemble' fuera de su lugar.", "Rigidez de tejidos: Tendones de la corva y banda iliotibial (ITB) extremadamente tensos que tiran de la rótula hacia los lados de forma anormal.", "Alineación estructural anatómica: Personas con rodillas en X (valgo), pies planos (exceso de pronación), o rotulas inusualmente altas (patela alta).", "Ser mujer o adolescente en etapa de crecimiento (cambios en el ángulo de las caderas)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es clínico y se basa en tu historial de actividad y movimiento:", items: ["Examen físico biomecánico: El traumatólogo, fisioterapeuta o médico deportivo evaluará cómo te agachas, la fuerza de tus piernas, la alineación de tu rótula al mover la rodilla y dónde te duele exactamente.", "Radiografías (Rayos X): A menudo resultan normales, pero se utilizan para descartar espolones óseos, problemas graves de alineación y artritis de rodilla.", "Resonancia Magnética (RM): Rara vez se necesita al principio, solo se pide si los síntomas no mejoran tras meses de terapia o para descartar daños graves en los ligamentos o el cartílago profundo."], note: "" }, treatment: { title: "Tratamientos", intro: "La recuperación requiere paciencia y constancia física; la cirugía es casi inexistente para esta afección:", subsections: [ { title: "Manejo Inicial (Fase Aguda)", items: ["Protocolo RICE: Reposo activo (dejar de correr y hacer sentadillas), Hielo tras la actividad, Compresión y Elevación de la rodilla para calmar la inflamación urgente.", "Medicamentos y control del dolor: Antiinflamatorios no esteroideos (Ibuprofeno, Naproxeno) durante episodios agudos."] }, { title: "Rehabilitación Biomecánica (La cura real)", items: ["Fisioterapia focalizada: Es el pilar absoluto. Ejercicios para fortalecer poderosamente los músculos de los glúteos, las caderas y la porción interior del cuádriceps (VMO), a fin de que vuelvan a 'tirar' de la rótula hacia el centro del surco.", "Estiramientos profundos: Flexibilizar los isquiotibiales, pantorrillas y la banda iliotibial externa.", "Uso de plantillas ortopédicas: Corrección del pie plano o la pronación severa para enderezar el ángulo de la pierna completa.", "Rodilleras estabilizadoras y Taping: Uso de vendaje neuromuscular o rodilleras con un agujero central para sujetar y guiar físicamente la rótula en su sitio durante el deporte y evitar el roce."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un fisioterapeuta deportivo o médico especialista si:", items: ["El dolor de la rodilla no cede tras cambiar tu rutina deportiva y descansar unos días", "El dolor interfiere con actividades diarias normales como subir escaleras o levantarte de una silla", "Tu rodilla comienza a ceder (perder fuerza y doblarse sola) o se traba físicamente al moverla"] } },
'Cáncer de garganta' : { intro: "El cáncer de garganta es un término general que abarca el desarrollo de tumores malignos (cancerosos) que se originan en la faringe (el tubo hueco detrás de la nariz y la boca), la laringe (la caja de la voz que contiene las cuerdas vocales) y las amígdalas.", whatIs: { title: "¿Qué es el Cáncer de Garganta?", text: "La gran mayoría de estos cánceres son carcinomas de células escamosas, lo que significa que comienzan en las células planas y delgadas que recubren el interior de la garganta. Debido a su ubicación vital, este cáncer y los tratamientos para curarlo pueden afectar profundamente funciones humanas esenciales como la capacidad de hablar, tragar alimentos y respirar. Detectarlo tempranamente cuando se siente el primer nudo persistente en la garganta es fundamental." }, symptoms: { title: "Síntomas y Señales Tempranas", intro: "Los síntomas varían según la ubicación del tumor (si está en las cuerdas vocales, los síntomas vocales son obvios y tempranos; si está más abajo o en las amígdalas, pueden ser silenciosos hasta crecer mucho):", groups: [ { name: "Síntomas de Alarma Frecuentes", items: ["Ronquera crónica, voz áspera o cambios persistentes en la voz que no desaparecen (común en cáncer laringeo)", "Dificultad o dolor agudo e inexplicable al tragar alimentos sólidos o líquidos (disfagia y odinofagia)", "Tos persistente e intratable, que ocasionalmente expulsa flema con sangre o manchas rojizas", "Aparición de un bulto indoloro o masa dura en el cuello que crece gradualmente (ganglio linfático metastásico)", "Dolor de oído sordo y constante en un solo lado (dolor referido a través de los nervios de la garganta)", "Sensación perpetua de tener 'algo atascado' en la garganta y pérdida de peso sin intentarlo"] } ], warning: "Cualquier episodio de ronquera o dolor de garganta constante que dure más de tres a cuatro semanas sin ninguna mejora, y que no responda a tratamientos comunes o antibióticos, exige obligatoriamente una exploración por parte de un otorrinolaringólogo." }, types: { title: "Ubicaciones y Tipos Clínicos", intro: "Se divide según la zona anatómica atacada:", items: ["Cáncer Faríngeo: Incluye el cáncer de nasofaringe (detrás de la nariz), orofaringe (parte media de la garganta y amígdalas, fuertemente asociado al VPH) e hipofaringe (parte inferior sobre la caja de la voz).", "Cáncer Laríngeo: Ataca la laringe. Puede ser glótico (en las mismas cuerdas vocales), supraglótico (parte superior que incluye la epiglotis) o subglótico (bajo las cuerdas vocales)."], note: "" }, causes: { title: "Causas y Factores de Riesgo Principales", intro: "El cáncer de garganta rara vez ocurre al azar. El tejido sufre un daño crónico por toxinas o virus durante décadas antes de mutar:", items: ["Consumo de Tabaco (El riesgo número uno): Fumar cigarrillos, pipas, puros, usar tabaco de mascar (rapé) aumenta exponencialmente el riesgo.", "Consumo de Alcohol en Exceso: Beber alcohol frecuentemente destruye y quema las células. Cuando se combina el alcohol pesado con el tabaquismo cotidiano, los riesgos se multiplican entre sí brutalmente, no solo se suman.", "Infección por el Virus del Papiloma Humano (VPH): Específicamente la cepa VPH-16, transmitida frecuentemente por sexo oral, es hoy en día la principal causa del aumento de cánceres de orofaringe y amígdalas en personas jóvenes y no fumadoras.", "Reflujo Gastroesofágico Crónico (ERGE): El ácido del estómago que sube hasta la garganta noche tras noche irrita y daña las células con el tiempo.", "Infección por el virus de Epstein-Barr (relacionado con el cáncer nasofaríngeo).", "Dieta muy pobre en frutas y verduras."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere visualización directa y extracción de tejido:", items: ["Laringoscopia o Endoscopia nasal: El especialista en garganta (otorrino) introduce un tubo flexible muy delgado con luz y cámara a través de la nariz o la boca para observar las cuerdas vocales y todas las partes profundas de la garganta y cuello.", "Biopsia: Si se ve un tumor, tejido anormal o pólipo, el médico extirpará un pequeño pedazo de tejido (con fórceps durante la endoscopia, o con una aguja guiada por ecografía en el cuello si el bulto está fuera) para analizar si es cáncer.", "Imágenes de Extensión (Estadificación): Tomografía Computarizada (TC), Resonancia Magnética (RM) y escáneres PET del cuello y tórax para ver cuán profundo ha crecido el tumor, y si ha llegado a los huesos, ganglios linfáticos o pulmones."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere un equipo de oncólogos y cirujanos para curar el cáncer intentando salvar, si es posible, la capacidad de hablar y tragar naturalmente:", subsections: [ { title: "Enfoque Oncológico y Quirúrgico", items: ["Radioterapia: Utiliza potentes haces de rayos X u otras radiaciones para matar las células. A menudo es el tratamiento principal y curativo para tumores muy pequeños (en estadio temprano) de las cuerdas vocales o faringe, evitando cirugía.", "Cirugía Endoscópica, Láser y Robótica (TORS): Para cánceres tempranos, el cirujano puede cortar, quemar y raspar el cáncer mediante cámaras a través de la boca sin cortar el cuello.", "Cirugía Mayor (Laringectomía o Faringectomía): Si el cáncer es avanzado. Pueden extirpar la parte enferma (laringectomía parcial), o, en casos extremos, extirpar TODA la laringe (Laringectomía Total), lo que deja al paciente respirando permanentemente por un agujero en el cuello (traqueostomía) y requiere aprender a hablar de nuevo con laringe artificial (foniatría).", "Quimioterapia y Terapia Dirigida (Cetuximab): Fármacos agresivos inyectados en la sangre. A menudo se administran junto con la radiación (quimiorradiación) para potenciar la cura de tumores grandes, o solos en casos avanzados y terminales para aliviar el dolor.", "Inmunoterapia: Fármacos (Pembrolizumab o Nivolumab) que ayudan a que el propio sistema inmunológico del paciente reconozca y ataque a las células cancerosas evasivas."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico general de inmediato, o pide una derivación a otorrinolaringología si:", items: ["Tienes una ronquera constante y notoria o te cambia la voz por más de 3 semanas", "Tosas y encuentras rastros de sangre o esputo rosado repetidamente", "Descubres un bulto que no duele en tu cuello que no desaparece al cabo de semanas", "Te cuesta cada vez más tragar trozos de carne o pastillas, sintiendo que chocan en tu garganta"] } },
'Trastorno de dolor' : { intro: "El trastorno de dolor (clínicamente clasificado en los manuales psiquiátricos actuales como Trastorno de Síntomas Somáticos con Predominio de Dolor, o dolor crónico idiopático) es un trastorno somatomorfo en el cual el síntoma principal y definitorio de la vida del paciente es un dolor físico crónico y grave en una o varias partes del cuerpo, siendo los factores psicológicos fundamentales en el inicio, gravedad y mantenimiento de este dolor.", whatIs: { title: "¿Qué es el Trastorno de Dolor?", text: "Es vital comprender que el dolor en este trastorno ES REAL; el paciente no lo está inventando, simulando ('haciéndose el enfermo') ni buscando llamar la atención conscientemente. El problema radica en que, aunque el dolor pudo haber empezado por una lesión médica física real (como una cirugía, un accidente de tráfico o una artritis), esa lesión sanó por completo hace mucho tiempo, pero el sistema nervioso central se ha 'reprogramado' debido a traumas psicológicos graves, estrés profundo y vulnerabilidad emocional. El cerebro entra en un bucle y genera, amplifica y perpetúa señales neurológicas de dolor físico debilitante que no responden a los analgésicos médicos tradicionales ni a explicaciones anatómicas." }, symptoms: { title: "Síntomas y Señales de Conducta", intro: "Los síntomas no son solo físicos; involucran el pensamiento obsesivo y la discapacidad de la vida del paciente:", groups: [ { name: "Síntomas Físicos Reportados", items: ["Dolor crónico, insoportable e intratable en sitios como la espalda baja, el cuello, la pelvis, las extremidades o dolores de cabeza diarios", "El dolor a menudo empeora bruscamente, migra o se intensifica en momentos de gran estrés emocional, ansiedad o conflicto personal", "Aparición de fatiga severa y alteraciones del sueño ligadas al dolor crónico incesante"] }, { name: "Síntomas Psicológicos y de Discapacidad Social", items: ["Ansiedad constante y extrema por la salud (pensamientos desproporcionados de que un síntoma menor significa una enfermedad oculta y mortal)", "Visitas incesantes y búsqueda compulsiva ('shopping médico') de médicos, especialistas y quiroprácticos buscando curas y cirugías, rechazando invariablemente los diagnósticos de que los análisis están 'sanos'", "Dependencia crónica de analgésicos opioides, tranquilizantes y parches fuertes que no alivian significativamente el problema", "El dolor asume el control total de la identidad de la persona: provoca discapacidad para trabajar, destrucción del matrimonio y aislamiento social profundo", "Depresión severa que surge debido a la aparente falta de curación y la desesperanza constante"] } ], warning: "Realizar múltiples cirugías ortopédicas y exploratorias en un paciente cuyo dolor subyacente está impulsado psicológicamente casi siempre empeora el dolor y añade complicaciones neurológicas reales permanentes." }, causes: { title: "Causas y Factores Desencadenantes", intro: "El dolor crónico amplificado suele ser producto de una vulnerabilidad mente-cuerpo:", items: ["Historial de abuso emocional, físico o sexual severo durante la infancia o adultez (frecuentemente los traumas reprimidos se manifiestan fisiológicamente como dolor)", "Experimentar un estrés de vida paralizante reciente (muerte de un ser querido, ruina económica, divorcios amargos)", "Historial médico familiar o personal de trastornos de ansiedad crónica, trastorno de estrés postraumático (TEPT) o depresión mayor clínica", "Beneficio secundario subconsciente: Involuntariamente, el dolor crónico permite al paciente evitar tareas o responsabilidades aterradoras de la vida, o sirve para obtener cuidado, amor y atención que el paciente siente que no recibiría estando 'sano'"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico muy cuidadoso que debe realizar un equipo psiquiátrico en conjunto con médicos de medicina interna, descartando otras enfermedades:", items: ["Examen físico completo, resonancias y analíticas obligatorias para descartar primeramente y sin lugar a dudas cualquier enfermedad oculta (como cáncer, esclerosis múltiple o artritis autoinmune grave) que explique el dolor.", "Evaluación Psiquiátrica/Psicológica Extensiva: Un profesional de la salud mental evaluará el historial traumático del paciente, su estado de ánimo y cómo responde cognitivamente a las frustraciones de la vida.", "Se diagnostica oficialmente como trastorno de síntomas somáticos con predominio de dolor cuando los pensamientos sobre el dolor consumen la vida entera del paciente durante más de 6 meses y se demuestra un factor psicológico desencadenante claro."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo de la recuperación no es lograr el 'dolor cero' y encontrar una causa anatómica, sino mejorar la capacidad física y tratar profundamente los conflictos psíquicos subyacentes. Requiere rehabilitación en Unidades del Dolor Especializadas:", subsections: [ { title: "Manejo Psicológico, Físico y Farmacológico", items: ["Psicoterapia (Terapia Cognitivo-Conductual - TCC): Es el pilar fundamental del tratamiento. Ayuda al paciente a reestructurar sus patrones de pensamiento catastrofistas, manejar los miedos ocultos, y desarrollar habilidades para enfrentarse a la vida real sin que el cuerpo recurra al dolor como escape.", "Medicamentos Psiquiátricos y Moduladores: Los analgésicos clásicos (opioides) se suspenden y se realiza desintoxicación; en su lugar, se recetan potentes Antidepresivos (como Duloxetina, Amitriptilina o Venlafaxina) o anticonvulsivos (Gabapentina), porque alteran los receptores químicos en el cerebro que comparten tanto la depresión como el dolor crónico, aliviando ambos físicamente.", "Rehabilitación Física Progresiva y Fisioterapia: Un fisioterapeuta trabaja para reactivar el cuerpo gradualmente. El objetivo es que la persona vuelva a trabajar, hacer ejercicio ligero y recuperar su rutina a pesar del dolor restante, enseñando al cerebro que el cuerpo no está roto ni al borde del colapso.", "Medicina Mente-Cuerpo: El yoga clínico, el biofeedback (biorretroalimentación), la relajación muscular progresiva y la meditación guiada enseñan al sistema nervioso sobreestimulado a calmarse biológicamente."] } ], note: "Es vital un enfoque comprensivo en lugar de estigmatizar; decirle al paciente 'todo está en tu cabeza' rompe el vínculo médico, ya que el paciente siente el dolor tan real como el de un hueso roto." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar ayuda psiquiátrica o de una unidad de manejo del dolor si tú o un ser querido:", items: ["Han visitado a múltiples especialistas y han sido sometidos a incontables exámenes sin encontrar ninguna enfermedad física justificada que explique la magnitud del dolor atroz", "Están consumiendo grandes dosis de analgésicos de prescripción cada día y la calidad de vida y el sufrimiento no mejoran en absoluto", "Sufren de una intensa depresión, un alto nivel de estrés, han dejado de trabajar y hablar de enfermedades es el centro de todas sus conversaciones familiares"] } },
'Amebiasis' : { intro: "La amebiasis es una infección del intestino grueso y, en ocasiones, del hígado y otros órganos, causada por un parásito microscópico unicelular llamado Entamoeba histolytica.", whatIs: { title: "¿Qué es la Amebiasis?", text: "Es una enfermedad parasitaria que se adquiere principalmente al ingerir agua o alimentos contaminados con materia fecal que contiene quistes de la ameba. Una vez en el intestino, los quistes se rompen y liberan parásitos activos que pueden invadir y destruir el revestimiento intestinal, causando desde diarrea leve hasta úlceras severas." }, symptoms: { title: "Síntomas Comunes", intro: "Muchas personas infectadas no presentan síntomas, pero cuando se manifiestan, suelen incluir:", groups: [ { name: "Síntomas Intestinales", items: ["Diarrea frecuente, a menudo con heces acuosas o blandas", "Dolor y calambres abdominales severos", "Disentería amebiana (diarrea grave que contiene sangre y mucosidad)", "Fiebre leve y pérdida de peso involuntaria", "Exceso de gases (flatulencias) y dolor al defecar (tenesmo)"] } ], warning: "Si el parásito atraviesa la pared intestinal y entra al torrente sanguíneo, puede viajar al hígado y causar un absceso hepático amebiano, una complicación muy dolorosa y potencialmente mortal." }, causes: { title: "Causas y Factores de Riesgo", intro: "La transmisión es por vía fecal-oral, favorecida por:", items: ["Consumo de agua o alimentos no potabilizados ni lavados correctamente", "Viajes a zonas endémicas o tropicales con saneamiento deficiente", "Prácticas sexuales que implican contacto anal-oral", "Vivir en instituciones hacinadas o con malas condiciones de higiene"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico identificará el parásito mediante pruebas de laboratorio:", items: ["Examen de heces (coproparasitoscópico) bajo el microscopio para detectar quistes o amebas activas (puede requerir múltiples muestras de días diferentes)", "Análisis de sangre para detectar anticuerpos (serología), especialmente útil si se sospecha que la ameba ha invadido el hígado", "Colonoscopia o ecografía abdominal (en casos graves o para buscar abscesos hepáticos)"], note: "" }, treatment: { title: "Tratamientos", intro: "La infección parasitaria requiere tratamiento con medicamentos específicos:", subsections: [ { title: "Opciones de Manejo", items: ["Amebicidas tisulares: Fármacos como el Metronidazol o Tinidazol (orales) para eliminar los parásitos activos en la pared intestinal y en otros órganos.", "Amebicidas luminales: Medicamentos como la Paramomicina o Diloxanida, tomados después del metronidazol para destruir los quistes que quedan flotando en el interior del intestino y evitar que la persona siga contagiando a otros.", "Rehidratación: Beber abundantes líquidos o sueros de rehidratación oral para compensar la pérdida por la diarrea."] } ], note: "Es vital terminar todo el curso de ambos tipos de medicamentos para asegurar la curación completa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico o a un centro de salud si:", items: ["Tienes diarrea que dura más de unos pocos días o diarrea que contiene sangre y moco", "Experimentas dolor abdominal intenso acompañado de fiebre alta", "Has viajado recientemente a un país tropical y presentas molestias intestinales"] } },
'Eccema' : { intro: "El eccema, médicamente conocido como dermatitis atópica, es una afección crónica e inflamatoria de la piel que provoca parches rojos, secos y extremadamente pruriginosos (que pican).", whatIs: { title: "¿Qué es el Eccema?", text: "En las personas con eccema, una mutación genética o un fallo en el sistema inmunológico debilita la barrera protectora de la piel. Esto impide que la piel retenga la humedad y permite que bacterias, irritantes y alérgenos penetren fácilmente. El resultado es una piel perpetuamente seca, reactiva e inflamada que tiende a agravarse periódicamente (brotes)." }, symptoms: { title: "Síntomas y Características", intro: "Los signos varían mucho de una persona a otra, pero incluyen:", groups: [ { name: "Signos en la Piel", items: ["Picazón severa y constante (prurito), que suele empeorar significativamente por la noche", "Piel seca, escamosa y engrosada (liquenificación) por el rascado crónico", "Manchas de color rojo a marrón grisáceo, típicamente en los pliegues de los codos, detrás de las rodillas, en el cuello, manos y rostro", "Pequeñas protuberancias que pueden supurar líquido claro y formar costras al rascarse", "Piel extremadamente sensible e hinchada por rascarse"] } ], warning: "Rascarse incontrolablemente rompe la piel y puede provocar la entrada de bacterias (como el estafilococo), causando una infección cutánea grave secundaria." }, causes: { title: "Causas y Desencadenantes", intro: "Aunque la base es genética, los brotes son disparados por factores externos:", items: ["Piel seca (falta de lípidos naturales), clima frío y seco, o baños con agua muy caliente", "Irritantes químicos: jabones fuertes, detergentes, perfumes, lana o telas sintéticas", "Estrés emocional intenso y ansiedad", "Alérgenos ambientales (polen, polvo, caspa de mascotas) o alergias alimentarias (especialmente en bebés)", "Sudoración excesiva y cambios bruscos de temperatura"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El dermatólogo diagnostica el eccema mediante la observación:", items: ["Examen visual de la piel y evaluación del historial médico y familiar de alergias o asma", "Pruebas de parche o análisis de sangre (para descartar alergias específicas que empeoran los brotes)", "Biopsia de piel (rara vez, solo para descartar otras enfermedades de la piel)"], note: "El eccema a menudo forma parte de la 'tríada atópica', lo que significa que el paciente también puede sufrir de asma y rinitis alérgica." }, treatment: { title: "Tratamientos", intro: "No existe cura, pero una buena rutina de cuidado de la piel y medicamentos controlan los brotes:", subsections: [ { title: "Manejo Diario y Fármacos", items: ["Hidratación intensiva: La regla de oro. Aplicar cremas emolientes o pomadas espesas (sin fragancia) al menos dos veces al día, y siempre en los 3 minutos posteriores a salir de la ducha para sellar el agua en la piel.", "Corticosteroides tópicos: Cremas recetadas aplicadas directamente sobre los parches rojos durante un brote para reducir rápidamente la inflamación y la picazón.", "Inhibidores de la calcineurina (Tacrolimus): Pomadas sin esteroides que alteran el sistema inmunológico local de la piel para prevenir brotes.", "Antihistamínicos orales: Ayudan principalmente a dormir por la noche si la picazón es insoportable.", "Terapias avanzadas: Fototerapia (tratamiento con luz UV) o inyecciones de medicamentos biológicos (Dupilumab) para casos de eccema crónico severo y resistente."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu dermatólogo o médico si:", items: ["La picazón es tan intensa que no te deja dormir o afecta tus actividades diarias", "Notas que las lesiones de la piel están supurando pus amarillo o tienen costras de color miel (signo claro de infección bacteriana)", "Tus cremas hidratantes o medicamentos habituales ya no logran controlar los brotes"] } },
'Riñones poliquísticos' : { intro: "La enfermedad de los riñones poliquísticos (Poliquistosis Renal o ERP) es un trastorno genético progresivo en el cual se desarrollan múltiples quistes llenos de líquido en los riñones, alterando su estructura y función.", whatIs: { title: "¿Qué son los Riñones Poliquísticos?", text: "A diferencia de los quistes renales simples (que son comunes y benignos), en la ERP los quistes se multiplican y crecen sin control. Con el paso de los años, estos quistes agrandan masivamente los riñones, reemplazando el tejido sano encargado de filtrar la sangre. Eventualmente, esto conduce a hipertensión arterial, daño renal crónico y, con frecuencia, insuficiencia renal terminal que requiere diálisis o trasplante." }, symptoms: { title: "Síntomas y Complicaciones", intro: "La forma más común (en adultos) puede ser asintomática durante décadas. Los síntomas incluyen:", groups: [ { name: "Síntomas Renales y Sistémicos", items: ["Presión arterial alta (hipertensión), que suele ser el primer signo de la enfermedad", "Dolor crónico, pesadez o sensación de plenitud en la espalda, los costados (flancos) o el abdomen", "Sangre en la orina (hematuria) que aparece cuando un quiste se rompe", "Infecciones frecuentes del tracto urinario o de los riñones", "Agrandamiento visible del abdomen debido al tamaño masivo de los riñones", "Piedras en los riñones (cálculos renales)"] } ], warning: "Las personas con ERP tienen un riesgo mucho mayor de desarrollar aneurismas cerebrales (debilitamiento de los vasos sanguíneos del cerebro). Un dolor de cabeza explosivo y repentino requiere atención médica de emergencia." }, types: { title: "Tipos Genéticos", intro: "Se hereda en dos formas distintas:", items: ["Autosómica Dominante (ERPAD): El tipo más común (90%). Los síntomas suelen aparecer entre los 30 y 50 años. Solo necesitas heredar el gen de uno de tus padres.", "Autosómica Recesiva (ERPAR): Muy rara y severa. Los síntomas aparecen en el feto o en el bebé recién nacido. Ambos padres deben ser portadores del gen defectuoso."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Las pruebas de imagen son fundamentales para el diagnóstico:", items: ["Ecografía abdominal: La forma más común, segura e indolora de detectar la presencia de múltiples quistes en los riñones.", "Tomografía Computarizada (TC) o Resonancia Magnética (RM): Ofrecen detalles precisos sobre el tamaño exacto de los riñones y el volumen de los quistes.", "Análisis de sangre y orina: Para evaluar qué tan bien están filtrando los riñones (creatinina) y buscar proteínas en la orina.", "Pruebas genéticas: Útiles si los resultados de imagen no son claros o para personas jóvenes con antecedentes familiares que desean saber si tienen el gen."], note: "" }, treatment: { title: "Tratamientos", intro: "No existe cura, pero el tratamiento agresivo retrasa la progresión de la enfermedad:", subsections: [ { title: "Manejo y Medicamentos", items: ["Control estricto de la presión arterial: El paso más vital. Mantener la presión baja con medicamentos (como IECA o ARA-II) retrasa enormemente el daño a los riñones.", "Tolvaptán: Un medicamento oral específico que bloquea una hormona antidiurética, ralentizando el crecimiento de los quistes y preservando la función renal en pacientes de alto riesgo.", "Manejo del dolor y complicaciones: Antibióticos para las infecciones, analgésicos no nefrotóxicos para el dolor crónico, y mucha hidratación.", "Tratamiento de la Insuficiencia Renal: Cuando los riñones finalmente fallan, las únicas opciones son la diálisis o el trasplante de riñón (la ERP no destruye el riñón trasplantado)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención médica si:", items: ["Tienes antecedentes familiares de poliquistosis renal y deseas evaluación clínica o consejo genético", "Ves sangre en tu orina repetidamente o sufres de dolores intensos en la parte baja de la espalda", "Sufres el 'peor dolor de cabeza de tu vida' (acude a urgencias por riesgo de aneurisma)"] } },
'Arcos caídos' : { intro: "Los arcos caídos, comúnmente conocidos como 'pie plano', son una afección estructural del pie en la que la bóveda o el arco natural de la planta del pie colapsa, haciendo que toda la planta toque el suelo al estar de pie.", whatIs: { title: "¿Qué son los Arcos Caídos?", text: "El arco del pie está sostenido por una fuerte red de tendones y ligamentos. Cuando estos tejidos se estiran, se debilitan o se desgarran, el arco pierde su soporte y se aplana. Muchas personas tienen pies planos desde la infancia y nunca sufren problemas, pero cuando el arco colapsa de forma adquirida en la edad adulta, altera toda la biomecánica de la pierna y puede causar dolores crónicos desde el pie hasta la espalda baja." }, symptoms: { title: "Síntomas y Consecuencias", intro: "Un pie plano asintomático es normal, pero si causa problemas, notarás:", groups: [ { name: "Problemas de Dolor y Alineación", items: ["Dolor o dolor sordo a lo largo del arco interior del pie, en el talón, o en el tobillo", "Hinchazón a lo largo de la parte interna del tobillo", "Fatiga muscular rápida en las piernas al caminar, correr o estar de pie", "Desviación del tobillo hacia adentro (valgo de tobillo), haciendo que los zapatos se desgasten asimétricamente de un solo lado", "Dolor secundario en las rodillas, caderas o la parte baja de la espalda debido a la mala postura y falta de amortiguación"] } ], warning: "Si de repente pierdes el arco de tu pie en la edad adulta y sientes dolor, podría ser una disfunción o ruptura del tendón tibial posterior. Ignorarlo puede llevar a una deformidad permanente del pie y osteoartritis severa." }, causes: { title: "Causas y Factores de Riesgo", intro: "El colapso del arco en adultos se debe al desgaste o estrés continuo:", items: ["Disfunción del tendón tibial posterior (el tendón principal que sostiene el arco se inflama o se rompe por desgaste)", "Envejecimiento natural (los ligamentos pierden elasticidad con los años)", "Obesidad o aumento de peso rápido (ej. embarazo), que aplica una carga excesiva a los ligamentos del pie", "Artritis reumatoide, que destruye las articulaciones del pie", "Traumatismos (fracturas de los huesos del pie o tobillo) o diabetes (que daña los nervios del pie)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de los arcos caídos es visual y funcional:", items: ["Prueba de la huella mojada o inspección visual al estar de pie (el especialista verá que no hay espacio entre el suelo y el arco)", "Prueba de ponerse de puntillas (si el talón no gira hacia adentro al ponerse de puntillas, indica un problema en el tendón tibial posterior)", "Radiografías de los pies en carga (de pie) para evaluar la severidad de la caída ósea y si hay artritis", "Ecografía o Resonancia Magnética (RM) para ver si los tendones están desgarrados o inflamados"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento solo es necesario si el pie plano duele. El objetivo es dar soporte al pie y aliviar la tensión de los tendones:", subsections: [ { title: "Manejo Conservador y Ortopédico", items: ["Soportes plantares (Plantillas ortopédicas a medida): Redirigen el peso, soportan el arco caído y evitan que el tobillo se doble hacia adentro. Son la solución más efectiva para aliviar el dolor.", "Calzado de soporte estructural: Usar zapatos anchos con soporte rígido para el arco y el talón.", "Fisioterapia: Ejercicios de estiramiento del tendón de Aquiles (que a menudo está muy tenso) y ejercicios con bandas de resistencia para fortalecer el tendón tibial posterior.", "Bajar de peso: Vital para reducir la carga sobre las estructuras debilitadas del pie.", "Cirugía: Se considera solo si el dolor es incapacitante, los tendones están rotos, o hay deformidad rígida extrema. Puede implicar reparación de tendones, reestructuración de huesos o fusión de articulaciones (artrodesis)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un podólogo, ortopedista o fisioterapeuta si:", items: ["Tienes dolor recurrente en los pies o los tobillos que te impide realizar tus actividades diarias", "Notas que tu arco se ha aplanado recientemente o que tus zapatos se están deformando hacia un lado", "Sientes que tu pie o tobillo es inestable, rígido o se hincha constantemente"] } },
'Dengue' : { intro: "El dengue es una infección viral transmitida por la picadura de mosquitos infectados, principalmente de la especie *Aedes aegypti*. Es una enfermedad febril aguda prevalente en zonas tropicales y subtropicales del mundo.", whatIs: { title: "¿Qué es el Dengue?", text: "El virus del dengue causa un cuadro gripal muy intenso, coloquialmente conocido como la 'fiebre rompehuesos' debido a los dolores musculares y articulares severos que provoca. Aunque la mayoría de los pacientes se recuperan en una o dos semanas, la infección puede evolucionar hacia una complicación letal llamada Dengue Grave (o dengue hemorrágico), que causa sangrado masivo, caída repentina de la presión arterial y estado de shock." }, symptoms: { title: "Síntomas y Señales", intro: "Los síntomas comienzan de 4 a 10 días después de la picadura del mosquito:", groups: [ { name: "Síntomas del Dengue Clásico", items: ["Fiebre altísima y repentina (hasta 40°C / 104°F)", "Dolor de cabeza muy intenso y característico dolor punzante detrás de los ojos", "Dolores musculares y articulares severos y profundos ('rompehuesos')", "Náuseas, vómitos y pérdida total de apetito", "Aparición de un sarpullido o erupción rojiza en la piel (a menudo 2-5 días después de que inicia la fiebre)"] }, { name: "Signos de Alarma (Dengue Grave)", items: ["Aparecen curiosamente cuando la fiebre disminuye (fase crítica):", "Dolor abdominal muy intenso y continuo", "Vómitos persistentes (a veces con sangre)", "Sangrado inexplicable por las encías, la nariz, o sangre en las heces o la orina", "Dificultad rápida para respirar y fatiga o irritabilidad extrema"] } ], warning: "Si presentas cualquiera de los 'Signos de Alarma' entre el tercer y séptimo día de la enfermedad (cuando la fiebre baja), acude a urgencias inmediatamente. Es el inicio del dengue grave, que requiere soporte hospitalario para sobrevivir." }, types: { title: "El Virus y el Riesgo", intro: "Un factor crucial del dengue es que el virus tiene cuatro serotipos distintos (DENV 1, 2, 3 y 4):", items: ["Infección primaria: Si te infectas por primera vez, adquieres inmunidad de por vida contra ese serotipo específico.", "Infección secundaria: Si te vuelve a picar un mosquito con un serotipo DIFERENTE, tu riesgo de desarrollar 'Dengue Grave' y hemorragias se multiplica exponencialmente por un fenómeno del sistema inmunológico."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico en zonas epidémicas se confirma con análisis de sangre:", items: ["Prueba de Antígeno NS1: Un análisis de sangre rápido que detecta una proteína del virus durante los primeros días de fiebre.", "Serología (Anticuerpos IgM/IgG): Detecta si tu cuerpo está combatiendo el virus (útil después del cuarto día de síntomas).", "Hemograma completo: Crucial para monitorear el dengue. Los médicos buscan una caída en los niveles de plaquetas (trombocitopenia) y un aumento en la concentración de la sangre (hematocrito), signos tempranos de dengue grave y fuga de líquidos."], note: "" }, treatment: { title: "Tratamientos", intro: "No existe un medicamento antiviral específico para curar el dengue. El tratamiento es de soporte para ayudar al cuerpo a recuperarse:", subsections: [ { title: "Manejo Médico y Precauciones Vitales", items: ["Control de la Fiebre y Dolor: Usar ÚNICAMENTE Paracetamol (Acetaminofén).", "PROHIBICIÓN ESTRICTA: No tomar NUNCA Ibuprofeno, Aspirina, Naproxeno ni ningún otro AINE. Estos medicamentos empeoran la función de las plaquetas y pueden desencadenar hemorragias mortales en pacientes con dengue.", "Hidratación: Beber cantidades masivas de líquidos, sueros de rehidratación oral y agua de coco es fundamental para evitar el shock por deshidratación y fuga de plasma.", "Ingreso Hospitalario (Dengue Grave): Si hay signos de alarma, el paciente necesita fluidos intravenosos de emergencia y monitoreo estricto de la presión arterial en cuidados intensivos, y posiblemente transfusiones de sangre."] } ], note: "La prevención es vital: eliminar agua estancada (cubos, macetas) donde los mosquitos se reproducen, usar repelentes con DEET y mosquiteras." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca asistencia médica de emergencia si, especialmente 24 a 48 horas después de que la fiebre haya bajado, presentas:", items: ["Dolor abdominal fuerte, vómitos repetidos o te sientes extremadamente débil e inquieto", "Sangras por la nariz o las encías al cepillarte, o ves moretones repentinos en la piel", "Sientes que tu piel está fría, húmeda y pálida (signo de shock circulatorio)"] } },
'Afasia' : { intro: "La afasia es un trastorno del lenguaje que afecta la capacidad de una persona para comunicarse. Dificulta severamente la habilidad para hablar, comprender el lenguaje hablado, leer y escribir.", whatIs: { title: "¿Qué es la Afasia?", text: "La afasia no afecta la inteligencia ni la capacidad de pensamiento de la persona; es estrictamente un problema de lenguaje. Ocurre cuando se produce un daño en las redes y áreas cerebrales que procesan el lenguaje, que en la mayoría de las personas se encuentran en el lado izquierdo del cerebro. El paciente a menudo sabe exactamente lo que quiere decir, pero su cerebro no puede encontrar las palabras, las emite desordenadas, o no puede decodificar lo que otros le están diciendo." }, symptoms: { title: "Síntomas y Señales", intro: "La afasia es muy frustrante para el paciente. Los síntomas dependen de qué parte del cerebro se dañó:", groups: [ { name: "Síntomas Expresivos (Problemas para Emitir el Lenguaje)", items: ["Hablar con frases muy cortas, entrecortadas o incompletas (por ejemplo, decir 'querer comida' en lugar de 'quiero algo de comer')", "Hacer un esfuerzo físico enorme para pronunciar las palabras", "Sustituir una palabra por otra (decir 'silla' cuando quiere decir 'mesa') o usar palabras inventadas e irreconocibles"] }, { name: "Síntomas Receptivos (Problemas para Entender el Lenguaje)", items: ["Incapacidad para comprender lo que dicen los demás, especialmente si hablan rápido o con frases largas", "La persona puede hablar de forma fluida y continua, pero las oraciones no tienen ningún sentido lógico", "No ser consciente de que los demás no pueden entender lo que está diciendo", "Dificultad repentina para comprender textos escritos o para escribir palabras correctamente"] } ], warning: "La afasia suele aparecer de manera repentina. Es uno de los signos clínicos más clásicos de un Accidente Cerebrovascular (Ictus) en curso." }, types: { title: "Tipos de Afasia", intro: "Las afasias se clasifican clínicamente en varios tipos:", items: ["Afasia de Broca (No fluida o Expresiva): El paciente entiende lo que le dicen, pero le cuesta muchísimo esfuerzo físico hablar. Habla con palabras sueltas. Suele causar gran frustración porque son conscientes de su problema.", "Afasia de Wernicke (Fluida o Receptiva): El paciente habla con fluidez y facilidad, pero usa palabras incorrectas o inventadas (ensalada de palabras). A menudo no entienden bien lo que se les dice y no se dan cuenta de que hablan sin sentido.", "Afasia Global: La forma más grave. Se produce por un daño extenso. El paciente no puede hablar, ni entender, ni leer, ni escribir."], note: "" }, causes: { title: "Causas Principales", intro: "Cualquier daño al tejido cerebral en los centros del lenguaje causa afasia:", items: ["Accidente Cerebrovascular (Ictus isquémico o hemorrágico): Es la causa número uno, con diferencia.", "Traumatismo craneoencefálico grave (golpes fuertes en la cabeza)", "Tumores cerebrales", "Infecciones cerebrales (encefalitis, abscesos)", "Enfermedades neurodegenerativas (como la Afasia Progresiva Primaria, una forma de demencia que comienza destruyendo el lenguaje antes de la memoria)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere imágenes médicas inmediatas y pruebas de lenguaje:", items: ["Tomografía Computarizada (TC) o Resonancia Magnética (RM) del cerebro: Pruebas de urgencia para identificar qué causó el daño cerebral (un derrame o un tumor) y dónde está ubicado exactamente.", "Evaluación del habla y lenguaje (Logopedia): Un patólogo del habla-lenguaje (logopeda) realiza pruebas exhaustivas pidiéndole al paciente que nombre objetos, repita palabras, responda preguntas simples, lea y escriba para determinar el tipo exacto y la gravedad de la afasia."], note: "" }, treatment: { title: "Tratamientos", intro: "La recuperación depende de la causa, la extensión del daño y la terapia intensiva:", subsections: [ { title: "Rehabilitación y Soporte", items: ["Terapia del Habla y el Lenguaje: Es el tratamiento fundamental. Cuanto antes comience, mejor. Ayuda a restaurar el lenguaje posible y a encontrar métodos alternativos para comunicarse.", "Terapias grupales: Practicar habilidades de comunicación en un entorno seguro y comprensivo con otras personas que padecen afasia reduce el aislamiento y la depresión.", "Comunicación Aumentativa y Alternativa (CAA): Uso de dispositivos, tabletas con imágenes, tarjetas con dibujos o libretas para ayudar a los pacientes que no pueden recuperar el habla a expresar sus necesidades.", "Tratamiento de la causa base: Evitar un segundo derrame cerebral mediante control de la presión arterial, anticoagulantes o cirugía si hay un tumor."] } ], note: "La familia debe ser educada para simplificar el lenguaje, hablar despacio, usar gestos y dar al paciente todo el tiempo necesario para responder sin interrumpirlo ni terminar sus frases." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La aparición repentina de afasia es una emergencia de vida o muerte. Llama al 911 de inmediato si alguien:", items: ["De repente no puede hablar, arrastra las palabras o dice cosas sin sentido", "No parece entender instrucciones simples que acabas de darle", "Acompaña estos problemas de lenguaje con debilidad o parálisis en la cara, un brazo o una pierna"] } },
'Eliminación de amalgamas' : { intro: "La eliminación de amalgamas es un procedimiento odontológico en el cual se retiran los empastes dentales tradicionales de color plateado. Estos empastes están compuestos por una aleación de metales líquidos que incluye aproximadamente un 50% de mercurio elemental, plata, estaño y cobre.", whatIs: { title: "¿Qué implica la Eliminación de Amalgamas?", text: "A lo largo de los años, las amalgamas pueden deteriorarse, agrietarse o causar fisuras en el diente. Muchas personas deciden retirarlas por motivos puramente estéticos (para reemplazarlas por resinas del color del diente) o por preocupación sobre la toxicidad crónica del mercurio. Sin embargo, el momento de mayor riesgo de exposición al vapor de mercurio no es cuando el empaste está intacto en la boca, sino exactamente durante el proceso mecánico de taladrarlo para extraerlo." }, symptoms: { title: "Razones o Indicaciones para Retirarlas", intro: "Los motivos por los cuales un dentista recomienda retirar un empaste de plata incluyen:", groups: [ { name: "Indicaciones Clínicas", items: ["Fractura o agrietamiento del empaste viejo o del diente que lo rodea", "Aparición de caries secundaria (nueva caries oculta) debajo o en los bordes de la amalgama", "Sensibilidad dental o dolor al masticar debido a filtraciones en el empaste", "Razones cosméticas (el paciente desea restauraciones blancas de composite o cerámica)", "Reacción alérgica documentada (muy rara) a los metales de la amalgama"] } ], warning: "Importante: Las principales organizaciones de salud dental del mundo (incluida la FDA y la ADA) NO recomiendan la extracción de empastes de amalgama que están en buenas condiciones únicamente para eliminar el mercurio del cuerpo, ya que el proceso de extracción en sí mismo expone al paciente a niveles más altos de vapor de mercurio que dejarlos intactos." }, treatment: { title: "Protocolo Seguro (Tratamiento Clínico)", intro: "Si se debe retirar la amalgama, es fundamental que el dentista utilice un protocolo de bioseguridad estricto (como el protocolo SMART) para minimizar la inhalación de vapores de mercurio y la ingestión de partículas metálicas:", subsections: [ { title: "Medidas de Bioseguridad durante la Extracción", items: ["Aislamiento Absoluto (Dique de goma): Es la medida más importante. Se coloca una lámina de goma o látex alrededor del diente aislandolo por completo del resto de la boca y la garganta, impidiendo que el paciente trague trozos de metal.", "Succión de alta velocidad, alto volumen y succión extraoral: Uso continuo de aspiradoras potentes colocadas muy cerca del diente para capturar y evacuar los vapores de mercurio y el agua inmediatamente.", "Refrigeración con abundante agua: El dentista debe rociar el diente constantemente con mucha agua fría mientras taladra, para evitar que el calor del taladro vaporice el mercurio.", "Extracción en trozos grandes (Seccionamiento): El objetivo es cortar el empaste en bloques grandes en lugar de molerlo o pulverizarlo por completo, reduciendo así la fricción y el vapor.", "Suministro de aire limpio: Algunos protocolos holísticos incluyen colocar una mascarilla de oxígeno o aire limpio sobre la nariz del paciente para evitar que inhale los aerosoles de la clínica durante el fresado."] } ], note: "Una vez retirado el metal, el diente se restaura con materiales biocompatibles como la resina compuesta (composite), ionómero de vidrio o incrustaciones de porcelana." }, whenToSeekHelp: { title: "¿Cuándo Consultar al Dentista?", intro: "Pide una revisión dental si:", items: ["Notas que un antiguo empaste plateado se ve oscuro en los bordes, está roto, astillado o suelto", "Sientes dolor agudo, sensibilidad prolongada al frío o al calor, o dolor punzante al morder sobre un diente con empaste", "Te preocupa la estética de tus empastes y deseas evaluar los riesgos y beneficios de cambiarlos por restauraciones del color del diente de forma segura"] } },
'Periimplantitis' : { intro: "La periimplantitis es una enfermedad infecciosa e inflamatoria crónica que afecta a los tejidos blandos (encías) y a los tejidos duros (hueso) que rodean un implante dental osteointegrado, provocando la pérdida progresiva del hueso de soporte.", whatIs: { title: "¿Qué es la Periimplantitis?", text: "Así como los dientes naturales pueden sufrir de periodontitis (piorrea), los implantes dentales pueden sufrir de periimplantitis. Ocurre cuando la placa bacteriana (sarro) se acumula en la superficie del titanio del implante debajo de la línea de las encías. La respuesta inmunitaria del cuerpo contra estas bacterias causa una inflamación que, lamentablemente, también destruye el hueso que ancla el implante a la mandíbula. Si no se trata a tiempo, el implante perderá su fijación, se aflojará y finalmente fracasará (se caerá)." }, symptoms: { title: "Síntomas y Alertas", intro: "En sus primeras etapas (mucositis periimplantaria, donde solo hay inflamación de la encía sin pérdida de hueso), puede ser casi asintomática. A medida que avanza a periimplantitis, los signos incluyen:", groups: [ { name: "Signos Clínicos en la Encía y el Implante", items: ["Enrojecimiento, inflamación o hinchazón de las encías que rodean el implante", "Sangrado fácil alrededor del implante durante el cepillado o al usar hilo dental", "Supuración (salida de pus) desde la encía alrededor de la corona del implante al presionarla", "Bolsas profundas (espacio aumentado) entre la encía y el implante detectadas por el dentista", "Recesión de la encía (la encía se encoge, exponiendo las roscas metálicas del implante)", "Movilidad o aflojamiento del implante (signo de etapa final muy grave)", "Dolor sordo en el área (aunque muchas periimplantitis no duelen hasta que el implante está a punto de fracasar)"] } ], warning: "La inflamación sangrante (mucositis) es el aviso previo; es completamente reversible con limpieza profesional. Si progresa a pérdida de hueso (periimplantitis), el daño es muy difícil de revertir y el tratamiento es complejo." }, causes: { title: "Causas y Factores de Riesgo", intro: "El origen es la acumulación bacteriana (placa y sarro), exacerbada fuertemente por:", items: ["Higiene oral deficiente en el hogar y falta de limpiezas dentales profesionales periódicas", "Tabaquismo crónico (los fumadores tienen un riesgo muchísimo mayor de fracaso del implante y problemas de curación)", "Antecedentes de enfermedad periodontal (piorrea) en los dientes naturales; si perdiste dientes por periodontitis, las bacterias siguen en tu boca y atacarán el implante", "Diabetes mellitus mal controlada (afecta la respuesta inmune y la salud del hueso)", "Exceso de cemento dental que quedó escondido debajo de la encía al pegar la corona sobre el implante", "Falta de tejido de encía gruesa (encía queratinizada) alrededor del implante"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere sondaje e imágenes radiográficas en consulta:", items: ["Sondaje periodontal: El dentista o periodoncista inserta una pequeña sonda milimetrada entre la encía y el implante para medir la profundidad de las 'bolsas'. Profundidades crecientes y sangrado al sondaje son diagnósticos.", "Radiografías periapicales: Cruciales para comparar los niveles de hueso actuales alrededor de las roscas del implante con las radiografías tomadas justo después de colocar la corona. Confirma la pérdida ósea en forma de 'cráter'."] }, treatment: { title: "Tratamientos", intro: "El objetivo es detener la infección, descontaminar la superficie de titanio (lo cual es muy difícil por sus roscas) y, si es posible, regenerar el hueso perdido:", subsections: [ { title: "Opciones Quirúrgicas y No Quirúrgicas", items: ["Tratamiento No Quirúrgico (Para estadios tempranos/Mucositis): Limpieza profunda (desbridamiento mecánico) en la clínica usando curetas especiales de teflón o titanio, pulido por aire o láser, junto con enjuagues antibacterianos (Clorhexidina) e instrucciones intensivas de higiene en casa.", "Cirugía de Acceso y Descontaminación: Si hay pérdida de hueso, el periodoncista debe hacer una cirugía abriendo la encía para ver el implante, limpiar el tejido inflamado infectado y descontaminar química o mecánicamente la superficie roscada del titanio.", "Cirugía Regenerativa Ósea: Tras descontaminar el implante, el cirujano coloca injertos de hueso (polvo de hueso) y membranas biológicas en el defecto para intentar que el hueso vuelva a crecer alrededor de las roscas expuestas.", "Extirpación (Explantación): Si la pérdida de hueso es masiva (más de 2/3 del implante) o el implante se mueve, la única opción es desenroscar y retirar el implante, limpiar el lecho infeccioso y, meses después, injertar hueso para intentar colocar un implante nuevo."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una revisión con tu dentista o periodoncista rápidamente si:", items: ["Tus encías sangran al lavarte los dientes alrededor de tu implante dental", "Sientes mal sabor de boca constante o ves pus asomando por la encía del implante", "Sientes que la corona o el propio implante están flojos o se mueven al masticar"] } },
'Alergia de insectos' : { intro: "La alergia a las picaduras de insectos es una reacción exagerada del sistema inmunológico al veneno inyectado por insectos como abejas, avispas, hormigas rojas o avispones.", whatIs: { title: "¿Qué es una Alergia a Insectos?", text: "Normalmente, una picadura de insecto causa dolor temporal, enrojecimiento e hinchazón local. Sin embargo, en personas alérgicas, el sistema inmunológico identifica erróneamente el veneno como una amenaza mortal, produciendo anticuerpos (IgE) que desencadenan una respuesta inflamatoria masiva. Esta reacción puede ser local (hinchazón extrema en la zona) o sistémica (anafilaxia), poniendo en riesgo la vida." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los síntomas varían desde reacciones locales grandes hasta emergencias sistémicas:", groups: [ { name: "Reacciones Locales Extensas", items: ["Enrojecimiento severo e hinchazón que se expande más de 10 centímetros más allá del sitio de la picadura", "Dolor progresivo, calor al tacto y picazón intensa que dura varios días"] }, { name: "Reacción Sistémica (Anafilaxia - Emergencia)", items: ["Urticaria generalizada (ronchas rojas que pican en todo el cuerpo)", "Hinchazón de la garganta, los labios o la lengua (angioedema)", "Dificultad severa para respirar, sibilancias o sensación de asfixia", "Mareos agudos, caída drástica de la presión arterial o pérdida de conocimiento", "Náuseas, vómitos o calambres abdominales repentinos"] } ], warning: "La anafilaxia puede desarrollarse en cuestión de minutos tras la picadura. El retraso en la administración de epinefrina es la principal causa de mortalidad en estas reacciones." }, types: { title: "Insectos Culpables Comunes", intro: "Las reacciones alérgicas severas son provocadas casi exclusivamente por insectos que pican e inyectan veneno:", items: ["Abejas melíferas (dejan el aguijón en la piel y mueren)", "Avispas, avispones y chaquetas amarillas (pueden picar repetidamente sin dejar el aguijón)", "Hormigas rojas o de fuego (inyectan veneno repetidamente aferrándose con sus mandíbulas)"], note: "Las picaduras de mosquitos, pulgas o garrapatas causan picazón molesta, pero rara vez desencadenan anafilaxia." }, causes: { title: "Causas y Factores de Riesgo", intro: "Cualquier persona puede desarrollar una alergia, pero los riesgos aumentan por:", items: ["Haber tenido una reacción alérgica previa a una picadura (incluso si fue leve, la siguiente puede ser severa)", "Historial personal o familiar de otras alergias severas o asma", "Profesiones de alto riesgo (apicultores, jardineros, trabajadores forestales o agrícolas)", "Ciertos medicamentos para la presión arterial (betabloqueantes) que pueden hacer que las reacciones sean más difíciles de tratar"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El alergólogo determinará el grado de alergia mediante:", items: ["Historia clínica detallada del evento de la picadura", "Pruebas cutáneas de alergia (Prick test): Se aplican pequeñas cantidades de veneno purificado en la piel para observar la reacción inflamatoria.", "Análisis de sangre (IgE específica): Mide la cantidad de anticuerpos alérgicos al veneno circulando en la sangre."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento abarca desde el manejo de la emergencia hasta la cura a largo plazo:", subsections: [ { title: "Manejo de Emergencia y Prevención", items: ["Autoinyector de Epinefrina (EpiPen): El único medicamento que salva vidas durante la anafilaxia. Toda persona con alergia diagnosticada debe llevar dos autoinyectores consigo en todo momento.", "Antihistamínicos y Corticosteroides: Para tratar reacciones locales extensas y reducir la picazón y la hinchazón prolongada.", "Inmunoterapia con Veneno (Vacunas para la alergia): Es el tratamiento definitivo a largo plazo. Consiste en inyectar cantidades minúsculas y gradualmente crecientes del veneno durante 3 a 5 años. Esto desensibiliza el sistema inmunológico, logrando una tasa de curación y prevención de anafilaxia del 90 al 98%.", "Medidas preventivas: Evitar caminar descalzo en el césped, no usar perfumes florales fuertes al aire libre y no beber de latas de refresco abiertas en verano (las avispas suelen meterse dentro)."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama al 911 de inmediato si:", items: ["Presentas dificultad para respirar, hinchazón en la cara o garganta, o mareos severos tras una picadura", "Tienes prescrito un EpiPen y has tenido que usarlo (debes ir a urgencias siempre después de inyectarte)"] } },
'Gripe' : { intro: "La gripe, o influenza, es una infección respiratoria altamente contagiosa causada por los virus de la influenza. A diferencia de un resfriado común, la gripe ataca de forma repentina y puede provocar complicaciones graves, especialmente en personas vulnerables.", whatIs: { title: "¿Qué es la Gripe?", text: "Es una infección viral que afecta principalmente la nariz, la garganta y, a veces, los pulmones. Los virus de la influenza viajan por el aire en gotitas cuando alguien tose, estornuda o habla. Aunque la mayoría de las personas se recuperan por completo en una o dos semanas, la gripe puede ser mortal en ancianos, niños pequeños, mujeres embarazadas y personas con enfermedades crónicas, debido a complicaciones como la neumonía severa." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "La característica definitoria de la gripe es su aparición brusca (te sientes bien por la mañana y muy enfermo por la tarde):", groups: [ { name: "Síntomas Clásicos", items: ["Fiebre alta repentina (frecuentemente superior a 38.5°C o 101°F) y escalofríos severos", "Dolores musculares y corporales intensos, especialmente en la espalda, brazos y piernas", "Fatiga extrema, debilidad y necesidad de guardar cama", "Dolor de cabeza fuerte", "Tos seca y persistente", "Dolor de garganta y congestión nasal"] } ], warning: "En los niños, la gripe a menudo se presenta con síntomas gastrointestinales (náuseas, vómitos, diarrea), lo cual es menos común en adultos." }, types: { title: "Tipos de Virus", intro: "Hay varios tipos de virus de la influenza, pero dos son responsables de las epidemias estacionales:", items: ["Influenza Tipo A: Es el tipo más común y severo. Capaz de infectar a animales (aves, cerdos) y humanos. Es el responsable de las grandes pandemias mundiales (como la gripe porcina H1N1 o la gripe aviar) porque muta muy rápido.", "Influenza Tipo B: Infecta casi exclusivamente a humanos. Causa brotes estacionales regulares pero generalmente no pandemias.", "Influenza Tipo C: Causa infecciones respiratorias muy leves y no provoca epidemias."], note: "" }, causes: { title: "Factores de Riesgo de Complicaciones", intro: "Cualquier persona puede contraer la gripe, pero el riesgo de que se vuelva grave o mortal aumenta en:", items: ["Niños menores de 5 años y adultos mayores de 65 años", "Personas con enfermedades crónicas (asma, EPOC, diabetes, insuficiencia cardíaca)", "Personas con sistemas inmunológicos deprimidos (pacientes con cáncer, VIH, o en tratamiento con esteroides)", "Mujeres embarazadas (hasta dos semanas después del parto)", "Personas con obesidad mórbida (IMC superior a 40)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se diagnostica por los síntomas durante la temporada de gripe, pero puede confirmarse con:", items: ["Pruebas de diagnóstico rápido de la influenza (RIDT): Se toma una muestra de la nariz o garganta con un hisopo y el resultado está listo en 15 minutos (aunque pueden dar falsos negativos).", "Pruebas moleculares (PCR rápida): Mucho más precisas y detectan el tipo exacto de virus.", "Radiografía de tórax: Se solicita si el médico escucha ruidos en los pulmones para descartar una neumonía complicante."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento se basa en el alivio de los síntomas y la prevención de complicaciones:", subsections: [ { title: "Manejo Médico y Antiviral", items: ["Reposo estricto e hidratación: Quedarse en casa, descansar en cama y beber muchos líquidos (agua, caldos, jugos) para evitar la deshidratación por la fiebre.", "Antivirales recetados (Oseltamivir/Tamiflu o Baloxavir/Xofluza): Si se toman en las primeras 48 horas desde el inicio de los síntomas, pueden acortar la duración de la enfermedad y prevenir complicaciones graves como la neumonía. Son cruciales para pacientes de alto riesgo.", "Analgésicos de venta libre (Paracetamol o Ibuprofeno): Para bajar la fiebre y aliviar los dolores musculares. (Nunca dar Aspirina a niños o adolescentes por el riesgo del Síndrome de Reye, una enfermedad cerebral fatal).", "Vacunación Anual (Prevención): La vacuna contra la gripe es la mejor defensa. Como el virus muta constantemente, la vacuna se actualiza cada año para proteger contra las cepas más probables de la temporada."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias inmediatamente si tú o un ser querido presentan:", items: ["Dificultad evidente para respirar o dolor intenso en el pecho al respirar", "Coloración azulada en los labios o rostro", "Confusión repentina, mareos severos o incapacidad para despertarse", "Fiebre que desaparece pero luego regresa bruscamente acompañada de una tos peor (signo de neumonía bacteriana secundaria)"] } },
'Inclusión dentaria' : { intro: "Una inclusión dentaria (o diente impactado) ocurre cuando un diente no logra emerger (erupcionar) a través de las encías hacia su posición normal en la boca en el tiempo esperado, quedando parcial o totalmente atrapado en el hueso maxilar o la encía.", whatIs: { title: "¿Qué es una Inclusión Dentaria?", text: "Los dientes necesitan suficiente espacio en los maxilares para salir derechos. A menudo, debido a la evolución humana, nuestros maxilares son demasiado pequeños para albergar todos los dientes. Cuando un diente intenta salir pero choca contra otro diente, hueso denso o encía gruesa, queda impactado. Los terceros molares (muelas del juicio) son los dientes que sufres inclusiones con mayor frecuencia, seguidos por los caninos superiores (colmillos)." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Un diente completamente incluido bajo el hueso puede no causar síntomas durante años. Si está parcialmente erupcionado, puede provocar:", groups: [ { name: "Síntomas Clínicos", items: ["Dolor sordo y constante en la parte posterior de la mandíbula o en las encías", "Hinchazón, enrojecimiento y sangrado de la encía sobre el diente atrapado", "Dificultad o dolor agudo al abrir la boca o masticar", "Mal aliento persistente (halitosis) o mal sabor de boca debido a que las bacterias se acumulan debajo del colgajo de encía que cubre el diente parcialmente visible", "Dolor de cabeza o dolor que se irradia hacia el oído o el cuello"] } ], warning: "La inflamación del tejido de la encía que cubre una muela del juicio parcialmente incluida se llama pericoronaritis. Si no se trata, la infección puede causar un absceso que se extiende rápidamente a la garganta o el cuello, requiriendo hospitalización." }, types: { title: "Problemas y Complicaciones", intro: "Los dientes impactados no siempre deben extraerse, pero si causan problemas, suelen generar:", items: ["Daño a dientes adyacentes: El diente impactado empuja contra el diente vecino (segundo molar), causando caries en la raíz o absorción del hueso.", "Formación de Quistes: El saco que rodea al diente dentro del maxilar puede llenarse de líquido, formando un quiste que destruye el hueso de la mandíbula o daña los nervios cercanos.", "Enfermedad de las encías y Caries: Los dientes parcialmente incluidos son imposibles de limpiar correctamente con el cepillo, convirtiéndose en focos perfectos para bacterias invisibles."], note: "" }, causes: { title: "Causas Principales", intro: "El fallo en la erupción suele ser un problema físico y de espacio:", items: ["Falta de espacio en la arcada dental (mandíbulas pequeñas)", "Obstáculos físicos (dientes supernumerarios, quistes, o un diente de leche que no se cayó a tiempo)", "Posición o ángulo anormal del diente en desarrollo (creciendo horizontalmente o en un ángulo cerrado)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere visualización interna por parte del dentista o cirujano maxilofacial:", items: ["Examen clínico bucal (revisión de encías inflamadas o dientes faltantes en la edad correspondiente)", "Radiografía panorámica dental (Ortopantomografía): La prueba esencial. Muestra todos los dientes, las raíces, el ángulo exacto de la inclusión y la cercanía a nervios importantes (como el nervio dentario inferior).", "Tomografía Computarizada de Haz Cónico (CBCT): Una imagen en 3D que el cirujano solicita antes de la extracción si las raíces del diente están enredadas o pegadas a un nervio principal."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento depende de si el diente está causando daño, dolor o riesgo de infecciones:", subsections: [ { title: "Manejo Odontológico y Quirúrgico", items: ["Observación: Si el diente impactado (como una muela del juicio) está completamente enterrado en el hueso, profundo, sin causar dolor ni quistes y sin afectar al diente vecino, el dentista puede decidir simplemente vigilarlo anualmente con radiografías.", "Extracción Quirúrgica: Es el tratamiento más común. Realizada por un cirujano oral, a menudo bajo sedación o anestesia local. Se abre la encía, se retira el hueso que cubre el diente y, frecuentemente, el diente se corta en varios pedazos para extraerlo sin dañar los nervios o el hueso circundante.", "Exposición Ortodóntica (Fenestración y Tracción): Utilizado principalmente para caninos (colmillos) impactados. El cirujano abre la encía para exponer el diente atrapado y pega un pequeño botón (bracket) con una cadena de oro. Luego, el ortodoncista usa brackets para tirar lentamente de esa cadena durante meses, forzando al diente a salir a su posición correcta en la sonrisa."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a una revisión dental urgente si:", items: ["Tienes dolor pulsátil o inflamación severa en la parte posterior de la mandíbula", "Se te hincha la cara o el cuello, o tienes fiebre junto con dolor de muelas", "Tienes dificultad para abrir la boca completamente o tragar (trismo)"] } },
'Hidronefrosis' : { intro: "La hidronefrosis es la hinchazón y dilatación de uno o ambos riñones. Ocurre cuando la orina no puede drenar correctamente desde el riñón hacia la vejiga, provocando que se acumule y genere presión hacia atrás en el interior del tejido renal.", whatIs: { title: "¿Qué es la Hidronefrosis?", text: "Los riñones filtran la sangre y producen orina, la cual viaja por dos tubos (uréteres) hasta la vejiga. La hidronefrosis no es una enfermedad primaria, sino un signo físico de que existe un problema de plomería subyacente. Puede ser un bloqueo físico en las vías urinarias (uropatía obstructiva) o un problema donde la orina fluye hacia atrás desde la vejiga hacia los riñones (reflujo). Si esta presión interna no se alivia, puede dañar permanentemente las delicadas unidades de filtrado del riñón, causando insuficiencia renal." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen de si la obstrucción es aguda (súbita) o crónica (lenta), y de la causa:", groups: [ { name: "Síntomas de Obstrucción Aguda (Emergencia dolorosa)", items: ["Dolor repentino, punzante e insoportable en el costado de la espalda o el abdomen (cólico nefrítico)", "Dolor que se irradia hacia la ingle o los testículos/labios vaginales", "Náuseas intensas y vómitos", "Sangre visible en la orina (hematuria)", "Sudoración fría"] }, { name: "Síntomas de Obstrucción Crónica (Progresiva)", items: ["Suele ser asintomática o causar un dolor sordo y vago en la zona lumbar", "Necesidad frecuente de orinar o flujo urinario muy débil", "Infecciones del tracto urinario recurrentes (por la orina estancada)", "Fiebre y escalofríos si el riñón bloqueado se infecta"] } ], warning: "Un riñón bloqueado y lleno de orina estancada es altamente susceptible a infecciones graves. Si se desarrolla fiebre con hidronefrosis, es una urgencia médica que puede llevar rápidamente a una sepsis." }, types: { title: "Causas y Desencadenantes", intro: "Cualquier cosa que bloquee el flujo de orina puede causar hidronefrosis:", items: ["Cálculos renales (Piedras en el riñón): La causa más común en adultos jóvenes. Una piedra se atasca en el uréter o en la salida del riñón.", "Hiperplasia Prostática Benigna (HPB): En hombres mayores, una próstata agrandada aprieta la uretra, causando que la orina retroceda desde la vejiga hacia ambos riñones.", "Reflujo Vesicoureteral: La válvula entre la vejiga y el uréter falla, común en niños y bebés (a menudo detectado en ecografías antes de nacer).", "Embarazo: El útero agrandado puede presionar temporalmente los uréteres.", "Tumores o Cáncer: Tumores en la vejiga, próstata, útero, oclusión por cáncer de colon o ganglios inflamados en la pelvis.", "Estenosis o tejido cicatricial: Estrechamiento de los uréteres por cirugías previas o radioterapia."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El objetivo es confirmar la hinchazón del riñón y localizar exactamente dónde está el bloqueo:", items: ["Ecografía renal y vesical: La primera y mejor prueba no invasiva. Permite visualizar claramente la dilatación del riñón y a menudo identificar la causa (como una próstata grande o piedras).", "Tomografía Computarizada (TC) de abdomen y pelvis: Extremadamente precisa para localizar cálculos renales, tumores o evaluar el nivel exacto de la obstrucción.", "Análisis de orina y sangre: Para detectar infecciones (bacterias/glóbulos blancos) y medir la función renal (creatinina).", "Gammagrafía renal MAG3: Se inyecta un radioisótopo para ver exactamente qué tan bien fluye la orina a través de cada riñón y comparar su función."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en drenar la orina estancada lo antes posible y eliminar el bloqueo:", subsections: [ { title: "Intervenciones Urológicas", items: ["Drenaje de emergencia: Si el riñón está en peligro o infectado, el urólogo colocará un catéter doble J (stent ureteral) a través de la vejiga para mantener el uréter abierto, o insertará un tubo directamente a través de la espalda hacia el riñón (nefrostomía percutánea) para vaciar la orina hacia una bolsa externa.", "Tratamiento de piedras (Litotricia): Uso de ondas de choque o cirugía láser (ureteroscopia) para romper y extraer el cálculo que bloquea el conducto.", "Cirugía de próstata: Si el bloqueo es por HPB, se recetan medicamentos para encogerla o se realiza una resección prostática.", "Antibióticos intravenosos: Obligatorios e inmediatos si la hidronefrosis está acompañada de una infección urinaria o fiebre.", "Cirugía reparadora: Para el reflujo vesicoureteral en niños o estrechamientos cicatriciales."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención médica de urgencia si presentas:", items: ["Dolor severo e intenso en el costado o la parte baja de la espalda", "Fiebre alta, escalofríos y temblores inexplicables", "Incapacidad total para orinar o presencia de mucha sangre en la orina"] } },
'Pie cavo' : { intro: "El pie cavo es una deformidad estructural y biomecánica en la cual el arco de la planta del pie es anormalmente alto, incluso al estar de pie o aplicar peso sobre él. Es lo opuesto al pie plano.", whatIs: { title: "¿Qué es el Pie Cavo?", text: "Debido a que el arco no se aplana para absorber el impacto al caminar, el pie cavo concentra todo el peso y la presión del cuerpo en dos únicas zonas de contacto: el talón y la base de los dedos (metatarso). Este exceso de presión constante provoca dolor crónico, callosidades gruesas y alteraciones en la forma de los dedos. A menudo, el pie cavo está vinculado a problemas neurológicos subyacentes." }, symptoms: { title: "Síntomas y Señales Físicas", intro: "El pie cavo es muy rígido y poco flexible, lo que desencadena problemas en cadena:", groups: [ { name: "Problemas Mecánicos y de Dolor", items: ["Arco visiblemente muy elevado al estar de pie", "Dolor agudo o sordo en la 'bola' del pie (metatarsalgia) y en el talón al caminar o correr", "Aparición de durezas y callos muy dolorosos y gruesos bajo la base de los dedos, el talón o el borde externo del pie", "Deformidades en los dedos: Dedos en garra (los dedos se encogen fuertemente hacia abajo) o dedos en martillo, causados por la tensión de los tendones", "Inestabilidad crónica del tobillo: Facilidad constante para sufrir esguinces o torceduras al caminar en terrenos irregulares", "Dolor que se irradia hacia las rodillas, caderas o espalda baja debido a la mala amortiguación"] } ], warning: "Si el pie cavo aparece de forma progresiva en un solo pie en un adulto o adolescente, es una señal de advertencia de un posible trastorno del sistema nervioso o compresión de la médula espinal." }, types: { title: "Causas y Origen", intro: "Es fundamental determinar si el origen es una variante anatómica o una enfermedad progresiva:", items: ["Idiopático: Es simplemente la forma natural en que los huesos del paciente crecieron (hereditario), sin ninguna enfermedad oculta. El pie suele ser doloroso pero el arco no sigue elevándose con los años.", "Neurológico: La causa más importante y común. Enfermedades que causan debilidad muscular y desequilibrio nervioso fuerzan a los huesos a arquearse. Destacan la Enfermedad de Charcot-Marie-Tooth (la causa neurológica más frecuente), espina bífida, parálisis cerebral, distrofia muscular, o secuelas de poliomielitis o accidentes cerebrovasculares."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere una evaluación exhaustiva por ortopedia y neurología:", items: ["Examen físico y biomecánico: El especialista observa la marcha, la huella plantar (podograma o podoscopia) y comprueba la flexibilidad del pie.", "Examen Neurológico Completo: Obligatorio para buscar debilidad en los reflejos, pérdida de sensibilidad muscular o signos de enfermedad de Charcot-Marie-Tooth.", "Radiografías en carga (de pie): Para medir los ángulos exactos de los huesos y planificar posibles cirugías.", "Electromiografía (EMG): Si se sospecha una enfermedad neurológica, para evaluar la salud de los nervios de las piernas."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento no busca aplanar el arco, sino redistribuir el peso, evitar el dolor y estabilizar el tobillo:", subsections: [ { title: "Manejo Conservador y Ortopédico", items: ["Plantillas ortopédicas a medida (Soportes plantares): Es la piedra angular del tratamiento. No curan la deformidad, pero rellenan el arco y amortiguan las zonas de alto impacto, aliviando el dolor inmediatamente y previniendo callos y úlceras.", "Calzado especializado: Uso de zapatos con suela gruesa, base ancha, buena amortiguación y caña alta para evitar esguinces de tobillo.", "Fisioterapia: Ejercicios intensivos para estirar la fascia plantar tensa, los gemelos y el tendón de Aquiles, y fortalecer los músculos estabilizadores del tobillo.", "Manejo de callos: Eliminación regular de las callosidades por parte de un podólogo."] }, { title: "Tratamiento Quirúrgico", items: ["Cirugía: Si el dolor es incapacitante, hay inestabilidad extrema o la deformidad neurológica empeora rápidamente. Las operaciones pueden incluir la liberación de la fascia plantar (cortar la banda tensa), transferencia de tendones (mover músculos para reequilibrar la fuerza del pie), osteotomías (cortar y realinear los huesos del arco) o artrodesis (fusión de articulaciones para dar estabilidad permanente)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una derivación a ortopedia y neurología si:", items: ["Sientes dolor intenso al estar de pie que no se alivia con zapatos cómodos", "Desarrollas debilidad progresiva en las piernas, tropiezas frecuentemente o notas que el arco de tu pie se está volviendo cada vez más alto con los meses", "Sufres esguinces de tobillo a repetición"] } },
'Síndrome antifosfolípido' : { intro: "El síndrome antifosfolípido (SAF), a veces llamado síndrome de Hughes, es un trastorno autoinmunitario crónico y sistémico en el cual el sistema inmunológico produce anticuerpos anormales que aumentan drásticamente el riesgo de formar coágulos de sangre en venas y arterias, y causan complicaciones graves durante el embarazo.", whatIs: { title: "¿Qué es el Síndrome Antifosfolípido?", text: "Normalmente, los anticuerpos protegen el cuerpo contra las infecciones. En el SAF, el cuerpo produce anticuerpos que atacan por error a proteínas normales unidas a fosfolípidos (un tipo de grasa que recubre todas las células de los vasos sanguíneos). Este ataque hace que la sangre sea 'pegajosa' o hipercoagulable. Es una causa principal e invisible de derrames cerebrales en personas jóvenes, ataques cardíacos, trombosis venosas profundas y abortos espontáneos recurrentes." }, symptoms: { title: "Síntomas y Eventos Médicos", intro: "El SAF puede ser silencioso hasta que ocurre un evento traumático de coagulación:", groups: [ { name: "Complicaciones por Coágulos de Sangre (Trombosis)", items: ["Trombosis Venosa Profunda (TVP): Formación de coágulos en las piernas, causando dolor, hinchazón y enrojecimiento.", "Embolia Pulmonar (EP): Un coágulo de la pierna viaja a los pulmones, provocando dolor de pecho agudo, falta de aire repentina y riesgo de muerte.", "Accidente Cerebrovascular (EVC o Ictus): Derrames cerebrales en personas inusualmente jóvenes (menores de 50 años) sin otros factores de riesgo cardiovascular.", "Ataques al corazón prematuros y problemas en las válvulas cardíacas."] }, { name: "Complicaciones del Embarazo", items: ["Abortos espontáneos recurrentes o inexplicables (tres o más, especialmente en el primer trimestre)", "Muerte fetal tardía (después del primer trimestre)", "Preeclampsia severa o temprana (presión arterial alta extrema en el embarazo)", "Parto prematuro provocado por insuficiencia placentaria (los coágulos cortan el flujo de sangre y nutrientes al bebé)"] }, { name: "Síntomas Dermatológicos y Otros", items: ["Livedo reticularis: Un patrón de encaje rojo o púrpura y moteado en la piel, a menudo en las rodillas y muñecas.", "Niveles crónicamente bajos de plaquetas en la sangre (trombocitopenia).", "Migrañas crónicas y severas."] } ], warning: "El Síndrome Antifosfolípido Catastrófico (CAPS) es una variante rara pero mortal donde ocurren trombosis masivas simultáneas en múltiples órganos vitales (riñones, pulmones, cerebro) en cuestión de días. Es una emergencia crítica." }, types: { title: "Clasificación Autoinmune", intro: "El SAF puede presentarse solo o acompañado:", items: ["SAF Primario: Ocurre por sí solo, sin la presencia de otra enfermedad autoinmune.", "SAF Secundario: Ocurre junto con otra enfermedad autoinmune subyacente, con abrumadora frecuencia asociado al Lupus Eritematoso Sistémico (LES)."], note: "Tener los anticuerpos en la sangre no significa necesariamente que tengas la enfermedad; se requiere haber sufrido un evento clínico (trombosis o problemas de embarazo) para el diagnóstico oficial." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es estricto y requiere un historial de coágulos o pérdida de embarazos combinado con análisis de sangre específicos:", items: ["Pruebas de sangre para tres autoanticuerpos: Anticoagulante lúpico, Anticuerpos anticardiolipina y Anticuerpos anti-beta-2 glicoproteína I.", "Confirmación repetida: Dado que las infecciones normales pueden causar picos temporales en estos anticuerpos, las pruebas deben resultar positivas al menos dos veces, con una separación mínima de 12 semanas, para confirmar el diagnóstico definitivo."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo del tratamiento es diluir la sangre lo suficiente para evitar coágulos mortales y proteger los embarazos:", subsections: [ { title: "Manejo Médico y Anticoagulación", items: ["Anticoagulantes de por vida: Pacientes que ya han sufrido un coágulo (TVP, embolia o derrame) generalmente deben tomar anticoagulantes (Warfarina/Sintrom) durante el resto de su vida. Requieren análisis de sangre regulares (INR) para vigilar que la sangre no esté ni muy espesa ni muy líquida.", "Tratamiento en el Embarazo: Las mujeres embarazadas con SAF no pueden tomar Warfarina (causa defectos congénitos). Se tratan con inyecciones diarias de heparina de bajo peso molecular bajo la piel, combinadas con una dosis baja de Aspirina. Esto aumenta enormemente las posibilidades de un embarazo exitoso (del 20% al 80%).", "Prevención en portadores sanos: Las personas que tienen los anticuerpos pero nunca han tenido un coágulo a menudo toman solo Aspirina infantil diaria y se les prohíbe fumar o tomar anticonceptivos orales (ya que los estrógenos aumentan el riesgo de trombosis)."] } ], note: "Los nuevos anticoagulantes orales directos (como Apixabán o Rivaroxabán) generalmente no se recomiendan para el SAF, ya que los estudios han demostrado un mayor riesgo de trombosis recurrente en comparación con la Warfarina tradicional." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita evaluación con reumatología o hematología si:", items: ["Has sufrido dos o más abortos espontáneos, muertes fetales inexplicables o complicaciones muy graves en el embarazo", "Has tenido un coágulo de sangre en las piernas o pulmones, o un derrame cerebral a una edad temprana", "Se te ha diagnosticado Lupus y nunca te han hecho la prueba para SAF"] } },
'Eyaculación retrasada en el sexo' : { intro: "La eyaculación retrasada en el sexo es una disfunción sexual masculina en la que se necesita un período anormalmente largo de estimulación sexual penetrativa o manual para lograr la eyaculación y el orgasmo, o en la que existe una incapacidad total para alcanzarlo a pesar del deseo y de mantener una erección firme.", whatIs: { title: "¿Qué es la Eyaculación Retrasada?", text: "A diferencia de la disfunción eréctil (problemas de erección) o la eyaculación precoz (clímax muy rápido), aquí el mecanismo físico del orgasmo se ve obstaculizado. El hombre puede mantener el coito durante 30, 45 o 60 minutos hasta la fatiga extrema, sin llegar al clímax. A menudo se clasifica como 'situacional' (el hombre puede eyacular fácilmente masturbándose solo, pero no durante el sexo con su pareja) o 'generalizada' (no puede eyacular bajo ninguna circunstancia). Esta condición causa un inmenso agotamiento físico, pérdida de placer y un severo impacto emocional en la relación de pareja." }, symptoms: { title: "Síntomas y Señales Clínicas", intro: "Los problemas se manifiestan tanto física como psicológicamente durante la intimidad:", groups: [ { name: "Problemas en la Dinámica Sexual", items: ["Demora prolongada (típicamente más de 30 minutos) de intensa actividad sexual directa requerida para alcanzar el orgasmo, muy por encima de lo que el paciente o su pareja desean", "Incapacidad total para eyacular vaginal o analmente, obligando al hombre a terminar masturbándose a sí mismo (frecuentemente requiriendo fantasías o estímulos muy específicos)", "Pérdida de la erección por puro agotamiento físico o frustración antes de alcanzar el clímax", "Sensación de dolor, irritación o excoriación en los genitales propios o de la pareja debido a la fricción prolongada", "Sentimientos de ansiedad severa ('ansiedad de desempeño') que comienzan incluso antes del encuentro sexual"] } ], warning: "La pareja a menudo internaliza este problema de forma dolorosa, asumiendo erróneamente que no son lo suficientemente atractivas, que el hombre no las desea, o que es una señal de infidelidad, lo que genera resentimiento y distanciamiento rápido." }, types: { title: "Causas y Factores Desencadenantes", intro: "La eyaculación retrasada es clásicamente un problema biopsicosocial, con raíces superpuestas:", items: ["Medicamentos (La causa física más común): Efecto secundario notorio y universal de los antidepresivos ISRS (Sertralina, Fluoxetina, Paroxetina). También por analgésicos fuertes, ansiolíticos, o medicinas para la presión y la próstata.", "Estilo de Masturbación (Síndrome de Agarre Fuerte / Desensibilización): Condicionamiento neurológico por años de masturbación con un agarre excesivamente fuerte, alta velocidad, posiciones inusuales o estímulos pornográficos extremos que una pareja humana (una vagina o boca) anatómicamente no puede replicar con la misma presión y fricción.", "Factores Psicológicos y Emocionales: Depresión oculta, conflictos no resueltos con la pareja, miedo extremo a un embarazo, puritanismo/culpa religiosa, o trauma por abuso pasado.", "Causas Neurológicas y Hormonales: Envejecimiento natural, neuropatía por diabetes mal controlada, daño en los nervios pélvicos por cirugía de próstata o espalda baja, y niveles muy bajos de testosterona."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo o médico especialista en salud sexual llevará a cabo:", items: ["Revisión exhaustiva de la lista de medicamentos, drogas o consumo de alcohol crónico", "Entrevista psicológica e historial sexual muy detallado (para descubrir cuándo ocurre, con quién, y qué tipo de estimulación sí logra el orgasmo)", "Análisis de sangre para descartar diabetes, problemas de tiroides o déficit de testosterona", "Examen físico para verificar la sensibilidad nerviosa de los genitales"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento está estrictamente guiado por la causa subyacente. No existe una 'pastilla mágica' universal (como la Viagra para las erecciones) para este problema orgásmico:", subsections: [ { title: "Intervenciones Médicas y Terapéuticas", items: ["Ajuste de Fármacos: Si la culpa es de un antidepresivo, el psiquiatra debe reducir la dosis cuidadosamente o cambiar a otro fármaco que no afecte la eyaculación (como el Bupropión). NUNCA suspendas un antidepresivo de golpe por tu cuenta.", "Reeducación Sensorial (Terapia de Masturbación): Si hay un acondicionamiento físico, se prescribe suspender completamente la pornografía y la masturbación solitaria durante un periodo prolongado para 'reiniciar' la sensibilidad del cerebro y del pene a estímulos más suaves y naturales con la pareja.", "Terapia Sexual y de Pareja: Aborda la ansiedad por el desempeño. Se instruye a las parejas a enfocarse en la intimidad y el placer sin la meta estricta del orgasmo, eliminando la 'presión' del reloj y mejorando la comunicación.", "Medicamentos 'Off-label': En casos selectos, médicos recetan fármacos que aumentan la excitación cerebral (como Amantadina, Cabergolina o Ciproheptadina) aunque no estén diseñados exclusivamente para esto, o tratan la deficiencia de testosterona si la hay."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es altamente recomendable consultar a un urólogo o terapeuta sexual certificado si:", items: ["El retraso o la falta de eyaculación genera discusiones, estrés, evitación del sexo o daña profundamente tu relación de pareja", "Deseas tener hijos con tu pareja y la afección está impidiendo el embarazo", "El problema apareció bruscamente después de iniciar un nuevo tratamiento médico o sufrir una lesión en la espalda"] } },
'Espondilolistesis' : { intro: "La espondilolistesis es una afección de la columna vertebral en la cual una de las vértebras (los huesos que forman la columna) se desliza hacia adelante sobre el hueso que se encuentra inmediatamente debajo de ella.", whatIs: { title: "¿Qué es la Espondilolistesis?", text: "La columna vertebral es una estructura fuerte y alineada, sostenida por pequeñas articulaciones (facetas) y ligamentos. Cuando estas estructuras se debilitan, se desgastan o se fracturan (especialmente en la región lumbar inferior o la base de la espalda), la vértebra pierde su agarre y se desliza hacia adelante. Si se desliza demasiado, puede presionar o pellizcar los nervios espinales o la propia médula espinal, causando dolor severo y debilidad en las piernas." }, symptoms: { title: "Síntomas y Alertas Neurológicas", intro: "Muchas personas con espondilolistesis leve no saben que la tienen. Si causa síntomas, estos típicamente incluyen:", groups: [ { name: "Síntomas Mecánicos y Dolor", items: ["Dolor lumbar crónico y persistente (el síntoma más común) que empeora con la actividad, al estar de pie o al inclinarse hacia atrás, y se alivia al sentarse o descansar", "Tensión, espasmos y rigidez extrema en los músculos isquiotibiales (la parte posterior de los muslos)", "Cambios en la postura: En casos graves, la persona camina con una postura rígida, inclinada hacia adelante, y con las rodillas ligeramente dobladas"] }, { name: "Síntomas por Compresión Nerviosa (Radiculopatía)", items: ["Dolor punzante, ardor o sensación de electricidad que baja por una o ambas piernas (ciática)", "Entumecimiento, hormigueo pesado o debilidad en los pies, tobillos o piernas", "Dificultad para caminar largas distancias (claudicación neurogénica)"] } ], warning: "Si experimentas una pérdida repentina de sensibilidad en la zona genital o incapacidad para controlar la orina o las heces (Síndrome de Cola de Caballo), acude a urgencias inmediatamente. Es una emergencia quirúrgica." }, types: { title: "Tipos de Espondilolistesis", intro: "Se clasifican según la causa fundamental del deslizamiento:", items: ["Espondilolistesis Istmica: Común en atletas jóvenes (gimnastas, levantadores de pesas, jugadores de fútbol americano). Ocurre por fracturas por estrés en una parte frágil del hueso (la pars interarticularis) debido al esfuerzo físico repetitivo y la hiperextensión de la espalda.", "Espondilolistesis Degenerativa: La más frecuente en adultos mayores de 50 años. El envejecimiento, la artrosis y la deshidratación de los discos debilitan las articulaciones vertebrales, permitiendo que la vértebra resbale lentamente.", "Espondilolistesis Congénita: Nacer con huesos de la columna anormalmente formados.", "Espondilolistesis Traumática o Patológica: Debida a un accidente severo, o a huesos destruidos por tumores o infecciones."], note: "Se mide en grados del I al IV: Grado I es un deslizamiento de hasta el 25%, mientras que el Grado IV es un desplazamiento casi total." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista en columna (traumatólogo o neurocirujano) la identificará mediante pruebas de imagen:", items: ["Radiografías de la columna lumbar (de pie, de lado, y en flexión/extensión): Es la prueba principal y crucial para diagnosticarla. Mide exactamente qué tanto se ha deslizado el hueso y si el deslizamiento es 'inestable' (se mueve más al doblar la espalda).", "Resonancia Magnética (RM): Se solicita de inmediato si el paciente tiene dolor en las piernas o debilidad, ya que muestra con detalle los discos, los nervios pellizcados y la médula espinal.", "Tomografía Computarizada (TC): Para examinar en detalle la estructura del hueso y detectar microfracturas por estrés en la 'pars' no visibles en radiografías simples."], note: "" }, treatment: { title: "Tratamientos", intro: "El manejo busca estabilizar la columna y aliviar el dolor, comenzando siempre por métodos conservadores si no hay daño nervioso grave:", subsections: [ { title: "Manejo Conservador (Primera Línea)", items: ["Reposo de actividades agravantes: Prohibir deportes que requieran hiperextensión de la espalda (como la gimnasia).", "Fisioterapia especializada: El pilar del tratamiento. Ejercicios dirigidos para fortalecer poderosamente la faja abdominal (core) y estirar intensamente los isquiotibiales. Un 'corsé muscular' natural previene que la vértebra se deslice más.", "Medicamentos e Inyecciones: AINEs (Ibuprofeno) para el dolor. Si hay ciática grave, las inyecciones epidurales de corticosteroides guiadas por rayos X alivian drásticamente la inflamación de los nervios.", "Ortesis (Corsés rígidos): A veces usados en niños o adolescentes con fracturas por estrés recientes para inmovilizar la columna y permitir que el hueso sane."] }, { title: "Tratamiento Quirúrgico", items: ["Fusión Espinal Lumbar: Recomendada si el dolor es incapacitante tras 6 meses de terapia, el hueso sigue deslizándose, o hay debilidad neurológica en las piernas. El cirujano alivia la presión sobre los nervios (descompresión/laminectomía) y luego alinea y une la vértebra deslizada a la de abajo usando injertos óseos, barras y tornillos de titanio para bloquear el movimiento permanentemente y curar el dolor."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una evaluación médica ortopédica si:", items: ["Tu dolor de espalda baja persiste por más de unas pocas semanas y empeora progresivamente", "El dolor baja claramente por debajo de tus glúteos y hacia tus piernas", "Sientes debilidad, entumecimiento o tropiezas al caminar"] } },
'Temblor' : { intro: "El temblor es un trastorno del movimiento caracterizado por una contracción y relajación muscular rítmica e involuntaria que provoca movimientos de oscilación en una o más partes del cuerpo.", whatIs: { title: "¿Qué es un Temblor?", text: "Aunque los temblores pueden ocurrir en cualquier momento, a menudo afectan las manos, brazos, cabeza, cuerdas vocales, torso o piernas. No son una enfermedad en sí, sino un síntoma de un problema neurológico o de otra condición médica. Pueden ser intermitentes o constantes." }, symptoms: { title: "Síntomas Comunes", intro: "Las manifestaciones físicas incluyen:", groups: [ { name: "Signos Motores", items: ["Movimiento rítmico y tembloroso en las manos, brazos, cabeza o piernas", "Dificultad para escribir o dibujar", "Problemas para sostener y usar utensilios, como una cuchara o un vaso", "Voz temblorosa o inestable"] } ], warning: "Un temblor repentino y de nueva aparición, especialmente si se acompaña de otros síntomas neurológicos como debilidad muscular o problemas para hablar, requiere evaluación médica urgente." }, types: { title: "Tipos de Temblores", intro: "Se clasifican según cuándo y cómo ocurren:", items: ["Temblor esencial: El tipo más común; suele ocurrir al realizar acciones como sostener un vaso (temblor de acción).", "Temblor de reposo: Ocurre cuando el músculo está relajado, típico en la enfermedad de Parkinson.", "Temblor fisiológico: Un temblor muy fino y normal que todos tenemos, pero que se intensifica por estrés, ansiedad o fatiga.", "Temblor cerebeloso: Temblor de intención que empeora a medida que se acerca al final de un movimiento voluntario."] }, causes: { title: "Causas y Factores de Riesgo", intro: "El origen del temblor puede ser muy variado:", items: ["Trastornos neurológicos (Esclerosis múltiple, accidente cerebrovascular, lesión cerebral traumática)", "Enfermedad de Parkinson o condiciones neurodegenerativas", "Trastornos de la tiroides (Hipertiroidismo)", "Consumo excesivo de cafeína o abuso crónico de alcohol (y abstinencia)", "Efecto secundario de ciertos medicamentos (para el asma, corticosteroides, antidepresivos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El neurólogo realizará una evaluación exhaustiva:", items: ["Examen neurológico (para evaluar reflejos, tono muscular, postura y marcha)", "Pruebas de rendimiento (escribir, dibujar una espiral, sostener un objeto)", "Análisis de sangre (para descartar problemas de tiroides o niveles anormales de químicos)", "Electromiograma (EMG) para medir la actividad muscular y la respuesta nerviosa"] }, treatment: { title: "Tratamientos", intro: "El tratamiento depende de la causa subyacente y de la severidad:", subsections: [ { title: "Opciones de Manejo", items: ["Medicamentos: Betabloqueantes (Propranolol) o anticonvulsivos (Primidona) son efectivos para el temblor esencial. Fármacos dopaminérgicos para el Parkinson.", "Terapia física y ocupacional: Ejercicios para mejorar el control muscular, la fuerza y la coordinación, además del uso de dispositivos adaptativos.", "Inyecciones de toxina botulínica (Botox): Útiles para temblores focales en la cabeza o las cuerdas vocales.", "Cirugía: Estimulación cerebral profunda (DBS), donde se implantan electrodos en el cerebro para bloquear las señales que causan el temblor, en casos severos y resistentes a la medicación."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico o neurólogo si:", items: ["El temblor interfiere significativamente con tus actividades diarias", "El temblor empeora progresivamente", "Aparece por primera vez o se acompaña de otros síntomas inusuales"] } },
'Anquiloglosia' : { intro: "La anquiloglosia, comúnmente conocida como frenillo lingual corto o lengua atada, es una afección congénita en la cual una banda de tejido inusualmente corta, gruesa o tensa une la parte inferior de la lengua a la base de la boca.", whatIs: { title: "¿Qué es la Anquiloglosia?", text: "Normalmente, el frenillo lingual se separa antes del nacimiento, permitiendo a la lengua un amplio rango de movimiento. En los bebés con anquiloglosia, esta separación no ocurre completamente. Esto puede restringir la movilidad de la lengua, lo que a menudo interfiere de manera significativa con la lactancia materna, y más adelante, puede afectar el habla y la higiene bucal." }, symptoms: { title: "Síntomas y Señales", intro: "Los signos son más evidentes durante la alimentación del bebé:", groups: [ { name: "En Bebés (Problemas de Lactancia)", items: ["Dificultad profunda para agarrarse al pezón (succión deficiente)", "Chasquidos al amamantar o pérdida de leche por las comisuras", "Poco aumento de peso en el bebé", "Dolor severo o daño en los pezones de la madre durante la lactancia"] }, { name: "Signos Físicos y en Niños Mayores", items: ["La lengua tiene forma de corazón o muesca en forma de 'V' al intentar sacarla", "Incapacidad para levantar la lengua hacia los dientes superiores o moverla de lado a lado", "Dificultad para pronunciar ciertos sonidos (t, d, z, s, th, r, l)"] } ], warning: "Si la anquiloglosia no se aborda cuando causa problemas de alimentación, puede llevar al destete precoz, desnutrición en el bebé y frustración extrema en la madre." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es una anomalía en el desarrollo embrionario:", items: ["El frenillo lingual simplemente no se retrae y acorta como debería durante el desarrollo fetal", "Genética: Tiende a darse en familias y es más común en niños que en niñas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico se realiza mediante inspección física:", items: ["Examen visual detallado de la boca del bebé por parte del pediatra, dentista pediátrico o consultor de lactancia", "Evaluación de la movilidad de la lengua y su elevación", "Evaluación directa de la toma de leche (observar cómo se alimenta el bebé)"] }, treatment: { title: "Tratamientos", intro: "El tratamiento es necesario solo si la condición causa problemas funcionales:", subsections: [ { title: "Opciones de Manejo", items: ["Observación: Si no hay problemas de alimentación, muchos casos leves se estiran y resuelven por sí solos con el tiempo.", "Terapia de lactancia: Trabajar con un consultor puede ayudar a mejorar la técnica de agarre sin necesidad de cirugía en casos moderados.", "Frenotomía: Un procedimiento rápido en consulta donde el médico corta el frenillo con tijeras estériles o láser. Es muy rápido y la molestia es mínima.", "Frenuloplastia: Un procedimiento quirúrgico bajo anestesia general para casos de frenillos muy gruesos o reparaciones complejas, requiriendo puntos de sutura."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca evaluación médica si:", items: ["Tu bebé tiene grandes dificultades para amamantar o no gana peso", "La lactancia te causa dolor insoportable o lesiones", "Tu hijo mayor tiene problemas evidentes con el habla o para lamer un helado"] } },
'Proctitis' : { intro: "La proctitis es la inflamación aguda o crónica del revestimiento interno (mucosa) del recto, la porción final del intestino grueso que termina en el ano.", whatIs: { title: "¿Qué es la Proctitis?", text: "Esta inflamación puede causar molestias significativas, dolor y una sensación constante y urgente de tener que defecar, incluso cuando los intestinos están vacíos. Puede ser un problema aislado y temporal o un síntoma de una enfermedad inflamatoria intestinal más amplia o de una infección." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas se localizan en la región anal y rectal:", groups: [ { name: "Síntomas Digestivos y Locales", items: ["Tenesmo: Una sensación persistente, a menudo dolorosa, de necesidad urgente de defecar", "Dolor en el recto, el ano o en la región pélvica", "Sangrado rectal (ver sangre roja brillante en las heces o en el papel higiénico)", "Aparición de mucosidad espesa o secreción purulenta por el recto", "Diarrea o dolor intenso durante la evacuación", "Dolor y calambres abdominales en el lado izquierdo"] } ], warning: "El sangrado rectal nunca debe ignorarse. Aunque a menudo es causado por afecciones benignas, siempre debe ser evaluado por un médico para descartar patologías graves." }, types: { title: "Causas y Desencadenantes", intro: "La inflamación puede tener múltiples orígenes:", items: ["Infecciones de Transmisión Sexual (ITS): Principalmente gonorrea, clamidia, sífilis y herpes genital, adquiridas a través del sexo anal receptivo.", "Enfermedad Inflamatoria Intestinal (EII): Como la enfermedad de Crohn o la colitis ulcerosa (en este caso, la proctitis es a menudo el primer signo).", "Proctitis por Radiación: Efecto secundario común después de recibir radioterapia para el cáncer de próstata o cuello uterino.", "Infecciones intestinales: Por bacterias como Salmonella, Campylobacter o infecciones intestinales por el uso reciente de antibióticos (C. difficile)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El gastroenterólogo requiere evaluar directamente el tejido inflamado:", items: ["Análisis de heces: Para descartar infecciones bacterianas, parasitarias o toxinas.", "Cultivo rectal: Un hisopado del recto para buscar ITS.", "Proctoscopia o Sigmoidoscopia: El médico inserta un tubo iluminado en el recto para inspeccionar visualmente el revestimiento y evaluar el nivel de inflamación.", "Biopsia: Extracción de un pequeño fragmento de tejido durante la endoscopia para analizarlo al microscopio y confirmar, por ejemplo, una enfermedad inflamatoria intestinal."] }, treatment: { title: "Tratamientos", intro: "El tratamiento debe dirigirse específicamente a la causa subyacente:", subsections: [ { title: "Manejo Médico", items: ["Antibióticos o Antivirales: Recetados si la proctitis es causada por una infección de transmisión sexual o bacteriana.", "Medicamentos Antiinflamatorios: Supositorios, enemas o espumas rectales que contienen mesalamina o corticosteroides, muy efectivos para tratar la inflamación localizada de la EII o por radiación.", "Tratamientos Sistémicos: Si la causa es la enfermedad de Crohn o la colitis ulcerosa extendida, se requieren medicamentos inmunosupresores o terapias biológicas orales o intravenosas.", "Ablación térmica (Argón Plasma): En casos severos de proctitis por radiación con sangrado crónico, se utiliza coagulación láser para sellar los vasos sangrantes."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico con prontitud si presentas:", items: ["Sangrado rectal persistente, secreción mucosa abundante o dolor intenso al ir al baño", "Sensación constante de necesitar defecar sin alivio", "Estos síntomas acompañados de fiebre o escalofríos"] } },
'Condromalacia patelar' : { intro: "La condromalacia patelar, a menudo conocida como 'rodilla de corredor', es el reblandecimiento y deterioro del cartílago articular que se encuentra en la parte inferior de la rótula (patela).", whatIs: { title: "¿Qué es la Condromalacia Patelar?", text: "Normalmente, la rótula se desliza suavemente sobre un surco en el fémur al doblar la rodilla. En esta condición, el cartílago que actúa como amortiguador en la cara interna de la rótula se desgasta, ablanda o fisura. Esto causa que la rótula roce directamente contra el fémur, provocando inflamación crónica, dolor y una sensación de fricción." }, symptoms: { title: "Síntomas Comunes", intro: "El dolor es altamente dependiente de la actividad mecánica:", groups: [ { name: "Síntomas Mecánicos y Dolor", items: ["Dolor sordo, sordo y persistente en la parte frontal de la rodilla, debajo o alrededor de la rótula", "El dolor empeora al subir y, especialmente, al bajar escaleras o pendientes", "Signo de la butaca: Dolor agudo después de estar sentado con las rodillas dobladas durante un tiempo prolongado (como en el cine o en un avión)", "Sensación de rozamiento, crujidos o chasquidos audibles (crepitación) al doblar y estirar la rodilla", "Hinchazón leve alrededor del área de la rótula"] } ], warning: "Si no se corrige la biomecánica que causa el roce, la condromalacia puede progresar hacia una osteoartritis patelofemoral prematura y permanente." }, causes: { title: "Causas y Factores de Riesgo", intro: "Suele ser una lesión por sobrecarga y mala alineación:", items: ["Mala alineación de la rótula: Los músculos no tiran de la rótula de forma recta, haciendo que frote contra un lado del surco del fémur.", "Desequilibrio muscular: Debilidad en los músculos cuádriceps (especialmente el vasto medial) y tensión en los isquiotibiales y la banda iliotibial.", "Sobrecarga repetitiva: Correr, saltar, hacer sentadillas o andar en bicicleta con alta intensidad o sin preparación adecuada.", "Anatomía: Pies planos o rodillas en valgo ('en X') aumentan la tensión en el ángulo de la rótula.", "Trauma directo: Un golpe fuerte en la rótula o una luxación previa."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico suele ser suficiente:", items: ["Examen físico: El traumatólogo presiona la rótula y evalúa la alineación, el dolor al movimiento y la fuerza del cuádriceps.", "Prueba de compresión rotuliana (Signo de Zohlen).", "Radiografías: Útiles para ver la alineación de la rótula en su surco y descartar artritis severa.", "Resonancia Magnética (RM): La mejor prueba para ver el estado real del cartílago blando y detectar fisuras tempranas (no visibles en rayos X)."] }, treatment: { title: "Tratamientos", intro: "El tratamiento inicial es conservador y se basa en la rehabilitación física:", subsections: [ { title: "Manejo y Rehabilitación", items: ["Reposo y Modificación de la Actividad: Evitar actividades de impacto, sentadillas y escaleras hasta que baje la inflamación.", "Hielo y Medicamentos: Aplicar frío tras el ejercicio y tomar AINEs (Ibuprofeno) para controlar el dolor inicial.", "Fisioterapia: Es el tratamiento más crucial. Ejercicios focalizados para fortalecer el músculo cuádriceps (vasto medial oblicuo) y estabilizar la pelvis, para que la rótula vuelva a deslizarse correctamente en el centro del surco.", "Rodilleras o cintas (Taping): El vendaje neuromuscular (Kinesiotaping) o las rodilleras con orificio patelar ayudan a guiar la rótula mecánicamente durante el movimiento.", "Cirugía (Artroscopia): Reservada para casos crónicos severos que no mejoran en meses. El cirujano alisa el cartílago dañado o realiza una liberación lateral para realinear la tensión de la rótula."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un fisioterapeuta o traumatólogo si:", items: ["El dolor en la parte delantera de la rodilla persiste por más de un par de semanas a pesar de hacer reposo", "La rodilla duele intensamente al bajar escaleras o comienza a hincharse", "Sientes que la rodilla se bloquea, se traba o 'crashea' al moverla"] } },
'Insuficiencia respiratoria' : { intro: "La insuficiencia respiratoria es una condición clínica grave y potencialmente letal en la cual el sistema respiratorio falla en su función principal: no puede suministrar suficiente oxígeno a la sangre, ni tampoco eliminar adecuadamente el dióxido de carbono.", whatIs: { title: "¿Qué es la Insuficiencia Respiratoria?", text: "Nuestros pulmones tienen un propósito dual: tomar oxígeno del aire para enviarlo a los órganos (oxigenación) y expulsar el dióxido de carbono, un gas de desecho tóxico (ventilación). Cuando hay una falla profunda en este sistema, ya sea por daño pulmonar directo, debilidad de los músculos respiratorios o problemas en el cerebro, los órganos del cuerpo comienzan a sufrir y pueden fallar rápidamente debido a la falta de oxígeno o la acidez generada por el dióxido de carbono acumulado." }, symptoms: { title: "Síntomas y Signos Críticos", intro: "Los síntomas pueden desarrollarse rápidamente (aguda) o lentamente (crónica):", groups: [ { name: "Síntomas Respiratorios y Físicos", items: ["Falta de aliento extrema, respiración muy rápida y superficial (taquipnea)", "Sensación de asfixia o 'hambre de aire', incluso estando en reposo", "Cianosis: Coloración azulada o grisácea en la piel, los labios o debajo de las uñas debido a niveles críticos de oxígeno", "Sudoración profusa y uso visible de los músculos del cuello y pecho para intentar respirar (tiraje)"] }, { name: "Síntomas Neurológicos y Cardiovasculares", items: ["Confusión mental, desorientación profunda, ansiedad severa o letargo (signos de que el cerebro no recibe oxígeno o está intoxicado con CO2)", "Somnolencia extrema que puede llevar a la pérdida de conocimiento (coma)", "Ritmo cardíaco muy acelerado (taquicardia) o arritmias peligrosas"] } ], warning: "La insuficiencia respiratoria aguda es una emergencia médica máxima. La falta de oxígeno destruye el cerebro y el corazón en cuestión de minutos, y el exceso de dióxido de carbono actúa como un sedante letal." }, types: { title: "Tipos de Insuficiencia", intro: "Se clasifica según el gas que presenta problemas en la sangre:", items: ["Tipo I (Insuficiencia Hipoxémica): El nivel de oxígeno en la sangre es peligrosamente bajo, pero el nivel de dióxido de carbono es normal. (Causado típicamente por neumonía, edema pulmonar, COVID-19 grave o SDRA).", "Tipo II (Insuficiencia Hipercápnica): Hay demasiado dióxido de carbono en la sangre, acompañado a menudo por bajo oxígeno. La 'bomba' respiratoria falla al exhalar. (Causado por EPOC severa, asma grave, sobredosis de sedantes o enfermedades musculares como ELA)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "En urgencias, se requiere confirmación inmediata:", items: ["Gasometría arterial (ABG): La prueba fundamental. Se extrae sangre de una arteria (generalmente en la muñeca) para medir con precisión los niveles exactos de Oxígeno, Dióxido de Carbono y el pH (acidez) de la sangre.", "Pulsioximetría: Para un monitoreo rápido y continuo de la saturación de oxígeno.", "Radiografía de tórax o TC de tórax: Para identificar la causa (neumonía, líquido, pulmón colapsado).", "Electrocardiograma (ECG): Para asegurar que el corazón no está fallando."] }, treatment: { title: "Tratamientos", intro: "El manejo requiere ingreso a la Unidad de Cuidados Intensivos (UCI):", subsections: [ { title: "Soporte Vital y Médico", items: ["Oxigenoterapia: Suministro de oxígeno adicional mediante cánulas nasales de alto flujo o mascarillas.", "Ventilación Mecánica No Invasiva (VNI): Uso de máquinas (BiPAP o CPAP) que empujan aire a presión a través de una mascarilla ajustada para ayudar a mantener las vías abiertas y facilitar el trabajo respiratorio.", "Ventilación Mecánica Invasiva (Intubación): En casos extremos, se inserta un tubo por la garganta hasta la tráquea conectado a un respirador artificial que respira por el paciente.", "Tratamiento de la causa base: Antibióticos para neumonías, diuréticos para exceso de líquido, broncodilatadores y esteroides para asma o EPOC, o antídotos para sobredosis."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias (911) inmediatamente si una persona presenta:", items: ["Dificultad repentina, severa y desesperada para respirar", "Coloración azulada en los labios, el rostro o las uñas", "Aparición súbita de confusión mental profunda, somnolencia anormal o incapacidad para despertarse completamente"] } },
'Polidactilia' : { intro: "La polidactilia es una anomalía congénita bastante común caracterizada por la presencia de dedos supernumerarios (dedos adicionales) en las manos o en los pies al momento del nacimiento.", whatIs: { title: "¿Qué es la Polidactilia?", text: "Durante el desarrollo del embrión, las manos y los pies comienzan con forma de 'paleta' y luego se dividen en cinco dedos distintos. Si hay un error en esta división genética, se forma un dedo extra. Este dedo adicional puede ser simplemente un pequeño bulto de tejido blando sin hueso, o un dedo completamente formado y funcional con sus propios huesos, articulaciones y tendones." }, symptoms: { title: "Características y Clasificación", intro: "La presentación clínica es visual en el nacimiento. Los médicos la clasifican por su ubicación en la mano o el pie:", groups: [ { name: "Tipos por Ubicación", items: ["Polidactilia Preaxial: El dedo extra está en el lado del pulgar (o del dedo gordo del pie). Es menos común en la población general pero más asociada a orígenes genéticos específicos.", "Polidactilia Postaxial: El dedo extra está en el lado del meñique (o del dedo pequeño del pie). Es el tipo más común.", "Polidactilia Central: El dedo extra crece en medio de la mano o el pie, fusionado entre los dedos centrales. Es la más rara y compleja de reparar."] } ], warning: "Aunque la polidactilia aislada es inofensiva y solo un problema estético, a veces puede presentarse junto con otras anomalías como parte de un síndrome genético más complejo." }, causes: { title: "Causas y Origen", intro: "Se desarrolla por factores genéticos:", items: ["Herencia Autosómica Dominante: A menudo se transmite de padres a hijos. Si un padre tiene el gen, hay un 50% de probabilidad de pasarlo (común en la polidactilia postaxial).", "Mutaciones genéticas aisladas sin antecedentes familiares.", "Parte de un síndrome genético mayor (como el Síndrome de Ellis-van Creveld, Síndrome de Patau o Síndrome de Rubinstein-Taybi)."] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "El diagnóstico es evidente, pero requiere evaluación para planificar el tratamiento:", items: ["Examen físico en el recién nacido", "Radiografías (Rayos X) de la extremidad afectada (absolutamente necesario para ver la estructura interna: si el dedo extra tiene huesos completos, cómo se conecta a las articulaciones principales y qué ligamentos comparte)", "Examen físico sistémico y pruebas genéticas (si el pediatra sospecha que la polidactilia forma parte de un síndrome más amplio)"] }, treatment: { title: "Tratamientos", intro: "El tratamiento es la extirpación quirúrgica del dedo adicional, preferiblemente en la primera infancia (entre el primer y el segundo año de vida):", subsections: [ { title: "Procedimientos Quirúrgicos", items: ["Ligadura o Clip vascular (Solo para dedos de tejido blando): Si el dedo extra no tiene hueso y está unido por un hilo de piel, el médico a veces puede atar un clip o sutura ajustada en la base en el consultorio pediátrico, cortando el flujo sanguíneo hasta que el tejido cae por sí solo.", "Cirugía de Extirpación Menor: Para dedos extra pequeños que contienen hueso, se realiza una pequeña cirugía ambulatoria para extraerlo.", "Cirugía Reconstructiva Compleja: En casos de polidactilia central o preaxial (pulgares duplicados), la cirugía es muy meticulosa. El cirujano ortopédico no solo corta el dedo sobrante, sino que debe reconstruir los ligamentos, músculos y articulaciones del dedo restante para asegurar que el niño tenga un agarre fuerte y un pulgar o mano completamente funcional."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La polidactilia se detecta invariablemente al nacer en el hospital. Debes:", items: ["Consultar a un cirujano ortopédico infantil o cirujano plástico pediátrico poco después del alta para planificar la intervención y evaluar la anatomía ósea a tiempo"] } },
'Acromegalia' : { intro: "La acromegalia es un trastorno hormonal raro y crónico que ocurre cuando la glándula pituitaria (ubicada en la base del cerebro) produce cantidades excesivas de hormona del crecimiento (GH) durante la edad adulta.", whatIs: { title: "¿Qué es la Acromegalia?", text: "En los niños, un exceso de hormona del crecimiento causa 'gigantismo', haciendo que crezcan a estaturas anormalmente altas. Sin embargo, en los adultos, las placas de crecimiento de los huesos largos ya están cerradas, por lo que los huesos ya no pueden crecer en longitud. En cambio, en la acromegalia, el exceso de hormona hace que los huesos de las manos, los pies y el rostro aumenten en grosor y tamaño. Como la progresión es sumamente lenta, los pacientes a menudo no notan los cambios hasta que la enfermedad está muy avanzada." }, symptoms: { title: "Síntomas Comunes", intro: "Los cambios físicos son graduales pero característicos:", groups: [ { name: "Cambios Estructurales y Físicos", items: ["Agrandamiento anormal de manos y pies (necesidad de anillos o zapatos más grandes)", "Cambios faciales gruesos: ensanchamiento de la nariz, labios gruesos, mandíbula inferior sobresaliente (prognatismo) y separación de los dientes", "Agrandamiento de la frente y las cejas prominentes", "Engrosamiento de la piel, piel grasa y sudoración excesiva y maloliente", "Voz más profunda, grave y ronca debido al engrosamiento de las cuerdas vocales y senos paranasales"] }, { name: "Problemas Médicos y Sistémicos", items: ["Dolores articulares severos y movilidad reducida (osteoartritis secundaria)", "Fatiga extrema y debilidad muscular", "Dolores de cabeza crónicos y pérdida de visión periférica (por el tumor en el cerebro)", "Apnea del sueño severa (por el agrandamiento de la lengua y los tejidos del cuello)", "Problemas cardiovasculares (agrandamiento del corazón) y diabetes"] } ], warning: "Si no se trata, la acromegalia es una enfermedad grave que reduce la esperanza de vida, provocando hipertensión incontrolable, enfermedad cardíaca severa y mayor riesgo de cáncer de colon." }, causes: { title: "Causas Principales", intro: "El exceso hormonal tiene un origen muy específico:", items: ["Adenoma Pituitario: En más del 95% de los casos, la causa es un tumor benigno (no canceroso) en la glándula pituitaria que segrega hormona del crecimiento de forma autónoma.", "Tumores no pituitarios (Extremadamente raro): Tumores en los pulmones, páncreas u otras partes del cuerpo que secretan GH o la hormona liberadora de GH (GHRH)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Requiere análisis endocrinológicos especializados y neuroimagen:", items: ["Análisis de factor de crecimiento insulínico tipo 1 (IGF-1): Es la prueba más fiable. A diferencia de la GH (que fluctúa todo el día), el IGF-1 se mantiene estable; si está elevado, indica fuertemente acromegalia.", "Prueba de supresión de la hormona del crecimiento oral: Se mide el nivel de GH antes y después de beber un líquido muy dulce. En una persona sana, el azúcar hace que la GH baje; en la acromegalia, los niveles de GH se mantienen altos.", "Resonancia Magnética (RM) del Cerebro: Una vez confirmado el exceso hormonal en sangre, se utiliza para localizar el tumor pituitario y medir su tamaño y relación con los nervios ópticos."] }, treatment: { title: "Tratamientos", intro: "El objetivo es reducir la producción de GH a niveles normales, aliviar la presión sobre el cerebro y revertir o mejorar los síntomas:", subsections: [ { title: "Opciones Quirúrgicas y Médicas", items: ["Cirugía Transesfenoidal: Es el tratamiento de primera línea y la opción curativa principal. El neurocirujano extirpa el tumor de la pituitaria a través de la nariz. Si tiene éxito, los niveles de GH caen inmediatamente.", "Medicamentos (Análogos de Somatostatina): Fármacos como el Octreotida o Lanreotida, inyectados mensualmente, simulan una hormona natural del cerebro que bloquea la producción de GH. Se usan si la cirugía no logra curar el tumor por completo o si el paciente no puede operarse.", "Agonistas de la Dopamina o Antagonistas del Receptor de GH (Pegvisomant): Otros fármacos utilizados para bloquear el efecto del exceso de hormonas en el cuerpo.", "Radioterapia: Se usa como último recurso para destruir lentamente las células tumorales restantes si la cirugía y los medicamentos no han funcionado."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Visita a tu médico general o endocrinólogo si:", items: ["Notas que tus zapatos, guantes o anillos ya no te entran y tus manos lucen inusualmente 'hinchadas' permanentemente", "Amigos o familiares comentan que los rasgos de tu rostro han cambiado drásticamente en los últimos años", "Sufres de dolores de cabeza inexplicables combinados con dolor en las articulaciones y ronquidos extremos"] } },
'Adherencia intrauterina' : { intro: "Las adherencias intrauterinas, también conocidas clínicamente como Síndrome de Asherman, son formaciones de bandas de tejido cicatricial que unen o 'pegan' las paredes internas de la cavidad del útero.", whatIs: { title: "¿Qué es el Síndrome de Asherman?", text: "Normalmente, la cavidad del útero es un espacio abierto revestido de tejido suave (el endometrio) que se prepara mensualmente para un embarazo o se desprende durante la menstruación. Cuando ocurre un daño profundo en este revestimiento, la curación anormal crea cicatrices (adherencias) que actúan como puentes conectando las paredes del útero. Esto reduce drásticamente el espacio dentro de la matriz, altera el flujo menstrual y crea un ambiente hostil que impide que un embrión se implante, siendo una causa importante de infertilidad." }, symptoms: { title: "Síntomas Clínicos", intro: "Las alteraciones dependen de la gravedad y extensión de las cicatrices:", groups: [ { name: "Problemas Reproductivos y Menstruales", items: ["Hipomenorrea: Periodos menstruales muy escasos, cortos o con un flujo sumamente ligero", "Amenorrea: Ausencia total de la menstruación mensual a pesar de no estar en la menopausia", "Infertilidad severa o incapacidad para quedar embarazada", "Pérdida gestacional recurrente (abortos espontáneos tempranos continuos)", "Dolor pélvico o calambres intensos cíclicos en la época en que debería llegar el periodo, sin flujo de sangre (la sangre queda atrapada por cicatrices en el cuello uterino)"] } ], warning: "Si has pasado por un legrado uterino recientemente y tus periodos menstruales no han regresado a la normalidad después de varios meses, debes sospechar de adherencias intrauterinas." }, causes: { title: "Causas y Desencadenantes", intro: "Casi siempre son una complicación de un traumatismo físico en el útero:", items: ["Legrado uterino instrumentado (D&C): Es la causa principal (hasta el 90% de los casos). Frecuentemente ocurre si se realiza un raspado del útero después de un aborto espontáneo retenido, un aborto inducido o para extraer restos de placenta tras el parto.", "Cirugías uterinas previas (como la extirpación de miomas o pólipos por histeroscopia).", "Infecciones pélvicas severas (como tuberculosis genital, esquistosomiasis, o endometritis severa asociada a procedimientos obstétricos).", "Uso prolongado de dispositivos intrauterinos (DIU) infectados (raro)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere pruebas de imagen específicas del interior del útero:", items: ["Histeroscopia: Es el estándar de oro (la prueba más precisa). El médico inserta una pequeña cámara iluminada en el útero para ver directamente las paredes pegadas y las bandas de cicatriz.", "Histerosalpingografía (HSG): Un examen de rayos X en el que se inyecta un líquido de contraste en el útero para delinear su forma. En el Síndrome de Asherman, el líquido muestra 'defectos de llenado' donde el contraste no puede entrar debido a las cicatrices.", "Sonohisterografía (Ecografía con infusión salina): Se introduce líquido en el útero mientras se hace una ecografía para detectar las adherencias en las paredes separadas."], note: "La ecografía pélvica tradicional es insuficiente y a menudo no logra ver las adherencias intrauterinas." }, treatment: { title: "Tratamientos", intro: "El objetivo es restaurar la anatomía normal de la cavidad uterina y regenerar el endometrio sano:", subsections: [ { title: "Enfoque Quirúrgico y Hormonal", items: ["Histeroscopia Operatoria (Adhesiólisis): Es el tratamiento principal. El cirujano utiliza microtijeras o láser a través de la cámara para cortar cuidadosamente y retirar el tejido cicatricial, separando las paredes del útero. Nunca se debe intentar raspar a ciegas (legrado).", "Barreras Mecánicas postoperatorias: Al terminar la cirugía, es altísimo el riesgo de que el útero vuelva a pegarse mientras sana. Se colocan temporalmente geles de ácido hialurónico, un balón intrauterino pediátrico o un DIU en la cavidad para mantener las paredes separadas físicamente durante unas semanas.", "Terapia Hormonal: Se prescriben dosis muy altas de estrógenos seguidas de progesterona durante uno a tres meses para forzar al cuerpo a crear un revestimiento endometrial nuevo y grueso que cubra las zonas crudas."] } ], note: "La recurrencia de las adherencias es muy común, por lo que a menudo se requiere más de una histeroscopia antes de lograr el éxito reproductivo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un ginecólogo especialista o a una clínica de fertilidad si:", items: ["Tus menstruaciones han desaparecido o se han vuelto notablemente escasas después de haberte sometido a un aborto, legrado o cirugía en el útero", "Has tenido múltiples abortos espontáneos inexplicables", "Estás experimentando fuertes dolores cíclicos mensuales pero no presentas sangrado vaginal"] } },
'Anemia ferropénica' : { intro: "La anemia ferropénica es el tipo más común de anemia. Ocurre cuando el cuerpo no tiene suficiente hierro, un mineral esencial necesario para producir la hemoglobina, la proteína de los glóbulos rojos que transporta el oxígeno a los tejidos del cuerpo.", whatIs: { title: "¿Qué es la Anemia Ferropénica?", text: "Sin suficiente hierro, el cuerpo no puede producir suficientes glóbulos rojos sanos y estos se vuelven pequeños y pálidos. Al carecer del oxígeno necesario, los órganos y músculos no pueden funcionar de manera óptima, lo que provoca una sensación constante de cansancio profundo y debilidad generalizada." }, symptoms: { title: "Síntomas Comunes", intro: "La anemia leve suele pasar desapercibida, pero a medida que las reservas de hierro se agotan, aparecen:", groups: [ { name: "Síntomas Generales", items: ["Fatiga extrema y falta de energía", "Palidez evidente en la piel, las encías y el interior de los párpados", "Dificultad para respirar, latidos cardíacos rápidos o dolor en el pecho, especialmente al hacer ejercicio", "Mareos, dolores de cabeza y manos o pies fríos"] }, { name: "Signos Característicos por Falta de Hierro", items: ["Uñas quebradizas o en forma de cuchara (coiloniquia)", "Caída inusual del cabello", "Inflamación o dolor en la lengua (glositis)", "Antojos inusuales por sustancias no nutritivas como hielo, tierra o almidón (Pica)", "Síndrome de las piernas inquietas"] } ], warning: "Una anemia severa prolongada obliga al corazón a bombear más sangre para compensar la falta de oxígeno, lo que puede derivar en latidos irregulares o insuficiencia cardíaca." }, causes: { title: "Causas y Factores de Riesgo", intro: "El hierro se agota debido a tres mecanismos principales:", items: ["Pérdida de sangre crónica: Menstruaciones muy abundantes, sangrado gastrointestinal por úlceras, pólipos, uso crónico de analgésicos (ibuprofeno) o cáncer de colon.", "Falta de hierro en la dieta: Dietas veganas o vegetarianas mal planificadas, o bajo consumo de alimentos ricos en hierro.", "Mala absorción: Trastornos intestinales como la enfermedad celíaca o haberse sometido a una cirugía de bypass gástrico.", "Embarazo: La necesidad de hierro se duplica para apoyar el volumen sanguíneo de la madre y el desarrollo del feto."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un simple análisis de sangre es suficiente para detectarla:", items: ["Hemograma completo (CBC): Muestra niveles bajos de hemoglobina, hematocrito y glóbulos rojos más pequeños de lo normal (microcitosis).", "Pruebas de hierro: La ferritina sérica (que mide las reservas de hierro almacenadas) estará muy baja.", "Endoscopia o Colonoscopia: Si no hay una causa obvia (como la menstruación), se realizan para buscar úlceras sangrantes o tumores en el tracto digestivo."], note: "El diagnóstico no termina al encontrar la anemia; el médico siempre debe descubrir POR QUÉ se está perdiendo hierro." }, treatment: { title: "Tratamientos", intro: "El objetivo es restaurar los niveles de hierro y tratar la causa de la pérdida de sangre:", subsections: [ { title: "Opciones de Manejo", items: ["Suplementos de hierro orales (Sulfato o Gluconato ferroso): Se deben tomar con el estómago vacío o con vitamina C (zumo de naranja) para mejorar la absorción. No deben tomarse con antiácidos o leche.", "Hierro intravenoso (IV): Se administra en el hospital si el paciente no tolera las pastillas, tiene problemas graves de absorción o necesita una reposición muy rápida.", "Modificaciones en la dieta: Aumentar el consumo de carnes rojas, hígado, legumbres, espinacas y cereales fortificados.", "Tratamiento de la causa subyacente: Prescribir anticonceptivos para reducir el sangrado menstrual pesado o tratar úlceras estomacales."] } ], note: "Los suplementos de hierro orales a menudo causan efectos secundarios molestos como estreñimiento, náuseas y heces de color negro oscuro (lo cual es inofensivo)." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu médico o acude a urgencias si:", items: ["Sientes una fatiga abrumadora que te impide hacer tus tareas diarias", "Sientes que te falta el aire al caminar distancias cortas", "Notas que tus heces son de color negro alquitranado o tienen sangre visible (signo de sangrado interno)"] } },
'Posmenopausia' : { intro: "La posmenopausia es la etapa de la vida de una mujer que comienza después de haber pasado 12 meses consecutivos sin tener un período menstrual. No es una enfermedad, sino una fase biológica natural que abarca el resto de la vida de la mujer.", whatIs: { title: "¿Qué es la Posmenopausia?", text: "Durante esta etapa, los ovarios ya no liberan óvulos y la producción de hormonas reproductivas, principalmente los estrógenos y la progesterona, disminuye drásticamente y se mantiene en niveles permanentemente bajos. Aunque muchos de los síntomas molestos de la transición menopáusica (sofocos) comienzan a desvanecerse, la falta crónica de estrógenos aumenta significativamente el riesgo de padecer afecciones de salud a largo plazo, como la osteoporosis y las enfermedades cardiovasculares." }, symptoms: { title: "Cambios y Síntomas a Largo Plazo", intro: "Los síntomas varían de una mujer a otra; algunas sienten un gran alivio, mientras que otras experimentan problemas debido al déficit estrogénico:", groups: [ { name: "Síntomas Físicos y Genitourinarios", items: ["Sequedad, picazón y atrofia vaginal (las paredes de la vagina se vuelven más delgadas y menos elásticas)", "Dolor o molestias significativas durante las relaciones sexuales (dispareunia)", "Mayor frecuencia de infecciones del tracto urinario (IVU) e incontinencia urinaria leve", "Sofocos y sudores nocturnos (pueden persistir durante varios años en la posmenopausia)", "Aumento de peso, especialmente acumulación de grasa alrededor de la cintura", "Cambios en la textura de la piel y adelgazamiento del cabello"] }, { name: "Síntomas Emocionales", items: ["Cambios de humor, irritabilidad leve", "Dificultad para dormir o insomnio continuo", "Dificultades leves de concentración o memoria ('niebla mental')"] } ], warning: "Cualquier sangrado vaginal o manchado que ocurra durante la posmenopausia NO es normal. Aunque a veces es causado por atrofia benigna, es la principal señal de advertencia del cáncer de endometrio y requiere evaluación médica inmediata." }, types: { title: "Riesgos de Salud Asociados", intro: "El bajo nivel de estrógeno impacta silenciosamente en órganos vitales:", items: ["Osteoporosis: Los huesos pierden densidad rápidamente, volviéndose frágiles y propensos a fracturas severas de cadera, muñeca o columna.", "Enfermedades Cardiovasculares: El estrógeno protege los vasos sanguíneos; su caída aumenta rápidamente el colesterol malo (LDL) y el riesgo de infartos y derrames cerebrales.", "Síndrome Genitourinario de la Menopausia (SGM): Daño crónico a los tejidos pélvicos que afecta profundamente la calidad de vida sexual y urinaria."], note: "" }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "No se requiere un diagnóstico para la posmenopausia en sí, pero sí un monitoreo preventivo riguroso:", items: ["Revisión del historial clínico (confirmación de 12 meses sin regla)", "Análisis de sangre (FSH y Estradiol) solo si hay dudas en mujeres más jóvenes", "Densitometría ósea (DEXA scan) obligatoria para medir la fuerza de los huesos y detectar osteoporosis", "Exámenes pélvicos regulares, citologías, mamografías anuales y control estricto de la presión arterial y el colesterol"], note: "" }, treatment: { title: "Manejo y Prevención", intro: "El enfoque es mantener la salud preventiva y tratar los síntomas molestos:", subsections: [ { title: "Opciones Terapéuticas y de Estilo de Vida", items: ["Terapia de Reemplazo Hormonal (TRH): Uso de estrógenos (y progesterona si la mujer aún tiene útero) para aliviar sofocos severos y prevenir la pérdida ósea. Debe ser prescrita a la menor dosis efectiva y por el menor tiempo posible, evaluando riesgos cardiovasculares y de cáncer de mama.", "Tratamientos vaginales locales: Cremas, anillos o tabletas de estrógeno en dosis muy bajas aplicadas directamente en la vagina para curar la sequedad y el dolor en el sexo sin afectar al resto del cuerpo.", "Suplementos de Calcio y Vitamina D, y medicamentos fijadores de hueso (bifosfonatos) si hay osteoporosis diagnosticada.", "Estilo de vida: Ejercicio de fuerza y soporte de peso (esencial para los huesos), dieta rica en calcio y abandono del tabaco."] } ], note: "La salud mental y el mantenimiento de una vida sexual activa y cómoda son fundamentales en esta etapa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Programa una visita urgente con tu ginecólogo si:", items: ["Tienes cualquier tipo de sangrado, manchado o flujo con sangre por la vagina", "Los sofocos, el insomnio o el dolor durante las relaciones sexuales afectan tu calidad de vida", "Sufres una fractura ósea tras una caída menor o un golpe leve"] } },
'Sinusitis aguda' : { intro: "La sinusitis aguda es una inflamación e infección a corto plazo de los senos paranasales (las cavidades huecas que se encuentran alrededor de la nariz, los ojos y las mejillas). Generalmente interfiere con el drenaje normal de la mucosidad y causa congestión.", whatIs: { title: "¿Qué es la Sinusitis Aguda?", text: "Normalmente, los senos paranasales producen moco que se drena hacia la nariz. Cuando te resfrías o sufres una alergia, las membranas mucosas se inflaman y se hinchan, bloqueando las aberturas de drenaje. El moco queda atrapado, creando un ambiente oscuro, húmedo y perfecto para que los virus, o a veces las bacterias, se multipliquen. El término 'aguda' significa que los síntomas duran menos de 4 semanas, y en la inmensa mayoría de los casos es de origen viral, no bacteriano." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen imitar a un resfriado muy fuerte, pero con dolor focalizado:", groups: [ { name: "Síntomas Faciales y Nasales", items: ["Dolor intenso, presión o sensación de pesadez en la frente, las mejillas, alrededor de los ojos o detrás de la nariz", "El dolor facial empeora notablemente al inclinarse hacia adelante o mover la cabeza bruscamente", "Congestión y bloqueo nasal severo que dificulta la respiración", "Secreción nasal espesa (moco de color amarillo o verde)", "Dolor referido en los dientes de la mandíbula superior", "Goteo posnasal (la mucosidad cae por la parte posterior de la garganta, causando irritación)"] }, { name: "Síntomas Generales", items: ["Disminución o pérdida del sentido del olfato y del gusto", "Mal aliento (halitosis) muy marcado", "Fatiga, dolor de oído y dolor de garganta", "Fiebre (más común si la causa es bacteriana)"] } ], warning: "Si el dolor o la hinchazón se extienden al tejido que rodea los ojos (párpados hinchados y rojos), o hay cambios en la visión, puede ser una celulitis periorbitaria, una complicación bacteriana grave que puede amenazar la vista." }, types: { title: "Diferencia: Viral vs. Bacteriana", intro: "Es clave diferenciar la causa para evitar el abuso de antibióticos:", items: ["Sinusitis Viral: Ocurre tras un resfriado común. Los síntomas alcanzan su pico en los días 3-5 y luego mejoran gradualmente. El moco verde NO significa necesariamente bacterias.", "Sinusitis Bacteriana: Se sospecha si los síntomas duran más de 10 días sin ninguna mejoría, o si hay un patrón de 'doble empeoramiento' (el resfriado parece mejorar, pero a los días 5-7 vuelve de golpe con fiebre alta, dolor extremo y moco purulento)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Cualquier cosa que inflame o bloquee las vías respiratorias puede causarla:", items: ["Infección viral (resfriado común, el desencadenante más frecuente)", "Rinitis alérgica (alergias al polen, ácaros o mascotas)", "Anomalías anatómicas (tabique nasal desviado o pólipos nasales que tapan los orificios)", "Infección dental severa que se extiende al seno maxilar (las raíces de los molares superiores están muy cerca de los senos paranasales)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico es suficiente en casi todos los casos:", items: ["Examen físico: El médico presionará tus mejillas y frente para detectar dolor, y examinará el interior de tu nariz con una luz.", "Imágenes: Las radiografías o Tomografías (TC) NO se recomiendan para una sinusitis aguda sin complicaciones, solo se solicitan si se sospecha de complicaciones graves o si la sinusitis se vuelve crónica (dura meses).", "Cultivo nasal: Rara vez se hace, a menos que el tratamiento falle repetidamente."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es reducir la inflamación, secar las secreciones y aliviar el dolor:", subsections: [ { title: "Manejo y Alivio", items: ["Lavados nasales con solución salina: El tratamiento casero más efectivo. Usar jeringas o 'loti pots' con agua estéril y sal para limpiar físicamente el moco espeso y los alérgenos.", "Corticosteroides nasales (ej. Fluticasona): Sprays recetados que bajan la inflamación dentro de la nariz de manera potente.", "Analgésicos y antiinflamatorios (Ibuprofeno, Paracetamol) para el dolor facial y de cabeza.", "Descongestionantes nasales en aerosol (ej. Oximetazolina): Útiles para abrir la nariz, pero NUNCA deben usarse por más de 3 días consecutivos para evitar la congestión de rebote severa.", "Antibióticos (ej. Amoxicilina): SOLO se prescriben si el médico sospecha fuertemente que la infección es bacteriana (síntomas de más de 10 días o doble empeoramiento)."] } ], note: "Beber abundantes líquidos, colocar paños tibios sobre la cara y usar un humidificador ayudan a aflojar la congestión." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un médico de inmediato si presentas:", items: ["Hinchazón, enrojecimiento severo o dolor intenso alrededor de un ojo", "Visión doble o cambios en tu capacidad visual", "Fiebre muy alta, confusión o cuello rígido", "Síntomas que duran más de 10 días sin mostrar signos de mejoría"] } },
'Enfermedad glomerular lúpica' : { intro: "La enfermedad glomerular lúpica, clínicamente conocida como Nefritis Lúpica, es una de las complicaciones más comunes y graves del Lupus Eritematoso Sistémico (LES). Ocurre cuando el lupus ataca directamente a los riñones.", whatIs: { title: "¿Qué es la Nefritis Lúpica?", text: "El lupus es una enfermedad autoinmune donde el sistema inmunológico del cuerpo se equivoca y ataca los tejidos sanos. En el riñón existen miles de filtros microscópicos llamados glomérulos que limpian la sangre. En la nefritis lúpica, los anticuerpos atacan estos glomérulos, causando una inflamación destructiva. Como los 'filtros' están dañados, no pueden eliminar los desechos y comienzan a filtrar proteínas valiosas y glóbulos rojos hacia la orina, lo que puede llevar rápidamente a una insuficiencia renal terminal." }, symptoms: { title: "Síntomas y Alertas", intro: "El daño renal temprano a menudo no duele ni presenta síntomas evidentes; suele detectarse en análisis de orina de rutina en pacientes lúpicos. A medida que empeora, causa:", groups: [ { name: "Síntomas Renales y Sistémicos", items: ["Orina espumosa (el signo clásico de que se está perdiendo un gran exceso de proteína en la orina, conocido como proteinuria)", "Orina de color oscuro, rojo o marrón (hematuria) debido al sangrado microscópico de los riñones", "Hinchazón severa (edema), especialmente en los pies, los tobillos, las piernas y alrededor de los ojos", "Aumento repentino de la presión arterial alta", "Aumento de peso rápido debido a la retención profunda de líquidos", "Empeoramiento de los síntomas generales del lupus: dolor articular, fatiga extrema, o sarpullido en forma de mariposa en la cara"] } ], warning: "Si no se diagnostica y trata de forma agresiva, entre el 10% y el 30% de las personas con nefritis lúpica severa desarrollan insuficiencia renal y necesitarán diálisis o un trasplante de riñón." }, types: { title: "Clasificación Biopsial", intro: "Se divide en 6 clases o grados dependiendo del daño observado bajo el microscopio, lo que dicta el tratamiento:", items: ["Clase I y II: Inflamación mínima; excelente pronóstico, suele requerir poco tratamiento renal específico.", "Clase III y IV: (Proliferativa focal y difusa) Son las formas más severas, destructivas y comunes. Requieren tratamiento inmunosupresor agresivo e inmediato para salvar el riñón.", "Clase V: (Membranosa) Causa pérdida masiva de proteínas y edema extremo, pero menos falla renal aguda.", "Clase VI: Esclerosis avanzada; el riñón está totalmente cicatrizado y los tratamientos no pueden revertirlo."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Todo paciente con lupus debe tener controles renales regulares:", items: ["Análisis de orina (Urianálisis): Es la prueba más importante de detección; busca proteínas, sangre y cilindros celulares que indican inflamación glomerular.", "Análisis de sangre: Se mide la creatinina para ver cómo están filtrando los riñones, y marcadores del lupus (anticuerpos anti-ADN bicatenario y niveles de complemento C3/C4).", "Biopsia Renal: El paso definitivo y obligatorio. Se extrae un minúsculo trozo de riñón con una aguja guiada por ecografía. Clasifica el grado del daño (Clase I-VI) y dirige exactamente qué medicamentos se deben utilizar."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento debe ser manejado conjuntamente por un nefrólogo y un reumatólogo; requiere apagar el sistema inmunológico:", subsections: [ { title: "Inmunosupresión y Protección Renal", items: ["Fase de Inducción (Ataque): Para apagar rápidamente el brote. Se utilizan altas dosis de corticosteroides (Metilprednisolona intravenosa o Prednisona oral) combinados con potentes inmunosupresores como el Micofenolato de Mofetilo o la Ciclofosfamida intravenosa.", "Fase de Mantenimiento: Una vez controlada la inflamación, se bajan los esteroides y se mantienen dosis bajas de inmunosupresores (Micofenolato o Azatioprina) durante años para evitar que el riñón vuelva a ser atacado.", "Medicamentos para la presión arterial: Es vital proteger los filtros renales usando medicamentos inhibidores de la ECA (Enalapril) o ARA-II (Losartán), ya que no solo bajan la presión, sino que reducen directamente la pérdida de proteínas en la orina.", "Hidroxicloroquina: Un medicamento antipalúdico que todo paciente con lupus debe tomar de por vida, ya que previene brotes renales y sistémicos.", "Diuréticos: Para eliminar el exceso de líquido y controlar el edema en piernas y pulmones."] } ], note: "El embarazo puede empeorar drásticamente la nefritis lúpica; debe planificarse estrictamente en momentos de remisión y con medicamentos seguros para el feto." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Si tienes Lupus, acude al nefrólogo o a urgencias inmediatamente si:", items: ["Notas que tu orina parece cerveza oscura o hace mucha espuma como la de la cerveza", "Se te hinchan repentinamente las piernas, los pies o la cara", "Tu presión arterial sube bruscamente, acompañada de dolor de cabeza"] } },
'Osteosarcoma' : { intro: "El osteosarcoma es el tipo más común de cáncer primario de hueso. Es un tumor maligno muy agresivo que afecta principalmente a niños, adolescentes y adultos jóvenes, originándose en las células responsables de formar nuevo tejido óseo.", whatIs: { title: "¿Qué es el Osteosarcoma?", text: "Se desarrolla a partir de células inmaduras llamadas osteoblastos que mutan. En lugar de formar hueso sano y fuerte, estas células producen una matriz ósea desorganizada y tumoral. Frecuentemente aparece en los extremos de los huesos largos, cerca de las articulaciones donde ocurre el crecimiento más rápido (las 'placas de crecimiento'), siendo la rodilla (fémur inferior o tibia superior) y el hueso del brazo cerca del hombro (húmero) las zonas más atacadas." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen confundirse inicialmente con 'dolores de crecimiento' o lesiones deportivas menores:", groups: [ { name: "Síntomas Locales y Óseos", items: ["Dolor óseo profundo, sordo y persistente en una extremidad específica", "El dolor empeora notablemente por la noche (despertando al paciente) o aumenta con la actividad física", "Aparición progresiva de hinchazón, un bulto firme o una masa palpable cerca de una articulación (como la rodilla)", "Cojera inexplicable o disminución en el movimiento de la pierna o el brazo", "Fractura de un hueso aparentemente sano tras una caída muy leve o movimiento rutinario (fractura patológica debida a que el cáncer debilita el hueso por dentro)"] } ], warning: "A diferencia de un esguince o golpe, el dolor del osteosarcoma no mejora con reposo, hielo ni con el paso de las semanas. Requiere imágenes médicas sin demora." }, types: { title: "Naturaleza de la Diseminación", intro: "Es un cáncer sistémico y agresivo:", items: ["Metástasis pulmonar: El mayor peligro del osteosarcoma es su capacidad para propagarse rápidamente a través de la sangre. El destino principal y casi exclusivo de sus metástasis son los pulmones.", "Por esta razón, la quimioterapia es obligatoria en todos los pacientes, incluso si el tumor en el hueso es pequeño y el escáner de tórax sale limpio, para destruir células invisibles circulantes."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "En la mayoría de los casos no se conoce la causa, pero el riesgo aumenta por:", items: ["Periodos de crecimiento óseo rápido (los picos ocurren en los 'estirones' de la pubertad)", "Antecedentes de radioterapia en esa misma zona del cuerpo para tratar otro cáncer infantil previo", "Factores Genéticos y Síndromes Hereditarios: Mutaciones como el Retinoblastoma hereditario (cáncer de ojo) o el Síndrome de Li-Fraumeni multiplican drásticamente la posibilidad de padecer osteosarcoma.", "En adultos mayores (un segundo pico menor después de los 60 años), a menudo surge como una complicación de la Enfermedad de Paget del hueso."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico debe ser realizado por especialistas en oncología ortopédica:", items: ["Radiografía simple: El primer paso; a menudo muestra una lesión clásica de destrucción ósea ('imagen en sol naciente' o 'triángulo de Codman').", "Resonancia Magnética (RM) del hueso: Crucial para ver el tamaño del tumor, cuánto ha invadido la médula espinal, los músculos, los nervios y los vasos sanguíneos circundantes para planear la cirugía.", "Tomografía Computarizada (TC) de Tórax: Obligatoria para revisar si hay nódulos de cáncer en los pulmones.", "Gammagrafía Ósea o PET-TC: Para detectar si el cáncer se ha diseminado a otros huesos del cuerpo.", "Biopsia Ósea: El diagnóstico definitivo. Se extrae una pequeña muestra del tumor (usualmente con aguja gruesa bajo anestesia) para confirmarlo al microscopio. Debe ser planificada por el mismo cirujano que hará la cirugía final para no comprometer la extremidad."], note: "" }, treatment: { title: "Tratamientos", intro: "El estándar de oro es un tratamiento combinado intensivo, que ha mejorado la supervivencia del 20% al 70% en décadas recientes:", subsections: [ { title: "Protocolo Oncológico", items: ["Quimioterapia Neoadyuvante (Preoperatoria): Varios ciclos de quimioterapia muy potente administrada en el hospital durante 2-3 meses antes de operar. Su objetivo es matar las metástasis invisibles de los pulmones y encoger el tumor principal en el hueso.", "Cirugía de Salvamento de Extremidad: El cirujano extirpa el hueso y el músculo canceroso dejando nervios y vasos intactos, y reconstruye el hueso faltante con una prótesis metálica de titanio a medida o un injerto de hueso de donante (banco de huesos). Se hace en más del 90% de los casos.", "Amputación: Tristemente, a veces es ineludible si el tumor envuelve nervios y vasos sanguíneos principales, o si hay una infección intratable.", "Quimioterapia Adyuvante (Posoperatoria): Más meses de quimioterapia después de la cirugía para asegurar la destrucción total del cáncer. El tipo de fármacos depende de qué tan muerto estaba el tumor al analizarlo tras sacarlo (tasa de necrosis)."] } ], note: "El osteosarcoma es muy resistente a la radioterapia, por lo que rara vez se usa a menos que el tumor no pueda operarse." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Lleva a tu hijo al pediatra o traumatólogo para unas radiografías si:", items: ["Se queja de un dolor en la rodilla, muslo o brazo que no desaparece en varias semanas, no está ligado a una caída obvia, y le duele por la noche", "Palpas un bulto duro que no se mueve adherido al hueso cerca de una articulación", "El niño empieza a cojear para evitar el dolor"] } },
'Glioma en adultos' : { intro: "Un glioma es el tipo más común de tumor cerebral primario (que se origina en el propio cerebro y no proviene de metástasis de otros órganos). Se forma a partir de las células gliales, que son el 'pegamento' y el tejido de soporte que nutre y protege a las neuronas del cerebro.", whatIs: { title: "¿Qué es un Glioma?", text: "A diferencia de tumores benignos que tienen bordes claros, los gliomas son temidos porque suelen crecer enviando 'raíces' o tentáculos microscópicos hacia el tejido cerebral sano y vital circundante (infiltración). Esto hace que sean biológicamente imposibles de extirpar por completo con cirugía. Varían desde tumores de grado bajo (crecimiento lento) hasta el devastador glioblastoma multiforme (el cáncer cerebral más agresivo y letal en adultos)." }, symptoms: { title: "Síntomas y Alertas Neurológicas", intro: "El cerebro no tiene receptores de dolor en sí. Los síntomas son causados por la masa que presiona el cráneo cerrado o que interfiere con funciones cerebrales específicas:", groups: [ { name: "Síntomas por Aumento de Presión (Generales)", items: ["Dolor de cabeza nuevo y persistente que empeora por la mañana al despertar, al toser o agacharse, y a menudo asociado con náuseas y vómitos explosivos", "Crisis convulsivas de nueva aparición (el primer síntoma en muchos adultos, desde temblores en una mano hasta desmayos con convulsiones completas)", "Confusión constante, somnolencia profunda y letargo"] }, { name: "Síntomas Neurológicos Focales (Según la Ubicación)", items: ["Problemas cognitivos severos: pérdida repentina de memoria, dificultad para encontrar palabras (afasia) o cambios profundos de personalidad", "Debilidad gradual, torpeza o parálisis en un brazo, pierna o lado de la cara", "Pérdida de la visión en un lado del campo visual o visión doble", "Dificultad progresiva para caminar o mantener el equilibrio"] } ], warning: "Tener una primera convulsión en la vida adulta sin antecedentes de epilepsia, o un dolor de cabeza progresivo y paralizante acompañado de vómitos matutinos, requiere una resonancia magnética cerebral de emergencia." }, types: { title: "Clasificación de los Gliomas", intro: "Se clasifican por el tipo de célula glial afectada y por su grado de agresividad (Escala de la OMS del I al IV):", items: ["Astrocitomas: Se originan en los astrocitos. Los de Grado II y III crecen a ritmo moderado. El Glioblastoma (Astrocitoma Grado IV) es el más frecuente y fatal, crece explosivamente y crea sus propios vasos sanguíneos y áreas de tejido muerto (necrosis).", "Oligodendrogliomas: Se forman en las células que producen la mielina aislante. Tienen mutaciones genéticas específicas (codeleción 1p/19q) que los hacen responder mucho mejor a la quimioterapia que los astrocitomas.", "Ependimomas: Crecen en las células que recubren los canales de líquido cefalorraquídeo. Más comunes en niños o en la médula espinal."], note: "Hoy en día, el diagnóstico depende fuertemente de análisis moleculares genéticos (como la mutación IDH), que pronostican la supervivencia mucho mejor que solo mirar las células al microscopio." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La neuroimagen y la patología son fundamentales:", items: ["Examen Neurológico: Para evaluar qué áreas del cerebro están fallando (visión, fuerza, reflejos).", "Resonancia Magnética (RM) del cerebro con contraste: El método de oro indiscutible. El contraste resalta los tumores de alto grado, delineando su tamaño y su proximidad a áreas críticas del cerebro (corteza motora o del lenguaje).", "Tomografía por Emisión de Positrones (PET): A veces se usa para medir la actividad metabólica del tumor.", "Biopsia Estereotáctica o Resección Quirúrgica: Es imperativo extraer tejido del cráneo. Un patólogo analiza el ADN y las células tumorales para dar el diagnóstico definitivo y la estrategia de medicación."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento no es curativo en gliomas de alto grado, el objetivo es prolongar la vida y mantener las funciones cerebrales:", subsections: [ { title: "Protocolo Neuro-Oncológico Estándar", items: ["Cirugía de máxima resección segura: La primera línea de ataque. El neurocirujano abre el cráneo (craneotomía) y extirpa la mayor cantidad posible de tumor sin dañar las partes del cerebro que controlan el movimiento o el habla. A menudo se hace con el paciente despierto (Cirugía despierto) para mapear el lenguaje.", "Radioterapia: Casi siempre necesaria tras la cirugía. Se enfoca radiación de alta energía en la cavidad donde estaba el tumor para matar las células 'infiltradas' que el cirujano no pudo ver.", "Quimioterapia (Temozolomida): Fármaco en pastilla que cruza la barrera del cerebro muy eficazmente; se toma a diario junto con la radiación y luego durante meses después.", "Campos de Tratamiento de Tumores (Optune): Un dispositivo en forma de casco con electrodos que el paciente usa en la cabeza, generando campos eléctricos que impiden que las células del glioblastoma se dividan.", "Terapias de apoyo: Esteroides (Dexametasona) para reducir rápidamente la inflamación cerebral masiva y anticonvulsivos para prevenir ataques epilépticos."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias o ve al hospital de inmediato si:", items: ["Sufres tu primera convulsión epiléptica de adulto", "Desarrollas debilidad, entumecimiento inusual o pérdida de movimiento en un lado de tu cuerpo", "Sufres cambios mentales graves (te desorientas, no reconoces familiares o no puedes formar palabras)"] } },
'Aneurisma de la aorta torácica' : { intro: "Un aneurisma de la aorta torácica es un área debilitada y abultada en la parte superior de la aorta (la arteria principal y más grande del cuerpo) a medida que atraviesa el pecho (tórax). Es una afección vascular crítica que, si no se controla, puede provocar el desgarro o la ruptura del vaso, causando una hemorragia interna mortal.", whatIs: { title: "¿Qué es un Aneurisma de la Aorta Torácica?", text: "La aorta sale directamente del corazón. Cuando las paredes de esta arteria vital se debilitan debido a presión arterial alta, genética o envejecimiento, la enorme fuerza de la sangre bombeada por el corazón empuja la pared hacia afuera, inflándola como un globo a punto de estallar. El mayor peligro es la 'disección aórtica' (donde las capas de la pared de la arteria se separan y se llenan de sangre) o la ruptura completa, ambas emergencias letales masivas." }, symptoms: { title: "Síntomas y Alertas Graves", intro: "Los aneurismas torácicos crecen muy lentamente y casi siempre son asintomáticos hasta que alcanzan un tamaño enorme o sufren un desgarro (disección). Si crecen lo suficiente como para presionar órganos cercanos en el pecho, causan:", groups: [ { name: "Síntomas por Compresión (Aneurisma Creciente)", items: ["Dolor sordo, profundo y constante en el pecho o en la parte superior de la espalda (entre los omóplatos)", "Ronquera o cambios en la voz persistentes (debido a que el aneurisma presiona el nervio de las cuerdas vocales)", "Tos crónica o dificultad para respirar (al presionar la tráquea)", "Dificultad o dolor agudo al tragar comida sólida (al presionar el esófago)"] }, { name: "Signos de Ruptura o Disección (Emergencia de Vida o Muerte)", items: ["Dolor fulminante, súbito, desgarrador e insoportable en el pecho o la espalda (descrito como si algo 'se estuviera rasgando' por dentro), que a menudo baja hacia el estómago", "Falta de aire aguda y extrema", "Caída catastrófica de la presión arterial, debilidad, mareos extremos, confusión y shock", "Sudoración fría y pérdida de conocimiento"] } ], warning: "Cualquier dolor de pecho o de espalda intenso y repentino que se sienta 'desgarrador' en una persona con presión alta o antecedentes genéticos es una alerta máxima de disección aórtica. Se debe llamar a urgencias (911) inmediatamente." }, types: { title: "Ubicación del Aneurisma", intro: "La aorta torácica tiene tres partes, y la ubicación dicta el riesgo:", items: ["Raíz aórtica y aorta ascendente (donde la aorta sale del corazón): El lugar más común, altamente asociado con enfermedades genéticas del tejido conectivo.", "Arco aórtico (donde la arteria se curva).", "Aorta descendente torácica (donde baja por la parte posterior del pecho)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El debilitamiento de la pared arterial puede ser adquirido o heredado:", items: ["Trastornos Genéticos (Síndrome de Marfan, Síndrome de Loeys-Dietz, Ehlers-Danlos vascular): Causan mutaciones que debilitan inherentemente el tejido conectivo de la aorta. Son la causa principal en pacientes jóvenes.", "Válvula aórtica bicúspide: Nacer con una válvula aórtica de dos valvas en lugar de tres aumenta enormemente el riesgo de agrandamiento de la raíz aórtica.", "Aterosclerosis (endurecimiento de las arterias) y Presión Arterial Alta crónica: Las placas de colesterol y la alta presión dañan mecánicamente las paredes de la aorta (más común en pacientes mayores).", "Aneurismas familiares: Historial de familiares cercanos que hayan muerto súbitamente de problemas aórticos.", "Tabaquismo y traumatismos graves en el pecho (como accidentes de tráfico)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se descubre por casualidad al hacer radiografías por otros motivos (como neumonía):", items: ["Ecocardiograma transtorácico: Fundamental para evaluar la raíz aórtica, el tamaño de la válvula del corazón y la función del músculo.", "Angiotomografía Computarizada (Angio-TC) de tórax: La prueba de oro. Brinda imágenes precisas y detalladas del tamaño del aneurisma, la pared arterial y ayuda a decidir quirúrgicamente cuándo operar.", "Angiografía por Resonancia Magnética (ARM): Alternativa a la TC para monitorear el aneurisma a largo plazo sin exposición a radiación repetida.", "Pruebas genéticas: Se recomiendan para familias si se sospecha Síndrome de Marfan u otra mutación."], note: "A diferencia del aneurisma abdominal, no existen programas de ecografía de cribado rutinario poblacional para el tórax, por lo que el diagnóstico de los que tienen riesgo familiar temprano es crítico." }, treatment: { title: "Tratamientos", intro: "El objetivo es controlar el crecimiento y programar la cirugía antes de que se rompa, basándose en su tamaño crítico (generalmente cuando supera los 5.0 - 5.5 cm de diámetro):", subsections: [ { title: "Manejo Médico y Control", items: ["Vigilancia estricta: Tomografías (TC) o Ecocardiogramas regulares cada 6-12 meses.", "Medicamentos vitales: Controlar estrictamente la presión arterial es el único freno médico. Se recetan Betabloqueadores o Bloqueadores de los receptores de angiotensina (ARA-II, como Losartán) para bajar la presión en la pared aórtica y ralentizar la dilatación.", "Restricción física: Prohibición absoluta de levantar pesas pesadas, hacer esfuerzos extremos o deportes de contacto (porque aumentan la presión intraaórtica de golpe)."] }, { title: "Opciones Quirúrgicas (Cuando alcanza el tamaño de riesgo)", items: ["Cirugía Abierta de Aorta: (Procedimiento complejo a corazón abierto). El cirujano corta el pecho, detiene el corazón temporalmente con una máquina extracorpórea, extirpa la parte abultada y cosé en su lugar un tubo sintético (injerto de Dacrón). Si la válvula está dañada, se reemplaza en el mismo acto.", "Reparación Endovascular de la Aorta Torácica (TEVAR): Procedimiento mínimamente invasivo (solo aplicable a ciertas partes de la aorta, como la descendente). Se introduce un stent recubierto de tela a través de una arteria en la ingle hasta la aorta torácica, forrando la zona debilitada para que la sangre fluya por el stent y no empuje el aneurisma."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La rotura es letal. Busca ayuda médica de emergencia (ambulancia, no conduzcas) si:", items: ["Sientes un dolor repentino, agudo, insoportable y profundo en el pecho, cuello, mandíbula o en la zona alta de la espalda", "Si presentas estos dolores junto con una fuerte sensación de falta de aire y mareos", "Si tienes antecedentes familiares de muerte súbita joven o Síndrome de Marfan, busca un cribado preventivo urgente con cardiología"] } },
'Infecciones de vías respiratorias de repetición (o recurrentes)' : { intro: "Las infecciones de vías respiratorias de repetición (o recurrentes) se definen por una frecuencia anormalmente alta de episodios infecciosos (como resfriados severos, sinusitis, otitis, bronquitis o neumonías) que afectan los pulmones, los senos paranasales, la garganta y los oídos a lo largo de un solo año.", whatIs: { title: "¿Qué son las Infecciones Respiratorias Recurrentes?", text: "Es importante destacar que es completamente normal que los niños sanos (especialmente los que asisten a la guardería) sufran entre 6 y 10 resfriados leves virales al año. Sin embargo, cuando las infecciones son excesivamente frecuentes, excepcionalmente graves, requieren múltiples ciclos de antibióticos para curarse, o terminan repetidamente en neumonía y hospitalización, indica que hay un problema subyacente. El sistema inmunológico o las defensas estructurales de las vías respiratorias están fallando." }, symptoms: { title: "Señales de Alerta de Frecuencia Anormal", intro: "Debes sospechar de un problema médico subyacente (y no solo 'mala suerte') si un niño o adulto experimenta:", groups: [ { name: "Indicadores de Inmunodeficiencia o Patología Base", items: ["Más de dos neumonías completas en un período de 12 meses", "Más de dos meses tomando antibióticos (en un año) con escaso efecto o rápida recaída", "Infecciones que no logran sanar con antibióticos orales normales y requieren antibióticos intravenosos (hospitalización)", "Infecciones profundas u orgánicas adicionales (como abscesos hepáticos o cutáneos recurrentes)", "Tos húmeda y productiva diaria, persistente y crónica (incluso entre los episodios de infección)", "En niños: Falta de crecimiento, peso bajo, o retraso evidente en el desarrollo (fallo de medro) asociado a la constante enfermedad"] } ], warning: "Las neumonías repetitivas en exactamente el mismo lóbulo pulmonar sugieren un bloqueo anatómico fijo (como un cuerpo extraño aspirado, malformación o un tumor), no un problema de inmunidad." }, types: { title: "Causas y Factores Subyacentes", intro: "Si la frecuencia es anormal, el médico debe investigar múltiples causas:", items: ["Ambientales y Alérgicas (Las más comunes): Exposición pasiva al humo del tabaco en casa (debilita masivamente los pulmones infantiles), asistencia temprana a guarderías hacinadas, o asma y rinitis alérgica severa no tratada (que bloquean los senos nasales y bronquios, favoreciendo infecciones).", "Anormalidades Anatómicas: Hipertrofia extrema de adenoides o amígdalas, o tabique desviado (bloquean el drenaje).", "Enfermedades Sistémicas: Fibrosis Quística (moco letalmente espeso que atrapa bacterias), Discinesia Ciliar Primaria (los 'pelillos' que limpian los pulmones no se mueven) o reflujo gastroesofágico crónico silencioso (microaspiración de ácido a los pulmones).", "Inmunodeficiencias Primarias: Un fallo genético raro del sistema inmunológico desde el nacimiento (como deficiencia de IgA o Inmunodeficiencia Común Variable) donde el cuerpo no crea anticuerpos contra las bacterias."] }, diagnosis: { title: "¿Cómo se Evalúa y Diagnostica?", intro: "Se requiere un enfoque paso a paso por pediatría, neumología y/o inmunología:", items: ["Historial clínico detallado (registrar exactamente qué gérmenes fueron cultivados, cuántas veces y la respuesta a los fármacos).", "Análisis de Sangre y Perfil Inmunológico: Recuento completo de células sanguíneas y medición específica de niveles de Inmunoglobulinas (IgG, IgA, IgM, IgE) y respuesta a vacunas previas.", "Radiografía de tórax de alta resolución o Tomografía Computarizada (TC): Para ver si las infecciones repetidas han causado daño permanente a los pulmones (bronquiectasias) o para descartar anomalías físicas.", "Pruebas de sudor (el estándar de oro para descartar Fibrosis Quística en niños).", "Pruebas de alergia y evaluación de la función pulmonar (espirometría) para descartar asma oculta."], note: "" }, treatment: { title: "Tratamientos y Prevención", intro: "El tratamiento no es solo dar antibióticos cada vez que la persona enferma, sino prevenir los episodios futuros:", subsections: [ { title: "Opciones de Manejo Preventivo y Específico", items: ["Control Ambiental Estricto: Eliminación total y absoluta del humo de tabaco en el entorno. Mejorar la ventilación, lavar manos y, si es posible en niños muy propensos, retrasar la entrada a la guardería masiva.", "Control de Enfermedades de Base: Tratar agresivamente el asma y las alergias con inhaladores diarios, lo que frecuentemente reduce las sinusitis y bronquitis asociadas.", "Vacunación exhaustiva: Asegurar que el paciente tenga todas las vacunas antineumocócicas (contra neumonía) y la vacuna anual contra la gripe (influenza).", "Medicamentos Profilácticos: En algunos casos de daño estructural o fibrosis, el médico puede recetar una dosis diaria y continua de antibióticos de bajo grado (como Azitromicina) durante el invierno para prevenir exacerbaciones.", "Terapia de Reemplazo de Inmunoglobulinas: Si se detecta un fallo grave del sistema inmune (falta de anticuerpos), los pacientes pueden recibir infusiones intravenosas (IVIG) o subcutáneas regulares de anticuerpos de donantes para darles defensas artificiales.", "Cirugía: Extirpación de adenoides y amígdalas gigantes, o colocación de tubos de ventilación en los oídos (diábolos) para resolver infecciones persistentes localizadas."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una derivación a un especialista en neumología o inmunología si tú o tu hijo:", items: ["Han padecido dos o más neumonías en el último año confirmadas por radiografía", "Necesitan recibir antibióticos por vía intravenosa reiteradas veces debido a infecciones graves y resistentes", "Presentan tos productiva (con flema) crónica durante semanas o meses, y tienen problemas para ganar peso"] } },
'Quiste pilonidal' : { intro: "Un quiste pilonidal es una bolsa anormal en la piel, ubicada habitualmente en la parte superior del pliegue interglúteo (la hendidura de los glúteos), que casi siempre contiene vello y restos de piel.", whatIs: { title: "¿Qué es un Quiste Pilonidal?", text: "Ocurre cuando el vello suelto penetra en la piel y el cuerpo lo reconoce como un cuerpo extraño, creando un quiste a su alrededor. Si este quiste se infecta, se convierte en un absceso pilonidal, una condición extremadamente dolorosa que acumula pus y sangre." }, symptoms: { title: "Síntomas Comunes", intro: "Un quiste pilonidal sin infección puede no causar síntomas. Si se infecta, los signos incluyen:", groups: [ { name: "Signos de Infección (Absceso)", items: ["Dolor intenso y creciente en la zona del coxis que empeora al sentarse o acostarse", "Enrojecimiento, inflamación y calor en la zona afectada", "Supuración de pus o sangre, a menudo con un olor muy desagradable", "Aparición de uno o varios pequeños orificios (senos) en la piel de la hendidura glútea", "Fiebre y malestar general (en casos severos)"] } ], warning: "Los quistes pilonidales tienen una alta tasa de recurrencia si no se tratan adecuadamente mediante la extracción completa de los folículos pilosos infectados." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se desencadena principalmente por la fricción y la presión:", items: ["Vello corporal abundante, grueso o rígido", "Fricción constante (usar ropa muy ajustada, andar en bicicleta)", "Sedentarismo (pasar largos períodos sentado, como conductores o trabajadores de oficina)", "Sobrepeso u obesidad", "Higiene deficiente en la zona o sudoración excesiva", "Tener un hoyuelo pilonidal de nacimiento"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico es muy directo:", items: ["Examen físico visual y palpación (el médico identificará el bulto enrojecido y los característicos poros o senos pilonidales en la línea media de los glúteos)"], note: "Rara vez se necesitan análisis de sangre o estudios de imagen a menos que la infección sea extensa y profunda." }, treatment: { title: "Tratamientos", intro: "El tratamiento varía desde el drenaje agudo hasta la cirugía definitiva:", subsections: [ { title: "Opciones Médicas y Quirúrgicas", items: ["Incisión y drenaje: Procedimiento rápido en consulta con anestesia local para aliviar el dolor abriendo el quiste y vaciando el pus.", "Antibióticos: Se recetan si hay signos de infección extendida en la piel (celulitis) o fiebre, pero no curan el quiste por sí solos.", "Cirugía de extirpación (Quistectomía): Para quistes recurrentes, el cirujano extirpa completamente el quiste y los tractos sinusales. La herida puede dejarse abierta para que sane desde adentro hacia afuera (menor riesgo de recurrencia pero curación lenta) o cerrarse con puntos.", "Depilación láser: Tras la curación, eliminar el vello de la zona de forma permanente reduce drásticamente el riesgo de nuevos quistes."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico o cirujano si:", items: ["Sientes un dolor agudo y punzante en la base de la columna que te impide sentarte", "Notas un bulto enrojecido y caliente en la zona del coxis", "El bulto comienza a supurar un líquido maloliente o sangre"] } },
'Fractura de mano' : { intro: "Una fractura de mano implica la rotura de uno o más huesos en la estructura de la mano, ya sean los pequeños huesos de los dedos (falanges) o los huesos largos que conectan los dedos con la muñeca (metacarpianos).", whatIs: { title: "¿Qué es una Fractura de Mano?", text: "La mano tiene 27 huesos intrincados y fundamentales para el agarre y la precisión. Una fractura puede variar desde una simple fisura sin desplazamiento hasta un hueso completamente aplastado o roto en múltiples fragmentos que sobresalen a través de la piel. Un mal tratamiento puede resultar en rigidez permanente o pérdida de la función." }, symptoms: { title: "Síntomas Comunes", intro: "Las señales de una fractura en la mano son inmediatas tras un impacto:", groups: [ { name: "Signos Clínicos y Funcionales", items: ["Dolor intenso e inmediato que empeora notablemente al intentar agarrar algo o mover los dedos", "Hinchazón rápida y severa en la mano o los dedos", "Hematomas (moretones) extensos que pueden extenderse hacia los dedos o la muñeca", "Deformidad obvia (un dedo torcido, acortado, o el nudillo hundido)", "Dedo rotado: Al cerrar el puño, el dedo fracturado se cruza por encima o por debajo de su dedo vecino (un signo clásico de fractura de metacarpiano)", "Incapacidad física para cerrar el puño o mover la mano"] } ], warning: "Si la fractura corta la piel (fractura abierta) o si notas entumecimiento y palidez extrema en los dedos, es una emergencia que requiere cirugía inmediata para prevenir infecciones óseas graves o daño nervioso." }, types: { title: "Tipos Frecuentes", intro: "Se clasifican según el hueso afectado:", items: ["Fractura de metacarpiano: Muy común, especialmente la 'fractura de boxeador' (rotura del cuello del 5º metacarpiano, debajo del nudillo del meñique, usualmente por golpear una pared o superficie dura).", "Fracturas de falanges (dedos): A menudo causadas por aplastamiento (como cerrar una puerta sobre los dedos) o lesiones deportivas.", "Fractura de escafoides: (Hueso del carpo, cerca de la base del pulgar) Ocurre al caer con la mano extendida; es notoria por su mala circulación y dificultad para sanar."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El traumatólogo evaluará la alineación y el daño óseo mediante:", items: ["Radiografías de la mano (rayos X) en múltiples proyecciones (anteroposterior, lateral y oblicua) para ver exactamente la ubicación, el número de fragmentos y el desplazamiento del hueso", "Examen físico para verificar la circulación (pulso capilar) y la función nerviosa (sensibilidad) en los dedos", "Tomografía Computarizada (TC) en casos de fracturas articulares muy complejas o astilladas"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es alinear los huesos perfectamente para recuperar la función completa de la mano:", subsections: [ { title: "Opciones Ortopédicas y Quirúrgicas", items: ["Inmovilización (Tratamiento conservador): Para fracturas estables y sin desplazamiento. Se utiliza una férula de aluminio, un yeso o cinta para unir el dedo roto al sano (sindactilia) durante 3 a 6 semanas.", "Reducción cerrada: Si el hueso está movido, el médico lo acomoda empujándolo desde afuera bajo anestesia local antes de colocar la férula.", "Fijación interna (Cirugía): Necesaria si la fractura es inestable, abierta, o afecta una articulación. El cirujano ortopédico inserta agujas de Kirschner (alambres), placas de titanio minúsculas o tornillos para mantener los huesos unidos mientras sanan.", "Fisioterapia: Fundamental e innegociable tras retirar la inmovilización para combatir la rigidez articular, que es la complicación más común tras una fractura de mano."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención médica de urgencia tras un golpe en la mano si:", items: ["Hay una deformidad visible, el dedo apunta en un ángulo extraño o el nudillo ha 'desaparecido'", "El dolor es insoportable y la mano se hincha como un globo rápidamente", "No tienes sensibilidad en las yemas de los dedos", "Al intentar cerrar el puño, un dedo se cruza sobre otro"] } },
'Hepatitis autoinmunitaria' : { intro: "La hepatitis autoinmunitaria (HAI) es una enfermedad crónica en la cual el propio sistema inmunológico del cuerpo ataca las células del hígado, provocando una inflamación persistente que puede derivar en cirrosis e insuficiencia hepática si no se diagnostica y trata a tiempo.", whatIs: { title: "¿Qué es la Hepatitis Autoinmunitaria?", text: "Normalmente, el sistema inmune nos defiende de virus y bacterias. En esta enfermedad, un fallo en el reconocimiento hace que los glóbulos blancos ataquen a los hepatocitos (las células del hígado) como si fueran invasores. Esta inflamación (hepatitis) destruye el tejido hepático gradualmente, reemplazándolo por tejido cicatricial duro (fibrosis y cirrosis)." }, symptoms: { title: "Síntomas Comunes", intro: "Puede ser silenciosa al principio o presentarse de forma repentina y severa:", groups: [ { name: "Síntomas Generales y Hepáticos", items: ["Fatiga extrema y falta de energía (el síntoma más común y persistente)", "Ictericia (coloración amarillenta de la piel y de la parte blanca de los ojos)", "Molestias, pesadez o dolor sordo en la parte superior derecha del abdomen, sobre el hígado", "Orina de color muy oscuro (color té) y heces pálidas", "Dolor en las articulaciones (artralgia) sin inflamación evidente", "Aparición de erupciones cutáneas, picazón intensa o vasos sanguíneos en forma de araña en la piel (arañas vasculares)", "Pérdida de apetito y náuseas"] } ], warning: "Si la enfermedad avanza a cirrosis sin tratamiento, provocará hinchazón severa del abdomen (ascitis), confusión mental (encefalopatía hepática) y hemorragias internas mortales." }, types: { title: "Tipos de HAI", intro: "Se clasifica en dos tipos principales basados en los anticuerpos en la sangre:", items: ["Hepatitis Autoinmunitaria Tipo 1: Es la forma más común. Afecta a personas de cualquier edad, pero frecuentemente a mujeres adultas jóvenes. Se asocia a menudo con otras enfermedades autoinmunes (celiaquía, tiroiditis, colitis ulcerosa).", "Hepatitis Autoinmunitaria Tipo 2: Es mucho menos común, suele ser más agresiva y afecta principalmente a niñas y mujeres jóvenes. A menudo es difícil de controlar."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Es provocada por la interacción de predisposición genética y factores ambientales:", items: ["Genética (heredar ciertos genes HLA que predisponen a enfermedades autoinmunes)", "Sexo (más del 70% de los pacientes son mujeres)", "Desencadenantes ambientales: Se cree que ciertas infecciones virales (como el sarampión, herpes o Epstein-Barr), toxinas, o incluso algunos medicamentos pueden 'despertar' la reacción autoinmune en personas genéticamente predispuestas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El hepatólogo combinará análisis de sangre con evaluación de tejidos:", items: ["Análisis de enzimas hepáticas: ALT y AST estarán crónicamente elevadas, indicando inflamación celular.", "Panel de Autoanticuerpos: Detección en sangre de Anticuerpos Antinucleares (ANA), Anticuerpos Antimúsculo Liso (ASMA) o Anti-LKM1 (específicos del tipo 2).", "Niveles de Inmunoglobulina G (IgG): Suelen estar anormalmente altos.", "Biopsia Hepática: Es la prueba definitiva. Se extrae una pequeña muestra de hígado con una aguja para observar al microscopio el patrón característico de daño autoinmune y determinar el grado de cirrosis."], note: "Es vital descartar primero las hepatitis virales (A, B, C) mediante análisis de sangre, ya que los síntomas son idénticos." }, treatment: { title: "Tratamientos", intro: "La meta es suprimir el sistema inmunológico hiperactivo para detener la destrucción del hígado y lograr la remisión:", subsections: [ { title: "Opciones de Manejo Médico", items: ["Corticosteroides (Prednisona o Budesonida): Es el tratamiento inicial rápido. Actúa como un potente antiinflamatorio para calmar el ataque al hígado. Las dosis iniciales son altas y luego se reducen gradualmente.", "Inmunosupresores ahorradores de esteroides (Azatioprina, Micofenolato): Se añaden al tratamiento para poder bajar la dosis de prednisona y evitar sus graves efectos secundarios a largo plazo. Mantienen el sistema inmunológico a raya de forma crónica.", "Trasplante de hígado: Si el diagnóstico es tardío, la cirrosis es irreversible y el hígado entra en insuficiencia terminal, el trasplante es la única opción de supervivencia (la enfermedad raramente regresa en el hígado nuevo)."] } ], note: "La mayoría de los pacientes necesitarán tomar medicamentos inmunosupresores de por vida para evitar recaídas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una revisión médica exhaustiva si:", items: ["Notas que tu piel o el blanco de tus ojos adquieren un tono amarillento", "Sientes una fatiga profunda que no se explica por falta de sueño o exceso de trabajo", "Tus análisis de sangre de rutina revelan que tus enzimas hepáticas (transaminasas) están altas de forma persistente"] } },
'Gonartrosis' : { intro: "La gonartrosis es el término médico para la osteoartritis de la rodilla, una enfermedad degenerativa y crónica caracterizada por el desgaste progresivo del cartílago articular que recubre los extremos de los huesos dentro de la rodilla.", whatIs: { title: "¿Qué es la Gonartrosis?", text: "Una rodilla sana tiene un cartílago liso y resbaladizo que actúa como un cojín entre el fémur (hueso del muslo), la tibia (hueso de la espinilla) y la rótula. En la gonartrosis, este cartílago se desgasta, se agrieta y desaparece gradualmente. Sin esta protección, los huesos terminan rozando directamente entre sí (hueso con hueso), lo que genera fricción severa, formación de espolones óseos (osteofitos), inflamación, dolor agudo y pérdida de la movilidad en la pierna." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas se desarrollan lentamente y empeoran con el paso de los años:", groups: [ { name: "Síntomas Articulares y Mecánicos", items: ["Dolor en la rodilla que empeora con la actividad (caminar, subir o bajar escaleras, arrodillarse) y mejora con el reposo", "Rigidez articular marcada al despertar por la mañana o después de estar sentado un rato (suele durar menos de 30 minutos)", "Sensación de roce, crujidos o chasquidos audibles (crepitación) al doblar la rodilla", "Hinchazón intermitente alrededor de la articulación debido a la inflamación del líquido sinovial (derrame articular)", "Pérdida de flexibilidad, incapacidad para estirar o doblar la rodilla por completo", "Deformidad visible en etapas avanzadas (la rodilla se arquea hacia adentro o hacia afuera)"] } ], warning: "Un dolor agudo repentino y bloqueo de la rodilla (no poder estirarla) en alguien con gonartrosis puede indicar un trozo de cartílago roto flotando suelto dentro de la articulación (cuerpo libre)." }, types: { title: "Causas y Factores de Riesgo", intro: "La artrosis de rodilla es el resultado del desgaste mecánico prolongado, acelerado por:", items: ["Edad (el riesgo aumenta exponencialmente después de los 50 años por el envejecimiento natural del cartílago)", "Obesidad o sobrepeso (el factor modificable más destructivo, ya que cada kilo extra ejerce una presión masiva sobre las rodillas al caminar)", "Traumatismos previos: Antiguas roturas de ligamentos cruzados (LCA), desgarros de menisco o fracturas articulares multiplican el riesgo de artrosis futura.", "Genética (tendencia familiar al desgaste articular temprano)", "Factores ocupacionales (trabajos que requieren cargar peso, arrodillarse constantemente o estar en cuclillas)", "Anatomía alterada (tener piernas en 'X' o arqueadas distribuye el peso de forma desigual)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El traumatólogo lo diagnostica rápidamente con examen e imagen:", items: ["Examen físico (evaluación de la marcha, rango de movimiento, dolor a la palpación y alineación de la pierna)", "Radiografías de la rodilla en carga (de pie): Es el examen de oro. Muestra el estrechamiento del espacio entre los huesos (donde debería estar el cartílago faltante) y la presencia de espolones óseos (osteofitos).", "Resonancia Magnética (RM): Rara vez es necesaria para diagnosticar la artrosis, pero se usa para ver si hay un desgarro de menisco o ligamento oculto acompañando al dolor."], note: "El grado de desgaste que se ve en la radiografía no siempre coincide con el dolor: personas con artrosis severa en la imagen pueden tener poco dolor, y viceversa." }, treatment: { title: "Tratamientos", intro: "No existe cura para regenerar el cartílago desgastado. El tratamiento es escalonado, desde cambios en el estilo de vida hasta cirugía:", subsections: [ { title: "Manejo Conservador (Primera Línea)", items: ["Pérdida de peso: Fundamental e innegociable. Bajar de peso reduce inmediatamente el dolor al quitar la carga destructiva sobre el hueso desnudo.", "Fisioterapia: Ejercicios de bajo impacto (natación, bicicleta estática) para fortalecer el músculo cuádriceps, que actúa como el principal amortiguador de la rodilla.", "Analgésicos y AINEs: Paracetamol, Ibuprofeno o Diclofenaco (orales o en gel tópico) para controlar el dolor y la inflamación.", "Ayudas ortopédicas: Uso de bastón (en la mano opuesta a la rodilla mala), plantillas o rodilleras de descarga para realinear la pierna."] }, { title: "Inyecciones y Cirugía", items: ["Infiltraciones con corticosteroides: Inyecciones directas en la rodilla para calmar rápidamente la inflamación severa (alivio temporal de meses).", "Viscosuplementación: Inyecciones de ácido hialurónico, que actúan como lubricante artificial para la articulación (los resultados varían).", "Prótesis Total de Rodilla (Artroplastia): La solución quirúrgica definitiva para la gonartrosis severa. El cirujano corta los extremos de los huesos desgastados y los reemplaza con piezas artificiales de metal y plástico de alta resistencia, eliminando el dolor y restaurando la movilidad."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide cita con un especialista en traumatología si:", items: ["El dolor de rodilla te impide caminar distancias cortas, hacer tus compras o subir escaleras sin ayuda", "El dolor es tan intenso que te despierta por las noches o dependes de pastillas para el dolor todos los días", "Tu rodilla se hincha frecuentemente, se deforma o cede repentinamente bajo tu peso"] } },
'Radiculopatía cervical' : { intro: "La radiculopatía cervical es una afección neurológica, coloquialmente conocida como 'nervio pellizcado', en la que una raíz nerviosa de la columna cervical (cuello) se inflama o se comprime, provocando dolor, debilidad y alteraciones sensoriales que se irradian hacia el hombro, el brazo o la mano.", whatIs: { title: "¿Qué es la Radiculopatía Cervical?", text: "La médula espinal envía ramas (raíces nerviosas) a través de pequeños canales en las vértebras del cuello para controlar y dar sensibilidad a los brazos. Si un disco intervertebral se hernia (se rompe) o si se forman espolones óseos por desgaste (artrosis), estos pueden invadir el espacio del canal y aplastar o irritar químicamente la raíz del nervio. El cerebro interpreta este daño en el cuello enviando una señal de dolor intenso a lo largo de todo el camino que recorre ese nervio hacia el brazo." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas son altamente específicos del nervio que está siendo aplastado (por ejemplo, el nervio C6 afecta el pulgar, el C7 el dedo medio):", groups: [ { name: "Síntomas Neurológicos Irradiados", items: ["Dolor agudo, punzante o quemante que comienza en el cuello y 'baja' como una corriente eléctrica por el hombro, el brazo, el antebrazo o hasta los dedos de la mano", "Entumecimiento, hormigueo profundo o sensación de 'alfileres y agujas' (parestesia) en un área específica del brazo o la mano", "Debilidad muscular en el brazo, hombro o mano (dificultad para levantar objetos, pérdida de fuerza en el agarre)", "El dolor a menudo empeora al mover el cuello (especialmente al inclinar la cabeza hacia atrás o hacia el lado dolorido)", "El dolor puede aliviarse colocando la mano del brazo afectado sobre la parte superior de la cabeza (Signo de abducción del hombro, ya que esto quita tensión al nervio)"] } ], warning: "La debilidad progresiva o la pérdida total de sensibilidad en el brazo, o problemas de coordinación en las piernas al caminar, indican que la compresión es severa o está afectando a la médula espinal (mielopatía), requiriendo evaluación neuroquirúrgica urgente." }, types: { title: "Causas Principales", intro: "Existen dos mecanismos principales que pellizcan el nervio, dependiendo de la edad:", items: ["Hernia discal cervical: Es la causa más común en personas jóvenes (20 a 40 años). Ocurre por un esfuerzo, traumatismo o movimiento brusco que rompe el disco y el gel interior sale presionando el nervio.", "Espondilosis cervical (Artrosis del cuello): Es la causa principal en personas mayores de 50 años. El desgaste crónico hace que los discos se encojan y se formen picos de hueso (osteofitos) alrededor de las articulaciones, estrechando lentamente el agujero por donde sale el nervio (estenosis foraminal)."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico combina la exploración física con pruebas de imagen:", items: ["Examen neurológico completo: El médico evaluará la fuerza, la sensibilidad en los dedos y los reflejos (como el del tríceps o bíceps) para deducir qué raíz nerviosa exacta está atrapada. Realizará la maniobra de Spurling (presionar la cabeza hacia abajo) para ver si reproduce el dolor del brazo.", "Resonancia Magnética (RM) cervical: La prueba de oro y la más precisa para visualizar tejidos blandos; muestra claramente los discos herniados y los nervios comprimidos.", "Radiografías de columna cervical: Útiles para ver el desgaste óseo y los espolones.", "Electromiografía (EMG): Si el diagnóstico no está claro, esta prueba mide la actividad eléctrica del músculo para confirmar que hay daño nervioso continuo."], note: "" }, treatment: { title: "Tratamientos", intro: "Afortunadamente, la gran mayoría de las radiculopatías cervicales (especialmente por hernias) mejoran y se resuelven sin cirugía con el paso de las semanas:", subsections: [ { title: "Tratamientos Conservadores (Primera Línea)", items: ["Reposo relativo breve y uso de collarín cervical blando (solo por unos días durante el dolor más agudo para evitar irritar más el nervio).", "Medicamentos: Antiinflamatorios (AINEs como Ibuprofeno, Naproxeno) y a menudo un ciclo corto de Corticosteroides orales (Prednisona) para reducir drásticamente la inflamación del nervio. Neuromoduladores (Gabapentina) para el dolor de hormigueo.", "Fisioterapia: Tracciones cervicales suaves, movilización y ejercicios para abrir el espacio por donde pasa el nervio y fortalecer los músculos del cuello.", "Inyecciones Epidurales de Esteroides: Bajo guía de rayos X, el especialista en dolor inyecta un potente antiinflamatorio directamente alrededor del nervio pinzado en la columna para aliviar el dolor severo."] }, { title: "Tratamiento Quirúrgico", items: ["Discectomía y fusión cervical anterior (ACDF): Si el dolor es incapacitante tras semanas de tratamiento, o si la debilidad del brazo empeora, el neurocirujano o traumatólogo retira el disco herniado o el espolón por la parte delantera del cuello para liberar el nervio, y luego fusiona las vértebras con un pequeño implante.", "Reemplazo de disco artificial: Una alternativa moderna a la fusión que preserva el movimiento del cuello."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude al especialista en columna o a emergencias si:", items: ["Sufres un dolor fulminante que se dispara por tu brazo como un rayo", "Notas que tu brazo o mano se está volviendo torpe, débil, o dejas caer los objetos involuntariamente", "El dolor no responde a analgésicos fuertes y no te permite dormir"] } },
'Enfisema pulmonar' : { intro: "El enfisema pulmonar es una enfermedad respiratoria crónica, progresiva e irreversible que forma parte de la Enfermedad Pulmonar Obstructiva Crónica (EPOC). Se caracteriza por la destrucción destructiva de los pequeños sacos de aire de los pulmones (los alvéolos), reduciendo drásticamente la capacidad del cuerpo para oxigenar la sangre.", whatIs: { title: "¿Qué es el Enfisema?", text: "Normalmente, los alvéolos de los pulmones son microscópicos, elásticos y con forma de racimos de uvas, proporcionando una gran superficie para que el oxígeno pase a la sangre. En el enfisema, los irritantes tóxicos (principalmente el humo del tabaco) destruyen las frágiles paredes entre estos sacos. Los racimos se fusionan formando bolsas de aire grandes e irregulares que no funcionan bien. Peor aún, los pulmones pierden su elasticidad natural; al exhalar, las vías respiratorias se colapsan, atrapando el aire 'viejo' en los pulmones y dejando poco espacio para inhalar aire fresco con oxígeno. Esto causa una asfixia o falta de aire constante." }, symptoms: { title: "Síntomas Comunes", intro: "El enfisema se desarrolla muy lentamente durante años; es posible que no se noten síntomas hasta que el daño pulmonar es significativo (a menudo a partir de los 50 años):", groups: [ { name: "Síntomas Respiratorios y Físicos", items: ["Falta de aire (disnea) progresiva: Al principio solo ocurre al hacer esfuerzos físicos, pero eventualmente se presenta al caminar distancias cortas o incluso estando en reposo.", "Opresión crónica en el pecho o sensación de no poder llenar los pulmones de aire por completo", "Tos frecuente, a menudo produciendo moco (especialmente si hay bronquitis crónica asociada)", "Sibilancias (sonido de silbido al respirar)", "Forma del tórax en tonel: El pecho se vuelve anormalmente grande y redondeado porque los pulmones están hiperinflados y llenos de aire atrapado.", "Fatiga extrema, letargo y pérdida de peso no intencionada (respirar con pulmones dañados quema muchísimas calorías)", "Coloración azulada o grisácea en labios y lechos ungueales (cianosis) debido a la falta de oxígeno en etapas severas"] } ], warning: "Una infección respiratoria común (como un resfriado o gripe) en alguien con enfisema puede desencadenar una exacerbación aguda, bloqueando totalmente la respiración y requiriendo hospitalización inmediata." }, types: { title: "Causas y Factores de Riesgo", intro: "El daño a los alvéolos está directamente causado por toxinas inhaladas:", items: ["Tabaquismo: Es la causa absoluta y principal de casi todos los casos de enfisema. A mayor cantidad y años fumando, mayor la destrucción pulmonar.", "Exposición pasiva al humo del tabaco a largo plazo", "Exposición ocupacional crónica: Inhalación constante de humos químicos, polvo de sílice, carbón o humos de soldadura y cocina con biomasa en interiores mal ventilados.", "Deficiencia de Alfa-1 antitripsina (AAT): Una causa genética rara en la cual las personas nacen sin una proteína clave que protege los pulmones de la destrucción enzimática. Afecta a personas más jóvenes y no fumadoras."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El neumólogo confirmará el daño pulmonar y la pérdida de función mediante:", items: ["Espirometría (Pruebas de Función Pulmonar): Es la prueba de oro. Mides cuánto aire puedes exhalar y a qué velocidad. En el enfisema, la velocidad de exhalación está severamente reducida por la obstrucción.", "Tomografía Computarizada (TC) de Tórax: Muestra con precisión quirúrgica los agujeros y la destrucción del tejido pulmonar (mucho más sensible que una radiografía simple).", "Radiografía de tórax: A menudo muestra pulmones agrandados y oscuros.", "Gasometría arterial o pulsioximetría: Para medir qué tan bien los pulmones transfieren oxígeno a la sangre y eliminan el dióxido de carbono.", "Análisis de sangre para descartar la deficiencia genética de Alfa-1 antitripsina (especialmente si el paciente es menor de 45 años)."], note: "" }, treatment: { title: "Tratamientos", intro: "El tejido pulmonar destruido no puede regenerarse. El tratamiento se centra en detener el avance del daño, aliviar la asfixia y mejorar la calidad de vida:", subsections: [ { title: "Modificación del Estilo de Vida y Medicamentos", items: ["Dejar de Fumar: Es el único paso que puede frenar la progresión de la enfermedad. Si sigues fumando, ningún medicamento detendrá el daño.", "Broncodilatadores Inhalados (Inhaladores): Medicamentos (como Tiotropio, Salmeterol o Albuterol) que relajan y abren las vías respiratorias colapsadas, facilitando la exhalación del aire atrapado.", "Corticosteroides inhalados u orales: Para reducir la inflamación severa y las exacerbaciones (frecuentemente combinados con broncodilatadores).", "Rehabilitación Pulmonar: Un programa esencial de ejercicios, técnicas de respiración (como respirar con los labios fruncidos) y educación nutricional para enseñar a vivir y ejercitarse con menos oxígeno sin entrar en pánico.", "Oxigenoterapia suplementaria: Prescrita si los niveles de oxígeno en sangre caen por debajo de los límites seguros. A menudo se requiere usar bombonas o concentradores de oxígeno las 24 horas del día en etapas avanzadas.", "Cirugía: En casos extremos (y muy seleccionados), la cirugía de reducción de volumen pulmonar elimina partes de tejido muy dañado para dar espacio al tejido sano restante a expandirse. El trasplante de pulmón es la última opción."] } ], note: "La vacunación anual contra la gripe y la vacuna contra el neumococo (neumonía) son de vida o muerte para los pacientes con enfisema, ya que las neumonías pueden ser letales en pulmones comprometidos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de urgencias o llama al 911 de inmediato si tú o tu familiar con EPOC presenta:", items: ["Dificultad extrema para respirar que te impide hablar, comer o caminar unos pasos", "Uñas, dedos o labios que se vuelven azules o grises (falta severa de oxígeno)", "Confusión mental, desorientación o letargo inusual"] } },
'Rítides facial' : { intro: "Las rítides faciales son el término médico y dermatológico para las arrugas, surcos, pliegues o líneas que se forman en la piel de la cara y el cuello. Aunque son una parte natural e inevitable del proceso de envejecimiento, su aparición prematura suele ser una fuente importante de preocupación estética.", whatIs: { title: "¿Qué son las Rítides Faciales?", text: "Nuestra piel se mantiene firme, tersa y sin arrugas gracias a una red profunda de colágeno, elastina y ácido hialurónico, sumado a una capa de grasa subcutánea. Con el paso del tiempo, el daño solar acumulado y los cambios biológicos, el cuerpo disminuye la producción de estas proteínas clave. La piel se vuelve más delgada, seca y pierde su capacidad de 'rebotar' o volver a su sitio después de estirarse. Además, la pérdida de hueso y grasa facial con la edad hace que la piel caiga, creando pliegues permanentes." }, symptoms: { title: "Características Clínicas", intro: "Las rítides se manifiestan en áreas específicas y con diferentes texturas:", groups: [ { name: "Signos Visuales", items: ["Líneas finas superficiales en las mejillas o alrededor de la boca ('código de barras' en el labio superior)", "Arrugas profundas y marcas de expresión, típicamente alrededor de los ojos ('patas de gallo'), la frente y el entrecejo (líneas del ceño fruncido)", "Surcos profundos que van desde la nariz hasta las comisuras de la boca (surcos nasogenianos)", "Flacidez de la piel y pliegues caídos en la línea de la mandíbula (jowls) o en el cuello"] } ], warning: "Las arrugas no son una condición médica de emergencia, pero los cambios rápidos en la piel, como parches de engrosamiento o heridas que no sanan entre las arrugas, deben ser evaluados por riesgo de cáncer de piel debido al daño solar asociado." }, types: { title: "Clasificación de las Rítides", intro: "Los dermatólogos dividen las arrugas en dos grandes grupos según su causa mecánica, lo cual define su tratamiento:", items: ["Rítides Dinámicas: Son causadas por la repetida contracción de los músculos faciales al hacer expresiones (sonreír, fruncir el ceño, entrecerrar los ojos). Al principio solo aparecen al hacer el gesto, pero con el tiempo se marcan en la piel. (Ejemplo clásico: patas de gallo y líneas de la frente).", "Rítides Estáticas: Son los pliegues y arrugas que siempre están visibles, incluso cuando el rostro está completamente relajado e inmóvil. Se deben a la pérdida de colágeno, la flacidez de la gravedad y el daño solar crónico."], note: "" }, causes: { title: "Causas y Factores de Envejecimiento", intro: "El desarrollo de arrugas está impulsado por el 'exposoma' (factores externos) y la genética:", items: ["Exposición al sol (Fotoenvejecimiento): Es, con abrumadora diferencia, la principal causa de las arrugas precoces. La radiación ultravioleta (UV) rompe directamente el tejido conectivo (colágeno y fibras de elastina) en la dermis profunda.", "Envejecimiento natural (cronológico): Disminución biológica de hormonas, aceites naturales, colágeno y afinamiento epidérmico.", "Tabaquismo: La nicotina y las toxinas estrechan fuertemente los vasos sanguíneos que irrigan la piel, privándola de oxígeno y nutrientes, y bloqueando la producción de colágeno, creando el clásico 'rostro de fumador'.", "Expresiones faciales repetitivas (gesticulación excesiva).", "Contaminación ambiental y falta de sueño o hidratación crónica."] }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "Es una evaluación clínica puramente estética:", items: ["Examen visual dermatológico o de medicina estética", "Clasificación de Glogau (mide el grado de fotoenvejecimiento basado en las arrugas en reposo o en movimiento)", "Análisis fotográfico o luces UV en clínicas estéticas para revelar el daño solar oculto y la profundidad de los poros"], note: "" }, treatment: { title: "Tratamientos y Prevención", intro: "El tratamiento estético cuenta con un arsenal enorme, desde rutinas de cuidado hasta cirugía:", subsections: [ { title: "Prevención y Tratamientos Tópicos", items: ["Protección solar estricta: El uso diario de protector solar (FPS 30 o más) es el tratamiento antienvejecimiento más importante y comprobado.", "Retinoides (Tretinoína/Retinol): Derivados de la Vitamina A aplicados en crema por las noches. Es el compuesto tópico más respaldado por la ciencia para reducir arrugas finas, estimulando la renovación celular y el colágeno.", "Antioxidantes (Vitamina C): Sueros matutinos para proteger del daño de radicales libres y la contaminación."] }, { title: "Procedimientos Estéticos Minimamente Invasivos", items: ["Toxina Botulínica (Botox): El tratamiento de elección y estándar de oro para las rítides DINÁMICAS (frente, entrecejo, patas de gallo). Relaja temporalmente el músculo que causa la arruga, alisando la piel.", "Rellenos Dérmicos (Ácido Hialurónico): Se inyectan como un gel para rellenar desde abajo las rítides ESTÁTICAS profundas (surcos nasogenianos, labios) o restaurar el volumen perdido en pómulos.", "Terapias de Láser (Láser CO2, Fraxel) y Radiofrecuencia: Queman o calientan las capas de la piel de forma controlada para forzar al cuerpo a crear colágeno nuevo y piel fresca, eliminando arrugas y manchas solares.", "Peelings químicos y Microneedling (Microagujas): Remueven las capas superiores de la piel vieja y estimulan la reparación de colágeno para líneas finas y textura de la piel."] }, { title: "Cirugía Plástica", items: ["Ritidectomía (Lifting facial o estiramiento facial): Cirugía para eliminar el exceso de piel flácida y tensar los músculos profundos del rostro y el cuello. Es el tratamiento definitivo para la flacidez y arrugas profundas causadas por la gravedad que no responden a inyectables."] } ], note: "Ninguna crema 'antiarrugas' comercial, sin importar su precio, puede eliminar arrugas profundas ni levantar la piel flácida como lo hace la medicina estética o la cirugía." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un dermatólogo o cirujano plástico certificado si:", items: ["Las arrugas o los cambios en tu piel están afectando negativamente tu autoestima y bienestar psicológico", "Deseas explorar opciones de tratamiento médico estético de manera segura", "Notas una lesión o 'arruga' en la piel que sangra, pica o no se cura, para descartar daño actínico o cáncer de piel"] } },
'Osteomielitis' : { intro: "La osteomielitis es una infección del hueso súbita o de larga duración. Puede ser una afección grave que requiere tratamiento médico inmediato para evitar la muerte del tejido óseo y su propagación a otras partes del cuerpo.", whatIs: { title: "¿Qué es la Osteomielitis?", text: "Es una inflamación ósea causada por bacterias o, menos frecuentemente, por hongos. Los microorganismos pueden llegar al hueso a través del torrente sanguíneo, propagarse desde un tejido infectado cercano o entrar directamente al hueso si hay una herida abierta o una fractura expuesta." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos varían según la edad y la causa, pero suelen incluir:", groups: [ { name: "Síntomas Locales", items: ["Dolor severo e intenso en el hueso afectado", "Hinchazón, enrojecimiento y sensación de calor en el área de la infección", "Incapacidad para mover la extremidad afectada o soportar peso"] }, { name: "Síntomas Sistémicos", items: ["Fiebre alta, escalofríos y sudoración", "Fatiga extrema y malestar general (letargo)", "Drenaje de pus a través de la piel en casos avanzados"] } ], warning: "La osteomielitis no tratada puede provocar la muerte del hueso (necrosis), abscesos profundos y, en casos extremos, requerir amputación para salvar la vida." }, types: { title: "Tipos de Infección", intro: "Se clasifica según cómo se originó la infección:", items: ["Diseminación hematógena: La bacteria viaja por la sangre desde otra parte del cuerpo (común en niños).", "Contigüidad: Se propaga desde una infección cercana, como una úlcera en el pie diabético.", "Inoculación directa: La bacteria entra por un traumatismo penetrante, cirugía ortopédica o fractura abierta."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El patógeno más común es el Staphylococcus aureus. Los riesgos incluyen:", items: ["Diabetes mal controlada (especialmente en los pies)", "Problemas de circulación periférica", "Uso prolongado de catéteres intravenosos o diálisis", "Cirugía ortopédica reciente o reemplazos articulares", "Sistema inmunológico debilitado"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para identificar el hueso infectado y la bacteria exacta:", items: ["Análisis de sangre (elevación de glóbulos blancos y marcadores de inflamación como VSG y PCR)", "Hemocultivos para detectar bacterias en la sangre", "Radiografías (pueden no mostrar daño óseo hasta semanas después)", "Resonancia Magnética (RM) o Gammagrafía ósea (muy sensibles para detectar infecciones tempranas)", "Biopsia ósea (el estándar de oro para identificar el germen y recetar el antibiótico correcto)"], note: "" }, treatment: { title: "Tratamientos", intro: "Requiere un abordaje agresivo médico y a menudo quirúrgico:", subsections: [ { title: "Opciones de Manejo", items: ["Antibióticos intravenosos (IV) prolongados: Generalmente se administran durante 4 a 6 semanas en el hospital o en casa mediante catéter.", "Desbridamiento quirúrgico: Cirugía para limpiar la herida, drenar el pus y extirpar todo el hueso y tejido muerto o infectado.", "Cirugía de restauración del flujo sanguíneo o injertos óseos en el espacio vacío dejado por el tejido extraído.", "Amputación (como último recurso extremo para detener una infección descontrolada)."] } ], note: "El tratamiento oportuno es clave para prevenir que la infección se vuelva crónica y recurrente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de urgencias de inmediato si:", items: ["Sientes un dolor óseo profundo y repentino acompañado de fiebre", "Notas un área de tu cuerpo enrojecida, caliente, hinchada y muy dolorosa", "Tienes una herida o úlcera que no sana y comienza a supurar pus o huele mal"] } },
'Retinopatía hipertensiva' : { intro: "La retinopatía hipertensiva es el daño a los delicados vasos sanguíneos de la retina (la parte posterior del ojo responsable de la visión) causado por la presión arterial alta crónica o severa no controlada.", whatIs: { title: "¿Qué es la Retinopatía Hipertensiva?", text: "La hipertensión arterial sostenida hace que las paredes de los diminutos vasos sanguíneos del ojo se engrosen, estrechen y, finalmente, se dañen. Esto reduce el flujo de sangre a la retina, lo que puede provocar pequeñas hemorragias, inflamación de la mácula y daño al nervio óptico, comprometiendo gravemente la visión." }, symptoms: { title: "Síntomas Comunes", intro: "En etapas tempranas a moderadas no suele haber síntomas perceptibles. Cuando avanza, puede causar:", groups: [ { name: "Problemas Visuales", items: ["Visión borrosa o doble", "Disminución gradual de la agudeza visual", "Puntos ciegos o 'moscas volantes' debido a sangrados microscópicos", "Pérdida de visión repentina en casos de crisis hipertensiva extrema"] } ], warning: "La retinopatía hipertensiva severa (con inflamación del nervio óptico o papiledema) es un signo de emergencia hipertensiva maligna que requiere hospitalización inmediata." }, types: { title: "Grados de Severidad", intro: "Los oftalmólogos clasifican el daño en una escala (generalmente de Keith-Wagener-Barker):", items: ["Grado 1 y 2: Estrechamiento leve a moderado de las arterias retinianas (generalmente asintomático).", "Grado 3: Aparición de hemorragias retinianas, exudados algodonosos (áreas isquémicas) y daño evidente.", "Grado 4: Todo lo anterior más inflamación del disco óptico (papiledema), indicando un daño orgánico severo en el cuerpo."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El único desencadenante es la presión arterial elevada prolongada. Factores que la empeoran:", items: ["Presión arterial crónica alta y mal controlada", "Duración prolongada de la hipertensión (años sin tratamiento)", "Coexistencia de diabetes (aumenta exponencialmente el daño vascular)", "Tabaquismo y niveles altos de colesterol", "Embarazo (preeclampsia)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es diagnosticada durante un examen de la vista de rutina:", items: ["Examen de fondo de ojo con pupilas dilatadas (el oftalmoscopio permite ver directamente los vasos estrechados o sangrantes)", "Angiografía con fluoresceína (se inyecta un tinte para ver el flujo de sangre y detectar fugas en la retina)", "Tomografía de Coherencia Óptica (OCT) para evaluar la inflamación o líquido debajo de la mácula"], note: "El oftalmólogo a menudo es el primer médico en detectar que una persona tiene hipertensión severa." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca completamente en la causa raíz:", subsections: [ { title: "Opciones de Manejo", items: ["Control estricto de la presión arterial: Es el único tratamiento primario efectivo (mediante medicamentos antihipertensivos, dieta DASH, ejercicio).", "Láser o inyecciones intraoculares: Si hay complicaciones como inflamación de la mácula (edema macular) o bloqueo severo de las venas, se pueden usar tratamientos oftalmológicos específicos para salvar la vista."] } ], note: "Bajar la presión arterial de forma segura puede revertir gran parte del daño en las etapas tempranas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca ayuda médica urgente si tienes hipertensión y:", items: ["Sufres cambios repentinos en la visión (borrosidad, manchas oscuras)", "Experimentas dolores de cabeza severos acompañados de visión doble o náuseas", "Todo paciente hipertenso debe someterse a un examen ocular dilatado al menos una vez al año"] } },
'Trastorno de personalidad histriónica' : { intro: "El trastorno de personalidad histriónica (TPH) es una afección psiquiátrica caracterizada por un patrón de comportamiento crónico de búsqueda excesiva de atención y emocionalidad extrema, que comienza típicamente en la edad adulta temprana.", whatIs: { title: "¿Qué es el TPH?", text: "Las personas con este trastorno sienten una necesidad abrumadora de ser el centro de atención. Para lograrlo, suelen exhibir un comportamiento teatral, dramático o inapropiadamente seductor. Si sienten que están siendo ignorados, experimentan un malestar profundo. A menudo, sus emociones parecen intensas pero cambian rápidamente y carecen de profundidad, lo que dificulta el mantenimiento de relaciones auténticas." }, symptoms: { title: "Síntomas y Señales Clave", intro: "El patrón de comportamiento incluye varias de estas características:", groups: [ { name: "Conductas y Emociones", items: ["Sentirse muy incómodo o poco apreciado cuando no se es el centro de atención", "Comportamiento social inapropiadamente provocativo, coqueto o sexualmente seductor", "Cambios rápidos y superficiales en las emociones", "Uso constante del aspecto físico para atraer la mirada de los demás", "Hablar de forma excesivamente impresionista pero con falta de detalles", "Autodramatización, teatralidad y expresión exagerada de las emociones", "Ser muy sugestionable y fácilmente influenciable por los demás o las circunstancias", "Considerar las relaciones más íntimas de lo que realmente son"] } ], warning: "A pesar de la aparente confianza y sociabilidad externa, las personas con TPH a menudo sufren una baja autoestima y tienen un mayor riesgo de depresión, ansiedad y conductas suicidas en busca de atención." }, types: { title: "Relación con otros Trastornos", intro: "Pertenece al Grupo B (trastornos dramáticos, erráticos o emocionales) del DSM-5, junto con:", items: ["Trastorno límite de la personalidad (Borderline)", "Trastorno narcisista de la personalidad", "Trastorno antisocial de la personalidad"], note: "Los límites entre estos trastornos a menudo se superponen y pueden presentarse conjuntamente." }, causes: { title: "Causas y Factores de Riesgo", intro: "El origen exacto es desconocido, pero se cree que es una combinación de:", items: ["Factores genéticos (tendencia heredada hacia la alta reactividad emocional)", "Eventos de la primera infancia (falta de disciplina, refuerzo positivo solo ante comportamientos dramáticos, modelado de comportamientos erráticos de los padres)", "Mecanismos de defensa desarrollados como respuesta a traumas psicológicos tempranos"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es evaluado por un profesional de la salud mental:", items: ["Entrevista clínica exhaustiva y evaluación psiquiátrica", "Análisis de patrones de comportamiento a largo plazo (no solo un evento aislado)", "Comparación con los criterios de diagnóstico del Manual Diagnóstico y Estadístico de los Trastornos Mentales (DSM-5)"], note: "El diagnóstico no se suele hacer hasta la edad adulta, cuando los patrones de personalidad están completamente formados." }, treatment: { title: "Tratamientos", intro: "La persona a menudo no cree que necesita terapia a menos que enfrente depresión o una crisis personal:", subsections: [ { title: "Opciones Terapéuticas", items: ["Psicoterapia (Terapia de conversación): Es el tratamiento principal. Ayuda a la persona a descubrir las motivaciones detrás de sus comportamientos y a aprender formas más saludables y asertivas de relacionarse con los demás.", "Terapia psicodinámica o analítica: Para abordar conflictos emocionales profundos de la infancia.", "Medicamentos: No existen fármacos para tratar directamente el TPH, pero se pueden recetar antidepresivos o ansiolíticos si el paciente presenta episodios de depresión o ansiedad severa."] } ], note: "La constancia en la terapia es un reto, ya que los pacientes tienden a aburrirse rápido o a dramatizar su recuperación." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Se sugiere buscar orientación psicológica si:", items: ["Tu comportamiento causa problemas crónicos en tu lugar de trabajo o en tus relaciones de pareja", "Sientes un vacío emocional abrumador o depresión cuando estás solo o no eres el foco de atención", "Tienes pensamientos de hacerte daño para demostrar un punto a los demás o buscar consuelo"] } },
'Infecciones de vías urinarias' : { intro: "Las infecciones de las vías urinarias (IVU) son infecciones comunes que ocurren cuando bacterias, típicamente del tracto digestivo, ingresan a la uretra y se multiplican en las vías urinarias. Pueden afectar la uretra, la vejiga o subir hasta los riñones.", whatIs: { title: "¿Qué son las IVU?", text: "El sistema urinario está diseñado para mantener alejadas las infecciones, pero estas defensas a veces fallan. Las mujeres tienen un riesgo mucho mayor de contraer una IVU que los hombres, principalmente debido a que su uretra es más corta y está más cerca del ano, facilitando el paso de bacterias (como E. coli) hacia la vejiga." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían dependiendo de qué parte del tracto urinario esté infectada:", groups: [ { name: "Vías Bajas (Cistitis/Uretritis)", items: ["Sensación de ardor intenso o escozor al orinar (disuria)", "Necesidad constante y urgente de orinar, aunque solo salga un poco", "Orina de aspecto turbio, oscuro, con sangre (rosado o rojizo) o con un olor muy fuerte", "Presión, molestias o dolor sordo en la parte baja del abdomen o la pelvis"] }, { name: "Vías Altas (Pielonefritis o Infección Renal)", items: ["Dolor en la parte superior de la espalda o en los costados (dolor de flanco)", "Fiebre alta, temblores y escalofríos intensos", "Náuseas y vómitos"] } ], warning: "Una infección renal no tratada es grave y puede provocar sepsis (infección en la sangre) y daño renal permanente. Requiere atención médica inmediata." }, types: { title: "Clasificación Anatómica", intro: "Las IVU se nombran según el órgano afectado:", items: ["Cistitis: Infección de la vejiga (la más común).", "Uretritis: Infección de la uretra (el conducto que saca la orina).", "Pielonefritis: Infección de uno o ambos riñones (la más peligrosa)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La mayoría son causadas por bacterias fecales, impulsadas por:", items: ["Anatomía femenina (uretra corta)", "Actividad sexual (que puede empujar bacterias hacia la uretra)", "Ciertos tipos de anticonceptivos (diafragmas o agentes espermicidas)", "Menopausia (la falta de estrógeno vuelve el tejido más frágil)", "Obstrucciones urinarias (cálculos renales o próstata agrandada)", "Uso de catéteres urinarios (sondas) en hospitales", "Sistema inmunológico deprimido (como en la diabetes)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico rápido y rutinario:", items: ["Análisis general de orina (para buscar glóbulos blancos, glóbulos rojos o bacterias)", "Urocultivo (para hacer crecer la bacteria en el laboratorio e identificar qué antibiótico es el mejor)", "Ecografía, TC o Cistoscopia (generalmente solo se utilizan si tienes infecciones recurrentes frecuentes para buscar anomalías estructurales)"], note: "" }, treatment: { title: "Tratamientos", intro: "Los antibióticos son la primera y más efectiva línea de defensa:", subsections: [ { title: "Opciones de Manejo", items: ["Antibióticos orales: (Como Fosfomicina, Nitrofurantoína o Cefalexina) prescritos generalmente de 3 a 7 días. Es vital terminar todo el tratamiento, incluso si te sientes mejor.", "Analgésicos urinarios: (Como Fenazopiridina) para aliviar el ardor intenso al orinar de inmediato, aunque pondrán la orina de color naranja brillante.", "Aumento de líquidos: Beber abundante agua para ayudar a 'lavar' las bacterias del tracto.", "Terapia intravenosa: Necesaria si la infección ha llegado a los riñones de forma severa, requiriendo ingreso hospitalario."] } ], note: "El jugo de arándano rojo no cura una infección activa, pero en algunas mujeres ayuda a prevenir recurrencias." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Contacta a un médico si:", items: ["Sientes dolor o ardor al orinar durante más de 24 horas", "Ves sangre en tu orina", "Desarrollas fiebre, escalofríos, náuseas o dolor fuerte en la espalda baja (síntomas de alarma de infección renal)"] } },
'Aneurisma aórtico abdominal' : { intro: "Un aneurisma aórtico abdominal (AAA) es un área ensanchada y abultada en la parte inferior de la aorta, el vaso sanguíneo más grande del cuerpo, que baja directamente desde el corazón y suministra sangre al abdomen, la pelvis y las piernas.", whatIs: { title: "¿Qué es un AAA?", text: "La pared de la aorta normalmente es fuerte y muscular. Debido al envejecimiento, el tabaquismo y la presión arterial alta, esta pared puede debilitarse. El flujo constante y a alta presión de la sangre hace que esa zona débil se infle como un globo. Si el aneurisma crece demasiado, la pared arterial se vuelve tan fina que puede romperse. Una ruptura aórtica provoca un sangrado interno masivo e incontrolable, siendo un evento catastrófico que a menudo resulta fatal." }, symptoms: { title: "Síntomas y Alertas", intro: "La mayoría de los aneurismas crecen lentamente sin causar ningún síntoma, pero a medida que se agrandan o están a punto de romperse, pueden presentarse:", groups: [ { name: "Síntomas de Aneurisma Creciente", items: ["Una sensación de latido (pulsación) profunda y constante cerca del ombligo", "Dolor profundo, sordo y constante en el abdomen o en un costado de este", "Dolor en la espalda baja que no desaparece con cambios de postura"] }, { name: "Signos Críticos de Ruptura (Emergencia Máxima)", items: ["Dolor repentino, extremadamente intenso y desgarrador en el abdomen o la espalda", "Caída abrupta de la presión arterial, causando mareos severos, desmayos o shock", "Piel pálida, sudor frío y pegajoso, y ritmo cardíaco muy acelerado", "Dificultad para respirar y debilidad extrema"] } ], warning: "Un aneurisma roto requiere cirugía de reanimación y reparación inmediata en cuestión de minutos; es una de las emergencias quirúrgicas más graves de la medicina." }, types: { title: "Tamaño y Riesgo", intro: "El manejo clínico depende del diámetro del abultamiento:", items: ["Pequeño (menos de 4 cm): Riesgo de ruptura muy bajo. Solo requiere vigilancia ecográfica anual.", "Mediano (4 a 5.4 cm): Riesgo moderado. Evaluación frecuente y control estricto de la presión arterial.", "Grande (más de 5.5 cm en hombres o 5.0 cm en mujeres): El riesgo de ruptura supera los riesgos de la cirugía; se recomienda reparación preventiva inminente."], note: "Cualquier aneurisma que crezca más de medio centímetro en solo 6 meses también requiere cirugía urgente." }, causes: { title: "Causas y Factores de Riesgo", intro: "El deterioro de la pared arterial es impulsado principalmente por:", items: ["Tabaquismo: Es el factor de riesgo número uno, el más fuerte y el más evitable (debilita las paredes de la aorta directamente).", "Edad y Sexo: Mucho más común en hombres mayores de 65 años.", "Aterosclerosis (acumulación de placas de grasa endurecida en los vasos).", "Presión arterial alta constante (que empuja contra las paredes debilitadas).", "Antecedentes familiares (componente genético muy importante)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "A menudo se descubren por accidente durante pruebas por otros motivos. Para medirlos se usa:", items: ["Ecografía abdominal (el examen más común, indoloro y preciso para medir el tamaño y monitorear el crecimiento del aneurisma)", "Tomografía Computarizada (TC) o Angio-TC (proporciona imágenes 3D exactas del tamaño, forma y localización, esenciales antes de planificar una cirugía)", "Resonancia Magnética (RM)"], note: "Se recomiendan ecografías de cribado preventivo (una sola vez en la vida) para todos los hombres mayores de 65 años que hayan fumado alguna vez." }, treatment: { title: "Tratamientos", intro: "El objetivo es prevenir la ruptura mediante observación o cirugía programada:", subsections: [ { title: "Estrategias de Reparación", items: ["Vigilancia Activa: Para aneurismas pequeños. Implica pruebas de imagen periódicas y control radical de la presión arterial y cese del tabaquismo.", "Reparación Endovascular del Aneurisma (EVAR): La opción preferida moderna. Es mínimamente invasiva. El cirujano inserta un catéter por la ingle y coloca un tubo de malla recubierto de tela (endoprótesis o stent-graft) dentro de la aorta enferma. La sangre pasa por el tubo, quitando la presión de la pared debilitada.", "Cirugía Abierta Tradicional: Se realiza un corte grande en el abdomen para extirpar la sección debilitada de la aorta y coser un tubo de injerto sintético en su lugar. La recuperación es larga (meses), pero la reparación suele ser de por vida."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a urgencias sin demora si:", items: ["Experimentas un dolor súbito e insoportable y profundo en el estómago, el costado o la espalda", "Si eres hombre mayor de 65 años, has sido fumador y nunca te han hecho una ecografía abdominal (pide un chequeo preventivo a tu médico de cabecera)"] } },
'Dolor crónico' : { intro: "El dolor crónico es un dolor persistente que dura más de tres a seis meses, sobreviviendo al tiempo de curación habitual de una lesión o enfermedad. Se considera una condición médica compleja y una enfermedad por derecho propio, más que un simple síntoma, afectando profundamente la vida física, emocional y social de la persona.", whatIs: { title: "¿Qué es el Dolor Crónico?", text: "El dolor agudo es una alarma normal que le avisa a tu cuerpo que algo está dañado y necesita sanar. En el dolor crónico, estas señales de alarma neurológicas siguen activándose en el sistema nervioso durante meses o años, incluso después de que la herida física original haya sanado por completo, o sin que exista un daño tisular activo. El sistema nervioso se vuelve hipersensible, amplificando el dolor." }, symptoms: { title: "Síntomas y Efectos", intro: "Va mucho más allá de la sensación física de molestia:", groups: [ { name: "Físicos", items: ["Dolor constante, sordo, punzante, ardiente o en forma de descargas que se mantiene día tras día", "Fatiga profunda, agotamiento y alteraciones severas del sueño (insomnio)", "Pérdida progresiva de la movilidad, fuerza y flexibilidad debido a la inactividad por miedo al dolor"] }, { name: "Psicológicos y Sociales", items: ["Ansiedad, irritabilidad y depresión clínica persistente", "Aislamiento social y dificultades en las relaciones familiares y laborales", "Sentimiento de desesperanza y reducción drástica de la calidad de vida"] } ], warning: "La dependencia o adicción a los analgésicos opioides es un riesgo grave en el manejo del dolor crónico mal supervisado." }, types: { title: "Orígenes Frecuentes", intro: "El dolor crónico puede originarse en cualquier parte, destacando:", items: ["Dolor nociceptivo: Daño persistente a tejidos como músculos, huesos o articulaciones (Artrosis, dolores de espalda mecánicos).", "Dolor neuropático: Daño o disfunción directa de los nervios (Neuropatía diabética, ciática crónica, neuralgia postherpética).", "Dolor nociplástico: Procesamiento alterado del dolor en el cerebro, sin daño evidente en nervios o tejidos (Fibromialgia, Síndrome del Intestino Irritable)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Puede ser desencadenado por:", items: ["Lesiones pasadas (traumatismos, cirugías) que dejaron daño en los nervios", "Enfermedades crónicas crónico-degenerativas (Osteoartritis, Artritis Reumatoide, Cáncer, Esclerosis Múltiple)", "Trastornos de hipersensibilidad central (Fibromialgia, migrañas crónicas)", "Factores psicológicos (el estrés crónico y los traumas emocionales pueden aumentar y perpetuar físicamente la intensidad del dolor)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un proceso complejo porque el dolor es una experiencia completamente subjetiva:", items: ["Historia clínica y uso de Escalas de Valoración del Dolor para medir intensidad y localización", "Diarios de dolor (para encontrar desencadenantes y patrones)", "Examen neurológico completo", "Pruebas de imagen (RM, radiografías) o de nervios (EMG), principalmente para descartar lesiones corregibles quirúrgicamente, no para 'validar' el dolor", "Evaluación psicológica (para entender el impacto emocional y detectar depresión asociada)"], note: "Que las radiografías salgan 'normales' no significa que el dolor no sea real; el dolor neuropático o de procesamiento central no se ve en imágenes." }, treatment: { title: "Tratamientos", intro: "La cura total rara vez es posible. El objetivo es el manejo, reduciendo el dolor y mejorando la funcionalidad mediante un enfoque multidisciplinario (Unidad del Dolor):", subsections: [ { title: "Opciones de Manejo Integral", items: ["Medicamentos: Analgésicos no opioides (Paracetamol, AINEs), Neuromoduladores (Antidepresivos tricíclicos, Gabapentina/Pregabalina para dolor nervioso), Parches de lidocaína o analgésicos tópicos.", "Intervenciones Físicas y de Fisioterapia: Ejercicio terapéutico de bajo impacto, estiramientos, TENS (Estimulación Nerviosa Eléctrica Transcutánea), acupuntura y masajes.", "Técnicas Intervencionistas: Inyecciones de corticosteroides, bloqueos nerviosos, inyecciones en los puntos gatillo o bombas de infusión implantables.", "Terapia Psicológica: Terapia Cognitivo-Conductual (TCC), mindfulness y relajación guiada para ayudar al cerebro a procesar las señales de dolor de manera diferente y tratar la depresión.", "Estimulación de la Médula Espinal: Implantes que envían señales eléctricas a la médula para interferir con las señales de dolor antes de que lleguen al cerebro."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu médico o pide una derivación a un especialista en manejo del dolor si:", items: ["El dolor ha durado más de 3 a 6 meses después de que la lesión original supuestamente sanó", "Tu dolor te impide trabajar, dormir, socializar o disfrutar de actividades básicas", "Te sientes deprimido, desesperado o dependes constantemente de medicamentos fuertes para pasar el día"] } },
'Tumor tiroideo' : { intro: "Un tumor tiroideo (comúnmente llamado nódulo tiroideo) es un crecimiento inusual de células que forma un bulto sólido o lleno de líquido dentro de la glándula tiroides, ubicada en la base frontal del cuello.", whatIs: { title: "¿Qué es un Tumor Tiroideo?", text: "La glándula tiroides produce hormonas que regulan el metabolismo del cuerpo. En ocasiones, partes del tejido crecen de manera focalizada creando nódulos. La inmensa mayoría de estos bultos (más del 90%) son benignos (no cancerosos) y no causan problemas ni necesitan tratamiento. Sin embargo, un pequeño porcentaje son cáncer de tiroides, por lo que todo bulto nuevo en el cuello debe ser evaluado por un médico." }, symptoms: { title: "Síntomas Comunes", intro: "Generalmente no causan ningún síntoma y se descubren en exámenes de rutina. Pero si crecen mucho o son hiperactivos, pueden causar:", groups: [ { name: "Síntomas Compresivos (Físicos)", items: ["Un bulto visible que se mueve hacia arriba y hacia abajo al tragar", "Sensación de presión, asfixia o de 'nudo en la garganta'", "Dificultad para tragar (disfagia) o respirar, si el nódulo presiona el esófago o la tráquea", "Ronquera inexplicable o cambios en la voz (si afecta las cuerdas vocales)"] }, { name: "Síntomas Hormonales (si el nódulo es 'tóxico' o hiperactivo)", items: ["Pérdida de peso inexplicable, nerviosismo y sudoración", "Latidos rápidos o irregulares", "Temblores y debilidad muscular (signos de hipertiroidismo)"] } ], warning: "Un bulto en la tiroides que crece rápidamente, se siente duro, fijo a la piel o viene acompañado de inflamación de los ganglios del cuello y ronquera, es un signo de alta sospecha de cáncer de tiroides." }, types: { title: "Naturaleza de los Nódulos", intro: "Los nódulos pueden tener diferentes características biológicas:", items: ["Nódulos Coloides: Sobrecrecimiento benigno de tejido tiroideo normal (el tipo más común).", "Quistes tiroideos: Bultos llenos de líquido, casi siempre benignos.", "Nódulos Inflamatorios: Debidos a una tiroiditis crónica (como la enfermedad de Hashimoto).", "Adenomas Tóxicos: Tumores benignos que producen hormona tiroidea de forma autónoma (causando hipertiroidismo).", "Cáncer de Tiroides: El riesgo es mayor si el paciente es muy joven (menor de 20 años), mayor de 70, o si el nódulo es sólido, oscuro en la ecografía o contiene microcalcificaciones."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Las razones por las que ocurren incluyen:", items: ["Deficiencia de yodo en la dieta (raro en países con sal yodada)", "Crecimiento excesivo de tejido tiroideo sano", "Antecedentes familiares de nódulos o cáncer de tiroides", "Exposición a radiación en la cabeza o el cuello durante la infancia (aumenta el riesgo de nódulos malignos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El principal objetivo es descartar el cáncer de forma segura:", items: ["Análisis de sangre para medir la TSH (hormona estimulante de la tiroides), para ver si la glándula funciona normalmente.", "Ecografía de tiroides: La prueba de imagen principal. Permite ver si el nódulo es sólido o líquido, su tamaño exacto y sus características (bordes irregulares, calcificaciones) para decidir si es sospechoso.", "Biopsia por Aspiración con Aguja Fina (BAAF): Si la ecografía muestra un nódulo sospechoso, el médico utiliza una aguja muy fina guiada por ultrasonido para extraer células y analizarlas al microscopio (es el único método para saber si es cáncer o no).", "Gammagrafía tiroidea: Se usa a veces si el análisis de TSH indica hipertiroidismo, para ver si el nódulo es 'caliente' (produce hormonas, casi siempre benigno) o 'frío' (no produce hormonas)."], note: "" }, treatment: { title: "Tratamientos", intro: "El manejo depende del tamaño, los síntomas y si hay cáncer:", subsections: [ { title: "Opciones de Manejo", items: ["Espera Vigilante (Observación): Para nódulos benignos, pequeños y sin síntomas. Consiste en realizar ecografías periódicas cada 6-12 meses para asegurar que no crezcan.", "Cirugía (Tiroidectomía parcial o total): Obligatoria si la biopsia muestra cáncer o sospecha de cáncer. También se usa para nódulos benignos muy grandes que causan asfixia o dificultad para tragar.", "Terapia con Yodo Radiactivo: Usada frecuentemente para encoger nódulos hiperactivos ('tóxicos') que causan hipertiroidismo, destruyendo el tejido glandular hiperactivo.", "Ablación por radiofrecuencia (o inyección de alcohol): Para nódulos benignos líquidos o sólidos que causan molestias y el paciente desea evitar la cirugía; se destruyen usando calor."] } ], note: "Si se extirpa toda la glándula tiroides, el paciente necesitará tomar una pastilla diaria de hormona tiroidea de reemplazo (levotiroxina) de por vida." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una revisión con tu médico o endocrinólogo si:", items: ["Detectas un bulto visible o palpable en la parte baja delantera de tu cuello", "Sientes una dificultad repentina para respirar o tragar comida sólida", "Desarrollas ronquera persistente que no se asocia a un resfriado"] } },
'GERD' : { intro: "La Enfermedad por Reflujo Gastroesofágico (GERD) es una afección digestiva crónica donde el ácido del estómago o la bilis irrita el revestimiento del esófago.", whatIs: { title: "¿Qué es?", text: "Ocurre cuando el esfínter esofágico inferior se debilita o relaja de manera anormal, permitiendo que el contenido estomacal regrese al esófago, causando acidez y posibles lesiones como el esófago de Barrett." }, symptoms: { title: "Síntomas", items: ["Acidez estomacal (pirosis)", "Regurgitación ácida o de comida", "Dolor de pecho o dificultad para tragar", "Tos crónica, laringitis o asma de nuevo inicio"] }, treatment: { title: "Manejo", items: ["Inhibidores de la bomba de protones (IBP) y antiácidos", "Evitar comidas copiosas, grasas o picantes", "No acostarse hasta 3 horas después de comer", "Cirugía (funduplicatura) en casos refractarios"] }, whenToSeekHelp: { title: "Urgencias", items: ["Dolor de pecho severo que irradia al brazo (puede confundirse con infarto)", "Vómitos con sangre o material oscuro", "Dificultad o dolor al tragar (disfagia)"] } },
'Sindactilia' : { intro: "La sindactilia es una condición congénita en la que dos o más dedos de las manos o de los pies están unidos o fusionados.", whatIs: { title: "¿Qué es?", text: "Es una de las malformaciones de las extremidades más comunes. Ocurre durante el desarrollo fetal cuando la separación normal de los dedos no se completa. La unión puede ser de piel y tejidos blandos (simple) o incluir la fusión de huesos (compleja)." }, types: { title: "Tipos", items: ["Simple (unión de tejidos blandos)", "Compleja (fusión ósea)", "Incompleta (no llega hasta la punta del dedo)", "Completa (llega hasta la punta y a veces incluye las uñas)"] }, treatment: { title: "Manejo", items: ["Cirugía de separación (generalmente realizada entre los 1 y 2 años de edad)", "Uso de injertos de piel para cubrir las áreas separadas", "Terapia física y ocupacional postoperatoria para asegurar la movilidad"] }, whenToSeekHelp: { title: "Consulta", items: ["Evaluación inicial al nacer para planificar la corrección quirúrgica oportuna y evitar que la unión interfiera con el crecimiento normal del niño"] } },
'Hipertensión renal' : { intro: "La hipertensión renal, o renovascular, es la presión arterial alta causada por el estrechamiento u obstrucción de las arterias que suministran sangre a los riñones.", whatIs: { title: "¿Qué es?", text: "Al recibir menos flujo sanguíneo debido al estrechamiento (estenosis), el riñón asume erróneamente que la presión corporal es baja o hay deshidratación. En respuesta, libera hormonas (renina) que elevan drásticamente la presión arterial en todo el cuerpo, siendo una hipertensión muy difícil de controlar." }, diagnosis: { title: "Detección", items: ["Ecografía Doppler de las arterias renales", "Angiotomografía Computarizada (Angio-TC)", "Angiografía por Resonancia Magnética (ARM)"] }, treatment: { title: "Manejo", items: ["Medicamentos antihipertensivos agresivos", "Angioplastia transluminal percutánea con colocación de stent (para abrir la arteria)", "Cirugía de derivación (bypass) en casos complejos"] }, whenToSeekHelp: { title: "Urgencias", items: ["Presión arterial que repentinamente se vuelve incontrolable o resistente a 3 o más medicamentos", "Hipertensión severa que aparece antes de los 30 o después de los 55 años", "Deterioro rápido de la función renal"] } },
'Prolactinoma' : { intro: "Un prolactinoma es un tumor benigno (adenoma) de la glándula pituitaria en el cerebro que produce una cantidad excesiva de la hormona prolactina.", whatIs: { title: "¿Qué es?", text: "Es el tipo de tumor hipofisario más común. El exceso de prolactina inhibe la producción normal de hormonas sexuales (estrógenos y testosterona), lo que provoca producción de leche en ausencia de embarazo o lactancia, alteraciones menstruales e infertilidad." }, symptoms: { title: "Síntomas", items: ["Secreción de leche por los pezones (galactorrea) en hombres o mujeres", "Periodos menstruales irregulares o ausentes (amenorrea)", "Disfunción eréctil, pérdida de vello corporal y bajo deseo sexual en hombres", "Dolores de cabeza y pérdida de visión periférica (si el tumor es grande y presiona el nervio óptico)"] }, treatment: { title: "Manejo", items: ["Medicamentos agonistas de la dopamina (Cabergolina o Bromocriptina) que reducen la prolactina y encogen el tumor de forma muy eficaz", "Cirugía transesfenoidal (extirpación a través de la nariz) si los fármacos fallan o el tumor amenaza la visión", "Radioterapia (en casos raros)"] }, whenToSeekHelp: { title: "Consulta", items: ["Secreción inusual por los pezones", "Ausencia prolongada y no explicada de la menstruación", "Pérdida de la visión lateral o dolores de cabeza constantes"] } },
'Evento vascular cerebral' : { intro: "Un evento vascular cerebral (EVC), ictus o derrame cerebral, ocurre cuando el flujo de sangre a una parte del cerebro se interrumpe de forma repentina, privando a las células de oxígeno y causando daño cerebral rápidamente.", whatIs: { title: "¿Qué es?", text: "Es una emergencia médica crítica. Puede ser isquémico (causado por un coágulo que bloquea una arteria cerebral, representando el 85% de los casos) o hemorrágico (cuando un vaso sanguíneo débil se rompe y sangra dentro del cerebro). Las neuronas afectadas comienzan a morir en minutos." }, symptoms: { title: "Signos (Escala FAST)", items: ["Asimetría facial (la mitad de la cara se cae o no puede sonreír)", "Debilidad repentina o parálisis en un brazo, una pierna o la mitad del cuerpo", "Dificultad súbita para hablar, arrastrar las palabras o incapacidad para comprender", "Pérdida brusca de la visión, equilibrio o el peor dolor de cabeza de su vida"] }, treatment: { title: "Manejo", items: ["Trombolíticos intravenosos (tPA) para disolver coágulos (solo si se administran en las primeras 4.5 horas)", "Trombectomía mecánica (extracción del coágulo con catéter)", "Cirugía para detener sangrados o aliviar presión (en EVC hemorrágico)", "Rehabilitación neurológica y física intensiva"] }, whenToSeekHelp: { title: "Urgencias", items: ["Cualquier síntoma de la escala FAST requiere llamar a emergencias (911) inmediatamente. Cada minuto de retraso equivale a millones de neuronas perdidas."] } },
'Enfermedad de Cushing' : { intro: "La enfermedad de Cushing es un trastorno hormonal raro causado por un tumor benigno en la glándula pituitaria que libera demasiada hormona adrenocorticotrópica (ACTH), lo que estimula una sobreproducción de cortisol en el cuerpo.", whatIs: { title: "¿Qué es?", text: "El cortisol es vital para responder al estrés, pero en niveles crónicamente tóxicos y elevados, altera profundamente el metabolismo. Provoca redistribución anormal de la grasa, debilidad extrema, pérdida de masa ósea y un aumento grave del riesgo cardiovascular y de infecciones." }, symptoms: { title: "Síntomas", items: ["Aumento de peso central (abdomen abultado) con brazos y piernas notablemente delgados", "Cara redonda, roja y llena (cara de luna llena)", "Acumulación de grasa en la base del cuello (giba de búfalo)", "Piel frágil que se amorata fácilmente y estrías anchas de color púrpura en el abdomen", "Debilidad muscular severa (dificultad para levantarse de una silla)"] }, treatment: { title: "Manejo", items: ["Cirugía transesfenoidal para extirpar el tumor pituitario (el tratamiento de elección curativo)", "Radioterapia pituitaria (si la cirugía no extirpa todo el tumor)", "Medicamentos inhibidores de la síntesis de cortisol (Ketoconazol, Metirapona)", "Extirpación de las glándulas suprarrenales (en casos refractarios)"] }, whenToSeekHelp: { title: "Consulta", items: ["Cambios físicos rápidos e inexplicables como obesidad central, cara redondeada y estrías moradas", "Debilidad muscular profunda", "Hipertensión y diabetes de muy difícil control de aparición reciente"] } },
'Corea de Huntington' : { intro: "La enfermedad o corea de Huntington es un trastorno genético hereditario, neurodegenerativo y progresivo que causa la degradación programada de las células nerviosas en ciertas áreas del cerebro.", whatIs: { title: "¿Qué es?", text: "Es una afección autosómica dominante (si un padre la tiene, el hijo tiene un 50% de probabilidad de heredarla). El gen mutado produce una proteína tóxica que destruye neuronas gradualmente. Suele manifestarse entre los 30 y 50 años, impactando las capacidades motoras, cognitivas y psiquiátricas del individuo hasta causar dependencia total." }, symptoms: { title: "Síntomas", items: ["Movimientos espasmódicos, de contorsión o danza involuntarios e incontrolables (corea)", "Rigidez muscular, torpeza y alteraciones graves del equilibrio y la marcha", "Deterioro cognitivo progresivo (pérdida de memoria, dificultad para planificar o enfocarse, demencia)", "Problemas psiquiátricos severos (depresión profunda, irritabilidad, cambios drásticos de personalidad, apatía)", "Dificultad progresiva para hablar y tragar"] }, treatment: { title: "Manejo", items: ["Actualmente no tiene cura ni tratamiento que frene su progresión", "Medicamentos como Tetrabenazina o Deutetrabenazina para suprimir los movimientos coreicos", "Antidepresivos y estabilizadores del estado de ánimo para los síntomas psiquiátricos", "Terapia del habla, fisioterapia y apoyo nutricional", "Atención multidisciplinaria y apoyo psicológico a la familia"] }, whenToSeekHelp: { title: "Consulta", items: ["Aparición de movimientos corporales involuntarios o torpeza inusual", "Cambios inexplicables en el comportamiento, el estado de ánimo o las capacidades mentales", "Si existen antecedentes familiares conocidos de la enfermedad, para buscar asesoramiento genético"] } },
'Anemia aplásica adquirida' : { intro: "La anemia aplásica adquirida es un trastorno raro y grave en el que la médula ósea deja de producir suficientes células sanguíneas nuevas (glóbulos rojos, blancos y plaquetas).", whatIs: { title: "¿Qué es?", text: "Es una condición donde el sistema inmunológico ataca por error a las células madre de la médula ósea. Al quedarse sin la 'fábrica' de la sangre, el paciente sufre de pancitopenia (escasez de todas las células sanguíneas), lo que deja al cuerpo sin energía, sin defensas contra infecciones y sin capacidad para coagular la sangre." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas derivan de la falta de los tres tipos de células sanguíneas:", groups: [ { name: "Signos Clínicos", items: ["Fatiga extrema, debilidad crónica y palidez (por falta de glóbulos rojos o anemia)", "Infecciones frecuentes, severas o que no curan, y fiebres inexplicables (por falta de glóbulos blancos)", "Hemorragias nasales, encías sangrantes, moretones fáciles o puntos rojos en la piel llamados petequias (por falta de plaquetas)"] } ], warning: "Una fiebre alta o un sangrado que no se detiene rápidamente es una emergencia médica absoluta en estos pacientes." }, causes: { title: "Causas y Factores de Riesgo", intro: "A menudo es idiopática (sin causa clara), pero puede ser desencadenada por:", items: ["Reacciones a ciertos medicamentos (como el cloranfenicol o sales de oro)", "Exposición repetida a químicos tóxicos, como el benceno o pesticidas", "Infecciones virales previas graves (Hepatitis, Epstein-Barr, VIH)", "Tratamientos de radioterapia o quimioterapia para el cáncer", "Enfermedades autoinmunes subyacentes"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una evaluación hematológica profunda:", items: ["Hemograma completo (muestra niveles peligrosamente bajos de los tres tipos de células sanguíneas)", "Aspirado y biopsia de médula ósea (es la prueba definitiva; muestra una médula 'vacía' o acelular, reemplazada en su mayoría por tejido graso)"] }, treatment: { title: "Tratamientos", intro: "El tratamiento es complejo y busca restaurar la médula o detener el ataque autoinmune:", subsections: [ { title: "Opciones de Manejo", items: ["Transfusiones de sangre y plaquetas (como medida de soporte vital para mantener los niveles mientras actúan otros tratamientos)", "Terapia inmunosupresora (Globulina antitimocítica y Ciclosporina) para suprimir el sistema inmunológico y permitir que la médula se recupere", "Estimulantes de la médula ósea (factores de crecimiento como eltrombopag o filgrastim) para forzar la producción de células", "Trasplante de células madre o de médula ósea (la única opción curativa definitiva, ideal en pacientes jóvenes que cuentan con un donante de familia compatible)"] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a emergencias hematológicas si presentas:", items: ["Aparición súbita de muchísimos moretones sin haberte golpeado", "Sangrado en las encías, la nariz o cortes menores que no logras detener", "Cualquier cuadro de fiebre, escalofríos o síntomas de infección aguda"] } },
'Desnutrición infantil' : { intro: "La desnutrición infantil es una condición patológica grave causada por la falta de ingesta, absorción o uso adecuado de nutrientes esenciales, que afecta devastadoramente el crecimiento, desarrollo y supervivencia durante los primeros años de vida.", whatIs: { title: "¿Qué es la Desnutrición Infantil?", text: "Es mucho más que tener bajo peso. Es una privación celular de la energía, proteínas, vitaminas y minerales necesarios para construir el cuerpo y el cerebro. Si ocurre de forma crónica durante los primeros 1,000 días de vida (desde la concepción hasta los 2 años), causa un daño cognitivo y físico profundo que a menudo es irreversible, limitando el coeficiente intelectual y la salud a futuro." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "Las manifestaciones varían según la gravedad y si faltan más calorías o más proteínas:", groups: [ { name: "Signos Clínicos Clásicos", items: ["Pérdida extrema de peso, aspecto esquelético y ausencia de grasa bajo la piel (Marasmo)", "Abdomen distendido o muy hinchado por la acumulación de líquidos, y retención de líquidos en pies y cara (Kwashiorkor)", "Retraso evidente en el crecimiento longitudinal (talla baja para su edad)", "Piel seca, escamosa, despigmentada, y cabello fino, quebradizo o que cambia a un tono rojizo/claro", "Apatía total, debilidad extrema, llanto débil, irritabilidad y falta absoluta de interés en el juego o entorno"] } ], warning: "La desnutrición severa destruye el sistema inmunológico. Los niños desnutridos rara vez mueren de hambre directa; mueren de enfermedades prevenibles como neumonía o diarrea que su cuerpo no puede combatir." }, types: { title: "Tipos de Desnutrición", intro: "Se clasifica en tres grandes grupos:", items: ["Desnutrición aguda severa (Marasmo y Kwashiorkor): Pérdida de peso reciente y extrema, es una emergencia vital.", "Desnutrición crónica (Retraso en el crecimiento o 'Stunting'): Talla baja para la edad debido a una desnutrición prolongada, refleja un daño a largo plazo.", "Hambre oculta: Deficiencia grave de micronutrientes esenciales (como vitamina A, hierro, yodo y zinc), incluso en niños que parecen tener un peso normal o sobrepeso."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra evalúa el estado nutricional y el daño a órganos mediante:", items: ["Medidas antropométricas rigurosas: Peso para la edad, talla para la edad, y peso para la talla cruzadas con las curvas de crecimiento estandarizadas de la OMS", "Medición del perímetro braquial (MUAC): Una cinta en el brazo que identifica rápidamente la desnutrición aguda severa", "Análisis de sangre y orina: Para medir los niveles de proteínas (albúmina), electrolitos, vitaminas, evaluar anemias severas y buscar infecciones ocultas"] }, treatment: { title: "Tratamientos y Rehabilitación", intro: "El tratamiento hospitalario debe ser estrictamente controlado y gradual, ya que sobrealimentar al niño de golpe puede causar un 'síndrome de realimentación' fatal:", subsections: [ { title: "Fases de Tratamiento", items: ["Fase de Estabilización inicial (Hospitalaria): Tratar o prevenir la hipoglucemia (azúcar baja), la hipotermia y la deshidratación severa sin sobrecargar el corazón. Se administran antibióticos agresivos para infecciones ocultas.", "Fórmula F-75: Una leche terapéutica baja en proteínas y sodio pero alta en carbohidratos para iniciar el metabolismo suavemente.", "Fase de Recuperación: Introducción de Alimentos Terapéuticos Listos para Usar (RUTF) o fórmula F-100 para lograr un aumento de peso rápido y reconstruir tejidos.", "Suplementación: Dosis masivas de Vitamina A, ácido fólico, hierro y zinc.", "Manejo Comunitario y Educación: Enseñar a los cuidadores sobre higiene, lactancia materna exclusiva (primeros 6 meses) y dietas locales nutritivas para prevenir recaídas."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Lleva al niño a un centro de salud inmediatamente si:", items: ["Su peso se ha estancado o está perdiendo peso visiblemente y la ropa le queda holgada", "Presenta hinchazón en los pies, manos o abdomen junto con un comportamiento extremadamente apático y triste", "Sufre de episodios de diarrea prolongada, vómitos, o no tiene fuerzas ni para llorar"] } },
'Defectos de refracción' : { intro: "Los defectos de refracción son los trastornos oculares más comunes en todo el mundo. Ocurren cuando la forma anatómica del ojo, la córnea o el cristalino impiden que los rayos de luz se enfoquen directamente y de manera perfecta sobre la retina, lo que resulta en una visión borrosa o distorsionada.", whatIs: { title: "¿Qué son los Defectos de Refracción?", text: "El ojo funciona como una cámara fotográfica: la luz entra y debe enfocarse exactamente en la 'película' trasera (la retina) para ver nítido. Cuando el globo ocular es demasiado largo, demasiado corto, o la 'lente' frontal (córnea) tiene una curvatura asimétrica, la luz se enfoca delante o detrás de la retina. Estos errores ópticos y físicos no son enfermedades oculares, sino anomalías anatómicas que se pueden corregir fácilmente con lentes." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas principales están relacionados con la borrosidad y el esfuerzo que hace el ojo para intentar enfocar:", groups: [ { name: "Síntomas Visuales y Físicos", items: ["Visión borrosa o nublada constante (ya sea al mirar de lejos, al leer de cerca, o a ambas distancias)", "Necesidad instintiva de entrecerrar los ojos para lograr ver más nítido", "Fatiga visual severa, pesadez o ardor en los ojos después de usar pantallas o leer", "Dolores de cabeza frecuentes, típicamente en la frente o alrededor de los ojos", "Visión de halos alrededor de las luces brillantes o problemas para conducir de noche"] } ], warning: "En los niños, la falta de corrección de un defecto refractivo alto, especialmente si un ojo ve mucho peor que el otro, puede causar que el cerebro ignore ese ojo, provocando ambliopía (ojo vago) irreversible." }, types: { title: "Los Cuatro Tipos Principales", intro: "Existen cuatro grandes defectos, dependiendo de la forma del ojo:", items: ["Miopía (Visión corta): El ojo es demasiado largo. La luz se enfoca DELANTE de la retina. Se ve mal de lejos, pero bien de cerca.", "Hipermetropía (Visión de lejos): El ojo es demasiado corto. La luz se enfoca DETRÁS de la retina. Se ve borroso de cerca, y a veces también de lejos si es muy alta.", "Astigmatismo: La córnea o el cristalino tienen una curvatura irregular (forma de huevo en lugar de pelota de fútbol). La luz se enfoca en múltiples puntos, causando visión distorsionada o alargada a TODAS las distancias.", "Presbicia (Vista cansada): Ocurre de forma natural a partir de los 40-45 años. El cristalino del ojo pierde su flexibilidad y no puede cambiar de forma para enfocar objetos muy cercanos (como letras pequeñas de un libro)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es indoloro y lo realiza un optometrista o un oftalmólogo:", items: ["Prueba de agudeza visual (leer una tabla de letras como la de Snellen a diferentes tamaños)", "Refracción manual o computarizada (usando un foróptero, la máquina de los cristales, para preguntar '¿mejor el 1 o el 2?' y encontrar la graduación exacta requerida)", "Topografía corneal (mapeo computarizado de la superficie del ojo, crucial para detectar astigmatismos irregulares)", "Examen con dilatación (especialmente en niños, para paralizar temporalmente los músculos del enfoque y encontrar la graduación real)"] }, treatment: { title: "Tratamientos", intro: "El objetivo es compensar la desviación de la luz para que aterrice exactamente en la retina:", subsections: [ { title: "Opciones de Corrección Óptica y Quirúrgica", items: ["Gafas (Anteojos) graduadas: El método de corrección más seguro, simple y accesible para cualquier edad y defecto.", "Lentes de contacto: Proporcionan un campo visual más amplio sin estorbos, pero requieren higiene meticulosa diaria para evitar úlceras o infecciones corneales graves.", "Cirugía Refractiva con Láser (LASIK, PRK, SMILE): Un láser excímer remodela y pule permanentemente la superficie de la córnea para corregir el defecto. Reservada para adultos mayores de 18-21 años cuya graduación ya se ha estabilizado.", "Implante de Lente Intraocular Fáquica (ICL): Se inserta quirúrgicamente una lente graduada dentro del ojo por delante del cristalino natural; se usa para miopías extremadamente altas que no se pueden operar con láser.", "Cirugía de Cristalino Transparente: Reemplazo de la lente natural del ojo por una lente artificial multifocal (a menudo se hace a la vez que se operan las cataratas) para curar la presbicia o hipermetropías extremas."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Agenda un examen de la vista si experimentas:", items: ["Dificultad para leer carteles de calles, reconocer rostros de lejos o leer la letra pequeña de tu teléfono sin alejar el brazo", "Sufres de dolores de cabeza repetitivos hacia el final del día de trabajo", "Notas que tus hijos se acercan demasiado al televisor, al cuaderno o guiñan constantemente los ojos para ver la pizarra"] } },
'Cáncer tiroideo (carcinoma medular)' : { intro: "El carcinoma medular de tiroides (CMT) es un tipo raro y agresivo de cáncer de tiroides. Se origina en unas células especiales llamadas células C (células parafoliculares), que no producen la hormona tiroidea común, sino una hormona diferente llamada calcitonina.", whatIs: { title: "¿Qué es el Carcinoma Medular de Tiroides?", text: "La mayoría de los cánceres de tiroides se forman en las células que usan yodo para crear la hormona del metabolismo. El CMT es diferente: comienza en las células que regulan el calcio. Por esta razón, este cáncer no responde a las terapias con yodo radiactivo que curan a la mayoría de los otros pacientes. Además, tiene una particularidad única: aproximadamente una cuarta parte de todos los casos de CMT son genéticos y se transmiten de padres a hijos dentro de un síndrome llamado Neoplasia Endocrina Múltiple tipo 2 (NEM 2)." }, symptoms: { title: "Síntomas y Señales Atípicas", intro: "Los síntomas locales son similares a otros tumores de cuello, pero también causa síntomas sistémicos únicos por exceso de hormonas:", groups: [ { name: "Síntomas Locales en el Cuello", items: ["Aparición de un nódulo (bulto) indoloro, duro y de crecimiento rápido en la base anterior del cuello", "Inflamación y endurecimiento de los ganglios linfáticos del cuello (adenopatías)", "Ronquera persistente o cambios bruscos en la voz si el tumor presiona los nervios de las cuerdas vocales", "Dificultad para tragar (disfagia) o sensación de asfixia, dolor o tos inexplicable"] }, { name: "Síntomas Sistémicos por Hormonas (Síndrome Paraneoplásico)", items: ["Diarrea crónica, grave e inexplicable y calambres abdominales (causados por los altos niveles de calcitonina y prostaglandinas que el tumor lanza a la sangre)", "Episodios de enrojecimiento facial intenso y repentino con sensación de calor (flushing)"] } ], warning: "Debido a su naturaleza agresiva, el CMT tiene una tendencia temprana a diseminarse (hacer metástasis) a los ganglios linfáticos y a órganos distantes como los pulmones, el hígado o los huesos, mucho antes de ser descubierto en el cuello." }, types: { title: "Clasificación Genética del CMT", intro: "Conocer el tipo es vital para toda la familia del paciente:", items: ["CMT Esporádico (75% de los casos): Ocurre por mutaciones aleatorias a lo largo de la vida en una sola persona. Típicamente afecta a adultos mayores (40-60 años) y solo hay un tumor en un lóbulo de la tiroides.", "CMT Familiar o Hereditario (25% de los casos): Causado por heredar una mutación en el protooncogén RET. Está vinculado al síndrome NEM 2A o NEM 2B (donde el paciente también desarrolla tumores graves en las glándulas suprarrenales -feocromocitoma- y paratiroides). Suele afectar a personas jóvenes o niños y formar múltiples tumores en ambos lados de la tiroides."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es altamente específico gracias a los marcadores tumorales en sangre:", items: ["Análisis de sangre para Calcitonina y Antígeno Carcinoembrionario (CEA): Si estos niveles están muy elevados, es un fuerte indicador casi definitivo de CMT.", "Ecografía de cuello de alta resolución: Para ubicar el tamaño del nódulo y examinar todos los ganglios linfáticos circundantes.", "Biopsia por Aspiración con Aguja Fina (BAAF): Se extraen células del nódulo para observarlas al microscopio.", "Estudio genético (Test del gen RET): Obligatorio e indispensable en TODO paciente diagnosticado con CMT. Si resulta positivo para la mutación, todos sus familiares de primer grado deben hacerse el test de sangre."], note: "Si un niño hereda la mutación RET de su padre enfermo, los médicos a menudo recomiendan extirpar su tiroides sana en la infancia temprana de forma preventiva, ya que el desarrollo del cáncer es casi del 100%." }, treatment: { title: "Tratamientos", intro: "Dado que no responde al yodo radiactivo ni a la quimioterapia tradicional, la cirugía experta es la piedra angular:", subsections: [ { title: "Enfoque Quirúrgico y Oncológico", items: ["Cirugía primaria agresiva (Tiroidectomía total): Extirpación completa y absoluta de toda la glándula tiroides, combinada SIEMPRE con una disección extensa (limpieza) de los ganglios linfáticos del compartimento central y lateral del cuello, para evitar que quede una sola célula tumoral.", "Descarte de Feocromocitoma: Antes de la cirugía de cuello, se DEBE examinar si hay tumores de adrenalina (feocromocitoma), ya que operarlos sin saberlo puede causar una crisis de presión arterial mortal en el quirófano.", "Reemplazo hormonal: Toma diaria de Levotiroxina de por vida para reemplazar la función de la tiroides extirpada.", "Terapia Dirigida (Inhibidores de Tirosina Quinasa): Fármacos orales muy potentes como el Vandetanib, Cabozantinib, Selpercatinib o Pralsetinib, que están diseñados específicamente para atacar la mutación genética RET en pacientes donde el cáncer ya se ha diseminado a otros órganos (metástasis) y no se puede operar.", "Radioterapia externa: Se usa ocasionalmente en el cuello para controlar tumores inoperables o reducir el dolor."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un cirujano endocrino u oncólogo inmediatamente si:", items: ["Palpas un bulto anormal, firme y fijo en la parte delantera de tu cuello", "Sufres una diarrea crónica misteriosa que los gastroenterólogos no logran curar, especialmente si tienes ganglios inflamados", "Alguien en tu familia biológica ha sido diagnosticado recientemente con Carcinoma Medular o Síndrome de Neoplasia Endocrina Múltiple"] } },
'Accidente cerebrovascular cardioembólico' : { intro: "Un accidente cerebrovascular (ACV) cardioembólico es un tipo de infarto o derrame cerebral isquémico grave. Ocurre cuando un coágulo de sangre que se ha formado en el corazón se desprende, viaja por el torrente sanguíneo (émbolo) y bloquea repentinamente una arteria vital en el cerebro, cortando el suministro de oxígeno de manera inmediata.", whatIs: { title: "¿Qué es un ACV Cardioembólico?", text: "El corazón debe bombear de manera rítmica. Cuando existen problemas cardíacos estructurales o de ritmo, la sangre puede estancarse dentro de las cámaras del corazón. Esta sangre estancada tiende a coagularse. Cuando el corazón bombea fuertemente, puede disparar un trozo de ese coágulo hacia la arteria aorta, que a menudo toma el camino directo hacia las arterias carótidas y sube al cerebro. Como el coágulo suele ser de gran tamaño y el bloqueo ocurre sin previo aviso en un tejido sano, los infartos cardioembólicos tienden a causar el daño cerebral más extenso y repentino, con altas tasas de discapacidad severa y mortalidad." }, symptoms: { title: "Síntomas Comunes (Emergencia Neurológica)", intro: "La característica principal del ACV embólico es que los síntomas alcanzan su máxima intensidad neurológica de manera brutal en segundos o minutos (sin un deterioro progresivo lento). Se utiliza la escala F.A.S.T.:", groups: [ { name: "Signos Críticos (Escala FAST)", items: ["Cara (Face): Parálisis facial o caída repentina de un lado de la cara, desviando la boca o impidiendo sonreír simétricamente.", "Brazos (Arms): Debilidad repentina, parálisis total o pérdida de sensibilidad en un brazo, una pierna o en la mitad completa del cuerpo.", "Habla (Speech): Dificultad súbita y severa para articular palabras (disartria), arrastrar las letras, decir incoherencias o incapacidad total para hablar o comprender lo que se le dice (afasia).", "Tiempo (Time): El tiempo es cerebro. Es una emergencia médica absoluta que requiere llamar a la ambulancia sin demora."] }, { name: "Otros Síntomas Súbitos", items: ["Pérdida brusca de visión en un ojo (amaurosis fugaz) o pérdida de parte del campo visual en ambos ojos", "Mareos extremadamente violentos, pérdida total de equilibrio o coordinación motora", "Dolor de cabeza repentino y sin causa conocida", "Desviación involuntaria y fija de la mirada hacia un solo lado"] } ], warning: "No importa si los síntomas desaparecen a los pocos minutos (lo cual se denomina Ataque Isquémico Transitorio o AIT). Un AIT es la alerta roja de que un ACV masivo está a punto de ocurrir y requiere atención de urgencias idéntica." }, causes: { title: "Causas y Enfermedades Cardíacas de Origen", intro: "El coágulo siempre proviene de una fuente cardíaca enferma. Los principales culpables son:", items: ["Fibrilación Auricular (FA): Es el origen de más del 50% de estos derrames. Las cámaras superiores del corazón tiemblan descontroladamente en lugar de contraerse, estancando enormes cantidades de sangre en la 'orejuela' izquierda, formando coágulos.", "Infarto de Miocardio (Ataque al corazón) Reciente: Parte del músculo cardíaco muere y no se mueve, permitiendo que la sangre se acumule y coagule sobre el tejido muerto.", "Enfermedad de las Válvulas Cardíacas: Como la estenosis mitral por fiebre reumática, o infecciones bacterianas activas en las válvulas (Endocarditis infecciosa) que desprenden material séptico.", "Válvulas cardíacas mecánicas protésicas (si el paciente no está tomando correctamente sus anticoagulantes).", "Insuficiencia cardíaca congestiva severa o miocardiopatía dilatada (corazón grande y débil que bombea muy lento).", "Foramen Oval Permeable (FOP): Un 'agujero' de nacimiento entre las aurículas que permite que coágulos de las venas de las piernas pasen al lado arterial y suban al cerebro (causa común en pacientes jóvenes sin otras enfermedades)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de emergencia busca confirmar el bloqueo, y luego encontrar de qué parte del corazón provino el coágulo:", items: ["Tomografía Computarizada (TC) de cráneo sin contraste INMEDIATA: Para descartar que no sea un sangrado (hemorragia cerebral), ya que el tratamiento de ambas cosas es opuesto y letal si se confunde.", "Angio-TC de vasos del cuello y cerebro: Para visualizar exactamente qué arteria está taponada y si se puede entrar con catéter a extraer el trombo.", "Resonancia Magnética (RM) cerebral: Revela el daño isquémico minutos después de que ocurra (mucho antes que la TC).", "Ecocardiograma (Transtorácico o Transesofágico) y Holter (Electrocardiograma de 24h-7días): Fundamental para buscar arritmias ocultas (como fibrilación auricular paroxística) o válvulas dañadas que crearon el émbolo en primer lugar."] }, treatment: { title: "Tratamientos", intro: "El tratamiento tiene dos fases: rescate cerebral de urgencia (horas) y prevención de por vida:", subsections: [ { title: "Tratamiento de Emergencia (Fase Aguda)", items: ["Trombolisis Intravenosa (Trombolíticos como Alteplasa/tPA): Un medicamento muy potente que disuelve coágulos. SOLO se puede administrar si el paciente llega al hospital y recibe el escáner dentro de las primeras 4.5 horas desde que empezaron los síntomas.", "Trombectomía Mecánica (Tratamiento Endovascular): Si la arteria taponada es grande, un neurointervencionista introduce un microcatéter por la arteria de la ingle, sube hasta el cerebro, atrapa el coágulo con una malla (stent-retriever) y lo extrae físicamente. Se puede realizar hasta 6-24 horas después del inicio en ciertos pacientes seleccionados."] }, { title: "Prevención Secundaria a Largo Plazo", items: ["Anticoagulación Oral Crónica: A diferencia de otros derrames donde se usa solo aspirina, los ACV cardioembólicos (como los de Fibrilación Auricular) requieren tratamiento con anticoagulantes fuertes de por vida (Warfarina o Anticoagulantes Orales Directos como Apixabán o Rivaroxabán) para que la sangre del corazón no se vuelva a coagular.", "Tratamiento de la causa cardíaca: Control estricto de arritmias, reemplazo de válvulas enfermas o cierre quirúrgico de un Foramen Oval Permeable (FOP).", "Rehabilitación intensiva: Terapia física, del habla y ocupacional para recuperar las funciones neurológicas perdidas."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La actuación debe ser inmediata, sin dudar ni un segundo. Llama al 911 (servicios de emergencia) si observas que a alguien, o a ti mismo, le ocurre repentinamente:", items: ["Se le cae la mitad de la cara o no puede sonreír derecho", "No puede mantener ambos brazos levantados o siente pesadez extrema en una pierna", "Arrastra las palabras, dice cosas sin sentido o no puede hablar en absoluto", "IMPORTANTE: Nunca esperar a 'ver si se le pasa'. Ve directamente a un hospital grande con unidad de ictus, cada minuto destruye 2 millones de neuronas."] } },
'Alergias en ambientes interiores' : { intro: "Las alergias en ambientes interiores (a menudo llamadas alergias perennes) son reacciones inflamatorias crónicas del sistema inmunológico provocadas por la inhalación constante de partículas o sustancias irritantes presentes en el aire cerrado del hogar, el lugar de trabajo o la escuela, manteniéndose activas durante todas las estaciones del año.", whatIs: { title: "¿Qué son las Alergias de Interior?", text: "A diferencia de las alergias al polen (fiebre del heno), que varían según la estación o si estamos al aire libre, las alergias de interior no dan tregua. Cuando una persona sensible inhala un alérgeno (como el polvo o el pelo de animal), su sistema inmunológico lo confunde con una amenaza y libera histamina. Esta sustancia química causa inflamación crónica en las vías respiratorias superiores (nariz), los ojos y los pulmones, provocando síntomas que a menudo se confunden con un resfriado interminable, afectando severamente el descanso nocturno y el rendimiento diurno." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas tienden a empeorar por la noche al dormir en la cama, al realizar tareas de limpieza (barrer o sacudir) o al estar en habitaciones poco ventiladas:", groups: [ { name: "Síntomas Respiratorios", items: ["Congestión nasal persistente (nariz tapada constantemente, respiración por la boca)", "Estornudos repetitivos (en salvas) y secreción nasal clara y acuosa", "Goteo posnasal severo (el moco cae por detrás de la nariz, causando carraspera constante y tos nocturna o matutina)", "Picazón intensa en el interior de la nariz, el paladar blando y la garganta", "Aparición o empeoramiento de los síntomas del asma bronquial (sibilancias, opresión en el pecho, falta de aire)"] }, { name: "Síntomas Oculares y Físicos", items: ["Ojos muy rojos, llorosos, hinchados y con un picor insoportable (conjuntivitis alérgica)", "Aparición de ojeras oscuras y azuladas debajo de los ojos ('ojeras alérgicas' por la congestión venosa nasal)", "Pliegue transversal sobre el puente de la nariz (por frotarse hacia arriba constantemente, el 'saludo alérgico')", "Fatiga crónica, somnolencia diurna, falta de concentración y dolores de cabeza frontales secundarios a la sinusitis alérgica"] } ], warning: "Ignorar las alergias perennes crónicas aumenta enormemente el riesgo de desarrollar asma en niños o de sufrir sinusitis bacterianas recurrentes, pólipos nasales y apneas del sueño." }, types: { title: "Principales Alérgenos de Interior", intro: "Los culpables de desencadenar estas reacciones son casi invisibles y están dentro de casa:", items: ["Ácaros del Polvo: Son la causa número uno. Son artrópodos microscópicos que se alimentan de escamas de piel humana y prosperan en ambientes cálidos y húmedos. Sus heces y restos muertos se acumulan profundamente en colchones, almohadas, sofás de tela, alfombras y peluches.", "Mascotas (Caspa de animales): La gente no es alérgica al 'pelo' del gato o del perro en sí, sino a las proteínas presentes en las escamas muertas de su piel (caspa), su saliva seca (al lamerse) y su orina, las cuales flotan en el aire y son extremadamente pegajosas a los muebles y ropa.", "Moho y Hongos: Sus esporas flotan en el aire y prosperan en zonas húmedas y poco ventiladas como sótanos, paredes de baños sin extractores, macetas regadas en exceso o detrás de fugas en tuberías.", "Cucarachas: Las heces, saliva y cuerpos en descomposición de las cucarachas se pulverizan y son un potente alérgeno en el aire, especialmente desencadenante de asma en entornos urbanos y edificios antiguos."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico alergólogo confirmará qué alérgenos están desencadenando la reacción mediante:", items: ["Revisión del historial clínico: Observando patrones (si empeora al despertar o tras limpiar).", "Pruebas Cutáneas de Alergia (Prick test): El método más rápido y estándar. Se colocan gotas de diversos extractos alergénicos (ácaros, gato, moho) en el brazo y se realizan pequeños pinchazos indoloros. Si hay alergia, aparece una roncha roja y con picor (como una picadura de mosquito) en 15 minutos.", "Análisis de sangre (IgE específica / RAST): Mide la cantidad de anticuerpos de alergia en la sangre. Se usa si la persona tiene problemas cutáneos severos o no puede suspender sus antihistamínicos para la prueba de piel.", "Radiografías o Endoscopia nasal: Para descartar que la congestión sea por un tabique desviado o pólipos nasales físicos."], note: "" }, treatment: { title: "Tratamientos", intro: "El enfoque requiere una combinación de evitar el alérgeno y usar medicación para suprimir la reacción inmunológica:", subsections: [ { title: "Control Ambiental (El paso más crítico)", items: ["Para los ácaros: Usar fundas de colchón y almohadas con cremallera a prueba de alérgenos. Lavar sábanas y mantas semanalmente en agua muy caliente (mínimo 60°C / 130°F). Eliminar alfombras o moquetas y cortinas pesadas del dormitorio.", "Para las mascotas: Mantenerlas estrictamente fuera de la habitación y de la cama. Lavar las manos tras tocarlas y usar filtros de aire HEPA potentes.", "Para el moho: Usar deshumidificadores para mantener la humedad de la casa por debajo del 50%. Reparar fugas de agua, limpiar el moho visible con lejía y ventilar los baños adecuadamente."] }, { title: "Tratamiento Médico", items: ["Corticosteroides Nasales en Aerosol (ej. Fluticasona, Mometasona, Budesonida): Son el tratamiento más potente, reduciendo drásticamente la inflamación y la congestión si se usan a diario de forma continua.", "Antihistamínicos orales (ej. Cetirizina, Fexofenadina, Loratadina): Para controlar los estornudos, picazón y secreción, sin causar somnolencia.", "Antihistamínicos y estabilizadores de mastocitos en colirios (gotas oculares) para la picazón extrema de ojos.", "Lavados o Irrigaciones nasales con solución salina: Arrastran físicamente los alérgenos y el moco denso fuera de los senos paranasales.", "Inmunoterapia (Vacunas o Gotas Sublinguales contra la alergia): Es el único tratamiento que modifica la enfermedad subyacente. Se administra el alérgeno en dosis incrementales durante varios años para que el sistema inmunológico se acostumbre (desensibilice) y deje de reaccionar, curando potencialmente la alergia a largo plazo."] } ], note: "Los aerosoles descongestionantes nasales (como la oximetazolina) no deben usarse más de 3 días, ya que causan una inflamación de rebote severa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide una derivación a alergología si:", items: ["Los medicamentos de venta libre y los antihistamínicos no alivian tu congestión o tus ojos rojos", "Tus síntomas de 'resfriado' duran varios meses y no desaparecen en todo el año", "Tú o tu hijo desarrollan silbidos en el pecho, tos nocturna que asfixia, u opresión pulmonar (señales claras de asma alérgico)", "Tu congestión nasal es tan grave que interfiere seriamente con tu calidad de sueño y te hace sentir fatigado todo el día"] } },
'Prediabetes' : { intro: "La prediabetes es una condición metabólica de alerta máxima en la cual los niveles de azúcar (glucosa) en el torrente sanguíneo son crónicamente más altos de lo normal, pero aún no han alcanzado el umbral necesario para ser diagnosticados como diabetes tipo 2. Es la antesala de una enfermedad crónica grave, pero lo más importante: es completamente reversible.", whatIs: { title: "¿Qué es la Prediabetes?", text: "Tu cuerpo descompone la comida en glucosa para obtener energía. El páncreas libera una hormona llamada insulina, que actúa como una 'llave' abriendo las células para que dejen entrar esa glucosa. En la prediabetes, las células comienzan a ignorar a la insulina (desarrollan resistencia a la insulina). Como el azúcar no puede entrar, se acumula en la sangre. El páncreas responde bombeando cada vez más insulina intentando forzar a las células a abrirse, hasta que eventualmente se agota y ya no puede mantener el ritmo. Si no se modifica el estilo de vida de inmediato, el 70% de las personas con prediabetes cruzarán la línea hacia la diabetes tipo 2, enfrentando de por vida altos riesgos de infartos, ceguera, fallos renales y amputaciones." }, symptoms: { title: "Síntomas y Señales Físicas Ocultas", intro: "El mayor peligro de la prediabetes es que es asintomática. Puedes tenerla durante años sin sentirte enfermo en absoluto. Sin embargo, hay signos físicos sutiles de la resistencia severa a la insulina que pueden observarse:", groups: [ { name: "Señales Dermatológicas y Metabólicas", items: ["Acantosis nigricans: Aparición de zonas de piel engrosada, aterciopelada y de color notablemente oscuro (marrón a negro), comúnmente en la parte posterior o lateral del cuello, en las axilas, o en los pliegues de los codos y rodillas (este es el signo clínico más clásico y visible de exceso de insulina en la sangre).", "Múltiples acrocordones: Pequeños bultos de piel colgante (verrugas de cuello) que aparecen repentinamente y en gran cantidad en el cuello o pecho.", "Cansancio y somnolencia abrumadora poco tiempo después de comer comidas altas en carbohidratos.", "Aumento notable y constante de grasa alrededor de la zona abdominal (grasa visceral central, en forma de manzana)."] } ], warning: "Si comienzas a sentir mucha más sed de lo normal (polidipsia), una necesidad muy frecuente de orinar (poliuria), fatiga extrema constante o visión borrosa ocasional, significa que es muy probable que tu prediabetes ya haya evolucionado a diabetes tipo 2 y el azúcar en sangre esté causando estragos tóxicos." }, types: { title: "Relación con el Síndrome Metabólico", intro: "La prediabetes rara vez viene sola; frecuentemente es el componente central de un grupo de factores destructivos conocido como 'Síndrome Metabólico', que multiplica el riesgo cardíaco e incluye:", items: ["Presión arterial elevada constante (Hipertensión)", "Niveles altos de Triglicéridos en sangre", "Niveles muy bajos de colesterol HDL (el colesterol 'bueno' que protege al corazón)", "Gordura concentrada alrededor de la cintura (un perímetro de cintura superior a 102 cm en hombres y 88 cm en mujeres)"], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Es el resultado directo de una interacción genética y hábitos modernos modernos, siendo el riesgo elevadísimo si:", items: ["Tienes sobrepeso u obesidad (el exceso de grasa visceral o intraabdominal hace que tus células sean directamente resistentes a la insulina).", "Tu dieta es alta en alimentos ultraprocesados, harinas refinadas y carbohidratos vacíos, y especialmente azúcares líquidos (refrescos, zumos endulzados).", "Llevas una vida sedentaria (no hacer ejercicio regularmente).", "Tienes familiares de primer grado (padres, hermanos) con diabetes tipo 2.", "Eres mujer y tuviste diabetes gestacional durante un embarazo, o diste a luz a un bebé de más de 4 kilos.", "Padeces el Síndrome de Ovario Poliquístico (SOP) o apnea obstructiva del sueño.", "La edad supera los 45 años, aunque cada vez es más común en adultos jóvenes y adolescentes."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para saber en qué punto estás, el médico solicitará pruebas de sangre precisas:", items: ["Prueba de Hemoglobina Glicosilada (HbA1c): Es la prueba más fiable porque muestra el promedio del azúcar en sangre de los últimos tres meses. (Normal: debajo de 5.7%. Prediabetes: entre 5.7% y 6.4%. Diabetes: 6.5% o superior).", "Examen de glucosa en sangre en ayunas: Te sacan sangre tras 8 horas sin comer. (Normal: debajo de 100 mg/dL. Prediabetes: de 100 a 125 mg/dL. Diabetes: 126 mg/dL o superior).", "Prueba oral de tolerancia a la glucosa: Mide el nivel de azúcar tras tomar una bebida intensamente dulce en el laboratorio. (Prediabetes: de 140 a 199 mg/dL a las dos horas)."], note: "Es vital hacerse revisiones anuales si tienes sobrepeso, porque una HbA1c de 6.4% está al borde de un daño orgánico permanente." }, treatment: { title: "Tratamientos y Reversión Activa", intro: "¡La prediabetes es curable y reversible! El tratamiento no se basa en pastillas, sino en la toma de control de tu estilo de vida para reactivar la sensibilidad celular:", subsections: [ { title: "Plan de Acción Antimicrobiano y Metabólico", items: ["Pérdida de Peso Estratégica: Este es el paso más importante. Perder apenas entre el 5% y el 7% de tu peso corporal total (por ejemplo, 5 kilos en una persona de 90 kilos) es suficiente para eliminar gran parte de la resistencia a la insulina y bajar el azúcar drásticamente a niveles normales.", "Alimentación de Bajo Índice Glucémico: Abandonar por completo los refrescos azucarados, los dulces, el pan blanco y los carbohidratos refinados. Basar la dieta en verduras, fibras crudas, granos enteros, legumbres y proteínas magras, que evitan que el azúcar en sangre tenga 'picos' violentos.", "Ejercicio Aeróbico y de Fuerza: El ejercicio es el tratamiento más potente que existe. La contracción del músculo consume glucosa inmediatamente, incluso sin ayuda de la insulina. Se exigen mínimo 150 minutos de ejercicio moderado a vigoroso a la semana (caminatas rápidas, bicicleta, natación) y añadir ejercicios de fuerza o pesas, ya que a más músculo tengas, más azúcar quemará tu cuerpo en reposo.", "Medicamentos de Apoyo: En casos de obesidad severa persistente, edad joven en el diagnóstico, mujeres con antecedentes de diabetes gestacional o SOP crónico, el médico prescribirá Metformina, un fármaco muy seguro que detiene la producción de azúcar por parte del hígado y mejora la respuesta celular a la insulina.", "Cirugía Bariátrica: Extremadamente eficaz para curar el metabolismo diabético en pacientes con obesidad mórbida que no logran perder peso y tienen alto riesgo cardiovascular."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No esperes a sentirte mal. Exige un análisis preventivo de HbA1c a tu médico si:", items: ["Tienes sobrepeso y más de 35 años de edad", "Notas oscurecimiento y engrosamiento extraño en la piel del cuello, las axilas o los pliegues de la piel (acantosis nigricans)", "Tienes fuertes antecedentes familiares de diabetes o sobrepeso, independientemente de tu edad actual", "Al menos, todo adulto mayor de 45 años debería chequearse su azúcar en sangre cada tres años de forma obligatoria"] } },
'Hemangioma' : { intro: "Un hemangioma (a menudo referido como hemangioma infantil) es el tumor benigno (no canceroso) más común que se presenta en los bebés. Se forma por un agrupamiento o maraña inusualmente densa de diminutos vasos sanguíneos (capilares) y células de las venas que crecen a un ritmo acelerado poco después del nacimiento. Pueden aparecer en la piel o dentro de órganos internos.", whatIs: { title: "¿Qué es un Hemangioma?", text: "Aparecen comúnmente en las primeras semanas de vida del bebé. En la piel, un hemangioma superficial se ve como una marca abultada, carnosa y de color rojo brillante intenso, por lo que a menudo se le llama 'marca de fresa'. Lo más característico de estos tumores es su ciclo vital predecible e inusual: crecen rápida y sorprendentemente durante el primer año de vida, luego entran en una fase de reposo y, a partir del primer o segundo año, comienzan a involucionar (encogerse, palidecerse y marchitarse lentamente) por sí mismos hasta desaparecer casi por completo durante la niñez." }, symptoms: { title: "Síntomas y Aspecto Clínico", intro: "El aspecto varía dependiendo de la profundidad en el tejido y el órgano afectado:", groups: [ { name: "Hemangiomas Superficiales de la Piel (Los más comunes)", items: ["Comienzan como una simple marca roja o plana que asoma a las semanas de nacer, o una zona pálida o azulada en la piel", "Rápidamente se elevan, convirtiéndose en un bulto rojo, de textura gomosa o abombada", "Ocurren más frecuentemente en la cabeza, la cara (especialmente frente, mejillas o párpados), el cuello y el pecho"] }, { name: "Hemangiomas Profundos de la Piel", items: ["Aparecen como una masa hinchada o un bulto debajo de la superficie de la piel", "El color de la piel sobre el bulto suele verse azulado o de tono púrpura apagado debido a la profundidad de los vasos sanguíneos anormales"] }, { name: "Hemangiomas en Órganos Internos (Hepáticos/Hígado)", items: ["La mayoría crecen en el interior del hígado y nunca causan problemas ni son detectados (un hallazgo casual de adulto).", "Si crecen excesivamente en bebés, pueden presionar órganos y causar: masa abdominal palpable, vómitos, falta de apetito o en casos extremos fallo cardíaco por el gran flujo de sangre desviado al tumor."] } ], warning: "Aunque la inmensa mayoría son benignos estéticamente, un hemangioma que crece velozmente alrededor del ojo del bebé puede bloquear su visión permanentemente (causando ojo vago), y los que crecen en la nariz o garganta pueden bloquear físicamente la vía respiratoria y ser asfixiantes. Estas son emergencias pediátricas." }, types: { title: "Ciclo de Involución y Complicaciones", intro: "Casi todos los hemangiomas desaparecerán sin cirugía, pero el proceso puede durar años:", items: ["Involución natural: El 50% de los hemangiomas han desaparecido a los 5 años, y casi el 90% a los 10 años de edad. Al final del proceso, la piel puede quedar con un ligero tono más pálido, más fina, o con un tejido residual fibro-graso.", "Ulceración (la complicación más frecuente): Alrededor del 15% de los hemangiomas se abren, se rompen y forman una llaga muy dolorosa y propensa al sangrado y a infecciones (especialmente si están ubicados en el área del pañal o los labios), dejando una cicatriz permanente."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Se desconoce el detonante exacto de por qué los vasos sanguíneos deciden crecer juntos y amontonarse, pero existen claros perfiles de riesgo:", items: ["Prematuridad: Es mucho más común en bebés nacidos antes de término.", "Bajo peso al nacer (una causa fuertemente vinculada).", "Sexo: Las niñas tienen hasta tres veces más probabilidades de desarrollarlos que los niños.", "Raza blanca o de piel clara caucásica.", "Embarazos múltiples (mellizos, trillizos).", "Insuficiencia de oxígeno en la placenta: Algunos estudios sugieren que células trofoblásticas (de la placenta) viajan y se implantan en la piel debido a escasez de oxígeno durante el desarrollo en el útero."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de un hemangioma no suele requerir pruebas invasivas:", items: ["Examen Físico Clínico: El pediatra o el dermatólogo pediátrico puede diagnosticar un hemangioma superficial simplemente con una inspección visual directa, reconociendo el característico tono rojo brillante.", "Ecografía o Ultrasonido cutáneo: Se utiliza para medir exactamente qué tan profundo bajo la piel crece un hemangioma abultado o medir el tamaño de un hemangioma interno en órganos.", "Resonancia Magnética (RM): Es indispensable si el hemangioma está ubicado cerca del ojo, de las vías respiratorias, en la zona inferior de la columna vertebral (espalda baja), o si son múltiples hemangiomas extensos (para descartar síndromes sistémicos raros asociados, como el Síndrome PHACE)."], note: "Tener múltiples hemangiomas en la piel aumenta significativamente la probabilidad de tener también hemangiomas ocultos en el hígado u otros órganos internos." }, treatment: { title: "Tratamientos", intro: "Para la gran mayoría de hemangiomas pequeños e inofensivos, el mejor tratamiento es la 'negligencia benigna' o esperar y observar. El tratamiento activo se usa solo para hemangiomas que causan daño o desfiguración severa:", subsections: [ { title: "Opciones de Terapia Activa", items: ["Betabloqueadores orales (Propranolol): Es el estándar de oro médico y el descubrimiento más importante en su tratamiento. Administrado en jarabe o solución oral bajo control del pediatra, frena el crecimiento del tumor y fuerza su encogimiento rápido bloqueando los vasos sanguíneos; es altamente efectivo y seguro, salvando la vista u órganos vitales en hemangiomas masivos.", "Betabloqueadores tópicos (Timolol en gotas o gel): Aplicados directamente sobre hemangiomas pequeños y superficiales en la piel para frenar su crecimiento, sin efectos secundarios en el cuerpo entero del bebé.", "Corticosteroides (Inyectados o Tópicos): Alternativa más antigua para frenar el crecimiento si el bebé no tolera el Propranolol, o inyectado directamente para reducir rápidamente la inflamación en zonas localizadas.", "Cirugía Láser: El láser de colorante pulsado se usa con alta eficacia para cauterizar (quemar de forma superficial) la herida si un hemangioma se úlcera, detener hemorragias o eliminar de forma cosmética los rastros de venitas rojas residuales que quedan en la piel tras la involución años después.", "Cirugía Plástica Excisional (Bisturí): Hoy en día es poco frecuente, reservada para hemangiomas que han dejado piel flácida o cicatrices colgantes irreparables tras su encogimiento completo, o raramente, en tumores inmensos del hígado de adultos si amenazan con reventarse."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental que el pediatra monitorice cualquier hemangioma desde su aparición inicial. Busca atención de emergencia médica o de cirugía pediátrica si notas que la marca del bebé:", items: ["Comienza a crecer rápidamente y a interferir físicamente de alguna manera con la apertura del ojo, la fosa nasal o los bordes de los labios", "Se presenta una ampolla, se pela, forma una llaga abierta (úlcera) que parece dolerle al bebé o supura cualquier líquido inusual", "Comienza a sangrar y la hemorragia no se detiene fácilmente con una simple presión constante de unos minutos con un paño limpio"] } },
'Neuropatias Compresivas' : { intro: "Las neuropatías compresivas son un grupo de afecciones dolorosas y debilitantes que ocurren cuando un nervio periférico es sometido a presión constante o 'atrapado' al pasar por canales estrechos de hueso, ligamentos o músculos en el cuerpo.", whatIs: { title: "¿Qué son las Neuropatías Compresivas?", text: "Nuestros nervios actúan como cables eléctricos que envían señales entre el cerebro y el resto del cuerpo. Cuando los tejidos circundantes se inflaman, se engrosan o se desplazan, pueden aplastar estos 'cables'. Esta compresión física daña la capa protectora del nervio (mielina) y, con el tiempo, el propio nervio, interrumpiendo las señales y provocando dolor, entumecimiento y debilidad en la zona afectada." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen desarrollarse gradualmente y empeorar con ciertas posturas:", groups: [ { name: "Síntomas Sensoriales", items: ["Entumecimiento, hormigueo o sensación de 'alfileres y agujas' (parestesia) en el área inervada por el nervio", "Dolor ardiente, punzante o eléctrico que puede irradiarse hacia otras zonas", "Sensibilidad extrema al tacto en la zona afectada"] }, { name: "Síntomas Motores (Etapas Avanzadas)", items: ["Debilidad muscular notable en la extremidad", "Torpeza al agarrar objetos (se caen las cosas de las manos)", "Atrofia (pérdida visible de masa muscular) si la compresión es crónica y severa"] } ], warning: "La debilidad muscular progresiva o la pérdida de sensibilidad permanente son signos de que el nervio está sufriendo un daño severo y posiblemente irreversible; requiere atención quirúrgica rápida." }, types: { title: "Tipos Más Comunes", intro: "Se nombran según el nervio y el lugar donde queda atrapado:", items: ["Síndrome del Túnel Carpiano: Compresión del nervio mediano en la muñeca (el más frecuente).", "Síndrome del Túnel Cubital: Atrapamiento del nervio cubital en el codo (causa hormigueo en el dedo meñique).", "Ciática o Radiculopatía: Compresión de las raíces nerviosas en la columna vertebral (por una hernia discal).", "Meralgia Parestésica: Atrapamiento del nervio cutáneo femoral lateral en la ingle (causa ardor en la parte externa del muslo).", "Síndrome del Túnel Tarsiano: Compresión del nervio tibial en el tobillo."] }, causes: { title: "Causas y Factores de Riesgo", intro: "La compresión suele ser el resultado de inflamación o estrés repetitivo:", items: ["Movimientos repetitivos diarios (escribir en teclado, uso de herramientas vibratorias, deportes repetitivos)", "Mantener posturas forzadas durante mucho tiempo (como dormir con los codos muy doblados)", "Traumatismos, fracturas o esguinces que causan hinchazón en la zona", "Condiciones médicas subyacentes que provocan retención de líquidos o inflamación (embarazo, artritis reumatoide, hipotiroidismo)", "Diabetes (hace que los nervios sean mucho más vulnerables al daño por compresión)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El neurólogo o traumatólogo determinará la ubicación exacta del bloqueo:", items: ["Examen físico neurológico (pruebas de provocación, como golpear suavemente el nervio -Signo de Tinel- o flexionar la articulación -Prueba de Phalen- para reproducir los síntomas)", "Electromiografía (EMG) y Estudios de Conducción Nerviosa (el estándar de oro: miden la velocidad de las señales eléctricas para ver exactamente dónde está bloqueado el nervio y qué tan dañado está)", "Ecografía neuromuscular de alta resolución (permite ver si el nervio está físicamente hinchado o aplastado)", "Resonancia Magnética (RM) (útil si se sospecha que un tumor, quiste o hernia está causando la compresión)"] }, treatment: { title: "Tratamientos", intro: "El objetivo es aliviar la presión sobre el nervio para permitir que sane por sí solo:", subsections: [ { title: "Opciones Conservadoras y Quirúrgicas", items: ["Inmovilización: Uso de férulas o muñequeras/coderas (especialmente por la noche) para mantener la articulación en una posición neutra y evitar pellizcar el nervio mientras se duerme.", "Modificación ergonómica: Cambiar la postura en el trabajo, usar teclados ergonómicos y tomar descansos frecuentes.", "Fisioterapia: Ejercicios de 'deslizamiento nervioso' y estiramientos para mejorar la movilidad del nervio a través de su canal.", "Medicamentos y Terapias: Antiinflamatorios no esteroideos (AINEs), neuromoduladores (gabapentina) o inyecciones locales de corticosteroides (para reducir la inflamación severa alrededor del nervio de forma rápida).", "Cirugía de Descompresión: Si el tratamiento conservador falla tras varios meses o hay atrofia muscular, el cirujano realiza una pequeña incisión para cortar el ligamento o tejido que está aplastando el nervio (ej. liberación del túnel carpiano), curando el problema de forma definitiva."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a evaluación médica especializada si:", items: ["El hormigueo o dolor te despierta frecuentemente durante la noche", "Notas que estás perdiendo fuerza en la mano, el brazo o la pierna, o se te caen los objetos accidentalmente", "Los síntomas no mejoran tras un par de semanas de evitar la actividad que sospechas que los causó"] } },
'Adenocarcinoma del útero' : { intro: "El adenocarcinoma del útero, específicamente el adenocarcinoma de endometrio, es el tipo más común de cáncer uterino. Se origina en el revestimiento interno del útero (el endometrio) y, gracias a que suele causar sangrado vaginal anormal desde sus primeras etapas, tiene una alta tasa de detección precoz y curación.", whatIs: { title: "¿Qué es el Adenocarcinoma Endometrial?", text: "Es un crecimiento maligno (canceroso) de las células glandulares que forman el endometrio. Normalmente, este revestimiento crece y se desprende cada mes durante la menstruación bajo el control de las hormonas (estrógenos y progesterona). Si hay un desequilibrio con exceso de estrógenos, las células pueden multiplicarse descontroladamente, llevando primero a una hiperplasia (engrosamiento) y luego a un adenocarcinoma." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "El signo cardinal del cáncer de endometrio es un cambio drástico en el patrón de sangrado:", groups: [ { name: "Síntomas Principales", items: ["Sangrado vaginal, manchado o secreción sanguinolenta después de la menopausia (incluso una sola gota es una señal de alerta máxima)", "Sangrado menstrual anormalmente abundante, prolongado o sangrado entre períodos en mujeres premenopáusicas", "Secreción vaginal acuosa, rosada o con mal olor", "Dolor sordo y persistente en la zona pélvica o en la parte baja de la espalda (generalmente en etapas más avanzadas)", "Pérdida de peso inexplicable y dolor durante las relaciones sexuales"] } ], warning: "Cualquier episodio de sangrado vaginal que ocurra después de que una mujer haya pasado por la menopausia debe ser investigado por un ginecólogo de inmediato. El 90% de los cánceres de endometrio presentan este síntoma." }, types: { title: "Tipos de Cáncer de Endometrio", intro: "Se clasifican según su aspecto microscópico y agresividad:", items: ["Tipo I (Adenocarcinoma endometrioide): Es el más frecuente (80%). Crece lentamente, está directamente relacionado con el exceso de estrógenos, y generalmente se detecta en etapas tempranas con un pronóstico excelente.", "Tipo II (Seroso, Células Claras, Carcinosarcoma): Son menos comunes pero mucho más agresivos. No están fuertemente ligados a las hormonas, tienden a propagarse más rápido fuera del útero y tienen un peor pronóstico."], note: "Los sarcomas uterinos son diferentes; se forman en la pared muscular del útero (miometrio), no en el revestimiento interno." }, causes: { title: "Factores de Riesgo", intro: "El riesgo aumenta significativamente por la exposición prolongada a estrógenos sin el equilibrio de la progesterona:", items: ["Obesidad: El tejido graso convierte algunas hormonas en estrógenos adicionales (es el factor de riesgo más importante y modificable).", "Terapia de Reemplazo Hormonal (TRH) con estrógenos solos (sin progestina) después de la menopausia.", "Afecciones hormonales crónicas: Síndrome de Ovario Poliquístico (SOP) o falta de ovulación crónica.", "Años reproductivos prolongados: Menstruación temprana (antes de los 12 años) o menopausia tardía.", "Nuliparidad: No haber estado nunca embarazada.", "Toma de Tamoxifeno (un medicamento para prevenir el cáncer de mama que actúa como estrógeno débil en el útero).", "Síndrome de Lynch (mutación genética hereditaria que aumenta drásticamente el riesgo de cáncer de colon y endometrio)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para diagnosticar el cáncer se debe obtener tejido del interior del útero:", items: ["Ecografía Transvaginal: Es el primer paso; el médico mide el grosor del endometrio. Si es demasiado grueso para la edad reproductiva de la paciente, se requieren más pruebas.", "Biopsia Endometrial: El procedimiento estándar de oro. Se inserta un tubo delgado en el útero en el consultorio para extraer una muestra de tejido y analizarla buscando células cancerosas.", "Histeroscopia con Legrado: Si la biopsia en el consultorio no es concluyente, se inserta una cámara en el útero bajo anestesia para ver el interior directamente y raspar tejido sospechoso.", "Pruebas de Imagen (TC, RM o PET): Una vez confirmado el cáncer, se realizan para estadificarlo (ver si se ha diseminado a los ganglios linfáticos, vejiga u otros órganos)."] }, treatment: { title: "Tratamientos", intro: "El tratamiento primario es casi siempre quirúrgico, y es curativo si el tumor está confinado al útero:", subsections: [ { title: "Enfoque Oncológico", items: ["Cirugía (Histerectomía total con salpingooforectomía bilateral): Extirpación completa del útero, el cuello uterino, las trompas de Falopio y ambos ovarios. A menudo, también se extirpan y analizan los ganglios linfáticos cercanos (ganglio centinela) para asegurar que el cáncer no se ha propagado.", "Radioterapia: Frecuentemente utilizada después de la cirugía (braquiterapia vaginal o radiación externa pélvica) para destruir cualquier célula microscópica restante y reducir el riesgo de recaída.", "Quimioterapia: Reservada para cánceres de Tipo II más agresivos, etapas avanzadas donde el cáncer se ha diseminado fuera del útero, o si el cáncer regresa.", "Terapia Hormonal (Progestinas) o Inmunoterapia: Utilizadas en algunos casos avanzados o en mujeres jóvenes en estadios muy tempranos que desean intentar preservar su fertilidad temporalmente."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una cita ginecológica de urgencia si experimentas:", items: ["Absolutamente cualquier tipo de sangrado, manchado o secreción inusual si ya has pasado la menopausia (incluso si es solo una vez)", "Sangrado muy abundante o prolongado que no es normal en tus ciclos habituales", "Diagnóstico previo de hiperplasia endometrial atípica"] } },
'Bebé de madre diabética' : { intro: "Un 'bebé de madre diabética' (BMD) se refiere a un recién nacido cuya madre padeció de diabetes gestacional (desarrollada durante el embarazo) o diabetes preexistente (tipo 1 o 2) mal controlada. Estos bebés enfrentan un conjunto único de riesgos metabólicos y de desarrollo en sus primeros días de vida debido al ambiente alterado en el útero.", whatIs: { title: "¿Qué sucede durante la Gestación?", text: "Durante el embarazo, la glucosa (azúcar) en la sangre de la madre atraviesa libremente la placenta y llega al bebé, pero la insulina materna no lo hace. Si la madre tiene niveles altos de azúcar, el bebé también los tendrá. En respuesta, el páncreas del feto produce cantidades masivas de su propia insulina para manejar ese exceso de azúcar. Como la insulina actúa como una poderosa hormona de crecimiento en el feto, esto provoca que el bebé crezca anormalmente grande y gordo (macrosomía). Al nacer, el cordón umbilical se corta y el suministro de azúcar gigante se detiene de golpe, pero el páncreas del bebé sigue produciendo demasiada insulina, lo que hace que su nivel de azúcar en la sangre se desplome peligrosamente a los pocos minutos o horas del parto." }, symptoms: { title: "Signos Clínicos en el Recién Nacido", intro: "Los neonatólogos vigilan muy de cerca a estos bebés buscando:", groups: [ { name: "Signos Físicos y Metabólicos", items: ["Macrosomía fetal: El bebé nace muy grande y pesado (a menudo más de 4 kg o 9 libras), con cara regordeta y mucho tejido graso en los hombros y el cuerpo.", "Hipoglucemia severa (bajo nivel de azúcar en la sangre): Puede causar que el bebé se vea pálido, letárgico, presente temblores (jitteriness), sudoración o dificultad para alimentarse.", "Síndrome de Dificultad Respiratoria: A pesar de ser grandes, la maduración de los pulmones a menudo se retrasa en los BMD, lo que causa respiración rápida, quejidos o aleteo nasal al nacer.", "Hipocalcemia o Hipomagnesemia (bajos niveles de calcio/magnesio): Puede causar espasmos o irritabilidad extrema.", "Policitemia e Ictericia: Producción excesiva de glóbulos rojos (haciendo que el bebé se vea muy rojo o rubicundo), que al descomponerse causan ictericia (piel amarilla)."] } ], warning: "La hipoglucemia no tratada rápidamente en el recién nacido puede causar daño cerebral permanente o convulsiones." }, causes: { title: "Riesgos Adicionales por Diabetes Materna", intro: "El impacto en el feto depende de cuándo ocurrió el mal control del azúcar:", items: ["Diabetes preexistente en el primer trimestre: Aumenta significativamente el riesgo de malformaciones congénitas graves (defectos del corazón, del tubo neural o del síndrome de regresión caudal).", "Diabetes gestacional en el segundo/tercer trimestre: Principalmente causa macrosomía, problemas de parto (distocia de hombros, donde el bebé se atasca en el canal de parto) y los desequilibrios metabólicos neonatales."] }, diagnosis: { title: "¿Cómo se Evalúa al Recién Nacido?", intro: "El diagnóstico de las complicaciones se realiza inmediatamente tras el parto:", items: ["Monitorización estricta de la glucosa en sangre capilar (pinchazos en el talón) comenzando en la primera hora de vida y repetido antes de cada toma durante las primeras 24 horas", "Análisis de sangre para medir niveles de calcio, magnesio, bilirrubina y hematocrito (para detectar policitemia)", "Ecocardiograma o radiografía de tórax (si el bebé presenta soplos cardíacos o dificultad para respirar)"] }, treatment: { title: "Tratamientos y Manejo en la UCIN", intro: "El objetivo es estabilizar los niveles metabólicos del bebé mientras su cuerpo se adapta a la vida fuera del útero:", subsections: [ { title: "Intervenciones Médicas", items: ["Alimentación temprana y frecuente: Es la primera línea de defensa contra la hipoglucemia. Se fomenta la lactancia materna inmediata o la suplementación con fórmula/gel de dextrosa.", "Glucosa Intravenosa (IV): Si el nivel de azúcar en sangre del bebé sigue siendo peligrosamente bajo a pesar de las alimentaciones, se debe administrar suero con glucosa por vía intravenosa en la unidad de neonatología.", "Soporte respiratorio: Uso de oxígeno suplementario o ventilación no invasiva (CPAP) si los pulmones están inmaduros.", "Fototerapia (luces azules especiales): Para tratar la ictericia y ayudar a eliminar el exceso de bilirrubina.", "Suplementos intravenosos de calcio o magnesio (si los análisis de sangre lo requieren)."] } ], note: "Una vez que los niveles de insulina del bebé se normalizan (usualmente en 2 a 4 días), la mayoría de estos problemas se resuelven por completo sin secuelas a largo plazo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La atención recae en el control prenatal de la madre:", items: ["Si estás embarazada, es vital asistir a todas las pruebas de tolerancia a la glucosa y seguir estrictamente las dietas o la insulina recetada por tu endocrinólogo", "Si notas que el bebé recién nacido en casa se muestra inusualmente adormilado, no se despierta para comer o presenta temblores repetitivos en las extremidades, acude a urgencias pediátricas inmediatamente"] } },
'Anemia hemolítica' : { intro: "La anemia hemolítica es un trastorno de la sangre en el cual los glóbulos rojos se destruyen de forma prematura y más rápido de lo que la médula ósea puede producir glóbulos rojos nuevos para reemplazarlos.", whatIs: { title: "¿Qué es la Anemia Hemolítica?", text: "Los glóbulos rojos (eritrocitos) transportan oxígeno por todo el cuerpo y normalmente viven alrededor de 120 días. En la anemia hemolítica, estas células se rompen o se destruyen en cuestión de días (hemólisis). Como resultado, el cuerpo no tiene suficientes células sanas para oxigenar los tejidos (anemia), y la ruptura masiva de glóbulos rojos libera grandes cantidades de bilirrubina en la sangre, lo que satura al hígado y provoca ictericia." }, symptoms: { title: "Síntomas y Signos Clínicos", intro: "Los pacientes presentan síntomas típicos de anemia, combinados con los de la descomposición de la sangre:", groups: [ { name: "Síntomas de Anemia", items: ["Fatiga extrema, debilidad y falta de energía constante", "Palidez marcada en la piel, encías y el interior de los párpados", "Dificultad para respirar (disnea) al hacer esfuerzos leves", "Palpitaciones, latidos cardíacos rápidos o irregulares (taquicardia) y mareos"] }, { name: "Signos Específicos de Hemólisis", items: ["Ictericia (coloración amarillenta notable en la piel y en la parte blanca de los ojos)", "Orina de color muy oscuro (color té, coñac o rojo pardo) debido a los subproductos de la sangre destruida filtrados por los riñones", "Esplenomegalia (agrandamiento del bazo), que puede causar una sensación de llenura o dolor sordo en el lado superior izquierdo del abdomen", "Cálculos biliares frecuentes (formados por el exceso de bilirrubina)"] } ], warning: "Una crisis hemolítica aguda (destrucción masiva repentina) puede causar fiebre, escalofríos, dolor de espalda intenso, caída rápida de la presión arterial y fallo renal agudo." }, types: { title: "Causas y Clasificación", intro: "Las causas se dividen en dos grandes grupos principales:", items: ["Anemia Hemolítica Intrínseca (Hereditaria): Los glóbulos rojos nacen defectuosos. Incluye enfermedades genéticas como la anemia falciforme (células en forma de hoz), la esferocitosis hereditaria (células esféricas frágiles), o deficiencias de enzimas como la G6PD.", "Anemia Hemolítica Extrínseca (Adquirida): Los glóbulos rojos son sanos, pero el cuerpo los destruye. Incluye causas autoinmunes (el sistema inmunológico produce anticuerpos que atacan a los glóbulos rojos), infecciones graves (malaria, sepsis), válvulas cardíacas mecánicas que aplastan las células, toxinas, o reacciones a medicamentos (como la penicilina)."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se requieren análisis de sangre específicos para confirmar la destrucción celular:", items: ["Hemograma completo (CBC): Mostrará un nivel bajo de hemoglobina y glóbulos rojos.", "Recuento de reticulocitos: Suele estar muy alto, ya que la médula ósea produce glóbulos rojos inmaduros rápidamente intentando compensar la pérdida.", "Prueba de bilirrubina (indirecta elevada) y niveles de LDH (enzima elevada durante la destrucción celular).", "Nivel de Haptoglobina: Estará anormalmente bajo (esta proteína se une a la hemoglobina libre destruida y desaparece de la sangre).", "Prueba de Coombs (Directa o Indirecta): Fundamental para confirmar si la causa es autoinmune (presencia de anticuerpos atacando las células).", "Frotis de sangre periférica: Observar las células bajo un microscopio para buscar formas anormales (esferocitos, esquistocitos)."] }, treatment: { title: "Tratamientos", intro: "El tratamiento depende estrictamente de la causa subyacente y de la gravedad de la anemia:", subsections: [ { title: "Opciones Médicas y Quirúrgicas", items: ["Anemia Autoinmune: Corticosteroides (Prednisona) en dosis altas para frenar el sistema inmunológico; si fallan, se usan medicamentos inmunosupresores más fuertes (Rituximab, Ciclofosfamida).", "Transfusiones de sangre: Intervención de emergencia rápida en casos de anemia grave para reponer los glóbulos rojos y evitar el fallo cardíaco.", "Suplementos de Ácido Fólico: Necesarios para ayudar a la médula ósea a seguir produciendo nuevas células sanguíneas rápidamente.", "Esplenectomía (Extirpación del bazo): En casos hereditarios (como la esferocitosis) o autoinmunes crónicos donde el bazo es el órgano principal que destruye erróneamente los glóbulos rojos, extirparlo resuelve o mejora enormemente la enfermedad.", "Suspensión de medicamentos: Si un fármaco es el causante de la reacción hemolítica, retirarlo es el paso principal."] } ] }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes acudir a la sala de emergencias inmediatamente si presentas:", items: ["Orina repentinamente muy oscura, como té negro o rojiza", "Aparición brusca de piel u ojos de color amarillo intenso (ictericia)", "Dificultad severa para respirar en reposo, dolor en el pecho o sensación de desmayo inminente"] } },
'Cistitis en niños' : { intro: "La cistitis en niños es una infección aguda de las vías urinarias bajas (IVU), específicamente la inflamación de la vejiga. Es una enfermedad pediátrica común, especialmente en las niñas y en los bebés que usan pañal, y requiere un diagnóstico oportuno para evitar que la infección ascienda a los riñones.", whatIs: { title: "¿Qué es la Cistitis Pediátrica?", text: "La orina es normalmente estéril. La cistitis ocurre cuando las bacterias (con mayor frecuencia *Escherichia coli* procedente del tracto digestivo) ingresan a través del meato urinario y ascienden por la uretra hasta la vejiga, donde se multiplican, causando irritación, hinchazón e inflamación dolorosa de las paredes vesicales." }, symptoms: { title: "Síntomas y Señales de Alarma", intro: "Los síntomas varían enormemente dependiendo de la edad del niño:", groups: [ { name: "Bebés y Niños Pequeños (No verbales)", items: ["Fiebre alta sin una causa obvia (a menudo es el único síntoma de una IVU en un bebé)", "Irritabilidad extrema y llanto constante e inexplicable", "Vómitos, rechazo al alimento o poco aumento de peso", "Orina con un olor inusualmente fuerte o desagradable"] }, { name: "Niños Mayores (Verbales)", items: ["Dolor, ardor o escozor al orinar (disuria) - el niño puede llorar al ir al baño", "Necesidad urgente y muy frecuente de orinar, a menudo haciendo solo unas gotas cada vez", "Dolor en la parte baja del abdomen (sobre el pubis) o sensación de presión", "Pérdida de orina accidental o enuresis nocturna (mojar la cama) en un niño que ya controlaba esfínteres", "Orina turbia, sanguinolenta (de color rosado o rojizo) o con muy mal olor"] } ], warning: "Si un niño con síntomas de cistitis desarrolla fiebre alta recurrente, escalofríos intensos, o dolor en los costados de la espalda (zona lumbar), es probable que la infección haya subido a los riñones (pielonefritis), lo cual es peligroso y puede dejar cicatrices renales permanentes." }, causes: { title: "Causas y Factores de Riesgo", intro: "Ciertas conductas o anatomías facilitan la entrada y retención de bacterias:", items: ["Limpieza incorrecta: En las niñas, limpiarse de atrás hacia adelante después de defecar arrastra bacterias fecales hacia la uretra.", "Retención voluntaria de orina: Niños que 'aguantan' las ganas de ir al baño para seguir jugando; la orina estancada favorece el crecimiento bacteriano.", "Estreñimiento severo: Las heces duras en el recto pueden presionar la vejiga, impidiendo que se vacíe por completo al orinar.", "Baños de burbujas o jabones fuertes que irritan la uretra.", "Anomalías anatómicas: Como el Reflujo Vesicoureteral (donde la orina fluye hacia atrás, de la vejiga a los riñones), u obstrucciones congénitas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamental recolectar la orina de manera limpia para evitar falsos positivos:", items: ["Análisis de Orina (Urianálisis) con tira reactiva en el consultorio (detecta glóbulos blancos, sangre y nitritos que sugieren infección rápida).", "Urocultivo: Es la prueba de oro obligatoria. Se envía orina al laboratorio para cultivar e identificar la bacteria exacta y determinar qué antibiótico la matará (tarda 48 horas). En bebés que usan pañal, a menudo se toma la orina mediante una sonda delgada o una punción suprapúbica (directamente de la vejiga) para asegurar que no esté contaminada por el pañal.", "Ecografía Renal y Vesical: Recomendada frecuentemente después del primer episodio de IVU en bebés o niños pequeños, para asegurar que no existan malformaciones anatómicas en los riñones o vejiga."], note: "" }, treatment: { title: "Tratamientos", intro: "Las infecciones urinarias en niños siempre requieren tratamiento médico, nunca remedios caseros exclusivos:", subsections: [ { title: "Manejo Médico y Prevención", items: ["Antibióticos orales: Recetados por el pediatra (ej. Amoxicilina, Cefalexina o Trimetoprima). Es crítico completar todo el ciclo del antibiótico (usualmente 5 a 7 días), incluso si el niño se siente mejor en 24 horas, para asegurar que la infección esté totalmente erradicada.", "Líquidos abundantes: Ofrecer mucha agua para ayudar a 'lavar' y expulsar las bacterias de la vejiga.", "Analgésicos pediátricos (Paracetamol o Ibuprofeno) para aliviar la fiebre y el dolor abdominal inicial.", "Prevención de recaídas: Tratar agresivamente cualquier estreñimiento, enseñar a las niñas a limpiarse de adelante hacia atrás, evitar prendas de vestir muy ajustadas y fomentar ir al baño regularmente sin retener la orina."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la consulta pediátrica o urgencias de inmediato si:", items: ["Tu bebé menor de 3 meses tiene fiebre de 38°C (100.4°F) o más (esto requiere evaluación hospitalaria urgente siempre)", "El niño tiene dolor intenso en la espalda, vómitos repetitivos y no puede retener los líquidos o antibióticos orales", "Observas sangre visible en la orina del niño"] } },
'Eyaculación retrasada' : { intro: "La eyaculación retrasada es una disfunción sexual masculina caracterizada por la necesidad de un período prolongado de estimulación sexual para lograr la eyaculación y el orgasmo, o por la incapacidad total para alcanzarlo a pesar de mantener una erección plena y desear eyacular.", whatIs: { title: "¿Qué es la Eyaculación Retrasada?", text: "A diferencia de la eyaculación precoz (que es muy rápida), en esta condición el hombre puede mantener relaciones sexuales durante 30 a 60 minutos o más sin lograr el clímax. Puede ser una condición de por vida (primaria) o adquirida (desarrollada después de un historial de función normal). También puede ser generalizada (ocurre en todas las situaciones) o situacional (solo ocurre durante las relaciones con una pareja, pero no durante la masturbación). Esta situación frecuentemente genera frustración intensa, agotamiento físico, y estrés severo en la relación de pareja." }, symptoms: { title: "Características del Trastorno", intro: "Los síntomas van más allá de la demora de tiempo:", groups: [ { name: "Indicadores Clínicos y Psicológicos", items: ["Incapacidad persistente para alcanzar el orgasmo durante el coito o la estimulación manual por parte de la pareja", "Necesidad de pausas frecuentes debido al agotamiento físico o la pérdida de erección por fatiga antes de lograr eyacular", "Sentimientos de insuficiencia, evitación de la intimidad sexual y ansiedad anticipatoria", "Frustración o sensación de rechazo por parte de la pareja, quien puede sentir erróneamente que no es lo suficientemente atractiva o estimulante"] } ], warning: "Si la condición se desarrolla súbitamente tras iniciar un nuevo tratamiento médico, no debes suspender la medicación por tu cuenta, pero debes informar a tu médico de inmediato." }, causes: { title: "Causas y Factores de Riesgo", intro: "Suele ser multifactorial, con una fuerte superposición de problemas físicos y psicológicos:", items: ["Factores Farmacológicos (Muy comunes): Efecto secundario de los antidepresivos (especialmente los ISRS como la Sertralina o Fluoxetina), ansiolíticos, medicamentos para la presión arterial alta o diuréticos.", "Factores Psicológicos: Ansiedad por el desempeño, estrés grave, depresión, culpa religiosa severa, miedo a causar un embarazo, o problemas y resentimientos no resueltos en la relación de pareja.", "Desensibilización por Masturbación Idiosincrásica: Acondicionamiento a un estilo de masturbación muy agresivo, de alta presión o velocidad (a menudo frente a la pornografía) que una pareja humana no puede replicar físicamente (síndrome del agarre de la muerte).", "Factores Físicos y Neurológicos: Envejecimiento natural, neuropatía diabética (daño a los nervios del pene), lesiones de la médula espinal, cirugías previas de próstata o niveles bajos de testosterona."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo o sexólogo realizará una evaluación integral:", items: ["Historia clínica y sexual muy detallada para determinar si el problema es situacional o general, y evaluar el impacto emocional", "Revisión exhaustiva de todos los medicamentos y suplementos que el paciente toma actualmente", "Examen físico para comprobar la sensibilidad neurológica de los genitales", "Análisis de sangre para verificar los niveles hormonales (testosterona, prolactina, tiroides) o descartar diabetes no diagnosticada"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere abordar tanto la biología como el entorno psicológico:", subsections: [ { title: "Opciones de Manejo", items: ["Ajuste de Medicación: Si la causa son los antidepresivos, el médico puede reducir la dosis o cambiar a un fármaco con menos efectos secundarios sexuales (como Bupropión o Mirtazapina).", "Terapia Psicosexual: Fundamental. Se enfoca en reducir la ansiedad de desempeño, mejorar la comunicación de pareja y eliminar la presión de que el sexo 'debe' terminar en eyaculación.", "Reacondicionamiento de la Masturbación: Abstinencia temporal de la masturbación o cambios en la técnica para re-sensibilizar el cerebro y el cuerpo a estímulos más suaves y realistas.", "Medicamentos Especializados: Aunque no hay medicamentos aprobados por la FDA específicamente para esto, a veces se usan fármacos fuera de indicación clínica (como Amantadina, Buspirona o Cabergolina) que alteran la química cerebral para facilitar el clímax.", "Tratamiento de la Enfermedad Base: Control estricto de la diabetes u optimización del reemplazo de testosterona."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No dudes en consultar a un urólogo o un terapeuta sexual si:", items: ["La demora o incapacidad para eyacular te causa estrés personal significativo, ansiedad o evitas tener relaciones sexuales", "El problema está causando conflictos, discusiones o deterioro en tu relación de pareja", "Deseas concebir un hijo con tu pareja y la afección lo está impidiendo"] } },
'Exotropía' : { intro: "La exotropía (comúnmente conocida como estrabismo divergente o 'ojo desviado hacia afuera') es una condición ocular en la que uno o ambos ojos se desvían hacia afuera, alejándose de la nariz. Es el tipo de estrabismo que ocurre con mayor frecuencia en la infancia tardía o la edad adulta temprana.", whatIs: { title: "¿Qué es la Exotropía?", text: "Para tener una visión binocular normal (ver en 3D y calcular distancias), los músculos de ambos ojos deben trabajar juntos de forma perfectamente sincronizada para apuntar al mismo objeto. En la exotropía, esta coordinación muscular falla. Cuando un ojo mira al objetivo, el otro se desvía hacia el exterior. Esto hace que el cerebro reciba dos imágenes diferentes y desconectadas. Para evitar la confusión y la visión doble, el cerebro de los niños suele 'apagar' (suprimir) la imagen del ojo desviado, lo que puede provocar una pérdida permanente de visión en ese ojo (ambliopía u ojo vago)." }, symptoms: { title: "Síntomas y Señales Observables", intro: "Los signos son tanto visuales como conductuales:", groups: [ { name: "Signos Clínicos", items: ["Desviación visible de un ojo hacia la sien (hacia afuera). A menudo no es constante al principio (exotropía intermitente).", "La desviación empeora notablemente cuando el niño está cansado, enfermo, soñando despierto o mirando objetos muy lejanos.", "Cerrar o guiñar un ojo cuando se está bajo la luz del sol brillante (un signo clásico y característico de la exotropía).", "Frotarse frecuentemente los ojos o presentar fatiga visual y dolores de cabeza severos tras la lectura.", "Quejas de visión doble (diplopía) en adultos o en niños cuando el cerebro aún no ha aprendido a suprimir la segunda imagen."] } ], warning: "Cualquier desviación ocular constante (que no se endereza) o que aparece repentinamente en un adulto debe ser evaluada por un oftalmólogo o neurólogo inmediatamente para descartar tumores cerebrales o problemas neurológicos." }, types: { title: "Tipos de Exotropía", intro: "La condición se manifiesta de diferentes maneras:", items: ["Exotropía Intermitente: Es la forma más común. Los ojos se ven normales y rectos la mayor parte del tiempo, pero el ojo 'se escapa' hacia afuera al estar fatigado o distraído.", "Exotropía Sensorial: Ocurre cuando un ojo pierde visión por otra razón (como una catarata grave en la infancia o un trauma). Al no ver bien, el cerebro deja de intentar mantenerlo alineado y el ojo ciego 'deriva' hacia afuera.", "Exotropía Constante: El ojo está permanentemente desviado hacia afuera y nunca se alinea con el otro."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "A menudo es idiopática, pero los músculos fallan en su coordinación por:", items: ["Herencia genética (antecedentes familiares de estrabismo o ambliopía son un factor de riesgo altísimo)", "Anomalías en los músculos del ojo o en los nervios del cerebro que los controlan", "Afecciones subyacentes como parálisis cerebral, síndrome de Down, o bebés que nacieron prematuramente", "Errores de refracción muy altos o desiguales (un ojo necesita mucha más graduación que el otro)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un oftalmólogo, idealmente especialista pediátrico, realizará un examen detallado:", items: ["Examen de agudeza visual para cada ojo (para detectar si ya hay ambliopía u ojo vago instalada)", "Pruebas de alineación ocular (como la prueba de ocluir y destapar) utilizando prismas para medir exactamente los grados de la desviación", "Examen de refracción bajo cicloplejia (usando gotas dilatadoras para medir si el niño necesita gafas)", "Examen neurológico básico y de la salud de la retina para asegurar que no hay problemas en el nervio óptico"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es escalonado, con el objetivo final de alinear los ojos y preservar la visión tridimensional:", subsections: [ { title: "Opciones de Manejo Visual y Quirúrgico", items: ["Uso de Gafas (Anteojos): Si existe miopía, astigmatismo u otras alteraciones, corregirlas a menudo ayuda a enderezar los ojos y mejorar el control cerebral sobre ellos.", "Terapia Ocular (Ortóptica): Ejercicios visuales y de convergencia guiados ('flexiones con lápiz') para ayudar al paciente a entrenar los músculos de sus ojos y enseñarle al cerebro a controlarlos juntos. Especialmente útil en exotropía intermitente leve.", "Terapia de oclusión (Parches): Si el ojo desviado ha desarrollado ambliopía, se tapa el ojo bueno con un parche durante varias horas al día para obligar al cerebro a usar y fortalecer el ojo débil.", "Cirugía de Músculos Extraoculares: Si la desviación es constante, severa o no mejora con lo anterior, el oftalmólogo cirujano debilita o acorta estratégicamente los pequeños músculos que rodean el ojo para realinearlo mecánicamente. A menudo es muy exitosa."] } ], note: "La cirugía mejora la alineación física, pero no corrige la mala visión ni el ojo vago. A menudo se requiere continuar usando parches o gafas después de la operación." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una revisión oftalmológica si:", items: ["Notas que uno de los ojos de tu hijo se desvía hacia afuera, incluso si solo ocurre de vez en cuando al estar cansado", "Tu hijo frecuentemente cierra un ojo cuando sale a la calle en un día soleado", "Tú, como adulto, experimentas episodios de visión doble que desaparecen al tapar uno de tus ojos"] } },
'Membrana epirretiniana macular' : { intro: "La membrana epirretiniana macular (MEM), también conocida como 'pucker macular' o celofán macular, es una enfermedad del ojo caracterizada por la formación de un tejido cicatricial (una fina membrana arrugada) sobre la superficie de la mácula, la zona central de la retina responsable de la visión detallada y nítida.", whatIs: { title: "¿Qué es una Membrana Epirretiniana?", text: "La retina es el tejido sensible a la luz en el fondo del ojo, y su centro exacto (la mácula) nos permite leer, reconocer rostros y ver detalles finos. A medida que envejecemos, el gel vítreo que llena el ojo se encoge y se despega naturalmente de la retina. En algunas personas, este desprendimiento provoca una reacción de reparación celular exagerada, formando una membrana casi invisible similar a un celofán sobre la mácula. A medida que esta membrana cicatriza, se contrae y se arruga, 'frunciendo' y distorsionando la mácula que está debajo, lo que arruina la visión central clara." }, symptoms: { title: "Síntomas y Efectos Visuales", intro: "Los síntomas afectan exclusivamente la visión central, nunca la periférica:", groups: [ { name: "Distorsiones Visuales", items: ["Visión borrosa o ligeramente nublada en el centro del campo visual, incluso usando gafas", "Metamorfopsia (el síntoma más característico): Las líneas rectas, como marcos de puertas, baldosas o líneas de texto, se ven onduladas, torcidas, curvas o rotas", "Dificultad progresiva para leer letras pequeñas o ver detalles finos en tareas de precisión", "Aparición de una mancha gris o área desenfocada estática directamente en el centro de la visión"] } ], warning: "Aunque puede ser muy frustrante, la membrana epirretiniana NO causa ceguera total, ya que la visión periférica o lateral (el resto de la retina) permanece completamente intacta." }, types: { title: "Diferencia con la Degeneración Macular", intro: "Es fundamental no confundirla con la Degeneración Macular Asociada a la Edad (DMAE):", items: ["Membrana Epirretiniana: Es un problema mecánico y de cicatrización en la superficie (encima) de la retina. Se puede 'pelar' quirúrgicamente con alto éxito.", "DMAE: Es un problema degenerativo debajo de la retina. Es más destructivo y se maneja con inyecciones de por vida, no se cura con cirugía."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La mayoría de los casos ocurren en personas mayores de 50 años, provocados por:", items: ["Desprendimiento de vítreo posterior (DVP): El envejecimiento normal del ojo donde la gelatina vítrea se separa de la retina (la causa en el 80% de los casos idiopáticos).", "Traumatismos o golpes fuertes previos en el ojo", "Cirugías intraoculares anteriores (como cirugía de desprendimiento de retina o cirugías de cataratas complicadas)", "Enfermedades inflamatorias del ojo (uveítis) o diabetes ocular (retinopatía diabética)", "Desgarros retinianos pasados tratados con láser"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El oftalmólogo (especialista en retina) la diagnostica sin necesidad de pruebas invasivas:", items: ["Examen de fondo de ojo con pupilas dilatadas (el médico puede ver un reflejo brillante y arrugado sobre la mácula)", "Tomografía de Coherencia Óptica (OCT): Es la prueba esencial de escáner láser no invasiva. Crea imágenes transversales en 3D de la retina, revelando la presencia, el grosor exacto de la membrana y cuánto está arrugando la mácula.", "Rejilla de Amsler: Una cuadrícula de líneas rectas que el paciente mira para revelar qué tan onduladas o distorsionadas percibe las líneas."], note: "La OCT se repite periódicamente para monitorear si la membrana está empeorando o es estable." }, treatment: { title: "Tratamientos", intro: "No existen gotas oculares, dietas, vitaminas ni medicamentos que disuelvan esta membrana. El tratamiento depende de cómo afecte la calidad de vida:", subsections: [ { title: "Opciones de Manejo y Cirugía", items: ["Observación Activa: Si la membrana es leve y los síntomas no interfieren con la vida diaria del paciente (lectura, conducción), el oftalmólogo simplemente la monitoreará cada 6 a 12 meses sin intervenir. Sorprendentemente, a veces pueden desprenderse por sí solas.", "Actualización de las gafas: Cambiar la graduación puede ayudar levemente a compensar parte de la visión borrosa.", "Vitrectomía con Pelado Macular (Cirugía Definitiva): Si la visión distorsionada impide realizar tareas importantes, el cirujano de retina realiza una microcirugía. Se extrae el gel vítreo del ojo (vitrectomía) y, utilizando unas pinzas microscópicas, 'pela' y retira con extremada delicadeza la membrana arrugada de la superficie de la mácula. El ojo se llena temporalmente con una burbuja de gas o aire para que la mácula se aplane y sane."] } ], note: "La recuperación de la cirugía es lenta; la visión tarda de 3 a 6 meses en enderezarse y mejorar tras extirpar la membrana. Además, esta cirugía acelera fuertemente la aparición de cataratas en ojos que no han sido operados de ellas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita una revisión oftalmológica urgente si:", items: ["De un día para otro, notas que las persianas, el marco de una puerta o las palabras en un libro se ven onduladas o distorsionadas", "Sientes que tu visión central se ha vuelto gris o brumosa, impidiéndote ver los rostros de las personas claramente"] } },
'Boca de trinchera' : { intro: "La 'boca de trinchera', médicamente conocida como gingivitis ulceronecrotizante aguda (GUNA), es una infección bacteriana severa, dolorosa y de rápida progresión que destruye el tejido de las encías.", whatIs: { title: "¿Qué es la Boca de Trinchera?", text: "Es una forma grave de gingivitis. Su nombre histórico proviene de la Primera Guerra Mundial, cuando los soldados en las trincheras la sufrían debido al estrés extremo, mala higiene y desnutrición. Las bacterias atacan las papilas (el tejido de la encía entre los dientes), causando úlceras, muerte del tejido (necrosis) y un dolor intenso que dificulta comer o cepillarse." }, symptoms: { title: "Síntomas Comunes", intro: "La aparición es súbita y los síntomas son muy característicos:", groups: [ { name: "Síntomas Bucales", items: ["Dolor intenso y constante en las encías", "Sangrado gingival espontáneo o ante el más mínimo roce", "Aparición de una película o capa grisácea/amarillenta sobre las encías (pseudomembrana de tejido muerto)", "Mal aliento extremo y fétido (halitosis grave)", "Úlceras en forma de 'cráter' entre los dientes"] }, { name: "Síntomas Generales", items: ["Fiebre y malestar general", "Ganglios linfáticos inflamados en el cuello y bajo la mandíbula"] } ], warning: "Sin tratamiento dental urgente, la infección puede destruir rápidamente el hueso que soporta los dientes, provocando su pérdida irreversible." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se desarrolla por un crecimiento bacteriano descontrolado, facilitado por:", items: ["Higiene bucal deficiente", "Estrés psicológico extremo o fatiga severa prolongada", "Tabaquismo crónico (reduce el flujo sanguíneo a las encías)", "Deficiencias nutricionales graves", "Sistema inmunológico debilitado (como en pacientes con VIH/SIDA o bajo estrés severo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico en el consultorio dental:", items: ["Examen visual directo por un odontólogo o periodoncista (las úlceras decapitadas entre los dientes son inconfundibles)", "Radiografías dentales panorámicas o periapicales (para evaluar si la infección ha comenzado a destruir el hueso de soporte bajo las encías)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere intervención profesional inmediata para detener la destrucción del tejido:", subsections: [ { title: "Manejo Odontológico", items: ["Desbridamiento profesional: Limpieza profunda y delicada por parte del dentista (usualmente bajo anestesia local) para eliminar el tejido muerto, la placa y el sarro.", "Antibióticos: Frecuentemente se prescribe Metronidazol o Amoxicilina para combatir las bacterias anaerobias responsables de la infección.", "Enjuagues antimicrobianos: Uso de colutorios con clorhexidina o peróxido de hidrógeno diluido varias veces al día.", "Analgésicos para el dolor intenso (Ibuprofeno o Paracetamol).", "Mejora estricta de la higiene oral y abandono del tabaco."] } ], note: "Una vez pasada la fase aguda, puede ser necesaria una cirugía periodontal menor para remodelar las encías destruidas y facilitar su limpieza futura." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un dentista de urgencia si:", items: ["Tus encías sangran de forma espontánea o están cubiertas por una película grisácea", "Sufres un dolor de encías tan agudo que te impide comer, dormir o cepillarte los dientes", "El dolor bucal está acompañado de fiebre y un mal aliento insoportable persistente"] } },
'Tinnitus' : { intro: "El tinnitus, comúnmente conocido como acúfeno, es la percepción de un sonido (zumbido, pitido, silbido o rugido) en los oídos o en la cabeza sin que exista una fuente de sonido externa.", whatIs: { title: "¿Qué es el Tinnitus?", text: "Es importante entender que el tinnitus no es una enfermedad en sí misma, sino un síntoma de un problema subyacente en el sistema auditivo (que incluye el oído, el nervio auditivo y el cerebro). Es una condición extremadamente común que puede ser temporal o crónica, y aunque en la mayoría de los casos no indica un problema de salud grave, puede afectar profundamente la calidad de vida, el sueño y la concentración." }, symptoms: { title: "Síntomas y Características", intro: "El paciente escucha ruidos 'fantasma' que pueden variar en tono e intensidad:", groups: [ { name: "Tipos de Sonido Percibidos", items: ["Zumbido agudo o pitido constante (el más frecuente)", "Sonido de estática, siseo, rugido de mar o zumbido de insectos", "Sonidos pulsátiles que van al ritmo de los latidos del corazón", "El ruido puede estar presente en uno o ambos oídos, ser continuo o ir y venir"] } ], warning: "Si el tinnitus es pulsátil (suena como el latido de tu corazón), ocurre en un solo oído, o está acompañado de mareos y pérdida de audición repentina, requiere evaluación médica urgente." }, types: { title: "Tipos de Tinnitus", intro: "Existen dos clasificaciones médicas principales:", items: ["Tinnitus Subjetivo: El más común. Solo tú puedes escuchar el ruido. Está causado por problemas en el oído externo, medio, interno o en los nervios auditivos.", "Tinnitus Objetivo: Un médico puede escuchar el ruido durante un examen utilizando un estetoscopio. Es raro y suele estar causado por problemas en los vasos sanguíneos, contracciones musculares del oído medio o problemas articulares (ATM)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Múltiples factores pueden desencadenarlo o empeorarlo:", items: ["Daño a las células ciliadas del oído interno por exposición a ruidos fuertes (conciertos, maquinaria, auriculares a volumen muy alto)", "Pérdida de audición relacionada con el envejecimiento (presbiacusia)", "Obstrucciones en el canal auditivo (tapones de cerumen apretados o infecciones de oído)", "Uso de medicamentos ototóxicos (dosis altas de aspirina, ciertos antibióticos, diuréticos o quimioterapia)", "Trastornos de la articulación temporomandibular (ATM) en la mandíbula, o lesiones en el cuello", "Enfermedad de Ménière (un trastorno del oído interno que también causa vértigo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un otorrinolaringólogo o audiólogo realizará:", items: ["Examen físico del oído, cabeza y cuello (buscando tapones de cera o escuchando flujos sanguíneos)", "Audiometría (prueba de audición completa en una cabina insonorizada para detectar el rango de pérdida auditiva asociada)", "Pruebas de movimiento: Pedir al paciente que apriete la mandíbula o mueva el cuello para ver si el sonido cambia", "Pruebas de imagen (Tomografía - TC o Resonancia Magnética - RM) si el tinnitus es unilateral o pulsátil, para descartar tumores benignos (neurinoma del acústico) o problemas vasculares"], note: "" }, treatment: { title: "Tratamientos", intro: "Si bien no siempre hay una 'cura' absoluta, el manejo se enfoca en minimizar el impacto del sonido:", subsections: [ { title: "Estrategias de Alivio y Manejo", items: ["Tratamiento de la causa subyacente: Extracción de tapones de cera, cambio de medicación ototóxica o tratamiento de problemas vasculares.", "Audífonos: Si hay pérdida de audición, usar audífonos amplifica los sonidos externos, haciendo que el tinnitus sea menos notorio.", "Enmascaramiento de sonido (Ruido blanco): Uso de máquinas de ruido blanco, ventiladores o radios a bajo volumen durante la noche para 'tapar' el zumbido interno y facilitar el sueño.", "Terapia de Reentrenamiento del Tinnitus (TRT): Un tratamiento especializado que combina el uso de dispositivos emisores de sonido de banda ancha con terapia psicológica para enseñar al cerebro a ignorar el ruido (habituación).", "Terapia Cognitivo-Conductual (TCC): Ayuda a reducir el estrés, la ansiedad y la depresión severa que frecuentemente acompañan al tinnitus crónico."] } ], note: "Evitar el silencio absoluto, reducir la cafeína y el alcohol, y manejar el estrés son pasos vitales, ya que la ansiedad amplifica el volumen percibido del tinnitus." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico especialista si:", items: ["El zumbido aparece repentinamente sin causa obvia", "Afecta solo a un oído o pulsa al ritmo de tus latidos", "Está acompañado de mareos intensos, pérdida de equilibrio o pérdida de audición repentina", "El ruido es tan molesto que interfiere con tu sueño, tu concentración o te provoca depresión"] } },
'Glaucoma de ángulo abierto' : { intro: "El glaucoma de ángulo abierto es la forma más común de glaucoma, una enfermedad ocular crónica que daña progresivamente el nervio óptico (el cable que envía las imágenes del ojo al cerebro). Es conocido como el 'ladrón silencioso de la vista' debido a que no presenta síntomas hasta que la pérdida de visión es irreversible.", whatIs: { title: "¿Qué es el Glaucoma de Ángulo Abierto?", text: "El ojo produce y drena continuamente un líquido llamado humor acuoso para mantener su forma y nutrición. En este tipo de glaucoma, el ángulo de drenaje está anatómicamente 'abierto', pero la malla de drenaje funciona de manera deficiente, como un filtro obstruido. El líquido se acumula gradualmente, elevando la presión intraocular (PIO). Con el paso de los años, esta alta presión aplasta y mata las fibras del nervio óptico, reduciendo el campo visual lentamente desde los bordes hacia el centro." }, symptoms: { title: "Síntomas Comunes", intro: "Esta es la característica más peligrosa de la enfermedad:", groups: [ { name: "Ausencia de Síntomas Iniciales", items: ["En sus primeras etapas, NO hay dolor, NO hay enrojecimiento y NO hay cambios perceptibles en la visión. La persona no nota que está perdiendo vista porque el cerebro compensa los primeros puntos ciegos."] }, { name: "Síntomas en Etapas Avanzadas", items: ["Aparición de puntos ciegos irregulares en la visión lateral (periférica)", "Visión de túnel (el campo visual se estrecha tanto que la persona solo puede ver lo que está directamente frente a ella)", "Tropezar con objetos a los lados o dificultad para conducir", "Pérdida total de la visión (ceguera) en etapas terminales no tratadas"] } ], warning: "El daño causado por el glaucoma es permanente e irreversible. La visión perdida no se puede recuperar. El único objetivo del tratamiento es detener un daño mayor." }, types: { title: "Factores de Riesgo", intro: "Cualquier persona puede padecerlo, pero el riesgo es mucho mayor si:", items: ["Tienes presión intraocular elevada (aunque algunas personas desarrollan glaucoma con presión 'normal')", "Eres mayor de 60 años", "Tienes ascendencia africana o hispana (el riesgo aumenta y aparece a edades más tempranas)", "Tienes antecedentes familiares directos de glaucoma", "Padeces miopía severa (visión corta alta) o diabetes", "Has usado corticosteroides (como gotas para los ojos o inhaladores) durante mucho tiempo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere exámenes oculares completos regulares:", items: ["Tonometría (prueba para medir la presión interna del ojo)", "Examen del fondo de ojo con dilatación (el oftalmólogo evalúa visualmente el color y la forma del nervio óptico para detectar daño temprano o 'excavación')", "Campimetría o prueba de campo visual (para mapear puntos ciegos en la visión periférica)", "Tomografía de Coherencia Óptica (OCT) (un escáner láser de alta precisión que mide el grosor de la capa de fibras nerviosas de la retina, detectando daños años antes de que aparezcan síntomas visuales)", "Gonioscopia (uso de una lente especial para ver si el ángulo de drenaje está abierto o cerrado)"], note: "Se recomiendan exámenes oftalmológicos regulares cada 1-2 años a partir de los 40 años para su detección precoz." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca exclusivamente en reducir y estabilizar la presión intraocular:", subsections: [ { title: "Opciones de Manejo Escalonado", items: ["Gotas Oftálmicas (Primera línea): Medicamentos de uso diario (como análogos de prostaglandinas o betabloqueantes) que disminuyen la producción de líquido en el ojo o mejoran su drenaje. Su cumplimiento estricto es vital.", "Trabeculoplastia con Láser (SLT/ALT): Un procedimiento ambulatorio rápido donde un láser abre los canales de la malla de drenaje para facilitar la salida del líquido.", "Cirugía de Filtración (Trabeculectomía): El cirujano crea una nueva vía de drenaje ('ampolla') en la parte blanca del ojo para que el líquido drene bajo la conjuntiva si las gotas y el láser no funcionan.", "Dispositivos de Drenaje (Tubos o Válvulas): Inserción de un pequeño tubo de silicona en el ojo para derivar el líquido.", "Cirugías de Glaucoma Mínimamente Invasivas (MIGS): Procedimientos más modernos y seguros que implantan micro-dispositivos para mejorar el drenaje en casos de leves a moderados."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "No esperes a tener síntomas. Acude a tu oftalmólogo si:", items: ["Tienes más de 40 años y antecedentes familiares de glaucoma (programa revisiones rutinarias)", "Notas que tienes que girar la cabeza para ver objetos a los lados (pérdida de visión periférica)", "Te han diagnosticado presión ocular alta en una revisión óptica general"] } },
'Cifosis postural' : { intro: "La cifosis postural es el encorvamiento excesivo hacia adelante de la parte superior de la espalda (columna torácica), coloquialmente conocido como 'joroba'. Es el tipo más común de cifosis y está causado directamente por malos hábitos de postura, no por deformidades estructurales en los huesos.", whatIs: { title: "¿Qué es la Cifosis Postural?", text: "La columna vertebral tiene curvas naturales; sin embargo, en la cifosis postural, esta curva se exagera (normalmente más de 50 grados). Ocurre cuando nos encorvamos constantemente, como al mirar el teléfono, sentarnos mal en el escritorio o llevar mochilas pesadas. Los músculos y ligamentos de la espalda se estiran y se debilitan, mientras que los músculos del pecho se acortan, fijando la mala postura. A diferencia de las cifosis estructurales, la columna en sí es normal y flexible, y la persona puede corregir la curva si se le pide que se ponga de pie derecha." }, symptoms: { title: "Síntomas Comunes", intro: "A menudo es más un problema estético que médico, pero puede causar molestias:", groups: [ { name: "Síntomas Visuales y Físicos", items: ["Postura visiblemente encorvada, con los hombros caídos hacia adelante y la cabeza adelantada", "Dolor leve a moderado, sordo y punzante en la parte media y superior de la espalda", "Fatiga muscular en la espalda y el cuello, especialmente tras estar de pie o sentado por largos periodos", "La curvatura desaparece por completo cuando la persona se acuesta boca arriba o hace un esfuerzo consciente por erguirse"] } ], warning: "Si la curvatura es dolorosa, rígida (no se corrige al intentar ponerse derecho) o empeora rápidamente en un adolescente, puede ser Cifosis de Scheuermann (estructural) y requiere valoración médica ortopédica." }, types: { title: "Diferencia con Cifosis Estructurales", intro: "Es crucial diferenciar la causa de la curvatura:", items: ["Cifosis Postural: Causada por debilidad muscular y malos hábitos. Huesos normales. Curva flexible. Típica en adolescentes y oficinistas.", "Cifosis de Scheuermann: Aparece en la adolescencia; las vértebras crecen en forma de cuña en lugar de rectangulares. Curva rígida y a menudo dolorosa.", "Cifosis Congénita: Malformación de la columna presente desde el nacimiento. Requiere cirugía.", "Cifosis Osteoporótica: Común en mujeres mayores; causada por microfracturas y aplastamiento de las vértebras debido a huesos frágiles."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "El desarrollo de esta condición se debe casi por completo a factores de estilo de vida:", items: ["Higiene postural deficiente (pasar horas encorvado frente a pantallas de ordenador, tablets o móviles)", "Debilidad en los músculos extensores de la espalda (core) y falta de acondicionamiento físico", "Baja autoestima o timidez en adolescentes (tendencia a encogerse para 'esconderse')", "Uso de mochilas escolares excesivamente pesadas que tiran de los hombros hacia adelante"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es rápido y clínico:", items: ["Prueba de flexión hacia adelante de Adams: El médico pide al paciente que se incline hacia adelante por la cintura. En la cifosis postural, la espalda mostrará una curva suave y redondeada.", "Evaluación de la flexibilidad: El médico pedirá al paciente que se tumbe en una camilla plana. Si la curva se aplana, es postural.", "Radiografías de la columna vertebral (lateral): Solo se solicitan para confirmar que las vértebras tienen una forma rectangular y saludable, y descartar otras afecciones si hay dolor severo o rigidez."], note: "" }, treatment: { title: "Tratamientos", intro: "La cifosis postural no requiere cirugía, yesos ni corsés ortopédicos agresivos. El tratamiento se basa en reeducar el cuerpo:", subsections: [ { title: "Manejo y Corrección", items: ["Fisioterapia: El pilar del tratamiento. Ejercicios dirigidos para fortalecer los músculos débiles de la espalda (que jalan los hombros hacia atrás) y estirar los músculos tensos del pecho (pectorales).", "Conciencia postural: Reeducación constante para sentarse y caminar erguido, imaginando un 'hilo que tira de la coronilla hacia el techo'.", "Ergonomía: Ajustar la altura de las sillas, escritorios y monitores de ordenador a nivel de los ojos para evitar agachar el cuello.", "Práctica de deportes específicos: Deportes como la natación (especialmente estilo espalda) o el Pilates son excelentes para fortalecer el core y corregir la postura.", "Analgésicos de venta libre: Ocasionalmente para aliviar el dolor muscular por fatiga."] } ], note: "Los correctores de postura de venta comercial no se recomiendan a largo plazo, ya que hacen el trabajo de los músculos, debilitando la espalda aún más con el tiempo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un traumatólogo o fisioterapeuta si:", items: ["El dolor de espalda es fuerte, empeora con el tiempo o te despierta por la noche", "Notas que eres incapaz de enderezar la espalda por mucho que lo intentes (rigidez)", "Sientes entumecimiento, debilidad o dolor que se irradia hacia los brazos o piernas"] } },
'Manos entumidas' : { intro: "El entumecimiento en las manos es una sensación anormal de pérdida de sensibilidad, a menudo acompañada de hormigueo, picazón o una sensación de 'alfileres y agujas' (parestesia). Generalmente es un síntoma de que un nervio se ha irritado, comprimido o dañado, o de que hay una interrupción temporal del flujo sanguíneo.", whatIs: { title: "¿Qué significa tener las Manos Entumidas?", text: "Es un síntoma neurológico o circulatorio muy común. Si te quedas dormido sobre tu brazo y despiertas con la mano entumecida, se debe a una compresión inofensiva y temporal. Sin embargo, si el entumecimiento es persistente, ocurre frecuentemente por la noche, o se acompaña de dolor y debilidad, suele indicar el atrapamiento de un nervio específico (como en el túnel carpiano) o una neuropatía sistémica." }, symptoms: { title: "Síntomas Asociados", intro: "El patrón de entumecimiento ofrece pistas vitales sobre la causa:", groups: [ { name: "Según el Patrón Nervioso", items: ["Entumecimiento en el pulgar, índice, medio y la mitad del anular: Típico del Síndrome del Túnel Carpiano (nervio mediano comprimido en la muñeca), a menudo empeora por la noche.", "Entumecimiento exclusivo en el dedo meñique y la mitad del anular: Indica compresión del nervio cubital (a menudo atrapado en el codo, conocido como síndrome del túnel cubital).", "Entumecimiento que viaja desde el cuello o el hombro hasta los dedos: Sugiere una radiculopatía cervical (un nervio pinzado en la columna del cuello por una hernia de disco o desgaste)."] }, { name: "Síntomas Generales Concurrentes", items: ["Sensación de ardor, dolor punzante o descargas eléctricas", "Debilidad en la mano y torpeza (dejar caer objetos frecuentemente)", "Sensibilidad al frío extremo o cambios de color en los dedos (blancos o azules)"] } ], warning: "Un entumecimiento repentino en una mano o en un brazo completo, especialmente si va acompañado de debilidad facial, confusión o dificultad para hablar, es un signo clásico de un Accidente Cerebrovascular (EVC o derrame) y es una emergencia de 911." }, causes: { title: "Causas y Factores de Riesgo", intro: "Múltiples problemas pueden dañar los nervios de las manos:", items: ["Neuropatías por atrapamiento (Síndrome del túnel carpiano y túnel cubital)", "Radiculopatía cervical (nervio espinal del cuello comprimido por hernia o artrosis)", "Neuropatía periférica diabética (daño crónico a los nervios por altos niveles de azúcar en sangre)", "Deficiencia severa de vitaminas, especialmente de Vitamina B12", "Trastornos autoinmunes (Artritis reumatoide, Lupus, Síndrome de Guillain-Barré)", "Enfermedad de Raynaud (espasmos de los vasos sanguíneos que bloquean el flujo ante el frío)", "Efecto secundario de ciertos medicamentos (como la quimioterapia) o alcoholismo crónico", "Gangliones o quistes articulares que presionan un nervio"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para descubrir exactamente dónde y por qué está fallando el nervio, el médico realizará:", items: ["Examen neurológico detallado (evaluando fuerza, reflejos y en qué dedos exactos se siente el hormigueo)", "Electromiografía (EMG) y Estudios de Conducción Nerviosa (miden la actividad eléctrica de los nervios; es la prueba de oro para confirmar túnel carpiano o neuropatías)", "Radiografías o Resonancia Magnética (RM) del cuello si se sospecha un problema en la columna cervical", "Análisis de sangre para descartar diabetes, problemas de tiroides, deficiencia de B12 o enfermedades autoinmunes"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento debe abordar la causa raíz de la compresión nerviosa:", subsections: [ { title: "Opciones Terapéuticas", items: ["Uso de férulas o muñequeras rígidas por la noche (el tratamiento inicial más eficaz para el túnel carpiano).", "Fisioterapia y ejercicios de deslizamiento nervioso para aliviar la tensión en el cuello o brazos.", "Medicamentos orales: Analgésicos, vitaminas (Complejo B), y para dolores neuropáticos crónicos se usan neuromoduladores como Gabapentina o Pregabalina.", "Inyecciones locales de corticosteroides (para reducir rápidamente la inflamación alrededor de un nervio pinzado).", "Control estricto del azúcar en sangre (vital si la causa es la diabetes).", "Cirugía de descompresión (como la liberación del túnel carpiano o cubital) si el entumecimiento es constante y hay riesgo de daño muscular permanente."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude al médico de urgencia si:", items: ["El entumecimiento aparece de manera repentina y afecta todo un lado de tu cuerpo", "Tienes dificultad para pensar, hablar o entender lo que te dicen al mismo tiempo que la mano se entume", "El entumecimiento se esparce rápidamente o afecta el control de tus esfínteres (orina/heces)", "Pide cita normal si el hormigueo empeora gradualmente y comienza a debilitar tu agarre"] } },
'Arterioesclerosis de las extremidades' : { intro: "La arterioesclerosis de las extremidades, diagnosticada comúnmente como Enfermedad Arterial Periférica (EAP), es un problema circulatorio frecuente en el cual las arterias que suministran sangre a las piernas y los pies se estrechan o se bloquean debido a la acumulación de placa de colesterol.", whatIs: { title: "¿Qué es la Enfermedad Arterial Periférica?", text: "Al igual que ocurre en el corazón (causando infartos), las arterias de las piernas pueden sufrir aterosclerosis (acumulación de grasas, colesterol y otras sustancias que forman placas endurecidas en sus paredes). Este estrechamiento reduce críticamente el flujo de sangre rica en oxígeno. Cuando caminas o haces ejercicio, tus músculos exigen más oxígeno; si las arterias están bloqueadas, no llega suficiente sangre, lo que provoca dolor agudo, calambres y debilidad." }, symptoms: { title: "Síntomas Comunes", intro: "Muchas personas tienen EAP leve sin síntomas, pero cuando la restricción de sangre es significativa, aparece:", groups: [ { name: "El Síntoma Clásico (Claudicación)", items: ["Claudicación Intermitente: Dolor intenso, calambres o fatiga en los músculos de las pantorrillas, los muslos o los glúteos que siempre ocurre al caminar o subir escaleras, y que se alivia predeciblemente tras unos minutos de reposo."] }, { name: "Signos Físicos de Mala Circulación", items: ["Piernas y pies fríos al tacto (especialmente comparado con el otro lado)", "Piel de las piernas que luce estirada, delgada o inusualmente brillante", "Pérdida de vello en los pies y pantorrillas, y crecimiento lento de las uñas de los pies", "Coloración pálida o azulada en las extremidades", "Pulso débil o totalmente ausente en las piernas o pies"] } ], warning: "Si experimentas dolor en los dedos del pie o en el pie mientras estás en reposo o acostado de noche (dolor de reposo isquémico), o si tienes llagas negras que no sanan, estás en riesgo inminente de desarrollar gangrena y perder la extremidad (Isquemia Crítica)." }, types: { title: "Diferenciación", intro: "No confundir con problemas venosos:", items: ["Problema Arterial (EAP): Falta de llegada de sangre limpia. Causa dolor al moverse, palidez, pies fríos, y úlceras secas y dolorosas en las puntas de los dedos.", "Problema Venoso (Várices/Insuficiencia): Falta de retorno de sangre sucia al corazón. Causa hinchazón, piernas pesadas, venas marcadas y úlceras húmedas en los tobillos."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La aterosclerosis es la causa fundamental, impulsada agresivamente por:", items: ["Tabaquismo: El factor de riesgo modificable más importante y destructivo. Fumar acelera la EAP enormemente.", "Diabetes: Acelera la formación de placa y daña los nervios periféricos.", "Edad (mayor de 50 años)", "Presión arterial alta (Hipertensión) y niveles altos de colesterol (Dislipidemia)", "Antecedentes familiares de enfermedad vascular periférica, enfermedades cardíacas o derrames cerebrales", "Niveles altos de homocisteína en la sangre"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamental realizar pruebas circulatorias:", items: ["Índice Tobillo-Brazo (ITB): Es la prueba inicial de oro. Compara la presión arterial medida en el tobillo con la presión en el brazo. Si la presión en el tobillo es significativamente menor, indica un bloqueo.", "Ecografía Doppler: Utiliza ondas sonoras para ver el flujo de sangre a través de las arterias e identificar el área exacta de bloqueo.", "Angiografía por Tomografía Computarizada (Angio-TC) o Resonancia Magnética (ARM): Imágenes detalladas con contraste de toda la red arterial.", "Angiografía con catéter: Examen invasivo con rayos X y tinte inyectado directamente en la arteria (se usa a menudo en el mismo momento que se planea destapar la arteria)."], note: "Tener EAP es una advertencia de que todo el sistema cardiovascular está afectado; los pacientes tienen un riesgo mucho mayor de sufrir ataques cardíacos." }, treatment: { title: "Tratamientos", intro: "El objetivo es detener la progresión de la placa, aliviar el dolor y prevenir amputaciones:", subsections: [ { title: "Opciones de Manejo Escalonado", items: ["Modificaciones Vitales: Dejar de fumar de inmediato (obligatorio). Control estricto de la diabetes, la presión arterial y el colesterol.", "Programa de Ejercicio Supervisado: Caminar hasta sentir dolor, descansar y volver a caminar. Esto entrena al cuerpo para crear nuevos vasos sanguíneos pequeños (circulación colateral) que rodeen el bloqueo.", "Medicamentos: Estatinas (para reducir colesterol y estabilizar la placa), Antiagregantes plaquetarios (Aspirina o Clopidogrel para prevenir coágulos), y Cilostazol (un fármaco específico que ensancha las arterias y mejora la distancia de caminata sin dolor).", "Angioplastia y Stents (Terapia Endovascular): Un procedimiento mínimamente invasivo donde se infla un pequeño globo dentro de la arteria bloqueada para abrirla, y a menudo se deja un tubo de malla de alambre (stent) para mantenerla abierta.", "Cirugía de Bypass (Derivación) Arterial: En casos graves o bloqueos muy largos, el cirujano utiliza una vena sana de otra parte del cuerpo, o un tubo sintético, para desviar el flujo de sangre alrededor de la arteria bloqueada."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental la atención vascular rápida si:", items: ["Experimentas dolor tipo calambre muscular en las pantorrillas al caminar que te obliga a detenerte, pero que desaparece al descansar", "Tienes llagas o heridas en los dedos del pie o el pie que no sanan después de varias semanas", "Tu pie se vuelve frío al tacto, pálido y duele intensamente incluso estando en reposo en la cama (Urgencia)"] } },
'Soplo cardíaco' : { intro: "Un soplo cardíaco no es una enfermedad por sí mismo, sino un sonido adicional o inusual, similar a un silbido, zumbido o crujido, que el médico escucha con el estetoscopio durante los latidos del corazón. Es causado por un flujo sanguíneo rápido o turbulento dentro de las cavidades del corazón o a través de sus válvulas.", whatIs: { title: "¿Qué es un Soplo Cardíaco?", text: "Para entenderlo, imagina el sonido del agua fluyendo silenciosamente por una manguera lisa. Si pellizcas la manguera o hay una obstrucción, el agua se vuelve turbulenta y hace ruido. De forma similar, la sangre fluye silenciosamente a través de un corazón normal. Si una válvula no se abre del todo o no cierra bien, o si hay un orificio en las paredes del corazón, el flujo de sangre se vuelve turbulento, creando el sonido del soplo. Muchos soplos son inofensivos, pero otros indican problemas cardíacos serios." }, symptoms: { title: "Síntomas Asociados (en Soplos Anormales)", intro: "Un soplo 'inocente' (inofensivo) no causa síntomas. Un soplo 'anormal' (por problemas estructurales) puede acompañarse de:", groups: [ { name: "Signos Clínicos", items: ["Dificultad para respirar, falta de aliento al hacer esfuerzo o al acostarse", "Hinchazón inusual (edema) en los tobillos, pies, piernas o el abdomen, y aumento de peso súbito", "Cianosis (coloración azulada en los labios o las yemas de los dedos, común en bebés con soplos congénitos)", "Fatiga constante, mareos intensos o episodios de desmayo (síncope) sin explicación", "Tos crónica persistente y agrandamiento de las venas del cuello", "Falta de apetito y crecimiento deficiente (en lactantes)"] } ], warning: "Si experimentas un dolor de pecho súbito o desmayos recurrentes, y sabes que tienes un soplo, es motivo de consulta urgente a cardiología." }, types: { title: "Clasificación Médica", intro: "El médico clasifica el soplo en dos grandes categorías:", items: ["Soplos Inocentes (Fisiológicos o Funcionales): Muy comunes en niños sanos (hasta el 50% los tienen). El corazón es normal, pero la sangre fluye rápido (por fiebre, crecimiento rápido, embarazo, anemia o hipertiroidismo). A menudo desaparecen al crecer o resolver la causa temporal.", "Soplos Anormales: Indican un problema estructural. En niños, suelen ser defectos congénitos (agujeros en el corazón). En adultos, suelen ser problemas adquiridos en las válvulas debido a envejecimiento, infecciones o fiebre reumática pasada."], note: "Los soplos también se clasifican por su volumen (grado del 1 al 6), momento en que ocurren (sistólico o diastólico) y tono." }, causes: { title: "Causas de Soplos Anormales", intro: "Los problemas estructurales más comunes que generan turbulencia son:", items: ["Estenosis valvular: Una válvula del corazón es rígida y no se abre completamente, forzando a la sangre a pasar por un orificio estrecho (ej. estenosis aórtica).", "Regurgitación o insuficiencia valvular: Una válvula no cierra herméticamente y la sangre se filtra hacia atrás (ej. prolapso de la válvula mitral).", "Defectos del tabique (CIA o CIV): 'Agujeros' anormales en la pared que separa las cámaras izquierda y derecha del corazón, presentes desde el nacimiento.", "Endocarditis infecciosa: Una infección bacteriana que destruye y crea vegetaciones en las válvulas del corazón.", "Fiebre reumática: Complicación de una infección de garganta por estreptococo no tratada en la infancia que deja cicatrices en las válvulas años después."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Si el médico detecta un soplo sospechoso, derivará al cardiólogo para:", items: ["Ecocardiograma: La prueba fundamental y definitiva. Usa ondas sonoras (ultrasonido) para crear imágenes en movimiento del corazón, permitiendo ver el tamaño de las cámaras, el estado de las válvulas y detectar fugas u orificios.", "Electrocardiograma (ECG): Para verificar el sistema eléctrico del corazón y detectar arritmias o agrandamiento muscular.", "Radiografía de tórax: Para ver si el corazón está agrandado o si hay líquido acumulado en los pulmones."], note: "El médico experimentado puede a menudo predecir la causa del soplo solo con escuchar detalladamente con el estetoscopio." }, treatment: { title: "Tratamientos", intro: "El tratamiento no es para curar el 'sonido', sino para corregir la causa si es peligrosa:", subsections: [ { title: "Manejo según la Causa", items: ["Soplos Inocentes: No requieren ningún tratamiento médico ni restricciones físicas. El paciente está completamente sano.", "Medicamentos: Si el soplo causa insuficiencia cardíaca, se recetan diuréticos (para eliminar líquido), inhibidores de la ECA (para relajar los vasos sanguíneos), betabloqueadores o anticoagulantes (para prevenir coágulos).", "Reparación o Reemplazo Valvular: Si una válvula está severamente dañada, requerirá cirugía a corazón abierto o procedimientos con catéter (TAVI) para repararla o cambiarla por una válvula artificial (mecánica o biológica).", "Cierre de Defectos Septales: Cirugía o cateterismo para tapar los 'agujeros' en el corazón congénitos."] } ], note: "Las personas con ciertas anomalías valvulares antes requerían antibióticos preventivos antes de ir al dentista; hoy en día, esto solo se recomienda para los casos de mayor riesgo (como los que tienen válvulas protésicas)." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar evaluación médica si a ti o a tu hijo le detectan un soplo y experimentan:", items: ["Episodios de desmayos, mareos extremos o sensación de que el corazón se 'salta' latidos", "Falta de aliento inusual al realizar esfuerzos físicos menores o al acostarse plano", "Cianosis (coloración azul) en las uñas o labios, o hinchazón severa en las piernas"] } },
'Embolia arterial' : { intro: "Una embolia arterial es una emergencia vascular potencialmente catastrófica que ocurre cuando un coágulo de sangre (émbolo), gas, placa o grasa viaja a través del torrente sanguíneo y se atasca bruscamente en una arteria más estrecha, bloqueando por completo el flujo de sangre rica en oxígeno hacia un órgano o una extremidad.", whatIs: { title: "¿Qué es una Embolia Arterial?", text: "A diferencia de la trombosis local (donde el coágulo se forma y crece lentamente en el lugar del bloqueo), un émbolo se forma en otra parte del cuerpo (generalmente en el corazón) y es disparado por la circulación hasta que choca contra un 'cuello de botella' arterial. Las extremidades (piernas y brazos) y el cerebro (causando un EVC isquémico) son los lugares más frecuentemente atacados. Al cortarse el riego de forma instantánea, el tejido afectado comenzará a morir (necrosis o gangrena) en cuestión de pocas horas si no se restaura la sangre." }, symptoms: { title: "Síntomas Clínicos", intro: "Los síntomas en las extremidades (las más comunes) aparecen de forma instantánea y brutal. Los médicos las conocen como las '6 P':", groups: [ { name: "Las 6 'P' de la Isquemia Arterial Aguda", items: ["Dolor (Pain): Dolor repentino, extremo e insoportable en la extremidad afectada.", "Palidez (Pallor): La piel se vuelve de color blanco cadáver o grisácea y luego moteada.", "Ausencia de pulso (Pulselessness): No se puede sentir el latido de la arteria debajo del bloqueo.", "Frialdad (Poikilothermia): La pierna o el brazo se sienten fríos al tacto como el hielo.", "Parálisis (Paralysis): Incapacidad para mover los dedos de la mano o el pie (un signo de daño severo al músculo y nervio).", "Parestesia (Paresthesia): Entumecimiento, hormigueo o sensación de 'muerte' total en la extremidad."] }, { name: "Síntomas en otros órganos", items: ["Cerebro: Parálisis facial, debilidad en un lado del cuerpo, pérdida del habla (Ictus / Accidente Cerebrovascular).", "Intestinos: Dolor abdominal agudo, extremo y desproporcionado, con náuseas y sangre en heces (Isquemia mesentérica).", "Riñón: Dolor súbito en la parte baja de la espalda o el costado y sangre en la orina."] } ], warning: "La isquemia arterial aguda en una extremidad es una carrera contra el reloj. El daño al tejido nervioso y muscular comienza a ser irreversible a las 6 horas del bloqueo." }, types: { title: "Diferencia entre Émbolo y Trombo", intro: "Para entender el tratamiento es vital conocer el origen:", items: ["Émbolo (Embolia): Material viajero. El 80-90% de los émbolos arteriales son coágulos de sangre que provienen de un corazón enfermo y se disparan a las arterias de las piernas, brazos o cerebro.", "Trombo (Trombosis): Un coágulo que se forma localmente sobre una placa de colesterol preexistente en la arteria."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La gran mayoría de los émbolos arteriales tienen un origen cardíaco:", items: ["Fibrilación Auricular: La causa más frecuente. Es una arritmia donde el corazón late de forma caótica, permitiendo que la sangre se estanque y forme coágulos que luego son expulsados.", "Infarto de miocardio reciente: El tejido cardíaco muerto favorece la formación de coágulos en su superficie interior.", "Enfermedad valvular y Endocarditis: Infecciones en las válvulas del corazón pueden desprender pequeños fragmentos (vegetaciones) llenos de bacterias.", "Aneurismas arteriales: Abultamientos en la aorta o arterias poplíteas donde se forman coágulos que luego se rompen en pedazos.", "Placas de aterosclerosis complejas que se desprenden (Ateroembolia)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico rápido es vital, confirmado inmediatamente por:", items: ["Ecografía Doppler dúplex de urgencia (el método más rápido para ubicar el punto exacto donde la sangre deja de fluir en la pierna o el brazo)", "Angiotomografía Computarizada (Angio-TC) (crea imágenes 3D de las arterias, muy útil para diagnosticar bloqueos en el intestino o el cerebro)", "Angiografía invasiva (se inyecta contraste por un catéter, a menudo se usa simultáneamente como medio de diagnóstico y tratamiento en el quirófano)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo único es restablecer el flujo sanguíneo ('revascularización') de inmediato para salvar el miembro u órgano:", subsections: [ { title: "Intervenciones de Emergencia", items: ["Embolectomía quirúrgica (Catéter de Fogarty): Es el tratamiento estándar para extremidades. El cirujano vascular hace un pequeño corte en la arteria y desliza un catéter con un globito desinflado más allá del coágulo, infla el globo y lo tira hacia atrás, arrastrando y extrayendo el coágulo físicamente.", "Trombolisis dirigida por catéter: Se inyectan medicamentos potentes para 'disolver o derretir' coágulos (como el tPA) directamente en el bloqueo a través de un tubo fino. (Lleva horas o días en hacer efecto, por lo que no se usa si el riesgo de perder la extremidad es inmediato).", "Anticoagulación sistémica inmediata: Se administra Heparina por vía intravenosa de inmediato para evitar que el coágulo crezca o que se formen nuevos.", "Amputación: Tristemente requerida si se llega demasiado tarde al hospital y los músculos ya están muertos y gangrenados (tejido inviable)."] } ], note: "Tras superar la emergencia, los pacientes a menudo requieren tomar medicamentos anticoagulantes de por vida para prevenir futuras embolias." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias del hospital más cercano a la máxima velocidad posible si:", items: ["Sufres un dolor fulminante e insoportable en una pierna o brazo de un segundo a otro", "Esa misma extremidad se vuelve blanca, fría y dejas de sentirla", "Pierdes la capacidad de mover los dedos o el pie/mano de esa extremidad", "Sufres parálisis facial repentina o dolor abdominal brutal e inexplicable"] } },
'Hipertensión renovascular' : { intro: "La hipertensión renovascular es una forma de presión arterial alta grave y resistente a medicamentos, causada por el estrechamiento u obstrucción (estenosis) de una o ambas arterias principales que llevan sangre a los riñones.", whatIs: { title: "¿Qué es la Hipertensión Renovascular?", text: "Es una de las causas secundarias más comunes de hipertensión, lo que significa que la presión alta es el síntoma de un problema estructural específico. Los riñones controlan el volumen de sangre del cuerpo. Cuando la arteria renal se estrecha, el riñón recibe menos sangre y asume erróneamente que la presión arterial de todo el cuerpo es baja o que hay una hemorragia. En respuesta, el riñón 'asustado' libera grandes cantidades de una hormona llamada renina, la cual desencadena una potente reacción química que hace que los vasos sanguíneos de todo el cuerpo se contraigan, disparando la presión arterial a niveles peligrosamente altos." }, symptoms: { title: "Síntomas Comunes", intro: "Al igual que la hipertensión esencial, suele ser silenciosa, pero hay pistas clínicas claras:", groups: [ { name: "Señales Clínicas y Manifestaciones", items: ["Desarrollo repentino de hipertensión severa en una persona muy joven (menor de 30 años) o en una persona mayor (mayor de 55 años)", "Presión arterial maligna y resistente que no logra controlarse a pesar de tomar tres o más medicamentos antihipertensivos a dosis máximas", "Empeoramiento rápido e inexplicable de la función de los riñones (detectado en análisis de sangre por la subida de creatinina)", "Episodios de acumulación repentina de líquido en los pulmones (edema pulmonar relámpago) sin razón aparente cardíaca", "Dolor de cabeza intenso, zumbido en los oídos o visión borrosa por la crisis hipertensiva"] } ], warning: "Si a un paciente se le recetan medicamentos inhibidores de la ECA (como Enalapril) y su función renal colapsa bruscamente, es un indicador clásico muy fuerte de que tiene estenosis severa en ambas arterias renales." }, types: { title: "Causas y Enfermedades de Origen", intro: "Existen dos enfermedades completamente distintas que bloquean la arteria:", items: ["Aterosclerosis de la Arteria Renal: Causa el 80-90% de los casos. Placas de grasa, colesterol y calcio bloquean la arteria cerca de donde se une a la aorta. Afecta principalmente a hombres y mujeres mayores de 50 años que tienen colesterol alto, fuman o tienen diabetes.", "Displasia Fibromuscular (DFM): Causa el 10-20% de los casos. Es un crecimiento anormal de las células en la pared de la arteria que le da un aspecto de 'collar de cuentas' (rosario) en las radiografías. Afecta predominantemente a mujeres jóvenes y de mediana edad (entre 15 y 50 años), y no está relacionada con el colesterol o el estilo de vida."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista evaluará la estructura arterial y el flujo sanguíneo:", items: ["Auscultación abdominal: A veces el médico puede escuchar un 'soplo' (sonido de zumbido) sobre el abdomen con un estetoscopio, indicando flujo sanguíneo turbulento.", "Ecografía Doppler de las arterias renales: Es el primer paso no invasivo. Utiliza ondas sonoras para ver y medir la velocidad de la sangre en los riñones.", "Angiotomografía Computarizada (Angio-TC) o Angiorresonancia Magnética (ARM): Imágenes 3D muy precisas para localizar estrechamientos y medir el porcentaje de bloqueo.", "Arteriografía Renal: Prueba invasiva que es el 'estándar de oro'. Se inyecta contraste a través de un catéter en la ingle para ver el bloqueo exacto en rayos X (suele hacerse cuando se planea abrir la arteria en el mismo procedimiento)."], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es normalizar la presión, preservar la función del riñón sano y desbloquear la arteria:", subsections: [ { title: "Manejo Farmacológico e Intervenciones", items: ["Medicamentos antihipertensivos: Muchos casos de origen aterosclerótico se manejan primero con medicamentos muy agresivos (IECA, ARA-II, diuréticos, bloqueadores de calcio) y estatinas para el colesterol, reservando la cirugía si fallan.", "Angioplastia transluminal percutánea (con o sin stent): Es el tratamiento preferido, especialmente efectivo y curativo para la Displasia Fibromuscular. Un catéter con un globo en la punta se infla en el estrechamiento para abrir la arteria. En el caso de aterosclerosis, generalmente se deja colocado un tubo de malla de metal (stent) para evitar que se cierre de nuevo.", "Cirugía de derivación (Bypass renal): En casos anatómicos extremadamente complejos o si la angioplastia falla, el cirujano utiliza un vaso sanguíneo sano o tubo sintético para conectar la aorta al riñón, rodeando el bloqueo.", "Dejar de fumar y dieta: Crucial para los pacientes con origen aterosclerótico."] } ], note: "La angioplastia en mujeres jóvenes con Displasia Fibromuscular a menudo 'cura' su hipertensión permanentemente, eliminando la necesidad de pastillas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca una derivación a nefrología o cardiología si:", items: ["Tu presión arterial ha estado siempre bien y de repente se vuelve peligrosamente alta y descontrolada", "Estás tomando múltiples pastillas para la presión y los niveles siguen por encima de 140/90 mmHg constantemente", "Tienes menos de 30 años, eres sano y te detectan hipertensión severa sin antecedentes familiares claros"] } },
'Tumor pituitario (tumor de la hipófisis)' : { intro: "Un tumor pituitario es un crecimiento anormal en la glándula hipófisis (o pituitaria), una pequeña estructura en la base del cerebro encargada de regular gran parte del sistema hormonal del cuerpo.", whatIs: { title: "¿Qué es un Tumor Pituitario?", text: "La mayoría de estos tumores son adenomas benignos (no cancerosos). Sin embargo, pueden causar graves problemas de salud de dos maneras: produciendo un exceso incontrolable de ciertas hormonas (tumores secretores) o creciendo lo suficiente como para presionar el cerebro y los nervios ópticos cercanos (tumores no secretores o macroadenomas)." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos dependen del tamaño del tumor y de las hormonas afectadas:", groups: [ { name: "Síntomas por Presión Física", items: ["Dolor de cabeza crónico", "Pérdida de la visión periférica (visión de túnel) por compresión del nervio óptico", "Movimientos oculares anormales o visión doble"] }, { name: "Síntomas Hormonales", items: ["Secreción de leche por los pezones y pérdida de la menstruación (exceso de prolactina)", "Crecimiento desproporcionado de manos, pies y mandíbula en adultos (Acromegalia por exceso de hormona del crecimiento)", "Aumento de peso en el tronco, cara de luna llena y estrías (Enfermedad de Cushing por exceso de ACTH)", "Fatiga, debilidad e intolerancia al frío (por deficiencia hormonal general)"] } ], warning: "La pérdida repentina de la visión periférica es una señal de alarma que requiere evaluación neurológica inmediata." }, types: { title: "Tipos de Tumores", intro: "Se clasifican por su función y tamaño:", items: ["Microadenomas (menos de 1 cm) y Macroadenomas (1 cm o más)", "Prolactinomas (el tipo secretor más común)", "Tumores no secretores (solo causan problemas al crecer)"], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Casi siempre son esporádicos (sin causa conocida), pero algunos se deben a:", items: ["Mutaciones genéticas heredadas", "Síndromes familiares como la Neoplasia Endocrina Múltiple tipo 1 (NEM 1)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico combina pruebas de imagen y endocrinología:", items: ["Resonancia Magnética (RM) del cerebro (el método más preciso para ver tumores en la silla turca)", "Análisis de sangre y orina (para medir los niveles de todas las hormonas pituitarias)", "Examen de agudeza y campo visual (para revisar si el tumor presiona los nervios ópticos)"], note: "" }, treatment: { title: "Tratamientos", intro: "El manejo es multidisciplinario e individualizado:", subsections: [ { title: "Opciones Terapéuticas", items: ["Observación: Si el tumor es pequeño, no crece y no produce hormonas, solo se vigila con RM periódicas.", "Medicamentos: Fármacos como la Cabergolina pueden encoger los prolactinomas eficazmente sin cirugía.", "Cirugía Transesfenoidal: Extirpación del tumor a través de la nariz y los senos paranasales, sin abrir el cráneo (tratamiento de elección para la mayoría de los tumores que requieren extirpación).", "Radioterapia o Radiocirugía (Gamma Knife): Se usa si el tumor no se puede extirpar por completo o si reaparece tras la cirugía.", "Terapia de Reemplazo Hormonal: Si la glándula pituitaria resulta dañada, el paciente deberá tomar hormonas de por vida."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu médico o endocrinólogo si:", items: ["Sufres dolores de cabeza persistentes acompañados de problemas de visión (especialmente si chocas con objetos a los lados)", "Notas secreción inusual por los pezones o cambios menstruales drásticos", "Experimentas cambios inexplicables en tus rasgos faciales, tamaño del calzado o debilidad profunda"] } },
'Dolor lumbar inespecífico' : { intro: "El dolor lumbar inespecífico es la molestia o tensión en la parte baja de la espalda (zona lumbar) que no se puede atribuir a una patología específica reconocible, como una hernia, fractura o enfermedad inflamatoria. Es la causa más común de dolor de espalda a nivel mundial.", whatIs: { title: "¿Qué es el Dolor Lumbar Inespecífico?", text: "Representa alrededor del 90% de los casos de dolor de espalda. Generalmente, se debe a problemas mecánicos como la distensión de músculos o ligamentos, espasmos musculares o malas posturas. Aunque puede ser intensamente doloroso y limitante, la gran mayoría de los episodios agudos mejoran significativamente en pocas semanas con cuidados básicos." }, symptoms: { title: "Síntomas Comunes", intro: "Las características del dolor mecánico son muy típicas:", groups: [ { name: "Síntomas", items: ["Dolor sordo, tensión o rigidez en la parte baja de la espalda", "Espasmos musculares fuertes que limitan el movimiento (como al intentar agacharse o levantarse de una silla)", "Dolor que empeora con el reposo prolongado y mejora con el movimiento suave", "El dolor generalmente se localiza en la espalda y no baja más allá de la rodilla"] } ], warning: "Los signos de alarma (banderas rojas) incluyen: dolor que no mejora con reposo nocturno, pérdida de peso inexplicable, fiebre, o pérdida del control de la orina o heces." }, causes: { title: "Causas y Factores de Riesgo", intro: "Suele ser multifactorial y relacionado con el estilo de vida:", items: ["Sobreesfuerzo físico o movimientos bruscos de levantamiento de peso", "Malas posturas crónicas (estar sentado muchas horas encorvado)", "Sedentarismo y debilidad de la musculatura del 'core' (abdomen y espalda)", "Sobrepeso u obesidad (aumenta la carga sobre la zona lumbar)", "Estrés psicológico, ansiedad o depresión (aumentan la tensión muscular)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamentalmente un diagnóstico clínico y de exclusión:", items: ["Examen físico e interrogatorio médico detallado", "Las radiografías y las RM generalmente NO son necesarias en las primeras 4-6 semanas a menos que existan señales de alerta o daño nervioso neurológico severo"], note: "Hacer radiografías innecesarias a menudo muestra un desgaste normal por la edad que asusta al paciente, pero que no es la causa del dolor." }, treatment: { title: "Tratamientos", intro: "El tratamiento moderno evita el reposo absoluto y fomenta la recuperación activa:", subsections: [ { title: "Opciones de Manejo", items: ["Mantenerse activo: Continuar con las actividades diarias normales en la medida en que el dolor lo permita (el reposo en cama prolongado empeora la rigidez).", "Fisioterapia y Ejercicio: Terapias de calor/frío, estiramientos y un programa de fortalecimiento muscular (Pilates, natación, yoga) son la mejor prevención a largo plazo.", "Medicamentos: Analgésicos (Paracetamol) o Antiinflamatorios no esteroideos (Ibuprofeno, Naproxeno) durante periodos cortos.", "Manejo del estrés: Terapias cognitivas y técnicas de relajación si el dolor se vuelve crónico (más de 3 meses)."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude al médico de inmediato si tu dolor de espalda está acompañado de:", items: ["Adormecimiento severo o debilidad progresiva en las piernas", "Incapacidad para controlar los intestinos o la vejiga", "Un traumatismo grave reciente (como un accidente de coche o una caída de altura)", "Fiebre alta o pérdida de peso involuntaria"] } },
'Cáncer de la vulva' : { intro: "El cáncer de la vulva es un tipo de tumor maligno poco frecuente que se desarrolla en los genitales externos de la mujer. Generalmente se manifiesta como un bulto, una llaga o úlcera en los labios vulvares que a menudo causa picazón y dolor.", whatIs: { title: "¿Qué es el Cáncer de Vulva?", text: "Es un crecimiento anormal de células cancerosas en la superficie de la vulva. La mayoría de los casos son carcinomas de células escamosas que se desarrollan lentamente a partir de lesiones precancerosas (Neoplasia Intraepitelial Vulvar o VIN). Con un diagnóstico temprano, es una enfermedad altamente tratable y con buen pronóstico." }, symptoms: { title: "Síntomas Comunes", intro: "Cualquier alteración duradera en la piel vulvar debe ser evaluada:", groups: [ { name: "Signos Clínicos", items: ["Picazón intensa y persistente (prurito vulvar) que no mejora con cremas habituales", "Aparición de un bulto, verruga, úlcera o llaga abierta en los labios mayores o menores", "Cambios en el color de la piel (zonas más rojas, blancas, oscuras o engrosadas)", "Sangrado o secreción vaginal que no está relacionada con la menstruación", "Dolor pélvico o sensibilidad extrema, especialmente al orinar o tener relaciones sexuales"] } ], warning: "Muchas mujeres retrasan la consulta médica por vergüenza, asumiendo erróneamente que los síntomas son una simple infección por hongos persistente." }, types: { title: "Tipos de Cáncer Vulvar", intro: "Se clasifican según las células de origen:", items: ["Carcinoma de células escamosas: Representa aproximadamente el 90% de los casos. Se forma en las células delgadas de la superficie de la piel.", "Melanoma vulvar: El segundo más común, se origina en las células que producen el pigmento de la piel. Suele verse como un lunar oscuro.", "Adenocarcinoma y enfermedad de Paget extramamaria (muy raros)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Aunque la causa exacta no siempre es clara, los riesgos aumentan con:", items: ["Edad avanzada (la edad promedio de diagnóstico es a los 65 años)", "Infección persistente por el Virus del Papiloma Humano (VPH), responsable de los casos en mujeres más jóvenes", "Afecciones cutáneas inflamatorias crónicas, particularmente el Liquen Escleroso vulvar", "Antecedentes de condiciones precancerosas de la vulva (VIN) o cáncer de cuello uterino", "Tabaquismo y tener un sistema inmunológico debilitado"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere visualización y toma de muestras:", items: ["Examen pélvico minucioso (inspección visual de toda la zona vulvar)", "Biopsia de la vulva (se adormece la zona y se extrae una pequeña muestra de la lesión para analizarla en el laboratorio; es la única forma de confirmar el cáncer)", "Pruebas de extensión: Resonancia Magnética (RM), Tomografía (TC) o PET para evaluar si el cáncer se ha diseminado a los ganglios linfáticos de la ingle o a otros órganos."], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es principalmente quirúrgico:", subsections: [ { title: "Opciones de Manejo", items: ["Cirugía: Es el pilar del tratamiento. Puede variar desde la escisión local amplia (extirpar el tumor y un margen de tejido sano) hasta una vulvectomía radical parcial o total (extirpación de gran parte de la vulva y ganglios linfáticos inguinofemorales).", "Biopsia del ganglio centinela: Procedimiento para identificar si el primer ganglio linfático al que drena el cáncer está afectado, evitando extirpar todos los ganglios innecesariamente.", "Radioterapia: Se usa con frecuencia para encoger tumores grandes antes de la cirugía o para tratar los ganglios linfáticos afectados.", "Quimioterapia: Generalmente combinada con la radioterapia, o utilizada en estadios avanzados o metástasis."] } ], note: "La vacuna contra el VPH y las revisiones ginecológicas regulares son las mejores medidas preventivas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Programa una cita con tu ginecólogo si notas:", items: ["Cualquier bulto, lesión, úlcera o cambio de color en la piel de tu vulva", "Picazón, dolor o ardor genital que dura más de un mes", "Sangrado inusual después de la menopausia"] } },
'Embarazo múltiple' : { intro: "Un embarazo múltiple es aquel en el que se desarrollan dos o más fetos en el útero de forma simultánea. Los embarazos de gemelos o mellizos son los más comunes, pero también incluyen trillizos o más. Requieren un control obstétrico más exhaustivo debido a los mayores riesgos involucrados.", whatIs: { title: "¿Qué es un Embarazo Múltiple?", text: "Es una condición gestacional que ocurre cuando dos o más óvulos son fertilizados y se implantan en el útero (mellizos dicigóticos o fraternos, los más frecuentes), o cuando un solo óvulo fertilizado se divide en dos o más embriones (gemelos monocigóticos o idénticos). El cuerpo materno debe adaptarse a exigencias fisiológicas extremas para sostener el crecimiento de varios bebés." }, symptoms: { title: "Síntomas y Señales Tempranas", intro: "A menudo, los síntomas típicos del embarazo se presentan de forma muy exagerada:", groups: [ { name: "Signos Clínicos", items: ["Náuseas y vómitos matutinos extremadamente intensos (hiperémesis)", "Aumento de peso más rápido y un útero que crece más grande de lo esperado para las fechas de gestación", "Fatiga extrema y falta de aire temprana", "Movimientos fetales que se sienten en múltiples áreas del abdomen simultáneamente", "Niveles muy elevados de la hormona hCG en los análisis de sangre iniciales"] } ], warning: "Los embarazos múltiples se consideran siempre de 'alto riesgo' obstétrico, independientemente de la salud previa de la madre." }, types: { title: "Tipos y Complicaciones Placentarias", intro: "Es crucial determinar cómo comparten la placenta (corionicidad):", items: ["Bicoriales Biamnióticos: Cada bebé tiene su propia placenta y su propia bolsa amniótica (todos los mellizos y algunos gemelos). Es el tipo más seguro.", "Monocoriales Biamnióticos: Comparten una sola placenta pero tienen bolsas separadas. Presenta riesgos de transfusión de sangre entre los bebés.", "Monocoriales Monoamnióticos: Comparten tanto la placenta como la bolsa. Es el tipo más raro y peligroso debido al riesgo de enredo de los cordones umbilicales."], note: "" }, causes: { title: "Causas y Factores que Aumentan la Probabilidad", intro: "Los embarazos múltiples han aumentado en las últimas décadas debido a:", items: ["Tratamientos de fertilidad e inducción de la ovulación (como la FIV o clomifeno)", "Edad materna avanzada (mujeres mayores de 30 años tienen más probabilidades de liberar varios óvulos de forma natural)", "Antecedentes familiares (especialmente del lado materno para mellizos)", "Etnia y número de embarazos previos"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es vital para la planificación:", items: ["Ecografía (ultrasonido) en el primer trimestre: Es la única forma de confirmar definitivamente cuántos embriones hay y evaluar si comparten o no la placenta (corionicidad).", "Monitoreo cardíaco fetal (escuchar múltiples latidos independientes)"], note: "" }, treatment: { title: "Cuidados y Manejo Prenatal", intro: "El manejo se centra en prevenir la prematuridad y proteger a la madre:", subsections: [ { title: "Estrategias de Seguimiento", items: ["Aumento de visitas prenatales: Ecografías frecuentes (a veces cada 2 semanas) para medir el crecimiento de cada feto y el volumen de líquido amniótico.", "Nutrición y suplementación: Aumento controlado del peso calórico y mayores dosis de ácido fólico, hierro y vitaminas prenatales para evitar la anemia.", "Prevención de complicaciones: Monitoreo estricto de la presión arterial materna (alto riesgo de preeclampsia) y de la glucosa (diabetes gestacional).", "Manejo del parto: Alto riesgo de parto prematuro. Muchos embarazos múltiples terminan en cesárea programada, dependiendo de la posición de los bebés, el número de fetos y si comparten placenta."] } ], note: "El Síndrome de Transfusión Feto-Fetal (STFF) es una complicación grave en gemelos que comparten placenta, requiriendo en ocasiones cirugía láser intrauterina." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Durante un embarazo múltiple, acude a urgencias si presentas:", items: ["Contracciones regulares o dolor pélvico rítmico antes de la semana 37 (riesgo inminente de parto prematuro)", "Pérdida de líquido o sangrado por la vagina", "Dolor de cabeza intenso, alteraciones visuales o hinchazón súbita de cara y manos (signos de preeclampsia severa)"] } },
'Síndrome de sueño y vigilia irregulares' : { intro: "El síndrome de ritmo de sueño-vigilia irregular es un trastorno raro del ritmo circadiano en el cual una persona carece de un ciclo consolidado de sueño nocturno y vigilia diurna. En su lugar, su sueño está fragmentado en múltiples siestas cortas repartidas a lo largo de las 24 horas del día.", whatIs: { title: "¿Qué es este Síndrome?", text: "Normalmente, nuestro reloj biológico interno (regulado por el cerebro y la luz ambiental) nos dicta dormir un bloque largo de noche y estar despiertos de día. En este trastorno, ese 'reloj maestro' falla o las señales ambientales que lo ajustan se han perdido. El resultado es un patrón caótico de sueño y vigilia. Aunque la persona puede dormir un total de horas adecuado en un periodo de 24 horas, la fragmentación constante destruye su calidad de vida y la de sus cuidadores." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas reflejan el caos del reloj interno:", groups: [ { name: "Patrones de Sueño y Comportamiento", items: ["Ausencia de un periodo principal de sueño nocturno (la persona no duerme de forma continua durante la noche)", "Múltiples episodios de sueño (siestas de 1 a 4 horas) distribuidos irregularmente a lo largo del día y la noche", "Insomnio severo durante la noche (despertares prolongados)", "Somnolencia diurna excesiva y letargo", "Empeoramiento de la confusión, desorientación o agitación (especialmente en pacientes con demencia)"] } ], warning: "Este trastorno es una de las principales causas de agotamiento extremo e institucionalización por parte de los cuidadores familiares de ancianos." }, causes: { title: "Causas y Factores de Riesgo", intro: "Rara vez ocurre en personas sanas; casi siempre se asocia a daños cerebrales o falta de estímulos:", items: ["Enfermedades neurodegenerativas (es extremadamente común en etapas avanzadas de la Enfermedad de Alzheimer o Parkinson)", "Daño cerebral adquirido (como traumatismos craneoencefálicos graves o tumores)", "Aislamiento ambiental severo (personas mayores institucionalizadas que pasan todo el día en cama, en interiores con poca iluminación, sin rutina social ni actividad física)", "Discapacidad intelectual grave en niños"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico se basa en el registro de los patrones de sueño:", items: ["Diario de sueño riguroso llevado por un cuidador durante al menos 14 días (mostrará la fragmentación caótica sin un patrón claro)", "Actigrafía: Uso de un dispositivo similar a un reloj de pulsera que registra el movimiento y la luz durante semanas para documentar los periodos de sueño y vigilia objetivamente.", "Evaluación neurológica para confirmar la enfermedad de base"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento no depende tanto de pastillas para dormir, sino de la estructuración rigurosa del entorno (Cronoterapia):", subsections: [ { title: "Opciones de Manejo Ambiental y Médico", items: ["Terapia de Luz Brillante (Fototerapia): Exponer al paciente a luz brillante y natural durante las mañanas y horas tempranas del día para ayudar a 'reiniciar' el reloj biológico.", "Estructuración de Rutinas (Zeitgebers): Establecer horarios fijos e inamovibles para las comidas, el aseo, la actividad social y el ejercicio durante el día.", "Control del entorno nocturno: Mantener la habitación completamente oscura, silenciosa y fresca durante la noche. Limitar estrictamente los ruidos y la interacción social de noche.", "Restricción de siestas: Minimizar el tiempo en cama durante el día para consolidar la necesidad de sueño hacia la noche.", "Suplementos de Melatonina: A veces se administran por la tarde-noche para enviar una señal química de oscuridad al cerebro."] } ], note: "Los medicamentos sedantes tradicionales a menudo empeoran la confusión en ancianos y aumentan el riesgo de caídas, por lo que se evitan." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca orientación de un especialista en medicina del sueño o un geriatra si:", items: ["El patrón de sueño caótico del paciente está causando un estrés insostenible o privación del sueño en los cuidadores familiares", "El paciente presenta episodios de deambulación nocturna peligrosa o agitación severa", "Las medidas básicas de higiene del sueño no logran mejorar la consolidación del descanso nocturno"] } },
'Alcohol en el embarazo' : { intro: "El consumo de alcohol en el embarazo es una de las principales causas prevenibles de defectos congénitos, discapacidades intelectuales y problemas de desarrollo en los recién nacidos, un conjunto de afecciones irreversibles conocidas colectivamente como Trastornos del Espectro Alcohólico Fetal (TEAF).", whatIs: { title: "¿Qué ocurre al consumir Alcohol en el Embarazo?", text: "Cuando una mujer embarazada bebe, el alcohol atraviesa rápidamente la placenta y llega al feto a través del cordón umbilical. El hígado de un feto en desarrollo no puede procesar o descomponer el alcohol, lo que significa que el nivel de alcohol en la sangre del bebé es el mismo, o incluso mayor y más duradero, que en la madre. Este alcohol actúa como un teratógeno tóxico que interfiere con el suministro de oxígeno y nutrientes, alterando el desarrollo normal de los órganos y, críticamente, causando daños permanentes en la estructura del cerebro fetal." }, symptoms: { title: "Consecuencias y Trastornos del Espectro Alcohólico Fetal (TEAF)", intro: "Los efectos duran toda la vida y pueden variar desde leves hasta muy severos:", groups: [ { name: "Anomalías Físicas y del Crecimiento", items: ["Rasgos faciales anormales y distintivos (cabeza pequeña, fisura palpebral corta, labio superior inusualmente liso y delgado)", "Crecimiento físico deficiente (bajo peso y baja estatura) antes y después del nacimiento", "Deformidades en las articulaciones, extremidades y dedos", "Defectos estructurales en el corazón, los riñones o problemas de visión y audición"] }, { name: "Problemas Neurológicos y de Comportamiento", items: ["Discapacidad intelectual profunda y trastornos del aprendizaje (especialmente en matemáticas)", "Microcefalia (cerebro y cabeza de tamaño anormalmente pequeño)", "Problemas severos de comportamiento, hiperactividad, mala memoria y falta de control de impulsos", "Retraso en el habla y el desarrollo del lenguaje", "Dificultad extrema para razonar, juzgar consecuencias o mantener un empleo en la edad adulta"] } ], warning: "Toda organización médica mundial establece una regla clara: No existe ninguna cantidad segura de alcohol, ningún tipo seguro de alcohol (vino, cerveza o licores fuertes) ni ningún momento seguro para beber durante todo el embarazo." }, causes: { title: "Riesgos Adicionales", intro: "Además del daño a largo plazo en el bebé, el consumo de alcohol aumenta directamente el riesgo obstétrico de:", items: ["Aborto espontáneo en el primer trimestre", "Muerte fetal intrauterina (muerte del bebé antes de nacer)", "Parto prematuro y complicaciones placentarias"] }, diagnosis: { title: "¿Cómo se Diagnostica el TEAF?", intro: "No hay una prueba de sangre única para diagnosticarlo tras el nacimiento. El diagnóstico en el niño se basa en:", items: ["Confirmación del historial de exposición prenatal al alcohol por parte de la madre", "Examen físico detallado por un genetista o pediatra identificando los rasgos faciales característicos", "Evaluaciones del crecimiento físico y del perímetro craneal a lo largo del tiempo", "Evaluaciones neuropsicológicas exhaustivas para documentar las deficiencias cognitivas y de comportamiento en la infancia"], note: "Muchos niños con daño cerebral relacionado con el alcohol no presentan los rasgos faciales físicos, lo que hace que sus problemas de comportamiento a menudo se diagnostiquen erróneamente como TDAH o mala conducta." }, treatment: { title: "Tratamientos y Prevención", intro: "El daño cerebral causado por el alcohol es permanente e incurable, por lo que la prevención es la única medida. Si el daño ya existe:", subsections: [ { title: "Manejo y Soporte para el Niño", items: ["Intervención temprana: Servicios de educación especial, terapia del habla, ocupacional y física iniciados lo antes posible para maximizar el potencial del niño.", "Medicamentos: Para manejar síntomas coexistentes como la hiperactividad severa, la ansiedad o la depresión.", "Entrenamiento para padres: Programas especializados para enseñar a las familias estrategias de crianza para manejar los problemas de comportamiento únicos asociados con el daño cerebral por alcohol."] }, { title: "Apoyo a la Madre Gestante", items: ["Intervención médica inmediata para mujeres embarazadas que sufren de trastorno por consumo de alcohol, incluyendo terapia de apoyo, asesoramiento y programas de rehabilitación libres de estigma."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental ser honesto con los proveedores de salud:", items: ["Si estás embarazada o planeas estarlo y te resulta difícil dejar de beber, solicita ayuda médica de inmediato; nunca es tarde para suspender el consumo y mejorar los resultados para el bebé.", "Si sospechas que tu hijo adoptivo o biológico puede tener TEAF debido a la exposición al alcohol durante el embarazo, busca una evaluación con un pediatra especializado en el desarrollo."] } },
'Conducta nasolagrimal obstruido' : { intro: "La obstrucción del conducto nasolagrimal (o dacriostenosis) es una afección ocular muy común en los bebés recién nacidos, en la que el pequeño tubo que drena las lágrimas desde el ojo hasta la nariz está parcial o totalmente bloqueado. Esto provoca que el ojo esté constantemente lloroso o supure legañas, incluso cuando el niño no está llorando.", whatIs: { title: "¿Qué es el Conducto Nasolagrimal Obstruido?", text: "Nuestros ojos producen lágrimas constantemente para mantenerse limpios y lubricados. Estas lágrimas deben drenar hacia un pequeño orificio en la esquina interna del ojo, bajar por el conducto nasolagrimal y vaciarse en la nariz. En aproximadamente el 20% de los recién nacidos, este conducto no se abre completamente al nacer (generalmente por una fina membrana de tejido que bloquea el extremo final). Al no poder drenar, las lágrimas se acumulan y derraman sobre la mejilla, y el líquido estancado en el saco lagrimal se vuelve propenso a infecciones leves." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas suelen aparecer entre las primeras semanas y el primer mes de vida:", groups: [ { name: "Signos Oculares", items: ["Lagrimeo constante y excesivo (epífora) en uno o ambos ojos, pareciendo que el bebé siempre está llorando", "Acumulación de legañas, secreción amarillenta o blanquecina en las pestañas, especialmente notable al despertar (los ojos 'amanecen pegados')", "Leve enrojecimiento de la piel en la esquina interna del ojo debido a la humedad constante y el roce", "El globo ocular (la parte blanca) en sí NO está rojo ni irritado (a diferencia de la conjuntivitis)"] } ], warning: "Si la zona entre el ojo y la nariz se hincha y forma un bulto rojo, caliente y muy doloroso, es una infección aguda del saco lagrimal (dacriocistitis) que requiere antibióticos orales de urgencia." }, causes: { title: "Causas Frecuentes", intro: "Dependiendo de la edad, la causa varía:", items: ["Congénita (en bebés): Falta de desarrollo completo o apertura de la válvula de Hasner al final del conducto al nacer. Es, con diferencia, la causa más común.", "En adultos: Puede deberse al envejecimiento (los conductos se estrechan), traumatismos faciales severos (fracturas de nariz), infecciones crónicas de los senos paranasales, pólipos nasales, o tumores."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El pediatra o el oftalmólogo lo diagnostican fácilmente en el consultorio:", items: ["Examen físico clínico visual (se observa el lagrimeo y la secreción sin ojo rojo)", "Prueba de desaparición de la fluoresceína: Se coloca una gota de colorante especial en el ojo; si el conducto está sano, el colorante desaparecerá hacia la nariz en minutos. Si está obstruido, el colorante permanecerá acumulado en el ojo."], note: "Es vital diferenciar esta obstrucción de otras afecciones raras pero graves, como el glaucoma congénito." }, treatment: { title: "Tratamientos", intro: "El pronóstico es excelente; más del 90% de los casos en bebés se resuelven espontáneamente antes del primer año de vida:", subsections: [ { title: "Manejo Conservador y Procedimientos", items: ["Masaje del saco lagrimal (Técnica de Crigler): Los padres deben realizar un masaje firme, presionando con el dedo limpio desde la esquina interna del ojo hacia abajo, hacia la nariz, varias veces al día. Esto aumenta la presión hidrostática y ayuda a reventar la membrana obstructiva.", "Limpieza constante: Limpiar suavemente las secreciones de los ojos con una gasa estéril humedecida en agua tibia o suero fisiológico.", "Gotas antibióticas: Recetadas por el médico SOLO si hay una secreción purulenta espesa que indique una infección bacteriana sobreagregada (las gotas no curan la obstrucción, solo la infección secundaria).", "Sondaje quirúrgico: Si la obstrucción persiste más allá de los 12 a 15 meses de edad, un oftalmólogo pasa una pequeña y fina sonda de metal por el conducto bajo anestesia general breve para abrirlo físicamente. Es un procedimiento rápido y altamente exitoso."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta con el pediatra o acude a urgencias si el bebé presenta:", items: ["El ojo se pone completamente rojo e irritado (signo de conjuntivitis)", "Un bulto visiblemente hinchado, enrojecido y doloroso cerca de la esquina interna del ojo", "Fiebre y letargo acompañados de síntomas oculares"] } },
'Pigmentación severa dental' : { intro: "La pigmentación severa dental es una alteración profunda del color natural de los dientes, manifestándose con manchas oscuras, amarillas o grisáceas que afectan significativamente la estética de la sonrisa.", whatIs: { title: "¿Qué es la Pigmentación Dental?", text: "Es el cambio de coloración del esmalte o la dentina (la capa interna del diente). A diferencia de las manchas superficiales por alimentos, las pigmentaciones severas suelen estar integradas en la estructura misma del diente, haciéndolas difíciles de eliminar con un simple cepillado o limpieza básica." }, symptoms: { title: "Síntomas y Signos", intro: "El principal síntoma es visual:", groups: [ { name: "Características Visuales", items: ["Manchas marrones, negras, amarillas o grises en uno o varios dientes", "Decoloración en forma de bandas o rayas horizontales (típico de medicamentos)", "Zonas blancas opacas o moteadas (típico de exceso de flúor)", "Pérdida del brillo natural y oscurecimiento general de la pieza dental"] } ], warning: "Un solo diente que se oscurece repentinamente de color gris o negro tras un golpe suele indicar que el nervio del diente ha muerto (necrosis pulpar) y requiere tratamiento de conducto." }, types: { title: "Tipos de Manchas", intro: "Se clasifican según la profundidad y el origen del color:", items: ["Pigmentación Extrínseca: Ocurre en la capa exterior (esmalte). Es causada por sustancias que tiñen desde afuera (humo, pigmentos de comida).", "Pigmentación Intrínseca: Ocurre en el interior del diente (dentina). Es causada por alteraciones durante la formación del diente o absorción de sustancias por la sangre."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas de las manchas intrínsecas severas incluyen:", items: ["Uso de antibióticos como la tetraciclina en la infancia (durante la formación de los dientes) o por la madre en el embarazo", "Fluorosis dental (consumo excesivo de flúor en el agua durante los primeros años de vida)", "Traumatismos dentales que causan sangrado interno en el diente", "Envejecimiento natural (el esmalte se desgasta y la dentina subyacente, que es más amarilla, se hace más visible)", "Genética y afecciones como la amelogénesis imperfecta"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El odontólogo realizará una evaluación clínica:", items: ["Examen visual directo para determinar el tipo, profundidad y patrón de la mancha", "Transiluminación o luz ultravioleta para ver grietas o alteraciones estructurales", "Radiografías periapicales (para descartar daño en la raíz o nervio muerto)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento depende totalmente de si la mancha es externa o interna:", subsections: [ { title: "Opciones Estéticas y Clínicas", items: ["Limpieza dental profesional (profilaxis con ultrasonido o aeropulidor) para eliminar manchas extrínsecas por tabaco o café.", "Blanqueamiento dental profesional (con peróxido de hidrógeno o carbamida activado por luz) para aclarar manchas más profundas.", "Blanqueamiento interno: Un procedimiento especial para dientes con tratamiento de conducto que se han oscurecido por dentro.", "Microabrasión del esmalte: Pulido químico y mecánico para eliminar defectos superficiales como la fluorosis leve.", "Carillas de porcelana o resina: Láminas finas que se adhieren sobre el diente para ocultar permanentemente manchas intrínsecas muy oscuras (como las de tetraciclina) que no responden al blanqueamiento.", "Coronas dentales: Fundas completas si el diente además de manchado está muy debilitado o roto."] } ], note: "Los tratamientos caseros o pastas blanqueadoras abrasivas pueden empeorar el problema al desgastar el esmalte de forma irreversible." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un dentista si:", items: ["Las manchas dentales afectan gravemente tu autoestima y no responden a una limpieza regular", "Un solo diente cambia repentinamente de color hacia un tono gris oscuro o negro", "Notas manchas acompañadas de dolor, sensibilidad extrema o fosas en el esmalte"] } },
'Deslizamiento de la epífisis capital femoral' : { intro: "El deslizamiento de la epífisis capital femoral (DECF) es un trastorno de la articulación de la cadera que afecta a los adolescentes, en el cual la cabeza ('bola') del hueso del muslo (fémur) se desliza hacia atrás en la placa de crecimiento.", whatIs: { title: "¿Qué es el DECF?", text: "Durante la adolescencia, los huesos crecen a través de zonas de cartílago blando llamadas placas de crecimiento. En el DECF, la placa de crecimiento en la parte superior del fémur se debilita. Debido al peso y las fuerzas biomecánicas, la 'cabeza' redondeada del fémur se desliza de su 'cuello', de forma similar a como una bola de helado se resbala de su cono. Es una emergencia ortopédica." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden desarrollarse lentamente a lo largo de meses o de forma súbita tras una caída menor:", groups: [ { name: "Signos Clínicos", items: ["Cojera al caminar, a menudo sin antecedentes de un golpe o trauma grave", "Dolor sordo y constante en la cadera, la ingle, el muslo o, curiosamente, en la rodilla (dolor referido, muy común que confunda el diagnóstico)", "La pierna afectada a menudo parece girar hacia afuera (rotación externa) al caminar o estar acostado", "Dificultad o incapacidad total para soportar el peso sobre la pierna afectada (en casos graves)", "La pierna afectada puede parecer ligeramente más corta que la sana"] } ], warning: "Un adolescente con dolor de rodilla inexplicable y cojera siempre debe ser evaluado de la cadera para descartar esta afección." }, types: { title: "Tipos de Deslizamiento", intro: "Se clasifica según la capacidad del paciente para caminar:", items: ["DECF Estable: El adolescente aún puede caminar o apoyar peso sobre la pierna, con o sin muletas (es el tipo más común).", "DECF Inestable: El dolor es tan severo que es absolutamente imposible apoyar peso sobre la pierna afectada. Este tipo conlleva un riesgo altísimo de cortar el suministro de sangre a la cabeza del fémur (necrosis avascular)."], note: "Hasta en un 40% de los casos, la cadera opuesta también puede desarrollar un deslizamiento en el futuro." }, causes: { title: "Causas y Factores de Riesgo", intro: "No se conoce la causa exacta, pero influyen fuertemente las hormonas y la biomecánica:", items: ["Obesidad o sobrepeso significativo infantil (el mayor factor de riesgo, ya que añade un estrés mecánico inmenso a la placa de crecimiento blanda)", "Rápidos estirones de crecimiento durante la pubertad", "Trastornos endocrinos (hipotiroidismo, problemas de la hormona del crecimiento)", "Antecedentes familiares de problemas de cadera", "Mayor incidencia en varones que en mujeres, típicamente entre los 10 y 16 años"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es crítico para evitar la deformidad permanente de la cadera:", items: ["Examen físico minucioso (el médico notará pérdida del movimiento de rotación interna de la cadera)", "Radiografías de la pelvis y caderas (proyección anteroposterior y proyección en posición de 'ancas de rana' para ver claramente cómo la cabeza del fémur se ha salido de su eje)", "Resonancia Magnética (RM) (solo se pide en etapas muy tempranas o 'predeslizamiento' cuando la radiografía parece normal pero hay mucho dolor)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es siempre quirúrgico y debe realizarse lo antes posible:", subsections: [ { title: "Intervenciones Quirúrgicas", items: ["Prohibición absoluta de carga de peso: Apenas se sospeche, el paciente debe usar muletas o silla de ruedas de inmediato para evitar que se deslice más.", "Fijación In Situ: El cirujano inserta uno o dos tornillos de metal grandes a través del cuello del fémur y hacia la cabeza femoral para fijar el hueso en su lugar e impedir que siga deslizándose. (Tratamiento estándar para casos estables).", "Reducción abierta: Para casos inestables y severos, el cirujano puede necesitar abrir la cadera, alinear el hueso en su posición original cuidadosamente y luego fijarlo con tornillos.", "Cirugía preventiva en la otra cadera: A veces, el cirujano insertará un tornillo en la cadera sana de forma preventiva si los riesgos de que le ocurra lo mismo son muy altos (como en trastornos endocrinos)."] } ], note: "Retrasar la cirugía aumenta el riesgo de artritis temprana severa de cadera y muerte del tejido óseo (necrosis avascular)." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Lleva a tu hijo adolescente a urgencias o al ortopedista pediátrico inmediatamente si:", items: ["Comienza a cojear sin razón aparente", "Se queja de dolor persistente en la ingle, el muslo o la rodilla que empeora con la actividad", "De repente es incapaz de ponerse de pie o caminar sobre una de sus piernas"] } },
'Cálculos vesicales' : { intro: "Los cálculos vesicales, o piedras en la vejiga, son masas duras de minerales que se forman dentro de la vejiga urinaria. Suelen ocurrir cuando la vejiga no logra vaciarse por completo de orina.", whatIs: { title: "¿Qué son los Cálculos Vesicales?", text: "La orina contiene diversos minerales disueltos. Si la orina se queda estancada en la vejiga, se concentra demasiado y estos minerales (como el ácido úrico o el oxalato de calcio) cristalizan y se unen formando 'piedras'. Pueden ser tan pequeños como un grano de arena o tan grandes como una pelota de golf. Son mucho más comunes en hombres mayores que en mujeres." }, symptoms: { title: "Síntomas Comunes", intro: "Curiosamente, algunas piedras pequeñas no causan síntomas. Cuando irritan la pared de la vejiga o bloquean la salida de la orina, provocan:", groups: [ { name: "Síntomas Urinarios y Dolor", items: ["Dolor sordo y constante o presión en la parte baja del abdomen (zona pélvica)", "Dolor o ardor agudo al orinar (disuria)", "Micción frecuente, especialmente despertarse varias veces por la noche para orinar", "Dificultad para comenzar a orinar, flujo de orina débil, o flujo que se detiene y comienza bruscamente", "Sangre en la orina (hematuria), que puede hacer que la orina se vea de color rosa, rojo o marrón", "Orina inusualmente turbia o de color muy oscuro"] } ], warning: "Si una piedra se atasca completamente en el cuello de la vejiga o en la uretra, causando la incapacidad total para orinar (retención urinaria aguda), es una urgencia médica dolorosa extrema." }, types: { title: "Composición de los Cálculos", intro: "Los cálculos pueden estar formados por diferentes minerales:", items: ["Ácido úrico (el tipo más común de cálculo vesical puro, asociado a orina ácida y dietas altas en proteínas)", "Estruvita (frecuentemente causados por infecciones urinarias bacterianas crónicas)", "Oxalato o fosfato de calcio (más comunes en el riñón, pero pueden bajar a la vejiga y crecer allí)"], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Cualquier afección que impida el vaciado de la vejiga fomenta la formación de piedras:", items: ["Agrandamiento de la próstata (Hiperplasia Prostática Benigna - HPB), que es la causa más frecuente en hombres mayores, ya que exprime la uretra y atrapa orina.", "Vejiga neurogénica (daño a los nervios que controlan la vejiga debido a lesiones en la médula espinal, derrames cerebrales o diabetes).", "Inflamación o infección crónica (cistitis), que altera la química de la orina.", "Uso de sondas vesicales permanentes o cuerpos extraños médicos (como mallas quirúrgicas migradas).", "Divertículos vesicales (pequeñas bolsas en la pared de la vejiga donde la orina se estanca)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El urólogo utilizará imágenes para ver las piedras:", items: ["Ecografía de la vejiga (prueba inicial rápida y sin radiación que muestra las piedras y la cantidad de orina retenida)", "Tomografía Computarizada (TC) de abdomen y pelvis sin contraste (la prueba más sensible, detecta piedras de cualquier tamaño y composición)", "Radiografías simples (KUB), aunque algunos cálculos (como los de ácido úrico) no se ven en los rayos X", "Cistoscopia (introducir una cámara pequeña a través de la uretra para ver directamente las piedras y la pared de la vejiga)", "Análisis de orina (para detectar infecciones microscópicas y cristales minerales)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere romper o extraer las piedras y solucionar el problema que causó que la orina se estancara:", subsections: [ { title: "Opciones de Eliminación", items: ["Aumento del consumo de agua: Solo es útil si las piedras son extremadamente pequeñas (como arenilla) para ayudar a expulsarlas.", "Cistolitotricia (Romper las piedras): El tratamiento más común. El cirujano inserta un cistoscopio a través de la uretra y utiliza un láser, ultrasonido o un dispositivo mecánico para triturar la piedra en fragmentos pequeños y luego lavarlos hacia afuera. No requiere cortes en la piel.", "Cirugía Abierta (Cistolitotomía): Se hace una incisión en la parte baja del abdomen y en la vejiga. Se reserva para piedras gigantes o cuando hay que reparar la vejiga simultáneamente.", "Tratamiento de la causa subyacente: Si el paciente tiene una próstata agrandada (HPB), el cirujano a menudo operará la próstata (ej. resección transuretral de la próstata - RTUP) durante la misma cirugía de extracción de cálculos para evitar que se formen de nuevo."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o al urólogo inmediatamente si:", items: ["No puedes orinar a pesar de tener muchas ganas (retención urinaria)", "Ves sangre roja brillante en tu orina", "Tienes un dolor pélvico severo o dolor intenso al intentar orinar"] } },
'Acné quístico' : { intro: "El acné quístico (o acné noduloquístico) es la forma más severa, profunda e inflamatoria de acné. Se caracteriza por la aparición de nódulos y quistes grandes, dolorosos y llenos de pus debajo de la superficie de la piel, y tiene un riesgo extremadamente alto de dejar cicatrices permanentes.", whatIs: { title: "¿Qué es el Acné Quístico?", text: "Mientras que el acné normal ocurre cerca de la superficie (espinillas o puntos negros), el acné quístico ocurre cuando una infección profunda en el folículo piloso hace que el poro se rompa bajo la piel. Esto desencadena una reacción inflamatoria masiva, formando nódulos duros o quistes llenos de líquido que pueden tardar semanas o meses en sanar. Es una afección médica crónica, no un simple problema de higiene." }, symptoms: { title: "Síntomas y Características", intro: "Las lesiones son inconfundibles por su severidad:", groups: [ { name: "Tipos de Lesiones", items: ["Nódulos: Bultos grandes, duros y dolorosos profundamente incrustados bajo la piel.", "Quistes: Protuberancias grandes, blandas y llenas de pus (fluctuantes), extremadamente sensibles al roce o la presión.", "Enrojecimiento intenso (eritema) o inflamación que se extiende más allá del área del grano.", "Cicatrices evidentes (hoyos profundos, cicatrices hundidas o cicatrices engrosadas tipo queloide) a medida que las lesiones antiguas sanan.", "Afecta principalmente la cara, pero también es común en la espalda, el pecho, los hombros y la línea de la mandíbula."] } ], warning: "Bajo ninguna circunstancia se debe intentar 'reventar' o exprimir un quiste de acné. La infección es demasiado profunda; apretarlo empujará las bacterias más profundamente, empeorando la inflamación y garantizando una cicatriz irreversible." }, types: { title: "Variantes Severas", intro: "Existen formas específicas de acné grave:", items: ["Acné Conglobata: Una forma altamente inflamatoria donde múltiples nódulos quísticos se conectan entre sí bajo la piel, formando canales (fístulas).", "Acné Fulminante: Una forma abrupta, rara y muy destructiva que aparece junto con fiebre, dolor en las articulaciones y llagas sangrantes (requiere esteroides de urgencia)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "No es causado por mala higiene, comida grasosa o chocolate. Sus raíces son biológicas y hormonales:", items: ["Hormonas andrógenas: Un exceso de andrógenos (como durante la pubertad) estimula las glándulas sebáceas para que produzcan cantidades masivas de sebo (aceite).", "Células muertas de la piel: No se desprenden correctamente y obstruyen el poro profundamente.", "Bacterias: La bacteria Cutibacterium acnes (C. acnes) queda atrapada en el poro sin oxígeno, donde se multiplica rápidamente y causa la inflamación severa.", "Genética: Tener padres con antecedentes de acné quístico severo es el mayor factor de predicción.", "Síndrome de Ovario Poliquístico (SOP) en mujeres adultas."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un dermatólogo lo diagnostica visualmente:", items: ["Examen físico de la piel (cara, pecho, espalda)", "Historial clínico para evaluar tratamientos previos fallidos, el ciclo menstrual en mujeres y el uso de medicamentos", "En mujeres con otros síntomas (como vello facial excesivo o reglas irregulares), se pueden pedir análisis de sangre para evaluar niveles hormonales o descartar SOP"], note: "Las cremas de venta libre o rutinas cosméticas NO curan el acné quístico; requiere medicamentos recetados sistémicos." }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere un enfoque médico agresivo desde el interior del cuerpo:", subsections: [ { title: "Opciones Dermatológicas Recetadas", items: ["Isotretinoína oral (Accutane/Roaccutan): Es el tratamiento más efectivo y la única 'cura' potencial para el acné quístico severo. Se toma durante varios meses. Reduce el tamaño de las glándulas sebáceas de forma permanente. Requiere controles de sangre estrictos y está absolutamente contraindicado en el embarazo debido a graves defectos de nacimiento.", "Antibióticos orales: (Doxiciclina, Minociclina) Se usan temporalmente para reducir rápidamente la inflamación dolorosa y matar bacterias antes de iniciar otros tratamientos.", "Terapia hormonal (mujeres): Píldoras anticonceptivas específicas o Espironolactona (un antiandrógeno) para bloquear las hormonas que causan la producción de aceite.", "Inyecciones de corticosteroides: El dermatólogo inyecta un esteroide diluido directamente en un quiste gigante y doloroso. La inflamación y el dolor desaparecen casi milagrosamente en 24-48 horas, evitando cicatrices inmediatas.", "Tratamiento de cicatrices: Láser, dermoabrasión, peelings químicos o microagujas, pero SOLO después de que el acné activo haya sido curado completamente."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide cita con un dermatólogo de inmediato si:", items: ["Tienes bultos rojos grandes, duros y dolorosos debajo de la piel que no tienen una 'cabeza' blanca", "Sientes que el acné está dejando marcas hundidas u oscuras en tu piel", "El estado de tu piel te causa una angustia psicológica severa, depresión o evitas salir de casa (aislamiento social)"] } },
'Esguince cervical' : { intro: "El esguince cervical, comúnmente conocido como 'latigazo cervical' (whiplash), es una lesión de los músculos y ligamentos del cuello causada por un movimiento brusco y violento de la cabeza hacia atrás (hiperextensión) y luego hacia adelante (hiperflexión).", whatIs: { title: "¿Qué es un Esguince Cervical?", text: "La columna cervical (cuello) es muy flexible pero frágil. Cuando sufre una fuerza de aceleración y desaceleración rápida (como cuando un coche es golpeado por detrás), los ligamentos, músculos, discos y nervios del cuello se estiran más allá de sus límites normales. Esto genera microdesgarros e inflamación en los tejidos blandos que sostienen la cabeza." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden no aparecer inmediatamente después del accidente; a menudo empeoran a las 24-48 horas:", groups: [ { name: "Síntomas Musculoesqueléticos", items: ["Dolor de cuello, rigidez extrema y dificultad severa para mover la cabeza de lado a lado o arriba y abajo", "Dolor sordo y constante que empeora con el movimiento del cuello", "Dolor, tensión o nudos musculares (espasmos) en los hombros, la parte superior de la espalda o los brazos"] }, { name: "Síntomas Neurológicos y Generales", items: ["Dolores de cabeza, frecuentemente originados en la base del cráneo y que irradian hacia la frente", "Sensación de hormigueo o entumecimiento en los brazos o manos (si un nervio se inflamó)", "Mareos temporales, fatiga y alteraciones del sueño", "Problemas de concentración, irritabilidad o zumbidos en los oídos (acúfenos) en casos severos asociados a concusión leve"] } ], warning: "La debilidad profunda y repentina en los brazos, dificultad para caminar o la pérdida de control de esfínteres tras un accidente indica un daño severo a la médula espinal, una emergencia crítica." }, types: { title: "Clasificación de Quebec (Grados de Gravedad)", intro: "El latigazo cervical se clasifica clínicamente:", items: ["Grado 0: No hay quejas de dolor ni signos físicos.", "Grado I: Quejas de dolor, rigidez o sensibilidad en el cuello, pero no hay signos físicos obvios para el médico.", "Grado II: Quejas de dolor y el médico encuentra disminución en el rango de movimiento o puntos de sensibilidad musculares claros.", "Grado III: Dolor en el cuello acompañado de signos neurológicos (reflejos débiles, falta de fuerza o sensibilidad en los brazos).", "Grado IV: Quejas en el cuello con evidencia de fractura o dislocación vertebral (una urgencia traumatológica mayor)."], note: "" }, causes: { title: "Causas Frecuentes", intro: "Cualquier impacto brusco puede causarlo, pero los más comunes son:", items: ["Accidentes automovilísticos (especialmente choques por alcance trasero)", "Impactos en deportes de contacto (fútbol americano, rugby, artes marciales)", "Agresiones físicas (como ser sacudido violentamente o golpeado en la cabeza)", "Caídas significativas (por ejemplo, caer de una bicicleta o caballo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El objetivo del diagnóstico es descartar fracturas graves y evaluar los tejidos blandos:", items: ["Evaluación neurológica y física detallada en urgencias (palpación, pruebas de fuerza, sensibilidad y reflejos)", "Radiografías simples de la columna cervical (esenciales para descartar fracturas de las vértebras o dislocaciones, y a menudo muestran 'pérdida de la curvatura normal' del cuello debido al espasmo muscular)", "Tomografía Computarizada (TC) (si hay sospecha de fracturas pequeñas que no se ven en los rayos X)", "Resonancia Magnética (RM) (solo se usa si hay síntomas neurológicos, como hormigueo en los brazos, para ver si hay hernias de disco, ligamentos rotos o compresión de la médula espinal)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo moderno es controlar el dolor y mantener el movimiento, no el reposo estricto prolongado:", subsections: [ { title: "Manejo y Recuperación", items: ["Movimiento Temprano Activo: A diferencia de años anteriores, ya NO se recomienda el uso prolongado de collarines ortopédicos (rígidos o blandos), ya que inmovilizar el cuello causa atrofia muscular y rigidez crónica. Se fomenta realizar estiramientos suaves lo antes posible.", "Control del dolor e inflamación: Analgésicos de venta libre (Ibuprofeno, Paracetamol), y en la fase inicial aguda, relajantes musculares recetados (solo por un par de días para poder dormir).", "Fisioterapia: El tratamiento más efectivo. Ejercicios guiados para restaurar el rango de movimiento, terapia manual, corrección postural y fortalecimiento.", "Terapia térmica: Aplicación de hielo durante las primeras 24-48 horas para reducir la hinchazón, seguida de calor húmedo para relajar los espasmos musculares profundos.", "Inyecciones: En casos de dolor crónico (que dura más de meses), se pueden usar inyecciones de puntos gatillo o bloqueos nerviosos temporales."] } ], note: "La mayoría de los esguinces cervicales leves se resuelven en 4 a 6 semanas, pero un porcentaje de personas puede experimentar dolor crónico durante meses o años (síndrome del latigazo cervical crónico)." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias inmediatamente después del impacto si:", items: ["El dolor de cuello es severo e incapacitante de inmediato", "Sientes entumecimiento, 'corriente eléctrica' o pérdida notable de fuerza en los hombros, brazos o manos", "Estás confundido, mareado, o perdiste el conocimiento por un momento tras el golpe"] } },
'Infección de la piel por bacterias' : { intro: "Las infecciones bacterianas de la piel ocurren cuando bacterias patógenas, comúnmente estafilococos o estreptococos, logran penetrar la barrera protectora de la piel a través de un corte, un rasguño, la picadura de un insecto o una herida abierta, proliferando y causando daño e inflamación en los tejidos cutáneos.", whatIs: { title: "¿Qué son las Infecciones Cutáneas Bacterianas?", text: "La piel sana está cubierta de bacterias (flora normal) que no causan daño. Sin embargo, cuando la piel se rompe o el sistema inmunológico está debilitado, estas u otras bacterias oportunistas pueden entrar en los tejidos. Pueden causar desde infecciones superficiales menores y molestas (como llagas o granos) hasta infecciones profundas en el tejido adiposo o muscular que amenazan la vida si las bacterias ingresan al torrente sanguíneo (septicemia)." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos dependen del tipo y profundidad de la infección, pero los generales incluyen:", groups: [ { name: "Síntomas Locales (en la Piel)", items: ["Enrojecimiento que se expande rápidamente en forma de mancha o área inflamada", "Hinchazón (edema) y piel que se siente anormalmente caliente al tacto", "Dolor y sensibilidad al rozar la zona afectada", "Aparición de pus (ampollas purulentas, pústulas o llagas que supuran un líquido amarillento/verdoso)", "Costras de color amarillo miel o amarronadas (muy característico del impétigo)"] }, { name: "Síntomas de Gravedad Sistémica", items: ["Fiebre y escalofríos", "Dolor generalizado y debilidad", "Rayas rojas que se extienden desde el área infectada hacia el corazón (signo de infección de los vasos linfáticos o linfangitis)"] } ], warning: "Un área roja y caliente en la piel que crece rápidamente día a día acompañada de fiebre es probablemente una celulitis, que requiere atención médica con antibióticos urgentes." }, types: { title: "Tipos Frecuentes de Infecciones Bacterianas", intro: "Se clasifican según la profundidad y estructura afectada:", items: ["Impétigo: Muy contagioso y superficial, común en niños. Provoca llagas rojas alrededor de la nariz y boca que se rompen y forman costras de color miel.", "Celulitis: Infección de las capas profundas de la piel y la grasa subcutánea. Se ve como una zona roja, hinchada y caliente, comúnmente en las piernas.", "Erisipela: Infección de las capas superiores con bordes muy definidos y elevados, a menudo en el rostro o piernas.", "Foliculitis, Forúnculos y Ántrax: Infecciones localizadas en los folículos pilosos. Comienzan como pequeños bultos rojos, creciendo hasta formar dolorosos abscesos llenos de pus.", "Fascitis Necrotizante (infección rara y grave): Destrucción extremadamente rápida de los tejidos profundos bajo la piel."], note: "El Staphylococcus aureus resistente a la meticilina (SARM) es una 'superbacteria' común hoy en día que causa infecciones de piel difíciles de tratar." }, causes: { title: "Causas y Factores de Riesgo", intro: "Bacterias comunes (*Staphylococcus aureus* o *Streptococcus pyogenes*) entran por brechas de defensa por:", items: ["Lesiones en la piel: Cortes, raspaduras, quemaduras, úlceras o heridas quirúrgicas recientes.", "Afecciones cutáneas crónicas: Eczema, psoriasis, pie de atleta o acné que provocan grietas microscópicas en la piel.", "Enfermedades subyacentes: Diabetes (altera la circulación y la inmunidad de la piel), mala circulación en las piernas, o inmunidad debilitada (VIH, quimioterapia).", "Entornos concurridos: Guarderías, gimnasios o cuarteles donde se comparte equipo, toallas o hay contacto de piel a piel (riesgo de transmisión de estafilococos)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico, observando la apariencia de la lesión:", items: ["Examen físico directo de la piel infectada", "Cultivo bacteriano mediante un hisopo (frotar la herida o el pus) para enviar al laboratorio y saber exactamente qué bacteria es y qué antibiótico la matará de forma efectiva (Antibiograma)", "Análisis de sangre y hemocultivos (si se sospecha que la infección es grave y ha pasado al torrente sanguíneo)", "Ecografía de partes blandas (si el médico sospecha de un absceso profundo oculto que necesita ser drenado)"], note: "" }, treatment: { title: "Tratamientos", intro: "El pilar del tratamiento son los antibióticos y el control local:", subsections: [ { title: "Opciones de Manejo", items: ["Antibióticos tópicos (Mupirocina, Ácido Fusídico): Cremas o ungüentos recetados para infecciones superficiales y localizadas como el impétigo leve.", "Antibióticos orales (Cefalexina, Amoxicilina, Doxiciclina para casos de SARM): Pastillas para infecciones más profundas como la celulitis extensa o múltiples forúnculos.", "Antibióticos intravenosos: Ingreso hospitalario necesario para infecciones severas, rápida progresión, afectación sistémica (fiebre) o infecciones cerca del ojo.", "Drenaje quirúrgico de abscesos (Incisión y drenaje): Si hay una bolsa de pus (forúnculo grande o ántrax), los antibióticos no penetrarán la pared del quiste; el médico debe hacer un corte bajo anestesia local para vaciar el pus.", "Cuidados de apoyo: Mantener el área limpia, cubrir heridas abiertas, aplicar compresas tibias en abscesos para ayudar a que 'maduren' y elevar la extremidad si hay celulitis para reducir la hinchazón."] } ], note: "NUNCA debes apretar o intentar reventar un forúnculo en casa, especialmente en el área facial (triángulo de la muerte), ya que puedes empujar la infección hacia el cerebro o la sangre." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a emergencias o a un médico en el mismo día si:", items: ["Tienes una mancha roja, dolorosa e hinchada en la piel que claramente se está expandiendo o agrandando de tamaño", "La infección está acompañada de fiebre alta, escalofríos, confusión o dolor insoportable", "La infección de la piel está cerca o alrededor de tus ojos (celulitis periorbitaria)", "Aparecen líneas o rayas rojas que suben desde la zona infectada hacia el resto del cuerpo"] } },
'Hipertensión arterial sistémica' : { intro: "La hipertensión arterial sistémica es una enfermedad crónica en la cual la fuerza que ejerce la sangre contra las paredes de las arterias del cuerpo es persistentemente demasiado alta. A menudo se le llama el 'asesino silencioso' porque rara vez causa síntomas evidentes hasta que ya ha dañado órganos vitales de manera irreversible.", whatIs: { title: "¿Qué es la Hipertensión Arterial?", text: "La presión arterial se mide con dos números: el superior (sistólica) indica la presión cuando el corazón late, y el inferior (diastólica) indica la presión cuando el corazón descansa entre latidos. Se considera presión arterial alta (hipertensión) cuando las lecturas se mantienen de manera sostenida por encima de 130/80 mmHg (según las pautas de la AHA) o 140/90 mmHg (según otras directrices). Esta presión alta constante actúa como un desgaste mecánico implacable en el interior de los vasos sanguíneos de todo el cuerpo, volviéndolos rígidos o propensos a romperse." }, symptoms: { title: "Síntomas Comunes", intro: "Es fundamental comprender que la hipertensión en sí no causa síntomas en la inmensa mayoría de las personas durante años. Sin embargo, en una crisis hipertensiva extrema pueden aparecer:", groups: [ { name: "Signos de Crisis Hipertensiva (Emergencia)", items: ["Dolor de cabeza muy intenso y pulsátil", "Sangrados nasales espontáneos y difíciles de detener", "Dificultad repentina para respirar o dolor en el pecho", "Mareos, zumbido en los oídos (acúfenos) severo o visión borrosa", "Confusión mental profunda"] } ], warning: "No puedes sentir que tu presión arterial es alta. La única manera de saberlo es midiéndola regularmente. Ignorar la hipertensión conduce a infartos, derrames cerebrales, insuficiencia renal y ceguera." }, types: { title: "Tipos de Hipertensión", intro: "Se divide médicamente según su causa de origen:", items: ["Hipertensión Primaria (Esencial): Representa el 90-95% de todos los casos en adultos. No tiene una única causa médica identificable y se desarrolla gradualmente a lo largo de los años debido a la combinación de genética, edad y factores del estilo de vida.", "Hipertensión Secundaria: Aparece repentinamente y tiende a causar lecturas más altas. Está causada por una condición médica oculta específica, como apnea del sueño, problemas en los riñones (enfermedad renal crónica, estenosis de la arteria renal), tumores en las glándulas suprarrenales (feocromocitoma), problemas de tiroides, o medicamentos (pastillas anticonceptivas, descongestionantes, analgésicos como el ibuprofeno, o drogas ilícitas)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "En la hipertensión esencial (primaria), el riesgo aumenta drásticamente por:", items: ["Edad y Herencia (los vasos sanguíneos pierden elasticidad con la edad y tener familiares con hipertensión aumenta el riesgo genéticamente)", "Sobrepeso u obesidad (requiere más sangre para oxigenar tejidos, aumentando la presión del bombeo)", "Dieta rica en sal (sodio), ya que hace que el cuerpo retenga líquido excesivo, aumentando el volumen de sangre", "Falta de actividad física (sedentarismo)", "Consumo excesivo de alcohol (más de 1-2 copas al día debilita el corazón)", "Consumo de tabaco (daña las paredes arteriales de inmediato)", "Estrés crónico severo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico nunca se basa en una sola lectura aislada en un momento de estrés:", items: ["Medición en el consultorio: Se requiere medir la presión con un esfigmomanómetro en ambos brazos, en posición sentada, con descanso previo, en al menos 2 a 3 visitas médicas separadas para confirmar el patrón de elevación.", "Monitoreo Ambulatorio de la Presión Arterial (MAPA) de 24 horas: Un pequeño dispositivo portátil mide automáticamente la presión cada 20-30 minutos durante un día y una noche normal (el método más preciso para confirmar el diagnóstico y descartar el síndrome de la 'bata blanca' por nervios en la consulta).", "Análisis de sangre y orina, Electrocardiograma (ECG) y examen de fondo de ojo: No diagnostican la presión, pero se realizan para evaluar si la presión alta ya ha causado daños ocultos en los riñones, el corazón o los ojos (daño de órgano diana)."], note: "" }, treatment: { title: "Tratamientos", intro: "Es una enfermedad para toda la vida. El tratamiento combina modificaciones drásticas del estilo de vida con medicamentos diarios:", subsections: [ { title: "Estilo de Vida y Dieta", items: ["Dieta DASH: Un plan alimenticio demostrado para bajar la presión, rico en frutas, verduras, cereales integrales, calcio y potasio, con una reducción drástica de alimentos procesados y sal (menos de 2,300 mg de sodio al día).", "Pérdida de peso: Bajar incluso de 2 a 4 kilos puede reducir la presión arterial significativamente en personas con sobrepeso.", "Ejercicio aeróbico regular (como caminar a paso rápido, nadar o andar en bicicleta durante 30 minutos al día)."] }, { title: "Tratamiento Farmacológico (Medicamentos)", items: ["Diuréticos ('pastillas para orinar'): Ayudan a los riñones a eliminar el exceso de sodio y agua del cuerpo, reduciendo el volumen sanguíneo.", "Inhibidores de la Enzima Convertidora de Angiotensina (IECA, como el Enalapril o Lisinopril) y Antagonistas de los Receptores de Angiotensina II (ARA-II, como el Losartán o Valsartán): Relajan las venas y arterias bloqueando la formación o acción de una sustancia química natural que estrecha los vasos sanguíneos.", "Bloqueadores de los canales de calcio (como Amlodipino): Impiden que el calcio entre en las células del corazón y las arterias, permitiendo que los vasos se relajen y se abran.", "Betabloqueadores: Hacen que el corazón lata más despacio y con menos fuerza, reduciendo la carga de trabajo."] } ], note: "Frecuentemente, se necesita una combinación de dos o más pastillas de baja dosis para lograr controlar la presión arterial de forma efectiva. Nunca se deben suspender repentinamente los medicamentos para la presión sin supervisión médica, ya que pueden causar una crisis de rebote grave." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias médicas inmediatamente si al medirte la presión está por encima de 180/120 mmHg y tienes:", items: ["Falta de aliento aguda y severa, o dolor fuerte, pesadez y opresión en el centro del pecho", "Entumecimiento repentino, debilidad extrema en un lado de la cara, brazo o pierna, o dificultad repentina para hablar", "El peor dolor de cabeza de tu vida, seguido de confusión o visión muy borrosa", "Dolor severo e inexplicable en la espalda o el abdomen"] } },
'Embarazo molar' : { intro: "Un embarazo molar (también conocido como mola hidatidiforme) es una complicación rara y dramática del embarazo, clasificada como una enfermedad trofoblástica gestacional. En esta condición, ocurre un error en el momento de la fertilización, resultando en el crecimiento de un tumor anormal (benigno) dentro del útero, en lugar de un feto y una placenta sanos.", whatIs: { title: "¿Qué es un Embarazo Molar?", text: "Normalmente, el tejido de la placenta (el trofoblasto) nutre al feto en crecimiento. En un embarazo molar, debido a un fallo genético en la concepción, las células formadoras de placenta se multiplican descontroladamente y se transforman en una masa de quistes hinchados llenos de líquido, que al microscopio se asemejan a un gran racimo de uvas blancas. Es una afección que no puede resultar en el nacimiento de un niño vivo, requiere la terminación médica del embarazo y un seguimiento estricto para evitar complicaciones cancerígenas raras." }, symptoms: { title: "Síntomas y Señales de Alerta", intro: "Al principio, parece un embarazo normal y dará positivo en las pruebas caseras, pero los síntomas anómalos pronto se desarrollan, usualmente en el primer trimestre:", groups: [ { name: "Síntomas Clínicos", items: ["Sangrado vaginal anormal durante el primer trimestre (puede ser sangre roja brillante a un flujo oscuro tipo posos de café)", "Expulsión vaginal de pequeños quistes similares a uvas a través de la vagina", "Náuseas y vómitos extremadamente severos y debilitantes (hiperémesis gravídica), mucho peores que los de un embarazo normal", "Útero inusualmente grande y que crece demasiado rápido para la edad gestacional calculada", "Dolor o presión pélvica notable en un embarazo muy temprano"] }, { name: "Complicaciones Asociadas", items: ["Presión arterial anormalmente alta (preeclampsia) antes de la semana 20 de embarazo (muy inusual en embarazos normales)", "Síntomas de tiroides hiperactiva (hipertiroidismo), como latidos cardíacos rápidos o sudoración excesiva", "Aparición de quistes en los ovarios"] } ], warning: "Si expulsas cualquier tejido por la vagina durante el embarazo, intenta conservarlo en un recipiente limpio para que el médico o el laboratorio puedan analizarlo y confirmar el diagnóstico." }, types: { title: "Tipos de Embarazo Molar", intro: "Se divide en dos categorías según su genética:", items: ["Embarazo Molar Completo: El tejido de la placenta es totalmente anormal y se hincha formando quistes llenos de líquido. NO hay formación de tejido fetal en absoluto. Ocurre clásicamente cuando un espermatozoide fertiliza un óvulo 'vacío' (sin información genética materna), duplicando solo la genética paterna.", "Embarazo Molar Parcial: Puede haber un desarrollo temprano y mixto de tejido placentario normal junto con tejido placentario anormal y quístico. Sí existe tejido fetal, pero este feto es genéticamente severamente anormal (a menudo por fertilización de un óvulo por dos espermatozoides a la vez), no puede sobrevivir, y morirá tempranamente en el útero."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Es causado estrictamente por anomalías cromosómicas en el momento de la fecundación, pero ciertos factores aumentan la probabilidad:", items: ["Extremos de edad materna: Es significativamente más común en mujeres menores de 20 años y mayores de 40 años (especialmente mayores de 45).", "Antecedentes previos: Haber tenido un embarazo molar en el pasado aumenta el riesgo de tener otro (de un 1-2%).", "Deficiencias nutricionales muy severas (bajos niveles de caroteno, vitamina A y folato en la dieta, más común en ciertas regiones del sudeste asiático y México)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se diagnostica durante la primera ecografía de rutina o al presentarse sangrado:", items: ["Ecografía pélvica transvaginal: El signo clásico de una mola completa es la ausencia de feto, ausencia de líquido amniótico y la presencia de un útero lleno de una masa quística con apariencia de 'tormenta de nieve' o 'queso suizo'.", "Análisis de sangre para GCH (gonadotropina coriónica humana): Los niveles de esta hormona del embarazo serán desproporcionadamente y extremadamente altos en comparación con un embarazo normal de la misma duración.", "Análisis patológico: Examen del tejido bajo microscopio tras su extirpación para confirmar el diagnóstico y tipo."], note: "" }, treatment: { title: "Tratamientos y Seguimiento", intro: "Un embarazo molar es inviable y debe eliminarse del útero de forma segura para prevenir infecciones severas, hemorragias o cáncer trofoblástico:", subsections: [ { title: "Procedimientos de Extirpación", items: ["Dilatación y legrado por succión (Legrado uterino instrumentado - LUI): Bajo anestesia local o general en un hospital, el cuello uterino se dilata y se utiliza un dispositivo de succión especializado para vaciar suavemente todo el tejido molar de la cavidad del útero. Es la técnica estándar.", "Histerectomía: En casos raros, si la mujer tiene mayor edad, ha decidido no tener futuros embarazos y existe un alto riesgo de que el tejido molar se vuelva maligno, el útero completo puede ser extirpado."] }, { title: "Seguimiento Obligatorio (El Paso Crítico)", items: ["Monitoreo de niveles de GCH: Tras la cirugía, se realizarán análisis de sangre semanales y luego mensuales (hasta por 6 a 12 meses) para asegurarse de que la hormona del embarazo llegue y se mantenga en nivel CERO.", "Prevención del embarazo: Es estrictamente prohibido quedar embarazada durante el periodo de seguimiento (seis meses a un año), ya que un nuevo embarazo produciría GCH, lo que imposibilitaría saber si el tejido tumoral molar ha vuelto a crecer.", "Tratamiento de la Neoplasia Trofoblástica Gestacional (NTG): En aproximadamente un 15-20% de las molas completas, parte del tejido tumoral queda profundamente incrustado en la pared del útero y sigue creciendo (a menudo manifestado como coriocarcinoma). En estos casos de malignización, se requiere iniciar un tratamiento curativo y altamente exitoso con quimioterapia."] } ], note: "Aunque perder un embarazo molar implica duelo y dolor emocional como cualquier aborto, desde el punto de vista médico, tras un tratamiento exitoso y un periodo de espera seguro, las probabilidades de tener un embarazo futuro completamente sano son altísimas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Si estás embarazada, contacta a tu médico u obstetra inmediatamente si:", items: ["Presentas cualquier cantidad de sangrado vaginal rojo o de color oscuro inusual", "Vomitas constantemente hasta el punto de no poder retener ni líquidos ni agua (náuseas matutinas anormalmente intensas)", "Sientes mareos severos, dolor de cabeza o experimentas dolor profundo o punzadas intensas en el vientre pélvico"] } },
'Arco alto' : { intro: "El arco alto, también conocido médicamente como pie cavo, es una condición estructural del pie en la que la bóveda plantar es excesivamente elevada, lo que altera la forma en que el pie absorbe el impacto al caminar.", whatIs: { title: "¿Qué es el Arco Alto?", text: "A diferencia de un pie normal o un pie plano, en el pie cavo el arco no se aplana al apoyar el peso del cuerpo. Esto provoca que toda la presión al estar de pie o caminar se concentre en dos puntos muy pequeños: el talón y la base de los dedos (metatarso), lo que genera una gran sobrecarga biomecánica." }, symptoms: { title: "Síntomas Comunes", intro: "La mala distribución del peso corporal suele provocar:", groups: [ { name: "Problemas Físicos y Dolor", items: ["Dolor intenso en el talón, la planta del pie o el metatarso al estar de pie o caminar", "Aparición de callosidades gruesas y dolorosas bajo la base de los dedos o en el talón", "Dedos en garra o dedos en martillo (los dedos se curvan y retraen debido a la tensión muscular)", "Inestabilidad al caminar y esguinces de tobillo frecuentes debido a la rigidez del pie"] } ], warning: "Si el arco alto aparece repentinamente en un solo pie o empeora rápidamente, requiere evaluación neurológica inmediata." }, types: { title: "Naturaleza de la Condición", intro: "El pie cavo puede ser una característica anatómica aislada o síntoma de otra enfermedad:", items: ["Pie cavo fisiológico o idiopático: Variante anatómica hereditaria sin una causa subyacente de enfermedad.", "Pie cavo neurológico: Secundario a enfermedades del sistema nervioso que causan desequilibrio muscular, como la enfermedad de Charcot-Marie-Tooth, espina bífida, parálisis cerebral o distrofia muscular."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es clínico y biomecánico:", items: ["Examen físico del pie en reposo y en carga (de pie)", "Podoscopia o estudio de la pisada (para ver la huella plantar, que mostrará la ausencia de apoyo en el medio pie)", "Radiografías de los pies en carga para medir los ángulos de los huesos", "Evaluación neurológica completa (si se sospecha una enfermedad subyacente)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es redistribuir el peso y aliviar la presión:", subsections: [ { title: "Opciones de Manejo", items: ["Plantillas ortopédicas personalizadas (diseñadas para rellenar el hueco del arco y amortiguar el impacto en el talón y el metatarso)", "Calzado adecuado: Zapatos de horma ancha, con suelas gruesas y excelente amortiguación", "Fisioterapia: Ejercicios para estirar la fascia plantar y el tendón de Aquiles, mejorando la flexibilidad", "Cirugía: Reservada para casos de dolor severo o deformidad progresiva (incluye liberación de la fascia, transferencia de tendones o corrección ósea)"] } ], note: "Las plantillas no curan el arco alto ni bajan el arco, pero son fundamentales para evitar el dolor y la aparición de úlceras." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un podiatra o traumatólogo si:", items: ["El dolor en los pies te impide realizar tus actividades diarias normales", "Desarrollas callosidades dolorosas que sangran o se infectan", "Notas inestabilidad constante, debilidad en las piernas o sufres torceduras de tobillo frecuentes"] } },
'Pérdida gestacional recurrente' : { intro: "La pérdida gestacional recurrente, o aborto recurrente, se define como la pérdida espontánea de dos o más embarazos clínicos consecutivos antes de la semana 20 de gestación. Es una experiencia emocionalmente devastadora que requiere una evaluación médica profunda.", whatIs: { title: "¿Qué es la Pérdida Gestacional Recurrente?", text: "Mientras que un solo aborto espontáneo es bastante común y a menudo se debe a una anomalía genética aleatoria en ese embrión específico, las pérdidas repetidas sugieren que podría existir un problema subyacente sistemático en el cuerpo de la madre o del padre que impide que el embarazo se desarrolle correctamente." }, symptoms: { title: "Síntomas de Aborto Espontáneo", intro: "Los signos de que un embarazo se está perdiendo incluyen:", groups: [ { name: "Signos Clínicos", items: ["Sangrado o manchado vaginal profuso (de color rojo brillante o marrón oscuro)", "Calambres intensos o dolor en la parte baja del abdomen o en la espalda baja", "Expulsión de tejido, coágulos grandes o líquido a través de la vagina", "Disminución repentina de los síntomas del embarazo (como la sensibilidad en los senos o las náuseas)"] } ], warning: "Cualquier sangrado vaginal abundante durante el embarazo acompañado de mareos intensos o dolor en un solo lado del abdomen debe evaluarse urgentemente para descartar un embarazo ectópico." }, causes: { title: "Causas y Factores de Riesgo", intro: "Aproximadamente en la mitad de los casos se identifica una causa tratable:", items: ["Anomalías genéticas o cromosómicas heredadas de uno de los padres (como translocaciones)", "Anomalías anatómicas del útero (útero septado, miomas, pólipos o incompetencia cervical)", "Trastornos inmunológicos o de coagulación (Síndrome Antifosfolípido, trombofilias, donde se forman coágulos en la placenta)", "Problemas endocrinos (diabetes no controlada, enfermedad de la tiroides, síndrome de ovario poliquístico o niveles bajos de progesterona)", "Factores del estilo de vida (tabaquismo crónico, consumo de alcohol o drogas, obesidad severa)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Tras dos o más pérdidas, se recomienda un estudio de fertilidad exhaustivo:", items: ["Análisis de sangre para detectar trastornos de coagulación (como el Síndrome Antifosfolípido), función tiroidea y niveles hormonales", "Cariotipo de ambos padres (prueba genética de sangre para revisar los cromosomas)", "Ecografía pélvica 3D o Histerosonografía (para evaluar la forma del interior del útero)", "Histeroscopia (inserción de una pequeña cámara en el útero para ver y posiblemente corregir problemas anatómicos directamente)"], note: "En un alto porcentaje de parejas (hasta el 50%), las pruebas médicas no logran identificar una causa exacta (pérdida recurrente idiopática)." }, treatment: { title: "Tratamientos", intro: "El tratamiento se dirige a la causa específica encontrada en los estudios:", subsections: [ { title: "Opciones Terapéuticas", items: ["Aspirina en dosis bajas y heparina (anticoagulantes inyectables) para mujeres con Síndrome Antifosfolípido o trastornos de coagulación", "Cirugía (histeroscopia) para corregir un útero septado, extirpar miomas o pólipos", "Cerclaje cervical (un punto de sutura en el cuello del útero) si la causa es la debilidad cervical", "Suplementos de progesterona o tratamiento con hormona tiroidea (levotiroxina) para problemas endocrinos", "Fecundación in vitro (FIV) con diagnóstico genético preimplantacional (PGT) para parejas con anomalías cromosómicas conocidas"] } ], note: "Incluso cuando no se encuentra una causa, la probabilidad de tener un embarazo exitoso en el futuro con un cuidado prenatal de apoyo es superior al 60%." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es crucial buscar orientación médica si:", items: ["Has sufrido dos o más abortos espontáneos (consecutivos o no)", "Estás embarazada de nuevo después de haber tenido pérdidas previas (para iniciar el monitoreo temprano)", "Sientes sangrado abundante, dolor insoportable o fiebre después de un aborto espontáneo (riesgo de hemorragia grave o infección)"] } },
'Síndrome de dolor pélvico crónico' : { intro: "El síndrome de dolor pélvico crónico (SDPC) es una afección debilitante caracterizada por dolor persistente en la región pélvica (la parte baja del abdomen) que dura al menos seis meses, y que no está asociado de manera obvia con el embarazo, menstruación o una infección activa.", whatIs: { title: "¿Qué es el Dolor Pélvico Crónico?", text: "Es un síndrome complejo que afecta tanto a mujeres como a hombres. El dolor se percibe en la pelvis, el periné o los genitales. A menudo, se convierte en una enfermedad en sí misma debido a los cambios que produce en el sistema nervioso central, haciendo que los nervios de la pelvis envíen señales de dolor continuas incluso si la lesión o causa original ya ha sanado." }, symptoms: { title: "Síntomas Comunes", intro: "El dolor puede presentarse de diversas maneras:", groups: [ { name: "Características del Dolor", items: ["Dolor constante, sordo y pesado, o bien dolores punzantes agudos e intermitentes", "Dolor que empeora al estar sentado durante mucho tiempo, al caminar o hacer ejercicio", "Dolor pélvico que se irradia hacia la espalda baja, los glúteos o los muslos", "Dolor severo durante o después de las relaciones sexuales (dispareunia)", "Dolor o ardor al orinar o al defecar, o necesidad constante y urgente de orinar"] } ], warning: "El dolor crónico constante suele generar fatiga extrema, problemas de sueño, depresión severa y ansiedad, lo que a su vez empeora la percepción del dolor." }, causes: { title: "Causas y Factores de Riesgo", intro: "A menudo es el resultado de múltiples problemas superpuestos (físicos y nerviosos):", items: ["En mujeres: Endometriosis, adenomiosis, enfermedad inflamatoria pélvica crónica, síndrome de congestión pélvica (varices en la pelvis) o adherencias pélvicas por cirugías previas.", "En hombres: Prostatitis crónica no bacteriana (la causa más común en varones).", "En ambos: Cistitis intersticial (síndrome de vejiga dolorosa), síndrome del intestino irritable (SII), disfunción o espasmos de los músculos del suelo pélvico, y síndromes de atrapamiento nervioso (como el nervio pudendo)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico de exclusión, descartando primero enfermedades agudas o infecciosas:", items: ["Historia clínica detallada y diario del dolor", "Examen físico pélvico para detectar puntos gatillo de tensión en los músculos del suelo pélvico", "Ecografía pélvica transvaginal o transrectal", "Resonancia Magnética (RM) pélvica", "Laparoscopia diagnóstica (en mujeres, para ver y confirmar endometriosis o adherencias) o cistoscopia (para evaluar el interior de la vejiga)"], note: "En muchos pacientes, no se encuentra una única causa anatómica que explique la severidad del dolor." }, treatment: { title: "Tratamientos", intro: "El tratamiento debe ser multidisciplinario, enfocado en el manejo de los síntomas y la mejora de la calidad de vida:", subsections: [ { title: "Enfoque Integral", items: ["Fisioterapia del suelo pélvico: Crucial para relajar los músculos pélvicos tensos y liberar los puntos gatillo (a menudo el tratamiento más efectivo).", "Medicamentos neuromoduladores: Antidepresivos tricíclicos (amitriptilina) o anticonvulsivos (gabapentina, pregabalina) que calman la hipersensibilidad de los nervios.", "Analgésicos y relajantes musculares, y en mujeres, terapias hormonales para suprimir la menstruación o tratar la endometriosis.", "Infiltraciones o bloqueos nerviosos locales con anestésicos y esteroides.", "Terapia psicológica (TCC): Esencial para desarrollar estrategias de afrontamiento frente al dolor crónico y tratar la depresión secundaria."] } ], note: "Los analgésicos opioides (narcóticos) rara vez son eficaces a largo plazo para este tipo de dolor y tienen un alto riesgo de adicción." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico especialista (ginecólogo, urólogo o especialista en dolor) si:", items: ["El dolor pélvico interfiere con tu capacidad para trabajar, dormir o disfrutar de la vida diaria", "Experimentas dolor insoportable de forma regular durante o después de las relaciones sexuales", "Presentas síntomas asociados como sangre en la orina o en las heces, o pérdida de peso inexplicable"] } },
'Enfermedad del sueño' : { intro: "La enfermedad del sueño, conocida médicamente como Tripanosomiasis Africana Humana, es una infección parasitaria potencialmente mortal transmitida al ser humano por la picadura de moscas tsetsé infectadas, las cuales se encuentran únicamente en ciertas regiones de África subsahariana.", whatIs: { title: "¿Qué es la Enfermedad del Sueño?", text: "Es causada por parásitos microscópicos llamados tripanosomas (*Trypanosoma brucei*). Después de la picadura de la mosca, los parásitos se multiplican en la sangre y la linfa. Si la enfermedad no se trata, en su segunda fase los parásitos logran cruzar la barrera hematoencefálica e invaden el sistema nervioso central y el cerebro. Esto provoca una grave inflamación neurológica que altera el reloj biológico del cuerpo (el ciclo de sueño-vigilia), conduciendo finalmente al coma y la muerte." }, symptoms: { title: "Síntomas y Fases", intro: "La enfermedad progresa en dos etapas bien diferenciadas:", groups: [ { name: "Primera Etapa (Fase Hemolinfática)", items: ["Aparición de una úlcera dolorosa e inflamada (chancro) en el lugar de la picadura de la mosca", "Fiebre intermitente, fuertes dolores de cabeza, y dolores articulares y musculares", "Picazón intensa en la piel y ganglios linfáticos muy inflamados (especialmente en la parte posterior del cuello)"] }, { name: "Segunda Etapa (Fase Neurológica)", items: ["Alteración profunda del ciclo de sueño: necesidad irresistible de dormir durante el día y períodos de insomnio prolongado durante la noche", "Cambios marcados de personalidad, irritabilidad, confusión y problemas de concentración", "Dificultad para caminar, temblores y debilidad muscular", "Convulsiones, seguidas de letargo profundo, coma y, finalmente, la muerte si no hay intervención médica"] } ], warning: "Sin el tratamiento adecuado, la tripanosomiasis africana se considera una enfermedad 100% fatal." }, types: { title: "Formas de la Enfermedad", intro: "Existen dos cepas del parásito que causan diferentes progresiones de la enfermedad:", items: ["Tripanosomiasis gambiense (T.b. gambiense): Presente en África occidental y central. Causa más del 95% de los casos. Es una infección crónica que progresa lentamente, pudiendo tardar años en llegar a la fase neurológica.", "Tripanosomiasis rhodesiense (T.b. rhodesiense): Presente en África oriental y meridional. Es una infección aguda y agresiva que invade el cerebro en cuestión de semanas o meses."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere pruebas de laboratorio para encontrar el parásito:", items: ["Análisis de sangre (frotis sanguíneo) o examen del líquido aspirado de un ganglio linfático inflamado para buscar físicamente el parásito bajo el microscopio", "Punción lumbar (extracción de líquido cefalorraquídeo de la columna vertebral) para determinar si los parásitos han cruzado al cerebro, lo cual es obligatorio para decidir qué tratamiento usar", "Pruebas de detección rápida en campo (disponibles para la forma gambiense)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento varía drásticamente según la etapa de la enfermedad y el tipo de parásito:", subsections: [ { title: "Opciones Médicas", items: ["Fase 1 (Antes de invadir el cerebro): Fármacos inyectables u orales más seguros, como Pentamidina (para la forma gambiense) o Suramina (para la forma rhodesiense).", "Fase 2 (Infección neurológica): Históricamente se usaba el melarsoprol (tóxico, derivado del arsénico). Hoy en día, para la forma gambiense se prefiere la Terapia Combinada de Nifurtimox-Eflornitina (NECT) o el Fexinidazol oral (un gran avance médico reciente que evita inyecciones complejas). Para la rhodesiense en fase 2, el melarsoprol sigue siendo necesario a pesar de sus graves efectos secundarios."] } ], note: "No existe vacuna ni medicamentos preventivos contra la enfermedad del sueño; la prevención se basa en evitar las picaduras de la mosca tsetsé." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención médica urgente si:", items: ["Has viajado o vivido en África subsahariana y desarrollas fiebres inexplicables, dolores de cabeza fuertes o ganglios inflamados, incluso meses después del viaje", "Notas alteraciones inusuales en tus patrones de sueño o cambios bruscos en tu estado mental", "Sufres una picadura muy dolorosa de mosca durante un safari que evoluciona hacia una llaga roja e hinchada"] } },
'Terror nocturno' : { intro: "El terror nocturno es un trastorno del sueño (una parasomnia) en el que una persona se despierta repentinamente de un sueño profundo en un estado de pánico extremo y agitación. Es mucho más común en niños pequeños, aunque ocasionalmente puede afectar a adultos.", whatIs: { title: "¿Qué es un Terror Nocturno?", text: "A diferencia de las pesadillas, que ocurren durante el sueño REM (sueño ligero donde soñamos y solemos recordar la trama), los terrores nocturnos ocurren durante el primer tercio de la noche, en la fase más profunda del sueño (sueño no REM). Durante un episodio, el cerebro de la persona se queda atascado entre estar profundamente dormido y medio despierto. Aunque la persona tiene los ojos abiertos y grita, en realidad está inconsciente, no responde al entorno, y por lo general, no recordará absolutamente nada a la mañana siguiente." }, symptoms: { title: "Síntomas y Comportamiento", intro: "Los episodios son a menudo más aterradores para los padres o la pareja que para la persona que los sufre:", groups: [ { name: "Durante el Episodio", items: ["Sentarse bruscamente en la cama, a menudo comenzando con un grito fuerte y desgarrador", "Mirada fija y vacía, con las pupilas dilatadas (ojos abiertos pero sin ver realmente)", "Respiración agitada, taquicardia severa y sudoración profusa", "Agitación física intensa: golpear, patear, retorcerse o salir de la cama corriendo (riesgo de sonambulismo o lesiones)", "Incapacidad para ser consolado o despertado completamente (la persona puede rechazar físicamente los abrazos o consuelos)"] } ], warning: "Intentar despertar o sacudir a una persona durante un terror nocturno no suele funcionar y a menudo empeora el episodio, haciéndolo más largo y agitando más a la persona." }, causes: { title: "Causas y Factores Desencadenantes", intro: "El sistema nervioso central inmaduro de los niños es la base, pero los episodios se desencadenan por:", items: ["Privación del sueño, agotamiento extremo o un horario de sueño muy irregular", "Fiebre alta o enfermedades (muy común en niños pequeños)", "Estrés emocional intenso, ansiedad o cambios importantes en la rutina (nuevo colegio, problemas familiares)", "Dormir en un entorno desconocido o con ruidos/luces perturbadoras", "Antecedentes familiares (fuerte componente genético; a menudo los padres también tuvieron terrores o sonambulismo)", "Afecciones subyacentes que fragmentan el sueño, como la apnea obstructiva del sueño o el síndrome de piernas inquietas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente, no se necesitan pruebas médicas. El diagnóstico es clínico:", items: ["Historia detallada del sueño proporcionada por los padres o la pareja", "Diferenciación con las pesadillas (en las pesadillas la persona se despierta, busca consuelo y recuerda el mal sueño)", "Polisomnografía (estudio del sueño en una clínica): Solo se solicita si los episodios son atípicamente frecuentes, ocurren en adultos por primera vez, o se sospecha de apneas del sueño o convulsiones nocturnas"], note: "" }, treatment: { title: "Tratamientos", intro: "En la gran mayoría de los casos infantiles, no se requiere tratamiento médico y el niño los superará al crecer:", subsections: [ { title: "Manejo y Prevención", items: ["Seguridad ante todo: No intentar despertar al niño. En su lugar, asegurar la habitación, retirar objetos peligrosos, asegurar puertas y ventanas, y guiar suavemente a la persona de vuelta a la cama.", "Mejora de la higiene del sueño: Mantener una rutina de sueño constante, relajante y asegurar suficientes horas de descanso para evitar la fatiga extrema.", "Despertares programados: Si los terrores ocurren a la misma hora cada noche, despertar suavemente al niño 15 minutos antes del episodio esperado, mantenerlo despierto un par de minutos y dejarlo dormir de nuevo (esto reinicia el ciclo de sueño).", "Tratamiento de causas subyacentes: Tratar el estrés, la fiebre o la apnea del sueño.", "Medicación: Rara vez justificada, pero se pueden prescribir benzodiacepinas en adultos o en casos infantiles extremos donde haya alto riesgo de lesiones."] } ], note: "Es vital que los padres mantengan la calma, ya que el niño no está sufriendo daño emocional ni recordará el evento." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta con el pediatra o a un especialista del sueño si:", items: ["Los terrores nocturnos son tan frecuentes (varios a la semana) que interrumpen severamente el sueño de toda la familia", "Los episodios llevan a comportamientos peligrosos que ponen en riesgo la seguridad del niño (saltar de la cama, sonambulismo)", "Los terrores nocturnos continúan en la adolescencia o comienzan repentinamente en la edad adulta", "Están acompañados de ronquidos fuertes o jadeos (signo de apnea del sueño)"] } },
'Trastornos neurocognitivos' : { intro: "Los Trastornos Neurocognitivos (TNC) son una categoría de afecciones médicas en las que la función cerebral principal que se ve afectada es la cognición. Estas condiciones representan una disminución significativa con respecto a un nivel previo de funcionamiento intelectual de la persona.", whatIs: { title: "¿Qué son los Trastornos Neurocognitivos?", text: "El término TNC (que reemplazó al término 'demencia' en los manuales de diagnóstico psiquiátrico modernos para ser más preciso y menos estigmatizante) engloba enfermedades que causan un declive adquirido en funciones mentales como la memoria, la atención, el lenguaje, el aprendizaje, el juicio y la capacidad espacial. A diferencia de problemas del desarrollo presentes desde el nacimiento, los TNC ocurren debido a daños cerebrales físicos adquiridos durante la vida." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen del grado del trastorno y del área del cerebro dañada:", groups: [ { name: "Síntomas Cognitivos y Prácticos", items: ["Olvidos frecuentes de información reciente, eventos o conversaciones", "Dificultad para planificar, tomar decisiones o resolver problemas cotidianos (como manejar el dinero)", "Problemas para encontrar las palabras correctas (afasia) o comprender el lenguaje", "Desorientación en el tiempo y el espacio (perderse en rutas habituales)", "Dificultad para reconocer rostros familiares u objetos (agnosia)"] }, { name: "Cambios en el Comportamiento", items: ["Apatía, pérdida de interés en hobbies o retiro de la interacción social", "Cambios bruscos de personalidad, irritabilidad, paranoia o comportamiento impulsivo e inapropiado"] } ], warning: "Si el declive cognitivo interfiere con la independencia de la persona para realizar actividades básicas (comer, vestirse, gestionar su hogar), se considera un TNC Mayor." }, types: { title: "Niveles y Causas Principales", intro: "Se clasifican por su gravedad (Leve o Mayor) y por la enfermedad subyacente que los causa:", items: ["TNC Leve (Deterioro Cognitivo Leve): Hay una disminución en la memoria o el pensamiento, pero la persona aún puede vivir de forma independiente con algunas compensaciones.", "TNC Mayor (anteriormente Demencia): La pérdida cognitiva es tan severa que la persona pierde su independencia.", "Causas Subyacentes Principales: Enfermedad de Alzheimer (la causa neurodegenerativa más común), Enfermedad Vascular (por derrames cerebrales), Cuerpos de Lewy, Degeneración Frontotemporal, Enfermedad de Parkinson, Lesión Cerebral Traumática severa, y la infección por VIH."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Una evaluación neurológica y psiquiátrica exhaustiva es necesaria para identificar la causa:", items: ["Evaluaciones neuropsicológicas y cognitivas estandarizadas (pruebas de memoria, lenguaje y resolución de problemas)", "Historial clínico detallado, a menudo con la participación esencial de familiares o cuidadores", "Análisis de sangre para descartar causas de declive cognitivo potencialmente reversibles (como déficit severo de vitamina B12, problemas de tiroides o infecciones sistémicas)", "Imágenes cerebrales estructurales (Resonancia Magnética - RM o TC) para buscar tumores, infartos o atrofia de áreas específicas del cerebro", "Imágenes funcionales (PET) o análisis de líquido cefalorraquídeo para buscar biomarcadores específicos del Alzheimer"], note: "Detectar si se trata de un TNC Leve es crucial, ya que permite intervenciones tempranas para planificar el futuro y ralentizar el progreso." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en la causa subyacente y en el manejo de la calidad de vida, ya que muchas causas (como el Alzheimer) son progresivas e incurables:", subsections: [ { title: "Estrategias Médicas y de Soporte", items: ["Intervenciones Farmacológicas: Uso de inhibidores de colinesterasa (Donepezilo) o memantina para tratar los síntomas cognitivos del Alzheimer. Fármacos para manejar la depresión, ansiedad o alteraciones graves del sueño asociadas.", "Terapias de Estimulación Cognitiva: Ejercicios mentales estructurados para ayudar a mantener activas las redes neuronales.", "Rehabilitación y Terapia Ocupacional: Adaptación del entorno del hogar para prevenir caídas, uso de recordatorios visuales y simplificación de las rutinas diarias para mantener la independencia el mayor tiempo posible.", "Modificación de factores de riesgo: Control agresivo de la presión arterial, la diabetes y el colesterol (crucial en los TNC vasculares).", "Apoyo al cuidador: Provisión de recursos, educación y grupos de apoyo para las familias, quienes soportan una carga emocional y física extrema."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un médico o neurólogo para una evaluación de memoria si:", items: ["La persona olvida información importante con frecuencia y repite las mismas preguntas en un corto período de tiempo", "Experimenta dificultades crecientes para manejar tareas cotidianas que antes hacía sin esfuerzo (como cocinar una receta conocida o pagar cuentas)", "La familia nota cambios drásticos e inexplicables en su personalidad o juicio"] } },
'Tetralogía de Fallot' : { intro: "La tetralogía de Fallot es un tipo complejo de defecto cardíaco congénito (presente al nacer) que combina cuatro anomalías estructurales en el corazón. Es la causa más común del síndrome del 'bebé azul' (cianosis) debido a la falta de oxígeno en la sangre.", whatIs: { title: "¿Qué es la Tetralogía de Fallot?", text: "Esta afección cambia la forma en que la sangre fluye a través del corazón y hacia los pulmones. Debido a estos defectos, la sangre pobre en oxígeno (azul) que debería ir a los pulmones se mezcla con la sangre rica en oxígeno (roja) y se bombea hacia el resto del cuerpo. Esto provoca que los bebés y niños afectados tengan un suministro crónico bajo de oxígeno en sus tejidos, dándoles una coloración azulada en la piel, labios y uñas." }, symptoms: { title: "Síntomas y Signos", intro: "Los síntomas varían según la gravedad de la obstrucción del flujo sanguíneo hacia los pulmones:", groups: [ { name: "Signos Físicos", items: ["Cianosis (coloración azulada, grisácea o violácea de la piel, labios y lechos ungueales, especialmente al llorar o alimentarse)", "Dificultad para respirar, respiración rápida o episodios de fatiga extrema durante la alimentación", "Falta de aumento de peso adecuado y retraso en el crecimiento", "Acropaquia o 'dedos en palillo de tambor' (ensanchamiento anormal de las puntas de los dedos de las manos y los pies, que ocurre con el tiempo)"] }, { name: "Crisis Hipercianóticas (Crisis de Fallot)", items: ["Son episodios súbitos y peligrosos donde el nivel de oxígeno cae drásticamente. El bebé o niño se pone de un azul muy oscuro, respira agitadamente, llora inconsolablemente, puede desmayarse o convulsionar.", "Los niños mayores con Fallot no reparado a menudo se 'ponen en cuclillas' instintivamente cuando se sienten sin aliento, ya que esta postura altera la presión sanguínea y aumenta el flujo de sangre a los pulmones temporalmente."] } ], warning: "Una crisis hipercianótica es una emergencia médica. Los padres deben instruirse en técnicas de primeros auxilios (como llevar las rodillas del bebé al pecho) mientras esperan la asistencia médica." }, types: { title: "Los Cuatro Defectos (La Tetralogía)", intro: "El corazón presenta los siguientes problemas simultáneamente:", items: ["1. Estenosis de la válvula pulmonar: Un estrechamiento de la válvula y arteria que llevan la sangre del corazón a los pulmones.", "2. Comunicación interventricular (CIV): Un orificio (soplo) en la pared (tabique) que separa las dos cámaras inferiores del corazón (ventrículos).", "3. Cabalgamiento de la aorta: La arteria aorta, que debería estar conectada solo al ventrículo izquierdo, está desplazada sobre el orificio del tabique, recibiendo sangre mezclada de ambos ventrículos.", "4. Hipertrofia del ventrículo derecho: El músculo del ventrículo derecho se vuelve anormalmente grueso por el esfuerzo excesivo de intentar bombear sangre a través de la válvula pulmonar estrecha."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Es un error en el desarrollo fetal durante el primer trimestre. Los factores de riesgo asociados incluyen:", items: ["Anomalías genéticas o síndromes cromosómicos en el bebé (como el Síndrome de DiGeorge o el Síndrome de Down)", "Factores maternos durante el embarazo: Infección por rubéola (sarampión alemán), alcoholismo, nutrición deficiente extrema o diabetes materna no controlada", "Edad materna avanzada (madres mayores de 40 años)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Generalmente se diagnostica poco después del nacimiento o incluso antes:", items: ["Ecocardiograma fetal (puede detectar los defectos en el corazón del bebé durante el embarazo)", "Oximetría de pulso al nacer (medición de niveles bajos de oxígeno en la sangre)", "Auscultación (el pediatra escucha un soplo cardíaco fuerte y áspero característico)", "Ecocardiograma posnatal (la prueba de oro que muestra la anatomía exacta y el flujo sanguíneo)", "Radiografía de tórax (clásicamente muestra un corazón con forma de 'bota' debido al ventrículo derecho agrandado)"], note: "" }, treatment: { title: "Tratamientos", intro: "La Tetralogía de Fallot requiere obligatoriamente corrección quirúrgica para la supervivencia:", subsections: [ { title: "Opciones Quirúrgicas y Manejo", items: ["Reparación Intracardíaca Completa: Es la cirugía a corazón abierto definitiva, realizada generalmente durante el primer año de vida (entre los 3 y 6 meses). El cirujano cierra el agujero del tabique con un parche y ensancha la salida hacia la arteria pulmonar para restaurar el flujo sanguíneo normal.", "Cirugía Paliativa Temporal (Derivación o Shunt): Se usa si el bebé es muy pequeño o prematuro para soportar la reparación completa. Se crea un tubo artificial (derivación) entre la aorta y la arteria pulmonar para aumentar el flujo de sangre a los pulmones, permitiendo al bebé crecer hasta estar listo para la cirugía definitiva.", "Manejo médico provisional: Medicamentos para controlar las crisis de cianosis antes de la cirugía."] } ], note: "Aunque la cirugía es altamente exitosa, las personas nacidas con esta condición requieren seguimiento con un cardiólogo especialista en congénitas de por vida, ya que pueden desarrollar problemas de válvulas o arritmias en la edad adulta." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca asistencia médica de emergencia inmediata si el bebé o niño:", items: ["Se pone súbitamente de un color azul profundo o grisáceo", "Respira de forma muy agitada, se muestra extremadamente débil, irritable o sin respuesta", "Sufre un desmayo o pérdida temporal del conocimiento"] } },
'Infecciones de la glándula salival' : { intro: "Las infecciones de la glándula salival (sialadenitis) son inflamaciones dolorosas causadas por infecciones bacterianas o virales en las glándulas que producen la saliva. Las más afectadas suelen ser las glándulas parótidas (delante de las orejas) o las glándulas submandibulares (debajo de la mandíbula).", whatIs: { title: "¿Qué es la Sialadenitis?", text: "Nuestras glándulas salivales producen saliva que fluye hacia la boca a través de pequeños tubos (conductos). Cuando la producción o el flujo de saliva disminuye o se bloquea, el ambiente estancado permite que las bacterias que viven normalmente en la boca asciendan por los conductos hacia la glándula y se multipliquen, causando una infección aguda e hinchazón dolorosa. Los virus, como el de las paperas, también pueden infectar directamente las glándulas a través del torrente sanguíneo." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos de una infección bacteriana aguda son muy llamativos:", groups: [ { name: "Síntomas Locales y Físicos", items: ["Aparición rápida de un bulto muy doloroso, firme e hinchado en la mejilla, frente a la oreja o debajo de la mandíbula", "Enrojecimiento y aumento de la temperatura de la piel sobre la glándula afectada", "Dolor intenso que empeora al abrir la boca, masticar o tragar", "Mal sabor de boca continuo (sabor fétido o salado)", "Supuración de pus visible en el interior de la boca cuando se presiona la glándula inflamada"] }, { name: "Síntomas Generales", items: ["Fiebre alta repentina y escalofríos", "Malestar general y fatiga"] } ], warning: "Si la hinchazón del cuello o la mandíbula es tan grave que causa dificultad para respirar, tragar su propia saliva o hablar, es una emergencia médica extrema." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las bacterias más comunes son *Staphylococcus aureus*, y las infecciones son desencadenadas por la reducción del flujo de saliva debido a:", items: ["Deshidratación severa (muy común en personas mayores frágiles, postoperatorios o personas enfermas que no beben líquidos)", "Cálculos salivales (sialolitiasis): Pequeñas piedras de calcio que se forman y tapan el conducto, estancando la saliva.", "Higiene bucodental deficiente (exceso de bacterias en la boca)", "Enfermedades crónicas, inmunosupresión o trastornos de la alimentación (anorexia)", "Toma de medicamentos que causan sequedad de boca severa (antihistamínicos, antidepresivos, diuréticos)", "Infecciones virales: El virus de las paperas es la causa viral más clásica, aunque también influyen el VIH y el virus de la gripe."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico médico suele ser rápido y clínico:", items: ["Examen físico oral y del cuello (el médico palpará las glándulas para buscar inflamación y exprimirá el conducto dentro de la boca buscando salida de pus)", "Ecografía de las glándulas salivales (muy útil para confirmar la inflamación y buscar si hay cálculos o piedras bloqueando el conducto)", "Tomografía Computarizada (TC) o Resonancia Magnética (RM) (solicitadas si se sospecha que la infección ha formado una bolsa profunda de pus o absceso, o para descartar tumores)", "Cultivo bacteriano (si sale pus de la glándula, se analiza para elegir el antibiótico más efectivo)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento inicial es conservador y busca eliminar la infección y reanudar el flujo de saliva:", subsections: [ { title: "Opciones de Manejo", items: ["Antibióticos orales o intravenosos (si la infección es grave o hay fiebre alta)", "Hidratación agresiva: Beber abundante agua es el paso más importante para forzar la producción de saliva.", "Sialogogos (estimulantes de saliva): Chupar caramelos duros sin azúcar (especialmente los ácidos como el limón) ayuda a que la glándula produzca saliva a la fuerza, 'lavando' el conducto por dentro.", "Medidas de confort: Aplicar compresas calientes sobre la mejilla inflamada, usar analgésicos y masajear suavemente la glándula para estimular el drenaje.", "Cirugía o procedimientos: Si hay un absceso (acumulación de pus), un médico debe hacer un corte para drenarlo. Si hay una piedra atascada que no sale, se puede extraer mediante endoscopia del conducto salival (sialoendoscopia)."] } ], note: "La gran mayoría de las infecciones agudas se curan completamente en una semana con hidratación y antibióticos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico general, dentista u otorrinolaringólogo si:", items: ["Aparece una hinchazón dolorosa en tus mejillas o bajo la mandíbula acompañada de fiebre", "Notas pus o un sabor muy desagradable y persistente en tu boca", "El dolor facial se vuelve insoportable al intentar comer", "Busca urgencias si la inflamación bloquea tus vías respiratorias o te impide tragar líquidos"] } },
'Gangrena' : { intro: "La gangrena es la muerte de tejido corporal como consecuencia de la falta de irrigación sanguínea o a una infección bacteriana grave. Esta condición, que afecta habitualmente a las extremidades pero puede dañar órganos internos, es una emergencia médica crítica.", whatIs: { title: "¿Qué es la Gangrena?", text: "Es una afección potencialmente mortal que ocurre cuando el tejido vivo se necrosa (muere) por isquemia (falta de sangre oxigenada) o por una invasión bacteriana destructiva. Sin sangre, los tejidos no pueden sobrevivir, y las bacterias prosperan en el tejido muerto, propagando toxinas rápidamente por el torrente sanguíneo." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos varían según la causa subyacente y si la piel está involucrada:", groups: [ { name: "Signos Visibles en la Piel", items: ["Decoloración inicial (pálida o roja) que cambia rápidamente a azul, violeta, marrón o negro", "Piel fría al tacto y con aspecto brillante o arrugado", "Aparición de ampollas llenas de líquido (a veces sanguinolento)"] }, { name: "Síntomas Sensoriales y Sistémicos", items: ["Dolor repentino y severo seguido de pérdida total de sensibilidad (entumecimiento)", "Secreción de olor fétido intenso en la zona afectada", "Fiebre, escalofríos y malestar general (signos de sepsis)"] } ], warning: "La gangrena es una emergencia absoluta. Si el tejido muerto se infecta, la infección puede propagarse por todo el cuerpo en horas y resultar fatal." }, types: { title: "Tipos de Gangrena", intro: "Se clasifica principalmente según su apariencia y causa:", items: ["Gangrena seca: El tejido se seca y se vuelve negro. Es común en personas con diabetes o aterosclerosis severa.", "Gangrena húmeda: Hay infección bacteriana, la piel se ampolla, supura y huele mal. Es muy peligrosa por su rápida propagación.", "Gangrena gaseosa: Infección profunda (frecuentemente por la bacteria Clostridium) que produce toxinas y gas atrapado bajo la piel.", "Gangrena interna: Afecta órganos como el intestino o la vesícula biliar por bloqueo del flujo sanguíneo."], note: "La gangrena gaseosa y la húmeda requieren intervención quirúrgica inmediata." }, causes: { title: "Causas y Factores de Riesgo", intro: "Resulta de cualquier condición que bloquee el flujo sanguíneo:", items: ["Diabetes mellitus (causa daño crónico a los nervios y vasos sanguíneos)", "Enfermedad arterial periférica (aterosclerosis severa)", "Traumatismos severos, heridas por aplastamiento o quemaduras graves", "Infecciones de heridas no tratadas", "Congelamiento severo (hipotermia localizada)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico es evidente, pero se requieren pruebas para ver la extensión:", items: ["Análisis de sangre (para buscar recuentos anormalmente altos de glóbulos blancos que indican infección severa)", "Radiografías, Tomografía Computarizada (TC) o Resonancia Magnética (RM) para ver gas en los tejidos o daño muscular profundo", "Arteriografía (para evaluar qué vasos sanguíneos están bloqueados)", "Cultivo de tejido o líquido de la herida (para identificar la bacteria exacta)"], note: "El tratamiento con antibióticos y cirugía no debe retrasarse esperando los resultados del cultivo." }, treatment: { title: "Tratamientos", intro: "El tratamiento implica la eliminación del tejido muerto, combatir la infección y restaurar el flujo de sangre:", subsections: [ { title: "Manejo Quirúrgico y Médico", items: ["Desbridamiento quirúrgico: Extirpación inmediata de todo el tejido muerto para evitar que la infección se propague.", "Amputación: En casos severos, es necesario amputar la extremidad afectada (dedo, pie, pierna) para salvar la vida del paciente.", "Antibióticos intravenosos: Dosis altas y de amplio espectro administradas directamente en vena.", "Terapia de oxígeno hiperbárico: Especialmente útil para la gangrena gaseosa, forzando oxígeno en los tejidos para matar bacterias anaeróbicas.", "Cirugía vascular: Bypass o angioplastia para restaurar el flujo sanguíneo al tejido sano restante."] } ], note: "La rehabilitación física y el apoyo psicológico son fundamentales tras una amputación." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de urgencias más cercana de inmediato si:", items: ["Tienes una herida que cambia de color rápidamente a azul o negro", "Sientes un dolor intenso e inexplicable que de repente se vuelve insensible", "Una herida comienza a supurar un líquido de olor extremadamente desagradable o sientes 'crujidos' bajo la piel"] } },
'Gangrena de tejidos blandos' : { intro: "La gangrena de tejidos blandos, médicamente conocida como fascitis necrotizante o 'infección por la bacteria comecarne', es una infección bacteriana extremadamente agresiva que destruye la piel, la grasa y el tejido que recubre los músculos (fascia).", whatIs: { title: "¿Qué es la Gangrena de Tejidos Blandos?", text: "Es una emergencia quirúrgica letal. Ciertas bacterias (como el estreptococo del grupo A o combinaciones de bacterias) penetran a través de una herida pequeña y liberan toxinas que destruyen los tejidos blandos a un ritmo alarmante (hasta varios centímetros por hora). Esta destrucción masiva de tejido provoca un estado de shock séptico y fallo multiorgánico rápidamente." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos iniciales pueden parecer una simple infección, pero empeoran drásticamente en horas:", groups: [ { name: "Síntomas Locales Críticos", items: ["Dolor agudo e insoportable que es desproporcionado a la apariencia de la herida", "Piel que rápidamente se vuelve roja, luego violeta o negruzca", "Hinchazón severa y rápida, a menudo con piel que se siente caliente y tensa", "Aparición de ampollas llenas de líquido oscuro o sanguinolento", "Crepitación (sensación de estallido de burbujas bajo la piel debido al gas)"] }, { name: "Síntomas Sistémicos", items: ["Fiebre alta, escalofríos y sudoración profusa", "Confusión mental, mareos y debilidad extrema (signos de shock)", "Ritmo cardíaco acelerado (taquicardia)"] } ], warning: "El sello distintivo de esta infección es el dolor extremo en una zona que apenas parece enrojecida en sus etapas iniciales. Requiere cirugía de emergencia." }, types: { title: "Tipos de Fascitis Necrotizante", intro: "Se clasifica por el tipo de bacterias involucradas:", items: ["Tipo I (Polimicrobiana): Causada por una mezcla de bacterias aeróbicas y anaeróbicas; más común en diabéticos y ancianos.", "Tipo II (Monomicrobiana): Causada frecuentemente por Streptococcus pyogenes (Estreptococo del Grupo A) o Staphylococcus aureus (MRSA); puede afectar a personas jóvenes y sanas tras un trauma menor.", "Tipo III: Relacionada con bacterias marinas como Vibrio vulnificus (al exponer heridas al agua de mar cálida)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Las bacterias entran al cuerpo a través de roturas en la piel, facilitadas por:", items: ["Cortes menores, rasguños, picaduras de insectos o heridas punzantes", "Heridas quirúrgicas o traumatismos contusos (incluso sin rotura visible de la piel)", "Inmunosupresión (diabetes no controlada, cáncer, alcoholismo crónico, uso prolongado de esteroides)", "Consumo de drogas intravenosas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico temprano es difícil pero vital; se basa en la alta sospecha clínica:", items: ["Exploración quirúrgica inmediata (el método definitivo para ver el tejido muerto y confirmar el diagnóstico)", "Tomografía Computarizada (TC) o Resonancia Magnética (RM) (para identificar engrosamiento fascial y gas en los tejidos blandos)", "Análisis de sangre (Indicador LRINEC para medir la inflamación sistémica profunda, leucocitosis, daño renal)", "Cultivos de sangre y tejido (para identificar la bacteria, aunque el tratamiento empírico comienza antes)"], note: "No se debe retrasar la cirugía por esperar resultados de imagen si la sospecha clínica es fuerte." }, treatment: { title: "Tratamientos", intro: "El único tratamiento efectivo es la cirugía inmediata combinada con antibióticos:", subsections: [ { title: "Intervenciones de Emergencia", items: ["Desbridamiento quirúrgico radical y temprano: Extracción rápida y completa de todos los tejidos infectados y muertos. A menudo se requieren múltiples cirugías diarias.", "Amputación: En ocasiones, es la única forma de detener la propagación de la infección en una extremidad.", "Antibióticos de amplio espectro en dosis masivas por vía intravenosa (ej. Penicilina, Clindamicina, Vancomicina).", "Soporte hemodinámico intensivo en la UCI (líquidos, vasopresores) para tratar el shock séptico.", "Inmunoglobulina intravenosa (IGIV) para neutralizar las toxinas bacterianas en casos de infección por estreptococo del grupo A."] } ], note: "La recuperación requiere posteriormente injertos de piel y meses de rehabilitación física y psicológica." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias sin dudarlo si:", items: ["Sientes un dolor insoportable alrededor de un corte o rasguño que se propaga rápidamente", "La piel alrededor de una herida se vuelve morada, se ampolla o se hincha visiblemente por horas", "Presentas fiebre alta, confusión y mareos junto con una infección en la piel"] } },
'Adenocarcinoma del estómago' : { intro: "El adenocarcinoma del estómago, o cáncer gástrico, es el tipo más común de cáncer de estómago. Se origina en las células que recubren la capa más interna del estómago (la mucosa), responsables de producir mucosidad y fluidos gástricos.", whatIs: { title: "¿Qué es el Adenocarcinoma del Estómago?", text: "Es un tumor maligno de crecimiento lento que se desarrolla a partir de las glándulas de la mucosa gástrica. Antes de que se forme el cáncer verdadero, a menudo ocurren cambios precancerosos en el revestimiento del estómago durante años. Debido a que rara vez causa síntomas en sus etapas iniciales, con frecuencia se diagnostica en etapas avanzadas cuando el tumor ya ha crecido o se ha diseminado." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas tempranos son vagos y similares a una indigestión, pero a medida que avanza se vuelven graves:", groups: [ { name: "Síntomas Tempranos", items: ["Sensación de plenitud o saciedad después de comer porciones pequeñas (saciedad precoz)", "Indigestión persistente, acidez estomacal severa o eructos constantes", "Náuseas leves y malestar general en la parte superior del abdomen"] }, { name: "Síntomas Avanzados", items: ["Pérdida de peso involuntaria y significativa", "Vómitos frecuentes (con o sin sangre)", "Heces de color negro oscuro, alquitranadas y con muy mal olor (melena, por sangrado interno)", "Dolor abdominal constante y severo", "Dificultad para tragar (disfagia), si el tumor está cerca del esófago", "Hinchazón abdominal por acumulación de líquido (ascitis)"] } ], warning: "La presencia de sangre en los vómitos o heces negras es un signo de sangrado digestivo activo y requiere evaluación médica de urgencia." }, types: { title: "Clasificación de Lauren", intro: "El adenocarcinoma gástrico se divide histológicamente en dos tipos principales:", items: ["Tipo Intestinal: Las células tumorales se asemejan a las del intestino. Es más común en hombres mayores, crece lentamente y suele estar fuertemente asociado a factores ambientales e infecciones (como H. pylori).", "Tipo Difuso: Las células tumorales no forman glándulas, sino que se infiltran y engrosan la pared del estómago de forma dispersa (linitis plástica). Es más agresivo, afecta a personas más jóvenes y tiene un componente genético más fuerte."], note: "El tipo difuso tiene un peor pronóstico debido a su rápida diseminación." }, causes: { title: "Causas y Factores de Riesgo", intro: "El riesgo de desarrollar esta enfermedad aumenta debido a:", items: ["Infección crónica por la bacteria Helicobacter pylori (la causa principal que provoca úlceras e inflamación crónica)", "Dieta alta en alimentos ahumados, salados, encurtidos y baja en frutas y verduras frescas", "Tabaquismo crónico y consumo excesivo de alcohol", "Antecedentes familiares de cáncer gástrico o síndromes genéticos (como el cáncer gástrico difuso hereditario - mutación CDH1)", "Anemia perniciosa y pólipos gástricos previos", "Edad avanzada (más común después de los 65 años)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La visualización directa y la biopsia son esenciales para el diagnóstico:", items: ["Endoscopia superior (EGD): El método principal; permite al médico ver el tumor y extraer tejido (biopsia) para analizarlo bajo el microscopio.", "Tomografía Computarizada (TC) de abdomen y tórax: Para determinar si el cáncer se ha diseminado (metástasis) a ganglios linfáticos, hígado o pulmones.", "Ecografía endoscópica (USE): Para evaluar la profundidad de penetración del tumor en la pared del estómago.", "Tomografía por emisión de positrones (PET): Para detectar áreas de propagación del cáncer en todo el cuerpo.", "Laparoscopia exploratoria: Para buscar pequeños tumores en el abdomen antes de planificar la cirugía principal."], note: "La endoscopia regular es crucial para personas con alto riesgo o antecedentes familiares." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del estadio del cáncer, la ubicación y la salud del paciente:", subsections: [ { title: "Enfoques Terapéuticos", items: ["Cirugía (Gastrectomía): Extirpación parcial (de una parte del estómago) o total (se extirpa todo el estómago y se conecta el esófago al intestino). Es el único tratamiento curativo en etapas tempranas.", "Quimioterapia: Se administra a menudo antes de la cirugía (neoadyuvante) para reducir el tumor y después (adyuvante) para matar células restantes.", "Radioterapia: Generalmente se combina con quimioterapia para tratar tumores localmente avanzados o aliviar síntomas.", "Terapia Dirigida: Medicamentos como el Trastuzumab (para tumores que tienen demasiada proteína HER2) o Ramucirumab (para detener la formación de nuevos vasos sanguíneos tumorales).", "Inmunoterapia: Fármacos que ayudan al sistema inmunitario del cuerpo a reconocer y atacar las células cancerosas (ej. Pembrolizumab)."] } ], note: "Vivir sin estómago requiere cambios radicales en la dieta, ingiriendo comidas muy pequeñas y frecuentes y suplementos vitamínicos inyectables (como la B12)." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un gastroenterólogo inmediatamente si experimentas:", items: ["Pérdida de peso rápida sin haber hecho dieta ni ejercicio", "Sensación de estar lleno rápidamente después de comer porciones muy pequeñas", "Vómitos con sangre o material parecido a los posos del café, o heces muy oscuras"] } },
'Cirrosis biliar primaria' : { intro: "La cirrosis biliar primaria (recientemente renombrada médicamente como Colangitis Biliar Primaria o CBP) es una enfermedad autoinmune crónica del hígado. El sistema inmunológico ataca y destruye lentamente los pequeños conductos biliares dentro del hígado, lo que lleva a la acumulación de toxinas y daño progresivo.", whatIs: { title: "¿Qué es la Colangitis Biliar Primaria?", text: "La bilis es producida por el hígado y ayuda en la digestión. En la CBP, los diminutos conductos que transportan la bilis se inflaman y se destruyen por un ataque autoinmune. Sin una vía de salida, la bilis y sus subproductos tóxicos retroceden y se acumulan en el hígado (colestasis). Con el paso de los años, este daño constante provoca cicatrización permanente del tejido hepático (cirrosis) e insuficiencia hepática terminal." }, symptoms: { title: "Síntomas Comunes", intro: "Aproximadamente la mitad de los pacientes no tienen síntomas al momento del diagnóstico (se detecta en análisis de rutina). Cuando aparecen, incluyen:", groups: [ { name: "Síntomas Tempranos", items: ["Fatiga extrema y debilitante (suele ser el primer y más molesto síntoma)", "Prurito (picazón intensa en la piel), especialmente en las palmas de las manos y las plantas de los pies, que empeora por la noche", "Ojos secos y boca seca (Síndrome de Sjögren secundario)"] }, { name: "Síntomas de Enfermedad Avanzada", items: ["Ictericia (coloración amarilla en piel y ojos)", "Xantomas y xantelasmas (pequeños depósitos de grasa o colesterol bajo la piel, especialmente alrededor de los ojos)", "Dolor o malestar en la parte superior derecha del abdomen", "Oscurecimiento anormal de la piel (hiperpigmentación)", "Hinchazón por retención de líquidos en abdomen (ascitis) o piernas (edema)"] } ], warning: "La CBP también afecta la absorción de grasas y vitaminas, lo que acelera el adelgazamiento severo de los huesos (osteoporosis) y aumenta el riesgo de fracturas tempranas." }, types: { title: "Naturaleza de la Enfermedad", intro: "Es fundamental entender que a pesar de su antiguo nombre:", items: ["No tiene relación con el consumo de alcohol (el término 'cirrosis' causaba mucho estigma social injustificado).", "No todos los pacientes desarrollan cirrosis verdadera. Si se detecta a tiempo, el medicamento ralentiza enormemente la enfermedad.", "Es predominante en el sexo femenino (alrededor del 90% de los pacientes son mujeres de entre 30 y 60 años)."], note: "El cambio de nombre de 'Cirrosis' a 'Colangitis' fue impulsado por asociaciones de pacientes para reflejar mejor la naturaleza real e inicial de la enfermedad." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se considera una enfermedad autoinmune compleja provocada por:", items: ["Factores genéticos (es más común tenerla si un familiar de primer grado, como madre o hermana, la padece)", "Reacción anormal del sistema inmunológico que ataca las células de los conductos biliares como si fueran invasores extraños", "Factores ambientales desencadenantes aún no del todo claros (infecciones bacterianas, productos químicos tóxicos, tabaquismo)", "Presencia de otras enfermedades autoinmunes (enfermedad celíaca, lupus, tiroiditis)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se realiza un diagnóstico combinando varias pruebas médicas:", items: ["Análisis de sangre para función hepática (niveles elevados de Fosfatasa Alcalina - ALP)", "Prueba de Anticuerpos Antimicocondriales (AMA) en sangre (positivos en el 90-95% de los pacientes, es el sello distintivo de la CBP)", "Ecografía abdominal o Elastografía (FibroScan) para evaluar la rigidez del hígado y descartar bloqueos fuera del hígado", "Biopsia hepática (extracción de tejido con aguja; a veces necesaria para confirmar el grado de daño celular y cicatrización)"], note: "Un análisis de sangre AMA positivo junto con niveles altos de ALP a menudo es suficiente para hacer un diagnóstico clínico." }, treatment: { title: "Tratamientos", intro: "No existe cura, pero la progresión puede ralentizarse drásticamente:", subsections: [ { title: "Manejo Médico y Soporte", items: ["Ácido Ursodesoxicólico (UDCA o Urso): El tratamiento de primera línea de por vida. Es un ácido biliar natural que ayuda a mover la bilis fuera del hígado y protege las células hepáticas.", "Ácido Obeticólico (Ocaliva): Se añade si el paciente no responde adecuadamente al UDCA.", "Fibratos (Bezafibrato, Fenofibrato): Medicamentos para el colesterol que también ayudan a reducir la inflamación hepática en la CBP.", "Tratamiento de síntomas: Colestiramina o Rifampicina para la picazón intensa; lágrimas y saliva artificial para la sequedad.", "Suplementos de vitaminas: Dosis altas de calcio, vitamina D y bifosfonatos para tratar y prevenir la osteoporosis severa.", "Trasplante de Hígado: Es la única opción cuando la enfermedad llega a insuficiencia hepática terminal. La CBP tiene excelentes tasas de supervivencia post-trasplante."] } ], note: "Es vital evitar el consumo de alcohol y ciertos medicamentos hepatotóxicos que supongan un estrés adicional para el hígado." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico especialista (hepatólogo) si:", items: ["Sientes una fatiga profunda que no se alivia con el sueño y el descanso", "Sufres de picazón intensa en el cuerpo sin ninguna erupción visible", "Tus exámenes de sangre de rutina muestran niveles de enzimas hepáticas crónicamente elevados sin razón aparente"] } },
'Uña del pie encarnada' : { intro: "Una uña del pie encarnada (conocida médicamente como onicocriptosis) es una afección común y dolorosa que se produce cuando el borde o la esquina de una uña del pie crece hacia adentro, clavándose en la piel suave que la rodea. Ocurre con mayor frecuencia en el dedo gordo del pie.", whatIs: { title: "¿Qué es una Uña Encarnada?", text: "La uña está diseñada para crecer sobre la superficie de la piel del dedo. Cuando el borde lateral se entierra en la piel, el cuerpo lo reconoce como un 'cuerpo extraño', desencadenando una respuesta inflamatoria agresiva. Esto provoca dolor, enrojecimiento y hace que la zona sea extremadamente susceptible a infecciones bacterianas o fúngicas secundarias." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían desde una leve molestia hasta una infección grave:", groups: [ { name: "Signos Iniciales y Moderados", items: ["Dolor y sensibilidad al presionar el dedo, a los lados de la uña", "Enrojecimiento localizado e inflamación (hinchazón) del tejido alrededor de la uña", "Dolor al usar zapatos cerrados o ajustados"] }, { name: "Signos de Infección Severa", items: ["Dolor punzante constante que impide caminar o dormir", "Supuración de líquido amarillento o pus alrededor de la uña", "Sobrecrecimiento de tejido rojizo y sangrante sobre el borde de la uña (granuloma)", "Piel caliente al tacto y olor fétido"] } ], warning: "Si tienes diabetes, mala circulación o inmunidad comprometida, una simple uña encarnada puede convertirse en una infección grave del pie (úlceras, gangrena u osteomielitis). Nunca intentes realizar 'cirugía de baño' tú mismo." }, types: { title: "Etapas de Severidad", intro: "La onicocriptosis se evalúa en grados:", items: ["Etapa 1 (Inflamatoria): Enrojecimiento leve, dolor con la presión, sin pus visible.", "Etapa 2 (Absceso): Dolor agudo, inflamación significativa, infección activa con drenaje de pus o sangre.", "Etapa 3 (Granulación): Infección crónica y formación de tejido de granulación (carne esponjosa rojiza) que cubre parcialmente la uña."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Generalmente es causada por hábitos inadecuados o anatomía:", items: ["Cortar las uñas de los pies demasiado cortas o curvar los bordes en lugar de cortarlas de forma recta", "Usar zapatos o calcetines demasiado apretados que presionan las uñas hacia la piel", "Traumatismos (golpearse el dedo del pie, que alguien lo pise, o actividades como correr o jugar al fútbol)", "Anatomía hereditaria (tener uñas inusualmente curvas, en forma de pinza o demasiado grandes para el dedo)", "Hiperhidrosis (pies excesivamente sudorosos que ablandan la piel alrededor de la uña)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico es muy sencillo y directo:", items: ["Examen físico visual del dedo del pie realizado por un podólogo o médico general", "Radiografías (rara vez necesarias, solo si se sospecha que la infección ha penetrado profundamente hasta el hueso, o por sospecha de un osteocondroma bajo la uña)"], note: "No se requieren análisis de sangre ni de laboratorio en casos estándar." }, treatment: { title: "Tratamientos", intro: "El tratamiento va desde cuidados caseros hasta intervenciones menores en consulta:", subsections: [ { title: "Opciones de Cuidado y Procedimientos", items: ["Tratamiento Casero (Etapa temprana): Remojar el pie en agua tibia con sal de Epsom durante 15-20 min, 3 veces al día. Levantar suavemente el borde de la uña con hilo dental limpio y colocar algodón debajo para evitar que se clave. Usar calzado amplio.", "Antibióticos: Cremas o pastillas recetadas solo si hay una infección bacteriana evidente.", "Cirugía Menor (Avulsión parcial de la uña): El podólogo aplica anestesia local y corta longitudinalmente el trozo de uña que se clava en la piel para extraerlo.", "Matricectomía (Tratamiento Definitivo): Tras extirpar el borde de la uña, se aplica un ácido químico (fenol) o láser en la matriz (raíz) de la uña para destruir esas células. Esto evita que ese lateral vuelva a crecer, resolviendo el problema de forma permanente."] } ], note: "La extirpación completa de toda la uña rara vez se recomienda, ya que causa deformidad y la nueva uña puede tardar un año en crecer con alto riesgo de encarnarse de nuevo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un podólogo o médico de inmediato si:", items: ["Tienes diabetes o problemas circulatorios y notas el dedo rojo o dolorido", "Observas pus, sangre o tejido esponjoso rojo creciendo sobre la uña", "El dolor es intenso, se irradia por el dedo o no ha mejorado tras varios días de cuidados caseros"] } },
'Pólipos cervicales' : { intro: "Los pólipos cervicales son crecimientos pequeños, lisos, rojizos y en forma de dedo que se forman en el cuello uterino (la parte inferior y estrecha del útero que se conecta con la vagina). Son tumores extremadamente comunes, casi siempre benignos (no cancerosos).", whatIs: { title: "¿Qué son los Pólipos Cervicales?", text: "El cuello uterino actúa como un canal entre la vagina y la cavidad uterina. Los pólipos son crecimientos excesivos de tejido que sobresalen de la superficie del canal cervical o del cuello uterino externo. Tienen una consistencia frágil, están muy irrigados por vasos sanguíneos y pueden presentarse solos o en grupos. Dado que en el 99% de los casos son benignos, su mayor problema es causar sangrado o molestias, no el riesgo de cáncer." }, symptoms: { title: "Síntomas Comunes", intro: "Muchas mujeres tienen pólipos y no presentan ningún síntoma (se descubren en chequeos). Cuando causan problemas, los signos incluyen:", groups: [ { name: "Síntomas Hemorrágicos y Secretores", items: ["Sangrado vaginal anormal después de tener relaciones sexuales (el síntoma más común por el roce del pólipo frágil)", "Sangrado o manchado entre los periodos menstruales", "Sangrado vaginal en mujeres que ya han pasado la menopausia", "Periodos menstruales más abundantes de lo normal", "Flujo vaginal excesivo (leucorrea), que puede ser de color blanco o amarillento y, a veces, tener un olor desagradable si el pólipo se infecta"] } ], warning: "Cualquier sangrado vaginal irregular, especialmente después de la menopausia, debe ser evaluado por un médico, ya que también es el síntoma principal de patologías más graves." }, types: { title: "Tipos de Pólipos Cervicales", intro: "Se clasifican según su ubicación de origen:", items: ["Pólipos endocervicales: Crecen desde el interior del canal cervical. Son los más comunes y se observan frecuentemente en mujeres en edad reproductiva.", "Pólipos ectocervicales: Crecen en la capa externa del cuello uterino. Son menos comunes y se ven más a menudo en mujeres posmenopáusicas."], note: "Los pólipos uterinos (endometriales) son diferentes; crecen dentro de la cavidad principal del útero y causan síntomas similares." }, causes: { title: "Causas y Factores de Riesgo", intro: "La causa exacta no se conoce completamente, pero su formación se asocia frecuentemente con:", items: ["Niveles altos o fluctuaciones de estrógenos (como durante el embarazo, o en años reproductivos)", "Inflamación crónica del cuello uterino (cervicitis)", "Infecciones cervicales pasadas o activas (vaginitis, VPH, clamidia)", "Congestión de los vasos sanguíneos en el canal cervical"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico se realiza rutinariamente en el consultorio ginecológico:", items: ["Examen pélvico visual con espéculo (el médico puede ver el pólipo asomando por el cuello uterino como una masa roja en forma de cereza o de dedo)", "Papanicolaou (Pap) o prueba de VPH", "Ecografía transvaginal (para revisar si hay más pólipos más profundos en la cavidad uterina)", "Biopsia de tejido (el pólipo extirpado siempre se envía al laboratorio de patología para confirmar que es benigno y no cáncer)"], note: "Es un hallazgo incidental muy frecuente durante la toma de citologías anuales." }, treatment: { title: "Tratamientos", intro: "La extirpación (polipectomía) es el tratamiento estándar, es rápido y a menudo indoloro:", subsections: [ { title: "Proceso de Extirpación", items: ["Polipectomía en consulta: El ginecólogo sujeta el pólipo con unas pinzas especiales y lo retuerce suavemente hasta que se desprende de su base, o lo corta.", "Cauterización o Nitrato de Plata: Tras la extracción, se aplica calor o un producto químico en la base para detener el sangrado y prevenir infecciones.", "Cirugía ambulatoria o Histeroscopia: Necesaria solo si los pólipos son muy grandes, tienen bases muy gruesas o están ubicados muy adentro del canal o en el útero."] } ], note: "Las mujeres no sienten dolor durante la extracción porque el tejido del pólipo no tiene terminaciones nerviosas, aunque pueden sentir leves calambres similares a la regla." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide cita con tu ginecólogo si presentas:", items: ["Sangrado o manchado vaginal después de las relaciones sexuales, lavados vaginales o fuera de tus días menstruales", "Sangrado de cualquier tipo si ya pasaste por la menopausia", "Secreción vaginal maloliente y abundante de forma repentina"] } },
'Demencia senil' : { intro: "El término 'demencia senil' es una expresión médica antigua y actualmente obsoleta que se usaba para describir la pérdida de memoria en personas mayores. Hoy en día, la comunidad médica se refiere a esto como Trastornos Neurocognitivos Mayores, siendo la Enfermedad de Alzheimer el tipo más común.", whatIs: { title: "¿Qué son los Trastornos Neurocognitivos Mayores?", text: "La demencia no es una enfermedad única, sino un término general para describir un grupo de síntomas que afectan gravemente la memoria, el pensamiento, el comportamiento y las habilidades sociales, hasta el punto de interferir significativamente con la vida diaria y la independencia de la persona. No es una parte normal del envejecimiento, sino el resultado de un daño físico progresivo a las células cerebrales." }, symptoms: { title: "Síntomas y Señales Tempranas", intro: "Los síntomas varían según la causa, pero a menudo incluyen de manera progresiva:", groups: [ { name: "Cambios Cognitivos", items: ["Pérdida de memoria a corto plazo (hacer la misma pregunta repetidamente o perder objetos constantemente)", "Dificultad para encontrar las palabras adecuadas, seguir instrucciones o comunicarse", "Dificultad en la planificación, organización o resolución de problemas complejos (como manejar las finanzas)", "Confusión y desorientación en lugares conocidos, fechas o temporadas", "Falta de coordinación motora y funciones espaciales (perderse al conducir)"] }, { name: "Cambios Psicológicos y de Comportamiento", items: ["Cambios repentinos y drásticos en la personalidad y el estado de ánimo (irritabilidad, apatía, depresión)", "Paranoia, agitación o comportamiento inapropiado sin razón aparente", "Alucinaciones o ideas delirantes en etapas avanzadas"] } ], warning: "La aparición repentina de confusión severa en un adulto mayor (en cuestión de horas o días) no suele ser demencia progresiva, sino 'delirium', a menudo causado por infecciones urinarias, medicamentos o deshidratación; es una urgencia médica." }, types: { title: "Tipos Comunes de Demencia", intro: "Las enfermedades específicas que causan demencia incluyen:", items: ["Enfermedad de Alzheimer (causa el 60-80% de los casos; se caracteriza por placas de proteínas y ovillos en el cerebro que destruyen las neuronas lentamente)", "Demencia Vascular (causada por daño a los vasos sanguíneos del cerebro, infartos cerebrales múltiples o problemas de flujo sanguíneo)", "Demencia con Cuerpos de Lewy (provoca alucinaciones visuales, problemas de sueño y síntomas similares al Parkinson)", "Demencia Frontotemporal (afecta principalmente la personalidad, el comportamiento y el lenguaje en edades más tempranas, entre 40 y 65 años)", "Demencia Mixta (tener más de un tipo de demencia a la vez, común en ancianos)"], note: "Algunas causas raras de demencia son reversibles, como las deficiencias graves de vitamina B12 o los problemas de tiroides." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño neurológico está fuertemente influenciado por:", items: ["Edad avanzada (el mayor riesgo conocido, sobre todo después de los 65 años)", "Antecedentes familiares y mutaciones genéticas específicas", "Salud cardiovascular deficiente (hipertensión no controlada, colesterol alto, diabetes, tabaquismo y obesidad aumentan el riesgo de demencia vascular y Alzheimer)", "Traumatismos craneoencefálicos graves o repetitivos", "Consumo crónico y excesivo de alcohol"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Evaluar la demencia requiere un enfoque multidisciplinario exhaustivo:", items: ["Evaluaciones cognitivas y neuropsicológicas detalladas (MME, MoCA) para medir la memoria, el razonamiento y las habilidades de lenguaje", "Evaluación psiquiátrica (para descartar depresión severa, conocida como 'pseudodemencia')", "Análisis de sangre y pruebas de laboratorio completas (para descartar causas reversibles como fallos renales, tiroideos o falta de vitaminas)", "Pruebas de imagen cerebral como Resonancia Magnética (RM) o Tomografía por Emisión de Positrones (PET) para detectar atrofia cerebral, tumores, hemorragias o placas de amiloide"], note: "" }, treatment: { title: "Tratamientos", intro: "No existe cura para la mayoría de las demencias progresivas, pero hay tratamientos para mejorar la calidad de vida:", subsections: [ { title: "Manejo Médico y Soporte", items: ["Medicamentos Inhibidores de la Colinesterasa (Donepezilo, Rivastigmina): Para mejorar temporalmente los síntomas en el Alzheimer de leve a moderado.", "Memantina: Utilizada para el Alzheimer moderado a severo para regular el glutamato en el cerebro.", "Nuevas terapias inmunológicas (Lecanemab): Anticuerpos monoclonales que intentan eliminar las placas de amiloide en etapas tempranas.", "Medicamentos psiquiátricos: Para tratar la depresión profunda, los trastornos del sueño, la agitación severa o las alucinaciones.", "Terapia ocupacional y modificación del entorno: Para hacer que el hogar sea más seguro, evitar caídas y fomentar la independencia guiada.", "Grupos de apoyo y respiro: Fundamentales para los cuidadores familiares, que enfrentan un alto nivel de desgaste físico y emocional."] } ], note: "La planificación legal y financiera anticipada es crucial en las primeras etapas del diagnóstico, cuando el paciente aún puede tomar decisiones." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Lleva a tu familiar a una evaluación neurológica si observas:", items: ["Problemas de memoria consistentes que afectan el desarrollo de su vida diaria (como olvidar cómo cocinar o perder el camino a casa)", "Dificultad inexplicable para manejar tareas financieras o realizar cálculos simples", "Cambios marcados en su juicio, higiene personal o comportamiento habitual"] } },
'Cáncer de vagina' : { intro: "El cáncer de vagina es un tipo de cáncer poco frecuente que se origina en los tejidos de la vagina, el conducto muscular que conecta el útero con el exterior del cuerpo. Aunque el cáncer que comienza directamente en la vagina (cáncer primario) es muy raro, a menudo otros tipos de cáncer (como el de cuello uterino, vulva o recto) pueden propagarse a esta zona (cáncer secundario).", whatIs: { title: "¿Qué es el Cáncer de Vagina?", text: "Es un crecimiento descontrolado de células malignas en el revestimiento o las paredes vaginales. Antes de convertirse en un cáncer invasivo, las células vaginales pueden sufrir cambios precancerosos durante años, conocidos como neoplasia intraepitelial vaginal (VAIN). El diagnóstico temprano en estas fases previas, frecuentemente mediante citologías, permite un tratamiento altamente exitoso." }, symptoms: { title: "Síntomas Comunes", intro: "En las primeras etapas, el cáncer de vagina a menudo no causa síntomas. A medida que progresa, puede provocar:", groups: [ { name: "Síntomas Locales y Hemorrágicos", items: ["Sangrado vaginal inusual, especialmente después de tener relaciones sexuales o sangrado en mujeres que ya han pasado la menopausia", "Flujo vaginal anormal, acuoso o sanguinolento, a menudo con un olor desagradable", "Presencia de un bulto palpable o una masa sólida en el canal vaginal", "Dolor pélvico persistente, dolor durante las relaciones sexuales o dolor en la zona vaginal"] }, { name: "Síntomas por Propagación (Etapas Avanzadas)", items: ["Dolor o dificultad al orinar (si el tumor presiona la uretra o vejiga)", "Estreñimiento severo, dolor al defecar o sangre en las heces (si presiona el recto)", "Hinchazón en las piernas"] } ], warning: "Cualquier sangrado vaginal que ocurra después de la menopausia es una señal de advertencia crítica de posibles afecciones ginecológicas malignas y requiere investigación inmediata." }, types: { title: "Tipos Histológicos", intro: "El cáncer de vagina se clasifica según el tipo de célula en el que comienza:", items: ["Carcinoma de células escamosas: Constituye el 85-90% de los casos. Se desarrolla en el revestimiento plano y delgado (células escamosas) de la vagina. Crece lentamente cerca del cuello uterino y está muy ligado a la edad y al VPH.", "Adenocarcinoma: Comienza en las células glandulares vaginales. Es más raro y afecta a mujeres más jóvenes. Un tipo muy específico (adenocarcinoma de células claras) afecta a mujeres cuyas madres tomaron el fármaco DES durante el embarazo.", "Melanoma vaginal: Se desarrolla en las células productoras de pigmento; es extremadamente raro y agresivo.", "Sarcoma: Se forma en las células musculares o del tejido conectivo profundo de las paredes vaginales."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Aunque la causa exacta de la mutación no siempre es clara, los factores de riesgo incluyen:", items: ["Infección por el Virus del Papiloma Humano (VPH): El factor de riesgo más importante (responsable de la mayoría de los carcinomas de células escamosas).", "Antecedentes de cáncer cervical o lesiones precancerosas en el cuello uterino (ya que comparten los mismos tejidos y riesgos de VPH).", "Edad avanzada (la mayoría de los casos ocurren en mujeres mayores de 60 años).", "Exposición al dietilestilbestrol (DES) en el útero materno (un fármaco recetado a embarazadas en la década de 1950, que causa el tipo de células claras).", "Tabaquismo e infección por VIH (debilitan el sistema inmunológico, permitiendo que las infecciones por VPH persistan y causen cáncer)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una inspección cuidadosa de los tejidos ginecológicos:", items: ["Examen pélvico y prueba de Papanicolaou (Pap): La prueba de Pap puede detectar células vaginales y cervicales anormales antes de que causen síntomas.", "Colposcopia: Uso de un instrumento con aumento y luz para examinar detalladamente la vagina y el cuello uterino, aplicando líquidos especiales que resaltan áreas anormales.", "Biopsia de tejido: Extracción de una pequeña muestra de tejido sospechoso para su análisis bajo el microscopio (el único método para confirmar el cáncer).", "Pruebas de imagen (TC, RM o PET): Para determinar la etapa del cáncer y si se ha diseminado a ganglios linfáticos u otros órganos pélvicos.", "Cistoscopia y proctoscopia: Para revisar si el cáncer ha invadido la vejiga o el recto adyacentes."], note: "" }, treatment: { title: "Tratamientos", intro: "El plan de tratamiento depende de la etapa, la ubicación del tumor y si hay deseo de preservar la anatomía sexual o la fertilidad:", subsections: [ { title: "Opciones Oncológicas", items: ["Cirugía: Va desde la escisión local amplia (tumores pequeños y precánceres) hasta la vaginectomía parcial o total (extirpación de parte o toda la vagina). En algunos casos, se puede realizar cirugía reconstructiva vaginal posteriormente.", "Radioterapia: Es el tratamiento principal y más común para la mayoría de los cánceres vaginales invasivos. Incluye radiación externa o braquiterapia (colocación de fuentes radiactivas directamente en la vagina).", "Quimioterapia: Usualmente se administra en combinación con la radioterapia para aumentar su eficacia (quimiorradiación), o para tratar tumores en etapas avanzadas.", "Láser o tratamientos tópicos: Utilizados únicamente para las lesiones precancerosas (VAIN) para destruir el revestimiento anormal sin cirugía mayor."] } ], note: "La vacuna contra el VPH es la herramienta de prevención más efectiva contra las lesiones precancerosas y el cáncer escamoso de vagina." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Programa una cita con tu ginecólogo de inmediato si:", items: ["Presentas cualquier tipo de sangrado vaginal inesperado o inusual (especialmente si no tienes la regla o ya pasaste la menopausia)", "Notas una masa, llaga o engrosamiento en la vagina", "Experimentas dolor pélvico o vaginal que no desaparece"] } },
'Acidosis metabólica' : { intro: "La acidosis metabólica es un trastorno del equilibrio ácido-base en el cual el cuerpo produce demasiado ácido o los riñones no logran eliminarlo adecuadamente, reduciendo el pH de la sangre.", whatIs: { title: "¿Qué es la Acidosis Metabólica?", text: "Es una condición clínica grave que indica un problema subyacente. Cuando los fluidos corporales contienen demasiado ácido, el funcionamiento celular se altera, pudiendo afectar el sistema cardiovascular y neurológico." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen de la causa y la gravedad:", groups: [ { name: "Signos Clínicos", items: ["Respiración rápida y profunda (respiración de Kussmaul)", "Confusión, letargo o fatiga extrema", "Dolor de cabeza", "Náuseas, vómitos y falta de apetito"] } ], warning: "La acidosis metabólica severa puede conducir a un estado de shock o coma si no se trata rápidamente." }, types: { title: "Tipos y Causas", intro: "Se clasifica según el mecanismo que genera el ácido:", items: ["Cetoacidosis diabética (por falta de insulina en la diabetes)", "Acidosis láctica (por falta de oxígeno en los tejidos, shock o sepsis)", "Acidosis hiperclorémica (pérdida severa de bicarbonato por diarrea prolongada)", "Acidosis renal (falla de los riñones para excretar ácido)"], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se requiere análisis de sangre y orina:", items: ["Gasometría arterial (para medir el pH, oxígeno y dióxido de carbono)", "Panel metabólico básico (para calcular la brecha aniónica o 'anion gap')", "Examen de cetonas en orina o sangre"] }, treatment: { title: "Tratamientos", intro: "El objetivo es tratar la condición subyacente que causa la acidez:", subsections: [ { title: "Opciones de manejo", items: ["Bicarbonato de sodio intravenoso (solo en casos específicos y severos)", "Administración de insulina y líquidos (para la cetoacidosis diabética)", "Tratamiento de infecciones o mejora de la oxigenación (para la acidosis láctica)", "Diálisis (si los riñones están fallando)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias inmediatamente si presentas:", items: ["Respiración inusualmente rápida y profunda", "Confusión extrema, somnolencia profunda o incapacidad para despertar", "Aliento con olor afrutado (signo de cetoacidosis)"] } },
'Apnea en recién nacidos' : { intro: "La apnea neonatal es una pausa en la respiración que dura 20 segundos o más, o una pausa más corta acompañada de una disminución en la frecuencia cardíaca (bradicardia) o cambios en el color de la piel.", whatIs: { title: "¿Qué es la Apnea Neonatal?", text: "Es una condición común en los bebés prematuros debido a la inmadurez del centro respiratorio en el cerebro. El bebé literalmente 'olvida' respirar por unos momentos, lo que reduce los niveles de oxígeno en su sangre." }, symptoms: { title: "Síntomas y Signos", intro: "Durante un episodio de apnea, el bebé puede presentar:", groups: [ { name: "Signos de Alarma", items: ["Pausas respiratorias prolongadas (ausencia de movimiento en el pecho)", "Bradicardia (latidos cardíacos anormalmente lentos)", "Cianosis (coloración azulada o violácea en labios, rostro o cuerpo)", "Palidez extrema o flacidez muscular (hipotonía)"] } ], warning: "Las apneas frecuentes o prolongadas requieren monitoreo hospitalario en la Unidad de Cuidados Intensivos Neonatales (UCIN)." }, types: { title: "Tipos de Apnea", intro: "Se clasifica según su mecanismo:", items: ["Central (el cerebro no envía la señal para respirar, común en prematuros)", "Obstructiva (hay un bloqueo en las vías respiratorias que impide el flujo de aire)", "Mixta (una combinación de ambas, el tipo más frecuente en prematuros)"], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La principal causa es la prematuridad, pero también puede ser provocada por:", items: ["Infecciones (sepsis, meningitis)", "Problemas metabólicos (bajo nivel de azúcar o calcio)", "Reflujo gastroesofágico", "Anomalías en el cerebro o hemorragias", "Problemas de temperatura (enfriamiento o sobrecalentamiento)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico se basa en el monitoreo continuo:", items: ["Monitores cardiorrespiratorios y oximetría de pulso", "Análisis de sangre para descartar infecciones o desequilibrios metabólicos", "Radiografía de tórax o ecografía cerebral si se sospechan otras complicaciones"] }, treatment: { title: "Tratamientos", intro: "El manejo depende de la causa y la frecuencia de los episodios:", subsections: [ { title: "Opciones Médicas", items: ["Estimulación táctil suave (frotar la espalda o golpear las plantas de los pies para recordarle al bebé que respire)", "Citrato de cafeína (medicamento estándar para estimular el centro respiratorio del cerebro)", "Soporte respiratorio no invasivo (CPAP) para mantener las vías aéreas abiertas", "Ventilación mecánica (solo en casos severos donde la medicación y el CPAP no son suficientes)"] } ], note: "La mayoría de los bebés prematuros superan la apnea de la prematuridad a medida que sus cerebros maduran, generalmente cerca de su fecha de parto original." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Si el bebé ya está en casa y notas:", items: ["Pausas en la respiración en las que el bebé se pone azul o pálido", "El bebé no responde o permanece flácido al tocarlo suavemente (Llama al 911 e inicia RCP si estás capacitado)"] } },
'Vaginitis' : { intro: "La vaginitis es una inflamación de la vagina que puede provocar secreción anormal, picazón, irritación y dolor. Es una afección muy común que la mayoría de las mujeres experimentará en algún momento de su vida.", whatIs: { title: "¿Qué es la Vaginitis?", text: "Normalmente, la vagina tiene un equilibrio saludable de bacterias (flora vaginal). Cuando este equilibrio se altera debido a infecciones, cambios hormonales o productos químicos irritantes, se produce una inflamación que altera el flujo vaginal y causa malestar en la zona íntima." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían según la causa, pero generalmente incluyen:", groups: [ { name: "Síntomas Locales", items: ["Cambio en el color, olor o cantidad del flujo vaginal", "Picazón, ardor o irritación intensa en la vagina y la vulva", "Dolor durante las relaciones sexuales (dispareunia)", "Ardor al orinar (disuria)", "Leve sangrado o manchado vaginal"] } ], warning: "No se recomienda el uso de duchas vaginales, ya que empeoran la condición al destruir las bacterias buenas protectoras." }, types: { title: "Tipos Principales", intro: "Existen tres causas infecciosas principales:", items: ["Vaginosis bacteriana: Alteración del equilibrio de bacterias; flujo blanco/grisáceo con olor a pescado.", "Infección por hongos (Candidiasis): Crecimiento excesivo de levaduras; flujo espeso y blanco (como requesón) con mucha picazón.", "Tricomoniasis: Infección de transmisión sexual por un parásito; flujo amarillo-verdoso, espumoso y con mal olor.", "Vaginitis atrófica: Causada por niveles bajos de estrógenos (menopausia), que adelgazan y secan la mucosa vaginal."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El ginecólogo evaluará la zona pélvica:", items: ["Examen pélvico visual", "Análisis de una muestra de secreción vaginal bajo el microscopio (frotis en fresco)", "Pruebas de pH vaginal", "Cultivos vaginales o pruebas moleculares (PCR) en casos recurrentes o dudosos"] }, treatment: { title: "Tratamientos", intro: "El tratamiento depende estrictamente de la causa diagnosticada:", subsections: [ { title: "Opciones de manejo", items: ["Para la Vaginosis Bacteriana: Antibióticos orales o en gel/crema vaginal (Metronidazol o Clindamicina).", "Para la Candidiasis: Medicamentos antifúngicos (cremas, óvulos de venta libre, o una pastilla oral como el Fluconazol).", "Para la Tricomoniasis: Antibiótico oral en dosis única (Metronidazol o Tinidazol) para la paciente y su pareja sexual.", "Para la Vaginitis Atrófica: Cremas, anillos o tabletas de estrógeno vaginal."] } ], note: "Es crucial no automedicarse sin un diagnóstico claro, ya que tratar una infección bacteriana con crema para hongos no funcionará y puede empeorar los síntomas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a consulta ginecológica si:", items: ["Es la primera vez que presentas síntomas vaginales inusuales", "Tienes fiebre, escalofríos o dolor pélvico profundo", "Tienes una nueva pareja sexual (podría ser una ITS)", "Has probado tratamientos de venta libre para hongos y tus síntomas persisten"] } },
'Tuberculosis' : { intro: "La tuberculosis (TB) es una enfermedad infecciosa bacteriana y potencialmente grave que afecta principalmente a los pulmones, aunque puede atacar cualquier órgano del cuerpo. Se propaga a través del aire de una persona a otra.", whatIs: { title: "¿Qué es la Tuberculosis?", text: "Es causada por la bacteria *Mycobacterium tuberculosis*. Cuando una persona infectada tose o estornuda, libera pequeñas gotas con bacterias que otra persona puede inhalar. La TB puede existir en estado 'latente' (la bacteria duerme en el cuerpo sin causar enfermedad) o 'activa' (la bacteria se multiplica, destruye los tejidos y es contagiosa)." }, symptoms: { title: "Síntomas de la TB Activa", intro: "Los síntomas pulmonares clásicos se desarrollan gradualmente a lo largo de semanas:", groups: [ { name: "Síntomas Pulmonares y Sistémicos", items: ["Tos severa y persistente que dura 3 semanas o más", "Tos con expulsión de sangre (hemoptisis) o esputo espeso", "Dolor en el pecho o dolor al respirar o toser", "Fiebre y escalofríos", "Sudores nocturnos profusos (empapan la ropa y sábanas)", "Pérdida de peso inexplicable y falta de apetito", "Fatiga extrema y debilidad"] } ], warning: "La tuberculosis activa sin tratamiento puede ser mortal, ya que la infección destruye los pulmones y puede diseminarse al cerebro, la columna vertebral o los riñones." }, causes: { title: "Factores de Riesgo", intro: "Las bacterias se transmiten por el aire, pero el riesgo de desarrollar TB activa aumenta por:", items: ["Tener el sistema inmunológico debilitado (personas con VIH/SIDA, diabetes severa, en tratamiento con quimioterapia o inmunosupresores)", "Contacto estrecho y prolongado con alguien que tiene TB activa y no recibe tratamiento", "Vivir o viajar a regiones donde la TB es endémica (África, Asia, Europa del Este)", "Vivir o trabajar en instalaciones concurridas (cárceles, hogares de ancianos, refugios)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Existen pruebas tanto para detectar la infección como para confirmar la enfermedad activa:", items: ["Prueba cutánea de la tuberculina (PPD o Mantoux) o análisis de sangre (IGRA) para detectar si hay bacterias en el cuerpo", "Radiografía de tórax (para buscar daños, cavidades o nódulos en los pulmones si la prueba cutánea es positiva)", "Baciloscopia y cultivo de esputo (analizar la flema en el laboratorio para ver y cultivar la bacteria; confirma la TB activa y orienta qué antibióticos funcionarán)", "Pruebas moleculares rápidas (GeneXpert) para detectar material genético de la bacteria y resistencias a medicamentos"] }, treatment: { title: "Tratamientos", intro: "La TB es curable, pero requiere un tratamiento antibiótico muy estricto y prolongado:", subsections: [ { title: "Protocolo de Medicación", items: ["Tratamiento para TB Activa: Combinación de 4 antibióticos potentes (Isoniazida, Rifampicina, Etambutol y Pirazinamida) tomados diariamente durante 6 a 9 meses.", "Tratamiento para TB Latente: Generalmente se toma 1 o 2 medicamentos durante 3 a 9 meses para evitar que la bacteria despierte en el futuro.", "Aislamiento Respiratorio: Las personas con TB activa pulmonar deben quedarse en casa e isolarse durante las primeras semanas de tratamiento hasta que los médicos confirmen que ya no son contagiosas.", "Terapia de Observación Directa (DOTS): Un trabajador de la salud supervisa que el paciente tome cada dosis para evitar el fracaso del tratamiento y la creación de cepas resistentes."] } ], note: "Interrumpir el tratamiento antes de tiempo causa Tuberculosis Multidrogorresistente (TB-MDR), que es extremadamente difícil, larga y costosa de curar." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita atención médica urgente si:", items: ["Tienes una tos constante por más de tres semanas, especialmente si hay manchas de sangre", "Experimentas pérdida de peso rápida, sudores nocturnos intensos y fiebre crónica", "Has estado en contacto cercano con alguien diagnosticado con Tuberculosis"] } },
'Herpes genital' : { intro: "El herpes genital es una infección de transmisión sexual (ITS) muy común causada por el virus del herpes simple (VHS). Causa llagas dolorosas en la zona genital y, una vez contraído, el virus permanece en el cuerpo de por vida, pudiendo causar brotes recurrentes.", whatIs: { title: "¿Qué es el Herpes Genital?", text: "Es una infección viral crónica. El virus entra al cuerpo por pequeñas grietas en la piel o mucosas durante las relaciones sexuales. Tras un primer brote (que suele ser el más doloroso), el virus viaja por los nervios hasta la médula espinal donde se queda 'dormido' (latente). Factores como el estrés, la menstruación o la fatiga pueden 'despertarlo', haciendo que viaje de vuelta a la piel y cause nuevas llagas." }, symptoms: { title: "Síntomas de los Brotes", intro: "Muchas personas no tienen síntomas o son tan leves que no los notan, pero cuando ocurren incluyen:", groups: [ { name: "Primer Brote (Primoinfección)", items: ["Aparición de pequeñas ampollas agrupadas, úlceras o llagas dolorosas en los genitales, ano o muslos", "Dolor intenso, picazón o ardor en el área afectada", "Dolor al orinar (si la orina toca las llagas abiertas)", "Síntomas similares a la gripe: fiebre, dolores musculares, dolor de cabeza", "Ganglios linfáticos inflamados y sensibles en la ingle"] }, { name: "Brotes Recurrentes", items: ["Suelen ser más cortos y menos dolorosos que el primero", "A menudo van precedidos por 'pródromos' (sensación de hormigueo, ardor o dolor en los glúteos o piernas) horas o días antes de que aparezcan las ampollas"] } ], warning: "El herpes genital aumenta el riesgo de contraer otras ITS, incluido el VIH, ya que las llagas abiertas facilitan la entrada de otros virus al cuerpo." }, types: { title: "Tipos de Virus", intro: "Existen dos cepas principales del virus:", items: ["VHS tipo 2: Es la causa clásica y más común del herpes genital. Se propaga por contacto sexual.", "VHS tipo 1: Tradicionalmente causa el herpes labial (fuego labial). Sin embargo, hoy en día es una causa muy frecuente de herpes genital, transmitido a través del sexo oral desde alguien con una llaga en la boca."], note: "Ambos tipos pueden transmitirse incluso cuando no hay llagas visibles en la piel." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El médico puede diagnosticarlo mediante:", items: ["Examen físico visual de las llagas durante un brote activo", "Cultivo viral o prueba de PCR: Se toma una muestra del líquido de la llaga (la prueba más precisa para confirmar el tipo de virus)", "Análisis de sangre (detecta anticuerpos contra el VHS-1 y VHS-2 para saber si has estado expuesto en el pasado, útil si no tienes síntomas activos)"], note: "" }, treatment: { title: "Tratamientos", intro: "No existe cura para el herpes, pero los medicamentos pueden controlar los síntomas y reducir la transmisión:", subsections: [ { title: "Manejo Médico", items: ["Medicamentos antivirales orales (Aciclovir, Valaciclovir o Famciclovir)", "Terapia episódica: Tomar antivirales a la primera señal de un brote (hormigueo) para acortar su duración y disminuir el dolor.", "Terapia supresiva: Tomar antivirales diariamente para reducir significativamente la frecuencia de los brotes y disminuir el riesgo de transmitir el virus a la pareja sexual.", "Baños de asiento con agua tibia y sal, y usar ropa interior de algodón suelta para aliviar el dolor durante los brotes."] } ], note: "Las mujeres embarazadas con herpes genital deben informar a su médico, ya que puede requerirse medicación preventiva o cesárea para evitar transmitir el virus al bebé durante el parto." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico o clínica de salud sexual si:", items: ["Notas cualquier ampolla, úlcera, bulto doloroso o erupción inusual en tus genitales", "Experimentas ardor muy doloroso al orinar", "Tu pareja ha sido diagnosticada recientemente con herpes genital o labial"] } },
'Hipertensión arterial pulmonar' : { intro: "La hipertensión arterial pulmonar (HAP) es un tipo específico y raro de presión arterial alta que afecta exclusivamente a las arterias de los pulmones y al lado derecho del corazón.", whatIs: { title: "¿Qué es la HAP?", text: "A diferencia de la hipertensión común, en la HAP los vasos sanguíneos finos de los pulmones se vuelven estrechos, rígidos o se bloquean. Esto dificulta el paso de la sangre, lo que aumenta drásticamente la presión dentro de estas arterias pulmonares. Para compensar la resistencia, el ventrículo derecho del corazón debe bombear con mucha más fuerza, lo que finalmente hace que el músculo cardíaco se debilite, se agrande y falle (cor pulmonale)." }, symptoms: { title: "Síntomas Comunes", intro: "En las primeras etapas, es posible que no se noten síntomas. A medida que avanza la enfermedad, pueden aparecer:", groups: [ { name: "Síntomas Cardiorrespiratorios", items: ["Falta de aire (disnea), inicialmente al hacer ejercicio y, finalmente, en reposo", "Fatiga extrema y debilidad progresiva", "Mareos, sensación de desvanecimiento o desmayos (síncope) al realizar esfuerzo físico", "Dolor o presión en el pecho", "Hinchazón (edema) en los tobillos, las piernas y, con el tiempo, en el abdomen (ascitis)", "Coloración azulada en los labios o la piel (cianosis)"] } ], warning: "La aparición de desmayos al hacer esfuerzo físico es un signo de gravedad que indica que el corazón ya no puede bombear sangre suficiente a través de los pulmones estenosados." }, causes: { title: "Causas y Factores de Riesgo", intro: "La HAP puede ser idiopática (sin causa conocida) o asociarse a:", items: ["Mutaciones genéticas hereditarias (HAP hereditaria)", "Enfermedades del tejido conectivo (Esclerodermia, Lupus)", "Enfermedades cardíacas congénitas", "Infección por VIH o cirrosis hepática", "Uso de ciertas drogas ilícitas o medicamentos (como pastillas para adelgazar, ej. fenfluramina)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un diagnóstico complejo que requiere descartar otras causas de falta de aire:", items: ["Ecocardiograma (la prueba inicial clave para estimar la presión pulmonar y ver el tamaño del corazón derecho)", "Cateterismo cardíaco derecho (el estándar de oro obligatorio para confirmar el diagnóstico y medir exactamente la presión dentro de la arteria pulmonar)", "Pruebas de función pulmonar y Tomografía Computarizada (TC) de tórax de alta resolución", "Gammagrafía de ventilación/perfusión (V/Q) para descartar coágulos crónicos en los pulmones"], note: "El diagnóstico temprano es difícil porque los síntomas imitan los del asma o la mala condición física." }, treatment: { title: "Tratamientos", intro: "No tiene cura, pero tratamientos complejos pueden mejorar los síntomas y retrasar la progresión:", subsections: [ { title: "Opciones de Manejo Especializado", items: ["Vasodilatadores específicos para los pulmones: Fármacos que abren las arterias pulmonares estrechadas (ej. Epoprostenol por bomba intravenosa continua, Sildenafilo, Bosentán, Iloprost).", "Diuréticos: Para eliminar la acumulación de líquido en piernas y abdomen.", "Anticoagulantes: Para prevenir la formación de coágulos de sangre en los pequeños vasos pulmonares.", "Oxigenoterapia suplementaria: Para ayudar a reducir la presión arterial pulmonar en algunos pacientes.", "Septostomía auricular o Trasplante de pulmón/corazón: En casos severos que no responden a la medicación máxima."] } ], note: "Las mujeres con HAP deben evitar el embarazo, ya que el riesgo de muerte materna es extremadamente alto debido al estrés cardiovascular." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita evaluación cardiológica o neumológica si presentas:", items: ["Falta de aire inexplicable o progresiva durante tus rutinas diarias", "Mareos que te llevan al borde del desmayo al caminar rápido o subir escaleras", "Hinchazón inusual en tobillos y piernas sin razón aparente"] } },
'Endotropía' : { intro: "La endotropía (comúnmente llamada 'bizquera') es el tipo más frecuente de estrabismo, en el cual uno o ambos ojos se desvían hacia adentro, en dirección a la nariz.", whatIs: { title: "¿Qué es la Endotropía?", text: "Es una desalineación de los ojos. Cuando los ojos no apuntan al mismo objeto a la vez, el cerebro recibe dos imágenes diferentes. Para evitar la visión doble, el cerebro de los niños pequeños a menudo aprende a ignorar (suprimir) la imagen que proviene del ojo desviado. Si esto no se corrige a tiempo, el ojo desviado puede perder visión de forma permanente, una condición conocida como ambliopía (ojo vago)." }, symptoms: { title: "Síntomas y Signos", intro: "El signo más evidente es la apariencia de los ojos, pero también incluye:", groups: [ { name: "Signos Visuales y de Conducta", items: ["Uno o ambos ojos están girados hacia adentro (puede ser constante o intermitente al enfocar o estar cansado)", "Falta de coordinación en los movimientos oculares", "El niño entorna los ojos o se los frota constantemente", "Inclinación o giro persistente de la cabeza para intentar ver con claridad (tortícolis ocular)", "Quejas de visión doble (diplopía), más común si aparece en niños mayores o adultos"] } ], warning: "Los bebés recién nacidos pueden cruzar los ojos esporádicamente, pero cualquier desviación ocular que persista después de los 3 o 4 meses de edad requiere una evaluación oftalmológica completa." }, types: { title: "Tipos de Endotropía", intro: "Se clasifica según su origen y momento de aparición:", items: ["Endotropía congénita (infantil): Aparece antes de los 6 meses. Los ojos suelen estar muy cruzados y los bebés a menudo alternan el ojo con el que miran.", "Endotropía acomodativa: Aparece generalmente entre los 2 y 4 años. Se debe a un esfuerzo de enfoque extremo causado por una hipermetropía alta no corregida. Al hacer un gran esfuerzo por ver de cerca, los ojos se cruzan hacia adentro.", "Endotropía adquirida: Aparece repentinamente en niños mayores o adultos, a menudo debido a problemas neurológicos, traumatismos, tumores o enfermedades vasculares (diabetes)."], note: "" }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El oftalmólogo pediátrico evaluará la visión y el alineamiento:", items: ["Examen completo de agudeza visual", "Examen de motilidad ocular y medición de la desviación mediante prismas", "Examen de refracción bajo cicloplejia (usando gotas que dilatan la pupila y paralizan el enfoque para medir la necesidad real de gafas)", "Examen del fondo de ojo (para asegurar que la retina y el nervio óptico estén sanos)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es restaurar la visión binocular, alinear los ojos y curar o prevenir el ojo vago:", subsections: [ { title: "Opciones Terapéuticas", items: ["Gafas (Anteojos): Es el tratamiento principal y a menudo único necesario para la endotropía acomodativa. Las gafas relajan el esfuerzo de enfoque y los ojos se enderezan.", "Parches oculares o gotas de atropina: Se usan para penalizar (tapar o nublar) el ojo bueno, obligando al cerebro a usar y fortalecer la visión del ojo desviado o 'vago'.", "Cirugía de los músculos extraoculares: Si las gafas no enderezan los ojos (como en la endotropía congénita), el cirujano debilita o refuerza músculos específicos del ojo para restaurar el alineamiento físico.", "Inyecciones de toxina botulínica (Botox): Ocasionalmente utilizadas en músculos oculares específicos como alternativa a la cirugía en ciertos casos."] } ], note: "La cirugía endereza los ojos, pero no cura el ojo vago. A menudo, el tratamiento con parche es necesario antes o después de la cirugía." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un oftalmólogo o pediatra si:", items: ["Notas que los ojos de tu hijo están cruzados o no se mueven juntos de manera coordinada", "Tu hijo inclina la cabeza de manera inusual para ver la televisión", "Eres un adulto y comienzas a experimentar visión doble repentina y ojos cruzados"] } },
'Gota crónica' : { intro: "La gota crónica es una forma progresiva y persistente de artritis inflamatoria causada por el depósito prolongado de cristales de ácido úrico en las articulaciones, tendones y tejidos circundantes.", whatIs: { title: "¿Qué es la Gota Crónica?", text: "La gota comienza como ataques agudos de dolor extremo e hinchazón (frecuentemente en el dedo gordo del pie). Si los niveles de ácido úrico en la sangre (hiperuricemia) permanecen elevados durante años sin tratamiento preventivo, los ataques se vuelven más frecuentes, prolongados e involucran múltiples articulaciones. Con el tiempo, se forman bultos duros de cristales bajo la piel (tofos) y se produce un daño articular erosivo y deformante, lo que se conoce como gota tofácea crónica." }, symptoms: { title: "Síntomas y Signos Tardíos", intro: "A diferencia del ataque agudo repentino, la fase crónica presenta:", groups: [ { name: "Daño Articular y Visible", items: ["Aparición de tofos (bultos firmes de tiza amarillenta/blanca bajo la piel, comúnmente en dedos de manos y pies, codos o en el cartílago de las orejas)", "Dolor articular sordo, crónico y rigidez diaria constante, simulando una artritis reumatoide o artrosis severa", "Deformidad visible en las articulaciones", "Movilidad articular permanentemente limitada"] }, { name: "Ataques Agudos Sobreagregados", items: ["Episodios recurrentes de dolor articular ardiente, hinchazón y enrojecimiento (frecuentemente despertando al paciente en la noche) que tardan más en sanar"] } ], warning: "Si la piel sobre un tofo se estira y se rompe, puede secretar una sustancia blanca similar a la pasta de dientes y es altamente susceptible a infecciones bacterianas graves." }, causes: { title: "Causas y Factores de Riesgo", intro: "La progresión a la fase crónica se debe a la hiperuricemia no controlada, exacerbada por:", items: ["Falta de tratamiento médico reductor del ácido úrico tras los primeros ataques agudos", "Dieta rica en purinas (carnes rojas, vísceras, mariscos)", "Consumo excesivo de alcohol, particularmente cerveza y licores fuertes", "Consumo alto de bebidas endulzadas con fructosa", "Enfermedades subyacentes crónicas (hipertensión, diabetes, obesidad, enfermedad renal, síndrome metabólico)", "Ciertos medicamentos, especialmente diuréticos tiazídicos ('pastillas para orinar')"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico de gota crónica y tofácea incluye:", items: ["Análisis de líquido sinovial o del contenido de un tofo (el estándar de oro: ver los cristales de ácido úrico en forma de aguja bajo un microscopio de luz polarizada)", "Niveles de ácido úrico en sangre (aunque pueden ser normales durante un ataque agudo, suelen estar persistentemente altos en la fase crónica)", "Radiografías de las articulaciones (para buscar las erosiones óseas características en 'mordida de rata' o daño cartilaginoso)", "Ecografía articular o TC de energía dual (para detectar microcristales de ácido úrico incluso antes de que se formen tofos grandes)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere un compromiso a largo plazo para disolver los cristales bajando el ácido úrico:", subsections: [ { title: "Manejo Médico y de Estilo de Vida", items: ["Medicamentos reductores de urato (Tratamiento Crónico): Alopurinol o Febuxostat son la piedra angular. Se toman diariamente de por vida para bajar y mantener el ácido úrico en sangre por debajo de 6 mg/dL, lo que previene nuevos ataques y encoge lentamente los tofos existentes.", "Manejo de los ataques (Tratamiento Agudo): Antiinflamatorios no esteroideos (AINEs, como la indometacina), Colquicina o Corticosteroides para detener el dolor y la inflamación de los brotes.", "Modificación de la dieta: Pérdida de peso gradual, beber mucha agua, evitar el alcohol y limitar purinas y fructosa.", "Cirugía: Rara vez necesaria, pero se utiliza para extirpar tofos infectados, grandes, o que destruyen la articulación o atrapan tendones."] } ], note: "Al iniciar medicamentos reductores de ácido úrico (Alopurinol), es normal sufrir brotes de gota temporales; no se debe suspender la medicación, sino que se da Colquicina preventiva durante los primeros meses." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar tratamiento médico especializado (Reumatología) si:", items: ["Sufres múltiples ataques de dolor articular al año", "Tienes bultos duros bajo la piel alrededor de tus articulaciones", "Tienes ataques de gota que ya no responden a los analgésicos habituales o tardan semanas en resolverse"] } },
'Prolapso de disco intervertebral' : { intro: "El prolapso de disco intervertebral, comúnmente conocido como hernia discal, es una afección de la columna vertebral en la que el centro blando de un disco espinal se desplaza fuera de su lugar, presionando los nervios cercanos y causando dolor.", whatIs: { title: "¿Qué es el Prolapso de Disco?", text: "La columna vertebral está formada por vértebras separadas por discos esponjosos que actúan como amortiguadores. Cuando el anillo exterior rígido de un disco se debilita o se desgarra, el núcleo pulposo y gelatinoso del interior puede sobresalir (prolapsarse). Esta protuberancia irrita químicamente o comprime físicamente las raíces nerviosas que salen de la médula espinal." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen de la ubicación del prolapso (generalmente en la zona lumbar o cervical):", groups: [ { name: "Prolapso Lumbar (Baja espalda)", items: ["Dolor punzante que baja por el glúteo y la pierna (ciática)", "Entumecimiento, hormigueo o sensación de 'alfileres y agujas' en el pie o la pierna", "Debilidad muscular al intentar levantar el pie o caminar"] }, { name: "Prolapso Cervical (Cuello)", items: ["Dolor agudo en el cuello que se irradia hacia el hombro, brazo o mano", "Pérdida de fuerza en el agarre de la mano", "Sensación de descarga eléctrica al mover el cuello de cierta manera"] } ], warning: "La pérdida repentina de control sobre la vejiga o los intestinos, junto con entumecimiento en la zona genital (anestesia en silla de montar), es una emergencia quirúrgica (Síndrome de Cauda Equina)." }, causes: { title: "Causas y Factores de Riesgo", intro: "El disco suele ceder debido a:", items: ["Desgaste natural relacionado con el envejecimiento (degeneración discal)", "Levantar objetos pesados usando los músculos de la espalda en lugar de las piernas", "Movimientos bruscos de torsión de la columna", "Sobrepeso crónico (aumenta el estrés sobre los discos lumbares)", "Tabaquismo (disminuye el suministro de oxígeno a los discos, acelerando su deterioro)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista evaluará la columna y los nervios mediante:", items: ["Examen físico y neurológico (prueba de elevación de la pierna recta, reflejos y sensibilidad)", "Resonancia Magnética (RM) (la prueba de oro para ver exactamente qué disco está prolapsado y qué nervio está comprimido)", "Tomografía Computarizada (TC)", "Electromiografía (EMG) (para evaluar la conducción eléctrica del nervio dañado)"], note: "Las radiografías simples no muestran los discos, pero se usan para descartar fracturas o artritis ósea." }, treatment: { title: "Tratamientos", intro: "El tratamiento inicial casi siempre es conservador:", subsections: [ { title: "Opciones de manejo", items: ["Reposo relativo inicial (no prolongado) seguido de Fisioterapia para fortalecer el 'core' y la espalda", "Analgésicos, antiinflamatorios no esteroideos (AINEs) y relajantes musculares", "Inyecciones epidurales de corticosteroides (para reducir la inflamación directa sobre el nervio)", "Microdiscectomía quirúrgica (cirugía mínimamente invasiva para extirpar solo el fragmento de disco que presiona el nervio, reservada para cuando el tratamiento conservador falla tras 6 semanas o hay debilidad motora progresiva)"] } ], note: "La mayoría de las hernias discales se reabsorben parcialmente y dejan de doler con el paso de los meses sin necesidad de cirugía." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un traumatólogo o neurocirujano si:", items: ["El dolor es insoportable y no mejora con analgésicos de venta libre", "Notas que tu pierna o brazo se vuelve cada vez más débil", "Tienes alteraciones en el control de esfínteres"] } },
'Acidosis tubular distal renal' : { intro: "La acidosis tubular distal renal (ATRD o ATR tipo 1) es un trastorno poco común en el cual los riñones no logran eliminar los ácidos adecuadamente en la orina, provocando que la sangre se vuelva demasiado ácida.", whatIs: { title: "¿Qué es la ATR Distal?", text: "El riñón tiene tubos microscópicos encargados de filtrar y equilibrar la sangre. En la ATR distal, la parte final de estos tubos (túbulo distal) pierde la capacidad de secretar iones de hidrógeno (ácido) hacia la orina. Como resultado, el ácido se acumula en el cuerpo (acidosis metabólica), lo que altera profundamente los niveles de potasio, calcio y la salud ósea." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden ser sutiles al principio, pero las complicaciones crónicas incluyen:", groups: [ { name: "Signos Clínicos y Complicaciones", items: ["Debilidad muscular severa, calambres o parálisis (debido a niveles peligrosamente bajos de potasio o hipopotasemia)", "Formación repetitiva de cálculos renales (piedras de calcio) y depósito de calcio en el tejido renal (nefrocalcinosis)", "Dolor óseo y predisposición a fracturas (osteomalacia o raquitismo, ya que el cuerpo extrae calcio de los huesos para neutralizar el ácido de la sangre)", "En niños: retraso significativo del crecimiento y falta de aumento de peso (retraso del desarrollo)"] } ], warning: "Una caída drástica en los niveles de potasio (crisis hipopotasémica) puede provocar arritmias cardíacas fatales." }, types: { title: "Diferenciación de ATR", intro: "Es fundamental no confundirla con otros tipos de acidosis tubular:", items: ["ATR Tipo 1 (Distal): Falla en la eliminación de ácido; orina alcalina, potasio bajo, muchas piedras en los riñones.", "ATR Tipo 2 (Proximal): Falla en la reabsorción de bicarbonato; sin piedras en los riñones.", "ATR Tipo 4: Asociada a niveles altos de potasio y problemas de la hormona aldosterona."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La ATRD puede ser hereditaria o adquirida:", items: ["Mutaciones genéticas hereditarias (común en casos pediátricos)", "Enfermedades autoinmunes (Síndrome de Sjögren, Lupus Eritematoso Sistémico, Artritis Reumatoide)", "Toxicidad por ciertos medicamentos (como el litio o la anfotericina B)", "Trastornos que causan niveles altos de calcio en la sangre"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El nefrólogo diagnosticará el trastorno mediante análisis químicos:", items: ["Análisis de gases en sangre arterial (para confirmar la acidosis metabólica)", "Análisis del nivel de potasio en sangre (suele estar muy bajo)", "Medición del pH de la orina (paradójicamente, la orina no puede volverse ácida y tiene un pH superior a 5.5 a pesar de la acidez de la sangre)", "Ecografía renal (para buscar piedras o nefrocalcinosis)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo es neutralizar el ácido en la sangre y reponer el potasio:", subsections: [ { title: "Opciones de manejo", items: ["Medicamentos alcalinizantes de por vida (Bicarbonato de sodio o Citrato de potasio/sodio oral) para neutralizar la acidez y prevenir el daño óseo y los cálculos", "Suplementos de potasio (para tratar la hipopotasemia)", "Tratamiento de la enfermedad autoinmune subyacente (si es una forma adquirida)", "Suplementación con Vitamina D y Calcio en casos de daño óseo severo"] } ], note: "Con un tratamiento adecuado, el pronóstico es excelente; los niños retoman su crecimiento normal y se detiene la formación de cálculos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca evaluación médica si:", items: ["Sufres de piedras en los riñones de forma recurrente", "Experimentas episodios de debilidad muscular extrema e inexplicable", "Un niño presenta retraso en su curva de crecimiento"] } },
'Hemorragia subaracnoidea' : { intro: "La hemorragia subaracnoidea (HSA) es un sangrado en el espacio situado entre el cerebro y la membrana que lo recubre (espacio subaracnoideo). Es una emergencia neurológica catastrófica que pone en riesgo la vida de forma inminente.", whatIs: { title: "¿Qué es una Hemorragia Subaracnoidea?", text: "El espacio subaracnoideo está lleno de líquido cefalorraquídeo que protege el cerebro. Cuando un vaso sanguíneo estalla en esta área, la sangre inunda el espacio, aumentando rápidamente la presión dentro del cráneo y dañando o destruyendo directamente el tejido cerebral por el contacto con la sangre tóxica." }, symptoms: { title: "Síntomas Comunes", intro: "El cuadro clínico es extremadamente agudo y reconocible:", groups: [ { name: "Síntoma Principal (El 'Grito' del Cerebro)", items: ["Un dolor de cabeza repentino, explosivo e intensísimo, frecuentemente descrito por los pacientes como 'el peor dolor de cabeza de mi vida' (cefalea en trueno)"] }, { name: "Síntomas Neurológicos y Sistémicos", items: ["Pérdida breve o prolongada del conocimiento", "Vómitos en proyectil y náuseas agudas", "Rigidez de nuca (incapacidad para tocar el pecho con la barbilla)", "Sensibilidad extrema a la luz (fotofobia) y visión doble", "Convulsiones o confusión mental severa"] } ], warning: "Un dolor de cabeza 'en trueno' es una urgencia vital absoluta; hasta un 15% de los pacientes mueren antes de llegar al hospital." }, causes: { title: "Causas y Factores de Riesgo", intro: "El sangrado no ocurre de la nada, suele deberse a:", items: ["Ruptura de un aneurisma cerebral (un abultamiento débil en la pared de una arteria; es la causa del 85% de las HSA espontáneas)", "Malformaciones arteriovenosas (MAV) (enredos anormales de vasos sanguíneos)", "Traumatismo craneoencefálico grave (golpes fuertes en la cabeza)", "Uso de drogas ilícitas (especialmente cocaína o metanfetaminas) y tabaquismo", "Hipertensión arterial severa descontrolada"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Cada minuto cuenta en la sala de emergencias:", items: ["Tomografía Computarizada (TC) de cráneo sin contraste (la primera y más importante prueba para ver la sangre fresca en el cerebro)", "Punción lumbar (extracción de líquido cefalorraquídeo de la columna; se realiza si la TC es normal pero la sospecha es alta, para buscar rastros de sangre o bilirrubina)", "Angiografía cerebral, Angio-TC o Angio-RM (para localizar exactamente el aneurisma o vaso roto y planificar la cirugía)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere cuidados intensivos neuroquirúrgicos para detener el sangrado y prevenir complicaciones:", subsections: [ { title: "Intervenciones Críticas", items: ["Clipaje quirúrgico (cirugía a cráneo abierto para colocar un clip de titanio en el cuello del aneurisma y cerrarlo)", "Embolización endovascular (Coiling) (procedimiento menos invasivo donde se introducen espirales de platino a través de la ingle hasta el aneurisma para coagularlo)", "Control estricto de la presión arterial y uso de medicamentos (como la Nimodipina) para prevenir el 'vasoespasmo' (un estrechamiento secundario letal de las arterias cerebrales)", "Drenaje ventricular (colocación de un catéter en el cerebro para aliviar la presión del exceso de líquido y sangre)"] } ], note: "La recuperación requiere una estancia prolongada en la UCI neurológica." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a los servicios de emergencia (911) inmediatamente si alguien experimenta:", items: ["Un dolor de cabeza insoportable que alcanza su máxima intensidad en segundos", "Pérdida repentina del conocimiento tras quejarse de dolor de cabeza", "Confusión, vómitos y debilidad súbita"] } },
'Eritema tóxico del neonato' : { intro: "El eritema tóxico del neonato es una erupción cutánea sumamente común, inofensiva y autolimitada que aparece en la piel de muchos recién nacidos sanos durante sus primeros días de vida.", whatIs: { title: "¿Qué es el Eritema Tóxico?", text: "A pesar de su nombre alarmante ('tóxico'), la afección no es tóxica, no es contagiosa, ni está causada por ninguna infección o alergia. Es simplemente una reacción inflamatoria transitoria de la piel del bebé mientras su sistema inmunológico se adapta al entorno fuera del útero materno." }, symptoms: { title: "Síntomas y Apariencia", intro: "La erupción tiene características visuales muy específicas que los pediatras reconocen fácilmente:", groups: [ { name: "Características Cutáneas", items: ["Manchas o ronchas rojas y planas, a menudo con pequeños bultos blancos o amarillentos en el centro (pústulas o pápulas), similares a una 'picadura de pulga'", "Aparecen predominantemente en la cara, el pecho, el estómago y las extremidades (rara vez en las palmas de las manos o las plantas de los pies)", "Las lesiones pueden desaparecer en unas pocas horas en una zona y aparecer en otra diferente", "El bebé se encuentra por lo demás perfectamente sano, come bien, no tiene fiebre y no parece sentir dolor ni picor"] } ], warning: "Si las pústulas son grandes, el bebé tiene fiebre, se ve aletargado o no se alimenta bien, NO es eritema tóxico y requiere evaluación médica inmediata por posible infección bacteriana o viral." }, causes: { title: "Causas", intro: "El origen exacto es desconocido, pero las teorías apuntan a:", items: ["Maduración del sistema inmunológico del recién nacido", "Respuesta inflamatoria benigna a los folículos pilosos (donde crece el vello)", "Adaptación a los estímulos térmicos y mecánicos del nuevo entorno"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico no requiere de ninguna prueba invasiva:", items: ["Examen físico clínico visual (el pediatra puede diagnosticarlo con solo mirar la piel del bebé)", "En casos muy raros donde hay duda diagnóstica, un frotis de una pústula bajo el microscopio mostrará un tipo específico de glóbulos blancos llamados eosinófilos, confirmando que no hay bacterias."], note: "" }, treatment: { title: "Tratamientos", intro: "El eritema tóxico no requiere ningún tratamiento médico:", subsections: [ { title: "Manejo en Casa", items: ["Observación (la erupción desaparecerá por sí sola, generalmente en 1 a 2 semanas)", "No apretar, pellizcar ni reventar los bultos (hacerlo puede causar una infección real en la piel del bebé)", "Mantener la piel del bebé limpia y seca bañándolo suavemente con agua tibia", "Evitar el uso excesivo de lociones, cremas o polvos que puedan irritar la delicada piel del neonato"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta con el pediatra de inmediato si el bebé:", items: ["Tiene fiebre de 38°C (100.4°F) o más", "Se muestra inusualmente irritable, letárgico o no quiere comer", "El sarpullido se ve hinchado, caliente al tacto, o supurando pus de color verdoso"] } },
'Submordida' : { intro: "La submordida (prognatismo mandibular o maloclusión de clase III) es una alteración dental y esquelética en la que la mandíbula inferior sobresale hacia adelante, haciendo que los dientes inferiores se superpongan a los dientes frontales superiores al cerrar la boca.", whatIs: { title: "¿Qué es una Submordida?", text: "Normalmente, los dientes superiores deben descansar ligeramente por delante de los inferiores. En una submordida, este alineamiento está invertido. Esta condición no solo es un problema estético que altera el perfil facial (dando apariencia de 'mentón prominente'), sino que causa serios problemas funcionales en la masticación, el habla y la salud de la articulación de la mandíbula." }, symptoms: { title: "Síntomas y Consecuencias", intro: "Más allá de la apariencia, la submordida genera problemas biomecánicos crónicos:", groups: [ { name: "Funcionales y Dentales", items: ["Dificultad evidente para masticar o morder alimentos", "Desgaste dental anormal, rápido y severo, con astillamiento del esmalte", "Dificultades en el habla (ceceo o problemas para articular ciertas consonantes)", "Dolor crónico en la articulación temporomandibular (ATM), dolores de cabeza y de oído", "Problemas de respiración bucal, ronquidos o apnea del sueño"] } ], warning: "Ignorar una submordida severa en la infancia puede requerir cirugías maxilofaciales complejas en la edad adulta, ya que los huesos terminan de crecer y fijarse." }, types: { title: "Clasificación de la Causa", intro: "La submordida se divide según qué parte está fallando:", items: ["Submordida dental: Los maxilares están bien alineados, pero los dientes inferiores están inclinados hacia adelante y los superiores hacia atrás.", "Submordida esquelética (Prognatismo): La mandíbula inferior (maxilar inferior) creció demasiado, el maxilar superior no creció lo suficiente, o una combinación de ambas. Es más severa."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Esta maloclusión tiene fuertes componentes hereditarios y ambientales:", items: ["Factores genéticos (se hereda la forma y tamaño de los maxilares de los padres)", "Hábitos infantiles prolongados (uso excesivo del chupón, chuparse el dedo o empuje lingual continuado más allá de los 3 años)", "Respiración bucal crónica por alergias severas o amígdalas/adenoides gigantes (altera el desarrollo del paladar y la mandíbula)", "Tumores en el hueso de la mandíbula (muy raro)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico y plan de tratamiento los realiza un ortodoncista o cirujano maxilofacial:", items: ["Examen clínico dental y facial", "Radiografías cefalométricas (imágenes laterales del cráneo para medir exactamente los ángulos y tamaños de los huesos maxilares)", "Radiografía panorámica y toma de impresiones (moldes) de los dientes"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento ideal depende de si el paciente aún está en crecimiento (niños) o ya terminó de crecer (adultos):", subsections: [ { title: "Opciones Ortopédicas y Quirúrgicas", items: ["Intervención Temprana en Niños (7-10 años): Expansores palatinos para ensanchar el maxilar superior, y máscaras faciales ortopédicas de tracción frontal para estimular el crecimiento del maxilar superior hacia adelante.", "Ortodoncia (Brackets o Alineadores): Para casos leves o submordidas estrictamente dentales, para corregir el ángulo de los dientes.", "Extracción dental: A veces se extraen dientes inferiores para crear espacio y poder retraer los dientes frontales inferiores.", "Cirugía Ortognática (Cirugía Maxilofacial): En adultos con submordida esquelética, un cirujano corta el hueso de la mandíbula y lo retrasa, o avanza el maxilar superior, fijándolos con placas y tornillos de titanio. Siempre se combina con ortodoncia antes y después de la cirugía."] } ], note: "La corrección de una submordida esquelética en adultos mejora drásticamente el perfil facial y la calidad de vida, pero requiere un compromiso de tratamiento de 2 a 3 años." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un ortodoncista para una evaluación si:", items: ["Observas que tu hijo (incluso con dientes de leche a los 6-7 años) tiene la mandíbula inferior adelantada", "Sufres dolores constantes de mandíbula (ATM) o dolor al masticar", "Tus dientes frontales están desgastándose rápidamente"] } },
'Tendinitis bicipital' : { intro: "La tendinitis bicipital es la inflamación o irritación del tendón de la cabeza larga del músculo bíceps, situado en la parte frontal del hombro. Causa dolor directo y limitación del movimiento en la articulación del hombro.", whatIs: { title: "¿Qué es la Tendinitis Bicipital?", text: "El músculo bíceps en la parte delantera del brazo superior tiene dos tendones que lo unen al hombro. La tendinitis ocurre por el desgaste repetitivo o el roce del 'tendón largo' mientras se desliza por un canal en el hueso del hombro (surco bicipital). Esta afección rara vez ocurre de forma aislada; generalmente es parte de un problema mayor de desgaste en el hombro, acompañando frecuentemente a lesiones del manguito de los rotadores." }, symptoms: { title: "Síntomas Comunes", intro: "El dolor es muy localizado y mecánico:", groups: [ { name: "Signos Clínicos", items: ["Dolor sordo, palpitante o agudo en la parte frontal y superior del hombro", "El dolor empeora al levantar el brazo por encima de la cabeza, estirarse hacia adelante o al cargar peso", "Sensación de chasquido, 'clic' o roce profundo en el hombro al mover el brazo", "Dolor al palpar o presionar directamente la parte delantera del hombro", "Debilidad al intentar flexionar el codo o girar la palma de la mano hacia arriba contra resistencia"] } ], warning: "Si experimentas un dolor agudo repentino, escuchas un chasquido fuerte y luego notas un bulto anormal en la mitad de tu brazo (el 'signo de Popeye'), significa que el tendón irritado se ha roto por completo." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño al tendón es principalmente por sobreuso crónico:", items: ["Envejecimiento (el colágeno de los tendones se degenera y se vuelve menos elástico con los años)", "Movimientos repetitivos del brazo por encima de la cabeza (deportes como natación, tenis, béisbol o lanzamiento de peso)", "Trabajos físicos intensos que requieran carga repetitiva", "Compensación por otras lesiones en el hombro (como desgarros del manguito rotador o pinzamiento subacromial)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El traumatólogo examinará la función del hombro:", items: ["Examen físico utilizando pruebas específicas (como la prueba de Speed o la prueba de Yergason, donde el paciente resiste el movimiento del médico para provocar el dolor exacto del tendón)", "Ecografía del hombro (muy útil para ver el tendón en movimiento y detectar inflamación o líquido alrededor de él)", "Resonancia Magnética (RM) (se pide para evaluar si el tendón está desgarrado y revisar el estado del manguito rotador)"], note: "Las radiografías no muestran tendones, pero pueden revelar si hay espolones óseos rozando el tendón." }, treatment: { title: "Tratamientos", intro: "El objetivo es reducir la inflamación y restaurar la función sin necesidad de quirófano:", subsections: [ { title: "Opciones Conservadoras y Quirúrgicas", items: ["Reposo y Modificación de Actividad: Evitar actividades que requieran levantar los brazos por encima de la cabeza.", "Aplicación de Hielo: Hielo local en la parte anterior del hombro varias veces al día para desinflamar.", "Medicamentos: Antiinflamatorios no esteroideos (AINEs) como el ibuprofeno.", "Fisioterapia: Ejercicios guiados para fortalecer los músculos del hombro (manguito rotador) y corregir la postura, aliviando la carga sobre el bíceps.", "Inyecciones de corticosteroides: Para aliviar el dolor intenso, inyectadas cuidadosamente en la vaina del tendón (no directamente en él para evitar que se rompa).", "Cirugía (Tenodesis o Tenotomía): Si el dolor persiste tras meses de terapia o el tendón está gravemente dañado, se opera para cortar el tendón dañado y anclarlo en una nueva posición, eliminando el roce."] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico especialista si:", items: ["El dolor en el hombro no mejora tras unas semanas de reposo y hielo", "Sufres una pérdida repentina de fuerza o incapacidad para levantar el brazo", "Aparece un bulto en el músculo de tu brazo tras un esfuerzo (rotura del tendón)"] } },
'Glaucoma de ángulo cerrado' : { intro: "El glaucoma de ángulo cerrado (o glaucoma agudo) es una emergencia oftalmológica extremadamente dolorosa y de progresión rápida. Ocurre cuando la presión del líquido dentro del ojo aumenta bruscamente debido a un bloqueo físico en el sistema de drenaje ocular, pudiendo causar ceguera en pocas horas.", whatIs: { title: "¿Qué es el Glaucoma de Ángulo Cerrado?", text: "El ojo produce continuamente un líquido (humor acuoso) que debe drenar a través de un 'sumidero' (la malla trabecular) ubicado en el ángulo donde el iris se encuentra con la córnea. En esta condición, el iris es empujado hacia adelante, cerrando físicamente ese ángulo y tapando el desagüe. El líquido sigue produciéndose pero no puede salir, lo que dispara la presión dentro del ojo como un globo inflado en exceso. Esta presión aplasta y destruye rápidamente las fibras del nervio óptico." }, symptoms: { title: "Síntomas Comunes", intro: "El ataque agudo es inconfundible y devastador:", groups: [ { name: "Síntomas de Emergencia", items: ["Dolor ocular repentino, severo e insoportable", "Dolor de cabeza agudo en el mismo lado del ojo afectado", "Visión borrosa súbita y nublada", "Visión de halos multicolores (como arcoíris) alrededor de las luces brillantes", "Enrojecimiento intenso del ojo ('ojo rojo')", "Náuseas extremas y vómitos profusos", "La pupila del ojo afectado se ve de tamaño mediano y no reacciona al iluminarla con luz"] } ], warning: "Esta es una emergencia médica de pérdida de visión. Si experimentas estos síntomas, acude a la sala de emergencias o a un oftalmólogo inmediatamente. El retraso en el tratamiento conduce a la ceguera permanente." }, types: { title: "Diferencia con el Glaucoma Común", intro: "Existen dos tipos principales de glaucoma, siendo diametralmente opuestos:", items: ["Glaucoma de ángulo abierto: Es el crónico, la causa más común. Es indoloro, muy lento y el drenaje está 'abierto' pero funciona mal.", "Glaucoma de ángulo cerrado: Es agudo, raro, extremadamente doloroso, muy rápido y el drenaje está físicamente tapado."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Ciertas anatomías oculares y situaciones provocan el ataque:", items: ["Anatomía ocular predispuesta (ojos pequeños, personas hipermétropes, o cristalinos engrosados por la edad)", "Dilatación de la pupila (al estar en la oscuridad, cines, estrés o estrés emocional, el iris se encoge y se amontona, bloqueando el ángulo)", "Medicamentos dilatadores (gotas oftálmicas para exámenes, antihistamínicos, antiespasmódicos o ciertos antidepresivos que dilatan la pupila accidentalmente)", "Etnia (mucho más común en poblaciones de ascendencia asiática o inuit) y envejecimiento"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico en urgencias debe ser inmediato:", items: ["Tonometría ocular (medición de la presión intraocular; en un ataque agudo, la presión suele ser extremadamente alta, superando a menudo los 40-60 mmHg, siendo lo normal entre 10-21 mmHg)", "Gonioscopia (el oftalmólogo usa una lente especial para confirmar visualmente que el ángulo de drenaje está físicamente cerrado)", "Examen con lámpara de hendidura (para evaluar la turbidez de la córnea, la inflamación y el estado de la pupila)"], note: "" }, treatment: { title: "Tratamientos", intro: "El objetivo urgente es reducir la presión del ojo para salvar el nervio óptico, seguido de un procedimiento definitivo:", subsections: [ { title: "Manejo Médico y Láser", items: ["Medicamentos de Urgencia (Reducción de Presión): Administración rápida de medicamentos por vía oral, intravenosa y en gotas oftálmicas (Betabloqueantes, inhibidores de la anhidrasa carbónica, pilocarpina o agentes hiperosmóticos como el manitol) para detener la producción de líquido y reducir la presión rápidamente.", "Iridotomía Periférica con Láser (Tratamiento Definitivo): Una vez que la presión baja, el oftalmólogo utiliza un láser para hacer un agujero microscópico en el borde del iris. Esto crea una 'válvula de escape' que iguala la presión y permite que el iris se separe del sistema de drenaje para siempre.", "Iridotomía profiláctica: El ojo sano (no afectado) generalmente recibe el mismo tratamiento con láser de forma preventiva, ya que tiene un riesgo altísimo de sufrir un ataque en el futuro."] } ], note: "La cirugía láser (iridotomía) es un procedimiento ambulatorio corto que resuelve el riesgo anatómico del bloqueo de forma permanente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Reacción vital: Llama al 911 o acude inmediatamente a urgencias si presentas:", items: ["Dolor extremo en el ojo combinado con visión borrosa y náuseas", "Aparición de halos de colores alrededor de las luces, especialmente si estás en un lugar oscuro (como el cine)"] } },
'Reacción anafiláctica' : { intro: "La reacción anafiláctica, o anafilaxia, es una respuesta alérgica grave, generalizada y de rápida progresión que puede poner en peligro la vida en cuestión de minutos si no se trata de inmediato.", whatIs: { title: "¿Qué es la Anafilaxia?", text: "Es una reacción desproporcionada y sistémica del sistema inmunológico frente a una sustancia que considera una amenaza (alérgeno). Esta reacción provoca una liberación masiva de sustancias químicas, como la histamina, que causan la dilatación extrema de los vasos sanguíneos (caída de la presión arterial) y la constricción de las vías respiratorias (asfixia)." }, symptoms: { title: "Síntomas y Signos Críticos", intro: "Los síntomas suelen aparecer a los pocos minutos de la exposición al alérgeno:", groups: [ { name: "Respiratorios y Cardiovasculares", items: ["Dificultad severa para respirar, tragar o hablar", "Sibilancias (silbidos al respirar) o tos persistente", "Hinchazón de la garganta, la lengua o los labios (angioedema)", "Caída brusca de la presión arterial, pulso rápido y débil, mareo severo o desmayo"] }, { name: "Cutáneos y Gastrointestinales", items: ["Urticaria generalizada (ronchas rojas y con mucha picazón)", "Enrojecimiento o palidez repentina y sudoración fría", "Náuseas, vómitos, dolor abdominal o diarrea repentina"] } ], warning: "La anafilaxia es una emergencia médica absoluta. El retraso en la administración de epinefrina aumenta significativamente el riesgo de muerte." }, causes: { title: "Desencadenantes Comunes", intro: "Cualquier alérgeno puede causarla, pero los más frecuentes son:", items: ["Alimentos (cacahuetes, nueces, mariscos, pescado, leche, huevos)", "Picaduras de insectos (abejas, avispas, hormigas rojas)", "Medicamentos (penicilina, antiinflamatorios, anestésicos)", "Látex (guantes, globos, material médico)"], note: "En algunos casos raros, puede ser inducida por el ejercicio (especialmente después de comer ciertos alimentos)." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "En urgencias, el diagnóstico es puramente clínico por la rapidez requerida. Posteriormente, un alergólogo confirmará la causa mediante:", items: ["Revisión detallada de los eventos previos a la reacción", "Análisis de sangre para medir niveles de triptasa (enzima liberada durante la anafilaxia)", "Pruebas cutáneas o de sangre (IgE específica) semanas después del evento para identificar el alérgeno exacto"], note: "" }, treatment: { title: "Tratamientos de Emergencia", intro: "La intervención debe ser inmediata y agresiva:", subsections: [ { title: "Manejo de Urgencia", items: ["Administración de Epinefrina (Adrenalina) intramuscular en el muslo (es el único tratamiento que salva vidas al revertir el shock y abrir las vías aéreas)", "Oxígeno suplementario y soporte ventilatorio si es necesario", "Líquidos intravenosos para restaurar la presión arterial", "Antihistamínicos y corticosteroides intravenosos (para prevenir síntomas secundarios o reacciones tardías)"] } ], note: "Toda persona con riesgo de anafilaxia debe llevar consigo dos autoinyectores de epinefrina (EpiPen) en todo momento." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama al 911 o acude a urgencias inmediatamente si tú o alguien más presenta:", items: ["Cualquier signo de dificultad respiratoria tras ingerir un alimento, tomar un medicamento o sufrir una picadura", "Hinchazón visible de la cara, lengua o garganta", "Sensación de mareo extremo, confusión o desvanecimiento inminente"] } },
'Amebiasis hepática' : { intro: "La amebiasis hepática, o absceso hepático amebiano, es una complicación grave de la infección intestinal causada por el parásito microscópico Entamoeba histolytica.", whatIs: { title: "¿Qué es la Amebiasis Hepática?", text: "Normalmente, esta ameba causa infección en los intestinos (disentería). Sin embargo, en algunos casos, los parásitos logran perforar la pared intestinal, entran al torrente sanguíneo a través de la vena porta y se alojan en el hígado. Allí, destruyen el tejido hepático y forman una cavidad llena de pus y tejido muerto conocida como absceso amebiano." }, symptoms: { title: "Síntomas Comunes", intro: "Suelen aparecer semanas o meses después de haber viajado a una zona endémica o haber tenido una infección intestinal:", groups: [ { name: "Síntomas Sistémicos y Abdominales", items: ["Fiebre alta, con escalofríos y sudores nocturnos", "Dolor constante, punzante o sordo en la parte superior derecha del abdomen", "Dolor que empeora al toser o respirar profundamente y puede irradiarse al hombro derecho", "Hepatomegalia (hígado agrandado y doloroso al tacto)"] }, { name: "Síntomas Asociados", items: ["Náuseas, vómitos y pérdida de apetito y peso", "Ictericia leve (coloración amarillenta de la piel o los ojos, aunque no siempre está presente)", "Tos seca o dolor torácico bajo si el absceso irrita el diafragma"] } ], warning: "Si el absceso se rompe hacia el abdomen, el pecho o el pericardio (alrededor del corazón), puede ser rápidamente letal." }, causes: { title: "Causas y Factores de Riesgo", intro: "La infección se contrae inicialmente por vía fecal-oral:", items: ["Ingestión de agua o alimentos contaminados con quistes de amebas", "Viajes recientes o residencia en regiones tropicales o con condiciones de saneamiento deficientes", "Mayor incidencia en hombres adultos (de 20 a 40 años) y personas inmunodeprimidas"], note: "Sorprendentemente, muchas personas con absceso hepático amebiano no recuerdan haber tenido diarrea previa." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se requiere confirmar la presencia del absceso y de anticuerpos contra la ameba:", items: ["Ecografía abdominal (prueba inicial más común para detectar la cavidad en el hígado)", "Tomografía Computarizada (TC) de abdomen con contraste (para obtener imágenes precisas del tamaño y ubicación)", "Análisis de sangre para serología amebiana (anticuerpos contra E. histolytica, que son positivos en más del 90% de los casos)", "Aspiración del absceso guiada por imagen (se realiza rara vez, solo si hay dudas diagnósticas o riesgo inminente de ruptura)"], note: "El pus del absceso amebiano tiene un aspecto característico descrito como 'pasta de anchoas' o 'salsa de chocolate'." }, treatment: { title: "Tratamientos", intro: "A diferencia de los abscesos bacterianos, el absceso amebiano suele curarse con medicamentos sin necesidad de cirugía:", subsections: [ { title: "Opciones de manejo", items: ["Amebicidas tisulares (Metronidazol o Tinidazol intravenoso u oral durante 10-14 días para matar a las amebas en el hígado)", "Amebicidas luminales (Paramomicina o Iodoquinol, tomados después para erradicar los quistes que aún viven en el intestino y evitar recaídas)", "Drenaje percutáneo con aguja (reservado únicamente para abscesos muy grandes, dolorosos, que no responden al tratamiento médico o que amenazan con romperse)"] } ], note: "La respuesta al Metronidazol suele ser espectacular, bajando la fiebre en 72 horas en la mayoría de los pacientes." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias si:", items: ["Presentas fiebre alta con dolor agudo e inusual en el lado derecho de las costillas o el abdomen", "Has viajado recientemente a zonas tropicales y desarrollas estos síntomas, incluso meses después", "El dolor abdominal se vuelve súbitamente insoportable y se extiende por todo el vientre (posible ruptura)"] } },
'Hipotensión' : { intro: "La hipotensión es el término médico para referirse a la presión arterial anormalmente baja, generalmente definida como una lectura de menos de 90 milímetros de mercurio (mmHg) para el número superior (sistólica) o menos de 60 mmHg para el número inferior (diastólica).", whatIs: { title: "¿Qué es la Hipotensión?", text: "Para algunas personas sanas, especialmente deportistas, tener la presión arterial baja es normal y no causa problemas. Sin embargo, se vuelve un problema médico cuando la presión cae tanto que el corazón, el cerebro y otras partes vitales del cuerpo no reciben suficiente sangre y oxígeno, provocando mareos, desmayos o, en casos extremos, estado de shock." }, symptoms: { title: "Síntomas Comunes", intro: "Cuando la presión baja causa un riego sanguíneo inadecuado, se experimenta:", groups: [ { name: "Síntomas Neurológicos y Generales", items: ["Mareos o sensación de aturdimiento, especialmente al ponerse de pie rápidamente", "Desmayos (síncope) o episodios de casi desmayo", "Visión borrosa o que se desvanece", "Dificultad para concentrarse y confusión mental", "Fatiga extrema inusual y debilidad"] }, { name: "Signos de Shock (Hipotensión Extrema)", items: ["Piel fría, pálida, sudorosa o pegajosa", "Respiración rápida y poco profunda", "Pulso rápido y débil"] } ], warning: "La hipotensión grave (shock) causada por pérdida de sangre, deshidratación severa o infecciones (sepsis) pone en peligro la vida inmediatamente." }, types: { title: "Tipos de Presión Arterial Baja", intro: "La hipotensión se clasifica a menudo según el momento en que ocurre:", items: ["Hipotensión ortostática o postural: Caída repentina de la presión al levantarse desde una posición sentada o acostada.", "Hipotensión posprandial: Caída de la presión entre 1 y 2 horas después de comer (común en adultos mayores).", "Hipotensión mediada neuralmente: Caída de la presión tras estar de pie durante mucho tiempo o tras emociones fuertes (frecuente en jóvenes).", "Hipotensión severa (Shock): Caída brusca debido a una pérdida masiva de sangre, ataque cardíaco, anafilaxia o infección."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La presión puede bajar por múltiples razones:", items: ["Deshidratación (vómitos, diarrea, fiebre o no beber suficiente agua)", "Medicamentos (diuréticos, bloqueadores alfa y beta, antidepresivos, fármacos para el Parkinson o Viagra)", "Problemas cardíacos (bradicardia, problemas de válvulas, insuficiencia cardíaca)", "Problemas endocrinos (insuficiencia suprarrenal, hipotiroidismo)", "Embarazo (la red circulatoria se expande rápidamente)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El objetivo es encontrar la causa subyacente de la presión baja:", items: ["Medición repetida de la presión arterial (sentado, acostado y de pie)", "Electrocardiograma (ECG) y Ecocardiograma para descartar problemas del corazón", "Análisis de sangre (para verificar anemia o niveles de azúcar)", "Prueba de la mesa inclinada (Tilt test) para evaluar cómo reacciona el cuerpo a los cambios de posición"], note: "" }, treatment: { title: "Tratamientos", intro: "Si no hay síntomas, rara vez requiere tratamiento. Si los hay, depende de la causa:", subsections: [ { title: "Opciones de manejo", items: ["Aumento de la ingesta de agua y líquidos (para prevenir la deshidratación y aumentar el volumen sanguíneo)", "Aumento del consumo de sal (solo bajo estricta recomendación médica)", "Uso de medias de compresión (para evitar que la sangre se estanque en las piernas)", "Revisión y ajuste de los medicamentos recetados actuales", "Medicamentos específicos como la Fludrocortisona (que aumenta el volumen de sangre) o la Midodrina (que restringe los vasos sanguíneos) en casos crónicos"] } ], note: "Para la hipotensión ortostática, es clave levantarse lentamente y evitar cruzar las piernas al estar sentado." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Solicita asistencia médica de emergencia si:", items: ["Tú o alguien más se desmaya o pierde el conocimiento", "Experimentas mareos intensos acompañados de dolor en el pecho, dificultad para respirar o rigidez en el cuello", "Presentas signos de shock (piel fría y sudorosa, pulso débil y rápido, respiración agitada)"] } },
'Cardiomiopatía hipertrófica (CMH)' : { intro: "La cardiomiopatía hipertrófica (CMH) es una enfermedad a menudo hereditaria en la que el músculo del corazón se vuelve anormalmente grueso (hipertrofiado), lo que dificulta su capacidad para bombear sangre con eficacia.", whatIs: { title: "¿Qué es la Cardiomiopatía Hipertrófica?", text: "En esta condición, el engrosamiento del músculo cardíaco suele ocurrir en el tabique que separa las cámaras inferiores del corazón (ventrículos). Este aumento de grosor puede causar que la cámara de bombeo (ventrículo izquierdo) se vuelva rígida, reduciendo la cantidad de sangre que el corazón puede recibir y bombear. A veces, el músculo engrosado bloquea físicamente la salida de la sangre del corazón (CMH obstructiva)." }, symptoms: { title: "Síntomas Comunes", intro: "Muchas personas con CMH no tienen síntomas durante años, pero cuando aparecen incluyen:", groups: [ { name: "Síntomas Cardiovasculares", items: ["Dificultad para respirar, especialmente al hacer ejercicio o esfuerzo físico", "Dolor en el pecho (angina), a menudo provocado por el ejercicio", "Desmayos (síncope) o sensación de mareo extremo inexplicables, particularmente durante o justo después de la actividad física", "Sensación de latidos cardíacos rápidos, aleteo o latidos fuertes (palpitaciones)"] } ], warning: "La CMH es una de las causas más comunes de muerte cardíaca súbita en atletas jóvenes que, en apariencia, están sanos y desconocen que tienen la enfermedad." }, types: { title: "Tipos de CMH", intro: "La afección se divide en dos formas principales:", items: ["CMH Obstructiva: El músculo engrosado obstruye o bloquea el flujo de sangre desde el ventrículo izquierdo hacia la aorta. Es el tipo más común y causa la mayoría de los síntomas.", "CMH No Obstructiva: El músculo está engrosado y la cámara de bombeo puede estar rígida, pero el flujo de sangre no está bloqueado directamente."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "La CMH es fundamentalmente genética:", items: ["Mutaciones genéticas heredadas que afectan a las proteínas del músculo cardíaco (es autosómica dominante, si uno de los padres la tiene, el hijo tiene un 50% de probabilidad de heredarla)", "A menudo se diagnostica durante la adolescencia o en la adultez joven, aunque puede desarrollarse a cualquier edad"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es fundamental la revisión familiar y los estudios de imagen del corazón:", items: ["Ecocardiograma (la prueba de oro: utiliza ondas sonoras para ver el grosor exacto del músculo y cómo fluye la sangre)", "Electrocardiograma (ECG) para detectar señales eléctricas anormales y arritmias (frecuentes en la CMH)", "Monitor Holter de 24-48 horas para detectar ritmos cardíacos peligrosos y ocultos", "Resonancia Magnética (RM) cardíaca para imágenes más detalladas del daño muscular", "Pruebas genéticas (para confirmar la mutación y evaluar a otros miembros de la familia)"], note: "Si se te diagnostica CMH, se recomienda encarecidamente que tus padres, hermanos e hijos se sometan a un ecocardiograma de detección." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en aliviar los síntomas, relajar el músculo cardíaco y prevenir la muerte súbita:", subsections: [ { title: "Opciones de manejo y procedimientos", items: ["Medicamentos: Betabloqueadores, bloqueadores de los canales de calcio o medicamentos más nuevos como el Mavacamten (Camzyos) para relajar el músculo cardíaco, ralentizar la frecuencia y aliviar la obstrucción.", "Desfibrilador Automático Implantable (DAI): Un dispositivo colocado en el pecho para detectar y detener arritmias letales mediante un choque eléctrico (crucial para prevenir la muerte súbita).", "Miectomía septal: Cirugía a corazón abierto para extirpar la porción engrosada del músculo y liberar el bloqueo del flujo sanguíneo.", "Ablación septal con alcohol: Procedimiento con catéter donde se inyecta alcohol en la arteria que irriga el área engrosada, causando que el músculo se reduzca."] } ], note: "Los pacientes con CMH a menudo deben evitar los deportes competitivos de alta intensidad y el levantamiento de pesas extremo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es una emergencia médica si tú o un familiar joven presenta:", items: ["Pérdida de conocimiento o desmayo súbito durante la práctica de deportes o ejercicio", "Dolor en el pecho severo o latidos cardíacos extremadamente rápidos e irregulares", "Falta de aire aguda y extrema en reposo"] } },
'Pseudoartrosis' : { intro: "La pseudoartrosis (también conocida como falta de consolidación o no unión) es el fracaso definitivo y permanente de la curación de una fractura ósea. El hueso roto no logra soldarse y formar callo óseo, creando una 'falsa articulación' móvil en un lugar donde no debería existir.", whatIs: { title: "¿Qué es la Pseudoartrosis?", text: "Normalmente, cuando un hueso se rompe, el cuerpo produce tejido nuevo (callo óseo) para unir los fragmentos. Si este proceso de curación se detiene por completo (generalmente después de 6 a 9 meses sin signos de progreso), los extremos del hueso permanecen separados, a menudo recubiertos de tejido fibroso o líquido, permitiendo un movimiento anormal y doloroso en el foco de la fractura." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos de que una fractura no ha sanado incluyen:", groups: [ { name: "Locales y Funcionales", items: ["Dolor sordo, crónico o punzante en el lugar exacto de la fractura que persiste o empeora meses después de la lesión inicial", "Dolor que aumenta al cargar peso o al usar la extremidad afectada", "Sensación de inestabilidad, debilidad o fallo en el hueso afectado", "Movimiento visible o perceptible (un 'chasquido' o crujido) en el medio del hueso donde no hay ninguna articulación natural", "Cojera prolongada (si la fractura es en la pierna)"] } ], warning: "La pseudoartrosis no se curará sola con más tiempo de reposo; requiere intervención médica especializada para reactivar el proceso de curación biológica." }, types: { title: "Tipos de Pseudoartrosis", intro: "Se clasifican según su apariencia biológica y vascularización en las radiografías:", items: ["Pseudoartrosis hipertrófica ('pata de elefante'): El cuerpo intenta curar la fractura produciendo mucho callo óseo, pero falla debido a una fijación inadecuada o demasiado movimiento (inestabilidad mecánica). Tiene buen riego sanguíneo.", "Pseudoartrosis atrófica: El hueso no intenta curarse, los extremos se ven redondeados o afilados sin callo óseo. Suele deberse a una falta de suministro de sangre al hueso (fallo biológico).", "Pseudoartrosis infectada: El fallo de consolidación es causado por una infección bacteriana profunda en el hueso (osteomielitis)."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Existen factores mecánicos y biológicos que detienen la curación:", items: ["Inestabilidad mecánica (la fractura no se inmovilizó correctamente con yeso, clavos o placas, permitiendo demasiado movimiento)", "Falta de suministro de sangre a los fragmentos del hueso (común en fracturas de tibia, escafoides o base del quinto metatarsiano)", "Tabaquismo severo (la nicotina contrae los vasos sanguíneos y detiene la curación ósea drásticamente)", "Infección en el sitio de la fractura (especialmente en fracturas abiertas o postquirúrgicas)", "Uso prolongado de AINEs (ibuprofeno, naproxeno) o corticosteroides durante la recuperación", "Enfermedades subyacentes como diabetes grave, osteoporosis o deficiencias nutricionales severas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El traumatólogo requerirá un seguimiento a largo plazo:", items: ["Radiografías seriadas durante varios meses (para demostrar la ausencia de puente óseo entre los fragmentos o la aparición de esclerosis y separación)", "Tomografía Computarizada (TC) (la mejor prueba para ver detalles finos de la unión ósea, el tejido fibroso y evaluar fracturas complejas)", "Gammagrafía ósea (para evaluar la actividad biológica y el riego sanguíneo del hueso)", "Análisis de sangre (para detectar marcadores de infección o deficiencias metabólicas)"], note: "Se diagnostica oficialmente pseudoartrosis cuando han pasado al menos 9 meses desde la lesión y no hay cambios radiológicos durante 3 meses consecutivos." }, treatment: { title: "Tratamientos", intro: "El tratamiento casi siempre es quirúrgico, con el objetivo de proporcionar estabilidad y estimular la biología del hueso:", subsections: [ { title: "Opciones Quirúrgicas y No Quirúrgicas", items: ["Fijación interna rígida: Cirugía para colocar placas, tornillos o clavos intramedulares más fuertes y estabilizar el hueso por completo.", "Injerto óseo (Autoinjerto): Extraer hueso sano del propio paciente (generalmente de la cresta ilíaca en la cadera) y colocarlo en la fractura para aportar células vivas que reinicien la curación (el estándar de oro).", "Sustitutos de injerto óseo o Proteínas Morfogenéticas Óseas (BMP): Sustancias químicas sintéticas que estimulan el crecimiento de hueso nuevo.", "Tratamiento de infecciones: Extracción de placas o clavos infectados, limpieza exhaustiva del hueso (desbridamiento) y antibióticos a largo plazo antes de intentar unirlo de nuevo.", "Estimuladores de crecimiento óseo: Dispositivos externos (ultrasonido de baja intensidad u ondas electromagnéticas) que se usan diariamente para estimular la consolidación en casos sin desplazamiento."] } ], note: "Dejar de fumar es absolutamente obligatorio antes y después de la cirugía para garantizar el éxito del injerto óseo." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu cirujano ortopédico si:", items: ["El dolor en tu fractura, en lugar de mejorar con los meses, sigue igual o empeora al intentar apoyar", "Sientes que el hueso cede, se dobla o hace ruido meses después de que te quitaron el yeso", "Tienes una herida o cicatriz quirúrgica sobre la fractura que comienza a doler, ponerse roja o supurar líquido"] } },
'Espolón calcáneo y fascitis plantar' : { intro: "El espolón calcáneo y la fascitis plantar son afecciones del talón íntimamente relacionadas que causan dolor agudo en la planta del pie. A menudo se confunden y se presentan juntas, siendo la causa más común del dolor de talón en adultos.", whatIs: { title: "¿Qué son la Fascitis Plantar y el Espolón?", text: "La fascitis plantar es la inflamación o degeneración de la fascia plantar, una banda de tejido gruesa y elástica que recorre la planta del pie conectando el talón con los dedos y que sostiene el arco. El espolón calcáneo es un depósito de calcio (crecimiento de hueso en forma de pico) que se forma en la parte inferior del hueso del talón, provocado por la tracción y tensión crónica de la fascia plantar inflamada sobre el hueso. Es importante destacar que el espolón rara vez duele por sí mismo; el dolor proviene de la fascia inflamada a su alrededor." }, symptoms: { title: "Síntomas Comunes", intro: "El patrón de dolor es muy característico e inconfundible:", groups: [ { name: "Características del Dolor", items: ["Dolor punzante, agudo o como si se pisara un clavo en la base del talón", "El dolor es mucho peor con los primeros pasos al levantarse de la cama por la mañana (la fascia se ha acortado y enfriado durante la noche y duele al estirarse repentinamente)", "El dolor mejora o disminuye después de caminar unos minutos y calentar el pie", "El dolor reaparece y empeora bruscamente después de estar sentado mucho tiempo o después de realizar ejercicio (no durante el ejercicio)"] } ], warning: "Ignorar la fascitis plantar puede provocar un dolor crónico que altere la forma de caminar, causando posteriormente problemas y dolor en la rodilla, cadera o espalda por compensación." }, types: { title: "Factores de Riesgo", intro: "Estas afecciones se desarrollan por tensión repetitiva y sobrecarga:", items: ["Edad (más común entre los 40 y 60 años)", "Biomecánica del pie (tener pies planos, arcos muy altos o un patrón inusual de caminar que distribuya el peso de forma desigual)", "Obesidad o aumento de peso repentino (aumenta el estrés sobre la fascia plantar)", "Ejercicios de alto impacto (correr, saltar, ballet o danza aeróbica)", "Profesiones que exigen estar de pie o caminar sobre superficies duras durante largas horas (maestros, operarios de fábrica, camareros)", "Uso de calzado inadecuado (zapatos sin soporte para el arco o suelas muy gastadas)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es fundamentalmente clínico, basado en la historia del dolor:", items: ["Examen físico (el médico buscará puntos de máxima sensibilidad al presionar la planta del talón y evaluará la tensión del tendón de Aquiles)", "Radiografía del pie (aunque no diagnostica la fascitis, se usa para ver si existe un espolón calcáneo y descartar fracturas por estrés)", "Ecografía o Resonancia Magnética (RM) (solo se solicitan si el dolor no responde al tratamiento tras varios meses, para medir el grosor de la fascia o buscar desgarros)"], note: "Tener un espolón visible en la radiografía no cambia el tratamiento; muchas personas tienen espolones y no sienten ningún dolor." }, treatment: { title: "Tratamientos", intro: "El manejo requiere paciencia; la mayoría de las personas se recuperan con meses de tratamiento conservador:", subsections: [ { title: "Opciones de manejo y rehabilitación", items: ["Fisioterapia y estiramientos diarios: Estirar consistentemente la fascia plantar y el tendón de Aquiles y los gemelos es el tratamiento más efectivo a largo plazo.", "Soporte ortopédico: Uso de taloneras de silicona, plantillas con soporte para el arco hechas a medida o zapatos con buena amortiguación.", "Férulas nocturnas: Mantienen el pie estirado mientras se duerme para que los primeros pasos de la mañana no duelan.", "Terapias físicas: Aplicación de hielo rodando una botella congelada bajo el pie y masajes de fricción profunda.", "Tratamientos médicos: Analgésicos (AINEs), infiltraciones locales de corticosteroides (usadas con precaución para evitar la ruptura de la fascia) o inyecciones de plasma rico en plaquetas (PRP).", "Terapia de ondas de choque extracorpóreas (ESWT): Pulsos de sonido para estimular la curación en casos crónicos.", "Cirugía: Rara vez necesaria (fasciotomía plantar); solo se considera si el dolor es severo después de 6 a 12 meses de tratamiento riguroso."] } ], note: "Descansar de las actividades de impacto que desencadenaron el dolor es esencial durante la fase aguda." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un podiatra, fisioterapeuta u ortopedista si:", items: ["El dolor en el talón te impide caminar normalmente o apoyar el peso del cuerpo", "Has probado con reposo, hielo y analgésicos durante un mes sin ninguna mejoría", "El talón está rojo, caliente al tacto, hinchado y acompañado de fiebre (podría ser una infección)", "Sientes un dolor repentino y un 'chasquido' en la planta del pie seguido de incapacidad para estirarlo (posible ruptura de la fascia)"] } },
'Síndrome de Edwards' : { intro: "El Síndrome de Edwards, también conocido como Trisomía 18, es un trastorno genético cromosómico severo que interfiere profundamente con el desarrollo fetal normal. Es la segunda trisomía autosómica más común después del Síndrome de Down, pero con consecuencias mucho más graves.", whatIs: { title: "¿Qué es el Síndrome de Edwards?", text: "La mayoría de las personas tienen 46 cromosomas en cada célula, divididos en 23 pares. El Síndrome de Edwards ocurre cuando un bebé nace con una copia adicional (tres en lugar de dos) del cromosoma 18 en sus células. Este material genético extra interrumpe el curso normal de desarrollo del cuerpo, causando malformaciones estructurales y defectos orgánicos graves y múltiples en casi todos los sistemas del cuerpo (corazón, riñones, cerebro)." }, symptoms: { title: "Síntomas y Características", intro: "Los signos físicos y médicos son severos y a menudo evidentes en las ecografías prenatales o al nacer:", groups: [ { name: "Rasgos Físicos Distintivos", items: ["Bajo peso extremo al nacer y tamaño anormalmente pequeño", "Cabeza pequeña de forma anormal (microcefalia) y parte posterior de la cabeza prominente", "Mandíbula y boca inusualmente pequeñas (micrognatia) y orejas de implantación baja", "Puños fuertemente cerrados con los dedos superpuestos de forma característica (el dedo índice sobre el medio y el meñique sobre el anular)", "Pies con la planta redondeada o en forma de 'mecedora' (pies en mecedora)"] }, { name: "Malformaciones Internas y Médicas", items: ["Defectos cardíacos congénitos graves (como defectos del tabique ventricular o conducto arterial persistente)", "Malformaciones renales, gastrointestinales o hernias en la pared abdominal (onfalocele)", "Problemas respiratorios y dificultad severa para alimentarse o tragar", "Discapacidad intelectual y retraso del desarrollo profundos"] } ], warning: "Debido a la extrema severidad de los defectos orgánicos, el Síndrome de Edwards tiene una tasa de supervivencia muy baja. Muchos embarazos terminan en aborto espontáneo o muerte fetal; de los bebés que nacen vivos, la mayoría fallece en los primeros días o semanas de vida, y menos del 10% sobrevive más allá del primer año." }, types: { title: "Tipos de Trisomía 18", intro: "La gravedad puede variar raramente dependiendo del tipo genético:", items: ["Trisomía 18 Completa: Es el tipo más común (95%). Cada célula del cuerpo tiene una copia completa adicional del cromosoma 18. Sus efectos son los más graves.", "Trisomía 18 en Mosaico: Solo algunas células tienen el cromosoma extra, mientras que otras son normales. Los síntomas pueden ser menos severos dependiendo del porcentaje de células afectadas.", "Trisomía 18 Parcial: Solo un trozo del cromosoma 18 se adhiere a otro cromosoma (translocación). Los síntomas son variables."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Es un accidente genético aleatorio en la mayoría de los casos:", items: ["Se debe a un error en la división celular (no disyunción) durante la formación del óvulo o el espermatozoide", "Por lo general, no se hereda y una familia con un bebé afectado rara vez tiene otro", "El riesgo aumenta a medida que la edad materna es más avanzada, aunque puede ocurrirle a mujeres de cualquier edad"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "A menudo se sospecha y se diagnostica durante el embarazo:", items: ["Pruebas de detección prenatal: Análisis de sangre materna (ADN fetal libre o pruebas de cribado) y ecografías detalladas (que muestran retraso en el crecimiento o defectos anatómicos)", "Pruebas de diagnóstico prenatal: Amniocentesis o biopsia de vellosidades coriónicas (para extraer líquido o tejido y analizar los cromosomas del bebé directamente)", "Diagnóstico postnatal: Cariotipo (análisis de cromosomas a partir de una muestra de sangre del bebé) y examen físico tras el nacimiento"], note: "" }, treatment: { title: "Tratamientos", intro: "No existe cura para el Síndrome de Edwards. El enfoque es estrictamente de apoyo:", subsections: [ { title: "Cuidados Paliativos y Médicos", items: ["El tratamiento se centra en brindar comodidad al bebé y apoyo a la familia (cuidados paliativos pediátricos)", "Asistencia respiratoria y oxígeno si el bebé tiene dificultad para respirar", "Alimentación por sonda si hay problemas para tragar", "En algunos casos excepcionales (generalmente en mosaicos menos severos o si los padres y médicos lo deciden), se pueden realizar cirugías para corregir problemas cardíacos o gastrointestinales, pero el riesgo quirúrgico es extremadamente alto", "Soporte psicológico y genético exhaustivo para los padres"] } ], note: "Las decisiones médicas son profundamente personales y complejas, requiriendo un estrecho acompañamiento de neonatólogos y especialistas en cuidados paliativos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "La atención está guiada por el equipo de obstetricia y pediatría:", items: ["Si tus pruebas prenatales (ecografías o sangre) indican un alto riesgo de anomalías cromosómicas, debes ser referida a un especialista en medicina materno-fetal y a un asesor genético", "Si ya tienes un hijo con Trisomía 18, es importante consultar a un asesor genético antes de planificar futuros embarazos para comprender (los muy bajos) riesgos de recurrencia"] } },
'Hiperplasia endometrial benigna' : { intro: "La hiperplasia endometrial benigna es el crecimiento excesivo y anormal del revestimiento interno del útero (el endometrio). Es una afección común que causa sangrados anormales, pero que, a diferencia de las hiperplasias atípicas, tiene un riesgo muy bajo de convertirse en cáncer.", whatIs: { title: "¿Qué es la Hiperplasia Endometrial?", text: "Normalmente, los estrógenos engruesan el endometrio y la progesterona lo prepara para descamarse durante la menstruación. Cuando hay un exceso de estrógenos sin suficiente progesterona, el endometrio crece demasiado. En la forma benigna (sin atipias), las células son normales, solo hay demasiadas." }, symptoms: { title: "Síntomas Comunes", intro: "El síntoma principal es la alteración profunda del patrón de sangrado:", groups: [ { name: "Irregularidades Menstruales", items: ["Menstruaciones extremadamente abundantes y prolongadas", "Sangrado o manchado entre los periodos menstruales", "Ciclos menstruales muy cortos (menos de 21 días)"] }, { name: "Señales de Alerta Crítica", items: ["Cualquier sangrado vaginal después de la menopausia", "Anemia secundaria severa por la pérdida de sangre (fatiga, mareos)"] } ], warning: "El sangrado posmenopáusico nunca es normal. Aunque muchas veces es hiperplasia benigna, debe evaluarse inmediatamente para descartar cáncer de endometrio." }, types: { title: "Factores de Riesgo", intro: "La exposición prolongada a estrógenos no compensados se da por:", items: ["Perimenopausia o menopausia", "Síndrome de ovario poliquístico (SOP) u obesidad severa", "Terapia de reemplazo de estrógenos sin progesterona", "Falta de ovulación crónica"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para medir el grosor y ver las células, el ginecólogo realizará:", items: ["Ecografía transvaginal (para medir el grosor de la línea endometrial)", "Biopsia endometrial (se extrae una pequeña muestra de tejido en el consultorio)", "Histeroscopia (se introduce una cámara en el útero para ver directamente y tomar la muestra)"], note: "La biopsia es el único método definitivo para confirmar que no hay células atípicas (precancerosas)." }, treatment: { title: "Tratamientos", intro: "El objetivo es adelgazar el revestimiento y prevenir el sangrado:", subsections: [ { title: "Opciones de manejo hormonal", items: ["Progestágenos orales (pastillas de progesterona para forzar el desprendimiento del tejido)", "Dispositivo Intrauterino (DIU) liberador de levonorgestrel (Mirena), que adelgaza el endometrio localmente de forma muy eficaz", "Pérdida de peso (reduce los estrógenos producidos por la grasa corporal)", "Histerectomía (extirpación del útero) solo si la paciente ya no desea tener hijos y no responde al tratamiento hormonal"] } ], note: "La hiperplasia sin atipias suele resolverse casi por completo con tratamiento médico hormonal." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Pide cita urgente con ginecología si:", items: ["Experimentas sangrado vaginal si ya has pasado la menopausia", "Tus reglas son tan fuertes que empapas una compresa o tampón cada hora", "Te sientes inusualmente débil, pálida o fatigada (signos de anemia)"] } },
'Trastorno de la personalidad evasiva' : { intro: "El trastorno de la personalidad evasiva (o por evitación) es una afección mental caracterizada por un patrón crónico de extrema inhibición social, sentimientos de profunda inadecuación y una sensibilidad hipersensible al rechazo o la crítica.", whatIs: { title: "¿Qué es este Trastorno?", text: "A diferencia de las personas a las que simplemente les gusta estar solas, quienes padecen este trastorno desean desesperadamente relacionarse y tener amigos, pero el miedo paralizante a ser avergonzados, juzgados o rechazados hace que eviten el contacto social. Se perciben a sí mismos como socialmente ineptos o inferiores a los demás." }, symptoms: { title: "Síntomas y Patrones", intro: "El comportamiento evasivo domina su vida diaria:", groups: [ { name: "Conductuales y Sociales", items: ["Evitación de actividades laborales o escolares que impliquen contacto interpersonal", "Rechazo a involucrarse con personas a menos que estén seguros de que serán aceptados", "Represión en relaciones íntimas por miedo a ser ridiculizados"] }, { name: "Emocionales", items: ["Preocupación excesiva por ser criticado o rechazado en situaciones sociales", "Sensación constante de inferioridad o falta de atractivo personal", "Reticencia a asumir riesgos personales o participar en nuevas actividades por miedo a pasar vergüenza"] } ], warning: "Si no se trata, este trastorno puede conducir a un aislamiento social extremo, depresión profunda y abuso de sustancias como mecanismo de afrontamiento." }, causes: { title: "Causas y Factores de Riesgo", intro: "Es el resultado de una combinación de factores biológicos y ambientales:", items: ["Temperamento naturalmente tímido o inhibido en la infancia", "Experiencias de rechazo, críticas severas o acoso (bullying) por parte de padres o compañeros durante la niñez", "Falta de afecto y validación emocional temprana"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un profesional de la salud mental evalúa:", items: ["Entrevista clínica exhaustiva y evaluación psicológica", "Uso de los criterios del Manual Diagnóstico y Estadístico de los Trastornos Mentales (DSM-5)", "Diferenciación con la fobia social (la evasiva abarca un sentido profundo de insuficiencia personal, no solo ansiedad ante situaciones específicas)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento requiere paciencia y confianza entre el paciente y el terapeuta:", subsections: [ { title: "Opciones terapéuticas", items: ["Psicoterapia a largo plazo (Terapia Cognitivo-Conductual o Terapia Dinámica) para desafiar las creencias de inferioridad", "Entrenamiento en habilidades sociales para mejorar la autoconfianza en la interacción", "Exposición gradual a situaciones sociales temidas", "Medicamentos (antidepresivos o ansiolíticos) para manejar síntomas coexistentes de depresión o ansiedad aguda"] } ], note: "La terapia de grupo puede ser muy efectiva una vez que la persona ha ganado algo de confianza en terapia individual." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca apoyo psicológico si:", items: ["Tu miedo al rechazo te impide avanzar en tu carrera profesional o conseguir empleo", "Te sientes extremadamente solitario y deprimido pero eres incapaz de acercarte a otros", "El aislamiento te genera pensamientos de desesperanza profunda"] } },
'Entropión' : { intro: "El entropión es una afección oftalmológica en la cual el párpado (generalmente el inferior) se pliega o invierte hacia adentro. Esto provoca que las pestañas y la piel rocen constantemente contra la superficie del ojo, causando irritación severa y daño potencial a la córnea.", whatIs: { title: "¿Qué es el Entropión?", text: "Es un problema mecánico del párpado. Al perder su tensión normal, el borde del párpado se voltea hacia adentro. La fricción continua de las pestañas actúa como un cepillo duro contra la delicada córnea, lo que puede provocar dolor agudo, úlceras corneales e incluso pérdida permanente de la visión si no se corrige." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos son directamente causados por el roce de las pestañas:", groups: [ { name: "Oculares", items: ["Sensación constante de tener arena o un cuerpo extraño en el ojo", "Enrojecimiento intenso y dolor ocular crónico", "Lagrimeo excesivo (epífora) como respuesta a la irritación", "Sensibilidad a la luz y al viento", "Secreción mucosa o formación de costras en el párpado"] } ], warning: "Un ojo crónicamente rojo con dolor agudo puede indicar una abrasión o úlcera corneal, lo que constituye una emergencia médica para la vista." }, types: { title: "Causas y Factores de Riesgo", intro: "El entropión puede originarse por varios motivos:", items: ["Entropión involutivo (el más común, causado por la debilidad muscular y relajación de los tendones debido al envejecimiento)", "Entropión cicatricial (por cicatrices químicas, quemaduras o enfermedades como el tracoma que encogen el tejido)", "Entropión espástico (causado por espasmos musculares debidos a una infección o cirugía ocular reciente)", "Entropión congénito (muy raro, presente al nacer)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El oftalmólogo lo diagnostica mediante un examen clínico rutinario:", items: ["Evaluación visual de los párpados y la posición de las pestañas", "Prueba del 'snap-back' (tirar del párpado hacia abajo y ver cuánto tarda en volver a su lugar) para evaluar la laxitud", "Examen con lámpara de hendidura para revisar la córnea en busca de rasguños o úlceras"], note: "" }, treatment: { title: "Tratamientos", intro: "Mientras el objetivo final es la cirugía, existen medidas temporales para proteger el ojo:", subsections: [ { title: "Manejo Temporal y Definitivo", items: ["Lágrimas artificiales y pomadas lubricantes (para reducir la fricción)", "Cinta adhesiva especial para la piel (tirar del párpado hacia abajo temporalmente)", "Inyecciones de toxina botulínica (Botox) para relajar los espasmos musculares (efecto temporal)", "Cirugía de corrección del párpado (cantoplastia o tensado del tendón), que es el tratamiento definitivo, rápido y altamente exitoso"] } ], note: "La cirugía suele hacerse con anestesia local de forma ambulatoria." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu oftalmólogo de inmediato si:", items: ["Tienes la sensación constante de que algo raspa o lastima tu ojo", "Notas que tu párpado inferior está girado hacia adentro", "Experimentas enrojecimiento ocular, dolor fuerte y disminución rápida de la visión"] } },
'Visión corta' : { intro: "La visión corta, conocida médicamente como miopía, es un defecto de refracción muy común en el que se puede ver claramente los objetos cercanos, pero los objetos distantes aparecen borrosos o desenfocados.", whatIs: { title: "¿Qué es la Miopía?", text: "Para ver con claridad, la luz debe enfocarse exactamente sobre la retina (el fondo del ojo). En la miopía, el globo ocular es demasiado largo o la córnea tiene una curvatura excesiva. Como resultado, la luz se enfoca en un punto 'delante' de la retina, lo que hace que los objetos lejanos se vean borrosos. Es una condición que a menudo comienza en la infancia y progresa hasta la edad adulta temprana." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos suelen ser evidentes al realizar actividades a distancia:", groups: [ { name: "Problemas Visuales", items: ["Dificultad para ver objetos lejanos (como la pizarra en la escuela o las señales de tráfico al conducir)", "Necesidad de entrecerrar los ojos para enfocar mejor", "Fatiga visual severa o dolores de cabeza por el esfuerzo ocular constante", "Dificultad para ver bien de noche (miopía nocturna)"] } ], warning: "La miopía alta o magna (mayor a -6 dioptrías) estira físicamente las capas internas del ojo, aumentando significativamente el riesgo de desgarros de retina, cataratas tempranas y glaucoma." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se desarrolla por una combinación de factores genéticos y ambientales:", items: ["Genética (altamente hereditaria si uno o ambos padres son miopes)", "Fatiga visual ambiental (pasar demasiado tiempo realizando tareas de cerca, como leer o usar pantallas)", "Falta de tiempo al aire libre durante la infancia (la luz natural parece ser un factor protector contra el alargamiento del ojo)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El optometrista o el oftalmólogo lo diagnostican fácilmente mediante:", items: ["Examen básico de agudeza visual (leer letras en una tabla optométrica a distancia)", "Prueba de refracción usando un foróptero para medir exactamente cuánto poder de lente se necesita para corregir la visión", "Examen con dilatación de pupilas (fundamental para revisar la salud de la retina en personas muy miopes)"], note: "" }, treatment: { title: "Tratamientos", intro: "La miopía no tiene 'cura' natural, pero se puede corregir ópticamente de varias formas:", subsections: [ { title: "Opciones de corrección", items: ["Gafas (anteojos) graduadas (el método más sencillo y seguro)", "Lentes de contacto (requieren estricta higiene para evitar infecciones de córnea)", "Ortoceratología (Orto-K: uso de lentes de contacto rígidos por la noche que moldean temporalmente la córnea)", "Cirugía refractiva láser (LASIK o PRK) para remodelar permanentemente la córnea (solo en adultos con graduación estable)", "Lentes intraoculares fáquicas (implantación de una lente permanente dentro del ojo para miopías extremadamente altas)"] } ], note: "En niños, el uso de gotas de atropina diluida o lentes especiales puede ayudar a frenar la progresión de la miopía." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca una evaluación oftalmológica urgente si:", items: ["Ves la aparición repentina de múltiples moscas volantes o destellos de luz (flashazos)", "Percibes una sombra o 'cortina' gris cayendo sobre una parte de tu campo visual (signos críticos de desprendimiento de retina)", "Tienes dificultad para conducir, especialmente de noche, por falta de agudeza"] } },
'Trastorno de la personalidad pasivo-agresiva' : { intro: "El trastorno de la personalidad pasivo-agresiva (o comportamiento pasivo-agresivo crónico) es un patrón en el que una persona expresa su enojo, frustración u hostilidad de manera indirecta, en lugar de abordarlo abierta y asertivamente.", whatIs: { title: "¿Qué es la Pasivo-Agresividad?", text: "Es una forma de sabotaje encubierto. Las personas con este rasgo evitan el conflicto directo. Por fuera pueden parecer complacientes, amables o de acuerdo con las demandas de los demás, pero por dentro albergan resentimiento. Expresan su ira de forma 'pasiva' a través de la procrastinación intencional, la terquedad, el sarcasmo o el 'olvido' sistemático de sus obligaciones para castigar a los demás." }, symptoms: { title: "Síntomas y Comportamientos", intro: "El comportamiento es confuso para quienes lo rodean:", groups: [ { name: "Conductas Clásicas", items: ["Resistencia constante a las demandas rutinarias en el trabajo o la familia (hacer las cosas mal a propósito)", "Procrastinación intencional y demoras crónicas para frustrar a otros", "Sarcasmo frecuente, actitud cínica o responder con evasivas y el 'tratamiento del silencio' (ley del hielo)", "Quejarse crónicamente de ser incomprendido, no valorado o ser víctima de los demás", "Criticar y despreciar de forma irracional a la autoridad"] } ], warning: "Este comportamiento suele erosionar profundamente las relaciones de pareja y el ambiente laboral, aislando eventualmente a la persona." }, diagnosis: { title: "¿Cómo se Evalúa?", intro: "Aunque ya no es una categoría diagnóstica independiente en las versiones más recientes del DSM, es un rasgo clínico muy importante:", items: ["Evaluación psicológica a través de entrevistas", "Análisis de los patrones de interacción en el entorno laboral y personal", "Diferenciación de otros trastornos subyacentes como depresión oculta, TDAH o trastorno límite de la personalidad"], note: "La persona afectada rara vez reconoce su ira o su sabotaje; a menudo sienten que los demás son irracionales o exigentes." }, treatment: { title: "Tratamientos", intro: "El tratamiento es un desafío porque la persona no suele aceptar que tiene un problema:", subsections: [ { title: "Opciones terapéuticas", items: ["Terapia Cognitivo-Conductual (TCC) para ayudar a la persona a identificar sus sentimientos ocultos de ira y resentimiento", "Entrenamiento en asertividad (aprender a expresar necesidades y enfados de forma directa, respetuosa y constructiva)", "Terapia de pareja o familiar (para mejorar las dinámicas de comunicación disfuncionales)", "Tratamiento para afecciones coexistentes (como ansiedad social o depresión)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es recomendable buscar apoyo terapéutico si:", items: ["Tu forma de manejar los conflictos está causando problemas crónicos en tu empleo (despidos, advertencias)", "Tus relaciones sentimentales fracasan continuamente debido a problemas de comunicación y resentimiento", "Sientes una frustración constante pero eres incapaz de expresar abiertamente por qué estás molesto"] } },
'Enterocolitis necrosante' : { intro: "La enterocolitis necrosante (ECN) es una enfermedad inflamatoria intestinal catastrófica que afecta casi exclusivamente a los recién nacidos prematuros o enfermos. En esta condición, el tejido del intestino grueso o delgado se inflama profundamente y comienza a morir (necrosarse).", whatIs: { title: "¿Qué es la Enterocolitis Necrosante?", text: "Es una emergencia neonatal grave. Se cree que la combinación de un intestino inmaduro, la falta de flujo sanguíneo adecuado al nacer y la introducción de alimento (especialmente fórmulas) permite que las bacterias normales del intestino invadan la pared intestinal dañada. Si el tejido muere, se crea un agujero (perforación) que derrama el contenido intestinal en la cavidad abdominal (peritonitis), causando una infección abrumadora en la sangre." }, symptoms: { title: "Síntomas Comunes", intro: "Suele aparecer entre los 3 y los 14 días de vida del bebé prematuro:", groups: [ { name: "Signos Digestivos y Abdominales", items: ["Abdomen hinchado (distendido), tenso y doloroso", "Vómitos de color verde o amarillo (contenido bilioso)", "Presencia visible o microscópica de sangre en las heces (pañales sanguinolentos)", "Enrojecimiento o coloración azulada/grisácea de la piel del abdomen"] }, { name: "Signos Sistémicos Severos", items: ["Intolerancia repentina a la alimentación (el alimento se queda en el estómago)", "Pausas largas en la respiración (apneas) y ritmo cardíaco inestable", "Letargo extremo, debilidad y falta de respuesta", "Inestabilidad de la temperatura corporal"] } ], warning: "La ECN progresa de forma fulminante; cualquier vómito bilioso o abdomen tenso en un prematuro requiere evaluación médica urgente de vida o muerte." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los neonatos más vulnerables son aquellos con:", items: ["Prematuridad extrema (es el factor de riesgo número uno)", "Bajo peso al nacer (menor a 1.500 gramos)", "Alimentación con fórmula (la leche materna actúa como un factor protector vital contra la ECN)", "Asfixia o falta de oxígeno durante un parto difícil", "Infecciones sistémicas previas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "En la Unidad de Cuidados Intensivos Neonatales (UCIN), se realizan:", items: ["Radiografías abdominales seriadas (el signo clave es la 'neumatosis intestinal', burbujas de aire atrapadas dentro de las paredes del intestino)", "Análisis de sangre continuos (para ver si los glóbulos blancos disminuyen bruscamente o si la sangre se vuelve ácida, signos de shock)", "Examen físico constante de la tensión del vientre del bebé"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento inmediato suspende la alimentación para dar descanso al intestino:", subsections: [ { title: "Manejo Médico y Quirúrgico", items: ["Suspensión inmediata de todas las tomas por la boca o sonda", "Colocación de una sonda nasogástrica gruesa para vaciar y descomprimir el estómago e intestinos", "Administración de antibióticos intravenosos potentes de inmediato", "Nutrición parenteral total (alimentación por vía intravenosa)", "Cirugía de emergencia (si hay perforación intestinal o si el tejido muerto no responde a los antibióticos, se debe extirpar la parte necrótica del intestino y, a menudo, crear una ostomía temporal)"] } ], note: "Los bebés que sobreviven a una ECN quirúrgica pueden tener problemas digestivos a largo plazo o síndrome del intestino corto." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Si tienes un bebé recién nacido en casa y observas:", items: ["Cualquier vómito de color verde intenso", "Sangre en el pañal", "Su abdomen se ve duro, brillante y se queja si se lo tocan", "El bebé se ve 'apagado', respira raro o no se despierta a comer (Llama al 911 o acude a urgencias pediátricas inmediatamente)"] } },
'Angiodisplasia del colon' : { intro: "La angiodisplasia del colon es una afección vascular caracterizada por la presencia de vasos sanguíneos dilatados, anormales y extremadamente frágiles en el revestimiento interno del colon (intestino grueso). Es una de las causas más comunes de sangrado gastrointestinal en adultos mayores.", whatIs: { title: "¿Qué es la Angiodisplasia del Colon?", text: "A diferencia del cáncer o las úlceras, la angiodisplasia es una malformación de las pequeñas venas y capilares dentro de la pared intestinal. Debido al envejecimiento y a los espasmos normales del intestino a lo largo de los años, estos vasos se hinchan y se vuelven muy frágiles. Aunque son lesiones benignas, pueden romperse fácilmente, provocando desde sangrados crónicos indetectables hasta hemorragias masivas." }, symptoms: { title: "Síntomas Comunes", intro: "El síntoma primordial es el sangrado, que a menudo ocurre sin ningún tipo de dolor:", groups: [ { name: "Señales de Sangrado", items: ["Presencia de sangre roja brillante o de color granate mezclada con las heces", "Heces de color negro oscuro y alquitranadas (melena, si el sangrado es más alto en el tracto)", "Sangre oculta en las heces detectada solo mediante pruebas de laboratorio"] }, { name: "Signos Secundarios (por Anemia)", items: ["Fatiga extrema y debilidad progresiva", "Palidez cutánea notable", "Dificultad para respirar al hacer esfuerzos leves", "Mareos o sensación de desmayo"] } ], warning: "Un sangrado rectal masivo y repentino que llena el inodoro de sangre es una emergencia que requiere atención hospitalaria inmediata." }, types: { title: "Factores Asociados", intro: "Estas lesiones vasculares están frecuentemente asociadas a:", items: ["Envejecimiento (muy común a partir de los 60 años)", "Estenosis aórtica (una afección de las válvulas del corazón; la combinación se conoce como Síndrome de Heyde)", "Enfermedad renal crónica", "Enfermedad de von Willebrand (trastorno de la coagulación)"], note: "Rara vez son causadas por una enfermedad maligna." }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "La localización del sangrado puede ser difícil porque las lesiones son planas:", items: ["Colonoscopia (el examen principal y de oro; permite ver los vasos dilatados con forma de 'estrella' roja o parche en la mucosa)", "Angiografía (inyección de contraste en las arterias si el sangrado es muy activo y no se ve en la colonoscopia)", "Cápsula endoscópica (una pequeña cámara que se traga, utilizada si el sangrado proviene del intestino delgado superior)", "Análisis de sangre (para confirmar anemia por pérdida crónica de sangre)"], note: "Es común que los pacientes requieran varias colonoscopias para encontrar la lesión exacta si esta no estaba sangrando durante el primer estudio." }, treatment: { title: "Tratamientos", intro: "Si las angiodisplasias no sangran y se encuentran por casualidad, no necesitan tratamiento. Si causan anemia o hemorragia:", subsections: [ { title: "Opciones de manejo", items: ["Cauterización por endoscopia/colonoscopia (se utiliza argón plasma, láser o electrocoagulación para quemar y sellar el vaso frágil sin necesidad de cirugía abierta)", "Angiografía con embolización (inyección de sustancias químicas a través de un catéter para taponar la arteria que sangra de forma aguda)", "Suplementos de hierro orales o intravenosos (para reponer los niveles de hierro tras sangrados crónicos)", "Cirugía de resección intestinal (extirpar la parte del colon afectada; se reserva estrictamente para hemorragias masivas que no se pueden detener endoscópicamente)"] } ], note: "" }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o contacta a tu gastroenterólogo si:", items: ["Ves sangre roja brillante en el inodoro o tus heces son negras y pegajosas", "Experimentas un cansancio extremo, mareos intensos y palidez (señales de que has perdido mucha sangre internamente)", "Te han diagnosticado anemia ferropénica y no se ha encontrado la causa"] } },
'Carcinoma hepatocelular' : { intro: "El carcinoma hepatocelular (CHC) es el tipo más común de cáncer primario de hígado. Ocurre con mayor frecuencia en personas con enfermedades hepáticas crónicas, como la cirrosis causada por infecciones de hepatitis B o C, o consumo crónico de alcohol.", whatIs: { title: "¿Qué es el Carcinoma Hepatocelular?", text: "Es un tumor maligno que se origina en los hepatocitos, las células principales que conforman el tejido del hígado. A menudo no presenta síntomas en sus etapas iniciales, lo que hace que su detección temprana mediante chequeos en pacientes de alto riesgo sea fundamental para lograr un tratamiento exitoso." }, symptoms: { title: "Síntomas Comunes", intro: "En etapas tempranas suele ser asintomático, pero al avanzar puede causar:", groups: [ { name: "Síntomas Generales y Digestivos", items: ["Pérdida de peso sin intentarlo y pérdida de apetito", "Sensación de saciedad precoz al comer pequeñas cantidades", "Náuseas y vómitos constantes", "Debilidad general y fatiga extrema"] }, { name: "Síntomas Físicos y Hepáticos", items: ["Dolor sordo y persistente en la parte superior derecha del abdomen", "Hinchazón abdominal debido a la acumulación de líquido (ascitis)", "Ictericia (coloración amarillenta de la piel y el blanco de los ojos)", "Heces blanquecinas o de color tiza"] } ], warning: "El empeoramiento repentino de la salud en una persona que ya tiene cirrosis hepática es una fuerte señal de advertencia de posible CHC." }, types: { title: "Patrones de Crecimiento", intro: "El CHC puede desarrollarse de diferentes maneras en el hígado:", items: ["Patrón de tumor único (una masa grande que crece gradualmente)", "Patrón multinodular (aparición de múltiples nódulos pequeños a lo largo de todo el hígado, típico en casos de cirrosis avanzada)"], note: "Un subtipo poco frecuente es el carcinoma fibrolamelar, que ocurre más a menudo en adultos jóvenes sin antecedentes de cirrosis." }, causes: { title: "Causas y Factores de Riesgo", intro: "El riesgo de desarrollar CHC aumenta significativamente por:", items: ["Infección crónica por el virus de la hepatitis B (VHB) o hepatitis C (VHC)", "Cirrosis hepática (cicatrización irreversible del hígado por diversas causas)", "Consumo excesivo y crónico de alcohol", "Enfermedad del hígado graso no alcohólico (asociada a la obesidad y diabetes)", "Exposición a aflatoxinas (toxinas producidas por un moho que crece en cultivos mal almacenados)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una combinación de pruebas de imagen y laboratorio:", items: ["Análisis de sangre para medir la Alfafetoproteína (AFP), un marcador tumoral hepático", "Ecografía hepática (para detectar masas)", "Tomografía Computarizada (TC) multifásica o Resonancia Magnética (RM) del hígado", "Biopsia hepática (extracción de tejido, aunque a veces se evita si los patrones de imagen son lo suficientemente concluyentes para evitar diseminar células)"], note: "Se recomiendan ecografías de control cada 6 meses en personas con cirrosis para detectar el CHC a tiempo." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende del tamaño, ubicación del tumor y de la salud general del hígado:", subsections: [ { title: "Opciones Curativas y Paliativas", items: ["Resección quirúrgica (extirpación de la parte del hígado con el tumor, si la función hepática restante es buena)", "Trasplante de hígado (la mejor opción en tumores pequeños con cirrosis severa)", "Ablación por radiofrecuencia o microondas (destrucción del tumor con calor para tumores pequeños)", "Quimioembolización transarterial (TACE) para bloquear el flujo sanguíneo al tumor", "Terapias dirigidas (como Sorafenib) e inmunoterapia para cáncer avanzado"] } ], note: "El hígado tiene capacidad de regenerarse, por lo que una resección parcial es posible si no hay cirrosis severa." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un gastroenterólogo o hepatólogo si:", items: ["Tienes antecedentes de cirrosis o hepatitis y notas dolor abdominal nuevo y persistente", "Desarrollas ictericia (ojos o piel amarillos) repentinamente", "Sufres una pérdida de peso inexplicable y tu abdomen se hincha rápidamente"] } },
'Fractura de la base del metatarso' : { intro: "Una fractura de la base del metatarso es una rotura en la parte inferior de los huesos largos del pie (los metatarsianos). La más frecuente y problemática de este tipo es la fractura en la base del quinto metatarsiano, situado en el borde externo del pie.", whatIs: { title: "¿Qué es esta Fractura?", text: "Se trata de una lesión ósea que generalmente ocurre debido a torceduras repentinas del pie, traumatismos directos o, en algunos casos, por el estrés repetitivo durante actividades deportivas. Dependiendo de la zona exacta de la base donde ocurra, puede requerir distintos tiempos de curación y tratamientos." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos de esta fractura suelen ser inmediatos tras la lesión:", groups: [ { name: "Locales y Funcionales", items: ["Dolor intenso y agudo en el borde externo del pie o en el empeine", "Hinchazón inmediata en la zona afectada", "Formación de moretones (hematomas) que se extienden por el pie", "Dificultad o incapacidad total para caminar o soportar peso sobre el pie lesionado", "Sensibilidad extrema al tacto en el área del hueso"] } ], warning: "Caminar sobre un pie con una fractura no tratada puede empeorar la lesión, separar los fragmentos del hueso y requerir cirugía inevitablemente." }, types: { title: "Tipos de Fracturas en el Quinto Metatarsiano", intro: "Existen tres zonas principales de rotura en la base del quinto metatarsiano:", items: ["Fractura por avulsión (Zona 1): Un tendón tira y arranca un pequeño trozo de hueso durante una torcedura. Es la más común y sana bien.", "Fractura de Jones (Zona 2): Ocurre en un área con muy poco suministro de sangre, lo que la hace notoria por ser difícil de sanar y propensa a no unirse (pseudoartrosis).", "Fractura por estrés diafisaria (Zona 3): Causada por trauma repetitivo o sobrecarga continuada."], note: "El tratamiento difiere radicalmente entre una fractura por avulsión simple y una fractura de Jones." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las causas más comunes de estas lesiones son:", items: ["Inversión brusca del pie (doblarse el tobillo hacia adentro al pisar mal, caer o jugar al fútbol o baloncesto)", "Impacto directo (como la caída de un objeto pesado sobre el pie)", "Sobrecarga repetitiva o aumento súbito en la intensidad del ejercicio físico (correr, saltar)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un traumatólogo u ortopedista evaluará el pie mediante:", items: ["Examen físico meticuloso para localizar el punto exacto del dolor", "Radiografías en múltiples proyecciones (frontal, lateral y oblicua) para confirmar la fractura y su desplazamiento", "Resonancia Magnética (RM) o Tomografía (TC) en casos de fracturas por estrés muy finas que no se ven en rayos X ordinarios"], note: "Es común confundir una fractura por avulsión con un simple esguince de tobillo grave si no se hacen radiografías." }, treatment: { title: "Tratamientos", intro: "El enfoque depende de la ubicación exacta de la rotura y su desplazamiento:", subsections: [ { title: "Opciones de manejo", items: ["Inmovilización: Uso de una bota ortopédica rígida para caminar o un yeso corto de pierna", "Descarga de peso: Uso de muletas para evitar apoyar el pie durante 4 a 8 semanas", "Protocolo RICE: Reposo, hielo (Ice), compresión y elevación en los primeros días", "Cirugía: Colocación de un tornillo o placa interna (frecuentemente recomendada para las Fracturas de Jones en atletas o cuando hay un desplazamiento significativo de los fragmentos óseos)"] } ], note: "Las fracturas de Jones suelen requerir cirugía para asegurar que el hueso suelde correctamente debido al bajo flujo sanguíneo en esa área." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención médica de urgencia si:", items: ["El dolor es insoportable e inmediato tras una torcedura", "Existe una deformidad obvia o el pie se ve fuera de su alineación normal", "No puedes dar más de cuatro pasos seguidos debido al dolor agudo"] } },
'Vértigo Central' : { intro: "El vértigo central es una sensación ilusoria de giro, movimiento o inestabilidad severa originada por una disfunción en el sistema nervioso central, específicamente en el tronco encefálico o en el cerebelo. A diferencia del vértigo periférico (que proviene del oído interno), el vértigo central suele ser un síntoma de una afección neurológica grave.", whatIs: { title: "¿Qué es el Vértigo Central?", text: "Es un problema en la forma en que el cerebro procesa las señales de equilibrio, el movimiento de los ojos y la información espacial. Debido a que el daño se ubica en las estructuras cerebrales de control, el vértigo rara vez se presenta solo; suele venir acompañado de otras deficiencias neurológicas significativas." }, symptoms: { title: "Síntomas Comunes", intro: "El vértigo central suele tener características distintivas que lo separan del periférico:", groups: [ { name: "Síntomas de Vértigo", items: ["Sensación de giro prolongada o inestabilidad constante (puede ser menos intensa que la periférica pero no cede rápidamente)", "Pérdida severa del equilibrio (incapacidad para mantenerse de pie o caminar sin ayuda)", "Nistagmo atípico (movimientos oculares rápidos e involuntarios que pueden ser verticales o cambiar de dirección)"] }, { name: "Síntomas Neurológicos Asociados", items: ["Visión doble (diplopía) o dificultad para enfocar la mirada", "Dificultad para hablar con claridad (disartria) o para tragar (disfagia)", "Debilidad, entumecimiento o pérdida de sensibilidad en la cara o extremidades", "Falta de coordinación motora severa (ataxia)"] } ], warning: "La aparición súbita de vértigo severo acompañado de síntomas neurológicos en un adulto mayor debe tratarse como un posible Accidente Cerebrovascular (EVC) hasta que se demuestre lo contrario." }, types: { title: "Diferenciación del Vértigo", intro: "Es crucial diferenciar entre los dos tipos principales:", items: ["Vértigo Periférico: Problema en el oído interno (ej. VPPB, laberintitis). El vértigo es intenso, da náuseas severas y se agrava mucho al mover la cabeza.", "Vértigo Central: Problema en el cerebro. Las náuseas son menos severas, el desequilibrio es extremo y siempre hay otros signos neurológicos presentes."], note: "En el vértigo central, el nistagmo (movimiento ocular) no se suprime cuando la persona fija la mirada en un punto." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las lesiones en el tronco encefálico o cerebelo pueden ser provocadas por:", items: ["Accidente Cerebrovascular (isquémico o hemorrágico) en la fosa posterior", "Ataque Isquémico Transitorio (AIT)", "Esclerosis Múltiple (enfermedad desmielinizante que daña las fibras nerviosas)", "Tumores cerebrales (como los meningiomas o neurinomas grandes)", "Migraña vestibular (una causa central frecuente y más benigna que causa episodios recurrentes)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Una evaluación neurológica urgente es imperativa:", items: ["Prueba clínica HINTS (Head Impulse, Nystagmus, Test of Skew) para diferenciar si la causa es central o periférica al pie de la cama", "Examen neurológico completo de pares craneales, fuerza y coordinación", "Resonancia Magnética (RM) del cerebro (el estándar de oro para ver infartos, tumores o lesiones de esclerosis múltiple)", "Tomografía Computarizada (TC) de cráneo urgente (si hay sospecha de sangrado)"], note: "La prueba HINTS, realizada por un médico experimentado, es más precisa que una TC temprana para descartar un infarto cerebral como causa del vértigo." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende por completo de la enfermedad neurológica subyacente:", subsections: [ { title: "Opciones de manejo", items: ["Intervención de emergencia (trombolisis intravenosa o cirugía) en caso de Accidente Cerebrovascular", "Corticosteroides en dosis altas para brotes de Esclerosis Múltiple", "Medicamentos profilácticos para prevenir ataques en caso de migraña vestibular", "Rehabilitación vestibular y neurológica intensiva para ayudar al cerebro a compensar la pérdida de equilibrio", "Cirugía o radioterapia en caso de tumores cerebelosos"] } ], note: "Los medicamentos supresores del vértigo (como el dimenhidrinato) rara vez son efectivos para el vértigo central crónico y pueden retrasar la recuperación natural del cerebro." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias de inmediato si el vértigo repentino se acompaña de:", items: ["Dificultad para hablar, debilidad en un lado del cuerpo o caída facial", "Visión doble o incapacidad repentina para caminar sin caerse", "El peor dolor de cabeza de tu vida que aparece de forma súbita"] } },
'Absceso hepático bacteriano' : { intro: "Un absceso hepático bacteriano, también conocido como absceso piógeno del hígado, es una cavidad llena de pus que se forma dentro del hígado. Es el resultado de una infección bacteriana grave y requiere tratamiento médico y drenaje urgente.", whatIs: { title: "¿Qué es el Absceso Hepático Bacteriano?", text: "Se trata de una masa infecciosa que destruye progresivamente el tejido hepático sano circundante, encapsulando bacterias, glóbulos blancos muertos y tejido necrosado. A diferencia del absceso amebiano (causado por parásitos), el absceso bacteriano suele estar originado por microorganismos del intestino o vías biliares que alcanzan el hígado." }, symptoms: { title: "Síntomas Comunes", intro: "El cuadro clínico puede desarrollarse de forma aguda o insidiosa a lo largo de semanas:", groups: [ { name: "Síntomas Generales y Sistémicos", items: ["Fiebre alta persistente, a menudo acompañada de escalofríos y sudoración profusa", "Malestar general agudo y debilidad", "Pérdida de apetito y pérdida de peso inexplicable", "Náuseas y vómitos"] }, { name: "Síntomas Locales", items: ["Dolor sordo, punzante o constante en la parte superior derecha del abdomen", "Dolor al respirar profundo que a veces se irradia hacia el hombro derecho", "Ictericia (coloración amarillenta de la piel o los ojos en estadios avanzados)", "Hígado agrandado y muy sensible al tacto (hepatomegalia)"] } ], warning: "Si el absceso se rompe dentro del abdomen, puede causar peritonitis severa y un shock séptico rápidamente mortal." }, types: { title: "Diferencias Diagnósticas", intro: "Es fundamental que el médico diferencie su origen:", items: ["Absceso Piógeno (bacteriano): Múltiples o único, asociado a problemas biliares, ancianos o inmunodeprimidos, tratado con antibióticos y drenaje.", "Absceso Amebiano (parasitario): Suele ser único, afecta a jóvenes o viajeros a zonas endémicas, tratado frecuentemente solo con antiparasitarios como el metronidazol."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Las bacterias (frecuentemente E. coli, Klebsiella o Streptococcus) llegan al hígado por varias vías:", items: ["Infecciones del tracto biliar (como colangitis o cálculos biliares que bloquean el conducto)", "Infecciones abdominales previas (como una apendicitis rota o diverticulitis severa que se propaga por la vena porta)", "Infección en el torrente sanguíneo (bacteriemia o septicemia generalizada)", "Traumatismo contuso en el hígado", "Afecciones como la diabetes mellitus, que reducen las defensas del cuerpo"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Se requiere confirmación por imagen y análisis del líquido:", items: ["Ecografía abdominal (prueba inicial para detectar la cavidad)", "Tomografía Computarizada (TC) de abdomen con contraste (el estándar de oro para ver el tamaño y planificar el drenaje)", "Hemograma y pruebas de función hepática (mostrarán glóbulos blancos muy elevados)", "Hemocultivos (para identificar las bacterias circulantes)", "Aspiración del pus guiada por imagen (para cultivarlo en laboratorio)"], note: "" }, treatment: { title: "Tratamientos", intro: "El tratamiento es agresivo y casi siempre requiere hospitalización:", subsections: [ { title: "Opciones de manejo", items: ["Drenaje percutáneo (un radiólogo intervencionista inserta un catéter a través de la piel y hacia el hígado para vaciar el pus durante varios días)", "Antibióticos intravenosos de amplio espectro (iniciados de inmediato y ajustados según el cultivo, continuados durante semanas)", "Cirugía abierta o laparoscópica (necesaria si el absceso es muy espeso, hay múltiples cavidades complejas o el drenaje percutáneo falla)", "Tratamiento de la causa original (por ejemplo, extraer cálculos biliares)"] } ], note: "La combinación de drenaje físico más antibióticos logra la curación en la gran mayoría de los casos sin necesidad de cirugía abierta." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a la sala de emergencias sin demora si experimentas:", items: ["Fiebre alta con escalofríos intensos e incontrolables", "Dolor severo y constante en la parte superior derecha de tu abdomen", "Desarrollo repentino de ictericia y confusión mental"] } },
'Agua en el pulmón' : { intro: "El 'agua en el pulmón', conocido médicamente en la clínica como edema pulmonar, es una afección potencialmente mortal caracterizada por la acumulación anormal de líquido en los diminutos sacos de aire de los pulmones (alvéolos), lo que dificulta enormemente la oxigenación de la sangre y la respiración.", whatIs: { title: "¿Qué es el Edema Pulmonar?", text: "Normalmente, los pulmones toman oxígeno del aire que respiramos y lo pasan al torrente sanguíneo. Cuando hay un edema pulmonar, los alvéolos se inundan de líquido proveniente de los vasos sanguíneos capilares circundantes. Esta inundación impide el intercambio vital de oxígeno y dióxido de carbono, creando una sensación real de asfixia o ahogo." }, symptoms: { title: "Síntomas Comunes", intro: "El edema puede desarrollarse repentinamente (agudo) o lentamente a lo largo del tiempo (crónico):", groups: [ { name: "Síntomas Agudos (Emergencia)", items: ["Falta de aliento extrema o asfixia, que empeora enormemente al acostarse (ortopnea)", "Sensación de pánico, ansiedad severa e inquietud (sensación inminente de ahogo)", "Tos fuerte que produce esputo espumoso, que a menudo está teñido de sangre (color rosado)", "Sibilancias o un sonido de burbujeo/gorgoteo al respirar", "Latidos cardíacos rápidos e irregulares (taquicardia)", "Piel fría, pegajosa y sudorosa"] }, { name: "Síntomas Crónicos (Desarrollo lento)", items: ["Dificultad para respirar al hacer esfuerzo físico", "Despertarse por la noche sintiendo falta de aire y necesitando sentarse para respirar (disnea paroxística nocturna)", "Hinchazón notoria en las piernas y los tobillos (edema periférico)", "Fatiga extrema inusual"] } ], warning: "El edema pulmonar agudo es una emergencia médica catastrófica. Sin tratamiento rápido, la persona puede asfixiarse debido a la falta de oxígeno en la sangre." }, types: { title: "Clasificación por Origen", intro: "El edema pulmonar se divide en dos categorías principales:", items: ["Edema Pulmonar Cardiogénico: Causado por un problema directo en el corazón. Es el más común. La presión en el lado izquierdo del corazón aumenta, haciendo que la sangre retroceda hacia las venas pulmonares y filtre líquido a los alvéolos.", "Edema Pulmonar No Cardiogénico: El corazón está bien, pero los capilares pulmonares se dañan y filtran líquido. Esto incluye el Síndrome de Dificultad Respiratoria Aguda (SDRA) o el edema pulmonar de las grandes alturas (HAPE)."], note: "El tratamiento inicial difiere significativamente dependiendo de si el origen es cardíaco o pulmonar." }, causes: { title: "Causas y Factores de Riesgo", intro: "Las condiciones que desencadenan este cuadro incluyen:", items: ["Insuficiencia cardíaca congestiva (la causa número uno a nivel mundial)", "Enfermedad de las arterias coronarias o ataques cardíacos severos", "Afecciones de las válvulas cardíacas (como estenosis mitral o aórtica)", "Hipertensión arterial grave y descontrolada", "Infecciones pulmonares masivas (como neumonía severa o sepsis)", "Exposición rápida a altitudes elevadas sin aclimatación", "Inhalación prolongada de humo o toxinas químicas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Debido a la naturaleza de urgencia, el diagnóstico debe ser veloz:", items: ["Oximetría de pulso y Gasometría arterial (para confirmar la falta crítica de oxígeno)", "Radiografía de tórax (la prueba principal, que mostrará áreas blancas o nubladas donde debería haber aire negro)", "Ecocardiograma y Electrocardiograma (ECG) para evaluar el funcionamiento y ritmo del corazón", "Análisis de sangre para medir el péptido natriurético cerebral (BNP), un marcador clave de insuficiencia cardíaca"], note: "El médico también escuchará los pulmones con un estetoscopio buscando sonidos de crepitación o burbujeo." }, treatment: { title: "Tratamientos", intro: "El manejo inicial busca proporcionar oxígeno y eliminar el líquido de inmediato:", subsections: [ { title: "Opciones de manejo agudo", items: ["Administración de oxígeno suplementario de alto flujo, a menudo a través de ventilación no invasiva (mascarilla CPAP/BiPAP) o, en casos extremos, intubación y ventilación mecánica", "Diuréticos intravenosos rápidos (como la Furosemida) para forzar a los riñones a excretar el exceso de líquidos a través de la orina", "Medicamentos vasodilatadores (como la Nitroglicerina) para expandir los vasos sanguíneos y disminuir la presión que el corazón debe vencer para bombear", "Medicamentos inotrópicos para fortalecer la capacidad de bombeo del músculo cardíaco", "Tratamiento de la causa subyacente (por ejemplo, medicación para estabilizar la presión arterial o intervenciones para un infarto)"] } ], note: "Es vital mantener al paciente sentado e incorporado, ya que recostarse empeora severamente la sensación de ahogo al redistribuir el líquido por todos los pulmones." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes llamar al número local de emergencias (911) inmediatamente si presentas o ves a alguien con:", items: ["Dificultad súbita e intensa para respirar y sensación de asfixia", "Tos que expulsa flemas espumosas y rosadas", "Coloración azulada o grisácea en los labios, la cara o debajo de las uñas", "Una caída drástica en la presión arterial acompañada de mareo severo y confusión"] } },
'Shock séptico' : { intro: "El shock séptico es una emergencia médica extrema y representa la complicación más severa de la sepsis. Se caracteriza por una caída catastrófica y sostenida de la presión arterial debida a una infección diseminada en el cuerpo, lo que provoca que los órganos vitales dejen de recibir el flujo de sangre y oxígeno necesarios para sobrevivir.", whatIs: { title: "¿Qué es el Shock Séptico?", text: "La sepsis ocurre cuando el sistema inmunológico reacciona de forma exagerada y descontrolada a una infección (bacteriana, viral o fúngica), atacando los propios órganos y tejidos del cuerpo. Cuando esta sepsis progresa al punto de causar anomalías celulares profundas y el colapso del sistema cardiovascular (la presión arterial no sube a pesar de dar fluidos), se entra en la fase de shock séptico, que conlleva un altísimo riesgo de muerte." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos del shock séptico evolucionan rápidamente y requieren reconocimiento inmediato:", groups: [ { name: "Signos Vitales Críticos", items: ["Presión arterial anormalmente baja (hipotensión grave)", "Frecuencia cardíaca extremadamente rápida y pulso débil (taquicardia)", "Respiración acelerada y superficial (taquipnea)", "Fiebre muy alta con escalofríos, o bien, temperatura corporal anormalmente baja (hipotermia)"] }, { name: "Signos de Fallo de Órganos", items: ["Estado mental alterado: confusión profunda, desorientación, delirio o pérdida de conocimiento (coma)", "Piel pálida, sudorosa, fría y húmeda, a menudo con manchas azuladas o patrón moteado", "Reducción severa o ausencia total de producción de orina (fallo renal agudo)", "Dificultad progresiva para respirar"] } ], warning: "La transición de una sepsis a un shock séptico puede ocurrir en cuestión de horas. La tasa de mortalidad supera el 40%, por lo que la acción hospitalaria debe ser inmediata." }, types: { title: "Etapas de la Enfermedad", intro: "Es fundamental entender la progresión:", items: ["Infección: Una enfermedad localizada (ej. neumonía, infección urinaria).", "Sepsis: La respuesta del cuerpo a la infección causa inflamación sistémica y daño a los órganos.", "Shock Séptico: La inflamación sistémica causa una dilatación masiva de los vasos sanguíneos, desplomando la presión arterial a niveles letales."], note: "Cualquier persona puede padecer sepsis, pero es más común en ancianos, diabéticos y personas inmunodeprimidas." }, causes: { title: "Causas y Factores de Riesgo", intro: "Puede ser desencadenado por infecciones en cualquier parte del cuerpo, destacando:", items: ["Infecciones pulmonares severas (Neumonía)", "Infecciones abdominales (Apendicitis rota, peritonitis, infecciones vesiculares)", "Infecciones del tracto urinario y riñones (Pielonefritis, uso de sondas)", "Infecciones del torrente sanguíneo (Bacteriemia primaria)", "Infecciones en piel y tejidos blandos profundos (Celulitis grave)", "Procedimientos quirúrgicos recientes o presencia de catéteres intravenosos permanentes"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico médico en urgencias se centra en la confirmación rápida de la infección y el colapso de los órganos:", items: ["Análisis de sangre para evaluar la presencia de infección, el daño a órganos (riñón, hígado) y problemas de coagulación", "Medición de los niveles de Lactato en sangre (un lactato elevado indica que las células no están recibiendo suficiente oxígeno)", "Hemocultivos y cultivos de orina, heridas o secreciones (deben tomarse preferiblemente antes de dar la primera dosis de antibiótico)", "Pruebas de imagen (Radiografías, Tomografía Computarizada - TC, o Ecografías) para buscar y confirmar la fuente exacta de la infección"], note: "El diagnóstico se basa en la confirmación de la infección más la necesidad persistente de medicamentos vasopresores para mantener la presión arterial." }, treatment: { title: "Tratamientos", intro: "El manejo del shock séptico se realiza en la Unidad de Cuidados Intensivos (UCI) siguiendo protocolos estrictos de resucitación temprana:", subsections: [ { title: "Rescate y Soporte Vital (Paquete de 1 Hora)", items: ["Administración de fluidos intravenosos cristaloides de forma agresiva y rápida para intentar elevar la presión arterial y mejorar el riego de los órganos", "Administración inmediata de antibióticos de amplio espectro por vía intravenosa, que luego se ajustarán según los resultados de los cultivos", "Uso de medicamentos vasopresores (como la Noradrenalina o Norepinefrina) administrados por bomba de infusión si la presión arterial sigue baja a pesar de los fluidos", "Terapia con corticosteroides (hidrocortisona) en algunos pacientes para ayudar a estabilizar la presión", "Soporte orgánico avanzado: Ventilación mecánica (intubación) para fallos respiratorios y Diálisis en caso de insuficiencia renal aguda", "Control de la fuente infecciosa: Cirugía de emergencia para drenar abscesos, extirpar tejido muerto o retirar catéteres infectados"] } ], note: "La regla de oro es el inicio de antibióticos potentes en la primera hora tras el reconocimiento del cuadro; cada hora de retraso aumenta la mortalidad drásticamente." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama a emergencias (911) inmediatamente si una persona con una infección conocida (o sospechada) desarrolla alguno de los siguientes signos:", items: ["Confusión súbita, desvarío, dificultad severa para despertar o falta de respuesta", "Dificultad intensa para respirar y latidos cardíacos inusualmente rápidos", "Mareos severos o incapacidad para ponerse de pie sin desmayarse", "Piel extremadamente fría, pálida o con parches azulados, y no ha orinado en las últimas 12 horas"] } },
'Colestasis' : { intro: "La colestasis es una afección médica en la cual se reduce o se bloquea por completo el flujo de la bilis desde el hígado, donde se produce, hacia el intestino delgado (duodeno). Esta interrupción causa que sustancias como la bilirrubina y las sales biliares se acumulen en la sangre, generando síntomas notables en todo el cuerpo.", whatIs: { title: "¿Qué es la Colestasis?", text: "La bilis es un fluido digestivo esencial para absorber las grasas y eliminar productos de desecho del hígado (como la bilirrubina vieja). Cuando las 'tuberías' del hígado (conductos biliares) están bloqueadas, o cuando las células hepáticas no pueden secretar la bilis adecuadamente, esta se estanca y pasa al torrente sanguíneo. Esto resulta en la clásica aparición de ictericia (piel amarilla) y una picazón profunda y persistente." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos clínicos son una consecuencia directa de la bilis acumulada en lugares incorrectos:", groups: [ { name: "Síntomas Físicos y Dermatológicos", items: ["Prurito intenso (picazón generalizada severa, que suele ser el síntoma más debilitante y empeora por la noche o con el calor)", "Ictericia (coloración amarillenta progresiva de la piel y de la parte blanca de los ojos o esclerótica)", "Fatiga profunda, cansancio y malestar general", "Náuseas, pérdida de apetito y dificultad para digerir alimentos grasos"] }, { name: "Cambios en Excreciones", items: ["Orina de color muy oscuro, similar al té cargado o al refresco de cola (por la excreción de bilirrubina por el riñón)", "Heces de color muy pálido, color arcilla o masilla blanca (acolia), ya que la bilis no llega al intestino para darles su color marrón habitual"] } ], warning: "La colestasis que se presenta con fiebre alta, dolor abdominal derecho y escalofríos puede indicar colangitis (infección aguda del conducto biliar bloqueado), una emergencia vital." }, types: { title: "Clasificación de la Colestasis", intro: "Se divide principalmente según el lugar físico donde se interrumpe el flujo biliar:", items: ["Colestasis Intrahepática: El problema ocurre dentro de la estructura misma del hígado. Las células hepáticas están dañadas o los pequeños conductos biliares internos están inflamados.", "Colestasis Extrahepática: Ocurre fuera del hígado. Es un bloqueo mecánico o físico en los grandes conductos biliares que transportan la bilis hacia la vesícula y el intestino.", "Colestasis Intrahepática del Embarazo (CIE): Trastorno específico del tercer trimestre del embarazo que causa picazón extrema en la madre y presenta riesgos para el feto, desapareciendo tras el parto."], note: "" }, causes: { title: "Causas y Factores de Riesgo", intro: "Dependiendo del tipo, las causas subyacentes varían:", items: ["Causas Extrahepáticas (bloqueos físicos): Cálculos biliares (piedras que atascan el conducto colédoco), tumores (cáncer de páncreas, de vías biliares o de vesícula), pancreatitis, o estenosis (cicatrices) en los conductos.", "Causas Intrahepáticas (enfermedad celular): Hepatitis viral aguda o alcohólica severa, cirrosis, enfermedades autoinmunes (Cirrosis Biliar Primaria, Colangitis Esclerosante), toxinas, o toxicidad por medicamentos (antibióticos como la amoxicilina-clavulánico, esteroides anabólicos, anticonceptivos orales)."] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Para determinar la causa y la ubicación del bloqueo, se requiere:", items: ["Análisis de sangre para medir la función hepática (elevación marcada de fosfatasa alcalina, GGT y bilirrubina directa)", "Ecografía abdominal (la prueba inicial más importante para ver si los conductos biliares están dilatados por un bloqueo físico externo o buscar cálculos)", "Colangiopancreatografía por Resonancia Magnética (CPRM), una imagen detallada sin radiación de todo el árbol biliar", "Colangiopancreatografía Retrógrada Endoscópica (CPRE), procedimiento con cámara por la boca que permite ver y destapar el conducto", "Biopsia hepática (extraer un pequeño trozo de hígado, reservado para causas intrahepáticas confusas)"], note: "Diferenciar si el problema está 'dentro' o 'fuera' del hígado es el paso crucial en el diagnóstico." }, treatment: { title: "Tratamientos", intro: "El tratamiento se enfoca en resolver la causa subyacente y aliviar la sintomatología estancada:", subsections: [ { title: "Opciones de Manejo", items: ["Procedimientos Intervencionistas: Para la colestasis extrahepática, se realiza una CPRE para extraer el cálculo biliar, colocar un stent (malla) para mantener abierto un conducto bloqueado por un tumor, o cirugía.", "Medicamentos Modificadores: Para causas intrahepáticas crónicas, se usa Ácido Ursodeoxicólico (Urso) para ayudar a mejorar el flujo y la composición de la bilis, protegiendo las células del hígado.", "Alivio del Prurito: Medicamentos como Colestiramina (atrapa las sales biliares en el intestino), Rifampicina o Naltrexona para calmar la picazón intratable.", "Suplementación Vitaminíca: Como la bilis no llega al intestino, el cuerpo no puede absorber las grasas. Se deben recetar suplementos de vitaminas solubles en grasa (Vitamina A, D, E y K) para evitar deficiencias graves, osteoporosis o problemas de coagulación."] } ], note: "Rascarse severamente la piel debido al prurito puede provocar escoriaciones crónicas e infecciones cutáneas secundarias." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Debes buscar atención médica inmediata si:", items: ["Tus ojos o tu piel desarrollan un color amarillo evidente (ictericia)", "Notas que tu orina se vuelve oscura constantemente y tus heces son de un color blanco o masilla", "Sufres de una picazón generalizada y severa que no te deja dormir, especialmente si estás embarazada", "El color amarillo viene acompañado de dolor agudo en el abdomen derecho, fiebre o escalofríos severos"] } },
'Andropausia' : { intro: "La andropausia, a veces llamada menopausia masculina, se refiere a la disminución gradual de los niveles de testosterona en los hombres a medida que envejecen. A diferencia de la menopausia femenina, no afecta a todos los hombres ni detiene por completo la función reproductiva.", whatIs: { title: "¿Qué es la Andropausia?", text: "Es un síndrome clínico asociado al envejecimiento masculino, caracterizado por una deficiencia de testosterona. Este descenso hormonal es lento y progresivo, comenzando generalmente a partir de los 40 años, y puede causar cambios físicos, sexuales y emocionales significativos." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden ser sutiles al principio e incluyen:", groups: [ { name: "Físicos y Emocionales", items: ["Pérdida de energía y fatiga constante", "Depresión, irritabilidad o cambios de humor", "Disminución de la masa muscular y aumento de grasa corporal", "Problemas de concentración y memoria"] }, { name: "Sexuales", items: ["Disminución de la libido o deseo sexual", "Disfunción eréctil o erecciones menos firmes", "Reducción en el volumen de la eyaculación"] } ], warning: "Estos síntomas también pueden ser causados por otras condiciones de salud como la diabetes o la depresión, por lo que es vital una evaluación médica." }, types: { title: "Afecciones Relacionadas", intro: "El término médico correcto suele ser:", items: ["Hipogonadismo de inicio tardío", "Deficiencia de testosterona relacionada con la edad (DTRE)", "Síndrome de deficiencia de testosterona"], note: "No todos los hombres mayores experimentarán niveles de testosterona lo suficientemente bajos como para causar síntomas." }, causes: { title: "Causas y Factores de Riesgo", intro: "El declive hormonal es natural, pero se acelera por:", items: ["Envejecimiento natural", "Obesidad y sedentarismo", "Estrés crónico y falta de sueño", "Consumo excesivo de alcohol", "Enfermedades crónicas (diabetes tipo 2, hipertensión)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere correlacionar síntomas con análisis:", items: ["Análisis de sangre para medir la testosterona total y libre (preferiblemente por la mañana)", "Cuestionarios de síntomas (como el cuestionario ADAM)", "Examen físico y de próstata", "Pruebas para descartar otras enfermedades (tiroides, diabetes)"], note: "Los niveles de testosterona varían a lo largo del día, siendo más altos en la mañana." }, treatment: { title: "Tratamientos", intro: "El enfoque depende de la severidad de los síntomas y los niveles hormonales:", subsections: [ { title: "Opciones de manejo", items: ["Terapia de reemplazo de testosterona (TRT) mediante geles, inyecciones o parches", "Cambios en el estilo de vida (pérdida de peso, dieta saludable, ejercicio de fuerza)", "Tratamiento de la depresión o ansiedad subyacente", "Medicamentos específicos para la disfunción eréctil"] } ], note: "La TRT debe ser monitoreada estrictamente por un médico debido a posibles riesgos cardiovasculares o prostáticos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un urólogo o endocrinólogo si:", items: ["Experimentas una caída notable en tu deseo sexual o disfunción eréctil", "Te sientes constantemente triste, fatigado o sin motivación", "Los cambios físicos y emocionales afectan tus relaciones o trabajo"] } },
'Artritis reactiva' : { intro: "La artritis reactiva es un tipo de dolor e inflamación articular que se desencadena como una respuesta autoinmune a una infección en otra parte del cuerpo, generalmente en los intestinos, los genitales o las vías urinarias.", whatIs: { title: "¿Qué es la Artritis Reactiva?", text: "Anteriormente conocida como síndrome de Reiter, es una espondiloartropatía inflamatoria. Ocurre cuando el sistema inmunológico reacciona de forma exagerada tras una infección bacteriana, atacando las articulaciones sanas, los ojos y la uretra, aunque la infección original ya haya sido controlada." }, symptoms: { title: "Síntomas Comunes", intro: "Se caracteriza por una tríada clásica de síntomas, aunque no todos aparecen siempre:", groups: [ { name: "Articulares y Musculares", items: ["Dolor e inflamación en rodillas, tobillos y pies", "Hinchazón de los dedos de los pies o manos (dedos en salchicha o dactilitis)", "Dolor en la espalda baja o los talones (fascitis plantar)"] }, { name: "Extraarticulares", items: ["Enrojecimiento, dolor e irritación ocular (conjuntivitis o uveítis)", "Ardor o dolor al orinar (uretritis)", "Erupciones cutáneas en las palmas de las manos o plantas de los pies"] } ], warning: "Los síntomas suelen aparecer entre 1 y 4 semanas después de la infección desencadenante." }, types: { title: "Infecciones Desencadenantes", intro: "Se clasifica según el origen de la infección previa:", items: ["Post-venérea (transmitida sexualmente, frecuentemente por Chlamydia trachomatis)", "Post-entérica (infecciones gastrointestinales por Salmonella, Shigella, Campylobacter o Yersinia)"], note: "La bacteria no se encuentra viva dentro de la articulación inflamada." }, causes: { title: "Causas y Factores de Riesgo", intro: "La predisposición a reaccionar a estas infecciones incluye:", items: ["Infección reciente gastrointestinal o de transmisión sexual", "Factor genético: Presencia del gen HLA-B27", "Edad (más común en hombres de 20 a 40 años)", "Prácticas sexuales sin protección o intoxicación alimentaria"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "No existe una prueba única; el diagnóstico es clínico y por exclusión:", items: ["Examen físico de las articulaciones, ojos y piel", "Análisis de sangre para detectar inflamación (VSG, PCR) y el marcador HLA-B27", "Análisis de líquido sinovial (para descartar artritis séptica o gota)", "Pruebas de orina o heces para buscar la bacteria original"], note: "El diagnóstico temprano es vital para descartar una infección articular directa que requeriría cirugía." }, treatment: { title: "Tratamientos", intro: "El objetivo es aliviar los síntomas y tratar cualquier infección subyacente restante:", subsections: [ { title: "Opciones de manejo", items: ["Antibióticos (si la infección bacteriana original aún está activa)", "Antiinflamatorios no esteroideos (AINEs) para el dolor articular", "Inyecciones de corticosteroides en las articulaciones afectadas", "Medicamentos antirreumáticos modificadores de la enfermedad (FAMEs) en casos crónicos", "Fisioterapia para mantener la movilidad"] } ], note: "La mayoría de las personas se recuperan completamente en un plazo de 3 a 12 meses." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un reumatólogo o médico general si:", items: ["Desarrollas dolor e hinchazón articular súbita (especialmente en rodillas o tobillos)", "Tuviste diarrea severa o una infección urinaria en las últimas 4 semanas", "Presentas dolor ocular enrojecido acompañado de dolor articular"] } },
'Infección sinusal' : { intro: "Una infección sinusal, o sinusitis, ocurre cuando las cavidades llenas de aire alrededor de la nariz y los ojos (senos paranasales) se inflaman e infectan. Es una condición muy frecuente que causa congestión, presión facial y malestar general.", whatIs: { title: "¿Qué es una Infección Sinusal?", text: "Normalmente, los senos paranasales están vacíos y recubiertos por una fina capa de moco que drena hacia la nariz. Cuando se bloquean (por un resfriado o alergia), el moco se acumula, creando un ambiente ideal para que virus, bacterias u hongos se multipliquen, causando inflamación e infección." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas pueden ser similares a los de un resfriado prolongado:", groups: [ { name: "Locales y Faciales", items: ["Dolor o presión en la frente, mejillas o alrededor de los ojos (empeora al inclinarse)", "Congestión o bloqueo nasal severo", "Secreción nasal espesa, amarilla o verdosa", "Dolor en los dientes superiores"] }, { name: "Generales", items: ["Pérdida del sentido del olfato y del gusto", "Mal aliento (halitosis)", "Tos (especialmente peor por la noche debido al goteo posnasal)", "Fiebre y fatiga"] } ], warning: "Si la hinchazón y el enrojecimiento se extienden alrededor de los ojos, puede ser una complicación grave que requiere atención de urgencia." }, types: { title: "Tipos de Sinusitis", intro: "Se clasifica según su duración y causa:", items: ["Sinusitis aguda (dura menos de 4 semanas, generalmente viral)", "Sinusitis subaguda (dura de 4 a 12 semanas)", "Sinusitis crónica (dura más de 12 semanas a pesar del tratamiento médico)", "Sinusitis recurrente (varios ataques agudos en un año)"], note: "La gran mayoría de las infecciones sinusales agudas son virales y no requieren antibióticos." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los bloqueos sinusales pueden ser provocados por:", items: ["Infecciones virales respiratorias (el resfriado común)", "Rinitis alérgica (fiebre del heno)", "Pólipos nasales (crecimientos benignos que bloquean los conductos)", "Tabique nasal desviado", "Infecciones dentales (pueden propagarse a los senos maxilares)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico suele ser clínico, realizado por un médico general o un otorrino:", items: ["Examen físico (presionar los senos paranasales para detectar dolor)", "Endoscopia nasal (para ver el interior de la nariz y los senos)", "Pruebas de imagen (Tomografía Computarizada - TC, en casos crónicos o complicados)", "Cultivos nasales (raro, solo si no responde al tratamiento)"], note: "Las radiografías simples ya no se recomiendan rutinariamente para diagnosticar sinusitis." }, treatment: { title: "Tratamientos", intro: "El tratamiento busca aliviar el dolor, reducir la inflamación y drenar el moco:", subsections: [ { title: "Opciones de manejo", items: ["Lavados o irrigaciones nasales con solución salina (muy efectivos)", "Corticosteroides nasales en aerosol (Fluticasona, Mometasona)", "Descongestionantes orales o nasales (máximo de 3 a 5 días para evitar efecto rebote)", "Analgésicos de venta libre (Ibuprofeno, Paracetamol)", "Antibióticos (SOLO prescritos si se sospecha fuertemente de una causa bacteriana severa)", "Cirugía endoscópica de los senos paranasales (en sinusitis crónica resistente)"] } ], note: "Descansar y beber muchos líquidos ayuda a diluir las secreciones mucosas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a tu médico si experimentas:", items: ["Síntomas que duran más de 10 días sin mejoría", "Síntomas que mejoran inicialmente y luego empeoran bruscamente (doble empeoramiento)", "Fiebre alta y persistente", "Cambios en la visión, visión doble o rigidez en el cuello (signos de alarma)"] } },
'Conjuntivitis aguda' : { intro: "La conjuntivitis aguda, comúnmente conocida como 'ojo rosa', es la inflamación de la membrana transparente (conjuntiva) que recubre el interior de los párpados y la parte blanca del globo ocular.", whatIs: { title: "¿Qué es la Conjuntivitis Aguda?", text: "Es una condición oftalmológica muy frecuente. Cuando los pequeños vasos sanguíneos de la conjuntiva se inflaman, se hacen más visibles, lo que hace que el ojo parezca rojizo o rosado. Puede ser causada por infecciones (altamente contagiosas), alergias o irritantes químicos." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían ligeramente según la causa, pero generalmente incluyen:", groups: [ { name: "En el Ojo Afectado", items: ["Enrojecimiento intenso en la parte blanca del ojo o en el párpado interno", "Sensación de picazón, ardor o de tener arena en el ojo", "Lagrimeo excesivo", "Secreción que forma una costra durante la noche, pegando los párpados", "Sensibilidad leve a la luz (fotofobia)"] } ], warning: "La conjuntivitis rara vez afecta la visión a largo plazo, pero si hay dolor intenso o visión borrosa persistente, podría tratarse de una condición ocular más grave." }, types: { title: "Tipos de Conjuntivitis", intro: "Se dividen en tres categorías principales:", items: ["Conjuntivitis viral (la más común, muy contagiosa, secreción acuosa)", "Conjuntivitis bacteriana (muy contagiosa, produce pus espeso amarillento o verdoso)", "Conjuntivitis alérgica (afecta ambos ojos, mucha picazón, acompañada de estornudos)", "Conjuntivitis irritativa (por cloro de piscinas, humo o químicos)"], note: "Las formas virales y bacterianas se propagan fácilmente en escuelas y guarderías." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los agentes responsables incluyen:", items: ["Adenovirus y otros virus del resfriado", "Bacterias como Staphylococcus aureus o Streptococcus pneumoniae", "Alérgenos (polen, polvo, caspa de animales)", "Exposición a productos químicos o lentes de contacto mal limpiados", "Contacto cercano con personas infectadas"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Un médico general o un oftalmólogo puede diagnosticarla fácilmente:", items: ["Examen ocular clínico y evaluación de los síntomas", "Revisión del historial médico reciente (resfriados o alergias)", "Toma de una muestra de la secreción ocular (raro, solo en infecciones severas que no sanan)"], note: "Identificar si es viral o bacteriana es clave para evitar el uso innecesario de antibióticos." }, treatment: { title: "Tratamientos", intro: "El tratamiento depende de la causa subyacente:", subsections: [ { title: "Opciones de manejo", items: ["Conjuntivitis viral: Compresas frías, lágrimas artificiales (sana sola en 1-2 semanas)", "Conjuntivitis bacteriana: Gotas o pomadas antibióticas oftálmicas recetadas", "Conjuntivitis alérgica: Gotas oculares antihistamínicas y evitar el alérgeno", "Higiene estricta: Lavado de manos frecuente, no frotarse los ojos y cambiar fundas de almohada diarias"] } ], note: "Las personas con conjuntivitis infecciosa no deben compartir toallas, maquillaje ni gotas para los ojos." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Es fundamental acudir al médico oftalmólogo si presentas:", items: ["Dolor intenso en el ojo (no solo irritación o picazón)", "Visión borrosa que no mejora al parpadear o limpiar las secreciones", "Sensibilidad extrema a la luz", "Los síntomas no mejoran tras 24-48 horas de usar antibióticos recetados", "Tienes el sistema inmunológico debilitado"] } },
'Pinguécula' : { intro: "Una pinguécula es un crecimiento benigno y común en la conjuntiva, el tejido transparente que recubre la parte blanca del ojo. Suele manifestarse como una pequeña mancha o bulto amarillento cerca de la córnea.", whatIs: { title: "¿Qué es una Pinguécula?", text: "Es una degeneración del colágeno normal de la conjuntiva, formando un depósito de proteínas, grasa y calcio. A diferencia de un pterigión, la pinguécula no crece por encima de la córnea (la parte transparente que cubre el iris y la pupila), por lo que rara vez amenaza la visión." }, symptoms: { title: "Síntomas Comunes", intro: "Muchas pinguéculas no causan síntomas, pero cuando lo hacen, incluyen:", groups: [ { name: "Oculares", items: ["Bulto o mancha amarillenta en la parte blanca del ojo (frecuentemente en el lado más cercano a la nariz)", "Sensación de tener un cuerpo extraño, arena o polvo en el ojo", "Ojo seco, irritación o picazón leve", "Enrojecimiento ocasional e inflamación localizada (pingueculitis)"] } ], warning: "Aunque es inofensiva, una pinguécula puede inflamarse si el ojo se reseca o se expone a irritantes ambientales excesivos." }, types: { title: "Diferencia con el Pterigión", intro: "A menudo se confunde con el pterigión (carnosidad), pero existen diferencias:", items: ["Pinguécula: Es un depósito amarillento que se queda en la parte blanca del ojo (esclerótica).", "Pterigión: Es un crecimiento de tejido carnoso que puede comenzar como una pinguécula, pero avanza y cubre la córnea, afectando la visión."], note: "Ambas condiciones comparten las mismas causas ambientales." }, causes: { title: "Causas y Factores de Riesgo", intro: "Se desarrolla por la exposición prolongada a factores ambientales severos:", items: ["Exposición crónica a los rayos ultravioleta (UV) del sol sin protección ocular", "Exposición al viento, polvo y arena frecuentes", "Sequedad ocular crónica (síndrome del ojo seco)", "Envejecimiento (más común en adultos mayores de 40 años)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es rápido e indoloro:", items: ["Examen oftalmológico de rutina con lámpara de hendidura", "Evaluación visual directa por el optometrista u oftalmólogo"], note: "No se requieren biopsias ni pruebas complejas debido a su apariencia característica." }, treatment: { title: "Tratamientos", intro: "Por lo general, no requiere tratamiento a menos que cause molestias significativas:", subsections: [ { title: "Opciones de manejo", items: ["Uso frecuente de lágrimas artificiales o gotas lubricantes para aliviar la sequedad y la sensación de arena", "Gotas antiinflamatorias no esteroideas o esteroides suaves (prescritas si hay pingueculitis severa)", "Protección preventiva: Uso de gafas de sol con bloqueo 100% UV y sombreros al estar al aire libre", "Cirugía de extirpación (muy rara vez necesaria, solo por motivos estéticos o si interfiere con el uso de lentes de contacto)"] } ], note: "La cirugía no es común porque la pinguécula puede volver a crecer y no suele afectar la visión." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a tu oftalmólogo si:", items: ["El bulto en el ojo cambia repentinamente de tamaño, forma o color", "El ojo se vuelve extremadamente rojo, doloroso y la irritación no cede con lágrimas artificiales", "Notas que el crecimiento comienza a extenderse sobre el área de color (iris) o afecta tu visión"] } },
'Angina de Ludwig' : { intro: "La angina de Ludwig es una infección bacteriana rara, de progresión rápida y potencialmente mortal que afecta el suelo de la boca, debajo de la lengua. Requiere atención médica de urgencia.", whatIs: { title: "¿Qué es la Angina de Ludwig?", text: "Es una celulitis (infección profunda de los tejidos blandos) submandibular grave. La inflamación masiva y la acumulación de líquido en la mandíbula inferior pueden empujar la lengua hacia arriba y hacia atrás, bloqueando completamente las vías respiratorias en cuestión de horas." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas avanzan con extrema rapidez e incluyen:", groups: [ { name: "Cuello y Boca", items: ["Hinchazón severa y endurecimiento del cuello y debajo del mentón (aspecto de 'cuello de toro')", "Dolor intenso y sensibilidad en el cuello, mandíbula y suelo de la boca", "Elevación y endurecimiento de la lengua (la lengua puede salirse de la boca)", "Dificultad o imposibilidad para abrir la boca, masticar o tragar", "Babeo excesivo (incapacidad para tragar la saliva)"] }, { name: "Generales y Respiratorios", items: ["Fiebre alta, escalofríos y debilidad general", "Dificultad para respirar o estridor (ruido ronco al respirar)", "Confusión o agitación por falta de oxígeno"] } ], warning: "Cualquier dificultad respiratoria o babeo incontrolable debido a hinchazón dental o de cuello es una emergencia médica absoluta que amenaza la vida." }, types: { title: "Complicaciones Potenciales", intro: "Si no se trata de inmediato, la infección puede propagarse y causar:", items: ["Asfixia total por obstrucción de las vías aéreas", "Infección en el torrente sanguíneo (sepsis)", "Mediastinitis (propagación de la infección a la cavidad torácica, cerca del corazón)"], note: "No se forman sacos de pus (abscesos) evidentes de inmediato, sino una inflamación generalizada y dura." }, causes: { title: "Causas y Factores de Riesgo", intro: "Casi siempre se origina por un problema dental no tratado:", items: ["Infección en los molares inferiores (la causa más común en un 90% de los casos)", "Extracción dental reciente o traumatismo oral", "Mala higiene bucodental", "Infecciones de las encías o quistes orales rotos", "Sistema inmunológico debilitado (como en pacientes diabéticos)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico rápido en emergencias es vital:", items: ["Examen físico inmediato del cuello y la cavidad oral", "Tomografía Computarizada (TC) de cuello con contraste (para evaluar la extensión de la infección y la vía aérea)", "Cultivos de líquidos o tejidos (para identificar la bacteria, comúnmente estreptococos o estafilococos)", "Radiografía dental (para localizar el diente infectado)"], note: "La prioridad siempre es asegurar la vía respiratoria antes de realizar estudios largos." }, treatment: { title: "Tratamientos", intro: "El tratamiento es hospitalario de emergencia y agresivo:", subsections: [ { title: "Opciones de manejo crítico", items: ["Asegurar las vías respiratorias (intubación o, en casos extremos, traqueostomía de urgencia)", "Administración inmediata de antibióticos intravenosos de amplio espectro", "Cirugía para drenar la infección, aliviar la presión del cuello y extraer el diente infectado (si esa es la causa)", "Monitoreo en la Unidad de Cuidados Intensivos (UCI)"] } ], note: "El tratamiento odontológico oportuno de las caries previene casi todos los casos de Angina de Ludwig." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Llama al 911 o acude a la sala de emergencias más cercana si tienes un dolor dental y presentas:", items: ["Hinchazón rápida y dura debajo de la lengua o la mandíbula inferior", "Cualquier dificultad para respirar, hablar o tragar", "La sensación de que tu lengua está siendo empujada hacia el paladar o la garganta"] } },
'Hiperacusia' : { intro: "La hiperacusia es un trastorno de la audición caracterizado por una sensibilidad extrema, molesta y a veces dolorosa a los sonidos ambientales cotidianos que la mayoría de las personas toleran sin dificultad.", whatIs: { title: "¿Qué es la Hiperacusia?", text: "Es una alteración en la forma en que el cerebro central procesa el sonido. En lugar de amortiguar los ruidos fuertes, el sistema auditivo amplifica desproporcionadamente las señales, haciendo que sonidos normales como correr agua, barajar platos, el motor de un coche o masticar, resulten insoportables, físicamente dolorosos o generen una reacción de pánico." }, symptoms: { title: "Síntomas Comunes", intro: "La hiperacusia afecta severamente la calidad de vida:", groups: [ { name: "Auditivos y Físicos", items: ["Percepción de sonidos normales como extremadamente fuertes o agudos", "Dolor físico agudo o presión en los oídos ante sonidos cotidianos", "Sensación de 'sobresalto' incontrolable ante ruidos repentinos", "Frecuente asociación con tinnitus (zumbidos o pitidos en los oídos)"] }, { name: "Emocionales y Conductuales", items: ["Ansiedad severa, estrés o ataques de pánico anticipatorios al ruido", "Uso constante de tapones para los oídos o auriculares con cancelación de ruido", "Aislamiento social extremo (evitar restaurantes, cines, calles concurridas)"] } ], warning: "El uso excesivo y prolongado de tapones para los oídos en ambientes silenciosos puede empeorar la hiperacusia al aumentar aún más la sensibilidad del cerebro." }, types: { title: "Trastornos Auditivos Relacionados", intro: "A menudo se confunde o coexiste con otras condiciones:", items: ["Misofonía (odio o respuesta emocional extrema a sonidos específicos, como masticar o respirar, no por el volumen)", "Fonofobia (miedo irracional a los sonidos)", "Reclutamiento (crecimiento anormalmente rápido de la percepción de volumen en personas con pérdida auditiva)"], note: "La hiperacusia puede ocurrir en personas con audición perfectamente normal." }, causes: { title: "Causas y Factores de Riesgo", intro: "Puede aparecer de forma gradual o repentina debido a:", items: ["Exposición a un ruido extremadamente fuerte (trauma acústico, como una explosión o concierto)", "Daño en la cabeza, cuello o latigazo cervical", "Cirugías del oído o del nervio facial", "Afecciones médicas (Enfermedad de Lyme, Síndrome de Ménière, Migrañas crónicas)", "Efecto secundario de ciertos medicamentos (ototóxicos)", "Eventos de estrés profundo o trastorno de estrés postraumático (TEPT)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico requiere una evaluación audiológica especializada:", items: ["Examen físico del oído y del canal auditivo", "Audiometría tonal completa (para evaluar si hay pérdida de audición)", "Prueba del Umbral de Disconfort (LDL) para medir el nivel exacto de decibelios en el que el sonido se vuelve molesto", "Evaluación psicológica para medir el impacto en la salud mental"], note: "" }, treatment: { title: "Tratamientos", intro: "No existe una pastilla curativa, pero se puede reeducar al cerebro:", subsections: [ { title: "Opciones de manejo", items: ["Terapia de Reentrenamiento de Tinnitus/Hiperacusia (TRT): Uso de generadores de ruido blanco a bajo volumen para desensibilizar el nervio auditivo lentamente.", "Terapia Cognitivo-Conductual (TCC): Para manejar la ansiedad, el miedo al sonido y desarrollar estrategias de afrontamiento.", "Desensibilización gradual (exponerse poco a poco a sonidos agradables)", "Evitar el silencio absoluto (enriquecimiento sonoro con música suave) y dejar de usar tapones excesivamente."] } ], note: "La recuperación suele ser un proceso largo que requiere meses de reentrenamiento acústico." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca ayuda de un otorrinolaringólogo o audiólogo si:", items: ["Los sonidos cotidianos te causan dolor físico en los oídos", "Estás evitando salir de casa, trabajar o socializar por miedo al ruido", "Sufres de ansiedad severa o zumbidos persistentes en los oídos que afectan tu sueño"] } },
'Síndrome de bradicardia-taquicardia' : { intro: "El síndrome de bradicardia-taquicardia, también conocido como síndrome del seno enfermo, es una alteración del ritmo cardíaco en la que el corazón late alternativamente de forma muy lenta y muy rápida. Es una condición que requiere evaluación cardiológica para prevenir complicaciones graves como desmayos o accidentes cerebrovasculares.", whatIs: { title: "¿Qué es el Síndrome de Bradicardia-Taquicardia?", text: "Es una disfunción del nódulo sinusal, el marcapasos natural del corazón. Esto provoca que el corazón no pueda mantener un ritmo constante, alternando entre latidos anormalmente lentos (bradicardia) y episodios de latidos rápidos o irregulares (taquicardia, a menudo fibrilación auricular)." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas dependen de la fase del ritmo cardíaco, pero suelen incluir:", groups: [ { name: "Durante la bradicardia", items: ["Mareos o aturdimiento", "Desmayos (síncope) o casi desmayos", "Fatiga extrema", "Confusión"] }, { name: "Durante la taquicardia", items: ["Palpitaciones fuertes o rápidas", "Dolor o presión en el pecho", "Dificultad para respirar"] } ], warning: "La combinación de estos ritmos aumenta significativamente el riesgo de formación de coágulos sanguíneos, especialmente si hay fibrilación auricular." }, types: { title: "Variantes y Afecciones Relacionadas", intro: "Esta afección se engloba dentro de los trastornos del nódulo sinusal, que incluyen:", items: ["Bradicardia sinusal severa", "Pausas sinusales o bloqueo sinoauricular", "Síndrome de bradicardia-taquicardia (la forma más compleja)"], note: "El patrón exacto varía de un paciente a otro." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño al sistema eléctrico del corazón suele deberse a:", items: ["Envejecimiento y desgaste natural del tejido cardíaco", "Cicatrices por infartos previos", "Daño por cirugías cardíacas", "Uso de ciertos medicamentos (betabloqueadores, antiarrítmicos)", "Enfermedades inflamatorias del corazón"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El cardiólogo evaluará el ritmo cardíaco mediante:", items: ["Electrocardiograma (ECG)", "Monitor Holter de 24 a 48 horas", "Monitor de eventos implantable (para síntomas infrecuentes)", "Estudio electrofisiológico (en casos complejos)"], note: "A veces los síntomas son esporádicos, por lo que el monitoreo prolongado es clave para atrapar la arritmia." }, treatment: { title: "Tratamientos", intro: "El tratamiento busca estabilizar el ritmo y prevenir complicaciones:", subsections: [ { title: "Opciones comunes", items: ["Implantación de un marcapasos (para corregir la bradicardia)", "Medicamentos antiarrítmicos (usados junto con el marcapasos para frenar la taquicardia)", "Anticoagulantes (para prevenir derrames cerebrales si hay fibrilación)", "Ablación con catéter (para destruir el tejido que causa la taquicardia)"] } ], note: "El marcapasos es el pilar fundamental del tratamiento, ya que permite usar medicamentos para la taquicardia de forma segura." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a urgencias o a tu médico si experimentas:", items: ["Pérdida de conocimiento o desmayos", "Dolor intenso o presión en el pecho", "Dificultad grave para respirar", "Palpitaciones que causan mareo extremo o debilidad"] } },
'Hernia discales' : { intro: "Una hernia discal es una afección frecuente de la columna vertebral que puede causar dolor, entumecimiento o debilidad en brazos o piernas. Ocurre cuando la parte blanda de un disco intervertebral se sale de su lugar, pudiendo presionar los nervios cercanos. En esta sección detallamos sus causas, síntomas y cómo manejarla.", whatIs: { title: "¿Qué es una Hernia Discal?", text: "La columna vertebral está formada por huesos (vértebras) separados por discos que actúan como amortiguadores. Una hernia discal sucede cuando el núcleo pulposo (centro blando) de un disco se desplaza a través de una grieta en su anillo fibroso exterior, comprimiendo o irritando las raíces nerviosas adyacentes." }, symptoms: { title: "Síntomas Comunes", intro: "La mayoría de las hernias ocurren en la zona lumbar (espalda baja) o cervical (cuello), y sus síntomas incluyen:", groups: [ { name: "Hernia Lumbar", items: ["Dolor intenso que se irradia hacia los glúteos, muslos o pantorrillas (ciática)", "Entumecimiento u hormigueo en la pierna o el pie", "Debilidad al levantar el pie o caminar"] }, { name: "Hernia Cervical", items: ["Dolor que se extiende hacia el hombro y el brazo", "Sensación de ardor o descargas eléctricas al mover el cuello", "Debilidad o pérdida de fuerza en la mano"] } ], warning: "Si el dolor viene acompañado de pérdida de control de esfínteres (vejiga o intestinos), es una emergencia médica." }, types: { title: "Tipos y Ubicaciones", intro: "Se clasifican principalmente según su ubicación en la columna:", items: ["Hernia discal lumbar (la más común, afecta la parte baja de la espalda)", "Hernia discal cervical (afecta el cuello y los brazos)", "Hernia discal torácica (muy poco frecuente, en la mitad de la espalda)"], note: "El grado de la hernia varía desde una protuberancia (abombamiento) hasta la extrusión completa del núcleo." }, causes: { title: "Causas y Factores de Riesgo", intro: "Generalmente es el resultado de un desgaste gradual relacionado con la edad (degeneración discal), pero otros factores incluyen:", items: ["Levantar objetos pesados de forma incorrecta (usando la espalda en lugar de las piernas)", "Sobrepeso u obesidad", "Movimientos bruscos o de torsión", "Factores genéticos", "Tabaquismo (acelera la degeneración del disco)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El especialista determinará la causa del dolor mediante:", items: ["Examen físico y neurológico (evaluación de reflejos y fuerza)", "Resonancia Magnética (RM) (la prueba más precisa para ver discos y nervios)", "Tomografía Computarizada (TC)", "Electromiografía (EMG) para localizar el nervio dañado"], note: "Las radiografías simples no muestran hernias discales, pero sirven para descartar fracturas o tumores." }, treatment: { title: "Tratamientos", intro: "El tratamiento varía de conservador a quirúrgico:", subsections: [ { title: "Opciones conservadoras", items: ["Reposo relativo de corta duración y evitación de esfuerzos", "Fisioterapia y ejercicios de fortalecimiento del core", "Analgésicos, antiinflamatorios (AINEs) y relajantes musculares", "Inyecciones epidurales de corticosteroides"] }, { title: "Opciones quirúrgicas", items: ["Microdiscectomía (extracción de la parte del disco que presiona el nervio)", "Laminectomía", "Fusión espinal (en casos de inestabilidad)"] } ], note: "La gran mayoría de las hernias discales mejoran significativamente con tratamiento conservador en 4 a 6 semanas." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca atención médica urgente si:", items: ["El dolor empeora y te impide realizar tus actividades diarias", "Experimentas pérdida repentina de fuerza o sensibilidad en las extremidades", "Presentas incapacidad para retener orina o heces (Síndrome de la cola de caballo)"] } },
'Síndrome de Ehlers-Danlos' : { intro: "El Síndrome de Ehlers-Danlos (SED) es un grupo de trastornos hereditarios que afectan los tejidos conectivos, principalmente la piel, las articulaciones y las paredes de los vasos sanguíneos. Aquí encontrarás información sobre sus características, diagnóstico y manejo para mejorar la calidad de vida.", whatIs: { title: "¿Qué es el Síndrome de Ehlers-Danlos?", text: "Es una condición genética que altera la producción, estructura o procesamiento del colágeno, la proteína que proporciona fuerza y elasticidad al cuerpo. Como resultado, las personas con SED suelen tener articulaciones inusualmente flexibles (hipermovilidad) y piel elástica o muy frágil que se lastima con facilidad." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían ampliamente según el tipo de SED, pero los más frecuentes incluyen:", groups: [ { name: "A nivel articular", items: ["Hipermovilidad (articulaciones que se mueven más allá del rango normal)", "Dislocaciones o subluxaciones frecuentes", "Dolor articular crónico"] }, { name: "A nivel de la piel y tejidos", items: ["Piel extremadamente suave, aterciopelada y elástica", "Fragilidad cutánea (heridas que tardan en sanar o cicatrices anormales)", "Aparición de moretones con gran facilidad"] } ], warning: "El tipo vascular del SED puede causar la ruptura espontánea de vasos sanguíneos importantes u órganos, siendo una complicación crítica." }, types: { title: "Tipos Principales de SED", intro: "Existen 13 subtipos reconocidos, siendo los más destacados:", items: ["Tipo Hipermovilidad (hSED): El más común, enfocado en articulaciones flexibles y dolor crónico.", "Tipo Clásico (cSED): Destaca por la extrema elasticidad y fragilidad de la piel.", "Tipo Vascular (vSED): El más grave, afecta la resistencia de arterias y órganos internos.", "Tipo Cifoescoliótico (kSED): Curvatura severa de la columna vertebral."], note: "El tipo hipermovilidad es el único que actualmente no tiene una prueba genética definitiva identificada." }, causes: { title: "Causas y Factores de Riesgo", intro: "El SED es exclusivamente una condición hereditaria:", items: ["Mutaciones en genes que codifican el colágeno o proteínas relacionadas", "Herencia autosómica dominante (basta una copia del gen mutado)", "Herencia autosómica recesiva (se requieren dos copias del gen mutado)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico clínico y genético es fundamental:", items: ["Evaluación clínica mediante la Escala de Beighton (para medir la hipermovilidad)", "Historial médico familiar detallado", "Biopsia de piel (para analizar la estructura del colágeno en algunos tipos)", "Pruebas genéticas de ADN (para identificar la mutación exacta)"], note: "El diagnóstico temprano es vital para prevenir lesiones articulares y monitorear riesgos cardiovasculares." }, treatment: { title: "Tratamientos y Manejo", intro: "No existe cura para el SED, el tratamiento se centra en la prevención y alivio de síntomas:", subsections: [ { title: "Opciones de manejo", items: ["Fisioterapia especializada (para estabilizar articulaciones fortaleciendo los músculos)", "Manejo del dolor con analgésicos y terapias alternativas", "Uso de aparatos ortopédicos o férulas para prevenir dislocaciones", "Monitoreo cardiovascular regular (especialmente en el tipo vascular)", "Precauciones extremas en cirugías o cuidado de heridas"] } ], note: "Es esencial el apoyo psicológico, ya que vivir con dolor crónico y una condición invisible puede ser agotador." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a evaluación médica si:", items: ["Tienes dislocaciones articulares frecuentes sin causa aparente", "Tu piel se desgarra fácilmente y sana dejando cicatrices muy anchas", "Tienes familiares diagnosticados con SED", "Experimentas dolor repentino y desgarrador en pecho o abdomen (urgencia en tipo vascular)"] } },
'Codependencia emocional y heridas de infancia' : { intro: "La codependencia emocional es un patrón de comportamiento relacional disfuncional donde una persona depende excesivamente de la aprobación o las necesidades de otra, olvidándose de sí misma. Frecuentemente, este patrón tiene sus raíces en heridas emocionales sufridas durante la infancia.", whatIs: { title: "¿Qué es la Codependencia?", text: "Es una condición psicológica y emocional caracterizada por una dependencia extrema hacia una pareja, familiar o amigo. La persona codependiente asume el rol de 'salvador' o 'cuidador', basando su autoestima en cuán útil o necesitado es por el otro, a expensas de su propio bienestar físico y mental." }, symptoms: { title: "Síntomas y Señales", intro: "Las personas con codependencia suelen presentar estos patrones:", groups: [ { name: "Conductuales", items: ["Dificultad para establecer límites saludables", "Necesidad obsesiva de complacer a los demás", "Permanecer en relaciones abusivas o tóxicas por miedo al abandono", "Asumir responsabilidades que corresponden a otros"] }, { name: "Emocionales", items: ["Baja autoestima y falta de identidad propia", "Ansiedad intensa ante la idea de ser rechazado", "Sentimientos de culpa al intentar cuidar de sí mismo", "Miedo profundo a la soledad"] } ], warning: "La codependencia a menudo acompaña a relaciones donde la otra parte sufre de adicciones o trastornos de personalidad." }, types: { title: "Heridas de la Infancia Relacionadas", intro: "La codependencia suele ser una estrategia de supervivencia aprendida debido a:", items: ["Herida de abandono (padres ausentes física o emocionalmente)", "Herida de rechazo (falta de validación o críticas constantes)", "Herida de humillación (bullying familiar o abuso)", "Asumir roles de adulto en la niñez (parentificación, por ejemplo, cuidar de padres alcohólicos)"], note: "El niño aprende que para recibir 'amor', debe ser útil y reprimir sus propias necesidades." }, causes: { title: "Causas y Factores de Riesgo", intro: "Los ambientes que fomentan la codependencia incluyen:", items: ["Hogares disfuncionales con adicciones (alcoholismo, drogas)", "Dinámicas familiares donde no se permitía expresar emociones", "Abuso físico, emocional o negligencia", "Modelos de crianza sobreprotectores o excesivamente autoritarios"] }, diagnosis: { title: "¿Cómo se Identifica?", intro: "No es un diagnóstico clínico oficial en el DSM-5, pero los profesionales de la salud mental lo identifican mediante:", items: ["Evaluación psicológica y entrevistas clínicas", "Análisis del historial de relaciones de la persona", "Exploración de la dinámica familiar de la infancia"], note: "Reconocer el patrón es el primer y más difícil paso hacia la recuperación." }, treatment: { title: "Tratamientos y Sanación", intro: "El objetivo es recuperar la identidad propia y sanar al 'niño interior':", subsections: [ { title: "Opciones terapéuticas", items: ["Psicoterapia individual (Terapia Cognitivo-Conductual, Psicoanálisis, Terapia de Esquemas)", "Grupos de apoyo (como Codependientes Anónimos - CoDA)", "Terapia EMDR (para procesar traumas infantiles)", "Práctica de asertividad y establecimiento de límites", "Fomento del autocuidado y la independencia emocional"] } ], note: "La sanación requiere tiempo y disposición para enfrentar dolores del pasado." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Busca apoyo psicológico si:", items: ["Tus relaciones siempre terminan causándote dolor y agotamiento", "Sientes que no tienes valor si no estás cuidando a alguien más", "Eres incapaz de alejarte de una relación que sabes que es destructiva", "Sufres ansiedad o depresión severa ligada al comportamiento de otra persona"] } },
'HIV/SIDA' : { intro: "El VIH (Virus de la Inmunodeficiencia Humana) es un virus que ataca el sistema inmunitario del cuerpo. Si no se trata, puede progresar a SIDA (Síndrome de Inmunodeficiencia Adquirida). Con la información y el tratamiento adecuado, las personas con VIH pueden llevar una vida larga, sana y sin riesgo de transmitir el virus.", whatIs: { title: "¿Qué es el VIH/SIDA?", text: "El VIH destruye los linfocitos CD4, células cruciales que ayudan al cuerpo a combatir infecciones. El SIDA es la fase más avanzada de esta infección, que ocurre cuando el sistema inmunitario está gravemente dañado, dejando al organismo vulnerable a infecciones oportunistas y ciertos tipos de cáncer." }, symptoms: { title: "Síntomas Comunes", intro: "Los síntomas varían según la etapa de la infección:", groups: [ { name: "Infección Aguda (2 a 4 semanas después del contagio)", items: ["Fiebre, escalofríos y sudores nocturnos", "Dolor de garganta y ganglios inflamados", "Fatiga y dolores musculares", "Erupción cutánea"] }, { name: "Etapa de SIDA (si no hay tratamiento)", items: ["Pérdida de peso rápida e inexplicable", "Infecciones graves recurrentes (neumonía, candidiasis oral severa)", "Diarrea crónica", "Manchas inusuales en la piel o dentro de la boca"] } ], warning: "Muchas personas no presentan síntomas durante años (fase crónica), por lo que la única forma de saber si se tiene el virus es haciéndose una prueba." }, types: { title: "Prevención y Conceptos Clave", intro: "Es vital entender cómo interactúa el virus con el tratamiento:", items: ["Indetectable = Intransmisible (I=I): Si la carga viral es indetectable gracias al tratamiento, no se puede transmitir el virus sexualmente.", "PrEP (Profilaxis preexposición): Pastilla diaria para personas en riesgo de contraer el virus.", "PEP (Profilaxis posexposición): Tratamiento de emergencia en las primeras 72 horas tras una posible exposición."], note: "El VIH NO se transmite por abrazos, lágrimas, saliva, sudor, picaduras de mosquitos o compartir cubiertos." }, causes: { title: "Causas y Formas de Transmisión", intro: "El VIH se transmite a través del contacto directo con ciertos fluidos corporales (sangre, semen, fluidos vaginales/rectales, leche materna):", items: ["Relaciones sexuales sin preservativo", "Compartir agujas o jeringas", "De madre a hijo durante el embarazo, el parto o la lactancia (prevenible con tratamiento)", "Transfusiones de sangre o pinchazos accidentales (muy raro hoy en día)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "El diagnóstico es rápido y confidencial mediante pruebas de laboratorio:", items: ["Pruebas rápidas de anticuerpos (saliva o pinchazo en el dedo)", "Pruebas de antígenos y anticuerpos (extracción de sangre, más rápidas en detectar)", "Pruebas de ácido nucleico (carga viral)"], note: "Existe un 'período ventana' donde el virus puede no ser detectado recién adquirido, por lo que a veces se requiere una segunda prueba." }, treatment: { title: "Tratamientos", intro: "No hay cura, pero la infección es totalmente manejable:", subsections: [ { title: "Opciones de tratamiento", items: ["Terapia Antirretroviral (TAR): Combinación de medicamentos diarios que reducen la cantidad de virus en el cuerpo.", "Medicamentos inyectables de acción prolongada", "Tratamiento y prevención de infecciones oportunistas"] } ], note: "Tomar la medicación exactamente como se receta es crucial para evitar la resistencia del virus y mantener la carga viral indetectable." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Acude a un centro de salud si:", items: ["Crees que has estado expuesto al VIH en las últimas 72 horas (para pedir la PEP)", "Tienes una vida sexual activa o compartes agujas (para realizar pruebas de rutina)", "Das positivo en una prueba casera de VIH (para confirmación e inicio de tratamiento)"] } },
'Enfermedad pulmonar intersticial difusa' : { intro: "La Enfermedad Pulmonar Intersticial Difusa (EPID) agrupa a más de 200 trastornos pulmonares crónicos que causan inflamación y cicatrización progresiva del tejido pulmonar, lo que dificulta la respiración y la oxigenación de la sangre.", whatIs: { title: "¿Qué es la EPID?", text: "En esta afección, el intersticio (el tejido que sostiene los sacos de aire o alvéolos en los pulmones) se inflama y luego se cicatriza, volviéndose grueso y rígido (fibrosis pulmonar). Esta rigidez impide que los pulmones se expandan adecuadamente y dificulta el paso del oxígeno hacia el torrente sanguíneo." }, symptoms: { title: "Síntomas Comunes", intro: "Los signos suelen ser graduales e insidiosos:", groups: [ { name: "Síntomas respiratorios y generales", items: ["Dificultad para respirar (disnea) progresiva, inicialmente al hacer esfuerzo y luego en reposo", "Tos seca y persistente", "Fatiga extrema y debilidad", "Ensanchamiento y redondeo de las puntas de los dedos (acropaquia)"] } ], warning: "Una vez que el tejido pulmonar se cicatriza (fibrosis), el daño es irreversible. El diagnóstico temprano es crucial para frenar la progresión." }, types: { title: "Tipos Frecuentes", intro: "La EPID engloba muchas enfermedades, entre las más conocidas están:", items: ["Fibrosis Pulmonar Idiopática (FPI) (sin causa conocida, suele ser agresiva)", "Neumonitis por hipersensibilidad (causada por inhalación crónica de polvo orgánico, como moho o heces de aves)", "Sarcoidosis", "Enfermedades pulmonares asociadas a enfermedades autoinmunes (Artritis reumatoide, Esclerodermia)"], note: "Identificar el tipo exacto requiere pruebas especializadas." }, causes: { title: "Causas y Factores de Riesgo", intro: "El daño pulmonar puede ser desencadenado por múltiples factores:", items: ["Exposición ocupacional o ambiental (polvo de sílice, asbesto, carbón)", "Ciertos medicamentos (quimioterápicos, algunos antibióticos o medicamentos para el corazón)", "Radioterapia previa en el tórax", "Enfermedades autoinmunes", "Factores genéticos", "Tabaquismo (empeora el pronóstico)"] }, diagnosis: { title: "¿Cómo se Diagnostica?", intro: "Es un proceso complejo realizado por un neumólogo:", items: ["Tomografía Computarizada (TC) de tórax de alta resolución (prueba clave para ver el patrón de cicatrización)", "Pruebas de función pulmonar (espirometría para medir la capacidad pulmonar)", "Gasometría arterial y oximetría de pulso", "Broncoscopia o biopsia pulmonar (para análisis celular)"], note: "Auscultar el pecho a menudo revela un sonido característico similar al de separar un cierre de velcro (crepitantes)." }, treatment: { title: "Tratamientos", intro: "El objetivo es ralentizar el avance de la enfermedad y mejorar la calidad de vida:", subsections: [ { title: "Opciones terapéuticas", items: ["Medicamentos antifibróticos (Pirfenidona, Nintedanib) para la FPI", "Corticosteroides e inmunosupresores (si la causa es autoinmune o inflamatoria)", "Oxigenoterapia domiciliaria", "Rehabilitación pulmonar", "Trasplante de pulmón (en casos severos y estadios finales)"] } ], note: "Las vacunas contra la gripe y el neumococo son fundamentales para prevenir infecciones que podrían ser fatales." }, whenToSeekHelp: { title: "¿Cuándo Buscar Ayuda Profesional?", intro: "Consulta a un médico si experimentas:", items: ["Falta de aire progresiva o que no tiene explicación", "Tos seca que dura más de un mes", "Fatiga inusual al realizar tareas simples que antes hacías sin problema"] } }
};